/// Per-channel cross-leg media bridge (native ↔ opt-in WebRTC roster).
const Bridge = media_bridge_mod.ChannelBridge(native_media_mod.max_call_participants);

/// Blocking acquire on the tryLock-only `std.atomic.Mutex` guarding the media
/// bridge registry (rare register/leave vs. the native pump thread).
fn lockSpin(m: *std.atomic.Mutex) void {
    while (!m.tryLock()) std.Thread.yield() catch {};
}

/// Context for the native→WebRTC cross-leg send callback.
const BridgeSendCtx = struct {
    server: *LinuxServer,
    channel: []const u8,
};

/// Resolve a WebRTC target's live address from the media plane and send the
/// rewrapped RTP packet there.
fn bridgeSendToWebrtc(ctx: *anyopaque, target: *const media_bridge_mod.Member, bytes: []const u8) void {
    const s: *BridgeSendCtx = @ptrCast(@alignCast(ctx));
    if (s.server.media_plane.remoteFor(s.channel, target.id())) |addr|
        s.server.media_plane.sendTo(addr, bytes);
}

/// Resolve a WebRTC target's live address and send canonical RTCP feedback
/// there. DTLS-SRTP egress fails closed inside MediaPlane until the pump owns a
/// queued protected-RTCP send path.
fn bridgeSendFeedbackToWebrtc(ctx: *anyopaque, target: *const media_bridge_mod.Member, bytes: []const u8) void {
    const s: *BridgeSendCtx = @ptrCast(@alignCast(ctx));
    if (s.server.media_plane.remoteFor(s.channel, target.id())) |addr|
        s.server.media_plane.sendRtcpTo(addr, bytes);
}

/// Cross-leg sink invoked by the native pump: rewrap the native frame to RTP and
/// fan it out to the channel's WebRTC members (live addresses resolved per peer).
fn bridgeOnNativeFrame(ctx: *anyopaque, channel: []const u8, datagram: []const u8) void {
    const self: *LinuxServer = @ptrCast(@alignCast(ctx));
    lockSpin(&self.media_bridges_mu);
    defer self.media_bridges_mu.unlock();
    const br = self.media_bridges.getPtr(channel) orelse return;
    var sctx = BridgeSendCtx{ .server = self, .channel = channel };
    br.fanoutNativeToWebrtc(datagram, &sctx, bridgeSendToWebrtc);
}

/// Cross-leg sink invoked by the native pump for authenticated native feedback:
/// translate keyframe/NACK control intent into RTCP for the WebRTC publisher.
fn bridgeOnNativeFeedback(ctx: *anyopaque, channel: []const u8, sender_stream_id: u32, feedback: []const u8) bool {
    const self: *LinuxServer = @ptrCast(@alignCast(ctx));
    lockSpin(&self.media_bridges_mu);
    defer self.media_bridges_mu.unlock();
    const br = self.media_bridges.getPtr(channel) orelse return false;
    var sctx = BridgeSendCtx{ .server = self, .channel = channel };
    return br.fanoutNativeFeedbackToWebrtc(sender_stream_id, feedback, &sctx, bridgeSendFeedbackToWebrtc);
}

/// Resolve a native target's learned address from the native transport and send
/// the rewrapped cadence datagram there.
fn bridgeSendToNative(ctx: *anyopaque, target: *const media_bridge_mod.Member, bytes: []const u8) void {
    const s: *BridgeSendCtx = @ptrCast(@alignCast(ctx));
    if (s.server.native_media.remoteFor(s.channel, target.id())) |addr|
        s.server.native_media.sendTo(s.channel, addr, bytes);
}

/// Resolve a native target's learned address and send control-plane feedback
/// there. Feedback is not a cadence media frame, so it bypasses media-frame MAC
/// tagging.
fn bridgeSendFeedbackToNative(ctx: *anyopaque, target: *const media_bridge_mod.Member, bytes: []const u8) void {
    const s: *BridgeSendCtx = @ptrCast(@alignCast(ctx));
    if (s.server.native_media.remoteFor(s.channel, target.id())) |addr|
        s.server.native_media.sendFeedbackTo(addr, bytes);
}

/// Cross-leg sink invoked by the WebRTC relay: rewrap the RTP frame to cadence
/// and fan it out to the channel's native members (live addresses per peer).
fn bridgeOnRtpFrame(ctx: *anyopaque, channel: []const u8, rtp: []const u8, keyframe_hint: bool) void {
    const self: *LinuxServer = @ptrCast(@alignCast(ctx));
    lockSpin(&self.media_bridges_mu);
    defer self.media_bridges_mu.unlock();
    const br = self.media_bridges.getPtr(channel) orelse return;
    var sctx = BridgeSendCtx{ .server = self, .channel = channel };
    const started_at_ms = self.nowMs();
    br.fanoutWebrtcToNative(rtp, keyframe_hint, &sctx, bridgeSendToNative);
    self.recordElapsedLatency(.media_relay, started_at_ms);
}

/// Cross-leg sink invoked by the WebRTC relay for RTCP feedback: translate
/// PLI/FIR/NACK into native feedback and deliver it only to the native publisher
/// named by the media SSRC.
fn bridgeOnRtcpFeedback(ctx: *anyopaque, channel: []const u8, rtcp: []const u8) bool {
    const self: *LinuxServer = @ptrCast(@alignCast(ctx));
    lockSpin(&self.media_bridges_mu);
    defer self.media_bridges_mu.unlock();
    const br = self.media_bridges.getPtr(channel) orelse return false;
    var sctx = BridgeSendCtx{ .server = self, .channel = channel };
    return br.fanoutRtcpFeedbackToNative(rtcp, &sctx, bridgeSendFeedbackToNative);
}

/// Builtin-test-only adapter for the actual Server native-media callback. A
/// supplied real transport is temporarily moved into a fully constructed NEW
/// Server, then restored before either owner tears down its resources.
pub const MediaBridgeFixture = if (builtin.is_test) struct {
    pub fn nativeToWebrtc(
        allocator: std.mem.Allocator,
        io: std.Io,
        plane: *media_plane_mod.MediaPlane,
        channel: []const u8,
        source_id: []const u8,
        source: media_bridge_mod.Member,
        recipient_id: []const u8,
        recipient: media_bridge_mod.Member,
        datagram: []const u8,
    ) anyerror!void {
        // A moved worker context would break its stable-address borrow. This
        // fixture only owns a synchronous stopped transport with real crypto.
        if (plane.thread != null or plane.runtime.slot != null or
            plane.runtime.entered.load(.acquire) or plane.runtime.exited.load(.acquire))
            return error.ActiveMediaFixture;
        const server = try allocator.create(LinuxServer);
        defer allocator.destroy(server);
        try server.initInPlace(allocator, .{ .host = "127.0.0.1", .port = 0, .max_clients = 2, .crypto_io = io });
        defer server.deinit();
        std.mem.swap(media_plane_mod.MediaPlane, &server.media_plane, plane);
        defer std.mem.swap(media_plane_mod.MediaPlane, &server.media_plane, plane);
        var bridge = Bridge.init();
        try bridge.register(source_id, source);
        try bridge.register(recipient_id, recipient);
        const owned_channel = try allocator.dupe(u8, channel);
        errdefer allocator.free(owned_channel);
        try server.media_bridges.put(allocator, owned_channel, bridge);
        // Exactly the callback installed on the real native transport; no test
        // routing verdict, direct crypto mutation or synthetic send is supplied.
        bridgeOnNativeFrame(server, channel, datagram);
    }
} else struct {};

