    inherited_mesh_redials: std.ArrayListUnmanaged(posix.sockaddr.in6) = .empty,
    inherited_mesh_redial_cursor: usize = 0,
    /// Decoded `[mesh].trust_roots` Ed25519 node signing keys. Empty preserves
