    ocg2_runtime: ?*ocg2_runtime_mod.Runtime = null,
    /// Exact monotonic origin paired with the observer's elapsed=0 prime.
    ocg2_runtime_monotonic_origin_ms: ?u64 = null,
    ocg2_projection: ?*ocg2_projection_mod.Runtime = null,
    ocg2_projection_origin_ms: ?u64 = null,
    ocg2_audit: ?*audit_trail_mod.AuditTrail = null,
    /// A terminal observer or projection failure is reported once; later timer
    /// turns remain silent while that runtime stays terminal.
    ocg2_runtime_terminal_logged: bool = false,
    /// Web Push delivery worker (borrowed; owned by main; null = disabled).
    webpush_worker: ?*webpush_mod.Worker = null,
    ocsp_worker: ?*managed_ocsp.Service = null,
    /// Accepted downstream outputs remain here until source fanout and every
    /// configured HTTP destination returns a real 2xx response.
    webpush_overflow_deliveries: [webpush_overflow_delivery_slots]?WebpushOverflowDelivery = @splat(null),
    /// Monotonic millis captured at init, for STATS u uptime.
    start_ms: i64 = 0,
    /// Wall-clock Unix seconds captured at init, for the registration 003
    /// creation line. Kept separate from `start_ms`, which is monotonic.
    boot_unix: i64 = 0,

    /// The reactor this call is running on. Single embedded reactor today, so it
    /// is just `&self.reactor`; when the daemon shards into N reactor threads this
    /// resolves to the thread-local current reactor (set at each thread's loop
    /// entry). Centralizing the lookup keeps every handler's `self.rx().ring` /
    /// `self.rx().clients` access shard-correct with no signature changes.
    pub inline fn rx(self: *LinuxServer) *Reactor {
        return current_reactor orelse &self.reactors[0];
    }

    /// True only on reactor 0's thread. Unlike `rx()`, an unset
    /// `current_reactor` is false — a background worker or test helper must
    /// not steal shared `last_*_ms` maintenance guards. I/O handlers keep
    /// the `rx()` fallback. docs/audit/timer-guard-0.7.md P0-TG-4.
    fn isMaintenanceReactor(self: *const LinuxServer) bool {
        return current_reactor == &self.reactors[0];
    }

    fn latencyReactorIndex() usize {
        return if (current_reactor) |reactor| reactor.shard_id else 0;
    }

    fn recordElapsedLatency(
        self: *LinuxServer,
        series: server_stats.LatencyStats.Series,
        started_at_ms: i64,
    ) void {
        const elapsed_ms: u64 = @intCast(@max(@as(i64, 0), self.nowMs() - started_at_ms));
        self.latency_stats.record(series, latencyReactorIndex(), elapsed_ms *| 1000);
    }

    /// Effective worker-reactor count, clamped to `[1, max_shards]`. Multi-reactor
    /// is correct under the multithreading "Phase B" coarse lock: `onCompletion`
    /// takes `world.lockWrite` once around the WHOLE completion, so every reactor
    /// serializes all shared-state reads/mutations + the delivery they drive (the
    /// per-reactor clients table + send buffers are reactor-local and need no
    /// lock). Reactors still parallelize the io_uring I/O; command processing
    /// serializes. `[limits].num_shards` defaults to 1 (single reactor); operators
    /// opt into more. Finer-grained (Phase C / RCU lock-free reads) is future work
    /// (docs/planning/24-multithreading.md) — it improves throughput, not safety.
    fn clampShards(config: Config) u12 {
        const requested: usize = if (config.num_shards == 0) 1 else config.num_shards;
        const capped = @min(requested, shard_mod.max_shards);
        return @intCast(@max(@as(usize, 1), capped));
    }

    /// Cert presence is the "TLS configured" signal (main.zig only supplies a
    /// chain when `[tls]` is enabled): a leaf chain plus any supported signing
    /// key. Shared by the implicit-TLS and wss listener gates.
    fn certReady(config: Config) bool {
        return config.tls_cert_chain.len != 0 and
            (config.tls_signing_key != null or config.tls_rsa_signing_key != null or config.tls_ecdsa_signing_key != null);
    }

    /// Validate a reloaded leaf chain before it goes live on REHASH. Mirrors the
    /// boot-time `validateTlsChain` in main.zig: the daemon's OWN chain is checked
    /// leaf-only (a CA-issued server chain ships leaf + intermediates, never a
    /// self-signed root, and an intermediate may use a key type the server does
    /// not sign with). A rejected leaf leaves the live certs untouched (the error
    /// propagates to the REHASH caller).
    fn validateReloadedChain(chain: []const []const u8) !void {
        if (chain.len == 0) return error.EmptyCertificateChain;
        const now_unix: i64 = @divTrunc(platform.realtimeMillis(), 1000);
        try x509_verify.validateServerChainAt(chain, now_unix);
    }

    /// Build one shard's `Reactor`: its own ring, connection table (reserved to
    /// `max_clients`), wake eventfd, and listeners stamped with `shard_id`. When
    /// `reuse_port` is set the CLIENT listeners use `SO_REUSEPORT` so N reactors
    /// can load-balance accepts; S2S is reactor-0-only because mesh dial/collision
    /// state is owned by reactor 0. The single-reactor path keeps the plain
    /// `createListener` sockets (and the inherited-fd upgrade handoff) for
    /// byte-identical behavior. On any partial failure every fd/resource already
    /// created for this shard is released.
    fn initReactor(allocator: std.mem.Allocator, config: Config, shard_id: u12, reuse_port: bool) !Reactor {
        // The plaintext listener is ALWAYS SO_REUSEPORT — even single-reactor — so
        // a later 1-shard -> N-shard UPGRADE can bind sibling per-shard listeners
        // on the same port (REUSEPORT requires every socket on the port to set
        // it; a single-reactor predecessor that bound a plain socket used to make
        // the multishard successor fail AddressInUse and fall back to boot-only).
        // Every shard adopts its own inherited fd across UPGRADE for a seamless
        // handoff (no bind gap, no accept-queue drop): a multi-shard predecessor
        // carries the full shard-ordered listener list, a single-shard (or
        // older) predecessor carries just shard 0's fd. Shards past the carried
        // list — and fresh boots — create their own.
        const inherited: ?linux.fd_t = blk: {
            if (nativeManifestListener(config, shard_id, .plain, false)) |fd| break :blk fd;
            if (shard_id < config.inherited_listener_fds.len) break :blk config.inherited_listener_fds[shard_id];
            if (shard_id == 0 and config.inherited_listener_fds.len == 0) break :blk config.inherited_listener_fd;
            break :blk null;
        };
        const windows_shared_acceptor_only = builtin.os.tag == .windows and shard_id != 0;
        const listener_fd: linux.fd_t = if (windows_shared_acceptor_only)
            -1
        else if (inherited) |fd| blk: {
            srvLog("onyx-server: adopting inherited listener fd {d} (shard {d})\n", .{ fd, shard_id });
            // Restore exec hygiene: the fd survived ONE execve on purpose;
            // re-arm CLOEXEC so it never leaks into any other child. The next
            // UPGRADE clears it again for exactly the listeners it carries.
            if (comptime builtin.os.tag == .linux) {
                _ = linux.fcntl(fd, posix.F.SETFD, posix.FD_CLOEXEC);
                try kernel_linux.applyListenerOptions(fd);
            } else if (comptime builtin.os.tag == .windows) {
                _ = try adoptNativeListener(config, fd);
            } else {
                try os_runtime.setCloexec(fd, true);
                try os_runtime.setNonblocking(fd);
            }
            break :blk fd;
        } else try reuseport.createReusePortListener(primaryListenerHost(config.host), config.port, config.backlog);
        errdefer closeFd(listener_fd);
        const inherited_companion: ?linux.fd_t = if (nativeManifestListener(config, shard_id, .plain, true)) |fd|
            fd
        else if (shard_id < config.inherited_listener_companion_fds.len)
            config.inherited_listener_companion_fds[shard_id]
        else
            null;
        const listener_companion_fd = try stageListenerCompanion(config.host, config.port, listener_fd, config.backlog, true, inherited, inherited_companion);
        errdefer if (listener_companion_fd >= 0) closeFd(listener_companion_fd);

        // S2S peers must be accepted on reactor 0: the mesh dial table,
        // collision resolver, and link-establish side effects are reactor-0
        // state. In sharded mode no other reactor even binds this port.
        const inherited_s2s = nativeManifestListener(config, shard_id, .s2s, false);
        const s2s_listener_fd: linux.fd_t = if (config.s2s_port != 0 and (!reuse_port or shard_id == 0))
            if (inherited_s2s) |fd| try adoptNativeListener(config, fd) else try createListener(primaryListenerHost(config.host), config.s2s_port, config.backlog)
        else
            -1;
        errdefer if (s2s_listener_fd >= 0) closeFd(s2s_listener_fd);
        const s2s_listener_companion_fd = if (s2s_listener_fd >= 0)
            try stageListenerCompanion(config.host, config.s2s_port, s2s_listener_fd, config.backlog, false, inherited_s2s, nativeManifestListener(config, shard_id, .s2s, true))
        else
            -1;
        errdefer if (s2s_listener_companion_fd >= 0) closeFd(s2s_listener_companion_fd);

        // Cert presence is the "TLS configured" signal (main.zig only supplies a
        // chain when [tls] is enabled). Port 0 then means an ephemeral bind, the
        // same convention the plaintext listener uses.
        const inherited_tls = nativeManifestListener(config, shard_id, .tls, false);
        const tls_listener_fd: linux.fd_t = if (certReady(config) and !windows_shared_acceptor_only)
            (if (inherited_tls) |fd|
                try adoptNativeListener(config, fd)
            else if (reuse_port)
                try reuseport.createReusePortListener(primaryListenerHost(config.host), config.tls_port, config.backlog)
            else
                try createListener(primaryListenerHost(config.host), config.tls_port, config.backlog))
        else
            -1;
        errdefer if (tls_listener_fd >= 0) closeFd(tls_listener_fd);
        const tls_listener_companion_fd = if (tls_listener_fd >= 0)
            try stageListenerCompanion(config.host, config.tls_port, tls_listener_fd, config.backlog, reuse_port, inherited_tls, nativeManifestListener(config, shard_id, .tls, true))
        else
            -1;
        errdefer if (tls_listener_companion_fd >= 0) closeFd(tls_listener_companion_fd);

        // Secure-WebSocket (wss) browser listener: gated on `ws_enabled` AND the
        // same cert-presence signal as the TLS listener (browsers require wss).
        // The testing-only plain mode stands it up without a certificate.
        const inherited_ws = nativeManifestListener(config, shard_id, .ws, false);
        const ws_listener_fd: linux.fd_t = if (config.ws_enabled and (certReady(config) or config.ws_allow_plain) and !windows_shared_acceptor_only)
            (if (inherited_ws) |fd|
                try adoptNativeListener(config, fd)
            else if (reuse_port)
                try reuseport.createReusePortListener(primaryListenerHost(config.host), config.ws_port, config.backlog)
            else
                try createListener(primaryListenerHost(config.host), config.ws_port, config.backlog))
        else
            -1;
        errdefer if (ws_listener_fd >= 0) closeFd(ws_listener_fd);
        const ws_listener_companion_fd = if (ws_listener_fd >= 0)
            try stageListenerCompanion(config.host, config.ws_port, ws_listener_fd, config.backlog, reuse_port, inherited_ws, nativeManifestListener(config, shard_id, .ws, true))
        else
            -1;
        errdefer if (ws_listener_companion_fd >= 0) closeFd(ws_listener_companion_fd);

        if (comptime builtin.os.tag == .linux) {
            const incoming_cpu = kernel_linux.shardIncomingCpu(shard_id);
            try kernel_linux.setIncomingCpu(listener_fd, incoming_cpu);
            if (s2s_listener_fd >= 0) try kernel_linux.setIncomingCpu(s2s_listener_fd, incoming_cpu);
            if (tls_listener_fd >= 0) try kernel_linux.setIncomingCpu(tls_listener_fd, incoming_cpu);
            if (ws_listener_fd >= 0) try kernel_linux.setIncomingCpu(ws_listener_fd, incoming_cpu);
        }

        var ring = RingCore.init(config.ring_entries, config.features) catch |err| {
            if (ringlane.isUnsupportedInitError(err)) return error.Unsupported;
            return err;
        };
        errdefer ring.deinit();

        // Reserve the full connection table up front so ConnState buffers never
        // move under in-flight io_uring I/O (a realloc would corrupt them). Each
        // reactor owns a disjoint slab keyed by its own `shard_id`.
        var clients = ClientTable.init(allocator, shard_id);
        errdefer clients.deinit();
        try clients.reserve(config.max_clients);

        return .{
            .ring = ring,
            .clients = clients,
            .shard_id = shard_id,
            .listener_fd = listener_fd,
            .s2s_listener_fd = s2s_listener_fd,
            .tls_listener_fd = tls_listener_fd,
            .ws_listener_fd = ws_listener_fd,
            .listener_companion_fd = listener_companion_fd,
            .s2s_listener_companion_fd = s2s_listener_companion_fd,
            .tls_listener_companion_fd = tls_listener_companion_fd,
            .ws_listener_companion_fd = ws_listener_companion_fd,
            // Best-effort: a daemon without eventfd simply runs un-wakeable (a
            // single reactor never needs an external nudge; multi-reactor needs it
            // for cross-shard delivery, so a failure there degrades to busier polls).
            .wake = reactor_wake.ReactorWake.init() catch null,
        };
    }

    /// Create, bind, and listen on a TCP socket, then initialize the Ringlane
    /// ring used for accept/recv/send completions.
    /// Construct directly into caller-owned storage. `self` is written exactly
    /// once, at the final assignment, so every errdefer below still unwinds a
    /// partially-built image the same way the by-value `init` did.
    ///
    /// Prefer this over `init` for heap fixtures. Debug builds give each
    /// temporary its own stack slot with little reuse, so materializing the
    /// ~2 MB LinuxServer by value costs a multiple of that in frame space
    /// (measured: a 33.6 MB frame against the stock 8 MB limit, which
    /// segfaults the Helix gate). Writing through a result pointer keeps the
    /// big inline subsystem arrays (webhook_posts, trace_recorder,
    /// oper_grants, event_history, ...) off the stack entirely.
    pub fn initInPlace(
        self: *LinuxServer,
        allocator: std.mem.Allocator,
        raw_config: Config,
    ) !void {
        return self.initInPlaceWithAccountSource(allocator, raw_config, null);
    }

    fn initInPlaceWithAccountSource(self: *LinuxServer, allocator: std.mem.Allocator, raw_config: Config, stage: ?*ManagedLeasedCoreStage) !void {
        if (builtin.os.tag != .linux and builtin.os.tag != .openbsd and builtin.os.tag != .windows) return error.Unsupported;

        const accounts_available = if (stage) |source| blk: {
            const b = managedLeasedStageBacking(source).core;
            try source.requireOriginalSources(b.leased_authority orelse return error.ConfiguredOwnerMismatch, b.leased_loan);
            if (raw_config.account_services != null) return error.InvalidAccountBinding;
            break :blk true;
        } else raw_config.account_services != null;

        const self_pidfd: linux.fd_t = if (comptime builtin.os.tag == .linux)
            try kernel_linux.openSelfPidfd()
        else
            -1;
        var self_pidfd_owned = self_pidfd >= 0;
        errdefer if (comptime builtin.os.tag == .linux) {
            if (self_pidfd_owned) os_runtime.close(self_pidfd);
        };

        // Ignore SIGPIPE process-wide. The reactors do socket I/O through io_uring
        // (which reports -EPIPE in the completion, never a signal), but raw
        // `write()`/`send()` on a peer-closed socket — done by the test harness
        // and any non-uring path — would otherwise deliver SIGPIPE, whose default
        // disposition silently terminates the process (no core, exit 141). Setting
        // it here covers both the daemon and the test binaries (which build a
        // Server but never call installUpgradeSignalHandler). Idempotent + global.
        ignoreSigpipe();

        const runtime_features = try normalizeServerPolicy(allocator, raw_config, accounts_available);
        errdefer if (runtime_features.owned_disabled_features) |owned| allocator.free(owned);
        const config = runtime_features.config;
        const durable_plan = try validateDurableDeviceBoot(config);
        try validateMeshAdmissionSecurity(config);
        const boot_unix = @divTrunc(platform.realtimeMillis(), 1000);
        protocol_inventory.setBootUnix(boot_unix);
        protocol_inventory.setNodeId(config.node_id);
        protocol_inventory.setMeshPeerCount(0);
        // Build the complete cold PROP successor before opening even the first
        // listener. DPROP validation, purge/repopulation, clock allocation, and
        // checked HLC observation are therefore incapable of leaving a bound
        // but non-authoritative daemon behind on failure.
        var initial_props = ircx_prop_store.DefaultStore.init(allocator);
        defer initial_props.deinit();
        var initial_channel_clocks: prop_checkpoint.ChannelClockMap = .empty;
        defer initial_channel_clocks.deinit(allocator);
        var initial_entity_clocks: prop_checkpoint.EntityClockMap = .empty;
        defer initial_entity_clocks.deinit(allocator);
        var durable_property_candidate: ?prop_checkpoint.Restored = null;
        defer if (durable_property_candidate) |*candidate| candidate.deinit();
        var initial_mesh_clock: mesh_clock_mod.MeshClock = .{};
        switch (durable_plan) {
            .inactive => {},
            .purge_only, .authoritative => {
                durable_property_candidate = try buildConfiguredDurableDeviceCandidate(
                    allocator,
                    &initial_props,
                    &initial_channel_clocks,
                    &initial_entity_clocks,
                    durable_plan,
                );
                try initial_mesh_clock.observeChecked(
                    durable_property_candidate.?.max_hlc,
                    @intCast(@max(@as(i64, 0), platform.realtimeMillis())),
                    mesh_clock_mod.default_max_future_skew_ms,
                );
            },
        }

        const shard_count = clampShards(config);
        try validateNativeInheritedListenerClaims(config);
        // For >1 shard EVERY listener (shard 0 included) must be SO_REUSEPORT or
        // the kernel rejects the second bind on the shared port. The single-shard
        // path keeps plain sockets so its behavior is byte-identical to before.
        const reuse_port = shard_count > 1;

        const reactors = try allocator.alloc(Reactor, shard_count);
        errdefer allocator.free(reactors);
        var built: usize = 0;
        errdefer for (reactors[0..built]) |*r| r.deinit();
        while (built < shard_count) : (built += 1) {
            var shard_config = config;
            if (builtin.os.tag == .openbsd and built > 0) {
                // A wildcard pair uses one selected ephemeral port. Every later
                // shard must bind that same port, including TLS/WS port0 cases.
                if (shard_config.port == 0) shard_config.port = try socketPort(reactors[0].listener_fd);
                if (shard_config.tls_port == 0 and reactors[0].tls_listener_fd >= 0)
                    shard_config.tls_port = try socketPort(reactors[0].tls_listener_fd);
                if (shard_config.ws_port == 0 and reactors[0].ws_listener_fd >= 0)
                    shard_config.ws_port = try socketPort(reactors[0].ws_listener_fd);
            }
            reactors[built] = try initReactor(allocator, shard_config, @intCast(built), reuse_port);
        }
        if (builtin.os.tag == .openbsd and config.inherited_listener_companion_fds.len > shard_count) {
            for (config.inherited_listener_companion_fds[shard_count..]) |fd| closeFd(fd);
        }
        // A predecessor with MORE shards than this successor carried extra
        // listener fds no reactor adopted: close them now so they neither leak
        // nor keep receiving SO_REUSEPORT-balanced SYNs nobody will accept.
        var surplus_closed_with_close_range = false;
        if (config.inherited_listener_fds.len > shard_count) {
            if (comptime builtin.os.tag == .linux) {
                surplus_closed_with_close_range = try kernel_linux.closeOwnedFdSpan(config.inherited_listener_fds[shard_count..]);
            } else {
                for (config.inherited_listener_fds[shard_count..]) |fd| closeFd(fd);
            }
        }
        var msg_ring_booted = false;
        if (comptime builtin.os.tag == .linux) {
            if (shard_count >= 2) {
                try reactors[0].ring.bootMsgRing(&reactors[1].ring);
                msg_ring_booted = true;
            }
        }

        var tls_ticket_key: tls_resumption.TicketKey = @splat(0);
        if (config.tls_enable_resumption) secure_fns.randomBytes(&tls_ticket_key);

        var whowas_store = try WhowasStore.init(allocator);
        errdefer whowas_store.deinit();

        var relay_replay_guard = try relay_v2_replay_guard.Guard.init(allocator, .{});
        errdefer relay_replay_guard.deinit();
        var relay_outbox = try relay_v2_outbox.Outbox.init(allocator, relay_v2_outbox.default_max_entries);
        errdefer relay_outbox.deinit();
        var relay_event_log = try relay_v2_event_log.EventLog.init(allocator, .{});
        errdefer relay_event_log.deinit();
        var e2ee_group_authority = try e2ee_group_mesh_authority.Authority.init(allocator, .{});
        errdefer e2ee_group_authority.deinit();
        var delivery_spool = try attachment_delivery_spool.Spool.init(allocator, .{});
        errdefer delivery_spool.deinit();
        var event_replay_guard = try event_spine_replay_guard.Guard.init(allocator, .{});
        errdefer event_replay_guard.deinit();

        // Parse the [mesh].connect auto-dial table once: invalid "host:port"
        // specs are logged and dropped so one typo never blocks the others.
        var mesh_dials: []MeshDial = &.{};
        if (config.mesh_connect.len != 0) {
            var valid: usize = 0;
            for (config.mesh_connect) |spec| {
                if (parseHostPort(spec) != null) {
                    valid += 1;
                } else {
                    srvLog("onyx-server: mesh auto-connect: bad peer spec '{s}' (want host:port); ignored\n", .{spec});
                }
            }
            if (valid != 0) {
                const dials = try allocator.alloc(MeshDial, valid);
                var n: usize = 0;
                for (config.mesh_connect) |spec| {
                    const hp = parseHostPort(spec) orelse continue;
                    dials[n] = .{ .spec = spec, .host = hp.host, .port = hp.port };
                    n += 1;
                }
                mesh_dials = dials;
            }
        }
        errdefer if (mesh_dials.len != 0) allocator.free(mesh_dials);

        var mesh_trusted_node_keys: [][32]u8 = &.{};
        if (config.mesh_trust_roots.len != 0) {
            var valid_roots: usize = 0;
            for (config.mesh_trust_roots) |root| {
                if (decodeMeshTrustRoot(root) != null) {
                    valid_roots += 1;
                } else {
                    srvLog("onyx-server: mesh trust root '{s}' is not a 32-byte hex/base64 key; ignored\n", .{root});
                }
            }
            if (valid_roots != 0) {
                const roots = try allocator.alloc([32]u8, valid_roots);
                var n: usize = 0;
                for (config.mesh_trust_roots) |root| {
                    if (decodeMeshTrustRoot(root)) |key| {
                        roots[n] = key;
                        n += 1;
                    }
                }
                mesh_trusted_node_keys = roots;
            }
        }
        errdefer if (mesh_trusted_node_keys.len != 0) allocator.free(mesh_trusted_node_keys);

        const relay_v2_activation_state = try computeRelayV2ActivationState(
            allocator,
            config,
            mesh_trusted_node_keys,
        );

        var relay_v2_required_nodes: []u64 = &.{};
        if (config.mesh_trust_roots.len != 0 and
            mesh_trusted_node_keys.len == config.mesh_trust_roots.len and
            mesh_trusted_node_keys.len + 1 <= relay_event_log.config.max_confirmed_nodes_per_row)
        {
            const nodes = try allocator.alloc(u64, mesh_trusted_node_keys.len + 1);
            var valid_membership = config.node_id != 0;
            nodes[0] = config.node_id;
            for (mesh_trusted_node_keys, nodes[1..]) |key, *node| {
                node.* = node_short_id.shortId(node_identity.nodeIdFromPublicKey(key));
            }
            std.mem.sort(u64, nodes, {}, std.sort.asc(u64));
            for (nodes[1..], nodes[0 .. nodes.len - 1]) |node, prior| {
                if (node == prior) {
                    valid_membership = false;
                    break;
                }
            }
            if (valid_membership) {
                relay_v2_required_nodes = nodes;
            } else {
                allocator.free(nodes);
                srvLog("onyx-server: MESSAGE_V2 durable membership disabled: trust roots contain the local node, duplicates, or short-id collisions\n", .{});
            }
        } else if (config.node_identity != null) {
            srvLog("onyx-server: MESSAGE_V2 durable membership disabled: require a non-empty, fully valid, bounded direct-neighbor trust-root set\n", .{});
        }
        errdefer if (relay_v2_required_nodes.len != 0) allocator.free(relay_v2_required_nodes);
        if (relay_v2_activation_state.activation_epoch != 0 and
            relay_v2_required_nodes.len != mesh_trusted_node_keys.len + 1)
            return error.InvalidRelayV2ActivationPlan;

        var meshpass_roots: []meshpass.TrustRoot = &.{};
        if (config.mesh_admission_roots.len != 0) {
            var valid_roots: usize = 0;
            for (config.mesh_admission_roots) |root| {
                if (decodeMeshTrustRoot(root) != null) {
                    valid_roots += 1;
                } else {
                    srvLog("onyx-server: mesh admission root '{s}' is not a 32-byte hex/base64 key; ignored\n", .{root});
                }
            }
            if (valid_roots != 0) {
                const roots = try allocator.alloc(meshpass.TrustRoot, valid_roots);
                var n: usize = 0;
                for (config.mesh_admission_roots) |root| {
                    if (decodeMeshTrustRoot(root)) |key| {
                        roots[n] = .{
                            .public_key = key,
                            .realm = config.mesh_realm,
                            .min_revocation_epoch = config.mesh_admission_min_revocation_epoch,
                        };
                        n += 1;
                    }
                }
                meshpass_roots = roots;
            } else {
                return error.InvalidMeshAdmissionRoot;
            }
        }
        errdefer if (meshpass_roots.len != 0) allocator.free(meshpass_roots);

        var mesh_admission_token: []u8 = &.{};
        if (config.mesh_admission_token.len != 0) {
            mesh_admission_token = try decodeMeshAdmissionToken(allocator, config.mesh_admission_token);
        }
        errdefer if (mesh_admission_token.len != 0) allocator.free(mesh_admission_token);

        const geo_ptr = try allocator.create(geo_services.Service);
        errdefer allocator.destroy(geo_ptr);
        geo_ptr.* = geo_services.Service.init(allocator, .{
            .weather_enabled = config.geo_enabled,
            .news_enabled = config.geo_enabled,
            .news_insecure_tls = config.geo_news_insecure_tls,
            .news_cache_dir = config.geo_news_cache_dir,
            .max_headlines = @intCast(@min(config.news_count, 5)),
        });

        var latency_stats = try server_stats.LatencyStats.init(allocator, reactors.len);
        errdefer latency_stats.deinit();
        var raid_state = try raid_shield.Shield.init(allocator);
        errdefer raid_state.deinit();

        // These tables allocate backing storage. Build every fallible leaf
        // before publishing self so OOM refunds the unopened NEW graph instead
        // of panicking with a partially initialized Server.
        var thread_store = try thread_snapshot.Table.init(allocator);
        errdefer thread_store.deinit();
        var schedule_store = try schedule_snapshot.Table.init(allocator);
        errdefer schedule_store.deinit();
        var appeal_store = try appeal.Table.init(allocator);
        errdefer appeal_store.deinit();
        var first_hold_store = try first_hold.Table.init(allocator);
        errdefer first_hold_store.deinit();
        var slash_store = try slash_cmd.Table.init(allocator);
        errdefer slash_store.deinit();
        var prepared_media_plane = try media_plane_mod.MediaPlane.initFallible(allocator);
        errdefer prepared_media_plane.deinit();

        self_pidfd_owned = false;
        self.* = .{
            .runtime_inherited_image = config.resume_arena_fd != null or config.native_arena_bytes != null or config.inherited_state_fd_manifest_present,
            .allocator = allocator,
            .config = config,
            .windows_helix_source_valid = .init(config.windows_helix_source_digest != null),
            .owned_disabled_features = runtime_features.owned_disabled_features,
            .wasm = wasm_bridge.Bridge.initWithOptions(allocator, .{
                .max_plugin_bytes = config.wasm_max_plugin_bytes,
                .max_memory_bytes = config.wasm_max_memory_bytes,
                .default_fuel = config.wasm_default_fuel,
                .allowed_caps = config.wasm_allowed_caps,
                .allowed_intents = config.wasm_allowed_intents,
                .registry = config.wasm_registry,
                .revoked_hashes = config.wasm_revoked_hashes,
                .disabled_plugins = config.wasm_disabled_plugins,
            }),
            .relay_seen = message_relay.SeenSet.init(allocator, 4096),
            .relay_v2_replay_guard = relay_replay_guard,
            .relay_v2_outbox = relay_outbox,
            .relay_v2_event_log = relay_event_log,
            .e2ee_group_mesh_authority = e2ee_group_authority,
            .e2ee_group_local_authoring_enabled = .init(config.e2ee_group_authoring_enabled),
            .attachment_delivery_spool = delivery_spool,
            .tls_ticket_key = tls_ticket_key,
            .native_stream_key = blk: {
                var k: [16]u8 = undefined;
                secure_fns.randomBytes(&k);
                break :blk k;
            },
            .reactors = reactors,
            .self_pidfd = self_pidfd,
            .surplus_closed_with_close_range = surplus_closed_with_close_range,
            .msg_ring_booted = msg_ring_booted,
            .mesh_dials = mesh_dials,
            .mesh_trusted_node_keys = mesh_trusted_node_keys,
            .relay_v2_required_nodes = relay_v2_required_nodes,
            .relay_v2_activation_state = relay_v2_activation_state,
            .meshpass_roots = meshpass_roots,
            .mesh_admission_token = mesh_admission_token,
            .pool = reactor_pool_mod.ReactorPool(*LinuxServer).init(allocator),
            .world = blk: {
                var w = world_model.World.init(allocator);
                w.max_list_entries = config.maxlist;
                break :blk w;
            },
            .whowas = whowas_store,
            .monitor = monitor.MonitorStore.init(allocator, config.monitorlimit),
            .read_markers = read_marker_store.DefaultStore.init(allocator),
            .silence = silence.Store.initWithParams(allocator, .{ .max_masks_per_owner = config.silencelimit }),
            .observe = observe_mod.Registry.init(allocator, .{}),
            .oper_motd = oper_motd_mod.OperMotd.init(allocator),
            .bot_registry = bot_registry_mod.BotRegistry.init(allocator),
            .threads = thread_store,
            .schedules = schedule_store,
            .appeals = appeal_store,
            .first_holds = first_hold_store,
            .slash_cmds = slash_store,
            .host_requests = host_request_mod.Queue.init(allocator, .{}),
            .guises = guise_mod.Registry.init(allocator, .{}),
            .shuns = shun_mod.ShunList.init(allocator, .{}),
            .gags = gag_set.GagSet.init(allocator, .{}),
            .temp_modes = svc_tempmode.TempModeQueue.init(allocator),
            .autojoins = autojoin_mod.AutoJoin.init(allocator),
            .nick_groups = memo_group_mod.NickGroup.init(allocator),
            .welcome = welcome_pack_mod.WelcomePack.init(allocator),
            // Verify and reset tokens are process-local. A dropped image does not
            // restore them: the old code is invalid, and the request commands
            // issue a new one. Pending TOTP enrollments stay in RAM the same way.
            .account_verifies = account_verify_mod.VerifyStore.init(allocator, .{ .token_bytes = 16 }),
            .reset_store = password_reset.ResetStore.init(allocator, .{ .token_bytes = reset_token_hex_len }),
            .totp = totp_auth.TotpStore.init(allocator, .{}),
            .history = HistoryStore.init(allocator),
            .search_index = search_index_mod.SearchIndex.initWithConfig(allocator, config.search_index_config),
            .event_spine_replay_guard = event_replay_guard,
            .chanstats = chanstats_mod.ChanStats.init(allocator),
            .warden = warden.Registry.init(allocator, .{}),
            .spamtrap = spamtrap_mod.DefaultSpamtrap.init(allocator),
            .raid_shield = raid_state,
            .metadata = metadata_store.DefaultStore.init(allocator),
            .geo = geo_ptr,
            .props = if (durable_property_candidate) |candidate|
                candidate.props
            else
                ircx_prop_store.DefaultStore.init(allocator),
            .access = ircx_access_store.AccessStore.init(allocator),
            .saccess = ircx_saccess.ServerAccessStore.init(allocator),
            .chan_akick = svc_akick.AkickStore.init(allocator),
            .chan_resv = svc_resv.ChannelResv.init(allocator, .{}),
            .server_jupe = svc_jupe.JupeStore.init(allocator, .{}),
            .clone_limit = clone_limit_mod.CloneLimiter.init(allocator, .{
                .max_per_ip = config.max_clones_per_ip,
                .max_per_net = config.max_clones_per_net,
            }),
            .nick_delay = nick_delay_mod.NickDelay.init(allocator),
            .conn_throttle = if (config.throttle_connects != 0) clone_detect_mod.CloneDetector.init(allocator, .{
                .max_concurrent_per_ip = 0, // concurrent caps are clone_limit's job; this is pure rate
                .max_connects_per_window = config.throttle_connects,
                .window_ms = @max(@as(u64, 1), config.throttle_window_ms),
            }) else null,
            .login_throttle = svc_login_throttle.Throttle.init(allocator, .{}),
            .oper_audit = svc_operaudit.OperAudit.init(allocator),
            .mesh_clones = mesh_clones_mod.MeshClones.init(allocator),
            .clone_key = deriveCloneKey(config.mesh_pass),
            .reputation = ip_reputation_mod.IpReputation.init(allocator, .{
                .half_life_ms = @intCast(@max(1, config.reputation_half_life_ms)),
                .refuse_threshold = @floatFromInt(config.reputation_refuse_threshold),
            }) catch unreachable,
            .account_abuse = account_abuse_mod.AccountAbuse.init(allocator),
            .accepts = accept_list.AcceptList(.{}).init(allocator),
            .snowflake = snowflake_id.Generator.init(.{ .node_id = @intCast(config.node_id & snowflake_id.NODE_MASK) }) catch unreachable,
            // Seed the msgid minter once from boot entropy (OS CSPRNG via
            // secure_fns/getrandom) so ids are opaque and disjoint across boots.
            .msgid_gen = msgid_mod.Generator.init(secure_fns.randomU64()),
            .activity_subs = activity_subscriptions.SubscriptionStore.init(allocator),
            .latency_stats = latency_stats,
            .peer_health = link_health_mod.Registry.init(allocator),
            .metrics_snapshot = metrics_http.MetricsSnapshot.init(allocator),
            .sessions = sessions_mod.SessionStore.initWithConfig(allocator, .{
                .max_accounts = @intCast(config.session_max_accounts),
                .max_sessions_per_account = config.session_max_per_account,
            }),
            .session_replica_store = session_replica_v2.Store.initWithConfig(allocator, .{
                .max_entries = @intCast(config.session_max_pending_migrations),
                .max_attachment_leases = @intCast(config.session_max_pending_migrations),
                .max_routes = @as(usize, @intCast(config.session_max_pending_migrations)) *| 16,
                .max_tombstones = @intCast(config.session_max_pending_migrations),
                .max_offer_lifetime_ms = mesh_reclaim_ttl_ms,
                .max_attachment_lease_lifetime_ms = session_attachment_lease_ttl_ms,
                .route_ttl_ms = mesh_reclaim_ttl_ms,
                .tombstone_ttl_ms = mesh_reclaim_ttl_ms,
            }),
            .content_filter = content_filter_mod.ContentFilter.initWithConfig(allocator, config.content_filter_config),
            .media_rooms = media_room.MediaRooms.initConfig(allocator, .{
                .max_participants = config.media_max_participants,
                .max_breakout_bytes = config.media_sfu_max_breakout_label_bytes,
            }),
            .media_plane = prepared_media_plane,
            .native_media = native_media_mod.NativeMediaTransport.initConfig(allocator, config.media_max_participants),
            .memo = memo_mod.MemoBox.initWithConfig(allocator, config.memo_config),
            .memo_forward = svc_memo_forward.MemoForwardStore.init(allocator),
            .memo_ignore = svc_memo_ignore.MemoIgnoreList.init(allocator),
            .transcript = transcript_mod.TranscriptLog.initConfig(allocator, config.transcript_config),
            .oper_registry = config.oper_registry,
            .account_services = config.account_services,
            .ocg2_runtime = config.ocg2_runtime,
            .ocg2_runtime_monotonic_origin_ms = config.ocg2_runtime_monotonic_origin_ms,
            .ocg2_projection = config.ocg2_projection,
            .ocg2_projection_origin_ms = config.ocg2_projection_origin_ms,
            .ocg2_audit = config.ocg2_audit,
            .mesh_clock = initial_mesh_clock,
            .reactor = config.reactor,
            .start_ms = if (config.reactor) |r| r.nowMillis() else platform.monotonicMillis(),
            .boot_unix = boot_unix,
        };
        if (durable_property_candidate) |candidate| {
            self.channel_prop_clocks = candidate.channel_clocks;
            self.entity_prop_clocks = candidate.entity_clocks;
            durable_property_candidate = null;
        }
        self.restoreDurableHistory();
        self.restoreDurableMemos();
        self.restoreDurableMarkers();
        self.restoreDurableGags();
        self.restoreDurableAbuse();
        self.restoreDurableVhosts();
        self.restoreProofChain();
    }

    /// By-value construction, kept for callers that own the result directly.
    /// This materializes the whole ~2 MB image in the caller's frame; a fixture
    /// that already has heap storage should call `initInPlace` instead so the
    /// image is never staged on the stack at all.
    pub fn init(allocator: std.mem.Allocator, raw_config: Config) !LinuxServer {
        var self: LinuxServer = undefined;
        try self.initInPlace(allocator, raw_config);
        return self;
    }

    /// Run module init→ready lifecycle once the server is at its final address
    /// (called by main after construction; init() returns by value so `self`
    /// is not stable inside it).
    pub fn start(self: *LinuxServer) void {
        if (self.configured_cold_resources_prepared)
            @panic("legacy startup cannot spawn behind the configured runtime Gate");
        self.bindFlightPanicTarget();
        // An inherited arena is an unpublished authoritative image. Starting
        // webhook/media/metrics workers before it is adopted lets off-reactor
        // producers observe and mutate the fresh boot image, then race the
        // atomic replacement. This is a programmer-ordering invariant, so fail
        // the process rather than limp into a partially resumed daemon.
        if (!self.inheritedStateConsumedBeforeServices())
            @panic("Server.start called before adoptInheritedSessions consumed the inherited Helix handoff");
        self.driveLifecycle(.init);
        self.driveLifecycle(.ready);
        // Holding area for cross-mesh live-session migration capsules awaiting the
        // client's reconnect. Allocated once here so handleMeshReclaim and the S2S
        // drain both see a live store (null until start = migration inert).
        if (self.pending_migrations == null) {
            self.pending_migrations = session_migrate.PendingMigrations.initWithConfig(self.allocator, .{
                .max_entries = self.config.session_max_pending_migrations,
                .max_per_account = self.config.session_max_per_account,
            });
        }
        // Restore cold-boot grants only. An inherited exact checkpoint already
        // includes revocation tombstones and its mint high-water mark.
        self.loadGrants();
        // Restore per-channel statistics persisted by a previous run so they
        // survive a restart or USR2 hot-upgrade.
        self.loadChanstats();
        // Restore the Event Spine history ring (EVENT REPLAY) the same way.
        self.restoreEventHistoryAtStart();
        if (self.config.media_enabled) {
            if (self.media_routing_owner == null) self.startMediaRoutingLegacy() catch |err| {
                srvLog("onyx-server: media routing disabled ({s})\n", .{@errorName(err)});
            };
        } else if (self.media_routing_owner == null) {
            // WS call membership is independent of UDP configuration. This
            // owns actual empty typed sources, not a fake UDP readiness row.
            self.prepareMediaRoutingOwner() catch |err| {
                srvLog("onyx-server: media membership unavailable ({s})\n", .{@errorName(err)});
            };
        }
        self.startMetrics();
        self.startWebhook();
    }

    /// Windows boot treats explicitly configured companions as required. The
    /// legacy start path logs optional-service failures; check their actual
    /// worker ownership before the reactor begins serving clients.
    pub fn startCheckedWindows(self: *LinuxServer) !void {
        if (comptime builtin.os.tag != .windows) return error.Unsupported;
        self.start();
        if (self.config.media_enabled and
            (self.media_routing_owner == null or
                (self.native_media.thread == null and self.native_media.runtime.view == null) or
                (self.media_plane.thread == null and self.media_plane.runtime.view == null)))
            return error.MediaStartupFailed;
        if (self.config.metrics_port != 0 and
            (self.metrics_server == null or
                (self.metrics_server.?.thread == null and self.metrics_server.?.runtime.view == null)))
            return error.MetricsStartupFailed;
        if (self.config.webhook_enabled and
            (self.webhook_server == null or
                (self.webhook_server.?.thread == null and self.webhook_server.?.runtime.view == null)))
            return error.WebhookStartupFailed;
        if (self.history_https != null and
            self.history_https.?.thread == null and self.history_https.?.runtime_worker.view == null)
            return error.HistoryStartupFailed;
    }

    /// Actual source resources have been prepared at this final Server address.
    /// Bind both typed owners and fund the complete fixed FIFO before any pump.
    fn prepareMediaRoutingOwner(self: *LinuxServer) !void {
        if (self.media_routing_owner != null) return error.RuntimeAlreadyPrepared;
        const owned = try self.allocator.create(MediaRoutingBacking);
        errdefer self.allocator.destroy(owned);
        const domain = try media_routing.Domain.create(self.allocator);
        errdefer domain.destroyQuiesced() catch @panic("failed routing construction retained a source row");
        const native_binding = try domain.bindNative(&self.native_media);
        errdefer domain.releaseNative(native_binding) catch @panic("failed routing construction retained Native custody");
        const webrtc_binding = try domain.bindWebrtc(&self.media_plane);
        errdefer domain.releaseWebrtc(webrtc_binding) catch @panic("failed routing construction retained WebRTC custody");
        // This is a finite, funded admission bound, not an eviction policy or
        // a claim that arbitrary configured populations can be accepted.
        if (self.config.media_enabled) try self.media_plane.prepareRoutingEgress(domain, 64, media_plane_mod.max_datagram);
        owned.* = .{ .server = self, .allocator = self.allocator, .domain = domain, .native_binding = native_binding, .webrtc_binding = webrtc_binding, .prepared_egress = if (self.media_plane.routing_egress) |queue| @ptrCast(queue) else null, .queue_retired = !self.config.media_enabled };
        self.media_routing_owner = @ptrCast(owned);
    }

    /// Cold preparation rollback owns no admitted route or worker. Actual source
    /// APIs verify that fact; no caller bool or mutable field clears custody.
    fn rollbackPreparedMediaRouting(self: *LinuxServer) void {
        const opaque_owner = self.media_routing_owner orelse return;
        const owner = mediaRoutingBacking(opaque_owner);
        if (!owner.queue_retired) self.media_plane.disposeRoutingEgress(owner.domain) catch @panic("cold rollback retained accepted routing output");
        owner.domain.releaseWebrtc(owner.webrtc_binding.?) catch @panic("cold rollback retained WebRTC authority");
        owner.domain.releaseNative(owner.native_binding.?) catch @panic("cold rollback retained Native authority");
        owner.domain.destroyQuiesced() catch @panic("cold rollback retained routing authority");
        self.media_routing_owner = null;
        owner.allocator.destroy(owner);
    }

    /// Registered JOIN capability delivery uses the same actual dispatch owner
    /// as OFFER/ANSWER. Membership and the complete MACKEY issuer publish once.
    pub fn mediaJoinJoined(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, kind: media_room.MediaKind) !void {
        const turn = try MediaAuthorityTurn.require(self, id, conn, .join, channel);
        try turn.requireEmptyIssuer();
        const owner = self.media_routing_owner orelse return self.failReply(conn, "MEDIA", "JOIN_FAILED", "Media routing is unavailable");
        var first_kind: bool = undefined;
        var stopped_recording: bool = undefined;
        if (self.config.ws_media_relay and conn.ws != null) {
            var plan = (PreparedMediaBrowserJoin.prepare(self, mediaRoutingBacking(owner).domain, id, conn, channel, kind, turn.label()) catch |err| switch (err) {
                error.BadState => return self.failReply(conn, "MEDIA", "SECURE_SIGNALING_REQUIRED", "Browser media credentials require a live protected signaling connection"),
                else => return err,
            }) orelse return;
            defer plan.deinit();
            first_kind = plan.physical.first_kind;
            stopped_recording = plan.stops_recording;
            try plan.domain.withLocked(&plan, PreparedMediaBrowserJoin.publishLocked);
            turn.published = true;
        } else {
            var plan = (try PreparedLogicalMediaJoin.prepare(turn, mediaRoutingBacking(owner).domain, kind)) orelse return;
            defer plan.deinit();
            first_kind = plan.physical.first_kind;
            stopped_recording = plan.stops_recording;
            try plan.domain.withLocked(&plan, PreparedLogicalMediaJoin.publishLocked);
        }
        conn.reply_capture = null;
        if (first_kind) try self.broadcastMediaEvent(channel, "JOIN", conn.session.displayName(), media_room.kindName(kind));
        if (stopped_recording) try self.broadcastMediaEvent(channel, "RECORD", conn.session.displayName(), "stopped");
        if (first_kind) self.webpushNotifyCallInvite(channel, conn.session.displayName());
    }

    fn configureMediaColdPolicy(self: *LinuxServer) !void {
        // Retain the configured Server callback lifetime at the final address.
        // Typed routing-bound pumps use Domain authority; these callbacks keep
        // the explicitly configured legacy bridge policy exact as well.
        self.native_media.setCrossLegSink(.{ .ctx = self, .on_native_frame = bridgeOnNativeFrame, .on_native_feedback = bridgeOnNativeFeedback });
        self.media_plane.setCrossLegSink(.{ .ctx = self, .on_rtp_frame = bridgeOnRtpFrame, .on_rtcp_feedback = bridgeOnRtcpFeedback });
        self.media_plane.max_frame_bytes = @intCast(@min(self.config.media_max_frame_bytes, @as(u64, media_plane_mod.max_datagram)));
        self.media_plane.max_upload_bytes = self.config.media_max_upload_bytes;
        self.native_media.max_frame_bytes = @intCast(@min(self.config.media_max_frame_bytes, @as(u64, native_media_mod.max_datagram)));
        self.native_media.max_upload_bytes = self.config.media_max_upload_bytes;
        self.native_media.configureMac(&self.native_stream_key, self.config.native_media_require_mac);
        if (self.config.media_stun_port != 0) {
            const ip4 = parseIp4(self.config.media_stun_host) orelse return error.InvalidMediaStunAddress;
            self.media_plane.stun_server = try media_plane_mod.TransportAddress.fromBytes(&ip4, self.config.media_stun_port);
        }
        self.media_plane.dtls_enabled = self.config.media_dtls_srtp;
        self.media_plane.dtls13_enabled = self.config.media_dtls13;
    }

    /// Legacy main startup also creates resources/routing/FIFO before spawning.
    /// Configured main uses the same owned resources with its private Control.
    fn startMediaRoutingLegacy(self: *LinuxServer) !void {
        const io = self.config.crypto_io orelse return error.MissingCryptoIo;
        try self.configureMediaColdPolicy();
        try self.native_media.prepareColdResources(io, native_media_mod.any_be, self.config.native_media_port);
        errdefer self.native_media.shutdown();
        try self.media_plane.prepareColdResources(io, media_plane_mod.any_be, self.config.media_port);
        errdefer self.media_plane.shutdown();
        try self.prepareMediaRoutingOwner();
        errdefer self.rollbackPreparedMediaRouting();
        try self.native_media.startPreparedLegacyWorker();
        errdefer {
            self.native_media.requestStopAndWake();
            self.native_media.joinLegacyAfterStop() catch @panic("failed media startup retained Native worker");
        }
        try self.media_plane.startPreparedLegacyWorker();
    }

    /// Fence actual accepted egress before stopping its consumer. Callers hold
    /// graph/producer ownership, and wait outside World/Domain/backend locks.
    pub fn settleMediaRoutingBeforeStop(self: *LinuxServer, deadline_ms: u64) !void {
        const opaque_owner = self.media_routing_owner orelse return;
        const owner = mediaRoutingBacking(opaque_owner);
        if (owner.queue_retired) return;
        const Cut = struct {
            owner: *MediaRoutingBacking,
            fn fence(scope: *media_routing.Locked, ctx: @This()) !media_plane_mod.RoutingProducerFence {
                return ctx.owner.server.media_plane.fenceRoutingProducersLocked(ctx.owner.domain, scope);
            }
            fn settled(scope: *media_routing.Locked, ctx: @This()) !void {
                try ctx.owner.server.media_plane.requireRoutingEgressSettledLocked(ctx.owner.domain, scope, ctx.owner.producer_fence.?);
            }
        };
        if (owner.producer_fence == null) owner.producer_fence = try owner.domain.withLocked(Cut{ .owner = owner }, Cut.fence);
        while (true) {
            owner.domain.withLocked(Cut{ .owner = owner }, Cut.settled) catch |err| switch (err) {
                error.Busy => {
                    const now_ms = std.math.cast(u64, platform.monotonicMillis()) orelse return error.InvalidMonotonicClock;
                    if (now_ms >= deadline_ms) return error.MediaSettlementPending;
                    std.Thread.yield() catch {};
                    continue;
                },
                else => return err,
            };
            return;
        }
    }

    /// Every source worker must already be joined and its View detached. Exact
    /// terminal retirement is source-checked and retains all resources on error.
    fn finishMediaRoutingAfterJoined(self: *LinuxServer) !void {
        return self.finishMediaRoutingAfterJoinedUntil(null);
    }

    fn finishMediaRoutingAfterJoinedUntil(self: *LinuxServer, deadline: ?std.Io.Clock.Timestamp) !void {
        const opaque_owner = self.media_routing_owner orelse return;
        const owner = mediaRoutingBacking(opaque_owner);
        try self.requireMediaRetirementDeadline(deadline);
        try owner.domain.closeForTerminal();
        if (!owner.queue_retired) {
            try self.media_plane.finishRoutingTerminalCleanup(owner.domain);
            owner.queue_retired = true;
        }
        const previous = current_reactor;
        defer current_reactor = previous;
        for (self.reactors) |*reactor| {
            current_reactor = reactor;
            for (reactor.clients.slots.items, 0..) |*slot, index| {
                if (!slot.occupied) continue;
                try self.requireMediaRetirementDeadline(deadline);
                const id: client_model.ClientId = .{ .shard = reactor.shard_id, .slot = @intCast(index), .gen = slot.gen };
                try self.retireMediaRoutingClient(id, &slot.value, true);
            }
        }
        // A failed later release retains exact remaining custody. Never reuse
        // a binding whose source already detached and freed its issued record.
        try self.requireMediaRetirementDeadline(deadline);
        if (owner.webrtc_binding) |binding| {
            try owner.domain.releaseWebrtc(binding);
            owner.webrtc_binding = null;
        }
        if (owner.native_binding) |binding| {
            try owner.domain.releaseNative(binding);
            owner.native_binding = null;
        }
        try owner.domain.destroyQuiesced();
        self.media_routing_owner = null;
        owner.allocator.destroy(owner);
    }

    fn requireMediaRetirementDeadline(self: *LinuxServer, deadline: ?std.Io.Clock.Timestamp) !void {
        const limit = deadline orelse return;
        if (limit.clock != .awake) return error.InvalidDeadline;
        const io = self.runtime_io orelse self.config.crypto_io orelse return error.MissingCryptoIo;
        if (std.Io.Clock.Timestamp.compare(std.Io.Clock.Timestamp.now(io, .awake), .gte, limit)) return error.Timeout;
    }

    /// Stop waits for the original World mutex with its original absolute
    /// deadline. A live maintenance HTTP attempt must not make lock acquisition
    /// an unbounded terminal wait; failure leaves source ownership untouched.
    fn lockWorldUntil(self: *LinuxServer, deadline: std.Io.Clock.Timestamp) !void {
        try self.requireMediaRetirementDeadline(deadline);
        const io = self.runtime_io orelse self.config.crypto_io orelse return error.MissingCryptoIo;
        while (!self.world.lock.tryLockExclusive()) {
            try self.requireMediaRetirementDeadline(deadline);
            try std.Io.sleep(io, .fromMilliseconds(1), .awake);
        }
        errdefer self.world.unlockWrite();
        try self.requireMediaRetirementDeadline(deadline);
    }

    fn retireMediaRoutingClient(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, terminal: bool) !void {
        const owner = mediaRoutingBacking(self.media_routing_owner orelse return error.BadState);
        const domain = owner.domain;
        const departure = try domain.prepareClientDeparture(id);
        defer departure.deinit();
        if (departure.isTerminal() != terminal) return error.BadState;
        const native = try self.native_media.prepareClientDeparture(domain, departure);
        defer native.deinit();
        const webrtc = try self.media_plane.prepareClientDeparture(domain, departure);
        defer webrtc.deinit();
        const rooms = try self.media_rooms.prepareClientDeparture(departure);
        defer rooms.deinit();
        var physical = try PreparedMediaPhysicalClientDeparture.prepare(self, id, conn);
        defer physical.deinit();
        const Cut = struct {
            domain: *media_routing.Domain,
            departure: *media_routing.PreparedClientDeparture,
            native: *native_media_mod.PreparedNativeClientDeparture,
            webrtc: *media_plane_mod.PreparedWebrtcClientDeparture,
            rooms: *media_room.PreparedRoomClientDeparture,
            physical: *PreparedMediaPhysicalClientDeparture,
            fn run(scope: *media_routing.Locked, ctx: @This()) !void {
                try ctx.departure.validateLocked(ctx.domain, scope);
                try ctx.native.validateLocked(ctx.domain, scope, ctx.departure);
                try ctx.webrtc.validateLocked(ctx.domain, scope, ctx.departure);
                try ctx.rooms.validateLocked(ctx.domain, scope, ctx.departure);
                try ctx.physical.validateLocked(ctx.domain, scope, ctx.departure);
                ctx.native.commitLocked(ctx.domain, scope);
                ctx.webrtc.commitLocked(ctx.domain, scope);
                ctx.rooms.commitLocked(ctx.domain, scope);
                ctx.physical.commit();
                ctx.departure.commitLocked(ctx.domain, scope);
            }
        };
        const cut: Cut = .{ .domain = domain, .departure = departure, .native = native, .webrtc = webrtc, .rooms = rooms, .physical = &physical };
        if (terminal) try domain.withTerminalLocked(cut, Cut.run) else try domain.withLocked(cut, Cut.run);
    }

    /// Bind complete cold companion resources at the final Server address.
    /// No worker is spawned. The closed configured owner supplies every slot
    /// to the shared Gate after this fallible preparation has finished.
    pub fn prepareConfiguredColdResources(self: *LinuxServer, io: std.Io) !void {
        if (self.runtime_inherited_image or !self.inheritedStateConsumedBeforeServices()) return error.InheritedRuntimeRequiresCarry;
        if (self.configured_cold_resources_prepared or self.metrics_server != null or self.webhook_server != null or
            self.native_media.thread != null or self.media_plane.thread != null or self.geo.thread != null)
            return error.RuntimeAlreadyPrepared;
        self.bindFlightPanicTarget();
        self.driveLifecycle(.init);
        self.driveLifecycle(.ready);
        if (self.pending_migrations == null) self.pending_migrations = session_migrate.PendingMigrations.initWithConfig(self.allocator, .{
            .max_entries = self.config.session_max_pending_migrations,
            .max_per_account = self.config.session_max_per_account,
        });
        // These are source-owned cold loads on an unpublished new graph.
        // Inherited constructors must use the mandatory captured state instead.
        self.loadGrants();
        self.loadChanstats();
        self.restoreEventHistoryAtStart();
        try self.geo.prepareColdResources(io);
        if (self.config.media_enabled) {
            try self.configureMediaColdPolicy();
            try self.native_media.prepareColdResources(io, native_media_mod.any_be, self.config.native_media_port);
            errdefer self.native_media.shutdown();
            try self.media_plane.prepareColdResources(io, media_plane_mod.any_be, self.config.media_port);
        }
        errdefer if (self.config.media_enabled) {
            self.media_plane.shutdown();
            self.native_media.shutdown();
        };
        try self.prepareMediaRoutingOwner();
        errdefer self.rollbackPreparedMediaRouting();
        if (self.config.metrics_port != 0) {
            try self.refreshMetricsSnapshotFallible();
            self.metrics_server = try metrics_http.MetricsServer.initWithConfig(&self.metrics_snapshot, self.config.metrics_port, .{ .bind_addr = self.config.metrics_bind_addr });
            errdefer {
                self.metrics_server.?.shutdown();
                self.metrics_server = null;
            }
            try self.metrics_server.?.prepareColdResources(io);
        }
        errdefer if (self.metrics_server) |*owner| {
            owner.shutdown();
            self.metrics_server = null;
        };
        if (self.config.webhook_enabled) {
            self.restoreWebhooksAtStart();
            self.webhook_server = try webhook_http.WebhookServer.init(&self.webhook_store, .{ .ctx = self, .submit = webhookSubmit }, self.config.webhook_port, .{
                .bind_addr = self.config.webhook_bind_addr,
                .handler = .{ .max_body = self.config.webhook_max_body, .rate = self.webhookRate() },
            });
            errdefer {
                self.webhook_server.?.shutdown();
                self.webhook_server = null;
            }
            try self.webhook_server.?.prepareColdResources(io);
        }
        errdefer if (self.webhook_server) |*owner| {
            owner.shutdown();
            self.webhook_server = null;
        };
        if (self.history_https) |*owner| try owner.prepareColdResources(io);
        self.configured_cold_resources_prepared = true;
    }

    /// Validate actual cold resource owners and callback lifetimes at the
    /// prepared cut. These checks never manufacture an activation receipt.
    pub fn requireConfiguredColdResources(self: *LinuxServer) !void {
        const owner_identity: *anyopaque = @ptrCast(self);
        if (!self.configured_cold_resources_prepared or self.runtime_inherited_image) return error.ConfiguredResourcesNotPrepared;
        if ((self.config.metrics_port != 0) != (self.metrics_server != null) or
            self.config.webhook_enabled != (self.webhook_server != null)) return error.ConfiguredOwnerMismatch;
        if (self.geo.opts.weather_enabled != self.config.geo_enabled or
            self.geo.opts.news_enabled != self.config.geo_enabled or
            self.geo.opts.news_insecure_tls != self.config.geo_news_insecure_tls or
            !std.mem.eql(u8, self.geo.opts.news_cache_dir, self.config.geo_news_cache_dir) or
            self.geo.opts.max_headlines != @min(self.config.news_count, 5)) return error.ConfiguredOwnerMismatch;
        if (self.metrics_server) |*owner| {
            if (owner.snapshot != &self.metrics_snapshot or owner.config.bind_addr != self.config.metrics_bind_addr or
                owner.port != self.config.metrics_port or owner.thread != null) return error.ConfiguredOwnerMismatch;
            _ = try metrics_http.observeListener(owner.listen_fd);
        }
        if (self.webhook_server) |*owner| {
            if (owner.store != &self.webhook_store or owner.sink.ctx != owner_identity or owner.sink.submit != webhookSubmit or
                owner.config.bind_addr != self.config.webhook_bind_addr or owner.handler.max_body != self.config.webhook_max_body or
                !std.meta.eql(owner.handler.rate, self.webhookRate()) or owner.port == 0 or
                (self.config.webhook_port != 0 and owner.port != self.config.webhook_port) or owner.thread != null)
                return error.ConfiguredOwnerMismatch;
            _ = try metrics_http.observeListener(owner.listen_fd);
        }
        if (self.history_https) |*owner| {
            if (owner.reader.ptr != owner_identity or owner.reader.readFn != historyHttpsRead or owner.thread != null) return error.ConfiguredOwnerMismatch;
            _ = try metrics_http.observeListener(owner.listen_fd);
        }
        // Callback presence alone is insufficient. The original source-issued
        // Domain registrations and funded FIFO must still belong to this graph.
        const routing_owner = mediaRoutingBacking(self.media_routing_owner orelse return error.ConfiguredOwnerMismatch);
        if (routing_owner.server != self or self.native_media.routing_domain != routing_owner.domain or
            self.media_plane.routing_domain != routing_owner.domain or
            self.native_media.routing_binding != routing_owner.native_binding or
            self.media_plane.routing_binding != routing_owner.webrtc_binding or
            routing_owner.native_binding == null or routing_owner.webrtc_binding == null or
            routing_owner.queue_retired != !self.config.media_enabled or
            (if (self.media_plane.routing_egress) |queue| @as(*const anyopaque, @ptrCast(queue)) else null) != routing_owner.prepared_egress or
            self.config.media_enabled != (routing_owner.prepared_egress != null)) return error.ConfiguredOwnerMismatch;
        const RoutingRelation = struct {
            owner: *MediaRoutingBacking,
            fn require(scope: *media_routing.Locked, ctx: @This()) !void {
                try ctx.owner.domain.requireNativeBindingLocked(scope, ctx.owner.native_binding.?, &ctx.owner.server.native_media);
                try ctx.owner.domain.requireWebrtcBindingLocked(scope, ctx.owner.webrtc_binding.?, &ctx.owner.server.media_plane);
            }
        };
        try routing_owner.domain.withLocked(RoutingRelation{ .owner = routing_owner }, RoutingRelation.require);
        if (self.config.media_enabled) {
            const native_cross = self.native_media.cross orelse return error.ConfiguredOwnerMismatch;
            const rtp_cross = self.media_plane.cross orelse return error.ConfiguredOwnerMismatch;
            if (native_cross.ctx != owner_identity or native_cross.on_native_frame != bridgeOnNativeFrame or
                native_cross.on_native_feedback != bridgeOnNativeFeedback or rtp_cross.ctx != owner_identity or
                rtp_cross.on_rtp_frame != bridgeOnRtpFrame or rtp_cross.on_rtcp_feedback != bridgeOnRtcpFeedback or
                self.native_media.thread != null or self.media_plane.thread != null or
                self.native_media.max_frame_bytes != @min(self.config.media_max_frame_bytes, @as(u64, native_media_mod.max_datagram)) or
                self.media_plane.max_frame_bytes != @min(self.config.media_max_frame_bytes, @as(u64, media_plane_mod.max_datagram)) or
                self.native_media.max_upload_bytes != self.config.media_max_upload_bytes or
                self.media_plane.max_upload_bytes != self.config.media_max_upload_bytes or
                self.native_media.max_participants != @min(self.config.media_max_participants, native_media_mod.max_call_participants) or
                self.native_media.require_mac != self.config.native_media_require_mac or !self.native_media.mac_key_configured or
                !std.crypto.timing_safe.eql([16]u8, self.native_media.mac_stream_key, self.native_stream_key) or
                self.media_plane.dtls_requested != self.config.media_dtls_srtp or
                self.media_plane.dtls13_requested != self.config.media_dtls13) return error.ConfiguredOwnerMismatch;
            const expected_stun: ?media_plane_mod.TransportAddress = if (self.config.media_stun_port == 0) null else blk: {
                const address = parseIp4(self.config.media_stun_host) orelse return error.InvalidMediaStunAddress;
                break :blk try media_plane_mod.TransportAddress.fromBytes(&address, self.config.media_stun_port);
            };
            if (!std.meta.eql(expected_stun, self.media_plane.stun_server)) return error.ConfiguredOwnerMismatch;
            const native_socket = if (self.native_media.socket) |*socket| socket else return error.ConfiguredOwnerMismatch;
            const media_socket = if (self.media_plane.socket) |*socket| socket else return error.ConfiguredOwnerMismatch;
            const native_observed = try native_socket.capture();
            const media_observed = try media_socket.capture();
            if (native_observed.address_be != native_media_mod.any_be or media_observed.address_be != media_plane_mod.any_be or
                native_observed.port != self.native_media.port or media_observed.port != self.media_plane.port or
                (self.config.native_media_port != 0 and native_observed.port != self.config.native_media_port) or
                (self.config.media_port != 0 and media_observed.port != self.config.media_port)) return error.ConfiguredOwnerMismatch;
        }
    }

    fn inheritedStateConsumedBeforeServices(self: *const LinuxServer) bool {
        return self.config.resume_arena_fd == null and
            self.config.native_arena_bytes == null and
            self.config.native_adopt_barrier == null and
            (builtin.os.tag != .openbsd or self.config.native_listener_manifest.len == 0) and
            !self.config.inherited_state_fd_manifest_present;
    }

    /// Stand up the live Prometheus `/metrics` HTTP listener when configured.
    /// Loopback-by-default and read-only; a bind/spawn failure logs and the
    /// daemon keeps serving IRC (metrics are non-essential). Seed the snapshot
    /// once so a scrape before the first stats tick returns valid (if sparse)
    /// exposition text instead of an empty body.
    fn startMetrics(self: *LinuxServer) void {
        if (self.config.metrics_port == 0) return;
        // A native successor has already imported and parked this exact owner.
        if (self.metrics_server != null) return;
        self.refreshMetricsSnapshot();
        self.metrics_server = metrics_http.MetricsServer.initWithConfig(
            &self.metrics_snapshot,
            self.config.metrics_port,
            .{ .bind_addr = self.config.metrics_bind_addr },
        ) catch |e| {
            srvLog("onyx-server: /metrics endpoint disabled ({s})\n", .{@errorName(e)});
            return;
        };
        if (comptime builtin.os.tag == .windows) {
            self.metrics_server.?.prepareColdResources(self.config.crypto_io orelse @panic("Windows metrics requires configured I/O")) catch |e| {
                srvLog("onyx-server: /metrics endpoint disabled ({s})\n", .{@errorName(e)});
                self.metrics_server.?.shutdown();
                self.metrics_server = null;
                return;
            };
        }
        // Spawn on the stored field so the accept loop's `self` pointer is stable
        // for the listener thread's lifetime.
        self.metrics_server.?.spawn() catch |e| {
            srvLog("onyx-server: /metrics endpoint disabled ({s})\n", .{@errorName(e)});
            self.metrics_server.?.shutdown();
            self.metrics_server = null;
            return;
        };
        srvLog("onyx-server: /metrics on TCP :{d}\n", .{self.metrics_server.?.port});
    }

    /// Render the current Prometheus exposition text and publish it into the
    /// mutex-guarded snapshot. Called from the stats cadence (the only writer)
    /// and once at startup. Best-effort: a render/alloc failure leaves the prior
    /// snapshot intact so a scrape returns stale-but-valid data.
    fn refreshMetricsSnapshot(self: *LinuxServer) void {
        self.refreshMetricsSnapshotFallible() catch return;
    }
    fn refreshMetricsSnapshotFallible(self: *LinuxServer) !void {
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(self.allocator);
        if (self.isMaintenanceReactor()) self.latency_stats.mergeShards();
        try self.stats.writePrometheus(self.allocator, &out);
        try self.latency_stats.writePrometheus(self.allocator, &out);
        try self.writeNodeHealthPrometheus(self.allocator, &out);
        try self.writeReactorAcceptPrometheus(self.allocator, &out);
        try self.peer_health.writePrometheus(self.allocator, &out);
        try self.writeE2eeGroupPrometheus(self.allocator, &out);
        const webpush_dropped: usize = if (self.webpush_worker) |worker| worker.dropped.load(.monotonic) else 0;
        try webpush_mod.appendDroppedSample(&out, self.allocator, webpush_dropped);
        try self.metrics_snapshot.set(out.items);
    }

    fn writePromGauge(
        allocator: std.mem.Allocator,
        out: *std.ArrayList(u8),
        name: []const u8,
        help: []const u8,
        value: anytype,
    ) !void {
        try out.print(allocator, "# HELP {s} {s}\n", .{ name, help });
        try out.print(allocator, "# TYPE {s} gauge\n", .{name});
        try out.print(allocator, "{s} {d}\n", .{ name, value });
    }

    fn writeNodeHealthPrometheus(self: *LinuxServer, allocator: std.mem.Allocator, out: *std.ArrayList(u8)) !void {
        const health = self.currentNodeHealth();
        try writePromGauge(allocator, out, "onyx_mesh_quorum", "Whether this node currently holds mesh quorum (1=yes, 0=no)", @as(u8, if (health.mesh_quorum) 1 else 0));
        try writePromGauge(allocator, out, "onyx_mesh_partitioned", "Whether this node sees a mesh partition (1=yes, 0=no)", @as(u8, if (health.mesh_partitioned) 1 else 0));
        try writePromGauge(allocator, out, "onyx_mesh_components", "Mesh connected components known to this node", health.mesh_components);
        try writePromGauge(allocator, out, "onyx_mesh_peers_up", "Mesh peers currently established from this node", health.mesh_peers_up);
        try writePromGauge(allocator, out, "onyx_mesh_peers_total", "Mesh peers tracked by this node", health.mesh_peers_total);
    }

    fn writeReactorAcceptPrometheus(self: *LinuxServer, allocator: std.mem.Allocator, out: *std.ArrayList(u8)) !void {
        try out.appendSlice(allocator, "# HELP onyx_reactor_accepts_total Sockets admitted by reactor shard\n" ++
            "# TYPE onyx_reactor_accepts_total counter\n");
        for (self.reactors, 0..) |*reactor, shard| {
            try out.print(allocator, "onyx_reactor_accepts_total{{shard=\"{d}\"}} {d}\n", .{
                shard,
                reactor.accepted_count.load(.acquire),
            });
        }
    }

    const E2eeGroupOperationalState = struct {
        authoring_enabled: bool,
        custody: usize,
        receipts: usize,
        pending: usize,
        current_peers: usize,
        required_peers: usize,

        fn activationReady(self: E2eeGroupOperationalState) bool {
            // Solo (no external-mesh expectation) is ready at 0/0. Mesh-capable
            // nodes never reach 0/0: e2eeGroupPeerReadiness synthesizes a
            // required peer so mixed-fleet re-enable stays fail-closed.
            return self.current_peers == self.required_peers;
        }
    };

    const E2eeGroupPeerReadiness = struct {
        current: usize,
        required: usize,
    };

    /// True when this process expects at least one external mesh neighbor for
    /// E2EEGROUP current-capability (listen, dial targets, or trust roots).
    /// A single-node roster alone is not an external-peer expectation.
    fn e2eeGroupExpectsExternalPeers(self: *const LinuxServer) bool {
        return self.config.s2s_port != 0 or
            self.config.mesh_connect.len != 0 or
            self.config.mesh_trust_roots.len != 0;
    }

    /// Mesh-capable nodes must never report activation-ready at 0/0 (inbound-
    /// only listen with the peer down, trust roots configured but no live
    /// link, dial list empty while S2S is enabled). A synthetic required peer
    /// keeps ON fail-closed without naming peers or allocating.
    fn e2eeGroupReadinessFailClosed(
        self: *const LinuxServer,
        readiness: E2eeGroupPeerReadiness,
    ) E2eeGroupPeerReadiness {
        if (readiness.required == 0 and self.e2eeGroupExpectsExternalPeers()) {
            return .{ .current = readiness.current, .required = 1 };
        }
        return readiness;
    }

    fn e2eeGroupPeerReadiness(self: *LinuxServer) E2eeGroupPeerReadiness {
        // A configured node-key roster is the strongest direct-neighbor truth:
        // every non-local member must have one established current-capable link.
        if (self.relay_v2_required_nodes.len != 0) {
            var required: usize = 0;
            var current: usize = 0;
            for (self.relay_v2_required_nodes) |required_node| {
                if (required_node == self.config.node_id) continue;
                required += 1;
                var ready = false;
                for (self.reactors) |*reactor| {
                    var it = reactor.clients.iterator();
                    while (it.next()) |entry| {
                        if (!entry.value.isActiveMeshPeer()) continue;
                        const link = entry.value.s2s_secured orelse continue;
                        if (!link.established() or !link.supportsE2eeGroup()) continue;
                        if (link.remoteNodeId() == required_node) {
                            ready = true;
                            break;
                        }
                    }
                    if (ready) break;
                }
                if (ready) current += 1;
            }
            return self.e2eeGroupReadinessFailClosed(.{ .current = current, .required = required });
        }

        // TOFU has no offline node-id roster. Use every presently authenticated
        // direct node plus the configured outbound dial count as the closest
        // fail-closed truth: a missing dial contributes required-but-not-current,
        // and a live plaintext/pre-current peer contributes direct-but-not-current.
        var nodes: [64]u64 = @splat(0);
        var capable: [64]bool = @splat(false);
        var node_len: usize = 0;
        var overflow = false;
        const Remember = struct {
            fn peer(
                seen_nodes: *[64]u64,
                seen_capable: *[64]bool,
                seen_len: *usize,
                overflowed: *bool,
                node: u64,
                is_capable: bool,
            ) void {
                if (node == 0) return;
                for (seen_nodes[0..seen_len.*], 0..) |known, i| {
                    if (known != node) continue;
                    seen_capable[i] = seen_capable[i] or is_capable;
                    return;
                }
                if (seen_len.* == seen_nodes.len) {
                    overflowed.* = true;
                    return;
                }
                seen_nodes[seen_len.*] = node;
                seen_capable[seen_len.*] = is_capable;
                seen_len.* += 1;
            }
        };
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                if (!entry.value.isActiveMeshPeer()) continue;
                if (entry.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    Remember.peer(
                        &nodes,
                        &capable,
                        &node_len,
                        &overflow,
                        link.remoteNodeId() orelse continue,
                        link.supportsE2eeGroup(),
                    );
                } else if (entry.value.s2s) |link| {
                    if (!link.established()) continue;
                    Remember.peer(
                        &nodes,
                        &capable,
                        &node_len,
                        &overflow,
                        link.remoteNodeId() orelse continue,
                        false,
                    );
                }
            }
        }
        var current: usize = 0;
        for (capable[0..node_len]) |is_capable| current += @intFromBool(is_capable);
        return self.e2eeGroupReadinessFailClosed(.{
            .current = current,
            // Saturating the bounded observation set must fail closed. One
            // synthetic required peer keeps activation false without exposing
            // peer identities or allocating on the operator/metrics path.
            .required = @max(node_len + @intFromBool(overflow), self.config.mesh_connect.len),
        });
    }

    fn e2eeGroupOperationalState(self: *LinuxServer) E2eeGroupOperationalState {
        const authoring_enabled = self.e2ee_group_local_authoring_enabled.load(.acquire);
        const peers = self.e2eeGroupPeerReadiness();
        lockSpin(&self.e2ee_group_mesh_mu);
        defer self.e2ee_group_mesh_mu.unlock();
        return .{
            .authoring_enabled = authoring_enabled,
            .custody = self.e2ee_group_mesh_authority.custodyLen(),
            .receipts = self.e2ee_group_mesh_authority.receiptLen(),
            .pending = self.e2ee_group_mesh_authority.pendingLen(),
            .current_peers = peers.current,
            .required_peers = peers.required,
        };
    }

    /// Export only count-level E2EEGROUP delivery authority. The authority owns
    /// opaque payloads, exact relay IDs, and origin keys; none of those cross
    /// this operational boundary. One mutex snapshot keeps the three gauges
    /// mutually coherent for a cold-restart drain decision.
    fn writeE2eeGroupPrometheus(self: *LinuxServer, allocator: std.mem.Allocator, out: *std.ArrayList(u8)) !void {
        const state = self.e2eeGroupOperationalState();
        try writePromGauge(allocator, out, "onyx_e2ee_group_local_authoring_enabled", "Whether this node accepts new locally authored E2EEGROUP controls (1=yes, 0=quiesced)", @as(u8, if (state.authoring_enabled) 1 else 0));
        try writePromGauge(allocator, out, "onyx_e2ee_group_current_capable_peers", "Direct mesh peers established with current E2EEGROUP support", state.current_peers);
        try writePromGauge(allocator, out, "onyx_e2ee_group_required_peers", "Configured or authenticated direct mesh peers required before authoring resumes", state.required_peers);
        try writePromGauge(allocator, out, "onyx_e2ee_group_activation_ready", "Whether every required direct mesh peer is current-capable (1=yes, 0=no)", @as(u8, if (state.activationReady()) 1 else 0));
        try writePromGauge(allocator, out, "onyx_e2ee_group_hop_custody", "Exact E2EEGROUP hop wires awaiting peer ACK", state.custody);
        try writePromGauge(allocator, out, "onyx_e2ee_group_ingress_receipts", "E2EEGROUP ingress receipts awaiting ACK_CONFIRM", state.receipts);
        try writePromGauge(allocator, out, "onyx_e2ee_group_pending", "Unsettled exact E2EEGROUP relay identities", state.pending);
    }

    /// The per-webhook rate policy assembled from config.
    fn webhookRate(self: *const LinuxServer) webhook_mod.RateConfig {
        return .{ .per_min = self.config.webhook_rate_per_min, .burst = self.config.webhook_rate_burst };
    }

    /// Stand up the plaintext webhook HTTP listener when enabled + a port is set.
    /// Loopback-by-default; a bind/spawn failure logs and the daemon keeps serving
    /// IRC. Restores persisted bindings first so a POST right after boot resolves.
    fn startWebhook(self: *LinuxServer) void {
        // `webhook_enabled` is the sole gate; a 0 port binds an OS-ephemeral one
        // (matching the IRC listener). When disabled this is a no-op and the
        // daemon is byte-identical to a build without the feature.
        if (!self.config.webhook_enabled) return;
        // The Windows Helix candidate has already adopted the exact store and
        // bound listener. Its worker remains parked until COMMIT.
        if (self.webhook_server != null) return;
        if (self.config.webhook_store_path.len == 0) {
            srvLog("onyx-server: webhook endpoint has no [webhook] store_path — bindings will NOT survive a restart or USR2 upgrade\n", .{});
        }
        self.restoreWebhooksAtStart();
        const sink = webhook_mod.PostSink{ .ctx = self, .submit = webhookSubmit };
        self.webhook_server = webhook_http.WebhookServer.init(
            &self.webhook_store,
            sink,
            self.config.webhook_port,
            .{
                .bind_addr = self.config.webhook_bind_addr,
                .handler = .{
                    .max_body = self.config.webhook_max_body,
                    .rate = self.webhookRate(),
                },
            },
        ) catch |e| {
            srvLog("onyx-server: webhook endpoint disabled ({s})\n", .{@errorName(e)});
            return;
        };
        if (comptime builtin.os.tag == .windows) {
            self.webhook_server.?.prepareColdResources(self.config.crypto_io orelse @panic("Windows webhook requires configured I/O")) catch |e| {
                srvLog("onyx-server: webhook endpoint disabled ({s})\n", .{@errorName(e)});
                self.webhook_server.?.shutdown();
                self.webhook_server = null;
                return;
            };
        }
        self.webhook_server.?.spawn() catch |e| {
            srvLog("onyx-server: webhook endpoint disabled ({s})\n", .{@errorName(e)});
            self.webhook_server.?.shutdown();
            self.webhook_server = null;
            return;
        };
        srvLog("onyx-server: webhook endpoint on TCP :{d}\n", .{self.webhook_server.?.port});
    }

    /// Construct the Windows successor's inert webhook owner at the final
    /// Server address. The authenticated transfer owns the listener socket;
    /// the mandatory checkpoint has already restored the binding/rate store.
    pub fn stageWindowsInheritedWebhook(self: *LinuxServer, transfer: *helix_native_windows_socket.Transfer, carry: *const webhook_http.Snapshot, io: std.Io) !void {
        if (comptime builtin.os.tag != .windows) return error.Unsupported;
        if (!self.config.webhook_enabled or self.webhook_server != null) return error.InvalidRuntime;
        const sink = webhook_mod.PostSink{ .ctx = self, .submit = webhookSubmit };
        self.webhook_server = try webhook_http.WebhookServer.initTransferred(
            &self.webhook_store,
            sink,
            transfer,
            carry,
            .{
                .bind_addr = self.config.webhook_bind_addr,
                .handler = .{
                    .max_body = self.config.webhook_max_body,
                    .rate = self.webhookRate(),
                },
            },
        );
        errdefer {
            self.webhook_server.?.shutdown();
            self.webhook_server = null;
        }
        try self.webhook_server.?.prepareColdResources(io);
    }

    /// `PostSink` callback: enqueue a validated post for reactor 0 and nudge it.
    /// Runs on the HTTP listener thread — it only touches the lock-free MPMC queue
    /// and the (thread-safe) wake eventfd, never any reactor-owned state. Returns
    /// false when the queue is full so the HTTP handler answers 429.
    fn webhookSubmit(ctx: *anyopaque, post: *const webhook_mod.PendingPost) bool {
        const self: *LinuxServer = @ptrCast(@alignCast(ctx));
        if (!self.webhook_posts.push(post.*)) return false;
        // Wake reactor 0 (it keeps a poll on its wake fd armed each loop) so the
        // post is drained promptly rather than on the next unrelated completion.
        if (self.reactors.len > 0) {
            if (self.reactors[0].wake) |*w| w.wake();
        }
        return true;
    }

    /// Drain pending webhook posts on reactor 0 and fan each into its channel.
    /// Called every `runOnce` (belt-and-suspenders alongside the wake). Bounded
    /// per iteration so a flood cannot starve normal I/O.
    fn drainWebhookPosts(self: *LinuxServer) void {
        if (self.webhook_server == null) return;
        if (self.reactors.len == 0 or self.rx() != &self.reactors[0]) return;
        var drained: usize = 0;
        while (drained < 64) : (drained += 1) {
            const post = self.webhook_posts.pop() orelse break;
            // Injection reads shared world state and drives delivery, so serialize
            // it under the same coarse `world.lockWrite` that `onCompletion` holds
            // around normal command processing (Phase B multithreading). The
            // lock is taken only when a post is actually present, so the common
            // empty-queue path stays lock-free.
            self.world.lockWrite();
            self.injectWebhookPost(&post);
            self.world.unlockWrite();
        }
    }

    /// Producer-barrier drain for Helix. `WebhookServer.pause()` has already
    /// joined the HTTP thread, all socket owners are quiesced, and the caller
    /// holds World. Rebind to reactor 0 so injected deliveries use the same
    /// ownership/routing geometry as the ordinary on-thread drain, then empty
    /// the finite queue completely before the authoritative fixed point.
    fn drainWebhookPostsForUpgradeLocked(self: *LinuxServer) void {
        if (self.reactors.len == 0) return;
        const saved_reactor = current_reactor;
        defer current_reactor = saved_reactor;
        current_reactor = &self.reactors[0];
        while (self.webhook_posts.pop()) |post| self.injectWebhookPost(&post);
    }

    fn publishWebhookResumeHealth(self: *LinuxServer, world_locked: bool, severity: event_spine.EventSeverity, msg: []const u8) void {
        if (world_locked) {
            self.publishOperEvent(.oper_action, severity, msg) catch {};
            return;
        }
        self.world.lockWrite();
        self.publishOperEvent(.oper_action, severity, msg) catch {};
        self.world.unlockWrite();
    }

    /// Try to restart a producer paused for Helix failure unwind. Never accept a
    /// new HTTP post while an older socket-quiesce generation is still RESUMING:
    /// that would publish behind a state boundary whose owners are fail-closed.
    /// Spawn failures remain scheduled for reactor 0's timer instead of turning
    /// one transient resource error into a permanent webhook outage.
    fn tryResumeWebhookAfterUpgrade(self: *LinuxServer, world_locked: bool) void {
        var blocked = false;
        var missing = false;
        var resume_error: ?anyerror = null;
        lockSpin(&self.webhook_lifecycle_gate);
        if (self.webhook_upgrade_pause_active.load(.acquire) or
            self.upgrade_quiesce_shard.load(.acquire) != no_quiesce_shard)
        {
            blocked = true;
        } else if (self.webhook_server) |*ws| {
            ws.resumeServing() catch |e| {
                resume_error = e;
            };
        } else {
            missing = true;
        }
        self.webhook_lifecycle_gate.unlock();

        // Health publication happens only after releasing the lifecycle gate;
        // CompletionHandler may already hold World on timer retry, and taking
        // the two locks in opposite orders would deadlock pause/unwind.
        if (blocked) {
            self.webhook_resume_pending.store(true, .release);
            const old = self.webhook_resume_attempts.fetchAdd(1, .acq_rel);
            if (old == 0 or old % 64 == 63) {
                srvLog("onyx-server: CRITICAL webhook listener remains paused: UPGRADE owners have not fully resumed\n", .{});
            }
            return;
        }
        if (missing) {
            self.webhook_resume_pending.store(false, .release);
            self.webhook_resume_attempts.store(0, .release);
            return;
        }
        if (resume_error) |e| {
            self.webhook_resume_pending.store(true, .release);
            const old = self.webhook_resume_attempts.fetchAdd(1, .acq_rel);
            if (old == 0 or old % 64 == 63) {
                srvLog("onyx-server: CRITICAL webhook listener resume failed ({s}); retry scheduled\n", .{@errorName(e)});
            }
            if (old == 0)
                self.publishWebhookResumeHealth(world_locked, .critical, "Webhook listener resume failed after UPGRADE; bounded timer retry scheduled");
            return;
        }
        const attempts = self.webhook_resume_attempts.swap(0, .acq_rel);
        self.webhook_resume_pending.store(false, .release);
        if (attempts != 0) {
            srvLog("onyx-server: webhook listener resumed after {d} deferred attempt(s)\n", .{attempts});
            self.publishWebhookResumeHealth(world_locked, .info, "Webhook listener recovered after UPGRADE failure unwind");
        }
    }

    fn retryWebhookResumeIfPending(self: *LinuxServer) void {
        if (!self.isMaintenanceReactor()) return;
        if (!self.webhook_resume_pending.load(.acquire)) return;
        // CompletionHandler holds World around onTimerTick.
        self.tryResumeWebhookAfterUpgrade(true);
    }

    /// Fan a validated, pre-sanitised webhook post into its bound channel as a
    /// synthetic bot sender, mirror it to the mesh, and record it in CHATHISTORY.
    /// Runs on reactor 0 (the delivery path routes cross-shard via `deliverTagged`).
    /// Every field is already CR/LF/control-free, so the wire cannot be corrupted.
    fn injectWebhookPost(self: *LinuxServer, post: *const webhook_mod.PendingPost) void {
        const chan = post.channel();
        if (!world_model.isChannelName(chan)) return;
        if (!self.world.channelExists(chan)) return;
        // Respect channel modes: a webhook bot holds no membership/voice, so a
        // moderated (+m) channel drops the post (the HTTP request already 204'd).
        if (self.world.channelHasFlag(chan, .moderated)) return;

        const nick = post.nick();
        if (nick.len == 0) return;
        // Synthetic sender prefix `<nick>!webhook@<server>`. `nick` is sanitised
        // (no space / CR / LF), so the prefix can never split or forge a line.
        var prefix_buf: [webhook_mod.max_nick + 96]u8 = undefined;
        const prefix = std.fmt.bufPrint(&prefix_buf, "{s}!webhook@{s}", .{
            nick, self.serverName(),
        }) catch return;

        var lines = std.mem.splitScalar(u8, post.body(), '\n');
        while (lines.next()) |line| {
            if (line.len == 0) continue;
            // Allocate one mesh event identity BEFORE either delivery leg. The
            // same authenticated (origin, hlc) deterministically produces the
            // local + remote msgid/time, so a webhook post is one event across
            // every reusable client instead of a local random id plus a second
            // mesh identity.
            const hlc = self.nextMeshHlc();
            const event_time_ms = mesh_clock_mod.MeshClock.physicalOf(hlc);
            var msgid_buf: [msgid_mod.id_len]u8 = undefined;
            const message_id = msgid_mod.fromMeshEvent(self.config.node_id, hlc, &msgid_buf);
            var time_buf: [40]u8 = undefined;
            const tags = MsgTags{
                .time_value = serverTimeValueAt(&time_buf, event_time_ms),
                .account = null,
                .client_tags = post.clientTags(),
                .msgid = message_id,
                .is_bot = true,
            };
            var msg_buf: [default_reply_bytes]u8 = undefined;
            const msg = formatMessage(&msg_buf, prefix, "PRIVMSG", &.{chan}, line) catch continue;
            self.broadcastChannelTagged(chan, tags, msg, null, .ordinary) catch {};

            // Mesh relay so remote members of `chan` see the post too. Loop-guarded.
            var relay_msg = s2s_link.RelayMessage{
                .verb = .privmsg,
                .target = chan,
                .source_nick = nick,
                .source_prefix = prefix,
                .account = "",
                .tags = post.clientTags() orelse "",
                .text = line,
                .origin_node = self.config.node_id,
                .hlc = hlc,
            };
            var pk_buf: [message_relay.pubkey_len]u8 = undefined;
            var sig_buf: [message_relay.sig_len]u8 = undefined;
            self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
            if (relay_msg.origin_sig.len != 0)
                _ = self.relay_seen.observe(self.config.node_id, hlc)
            else
                _ = self.relay_seen.observeUnsigned(self.config.node_id, hlc);
            _ = self.relayToPeers(relay_msg, .{ .channel = chan });

            self.recordHistoryRelayAt(chan, prefix, message_id, "PRIVMSG", line, post.clientTags(), event_time_ms);
        }
    }

    /// Persist the webhook binding set to `[webhook] store_path` (best-effort;
    /// mirrors `persistGrants`). Called after every WEBHOOK create/delete so the
    /// file is current before any restart or USR2 hot-upgrade.
    fn persistWebhooks(self: *LinuxServer) void {
        if (self.config.webhook_store_path.len == 0) return;
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(self.allocator);
        self.webhook_store.serialize(self.allocator, &out) catch return;
        writeFileAbs(self.allocator, self.config.webhook_store_path, out.items);
    }

    /// Restore persisted webhook bindings at boot (from `start`). No-op without a
    /// configured path / readable file.
    fn loadWebhooks(self: *LinuxServer) void {
        if (self.config.webhook_store_path.len == 0) return;
        const io = self.config.crypto_io orelse return;
        const text = std.Io.Dir.cwd().readFileAlloc(io, self.config.webhook_store_path, self.allocator, .limited(1 << 20)) catch return;
        defer self.allocator.free(text);
        const restored = self.webhook_store.load(text, self.nowMs(), self.webhookRate());
        if (restored != 0) srvLog("onyx-server: restored {d} webhook binding(s)\n", .{restored});
    }

    fn restoreWebhooksAtStart(self: *LinuxServer) void {
        if (self.inherited_webhook_store_restored) return;
        self.loadWebhooks();
    }

    /// `WEBHOOK CREATE <#channel> [name] | LIST <#channel> | DELETE <id>` —
    /// manage Discord-compatible incoming webhook bindings. Every subcommand that
    /// names a channel is gated on channel-operator status (network opers bypass).
    pub fn handleWebhook(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.config.webhook_enabled) {
            try self.noticeTo(conn, "WEBHOOK: the webhook endpoint is not enabled on this server");
            return;
        }
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"WEBHOOK"}, "Usage: WEBHOOK CREATE <#channel> [name] | LIST <#channel> | DELETE <id>");
            return;
        }
        const params = parsed.paramSlice();
        const sub = params[0];
        if (std.ascii.eqlIgnoreCase(sub, "CREATE")) {
            try self.webhookCreate(id, conn, params);
        } else if (std.ascii.eqlIgnoreCase(sub, "LIST")) {
            try self.webhookList(id, conn, params);
        } else if (std.ascii.eqlIgnoreCase(sub, "DELETE")) {
            try self.webhookDelete(id, conn, params);
        } else {
            try self.noticeTo(conn, "WEBHOOK: unknown subcommand (use CREATE, LIST, or DELETE)");
        }
    }

    /// Channel-op gate for WEBHOOK subcommands: true if the caller is a channel
    /// operator (or a network oper). On failure it queues the appropriate numeric
    /// and returns false. Mirrors the KICK/MODE op predicate.
    fn webhookChannelOpGate(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8) bool {
        if (conn.session.isOper()) return true;
        const mm = self.world.memberModes(channel, worldIdFromClient(id)) orelse {
            queueNumeric(conn, .ERR_NOTONCHANNEL, &.{channel}, "You're not on that channel") catch {};
            return false;
        };
        if (!mm.isOperator()) {
            queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{channel}, "You're not channel operator") catch {};
            return false;
        }
        return true;
    }

    fn webhookCreate(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, params: []const []const u8) !void {
        if (params.len < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"WEBHOOK"}, "Usage: WEBHOOK CREATE <#channel> [name]");
            return;
        }
        const channel = params[1];
        if (!world_model.isChannelName(channel)) {
            try self.noticeTo(conn, "WEBHOOK: that is not a channel name");
            return;
        }
        if (conn.session.account()) |account| {
            if (self.accountIsGatedBot(account)) {
                if (!self.bot_grants.allows(account, .webhook, channel, self.grantNowU64())) {
                    try self.noticeTo(conn, "BOTGRANT: webhook refused");
                    return;
                }
            } else if (!self.webhookChannelOpGate(id, conn, channel)) return;
        } else if (!self.webhookChannelOpGate(id, conn, channel)) return;
        const name = if (params.len >= 3) params[2] else channel;

        var idm: [webhook_mod.id_bytes]u8 = undefined;
        var tkm: [webhook_mod.token_bytes]u8 = undefined;
        secure_fns.randomBytes(&idm);
        secure_fns.randomBytes(&tkm);
        const creator = conn.session.account() orelse conn.session.displayName();
        const now_unix: i64 = @divTrunc(platform.realtimeMillis(), 1000);
        const creds = self.webhook_store.create(channel, name, creator, now_unix, self.nowMs(), self.webhookRate(), idm, tkm) catch |e| {
            const msg = switch (e) {
                error.Full => "WEBHOOK: server webhook limit reached",
                error.ChannelFull => "WEBHOOK: this channel already has the maximum number of webhooks",
                error.BadChannel => "WEBHOOK: invalid channel name",
            };
            try self.noticeTo(conn, msg);
            return;
        };
        self.persistWebhooks();

        var url_buf: [512]u8 = undefined;
        const url = self.webhookUrl(&url_buf, &creds.id, &creds.token);
        var line: [640]u8 = undefined;
        try self.noticeTo(conn, std.fmt.bufPrint(&line, "WEBHOOK: created for {s} — POST Discord webhook JSON to {s}", .{ channel, url }) catch "WEBHOOK: created");
        try self.noticeTo(conn, "WEBHOOK: this URL contains the secret token and is shown only once — store it now.");
    }

    fn webhookList(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, params: []const []const u8) !void {
        if (params.len < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"WEBHOOK"}, "Usage: WEBHOOK LIST <#channel>");
            return;
        }
        const channel = params[1];
        if (!self.webhookChannelOpGate(id, conn, channel)) return;
        var entries: [webhook_mod.max_per_channel]webhook_mod.ListEntry = undefined;
        const n = self.webhook_store.list(channel, &entries);
        if (n == 0) {
            var b: [128]u8 = undefined;
            try self.noticeTo(conn, std.fmt.bufPrint(&b, "WEBHOOK: no webhooks bound to {s}", .{channel}) catch "WEBHOOK: none");
            return;
        }
        for (entries[0..n]) |*e| {
            var b: [320]u8 = undefined;
            // The token is NOT stored in plaintext and is never shown here.
            try self.noticeTo(conn, std.fmt.bufPrint(&b, "WEBHOOK: id={s} name={s} by={s}", .{ e.id, e.name(), e.creator() }) catch continue);
        }
    }

    fn webhookDelete(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, params: []const []const u8) !void {
        if (params.len < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"WEBHOOK"}, "Usage: WEBHOOK DELETE <id>");
            return;
        }
        const wid = params[1];
        var chbuf: [webhook_mod.max_channel]u8 = undefined;
        const channel = self.webhook_store.channelOf(wid, &chbuf) orelse {
            try self.noticeTo(conn, "WEBHOOK: no such webhook id");
            return;
        };
        if (!self.webhookChannelOpGate(id, conn, channel)) return;
        _ = self.webhook_store.remove(wid);
        self.persistWebhooks();
        try self.noticeTo(conn, "WEBHOOK: deleted");
    }

    /// Render the full webhook URL for the CREATE reply. Uses the configured
    /// public base (a reverse-proxy origin) when set; otherwise derives
    /// `http://<bind-ip>:<port>` from the listener config.
    fn webhookUrl(self: *const LinuxServer, buf: []u8, id: []const u8, token: []const u8) []const u8 {
        const base = self.config.webhook_public_base;
        if (base.len != 0) {
            const trimmed = if (base[base.len - 1] == '/') base[0 .. base.len - 1] else base;
            return std.fmt.bufPrint(buf, "{s}/api/webhooks/{s}/{s}", .{ trimmed, id, token }) catch buf[0..0];
        }
        const a = self.config.webhook_bind_addr;
        return std.fmt.bufPrint(buf, "http://{d}.{d}.{d}.{d}:{d}/api/webhooks/{s}/{s}", .{
            (a >> 24) & 0xff, (a >> 16) & 0xff, (a >> 8) & 0xff, a & 0xff, self.config.webhook_port, id, token,
        }) catch buf[0..0];
    }

    fn destroyOutboundWebhooks(self: *LinuxServer) void {
        for (&self.outbound_webhooks) |*slot| self.clearOutboundSlot(slot);
    }

    fn clearOutboundSlot(self: *LinuxServer, slot: *?OutboundWebhook) void {
        if (slot.*) |sub| {
            self.allocator.free(sub.url);
            @memset(sub.secret, 0);
            self.allocator.free(sub.secret);
            slot.* = null;
        }
    }

    fn outboundWebhookCount(self: *const LinuxServer) usize {
        var n: usize = 0;
        for (self.outbound_webhooks) |slot| {
            if (slot != null) n += 1;
        }
        return n;
    }

    /// `OUTHOOK ADD <url> <secret> <categories>` registers a push target.
    /// `DEL` removes one. `LIST` shows URLs and categories, never the secret.
    /// Private, loopback, and link-local targets are refused unless
    /// `webhook_allow_private` is set. Inbound `WEBHOOK` is unchanged.
    pub fn handleOutboundWebhook(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.isOper()) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied- You're not an IRC operator");
            return;
        }
        if (!self.requirePriv(conn, .server_admin)) return;
        const p = parsed.paramSlice();
        if (p.len < 1) {
            try self.noticeTo(conn, "Usage: OUTHOOK ADD <url> <secret> <categories> | DEL <url> | LIST");
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "LIST")) {
            if (self.outboundWebhookCount() == 0) {
                try self.noticeTo(conn, "OUTHOOK: none");
                return;
            }
            for (self.outbound_webhooks) |slot| {
                const sub = slot orelse continue;
                var cats: [256]u8 = undefined;
                const shown = outboundCategoryText(sub.mask, &cats);
                var buf: [default_reply_bytes]u8 = undefined;
                const note = std.fmt.bufPrint(&buf, "OUTHOOK: {s} categories={s}", .{ sub.url, shown }) catch continue;
                try self.noticeTo(conn, note);
            }
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "DEL") or std.ascii.eqlIgnoreCase(p[0], "DELETE")) {
            if (p.len < 2) {
                try self.noticeTo(conn, "Usage: OUTHOOK DEL <url>");
                return;
            }
            for (&self.outbound_webhooks) |*slot| {
                const sub = slot.* orelse continue;
                if (!std.mem.eql(u8, sub.url, p[1])) continue;
                self.clearOutboundSlot(slot);
                _ = self.recordOperAudit(conn.session.displayName(), .other, p[1], "outbound webhook del");
                try self.noticeTo(conn, "OUTHOOK: removed");
                return;
            }
            try self.noticeTo(conn, "OUTHOOK: no such url");
            return;
        }
        if (!std.ascii.eqlIgnoreCase(p[0], "ADD")) {
            try self.noticeTo(conn, "OUTHOOK: subcommand must be ADD, DEL, or LIST");
            return;
        }
        if (p.len < 4) {
            try self.noticeTo(conn, "Usage: OUTHOOK ADD <url> <secret> <categories>");
            return;
        }
        const url = p[1];
        const secret = p[2];
        if (url.len == 0 or url.len > outbound_webhook_url_max or secret.len == 0 or secret.len > outbound_webhook_secret_max) {
            try self.noticeTo(conn, "OUTHOOK: url or secret is empty or too long");
            return;
        }
        const parsed_url = http_fetch.parseUrl(url) catch {
            try self.noticeTo(conn, "OUTHOOK: bad url");
            return;
        };
        if (!self.config.webhook_allow_private and outboundHostPrivate(parsed_url.host)) {
            try self.noticeTo(conn, "OUTHOOK: refusing private or local target");
            return;
        }
        const mask = parseOutboundCategories(p[3]) orelse {
            try self.noticeTo(conn, "OUTHOOK: unknown category");
            return;
        };
        const url_copy = self.allocator.dupe(u8, url) catch {
            try self.noticeTo(conn, "OUTHOOK: out of memory");
            return;
        };
        const secret_copy = self.allocator.dupe(u8, secret) catch {
            self.allocator.free(url_copy);
            try self.noticeTo(conn, "OUTHOOK: out of memory");
            return;
        };
        var replaced = false;
        for (&self.outbound_webhooks) |*slot| {
            const sub = slot.* orelse continue;
            if (!std.mem.eql(u8, sub.url, url)) continue;
            self.clearOutboundSlot(slot);
            slot.* = .{ .url = url_copy, .secret = secret_copy, .mask = mask };
            replaced = true;
            break;
        }
        if (!replaced) {
            var stored = false;
            for (&self.outbound_webhooks) |*slot| {
                if (slot.* != null) continue;
                slot.* = .{ .url = url_copy, .secret = secret_copy, .mask = mask };
                stored = true;
                break;
            }
            if (!stored) {
                self.allocator.free(url_copy);
                @memset(secret_copy, 0);
                self.allocator.free(secret_copy);
                try self.noticeTo(conn, "OUTHOOK: limit reached");
                return;
            }
        }
        _ = self.recordOperAudit(conn.session.displayName(), .other, url, "outbound webhook");
        try self.noticeTo(conn, if (replaced) "OUTHOOK: updated" else "OUTHOOK: registered");
    }

    fn accountIsGatedBot(self: *const LinuxServer, account: []const u8) bool {
        return self.bot_grants.isBot(account) or self.bot_registry.isBot(account);
    }

    fn botChannelSpeakDenied(self: *LinuxServer, conn: *ConnState, target: []const u8) bool {
        if (!world_model.isChannelName(target)) return false;
        const account = conn.session.account() orelse return false;
        if (!self.accountIsGatedBot(account)) return false;
        return !self.bot_grants.allows(account, .speak, target, self.grantNowU64());
    }

    /// `BOTGRANT ADD <account> <speak|webhook|history> <channel> <ttl-seconds>`
    /// grants one scoped action. `DEL` revokes it. `LIST` shows live grants.
    /// The account becomes a bot. The grant is not an oper bit.
    pub fn handleBotGrant(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.isOper()) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied- You're not an IRC operator");
            return;
        }
        if (!self.requirePriv(conn, .server_admin)) return;
        const p = parsed.paramSlice();
        if (p.len < 1) {
            try self.noticeTo(conn, "Usage: BOTGRANT ADD <account> <speak|webhook|history> <channel> <ttl-seconds> | DEL <account> <kind> <channel> | LIST [account]");
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "LIST")) {
            const filter = if (p.len >= 2) p[1] else null;
            var shown: usize = 0;
            const now = self.grantNowU64();
            var live: [bot_grant_snapshot.max_grants]bot_grant_snapshot.GrantView = undefined;
            const n = self.bot_grants.copyLive(now, &live);
            for (live[0..n]) |slot| {
                if (filter) |name| {
                    if (!std.ascii.eqlIgnoreCase(slot.account, name)) continue;
                }
                var buf: [default_reply_bytes]u8 = undefined;
                const note = std.fmt.bufPrint(&buf, "BOTGRANT: {s} {s} {s} expires={d}", .{
                    slot.account,
                    @tagName(slot.kind),
                    slot.scope,
                    slot.expiry_ms,
                }) catch continue;
                try self.noticeTo(conn, note);
                shown += 1;
            }
            if (shown == 0) try self.noticeTo(conn, "BOTGRANT: none");
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "DEL") or std.ascii.eqlIgnoreCase(p[0], "DELETE")) {
            if (p.len < 4) {
                try self.noticeTo(conn, "Usage: BOTGRANT DEL <account> <speak|webhook|history> <channel>");
                return;
            }
            const kind = bot_grant_snapshot.Kind.parse(p[2]) orelse {
                try self.noticeTo(conn, "BOTGRANT: kind must be speak, webhook, or history");
                return;
            };
            if (!self.bot_grants.remove(p[1], kind, p[3])) {
                try self.noticeTo(conn, "BOTGRANT: no such grant");
                return;
            }
            _ = self.recordOperAudit(conn.session.displayName(), .other, p[1], "bot grant del");
            try self.noticeTo(conn, "BOTGRANT: revoked");
            return;
        }
        if (!std.ascii.eqlIgnoreCase(p[0], "ADD")) {
            try self.noticeTo(conn, "Usage: BOTGRANT ADD <account> <speak|webhook|history> <channel> <ttl-seconds> | DEL <account> <kind> <channel> | LIST [account]");
            return;
        }
        if (p.len < 5) {
            try self.noticeTo(conn, "Usage: BOTGRANT ADD <account> <speak|webhook|history> <channel> <ttl-seconds>");
            return;
        }
        const account = p[1];
        const kind = bot_grant_snapshot.Kind.parse(p[2]) orelse {
            try self.noticeTo(conn, "BOTGRANT: kind must be speak, webhook, or history");
            return;
        };
        const scope = p[3];
        if (account.len == 0 or account.len > bot_grant_snapshot.max_account) {
            try self.noticeTo(conn, "BOTGRANT: account name is empty or too long");
            return;
        }
        if (!world_model.isChannelName(scope) or scope.len > bot_grant_snapshot.max_scope) {
            try self.noticeTo(conn, "BOTGRANT: scope must be a channel name");
            return;
        }
        const ttl = std.fmt.parseInt(u64, p[4], 10) catch {
            try self.noticeTo(conn, "BOTGRANT: ttl must be a positive number of seconds");
            return;
        };
        if (ttl == 0 or ttl > std.math.maxInt(u64) / 1000) {
            try self.noticeTo(conn, "BOTGRANT: ttl must be a positive number of seconds");
            return;
        }
        const now = self.grantNowU64();
        const expiry = std.math.add(u64, now, ttl * 1000) catch {
            try self.noticeTo(conn, "BOTGRANT: ttl is too large");
            return;
        };
        self.bot_registry.register(account, .{}) catch {
            try self.noticeTo(conn, "BOTGRANT: could not register the bot account");
            return;
        };
        self.bot_grants.upsert(account, kind, scope, expiry, now) catch |err| {
            const msg: []const u8 = switch (err) {
                error.TooMany => "BOTGRANT: grant table is full",
                else => "BOTGRANT: rejected",
            };
            try self.noticeTo(conn, msg);
            return;
        };
        _ = self.recordOperAudit(conn.session.displayName(), .other, account, "bot grant");
        try self.noticeTo(conn, "BOTGRANT: added");
    }

    /// Push one admitted oper event to every subscription whose mask includes
    /// `category`. Each delivery signs the body and retries up to the cap.
    fn deliverOutboundWebhooks(self: *LinuxServer, category: event_spine.EventCategory, severity: event_spine.EventSeverity, message: []const u8) void {
        var body_buf: [1024]u8 = undefined;
        const body = formatOutboundBody(&body_buf, category, severity, self.serverName(), message) orelse {
            self.outbound_webhook_dropped += 1;
            return;
        };
        for (self.outbound_webhooks) |slot| {
            const sub = slot orelse continue;
            if (!sub.mask.contains(category)) continue;
            self.postOutboundWebhook(sub, body);
        }
    }

    fn postOutboundWebhook(self: *LinuxServer, sub: OutboundWebhook, body: []const u8) void {
        const parsed = http_fetch.parseUrl(sub.url) catch {
            self.outbound_webhook_dropped += 1;
            return;
        };
        const addr = self.resolveOutboundWebhookAddress(parsed.host, parsed.port) catch {
            self.outbound_webhook_dropped += 1;
            return;
        };
        const test_anchors = self.outboundTrustOverrideForTest();
        var trust: ?outbound_trust.Store = if (parsed.tls and test_anchors == null)
            self.loadOutboundTrust() catch {
                self.outbound_webhook_dropped += 1;
                return;
            }
        else
            null;
        defer if (trust) |*store| store.deinit();
        var sig_buf: [71]u8 = undefined;
        const signature = outboundSignature(sub.secret, body, &sig_buf);
        var opts = http_fetch.Options{
            .connect_timeout_ms = 400,
            .recv_timeout_ms = 400,
            .max_response_bytes = 4096,
        };
        opts.trust_anchors = if (test_anchors) |anchors| anchors else if (trust) |*store| store.anchors() else &.{};
        opts.disallowed_certs = if (trust) |*store| store.disallowed() else &.{};
        opts.windows_chain_policy = builtin.os.tag == .windows and trust != null;
        var selected_addr = addr;
        var tried_aaaa = false;
        const hostname = outboundHostIsHostname(parsed.host, parsed.port);
        var attempt: u8 = 0;
        while (attempt < outbound_webhook_attempt_cap) : (attempt += 1) {
            var connected = false;
            opts.connect_established = &connected;
            self.outbound_webhook_attempts += 1;
            const resp = self.postOutboundAtAddress(parsed, body, signature, selected_addr, opts) catch |err| {
                if (!tried_aaaa and shouldWindowsPinnedAAAAFallback(selected_addr, hostname, connected, err)) {
                    selected_addr = self.resolveOutboundWebhookAAAAAddress(parsed.host, parsed.port) catch break;
                    tried_aaaa = true;
                    continue;
                }
                // A connected POST may have reached the peer. Transport errors
                // after that point cannot justify an automatic replay.
                if (connected) break;
                continue;
            };
            defer self.allocator.free(resp);
            if (httpStatus2xx(resp)) {
                self.outbound_webhook_delivered += 1;
                return;
            }
        }
        self.outbound_webhook_dropped += 1;
    }

    fn resolveOutboundWebhookAddress(self: *LinuxServer, host: []const u8, port: u16) !std.Io.net.IpAddress {
        if (!self.config.webhook_allow_private and outboundHostPrivate(host)) return error.PrivateOutboundAddress;
        var host_buf: [256]u8 = undefined;
        const lookup_host = outboundNormalizeHost(host, &host_buf);
        if (lookup_host.len == 0) return error.BadUrl;
        const addr = if (self.outbound_resolve_for_test) |resolve|
            try resolve(lookup_host, port)
        else
            http_fetch.resolveHostA(lookup_host, port, 400) catch |err| blk: {
                // Windows system DNS may return only an AAAA answer. This
                // fallback remains inside the screened, pinned webhook path.
                if (comptime builtin.os.tag == .windows) {
                    if (err == error.HostNotFound) break :blk try http_fetch.resolveHostAAAA(lookup_host, port, 400);
                }
                return err;
            };
        if (!self.config.webhook_allow_private and outboundAddrPrivate(addr)) return error.PrivateOutboundAddress;
        return addr;
    }

    fn resolveOutboundWebhookAAAAAddress(self: *LinuxServer, host: []const u8, port: u16) !std.Io.net.IpAddress {
        if (!self.config.webhook_allow_private and outboundHostPrivate(host)) return error.PrivateOutboundAddress;
        var host_buf: [256]u8 = undefined;
        const lookup_host = outboundNormalizeHost(host, &host_buf);
        if (lookup_host.len == 0) return error.BadUrl;
        const addr = if (self.outbound_resolve_aaaa_for_test) |resolve|
            try resolve(lookup_host, port)
        else
            try http_fetch.resolveHostAAAA(lookup_host, port, 400);
        if (addr != .ip6) return error.HostNotFound;
        if (!self.config.webhook_allow_private and outboundAddrPrivate(addr)) return error.PrivateOutboundAddress;
        return addr;
    }

    fn loadOutboundTrust(self: *LinuxServer) !outbound_trust.Store {
        if (self.runtime_io) |io| return outbound_trust.load(self.allocator, io);
        if (self.config.crypto_io) |io| return outbound_trust.load(self.allocator, io);
        var local_io = std.Io.Threaded.init(std.heap.smp_allocator, .{});
        defer local_io.deinit();
        return outbound_trust.load(self.allocator, local_io.io());
    }

    fn postOutboundAtAddress(self: *LinuxServer, url: http_fetch.Url, body: []const u8, signature: []const u8, addr: std.Io.net.IpAddress, opts: http_fetch.Options) ![]u8 {
        if (comptime builtin.is_test) {
            if (self.outbound_post_at_address_for_test) |post| return post(self.allocator, url, body, signature, addr, opts);
        }
        return http_fetch.postSignedAtAddress(self.allocator, url, body, signature, addr, opts);
    }

    fn outboundTrustOverrideForTest(self: *LinuxServer) ?[]const []const u8 {
        if (comptime builtin.is_test) return self.outbound_trust_anchors_for_test;
        return null;
    }

    test "server start gates media transports on media_enabled" {
        if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
        const allocator = std.testing.allocator;

        var media_off = LinuxServer.init(allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .media_enabled = false,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer media_off.deinit();
        media_off.start();
        try std.testing.expectEqual(@as(u16, 0), media_off.media_plane.port);
        try std.testing.expectEqual(@as(u16, 0), media_off.native_media.port);

        var media_on = LinuxServer.init(allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .media_enabled = true,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer media_on.deinit();
        media_on.start();
        if (media_on.media_plane.port == 0 or media_on.native_media.port == 0) return error.SkipZigTest;
        try std.testing.expect(media_on.media_plane.port != 0);
        try std.testing.expect(media_on.native_media.port != 0);
    }

    test "Server.init threads content filter and memo configs" {
        if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
        const allocator = std.testing.allocator;

        var server = LinuxServer.init(allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .media_sfu_max_breakout_label_bytes = 8,
            .content_filter_config = .{
                .max_patterns = 1,
                .max_pattern_len = 4,
            },
            .memo_config = .{
                .max_text_bytes = 4,
                .max_from_bytes = 16,
                .max_per_account = 1,
                .max_accounts = 1,
            },
            .search_index_config = .{
                .max_words = 1,
                .max_ids_per_word = 1,
                .max_token_bytes = 4,
            },
            .transcript_config = .{
                .max_text_bytes = 4,
                .max_speaker_bytes = 8,
                .max_per_channel = 1,
                .max_channels = 1,
            },
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();

        try std.testing.expect(try server.content_filter.add("abcd"));
        try std.testing.expect(!try server.content_filter.add("abcde"));
        try std.testing.expect(!try server.content_filter.add("wxyz"));

        try server.media_rooms.join("#a", "alice", .voice);
        try server.media_rooms.setBreakout("#a", "alice", "engineering");
        try std.testing.expectEqualStrings("engineer", server.media_rooms.breakoutOf("#a", "alice"));

        try std.testing.expectEqual(@as(usize, 1), try server.memo.send("acct", "sender", "1234", 0));
        try std.testing.expectError(error.MessageInvalid, server.memo.send("acct", "sender", "12345", 0));
        try std.testing.expectError(error.MailboxFull, server.memo.send("acct", "sender", "next", 0));
        try std.testing.expectError(error.TooManyAccounts, server.memo.send("other", "sender", "ok", 0));

        try server.search_index.index("m1", "abcd");
        try std.testing.expectEqual(@as(usize, 1), server.search_index.find("abcd").len);
        try std.testing.expectError(error.TokenTooLong, server.search_index.index("m2", "abcde"));
        try std.testing.expectError(error.TooManyWords, server.search_index.index("m3", "wxyz"));

        try std.testing.expectEqual(@as(usize, 1), try server.transcript.push("#a", "speaker", "1234", 0));
        try std.testing.expectError(error.CaptionInvalid, server.transcript.push("#a", "speaker", "12345", 0));
        try std.testing.expectError(error.CaptionInvalid, server.transcript.push("#a", "speaker-too-long", "ok", 0));
        try std.testing.expectEqual(@as(usize, 1), try server.transcript.push("#a", "speaker", "next", 1));
        try std.testing.expectEqualStrings("next", server.transcript.recent("#a")[0].text);
        try std.testing.expectError(error.TooManyChannels, server.transcript.push("#b", "speaker", "ok", 0));
    }

    /// Build the TLS 1.3 config for one accepted client. Certificate material is
    /// borrowed from `Config`; resumption state is process-wide and shared by all
    /// per-connection TLS engines so tickets survive reactor/thread boundaries.
    /// Build the TLS 1.3 listener config. `request_client_cert` is passed
    /// explicitly rather than read straight from config because it MUST differ
    /// per listener: the implicit-TLS IRC port may request a client cert (mTLS
    /// for SASL EXTERNAL / CERTFP), but the browser WebSocket port must NEVER —
    /// browsers cannot satisfy a CertificateRequest on a script-initiated WS and
    /// abort the handshake (close 1006, "opening handshake was canceled"), which
    /// silently breaks every browser client. See startAcceptedWs.
    fn tls13Config(self: *LinuxServer, request_client_cert: bool) tls_server.Config {
        self.retireExpiredActiveOcspStaple();
        var cfg = tls_server.Config{
            .cert_chain = self.config.tls_cert_chain,
            .signing_key = self.config.tls_signing_key,
            .ecdsa_p256_signing_key = self.config.tls_ecdsa_signing_key,
            .rsa_signing_key = self.config.tls_rsa_signing_key,
            .request_client_cert = request_client_cert,
            .sni_certs = self.config.tls_sni_certs,
            .ech_keys = self.config.tls_ech_keys,
            .enable_raw_public_key = self.config.tls_raw_public_key,
        };
        if (self.config.tls_ocsp_staple) |staple| {
            if (@divFloor(platform.realtimeMillis(), 1000) < self.ocsp_staple_valid_until_unix)
                cfg.ocsp_staple = staple;
        }
        if (self.config.tls_enable_resumption) {
            cfg.enable_session_tickets = true;
            cfg.ticket_key = self.tls_ticket_key;
            cfg.previous_ticket_key = self.tls_previous_ticket_key;
            cfg.replay_guard = &self.tls_replay_guard;
            cfg.now_unix_seconds = @divTrunc(platform.realtimeMillis(), 1000);
            cfg.max_early_data_size = self.config.tls_early_data_max_size;
        }
        return cfg;
    }

    /// Build the hardened TLS 1.2 engine config, mirroring `tls13Config`. RFC
    /// 5077 session tickets are gated on the SAME `tls_enable_resumption` flag
    /// and reuse the SAME ticket key + replay guard as the TLS 1.3 leg, so a
    /// successor process resumes connections that started on either protocol.
    /// When resumption is off these fields stay at their defaults and the 1.2
    /// engine behaves exactly as before (full handshakes only).
    fn tls12Config(self: *LinuxServer) tls12_server.Config {
        self.retireExpiredActiveOcspStaple();
        var cfg = tls12_server.Config{
            .cert_chain = self.config.tls12_cert_chain,
            .ecdsa_p256_signing_key = self.config.tls12_signing_key,
            .rsa_signing_key = self.config.tls_rsa_signing_key,
            .request_client_cert = self.config.tls_request_client_cert,
        };
        // Only staple on the 1.2 leg when it presents the SAME leaf as the 1.3
        // leg (shared chain object). An Ed25519 1.3 leaf forces a separately
        // minted ECDSA 1.2 leaf whose serial the staple does not cover, so it must
        // not be stapled (design §6 signing-key independence).
        if (self.config.tls_ocsp_staple) |staple| {
            if (@divFloor(platform.realtimeMillis(), 1000) < self.ocsp_staple_valid_until_unix and
                self.config.tls12_cert_chain.len != 0 and self.config.tls_cert_chain.len != 0 and
                self.config.tls12_cert_chain[0].ptr == self.config.tls_cert_chain[0].ptr)
                cfg.ocsp_staple = staple;
        }
        if (self.config.tls_enable_resumption) {
            cfg.enable_session_tickets = true;
            cfg.ticket_key = self.tls_ticket_key;
            cfg.previous_ticket_key = self.tls_previous_ticket_key;
            cfg.replay_guard = &self.tls_replay_guard;
            cfg.now_unix_seconds = @divTrunc(platform.realtimeMillis(), 1000);
        }
        return cfg;
    }

    /// Bind a loopback HTTPS listener for GET /history. A public address is
    /// refused before a socket is created. The body is whatever CHATHISTORY
    /// would already show that account. Joined from `deinit`.
    pub fn openHistoryHttps(self: *LinuxServer, configured: []const u8, port: u16, tls_config: tls_server.Config) !u16 {
        if (self.history_https) |*existing| {
            existing.shutdown();
            self.history_https = null;
        }
        self.history_https = try history_http.HttpsListener.open(self.allocator, configured, port, tls_config, .{
            .ptr = self,
            .readFn = historyHttpsRead,
        });
        errdefer {
            self.history_https.?.shutdown();
            self.history_https = null;
        }
        try self.history_https.?.prepareColdResources(self.config.crypto_io orelse return error.MissingCryptoIo);
        try self.history_https.?.spawn();
        return self.history_https.?.port;
    }

    fn historyTlsReplayCustodyValid(self: *LinuxServer, tls_config: tls_server.Config) bool {
        const replay_required = tls_config.enable_session_tickets or tls_config.max_early_data_size != 0;
        return if (replay_required)
            self.config.tls_enable_resumption and tls_config.replay_guard == &self.tls_replay_guard
        else
            tls_config.replay_guard == null;
    }

    /// Build the Windows successor's history HTTPS owner at its final Server
    /// address. HXHH authenticates the loopback endpoint and TLS policy before
    /// this one-use socket import; the worker stays parked until COMMIT.
    pub fn stageWindowsInheritedHistory(self: *LinuxServer, transfer: *helix_native_windows_socket.Transfer, carry: *const history_http.Snapshot, tls_config: tls_server.Config, io: std.Io) !void {
        if (comptime builtin.os.tag != .windows) return error.Unsupported;
        if (self.history_https != null) return error.InvalidRuntime;
        if (!self.historyTlsReplayCustodyValid(tls_config)) return error.InvalidInheritedHandoff;
        const configured = if (carry.listener.family == 23) "::1" else "127.0.0.1";
        self.history_https = try history_http.HttpsListener.initTransferred(
            self.allocator,
            configured,
            transfer,
            carry,
            tls_config,
            .{ .ptr = self, .readFn = historyHttpsRead },
        );
        errdefer {
            self.history_https.?.shutdown();
            self.history_https = null;
        }
        try self.history_https.?.prepareColdResources(io);
    }

    pub fn setWindowsWebTransportOwner(self: *LinuxServer, owner: ?*managed_wt.WebTransportListener) !void {
        if (comptime builtin.os.tag != .windows) return error.Unsupported;
        if (owner) |candidate| {
            if (self.config.webtransport_port == 0 or candidate.port != self.config.webtransport_port or
                self.windows_webtransport_owner != null) return error.ConfiguredOwnerMismatch;
            self.windows_webtransport_owner = candidate;
        } else {
            self.windows_webtransport_owner = null;
        }
    }

    /// The WebTransport bridge's connected loopback socket must have exactly
    /// one reverse four-tuple among the successor's adopted IRC clients. This
    /// pointer never grants socket authority and is cleared at the commit edge.
    pub fn setWindowsActiveWebTransportCandidate(self: *LinuxServer, snapshot: *const managed_wt.ActiveSnapshot, accepted: []const helix_native_windows_active_wt_custody.AcceptedIrcSocket) !void {
        if (comptime builtin.os.tag != .windows) return error.Unsupported;
        if (self.config.native_adopt_barrier == null or self.windows_webtransport_owner == null or
            self.windows_wt_active_candidate_snapshot != null or self.windows_wt_active_candidate_accepted != null) return error.InvalidRuntime;
        self.windows_wt_active_candidate_snapshot = snapshot;
        self.windows_wt_active_candidate_accepted = accepted;
    }

    fn validateWindowsActiveWebTransportAcceptedJoin(self: *LinuxServer) !void {
        if (comptime builtin.os.tag != .windows) return error.Unsupported;
        const snapshot = self.windows_wt_active_candidate_snapshot orelse return;
        const source_accepted = self.windows_wt_active_candidate_accepted orelse return error.InvalidInheritedHandoff;
        var observed: std.ArrayList(helix_native_windows_active_wt_custody.AcceptedIrcSocket) = .empty;
        defer observed.deinit(self.allocator);
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                const conn = entry.value;
                if (conn.s2s != null or conn.s2s_secured != null) continue;
                if (conn.fd < 0) return error.InvalidInheritedHandoff;
                const fd: usize = @intCast(conn.fd);
                var source_row: ?helix_native_windows_active_wt_custody.AcceptedIrcSocket = null;
                for (source_accepted) |row| if (row.fd == fd) {
                    if (source_row != null) return error.InvalidInheritedHandoff;
                    source_row = row;
                };
                try observed.append(self.allocator, try helix_native_windows_active_wt_custody.verifyImportedAcceptedIrcSocket(
                    fd,
                    source_row orelse return error.InvalidInheritedHandoff,
                ));
            }
        }
        if (observed.items.len != source_accepted.len) return error.InvalidInheritedHandoff;
        try helix_native_windows_active_wt_custody.validateAcceptedJoin(snapshot, observed.items);
    }

    /// Restore the exact two UDP media owners before the Windows Gate is
    /// created. Both sockets and pump-owned idle secrets come from the
    /// authenticated HXUD handoff; neither owner binds a replacement port or
    /// starts a worker here. Any later failure aborts the inert candidate.
    pub fn stageWindowsInheritedMedia(
        self: *LinuxServer,
        webrtc_transfer: *helix_native_windows_udp_socket.Transfer,
        webrtc_carry: *const media_plane_mod.Snapshot,
        native_transfer: *helix_native_windows_udp_socket.Transfer,
        native_carry: *const native_media_mod.Snapshot,
        io: std.Io,
    ) !void {
        if (comptime builtin.os.tag != .windows) return error.Unsupported;
        if (!self.config.media_enabled or self.media_routing_owner != null or
            self.media_plane.socket != null or self.native_media.socket != null or
            self.media_plane.thread != null or self.native_media.thread != null)
            return error.InvalidRuntime;
        const stun_server: ?media_plane_mod.TransportAddress = if (self.config.media_stun_port == 0) null else blk: {
            const ip4 = parseIp4(self.config.media_stun_host) orelse return error.InvalidMediaStunAddress;
            break :blk try media_plane_mod.TransportAddress.fromBytes(&ip4, self.config.media_stun_port);
        };
        try webrtc_carry.validateConfiguration(.{
            .max_frame_bytes = @intCast(@min(self.config.media_max_frame_bytes, @as(u64, media_plane_mod.max_datagram))),
            .max_upload_bytes = self.config.media_max_upload_bytes,
            .stun_server = stun_server,
            .dtls_requested = self.config.media_dtls_srtp,
            .dtls13_requested = self.config.media_dtls13,
            .cross_configured = true,
        });
        if (!native_carry.mac_key_configured) return error.ConfiguredOwnerMismatch;
        try native_carry.validateConfiguration(.{
            .max_frame_bytes = @intCast(@min(self.config.media_max_frame_bytes, @as(u64, native_media_mod.max_datagram))),
            .max_upload_bytes = self.config.media_max_upload_bytes,
            .max_participants = @min(self.config.media_max_participants, native_media_mod.max_call_participants),
            .require_mac = self.config.native_media_require_mac,
            .mac_stream_key = native_carry.mac_stream_key,
            .mac_key_configured = true,
            .cross_configured = true,
        });
        if ((self.config.media_port != 0 and self.config.media_port != webrtc_carry.socket.port) or
            (self.config.native_media_port != 0 and self.config.native_media_port != native_carry.socket.port))
            return error.ConfiguredOwnerMismatch;
        var native = try native_media_mod.NativeMediaTransport.initTransferred(self.allocator, native_transfer, native_carry, .{
            .ctx = self,
            .on_native_frame = bridgeOnNativeFrame,
            .on_native_feedback = bridgeOnNativeFeedback,
        });
        errdefer native.deinit();
        var webrtc = try media_plane_mod.MediaPlane.initTransferred(self.allocator, webrtc_transfer, webrtc_carry, .{
            .ctx = self,
            .on_rtp_frame = bridgeOnRtpFrame,
            .on_rtcp_feedback = bridgeOnRtcpFeedback,
        });
        errdefer webrtc.deinit();
        try native.prepareInheritedResources(io);
        try webrtc.prepareInheritedResources(io);
        self.native_media.deinit();
        self.media_plane.deinit();
        self.native_stream_key = native_carry.mac_stream_key;
        self.native_media = native;
        self.media_plane = webrtc;
    }

    /// Import both exact active UDP sockets while their physical registries
    /// and graph remain detached. The candidate's later inherited-client cut
    /// supplies the sole ClientId remap before either pump can run.
    pub fn stageWindowsInheritedActiveMedia(
        self: *LinuxServer,
        native_transfer: *helix_native_windows_udp_socket.Transfer,
        native_carry: *const native_media_mod.PhysicalTransportSnapshot,
        webrtc_transfer: *helix_native_windows_udp_socket.Transfer,
        webrtc_carry: *const media_plane_mod.PhysicalSnapshot,
        webrtc_limits: media_plane_mod.PhysicalSnapshot.Limits,
        io: std.Io,
    ) !void {
        if (comptime builtin.os.tag != .windows) return error.Unsupported;
        if (!self.config.media_enabled or self.media_routing_owner != null or
            self.media_plane.socket != null or self.native_media.socket != null or
            self.media_plane.thread != null or self.native_media.thread != null)
            return error.InvalidRuntime;
        const stun_server: ?media_plane_mod.TransportAddress = if (self.config.media_stun_port == 0) null else blk: {
            const ip4 = parseIp4(self.config.media_stun_host) orelse return error.InvalidMediaStunAddress;
            break :blk try media_plane_mod.TransportAddress.fromBytes(&ip4, self.config.media_stun_port);
        };
        const expected_native: native_media_mod.Policy = .{
            .max_frame_bytes = @intCast(@min(self.config.media_max_frame_bytes, @as(u64, native_media_mod.max_datagram))),
            .max_upload_bytes = self.config.media_max_upload_bytes,
            .max_participants = @min(self.config.media_max_participants, native_media_mod.max_call_participants),
            .require_mac = self.config.native_media_require_mac,
            .mac_stream_key = native_carry.policy.mac_stream_key,
            .mac_key_configured = true,
            .cross_configured = true,
        };
        const expected_webrtc: media_plane_mod.Policy = .{
            .max_frame_bytes = @intCast(@min(self.config.media_max_frame_bytes, @as(u64, media_plane_mod.max_datagram))),
            .max_upload_bytes = self.config.media_max_upload_bytes,
            .stun_server = stun_server,
            .dtls_requested = self.config.media_dtls_srtp,
            .dtls13_requested = self.config.media_dtls13,
            .cross_configured = true,
        };
        if ((self.config.native_media_port != 0 and self.config.native_media_port != native_carry.socket.port) or
            (self.config.media_port != 0 and self.config.media_port != webrtc_carry.socket.port))
            return error.ConfiguredOwnerMismatch;
        var native = try native_media_mod.NativeMediaTransport.initTransferredPhysical(
            self.allocator,
            native_transfer,
            native_carry,
            expected_native,
            .{ .ctx = self, .on_native_frame = bridgeOnNativeFrame, .on_native_feedback = bridgeOnNativeFeedback },
        );
        errdefer native.deinit();
        var webrtc = try media_plane_mod.MediaPlane.initTransferredPhysical(
            self.allocator,
            webrtc_transfer,
            webrtc_carry,
            expected_webrtc,
            webrtc_limits,
            .{ .ctx = self, .on_rtp_frame = bridgeOnRtpFrame, .on_rtcp_feedback = bridgeOnRtcpFeedback },
        );
        errdefer webrtc.deinit();
        try native.prepareInheritedResources(io);
        try webrtc.prepareInheritedResources(io);
        self.native_media.deinit();
        self.media_plane.deinit();
        self.native_stream_key = native_carry.policy.mac_stream_key;
        self.native_media = native;
        self.media_plane = webrtc;
    }

    pub fn setWindowsActiveMediaCandidate(self: *LinuxServer, candidate: NativeWindowsActiveMediaCandidate) !void {
        if (comptime builtin.os.tag != .windows) return error.Unsupported;
        if (self.config.native_adopt_barrier == null or !self.config.media_enabled or
            self.media_routing_owner != null or self.native_media.socket == null or
            self.media_plane.socket == null or self.windows_active_media_candidate != null)
            return error.InvalidRuntime;
        try candidate.graph.validate();
        self.windows_active_media_candidate = candidate;
    }

    /// Rebuild the pristine graph/FIFO at the final Server address. Active
    /// routing state uses the separately authenticated HXMG/HXNA/HXWA bodies.
    pub fn prepareWindowsInheritedMediaRouting(self: *LinuxServer) !void {
        if (comptime builtin.os.tag != .windows) return error.Unsupported;
        if (!self.config.media_enabled or self.media_routing_owner != null or
            self.native_media.socket == null or self.media_plane.socket == null)
            return error.InvalidRuntime;
        try self.prepareMediaRoutingOwner();
    }

    fn historyHttpsRead(ptr: *anyopaque, account: []const u8, target: []const u8, out: []u8) error{Denied}!usize {
        const server: *LinuxServer = @ptrCast(@alignCast(ptr));
        var msgs: [8]lotus.Message = undefined;
        const rows = try server.readAccountHistory(account, target, &msgs);
        var n: usize = 0;
        for (rows) |row| {
            if (n >= out.len) break;
            const line = std.fmt.bufPrint(out[n..], "{s} {s}\n", .{ row.msgid, row.text }) catch break;
            n += line.len;
        }
        return n;
    }

    pub fn deinit(self: *LinuxServer) void {
        // Every reactor borrows World, sessions, TLS generations and fabric.
        // Stop/wake/join before any of those owners can be destroyed. Main must
        // settle companion producers before requesting this reactor stop.
        if (self.runtime_gate) |view| view.requireAllJoined() catch
            @panic("runtime owner must cancel/stop and join before Server destruction");
        self.detachRuntimeAfterJoined() catch @panic("Server cleanup without actual runtime joins");
        if (self.shutdown) |run| self.requestStop(run);
        self.pool.deinit();
        if (self.media_routing_owner != null) {
            const deadline_ms = checkedMonotonicDeadlineMillis(5_000) catch @panic("invalid media teardown clock");
            self.settleMediaRoutingBeforeStop(deadline_ms) catch @panic("media accepted output must settle before teardown");
            self.native_media.requestStopAndWake();
            self.media_plane.requestStopAndWake();
            self.native_media.joinLegacyAfterStop() catch @panic("runtime owner must join and detach Native before Server teardown");
            self.media_plane.joinLegacyAfterStop() catch @panic("runtime owner must join and detach WebRTC before Server teardown");
            self.finishMediaRoutingAfterJoined() catch @panic("media source retirement must complete before Server teardown");
        }
        self.clearFlightPanicTarget();
        // Stop + join the /metrics listener thread FIRST, before freeing the
        // snapshot it reads. shutdown() signals the stop flag, closes the
        // listener fd, and joins. No-op when the endpoint was never started.
        if (self.metrics_server) |*ms| {
            ms.shutdown();
            self.metrics_server = null;
        }
        if (self.history_https) |*hs| {
            hs.shutdown();
            self.history_https = null;
        }
        // Stop + join the webhook listener before anything it might touch (the
        // shared store) is torn down. shutdown() closes the fd and joins; the
        // store is an inline value with no heap to free.
        lockSpin(&self.webhook_lifecycle_gate);
        if (self.webhook_server) |*ws| {
            ws.shutdown();
            self.webhook_server = null;
        }
        self.webhook_lifecycle_gate.unlock();
        self.metrics_snapshot.deinit();
        if (self.owned_disabled_features) |owned| {
            self.allocator.free(owned);
            self.owned_disabled_features = null;
        }
        self.driveDeinit();
        self.geo.stop();
        self.allocator.destroy(self.geo);
        self.wasm.deinit();
        self.relay_seen.deinit();
        // Tear down every connection owned by every shard's reactor (each reactor
        // owns a disjoint slab). Single-reactor mode just walks `reactors[0]`.
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (slot.occupied) {
                    if (slot.value.s2s) |link| {
                        link.deinit();
                        self.allocator.destroy(link);
                        slot.value.s2s = null;
                    }
                    if (slot.value.s2s_secured) |link| {
                        link.deinit();
                        self.allocator.destroy(link);
                        slot.value.s2s_secured = null;
                    }
                    self.abortMultiline(&slot.value);
                    if (slot.value.tls) |t| {
                        t.deinit();
                        self.allocator.destroy(t);
                        slot.value.tls = null;
                    }
                    if (slot.value.ws) |w| {
                        self.allocator.destroy(w);
                        slot.value.ws = null;
                    }
                    self.clearDeferredSessionMeshParts(&slot.value);
                    slot.value.session_list_cache.reset();
                    if (slot.value.send_overflow.capacity > 0)
                        slot.value.send_overflow.deinit(slot.value.overflow_allocator);
                    if (slot.value.tls_deferred_plain.capacity > 0) slot.value.tls_deferred_plain.deinit(slot.value.overflow_allocator);
                    if (slot.value.recv_overflow.capacity > 0)
                        slot.value.recv_overflow.deinit(slot.value.overflow_allocator);
                    closeFd(slot.value.fd);
                }
            }
        }
        self.history.deinit();
        self.search_index.deinit();
        for (self.relay_v2_deferred[0..self.relay_v2_deferred_len]) |*pending|
            pending.deinit(self.allocator);
        self.relay_v2_outbox.deinit();
        self.relay_v2_event_log.deinit();
        self.relay_v2_replay_guard.deinit();
        self.e2ee_group_mesh_authority.deinit();
        self.attachment_delivery_spool.deinit();
        self.event_spine_replay_guard.deinit();
        self.chanstats.deinit();
        if (self.mesh_ban_filter) |*filter| filter.deinit();
        if (self.policy_undo) |*undo| self.destroyPolicyUndo(undo);
        self.policy_undo = null;
        self.destroyOutboundWebhooks();
        for (&self.webpush_overflow_deliveries) |*slot| if (slot.*) |*delivery| {
            delivery.deinit(self.allocator);
            slot.* = null;
        };
        self.bot_registry.deinit();
        self.threads.deinit();
        self.schedules.deinit();
        self.appeals.deinit();
        self.first_holds.deinit();
        self.slash_cmds.deinit();
        self.mesh_search_peers.deinit(self.allocator);
        self.mesh_search_wires.deinit(self.allocator);
        self.deinitMeshSearchPending();
        self.warden.deinit();
        self.spamtrap.deinit();
        self.raid_shield.deinit();
        self.metadata.deinit();
        self.props.deinit();
        {
            var it = self.channel_prop_clocks.iterator();
            while (it.next()) |entry| {
                self.allocator.free(entry.key_ptr.*);
                entry.value_ptr.deinit(self.allocator);
            }
            self.channel_prop_clocks.deinit(self.allocator);
        }
        {
            var it = self.slowmode_last.keyIterator();
            while (it.next()) |key| self.allocator.free(@constCast(key.*));
            self.slowmode_last.deinit(self.allocator);
        }
        {
            var it = self.entity_prop_clocks.iterator();
            while (it.next()) |entry| {
                self.allocator.free(entry.key_ptr.*);
                entry.value_ptr.deinit(self.allocator);
            }
            self.entity_prop_clocks.deinit(self.allocator);
        }
        self.access.deinit();
        self.saccess.deinit();
        self.chan_akick.deinit();
        self.chan_resv.deinit();
        self.server_jupe.deinit();
        self.clone_limit.deinit();
        if (self.conn_throttle) |*t| t.deinit();
        self.login_throttle.deinit();
        self.oper_audit.deinit();
        self.mesh_clones.deinit();
        self.nick_delay.deinit();
        self.reputation.deinit();
        self.account_abuse.deinit();
        self.accepts.deinit();
        self.silence.deinit();
        self.observe.deinit();
        self.oper_motd.deinit();
        self.host_requests.deinit();
        self.guises.deinit();
        self.shuns.deinit();
        self.gags.deinit();
        self.temp_modes.deinit();
        self.autojoins.deinit();
        self.nick_groups.deinit();
        self.welcome.deinit();
        {
            var it = self.mlocks.iterator();
            while (it.next()) |e| {
                self.allocator.free(e.key_ptr.*);
                self.allocator.free(e.value_ptr.*);
            }
            self.mlocks.deinit(self.allocator);
        }
        {
            var it = self.seen.iterator();
            while (it.next()) |e| self.allocator.free(e.key_ptr.*);
            self.seen.deinit(self.allocator);
        }
        if (self.geoip_bytes) |b| self.allocator.free(b);
        if (self.geoip_asn_bytes) |b| self.allocator.free(b);
        self.account_verifies.deinit();
        self.reset_store.deinit();
        self.totp.deinit();
        self.activity_subs.deinit();
        self.session_drop_journal.deinit();
        self.sessions.deinit();
        if (self.pending_migrations) |*pm| pm.deinit();
        self.session_replica_store.deinit();
        self.session_replica_routes.deinit(self.allocator);
        self.session_replica_identities.deinit(self.allocator);
        self.session_replica_nicks.deinit(self.allocator);
        self.content_filter.deinit();
        // Stop BOTH media pump threads before freeing either transport or the
        // bridge registry. Each pump's cross-leg sink reaches into the OTHER
        // transport (native pump -> media_plane.sendTo, RTP pump ->
        // native_media.sendTo) via media_bridges, so deiniting one transport (or
        // the bridges) while the other pump is still live is a use-after-free —
        // a teardown race that crashes a background thread shortly after a test
        // passes (surfacing as a spurious "failed command" under `zig build
        // test`'s `--listen=-` runner). shutdown() is idempotent, so the later
        // deinit() calls (which call it again) are safe.
        self.media_plane.shutdown();
        self.native_media.shutdown();
        self.media_physical_attachments.deinit(self.allocator);
        self.media_rooms.deinit();
        self.media_plane.deinit();
        self.native_media.deinit();
        {
            var bit = self.media_bridges.keyIterator();
            while (bit.next()) |k| self.allocator.free(k.*);
            self.media_bridges.deinit(self.allocator);
        }
        self.memo.deinit();
        self.memo_forward.deinit();
        self.memo_ignore.deinit();
        self.transcript.deinit();
        self.allocator.free(self.reload_bindings);
        if (self.reload_class_registry) |*r| r.deinit();
        if (self.reload_parsed) |*p| p.deinit(self.allocator);
        // Free the server-owned TLS reload generations, if any (the current plus
        // the one-cycle-retained previous generation). The boot cert generation is
        // main-owned and is never freed here.
        if (self.reload_tls) |*t| t.deinit(self.allocator);
        if (self.reload_tls12) |*t| t.deinit(self.allocator);
        if (self.reload_tls_prev) |*t| t.deinit(self.allocator);
        if (self.reload_tls12_prev) |*t| t.deinit(self.allocator);
        for (self.reload_tls_retired.items) |*retired| retired.deinit(self.allocator);
        self.reload_tls_retired.deinit(self.allocator);
        // Free all server-owned OCSP generations after the connection tables.
        if (self.ocsp_staple_owned) |owned| self.allocator.free(owned);
        if (self.ocsp_staple_prev) |prev| self.allocator.free(prev);
        for (self.ocsp_staple_retired.items) |retired| self.allocator.free(retired);
        self.ocsp_staple_retired.deinit(self.allocator);
        if (self.ocsp_staple_incoming) |incoming| self.allocator.free(incoming);
        self.read_markers.deinit();
        self.deinitReadMarkerFacts(&self.read_marker_facts);
        self.monitor.deinit();
        self.whowas.deinit();
        self.world.deinit();
        // Reactor workers were joined before semantic teardown above; only
        // backend tables/wakes/listeners and the drained fabric remain owned.
        // Media pumps are already stopped above, and reactor producers are now
        // joined, so no recorder can access a histogram after this point.
        self.latency_stats.deinit();
        self.peer_health.deinit();
        self.freePublishedMeshPeers();
        if (self.self_pidfd >= 0) {
            closeFd(self.self_pidfd);
            self.self_pidfd = -1;
        }
        for (self.reactors) |*reactor| {
            self.discardDeferredUpgrade(reactor);
            reactor.deinit();
        }
        if (comptime builtin.os.tag == .windows) std.debug.assert(self.windows_manual_upgrade_pending == 0);
        self.allocator.free(self.reactors);
        if (self.mesh_dials.len != 0) self.allocator.free(self.mesh_dials);
        self.inherited_mesh_redials.deinit(self.allocator);
        if (self.mesh_trusted_node_keys.len != 0) self.allocator.free(self.mesh_trusted_node_keys);
        if (self.relay_v2_required_nodes.len != 0) self.allocator.free(self.relay_v2_required_nodes);
        if (self.meshpass_roots.len != 0) self.allocator.free(self.meshpass_roots);
        if (self.mesh_admission_token.len != 0) self.allocator.free(self.mesh_admission_token);
        if (self.fabric) |*f| f.deinit();
        self.* = undefined;
    }

    /// Arm the accept SQE if needed. Submission is batched by `runOnce`.
    pub fn armAccept(self: *LinuxServer) !void {
        if (self.rx().socket_io_quiescing) return;
        for (self.rx().acceptOps()) |op| {
            if (op.fd < 0 or op.armed.*) continue;
            if (op.kind == .s2s and self.rx() != &self.reactors[0]) continue;
            try io_backend.submitAccept(&self.rx().ring, op.token, op.fd);
            op.armed.* = true;
        }
    }

    /// Keep exactly one poll on the cross-reactor wake eventfd in flight, so a
    /// foreign reactor's `wakeReactor()` makes this loop run.
    fn armWake(self: *LinuxServer) !void {
        if (self.rx().wake) |w| {
            if (!self.rx().wake_armed) {
                try io_backend.submitPoll(&self.rx().ring, wake_token, w.fd(), linux.POLL.IN);
                self.rx().wake_armed = true;
            }
        }
    }

    /// Wake this reactor from any thread: the in-flight wake poll completes, the
    /// loop runs, and (once the multi-reactor model lands) drains its mailbox.
    pub fn wakeReactor(self: *LinuxServer) void {
        if (self.rx().wake) |*w| w.wake();
    }

    /// Wake EVERY reactor's wake eventfd from any thread. Each reactor keeps a
    /// poll on its own wake fd in flight (`armWake` each `runOnce`), so this makes
    /// every blocked `submitAndWait(1)` return at once. Used by the stop path: a
    /// SO_REUSEPORT throwaway connection only nudges the one reactor the kernel
    /// happens to route it to, leaving the others blocked forever in
    /// `submitAndWait`; an explicit wake-all is what lets `pool.join()` complete.
    pub fn wakeAllReactors(self: *LinuxServer) void {
        for (self.reactors) |*r| {
            if (r.wake) |*w| w.wake();
        }
    }

    /// Cooperative multi-reactor stop: clear the shared run flag, then wake every
    /// reactor so each blocked loop returns from `submitAndWait`, re-checks the
    /// (now false) flag, and exits — letting `runThreaded`'s `pool.join()` finish.
    /// Callable from any thread (e.g. a test driver, or DIE/RESTART). Without the
    /// wake-all a reactor with no pending completion would never observe the clear.
    pub fn requestStop(self: *LinuxServer, run: *std.atomic.Value(bool)) void {
        run.store(false, .release);
        self.wakeAllReactors();
    }

    /// Handle the wake-fd poll completion: drain the eventfd, mark the poll
    /// consumed (re-armed next `runOnce`), record the wake, then drain this
    /// shard's cross-shard mailbox and flush the handed-off bytes to the local
    /// connections they target.
    fn onWakePoll(self: *LinuxServer) void {
        self.rx().wake_armed = false;
        if (self.rx().wake) |*w| w.drain();
        _ = self.rx().wake_count.fetchAdd(1, .monotonic);
        // A source may have published poison without successfully queueing a
        // fabric record. Abort it before any already-mailboxed later event can
        // append, then sweep again for failures discovered while draining.
        self.abortPoisonedDeliveries();
        self.drainSessionDropControls();
        self.drainFabric();
        self.drainAttachmentSpoolForCurrentReactor();
        if (self.rx() == &self.reactors[0]) self.retryRelayV2Outbox();
        if (self.rx() == &self.reactors[0] and
            self.e2ee_group_retry_requested.swap(false, .acq_rel))
            self.retryE2eeGroupCustody();
        self.abortPoisonedDeliveries();
    }

    /// Drain every cross-shard delivery addressed to THIS reactor's shard and
    /// append each handoff's bytes to the local connection it targets, then arm
    /// send and release the pooled buffer. Runs under the world write lock (the
    /// completion bracket), so it is serialized against every other reactor's
    /// world access. The connection lookup uses THIS reactor's slab — the only
    /// reactor that may touch these send buffers. A handoff whose target slot is
    /// gone (the connection closed before its bytes arrived) is dropped; its
    /// buffer is still released so the pool never leaks.
    fn drainFabric(self: *LinuxServer) void {
        _ = self.drainFabricCount();
    }

    /// Drain the independent SESSION DROP control lane before ordinary byte
    /// delivery. A control is only a wake hint: the bounded journal remains the
    /// authority, so a late/duplicate control merely prompts the same sweep.
    fn drainSessionDropControls(self: *LinuxServer) void {
        const fabric = if (self.fabric) |*f| f else {
            self.sweepSessionDropTransactions();
            return;
        };
        var controls: [64]reactor_fabric.SessionDropControl = undefined;
        while (fabric.drainControls(self.rx().shard_id, &controls) != 0) {}
        self.sweepSessionDropTransactions();
    }

    /// Counted form used by the Helix final fixed point. A delivery drained on a
    /// later shard may enqueue work back to an earlier shard, so a single linear
    /// sweep is not a proof that the complete fabric is empty.
    fn drainFabricCount(self: *LinuxServer) usize {
        const fabric = if (self.fabric) |*f| f else return 0;
        const my_shard = self.rx().shard_id;
        var msgs: [64]reactor_fabric.DeliverMsg = undefined;
        var drained: usize = 0;
        while (true) {
            const n = fabric.drain(my_shard, &msgs);
            if (n == 0) break;
            drained += n;
            for (msgs[0..n]) |msg| {
                // Every buffer this reactor drains was acquired for ITS shard, so
                // it goes back to this shard's pool.
                defer fabric.release(my_shard, msg.buf);
                const bytes = fabric.bytes(msg.buf);
                // Cross-shard OBSERVE fan-out: `bytes` is an encoded observe_event;
                // decode it and push a per-watcher OBSERVE line to THIS reactor's
                // matching opers (its own client table, on its own thread).
                if (msg.broadcast_observe) {
                    self.deliverObserveFromWire(bytes);
                    continue;
                }
                // Cross-shard oper-event fan-out: deliver to every one of THIS
                // reactor's clients subscribed to the carried category (safe — we
                // only touch our own shard's client table, on our own thread).
                if (msg.broadcast_category) |cat_raw| {
                    const category: event_spine.EventCategory = @enumFromInt(cat_raw);
                    const severity: event_spine.EventSeverity = @enumFromInt(@min(msg.broadcast_severity, @as(u8, @typeInfo(event_spine.EventSeverity).@"enum".field_names.len - 1)));
                    // The publishing reactor carried the event subject inline so this
                    // reactor applies each local subscriber's per-category subject
                    // glob exactly as the origin did. An empty carried subject means
                    // match-all (the common, unscoped case).
                    const subject = msg.broadcastSubject();
                    // Origin server: the node where the event was raised. Empty means
                    // a locally-raised event, so use this server's name; a network-
                    // wide event fanned in from a peer carries the true origin.
                    const carried_origin = msg.broadcastOrigin();
                    const origin = if (carried_origin.len != 0) carried_origin else self.serverName();
                    // `bytes` is the raw chatsvc event BODY; render the per-recipient
                    // `:<origin> EVENT <target> <body>` line for each local subscriber
                    // (target = that subscriber's own nick), matching the origin shard.
                    const stable_identity: ?EventSpineDeliveryIdentity = if (msg.broadcast_has_event_identity)
                        .{
                            .event_id = msg.broadcast_event_id,
                            .origin_time_ms = msg.broadcast_event_time_ms,
                        }
                    else
                        null;
                    var it = self.rx().clients.iterator();
                    while (it.next()) |entry| {
                        const c = entry.value;
                        if (c.closing) continue;
                        if (c.delivery_gap.load(.acquire)) {
                            self.beginDeliveryGapAbort(c);
                            continue;
                        }
                        // `bytes` is the raw event BODY, which is also the IRCX
                        // type-routing key (its leading TYPE token), so the
                        // receiving shard classifies exactly as the origin shard.
                        if (!sessionWantsEvent(&c.session, category, severity, bytes, subject)) continue;
                        // MEDIA events stay member-scoped on this shard too.
                        if (!self.mediaEventAllowed(entry.id, &c.session, bytes)) continue;
                        var line_buf: [default_reply_bytes]u8 = undefined;
                        var tag_buf: [256]u8 = undefined;
                        const client_tags = eventSpineDeliveryTags(&c.session, category, severity, stable_identity, &tag_buf);
                        const line = event_spine.renderEventTagged(client_tags, origin, c.session.displayName(), bytes, &line_buf) catch continue;
                        appendToConn(c, line) catch {
                            self.poisonOwnedDelivery(c);
                            continue;
                        };
                        self.armSendIfNeeded(c) catch {
                            self.poisonOwnedDelivery(c);
                        };
                    }
                    continue;
                }
                const conn = self.rx().clients.get(msg.to) orelse continue;
                // Source-side poison is published out-of-band precisely so a
                // queued prefix/later record cannot append after the gap.
                if (self.abortDeliveryGapFor(msg.to, conn)) continue;
                if (conn.closing) continue;
                if (msg.close_after and bytes.len == 0) {
                    const tok = tokenFromId(msg.to) catch continue;
                    self.closeConn(tok, msg.close_reason) catch {};
                    continue;
                }
                if (msg.preframed_secure) {
                    appendSecuredToConn(conn, bytes) catch {
                        self.poisonOwnedDelivery(conn);
                        continue;
                    };
                } else {
                    appendToConn(conn, bytes) catch {
                        self.poisonOwnedDelivery(conn);
                        continue;
                    };
                }
                self.armSendIfNeeded(conn) catch {
                    self.poisonOwnedDelivery(conn);
                    continue;
                };
                if (msg.close_after) {
                    conn.close_reason = msg.close_reason;
                    conn.closing = true;
                }
            }
        }
        return drained;
    }

    /// Keep exactly one periodic timeout-sweep timer in flight.
    fn armTimer(self: *LinuxServer) !void {
        if (self.rx().timer_armed) return;
        const ns = self.config.sweep_interval_ms * std.time.ns_per_ms;
        self.rx().timer_spec = .{ .sec = @intCast(@divFloor(ns, std.time.ns_per_s)), .nsec = @intCast(@mod(ns, std.time.ns_per_s)) };
        try io_backend.submitTimeout(&self.rx().ring, timer_token, &self.rx().timer_spec);
        self.rx().timer_armed = true;
    }

    /// Reconcile every token whose authority can change before destructive
    /// Store expiry. If the key snapshot or any fail-closed projection cannot
    /// complete, retain the expired Store objects and retry on the next timer
    /// turn; this prevents the last retry key from disappearing under OOM.
    fn sweepSessionReplicaStore(self: *LinuxServer) void {
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        // An expired local OFFER may be the only durable retry journal left
        // after final row removal. Mint every affected exact-origin tombstone
        // before destructive expiry. Continue across all bounded pages after a
        // failure so one allocation-starved token cannot starve later orphans;
        // if any journal remains, preserve the entire expired set for next tick.
        var orphan_failed = false;
        var orphan_cursor: ?session_migrate.Token = null;
        while (true) {
            var page_buf: [32]session_migrate.Token = undefined;
            const page = self.session_replica_store.projectionSweepTokensAfter(now_wall, orphan_cursor, &page_buf);
            if (page.len == 0) break;
            for (page) |token| {
                if (self.session_replica_store.getOrigin(token, self.config.node_id) == null or
                    self.sessions.containsToken(token)) continue;
                self.publishSessionReplicaRevoke(token);
                if (self.session_replica_store.getOriginTombstone(token, self.config.node_id) == null)
                    orphan_failed = true;
            }
            orphan_cursor = page[page.len - 1];
            if (page.len < page_buf.len) break;
        }
        if (orphan_failed) return;

        var affected: std.ArrayListUnmanaged(session_migrate.Token) = .empty;
        defer affected.deinit(self.allocator);
        var cursor: ?session_migrate.Token = null;
        while (true) {
            var page_buf: [32]session_migrate.Token = undefined;
            const page = self.session_replica_store.projectionSweepTokensAfter(now_wall, cursor, &page_buf);
            if (page.len == 0) break;
            affected.appendSlice(self.allocator, page) catch return;
            cursor = page[page.len - 1];
            if (page.len < page_buf.len) break;
        }

        for (affected.items) |token| {
            if (!self.projectBestSessionReplicaV2(token)) return;
        }
        const swept = self.session_replica_store.sweep(now_wall);
        if (swept.entries != 0 or swept.attachment_leases != 0 or swept.routes != 0 or
            swept.tombstones != 0 or swept.quarantines != 0)
            self.session_replica_store_generation +%= 1;
        // Marker expiry can reveal an otherwise-live entry, so reconcile once
        // more against the post-sweep Store. A live authority remains available
        // to the ordinary retry cursor if this second pass hits allocation
        // pressure; rowless tokens were already completed before removal.
        for (affected.items) |token| _ = self.projectBestSessionReplicaV2(token);
        _ = self.prunePendingReplicasWithoutStoreAuthority(now_wall);
    }

    /// Advance the projection-free OCG2 observer from reactor 0 only. Main
    /// primes the borrowed Runtime synchronously with elapsed=0 and supplies the
    /// exact monotonic origin used for that prime; timer turns then advance only
    /// the elapsed component while sampling wall time independently. Retryable
    /// results are intentionally quiet and naturally retry next cadence. A
    /// terminal Runtime (or an impossible local monotonic rollback) is logged
    /// once and never driven again.
    fn tickOcg2Runtime(self: *LinuxServer) bool {
        if (!self.isMaintenanceReactor()) return false;
        if (self.ocg2_runtime_terminal_logged) return false;
        const runtime = self.ocg2_runtime orelse return false;
        const origin_ms = self.ocg2_runtime_monotonic_origin_ms orelse return false;
        const now_ms = self.nowU64();
        if (now_ms < origin_ms) {
            // CLOCK_MONOTONIC cannot precede a sample captured earlier in this
            // process. Treat a violated seam (including a broken injected test
            // clock) as a one-way authority failure, never as elapsed=0.
            _ = runtime.failMonotonicRollback();
            self.ocg2_runtime_terminal_logged = true;
            srvLog("onyx-server: OCG2 observer stopped: monotonic clock preceded its primed origin\n", .{});
            return false;
        }

        switch (runtime.tick(self.meshWallMs(), now_ms - origin_ms)) {
            .disabled, .complete, .retryable => {},
            .failed => |failure| {
                self.ocg2_runtime_terminal_logged = true;
                srvLog("onyx-server: OCG2 observer stopped: {s}\n", .{@tagName(std.meta.activeTag(failure))});
            },
        }
        return true;
    }

    /// Reactor 0 projects the durable OCG2 image onto every logged-in session.
    /// A retryable or failed generation leaves the previous privilege image in
    /// place; the next timer turn tries again.
    fn projectOcg2LiveSessions(self: *LinuxServer) void {
        if (!self.isMaintenanceReactor()) return;
        if (self.ocg2_runtime_terminal_logged) return;
        const runtime = self.ocg2_projection orelse return;
        const origin_ms = self.ocg2_projection_origin_ms orelse return;
        const audit = self.ocg2_audit orelse return;
        const now_ms = self.nowU64();
        if (now_ms < origin_ms) return;
        var sessions: std.ArrayList(ocg2_live_projection.SessionRef) = .empty;
        defer sessions.deinit(self.allocator);
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                const client = entry.value;
                if (client.s2s != null or client.s2s_secured != null) continue;
                const account = client.session.account() orelse continue;
                const binding = if (self.oper_registry) |*registry|
                    oper_session_provenance.configuredLocalBinding(registry, account)
                else
                    null;
                sessions.append(self.allocator, .{
                    .session = &client.session,
                    .configured_binding = binding,
                }) catch return;
            }
        }
        switch (ocg2_live_projection.projectOnce(
            self.allocator,
            runtime,
            sessions.items,
            audit,
            self.meshWallMs(),
            now_ms - origin_ms,
        ) catch return) {
            .committed, .unchanged, .aborted, .busy, .retryable => {},
            .terminal => {
                self.ocg2_runtime_terminal_logged = true;
                srvLog("onyx-server: OCG2 projection stopped\n", .{});
            },
        }
    }

    /// Fired when the periodic timer elapses: run the timeout sweep and re-arm.
    fn onTimerTick(self: *LinuxServer) void {
        self.rx().timer_armed = false;
        // The journal sweep is authoritative recovery for a missed control
        // mailbox hint and for a requester/owner that vanished before cleanup.
        self.sweepSessionDropTransactions();
        // A delivery gap is a stream-integrity failure, not ordinary timeout
        // work. Disconnect it before any timer-driven projection or retry can
        // enqueue a later event to that generation.
        self.abortPoisonedDeliveries();
        self.drainAttachmentSpoolForCurrentReactor();
        self.retryWebhookResumeIfPending();
        if (self.isMaintenanceReactor()) {
            self.reconcileWebpushOutcomesLocked(null) catch {};
            // Network retry is outside the Worker mutex. The terminal consumer
            // only observes this retained outbox; it never runs synchronous HTTP.
            self.retryWebpushOverflowOutputsLocked();
            self.retryDirtyDurableMemos();
        }
        // SIGUSR2 → connection-preserving Helix UPGRADE. Polled here (out of
        // signal context) and gated to reactor 0 — the reactor that owns the
        // listener + every client connection the upgrade carries. `swap`
        // atomically consumes the request so a single signal fires exactly one
        // upgrade. On success `performUpgrade` execve's and never returns; a
        // failure is logged and the daemon keeps serving.
        if (self.isMaintenanceReactor() and upgrade_signal_requested.swap(false, .seq_cst)) {
            self.deferUpgrade(.signal);
        }
        if (comptime builtin.os.tag == .windows) {
            if (self.isMaintenanceReactor()) {
                var socket_due = io_backend.windowsSocketIdRolloverDue();
                if (comptime build_info.windows_rollover_smoke)
                    socket_due = socket_due or self.windowsRolloverSmokeMode() != null;
                _ = self.maybeDeferWindowsDescriptorRollover(
                    self.nowMs(),
                    socket_due,
                    os_runtime.windowsFileIdRolloverDue(),
                );
            }
        }
        if (self.isMaintenanceReactor()) self.maybeReloadAcmeTls();
        if (self.isMaintenanceReactor()) self.maybeSwapOcspStaple();
        if (self.isMaintenanceReactor() and self.reload_tls_retired.items.len != 0)
            self.pruneRetiredTlsGenerations();
        if (self.isMaintenanceReactor() and self.ocsp_staple_retired.items.len != 0)
            self.pruneRetiredOcspStaples();
        self.retryFailedSessionHandoffs();
        if (comptime builtin.os.tag == .windows) self.retryWindowsClosingIo();
        self.sweepTimeouts();
        self.sweepDeferredSessionAutojoins();
        // Local channel projection is owner-reactor scoped: every shard applies
        // and bootstraps only its own attachments, while foreign rows remain a
        // verification barrier. Retry on every reactor so a shard-1+ attachment
        // cannot leave the shared journal (and UPGRADE preflight) dirty forever.
        self.retryDirtyLocalChannelProjections();
        // Evict lapsed nick-delay holds (reactor-0 only, like other shared-state
        // maintenance; runs under the same world write lock as hold/check/release).
        if (self.isMaintenanceReactor() and self.config.nick_delay_ms != 0) _ = self.nick_delay.sweep(self.nowMs());
        // Prune the throttle's expired/empty per-IP state on the same cadence.
        if (self.isMaintenanceReactor()) {
            self.expireRetainedHistory();
            self.evaluateRaidShield();
            _ = self.tickOcg2Runtime();
            self.projectOcg2LiveSessions();
            if (self.conn_throttle) |*t| t.prune(self.nowMs());
            // Evict unlocked, decayed-to-floor login-throttle records too.
            _ = self.login_throttle.sweep(self.nowMs());
            // Evict staged cross-mesh session-migration capsules whose reclaim
            // window lapsed — same TTL as the mesh reclaim token that unlocks
            // them, so a capsule never outlives the only token that could
            // consume it. Together with `PendingMigrations.max_entries` this
            // bounds what a signed peer can pin in memory. Reactor-0-gated
            // shared-state maintenance like the sweeps above.
            if (self.pending_migrations) |*pm| _ = pm.sweep(self.nowMs(), mesh_reclaim_ttl_ms);
            self.sweepSessionReplicaStore();
            self.retryDeferredRelayV2();
            self.retryRelayV2Outbox();
            self.retryE2eeGroupCustody();
        }
        if (self.isMaintenanceReactor()) self.sweepDeferredDeliveries();
        self.sweepTempModes();
        // Keep the IRCX ACCESS store clock current on every reactor (a JOIN
        // gate may match on any shard) so timed ACCESS entries expire; reclaim
        // lapsed entries on reactor 0 under the same world lock as other sweeps.
        self.access.now_seconds = self.accessNowSeconds();
        if (self.isMaintenanceReactor()) _ = self.access.pruneExpired();
        // Re-dial any [mesh].connect peer whose link dropped (reactor-0 only;
        // rate-capped per peer, no-op while a dial is in flight or established).
        // Stall accounting runs first so an open breaker is visible before the
        // same tick decides whether a retry is allowed.
        if (self.isMaintenanceReactor()) self.sweepMooringStalls();
        _ = self.sweepMeshAutoConnect(false, 1);
        // Mesh RTT samples for status.json / MESH: timestamped PING→PONG on each
        // established peer. Reactor-0-only (S2S links live here); cadence is short
        // enough for a live status page but well below CRDT anti-entropy load.
        if (self.isMaintenanceReactor()) self.maybeProbeMeshPeerRtt();
        // Publish the distinct-peer count for cross-shard LUSERS reads. Reactor 0
        // owns the peer links, so it is the only reactor that can compute this;
        // other shards read the published atomic. Converges within one tick of a
        // peer establishing/dropping.
        if (self.isMaintenanceReactor()) self.publishPeerCount();
        // Mesh anti-entropy: periodically re-burst this node's local channel
        // state to every established peer so anything missed during a split or a
        // reconnect race converges within the cadence instead of staying out of
        // sync forever. Reactor-0-GATED: S2S peer links live only on reactor 0, so
        // both `resyncMeshStateToPeers` and `pruneStaleMeshMembers` walk reactor 0's
        // slots and do nothing on any other reactor. The `last_membership_resync_ms`
        // guard is shared server state, so it MUST only be advanced by the reactor
        // that actually performs the re-burst: on a multi-reactor node, letting a
        // sibling reactor consume the guard (while doing no work, because it holds no
        // peer links) starves reactor 0's real re-burst below the intended cadence.
        // The receiver then never sees a re-affirmation within `stale_member_ttl_ms`
        // and reaps every live peer-homed member (empty NAMES + broken cross-node
        // PRIVMSG). Gating both the guard and the work through
        // `isMaintenanceReactor` (not `rx()`, which treats an unset threadlocal
        // as reactor 0) keeps the send cadence honest.
        if (self.isMaintenanceReactor()) {
            const now = self.nowMs();
            // Cross-mesh oper-grant refresh: minted grants expire after
            // `oper_grant_ttl_ms`, so on a link that stays up longer than the
            // TTL a still-logged-in oper's grant lapses on every peer (remote
            // lookup → null, the `*` prefix decays) unless it is re-minted.
            // Re-mint + re-broadcast every live opered session's grant on a
            // dedicated cadence well inside the TTL. Same reactor-0 discipline
            // as the membership resync below: BOTH the work and the cadence
            // guard live behind the reactors[0] gate, so a link-less sibling
            // reactor can never consume the guard while doing nothing.
            if (operGrantRefreshDue(self.last_oper_grant_refresh_ms, now)) {
                self.last_oper_grant_refresh_ms = now;
                self.rebroadcastLocalOpers();
            }
            if (self.last_session_replica_refresh_ms == 0) {
                self.last_session_replica_refresh_ms = now;
            } else if (now - self.last_session_replica_refresh_ms >= session_replica_refresh_interval_ms) {
                self.last_session_replica_refresh_ms = now;
                self.refreshPortableSessionReplicasV2();
            }
            if (self.last_session_attachment_lease_refresh_ms == 0) {
                self.last_session_attachment_lease_refresh_ms = now;
                // Hot-adopted clients may inherit a lease already near expiry;
                // renew on the first successor maintenance turn instead of
                // waiting a full interval and opening a false-offline window.
                self.refreshAttachedSessionReplicaLeases();
            } else if (now - self.last_session_attachment_lease_refresh_ms >= session_attachment_lease_refresh_interval_ms) {
                self.last_session_attachment_lease_refresh_ms = now;
                self.refreshAttachedSessionReplicaLeases();
            }
            if (now - self.last_membership_resync_ms >= membership_resync_interval_ms) {
                self.last_membership_resync_ms = now;
                self.resyncMeshStateToPeers();
                // Anti-entropy is additive (the re-burst only re-affirms PRESENT
                // members), so a remote member whose PART/QUIT was never propagated
                // would linger forever. Reap such stale projections from each peer's
                // RouteTable on the same cadence: their local last-seen stamp froze
                // when they departed, so they age past `stale_member_ttl_ms` while
                // live members keep being refreshed. Runs under the completion-wide
                // `world.lockWrite` (see onCompletion).
                self.pruneStaleMeshMembers(now);
            }
            self.retryDirtySessionReplicaTokens();
            self.retryDirtySessionReplicaProjections();
            self.retrySessionReplicaStoreStages();
            self.resumeSessionReplicaReplays();
            self.retryOrphanedLocalSessionReplicaRevokes();
        }
        self.maybeWriteStats();
    }

    /// Retry closes whose exact-token World handoff failed before teardown.
    /// Slot storage is stable while iterating; closeConn may mark the current
    /// slot free but never reallocates the slot array. A repeated OOM simply
    /// leaves the retry bit set for the next timer tick.
    fn retryFailedSessionHandoffs(self: *LinuxServer) void {
        var index: usize = 0;
        while (index < self.rx().clients.slots.items.len) : (index += 1) {
            const slot = &self.rx().clients.slots.items[index];
            if (!slot.occupied or !slot.value.session_handoff_retry) continue;
            const id = idFromToken(slot.value.token);
            const handed_off = self.handoffLiveSessionIdentity(id, &slot.value) catch continue;
            slot.value.session_handoff_complete = handed_off;
            slot.value.session_handoff_checked = true;
            slot.value.session_handoff_retry = false;

            // A send CQE may still hold a kernel reference to send_buf. The
            // ordinary send-completion path owns final teardown in that case.
            if (hasUnsentOutput(&slot.value)) {
                self.armSendIfNeeded(&slot.value) catch {
                    // Arming failed, so no kernel reference was created and it
                    // is safe to drop the unsent tail during final close.
                    self.closeConn(slot.value.token, slot.value.close_reason) catch {};
                };
                continue;
            }
            self.closeConn(slot.value.token, slot.value.close_reason) catch {};
        }
    }

    /// Re-send local mesh state to every established S2S peer. Membership is
    /// HLC-keyed so re-affirming present members is idempotent; this fills gaps
    /// (a member the peer never learned about). Mirrors the one-shot
    /// link-establish burst (`sendMembershipBurstTo`) on a periodic cadence.
    fn resyncMeshStateToPeers(self: *LinuxServer) void {
        for (self.rx().clients.slots.items) |*slot| {
            if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
            const is_peer = slot.value.s2s_secured != null or slot.value.s2s != null;
            if (!is_peer) continue;
            const established = if (slot.value.s2s_secured) |l|
                l.established()
            else if (slot.value.s2s) |l|
                l.established()
            else
                false;
            if (!established) continue;
            // A long retained-object replay can span several maintenance turns.
            // Do not let the periodic anti-entropy cadence bypass the same
            // authority-before-membership ordering as establishment/RESYNC;
            // coalesce it into the pending secured burst instead.
            if (slot.value.s2s_secured != null and slot.value.session_replica_replay_pending) {
                slot.value.session_replica_resync_burst_pending = true;
                continue;
            }
            const peer_name = establishedPeerName(&slot.value);
            if (peer_name) |name| {
                if (self.peer_health.get(name)) |h| h.value_sync = .syncing;
            }
            if (self.sendMeshStateBurstTo(&slot.value)) {
                if (peer_name) |name| self.notePeerAntiEntropy(name);
            }
        }
    }

    /// Reap stale (never-retracted) remote member projections from every
    /// established peer's RouteTable. The membership re-burst is additive, so a
    /// remote PART/QUIT lost during a split, USR2 churn, or an abrupt drop would
    /// otherwise leave a permanent zombie in the peer's roster. Members whose local
    /// last-seen stamp was not refreshed within `stale_member_ttl_ms` of `now_ms`
    /// are pruned. `now_ms` is this node's monotonic `nowMs()`, the SAME clock the
    /// feed path stamps onto each member (`applyMembership`'s `now_ms`), so the
    /// staleness compare stays in one clock domain (see `RouteTable.pruneStale`).
    /// Walks the same `self.rx().clients.slots` as `resyncMeshStateToPeers` (peer
    /// links live on reactor 0). Secured links are deliberately excluded: their
    /// remote roster is inbound state, while this connection's replay/burst flags
    /// describe outbound state and cannot safely authorize deletion. They repair
    /// omissions only from peer-originated authenticated MEMBERSHIP_SYNC markers.
    /// The simpler `clearDroppedPeerRouteOrigin` does not use this lifecycle gate.
    fn pruneStaleMeshMembers(self: *LinuxServer, now_ms: i64) void {
        const window: i64 = stale_member_ttl_ms;
        for (self.rx().clients.slots.items) |*slot| {
            if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
            if (slot.value.s2s_secured != null) continue;
            if (slot.value.s2s) |link| {
                if (!link.established()) continue;
                _ = link.peer.pruneStaleMembers(now_ms, window) catch {
                    self.drainIdentityTransitions(&slot.value, link);
                    continue;
                };
                self.drainIdentityTransitions(&slot.value, link);
            }
        }
    }

    fn clearDroppedPeerRouteOrigin(self: *LinuxServer, dropped_node: u64) void {
        if (dropped_node == 0) return;
        for (self.rx().clients.slots.items) |*slot| {
            if (!slot.occupied) continue;
            if (slot.value.s2s_secured) |link| {
                if (link.inner) |inner| inner.peer.routes.clearOrigin(dropped_node);
            } else if (slot.value.s2s) |link| {
                link.peer.routes.clearOrigin(dropped_node);
            }
        }
    }

    /// Publish server/channel stats to the configured web directory (stats.json
    /// + index.html) for static hosting by nginx. Throttled to stats_interval_ms;
    /// best-effort — any I/O error is swallowed so it never disrupts the loop.
    /// Increment the count for `code` in the parallel tally arrays, appending a
    /// new bucket if unseen. When full, unknown/overflow folds into "??".
    fn tallyCountry(codes: [][]const u8, counts: []u32, n: *usize, code: []const u8) void {
        for (codes[0..n.*], 0..) |existing, i| {
            if (std.ascii.eqlIgnoreCase(existing, code)) {
                counts[i] += 1;
                return;
            }
        }
        if (n.* < codes.len) {
            codes[n.*] = code;
            counts[n.*] = 1;
            n.* += 1;
            return;
        }
        // Table full: fold into an existing "??" bucket if present.
        for (codes[0..n.*], 0..) |existing, i| {
            if (std.mem.eql(u8, existing, "??")) {
                counts[i] += 1;
                return;
            }
        }
    }

    /// Copy the tally into `out` sorted by count descending (selection sort over
    /// a tiny fixed set); returns the number of entries written.
    fn topCountries(codes: []const []const u8, counts: []const u32, out: []stats_report.CountryCount) usize {
        const n = @min(codes.len, out.len);
        for (0..n) |i| out[i] = .{ .code = codes[i], .clients = counts[i] };
        for (0..n) |i| {
            var max_j = i;
            for (i + 1..n) |j| {
                if (out[j].clients > out[max_j].clients) max_j = j;
            }
            if (max_j != i) {
                const tmp = out[i];
                out[i] = out[max_j];
                out[max_j] = tmp;
            }
        }
        return n;
    }

    /// Registered local (non-S2S) clients and opers across EVERY reactor.
    /// `rx().clients` is shard-local; LUSERS peaks and the public stats page
    /// must report the node total. World lock already held by the timer.
    fn tallyRegisteredLocalClients(self: *LinuxServer) struct { clients: u64, opers: u64 } {
        var clients: u64 = 0;
        var opers: u64 = 0;
        for (self.reactors) |*r| {
            var it = r.clients.iterator();
            while (it.next()) |e| {
                const c = e.value;
                if (c.s2s != null or c.s2s_secured != null) continue;
                if (!c.session.registered()) continue;
                clients += 1;
                if (c.session.isOper()) opers += 1;
            }
        }
        return .{ .clients = clients, .opers = opers };
    }

    fn maybeWriteStats(self: *LinuxServer) void {
        // Per-channel statistics: flush index.json + <slug>.json into the
        // channel-stats dir on the stats cadence. Runs under the completion-wide
        // world.lockWrite (the timer completion holds it), so it is serialized
        // against the recordHistory* feed even on a multi-reactor node; the
        // throttle ensures exactly one flush per interval.
        if (self.config.chanstats_dir.len != 0) {
            const cnow = self.nowMs();
            if (self.chanstats_last_write_ms == 0 or cnow - self.chanstats_last_write_ms >= self.config.stats_interval_ms) {
                self.chanstats_last_write_ms = cnow;
                if (self.config.crypto_io) |io| {
                    // Presence provider: current members (local + mesh roster)
                    // per channel, read under the same world.lockWrite the
                    // flush already holds.
                    const Presence = struct {
                        fn count(ctx: *anyopaque, channel: []const u8) usize {
                            const srv: *LinuxServer = @ptrCast(@alignCast(ctx));
                            return srv.globalMemberCount(channel, srv.world.memberCount(channel));
                        }
                        // A channel STILL EXISTS if it currently has members
                        // (local + mesh roster) OR is durably registered.
                        // Everything else (a transient channel whose last member
                        // left) is pruned from stats.
                        fn exists(ctx: *anyopaque, channel: []const u8) bool {
                            const srv: *LinuxServer = @ptrCast(@alignCast(ctx));
                            if (srv.globalMemberCount(channel, srv.world.memberCount(channel)) > 0) return true;
                            if (srv.account_services) |svc| return svc.channelIsRegistered(channel);
                            return false;
                        }
                    };
                    // The World is authoritative for a channel's current
                    // topic. Reconcile it before rendering so a restart or an
                    // older collector snapshot cannot leave the public feed
                    // showing an obsolete wire payload. `syncTopic` only
                    // repairs tracked channels and does not fabricate activity.
                    var stats_channels = self.chanstats.channels.iterator();
                    while (stats_channels.next()) |entry| {
                        const channel = entry.key_ptr.*;
                        if (self.world.topicInfo(channel)) |topic| {
                            self.chanstats.syncTopic(channel, nickFromPrefix(topic.setter), topic.text, platform.realtimeMillis());
                        } else {
                            self.chanstats.syncTopic(channel, "", "", platform.realtimeMillis());
                        }
                    }
                    self.chanstats.writeJson(io, self.config.chanstats_dir, self.config.network_name, self.serverName(), platform.realtimeMillis(), .{
                        .users_online = self.meshUserCount(),
                        .presence_ctx = self,
                        .presence_fn = Presence.count,
                        // A cold restart temporarily has no channel projection
                        // while secured peers and resumable attachments return.
                        // Do not erase a persisted public aggregate during that
                        // convergence window; ordinary pruning resumes after it.
                        .exists_fn = if (cnow >= self.chanstats_prune_ready_ms) Presence.exists else null,
                    });
                    // Public status page feed: this node's health + its mesh
                    // peers, written alongside the channel stats.
                    self.writeStatusJson(io);
                }
            }
        }
        self.maybeRunBackups();
        // Event Spine history snapshot, gated to reactor 0 (the ring is shared
        // across reactors, so a single writer avoids N redundant concurrent
        // snapshots racing the same target) and throttled to the stats cadence.
        // The write itself is atomic (tmp+rename, see `saveEventHistory`), and
        // reactor 0's snapshot captures events raised on every shard.
        if (self.config.event_history_path.len != 0 and self.isMaintenanceReactor()) {
            const enow = self.nowMs();
            if (self.event_history_last_write_ms == 0 or enow - self.event_history_last_write_ms >= self.config.stats_interval_ms) {
                self.event_history_last_write_ms = enow;
                self.saveEventHistory();
            }
        }
        // Flush any elapsed flood-collapse windows (reactor 0) into a single
        // ".flood/.warn" summary each — published as >= warn so they bypass the
        // collapser (no self-collapse).
        if (self.isMaintenanceReactor()) {
            var summaries: [16]event_collapse_mod.Summary = undefined;
            const n = self.event_collapse.flush(platform.realtimeMillis(), &summaries);
            for (summaries[0..n]) |*s| {
                const cat: event_spine.EventCategory = if (s.category < @typeInfo(event_spine.EventCategory).@"enum".field_names.len)
                    @enumFromInt(s.category)
                else
                    .flood;
                var mb: [320]u8 = undefined;
                const msg = std.fmt.bufPrint(&mb, "collapsed {d}x {s} ({d} suppressed in {d}s): {s}", .{
                    s.total, cat.code(), s.suppressed, @divTrunc(s.span_ms, 1000), s.message(),
                }) catch continue;
                self.publishOperEvent(.flood, .warn, msg) catch {};
            }
        }

        // Refresh the live Prometheus snapshot on the same throttled cadence as
        // the web-stats files, even when web stats are disabled — the /metrics
        // endpoint only needs the counters, not the GeoIP/web rendering below.
        if (self.metrics_server != null) {
            const now_m = self.nowMs();
            if (self.metrics_last_refresh_ms == 0 or
                now_m - self.metrics_last_refresh_ms >= self.config.stats_interval_ms)
            {
                self.metrics_last_refresh_ms = now_m;
                self.refreshMetricsSnapshot();
            }
        }

        const dir = self.config.stats_web_dir;
        if (dir.len == 0) return;
        const io = self.config.crypto_io orelse return;
        const now = self.nowMs();
        if (self.stats_last_write_ms != 0 and now - self.stats_last_write_ms < self.config.stats_interval_ms) return;
        self.stats_last_write_ms = now;

        const pop = self.tallyRegisteredLocalClients();
        const clients = pop.clients;
        const opers = pop.opers;
        // Country tally (parallel arrays): code slice borrowed from the loaded
        // GeoIP database bytes, which outlive this render. Bounded; overflow
        // beyond the cap is folded into the "??" (unknown) bucket.
        const max_countries = 24;
        var cc_codes: [max_countries][]const u8 = undefined;
        var cc_counts: [max_countries]u32 = undefined;
        var cc_n: usize = 0;
        const geodb = self.ensureGeoip();
        // Same all-reactor walk as the population tally: GeoIP buckets must
        // not under-count shards 1..N. docs/audit/timer-guard-0.7.md P0-TG-1.
        for (self.reactors) |*r| {
            var it = r.clients.iterator();
            while (it.next()) |e| {
                const c = e.value;
                if (c.s2s != null or c.s2s_secured != null) continue;
                if (!c.session.registered()) continue;
                if (geodb) |db| {
                    var code: []const u8 = "??";
                    if (parseGeoIp(c.session.realHost())) |gip| {
                        if (db.lookupInfo(gip) catch null) |gi| {
                            if (gi.country_iso) |iso| if (iso.len > 0) {
                                code = iso;
                            };
                        }
                    }
                    tallyCountry(&cc_codes, &cc_counts, &cc_n, code);
                }
            }
        }
        if (clients > self.stats_peak_clients) self.stats_peak_clients = clients;

        // Sort the country tally descending and surface the top entries.
        var top_countries: [max_countries]stats_report.CountryCount = undefined;
        const nctry = topCountries(cc_codes[0..cc_n], cc_counts[0..cc_n], &top_countries);

        // Append the current client count to the history ring, then materialize
        // it oldest→newest for the sparkline.
        self.stats_history[self.stats_hist_head] = @intCast(@min(clients, std.math.maxInt(u32)));
        self.stats_hist_head = (self.stats_hist_head + 1) % self.stats_history.len;
        if (self.stats_hist_count < self.stats_history.len) self.stats_hist_count += 1;
        var hist_buf: [60]u32 = undefined;
        const hc = self.stats_hist_count;
        const hstart = (self.stats_hist_head + self.stats_history.len - hc) % self.stats_history.len;
        var hi: usize = 0;
        while (hi < hc) : (hi += 1) hist_buf[hi] = self.stats_history[(hstart + hi) % self.stats_history.len];

        // Busiest public channels (skip secret/hidden), kept sorted desc, capped.
        var tops: [20]stats_report.TopChannel = undefined;
        var ntop: usize = 0;
        var cit = self.world.channelIterator();
        while (cit.next()) |cv| {
            if (cv.secret or cv.hidden) continue;
            const entry = stats_report.TopChannel{
                .name = cv.name,
                .members = @intCast(@min(cv.members, std.math.maxInt(u32))),
                .topic = cv.topic,
            };
            if (ntop < tops.len) {
                tops[ntop] = entry;
                ntop += 1;
            } else if (entry.members <= tops[ntop - 1].members) {
                continue;
            } else {
                tops[ntop - 1] = entry;
            }
            // Bubble the new/replaced entry up to keep descending order.
            var j = ntop - 1;
            while (j > 0 and tops[j].members > tops[j - 1].members) : (j -= 1) {
                const tmp = tops[j];
                tops[j] = tops[j - 1];
                tops[j - 1] = tmp;
            }
        }

        // Assign each top channel a filename slug (post-sort, so links are stable
        // with the rendered order) for its linked detail page.
        var slug_store: [20][64]u8 = undefined;
        for (tops[0..ntop], 0..) |*t, si| {
            const slen = statsSlug(t.name, &slug_store[si]);
            t.slug = slug_store[si][0..slen];
        }

        const snapshot = stats_report.Snapshot{
            .server_name = self.serverName(),
            .network = protocol_inventory.currentNetworkName(),
            .version = server_version,
            .generated_unix = @divTrunc(platform.realtimeMillis(), 1000),
            .uptime_secs = @intCast(@max(@as(i64, 0), @divTrunc(now - self.start_ms, 1000))),
            .clients = clients,
            .opers = opers,
            .channels = self.world.channelCount(),
            .servers = 1,
            .max_clients = self.stats_peak_clients,
            .connections_total = self.stats.connections_total.load(.monotonic),
            .messages_total = self.stats.messages_in_total.load(.monotonic),
            .bytes_in = self.stats.bytes_in_total.load(.monotonic),
            .bytes_out = self.stats.bytes_out_total.load(.monotonic),
            .node_health = self.currentNodeHealth(),
            .history = hist_buf[0..hc],
            .top_channels = tops[0..ntop],
            .top_countries = top_countries[0..nctry],
        };

        const buf = self.allocator.alloc(u8, 256 * 1024) catch return;
        defer self.allocator.free(buf);
        self.publishStatsFile(io, dir, "stats.json", stats_report.renderJson, snapshot, buf);
        self.publishStatsFile(io, dir, "index.html", stats_report.renderHtml, snapshot, buf);

        // Per-channel detail pages for each listed channel.
        for (tops[0..ntop]) |t| {
            var members: [128]stats_report.Member = undefined;
            var prefix_store: [128][1]u8 = undefined;
            var mn: usize = 0;
            if (self.world.memberIterator(t.name)) |mit_const| {
                var mit = mit_const;
                while (mit.next()) |wid| {
                    if (mn == members.len) break;
                    const mc = self.connFor(clientIdFromWorld(wid.*)) orelse continue;
                    const mm = self.world.memberModes(t.name, wid.*) orelse world_model.MemberModes.empty();
                    const hp = mm.highestPrefix();
                    var pfx: []const u8 = "";
                    if (hp != 0) {
                        prefix_store[mn][0] = hp;
                        pfx = prefix_store[mn][0..1];
                    }
                    members[mn] = .{ .nick = mc.session.displayName(), .prefix = pfx };
                    mn += 1;
                }
            }
            var modes_buf: [40]u8 = undefined;
            const detail = stats_report.ChannelDetail{
                .name = t.name,
                .topic = t.topic,
                .modes = self.world.channelModeString(t.name, &modes_buf),
                .member_count = t.members,
                .members = members[0..mn],
                .generated_unix = snapshot.generated_unix,
            };
            var w = std.Io.Writer.fixed(buf);
            stats_report.renderChannelHtml(detail, &w) catch continue;
            var name_buf: [96]u8 = undefined;
            const name = std.fmt.bufPrint(&name_buf, "chan_{s}.html", .{t.slug}) catch continue;
            writeStatsFileAtomic(io, dir, name, w.buffered());
        }
    }

    fn maybeRunBackups(self: *LinuxServer) void {
        if (self.config.backup_dir.len == 0 or !self.isMaintenanceReactor()) return;
        const io = self.config.crypto_io orelse return;
        const now = self.nowMs();
        if (self.backup_last_write_ms != 0 and now - self.backup_last_write_ms < self.config.backup_interval_ms) return;
        const retry_ms = @max(@as(i64, 5_000), @min(self.config.backup_interval_ms, @as(i64, 5 * 60_000)));
        if (self.backup_last_failure_ms != 0 and now - self.backup_last_failure_ms < retry_ms) return;
        if (self.writeBackupSet(io)) {
            self.backup_last_write_ms = now;
            self.backup_last_failure_ms = 0;
        } else self.backup_last_failure_ms = now;
    }

    fn writeBackupSet(self: *LinuxServer, io: std.Io) bool {
        const generated_unix = @divTrunc(platform.realtimeMillis(), 1000);
        const svc = self.account_services orelse return false;
        svc.compactStoreForBackup() catch |err| {
            if (comptime builtin.os.tag == .windows) std.debug.print("onyx-server: Windows backup compact failed ({s})\n", .{@errorName(err)});
            return false;
        };
        var private_writer: ?backup_set.PrivateWriterWindows = null;
        if (comptime builtin.os.tag == .windows) {
            private_writer = backup_set.PrivateWriterWindows.open(io, self.config.backup_dir) catch |err| {
                std.debug.print("onyx-server: Windows backup private directory failed ({s})\n", .{@errorName(err)});
                return false;
            };
        }
        defer if (private_writer) |*writer| writer.deinit();
        const writer_ptr: ?*backup_set.PrivateWriterWindows = if (private_writer) |*writer| writer else null;
        var nonce: [16]u8 = undefined;
        if (comptime builtin.os.tag == .windows) io.random(&nonce);
        var name_buf: [96]u8 = undefined;
        const name = if (comptime builtin.os.tag == .windows)
            std.fmt.bufPrint(&name_buf, "accounts-{d}-{s}.db.snap", .{ generated_unix, std.fmt.bytesToHex(nonce, .lower) }) catch return false
        else
            std.fmt.bufPrint(&name_buf, "accounts-{d}.db.snap", .{generated_unix}) catch return false;
        const source = if (self.config.account_store_path.len != 0) self.config.account_store_path else svc.store.snapshot_path;
        if (comptime builtin.os.tag == .windows) {
            const snapshot = svc.store.readPrivateSnapshotAllocWindows(self.allocator, backup_set.max_backup_file_bytes) catch |err| {
                std.debug.print("onyx-server: Windows backup snapshot read failed ({s})\n", .{@errorName(err)});
                return false;
            };
            defer {
                std.crypto.secureZero(u8, snapshot);
                self.allocator.free(snapshot);
            }
            writer_ptr.?.writeNewFile(name, snapshot) catch |err| {
                std.debug.print("onyx-server: Windows backup snapshot publish failed ({s})\n", .{@errorName(err)});
                return false;
            };
        } else if (!self.copyFileToBackup(io, svc.store.snapshot_path, name, backup_set.max_backup_file_bytes, null)) return false;

        var files: [2]backup_set.Artifact = undefined;
        files[0] = .{ .kind = "accounts", .name = name, .source = source };
        var file_count: usize = 1;
        var chanstats_included = false;
        if (self.config.chanstats_dir.len != 0) {
            chanstats_mod.saveSnapshot(&self.chanstats, io, self.config.chanstats_dir);
            var src_buf: [1024]u8 = undefined;
            const src = std.fmt.bufPrint(&src_buf, "{s}/.chanstats.snapshot", .{self.config.chanstats_dir}) catch return false;
            var stats_name_buf: [96]u8 = undefined;
            const stats_name = if (comptime builtin.os.tag == .windows)
                std.fmt.bufPrint(&stats_name_buf, "chanstats-{d}-{s}.snapshot", .{ generated_unix, std.fmt.bytesToHex(nonce, .lower) }) catch return false
            else
                std.fmt.bufPrint(&stats_name_buf, "chanstats-{d}.snapshot", .{generated_unix}) catch return false;
            if (!self.copyFileToBackup(io, src, stats_name, backup_set.max_backup_file_bytes, writer_ptr)) return false;
            files[1] = .{ .kind = backup_set.chanstats_name, .name = stats_name, .source = src };
            file_count = 2;
            chanstats_included = true;
        }

        var manifest_buf: [4096]u8 = undefined;
        const manifest = backup_set.writeManifest(&manifest_buf, generated_unix, files[0..file_count], chanstats_included) catch return false;
        if (writer_ptr) |writer| {
            writer.writeFile("latest.json", manifest) catch |err| {
                std.debug.print("onyx-server: Windows backup manifest publish failed ({s})\n", .{@errorName(err)});
                return false;
            };
            return true;
        }
        return writeFileAtomicStatus(io, self.config.backup_dir, "latest.json", manifest);
    }

    fn copyFileToBackup(self: *LinuxServer, io: std.Io, source_path: []const u8, name: []const u8, limit: usize, private_writer: ?*backup_set.PrivateWriterWindows) bool {
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, source_path, self.allocator, .limited(limit)) catch |err| {
            if (comptime builtin.os.tag == .windows) std.debug.print("onyx-server: Windows backup artifact {s} read failed ({s})\n", .{ name, @errorName(err) });
            return false;
        };
        defer self.allocator.free(bytes);
        if (private_writer) |writer| {
            writer.writeNewFile(name, bytes) catch |err| {
                if (comptime builtin.os.tag == .windows) std.debug.print("onyx-server: Windows backup artifact {s} publish failed ({s})\n", .{ name, @errorName(err) });
                return false;
            };
            return true;
        }
        return writeFileAtomicStatus(io, self.config.backup_dir, name, bytes);
    }

    /// Sanitize a channel name into a filename slug (keep [A-Za-z0-9_-], map the
    /// rest to '_'); returns the byte length written. Never empty.
    fn statsSlug(name: []const u8, out: *[64]u8) usize {
        var n: usize = 0;
        for (name) |c| {
            if (n == out.len) break;
            out[n] = switch (c) {
                'A'...'Z', 'a'...'z', '0'...'9', '-' => c,
                else => '_',
            };
            n += 1;
        }
        if (n == 0) {
            out[0] = 'c';
            n = 1;
        }
        return n;
    }

    fn publishStatsFile(
        self: *LinuxServer,
        io: anytype,
        dir: []const u8,
        name: []const u8,
        comptime render: anytype,
        snapshot: stats_report.Snapshot,
        buf: []u8,
    ) void {
        _ = self;
        var w = std.Io.Writer.fixed(buf);
        render(snapshot, &w) catch return;
        writeStatsFileAtomic(io, dir, name, w.buffered());
    }

    /// Map a mesh peer's link state to a compact public status string.
    fn peerStatusString(state: link_health_mod.PeerState) []const u8 {
        return switch (state) {
            .established => "up",
            .connecting, .handshaking => "connecting",
            .draining => "draining",
            .down => "down",
        };
    }

    fn currentNodeHealth(self: *LinuxServer) stats_report.NodeHealth {
        var peers_total: u32 = 0;
        var peers_up: u32 = 0;
        for (self.peer_health.entries.items) |*slot| {
            peers_total += 1;
            if (slot.health.state == .established) peers_up += 1;
        }
        const status: []const u8 = if (!self.partition_quorum)
            "degraded"
        else if (self.partition_split or peers_up < peers_total)
            "warning"
        else
            "ok";
        return .{
            .status = status,
            .mesh_quorum = self.partition_quorum,
            .mesh_partitioned = self.partition_split,
            .mesh_components = @intCast(@min(self.partition_components, std.math.maxInt(u32))),
            .mesh_peers_up = peers_up,
            .mesh_peers_total = peers_total,
        };
    }

    /// Emit `status.json` — the public status-page feed. This node's identity,
    /// uptime, live user count and mesh-quorum health, plus every known mesh
    /// peer's link state, smoothed RTT and time-in-state. Read from this node's
    /// perspective (each node writes its own); best-effort, same cadence as the
    /// channel stats. Timestamps are wall-clock seconds; durations are seconds.
    fn writeStatusJson(self: *LinuxServer, io: std.Io) void {
        var buf: [8192]u8 = undefined;
        const json = self.buildStatusJson(&buf);
        writeStatsFileAtomic(io, self.config.chanstats_dir, "status.json", json);
    }

    fn directoryRankScore(public_activity: chanstats_mod.ChanStats.PublicSummary) u64 {
        return public_activity.messages +| (public_activity.active_channels_24h *| 100) +| (public_activity.channels *| 10);
    }

    pub fn meshAdmissionMode(self: *const LinuxServer) []const u8 {
        if (self.meshpass_roots.len != 0) return "signed";
        if (self.config.mesh_pass.len != 0) return "shared-secret";
        return "open";
    }

    /// Pure builder for `status.json` (see `writeStatusJson`). Returns the JSON
    /// slice backed by `buf`; on overflow returns whatever was written so far
    /// (best-effort, never fails). Separated so it is testable without file I/O.
    fn buildStatusJson(self: *LinuxServer, buf: []u8) []const u8 {
        var w = std.Io.Writer.fixed(buf);
        const now_unix = @divTrunc(platform.realtimeMillis(), 1000);
        const uptime: i64 = @max(0, now_unix - self.boot_unix);
        const now_mono: u64 = @intCast(@max(@as(i64, 0), self.nowMs()));

        w.writeAll("{\"generated_at\":") catch return w.buffered();
        w.print("{d}", .{now_unix}) catch return w.buffered();
        w.writeAll(",\"network\":") catch return w.buffered();
        writeJsonEscaped(&w, self.config.network_name) catch return w.buffered();
        w.writeAll(",\"node\":") catch return w.buffered();
        writeJsonEscaped(&w, self.serverName()) catch return w.buffered();
        w.writeAll(",\"description\":") catch return w.buffered();
        writeJsonEscaped(&w, self.config.server_description) catch return w.buffered();
        w.writeAll(",\"icon_url\":") catch return w.buffered();
        if (self.config.network_icon_url.len != 0) {
            writeJsonEscaped(&w, self.config.network_icon_url) catch return w.buffered();
        } else {
            w.writeAll("null") catch return w.buffered();
        }
        w.print(",\"discoverable\":{s}", .{if (self.config.network_discoverable) "true" else "false"}) catch return w.buffered();
        w.print(",\"uptime_seconds\":{d}", .{uptime}) catch return w.buffered();
        w.print(",\"users_online\":{d}", .{self.meshUserCount()}) catch return w.buffered();
        const public_activity = self.chanstats.publicSummary(platform.realtimeMillis());
        w.print(",\"activity\":{{\"channels\":{d},\"messages\":{d},\"active_channels_24h\":{d},\"last_active\":", .{
            public_activity.channels,
            public_activity.messages,
            public_activity.active_channels_24h,
        }) catch return w.buffered();
        if (public_activity.last_active_ms) |last| {
            w.print("{d}", .{@divFloor(last, 1000)}) catch return w.buffered();
        } else {
            w.writeAll("null") catch return w.buffered();
        }
        w.writeAll(",\"heatline\":[") catch return w.buffered();
        for (public_activity.heatline[0..public_activity.heatline_len], 0..) |messages, i| {
            if (i != 0) w.writeAll(",") catch return w.buffered();
            w.print("{d}", .{messages}) catch return w.buffered();
        }
        w.writeAll("]") catch return w.buffered();
        w.writeAll("}") catch return w.buffered();
        w.print(",\"directory\":{{\"listed\":{s},\"rank_score\":{d},\"last_active\":", .{
            if (self.config.network_discoverable) "true" else "false",
            directoryRankScore(public_activity),
        }) catch return w.buffered();
        if (public_activity.last_active_ms) |last| {
            w.print("{d}", .{@divFloor(last, 1000)}) catch return w.buffered();
        } else {
            w.writeAll("null") catch return w.buffered();
        }
        w.writeAll(",\"entry\":{\"network\":") catch return w.buffered();
        writeJsonEscaped(&w, self.config.network_name) catch return w.buffered();
        w.writeAll(",\"node\":") catch return w.buffered();
        writeJsonEscaped(&w, self.serverName()) catch return w.buffered();
        w.writeAll(",\"description\":") catch return w.buffered();
        writeJsonEscaped(&w, self.config.server_description) catch return w.buffered();
        w.print(",\"users_online\":{d},\"channels\":{d},\"messages\":{d},\"active_channels_24h\":{d}}}}}", .{
            self.meshUserCount(),
            public_activity.channels,
            public_activity.messages,
            public_activity.active_channels_24h,
        }) catch return w.buffered();
        w.print(",\"features\":{{\"s2s\":{s},\"websocket\":{s},\"webtransport\":{s},\"proxy_protocol\":{s},\"media\":{s},\"webpush\":{s},\"webauthn\":{s},\"webhook\":{s},\"metrics\":{s},\"sts\":{s},\"raw_public_key\":{s},\"ktls_tx\":{s},\"ktls_rx\":{s},\"orowasm\":{s},\"geo\":{s},\"connection_throttle\":{s},\"mesh_clone_limit\":{s},\"reputation_gate\":{s},\"dnsbl\":{s}}}", .{
            if (self.config.s2s_port != 0 or self.config.mesh_connect.len != 0) "true" else "false",
            if (self.config.ws_enabled) "true" else "false",
            if (self.config.webtransport_port != 0) "true" else "false",
            if (self.config.proxy_protocol_enabled and self.config.trusted_proxies.len != 0) "true" else "false",
            if (self.config.media_enabled) "true" else "false",
            if (self.config.webpush_vapid_pub.len != 0) "true" else "false",
            if (self.config.webauthn_rp_id != null and self.config.webauthn_origins.len != 0) "true" else "false",
            if (self.config.webhook_enabled) "true" else "false",
            if (self.config.metrics_port != 0) "true" else "false",
            if (self.config.sts_value != null) "true" else "false",
            if (self.config.tls_raw_public_key) "true" else "false",
            if (self.config.tls_ktls_tx) "true" else "false",
            if (self.config.tls_ktls_rx) "true" else "false",
            if (self.config.wasm_plugin_dir.len != 0) "true" else "false",
            if (self.config.geo_enabled) "true" else "false",
            if (self.config.throttle_connects != 0) "true" else "false",
            if (self.config.max_clones_per_ip_net != 0) "true" else "false",
            if (self.config.reputation_refuse_threshold != 0) "true" else "false",
            if (self.config.dnsbl != null) "true" else "false",
        }) catch return w.buffered();
        w.print(",\"mesh\":{{\"quorum\":{s},\"partitioned\":{s},\"components\":{d}}}", .{
            if (self.partition_quorum) "true" else "false",
            if (self.partition_split) "true" else "false",
            self.partition_components,
        }) catch return w.buffered();
        const relay_v2_roster_digest = std.fmt.bytesToHex(
            self.relay_v2_activation_state.roster_digest,
            .lower,
        );
        w.print(",\"relay_v2\":{{\"bridge_implemented\":true,\"authoring\":\"{s}\",\"authoring_eligible\":{s},\"activation_epoch\":{d},\"roster_count\":{d},\"roster_digest\":", .{
            @tagName(self.relay_v2_activation_state.mode),
            if (self.authoredRelayV2Configured()) "true" else "false",
            self.relay_v2_activation_state.activation_epoch,
            self.config.relay_v2_roster.len,
        }) catch return w.buffered();
        if (self.relay_v2_activation_state.activation_epoch == 0) {
            w.writeAll("null") catch return w.buffered();
        } else {
            w.print("\"{s}\"", .{&relay_v2_roster_digest}) catch return w.buffered();
        }
        w.writeAll("}") catch return w.buffered();
        w.writeAll(",\"mesh_admission\":{\"mode\":") catch return w.buffered();
        writeJsonEscaped(&w, self.meshAdmissionMode()) catch return w.buffered();
        w.print(",\"secured_s2s\":{s},\"require_secured\":{s},\"require_signed_frames\":{s},\"roots\":{d},\"token_present\":{s},\"min_revocation_epoch\":{d}}}", .{
            if (self.s2sSecured()) "true" else "false",
            if (self.config.require_secured) "true" else "false",
            if (self.config.s2s_config.require_signed_frames) "true" else "false",
            self.meshpass_roots.len,
            if (self.mesh_admission_token.len != 0) "true" else "false",
            self.config.mesh_admission_min_revocation_epoch,
        }) catch return w.buffered();
        const kt_status = if (self.account_services) |svc|
            svc.keyTransparencyStatus()
        else
            services_mod.Services.KeyTransparencyStatus{ .enabled = false };
        w.writeAll(",\"accounts\":{\"key_transparency\":{\"enabled\":") catch return w.buffered();
        w.writeAll(if (kt_status.enabled) "true" else "false") catch return w.buffered();
        w.writeAll(",\"available\":") catch return w.buffered();
        w.writeAll(if (kt_status.available) "true" else "false") catch return w.buffered();
        w.writeAll(",\"semantics\":\"observational\",\"scope\":\"node-local\"") catch return w.buffered();
        w.print(",\"entries\":{d},\"root\":", .{kt_status.entries}) catch return w.buffered();
        if (kt_status.enabled and kt_status.available) {
            const root_hex = std.fmt.bytesToHex(kt_status.root, .lower);
            w.print("\"{s}\"", .{&root_hex}) catch return w.buffered();
        } else {
            w.writeAll("null") catch return w.buffered();
        }
        w.writeAll("}}") catch return w.buffered();
        const history_root_hex = std.fmt.bytesToHex(self.history.root(), .lower);
        w.print(",\"history\":{{\"targets\":{d},\"entries\":{d},\"tombstones\":{d},\"root\":\"{s}\"}}", .{
            self.history.targetCount(),
            self.history.totalStoredCount(),
            self.history.tombstoneCount(),
            &history_root_hex,
        }) catch return w.buffered();

        w.writeAll(",\"peers\":[") catch return w.buffered();
        var first = true;
        for (self.peer_health.entries.items) |*slot| {
            const h = &slot.health;
            if (!first) w.writeAll(",") catch return w.buffered();
            first = false;
            w.writeAll("{\"name\":") catch return w.buffered();
            writeJsonEscaped(&w, slot.name()) catch return w.buffered();
            w.print(",\"state\":\"{s}\"", .{peerStatusString(h.state)}) catch return w.buffered();
            w.print(",\"up\":{s}", .{if (h.state == .established) "true" else "false"}) catch return w.buffered();
            if (h.ewma_rtt_ms) |rtt| {
                w.print(",\"rtt_ms\":{d}", .{@as(u64, @intFromFloat(@max(0, rtt)))}) catch return w.buffered();
            } else {
                w.writeAll(",\"rtt_ms\":null") catch return w.buffered();
            }
            w.print(",\"since_seconds\":{d}", .{@divTrunc(h.since(now_mono), 1000)}) catch return w.buffered();
            w.writeAll("}") catch return w.buffered();
        }
        w.writeAll("]}") catch return w.buffered();
        return w.buffered();
    }

    fn writeStatsFileAtomic(io: anytype, dir: []const u8, name: []const u8, data: []const u8) void {
        _ = writeFileAtomicStatus(io, dir, name, data);
    }

    fn writeFileAtomicStatus(io: anytype, dir: []const u8, name: []const u8, data: []const u8) bool {
        var path_buf: [1024]u8 = undefined;
        const path = std.fmt.bufPrint(&path_buf, "{s}/{s}", .{ dir, name }) catch return false;
        var atomic = std.Io.Dir.cwd().createFileAtomic(io, path, .{ .replace = true }) catch return false;
        defer atomic.deinit(io);
        atomic.file.writeStreamingAll(io, data) catch return false;
        atomic.file.sync(io) catch return false;
        atomic.replace(io) catch return false;
        // Windows has no directory fsync through std.Io; the file has been
        // flushed and the atomic replacement has already completed.
        if (comptime builtin.os.tag != .windows) syncIoDir(atomic.dir, io) catch return false;
        return true;
    }

    fn syncIoDir(dir: std.Io.Dir, io: std.Io) !void {
        var dir_file = try dir.openFile(io, ".", .{ .mode = .read_only, .allow_directory = true });
        defer dir_file.close(io);
        try dir_file.sync(io);
    }

    /// Apply any TEMPMODE reverts whose timer has elapsed as real `-mode` MODE
    /// changes broadcast to the channel, then drop the spent entries.
    fn sweepTempModes(self: *LinuxServer) void {
        if (self.temp_modes.len() == 0) return;
        const now = self.nowMs();
        var actions: [32]svc_tempmode.RevertAction = undefined;
        while (true) {
            const n = self.temp_modes.due(now, &actions);
            if (n == 0) break;
            for (actions[0..n]) |action| {
                const mode = channelFlagFromLetter(action.mode_letter) orelse continue;
                if (!self.world.channelExists(action.channel)) continue;
                _ = self.world.setChannelFlag(action.channel, mode, false) catch continue;
                var buf: [128]u8 = undefined;
                const line = std.fmt.bufPrint(&buf, ":{s} MODE {s} -{c}\r\n", .{ self.serverName(), action.channel, action.mode_letter }) catch continue;
                self.broadcastChannel(action.channel, line, null) catch {};
            }
            _ = self.temp_modes.sweep(now);
            if (n < actions.len) break; // batch drained
        }
    }

    /// Reactor 0 delivers each due deferred job once. `claimDue` marks the job
    /// fired before this sends, so a later tick or a USR2 replay cannot send it
    /// again. The body is the memo stored at schedule time; history records the
    /// same body when the send happens.
    fn sweepDeferredDeliveries(self: *LinuxServer) void {
        if (!self.isMaintenanceReactor()) return;
        const wall = self.meshWallMs();
        const now: i64 = if (wall > @as(u64, std.math.maxInt(i64))) std.math.maxInt(i64) else @intCast(wall);
        var due: [schedule_snapshot.max_jobs]schedule_snapshot.Fired = undefined;
        const n = self.schedules.claimDue(now, &due);
        for (due[0..n]) |job| self.deliverScheduled(job);
    }

    fn deliverScheduled(self: *LinuxServer, job: schedule_snapshot.Fired) void {
        const pending = self.memo.pending(job.keySlice());
        if (pending.len == 0) return;
        const src = pending[0].text;
        if (src.len == 0 or src.len > 512) return;
        var body_buf: [512]u8 = undefined;
        @memcpy(body_buf[0..src.len], src);
        const body = body_buf[0..src.len];
        const target = job.targetSlice();
        if (!self.world.channelExists(target)) return;
        const sender = job.senderSlice();
        var msgid_buf: [17]u8 = undefined;
        msgid_buf[0] = 's';
        const hex = "0123456789abcdef";
        var shift: u6 = 60;
        var hi: usize = 0;
        while (hi < 16) : (hi += 1) {
            msgid_buf[1 + hi] = hex[@as(usize, @intCast((job.id >> shift) & 0xf))];
            if (shift >= 4) shift -= 4;
        }
        var pfx_buf: [80]u8 = undefined;
        const pfx = std.fmt.bufPrint(&pfx_buf, "{s}!{s}@deferred", .{ sender, sender }) catch return;
        const stamp = self.meshWallMs();
        if (job.kind == schedule_snapshot.kind_channel) {
            var line_buf: [800]u8 = undefined;
            const line = std.fmt.bufPrint(&line_buf, ":{s} PRIVMSG {s} :{s}\r\n", .{ pfx, target, body }) catch return;
            self.broadcastChannel(target, line, null) catch {};
            self.recordHistoryRelayAt(target, pfx, &msgid_buf, "PRIVMSG", body, null, stamp);
            return;
        }
        const mode = channelFlagFromLetter(job.mode) orelse return;
        _ = self.world.setChannelFlag(target, mode, true) catch return;
        var line_buf: [160]u8 = undefined;
        const line = std.fmt.bufPrint(&line_buf, ":{s} MODE {s} +{c}\r\n", .{ self.serverName(), target, job.mode }) catch return;
        self.broadcastChannel(target, line, null) catch {};
        self.recordHistoryRelayAt(target, pfx, &msgid_buf, "MODE", body, null, stamp);
    }

    /// Map a channel flag-mode letter to its `ChannelMode`, or null if the letter
    /// is not a supported boolean channel flag (TEMPMODE handles flags only).
    fn channelFlagFromLetter(letter: u8) ?world_model.ChannelMode {
        return switch (letter) {
            'i' => .invite_only,
            'm' => .moderated,
            'n' => .no_external,
            't' => .topic_ops,
            's' => .secret,
            'C' => .no_ctcp,
            'T' => .no_notice,
            'N' => .no_nick,
            'g' => .free_invite,
            'S' => .tls_only,
            'M' => .mod_reg,
            else => null,
        };
    }

    /// Drop connections that have not completed registration within the
    /// configured window. (Idle/ping timeouts for registered clients build on
    /// this same sweep.)
    fn sweepTimeouts(self: *LinuxServer) void {
        const now = self.nowMs();
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            const c = entry.value;
            if (c.closing) {
                if (c.s2s_dedup_drain_deadline_ms != 0) self.progressS2sDedupDrain(c);
                continue;
            }
            if (c.s2s != null or c.s2s_secured != null) {
                // TCP ESTABLISHED is not peer liveness: a vanished/restarted peer
                // can leave a half-open socket indefinitely. RTT probes below set
                // one outstanding application-level receipt barrier; any bytes
                // received on the already-authenticated stream clear it in
                // handleRecv. Actively shutdown
                // an expired link so its armed recv completes and normal close /
                // retained anti-entropy / redial recovery runs.
                if (self.s2sPeerLivenessExpired(c, now)) {
                    self.logMeshEvent(.peer_down, establishedPeerName(c) orelse "pending-peer", "mesh liveness probe timed out");
                    self.closeConn(c.token, "Mesh liveness timeout") catch {};
                }
                continue;
            }
            // Per-class timeout overrides (0 = inherit the `[limits]` global). The
            // default class_policy on an unregistered conn inherits the global,
            // which is correct — the class is not matched until registration.
            const reg_deadline = if (c.class_policy.register_timeout_ms != 0) @as(i64, @intCast(c.class_policy.register_timeout_ms)) else self.config.registration_timeout_ms;
            const ping_interval = if (c.class_policy.ping_interval_ms != 0) @as(i64, @intCast(c.class_policy.ping_interval_ms)) else self.config.ping_interval_ms;
            const ping_grace = if (c.class_policy.ping_timeout_ms != 0) @as(i64, @intCast(c.class_policy.ping_timeout_ms)) else self.config.ping_timeout_ms;

            if (!c.session.registered()) {
                // Unregistered: enforce the registration handshake window.
                if (now - c.connected_at_ms <= reg_deadline) continue;
                // Queue the ERROR and mark closing; the existing send-drain path
                // (handleSend) calls closeConn for the proper io_uring-integrated
                // teardown (shutdown in-flight recv, free slot). Never closeFd here.
                self.penalizePeer(c, self.config.reg_timeout_penalty);
                emitServerLine(c, "ERROR :Registration timeout");
                c.close_reason = "Registration timeout";
                c.closing = true;
                self.armSendIfNeeded(c) catch {};
                continue;
            }

            // Nick protection: a registered nick held by an unauthenticated user
            // is force-renamed to a Guest nick once the grace window elapses. The
            // policy is the OWNER account's per-account SECURE/ENFORCE settings
            // (svc_enforce); the mechanism (guest-nick generation) stays in
            // nick_enforcement. The owner account name equals the registered nick.
            // Self-clears once the user identifies. Default (no flags set) keeps
            // today's always-on enforcement.
            if (c.nick_claimed_at_ms != 0) {
                const owner_nick = c.session.displayName();
                const authed_owner = if (c.session.account()) |a|
                    std.ascii.eqlIgnoreCase(a, owner_nick)
                else
                    false;
                const grace_secs: u32 = @intCast(@max(@as(i64, 0), self.config.nick_grace_ms) / 1000);
                const settings: svc_enforce.AccountSecurity = if (self.account_services) |svc|
                    svc.accountSecurity(owner_nick, grace_secs)
                else
                    .{ .enforce = true, .enforce_seconds = grace_secs };
                // Soft host-recognition (svc_acclist / RECOGNIZE): an unauthenticated
                // holder whose nick!user@host matches the owner account's recognition
                // list keeps the nick past the grace — but gains NO account privileges
                // (session.account stays null; only SASL grants those).
                const access_match = if (self.account_services) |svc| blk: {
                    var mb: [320]u8 = undefined;
                    const mask = std.fmt.bufPrint(&mb, "{s}!{s}@{s}", .{ owner_nick, c.session.username(), hostOf(c) }) catch break :blk false;
                    break :blk svc.recognizeMatches(owner_nick, mask);
                } else false;
                switch (svc_enforce.decide(settings, .{
                    .identified = authed_owner,
                    .access_match = access_match,
                    .claimed_at_ms = c.nick_claimed_at_ms,
                    .now_ms = now,
                })) {
                    .recognized, .allow => c.nick_claimed_at_ms = 0,
                    .warn => {},
                    .enforce => {
                        var gbuf: [32]u8 = undefined;
                        const seed: u64 = @as(u64, @bitCast(entry.id)) & 0xFFFFFF;
                        if (nick_enforcement.guestNick(&gbuf, seed)) |guest| {
                            self.forceRenameTo(entry.id, c, guest);
                            self.armSendIfNeeded(c) catch {};
                        } else |_| {}
                        c.nick_claimed_at_ms = 0;
                    },
                }
            }

            // Registered: idle clients get a server PING; if the grace elapses
            // with no inbound traffic the connection is dropped (Ping timeout).
            if (c.awaiting_pong) {
                if (now - c.ping_sent_ms <= ping_grace) continue;
                emitServerLine(c, "ERROR :Ping timeout");
                c.close_reason = "Ping timeout";
                c.closing = true;
                self.armSendIfNeeded(c) catch {};
                continue;
            }
            if (now - c.last_activity_ms <= ping_interval) continue;
            emitPing(c);
            c.awaiting_pong = true;
            c.ping_sent_ms = now;
            self.armSendIfNeeded(c) catch {};
        }
    }

    pub fn s2sBoundPort(self: *LinuxServer) !u16 {
        if (self.reactors[0].s2s_listener_fd < 0) return error.Unsupported;
        return socketPort(self.reactors[0].s2s_listener_fd);
    }

    pub fn tlsBoundPort(self: *LinuxServer) !u16 {
        if (self.rx().tls_listener_fd < 0) return error.Unsupported;
        return socketPort(self.rx().tls_listener_fd);
    }

    pub fn wsBoundPort(self: *LinuxServer) !u16 {
        if (self.rx().ws_listener_fd < 0) return error.Unsupported;
        return socketPort(self.rx().ws_listener_fd);
    }

    /// Process at least one io_uring completion. Callers may loop this until
    /// their own stop condition is satisfied.
    pub fn runOnce(self: *LinuxServer) !void {
        if (comptime builtin.is_test) {
            if (self.reactor_fail_for_test) return error.ReactorGiveUp;
            if (current_reactor) |r| {
                if (self.reactor_poison_shard_for_test.load(.acquire) == r.shard_id)
                    return error.BackendPoisoned;
            }
        }
        // Bind this thread to its reactor so every handler's rx() resolves to the
        // reactor whose ring produced the completions. A multi-reactor worker has
        // already bound its own shard before looping (so we never clobber it);
        // single-reactor callers and direct-test invocations bind shard 0 here.
        if (current_reactor == null) current_reactor = &self.reactors[0];
        // Control SQEs always win the turn. Helix activation and mesh connects
        // are deliberately staged below them so a full inherited population can
        // neither wedge accept/wake/timer nor drop quiet clients on SQ-full.
        try self.armAccept();
        self.armWake() catch {}; // cross-reactor wake poll; non-fatal if it can't arm
        self.armTimer() catch {}; // periodic timeout sweep; non-fatal if it can't arm
        _ = try self.activatePendingSocketIo();
        if (self.rx() == &self.reactors[0]) {
            if (self.activateInheritedMeshRedials(1)) self.wakeReactor();
            if (!self.mesh_dials_booted) {
                self.mesh_dials_booted = self.sweepMeshAutoConnect(true, 1);
                if (!self.mesh_dials_booted) self.wakeReactor();
            }
        }
        _ = try self.rx().ring.submitAndWait(1);

        var handler = CompletionHandler{ .server = self };
        var cqes: [ringlane.max_cqe_batch]reactor_backend.CompletionBuffer = undefined;
        const cqe_batch = @min(@as(usize, self.config.cqe_batch), cqes.len);
        _ = try self.rx().ring.reapCompletions(cqes[0..cqe_batch], 0, &handler);
        if (handler.err) |err| return err;

        if (comptime builtin.os.tag == .windows) {
            // The one listener owner hands off accepted sockets before they
            // have an IOCP association. Admit on the destination owner thread
            // so its first receive binds the socket to that shard's port.
            var first_accept_error: ?anyerror = null;
            while (self.rx().windows_accepted.pop()) |accepted| {
                self.world.lockWrite();
                self.handleAccept(accepted) catch |err| {
                    if (first_accept_error == null) first_accept_error = err;
                };
                self.world.unlockWrite();
            }
            if (first_accept_error) |err| return err;
        }

        // Belt-and-suspenders against a lost wake: drain any cross-shard handoffs
        // addressed to this reactor every iteration, not only on the wake-poll
        // completion. Cheap when empty (one lock-free pop returning 0). Each
        // reactor drains only its own mailbox into its own connections, so this is
        // reactor-local and needs no world lock. No-op in single-reactor mode.
        if (self.fabric != null) {
            // This fallback drain can close a poisoned connection and therefore
            // mutate shared World/session state. Match the completion bracket's
            // serialization instead of touching it outside the World lock.
            self.world.lockWrite();
            self.abortPoisonedDeliveries();
            self.drainSessionDropControls();
            self.drainFabric();
            self.abortPoisonedDeliveries();
            self.world.unlockWrite();
        }

        // Drain any off-thread webhook posts addressed to reactor 0 and fan each
        // into its channel on-thread. Cheap when empty (one lock-free pop).
        self.drainWebhookPosts();

        _ = try self.rx().ring.submit();
        // UPGRADE is deliberately deferred past the complete copied CQE batch,
        // the final fabric drain, and submission of same-turn SQEs. Starting it
        // inside a timer/command callback would snapshot state before later CQEs
        // already copied from the ring had updated recv/send ownership.
        self.runDeferredUpgrade();
    }

    fn deferUpgrade(self: *LinuxServer, request: DeferredUpgradeRequest) void {
        if (comptime builtin.os.tag == .windows) {
            lockSpin(&self.windows_upgrade_priority_lock);
            defer self.windows_upgrade_priority_lock.unlock();
            // A manual request is published while holding the same lock used by
            // the automatic candidate claim. An earlier manual request wins,
            // even when its owner is another reactor or already handing off.
            if (std.meta.activeTag(request) == .windows_descriptor_rollover and
                self.windows_manual_upgrade_pending != 0) return;
            if (self.rx().deferred_upgrade) |pending| {
                switch (pending) {
                    .windows_descriptor_rollover => {
                        self.rx().deferred_upgrade = request;
                        if (std.meta.activeTag(request) != .windows_descriptor_rollover) {
                            self.windows_manual_upgrade_pending += 1;
                            self.rx().deferred_upgrade_counted = true;
                        }
                    },
                    else => {},
                }
            } else {
                if (std.meta.activeTag(request) != .windows_descriptor_rollover) {
                    self.windows_manual_upgrade_pending += 1;
                    self.rx().deferred_upgrade_counted = true;
                }
                self.rx().deferred_upgrade = request;
            }
            return;
        }
        if (self.rx().deferred_upgrade) |pending| {
            // A human request or SIGUSR2 received later in the same CQE batch
            // takes precedence over an automatic rollover attempt.
            switch (pending) {
                .windows_descriptor_rollover => self.rx().deferred_upgrade = request,
                else => {},
            }
        } else self.rx().deferred_upgrade = request;
    }

    fn finishCountedManualUpgrade(self: *LinuxServer) void {
        if (comptime builtin.os.tag != .windows) return;
        lockSpin(&self.windows_upgrade_priority_lock);
        defer self.windows_upgrade_priority_lock.unlock();
        std.debug.assert(self.windows_manual_upgrade_pending != 0);
        self.windows_manual_upgrade_pending -= 1;
    }

    fn discardDeferredUpgrade(self: *LinuxServer, reactor: *Reactor) void {
        if (reactor.deferred_upgrade) |request| switch (request) {
            .client_target => |target| self.allocator.free(target.executable),
            else => {},
        };
        reactor.deferred_upgrade = null;
        if (reactor.deferred_upgrade_counted) self.finishCountedManualUpgrade();
        reactor.deferred_upgrade_counted = false;
    }

    fn noteWindowsDescriptorRolloverAttempt(self: *LinuxServer, now_ms: i64) void {
        self.windows_descriptor_rollover_retry_after_ms = std.math.add(
            i64,
            @max(@as(i64, 0), now_ms),
            windows_descriptor_rollover_retry_ms,
        ) catch std.math.maxInt(i64);
    }

    fn windowsRolloverSmokeMode(self: *LinuxServer) ?WindowsRolloverSmokeMode {
        if (comptime builtin.os.tag != .windows or !build_info.windows_rollover_smoke) return null;
        const config_path = self.config.config_path orelse return null;
        const io = self.runtime_io orelse self.config.crypto_io orelse return null;
        var path_buf: [4096]u8 = undefined;
        const path = std.fmt.bufPrint(&path_buf, "{s}.rollover-smoke", .{config_path}) catch return null;
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, path, self.allocator, .limited(64)) catch return null;
        defer self.allocator.free(bytes);
        return parseWindowsRolloverSmokeMarker(bytes, @bitCast(platform.currentPid()));
    }

    /// Only reactor 0 may queue this maintenance request. A failed candidate
    /// keeps serving and is retried at most once per minute, well before either
    /// process-local ID namespace reaches exhaustion. Helix imports live IDs;
    /// retired predecessor IDs disappear only when that process exits.
    fn maybeDeferWindowsDescriptorRollover(self: *LinuxServer, now_ms: i64, socket_due: bool, file_due: bool) bool {
        if (comptime builtin.os.tag != .windows) return false;
        if (!self.isMaintenanceReactor() or (!socket_due and !file_due) or
            now_ms < self.windows_descriptor_rollover_retry_after_ms) return false;
        lockSpin(&self.windows_upgrade_priority_lock);
        if (self.windows_manual_upgrade_pending != 0 or
            self.rx().deferred_upgrade != null or
            self.windows_helix_upgrade_claimed.load(.acquire))
        {
            self.windows_upgrade_priority_lock.unlock();
            return false;
        }
        self.rx().deferred_upgrade = .windows_descriptor_rollover;
        self.windows_upgrade_priority_lock.unlock();
        self.noteWindowsDescriptorRolloverAttempt(now_ms);
        srvLog(
            "onyx-server: Windows descriptor ID rollover due (socket={any}, file={any}); scheduling pinned-image Helix UPGRADE, with 60s retry interval\n",
            .{ socket_due, file_due },
        );
        return true;
    }

    /// Run only after `runOnce` dispatched the entire copied CQE batch. The
    /// requester is a generational id rather than a borrowed pointer; if it
    /// disconnected later in that same batch the upgrade remains valid and its
    /// progress falls back to the server log.
    fn runDeferredUpgrade(self: *LinuxServer) void {
        if (comptime builtin.is_test) {
            if (self.rx() == &self.reactors[0]) {
                const capture_ptr = self.test_live_upgrade_capture_ptr.swap(0, .acq_rel);
                if (capture_ptr != 0) {
                    const capture: *TestLiveUpgradeCapture = @ptrFromInt(capture_ptr);
                    self.captureLiveUpgradeForTest(capture) catch |err| {
                        capture.failure = err;
                        capture.completed.store(true, .release);
                    };
                    return;
                }
            }
        }
        const request = self.rx().deferred_upgrade orelse return;
        const was_counted = self.rx().deferred_upgrade_counted;
        self.rx().deferred_upgrade = null;
        self.rx().deferred_upgrade_counted = false;
        defer if (was_counted) self.finishCountedManualUpgrade();
        defer switch (request) {
            .client_target => |target| self.allocator.free(target.executable),
            else => {},
        };
        self.performUpgrade(request) catch |err| {
            switch (request) {
                .windows_descriptor_rollover => {
                    self.noteWindowsDescriptorRolloverAttempt(self.nowMs());
                    srvLog("onyx-server: Windows descriptor rollover UPGRADE failed ({s}); will retry no sooner than 60s\n", .{@errorName(err)});
                },
                else => srvLog("onyx-server: deferred UPGRADE failed: {s}\n", .{@errorName(err)}),
            }
        };
    }

    fn requestLiveUpgradeCaptureForTest(self: *LinuxServer, capture: *TestLiveUpgradeCapture) !void {
        if (comptime !builtin.is_test) return error.Unsupported;
        if (capture.completed.load(.acquire)) return error.InvalidInheritedHandoff;
        if (self.test_live_upgrade_capture_ptr.cmpxchgStrong(
            0,
            @intFromPtr(capture),
            .acq_rel,
            .acquire,
        ) != null) return error.SessionReplicaConverging;
        self.wakeAllReactors();
    }

    /// Execute the real socket-owner safe point and production sealers, stopping
    /// just before exec planning. Success transfers the exact carried descriptor
    /// set out of the predecessor and stops its loop without rearming I/O; the
    /// test harness then boots a fresh Server and exercises normal adoption.
    fn captureLiveUpgradeForTest(self: *LinuxServer, capture: *TestLiveUpgradeCapture) !void {
        if (comptime !builtin.is_test) return error.Unsupported;
        if (self.rx() != &self.reactors[0]) return error.ShardQuiesceFailed;
        const run = self.shutdown orelse return error.InvalidInheritedHandoff;

        try self.quiesceSiblingReactors();
        var owns_quiesce = true;
        errdefer if (owns_quiesce) self.resumeSiblingReactors();

        self.world.lockWrite();
        if (self.upgradeContinuityBlockerLocked() != null) {
            self.world.unlockWrite();
            return error.SessionReplicaConverging;
        }
        var boundary_stable = false;
        const boundary_rounds = @max(@as(usize, 2), self.config.max_clients + self.reactors.len);
        var boundary_round: usize = 0;
        while (boundary_round < boundary_rounds) : (boundary_round += 1) {
            const replica_ready = self.prepareSessionReplicaUpgradeBoundary();
            const progress = self.drainAllUpgradeFabricFixedPointLocked() catch |err| {
                self.world.unlockWrite();
                return err;
            };
            if (replica_ready and progress == 0) {
                boundary_stable = true;
                break;
            }
        }
        self.world.unlockWrite();
        if (!boundary_stable) return error.SessionReplicaConverging;

        var blobs: std.ArrayList([]u8) = .empty;
        defer {
            for (blobs.items) |blob| self.allocator.free(blob);
            blobs.deinit(self.allocator);
        }
        var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
        defer pieces.deinit(self.allocator);
        try appendCurrentMandatoryUpgradeStateForTest(self, &pieces, &blobs);
        _ = self.sealSessionRegistry(&pieces, &blobs) orelse return error.SessionReplicaConverging;

        var total_slots: usize = 0;
        for (self.reactors) |*reactor| total_slots += reactor.clients.slots.items.len;
        const carried_fds = try self.allocator.alloc(linux.fd_t, total_slots);
        defer self.allocator.free(carried_fds);
        var carried_fd_count: usize = 0;
        // `sealShardClients` clears CLOEXEC incrementally. Always unwind the
        // exact accrued prefix, including failures before capture publication.
        errdefer restoreCloexec(carried_fds[0..carried_fd_count]);
        var counts = SealCounts{};
        for (self.reactors) |*reactor|
            self.sealShardClients(reactor, &pieces, &blobs, carried_fds, &carried_fd_count, &counts);
        capture.state_fd_count = carried_fd_count;
        if (counts.s2s_preserve_failed or counts.s2s_hint_failed or counts.fd_prepare_failed or
            counts.clients != counts.clients_expected or
            carried_fd_count > TestLiveUpgradeCapture.max_state_fds)
            return error.SessionReplicaConverging;

        var prepared = try helix_live.prepare(self.allocator, .{
            .epoch = @intCast(@max(0, self.nowMs())),
            .now_ms = self.nowMs(),
            .timeout_ms = 5_000,
            .arena_name = "onyx-test-live-upgrade",
            .pieces = pieces.items,
            .fds = &.{},
        });
        defer prepared.deinit();
        const arena = prepared.runtime.arena orelse return error.SessionReplicaConverging;
        capture.arena_fd = try os_runtime.duplicate(arena.fd);
        errdefer {
            closeFd(capture.arena_fd);
            capture.arena_fd = -1;
        }

        @memcpy(capture.state_fds[0..carried_fd_count], carried_fds[0..carried_fd_count]);
        capture.clients = counts.clients;
        capture.s2s_preserved = counts.s2s_preserved;

        // execve would discard the predecessor without running destructors. The
        // in-process seam explicitly relinquishes the transferred fds so its
        // later deinit cannot close sockets already adopted by the successor.
        var ownership_matches: usize = 0;
        for (carried_fds[0..carried_fd_count]) |fd| {
            var fd_matches: usize = 0;
            for (self.reactors) |*reactor| {
                for (reactor.clients.slots.items) |*slot| {
                    if (slot.occupied and slot.value.fd == fd) fd_matches += 1;
                }
            }
            if (fd_matches != 1) return error.InvalidInheritedHandoff;
            ownership_matches += 1;
        }
        if (ownership_matches != carried_fd_count) return error.InvalidInheritedHandoff;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                for (carried_fds[0..carried_fd_count]) |fd| {
                    if (slot.value.fd == fd) {
                        slot.value.fd = -1;
                        break;
                    }
                }
            }
        }

        owns_quiesce = false;
        run.store(false, .release);
        // execve would terminate every parked sibling. The in-process seam must
        // release only the park loop (with `run=false`) so workers exit without
        // rearming any transferred socket before the harness joins them.
        self.upgrade_quiesce_shard.store(no_quiesce_shard, .release);
        self.wakeAllReactors();
        capture.completed.store(true, .release);
    }

    pub fn boundPort(self: *LinuxServer) !u16 {
        return socketPort(self.rx().listener_fd);
    }

    /// Deterministic native Helix listener custody: shard order, primary roles,
    /// then companion roles. Call under the upgrade owner barrier before
    /// transferring rights; this method neither arms I/O nor changes flags.
    pub fn collectListenerManifest(self: *LinuxServer, allocator: std.mem.Allocator) ![]ListenerDescriptor {
        var count: usize = 0;
        for (self.reactors) |*r| for (r.acceptOps()) |op| {
            if (op.fd >= 0) count += 1;
        };
        const rows = try allocator.alloc(ListenerDescriptor, count);
        errdefer allocator.free(rows);
        var index: usize = 0;
        for (self.reactors) |*r| for (r.acceptOps()) |op| {
            if (op.fd < 0) continue;
            const family: ListenerFamily = if (comptime builtin.os.tag == .windows) blk: {
                const observed = io_backend.observeWindowsListeningTcpSocket(op.fd) catch return error.InvalidInheritedListener;
                break :blk switch (observed.local.address) {
                    .ipv4 => .ipv4,
                    .ipv6 => .ipv6,
                };
            } else blk: {
                var address: posix.sockaddr.storage = undefined;
                var len: posix.socklen_t = @sizeOf(posix.sockaddr.storage);
                if (posix.errno(socket_system.getsockname(op.fd, @ptrCast(&address), &len)) != .SUCCESS)
                    return error.InvalidInheritedListener;
                break :blk switch (address.family) {
                    posix.AF.INET => .ipv4,
                    posix.AF.INET6 => .ipv6,
                    else => return error.InvalidInheritedListener,
                };
            };
            for (rows[0..index]) |prior| if (prior.fd == op.fd) return error.InvalidInheritedListener;
            rows[index] = .{ .shard = r.shard_id, .kind = op.kind, .family = family, .fd = op.fd };
            index += 1;
        };
        return rows;
    }

    /// Allocate the complete configured fabric at the final Server address.
    /// Failure leaves the candidate's live resources/run flag unchanged; no
    /// reactor or command can run until the complete shared Gate is released.
    pub fn prepareRuntimeResources(self: *LinuxServer, io: std.Io, run: *reactor_pool_mod.RunFlag) !void {
        const phase = self.runtime_phase.load(.acquire);
        if (phase != .idle and phase != .joined) return error.RuntimeAlreadyPrepared;
        if (self.pool.count() != 0 or self.runtime_gate != null) return error.RuntimeAlreadyPrepared;
        if (!run.load(.acquire) or self.reactors.len == 0) return error.InvalidRuntime;
        if (self.reactors.len == 1) {
            if (self.fabric != null) return error.InvalidRuntime;
        } else if (self.fabric) |*fabric| {
            if (fabric.inboxes.len != self.reactors.len or fabric.controls.len != self.reactors.len or
                fabric.wakes.len != self.reactors.len or fabric.pools.len != self.reactors.len)
                return error.InvalidRuntime;
        } else {
            // Detached fallible construction, then one no-fail ownership move.
            const candidate = try reactor_fabric.ReactorFabric.init(self.allocator, self.reactors.len);
            self.fabric = candidate;
        }
        for (self.reactors) |*reactor| reactor.runtime_activated.store(false, .release);
        self.shutdown = run;
        self.runtime_io = io;
        self.runtime_phase.store(.resources, .release);
    }

    /// Prepare actual reactor workers under MAIN's one runtime-wide Gate.
    /// Single-shard is an explicit inline owner with zero reactor worker rows.
    /// Any partial spawn error cancels/joins the entire candidate Gate before
    /// main is permitted to free any borrowed companion or Server context.
    pub fn prepareRuntimeWorkers(self: *LinuxServer, control: *reactor_pool_mod.runtime_start_gate.Control, view: *const reactor_pool_mod.runtime_start_gate.View, slots: []const reactor_pool_mod.runtime_start_gate.Slot) !void {
        try control.requireView(view);
        if (self.runtime_phase.load(.acquire) != .resources or self.runtime_gate != null) return error.RuntimeNotPrepared;
        if (view.inspect().phase != .preparing) return error.RuntimeNotPreparing;
        const run = self.shutdown orelse return error.RuntimeNotPrepared;
        if (self.reactors.len == 1) {
            if (slots.len != 0 or self.fabric != null or self.pool.count() != 0) return error.InvalidRuntime;
        } else {
            if (slots.len != self.reactors.len or self.fabric == null) return error.InvalidRuntime;
            try self.pool.prepareDormant(control, view, slots, self, run, reactorWorker);
        }
        self.runtime_gate = view;
        self.runtime_phase.store(.workers, .release);
    }

    /// Observe the creator's actual joins, then drop borrowed View references.
    /// This does not cancel or join a handle and cannot release another owner.
    pub fn detachRuntimeAfterJoined(self: *LinuxServer) !void {
        if (self.runtime_gate) |view| try view.requireAllJoined();
        try self.pool.detachAfterJoined();
        self.runtime_gate = null;
    }

    /// Real core resources and all actual Gate arrivals. Main additionally
    /// joins every configured companion/resource/state row before native READY.
    pub fn requirePreparedRuntime(self: *const LinuxServer) !void {
        if (self.runtime_phase.load(.acquire) != .workers or self.runtime_io == null or self.shutdown == null) return error.RuntimeNotPrepared;
        const gate = self.runtime_gate orelse return error.RuntimeNotPrepared;
        try gate.requireAllParked();
        if (self.reactors.len == 1) {
            if (self.fabric != null or self.pool.count() != 0) return error.InvalidRuntime;
        } else {
            const fabric = self.fabric orelse return error.InvalidRuntime;
            if (fabric.inboxes.len != self.reactors.len or fabric.controls.len != self.reactors.len or
                fabric.wakes.len != self.reactors.len or fabric.pools.len != self.reactors.len)
                return error.InvalidRuntime;
            try self.pool.requireParked();
        }
        for (self.reactors) |*reactor| {
            if (reactor.runtime_activated.load(.acquire)) return error.InvalidRuntime;
        }
    }

    /// Non-failing publication only after full preparation/adoption succeeds.
    /// Never opens the Gate; main publishes ALL owners before its one release.
    pub fn publishPreparedRuntime(self: *LinuxServer) void {
        self.requirePreparedRuntime() catch @panic("runtime publication without exact prepared owners");
        self.runtime_phase.store(.published, .release);
    }

    /// Standalone reactor-only owner. No allocation, bind, spawn or shard
    /// fallback is possible here. A configured whole graph instead lets its
    /// Runtime settle companions before the private Control joins all owners.
    pub fn runPreparedRuntime(self: *LinuxServer, control: *reactor_pool_mod.runtime_start_gate.Control, run: *reactor_pool_mod.RunFlag) void {
        if (self.runtime_phase.load(.acquire) != .published or self.shutdown != run or self.runtime_gate == null or
            self.runtime_gate.?.inspect().phase != .released)
        {
            self.runtimePreparationFailed(run, error.RuntimeNotPublished);
            return;
        }
        control.requireView(self.runtime_gate.?) catch |err| {
            self.runtimePreparationFailed(run, err);
            return;
        };
        const reactor_workers = if (self.reactors.len == 1) 0 else self.reactors.len;
        const metrics_owner: ?*metrics_http.MetricsServer = if (self.metrics_server) |*owner|
            if (owner.runtime.view == self.runtime_gate) owner else null
        else
            null;
        const webhook_owner: ?*webhook_http.WebhookServer = if (self.webhook_server) |*owner|
            if (owner.runtime.view == self.runtime_gate) owner else null
        else
            null;
        const history_owner: ?*history_http.HttpsListener = if (self.history_https) |*owner|
            if (owner.runtime_worker.view == self.runtime_gate) owner else null
        else
            null;
        const webtransport_owner: ?*managed_wt.WebTransportListener = if (self.windows_webtransport_owner) |owner|
            if (owner.runtime.view == self.runtime_gate) owner else null
        else
            null;
        const native_media_owner: ?*native_media_mod.NativeMediaTransport = if (self.native_media.runtime.view == self.runtime_gate) &self.native_media else null;
        const webrtc_media_owner: ?*media_plane_mod.MediaPlane = if (self.media_plane.runtime.view == self.runtime_gate) &self.media_plane else null;
        const rdns_owner: ?*rdns.Resolver = if (self.config.rdns) |owner|
            if (owner.runtime.view == self.runtime_gate) owner else null
        else
            null;
        const dnsbl_owner: ?*dnsbl_resolver.Resolver = if (self.config.dnsbl) |owner|
            if (owner.runtime.view == self.runtime_gate) owner else null
        else
            null;
        const webpush_owner: ?*webpush_mod.Worker = if (self.webpush_worker) |owner|
            if (owner.runtime.view == self.runtime_gate) owner else null
        else
            null;
        const geo_owner: ?*geo_services.Service = if (self.geo.runtime.view == self.runtime_gate) self.geo else null;
        const mail_owner: ?*mail_sender.Sender = if (self.config.mail_sender) |owner|
            if (owner.runtime.view == self.runtime_gate) owner else null
        else
            null;
        const acme_owner: ?*@import("acme_renewal.zig").Service = if (self.acme_worker) |owner|
            if (owner.runtime.view == self.runtime_gate) owner else null
        else
            null;
        const ocsp_owner: ?*managed_ocsp.Service = if (self.ocsp_worker) |owner|
            if (owner.runtime.view == self.runtime_gate) owner else null
        else
            null;
        const expected = reactor_workers + @intFromBool(metrics_owner != null) +
            @intFromBool(webhook_owner != null) + @intFromBool(rdns_owner != null) +
            @intFromBool(dnsbl_owner != null) + @intFromBool(history_owner != null) +
            @intFromBool(webtransport_owner != null) + @intFromBool(native_media_owner != null) +
            @intFromBool(webrtc_media_owner != null) +
            @intFromBool(webpush_owner != null) + @intFromBool(geo_owner != null) +
            @intFromBool(mail_owner != null) + @intFromBool(acme_owner != null) +
            @intFromBool(ocsp_owner != null);
        if (self.runtime_gate.?.inspect().expected != expected) {
            self.runtimePreparationFailed(run, error.InvalidRuntime);
            return;
        }
        if (self.reactors.len == 1) {
            current_reactor = &self.reactors[0];
            self.runLoopResilient(run);
        } else if (metrics_owner != null or webhook_owner != null or history_owner != null or webtransport_owner != null or native_media_owner != null or webrtc_media_owner != null or rdns_owner != null or dnsbl_owner != null or webpush_owner != null or geo_owner != null or mail_owner != null or acme_owner != null or ocsp_owner != null) {
            // Retained companions must not keep joinAll blocked after the
            // reactor fleet exits. Join the reactor rows first, then signal
            // the companion workers and join their exact Gate-owned handles.
            for (0..reactor_workers) |index| {
                const slot = self.runtime_gate.?.slot(.reactor, @intCast(index), self) catch @panic("missing Windows reactor slot");
                control.joinParticipant(slot) catch @panic("Windows reactor slot join failed");
            }
        }
        if (metrics_owner) |owner| owner.requestStopAndWake();
        if (webhook_owner) |owner| owner.requestStopAndWake();
        if (history_owner) |owner| owner.requestStopAndWake();
        if (webtransport_owner) |owner| owner.requestStopAndWake();
        if (native_media_owner) |owner| owner.requestStopAndWake();
        if (webrtc_media_owner) |owner| owner.requestStopAndWake();
        if (rdns_owner) |owner| owner.requestStopAndWake();
        if (dnsbl_owner) |owner| owner.requestStopAndWake();
        if (webpush_owner) |owner| owner.requestStopAndWake();
        if (geo_owner) |owner| owner.requestStopAndWake();
        if (mail_owner) |owner| owner.requestStopAndWake();
        if (acme_owner) |owner| owner.requestStopAndWake();
        if (ocsp_owner) |owner| owner.requestStopAndWake();
        control.joinAll();
        self.detachRuntimeAfterJoined() catch @panic("runtime returned before actual owner joins");
        self.runtime_phase.store(.joined, .release);
    }

    /// Existing standalone callers prepare their OWN complete reactor-only
    /// runtime before admission. Main's native transaction uses the explicit
    /// preparation APIs before READY and calls runPreparedRuntime after COMMIT.
    /// Preparation failure is terminal: it never runs a subset of the shards.
    pub fn runThreaded(self: *LinuxServer, run: *reactor_pool_mod.RunFlag) void {
        var local_io = std.Io.Threaded.init(std.heap.smp_allocator, .{});
        defer local_io.deinit();
        const io = self.config.crypto_io orelse local_io.io();
        self.prepareRuntimeResources(io, run) catch |err| {
            self.runtimePreparationFailed(run, err);
            return;
        };
        const gate_mod = reactor_pool_mod.runtime_start_gate;
        var specs: [shard_mod.max_shards]gate_mod.ParticipantSpec = undefined;
        var slots: [shard_mod.max_shards]gate_mod.Slot = undefined;
        const count = if (self.reactors.len == 1) 0 else self.reactors.len;
        for (specs[0..count], 0..) |*spec, index| spec.* = .{ .kind = .reactor, .instance = @intCast(index), .owner_identity = self };
        const gate = gate_mod.create(self.allocator, io, specs[0..count]) catch |err| {
            self.runtimePreparationFailed(run, err);
            return;
        };
        defer {
            if (gate.view.inspect().phase == .preparing) gate.control.cancelAllAndJoin() else {
                self.requestStop(run);
                gate.control.joinAll();
            }
            self.detachRuntimeAfterJoined() catch @panic("standalone runtime cleanup without actual joins");
            self.pool.deinit();
            self.pool = reactor_pool_mod.ReactorPool(*LinuxServer).init(self.allocator);
            gate.control.destroyJoined();
        }
        for (slots[0..count], 0..) |*slot, index| slot.* = gate.view.slot(.reactor, @intCast(index), self) catch unreachable;
        self.prepareRuntimeWorkers(gate.control, gate.view, slots[0..count]) catch |err| {
            self.runtimePreparationFailed(run, err);
            return;
        };
        gate.control.awaitAllParked(std.Io.Clock.Timestamp.fromNow(io, .{ .clock = .awake, .raw = .fromMilliseconds(30_000) })) catch |err| {
            self.runtimePreparationFailed(run, err);
            return;
        };
        self.publishPreparedRuntime();
        gate.control.releaseAll();
        self.runPreparedRuntime(gate.control, run);
    }

    fn runtimePreparationFailed(self: *LinuxServer, run: *reactor_pool_mod.RunFlag, err: anyerror) void {
        srvLog("onyx-server: complete runtime preparation failed ({s}); no reactor admitted\n", .{@errorName(err)});
        _ = self.runtime_failure.cmpxchgStrong(0, 3, .acq_rel, .acquire);
        self.requestStop(run);
    }

    /// Actual owner activation, published only after a successful backend loop
    /// turn, not from an arrival or a freely supplied service-ready boolean.
    pub fn requireActivatedRuntime(self: *const LinuxServer) !void {
        const run = self.shutdown orelse return error.RuntimeNotPrepared;
        if (!run.load(.acquire)) return error.RuntimeStopped;
        if (self.runtime_phase.load(.acquire) != .published) return error.RuntimeNotPublished;
        const gate = self.runtime_gate orelse return error.RuntimeNotPrepared;
        if (gate.inspect().phase != .released) return error.RuntimeNotPublished;
        if (self.runtimeFailure()) |err| return err;
        for (self.reactors) |*reactor| {
            if (!reactor.runtime_activated.load(.acquire)) return error.RuntimeNotActivated;
        }
        if (!run.load(.acquire)) return error.RuntimeStopped;
    }

    /// Inspect only after runThreaded joins every worker. Terminal I/O failure
    /// must reach the process exit status instead of looking like DIE/shutdown.
    pub fn runtimeFailure(self: *const LinuxServer) ?anyerror {
        return switch (self.runtime_failure.load(.acquire)) {
            0 => null,
            1 => error.BackendPoisoned,
            2 => error.ReactorGiveUp,
            else => error.RuntimePreparationFailed,
        };
    }

    fn stopFailedReactors(self: *LinuxServer, run: *std.atomic.Value(bool), failure: u8) void {
        const first = self.runtime_failure.cmpxchgStrong(0, failure, .acq_rel, .acquire) == null;
        // Keep backend-owned socket buffers and slots intact until deinit.
        // Wake all siblings, including any parked at the upgrade safe point.
        self.requestStop(run);
        if (first) self.flushFlightRecorder(.reactor, "reactor giving up after persistent errors");
    }

    /// One reactor worker thread: bind this thread to its shard's reactor, then
    /// loop `runOnce` (which arms accept/wake/timer and reaps completions) until
    /// the shared run flag clears. Each worker touches only its own reactor's ring
    /// and connection slab; cross-shard work crosses via the fabric.
    fn reactorWorker(self: *LinuxServer, shard: u12, run: *reactor_pool_mod.RunFlag) void {
        current_reactor = &self.reactors[shard];
        self.runLoopResilient(run);
    }

    /// Drive `runOnce` until the run flag clears. An error escaping runOnce is a
    /// bug (per-client faults are firewalled below), but it must not silently
    /// kill the reactor thread and take the shard's clients with it: log it and
    /// keep serving. Only a persistent failure — the loop erroring on every
    /// iteration with no successful completion in between — exits, since that
    /// means the ring itself is broken and spinning would burn the core.
    fn runLoopResilient(self: *LinuxServer, run: anytype) void {
        var consecutive_failures: u32 = 0;
        while (run.load(.acquire)) {
            // Multi-shard UPGRADE quiesce: while another reactor seals every
            // shard's connection state, park HERE — between loop turns, so this
            // worker holds no ring/slab state mid-mutation. The sealer's wake
            // (wakeAllReactors) pops this loop out of submitAndWait so the park
            // is reached within one turn. Resumes when the sealer clears the
            // flag (upgrade failed) or never (execve replaced the process).
            self.parkForUpgradeQuiesce(run);
            if (!run.load(.acquire)) break;
            if (self.runOnce()) |_| {
                self.rx().runtime_activated.store(true, .release);
                consecutive_failures = 0;
            } else |err| {
                consecutive_failures += 1;
                srvLog(
                    "onyx-server: reactor loop error {s} ({d} consecutive)\n",
                    .{ @errorName(err), consecutive_failures },
                );
                if (err == error.BackendPoisoned or consecutive_failures >= 64) {
                    srvLog("onyx-server: reactor giving up after persistent errors\n", .{});
                    self.stopFailedReactors(run, if (err == error.BackendPoisoned) 1 else 2);
                    return;
                }
            }
        }
    }

    fn ownedSocketIoQuiesced(self: *LinuxServer) bool {
        const r = self.rx();
        if (!r.acceptsQuiesced()) return false;
        for (self.rx().clients.slots.items) |*slot| {
            if (!slot.occupied) continue;
            if (slot.value.recv_armed or slot.value.send_armed or slot.value.connect_armed) return false;
        }
        return true;
    }

    /// Owner-thread socket safe point. Queue exact user_data cancels for every
    /// armed RECV/SEND, submit them, and keep reaping through the ordinary
    /// CompletionHandler until the matching original CQEs release every buffer.
    /// Positive/partial CQEs that beat cancellation are applied normally; only
    /// ECANCELED changes meaning (ownership release, not EOF/stream failure).
    fn quiesceOwnedSocketIo(self: *LinuxServer) !void {
        const r = self.rx();
        r.socket_io_quiescing = true;
        var waited_ms: u64 = 0;
        var first_err: ?anyerror = null;
        while (!self.ownedSocketIoQuiesced()) {
            var sq_full = false;
            for (r.acceptOps()) |op| {
                if (!op.armed.* or op.pending.*) continue;
                io_backend.submitCancel(&r.ring, .accept, op.token) catch |err| switch (err) {
                    error.SubmissionQueueFull => {
                        sq_full = true;
                        break;
                    },
                    else => {
                        if (first_err == null) first_err = err;
                        break;
                    },
                };
                op.pending.* = true;
            }
            for (r.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                if (conn.recv_armed and !conn.recv_cancel_pending) {
                    io_backend.submitCancel(&r.ring, .recv, conn.token) catch |err| switch (err) {
                        error.SubmissionQueueFull => {
                            sq_full = true;
                            break;
                        },
                        else => {
                            if (first_err == null) first_err = err;
                            break;
                        },
                    };
                    conn.recv_cancel_pending = true;
                }
                if (conn.send_armed and !conn.send_cancel_pending) {
                    io_backend.submitCancel(&r.ring, .send, conn.token) catch |err| switch (err) {
                        error.SubmissionQueueFull => {
                            sq_full = true;
                            break;
                        },
                        else => {
                            if (first_err == null) first_err = err;
                            break;
                        },
                    };
                    conn.send_cancel_pending = true;
                }
                if (conn.connect_armed and !conn.connect_cancel_pending) {
                    io_backend.submitCancel(&r.ring, .connect, conn.token) catch |err| switch (err) {
                        error.SubmissionQueueFull => {
                            sq_full = true;
                            break;
                        },
                        else => {
                            if (first_err == null) first_err = err;
                            break;
                        },
                    };
                    conn.connect_cancel_pending = true;
                }
            }

            // Submit both the cancels and any same-turn SQEs queued before the
            // deferred safe point. Nonblocking reap avoids hanging forever on an
            // operation whose cancel raced a completion already in the CQ.
            _ = r.ring.submit() catch |err| blk: {
                if (first_err == null) first_err = err;
                break :blk 0;
            };
            var handler = CompletionHandler{ .server = self };
            var cqes: [ringlane.max_cqe_batch]reactor_backend.CompletionBuffer = undefined;
            const cqe_batch = @min(@as(usize, self.config.cqe_batch), cqes.len);
            r.ring.reapCompletions(cqes[0..cqe_batch], 0, &handler) catch |err| {
                if (first_err == null) first_err = err;
            };
            if (handler.err) |err| {
                if (first_err == null) first_err = err;
            }
            if (self.ownedSocketIoQuiesced()) break;
            if (waited_ms >= 5_000) return first_err orelse error.SocketIoQuiesceFailed;
            sleepOneMillis();
            waited_ms += 1;
            if (sq_full or waited_ms % 200 == 0) self.wakeReactor();
        }
        if (first_err) |err| return err;
    }

    /// After every owner stopped socket input, drain this owner's final mailbox.
    /// At that point no later RECV can enqueue behind this drain, so the sealed
    /// SendQ includes every cross-shard delivery accepted before the boundary.
    fn drainUpgradeFabric(self: *LinuxServer) void {
        if (self.fabric == null) return;
        self.world.lockWrite();
        self.abortPoisonedDeliveries();
        self.drainSessionDropControls();
        self.drainFabric();
        self.abortPoisonedDeliveries();
        self.world.unlockWrite();
    }

    /// With every socket owner quiesced and every sibling parked, rebind this
    /// coordinator thread to each reactor and drain until a complete all-shard
    /// pass makes no progress. The caller already holds World. Rebinding is safe
    /// here because socket_io_quiescing prevents delivery helpers from submitting
    /// to a foreign SINGLE_ISSUER ring; they only mutate the state being sealed.
    fn drainAllUpgradeFabricFixedPointLocked(self: *LinuxServer) !usize {
        const saved_reactor = current_reactor;
        defer current_reactor = saved_reactor;

        var total_slots: usize = 0;
        const inline_fallback = self.pool.count() == 0;
        for (self.reactors) |*r| {
            const inactive_foreign = inline_fallback and r != self.rx() and !r.socket_io_quiescing;
            if (!r.acceptsQuiesced())
                return error.UpgradeSocketOwnerNotQuiesced;
            if (inactive_foreign and r.clients.len() != 0)
                return error.UpgradeSocketOwnerNotQuiesced;
            total_slots = std.math.add(usize, total_slots, r.clients.slots.items.len) catch
                return error.UpgradeFabricDidNotQuiesce;
            for (r.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                if (conn.recv_armed or conn.send_armed or conn.connect_armed or
                    conn.recv_cancel_pending or conn.send_cancel_pending or conn.connect_cancel_pending)
                    return error.UpgradeSocketOwnerNotQuiesced;
            }
            if (!r.socket_io_quiescing and !inactive_foreign)
                return error.UpgradeSocketOwnerNotQuiesced;
        }
        const fabric_budget = if (self.fabric == null)
            0
        else
            std.math.mul(
                usize,
                reactor_fabric.ReactorFabric.capacity,
                self.reactors.len,
            ) catch return error.UpgradeFabricDidNotQuiesce;
        const max_passes = std.math.add(usize, total_slots, fabric_budget) catch
            return error.UpgradeFabricDidNotQuiesce;

        var pass: usize = 0;
        var total_progress: usize = 0;
        while (pass <= max_passes) : (pass += 1) {
            var progress: usize = 0;
            for (self.reactors) |*r| {
                if (inline_fallback and r != self.rx() and !r.socket_io_quiescing) continue;
                current_reactor = r;
                progress += self.abortPoisonedDeliveriesCount();
                progress += self.drainFabricCount();
                progress += self.abortPoisonedDeliveriesCount();
            }
            if (progress == 0) {
                // No drain path may have reacquired kernel ownership while the
                // thread was rebound. Revalidate every active owner at the exact
                // zero-progress boundary rather than trusting the entry check.
                for (self.reactors) |*r| {
                    if (inline_fallback and r != self.rx() and !r.socket_io_quiescing) continue;
                    if (!r.socket_io_quiescing or !r.acceptsQuiesced()) return error.UpgradeSocketOwnerNotQuiesced;
                    for (r.clients.slots.items) |*slot| {
                        if (!slot.occupied) continue;
                        const conn = &slot.value;
                        if (conn.recv_armed or conn.send_armed or conn.connect_armed or
                            conn.recv_cancel_pending or conn.send_cancel_pending or conn.connect_cancel_pending)
                            return error.UpgradeSocketOwnerNotQuiesced;
                    }
                }
                return total_progress;
            }
            total_progress = std.math.add(usize, total_progress, progress) catch
                return error.UpgradeFabricDidNotQuiesce;
        }
        return error.UpgradeFabricDidNotQuiesce;
    }

    /// Failure-path owner resume. Re-enable arming, stage every live/closing
    /// connection through the existing fair activator, and submit the first
    /// bounded page immediately. Further pages retain their normal wake retry.
    fn resumeOwnedSocketIo(self: *LinuxServer) void {
        const r = self.rx();
        // Never reinterpret a late exact-cancel CQE as ordinary EOF/error. Drain
        // issued cancellations to their original CQEs before clearing the
        // no-rearm mode; if the ring is still unhealthy, keep the owner quiesced
        // and let a later recovery turn finish it rather than corrupt the stream.
        if (!self.ownedSocketIoQuiesced()) _ = self.quiesceOwnedSocketIo() catch {};
        if (!self.ownedSocketIoQuiesced()) return;
        r.socket_io_quiescing = false;
        for (r.acceptOps()) |op| op.pending.* = false;
        self.armAccept() catch self.wakeReactor();
        for (r.clients.slots.items) |*slot| {
            if (!slot.occupied) continue;
            const conn = &slot.value;
            if (!conn.recv_armed) conn.recv_cancel_pending = false;
            if (!conn.send_armed) conn.send_cancel_pending = false;
            if (!conn.connect_armed) conn.connect_cancel_pending = false;
            if (conn.connect_rearm_pending) {
                self.armConnect(conn) catch {
                    self.wakeReactor();
                    continue;
                };
                if (conn.connect_armed) conn.connect_rearm_pending = false;
                continue;
            }
            conn.io_activation_pending = true;
            conn.activation_recv_required = !conn.closing;
        }
        _ = self.activatePendingSocketIo() catch {};
        _ = r.ring.submit() catch {};
    }

    /// Complete this sibling's half of the RESUMING barrier exactly once. The
    /// caller stays inside this invocation until the coordinator publishes
    /// IDLE, so one worker can neither acknowledge twice nor begin a new loop
    /// turn while an older generation is still unwinding.
    fn finishUpgradeResumeIfComplete(self: *LinuxServer) void {
        if (!self.upgrade_coordinator_resumed.load(.acquire)) return;
        if (self.upgrade_resume_done.load(.acquire) != self.upgrade_expected_siblings.load(.acquire)) return;
        if (self.upgrade_quiesce_shard.cmpxchgStrong(
            resuming_quiesce_shard,
            no_quiesce_shard,
            .acq_rel,
            .acquire,
        ) == null) self.wakeAllReactors();
    }

    fn resumeUpgradeSiblingAndWait(self: *LinuxServer, run: anytype) void {
        while (self.rx().socket_io_quiescing) {
            if (!run.load(.acquire)) return;
            self.resumeOwnedSocketIo();
            if (!self.rx().socket_io_quiescing) break;
            self.upgrade_io_failed.store(true, .release);
            sleepOneMillis();
        }
        _ = self.upgrade_resume_done.fetchAdd(1, .acq_rel);
        self.finishUpgradeResumeIfComplete();
        while (self.upgrade_quiesce_shard.load(.acquire) == resuming_quiesce_shard) {
            if (!run.load(.acquire)) return;
            sleepOneMillis();
        }
    }

    /// Park this reactor worker while a multi-shard UPGRADE seal owned by a
    /// DIFFERENT shard is in flight. Before publishing its park, the owner
    /// cancels/reaps its own exact socket operations, joins the all-owner barrier,
    /// drains its final fabric mailbox, and only then exposes stable snapshot
    /// state to the sealer.
    fn parkForUpgradeQuiesce(self: *LinuxServer, run: anytype) void {
        const q = self.upgrade_quiesce_shard.load(.acquire);
        if (q == no_quiesce_shard) return;
        if (q == initializing_quiesce_shard) return;
        if (q == resuming_quiesce_shard) {
            if (self.rx().shard_id == self.upgrade_coordinator_shard.load(.acquire)) {
                while (self.upgrade_quiesce_shard.load(.acquire) == resuming_quiesce_shard and run.load(.acquire)) {
                    if (self.rx().socket_io_quiescing) self.resumeOwnedSocketIo();
                    if (!self.rx().socket_io_quiescing) {
                        self.upgrade_coordinator_resumed.store(true, .release);
                        self.finishUpgradeResumeIfComplete();
                    }
                    sleepOneMillis();
                }
                return;
            }
            self.resumeUpgradeSiblingAndWait(run);
            return;
        }
        if (q < self.reactors.len and self.rx() == &self.reactors[q]) return; // the sealer itself

        self.quiesceOwnedSocketIo() catch {
            self.upgrade_io_failed.store(true, .release);
        };
        _ = self.upgrade_io_quiesced.fetchAdd(1, .acq_rel);
        while (!self.upgrade_drain_ready.load(.acquire) and
            self.upgrade_quiesce_shard.load(.acquire) == q)
        {
            if (!run.load(.acquire)) break;
            sleepOneMillis();
        }
        if (self.upgrade_quiesce_shard.load(.acquire) != q) {
            self.resumeUpgradeSiblingAndWait(run);
            return;
        }
        self.drainUpgradeFabric();
        _ = self.upgrade_parked.fetchAdd(1, .acq_rel);
        while (self.upgrade_quiesce_shard.load(.acquire) == q) {
            sleepOneMillis();
        }
        self.resumeUpgradeSiblingAndWait(run);
    }

    /// Quiesce every OTHER reactor worker so the calling thread may seal all
    /// shards' per-connection state for a Helix UPGRADE. Counts live pool
    /// workers (zero when the reactors run in-line/single-threaded — then no
    /// park is needed; the caller is the only thread touching any shard) and
    /// waits, bounded, for each sibling to park. Fail-safe: a sibling that
    /// never parks aborts the upgrade (`error.ShardQuiesceFailed`) rather than
    /// sealing state a live thread still mutates.
    fn quiesceSiblingReactors(self: *LinuxServer) !void {
        const workers = self.pool.count();
        const expected: u32 = if (workers == 0) 0 else @intCast(workers - 1);
        // CAS-claim the quiesce: two racing UPGRADEs (SIGUSR2 on reactor 0 vs
        // an oper /UPGRADE on another shard) must never both seal — the loser
        // refuses (its worker then parks, letting the winner proceed).
        if (self.upgrade_quiesce_shard.cmpxchgStrong(no_quiesce_shard, initializing_quiesce_shard, .acq_rel, .acquire) != null)
            return error.ShardQuiesceFailed;
        self.upgrade_coordinator_shard.store(self.rx().shard_id, .release);
        self.upgrade_coordinator_resumed.store(false, .release);
        self.upgrade_expected_siblings.store(expected, .release);
        self.upgrade_parked.store(0, .release);
        self.upgrade_io_quiesced.store(0, .release);
        self.upgrade_resume_done.store(0, .release);
        self.upgrade_io_failed.store(false, .release);
        self.upgrade_drain_ready.store(false, .release);
        self.upgrade_quiesce_shard.store(self.rx().shard_id, .release);
        self.wakeAllReactors();

        // The coordinator is an owner too. It stops its own socket input before
        // releasing the final-mailbox drain phase to siblings.
        self.quiesceOwnedSocketIo() catch |err| {
            self.upgrade_io_failed.store(true, .release);
            self.resumeSiblingReactors();
            return err;
        };
        var waited_ms: u64 = 0;
        while (true) {
            const quiesced = self.upgrade_io_quiesced.load(.acquire);
            if (quiesced == expected) break;
            if (quiesced > expected or self.upgrade_quiesce_shard.load(.acquire) != self.rx().shard_id) {
                self.resumeSiblingReactors();
                return error.ShardQuiesceFailed;
            }
            if (waited_ms >= 5_000) {
                self.resumeSiblingReactors();
                return error.ShardQuiesceFailed;
            }
            sleepOneMillis();
            waited_ms += 1;
            // Re-nudge stragglers: a wake consumed before the flag was visible
            // leaves a sibling blocked in submitAndWait until its sweep timer.
            if (waited_ms % 200 == 0) self.wakeAllReactors();
        }
        if (self.upgrade_io_failed.load(.acquire)) {
            self.resumeSiblingReactors();
            return error.SocketIoQuiesceFailed;
        }
        self.upgrade_drain_ready.store(true, .release);
        self.wakeAllReactors();
        self.drainUpgradeFabric();

        waited_ms = 0;
        while (true) {
            const parked = self.upgrade_parked.load(.acquire);
            if (parked == expected) break;
            if (parked > expected or self.upgrade_quiesce_shard.load(.acquire) != self.rx().shard_id) {
                self.resumeSiblingReactors();
                return error.ShardQuiesceFailed;
            }
            if (waited_ms >= 5_000) {
                self.resumeSiblingReactors();
                return error.ShardQuiesceFailed;
            }
            sleepOneMillis();
            waited_ms += 1;
            if (waited_ms % 200 == 0) self.wakeAllReactors();
        }
    }

    /// Release a quiesce taken by `quiesceSiblingReactors` (upgrade failed —
    /// the daemon keeps serving). Parked workers observe the clear and resume.
    fn resumeSiblingReactors(self: *LinuxServer) void {
        const q = self.upgrade_quiesce_shard.load(.acquire);
        if (q == no_quiesce_shard) return;
        const expected = self.upgrade_expected_siblings.load(.acquire);
        self.upgrade_drain_ready.store(false, .release);
        self.upgrade_quiesce_shard.store(resuming_quiesce_shard, .release);
        self.wakeAllReactors();
        if (self.rx().socket_io_quiescing) self.resumeOwnedSocketIo();
        if (self.rx().socket_io_quiescing) {
            self.upgrade_io_failed.store(true, .release);
            srvLog("onyx-server: UPGRADE quiesce left coordinator ring fail-closed in RESUMING\n", .{});
            return;
        }
        self.upgrade_coordinator_resumed.store(true, .release);
        self.finishUpgradeResumeIfComplete();

        var waited_ms: u64 = 0;
        while (true) {
            if (self.upgrade_quiesce_shard.load(.acquire) == no_quiesce_shard) return;
            const resumed = self.upgrade_resume_done.load(.acquire);
            if (resumed == expected) {
                self.finishUpgradeResumeIfComplete();
                continue;
            }
            if (resumed > expected) {
                self.upgrade_io_failed.store(true, .release);
                srvLog("onyx-server: UPGRADE resume barrier over-counted; retaining RESUMING state\n", .{});
                return;
            }
            if (waited_ms >= 5_000) {
                self.upgrade_io_failed.store(true, .release);
                srvLog("onyx-server: UPGRADE resume barrier timed out; retaining RESUMING state\n", .{});
                return;
            }
            sleepOneMillis();
            waited_ms += 1;
            if (waited_ms % 200 == 0) self.wakeAllReactors();
        }
    }

    pub fn handleAccept(self: *LinuxServer, event: ringlane.AcceptEvent) !void {
        const op = blk: {
            for (self.rx().acceptOps()) |candidate| {
                if (ringTokenEql(candidate.token, event.token)) break :blk candidate;
            }
            if (event.res >= 0) closeFd(event.res);
            return error.BadCompletion;
        };
        const is_s2s = op.kind == .s2s;
        const is_tls = op.kind == .tls;
        const is_ws = op.kind == .ws;
        const armed = op.armed;
        const cancel_pending = op.pending;
        const was_cancel_pending = cancel_pending.*;
        if (!event.more) {
            armed.* = false;
            cancel_pending.* = false;
        }
        if (was_cancel_pending and event.res == -@as(i32, @intFromEnum(linux.E.CANCELED))) {
            if (!self.rx().socket_io_quiescing) self.armAccept() catch self.wakeReactor();
            return;
        }
        if (event.res < 0) return error.BadCompletion;

        if (comptime builtin.os.tag == .windows) {
            if (self.reactors.len > 1 and self.rx() == &self.reactors[0] and !is_s2s) {
                const target = self.windows_accept_next % self.reactors.len;
                self.windows_accept_next +%= 1;
                if (target != 0 and self.reactors[target].wake != null and
                    self.reactors[target].windows_accepted.push(.{
                        .token = event.token,
                        .res = event.res,
                        .more = false,
                    }))
                {
                    if (self.reactors[target].wake) |*wake| wake.wake();
                    return;
                }
            }
        }

        const fd: linux.fd_t = event.res;
        errdefer closeFd(fd);

        // Refuse past the reserved cap: alloc beyond capacity would realloc the
        // slot array and move ConnState buffers out from under in-flight I/O.
        if (self.rx().clients.len() >= self.config.max_clients) {
            closeFd(fd);
            return;
        }

        // [mesh].require_secured: refuse plaintext S2S peers. A plaintext link is
        // only ever stood up when secured S2S is unavailable, so a require_secured
        // operator drops the peer rather than relaying in clear. (Secured peers go
        // through the Mooring path below and are unaffected.)
        if (is_s2s and self.config.require_secured and !self.s2sSecured()) {
            self.traceLog(.info, .s2s, "refused plaintext S2S peer ([mesh].require_secured)");
            closeFd(fd);
            return;
        }

        const id = try self.rx().clients.alloc(ConnState.init(fd));
        _ = self.rx().accepted_count.fetchAdd(1, .monotonic);
        // Free the slot on any later failure so a half-set-up accept never leaves
        // an occupied slot (which deinit would then try to tear down).
        errdefer _ = self.rx().clients.free(id);
        const conn = self.rx().clients.get(id).?;
        conn.overflow_allocator = self.allocator; // backs the SendQ overflow heap
        // S2S links get the `server` class SendQ cap immediately (they carry mesh
        // bursts from the first frame); clients keep the generous default until
        // `assignConnClass` matches them at registration.
        if (is_s2s) {
            const configured = if (self.config.class_registry) |*reg|
                reg.classFor(.{ .is_server_link = true }).policy.sendq
            else
                conn.sendq_cap;
            conn.sendq_cap = s2sSendqCap(configured);
        }
        conn.token = try tokenFromId(id);
        conn.connected_at_ms = self.nowMs();
        conn.last_activity_ms = conn.connected_at_ms;
        conn.last_message_ms = conn.connected_at_ms;
        if (!is_s2s) {
            // The active gauge describes physical open client slots, including a
            // trusted-PROXY preamble or TLS handshake still in progress. Acquire
            // ownership as soon as the fully initialized slot exists; every later
            // rejection/error either closes through closeConn or explicitly drops
            // this same latch before freeing the slot.
            self.noteClientAccepted(conn);
        }
        errdefer self.dropClientStats(conn);

        if (is_s2s and self.s2sSecured()) {
            self.captureClientHost(conn);
            // PQ-secured peer: stand up a SecuredLink (responder). Its TOFU prekey
            // preamble is already queued; send it and wait for the initiator's M1.
            const link = try self.newSecuredLink(.responder);
            errdefer {
                link.deinit();
                self.allocator.destroy(link);
            }
            conn.s2s_secured = link;
            errdefer conn.s2s_secured = null;
            const out = link.outbound();
            if (out.len != 0) {
                try appendToConn(conn, out);
                link.clearOutbound();
            }
            // Acquire RECV first. If the SQ has no room for the prekey SEND,
            // retain the fully-built slot and let the fair activator queue only
            // that missing op; never unwind a slot whose recv_buf the kernel owns.
            self.armRecv(conn) catch |err| switch (err) {
                error.SubmissionQueueFull => {
                    conn.io_activation_pending = true;
                    conn.activation_recv_required = true;
                    self.wakeReactor();
                    self.noteS2sTcpOpened(conn);
                    self.traceLog(.info, .s2s, "s2s secured peer accepted (activation staged)");
                    return;
                },
                else => return err,
            };
            self.armSendIfNeeded(conn) catch {
                conn.io_activation_pending = true;
                conn.activation_recv_required = true;
                self.wakeReactor();
                self.noteS2sTcpOpened(conn);
                self.traceLog(.info, .s2s, "s2s secured peer accepted (send staged)");
                return;
            };
            self.noteS2sTcpOpened(conn);
            self.traceLog(.info, .s2s, "s2s secured peer accepted");
            return;
        }
        if (is_s2s) {
            self.captureClientHost(conn);
            // Server-to-server peer: stand up an S2sLink and wait for its inbound
            // handshake (the connecting side opens it; we respond on recv).
            const link = try self.allocator.create(s2s_link.S2sLink);
            errdefer self.allocator.destroy(link);
            try link.init(.{
                .allocator = self.allocator,
                .local_node_id = self.config.node_id,
                // remote_node_id is learned from the inbound handshake.
                .remote_node_id = 0,
                .local_epoch_ms = @intCast(@max(0, platform.realtimeMillis())),
                .server_name = self.serverName(),
                .config = self.config.s2s_config,
            });
            errdefer link.deinit();
            link.setLocalNickResolver(self.localNickResolver());
            link.setResidenceVerifier(self.residenceVerifier());
            link.setSessionTokenResolver(self.sessionTokenResolver());
            link.setSessionTokenNickAuthorizer(self.sessionTokenNickAuthorizer());
            conn.s2s = link;
            // Clear the dangling pointer before the slot is freed if submitRecv
            // fails, so deinit can never observe a freed link.
            errdefer conn.s2s = null;
            self.armRecv(conn) catch {
                self.noteS2sTcpOpened(conn);
                self.traceLog(.info, .s2s, "s2s peer accepted (activation staged)");
                return;
            };
            self.noteS2sTcpOpened(conn);
            self.traceLog(.info, .s2s, "s2s peer accepted");
            return;
        }

        // Capture the peer host (real + auto-cloak) before client setup. A
        // trusted PROXY preamble may replace this with the original client IP
        // before TLS/WS/plain IRC bytes are consumed.
        self.captureClientHost(conn);

        const kind: AcceptKind = if (is_tls) .tls else if (is_ws) .ws else .plain;
        if (self.shouldReadProxyHeader(conn)) {
            conn.accept_kind = kind;
            conn.proxy_pending = true;
            self.armRecv(conn) catch {
                self.traceLog(.info, .net, "trusted proxy accepted; receive activation staged");
                return;
            };
            self.traceLog(.info, .net, "trusted proxy accepted; waiting for PROXY header");
            return;
        }

        _ = try self.startAcceptedClient(id, conn, kind, true);
    }

    /// Capture the peer's IP at accept: record it as the real host and, when a
    /// cloak key is configured, set the visible host to its HMAC cloak so other
    /// users never see the raw address. Best-effort: any failure leaves the host
    /// fields empty and the prefix path falls back to the default host.
    fn captureClientHost(self: *LinuxServer, conn: *ConnState) void {
        if (comptime builtin.os.tag == .windows) {
            const peer = io_backend.socketPeerAddress(conn.fd) catch return;
            const addr: dns.Address = switch (peer) {
                .ipv4 => |bytes| .{ .ipv4 = bytes },
                .ipv6 => |bytes| if (isV4Mapped(bytes))
                    .{ .ipv4 = bytes[12..16].* }
                else
                    .{ .ipv6 = bytes },
            };
            self.applyAcceptedAddress(conn, addr);
            return;
        }
        var storage: posix.sockaddr.storage = undefined;
        var len: posix.socklen_t = @sizeOf(posix.sockaddr.storage);
        if (comptime builtin.os.tag == .linux) {
            const rc = linux.getpeername(conn.fd, @ptrCast(&storage), &len);
            if (posix.errno(rc) != .SUCCESS) return;
        } else os_runtime.getpeername(conn.fd, &storage, &len) catch return;
        const sa: *const posix.sockaddr = @ptrCast(@alignCast(&storage));
        const addr: dns.Address = switch (sa.family) {
            posix.AF.INET => blk: {
                const in: *const posix.sockaddr.in = @ptrCast(@alignCast(&storage));
                const b: [4]u8 = @bitCast(in.addr);
                break :blk .{ .ipv4 = b };
            },
            posix.AF.INET6 => blk: {
                const in6: *const posix.sockaddr.in6 = @ptrCast(@alignCast(&storage));
                // A dual-stack listener reports IPv4 peers as IPv4-mapped IPv6
                // (::ffff:a.b.c.d). Unwrap those to real IPv4 so host display,
                // cloaking, bans, reputation, and clone limits treat them as the
                // v4 address they actually are — not a synthetic v6 host.
                if (isV4Mapped(in6.addr)) {
                    const b: [4]u8 = in6.addr[12..16].*;
                    break :blk .{ .ipv4 = b };
                }
                break :blk .{ .ipv6 = in6.addr };
            },
            else => return,
        };
        self.applyAcceptedAddress(conn, addr);
    }

    /// Apply an already-authenticated client address (kernel peer or trusted
    /// PROXY header) to the session host/cloak state.
    fn applyAcceptedAddress(self: *LinuxServer, conn: *ConnState, addr: dns.Address) void {
        conn.peer_addr = addr;
        var ipbuf: [cloak.max_cloak_len]u8 = undefined;
        const ip = addrText(addr, &ipbuf) orelse return;
        // Loopback connections display as the conventional "localhost" (cloaking
        // a 127.x / ::1 address is pointless and noisy).
        if (std.mem.startsWith(u8, ip, "127.") or std.mem.eql(u8, ip, "0:0:0:0:0:0:0:1")) {
            conn.session.setRealHost(default_host);
            conn.session.setVisibleHost(default_host);
            return;
        }
        conn.session.setRealHost(ip);
        // Kick off forward-confirmed reverse DNS off the hot path; the result (if
        // any) upgrades the cloak base from the IP to the hostname at
        // registration time. The initial visible host below is always IP-based.
        if (self.config.rdns) |res| {
            res.request(addr);
        }
        // Kick off the DNS blocklist check off the hot path too; the verdict is
        // read at registration (enforceDnsbl), by which point the lookup has had
        // the handshake window to resolve. Fail-open if it has not.
        if (self.config.dnsbl) |bl| {
            bl.request(addr);
        }
        self.applyVisibleHost(conn);
    }

    /// (Re)compute a client's visible (cloaked) host. Prefers a forward-confirmed
    /// reverse-DNS hostname when the resolver has one ready, else the raw IP; the
    /// chosen base is then HMAC-cloaked (IP → hierarchical tokens, hostname →
    /// domain-preserving) when a cloak key is configured. Called once at connect
    /// (IP base) and again at registration completion (hostname base, if rDNS has
    /// finished by then). Best-effort: never fails a connection.
    fn applyVisibleHost(self: *LinuxServer, conn: *ConnState) void {
        const addr = conn.peer_addr orelse return;
        var ipbuf: [cloak.max_cloak_len]u8 = undefined;
        const ip_text = addrText(addr, &ipbuf) orelse return;
        // Loopback stays the conventional "localhost" (cloaking 127.x / ::1 is
        // pointless); matches captureClientHost so the registration re-apply
        // never overrides it with a cloaked 127.0.0.1.
        if (std.mem.startsWith(u8, ip_text, "127.") or std.mem.eql(u8, ip_text, "0:0:0:0:0:0:0:1")) {
            conn.session.setVisibleHost(default_host);
            return;
        }
        if (self.config.cloak_key) |key| {
            var cbuf: [cloak.max_cloak_len]u8 = undefined;
            // Per-account cloak: a logged-in client shows a stable, friendly
            // `<account>.users.<suffix>` that follows them across IPs/devices.
            // Explicit VHOST personas set the host directly (not recomputed here),
            // so they still win. Falls through to the IP cloak on an unusable
            // account label or for logged-out clients.
            if (self.config.cloak_account) {
                if (conn.session.account()) |acct| {
                    if (cloak.cloakAccount(&cbuf, acct, self.config.cloak_suffix)) |ac| {
                        conn.session.setVisibleHost(ac);
                        return;
                    } else |_| {}
                }
            }
            // Auth-split (P0-1): an ANONYMOUS (not-logged-in) client, when anon
            // epoch rotation is enabled, gets an OPAQUE cloak salted by the
            // current wall-clock epoch — so a static-IP anonymous user is neither
            // linkable across epochs nor leaks subnet co-membership. Logged-in
            // clients skip this (account() != null) and fall through to the stable
            // account/hierarchical cloak, keeping subnet-bannability. Moderation of
            // anonymous abuse shifts to account bans + registration friction.
            if (self.config.cloak_anon_epoch_secs != 0 and conn.session.account() == null) {
                const opts = cloak.Options{ .suffix = self.config.cloak_suffix };
                conn.session.setVisibleHost(cloak.cloakOpaqueEpoch(&cbuf, &key, ip_text, self.anonCloakEpoch(), opts) catch {
                    conn.session.setVisibleHost(ip_text);
                    return;
                });
                return;
            }
            // Cloak the IP ITSELF — never the reverse-DNS name, which would leak
            // the ISP's registrable domain (`....comcast.net`). rDNS still resolves
            // (for the oper-only real-host WHOIS line); it just never feeds the
            // public cloak. Opaque mode emits one token over the whole address;
            // hierarchical mode mixes in GeoIP country + ASN as ban-able labels.
            const opts = cloak.Options{ .suffix = self.config.cloak_suffix };
            const cloaked = if (self.config.cloak_opaque)
                cloak.cloakOpaque(&cbuf, &key, ip_text, opts)
            else
                cloak.cloak(&cbuf, &key, ip_text, self.cloakGeo(ip_text), opts);
            conn.session.setVisibleHost(cloaked catch {
                conn.session.setVisibleHost(ip_text);
                return;
            });
        } else {
            // No cloak key configured: show the reverse-DNS name when the operator
            // enabled rDNS, else the raw IP (their explicit non-cloaking choice).
            var hostbuf: [cloak.max_cloak_len]u8 = undefined;
            var base: []const u8 = ip_text;
            if (self.config.rdns) |res| {
                if (res.lookup(addr, &hostbuf)) |name| base = name;
            }
            conn.session.setVisibleHost(base);
        }
    }

    /// Look up the GeoIP country + origin ASN for a client IP so the cloak can
    /// carry ban-able `a<asn>.<cc>` labels. Best-effort: any miss (no DB, private
    /// range, unresolved) leaves the field zero/empty and the cloak renders the
    /// stable `a0`/`xx` placeholders. The country slice borrows the GeoIP mmap,
    /// which stays mapped for the process lifetime, so it is valid until the
    /// immediately-following `cloak.cloak` copies it out.
    fn cloakGeo(self: *LinuxServer, ip_text: []const u8) cloak.Geo {
        const gip = parseGeoIp(ip_text) orelse return cloak.Geo.none;
        var geo = cloak.Geo{};
        if (self.ensureGeoip()) |db| {
            if (db.lookupInfo(gip) catch null) |gi| {
                if (gi.country_iso) |iso| geo.country = iso;
            }
        }
        if (self.lookupGeoAsn(gip).asn) |asn| geo.asn = asn;
        return geo;
    }

    /// Compute a client's visible host under the PREVIOUS cloak key (for ban
    /// continuity across a key rotation), into `buf`. Returns null when there is
    /// no previous key, no peer address, the client is on loopback, or the client
    /// currently wears a key-free host (per-account cloak / explicit persona) —
    /// in those cases the previous-key host is identical or irrelevant, so the
    /// primary WARD check already covered it. Mirrors the IP-cloak branch of
    /// applyVisibleHost, only with `cloak_prev_key`.
    fn prevKeyCloakHost(self: *LinuxServer, conn: *ConnState, buf: []u8) ?[]const u8 {
        const key = self.config.cloak_prev_key orelse return null;
        // A logged-in client under account_cloak wears the key-free account host,
        // which does not change with the key — nothing extra to match.
        if (self.config.cloak_account and conn.session.account() != null) return null;
        const addr = conn.peer_addr orelse return null;
        var ipbuf: [cloak.max_cloak_len]u8 = undefined;
        const ip_text = addrText(addr, &ipbuf) orelse return null;
        if (std.mem.startsWith(u8, ip_text, "127.") or std.mem.eql(u8, ip_text, "0:0:0:0:0:0:0:1")) return null;
        const opts = cloak.Options{ .suffix = self.config.cloak_suffix };
        const cloaked = if (self.config.cloak_opaque)
            cloak.cloakOpaque(buf, &key, ip_text, opts)
        else
            cloak.cloak(buf, &key, ip_text, self.cloakGeo(ip_text), opts);
        return cloaked catch null;
    }

    /// Derive the 16-byte network-wide IP-salt from the shared mesh secret. A
    /// fixed domain tag separates it from other uses of the secret; the same
    /// secret yields the same key on every node, so an IP hashes identically
    /// mesh-wide. (An empty secret still yields a stable key — fine for hashing.)
    fn deriveCloneKey(mesh_pass: []const u8) [16]u8 {
        var h = std.crypto.hash.sha2.Sha256.init(.{});
        h.update("onyx-clone-salt\x00");
        h.update(mesh_pass);
        var digest: [32]u8 = undefined;
        h.final(&digest);
        return digest[0..16].*;
    }

    /// Whether `addr` is an IPv4 (127.0.0.0/8) or IPv6 (::1) loopback address.
    fn addrIsLoopback(addr: dns.Address) bool {
        return switch (addr) {
            .ipv4 => |b| b[0] == 127,
            .ipv6 => |b| std.mem.eql(u8, &b, &(@as([15]u8, @splat(0)) ++ [_]u8{1})),
        };
    }

    /// Format an address as its canonical text (IPv4 dotted-quad / IPv6) into
    /// `buf`, returning the slice or null on overflow.
    pub fn addrText(addr: dns.Address, buf: []u8) ?[]const u8 {
        return switch (addr) {
            .ipv4 => |b| std.fmt.bufPrint(buf, "{d}.{d}.{d}.{d}", .{ b[0], b[1], b[2], b[3] }) catch null,
            .ipv6 => |b| formatIp6(buf, b) catch null,
        };
    }

    /// Drive a server-to-server peer connection: feed inbound bytes to its
    /// S2sLink and queue any outbound frames the link produced for sending.
    /// Monotonic time in ms, routed through the reactor seam when one is injected
    /// (deterministic simulation), else the system monotonic clock.
    pub fn nowMs(self: *const LinuxServer) i64 {
        return if (self.reactor) |r| r.nowMillis() else platform.monotonicMillis();
    }

    /// Monotonic ms as a non-negative u64 (the reputation table's clock type).
    pub fn nowU64(self: *const LinuxServer) u64 {
        return @intCast(@max(0, self.nowMs()));
    }

    /// Wall-clock unix SECONDS for the IRCX ACCESS timeout domain. ACCESS
    /// timeouts are relative seconds, so the store compares against wall-clock
    /// seconds (same domain as LISTX C/T age filters); sourced through the
    /// reactor so deterministic simulation controls it.
    fn accessNowSeconds(self: *const LinuxServer) u64 {
        return self.meshWallMs() / 1000;
    }

    /// Wall-clock (Unix-epoch) ms — the physical base for the cross-mesh HLC.
    /// Sourced through the reactor so deterministic simulation controls it (and
    /// keeps it shared/comparable across simulated nodes); off-reactor it is the
    /// system wall clock. NEVER `nowMs()`, whose monotonic value is per-host and
    /// not comparable across the mesh.
    fn meshWallMs(self: *const LinuxServer) u64 {
        const w = if (self.reactor) |r| r.wallMillis() else platform.realtimeMillis();
        return @intCast(@max(@as(i64, 0), w));
    }

    /// WALL-CLOCK ms (u64) for the cross-node oper-grant domain. A grant carries an
    /// ABSOLUTE `issued_ms`/`expiry_ms` that two different hosts must compare against
    /// their own clocks, so it MUST use the NTP-synced real-time clock — NOT `nowMs()`
    /// (CLOCK_MONOTONIC = time-since-boot, which differs between hosts by their uptime
    /// skew). With monotonic stamps a grant issued by a lower-uptime node looked
    /// already-expired to a higher-uptime peer (`now_ms >= expiry_ms`) and was
    /// silently rejected, so its operator never gained the `*` prefix across the mesh.
    /// Same clock-domain lesson as the mesh zombie-GC (monotonic clocks are per-node).
    pub fn grantNowU64(self: *const LinuxServer) u64 {
        _ = self;
        return @intCast(@max(@as(i64, 0), platform.realtimeMillis()));
    }

    /// Current anonymous-cloak rotation epoch: `floor(wall_clock_seconds /
    /// anon_epoch_secs)`. Wall-clock based so every mesh node computes the same
    /// epoch for a given instant (same cross-node clock-domain rule as oper
    /// grants and HLC LWW; a per-node monotonic clock would desync the anon
    /// cloak across the mesh). Returns 0 when rotation is disabled, so the
    /// division is never reached with a zero divisor.
    fn anonCloakEpoch(self: *const LinuxServer) u64 {
        const secs = self.config.cloak_anon_epoch_secs;
        if (secs == 0) return 0;
        const now_ms: u64 = @intCast(@max(@as(i64, 0), platform.realtimeMillis()));
        return (now_ms / 1000) / secs;
    }

    /// Whether IP reputation is active (a non-zero refuse threshold configured).
    fn reputationOn(self: *const LinuxServer) bool {
        return self.config.reputation_refuse_threshold != 0;
    }

    /// Publish a SECURITY-category Event Spine event for pre-registration
    /// admission refusals. These happen before a stable client prefix exists, so
    /// identify the source by the real peer IP/host rather than nick!user@host.
    fn publishSecurityAdmissionRefusal(self: *LinuxServer, conn: *const ConnState, kind: []const u8, detail: []const u8) void {
        var addr_buf: [128]u8 = undefined;
        const source = if (conn.peer_addr) |addr|
            addrText(addr, &addr_buf) orelse conn.session.realHost()
        else
            conn.session.realHost();
        const src = if (source.len != 0) source else "unknown";
        var mbuf: [640]u8 = undefined;
        const msg = std.fmt.bufPrint(&mbuf, "{s} refused {s} ({s})", .{ kind, src, detail }) catch return;
        self.publishOperEvent(.security, .warn, msg) catch {};
    }

    fn trustedProxyMatches(addr: dns.Address, text: []const u8) bool {
        if (std.Io.net.IpAddress.parseIp4(text, 0)) |parsed| {
            return switch (addr) {
                .ipv4 => |b| std.mem.eql(u8, b[0..], parsed.ip4.bytes[0..4]),
                .ipv6 => false,
            };
        } else |_| {}
        if (std.Io.net.IpAddress.parseIp6(text, 0)) |parsed| {
            return switch (addr) {
                .ipv4 => false,
                .ipv6 => |b| std.mem.eql(u8, b[0..], parsed.ip6.bytes[0..16]),
            };
        } else |_| {}
        var buf: [cloak.max_cloak_len]u8 = undefined;
        const rendered = addrText(addr, &buf) orelse return false;
        return std.mem.eql(u8, rendered, text);
    }

    fn shouldReadProxyHeader(self: *const LinuxServer, conn: *const ConnState) bool {
        if (!self.config.proxy_protocol_enabled or self.config.trusted_proxies.len == 0) return false;
        const addr = conn.peer_addr orelse return false;
        for (self.config.trusted_proxies) |trusted| {
            if (trustedProxyMatches(addr, trusted)) return true;
        }
        return false;
    }

    fn proxyHeaderAddress(header: proxy_protocol.Header) ?dns.Address {
        if (header.is_local) return null;
        return switch (header.family) {
            .tcp4 => .{ .ipv4 = header.src_ip[0..4].* },
            .tcp6 => .{ .ipv6 = header.src_ip[0..16].* },
            .unknown => null,
        };
    }

    fn refuseSilentClient(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) bool {
        var refuse = self.draining;
        if (!refuse and self.reputationOn()) {
            if (conn.peer_addr) |addr| {
                if (self.reputation.shouldRefuse(addr, self.nowU64()) and !self.config.challenge_enabled) {
                    self.publishSecurityAdmissionRefusal(conn, "REPUTATION", "threshold exceeded");
                    refuse = true;
                }
            }
        }
        // Connection-rate throttle: too many new connects from one source IP in
        // the window are refused. Skipped for loopback / trusted-proxy sources
        // (a shared reverse proxy fronting WebSocket clients must not be
        // throttled as one IP). Fails open on any allocator/tracking error.
        if (!refuse and self.conn_throttle != null and !self.ipCloneExempt(conn)) {
            if (conn.peer_addr) |addr| {
                var ipbuf: [64]u8 = undefined;
                if (addrText(addr, &ipbuf)) |ip| {
                    const decision = self.conn_throttle.?.classifyConnect(self.nowMs(), ip) catch .allow;
                    switch (decision) {
                        .allow => conn.throttle_counted = true,
                        .connect_throttled, .clone_limited => {
                            self.penalizePeer(conn, self.config.clone_refuse_penalty);
                            self.publishSecurityAdmissionRefusal(conn, "CONNECTION_THROTTLE", if (decision == .connect_throttled) "connect rate exceeded" else "concurrent connection limit exceeded");
                            refuse = true;
                        },
                    }
                }
            }
        }
        if (!refuse) {
            if (conn.peer_addr) |addr| {
                if (self.clone_limit.register(addr)) {
                    conn.clone_counted = true;
                } else |err| switch (err) {
                    error.TooManyPerIp, error.TooManyPerNet => {
                        self.penalizePeer(conn, self.config.clone_refuse_penalty);
                        self.publishSecurityAdmissionRefusal(conn, "CLONE_LIMIT", if (err == error.TooManyPerIp) "per-IP cap exceeded" else "per-network cap exceeded");
                        refuse = true;
                    },
                    error.NoSpaceLeft => {},
                }
            }
        }
        if (!refuse) return false;
        // Refuse path bypasses closeConn, so release the throttle slot we may have
        // recorded above before tearing the fd down (clone_limit only counts on
        // the accept path, never here).
        self.releaseThrottle(conn);
        self.noteClientRefusedBeforeLive(conn);
        closeFd(conn.fd);
        _ = self.rx().clients.free(id);
        return true;
    }

    /// Release this connection's connection-rate throttle slot (if it holds one).
    /// Renders the same source-IP text used at `classifyConnect`. Used by both the
    /// refuse path and `closeConn`.
    fn releaseThrottle(self: *LinuxServer, conn: *ConnState) void {
        if (!conn.throttle_counted) return;
        conn.throttle_counted = false;
        const t = if (self.conn_throttle) |*tt| tt else return;
        const addr = conn.peer_addr orelse return;
        var ipbuf: [64]u8 = undefined;
        if (addrText(addr, &ipbuf)) |ip| _ = t.disconnect(ip);
    }

    fn startAcceptedTls(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, arm_recv: bool) !bool {
        if (self.refuseSilentClient(id, conn)) return false;
        const tls = try self.allocator.create(tls_conn.TlsConn);
        // Implicit-TLS IRC listener: honour the configured client-cert request
        // (mTLS for SASL EXTERNAL / CERTFP). Dedicated IRC clients can present a
        // cert here; the browser WS path forces this off (startAcceptedWs).
        const tls_cfg = self.tls13Config(self.config.tls_request_client_cert);
        if (self.config.tls12_cert_chain.len != 0 and (self.config.tls12_signing_key != null or self.config.tls_rsa_signing_key != null)) {
            tls.* = tls_conn.TlsConn.initDual(self.allocator, tls_cfg, self.tls12Config());
        } else {
            tls.* = tls_conn.TlsConn.initBorrowed(self.allocator, tls_cfg) catch {
                self.allocator.destroy(tls);
                self.noteClientRefusedBeforeLive(conn);
                closeFd(conn.fd);
                _ = self.rx().clients.free(id);
                return false;
            };
        }
        errdefer {
            tls.deinit();
            self.allocator.destroy(tls);
        }
        conn.tls = tls;
        conn.is_tls = true;
        self.injectSessionState(conn);
        if (arm_recv) self.armRecv(conn) catch {
            conn.io_activation_pending = true;
            conn.activation_recv_required = true;
            self.wakeReactor();
        };
        self.noteClientAccepted(conn);
        self.traceLog(.info, .net, "tls client accepted");
        return true;
    }

    fn startAcceptedWs(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, arm_recv: bool) !bool {
        if (self.refuseSilentClient(id, conn)) return false;
        const ws = try self.allocator.create(WsState);
        ws.* = .{};
        errdefer {
            conn.ws = null;
            self.allocator.destroy(ws);
        }
        conn.ws = ws;
        if (certReady(self.config)) {
            const tls = try self.allocator.create(tls_conn.TlsConn);
            // NEVER request a client cert on the browser WebSocket listener:
            // browsers cannot satisfy a TLS CertificateRequest on a script-
            // initiated WebSocket and abort the handshake (close 1006), which
            // silently breaks every browser client. mTLS/CERTFP is unavailable
            // to browser JS anyway, so forcing this off loses nothing.
            const tls_cfg = self.tls13Config(false);
            if (self.config.tls12_cert_chain.len != 0 and (self.config.tls12_signing_key != null or self.config.tls_rsa_signing_key != null)) {
                tls.* = tls_conn.TlsConn.initDual(self.allocator, tls_cfg, self.tls12Config());
            } else {
                tls.* = tls_conn.TlsConn.initBorrowed(self.allocator, tls_cfg) catch {
                    self.allocator.destroy(tls);
                    conn.ws = null;
                    self.allocator.destroy(ws);
                    self.noteClientRefusedBeforeLive(conn);
                    closeFd(conn.fd);
                    _ = self.rx().clients.free(id);
                    return false;
                };
            }
            conn.tls = tls;
            conn.is_tls = true;
        }
        errdefer if (conn.tls) |t| {
            t.deinit();
            self.allocator.destroy(t);
            conn.tls = null;
        };
        self.injectSessionState(conn);
        if (arm_recv) self.armRecv(conn) catch {
            conn.io_activation_pending = true;
            conn.activation_recv_required = true;
            self.wakeReactor();
        };
        self.noteClientAccepted(conn);
        self.traceLog(.info, .net, "ws client accepted");
        return true;
    }

    fn startAcceptedPlain(self: *LinuxServer, conn: *ConnState, arm_recv: bool) !bool {
        if (self.draining) {
            emitServerLine(conn, "ERROR :Server is draining; try again later");
            conn.close_reason = "Server draining";
            conn.closing = true;
            self.armSendIfNeeded(conn) catch {
                conn.io_activation_pending = true;
                conn.activation_recv_required = false;
                self.wakeReactor();
            };
            self.noteClientAccepted(conn);
            return true;
        }
        if (self.reputationOn()) {
            if (conn.peer_addr) |addr| {
                if (self.reputation.shouldRefuse(addr, self.nowU64()) and !self.config.challenge_enabled) {
                    self.publishSecurityAdmissionRefusal(conn, "REPUTATION", "threshold exceeded");
                    emitServerLine(conn, "ERROR :Connection refused (reputation)");
                    conn.close_reason = "Reputation";
                    conn.closing = true;
                    self.armSendIfNeeded(conn) catch {
                        conn.io_activation_pending = true;
                        conn.activation_recv_required = false;
                        self.wakeReactor();
                    };
                    self.noteClientAccepted(conn);
                    return true;
                }
            }
        }
        if (conn.peer_addr) |addr| {
            if (self.clone_limit.register(addr)) {
                conn.clone_counted = true;
            } else |err| switch (err) {
                error.TooManyPerIp, error.TooManyPerNet => {
                    self.penalizePeer(conn, self.config.clone_refuse_penalty);
                    self.publishSecurityAdmissionRefusal(conn, "CLONE_LIMIT", if (err == error.TooManyPerIp) "per-IP cap exceeded" else "per-network cap exceeded");
                    emitServerLine(conn, "ERROR :Too many connections from your host");
                    conn.close_reason = "Too many connections";
                    conn.closing = true;
                    self.armSendIfNeeded(conn) catch {
                        conn.io_activation_pending = true;
                        conn.activation_recv_required = false;
                        self.wakeReactor();
                    };
                    self.noteClientAccepted(conn);
                    return true;
                },
                error.NoSpaceLeft => {},
            }
        }
        self.injectSessionState(conn);
        if (arm_recv) self.armRecv(conn) catch {
            conn.io_activation_pending = true;
            conn.activation_recv_required = true;
            self.wakeReactor();
        };
        self.noteClientAccepted(conn);
        self.traceLog(.info, .net, "client accepted");
        return true;
    }

    fn startAcceptedClient(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, kind: AcceptKind, arm_recv: bool) !bool {
        // Kernel-level dead-connection detection for every client transport
        // (plain/TLS/WS share the same underlying TCP fd). Keeps channel rosters
        // honest when a client disappears without a clean close.
        applyClientKeepalive(conn.fd);
        return switch (kind) {
            .plain => try self.startAcceptedPlain(conn, arm_recv),
            .tls => try self.startAcceptedTls(id, conn, arm_recv),
            .ws => try self.startAcceptedWs(id, conn, arm_recv),
        };
    }

    /// Add `points` of penalty to a peer's reputation (no-op when disabled or the
    /// peer address is unknown). Best-effort: decay-math errors are swallowed.
    fn penalizePeer(self: *LinuxServer, conn: *const ConnState, points: f64) void {
        if (!self.reputationOn()) return;
        if (conn.peer_addr) |addr| {
            _ = self.reputation.penalize(addr, points, self.nowU64()) catch return;
            self.snapshotReputation();
        }
    }

    /// Bands/features advertised by this node's S2S prekeys.
    const s2s_bands: u128 = 0b1111;
    const s2s_features: u128 = 0b1;

    /// True when PQ-secured S2S is configured (node identity + a CSPRNG io).
    pub fn s2sSecured(self: *const LinuxServer) bool {
        return self.config.node_identity != null and self.config.crypto_io != null;
    }

    /// Local signing identity alone does not activate durable relay-v2. A
    /// standalone or TOFU deployment has no exact event-time coverage set and
    /// therefore stays on ordinary local/legacy delivery. Nonempty root config
    /// does activate the strict path even when malformed: admission then fails
    /// closed instead of silently degrading a requested durable mesh to legacy.
    pub fn authoredRelayV2Configured(self: *const LinuxServer) bool {
        return self.relay_v2_activation_state.mode == .active and
            self.relay_v2_required_nodes.len >= 2;
    }

    /// Build a heap-owned SecuredLink for `role`, using a freshly-derived prekey.
    /// Validity uses the wall clock so the window is comparable across nodes.
    fn newSecuredLink(self: *LinuxServer, role: secured_s2s_link.Role) !*secured_s2s_link.SecuredLink {
        const ident = self.config.node_identity.?;
        const wall: u64 = @intCast(@max(0, platform.realtimeMillis()));
        // Back-date not_before so a peer that captured its verify-clock slightly
        // earlier (connect/accept ordering + modest skew) still sees the prekey as
        // valid; the validity window stays long via the ttl.
        const not_before = wall -| (5 * 60 * 1000);
        const prekey = try ident.signedPrekey(1, not_before, 24 * 60 * 60 * 1000, s2s_bands, s2s_features);
        var pins: [secured_s2s_link.max_expected_remotes][20]u8 = undefined;
        var pin_count: usize = 0;
        for (self.config.mesh_trust_roots) |root| {
            if (pin_count == pins.len) break;
            if (parseMeshTrustRoot(root)) |pin| {
                pins[pin_count] = pin;
                pin_count += 1;
            } else {
                self.traceLog(.warn, .s2s, "invalid mesh trust root ignored");
            }
        }
        const link = try self.allocator.create(secured_s2s_link.SecuredLink);
        errdefer self.allocator.destroy(link);
        // Raise the per-peer frame ceiling so a signed MEDIA_WS_DATAGRAM can
        // carry a full browser Cadence frame. Leave the shared
        // `s2s_frame.default_max_frame_size` (and thus portable-session
        // snapshot budgets) at 1 MiB.
        var media_s2s_cfg = self.config.s2s_config;
        if (media_s2s_cfg.max_frame_size < media_ws_relay.required_max_frame_size) {
            media_s2s_cfg.max_frame_size = media_ws_relay.required_max_frame_size;
        }
        link.* = try secured_s2s_link.SecuredLink.init(.{
            .allocator = self.allocator,
            .role = role,
            .identity = ident,
            .local_prekey = prekey,
            .cfg = .{
                .realm = ident.realm,
                .supported_bands = s2s_bands,
                .supported_features = s2s_features,
                .mesh_pass = if (self.mesh_admission_token.len != 0) self.mesh_admission_token else self.config.mesh_pass,
                .meshpass_roots = self.meshpass_roots,
                .now_ms = wall,
            },
            .rng = self.config.crypto_io.?,
            .server_name = self.serverName(),
            .description = self.config.server_description,
            .local_epoch_ms = wall,
            .inner_config = media_s2s_cfg,
            .expected_remotes = pins[0..pin_count],
            .trusted_node_keys = self.mesh_trusted_node_keys,
        });
        // Cross-namespace NICK collision resolution: the local world is
        // authoritative, so the route table renames a colliding remote nick to its
        // mesh UID. Retained through the lazy inner stand-up (post-AKE).
        link.setLocalNickResolver(self.localNickResolver());
        link.setResidenceVerifier(self.residenceVerifier());
        link.setSessionTokenResolver(self.sessionTokenResolver());
        link.setSessionTokenNickAuthorizer(self.sessionTokenNickAuthorizer());
        return link;
    }

    fn parseMeshTrustRoot(text: []const u8) ?[20]u8 {
        if (text.len == 40) {
            var out: [20]u8 = undefined;
            _ = std.fmt.hexToBytes(&out, text) catch return null;
            return out;
        }
        if (text.len == 64) {
            var key: [32]u8 = undefined;
            _ = std.fmt.hexToBytes(&key, text) catch return null;
            return node_identity.nodeIdFromPublicKey(key);
        }
        return null;
    }

    fn bindRelayV2UnboundIfReady(
        self: *LinuxServer,
        conn: *ConnState,
        link: *secured_s2s_link.SecuredLink,
    ) void {
        if (!conn.ownsActiveMeshLink(link) or conn.relay_v2_unbound_bound or
            !link.supportsSecureRelayV2()) return;
        const peer = link.remoteNodeId() orelse return;
        if (!self.relayV2DirectNeighbor(peer)) return;
        lockSpin(&self.relay_v2_replay_mu);
        _ = self.relay_v2_outbox.bindUnbound(peer);
        self.relay_v2_replay_mu.unlock();
        conn.relay_v2_unbound_bound = true;
        self.forwardAcceptedRelayV2(&.{});
    }

    /// Acquire this physical client's process-local gauge ownership exactly once.
    /// The monotonic total and the active gauge deliberately move together here.
    fn noteClientAccepted(self: *LinuxServer, conn: *ConnState) void {
        if (conn.stats_client_counted) return;
        conn.stats_client_counted = true;
        self.stats.onAccept();
    }

    /// Release exactly this slot's active-gauge ownership. An uncounted
    /// pre-admission socket is a no-op and can never subtract another live slot.
    fn dropClientStats(self: *LinuxServer, conn: *ConnState) void {
        if (!conn.stats_client_counted) return;
        conn.stats_client_counted = false;
        self.stats.onClose(false, false);
    }

    /// Record refusal of a completely initialized physical slot. The total was
    /// acquired when the slot became live; only its active ownership is released.
    fn noteClientRefusedBeforeLive(self: *LinuxServer, conn: *ConnState) void {
        self.dropClientStats(conn);
    }

    /// Acquire TCP-level S2S gauge ownership exactly once. Establishment remains
    /// a separate transition below, so an AKE-stuck slot is visible as tcp=1/link=0.
    fn noteS2sTcpOpened(self: *LinuxServer, conn: *ConnState) void {
        if (conn.stats_s2s_tcp_counted) return;
        conn.stats_s2s_tcp_counted = true;
        self.stats.onS2sAccept();
    }

    /// Count a mesh-routable peer once for metrics + journal. Idempotent per conn.
    fn noteS2sEstablished(self: *LinuxServer, conn: *ConnState, remote_name: []const u8, kind: []const u8) void {
        if (conn.s2s_established_counted) return;
        conn.s2s_established_counted = true;
        self.stats.onS2sEstablished();
        const name = if (remote_name.len != 0) remote_name else "pending-peer";
        var buf: [160]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, "mesh S2S established ({s}) peer={s}", .{ kind, name }) catch "mesh S2S established";
        srvLog("onyx-server: {s}\n", .{line});
        self.traceLog(.info, .s2s, line);
        if (self.meshDialForConn(conn)) |dial| self.noteMeshDialSuccess(dial);
    }

    /// Drive a PQ-secured S2S peer: feed inbound bytes through the framed Mooring
    /// link and queue its outbound. Logs the AKE establishment transition.
    fn driveS2sSecured(self: *LinuxServer, conn: *ConnState, link: *secured_s2s_link.SecuredLink, bytes: []const u8) void {
        if (!conn.meshAdmissionOpen() or conn.s2s_secured != link) return;
        const was = link.established();
        const now: u64 = @intCast(@max(0, self.nowMs()));
        link.feed(bytes, now) catch |err| {
            self.noteMeshConnectFailure(conn.token, "S2S handshake failed");
            var err_buf: [128]u8 = undefined;
            const detail = std.fmt.bufPrint(&err_buf, "secured link handshake/feed failed: {s}", .{@errorName(err)}) catch "secured link handshake/feed failed";
            // Journal-visible: auto-connect only logs "dial initiated", so a
            // silent PrekeyRejected/MeshPassMismatch/BadSignature loop is
            // invisible without this (2026-07-19 realm-rename domain netsplit).
            srvLog("onyx-server: mesh {s}\n", .{detail});
            self.traceLog(.warn, .s2s, detail);
            self.logMeshEvent(.link_handshake, if (link.remoteName().len != 0) link.remoteName() else "pending-secured-peer", detail);
            conn.closing = true;
            return;
        };
        const out = link.outbound();
        const out_len = out.len;
        if (out.len != 0) {
            // `out` may begin with whole encrypted records retained by a
            // retryable mesh burst. Inbound traffic is legal while our SendQ is
            // congested; page complete records and keep driving the received
            // RESYNC/ACK instead of closing merely because the queue is full.
            if (!self.flushMeshBurstStage(conn) and conn.closing) return;
        }
        // JUPE gate: refuse a peer whose server name is juped — checked on every
        // established drive (not just the first), so a peer juped AFTER it linked
        // is dropped on its next activity, on its own reactor thread (no
        // cross-reactor mutation). Runs before the peer_up announcement.
        if (link.established() and self.refuseJupedPeer(conn, link.remoteName())) return;
        const marker_capable = link.supportsReadMarkers();
        if (marker_capable and !conn.read_marker_capability_seen) {
            // The initial burst can finish before the distinct extension reply.
            // Offer again locally without requesting another handshake/RESYNC.
            conn.session_replica_resync_burst_pending = true;
            if (conn.mesh_burst_stage != .idle) conn.mesh_burst_restart_pending = true;
        }
        conn.read_marker_capability_seen = marker_capable;
        if (!was and link.established()) {
            self.noteS2sEstablished(conn, link.remoteName(), "secured");
            self.logMeshEvent(.peer_up, link.remoteName(), "secured link established");
            self.publishServerLink(link.remoteName(), true);
            self.markPeerHealth(link.remoteName(), .established);
            self.updatePartitionTransitions();
            if (self.resolveS2sCollision(conn, link.remoteName())) return; // this link lost the dedup
            // Publish only after collision resolution. If the new secured link
            // won, resolveS2sCollision marked the old route dedup-closing and
            // this immediately replaces its authenticated key in the trust
            // snapshot; if there was no collision it makes the peer trusted
            // without waiting for the periodic timer.
            self.publishPeerCount();

            // Replay the retained Store for both current and rolling-old peers.
            // Old peers receive an exact-once legacy translation of current
            // local OFFERs; they never trigger a whole-store refresh/remint.
            if (!conn.session_replica_replay_pending) self.scheduleSessionReplicaReplay(conn);
        }
        if (!conn.ownsActiveMeshLink(link)) return;
        self.bindRelayV2UnboundIfReady(conn, link);
        if (link.established()) {
            self.accountPeerBytes(link.remoteName(), bytes.len, out_len);
            self.syncPeerRtt(link.remoteName(), link.lastRttMs());
            self.notePeerSendBacklog(link.remoteName(), connSendBacklog(conn));
        }
        // Apply signed session authority BEFORE user-message delivery. OFFER and
        // the first MESSAGE can share one socket read; draining the frame-family
        // queues in the opposite order would falsely reject that first event.
        const residence_batch_complete = self.drainSessionReplicaV2(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        if (residence_batch_complete)
            link.processDeferredResidenceFrames(now)
        else
            link.discardDeferredResidenceFrames();
        // An incomplete authority feed whose RESYNC could not be durably queued
        // closes below. Do not deliver any other frame family from that same
        // feed after the fail-closed decision.
        if (conn.closing) return;
        // Drain inbound cross-node user messages over the secured link.
        if (link.takeInbound()) |inbound| {
            for (inbound) |*owned| {
                self.deliverRelay(owned.msg);
                owned.deinit(self.allocator);
            }
            self.allocator.free(inbound);
        } else |_| {}
        // Signed v2 is a separate exact-once authority and never falls through
        // legacy MESSAGE delivery/downgrade.
        // The authority drain above may unblock immutable MESSAGE_V2 objects
        // retained from an earlier read. Retry them before newer signed frames.
        self.retryDeferredRelayV2();
        self.drainRelayV2(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainRelayV2Acks(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Surface identity transitions in the exact order accepted by the peer.
        self.drainIdentityTransitions(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply/surface remote aggregate channel MODE flag changes in real time.
        self.drainChannelModeFlagChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply/surface remote parameter/IRCX channel MODE state in real time.
        self.drainChannelModeStateChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply/surface remote channel list-mode (+b/+e/+I) changes in real time.
        self.drainChannelListChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply remote IRCX channel PROP changes and surface non-secret updates.
        self.drainChannelPropChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply remote IRCX user/member PROP changes (ENTITY_PROP) to the store.
        self.drainEntityPropChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // E2EEGROUP authorization consumes the already-applied session,
        // residence, membership, and device-property authorities above.
        self.drainE2eeGroup(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainE2eeGroupAcks(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply/surface remote channel topic changes in real time.
        self.drainTopicChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Audit origin-spoofed or misrouted direct-owned S2S frames.
        self.drainOriginRejections(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Fold this peer's network-wide clone counts into the aggregate.
        self.drainCloneCountsFrom(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainOperEvents(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainOperEventsV2(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainObserveEvents(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainKills(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainWards(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainMeshSearch(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainKeyTransHeads(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainMemoPushes(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainMediaWsDatagrams(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainRepairResync(conn, link, true);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Consume tombstones first. The peer driver keeps frame families in
        // separate queues, so this ordering makes a consume win over a delayed
        // offer that arrived in the same socket turn.
        self.drainSessionMigrationConsumed(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Drain inbound live-session migration capsules: verify each against the
        // peer's authenticated node key (MigrationTarget.accept) and stage it in
        // pending_migrations for the client's eventual reconnect+reclaim. Only the
        // secured leg carries these (the capsule holds account/host state).
        self.drainSessionMigrations(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Drain inbound cross-mesh oper grants. Each is verified against the
        // peer's authenticated Ed25519 key from the Mooring handshake before it
        // can confer operator authority locally — an unverifiable grant is
        // silently dropped by applyMeshGrant.
        if (link.peerNodeKey()) |peer_key| {
            if (link.takeOperGrants()) |grants| {
                for (grants) |g| {
                    _ = self.applyMeshGrant(g, peer_key);
                    self.allocator.free(g);
                }
                self.allocator.free(grants);
            } else |_| {}
        }
        // A peer that resumed this link across a hot upgrade (its converged view was
        // reset to empty) asked us to re-send our full state. Answer with the same
        // burst a fresh establishment sends — it rides the preserved encrypted
        // stream, so the peer reconverges within one round-trip with no netsplit.
        if (link.established() and link.takeResyncRequest()) {
            // Queue and flush exact signed authority before any token-less
            // NICK/MEMBERSHIP burst. The peer may receive records in separate
            // TCP reads; sidecars must never become visible in an authority-free
            // window merely because RESYNC output was segmented.
            self.requestFullSessionReplicaReplay(conn);
        }
        // Establishment, repair, and explicit RESYNC only schedule/coalesce above.
        // Drain at most one bounded replay batch per socket-drive turn; invoking
        // once in a branch and again here would silently defeat both frame and
        // ciphertext budgets and make a repeated RESYNC skip the observable page.
        if (conn.session_replica_replay_pending) self.replaySessionReplicaStoreTo(conn, link);
        self.releaseMeshBurstAfterSessionReplicaReplay(conn, link);
    }

    /// Encode current local oper grants for one secured peer. The surrounding
    /// retryable burst stage owns encrypted-record pagination and clears no
    /// ciphertext until it has entered that peer's SendQ.
    ///
    /// Re-signs the live registry entries this node already issued — it does
    /// NOT mint a higher incarnation on the 30s anti-entropy cadence. Reminting
    /// every burst made peers treat an unchanged privilege refresh as
    /// `superseded` and re-broadcast synthetic `MODE +Y` forever.
    fn sendLocalOperBurstTo(self: *LinuxServer, conn: *ConnState) bool {
        if (!conn.isActiveMeshPeer()) return false;
        const link = conn.s2s_secured orelse return true;
        const kp = self.meshSignKey() orelse return true;
        const now = self.grantNowU64();
        const me = protocol_inventory.currentServerName();
        var it = self.oper_grants.liveIterator(now);
        while (it.next()) |fields| {
            if (!std.ascii.eqlIgnoreCase(fields.issuer_node, me)) continue;
            if (fields.privilege_bits == 0) continue; // tombstones are not anti-entropy cargo
            var buf: [oper_cred_share.max_grant_len]u8 = undefined;
            const n = oper_cred_share.sign(kp, fields, &buf) catch return false;
            link.sendOperGrant(buf[0..n]) catch return false;
        }
        // Catch a live local oper whose grant was never minted (boot race /
        // keyless→keyed transition). Real elevation still goes through
        // mintOperGrant; this only fills a missing registry row once.
        for (self.reactors) |*reactor| {
            var clients = reactor.clients.iterator();
            while (clients.next()) |entry| {
                const client = entry.value;
                if (client.s2s != null or client.s2s_secured != null) continue;
                if (!client.session.registered() or !client.session.isOper()) continue;
                const account = client.session.account() orelse continue;
                if (self.oper_grants.lookup(account, now) != null) continue;
                self.mintOperGrant(account, client.session.oper_priv, client.session.operClass(), client.session.operTitle());
            }
        }
        return true;
    }

    /// Ship every `mesh`-scope WARD this node currently holds to a freshly
    /// established secured peer, so a node that links after a ban was set still
    /// enforces it (mesh-ban anti-entropy, paralleling local oper grants).
    /// Best-effort; node-scope wards are local and never shipped. The burst
    /// driver owns the accumulated ciphertext and retry edge.
    fn meshBanFilterWire(self: *LinuxServer, buf: *[warden.mesh_ban_filter_wire_len]u8) ?[]const u8 {
        var filter = warden.buildMeshBanFilter(self.allocator, self.warden.all(), platform.realtimeMillis()) catch return null;
        defer filter.deinit();
        return warden.encodeMeshBanFilter(&filter, buf) catch null;
    }

    fn sendMeshWardsTo(self: *LinuxServer, conn: *ConnState) bool {
        if (!conn.isActiveMeshPeer()) return false;
        const link = conn.s2s_secured orelse return true;
        if (!link.established()) return true;
        // The compact filter is the first mesh-ban frame. The records below
        // are the authority; a filter hit never refuses by itself.
        var filter_buf: [warden.mesh_ban_filter_wire_len]u8 = undefined;
        const filter_wire = self.meshBanFilterWire(&filter_buf) orelse return false;
        link.sendWard(filter_wire) catch return false;
        for (self.warden.all()) |w| {
            if (w.scope != .mesh) continue;
            var wire_buf: [warden.max_wire_len]u8 = undefined;
            const wire = warden.encodeWire(.{
                .op = .add,
                .match = w.match,
                .pattern = w.pattern,
                .action = w.action,
                .reason = w.reason,
                .set_by = w.set_by,
                .created_ms = w.created_ms,
                .expires_ms = w.expires_ms,
            }, &wire_buf) catch return false;
            link.sendWard(wire) catch return false;
        }
        return true;
    }

    /// Re-mint + broadcast every locally-opered session's grant, so a freshly
    /// established secured peer learns this node's current operators without
    /// waiting for them to re-elevate. Grants ride only the secured mesh.
    /// Scans EVERY reactor's client table — a connection is pinned to its shard
    /// for life, so an oper homed on a sibling reactor would otherwise never be
    /// re-propagated on relink/RESYNC/repair and a peer that restarted (or
    /// USR2'd) would never learn the grant (its `*` silently missing). The scan
    /// is read-only and runs on the reactor-0 drive path under the
    /// completion-wide world lock, same as `isOverrideOper` and the presence
    /// burst; the mint/broadcast stays on this (reactor-0) thread.
    fn rebroadcastLocalOpers(self: *LinuxServer) void {
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                const c = entry.value;
                if (c.s2s != null or c.s2s_secured != null) continue;
                if (!c.session.registered() or !c.session.isOper()) continue;
                const account = c.session.account() orelse continue;
                self.mintOperGrant(account, c.session.oper_priv, c.session.operClass(), c.session.operTitle());
            }
        }
    }

    fn driveS2s(self: *LinuxServer, conn: *ConnState, link: *s2s_link.S2sLink, bytes: []const u8) void {
        if (!conn.meshAdmissionOpen() or conn.s2s != link) return;
        self.s2s_feed_seq +%= 1;
        const was = link.established();
        const now: u64 = @intCast(@max(0, self.nowMs()));
        link.feed(bytes, now, self.s2s_feed_seq) catch {
            self.noteMeshConnectFailure(conn.token, "S2S handshake failed");
            conn.closing = true;
            return;
        };
        // JUPE gate: see driveS2sSecured — checked on every established drive so a
        // peer juped after linking is dropped on its next activity (own thread).
        if (link.established() and self.refuseJupedPeer(conn, link.remoteName())) return;
        if (!was and link.established()) {
            self.noteS2sEstablished(conn, link.remoteName(), "plaintext");
            self.logMeshEvent(.peer_up, link.remoteName(), "link established");
            self.publishServerLink(link.remoteName(), true);
            self.markPeerHealth(link.remoteName(), .established);
            self.updatePartitionTransitions();
            if (self.resolveS2sCollision(conn, link.remoteName())) return; // this link lost the dedup
            self.publishPeerCount();
        }
        const out = link.outbound();
        if (out.len != 0) {
            appendToConn(conn, out) catch {
                conn.closing = true;
                return;
            };
            link.clearOutbound();
        }
        if (link.established()) {
            self.accountPeerBytes(link.remoteName(), bytes.len, out.len);
            self.syncPeerRtt(link.remoteName(), link.lastRttMs());
            self.notePeerSendBacklog(link.remoteName(), connSendBacklog(conn));
        }
        if (!conn.ownsActiveMeshLink(link)) return;
        // Drain inbound cross-node user messages and deliver to local clients.
        if (link.takeInbound()) |inbound| {
            for (inbound) |*owned| {
                self.deliverRelay(owned.msg);
                owned.deinit(self.allocator);
            }
            self.allocator.free(inbound);
        } else |_| {}
        // Surface identity transitions in the exact order accepted by the peer.
        self.drainIdentityTransitions(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply/surface remote aggregate channel MODE flag changes in real time.
        self.drainChannelModeFlagChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply/surface remote parameter/IRCX channel MODE state in real time.
        self.drainChannelModeStateChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply/surface remote channel list-mode (+b/+e/+I) changes in real time.
        self.drainChannelListChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply remote IRCX channel PROP changes and surface non-secret updates.
        self.drainChannelPropChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply remote IRCX user/member PROP changes (ENTITY_PROP) to the store.
        self.drainEntityPropChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Apply/surface remote channel topic changes in real time.
        self.drainTopicChanges(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Audit origin-spoofed or misrouted direct-owned S2S frames.
        self.drainOriginRejections(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        // Fold this peer's network-wide clone counts into the aggregate.
        self.drainCloneCountsFrom(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainOperEvents(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainObserveEvents(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainKills(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainWards(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainMeshSearch(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainKeyTransHeads(conn, link);
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainRepairResync(conn, link, false);
        if (!conn.ownsActiveMeshLink(link)) return;
        if (!conn.s2s_burst_done and link.established()) {
            if (self.sendMeshStateBurstTo(conn)) {
                conn.s2s_burst_done = true;
                self.notePeerAntiEntropy(link.remoteName());
            }
        }
    }

    /// Bridge a valid Merkle/RBSR repair response to live daemon state using the
    /// existing full-state resync path. The repair frame updates only the pure
    /// peer-driver CRDT shadow; user-visible roster/mode/prop state still arrives
    /// through normal daemon-drained S2S frame families.
    fn drainRepairResync(self: *LinuxServer, conn: *ConnState, link: anytype, secured: bool) void {
        if (!conn.ownsActiveMeshLink(link) or !link.takeRepairResyncRequest()) return;
        self.traceLog(.info, .s2s, "s2s repair applied; requesting full state resync");
        link.sendResync() catch {
            conn.closing = true;
            return;
        };
        if (comptime @TypeOf(link) == *secured_s2s_link.SecuredLink) {
            std.debug.assert(secured);
            if (!self.flushMeshBurstStage(conn) and conn.closing) return;
            // Repair can reset the peer's converged roster just like an explicit
            // RESYNC. Schedule/coalesce here; `driveS2sSecured` performs the one
            // replay batch allowed for this socket turn and releases the shared
            // roster/opers/wards/clone burst only after every page is queued.
            self.requestFullSessionReplicaReplay(conn);
        } else {
            std.debug.assert(!secured);
            self.flushS2sOutbound(conn, link.outbound()) catch {
                conn.closing = true;
                return;
            };
            link.clearOutbound();
            if (self.sendMeshStateBurstTo(conn)) self.notePeerAntiEntropy(link.remoteName());
        }
    }

    /// Completion for an outbound S2S connect: on success open the handshake from
    /// our side and start receiving; on failure tear the peer down.
    pub fn handleConnect(self: *LinuxServer, event: ringlane.ConnectEvent) !void {
        const conn = self.connForToken(event.token) catch return;
        const was_cancel_pending = conn.connect_cancel_pending;
        conn.connect_armed = false;
        conn.connect_cancel_pending = false;
        if (comptime builtin.os.tag == .windows) {
            if (conn.windows_force_close_cancel) {
                try self.closeConn(event.token, conn.close_reason);
                return;
            }
        }
        if (was_cancel_pending and event.res == -@as(i32, @intFromEnum(linux.E.CANCELED))) {
            conn.connect_rearm_pending = true;
            if (!self.rx().socket_io_quiescing) {
                self.armConnect(conn) catch {
                    self.wakeReactor();
                    return;
                };
                if (conn.connect_armed) conn.connect_rearm_pending = false;
            }
            return;
        }
        conn.connect_rearm_pending = false;
        if (conn.closing) {
            try self.closeConn(event.token, conn.close_reason);
            return;
        }
        if (event.res < 0) {
            self.noteMeshConnectFailure(event.token, "S2S connect failed");
            try self.closeConn(event.token, "S2S connect failed");
            return;
        }
        if (conn.s2s_secured) |_| {
            // Secured initiator: just listen — the responder sends its prekey
            // preamble first, which drives the handshake on recv.
            self.armRecv(conn) catch {
                conn.io_activation_pending = true;
                conn.activation_recv_required = true;
                self.wakeReactor();
            };
            return;
        }
        const link = conn.s2s orelse return;
        const now: u64 = @intCast(@max(0, self.nowMs()));
        link.start(now) catch {
            self.noteMeshConnectFailure(event.token, "S2S handshake failed");
            try self.closeConn(event.token, "S2S handshake failed");
            return;
        };
        const out = link.outbound();
        if (out.len != 0) {
            appendToConn(conn, out) catch {
                try self.closeConn(event.token, "S2S send overflow");
                return;
            };
            link.clearOutbound();
        }
        // RECV first makes partial acquisition safe: a full SQ on the SEND leg
        // leaves a live, owned slot that the bounded activator can finish.
        self.armRecv(conn) catch {
            conn.io_activation_pending = true;
            conn.activation_recv_required = true;
            self.wakeReactor();
            return;
        };
        self.armSendIfNeeded(conn) catch {
            conn.io_activation_pending = true;
            conn.activation_recv_required = true;
            self.wakeReactor();
        };
    }

    fn driveClientBytes(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, chunk: []const u8) !bool {
        if (conn.s2s_secured) |link| {
            self.driveS2sSecured(conn, link, chunk);
        } else if (conn.s2s) |link| {
            self.driveS2s(conn, link, chunk);
        } else if (conn.tls != null and conn.tls_rx_offloaded) {
            // kTLS RX offload: recv() already returned kernel-decrypted plaintext;
            // route it exactly as driveTls routes its decrypted output (WS frames
            // or IRC lines), bypassing the userspace TLS engine. A control record
            // would have surfaced as a recv error and closed the conn upstream.
            (if (conn.ws != null) self.driveWs(id, conn, chunk) else self.feedBytes(id, conn, chunk)) catch |err| switch (err) {
                error.LineTooLong => {
                    conn.close_reason = "Line too long";
                    try self.closeConn(conn.token, conn.close_reason);
                    return false;
                },
                else => return err,
            };
        } else if (conn.tls != null) {
            self.driveTls(id, conn, chunk) catch |err| switch (err) {
                error.LineTooLong => {
                    conn.close_reason = "Line too long";
                    try self.closeConn(conn.token, conn.close_reason);
                    return false;
                },
                else => return err,
            };
        } else if (conn.ws != null) {
            // Plain-ws testing mode only (the production ws listener always
            // carries TLS, so its bytes route through driveTls above).
            self.driveWs(id, conn, chunk) catch |err| switch (err) {
                error.LineTooLong => {
                    conn.close_reason = "Line too long";
                    try self.closeConn(conn.token, conn.close_reason);
                    return false;
                },
                else => return err,
            };
        } else {
            self.feedBytes(id, conn, chunk) catch |err| switch (err) {
                error.LineTooLong => {
                    conn.close_reason = "Line too long";
                    try self.closeConn(conn.token, conn.close_reason);
                    return false;
                },
                else => return err,
            };
        }
        // A driver may synchronously finalize a collision loser or terminal
        // failure after RECV released its storage reference. The completion
        // caller must not use that old pointer, even if its slot was reused.
        return self.connFor(id) != null;
    }

    fn driveProxyHeader(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, chunk: []const u8) !bool {
        if (chunk.len > conn.proxy_buf.len - conn.proxy_len) {
            conn.close_reason = "Bad PROXY header";
            conn.closing = true;
            return true;
        }
        @memcpy(conn.proxy_buf[conn.proxy_len .. conn.proxy_len + chunk.len], chunk);
        conn.proxy_len += chunk.len;
        const bytes = conn.proxy_buf[0..conn.proxy_len];

        if (bytes.len <= proxy_protocol.v2_signature.len and
            std.mem.eql(u8, bytes, proxy_protocol.v2_signature[0..bytes.len]))
        {
            return true;
        }
        if (bytes.len >= 16 and std.mem.startsWith(u8, bytes, &proxy_protocol.v2_signature)) {
            const total = proxy_protocol.v2TotalLength(bytes) catch |err| switch (err) {
                error.Truncated => return true,
                else => {
                    conn.close_reason = "Bad PROXY header";
                    conn.closing = true;
                    return true;
                },
            };
            if (total > proxy_protocol.max_header_bytes) {
                conn.close_reason = "Bad PROXY header";
                conn.closing = true;
                return true;
            }
        } else if (bytes.len > proxy_protocol.v1_max_line_len and std.mem.startsWith(u8, bytes, "PROXY ")) {
            conn.close_reason = "Bad PROXY header";
            conn.closing = true;
            return true;
        }

        const parsed = proxy_protocol.parse(bytes) catch |err| switch (err) {
            error.Truncated => return true,
            else => {
                conn.close_reason = "Bad PROXY header";
                conn.closing = true;
                return true;
            },
        };
        if (parsed.consumed > proxy_protocol.max_header_bytes) {
            conn.close_reason = "Bad PROXY header";
            conn.closing = true;
            return true;
        }
        if (proxyHeaderAddress(parsed.header)) |addr| self.applyAcceptedAddress(conn, addr);

        conn.proxy_pending = false;
        const rest = bytes[parsed.consumed..];
        if (!try self.startAcceptedClient(id, conn, conn.accept_kind, false)) return false;
        if (conn.closing) return true;
        if (rest.len != 0) return try self.driveClientBytes(id, conn, rest);
        return true;
    }

    /// Outcome of demuxing a kTLS-RX control record off `conn` (see
    /// `handleKtlsRxControl`).
    const KtlsRxDrain = enum {
        /// The conn survived (a KeyUpdate and/or app data was consumed) — re-arm recv.
        survived,
        /// The conn should be closed (close_notify / rekey-needed / fault). The
        /// caller sets `closing` and closes once the send queue drains.
        close,
        /// `driveClientBytes` already closed and freed the conn (e.g. LineTooLong) —
        /// the caller must return immediately and touch nothing further.
        freed,
    };

    /// kTLS-RX control-record demux. On an offloaded conn a kernel-decrypted TLS
    /// *control* record (KeyUpdate / close_notify) surfaces as a recv error because
    /// a plain recv cannot convey the record type; rather than drop the conn, read
    /// the queued record(s) via `recvmsg` + the `TLS_GET_RECORD_TYPE` cmsg and act
    /// on the content type. A KeyUpdate is consumed (no drop); any coalesced app
    /// data is fed to the IRC/WS layer; a close_notify closes gracefully; a
    /// rekey-needed or unexpected record closes fail-safe (distinct reasons for
    /// logs). Bounded by `ktls_control_drain_max`; `MSG.DONTWAIT` keeps it off the
    /// blocking path.
    fn handleKtlsRxControl(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) !KtlsRxDrain {
        _ = id;
        const t = conn.tls orelse return .close;
        if (t.control_phase != .kernel_control_read_held and conn.tls_tx_offloaded)
            conn.tls_kernel_prefix_remaining = sendq.wireBacklog(conn);
        t.control_phase = .kernel_control_read_held;
        t.held_record_len = 0;
        conn.io_activation_pending = true;
        conn.activation_recv_required = false;
        try self.progressTlsControl(conn);
        return if (conn.closing) .close else .survived;
    }

    fn tlsControlWaiting(conn: *const ConnState) bool {
        const t = conn.tls orelse return conn.tls_alert_pending;
        return t.control_phase != .none or t.tx_ku_reply_pending or t.hasCompleteBufferedInbound() or conn.tls_alert_pending;
    }

    /// The only live control-progress owner. It waits for armed kernel custody,
    /// replaces reserved credit with a real response, and drains one typed tail
    /// as a complete TLS preparation. Every retry preserves the stable phase.
    fn progressTlsControl(self: *LinuxServer, conn: *ConnState) anyerror!void {
        return self.progressTlsControlWithBudget(conn, 5);
    }

    /// Control progress can release buffered application input from a SEND or
    /// activation turn. Keep its parser policy local to this physical row, just
    /// as driveClientBytes does on RECV, without freeing storage under the
    /// control owner's active turn. The outer owner finalizes the closing row.
    fn driveTlsControlInput(self: *LinuxServer, conn: *ConnState, bytes: []const u8, decrypted: bool) !void {
        // A drain-close still completes its TLS control obligation. Its already
        // decrypted application bytes have no remaining command authority.
        if (decrypted and conn.closing) return;
        const id = idFromToken(conn.token);
        (if (!decrypted) self.driveTls(id, conn, bytes) else if (conn.ws != null)
            self.driveWs(id, conn, bytes)
        else
            self.feedBytes(id, conn, bytes)) catch |err| switch (err) {
            error.LineTooLong => {
                conn.close_reason = "Line too long";
                conn.closing = true;
                conn.tls_terminal_failure = true;
                discardTlsUnsealedTail(conn);
                conn.tls_discard_unsent = true;
                if (!conn.send_armed) {
                    discardPoisonedSendTail(conn);
                    conn.tls_discard_unsent = false;
                }
                conn.io_activation_pending = true;
                conn.activation_recv_required = false;
            },
            else => return err,
        };
    }

    /// A bounded owner control turn. The live scheduler budgets the whole KU;
    /// smaller positive turns use the same custody/cursor path, without assuming
    /// that a nonblocking syscall accepted the entire offered fragment.
    fn progressTlsControlWithBudget(self: *LinuxServer, conn: *ConnState, fragment_budget: usize) anyerror!void {
        if (self.rx().socket_io_quiescing or conn.send_armed or conn.tls_ingress_active or conn.tls_progress_active) return;
        conn.tls_progress_active = true;
        defer conn.tls_progress_active = false;
        const t = conn.tls orelse return;
        if (conn.tls_discard_unsent) {
            discardPoisonedSendTail(conn);
            conn.tls_discard_unsent = false;
        }
        if (conn.tls_alert_pending) {
            const accepted = ktls.sendControl(conn.fd, .alert, conn.tls_alert_bytes[conn.tls_alert_sent..]) catch |err| {
                if (err == error.WouldBlock) return;
                conn.tls_alert_pending = false;
                return;
            };
            conn.tls_alert_sent += @intCast(accepted);
            if (conn.tls_alert_sent == 2) conn.tls_alert_pending = false;
            return;
        }
        if (conn.tls_terminal_failure or conn.delivery_gap.load(.acquire)) return;
        if (t.tx_ku_reply_pending) {
            if (conn.tls_kernel_prefix_remaining != 0) return;
            const done = t.progressKernelReply(conn.fd, fragment_budget) catch |err| {
                self.failTls(conn, err);
                return;
            };
            sendq.consumeControlCharge(conn, done.accepted);
            if (!done.completed) return;
        }
        if (t.control_phase == .userspace_requested_ku_held) {
            // A sealed software prefix must reach the socket before new keys.
            // An unfunded kernel hold drains old accepted plaintext for credit.
            if (if (conn.tls_tx_offloaded) conn.tls_kernel_prefix_remaining != 0 else sendq.wireBacklog(conn) != 0) return;
            try self.driveTlsControlInput(conn, &.{}, false);
            if (conn.closing or t.control_phase == .userspace_requested_ku_held or t.tx_ku_reply_pending) return;
        }
        if (t.control_phase == .kernel_control_read_held) {
            if (if (conn.tls_tx_offloaded) conn.tls_kernel_prefix_remaining != 0 else sendq.wireBacklog(conn) != 0) return;
            const credit: usize = if (conn.tls_tx_offloaded) 5 else 27;
            var reservation = sendq.prepareControlReservation(conn, credit) catch return;
            reservation.commit();
            // Reserve exact ciphertext custody before recvmsg can admit a KU.
            var wire: ?sendq.PreparedReservedControlAppend(*ConnState) = null;
            if (!conn.tls_tx_offloaded) wire = sendq.prepareReservedControlAppend(conn, 27) catch return;
            defer if (wire) |*ticket| ticket.abort();
            var iterations: usize = 0;
            while (iterations < ktls_control_drain_max) : (iterations += 1) {
                const received = t.readKernelControl(conn.fd, &conn.recv_buf) catch |err| {
                    if (err == error.WouldBlock or err == error.OutOfMemory) return;
                    self.failTls(conn, err);
                    return;
                };
                switch (received) {
                    .progress => {},
                    .application => |plain| {
                        // A control indication can coalesce a later app record.
                        // The instance rejects interleaving before parser/liveness.
                        sendq.cancelControlReservation(conn);
                        conn.tls_kernel_prefix_remaining = 0;
                        t.control_phase = if (conn.tls_deferred_plain.items.len != 0) .software_tail_ready else .none;
                        if (conn.closing) break;
                        conn.last_activity_ms = self.nowMs();
                        conn.awaiting_pong = false;
                        self.stats.onBytesIn(plain.len);
                        try self.driveTlsControlInput(conn, plain, true);
                        break;
                    },
                    .key_update => |ku| {
                        if (ku.software_reply) |reply| {
                            defer self.allocator.free(reply);
                            wire.?.commit(reply);
                        } else if (!ku.requested) sendq.cancelControlReservation(conn);
                        conn.tls_kernel_prefix_remaining = 0;
                        t.control_phase = if (conn.tls_deferred_plain.items.len != 0) .software_tail_ready else .none;
                        conn.last_activity_ms = self.nowMs();
                        conn.awaiting_pong = false;
                        break;
                    },
                }
            }
            if (t.control_phase == .kernel_control_read_held or t.tx_ku_reply_pending) return;
        }
        if (t.control_phase == .software_tail_ready) {
            var chunks: std.ArrayList([]const u8) = .empty;
            defer chunks.deinit(self.allocator);
            var iterator = sendq.DeferredIterator{ .bytes = conn.tls_deferred_plain.items };
            while (iterator.next() catch {
                self.failTls(conn, error.InvalidDeferred);
                return;
            }) |part| chunks.append(self.allocator, part) catch return;
            var encrypted = t.prepareDeferredWriteBatch(chunks.items) catch |err| switch (err) {
                error.OutOfMemory => return,
                else => {
                    self.failTls(conn, err);
                    return;
                },
            };
            defer encrypted.deinit();
            if (encrypted.bytes().len != conn.tls_deferred_charge) {
                self.failTls(conn, error.InvalidDeferred);
                return;
            }
            var replacement = sendq.prepareDeferredReplacement(conn, encrypted.bytes().len) catch return;
            replacement.commit(encrypted.bytes());
            encrypted.commit();
            t.control_phase = .none;
        }
        if (t.control_phase == .none and t.hasCompleteBufferedInbound()) {
            try self.driveTlsControlInput(conn, &.{}, false);
        }
    }

    fn discardTlsUnsealedTail(conn: *ConnState) void {
        conn.tls_deferred_plain.clearRetainingCapacity();
        conn.tls_deferred_charge = 0;
        sendq.cancelControlReservation(conn);
    }

    fn failTls(self: *LinuxServer, conn: *ConnState, failure: anyerror) void {
        const t = conn.tls orelse return;
        conn.tls_terminal_failure = true;
        conn.closing = true;
        conn.close_reason = if (failure == error.TlsAlert) "TLS peer alert" else "TLS record failure";
        discardTlsUnsealedTail(conn);
        if (failure == error.TlsAlert) {
            conn.tls_discard_unsent = true;
        } else if (conn.tls_tx_offloaded) {
            // No accepted plaintext suffix can continue after an ambiguous
            // kernel epoch. Retain armed storage until its exact CQE, then
            // dispose all unsent app/control liability before final teardown.
            conn.tls_discard_unsent = true;
            // Pending old-key KU failure has no coherent alert epoch. Close.
            if (!t.tx_ku_reply_pending) if (tls_record.fatalAlertBytes(failure)) |bytes| {
                conn.tls_alert_bytes = bytes;
                conn.tls_alert_sent = 0;
                conn.tls_alert_pending = true;
                conn.tls_discard_unsent = true;
            };
        } else if (t.takeAlert(failure)) |alert| {
            defer self.allocator.free(alert);
            rawAppendToConn(conn, alert) catch {};
        }
        if (conn.tls_discard_unsent and !conn.send_armed) {
            discardPoisonedSendTail(conn);
            conn.tls_discard_unsent = false;
        }
        conn.io_activation_pending = true;
        conn.activation_recv_required = false;
    }

    pub fn handleRecv(self: *LinuxServer, event: ringlane.RecvEvent) !void {
        const id = idFromToken(event.token);
        const conn = try self.connForToken(event.token);
        const was_cancel_pending = conn.recv_cancel_pending;
        conn.recv_armed = false;
        conn.recv_cancel_pending = false;
        if (comptime builtin.os.tag == .windows) {
            if (conn.windows_force_close_cancel) {
                try self.closeConn(event.token, conn.close_reason);
                return;
            }
        }

        // Helix's exact cancel releases the kernel's recv_buf reference without
        // meaning EOF. Preserve the live stream and, while the owner is at its
        // safe point, deliberately do not arm a replacement RECV. A close that
        // was already latched still gets its ordinary all-refs-clear finalizer.
        if (was_cancel_pending and
            event.res == -@as(i32, @intFromEnum(linux.E.CANCELED)))
        {
            if (!self.rx().socket_io_quiescing) {
                // Failure-resume may have released the shared barrier before a
                // cancel's original CQE arrived. Retain accepted close output
                // just as on SEND cancellation; ECANCELED is not a stream gap.
                try self.armSendIfNeeded(conn);
                if (conn.closing and !hasUnsentOutput(conn))
                    try self.closeConn(event.token, conn.close_reason)
                else if (!conn.closing)
                    try self.armRecv(conn);
            } else if (conn.closing and !hasUnsentOutput(conn)) {
                try self.closeConn(event.token, conn.close_reason);
            }
            return;
        }

        // A close requested by another completion/timer wins over any positive
        // bytes that raced with shutdown. The CQE has released recv_buf; discard
        // its payload and let the all-refs-clear finalizer decide whether the slot
        // can now be recycled.
        if (conn.closing) {
            try self.armSendIfNeeded(conn);
            if (!hasUnsentOutput(conn))
                try self.closeConn(event.token, conn.close_reason);
            return;
        }

        // Check before kTLS control handling, liveness mutation, or IRC parsing.
        // A positive recv must never overwrite `closing` and execute commands
        // after another shard declared an outbound byte gap.
        if (self.abortDeliveryGapFor(id, conn)) return;

        // kTLS RX offload: a kernel-decrypted TLS control record surfaces here as a
        // recv error (res < 0, typically -EIO) because a plain recv cannot carry the
        // record type. Demux it via recvmsg + cmsg instead of dropping the conn — a
        // KeyUpdate is consumed and the conn continues; a close_notify closes.
        if (conn.tls_rx_offloaded and event.res < 0) {
            switch (try self.handleKtlsRxControl(id, conn)) {
                .freed => return,
                .survived => {
                    try self.armSendIfNeeded(conn);
                    if (!conn.closing) {
                        try self.armRecv(conn);
                    } else if (!hasUnsentOutput(conn)) {
                        try self.closeConn(event.token, conn.close_reason);
                    }
                    return;
                },
                .close => {
                    conn.closing = true;
                    try self.armSendIfNeeded(conn);
                    if (!hasUnsentOutput(conn)) {
                        try self.closeConn(event.token, conn.close_reason);
                    }
                    return;
                },
            }
        }

        if (event.res <= 0) conn.closing = true;
        if (event.res > 0) {
            if (conn.tls_rx_offloaded) {
                const t = conn.tls orelse return error.ClientNotFound;
                if (!t.kernelApplicationAllowed()) {
                    self.failTls(conn, error.BadHandshake);
                    try self.armSendIfNeeded(conn);
                    return;
                }
            }
            const chunk = conn.recv_buf[0..@as(usize, @intCast(event.res))];
            self.stats.onBytesIn(chunk.len);
            // Any inbound traffic proves liveness: refresh the idle clock and
            // clear a pending ping-timeout (the client answered, PONG or not).
            conn.last_activity_ms = self.nowMs();
            conn.awaiting_pong = false;
            // Inbound bytes are presence. The peer's hybrid logical clock is not read.
            if (activeMeshPeerName(conn)) |peer_name| self.notePeerStillHere(peer_name, 0);
            if (conn.proxy_pending) {
                if (!try self.driveProxyHeader(id, conn, chunk)) return;
            } else {
                if (!try self.driveClientBytes(id, conn, chunk)) return;
            }
            try self.armSendIfNeeded(conn);
            if (!conn.closing) {
                try self.armRecv(conn);
            }
        }
        if (conn.closing and !hasUnsentOutput(conn)) {
            try self.closeConn(event.token, conn.close_reason);
        }
    }

    pub fn handleSend(self: *LinuxServer, event: ringlane.SendEvent) !void {
        const id = idFromToken(event.token);
        const conn = try self.connForToken(event.token);
        const was_cancel_pending = conn.send_cancel_pending;
        const submitted = conn.send_submitted_len;
        const submitted_offset = conn.send_submitted_offset;
        conn.send_submitted_len = 0;
        conn.send_submitted_offset = 0;
        conn.send_armed = false;
        conn.send_cancel_pending = false;
        if (comptime builtin.os.tag == .windows) {
            if (conn.windows_force_close_cancel) {
                try self.closeConn(event.token, conn.close_reason);
                return;
            }
        }
        // Cancellation is not a stream error. No bytes were accepted, so retain
        // the exact unsent [send_offset, send_len) tail for the Helix snapshot.
        if (was_cancel_pending and
            event.res == -@as(i32, @intFromEnum(linux.E.CANCELED)))
        {
            if (!self.rx().socket_io_quiescing) {
                try self.armSendIfNeeded(conn);
                if (conn.closing and !hasUnsentOutput(conn))
                    try self.closeConn(event.token, conn.close_reason)
                else if (!conn.closing)
                    try self.armRecv(conn);
            }
            return;
        }
        // The CQE released the kernel's reference. Drop the entire unsent tail
        // now; sending any later queued bytes would cross the known stream gap.
        if (self.abortDeliveryGapFor(id, conn)) return;
        if (event.res < 0) {
            // An actual stream error cannot complete the collision handshake.
            // Preserve the ordinary immediate failure path instead of retrying
            // a tail across a known byte gap.
            conn.s2s_dedup_drain_deadline_ms = 0;
            try self.closeConn(event.token, conn.close_reason);
            return;
        }

        if (event.res == 0) {
            try self.closeConn(event.token, "SEND made no progress");
            return;
        }
        const accepted: usize = @intCast(event.res);
        if (accepted > submitted or submitted_offset != conn.send_offset or
            conn.send_offset > conn.send_len or accepted > conn.send_len - conn.send_offset)
        {
            try self.closeConn(event.token, "Invalid SEND completion");
            return;
        }
        if (conn.tls_kernel_prefix_remaining != 0) {
            if (accepted > conn.tls_kernel_prefix_remaining) {
                try self.closeConn(event.token, "Invalid TLS prefix completion");
                return;
            }
            conn.tls_kernel_prefix_remaining -= accepted;
        }
        self.stats.onBytesOut(accepted);
        conn.send_offset += @as(usize, @intCast(event.res));
        if (conn.send_offset >= conn.send_len) {
            conn.send_offset = 0;
            conn.send_len = 0;
            // Inline buffer drained: pull the next chunk of the SendQ overflow into
            // it (nothing is armed here, so refilling the inline buffer is safe).
            refillFromOverflow(conn);
        }

        try self.armSendIfNeeded(conn);
        // Once the send stream is fully drained (armSendIfNeeded above re-armed if
        // the overflow still had data), a pending kTLS conn attaches TX offload.
        self.maybeAttachKtlsTx(conn);
        if (conn.closing and !hasUnsentOutput(conn)) {
            try self.closeConn(event.token, conn.close_reason);
        }
    }

    const DeliveryOutcome = enum {
        /// Every byte (or owner control record) was accepted for this exact
        /// generation. It may still be queued in the target shard's mailbox.
        delivered,
        /// The generational target no longer exists. A stale delivery is benign
        /// and must never poison a later client that reused the same slot.
        target_gone,
        /// A live exact generation developed an ordering gap and was atomically
        /// marked for owner-side disconnect.
        poisoned,
    };

    const delivery_gap_reason = "Delivery gap; reconnect/resume required";

    /// Publish a delivery gap to one exact target generation. Connection slabs
    /// reserve their complete backing storage at boot, so the atomic field never
    /// moves; `get(id)` validates shard+slot+generation under the completion-wide
    /// World lock before a foreign reactor touches that one atomic. A stale id
    /// therefore cannot poison a client that later reused its slot.
    fn poisonDeliveryGeneration(self: *LinuxServer, id: client_model.ClientId) DeliveryOutcome {
        const conn = self.connFor(id) orelse return .target_gone;
        conn.delivery_gap.store(true, .release);
        self.wakeShard(id.shard);
        return .poisoned;
    }

    /// Owner-only first phase of the abort. Do not immediately free an armed
    /// connection: io_uring may still hold a reference to its inline send buffer.
    fn beginDeliveryGapAbort(_: *LinuxServer, conn: *ConnState) void {
        if (conn.delivery_abort_started) return;
        conn.delivery_abort_started = true;
        conn.s2s_dedup_drain_deadline_ms = 0;
        conn.closing = true;
        conn.close_reason = delivery_gap_reason;
    }

    /// Discard every byte that has not reached the kernel. This is legal only
    /// after an armed send CQE releases its reference (or when no send was armed
    /// at observation time); mutating the inline buffer earlier would race the
    /// kernel's zero-copy read.
    fn discardPoisonedSendTail(conn: *ConnState) void {
        std.debug.assert(!conn.send_armed);
        conn.send_offset = 0;
        conn.tls_kernel_prefix_remaining = 0;
        conn.send_len = 0;
        if (conn.send_overflow.capacity > 0)
            conn.send_overflow.clearAndFree(conn.overflow_allocator);
        conn.tls_deferred_plain.clearAndFree(conn.overflow_allocator);
        conn.tls_deferred_charge = 0;
        conn.tls_control_charge = 0;
    }

    /// Observe and, when no send SQE owns the buffer, finish one poisoned
    /// connection immediately. Returns true whenever command/delivery processing
    /// must stop for this connection, including while final close is deferred.
    fn abortDeliveryGapFor(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
    ) bool {
        if (!conn.delivery_gap.load(.acquire)) return false;
        self.beginDeliveryGapAbort(conn);
        if (!conn.send_armed) {
            discardPoisonedSendTail(conn);
            const token = tokenFromId(id) catch return true;
            self.closeConn(token, conn.close_reason) catch {};
        }
        return true;
    }

    /// Owner-reactor sweep used at every boundary that could otherwise process a
    /// later command or timer action. Slot storage stays stable while closeConn
    /// frees the current entry, matching retryFailedSessionHandoffs' iteration.
    fn abortPoisonedDeliveries(self: *LinuxServer) void {
        _ = self.abortPoisonedDeliveriesCount();
    }

    /// Count owner-side poison transitions for the Helix fabric fixed point.
    /// A poisoned close can itself publish cross-shard state, so that transition
    /// is progress even when the mailbox was empty at the start of the pass.
    fn abortPoisonedDeliveriesCount(self: *LinuxServer) usize {
        var progressed: usize = 0;
        var index: usize = 0;
        while (index < self.rx().clients.slots.items.len) : (index += 1) {
            const slot = &self.rx().clients.slots.items[index];
            if (!slot.occupied or !slot.value.delivery_gap.load(.acquire)) continue;
            const id = slotClientId(self.rx(), index, slot.gen);
            _ = self.abortDeliveryGapFor(id, &slot.value);
            // Count every unresolved poison on every pass. Therefore a zero
            // progress fixed-point pass proves no occupied poisoned slot remains;
            // an abort that cannot finish reaches the derived bound and refuses.
            progressed += 1;
        }
        return progressed;
    }

    /// Mark a failure discovered by the target owner itself. The caller must not
    /// touch `conn` after the next abort sweep because it may free the slot.
    pub fn poisonOwnedDelivery(self: *LinuxServer, conn: *ConnState) void {
        conn.delivery_gap.store(true, .release);
        self.beginDeliveryGapAbort(conn);
    }

    /// The single cross-shard-aware outbound byte sink. Every "write a finished
    /// line (or lines) to the connection behind `id`" path funnels here so the
    /// shard decision is made in exactly one place:
    ///
    ///   * `id` on THIS reactor's shard  → append to its local send buffer and arm
    ///     send, exactly as the single-reactor path always did (no copy, no lock).
    ///   * `id` on ANOTHER shard          → copy the bytes into pooled `DeliverBuf`s
    ///     (chunked to the pool's per-buffer max, FIFO-ordered), hand each off to
    ///     the owning shard's fabric mailbox, and wake that reactor. The target
    ///     reactor drains its mailbox in `onWakePoll`, appends to the local conn,
    ///     and releases the buffer. A connection's send buffer / ring is therefore
    ///     never touched by a non-owning reactor.
    ///
    /// Returns `error.ClientNotFound` only for a LOCAL miss (stale/closed slot);
    /// a cross-shard handoff cannot see the target's liveness, so it best-effort
    /// enqueues and the owning reactor drops the bytes if the slot is gone.
    fn enqueueDelivery(self: *LinuxServer, id: client_model.ClientId, bytes: []const u8) !void {
        _ = self.enqueueDeliveryMaybeClose(id, bytes, false, "Client quit");
    }

    fn enqueuePreframedSecureDelivery(self: *LinuxServer, id: client_model.ClientId, bytes: []const u8) !void {
        _ = self.enqueueDeliveryMaybeCloseEx(id, bytes, .{
            .close_after = false,
            .close_reason = "Client quit",
            .preframed_secure = true,
        });
    }

    pub fn enqueueDeliveryThenClose(self: *LinuxServer, id: client_model.ClientId, bytes: []const u8, close_reason: []const u8) !void {
        _ = self.enqueueDeliveryMaybeClose(id, bytes, true, close_reason);
    }

    pub fn enqueueCloseOnOwner(self: *LinuxServer, id: client_model.ClientId, close_reason: []const u8) !void {
        if (id.shard == self.rx().shard_id) {
            const tok = try tokenFromId(id);
            return self.closeConn(tok, close_reason);
        }
        // A close is an authority decision, not merely an ordered mailbox item.
        // Publish the exact-generation atomic before the owner can consume a
        // positive RECV CQE that raced ahead of this control message. The owner
        // checks delivery_gap before parsing bytes, so successful enqueue and
        // mailbox congestion have the same fail-closed command boundary.
        if (self.poisonDeliveryGeneration(id) == .target_gone) return;
        const fabric = if (self.fabric) |*f| f else {
            return;
        };
        const buf = fabric.acquire(id.shard, "") orelse {
            self.noteCrossShardDrop(fabric, 1);
            return;
        };
        if (!fabric.sendTo(id.shard, .{ .to = id, .buf = buf, .close_after = true, .close_reason = close_reason })) {
            fabric.release(id.shard, buf);
            self.noteCrossShardDrop(fabric, 1);
            return;
        }
        self.wakeShard(id.shard);
    }

    /// Complete an attached DROP on this reactor only. Foreign owners are
    /// fail-closed at dispatch until the reserved two-owner protocol lands.
    fn revokeAttachedSessionOnLocalOwner(self: *LinuxServer, account: []const u8, expected: sessions_mod.Session) ListedSessionRevoke {
        if (account.len > 64) return .stale;
        const notice = ":onyx.local NOTICE * :SESSION: this session was revoked from another device\r\n";
        const id = clientIdFromMonitor(expected.client);
        if (id.shard != self.rx().shard_id) return .temporarily_unavailable;
        {
            const conn = self.rx().clients.get(id) orelse return .stale;
            const conn_account = conn.session.account() orelse return .stale;
            if (!std.ascii.eqlIgnoreCase(conn_account, account) or conn.closing) return .stale;

            // Stage every fallible World mutation while the exact row still
            // exists.  `closeConn` uses that row to discover a live sibling;
            // removing it first would turn this into a false final QUIT.
            var restores: std.ArrayListUnmanaged(world_model.MemberRestore) = .empty;
            defer restores.deinit(self.allocator);
            const nick = conn.session.displayName();
            var successor: ?client_model.ClientId = null;
            var first_eligible: ?client_model.ClientId = null;
            const from_wid = worldIdFromClient(id);
            const nick_owner = self.world.findNick(nick);
            const rows = self.sessions.copySessionsAlloc(self.allocator, account) catch return .temporarily_unavailable;
            defer self.allocator.free(rows);
            var unattested_exact_sibling = false;
            for (rows) |row| {
                if (!row.attached or row.client == expected.client) continue;
                if (!std.crypto.timing_safe.eql(sessions_mod.Token, row.token, expected.token)) continue;
                const candidate_id = clientIdFromMonitor(row.client);
                if (candidate_id.shard != self.rx().shard_id) {
                    unattested_exact_sibling = true;
                    continue;
                }
                const candidate = self.connFor(candidate_id) orelse {
                    unattested_exact_sibling = true;
                    continue;
                };
                if (candidate.closing or candidate.s2s != null or candidate.s2s_secured != null) {
                    unattested_exact_sibling = true;
                    continue;
                }
                const candidate_account = candidate.session.account() orelse continue;
                if (!std.ascii.eqlIgnoreCase(candidate_account, account)) continue;
                if (!std.ascii.eqlIgnoreCase(candidate.session.displayName(), nick)) continue;
                if (first_eligible == null) first_eligible = candidate_id;
                if (nick_owner) |owner| {
                    if (owner.eql(worldIdFromClient(candidate_id))) {
                        successor = candidate_id;
                        break;
                    }
                }
            }
            // If the target is still the rendered nick owner, any validated
            // exact sibling can take it.  If another exact sibling owns the
            // nick, it must be chosen: claiming onto an arbitrary earlier row
            // would reject NickInUse and make a safe local revoke unavailable.
            if (successor == null) if (nick_owner) |owner| {
                if (owner.eql(from_wid)) successor = first_eligible;
            };
            // A same-token attached row whose owner cannot participate in this
            // transaction is evidence that this is not a final-row close. It
            // must not be downgraded to a QUIT-producing final revoke.
            if (successor == null and (unattested_exact_sibling or first_eligible != null)) return .temporarily_unavailable;

            var handoff: ?world_model.World.PreparedSessionRestore = null;
            if (successor) |next| {
                const to_wid = worldIdFromClient(next);
                var channels = self.world.channels.iterator();
                while (channels.next()) |entry| {
                    const old_modes = self.world.memberModes(entry.key_ptr.*, from_wid);
                    const next_modes = self.world.memberModes(entry.key_ptr.*, to_wid);
                    if (old_modes == null and next_modes == null) continue;
                    restores.append(self.allocator, .{
                        .channel = entry.key_ptr.*,
                        .modes = .{ .bits = (if (old_modes) |m| m.bits else 0) | (if (next_modes) |m| m.bits else 0) },
                    }) catch return .temporarily_unavailable;
                }
                const exact = [_]world_model.ClientId{ from_wid, to_wid };
                handoff = self.world.prepareSessionRestore(
                    nick,
                    to_wid,
                    &exact,
                    .{ .claim_exact = to_wid },
                    restores.items,
                ) catch return .temporarily_unavailable;
            }
            defer if (handoff) |*prepared| prepared.abort();

            // The Store CAS is the linearization point.  A stale LIST selector
            // aborts the inert World ticket, leaving nick/membership unchanged.
            const handle = self.sessions.removeExact(account, expected) orelse return .stale;
            if (handoff) |*prepared| {
                prepared.commit();
                conn.session_handoff_complete = true;
            }
            conn.session_handoff_checked = true;
            lockSpin(&self.attachment_delivery_mu);
            _ = self.attachment_delivery_spool.discardAttachment(expected.client);
            self.attachment_delivery_mu.unlock();
            self.finalizeRemovedSessionAuthority(handle);
            self.enqueueDeliveryThenClose(id, notice, "session revoked") catch {};
            return .removed;
        }
    }

    fn enqueueDeliveryMaybeClose(self: *LinuxServer, id: client_model.ClientId, bytes: []const u8, close_after: bool, close_reason: []const u8) DeliveryOutcome {
        return self.enqueueDeliveryMaybeCloseEx(id, bytes, .{
            .close_after = close_after,
            .close_reason = close_reason,
            .preframed_secure = false,
        });
    }

    const DeliveryOptions = struct {
        close_after: bool,
        close_reason: []const u8,
        preframed_secure: bool,
    };

    fn enqueueDeliveryMaybeCloseEx(self: *LinuxServer, id: client_model.ClientId, bytes: []const u8, opts: DeliveryOptions) DeliveryOutcome {
        // Local fast path (always taken in single-reactor mode, where shard_id==0
        // and every id carries shard 0).
        if (id.shard == self.rx().shard_id) {
            const conn = self.rx().clients.get(id) orelse return .target_gone;
            if (conn.closing) return .target_gone;
            // A full send buffer is the RECIPIENT's fault (it stopped reading):
            // poison that exact recipient and report the outcome without faulting
            // the sender, so a fan-out continues to later healthy recipients.
            const append_result = if (opts.preframed_secure)
                appendSecuredToConn(conn, bytes)
            else
                appendToConn(conn, bytes);
            append_result catch {
                self.poisonOwnedDelivery(conn);
                return .poisoned;
            };
            self.armSendIfNeeded(conn) catch {
                self.poisonOwnedDelivery(conn);
                return .poisoned;
            };
            if (opts.close_after) {
                conn.close_reason = opts.close_reason;
                conn.closing = true;
            }
            return .delivered;
        }
        // Cross-shard: hand off through the fabric. An absent fabric is itself a
        // stream gap; publish poison directly to the exact reserved slab entry.
        const fabric = if (self.fabric) |*f| f else return self.poisonDeliveryGeneration(id);
        var off: usize = 0;
        while (off < bytes.len) {
            const end = @min(off + deliver_handle.max_bytes, bytes.len);
            const chunk = bytes[off..end];
            // Poison on the FIRST acquire failure, matching `enqueueCloseOnOwner`.
            // The only paths that free a `DeliverBuf` / inbox slot run under the
            // same `world.lockWrite` this sender holds, so a retry-spin here can
            // never succeed — it only burns cycles and stalls every other reactor
            // on that lock (an overload amplifier to a wedged shard). A prior chunk
            // may already be in the mailbox; poison makes that partial stream
            // terminal so later bytes cannot overtake it.
            const buf = fabric.acquire(id.shard, chunk) orelse {
                const outcome = self.poisonDeliveryGeneration(id);
                self.noteCrossShardDrop(fabric, 1);
                return outcome;
            };
            const is_last = opts.close_after and end == bytes.len;
            if (!fabric.sendTo(id.shard, .{
                .to = id,
                .buf = buf,
                .close_after = is_last,
                .close_reason = opts.close_reason,
                .preframed_secure = opts.preframed_secure,
            })) {
                // Same rationale: the inbox drains only under the world lock this
                // sender holds, so poison on the first full-inbox observation.
                fabric.release(id.shard, buf);
                const outcome = self.poisonDeliveryGeneration(id);
                self.noteCrossShardDrop(fabric, 1);
                return outcome;
            }
            off = end;
        }
        // Wake the OWNING reactor through its own wake eventfd (the one it arms a
        // poll on each loop). Its wake-poll completion runs `drainFabric`, which
        // consumes the mailbox we just pushed to. We deliberately do not use the
        // fabric's own wake fds: the reactor loop only watches `Reactor.wake`, so
        // unifying on it reuses the existing arm/poll plumbing.
        //
        // Inside a fan-out (`beginWakeBatch`), do NOT wake per recipient: record
        // the touched shard and let `endWakeBatch` fire ONE wake per shard after
        // the whole member loop. Wakes still land strictly after every enqueue, so
        // no wake is missed; a channel with M cross-shard members costs K wakes
        // (K = distinct shards) instead of M eventfd writes.
        const rctr = self.rx();
        if (rctr.wake_batch.active()) {
            rctr.wake_batch.mark(id.shard);
        } else {
            self.wakeShard(id.shard);
        }
        return .delivered;
    }

    /// Wake the reactor owning `shard` through its own wake eventfd so its loop
    /// runs and drains its fabric inbox. No-op if that reactor has no eventfd.
    inline fn wakeShard(self: *LinuxServer, shard: u12) void {
        if (self.reactors[shard].wake) |*w| w.wake();
    }

    /// Account `n` cross-shard messages shed under sustained back-pressure. Bumps
    /// the fabric's observable counter and emits a rate-limited warn (first drop,
    /// then every 1024th) so a lossy fan-out surfaces in logs without spamming.
    fn noteCrossShardDrop(self: *LinuxServer, fabric: *reactor_fabric.ReactorFabric, n: u64) void {
        const prior = fabric.recordDrop(n);
        if (prior % 1024 == 0) {
            var buf: [128]u8 = undefined;
            const line = std.fmt.bufPrint(
                &buf,
                "cross-shard delivery dropped under back-pressure (total {d})",
                .{prior + n},
            ) catch "cross-shard delivery dropped under back-pressure";
            self.traceLog(.warn, .reactor, line);
        }
    }

    /// Total cross-shard messages dropped under back-pressure (0 without a fabric).
    fn crossShardDrops(self: *LinuxServer) u64 {
        const fabric = if (self.fabric) |*f| f else return 0;
        return fabric.droppedCount();
    }

    /// Open a fan-out wake batch on the calling reactor. Until the matching
    /// `endWakeBatch`, cross-shard deliveries record their target shard instead of
    /// waking it, so an M-member broadcast coalesces to one wake per touched shard.
    /// Re-entrant (depth-counted); pair with `defer self.endWakeBatch()`.
    inline fn beginWakeBatch(self: *LinuxServer) void {
        self.rx().wake_batch.depth += 1;
    }

    /// Close a fan-out wake batch. The OUTERMOST close (depth→0) fires exactly one
    /// wake per distinct shard touched during the batch and clears the set. Because
    /// every enqueue happened before this flush, no wake can be missed.
    fn endWakeBatch(self: *LinuxServer) void {
        const batch = &self.rx().wake_batch;
        std.debug.assert(batch.depth > 0);
        batch.depth -= 1;
        if (batch.depth != 0) return;
        for (&batch.words, 0..) |*w, wi| {
            var bits = w.*;
            while (bits != 0) {
                const b: u6 = @intCast(@ctz(bits));
                const shard: u12 = @intCast(wi * WakeBatch.word_bits + b);
                self.wakeShard(shard);
                bits &= bits - 1;
            }
            w.* = 0;
        }
    }

    pub fn deliver(self: *LinuxServer, id: client_model.ClientId, bytes: []const u8) !void {
        return self.enqueueDelivery(id, bytes);
    }

    /// Shard-aware equivalent of `queueNumeric` + arm: format the numeric for the
    /// connection behind `id` (using its display name read from the owning reactor
    /// under the world lock) and route the bytes through `enqueueDelivery` (local
    /// append or cross-shard fabric handoff). Use this wherever a numeric must go
    /// to a connection that is NOT the one currently being processed and may live
    /// on another shard.
    fn deliverNumeric(
        self: *LinuxServer,
        id: client_model.ClientId,
        code: Numeric,
        params: []const []const u8,
        trailing: []const u8,
    ) !void {
        const target = self.connFor(id) orelse return;
        if (target.closing) return;
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = try formatNumericLine(&line_buf, target.session.displayName(), code, params, trailing);
        try self.enqueueDelivery(id, line);
    }

    /// Look up the connection behind `id` on its OWNING reactor's slab, whatever
    /// shard that is. Safe for READ-ONLY inspection of the connection's session
    /// (caps, away, umodes, display name): every such field is mutated only while
    /// holding `world.lockWrite`, which brackets the whole completion, so a read
    /// here is serialized against that connection's own command processing. NEVER
    /// write to a returned foreign connection's send buffer or arm its ring — that
    /// is its reactor's job; route bytes there through `enqueueDelivery`.
    pub fn connFor(self: *LinuxServer, id: client_model.ClientId) ?*ConnState {
        if (id.shard >= self.reactors.len) return null;
        return self.reactors[id.shard].clients.get(id);
    }

    fn slotClientId(reactor: *const Reactor, slot_index: usize, gen: u32) client_model.ClientId {
        return .{ .shard = reactor.shard_id, .slot = @intCast(slot_index), .gen = gen };
    }

    const max_delivery_prefix_bytes: usize = 256;
    const max_prefixed_delivery_bytes: usize = default_reply_bytes + max_delivery_prefix_bytes;

    /// Submit one logical IRC line as one delivery record. Prefix and body are
    /// never admitted separately: a full SendQ/fabric therefore cannot retain a
    /// syntactically valid-looking `@tag ` prefix after rejecting its body.
    fn deliverPrefixed(
        self: *LinuxServer,
        id: client_model.ClientId,
        prefix: []const u8,
        bytes: []const u8,
    ) !void {
        if (prefix.len > max_delivery_prefix_bytes or bytes.len > default_reply_bytes)
            return error.OutputTooSmall;
        const total = std.math.add(usize, prefix.len, bytes.len) catch return error.OutputTooSmall;
        if (total > max_prefixed_delivery_bytes) return error.OutputTooSmall;

        var joined: [max_prefixed_delivery_bytes]u8 = undefined;
        @memcpy(joined[0..prefix.len], prefix);
        @memcpy(joined[prefix.len..total], bytes);
        // Preserve the delivery helpers' historical caller contract: once the
        // initial exact-generation lookup succeeded, recipient loss/congestion
        // is isolated to that recipient. The enqueue seam publishes poison when
        // needed; it must not fault an unrelated direct-message sender.
        _ = self.enqueueDeliveryMaybeClose(id, joined[0..total], false, "Client quit");
    }

    /// Deliver `bytes` (a complete `:prefix ...` line), prepending the IRCv3
    /// server-time `tag` for recipients that negotiated the server-time cap.
    /// `tag` is precomputed once per event so all recipients share a timestamp.
    fn deliverTimed(self: *LinuxServer, id: client_model.ClientId, tag: []const u8, bytes: []const u8) !void {
        const conn = self.connFor(id) orelse return error.ClientNotFound;
        if (conn.closing) return;
        // Cap inspection is a serialized read of the owning reactor's session;
        // the complete logical line then crosses the delivery seam exactly once.
        const prefix = if (tag.len != 0 and conn.session.hasCap(.server_time)) tag else "";
        try self.deliverPrefixed(id, prefix, bytes);
    }

    /// Per-event message tags available to attach (server-time value WITHOUT the
    /// `@time=` already formatted, and the sender's account if logged in). The
    /// actual `@k=v;k=v ` segment is assembled PER RECIPIENT from the caps they
    /// negotiated, so a client gets exactly the tags it asked for in one segment.
    const MsgTags = struct {
        time_value: []const u8, // ISO-8601, e.g. "2026-06-04T..Z" (no key)
        account: ?[]const u8, // sender's account, or null when not logged in
        /// Sender's raw IRCv3 tag segment (no leading '@'); only its client-only
        /// (`+...`) tags are relayed, to recipients negotiating message-tags.
        client_tags: ?[]const u8 = null,
        /// Server-minted `msgid` value (no `msgid=` key), shared by every
        /// recipient of this message. Null for events that carry no msgid.
        msgid: ?[]const u8 = null,
        /// Sender has user mode +B. Emitted as IRCv3 valueless `bot` server tag
        /// only to recipients that negotiated message-tags.
        is_bot: bool = false,
    };

    /// Render one complete attachment-specific plaintext IRC record after the
    /// recipient's negotiated tag capabilities have been applied. The returned
    /// bytes are the durable spool payload: TLS and WebSocket framing remain
    /// connection transport state and are applied only when the owner drains it.
    fn renderTaggedRecord(
        self: *LinuxServer,
        id: client_model.ClientId,
        tags: MsgTags,
        bytes: []const u8,
        out: []u8,
    ) ![]const u8 {
        const conn = self.connFor(id) orelse return error.ClientNotFound;
        if (conn.closing) return error.ClientNotFound;
        if (bytes.len > default_reply_bytes) return error.OutputTooSmall;
        var tagbuf: [max_delivery_prefix_bytes]u8 = undefined;
        const prefix = buildTagPrefix(&conn.session, tags, &tagbuf);
        const total = std.math.add(usize, prefix.len, bytes.len) catch return error.OutputTooSmall;
        if (total > out.len or total > max_prefixed_delivery_bytes) return error.OutputTooSmall;
        @memcpy(out[0..prefix.len], prefix);
        @memcpy(out[prefix.len..total], bytes);
        return out[0..total];
    }

    /// Only rows with a real reusable credential belong in the durable spool.
    /// Anonymous/untracked sockets retain the ordinary best-effort delivery
    /// contract and cannot strand an orphan record after they disappear.
    fn attachmentHasReusableSession(self: *LinuxServer, id: client_model.ClientId) bool {
        const conn = self.connFor(id) orelse return false;
        const account = conn.session.account() orelse return false;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return false;
        return !tokenIsNull(handle.token);
    }

    fn attachmentEventId(msgid: []const u8) attachment_delivery_spool.EventId {
        var digest: [std.crypto.hash.Blake3.digest_length]u8 = undefined;
        var hasher = std.crypto.hash.Blake3.init(.{});
        hasher.update("onyx-attachment-delivery-v1\x00");
        hasher.update(msgid);
        hasher.final(&digest);
        return digest[0..@sizeOf(attachment_delivery_spool.EventId)].*;
    }

    fn e2eeGroupAttachmentEventId(
        relay_id: e2ee_group_relay.RelayId,
    ) attachment_delivery_spool.EventId {
        var digest: [std.crypto.hash.Blake3.digest_length]u8 = undefined;
        var hasher = std.crypto.hash.Blake3.init(.{});
        hasher.update("onyx-attachment-e2ee-group-v1\x00");
        hasher.update(&relay_id);
        hasher.final(&digest);
        return digest[0..@sizeOf(attachment_delivery_spool.EventId)].*;
    }

    /// Reserve one already-rendered physical attachment record. This is the
    /// compatibility entry point used by local event paths; MESSAGE_V2 admission
    /// prepares the complete recipient batch inside its authority transaction.
    fn reserveTaggedAttachmentDelivery(
        self: *LinuxServer,
        id: client_model.ClientId,
        tags: MsgTags,
        bytes: []const u8,
    ) !void {
        const msgid = tags.msgid orelse return error.InvalidRecord;
        var rendered_buf: [max_prefixed_delivery_bytes]u8 = undefined;
        const rendered = try self.renderTaggedRecord(id, tags, bytes, &rendered_buf);
        const record = attachment_delivery_spool.BatchRecord{
            .client = monitorIdFromClient(id),
            .event_id = attachmentEventId(msgid),
            .bytes = rendered,
        };
        lockSpin(&self.attachment_delivery_mu);
        const reserved = self.attachment_delivery_spool.reserveBatch(&.{record});
        self.attachment_delivery_mu.unlock();
        _ = try reserved;
        self.wakeShard(id.shard);
        if (id.shard == self.rx().shard_id) self.drainAttachmentSpoolForCurrentReactor();
    }

    /// Owner-only SendQ drain for durable attachment records. SendQ pressure is
    /// not a connection fault: the head stays in the spool and a later send/timer
    /// turn retries it. A record retires only after the exact plaintext bytes
    /// entered that physical connection's SendQ.
    fn drainAttachmentSpoolForCurrentReactor(self: *LinuxServer) void {
        lockSpin(&self.attachment_delivery_mu);
        defer self.attachment_delivery_mu.unlock();
        var pending_buf: [64]attachment_delivery_spool.PendingRecord = undefined;
        const pending = self.attachment_delivery_spool.collectPending(&pending_buf);
        for (pending) |record| {
            const id = clientIdFromMonitor(record.client);
            if (id.shard != self.rx().shard_id) continue;
            const conn = self.rx().clients.get(id) orelse continue;
            if (conn.closing) continue;
            appendToConn(conn, record.bytes) catch continue;
            if (!self.attachment_delivery_spool.commitHeadToSendq(
                record.client,
                record.sequence,
                record.event_id,
            )) continue;
            self.armSendIfNeeded(conn) catch {
                self.poisonOwnedDelivery(conn);
            };
        }
    }

    fn transferAttachmentDeliveries(
        self: *LinuxServer,
        old_client: sessions_mod.ClientId,
        new_client: sessions_mod.ClientId,
    ) attachment_delivery_spool.TransferError!void {
        lockSpin(&self.attachment_delivery_mu);
        defer self.attachment_delivery_mu.unlock();
        _ = try self.attachment_delivery_spool.transferAttachment(old_client, new_client);
    }

    const PreparedResumeAttachmentTransfer = struct {
        server: *LinuxServer,
        prepared: attachment_delivery_spool.PreparedAttachmentTransfer,
        locked: bool = true,

        fn commit(self: *PreparedResumeAttachmentTransfer) void {
            _ = self.prepared.commit();
        }

        fn release(self: *PreparedResumeAttachmentTransfer) void {
            if (self.locked) {
                self.server.attachment_delivery_mu.unlock();
                self.locked = false;
            }
        }

        fn deinit(self: *PreparedResumeAttachmentTransfer) void {
            self.prepared.deinit();
            self.release();
            self.* = undefined;
        }
    };

    /// Prepare the delivery half of an exact attachment rebind and retain the
    /// spool mutation lock until the joint SessionStore/World/spool cut has
    /// committed or aborted. The returned ticket is logically non-copyable.
    fn prepareResumeAttachmentTransfer(
        self: *LinuxServer,
        old_client: sessions_mod.ClientId,
        new_client: sessions_mod.ClientId,
    ) attachment_delivery_spool.TransferError!PreparedResumeAttachmentTransfer {
        lockSpin(&self.attachment_delivery_mu);
        errdefer self.attachment_delivery_mu.unlock();
        return .{
            .server = self,
            .prepared = try self.attachment_delivery_spool.prepareAttachmentTransfer(
                old_client,
                new_client,
            ),
        };
    }

    const PreparedAttachmentDeliveryBatch = struct {
        server: *LinuxServer,
        prepared: ?attachment_delivery_spool.PreparedBatch = null,
        locked: bool = false,

        fn commit(self: *PreparedAttachmentDeliveryBatch) void {
            if (self.prepared) |*prepared| _ = prepared.commit();
        }

        fn release(self: *PreparedAttachmentDeliveryBatch) void {
            if (self.prepared) |*prepared| prepared.deinit();
            self.prepared = null;
            if (self.locked) {
                self.server.attachment_delivery_mu.unlock();
                self.locked = false;
            }
        }

        fn deinit(self: *PreparedAttachmentDeliveryBatch) void {
            self.release();
            self.* = undefined;
        }
    };

    /// Finish every allocation for a complete recipient set and retain the spool
    /// mutation lock through MESSAGE_V2's RVG2/Lotus/outbox publication. This
    /// makes `PreparedBatch.commit` one member of the joint no-fail cut rather
    /// than a best-effort consequence after mesh acceptance.
    fn prepareAttachmentDeliveryBatch(
        self: *LinuxServer,
        recipients: []const client_model.ClientId,
        tags: MsgTags,
        bytes: []const u8,
    ) !PreparedAttachmentDeliveryBatch {
        const msgid = tags.msgid orelse return .{ .server = self };
        var owned: std.ArrayList([]u8) = .empty;
        defer {
            for (owned.items) |record| self.allocator.free(record);
            owned.deinit(self.allocator);
        }
        var records: std.ArrayList(attachment_delivery_spool.BatchRecord) = .empty;
        defer records.deinit(self.allocator);
        for (recipients) |id| {
            if (!self.attachmentHasReusableSession(id)) continue;
            var rendered_buf: [max_prefixed_delivery_bytes]u8 = undefined;
            const rendered = try self.renderTaggedRecord(id, tags, bytes, &rendered_buf);
            const copy = try self.allocator.dupe(u8, rendered);
            owned.append(self.allocator, copy) catch |err| {
                self.allocator.free(copy);
                return err;
            };
            try records.append(self.allocator, .{
                .client = monitorIdFromClient(id),
                .event_id = attachmentEventId(msgid),
                .bytes = copy,
            });
        }
        if (records.items.len == 0) return .{ .server = self };

        lockSpin(&self.attachment_delivery_mu);
        errdefer self.attachment_delivery_mu.unlock();
        return .{
            .server = self,
            .prepared = try self.attachment_delivery_spool.prepareBatch(records.items),
            .locked = true,
        };
    }

    /// Reserve the exact opaque E2EEGROUP line for every event-time physical
    /// recipient. Unlike ordinary chat, no capable recipient may silently fall
    /// back to best-effort SendQ delivery: an upstream ACK is permitted only
    /// after the complete batch is retained.
    ///
    /// ADS1's Helix relation maps physical client ids through HSSN. Normal
    /// recipient collection therefore excludes anonymous/untracked sockets as
    /// ineligible before this point. If an eligible attachment loses that
    /// authority between collection and preparation, refuse the whole admission
    /// retryably before ACK instead of stranding an unadoptable record.
    fn prepareE2eeGroupAttachmentDeliveryBatch(
        self: *LinuxServer,
        recipients: []const client_model.ClientId,
        relay_id: e2ee_group_relay.RelayId,
        line: []const u8,
    ) !PreparedAttachmentDeliveryBatch {
        var records: std.ArrayList(attachment_delivery_spool.BatchRecord) = .empty;
        defer records.deinit(self.allocator);
        try records.ensureTotalCapacity(self.allocator, recipients.len);
        const event_id = e2eeGroupAttachmentEventId(relay_id);
        for (recipients) |id| {
            if (!self.attachmentHasReusableSession(id))
                return error.UntrackedAttachment;
            records.appendAssumeCapacity(.{
                .client = monitorIdFromClient(id),
                .event_id = event_id,
                .bytes = line,
            });
        }
        if (records.items.len == 0) return .{ .server = self };

        // Lock order is attachment_delivery_mu -> e2ee_group_mesh_mu. Retain
        // this lane through the authority admit and the joint no-fail cut.
        lockSpin(&self.attachment_delivery_mu);
        errdefer self.attachment_delivery_mu.unlock();
        return .{
            .server = self,
            .prepared = try self.attachment_delivery_spool.prepareBatch(records.items),
            .locked = true,
        };
    }

    /// The joint cut is already live. Wake every owning shard, then drain the
    /// caller's shard synchronously. SendQ pressure leaves the exact ADS1 head
    /// retained; it is not a connection poison and never triggers a lossy
    /// fallback through the cross-shard fabric.
    fn driveE2eeGroupAttachmentDeliveries(
        self: *LinuxServer,
        recipients: []const client_model.ClientId,
    ) void {
        for (recipients) |id| self.wakeShard(id.shard);
        self.drainAttachmentSpoolForCurrentReactor();
    }

    fn appendUniqueDeliveryId(
        self: *LinuxServer,
        out: *std.ArrayList(client_model.ClientId),
        id: client_model.ClientId,
    ) std.mem.Allocator.Error!void {
        for (out.items) |existing| if (existing.eql(id)) return;
        try out.append(self.allocator, id);
    }

    fn deliveryVisibleForClientTags(
        self: *LinuxServer,
        id: client_model.ClientId,
        client_tags: ?[]const u8,
    ) bool {
        const tags = client_tags orelse return true;
        const conn = self.connFor(id) orelse return false;
        var visible: [irc_line.max_client_tags_raw_len]u8 = undefined;
        return clientTagsForSession(&conn.session, tags, &visible).len != 0;
    }

    fn collectChannelDeliveryIds(
        self: *LinuxServer,
        channel: []const u8,
        min_rank: u8,
        excluded: ?client_model.ClientId,
        visible_client_tags: ?[]const u8,
        out: *std.ArrayList(client_model.ClientId),
    ) std.mem.Allocator.Error!void {
        var members = self.world.memberIterator(channel) orelse return;
        while (members.next()) |member| {
            if (min_rank != 0) {
                const modes = self.world.memberModes(channel, member.*) orelse continue;
                if (modes.rank() < min_rank) continue;
            }
            const id = clientIdFromWorld(member.*);
            if (excluded) |skip| if (id.eql(skip)) continue;
            if (!self.deliveryVisibleForClientTags(id, visible_client_tags)) continue;
            try self.appendUniqueDeliveryId(out, id);
        }
    }

    fn collectDirectDeliveryIds(
        self: *LinuxServer,
        recipients: []const client_model.ClientId,
        sender_attachments: []const client_model.ClientId,
        sender: client_model.ClientId,
        echo_sender: bool,
        visible_client_tags: ?[]const u8,
        out: *std.ArrayList(client_model.ClientId),
    ) std.mem.Allocator.Error!void {
        for (recipients) |id| {
            if (!self.deliveryVisibleForClientTags(id, visible_client_tags)) continue;
            try self.appendUniqueDeliveryId(out, id);
        }
        for (sender_attachments) |id| {
            if (id.eql(sender) and !echo_sender) continue;
            if (!self.deliveryVisibleForClientTags(id, visible_client_tags)) continue;
            try self.appendUniqueDeliveryId(out, id);
        }
    }

    /// Deliver `bytes` with an IRCv3 message-tag segment assembled for THIS
    /// recipient: `@time=…;account=… ` including only the tags whose caps the
    /// recipient negotiated. Used by the PRIVMSG/NOTICE/TAGMSG paths.
    const TaggedDeliveryMode = enum {
        ordinary,
        prepared_batch,
        /// Durable MESSAGE_V2/ADS1 reservation was not obtained for this event
        /// (spool pressure, journal busy, or admit soft-fail). Deliver via the
        /// ordinary SendQ path so local chat is not bricked; no ADS1 retention.
        mesh_busy_local,
    };

    fn deliverTaggedMode(
        self: *LinuxServer,
        id: client_model.ClientId,
        tags: MsgTags,
        bytes: []const u8,
        mode: TaggedDeliveryMode,
    ) !void {
        const conn = self.connFor(id) orelse return error.ClientNotFound;
        if (conn.closing) return;
        if (tags.msgid != null and self.attachmentHasReusableSession(id)) {
            switch (mode) {
                .prepared_batch => {
                    // The complete reusable-recipient set was reserved atomically
                    // with MESSAGE_V2 authority. Ordinary fanout is now only the
                    // transport trigger: reserving again after another attachment
                    // drained the shared batch would recreate the retired event.
                    self.wakeShard(id.shard);
                    if (id.shard == self.rx().shard_id) self.drainAttachmentSpoolForCurrentReactor();
                    return;
                },
                .ordinary => {
                    // Prefer ADS1 for multi-device resume. Spool pressure must
                    // not drop a message that already admitted to RVG2/Lotus —
                    // fall through to immediate SendQ (post-admit delivery,
                    // not a mesh-authority skip).
                    if (self.reserveTaggedAttachmentDelivery(id, tags, bytes)) |_| {
                        return;
                    } else |_| {}
                },
                .mesh_busy_local => {
                    // Explicit mesh-busy / admit-miss fanout: skip ADS1 and
                    // deliver via SendQ so local members still see the line.
                },
            }
        }
        // Sized for the full @-segment: server-time + account + msgid + relayed
        // client-only tags. Built from a serialized read of the owning reactor's
        // negotiated caps; the bytes then route to that reactor via enqueueDelivery.
        var tagbuf: [256]u8 = undefined;
        const prefix = buildTagPrefix(&conn.session, tags, &tagbuf);
        try self.deliverPrefixed(id, prefix, bytes);
    }

    fn deliverTagged(self: *LinuxServer, id: client_model.ClientId, tags: MsgTags, bytes: []const u8) !void {
        return self.deliverTaggedMode(id, tags, bytes, .ordinary);
    }

    fn deliverPreparedTagged(self: *LinuxServer, id: client_model.ClientId, tags: MsgTags, bytes: []const u8) !void {
        return self.deliverTaggedMode(id, tags, bytes, .prepared_batch);
    }

    /// Mirror one already-rendered direct PRIVMSG/NOTICE line to the other
    /// attached local sessions of `account` that explicitly opted in. This helper
    /// is called only from the user-target DM path, never from mirrored delivery,
    /// so sibling copies cannot recursively fan out.
    fn deliverSessionSyncSiblings(
        self: *LinuxServer,
        account: []const u8,
        excluded_token: ?sessions_mod.Token,
        tags: MsgTags,
        bytes: []const u8,
        skip_a: client_model.ClientId,
        skip_b: ?client_model.ClientId,
    ) void {
        self.deliverSessionSyncSiblingsNick(account, excluded_token, null, tags, bytes, skip_a, skip_b, null, null);
    }

    /// Optionally mirror to an account's OTHER named sessions. Exact-token
    /// attachments use mandatory delivery before this helper. Excluded nicks are
    /// authority boundaries: another token rendering the addressed/source nick
    /// is independent and cannot opt into that event through account affinity.
    fn deliverSessionSyncSiblingsNick(
        self: *LinuxServer,
        account: []const u8,
        excluded_token_a: ?sessions_mod.Token,
        excluded_token_b: ?sessions_mod.Token,
        tags: MsgTags,
        bytes: []const u8,
        skip_a: ?client_model.ClientId,
        skip_b: ?client_model.ClientId,
        excluded_nick_a: ?[]const u8,
        excluded_nick_b: ?[]const u8,
    ) void {
        const skip_a_flat = if (skip_a) |id| monitorIdFromClient(id) else null;
        const skip_b_flat = if (skip_b) |id| monitorIdFromClient(id) else null;
        const account_sessions = self.sessions.copySessionsAlloc(self.allocator, account) catch return;
        defer self.allocator.free(account_sessions);
        for (account_sessions) |s| {
            if (excluded_token_a) |token| {
                if (std.crypto.timing_safe.eql(sessions_mod.Token, s.token, token)) continue;
            }
            if (excluded_token_b) |token| {
                if (std.crypto.timing_safe.eql(sessions_mod.Token, s.token, token)) continue;
            }
            const sibling_id = clientIdFromMonitor(s.client);
            const sibling = self.connFor(sibling_id) orelse continue;
            // Defense in depth: only mirror to a sibling STILL authenticated to
            // this account. A stale SessionStore entry (e.g. left behind by an
            // account switch) must never leak this account's DMs to a connection
            // no longer logged into it.
            const cur = sibling.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(cur, account)) continue;
            // Same rendered nick with a DIFFERENT token is an independent
            // authority domain, never an account-sync alias. Exact-token peers
            // were already delivered through the mandatory path above.
            if (excluded_nick_a) |n| {
                if (std.ascii.eqlIgnoreCase(sibling.session.displayName(), n)) continue;
            }
            if (excluded_nick_b) |n| {
                if (std.ascii.eqlIgnoreCase(sibling.session.displayName(), n)) continue;
            }
            if (!allowsSessionSyncSibling(s, sibling, skip_a_flat, skip_b_flat)) continue;
            self.deliverTagged(sibling_id, tags, bytes) catch continue;
        }
    }

    fn broadcastChannelTagged(
        self: *LinuxServer,
        channel: []const u8,
        tags: MsgTags,
        bytes: []const u8,
        except: ?client_model.ClientId,
        mode: TaggedDeliveryMode,
    ) !void {
        var members = self.world.memberIterator(channel) orelse return error.NoSuchChannel;
        // Coalesce per-recipient cross-shard wakes into one wake per touched shard.
        self.beginWakeBatch();
        defer self.endWakeBatch();
        while (members.next()) |member| {
            const mid = clientIdFromWorld(member.*);
            if (except) |skip| {
                if (mid.eql(skip)) continue;
            }
            self.deliverTaggedMode(mid, tags, bytes, mode) catch continue;
        }
    }

    fn broadcastChannel(
        self: *LinuxServer,
        channel: []const u8,
        bytes: []const u8,
        except: ?client_model.ClientId,
    ) !void {
        var tag_buf: [48]u8 = undefined;
        const tag = serverTimeTag(&tag_buf);
        var members = self.world.memberIterator(channel) orelse return error.NoSuchChannel;
        self.beginWakeBatch();
        defer self.endWakeBatch();
        while (members.next()) |member| {
            const id = clientIdFromWorld(member.*);
            if (except) |skip| {
                if (id.eql(skip)) continue;
            }
            self.deliverTimed(id, tag, bytes) catch continue;
        }
    }

    fn broadcastChannelCap(
        self: *LinuxServer,
        channel: []const u8,
        bytes: []const u8,
        cap: dispatch.CapId,
        except: ?client_model.ClientId,
    ) !void {
        var tag_buf: [48]u8 = undefined;
        const tag = serverTimeTag(&tag_buf);
        var members = self.world.memberIterator(channel) orelse return error.NoSuchChannel;
        self.beginWakeBatch();
        defer self.endWakeBatch();
        while (members.next()) |member| {
            const id = clientIdFromWorld(member.*);
            if (except) |skip| {
                if (id.eql(skip)) continue;
            }
            const mconn = self.connFor(id) orelse continue;
            if (!mconn.session.hasCap(cap)) continue;
            self.deliverTimed(id, tag, bytes) catch continue;
        }
    }

    fn broadcastChannelTaggedCap(
        self: *LinuxServer,
        channel: []const u8,
        tags: MsgTags,
        bytes: []const u8,
        cap: dispatch.CapId,
        except: ?client_model.ClientId,
    ) !void {
        var members = self.world.memberIterator(channel) orelse return error.NoSuchChannel;
        self.beginWakeBatch();
        defer self.endWakeBatch();
        while (members.next()) |member| {
            const id = clientIdFromWorld(member.*);
            if (except) |skip| {
                if (id.eql(skip)) continue;
            }
            const mconn = self.connFor(id) orelse continue;
            if (!mconn.session.hasCap(cap)) continue;
            self.deliverTagged(id, tags, bytes) catch continue;
        }
    }

    /// Like broadcastChannelTagged but only to members whose status rank is >=
    /// min_rank (STATUSMSG: `@#chan`, `+#chan`, ...).
    fn broadcastChannelMinRank(
        self: *LinuxServer,
        channel: []const u8,
        tags: MsgTags,
        bytes: []const u8,
        except: ?client_model.ClientId,
        min_rank: u8,
        mode: TaggedDeliveryMode,
    ) !void {
        var members = self.world.memberIterator(channel) orelse return error.NoSuchChannel;
        self.beginWakeBatch();
        defer self.endWakeBatch();
        while (members.next()) |member| {
            const mm = self.world.memberModes(channel, member.*) orelse continue;
            if (mm.rank() < min_rank) continue;
            const id = clientIdFromWorld(member.*);
            if (except) |skip| {
                if (id.eql(skip)) continue;
            }
            self.deliverTaggedMode(id, tags, bytes, mode) catch continue;
        }
    }

    /// Forward a cross-node user message to every established S2S peer except
    /// `skip`. Loop-guarded per-peer by (origin_node, hlc). Best-effort: a full
    /// link buffer never faults the local delivery that triggered it.
    /// Which peers a relayed message should go to, narrowed via route_table so we
    /// don't broadcast every message to the whole mesh.
    const RelayScope = union(enum) {
        all,
        channel: []const u8, // only peers that announced members of this channel
        nick: []const u8, // only the peer whose route_table owns this nick
        /// A locally-held nick whose reusable logical session was replicated to
        /// authenticated mesh peers. Route-table ownership remains the ordinary
        /// path; the exact token -> peer binding is the narrow fallback when F1
        /// correctly UID-disambiguates a remote attachment that has no residence
        /// proof of its own.
        session_nick: struct {
            nick: []const u8,
            token: session_migrate.Token,
            also_token: ?session_migrate.Token = null,
        },
    };

    /// Forward a relayed message to the peers selected by `scope`. Returns the
    /// number of peer links it was sent to (so callers can fall back to a wider
    /// scope when a targeted route is not yet known).
    fn relayToPeers(self: *LinuxServer, msg: s2s_link.RelayMessage, scope: RelayScope) usize {
        return self.relayLegacyToPeers(msg, scope, false);
    }

    /// Legacy compatibility flood. Once the origin has durably admitted the
    /// logical event as MESSAGE_V2, that event is V2-only on every edge. An old
    /// peer stays connected but receives the exact retained RVL2 wire only after
    /// it negotiates V2; sending a legacy twin now would deliver it a second time
    /// when the retained object replays after upgrade. Genuine legacy-only
    /// events continue through this path unchanged.
    fn relayLegacyToPeers(
        self: *LinuxServer,
        msg: s2s_link.RelayMessage,
        scope: RelayScope,
        v2_admitted: bool,
    ) usize {
        if (v2_admitted) return 0;
        var sent: usize = 0;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    if (!relayWanted(link, scope) and !self.relayWantedBySessionReplica(link, scope)) continue;
                    link.sendMessage(msg) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                    sent += 1;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    if (!relayWanted(link, scope)) continue;
                    link.sendMessage(msg) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                    sent += 1;
                }
            }
        }
        return sent;
    }

    fn hasSecureRelayV2Peer(self: *LinuxServer) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                if (slot.value.s2s_secured) |link| {
                    if (link.established() and link.supportsSecureRelayV2()) return true;
                }
            }
        }
        return false;
    }

    /// Per-link scope test (duck-typed over S2sLink / SecuredLink — both expose
    /// channelMembers + routeNickNode).
    fn relayWanted(link: anytype, scope: RelayScope) bool {
        return switch (scope) {
            .all => true,
            .channel => |ch| link.channelMembers(ch).len > 0,
            .nick => |nk| link.bestNickClaim(nk) != null,
            .session_nick => |target| link.bestNickClaim(target.nick) != null,
        };
    }

    /// Session-aware nick routing is permitted only on an authenticated secured
    /// link to the exact peer that was successfully offered this token's signed
    /// migration capsule. The binding is recorded by `broadcastSessionMigration`
    /// or retained-Store legacy replay; no wire-controlled account or nick can
    /// create it.
    /// Keeping this separate from `relayWanted` ensures plaintext peers can never
    /// qualify through a portable-session route.
    fn relayWantedBySessionReplica(self: *LinuxServer, link: *secured_s2s_link.SecuredLink, scope: RelayScope) bool {
        const target = switch (scope) {
            .session_nick => |value| value,
            else => return false,
        };
        const peer = link.peerShortId() orelse return false;
        if (self.session_replica_routes.contains(.{ .token = target.token, .peer = peer })) return true;
        if (target.also_token) |token| {
            return self.session_replica_routes.contains(.{ .token = token, .peer = peer });
        }
        return false;
    }

    fn relayDirectMessagePolicyBlocks(
        self: *LinuxServer,
        msg: s2s_link.RelayMessage,
        sender_account: []const u8,
        recipient_id: client_model.ClientId,
    ) bool {
        if (self.connFor(recipient_id)) |rconn| {
            if (sender_account.len == 0 and rconn.session.umodes.contains(.regonly_pm)) return true;
            if (msg.verb == .privmsg and rconn.session.umodes.contains(.no_ctcp) and isBlockableCtcp(msg.text)) return true;
            if (rconn.session.umodes.contains(.callerid)) {
                const self_msg = std.ascii.eqlIgnoreCase(msg.source_nick, msg.target);
                const accepted = self.accepts.contains(msg.target, msg.source_nick) catch false;
                const same_account = if (sender_account.len != 0)
                    if (rconn.session.account()) |ra| std.ascii.eqlIgnoreCase(sender_account, ra) else false
                else
                    false;
                if (!self_msg and !accepted and !same_account) return true;
            }
        }
        if (self.silence.isSilenced(msg.target, msg.source_prefix)) return true;
        return false;
    }

    /// True if any S2S peer link (secured or plaintext) is established — used to
    /// decide whether an unknown-local nick might be reachable across the mesh.
    fn hasEstablishedPeer(self: *LinuxServer) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                if (slot.value.s2s_secured) |l| {
                    if (l.established()) return true;
                } else if (slot.value.s2s) |l| {
                    if (l.established()) return true;
                }
            }
        }
        return false;
    }

    const RelayOriginAuth = enum { unsigned, verified };

    /// Whether `origin_node` is represented by an established one-hop roster on
    /// this node. Direct peers must remain subject to receiver-side +n checks:
    /// their link roster can prove whether the signed sender is actually joined.
    /// A non-direct origin has no such one-hop roster here; its verified origin
    /// signature is therefore the only end-to-end attestation that the origin
    /// performed its own membership gate.
    fn relayOriginIsDirectPeer(self: *LinuxServer, origin_node: u64) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                if (slot.value.s2s_secured) |link| {
                    if (link.established() and link.remoteNodeId() == origin_node) return true;
                } else if (slot.value.s2s) |link| {
                    if (link.established() and link.remoteNodeId() == origin_node) return true;
                }
            }
        }
        return false;
    }

    /// A verified, non-direct origin may attest only the membership portion of
    /// receiver-side channel policy. Keeping this decision separate from the
    /// speech gate makes the trust boundary explicit: unsigned relays and signed
    /// direct peers never receive the exception.
    fn relayOriginAttestsExternalMembership(auth: RelayOriginAuth, origin_is_direct: bool) bool {
        return auth == .verified and !origin_is_direct;
    }

    /// Verify the self-contained origin signature of an inbound relayed message.
    /// Legacy unsigned messages remain eligible for ordinary target delivery,
    /// but the distinct return value ensures they can never consume account/nick
    /// trust for reusable-session coexistence or sender-copy fan-out.
    fn relayOriginAuth(self: *LinuxServer, msg: s2s_link.RelayMessage) ?RelayOriginAuth {
        const outcome = message_relay.verifyOrigin(self.allocator, msg) catch {
            // Allocation failure verifying: fail CLOSED (drop) rather than deliver
            // an unverified message. Counted as a rejection for audit visibility.
            self.recordRelaySignatureReject(msg, "verification allocation failed");
            return null;
        };
        return switch (outcome) {
            .unsigned => .unsigned,
            .verified => .verified,
            .origin_mismatch => blk: {
                self.recordRelaySignatureReject(msg, "origin pubkey does not self-certify the claimed origin node");
                break :blk null;
            },
            .bad_signature => blk: {
                self.recordRelaySignatureReject(msg, "origin signature verification failed");
                break :blk null;
            },
        };
    }

    /// Account + audit a dropped relayed message whose origin signature failed.
    /// Bumps the daemon-level reject counter and emits the same `.s2s` warn audit
    /// signal that direct-owned frame origin rejections use (`drainOriginRejections`).
    fn recordRelaySignatureReject(self: *LinuxServer, msg: s2s_link.RelayMessage, reason: []const u8) void {
        self.rejected_relay_signatures +|= 1;
        var buf: [256]u8 = undefined;
        const line = std.fmt.bufPrint(
            &buf,
            "dropped relayed {s} claiming origin {d}: {s}",
            .{ msg.verb.commandWord(), msg.origin_node, reason },
        ) catch "dropped relayed message with bad origin signature";
        self.traceLog(.warn, .s2s, line);
    }

    /// Resolve which mesh node a nick is homed on from every established link's
    /// roster-backed best claim. Folding the strict `(hlc,node)` total order makes
    /// the result independent of reactor/slot/link insertion order and handles
    /// case variants even when the exact-key route index missed an update.
    fn meshNickHomeNode(self: *LinuxServer, nick: []const u8) ?s2s_link.NodeId {
        var best: ?s2s_link.NickClaim = null;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    if (link.bestNickClaim(nick)) |claim| mergeMeshNickClaim(&best, claim);
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    if (link.bestNickClaim(nick)) |claim| mergeMeshNickClaim(&best, claim);
                }
            }
        }
        return if (best) |claim| claim.node_id else null;
    }

    const RelaySenderHome = union(enum) {
        unknown,
        match,
        mismatch: u64,
    };

    /// Inbound sender-identity binding: classify whether the relayed message's
    /// sender nick is homed on a mesh node this receiver KNOWS, and if known
    /// whether that home matches the frame's claimed `origin_node`.
    /// `source_prefix` IS covered by relay-v1's signed
    /// transcript; the separately encoded `source_nick` is not, so deliverRelay
    /// ignores it and re-derives the nick from that signed prefix. A keyed origin
    /// can still deliberately sign a prefix for a nick it does not own: the
    /// signature proves which node authored the claim, not nick residence. The
    /// receiver's route table homes that user elsewhere,
    /// so the claim is rejected here. Deliberately account-INDEPENDENT: `account` is
    /// origin-controlled/unsigned and must never wave a mismatched sender through.
    fn relaySenderHome(self: *LinuxServer, source_nick: []const u8, origin_node: u64) RelaySenderHome {
        const home = self.meshNickHomeNode(source_nick) orelse return .unknown;
        if (home == origin_node) return .match;
        return .{ .mismatch = home };
    }

    /// Resolve the residence-trusted account for `nick` at one exact mesh node.
    /// Remote roster rows may keep a display account without residence trust;
    /// only `account_trusted` origin-matching rows are eligible here. If
    /// independently converged links disagree, fail closed instead of choosing
    /// an account and exposing another conversation's `$dm:acct` history.
    fn trustedRemoteAccountAtNode(self: *LinuxServer, nick: []const u8, node: u64) ?[]const u8 {
        var found: ?[]const u8 = null;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const member = if (slot.value.s2s_secured) |link| blk: {
                    if (!link.established()) continue;
                    break :blk link.findRemoteMember(nick);
                } else if (slot.value.s2s) |link| blk: {
                    if (!link.established()) continue;
                    break :blk link.findRemoteMember(nick);
                } else continue;
                const remote = member orelse continue;
                if (remote.node != node or !remote.account_trusted or remote.account.len == 0) continue;
                if (found) |account| {
                    if (!std.ascii.eqlIgnoreCase(account, remote.account)) return null;
                } else {
                    found = remote.account;
                }
            }
        }
        return found;
    }

    fn trustedRemoteAccountForNick(self: *LinuxServer, nick: []const u8) ?[]const u8 {
        const home = self.meshNickHomeNode(nick) orelse return null;
        return self.trustedRemoteAccountAtNode(nick, home);
    }

    const ReplicatedSessionProof = struct {
        trusted_account: []const u8,
        token: sessions_mod.Token,
        modes: world_model.MemberModes,
    };

    fn proofFromSessionReplicaEntry(
        self: *LinuxServer,
        entry: *const session_replica_v2.Store.Entry,
        token: sessions_mod.Token,
        account: []const u8,
        nick: []const u8,
        channel: ?[]const u8,
        now_wall: i64,
    ) ?ReplicatedSessionProof {
        if (now_wall > entry.expires_at_ms or
            !std.ascii.eqlIgnoreCase(entry.account, account) or
            !std.ascii.eqlIgnoreCase(entry.nick, nick)) return null;
        var origin_snapshot = migration_relay.Snapshot.decode(self.allocator, entry.snapshot) catch return null;
        defer origin_snapshot.deinit(self.allocator);
        if (!std.ascii.eqlIgnoreCase(origin_snapshot.account, entry.account) or
            !std.ascii.eqlIgnoreCase(origin_snapshot.nick, entry.nick)) return null;
        var modes = world_model.MemberModes.empty();
        if (channel) |wanted| {
            var found_channel = false;
            for (origin_snapshot.channels, 0..) |carried, i| {
                if (!std.ascii.eqlIgnoreCase(carried, wanted)) continue;
                modes.bits = if (i < origin_snapshot.channel_modes.len) origin_snapshot.channel_modes[i] else 0;
                found_channel = true;
                break;
            }
            if (!found_channel) return null;
        }
        return .{ .trusted_account = entry.account, .token = token, .modes = modes };
    }

    /// Resolve signed portable-session authority without consulting the relay's
    /// mutable account field. The local nick owner supplies the account and exact
    /// portable token candidates; the Store binds each candidate to the verified
    /// origin and signed-prefix nick. Multiple distinct matching tokens are
    /// ambiguous until relay-v2 carries a signed per-message token, so fail closed.
    fn replicatedSessionProof(
        self: *LinuxServer,
        origin_node: u64,
        nick: []const u8,
        channel: ?[]const u8,
    ) ?ReplicatedSessionProof {
        if (nick.len == 0) return null;
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        const wid = self.world.findNick(nick) orelse {
            // After the original local socket detaches there is no World nick
            // owner, but the exact token remains in SessionStore. Select only a
            // unique live signed (origin,nick) fact, then prove that SAME token is
            // a local portable session under the signed account.
            const live = (self.session_replica_store.uniqueLiveOriginNick(origin_node, nick, now_wall) catch return null) orelse return null;
            var account_buf: [session_replica_account_max]u8 = undefined;
            const local = self.sessions.findByTokenInto(live.token, &account_buf) orelse return null;
            if (!std.ascii.eqlIgnoreCase(local.account, live.entry.account)) return null;
            const local_session = self.sessions.findTokenSessionInAccount(local.account, live.token) orelse return null;
            if (!local_session.portable_resume) return null;
            return self.proofFromSessionReplicaEntry(live.entry, live.token, local.account, nick, channel, now_wall);
        };
        const owner_id = clientIdFromWorld(wid);
        const local_conn = self.connFor(owner_id) orelse return null;
        if (local_conn.s2s != null or local_conn.s2s_secured != null) return null;
        const account = local_conn.session.account() orelse return null;
        if (account.len == 0) return null;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(owner_id)) orelse return null;
        if (!handle.portable or tokenIsNull(handle.token)) return null;
        // V2 authority is end-to-end: the relay signature identifies the origin,
        // while the retained signed OFFER must bind that origin to the exact token
        // of the local World nick owner. An unrelated same-account detached token
        // is never a substitute. Routes remain reachability hints only.
        if (self.session_replica_store.getOrigin(handle.token, origin_node)) |entry| {
            if (self.proofFromSessionReplicaEntry(entry, handle.token, account, nick, channel, now_wall)) |proof| return proof;
        }

        // Rolling-old direct-peer fallback remains bound to the same exact owner
        // token and local account; it never scans arbitrary account ghosts.
        if (!self.session_replica_routes.contains(.{ .token = handle.token, .peer = origin_node })) return null;
        var modes = world_model.MemberModes.empty();
        if (channel) |wanted| modes = self.world.memberModes(wanted, wid) orelse return null;
        return .{ .trusted_account = account, .token = handle.token, .modes = modes };
    }

    /// Resolve MESSAGE_V2's signed sender route only through the exact raw
    /// reusable token retained by local session authority. Nick/account affinity
    /// is never a substitute: a sibling logical session with the same visible
    /// identity hashes to a different route and receives no sent-copy authority.
    fn replicatedSessionProofV2(
        self: *LinuxServer,
        msg: message_relay_v2.RelayMessage,
    ) ?ReplicatedSessionProof {
        const signed_route = msg.sender_route_id orelse return null;
        const nick = msg.sourceNick() orelse return null;
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        var account_buf: [session_replica_account_max]u8 = undefined;
        const local = self.localPortableSessionByRoute(signed_route, &account_buf) orelse return null;
        const entry = self.session_replica_store.getOrigin(local.token, msg.origin_node) orelse return null;
        if (!std.ascii.eqlIgnoreCase(local.account, entry.account) or
            !std.ascii.eqlIgnoreCase(nick, entry.nick) or now_wall > entry.expires_at_ms) return null;
        const local_session = self.sessions.findTokenSessionInAccount(local.account, local.token) orelse return null;
        if (!local_session.portable_resume) return null;
        return self.proofFromSessionReplicaEntry(
            entry,
            local.token,
            local.account,
            nick,
            if (msg.scope_kind == .channel or msg.scope_kind == .channel_whisper) msg.target else null,
            now_wall,
        );
    }

    const RelayV2RoutePredicateContext = struct {
        route: message_relay_v2.RouteId,
    };

    fn relayV2TokenMatchesRoute(context: *const anyopaque, token: sessions_mod.Token) bool {
        const wanted: *const RelayV2RoutePredicateContext = @ptrCast(@alignCast(context));
        const derived = message_relay_v2.routeId(token) catch return false;
        return std.crypto.timing_safe.eql(message_relay_v2.RouteId, derived, wanted.route);
    }

    fn localPortableSessionByRoute(
        self: *LinuxServer,
        route: message_relay_v2.RouteId,
        account_out: []u8,
    ) ?sessions_mod.SessionStore.TokenMatch {
        var context = RelayV2RoutePredicateContext{ .route = route };
        return self.sessions.findUniquePortableTokenInto(.{
            .context = &context,
            .matches_fn = relayV2TokenMatchesRoute,
        }, account_out);
    }

    /// Bind a signed MESSAGE_V2 origin to its self-certifying full public key.
    /// Server registries currently contain direct peers only, so requiring a
    /// local name row would make a legitimate A->B->C origin permanently
    /// unknowable at C. The authenticated immediate peer authorizes carriage;
    /// the immutable inner signature binds the third-party origin itself.
    fn relayV2OriginKnown(self: *LinuxServer, msg: message_relay_v2.RelayMessage) bool {
        if (msg.origin_node == self.config.node_id) {
            const identity = self.config.node_identity orelse return false;
            return msg.origin_pubkey.len == message_relay_v2.pubkey_len and
                std.mem.eql(u8, msg.origin_pubkey, &identity.sign_kp.public_key);
        }
        if (msg.origin_pubkey.len != message_relay_v2.pubkey_len) return false;
        return message_relay.originShortId(msg.origin_pubkey[0..message_relay_v2.pubkey_len].*) ==
            msg.origin_node;
    }

    const RelayV2ExactTarget = struct {
        primary: client_model.ClientId,
        account: []const u8,
        token: sessions_mod.Token,
    };

    const RelayV2ExactTargetResolution = union(enum) {
        transit,
        pending,
        ready: RelayV2ExactTarget,
    };

    /// Resolve a signed recipient route to one local logical session and
    /// snapshot every attached transport for that exact raw token. A same nick
    /// or account with another token is intentionally invisible to this path.
    fn collectRelayV2ExactTarget(
        self: *LinuxServer,
        nick: []const u8,
        signed_route: message_relay_v2.RouteId,
        required_channel: ?[]const u8,
        account_out: []u8,
        out: *std.ArrayList(client_model.ClientId),
    ) std.mem.Allocator.Error!RelayV2ExactTargetResolution {
        const match = self.localPortableSessionByRoute(signed_route, account_out) orelse
            return .transit;
        try self.collectAttachedTokenAuthorityClients(match.account, match.token, out);
        var index: usize = 0;
        while (index < out.items.len) {
            const conn = self.connFor(out.items[index]) orelse {
                _ = out.orderedRemove(index);
                continue;
            };
            const wrong_nick = !std.ascii.eqlIgnoreCase(conn.session.displayName(), nick);
            const wrong_channel = if (required_channel) |channel|
                !self.world.isMember(channel, worldIdFromClient(out.items[index]))
            else
                false;
            if (wrong_nick or wrong_channel) {
                _ = out.orderedRemove(index);
            } else {
                index += 1;
            }
        }
        if (out.items.len == 0) return .pending;
        return .{ .ready = .{
            .primary = out.items[0],
            .account = match.account,
            .token = match.token,
        } };
    }

    /// Account + audit a relayed message dropped locally because its sender nick is
    /// homed on a different node than the frame claims. Mirrors
    /// `recordRelaySignatureReject`, on the dedicated home-mismatch counter.
    fn recordRelayHomeMismatch(self: *LinuxServer, msg: s2s_link.RelayMessage, home_node: u64) void {
        self.rejected_relay_home_mismatch +|= 1;
        var buf: [256]u8 = undefined;
        const line = std.fmt.bufPrint(
            &buf,
            "dropped relayed {s} from {s} claiming origin {d}: nick is homed on node {d}",
            .{ msg.verb.commandWord(), msg.source_nick, msg.origin_node, home_node },
        ) catch "dropped relayed message: sender nick homed on a different node";
        self.traceLog(.warn, .s2s, line);
    }

    fn recordRelayUnknownHomeV1(self: *LinuxServer, msg: s2s_link.RelayMessage) void {
        self.rejected_relay_unknown_home_v1 +|= 1;
        var buf: [256]u8 = undefined;
        const line = std.fmt.bufPrint(
            &buf,
            "dropped relayed {s} from {s} claiming origin {d}: sender home unknown and no portable proof",
            .{ msg.verb.commandWord(), msg.source_nick, msg.origin_node },
        ) catch "dropped relayed message: sender home unknown without portable proof";
        self.traceLog(.warn, .s2s, line);
    }

    /// Sign a relay message's canonical origin transcript in place at the ORIGIN
    /// (this node authored it), stamping `origin_pubkey`/`origin_sig` so every hop
    /// can verify it. No-op (legacy unsigned path) when this node has no node
    /// identity, OR when `config.node_id` is not the self-certified short id of
    /// the node key — signing then would mint a signature that fails its own
    /// origin check, so we deliberately leave the message unsigned instead.
    /// `pubkey_buf`/`sig_buf` back the stamped slices and MUST outlive the
    /// `relayToPeers` send (the encode reads them); both are caller stack buffers.
    fn signRelayOrigin(
        self: *LinuxServer,
        msg: *s2s_link.RelayMessage,
        pubkey_buf: *[message_relay.pubkey_len]u8,
        sig_buf: *[message_relay.sig_len]u8,
    ) void {
        const ident = self.config.node_identity orelse return;
        // Self-certification invariant: the stamped origin id MUST equal
        // `originShortId(pubkey)`. `origin_node` is `config.node_id`, which an
        // operator can set independently of the node key; only sign when they
        // agree so a receiver's `originShortId(pubkey) == origin_node` check holds.
        if (ident.shortId() != msg.origin_node) return;
        const transcript = message_relay.originTranscript(self.allocator, msg.*) catch return;
        defer self.allocator.free(transcript);
        message_relay.signInPlace(msg, &ident.sign_kp, transcript, pubkey_buf, sig_buf) catch return;
    }

    /// A self-contained multi-hop origin signature for a LOCALLY-authored channel
    /// PROP fact: the origin node id this node certifies, plus the stamped
    /// `(pubkey, sig)` borrowing the caller's backing buffers. `pubkey`/`sig` are
    /// empty when this node cannot sign (no node identity), in which case the
    /// fact follows the legacy unsigned path. `node` is always `config.node_id`
    /// (the local origin) regardless of signing.
    const LocalPropSig = struct {
        node: u64,
        pubkey: []const u8 = "",
        sig: []const u8 = "",
    };

    /// Sign a LOCALLY-authored channel PROP fact's canonical transcript ONCE, at
    /// the origin (this node), returning the stamped `(pubkey, sig)` to STORE with
    /// the clock and re-emit on every re-broadcast/burst. No-op (unsigned) when
    /// this node has no node identity, OR when `config.node_id` is not the
    /// self-certified short id of the node key — signing then would mint a
    /// signature that fails its own origin check, so the fact is left unsigned.
    /// Mirrors `signRelayOrigin` exactly for the CHANNEL_PROP CRDT. `pubkey_buf`/
    /// `sig_buf` back the returned slices and MUST outlive the
    /// `recordChannelPropClock` + announce that follow.
    fn signLocalChannelProp(
        self: *LinuxServer,
        present: bool,
        channel: []const u8,
        key: []const u8,
        value: []const u8,
        owner: []const u8,
        hlc: u64,
        pubkey_buf: *[channel_prop_event.pubkey_len]u8,
        sig_buf: *[channel_prop_event.sig_len]u8,
    ) LocalPropSig {
        // Stamp the origin with the node's MESH identity — the key's short id,
        // which is what the secured s2s link speaks (`local_node_id`) — NOT
        // `config.node_id` (a human-facing label an operator sets independently
        // of the key). Using the short id makes the fact self-certifying: the
        // receiver's `originShortId(pubkey) == origin_node` check holds, the
        // signed fact bypasses the direct-origin gate, and it applies. Stamping
        // config.node_id instead left the fact unsigned AND with an origin the
        // peer's direct-origin gate rejected — so channel props never propagated.
        const ident = self.config.node_identity orelse return .{ .node = self.config.node_id };
        const origin_node = ident.shortId();

        var ev = channel_prop_event.ChannelPropEvent{
            .present = present,
            .origin_node = origin_node,
            .hlc = hlc,
            .channel = channel,
            .key = key,
            .value = value,
            .owner = owner,
        };
        const transcript = channel_prop_event.originTranscript(self.allocator, ev) catch return .{ .node = origin_node };
        defer self.allocator.free(transcript);
        channel_prop_event.signInPlace(&ev, &ident.sign_kp, transcript, pubkey_buf, sig_buf) catch return .{ .node = origin_node };
        return .{ .node = origin_node, .pubkey = ev.origin_pubkey, .sig = ev.origin_sig };
    }

    /// Sign a LOCALLY-authored user/member PROP fact's canonical transcript ONCE,
    /// at the origin (this node). The ENTITY_PROP counterpart of
    /// `signLocalChannelProp`: identical no-op-unless-self-certifying contract.
    /// `pubkey_buf`/`sig_buf` back the returned slices and MUST outlive the
    /// `recordEntityPropClock` + announce that follow.
    fn signLocalEntityProp(
        self: *LinuxServer,
        present: bool,
        kind: entity_prop_event.EntityKind,
        entity: []const u8,
        key: []const u8,
        value: []const u8,
        owner: []const u8,
        hlc: u64,
        pubkey_buf: *[entity_prop_event.pubkey_len]u8,
        sig_buf: *[entity_prop_event.sig_len]u8,
    ) LocalPropSig {
        // Mesh identity (key short id), not config.node_id — see
        // `signLocalChannelProp` for why. Entity (user/member) props share the
        // same CRDT propagation gate, so they had the same silent drop.
        const ident = self.config.node_identity orelse return .{ .node = self.config.node_id };
        const origin_node = ident.shortId();

        var ev = entity_prop_event.EntityPropEvent{
            .present = present,
            .kind = kind,
            .origin_node = origin_node,
            .hlc = hlc,
            .entity = entity,
            .key = key,
            .value = value,
            .owner = owner,
        };
        const transcript = entity_prop_event.originTranscript(self.allocator, ev) catch return .{ .node = origin_node };
        defer self.allocator.free(transcript);
        entity_prop_event.signInPlace(&ev, &ident.sign_kp, transcript, pubkey_buf, sig_buf) catch return .{ .node = origin_node };
        return .{ .node = origin_node, .pubkey = ev.origin_pubkey, .sig = ev.origin_sig };
    }

    /// Recover the rendered nick from the IRC prefix. On verified messages this
    /// prefix is origin-signed; on legacy unsigned traffic it is merely the one
    /// internally-consistent identity source. The separately encoded
    /// `source_nick` field is advisory and never selects a local session.
    fn relaySourceNickFromPrefix(source_prefix: []const u8) ?[]const u8 {
        if (source_prefix.len == 0 or source_prefix[0] == ':') return null;
        var end = source_prefix.len;
        if (std.mem.indexOfScalar(u8, source_prefix, '!')) |at| end = @min(end, at);
        if (std.mem.indexOfScalar(u8, source_prefix, '@')) |at| end = @min(end, at);
        if (end == 0) return null;
        return source_prefix[0..end];
    }

    /// Resolve a signed relay origin's authenticated/gossiped server name. A
    /// direct peer is bound by its handshake node id; a multi-hop origin is
    /// resolved through the converged node registry carried by any live link.
    fn relayOriginServerName(self: *LinuxServer, origin_node: u64) ?[]const u8 {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    if (link.remoteNodeId() == origin_node and link.remoteName().len != 0) return link.remoteName();
                    if (link.nodeName(origin_node)) |name| if (name.len != 0) return name;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    if (link.remoteNodeId() == origin_node and link.remoteName().len != 0) return link.remoteName();
                    if (link.nodeName(origin_node)) |name| if (name.len != 0) return name;
                }
            }
        }
        return null;
    }

    /// True only for the server-authored webhook prefix shape emitted by
    /// `injectWebhookPost`: `nick!webhook@<origin-server>`. The prefix and origin
    /// node are covered by the verified end-to-end signature, and the host must
    /// equal the mesh registry's authenticated name for that origin. A client
    /// merely choosing USER `webhook` cannot satisfy the server-host binding.
    fn isVerifiedWebhookRelay(self: *LinuxServer, msg: s2s_link.RelayMessage, auth: RelayOriginAuth) bool {
        if (auth != .verified) return false;
        // This exception is only for the immutable shape authored by
        // `injectWebhookPost`; a keyed peer must not obtain a general nick-home
        // bypass by putting `webhook` in an arbitrary DM/NOTICE/DATA prefix.
        if (msg.verb != .privmsg or !world_model.isChannelName(msg.target) or
            msg.min_rank != 0 or msg.recipient.len != 0 or msg.data_tag.len != 0)
            return false;
        const bang = std.mem.indexOfScalar(u8, msg.source_prefix, '!') orelse return false;
        const at_rel = std.mem.indexOfScalar(u8, msg.source_prefix[bang + 1 ..], '@') orelse return false;
        const at = bang + 1 + at_rel;
        if (!std.mem.eql(u8, msg.source_prefix[bang + 1 .. at], "webhook")) return false;
        const origin_name = self.relayOriginServerName(msg.origin_node) orelse return false;
        return std.ascii.eqlIgnoreCase(msg.source_prefix[at + 1 ..], origin_name);
    }

    const RelayV2History = struct {
        target: []const u8,
        sender: []const u8,
        text: []const u8,
        command: []const u8,
        client_tags: ?[]const u8,
        timestamp_ms: u64,
    };

    const RelayV2AdmitOutcome = union(enum) {
        accepted: relay_v2_replay_guard.RelayId,
        duplicate: relay_v2_replay_guard.RelayId,
        rejected,
    };

    const RelayV2OutboxReservation = struct {
        peers: []const u64,
        receipt_peer: ?u64 = null,
        wire: []const u8,
        unbound_excluded_peer: u64 = relay_v2_outbox.local_origin_exclusion,
    };

    /// Stage MESSAGE_V2 replay authority in a complete candidate, optionally
    /// enter the same accepted RelayId into Lotus, and publish both only at the
    /// no-fail boundary. Callers must finish routing/policy checks before asking
    /// for a history row: `.inserted` is the only outcome that authorizes live
    /// delivery, SearchIndex projection, or exact-wire re-forwarding. A duplicate,
    /// equivocation, malformed row, capacity failure, or OOM leaves the live
    /// RVG2 authority unchanged; Lotus' ingestExactOnce contract likewise leaves
    /// all non-insert outcomes byte-exact.
    fn admitRelayV2Detailed(
        self: *LinuxServer,
        msg: message_relay_v2.RelayMessage,
        history: ?RelayV2History,
        outbox: ?RelayV2OutboxReservation,
        delivery: ?*PreparedAttachmentDeliveryBatch,
    ) std.mem.Allocator.Error!RelayV2AdmitOutcome {
        lockSpin(&self.relay_v2_replay_mu);
        defer self.relay_v2_replay_mu.unlock();
        const checkpoint = self.relay_v2_replay_guard.encodeCheckpoint(self.allocator) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return .rejected,
        };
        defer self.allocator.free(checkpoint);
        var candidate = relay_v2_replay_guard.Guard.decodeCheckpoint(
            self.allocator,
            self.relay_v2_replay_guard.config,
            checkpoint,
        ) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return .rejected,
        };
        defer candidate.deinit();
        const relay_id = switch (try candidate.admitMessage(msg)) {
            .accepted => |id| id,
            .duplicate => |id| return .{ .duplicate = id },
            .equivocation,
            .retired,
            .origin_capacity,
            .origin_mismatch,
            .bad_signature,
            .invalid_semantic,
            => return .rejected,
        };

        var event_log_plan: ?relay_v2_event_log.PreparedAccepted = null;
        defer if (event_log_plan) |*plan| plan.deinit();
        if (outbox) |reservation| {
            if (self.relay_v2_required_nodes.len < 2) return .rejected;
            const prepared = self.relay_v2_event_log.prepareAccepted(
                relay_id,
                reservation.wire,
                self.config.node_id,
                reservation.receipt_peer,
                self.relay_v2_required_nodes,
            ) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                else => return .rejected,
            };
            event_log_plan = switch (prepared) {
                .ready => |plan| plan,
                .conflict => return .rejected,
            };
            if (event_log_plan.?.outcome() != .inserted) return .rejected;
        }

        var lotus_candidate: ?HistoryStore = null;
        defer if (lotus_candidate) |*candidate_store| candidate_store.deinit();
        if (history) |row| {
            const lotus_checkpoint = self.history.encodeCheckpoint(self.allocator) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                else => return .rejected,
            };
            defer self.allocator.free(lotus_checkpoint);
            lotus_candidate = HistoryStore.decodeCheckpoint(self.allocator, lotus_checkpoint) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                else => return .rejected,
            };
            var msgid_buf: [msgid_mod.id_len]u8 = undefined;
            const stable_msgid = msgid_mod.fromStableId(relay_id, &msgid_buf);
            const result = lotus_candidate.?.ingestExactOnce(row.target, .{
                .msgid = stable_msgid,
                .sender = row.sender,
                .text = row.text,
                .timestamp = row.timestamp_ms,
                .command = row.command,
                .client_tags = row.client_tags,
            }) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                else => return .rejected,
            };
            switch (result) {
                .inserted => {},
                .exact_duplicate, .equivocation => return .rejected,
            }
        }

        // Reserve every immediate-hop retransmission before either RVG2 or
        // Lotus becomes live. putBatch is itself failure-atomic, and no fallible
        // work follows this point.
        if (outbox) |reservation| {
            self.relay_v2_outbox.putBatchExcluding(
                reservation.peers,
                reservation.receipt_peer,
                relay_id,
                reservation.wire,
                self.meshWallMs() +| relay_v2_initial_retry_ms,
                reservation.unbound_excluded_peer,
            ) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                else => return .rejected,
            };
        }

        // Every fallible authority reservation is complete. Publish the exact
        // per-attachment rendered records in the same allocation-free cut as
        // Lotus and RVG2, before an inbound caller can emit ACK.
        if (delivery) |prepared_delivery| prepared_delivery.commit();

        if (lotus_candidate) |*candidate_store|
            std.mem.swap(HistoryStore, &self.history, candidate_store);

        std.mem.swap(
            relay_v2_replay_guard.Guard,
            &self.relay_v2_replay_guard,
            &candidate,
        );
        if (event_log_plan) |*plan| _ = plan.commit();
        if (history) |row| {
            var thread_msgid_buf: [msgid_mod.id_len]u8 = undefined;
            const thread_msgid = msgid_mod.fromStableId(relay_id, &thread_msgid_buf);
            self.noteThreadFromTags(thread_msgid, row.client_tags);
        }
        return .{ .accepted = relay_id };
    }

    fn probeRelayV2(
        self: *LinuxServer,
        msg: message_relay_v2.RelayMessage,
        via_peer: u64,
    ) std.mem.Allocator.Error!relay_v2_replay_guard.Probe {
        lockSpin(&self.relay_v2_replay_mu);
        defer self.relay_v2_replay_mu.unlock();
        const probe = try self.relay_v2_replay_guard.probeMessage(msg);
        return switch (probe) {
            .unseen => |id| if (self.relay_v2_event_log.contains(id) or
                self.relay_v2_outbox.containsReceipt(via_peer, id))
                .{ .duplicate = id }
            else
                probe,
            .retired => |id| if (self.relay_v2_event_log.contains(id) or
                self.relay_v2_outbox.containsReceipt(via_peer, id))
                .{ .duplicate = id }
            else
                probe,
            else => probe,
        };
    }

    /// An RVG2 duplicate can still be a new authenticated ingress edge in a
    /// cycle, or a replay whose prior ACK was lost. Reserve that peer's durable
    /// receipt and the RVL2 one-sweep exclusion transactionally before ACKing.
    /// A row already retired from RVL2 is re-ACKable only when RVO2 still holds
    /// this exact peer receipt.
    fn retainRelayV2DuplicateIngress(
        self: *LinuxServer,
        relay_id: relay_v2_replay_guard.RelayId,
        wire: []const u8,
        via_peer: u64,
    ) std.mem.Allocator.Error!bool {
        if (!self.relayV2DirectNeighbor(via_peer) or self.relay_v2_required_nodes.len < 2)
            return false;
        const peers = try self.collectRelayV2OutboxPeers(via_peer, false);
        defer self.allocator.free(peers);

        lockSpin(&self.relay_v2_replay_mu);
        defer self.relay_v2_replay_mu.unlock();
        if (!self.relay_v2_event_log.contains(relay_id))
            return self.relay_v2_outbox.containsReceipt(via_peer, relay_id);
        const prepared = self.relay_v2_event_log.prepareAccepted(
            relay_id,
            wire,
            self.config.node_id,
            via_peer,
            self.relay_v2_required_nodes,
        ) catch |err| return switch (err) {
            error.OutOfMemory => error.OutOfMemory,
            else => false,
        };
        var plan = switch (prepared) {
            .ready => |ready| ready,
            .conflict => return false,
        };
        defer plan.deinit();
        if (plan.outcome() != .exact_duplicate) return false;
        // An exact ingress replay cannot undo a durable neighbor ACK or widen
        // the event's original coverage set. Keep its receipt, but reserve
        // retries only for still-unconfirmed peers in the retained authority.
        const retained = self.relay_v2_event_log.viewFor(relay_id) orelse return false;
        var pending_len: usize = 0;
        for (peers) |peer| {
            if (std.mem.indexOfScalar(u64, retained.required_nodes, peer) == null or
                std.mem.indexOfScalar(u64, retained.confirmed_nodes, peer) != null) continue;
            peers[pending_len] = peer;
            pending_len += 1;
        }
        self.relay_v2_outbox.putBatchExcluding(
            peers[0..pending_len],
            via_peer,
            relay_id,
            wire,
            self.meshWallMs() +| relay_v2_initial_retry_ms,
            via_peer,
        ) catch |err| return switch (err) {
            error.OutOfMemory => error.OutOfMemory,
            else => false,
        };
        _ = plan.commit();
        return true;
    }

    fn admitRelayV2(
        self: *LinuxServer,
        msg: message_relay_v2.RelayMessage,
        history: ?RelayV2History,
    ) std.mem.Allocator.Error!?relay_v2_replay_guard.RelayId {
        return switch (try self.admitRelayV2Detailed(msg, history, null, null)) {
            .accepted => |id| id,
            .duplicate, .rejected => null,
        };
    }

    const AcceptedAuthoredRelayV2 = struct {
        relay_id: relay_v2_replay_guard.RelayId,
        wire: []u8,
        /// True when ADS1 reserved the reusable-session recipient batch in the
        /// same no-fail cut as RVG2/Lotus. False when spool pressure forced a
        /// soft-fail: callers must use ordinary/mesh_busy_local delivery, not
        /// prepared_batch (which only drains the empty spool and drops the line).
        has_attachment_batch: bool = true,

        fn deinit(self: *AcceptedAuthoredRelayV2, allocator: std.mem.Allocator) void {
            allocator.free(self.wire);
            self.* = undefined;
        }

        fn deliveryMode(self: AcceptedAuthoredRelayV2) TaggedDeliveryMode {
            return if (self.has_attachment_batch) .prepared_batch else .ordinary;
        }
    };

    const AuthoredRelayV2Delivery = struct {
        recipients: []const client_model.ClientId,
        line: []const u8,
        is_bot: bool = false,
    };

    fn collectRelayV2OutboxPeers(
        self: *LinuxServer,
        exclude_peer: ?u64,
        include_unbound_when_empty: bool,
    ) std.mem.Allocator.Error![]u64 {
        var peers: std.ArrayList(u64) = .empty;
        errdefer peers.deinit(self.allocator);
        _ = include_unbound_when_empty;
        for (self.relay_v2_required_nodes) |peer| {
            if (peer == self.config.node_id) continue;
            if (exclude_peer != null and peer == exclude_peer.?) continue;
            try peers.append(self.allocator, peer);
        }
        return peers.toOwnedSlice(self.allocator);
    }

    fn relayV2DirectNeighbor(self: *const LinuxServer, node: u64) bool {
        if (node == 0 or node == self.config.node_id) return false;
        for (self.relay_v2_required_nodes) |required| {
            if (required == node) return true;
        }
        return false;
    }

    /// Build and sign one immutable local MESSAGE_V2, finish every allocation
    /// (including canonical encode) before authority publication, then enter it
    /// through the same RVG2/Lotus transaction as inbound traffic.
    fn admitAuthoredRelayV2(
        self: *LinuxServer,
        verb: message_relay_v2.Verb,
        target: []const u8,
        min_rank: u8,
        source_prefix: []const u8,
        account: []const u8,
        tags: []const u8,
        data_tag: []const u8,
        text: []const u8,
        scope_kind: message_relay_v2.ScopeKind,
        recipient: []const u8,
        sender_token: ?sessions_mod.Token,
        sender_member_modes: ?u8,
        recipient_token: ?sessions_mod.Token,
        hlc: u64,
        history: ?RelayV2History,
        delivery: ?AuthoredRelayV2Delivery,
    ) !?AcceptedAuthoredRelayV2 {
        const identity = self.config.node_identity orelse return null;
        const sender_route = if (sender_token) |token|
            message_relay_v2.routeId(token) catch return null
        else
            null;
        const recipient_route = if (recipient_token) |token|
            message_relay_v2.routeId(token) catch return null
        else
            null;
        var pubkey: [message_relay_v2.pubkey_len]u8 = undefined;
        var signature: [message_relay_v2.sig_len]u8 = undefined;
        var msg = message_relay_v2.RelayMessage{
            .verb = verb,
            .target = target,
            .min_rank = min_rank,
            .source_prefix = source_prefix,
            .account = account,
            .tags = tags,
            .data_tag = data_tag,
            .text = text,
            .recipient = recipient,
            .scope_kind = scope_kind,
            .sender_route_id = sender_route,
            .sender_member_modes = sender_member_modes,
            .recipient_route_id = recipient_route,
            .origin_node = self.config.node_id,
            .hlc = hlc,
        };
        try message_relay_v2.stampOrigin(
            self.allocator,
            &msg,
            &identity.sign_kp,
            &pubkey,
            &signature,
        );
        const wire = try message_relay_v2.encode(self.allocator, msg);
        errdefer self.allocator.free(wire);
        var prepared_delivery: ?PreparedAttachmentDeliveryBatch = null;
        defer if (prepared_delivery) |*prepared| prepared.deinit();
        if (delivery) |plan| {
            const predicted_relay_id = try message_relay_v2.relayId(self.allocator, msg);
            var msgid_buf: [msgid_mod.id_len]u8 = undefined;
            var time_buf: [40]u8 = undefined;
            const stable_msgid = msgid_mod.fromStableId(predicted_relay_id, &msgid_buf);
            // ADS1 spool pressure must not abort RVG2/Lotus/RVL2 admission.
            // When the attachment batch cannot be reserved, continue without it
            // so mesh durability still publishes and local delivery uses
            // mesh_busy_local SendQ (not a skip of durable admit).
            prepared_delivery = self.prepareAttachmentDeliveryBatch(
                plan.recipients,
                .{
                    .time_value = serverTimeValueAt(
                        &time_buf,
                        mesh_clock_mod.MeshClock.physicalOf(hlc),
                    ),
                    .account = if (account.len != 0) account else null,
                    .client_tags = if (tags.len != 0) tags else null,
                    .msgid = stable_msgid,
                    .is_bot = plan.is_bot,
                },
                plan.line,
            ) catch |err| switch (err) {
                error.OutOfMemory, error.CapacityExceeded => null,
                else => return err,
            };
        }
        const peers = try self.collectRelayV2OutboxPeers(null, true);
        defer self.allocator.free(peers);
        // Only a staged ADS1 batch counts. An empty prepare (no reusable
        // recipients) returns a non-null shell with prepared=null — that must
        // NOT force prepared_batch delivery (wake-only drain of an empty spool
        // would drop every recipient that later becomes reusable mid-fanout).
        const has_attachment_batch = if (prepared_delivery) |pd| pd.prepared != null else false;
        const relay_id = switch (try self.admitRelayV2Detailed(msg, history, .{
            .peers = peers,
            .wire = wire,
            .unbound_excluded_peer = self.config.node_id,
        }, if (prepared_delivery) |*prepared| prepared else null)) {
            .accepted => |id| id,
            .duplicate, .rejected => {
                self.allocator.free(wire);
                return null;
            },
        };
        if (prepared_delivery) |*prepared| prepared.release();
        return .{
            .relay_id = relay_id,
            .wire = wire,
            .has_attachment_batch = has_attachment_batch,
        };
    }

    /// Re-flood one already-admitted MESSAGE_V2 object without decode/re-encode
    /// drift. Only secured, negotiated v2 links are eligible; inbound v2 is
    /// never downgraded into legacy MESSAGE, whose mutable fields and bounded
    /// seen set cannot preserve the same authority.
    fn forwardAcceptedRelayV2(self: *LinuxServer, wire: []const u8) void {
        _ = wire;
        // All MESSAGE_V2 egress, including the just-accepted live case, flows
        // through RVL2's per-origin ordered scheduler. Direct forwarding here
        // could let e1..e65 overtake a retained e0 and make RVG2 retire e0 at the
        // receiver. Reactor 0 owns S2S links; foreign shards only wake it.
        if (current_reactor == &self.reactors[0]) {
            self.retryRelayV2Outbox();
        } else if (self.reactors[0].wake) |*wake| {
            wake.wake();
        }
    }

    fn deferRelayV2(
        self: *LinuxServer,
        item: *s2s_link.InboundMessageV2,
        reason: RelayV2DeferredReason,
    ) bool {
        for (self.relay_v2_deferred[0..self.relay_v2_deferred_len]) |*pending| {
            if (std.mem.eql(u8, pending.inbound.wire, item.wire)) {
                if (reason == .unknown_home_authority) pending.reason = .unknown_home_authority;
                item.deinit(self.allocator);
                return true;
            }
        }
        if (self.relay_v2_deferred_len == relay_v2_deferred_capacity) return false;
        self.relay_v2_deferred[self.relay_v2_deferred_len] = .{
            .inbound = item.*,
            .reason = reason,
            .first_deferred_ms = self.meshWallMs(),
            .retries = 0,
        };
        self.relay_v2_deferred_len += 1;
        item.* = undefined;
        return true;
    }

    fn relayV2UnknownHomeRetryExpired(_: *LinuxServer, pending: *const DeferredRelayV2, now_ms: u64) bool {
        if (pending.reason != .unknown_home_authority) return false;
        if (pending.retries >= relay_v2_unknown_home_retry_limit) return true;
        return now_ms >= pending.first_deferred_ms and
            now_ms - pending.first_deferred_ms >= relay_v2_unknown_home_retry_ttl_ms;
    }

    const RelayV2DeliveryOutcome = union(enum) {
        accepted: relay_v2_replay_guard.RelayId,
        duplicate: relay_v2_replay_guard.RelayId,
        permanent,
        retry: RelayV2DeferredReason,
    };

    fn sendRelayV2AckToPeer(
        self: *LinuxServer,
        peer: u64,
        relay_id: relay_v2_replay_guard.RelayId,
    ) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, slot_index| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established() or !link.supportsSecureRelayV2()) continue;
                if ((link.remoteNodeId() orelse continue) != peer) continue;
                const peer_id = slotClientId(reactor, slot_index, slot.gen);
                // A prior retry may already own complete ciphertext in the
                // shared secured buffer. Drain it first; encoding the same
                // receipt again on every due pass would grow unbounded while a
                // healthy peer's SendQ remains congested.
                if (!self.flushSecuredS2sOutboundTo(peer_id, link)) return false;
                link.sendMessageV2Ack(relay_id) catch return false;
                if (!self.flushSecuredS2sOutboundTo(peer_id, link)) return false;
                return true;
            }
        }
        return false;
    }

    fn sendRelayV2AckConfirmToPeer(
        self: *LinuxServer,
        peer: u64,
        relay_id: relay_v2_replay_guard.RelayId,
    ) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, slot_index| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established() or !link.supportsRelayV2AckConfirm()) continue;
                if ((link.remoteNodeId() orelse continue) != peer) continue;
                const peer_id = slotClientId(reactor, slot_index, slot.gen);
                if (!self.flushSecuredS2sOutboundTo(peer_id, link)) return;
                link.sendMessageV2AckConfirm(relay_id) catch return;
                if (!self.flushSecuredS2sOutboundTo(peer_id, link)) return;
                return;
            }
        }
    }

    fn commitRelayV2NeighborAck(
        self: *LinuxServer,
        peer: u64,
        relay_id: relay_v2_replay_guard.RelayId,
    ) bool {
        if (!self.relayV2DirectNeighbor(peer)) return false;
        lockSpin(&self.relay_v2_replay_mu);
        defer self.relay_v2_replay_mu.unlock();
        if (!self.relay_v2_event_log.contains(relay_id)) {
            // A duplicate ACK after the last required confirmation retired RVL2
            // still needs another ACK_CONFIRM; the 128-bit ID came from the
            // authenticated neighbor and RVG2 remains the retired-ID authority.
            _ = self.relay_v2_outbox.acknowledge(peer, relay_id);
            return true;
        }
        var plan = self.relay_v2_event_log.prepareAuthenticatedDurableAck(
            relay_id,
            peer,
        ) catch return false;
        defer plan.deinit();
        _ = self.relay_v2_outbox.acknowledge(peer, relay_id);
        _ = plan.commit();
        return true;
    }

    fn commitRelayV2IngressAckConfirm(
        self: *LinuxServer,
        peer: u64,
        relay_id: relay_v2_replay_guard.RelayId,
    ) bool {
        if (!self.relayV2DirectNeighbor(peer)) return false;
        lockSpin(&self.relay_v2_replay_mu);
        defer self.relay_v2_replay_mu.unlock();
        // ACK_CONFIRM is meaningful only for a receipt we durably reserved when
        // accepting this exact neighbor's ingress. This blocks unsolicited
        // confirmations from manufacturing coverage.
        if (!self.relay_v2_outbox.containsReceipt(peer, relay_id)) return false;
        if (!self.relay_v2_event_log.contains(relay_id)) {
            _ = self.relay_v2_outbox.acknowledge(peer, relay_id);
            return self.relay_v2_outbox.confirmReceipt(peer, relay_id);
        }
        var plan = self.relay_v2_event_log.prepareAuthenticatedDurableAck(
            relay_id,
            peer,
        ) catch return false;
        defer plan.deinit();
        _ = self.relay_v2_outbox.acknowledge(peer, relay_id);
        _ = self.relay_v2_outbox.confirmReceipt(peer, relay_id);
        _ = plan.commit();
        return true;
    }

    fn drainRelayV2Acks(
        self: *LinuxServer,
        conn: *const ConnState,
        link: *secured_s2s_link.SecuredLink,
    ) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const peer = link.remoteNodeId() orelse return;
        const acks = link.takeInboundV2Acks() catch return;
        defer self.allocator.free(acks);
        // Confirmation has its own negotiated payload shape, so it is safe to
        // answer even a duplicate ACK after the outbound row was already removed.
        // A lost confirmation therefore triggers another ACK/confirm round rather
        // than pinning the receiver's durable admission proof forever.
        for (acks) |id| {
            if (comptime builtin.is_test)
                if (self.consumeRelayV2AckDropForTest(peer, id)) continue;
            if (self.commitRelayV2NeighborAck(peer, id))
                self.sendRelayV2AckConfirmToPeer(peer, id);
        }

        const confirms = link.takeInboundV2AckConfirms() catch return;
        defer self.allocator.free(confirms);
        for (confirms) |id| _ = self.commitRelayV2IngressAckConfirm(peer, id);
        if (acks.len != 0 or confirms.len != 0) self.forwardAcceptedRelayV2(&.{});
    }

    fn consumeRelayV2AckDropForTest(
        self: *LinuxServer,
        peer: u64,
        relay_id: relay_v2_replay_guard.RelayId,
    ) bool {
        if (comptime !builtin.is_test) return false;
        lockSpin(&self.relay_v2_replay_mu);
        defer self.relay_v2_replay_mu.unlock();
        if (!self.test_drop_relay_v2_ack.armed or
            self.test_drop_relay_v2_ack.peer != peer or
            !std.mem.eql(u8, &self.test_drop_relay_v2_ack.relay_id, &relay_id))
        {
            return false;
        }
        self.test_drop_relay_v2_ack = .{};
        return true;
    }

    fn dropRelayV2AckForMsgidFromForTest(
        self: *LinuxServer,
        peer: u64,
        msgid: []const u8,
    ) !relay_v2_replay_guard.RelayId {
        if (comptime !builtin.is_test) return error.Unsupported;
        if (peer == 0 or msgid.len != msgid_mod.id_len) return error.InvalidFaultTarget;
        lockSpin(&self.relay_v2_replay_mu);
        defer self.relay_v2_replay_mu.unlock();
        if (self.test_drop_relay_v2_ack.armed) return error.AlreadyArmed;

        var matched: ?relay_v2_replay_guard.RelayId = null;
        var rendered_buf: [msgid_mod.id_len]u8 = undefined;
        var index: usize = 0;
        while (index < self.relay_v2_event_log.len()) : (index += 1) {
            const row = self.relay_v2_event_log.viewAt(index);
            const rendered = msgid_mod.fromStableId(row.relay_id, &rendered_buf);
            if (!std.mem.eql(u8, rendered, msgid)) continue;
            if (matched != null) return error.AmbiguousFaultTarget;
            matched = row.relay_id;
        }
        self.test_drop_relay_v2_ack = .{
            .armed = true,
            .peer = peer,
            .relay_id = matched orelse return error.RelayNotRetained,
        };
        return self.test_drop_relay_v2_ack.relay_id;
    }

    fn relayV2AckDropArmedForTest(self: *LinuxServer) bool {
        if (comptime !builtin.is_test) return false;
        lockSpin(&self.relay_v2_replay_mu);
        defer self.relay_v2_replay_mu.unlock();
        return self.test_drop_relay_v2_ack.armed;
    }

    const RelayV2AuthorityStateForTest = struct {
        event_retained: bool,
        outbox_retained: bool,
        receipt_retained: bool,
    };

    fn relayV2AuthorityStateForTest(
        self: *LinuxServer,
        peer: u64,
        relay_id: relay_v2_replay_guard.RelayId,
    ) RelayV2AuthorityStateForTest {
        self.world.lockWrite();
        defer self.world.unlockWrite();
        lockSpin(&self.relay_v2_replay_mu);
        defer self.relay_v2_replay_mu.unlock();
        return .{
            .event_retained = self.relay_v2_event_log.contains(relay_id),
            .outbox_retained = self.relay_v2_outbox.contains(peer, relay_id),
            .receipt_retained = self.relay_v2_outbox.containsReceipt(peer, relay_id),
        };
    }

    fn sessionReplicaChannelFromOriginForTest(
        self: *LinuxServer,
        token: session_migrate.Token,
        origin: u64,
        channel: []const u8,
    ) bool {
        self.world.lockWrite();
        defer self.world.unlockWrite();
        const entry = self.session_replica_store.getOrigin(token, origin) orelse return false;
        if (entry.revision.origin_node != origin) return false;
        var snapshot = migration_relay.Snapshot.decode(self.allocator, entry.snapshot) catch return false;
        defer snapshot.deinit(self.allocator);
        return sessionSnapshotChannelMode(&snapshot, channel) != null;
    }

    fn replayRelayV2WireToPeer(self: *LinuxServer, peer: u64, wire: []const u8) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, slot_index| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established() or !link.supportsSecureRelayV2()) continue;
                if ((link.remoteNodeId() orelse continue) != peer) continue;
                const peer_id = slotClientId(reactor, slot_index, slot.gen);
                if (!self.flushSecuredS2sOutboundTo(peer_id, link)) return false;
                link.replayRetainedMessageV2Wire(wire) catch return false;
                if (!self.flushSecuredS2sOutboundTo(peer_id, link)) return false;
                return true;
            }
        }
        return false;
    }

    fn collectRelayV2RetryWork(
        self: *LinuxServer,
        work: []RelayV2RetryWork,
    ) usize {
        if (work.len == 0 or self.relay_v2_required_nodes.len == 0) return 0;
        var work_len: usize = 0;
        var bytes_staged: usize = 0;

        lockSpin(&self.relay_v2_replay_mu);
        defer self.relay_v2_replay_mu.unlock();
        const peer_count = self.relay_v2_required_nodes.len;
        var cursor = self.relay_v2_peer_cursor % peer_count;
        var remaining = peer_count;
        while (remaining != 0 and work_len < work.len) {
            if (work_len != 0 and bytes_staged >= relay_v2_retry_byte_budget) break;

            const peer = self.relay_v2_required_nodes[cursor];
            cursor = (cursor + 1) % peer_count;
            self.relay_v2_peer_cursor = cursor;
            remaining -= 1;
            if (peer == self.config.node_id) continue;

            var page: [1]relay_v2_event_log.PageItem = undefined;
            const page_len = self.relay_v2_event_log.collectPageForNode(peer, &page) catch continue;
            if (page_len == 0) continue;
            const item = page[0];
            if (work_len != 0 and item.wire.len > relay_v2_retry_byte_budget - bytes_staged)
                continue;
            const wire = self.allocator.dupe(u8, item.wire) catch continue;
            work[work_len] = .{ .peer = peer, .relay_id = item.relay_id, .wire = wire };
            work_len += 1;
            bytes_staged +|= item.wire.len;
        }
        return work_len;
    }

    fn retryRelayV2Outbox(self: *LinuxServer) void {
        var work: [relay_v2_retry_frame_budget]RelayV2RetryWork = undefined;
        const now = self.meshWallMs();
        const work_len = self.collectRelayV2RetryWork(&work);

        defer for (work[0..work_len]) |item| self.allocator.free(item.wire);
        for (work[0..work_len]) |item| {
            _ = self.replayRelayV2WireToPeer(item.peer, item.wire);
        }

        // Accepted inbound receipts use the same bounded, fair retry shape. ACK
        // confirmation removes them; a lost ACK or confirmation cannot age the
        // proof out behind unrelated messages.
        var receipts: [relay_v2_retry_frame_budget]relay_v2_outbox.Receipt = undefined;
        lockSpin(&self.relay_v2_replay_mu);
        const receipt_len = self.relay_v2_outbox.collectDueReceipts(now, &receipts);
        self.relay_v2_replay_mu.unlock();
        for (receipts[0..receipt_len]) |receipt| {
            if (!self.sendRelayV2AckToPeer(receipt.peer, receipt.relay_id)) continue;
            lockSpin(&self.relay_v2_replay_mu);
            for (self.relay_v2_outbox.mutableReceiptItems()) |*live| {
                if (live.peer != receipt.peer or
                    !std.mem.eql(u8, &live.relay_id, &receipt.relay_id)) continue;
                live.attempts +|= 1;
                const shift: u5 = @intCast(@min(live.attempts, 5));
                live.retry_after_ms = now +| (relay_v2_initial_retry_ms << shift);
                break;
            }
            self.relay_v2_replay_mu.unlock();
        }
    }

    fn retryDeferredRelayV2(self: *LinuxServer) void {
        const now_ms = self.meshWallMs();
        var index: usize = 0;
        while (index < self.relay_v2_deferred_len) {
            const pending = &self.relay_v2_deferred[index];
            switch (self.deliverRelayV2(
                pending.inbound.owned.msg,
                pending.inbound.wire,
                pending.inbound.via_peer,
            )) {
                .retry => |reason| {
                    pending.reason = reason;
                    pending.retries +|= 1;
                    if (self.relayV2UnknownHomeRetryExpired(pending, now_ms)) {
                        pending.deinit(self.allocator);
                        self.relay_v2_deferred_len -= 1;
                        if (index != self.relay_v2_deferred_len)
                            self.relay_v2_deferred[index] = self.relay_v2_deferred[self.relay_v2_deferred_len];
                        continue;
                    }
                    index += 1;
                    continue;
                },
                .accepted => |id| _ = self.sendRelayV2AckToPeer(pending.inbound.via_peer, id),
                .duplicate => |id| _ = self.sendRelayV2AckToPeer(pending.inbound.via_peer, id),
                .permanent => {},
            }
            pending.deinit(self.allocator);
            self.relay_v2_deferred_len -= 1;
            if (index != self.relay_v2_deferred_len)
                self.relay_v2_deferred[index] = self.relay_v2_deferred[self.relay_v2_deferred_len];
        }
    }

    fn drainRelayV2(
        self: *LinuxServer,
        conn: *ConnState,
        link: *secured_s2s_link.SecuredLink,
    ) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const inbound = link.takeInboundV2() catch return;
        defer self.allocator.free(inbound);
        for (inbound, 0..) |*item, inbound_index| {
            switch (self.deliverRelayV2(item.owned.msg, item.wire, item.via_peer)) {
                .accepted => |id| {
                    _ = self.sendRelayV2AckToPeer(item.via_peer, id);
                    item.deinit(self.allocator);
                },
                .duplicate => |id| {
                    _ = self.sendRelayV2AckToPeer(item.via_peer, id);
                    item.deinit(self.allocator);
                },
                .permanent => item.deinit(self.allocator),
                .retry => |reason| if (!self.deferRelayV2(item, reason)) {
                    // Do not keep consuming a feed after the exact deferred
                    // authority is full. Closing forces retained sender replay;
                    // silently accepting or evicting would create an event gap.
                    item.deinit(self.allocator);
                    for (inbound[inbound_index + 1 ..]) |*later| later.deinit(self.allocator);
                    conn.closing = true;
                    self.traceLog(.err, .s2s, "MESSAGE_V2 deferred queue exhausted; closing peer feed");
                    return;
                },
            }
        }
    }

    /// Dedicated signed MESSAGE_V2 live path. All routing and policy resolution
    /// that can fail is completed before `admitRelayV2`; only its accepted
    /// RelayId authorizes tags, local fanout, projections, or exact-wire flood.
    fn deliverRelayV2(
        self: *LinuxServer,
        msg: message_relay_v2.RelayMessage,
        wire: []const u8,
        via_peer: u64,
    ) RelayV2DeliveryOutcome {
        if (!self.relayV2DirectNeighbor(via_peer)) return .permanent;
        message_relay_v2.validateSemantic(msg) catch return .permanent;
        // Lost ACKs are replayed against immutable authenticated identity, not
        // today's mutable route or policy state. Re-ack an exact retained
        // duplicate before target/session resolution; unseen events still run
        // every first-admission check below before RVG2 can advance.
        switch (self.probeRelayV2(msg, via_peer) catch return .{ .retry = .transient }) {
            .duplicate => |id| return if (self.retainRelayV2DuplicateIngress(
                id,
                wire,
                via_peer,
            ) catch return .{ .retry = .transient }) .{ .duplicate = id } else .permanent,
            .unseen => {},
            .equivocation,
            .retired,
            .origin_mismatch,
            .bad_signature,
            .invalid_semantic,
            => return .permanent,
        }
        const source_nick = msg.sourceNick() orelse return .permanent;
        if (!self.relayV2OriginKnown(msg)) return .{ .retry = .transient };
        const latest_physical = std.math.add(
            u64,
            self.meshWallMs(),
            mesh_clock_mod.default_max_future_skew_ms,
        ) catch std.math.maxInt(u64);
        if (mesh_clock_mod.MeshClock.physicalOf(msg.hlc) > latest_physical) return .{ .retry = .transient };
        var safe_tag_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
        const safe_tags = clientOnlyTags(msg.tags, &safe_tag_buf);
        const clean_msg = s2s_link.RelayMessage{
            .verb = msg.verb,
            .target = msg.target,
            .min_rank = msg.min_rank,
            .source_nick = source_nick,
            .source_prefix = msg.source_prefix,
            .account = msg.account,
            .tags = safe_tags,
            .text = msg.text,
            .data_tag = msg.data_tag,
            .recipient = msg.recipient,
            .origin_node = msg.origin_node,
            .hlc = msg.hlc,
            .origin_pubkey = msg.origin_pubkey,
            .origin_sig = msg.origin_sig,
        };

        const replica_proof = self.replicatedSessionProofV2(msg);
        // SESSION_REPLICA and MESSAGE_V2 may arrive in adjacent records. A
        // locally resident sender without its exact signed route proof is
        // unresolved authority, not a policy denial: retaining the immutable
        // wire lets the authority drain complete before RVG2 is consumed.
        if (msg.sender_route_id) |sender_route| {
            var sender_account_buf: [session_replica_account_max]u8 = undefined;
            const receiver_owns_route = self.localPortableSessionByRoute(
                sender_route,
                &sender_account_buf,
            ) != null;
            if (receiver_owns_route and replica_proof == null) return .{ .retry = .transient };
        }
        const signed_member_modes: ?world_model.MemberModes = if (msg.sender_member_modes) |bits|
            .{ .bits = bits }
        else
            null;
        // Roster rows are link-local, so a far receiver in A-B-C cannot know a
        // node-C direct sender's home. A signed, non-null sender route is the
        // origin's existing wire-compatible assertion that this event came
        // from one locally attached reusable session. It can bridge only an
        // absent roster claim; a known conflicting home remains a permanent
        // rejection below. Old peers continue to decode the exact same schema.
        const signed_direct_residence = msg.scope_kind == .direct and msg.sender_route_id != null;
        const sender_home = self.relaySenderHome(source_nick, msg.origin_node);
        // replica_proof is a portable session — it may override residence.
        // signed_member_modes is only the origin's assertion of mode bits: it
        // may skip the unknown-home retry (no residence yet), but must never
        // launder a known-home mismatch.
        if (replica_proof == null) {
            switch (sender_home) {
                .mismatch => |home| {
                    self.recordRelayHomeMismatch(clean_msg, home);
                    return .permanent;
                },
                .unknown => if (signed_member_modes == null and !signed_direct_residence)
                    return .{ .retry = .unknown_home_authority },
                .match => {},
            }
        }
        const local_sender_allowed = !(self.nickIsLiveLocal(source_nick) and replica_proof == null);
        const residence_account: ?[]const u8 = if (replica_proof == null)
            self.trustedRemoteAccountAtNode(source_nick, msg.origin_node)
        else
            null;
        const policy_account = if (replica_proof) |proof|
            proof.trusted_account
        else if (residence_account) |account|
            account
        else
            "";
        const is_data_family = switch (msg.verb) {
            .data, .request, .reply => true,
            else => false,
        };
        var recipient_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer recipient_ids.deinit(self.allocator);
        var sender_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer sender_ids.deinit(self.allocator);
        var exact_target: ?RelayV2ExactTarget = null;
        var speech: ChannelSpeechResult = .deny;
        var effective_text = msg.text;
        // Bound the strip buffer to the largest deliverable line body so an
        // oversized colour-formatted MESSAGE_V2 cannot fail the strip and fall
        // through with raw mIRC codes on a +f channel (CWE-400 / policy bypass).
        // Required-room ciphertext is validated on the original body first;
        // +f must never rewrite an admitted ONYXROOM1 envelope.
        var noformat_buf: [default_reply_bytes]u8 = undefined;
        var dm_key_buf: [320]u8 = undefined;
        var recipient_account_buf: [session_replica_account_max]u8 = undefined;
        var history_row: ?RelayV2History = null;

        if (replica_proof) |proof| {
            self.collectAttachedTokenAuthorityClients(
                proof.trusted_account,
                proof.token,
                &sender_ids,
            ) catch return .{ .retry = .transient };
        }

        switch (msg.scope_kind) {
            .channel => {
                // Topology is never channel-membership authority. A third-hop
                // origin signature proves authorship, not +n bypass rights;
                // only the separately authenticated webhook shape is external.
                const allow_external = self.isVerifiedWebhookRelay(clean_msg, .verified);
                if (self.world.channelHasFlag(msg.target, .no_external) and
                    !allow_external and replica_proof == null and signed_member_modes == null and
                    !self.remoteMemberOfChannelAtNode(msg.target, source_nick, msg.origin_node))
                {
                    // A membership burst can trail the immutable message on a
                    // newly converging multi-hop route. Do not turn missing
                    // receiver-owned membership authority into either a +n
                    // bypass or a consumed-and-lost denial.
                    return .{ .retry = .transient };
                }
                const effective_sender_modes = if (replica_proof) |proof|
                    proof.modes
                else
                    signed_member_modes orelse self.relaySenderModes(msg.target, source_nick);
                if (is_data_family and !self.remoteDataTagAuthorized(
                    msg.data_tag,
                    true,
                    effective_sender_modes,
                    policy_account,
                )) return .permanent;
                // DATA/REQUEST/REPLY stay on the pre-envelope contract: required
                // rooms only asked for a legacy e2ee tag, never ONYXROOM1 text.
                const e2ee_ok = if (is_data_family)
                    self.channelEncryptionPolicy(msg.target) != .required or
                        e2ee_policy.encryptedTagPresent(if (safe_tags.len != 0) safe_tags else null)
                else
                    self.messageSatisfiesEncryptionPolicy(
                        msg.target,
                        if (safe_tags.len != 0) safe_tags else null,
                        msg.text,
                        msg.verb == .tagmsg,
                    );
                const local_content_allowed = e2ee_ok and !(is_data_family and
                    self.world.channelHasExtFlag(msg.target, .nocomicdata) and
                    effective_sender_modes.rank() < 2);
                if (local_content_allowed and msg.verb != .tagmsg and !is_data_family and
                    self.channelEncryptionPolicy(msg.target) != .required and
                    self.world.channelHasExtFlag(msg.target, .noformat) and
                    color_strip.hasFormatting(msg.text))
                {
                    effective_text = color_strip.stripFormattingWith(
                        .{ .max_output_bytes = default_reply_bytes },
                        msg.text,
                        &noformat_buf,
                    ) catch msg.text;
                }
                if (local_sender_allowed and local_content_allowed) {
                    speech = self.relayChannelSpeechGate(
                        msg.target,
                        source_nick,
                        msg.source_prefix,
                        policy_account,
                        effective_text,
                        msg.verb == .notice,
                        msg.min_rank,
                        if (replica_proof) |proof| proof.modes else signed_member_modes,
                        allow_external,
                    );
                }
                if (speech != .deny and speech != .opmoderate and msg.min_rank == 0) {
                    const command: ?[]const u8 = switch (msg.verb) {
                        .privmsg => "PRIVMSG",
                        .notice => "NOTICE",
                        .tagmsg => if (tagmsgHistoryEligible(safe_tags)) "TAGMSG" else null,
                        else => null,
                    };
                    if (command) |history_command| history_row = .{
                        .target = msg.target,
                        .sender = msg.source_prefix,
                        .text = if (msg.verb == .tagmsg) "" else effective_text,
                        .command = history_command,
                        .client_tags = if (safe_tags.len != 0) safe_tags else null,
                        .timestamp_ms = mesh_clock_mod.MeshClock.physicalOf(msg.hlc),
                    };
                }
            },
            .direct => if (local_sender_allowed) {
                if (is_data_family and !self.remoteDataTagAuthorized(
                    msg.data_tag,
                    false,
                    null,
                    policy_account,
                )) return .permanent;
                const signed_route = msg.recipient_route_id orelse return .permanent;
                const target_resolution = self.collectRelayV2ExactTarget(
                    msg.target,
                    signed_route,
                    null,
                    &recipient_account_buf,
                    &recipient_ids,
                ) catch return .{ .retry = .transient };
                switch (target_resolution) {
                    .ready => |target| exact_target = target,
                    .pending => return .{ .retry = .transient },
                    .transit => {},
                }
                if (exact_target) |target| {
                    var index: usize = 0;
                    while (index < recipient_ids.items.len) {
                        if (self.relayDirectMessagePolicyBlocks(
                            clean_msg,
                            policy_account,
                            recipient_ids.items[index],
                        )) {
                            _ = recipient_ids.orderedRemove(index);
                        } else {
                            index += 1;
                        }
                    }
                    if (recipient_ids.items.len == 0) {
                        exact_target = null;
                        // Match the legacy policy invariant: a recipient-side
                        // SILENCE/+g/+C/+R denial also suppresses the author's
                        // exact-token sent copy on this node.
                        sender_ids.clearRetainingCapacity();
                    }
                    if (exact_target != null and msg.verb == .privmsg) {
                        const sender_account: ?[]const u8 = if (replica_proof) |proof|
                            proof.trusted_account
                        else
                            self.trustedRemoteAccountAtNode(source_nick, msg.origin_node);
                        if (sender_account) |sender| {
                            if (dmHistoryKey(source_nick, sender, msg.target, target.account, &dm_key_buf)) |key| {
                                history_row = .{
                                    .target = key,
                                    .sender = msg.source_prefix,
                                    .text = msg.text,
                                    .command = "PRIVMSG",
                                    .client_tags = if (safe_tags.len != 0) safe_tags else null,
                                    .timestamp_ms = mesh_clock_mod.MeshClock.physicalOf(msg.hlc),
                                };
                            }
                        }
                    }
                }
            },
            .channel_whisper => if (local_sender_allowed) {
                const signed_route = msg.recipient_route_id orelse return .permanent;
                const sender_member = replica_proof != null or signed_member_modes != null or
                    self.remoteMemberOfChannelAtNode(msg.target, source_nick, msg.origin_node);
                if (sender_member and !self.world.channelHasExtFlag(msg.target, .nowhisper)) {
                    const target_resolution = self.collectRelayV2ExactTarget(
                        msg.recipient,
                        signed_route,
                        msg.target,
                        &recipient_account_buf,
                        &recipient_ids,
                    ) catch return .{ .retry = .transient };
                    switch (target_resolution) {
                        .ready => |target| exact_target = target,
                        .pending => return .{ .retry = .transient },
                        .transit => {},
                    }
                }
            },
        }

        // Pre-render before authority publication. A locally unrenderable object
        // is rejected without consuming RVG2 so an upgraded implementation can
        // retry it; a pure-transit node uses the same bounded IRC grammar.
        const verb = msg.verb.commandWord();
        var render_target_buf: [128]u8 = undefined;
        const render_target = if (msg.scope_kind == .channel)
            if (statusRankPrefix(msg.min_rank)) |prefix|
                std.fmt.bufPrint(&render_target_buf, "{c}{s}", .{ prefix, msg.target }) catch
                    return .permanent
            else
                msg.target
        else
            msg.target;
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = if (msg.scope_kind == .channel_whisper)
            std.fmt.bufPrint(&line_buf, ":{s} WHISPER {s} {s} :{s}\r\n", .{
                msg.source_prefix, msg.target, msg.recipient, msg.text,
            }) catch return .permanent
        else if (msg.verb == .tagmsg)
            std.fmt.bufPrint(&line_buf, ":{s} TAGMSG {s}\r\n", .{
                msg.source_prefix, render_target,
            }) catch return .permanent
        else if (is_data_family)
            std.fmt.bufPrint(&line_buf, ":{s} {s} {s} {s} :{s}\r\n", .{
                msg.source_prefix, verb, render_target, msg.data_tag, effective_text,
            }) catch return .permanent
        else
            std.fmt.bufPrint(&line_buf, ":{s} {s} {s} :{s}\r\n", .{
                msg.source_prefix, verb, render_target, effective_text,
            }) catch return .permanent;

        // RelayId is a deterministic digest of the immutable signed object. Use
        // it to render the complete attachment batch before live RVG2 authority
        // moves; `admitMessage` below still performs the signature/origin checks
        // and must return the same identity before publication.
        const predicted_relay_id = message_relay_v2.relayId(self.allocator, msg) catch return .{ .retry = .transient };
        var msgid_buf: [msgid_mod.id_len]u8 = undefined;
        var time_buf: [40]u8 = undefined;
        const stable_msgid = msgid_mod.fromStableId(predicted_relay_id, &msgid_buf);
        const tags = MsgTags{
            .time_value = serverTimeValueAt(
                &time_buf,
                mesh_clock_mod.MeshClock.physicalOf(msg.hlc),
            ),
            .account = if (policy_account.len != 0) policy_account else null,
            .client_tags = safe_tags,
            .msgid = stable_msgid,
        };

        var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer delivery_ids.deinit(self.allocator);
        switch (msg.scope_kind) {
            .channel => if (speech != .deny) {
                if (self.world.memberIterator(msg.target)) |*iter| {
                    var members = iter.*;
                    const min_rank: u8 = if (speech == .opmoderate) 2 else msg.min_rank;
                    while (members.next()) |member| {
                        if (min_rank != 0) {
                            const modes = self.world.memberModes(msg.target, member.*) orelse continue;
                            if (modes.rank() < min_rank) continue;
                        }
                        const id = clientIdFromWorld(member.*);
                        if (msg.verb == .tagmsg) {
                            const target_conn = self.connFor(id) orelse continue;
                            var visible: [irc_line.max_client_tags_raw_len]u8 = undefined;
                            if (clientTagsForSession(&target_conn.session, safe_tags, &visible).len == 0) continue;
                        }
                        delivery_ids.append(self.allocator, id) catch return .{ .retry = .transient };
                    }
                }
            },
            .direct, .channel_whisper => {
                for (recipient_ids.items) |id| {
                    if (msg.verb == .tagmsg) {
                        const target_conn = self.connFor(id) orelse continue;
                        var visible: [irc_line.max_client_tags_raw_len]u8 = undefined;
                        if (clientTagsForSession(&target_conn.session, safe_tags, &visible).len == 0) continue;
                    }
                    delivery_ids.append(self.allocator, id) catch return .{ .retry = .transient };
                }
                for (sender_ids.items) |sender_id| {
                    var already_recipient = false;
                    for (recipient_ids.items) |recipient_id| if (sender_id.eql(recipient_id)) {
                        already_recipient = true;
                        break;
                    };
                    if (already_recipient) continue;
                    if (msg.verb == .tagmsg) {
                        const target_conn = self.connFor(sender_id) orelse continue;
                        var visible: [irc_line.max_client_tags_raw_len]u8 = undefined;
                        if (clientTagsForSession(&target_conn.session, safe_tags, &visible).len == 0) continue;
                    }
                    delivery_ids.append(self.allocator, sender_id) catch return .{ .retry = .transient };
                }
            },
        }
        var prepared_delivery = self.prepareAttachmentDeliveryBatch(
            delivery_ids.items,
            tags,
            line,
        ) catch return .{ .retry = .transient };
        defer prepared_delivery.deinit();

        const outbox_peers = self.collectRelayV2OutboxPeers(via_peer, true) catch return .{ .retry = .transient };
        defer self.allocator.free(outbox_peers);
        const outbox_reservation = RelayV2OutboxReservation{
            .peers = outbox_peers,
            .receipt_peer = via_peer,
            .wire = wire,
            .unbound_excluded_peer = via_peer,
        };
        const relay_id = switch (self.admitRelayV2Detailed(msg, history_row, outbox_reservation, &prepared_delivery) catch return .{ .retry = .transient }) {
            .accepted => |id| id,
            .duplicate => |id| return .{ .duplicate = id },
            .rejected => return .permanent,
        };
        std.debug.assert(std.mem.eql(u8, &relay_id, &predicted_relay_id));
        // The joint cut is published. Release the spool lane before the ordinary
        // fanout helpers encounter the now-exact-duplicate records and drain them.
        prepared_delivery.release();

        if (history_row) |row| {
            self.indexHistoryBody(stable_msgid, row.text, null);
            self.chanstatsMessage(row.target, row.sender, row.command, row.text);
        }

        switch (msg.scope_kind) {
            .channel => if (speech != .deny) {
                if (self.world.memberIterator(msg.target)) |*iter| {
                    var members = iter.*;
                    const min_rank: u8 = if (speech == .opmoderate) 2 else msg.min_rank;
                    while (members.next()) |member| {
                        if (min_rank != 0) {
                            const modes = self.world.memberModes(msg.target, member.*) orelse continue;
                            if (modes.rank() < min_rank) continue;
                        }
                        const id = clientIdFromWorld(member.*);
                        if (msg.verb == .tagmsg) {
                            const conn = self.connFor(id) orelse continue;
                            var visible: [irc_line.max_client_tags_raw_len]u8 = undefined;
                            if (clientTagsForSession(&conn.session, safe_tags, &visible).len == 0) continue;
                        }
                        self.deliverPreparedTagged(id, tags, line) catch {};
                    }
                }
            },
            .direct, .channel_whisper => {
                for (recipient_ids.items) |id| {
                    if (msg.verb == .tagmsg) {
                        const target_conn = self.connFor(id) orelse continue;
                        var visible: [irc_line.max_client_tags_raw_len]u8 = undefined;
                        if (clientTagsForSession(&target_conn.session, safe_tags, &visible).len == 0) continue;
                    }
                    self.deliverPreparedTagged(id, tags, line) catch {};
                }
            },
        }
        for (sender_ids.items) |sender_id| {
            var already_recipient = false;
            for (recipient_ids.items) |recipient_id| {
                if (sender_id.eql(recipient_id)) {
                    already_recipient = true;
                    break;
                }
            }
            if (already_recipient) continue;
            if (msg.scope_kind == .channel) {
                // Channel fanout above already visits every eligible physical
                // member, including all exact-token sender attachments. A
                // second sender-mirror delivery duplicates ordinary messages
                // and leaks denied/status/TAGMSG-invisible events.
                continue;
            }
            if (msg.verb == .tagmsg) {
                const target_conn = self.connFor(sender_id) orelse continue;
                var visible: [irc_line.max_client_tags_raw_len]u8 = undefined;
                if (clientTagsForSession(&target_conn.session, safe_tags, &visible).len == 0) continue;
            }
            self.deliverPreparedTagged(sender_id, tags, line) catch {};
        }
        self.forwardAcceptedRelayV2(wire);
        return .{ .accepted = relay_id };
    }

    /// Deliver an inbound legacy relayed user message to LOCAL recipients only.
    /// Multi-hop propagation is owned exclusively by accepted MESSAGE_V2 objects.
    fn deliverRelay(self: *LinuxServer, msg: s2s_link.RelayMessage) void {
        // Decode enforces this for wire traffic, but tests and in-process paths
        // can call deliverRelay directly. Keep the semantic trust boundary here
        // too, before signature work or dedup observation: no authenticated peer
        // may smuggle CR/LF/control bytes or an ambiguous prefix/tag/account into
        // a rendered IRC line, and an invalid frame cannot poison `(origin,hlc)`.
        message_relay.validateSemantic(msg) catch {
            self.recordRelaySignatureReject(msg, "unsafe relay semantics");
            return;
        };
        // End-to-end origin authentication at EVERY hop. A message that carries a
        // self-contained signature is verified against the CLAIMED origin (self-
        // certifying: the signing key must derive `origin_node`). On failure the
        // message is dropped here — never delivered, never re-forwarded — so a
        // relay cannot forge or tamper with an authored message. A message with
        // no signature follows the legacy (unsigned) path unchanged.
        const origin_auth = self.relayOriginAuth(msg) orelse return;
        // Authenticate BEFORE observing the dedup key. A forged frame must not be
        // able to poison `(origin, hlc)` and suppress the valid signed frame that
        // arrives on another mesh path later.
        const already_seen = switch (origin_auth) {
            .verified => self.relay_seen.observe(msg.origin_node, msg.hlc),
            .unsigned => self.relay_seen.observeUnsigned(msg.origin_node, msg.hlc),
        };
        if (already_seen) return;
        const source_nick = relaySourceNickFromPrefix(msg.source_prefix) orelse {
            self.recordRelaySignatureReject(msg, "source prefix has no nick");
            return;
        };
        var safe_tag_buf: [256]u8 = undefined;
        const safe_tags = clientOnlyTags(msg.tags, &safe_tag_buf);
        const clean_msg = s2s_link.RelayMessage{
            .verb = msg.verb,
            .target = msg.target,
            .min_rank = msg.min_rank,
            .source_nick = source_nick,
            .source_prefix = msg.source_prefix,
            .account = msg.account,
            .tags = safe_tags,
            .text = msg.text,
            .data_tag = msg.data_tag,
            .recipient = msg.recipient,
            .origin_node = msg.origin_node,
            .hlc = msg.hlc,
            // Preserve the ORIGINAL author's signature verbatim so a 3rd-hop node
            // re-verifies the true origin, not this relay. `tags` is sanitized
            // above (server-stamped msgid / client-tag filtered) but is NOT a
            // signed field, so the carried signature stays valid downstream.
            .origin_pubkey = msg.origin_pubkey,
            .origin_sig = msg.origin_sig,
        };
        const replica_proof = if (origin_auth == .verified)
            self.replicatedSessionProof(
                clean_msg.origin_node,
                clean_msg.source_nick,
                if (world_model.isChannelName(clean_msg.target)) clean_msg.target else null,
            )
        else
            null;
        // WHISPER is nick-scoped within a shared channel; it never fans out to all
        // channel members, so it follows a dedicated inbound path below.
        if (clean_msg.verb == .whisper) {
            self.deliverRelayWhisper(clean_msg, replica_proof);
            return;
        }
        const verb = clean_msg.verb.commandWord();
        const is_data_family = switch (clean_msg.verb) {
            .data, .request, .reply => true,
            else => false,
        };
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = if (clean_msg.verb == .tagmsg)
            std.fmt.bufPrint(&line_buf, ":{s} TAGMSG {s}\r\n", .{ clean_msg.source_prefix, clean_msg.target }) catch return
        else if (is_data_family)
            // IRCX typed line: `:prefix <CMD> <target> <data_tag> :<text>`.
            std.fmt.bufPrint(&line_buf, ":{s} {s} {s} {s} :{s}\r\n", .{ clean_msg.source_prefix, verb, clean_msg.target, clean_msg.data_tag, clean_msg.text }) catch return
        else
            std.fmt.bufPrint(&line_buf, ":{s} {s} {s} :{s}\r\n", .{ clean_msg.source_prefix, verb, clean_msg.target, clean_msg.text }) catch return;
        var time_buf: [40]u8 = undefined;
        var msgid_buf: [msgid_mod.id_len]u8 = undefined;
        const stable_event_identity = origin_auth == .verified and clean_msg.hlc != 0;
        const replica_modes: ?world_model.MemberModes = if (replica_proof) |proof| proof.modes else null;
        // For a portable sibling, every account-sensitive local decision uses
        // the Store-derived account. The relay-v1 account field remains mutable
        // hop data and cannot become authority merely because origin signed the
        // distinct prefix transcript.
        const residence_account: ?[]const u8 = if (origin_auth == .verified and replica_proof == null)
            self.trustedRemoteAccountAtNode(clean_msg.source_nick, clean_msg.origin_node)
        else
            null;
        const policy_account = if (replica_proof) |proof|
            proof.trusted_account
        else if (residence_account) |account|
            account
        else
            "";
        const target_is_channel = world_model.isChannelName(clean_msg.target);
        const effective_remote_modes: ?world_model.MemberModes = if (target_is_channel)
            replica_modes orelse self.relaySenderModes(clean_msg.target, clean_msg.source_nick)
        else
            null;
        if (is_data_family and !self.remoteDataTagAuthorized(
            clean_msg.data_tag,
            target_is_channel,
            effective_remote_modes,
            policy_account,
        )) return;
        const relay_tags = MsgTags{
            .time_value = if (stable_event_identity)
                serverTimeValueAt(&time_buf, mesh_clock_mod.MeshClock.physicalOf(clean_msg.hlc))
            else
                serverTimeValue(&time_buf),
            .account = if (policy_account.len != 0) policy_account else null,
            .client_tags = clean_msg.tags,
            .msgid = if (stable_event_identity)
                msgid_mod.fromMeshEvent(clean_msg.origin_node, clean_msg.hlc, &msgid_buf)
            else
                self.msgid_gen.next(&msgid_buf),
        };

        const verified_webhook = self.isVerifiedWebhookRelay(clean_msg, origin_auth);
        const verified_multihop_membership = relayOriginAttestsExternalMembership(
            origin_auth,
            self.relayOriginIsDirectPeer(clean_msg.origin_node),
        );

        // Origin spoof guard: a relayed message must never be RENDERED locally as a
        // nick that is live & local on THIS node — UNLESS it is the SAME account.
        // Multi-client / one-nick is by design: `kain` may be live on this node and
        // on a peer at once (same authenticated account), so a relayed line from that
        // sibling session is legitimate and must be delivered (so the user's other
        // devices + co-channel members see it). Only a DIFFERENT account asserting a
        // local nick's prefix is a real spoof. Legacy MESSAGE is a terminal
        // compatibility leaf; only MESSAGE_V2 may re-flood across the mesh.
        if (self.nickIsLiveLocal(clean_msg.source_nick) and replica_proof == null) {
            return;
        }

        // Sender-identity binding: a keyed-but-Byzantine peer can deliberately
        // SIGN a `source_prefix` that renders another node's user's nick. The
        // standalone `source_nick` field is unsigned but ignored above (we derive
        // it from the signed prefix). `account`, `tags`, and `min_rank` are also
        // unsigned/hop-mutable and cannot establish nick ownership.
        // Legacy v1 is fail-closed on sender-home uncertainty unless a signed
        // portable proof supplies authority or the self-certifying origin has
        // authored the daemon's exact synthetic webhook identity.
        if (replica_modes == null and !verified_webhook) {
            switch (self.relaySenderHome(clean_msg.source_nick, clean_msg.origin_node)) {
                .match => {},
                .mismatch => |home| {
                    self.recordRelayHomeMismatch(clean_msg, home);
                    return;
                },
                .unknown => {
                    self.recordRelayUnknownHomeV1(clean_msg);
                    return;
                },
            }
        }

        if (world_model.isChannelName(clean_msg.target)) {
            // Receiver-side defense-in-depth: re-enforce THIS node's channel
            // policy (+n/+m/+M/+b/+Z) against the REMOTE sender before delivering
            // to local members. A mode/ban that has desynced across the mesh (or
            // a hostile/buggy peer) must not let a remote actor bypass local
            // policy. Channels without those flags always deliver.
            // Typed DATA/REQUEST/REPLY never used the room-text pairing; keep
            // the legacy relay path ungated so comic-chat frames still fan out.
            if (!is_data_family and !self.messageSatisfiesEncryptionPolicy(
                clean_msg.target,
                if (clean_msg.tags.len != 0) clean_msg.tags else null,
                clean_msg.text,
                clean_msg.verb == .tagmsg,
            )) return;
            const speech = self.relayChannelSpeechGate(
                clean_msg.target,
                clean_msg.source_nick,
                clean_msg.source_prefix,
                policy_account,
                clean_msg.text,
                clean_msg.verb == .notice,
                clean_msg.min_rank,
                replica_modes,
                verified_webhook or verified_multihop_membership,
            );
            if (speech == .deny) {
                return;
            }
            var target_buf: [128]u8 = undefined;
            const render_target = if (statusRankPrefix(clean_msg.min_rank)) |prefix|
                std.fmt.bufPrint(&target_buf, "{c}{s}", .{ prefix, clean_msg.target }) catch clean_msg.target
            else
                clean_msg.target;
            var eff_text = clean_msg.text;
            var nf_text_buf: [default_reply_bytes]u8 = undefined;
            // +V NOCOMICDATA: re-enforce the local channel's comic-chat-DATA ban
            // against a remote sender (the local handleData rejects non-op DATA
            // here with 531; on the receive side we silently drop).
            if (is_data_family and self.world.channelHasExtFlag(clean_msg.target, .nocomicdata) and
                (replica_modes orelse self.relaySenderModes(clean_msg.target, clean_msg.source_nick)).rank() < 2)
            {
                return;
            }
            if (clean_msg.verb != .tagmsg and !is_data_family and
                self.channelEncryptionPolicy(clean_msg.target) != .required and
                self.world.channelHasExtFlag(clean_msg.target, .noformat) and
                color_strip.hasFormatting(clean_msg.text))
            {
                if (color_strip.stripFormattingWith(.{ .max_output_bytes = default_reply_bytes }, clean_msg.text, &nf_text_buf)) |clean|
                    eff_text = clean
                else |_| {}
            }
            var channel_line_buf: [default_reply_bytes]u8 = undefined;
            const channel_line = if (clean_msg.verb == .tagmsg)
                std.fmt.bufPrint(&channel_line_buf, ":{s} TAGMSG {s}\r\n", .{ clean_msg.source_prefix, render_target }) catch return
            else if (is_data_family)
                std.fmt.bufPrint(&channel_line_buf, ":{s} {s} {s} {s} :{s}\r\n", .{ clean_msg.source_prefix, verb, render_target, clean_msg.data_tag, eff_text }) catch return
            else
                std.fmt.bufPrint(&channel_line_buf, ":{s} {s} {s} :{s}\r\n", .{ clean_msg.source_prefix, verb, render_target, eff_text }) catch return;
            if (self.world.memberIterator(clean_msg.target)) |*it| {
                var members = it.*;
                if (speech == .opmoderate or clean_msg.min_rank > 0) {
                    const min_rank = if (speech == .opmoderate) 2 else clean_msg.min_rank;
                    while (members.next()) |member| {
                        const mm = self.world.memberModes(clean_msg.target, member.*) orelse continue;
                        if (mm.rank() < min_rank) continue;
                        const mid = clientIdFromWorld(member.*);
                        if (clean_msg.verb == .tagmsg) {
                            const mconn = self.connFor(mid) orelse continue;
                            var visible_tags_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
                            if (clientTagsForSession(&mconn.session, clean_msg.tags, &visible_tags_buf).len == 0) continue;
                        }
                        self.deliverTagged(mid, relay_tags, channel_line) catch {};
                    }
                } else {
                    while (members.next()) |member| {
                        const mid = clientIdFromWorld(member.*);
                        if (clean_msg.verb == .tagmsg) {
                            const mconn = self.connFor(mid) orelse continue;
                            var visible_tags_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
                            if (clientTagsForSession(&mconn.session, clean_msg.tags, &visible_tags_buf).len == 0) continue;
                        }
                        self.deliverTagged(mid, relay_tags, channel_line) catch {};
                    }
                }
            }
            // Record the incoming relayed channel message into the CHATHISTORY
            // ring so cross-node CHATHISTORY works: a member reading back on THIS
            // node sees messages authored on a peer, not just locally-originated
            // ones. Gated exactly like the locally-originated record path
            // (`min_rank == 0`, general delivery only): opmoderate / status-
            // prefixed messages are not recorded, and TAGMSG / data-family ride
            // their own history mechanisms. Locally-originated messages never
            // reach here — the relay seen-set drops our own origin_node above.
            if (clean_msg.min_rank == 0 and speech != .opmoderate) {
                if (relay_tags.msgid) |rid| {
                    switch (clean_msg.verb) {
                        .privmsg, .notice => if (stable_event_identity)
                            self.recordHistoryRelayAt(clean_msg.target, clean_msg.source_prefix, rid, verb, eff_text, if (clean_msg.tags.len != 0) clean_msg.tags else null, mesh_clock_mod.MeshClock.physicalOf(clean_msg.hlc))
                        else
                            self.recordHistoryRelay(clean_msg.target, clean_msg.source_prefix, rid, verb, eff_text, if (clean_msg.tags.len != 0) clean_msg.tags else null),
                        .tagmsg => if (tagmsgHistoryEligible(clean_msg.tags)) {
                            if (stable_event_identity)
                                self.recordHistoryRelayAt(clean_msg.target, clean_msg.source_prefix, rid, "TAGMSG", "", clean_msg.tags, mesh_clock_mod.MeshClock.physicalOf(clean_msg.hlc))
                            else
                                self.recordHistoryRelay(clean_msg.target, clean_msg.source_prefix, rid, "TAGMSG", "", clean_msg.tags);
                        },
                        else => {},
                    }
                }
            }
        } else {
            var recipient_id: ?client_model.ClientId = null;
            var recipient_account: ?[]const u8 = null;
            var recipient_token: ?sessions_mod.Token = null;
            var sender_copy_allowed = true;
            var recipient_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer recipient_ids.deinit(self.allocator);
            var sender_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer sender_ids.deinit(self.allocator);
            if (self.world.findNick(clean_msg.target)) |wid| {
                recipient_id = clientIdFromWorld(wid);
                if (self.relayDirectMessagePolicyBlocks(clean_msg, policy_account, recipient_id.?)) {
                    // Match the origin-local policy path: SILENCE/+g/+C/+R blocks
                    // both recipient delivery and the author's sibling sent-copy.
                    sender_copy_allowed = false;
                } else {
                    if (self.connFor(recipient_id.?)) |rconn| {
                        recipient_account = rconn.session.account();
                        self.collectAttachedExactTokenClients(recipient_id.?, rconn, &recipient_ids) catch return;
                        if (recipient_account) |account| {
                            if (self.sessions.resumeHandleForClient(account, monitorIdFromClient(recipient_id.?))) |handle| {
                                if (!tokenIsNull(handle.token)) recipient_token = handle.token;
                            }
                        }
                    } else {
                        recipient_ids.append(self.allocator, recipient_id.?) catch return;
                    }
                }
            }

            // Sender sent-copy mirror: a relay may reach this peer solely through
            // the author's authenticated portable-session route, even when the DM
            // target is not local. Exact token identity, not account/nick affinity,
            // selects that mandatory sent-copy set.
            if (sender_copy_allowed) {
                if (replica_proof) |proof| {
                    const sender_is_recipient_token = if (recipient_token) |token|
                        (if (recipient_account) |account|
                            std.ascii.eqlIgnoreCase(account, proof.trusted_account)
                        else
                            false) and std.crypto.timing_safe.eql(sessions_mod.Token, token, proof.token)
                    else
                        false;
                    if (!sender_is_recipient_token)
                        self.collectAttachedTokenAuthorityClients(proof.trusted_account, proof.token, &sender_ids) catch return;
                }
            }

            // Both complete sets were snapshotted before the first delivery.
            // Congestion/closure of one transport is isolated from every sibling.
            for (recipient_ids.items) |logical_id| self.deliverTagged(logical_id, relay_tags, line) catch {};
            for (sender_ids.items) |logical_id| self.deliverTagged(logical_id, relay_tags, line) catch {};
            const sender_is_recipient_account = if (replica_proof) |proof|
                if (recipient_account) |account| std.ascii.eqlIgnoreCase(proof.trusted_account, account) else false
            else
                false;
            if (sender_copy_allowed and sender_is_recipient_account) {
                if (replica_proof) |proof| self.deliverSessionSyncSiblingsNick(
                    proof.trusted_account,
                    recipient_token,
                    proof.token,
                    relay_tags,
                    line,
                    recipient_id,
                    null,
                    clean_msg.target,
                    clean_msg.source_nick,
                );
            } else if (sender_copy_allowed) {
                if (recipient_account) |account| self.deliverSessionSyncSiblingsNick(
                    account,
                    recipient_token,
                    null,
                    relay_tags,
                    line,
                    recipient_id,
                    null,
                    clean_msg.target,
                    null,
                );
                if (replica_proof) |proof| self.deliverSessionSyncSiblingsNick(
                    proof.trusted_account,
                    proof.token,
                    null,
                    relay_tags,
                    line,
                    recipient_id,
                    null,
                    clean_msg.source_nick,
                    null,
                );
            }

            // Store a remote PRIVMSG under the same account-canonical DM key the
            // origin uses, but only when BOTH identities are locally proven. The
            // recipient account comes from the local session. The sender account
            // comes either from an authenticated portable-replica route or from a
            // residence-verified roster row bound to the signed-prefix nick and
            // origin node. The relay's mutable `account` field alone never creates
            // or selects `$dm:acct` history; ambiguity/missing proof skips storage.
            if (clean_msg.verb == .privmsg and origin_auth == .verified) {
                const sender_account: ?[]const u8 = if (replica_proof) |proof|
                    proof.trusted_account
                else
                    self.trustedRemoteAccountAtNode(clean_msg.source_nick, clean_msg.origin_node);
                if (sender_account) |sa| if (recipient_account) |ra| if (relay_tags.msgid) |rid| {
                    var dm_key_buf: [320]u8 = undefined;
                    if (dmHistoryKey(clean_msg.source_nick, sa, clean_msg.target, ra, &dm_key_buf)) |store_target| {
                        const history_tags: ?[]const u8 = if (clean_msg.tags.len != 0) clean_msg.tags else null;
                        if (stable_event_identity)
                            self.recordHistoryRelayAt(store_target, clean_msg.source_prefix, rid, "PRIVMSG", clean_msg.text, history_tags, mesh_clock_mod.MeshClock.physicalOf(clean_msg.hlc))
                        else
                            self.recordHistoryRelay(store_target, clean_msg.source_prefix, rid, "PRIVMSG", clean_msg.text, history_tags);
                    }
                };
            }
        }
        // Legacy MESSAGE is local-delivery-only. Multi-hop propagation is owned
        // exclusively by accepted MESSAGE_V2 exact-wire forwarding.
    }

    /// Inbound IRCX WHISPER relay: deliver a `:prefix WHISPER <channel>
    /// <recipient> :<text>` line to the LOCAL recipient nick when it shares the
    /// channel, re-enforcing the same membership invariant the local handler does
    /// (both sender and recipient must be on the channel). The global seen-set is
    /// already observed by the caller (`deliverRelay`).
    fn deliverRelayWhisper(
        self: *LinuxServer,
        msg: s2s_link.RelayMessage,
        replica_proof: ?ReplicatedSessionProof,
    ) void {
        // Origin spoof guard: a peer must not assert a prefix for a nick that is
        // live & local here — UNLESS it is the SAME account (a legitimate
        // multi-client / one-nick sibling on a peer; see deliverRelay).
        if (self.nickIsLiveLocal(msg.source_nick) and replica_proof == null) {
            return;
        }
        // Sender-identity binding (see deliverRelay): enforce known-home match and
        // fail closed on unknown residence without signed portable proof.
        if (replica_proof == null) {
            switch (self.relaySenderHome(msg.source_nick, msg.origin_node)) {
                .match => {},
                .mismatch => |home| {
                    self.recordRelayHomeMismatch(msg, home);
                    return;
                },
                .unknown => {
                    self.recordRelayUnknownHomeV1(msg);
                    return;
                },
            }
        }
        // WHISPER is stricter than ordinary channel speech: both endpoints must
        // share the named channel even when +n is unset. A valid relay signature
        // authenticates the authoring node, but does not by itself prove that the
        // signed-prefix nick joined this channel. Accept only either the exact
        // signed portable-session snapshot proved by `replica_proof`, or a
        // converged membership row whose authenticated origin is the message's
        // signed origin. A same-nick row homed on another node is never enough.
        if (replica_proof == null and !self.remoteMemberOfChannelAtNode(msg.target, msg.source_nick, msg.origin_node)) {
            return;
        }
        // Re-enforce +w NOWHISPER against the remote sender (receiver-side
        // defense-in-depth; a desynced flag must not let a remote bypass policy).
        if (self.world.channelExists(msg.target) and self.world.channelHasExtFlag(msg.target, .nowhisper)) {
            return;
        }
        if (self.world.findNick(msg.recipient)) |rwid| {
            // WHISPER invariant: the recipient must be on the shared channel.
            if (self.world.isMember(msg.target, rwid)) {
                var line_buf: [default_reply_bytes]u8 = undefined;
                if (std.fmt.bufPrint(&line_buf, ":{s} WHISPER {s} {s} :{s}\r\n", .{ msg.source_prefix, msg.target, msg.recipient, msg.text })) |line| {
                    self.deliver(clientIdFromWorld(rwid), line) catch {};
                } else |_| {}
            }
        }
        // Terminal legacy leaf: no re-forward.
    }

    /// Acquire the connection's single RECV ownership reference. Every recv SQE
    /// in this server passes through here so close/finalization has one exact
    /// latch to consult.
    fn armRecv(self: *LinuxServer, conn: *ConnState) !void {
        if (self.rx().socket_io_quiescing or conn.recv_armed or conn.closing or tlsControlWaiting(conn)) return;
        io_backend.submitRecv(&self.rx().ring, conn.token, conn.fd, &conn.recv_buf) catch |err| {
            if (err == error.SubmissionQueueFull) {
                conn.io_activation_pending = true;
                conn.activation_recv_required = true;
                self.wakeReactor();
                return;
            }
            return err;
        };
        conn.recv_armed = true;
    }

    /// Acquire the connection's single CONNECT ownership reference. The address
    /// lives inline in ConnState and therefore remains stable until the matching
    /// exact-generation completion clears `connect_armed`.
    fn armConnect(self: *LinuxServer, conn: *ConnState) !void {
        if (self.rx().socket_io_quiescing or conn.connect_armed or conn.closing) return;
        if (!conn.s2s_initiator or !conn.s2s_dial_target_known) return error.InvalidAddress;
        try self.rx().ring.submitConnect(
            conn.token,
            conn.fd,
            @ptrCast(&conn.s2s_connect_addr),
            @sizeOf(posix.sockaddr.in6),
        );
        conn.connect_armed = true;
    }

    /// One eligibility rule for the armer and activation scheduler. Reserved
    /// control credit and a new-epoch kernel suffix are not sendable wire while
    /// the old-key reply is waiting. Genuine SQ pressure remains retryable work.
    fn tlsAllowsQueuedWire(conn: *const ConnState) bool {
        if (conn.tls_alert_pending) return false;
        if (conn.tls) |t| {
            if (t.tx_ku_reply_pending or (conn.tls_tx_offloaded and
                (t.control_phase == .userspace_requested_ku_held or t.control_phase == .kernel_control_read_held) and
                conn.tls_kernel_prefix_remaining == 0)) return false;
        }
        return true;
    }

    pub fn armSendIfNeeded(self: *LinuxServer, conn: *ConnState) !void {
        try self.progressTlsControl(conn);
        if (!tlsAllowsQueuedWire(conn)) return;
        if (comptime builtin.is_test) {
            if (conn.test_sendq_capture) {
                std.debug.assert(conn.fd < 0);
                return;
            }
        }
        if (self.rx().socket_io_quiescing or conn.send_armed) return;
        // A whole prepared TLS batch may enter overflow while inline storage
        // is empty. Only the owner may refill, after any armed SEND releases its
        // buffer; the empty-inline fast return must not strand accepted wire.
        if (conn.send_offset >= conn.send_len and conn.send_overflow.items.len != 0)
            refillFromOverflow(conn);
        if (conn.send_offset >= conn.send_len) return;
        // A staged activation that still owes RECV must acquire that ownership
        // first. This keeps inherited secured-link replay/burst helpers inert
        // even though they normally arm output as they append it.
        if (!conn.closing and conn.io_activation_pending and conn.activation_recv_required and !conn.recv_armed) return;
        var submitted_len = conn.send_len - conn.send_offset;
        if (conn.tls_tx_offloaded) {
            submitted_len = @min(submitted_len, tls_record.max_plaintext_len);
            if (conn.tls.?.control_phase == .userspace_requested_ku_held or conn.tls.?.control_phase == .kernel_control_read_held)
                submitted_len = @intCast(@min(submitted_len, conn.tls_kernel_prefix_remaining));
        }
        if (submitted_len == 0) return;
        io_backend.submitSend(&self.rx().ring, conn.token, conn.fd, conn.send_buf[conn.send_offset..][0..submitted_len]) catch |err| {
            if (err == error.SubmissionQueueFull) {
                conn.io_activation_pending = true;
                conn.activation_recv_required = !tlsControlWaiting(conn) and (conn.activation_recv_required or (!conn.recv_armed and !conn.closing));
                self.wakeReactor();
                return;
            }
            return err;
        };
        conn.send_submitted_len = submitted_len;
        conn.send_submitted_offset = conn.send_offset;
        conn.send_armed = true;
    }

    /// A healthy drain-close retains every accepted output domain, including
    /// software plaintext waiting for retryable preparation and a KU obligation.
    /// Terminal failure disposes those domains explicitly before finalization.
    fn hasUnsentOutput(conn: *const ConnState) bool {
        if (conn.send_armed or sendq.wireBacklog(conn) != 0 or conn.tls_alert_pending or
            conn.tls_deferred_plain.items.len != 0 or conn.tls_deferred_charge != 0 or
            conn.tls_control_charge != 0 or conn.tls_kernel_prefix_remaining != 0) return true;
        if (conn.tls) |t| if (!conn.tls_terminal_failure and
            (t.control_phase != .none or t.tx_ku_reply_pending or t.unpublished.items.len != 0)) return true;
        return false;
    }

    inline fn kernelOwnsConnStorage(conn: *const ConnState) bool {
        return conn.recv_armed or conn.send_armed or conn.connect_armed;
    }

    fn hasPendingSocketActivation(self: *LinuxServer) bool {
        for (self.rx().clients.slots.items) |*slot| {
            if (slot.occupied and (slot.value.io_activation_pending or slot.value.connect_rearm_pending or tlsControlWaiting(&slot.value))) return true;
        }
        return false;
    }

    /// Fairly activate inert Helix-adopted sockets without starving the control
    /// SQEs that make the loop progress. Partial activation is safe: each acquired
    /// op has its ownership bit, and the slot remains pending until all required
    /// ops are armed. A quiet remainder is nudged through the eventfd wake.
    fn activatePendingSocketIo(self: *LinuxServer) !bool {
        self.world.lockWrite();
        defer self.world.unlockWrite();
        return self.activatePendingSocketIoLocked();
    }

    /// Activation may release authenticated TLS/WS commands and finalize rows.
    /// Hold the same outer graph exclusion as a completion for the whole turn;
    /// progress/armer helpers must not reacquire this nonrecursive lock.
    fn activatePendingSocketIoLocked(self: *LinuxServer) !bool {
        const slots = self.rx().clients.slots.items;
        if (slots.len == 0) return false;

        const budget = @max(@as(usize, 1), @min(@as(usize, 16), @as(usize, self.config.ring_entries) / 2));
        var acquired: usize = 0;
        var scanned: usize = 0;
        var index = self.rx().activation_cursor % slots.len;
        while (scanned < slots.len) : (scanned += 1) {
            const slot = &slots[index];
            if (slot.occupied and (slot.value.io_activation_pending or slot.value.connect_rearm_pending or tlsControlWaiting(&slot.value))) {
                const conn = &slot.value;
                try self.progressTlsControl(conn);
                // A canceled outbound dial must reacquire CONNECT before any
                // RECV/SEND can be staged. Keep it in the same fair cursor as
                // inherited socket activation so SQ pressure cannot orphan it.
                if (conn.connect_rearm_pending and !conn.closing) {
                    self.armConnect(conn) catch |err| switch (err) {
                        error.SubmissionQueueFull => {
                            self.rx().activation_cursor = index;
                            self.wakeReactor();
                            return true;
                        },
                        else => return err,
                    };
                    if (!conn.connect_armed) {
                        self.rx().activation_cursor = index;
                        self.wakeReactor();
                        return true;
                    }
                    conn.connect_rearm_pending = false;
                    conn.io_activation_pending = false;
                    conn.activation_recv_required = false;
                    acquired += 1;
                    index = (index + 1) % slots.len;
                    self.rx().activation_cursor = index;
                    if (acquired >= budget) return self.hasPendingSocketActivation();
                    continue;
                }
                if (conn.connect_rearm_pending and conn.closing) {
                    conn.connect_rearm_pending = false;
                    conn.io_activation_pending = true;
                    conn.activation_recv_required = false;
                }
                if (conn.closing and !hasUnsentOutput(conn) and !kernelOwnsConnStorage(conn)) {
                    const token = conn.token;
                    conn.io_activation_pending = false;
                    conn.activation_recv_required = false;
                    index = (index + 1) % slots.len;
                    self.rx().activation_cursor = index;
                    self.closeConn(token, conn.close_reason) catch {};
                    continue;
                }
                if (tlsControlWaiting(conn)) conn.activation_recv_required = false;
                if (!conn.closing and conn.activation_recv_required and !conn.recv_armed) {
                    try self.armRecv(conn);
                    if (!conn.recv_armed) {
                        self.rx().activation_cursor = index;
                        self.wakeReactor();
                        return true;
                    }
                    acquired += 1;
                }
                const recv_ready = conn.closing or !conn.activation_recv_required or conn.recv_armed;
                if (recv_ready and
                    tlsAllowsQueuedWire(conn) and sendq.wireBacklog(conn) != 0 and !conn.send_armed)
                {
                    try self.armSendIfNeeded(conn);
                    if (!conn.send_armed) {
                        self.rx().activation_cursor = index;
                        self.wakeReactor();
                        return true;
                    }
                    acquired += 1;
                }
                if (recv_ready and
                    (sendq.wireBacklog(conn) == 0 or conn.send_armed))
                {
                    conn.io_activation_pending = tlsControlWaiting(conn);
                    conn.activation_recv_required = false;
                }
            }

            index = (index + 1) % slots.len;
            self.rx().activation_cursor = index;
            if (acquired >= budget) {
                const more = self.hasPendingSocketActivation();
                if (more) self.wakeReactor();
                return more;
            }
        }
        return self.hasPendingSocketActivation();
    }

    fn connForToken(self: *LinuxServer, token: RingFdToken) ServerError!*ConnState {
        return self.rx().clients.get(idFromToken(token)) orelse error.ClientNotFound;
    }

    /// Apply server-injected per-session state on a freshly accepted client
    /// before it can negotiate: the SASL verifiers (PLAIN fat-pointer checker;
    /// SCRAM additionally needs a per-connection CSPRNG hex server nonce —
    /// printable + comma-free per the SCRAM grammar) and the STS policy (so the
    /// `sts` cap is advertised on CAP LS when an operator enabled it).
    fn injectSessionState(self: *LinuxServer, conn: *ConnState) void {
        conn.session.configureMultiline(self.config.multiline_max_bytes, self.config.multiline_max_lines) catch {};
        if (!self.config.sasl_enabled) {
            if (self.config.sts_value) |v| conn.session.enableSts(v) catch {};
            return;
        }
        if (self.config.sasl_checker) |chk| conn.session.sasl_plain = chk;
        // TOTP second-factor gate: lets the SASL completion path refuse a
        // knowledge-factor login (PLAIN/SCRAM) for a 2FA-active account.
        conn.session.sasl_totp_gate = .{ .ptr = self, .activeFn = totpGateActive };
        // Account-status gate: refuses a SUSPENDED or FORBIDDEN account at SASL
        // success even when the mechanism verified (closes the SCRAM/OAUTHBEARER
        // status-bypass on the CAP AUTHENTICATE path).
        conn.session.sasl_account_gate = .{ .ptr = self, .blockedFn = accountStatusGateBlocked };
        conn.session.sasl_account_known = .{ .ptr = self, .knownFn = accountKnownGateKnown };
        // SCRAM (both digests) needs a per-connection server nonce. Generate it
        // once if either SCRAM lookup is configured, then attach whichever
        // lookups are present so SCRAM-SHA-256 and SCRAM-SHA-512 share the nonce.
        if (self.config.sasl_scram256 != null or self.config.sasl_scram512 != null) {
            if (self.config.crypto_io) |io| {
                var raw: [16]u8 = undefined;
                io.random(&raw);
                var hex: [32]u8 = undefined;
                const charset = "0123456789abcdef";
                for (raw, 0..) |b, i| {
                    hex[i * 2] = charset[b >> 4];
                    hex[i * 2 + 1] = charset[b & 0x0f];
                }
                conn.session.setSaslServerNonce(&hex);
                if (self.config.sasl_scram256) |scram| conn.session.sasl_scram256 = scram;
                if (self.config.sasl_scram512) |scram| conn.session.sasl_scram512 = scram;
            }
        }
        if (self.config.sts_value) |v| conn.session.enableSts(v) catch {};
        if (self.config.sasl_external) |ext| conn.session.sasl_external = ext;
        if (self.config.sasl_session_token) |tok| conn.session.sasl_session_token = tok;
        if (self.config.sasl_oauthbearer) |oauth| conn.session.sasl_oauthbearer = oauth;
        conn.session.sasl_allow_anonymous = self.config.sasl_allow_anonymous;
        conn.session.sasl_oauth_auto_provision = self.config.sasl_oauth_auto_provision;
        conn.session.sasl_decode_max_bytes = @min(@as(usize, self.config.sasl_decode_max_bytes), sasl_mechrouter.MAX_RAW_MESSAGE);
    }

    fn retainCloseReason(conn: *ConnState, reason: []const u8) void {
        const len = @min(reason.len, conn.close_reason_store.len);
        if (reason.ptr != @as([*]const u8, @ptrCast(&conn.close_reason_store[0])))
            @memcpy(conn.close_reason_store[0..len], reason[0..len]);
        conn.close_reason = conn.close_reason_store[0..len];
    }

    fn cancelWindowsClosingIo(self: *LinuxServer, conn: *ConnState) void {
        if (comptime builtin.os.tag != .windows) return;
        const ring = &self.rx().ring;
        if (conn.recv_armed and !conn.recv_cancel_pending) {
            if (io_backend.submitCancel(ring, .recv, conn.token)) |_| {
                conn.recv_cancel_pending = true;
            } else |err| {
                if (err == error.SubmissionQueueFull) self.wakeReactor();
            }
        }
        if (conn.send_armed and !conn.send_cancel_pending) {
            if (io_backend.submitCancel(ring, .send, conn.token)) |_| {
                conn.send_cancel_pending = true;
            } else |err| {
                if (err == error.SubmissionQueueFull) self.wakeReactor();
            }
        }
        if (conn.connect_armed and !conn.connect_cancel_pending) {
            if (io_backend.submitCancel(ring, .connect, conn.token)) |_| {
                conn.connect_cancel_pending = true;
            } else |err| {
                if (err == error.SubmissionQueueFull) self.wakeReactor();
            }
        }
    }

    fn retryWindowsClosingIo(self: *LinuxServer) void {
        if (comptime builtin.os.tag != .windows) return;
        for (self.rx().clients.slots.items) |*slot| {
            if (!slot.occupied or !slot.value.windows_force_close_cancel) continue;
            self.closeConn(slot.value.token, slot.value.close_reason) catch {};
        }
    }

    fn closeConn(self: *LinuxServer, token: RingFdToken, reason: []const u8) !void {
        const id = idFromToken(token);
        if (self.rx().clients.get(id)) |conn| {
            // A racing RECV (including cancellation at a Helix safe point) must
            // not shutdown the socket while a collision's final SEND owns its
            // buffer or retained link output still needs staging.
            if (conn.s2s_dedup_drain_deadline_ms != 0) {
                self.progressS2sDedupDrain(conn);
                return;
            }
            // Request-close and final teardown are deliberately separate. A CQE's
            // generation check protects dispatch, but it cannot stop the kernel
            // from touching inline slot storage. Retain the first reason, force a
            // quiet recv/connect to complete, and recycle only after every exact
            // ownership latch has been cleared by its matching handler.
            if (kernelOwnsConnStorage(conn)) {
                if (conn.tls != null) {
                    conn.tls_terminal_failure = true;
                    conn.tls_discard_unsent = true;
                }
                if (conn.closing)
                    retainCloseReason(conn, conn.close_reason)
                else
                    retainCloseReason(conn, reason);
                conn.closing = true;
                conn.io_activation_pending = false;
                conn.activation_recv_required = false;
                if (comptime builtin.os.tag == .windows) {
                    conn.windows_force_close_cancel = true;
                    self.cancelWindowsClosingIo(conn);
                }
                if (comptime builtin.os.tag == .linux)
                    _ = linux.shutdown(conn.fd, linux.SHUT.RDWR)
                else
                    os_runtime.shutdownBoth(conn.fd);
                return;
            }
            // This is the only fallible phase allowed to precede teardown for a
            // normal client. If a live exact-token sibling exists but staging
            // its World handoff hits allocation pressure, retain the slot and
            // retry from the periodic timer. Treating that failure as "no
            // sibling" would emit a false final QUIT and erase shared state.
            var local_identity_remains = false;
            if (conn.s2s == null and conn.s2s_secured == null) {
                local_identity_remains = conn.session_handoff_complete;
                if (!conn.session_handoff_checked) {
                    local_identity_remains = self.handoffLiveSessionIdentity(id, conn) catch |err| {
                        conn.closing = true;
                        retainCloseReason(conn, reason);
                        conn.session_handoff_retry = true;
                        return err;
                    };
                    conn.session_handoff_complete = local_identity_remains;
                    conn.session_handoff_checked = true;
                }
                conn.session_handoff_retry = false;
            }
            // Release any SendQ / RecvQ overflow heap before the slot is freed/reused
            // (covers every close path below, including S2S links that carry mesh bursts).
            if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
            if (conn.tls_deferred_plain.capacity > 0) conn.tls_deferred_plain.deinit(conn.overflow_allocator);
            if (conn.recv_overflow.capacity > 0) conn.recv_overflow.deinit(conn.overflow_allocator);
            // S2S peer: tear down the link, close, free the slot — no IRC quit path.
            if (conn.s2s_secured) |link| {
                self.flushFlightRecorder(.s2s, "mooring link dropped");
                const publish_peer_snapshot = !conn.s2s_dedup;
                const dropped_node = link.peerShortId();
                if (!conn.s2s_dedup and link.remoteName().len != 0) {
                    self.logMeshEvent(.peer_down, link.remoteName(), "secured link dropped");
                    self.publishServerLink(link.remoteName(), false);
                    _ = self.peer_health.remove(link.remoteName());
                }
                // A collision-collapsed duplicate keeps the peer reachable via the
                // surviving link, so its members never left — no netsplit.
                if (!conn.s2s_dedup) self.netsplitOnPeerDrop(conn); // #64: notify locals before the roster is gone
                if (!conn.s2s_dedup) if (dropped_node) |node| self.clearDroppedPeerRouteOrigin(node);
                if (!conn.s2s_dedup) {
                    if (dropped_node) |node| _ = self.session_replica_store.removePeer(node);
                }
                // Drop this peer's network-wide clone contributions (keyed by the
                // same node id `setRemote` used, so a dedup'd duplicate is skipped).
                if (!conn.s2s_dedup) if (link.remoteNodeId()) |node| self.mesh_clones.dropNode(node);
                const was_est = conn.s2s_established_counted;
                link.deinit();
                self.allocator.destroy(link);
                conn.s2s_secured = null;
                if (!conn.s2s_dedup) self.updatePartitionTransitions(); // detect a split this drop caused
                closeFd(conn.fd);
                if (conn.stats_s2s_tcp_counted) {
                    conn.stats_s2s_tcp_counted = false;
                    conn.s2s_established_counted = false;
                    self.stats.onClose(true, was_est);
                }
                _ = self.rx().clients.free(id);
                // The removed slot must be absent before recomputing. A dedup
                // loser never republishes: the collision winner already
                // replaced the route at establishment, and teardown must not
                // perturb that survivor's snapshot.
                if (publish_peer_snapshot) self.publishPeerCount();
                return;
            }
            if (conn.s2s) |link| {
                const publish_peer_snapshot = !conn.s2s_dedup;
                const dropped_node = link.remoteNodeId();
                if (!conn.s2s_dedup and link.remoteName().len != 0) {
                    self.logMeshEvent(.peer_down, link.remoteName(), "link dropped");
                    self.publishServerLink(link.remoteName(), false);
                    _ = self.peer_health.remove(link.remoteName());
                }
                // A collision-collapsed duplicate keeps the peer reachable via the
                // surviving link, so its members never left — no netsplit.
                if (!conn.s2s_dedup) self.netsplitOnPeerDrop(conn); // #64: notify locals before the roster is gone
                if (!conn.s2s_dedup) if (dropped_node) |node| self.clearDroppedPeerRouteOrigin(node);
                // Drop this peer's network-wide clone contributions.
                if (!conn.s2s_dedup) if (dropped_node) |node| self.mesh_clones.dropNode(node);
                const was_est = conn.s2s_established_counted;
                link.deinit();
                self.allocator.destroy(link);
                conn.s2s = null;
                if (!conn.s2s_dedup) self.updatePartitionTransitions(); // detect a split this drop caused
                closeFd(conn.fd);
                if (conn.stats_s2s_tcp_counted) {
                    conn.stats_s2s_tcp_counted = false;
                    conn.s2s_established_counted = false;
                    self.stats.onClose(true, was_est);
                }
                _ = self.rx().clients.free(id);
                if (publish_peer_snapshot) self.publishPeerCount();
                return;
            }
            self.dropClientStats(conn);
            self.clearGuestReadMarkers(conn);
            self.stats.onQuit();
            conn.session_list_cache.reset();
            // Free any in-flight inbound multiline batch buffer.
            self.abortMultiline(conn);
            // Tear down the per-connection TLS engine, if any.
            if (conn.tls) |t| {
                t.deinit();
                self.allocator.destroy(t);
                conn.tls = null;
            }
            // And the WebSocket adapter, if any.
            if (conn.ws) |w| {
                self.allocator.destroy(w);
                conn.ws = null;
            }
            // Release this connection's clone-limiter slot (only if it was counted;
            // refused accepts and addr-less peers never registered).
            if (conn.clone_counted) {
                if (conn.peer_addr) |addr| self.clone_limit.release(addr);
                conn.clone_counted = false;
            }
            self.releaseThrottle(conn);
            self.meshCloneRelease(conn);
            self.activity_subs.removeClient(monitorIdFromClient(id));
            var remote_identity_may_remain = false;
            // Multi-session: a logged-in client's session is *retained* as
            // detached (for reclaim/bouncer); an anonymous client is dropped.
            if (conn.session.account()) |acct| {
                const resume_handle = self.sessions.resumeHandleForClient(acct, monitorIdFromClient(id));
                if (resume_handle) |handle|
                    self.cancelSessionDropsForToken(acct, handle.token);
                if (!conn.session_detach_prepared) {
                    if (self.encodeMigrationSnapshot(id, conn)) |snapshot| {
                        defer self.allocator.free(snapshot);
                        if (!self.sessions.markDetachedWithSnapshot(acct, monitorIdFromClient(id), snapshot)) {
                            // Snapshot allocation failure already detaches while
                            // preserving the prior image. Retry the allocation-
                            // free detach to distinguish that safe degraded case
                            // from a still-conflicting/missing row; only the
                            // latter may be retired before ConnState is freed.
                            if (!self.sessions.markDetached(acct, monitorIdFromClient(id)))
                                _ = self.removeTrackedSession(acct, monitorIdFromClient(id));
                        }
                    } else {
                        if (!self.sessions.markDetached(acct, monitorIdFromClient(id)))
                            _ = self.removeTrackedSession(acct, monitorIdFromClient(id));
                    }
                }
                // Portable resume is opt-in: only a session whose MTOKEN was
                // actually delivered is replicated. The connection/world state
                // is still intact here, so the snapshot is complete.
                if (self.config.session_migrate_on_detach) {
                    if (resume_handle) |handle| {
                        if (handle.portable and !tokenIsNull(handle.token)) {
                            // A portable logical session can have live attachments
                            // behind any established secured peer. There is no
                            // ownership transfer/ACK to wait for: publishing PART
                            // or QUIT for this one socket would incorrectly evict
                            // those remote attachments from the shared identity.
                            remote_identity_may_remain = self.exactRemoteSessionAuthority(handle.token);
                            if (!conn.session_detach_prepared)
                                _ = self.shipSessionMigration(id, conn, acct, handle.token);
                        }
                    }
                }
            } else {
                _ = self.sessions.removeClient(monitorIdFromClient(id));
            }
            // This must precede the portable/live-sibling identity handoff: that
            // path intentionally skips broadcastQuit, but a pre-restore Device*
            // PRESENCE route still needs explicit retirement if authority never
            // became publishable.
            const identity_remains = local_identity_remains or remote_identity_may_remain;
            self.retractDeferredSessionMeshIdentity(id, conn, identity_remains);
            self.clearDeferredSessionMeshParts(conn);
            // Transport loss is not logical-session loss while another local
            // attachment remains. Hand off nick ownership and channel state
            // before any offline/QUIT side effect is emitted.
            // Hold this nick against reuse for the nick-delay window before the
            // world drops it. No-op on a clean QUIT (handleQuit already held +
            // removed the nick) and for anonymous/unregistered/shared sessions.
            if (!identity_remains) self.holdNickOnExit(id, conn);
            defer self.world.removeClient(worldIdFromClient(id));
            // Record only for abrupt drops: a clean QUIT already recorded (and
            // removed the nick) in handleQuit, so skip to avoid a duplicate.
            if (!identity_remains and self.world.nickOf(worldIdFromClient(id)) != null) self.recordWhowas(conn);
            // MONITOR occupancy belongs to the logical rendered identity, but
            // subscriptions belong to this physical connection. Always remove
            // the departing client from reverse indexes; emit offline only when
            // neither this exact session nor another same-nick local token lives.
            if (conn.session.registered()) {
                const nick = conn.session.displayName();
                if (!std.mem.eql(u8, nick, "*") and !identity_remains and
                    !self.localRenderedNickOccupiedExcept(nick, &.{id}))
                    self.monitorOffline(nick) catch {};
                self.monitor.removeClient(monitorIdFromClient(id));
            }
            // Media: drop the departing nick from any call, notifying members.
            if (conn.session.registered()) self.leaveAllMediaRooms(id, conn);
            // OBSERVE: push a quit record, then drop this client's own subscription.
            if (!identity_remains and conn.session.registered()) {
                self.notifyObservers(.quit, observeSubject(conn, reason));
                if (self.world.nickOf(worldIdFromClient(id)) != null) self.publishUserDisconnectEvent(conn, reason) catch {};
            }
            _ = self.observe.clear(monitorIdFromClient(id));
            if (!identity_remains) {
                self.broadcastQuit(id, conn, reason) catch {};
                self.publishChannelDestroyEventsForClient(id);
            }
            closeFd(conn.fd);
            _ = self.rx().clients.free(id);
        }
    }

    /// Snapshot a departing client's identity into the WHOWAS ring. The store
    /// copies into fixed slots, so the borrowed session strings are safe to pass.
    /// Best-effort: validation failures (e.g. over-length) are dropped.
    fn recordWhowas(self: *LinuxServer, conn: *const ConnState) void {
        if (!conn.session.registered()) return;
        const nick = conn.session.displayName();
        if (std.mem.eql(u8, nick, "*")) return;
        self.whowas.addOnQuit(.{
            .nick = nick,
            .user = conn.session.username(),
            .host = whowasRecordedHost(conn),
            .realname = conn.session.realname(),
            .account = conn.session.account() orelse "",
            .signoff_time = @divTrunc(platform.realtimeMillis(), 1000),
        }) catch {};
    }

    /// Host stored for WHOWAS: the connection's real host when it is a legal
    /// host token, otherwise the visible host, otherwise the process default.
    fn whowasRecordedHost(conn: *const ConnState) []const u8 {
        const real_host = conn.session.realHost();
        if (whowasHostOk(real_host)) return real_host;
        const visible = conn.session.host();
        if (whowasHostOk(visible)) return visible;
        return default_host;
    }

    fn whowasHostOk(host: []const u8) bool {
        if (host.len == 0 or host.len > 255) return false;
        for (host) |ch| {
            if (ch == 0 or ch == '\r' or ch == '\n' or ch == ' ' or ch < 0x20 or ch == 0x7f) return false;
        }
        return true;
    }

    fn broadcastQuit(self: *LinuxServer, id: client_model.ClientId, conn: *const ConnState, reason: []const u8) !void {
        if (self.world.nickOf(worldIdFromClient(id)) == null) return;

        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const quit_prefix = try clientPrefix(conn, &prefix_buf);
        const msg = try formatMessage(&msg_buf, quit_prefix, "QUIT", &.{}, reason);
        // draft/event-playback body: `:reason` so the event renders `:nick QUIT
        // :reason` (QUIT carries no target — recorded into each channel below).
        var quit_body_buf: [600]u8 = undefined;
        const quit_body = std.fmt.bufPrint(&quit_body_buf, ":{s}", .{reason}) catch ":";

        const nick = conn.session.displayName();
        const announce = !std.mem.eql(u8, nick, "*");
        // Preserve QUIT (rather than degrading it to a PART per channel) across
        // the existing MEMBERSHIP wire without breaking rolling peers. Setter is
        // already an optional, backward-compatible field; realname is irrelevant
        // after departure, so this event uses it for the bounded quit reason.
        var quit_reason_buf: [client_model.MAX_REALNAME_BYTES]u8 = undefined;
        const quit_reason_len = @min(reason.len, quit_reason_buf.len);
        for (reason[0..quit_reason_len], 0..) |byte, i| {
            quit_reason_buf[i] = if (byte < 0x20 or byte == 0x7f) ' ' else byte;
        }
        var quit_identity = membershipIdentityOf(conn);
        quit_identity.realname = quit_reason_buf[0..quit_reason_len];
        // Presence first lets a current peer issue the identity-wide QUIT while
        // every channel route is still visible. Per-channel negatives follow to
        // converge authority and are client-display-deduped at the receiver.
        if (announce and !conn.session_mesh_announce_pending)
            self.announceMembership(presence_channel, nick, 0, false, quit_identity, mesh_quit_setter);
        var it = self.world.channels.iterator();
        while (it.next()) |entry| {
            if (entry.value_ptr.members.contains(worldIdFromClient(id))) {
                // One congested recipient/channel must not abort teardown for
                // every later channel or strand the mesh presence route. QUIT
                // fanout is best-effort; history and authoritative membership
                // withdrawal must always run to completion.
                self.broadcastChannel(entry.key_ptr.*, msg, id) catch {};
                self.recordHistoryEventSender(entry.key_ptr.*, quit_prefix, "QUIT", quit_body);
                // Tell mesh peers this member is gone so their remote roster
                // drops it. The QUIT marker preserves identity-wide client
                // semantics while each channel fact still converges separately.
                if (announce and !conn.session_mesh_announce_pending)
                    self.announceMembership(entry.key_ptr.*, nick, 0, false, quit_identity, mesh_quit_setter);
            }
        }
    }

    /// Drive an implicit-TLS client's recv chunk: frame + decrypt through the
    /// per-conn adapter, write any handshake flight back (raw — appendToConn
    /// leaves it unencrypted while the handshake is incomplete), and feed any
    /// decrypted plaintext into the normal line parser. A handshake/record fault
    /// closes only this connection.
    fn driveTls(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, chunk: []const u8) !void {
        std.debug.assert(!conn.tls_ingress_active);
        conn.tls_ingress_active = true;
        defer conn.tls_ingress_active = false;
        const handshake_pending = !conn.tls.?.handshakeDone();
        const started_at_ms = self.nowMs();
        const t = conn.tls.?;
        const connected13 = t.handshakeDone() and t.negotiatedVersion() == .tls13;
        var control_custody: ?sendq.PreparedReservedControlAppend(*ConnState) = null;
        defer if (control_custody) |*ticket| ticket.abort();
        var funded = false;
        if (connected13) {
            const credit: usize = if (conn.tls_tx_offloaded) 5 else 27;
            if (sendq.prepareControlReservation(conn, credit)) |candidate| {
                var reservation = candidate;
                reservation.commit();
                funded = true;
            } else |_| {}
        }
        const held_before = t.control_phase == .userspace_requested_ku_held;
        const old_wire_before = sendq.wireBacklog(conn);
        const old_prefix = if (conn.tls_tx_offloaded and held_before) conn.tls_kernel_prefix_remaining else old_wire_before;
        var allow_requested = funded and !conn.send_armed and old_prefix == 0;
        if (allow_requested and !conn.tls_tx_offloaded) {
            control_custody = sendq.prepareReservedControlAppend(conn, 27) catch null;
            if (control_custody == null) allow_requested = false;
        }
        const outcome = t.onInboundWithControlCustody(chunk, !connected13 or allow_requested) catch |err| {
            self.failTls(conn, err);
            return;
        };
        if (conn.tls_tx_offloaded and !held_before and t.control_phase == .userspace_requested_ku_held)
            conn.tls_kernel_prefix_remaining = old_wire_before;
        if (outcome.control_reply) {
            std.debug.assert(outcome.handshake_bytes.len == 27 and control_custody != null);
            control_custody.?.commit(outcome.handshake_bytes);
            t.control_phase = if (conn.tls_deferred_plain.items.len != 0) .software_tail_ready else .none;
        } else if (t.tx_ku_reply_pending) {
            t.control_phase = .none;
            t.held_record_len = 0;
        } else if (t.control_phase != .userspace_requested_ku_held) {
            sendq.cancelControlReservation(conn);
        }
        if (tlsControlWaiting(conn)) {
            conn.io_activation_pending = true;
            conn.activation_recv_required = false;
        }
        if (handshake_pending and conn.tls.?.handshakeDone()) {
            self.recordElapsedLatency(.tls_handshake, started_at_ms);
        }
        // Once the mTLS handshake completes, bind the presented client cert's
        // fingerprint to the session so SASL EXTERNAL can match it to an account.
        if (conn.session.tls_certfp == null and conn.tls.?.handshakeDone()) {
            if (conn.tls.?.clientCertDer()) |der| {
                certfp.computeHex(der, &conn.certfp_buf);
                conn.session.tls_certfp = conn.certfp_buf[0..];
            }
        }
        // Capture the negotiated cipher suite once the handshake completes, so
        // WHOIS 671 can show it. cipherName() returns a static string — no
        // per-connection backing or lifetime concern.
        if (conn.session.tls_cipher == null and conn.tls.?.handshakeDone()) {
            conn.session.tls_cipher = conn.tls.?.cipherName();
        }
        if (conn.session.tls_exporter == null and conn.tls.?.handshakeDone()) {
            if (conn.tls.?.channelBindingTlsExporter(&conn.tls_exporter_buf)) |_| {
                conn.session.tls_exporter = conn.tls_exporter_buf;
            } else |_| {}
        }
        // kTLS TX offload (roadmap 3.1): once a TLS 1.3 handshake completes and
        // offload is enabled, mark it pending — the attach itself waits for the
        // send buffer to fully drain (below / at send-completion) so the kernel
        // only ever takes over a clean, already-flushed send stream.
        if (self.config.tls_ktls_tx and conn.tls.?.handshakeDone() and
            !conn.tls_tx_offloaded and !conn.ktls_attach_pending and
            conn.tls.?.negotiatedVersion() == .tls13)
        {
            conn.ktls_attach_pending = true;
        }
        // A post-handshake TLS record (e.g. a KeyUpdate response) on an
        // already-offloaded conn cannot be written as userspace ciphertext — the
        // kernel would double-encrypt it. Phase 1 does not offload conns that need
        // server-initiated post-handshake sends, so drop it (the client
        // reconnects) rather than corrupt the stream.
        if (conn.tls_tx_offloaded and outcome.handshake_bytes.len != 0) {
            conn.closing = true;
            return;
        }
        if (outcome.handshake_bytes.len != 0 and !outcome.control_reply) {
            // `handshake_bytes` are ALREADY-FORMED TLS records (the handshake
            // flight / post-handshake KeyUpdate) produced by the TLS engine, so
            // they go straight to the wire — NEVER through the app-data encrypt
            // seam. This matters for TLS 1.2: the server's CCS+Finished is built
            // in the same onInbound that flips the connection to "established", so
            // a plain appendToConn would see handshakeDone()=true and wrongly
            // re-encrypt the flight as application_data (clients abort with
            // "unexpected message"). TLS 1.3 sends its Finished pre-established so
            // it never tripped this.
            rawAppendToConn(conn, outcome.handshake_bytes) catch {
                conn.closing = true;
                return;
            };
        }
        if (!conn.closing and outcome.plaintext.len != 0) {
            if (conn.ws != null) {
                // wss browser client: decrypted bytes are HTTP-upgrade/WebSocket
                // frames, not bare IRC lines.
                try self.driveWs(id, conn, outcome.plaintext);
            } else {
                try self.feedBytes(id, conn, outcome.plaintext);
            }
        }
        // kTLS RX offload (txrx): attach once the handshake is done and the inbound
        // is at a clean record boundary (any app data in this chunk was just
        // consumed above, advancing app_read_seq; no partial record is buffered),
        // so the kernel resumes decryption from exactly app_read_seq. One-shot: a
        // conn that still holds a partial inbound record stays on userspace RX.
        // After this, recv() returns plaintext (routed via driveClientBytes).
        if (self.config.tls_ktls_rx and conn.tls.?.handshakeDone() and
            !conn.tls_rx_offloaded and conn.tls.?.negotiatedVersion() == .tls13 and
            !conn.tls.?.hasBufferedInbound())
        {
            if (conn.tls.?.enableKtlsRx(conn.fd)) |_| {
                conn.tls_rx_offloaded = true;
            } else |_| {} // attach failed → stay on userspace RX
        }
        // If offload is pending and the send buffer is already drained (e.g. no
        // NewSessionTicket to flush), attach now; otherwise the send-completion
        // drain hook picks it up once the flight finishes.
        self.maybeAttachKtlsTx(conn);
    }

    /// Attach kTLS TX offload when a pending conn's send path has fully drained
    /// (inline `send_buf` emptied, no `send_overflow`, nothing armed), so the
    /// kernel only ever takes over a clean send stream — never a ciphertext tail.
    /// A failed attach silently leaves the conn on userspace TLS. Called at the
    /// connected transition and on every send-completion drain.
    fn maybeAttachKtlsTx(self: *LinuxServer, conn: *ConnState) void {
        _ = self;
        if (!conn.ktls_attach_pending) return;
        if (conn.send_offset < conn.send_len) return; // inline bytes still queued
        if (conn.send_overflow.items.len != 0) return; // overflow still queued
        if (conn.send_armed or tlsControlWaiting(conn) or conn.tls_control_charge != 0 or conn.tls_deferred_charge != 0) return; // exact output owner still pending
        const t = conn.tls orelse {
            conn.ktls_attach_pending = false;
            return;
        };
        t.enableKtlsTx(conn.fd) catch {
            conn.ktls_attach_pending = false; // stay in userspace TLS
            return;
        };
        conn.ktls_attach_pending = false;
        conn.tls_tx_offloaded = true;
    }

    /// Drive a WebSocket client's decrypted (or, in the gated plain-ws testing
    /// mode, raw) inbound bytes: finish the HTTP/1.1 Upgrade first, then deframe
    /// RFC 6455 frames and feed data payloads into the normal IRC line buffer.
    /// Handshake and frame faults close only this connection (the same
    /// per-connection firewall as driveTls / processLiveLine).
    fn driveWs(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, bytes: []const u8) !void {
        const ws = conn.ws.?;
        var rest = bytes;
        if (ws.phase == .handshake) {
            // The queued 101/refusal bytes are flushed by handleRecv's
            // armSendIfNeeded after this call returns.
            rest = wsDriveHandshake(conn, ws, rest) orelse return;
            if (ws.phase != .open) return; // request head still incomplete
        }
        if (rest.len == 0) return;
        ws.deframer.feed(rest) catch |err| {
            wsDeframeError(conn, err);
            return;
        };
        while (true) {
            const event = ws.deframer.next() catch |err| {
                wsDeframeError(conn, err);
                return;
            } orelse break;
            switch (event) {
                .data => |d| {
                    if (d.binary) {
                        if (!wsAdmitsBinaryApplication(ws)) {
                            wsProtocolError(conn);
                            return;
                        }
                        if (!d.continuation) {
                            // Single-frame messages retain the zero-copy fast
                            // path. A non-FIN opener begins bounded application
                            // reassembly; active distinguishes an empty opener.
                            if (ws.binary_message_active) {
                                wsProtocolError(conn);
                                return;
                            }
                            if (d.fin) {
                                self.handleWsMediaDatagram(id, conn, d.payload);
                                if (conn.closing) return;
                            } else {
                                if (d.payload.len > ws.binary_message_buf.len) {
                                    wsMessageTooBig(conn);
                                    return;
                                }
                                @memcpy(ws.binary_message_buf[0..d.payload.len], d.payload);
                                ws.binary_message_len = d.payload.len;
                                ws.binary_message_active = true;
                            }
                        } else {
                            // A continuation is never independently routable.
                            // Append it to the opening message and route exactly
                            // once only after the FIN continuation completes it.
                            if (!ws.binary_message_active or
                                d.payload.len > ws.binary_message_buf.len - ws.binary_message_len)
                            {
                                if (!ws.binary_message_active) {
                                    wsProtocolError(conn);
                                } else {
                                    wsMessageTooBig(conn);
                                }
                                return;
                            }
                            @memcpy(ws.binary_message_buf[ws.binary_message_len..][0..d.payload.len], d.payload);
                            ws.binary_message_len += d.payload.len;
                            if (d.fin) {
                                const message = ws.binary_message_buf[0..ws.binary_message_len];
                                ws.binary_message_active = false;
                                ws.binary_message_len = 0;
                                self.handleWsMediaDatagram(id, conn, message);
                                if (conn.closing) return;
                            }
                        }
                    } else {
                        if (ws.subprotocol == .ircv3_text and
                            std.mem.indexOfAny(u8, d.payload, "\r\n") != null)
                        {
                            // text.ircv3.net maps exactly one IRC message to
                            // one WebSocket message; CR/LF would batch or
                            // smuggle an additional IRC line. Reject the whole
                            // application message before any line is routed.
                            wsProtocolError(conn);
                            return;
                        }
                        try self.feedBytes(id, conn, d.payload);
                        if (conn.closing) return;
                        // IRCv3 WebSocket convention: the frame boundary terminates
                        // the IRC message even without a trailing CRLF. Synthesize
                        // one so both frame-per-message clients and CRLF-framing
                        // clients parse identically.
                        if (d.fin and ws.subprotocol == .ircv3_text and pendingInbound(conn) == 0) {
                            // An empty WebSocket message is not a complete IRC
                            // line under the negotiated mapping.
                            wsProtocolError(conn);
                            return;
                        }
                        if (d.fin and pendingInbound(conn) != 0) try self.feedBytes(id, conn, "\r\n");
                        if (conn.closing) return;
                    }
                },
                .ping => |payload| wsQueueControl(conn, .pong, payload),
                .pong => {},
                .close => |payload| {
                    // Echo the close (status code included) and drain-close.
                    wsQueueControl(conn, .close, payload);
                    conn.closing = true;
                    return;
                },
            }
        }
    }

    fn challengeRequired(self: *LinuxServer, conn: *ConnState) bool {
        if (!self.config.challenge_enabled) return false;
        if (conn.s2s != null or conn.s2s_secured != null) return false;
        if (self.reputationOn()) {
            if (conn.peer_addr) |addr| {
                if (self.reputation.shouldRefuse(addr, self.nowU64())) return true;
            }
        }
        return self.raid_shield.engaged();
    }

    fn armChallengeHold(self: *LinuxServer, conn: *ConnState) void {
        if (conn.challenge_passed or !self.challengeRequired(conn)) {
            conn.session.challenge_hold = false;
            return;
        }
        conn.session.challenge_hold = true;
        if (conn.challenge_seed_len != 0) return;
        var text: [48]u8 = undefined;
        const rendered = std.fmt.bufPrint(&text, "challenge:{d}:{d}", .{ self.challenge_issued, self.nowU64() }) catch "challenge";
        self.challenge_issued += 1;
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(rendered, &digest, .{});
        @memcpy(conn.challenge_seed[0..16], digest[0..16]);
        conn.challenge_seed_len = 16;
    }

    fn noticeChallenge(self: *LinuxServer, conn: *ConnState) !void {
        var buf: [240]u8 = undefined;
        const text = switch (self.challenge_method) {
            .pow => blk: {
                var hex_buf: [32]u8 = undefined;
                const hex = challenge_mod.hexEncode(conn.challenge_seed[0..conn.challenge_seed_len], &hex_buf);
                break :blk std.fmt.bufPrint(&buf, "CHALLENGE pow {s}", .{hex}) catch "CHALLENGE pow";
            },
            .question => std.fmt.bufPrint(&buf, "CHALLENGE question {s}", .{self.challenge_question[0..self.challenge_question_len]}) catch "CHALLENGE question",
        };
        try self.noticeTo(conn, text);
    }

    /// Oper METHOD/QUESTION selects the ladder arm. An unregistered answer is
    /// checked by `challenge_mod.admit`. A pass clears the hold and may emit 001.
    /// It does not log the client into an account.
    pub fn handleChallenge(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        _ = id;
        const p = parsed.paramSlice();
        if (conn.session.registered()) {
            if (!conn.session.isOper()) {
                try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied");
                return;
            }
            if (!self.config.challenge_enabled) {
                try self.noticeTo(conn, "CHALLENGE disabled");
                return;
            }
            if (p.len >= 2 and std.ascii.eqlIgnoreCase(p[0], "METHOD")) {
                if (std.ascii.eqlIgnoreCase(p[1], "pow")) self.challenge_method = .pow else if (std.ascii.eqlIgnoreCase(p[1], "question")) self.challenge_method = .question else {
                    try self.noticeTo(conn, "CHALLENGE method is pow or question");
                    return;
                }
                try self.noticeTo(conn, "CHALLENGE method set");
                return;
            }
            if (p.len >= 1 and std.ascii.eqlIgnoreCase(p[0], "QUESTION")) {
                if (p.len < 3 or p[1].len == 0 or p[1].len > challenge_mod.max_text or p[2].len == 0 or p[2].len > challenge_mod.max_answer or dispatch.hasControlByte(p[1]) or dispatch.hasControlByte(p[2])) {
                    try self.noticeTo(conn, "Usage: CHALLENGE QUESTION <question> :<answer>");
                    return;
                }
                @memcpy(self.challenge_question[0..p[1].len], p[1]);
                self.challenge_question_len = p[1].len;
                @memcpy(self.challenge_answer[0..p[2].len], p[2]);
                self.challenge_answer_len = p[2].len;
                self.challenge_method = .question;
                try self.noticeTo(conn, "CHALLENGE question set");
                return;
            }
            try self.noticeTo(conn, "Usage: CHALLENGE METHOD <pow|question>");
            return;
        }
        if (p.len < 1) {
            try self.noticeTo(conn, "Usage: CHALLENGE <answer>");
            return;
        }
        if (!conn.session.challenge_hold and !self.challengeRequired(conn)) {
            try self.noticeTo(conn, "CHALLENGE not required");
            return;
        }
        if (self.nowMs() < conn.challenge_not_before_ms) {
            try self.noticeTo(conn, "CHALLENGE wait");
            return;
        }
        const material = challenge_mod.Material{
            .seed = conn.challenge_seed[0..conn.challenge_seed_len],
            .expected = self.challenge_answer[0..self.challenge_answer_len],
        };
        if (!challenge_mod.admit(self.challenge_method, material, p[0])) {
            const now = self.nowMs();
            conn.challenge_not_before_ms = now + challenge_mod.fail_delay_ms;
            try self.noticeTo(conn, "CHALLENGE failed");
            return;
        }
        conn.challenge_passed = true;
        var storage: [default_reply_bytes]u8 = undefined;
        var replies = dispatch.ReplyCtx.init(&storage);
        try dispatch.releaseChallengeHold(&conn.session, &replies);
        if (replies.written().len != 0) try appendToConn(conn, replies.written());
    }

    /// Post-001 registration tail shared by NICK/USER and a passed challenge.
    fn completeLiveRegistration(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) !void {
        // Re-apply the visible host now that the background resolver (kicked
        // off at connect) has had the handshake window to finish. With a
        // cloak key this re-cloaks the IP (rDNS never feeds the public cloak
        // — that would leak the ISP domain); without one it picks up the
        // forward-confirmed reverse-DNS name if the operator enabled rDNS.
        self.applyVisibleHost(conn);
        try self.registerConnNick(id, conn);
        if (conn.closing) return;
        // Complete the registration burst after the 001-005 numerics
        // (emitted by the dispatch welcome): LUSERS (251-255) then the
        // MOTD (375/372/376 or 422), as every ircd does on connect.
        self.handleLusers(conn) catch {};
        self.handleMotd(conn) catch {};
        // Warden: a network/node ban (Match × Scope × Action) is
        // enforced against the freshly registered client's facets,
        // before oper elevation/welcome.
        if (self.enforceWard(conn)) return;
        // Connect-time DNS blocklist: refuse (or network-ban) a client
        // whose IP is listed by a configured zone. Best-effort — a lookup
        // not yet resolved by now lets the client through (fail-open).
        if (self.enforceDnsbl(conn)) return;
        if (try self.enforceServerAccess(conn)) return;
        // Persistent +z GAG: a client reconnecting from a gagged IP is
        // re-flagged so its messages stay silenced and +z displays.
        {
            const rip = conn.session.realHost();
            if (rip.len > 0 and self.gags.contains(rip)) conn.gagged = true;
        }
        // SEEN: record this account's login for the LASTSEEN history.
        if (conn.session.account()) |acct| {
            var mb: [256]u8 = undefined;
            const mask = clientPrefix(conn, &mb) catch "";
            self.recordSeen(acct, mask, .login);
        }
        const external_candidate = if (conn.sasl_external_authenticated) blk: {
            const account = conn.session.account() orelse break :blk ExternalResumeCandidate.none;
            break :blk self.externalResumeCandidate(
                monitorIdFromClient(id),
                account,
                conn.session.displayName(),
            );
        } else ExternalResumeCandidate.none;
        // SASL-only oper: elevate now if the (SASL-set) account is bound to
        // an operator class. Emits 381 + MODE +o after the welcome burst.
        // Gated on the mechanism allowing elevation: federated (OAUTHBEARER)
        // and guest (ANONYMOUS) logins never auto-oper, matching the gated
        // SASL-success/REGISTER elevation sites.
        if (conn.session.sasl_oper_elevation_allowed) try self.elevateOperFromAccountWithPrefix(
            conn,
            external_candidate == .none,
        );
        // Match the now-fully-identified client (IP/TLS/account/oper) to its
        // connection class, apply the per-class SendQ ceiling, then enforce
        // the class admission policy (require_tls / require_sasl).
        self.assignConnClass(conn);
        if (self.enforceClassAdmission(conn)) return;
        self.meshCloneAdd(conn); // count toward the network-wide IP aggregate + gossip
        // EXTERNAL authority is selected before inserting the claimant:
        // a cap-bound insertion may evict the detached row we are about
        // to restore. Only a genuinely fresh login gets a new token.
        if (!conn.sasl_external_authenticated) self.trackSession(id, conn);
        const external_outcome = if (conn.sasl_external_authenticated)
            try self.autoResumeExternalSession(id, conn, external_candidate)
        else
            ExternalResumeOutcome.fresh;
        if (external_outcome == .blocked) {
            conn.closing = true;
            return;
        }
        self.armBoundedExactResumeHoldIfNeeded(id, conn);
        if (!try self.enforceE2eeSessionEligibility(id, conn)) return;
        try self.deliverMemo(conn); // hand over any offline messages
        // OBSERVE: push a connect record to watching operators.
        self.notifyObservers(.connect, observeSubject(conn, ""));
        self.publishUserConnectEvent(conn) catch {};
        // Apply any operator-approved vhost waiting for this account.
        self.maybeApplyApprovedVhost(id, conn);
        if (external_outcome == .fresh) self.applyLoginJoinState(id, conn);
        // Set the client's `location`/`country` metadata from GeoIP (or
        // the configured default) so `!weather` has a per-user location.
        self.setGeoLocation(conn);
        // Welcome-burst origin line: the client's OWN GeoIP location + ASN,
        // shown only to them (privacy-safe — never another user's geo/ASN).
        self.emitGeoOriginNotice(conn);
        self.deliverWelcome(conn);
        self.emitClientRegistered(id, conn);
        self.evaluateNickProtection(conn);
    }

    fn feedBytes(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, bytes: []const u8) !void {
        if (conn.closing) return;
        for (bytes) |byte| {
            const line = (recvqPush(conn, byte) catch |err| switch (err) {
                error.LineTooLong => {
                    conn.closing = true;
                    self.stats.onError();
                    return error.LineTooLong;
                },
                error.OutOfMemory => return error.OutOfMemory,
            }) orelse continue;
            self.stats.onLine();
            try self.processLiveLine(id, conn, line);
            recvqReset(conn);
            // QUIT, parser/flood policy, and command handlers can mark the
            // transport closing. Bytes later in the same TCP/TLS/WS payload
            // are untrusted post-close input and must never be dispatched.
            if (conn.closing) return;
        }
    }

    fn processLiveLine(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, line: []const u8) !void {
        // Parse errors are the CLIENT's fault and must never propagate past
        // this frame: an escaped error reaches onCompletion's handler.err path
        // and tears down the whole reactor — a one-line remote DoS for any
        // unauthenticated peer. Blank lines are ignored per RFC 1459; every
        // other malformed line closes only the offending connection.
        const parsed = irc_line.parseLine(line) catch |err| switch (err) {
            error.EmptyLine => return,
            else => {
                conn.closing = true;
                return;
            },
        };
        const was_registered = conn.session.registered();

        // STATS m (RPL_STATSCOMMANDS): record this verb's usage. Counts every
        // well-formed line (registered or not); the byte total is the raw line
        // length. Lock-free for verbs already in the table.
        self.command_usage.record(parsed.command, line.len);

        // The single per-connection flood guard. Set up from the matched class in
        // `assignConnClass` (null when exempt / no limit / S2S). Keep-alives are
        // free, commands are weighted, and a spread-spam throttle plus a decaying
        // excess budget escalate a sustained flood to disconnect. A `.throttle`
        // keeps processing the line (no silently dropped user input) while excess
        // climbs; only `.disconnect` tears the client down.
        if (was_registered and conn.s2s == null and conn.s2s_secured == null) {
            if (conn.flood_guard) |*guard| {
                const decision = guard.classifyRaw(self.nowMs(), line);
                conn.last_flood = decision;
                if (decision != .allow) self.noteAccountAbuse(conn);
                if (decision == .disconnect) {
                    emitServerLine(conn, "ERROR :Excess Flood");
                    conn.close_reason = "Excess Flood";
                    conn.closing = true;
                    self.armSendIfNeeded(conn) catch {};
                    return;
                }
            }
        }

        if (!was_registered) {
            self.armChallengeHold(conn);
            if (std.ascii.eqlIgnoreCase(parsed.command, "CHALLENGE")) {
                try self.handleChallenge(id, conn, &parsed);
                if (conn.session.registered()) try self.completeLiveRegistration(id, conn);
                return;
            }
            // IRCX discovery must work BEFORE registration (draft-pfenning): an
            // unregistered client probes support via IRCX/ISIRCX/MODE ISIRCX.
            if (std.ascii.eqlIgnoreCase(parsed.command, "IRCX")) {
                try self.handleIrcx(conn, true);
                return;
            }
            if (std.ascii.eqlIgnoreCase(parsed.command, "ISIRCX")) {
                try self.handleIrcx(conn, false);
                return;
            }
            if (std.ascii.eqlIgnoreCase(parsed.command, "MODE") and
                parsed.param_count >= 1 and std.ascii.eqlIgnoreCase(parsed.paramSlice()[0], "ISIRCX"))
            {
                try self.handleIrcx(conn, false);
                return;
            }
            if (std.ascii.eqlIgnoreCase(parsed.command, "MODE") and
                parsed.param_count >= 2 and
                std.ascii.eqlIgnoreCase(parsed.paramSlice()[0], conn.session.displayName()) and
                std.ascii.eqlIgnoreCase(parsed.paramSlice()[1], "ISIRCX"))
            {
                try self.handleIrcx(conn, false);
                return;
            }
            // draft/pre-away: a negotiating client may set its AWAY state during
            // the registration handshake. Apply it now so the user is already
            // marked away when registration completes. away-notify fan-out is a
            // no-op here (no channels joined yet).
            if (std.ascii.eqlIgnoreCase(parsed.command, "AWAY") and conn.session.hasCap(.pre_away)) {
                try self.handleAway(id, conn, &parsed);
                return;
            }
            // draft/account-registration: pre-registration REGISTER is not
            // supported (account creation requires a completed connection so the
            // current nick/account identity is established). Reply with the draft
            // standard-replies FAIL instead of letting REGISTER fall through to
            // generic dispatch, which would emit 421 ERR_UNKNOWNCOMMAND for an
            // unregistered client. This is also why the cap is not advertised
            // before-connect.
            if (std.ascii.eqlIgnoreCase(parsed.command, "REGISTER")) {
                self.failReply(conn, "REGISTER", "COMPLETE_CONNECTION_REQUIRED", "Complete connection registration first") catch |err| switch (err) {
                    error.OutputTooSmall,
                    error.TextTooLong,
                    error.NoSpaceLeft,
                    error.OversizeLine,
                    error.LineTooLong,
                    => conn.closing = true,
                    else => return err,
                };
                return;
            }
            // A network ban closes the socket at registration. APPEAL is the
            // one command a new connection can file before that checkpoint.
            // It must not complete registration or reach a channel.
            if (std.ascii.eqlIgnoreCase(parsed.command, "APPEAL")) {
                _ = try self.dispatchModules(id, conn, &parsed, line);
                return;
            }
            if (std.ascii.eqlIgnoreCase(parsed.command, "AUTHENTICATE") and !self.authenticationAvailable()) {
                conn.session.sasl_router = null;
                conn.session.sasl_pending = null;
                conn.session.sasl_issue_session_token = false;
                conn.session.client.registration.sasl = .failed;
                var failure_buf: [default_reply_bytes]u8 = undefined;
                const failure = try std.fmt.bufPrint(&failure_buf, ":{s} 904 {s} :Account storage requires recovery\r\n", .{ self.serverName(), conn.session.displayName() });
                return appendToConn(conn, failure);
            }
            const external_exchange = conn.session.sasl_pending == .external;
            var prereg_reply_buf: [default_reply_bytes]u8 = undefined;
            var sink = PreregReplySink{ .buf = &prereg_reply_buf };
            // Same per-client firewall as dispatchRegistered below: a full send
            // buffer, oversize reply, or an outbound control-byte reflection
            // (error.ControlByte) during preregistration closes only this
            // connection instead of escaping to the reactor loop.
            processLine(conn, line, &sink) catch |err| switch (err) {
                error.ControlByte,
                error.OutputTooSmall,
                error.TextTooLong,
                error.NoSpaceLeft,
                error.OversizeLine,
                error.LineTooLong,
                => {
                    conn.closing = true;
                    return;
                },
                else => return err,
            };
            if (conn.session.registered() and self.registeredNickRequiresAuthentication(conn, conn.session.displayName())) {
                try queueNumeric(
                    conn,
                    .ERR_ERRONEUSNICKNAME,
                    &.{conn.session.displayName()},
                    "Nickname is registered; authenticate as this account before using it",
                );
                conn.close_reason = "Registered nickname requires authentication";
                conn.closing = true;
                return;
            }
            if (sink.written().len != 0) try appendToConn(conn, sink.written());
            if (std.ascii.eqlIgnoreCase(parsed.command, "AUTHENTICATE"))
                conn.sasl_external_authenticated = external_exchange and
                    conn.session.client.registration.sasl == .succeeded and
                    conn.session.account() != null;
            if (conn.session.sasl_issue_session_token) {
                conn.session.sasl_issue_session_token = false;
                self.issueSessionTokenNotice(conn, "SASL") catch {};
            }
            if (!conn.session.registered() and conn.session.challenge_hold and conn.session.registration.nick_seen and conn.session.registration.user_seen and (std.ascii.eqlIgnoreCase(parsed.command, "NICK") or std.ascii.eqlIgnoreCase(parsed.command, "USER"))) {
                try self.noticeChallenge(conn);
            }
            if (conn.session.registered()) try self.completeLiveRegistration(id, conn);
            if (std.ascii.eqlIgnoreCase(parsed.command, "QUIT")) {
                conn.closing = true;
            }
            return;
        }

        if (std.ascii.eqlIgnoreCase(parsed.command, "PING")) {
            var sink = QueueSink{ .conn = conn };
            processLine(conn, line, &sink) catch |err| switch (err) {
                error.ControlByte,
                error.OutputTooSmall,
                error.TextTooLong,
                error.NoSpaceLeft,
                error.OversizeLine,
                error.LineTooLong,
                => conn.closing = true,
                else => return err,
            };
            return;
        }

        // An authenticated E2EE socket admitted only for a bounded exact-resume
        // attempt is isolated from ordinary IRC participation until it proves a
        // physical attachment. SESSION/CAP/QUIT remain available; PING returned
        // above so clients can keep the handshake transport alive.
        if (conn.resume_autojoin_deferred and
            conn.session.hasCap(.onyx_e2ee) and
            !self.attachmentHasReusableSession(id) and
            !std.ascii.eqlIgnoreCase(parsed.command, "SESSION") and
            !std.ascii.eqlIgnoreCase(parsed.command, "CAP") and
            !std.ascii.eqlIgnoreCase(parsed.command, "QUIT"))
        {
            try self.failReply(conn, "SESSION", "RESUME_PENDING", "complete exact SESSION RESUME before IRC participation");
            return;
        }

        // A per-client fault (oversized reply, malformed param) must close only
        // THAT connection — never escalate to runOnce and tear down the reactor.
        // `error.ControlByte` is such a fault: the outbound reply builders reject
        // reflecting a control byte into a prefix/command/param/trailing/target
        // (the CWE-93 CRLF/command-injection guard in dispatch.zig) — dropping
        // this client's reply, not faulting the shard.
        self.dispatchRegistered(id, conn, &parsed, line) catch |err| switch (err) {
            error.ControlByte,
            error.OutputTooSmall,
            error.InvalidNamesRoster,
            error.TextTooLong,
            error.NoSpaceLeft,
            error.OversizeLine,
            error.LineTooLong,
            => conn.closing = true,
            else => return err, // infra (OOM, ring) bubbles up
        };
        // CAP remains legal after registration. If onyx/e2ee was just
        // negotiated on a logged-in socket whose SessionStore attach could not
        // be retained, reject the capability boundary explicitly instead of
        // leaving a visible channel member that encrypted fan-out must omit.
        if (std.ascii.eqlIgnoreCase(parsed.command, "CAP") and
            !try self.enforceE2eeSessionEligibility(id, conn)) return;
    }

    fn labeledBulkCaptureCapacity(conn: *const ConnState, names: bool) ?usize {
        const inline_queued = conn.send_len - conn.send_offset;
        const queued = std.math.add(usize, inline_queued, conn.send_overflow.items.len) catch return null;
        if (queued >= conn.sendq_cap) return null;
        const remaining = conn.sendq_cap - queued;
        // NAMES completeness is bounded by the configured SendQ itself: do not
        // reintroduce the former ~520 KiB truncation through labeled-response.
        // Historical finite-row bulk commands retain their 65-arena command cap.
        return if (names) remaining else @min(default_reply_bytes * 65, remaining);
    }

    fn dispatchRegistered(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        parsed: *const irc_line.LineView,
        line: []const u8,
    ) !void {
        // Refresh the world's wall-clock so a channel created by this command
        // (JOIN/CREATE) gets a correct IRCX CREATION timestamp without the pure
        // world taking a clock dependency.
        self.world.clock_unix = @divFloor(platform.realtimeMillis(), 1000);

        // draft/multiline: a negotiating client's `BATCH +ref draft/multiline`
        // and its @batch-tagged PRIVMSG/NOTICE chunks are routed into the
        // per-conn reassembler instead of normal dispatch. Returns true when the
        // line was consumed by the multiline path.
        if (conn.session.hasCap(.multiline)) {
            if (try self.routeMultiline(id, conn, parsed, line)) return;
        }

        // Resolve via the module spine (SerpentRegistry + OroWasm). When the
        // client tagged this command with `@label` and negotiated the
        // labeled-response cap, its whole reply set is captured at the plaintext
        // seam and reframed under the label — a single tagged line, a
        // labeled-response BATCH, or a bare ACK for a command that replies
        // nothing — before it reaches the wire.
        var label_buf: [labeled_response.MAX_LABEL_LEN]u8 = undefined;
        const want_label: ?[]const u8 =
            if (conn.session.hasCap(.labeled_response)) labelTagValue(parsed, &label_buf) else null;

        if (MediaAuthorityTurn.selected(parsed) != null)
            return self.dispatchMediaAuthority(id, conn, parsed, line, want_label);

        if (want_label) |label| {
            var cap_buf: [default_reply_bytes]u8 = undefined;
            const names_label = std.ascii.eqlIgnoreCase(parsed.command, "NAMES");
            const bulk_label = std.ascii.eqlIgnoreCase(parsed.command, "CHATHISTORY") or
                std.ascii.eqlIgnoreCase(parsed.command, "SEARCH") or
                std.ascii.eqlIgnoreCase(parsed.command, "JOIN");
            const dynamic_capture_cap = if (bulk_label or names_label) cap: {
                const capacity = labeledBulkCaptureCapacity(conn, names_label) orelse {
                    self.poisonOwnedDelivery(conn);
                    return;
                };
                // The labeled emitter performs exact transport-framing
                // reservation after the plaintext command capture is complete.
                break :cap capacity;
            } else 0;
            const bulk_buf = if (bulk_label or names_label)
                self.allocator.alloc(u8, dynamic_capture_cap) catch {
                    self.poisonOwnedDelivery(conn);
                    return;
                }
            else
                null;
            defer if (bulk_buf) |storage| self.allocator.free(storage);
            var capture = ReplyCapture{ .buf = bulk_buf orelse &cap_buf };
            conn.reply_capture = &capture;
            const outcome = self.dispatchModules(id, conn, parsed, line) catch |err| {
                conn.reply_capture = null;
                return err;
            };
            conn.reply_capture = null; // restore the wire path before re-emitting
            if (outcome == .handled) {
                emitLabeledIssuer(conn, label, &capture, self.allocator) catch {
                    self.poisonOwnedDelivery(conn);
                };
                return;
            }
            // not_found: the spine emitted nothing into the capture; fall through
            // to the registration-handshake processor (unlabeled — those verbs
            // are not part of the post-registration labeled command set).
        } else if (try self.dispatchModules(id, conn, parsed, line) == .handled) {
            return;
        }

        // Everything daemon-owned is a SerpentRegistry command (resolved above).
        // The only remaining direct path is the registration-handshake processor
        // (dispatch.zig command_table: PASS/NICK/USER/CAP/AUTHENTICATE/PING/QUIT)
        // — those verbs must work both before and after registration, so they
        // live in the lower layer rather than the post-registration registry.
        var sink = QueueSink{ .conn = conn };
        try processLine(conn, line, &sink);
    }

    /// The real module spine still performs every registration/feature gate.
    /// This original physical dispatch owns the label before any handler stages
    /// its final bytes; a joined handler's issuer is never emitted a second time.
    fn dispatchMediaAuthority(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView, line: []const u8, selected_label: ?[]const u8) !void {
        const action = MediaAuthorityTurn.selected(parsed) orelse return error.BadState;
        if (current_media_authority_turn != null or conn.reply_capture != null or
            self.connFor(id) != conn) return error.BadState;
        var storage: [default_reply_bytes]u8 = undefined;
        defer std.crypto.secureZero(u8, &storage);
        var capture: ReplyCapture = .{ .buf = &storage };
        var turn: MediaAuthorityTurn = .{
            .server = self,
            .id = id,
            .conn = conn,
            .action = action,
            .channel = parsed.paramSlice()[1],
            .capture = &capture,
        };
        if (selected_label) |label| {
            if (label.len == 0 or label.len > turn.label_storage.len) return error.BadState;
            @memcpy(turn.label_storage[0..label.len], label);
            turn.label_len = label.len;
        }
        conn.reply_capture = &capture;
        current_media_authority_turn = &turn;
        const outcome = blk: {
            defer {
                current_media_authority_turn = null;
                conn.reply_capture = null;
            }
            break :blk try self.dispatchModules(id, conn, parsed, line);
        };
        if (turn.published) {
            std.debug.assert(outcome == .handled and !capture.overflowed and capture.len == 0);
            return;
        }
        if (outcome == .handled) {
            if (selected_label) |label| {
                emitLabeledIssuer(conn, label, &capture, self.allocator) catch self.poisonOwnedDelivery(conn);
            } else {
                if (capture.overflowed) return error.OutputTooSmall;
                if (capture.len != 0) try LinuxServer.appendHistoryReplay(conn, capture.captured());
            }
            return;
        }
        // Preserve the normal lower dispatch behavior if no module owns it.
        var sink = QueueSink{ .conn = conn };
        try processLine(conn, line, &sink);
    }

    const ModuleOutcome = enum { handled, not_found };

    /// Consult the module spine — the comptime SerpentRegistry first, then any
    /// loaded OroWasm control-plane plugin — for `parsed.command`. Emits the
    /// command's replies (and any gate-failure numeric) to `conn`, returning
    /// `.handled` when a spine owned the command (including a denied/disabled
    /// gate) and `.not_found` when neither claimed it. Output routes through
    /// `appendToConn`, so an active `reply_capture` diverts it for labeling.
    fn dispatchModules(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        parsed: *const irc_line.LineView,
        line: []const u8,
    ) !ModuleOutcome {
        // E2EEGROUP's live operator barrier is a server-owned extension of the
        // registered client command. Intercept its one-parameter control shape
        // before the ordinary four-parameter module minimum is applied; all
        // payload-bearing authoring records continue through SerpentRegistry.
        if (try self.handleE2eeGroupOperatorControl(conn, parsed)) return .handled;

        // SerpentRegistry module spine (strangler-fig): consult the comptime
        // module registry first. A migrated command is handled here.
        {
            var core = module_core.Core{
                .services = .{ .allocator = self.allocator, .config = &self.config },
                .server = self,
                .id = id,
                .conn = conn,
                .parsed = parsed,
                .line = line,
            };
            const caps = mod_registry.DispatchCaps{
                .registered = conn.session.registered(),
                .oper = conn.session.isOper(),
                .ircx = conn.ircx,
                .disabled_features = self.config.disabled_features,
            };
            switch (try module_manifest.Live.dispatchGated(&core, parsed.command, parsed.paramSlice(), caps)) {
                .handled => return .handled,
                .too_few_params => {
                    try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{parsed.command}, "Not enough parameters");
                    return .handled;
                },
                .denied => |reason| {
                    switch (reason) {
                        .needs_oper => try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied: operator privileges required"),
                        .needs_registered => try queueNumeric(conn, .ERR_NOTREGISTERED, &.{}, "You have not registered"),
                        .needs_ircx => try queueNumeric(conn, .ERR_UNKNOWNCOMMAND, &.{parsed.command}, "IRCX command requires ISIRCX"),
                    }
                    return .handled;
                },
                .disabled => {
                    try queueNumeric(conn, .ERR_UNKNOWNCOMMAND, &.{parsed.command}, "Command disabled by configuration");
                    return .handled;
                },
                .not_found => {},
            }
        }

        // OroWasm control-plane plugins: a loaded third-party plugin may own this
        // command. Consulted after the comptime registry misses; empty by default.
        if (self.wasm.count() > 0 and self.wasm.hasCommand(parsed.command)) {
            var wcore = module_core.Core{
                .services = .{ .allocator = self.allocator, .config = &self.config },
                .server = self,
                .id = id,
                .conn = conn,
                .parsed = parsed,
                .line = line,
            };
            const host = wasm_bridge.HostBindings{
                .ctx = &wcore,
                .reply = wasmReplyCb,
                .log = wasmLogCb,
                .now_ms = wasmNowCb,
            };
            switch (self.wasm.dispatch(parsed.command, parsed.paramSlice(), host)) {
                .handled => return .handled,
                .denied => {
                    try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{parsed.command}, "Plugin lacks the required capability");
                    return .handled;
                },
                .trap => {
                    try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{parsed.command}, "Plugin execution trapped");
                    return .handled;
                },
                .not_found => {},
            }
        }

        return .not_found;
    }

    /// Module-facing numeric reply: lets a SerpentRegistry module emit a numeric
    /// to a client through `Core.reply` without touching server internals.
    pub fn moduleNumeric(self: *LinuxServer, conn: *ConnState, code: Numeric, params: []const []const u8, trailing: []const u8) ServerError!void {
        _ = self;
        try queueNumeric(conn, code, params, trailing);
    }

    /// Module-facing raw line emit (already CRLF-terminated by the caller).
    pub fn moduleRaw(self: *LinuxServer, conn: *ConnState, bytes: []const u8) ServerError!void {
        _ = self;
        try appendToConn(conn, bytes);
    }

    /// Drive a module-lifecycle phase across every enabled module. Hook handlers
    /// (and lifecycle fns) receive `*LinuxServer` as their erased ctx. No module
    /// declares lifecycle fns yet, so this is a no-op walk today — but the spine
    /// is live so a module/plugin can opt in without further server changes.
    fn driveLifecycle(self: *LinuxServer, comptime phase: enum { init, ready }) void {
        inline for (module_manifest.enabled) |m| {
            const fn_opt = switch (phase) {
                .init => m.on_init,
                .ready => m.on_ready,
            };
            if (fn_opt) |f| f(self) catch |err| {
                srvLog("onyx-server: module {s} on_{s} failed: {s}\n", .{ m.id, @tagName(phase), @errorName(err) });
            };
        }
    }

    fn driveDeinit(self: *LinuxServer) void {
        inline for (module_manifest.enabled) |m| {
            if (m.on_deinit) |f| f(self);
        }
    }

    /// Fire the informational `client_registered` typed hook for a freshly
    /// welcomed client. Veto is N/A (informational). Errors are swallowed: a
    /// subscriber fault must never break registration.
    fn emitClientRegistered(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) void {
        var payload = mod_registry.ClientRegisteredPayload{
            .client_id = @as(u64, @bitCast(id)),
            .nick = conn.session.displayName(),
        };
        _ = module_manifest.Live.callHook(.client_registered, self, &payload) catch {};
    }

    /// A HOLDNICK reservation blocks `conn` from `nick` when the nick matches a
    /// reservation glob AND the user is neither an operator nor GRANT-exempt (a
    /// trusted hostmask). Returns the matched reservation when blocked. Fails
    /// closed if the user's mask can't be built.
    fn nickReservationBlocks(self: *LinuxServer, conn: *ConnState, nick: []const u8) ?ircx_saccess.Entry {
        const entry = self.saccess.matchHoldNick(nick) orelse return null;
        if (conn.session.isOper()) return null;
        var mask_buf: [256]u8 = undefined;
        const mask = clientPrefix(conn, &mask_buf) catch return entry;
        if (self.saccess.matchHostmask(.grant, mask) != null) return null;
        return entry;
    }

    /// Registered account names are identity claims, not guest nicknames. The
    /// account store is authoritative and the owner must have completed SASL
    /// before registration or a later NICK change may adopt the name.
    fn registeredNickRequiresAuthentication(self: *LinuxServer, conn: *ConnState, nick: []const u8) bool {
        const svc = self.account_services orelse return false;
        if (conn.session.account()) |account| {
            if (std.ascii.eqlIgnoreCase(account, nick)) return false;
        }
        _ = svc.accountInfo(nick) catch return false;
        return true;
    }

    fn registerConnNick(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) !void {
        const nick = conn.session.displayName();
        if (std.mem.eql(u8, nick, "*")) return;
        if (self.registeredNickRequiresAuthentication(conn, nick)) {
            try queueNumeric(conn, .ERR_ERRONEUSNICKNAME, &.{nick}, "Nickname is registered; authenticate as this account before using it");
            conn.close_reason = "Registered nickname requires authentication";
            conn.closing = true;
            return;
        }
        if (self.saccess.matchNick(nick)) |entry| {
            try queueNumeric(conn, .ERR_ERRONEUSNICKNAME, &.{nick}, serverAccessReason(entry, "Nickname blocked by SACCESS"));
            conn.closing = true;
            return;
        }
        if (self.nickReservationBlocks(conn, nick)) |entry| {
            try queueNumeric(conn, .ERR_ERRONEUSNICKNAME, &.{nick}, serverAccessReason(entry, "Nickname is reserved"));
            conn.closing = true;
            return;
        }
        if (self.nickDelayBlocks(conn, nick)) {
            try queueNumeric(conn, .ERR_UNAVAILRESOURCE, &.{nick}, "Nick is held (nick delay); try again shortly");
            conn.closing = true;
            return;
        }
        self.world.registerNick(nick, worldIdFromClient(id)) catch |err| switch (err) {
            error.NickInUse => {
                // Account-aware same-nick multi-session: if THIS connection is
                // SASL-authenticated and the existing holder of `nick` is a local
                // connection logged in to the SAME account, this is the same
                // identity attaching from another client/device — do NOT 433/close.
                // Let registration complete sharing the nick: the primary keeps
                // world ownership; this conn keeps displayName == nick and is added
                // to the account session group (trackSession) so DM/notice fan-out
                // reaches it. (NAMES dedup + mesh-wide same-nick are out of scope;
                // a second client may JOIN channels itself.)
                if (conn.session.account()) |acct| {
                    if (self.nickHeldBySameAccount(nick, acct, worldIdFromClient(id))) {
                        // Shared nick; the holder already notified MONITOR online.
                        return;
                    }
                }
                try queueNumeric(conn, .ERR_NICKNAMEINUSE, &.{nick}, "Nickname is already in use");
                conn.closing = true;
                return;
            },
            else => return err,
        };
        // This nick is now live: clear any nick-delay hold an oper / exempt class
        // bypassed, so a later expiry sweep cannot evict a stale entry for it.
        if (self.config.nick_delay_ms != 0) self.nick_delay.release(nick);
        // Notify any MONITOR watchers that this nick just came online. Best-effort:
        // a fanout failure (e.g. a watcher's send queue, or the >64-watcher path)
        // must never abort the registering client's own registration / welcome.
        self.monitorOnline(nick) catch {};
        // Gossip this user's PRESENCE to the mesh so cross-node DMs reach them even
        // when they are in no channel (channel membership alone wouldn't replicate
        // them). Idempotent + re-affirmed by the anti-entropy burst; withdrawn in
        // `broadcastQuit`. The same-account-share path returned above, so a second
        // session sharing the nick doesn't re-announce (the primary already did).
        self.announceMembership(presence_channel, nick, 0, true, membershipIdentityOf(conn), "");
        // Stamp the mesh-claim HLC for this session so a same-account cross-mesh
        // collision can tell the live session from a stale ghost (newest wins).
        conn.mesh_nick_hlc = self.nextMeshHlc();
    }

    /// Whether `nick` is currently held in the world by a LOCAL connection that
    /// is SASL-authenticated to the SAME `account` (case-insensitive account
    /// compare; both must be non-empty). `self_id` is excluded so a connection
    /// never matches itself. Used to admit a same-account same-nick multi-session
    /// attach instead of 433/closing the new connection.
    fn nickHeldBySameAccount(
        self: *LinuxServer,
        nick: []const u8,
        account: []const u8,
        self_id: world_model.ClientId,
    ) bool {
        if (account.len == 0) return false;
        const holder = self.world.findNick(nick) orelse return false;
        if (holder.eql(self_id)) return false;
        const holder_conn = self.connFor(clientIdFromWorld(holder)) orelse return false;
        const holder_acct = holder_conn.session.account() orelse return false;
        if (holder_acct.len == 0) return false;
        return std.ascii.eqlIgnoreCase(holder_acct, account);
    }

    /// Whether nick-delay refuses `conn`'s attempt to take `nick`. False when
    /// nick delay is disabled, the nick is not held (or its window lapsed), the
    /// requester is an operator or a `nick_delay_exempt` class, or the requester
    /// is authenticated to the account that owns the hold — a legitimate reclaim,
    /// which clears the hold.
    fn nickDelayBlocks(self: *LinuxServer, conn: *ConnState, nick: []const u8) bool {
        if (self.config.nick_delay_ms == 0) return false;
        const held = self.nick_delay.check(nick, self.nowMs()) orelse return false;
        if (conn.session.isOper()) return false;
        if (conn.class_policy.nick_delay_exempt) return false;
        if (held.owner) |owner| {
            if (conn.session.account()) |acct| {
                if (std.ascii.eqlIgnoreCase(owner, acct)) {
                    self.nick_delay.release(nick); // rightful owner reclaims it
                    return false;
                }
            }
        }
        return true;
    }

    /// Hold `conn`'s current world nick after it exits so it cannot be grabbed
    /// for `nick_delay_ms`. No-op when nick delay is disabled or the connection
    /// owns no world nick (anonymous / unregistered / a shared secondary
    /// session). Call before `world.removeClient`, while the nick still resolves.
    fn holdNickOnExit(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) void {
        if (self.config.nick_delay_ms == 0) return;
        const nick = self.world.nickOf(worldIdFromClient(id)) orelse return;
        const expires = self.nowMs() + @as(i64, @intCast(self.config.nick_delay_ms));
        self.nick_delay.hold(nick, expires, conn.session.account()) catch {};
    }

    /// Preserve a logical identity when one transport leaves but another local
    /// attachment of the same authenticated account+nick AND exact reusable token
    /// is still live. If the departing transport owns the nick lookup, transfer it
    /// atomically. Merge its channel memberships/modes into the successor before
    /// removal so the remaining client keeps receiving events and can participate
    /// everywhere the shared session was joined. Returns true when the identity
    /// remains. A null-token session has no reusable credential and therefore can
    /// never authorize a handoff to an otherwise-similar account session.
    fn handoffLiveSessionIdentity(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) !bool {
        const account = conn.session.account() orelse return false;
        const nick = conn.session.displayName();
        if (nick.len == 0 or std.mem.eql(u8, nick, "*")) return false;
        const cid = monitorIdFromClient(id);
        const handle = self.sessions.resumeHandleForClient(account, cid) orelse return false;
        if (tokenIsNull(handle.token)) return false;
        const rows = try self.sessions.copySessionsAlloc(self.allocator, account);
        defer self.allocator.free(rows);

        var successor_id: ?client_model.ClientId = null;
        for (rows) |row| {
            if (!row.attached or row.client == cid) continue;
            if (!std.crypto.timing_safe.eql(sessions_mod.Token, row.token, handle.token)) continue;
            const sibling_id = clientIdFromMonitor(row.client);
            // Bootstrap output belongs to the connection's owner reactor. A
            // foreign row is left absent here; the durable projector is retried
            // by that owner and atomically restores World state before emitting
            // self JOIN/topic/NAMES. Thus World membership is never visible on a
            // socket that missed its channel bootstrap.
            if (sibling_id.shard != self.rx().shard_id) continue;
            const sibling = self.connFor(sibling_id) orelse continue;
            if (sibling.closing or sibling.s2s != null or sibling.s2s_secured != null) continue;
            const sibling_account = sibling.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(sibling_account, account)) continue;
            if (!std.ascii.eqlIgnoreCase(sibling.session.displayName(), nick)) continue;
            successor_id = sibling_id;
            break;
        }
        const successor = successor_id orelse return false;
        const from_wid = worldIdFromClient(id);
        const to_wid = worldIdFromClient(successor);

        // Preserve the union of the departing attachment's channel authority.
        // Stage the complete image first: a later allocation failure must not
        // add only a prefix of channels and then fall through to ordinary QUIT.
        var restores: std.ArrayListUnmanaged(world_model.MemberRestore) = .empty;
        defer restores.deinit(self.allocator);
        var channels = self.world.channels.iterator();
        while (channels.next()) |entry| {
            const old_modes = self.world.memberModes(entry.key_ptr.*, from_wid) orelse continue;
            const current = self.world.memberModes(entry.key_ptr.*, to_wid) orelse world_model.MemberModes.empty();
            try restores.append(self.allocator, .{
                .channel = entry.key_ptr.*,
                .modes = .{ .bits = current.bits | old_modes.bits },
            });
        }
        if (self.world.nickOf(from_wid) != null) {
            const exact = [_]world_model.ClientId{ from_wid, to_wid };
            _ = try self.world.handoffExactSessionIdentity(nick, to_wid, &exact, restores.items);
        } else {
            _ = try self.world.restoreMembersBatchExisting(to_wid, restores.items);
        }
        return true;
    }

    /// Exact Store authority is the only remote proof that a portable logical
    /// session remains live. An arbitrary secured peer is not evidence that it
    /// holds this token and must never suppress the final QUIT.
    fn exactRemoteSessionAuthority(self: *LinuxServer, token: sessions_mod.Token) bool {
        if (tokenIsNull(token)) return false;
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        return self.session_replica_store.hasAttachedOriginOtherThan(token, self.config.node_id, now_wall);
    }

    /// Capture the final clean-QUIT image while World still contains every
    /// channel, then publish/ship that same complete state before handleQuit
    /// removes the local identity. closeConn observes the flag and must not
    /// replace it with a newer empty post-removal snapshot.
    fn prepareCleanSessionDetach(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) bool {
        if (conn.session_detach_prepared) return true;
        const account = conn.session.account() orelse return false;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return false;
        const encoded = self.encodeMigrationSnapshot(id, conn) orelse return false;
        defer self.allocator.free(encoded);
        if (!self.sessions.markDetachedWithSnapshot(account, monitorIdFromClient(id), encoded)) return false;
        conn.session_detach_prepared = true;

        if (self.config.session_migrate_on_detach and handle.portable and !tokenIsNull(handle.token)) {
            // shipSessionMigration publishes the v2 Store object first and marks
            // the token dirty on every failure. Because the detached snapshot is
            // already retained, the retry path can reproduce this exact image
            // after ConnState and World membership are gone.
            _ = self.shipSessionMigration(id, conn, account, handle.token);
        }
        return true;
    }

    fn connHasExactRemoteSessionAuthority(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) bool {
        if (!self.config.session_migrate_on_detach) return false;
        const account = conn.session.account() orelse return false;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return false;
        return handle.portable and self.exactRemoteSessionAuthority(handle.token);
    }

    /// Broadcast a JOIN to every channel member, choosing the IRCv3 extended-join
    /// form (`JOIN #c <account> :<realname>`) for recipients that negotiated the
    /// cap and the plain form otherwise. Server-time is applied per recipient.
    /// World projection (#6) producer: announce a local member's presence (or
    /// departure) in `channel` to every established S2S peer. Best-effort — a full
    /// link buffer or send-arm failure never faults the local membership change.
    /// On peer-link drop, notify local members with an IRCv3 netsplit BATCH of
    /// QUITs for the remote members that link had announced (instead of letting
    /// them silently vanish from NAMES). Must run BEFORE the link is deinit'd
    /// (it reads the link's remote roster). Best-effort. (#64)
    /// Deliver a peer-transition event to a channel's LOCAL members: the IRCv3
    /// BATCH form to members that negotiated the `batch` cap, and the equivalent
    /// un-batched lines to those that did not — a non-`batch` client must never
    /// receive `@batch=` framing or BATCH open/close it can't parse. Peer links
    /// are skipped. Routes via the shard-aware sink (local append or cross-shard
    /// handoff).
    fn deliverChannelBatchGated(self: *LinuxServer, channel: []const u8, batched: []const u8, plain: []const u8) void {
        var members = self.world.memberIterator(channel) orelse return;
        while (members.next()) |member| {
            const mid = clientIdFromWorld(member.*);
            const mc = self.connFor(mid) orelse continue;
            if (mc.s2s != null or mc.s2s_secured != null) continue; // skip peer links
            // Cap clients get the batched form; clients without `batch` — and cap
            // clients whose batch failed to render (empty) — fall back to the
            // un-batched lines so nobody is silently dropped.
            const bytes = if (mc.session.hasCap(.batch) and batched.len != 0) batched else plain;
            if (bytes.len == 0) continue;
            self.enqueueDelivery(mid, bytes) catch continue;
        }
    }

    fn netsplitOnPeerDrop(self: *LinuxServer, conn: *ConnState) void {
        const remote_name = if (conn.s2s_secured) |l| l.remoteName() else if (conn.s2s) |l| l.remoteName() else return;
        var cit = self.world.channelIterator();
        while (cit.next()) |cv| {
            const remote_members = if (conn.s2s_secured) |l|
                l.channelMembers(cv.name)
            else if (conn.s2s) |l|
                l.channelMembers(cv.name)
            else
                &.{};
            if (remote_members.len == 0) continue;

            // Chunk so an arbitrarily large channel never silently drops members
            // past a fixed cap; each chunk is one netsplit BATCH.
            var off: usize = 0;
            while (off < remote_members.len) {
                const chunk_end = @min(off + mesh_batch_chunk, remote_members.len);
                var ghosts: [mesh_batch_chunk]netsplit_batch.Ghost = undefined;
                var prefixes: [mesh_batch_chunk][420]u8 = undefined;
                var n: usize = 0;
                for (remote_members[off..chunk_end]) |m| {
                    // Never QUIT a nick that is still homed locally: a live local
                    // user cannot split away with a peer link. Such roster entries
                    // are membership echoes (e.g. the peer's MODE-status announce
                    // for one of OUR members), and a fabricated QUIT permanently
                    // removes the user from local clients' nicklists. (#64)
                    if (self.nickIsLiveLocal(m.nick)) continue;
                    // QUIT with the member's propagated real user@host when known,
                    // matching how the user was rendered while present.
                    const user: []const u8 = if (m.username.len != 0) m.username else "*";
                    const host: []const u8 = if (m.host.len != 0) m.host else remote_name;
                    const prefix = std.fmt.bufPrint(&prefixes[n], "{s}!{s}@{s}", .{ m.nick, user, host }) catch continue;
                    ghosts[n] = .{ .prefix = prefix, .nick = m.nick };
                    n += 1;
                }
                off = chunk_end;
                if (n == 0) continue;

                var ref_buf: [18]u8 = undefined;
                const ref = netsplit_batch.makeBatchRef(&ref_buf, mesh_batch_ref_seq.fetchAdd(1, .monotonic));
                var batch_buf: [mesh_batch_buf_len]u8 = undefined;
                var plain_buf: [mesh_batch_buf_len]u8 = undefined;
                const batched = netsplit_batch.writeNetsplit(&batch_buf, ref, self.serverName(), remote_name, ghosts[0..n]) catch continue;
                const plain = netsplit_batch.writeQuitsPlain(&plain_buf, self.serverName(), remote_name, ghosts[0..n]) catch continue;
                self.deliverChannelBatchGated(cv.name, batched, plain);
            }
        }
    }

    /// Burst all currently wired local mesh state to ONE peer link. This wrapper
    /// is shared by the one-shot link-establish burst and the periodic
    /// anti-entropy cadence so new state families have one re-sync hook.
    fn sendMeshStateBurstTo(self: *LinuxServer, conn: *ConnState) bool {
        if (!conn.isActiveMeshPeer()) return false;
        if (conn.mesh_burst_stage == .idle) conn.mesh_burst_stage = .membership;

        while (conn.mesh_burst_stage != .idle) {
            if (!conn.mesh_burst_stage_encoded) {
                // A producer may have failed after emitting an earlier row of
                // this family. Commit that complete-record prefix before retrying
                // the family; re-emitted CRDT rows are idempotent, while silently
                // advancing the stage would permanently omit the failed row.
                if (!self.flushMeshBurstStage(conn)) return false;
                const encoded = switch (conn.mesh_burst_stage) {
                    .idle => unreachable,
                    .membership => self.sendMembershipBurstTo(conn),
                    .mode_flags => self.sendChannelModeFlagsBurstTo(conn),
                    .mode_state => self.sendChannelModeStateBurstTo(conn),
                    .channel_props => self.sendChannelPropBurstTo(conn),
                    .entity_props => self.sendEntityPropBurstTo(conn),
                    .topics => self.sendTopicBurstTo(conn),
                    .opers => self.sendLocalOperBurstTo(conn),
                    .wards => self.sendMeshWardsTo(conn),
                    .clones => if (conn.s2s_secured) |link|
                        self.sendCloneAntiEntropy(conn, link)
                    else if (conn.s2s) |link|
                        self.sendCloneAntiEntropy(conn, link)
                    else
                        true,
                    .keytrans => if (conn.s2s_secured) |link|
                        self.sendKeyTransHeadOn(link)
                    else if (conn.s2s) |link|
                        self.sendKeyTransHeadOn(link)
                    else
                        true,
                };
                if (!encoded) {
                    // Preserve/flush any complete rows emitted before the
                    // failure, but leave the family uncommitted for a full retry.
                    _ = self.flushMeshBurstStage(conn);
                    return false;
                }
                conn.mesh_burst_stage_encoded = true;
            }
            if (!self.flushMeshBurstStage(conn)) return false;
            conn.mesh_burst_stage_encoded = false;
            conn.mesh_burst_stage = switch (conn.mesh_burst_stage) {
                .idle => unreachable,
                .membership => .mode_flags,
                .mode_flags => .mode_state,
                .mode_state => .channel_props,
                .channel_props => .entity_props,
                .entity_props => .topics,
                .topics => .opers,
                .opers => .wards,
                .wards => .clones,
                .clones => .keytrans,
                .keytrans => .idle,
            };
            if (conn.mesh_burst_stage == .idle and conn.mesh_burst_restart_pending) {
                conn.mesh_burst_restart_pending = false;
                conn.mesh_burst_stage = .membership;
            }
        }
        return true;
    }

    /// Drain one encoded burst family without dropping authenticated records.
    /// Secured links page by whole outer-record boundaries and retain the exact
    /// suffix across SendQ backpressure; plaintext rolling-old links retain the
    /// complete inner buffer until its one append succeeds.
    fn flushMeshBurstStage(self: *LinuxServer, conn: *ConnState) bool {
        if (conn.s2s_secured) |link| {
            while (link.outbound().len != 0) {
                const inline_queued = conn.send_len - conn.send_offset;
                const queued = std.math.add(usize, inline_queued, conn.send_overflow.items.len) catch {
                    conn.closing = true;
                    return false;
                };
                if (queued > conn.sendq_cap) {
                    conn.closing = true;
                    return false;
                }
                const available = conn.sendq_cap - queued;
                const prefix = link.outboundRecordPrefix(available);
                if (prefix.len == 0) {
                    // Ordinary congestion retries after the SendQ drains. One
                    // record larger than an empty server SendQ can never make
                    // progress and is a terminal configuration/protocol error.
                    if (queued == 0) conn.closing = true;
                    return false;
                }
                reserveRawAppendToConn(conn, prefix.len) catch return false;
                appendToConn(conn, prefix) catch {
                    conn.closing = true;
                    return false;
                };
                if (!link.consumeOutboundPrefix(prefix.len)) {
                    conn.closing = true;
                    return false;
                }
                if (conn.s2s_probe_pending) {
                    std.debug.assert(conn.s2s_probe_pending_bytes != 0);
                    if (prefix.len >= conn.s2s_probe_pending_bytes) {
                        // The prefix is a whole-record boundary and has crossed
                        // the exact end of the probe. Later records may remain in
                        // SecuredLink.outbound; they cannot delay this receipt
                        // clock or cause a fast answer to race a phantom deadline.
                        conn.s2s_probe_pending = false;
                        conn.s2s_probe_pending_bytes = 0;
                        conn.awaiting_pong = true;
                        conn.ping_sent_ms = self.nowMs();
                    } else {
                        conn.s2s_probe_pending_bytes -= prefix.len;
                    }
                }
                self.armSendIfNeeded(conn) catch {
                    conn.closing = true;
                    return false;
                };
            }
            return true;
        }
        if (conn.s2s) |link| {
            self.flushS2sOutbound(conn, link.outbound()) catch return false;
            link.clearOutbound();
        }
        return true;
    }

    const ChannelModeFlagSpec = struct {
        mode: world_model.ChannelMode,
        letter: u8,
        bit: u16,
    };

    const channel_mode_flag_specs = [_]ChannelModeFlagSpec{
        .{ .mode = .invite_only, .letter = 'i', .bit = 1 << 0 },
        .{ .mode = .moderated, .letter = 'm', .bit = 1 << 1 },
        .{ .mode = .no_external, .letter = 'n', .bit = 1 << 2 },
        .{ .mode = .topic_ops, .letter = 't', .bit = 1 << 3 },
        .{ .mode = .secret, .letter = 's', .bit = 1 << 4 },
        .{ .mode = .no_ctcp, .letter = 'C', .bit = 1 << 5 },
        .{ .mode = .no_notice, .letter = 'T', .bit = 1 << 6 },
        .{ .mode = .no_nick, .letter = 'N', .bit = 1 << 7 },
        .{ .mode = .free_invite, .letter = 'g', .bit = 1 << 8 },
        .{ .mode = .tls_only, .letter = 'S', .bit = 1 << 9 },
        .{ .mode = .mod_reg, .letter = 'M', .bit = 1 << 10 },
        .{ .mode = .news_wire, .letter = 'W', .bit = 1 << 11 },
        .{ .mode = .oper_only, .letter = 'O', .bit = 1 << 12 },
        .{ .mode = .admin_only, .letter = 'A', .bit = 1 << 13 },
    };
    const local_channel_policy_flag_mask: u16 = (1 << 2) | (1 << 3) | (1 << 12) | (1 << 13);

    /// The `+s` (secret) bit within the mesh-replicated channel MODE aggregate,
    /// derived from `channel_mode_flag_specs` so it can never drift from the wire
    /// layout. Used to hide a remote-only secret channel from LIST/LISTX.
    const channel_secret_flag_bit: u16 = blk: {
        for (channel_mode_flag_specs) |spec| {
            if (spec.mode == .secret) break :blk spec.bit;
        }
        @compileError("no secret flag in channel_mode_flag_specs");
    };

    fn channelModeFlagBits(self: *LinuxServer, channel: []const u8) u16 {
        var flags: u16 = 0;
        for (channel_mode_flag_specs) |spec| {
            if (self.world.channelHasFlag(channel, spec.mode)) flags |= spec.bit;
        }
        return flags;
    }

    fn setChannelModeFlagBits(self: *LinuxServer, channel: []const u8, flags: u16) void {
        const current = self.channelModeFlagBits(channel);
        const applied = (flags & ~local_channel_policy_flag_mask) | (current & local_channel_policy_flag_mask);
        if (((flags ^ current) & local_channel_policy_flag_mask) != 0) {
            self.traceLog(.info, .s2s, "remote channel mode aggregate ignored local policy flags");
        }
        for (channel_mode_flag_specs) |spec| {
            _ = self.world.setChannelFlag(channel, spec.mode, (applied & spec.bit) != 0) catch {};
        }
    }

    /// Burst the full local channel-member roster to ONE freshly-established peer
    /// link (the conn's s2s/s2s_secured), so the peer's NAMES/WHO is correct
    /// immediately rather than only after subsequent joins. Best-effort. (#65)
    fn sendMembershipBurstTo(self: *LinuxServer, conn: *ConnState) bool {
        if (!conn.isActiveMeshPeer()) return false;
        // Wall-clock mesh HLC — feeds route_table's cross-host LWW (nick/channel
        // keyed), so it must be recency-comparable, never monotonic (was the
        // per-host `self.nowMs()`, the membership-desync root cause). See nextMeshHlc.
        const hlc = self.nextMeshHlc();
        var generation_complete = true;
        var cit = self.world.channelIterator();
        while (cit.next()) |cv| {
            var members = self.world.memberIterator(cv.name) orelse continue;
            while (members.next()) |member| {
                const mconn = self.connFor(clientIdFromWorld(member.*)) orelse continue;
                if (mconn.s2s != null or mconn.s2s_secured != null) continue; // skip peer links
                // A restored portable attachment is deliberately invisible to
                // token-less anti-entropy until its exact signed Store row is
                // accepted. The dedicated deferred flush preserves strict
                // OFFER -> NICK -> MEMBERSHIP ordering and then clears this gate.
                if (mconn.session_mesh_announce_pending) {
                    generation_complete = false;
                    continue;
                }
                const nick = mconn.session.displayName();
                const status: u4 = @truncate((self.world.memberModes(cv.name, member.*) orelse world_model.MemberModes.empty()).bits);
                const ident = membershipIdentityOf(mconn);
                if (conn.s2s_secured) |link| {
                    link.sendMembership(cv.name, nick, status, hlc, true, ident, "") catch return false;
                } else if (conn.s2s) |link| {
                    link.sendMembership(cv.name, nick, status, hlc, true, ident, "") catch return false;
                }
            }
            if (self.world.bansOf(cv.name)) |entries| {
                for (entries) |entry| if (!self.sendChannelListToConn(conn, cv.name, .ban, entry.mask, entry.setter, entry.set_at, hlc, true)) return false;
            }
            if (self.world.exemptsOf(cv.name)) |entries| {
                for (entries) |entry| if (!self.sendChannelListToConn(conn, cv.name, .exempt, entry.mask, entry.setter, entry.set_at, hlc, true)) return false;
            }
            if (self.world.invexOf(cv.name)) |entries| {
                for (entries) |entry| if (!self.sendChannelListToConn(conn, cv.name, .invex, entry.mask, entry.setter, entry.set_at, hlc, true)) return false;
            }
            if (self.world.mutesOf(cv.name)) |entries| {
                for (entries) |entry| if (!self.sendChannelListToConn(conn, cv.name, .quiet, entry.mask, entry.setter, entry.set_at, hlc, true)) return false;
            }
        }
        // PRESENCE burst: announce every local registered user (channel or not) into
        // the peer's `presence_channel` roster so it can route cross-node DMs to them.
        // Reuses the signed MEMBERSHIP path; `presence_channel` is suppressed from all
        // user-visible emit, so it only ever populates the peer's route index. Runs on
        // link-establish AND the periodic anti-entropy resync (idempotent, HLC-keyed).
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const mc = &slot.value;
                if (mc.s2s != null or mc.s2s_secured != null) continue; // skip peer links
                if (!mc.session.registered()) continue;
                if (mc.session_mesh_announce_pending) {
                    generation_complete = false;
                    continue;
                }
                const pnick = mc.session.displayName();
                if (std.mem.eql(u8, pnick, "*")) continue;
                const pident = membershipIdentityOf(mc);
                if (conn.s2s_secured) |link| {
                    link.sendMembership(presence_channel, pnick, 0, hlc, true, pident, "") catch return false;
                } else if (conn.s2s) |link| {
                    link.sendMembership(presence_channel, pnick, 0, hlc, true, pident, "") catch return false;
                }
            }
        }
        // A pending live attachment was intentionally omitted until its signed
        // Store authority is publishable. Flush the complete PRESENT prefix but
        // leave this retryable stage uncommitted; certifying it as a complete
        // generation could false-PART the receiver's existing row.
        if (!generation_complete) return false;
        // Ordered after every PRESENT record above. On secured links this is an
        // authenticated inbound-generation proof; rolling-old peers skip the
        // unknown tag and therefore fail safe by retaining rows until upgraded.
        if (conn.s2s_secured) |link| {
            link.sendMembershipSync() catch return false;
        } else if (conn.s2s) |link| {
            link.sendMembershipSync() catch return false;
        }
        return true;
    }

    /// Burst aggregate local channel MODE flags to ONE freshly-established peer
    /// so a relink converges immediately instead of waiting for the next MODE.
    fn sendChannelModeFlagsBurstTo(self: *LinuxServer, conn: *ConnState) bool {
        if (!conn.isActiveMeshPeer()) return false;
        // Wall-clock mesh HLC — feeds route_table's cross-host LWW (nick/channel
        // keyed), so it must be recency-comparable, never monotonic (was the
        // per-host `self.nowMs()`, the membership-desync root cause). See nextMeshHlc.
        const hlc = self.nextMeshHlc();
        var cit = self.world.channelIterator();
        while (cit.next()) |cv| {
            const flags = self.channelModeFlagBits(cv.name);
            if (conn.s2s_secured) |link| {
                link.sendChannelModeFlags(cv.name, flags, hlc) catch return false;
            } else if (conn.s2s) |link| {
                link.sendChannelModeFlags(cv.name, flags, hlc) catch return false;
            }
        }
        return true;
    }

    const ChannelModeStateSnapshot = struct {
        private: bool = false,
        hidden: bool = false,
        ext_bits: u32 = 0,
        key_buf: [channel_mode_state_event.max_key_len]u8 = undefined,
        key_len: usize = 0,
        limit: ?u32 = null,
        throttle_joins: u16 = 0,
        throttle_secs: u32 = 0,
        forward_buf: [channel_mode_state_event.max_forward_len]u8 = undefined,
        forward_len: usize = 0,

        fn key(self: *const ChannelModeStateSnapshot) ?[]const u8 {
            return if (self.key_len == 0) null else self.key_buf[0..self.key_len];
        }

        fn forward(self: *const ChannelModeStateSnapshot) ?[]const u8 {
            return if (self.forward_len == 0) null else self.forward_buf[0..self.forward_len];
        }

        fn eql(self: *const ChannelModeStateSnapshot, other: *const ChannelModeStateSnapshot) bool {
            return self.private == other.private and
                self.hidden == other.hidden and
                self.ext_bits == other.ext_bits and
                self.limit == other.limit and
                self.throttle_joins == other.throttle_joins and
                self.throttle_secs == other.throttle_secs and
                optSliceEql(self.key(), other.key()) and
                optSliceEql(self.forward(), other.forward());
        }
    };

    fn optSliceEql(a: ?[]const u8, b: ?[]const u8) bool {
        if (a) |aa| {
            if (b) |bb| return std.mem.eql(u8, aa, bb);
            return false;
        }
        return b == null;
    }

    fn extModeBits(self: *LinuxServer, channel: []const u8) u32 {
        return @as(u32, @bitCast(self.world.channelExtModes(channel))) & channel_mode_state_event.ext_flag_mask;
    }

    fn channelModeStateSnapshot(self: *LinuxServer, channel: []const u8) ChannelModeStateSnapshot {
        var out = ChannelModeStateSnapshot{
            .private = self.world.isPrivate(channel),
            .hidden = self.world.isHidden(channel),
            .ext_bits = self.extModeBits(channel),
            .limit = self.world.channelLimit(channel),
        };
        if (self.world.channelKey(channel)) |key| {
            const n = @min(key.len, out.key_buf.len);
            @memcpy(out.key_buf[0..n], key[0..n]);
            out.key_len = n;
        }
        if (self.world.throttleOf(channel)) |throttle| {
            out.throttle_joins = throttle.joins;
            out.throttle_secs = throttle.secs;
        }
        if (self.world.forwardOf(channel)) |forward| {
            const n = @min(forward.len, out.forward_buf.len);
            @memcpy(out.forward_buf[0..n], forward[0..n]);
            out.forward_len = n;
        }
        return out;
    }

    fn channelModeStateEvent(self: *LinuxServer, channel: []const u8, hlc: u64) channel_mode_state_event.ChannelModeStateEvent {
        const throttle = self.world.throttleOf(channel);
        return .{
            .origin_node = self.config.node_id,
            .hlc = hlc,
            .channel = channel,
            .private = self.world.isPrivate(channel),
            .hidden = self.world.isHidden(channel),
            .ext_bits = self.extModeBits(channel),
            .key = self.world.channelKey(channel),
            .limit = self.world.channelLimit(channel),
            .throttle_joins = if (throttle) |t| t.joins else 0,
            .throttle_secs = if (throttle) |t| t.secs else 0,
            .forward = self.world.forwardOf(channel),
        };
    }

    fn sendChannelModeStateBurstTo(self: *LinuxServer, conn: *ConnState) bool {
        if (!conn.isActiveMeshPeer()) return false;
        const hlc = self.nextMeshHlc();
        var cit = self.world.channelIterator();
        while (cit.next()) |cv| {
            const ev = self.channelModeStateEvent(cv.name, hlc);
            if (conn.s2s_secured) |link| {
                link.sendChannelModeState(ev) catch return false;
            } else if (conn.s2s) |link| {
                link.sendChannelModeState(ev) catch return false;
            }
        }
        return true;
    }

    fn announceChannelModeState(self: *LinuxServer, channel: []const u8) void {
        const ev = self.channelModeStateEvent(channel, self.nextMeshHlc());
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    link.sendChannelModeState(ev) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendChannelModeState(ev) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    /// Monotonic-ish hybrid logical clock for LWW mesh facts: wall-clock millis in
    /// the high bits, a per-node sequence in the low 16 so two writes in the same
    /// millisecond still order. Shared by PROP and TOPIC propagation.
    fn nextMeshHlc(self: *LinuxServer) u64 {
        lockSpin(&self.mesh_clock_lock);
        defer self.mesh_clock_lock.unlock();
        self.msg_seq +%= 1;
        // Physical base is WALL-CLOCK, not monotonic: a mesh hlc is compared
        // against a PEER's hlc under LWW/collision resolution, and only real
        // (epoch) time is comparable across hosts. MeshClock guards against a
        // wall-clock step-back so our own writes never regress. The packed
        // layout `(physical << 16) | seq` is unchanged (wire-compatible).
        return self.mesh_clock.stamp(self.meshWallMs(), self.msg_seq);
    }

    fn observeSessionReplicaRevision(self: *LinuxServer, revision: session_replica_v2.Revision) void {
        lockSpin(&self.mesh_clock_lock);
        defer self.mesh_clock_lock.unlock();
        self.mesh_clock.observeChecked(
            revision.sequence,
            self.meshWallMs(),
            session_replica_v2.default_max_future_skew_ms,
        ) catch {};
    }

    fn nextChannelPropHlc(self: *LinuxServer) u64 {
        return self.nextMeshHlc();
    }

    /// Admit a remote property fact into the process causal high-water mark
    /// before mutating either the raw store or its LWW clock. This prevents a
    /// peer from pinning property state at `maxInt` (or far-future wall time),
    /// and guarantees the next locally-authored fact is strictly newer than
    /// every accepted remote channel/entity property fact.
    fn observeRemotePropertyHlc(self: *LinuxServer, remote_hlc: u64) bool {
        lockSpin(&self.mesh_clock_lock);
        defer self.mesh_clock_lock.unlock();
        self.mesh_clock.observeChecked(
            remote_hlc,
            self.meshWallMs(),
            mesh_clock_mod.default_max_future_skew_ms,
        ) catch return false;
        return true;
    }

    fn writeChannelPropClockKey(out: []u8, channel: []const u8, key: []const u8) ?[]const u8 {
        return prop_checkpoint.writeChannelClockKey(out, channel, key);
    }

    fn channelPropClock(self: *LinuxServer, channel: []const u8, key: []const u8) ?*ChannelPropClock {
        var key_buf: [ircx_prop_store.default_max_entity_id + 1 + ircx_prop_store.default_max_key]u8 = undefined;
        const map_key = writeChannelPropClockKey(&key_buf, channel, key) orelse return null;
        return self.channel_prop_clocks.getPtr(map_key);
    }

    fn allocChannelPropClockKey(self: *LinuxServer, channel: []const u8, key: []const u8) ![]u8 {
        const out = try self.allocator.alloc(u8, channel.len + 1 + key.len);
        errdefer self.allocator.free(out);
        const written = writeChannelPropClockKey(out, channel, key) orelse return error.OutOfMemory;
        return out[0..written.len];
    }

    /// LWW-record a channel PROP clock, storing the ORIGINAL author's
    /// `origin_node` and the self-contained multi-hop origin `(pubkey, sig)` so a
    /// later re-broadcast/burst re-emits the original author's signature verbatim.
    /// `origin_pubkey`/`origin_sig` are empty ("") on the legacy unsigned path.
    /// On an LWW overwrite the previous owner + signature bytes are freed and the
    /// new ones duped in; the insert path dupes all owned bytes. Lifetime is
    /// balanced against `ChannelPropClock.deinit`.
    fn recordChannelPropClock(
        self: *LinuxServer,
        channel: []const u8,
        key: []const u8,
        owner: []const u8,
        hlc: u64,
        present: bool,
        origin_node: u64,
        origin_pubkey: []const u8,
        origin_sig: []const u8,
    ) bool {
        if (self.channelPropClock(channel, key)) |entry| {
            if (hlc <= entry.hlc) return false;
            // Stage all three new owned copies BEFORE mutating the entry so a mid-
            // way allocation failure leaves the existing entry intact (no partial
            // overwrite, no leak).
            const owner_copy = self.allocator.dupe(u8, owner) catch return false;
            const pubkey_copy = self.allocator.dupe(u8, origin_pubkey) catch {
                self.allocator.free(owner_copy);
                return false;
            };
            const sig_copy = self.allocator.dupe(u8, origin_sig) catch {
                self.allocator.free(owner_copy);
                self.allocator.free(pubkey_copy);
                return false;
            };
            self.allocator.free(entry.owner);
            self.allocator.free(entry.origin_pubkey);
            self.allocator.free(entry.origin_sig);
            entry.owner = owner_copy;
            entry.origin_pubkey = pubkey_copy;
            entry.origin_sig = sig_copy;
            entry.hlc = hlc;
            entry.present = present;
            entry.origin_node = origin_node;
            return true;
        }

        const map_key = self.allocChannelPropClockKey(channel, key) catch return false;
        const channel_copy = self.allocator.dupe(u8, channel) catch {
            self.allocator.free(map_key);
            return false;
        };
        const key_copy = self.allocator.dupe(u8, key) catch {
            self.allocator.free(map_key);
            self.allocator.free(channel_copy);
            return false;
        };
        const owner_copy = self.allocator.dupe(u8, owner) catch {
            self.allocator.free(map_key);
            self.allocator.free(channel_copy);
            self.allocator.free(key_copy);
            return false;
        };
        const pubkey_copy = self.allocator.dupe(u8, origin_pubkey) catch {
            self.allocator.free(map_key);
            self.allocator.free(channel_copy);
            self.allocator.free(key_copy);
            self.allocator.free(owner_copy);
            return false;
        };
        const sig_copy = self.allocator.dupe(u8, origin_sig) catch {
            self.allocator.free(map_key);
            self.allocator.free(channel_copy);
            self.allocator.free(key_copy);
            self.allocator.free(owner_copy);
            self.allocator.free(pubkey_copy);
            return false;
        };

        self.channel_prop_clocks.putNoClobber(self.allocator, map_key, .{
            .channel = channel_copy,
            .key = key_copy,
            .owner = owner_copy,
            .hlc = hlc,
            .present = present,
            .origin_node = origin_node,
            .origin_pubkey = pubkey_copy,
            .origin_sig = sig_copy,
        }) catch {
            self.allocator.free(map_key);
            self.allocator.free(channel_copy);
            self.allocator.free(key_copy);
            self.allocator.free(owner_copy);
            self.allocator.free(pubkey_copy);
            self.allocator.free(sig_copy);
            return false;
        };
        return true;
    }

    /// The `PropOrigin` to emit for a stored clock in a burst. Returns the stored
    /// ORIGINAL author's `(node, pubkey, sig)` only when the signature still
    /// verifies against the EXACT `(present, value, owner, hlc)` tuple being
    /// emitted (so a re-broadcast preserves the original author's signature). When
    /// the live tuple has diverged from the signed one, or the fact is unsigned,
    /// returns an unsigned origin carrying just the original `origin_node` (legacy
    /// LWW path at the receiver) — never a stale signature that cannot verify.
    fn burstPropOrigin(
        self: *LinuxServer,
        clock: *const ChannelPropClock,
        present: bool,
        value: []const u8,
        owner: []const u8,
    ) s2s_peer_mod.S2sPeer.PropOrigin {
        if (clock.origin_pubkey.len == 0) return .{ .node = clock.origin_node };
        const ev = channel_prop_event.ChannelPropEvent{
            .present = present,
            .origin_node = clock.origin_node,
            .hlc = clock.hlc,
            .channel = clock.channel,
            .key = clock.key,
            .value = value,
            .owner = owner,
            .origin_pubkey = clock.origin_pubkey,
            .origin_sig = clock.origin_sig,
        };
        const outcome = channel_prop_event.verifyOrigin(self.allocator, ev) catch return .{ .node = clock.origin_node };
        if (outcome == .verified) {
            return .{ .node = clock.origin_node, .pubkey = clock.origin_pubkey, .sig = clock.origin_sig };
        }
        return .{ .node = clock.origin_node };
    }

    // ---- user/member (ENTITY_PROP) LWW clocks -----------------------------
    //
    // Parallel to the channel-prop clock machinery above. A separate map keyed by
    // `kind || entity || key` (the kind tag disambiguates a user prop on "alice"
    // from a member prop whose entity is "alice"-ish, and keeps the namespace
    // distinct from channel clocks which live in their own map).

    fn writeEntityPropClockKey(out: []u8, kind: entity_prop_event.EntityKind, entity: []const u8, key: []const u8) ?[]const u8 {
        return prop_checkpoint.writeEntityClockKey(out, kind, entity, key);
    }

    fn entityPropClock(self: *LinuxServer, kind: entity_prop_event.EntityKind, entity: []const u8, key: []const u8) ?*EntityPropClock {
        var key_buf: [1 + entity_prop_event.max_entity_len + 1 + ircx_prop_store.default_max_key]u8 = undefined;
        const map_key = writeEntityPropClockKey(&key_buf, kind, entity, key) orelse return null;
        return self.entity_prop_clocks.getPtr(map_key);
    }

    fn allocEntityPropClockKey(self: *LinuxServer, kind: entity_prop_event.EntityKind, entity: []const u8, key: []const u8) ![]u8 {
        const out = try self.allocator.alloc(u8, 1 + entity.len + 1 + key.len);
        errdefer self.allocator.free(out);
        const written = writeEntityPropClockKey(out, kind, entity, key) orelse return error.OutOfMemory;
        return out[0..written.len];
    }

    /// Pre-staged LWW clock bytes. All fallible allocations happen here; the
    /// later commit only swaps pointers or `putAssumeCapacity`.
    const StagedEntityPropClock = struct {
        replace: ?*EntityPropClock = null,
        map_key: []u8 = &.{},
        entity: []u8 = &.{},
        key: []u8 = &.{},
        owner: []u8,
        origin_pubkey: []u8,
        origin_sig: []u8,
        kind: entity_prop_event.EntityKind,
        hlc: u64,
        present: bool,
        origin_node: u64,

        fn discard(self: *StagedEntityPropClock, allocator: std.mem.Allocator) void {
            if (self.replace == null) {
                if (self.map_key.len != 0) allocator.free(self.map_key);
                if (self.entity.len != 0) allocator.free(self.entity);
                if (self.key.len != 0) allocator.free(self.key);
            }
            allocator.free(self.owner);
            allocator.free(self.origin_pubkey);
            allocator.free(self.origin_sig);
            self.* = undefined;
        }
    };

    fn stageEntityPropClock(
        self: *LinuxServer,
        kind: entity_prop_event.EntityKind,
        entity: []const u8,
        key: []const u8,
        owner: []const u8,
        hlc: u64,
        present: bool,
        origin_node: u64,
        origin_pubkey: []const u8,
        origin_sig: []const u8,
    ) ?StagedEntityPropClock {
        if (self.entityPropClock(kind, entity, key)) |existing| {
            if (hlc <= existing.hlc) return null;
            const owner_copy = self.allocator.dupe(u8, owner) catch return null;
            const pubkey_copy = self.allocator.dupe(u8, origin_pubkey) catch {
                self.allocator.free(owner_copy);
                return null;
            };
            const sig_copy = self.allocator.dupe(u8, origin_sig) catch {
                self.allocator.free(owner_copy);
                self.allocator.free(pubkey_copy);
                return null;
            };
            return .{
                .replace = existing,
                .owner = owner_copy,
                .origin_pubkey = pubkey_copy,
                .origin_sig = sig_copy,
                .kind = kind,
                .hlc = hlc,
                .present = present,
                .origin_node = origin_node,
            };
        }

        self.entity_prop_clocks.ensureUnusedCapacity(self.allocator, 1) catch return null;
        const map_key = self.allocEntityPropClockKey(kind, entity, key) catch return null;
        const entity_copy = self.allocator.dupe(u8, entity) catch {
            self.allocator.free(map_key);
            return null;
        };
        const key_copy = self.allocator.dupe(u8, key) catch {
            self.allocator.free(map_key);
            self.allocator.free(entity_copy);
            return null;
        };
        const owner_copy = self.allocator.dupe(u8, owner) catch {
            self.allocator.free(map_key);
            self.allocator.free(entity_copy);
            self.allocator.free(key_copy);
            return null;
        };
        const pubkey_copy = self.allocator.dupe(u8, origin_pubkey) catch {
            self.allocator.free(map_key);
            self.allocator.free(entity_copy);
            self.allocator.free(key_copy);
            self.allocator.free(owner_copy);
            return null;
        };
        const sig_copy = self.allocator.dupe(u8, origin_sig) catch {
            self.allocator.free(map_key);
            self.allocator.free(entity_copy);
            self.allocator.free(key_copy);
            self.allocator.free(owner_copy);
            self.allocator.free(pubkey_copy);
            return null;
        };
        return .{
            .map_key = map_key,
            .entity = entity_copy,
            .key = key_copy,
            .owner = owner_copy,
            .origin_pubkey = pubkey_copy,
            .origin_sig = sig_copy,
            .kind = kind,
            .hlc = hlc,
            .present = present,
            .origin_node = origin_node,
        };
    }

    fn commitStagedEntityPropClock(self: *LinuxServer, staged: StagedEntityPropClock) void {
        if (staged.replace) |existing| {
            self.allocator.free(existing.owner);
            self.allocator.free(existing.origin_pubkey);
            self.allocator.free(existing.origin_sig);
            existing.owner = staged.owner;
            existing.origin_pubkey = staged.origin_pubkey;
            existing.origin_sig = staged.origin_sig;
            existing.hlc = staged.hlc;
            existing.present = staged.present;
            existing.origin_node = staged.origin_node;
            return;
        }
        self.entity_prop_clocks.putAssumeCapacity(staged.map_key, .{
            .kind = staged.kind,
            .entity = staged.entity,
            .key = staged.key,
            .owner = staged.owner,
            .hlc = staged.hlc,
            .present = staged.present,
            .origin_node = staged.origin_node,
            .origin_pubkey = staged.origin_pubkey,
            .origin_sig = staged.origin_sig,
        });
    }

    /// LWW-record a user/member PROP clock. The ENTITY_PROP counterpart of
    /// `recordChannelPropClock`: stores the ORIGINAL author's `origin_node` + the
    /// self-contained multi-hop `(pubkey, sig)` so a later re-broadcast/burst
    /// re-emits the original author's signature verbatim. Empty on the legacy
    /// unsigned path. Owned-bytes lifetime is balanced against
    /// `EntityPropClock.deinit`; on an LWW overwrite the previous owner + signature
    /// are freed and the new ones duped in. Staged-before-mutate so a mid-way alloc
    /// failure leaves the existing entry intact.
    fn recordEntityPropClock(
        self: *LinuxServer,
        kind: entity_prop_event.EntityKind,
        entity: []const u8,
        key: []const u8,
        owner: []const u8,
        hlc: u64,
        present: bool,
        origin_node: u64,
        origin_pubkey: []const u8,
        origin_sig: []const u8,
    ) bool {
        const staged = self.stageEntityPropClock(
            kind,
            entity,
            key,
            owner,
            hlc,
            present,
            origin_node,
            origin_pubkey,
            origin_sig,
        ) orelse return false;
        self.commitStagedEntityPropClock(staged);
        return true;
    }

    /// The `PropOrigin` to emit for a stored ENTITY_PROP clock in a burst. The
    /// counterpart of `burstPropOrigin`: re-emits the ORIGINAL author's stored
    /// `(node, pubkey, sig)` only when the signature still verifies against the
    /// EXACT `(present, value, owner, hlc)` tuple being emitted; otherwise an
    /// unsigned origin carrying just `origin_node` (never a stale signature).
    fn burstEntityPropOrigin(
        self: *LinuxServer,
        clock: *const EntityPropClock,
        present: bool,
        value: []const u8,
        owner: []const u8,
    ) s2s_peer_mod.S2sPeer.PropOrigin {
        if (clock.origin_pubkey.len == 0) return .{ .node = clock.origin_node };
        const ev = entity_prop_event.EntityPropEvent{
            .present = present,
            .kind = clock.kind,
            .origin_node = clock.origin_node,
            .hlc = clock.hlc,
            .entity = clock.entity,
            .key = clock.key,
            .value = value,
            .owner = owner,
            .origin_pubkey = clock.origin_pubkey,
            .origin_sig = clock.origin_sig,
        };
        const outcome = entity_prop_event.verifyOrigin(self.allocator, ev) catch return .{ .node = clock.origin_node };
        if (outcome == .verified) {
            return .{ .node = clock.origin_node, .pubkey = clock.origin_pubkey, .sig = clock.origin_sig };
        }
        return .{ .node = clock.origin_node };
    }

    /// Fan a user/member PROP fact out to every established peer link over
    /// ENTITY_PROP. The counterpart of `announceChannelProp`.
    fn announceEntityProp(
        self: *LinuxServer,
        kind: entity_prop_event.EntityKind,
        entity: []const u8,
        key: []const u8,
        value: []const u8,
        owner: []const u8,
        hlc: u64,
        present: bool,
        origin: s2s_peer_mod.S2sPeer.PropOrigin,
    ) void {
        if (isReadMarkerPropKey(key)) return;
        if (kind == .user and account_identity.isReservedNamespace(key)) return;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    link.sendEntityProp(kind, entity, key, value, owner, hlc, present, origin) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendEntityProp(kind, entity, key, value, owner, hlc, present, origin) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    const DurableDeviceMutationOutcome = enum {
        committed,
        not_logged_in,
        owner_mismatch,
        invalid_fact,
        signer_unavailable,
        durable_unavailable,
        stale,
        replay,
        equivocation,
        preadmission_failed,
        restart_required,
    };

    /// Recognize the reserved namespace case-insensitively because PROP storage
    /// folds keys. Without this gate `E2EE.DEVICE.foo` could bypass the durable
    /// writer and overwrite the same folded live row as `e2ee.device.foo`.
    fn isReservedDevicePropPrefix(raw: []const u8) bool {
        return raw.len >= e2ee_policy.device_prop_prefix.len and
            std.ascii.eqlIgnoreCase(raw[0..e2ee_policy.device_prop_prefix.len], e2ee_policy.device_prop_prefix);
    }

    fn canonicalDevicePropKey(raw: []const u8, out: *[e2ee_policy.device_prop_prefix.len + e2ee_policy.max_device_id_len]u8) ?[]const u8 {
        if (!isReservedDevicePropPrefix(raw) or
            raw.len <= e2ee_policy.device_prop_prefix.len or
            raw.len > e2ee_policy.device_prop_prefix.len + e2ee_policy.max_device_id_len)
            return null;
        const device_id = raw[e2ee_policy.device_prop_prefix.len..];
        if (!e2ee_policy.validDeviceId(device_id)) return null;
        @memcpy(out[0..e2ee_policy.device_prop_prefix.len], e2ee_policy.device_prop_prefix);
        _ = std.ascii.lowerString(out[e2ee_policy.device_prop_prefix.len..][0..device_id.len], device_id);
        return out[0 .. e2ee_policy.device_prop_prefix.len + device_id.len];
    }

    fn validDurableDeviceValue(key: []const u8, value: []const u8) bool {
        const parsed = splitE2eeDeviceValue(value) orelse return false;
        const canonical_device = key[e2ee_policy.device_prop_prefix.len..];
        const directory = @import("../proto/e2ee_device_directory.zig");
        if (directory.isStoredAlgorithm(parsed.algorithm)) {
            const odd1 = directory.parseCanonical(parsed.public_key) orelse return false;
            var derived_buf: [directory.device_id_len]u8 = undefined;
            const derived = directory.deviceId(odd1, &derived_buf);
            if (!std.ascii.eqlIgnoreCase(canonical_device, derived)) return false;
        } else {
            e2ee_policy.validateAdvertisement(
                canonical_device,
                parsed.algorithm,
                parsed.public_key,
            ) catch return false;
        }
        var canonical_buf: [e2ee_policy.max_device_value_len]u8 = undefined;
        const canonical = e2ee_policy.deviceValue(parsed.algorithm, parsed.public_key, &canonical_buf) orelse return false;
        return std.mem.eql(u8, canonical, value);
    }

    /// Sole local authoring transaction for user `e2ee.device.*` facts.
    ///
    /// The authenticated account supplies both entity and owner. The live PROP
    /// mutation and exact signed ENTITY_PROP clock are allocation-complete before
    /// Services crosses the DPROP1 durable cut. Only `.committed` publishes those
    /// prepared live structures, after which notification and mesh fanout reuse
    /// the exact tuple committed durably. A durable ambiguity permanently poisons
    /// this server instance; retrying could publish the opposite of WAL replay.
    fn commitLocalDurableDeviceProp(
        self: *LinuxServer,
        conn: *ConnState,
        requested_entity: ?ircx_prop_store.Entity,
        raw_key: []const u8,
        value: []const u8,
        present: bool,
    ) DurableDeviceMutationOutcome {
        if (self.durable_device_restart_required) return .restart_required;
        const raw_account = conn.session.account() orelse return .not_logged_in;
        const canonical_account = services_mod.canonicalAccount(raw_account) catch return .invalid_fact;
        const account = canonical_account.asSlice();
        if (requested_entity) |requested| {
            if (requested.kind != .user or !std.ascii.eqlIgnoreCase(requested.id, account))
                return .owner_mismatch;
        }

        var key_buf: [e2ee_policy.device_prop_prefix.len + e2ee_policy.max_device_id_len]u8 = undefined;
        const key = canonicalDevicePropKey(raw_key, &key_buf) orelse return .invalid_fact;
        if (present and !validDurableDeviceValue(key, value)) return .invalid_fact;
        if (!present and value.len != 0) return .invalid_fact;

        const svc = self.account_services orelse return .durable_unavailable;
        const ident = self.config.node_identity orelse return .signer_unavailable;
        const origin_node = ident.shortId();
        if (origin_node == 0) return .signer_unavailable;
        const hlc = self.nextChannelPropHlc();
        var pubkey_buf: [entity_prop_event.pubkey_len]u8 = undefined;
        var sig_buf: [entity_prop_event.sig_len]u8 = undefined;
        var event = entity_prop_event.EntityPropEvent{
            .present = present,
            .kind = .user,
            .origin_node = origin_node,
            .hlc = hlc,
            .entity = account,
            .key = key,
            .value = if (present) value else "",
            .owner = account,
        };
        const transcript = entity_prop_event.originTranscript(self.allocator, event) catch return .signer_unavailable;
        defer self.allocator.free(transcript);
        entity_prop_event.signInPlace(&event, &ident.sign_kp, transcript, &pubkey_buf, &sig_buf) catch
            return .signer_unavailable;

        const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
        var prepared_set: ?ircx_prop_store.DefaultStore.PreparedSetProp = null;
        defer if (prepared_set) |*prepared| prepared.deinit();
        var prepared_delete: ?ircx_prop_store.DefaultStore.PreparedDeleteProp = null;
        defer if (prepared_delete) |prepared| prepared.deinit();
        if (present) {
            prepared_set = self.props.prepareSetProp(entity, key, value, .{ .id = account, .access = .user }) catch
                return .preadmission_failed;
        } else {
            prepared_delete = self.props.prepareDeleteProp(entity, key) catch
                return .preadmission_failed;
        }

        var staged_clock = self.stageEntityPropClock(
            .user,
            account,
            key,
            account,
            hlc,
            present,
            event.origin_node,
            event.origin_pubkey,
            event.origin_sig,
        ) orelse return .preadmission_failed;
        var clock_committed = false;
        defer if (!clock_committed) staged_clock.discard(self.allocator);

        switch (svc.commitLocalDurableDeviceFact(event)) {
            .committed => {},
            .disabled => return .durable_unavailable,
            .stale => return .stale,
            .replay => return .replay,
            .equivocation => return .equivocation,
            .preadmission => return .preadmission_failed,
            .restart_required => {
                self.durable_device_restart_required = true;
                srvLog("CRITICAL: DPROP1 durable device-property outcome is ambiguous/fatal; stopping for OroStore reopen\n", .{});
                self.traceLog(.warn, .storage, "CRITICAL DPROP1 durable outcome requires OroStore reopen");
                if (self.shutdown) |run| self.requestStop(run);
                return .restart_required;
            },
        }

        if (prepared_set) |*prepared| {
            _ = prepared.commit();
        } else {
            _ = prepared_delete.?.commit();
        }
        self.commitStagedEntityPropClock(staged_clock);
        clock_committed = true;
        self.notifyLocalPropChange(conn, entity, key, if (present) value else "");
        self.announceEntityProp(
            .user,
            account,
            key,
            if (present) value else "",
            account,
            hlc,
            present,
            .{ .node = event.origin_node, .pubkey = event.origin_pubkey, .sig = event.origin_sig },
        );
        return .committed;
    }

    fn durableDeviceFailureReply(
        self: *LinuxServer,
        conn: *ConnState,
        command: []const u8,
        outcome: DurableDeviceMutationOutcome,
    ) !void {
        return switch (outcome) {
            .committed => {},
            .not_logged_in => self.failReply(conn, command, "NOT_LOGGED_IN", "Log in before managing E2EE device keys"),
            .owner_mismatch => self.failReply(conn, command, "DEVICE_OWNER_MISMATCH", "Device keys may only be changed by their authenticated account"),
            .invalid_fact => self.failReply(conn, command, "BAD_DEVICE_FACT", "Device property key or value is invalid"),
            .signer_unavailable => self.failReply(conn, command, "SIGNER_UNAVAILABLE", "Signed device-property authority is unavailable"),
            .durable_unavailable => self.failReply(conn, command, "DURABLE_UNAVAILABLE", "Durable device-property state is unavailable"),
            .stale => self.failReply(conn, command, "STALE_FACT", "Durable device-property state is newer"),
            .replay => self.failReply(conn, command, "REPLAY", "Device-property fact was already committed"),
            .equivocation => self.failReply(conn, command, "EQUIVOCATION", "Conflicting device-property fact was rejected"),
            .preadmission_failed => self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Device-property transaction could not be prepared"),
            .restart_required => self.failReply(conn, command, "RESTART_REQUIRED", "Durable device-property outcome requires store reopen"),
        };
    }

    fn durableDeviceNumericReply(
        self: *LinuxServer,
        conn: *ConnState,
        entity: ircx_prop_store.Entity,
        outcome: DurableDeviceMutationOutcome,
    ) !void {
        _ = self;
        return switch (outcome) {
            .committed => {},
            .not_logged_in, .owner_mismatch => queueNumeric(conn, .ERR_NOACCESS, &.{entity.id}, "Device keys may only be changed by their authenticated account"),
            .invalid_fact => queueNumeric(conn, .ERR_BADPROPERTY, &.{entity.id}, "Invalid device property"),
            .stale, .replay, .equivocation => queueNumeric(conn, .ERR_SECURITY, &.{entity.id}, "Device property failed durable security admission"),
            .signer_unavailable, .durable_unavailable, .preadmission_failed, .restart_required => queueNumeric(conn, .ERR_RESOURCE, &.{entity.id}, "Durable device-property authority is unavailable"),
        };
    }

    /// Sign + record + announce a freshly LOCALLY-authored user/member PROP fact.
    /// Shared by the PROP set and delete paths in `handleProp` so both fan a signed
    /// ENTITY_PROP out to the mesh and seed a local clock for later bursts.
    fn propagateLocalEntityProp(
        self: *LinuxServer,
        present: bool,
        store_kind: ircx_prop_store.EntityKind,
        entity: []const u8,
        key: []const u8,
        value: []const u8,
        owner: []const u8,
    ) void {
        self.propagateLocalEntityPropAt(present, store_kind, entity, key, value, owner, self.nextChannelPropHlc());
    }

    fn propagateLocalEntityPropAt(
        self: *LinuxServer,
        present: bool,
        store_kind: ircx_prop_store.EntityKind,
        entity: []const u8,
        key: []const u8,
        value: []const u8,
        owner: []const u8,
        hlc: u64,
    ) void {
        const kind = entity_prop_event.EntityKind.fromStoreKind(store_kind) orelse return;
        var pk_buf: [entity_prop_event.pubkey_len]u8 = undefined;
        var sig_buf: [entity_prop_event.sig_len]u8 = undefined;
        const ps = self.signLocalEntityProp(present, kind, entity, key, value, owner, hlc, &pk_buf, &sig_buf);
        if (self.recordEntityPropClock(kind, entity, key, owner, hlc, present, ps.node, ps.pubkey, ps.sig)) {
            self.announceEntityProp(kind, entity, key, value, owner, hlc, present, .{ .node = ps.node, .pubkey = ps.pubkey, .sig = ps.sig });
        }
    }

    /// Account + audit a dropped remote ENTITY_PROP fact whose self-contained
    /// multi-hop origin signature failed. Reuses the daemon-level multi-hop reject
    /// counter (`rejected_relay_signatures`).
    fn recordEntityPropSignatureReject(self: *LinuxServer, ch: anytype, reason: []const u8) void {
        self.rejected_relay_signatures +|= 1;
        var buf: [256]u8 = undefined;
        const line = std.fmt.bufPrint(
            &buf,
            "dropped ENTITY_PROP {s}/{s} claiming origin {d}: {s}",
            .{ ch.entity, ch.key, ch.origin_node, reason },
        ) catch "dropped ENTITY_PROP with bad origin signature";
        self.traceLog(.warn, .s2s, line);
    }

    /// Verify an inbound ENTITY_PROP fact's self-contained multi-hop origin
    /// signature. The counterpart of `channelPropOriginVerified`. Fails CLOSED on
    /// an allocation failure during verification.
    fn entityPropOriginVerified(self: *LinuxServer, ch: anytype) bool {
        const ev = entity_prop_event.EntityPropEvent{
            .present = ch.present,
            .kind = ch.kind,
            .origin_node = ch.origin_node,
            .hlc = ch.hlc,
            .entity = ch.entity,
            .key = ch.key,
            .value = ch.value,
            .owner = ch.owner,
            .origin_pubkey = ch.origin_pubkey,
            .origin_sig = ch.origin_sig,
        };
        const outcome = entity_prop_event.verifyOrigin(self.allocator, ev) catch {
            self.recordEntityPropSignatureReject(ch, "verification allocation failed");
            return false;
        };
        return switch (outcome) {
            .unsigned, .verified => true,
            .origin_mismatch => blk: {
                self.recordEntityPropSignatureReject(ch, "origin pubkey does not self-certify the claimed origin node");
                break :blk false;
            },
            .bad_signature => blk: {
                self.recordEntityPropSignatureReject(ch, "origin signature verification failed");
                break :blk false;
            },
        };
    }

    /// True iff THIS node holds a live SASL session for `account` — i.e. this node
    /// is the account's authoritative home. Rooted in SASL (the only non-forgeable
    /// account anchor): `sessionsInto` snapshots the account's local sessions and
    /// each is re-verified still logged into `account` (a stale SessionStore entry
    /// from an account switch is skipped, mirroring `deliverSessionSyncSiblingsNick`).
    fn accountHasLocalSession(self: *LinuxServer, account: []const u8) bool {
        if (account.len == 0) return false;
        const account_sessions = self.sessions.copySessionsAlloc(self.allocator, account) catch return false;
        defer self.allocator.free(account_sessions);
        for (account_sessions) |s| {
            const conn = self.connFor(clientIdFromMonitor(s.client)) orelse continue;
            const cur = conn.session.account() orelse continue;
            if (std.mem.eql(u8, cur, account)) return true;
        }
        return false;
    }

    /// P1 (F1 account-key authority): is an inbound `identity.key.*` /
    /// `identity.residence.*` ENTITY_PROP write for a USER entity (= account)
    /// authoritative from `origin_node`? These props are the RECEIVER-OWNED pubkey
    /// source residence trust verifies against, so a Byzantine admitted peer must
    /// not be able to inject `identity.key.<victim>` = its own key. Two
    /// complementary, non-forgeable anchors — the analog of the nick-path
    /// `meshNickHomeNode`/`recordRelayHomeMismatch` gate, rooted in SASL:
    ///   (a) LOCAL SASL anchor: if this node holds a live SASL session for the
    ///       account, it IS the authoritative home — reject EVERY remote-origin
    ///       write (the genuine key was written locally via IDENTITY ADD, never
    ///       ingested; a remote one is a forgery, even for an account whose clock
    ///       is absent because it has not enrolled yet).
    ///   (b) ORIGIN BINDING: once a prop clock exists for the exact identity key,
    ///       only the origin that established it may update it — a Byzantine peer
    ///       cannot OVERWRITE a genuine home node's key/residence with its own,
    ///       even at a higher hlc that plain LWW would accept. Genuine key
    ///       rotation from the same home is same-origin and still applies.
    /// A non-USER entity or a non-identity key is never gated (returns true) so
    /// ordinary ENTITY_PROP LWW is unchanged.
    ///
    /// RESIDUAL (deferred, owner: onyx-server-mesh / stack-architect): a COLD third
    /// node that has never seen the account — no local session, no clock — fails
    /// OPEN, so a Byzantine peer that WINS the ENTITY_PROP burst race to that node
    /// (delivers `identity.key.<victim>`=own-key before any honest node) binds the
    /// clock to its own origin. This binding is then STICKY, NOT self-healing: the
    /// gate runs BEFORE the LWW check, so the genuine home's later key (a different
    /// origin) is rejected at every hlc and anti-entropy re-delivery cannot displace
    /// it. Recovery is only a LOCAL write on that node (the victim SASL-logs-in
    /// there — that bypasses this gate) or an operator clear. Helix now carries
    /// the exact entity clocks, so USR2 does not re-arm the window; a genuinely
    /// cold node still has the first-observation race. This is the compromised-
    /// relink-source class the blueprint defers (R2/R3); the fully-sound remote anchor
    /// (SASL-home-authenticated identity replication) is the larger mesh-security
    /// design. Home and already-converged (warm) nodes are NOT exposed.
    fn accountIdentityPropAuthorized(
        self: *LinuxServer,
        kind: entity_prop_event.EntityKind,
        entity: []const u8,
        key: []const u8,
        origin_node: u64,
    ) bool {
        if (kind.toStoreKind() != .user) return true;
        if (!account_identity.isPropKey(key) and !account_identity.isResidencePropKey(key)) return true;
        // (a) local SASL anchor — this node is the account's home.
        if (self.accountHasLocalSession(entity)) return origin_node == self.config.node_id;
        // (b) origin binding — a later different-origin write cannot overwrite.
        if (self.entityPropClock(kind, entity, key)) |clock| {
            if (clock.origin_node != origin_node) return false;
        }
        return true;
    }

    /// Account + audit an ENTITY_PROP identity write dropped because its origin is
    /// not the account's authoritative home (P1). Reuses the home-mismatch counter
    /// the nick-path gate uses — semantically the same rejection class.
    fn recordEntityPropAuthorityReject(self: *LinuxServer, ch: anytype) void {
        self.rejected_relay_home_mismatch +|= 1;
        var buf: [256]u8 = undefined;
        const line = std.fmt.bufPrint(
            &buf,
            "dropped ENTITY_PROP identity write {s}/{s} from node {d}: origin is not the account's authoritative home",
            .{ ch.entity, ch.key, ch.origin_node },
        ) catch "dropped ENTITY_PROP identity write: origin is not the account's home";
        self.traceLog(.warn, .s2s, line);
    }

    /// Apply an inbound ENTITY_PROP fact LWW into the local prop store + clock.
    /// The counterpart of `applyRemoteChannelProp`: verify-then-LWW, dropping a
    /// forged fact before it is applied or re-broadcast. The entity id is validated
    /// by the store on insert; a malformed id (rejected by `Entity.fromId`) simply
    /// fails to apply.
    fn applyRemoteEntityProp(self: *LinuxServer, ch: anytype) bool {
        // This namespace has a private timestamp-max admission path. It must
        // never enter ordinary property LWW or public PROP notification.
        if (isReadMarkerPropKey(ch.key)) return false;
        if (ch.kind.toStoreKind() == .user and account_identity.isReservedNamespace(ch.key)) {
            self.remote_identity_props_quarantined +|= 1;
            var quarantine_buf: [256]u8 = undefined;
            const quarantine = std.fmt.bufPrint(
                &quarantine_buf,
                "quarantined remote ENTITY_PROP identity fact {s}/{s} from node {d}",
                .{ ch.entity, ch.key, ch.origin_node },
            ) catch "quarantined remote ENTITY_PROP identity fact";
            self.traceLog(.warn, .s2s, quarantine);
            return false;
        }
        if (ch.kind.toStoreKind() == .user and isReservedDevicePropPrefix(ch.key)) {
            self.remote_device_props_quarantined +|= 1;
            var warning_buf: [256]u8 = undefined;
            const warning = std.fmt.bufPrint(
                &warning_buf,
                "quarantined remote ENTITY_PROP device fact {s}/{s} from node {d}",
                .{ ch.entity, ch.key, ch.origin_node },
            ) catch "quarantined remote ENTITY_PROP device fact";
            self.traceLog(.warn, .s2s, warning);
            return false;
        }
        if (!self.entityPropOriginVerified(ch)) return false;
        // P1: an identity.key.*/identity.residence.* write is only authoritative
        // from the account's home — reject a non-home (forged) write fail-closed
        // BEFORE it can overwrite the receiver-owned pubkey residence trust reads.
        if (!self.accountIdentityPropAuthorized(ch.kind, ch.entity, ch.key, ch.origin_node)) {
            self.recordEntityPropAuthorityReject(ch);
            return false;
        }
        if (self.entityPropClock(ch.kind, ch.entity, ch.key)) |existing| {
            if (ch.hlc <= existing.hlc) return false;
        }
        const entity = ircx_prop_store.Entity{ .kind = ch.kind.toStoreKind(), .id = ch.entity };
        // A missing valid row is exactly what a tombstone describes, but an
        // invalid entity/key must not become a durable clock-only poison row.
        // Validate the lookup shape without mutating before observing its HLC.
        _ = self.props.getPropRaw(entity, ch.key) catch |err| switch (err) {
            error.PropMissing => {},
            else => return false,
        };
        const owner = if (ch.owner.len != 0) ch.owner else "remote";

        // No-partial-mutation commit: reserve EVERY allocation this fact could
        // ever require — the prop-store write and the LWW clock write — before
        // touching anything a later failure could leave half-applied.
        // `prepareSetProp` is a real reservation (unlike `preflightSetProp`,
        // which validates but disclaims reserving), and `stageEntityPropClock`
        // is already allocation-complete. Neither mutates props, clocks, the
        // KEYTRANS log, or the mesh HLC watermark. Only once BOTH have
        // succeeded may the watermark — which never rolls back — advance, and
        // only then do we run the commit sequence, which by construction
        // cannot fail.
        var prepared_set: ?ircx_prop_store.DefaultStore.PreparedSetProp = null;
        defer if (prepared_set) |*prepared| prepared.deinit();
        if (ch.present) {
            prepared_set = self.props.prepareSetProp(entity, ch.key, ch.value, .{ .id = owner, .access = .server }) catch return false;
        }

        var staged = self.stageEntityPropClock(
            ch.kind,
            ch.entity,
            ch.key,
            owner,
            ch.hlc,
            ch.present,
            ch.origin_node,
            ch.origin_pubkey,
            ch.origin_sig,
        ) orelse return false;

        // The mesh HLC watermark only ever moves forward, so it may advance
        // only once every fallible step above has already succeeded —
        // advancing it any earlier would pin the watermark forward for a
        // remote fact that never actually committed.
        if (!self.observeRemotePropertyHlc(ch.hlc)) {
            staged.discard(self.allocator);
            return false;
        }

        if (prepared_set) |*prepared| {
            _ = prepared.commit();
        } else {
            self.props.deleteProp(entity, ch.key) catch {};
        }
        self.commitStagedEntityPropClock(staged);
        self.observeUserCredentialProp(
            ch.present,
            ch.kind.toStoreKind(),
            ch.entity,
            ch.key,
            ch.value,
            ch.hlc,
            ch.origin_node,
            ch.origin_pubkey,
        );
        return true;
    }

    /// Mesh counterpart of a local user/member PROP-notify: fan a remote
    /// ENTITY_PROP change out to local IRCX clients with the remote node name as
    /// prefix. A user prop reaches the target + common-channel IRCX peers; a
    /// member prop reaches the member's channel under the per-tier secret gate.
    fn emitRemoteEntityProp(self: *LinuxServer, ch: anytype, remote_name: []const u8) void {
        if (isReadMarkerPropKey(ch.key)) return;
        const host = if (remote_name.len != 0) remote_name else self.serverName();
        var buf: [900]u8 = undefined;
        const line = if (ch.present)
            std.fmt.bufPrint(&buf, ":{s} PROP {s} {s} :{s}\r\n", .{ host, ch.entity, ch.key, ch.value }) catch return
        else
            std.fmt.bufPrint(&buf, ":{s} PROP {s} {s} :\r\n", .{ host, ch.entity, ch.key }) catch return;
        switch (ch.kind.toStoreKind()) {
            .user => self.fanUserPropNotify(ch.entity, line, null),
            .member => {
                const split = std.mem.indexOfScalar(u8, ch.entity, ':') orelse return;
                self.fanChannelPropNotify(ch.entity[0..split], ch.key, line, null);
            },
            .channel => {},
        }
    }

    /// Drain a link's remote user/member PROP changes (ENTITY_PROP), apply them LWW
    /// to the local store, then fan each applied change out to local IRCX clients
    /// (mirroring a local change's visibility) in addition to the on-demand
    /// PROP GET reply path.
    fn drainEntityPropChanges(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const changes = link.takeEntityPropChanges() catch return;
        const remote = link.remoteName();
        for (changes) |*ch| {
            if (isReadMarkerPropKey(ch.key)) {
                if (comptime @TypeOf(link) == *secured_s2s_link.SecuredLink) {
                    if (link.supportsReadMarkers()) self.admitRemoteReadMarker(ch) catch {};
                }
            } else if (self.applyRemoteEntityProp(ch)) {
                self.emitRemoteEntityProp(ch, remote);
            }
            ch.deinit(self.allocator);
        }
        self.allocator.free(changes);
    }

    /// Burst every stored user/member PROP clock to a freshly-established peer, the
    /// counterpart of `sendChannelPropBurstTo`. Re-emits the ORIGINAL author's
    /// stored origin + signature verbatim (or seeds + signs a locally-owned prop
    /// that has no clock yet), falling back to unsigned for an emit whose live
    /// tuple diverged from the signed one.
    fn sendEntityPropBurstTo(self: *LinuxServer, conn: *ConnState) bool {
        if (!conn.isActiveMeshPeer()) return false;
        var it = self.entity_prop_clocks.iterator();
        while (it.next()) |entry| {
            const clock = entry.value_ptr;
            if (isReadMarkerPropKey(clock.key)) continue;
            if (clock.kind == .user and account_identity.isReservedNamespace(clock.key)) continue;
            var present = clock.present;
            var value: []const u8 = "";
            var owner: []const u8 = clock.owner;
            if (clock.present) {
                const entity = ircx_prop_store.Entity{ .kind = clock.kind.toStoreKind(), .id = clock.entity };
                if (self.props.getProp(entity, clock.key)) |ev| {
                    value = ev.value;
                    owner = ev.owner;
                } else |_| {
                    present = false;
                }
            }
            const origin = self.burstEntityPropOrigin(clock, present, value, owner);
            if (conn.s2s_secured) |link| {
                link.sendEntityProp(clock.kind, clock.entity, clock.key, value, owner, clock.hlc, present, origin) catch return false;
            } else if (conn.s2s) |link| {
                link.sendEntityProp(clock.kind, clock.entity, clock.key, value, owner, clock.hlc, present, origin) catch return false;
            }
        }
        return self.sendReadMarkerBurstTo(conn);
    }

    fn sendChannelPropBurstTo(self: *LinuxServer, conn: *ConnState) bool {
        if (!conn.isActiveMeshPeer()) return false;
        var cit = self.world.channelIterator();
        while (cit.next()) |cv| {
            const entity = ircx_prop_store.Entity{ .kind = .channel, .id = cv.name };
            var views: [ircx_prop_store.default_max_props_per_entity]ircx_prop_store.EntryView = undefined;
            const rows = self.props.listProps(entity, &views) catch return false;
            for (rows) |entry| {
                if (self.channelPropClock(entry.entity.id, entry.key) == null) {
                    // A locally-owned prop with no clock yet: seed one as a LOCAL
                    // origin and sign it, so the burst re-emits a verifiable fact.
                    const hlc = self.nextChannelPropHlc();
                    var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
                    var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
                    const ps = self.signLocalChannelProp(true, entry.entity.id, entry.key, entry.value, entry.owner, hlc, &pk_buf, &sig_buf);
                    if (!self.recordChannelPropClock(entry.entity.id, entry.key, entry.owner, hlc, true, ps.node, ps.pubkey, ps.sig)) return false;
                }
            }
        }

        var it = self.channel_prop_clocks.iterator();
        while (it.next()) |entry| {
            const clock = entry.value_ptr;
            var present = clock.present;
            var value: []const u8 = "";
            var owner: []const u8 = clock.owner;
            if (clock.present) {
                const entity = ircx_prop_store.Entity{ .kind = .channel, .id = clock.channel };
                if (self.props.getProp(entity, clock.key)) |ev| {
                    value = ev.value;
                    owner = ev.owner;
                } else |_| {
                    present = false;
                }
            }
            // Re-emit the ORIGINAL author's stored origin + signature verbatim so a
            // bursted fact still self-certifies its true author at the receiver.
            // The signature is bound to the EXACT (present, value, owner, hlc) the
            // author signed; the burst re-derives value/owner/present from the
            // live store, which can diverge from the signed tuple (e.g. the prop
            // was deleted but the clock still recorded it present). When the stored
            // signature no longer matches the tuple being emitted, fall back to
            // unsigned for THIS emit rather than ship a signature that cannot
            // verify (the receiver applies it via the legacy LWW path).
            const origin = self.burstPropOrigin(clock, present, value, owner);
            if (conn.s2s_secured) |link| {
                link.sendChannelProp(clock.channel, clock.key, value, owner, clock.hlc, present, origin) catch return false;
            } else if (conn.s2s) |link| {
                link.sendChannelProp(clock.channel, clock.key, value, owner, clock.hlc, present, origin) catch return false;
            }
        }
        return true;
    }

    fn sendChannelListToConn(
        self: *LinuxServer,
        conn: *ConnState,
        channel: []const u8,
        kind: channel_list_event.ListKind,
        mask: []const u8,
        setter: []const u8,
        set_at: i64,
        hlc: u64,
        present: bool,
    ) bool {
        _ = self;
        if (conn.s2s_secured) |link| {
            link.sendChannelList(channel, kind, mask, setter, set_at, hlc, present) catch return false;
        } else if (conn.s2s) |link| {
            link.sendChannelList(channel, kind, mask, setter, set_at, hlc, present) catch return false;
        }
        return true;
    }

    fn announceMembership(self: *LinuxServer, channel: []const u8, nick: []const u8, status: u4, present: bool, ident: s2s_link.S2sLink.MemberIdentity, setter: []const u8) void {
        // Wall-clock mesh HLC — feeds route_table's cross-host LWW (nick/channel
        // keyed), so it must be recency-comparable, never monotonic (was the
        // per-host `self.nowMs()`, the membership-desync root cause). See nextMeshHlc.
        const hlc = self.nextMeshHlc();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    link.sendMembership(channel, nick, status, hlc, present, ident, setter) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendMembership(channel, nick, status, hlc, present, ident, setter) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    fn announceChannelModeFlags(self: *LinuxServer, channel: []const u8, flags: u16) void {
        // Wall-clock mesh HLC — feeds route_table's cross-host LWW (nick/channel
        // keyed), so it must be recency-comparable, never monotonic (was the
        // per-host `self.nowMs()`, the membership-desync root cause). See nextMeshHlc.
        const hlc = self.nextMeshHlc();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    link.sendChannelModeFlags(channel, flags, hlc) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendChannelModeFlags(channel, flags, hlc) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    fn announceChannelList(
        self: *LinuxServer,
        channel: []const u8,
        kind: channel_list_event.ListKind,
        mask: []const u8,
        setter: []const u8,
        set_at: i64,
        present: bool,
    ) void {
        // Wall-clock mesh HLC — feeds route_table's cross-host LWW (nick/channel
        // keyed), so it must be recency-comparable, never monotonic (was the
        // per-host `self.nowMs()`, the membership-desync root cause). See nextMeshHlc.
        const hlc = self.nextMeshHlc();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    link.sendChannelList(channel, kind, mask, setter, set_at, hlc, present) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendChannelList(channel, kind, mask, setter, set_at, hlc, present) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    /// Fan a channel PROP fact out to every established peer link. `origin`
    /// carries the ORIGINAL author's node id and self-contained multi-hop
    /// signature (see `s2s_link.S2sLink.sendChannelProp`): the local-author path
    /// passes this node's signed origin, and the inbound re-broadcast path passes
    /// the remote author's stored `(node, pubkey, sig)` so every hop verifies the
    /// ORIGINAL author rather than this relay.
    fn announceChannelProp(
        self: *LinuxServer,
        channel: []const u8,
        key: []const u8,
        value: []const u8,
        owner: []const u8,
        hlc: u64,
        present: bool,
        origin: s2s_peer_mod.S2sPeer.PropOrigin,
    ) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    link.sendChannelProp(channel, key, value, owner, hlc, present, origin) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendChannelProp(channel, key, value, owner, hlc, present, origin) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    /// The LOCAL member identity (real username, realname, VISIBLE/cloaked host)
    /// to propagate alongside a membership announcement, so remote peers render
    /// the real `user@host` instead of the `mesh@<server>` placeholder.
    fn membershipIdentityOf(conn: *const ConnState) s2s_link.S2sLink.MemberIdentity {
        return .{
            .username = conn.session.username(),
            .realname = conn.session.realname(),
            .host = hostOf(conn),
            // The authenticated account ("" = not logged in) so a remote peer can
            // recognize a colliding nick as the SAME identity (account-aware
            // reconcile) instead of UID-renaming a logged-in user.
            .account = conn.session.account() orelse "",
            // Oper-visible identity for a peer's remote-user WHOIS (338/276/320).
            // SENSITIVE: the s2s layer emits these ONLY over a secured, oper-info
            // capable link (see cap_member_oper_info) and the peer shows them only
            // to operators — so populating them here is safe.
            .real_host = conn.session.realHost(),
            .certfp = conn.session.tls_certfp orelse "",
        };
    }

    /// True when `nick` belongs to a live, locally-connected (non-peer) client.
    /// A peer link's remote roster can contain echoes of OUR OWN members (a peer
    /// announcing a status grant for a user homed here attributes that nick to
    /// the link); fabricating JOIN/PART/netsplit-QUIT display lines for such a
    /// nick desyncs every client-side nicklist from the server roster — the
    /// user never actually left.
    fn nickIsLiveLocal(self: *LinuxServer, nick: []const u8) bool {
        const wid = self.world.findNick(nick) orelse return false;
        const conn = self.connFor(clientIdFromWorld(wid)) orelse return false;
        return conn.s2s == null and conn.s2s_secured == null;
    }

    /// True when a live-local `nick` is logged in to `account` (case-insensitive,
    /// both non-empty). Used to tell a legitimate multi-client / one-nick SIBLING
    /// session (same account on another mesh node — by design) apart from a real
    /// origin spoof (a peer asserting a DIFFERENT account's hold on a local nick).
    /// `account` is the relayed message's authenticated account (origin-verified).
    fn localNickSameAccount(self: *LinuxServer, nick: []const u8, account: []const u8) bool {
        if (account.len == 0) return false;
        const wid = self.world.findNick(nick) orelse return false;
        const conn = self.connFor(clientIdFromWorld(wid)) orelse return false;
        if (conn.s2s != null or conn.s2s_secured != null) return false;
        const local_acct = conn.session.account() orelse return false;
        return std.ascii.eqlIgnoreCase(local_acct, account);
    }

    /// Match a connection to its `[class.*]` class and apply the per-class policy.
    /// Today it sets the SendQ ceiling; recvq, clone/channel caps, timeouts,
    /// admission, and flood limits layer onto this same assignment point. Called at
    /// registration and after USR2 adoption; a no-op when no class registry is set
    /// (the generous default cap stands).
    fn assignConnClass(self: *LinuxServer, conn: *ConnState) void {
        const reg = if (self.config.class_registry) |*r| r else return;
        const class = reg.classFor(matchCtx(conn));
        conn.class_policy = class.policy;
        conn.sendq_cap = if (conn.s2s != null or conn.s2s_secured != null)
            s2sSendqCap(class.policy.sendq)
        else
            class.policy.sendq;
        conn.recvq_cap = if (class.policy.recvq != 0) @intCast(class.policy.recvq) else default_recvq_cap;

        // The single flood guard is derived here from the matched class. Re-match
        // (oper-up moving to a flood_exempt class, USR2 adoption) retunes it in
        // place or clears it, so policy lives in exactly one spot.
        const fg_cfg = class.policy.floodGuardConfig();
        if (fg_cfg.enabled) {
            if (conn.flood_guard) |*g| {
                g.reconfigure(fg_cfg);
            } else {
                conn.flood_guard = flood_guard.FloodGuard.init(fg_cfg, self.nowMs());
            }
        } else {
            conn.flood_guard = null;
        }
    }

    fn s2sSendqCap(configured: usize) usize {
        return @max(configured, min_s2s_sendq_cap);
    }

    /// Build the connection-class match context for `conn` from its live session
    /// state. Shared by every site that matches or re-matches a connection to a
    /// class (assignment, member counts, per-IP cap), so the criteria stay in one
    /// place.
    fn matchCtx(conn: *const ConnState) conn_class.MatchContext {
        return .{
            .ip_text = conn.session.realHost(),
            .is_tls = conn.tls != null,
            .has_account = conn.session.account() != null,
            .is_oper = conn.session.isOper(),
            .ident = conn.session.username(),
            .host = conn.session.realHost(),
            .is_server_link = conn.s2s != null or conn.s2s_secured != null,
        };
    }

    /// Enforce the matched class's admission policy (require_tls / require_sasl).
    /// Returns true and tears the client down (notice + close) when the class
    /// refuses it; false to admit. Reads the policy stored by `assignConnClass`,
    /// so call it after that (post-SASL/oper, when the class is final).
    fn enforceClassAdmission(self: *LinuxServer, conn: *ConnState) bool {
        const p = conn.class_policy;
        var reason: ?[]const u8 = if (p.require_tls and conn.tls == null)
            "Connection class requires a TLS (implicit-TLS) connection"
        else if (p.require_sasl and conn.session.account() == null)
            "Connection class requires SASL authentication"
        else
            null;
        // Per-class population caps, evaluated once the class is final (post
        // SASL/oper, post PROXY-header IP resolution — so account, host, and the
        // real source IP are all known, making these WebSocket/proxy-safe). One
        // scan yields every dimension; each count includes this just-registered
        // connection, so the Nth admitted client trips when the count exceeds the
        // limit. The IP and host dimensions are skipped for loopback/trusted-proxy
        // sources, which legitimately aggregate many distinct clients. Operators
        // holding `limit_exempt` bypass every cap; authenticated accounts get a +2
        // bonus on the source-keyed caps (IP / host / account).
        if (reason == null and !conn.session.hasPriv(.limit_exempt) and
            (p.max_clients != 0 or p.max_per_ip != 0 or p.max_per_account != 0 or p.max_per_host != 0))
        {
            if (self.config.class_registry) |*r| {
                const name = r.classFor(matchCtx(conn)).name;
                const counts = self.classCounts(conn, name);
                const ip_exempt = self.ipCloneExempt(conn);
                const host_exempt = ip_exempt or std.mem.eql(u8, conn.session.realHost(), default_host);
                const bonus: u32 = if (conn.session.account() != null) 2 else 0;
                if (p.max_clients != 0 and counts.total > p.max_clients) {
                    reason = "Connection class is full (too many clients)";
                } else if (p.max_per_ip != 0 and !ip_exempt and counts.ip > p.max_per_ip + bonus) {
                    reason = "Too many connections from your host in this connection class";
                } else if (p.max_per_account != 0 and conn.session.account() != null and counts.account > p.max_per_account + bonus) {
                    reason = "Too many connections from your account in this connection class";
                } else if (p.max_per_host != 0 and !host_exempt and counts.host > p.max_per_host + bonus) {
                    reason = "Too many connections from your host in this connection class";
                }
            }
        }
        // Network-wide (mesh) per-IP clone cap: local + every peer's count for the
        // same salted-IP-hash. Same exemptions: `limit_exempt` opers bypass,
        // accounts get +2, loopback/trusted-proxy are skipped (meshCloneHash → null).
        if (reason == null and !conn.session.hasPriv(.limit_exempt) and self.config.max_clones_per_ip_net != 0) {
            if (self.meshCloneHash(conn)) |hash| {
                const net_bonus: u32 = if (conn.session.account() != null) 2 else 0;
                if (self.mesh_clones.networkCount(hash) >= self.config.max_clones_per_ip_net + net_bonus) {
                    reason = "Too many connections from your IP across the network";
                }
            }
        }
        if (reason) |r| {
            self.noticeTo(conn, r) catch {};
            conn.close_reason = "Connection class policy";
            conn.closing = true;
            return true;
        }
        return false;
    }

    /// The salted-IP-hash for `conn`'s source, or null when network-wide clone
    /// counting does not apply: disabled, no address, or a loopback/trusted-proxy
    /// source that must not be IP-counted (WebSocket-safe). Raw IPs never leave
    /// the node — only this keyed hash is gossiped.
    fn meshCloneHash(self: *LinuxServer, conn: *const ConnState) ?u64 {
        if (self.config.max_clones_per_ip_net == 0) return null;
        if (self.ipCloneExempt(conn)) return null;
        const addr = conn.peer_addr orelse return null;
        return switch (addr) {
            .ipv4 => |b| mesh_clones_mod.hashIp(self.clone_key, &b),
            .ipv6 => |b| mesh_clones_mod.hashIp(self.clone_key, &b),
        };
    }

    /// Record `conn` in the network-wide clone aggregate after it is admitted, and
    /// gossip the new local count for its IP-hash to peers. No-op when the IP is
    /// exempt / network counting is disabled.
    fn meshCloneAdd(self: *LinuxServer, conn: *ConnState) void {
        const hash = self.meshCloneHash(conn) orelse return;
        const n = self.mesh_clones.addLocal(hash) catch return;
        conn.mesh_clone_hash = hash;
        conn.mesh_clone_counted = true;
        self.publishCloneCount(hash, n);
    }

    /// Release `conn` from the network-wide clone aggregate on close and gossip the
    /// decremented count. Exactly-once via `mesh_clone_counted`.
    fn meshCloneRelease(self: *LinuxServer, conn: *ConnState) void {
        if (!conn.mesh_clone_counted) return;
        conn.mesh_clone_counted = false;
        const n = self.mesh_clones.removeLocal(conn.mesh_clone_hash);
        self.publishCloneCount(conn.mesh_clone_hash, n);
    }

    /// Gossip a single `(hash, count)` update to every established peer link.
    fn publishCloneCount(self: *LinuxServer, hash: u64, count: u32) void {
        var buf: [mesh_clones_mod.encodedLen(1)]u8 = undefined;
        const payload = mesh_clones_mod.encodeCounts(&buf, &.{.{ .hash = hash, .count = count }}) catch return;
        self.broadcastCloneCounts(payload);
    }

    /// Send a CLONE_COUNT payload to every established peer link (both legs),
    /// flushing each link's framing to its connection. Best-effort.
    fn broadcastCloneCounts(self: *LinuxServer, payload: []const u8) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    link.sendCloneCounts(payload) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendCloneCounts(payload) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    /// Decode and ingest a peer's inbound CLONE_COUNT payloads, attributing each
    /// entry to that peer's `node` in the network-wide aggregate. Malformed
    /// payloads are skipped (never fatal). Caller passes the link's authenticated
    /// node id so a peer can only assert ITS OWN counts.
    fn ingestCloneCounts(self: *LinuxServer, node: u64, payloads: [][]u8) void {
        defer {
            for (payloads) |p| self.allocator.free(p);
            self.allocator.free(payloads);
        }
        for (payloads) |p| {
            const view = mesh_clones_mod.decodeCounts(p) catch continue;
            var i: u32 = 0;
            while (i < view.n) : (i += 1) {
                const e = view.get(i);
                self.mesh_clones.setRemote(node, e.hash, e.count) catch {};
            }
        }
    }

    /// Drain a peer's inbound CLONE_COUNT payloads and fold them into the
    /// aggregate under that link's authenticated node id. Always frees the queued
    /// payloads (even when the link has no node id yet).
    fn drainCloneCountsFrom(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const payloads = link.takeCloneCounts() catch return;
        const node = link.remoteNodeId() orelse {
            for (payloads) |p| self.allocator.free(p);
            self.allocator.free(payloads);
            return;
        };
        self.ingestCloneCounts(node, payloads);
    }

    /// Anti-entropy: ship this node's local count table to a freshly linked peer
    /// so it converges immediately. Chunked (bounded stack); best-effort. Flushes
    /// through `conn` (the drive path owns the connection, not a pid).
    fn sendCloneAntiEntropy(self: *LinuxServer, conn: *ConnState, link: anytype) bool {
        if (!conn.ownsActiveMeshLink(link)) return false;
        if (self.config.max_clones_per_ip_net == 0) return true;
        const chunk = 256;
        var buf: [mesh_clones_mod.encodedLen(chunk)]u8 = undefined;
        var entries: [chunk]mesh_clones_mod.Entry = undefined;
        var it = self.mesh_clones.localIterator();
        while (true) {
            var n: usize = 0;
            while (n < entries.len) {
                const e = it.next() orelse break;
                entries[n] = .{ .hash = e.key_ptr.*, .count = e.value_ptr.* };
                n += 1;
            }
            if (n == 0) break;
            const payload = mesh_clones_mod.encodeCounts(&buf, entries[0..n]) catch return false;
            link.sendCloneCounts(payload) catch return false;
        }
        return true;
    }

    /// Count live connections currently in connection class `name` (across all
    /// reactor shards; safe — STATS runs under the world lock). S2S links count as
    /// `server`; registered clients are re-matched. Used by STATS Y.
    pub fn countClassMembers(self: *LinuxServer, name: []const u8) usize {
        const reg = if (self.config.class_registry) |*r| r else return 0;
        var n: usize = 0;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const c = &slot.value;
                if (c.s2s != null or c.s2s_secured != null) {
                    if (std.ascii.eqlIgnoreCase(name, "server")) n += 1;
                    continue;
                }
                if (!c.session.registered()) continue;
                const cls = reg.classFor(matchCtx(c));
                if (std.ascii.eqlIgnoreCase(cls.name, name)) n += 1;
            }
        }
        return n;
    }

    /// Per-class population counts relative to `conn`. Used by the registration
    /// admission caps; one scan yields every dimension.
    const ClassCounts = struct { total: u32 = 0, ip: u32 = 0, account: u32 = 0, host: u32 = 0 };

    /// Single-pass per-class counts relative to `conn`, across all reactor shards:
    /// total same-class members, plus how many share `conn`'s exact source IP,
    /// account, and resolved host. Includes `conn` itself once it is in a slot.
    /// Backs the per-class max_clients / max_per_ip / max_per_account /
    /// max_per_host caps. Safe under the world lock (registration runs under it).
    fn classCounts(self: *LinuxServer, conn: *const ConnState, class_name: []const u8) ClassCounts {
        const reg = if (self.config.class_registry) |*r| r else return .{};
        var out = ClassCounts{};
        const my_ip = conn.peer_addr;
        const my_acct = conn.session.account();
        const my_host = conn.session.realHost();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const c = &slot.value;
                if (c.s2s != null or c.s2s_secured != null) continue;
                if (!c.session.registered()) continue;
                const cls = reg.classFor(matchCtx(c));
                if (!std.ascii.eqlIgnoreCase(cls.name, class_name)) continue;
                out.total += 1;
                if (my_ip) |ip| {
                    if (c.peer_addr) |cip| {
                        if (std.meta.eql(cip, ip)) out.ip += 1;
                    }
                }
                if (my_acct) |acct| {
                    if (c.session.account()) |cacct| {
                        if (std.ascii.eqlIgnoreCase(cacct, acct)) out.account += 1;
                    }
                }
                if (my_host.len != 0 and std.ascii.eqlIgnoreCase(c.session.realHost(), my_host)) out.host += 1;
            }
        }
        return out;
    }

    /// Whether `conn`'s source IP must be EXEMPT from IP/host-keyed clone limits:
    /// loopback or a configured trusted proxy. Such addresses aggregate many
    /// distinct real clients (a reverse proxy fronting WebSocket clients, or local
    /// bots/services), so an IP/host clone cap there would falsely lump them.
    fn ipCloneExempt(self: *const LinuxServer, conn: *const ConnState) bool {
        const addr = conn.peer_addr orelse return true;
        if (addrIsLoopback(addr)) return true;
        if (self.config.proxy_protocol_enabled) {
            for (self.config.trusted_proxies) |t| {
                if (trustedProxyMatches(addr, t)) return true;
            }
        }
        return false;
    }

    /// Resolve a REMOTE (mesh) member's channel status bits by nick, scanning
    /// every established peer link's converged channel roster (the route table —
    /// the only place mesh members are represented; remote users are NOT in the
    /// world member map). Returns the member's status (u4 prefix bits) when any
    /// link's `#channel` roster lists `nick` (ASCII case-insensitive), else null.
    /// Used by the inbound-relay channel-policy gate (+n/+m/+b) to decide whether
    /// a relayed message's remote sender is a member of THIS node's projection of
    /// the channel before delivering it to local members.
    fn remoteMemberStatusInChannel(self: *LinuxServer, channel: []const u8, nick: []const u8) ?u4 {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const members = if (slot.value.s2s_secured) |l|
                    l.channelMembers(channel)
                else if (slot.value.s2s) |l|
                    l.channelMembers(channel)
                else
                    continue;
                for (members) |m| {
                    if (std.ascii.eqlIgnoreCase(m.nick, nick)) return m.status;
                }
            }
        }
        return null;
    }

    /// Whether `nick` is a member of `channel` in THIS node's projection — either
    /// a local world member (resolved by nick) or a remote member in any peer
    /// link's roster. The combined membership view used by the inbound-relay
    /// channel-policy gate so a legitimate member's relayed message is never
    /// dropped while a true non-member's is.
    fn relaySenderIsMember(self: *LinuxServer, channel: []const u8, nick: []const u8) bool {
        if (self.world.isMemberByNick(channel, nick)) return true;
        return self.remoteMemberStatusInChannel(channel, nick) != null;
    }

    /// Effective channel status bits for `nick` in `channel` across the combined
    /// (local world + remote roster) projection — the local member modes take
    /// precedence if present, else the remote roster's status. Empty when the
    /// actor is not a member anywhere. Used to evaluate +m speak rights and op
    /// override for a relayed remote sender.
    fn relaySenderModes(self: *LinuxServer, channel: []const u8, nick: []const u8) world_model.MemberModes {
        if (self.world.memberModesByNick(channel, nick)) |mm| return mm;
        if (self.remoteMemberStatusInChannel(channel, nick)) |status|
            return world_model.MemberModes{ .bits = @as(u8, status) };
        return world_model.MemberModes.empty();
    }

    /// Receiver-side re-enforcement of LOCAL channel policy against the REMOTE
    /// sender of an inbound relayed PRIVMSG/NOTICE/TAGMSG, mirroring the local
    /// `channelSpeechGate` (+n/+m/+M/+b/+Z/+C/+T/+f/+U/statusmsg) for messages
    /// that arrived over the mesh. Returns .allow, .deny, or .opmoderate for
    /// local delivery; forwarding to other mesh peers remains independent so each
    /// downstream node can apply its own policy. `nick`/`prefix`/`account`
    /// describe the remote actor.
    fn relayChannelSpeechGate(
        self: *LinuxServer,
        channel: []const u8,
        nick: []const u8,
        prefix: []const u8,
        account: []const u8,
        text: []const u8,
        is_notice: bool,
        min_rank: u8,
        replicated_modes: ?world_model.MemberModes,
        allow_external: bool,
    ) ChannelSpeechResult {
        // +n no_external: only members may send. Resolve membership across the
        // combined local+remote projection; a non-member is dropped. The narrow
        // `allow_external` exception is pre-authenticated by the caller: either a
        // verified server webhook or a verified multi-hop origin for which this
        // node cannot possess a one-hop membership roster. It bypasses ONLY +n;
        // every remaining receiver-side mode below is still re-enforced here.
        const is_member = allow_external or replicated_modes != null or self.relaySenderIsMember(channel, nick);
        if (self.world.channelHasFlag(channel, .no_external) and !is_member) return .deny;

        const modes = replicated_modes orelse self.relaySenderModes(channel, nick);
        const opmod = self.world.channelHasExtFlag(channel, .opmoderate);
        var opmod_route = false;

        // +m moderated: a member without voice+ cannot speak.
        if (self.world.channelHasFlag(channel, .moderated) and !modes.canSpeakModerated()) {
            if (opmod) opmod_route = true else return .deny;
        }
        // +M mod_reg: an unauthenticated member without voice+ cannot speak.
        if (self.world.channelHasFlag(channel, .mod_reg) and account.len == 0 and !modes.canSpeakModerated()) {
            if (opmod) opmod_route = true else return .deny;
        }
        // +a authonly: an unauthenticated remote sender cannot speak (mirrors the join gate).
        if (self.world.channelHasExtFlag(channel, .authonly) and account.len == 0) return .deny;

        // +b bans / +Z quiet: build an extban context from the remote actor's
        // propagated prefix (nick!user@host) + account; an op member overrides a
        // mute but not a ban. Account/host fall through to host-glob matching.
        const ban_ctx = world_model.World.BanContext{
            .account = if (account.len == 0) null else account,
            .realname = "",
            .host = prefix,
            .country = null,
            .channels = &.{},
        };
        if (self.world.isBannedCtx(channel, ban_ctx)) return .deny;
        if (!modes.canSpeakModerated() and self.world.isMutedCtx(channel, ban_ctx)) {
            if (opmod) opmod_route = true else return .deny;
        }

        const sender_op = modes.isOperator();
        if (!sender_op and self.world.channelHasFlag(channel, .no_ctcp) and isBlockableCtcp(text)) return .deny;
        if (is_notice and !sender_op and self.world.channelHasFlag(channel, .no_notice)) return .deny;
        if (min_rank > 0 and modes.rank() < 1) return .deny;

        const slow_exempt = self.remoteHasOverridePrefix(account) or
            (self.channelSlowmodeVoiceExempt(channel) and modes.canSpeakModerated());
        if (self.slowmodeDenies(channel, nick, slow_exempt)) return .deny;

        return if (opmod_route) .opmoderate else .allow;
    }

    /// Surface a remote (mesh) channel membership change to LOCAL members of
    /// `channel` as live IRC lines, so clients already sitting in the channel see
    /// remote users join/leave/gain-status in real time — not only on a fresh
    /// NAMES. Remote users render with their PROPAGATED real `user@host`
    /// (username + cloaked/visible host from the MEMBERSHIP event), matching the
    /// NAMES projection (`addRemoteMembers`); only an identity-less event falls
    /// back to the `mesh@<origin server>` placeholder.
    ///   - joined: `:nick!user@host JOIN #chan`, then a MODE for any join prefix.
    ///   - status: a MODE diff (added/removed prefix modes vs `prev_status`).
    ///   - parted: `:nick!user@host PART #chan`.
    /// Best-effort: a channel with no local members has no one to notify.
    fn emitRemoteMembership(self: *LinuxServer, ch: anytype, remote_name: []const u8) void {
        const server_host = if (remote_name.len != 0) remote_name else default_host;
        const user = if (ch.username.len != 0) ch.username else world_projection.remote_user_placeholder;
        const host = if (ch.host.len != 0) ch.host else server_host;
        var buf: [900]u8 = undefined;
        switch (ch.kind) {
            .joined => {
                // Membership echo for a nick homed HERE (a peer announcing
                // status for our own member): local clients never lost this
                // user, so re-JOINing would duplicate them — surface only the
                // status diff.
                if (self.nickIsLiveLocal(ch.nick)) {
                    if (ch.status != 0) self.emitRemoteModeDiff(ch.channel, ch.nick, server_host, ch.prev_status, ch.status, ch.setter);
                    return;
                }
                self.noteRaidJoin(ch.channel, server_host);
                const line = std.fmt.bufPrint(&buf, ":{s}!{s}@{s} JOIN :{s}\r\n", .{ ch.nick, user, host, ch.channel }) catch return;
                self.broadcastChannel(ch.channel, line, null) catch return;
                if (ch.status != 0) self.emitRemoteModeDiff(ch.channel, ch.nick, server_host, 0, ch.status, ch.setter);
                // A remote oper carries no grantable channel status, so the diff
                // above won't show its `*`. Announce the derived +Y when a live
                // grant already names this account (applyMeshGrant covers the
                // reverse order, where the grant lands after the JOIN). Local
                // isOverrideOper never matches a remote nick.
                if (self.remoteHasOverridePrefix(ch.account)) self.emitOperPrefixMode(ch.channel, ch.nick, true);
            },
            .parted => {
                if (std.mem.eql(u8, ch.setter, mesh_quit_setter)) {
                    self.emitRemoteQuit(ch, remote_name);
                    return;
                }
                // Echo artifact: the user is still connected here — a fabricated
                // PART would desync client nicklists from the server roster.
                if (self.nickIsLiveLocal(ch.nick)) return;
                const line = std.fmt.bufPrint(&buf, ":{s}!{s}@{s} PART {s}\r\n", .{ ch.nick, user, host, ch.channel }) catch return;
                self.broadcastChannel(ch.channel, line, null) catch {};
            },
            .status => self.emitRemoteModeDiff(ch.channel, ch.nick, server_host, ch.prev_status, ch.status, ch.setter),
            // Not a roster transition — handled in drainIdentityTransitions, never
            // surfaced as an IRC line here.
            .ghost_reclaim => {},
        }
    }

    fn remoteNickInChannel(self: *LinuxServer, channel: []const u8, nick: []const u8) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const members = blk: {
                    if (slot.value.s2s_secured) |link| {
                        if (link.established()) break :blk link.channelMembers(channel);
                    } else if (slot.value.s2s) |link| {
                        if (link.established()) break :blk link.channelMembers(channel);
                    }
                    continue;
                };
                for (members) |member| {
                    if (std.ascii.eqlIgnoreCase(member.nick, nick)) return true;
                }
            }
        }
        return false;
    }

    fn remoteQuitSeenRecently(conn: *ConnState, nick: []const u8, now_ms: i64) bool {
        var folded: [client_model.MAX_NICK_BYTES]u8 = undefined;
        if (nick.len > folded.len) return false;
        for (nick, 0..) |byte, i| folded[i] = std.ascii.toLower(byte);
        const nick_hash = std.hash.Wyhash.hash(0, folded[0..nick.len]);
        const repeated = conn.remote_quit_seen and
            conn.remote_quit_nick_hash == nick_hash and
            now_ms >= conn.remote_quit_at_ms and
            now_ms - conn.remote_quit_at_ms <= remote_quit_dedup_ms;
        if (!repeated) {
            conn.remote_quit_nick_hash = nick_hash;
            conn.remote_quit_at_ms = now_ms;
            conn.remote_quit_seen = true;
        }
        return repeated;
    }

    /// Render one remote logical departure to every local client sharing at
    /// least one channel with the nick. The trigger channel is included even
    /// though its route fact was removed before this derived delta was queued.
    fn emitRemoteQuit(self: *LinuxServer, ch: anytype, remote_name: []const u8) void {
        if (self.nickIsLiveLocal(ch.nick)) return;

        const server_host = if (remote_name.len != 0) remote_name else default_host;
        const user = if (ch.username.len != 0) ch.username else world_projection.remote_user_placeholder;
        const host = if (ch.host.len != 0) ch.host else server_host;
        const reason = if (ch.realname.len != 0) ch.realname else "Client quit";
        var line_buf: [900]u8 = undefined;
        const line = std.fmt.bufPrint(
            &line_buf,
            ":{s}!{s}@{s} QUIT :{s}\r\n",
            .{ ch.nick, user, host, reason },
        ) catch return;

        var recipients: std.ArrayList(client_model.ClientId) = .empty;
        defer recipients.deinit(self.allocator);
        var channels = self.world.channelIterator();
        while (channels.next()) |channel| {
            const trigger_channel = !isPresenceChannel(ch.channel) and
                std.ascii.eqlIgnoreCase(channel.name, ch.channel);
            if (!trigger_channel and !self.remoteNickInChannel(channel.name, ch.nick)) continue;
            var members = self.world.memberIterator(channel.name) orelse continue;
            while (members.next()) |member| {
                const recipient = clientIdFromWorld(member.*);
                const conn = self.connFor(recipient) orelse continue;
                if (conn.s2s != null or conn.s2s_secured != null) continue;
                self.appendUniqueDeliveryId(&recipients, recipient) catch return;
            }
        }

        var tag_buf: [48]u8 = undefined;
        const tag = serverTimeTag(&tag_buf);
        const now_ms = self.nowMs();
        for (recipients.items) |recipient| {
            const conn = self.connFor(recipient) orelse continue;
            if (remoteQuitSeenRecently(conn, ch.nick, now_ms)) continue;
            self.deliverTimed(recipient, tag, line) catch continue;
        }
    }

    /// Emit a `MODE #chan +/-<letters> <nick> …` to local channel members for a
    /// remote member whose prefix modes changed from `prev` to `now`. Combines
    /// the additions and removals into one line (each member mode repeats the
    /// nick as its parameter).
    fn emitRemoteModeDiff(self: *LinuxServer, channel: []const u8, nick: []const u8, host: []const u8, prev: u4, now: u4, setter: []const u8) void {
        const added = now & ~prev;
        const removed = prev & ~now;
        if (added == 0 and removed == 0) return;
        var modes_buf: [16]u8 = undefined;
        var params_buf: [320]u8 = undefined;
        var ml: usize = 0;
        var pl: usize = 0;
        const order = [_]chanmode.MemberMode{ .founder, .owner, .op, .voice };
        inline for ([_]struct { sign: u8, mask: u4 }{ .{ .sign = '+', .mask = @truncate(added) }, .{ .sign = '-', .mask = @truncate(removed) } }) |grp| {
            if (grp.mask != 0) {
                if (ml < modes_buf.len) {
                    modes_buf[ml] = grp.sign;
                    ml += 1;
                }
                for (order) |m| {
                    if ((world_model.MemberModes{ .bits = @as(u8, grp.mask) }).contains(m)) {
                        if (ml < modes_buf.len) {
                            modes_buf[ml] = chanmode.memberModeLetter(m);
                            ml += 1;
                        }
                        const seg = std.fmt.bufPrint(params_buf[pl..], " {s}", .{nick}) catch break;
                        pl += seg.len;
                    }
                }
            }
        }
        // Prefer the actual setter (the oper/owner who ran /MODE) as the source
        // prefix so cross-node MODE reads `:kain MODE …`, not the origin server.
        // Empty setter (link-up resync, no operation context) falls back to host.
        const source = if (setter.len != 0) setter else host;
        var line_buf: [600]u8 = undefined;
        const line = std.fmt.bufPrint(&line_buf, ":{s} MODE {s} {s}{s}\r\n", .{ source, channel, modes_buf[0..ml], params_buf[0..pl] }) catch return;
        self.broadcastChannel(channel, line, null) catch {};
    }

    /// Announce the derived network-operator `*` prefix to a channel's LOCAL
    /// members as a synthetic `:server MODE #chan +Y <nick>` (or `-Y`). The `*`
    /// (+Y) is render-derived from oper status — it is never a stored channel
    /// mode and never rides a JOIN — so already-present clients otherwise only
    /// learn it on a fresh NAMES. This pushes the change live the instant oper
    /// status appears/disappears. Only this node's local members are notified;
    /// peers converge independently when they apply the same oper grant.
    fn emitOperPrefixMode(self: *LinuxServer, channel: []const u8, nick: []const u8, add: bool) void {
        // Idempotence: a mesh relink re-bursts a member's JOIN and its oper
        // grant, and both would announce the derived `*`. Collapse repeats of
        // the same (channel, nick, add) within the dedup window so a rejoining
        // remote oper gets a single +Y, not two (or the churn on every relink).
        if (self.oper_prefix_dedup.seenRecently(channel, nick, add, self.nowMs())) return;
        var buf: [600]u8 = undefined;
        const sign: u8 = if (add) '+' else '-';
        const line = std.fmt.bufPrint(&buf, ":{s} MODE {s} {c}{c} {s}\r\n", .{
            self.serverName(), channel, sign, chanmode.oper_mode_letter, nick,
        }) catch return;
        self.broadcastChannel(channel, line, null) catch {};
    }

    /// True if `nick` is a member of `channel` — whether as a local-world member
    /// or a remote member projected from an established peer roster. Mirrors the
    /// dual lookup `remoteMemberChannels` relies on; caller holds world.lockWrite.
    fn nickInChannelAnywhere(self: *LinuxServer, channel: []const u8, nick: []const u8) bool {
        if (self.world.findNick(nick)) |wid| {
            if (self.world.isMember(channel, wid)) return true;
        }
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const members = blk: {
                    if (slot.value.s2s_secured) |link| {
                        if (link.established()) break :blk link.channelMembers(channel);
                    } else if (slot.value.s2s) |link| {
                        if (link.established()) break :blk link.channelMembers(channel);
                    }
                    continue;
                };
                for (members) |rm| {
                    if (std.ascii.eqlIgnoreCase(rm.nick, nick)) return true;
                }
            }
        }
        return false;
    }

    /// Push the network-operator `*` prefix change for `nick` to every channel it
    /// belongs to, so nicklists update the moment an oper grant is applied or
    /// revoked rather than only on the next NAMES — the gap that left a remote
    /// oper showing un-starred after a mesh relink re-projected it. Caller holds
    /// world.lockWrite (cross-reactor roster read). Best-effort.
    fn announceOperPrefixAllChannels(self: *LinuxServer, nick: []const u8, add: bool) void {
        var cit = self.world.channelIterator();
        while (cit.next()) |cv| {
            if (self.nickInChannelAnywhere(cv.name, nick)) {
                self.emitOperPrefixMode(cv.name, nick, add);
            }
        }
    }

    /// Resolve an authenticated account to the actual nick spellings clients
    /// currently render. Local attachments are authoritative; remote roster
    /// accounts are eligible only when the membership residence proof survived
    /// S2S admission (untrusted rows have an empty account). The temporary set
    /// prevents the fixed-size per-channel dedup ring from being used as a
    /// cross-attachment identity set when one session has many channels.
    fn announceOperPrefixForAccount(self: *LinuxServer, account: []const u8, add: bool) void {
        var nicks: std.ArrayListUnmanaged([]const u8) = .empty;
        defer nicks.deinit(self.allocator);
        var seen = CiNameSet.init(self.allocator);
        defer seen.deinit();

        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                if (!conn.session.registered() or conn.s2s != null or conn.s2s_secured != null) continue;
                const live_account = conn.session.account() orelse continue;
                if (!std.ascii.eqlIgnoreCase(live_account, account)) continue;
                const nick = conn.session.displayName();
                const gop = seen.getOrPut(nick) catch break;
                if (!gop.found_existing) nicks.append(self.allocator, nick) catch break;
            }
        }

        // A grant can arrive before or after the corresponding remote roster.
        // When the roster is present, resolve account -> display nick from every
        // local channel projection. Remote-only channels have no local recipient
        // for this synthetic MODE and therefore need no emission here.
        var cit = self.world.channelIterator();
        while (cit.next()) |cv| {
            for (self.reactors) |*reactor| {
                for (reactor.clients.slots.items) |*slot| {
                    if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                    const members = blk: {
                        if (slot.value.s2s_secured) |link| {
                            if (link.established()) break :blk link.channelMembers(cv.name);
                        } else if (slot.value.s2s) |link| {
                            if (link.established()) break :blk link.channelMembers(cv.name);
                        }
                        continue;
                    };
                    for (members) |member| {
                        if (member.account.len == 0 or !std.ascii.eqlIgnoreCase(member.account, account)) continue;
                        const gop = seen.getOrPut(member.nick) catch break;
                        if (!gop.found_existing) nicks.append(self.allocator, member.nick) catch break;
                    }
                }
            }
        }

        for (nicks.items) |nick| self.announceOperPrefixAllChannels(nick, add);
    }

    /// Same as `announceOperPrefixForAccount`, but only remote roster nicks.
    /// A mesh grant must never mint +Y/-Y for a locally-homed attachment —
    /// those stay configured-local (`isOverrideOper`).
    fn announceRemoteOperPrefixForAccount(self: *LinuxServer, account: []const u8, add: bool) void {
        if (account.len == 0) return;
        var nicks: std.ArrayListUnmanaged([]const u8) = .empty;
        defer nicks.deinit(self.allocator);
        var seen = CiNameSet.init(self.allocator);
        defer seen.deinit();

        var cit = self.world.channelIterator();
        while (cit.next()) |cv| {
            for (self.reactors) |*reactor| {
                for (reactor.clients.slots.items) |*slot| {
                    if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                    const members = blk: {
                        if (slot.value.s2s_secured) |link| {
                            if (link.established()) break :blk link.channelMembers(cv.name);
                        } else if (slot.value.s2s) |link| {
                            if (link.established()) break :blk link.channelMembers(cv.name);
                        }
                        continue;
                    };
                    for (members) |member| {
                        if (member.account.len == 0 or !std.ascii.eqlIgnoreCase(member.account, account)) continue;
                        const gop = seen.getOrPut(member.nick) catch break;
                        if (!gop.found_existing) nicks.append(self.allocator, member.nick) catch break;
                    }
                }
            }
        }

        for (nicks.items) |nick| self.announceOperPrefixAllChannels(nick, add);
    }

    fn emitRemoteChannelModeFlags(self: *LinuxServer, channel: []const u8, remote_name: []const u8, prev: u16, now: u16) void {
        const added = now & ~prev;
        const removed = prev & ~now;
        if (added == 0 and removed == 0) return;

        var modes_buf: [32]u8 = undefined;
        var ml: usize = 0;
        for ([_]struct { sign: u8, mask: u16 }{ .{ .sign = '+', .mask = added }, .{ .sign = '-', .mask = removed } }) |grp| {
            if (grp.mask == 0) continue;
            if (ml < modes_buf.len) {
                modes_buf[ml] = grp.sign;
                ml += 1;
            }
            for (channel_mode_flag_specs) |spec| {
                if ((grp.mask & spec.bit) != 0 and ml < modes_buf.len) {
                    modes_buf[ml] = spec.letter;
                    ml += 1;
                }
            }
        }
        const host = if (remote_name.len != 0) remote_name else default_host;
        var line_buf: [600]u8 = undefined;
        const line = std.fmt.bufPrint(&line_buf, ":{s} MODE {s} {s}\r\n", .{ host, channel, modes_buf[0..ml] }) catch return;
        self.broadcastChannel(channel, line, null) catch {};
    }

    /// Drain MEMBERSHIP and NICKCHANGE through their shared peer-application
    /// order. A resume transition may deliberately arrive as PART(old nick),
    /// NICK(old -> new), JOIN(new nick); draining the historical typed queues in
    /// family order rewrote that sequence and exposed impossible client state.
    /// Consecutive same-channel JOINs are still grouped into bounded NETJOIN
    /// batches, but an intervening NICK is now an ordering barrier.
    fn drainIdentityTransitions(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const remote = link.remoteName();
        const fold_legacy = !link.supportsSessionReplicaV2();

        while (link.takeNextIdentityTransition()) |queued| {
            var transition = queued;
            switch (transition) {
                .nick => |*d| {
                    self.emitRemoteNick(d, remote, link);
                    d.deinit(self.allocator);
                },
                .membership => |*first| {
                    if (fold_legacy) _ = self.foldLegacySessionMembership(link, first, remote);
                    if (first.kind != .joined) {
                        if (first.kind == .ghost_reclaim) {
                            self.reclaimGhostSession(first);
                        } else if (isPresenceChannel(first.channel) and
                            first.kind == .parted and
                            std.mem.eql(u8, first.setter, mesh_quit_setter))
                        {
                            self.emitRemoteQuit(first, remote);
                        } else if (!isPresenceChannel(first.channel)) {
                            self.emitRemoteMembership(first, remote);
                        }
                        first.deinit(self.allocator);
                        continue;
                    }

                    var run: [mesh_batch_chunk]s2s_peer_mod.S2sPeer.MembershipDelta = undefined;
                    run[0] = first.*;
                    var count: usize = 1;
                    while (count < run.len) {
                        const next = link.peekNextMembershipTransition() orelse break;
                        if (next.kind != .joined or !std.mem.eql(u8, next.channel, run[0].channel)) break;
                        var next_transition = link.takeNextIdentityTransition() orelse unreachable;
                        switch (next_transition) {
                            .membership => |*change| {
                                if (fold_legacy) _ = self.foldLegacySessionMembership(link, change, remote);
                                run[count] = change.*;
                                count += 1;
                            },
                            .nick => unreachable,
                        }
                    }

                    if (!isPresenceChannel(run[0].channel)) {
                        if (count >= 2) {
                            self.emitNetjoinRun(run[0].channel, remote, run[0..count]);
                        } else {
                            self.emitRemoteMembership(&run[0], remote);
                        }
                    }
                    for (run[0..count]) |*change| change.deinit(self.allocator);
                },
            }
        }
    }

    /// Consume candidate-link identity deltas without applying or publishing
    /// them. Helix precommit route reconciliation must leave no queued derived
    /// transition that could become visible after activation.
    fn discardIdentityTransitions(self: *LinuxServer, link: anytype) void {
        while (link.takeNextIdentityTransition()) |queued| {
            var transition = queued;
            switch (transition) {
                .nick => |*delta| delta.deinit(self.allocator),
                .membership => |*delta| delta.deinit(self.allocator),
            }
        }
    }

    /// A rolling-old peer may still use token-less MEMBERSHIP to synchronize a
    /// genuine legacy logical session. Once any origin has retained signed v2
    /// identity authority or conflict evidence, however, a hop-by-hop sidecar
    /// must not widen that authority back to every same-account/same-nick token.
    /// The peer rejects this case before routing; this guard is daemon-side
    /// defence in depth. Missing identity/account fails closed naturally in
    /// `applyRemoteSessionMembership` and preserves genuine legacy projection.
    fn shouldFoldLegacySessionMembership(self: *LinuxServer, link: anytype, ch: anytype) bool {
        if (link.supportsSessionReplicaV2()) return false;
        return !self.hasRetainedSessionReplicaNickAuthority(ch.nick);
    }

    fn foldLegacySessionMembership(self: *LinuxServer, link: anytype, ch: anytype, remote_name: []const u8) bool {
        if (!self.shouldFoldLegacySessionMembership(link, ch)) return false;
        self.applyRemoteSessionMembership(ch, remote_name);
        return true;
    }

    fn applyRemoteSessionMembership(self: *LinuxServer, ch: anytype, remote_name: []const u8) void {
        if (ch.account.len == 0 or ch.nick.len == 0 or !self.nickIsLiveLocal(ch.nick)) return;
        const rows = self.sessions.copySessionsAlloc(self.allocator, ch.account) catch return;
        defer self.allocator.free(rows);

        var ids: std.ArrayList(client_model.ClientId) = .empty;
        defer ids.deinit(self.allocator);
        for (rows) |row| {
            if (!row.attached) continue;
            const id = clientIdFromMonitor(row.client);
            const conn = self.connFor(id) orelse continue;
            if (conn.closing) continue;
            const account = conn.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(account, ch.account)) continue;
            if (!std.ascii.eqlIgnoreCase(conn.session.displayName(), ch.nick)) continue;
            ids.append(self.allocator, id) catch return;
        }
        if (ids.items.len == 0) return;

        const host = if (ch.host.len != 0) ch.host else if (remote_name.len != 0) remote_name else default_host;
        const user = if (ch.username.len != 0) ch.username else world_projection.remote_user_placeholder;
        var line_buf: [900]u8 = undefined;
        switch (ch.kind) {
            .joined => {
                for (ids.items) |id| self.world.restoreMember(ch.channel, worldIdFromClient(id), .{ .bits = ch.status }) catch {};
                const line = std.fmt.bufPrint(&line_buf, ":{s}!{s}@{s} JOIN :{s}\r\n", .{ ch.nick, user, host, ch.channel }) catch return;
                self.broadcastChannel(ch.channel, line, null) catch {};
            },
            .parted => {
                const line = std.fmt.bufPrint(&line_buf, ":{s}!{s}@{s} PART {s}\r\n", .{ ch.nick, user, host, ch.channel }) catch return;
                self.broadcastChannel(ch.channel, line, null) catch {};
                for (ids.items) |id| self.world.part(ch.channel, worldIdFromClient(id)) catch {};
            },
            .status => {
                for (ids.items) |id| self.world.restoreMember(ch.channel, worldIdFromClient(id), .{ .bits = ch.status }) catch {};
            },
            .ghost_reclaim => {},
        }
    }

    /// Retire ("ghost-kill") the stale LOCAL session named by a `ghost_reclaim`
    /// delta: the same authenticated account is live on another mesh node with a
    /// strictly-newer claim, so this older local session is the ghost. Defence in
    /// depth before disconnecting anyone: the local holder must still exist, be
    /// authenticated, and match the remote claim's account (case-insensitive). A
    /// missing/changed/anonymous holder is left untouched.
    fn reclaimGhostSession(self: *LinuxServer, d: anytype) void {
        if (d.account.len == 0) return; // never reclaim against an anonymous claim
        const wid = self.world.findNick(d.nick) orelse return;
        const victim_id = clientIdFromWorld(wid);
        const victim = self.connFor(victim_id) orelse return;
        const victim_account = victim.session.account() orelse return;
        if (!std.ascii.eqlIgnoreCase(victim_account, d.account)) return;
        // Multi-device: a still-LIVE local session of the same account is a
        // concurrent device (the bouncer model — sessions.zig tracks up to
        // max_sessions_per_account of them), NOT a stale ghost. A newer login on
        // another mesh node must never kill it; only a connection already tearing
        // down is a genuine ghost worth retiring here. Deliberately reclaiming a
        // *specific* session is the explicit token-based SESSION RESUME path, not
        // this mesh-claim heuristic. Without this guard, opening a second client
        // anywhere on the mesh disconnects the first ("resume anywhere" broken).
        if (!victim.closing) return;
        var buf: [default_reply_bytes]u8 = undefined;
        const ln = std.fmt.bufPrint(&buf, ":{s} ERROR :Session reclaimed (newer login for {s} elsewhere)\r\n", .{ self.serverName(), victim_account }) catch return;
        self.enqueueDeliveryThenClose(victim_id, ln, "Session reclaimed") catch {};
    }

    /// Emit a run of remote joins to one channel as a cap-gated IRCv3 `netjoin`
    /// BATCH (the mirror of `netsplitOnPeerDrop`), chunked so a large rejoin
    /// never drops members. Prefix modes (op/voice/…) follow the batch as MODE
    /// lines, matching the single-join path in `emitRemoteMembership`.
    fn emitNetjoinRun(self: *LinuxServer, channel: []const u8, remote_name: []const u8, run: anytype) void {
        const server_host = if (remote_name.len != 0) remote_name else default_host;
        var off: usize = 0;
        while (off < run.len) {
            const chunk_end = @min(off + mesh_batch_chunk, run.len);
            var ghosts: [mesh_batch_chunk]netsplit_batch.Ghost = undefined;
            var prefixes: [mesh_batch_chunk][420]u8 = undefined;
            var n: usize = 0;
            for (run[off..chunk_end]) |*ch| {
                // Skip membership echoes of locally-homed users — they never
                // split, so local clients never lost their JOIN. (#64)
                if (self.nickIsLiveLocal(ch.nick)) continue;
                self.noteRaidJoin(channel, server_host);
                const user = if (ch.username.len != 0) ch.username else world_projection.remote_user_placeholder;
                const host = if (ch.host.len != 0) ch.host else server_host;
                const prefix = std.fmt.bufPrint(&prefixes[n], "{s}!{s}@{s}", .{ ch.nick, user, host }) catch continue;
                ghosts[n] = .{ .prefix = prefix, .nick = ch.nick };
                n += 1;
            }
            off = chunk_end;
            if (n == 0) continue;

            var ref_buf: [18]u8 = undefined;
            const ref = netsplit_batch.makeBatchRef(&ref_buf, mesh_batch_ref_seq.fetchAdd(1, .monotonic));
            var batch_buf: [mesh_batch_buf_len]u8 = undefined;
            var plain_buf: [mesh_batch_buf_len]u8 = undefined;
            const batched = netsplit_batch.writeNetjoin(&batch_buf, ref, self.serverName(), remote_name, channel, ghosts[0..n]) catch continue;
            const plain = netsplit_batch.writeJoinsPlain(&plain_buf, channel, ghosts[0..n]) catch continue;
            self.deliverChannelBatchGated(channel, batched, plain);
        }
        // Prefix modes for the joined members, after the batch (display-only;
        // world roster was already updated on receive). A locally-homed nick
        // echoed back in a link-up burst never actually left, so diff against its
        // REAL prev_status (mirroring emitRemoteMembership's single-join path) —
        // an unchanged status is then a no-op, so a relink/upgrade re-burst no
        // longer spams a spurious ":server MODE #chan +Q <nick>". A genuine remote
        // join is still announced from 0 (full prefix modes).
        for (run) |*ch| {
            if (ch.status != 0) {
                const prev: u4 = if (self.nickIsLiveLocal(ch.nick)) ch.prev_status else 0;
                self.emitRemoteModeDiff(channel, ch.nick, server_host, prev, ch.status, ch.setter);
            }
            if (!self.nickIsLiveLocal(ch.nick) and self.remoteHasOverridePrefix(ch.account)) {
                self.emitOperPrefixMode(channel, ch.nick, true);
            }
        }
    }

    /// Drain a link's remote aggregate channel MODE flag changes, apply each to
    /// the local world, and surface the actual local delta as a MODE line.
    fn drainChannelModeFlagChanges(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const changes = link.takeChannelModeFlagChanges() catch return;
        const remote = link.remoteName();
        for (changes) |*ch| {
            if (self.world.channelExists(ch.channel)) {
                const prev = self.channelModeFlagBits(ch.channel);
                self.setChannelModeFlagBits(ch.channel, ch.flags);
                const now = self.channelModeFlagBits(ch.channel);
                self.emitRemoteChannelModeFlags(ch.channel, remote, prev, now);
            }
            ch.deinit(self.allocator);
        }
        self.allocator.free(changes);
    }

    /// Drain remote parameter/IRCX channel MODE snapshots, preserving local MLOCK
    /// authority and surfacing actual local deltas as MODE lines.
    fn drainChannelModeStateChanges(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const changes = link.takeChannelModeStateChanges() catch return;
        const remote = link.remoteName();
        for (changes) |*ch| {
            var before: ChannelModeStateSnapshot = undefined;
            var after: ChannelModeStateSnapshot = undefined;
            if (self.applyRemoteChannelModeState(ch, &before, &after)) {
                self.emitRemoteChannelModeState(ch.channel, remote, &before, &after);
            }
            ch.deinit(self.allocator);
        }
        self.allocator.free(changes);
    }

    fn drainOriginRejections(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const rejected = link.takeRejectedOriginFrames();
        if (rejected == 0) return;
        var buf: [160]u8 = undefined;
        const msg = std.fmt.bufPrint(
            &buf,
            "dropped {d} S2S frame(s) with origin not matching authenticated peer {s}",
            .{ rejected, link.remoteName() },
        ) catch "dropped S2S frame(s) with mismatched origin";
        self.traceLog(.warn, .s2s, msg);
    }

    fn applyRemoteChannelModeState(
        self: *LinuxServer,
        ch: anytype,
        before: *ChannelModeStateSnapshot,
        after: *ChannelModeStateSnapshot,
    ) bool {
        if (self.mlocks.get(ch.channel) != null) {
            self.traceLog(.info, .s2s, "remote channel mode state ignored on mlocked channel");
            return false;
        }
        self.world.ensureRemoteListChannel(ch.channel) catch return false;
        before.* = self.channelModeStateSnapshot(ch.channel);

        _ = self.world.setPrivate(ch.channel, ch.private) catch return false;
        _ = self.world.setHidden(ch.channel, ch.hidden) catch return false;
        self.world.setChannelKey(ch.channel, ch.key) catch return false;
        self.world.setChannelLimit(ch.channel, ch.limit) catch return false;
        if (ch.throttle_joins != 0 and ch.throttle_secs != 0) {
            self.world.setThrottle(ch.channel, ch.throttle_joins, ch.throttle_secs) catch return false;
        } else {
            self.world.clearThrottle(ch.channel) catch return false;
        }
        if (ch.forward) |target| {
            if (!chan_forward.validForwardTarget(target, ch.channel)) return false;
            self.world.setForward(ch.channel, target) catch return false;
        } else {
            self.world.setForward(ch.channel, null) catch return false;
        }

        const ext: chanmode_ext.ExtChannelFlags = @bitCast(ch.ext_bits);
        for (chanmode_ext.mode_specs) |spec| {
            _ = self.world.setChannelExtFlag(ch.channel, spec.flag, ext.has(spec.flag)) catch return false;
        }
        after.* = self.channelModeStateSnapshot(ch.channel);
        return !before.eql(after);
    }

    fn emitRemoteChannelModeState(
        self: *LinuxServer,
        channel: []const u8,
        remote_name: []const u8,
        before: *const ChannelModeStateSnapshot,
        after: *const ChannelModeStateSnapshot,
    ) void {
        var modes_buf: [128]u8 = undefined;
        var modes = Buf{ .storage = &modes_buf };
        var targets_buf: [512]u8 = undefined;
        var targets = Buf{ .storage = &targets_buf };
        var sign: u8 = 0;

        appendStateFlagDiff(&modes, &sign, 'p', before.private, after.private);
        appendStateFlagDiff(&modes, &sign, 'h', before.hidden, after.hidden);
        for (chanmode_ext.mode_specs) |spec| {
            if (spec.flag == .private or spec.flag == .hidden) continue;
            const was = extBitHas(before.ext_bits, spec.flag);
            const now = extBitHas(after.ext_bits, spec.flag);
            appendStateFlagDiff(&modes, &sign, spec.letter, was, now);
        }
        if (!optSliceEql(before.key(), after.key())) {
            if (after.key()) |key|
                appendParamMode(&modes, &targets, &sign, '+', 'k', key)
            else
                appendParamMode(&modes, &targets, &sign, '-', 'k', "*");
        }
        if (before.limit != after.limit) {
            if (after.limit) |limit| {
                var limit_buf: [16]u8 = undefined;
                const text = std.fmt.bufPrint(&limit_buf, "{d}", .{limit}) catch "";
                appendParamMode(&modes, &targets, &sign, '+', 'l', text);
            } else {
                appendModeLetter(&modes, &sign, '-', 'l');
            }
        }
        if (before.throttle_joins != after.throttle_joins or before.throttle_secs != after.throttle_secs) {
            if (after.throttle_joins != 0 and after.throttle_secs != 0) {
                var throttle_buf: [32]u8 = undefined;
                const text = std.fmt.bufPrint(&throttle_buf, "{d}:{d}", .{ after.throttle_joins, after.throttle_secs }) catch "";
                appendParamMode(&modes, &targets, &sign, '+', 'j', text);
            } else {
                appendModeLetter(&modes, &sign, '-', 'j');
            }
        }
        if (!optSliceEql(before.forward(), after.forward())) {
            if (after.forward()) |target|
                appendParamMode(&modes, &targets, &sign, '+', 'f', target)
            else
                appendModeLetter(&modes, &sign, '-', 'f');
        }
        if (modes.written().len == 0) return;

        const prefix = if (remote_name.len != 0) remote_name else self.serverName();
        var line_buf: [default_reply_bytes]u8 = undefined;
        var line = Buf{ .storage = &line_buf };
        line.append(":") catch return;
        line.append(prefix) catch return;
        line.append(" MODE ") catch return;
        line.append(channel) catch return;
        line.appendByte(' ') catch return;
        line.append(modes.written()) catch return;
        line.append(targets.written()) catch return;
        line.append("\r\n") catch return;
        self.broadcastChannel(channel, line.written(), null) catch {};
    }

    fn appendStateFlagDiff(modes: *Buf, sign: *u8, letter: u8, before: bool, after: bool) void {
        if (before == after) return;
        appendModeLetter(modes, sign, if (after) '+' else '-', letter);
    }

    fn extBitHas(bits: u32, flag: chanmode_ext.ExtChannelFlag) bool {
        const flags: chanmode_ext.ExtChannelFlags = @bitCast(bits);
        return flags.has(flag);
    }

    /// Account + audit a dropped remote CHANNEL_PROP fact whose self-contained
    /// multi-hop origin signature failed. Reuses the daemon-level multi-hop reject
    /// counter (`rejected_relay_signatures`, shared with the MESSAGE relay) and the
    /// same `.s2s` warn audit signal direct-frame origin rejections use.
    fn recordChannelPropSignatureReject(self: *LinuxServer, ch: anytype, reason: []const u8) void {
        self.rejected_relay_signatures +|= 1;
        var buf: [256]u8 = undefined;
        const line = std.fmt.bufPrint(
            &buf,
            "dropped CHANNEL_PROP {s}/{s} claiming origin {d}: {s}",
            .{ ch.channel, ch.key, ch.origin_node, reason },
        ) catch "dropped CHANNEL_PROP with bad origin signature";
        self.traceLog(.warn, .s2s, line);
    }

    /// Verify an inbound CHANNEL_PROP fact's self-contained multi-hop origin
    /// signature. `.unsigned`/`.verified` => apply; any rejection drops the fact
    /// (never applied, never re-emitted) and is counted + audited. Fails CLOSED on
    /// an allocation failure during verification.
    fn channelPropOriginVerified(self: *LinuxServer, ch: anytype) bool {
        const ev = channel_prop_event.ChannelPropEvent{
            .present = ch.present,
            .origin_node = ch.origin_node,
            .hlc = ch.hlc,
            .channel = ch.channel,
            .key = ch.key,
            .value = ch.value,
            .owner = ch.owner,
            .origin_pubkey = ch.origin_pubkey,
            .origin_sig = ch.origin_sig,
        };
        const outcome = channel_prop_event.verifyOrigin(self.allocator, ev) catch {
            self.recordChannelPropSignatureReject(ch, "verification allocation failed");
            return false;
        };
        return switch (outcome) {
            .unsigned, .verified => true,
            .origin_mismatch => blk: {
                self.recordChannelPropSignatureReject(ch, "origin pubkey does not self-certify the claimed origin node");
                break :blk false;
            },
            .bad_signature => blk: {
                self.recordChannelPropSignatureReject(ch, "origin signature verification failed");
                break :blk false;
            },
        };
    }

    fn applyRemoteChannelProp(self: *LinuxServer, ch: anytype) bool {
        // End-to-end origin authentication BEFORE applying. A fact carrying a
        // self-contained signature is verified against the CLAIMED origin (self-
        // certifying). On failure it is dropped here — never applied, never
        // re-broadcast — so a relay cannot forge or alter another node's fact. An
        // unsigned fact follows the legacy path unchanged (already gated at the
        // per-link layer for signing peers).
        if (!self.channelPropOriginVerified(ch)) return false;
        if (self.channelPropClock(ch.channel, ch.key)) |entry| {
            if (ch.hlc <= entry.hlc) return false;
        }
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = ch.channel };
        // Preserve a valid clock-only tombstone for a missing property, but
        // reject malformed entity/key bytes before they touch the causal clock.
        _ = self.props.getPropRaw(entity, ch.key) catch |err| switch (err) {
            error.PropMissing => {},
            else => return false,
        };
        const owner = if (ch.owner.len != 0) ch.owner else "remote";
        if (ch.present) {
            self.props.preflightSetProp(entity, ch.key, ch.value, .{ .id = owner, .access = .server }) catch
                return false;
        }
        if (!self.observeRemotePropertyHlc(ch.hlc)) return false;
        if (ch.present) {
            _ = self.props.setProp(entity, ch.key, ch.value, .{ .id = owner, .access = .server }) catch return false;
        } else {
            self.props.deleteProp(entity, ch.key) catch {};
        }
        // Store the ORIGINAL author's origin id + signature so a later
        // re-broadcast/burst re-emits the original author's `(pubkey, sig)` — the
        // multi-hop guarantee — not this relay's.
        return self.recordChannelPropClock(ch.channel, ch.key, owner, ch.hlc, ch.present, ch.origin_node, ch.origin_pubkey, ch.origin_sig);
    }

    fn emitRemoteChannelProp(self: *LinuxServer, ch: anytype, remote_name: []const u8) void {
        const host = if (remote_name.len != 0) remote_name else self.serverName();
        var buf: [900]u8 = undefined;
        const line = if (ch.present)
            std.fmt.bufPrint(&buf, ":{s} PROP {s} {s} :{s}\r\n", .{ host, ch.channel, ch.key, ch.value }) catch return
        else
            std.fmt.bufPrint(&buf, ":{s} PROP {s} {s} :\r\n", .{ host, ch.channel, ch.key }) catch return;
        // Same IRCX-gated, per-tier fanout as a local change: a secret key reaches
        // only local members at/above its tier (no leak), a non-secret key reaches
        // all local IRCX members. No local setter to exclude (mesh origin).
        self.fanChannelPropNotify(ch.channel, ch.key, line, null);
    }

    /// Drain a link's remote IRCX channel PROP changes, apply them LWW to the
    /// local store, and fan PROP-change lines out to local IRCX members (per-tier
    /// for secret keys), mirroring a local change's visibility.
    fn drainChannelPropChanges(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const changes = link.takeChannelPropChanges() catch return;
        const remote = link.remoteName();
        for (changes) |*ch| {
            if (self.applyRemoteChannelProp(ch)) {
                self.emitRemoteChannelProp(ch, remote);
            }
            ch.deinit(self.allocator);
        }
        self.allocator.free(changes);
    }

    fn applyRemoteChannelList(self: *LinuxServer, ch: anytype) bool {
        if (ch.present) {
            self.world.ensureRemoteListChannel(ch.channel) catch return false;
            return switch (ch.kind) {
                .ban => self.world.addBan(ch.channel, ch.mask, ch.setter, ch.set_at) catch false,
                .exempt => self.world.addExempt(ch.channel, ch.mask, ch.setter, ch.set_at) catch false,
                .invex => self.world.addInvex(ch.channel, ch.mask, ch.setter, ch.set_at) catch false,
                .quiet => self.world.addMute(ch.channel, ch.mask, ch.setter, ch.set_at) catch false,
            };
        }
        return switch (ch.kind) {
            .ban => self.world.removeBan(ch.channel, ch.mask) catch false,
            .exempt => self.world.removeExempt(ch.channel, ch.mask) catch false,
            .invex => self.world.removeInvex(ch.channel, ch.mask) catch false,
            .quiet => self.world.removeMute(ch.channel, ch.mask) catch false,
        };
    }

    fn emitRemoteChannelList(self: *LinuxServer, ch: anytype, remote_name: []const u8) void {
        const prefix = if (ch.setter.len != 0) ch.setter else if (remote_name.len != 0) remote_name else self.serverName();
        var line_buf: [1024]u8 = undefined;
        const line = std.fmt.bufPrint(
            &line_buf,
            ":{s} MODE {s} {c}{c} {s}\r\n",
            .{ prefix, ch.channel, if (ch.present) @as(u8, '+') else @as(u8, '-'), ch.kind.letter(), ch.mask },
        ) catch return;
        self.broadcastChannel(ch.channel, line, null) catch {};
    }

    /// Drain remote +b/+e/+I list-mode changes, apply them to local world state,
    /// and surface real changes as MODE lines to local channel members.
    fn drainChannelListChanges(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const changes = link.takeChannelListChanges() catch return;
        const remote = link.remoteName();
        for (changes) |*ch| {
            if (self.applyRemoteChannelList(ch)) self.emitRemoteChannelList(ch, remote);
            ch.deinit(self.allocator);
        }
        self.allocator.free(changes);
    }

    /// Drain remote channel topic changes, apply each to the local world (so
    /// TOPIC queries reflect it), and surface a live `TOPIC` line to local
    /// members. The route-table LWW already gated stale/re-burst events.
    fn drainTopicChanges(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const changes = link.takeTopicChanges() catch return;
        const remote = link.remoteName();
        for (changes) |*ch| {
            // Only surface the topic to local members when this node actually
            // applied it: a +t-rejected remote topic must neither change state
            // nor be echoed as a live TOPIC line.
            if (self.applyRemoteTopic(ch)) {
                self.emitRemoteTopic(ch, remote);
                self.chanstatsEvent(ch.channel, ch.setter, "TOPIC", ch.topic);
            }
            ch.deinit(self.allocator);
        }
        self.allocator.free(changes);
    }

    /// Apply an inbound remote TOPIC to the local projection. Returns true when
    /// applied, false when rejected by local policy or when the event is an
    /// unchanged re-affirmation (so the caller suppresses the live emit).
    fn applyRemoteTopic(self: *LinuxServer, ch: anytype) bool {
        if (!self.world.channelExists(ch.channel)) return false;
        // Unchanged re-affirmation dedup, keyed on the WORLD topic — state that
        // survives a Helix upgrade in the World capsule. The topic re-burst
        // (`sendTopicBurstTo`: RESYNC answers and the periodic anti-entropy
        // cadence) stamps a FRESH mesh HLC, so the per-link route-table LWW
        // clock cannot gate it: post-upgrade the link's clock was reset, and in
        // steady state the fresh HLC always supersedes. Every sibling drain
        // (mode flags, mode state, lists) already diffs against the carried
        // World before emitting; topics must do the same, or every re-burst
        // re-announces `:setter TOPIC #chan :<unchanged text>` to local
        // members. A genuine change (different text, setter, or set_at — a
        // deliberate re-SET of the same text included) still applies + emits.
        const cur = self.world.topicInfo(ch.channel);
        if (ch.present) {
            if (cur) |info| {
                if (std.mem.eql(u8, info.text, ch.topic) and
                    std.mem.eql(u8, info.setter, ch.setter) and
                    info.set_at == ch.set_at) return false;
            }
        } else if (cur == null or cur.?.text.len == 0) {
            return false; // clearing an already-absent topic is a no-op
        }
        // Receiver-side defense-in-depth, mirroring handleTopic: when THIS node's
        // projection has +t (topic_ops), only an op/founder may change the topic.
        // Resolve the remote setter's status across the combined local+remote
        // projection (the setter is a nick/prefix); reject (do not apply, do not
        // emit) when +t is set and the setter is not op/founder. Without +t we
        // apply as before. Fail-closed under +t only — a setter we cannot resolve
        // as op is rejected, matching the local policy for non-ops.
        if (self.world.channelHasFlag(ch.channel, .topic_ops)) {
            const setter_nick = setterNick(ch.setter);
            const modes = self.relaySenderModes(ch.channel, setter_nick);
            if (!modes.isOperator()) return false;
        }
        if (ch.present) {
            self.world.setTopic(ch.channel, ch.topic, ch.setter, ch.set_at) catch return false;
        } else {
            self.world.setTopic(ch.channel, "", ch.setter, ch.set_at) catch return false;
        }
        return true;
    }

    /// Extract the bare nick from a setter field that may be a full
    /// `nick!user@host` prefix or just a bare nick (the topic setter is stored as
    /// the client prefix). Returns the substring up to the first `!`.
    fn setterNick(setter: []const u8) []const u8 {
        if (std.mem.indexOfScalar(u8, setter, '!')) |bang| return setter[0..bang];
        return setter;
    }

    fn emitRemoteTopic(self: *LinuxServer, ch: anytype, remote_name: []const u8) void {
        // Only locally-known channels have local members to notify.
        if (!self.world.channelExists(ch.channel)) return;
        const prefix = if (ch.setter.len != 0) ch.setter else if (remote_name.len != 0) remote_name else self.serverName();
        var buf: [900]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} TOPIC {s} :{s}\r\n", .{ prefix, ch.channel, ch.topic }) catch return;
        self.broadcastChannel(ch.channel, line, null) catch {};
    }

    fn emitRemoteNick(self: *LinuxServer, d: anytype, remote_name: []const u8, link: anytype) void {
        // A verified same-identity mesh attachment may rename its generated
        // pre-resume nick into the exact nick already homed here. Clients never
        // saw that route-only PRESENCE alias as a channel member, and emitting a
        // NICK into an already-live local nick is both redundant and invalid IRC.
        // Untrusted/different-account collisions are UID-resolved in S2sPeer and
        // therefore do not reach this real-nick suppression.
        if (self.nickIsLiveLocal(d.new_nick)) return;
        const user = if (d.username.len != 0) d.username else world_projection.remote_user_placeholder;
        const host = if (d.host.len != 0) d.host else if (remote_name.len != 0) remote_name else default_host;
        var buf: [900]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s}!{s}@{s} NICK {s}\r\n", .{ d.old_nick, user, host, d.new_nick }) catch return;

        // Deliver once per local client that shares any channel with the renamed
        // remote user (now stored under new_nick in the peer's rosters).
        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();
        var it = self.world.channels.iterator();
        while (it.next()) |entry| {
            const channel = entry.key_ptr.*;
            var present = false;
            for (link.channelMembers(channel)) |m| {
                if (std.ascii.eqlIgnoreCase(m.nick, d.new_nick)) {
                    present = true;
                    break;
                }
            }
            if (!present) continue;
            var members = self.world.memberIterator(channel) orelse continue;
            while (members.next()) |member| {
                const mid = clientIdFromWorld(member.*);
                const key = @as(u64, @bitCast(mid));
                if (seen.contains(key)) continue;
                seen.put(key, {}) catch {};
                self.deliver(mid, line) catch {};
            }
        }
    }

    /// Announce a local channel topic change to every established mesh peer so
    /// their members see the new topic in real time.
    fn announceTopic(self: *LinuxServer, channel: []const u8, topic: []const u8, setter: []const u8, set_at: i64, present: bool) void {
        const hlc = self.nextMeshHlc();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    link.sendTopic(channel, topic, setter, set_at, hlc, present) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendTopic(channel, topic, setter, set_at, hlc, present) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    /// Announce a local user's nick change to every established mesh peer so their
    /// rosters rename the user and their members see a live NICK line.
    /// Predicate for the mesh route table's cross-namespace NICK collision check:
    /// true iff a LOCAL client currently holds `nick` (RFC-1459 case-insensitive,
    /// lock-free via the world's RCU nick mirror). Local nicks are authoritative,
    /// so an incoming remote nick that matches one is renamed to its mesh UID.
    /// S2S runs reactor-0-only, so this read never races a concurrent reactor's
    /// nick mutation in a way the RCU mirror does not already serialize.
    fn localNickHeld(ctx: *anyopaque, nick: []const u8) bool {
        const self: *LinuxServer = @ptrCast(@alignCast(ctx));
        return self.world.findNick(nick) != null;
    }

    /// The authenticated account of the LOCAL client currently holding `nick`, or
    /// null when no local client holds it or the holder is not logged in. Borrowed
    /// for the duration of the synchronous resolve call. Lets the route table tell
    /// a same-identity duplicate (account-aware reconcile) from a genuine collision.
    fn localNickAccount(ctx: *anyopaque, nick: []const u8) ?[]const u8 {
        const self: *LinuxServer = @ptrCast(@alignCast(ctx));
        const wid = self.world.findNick(nick) orelse return null;
        const conn = self.connFor(clientIdFromWorld(wid)) orelse return null;
        const acct = conn.session.account() orelse return null;
        return if (acct.len != 0) acct else null;
    }

    /// The mesh-claim HLC of the LOCAL client holding `nick` (0 = unknown / not
    /// held), so the route table can tell a stale ghost from the live session.
    fn localNickHlc(ctx: *anyopaque, nick: []const u8) u64 {
        const self: *LinuxServer = @ptrCast(@alignCast(ctx));
        const wid = self.world.findNick(nick) orelse return 0;
        const conn = self.connFor(clientIdFromWorld(wid)) orelse return 0;
        return conn.mesh_nick_hlc;
    }

    /// Exact reusable-session token held by the local nick owner. Account
    /// equality alone is insufficient here: only the exact signed session may
    /// collapse a remote UID sidecar into this canonical local identity.
    fn localNickSessionToken(ctx: *anyopaque, nick: []const u8) ?s2s_link.S2sLink.SessionToken {
        const self: *LinuxServer = @ptrCast(@alignCast(ctx));
        const wid = self.world.findNick(nick) orelse return null;
        const id = clientIdFromWorld(wid);
        const conn = self.connFor(id) orelse return null;
        const account = conn.session.account() orelse return null;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return null;
        return handle.token;
    }

    /// Build the borrowed `LocalNickResolver` the mesh links consult; `self` must
    /// outlive every link (it does — links are torn down before server shutdown).
    fn localNickResolver(self: *LinuxServer) s2s_link.S2sLink.LocalNickResolver {
        return .{
            .ctx = self,
            .held_fn = localNickHeld,
            .account_fn = localNickAccount,
            .hlc_fn = localNickHlc,
            .session_token_fn = localNickSessionToken,
        };
    }

    /// The `identity.key.*` / `identity.residence.*` account-identity props are
    /// replicated over ENTITY_PROP, whose ingest (`entityPropOriginVerified` ->
    /// `entity_prop_event.verifyOrigin`) authenticates only that the AUTHORING
    /// node self-certifies its OWN origin — it does NOT check that the node is
    /// AUTHORITATIVE for the account entity. Without more, any admitted (but
    /// Byzantine) peer could inject `identity.key.<victim>` = its own key AND a
    /// matching `identity.residence.<victim>` proof it signs, and `residenceTrusted`
    /// would then verify it — defeating F1. This callback does not treat a
    /// replicated identity pubkey as account authority.
    ///
    /// RECEIVER-side residence callback. Signed SESSION_REPLICA_V2 authority is
    /// the only account proof. A live local non-s2s client must match that
    /// client's own token: a missing proof stays untrusted and does not fall
    /// through to some other token's offer. A node with no such local holder
    /// trusts one unique live origin entry whose account and nick match.
    /// Ambiguous or mismatched store facts are rejected. A compromised origin
    /// can still sign a replica for its own users. `identity.key.*` and
    /// `identity.residence.*` props stay untrusted.
    const SessionReplicaResidenceDecision = enum { none, trusted, mismatch };

    fn sessionReplicaResidenceDecision(
        self: *LinuxServer,
        account: []const u8,
        nick: []const u8,
        origin_node: u64,
    ) SessionReplicaResidenceDecision {
        if (nick.len == 0 or origin_node == 0) return .none;
        if (self.world.findNick(nick)) |wid| {
            const id = clientIdFromWorld(wid);
            if (self.connFor(id)) |conn| {
                if (!conn.closing and conn.s2s == null and conn.s2s_secured == null) {
                    const local_account = conn.session.account() orelse return .none;
                    if (!std.ascii.eqlIgnoreCase(conn.session.displayName(), nick)) return .none;
                    const handle = self.sessions.resumeHandleForClient(local_account, monitorIdFromClient(id)) orelse return .none;
                    const entry = self.session_replica_store.getOrigin(handle.token, origin_node) orelse return .none;
                    const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
                    if (entry.quarantine_until_ms != null or now_wall > entry.expires_at_ms) return .none;
                    if (!std.ascii.eqlIgnoreCase(entry.account, local_account) or
                        !std.ascii.eqlIgnoreCase(entry.nick, nick)) return .mismatch;
                    return if (account.len != 0 and std.ascii.eqlIgnoreCase(account, local_account)) .trusted else .mismatch;
                }
            }
        }
        return self.storedReplicaResidence(account, nick, origin_node);
    }

    fn storedReplicaResidence(
        self: *LinuxServer,
        account: []const u8,
        nick: []const u8,
        origin_node: u64,
    ) SessionReplicaResidenceDecision {
        if (account.len == 0) return .none;
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        const identity = self.session_replica_store.uniqueLiveOriginNick(origin_node, nick, now_wall) catch return .mismatch;
        const live = identity orelse return .none;
        if (!std.ascii.eqlIgnoreCase(live.entry.account, account) or
            !std.ascii.eqlIgnoreCase(live.entry.nick, nick)) return .mismatch;
        return .trusted;
    }

    fn sessionReplicaResidenceTrusted(
        self: *LinuxServer,
        account: []const u8,
        nick: []const u8,
        origin_node: u64,
    ) bool {
        return self.sessionReplicaResidenceDecision(account, nick, origin_node) == .trusted;
    }

    /// Conservative downgrade guard for the legacy fold. Unlike collision
    /// trust, which is intentionally bound to the one World nick owner, this
    /// scans the retained signed Store because the authoritative token may be
    /// rowless here while a distinct-token same-identity decoy is live. The
    /// tokenless sidecar is hop-by-hop while Store authority is end-to-end, so
    /// one or several retained tokens from any origin forbid broad account+nick
    /// mutation. The Store predicate is allocation-free and applies IRC
    /// casemapping, so forwarding and case variants cannot bypass the guard.
    fn hasRetainedSessionReplicaNickAuthority(self: *LinuxServer, nick: []const u8) bool {
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        return self.session_replica_store.hasRetainedNick(nick, now_wall);
    }

    fn residenceTrusted(
        ctx: *anyopaque,
        account: []const u8,
        nick: []const u8,
        origin_node: u64,
        session_replica_v2_negotiated: bool,
    ) s2s_link.S2sLink.ResidenceDecision {
        const self: *LinuxServer = @ptrCast(@alignCast(ctx));
        // Store authority is valid only inside the exact currently-negotiated v2
        // transport. A signed peer may omit the capability on reconnect; that
        // downgrade must never unlock account trust for token-less MEMBERSHIP.
        if (session_replica_v2_negotiated) {
            return switch (self.sessionReplicaResidenceDecision(account, nick, origin_node)) {
                .trusted => .trusted,
                .mismatch => .reject,
                .none => .untrusted,
            };
        }
        // Once end-to-end token authority (or unexpired conflict evidence) exists
        // for this identity, token-less claims are neither a legacy trust path nor
        // an ordinary UID collision. Reject them before RouteTable mutation.
        // The wire account is attacker-controlled on a downgraded transport.
        // Retained v2 nick authority wins even if the peer omits or substitutes
        // an account; otherwise that substitution could move the protected route.
        if (self.hasRetainedSessionReplicaNickAuthority(nick)) return .reject;
        if (account.len == 0) return .untrusted;
        // E5E1: replicated identity.key/residence props are retired as an
        // account-authority source. Only the exact negotiated SESSION_REPLICA_V2
        // proof path above can return trusted.
        return .untrusted;
    }

    /// Build the borrowed `ResidenceVerifier` the mesh links consult (Design C).
    fn residenceVerifier(self: *LinuxServer) s2s_link.S2sLink.ResidenceVerifier {
        return .{ .ctx = self, .verify_fn = residenceTrusted };
    }

    /// Bind token-less MEMBERSHIP compatibility frames to exact signed Store
    /// authority entirely on the receiver. A frame can mutate a token-owned row
    /// only when one live `(origin,nick)` authority is unambiguous and its
    /// deterministic best snapshot agrees with the frame's present/absent fact.
    fn resolveSessionMembershipToken(
        ctx: *anyopaque,
        origin_node: u64,
        nick: []const u8,
        channel: []const u8,
        present: bool,
    ) s2s_link.S2sLink.SessionTokenDecision {
        const self: *LinuxServer = @ptrCast(@alignCast(ctx));
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        const identity = self.session_replica_store.uniqueLiveOriginNick(origin_node, nick, now_wall) catch
            return .reject;
        const exact = identity orelse {
            // A case variant, another-origin claim, or retained quarantine is
            // still signed authority for this logical nick. Never widen it into
            // an untagged compatibility row merely because this exact origin did
            // not select a unique token.
            if (self.session_replica_store.hasRetainedNick(nick, now_wall)) return .reject;
            return .unbound;
        };
        const best = self.session_replica_store.bestLiveIdentity(exact.token, now_wall) orelse return .reject;
        var snapshot = migration_relay.Snapshot.decode(self.allocator, best.snapshot) catch return .reject;
        defer snapshot.deinit(self.allocator);
        if (!std.ascii.eqlIgnoreCase(snapshot.account, best.account) or
            !std.ascii.eqlIgnoreCase(snapshot.nick, best.nick)) return .reject;
        // The token's deterministic winner may be a newer rename from another
        // origin. Never let an older origin keep mutating the obsolete nick even
        // when both snapshots contain the same channel.
        if (!std.ascii.eqlIgnoreCase(nick, best.nick)) return .reject;
        const desired_present = sessionSnapshotChannelMode(&snapshot, channel) != null;
        if (present != desired_present) return .reject;
        return .{ .bind = exact.token };
    }

    fn sessionTokenResolver(self: *LinuxServer) s2s_link.S2sLink.SessionTokenResolver {
        return .{ .ctx = self, .resolve_fn = resolveSessionMembershipToken };
    }

    fn authorizeSessionTokenNick(
        ctx: *anyopaque,
        origin_node: u64,
        old_nick: []const u8,
        tagged_token: ?session_migrate.Token,
        new_nick: []const u8,
    ) s2s_link.S2sLink.SessionTokenNickDecision {
        const self: *LinuxServer = @ptrCast(@alignCast(ctx));
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        if (tagged_token) |token| {
            const best = self.session_replica_store.bestLiveIdentity(token, now_wall) orelse return .reject;
            return if (std.ascii.eqlIgnoreCase(best.nick, new_nick)) .{ .bind = token } else .reject;
        }

        // Compatibility NICKCHANGE has no token on the wire. Bind it only when
        // receiver-owned Store authority selects exactly one token for the old
        // origin/nick, or for an authority-first rename already published under
        // the new nick. Any ambiguity is a hard rejection. With no matching
        // origin authority, retained authority for either identity still blocks
        // the token-less path; only a genuinely legacy identity may pass.
        if (self.session_replica_store.uniqueLiveOriginNick(origin_node, old_nick, now_wall) catch return .reject) |identity| {
            const best = self.session_replica_store.bestLiveIdentity(identity.token, now_wall) orelse return .reject;
            return if (std.ascii.eqlIgnoreCase(best.nick, new_nick)) .{ .bind = identity.token } else .reject;
        }
        if (self.session_replica_store.uniqueLiveOriginNick(origin_node, new_nick, now_wall) catch return .reject) |identity| {
            const best = self.session_replica_store.bestLiveIdentity(identity.token, now_wall) orelse return .reject;
            return if (std.ascii.eqlIgnoreCase(best.nick, new_nick)) .{ .bind = identity.token } else .reject;
        }
        if (self.hasRetainedSessionReplicaNickAuthority(old_nick) or
            self.hasRetainedSessionReplicaNickAuthority(new_nick)) return .reject;
        return .legacy;
    }

    fn sessionTokenNickAuthorizer(self: *LinuxServer) s2s_link.S2sLink.SessionTokenNickAuthorizer {
        return .{ .ctx = self, .authorize_fn = authorizeSessionTokenNick };
    }

    fn announceNickChange(
        self: *LinuxServer,
        old_nick: []const u8,
        new_nick: []const u8,
        ident: s2s_link.S2sLink.MemberIdentity,
        v2_authority_ready: bool,
    ) void {
        const hlc = self.nextMeshHlc();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    if (link.supportsSessionReplicaV2() and !v2_authority_ready) continue;
                    link.sendNickChange(old_nick, new_nick, ident, hlc) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    if (link.supportsSessionReplicaV2() and !v2_authority_ready) continue;
                    link.sendNickChange(old_nick, new_nick, ident, hlc) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    /// Burst every local channel's current topic to ONE freshly-established peer
    /// so a relink converges immediately instead of waiting for the next TOPIC.
    fn sendTopicBurstTo(self: *LinuxServer, conn: *ConnState) bool {
        if (!conn.isActiveMeshPeer()) return false;
        var cit = self.world.channelIterator();
        while (cit.next()) |cv| {
            const info = self.world.topicInfo(cv.name) orelse continue;
            if (info.text.len == 0) continue;
            const hlc = self.nextMeshHlc();
            if (conn.s2s_secured) |link| {
                link.sendTopic(cv.name, info.text, info.setter, info.set_at, hlc, true) catch return false;
            } else if (conn.s2s) |link| {
                link.sendTopic(cv.name, info.text, info.setter, info.set_at, hlc, true) catch return false;
            }
        }
        return true;
    }

    fn flushS2sOutbound(self: *LinuxServer, conn: *ConnState, out: []const u8) !void {
        if (out.len == 0) return;
        try appendToConn(conn, out);
        try self.armSendIfNeeded(conn);
    }

    fn flushS2sOutboundTo(self: *LinuxServer, id: client_model.ClientId, out: []const u8) !void {
        if (out.len == 0) return;
        // The S2S link state is serialized by the world write lock; the actual
        // socket send buffer remains owned by `id.shard` via enqueueDelivery.
        try self.enqueueDelivery(id, out);
    }

    /// Preserve secured-link ciphertext under ordinary peer backpressure. S2S
    /// sockets are reactor-owned; a foreign shard must never chunk a shared AEAD
    /// stream through the generic delivery fabric because a partial mailbox
    /// enqueue cannot be retried byte-for-byte. Wake the owner and leave the
    /// complete records in `link`. On the owner, use the same whole-record SendQ
    /// pager as replay/burst release, which neither poisons nor clears on a full
    /// but otherwise healthy peer queue.
    fn flushSecuredS2sOutboundTo(
        self: *LinuxServer,
        id: client_model.ClientId,
        link: *secured_s2s_link.SecuredLink,
    ) bool {
        // Collision losers retain their final flight only. Validate the exact
        // connection even for an empty link buffer before callers encode new
        // application records on a route that is already retiring.
        const conn = self.connFor(id) orelse return false;
        if (!conn.ownsActiveMeshLink(link)) return false;
        if (link.outbound().len == 0) return true;
        if (id.shard != self.rx().shard_id) {
            self.wakeShard(id.shard);
            return false;
        }
        return self.flushMeshBurstStage(conn);
    }

    const NamesRosterEntry = struct {
        prefixes: chanmode.PrefixList,
        nick: []const u8,
        user: []const u8,
        host: []const u8,

        fn asMember(self: *const NamesRosterEntry) names_reply.Member {
            return .{
                .prefixes = self.prefixes.asSlice(),
                .nick = self.nick,
                .user = self.user,
                .host = self.host,
            };
        }
    };

    const NamesNickContext = struct {
        pub fn hash(_: @This(), nick: []const u8) u64 {
            var hasher = std.hash.Wyhash.init(0x4e41_4d45_535f_4e49);
            for (nick) |ch| {
                const folded = [1]u8{std.ascii.toLower(ch)};
                hasher.update(&folded);
            }
            return hasher.final();
        }

        pub fn eql(_: @This(), a: []const u8, b: []const u8) bool {
            return std.ascii.eqlIgnoreCase(a, b);
        }
    };

    const NamesNickSet = std.HashMapUnmanaged(
        []const u8,
        void,
        NamesNickContext,
        std.hash_map.default_max_load_percentage,
    );

    /// Add one representable logical IRC identity to a dynamically bounded NAMES
    /// roster. The entry limit is derived from this request's remaining plaintext
    /// output budget: every accepted member consumes at least one token byte and
    /// one separator byte, so a larger unique roster could not possibly complete
    /// before the SendQ/capture ceiling anyway. Any invalid identity aborts the
    /// still-private roster build: silently skipping an admitted mesh row and
    /// then emitting 366 would falsely certify a complete channel image.
    fn appendNamesRosterEntry(
        self: *LinuxServer,
        entries: *std.ArrayListUnmanaged(NamesRosterEntry),
        seen: *NamesNickSet,
        max_entries: usize,
        nick: []const u8,
        user: []const u8,
        host: []const u8,
        modes: world_model.MemberModes,
        is_override_oper: bool,
    ) ServerError!bool {
        var prefixes = modes.allPrefixes();
        if (is_override_oper) prefixes.prependOper();
        const candidate = NamesRosterEntry{
            .prefixes = prefixes,
            .nick = nick,
            .user = user,
            .host = host,
        };
        names_reply.validateMember(candidate.asMember()) catch return error.InvalidNamesRoster;
        if (seen.contains(nick)) return false;
        if (entries.items.len >= max_entries) return error.OutputTooSmall;
        try entries.ensureUnusedCapacity(self.allocator, 1);
        const seen_result = try seen.getOrPut(self.allocator, nick);
        if (seen_result.found_existing) return false;
        entries.appendAssumeCapacity(candidate);
        return true;
    }

    /// Append a peer's remote channel members into the NAMES roster (deduped,
    /// auditorium-filtered). `members` is a borrowed roster from either link
    /// type. Each member renders with its PROPAGATED real username + visible
    /// (cloaked) host; only a roster entry whose origin never supplied identity
    /// falls back to the `mesh@<server>` placeholder.
    fn addRemoteMembers(
        self: *LinuxServer,
        entries: *std.ArrayListUnmanaged(NamesRosterEntry),
        seen: *NamesNickSet,
        max_entries: usize,
        is_auditorium: bool,
        viewer_rank: auditorium.Rank,
        remote_name: []const u8,
        members: anytype,
    ) ServerError!void {
        for (members) |rm| {
            const modes = world_model.MemberModes{ .bits = @as(u8, rm.status) };
            if (is_auditorium and !auditorium.visibleTo(viewer_rank, auditoriumRank(modes))) continue;
            _ = try self.appendNamesRosterEntry(
                entries,
                seen,
                max_entries,
                rm.nick,
                if (rm.username.len != 0) rm.username else world_projection.remote_user_placeholder,
                if (rm.host.len != 0) rm.host else if (remote_name.len != 0) remote_name else default_host,
                modes,
                self.isOverrideOper(rm.nick) or self.remoteHasOverridePrefix(rm.account),
            );
        }
    }

    /// Total members of `channel` across the WHOLE mesh: the local member count plus
    /// every distinct remote member an established S2S peer announced for it, deduped
    /// by nick against locals and across links — the same membership set the NAMES
    /// world-projection merges (auditorium `+x` may hide some from NAMES *visibility*,
    /// but the channel's true population is what a LIST count should report). LIST
    /// otherwise reported only the LOCAL count, so a channel with members on a peer
    /// node was undercounted (and a channel whose locals all live on a peer could
    /// read as smaller than its own NAMES). Iterates ALL reactors because S2S links
    /// live only on reactor 0; safe because `onCompletion` holds `world.lockWrite`
    /// around the whole completion (the same guarantee `sendNames` relies on).
    fn globalMemberCount(self: *LinuxServer, channel: []const u8, local_count: usize) usize {
        var total = local_count;
        // Bounded scratch of remote nicks already counted (dedup across links and
        // against locals); beyond the cap the count saturates rather than growing the
        // stack frame. 256 keeps this ~4 KiB on the live completion stack — realistic
        // per-channel sizes are far smaller, and the saturation handles the rest.
        const max_seen = 256;
        var seen_buf: [max_seen][]const u8 = undefined;
        var seen: usize = 0;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const members = blk: {
                    if (slot.value.s2s_secured) |link| {
                        if (link.established()) break :blk link.channelMembers(channel);
                    } else if (slot.value.s2s) |link| {
                        if (link.established()) break :blk link.channelMembers(channel);
                    }
                    continue;
                };
                for (members) |rm| {
                    if (self.world.isMemberByNick(channel, rm.nick)) continue; // echo of a local member
                    var dup = false;
                    var i: usize = 0;
                    while (i < seen) : (i += 1) {
                        if (std.ascii.eqlIgnoreCase(seen_buf[i], rm.nick)) {
                            dup = true;
                            break;
                        }
                    }
                    if (dup) continue;
                    if (seen < max_seen) {
                        seen_buf[seen] = rm.nick;
                        seen += 1;
                    }
                    total += 1;
                }
            }
        }
        return total;
    }

    /// Newest topic a remote peer has published for a channel that may have no
    /// local world row. The text borrows the peer route table for this turn.
    fn remotePublishedTopic(self: *LinuxServer, channel: []const u8) ?struct { text: []const u8, set_at: i64 } {
        var found = false;
        var best_hlc: u64 = 0;
        var best_text: []const u8 = "";
        var best_set: i64 = 0;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const view: ?s2s_peer_mod.TopicView = if (slot.value.s2s_secured) |link| blk: {
                    if (!link.established()) break :blk null;
                    break :blk link.channelTopic(channel);
                } else if (slot.value.s2s) |link| blk: {
                    if (!link.established()) break :blk null;
                    break :blk link.channelTopic(channel);
                } else null;
                if (view) |v| {
                    if (!found or v.hlc >= best_hlc) {
                        found = true;
                        best_hlc = v.hlc;
                        best_text = v.topic;
                        best_set = if (v.present) v.set_at else 0;
                    }
                }
            }
        }
        if (!found) return null;
        return .{ .text = best_text, .set_at = best_set };
    }

    /// Whether a channel that has NO local world record should still be hidden
    /// from LIST/LISTX because the mesh gossiped a `+s` (secret) aggregate for
    /// it. Hidden (`+h`)/private (`+p`) state materializes a local world record
    /// via `ensureRemoteListChannel` on the CHANNEL_MODE_STATE burst, so a
    /// channel reaching this path can only be gated by the secret bit carried in
    /// the separate CHANNEL_MODE_FLAGS aggregate (which never materializes a
    /// world record). Any established peer asserting secret wins (fail-closed).
    fn remoteChannelSecret(self: *LinuxServer, channel: []const u8) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const flags: ?u16 = blk: {
                    if (slot.value.s2s_secured) |link| {
                        if (link.established()) break :blk if (link.channelModeFlags(channel)) |f| f.flags else null;
                    } else if (slot.value.s2s) |link| {
                        if (link.established()) break :blk if (link.channelModeFlags(channel)) |f| f.flags else null;
                    }
                    break :blk null;
                };
                if (flags) |f| {
                    if ((f & channel_secret_flag_bit) != 0) return true;
                }
            }
        }
        return false;
    }

    /// Collect the mesh-wide set of channel names that exist ONLY on remote peers
    /// — i.e. every channel with a live remote roster on an established S2S link
    /// (secured or plaintext) that has no local world record — deduplicated
    /// case-insensitively across links. Internal routing pseudo-channels (the
    /// presence roster, and anything not a real channel name) are excluded. The
    /// returned name slices are borrowed from peer route tables and stay valid
    /// for the calling handler turn; the OUTER slice is owned by the caller and
    /// must be freed with `self.allocator`.
    fn remoteOnlyChannelNames(self: *LinuxServer) std.mem.Allocator.Error![]const []const u8 {
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        errdefer names.deinit(self.allocator);
        var seen = CiNameSet.init(self.allocator);
        defer seen.deinit();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    if (link.channelNames()) |it_| {
                        var it = it_;
                        try self.collectRemoteChannelNames(&it, &names, &seen);
                    }
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    var it = link.channelNames();
                    try self.collectRemoteChannelNames(&it, &names, &seen);
                }
            }
        }
        return names.toOwnedSlice(self.allocator);
    }

    /// Drain one peer's channel-name iterator into the deduped union, skipping
    /// non-channel routing names and any channel already present in the local
    /// world (those are emitted from the world pass instead).
    fn collectRemoteChannelNames(
        self: *LinuxServer,
        it: anytype,
        names: *std.ArrayListUnmanaged([]const u8),
        seen: *CiNameSet,
    ) std.mem.Allocator.Error!void {
        while (it.next()) |name| {
            if (!world_model.isChannelName(name)) continue; // skips ~presence~ etc.
            if (self.world.channelExists(name)) continue; // handled by the world pass
            const gop = try seen.getOrPut(name);
            if (gop.found_existing) continue;
            try names.append(self.allocator, name);
        }
    }

    fn broadcastJoin(self: *LinuxServer, channel: []const u8, conn: *ConnState) !void {
        var prefix_buf: [256]u8 = undefined;
        const prefix = try clientPrefix(conn, &prefix_buf);
        const account = conn.session.account() orelse "*";

        // draft/event-playback: record the join as a JOIN event (`:joiner JOIN
        // #chan`) in channel history for event-playback replay.
        self.recordHistoryEvent(channel, conn, "JOIN", channel);

        var plain_buf: [default_reply_bytes]u8 = undefined;
        const plain = try formatMessage(&plain_buf, prefix, "JOIN", &.{channel}, null);

        var ext_buf: [default_reply_bytes]u8 = undefined;
        const ext = try formatMessage(&ext_buf, prefix, "JOIN", &.{ channel, account }, conn.session.realname());

        var tag_buf: [48]u8 = undefined;
        const tag = serverTimeTag(&tag_buf);

        // +x AUDITORIUM: a regular member's JOIN is only relayed to ops/voiced
        // (and the joiner itself); ops/voiced joins are relayed to everyone.
        const is_auditorium = self.world.channelHasExtFlag(channel, .auditorium);
        const joiner_wid = self.world.findNick(conn.session.displayName());
        const joiner_rank = if (joiner_wid) |jw|
            auditoriumRank(self.world.memberModes(channel, jw) orelse world_model.MemberModes.empty())
        else
            auditorium.Rank.regular;
        const relay_all = !is_auditorium or auditorium.shouldRelayJoinPart(joiner_rank);

        var members = self.world.memberIterator(channel) orelse return error.NoSuchChannel;
        self.beginWakeBatch();
        defer self.endWakeBatch();
        while (members.next()) |member| {
            if (!relay_all) {
                const is_self = if (joiner_wid) |jw| member.*.eql(jw) else false;
                const mrank = auditoriumRank(self.world.memberModes(channel, member.*) orelse world_model.MemberModes.empty());
                if (!is_self and !auditorium.shouldRelayJoinPart(mrank)) continue;
            }
            const mid = clientIdFromWorld(member.*);
            const mconn = self.connFor(mid) orelse continue;
            const body = if (mconn.session.hasCap(.extended_join)) ext else plain;
            self.deliverTimed(mid, tag, body) catch continue;
        }
        // A joining network operator carries the derived `*` prefix, which the
        // bare JOIN above cannot convey. Announce the synthetic +Y so existing
        // members' nicklists show the star immediately, not only on next NAMES.
        if (conn.session.hasPriv(.oper_override)) {
            self.emitOperPrefixMode(channel, conn.session.displayName(), true);
        }
    }

    fn serverAccessReason(entry: ircx_saccess.Entry, fallback: []const u8) []const u8 {
        return entry.reason orelse fallback;
    }

    fn enforceServerAccess(self: *LinuxServer, conn: *ConnState) !bool {
        var mask_buf: [256]u8 = undefined;
        const mask = clientPrefix(conn, &mask_buf) catch return false;
        // IRCX processing order: GRANT, then DENY/GAG (GRANT overrides DENY).
        // A server-level GRANT is a whitelist exemption: a connecting client
        // whose mask matches a GRANT entry bypasses the SACCESS deny/gag
        // firewall entirely. Matches the IRCX ACCESS server-side firewall semantics.
        if (self.saccess.matchHostmask(.grant, mask) != null) return false;
        if (self.saccess.matchHostmask(.deny, mask)) |entry| {
            var buf: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&buf, "ERROR :{s}\r\n", .{serverAccessReason(entry, "Access denied by SACCESS")}) catch "ERROR :Access denied by SACCESS\r\n";
            try appendToConn(conn, line);
            conn.closing = true;
            return true;
        }
        if (self.saccess.matchHostmask(.gag, mask) != null) conn.gagged = true;
        return false;
    }

    fn accessEntryAllowsJoin(entry: ircx_access_store.EntryView) bool {
        return entry.level != .deny;
    }

    fn ircxAccessJoinEntry(self: *LinuxServer, channel: []const u8, conn: *ConnState) ?ircx_access_store.EntryView {
        var mask_buf: [256]u8 = undefined;
        const mask = clientPrefix(conn, &mask_buf) catch return null;
        return self.access.matchHostmask(channel, mask) catch null;
    }

    /// Registered-channel AKICK join gate. A non-oper joiner whose mask (or
    /// account) matches an active AKICK entry is refused entry with 474. This is
    /// consulted on BOTH join paths: from `joinDenied` for a live channel, and
    /// from the create path in `joinOne` — a registered channel's AKICK must bite
    /// even when no live channel exists yet (otherwise the masked user could
    /// re-create the empty channel and walk straight in). Opers bypass.
    /// `precomputed_mask` reuses the caller's `nick!user@host` when available.
    fn akickDenied(
        self: *LinuxServer,
        conn: *ConnState,
        channel: []const u8,
        precomputed_mask: ?[]const u8,
        quiet: bool,
    ) !bool {
        if (self.chan_akick.count(channel) == 0) return false;
        var mask_buf: [256]u8 = undefined;
        const mask = precomputed_mask orelse (clientPrefix(conn, &mask_buf) catch return false);
        if (self.chan_akick.matchOnJoin(channel, mask, conn.session.account(), self.nowMs())) |ak| {
            if (conn.session.isOper()) {
                if (overrideActive(conn)) self.auditOverrideUse(conn, "JOIN", channel, "matched channel AKICK");
                return false;
            }
            if (!quiet) try queueNumeric(conn, .ERR_BANNEDFROMCHAN, &.{channel}, ak.reason);
            return true;
        }
        return false;
    }

    fn kickCurrentAkickMatches(self: *LinuxServer, channel: []const u8, added_mask: []const u8, reason: []const u8) !void {
        if (!self.world.channelExists(channel)) return;
        const Victim = struct {
            id: client_model.ClientId,
            conn: *ConnState,
            projection: ?sessions_mod.LocalChannelProjectionWork = null,
        };
        var victims: std.ArrayListUnmanaged(Victim) = .empty;
        defer victims.deinit(self.allocator);

        const now = self.nowMs();
        var members = self.world.memberIterator(channel) orelse return;
        while (members.next()) |member| {
            const wid = member.*;
            const cid = clientIdFromWorld(wid);
            const c = self.connFor(cid) orelse continue;
            if (c.session.isOper()) continue;
            var mask_buf: [256]u8 = undefined;
            const hostmask = clientPrefix(c, &mask_buf) catch continue;
            const hit = self.chan_akick.matchOnJoin(channel, hostmask, c.session.account(), now) orelse continue;
            if (!std.ascii.eqlIgnoreCase(hit.mask, added_mask)) continue;
            var duplicate_group = false;
            for (victims.items) |victim| {
                if (self.clientsShareExactToken(victim.id, victim.conn, cid, c)) {
                    duplicate_group = true;
                    break;
                }
            }
            if (!duplicate_group) try victims.append(self.allocator, .{ .id = cid, .conn = c });
        }

        const kick_reason = if (reason.len == 0) "Auto-kicked" else reason;
        var first_error: ?anyerror = null;
        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        for (victims.items) |*victim| {
            const c = victim.conn;
            const nick = c.session.displayName();
            logical_ids.clearRetainingCapacity();
            self.collectAttachedExactTokenClients(victim.id, c, &logical_ids) catch |err| {
                if (first_error == null) first_error = err;
                continue;
            };
            victim.projection = self.armLocalChannelProjectionForClient(
                victim.id,
                c,
                channel,
                false,
                0,
            ) catch |err| {
                if (first_error == null) first_error = err;
                continue;
            };
            const nick_survives = self.renderedNickSurvivesTokenRemoval(victim.id, c, channel, nick);
            var msg_buf: [default_reply_bytes]u8 = undefined;
            if (formatMessage(&msg_buf, self.serverName(), "KICK", &.{ channel, nick }, kick_reason)) |msg| {
                if (nick_survives) {
                    for (logical_ids.items) |logical_id| {
                        if (!self.world.isMember(channel, worldIdFromClient(logical_id))) continue;
                        self.deliverTimed(logical_id, "", msg) catch {};
                    }
                } else {
                    self.broadcastChannel(channel, msg, null) catch {};
                }
            } else |_| {}
            self.completeLocalChannelRemoval(victim.id, c, channel, nick, victim.projection, !nick_survives);
        }
        if (first_error) |err| return err;
    }

    /// Channel-mode gate for JOIN. Returns true (and emits the numeric) when the
    /// join must be refused: +b ban (474), +i invite-only (473), +k bad key
    /// (475), +l full (471). A pending INVITE bypasses ban and invite-only.
    fn joinDenied(
        self: *LinuxServer,
        conn: *ConnState,
        id: client_model.ClientId,
        channel: []const u8,
        supplied_key: ?[]const u8,
        quiet: bool,
    ) !bool {
        const wid = worldIdFromClient(id);
        const invited = self.world.hasInvite(channel, wid);
        const active_override = overrideActive(conn);

        // Warden quarantine (network silence / SHUN): a restricted client may not
        // join any channel. Opers are never restricted.
        if (conn.session.isRestricted()) {
            if (!quiet) try queueNumeric(conn, .ERR_BANNEDFROMCHAN, &.{channel}, "You are quarantined and cannot join channels");
            return true;
        }

        // +S TLS-only: join permitted only over a TLS session (implicit-TLS fact;
        // no STARTTLS). Server opers bypass.
        if (self.world.channelHasFlag(channel, .tls_only) and !conn.is_tls and !conn.session.isOper()) {
            if (!quiet) try queueNumeric(conn, .ERR_SECUREONLYCHAN, &.{channel}, "Cannot join channel (+S) - TLS required");
            return true;
        }

        // +O oper-only / +A admin-only: server operator gates, checked with the
        // other hard join denials and bypassed by no channel status.
        if (self.world.channelHasFlag(channel, .oper_only) and !conn.session.isOper()) {
            if (!quiet) try queueNumeric(conn, .ERR_OPERONLYCHAN, &.{channel}, "Cannot join channel (+O) - IRC operator required");
            return true;
        }
        if (self.world.channelHasFlag(channel, .admin_only) and !conn.session.isAdmin()) {
            if (active_override) {
                self.auditOverrideUse(conn, "JOIN", channel, "bypassed +A admin-only");
            } else {
                if (!quiet) try queueNumeric(conn, .ERR_OPERONLYCHAN, &.{channel}, "Cannot join channel (+A) - server administrator required");
                return true;
            }
        }

        // +a AUTHONLY (IRCX): only authenticated accounts may join, regardless of
        // invite. Enforced before all other gates.
        if (self.world.channelHasExtFlag(channel, .authonly) and conn.session.account() == null) {
            if (active_override) {
                self.auditOverrideUse(conn, "JOIN", channel, "bypassed +a authonly");
            } else {
                if (!quiet) try queueNumeric(conn, .ERR_NEEDREGGEDNICK, &.{channel}, "Cannot join channel (+a) - you must be authenticated");
                return true;
            }
        }

        var mask_buf: [256]u8 = undefined;
        const mask = try clientPrefix(conn, &mask_buf);
        // Extended-ban context (account/realname/channels + host glob fallthrough).
        var chan_buf: [64][]const u8 = undefined;
        const ban_ctx = banContextFor(self, conn, wid, mask, &chan_buf);
        // Registered-channel AKICK: a mask/account match is auto-denied entry
        // (services-style; overrides an invite). Opers bypass.
        if (try self.akickDenied(conn, channel, mask, quiet)) return true;
        // IRCX ACCESS: the effective matching entry is consulted before local
        // channel list modes. Positive entries override channel-local denials
        // (ban/invite/key/full in joinOne) and later auto-apply status; DENY
        // remains a channel-local ban when no positive entry outranks it.
        const access_entry = self.access.matchHostmask(channel, mask) catch null;
        const access_override = if (access_entry) |entry| accessEntryAllowsJoin(entry) else false;
        if (access_entry) |entry| {
            if (entry.level == .deny) {
                if (active_override) {
                    self.auditOverrideUse(conn, "JOIN", channel, "bypassed ACCESS DENY");
                } else {
                    if (!quiet) try queueNumeric(conn, .ERR_BANNEDFROMCHAN, &.{channel}, "Cannot join channel (ACCESS DENY)");
                    return true;
                }
            }
        }
        // +b ban (isBannedCtx honors +e exceptions and extended bans) blocks the
        // join even when the user holds a pending invite.
        if (!access_override and self.world.isBannedCtx(channel, ban_ctx)) {
            if (active_override) {
                self.auditOverrideUse(conn, "JOIN", channel, "bypassed +b ban");
            } else {
                if (!quiet) try queueNumeric(conn, .ERR_BANNEDFROMCHAN, &.{channel}, "Cannot join channel (+b)");
                return true;
            }
        }
        // +i blocks unless the user holds an invite OR matches a +I invex mask.
        if (!access_override and !invited and self.world.channelHasFlag(channel, .invite_only) and !self.world.isInvexedCtx(channel, ban_ctx)) {
            if (active_override) {
                self.auditOverrideUse(conn, "JOIN", channel, "bypassed +i invite-only");
            } else {
                if (!quiet) try queueNumeric(conn, .ERR_INVITEONLYCHAN, &.{channel}, "Cannot join channel (+i)");
                return true;
            }
        }
        if (self.world.channelKey(channel)) |key| {
            if (!access_override and (supplied_key == null or !std.mem.eql(u8, supplied_key.?, key))) {
                if (active_override) {
                    self.auditOverrideUse(conn, "JOIN", channel, "bypassed +k key");
                } else {
                    if (!quiet) try queueNumeric(conn, .ERR_BADCHANNELKEY, &.{channel}, "Cannot join channel (+k)");
                    return true;
                }
            }
        }
        // +l (full) is handled separately in joinOne so it can fall back to
        // the IRCX +d auto-clone path; all the gates above are hard denials.
        return false;
    }

    /// True when `channel` has a +l member limit and is at or over it.
    fn isChannelFull(self: *LinuxServer, channel: []const u8) bool {
        const limit = self.world.channelLimit(channel) orelse return false;
        return self.world.memberCount(channel) >= limit;
    }

    const CloneTarget = struct { name: []const u8, create: bool };

    /// Select a +d clone without mutating World. Fresh clone materialization is
    /// delayed until the exact-token JOIN journal has accepted the intent.
    fn selectCloneTarget(self: *LinuxServer, parent: []const u8, buf: []u8) ?CloneTarget {
        var n: u32 = 1;
        while (n < 1000) : (n += 1) {
            const name = std.fmt.bufPrint(buf, "{s}{d}", .{ parent, n }) catch return null;
            if (!self.world.channelExists(name)) return .{ .name = name, .create = true };
            // An existing clone with room takes the join; a full one is skipped.
            if (self.world.channelHasExtFlag(name, .clone) and !self.isChannelFull(name)) {
                return .{ .name = name, .create = false };
            }
        }
        return null;
    }

    pub fn handleJoin(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"JOIN"}, "Not enough parameters");
            return;
        }
        // `JOIN 0` (RFC 2812 §3.2.1): the special channel name "0" is a request to
        // PART from ALL channels the client is currently in. It is NOT a real
        // channel, so handle it before the comma-split / channel-name path.
        if (std.mem.eql(u8, parsed.paramSlice()[0], "0")) {
            try self.partAllChannels(id, conn);
            return;
        }
        // `JOIN #a,#b key1,key2`: channels and keys are positional comma lists.
        var channels = std.mem.splitScalar(u8, parsed.paramSlice()[0], ',');
        var keys = std.mem.splitScalar(u8, if (parsed.param_count >= 2) parsed.paramSlice()[1] else "", ',');
        while (channels.next()) |channel| {
            if (channel.len == 0) continue;
            const key_part = keys.next() orelse "";
            const key: ?[]const u8 = if (key_part.len != 0) key_part else null;
            try self.joinOne(id, conn, channel, key, 0);
        }
    }

    /// `JOIN 0` — PART the client from every channel it is in. Snapshots the
    /// membership list first (partOne mutates the world's per-client channel set,
    /// so iterating it live would be unsound) and parts each with no reason.
    fn partAllChannels(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) !void {
        var chan_names: [256][]const u8 = undefined;
        const nchan = self.world.channelsOf(worldIdFromClient(id), &chan_names);
        if (nchan == 0) return;
        // channelsOf returns slices borrowed from world storage that partOne may
        // free as a channel empties; copy each name into a heap snapshot so every
        // PART operates on stable bytes. Heap (not a large stack buffer) keeps this
        // frame small since it sits on the deep JOIN/PART dispatch chain.
        var total: usize = 0;
        for (chan_names[0..nchan]) |cn| total += cn.len;
        const backing = try self.allocator.alloc(u8, total);
        defer self.allocator.free(backing);
        const copies = try self.allocator.alloc([]const u8, nchan);
        defer self.allocator.free(copies);
        var off: usize = 0;
        for (chan_names[0..nchan], 0..) |cn, i| {
            @memcpy(backing[off .. off + cn.len], cn);
            copies[i] = backing[off .. off + cn.len];
            off += cn.len;
        }
        for (copies) |cn| {
            try self.partOne(id, conn, cn, null);
        }
    }

    /// If `channel` has a usable +f forward target (one hop only, gated by
    /// `depth`), emit RPL_LINKCHANNEL (470), copy the target into `out`, and
    /// return it for the caller to JOIN. Returns null when no usable forward
    /// exists. Does NOT call joinOne itself (keeps joinOne's error set clean).
    fn forwardTarget(self: *LinuxServer, conn: *ConnState, channel: []const u8, depth: u8, out: []u8) !?[]const u8 {
        if (depth != 0) return null;
        // User mode +Q (no-forward): a user who opted out is never redirected to a
        // +f forward target — the original blocked-JOIN deny numeric fires instead.
        if (conn.session.hasUmode(.no_forward)) return null;
        const fwd = self.world.forwardOf(channel) orelse return null;
        if (std.ascii.eqlIgnoreCase(fwd, channel)) return null;
        if (!world_model.isChannelName(fwd)) return null;
        // +D disforward (MODE_DISFORWARD): a channel that refuses to be a
        // forward destination is skipped — the original blocked-JOIN deny fires.
        if (self.world.channelHasExtFlag(fwd, .disforward)) return null;
        if (fwd.len > out.len) return null;
        @memcpy(out[0..fwd.len], fwd);
        const ftarget = out[0..fwd.len];
        var lb: [256]u8 = undefined;
        const line = std.fmt.bufPrint(&lb, ":{s} 470 {s} {s} {s} :Forwarding to another channel\r\n", .{ self.serverName(), conn.session.displayName(), channel, ftarget }) catch return null;
        try appendToConn(conn, line);
        return ftarget;
    }

    fn joinOne(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, key: ?[]const u8, depth: u8) !void {
        return self.joinOneWith(id, conn, channel, key, depth, false, null);
    }

    /// Join implementation with one internal-only exception for IRCX CREATE's
    /// cloned-channel path. CREATE pre-seats its founder to bypass inherited
    /// +i/+k gates; `prejoined_create` preserves that bypass while still treating
    /// the seat as a new logical JOIN for rendering, persistence, and mesh sync.
    fn joinOneWith(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        key: ?[]const u8,
        depth: u8,
        prejoined_create: bool,
        prearmed_projection: ?sessions_mod.LocalChannelProjectionWork,
    ) !void {
        // Reject malformed or over-long channel names (CHANNELLEN, advertised in
        // ISUPPORT and enforced here — the name validator checks only the prefix).
        if (!world_model.isChannelName(channel) or channel.len > self.config.channellen) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        if (self.saccess.matchChannel(channel)) |entry| {
            try queueNumeric(conn, .ERR_UNAVAILRESOURCE, &.{channel}, serverAccessReason(entry, "Channel blocked by SACCESS"));
            return;
        }
        const wid = worldIdFromClient(id);
        // Channel RESV applies before the existing-channel mode gates. A
        // reserved name must be refused when its first member would create it
        // as well as when a later client tries to join it.
        const active_override = overrideActive(conn);
        if (!self.world.isMember(channel, wid)) {
            if (self.chan_resv.match(channel, self.nowMs())) |resv| {
                if (!conn.session.isOper()) {
                    try queueNumeric(conn, .ERR_UNAVAILRESOURCE, &.{channel}, resv.reason);
                    return;
                }
                if (active_override) self.auditOverrideUse(conn, "JOIN", channel, "bypassed channel RESV");
            }
        }

        // Enforce channel modes only when joining an EXISTING channel as a new
        // member. Creating a fresh channel (founder path) bypasses channel-mode gates.
        // CHANLIMIT: cap how many channels a non-oper may be in. Only a NEW join
        // counts; re-JOIN of a channel already joined is a no-op and exempt. The
        // connection class may override the global limit (`max_channels`, 0 =
        // inherit `[limits].chanlimit`).
        const chan_cap = if (conn.class_policy.max_channels != 0) conn.class_policy.max_channels else self.config.chanlimit;
        if (!conn.session.isOper() and !self.world.isMember(channel, wid) and
            self.world.channelCountOf(wid) >= chan_cap)
        {
            try queueNumeric(conn, .ERR_TOOMANYCHANNELS, &.{channel}, "You have joined too many channels");
            return;
        }
        var clone_buf: [160]u8 = undefined;
        var fwd_buf: [80]u8 = undefined;
        var join_target = channel;
        var clone_parent: ?[]const u8 = null;
        if (self.world.channelExists(channel) and !self.world.isMember(channel, wid)) {
            const invited = self.world.hasInvite(channel, wid);
            // +f forward: when refused, redirect to the forward target (one hop).
            // Suppress the deny numeric while a forward is a candidate, then either
            // redirect quietly or, if the forward is unusable, emit the real deny.
            const fwd_quiet = depth == 0 and self.world.forwardOf(channel) != null;
            if (try self.joinDenied(conn, id, channel, key, fwd_quiet)) {
                if (fwd_quiet) {
                    if (try self.forwardTarget(conn, channel, depth, &fwd_buf)) |target| {
                        return self.joinOneWith(id, conn, target, null, depth + 1, false, null);
                    }
                    _ = try self.joinDenied(conn, id, channel, key, false);
                }
                return;
            }
            // Join throttle: deny if the window is full. The effective rate is the
            // channel's explicit +j, else the network-wide raid-guard default
            // (`raid_joins`/`raid_secs`, 0 = off). Opers and invited users bypass.
            // Checked after the hard gates so a denied join consumes no slot. The
            // first denial in a window fires a one-shot raid alert on the Spine.
            if (!conn.session.isOper() and !invited) {
                switch (self.world.throttleAdmit(channel, self.nowMs(), self.config.raid_joins, self.config.raid_secs)) {
                    .admitted => {},
                    .throttled => {
                        try queueNumeric(conn, .ERR_THROTTLE, &.{channel}, "Cannot join channel (+j) - join rate exceeded, try again shortly");
                        return;
                    },
                    .throttled_alert => {
                        self.raidAlert(channel);
                        try queueNumeric(conn, .ERR_THROTTLE, &.{channel}, "Cannot join channel (+j) - join rate exceeded, try again shortly");
                        return;
                    },
                }
            }
            // +l full: IRCX +d cloneable channels redirect the join to a clone;
            // otherwise it is a hard 471.
            const access_override = if (self.ircxAccessJoinEntry(channel, conn)) |entry| accessEntryAllowsJoin(entry) else false;
            if (!access_override and !invited and self.isChannelFull(channel)) {
                if (active_override) {
                    self.auditOverrideUse(conn, "JOIN", channel, "bypassed +l limit");
                } else if (self.world.channelHasExtFlag(channel, .cloneable)) {
                    const clone_target = self.selectCloneTarget(channel, &clone_buf) orelse {
                        try queueNumeric(conn, .ERR_CHANNELISFULL, &.{channel}, "Cannot join channel (+l)");
                        return;
                    };
                    join_target = clone_target.name;
                    if (clone_target.create) clone_parent = channel;
                } else {
                    // +l full: redirect to +f forward target if set, else hard 471.
                    if (try self.forwardTarget(conn, channel, depth, &fwd_buf)) |target| {
                        return self.joinOneWith(id, conn, target, null, depth + 1, false, null);
                    }
                    try queueNumeric(conn, .ERR_CHANNELISFULL, &.{channel}, "Cannot join channel (+l)");
                    return;
                }
            }
        }

        // Founder creating a brand-new channel: purge any orphaned IRCX state from
        // a prior same-named incarnation so stale ACCESS DENY/GRANT entries or
        // secret PROP keys can never bleed into the new channel. (A clone target is
        // already set up by cloneChannel, so it is never "creating" here.)
        const creating = !self.world.channelExists(join_target) and clone_parent == null;
        if (creating) {
            // Registered-channel AKICK must bite even when re-creating an empty
            // registered channel: joinDenied's gate only runs for live channels,
            // so a masked user could otherwise re-create the channel and enter.
            if (try self.akickDenied(conn, join_target, null, false)) return;
        }

        // Arm the exact PRE-state after every denial and before the first World
        // mutation. If the JOIN transaction fails before finalization, retrying
        // this image restores the old membership instead of fabricating a plain
        // member. Replacement with post-automode state is allocation-free.
        const old_modes = self.world.memberModes(join_target, wid);
        var reversible_arm: ?ReversibleLocalChannelProjectionArm = null;
        var local_projection: ?sessions_mod.LocalChannelProjectionWork = if (prearmed_projection) |pending|
            pending
        else blk: {
            const armed = self.armReversibleLocalChannelProjectionForClient(
                id,
                conn,
                join_target,
                old_modes != null,
                if (old_modes) |modes| modes.bits else 0,
            ) catch {
                try self.failReply(conn, "JOIN", "TEMPORARILY_UNAVAILABLE", "Session channel state is busy; retry JOIN");
                return;
            };
            reversible_arm = armed;
            break :blk armed.work;
        };

        if (clone_parent) |parent| {
            var prepared_clone = (self.world.prepareCloneTemplate(parent, join_target) catch |err| {
                if (reversible_arm) |armed| self.rollbackReversibleLocalChannelProjection(armed);
                return err;
            }) orelse {
                if (reversible_arm) |armed| self.rollbackReversibleLocalChannelProjection(armed);
                try queueNumeric(conn, .ERR_CHANNELEXIST, &.{join_target}, "Channel already exists");
                return;
            };
            defer prepared_clone.abort();
            prepared_clone.commitSeated(wid, world_model.MemberModes.fromModes(&.{.founder})) catch {
                if (reversible_arm) |armed| self.rollbackReversibleLocalChannelProjection(armed);
                try self.failReply(conn, "JOIN", "TEMPORARILY_UNAVAILABLE", "Channel state is busy; retry JOIN");
                return;
            };
            self.clonePublicChannelProps(parent, join_target);
        }

        const pre_join_modes = old_modes;
        // Prepared clone/CREATE paths have already seated this exact World id.
        // Avoid a second fallible World operation after their atomic commit.
        const newly_joined = if (clone_parent != null or prejoined_create)
            false
        else
            self.world.join(join_target, wid) catch {
                // World JOIN is failure-atomic, so no accepted mutation remains
                // and an older exact accepted intent must be restored.
                if (reversible_arm) |armed| self.rollbackReversibleLocalChannelProjection(armed);
                self.failReply(conn, "JOIN", "TEMPORARILY_UNAVAILABLE", "Channel state is busy; retry JOIN") catch {};
                return;
            };
        const logical_joined = newly_joined or prejoined_create or clone_parent != null;
        if (logical_joined) self.noteRaidJoin(join_target, self.serverName());
        if (creating) {
            // The World commit is the acceptance boundary. Purge orphaned
            // external metadata only after it succeeds so a failed JOIN cannot
            // destroy a prior incarnation's durable policy.
            self.props.clearChannel(join_target);
            _ = self.access.clear(.{ .channel = join_target }) catch {};
            // KEEPTOPIC: restore a registered channel's saved topic on recreation,
            // so a topic the founder set isn't lost when the channel empties.
            if (self.account_services) |kt| {
                var kttext: [512]u8 = undefined;
                var ktsetter: [256]u8 = undefined;
                if (kt.chanKeepTopicGet(join_target, &kttext, &ktsetter)) |saved| {
                    if (self.world.topic(join_target) == null) {
                        // A legacy value carries no setter/set_at (setter == null);
                        // fall back to serverName()/now exactly as before. A
                        // versioned value restores the original setter + set-time.
                        const restore_setter = saved.setter orelse self.serverName();
                        const restore_at = if (saved.setter != null) saved.set_at else @divFloor(platform.realtimeMillis(), 1000);
                        self.world.setTopic(join_target, saved.text, restore_setter, restore_at) catch {};
                    }
                }
                // PRIVATE (CHANNEL SET): a registered channel marked private comes
                // back hidden from public LIST/NAMES, so apply +s on recreation.
                if (kt.channelFlagSet(join_target, services_mod.channel_flag_private)) {
                    _ = self.world.setChannelFlag(join_target, .secret, true) catch {};
                }
            }
        }

        // An admin who already wields full channel authority via the +j override
        // umode must NOT also seize founder-by-creation. World.join grants the
        // founder tier (+Q) to the first member of a channel with no LOCAL members,
        // and such an admin renders with the `*` oper prefix and manages the channel
        // via +j — they neither need nor should hold a stored founder status just
        // for being first into an empty channel (e.g. autojoining after a restart
        // wiped channel state).
        //
        // Gate on the join having ACTUALLY granted founder, NOT on `creating`
        // (= !channelExists). Those two disagree across the mesh: after a node
        // restart the relink re-creates the channel ENTITY from a peer's membership
        // burst (remote members live in the link roster, not the local member set),
        // so `channelExists` is true while the LOCAL member count is still zero —
        // the admin then autojoins, world.join founds them (zero local members), but
        // a `creating`-gated strip was skipped. A freshly-joined member can hold
        // founder ONLY via founder-by-creation here (no ACCESS/services grant has run
        // yet — those re-apply a genuine registered/ACCESS founder below), so the
        // newly-joined + holds-founder pair detects exactly founder-by-creation.
        //
        // Gate on the +j umode (not the bare oper_override privilege): an oper
        // WITHOUT +j has no override authority and still needs founder-by-creation to
        // manage what it creates.
        if (logical_joined and conn.session.hasUmode(.override)) {
            if (self.world.memberModes(join_target, wid)) |mm| {
                if (mm.contains(.founder))
                    _ = self.world.setMemberMode(join_target, wid, .founder, false) catch {};
            }
        }

        // IRCX tiered keys: a presented key matching the channel's HOSTKEY/OWNERKEY
        // property grants graduated status (op / owner) on join — additive, so a
        // founder keeps founder. Member-tier (+k) is already enforced as the gate.
        if (key) |presented| {
            var tkeys = tiered_keys.ChannelKeys{};
            defer tkeys.deinit(self.allocator);
            const chan_entity = ircx_prop_store.Entity{ .kind = .channel, .id = join_target };
            if (self.props.getPropRaw(chan_entity, "HOSTKEY")) |ev| {
                tkeys.setKey(self.allocator, .host, ev.value) catch {};
            } else |_| {}
            if (self.props.getPropRaw(chan_entity, "OWNERKEY")) |ev| {
                tkeys.setKey(self.allocator, .owner, ev.value) catch {};
            } else |_| {}
            // FOUNDERKEY is a secret prop, so it must be read RAW (getProp hides
            // secrets) — matching HOSTKEY/OWNERKEY above.
            if (self.props.getPropRaw(chan_entity, "FOUNDERKEY")) |ev| {
                tkeys.setKey(self.allocator, .founder, ev.value) catch {};
            } else |_| {}
            switch (tkeys.grantFor(presented)) {
                .founder => _ = self.world.setMemberMode(join_target, wid, .founder, true) catch {},
                .owner => _ = self.world.setMemberMode(join_target, wid, .owner, true) catch {},
                .host => _ = self.world.setMemberMode(join_target, wid, .op, true) catch {},
                .member, .none => {},
            }
        }

        // IRCX ACCESS GRANT: a stored channel ACCESS entry matching the joiner and
        // resolving to a status tier auto-applies that member status on join — the
        // IRCX analog of services auto-op/-voice, and the positive counterpart to
        // the ACCESS DENY join gate. DENY is enforced earlier in joinDenied and so
        // never reaches here, leaving the joiner's highest non-DENY tier. Additive
        // (a founder-by-creation keeps founder); `catch null`/`catch ""` fail open
        // exactly as the DENY path does.
        {
            var amask_buf: [256]u8 = undefined;
            const amask = clientPrefix(conn, &amask_buf) catch "";
            if (amask.len != 0) {
                if (self.access.matchHostmask(join_target, amask) catch null) |entry| {
                    const granted: ?chanmode.MemberMode = switch (entry.level) {
                        .founder => .founder,
                        .owner => .owner,
                        // HOST is the IRCX channel-operator tier; GRANT is IRCX
                        // "operator access" — both map to +o.
                        .host, .grant => .op,
                        .voice => .voice,
                        .deny => null,
                    };
                    if (granted) |mm| _ = self.world.setMemberMode(join_target, wid, mm, true) catch {};
                }
            }
        }

        // Services CHANNEL ACCESS automode: registered account grants apply on
        // join alongside IRCX hostmask ACCESS. This uses the durable ChanServ
        // account list, not the separate IRCX mask store above.
        if (self.account_services) |svc| {
            if (conn.session.account()) |acct| {
                if (svc.channelAccessLevelFor(join_target, acct) catch null) |level| {
                    _ = self.world.setMemberMode(join_target, wid, servicesAccessMode(level), true) catch {};
                }
            }
        }

        if (local_projection) |prepared| {
            const final_modes = self.world.memberModes(join_target, wid) orelse world_model.MemberModes.empty();
            local_projection = self.finalizeLocalChannelProjection(prepared, true, final_modes.bits);
        }

        // The accepted World transition and its final post-automode journal are
        // committed above. Ancillary event publication must not abort the client
        // bootstrap and strand the command behind an unrelated event sink error.
        if (creating) self.publishChannelEvent("CREATE", join_target) catch {};

        if (logical_joined) self.broadcastJoin(join_target, conn) catch {};
        const jmodes = self.world.memberModes(join_target, wid) orelse world_model.MemberModes.empty();
        // Commit the complete signed token image before clearing the local retry
        // journal or publishing the token-less MEMBERSHIP rendering sidecar.
        // A re-JOIN may still change status through a tiered key or ACCESS grant;
        // identical re-JOINs mint no revision.
        const pre_join_bits = if (pre_join_modes) |modes| modes.bits else 0;
        const changed_logical_image = logical_joined or pre_join_bits != jmodes.bits;
        if (changed_logical_image) _ = self.commitPortableSessionMutation(id, conn);
        if (local_projection) |pending| _ = self.projectLocalChannelProjection(pending, true);
        if (changed_logical_image and !conn.session_mesh_announce_pending)
            self.announceMembership(join_target, conn.session.displayName(), @truncate(jmodes.bits), true, membershipIdentityOf(conn), "");

        // Spamtrap: a non-oper joining an operator-designated honeypot channel
        // trips the trap (oper alert + offender flag). Lock-free no-op when no
        // channel traps are configured.
        if (logical_joined) {
            self.spamtrapCheck(conn.session.displayName(), .channel, join_target, conn.session.isOper());
            self.publishMemberEvent("JOIN", join_target, conn.session.displayName(), null) catch {};
            // Standing OBSERVE feed: fire the join action so an oper watching a
            // host sees channel joins (previously defined but never emitted).
            self.notifyObservers(.join, observeSubject(conn, join_target));
        }
        if (creating) {
            var flags_buf: [16]u8 = undefined;
            const flags = self.world.channelModeString(join_target, &flags_buf);
            var line_buf: [default_reply_bytes]u8 = undefined;
            if (formatMessage(&line_buf, self.serverName(), "MODE", &.{ join_target, flags }, null)) |msg|
                self.broadcastChannel(join_target, msg, null) catch {}
            else |_| {}
        }
        if (logical_joined) {
            self.sendTopicReply(conn, join_target) catch {};
            // draft/no-implicit-names: a capable client suppresses the automatic
            // NAMES burst on JOIN (it can still request NAMES explicitly).
            // Fail-closed like explicit NAMES / resume bootstrap: never certify a
            // successful JOIN with a swallowed empty roster (nicklist desync —
            // client arms an implicit NAMES burst and will not re-poll while it
            // believes the burst is in flight). InvalidNamesRoster / OutputTooSmall
            // propagate to processLiveLine which marks conn.closing.
            if (!conn.session.hasCap(.no_implicit_names)) try self.sendNames(conn, join_target);

            self.pushMarkreadOnJoin(conn, join_target) catch {};

            // Bouncer rewind: a reconnecting client with onyx/bouncer gets the
            // channel messages it missed (everything after its stored read marker)
            // right after the NAMES burst. The replay renderer adds BATCH only when
            // the client negotiated the `batch` cap.
            self.replayRewindOnJoin(conn, join_target) catch {};
        }

        // IRCX ONJOIN: deliver the channel's on-join message PROP to the joiner.
        if (logical_joined) self.deliverChannelPropMessage(conn, join_target, "ONJOIN");
    }

    /// Deliver a channel's IRCX on-join/on-part message PROP (ONJOIN/ONPART) to a
    /// single user as a server NOTICE, tagged with the channel. No-op when unset.
    /// Reuses the live IRCX PROP store (durable + mesh-synced + access-controlled).
    fn deliverChannelPropMessage(self: *LinuxServer, conn: *ConnState, channel: []const u8, key: []const u8) void {
        const ev = self.props.getProp(.{ .kind = .channel, .id = channel }, key) catch return;
        if (ev.value.len == 0) return;
        var buf: [default_reply_bytes]u8 = undefined;
        const out = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :[{s}] {s}\r\n", .{ self.serverName(), conn.session.displayName(), channel, ev.value }) catch return;
        emitReplyLine(conn, out) catch {};
    }

    pub fn handlePart(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"PART"}, "Not enough parameters");
            return;
        }
        const reason = if (parsed.param_count >= 2) parsed.paramSlice()[1] else null;
        // `PART #a,#b :reason`: comma-separated channel list, shared reason.
        var channels = std.mem.splitScalar(u8, parsed.paramSlice()[0], ',');
        while (channels.next()) |channel| {
            if (channel.len == 0) continue;
            try self.partOne(id, conn, channel, reason);
        }
    }

    fn partOne(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, reason: ?[]const u8) !void {
        if (!self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        if (!self.world.isMember(channel, worldIdFromClient(id))) {
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{channel}, "You're not on that channel");
            return;
        }

        // Render the logical event before the acceptance arm. A formatting
        // failure therefore rejects without publishing an absent intent.
        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = try formatMessage(&msg_buf, try clientPrefix(conn, &prefix_buf), "PART", &.{channel}, reason);
        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        self.collectAttachedExactTokenClients(id, conn, &logical_ids) catch {
            try self.failReply(conn, "PART", "TEMPORARILY_UNAVAILABLE", "Session channel state is busy; retry PART");
            return;
        };

        // Once accepted, PART is a one-way exact-token intent. Arm every row
        // before broadcasting or touching World; OOM rejects the command while
        // the old membership is still intact. Any later ancillary failure leaves
        // the durable absent image for the timer projector to finish.
        const local_projection = self.armLocalChannelProjectionForClient(
            id,
            conn,
            channel,
            false,
            0,
        ) catch {
            try self.failReply(conn, "PART", "TEMPORARILY_UNAVAILABLE", "Session channel state is busy; retry PART");
            return;
        };

        // Channel membership removal also retires each affected transport's
        // media authority while the old nick/member route is still intact.
        for (logical_ids.items) |logical_id| {
            if (!self.world.isMember(channel, worldIdFromClient(logical_id))) continue;
            const logical_conn = self.connFor(logical_id) orelse continue;
            _ = self.retireMediaPhysicalChannel(logical_id, logical_conn, channel, logical_conn.session.displayName()) catch {};
        }

        // IRCX ONPART: deliver the channel's on-part message PROP to the leaver.
        self.deliverChannelPropMessage(conn, channel, "ONPART");

        // +x AUDITORIUM: a regular member's PART is only relayed to ops/voiced (and
        // the parter itself), mirroring the JOIN relay gating.
        const wid = worldIdFromClient(id);
        const parted_nick = conn.session.displayName();
        const nick_survives = self.renderedNickSurvivesTokenRemoval(id, conn, channel, parted_nick);
        const parter_rank = auditoriumRank(self.world.memberModes(channel, wid) orelse world_model.MemberModes.empty());
        if (nick_survives) {
            for (logical_ids.items) |logical_id| {
                if (!self.world.isMember(channel, worldIdFromClient(logical_id))) continue;
                self.deliverTimed(logical_id, "", msg) catch {};
            }
        } else if (self.world.channelHasExtFlag(channel, .auditorium) and !auditorium.shouldRelayJoinPart(parter_rank)) {
            var tag_buf: [48]u8 = undefined;
            const tag = serverTimeTag(&tag_buf);
            var members = self.world.memberIterator(channel) orelse unreachable;
            while (members.next()) |member| {
                const is_self = member.*.eql(wid);
                const mrank = auditoriumRank(self.world.memberModes(channel, member.*) orelse world_model.MemberModes.empty());
                if (!is_self and !auditorium.shouldRelayJoinPart(mrank)) continue;
                self.deliverTimed(clientIdFromWorld(member.*), tag, msg) catch {};
            }
        } else {
            self.broadcastChannel(channel, msg, null) catch {};
        }
        if (!nick_survives) {
            // Only the rendered identity's public 1 -> 0 transition belongs in
            // shared event-playback history.
            var part_ev_buf: [600]u8 = undefined;
            const part_body = if (reason) |r|
                (std.fmt.bufPrint(&part_ev_buf, "{s} :{s}", .{ channel, r }) catch channel)
            else
                channel;
            self.recordHistoryEvent(channel, conn, "PART", part_body);
            self.publishMemberEvent("PART", channel, parted_nick, reason) catch {};
        }
        // Standing OBSERVE feed: fire the part action (previously never emitted).
        if (!nick_survives) self.notifyObservers(.part, observeSubject(conn, channel));
        self.completeLocalChannelRemoval(id, conn, channel, parted_nick, local_projection, !nick_survives);
        if (!self.world.channelExists(channel)) self.publishChannelEvent("DESTROY", channel) catch {};
    }

    pub fn handleNames(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1) {
            // Bare NAMES lists every visible channel. A non-oper must not see a
            // secret(+s) or hidden(+h) channel, and — consistent with the
            // single-channel ShowChannel gate below — must not see a private(+p)
            // channel it is not a member of. Opers see everything; members see
            // their own private channels. Fail-closed on an unknown viewer.
            const viewer_is_oper = conn.session.isOper();
            const viewer_wid = self.world.findNick(conn.session.displayName());
            var it = self.world.channelIterator();
            while (it.next()) |ch| {
                if (!viewer_is_oper) {
                    if (ch.secret or ch.hidden) continue;
                    if (self.world.isPrivate(ch.name)) {
                        const is_member = if (viewer_wid) |vw| self.world.isMember(ch.name, vw) else false;
                        if (!is_member) continue;
                    }
                }
                if (self.rosterRefused(ch.name)) continue;
                try self.sendNames(conn, ch.name);
            }
            return;
        }

        const channel = parsed.paramSlice()[0];
        if (!self.world.channelExists(channel)) {
            if (world_model.isChannelName(channel)) {
                try queueNumeric(conn, .RPL_ENDOFNAMES, &.{channel}, "End of /NAMES list");
            } else {
                try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            }
            return;
        }
        // A sealed room has no clear member list, including for members and opers.
        // An empty 366 would look like an empty channel, so the command fails.
        if (self.rosterRefused(channel)) {
            try self.failReply(conn, "NAMES", "MEMBERSHIP_SEALED", "Channel roster is sealed");
            return;
        }
        // A secret (+s), private (+p), or hidden (+h) channel's roster is
        // visible only to its members and opers. A non-member gets a bare
        // RPL_ENDOFNAMES, never the member list. WHOIS uses the same gate.
        if (!conn.session.isOper() and
            (self.world.channelHasFlag(channel, .secret) or self.world.isPrivate(channel) or self.world.isHidden(channel)))
        {
            const viewer_wid = self.world.findNick(conn.session.displayName());
            const is_member = if (viewer_wid) |vw| self.world.isMember(channel, vw) else false;
            if (!is_member) {
                try queueNumeric(conn, .RPL_ENDOFNAMES, &.{channel}, "End of /NAMES list");
                return;
            }
        }
        try self.sendNames(conn, channel);
    }

    /// Apply IRCX +z/-z GAG to another user (operator-only; caller verified oper).
    ///
    /// GAG binds to the target's IP address, not the single connection: adding it
    /// records the IP in the persistent `gags` set, so every nick from that IP is
    /// silenced and the gag survives reconnection. The per-connection `gagged`
    /// flag is mirrored onto every live client sharing the IP for display/WHOIS.
    fn applyGag(self: *LinuxServer, conn: *ConnState, target_nick: []const u8, mode_str: []const u8) !void {
        const twid = self.world.findNick(target_nick) orelse {
            try queueNumeric(conn, .ERR_NOSUCHNICK, &.{target_nick}, "No such nick");
            return;
        };
        const tconn = self.connFor(clientIdFromWorld(twid)) orelse {
            try queueNumeric(conn, .ERR_NOSUCHNICK, &.{target_nick}, "No such nick");
            return;
        };
        var sign = true;
        var adding: ?bool = null;
        for (mode_str) |ch| switch (ch) {
            '+' => sign = true,
            '-' => sign = false,
            'z' => adding = sign,
            else => {},
        };
        const turn_on = adding orelse return; // no 'z' in the mode string

        const ip = tconn.session.realHost();
        if (turn_on) {
            if (ip.len > 0) self.recordGag(ip);
        } else {
            if (ip.len > 0) self.forgetGag(ip);
        }
        // Mirror the display flag onto every live connection from this IP (and
        // the target itself, covering the IP-unknown edge case).
        tconn.gagged = turn_on;
        if (ip.len > 0) self.mirrorGagFlag(ip, turn_on);

        var buf: [128]u8 = undefined;
        const reflect = std.fmt.bufPrint(&buf, ":{s} MODE {s} {s}z\r\n", .{ self.serverName(), target_nick, if (turn_on) "+" else "-" }) catch return;
        try appendToConn(conn, reflect);
    }

    /// Set the per-connection `gagged` display flag on every registered client
    /// whose real IP equals `ip`. Silencing itself is authoritative via `gags`.
    fn mirrorGagFlag(self: *LinuxServer, ip: []const u8, on: bool) void {
        if (ip.len == 0) return;
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                const c = entry.value;
                if (std.ascii.eqlIgnoreCase(c.session.realHost(), ip)) c.gagged = on;
            }
        }
    }

    /// MODE for channel member status modes (+Q/+q/+o/+v, founder +Q is creation-
    /// only) gated by tier rank, flag modes (i/m/n/t/s), and parameterised modes
    /// (+k key, +l limit, +b ban; `MODE #c b` lists bans). User-target MODE is not
    /// handled on this path.
    /// Emit focused list-mode errors for cap/validation failures; other errors
    /// (e.g. NoSuchChannel) are swallowed by the MODE loop as before.
    fn maybeListFull(self: *LinuxServer, conn: *ConnState, channel: []const u8, mask: []const u8, err: anyerror) ServerError!void {
        _ = self;
        if (err == error.ListFull) {
            try queueNumeric(conn, .ERR_BANLISTFULL, &.{ channel, mask }, "Channel list is full");
        } else if (err == error.InvalidMask) {
            try queueNumeric(conn, .ERR_BADCHANMASK, &.{mask}, "Invalid channel mask");
        }
    }

    pub fn handleMode(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"MODE"}, "Not enough parameters");
            return;
        }
        const channel = parsed.paramSlice()[0];
        // `MODE ISIRCX` is the IRCX discovery form (draft-pfenning): reply RPL_IRCX.
        if (std.ascii.eqlIgnoreCase(channel, "ISIRCX")) {
            try self.handleIrcx(conn, false);
            return;
        }
        if (parsed.param_count >= 2 and
            std.ascii.eqlIgnoreCase(channel, conn.session.displayName()) and
            std.ascii.eqlIgnoreCase(parsed.paramSlice()[1], "ISIRCX"))
        {
            try self.handleIrcx(conn, false);
            return;
        }
        if (!world_model.isChannelName(channel)) {
            // IRCX +z GAG: an operator may set/clear GAG on ANOTHER user; the
            // server then silently drops that user's messages. Other cross-user
            // umode changes remain forbidden.
            if (conn.session.isOper() and parsed.param_count >= 2 and
                !std.mem.eql(u8, channel, conn.session.displayName()))
            {
                const ms = parsed.paramSlice()[1];
                if (std.mem.indexOfScalar(u8, ms, 'z') != null) {
                    try self.applyGag(conn, channel, ms);
                    return;
                }
            }
            // User-target MODE: only the client's own nick is settable.
            try self.handleUserMode(id, conn, parsed, channel);
            return;
        }
        if (!self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }

        // Query form: MODE #chan -> RPL_CHANNELMODEIS. Per the channel-mode rules:
        // the +l/+k LETTERS are shown to everyone, but their PARAM VALUES (limit,
        // key) only to members. Param order matches letter order (l before k).
        if (parsed.param_count == 1) {
            var flags_buf: [16]u8 = undefined;
            const flags = self.world.channelModeString(channel, &flags_buf); // "+imnt"
            const limit = self.world.channelLimit(channel);
            const key = self.world.channelKey(channel);
            const is_member = self.world.isMember(channel, worldIdFromClient(id));

            var modes_buf: [48]u8 = undefined;
            var mb = Buf{ .storage = &modes_buf };
            mb.append(flags) catch {};
            if (limit != null) mb.appendByte('l') catch {};
            if (key != null) mb.appendByte('k') catch {};
            // Append IRCX extended flag letters (rendered "+abc"; drop the sign).
            var ext_buf: [32]u8 = undefined;
            if (chanmode_ext.renderModes(self.world.channelExtModes(channel), &ext_buf)) |ext_str| {
                if (ext_str.len > 1) mb.append(ext_str[1..]) catch {};
            } else |_| {}

            var parts: [4][]const u8 = undefined;
            var n: usize = 0;
            parts[n] = channel;
            n += 1;
            parts[n] = mb.written();
            n += 1;
            var lim_buf: [16]u8 = undefined;
            if (is_member) {
                if (limit) |lv| {
                    parts[n] = std.fmt.bufPrint(&lim_buf, "{d}", .{lv}) catch "0";
                    n += 1;
                }
                if (key) |k| {
                    parts[n] = k;
                    n += 1;
                }
            }
            try queueNumeric(conn, .RPL_CHANNELMODEIS, parts[0..n], "");
            if (self.world.channelCreatedUnix(channel)) |created| {
                var created_buf: [32]u8 = undefined;
                const created_text = std.fmt.bufPrint(&created_buf, "{d}", .{created}) catch "0";
                try queueNumeric(conn, .RPL_CREATIONTIME, &.{ channel, created_text }, "");
            }
            return;
        }

        const active_override = overrideActive(conn);
        const setter_opt = self.world.memberModes(channel, worldIdFromClient(id));
        if (setter_opt == null and !active_override) {
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{channel}, "You're not on that channel");
            return;
        }
        const setter = setter_opt orelse world_model.MemberModes.empty();
        if (!setter.isOperator() and !active_override) {
            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{channel}, "You're not channel operator");
            return;
        }
        var override_mode_bypass = active_override and !setter.isOperator();

        const mode_str = parsed.paramSlice()[1];

        // MLOCK: a services mode-lock forbids non-founder, non-oper ops from
        // changing locked flags. The founder (+Q) and server opers bypass it.
        if (!conn.session.isOper() and !setter.contains(.founder)) {
            if (self.mlocks.get(channel)) |spec_str| {
                if (mode_lock_mod.LockSpec.parse(spec_str)) |spec| {
                    var sign_on = true;
                    for (mode_str) |ch| {
                        switch (ch) {
                            '+' => sign_on = true,
                            '-' => sign_on = false,
                            // Param/status modes are not lockable simple flags.
                            'Q', 'q', 'o', 'v', 'b', 'e', 'I', 'k', 'l' => {},
                            else => {
                                if (mode_lock_mod.evaluate(spec, ch, sign_on) == .forbid) {
                                    var nb: [default_reply_bytes]u8 = undefined;
                                    const note = std.fmt.bufPrint(&nb, "Mode +{c} is locked by services (MLOCK {s})", .{ ch, spec_str }) catch return;
                                    try self.noticeTo(conn, note);
                                    return;
                                }
                            },
                        }
                    }
                } else |_| {}
            }
        }
        // Sized generously; appends soft-fail (break) rather than erroring so a
        // pathological toggle string ("+i-i+i...") truncates instead of faulting.
        var applied_buf: [256]u8 = undefined;
        var applied = Buf{ .storage = &applied_buf };
        var targets_buf: [default_reply_bytes / 2]u8 = undefined;
        var targets = Buf{ .storage = &targets_buf };
        var arg_index: usize = 2;
        var adding = true;
        var emitted_sign: u8 = 0;
        var list_setter_buf: [256]u8 = undefined;
        const list_setter = try clientPrefix(conn, &list_setter_buf);
        const list_set_at = @divFloor(platform.realtimeMillis(), 1000);
        var channel_flags_changed = false;
        var channel_state_changed = false;

        for (mode_str) |ch| {
            switch (ch) {
                '+' => adding = true,
                '-' => adding = false,
                'Q', 'q', 'o', 'v' => {
                    if (arg_index >= parsed.param_count) continue;
                    const target_nick = parsed.paramSlice()[arg_index];
                    arg_index += 1;
                    const mode: world_model.MemberMode = switch (ch) {
                        'Q' => .founder,
                        'q' => .owner,
                        'o' => .op,
                        'v' => .voice,
                        else => unreachable,
                    };
                    // Founder is singular and granted only at channel creation;
                    // it cannot be handed out via MODE (a founder may still drop
                    // or transfer their own via dedicated mechanisms later).
                    if (mode == .founder and adding) {
                        try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{channel}, "Founder is set at channel creation, not by MODE");
                        continue;
                    }
                    const target = self.world.findNick(target_nick) orelse {
                        try queueNumeric(conn, .ERR_NOSUCHNICK, &.{target_nick}, "No such nick");
                        continue;
                    };
                    const target_modes = self.world.memberModes(channel, target) orelse {
                        try queueNumeric(conn, .ERR_USERNOTINCHANNEL, &.{ target_nick, channel }, "They aren't on that channel");
                        continue;
                    };
                    // Cumulative-authority tier hierarchy (founder > owner > op):
                    // expand the named change into the concrete tier ops it implies.
                    // A deop strips the higher tiers it carries; a higher-tier
                    // removal demotes one rank. Voice is independent. See
                    // `chanmode.cascadeStatusOps`.
                    var ops_buf: [3]chanmode.TierOp = undefined;
                    const ops = ops_buf[0..chanmode.cascadeStatusOps(target_modes, mode, adding, &ops_buf)];
                    if (ops.len == 0) continue; // already in the desired state
                    // Authority: the actor must outrank the HIGHEST tier the cascade
                    // touches, not just the letter typed (a `-o` that strips a founder
                    // needs founder-level authority). Server opers with active
                    // override bypass and are audited.
                    var required_rank: u8 = 0;
                    for (ops) |op| required_rank = @max(required_rank, chanmode.rankOfMode(op.mode));
                    if (setter.rank() < required_rank) {
                        if (active_override) {
                            override_mode_bypass = true;
                        } else {
                            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{channel}, "Insufficient channel privilege for that mode");
                            continue;
                        }
                    }
                    // Rank protection: you cannot change a member ranked above you
                    // (acting on yourself is always allowed). Server opers bypass.
                    if (!target.eql(worldIdFromClient(id))) {
                        const target_rank = target_modes.rank();
                        if (!conn.session.isOper() and setter.rank() < target_rank) {
                            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{channel}, "Cannot change the modes of a higher-ranked member");
                            continue;
                        } else if (active_override and setter.rank() < target_rank) {
                            override_mode_bypass = true;
                        }
                    }
                    var desired_modes = target_modes;
                    for (ops) |op| {
                        if (op.on) desired_modes.add(op.mode) else desired_modes.remove(op.mode);
                    }
                    const target_id = clientIdFromWorld(target);
                    const target_conn = self.connFor(target_id);
                    const local_projection = if (target_conn) |local_target|
                        self.armLocalChannelProjectionForClient(
                            target_id,
                            local_target,
                            channel,
                            true,
                            desired_modes.bits,
                        ) catch {
                            try self.failReply(conn, "MODE", "TEMPORARILY_UNAVAILABLE", "Session channel state is busy; retry MODE");
                            continue;
                        }
                    else
                        null;
                    // Apply each concrete tier op; echo every one that actually
                    // flipped (so the cascade is visible on the wire).
                    var any_changed = false;
                    for (ops) |op| {
                        const changed = self.world.setMemberMode(channel, target, op.mode, op.on) catch unreachable;
                        std.debug.assert(changed);
                        any_changed = true;
                        channel_flags_changed = true;
                        const want_sign: u8 = if (op.on) '+' else '-';
                        if (emitted_sign != want_sign) {
                            applied.appendByte(want_sign) catch break;
                            emitted_sign = want_sign;
                        }
                        applied.appendByte(chanmode.memberModeLetter(op.mode)) catch break;
                        targets.appendByte(' ') catch break;
                        targets.append(target_nick) catch break;
                    }
                    if (any_changed) {
                        // Propagate the member's new prefix status to mesh peers so
                        // remote rosters + clients converge immediately (not only via
                        // the periodic re-burst). Local target only — a remote member's
                        // status is owned by its home node.
                        const nm = self.world.memberModes(channel, target) orelse world_model.MemberModes.empty();
                        // Carry the SETTER (the oper running /MODE) so the remote node
                        // renders `:setter MODE …`, not the origin server placeholder.
                        if (target_conn) |local_target| {
                            self.completeLocalMemberModeMutation(
                                target_id,
                                local_target,
                                channel,
                                target_nick,
                                nm,
                                local_projection,
                                conn.session.displayName(),
                            );
                        } else {
                            self.announceMembership(channel, target_nick, @truncate(nm.bits), true, .{}, conn.session.displayName());
                        }
                    }
                },
                'i', 'm', 'n', 't', 's', 'C', 'T', 'N', 'g', 'S', 'M', 'W', 'O', 'A' => {
                    const mode: world_model.ChannelMode = switch (ch) {
                        'i' => .invite_only,
                        'm' => .moderated,
                        'n' => .no_external,
                        't' => .topic_ops,
                        's' => .secret,
                        'C' => .no_ctcp,
                        'T' => .no_notice,
                        'N' => .no_nick,
                        'g' => .free_invite,
                        'S' => .tls_only,
                        'M' => .mod_reg,
                        'W' => .news_wire,
                        'O' => .oper_only,
                        'A' => .admin_only,
                        else => unreachable,
                    };
                    if ((mode == .oper_only or mode == .admin_only) and !conn.session.isOper()) {
                        try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "That channel mode is operator-only");
                        continue;
                    }
                    const changed = self.world.setChannelFlag(channel, mode, adding) catch continue;
                    if (changed) {
                        channel_flags_changed = true;
                        const want_sign: u8 = if (adding) '+' else '-';
                        if (emitted_sign != want_sign) {
                            applied.appendByte(want_sign) catch break;
                            emitted_sign = want_sign;
                        }
                        applied.appendByte(ch) catch break;
                    }
                },
                'p', 'h' => {
                    // +p private / +h IRCX HIDDEN (world.Channel flags, not chanmode).
                    const changed = if (ch == 'p')
                        (self.world.setPrivate(channel, adding) catch continue)
                    else
                        (self.world.setHidden(channel, adding) catch continue);
                    if (changed) {
                        channel_state_changed = true;
                        appendModeLetter(&applied, &emitted_sign, if (adding) '+' else '-', ch);
                    }
                },
                'k' => {
                    if (adding) {
                        if (arg_index >= parsed.param_count) continue;
                        const key = parsed.paramSlice()[arg_index];
                        arg_index += 1;
                        // KEYLEN: reject (do not truncate — a shortened key is a
                        // different secret) an over-long +k key. Advertised in
                        // ISUPPORT and enforced here, the primary key set-path.
                        if (key.len > self.config.keylen) continue;
                        self.world.setChannelKey(channel, key) catch continue;
                        channel_state_changed = true;
                        appendParamMode(&applied, &targets, &emitted_sign, '+', 'k', key);
                    } else {
                        self.world.setChannelKey(channel, null) catch continue;
                        channel_state_changed = true;
                        appendParamMode(&applied, &targets, &emitted_sign, '-', 'k', "*");
                    }
                },
                'l' => {
                    if (adding) {
                        if (arg_index >= parsed.param_count) continue;
                        const arg = parsed.paramSlice()[arg_index];
                        arg_index += 1;
                        const limit = std.fmt.parseInt(u32, arg, 10) catch continue;
                        self.world.setChannelLimit(channel, limit) catch continue;
                        channel_state_changed = true;
                        appendParamMode(&applied, &targets, &emitted_sign, '+', 'l', arg);
                    } else {
                        self.world.setChannelLimit(channel, null) catch continue;
                        channel_state_changed = true;
                        appendModeLetter(&applied, &emitted_sign, '-', 'l');
                    }
                },
                'b' => {
                    // No argument => RPL_BANLIST query.
                    if (arg_index >= parsed.param_count) {
                        try self.sendBanList(conn, channel);
                        continue;
                    }
                    const mask = parsed.paramSlice()[arg_index];
                    arg_index += 1;
                    var policy_snap: ?PolicyUndo = self.snapshotBan() catch null;
                    defer if (policy_snap) |*snap| self.destroyPolicyUndo(snap);
                    const changed = if (adding)
                        (self.world.addBan(channel, mask, list_setter, list_set_at) catch |e| {
                            try self.maybeListFull(conn, channel, mask, e);
                            continue;
                        })
                    else
                        (self.world.removeBan(channel, mask) catch continue);
                    if (changed) {
                        if (policy_snap) |snap| {
                            self.commitPolicy(snap);
                            policy_snap = null;
                        }
                        _ = self.recordOperAudit(list_setter, .other, mask, "ban change");
                        const sign: u8 = if (adding) '+' else '-';
                        appendParamMode(&applied, &targets, &emitted_sign, sign, 'b', mask);
                        self.announceChannelList(channel, .ban, mask, list_setter, list_set_at, adding);
                    }
                },
                'e' => {
                    // No argument => RPL_EXCEPTLIST query (348/349).
                    if (arg_index >= parsed.param_count) {
                        try self.sendMaskList(conn, channel, self.world.exemptsOf(channel), .RPL_EXCEPTLIST, .RPL_ENDOFEXCEPTLIST, "End of channel exception list");
                        continue;
                    }
                    const mask = parsed.paramSlice()[arg_index];
                    arg_index += 1;
                    const changed = if (adding)
                        (self.world.addExempt(channel, mask, list_setter, list_set_at) catch |e| {
                            try self.maybeListFull(conn, channel, mask, e);
                            continue;
                        })
                    else
                        (self.world.removeExempt(channel, mask) catch continue);
                    if (changed) {
                        appendParamMode(&applied, &targets, &emitted_sign, if (adding) '+' else '-', 'e', mask);
                        self.announceChannelList(channel, .exempt, mask, list_setter, list_set_at, adding);
                    }
                },
                'I' => {
                    // No argument => RPL_INVITELIST query (346/347).
                    if (arg_index >= parsed.param_count) {
                        try self.sendMaskList(conn, channel, self.world.invexOf(channel), .RPL_INVITELIST, .RPL_ENDOFINVITELIST, "End of channel invite exception list");
                        continue;
                    }
                    const mask = parsed.paramSlice()[arg_index];
                    arg_index += 1;
                    const changed = if (adding)
                        (self.world.addInvex(channel, mask, list_setter, list_set_at) catch |e| {
                            try self.maybeListFull(conn, channel, mask, e);
                            continue;
                        })
                    else
                        (self.world.removeInvex(channel, mask) catch continue);
                    if (changed) {
                        appendParamMode(&applied, &targets, &emitted_sign, if (adding) '+' else '-', 'I', mask);
                        self.announceChannelList(channel, .invex, mask, list_setter, list_set_at, adding);
                    }
                },
                'Z' => {
                    // +Z quiet (MUTE) list — like +b but only suppresses speech.
                    // No argument => list query (RPL_QUIETLIST 728 / 729).
                    if (arg_index >= parsed.param_count) {
                        try self.sendMaskList(conn, channel, self.world.mutesOf(channel), .RPL_QUIETLIST, .RPL_ENDOFQUIETLIST, "End of channel quiet list");
                        continue;
                    }
                    const mask = parsed.paramSlice()[arg_index];
                    arg_index += 1;
                    const changed = if (adding)
                        (self.world.addMute(channel, mask, list_setter, list_set_at) catch |e| {
                            try self.maybeListFull(conn, channel, mask, e);
                            continue;
                        })
                    else
                        (self.world.removeMute(channel, mask) catch continue);
                    if (changed) {
                        appendParamMode(&applied, &targets, &emitted_sign, if (adding) '+' else '-', 'Z', mask);
                        self.announceChannelList(channel, .quiet, mask, list_setter, list_set_at, adding);
                    }
                },
                'j' => {
                    // +j join throttle: param "joins:seconds" on set, bare on unset.
                    if (adding) {
                        if (arg_index >= parsed.param_count) continue;
                        const spec = parsed.paramSlice()[arg_index];
                        arg_index += 1;
                        const colon = std.mem.indexOfScalar(u8, spec, ':') orelse continue;
                        const joins = std.fmt.parseInt(u16, spec[0..colon], 10) catch continue;
                        const secs = std.fmt.parseInt(u32, spec[colon + 1 ..], 10) catch continue;
                        if (joins == 0 or secs == 0) continue;
                        self.world.setThrottle(channel, joins, secs) catch continue;
                        channel_state_changed = true;
                        appendParamMode(&applied, &targets, &emitted_sign, '+', 'j', spec);
                    } else {
                        if (self.world.throttleOf(channel) == null) continue;
                        self.world.clearThrottle(channel) catch continue;
                        channel_state_changed = true;
                        appendModeLetter(&applied, &emitted_sign, '-', 'j');
                    }
                },
                'f' => {
                    // +f forward: param is the target channel on set, bare on unset.
                    if (adding) {
                        if (arg_index >= parsed.param_count) continue;
                        const target = parsed.paramSlice()[arg_index];
                        arg_index += 1;
                        if (!chan_forward.validForwardTarget(target, channel)) continue;
                        // Target-side permission (forward-target check): the target
                        // must exist, and unless it is +F (freetarget) the setter
                        // must hold ops there — so you can't dump users into an
                        // arbitrary channel you don't run.
                        if (!conn.session.isOper()) {
                            if (!self.world.channelExists(target)) {
                                try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{target}, "No such channel");
                                continue;
                            }
                            if (!self.world.channelHasExtFlag(target, .freetarget)) {
                                const tm = self.world.memberModes(target, worldIdFromClient(id)) orelse world_model.MemberModes.empty();
                                if (tm.rank() < 2) {
                                    try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{target}, "You're not channel operator on the forward target");
                                    continue;
                                }
                            }
                        }
                        self.world.setForward(channel, target) catch continue;
                        channel_state_changed = true;
                        appendParamMode(&applied, &targets, &emitted_sign, '+', 'f', target);
                    } else {
                        if (self.world.forwardOf(channel) == null) continue;
                        self.world.setForward(channel, null) catch continue;
                        channel_state_changed = true;
                        appendModeLetter(&applied, &emitted_sign, '-', 'f');
                    }
                },
                else => {
                    // IRCX extended channel flags (AUTHONLY a, AUDITORIUM x,
                    // NOWHISPER w, CLONEABLE d, KNOCK u, etc.) with no base-mode slot.
                    if (chanmode_ext.letterToFlag(ch)) |flag| {
                        if (chanmode_ext.requiresOper(flag) and !conn.session.isOper()) {
                            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "That channel mode is operator-only");
                            continue;
                        }
                        const changed = self.world.setChannelExtFlag(channel, flag, adding) catch continue;
                        if (changed) {
                            channel_state_changed = true;
                            appendModeLetter(&applied, &emitted_sign, if (adding) '+' else '-', ch);
                        }
                    } else {
                        var mode_buf: [1]u8 = .{ch};
                        try queueNumeric(conn, .ERR_UNKNOWNMODE, &.{&mode_buf}, "is unknown mode char to me");
                    }
                },
            }
        }

        if (channel_flags_changed) self.announceChannelModeFlags(channel, self.channelModeFlagBits(channel));
        if (channel_state_changed) self.announceChannelModeState(channel);
        if (applied.written().len == 0) return;
        if (override_mode_bypass) self.auditOverrideUse(conn, "MODE", channel, "changed channel modes without normal channel authority");

        var prefix_buf: [256]u8 = undefined;
        var line_buf: [default_reply_bytes]u8 = undefined;
        var line = Buf{ .storage = &line_buf };
        try line.append(":");
        try line.append(try clientPrefix(conn, &prefix_buf));
        try line.append(" MODE ");
        try line.append(channel);
        try line.appendByte(' ');
        try line.append(applied.written());
        try line.append(targets.written());
        try line.append("\r\n");
        try self.broadcastChannel(channel, line.written(), null);
        // CHANNEL MODE event carries the applied mode delta + params so subscribers
        // see WHAT changed (e.g. "CHANNEL MODE #c +nt-l", "CHANNEL MODE #c +o nick"),
        // not just that a mode changed.
        var mode_detail_buf: [default_reply_bytes]u8 = undefined;
        if (std.fmt.bufPrint(&mode_detail_buf, "{s}{s}", .{ applied.written(), targets.written() })) |mode_detail| {
            try self.publishChannelEventDetail("MODE", channel, mode_detail);
        } else |_| {
            try self.publishChannelEvent("MODE", channel);
        }
        // draft/event-playback: record the channel mode change as a MODE event
        // (`:setter MODE #chan <applied> <params>`) for event-playback replay.
        var mode_ev_buf: [default_reply_bytes]u8 = undefined;
        if (std.fmt.bufPrint(&mode_ev_buf, "{s} {s}{s}", .{ channel, applied.written(), targets.written() })) |mbody| {
            self.recordHistoryEvent(channel, conn, "MODE", mbody);
        } else |_| {}
    }

    /// MODE <nick> [modes] — user modes. A client may only view/change its own
    /// (ERR_USERSDONTMATCH 502 otherwise). Query form returns RPL_UMODEIS (221).
    /// Supports +i invisible and +B bot today (IRCv3 bot-mode).
    pub fn handleUserMode(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView, target: []const u8) !void {
        if (!std.ascii.eqlIgnoreCase(target, conn.session.displayName())) {
            if (conn.session.isOper() and parsed.param_count >= 2) {
                try self.handleOperUserMode(conn, parsed, target);
                return;
            }
            try queueNumeric(conn, .ERR_USERSDONTMATCH, &.{}, "Cannot change mode for other users");
            return;
        }
        // Query form: MODE <ownnick>.
        if (parsed.param_count == 1) {
            var ms_buf: [16]u8 = undefined;
            try queueNumeric(conn, .RPL_UMODEIS, &.{}, conn.session.umodeString(&ms_buf));
            return;
        }

        const mode_str = parsed.paramSlice()[1];
        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        try self.collectAttachedExactTokenClients(id, conn, &logical_ids);
        var applied_buf: [32]u8 = undefined;
        var applied = Buf{ .storage = &applied_buf };
        var adding = true;
        var emitted_sign: u8 = 0;
        for (mode_str) |ch| {
            switch (ch) {
                '+' => adding = true,
                '-' => adding = false,
                else => {
                    // Catalog-driven: apply any client-writable user mode (i, B, D,
                    // g, C, R, p, …). Server-managed modes (r/z/x) and unknown
                    // letters are silently ignored. +j override is client-toggled
                    // but privilege-gated because it grants audited operator power.
                    const mode = usermode.modeFromLetter(ch) orelse continue;
                    const spec = usermode.specFor(mode) orelse continue;
                    if (spec.policy != .client_writable) continue;
                    if (mode == .override and adding and !conn.session.hasPriv(.oper_override)) {
                        try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied: requires the 'oper_override' operator privilege");
                        continue;
                    }
                    var changed = false;
                    for (logical_ids.items) |logical_id| {
                        const logical_conn = self.connFor(logical_id) orelse continue;
                        changed = logical_conn.session.setUmode(mode, adding) or changed;
                    }
                    if (changed) {
                        appendModeLetter(&applied, &emitted_sign, if (adding) '+' else '-', ch);
                        if (mode == .override) {
                            const detail = if (adding) "enabled override" else "disabled override";
                            self.auditOverrideUse(conn, "UMODE", conn.session.displayName(), detail);
                        }
                    }
                },
            }
        }
        if (applied.written().len == 0) return;

        // User modes are logical-session state. Publish the complete exact-token
        // snapshot before any attachment observes the reflection; a failed Store
        // accept remains dirty and retryable rather than emitting token-less mesh
        // state ahead of its authority.
        _ = self.commitPortableSessionMutation(id, conn);

        var prefix_buf: [256]u8 = undefined;
        var line_buf: [default_reply_bytes]u8 = undefined;
        const nick = conn.session.displayName();
        const msg = try formatMessage(&line_buf, try clientPrefix(conn, &prefix_buf), "MODE", &.{ nick, applied.written() }, null);
        for (logical_ids.items) |logical_id| self.deliver(logical_id, msg) catch {};
    }

    fn handleOperUserMode(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView, target: []const u8) !void {
        const twid = self.world.findNick(target) orelse {
            try queueNumeric(conn, .ERR_NOSUCHNICK, &.{target}, "No such nick");
            return;
        };
        const tid = clientIdFromWorld(twid);
        const tconn = self.connFor(tid) orelse {
            try queueNumeric(conn, .ERR_NOSUCHNICK, &.{target}, "No such nick");
            return;
        };
        const mode_str = parsed.paramSlice()[1];
        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        try self.collectAttachedExactTokenClients(tid, tconn, &logical_ids);
        var applied_buf: [16]u8 = undefined;
        var applied = Buf{ .storage = &applied_buf };
        var adding = true;
        var emitted_sign: u8 = 0;
        for (mode_str) |ch| {
            switch (ch) {
                '+' => adding = true,
                '-' => adding = false,
                else => {
                    const mode = usermode.modeFromLetter(ch) orelse continue;
                    switch (mode) {
                        .media_tx_deny, .media_presence_private => {},
                        else => continue,
                    }
                    var changed = false;
                    for (logical_ids.items) |logical_id| {
                        const logical_conn = self.connFor(logical_id) orelse continue;
                        changed = logical_conn.session.setUmode(mode, adding) or changed;
                    }
                    if (changed) {
                        appendModeLetter(&applied, &emitted_sign, if (adding) '+' else '-', ch);
                    }
                },
            }
        }
        if (applied.written().len == 0) return;
        _ = self.commitPortableSessionMutation(tid, tconn);

        var line_buf: [default_reply_bytes]u8 = undefined;
        const msg = try formatMessage(&line_buf, self.serverName(), "MODE", &.{ target, applied.written() }, null);
        appendToConn(conn, msg) catch {};
        for (logical_ids.items) |logical_id| {
            const logical_conn = self.connFor(logical_id) orelse continue;
            if (logical_conn == conn) continue;
            self.deliver(logical_id, msg) catch {};
        }
    }

    /// Convert the protocol builder's validated command body into one complete
    /// IRC wire line. `buildKickBroadcastWith` intentionally omits framing (as
    /// do the other protocol builders); this sole production boundary appends
    /// CRLF exactly once before channel delivery.
    fn buildKickWire(
        out: []u8,
        kicker_prefix: kick.Prefix,
        channel: []const u8,
        user: []const u8,
        reason: []const u8,
    ) kick.KickError![]const u8 {
        if (out.len < 2) return error.OutputTooSmall;
        const body = try kick.buildKickBroadcastWith(
            .{ .require_utf8 = false },
            out[0 .. out.len - 2],
            kicker_prefix,
            channel,
            user,
            reason,
        );
        out[body.len] = '\r';
        out[body.len + 1] = '\n';
        return out[0 .. body.len + 2];
    }

    /// KICK <channel> <user> [:reason]. Kicker must be op-or-higher and may not
    /// kick a member who outranks them (tier rank). The target sees their own
    /// kick (broadcast before removal).
    pub fn handleKick(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const args = kick.parseKickArgs(parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"KICK"}, "Not enough parameters");
            return;
        };
        if (!self.world.channelExists(args.channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{args.channel}, "No such channel");
            return;
        }
        const active_override = overrideActive(conn);
        const kicker_opt = self.world.memberModes(args.channel, worldIdFromClient(id));
        if (kicker_opt == null and !active_override) {
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{args.channel}, "You're not on that channel");
            return;
        }
        const kicker = kicker_opt orelse world_model.MemberModes.empty();
        if (!kicker.isOperator() and !active_override) {
            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{args.channel}, "You're not channel operator");
            return;
        }
        var override_kick_bypass = active_override and !kicker.isOperator();
        const target = self.world.findNick(args.user) orelse {
            try queueNumeric(conn, .ERR_USERNOTINCHANNEL, &.{ args.user, args.channel }, "They aren't on that channel");
            return;
        };
        const target_mm = self.world.memberModes(args.channel, target) orelse {
            try queueNumeric(conn, .ERR_USERNOTINCHANNEL, &.{ args.user, args.channel }, "They aren't on that channel");
            return;
        };
        // Always protect +Y: a network operator (oper holding oper_override, the
        // `*` prefix above founder) outranks every channel member. +Y is
        // oper-derived, NOT a member-mode bit, so the rank check below misses it —
        // gate explicitly. Only a server operator may kick a +Y; an owner/op who
        // is not an operator cannot. Covers local + propagated cross-mesh opers.
        if (!conn.session.isOper() and self.isOverrideOper(args.user)) {
            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{args.channel}, "Cannot kick a network operator");
            return;
        }
        if (!conn.session.isOper() and kicker.rank() < target_mm.rank()) {
            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{args.channel}, "Cannot kick a higher-ranked member");
            return;
        } else if (active_override and kicker.rank() < target_mm.rank()) {
            override_kick_bypass = true;
        }

        const kicker_prefix = kick.Prefix{ .nick = conn.session.displayName(), .user = conn.session.username(), .host = hostOf(conn) };
        // Cap the kick comment at the configured KICKLEN (advertised in ISUPPORT),
        // truncated on a UTF-8 codepoint boundary. Render before the acceptance
        // arm so a malformed/oversized event cannot strand an absent intent.
        const reason = utf8TruncateBytes(args.reason, self.config.kicklen);
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = buildKickWire(&msg_buf, kicker_prefix, args.channel, args.user, reason) catch return;

        const target_id = clientIdFromWorld(target);
        const target_conn = self.connFor(target_id);
        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        if (target_conn) |local_target| {
            self.collectAttachedExactTokenClients(target_id, local_target, &logical_ids) catch {
                try self.failReply(conn, "KICK", "TEMPORARILY_UNAVAILABLE", "Session channel state is busy; retry KICK");
                return;
            };
        }
        const local_projection = if (target_conn) |local_target|
            self.armLocalChannelProjectionForClient(
                target_id,
                local_target,
                args.channel,
                false,
                0,
            ) catch {
                try self.failReply(conn, "KICK", "TEMPORARILY_UNAVAILABLE", "Session channel state is busy; retry KICK");
                return;
            }
        else
            null;
        const nick_survives = if (target_conn) |local_target|
            self.renderedNickSurvivesTokenRemoval(target_id, local_target, args.channel, args.user)
        else
            false;

        // KICK removes the exact-token channel projection, so retire media for
        // every local physical attachment that projection will remove.
        for (logical_ids.items) |logical_id| {
            if (!self.world.isMember(args.channel, worldIdFromClient(logical_id))) continue;
            const logical_conn = self.connFor(logical_id) orelse continue;
            _ = self.retireMediaPhysicalChannel(logical_id, logical_conn, args.channel, logical_conn.session.displayName()) catch {};
        }

        if (nick_survives) {
            for (logical_ids.items) |logical_id| {
                if (!self.world.isMember(args.channel, worldIdFromClient(logical_id))) continue;
                self.deliverTimed(logical_id, "", msg) catch {};
            }
        } else {
            self.broadcastChannel(args.channel, msg, null) catch {};
        }
        if (override_kick_bypass) self.auditOverrideUse(conn, "KICK", args.channel, args.user);
        if (!nick_survives) {
            self.publishMemberEvent("KICK", args.channel, args.user, reason) catch {};
            // draft/event-playback: record only the rendered identity's public
            // 1 -> 0 transition in shared channel history.
            var kick_ev_buf: [600]u8 = undefined;
            if (std.fmt.bufPrint(&kick_ev_buf, "{s} {s} :{s}", .{ args.channel, args.user, reason })) |kbody| {
                self.recordHistoryEvent(args.channel, conn, "KICK", kbody);
            } else |_| {}
        }
        if (target_conn) |local_target| {
            self.completeLocalChannelRemoval(target_id, local_target, args.channel, args.user, local_projection, !nick_survives);
        } else {
            self.world.part(args.channel, target) catch {};
        }
        if (!self.world.channelExists(args.channel)) self.publishChannelEvent("DESTROY", args.channel) catch {};
    }

    /// ISON <nick>... — reply RPL_ISON (303) with the subset that is online.
    pub fn handleIson(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        var online_buf: [32][]const u8 = undefined;
        var count: usize = 0;
        for (parsed.paramSlice()) |nick| {
            if (count >= online_buf.len) break;
            if (self.world.findNick(nick)) |wid| {
                const mconn = self.connFor(clientIdFromWorld(wid));
                if (mconn != null and self.userHiddenByInvisible(conn, wid, mconn.?)) continue;
                online_buf[count] = nick;
                count += 1;
            }
        }
        var out_buf: [default_reply_bytes]u8 = undefined;
        var lines_buf: [8]ison_userhost.ReplyLine = undefined;
        var sink = ison_userhost.ReplyLineSink{ .lines = &lines_buf };
        ison_userhost.writeIsonReplies(&out_buf, self.serverName(), conn.session.displayName(), online_buf[0..count], alwaysOnline, &sink) catch return;
        for (sink.slice()) |line| try appendToConn(conn, line.bytes);
    }

    /// USERHOST <nick>... (up to 5) — reply RPL_USERHOST (302).
    pub fn handleUserhost(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        var targets: [ison_userhost.USERHOST_MAX_TARGETS]ison_userhost.UserhostTarget = undefined;
        var count: usize = 0;
        for (parsed.paramSlice()) |nick| {
            if (count >= targets.len) break;
            const wid = self.world.findNick(nick) orelse continue;
            // Reflect live per-client oper (`*`) and away (`-`/`+`) state from the
            // target's session, as RPL_USERHOST requires.
            const mconn = self.connFor(clientIdFromWorld(wid));
            const is_oper = if (mconn) |mc| mc.session.isOper() and !operHidden(mc, conn) else false;
            const is_away = if (mconn) |mc| mc.session.awayMessage() != null else false;
            const vhost = if (mconn) |mc| hostOf(mc) else default_host;
            targets[count] = .{ .nick = nick, .is_oper = is_oper, .is_away = is_away, .user = usernameOf(self, wid), .host = vhost };
            count += 1;
        }
        var out_buf: [default_reply_bytes]u8 = undefined;
        const line = ison_userhost.writeUserhostReply(&out_buf, self.serverName(), conn.session.displayName(), targets[0..count]) catch return;
        try appendToConn(conn, line);
    }

    /// WHO <channel|nick> — RPL_WHOREPLY (352) per match + RPL_ENDOFWHO (315).
    /// WHOX channel reply: RPL_WHOSPCRPL (354) per member with only the requested
    /// fields, then RPL_ENDOFWHO (315).
    pub fn handleWhox(self: *LinuxServer, conn: *ConnState, target: []const u8, req: whox.Request) !void {
        const requester = conn.session.displayName();
        if (world_model.isChannelName(target) and self.world.channelExists(target)) {
            if (self.rosterRefused(target)) {
                try self.failReply(conn, "WHO", "MEMBERSHIP_SEALED", "Channel roster is sealed");
                return;
            }
            // Same ShowChannel gate as plain WHO: a secret(+s), private(+p),
            // or hidden(+h) roster is visible only to members and opers.
            // Non-member non-oper gets a bare RPL_ENDOFWHO. Fail-closed.
            if (!conn.session.isOper() and
                (self.world.channelHasFlag(target, .secret) or self.world.isPrivate(target) or self.world.isHidden(target)))
            {
                const viewer_wid = self.world.findNick(requester);
                const is_member = if (viewer_wid) |vw| self.world.isMember(target, vw) else false;
                if (!is_member) {
                    var endbuf: [default_reply_bytes]u8 = undefined;
                    const end = who.writeEndOfWho(&endbuf, self.serverName(), requester, target) catch return;
                    try appendToConn(conn, end);
                    return;
                }
            }
            var it = self.world.memberIterator(target) orelse return;
            while (it.next()) |member| {
                const nick = self.world.nickOf(member.*) orelse continue;
                const mconn = self.connFor(clientIdFromWorld(member.*));
                if (mconn != null and self.userHiddenByInvisible(conn, member.*, mconn.?)) continue;
                const hp = (self.world.memberModes(target, member.*) orelse world_model.MemberModes.empty()).highestPrefix();
                try self.emitWhoxRow(conn, req, requester, target, nick, usernameOf(self, member.*), mconn, hp);
            }
        } else if (self.world.findNick(target)) |wid| {
            // Nick target: a single 354 row, no channel context (channel "*").
            const mconn = self.connFor(clientIdFromWorld(wid));
            if (mconn != null and !self.userHiddenByInvisible(conn, wid, mconn.?)) {
                try self.emitWhoxRow(conn, req, requester, "*", target, usernameOf(self, wid), mconn, 0);
            }
        }
        var endbuf: [default_reply_bytes]u8 = undefined;
        const end = who.writeEndOfWho(&endbuf, self.serverName(), requester, target) catch return;
        try appendToConn(conn, end);
    }

    /// +H hide-oper: whether `target`'s operator status must be hidden from
    /// `viewer` — true when the target set +H and the viewer is neither an oper
    /// nor the target themselves.
    fn operHidden(target: *ConnState, viewer: *ConnState) bool {
        return target.session.umodes.contains(.hide_oper) and !viewer.session.isOper() and viewer != target;
    }

    fn sharesAnyChannelWith(self: *LinuxServer, left: world_model.ClientId, right: world_model.ClientId) bool {
        if (left.eql(right)) return true;
        var chan_names: [64][]const u8 = undefined;
        const nchan = self.world.channelsOf(left, &chan_names);
        for (chan_names[0..nchan]) |channel| {
            if (self.world.isMember(channel, right)) return true;
        }
        return false;
    }

    fn userHiddenByInvisible(self: *LinuxServer, viewer: *ConnState, target_wid: world_model.ClientId, target: *ConnState) bool {
        if (!target.session.umodes.contains(.invisible)) return false;
        if (viewer == target or viewer.session.isOper()) return false;
        const viewer_wid = self.world.findNick(viewer.session.displayName()) orelse return true;
        return !self.sharesAnyChannelWith(viewer_wid, target_wid);
    }

    fn channelHiddenFromWhois(self: *LinuxServer, channel: []const u8, viewer_wid: world_model.ClientId) bool {
        if (!self.world.channelHasFlag(channel, .secret) and !self.world.isPrivate(channel) and !self.world.isHidden(channel)) return false;
        return !self.world.isMember(channel, viewer_wid);
    }

    /// Emit one RPL_WHOSPCRPL (354) row. Flags are `<H|G>[*][<prefix>]`: away,
    /// then oper, then the highest channel prefix (channel targets only).
    fn emitWhoxRow(
        self: *LinuxServer,
        conn: *ConnState,
        req: whox.Request,
        requester: []const u8,
        channel: []const u8,
        nick: []const u8,
        username: []const u8,
        mconn: ?*ConnState,
        prefix: u8,
    ) !void {
        var flags_buf: [6]u8 = undefined;
        var fl: usize = 0;
        flags_buf[fl] = if (mconn != null and mconn.?.session.awayMessage() != null) 'G' else 'H';
        fl += 1;
        if (mconn != null and mconn.?.session.isOper() and !operHidden(mconn.?, conn)) {
            flags_buf[fl] = '*';
            fl += 1;
        }
        if (prefix != 0) {
            flags_buf[fl] = prefix;
            fl += 1;
        }
        const idle: u32 = if (mconn) |c|
            @intCast(@max(0, @divTrunc(self.nowMs() - c.last_activity_ms, 1000)))
        else
            0;
        const visible_ip: []const u8 = if (mconn) |c| blk: {
            if (conn.session.isOper() or conn == c) {
                const real = c.session.realHost();
                break :blk if (real.len > 0) real else "0";
            }
            break :blk "255.255.255.255";
        } else "0";
        const visible_oper_level: []const u8 = if (mconn) |c| blk: {
            if (!c.session.isOper() or operHidden(c, conn)) break :blk "0";
            if (!conn.session.isOper() and conn != c) break :blk "0";
            const class = c.session.operClass();
            if (class.len > 0) break :blk class;
            const title = c.session.operTitle();
            break :blk if (title.len > 0) title else "1";
        } else "0";
        const ctx = whox.ReplyContext{
            .server_name = self.serverName(),
            .requester = requester,
            .request = req,
            .member = .{
                .channel = channel,
                .user = username,
                .ip = visible_ip,
                .host = if (mconn) |c| hostOf(c) else default_host,
                .server = self.serverName(),
                .nick = nick,
                .flags = flags_buf[0..fl],
                .idle_seconds = idle,
                .account = if (mconn) |c| (c.session.account() orelse "0") else "0",
                .oper_level = visible_oper_level,
                .realname = if (mconn) |c| c.session.realname() else nick,
            },
        };
        const line = whox.buildReply(self.allocator, ctx) catch return;
        defer self.allocator.free(line);
        try appendToConn(conn, line);
    }

    pub fn handleWho(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"WHO"}, "Not enough parameters");
            return;
        }
        const target = parsed.paramSlice()[0];
        const requester = conn.session.displayName();
        var buf: [default_reply_bytes]u8 = undefined;

        // WHOX: `WHO <target> %<fields>[,token]` -> RPL_WHOSPCRPL (354).
        if (parsed.param_count >= 2 and parsed.paramSlice()[1].len >= 1 and parsed.paramSlice()[1][0] == '%') {
            if (whox.parse(parsed.paramSlice()[1])) |req| {
                try self.handleWhox(conn, target, req);
                return;
            } else |_| {} // malformed selector: fall through to plain WHO
        }

        if (world_model.isChannelName(target) and self.world.channelExists(target)) {
            if (self.rosterRefused(target)) {
                try self.failReply(conn, "WHO", "MEMBERSHIP_SEALED", "Channel roster is sealed");
                return;
            }
            // A secret (+s), private (+p), or hidden (+h) roster is visible
            // only to members and opers. A non-member non-oper gets a bare
            // RPL_ENDOFWHO. Fail-closed: an unknown viewer is a non-member.
            if (!conn.session.isOper() and
                (self.world.channelHasFlag(target, .secret) or self.world.isPrivate(target) or self.world.isHidden(target)))
            {
                const viewer_wid = self.world.findNick(requester);
                const is_member = if (viewer_wid) |vw| self.world.isMember(target, vw) else false;
                if (!is_member) {
                    const end = who.writeEndOfWho(&buf, self.serverName(), requester, target) catch return;
                    try appendToConn(conn, end);
                    return;
                }
            }
            var it = self.world.memberIterator(target) orelse return;
            while (it.next()) |member| {
                const nick = self.world.nickOf(member.*) orelse continue;
                const mconn = self.connFor(clientIdFromWorld(member.*));
                if (mconn != null and self.userHiddenByInvisible(conn, member.*, mconn.?)) continue;
                const hp = (self.world.memberModes(target, member.*) orelse world_model.MemberModes.empty()).highestPrefix();
                const ctx = who.ReplyContext{
                    .server_name = self.serverName(),
                    .requester = requester,
                    .target = target,
                    .client = .{
                        .nick = nick,
                        .user = usernameOf(self, member.*),
                        .host = if (mconn) |c| hostOf(c) else default_host,
                        .server = self.serverName(),
                        .realname = if (mconn) |c| c.session.realname() else nick,
                        .away = if (mconn) |c| c.session.awayMessage() != null else false,
                        .oper = if (mconn) |c| c.session.isOper() and !operHidden(c, conn) else false,
                        .account = if (mconn) |c| c.session.account() else null,
                    },
                    .member = .{ .channel = target, .channel_prefix = if (hp != 0) hp else null },
                };
                const line = who.writeWhoReply(&buf, ctx) catch continue;
                try appendToConn(conn, line);
            }
        } else if (self.world.findNick(target)) |wid| {
            const mconn = self.connFor(clientIdFromWorld(wid));
            if (mconn != null and self.userHiddenByInvisible(conn, wid, mconn.?)) {
                // Hidden by +i: complete the query with 315 and no 352 row.
            } else {
                const ctx = who.ReplyContext{
                    .server_name = self.serverName(),
                    .requester = requester,
                    .target = target,
                    .client = .{
                        .nick = target,
                        .user = usernameOf(self, wid),
                        .host = if (mconn) |c| hostOf(c) else default_host,
                        .server = self.serverName(),
                        .realname = if (mconn) |c| c.session.realname() else target,
                        .away = if (mconn) |c| c.session.awayMessage() != null else false,
                        .oper = if (mconn) |c| c.session.isOper() and !operHidden(c, conn) else false,
                        .account = if (mconn) |c| c.session.account() else null,
                    },
                };
                if (who.writeWhoReply(&buf, ctx)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
            }
        }

        const end = who.writeEndOfWho(&buf, self.serverName(), requester, target) catch return;
        try appendToConn(conn, end);
    }

    /// LIST [<filters>] — RPL_LISTSTART/RPL_LIST/RPL_LISTEND. Secret (+s)
    /// channels are hidden. Malformed filters return a numeric instead of
    /// falling back to listing every channel. C/T filters use wall-clock seconds
    /// from the channel creation and topic timestamps. Enumerates the mesh-wide
    /// union of channels: the local world PLUS channels whose members live only
    /// on remote peers, so browse-all is identical regardless of which mesh node
    /// the client attached to.
    pub fn handleList(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const request = list.parseList(parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"LIST"}, "Invalid LIST filter");
            return;
        };
        // ELIST extended filters (>N/<N/C/T/mask); empty set matches everything.
        var filters = elist.parseParams(self.allocator, parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"LIST"}, "Invalid LIST filter");
            return;
        };
        defer filters.deinit(self.allocator);
        // Channels present only on remote peers (no local world record). Borrowed
        // name slices, valid for this handler turn; the outer slice is owned here.
        const remote_only = self.remoteOnlyChannelNames() catch &.{};
        defer self.allocator.free(remote_only);
        const Adapter = struct {
            server: *LinuxServer,
            it: world_model.World.ChannelViewIterator,
            remote: []const []const u8,
            remote_idx: usize = 0,
            filters: *const elist.FilterSet,
            now_seconds: i64,
            fn ageSeconds(now_seconds: i64, then_seconds: i64) u64 {
                if (then_seconds <= 0 or now_seconds <= then_seconds) return 0;
                return @intCast(now_seconds - then_seconds);
            }
            pub fn next(s: *@This()) ?list.ChannelInfo {
                // Phase 1: local world channels.
                while (s.it.next()) |v| {
                    if (v.secret or v.hidden) continue;
                    // Count members mesh-wide (local + remote peer roster), so the
                    // displayed count — and the >N/<N ELIST filter — match NAMES.
                    const users = s.server.globalMemberCount(v.name, v.members);
                    const created_ago = ageSeconds(s.now_seconds, v.created_unix);
                    const topic_age = ageSeconds(s.now_seconds, v.topic_time);
                    if (!s.filters.matches(.{ .name = v.name, .users = @intCast(users), .created_ago = created_ago, .topic_age = topic_age })) continue;
                    return .{
                        .name = v.name,
                        .users = @intCast(users),
                        .topic = v.topic,
                        .created_at = v.created_unix,
                        .topic_set_at = if (v.topic_time > 0) v.topic_time else null,
                    };
                }
                // Phase 2: remote-only channels. The topic is the text the peer
                // published; creation time is still unreplicated, so created stays
                // 0. Secret is honored via the gossiped MODE aggregate; hidden/private materialize a
                // world record so cannot reach this phase. Eventual-consistency
                // note: a freshly-created remote +s/+h channel can be briefly
                // visible here between its MEMBERSHIP burst and the MODE-flags/state
                // burst that follows — it self-heals once those converge.
                while (s.remote_idx < s.remote.len) {
                    const name = s.remote[s.remote_idx];
                    s.remote_idx += 1;
                    if (s.server.remoteChannelSecret(name)) continue;
                    const users = s.server.globalMemberCount(name, 0);
                    if (users == 0) continue; // no live members anywhere: nothing to show
                    const published = s.server.remotePublishedTopic(name);
                    const topic = if (published) |t| t.text else "";
                    const set_at = if (published) |t| t.set_at else 0;
                    const topic_age = ageSeconds(s.now_seconds, set_at);
                    if (!s.filters.matches(.{ .name = name, .users = @intCast(users), .created_ago = 0, .topic_age = topic_age })) continue;
                    return .{
                        .name = name,
                        .users = @intCast(users),
                        .topic = topic,
                        .created_at = 0,
                        .topic_set_at = if (set_at > 0 and topic.len != 0) set_at else null,
                    };
                }
                return null;
            }
        };
        const now_seconds = @divFloor(platform.realtimeMillis(), 1000);
        var adapter = Adapter{ .server = self, .it = self.world.channelIterator(), .remote = remote_only, .filters = &filters, .now_seconds = now_seconds };
        var scratch: [default_reply_bytes]u8 = undefined;
        var sink = ConnLineSinkCRLF{ .conn = conn };
        list.emitList(Adapter, &adapter, request, .{ .server_name = self.serverName(), .requester = conn.session.displayName(), .now_seconds = now_seconds }, &scratch, &sink) catch return;
    }

    /// Upper bound on LISTX entries emitted before the reply is truncated with
    /// RPL_LISTXTRUNC (816). Bounds pathological replies on large networks.
    const listx_max_results: usize = 1024;

    /// Write one LISTX entry (812) plus its optional PICS line (817) for `info`.
    /// PICS/SUBJECT/LANGUAGE come from the IRCX PROP store, keyed by channel name
    /// — so they resolve for remote-only channels too when the props replicated.
    fn emitListxEntry(self: *LinuxServer, conn: *ConnState, ctx: listx.ReplyContext, info: listx.ChannelInfo) !void {
        var ebuf: [default_reply_bytes]u8 = undefined;
        if (listx.writeListxEntry(&ebuf, ctx, info)) |line| try appendToConn(conn, line) else |_| {}
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = info.name };
        if (self.props.getProp(entity, "PICS")) |ev| {
            if (ev.value.len != 0) {
                var pbuf: [default_reply_bytes]u8 = undefined;
                if (listx.writeListxPics(&pbuf, ctx, info.name, ev.value)) |line| try appendToConn(conn, line) else |_| {}
            }
        } else |_| {}
    }

    /// LISTX [<filter>] — IRCX extended channel list (811/812/816/817). Every
    /// draft filter term is honored against real channel data: member-count,
    /// name/topic/subject/language masks, creation-age (`C`) and topic-age (`T`)
    /// thresholds, and the registered (`R=`) flag. Creation/topic ages are
    /// computed in wall-clock ms from the channel's `created_unix`/`topic_time`
    /// (unix seconds); SUBJECT/LANGUAGE come from the IRCX PROP store. The reply
    /// is capped at `listx_max_results`, emitting 816 when truncated. Enumerates
    /// the mesh-wide union of channels (local world PLUS remote-only channels),
    /// so browse-all is identical from any mesh node.
    pub fn handleListx(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const request = listx.parse(parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"LISTX"}, "Invalid LISTX filter");
            return;
        };
        const ctx = listx.ReplyContext{ .server_name = self.serverName(), .requester = conn.session.displayName() };
        // Channels present only on remote peers (no local world record).
        const remote_only = self.remoteOnlyChannelNames() catch &.{};
        defer self.allocator.free(remote_only);
        var buf: [default_reply_bytes]u8 = undefined;
        if (listx.writeListxStart(&buf, ctx)) |line| try appendToConn(conn, line) else |_| {}
        const now_ms: u64 = @intCast(@max(0, platform.realtimeMillis()));
        var emitted: usize = 0;
        var truncated = false;
        // Phase 1: local world channels.
        var it = self.world.channelIterator();
        while (it.next()) |v| {
            if (v.secret or v.hidden) continue;
            const entity = ircx_prop_store.Entity{ .kind = .channel, .id = v.name };
            const subject = if (self.props.getProp(entity, "SUBJECT")) |ev| ev.value else |_| "";
            const language = if (self.props.getProp(entity, "LANGUAGE")) |ev| ev.value else |_| "";
            const info = listx.ChannelInfo{
                .name = v.name,
                // Mesh-wide member count (local + remote roster), matching NAMES/LIST.
                .members = @intCast(self.globalMemberCount(v.name, v.members)),
                .topic = v.topic,
                .created_ms = if (v.created_unix > 0) @as(u64, @intCast(v.created_unix)) * 1000 else 0,
                .topic_ms = if (v.topic_time > 0) @as(u64, @intCast(v.topic_time)) * 1000 else null,
                .subject = subject,
                .language = language,
                .registered = v.registered,
            };
            if (!request.matches(info, now_ms)) continue;
            if (emitted >= listx_max_results) {
                truncated = true;
                break;
            }
            try self.emitListxEntry(conn, ctx, info);
            emitted += 1;
        }
        // Phase 2: remote-only channels. The 812 topic is the text the peer
        // published; creation time is still unreplicated. Secret is honored via
        // the gossiped MODE aggregate; hidden/private materialize a world record
        // so cannot reach this phase.
        if (!truncated) {
            for (remote_only) |name| {
                if (self.remoteChannelSecret(name)) continue;
                const members = self.globalMemberCount(name, 0);
                if (members == 0) continue;
                const entity = ircx_prop_store.Entity{ .kind = .channel, .id = name };
                const subject = if (self.props.getProp(entity, "SUBJECT")) |ev| ev.value else |_| "";
                const language = if (self.props.getProp(entity, "LANGUAGE")) |ev| ev.value else |_| "";
                const published = self.remotePublishedTopic(name);
                const topic = if (published) |t| t.text else "";
                const set_at = if (published) |t| t.set_at else 0;
                const info = listx.ChannelInfo{
                    .name = name,
                    .members = @intCast(members),
                    .topic = topic,
                    .created_ms = 0,
                    .topic_ms = if (set_at > 0 and topic.len != 0) @as(u64, @intCast(set_at)) * 1000 else null,
                    .subject = subject,
                    .language = language,
                    .registered = false,
                };
                if (!request.matches(info, now_ms)) continue;
                if (emitted >= listx_max_results) {
                    truncated = true;
                    break;
                }
                try self.emitListxEntry(conn, ctx, info);
                emitted += 1;
            }
        }
        if (truncated) {
            var tbuf: [default_reply_bytes]u8 = undefined;
            if (listx.writeListxTrunc(&tbuf, ctx, @intCast(emitted))) |line| try appendToConn(conn, line) else |_| {}
        }
        var endbuf: [default_reply_bytes]u8 = undefined;
        if (listx.writeListxEnd(&endbuf, ctx)) |line| try appendToConn(conn, line) else |_| {}
    }

    /// WHOIS [server] <nick> — full WHOIS sequence for a local user.
    pub fn handleWhois(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"WHOIS"}, "Not enough parameters");
            return;
        }
        // WHOIS [<server>] <nick>: the target is the last parameter.
        const target_nick = parsed.paramSlice()[parsed.param_count - 1];
        var storage: [default_reply_bytes * 2]u8 = undefined;
        var lines_buf: [40]whois.WhoisLine = undefined;
        var sink = whois.WhoisLineSink{ .lines = &lines_buf, .storage = &storage };

        const target_wid = self.world.findNick(target_nick);
        const target_conn: ?*ConnState = if (target_wid) |w| self.connFor(clientIdFromWorld(w)) else null;
        if (target_wid == null or target_conn == null) {
            // Not a local client: try the mesh projection before giving up. A
            // remote member announced by an established S2S peer gets a minimal
            // WHOIS (311/312/313/318) built from converged mesh state.
            if (self.findRemoteWhois(target_nick)) |remote| {
                self.sendRemoteWhois(conn, &sink, remote) catch return;
                return;
            }
            whois.writeNoSuchNick(&sink, self.serverName(), conn.session.displayName(), target_nick) catch return;
            // Always close the WHOIS with RPL_ENDOFWHOIS (318) so clients that
            // wait for the terminator don't hang on a failed lookup. Best-effort:
            // a malformed nick that 401 already reported is simply not closed.
            whois.writeEndOfWhois(&sink, self.serverName(), conn.session.displayName(), target_nick) catch {};
            for (sink.slice()) |line| try appendToConn(conn, line.bytes);
            return;
        }

        // Channels the target is in, with their highest status prefix.
        var chan_names: [32][]const u8 = undefined;
        const nchan = self.world.channelsOf(target_wid.?, &chan_names);
        var memberships: [32]whois.ChannelMembership = undefined;
        // Two bytes per channel: an optional `*` network-operator prefix plus the
        // stored highest channel prefix (e.g. "*@").
        var prefix_store: [32][2]u8 = undefined;
        const requester_wid = self.world.findNick(conn.session.displayName()) orelse world_model.ClientId.invalid;
        // Network operators (oper_override) render with the derived `*` prefix on
        // every channel in WHOIS too, mirroring NAMES — it is live oper status, not
        // a stored channel mode, so it shows even where they hold no member status.
        const target_is_oper = self.isOverrideOper(target_conn.?.session.displayName());
        var visible_nchan: usize = 0;
        for (chan_names[0..nchan]) |cn| {
            if (self.channelHiddenFromWhois(cn, requester_wid)) continue;
            const modes = self.world.memberModes(cn, target_wid.?) orelse world_model.MemberModes.empty();
            var plen: usize = 0;
            if (target_is_oper) {
                prefix_store[visible_nchan][plen] = '*';
                plen += 1;
            }
            const hp = modes.highestPrefix();
            if (hp != 0) {
                prefix_store[visible_nchan][plen] = hp;
                plen += 1;
            }
            memberships[visible_nchan] = .{ .prefix = prefix_store[visible_nchan][0..plen], .channel = cn };
            visible_nchan += 1;
        }

        const tconn = target_conn.?;

        // GeoIP/ASN summary (RPL_WHOISSPECIAL), visible to opers or to the user
        // themselves, when a MaxMind database is loaded and the IP resolves.
        var geo_buf: [256]u8 = undefined;
        var geo_text: ?[]const u8 = null;
        if (conn.session.isOper() or conn == tconn) {
            if (parseGeoIp(tconn.session.realHost())) |gip| {
                // City DB → city + region + country; the separate ASN DB → AS + org.
                var city: ?[]const u8 = null;
                var region: ?[]const u8 = null;
                var country: ?[]const u8 = null;
                if (self.ensureGeoip()) |db| {
                    if (db.lookupInfo(gip) catch null) |gi| country = gi.country_iso;
                    city = db.lookupName(gip, "city", "en") catch null;
                    region = db.lookupString(gip, &.{ "subdivisions", "0", "names", "en" }) catch null;
                }
                const asn_info = self.lookupGeoAsn(gip);
                geo_text = buildGeoWhois(&geo_buf, city, region, country, asn_info.asn, asn_info.asorg);
            }
        }

        // "make rDNS live" — fold the forward-confirmed reverse-DNS name (from the
        // resolver cache; opers/self only) into the free-form RPL_WHOISSPECIAL (320)
        // line. 320 is a trailing param so the space-bearing text is safe, and the
        // name NEVER feeds the privacy-preserving public cloak.
        var special_buf: [560]u8 = undefined;
        var rdns_buf: [cloak.max_cloak_len]u8 = undefined;
        var special: ?[]const u8 = geo_text;
        if (conn.session.isOper() or conn == tconn) {
            if (self.config.rdns) |res| {
                if (tconn.peer_addr) |paddr| {
                    if (res.lookup(paddr, &rdns_buf)) |name| {
                        special = if (geo_text) |g|
                            (std.fmt.bufPrint(&special_buf, "rDNS {s} · {s}", .{ name, g }) catch geo_text)
                        else
                            (std.fmt.bufPrint(&special_buf, "rDNS {s}", .{name}) catch null);
                    }
                }
            }
        }

        const subject = whois.WhoisSubject{
            // Show the target's nick in the exact case they registered, not the
            // case the requester happened to type in the WHOIS command.
            .nick = tconn.session.displayName(),
            .user = tconn.session.username(),
            .host = hostOf(tconn),
            .realname = tconn.session.realname(),
            .account = tconn.session.account(),
            .away = tconn.session.awayMessage(),
            // RPL_WHOISIDLE (317): seconds since the target's last PRIVMSG, and the
            // wall-clock signon time. `connected_at_ms`/`last_message_ms` are on the
            // monotonic clock, so derive the unix signon from realtime minus the
            // connection's monotonic age.
            .idle_secs = @intCast(@max(@as(i64, 0), @divTrunc(self.nowMs() - tconn.last_message_ms, 1000))),
            .signon_ts = blk: {
                const age_ms = @max(@as(i64, 0), self.nowMs() - tconn.connected_at_ms);
                const signon_unix_ms = platform.realtimeMillis() - age_ms;
                break :blk @intCast(@max(@as(i64, 0), @divTrunc(signon_unix_ms, 1000)));
            },
            .geo = special,
            // RPL_WHOISSPECIAL (320) message-restriction hints, shown to every
            // requester so a sender learns their PM will be filtered before
            // trying: +R (regonly-pm) only accepts messages from registered
            // senders; +g (caller-ID) only from accept-listed senders. Both are
            // enforced on the PRIVMSG/NOTICE path; here we only reflect the mode.
            .regonly_msgs = tconn.session.umodes.contains(.regonly_pm),
            .callerid = tconn.session.umodes.contains(.callerid),
            // RPL_WHOISSERVER (312) trailing: this node's configured description
            // (`[network] description`), mirroring the per-server description a
            // remote node gossips for its own users.
            .server_info = if (self.config.server_description.len > 0) self.config.server_description else null,
            // +H hide-oper: suppress operator status unless the requester is an
            // oper (or the user themselves).
            .is_oper = tconn.session.isOper() and !operHidden(tconn, conn),
            .is_admin = tconn.session.isAdmin() and !operHidden(tconn, conn),
            .oper_title = if (tconn.session.isOper() and !operHidden(tconn, conn) and tconn.session.operTitle().len > 0)
                tconn.session.operTitle()
            else
                null,
            .is_bot = tconn.session.isBot(),
            // RPL_WHOISCERTFP (276): surface the TLS client-cert fingerprint of a
            // mutual-TLS user (the same value SASL EXTERNAL matches to an account).
            .certfp = tconn.session.tls_certfp,
            // RPL_WHOISSECURE (671): the target is connected over TLS, with the
            // negotiated cipher suite name when the handshake recorded one
            // (local connections only; remote users carry no local TLS state).
            .is_secure = tconn.is_tls,
            .secure_cipher = tconn.session.tls_cipher,
            // RPL_WHOISACTUALLY (338): real host/IP, shown only to opers or self.
            .actual_host = if (conn.session.isOper() or conn == tconn) blk: {
                const rh = tconn.session.realHost();
                break :blk if (rh.len > 0) rh else null;
            } else null,
            // +p hide-chans: suppress the channel list unless the requester is the
            // user themselves or an oper.
            .channels = blk: {
                const hide = tconn.session.umodes.contains(.hide_chans) and
                    !conn.session.isOper() and conn != tconn;
                break :blk memberships[0..if (hide) 0 else visible_nchan];
            },
        };
        whois.writeWhois(&sink, self.serverName(), conn.session.displayName(), subject) catch return;
        for (sink.slice()) |line| try appendToConn(conn, line.bytes);
    }

    /// A remote (mesh) WHOIS subject resolved from S2S peer rosters: the nick
    /// as the roster spells it, its PROPAGATED identity (username/realname/
    /// visible host — "" when the origin never supplied it), plus its origin
    /// server — the owning node's registry name when known, falling back to the
    /// direct peer's name for an unmapped multi-hop node. Channel rosters are
    /// the only mesh-wide nick replication today, so a remote user in no
    /// channels stays unfindable (full per-nick origin tracking would need a
    /// nick→origin gossip table).
    const RemoteWhois = struct {
        nick: []const u8,
        username: []const u8,
        realname: []const u8,
        host: []const u8,
        server: []const u8,
        server_info: ?[]const u8,
        /// The member's authenticated account ("" = not logged in / unknown),
        /// propagated via cap_member_account — drives the 330 "logged in as" line.
        account: []const u8,
        /// REAL (uncloaked) host/IP, propagated only over a secured oper-info link
        /// ("" = withheld) — oper-only 338 + GeoIP/ASN 320 for the remote user.
        real_host: []const u8,
        /// TLS client-cert fingerprint ("" = none) — oper-only 276.
        certfp: []const u8,
    };

    /// Resolve `nick` as a remote mesh member via any established S2S peer
    /// (secured or plaintext). Borrowed slices; valid within this handler turn.
    fn findRemoteWhois(self: *LinuxServer, nick: []const u8) ?RemoteWhois {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    if (remoteWhoisFromLink(link, nick)) |rw| return rw;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    if (remoteWhoisFromLink(link, nick)) |rw| return rw;
                }
            }
        }
        return null;
    }

    /// Per-link roster probe (duck-typed over S2sLink / SecuredLink — both
    /// expose findRemoteMember + nodeName + nodeDescription + remoteName).
    fn remoteWhoisFromLink(link: anytype, nick: []const u8) ?RemoteWhois {
        const member = link.findRemoteMember(nick) orelse return null;
        // RPL_WHOISSERVER (312): the owning node's registry entry names the
        // remote user's actual home server; an unmapped multi-hop node falls
        // back to the direct peer's name.
        if (link.nodeName(member.node)) |name| {
            return .{
                .nick = member.nick,
                .username = member.username,
                .realname = member.realname,
                .host = member.host,
                .server = name,
                .server_info = link.nodeDescription(member.node),
                .account = member.account,
                .real_host = member.real_host,
                .certfp = member.certfp,
            };
        }
        const direct = link.remoteName();
        return .{
            .nick = member.nick,
            .username = member.username,
            .realname = member.realname,
            .host = member.host,
            .server = if (direct.len != 0) direct else default_host,
            .server_info = null,
            .account = member.account,
            .real_host = member.real_host,
            .certfp = member.certfp,
        };
    }

    /// Emit the minimal WHOIS sequence for a remote mesh member: 311 with the
    /// member's PROPAGATED identity (real username, realname, and cloaked/
    /// visible host — falling back to the placeholder/origin-server forms only
    /// when the origin never supplied identity), 312 with the actual home
    /// server, RPL_WHOISCHANNELS (319) from the mesh roster, RPL_WHOISACCOUNT
    /// (330) when the member's account propagated, RPL_WHOISOPERATOR (313) when
    /// a live mesh display grant covers the account, and 318. To an OPERATOR
    /// requester it ALSO surfaces the deanonymized identity a secured oper-info
    /// link propagated: the real host/IP (338), GeoIP/ASN (320, computed locally
    /// from that IP), and the TLS cert fingerprint (276). Idle/away/671 are
    /// per-connection state remote nodes don't replicate, so they are omitted.
    fn sendRemoteWhois(
        self: *LinuxServer,
        conn: *ConnState,
        sink: *whois.WhoisLineSink,
        remote: RemoteWhois,
    ) !void {
        // Channels the remote user is in, resolved from the mesh rosters (they are
        // not in the local world member set). Gives the 319 line that was missing.
        var memberships: [32]whois.ChannelMembership = undefined;
        var prefix_store: [32][2]u8 = undefined;
        const requester_wid = self.world.findNick(conn.session.displayName()) orelse world_model.ClientId.invalid;
        const nchan = self.remoteMemberChannels(remote.nick, requester_wid, memberships[0..], prefix_store[0..]);
        // Oper-only deanonymized identity: the real IP (338) + GeoIP/ASN (320,
        // resolved locally from that IP via the same MaxMind path the local WHOIS
        // uses) + TLS cert fingerprint (276). real_host/certfp are non-empty ONLY
        // when a secured oper-info link propagated them; additionally gate display
        // on the REQUESTER being an operator so a regular user never sees them.
        const requester_is_oper = conn.session.isOper();
        var geo_buf: [256]u8 = undefined;
        var geo_text: ?[]const u8 = null;
        if (requester_is_oper and remote.real_host.len != 0) {
            if (parseGeoIp(remote.real_host)) |gip| {
                var city: ?[]const u8 = null;
                var region: ?[]const u8 = null;
                var country: ?[]const u8 = null;
                if (self.ensureGeoip()) |db| {
                    if (db.lookupInfo(gip) catch null) |gi| country = gi.country_iso;
                    city = db.lookupName(gip, "city", "en") catch null;
                    region = db.lookupString(gip, &.{ "subdivisions", "0", "names", "en" }) catch null;
                }
                const asn_info = self.lookupGeoAsn(gip);
                geo_text = buildGeoWhois(&geo_buf, city, region, country, asn_info.asn, asn_info.asorg);
            }
        }
        const oper_display = self.remoteOperDisplay(remote.account);
        const subject = whois.WhoisSubject{
            .nick = remote.nick,
            .user = if (remote.username.len != 0) remote.username else world_projection.remote_user_placeholder,
            .host = if (remote.host.len != 0) remote.host else remote.server,
            .realname = if (remote.realname.len != 0) remote.realname else "Remote mesh user",
            .server = remote.server,
            .server_info = remote.server_info,
            // 330 "is logged in as <account>" for a remote member whose account the
            // mesh propagated (cap_member_account) — matches a local user's WHOIS.
            .account = if (remote.account.len != 0) remote.account else null,
            // Display-only projection from a live signed grant. Privilege
            // (KICK immunity, DATA, isOverrideOper) stays configured-local;
            // OCG2 activation remains separately held.
            .is_oper = oper_display != null,
            .is_admin = if (oper_display) |oper| oper.is_admin else false,
            .oper_title = if (oper_display) |oper|
                if (oper.title.len > 0) oper.title else null
            else
                null,
            // Idle/signon are per-connection state the origin node doesn't replicate,
            // so suppress RPL_WHOISIDLE rather than render a bogus "idle 0, epoch".
            .show_idle = false,
            .channels = memberships[0..nchan],
            // Oper-only deanonymized identity (see the geo block above).
            .actual_host = if (requester_is_oper and remote.real_host.len != 0) remote.real_host else null,
            .certfp = if (requester_is_oper and remote.certfp.len != 0) remote.certfp else null,
            .geo = geo_text,
        };
        whois.writeWhois(sink, self.serverName(), conn.session.displayName(), subject) catch return;
        for (sink.slice()) |line| try appendToConn(conn, line.bytes);
    }

    /// Enumerate the channels a REMOTE mesh `nick` belongs to, for its WHOIS 319.
    /// Remote members live in per-link rosters (not the world member set), so scan
    /// every known channel's established-peer roster for the nick. WHOIS is rare and
    /// the whole completion holds `world.lockWrite`, so the cross-reactor read is
    /// race-free (the guarantee `sendNames` relies on). Honors WHOIS channel
    /// visibility exactly like the local path and prepends the derived `*`
    /// network-operator prefix for an override oper, mirroring NAMES. Each
    /// `prefix_store` slot holds up to two bytes ("*" + the stored highest prefix).
    /// Returns the count written into `out`.
    fn remoteMemberChannels(
        self: *LinuxServer,
        nick: []const u8,
        requester_wid: world_model.ClientId,
        out: []whois.ChannelMembership,
        prefix_store: [][2]u8,
    ) usize {
        var n: usize = 0;
        var cit = self.world.channelIterator();
        outer: while (cit.next()) |cv| {
            if (n >= out.len) break;
            if (self.channelHiddenFromWhois(cv.name, requester_wid)) continue;
            for (self.reactors) |*reactor| {
                for (reactor.clients.slots.items) |*slot| {
                    if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                    const members = blk: {
                        if (slot.value.s2s_secured) |link| {
                            if (link.established()) break :blk link.channelMembers(cv.name);
                        } else if (slot.value.s2s) |link| {
                            if (link.established()) break :blk link.channelMembers(cv.name);
                        }
                        continue;
                    };
                    for (members) |rm| {
                        if (!std.ascii.eqlIgnoreCase(rm.nick, nick)) continue;
                        const modes = world_model.MemberModes{ .bits = @as(u8, rm.status) };
                        var plen: usize = 0;
                        if (self.isOverrideOper(nick) or self.remoteHasOverridePrefix(rm.account)) {
                            prefix_store[n][plen] = '*';
                            plen += 1;
                        }
                        const hp = modes.highestPrefix();
                        if (hp != 0) {
                            prefix_store[n][plen] = hp;
                            plen += 1;
                        }
                        out[n] = .{ .prefix = prefix_store[n][0..plen], .channel = cv.name };
                        n += 1;
                        continue :outer; // found in this channel; move to the next
                    }
                }
            }
        }
        return n;
    }

    /// INVITE <nick> <channel> — invite a user; +i channels require op (no +g
    /// free-invite mode yet). RPL_INVITING to inviter + INVITE line to target.
    pub fn handleInvite(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const args = invite.parseInviteArgs(parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"INVITE"}, "Not enough parameters");
            return;
        };
        const target_wid = self.world.findNick(args.nick) orelse {
            try queueNumeric(conn, .ERR_NOSUCHNICK, &.{args.nick}, "No such nick");
            return;
        };
        if (!self.world.channelExists(args.channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{args.channel}, "No such channel");
            return;
        }
        const inviter_modes = self.world.memberModes(args.channel, worldIdFromClient(id));
        const result = invite.checkInvitePreconditions(.{
            .on_channel = inviter_modes != null or conn.session.hasPriv(.oper_override),
            .is_operator = (if (inviter_modes) |m| m.isOperator() else false) or conn.session.hasPriv(.oper_override),
            .invite_only = self.world.channelHasFlag(args.channel, .invite_only),
            .free_invite = self.world.channelHasFlag(args.channel, .free_invite),
            .target_on_channel = self.world.isMember(args.channel, target_wid),
        });
        switch (result) {
            .allow => {},
            .deny_not_on_channel => return queueNumeric(conn, .ERR_NOTONCHANNEL, &.{args.channel}, "You're not on that channel"),
            .deny_user_on_channel => return queueNumeric(conn, .ERR_USERONCHANNEL, &.{ args.nick, args.channel }, "is already on channel"),
            .deny_chan_op_privs_needed => return queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{args.channel}, "You're not channel operator"),
        }
        // Record a persistent invite only when a channel gate consumes it: +i,
        // +l, or +j. INVITE delivery itself still succeeds for ordinary channels.
        if (self.world.channelHasFlag(args.channel, .invite_only) or
            self.world.channelLimit(args.channel) != null or
            self.world.throttleOf(args.channel) != null)
        {
            self.world.addInvite(args.channel, target_wid) catch {};
        }

        var num_buf: [default_reply_bytes]u8 = undefined;
        const inviting = invite.buildInvitingNumeric(&num_buf, self.serverName(), conn.session.displayName(), args.nick, args.channel) catch return;
        try appendToConn(conn, inviting);
        try appendToConn(conn, "\r\n");

        const prefix = invite.Prefix{ .nick = conn.session.displayName(), .user = conn.session.username(), .host = hostOf(conn) };
        var line_buf: [default_reply_bytes]u8 = undefined;
        const target_line = invite.buildTargetInviteLine(&line_buf, prefix, args.nick, args.channel) catch return;
        // deliver() expects a CRLF-terminated line; the builder omits it.
        var full_buf: [default_reply_bytes]u8 = undefined;
        const full = std.fmt.bufPrint(&full_buf, "{s}\r\n", .{target_line}) catch return;
        try self.deliver(clientIdFromWorld(target_wid), full);

        // IRCv3 invite-notify: tell channel members who hold
        // the cap, except the inviter — `:inviter!u@h INVITE <target> :<channel>`.
        var notif_prefix: [256]u8 = undefined;
        var notif_buf: [default_reply_bytes]u8 = undefined;
        const notif = try formatMessage(&notif_buf, try clientPrefix(conn, &notif_prefix), "INVITE", &.{args.nick}, args.channel);
        var members = self.world.memberIterator(args.channel) orelse return;
        while (members.next()) |member| {
            const mid = clientIdFromWorld(member.*);
            if (mid.eql(id)) continue;
            const mconn = self.connFor(mid) orelse continue;
            if (!mconn.session.hasCap(.invite_notify)) continue;
            try self.deliver(mid, notif);
        }
    }

    /// KILL <nick> :<reason> — oper-only forced disconnect. Delivers a KILL line
    /// then routes the victim through the graceful close-on-drain path (its
    /// channels see a QUIT once the buffer flushes). Non-opers get 481.
    /// `CLOSE` (oper) — drop every still-unregistered connection. A classic
    /// anti-flood tool: clears half-open/handshake-stalled clients without
    /// touching registered users or server links. Each victim is torn down via
    /// the standard drain-close path (queue ERROR, mark closing, arm send).
    /// `UNREJECT <ip>` (oper) — forget an IP's accumulated reputation penalty so
    /// a falsely-flagged host can reconnect immediately. No-op (but reported) if
    /// reputation is disabled or the IP carries no penalty.
    pub fn handleUnreject(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleUnreject(self, conn, parsed);
    }

    /// `DRAIN [OFF]` (oper) — toggle drain mode. With no arg (or `ON`) the server
    /// refuses new client connections; `DRAIN OFF` resumes accepting. Existing
    /// clients and S2S links are never affected.
    pub fn handleDrain(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleDrain(self, conn, parsed);
    }

    pub fn handleClose(self: *LinuxServer, conn: *ConnState) !void {
        return oper_cmd.handleClose(self, conn);
    }

    pub fn handleKill(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleKill(self, conn, parsed);
    }

    /// Strip control bytes (CR/LF and any other <0x20, plus DEL) from a KILL reason
    /// and clamp to the relay codec bound. Empty input (or a reason that was all
    /// control bytes) falls back to "Killed". Incorporates the old svc_killpath
    /// reason hardening into the live path.
    pub fn sanitizeKillReason(raw: []const u8, out: []u8) []const u8 {
        var n: usize = 0;
        for (raw) |b| {
            if (b < 0x20 or b == 0x7f) continue;
            if (n >= out.len) break;
            out[n] = b;
            n += 1;
        }
        if (n == 0) {
            const fallback = "Killed";
            const m = @min(fallback.len, out.len);
            @memcpy(out[0..m], fallback[0..m]);
            return out[0..m];
        }
        return out[0..n];
    }

    /// Publish the oper-visible KILL Event-Spine alert (kill category), fanned
    /// network-wide so opers everywhere see it. Issued ONCE on the killing node.
    pub fn publishKillEvent(self: *LinuxServer, real_killer: []const u8, target_nick: []const u8, reason: []const u8, override: bool) !void {
        var kev_buf: [512]u8 = undefined;
        const proof_id = self.recordOperAudit(real_killer, .kill, target_nick, reason);
        const kev = if (proof_id) |pid|
            if (override)
                (std.fmt.bufPrint(&kev_buf, "{s} killed {s} as SYSTEM ({s}) proof={s}", .{ real_killer, target_nick, reason, pid[0..] }) catch "anonymous kill")
            else
                (std.fmt.bufPrint(&kev_buf, "{s} killed {s} ({s}) proof={s}", .{ real_killer, target_nick, reason, pid[0..] }) catch reason)
        else if (override)
            (std.fmt.bufPrint(&kev_buf, "{s} killed {s} as SYSTEM ({s})", .{ real_killer, target_nick, reason }) catch "anonymous kill")
        else
            (std.fmt.bufPrint(&kev_buf, "{s} killed {s} ({s})", .{ real_killer, target_nick, reason }) catch reason);
        try self.publishOperEvent(.kill, .warn, kev);
    }

    /// Disconnect a LOCAL client as a KILL: deliver its KILL line + an ERROR close,
    /// then schedule the graceful close (the send-drain fires QUIT to channels).
    /// `kill_prefix` sources the KILL line (`nick!user@host` or SYSTEM);
    /// `public_killer` names the actor in the close reason. Cross-shard safe: a
    /// target on another reactor is closed via enqueueDeliveryThenClose (never a
    /// foreign-conn mutation); only a same-shard target is armed directly here.
    pub fn performKillDisconnect(self: *LinuxServer, target_id: client_model.ClientId, target_nick: []const u8, kill_prefix: []const u8, public_killer: []const u8, reason: []const u8) !void {
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const kill_line = try formatMessage(&msg_buf, kill_prefix, "KILL", &.{target_nick}, reason);
        try self.deliver(target_id, kill_line);

        var err_buf: [default_reply_bytes]u8 = undefined;
        const err_line = std.fmt.bufPrint(&err_buf, "ERROR :Closing Link: {s} (Killed ({s} ({s})))\r\n", .{ target_nick, public_killer, reason }) catch return error.OutputTooSmall;
        try self.enqueueDeliveryThenClose(target_id, err_line, "Killed");

        if (target_id.shard == self.rx().shard_id) {
            if (self.connFor(target_id)) |tconn| {
                tconn.closing = true;
                try self.armSendIfNeeded(tconn);
            }
        }
    }

    /// Send a signed KILL to the established mesh peer whose route_table owns
    /// `target_nick`. Returns true once a matching peer was found and the frame
    /// flushed. `killer` is the full mask (or SYSTEM); the owning node renders the
    /// KILL line/close from it.
    pub fn sendKillToOwner(self: *LinuxServer, target_nick: []const u8, killer: []const u8, reason: []const u8) bool {
        const origin = self.serverName();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    if (link.routeNickNode(target_nick) == null) continue;
                    link.sendKill(origin, killer, target_nick, reason) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                    return true;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    if (link.routeNickNode(target_nick) == null) continue;
                    link.sendKill(origin, killer, target_nick, reason) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                    return true;
                }
            }
        }
        return false;
    }

    /// Decode + apply this peer's inbound KILL frames: disconnect the named LOCAL
    /// target on behalf of the remote killer. No oper-event re-publish (the issuing
    /// node already fanned it network-wide); the resulting QUIT propagates normally.
    /// A target that is not (or no longer) local is a no-op; malformed payloads are
    /// skipped. The frame was already signature-verified by the substrate link.
    fn drainKills(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const payloads = link.takeKills() catch return;
        defer {
            for (payloads) |p| self.allocator.free(p);
            self.allocator.free(payloads);
        }
        for (payloads) |p| {
            const ev = kill_relay.decode(p) catch continue;
            // Bind the origin to the authenticated sending peer (kills are sent
            // DIRECTLY origin→owner, single hop) rather than trusting the
            // wire-supplied origin_server, which a compromised peer could spoof.
            self.applyRemoteKill(ev, trustedOrigin(link, ev.origin_server));
        }
    }

    fn applyRemoteKill(self: *LinuxServer, ev: kill_relay.KillRelay, origin: []const u8) void {
        const wid = self.world.findNick(ev.target) orelse return;
        const tid = clientIdFromWorld(wid);
        const tconn = self.connFor(tid) orelse return;
        if (tconn.s2s != null or tconn.s2s_secured != null) return; // never a peer link
        if (tconn.closing) return;
        // Local audit trail (queryable via MESH LOG) of the applied remote kill,
        // tagged with the authenticated origin server so a cross-node kill of a
        // user this node owns is traceable to its source — the origin's own
        // OPER_EVENT fan carries the oper NOTICE, so this is a log, not a dup.
        var detail_buf: [kill_relay.max_name_len + kill_relay.max_reason_len + 16]u8 = undefined;
        const detail = std.fmt.bufPrint(&detail_buf, "by {s}: {s}", .{ ev.killer, ev.reason }) catch ev.reason;
        self.logMeshEvent(.remote_kill, if (origin.len != 0) origin else ev.target, detail);
        // The remote killer mask is both the KILL-line source and the close actor.
        self.performKillDisconnect(tid, ev.target, ev.killer, ev.killer, ev.reason) catch {};
    }

    /// WHOWAS <nick> [count] — historical identities from the ring, most-recent
    /// first (314 + 312 signoff, 406 if none, 369 end).
    pub fn handleWhowas(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"WHOWAS"}, "Not enough parameters");
            return;
        }
        const target = parsed.paramSlice()[0];
        const requested_count = if (parsed.param_count >= 2)
            std.fmt.parseInt(usize, parsed.paramSlice()[1], 10) catch 16
        else
            16;
        const max_results = @min(requested_count, 16);

        var records: [16]whowas.Record = undefined;
        const found = self.whowas.query(target, max_results, &records) catch records[0..0];
        const n = found.len;

        var entries: [16]whowas_reply.HistoryEntry = undefined;
        for (found, 0..) |rec, i| {
            entries[i] = .{
                .nick = rec.nick,
                .user = rec.user,
                .host = rec.host,
                .realname = rec.realname,
                .account = rec.account,
                .signoff_time = rec.signoff_time,
                .server = self.serverName(),
            };
        }

        var scratch: [default_reply_bytes]u8 = undefined;
        var sink = ConnLineSink{ .conn = conn };
        whowas_reply.emitWhowas(&scratch, self.serverName(), conn.session.displayName(), target, entries[0..n], &sink) catch return;
    }

    /// KNOCK <channel> [:reason] — ask for an invite to a +i channel. Channel
    /// ops get RPL_KNOCK (710); the knocker gets RPL_KNOCKDLVR (711) only after
    /// a local operator is notified. Refused if the channel is open (713) or
    /// the knocker is already a member (714).
    pub fn handleKnock(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"KNOCK"}, "Not enough parameters");
            return;
        }
        const channel = parsed.paramSlice()[0];
        const reason = if (parsed.param_count >= 2) parsed.paramSlice()[1] else "wants to join";
        if (!self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        const wid = worldIdFromClient(id);
        if (self.world.isMember(channel, wid)) {
            try queueNumeric(conn, .ERR_KNOCKONCHAN, &.{channel}, "You are already on that channel");
            return;
        }
        // IRCX KNOCK gating (additive, decision 6a): KNOCK is accepted when the
        // channel is invite-only (+i) OR explicitly knock-enabled (+u). A channel
        // with neither is "open" and refuses the knock (713).
        const knock_invite = self.world.channelHasFlag(channel, .invite_only);
        const knock_ext = self.world.channelHasExtFlag(channel, .knock);
        if (!knock_invite and !knock_ext) {
            try queueNumeric(conn, .ERR_CHANOPEN, &.{channel}, "Channel is open");
            return;
        }

        // Notify every local operator-or-higher member.
        var mask_buf: [256]u8 = undefined;
        const mask = try clientPrefix(conn, &mask_buf);
        var members = self.world.memberIterator(channel) orelse return;
        var notified_ops: usize = 0;
        while (members.next()) |member| {
            const mm = self.world.memberModes(channel, member.*) orelse continue;
            if (!mm.isOperator()) continue;
            const op_id = clientIdFromWorld(member.*);
            const op_conn = self.connFor(op_id) orelse continue;
            if (op_conn.closing) continue;
            var line_buf: [default_reply_bytes]u8 = undefined;
            const line = try formatNumericLine(&line_buf, op_conn.session.displayName(), .RPL_KNOCK, &.{ channel, mask }, reason);
            if (self.enqueueDeliveryMaybeClose(op_id, line, false, "Client quit") == .delivered) notified_ops += 1;
        }
        if (notified_ops > 0) {
            try queueNumeric(conn, .RPL_KNOCKDLVR, &.{channel}, "Your KNOCK has been delivered");
        }

        // MEMBER KNOCK event: a non-member asked to enter a gated channel. Lets
        // MEMBER subscribers (and legacy oper-action opers) see knocks network-wide.
        try self.publishMemberEvent("KNOCK", channel, conn.session.displayName(), reason);
    }

    /// RENAME <#old> <#new> [:reason] — IRCv3 draft/channel-rename. A channel
    /// operator (or server oper) renames a channel in place; membership/modes/
    /// bans/topic carry over. Members negotiating draft/channel-rename receive a
    /// native `:renamer RENAME #old #new [:reason]`; others get a PART(old)+
    /// JOIN(new) fallback so their client tracks the move.
    pub fn handleRename(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const args = channel_rename.parseRenameArgs(parsed.paramSlice()) catch |e| {
            const code: []const u8 = switch (e) {
                error.MissingOldChannel, error.MissingNewChannel => "NEED_MORE_PARAMS",
                error.NeedSameType => "NEED_SAME_TYPE",
                else => "INVALID_PARAMS",
            };
            try self.failReply(conn, "RENAME", code, "Invalid RENAME parameters");
            return;
        };
        const old = args.old_channel;
        const new = args.new_channel;
        if (!self.world.channelExists(old)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{old}, "No such channel");
            return;
        }
        const wid = worldIdFromClient(id);
        if (!self.world.isMember(old, wid)) {
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{old}, "You're not on that channel");
            return;
        }
        const mm = self.world.memberModes(old, wid) orelse world_model.MemberModes.empty();
        if (!mm.isOperator() and !conn.session.isOper()) {
            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{old}, "You're not channel operator");
            return;
        }
        const ok = self.world.renameChannel(old, new) catch {
            try self.failReply(conn, "RENAME", "CANNOT_RENAME", "Could not rename channel");
            return;
        };
        if (!ok) {
            try self.failReply(conn, "RENAME", "CHANNEL_NAME_IN_USE", "Target channel name is already in use");
            return;
        }

        // Native RENAME line, sourced from the renamer's prefix.
        var pfx_buf: [256]u8 = undefined;
        const pfx = clientPrefix(conn, &pfx_buf) catch return;
        var rline_buf: [default_reply_bytes]u8 = undefined;
        const rline = if (args.reason.len != 0)
            std.fmt.bufPrint(&rline_buf, ":{s} RENAME {s} {s} :{s}\r\n", .{ pfx, old, new, args.reason }) catch return
        else
            std.fmt.bufPrint(&rline_buf, ":{s} RENAME {s} {s}\r\n", .{ pfx, old, new }) catch return;

        // CHANNEL RENAME event: a channel changed name in place. The body reads
        // chronologically ("CHANNEL RENAME #old #new") while the match subject is
        // the SURVIVING channel, so CHANNEL subscribers' channel globs track the
        // new name. Emitted before the member fan-out so it fires even for a
        // single-member channel.
        {
            var ren_buf: [512]u8 = undefined;
            if (std.fmt.bufPrint(&ren_buf, "CHANNEL RENAME {s} {s}", .{ old, new })) |ren_msg| {
                try self.publishOperEventSubject(.announce, .notice, ren_msg, new);
            } else |_| {}
        }

        // Fan out to every member (channel now lives under the new key).
        var members = self.world.memberIterator(new) orelse return;
        while (members.next()) |member| {
            const mid = clientIdFromWorld(member.*);
            const mconn = self.connFor(mid) orelse continue;
            if (mconn.session.hasCap(.channel_rename)) {
                self.deliver(mid, rline) catch {};
            } else {
                // PART(old)+JOIN(new) fallback, sourced as the member themself.
                var mpfx_buf: [256]u8 = undefined;
                const mpfx = clientPrefix(mconn, &mpfx_buf) catch continue;
                var part_buf: [default_reply_bytes]u8 = undefined;
                const part = std.fmt.bufPrint(&part_buf, ":{s} PART {s} :Channel renamed to {s}\r\n", .{ mpfx, old, new }) catch continue;
                self.deliver(mid, part) catch {};
                var join_buf: [default_reply_bytes]u8 = undefined;
                const join = std.fmt.bufPrint(&join_buf, ":{s} JOIN {s}\r\n", .{ mpfx, new }) catch continue;
                self.deliver(mid, join) catch {};
            }
        }
    }

    /// MONITOR +/-/C/L/S — IRCv3 contact notification. Targets' online/offline
    /// transitions are reported (730/731); L lists (732/733), S reports status.
    pub fn handleMonitor(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        var replies_buf: [64]monitor.MonitorReply = undefined;
        var storage: [default_reply_bytes]u8 = undefined;
        var sink = monitor.MonitorReplySink{ .replies = &replies_buf, .storage = &storage };
        // A per-connection-class `monitor` cap (when set) overrides the global
        // advertised MONITOR limit for this client's adds.
        const monitor_cap: ?usize = if (conn.class_policy.monitor != 0) conn.class_policy.monitor else null;
        self.monitor.handleWithLimit(monitorIdFromClient(id), parsed.paramSlice(), &sink, monitor_cap) catch |err| switch (err) {
            error.MissingParameter => return queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"MONITOR"}, "Not enough parameters"),
            error.OutOfMemory => return error.OutOfMemory,
            else => return, // InvalidTarget / TooManyReplies / OutputTooSmall: best-effort
        };
        try self.flushMonitorReplies(&sink);
    }

    /// Route each structured MONITOR reply to its destination watcher and arm
    /// that connection's send (replies may target clients other than the caller).
    fn flushMonitorReplies(self: *LinuxServer, sink: *const monitor.MonitorReplySink) !void {
        for (sink.slice()) |reply| {
            const wid = clientIdFromMonitor(reply.client);
            switch (reply.numeric) {
                .ERR_MONLISTFULL => {
                    var limit_buf: [16]u8 = undefined;
                    const limit = std.fmt.bufPrint(&limit_buf, "{d}", .{self.config.monitorlimit}) catch "0";
                    try self.deliverNumeric(wid, monitorNumeric(reply.numeric), &.{ limit, reply.targets }, reply.text);
                },
                .RPL_MONONLINE => {
                    var mask_buf: [default_reply_bytes]u8 = undefined;
                    const targets = self.monitorOnlineMasks(reply.targets, &mask_buf) catch reply.targets;
                    try self.deliverNumeric(wid, monitorNumeric(reply.numeric), &.{}, targets);
                },
                else => {
                    const trailing = if (reply.targets.len != 0) reply.targets else reply.text;
                    try self.deliverNumeric(wid, monitorNumeric(reply.numeric), &.{}, trailing);
                },
            }
        }
    }

    fn monitorOnlineMasks(self: *LinuxServer, targets: []const u8, out: []u8) ServerError![]const u8 {
        var buf = Buf{ .storage = out };
        var it = std.mem.splitScalar(u8, targets, ',');
        var first = true;
        while (it.next()) |target| {
            if (target.len == 0) continue;
            if (!first) try buf.appendByte(',');
            first = false;
            if (self.world.findNick(target)) |wid| {
                if (self.connFor(clientIdFromWorld(wid))) |live| {
                    var prefix_buf: [256]u8 = undefined;
                    try buf.append(try clientPrefix(live, &prefix_buf));
                    continue;
                }
            }
            try buf.append(target);
        }
        return buf.written();
    }

    /// Notify MONITOR watchers that `nick` just came online (on registration).
    fn monitorOnline(self: *LinuxServer, nick: []const u8) !void {
        const watcher_count = self.monitor.watcherCount(nick);
        var replies_buf: [64]monitor.MonitorReply = undefined;
        var allocated_replies: ?[]monitor.MonitorReply = null;
        defer if (allocated_replies) |buf| self.allocator.free(buf);
        const replies = if (watcher_count <= replies_buf.len) replies_buf[0..] else blk: {
            const buf = try self.allocator.alloc(monitor.MonitorReply, watcher_count);
            allocated_replies = buf;
            break :blk buf;
        };

        var storage_buf: [default_reply_bytes]u8 = undefined;
        var allocated_storage: ?[]u8 = null;
        defer if (allocated_storage) |buf| self.allocator.free(buf);
        const storage_len = @max(default_reply_bytes, watcher_count * @max(nick.len, @as(usize, 1)));
        const storage = if (storage_len <= storage_buf.len) storage_buf[0..] else blk: {
            const buf = try self.allocator.alloc(u8, storage_len);
            allocated_storage = buf;
            break :blk buf;
        };

        var sink = monitor.MonitorReplySink{ .replies = replies, .storage = storage };
        self.monitor.setOnline(nick, &sink) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.TooManyReplies, error.OutputTooSmall => {
                try self.flushMonitorReplies(&sink);
                return;
            },
            else => return,
        };
        try self.flushMonitorReplies(&sink);
    }

    /// Notify watchers that the final physical occupant of `nick` went offline.
    /// Connection-owned subscriptions are removed independently by `closeConn`
    /// even when a same-nick sibling keeps this rendered identity online.
    fn monitorOffline(self: *LinuxServer, nick: []const u8) !void {
        try self.monitorOccupancyTransition(nick, nick, false, true);
    }

    /// STATS <letter> — server statistics. Supports u (uptime, 242), o (oper
    /// blocks, 243), k/d (WARD ban masks/addresses, 216/225), y (connection
    /// classes + per-class policy/match/live, 218), l (established S2S peer links,
    /// 211), c (connect blocks / mesh peers, 213), i (allow blocks / connection
    /// classes, 215), m (command usage counts, 212), p (online opers, public), and
    /// z (runtime counters, 249, oper-only). Terminates with 219.
    pub fn handleStats(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleStats(self, conn, parsed);
    }

    /// RECOGNIZE ADD|DEL|LIST [mask] — manage YOUR account's host-recognition list
    /// (svc_acclist). A later unauthenticated connection whose nick matches your
    /// account and whose `nick!user@host` matches one of these masks is SOFT-
    /// recognized (keeps the nick past the protection grace) but is granted NO
    /// account privileges without SASL. Managing the list requires being identified.
    pub fn handleRecognize(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const acct = conn.session.account() orelse {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{"RECOGNIZE"}, "You must be identified to manage your recognition list");
            return;
        };
        const svc = self.account_services orelse {
            try queueNumeric(conn, .ERR_UNKNOWNCOMMAND, &.{"RECOGNIZE"}, "Account services are unavailable");
            return;
        };
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"RECOGNIZE"}, "Usage: RECOGNIZE ADD|DEL|LIST [mask]");
            return;
        }
        const params = parsed.paramSlice();
        const sub = params[0];
        const nick = conn.session.displayName();
        var nb: [600]u8 = undefined;

        if (std.ascii.eqlIgnoreCase(sub, "LIST")) {
            var lb: [4096]u8 = undefined;
            const blob = svc.recognizeBlob(acct, &lb);
            if (blob.len == 0) {
                const line = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :Recognition list for {s} is empty\r\n", .{ self.serverName(), nick, acct }) catch return;
                try emitReplyLine(conn, line);
                return;
            }
            var it = std.mem.splitScalar(u8, blob, '\n');
            while (it.next()) |m| {
                if (m.len == 0) continue;
                const line = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :Recognize: {s}\r\n", .{ self.serverName(), nick, m }) catch continue;
                try emitReplyLine(conn, line);
            }
            return;
        }

        if (params.len < 2 or params[1].len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"RECOGNIZE"}, "Usage: RECOGNIZE ADD|DEL <mask>");
            return;
        }
        const mask = params[1];

        if (std.ascii.eqlIgnoreCase(sub, "ADD")) {
            const outcome = svc.recognizeAdd(acct, mask) catch {
                try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{"RECOGNIZE"}, "Could not update recognition list");
                return;
            };
            const msg = switch (outcome) {
                .added => "added to your recognition list",
                .already_present => "is already on your recognition list",
                .list_full => "rejected: recognition list is full",
                .invalid_mask => "rejected: invalid mask",
            };
            const line = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :Recognize {s}: {s}\r\n", .{ self.serverName(), nick, mask, msg }) catch return;
            try emitReplyLine(conn, line);
            return;
        }

        if (std.ascii.eqlIgnoreCase(sub, "DEL") or std.ascii.eqlIgnoreCase(sub, "REMOVE")) {
            const removed = svc.recognizeDel(acct, mask) catch {
                try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{"RECOGNIZE"}, "Could not update recognition list");
                return;
            };
            const msg = if (removed) "removed from your recognition list" else "was not on your recognition list";
            const line = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :Recognize {s}: {s}\r\n", .{ self.serverName(), nick, mask, msg }) catch return;
            try emitReplyLine(conn, line);
            return;
        }

        try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"RECOGNIZE"}, "Usage: RECOGNIZE ADD|DEL|LIST [mask]");
    }

    /// MARKREAD <target> [timestamp=…] — IRCv3 read-marker. GET returns the
    /// stored marker (or `*`); SET advances it (monotonic) and echoes it back.
    /// Authenticated accounts share a durable mesh position. Guests retain only
    /// this physical connection's local position.
    pub fn handleMarkread(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.hasCap(.read_marker)) {
            try self.failReply(conn, "MARKREAD", "NEED_REGISTRATION", "You must negotiate the draft/read-marker capability");
            return;
        }
        if (self.read_marker_unavailable) {
            try self.failReply(conn, "MARKREAD", "TEMPORARILY_UNAVAILABLE", "Read markers are unavailable");
            return;
        }
        var owner_buf: [read_marker_store.default_max_owner_bytes]u8 = undefined;
        const owner = readMarkerOwner(conn, &owner_buf) catch return;
        const req = read_marker_store.parse(parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"MARKREAD"}, "Invalid MARKREAD parameters");
            return;
        };
        var out_buf: [default_reply_bytes]u8 = undefined;
        const line = switch (req) {
            .get => |target| blk: {
                const ts = self.read_markers.get(owner, target) catch null;
                break :blk if (ts) |t|
                    (read_marker_store.buildTimestampResponse(target, t, &out_buf) catch return)
                else
                    (read_marker_store.buildResponse(target, .unset, &out_buf) catch return);
            },
            .set => |sr| blk: {
                const ts = switch (sr.marker) {
                    .timestamp => |t| t,
                    .unset => break :blk (read_marker_store.buildResponse(sr.target, .unset, &out_buf) catch return),
                };
                const res = if (conn.session.account() != null)
                    self.commitAccountReadMarker(owner, sr.target, ts) catch {
                        try self.failReply(conn, "MARKREAD", "TEMPORARILY_UNAVAILABLE", "Could not save read marker; retry later");
                        return;
                    }
                else
                    self.read_markers.set(owner, sr.target, ts) catch return;
                if (res.changed and conn.session.account() != null) {
                    self.publishAccountReadMarker(owner, sr.target, res.timestamp, conn);
                }
                break :blk (read_marker_store.buildTimestampResponse(sr.target, res.timestamp, &out_buf) catch return);
            },
        };
        try appendToConn(conn, line);
    }

    fn currentPinsValue(self: *LinuxServer, channel: []const u8) []const u8 {
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const ev = self.props.getProp(entity, "PINS") catch return "";
        return ev.value;
    }

    fn emitPinsReply(self: *LinuxServer, conn: *ConnState, channel: []const u8, value: []const u8) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} PINS {s} :{s}\r\n", .{ self.serverName(), channel, value }) catch return error.OutputTooSmall;
        try appendToConn(conn, line);
    }

    fn persistPinsValue(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, value: []const u8) !bool {
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const access = self.propAccess(id, conn, entity) orelse {
            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{channel}, "You're not channel operator");
            return false;
        };
        switch (self.channelBuiltinSet(entity, "PINS", value, false)) {
            .bad_value => {
                try queueNumeric(conn, .ERR_BADVALUE, &.{ channel, "PINS" }, "Invalid property value");
                return false;
            },
            .applied => return false,
            .not_handled => {},
        }
        if (overrideActive(conn) and self.propOverrideWouldBypass(id, entity)) {
            self.auditOverrideUse(conn, "PINS", channel, "SET");
        }
        const setter = ircx_prop_store.Setter{ .id = conn.session.displayName(), .access = access };
        const ev = self.props.setProp(entity, "PINS", value, setter) catch {
            try queueNumeric(conn, .ERR_BADVALUE, &.{ channel, "PINS" }, "Invalid property value");
            return false;
        };
        const hlc = self.nextChannelPropHlc();
        var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
        var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
        const ps = self.signLocalChannelProp(true, ev.entity.id, ev.key, ev.value, ev.owner, hlc, &pk_buf, &sig_buf);
        if (self.recordChannelPropClock(ev.entity.id, ev.key, ev.owner, hlc, true, ps.node, ps.pubkey, ps.sig)) {
            self.announceChannelProp(ev.entity.id, ev.key, ev.value, ev.owner, hlc, true, .{ .node = ps.node, .pubkey = ps.pubkey, .sig = ps.sig });
        }
        self.notifyLocalPropChange(conn, ev.entity, ev.key, ev.value);
        return true;
    }

    /// PINS <#channel> [LIST|ADD <msgid>|DEL <msgid>|CLEAR] — first-class
    /// front-end for the mesh-propagated `PINS` channel PROP. The command does
    /// not create a second store; clients using IRCX PROP see the same state.
    pub fn handlePins(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"PINS"}, "Usage: PINS <#channel> [LIST|ADD <msgid>|DEL <msgid>|CLEAR]");
            return;
        }
        const channel = parsed.paramSlice()[0];
        if (!world_model.isChannelName(channel) or !self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        const wid = worldIdFromClient(id);
        if (!conn.session.isOper() and !self.world.isMember(channel, wid)) {
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{channel}, "You're not on that channel");
            return;
        }

        const current = self.currentPinsValue(channel);
        if (parsed.param_count == 1 or std.ascii.eqlIgnoreCase(parsed.paramSlice()[1], "LIST")) {
            try self.emitPinsReply(conn, channel, current);
            return;
        }

        const sub = parsed.paramSlice()[1];
        var next_buf: [ircx_prop_store.default_max_value]u8 = undefined;
        var mutation: PinsMutation = undefined;
        if (std.ascii.eqlIgnoreCase(sub, "ADD")) {
            if (parsed.param_count < 3) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"PINS"}, "Usage: PINS <#channel> ADD <msgid>");
                return;
            }
            mutation = pinsAddValue(current, parsed.paramSlice()[2], &next_buf, self.config.media_pins_max_per_channel, self.config.media_pins_max_msgid_bytes) orelse {
                try queueNumeric(conn, .ERR_BADVALUE, &.{ channel, "PINS" }, "Invalid property value");
                return;
            };
        } else if (std.ascii.eqlIgnoreCase(sub, "DEL") or std.ascii.eqlIgnoreCase(sub, "REMOVE")) {
            if (parsed.param_count < 3) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"PINS"}, "Usage: PINS <#channel> DEL <msgid>");
                return;
            }
            mutation = pinsDeleteValue(current, parsed.paramSlice()[2], &next_buf, self.config.media_pins_max_msgid_bytes) orelse {
                try queueNumeric(conn, .ERR_BADVALUE, &.{ channel, "PINS" }, "Invalid property value");
                return;
            };
        } else if (std.ascii.eqlIgnoreCase(sub, "CLEAR")) {
            mutation = .{ .value = "", .changed = current.len != 0 };
        } else {
            try self.failReply(conn, "PINS", "INVALID_SUBCOMMAND", "Use LIST, ADD, DEL, or CLEAR");
            return;
        }

        if (mutation.changed) {
            if (!try self.persistPinsValue(id, conn, channel, mutation.value)) return;
        }
        try self.emitPinsReply(conn, channel, mutation.value);
    }

    fn pushMarkreadOnJoin(self: *LinuxServer, conn: *ConnState, channel: []const u8) !void {
        if (self.read_marker_unavailable) return;
        if (!conn.session.hasCap(.read_marker)) return;
        var owner_buf: [read_marker_store.default_max_owner_bytes]u8 = undefined;
        const owner = readMarkerOwner(conn, &owner_buf) catch return;
        const ts = (self.read_markers.get(owner, channel) catch null) orelse return;
        var out_buf: [default_reply_bytes]u8 = undefined;
        const line = read_marker_store.buildTimestampResponse(channel, ts, &out_buf) catch return;
        try appendToConn(conn, line);
    }

    /// SILENCE [+mask|-mask ...] — server-side ignore list. With no args (or a
    /// query) it lists the caller's masks (RPL_SILELIST 271 / 272). Add/remove
    /// ops are applied and echoed. Keyed by the caller's nick.
    pub fn handleSilence(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const owner = conn.session.displayName();
        if (parsed.param_count == 0) {
            var lbuf: [default_reply_bytes]u8 = undefined;
            const masks = self.silence.list(owner, &lbuf) catch "";
            if (masks.len != 0) try queueNumeric(conn, .RPL_SILELIST, &.{masks}, "");
            try queueNumeric(conn, .RPL_ENDOFSILELIST, &.{}, "End of SILENCE list");
            return;
        }
        const req = silence.parse(parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"SILENCE"}, "Invalid SILENCE mask");
            return;
        };
        var prefix_buf: [256]u8 = undefined;
        const prefix = try clientPrefix(conn, &prefix_buf);
        // A per-connection-class `silence` cap (when set) overrides the global
        // advertised SILENCE limit for this owner's adds.
        const silence_cap: usize = if (conn.class_policy.silence != 0)
            conn.class_policy.silence
        else
            self.silence.params.max_masks_per_owner;
        const silence_acct = conn.session.account();
        for (req.slice()) |op| {
            const changed = switch (op.kind) {
                .add => self.silence.addWithLimit(owner, op.mask, silence_cap) catch continue,
                .remove => self.silence.remove(owner, op.mask) catch continue,
            };
            if (!changed) continue;
            // Account-persist so the ignore list survives reconnect / cold restart.
            if (silence_acct) |a| if (self.account_services) |svc| switch (op.kind) {
                .add => svc.silencePersistAdd(a, op.mask) catch {},
                .remove => svc.silencePersistDel(a, op.mask) catch {},
            };
            var line_buf: [default_reply_bytes]u8 = undefined;
            const sign: u8 = if (op.kind == .add) '+' else '-';
            const line = std.fmt.bufPrint(&line_buf, ":{s} SILENCE {c}{s}\r\n", .{ prefix, sign, op.mask }) catch continue;
            try appendToConn(conn, line);
        }
    }

    /// LISTCHANS — list the registered channels where YOU (your account) hold an
    /// access grant, with your level. The durable reverse of `CHANNEL ACCESS LIST`;
    /// handy for a "my channels" view in web clients. Requires being identified.
    pub fn handleListchans(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        _ = parsed;
        const acct = conn.session.account() orelse {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{"LISTCHANS"}, "You must be identified to list your channels");
            return;
        };
        const svc = self.account_services orelse {
            try queueNumeric(conn, .ERR_UNKNOWNCOMMAND, &.{"LISTCHANS"}, "Account services are unavailable");
            return;
        };
        var count: usize = 0;
        const Ctx = struct { srv: *LinuxServer, conn: *ConnState, count: *usize };
        svc.channelsForAccount(acct, Ctx{ .srv = self, .conn = conn, .count = &count }, struct {
            fn cb(c: Ctx, channel: []const u8, level: services_mod.AccessLevel) void {
                var nb: [600]u8 = undefined;
                const line = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :LISTCHANS {s} {s}\r\n", .{ c.srv.serverName(), c.conn.session.displayName(), channel, @tagName(level) }) catch return;
                emitReplyLine(c.conn, line) catch {};
                c.count.* += 1;
            }
        }.cb);
        var eb: [128]u8 = undefined;
        const endl = std.fmt.bufPrint(&eb, ":{s} NOTICE {s} :End of LISTCHANS ({d})\r\n", .{ self.serverName(), conn.session.displayName(), count }) catch return;
        try emitReplyLine(conn, endl);
    }

    /// CHANBADWORDS <#channel> <ADD|DEL|LIST> [pattern] — per-channel word filter
    /// (svc_chanbadwords). Channel operators manage the list; a matching message
    /// from a non-op/non-oper member is blocked. Patterns are case-insensitive
    /// substrings; the list is durable (survives restart).
    pub fn handleChanbadwords(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"CHANBADWORDS"}, "Usage: CHANBADWORDS <#channel> <ADD|DEL|LIST> [pattern]");
            return;
        }
        const params = parsed.paramSlice();
        const channel = params[0];
        const sub = params[1];
        if (!self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        const svc = self.account_services orelse {
            try queueNumeric(conn, .ERR_UNKNOWNCOMMAND, &.{"CHANBADWORDS"}, "Account services are unavailable");
            return;
        };
        const mm = self.world.memberModes(channel, worldIdFromClient(id)) orelse {
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{channel}, "You're not on that channel");
            return;
        };
        if (!mm.isOperator() and !conn.session.isOper()) {
            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{channel}, "You're not channel operator");
            return;
        }
        const nick = conn.session.displayName();
        var nb: [600]u8 = undefined;

        if (std.ascii.eqlIgnoreCase(sub, "LIST")) {
            const Ctx = struct { srv: *LinuxServer, conn: *ConnState, channel: []const u8 };
            svc.chanBadwordForEach(channel, Ctx{ .srv = self, .conn = conn, .channel = channel }, struct {
                fn cb(c: Ctx, pattern: []const u8) void {
                    var b: [600]u8 = undefined;
                    const line = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :CHANBADWORDS {s} :{s}\r\n", .{ c.srv.serverName(), c.conn.session.displayName(), c.channel, pattern }) catch return;
                    emitReplyLine(c.conn, line) catch {};
                }
            }.cb);
            const endl = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :End of CHANBADWORDS for {s}\r\n", .{ self.serverName(), nick, channel }) catch return;
            try emitReplyLine(conn, endl);
            return;
        }
        if (params.len < 3 or params[2].len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"CHANBADWORDS"}, "Usage: CHANBADWORDS <#channel> <ADD|DEL> <pattern>");
            return;
        }
        const pattern = params[2];
        if (std.ascii.eqlIgnoreCase(sub, "ADD")) {
            const ok = svc.chanBadwordAdd(channel, pattern) catch false;
            const msg = if (ok) "added" else "rejected (duplicate, too long, or list full)";
            const line = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :CHANBADWORDS {s} {s}: {s}\r\n", .{ self.serverName(), nick, channel, pattern, msg }) catch return;
            try emitReplyLine(conn, line);
            return;
        }
        if (std.ascii.eqlIgnoreCase(sub, "DEL") or std.ascii.eqlIgnoreCase(sub, "REMOVE")) {
            const ok = svc.chanBadwordDel(channel, pattern) catch false;
            const msg = if (ok) "removed" else "not found";
            const line = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :CHANBADWORDS {s} {s}: {s}\r\n", .{ self.serverName(), nick, channel, pattern, msg }) catch return;
            try emitReplyLine(conn, line);
            return;
        }
        try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"CHANBADWORDS"}, "Usage: CHANBADWORDS <#channel> <ADD|DEL|LIST> [pattern]");
    }

    fn lowerCopy(out: []u8, value: []const u8) ?[]const u8 {
        if (value.len > out.len) return null;
        for (value, 0..) |ch, i| out[i] = std.ascii.toLower(ch);
        return out[0..value.len];
    }

    fn bytesLess(a: []const u8, b: []const u8) bool {
        const n = @min(a.len, b.len);
        var i: usize = 0;
        while (i < n) : (i += 1) {
            if (a[i] != b[i]) return a[i] < b[i];
        }
        return a.len < b.len;
    }

    fn dmHistoryKey(a_nick: []const u8, a_account: ?[]const u8, b_nick: []const u8, b_account: ?[]const u8, out: []u8) ?[]const u8 {
        const use_accounts = a_account != null and b_account != null;
        const a = if (use_accounts) a_account.? else a_nick;
        const b = if (use_accounts) b_account.? else b_nick;
        var la_buf: [128]u8 = undefined;
        var lb_buf: [128]u8 = undefined;
        const la = lowerCopy(&la_buf, a) orelse return null;
        const lb = lowerCopy(&lb_buf, b) orelse return null;
        const first = if (bytesLess(la, lb)) la else lb;
        const second = if (bytesLess(la, lb)) lb else la;
        const scope: []const u8 = if (use_accounts) "acct" else "nick";
        return std.fmt.bufPrint(out, "$dm:{s}:{s}:{s}", .{ scope, first, second }) catch null;
    }

    pub fn historyKeyForTarget(self: *LinuxServer, conn: *ConnState, target: []const u8, out: []u8) []const u8 {
        if (world_model.isChannelName(target)) return target;
        const peer_account = if (self.world.findNick(target)) |wid|
            if (self.connFor(clientIdFromWorld(wid))) |peer| peer.session.account() else null
        else
            self.trustedRemoteAccountForNick(target);
        return dmHistoryKey(conn.session.displayName(), conn.session.account(), target, peer_account, out) orelse target;
    }

    const HistoryView = enum { allow, hidden, policy };

    /// Same channel visibility CHATHISTORY uses. A non-channel target is a
    /// direct-message key built from the caller, not a network-wide read.
    fn historyView(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, target: []const u8) HistoryView {
        if (!world_model.isChannelName(target)) return .allow;
        const wid = worldIdFromClient(id);
        const channel_exists = self.world.channelExists(target);
        const is_member = self.world.isMember(target, wid);
        const is_visible = channel_exists and
            !self.world.channelHasFlag(target, .secret) and
            !self.world.isPrivate(target) and
            !self.world.isHidden(target);
        if (!chathistory_cmd.channelHistoryTargetAllowed(channel_exists, is_member, is_visible)) return .hidden;
        if (!self.historyPolicyAllows(target, is_member, conn.session.isOper())) return .policy;
        return .allow;
    }

    fn ensureChathistoryTargetVisible(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, target: []const u8) !bool {
        switch (self.historyView(id, conn, target)) {
            .allow => return true,
            .policy => {
                self.publishHistoryPolicyDeny(target, conn);
                try self.failReply(conn, "CHATHISTORY", "ACCESS_DENIED", "Cannot access channel history");
                return false;
            },
            .hidden => {
                try self.failReply(conn, "CHATHISTORY", "ACCESS_DENIED", "Cannot access channel history");
                return false;
            },
        }
    }

    /// Bodies the live account can already read with CHATHISTORY. A missing
    /// session or a failed visibility check is a denial, not an empty room.
    pub fn readAccountHistory(self: *LinuxServer, account: []const u8, target: []const u8, out: []lotus.Message) error{Denied}![]const lotus.Message {
        const live = self.connForAccount(account) orelse return error.Denied;
        if (self.historyView(live.id, live.conn, target) != .allow) return error.Denied;
        if (world_model.isChannelName(target)) {
            if (self.accountIsGatedBot(account) and !self.bot_grants.allows(account, .history, target, self.grantNowU64())) return error.Denied;
        }
        var key_buf: [320]u8 = undefined;
        const store_target = self.historyKeyForTarget(live.conn, target, &key_buf);
        return self.history.latest(store_target, out.len, out) catch return error.Denied;
    }

    fn connForAccount(self: *LinuxServer, account: []const u8) ?struct { id: client_model.ClientId, conn: *ConnState } {
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                const acct = entry.value.session.account() orelse continue;
                if (std.ascii.eqlIgnoreCase(acct, account)) return .{ .id = entry.id, .conn = entry.value };
            }
        }
        return null;
    }

    fn historyRealtimeMs() u64 {
        return @intCast(@max(@as(i64, 0), platform.realtimeMillis()));
    }

    fn indexHistoryBody(self: *LinuxServer, msgid: []const u8, text: []const u8, tags: ?[]const u8) void {
        if (e2ee_policy.encryptedTagPresent(tags)) return;
        if (std.mem.startsWith(u8, text, e2ee_policy.room_envelope_prefix)) return;
        self.search_index.index(msgid, text) catch {};
    }

    fn persistHistoryRecord(
        self: *LinuxServer,
        target: []const u8,
        msgid: []const u8,
        sender: []const u8,
        text: []const u8,
        timestamp_ms: u64,
        command: []const u8,
        tags: ?[]const u8,
    ) void {
        const svc = self.account_services orelse return;
        history_durable.append(svc.store, .{
            .target = target,
            .msgid = msgid,
            .sender = sender,
            .text = text,
            .timestamp = timestamp_ms,
            .command = command,
            .client_tags = tags orelse "",
        }) catch |err| {
            srvLog("onyx-server: history durable append failed ({s})\n", .{@errorName(err)});
        };
    }

    fn storeOfflineMemo(self: *LinuxServer, account: []const u8, from: []const u8, text: []const u8, now_ms: i64) !usize {
        // Reject a row that cannot fit the durable wire or configured store
        // record before accepting it into RAM, even if MemoBox limits rose.
        if (self.account_services) |svc|
            memo_durable.validateRowForStore(svc.store, account, from, text) catch return error.MessageInvalid;
        const n = try self.memo.send(account, from, text, now_ms);
        if (self.account_services) |svc| {
            // Once an append failed, another append can succeed while leaving
            // the earlier accepted message out of the durable generation.
            if (self.memo_durable_dirty) {
                self.snapshotDurableMemos(self.nowMs());
            } else {
                memo_durable.append(svc.store, account, from, text, now_ms) catch |err| {
                    self.memo_durable_dirty = true;
                    self.memo_durable_retry_after_ms = self.nowMs() +| 60_000;
                    srvLog("onyx-server: memo durable append failed ({s})\n", .{@errorName(err)});
                };
            }
        }
        return n;
    }

    fn snapshotDurableMemos(self: *LinuxServer, now_ms: i64) void {
        const svc = self.account_services orelse return;
        memo_durable.replaceAll(svc.store, &self.memo) catch |err| {
            self.memo_durable_dirty = true;
            self.memo_durable_retry_after_ms = now_ms +| 60_000;
            srvLog("onyx-server: memo durable snapshot failed ({s})\n", .{@errorName(err)});
            return;
        };
        self.memo_durable_dirty = false;
        self.memo_durable_retry_after_ms = 0;
    }

    fn retryDirtyDurableMemos(self: *LinuxServer) void {
        if (!self.memo_durable_dirty or self.account_services == null) return;
        const now = self.nowMs();
        if (now < self.memo_durable_retry_after_ms) return;
        self.snapshotDurableMemos(now);
    }

    fn clearOfflineMemo(self: *LinuxServer, account: []const u8) usize {
        const n = self.memo.clear(account);
        self.snapshotDurableMemos(self.nowMs());
        return n;
    }

    fn rememberReadMarker(
        self: *LinuxServer,
        owner: []const u8,
        target: []const u8,
        timestamp: read_marker_store.Timestamp,
    ) !read_marker_store.SetResult {
        if (self.read_marker_unavailable) return error.ReadMarkerUnavailable;
        var target_buf: [read_marker_store.default_max_target_bytes]u8 = undefined;
        const canonical_target = try canonicalReadMarkerTarget(target, &target_buf);
        var prepared = try self.read_markers.prepareSet(owner, canonical_target, timestamp);
        defer prepared.deinit();
        if (prepared.result.changed) {
            if (self.account_services) |svc| {
                svc.lock.lockExclusive();
                defer svc.lock.unlockExclusive();
                var durable = try marker_durable.preparePut(svc.store, owner, canonical_target, prepared.result.timestamp, null);
                defer durable.deinit();
                durable.commit() catch |err| {
                    if (svc.store.preparedWritesPoisoned()) self.read_marker_unavailable = true;
                    return err;
                };
            }
        }
        const result = prepared.commit();
        if (result.changed) {
            var key_buf: [read_marker_store.default_max_owner_bytes + 1 + read_marker_store.default_max_target_bytes]u8 = undefined;
            if (self.read_marker_facts.fetchRemove(readMarkerFactKey(owner, canonical_target, &key_buf))) |removed| {
                self.allocator.free(removed.key);
                self.allocator.free(removed.value);
            }
        }
        return result;
    }

    const read_marker_prop_prefix = "read.marker/";
    const read_marker_wire_max = 512;
    const ReadMarkerFactMap = std.StringHashMapUnmanaged([]u8);

    fn isReadMarkerPropKey(key: []const u8) bool {
        return key.len >= read_marker_prop_prefix.len and
            std.ascii.eqlIgnoreCase(key[0..read_marker_prop_prefix.len], read_marker_prop_prefix);
    }

    fn readMarkerOwner(conn: *const ConnState, out: *[read_marker_store.default_max_owner_bytes]u8) ![]const u8 {
        if (conn.session.account()) |account| {
            const canonical = try services_mod.canonicalAccount(account);
            const owner = canonical.asSlice();
            @memcpy(out[0..owner.len], owner);
            return out[0..owner.len];
        }
        const physical: u64 = @bitCast(idFromToken(conn.token));
        return std.fmt.bufPrint(out, "n:{x:0>16}", .{physical});
    }

    fn clearGuestReadMarkers(self: *LinuxServer, conn: *const ConnState) void {
        var owner_buf: [read_marker_store.default_max_owner_bytes]u8 = undefined;
        const physical: u64 = @bitCast(idFromToken(conn.token));
        const owner = std.fmt.bufPrint(&owner_buf, "n:{x:0>16}", .{physical}) catch unreachable;
        var it = self.read_markers.entries.iterator();
        while (it.next()) |entry| {
            const key = entry.key_ptr.*;
            if (key.len <= owner.len or key[owner.len] != 0 or !std.mem.eql(u8, key[0..owner.len], owner)) continue;
            _ = self.read_markers.entries.remove(key);
            self.allocator.free(key);
        }
    }

    fn canonicalReadMarkerTarget(target: []const u8, out: *[read_marker_store.default_max_target_bytes]u8) ![]const u8 {
        // Keep the established store's ASCII target folding. Do not silently
        // introduce a different nick/channel casemap into persisted keys.
        if (target.len == 0 or target.len > out.len) return error.InvalidTarget;
        for (target, 0..) |byte, i| {
            if (byte <= 0x20 or byte == 0x7f or byte == ',' or byte == ':') return error.InvalidTarget;
            out[i] = std.ascii.toLower(byte);
        }
        return out[0..target.len];
    }

    fn readMarkerPropKey(target: []const u8, out: *[entity_prop_event.max_key_len]u8) []const u8 {
        var digest: [32]u8 = undefined;
        std.crypto.hash.Blake3.hash(target, &digest, .{});
        @memcpy(out[0..read_marker_prop_prefix.len], read_marker_prop_prefix);
        const encoded = base64url.encode(out[read_marker_prop_prefix.len..], &digest) catch unreachable;
        return out[0 .. read_marker_prop_prefix.len + encoded.len];
    }

    fn readMarkerFactKey(owner: []const u8, target: []const u8, out: []u8) []const u8 {
        @memcpy(out[0..owner.len], owner);
        out[owner.len] = 0;
        @memcpy(out[owner.len + 1 ..][0..target.len], target);
        return out[0 .. owner.len + 1 + target.len];
    }

    fn deinitReadMarkerFacts(self: *LinuxServer, facts: *ReadMarkerFactMap) void {
        var it = facts.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        facts.deinit(self.allocator);
        facts.* = .empty;
    }

    const StagedReadMarkerFact = struct {
        key: ?[]u8,
        wire: ?[]u8,

        fn deinit(self: *StagedReadMarkerFact, allocator: std.mem.Allocator) void {
            if (self.key) |key| allocator.free(key);
            if (self.wire) |wire| allocator.free(wire);
            self.* = .{ .key = null, .wire = null };
        }

        fn commit(self: *StagedReadMarkerFact, server: *LinuxServer) void {
            const key = self.key.?;
            const slot = server.read_marker_facts.getOrPutAssumeCapacity(key);
            if (slot.found_existing) {
                server.allocator.free(key);
                server.allocator.free(slot.value_ptr.*);
            }
            slot.value_ptr.* = self.wire.?;
            self.* = .{ .key = null, .wire = null };
        }
    };

    fn stageReadMarkerFact(self: *LinuxServer, owner: []const u8, target: []const u8, wire: []const u8) !StagedReadMarkerFact {
        var key_buf: [read_marker_store.default_max_owner_bytes + 1 + read_marker_store.default_max_target_bytes]u8 = undefined;
        const key = readMarkerFactKey(owner, target, &key_buf);
        if (!self.read_marker_facts.contains(key)) {
            if (self.read_marker_facts.count() >= read_marker_store.default_max_entries) return error.TargetLimitExceeded;
            try self.read_marker_facts.ensureUnusedCapacity(self.allocator, 1);
        }
        const owned_key = try self.allocator.dupe(u8, key);
        errdefer self.allocator.free(owned_key);
        const owned_wire = try self.allocator.dupe(u8, wire);
        return .{ .key = owned_key, .wire = owned_wire };
    }

    const ParsedReadMarkerFact = struct {
        owner: []const u8,
        target: []const u8,
        timestamp: read_marker_store.Timestamp,
    };

    fn validateReadMarkerFact(self: *LinuxServer, event: entity_prop_event.EntityPropEvent) !ParsedReadMarkerFact {
        if (event.kind != .user or !event.present or event.hlc == 0 or event.value.len <= 25 or event.value[24] != ' ')
            return error.BadReadMarkerFact;
        const account = try services_mod.canonicalAccount(event.entity);
        if (!std.mem.eql(u8, account.asSlice(), event.entity) or !std.mem.eql(u8, event.owner, event.entity))
            return error.BadReadMarkerFact;
        const timestamp = try read_marker_store.Timestamp.parseWire(event.value[0..24]);
        const target = event.value[25..];
        var target_buf: [read_marker_store.default_max_target_bytes]u8 = undefined;
        const canonical_target = try canonicalReadMarkerTarget(target, &target_buf);
        if (!std.mem.eql(u8, target, canonical_target)) return error.BadReadMarkerFact;
        var key_buf: [entity_prop_event.max_key_len]u8 = undefined;
        if (!std.mem.eql(u8, event.key, readMarkerPropKey(target, &key_buf))) return error.BadReadMarkerFact;
        if (try entity_prop_event.verifyOrigin(self.allocator, event) != .verified) return error.BadReadMarkerFact;
        // The secured mesh carrier authorizes transit origins; the signature
        // binds their complete self-certifying identity. Our own short id must
        // additionally match our full configured key, as on MESSAGE_V2.
        if (event.origin_node == self.config.node_id) {
            const identity = self.config.node_identity orelse return error.BadReadMarkerFact;
            if (!std.mem.eql(u8, event.origin_pubkey, &identity.sign_kp.public_key)) return error.BadReadMarkerFact;
        }
        return .{ .owner = event.entity, .target = target, .timestamp = timestamp };
    }

    fn commitAccountReadMarker(self: *LinuxServer, owner: []const u8, raw_target: []const u8, timestamp: read_marker_store.Timestamp) !read_marker_store.SetResult {
        if (self.read_marker_unavailable) return error.ReadMarkerUnavailable;
        const svc = self.account_services orelse return error.ReadMarkerUnavailable;
        var target_buf: [read_marker_store.default_max_target_bytes]u8 = undefined;
        const target = try canonicalReadMarkerTarget(raw_target, &target_buf);
        const identity = self.config.node_identity orelse return self.rememberReadMarker(owner, target, timestamp);
        var prepared = try self.read_markers.prepareSet(owner, target, timestamp);
        defer prepared.deinit();
        var fact_key_buf: [read_marker_store.default_max_owner_bytes + 1 + read_marker_store.default_max_target_bytes]u8 = undefined;
        const fact_key = readMarkerFactKey(owner, target, &fact_key_buf);
        if (!prepared.result.changed) {
            // Legacy rows have no authenticated author. Only an explicit SET of
            // that exact (or newer) position may promote one to a signed fact.
            if (self.read_marker_facts.contains(fact_key) or
                !std.mem.eql(u8, timestamp.slice(), prepared.result.timestamp.slice())) return prepared.commit();
        }
        var clock_candidate = self.read_marker_clock;
        if (clock_candidate.last_stamp == std.math.maxInt(u64)) return error.ClockExhausted;
        const hlc = clock_candidate.stamp(self.meshWallMs(), 0);
        var key_buf: [entity_prop_event.max_key_len]u8 = undefined;
        const key = readMarkerPropKey(target, &key_buf);
        var value_buf: [25 + read_marker_store.default_max_target_bytes]u8 = undefined;
        @memcpy(value_buf[0..24], prepared.result.timestamp.slice());
        value_buf[24] = ' ';
        @memcpy(value_buf[25..][0..target.len], target);
        var event = entity_prop_event.EntityPropEvent{
            .kind = .user,
            .present = true,
            .origin_node = identity.shortId(),
            .hlc = hlc,
            .entity = owner,
            .key = key,
            .value = value_buf[0 .. 25 + target.len],
            .owner = owner,
        };
        var public_key: [entity_prop_event.pubkey_len]u8 = undefined;
        var signature: [entity_prop_event.sig_len]u8 = undefined;
        const transcript = try entity_prop_event.originTranscript(self.allocator, event);
        defer self.allocator.free(transcript);
        try entity_prop_event.signInPlace(&event, &identity.sign_kp, transcript, &public_key, &signature);
        var wire_buf: [read_marker_wire_max]u8 = undefined;
        const wire = try entity_prop_event.encode(event, &wire_buf);
        var staged = try self.stageReadMarkerFact(owner, target, wire);
        defer staged.deinit(self.allocator);
        {
            svc.lock.lockExclusive();
            defer svc.lock.unlockExclusive();
            var durable = try marker_durable.preparePutWithClock(svc.store, owner, target, prepared.result.timestamp, wire, hlc);
            defer durable.deinit();
            durable.commit() catch |err| {
                if (svc.store.preparedWritesPoisoned()) self.read_marker_unavailable = true;
                return err;
            };
        }
        const result = prepared.commit();
        staged.commit(self);
        self.read_marker_clock = clock_candidate;
        // The entire signed frontier is retained independently of every send.
        self.announceReadMarker(event);
        return result;
    }

    fn admitRemoteReadMarker(self: *LinuxServer, change: anytype) !void {
        if (self.read_marker_unavailable) return error.ReadMarkerUnavailable;
        const event = entity_prop_event.EntityPropEvent{
            .kind = change.kind,
            .present = change.present,
            .origin_node = change.origin_node,
            .hlc = change.hlc,
            .entity = change.entity,
            .key = change.key,
            .value = change.value,
            .owner = change.owner,
            .origin_pubkey = change.origin_pubkey,
            .origin_sig = change.origin_sig,
        };
        const parsed = try self.validateReadMarkerFact(event);
        var clock_candidate = self.read_marker_clock;
        try clock_candidate.observeChecked(event.hlc, self.meshWallMs(), mesh_clock_mod.default_max_future_skew_ms);
        var prepared = try self.read_markers.prepareSet(parsed.owner, parsed.target, parsed.timestamp);
        defer prepared.deinit();
        if (!std.mem.eql(u8, parsed.timestamp.slice(), prepared.result.timestamp.slice())) return;
        var wire_buf: [read_marker_wire_max]u8 = undefined;
        const wire = try entity_prop_event.encode(event, &wire_buf);
        var fact_key_buf: [read_marker_store.default_max_owner_bytes + 1 + read_marker_store.default_max_target_bytes]u8 = undefined;
        const fact_key = readMarkerFactKey(parsed.owner, parsed.target, &fact_key_buf);
        if (!prepared.result.changed) {
            if (self.read_marker_facts.get(fact_key)) |stored| {
                // Equal read positions select one immutable signed winner in a
                // deterministic order; duplicate repair never repeats delivery.
                if (std.mem.order(u8, wire, stored) != .gt) return;
            }
        }
        var staged = try self.stageReadMarkerFact(parsed.owner, parsed.target, wire);
        defer staged.deinit(self.allocator);
        const svc = self.account_services orelse return error.ReadMarkerUnavailable;
        {
            svc.lock.lockExclusive();
            defer svc.lock.unlockExclusive();
            var durable = try marker_durable.preparePutWithClock(svc.store, parsed.owner, parsed.target, parsed.timestamp, wire, clock_candidate.last_stamp);
            defer durable.deinit();
            durable.commit() catch |err| {
                if (svc.store.preparedWritesPoisoned()) self.read_marker_unavailable = true;
                return err;
            };
        }
        const result = prepared.commit();
        staged.commit(self);
        self.read_marker_clock = clock_candidate;
        if (result.changed) self.publishAccountReadMarker(parsed.owner, parsed.target, result.timestamp, null);
        self.announceReadMarker(event);
    }

    fn publishAccountReadMarker(self: *LinuxServer, account: []const u8, target: []const u8, timestamp: read_marker_store.Timestamp, excluded: ?*ConnState) void {
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = read_marker_store.buildTimestampResponse(target, timestamp, &line_buf) catch return;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or slot.value.closing or slot.value.s2s != null or slot.value.s2s_secured != null) continue;
                if (excluded) |origin| if (&slot.value == origin) continue;
                if (!slot.value.session.hasCap(.read_marker)) continue;
                const attached_account = slot.value.session.account() orelse continue;
                if (!std.ascii.eqlIgnoreCase(account, attached_account)) continue;
                // One pass over physical slots preserves every same-token
                // attachment. Cross-reactor delivery uses its owning mailbox.
                self.enqueueDelivery(slotClientId(reactor, i, slot.gen), line) catch {};
            }
        }
    }

    fn announceReadMarker(self: *LinuxServer, event: entity_prop_event.EntityPropEvent) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.supportsReadMarkers()) continue;
                link.sendEntityProp(event.kind, event.entity, event.key, event.value, event.owner, event.hlc, event.present, .{ .node = event.origin_node, .pubkey = event.origin_pubkey, .sig = event.origin_sig }) catch continue;
                _ = self.flushSecuredS2sOutboundTo(slotClientId(reactor, i, slot.gen), link);
            }
        }
    }

    fn sendReadMarkerBurstTo(self: *LinuxServer, conn: *ConnState) bool {
        if (!conn.isActiveMeshPeer()) return false;
        if (self.read_marker_unavailable) return true;
        const link = conn.s2s_secured orelse return true;
        if (!link.supportsReadMarkers()) return true;
        var it = self.read_marker_facts.valueIterator();
        while (it.next()) |wire| {
            const event = entity_prop_event.decode(wire.*) catch return false;
            link.sendEntityProp(event.kind, event.entity, event.key, event.value, event.owner, event.hlc, event.present, .{ .node = event.origin_node, .pubkey = event.origin_pubkey, .sig = event.origin_sig }) catch return false;
        }
        return true;
    }

    fn restoreDurableMarkers(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        self.restoreReadMarkerCandidate(svc) catch |err| {
            self.read_marker_unavailable = true;
            srvLog("onyx-server: read-marker durable restore failed closed ({s})\n", .{@errorName(err)});
        };
    }

    fn restoreReadMarkerCandidate(self: *LinuxServer, svc: *services_mod.Services) !void {
        svc.lock.lockExclusive();
        defer svc.lock.unlockExclusive();
        var candidate = try marker_durable.stageRestore(svc.store, self.allocator);
        defer candidate.deinit();
        var facts: ReadMarkerFactMap = .empty;
        defer self.deinitReadMarkerFacts(&facts);
        if (candidate.clock == std.math.maxInt(u64)) return error.BadReadMarkerFact;
        for (candidate.rows.items) |row| {
            const wire = row.fact_wire orelse continue;
            if (wire.len > read_marker_wire_max) return error.BadReadMarkerFact;
            const event = try entity_prop_event.decode(wire);
            const parsed = try self.validateReadMarkerFact(event);
            if (!std.mem.eql(u8, parsed.owner, row.owner) or !std.mem.eql(u8, parsed.target, row.target) or
                !std.mem.eql(u8, parsed.timestamp.slice(), row.timestamp.slice()) or event.hlc > candidate.clock)
                return error.BadReadMarkerFact;
            const restored = (try candidate.markers.get(row.owner, row.target)) orelse return error.BadReadMarkerFact;
            if (!std.mem.eql(u8, restored.slice(), row.timestamp.slice())) return error.BadReadMarkerFact;
            var canonical_wire: [read_marker_wire_max]u8 = undefined;
            if (!std.mem.eql(u8, wire, try entity_prop_event.encode(event, &canonical_wire))) return error.BadReadMarkerFact;
            var key_buf: [read_marker_store.default_max_owner_bytes + 1 + read_marker_store.default_max_target_bytes]u8 = undefined;
            const key = try self.allocator.dupe(u8, readMarkerFactKey(row.owner, row.target, &key_buf));
            errdefer self.allocator.free(key);
            const owned_wire = try self.allocator.dupe(u8, wire);
            errdefer self.allocator.free(owned_wire);
            try facts.put(self.allocator, key, owned_wire);
        }
        std.mem.swap(read_marker_store.DefaultStore, &self.read_markers, &candidate.markers);
        std.mem.swap(ReadMarkerFactMap, &self.read_marker_facts, &facts);
        self.read_marker_clock = .{ .last_stamp = candidate.clock, .last_physical = mesh_clock_mod.MeshClock.physicalOf(candidate.clock) };
        self.read_marker_unavailable = false;
    }

    fn recordGag(self: *LinuxServer, ip: []const u8) void {
        self.gags.add(ip) catch return;
        self.snapshotGags();
    }

    fn forgetGag(self: *LinuxServer, ip: []const u8) void {
        if (!self.gags.remove(ip)) return;
        self.snapshotGags();
    }

    fn snapshotGags(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        gag_durable.replaceAll(svc.store, &self.gags) catch |err| {
            srvLog("onyx-server: gag durable snapshot failed ({s})\n", .{@errorName(err)});
        };
    }

    fn restoreDurableGags(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        gag_durable.restoreInto(svc.store, &self.gags) catch |err| {
            srvLog("onyx-server: gag durable restore failed closed ({s})\n", .{@errorName(err)});
        };
    }

    pub fn snapshotShuns(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        abuse_durable.replaceShuns(svc.store, &self.shuns) catch |err| {
            srvLog("onyx-server: shun durable snapshot failed ({s})\n", .{@errorName(err)});
        };
    }

    pub fn snapshotSpamtraps(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        var nicks: std.ArrayListUnmanaged([]u8) = .empty;
        var chans: std.ArrayListUnmanaged([]u8) = .empty;
        defer {
            for (nicks.items) |name| self.allocator.free(name);
            for (chans.items) |name| self.allocator.free(name);
            nicks.deinit(self.allocator);
            chans.deinit(self.allocator);
        }
        lockSpin(&self.spamtrap_mu);
        const copied = self.spamtrap.dupeTrapNames(self.allocator, &nicks, &chans);
        self.spamtrap_mu.unlock();
        copied catch |err| {
            srvLog("onyx-server: spamtrap durable copy failed ({s})\n", .{@errorName(err)});
            return;
        };
        abuse_durable.replaceSpam(svc.store, nicks.items, chans.items) catch |err| {
            srvLog("onyx-server: spamtrap durable snapshot failed ({s})\n", .{@errorName(err)});
        };
    }

    fn snapshotKoshi(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        abuse_durable.replaceKoshi(svc.store, &self.content_filter) catch |err| {
            srvLog("onyx-server: koshi durable snapshot failed ({s})\n", .{@errorName(err)});
        };
    }

    pub fn snapshotReputation(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        const rows = self.reputation.dupeRows(self.allocator) catch |err| {
            srvLog("onyx-server: reputation durable copy failed ({s})\n", .{@errorName(err)});
            return;
        };
        defer self.allocator.free(rows);
        abuse_durable.replaceReputation(svc.store, rows) catch |err| {
            srvLog("onyx-server: reputation durable snapshot failed ({s})\n", .{@errorName(err)});
        };
    }

    fn snapshotAccountAbuse(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        abuse_durable.replaceAccounts(svc.store, &self.account_abuse) catch |err| {
            srvLog("onyx-server: account abuse snapshot failed ({s})\n", .{@errorName(err)});
        };
    }

    fn restoreDurableAbuse(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        abuse_durable.restoreShuns(svc.store, &self.shuns) catch |err| {
            srvLog("onyx-server: shun durable restore failed closed ({s})\n", .{@errorName(err)});
        };
        if (abuse_durable.restoreSpam(svc.store, &self.spamtrap)) {
            self.spamtrap_active.store(self.spamtrap.trapNickCount() + self.spamtrap.trapChannelCount() > 0, .release);
        } else |err| {
            srvLog("onyx-server: spamtrap durable restore failed closed ({s})\n", .{@errorName(err)});
        }
        abuse_durable.restoreKoshi(svc.store, &self.content_filter) catch |err| {
            srvLog("onyx-server: koshi durable restore failed closed ({s})\n", .{@errorName(err)});
        };
        abuse_durable.restoreReputation(svc.store, &self.reputation) catch |err| {
            srvLog("onyx-server: reputation durable restore failed closed ({s})\n", .{@errorName(err)});
        };
        abuse_durable.restoreAccounts(svc.store, &self.account_abuse) catch |err| {
            srvLog("onyx-server: account abuse restore failed closed ({s})\n", .{@errorName(err)});
        };
    }

    /// Bump the account axis when the connection guard throttles or disconnects.
    /// A missing account leaves the score untouched. The connection guard itself
    /// is not written.
    fn noteAccountAbuse(self: *LinuxServer, conn: *ConnState) void {
        const account = conn.session.account() orelse return;
        _ = self.account_abuse.note(account) catch |err| {
            srvLog("onyx-server: account abuse note failed ({s})\n", .{@errorName(err)});
            return;
        };
        self.snapshotAccountAbuse();
    }

    pub fn liveConnByNick(self: *LinuxServer, nick: []const u8) ?*ConnState {
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                if (std.ascii.eqlIgnoreCase(entry.value.session.displayName(), nick)) return entry.value;
            }
        }
        return null;
    }

    pub fn shunMatchesConn(self: *LinuxServer, conn: *ConnState) bool {
        const now = self.nowMs();
        const nick = conn.session.displayName();
        if (nick.len > 0 and self.shuns.isShunned(nick, now)) return true;
        const ip = conn.session.realHost();
        if (ip.len > 0 and self.shuns.isShunned(ip, now)) return true;
        var hm_buf: [320]u8 = undefined;
        if (clientPrefix(conn, &hm_buf)) |hm| {
            if (self.shuns.isShunned(hm, now)) return true;
        } else |_| {}
        return false;
    }

    /// `ABUSE <nick>` — oper explanation, from current RAM, of why a live
    /// connection was throttled, shunned, DNSBL-marked, or reputation-decayed.
    /// The account score is reported beside the connection guard, not instead of it.
    pub fn handleAbuse(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleAbuse(self, conn, parsed);
    }

    fn grantDurablePersona(self: *LinuxServer, account: []const u8, name: []const u8, host: []const u8, source: guise_mod.Source) !void {
        try self.guises.grant(account, name, host, source, self.nowMs());
        self.snapshotVhosts();
    }

    fn claimDurablePersona(self: *LinuxServer, account: []const u8, host: []const u8) !guise_mod.Offer {
        const offer = try self.guises.claim(account, host, self.nowMs());
        self.snapshotVhosts();
        return offer;
    }

    fn addDurableOffer(self: *LinuxServer, template: []const u8, label: []const u8) !void {
        try self.guises.addOffer(template, label);
        self.snapshotVhosts();
    }

    fn snapshotVhosts(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        vhost_durable.replaceAll(svc.store, &self.guises) catch |err| {
            srvLog("onyx-server: vhost durable snapshot failed ({s})\n", .{@errorName(err)});
        };
    }

    fn restoreDurableVhosts(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        vhost_durable.restoreInto(svc.store, &self.guises) catch |err| {
            srvLog("onyx-server: vhost durable restore failed closed ({s})\n", .{@errorName(err)});
        };
    }

    fn persistProofChain(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        const blob = self.oper_audit.writeChain(self.allocator) catch |err| {
            srvLog("onyx-server: proof chain snapshot failed ({s})\n", .{@errorName(err)});
            return;
        };
        defer self.allocator.free(blob);
        svc.store.put(.props, svc_operaudit.chain_store_key, blob) catch |err| {
            srvLog("onyx-server: proof chain snapshot failed ({s})\n", .{@errorName(err)});
        };
    }

    fn restoreProofChain(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        const blob = svc.store.get(.props, svc_operaudit.chain_store_key) orelse return;
        self.oper_audit.readChain(blob) catch |err| {
            srvLog("onyx-server: proof chain restore failed closed ({s})\n", .{@errorName(err)});
            self.oper_audit.markChainBroken();
        };
    }

    fn sealProofChain(self: *LinuxServer) void {
        const head = self.oper_audit.chainHead() orelse return;
        const kp = self.meshSignKey() orelse return;
        const msg = svc_operaudit.chainHeadMessage(head);
        const sig = kp.sign(&msg, null) catch return;
        self.oper_audit.seal(head, sig.toBytes(), kp.public_key.toBytes());
    }

    fn restoreDurableMemos(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        memo_durable.restoreInto(svc.store, &self.memo) catch |err| {
            srvLog("onyx-server: memo durable restore failed closed ({s})\n", .{@errorName(err)});
        };
    }

    fn restoreDurableHistory(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        history_durable.restoreInto(HistoryStore, svc.store, &self.history, &self.search_index) catch |err| {
            srvLog("onyx-server: history durable restore failed closed ({s})\n", .{@errorName(err)});
            return;
        };
        self.rebuildThreadsFromHistory();
    }

    /// The native candidate reads the predecessor's WAL without mutation.
    /// Hold World after every socket owner and producer reaches the seal cut;
    /// publish the canonical durable image before either history capsule is
    /// encoded. A failed write refuses the handoff and leaves its serving
    /// predecessor and accepted in-memory history in place.
    fn prepareNativeDurableHistoryUpgradeBoundary(self: *LinuxServer) !void {
        const svc = self.account_services orelse return;
        try history_durable.replaceAll(HistoryStore, svc.store, &self.history);
    }

    fn snapshotDurableHistory(self: *LinuxServer) void {
        const svc = self.account_services orelse return;
        history_durable.replaceAll(HistoryStore, svc.store, &self.history) catch |err| {
            srvLog("onyx-server: history durable snapshot failed ({s})\n", .{@errorName(err)});
        };
    }

    /// Record a message into the CHATHISTORY ring (Lotus) at an explicit event
    /// timestamp. Stable mesh events pass the physical lane of the same HLC that
    /// minted their msgid/live server-time, keeping replay byte-identical even
    /// when the store write happens later.
    fn recordHistoryAt(
        self: *LinuxServer,
        store_target: []const u8,
        conn: *ConnState,
        msgid: []const u8,
        command: []const u8,
        text: []const u8,
        client_tags: ?[]const u8,
        timestamp_ms: u64,
    ) void {
        var prefix_buf: [256]u8 = undefined;
        const sender = clientPrefix(conn, &prefix_buf) catch return;
        _ = self.history.append(store_target, .{
            .msgid = msgid,
            .sender = sender,
            .text = text,
            .timestamp = timestamp_ms,
            .command = command,
            .client_tags = client_tags,
        }) catch {};
        self.persistHistoryRecord(store_target, msgid, sender, text, timestamp_ms, command, client_tags);
        self.noteThreadFromTags(msgid, client_tags);
        // Forward-index the message body for draft/search (word -> msgid). Bounded
        // by the index Config (max words/ids/token bytes); oversize indexes are a
        // best-effort drop, never an error to the sender. msgid uniquely keys the
        // entry; `handleSearch` re-scopes a hit to a target's own history.
        // E2EE ciphertext stays in the ring and is not indexed as text.
        self.indexHistoryBody(msgid, text, client_tags);
        self.chanstatsMessage(store_target, sender, command, text);
    }

    fn tagmsgHistoryEligible(tags: []const u8) bool {
        return findTagValue(tags, "+typing") != null or
            findTagValue(tags, "+draft/typing") != null or
            findTagValue(tags, "+draft/react") != null or
            findTagValue(tags, "+draft/unreact") != null;
    }

    /// Record an INCOMING relayed channel message into the CHATHISTORY ring, so
    /// cross-node CHATHISTORY works (a member who reads back history on THIS node
    /// sees messages authored on a peer). Unlike `recordHistory` the sender is a
    /// ready-made prefix string (the relay carries `source_prefix`, not a local
    /// `ConnState`). Mirrors the locally-originated record: same forward-index for
    /// draft/search. Locally-originated messages never reach here — `deliverRelay`
    /// drops our own `origin_node` via the relay seen-set before delivery.
    fn recordHistoryRelayAt(
        self: *LinuxServer,
        store_target: []const u8,
        sender_prefix: []const u8,
        msgid: []const u8,
        command: []const u8,
        text: []const u8,
        client_tags: ?[]const u8,
        timestamp_ms: u64,
    ) void {
        _ = self.history.append(store_target, .{
            .msgid = msgid,
            .sender = sender_prefix,
            .text = text,
            .timestamp = timestamp_ms,
            .command = command,
            .client_tags = client_tags,
        }) catch {};
        self.persistHistoryRecord(store_target, msgid, sender_prefix, text, timestamp_ms, command, client_tags);
        self.noteThreadFromTags(msgid, client_tags);
        self.indexHistoryBody(msgid, text, client_tags);
        self.chanstatsMessage(store_target, sender_prefix, command, text);
    }

    fn recordHistoryRelay(
        self: *LinuxServer,
        store_target: []const u8,
        sender_prefix: []const u8,
        msgid: []const u8,
        command: []const u8,
        text: []const u8,
        client_tags: ?[]const u8,
    ) void {
        self.recordHistoryRelayAt(store_target, sender_prefix, msgid, command, text, client_tags, historyRealtimeMs());
    }

    fn recordHistoryTagmsgAt(self: *LinuxServer, store_target: []const u8, conn: *ConnState, msgid: []const u8, tags: []const u8, timestamp_ms: u64) void {
        if (!tagmsgHistoryEligible(tags)) return;
        var prefix_buf: [256]u8 = undefined;
        const sender = clientPrefix(conn, &prefix_buf) catch return;
        _ = self.history.append(store_target, .{
            .msgid = msgid,
            .sender = sender,
            .text = "",
            .timestamp = timestamp_ms,
            .command = "TAGMSG",
            .client_tags = tags,
        }) catch {};
        self.persistHistoryRecord(store_target, msgid, sender, "", timestamp_ms, "TAGMSG", tags);
        self.noteThreadFromTags(msgid, tags);
    }

    /// A delivered message whose `+draft/reply` value passes the shipped msgid
    /// check joins that thread. Invalid values stay on the wire and do not
    /// create a thread. The tag itself is not removed here.
    fn noteThreadFromTags(self: *LinuxServer, msgid: []const u8, client_tags: ?[]const u8) void {
        const tags = client_tags orelse return;
        const raw = findTagValue(tags, draft_reply_relay.TAG_KEY) orelse return;
        const parent = draft_reply_relay.parse(raw) catch return;
        const reply = draft_reply_relay.parse(msgid) catch return;
        self.threads.noteReply(parent, reply) catch {};
    }

    /// Cold start has no Helix arena. Durable history already stored the reply
    /// tag, so the thread table is rebuilt from those rows, oldest first.
    fn rebuildThreadsFromHistory(self: *LinuxServer) void {
        self.threads.clear();
        var it = self.history.deterministicIterator();
        while (it.next()) |entry| {
            if (entry.message.tombstone) continue;
            self.noteThreadFromTags(entry.message.msgid, entry.message.client_tags);
        }
    }

    /// Record a draft/event-playback EVENT (a non-message channel action such as
    /// TOPIC) into the CHATHISTORY ring. Replays as `command` and is delivered
    /// only to clients that negotiated `event-playback`. A fresh msgid is minted
    /// (events carry no client msgid). `store_target` is the channel.
    fn recordHistoryEvent(self: *LinuxServer, store_target: []const u8, conn: *const ConnState, command: []const u8, text: []const u8) void {
        var prefix_buf: [256]u8 = undefined;
        const sender = clientPrefix(conn, &prefix_buf) catch return;
        self.recordHistoryEventSender(store_target, sender, command, text);
    }

    /// Like `recordHistoryEvent` but with an explicit sender prefix — used for
    /// cross-channel events (NICK uses the OLD prefix; QUIT records into every
    /// channel the leaver was in) where the prefix is not simply `conn`'s current
    /// identity at the call site.
    fn recordHistoryEventSender(self: *LinuxServer, store_target: []const u8, sender: []const u8, command: []const u8, text: []const u8) void {
        const ts: u64 = @intCast(@max(@as(i64, 0), platform.realtimeMillis()));
        var msgid_buf: [msgid_mod.id_len]u8 = undefined;
        const msgid = self.msgid_gen.next(&msgid_buf);
        _ = self.history.append(store_target, .{ .msgid = msgid, .sender = sender, .text = text, .timestamp = ts, .command = command }) catch {};
        self.persistHistoryRecord(store_target, msgid, sender, text, ts, command, null);
        self.chanstatsEvent(store_target, sender, command, text);
    }

    // ── channel-stats feed (native per-channel statistics engine) ────────────

    /// Bare nick from a `[:]nick!user@host` prefix; "" for a server source.
    fn nickFromPrefix(prefix: []const u8) []const u8 {
        var p = prefix;
        if (p.len != 0 and p[0] == ':') p = p[1..];
        if (std.mem.indexOfScalar(u8, p, '!')) |i| return p[0..i];
        // A bare server name (has a dot, no user@) is not a nick.
        if (std.mem.indexOfScalar(u8, p, '@') == null and std.mem.indexOfScalar(u8, p, '.') != null) return "";
        return p;
    }

    /// Feed a channel PRIVMSG into the per-channel stats aggregator. No-op unless
    /// channel stats are enabled and the target is a channel.
    fn chanstatsMessage(self: *LinuxServer, target: []const u8, sender_prefix: []const u8, command: []const u8, text: []const u8) void {
        if (self.config.chanstats_dir.len == 0) return;
        if (!world_model.isChannelName(target)) return;
        if (!std.ascii.eqlIgnoreCase(command, "PRIVMSG")) return;
        // Ephemeral rooms leave no persistent footprint: their messages must
        // not accumulate into the durable chanstats aggregate either.
        if (self.channelEphemeralTtlMs(target) != 0) return;
        const nick = nickFromPrefix(sender_prefix);
        if (nick.len == 0) return;
        self.chanstats.recordMessage(target, nick, text, platform.realtimeMillis());
    }

    /// Feed a channel membership/topic EVENT into the aggregator.
    fn chanstatsEvent(self: *LinuxServer, target: []const u8, sender_prefix: []const u8, command: []const u8, text: []const u8) void {
        if (self.config.chanstats_dir.len == 0) return;
        if (!world_model.isChannelName(target)) return;
        const now = platform.realtimeMillis();
        if (std.ascii.eqlIgnoreCase(command, "JOIN")) {
            self.chanstats.recordEvent(target, .join, now);
        } else if (std.ascii.eqlIgnoreCase(command, "PART")) {
            self.chanstats.recordEvent(target, .part, now);
        } else if (std.ascii.eqlIgnoreCase(command, "QUIT")) {
            self.chanstats.recordEvent(target, .quit, now);
        } else if (std.ascii.eqlIgnoreCase(command, "KICK")) {
            self.chanstats.recordEvent(target, .kick, now);
        } else if (std.ascii.eqlIgnoreCase(command, "TOPIC")) {
            self.chanstats.recordTopic(target, nickFromPrefix(sender_prefix), topicTextFromHistoryEvent(target, text), now);
        }
    }

    /// TOPIC history stores a complete IRC parameter body (`#channel :topic`),
    /// whereas mesh updates carry only the topic text. Normalize both forms
    /// before they reach the public statistics feed.
    fn topicTextFromHistoryEvent(target: []const u8, text: []const u8) []const u8 {
        var topic = text;
        var has_history_envelope = false;
        if (topic.len > target.len and
            std.ascii.eqlIgnoreCase(topic[0..target.len], target) and
            topic[target.len] == ' ')
        {
            topic = topic[target.len + 1 ..];
            has_history_envelope = true;
        }
        if (has_history_envelope and topic.len != 0 and topic[0] == ':') topic = topic[1..];
        return topic;
    }

    fn latestActivityInWindow(
        self: *LinuxServer,
        store_target: []const u8,
        query: chathistory_targets.TargetsQuery,
    ) ?u64 {
        if (query.to_ms < 0) return null;
        const lo: u64 = if (query.from_ms <= 0) 0 else @intCast(query.from_ms);
        const hi: u64 = @intCast(query.to_ms);
        var one: [1]lotus.Message = undefined;
        const found = self.history.before(store_target, hi +| 1, 1, &one) catch return null;
        if (found.len == 0) return null;
        if (found[0].timestamp < lo) return null;
        return found[0].timestamp;
    }

    fn historyMessageByMsgid(self: *LinuxServer, store_target: []const u8, msgid: []const u8) ?lotus.Message {
        var buf: [256]lotus.Message = undefined;
        const found = self.history.latest(store_target, buf.len, &buf) catch return null;
        for (found) |message| {
            if (msgedit.authorizationKeyMatches(message.msgid, msgid)) return message;
        }
        return null;
    }

    fn historyEntryIsTagmsg(command: []const u8) bool {
        return std.mem.eql(u8, command, "TAGMSG");
    }

    fn historyTagmsgVisibleTo(session: *const dispatch.ClientSession, message: lotus.Message) bool {
        const raw = message.client_tags orelse return false;
        var tag_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
        return clientTagsForSession(session, raw, &tag_buf).len != 0;
    }

    pub fn historyMessageVisibleTo(session: *const dispatch.ClientSession, message: lotus.Message) bool {
        if (message.tombstone) return false;
        if (historyEntryIsTagmsg(message.command)) return historyTagmsgVisibleTo(session, message);
        if (!session.hasCap(.event_playback) and historyEntryIsEvent(message.command)) return false;
        return true;
    }

    fn historyReplayHasVisible(conn: *ConnState, messages: []const lotus.Message) bool {
        for (messages) |message| {
            if (historyMessageVisibleTo(&conn.session, message)) return true;
        }
        return false;
    }

    fn renderHistoryReplay(
        self: *LinuxServer,
        conn: *ConnState,
        out: []u8,
        ref: []const u8,
        target: []const u8,
        messages: []const lotus.Message,
        topic_filter: ?[]const u8,
    ) ![]const u8 {
        // Ephemeral rooms: a channel with the EPHEMERAL prop set drops any
        // message older than its TTL from EVERY replay path (this is the single
        // funnel for CHATHISTORY, bouncer rewind and SEARCH), so the server
        // simply never re-serves expired content. The ring still bounds memory;
        // this makes the expiry policy authoritative on read.
        const floor: u64 = self.ephemeralFloorMs(target);
        var writer = std.Io.Writer.fixed(out);
        const use_batch = conn.session.hasCap(.batch);
        if (use_batch) try writer.print("BATCH +{s} chathistory {s}\r\n", .{ ref, target });
        for (messages) |message| {
            if (message.timestamp < floor) continue;
            // Named-conversation filter: when a topic label is requested, replay
            // only messages carrying a matching (decoded) `+onyx/topic` tag.
            // Absent filter => every message, byte-identical to before.
            if (topic_filter) |want| {
                var mbuf: [topic_tag.max_label_len]u8 = undefined;
                const have = if (message.client_tags) |ct| topic_tag.labelFromTags(ct, &mbuf) else null;
                if (have == null or !std.mem.eql(u8, have.?, want)) continue;
            }
            if (!historyMessageVisibleTo(&conn.session, message)) continue;
            try writeHistoryReplayLine(&writer, &conn.session, if (use_batch) ref else null, target, message);
        }
        if (use_batch) try writer.print("BATCH -{s}\r\n", .{ref});
        return writer.buffered();
    }

    /// Render a complete bounded replay without imposing the old fixed 32 KiB
    /// aggregate ceiling.  One admitted history row can contain a 4096-byte
    /// room envelope plus replay-visible client tags and prefixes, so several
    /// valid rows legitimately exceed that legacy scratch buffer.  Query row
    /// counts are already bounded (64 for CHATHISTORY/rewind, 50 for SEARCH);
    /// reserve two ordinary reply frames per row to cover the largest legal
    /// line, plus batch framing.  The caller owns and must free the allocation.
    pub fn renderHistoryReplayOwned(
        self: *LinuxServer,
        conn: *ConnState,
        ref: []const u8,
        target: []const u8,
        messages: []const lotus.Message,
        topic_filter: ?[]const u8,
    ) ![]u8 {
        const max_replay_rows: usize = 64;
        if (messages.len > max_replay_rows) return error.OutputTooSmall;
        const capacity = std.math.add(
            usize,
            default_reply_bytes,
            try std.math.mul(usize, messages.len, default_reply_bytes * 2),
        ) catch return error.OutputTooSmall;
        const scratch = try self.allocator.alloc(u8, capacity);
        errdefer self.allocator.free(scratch);
        const rendered = try self.renderHistoryReplay(conn, scratch, ref, target, messages, topic_filter);
        const owned = try self.allocator.dupe(u8, rendered);
        self.allocator.free(scratch);
        return owned;
    }

    /// Enqueue a rendered replay one complete IRC line at a time.  The replay
    /// may legitimately exceed the daemon's 8 KiB logical-record boundary even
    /// though each individual IRC line is legal.  Treating the whole batch as a
    /// single append makes the connection firewall close an otherwise healthy
    /// reader; line-wise appends preserve the exact byte stream while allowing
    /// SendQ overflow and TLS/WebSocket framing to operate on bounded records.
    pub fn appendHistoryReplay(conn: *ConnState, replay: []const u8) !void {
        const websocket_open = if (conn.ws) |ws| ws.phase == .open else false;
        const userspace_tls = if (conn.tls) |tls| tls.handshakeDone() and !conn.tls_tx_offloaded else false;
        const raw_bound = linewiseReplayRawBound(replay, websocket_open, userspace_tls) orelse
            return error.OutputTooSmall;
        try reserveRawAppendToConn(conn, raw_bound);
        var rest = replay;
        while (std.mem.indexOfScalar(u8, rest, '\n')) |newline| {
            const line = rest[0 .. newline + 1];
            if (line.len > default_reply_bytes) return error.OutputTooSmall;
            rest = rest[newline + 1 ..];
        }
        if (rest.len != 0) return error.OutputTooSmall;

        rest = replay;
        while (std.mem.indexOfScalar(u8, rest, '\n')) |newline| {
            const line = rest[0 .. newline + 1];
            try appendToConn(conn, line);
            rest = rest[newline + 1 ..];
        }
    }

    /// Conservative SendQ reservation for a replay emitted one line per append.
    /// Userspace TLS creates at least one record for every append, so its record
    /// count is the number of IRC lines rather than ceil(total/16KiB).
    fn linewiseReplayRawBound(replay: []const u8, websocket_open: bool, userspace_tls: bool) ?usize {
        const lines = std.mem.count(u8, replay, "\n");
        var bytes = replay.len;
        if (websocket_open) {
            const terminators = std.math.mul(usize, lines, 2) catch return null;
            if (terminators > bytes) return null;
            bytes -= terminators;
            bytes = std.math.add(usize, bytes, std.math.mul(usize, lines, 10) catch return null) catch return null;
        }
        if (userspace_tls) {
            bytes = std.math.add(usize, bytes, std.math.mul(usize, lines, 256) catch return null) catch return null;
        }
        return bytes;
    }

    /// The EPHEMERAL TTL for a channel in milliseconds (0 = not ephemeral).
    /// Read straight from the IRCX EPHEMERAL prop (a plain, mesh-propagated
    /// channel property), parsed as a whole-second TTL.
    fn channelEphemeralTtlMs(self: *LinuxServer, channel: []const u8) u64 {
        if (channel.len == 0) return 0;
        if (channel[0] != '#' and channel[0] != '&') return 0; // DMs never expire here
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const ev = self.props.getProp(entity, "EPHEMERAL") catch return 0;
        const secs = std.fmt.parseInt(u64, ev.value, 10) catch return 0;
        return secs *| 1000;
    }

    /// Configured SLOWMODE gap in milliseconds. 0 means the channel is not limited.
    fn channelSlowmodeGapMs(self: *LinuxServer, channel: []const u8) u64 {
        if (channel.len == 0 or (channel[0] != '#' and channel[0] != '&')) return 0;
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const ev = self.props.getProp(entity, "SLOWMODE") catch return 0;
        const secs = std.fmt.parseInt(u64, ev.value, 10) catch return 0;
        if (secs == 0 or secs > slowmode_max_secs) return 0;
        return secs * 1000;
    }

    /// Voice and channel operators skip the gap unless SLOWVOICE is "0".
    /// Absent and "1" keep the exemption. Network operators are always exempt.
    fn channelSlowmodeVoiceExempt(self: *LinuxServer, channel: []const u8) bool {
        if (channel.len == 0 or (channel[0] != '#' and channel[0] != '&')) return true;
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const ev = self.props.getProp(entity, "SLOWVOICE") catch return true;
        return !std.mem.eql(u8, ev.value, "0");
    }

    fn slowmodeKey(channel: []const u8, nick: []const u8, buf: []u8) ?[]const u8 {
        if (channel.len == 0 or nick.len == 0) return null;
        if (channel.len + 1 + nick.len > buf.len) return null;
        for (channel, 0..) |byte, index| buf[index] = std.ascii.toLower(byte);
        buf[channel.len] = 0;
        for (nick, 0..) |byte, index| buf[channel.len + 1 + index] = std.ascii.toLower(byte);
        return buf[0 .. channel.len + 1 + nick.len];
    }

    fn slowmodeTooSoon(self: *LinuxServer, channel: []const u8, nick: []const u8, gap_ms: u64) bool {
        var buf: [slowmode_key_max]u8 = undefined;
        const key = slowmodeKey(channel, nick, &buf) orelse return true;
        const last = self.slowmode_last.get(key) orelse return false;
        const now = self.nowU64();
        if (now < last) return true;
        return now - last < gap_ms;
    }

    fn noteSlowmodeSend(self: *LinuxServer, channel: []const u8, nick: []const u8) bool {
        var buf: [slowmode_key_max]u8 = undefined;
        const key = slowmodeKey(channel, nick, &buf) orelse return false;
        const now = self.nowU64();
        if (self.slowmode_last.getPtr(key)) |slot| {
            slot.* = now;
            return true;
        }
        const owned = self.allocator.dupe(u8, key) catch return false;
        self.slowmode_last.put(self.allocator, owned, now) catch {
            self.allocator.free(owned);
            return false;
        };
        return true;
    }

    /// True when this send must be refused. An allowed, non-exempt send records
    /// the timer. A refusal leaves the previous timestamp where it was.
    fn slowmodeDenies(self: *LinuxServer, channel: []const u8, nick: []const u8, exempt: bool) bool {
        if (exempt) return false;
        const gap_ms = self.channelSlowmodeGapMs(channel);
        if (gap_ms == 0) return false;
        if (self.slowmodeTooSoon(channel, nick, gap_ms)) return true;
        return !self.noteSlowmodeSend(channel, nick);
    }

    fn publishSlowmodeProp(
        self: *LinuxServer,
        channel: []const u8,
        key: []const u8,
        value: []const u8,
        owner: []const u8,
        present: bool,
    ) void {
        const hlc = self.nextChannelPropHlc();
        var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
        var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
        const ps = self.signLocalChannelProp(present, channel, key, value, owner, hlc, &pk_buf, &sig_buf);
        if (self.recordChannelPropClock(channel, key, owner, hlc, present, ps.node, ps.pubkey, ps.sig)) {
            self.announceChannelProp(channel, key, value, owner, hlc, present, .{ .node = ps.node, .pubkey = ps.pubkey, .sig = ps.sig });
        }
    }

    /// Raid-shield entry for the same SLOWMODE prop a channel operator sets.
    /// `null` or 0 clears it. The value is what the property checkpoint restores.
    pub fn setChannelSlowmode(self: *LinuxServer, channel: []const u8, gap_secs: ?u64) !void {
        if (channel.len == 0 or (channel[0] != '#' and channel[0] != '&')) return error.InvalidChannel;
        const secs = gap_secs orelse 0;
        if (secs > slowmode_max_secs) return error.InvalidGap;
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        if (secs == 0) {
            self.props.deleteProp(entity, "SLOWMODE") catch |err| switch (err) {
                error.PropMissing => {},
                else => return err,
            };
            self.publishSlowmodeProp(channel, "SLOWMODE", "", "raid-shield", false);
            return;
        }
        var buf: [20]u8 = undefined;
        const text = std.fmt.bufPrint(&buf, "{d}", .{secs}) catch return error.InvalidGap;
        const ev = try self.props.setProp(entity, "SLOWMODE", text, .{ .id = "raid-shield", .access = .host });
        self.publishSlowmodeProp(channel, ev.key, ev.value, ev.owner, true);
    }

    /// Record one accepted join for the raid shield. `origin` is this server for
    /// a local JOIN and the Mooring peer name for a remote announcement.
    /// Allocation failure leaves the join in place.
    fn noteRaidJoin(self: *LinuxServer, channel: []const u8, origin: []const u8) void {
        self.raid_shield.note(channel, origin, self.nowU64()) catch |err| {
            srvLog("onyx-server: raid shield note failed ({s})\n", .{@errorName(err)});
        };
    }

    /// Reactor 0 turns a correlated burst into one slowmode engagement, and
    /// clears that slowmode after the channel has been quiet. A second pass
    /// while the shield is still engaged does not raise another verdict.
    fn evaluateRaidShield(self: *LinuxServer) void {
        if (!self.isMaintenanceReactor()) return;
        const actions = self.raid_shield.evaluate(self.nowU64()) catch |err| {
            srvLog("onyx-server: raid shield evaluate failed ({s})\n", .{@errorName(err)});
            return;
        };
        defer if (actions.len != 0) self.allocator.free(actions);
        for (actions) |action| {
            switch (action.kind) {
                .engage => {
                    self.setChannelSlowmode(action.channel, raid_shield.engaged_gap_secs) catch |err| {
                        srvLog("onyx-server: raid shield slowmode failed ({s})\n", .{@errorName(err)});
                        continue;
                    };
                    var buf: [320]u8 = undefined;
                    const msg = std.fmt.bufPrint(&buf, "FLOOD raid shield engaged slowmode on {s}", .{action.channel}) catch continue;
                    self.publishOperEvent(.flood, .warn, msg) catch {};
                },
                .relax => self.setChannelSlowmode(action.channel, null) catch {},
            }
        }
    }

    /// The oldest message timestamp (epoch ms) still visible in `channel`, or 0
    /// when the channel is not ephemeral. Messages before this are expired.
    fn ephemeralFloorMs(self: *LinuxServer, channel: []const u8) u64 {
        const ttl_ms = self.channelEphemeralTtlMs(channel);
        if (ttl_ms == 0) return 0;
        const now_i = platform.realtimeMillis();
        const now: u64 = if (now_i > 0) @intCast(now_i) else 0;
        return if (now > ttl_ms) now - ttl_ms else 0;
    }

    /// RETAIN TTL in milliseconds. 0 means the channel does not expire history.
    /// A stored value that is not a whole number of seconds inside the PROP
    /// bounds is off, same as a missing property.
    fn channelRetainTtlMs(self: *LinuxServer, channel: []const u8) u64 {
        if (channel.len == 0 or (channel[0] != '#' and channel[0] != '&')) return 0;
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const ev = self.props.getProp(entity, "RETAIN") catch return 0;
        const secs = std.fmt.parseInt(u64, ev.value, 10) catch return 0;
        if (secs == 0 or secs < retain_min_secs or secs > retain_max_secs) return 0;
        return std.math.mul(u64, secs, 1000) catch 0;
    }

    fn historyHoldsText(self: *const LinuxServer, text: []const u8) bool {
        var it = self.history.deterministicIterator();
        while (it.next()) |entry| {
            if (std.mem.eql(u8, entry.message.text, text)) return true;
        }
        return false;
    }

    /// Delete history older than each channel's RETAIN property. The row, its
    /// search id, and a memo whose body is only that stored text (plaintext or
    /// ciphertext) all go. The body is not decrypted.
    fn expireRetainedHistory(self: *LinuxServer) void {
        const now = self.meshWallMs();
        var names: std.ArrayList([]u8) = .empty;
        defer {
            for (names.items) |name| self.allocator.free(name);
            names.deinit(self.allocator);
        }
        const Collect = struct {
            server: *LinuxServer,
            names: *std.ArrayList([]u8),
            now: u64,
            fn visit(ctx: *@This(), target: []const u8) void {
                const ttl_ms = ctx.server.channelRetainTtlMs(target);
                if (ttl_ms == 0 or ctx.now < ttl_ms) return;
                const owned = ctx.server.allocator.dupe(u8, target) catch return;
                ctx.names.append(ctx.server.allocator, owned) catch {
                    ctx.server.allocator.free(owned);
                };
            }
        };
        var collect = Collect{ .server = self, .names = &names, .now = now };
        self.history.forEachTarget(&collect, Collect.visit);

        var removed_history = false;
        var removed_memos: usize = 0;
        for (names.items) |target| {
            const ttl_ms = self.channelRetainTtlMs(target);
            if (ttl_ms == 0 or now < ttl_ms) continue;
            const cutoff = now - ttl_ms;
            while (self.history.oldestNotAfter(target, cutoff)) |row| {
                if (row.msgid.len > 1024 or row.text.len > e2ee_policy.max_room_envelope_wire_len) break;
                var msgid_buf: [1024]u8 = undefined;
                @memcpy(msgid_buf[0..row.msgid.len], row.msgid);
                const msgid = msgid_buf[0..row.msgid.len];
                var text_buf: [e2ee_policy.max_room_envelope_wire_len]u8 = undefined;
                @memcpy(text_buf[0..row.text.len], row.text);
                const text = text_buf[0..row.text.len];
                self.history.forget(target, msgid) catch break;
                removed_history = true;
                _ = self.search_index.remove(msgid);
                if (text.len != 0 and !self.historyHoldsText(text)) {
                    removed_memos += self.memo.removeCopies(text);
                }
            }
        }
        if (removed_history) self.snapshotDurableHistory();
        if (removed_memos != 0) {
            self.snapshotDurableMemos(self.nowMs());
        }
    }

    fn writeHistoryReplayLine(
        writer: anytype,
        session: *const dispatch.ClientSession,
        batch_ref: ?[]const u8,
        target: []const u8,
        message: lotus.Message,
    ) !void {
        var timestamp_buf: [24]u8 = undefined;
        const timestamp = try chathistory_cmd.formatTimestamp(message.timestamp, &timestamp_buf);
        if (batch_ref) |ref| {
            try writer.print("@batch={s};time={s};msgid={s}", .{ ref, timestamp, message.msgid });
        } else {
            try writer.print("@time={s};msgid={s}", .{ timestamp, message.msgid });
        }
        if (historyEntryIsTagmsg(message.command)) {
            const raw = message.client_tags orelse return;
            var tag_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
            const visible_tags = clientTagsForSession(session, raw, &tag_buf);
            if (visible_tags.len == 0) return;
            try writer.print(";{s} :{s} TAGMSG {s}\r\n", .{ visible_tags, message.sender, target });
            return;
        }
        if (message.client_tags) |raw| {
            var tag_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
            const visible_tags = clientTagsForSession(session, raw, &tag_buf);
            if (visible_tags.len != 0) try writer.print(";{s}", .{visible_tags});
        }
        try writer.print(" :{s} {s}", .{ message.sender, message.command });
        if (historyEntryIsEvent(message.command)) {
            try writer.print(" {s}\r\n", .{message.text});
        } else {
            try writer.print(" {s} :{s}\r\n", .{ target, message.text });
        }
    }

    /// Convert a fixed-width `YYYY-MM-DDThh:mm:ss.sssZ` read-marker timestamp to
    /// epoch milliseconds (the unit the Lotus history ring is keyed on). Returns
    /// null on any malformed field. Uses the civil-from-days algorithm so it is
    /// allocation- and table-free.
    fn markerToMillis(s: []const u8) ?u64 {
        if (s.len < 24) return null;
        const year = std.fmt.parseInt(i64, s[0..4], 10) catch return null;
        const month = std.fmt.parseInt(i64, s[5..7], 10) catch return null;
        const day = std.fmt.parseInt(i64, s[8..10], 10) catch return null;
        const hh = std.fmt.parseInt(i64, s[11..13], 10) catch return null;
        const mm = std.fmt.parseInt(i64, s[14..16], 10) catch return null;
        const ss = std.fmt.parseInt(i64, s[17..19], 10) catch return null;
        const ms = std.fmt.parseInt(i64, s[20..23], 10) catch return null;
        const j = if (month <= 2) year - 1 else year;
        const era = @divFloor(if (j >= 0) j else j - 399, 400);
        const yoe = j - era * 400;
        const mp: i64 = if (month > 2) month - 3 else month + 9;
        const doy = @divFloor(153 * mp + 2, 5) + day - 1;
        const doe = yoe * 365 + @divFloor(yoe, 4) - @divFloor(yoe, 100) + doy;
        const days = era * 146097 + doe - 719468;
        const total_ms = (((days * 24 + hh) * 60 + mm) * 60 + ss) * 1000 + ms;
        if (total_ms < 0) return null;
        return @intCast(total_ms);
    }

    /// Bouncer rewind: when a `onyx/bouncer` client (re)joins a channel,
    /// replay the messages it missed — everything after its stored read marker.
    /// No marker means there is nothing to rewind to
    /// (a fresh client has read everything), so we stay silent rather than dump
    /// the full ring. No-op for clients without the cap or without an account.
    fn replayRewindOnJoin(self: *LinuxServer, conn: *ConnState, channel: []const u8) !void {
        if (self.read_marker_unavailable) return;
        if (!conn.session.hasCap(.onyx_bouncer)) return;
        const account = conn.session.account() orelse return;
        const canonical = services_mod.canonicalAccount(account) catch return;
        const owner = canonical.asSlice();
        const marker = (self.read_markers.get(owner, channel) catch null) orelse return;
        const marker_ms = markerToMillis(marker.slice()) orelse return;
        // Bouncer rewind replays *channel* history, so it must honor the same
        // history-policy gate the explicit CHATHISTORY path enforces (see
        // `ensureChathistoryTargetVisible`). The joiner is already a member at
        // this point in the JOIN flow, so pass is_member = true; a
        // `history-policy=opers` channel therefore still suppresses a non-oper
        // member's rewind, matching the FAIL ... ACCESS_DENIED an explicit
        // `CHATHISTORY LATEST` on the same channel would return.
        if (!self.historyPolicyAllows(channel, true, conn.session.isOper())) return;
        var buf: [64]lotus.Message = undefined;
        const found = self.history.after(channel, marker_ms, buf.len, buf[0..]) catch return;
        if (found.len == 0) return;
        if (!historyReplayHasVisible(conn, found)) return;
        const replay = self.renderHistoryReplayOwned(conn, "rewind", channel, found, null) catch {
            self.failReply(conn, "CHATHISTORY", "REPLAY_TOO_LARGE", "Bouncer rewind is too large; request fewer messages") catch {};
            return;
        };
        defer self.allocator.free(replay);
        appendHistoryReplay(conn, replay) catch {
            self.poisonOwnedDelivery(conn);
            return;
        };
    }

    /// CHATHISTORY <sub> <target> <criteria...> <limit> — IRCv3 history replay.
    /// Supports LATEST and BEFORE/AFTER with timestamp selectors over the Lotus
    /// ring; emits a `chathistory` BATCH of PRIVMSG lines (msgid+server-time).
    /// Resolve a CHATHISTORY selector to a server timestamp: a timestamp passes
    /// through; a msgid is looked up in `target`'s history. Null when a msgid is
    /// unknown (the caller then returns an empty result for that bound).
    fn resolveSelector(self: *LinuxServer, target: []const u8, sel: chathistory_cmd.Selector) ?u64 {
        return switch (sel) {
            .timestamp => |ts| ts,
            .msgid => |id| self.history.timestampOf(target, id),
        };
    }

    fn chathistoryTargetsFail(self: *LinuxServer, conn: *ConnState, err: chathistory_targets.ParseError) !void {
        const reason: []const u8 = switch (err) {
            error.NeedMoreParams => "Missing CHATHISTORY parameters",
            else => "Invalid CHATHISTORY parameters",
        };
        try self.failReply(conn, "CHATHISTORY", "INVALID_PARAMS", reason);
    }

    fn chathistoryCommandLine(line: []const u8) ?[]const u8 {
        const trimmed = std.mem.trimEnd(u8, line, "\r\n");
        if (trimmed.len == 0) return null;
        if (trimmed[0] != '@') return trimmed;
        const tag_end = std.mem.indexOfScalar(u8, trimmed, ' ') orelse return null;
        const command_line = std.mem.trimStart(u8, trimmed[tag_end + 1 ..], " ");
        return if (command_line.len == 0) null else command_line;
    }

    fn handleChathistoryTargets(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, line: []const u8) !void {
        const query = chathistory_targets.TargetsQuery.parse(line) catch |err| {
            try self.chathistoryTargetsFail(conn, err);
            return;
        };

        var index = chathistory_targets.TargetIndex.init(self.allocator, .{ .max_targets = 512, .max_query_limit = 64 });
        defer index.deinit();

        var chans: [128][]const u8 = undefined;
        const chan_count = self.world.channelsOf(worldIdFromClient(id), &chans);
        for (chans[0..chan_count]) |channel| {
            if (self.latestActivityInWindow(channel, query)) |ts| {
                index.touch(channel, @intCast(ts)) catch {};
            }
        }

        const requester_wid = worldIdFromClient(id);
        var nick_it = self.world.client_nicks.iterator();
        while (nick_it.next()) |entry| {
            if (entry.key_ptr.*.eql(requester_wid)) continue;
            const peer = entry.value_ptr.*;
            var key_buf: [320]u8 = undefined;
            const peer_account = if (self.connFor(clientIdFromWorld(entry.key_ptr.*))) |peer_conn| peer_conn.session.account() else null;
            const store_key = dmHistoryKey(conn.session.displayName(), conn.session.account(), peer, peer_account, &key_buf) orelse continue;
            if (self.latestActivityInWindow(store_key, query)) |ts| {
                index.touch(peer, @intCast(ts)) catch {};
            }
        }

        var out: [64]chathistory_targets.Target = undefined;
        const targets = index.query(query, &out) catch out[0..0];
        var reply: [default_reply_bytes * 4]u8 = undefined;
        var writer = std.Io.Writer.fixed(&reply);
        const use_batch = conn.session.hasCap(.batch);
        if (use_batch) try writer.print("BATCH +1 {s}\r\n", .{chathistory_cmd.targets_batch_type});
        for (targets) |target| {
            var line_buf: [192]u8 = undefined;
            const detail = chathistory_targets.formatTargetLine(&line_buf, target) catch continue;
            if (use_batch) {
                try writer.print("@batch=1 :{s} CHATHISTORY TARGETS {s}\r\n", .{ self.serverName(), detail });
            } else {
                try writer.print(":{s} CHATHISTORY TARGETS {s}\r\n", .{ self.serverName(), detail });
            }
        }
        if (use_batch) try writer.print("BATCH -1\r\n", .{});
        appendHistoryReplay(conn, writer.buffered()) catch {
            self.poisonOwnedDelivery(conn);
            return;
        };
    }

    pub fn handleChathistory(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView, line: []const u8) !void {
        if (!conn.session.hasCap(.chathistory)) {
            try self.failReply(conn, "CHATHISTORY", "NEED_REGISTRATION", "You must negotiate the draft/chathistory capability");
            return;
        }
        // Module handlers receive the original wire line so they can inspect
        // tags through `parsed`. The CHATHISTORY grammar itself begins at the
        // command, not at an optional `@tags` prefix.
        const command_line = chathistoryCommandLine(line) orelse {
            try self.failReply(conn, "CHATHISTORY", "INVALID_PARAMS", "Invalid CHATHISTORY parameters");
            return;
        };
        if (std.ascii.startsWithIgnoreCase(command_line, "CHATHISTORY TARGETS")) {
            try self.handleChathistoryTargets(id, conn, command_line);
            return;
        }
        const req = chathistory_cmd.parse(command_line) catch |err| {
            // IRCv3 chathistory: malformed requests get a typed standard reply,
            // `FAIL CHATHISTORY <code> :<reason>`, never silence.
            const code = @tagName(chathistory_cmd.failCode(err));
            const reason: []const u8 = switch (err) {
                error.NEED_MORE_PARAMS => "Missing CHATHISTORY parameters",
                error.INVALID_TARGET => "Invalid CHATHISTORY target",
                else => "Invalid CHATHISTORY parameters",
            };
            try self.failReply(conn, "CHATHISTORY", code, reason);
            return;
        };
        const hist_target = chathistory_cmd.requestTarget(req);
        if (!try self.ensureChathistoryTargetVisible(id, conn, hist_target)) return;
        if (world_model.isChannelName(hist_target)) {
            if (conn.session.account()) |account| {
                if (self.accountIsGatedBot(account) and !self.bot_grants.allows(account, .history, hist_target, self.grantNowU64())) {
                    try self.failReply(conn, "CHATHISTORY", "ACCESS_DENIED", "BOTGRANT: history refused");
                    return;
                }
            }
        }
        var buf: [64]lotus.Message = undefined;
        var target: []const u8 = "";
        var found: []const lotus.Message = buf[0..0];
        // Optional named-conversation filter: a `+onyx/topic=<label>` message
        // tag on the CHATHISTORY command restricts replay to one conversation.
        // Absent/invalid => null (all messages, exactly as before).
        var topic_buf: [topic_tag.max_label_len]u8 = undefined;
        const topic_filter: ?[]const u8 = if (parsed.tags_raw) |tr| topic_tag.labelFromTags(tr, &topic_buf) else null;
        switch (req) {
            .latest => |r| {
                target = r.target;
                var key_buf: [320]u8 = undefined;
                const store_target = self.historyKeyForTarget(conn, target, &key_buf);
                const n = @min(@as(usize, r.limit), buf.len);
                switch (chathistory_cmd.latestMode(r)) {
                    .unbounded => found = self.history.latest(store_target, n, buf[0..n]) catch buf[0..0],
                    .before_bound => if (self.resolveSelector(store_target, r.lower_bound.?)) |ts| {
                        found = self.history.before(store_target, ts, n, buf[0..n]) catch buf[0..0];
                    },
                }
            },
            .before => |r| {
                target = r.target;
                var key_buf: [320]u8 = undefined;
                const store_target = self.historyKeyForTarget(conn, target, &key_buf);
                const n = @min(@as(usize, r.limit), buf.len);
                // timestamp directly, or a msgid resolved to its timestamp.
                if (self.resolveSelector(store_target, r.selector)) |ts| {
                    found = self.history.before(store_target, ts, n, buf[0..n]) catch buf[0..0];
                }
            },
            .after => |r| {
                target = r.target;
                var key_buf: [320]u8 = undefined;
                const store_target = self.historyKeyForTarget(conn, target, &key_buf);
                const n = @min(@as(usize, r.limit), buf.len);
                if (self.resolveSelector(store_target, r.selector)) |ts| {
                    found = self.history.after(store_target, ts, n, buf[0..n]) catch buf[0..0];
                }
            },
            .between => |r| {
                target = r.target;
                var key_buf: [320]u8 = undefined;
                const store_target = self.historyKeyForTarget(conn, target, &key_buf);
                const n = @min(@as(usize, r.limit), buf.len);
                if (self.resolveSelector(store_target, r.start)) |s| {
                    if (self.resolveSelector(store_target, r.end)) |e| {
                        const raw = switch (chathistory_cmd.rangeDirection(s, e)) {
                            .forward => self.history.after(store_target, s, n, buf[0..n]) catch buf[0..0],
                            .reverse => self.history.before(store_target, s, n, buf[0..n]) catch buf[0..0],
                        };
                        var k: usize = 0;
                        for (raw) |m| {
                            const in_range = switch (chathistory_cmd.rangeDirection(s, e)) {
                                .forward => m.timestamp < e,
                                .reverse => m.timestamp > e,
                            };
                            if (in_range) {
                                buf[k] = m; // safe in-place compaction (k <= source index)
                                k += 1;
                            }
                        }
                        found = buf[0..k];
                    }
                }
            },
            .around => |r| {
                target = r.target;
                var key_buf: [320]u8 = undefined;
                const store_target = self.historyKeyForTarget(conn, target, &key_buf);
                // Return up to `limit` messages centred on the pivot (a timestamp
                // or a msgid resolved to its timestamp): ~half strictly before it
                // (reversed to chronological order) followed by the pivot and
                // later, oldest-first.
                if (self.resolveSelector(store_target, r.center)) |center| {
                    const total = @min(@as(usize, r.limit), buf.len);
                    const half = total / 2;
                    var before_buf: [64]lotus.Message = undefined;
                    var after_buf: [64]lotus.Message = undefined;
                    const bn = @min(half, before_buf.len);
                    const before_part = self.history.before(store_target, center, bn, before_buf[0..bn]) catch before_buf[0..0];
                    const remaining = total - before_part.len;
                    const an = @min(remaining, after_buf.len);
                    const after_part = self.history.after(store_target, center -| 1, an, after_buf[0..an]) catch after_buf[0..0];
                    var k: usize = 0;
                    var i: usize = before_part.len; // before_part is newest-first; emit reversed
                    while (i > 0 and k < buf.len) {
                        i -= 1;
                        buf[k] = before_part[i];
                        k += 1;
                    }
                    for (after_part) |m| {
                        if (k == buf.len) break;
                        buf[k] = m;
                        k += 1;
                    }
                    found = buf[0..k];
                }
            },
        }

        const replay = self.renderHistoryReplayOwned(conn, "1", target, found, topic_filter) catch {
            try self.failReply(conn, "CHATHISTORY", "REPLAY_TOO_LARGE", "History replay is too large; request fewer messages");
            return;
        };
        defer self.allocator.free(replay);
        appendHistoryReplay(conn, replay) catch {
            self.poisonOwnedDelivery(conn);
            return;
        };
    }

    /// A CHATHISTORY entry is a draft/event-playback EVENT (rather than an
    /// ordinary message) when its replay command is neither PRIVMSG nor NOTICE.
    fn historyEntryIsEvent(command: []const u8) bool {
        return !std.mem.eql(u8, command, "PRIVMSG") and !std.mem.eql(u8, command, "NOTICE") and !historyEntryIsTagmsg(command);
    }

    /// draft/search result cap. The command body lives in `search_cmd.zig`.
    const search_max_results = search_cmd.max_results;

    /// `SEARCH <target> [<query...>]` — IRCv3 draft/search. The messaging module
    /// thunk calls this wrapper; the parse, cap, and replay live in `search_cmd.zig`.
    pub fn handleSearch(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, line: []const u8) !void {
        return search_cmd.handle(self, worldIdFromClient(id), conn, line);
    }

    /// Remember an in-process node SEARCH can call directly. A live Mooring
    /// link is asked with SEARCH_QUERY instead. Asking yourself is a no-op.
    pub fn attachMeshSearchPeer(self: *LinuxServer, peer: *LinuxServer) !void {
        if (peer == self) return;
        for (self.mesh_search_peers.items) |existing| {
            if (existing == peer) return;
        }
        try self.mesh_search_peers.append(self.allocator, peer);
    }

    /// Borrow a peer whose SEARCH frames travel through `sink`. The same send
    /// path `handleSearch` uses for this list also scans live secured links.
    pub fn noteMeshSearchLink(self: *LinuxServer, peer: *s2s_peer_mod.S2sPeer, sink: s2s_peer_mod.ByteSink) !void {
        for (self.mesh_search_wires.items) |*existing| {
            if (existing.peer == peer) {
                existing.sink = sink;
                return;
            }
        }
        try self.mesh_search_wires.append(self.allocator, .{ .peer = peer, .sink = sink });
    }

    fn allocMeshSearchId(self: *LinuxServer) u32 {
        var id = self.next_mesh_search_id +% 1;
        if (id == 0) id = 1;
        self.next_mesh_search_id = id;
        return id;
    }

    fn destroyMeshSearchPending(self: *LinuxServer, pending: *PendingMeshSearch) void {
        self.allocator.free(pending.target);
        for (pending.sent_ids.items) |id| self.allocator.free(id);
        pending.sent_ids.deinit(self.allocator);
    }

    fn deinitMeshSearchPending(self: *LinuxServer) void {
        for (self.mesh_search_pending.items) |*pending| self.destroyMeshSearchPending(pending);
        self.mesh_search_pending.deinit(self.allocator);
    }

    fn dropMeshSearchToken(self: *LinuxServer, token: RingFdToken) void {
        var i: usize = 0;
        while (i < self.mesh_search_pending.items.len) {
            if (ringTokenEql(self.mesh_search_pending.items[i].token, token)) {
                var old = self.mesh_search_pending.orderedRemove(i);
                self.destroyMeshSearchPending(&old);
            } else {
                i += 1;
            }
        }
    }

    fn rememberMeshSearch(
        self: *LinuxServer,
        id: u32,
        conn: *ConnState,
        target: []const u8,
        already: []const lotus.Message,
        expect: usize,
    ) !void {
        self.dropMeshSearchToken(conn.token);
        while (self.mesh_search_pending.items.len >= mesh_search_pending_max) {
            var old = self.mesh_search_pending.orderedRemove(0);
            self.destroyMeshSearchPending(&old);
        }
        const target_copy = try self.allocator.dupe(u8, target);
        errdefer self.allocator.free(target_copy);
        var ids: std.ArrayListUnmanaged([]u8) = .empty;
        errdefer {
            for (ids.items) |item| self.allocator.free(item);
            ids.deinit(self.allocator);
        }
        for (already) |message| {
            const copy = try self.allocator.dupe(u8, message.msgid);
            ids.append(self.allocator, copy) catch |err| {
                self.allocator.free(copy);
                return err;
            };
        }
        try self.mesh_search_pending.append(self.allocator, .{
            .id = id,
            .token = conn.token,
            .target = target_copy,
            .sent_ids = ids,
            .sent = already.len,
            .expect = expect,
        });
    }

    fn meshSearchSeen(pending: *const PendingMeshSearch, msgid: []const u8) bool {
        for (pending.sent_ids.items) |id| {
            if (std.mem.eql(u8, id, msgid)) return true;
        }
        return false;
    }

    /// Ask every negotiated mesh peer. Returns true when at least one query
    /// was sent and the reply is still outstanding. Local hits already shown
    /// to the client are remembered so a later reply cannot repeat them or
    /// pass the hard cap.
    pub fn dispatchMeshSearchQuery(
        self: *LinuxServer,
        conn: *ConnState,
        target: []const u8,
        words: []const []const u8,
        already: []const lotus.Message,
    ) bool {
        if (!world_model.isChannelName(target) or words.len == 0) return false;
        var qbuf: [1024]u8 = undefined;
        const id = self.allocMeshSearchId();
        const wire = mesh_search.encodeQuery(id, target, words, &qbuf) orelse return false;
        var sent: usize = 0;
        for (self.mesh_search_wires.items) |link| {
            link.peer.sendSearchQuery(link.sink, wire) catch continue;
            sent += 1;
        }
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                if (!entry.value.isActiveMeshPeer()) continue;
                const secured = entry.value.s2s_secured orelse continue;
                secured.sendSearchQuery(wire) catch continue;
                sent += 1;
            }
        }
        if (sent == 0) return false;
        self.rememberMeshSearch(id, conn, target, already, sent) catch return false;
        return true;
    }

    fn answerSearchPayload(self: *LinuxServer, payload: []const u8) ?[]u8 {
        const query = mesh_search.decodeQuery(payload) orelse return null;
        if (query.word_count == 0) return null;
        var hits: [search_cmd.max_results]mesh_search.Borrowed = undefined;
        const n = search_cmd.serve(self, query.target, query.words[0..query.word_count], &hits);
        return mesh_search.encodeReply(self.allocator, query.id, hits[0..n], search_cmd.max_results) catch null;
    }

    fn deliverSearchPayload(self: *LinuxServer, payload: []const u8) void {
        var decoded: [search_cmd.max_results]mesh_search.HitView = undefined;
        const view = mesh_search.decodeReply(payload, &decoded) orelse return;
        var index: ?usize = null;
        for (self.mesh_search_pending.items, 0..) |pending, i| {
            if (pending.id == view.id) {
                index = i;
                break;
            }
        }
        const at = index orelse return;
        const pending = &self.mesh_search_pending.items[at];
        const conn = self.connForToken(pending.token) catch {
            var old = self.mesh_search_pending.orderedRemove(at);
            self.destroyMeshSearchPending(&old);
            return;
        };
        const wid = worldIdFromClient(idFromToken(pending.token));
        const can_see = self.world.isMember(pending.target, wid);
        var batch: [search_cmd.max_results]lotus.Message = undefined;
        var batch_len: usize = 0;
        for (decoded[0..view.count]) |hit| {
            if (pending.sent >= search_cmd.max_results or batch_len >= batch.len) break;
            if (meshSearchSeen(pending, hit.msgid)) continue;
            if (!mesh_search.keep(can_see, hit.text, hit.tags)) continue;
            const message = lotus.Message{
                .msgid = hit.msgid,
                .sender = hit.sender,
                .text = hit.text,
                .timestamp = hit.timestamp,
                .tombstone = false,
                .command = "PRIVMSG",
                .client_tags = hit.tags,
            };
            if (!historyMessageVisibleTo(&conn.session, message)) continue;
            const copy = self.allocator.dupe(u8, hit.msgid) catch continue;
            pending.sent_ids.append(self.allocator, copy) catch {
                self.allocator.free(copy);
                continue;
            };
            batch[batch_len] = message;
            batch_len += 1;
            pending.sent += 1;
        }
        if (batch_len != 0) {
            const replay = self.renderHistoryReplayOwned(conn, "search", pending.target, batch[0..batch_len], null) catch null;
            if (replay) |owned| {
                defer self.allocator.free(owned);
                LinuxServer.appendHistoryReplay(conn, owned) catch self.poisonOwnedDelivery(conn);
            }
        }
        pending.got += 1;
        if (pending.got >= pending.expect) {
            var old = self.mesh_search_pending.orderedRemove(at);
            self.destroyMeshSearchPending(&old);
        }
    }

    /// Sign this node's current key-transparency head, or return null when
    /// there is no identity, no log, or an empty log. Anti-entropy sends nothing
    /// in those cases.
    fn localKeyTransHeadWire(self: *LinuxServer, out: []u8) ?[]const u8 {
        const ident = self.config.node_identity orelse return null;
        const svc = self.account_services orelse return null;
        var head = svc.keyTransparencyUnsignedLocalHead(ident.shortId()) catch return null;
        key_transparency.signHead(&ident.sign_kp, &head) catch return null;
        return key_transparency.encodeHeadWire(head, out) catch null;
    }

    /// Anti-entropy carrier for one signed key-transparency head. A peer that
    /// has not answered the probe is skipped; that is not a burst failure.
    fn sendKeyTransHeadOn(self: *LinuxServer, link: anytype) bool {
        var buf: [key_transparency.head_wire_len]u8 = undefined;
        const wire = self.localKeyTransHeadWire(&buf) orelse return true;
        link.sendKeyTransHead(wire) catch |err| switch (err) {
            error.KeyTransUnavailable => return true,
            else => return false,
        };
        return true;
    }

    fn drainKeyTransHeads(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainKeyTransHeadsAdmitted(link);
    }

    fn drainKeyTransHeadsAdmitted(self: *LinuxServer, link: anytype) void {
        const payloads = link.takeKeyTransHeads() catch return;
        defer {
            for (payloads) |payload| self.allocator.free(payload);
            if (payloads.len != 0) self.allocator.free(payloads);
        }
        const svc = self.account_services orelse return;
        for (payloads) |payload| {
            const head = key_transparency.decodeHeadWire(payload) catch continue;
            svc.storeKeyTransparencyHead(head) catch continue;
        }
    }

    fn drainKeyTransPeer(self: *LinuxServer, peer: *s2s_peer_mod.S2sPeer) void {
        if (comptime !builtin.is_test) return;
        const KeyTransPeerBridge = struct {
            peer: *s2s_peer_mod.S2sPeer,
            fn takeKeyTransHeads(bridge: *@This()) ![][]u8 {
                return bridge.peer.takeKeyTransHeads();
            }
        };
        var bridge = KeyTransPeerBridge{ .peer = peer };
        self.drainKeyTransHeadsAdmitted(&bridge);
    }

    /// Answer inbound queries and deliver inbound replies. `link` is the
    /// secured link, the plaintext link, or the test peer bridge.
    fn drainMeshSearch(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        self.drainMeshSearchAdmitted(link);
    }

    fn drainMeshSearchAdmitted(self: *LinuxServer, link: anytype) void {
        const queries = link.takeSearchQueries() catch return;
        defer {
            for (queries) |payload| self.allocator.free(payload);
            if (queries.len != 0) self.allocator.free(queries);
        }
        for (queries) |payload| {
            const reply = self.answerSearchPayload(payload) orelse continue;
            defer self.allocator.free(reply);
            link.sendSearchReply(reply) catch {};
        }
        const replies = link.takeSearchReplies() catch return;
        defer {
            for (replies) |payload| self.allocator.free(payload);
            if (replies.len != 0) self.allocator.free(replies);
        }
        for (replies) |payload| self.deliverSearchPayload(payload);
    }

    fn drainMeshSearchPeer(self: *LinuxServer, peer: *s2s_peer_mod.S2sPeer, sink: s2s_peer_mod.ByteSink) void {
        if (comptime !builtin.is_test) return;
        const SearchPeerBridge = struct {
            peer: *s2s_peer_mod.S2sPeer,
            sink: s2s_peer_mod.ByteSink,
            fn takeSearchQueries(s: *@This()) ![][]u8 {
                return s.peer.takeSearchQueries();
            }
            fn takeSearchReplies(s: *@This()) ![][]u8 {
                return s.peer.takeSearchReplies();
            }
            fn sendSearchReply(s: *@This(), wire: []const u8) !void {
                try s.peer.sendSearchReply(s.sink, wire);
            }
        };
        var bridge = SearchPeerBridge{ .peer = peer, .sink = sink };
        self.drainMeshSearchAdmitted(&bridge);
    }

    /// `UNFURL ON|OFF|<https-url>`. The daemon flag defaults off. A client that
    /// has not sent ON is refusing previews. The fetch is one https GET with no
    /// Cookie header and no cookie jar. Private, link-local, and loopback
    /// addresses are refused before the connection.
    pub fn handleUnfurl(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.registered()) {
            try queueNumeric(conn, .ERR_NOTREGISTERED, &.{}, "You have not registered");
            return;
        }
        if (!self.config.unfurl_enabled) {
            try self.noticeTo(conn, "UNFURL: disabled");
            return;
        }
        const p = parsed.paramSlice();
        if (p.len < 1 or p[0].len == 0) {
            try self.noticeTo(conn, "Usage: UNFURL <ON|OFF|https://host/path>");
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "ON")) {
            conn.unfurl_opt_in = true;
            try self.noticeTo(conn, "UNFURL: previews on");
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "OFF")) {
            conn.unfurl_opt_in = false;
            try self.noticeTo(conn, "UNFURL: client refused");
            return;
        }
        if (!conn.unfurl_opt_in) {
            try self.noticeTo(conn, "UNFURL: client refused");
            return;
        }
        const target = unfurl.parseHttps(p[0]) catch {
            try self.noticeTo(conn, "UNFURL: https URLs only");
            return;
        };
        const addr = self.resolveUnfurlAddress(target) catch |err| {
            try self.noticeTo(conn, if (err == error.PrivateUnfurlAddress) "UNFURL: address refused" else "UNFURL: could not resolve");
            return;
        };
        var request_buf: [512]u8 = undefined;
        const request = unfurl.buildTargetRequest(&request_buf, target) catch {
            try self.noticeTo(conn, "UNFURL: url is too long");
            return;
        };
        var body_buf: [unfurl.max_body]u8 = undefined;
        const body = self.unfurlBody(request, target, addr, &body_buf) catch {
            try self.noticeTo(conn, "UNFURL: could not fetch");
            return;
        };
        var title_buf: [unfurl.max_field]u8 = undefined;
        var desc_buf: [unfurl.max_field]u8 = undefined;
        var image_buf: [unfurl.max_field]u8 = undefined;
        const preview = unfurl.parse(body, &title_buf, &desc_buf, &image_buf);
        var notice_buf: [640]u8 = undefined;
        const notice = std.fmt.bufPrint(&notice_buf, "UNFURL title={s} description={s} image={s}", .{ preview.title, preview.description, preview.image }) catch {
            try self.noticeTo(conn, "UNFURL: preview is too long");
            return;
        };
        try self.noticeTo(conn, notice);
    }

    fn resolveUnfurlAddress(self: *LinuxServer, target: unfurl.Target) !std.Io.net.IpAddress {
        const addr = if (target.literal) |literal|
            literal
        else if (self.unfurl_resolve_for_test) |resolve|
            try resolve(target.host)
        else
            try resolveUnfurlHostname(target.host, target.port, http_fetch.resolveHostA, http_fetch.resolveHostAAAA);
        if (unfurl.deniedAddress(addr)) return error.PrivateUnfurlAddress;
        return addr;
    }

    fn resolveUnfurlHostname(
        host: []const u8,
        port: u16,
        resolve_a: *const fn ([]const u8, u16, u31) anyerror!std.Io.net.IpAddress,
        resolve_aaaa: *const fn ([]const u8, u16, u31) anyerror!std.Io.net.IpAddress,
    ) !std.Io.net.IpAddress {
        return resolve_a(host, port, 2000) catch |err| {
            // Windows DNS can report HostNotFound when only AAAA answers exist.
            if (comptime builtin.os.tag == .windows) {
                if (err == error.HostNotFound) return resolve_aaaa(host, port, 2000);
            }
            return err;
        };
    }

    fn resolveUnfurlAAAAAddress(self: *LinuxServer, target: unfurl.Target) !std.Io.net.IpAddress {
        if (target.literal != null) return error.PrivateUnfurlAddress;
        const addr = if (self.unfurl_resolve_aaaa_for_test) |resolve|
            try resolve(target.host)
        else
            try http_fetch.resolveHostAAAA(target.host, target.port, 2000);
        if (addr != .ip6) return error.HostNotFound;
        if (unfurl.deniedAddress(addr)) return error.PrivateUnfurlAddress;
        return addr;
    }

    fn unfurlBody(self: *LinuxServer, request: []const u8, target: unfurl.Target, addr: std.Io.net.IpAddress, dest: []u8) ![]const u8 {
        if (self.unfurl_fetch_for_test) |fetch| {
            const n = try fetch(request, dest);
            return dest[0..@min(n, dest.len)];
        }
        if (self.unfurl_fetch_at_address_for_test) |fetch| {
            const n = try fetch(request, addr, dest);
            return dest[0..@min(n, dest.len)];
        }
        const test_anchors = self.outboundTrustOverrideForTest();
        var trust: ?outbound_trust.Store = if (test_anchors == null) try self.loadOutboundTrust() else null;
        defer if (trust) |*store| store.deinit();
        var connected = false;
        const opts = http_fetch.Options{
            .max_response_bytes = unfurl.max_body,
            .trust_anchors = if (test_anchors) |anchors| anchors else if (trust) |*store| store.anchors() else &.{},
            .disallowed_certs = if (trust) |*store| store.disallowed() else &.{},
            .windows_chain_policy = builtin.os.tag == .windows and trust != null,
            .connect_established = &connected,
        };
        const raw = self.getUnfurlAtAddress(target, request, addr, opts) catch |err| blk: {
            if (!shouldWindowsPinnedAAAAFallback(addr, target.literal == null, connected, err)) return err;
            const fallback_addr = try self.resolveUnfurlAAAAAddress(target);
            connected = false;
            break :blk try self.getUnfurlAtAddress(target, request, fallback_addr, opts);
        };
        defer self.allocator.free(raw);
        const split = std.mem.indexOf(u8, raw, "\r\n\r\n") orelse return dest[0..0];
        const body = raw[split + 4 ..];
        const n = @min(body.len, dest.len);
        @memcpy(dest[0..n], body[0..n]);
        return dest[0..n];
    }

    fn getUnfurlAtAddress(self: *LinuxServer, target: unfurl.Target, request: []const u8, addr: std.Io.net.IpAddress, opts: http_fetch.Options) ![]u8 {
        if (comptime builtin.is_test) {
            if (self.unfurl_get_at_address_for_test) |get| return get(self.allocator, target.host, target.port, request, addr, opts);
        }
        return http_fetch.getAtAddress(self.allocator, target.host, target.port, true, request, addr, opts);
    }

    /// `APPEAL <text>` files one structured appeal per host per window. The
    /// connection does not need to be registered or joined. `APPEAL LIST` and
    /// `APPEAL ANSWER <id> :<text>` are oper-only. The answer is audited. Nothing
    /// on this path is sent to a channel.
    pub fn handleAppeal(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const p = parsed.paramSlice();
        if (p.len < 1 or p[0].len == 0) {
            try self.noticeTo(conn, "Usage: APPEAL <text> | APPEAL LIST | APPEAL ANSWER <id> :<text>");
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "LIST")) {
            if (!conn.session.isOper()) {
                try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied");
                return;
            }
            var views: [appeal.max_appeals]appeal.View = undefined;
            const n = self.appeals.list(&views);
            if (n == 0) {
                try self.noticeTo(conn, "APPEAL none");
                return;
            }
            for (views[0..n]) |view| {
                var buf: [512]u8 = undefined;
                const line = std.fmt.bufPrint(&buf, "APPEAL {d} {s} {s} {s} :{s}", .{
                    view.id,
                    view.nick,
                    view.host,
                    if (view.answered) "answered" else "open",
                    view.text,
                }) catch continue;
                try self.noticeTo(conn, line);
            }
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "ANSWER")) {
            if (!conn.session.isOper()) {
                try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied");
                return;
            }
            if (p.len < 3) {
                try self.noticeTo(conn, "Usage: APPEAL ANSWER <id> :<text>");
                return;
            }
            const id = std.fmt.parseInt(u64, p[1], 10) catch {
                try self.noticeTo(conn, "APPEAL no such id");
                return;
            };
            self.appeals.answer(id, p[2]) catch {
                try self.noticeTo(conn, "APPEAL no such id");
                return;
            };
            var id_buf: [32]u8 = undefined;
            const id_text = std.fmt.bufPrint(&id_buf, "{d}", .{id}) catch "0";
            var reason_buf: [180]u8 = undefined;
            const reason = std.fmt.bufPrint(&reason_buf, "appeal answer: {s}", .{p[2]}) catch "appeal answer";
            _ = self.recordOperAudit(conn.session.displayName(), .other, id_text, reason);
            try self.noticeTo(conn, "APPEAL answered");
            return;
        }
        const host = conn.session.realHost();
        const key = if (host.len != 0) host else conn.session.displayName();
        const nick = conn.session.displayName();
        const wall = self.meshWallMs();
        const now: i64 = if (wall > @as(u64, std.math.maxInt(i64))) std.math.maxInt(i64) else @intCast(wall);
        const id = self.appeals.file(nick, key, p[0], now) catch |err| switch (err) {
            error.Window => {
                try self.noticeTo(conn, "APPEAL already filed");
                return;
            },
            else => {
                try self.noticeTo(conn, "APPEAL could not file");
                return;
            },
        };
        var buf: [64]u8 = undefined;
        const notice = std.fmt.bufPrint(&buf, "APPEAL filed {d}", .{id}) catch "APPEAL filed";
        try self.noticeTo(conn, notice);
    }

    /// `OPERMOTD` — show the operator MOTD (RPL_OMOTDSTART/OMOTD/ENDOFOMOTD, or
    /// ERR_NOOPERMOTD if unset). `OPERMOTD SET :<text>` (oper-only) replaces it.
    pub fn handleOperMotd(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleOperMotd(self, conn, parsed);
    }

    /// `AUTOJOIN <ADD|DEL|LIST> [#channel]` — manage the caller's per-account
    /// auto-join list (applied automatically on each login). Requires login.
    pub fn handleAutojoin(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const account = conn.session.account() orelse {
            try self.failReply(conn, "AUTOJOIN", "ACCOUNT_REQUIRED", "Log in to manage autojoin");
            return;
        };
        const p = parsed.paramSlice();
        if (p.len == 0 or std.ascii.eqlIgnoreCase(p[0], "LIST")) {
            const chans = self.autojoins.list(account) catch &.{};
            for (chans) |c| {
                var b: [default_reply_bytes]u8 = undefined;
                const line = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :AUTOJOIN {s}\r\n", .{ self.serverName(), conn.session.displayName(), c }) catch continue;
                try emitReplyLine(conn, line);
            }
            try self.noticeTo(conn, "AUTOJOIN: end of list");
            return;
        }
        if (p.len < 2 or p[1].len == 0) {
            try self.noticeTo(conn, "Usage: AUTOJOIN <ADD|DEL|LIST> [#channel]");
            return;
        }
        const channel = p[1];
        if (std.ascii.eqlIgnoreCase(p[0], "ADD")) {
            self.autojoins.add(account, channel) catch {
                try self.noticeTo(conn, "AUTOJOIN: could not add (invalid channel, duplicate, or limit)");
                return;
            };
            try self.noticeTo(conn, "AUTOJOIN added");
        } else if (std.ascii.eqlIgnoreCase(p[0], "DEL")) {
            self.autojoins.remove(account, channel) catch {
                try self.noticeTo(conn, "AUTOJOIN: no such entry");
                return;
            };
            try self.noticeTo(conn, "AUTOJOIN removed");
        } else {
            try self.noticeTo(conn, "Usage: AUTOJOIN <ADD|DEL|LIST> [#channel]");
        }
    }

    /// `GROUP <ADD|DEL|LIST|PRIMARY> [nick]` — group multiple nicks under the
    /// caller's account, with a primary. Backed by memo_group.NickGroup. Requires
    /// login. (Distinct from single-nick registration ownership.)
    pub fn handleGroup(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const account = conn.session.account() orelse {
            try self.failReply(conn, "GROUP", "ACCOUNT_REQUIRED", "Log in to manage your nick group");
            return;
        };
        const p = parsed.paramSlice();
        if (p.len == 0 or std.ascii.eqlIgnoreCase(p[0], "LIST")) {
            var buf: [64][]const u8 = undefined;
            const nicks = self.nick_groups.list(account, &buf) catch &.{};
            const primary = (self.nick_groups.primary(account) catch null) orelse "";
            for (nicks) |nk| {
                var b: [default_reply_bytes]u8 = undefined;
                const star: []const u8 = if (std.ascii.eqlIgnoreCase(nk, primary)) " (primary)" else "";
                const line = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :GROUP {s}{s}\r\n", .{ self.serverName(), conn.session.displayName(), nk, star }) catch continue;
                try emitReplyLine(conn, line);
            }
            try self.noticeTo(conn, "GROUP: end of list");
            return;
        }
        if (p.len < 2 or p[1].len == 0) {
            try self.noticeTo(conn, "Usage: GROUP <ADD|DEL|LIST|PRIMARY> [nick]");
            return;
        }
        const nick = p[1];
        if (std.ascii.eqlIgnoreCase(p[0], "ADD")) {
            _ = self.nick_groups.add(account, nick) catch {
                try self.noticeTo(conn, "GROUP: could not add (invalid, duplicate, or limit)");
                return;
            };
            try self.noticeTo(conn, "GROUP nick added");
        } else if (std.ascii.eqlIgnoreCase(p[0], "DEL")) {
            _ = self.nick_groups.remove(account, nick) catch {
                try self.noticeTo(conn, "GROUP: no such grouped nick");
                return;
            };
            try self.noticeTo(conn, "GROUP nick removed");
        } else if (std.ascii.eqlIgnoreCase(p[0], "PRIMARY")) {
            self.nick_groups.setPrimary(account, nick) catch {
                try self.noticeTo(conn, "GROUP: nick must be in your group first");
                return;
            };
            try self.noticeTo(conn, "GROUP primary set");
        } else {
            try self.noticeTo(conn, "Usage: GROUP <ADD|DEL|LIST|PRIMARY> [nick]");
        }
    }

    /// `VERIFY [account] <code>` — confirm a pending account email verification
    /// issued at REGISTER time. The one-argument form keeps legacy behaviour by
    /// using the caller's logged-in account.
    pub fn handleVerify(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.authenticationAvailable())
            return self.failReply(conn, "VERIFY", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        if (parsed.param_count < 1 or parsed.paramSlice()[0].len == 0) {
            try self.noticeTo(conn, "Usage: VERIFY [account] <code>");
            return;
        }
        const params = parsed.paramSlice();
        var account: []const u8 = undefined;
        var code: []const u8 = undefined;
        if (parsed.param_count >= 2 and params[1].len != 0) {
            account = params[0];
            code = params[1];
        } else {
            account = conn.session.account() orelse {
                try self.failReply(conn, "VERIFY", "ACCOUNT_REQUIRED", "Log in before verifying");
                return;
            };
            code = params[0];
        }
        if (self.account_services) |svc| {
            var scratch: [1024]u8 = undefined;
            const now_u: u64 = @intCast(@max(0, self.nowMs()));
            const durable = svc.confirmAccountEmail(account, code, now_u, &scratch) catch null;
            if (durable) |result| switch (result) {
                .verified => {
                    _ = self.account_verifies.cancel(account);
                    try self.noticeTo(conn, "VERIFY: your account email is now verified");
                    return;
                },
                .expired => {
                    _ = self.account_verifies.cancel(account);
                    try self.failReply(conn, "VERIFY", "EXPIRED", "Verification code expired; re-register or request a new one");
                    return;
                },
                .bad_token => {
                    try self.failReply(conn, "VERIFY", "INVALID_CODE", "Incorrect verification code");
                    return;
                },
                .no_pending => {},
            };
        }
        const now_u: u64 = @intCast(@max(0, self.nowMs()));
        switch (self.account_verifies.confirm(account, code, now_u)) {
            .verified => try self.noticeTo(conn, "VERIFY: your account email is now verified"),
            .expired => try self.failReply(conn, "VERIFY", "EXPIRED", "Verification code expired; re-register or request a new one"),
            .no_pending => try self.noticeTo(conn, "VERIFY: nothing to verify for your account"),
            .bad_token => try self.failReply(conn, "VERIFY", "INVALID_CODE", "Incorrect verification code"),
            .locked => try self.failReply(conn, "VERIFY", "TOO_MANY_ATTEMPTS", "Too many attempts; verification locked"),
        }
    }

    /// RFC 4648 base32 alphabet (no padding) — a TOTP shared secret is a string of
    /// these symbols; 256 = 8*32, so masking a uniform random byte is unbiased.
    const totp_b32_alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
    /// Secret length in base32 symbols (32 symbols = 160 bits = 20 bytes).
    const totp_secret_symbols = 32;

    /// Current Unix time in SECONDS for TOTP — the wall clock the authenticator
    /// app uses, never the daemon's monotonic `nowMs`.
    fn totpUnixSeconds() i64 {
        return @divFloor(platform.realtimeMillis(), 1000);
    }

    /// Whether `account` has active TOTP 2FA — the ENFORCEMENT source of truth.
    /// Reads the persisted enrollment (only a CONFIRMed secret is stored), which
    /// is thread-safe (services lock) and never mutates the in-memory store, so
    /// it is safe to call from any login path (incl. the SASL gate). A pending,
    /// unpersisted enrollment correctly does not require a second factor.
    fn totpRequired(self: *LinuxServer, account: []const u8) bool {
        const svc = self.account_services orelse return false;
        // Unknown durable policy after ambiguous I/O must never relax 2FA.
        if (!svc.authenticationAvailable()) return true;
        return svc.totpEnrolled(account);
    }

    fn authenticationAvailable(self: *LinuxServer) bool {
        const svc = self.account_services orelse return true;
        return svc.authenticationAvailable();
    }

    /// `sasl.TotpGate` adapter: lets the SASL completion path (which has only the
    /// session, not the server) query 2FA status through an installed fat pointer.
    fn totpGateActive(ptr: *anyopaque, account: []const u8) bool {
        const self: *LinuxServer = @ptrCast(@alignCast(ptr));
        return self.totpRequired(account);
    }

    /// `sasl.AccountStatusGate` adapter: lets the SASL completion path (which
    /// holds only the session) refuse a SUSPENDED or FORBIDDEN account through an
    /// installed fat pointer. This is the chokepoint that closes the SCRAM /
    /// OAUTHBEARER bypass — their verifiers never consult account status. When no
    /// account store is present, no registered account can exist to succeed, so
    /// "not blocked" is safe.
    fn accountStatusGateBlocked(ptr: *anyopaque, account: []const u8) bool {
        const self: *LinuxServer = @ptrCast(@alignCast(ptr));
        const svc = self.account_services orelse return false;
        return !svc.authenticationAvailable() or svc.accountAuthBlocked(account);
    }

    /// `sasl.AccountKnownGate` adapter: unknown OAuth accounts fail closed
    /// unless the operator explicitly enables session binding for them.
    fn accountKnownGateKnown(ptr: *anyopaque, account: []const u8) bool {
        const self: *LinuxServer = @ptrCast(@alignCast(ptr));
        const svc = self.account_services orelse return false;
        return svc.accountIsRegistered(account);
    }

    /// Whether `account` has ACTIVE TOTP 2FA, ensuring the secret is loaded into
    /// the live store (lazily restoring a persisted secret after a restart) so a
    /// subsequent `self.totp.verify` can check a code with the replay guard. Use
    /// `totpRequired` for a pure read-only gate check.
    fn totpActiveForAccount(self: *LinuxServer, account: []const u8) bool {
        if (!self.authenticationAvailable()) return false;
        if (self.totp.isEnrolled(account)) return true;
        // A pending (unconfirmed) in-memory enrollment is authoritative — never
        // overwrite it with a persisted load (which would discard the pending
        // secret the user is mid-enrolling).
        if (self.totp.isPending(account)) return false;
        const svc = self.account_services orelse return false;
        var buf: [services_mod.Services.totp_secret_max]u8 = undefined;
        const b32 = svc.totpSecretGet(account, &buf) orelse return false;
        self.totp.loadActive(account, b32) catch return false;
        return self.totp.isEnrolled(account);
    }

    /// `TOTP <ENROLL | CONFIRM <code> | DISABLE | STATUS>` — manage the logged-in
    /// account's TOTP two-factor authentication. ENROLL mints a secret (shown in
    /// band + as an otpauth:// URI for the authenticator app); CONFIRM activates
    /// it (and durably persists it); login then requires a code (handleIdentify /
    /// SASL). Requires being logged in.
    pub fn handleTotp(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const account = conn.session.account() orelse
            return self.failReply(conn, "TOTP", "ACCOUNT_REQUIRED", "Log in to an account before managing TOTP");
        const svc = self.account_services orelse
            return self.failReply(conn, "TOTP", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        if (!svc.authenticationAvailable())
            return self.failReply(conn, "TOTP", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        if (parsed.param_count == 0)
            return self.failReply(conn, "TOTP", "NEED_MORE_PARAMS", "Usage: TOTP <ENROLL|CONFIRM <code>|DISABLE|STATUS>");
        const sub = parsed.paramSlice()[0];

        if (std.ascii.eqlIgnoreCase(sub, "STATUS")) {
            const state = if (self.totpActiveForAccount(account))
                "active"
            else if (self.totp.isPending(account))
                "pending — run TOTP CONFIRM <code> to activate"
            else
                "disabled";
            return channelNotice(conn, "TOTP: two-factor authentication is {s}", .{state});
        }

        if (std.ascii.eqlIgnoreCase(sub, "DISABLE")) {
            // Fixed lock order: TotpStore -> Services -> prepared WAL batch.
            // Pin the runtime entry through durable deletion + token revocation;
            // a failed admission leaves active/pending state and replay intact.
            const was = blk: {
                var change = self.totp.stageRemoval(account);
                defer change.deinit();
                const existed = change.outcome == .ok or svc.totpEnrolled(account);
                svc.totpPolicyCommit(account, null) catch
                    return self.failReply(conn, "TOTP", "TEMPORARILY_UNAVAILABLE", "Could not persist TOTP policy; try again after storage recovery");
                _ = change.commitRemoval();
                break :blk existed;
            };
            return channelNotice(conn, "TOTP: two-factor authentication {s}", .{if (was) "disabled" else "was not enabled"});
        }

        if (std.ascii.eqlIgnoreCase(sub, "ENROLL")) {
            // The shared secret must never cross a plaintext link.
            if (!conn.is_tls)
                return self.failReply(conn, "TOTP", "INSECURE_TRANSPORT", "Enroll TOTP over a secure (TLS) connection; the secret must not cross plaintext");
            if (self.totpRequired(account) or self.totp.isEnrolled(account))
                return self.failReply(conn, "TOTP", "ALREADY_ENROLLED", "TOTP is already active; DISABLE it first to re-enroll");
            const io = self.config.crypto_io orelse
                return self.failReply(conn, "TOTP", "TEMPORARILY_UNAVAILABLE", "No randomness source configured");
            var rnd: [totp_secret_symbols]u8 = undefined;
            defer std.crypto.secureZero(u8, &rnd);
            io.random(&rnd);
            var secret: [totp_secret_symbols]u8 = undefined;
            defer std.crypto.secureZero(u8, &secret);
            for (rnd, 0..) |b, i| secret[i] = totp_b32_alphabet[b & 0x1f];
            self.totp.enroll(account, &secret) catch
                return self.failReply(conn, "TOTP", "INTERNAL_ERROR", "Could not start enrollment");
            const issuer = self.serverName();
            var uri: [320]u8 = undefined;
            const otpauth = std.fmt.bufPrint(&uri, "otpauth://totp/{s}:{s}?secret={s}&issuer={s}&algorithm=SHA1&digits=6&period=30", .{ issuer, account, &secret, issuer }) catch "";
            try channelNotice(conn, "TOTP: add this to your authenticator, then run TOTP CONFIRM <code>", .{});
            try channelNotice(conn, "TOTP: secret {s}", .{&secret});
            if (otpauth.len != 0) try channelNotice(conn, "TOTP: {s}", .{otpauth});
            return;
        }

        if (std.ascii.eqlIgnoreCase(sub, "CONFIRM")) {
            if (parsed.param_count < 2)
                return self.failReply(conn, "TOTP", "NEED_MORE_PARAMS", "Usage: TOTP CONFIRM <code>");
            const code = parsed.paramSlice()[1];
            const outcome = blk: {
                var change = self.totp.stageConfirmation(account, code, totpUnixSeconds());
                defer change.deinit();
                if (change.outcome == .ok) {
                    // The borrowed secret stays pinned by the TOTP lock. The
                    // batch revokes sst_ authority in the same durable cut.
                    svc.totpPolicyCommit(account, change.secretB32()) catch
                        return self.failReply(conn, "TOTP", "TEMPORARILY_UNAVAILABLE", "Could not persist TOTP policy; try again after storage recovery");
                    change.commitConfirmation();
                }
                break :blk change.outcome;
            };
            switch (outcome) {
                .ok => {
                    return channelNotice(conn, "TOTP: two-factor authentication is now ACTIVE — future logins require a code", .{});
                },
                .bad_code => return self.failReply(conn, "TOTP", "INVALID_CODE", "Incorrect code; try the current one from your authenticator"),
                .not_enrolled => return self.failReply(conn, "TOTP", "NO_PENDING", "Nothing to confirm — run TOTP ENROLL first"),
            }
        }

        return self.failReply(conn, "TOTP", "INVALID_SUBCOMMAND", "Usage: TOTP <ENROLL|CONFIRM <code>|DISABLE|STATUS>");
    }

    /// `RECOVERYCODES <STATUS|GENERATE [password]|CLEAR [password]|LOGIN <account> <code>>`
    /// Offline single-use account recovery codes (Era 2 B8). GENERATE replaces the
    /// entire set and returns plaintext once; LOGIN consumes a code and logs in
    /// (bypasses password + TOTP). Codes are never re-listed after generation.
    pub fn handleRecoveryCodes(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.authenticationAvailable())
            return self.failReply(conn, "RECOVERYCODES", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        const svc = self.account_services orelse return self.failReply(conn, "RECOVERYCODES", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        const p = parsed.paramSlice();
        if (p.len < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"RECOVERYCODES"}, "Usage: RECOVERYCODES <STATUS|GENERATE|CLEAR|LOGIN>");
            return;
        }
        const sub = p[0];
        if (std.ascii.eqlIgnoreCase(sub, "STATUS")) {
            const account = conn.session.account() orelse
                return self.failReply(conn, "RECOVERYCODES", "ACCOUNT_REQUIRED", "Log in before checking recovery codes");
            const remaining = svc.recoveryCodesRemaining(account);
            try channelNotice(conn, "RECOVERYCODES: {d} unused code{s}", .{ remaining, if (remaining == 1) "" else "s" });
            return;
        }
        if (std.ascii.eqlIgnoreCase(sub, "GENERATE")) {
            const account = conn.session.account() orelse
                return self.failReply(conn, "RECOVERYCODES", "ACCOUNT_REQUIRED", "Log in before generating recovery codes");
            if (!conn.is_tls) return self.failReply(conn, "RECOVERYCODES", "INSECURE_TRANSPORT", "Generate recovery codes only over TLS");
            if (p.len >= 2) {
                _ = svc.identifyAccount(account, p[1]) catch |err| switch (err) {
                    error.AuthFailed => return self.failReply(conn, "RECOVERYCODES", "AUTH_FAILED", "Password incorrect"),
                    else => return self.failReply(conn, "RECOVERYCODES", "INTERNAL_ERROR", "Could not verify password"),
                };
            }
            const io = self.config.crypto_io orelse
                return self.failReply(conn, "RECOVERYCODES", "TEMPORARILY_UNAVAILABLE", "No randomness source configured");
            var plain: [services_mod.Services.recovery_code_count][services_mod.Services.recovery_code_raw_len]u8 = undefined;
            var code_slices: [services_mod.Services.recovery_code_count][]const u8 = undefined;
            var i: usize = 0;
            while (i < plain.len) : (i += 1) {
                var raw: [services_mod.Services.recovery_code_raw_len]u8 = undefined;
                io.random(&raw);
                const alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
                for (&plain[i], raw) |*out, b| out.* = alphabet[b % alphabet.len];
                code_slices[i] = plain[i][0..];
            }
            svc.recoveryCodesReplace(account, code_slices[0..]) catch
                return self.failReply(conn, "RECOVERYCODES", "INTERNAL_ERROR", "Could not store recovery codes");
            try channelNotice(conn, "RECOVERYCODES: generated {d} single-use codes — copy them now; they will not be shown again", .{plain.len});
            i = 0;
            while (i < plain.len) : (i += 1) {
                var shown: [11]u8 = undefined;
                @memcpy(shown[0..5], plain[i][0..5]);
                shown[5] = '-';
                @memcpy(shown[6..11], plain[i][5..10]);
                try channelNotice(conn, "RECOVERYCODES: {d}. {s}", .{ i + 1, shown[0..] });
            }
            return;
        }
        if (std.ascii.eqlIgnoreCase(sub, "CLEAR")) {
            const account = conn.session.account() orelse
                return self.failReply(conn, "RECOVERYCODES", "ACCOUNT_REQUIRED", "Log in before clearing recovery codes");
            if (p.len >= 2) {
                _ = svc.identifyAccount(account, p[1]) catch |err| switch (err) {
                    error.AuthFailed => return self.failReply(conn, "RECOVERYCODES", "AUTH_FAILED", "Password incorrect"),
                    else => return self.failReply(conn, "RECOVERYCODES", "INTERNAL_ERROR", "Could not verify password"),
                };
            }
            svc.recoveryCodesClear(account) catch {};
            try channelNotice(conn, "RECOVERYCODES: all recovery codes cleared", .{});
            return;
        }
        if (std.ascii.eqlIgnoreCase(sub, "LOGIN")) {
            if (p.len < 3) {
                return self.failReply(conn, "RECOVERYCODES", "NEED_MORE_PARAMS", "Usage: RECOVERYCODES LOGIN <account> <code>");
            }
            const account = p[1];
            var code_buf: [64]u8 = undefined;
            var code_len: usize = 0;
            for (p[2]) |c| {
                if (c == '-' or c == ' ') continue;
                if (code_len >= code_buf.len) break;
                code_buf[code_len] = std.ascii.toUpper(c);
                code_len += 1;
            }
            const code = code_buf[0..code_len];
            svc.recoveryCodeConsume(account, code) catch |err| switch (err) {
                error.AuthFailed, error.NotFound => return self.failReply(conn, "RECOVERYCODES", "AUTH_FAILED", "Invalid or already-used recovery code"),
                else => return self.failReply(conn, "RECOVERYCODES", "INTERNAL_ERROR", "Could not consume recovery code"),
            };
            self.finishLogin(conn, account) catch |err| switch (err) {
                error.StorePoisoned => return self.failReply(conn, "RECOVERYCODES", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery"),
                else => return err,
            };
            try channelNotice(conn, "RECOVERYCODES: login ok — that code is now spent", .{});
            return;
        }
        return self.failReply(conn, "RECOVERYCODES", "INVALID_SUBCOMMAND", "Usage: RECOVERYCODES <STATUS|GENERATE|CLEAR|LOGIN>");
    }

    /// `WELCOME <ADD :line | CLEAR | SHOW>` — oper-managed network onboarding
    /// pack delivered once per account on first login (backed by welcome_pack).
    pub fn handleWelcome(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const p = parsed.paramSlice();
        if (p.len == 0 or std.ascii.eqlIgnoreCase(p[0], "SHOW")) {
            for (self.welcome.lines()) |l| {
                var b: [default_reply_bytes]u8 = undefined;
                const line = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :WELCOME :{s}\r\n", .{ self.serverName(), conn.session.displayName(), l }) catch continue;
                try emitReplyLine(conn, line);
            }
            try self.noticeTo(conn, "WELCOME: end of pack");
            return;
        }
        if (!conn.session.isOper()) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied- You're not an IRC operator");
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "CLEAR")) {
            self.welcome.setLines(&.{}) catch {};
            try self.noticeTo(conn, "WELCOME pack cleared");
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "ADD") and p.len >= 2 and p[1].len != 0) {
            // Rebuild the pack = current lines + the new one, via independent
            // dupes so setLines never aliases the pack's own storage.
            var tmp: std.ArrayListUnmanaged([]const u8) = .empty;
            defer {
                for (tmp.items) |it| self.allocator.free(it);
                tmp.deinit(self.allocator);
            }
            for (self.welcome.lines()) |l| try tmp.append(self.allocator, try self.allocator.dupe(u8, l));
            try tmp.append(self.allocator, try self.allocator.dupe(u8, p[1]));
            self.welcome.setLines(tmp.items) catch {
                try self.noticeTo(conn, "WELCOME: could not add (limit or invalid)");
                return;
            };
            try self.noticeTo(conn, "WELCOME line added");
            return;
        }
        try self.noticeTo(conn, "Usage: WELCOME <ADD :line | CLEAR | SHOW>");
    }

    /// On login, deliver the onboarding pack to a brand-new account exactly once.
    fn deliverWelcome(self: *LinuxServer, conn: *ConnState) void {
        const account = conn.session.account() orelse return;
        const lines = (self.welcome.deliverOnce(account) catch return) orelse return;
        for (lines) |l| {
            var b: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :[Welcome] {s}\r\n", .{ self.serverName(), conn.session.displayName(), l }) catch continue;
            emitReplyLine(conn, line) catch {};
        }
    }

    /// On login, join the account's auto-join channels.
    fn applyAutojoin(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) void {
        const account = conn.session.account() orelse return;
        const chans = self.autojoins.list(account) catch return;
        for (chans) |c| self.joinOne(id, conn, c, null, 0) catch {};
    }

    /// Attach a newly logged-in session-sync client to the channel projection of
    /// its already-live same-account/same-nick siblings. Each socket becomes a
    /// real World member (so it receives every channel event and can speak from
    /// that socket), while the attach is rendered only to the new client rather
    /// than as a duplicate logical JOIN to everyone else.
    fn syncLiveSessionChannels(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, account: []const u8) void {
        if (!conn.session.hasCap(.onyx_session_sync)) return;
        const cid = monitorIdFromClient(id);
        const handle = self.sessions.resumeHandleForClient(account, cid) orelse return;
        if (tokenIsNull(handle.token)) return;
        const sessions = self.sessions.copySessionsAlloc(self.allocator, account) catch return;
        defer self.allocator.free(sessions);

        var channel_it = self.world.channels.iterator();
        while (channel_it.next()) |entry| {
            const channel = entry.key_ptr.*;
            if (self.world.isMember(channel, worldIdFromClient(id))) continue;

            var inherited = world_model.MemberModes.empty();
            var found = false;
            for (sessions) |session| {
                if (!session.attached or session.client == cid) continue;
                if (!std.crypto.timing_safe.eql(sessions_mod.Token, session.token, handle.token)) continue;
                const sibling_id = clientIdFromMonitor(session.client);
                const sibling = self.connFor(sibling_id) orelse continue;
                const sibling_account = sibling.session.account() orelse continue;
                if (!std.ascii.eqlIgnoreCase(sibling_account, account)) continue;
                if (!std.ascii.eqlIgnoreCase(sibling.session.displayName(), conn.session.displayName())) continue;
                const modes = self.world.memberModes(channel, worldIdFromClient(sibling_id)) orelse continue;
                inherited.bits |= modes.bits;
                found = true;
            }
            if (!found) continue;
            const pending = self.armLocalChannelProjectionForClient(
                id,
                conn,
                channel,
                true,
                inherited.bits,
            ) catch continue;
            if (pending) |work| _ = self.projectLocalChannelProjection(work, true);
        }
    }

    fn sendJoinToAttachment(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8) !void {
        var prefix_buf: [256]u8 = undefined;
        const prefix = try clientPrefix(conn, &prefix_buf);
        var plain_buf: [default_reply_bytes]u8 = undefined;
        const plain = try formatMessage(&plain_buf, prefix, "JOIN", &.{channel}, null);
        var ext_buf: [default_reply_bytes]u8 = undefined;
        const account = conn.session.account() orelse "*";
        const ext = try formatMessage(&ext_buf, prefix, "JOIN", &.{ channel, account }, conn.session.realname());
        var tag_buf: [48]u8 = undefined;
        try self.deliverTimed(id, serverTimeTag(&tag_buf), if (conn.session.hasCap(.extended_join)) ext else plain);
    }

    /// Collect every live local transport in `id`'s exact reusable-token group.
    /// Account equality is deliberately insufficient: independently issued
    /// sessions remain separate authority domains even when they render the same
    /// nick. The caller supplies an empty list and performs this before mutation,
    /// so allocation failure cannot leave only part of a logical identity updated.
    fn collectAttachedExactTokenClients(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        out: *std.ArrayList(client_model.ClientId),
    ) std.mem.Allocator.Error!void {
        try out.append(self.allocator, id);
        const account = conn.session.account() orelse return;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return;
        // The all-zero value is the untracked/CSPRNG-unavailable sentinel, not a
        // shared credential. Equal sentinels must never merge independent clients.
        if (tokenIsNull(handle.token)) return;
        const rows = try self.sessions.copySessionsAlloc(self.allocator, account);
        defer self.allocator.free(rows);
        for (rows) |row| {
            if (!row.attached or row.client == monitorIdFromClient(id)) continue;
            if (!std.crypto.timing_safe.eql(sessions_mod.Token, row.token, handle.token)) continue;
            const sibling_id = clientIdFromMonitor(row.client);
            const sibling = self.connFor(sibling_id) orelse continue;
            if (sibling.closing or sibling.s2s != null or sibling.s2s_secured != null) continue;
            const sibling_account = sibling.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(sibling_account, account)) continue;
            try out.append(self.allocator, sibling_id);
        }
    }

    /// Resolve live local attachments from an already-authenticated
    /// `(account, token)` authority (for inbound mesh events where there may be
    /// no single World owner). Unlike account session-sync this is mandatory
    /// exact-token fan-out and never widens through a shared rendered nick.
    fn collectAttachedTokenAuthorityClients(
        self: *LinuxServer,
        account: []const u8,
        token: sessions_mod.Token,
        out: *std.ArrayList(client_model.ClientId),
    ) std.mem.Allocator.Error!void {
        if (tokenIsNull(token)) return;
        const rows = try self.sessions.copySessionsAlloc(self.allocator, account);
        defer self.allocator.free(rows);
        for (rows) |row| {
            if (!row.attached or !std.crypto.timing_safe.eql(sessions_mod.Token, row.token, token)) continue;
            const id = clientIdFromMonitor(row.client);
            const conn = self.connFor(id) orelse continue;
            if (conn.closing or conn.s2s != null or conn.s2s_secured != null) continue;
            const current_account = conn.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(current_account, account)) continue;
            try out.append(self.allocator, id);
        }
    }

    fn clientsShareExactToken(
        self: *LinuxServer,
        left_id: client_model.ClientId,
        left: *ConnState,
        right_id: client_model.ClientId,
        right: *ConnState,
    ) bool {
        if (left_id.eql(right_id)) return true;
        const left_account = left.session.account() orelse return false;
        const right_account = right.session.account() orelse return false;
        if (!std.ascii.eqlIgnoreCase(left_account, right_account)) return false;
        const left_handle = self.sessions.resumeHandleForClient(left_account, monitorIdFromClient(left_id)) orelse return false;
        const right_handle = self.sessions.resumeHandleForClient(right_account, monitorIdFromClient(right_id)) orelse return false;
        if (tokenIsNull(left_handle.token) or tokenIsNull(right_handle.token)) return false;
        return std.crypto.timing_safe.eql(sessions_mod.Token, left_handle.token, right_handle.token);
    }

    /// Prepare one durable desired channel image before the command mutates
    /// World. Untracked/anonymous clients have no reusable token and therefore
    /// retain the historical single-connection path. For a real token, however,
    /// arm is the acceptance boundary: allocation/capacity failure leaves World
    /// untouched, while success makes the intent retryable across every row in
    /// the exact token group.
    const ReversibleLocalChannelProjectionArm = struct {
        work: ?sessions_mod.LocalChannelProjectionWork,
        previous: ?sessions_mod.LocalChannelProjection,
    };

    fn armReversibleLocalChannelProjectionForClient(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        present: bool,
        member_mode_bits: u8,
    ) !ReversibleLocalChannelProjectionArm {
        const account = conn.session.account() orelse return .{ .work = null, .previous = null };
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse
            return .{ .work = null, .previous = null };
        if (tokenIsNull(handle.token)) return .{ .work = null, .previous = null };
        const armed = try self.sessions.armTokenLocalChannelProjectionWithPrevious(
            handle.token,
            channel,
            present,
            member_mode_bits,
        );
        return .{
            .work = .{ .token = handle.token, .projection = armed.intent },
            .previous = armed.previous,
        };
    }

    fn armLocalChannelProjectionForClient(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        present: bool,
        member_mode_bits: u8,
    ) !?sessions_mod.LocalChannelProjectionWork {
        return (try self.armReversibleLocalChannelProjectionForClient(
            id,
            conn,
            channel,
            present,
            member_mode_bits,
        )).work;
    }

    fn rollbackReversibleLocalChannelProjection(
        self: *LinuxServer,
        armed: ReversibleLocalChannelProjectionArm,
    ) void {
        const work = armed.work orelse return;
        _ = self.sessions.rollbackTokenLocalChannelProjectionArm(
            work.token,
            work.projection.generation,
            armed.previous,
        );
    }

    /// Replace an already-armed same-channel intent with its final desired
    /// member modes. First arm allocated every missing row journal; replacement
    /// of that same channel is consequently allocation-free and capacity-safe.
    fn finalizeLocalChannelProjection(
        self: *LinuxServer,
        armed: sessions_mod.LocalChannelProjectionWork,
        present: bool,
        member_mode_bits: u8,
    ) sessions_mod.LocalChannelProjectionWork {
        const projection = self.sessions.armTokenLocalChannelProjection(
            armed.token,
            armed.projection.channel(),
            present,
            member_mode_bits,
        ) catch unreachable;
        return .{ .token = armed.token, .projection = projection };
    }

    /// Atomically bootstrap one owner-local attachment that is absent from a
    /// desired-present projection. Render JOIN/topic/NAMES into an isolated
    /// plaintext capture while the temporary World row supplies the exact NAMES
    /// view. Nothing reaches the socket until the complete bounded batch exists.
    /// A render/overflow failure rolls the temporary row back; after enqueue is
    /// attempted output may be irreversible, so poison/target loss retains both
    /// World state and the journal for reconnect/resume repair.
    fn bootstrapProjectedChannel(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        modes: world_model.MemberModes,
    ) bool {
        if (conn.reply_capture != null) return false;
        // Size the isolated bootstrap from this connection's actual remaining
        // SendQ rather than a fixed six-arena estimate. Large complete NAMES
        // bursts can legitimately exceed that legacy ceiling; the capture and
        // SendQ checks still bound memory and abort before World publication.
        const inline_queued = conn.send_len - conn.send_offset;
        const queued = std.math.add(usize, inline_queued, conn.send_overflow.items.len) catch return false;
        if (queued >= conn.sendq_cap) return false;
        const capture_storage = self.allocator.alloc(u8, conn.sendq_cap - queued) catch return false;
        defer self.allocator.free(capture_storage);
        var capture = ReplyCapture{ .buf = capture_storage };

        self.world.restoreMember(channel, worldIdFromClient(id), modes) catch return false;
        conn.reply_capture = &capture;
        const rendered = blk: {
            self.sendJoinToAttachment(id, conn, channel) catch break :blk false;
            self.sendTopicReply(conn, channel) catch break :blk false;
            if (!conn.session.hasCap(.no_implicit_names))
                self.sendNames(conn, channel) catch break :blk false;
            break :blk !capture.overflowed;
        };
        conn.reply_capture = null;
        if (!rendered) {
            self.world.part(channel, worldIdFromClient(id)) catch {};
            return false;
        }

        return self.enqueueDeliveryMaybeClose(id, capture.captured(), false, "Client quit") == .delivered;
    }

    /// Apply one journaled exact-token channel image to every currently attached
    /// local transport. A generation re-read is the gate before any World write;
    /// stale work is ignored, detached-only or temporarily unresolved groups are
    /// retained, and completion uses generation CAS so a newer same-channel
    /// command can never be erased by an older retry.
    fn projectLocalChannelProjection(
        self: *LinuxServer,
        work: sessions_mod.LocalChannelProjectionWork,
        authority_published: bool,
    ) bool {
        var candidate = work;
        // A same-channel replacement can race the independent SessionStore lock
        // while this projector allocates its row snapshot. Chase boundedly so the
        // newest accepted image is normally applied in this turn, never the stale
        // copy supplied by the retry cursor.
        for (0..sessions_mod.local_channel_projection_capacity + 1) |_| {
            const observed = self.sessions.tokenLocalChannelProjection(
                candidate.token,
                candidate.projection.channel(),
            ) orelse return true;
            if (observed.generation != candidate.projection.generation) {
                candidate.projection = observed;
                continue;
            }

            var account_buf: [session_replica_account_max]u8 = undefined;
            const match = self.sessions.findByTokenInto(candidate.token, &account_buf) orelse return false;
            const rows = self.sessions.copySessionsAlloc(self.allocator, match.account) catch return false;
            defer self.allocator.free(rows);

            // Re-read after every fallible preparation and immediately before the
            // first World write. CAS protects clearing, but only this guard keeps
            // a stale retry from transiently applying obsolete state.
            const current = self.sessions.tokenLocalChannelProjection(
                candidate.token,
                candidate.projection.channel(),
            ) orelse return true;
            if (current.generation != candidate.projection.generation) {
                candidate.projection = current;
                continue;
            }

            var exact_rows: usize = 0;
            var has_detached = false;
            for (rows) |row| {
                if (!std.crypto.timing_safe.eql(sessions_mod.Token, row.token, candidate.token)) continue;
                exact_rows += 1;
                // Detached snapshots are not patched by this foundation. Retain
                // the journal for mixed as well as detached-only groups so a later
                // RESUME can never restore stale membership over a cleared intent.
                // Live siblings still converge now; a ghost must not block their
                // repair merely because it prevents the final CAS-clear.
                if (!row.attached) has_detached = true;
            }
            if (exact_rows == 0) return false;

            var complete = true;
            var representative: ?struct { id: client_model.ClientId, conn: *ConnState } = null;
            const desired_modes = world_model.MemberModes{ .bits = current.member_mode_bits };
            for (rows) |row| {
                if (!std.crypto.timing_safe.eql(sessions_mod.Token, row.token, candidate.token)) continue;
                if (!row.attached) continue;
                const id = clientIdFromMonitor(row.client);
                const conn = self.connFor(id) orelse {
                    complete = false;
                    continue;
                };
                if (conn.closing or conn.s2s != null or conn.s2s_secured != null) {
                    complete = false;
                    continue;
                }
                const account = conn.session.account() orelse {
                    complete = false;
                    continue;
                };
                if (!std.ascii.eqlIgnoreCase(account, match.account)) {
                    complete = false;
                    continue;
                }
                if (representative == null) representative = .{ .id = id, .conn = conn };
                const wid = worldIdFromClient(id);

                // A reactor may mutate shared World under the global write lock,
                // but only the connection's owner may append its JOIN bootstrap.
                // Foreign rows are therefore verification-only in this turn; the
                // same fair journal is retried by every reactor timer.
                if (id.shard != self.rx().shard_id) {
                    const modes = self.world.memberModes(current.channel(), wid);
                    if (current.present) {
                        if (modes == null or modes.?.bits != desired_modes.bits) complete = false;
                    } else if (modes != null) {
                        complete = false;
                    }
                    continue;
                }

                if (current.present) {
                    const was_member = self.world.isMember(current.channel(), wid);
                    if (was_member) {
                        self.world.restoreMember(current.channel(), wid, desired_modes) catch {
                            complete = false;
                            continue;
                        };
                    } else if (!self.bootstrapProjectedChannel(id, conn, current.channel(), desired_modes)) {
                        complete = false;
                        continue;
                    }
                } else if (self.world.channelExists(current.channel()) and
                    self.world.isMember(current.channel(), wid))
                {
                    self.world.part(current.channel(), wid) catch {
                        complete = false;
                        continue;
                    };
                }
            }
            if (!complete) return false;
            // Command paths publish their full token image before calling us.
            // A retry reached after an accepted command aborted on a fallible
            // World step has no such caller, so finish authority + sidecar here
            // before CAS-clearing the only durable intent.
            if (!authority_published and !has_detached) {
                const source = representative orelse return false;
                _ = self.commitPortableSessionMutation(source.id, source.conn);
                const rendered_identity_survives = !current.present and
                    self.renderedNickSurvivesTokenRemoval(
                        source.id,
                        source.conn,
                        current.channel(),
                        source.conn.session.displayName(),
                    );
                if (!rendered_identity_survives and !source.conn.session_mesh_announce_pending)
                    self.announceMembership(
                        current.channel(),
                        source.conn.session.displayName(),
                        @truncate(if (current.present) current.member_mode_bits else 0),
                        current.present,
                        membershipIdentityOf(source.conn),
                        "",
                    );
            }
            if (has_detached) return false;
            if (self.sessions.clearTokenLocalChannelProjection(
                candidate.token,
                current.channel(),
                current.generation,
            )) return true;
            if (self.sessions.tokenLocalChannelProjection(candidate.token, current.channel())) |newer| {
                candidate.projection = newer;
                continue;
            }
            return true;
        }
        return false;
    }

    /// Bounded, fair timer/UPGRADE retry for prepared local World intents.
    fn retryDirtyLocalChannelProjections(self: *LinuxServer) void {
        var work_buf: [session_replica_dirty_retry_batch]sessions_mod.LocalChannelProjectionWork = undefined;
        const work = self.sessions.dirtyLocalProjectionsInto(&work_buf);
        for (work) |pending| _ = self.projectLocalChannelProjection(pending, false);
    }

    /// Channel status belongs to the logical token group. Keep every attached
    /// local transport's World membership byte-identical after MODE so any
    /// client can immediately exercise the same voice/operator authority.
    fn mirrorTokenGroupMemberModes(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        modes: world_model.MemberModes,
    ) void {
        const account = conn.session.account() orelse return;
        const cid = monitorIdFromClient(id);
        const handle = self.sessions.resumeHandleForClient(account, cid) orelse return;
        if (tokenIsNull(handle.token)) return;
        const rows = self.sessions.copySessionsAlloc(self.allocator, account) catch return;
        defer self.allocator.free(rows);
        for (rows) |row| {
            if (!row.attached or row.client == cid) continue;
            if (!std.crypto.timing_safe.eql(sessions_mod.Token, row.token, handle.token)) continue;
            const sibling_id = clientIdFromMonitor(row.client);
            const sibling = self.connFor(sibling_id) orelse continue;
            if (sibling.closing or sibling.s2s != null or sibling.s2s_secured != null) continue;
            const sibling_account = sibling.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(sibling_account, account)) continue;
            self.world.restoreMember(channel, worldIdFromClient(sibling_id), modes) catch {};
        }
    }

    /// PART is a logical-session action: remove every local attachment sharing
    /// the token, after the single PART line has been delivered to all of them.
    fn partTokenGroupChannel(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8) void {
        const account = conn.session.account() orelse {
            self.world.part(channel, worldIdFromClient(id)) catch {};
            return;
        };
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse {
            self.world.part(channel, worldIdFromClient(id)) catch {};
            return;
        };
        if (tokenIsNull(handle.token)) {
            self.world.part(channel, worldIdFromClient(id)) catch {};
            return;
        }
        const rows = self.sessions.copySessionsAlloc(self.allocator, account) catch {
            self.world.part(channel, worldIdFromClient(id)) catch {};
            return;
        };
        defer self.allocator.free(rows);
        for (rows) |row| {
            if (!row.attached) continue;
            if (!std.crypto.timing_safe.eql(sessions_mod.Token, row.token, handle.token)) continue;
            const sibling_id = clientIdFromMonitor(row.client);
            const sibling = self.connFor(sibling_id) orelse continue;
            if (sibling.closing or sibling.s2s != null or sibling.s2s_secured != null) continue;
            const sibling_account = sibling.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(sibling_account, account)) continue;
            self.world.part(channel, worldIdFromClient(sibling_id)) catch {};
        }
    }

    fn completeLocalChannelRemoval(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        nick: []const u8,
        projection: ?sessions_mod.LocalChannelProjectionWork,
        publish_absence: bool,
    ) void {
        self.partTokenGroupChannel(id, conn, channel);
        _ = self.commitPortableSessionMutation(id, conn);
        if (projection) |pending| _ = self.projectLocalChannelProjection(pending, true);
        if (publish_absence and !conn.session_mesh_announce_pending)
            self.announceMembership(channel, nick, 0, false, membershipIdentityOf(conn), "");
    }

    fn renderedNickSurvivesTokenRemoval(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        nick: []const u8,
    ) bool {
        var members = self.world.memberIterator(channel) orelse return false;
        while (members.next()) |member| {
            const other_id = clientIdFromWorld(member.*);
            const other = self.connFor(other_id) orelse continue;
            if (!std.ascii.eqlIgnoreCase(other.session.displayName(), nick)) continue;
            if (self.clientsShareExactToken(id, conn, other_id, other)) continue;
            return true;
        }
        return false;
    }

    fn completeLocalMemberModeMutation(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        nick: []const u8,
        modes: world_model.MemberModes,
        projection: ?sessions_mod.LocalChannelProjectionWork,
        setter: []const u8,
    ) void {
        // A durable projection owns exact-token fan-out (including owner-local
        // bootstrap for a missing row). The legacy mirror is only a fallback for
        // unjournaled/sentinel sessions; running it first could materialize a
        // foreign World row before that socket receives its JOIN bootstrap.
        if (projection == null) self.mirrorTokenGroupMemberModes(id, conn, channel, modes);
        _ = self.commitPortableSessionMutation(id, conn);
        if (projection) |pending| _ = self.projectLocalChannelProjection(pending, true);
        if (!conn.session_mesh_announce_pending)
            self.announceMembership(channel, nick, @truncate(modes.bits), true, membershipIdentityOf(conn), setter);
    }

    /// Give an authenticated reconnect a bounded window to present an exact
    /// SESSION RESUME credential before account autojoin. A same-account login
    /// is not proof of ownership of any particular detached device session, so
    /// this probe NEVER restores or consumes the newest ghost implicitly.
    fn restoreDetachedBeforeAutojoin(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, account: []const u8) bool {
        const cid = monitorIdFromClient(id);
        const candidate = self.sessions.copyNewestDetachedSnapshotInAccount(self.allocator, account, cid) catch null;
        const has_local_candidate = candidate != null;
        if (candidate) |detached| self.allocator.free(detached.snapshot);
        // A portable resume may exist only on a peer, so the local SessionStore
        // cannot always predict it before the post-001 SESSION RESUME command.
        // Any client that negotiated the session-sync contract gets the same
        // bounded window; SESSION TOKEN releases a genuinely fresh login at once.
        if (!has_local_candidate and !conn.session.hasCap(.onyx_session_sync)) return false;

        conn.resume_autojoin_deferred = true;
        conn.resume_autojoin_deadline_ms = self.nowMs() + 2_000;
        return true;
    }

    /// Arm the resume/autojoin hold before E2EE eligibility is enforced. This is
    /// required when no-evict bootstrap tracking leaves an at-cap reconnect
    /// intentionally untracked: exact resume must get a bounded chance to replace
    /// its selected detached row, while all ordinary participation stays gated.
    fn armBoundedExactResumeHoldIfNeeded(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
    ) void {
        const account = conn.session.account() orelse return;
        if (self.attachmentHasReusableSession(id)) return;
        var rows_buf: [sessions_mod.snapshot_capacity]sessions_mod.Session = undefined;
        var has_detached_attachment = false;
        for (self.sessions.sessionsInto(account, &rows_buf)) |row| {
            if (!row.attached and row.attachment_id != null) {
                has_detached_attachment = true;
                break;
            }
        }
        if (!has_detached_attachment and !conn.session.hasCap(.onyx_session_sync)) return;
        conn.resume_autojoin_deferred = true;
        conn.resume_autojoin_deadline_ms = self.nowMs() + 2_000;
    }

    fn finishDeferredSessionAutojoin(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, restored: bool) void {
        if (!conn.resume_autojoin_deferred) return;
        conn.resume_autojoin_deferred = false;
        conn.resume_autojoin_deadline_ms = 0;
        // The one-shot TOKEN preservation is meaningful only inside this bounded
        // retry window. Expiry (or any explicit finish) releases both latches so
        // a stale WARN cannot refuse every later Helix UPGRADE indefinitely.
        conn.preserve_resume_credential_once = false;
        if (!restored) self.applyAutojoin(id, conn);
    }

    fn sweepDeferredSessionAutojoins(self: *LinuxServer) void {
        const now = self.nowMs();
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            const conn = entry.value;
            if (conn.resume_autojoin_deferred) {
                if (now < conn.resume_autojoin_deadline_ms) continue;
                if (conn.session.hasCap(.onyx_e2ee) and
                    conn.session.account() != null and
                    !self.attachmentHasReusableSession(entry.id))
                {
                    conn.resume_autojoin_deferred = false;
                    conn.resume_autojoin_deadline_ms = 0;
                    conn.preserve_resume_credential_once = false;
                    retainCloseReason(conn, "E2EE exact session resume expired");
                    conn.closing = true;
                    self.failReply(
                        conn,
                        "E2EEGROUP",
                        "SESSION_UNAVAILABLE",
                        "exact session resume window expired",
                    ) catch {};
                    continue;
                }
                self.finishDeferredSessionAutojoin(entry.id, conn, false);
                continue;
            }
            // A manual RESUME retry can arm credential preservation without an
            // account-autojoin hold. It owns the same bounded deadline and must
            // expire independently, otherwise no autojoin sweep can ever clear
            // it and every later UPGRADE remains refused.
            if (conn.preserve_resume_credential_once and
                conn.resume_autojoin_deadline_ms != 0 and
                now >= conn.resume_autojoin_deadline_ms)
            {
                conn.preserve_resume_credential_once = false;
                conn.resume_autojoin_deadline_ms = 0;
            }
        }
    }

    fn applyLoginJoinState(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) void {
        const account = conn.session.account() orelse return;
        self.syncLiveSessionChannels(id, conn, account);
        if (self.restoreDetachedBeforeAutojoin(id, conn, account)) return;
        self.applyAutojoin(id, conn);
    }

    /// `SHUN <mask> [secs] [:reason]` / `UNSHUN <mask>` — oper network mute.
    /// A shunned (non-oper) sender stays connected but their PRIVMSG/NOTICE are
    /// silently dropped. Bare `SHUN` lists active shuns.
    pub fn handleShun(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView, adding: bool) !void {
        return oper_cmd.handleShun(self, conn, parsed, adding);
    }

    /// `GLOBAL [<mask>|#chan] :<text>` — oper broadcast to all users (or a
    /// hostmask/channel audience). Delivered as a server NOTICE.
    pub fn handleGlobal(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleGlobal(self, id, conn, parsed);
    }

    fn persistWardMirror(self: *LinuxServer, conn: *ConnState, ward: warden.Ward) void {
        const svc = self.account_services orelse return;
        var scratch: [512]u8 = undefined;
        svc.persistWard(.{
            .match = ward.match.token(),
            .pattern = ward.pattern,
            .scope = ward.scope.token(),
            .action = ward.action.token(),
            .reason = ward.reason,
            .setter = ward.set_by,
            .created_ms = ward.created_ms,
            .expires_ms = ward.expires_ms,
        }, &scratch) catch {
            self.noticeTo(conn, "WARD: live entry added but persistent mirror failed") catch {};
        };
    }

    fn deleteWardMirror(self: *LinuxServer, match: warden.Match, pattern: []const u8) void {
        const svc = self.account_services orelse return;
        var scratch: [512]u8 = undefined;
        svc.deleteWard(match.token(), pattern, &scratch) catch {};
    }

    /// Persist a live SACCESS ADD to the durable store so the server-access
    /// firewall (DENY/GAG/GRANT/NOCHANNEL/NONICK) survives restart and hot
    /// rebuild. Mirrors `persistWardMirror`; best-effort, never blocks the live
    /// add (the in-memory `self.saccess` already holds the authoritative entry).
    fn persistSaccessMirror(self: *LinuxServer, entry: ircx_saccess.Entry) void {
        const svc = self.account_services orelse return;
        var scratch: [512]u8 = undefined;
        svc.persistSaccess(.{
            .entry_type = entry.entry_type.token(),
            .mask = entry.mask,
            .duration = entry.duration orelse 0,
            .reason = entry.reason orelse "",
        }, &scratch) catch {};
    }

    fn deleteSaccessMirror(self: *LinuxServer, entry_type: ircx_saccess.EntryType, mask: []const u8) void {
        const svc = self.account_services orelse return;
        var scratch: [512]u8 = undefined;
        svc.deleteSaccess(entry_type.token(), mask, &scratch) catch {};
    }

    fn clearSaccessMirror(self: *LinuxServer, entry_type: ?ircx_saccess.EntryType) void {
        const svc = self.account_services orelse return;
        const tok: ?[]const u8 = if (entry_type) |et| et.token() else null;
        svc.clearSaccess(tok) catch {};
    }

    pub fn addWardLive(
        self: *LinuxServer,
        conn: *ConnState,
        match: warden.Match,
        pattern: []const u8,
        scope: warden.Scope,
        action: warden.Action,
        secs: i64,
        reason: []const u8,
        audit_action: svc_operaudit.Action,
    ) !void {
        if (scope == .mesh) {
            switch (try self.twoPersonAdmit(conn, .ward_add, pattern)) {
                .waiting => return,
                .proceed, .confirmed => {},
            }
        }
        var policy_snap: ?PolicyUndo = self.snapshotWard() catch null;
        defer if (policy_snap) |*snap| self.destroyPolicyUndo(snap);
        const now = platform.realtimeMillis();
        const ward = warden.Ward{
            .match = match,
            .pattern = pattern,
            .scope = scope,
            .action = action,
            .reason = reason,
            .set_by = conn.session.displayName(),
            .created_ms = now,
            .expires_ms = if (secs > 0) now + secs * 1000 else 0,
        };
        self.warden.add(ward) catch {
            try self.noticeTo(conn, "WARD: could not add ward (limit or invalid input)");
            return;
        };
        if (policy_snap) |snap| {
            self.commitPolicy(snap);
            policy_snap = null;
        }
        self.persistWardMirror(conn, ward);
        // A `mesh`-scope ward propagates to every secured peer so already-running
        // nodes enforce it live. A `node`-scope ward stays local.
        if (scope == .mesh) self.broadcastMeshWard(ward, .add);
        // Act on already-connected clients now — a ban must bite during a live
        // raid, not only refuse the abuser's next reconnect.
        self.reapWardMatches();
        const proof_id = self.recordOperAudit(conn.session.displayName(), audit_action, pattern, if (reason.len != 0) reason else "WARD ADD");
        var b: [default_reply_bytes]u8 = undefined;
        const note = if (proof_id) |pid|
            std.fmt.bufPrint(&b, "WARD ADD {s} {s} {s}/{s} proof={s}", .{ match.token(), pattern, scope.token(), action.token(), pid[0..] }) catch return
        else
            std.fmt.bufPrint(&b, "WARD ADD {s} {s} {s}/{s}", .{ match.token(), pattern, scope.token(), action.token() }) catch return;
        try self.publishOperEvent(.oper_action, .notice, note);
    }

    pub fn deleteWardLive(self: *LinuxServer, conn: *ConnState, match: warden.Match, pattern: []const u8) !void {
        // Capture the entry's scope BEFORE removal so a mesh-scope removal can be
        // propagated to peers (the `remove` itself only returns a bool). Resolve it
        // by a direct registry lookup so the scope read is correct regardless of how
        // many Wards share `match` (a bounded `list` copy could miss the entry).
        const was_mesh = if (self.warden.find(match, pattern)) |w| w.scope == .mesh else false;
        if (was_mesh) {
            switch (try self.twoPersonAdmit(conn, .ward_del, pattern)) {
                .waiting => return,
                .proceed, .confirmed => {},
            }
        }
        var policy_snap: ?PolicyUndo = if (was_mesh or self.warden.find(match, pattern) != null)
            self.snapshotWard() catch null
        else
            null;
        defer if (policy_snap) |*snap| self.destroyPolicyUndo(snap);
        const removed = self.warden.remove(match, pattern);
        if (removed) {
            if (policy_snap) |snap| {
                self.commitPolicy(snap);
                policy_snap = null;
            }
            self.deleteWardMirror(match, pattern);
            if (was_mesh) {
                // Propagate the removal so peers forget the network ban too. Only
                // (op, match, pattern) are load-bearing for a remove; the rest are
                // filler the receiver ignores.
                self.broadcastMeshWard(.{
                    .match = match,
                    .pattern = pattern,
                    .scope = .mesh,
                    .action = .expel,
                }, .remove);
            }
        }
        const status = if (removed) "removed" else "not found";
        const proof_id = self.recordOperAudit(conn.session.displayName(), .ward_del, pattern, status);
        var b: [default_reply_bytes]u8 = undefined;
        const note = if (proof_id) |pid|
            std.fmt.bufPrint(&b, "WARD DEL {s} {s}: {s} proof={s}", .{ match.token(), pattern, status, pid[0..] }) catch return
        else
            std.fmt.bufPrint(&b, "WARD DEL {s} {s}: {s}", .{ match.token(), pattern, status }) catch return;
        try self.publishOperEvent(.oper_action, .notice, note);
    }

    /// `WARD <ADD|DEL|LIST|TEST> …` — the unified network-ban command for admins
    /// and opers, replacing the legacy K/D/G/Z/X/Q-line alphabet with one
    /// orthogonal model (backed by the Warden registry: Match × Scope × Action).
    /// Oper-only.
    ///   ADD  <match> <pattern> [scope] [action] [duration_secs] [:reason]
    ///   DEL  <match> <pattern>
    ///   LIST [match]
    ///   TEST <match> <value>
    pub fn handleWard(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleWard(self, conn, parsed);
    }

    pub const WardAlias = enum { kline, dline, xline };

    pub fn handleWardAlias(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView, alias: WardAlias) !void {
        return oper_cmd.handleWardAlias(self, conn, parsed, alias);
    }

    /// ACCEPT [+nick|-nick|*|...] — caller-id (+g) allow list. Bare/`*` lists
    /// (RPL_ACCEPTLIST 281 / RPL_ENDOFACCEPT 282); +/- add/remove. Keyed by nick.
    pub fn handleAcceptCmd(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const owner = conn.session.displayName();
        if (parsed.param_count == 0) {
            try self.sendAcceptList(conn, owner);
            return;
        }
        const cmd = accept_list.parse(parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"ACCEPT"}, "Invalid ACCEPT");
            return;
        };
        for (cmd.slice()) |op| {
            switch (op.action) {
                .add => self.accepts.add(owner, op.nick) catch {},
                .remove => self.accepts.remove(owner, op.nick) catch {},
                .list => try self.sendAcceptList(conn, owner),
            }
        }
    }

    fn sendAcceptList(self: *LinuxServer, conn: *ConnState, owner: []const u8) !void {
        var nicks: [64][]const u8 = undefined;
        const got = self.accepts.list(owner, &nicks) catch nicks[0..0];
        for (got) |n| try queueNumeric(conn, .RPL_ACCEPTLIST, &.{n}, "");
        try queueNumeric(conn, .RPL_ENDOFACCEPT, &.{}, "End of /ACCEPT list");
    }

    /// USERIP <nick>... — like USERHOST but shows IP (340).
    pub fn handleUserip(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleUserip(self, conn, parsed);
    }

    /// Flag off returns `.proceed` and the caller runs the existing body.
    /// Flag on records the first oper and waits. A second distinct oper, for
    /// the same kind and target, inside the window, confirms. The same identity
    /// cannot confirm itself. A different kind or an expired window replaces
    /// the pending approval instead of confirming it.
    pub fn twoPersonAdmit(self: *LinuxServer, conn: *ConnState, kind: TwoPersonKind, target: []const u8) !TwoPersonAdmit {
        if (!self.config.two_person_rule) return .proceed;
        const identity = twoPersonIdentity(conn);
        const now = self.nowMs();
        if (self.two_person_pending) |pending| {
            const same = pending.kind == kind and std.ascii.eqlIgnoreCase(pending.targetSlice(), target);
            if (same and twoPersonStillOpen(now, pending.at_ms)) {
                if (std.ascii.eqlIgnoreCase(pending.identitySlice(), identity)) {
                    try self.noticeTo(conn, "waiting for a second operator");
                    return .waiting;
                }
                _ = self.recordOperAudit(identity, twoPersonAuditAction(kind), target, "two-person approval");
                self.two_person_pending = null;
                return .confirmed;
            }
        }
        var next = TwoPersonPending{ .kind = kind, .at_ms = now };
        next.identity_len = twoPersonCopy(&next.identity, identity) orelse {
            try self.noticeTo(conn, "waiting for a second operator");
            return .waiting;
        };
        next.target_len = twoPersonCopy(&next.target, target) orelse {
            try self.noticeTo(conn, "waiting for a second operator");
            return .waiting;
        };
        self.two_person_pending = next;
        _ = self.recordOperAudit(identity, twoPersonAuditAction(kind), target, "two-person approval");
        try self.noticeTo(conn, "waiting for a second operator");
        return .waiting;
    }

    /// DIE / RESTART — oper-only server lifecycle.
    ///   * DIE     — shut the server down (clear the run flag; the process exits
    ///               and stays down — no re-exec, no service-manager restart).
    ///   * RESTART — re-exec the on-disk binary IN PLACE: a clean restart that
    ///               re-reads config and rebinds, dropping all client state (unlike
    ///               the session-preserving USR2 UPGRADE). The listener fd is
    ///               carried across execve so the port stays bound through the
    ///               swap. Re-exec is Linux-only; on other platforms (or if the
    ///               re-exec machinery fails) RESTART falls back to clearing the
    ///               run flag so a supervising service manager can relaunch.
    pub fn handleDie(self: *LinuxServer, conn: *ConnState, cmd: []const u8) !void {
        return oper_cmd.handleDie(self, conn, cmd);
    }

    /// `UPGRADE` — oper-only hot in-place binary upgrade (Helix). Serializes every
    /// registered session into a sealed memfd arena, then re-execs the on-disk
    /// binary `--supervisor` preserving the listening socket, the arena, and every
    /// carried client socket (FD_CLOEXEC cleared), so the port stays bound and the
    /// successor re-attaches the live connections. TLS clients additionally carry
    /// their live engine state (suite + traffic secrets + record seqs + buffered
    /// bytes) so the encrypted stream survives the swap; failure to export any
    /// live TLS client refuses the complete UPGRADE. Established secured S2S links
    /// likewise must seal and resume in place. Only plaintext or unestablished
    /// hand-dialed links use a re-dial hint, while config-managed [mesh].connect
    /// peers re-dial through the mesh boot pass.
    /// wss browser clients are carried too: the WS adapter's partial framing
    /// state rides the v2 `.ws_session` capsule (see wsCarryable), so even a
    /// mid-frame browser client survives with no lost bytes.
    pub fn handleUpgrade(self: *LinuxServer, conn: *ConnState) !void {
        return self.handleUpgradeCommand(conn, &.{});
    }

    /// An explicit Windows target is copied into the deferred request because
    /// the parsed IRC line is gone before the owner reactor reaches its safe
    /// handoff point. No socket custody moves until that image is challenged.
    pub fn handleUpgradeCommand(self: *LinuxServer, conn: *ConnState, params: []const []const u8) !void {
        if (!self.requirePriv(conn, .server_restart)) return;
        if (params.len > 1 or (params.len == 1 and (builtin.os.tag != .windows or
            params[0].len < 3 or !std.ascii.isAlphabetic(params[0][0]) or
            params[0][1] != ':' or (params[0][2] != '\\' and params[0][2] != '/') or
            std.mem.indexOfAny(u8, params[0], "\x00\r\n\"") != null)))
        {
            try self.noticeTo(conn, "UPGRADE refused: use one fully qualified local Windows executable path");
            return;
        }
        // Compare the on-disk listener set before the upgrade is queued. SIGUSR2
        // is the signal the operator sends after this command, or after
        // `--check-config --against`, has already refused.
        if (try self.upgradeRefusedForListenerChange(conn)) return;
        if (params.len == 1) {
            if (self.rx().deferred_upgrade) |pending| switch (pending) {
                .windows_descriptor_rollover => {},
                else => {
                    try self.noticeTo(conn, "UPGRADE already pending on this reactor");
                    return;
                },
            };
            const io = self.config.crypto_io orelse return error.NativeUpgradeUnavailable;
            const running = self.config.exe_path orelse return error.NativeUpgradeUnavailable;
            const running_canonical = std.Io.Dir.cwd().realPathFileAlloc(io, running, self.allocator) catch {
                try self.noticeTo(conn, "UPGRADE refused: cannot verify running executable directory");
                return;
            };
            defer self.allocator.free(running_canonical);
            const executable = std.Io.Dir.cwd().realPathFileAlloc(io, params[0], self.allocator) catch {
                try self.noticeTo(conn, "UPGRADE refused: cannot open staged executable");
                return;
            };
            var queued = false;
            defer if (!queued) self.allocator.free(executable);
            const running_dir = std.fs.path.dirname(running_canonical) orelse return error.NativeUpgradeUnavailable;
            const target_dir = std.fs.path.dirname(executable) orelse return error.NativeUpgradeUnavailable;
            const target_name = std.fs.path.basename(executable);
            if (!std.ascii.eqlIgnoreCase(running_dir, target_dir) or
                target_name.len < "onyx-server.exe".len or
                !std.ascii.eqlIgnoreCase(target_name[0.."onyx-server".len], "onyx-server") or
                !std.ascii.eqlIgnoreCase(target_name[target_name.len - ".exe".len ..], ".exe"))
            {
                try self.noticeTo(conn, "UPGRADE refused: staged onyx-server executable must be beside the running image");
                return;
            }
            self.deferUpgrade(.{ .client_target = .{ .id = idFromToken(conn.token), .executable = executable } });
            queued = true;
            return;
        }
        self.deferUpgrade(.{ .client = idFromToken(conn.token) });
    }

    /// Ports the process is actually serving. Zero means that listener is off.
    /// This matches `config_format.listenerSetFromConfig` for the file that booted
    /// the process: TLS is `tls_port` only when main armed it, and WebSocket is
    /// the configured port only when `ws_enabled`.
    fn configuredListenerSet(self: *const LinuxServer) config_format.ListenerSet {
        return .{
            .irc = self.config.port,
            .tls = self.config.tls_port,
            .ws = if (self.config.ws_enabled) self.config.ws_port else 0,
            .webtransport = self.config.webtransport_port,
            .s2s = self.config.s2s_port,
            .media = self.config.media_port,
            .native_media = self.config.native_media_port,
        };
    }

    /// True when UPGRADE must stop before `deferUpgrade`. No config path means
    /// there is no on-disk listener delta to apply (tests and a path-less boot).
    /// A path that cannot be read or parsed also stops the upgrade: adopting
    /// blindly is how an operator would learn about a listener change too late.
    fn upgradeRefusedForListenerChange(self: *LinuxServer, conn: *ConnState) !bool {
        const path = self.config.config_path orelse return false;
        const io = self.config.crypto_io orelse {
            try self.noticeTo(conn, "UPGRADE refused: cannot read config to compare listeners; cold restart required");
            return true;
        };
        const text = std.Io.Dir.cwd().readFileAlloc(io, path, self.allocator, .limited(1 << 20)) catch {
            try self.noticeTo(conn, "UPGRADE refused: cannot read config file");
            return true;
        };
        defer self.allocator.free(text);
        var parsed = config_format.parseToml(self.allocator, text, self.config.config_resolver) catch {
            try self.noticeTo(conn, "UPGRADE refused: config parse error");
            return true;
        };
        defer parsed.deinit(self.allocator);
        if (config_format.listenerChangeError(self.configuredListenerSet(), config_format.listenerSetFromConfig(parsed))) |why| {
            try self.noticeTo(conn, why);
            return true;
        }
        return false;
    }

    /// Session replica dirty flags, pending Store staging, local channel
    /// projection journals, and deferred resume sidecars are predecessor-only
    /// convergence state. Never exec while any of them remains: first run one
    /// bounded retry pass for the wired lanes, then require every lane to be
    /// clean. A capacity/OOM failure refuses the upgrade and leaves the
    /// predecessor serving normally so housekeeping (or the next attempt) can
    /// finish the work without silently erasing an exact-token mutation.
    fn prepareSessionReplicaUpgradeBoundary(self: *LinuxServer) bool {
        self.retryDirtySessionReplicaTokens();
        self.retryDirtySessionReplicaProjections();
        self.retryDirtyLocalChannelProjections();
        self.retrySessionReplicaStoreStages();

        if (self.sessions.dirtyReplicaRowCount() != 0 or
            self.sessions.dirtyReplicaProjectionRowCount() != 0 or
            self.sessions.dirtyLocalProjectionRowCount() != 0 or
            self.session_replica_stage_retry_pending)
        {
            return false;
        }

        var ready = true;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                // These two resume/TOKEN handshake flags are intentionally
                // connection-local and are not in the current client capsule.
                // Refuse the short in-flight window instead of resetting it on
                // the successor (which could overwrite a valid credential or
                // skip the exact-session autojoin decision).
                if (conn.s2s == null and conn.s2s_secured == null and
                    (conn.preserve_resume_credential_once or conn.resume_autojoin_deferred))
                {
                    ready = false;
                }
                if (!conn.session_mesh_announce_pending) continue;
                // A pending slot that cannot be flushed is still a refusal. In
                // particular, `closing` is not part of the client capsule, so
                // skipping it here could resurrect a half-closed restored
                // identity in the successor with its old-nick retraction lost.
                if (conn.closing or conn.s2s != null or conn.s2s_secured != null) {
                    ready = false;
                    continue;
                }
                const id = slotClientId(reactor, i, slot.gen);
                if (conn.session_mesh_announce_token_bound and
                    !self.deferredSessionMeshAuthorityReady(id, conn))
                {
                    _ = self.publishCurrentSessionReplicaToken(conn.session_mesh_announce_token);
                    if (self.deferredSessionMeshAuthorityReady(id, conn)) {
                        self.flushDeferredSessionMeshAnnouncements(id, conn);
                    }
                }
                if (conn.session_mesh_announce_pending) ready = false;
            }
        }
        // Publishing a bound deferred token above can itself discover a failed
        // live projection or Pending-store stage. Recheck every predecessor-only
        // lane after the loop so a newly-created retry bit cannot cross execve.
        if (self.sessions.dirtyReplicaRowCount() != 0 or
            self.sessions.dirtyReplicaProjectionRowCount() != 0 or
            self.sessions.dirtyLocalProjectionRowCount() != 0 or
            self.session_replica_stage_retry_pending)
        {
            return false;
        }
        return ready;
    }

    /// Emit one UPGRADE progress line: a NOTICE to the requesting oper when the
    /// upgrade was issued by `/UPGRADE`, or a server-log line when it was
    /// triggered by SIGUSR2 (no requesting client). Best-effort — a failed
    /// notice never aborts an in-flight upgrade.
    fn upgradeNotice(self: *LinuxServer, requester: ?*ConnState, msg: []const u8) void {
        if (requester) |c| {
            self.noticeTo(c, msg) catch {};
        } else {
            srvLog("onyx-server: {s}\n", .{msg});
        }
    }

    fn deferredUpgradeRequester(self: *LinuxServer, request: DeferredUpgradeRequest) ?*ConnState {
        const id = switch (request) {
            .signal, .windows_descriptor_rollover => null,
            .client => |client| client,
            .client_target => |target| target.id,
        } orelse return null;
        if (id.shard != self.rx().shard_id) return null;
        return self.rx().clients.get(id);
    }

    fn deferredUpgradeNotice(self: *LinuxServer, request: DeferredUpgradeRequest, msg: []const u8) void {
        self.upgradeNotice(self.deferredUpgradeRequester(request), msg);
    }

    fn deferredUpgradeActor(self: *LinuxServer, request: DeferredUpgradeRequest) []const u8 {
        if (self.deferredUpgradeRequester(request)) |conn| return conn.session.displayName();
        return switch (request) {
            .windows_descriptor_rollover => "Windows descriptor rollover",
            else => "SIGUSR2",
        };
    }

    /// Open the target image once, execute that exact open file through
    /// `/proc/self/fd/<n>` in side-effect-free capability mode, and retain
    /// the descriptor for the final `execveat`. This both refuses incompatible
    /// rollbacks before any live fd becomes inheritable and prevents a deploy
    /// rename between probe and exec from changing the selected image.
    fn openCompatibleUpgradeTarget(
        self: *LinuxServer,
        binary_path: []const u8,
    ) anyerror!linux.fd_t {
        if (comptime builtin.os.tag != .linux) return error.Unsupported;
        const zpath = try self.allocator.dupeSentinel(u8, binary_path, 0);
        defer self.allocator.free(zpath);
        const open_rc = linux.open(zpath.ptr, .{ .ACCMODE = .RDONLY, .CLOEXEC = true }, 0);
        if (posix.errno(open_rc) != .SUCCESS) return error.UpgradeTargetOpenFailed;
        const executable_fd: linux.fd_t = @intCast(open_rc);
        errdefer closeFd(executable_fd);

        const io = self.config.crypto_io orelse return error.UpgradeProbeUnavailable;
        if (!try helix_live.probeUpgradeExecutableFd(self.allocator, io, executable_fd))
            return error.UpgradeTargetIncompatible;
        return executable_fd;
    }

    /// Core Helix UPGRADE: serialize every carried session into a sealed memfd
    /// arena, then re-exec the on-disk binary preserving the listener + client
    /// sockets. `requester` is the oper connection that ran `/UPGRADE` (carried
    /// like every other live client and also sent progress NOTICEs), or `null` for a
    /// SIGUSR2-triggered upgrade — a shell-driven deploy
    /// (`systemctl kill -s USR2 onyx-server`) that has no requesting client, so every
    /// registered session is carried and status is logged. The oper privilege
    /// check lives in the `handleUpgrade` wrapper; a signal-triggered upgrade is
    /// implicitly privileged (it came from the service manager / root).
    /// Seal an established secured mesh link for a zero-drop Helix upgrade. Queues
    /// an `.s2s_link` capsule carrying the link's crypto (Mooring record keys +
    /// counters), inner framing header, partial-record carry, and all not-yet-sent
    /// outbound bytes. The caller preserves the socket fd (CLOEXEC cleared) so the
    /// peer never sees a drop. Returns true on success; false on ANY failure.
    /// Failure for an established link is fatal to the complete upgrade; only an
    /// unestablished dial may fall back to the re-dial path.
    fn sealSecuredLink(
        self: *LinuxServer,
        conn: *ConnState,
        link: *secured_s2s_link.SecuredLink,
        pieces: *std.ArrayList(helix_live.StatePiece),
        blobs: *std.ArrayList([]u8),
    ) bool {
        if (conn.recv_armed or conn.send_armed or conn.connect_armed or
            conn.recv_cancel_pending or conn.send_cancel_pending or conn.connect_cancel_pending) return false;
        std.debug.assert(!conn.recv_armed and !conn.send_armed and !conn.connect_armed);
        std.debug.assert(!conn.recv_cancel_pending and !conn.send_cancel_pending and !conn.connect_cancel_pending);
        const outer = link.exportOuter();
        const inner = link.snapshotInner() orelse return false;
        const remote_name = link.snapshotInnerRemoteName();

        // Full unsent outbound, in wire order: the ConnState SendQ (inline tail +
        // heap overflow) — bytes drained from the link but not yet on the kernel —
        // FIRST, then the link's own undrained sealed records. The kernel-buffered
        // tail already on the socket rides the preserved fd.
        const conn_tail = conn.send_buf[conn.send_offset..conn.send_len];
        const conn_ovf = conn.send_overflow.items;
        const total_pending = conn_tail.len + conn_ovf.len + outer.pending_out.len;
        var pending_buf: ?[]u8 = null;
        defer if (pending_buf) |p| self.allocator.free(p);
        var pending: []const u8 = &.{};
        if (total_pending != 0) {
            const buf = self.allocator.alloc(u8, total_pending) catch return false;
            @memcpy(buf[0..conn_tail.len], conn_tail);
            @memcpy(buf[conn_tail.len..][0..conn_ovf.len], conn_ovf);
            @memcpy(buf[conn_tail.len + conn_ovf.len ..], outer.pending_out);
            pending_buf = buf;
            pending = buf;
        }

        // v4: seal the link's converged remote-member roster verbatim (nick
        // spelling incl. loser-UID aliases, origin node, status, HLC, identity,
        // and the receiver-derived session token). The successor primes its
        // fresh route table from it BEFORE the RESYNC, so the peer's re-burst
        // dedups to `.unchanged` instead of re-announcing every surviving
        // member to local clients as a spurious JOIN — and NAMES for remote
        // members stays correct even before the re-burst lands.
        var roster: std.ArrayList(u8) = .empty;
        defer roster.deinit(self.allocator);
        var roster_count: u32 = 0;
        if (link.channelNames()) |names| {
            var nit = names;
            while (nit.next()) |chan| {
                for (link.channelMembers(chan)) |m| {
                    if (roster_count == std.math.maxInt(u32)) return false;
                    s2s_snapshot.appendRosterMember(self.allocator, &roster, .{
                        .channel = chan,
                        .nick = m.nick,
                        .node = m.node,
                        .status = m.status,
                        .hlc = m.hlc,
                        .username = m.username,
                        .realname = m.realname,
                        .host = m.host,
                        .account = m.account,
                        .real_host = m.real_host,
                        .certfp = m.certfp,
                        .session_token = m.session_token,
                    }) catch return false;
                    roster_count += 1;
                }
            }
        }

        var caps: u8 = 0;
        if (inner.peer_supports_signing) caps |= s2s_snapshot.cap_signing;
        if (inner.peer_supports_account) caps |= s2s_snapshot.cap_account;
        if (inner.peer_supports_oper_info) caps |= s2s_snapshot.cap_oper_info;
        if (inner.peer_supports_repair) caps |= s2s_snapshot.cap_repair;
        if (inner.peer_supports_session_replica_v2) caps |= s2s_snapshot.cap_session_replica_v2;
        if (inner.peer_supports_session_attachment_lease_v2) caps |= s2s_snapshot.cap_session_attachment_lease_v2;
        if (inner.peer_supports_secure_relay_v2) caps |= s2s_snapshot.cap_secure_relay_v2;
        if (inner.peer_supports_event_spine_v2) caps |= s2s_snapshot.cap_event_spine_v2;
        var caps_ext: u8 = 0;
        if (inner.peer_supports_relay_v2_current)
            caps_ext |= s2s_snapshot.cap_ext_relay_v2_current;
        if (inner.peer_supports_relay_v2_ack_confirm)
            caps_ext |= s2s_snapshot.cap_ext_relay_v2_ack_confirm;

        var snap = s2s_snapshot.Snapshot{
            .fd = conn.fd,
            .role = @intFromEnum(outer.role),
            .s2s_initiator = conn.s2s_initiator,
            .send_counter = outer.send_counter,
            .recv_counter = outer.recv_counter,
            .feed_seq = outer.feed_seq,
            .pl_local_epoch_ms = inner.link.local_epoch_ms,
            .pl_remote_epoch_ms = inner.link.remote_epoch_ms,
            .pl_send_credit = inner.link.send_credit,
            .pl_pending_credit = inner.link.pending_credit,
            .pl_next_out_seq = inner.link.next_out_seq,
            .pl_next_in_seq = inner.link.next_in_seq,
            .pl_last_acked = inner.link.last_acked_by_remote,
            .remote_node_id = inner.remote_node_id,
            .remote_epoch_ms = inner.remote_epoch_ms,
            .caps = caps,
            .caps_ext = caps_ext,
            .remote_name = remote_name,
            .connect_addr = if (conn.s2s_dial_target_known) std.mem.asBytes(&conn.s2s_connect_addr) else &.{},
            .rec_inbuf = outer.rec_inbuf,
            .pending_out = pending,
            .roster = roster.items,
            .roster_count = roster_count,
        };
        outer.established.serialize(&snap.established);

        const blob = s2s_snapshot.encode(self.allocator, snap) catch return false;
        blobs.append(self.allocator, blob) catch {
            self.allocator.free(blob);
            return false;
        };
        pieces.append(self.allocator, .{ .kind = .s2s_link, .bytes = blob }) catch return false;
        return true;
    }

    /// Seal the account-level multi-session/bouncer registry into `.sessions`
    /// capsules (one per account) so SESSION reclaim tokens, detached restore
    /// snapshots, and attached-session identity survive the USR2 swap. Without
    /// this every upgrade silently WIPED the registry: post-upgrade SESSION
    /// RESUME answered FAIL NO_SESSION and every pre-upgrade mesh MTOKEN pointed
    /// at a session the origin no longer held. Fail-closed: null means at least
    /// one account could not be sealed and the caller must refuse the upgrade.
    fn sealSessionRegistry(
        self: *LinuxServer,
        pieces: *std.ArrayList(helix_live.StatePiece),
        blobs: *std.ArrayList([]u8),
    ) ?usize {
        // Join-key map: session client id -> live socket fd. The fd is the
        // Helix join key back to the carried `.clients` snapshot (the same key
        // the TLS/WS capsules use); an attached session whose connection ends
        // up not carried simply finds no successor match and degrades to a
        // detached (reclaimable) ghost — fail-safe, never a wrong re-join.
        var fd_by_cid = std.AutoHashMap(u64, i32).init(self.allocator);
        defer fd_by_cid.deinit();
        // Every shard's clients: an attached session may live on any reactor
        // (callers quiesce siblings before the multi-shard seal), and missing a
        // shard here silently degrades its attached sessions to detached ghosts.
        for (self.reactors) |*r| {
            var cit = r.clients.iterator();
            while (cit.next()) |e| {
                if (e.value.s2s != null or e.value.s2s_secured != null) continue;
                if (!e.value.session.registered()) continue;
                fd_by_cid.put(monitorIdFromClient(e.id), e.value.fd) catch return null;
            }
        }

        var sealed: usize = 0;
        var expected: usize = 0;
        var complete = true;
        self.sessions.lock.lockShared();
        defer self.sessions.lock.unlockShared();
        var it = self.sessions.accounts.iterator();
        while (it.next()) |entry| {
            const acct_sessions = entry.value_ptr.items.items;
            if (acct_sessions.len == 0) continue;
            expected += 1;
            const entries_buf = self.allocator.alloc(session_capsule.SessionEntry, acct_sessions.len) catch {
                complete = false;
                continue;
            };
            defer self.allocator.free(entries_buf);
            // Entries borrow store-owned token/snapshot bytes; the shared lock
            // held above keeps them stable until encode() copies them below.
            for (acct_sessions, entries_buf) |*s, *out| {
                out.* = .{
                    .token = s.token[0..],
                    .signon_unix = s.signon_ms,
                    .detached = !s.attached,
                    .client = s.client,
                    .fd = if (s.attached) (fd_by_cid.get(s.client) orelse blk: {
                        complete = false;
                        break :blk -1;
                    }) else -1,
                    .snapshot = if (!s.attached) (s.snapshot orelse &.{}) else &.{},
                    .portable_resume = s.portable_resume,
                    .attachment_id = if (s.attachment_id) |attachment_id| attachment_id.raw else null,
                };
            }
            const cap = session_capsule.SessionCapsule{
                .account = entry.key_ptr.*,
                .sessions = entries_buf,
            };
            const buf = self.allocator.alloc(u8, cap.encodedLen()) catch {
                complete = false;
                continue;
            };
            _ = cap.encode(buf) catch {
                self.allocator.free(buf);
                complete = false;
                continue;
            };
            blobs.append(self.allocator, buf) catch {
                self.allocator.free(buf);
                complete = false;
                continue;
            };
            pieces.append(self.allocator, .{ .kind = .sessions, .bytes = buf }) catch {
                complete = false;
                continue;
            };
            sealed += 1;
        }
        if (!complete or sealed != expected) return null;
        return sealed;
    }

    const PendingMigrationSealCounts = struct {
        entries: usize,
        consumed: usize,
    };

    /// Seal the complete holding area as one v2 `.pending_migration` checkpoint.
    /// The PMST blob includes both live offers and consumed-token replay state;
    /// it is all-or-nothing so USR2 cannot reset ordering/expiry metadata or
    /// expose a partial migration set on the successor.
    fn sealPendingMigrationCheckpoint(
        self: *LinuxServer,
        pieces: *std.ArrayList(helix_live.StatePiece),
        blobs: *std.ArrayList([]u8),
    ) ?PendingMigrationSealCounts {
        var empty = session_migrate.PendingMigrations.initWithConfig(self.allocator, .{
            .max_entries = self.config.session_max_pending_migrations,
            .max_per_account = self.config.session_max_per_account,
        });
        defer empty.deinit();
        const pm = if (self.pending_migrations) |*p| p else &empty;
        const captured_at_ms = @max(@as(i64, 0), self.nowMs());
        const buf = pm.encodeUpgradeCheckpoint(self.allocator, captured_at_ms) catch return null;
        blobs.append(self.allocator, buf) catch {
            self.allocator.free(buf);
            return null;
        };
        pieces.append(self.allocator, .{
            .kind = .pending_migration,
            .bytes = buf,
            // A v1 successor would otherwise accept the overlapping schema and
            // parse PMST as one legacy offer, silently losing most state. Force
            // hot rollback across this representation boundary to fail closed;
            // cold restart remains the supported downgrade path.
            .min_supported = 2,
        }) catch return null;
        return .{ .entries = pm.count(), .consumed = pm.consumedCount() };
    }

    /// Build the process HLC image that a successor must inherit after folding
    /// in every retained PROP clock/tombstone. The predecessor is deliberately
    /// left untouched: any later allocation, seal, or exec failure keeps its
    /// causal state byte-exact. Future-skewed or exhausted retained clocks
    /// refuse the hot upgrade rather than reappearing with an older writer.
    fn preparePropertyUpgradeClockBoundary(self: *LinuxServer) ?mesh_clock_mod.MeshClock {
        const maximum = prop_checkpoint.maxClockHlc(
            &self.channel_prop_clocks,
            &self.entity_prop_clocks,
        ) catch return null;
        lockSpin(&self.mesh_clock_lock);
        defer self.mesh_clock_lock.unlock();
        var candidate = self.mesh_clock;
        candidate.observeChecked(
            maximum,
            self.meshWallMs(),
            mesh_clock_mod.default_max_future_skew_ms,
        ) catch return null;
        return candidate;
    }

    /// Seal the raw property store and both clock/tombstone maps as one exact
    /// v2-required mesh checkpoint. Even the completely empty image is emitted:
    /// absence is reserved for a genuinely legacy predecessor.
    fn sealPropertyUpgradeCheckpoint(
        self: *LinuxServer,
        pieces: *std.ArrayList(helix_live.StatePiece),
        blobs: *std.ArrayList([]u8),
    ) bool {
        const buf = prop_checkpoint.encode(
            self.allocator,
            &self.props,
            &self.channel_prop_clocks,
            &self.entity_prop_clocks,
        ) catch return false;
        blobs.append(self.allocator, buf) catch {
            self.allocator.free(buf);
            return false;
        };
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = buf,
            // Losing this piece would restore the property rows without their
            // LWW/tombstone authority (or vice versa). No v1 successor may
            // accept that partial world; cold restart is the downgrade path.
            .min_supported = 2,
        }) catch return false;
        return true;
    }

    const MandatoryStateSeal = struct {
        world_bytes: usize,
        history_bytes: usize,
        webhook_bytes: usize,
        relay_replay_bytes: usize,
        relay_outbox_bytes: usize,
        relay_event_log_bytes: usize,
        attachment_delivery_bytes: usize,
        event_replay_bytes: usize,
        e2ee_group_replay_bytes: usize,
    };

    fn helixWorldRelationIdentity(
        context: *anyopaque,
        client: world_model.ClientId,
    ) ?world_checkpoint.MemberIdentity {
        const self: *LinuxServer = @ptrCast(@alignCast(context));
        const conn = self.connFor(clientIdFromWorld(client)) orelse return null;
        if (conn.fd < 0 or conn.closing or conn.s2s != null or conn.s2s_secured != null)
            return null;
        const nick = conn.session.displayName();
        if (nick.len == 0 or std.mem.eql(u8, nick, "*")) return null;
        return .{ .join_key = @intCast(conn.fd), .nick = nick };
    }

    fn helixWorldRelationClient(
        context: *anyopaque,
        join_key: u64,
    ) ?world_model.ClientId {
        const self: *LinuxServer = @ptrCast(@alignCast(context));
        if (join_key > std.math.maxInt(linux.fd_t)) return null;
        const fd: linux.fd_t = @intCast(join_key);
        var found: ?world_model.ClientId = null;
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                if (entry.value.fd != fd or entry.value.s2s != null or
                    entry.value.s2s_secured != null) continue;
                if (found != null) return null;
                found = worldIdFromClient(entry.id);
            }
        }
        return found;
    }

    fn helixWorldRelationResolver(self: *LinuxServer) world_checkpoint.NickResolver {
        return .{
            .context = self,
            .resolve = helixWorldRelationIdentity,
            .lookup = helixWorldRelationClient,
        };
    }

    /// Seal the three process-authoritative state families that cannot be
    /// reconstructed exactly from client capsules or disk. The caller holds
    /// World's write lock across this function and every other seal operation,
    /// so the channel metadata/member projection and the client snapshots below
    /// describe one stable logical instant. Empty stores are still encoded: an
    /// inherited arena without any one of these singletons is incomplete.
    fn sealMandatoryStateUpgradeCheckpoints(
        self: *LinuxServer,
        pieces: *std.ArrayList(helix_live.StatePiece),
        blobs: *std.ArrayList([]u8),
    ) ?MandatoryStateSeal {
        const world_wire = world_checkpoint.encodeLockedResolved(
            self.allocator,
            &self.world,
            self.helixWorldRelationResolver(),
        ) catch |err| {
            srvLog("onyx-server: UPGRADE World checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        blobs.append(self.allocator, world_wire) catch {
            srvLog("onyx-server: UPGRADE World blob ownership append failed\n", .{});
            self.allocator.free(world_wire);
            return null;
        };
        pieces.append(self.allocator, .{ .kind = .channels, .bytes = world_wire }) catch {
            srvLog("onyx-server: UPGRADE World piece append failed\n", .{});
            return null;
        };

        // ADS1 is the outermost mutation lane because MESSAGE_V2 admission takes
        // attachment_delivery_mu before relay_v2_replay_mu. Seal the complete
        // five-authority cut in that same order: exact rendered attachment rows,
        // Lotus consequence, RVG2 identity, RVO2 immediate-hop retries, and RVL2
        // full-mesh repair authority. Empty images remain mandatory material.
        lockSpin(&self.attachment_delivery_mu);
        lockSpin(&self.relay_v2_replay_mu);
        const lotus_wire = self.history.encodeCheckpoint(self.allocator) catch |err| {
            self.relay_v2_replay_mu.unlock();
            self.attachment_delivery_mu.unlock();
            srvLog("onyx-server: UPGRADE Lotus checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        const relay_replay_wire = self.relay_v2_replay_guard.encodeCheckpoint(self.allocator) catch |err| {
            self.allocator.free(lotus_wire);
            self.relay_v2_replay_mu.unlock();
            self.attachment_delivery_mu.unlock();
            srvLog("onyx-server: UPGRADE MESSAGE_V2 replay checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        const relay_outbox_wire = self.relay_v2_outbox.encodeCheckpoint(self.allocator) catch |err| {
            self.allocator.free(lotus_wire);
            self.allocator.free(relay_replay_wire);
            self.relay_v2_replay_mu.unlock();
            self.attachment_delivery_mu.unlock();
            srvLog("onyx-server: UPGRADE MESSAGE_V2 outbox checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        const relay_event_log_wire = self.relay_v2_event_log.encodeCheckpoint(self.allocator) catch |err| {
            self.allocator.free(lotus_wire);
            self.allocator.free(relay_replay_wire);
            self.allocator.free(relay_outbox_wire);
            self.relay_v2_replay_mu.unlock();
            self.attachment_delivery_mu.unlock();
            srvLog("onyx-server: UPGRADE MESSAGE_V2 event-log checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        const attachment_delivery_wire = self.attachment_delivery_spool.encodeCheckpoint(self.allocator) catch |err| {
            self.allocator.free(lotus_wire);
            self.allocator.free(relay_replay_wire);
            self.allocator.free(relay_outbox_wire);
            self.allocator.free(relay_event_log_wire);
            self.relay_v2_replay_mu.unlock();
            self.attachment_delivery_mu.unlock();
            srvLog("onyx-server: UPGRADE attachment-delivery checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        self.relay_v2_replay_mu.unlock();
        self.attachment_delivery_mu.unlock();
        defer self.allocator.free(lotus_wire);
        var relay_replay_owned = true;
        defer if (relay_replay_owned) self.allocator.free(relay_replay_wire);
        var relay_outbox_owned = true;
        defer if (relay_outbox_owned) self.allocator.free(relay_outbox_wire);
        var relay_event_log_owned = true;
        defer if (relay_event_log_owned) self.allocator.free(relay_event_log_wire);
        var attachment_delivery_owned = true;
        defer if (attachment_delivery_owned) self.allocator.free(attachment_delivery_wire);
        const search_wire = self.search_index.encodeCheckpoint(self.allocator) catch |err| {
            srvLog("onyx-server: UPGRADE search checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        defer self.allocator.free(search_wire);
        var event_writer = std.Io.Writer.Allocating.init(self.allocator);
        defer event_writer.deinit();
        self.event_history.serializeInto(&event_writer.writer) catch |err| {
            srvLog("onyx-server: UPGRADE EventHistory checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        const history_wire = history_checkpoint.encode(self.allocator, .{}, .{
            .lotus = lotus_wire,
            .search_index = search_wire,
            .event_history = event_writer.written(),
        }) catch |err| {
            srvLog("onyx-server: UPGRADE history bundle seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        blobs.append(self.allocator, history_wire) catch {
            srvLog("onyx-server: UPGRADE history blob ownership append failed\n", .{});
            self.allocator.free(history_wire);
            return null;
        };
        pieces.append(self.allocator, .{ .kind = .history, .bytes = history_wire }) catch {
            srvLog("onyx-server: UPGRADE history piece append failed\n", .{});
            return null;
        };

        const webhook_wire = self.webhook_store.encodeUpgradeCheckpoint(self.allocator) catch |err| {
            srvLog("onyx-server: UPGRADE webhook checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        blobs.append(self.allocator, webhook_wire) catch {
            srvLog("onyx-server: UPGRADE webhook blob ownership append failed\n", .{});
            self.allocator.free(webhook_wire);
            return null;
        };
        pieces.append(self.allocator, .{ .kind = .webhook_store, .bytes = webhook_wire }) catch {
            srvLog("onyx-server: UPGRADE webhook piece append failed\n", .{});
            return null;
        };

        lockSpin(&self.event_spine_replay_mu);
        const event_replay_wire = self.event_spine_replay_guard.encodeCheckpoint(self.allocator) catch |err| {
            self.event_spine_replay_mu.unlock();
            srvLog("onyx-server: UPGRADE Event Spine replay checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        self.event_spine_replay_mu.unlock();
        blobs.append(self.allocator, event_replay_wire) catch {
            srvLog("onyx-server: UPGRADE Event Spine replay blob ownership append failed\n", .{});
            self.allocator.free(event_replay_wire);
            return null;
        };
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = event_replay_wire,
            // ESG2 is the exact v2 delivery authority. A predecessor may not
            // allow a v1 successor to ignore it and replay retired events.
            .min_supported = 2,
        }) catch {
            srvLog("onyx-server: UPGRADE Event Spine replay piece append failed\n", .{});
            return null;
        };

        // EGRG is metadata-only. Opaque E2EEGROUP payloads and hop wires never
        // enter Helix; any outstanding RAM custody makes the whole seal unsafe
        // and therefore refuses the upgrade rather than losing recoverability.
        lockSpin(&self.e2ee_group_mesh_mu);
        const e2ee_group_replay_wire = self.e2ee_group_mesh_authority.encodeCheckpoint(
            self.allocator,
        ) catch |err| {
            self.e2ee_group_mesh_mu.unlock();
            srvLog(
                "onyx-server: UPGRADE E2EEGROUP replay checkpoint seal failed ({s})\n",
                .{@errorName(err)},
            );
            return null;
        };
        self.e2ee_group_mesh_mu.unlock();
        var e2ee_group_replay_owned = true;
        defer if (e2ee_group_replay_owned) self.allocator.free(e2ee_group_replay_wire);
        blobs.append(self.allocator, e2ee_group_replay_wire) catch {
            srvLog("onyx-server: UPGRADE E2EEGROUP replay blob ownership append failed\n", .{});
            return null;
        };
        e2ee_group_replay_owned = false;
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = e2ee_group_replay_wire,
            // Exact-once E2EEGROUP delivery authority. A predecessor or
            // rollback binary that cannot recognize EGRG must reject the arena.
            .min_supported = 2,
        }) catch {
            srvLog("onyx-server: UPGRADE E2EEGROUP replay piece append failed\n", .{});
            return null;
        };

        blobs.append(self.allocator, relay_outbox_wire) catch {
            srvLog("onyx-server: UPGRADE MESSAGE_V2 outbox blob ownership append failed\n", .{});
            return null;
        };
        relay_outbox_owned = false;
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = relay_outbox_wire,
            .min_supported = 2,
        }) catch {
            srvLog("onyx-server: UPGRADE MESSAGE_V2 outbox piece append failed\n", .{});
            return null;
        };

        blobs.append(self.allocator, relay_replay_wire) catch {
            srvLog("onyx-server: UPGRADE MESSAGE_V2 replay blob ownership append failed\n", .{});
            return null;
        };
        relay_replay_owned = false;
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = relay_replay_wire,
            // RVG2 is the exact signed MESSAGE_V2 delivery authority. Losing it
            // across exec would make already-delivered captures live again.
            .min_supported = 2,
        }) catch {
            srvLog("onyx-server: UPGRADE MESSAGE_V2 replay piece append failed\n", .{});
            return null;
        };

        blobs.append(self.allocator, relay_event_log_wire) catch {
            srvLog("onyx-server: UPGRADE MESSAGE_V2 event-log blob ownership append failed\n", .{});
            return null;
        };
        relay_event_log_owned = false;
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = relay_event_log_wire,
            .min_supported = 2,
        }) catch {
            srvLog("onyx-server: UPGRADE MESSAGE_V2 event-log piece append failed\n", .{});
            return null;
        };

        blobs.append(self.allocator, attachment_delivery_wire) catch {
            srvLog("onyx-server: UPGRADE attachment-delivery blob ownership append failed\n", .{});
            return null;
        };
        attachment_delivery_owned = false;
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = attachment_delivery_wire,
            .min_supported = 2,
        }) catch {
            srvLog("onyx-server: UPGRADE attachment-delivery piece append failed\n", .{});
            return null;
        };

        // Seal the server-wide cross-mesh oper-grant registry (grants +
        // revocation tombstones + the mint-incarnation high-water mark). The
        // successor primes its registry from this BEFORE the io loop can
        // process any peer grant re-mint, so `applyMeshGrant` sees
        // `had_oper_override=true` for an unchanged oper and does NOT
        // re-broadcast a spurious `MODE #chan +Y <nick>` after every upgrade.
        // An empty registry image remains mandatory material (it still carries
        // the incarnation mark).
        const oper_grant_wire = oper_grant_snapshot.encodeFromRegistry(
            self.allocator,
            &self.oper_grants,
            self.grantNowU64(),
            self.grant_incarnation,
        ) catch |err| {
            srvLog("onyx-server: UPGRADE oper-grant checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        blobs.append(self.allocator, oper_grant_wire) catch {
            srvLog("onyx-server: UPGRADE oper-grant blob ownership append failed\n", .{});
            self.allocator.free(oper_grant_wire);
            return null;
        };
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = oper_grant_wire,
            // Exact server-wide state piece: a rollback binary that cannot
            // recognize it must refuse the arena, never silently drop it.
            .min_supported = 2,
        }) catch {
            srvLog("onyx-server: UPGRADE oper-grant piece append failed\n", .{});
            return null;
        };

        // Scoped bot grants ride the same mesh_checkpoint family under a
        // different magic. Absence stays legal (a pre-O12 arena has no piece).
        // An empty image is still sealed so the successor keeps "no grants"
        // distinct from a missing predecessor piece only by adopting empty.
        const bot_grant_wire = bot_grant_snapshot.encodeFrom(
            self.allocator,
            &self.bot_grants,
            self.grantNowU64(),
        ) catch |err| {
            srvLog("onyx-server: UPGRADE bot-grant checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        blobs.append(self.allocator, bot_grant_wire) catch {
            srvLog("onyx-server: UPGRADE bot-grant blob ownership append failed\n", .{});
            self.allocator.free(bot_grant_wire);
            return null;
        };
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = bot_grant_wire,
            .min_supported = 2,
        }) catch {
            srvLog("onyx-server: UPGRADE bot-grant piece append failed\n", .{});
            return null;
        };

        // Reply threads ride the same mesh_checkpoint family under a different
        // magic. Absence stays legal. An empty image is still sealed.
        const thread_wire = thread_snapshot.encodeFrom(self.allocator, &self.threads) catch |err| {
            srvLog("onyx-server: UPGRADE thread checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        blobs.append(self.allocator, thread_wire) catch {
            srvLog("onyx-server: UPGRADE thread blob ownership append failed\n", .{});
            self.allocator.free(thread_wire);
            return null;
        };
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = thread_wire,
            .min_supported = 2,
        }) catch {
            srvLog("onyx-server: UPGRADE thread piece append failed\n", .{});
            return null;
        };

        // Deferred deliveries ride the same family. Absence stays legal. An
        // empty image is still sealed. Fired jobs stay fired so the successor
        // does not send them again.
        const schedule_wire = schedule_snapshot.encodeFrom(self.allocator, &self.schedules) catch |err| {
            srvLog("onyx-server: UPGRADE schedule checkpoint seal failed ({s})\n", .{@errorName(err)});
            return null;
        };
        blobs.append(self.allocator, schedule_wire) catch {
            srvLog("onyx-server: UPGRADE schedule blob ownership append failed\n", .{});
            self.allocator.free(schedule_wire);
            return null;
        };
        pieces.append(self.allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = schedule_wire,
            .min_supported = 2,
        }) catch {
            srvLog("onyx-server: UPGRADE schedule piece append failed\n", .{});
            return null;
        };

        return .{
            .world_bytes = world_wire.len,
            .history_bytes = history_wire.len,
            .webhook_bytes = webhook_wire.len,
            .relay_replay_bytes = relay_replay_wire.len,
            .relay_outbox_bytes = relay_outbox_wire.len,
            .relay_event_log_bytes = relay_event_log_wire.len,
            .attachment_delivery_bytes = attachment_delivery_wire.len,
            .event_replay_bytes = event_replay_wire.len,
            .e2ee_group_replay_bytes = e2ee_group_replay_wire.len,
        };
    }

    fn sealTlsTicketKeyUpgradeCapsule(
        allocator: std.mem.Allocator,
        current: tls_resumption.TicketKey,
        previous: ?tls_resumption.TicketKey,
        pieces: *std.ArrayList(helix_live.StatePiece),
        blobs: *std.ArrayList([]u8),
    ) bool {
        const tk = ticket_key_capsule.encode(allocator, .{
            .current = current,
            .previous = previous,
        }) catch return false;
        blobs.append(allocator, tk) catch {
            allocator.free(tk);
            return false;
        };
        pieces.append(allocator, .{ .kind = .tls_ticket_keys, .bytes = tk }) catch return false;
        return true;
    }

    fn sealTlsReplayUpgradeCheckpoint(
        allocator: std.mem.Allocator,
        guard: *tls_resumption.ReplayGuard,
        pieces: *std.ArrayList(helix_live.StatePiece),
    ) ![]u8 {
        const wire = try native_windows_tls_replay.encodeSnapshot(allocator, guard);
        errdefer {
            std.crypto.secureZero(u8, wire);
            allocator.free(wire);
        }
        try pieces.append(allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = wire,
            .min_supported = 2,
        });
        return wire;
    }

    fn stageTlsReplayUpgradeCheckpoint(
        allocator: std.mem.Allocator,
        resumption_enabled: bool,
        caps: []const helix_capsule.Capsule,
    ) !?native_windows_tls_replay.Owned {
        const descriptor = helix_capsule.descriptor(.mesh_checkpoint);
        var replacement: ?native_windows_tls_replay.Owned = null;
        errdefer if (replacement) |*owned| owned.deinit();
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint or c.fields.len == 0 or
                !native_windows_tls_replay.isCheckpoint(c.fields[0].bytes)) continue;
            if (!resumption_enabled or replacement != null or
                c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != 2 or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
                return error.InvalidInheritedHandoff;
            replacement = try native_windows_tls_replay.decodeOwned(allocator, c.fields[0].bytes);
        }
        if (resumption_enabled and replacement == null) return error.InvalidInheritedHandoff;
        return replacement;
    }

    fn sealMemoInboxUpgradeCheckpoint(
        allocator: std.mem.Allocator,
        box: *const memo_mod.MemoBox,
        dirty: bool,
        pieces: *std.ArrayList(helix_live.StatePiece),
    ) ![]u8 {
        const wire = try native_windows_memo_inbox.encode(allocator, box, dirty);
        errdefer {
            std.crypto.secureZero(u8, wire);
            allocator.free(wire);
        }
        try pieces.append(allocator, .{
            .kind = .mesh_checkpoint,
            .bytes = wire,
            .min_supported = 2,
        });
        return wire;
    }

    fn stageMemoInboxUpgradeCheckpoint(
        allocator: std.mem.Allocator,
        config: memo_mod.Config,
        caps: []const helix_capsule.Capsule,
    ) !native_windows_memo_inbox.State {
        const descriptor = helix_capsule.descriptor(.mesh_checkpoint);
        var replacement: ?native_windows_memo_inbox.State = null;
        errdefer if (replacement) |*owned| owned.deinit();
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint or c.fields.len == 0 or
                !native_windows_memo_inbox.isCheckpoint(c.fields[0].bytes)) continue;
            if (replacement != null or
                c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != 2 or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
                return error.InvalidInheritedHandoff;
            replacement = try native_windows_memo_inbox.decode(allocator, c.fields[0].bytes, config);
        }
        return replacement orelse error.InvalidInheritedHandoff;
    }

    fn sealMeshRedialUpgradeHint(
        allocator: std.mem.Allocator,
        hint: mesh_redial.Peer,
        pieces: *std.ArrayList(helix_live.StatePiece),
        blobs: *std.ArrayList([]u8),
    ) bool {
        const wire = mesh_redial.encode(hint);
        const hb = allocator.dupe(u8, &wire) catch return false;
        blobs.append(allocator, hb) catch {
            allocator.free(hb);
            return false;
        };
        pieces.append(allocator, .{ .kind = .mesh_checkpoint, .bytes = hb }) catch return false;
        return true;
    }

    /// Per-shard client counters accumulated by `sealShardClients` across the
    /// whole multi-shard UPGRADE seal.
    const SealCounts = struct {
        /// Client connections carried (fd preserved + `.clients` capsule sealed).
        clients: usize = 0,
        /// Registered client connections that must remain live. If this differs
        /// from `clients`, the hot upgrade is refused instead of disconnecting a
        /// TLS/WS/export-failed or half-closing client.
        clients_expected: usize = 0,
        fd_prepare_failed: bool = false,
        /// Of those, how many carried a live TLS engine / a WS adapter.
        tls: usize = 0,
        ws: usize = 0,
        /// Mesh links: re-dial hints sealed / secured links preserved (fd carried).
        s2s_hints: usize = 0,
        s2s_preserved: usize = 0,
        s2s_preserve_failed: bool = false,
        s2s_hint_failed: bool = false,
    };

    /// Seal ONE reactor shard's connections for a Helix UPGRADE: every carried
    /// client gets its capsules queued on `pieces`/`blobs` and its socket ID
    /// recorded in `carried_fds` (which must have room
    /// for the shard's whole slot table). Established secured mesh links (a
    /// reactor-0-only population) are preserved the same way; other links seal
    /// a re-dial hint. Safe to call for a foreign shard ONLY while that shard's
    /// worker is parked (`quiesceSiblingReactors`) or not running at all — the
    /// parked-counter handshake publishes the shard's connection state to this
    /// thread. The caller compares `clients` with `clients_expected`; any live
    /// client that cannot be sealed refuses the whole UPGRADE before exec.
    fn sealShardClients(
        self: *LinuxServer,
        r: *Reactor,
        pieces: *std.ArrayList(helix_live.StatePiece),
        blobs: *std.ArrayList([]u8),
        carried_fds: []linux.fd_t,
        fd_count: *usize,
        counts: *SealCounts,
    ) void {
        var it = r.clients.iterator();
        while (it.next()) |e| {
            // S2S peer links: PRESERVE an established secured link across the swap
            // (zero-drop) — seal its crypto + inner framing state into an .s2s_link
            // capsule and carry the socket fd so the PEER never sees a drop (no
            // netsplit, no oper-prefix churn). A plaintext link (no crypto to
            // resume) may use a re-dial hint. An established secured link that
            // cannot snapshot refuses the whole UPGRADE. For an unestablished
            // hand-dialed initiator (oper CONNECT), seal a re-dial hint
            // so the successor reconnects at boot; config-managed [mesh].connect
            // dials are re-dialed by the successor's mesh boot pass instead.
            if (e.value.s2s != null or e.value.s2s_secured != null) {
                // This process-local retirement latch has no capsule schema.
                // Refuse the cut until drain completes; carrying a closing loser
                // as an ordinary established route would resurrect a duplicate.
                if (e.value.s2s_dedup_drain_deadline_ms != 0) {
                    counts.s2s_preserve_failed = true;
                    continue;
                }
                if (e.value.s2s_secured) |link| {
                    // Preserve an established secured link only after every exact
                    // socket operation has been canceled and its completion reaped.
                    // `sealSecuredLink` rejects any residual armed/cancel-pending
                    // state, so no in-flight record may race the swap; the caller
                    // refuses the whole UPGRADE instead of accepting AuthFail/redial.
                    const est = link.established();
                    if (est and self.sealSecuredLink(e.value, link, pieces, blobs)) {
                        // Preserved: carry the socket across the upgrade; do NOT also seal a
                        // re-dial hint (that would open a duplicate link → churn).
                        if (builtin.os.tag != .windows and !setCloexec(e.value.fd, builtin.os.tag == .openbsd)) {
                            counts.fd_prepare_failed = true;
                            continue;
                        }
                        carried_fds[fd_count.*] = e.value.fd;
                        fd_count.* += 1;
                        counts.s2s_preserved += 1;
                        continue;
                    }
                    if (est) {
                        counts.s2s_preserve_failed = true;
                        srvLog("onyx-server: UPGRADE — established secured S2S snapshot failed; exact upgrade will be refused\n", .{});
                        continue;
                    }
                }
                if (e.value.s2s_initiator and e.value.s2s_dial_target_known and !self.dialManaged(e.value.token)) {
                    if (!sealMeshRedialUpgradeHint(self.allocator, .{
                        .addr = e.value.s2s_connect_addr.addr,
                        .port = std.mem.bigToNative(u16, e.value.s2s_connect_addr.port),
                    }, pieces, blobs)) {
                        counts.s2s_hint_failed = true;
                        continue;
                    }
                    counts.s2s_hints += 1;
                }
                continue;
            }
            // Every non-mesh transport must either be carried exactly or make
            // the hot upgrade refuse. Silently omitting a pre-registration TLS,
            // WS, or IRC handshake would close it at exec and violate Helix's
            // connected-client guarantee.
            counts.clients_expected += 1;
            if (!e.value.session.registered()) continue;
            // An open draft/multiline batch owns accepted chunks that are not
            // part of the session capsule. Refuse the whole upgrade until the
            // batch closes, instead of losing its prefix after COMMIT.
            if (e.value.multiline != null) continue;
            var flood_carry: ?flood_guard.CarryState = null;
            if (e.value.flood_guard) |*guard| flood_carry = guard.exportCarry() catch continue;
            // A carried client's socket fd is the exact join key for every
            // transport and per-client sidecar. Synthetic/half-constructed
            // entries with no live descriptor make the seal incomplete; never
            // let a signed cast turn -1 into an unrelated u64 owner id.
            if (e.value.fd < 0) continue;
            // A carried client is snapshotted only after the owner reaped both
            // original CQEs and their exact-cancel provenance. An in-flight
            // CONNECT still borrows the inline sockaddr and is likewise refused;
            // listener ACCEPT owns no ConnState storage and stays outside this
            // per-connection boundary.
            if (e.value.recv_armed or e.value.send_armed or e.value.send_submitted_len != 0 or e.value.send_submitted_offset != 0 or e.value.connect_armed or
                e.value.recv_cancel_pending or e.value.send_cancel_pending or e.value.connect_cancel_pending) continue;
            std.debug.assert(!e.value.recv_armed and !e.value.send_armed and !e.value.connect_armed);
            std.debug.assert(!e.value.recv_cancel_pending and !e.value.send_cancel_pending and !e.value.connect_cancel_pending);
            if (e.value.closing) continue;
            // wss browser client: carry it whenever its
            // WebSocket adapter is past the HTTP Upgrade (phase=open) — the
            // adapter's partial framing state (a mid-frame deframer + a partial
            // outbound line) is serialized into the `.ws_session` capsule
            // and restored verbatim on the successor, so being mid-frame no
            // longer drops the client (the TLS crypto rides its own capsule
            // below). A handshake-phase adapter — or the pathological
            // popped-event-pending state that cannot exist between reactor
            // turns — makes the seal incomplete and refuses UPGRADE before exec.
            const carry_ws = if (e.value.ws) |wsst| wsCarryable(wsst) else false;
            if (e.value.ws != null and !carry_ws) continue;
            // TLS client: export the live engine state FIRST. If it cannot be
            // exported, the exact client count remains incomplete and UPGRADE is
            // refused before exec. A TLS socket must never reach the successor
            // without its crypto state.
            var tls_blob: ?[]u8 = null;
            if (e.value.tls) |t| {
                if (e.value.tls_ingress_active or e.value.tls_progress_active or e.value.tls_alert_pending or e.value.tls_discard_unsent) continue;
                const wire_chunks = [_][]const u8{
                    e.value.send_buf[e.value.send_offset..e.value.send_len],
                    e.value.send_overflow.items,
                };
                var capture = t.prepareCapture(self.allocator, .{
                    .fd = e.value.fd,
                    .tx_offloaded = e.value.tls_tx_offloaded,
                    .rx_offloaded = e.value.tls_rx_offloaded,
                    .wire_chunks = &wire_chunks,
                    .deferred_plain = e.value.tls_deferred_plain.items,
                    .deferred_ciphertext_charge = e.value.tls_deferred_charge,
                    .control_charge = std.math.cast(u32, e.value.tls_control_charge) orelse continue,
                    .queue_cap = e.value.sendq_cap,
                    .kernel_tx_prefix_remaining = e.value.tls_kernel_prefix_remaining,
                }) catch continue;
                defer capture.deinit();
                tls_blob = tls_snapshot.encode(self.allocator, .{
                    .kernel_tx_prefix_remaining = capture.kernel_tx_prefix_remaining,
                    .fd = e.value.fd,
                    .state = capture.state,
                    .pending_out = capture.pending_out,
                    .certfp = if (e.value.session.tls_certfp) |fp| fp else &.{},
                    .tx_offloaded = e.value.tls_tx_offloaded,
                    .rx_offloaded = e.value.tls_rx_offloaded,
                    .control_charge = @intCast(e.value.tls_control_charge),
                    .deferred_ciphertext_charge = e.value.tls_deferred_charge,
                    .deferred_plain = e.value.tls_deferred_plain.items,
                }) catch continue;
            }
            var snap = e.value.session.snapshot();
            snap.fd = e.value.fd; // re-attached by the successor
            // AcceptEx does not reliably expose the peer sockaddr on an
            // imported socket. Preserve the already-authenticated kernel or
            // trusted PROXY address and its exact clone-limit accounting.
            snap.peer_addr = e.value.peer_addr;
            snap.clone_counted = e.value.clone_counted;
            snap.throttle_counted = e.value.throttle_counted;
            snap.mesh_clone_counted = e.value.mesh_clone_counted;
            snap.mesh_clone_hash = e.value.mesh_clone_hash;
            // Preserve attachment-scoped access and client feature decisions.
            // SACCESS GAG is not necessarily present in the durable gag table.
            snap.gagged = e.value.gagged;
            snap.ircx = e.value.ircx;
            snap.unfurl_opt_in = e.value.unfurl_opt_in;
            snap.last_search_ms = e.value.last_search_ms;
            snap.keytrans_require = e.value.keytrans_require;
            snap.nick_claimed_at_ms = e.value.nick_claimed_at_ms;
            snap.flood_guard = flood_carry;
            // Record whether this connection was secured (had a live TLS engine).
            // The successor uses it as the fail-safe join: a secured client that
            // arrives without a decodable TLS-engine capsule is DROPPED, never
            // adopted as plaintext (a secured socket must not fall back to cleartext).
            snap.was_secured = e.value.tls != null;
            // Current client schema carries the transport join explicitly. The
            // successor requires a one-to-one `.ws_session` sidecar whenever
            // this bit is set, so a framed socket can never resume as raw IRC.
            snap.was_websocket = e.value.ws != null;
            // Carry the monotonic signon/last-message clocks so WHOIS idle/signon
            // survive the in-place UPGRADE (CLOCK_MONOTONIC is unchanged by execve).
            snap.connected_at_ms = e.value.connected_at_ms;
            snap.last_message_ms = e.value.last_message_ms;
            // Capture channel memberships + member modes so the successor re-joins.
            // Use a separate write index: a channel whose member modes can't be
            // read is skipped entirely, never leaving an undefined slot inside the
            // serialized range (which would encode garbage into the snapshot).
            const chan_cap = self.world.channelCountOf(worldIdFromClient(e.id));
            const chan_names = self.allocator.alloc([]const u8, chan_cap) catch {
                if (tls_blob) |tb| self.allocator.free(tb);
                continue;
            };
            defer self.allocator.free(chan_names);
            const nch = self.world.channelsOf(worldIdFromClient(e.id), chan_names);
            const chans = self.allocator.alloc(session_snapshot.ChannelMembership, nch) catch {
                if (tls_blob) |tb| self.allocator.free(tb);
                continue;
            };
            defer self.allocator.free(chans);
            var chan_n: usize = 0;
            var channels_complete = true;
            for (chan_names[0..nch]) |cname| {
                const m = self.world.memberModes(cname, worldIdFromClient(e.id)) orelse {
                    channels_complete = false;
                    break;
                };
                chans[chan_n] = .{ .name = cname, .modes = m.bits };
                chan_n += 1;
            }
            if (!channels_complete or chan_n != nch) {
                if (tls_blob) |tb| self.allocator.free(tb);
                continue;
            }
            snap.channels = chans[0..chan_n];
            // Carry the negotiated IRCv3 caps (by name) so echo-message and friends
            // survive the UPGRADE without a client reconnect. The buffer lives until
            // encode() copies it below; it is sized to hold the full cap set.
            var caps_buf: [dispatch.max_cap_names_len]u8 = undefined;
            snap.caps = e.value.session.renderNegotiatedCaps(&caps_buf);
            // Carry the client's multi-session reclaim token so the successor
            // re-tracks the adopted connection under the SAME token. Without it
            // every carried client became a SessionStore orphan after USR2
            // (SESSION TOKEN answered "no token"; its eventual disconnect found
            // no entry to detach — permanently un-reclaimable). The buffer
            // lives until encode() copies it below.
            var sess_tok: sessions_mod.Token = undefined;
            if (e.value.session.account()) |acct| {
                const handle = self.sessions.resumeHandleForClient(acct, monitorIdFromClient(e.id)) orelse {
                    if (tls_blob) |tb| self.allocator.free(tb);
                    continue;
                };
                if (tokenIsNull(handle.token)) {
                    if (tls_blob) |tb| self.allocator.free(tb);
                    continue;
                }
                sess_tok = handle.token;
                snap.session_token = sess_tok[0..];
            }
            // v4 tail: the partial inbound line pending in the RecvQ (inline
            // line_buf or its heap overflow) — dropping it made the next
            // recv'd bytes parse as a torn line on the successor.
            snap.pending_in = if (e.value.recv_overflow.items.len != 0)
                e.value.recv_overflow.items
            else
                e.value.line_buf[0..e.value.line_len];
            // v4 tail: a PLAINTEXT connection's unsent SendQ tail (inline +
            // overflow, contiguous). A TLS connection's unsent ciphertext is
            // carried by its `.tls_session` capsule above — never both.
            var plain_pend_tmp: ?[]u8 = null;
            defer if (plain_pend_tmp) |p| self.allocator.free(p);
            if (e.value.tls == null) {
                const ptail = e.value.send_buf[e.value.send_offset..e.value.send_len];
                const povf = e.value.send_overflow.items;
                if (povf.len == 0) {
                    snap.pending_out = ptail;
                } else if (self.allocator.alloc(u8, ptail.len + povf.len)) |buf| {
                    @memcpy(buf[0..ptail.len], ptail);
                    @memcpy(buf[ptail.len..], povf);
                    plain_pend_tmp = buf;
                    snap.pending_out = buf;
                } else |_| {
                    // The SendQ is one ordered byte stream. Carrying only the
                    // inline prefix would silently truncate client-visible
                    // events, so leave this client unsealed; the global expected
                    // count then refuses UPGRADE without disconnecting anyone.
                    continue;
                }
            }
            const blob = session_snapshot.encode(self.allocator, snap) catch {
                if (tls_blob) |tb| self.allocator.free(tb);
                continue;
            };
            // Queue the TLS piece BEFORE the session piece: an orphaned TLS
            // capsule is ignored by the successor, but a TLS client whose session
            // piece landed without its TLS piece would be adopted as plaintext —
            // never allow that ordering.
            if (tls_blob) |tb| {
                blobs.append(self.allocator, tb) catch {
                    self.allocator.free(tb);
                    self.allocator.free(blob);
                    continue;
                };
                pieces.append(self.allocator, .{ .kind = .tls_session, .bytes = tb }) catch {
                    self.allocator.free(blob);
                    continue;
                };
            }
            // Queue the WS marker BEFORE the session piece too (same ordering
            // rationale as TLS): its presence tells the successor to rebuild the
            // WebSocket adapter for this fd. An orphaned WS capsule is harmless
            // (ignored when no client matches its fd).
            if (carry_ws) {
                const wsst = e.value.ws.?;
                const wb = ws_snapshot.encode(self.allocator, .{
                    .fd = e.value.fd,
                    .phase_open = true,
                    .fragmented = wsst.deframer.fragmented,
                    .msg_binary = wsst.deframer.msg_binary,
                    // Partial framing state (introduced in v2): the buffered partial inbound
                    // frame's wire bytes + the partial outbound line, restored
                    // verbatim by the successor so no byte is lost mid-frame.
                    .deframer = wsst.deframer.buf[0..wsst.deframer.len],
                    .tx = wsst.tx_buf[0..wsst.tx_len],
                    .subprotocol = wsst.subprotocol,
                    .binary_message_active = wsst.binary_message_active,
                    .binary_message = wsst.binary_message_buf[0..wsst.binary_message_len],
                }) catch {
                    self.allocator.free(blob);
                    continue;
                };
                blobs.append(self.allocator, wb) catch {
                    self.allocator.free(wb);
                    self.allocator.free(blob);
                    continue;
                };
                pieces.append(self.allocator, .{ .kind = .ws_session, .bytes = wb }) catch {
                    self.allocator.free(blob);
                    continue;
                };
            }
            blobs.append(self.allocator, blob) catch {
                self.allocator.free(blob);
                continue;
            };
            pieces.append(self.allocator, .{ .kind = .clients, .bytes = blob }) catch continue;
            var sidecars_complete = true;
            // Carry exactly one MONITOR watch-list capsule for every client,
            // including an empty list. The inherited socket FD is the join key;
            // client ids do not survive the swap. A missing/incomplete sidecar
            // makes the whole client image unsealable, so UPGRADE stays in the
            // predecessor instead of silently dropping server-side state.
            const mon_client = monitorIdFromClient(e.id);
            carry_mon: {
                const mon_total = self.monitor.monitorCount(mon_client);
                if (mon_total > max_carried_monitor_targets) {
                    sidecars_complete = false;
                    break :carry_mon;
                }
                var targets: [max_carried_monitor_targets][]const u8 = undefined;
                const got = self.monitor.targetsInto(mon_client, targets[0..mon_total]);
                if (got != mon_total) {
                    sidecars_complete = false;
                    break :carry_mon;
                }
                var wire_len: usize = 4 + 1 + 8 + 2; // magic + version + client_id + count
                for (targets[0..got]) |t| wire_len += 2 + t.len;
                const mbuf = self.allocator.alloc(u8, wire_len) catch {
                    sidecars_complete = false;
                    break :carry_mon;
                };
                const wire = (monitor_capsule.MonitorCapsule{
                    .client_id = @intCast(e.value.fd),
                    .targets = targets[0..got],
                }).encode(mbuf) catch {
                    self.allocator.free(mbuf);
                    sidecars_complete = false;
                    break :carry_mon;
                };
                blobs.append(self.allocator, mbuf) catch {
                    self.allocator.free(mbuf);
                    sidecars_complete = false;
                    break :carry_mon;
                };
                pieces.append(self.allocator, .{ .kind = .monitor_list, .bytes = wire }) catch {
                    sidecars_complete = false;
                    break :carry_mon;
                };
            }
            // Carry the client's SILENCE list the same way (join key = fd in
            // client_id), including an empty list. The store is keyed by owner
            // nick; the successor resolves the adopted client's nick from the
            // fd. Failure closes the exact handoff instead of losing masks.
            carry_sil: {
                var sil_masks: [max_carried_silence_masks + 1][]const u8 = undefined;
                const sil_n = self.silence.masksInto(e.value.session.displayName(), &sil_masks);
                if (sil_n > max_carried_silence_masks) {
                    sidecars_complete = false;
                    break :carry_sil;
                }
                var wire_len: usize = 4 + 1 + 8 + 2; // magic + version + client_id + count
                for (sil_masks[0..sil_n]) |m| wire_len += 2 + m.len;
                const sbuf = self.allocator.alloc(u8, wire_len) catch {
                    sidecars_complete = false;
                    break :carry_sil;
                };
                const wire = (silence_capsule.SilenceCapsule{
                    .client_id = @intCast(e.value.fd),
                    .masks = sil_masks[0..sil_n],
                }).encode(sbuf) catch {
                    self.allocator.free(sbuf);
                    sidecars_complete = false;
                    break :carry_sil;
                };
                blobs.append(self.allocator, sbuf) catch {
                    self.allocator.free(sbuf);
                    sidecars_complete = false;
                    break :carry_sil;
                };
                pieces.append(self.allocator, .{ .kind = .silence_list, .bytes = wire }) catch {
                    sidecars_complete = false;
                    break :carry_sil;
                };
            }
            if (!sidecars_complete) continue;
            if (tls_blob != null) counts.tls += 1;
            if (carry_ws) counts.ws += 1;
            // Preserve the client socket so the successor re-attaches it.
            if (builtin.os.tag != .windows and !setCloexec(e.value.fd, builtin.os.tag == .openbsd)) {
                counts.fd_prepare_failed = true;
                continue;
            }
            carried_fds[fd_count.*] = e.value.fd;
            fd_count.* += 1;
            counts.clients += 1;
        }
    }

    fn performUpgrade(self: *LinuxServer, request: DeferredUpgradeRequest) !void {
        if (comptime builtin.os.tag == .openbsd) {
            const hooks = self.config.native_upgrade_hooks orelse return error.NativeUpgradeUnavailable;
            const exe_target = self.config.exe_path orelse return error.NativeUpgradeUnavailable;
            // Only the control socket crosses fork+exec. The leaf authenticates
            // the actual running image before any service/socket owner pauses.
            try hooks.begin(hooks.ctx, exe_target);
            defer hooks.abort(hooks.ctx);
            return self.performUpgradeAfterCompatibleTarget(request, -1, exe_target);
        }
        if (comptime builtin.os.tag == .windows) {
            const hooks = self.config.native_upgrade_hooks orelse return error.NativeUpgradeUnavailable;
            const exe_target = switch (request) {
                .client_target => |target| target.executable,
                else => self.config.exe_path orelse return error.NativeUpgradeUnavailable,
            };
            if (!self.windows_helix_source_valid.load(.acquire) or self.config.windows_helix_source_digest == null or
                self.config.config_path == null or !self.config.windows_helix_explicit_node_secret or
                !self.config.windows_helix_explicit_cloak_secret)
            {
                const reason = "UPGRADE refused: Windows config or external material has no exact source proof";
                srvLog("onyx-server: {s}\n", .{reason});
                self.deferredUpgradeNotice(request, reason);
                return error.NativeUpgradeUnavailable;
            }
            const candidate_claimed = if (std.meta.activeTag(request) == .windows_descriptor_rollover) blk: {
                lockSpin(&self.windows_upgrade_priority_lock);
                defer self.windows_upgrade_priority_lock.unlock();
                // The same lock publishes manual intent across all reactors.
                // Claiming before the pinned-image launch is the ordering cut:
                // any operator request already published must run first.
                if (self.windows_manual_upgrade_pending != 0) {
                    srvLog("onyx-server: Windows descriptor rollover UPGRADE deferred: operator UPGRADE is pending\n", .{});
                    return error.OperatorUpgradePending;
                }
                break :blk self.windows_helix_upgrade_claimed.cmpxchgStrong(false, true, .acq_rel, .acquire) == null;
            } else self.windows_helix_upgrade_claimed.cmpxchgStrong(false, true, .acq_rel, .acquire) == null;
            if (!candidate_claimed) {
                self.deferredUpgradeNotice(request, "UPGRADE refused: another Windows candidate is active");
                return error.UpgradeAlreadyActive;
            }
            defer self.windows_helix_upgrade_claimed.store(false, .release);
            switch (request) {
                .windows_descriptor_rollover => {
                    const begin_same_image = hooks.beginSameImage orelse return error.NativeUpgradeUnavailable;
                    try begin_same_image(hooks.ctx);
                },
                else => try hooks.begin(hooks.ctx, exe_target),
            }
            defer hooks.abort(hooks.ctx);
            if (comptime build_info.windows_rollover_smoke) {
                if (std.meta.activeTag(request) == .windows_descriptor_rollover) {
                    if (self.windowsRolloverSmokeMode()) |mode| {
                        srvLog("onyx-server: Windows rollover smoke pinned candidate negotiated (mode={s})\n", .{@tagName(mode)});
                        if (mode == .fail) return error.TestRolloverSmokeAbort;
                    }
                }
            }
            return self.performUpgradeAfterCompatibleTarget(request, -1, exe_target);
        }
        if (comptime builtin.os.tag != .linux) {
            self.deferredUpgradeNotice(request, "UPGRADE is unavailable on this target");
            return;
        }
        const exe_target = self.config.exe_path orelse "/proc/self/exe";
        const executable_fd = self.openCompatibleUpgradeTarget(exe_target) catch |e| {
            var eb: [160]u8 = undefined;
            self.world.lockWrite();
            defer self.world.unlockWrite();
            self.deferredUpgradeNotice(
                request,
                std.fmt.bufPrint(
                    &eb,
                    "UPGRADE refused: target binary cannot accept the exact Helix handoff ({s})",
                    .{@errorName(e)},
                ) catch "UPGRADE refused: target binary is Helix-incompatible",
            );
            self.publishOperEvent(.oper_action, .critical, "UPGRADE refused: target binary failed exact Helix capability probe") catch {};
            return error.UpgradeTargetIncompatible;
        };
        defer closeFd(executable_fd);

        return self.performUpgradeAfterCompatibleTarget(request, executable_fd, exe_target);
    }

    const UpgradeContinuityBlocker = enum {
        session_drop_transaction,
        relay_v2_deferred,
        webpush_overflow_delivery,
        webtransport_listener,
        acme_companion,
        media_rooms,
        media_plane,
        native_media,
        media_bridge,
    };

    /// Fail-closed inventory for process-owned continuity that Helix does not
    /// serialize yet. The caller holds World's write lock, which is the server's
    /// mutation boundary for MediaRooms/signaling. Transport predicates take
    /// their own pump locks; bridge values are inspected under their owner lock.
    fn upgradeContinuityBlockerLocked(self: *LinuxServer) ?UpgradeContinuityBlocker {
        // DROP reservations are RAM-only two-owner latches. Refuse rather than
        // serializing a half-committed identity transfer into the successor.
        if (self.session_drop_journal.activeCount() != 0) return .session_drop_transaction;
        // Deferred MESSAGE_V2 owns exact signed wire not yet published into
        // RVG2. Until it has a Helix capsule, exec must never discard it.
        if (self.relay_v2_deferred_len != 0) return .relay_v2_deferred;
        if (self.hasRetainedWebpushOverflow()) return .webpush_overflow_delivery;
        if (self.config.webtransport_port != 0 and
            (builtin.os.tag != .windows or self.windows_webtransport_owner == null))
            return .webtransport_listener;
        if (self.acme_reload_tls != null and (builtin.os.tag != .windows or self.acme_worker == null))
            return .acme_companion;
        const windows_media_checkpoint = builtin.os.tag == .windows and self.config.media_enabled;
        if (!windows_media_checkpoint and !self.media_rooms.upgradeContinuityReady()) return .media_rooms;
        // Windows seals a configured media Domain with both paused UDP owners
        // at the native transfer cut below. The pristine and active captures
        // each prove their own exact continuity before transfer.
        if (builtin.os.tag != .windows or !self.config.media_enabled) {
            if (!self.media_plane.upgradeContinuityReady()) return .media_plane;
            if (!self.native_media.upgradeContinuityReady()) return .native_media;
        }
        if (!windows_media_checkpoint) {
            lockSpin(&self.media_bridges_mu);
            defer self.media_bridges_mu.unlock();
            var bridges = self.media_bridges.valueIterator();
            while (bridges.next()) |bridge| {
                if (!bridge.upgradeContinuityReady()) return .media_bridge;
            }
        }
        return null;
    }

    fn upgradeContinuityBlockerName(blocker: UpgradeContinuityBlocker) []const u8 {
        return switch (blocker) {
            .session_drop_transaction => "SESSION DROP transaction",
            .relay_v2_deferred => "deferred MESSAGE_V2 authority",
            .webpush_overflow_delivery => "accepted Webpush overflow delivery",
            .webtransport_listener => "WebTransport listener",
            .acme_companion => "ACME renewal companion",
            .media_rooms => "media room control state",
            .media_plane => "WebRTC media transport state",
            .native_media => "native media transport state",
            .media_bridge => "cross-leg media bridge state",
        };
    }

    /// Post-capability-probe half of `performUpgrade`. Kept as a narrow test seam
    /// so failure-unwind tests can enter the producer barrier deterministically
    /// without depending on a separately-installed Onyx Server executable. Production
    /// reaches this only after `openCompatibleUpgradeTarget` has pinned and
    /// successfully probed `executable_fd`.
    fn performUpgradeAfterCompatibleTarget(
        self: *LinuxServer,
        request: DeferredUpgradeRequest,
        executable_fd: linux.fd_t,
        exe_target: []const u8,
    ) !void {

        // The metrics listener is a separate socket owner. Park its accept
        // loop at an operation boundary before freezing reactors and World;
        // rollback resumes the same bound listener and retained snapshot.
        var windows_metrics_pause: ?metrics_http.runtime_pause.Token = null;
        defer if (comptime builtin.os.tag == .windows) {
            if (windows_metrics_pause) |token| {
                if (self.metrics_server) |*owner| owner.resumePaused(token) catch @panic("Windows metrics pause could not resume");
            }
        };
        if (comptime builtin.os.tag == .windows) {
            if (self.metrics_server) |*owner| {
                const epoch = std.math.add(u64, self.windows_metrics_pause_epoch, 1) catch return error.InvalidRuntime;
                const token = try owner.requestPause(epoch);
                self.windows_metrics_pause_epoch = epoch;
                windows_metrics_pause = token;
                const io = self.config.crypto_io orelse return error.InvalidRuntime;
                try owner.awaitPaused(token, std.Io.Clock.Timestamp.fromNow(io, .{ .clock = .awake, .raw = .fromMilliseconds(30_000) }));
            }
        }

        // A Windows webhook worker parks after finishing the complete current
        // request. This works for both cold-boot and Gate-managed successors,
        // preserving the same bound listener through sequential upgrades.
        var windows_webhook_pause: ?webhook_http.runtime_pause.Token = null;
        defer if (comptime builtin.os.tag == .windows) {
            if (windows_webhook_pause) |token| {
                if (self.webhook_server) |*owner| owner.resumePaused(token) catch @panic("Windows webhook pause could not resume");
            }
        };
        if (comptime builtin.os.tag == .windows) {
            if (self.webhook_server) |*owner| {
                const epoch = std.math.add(u64, self.windows_webhook_pause_epoch, 1) catch return error.InvalidRuntime;
                const token = try owner.requestPause(epoch);
                self.windows_webhook_pause_epoch = epoch;
                windows_webhook_pause = token;
                const io = self.config.crypto_io orelse return error.InvalidRuntime;
                try owner.awaitPaused(token, std.Io.Clock.Timestamp.fromNow(io, .{ .clock = .awake, .raw = .fromMilliseconds(30_000) }));
            }
        }

        var windows_history_pause: ?history_http.runtime_pause.Token = null;
        defer if (comptime builtin.os.tag == .windows) {
            if (windows_history_pause) |token| {
                if (self.history_https) |*owner| owner.resumePaused(token) catch @panic("Windows history HTTPS pause could not resume");
            }
        };
        if (comptime builtin.os.tag == .windows) {
            if (self.history_https) |*owner| {
                const epoch = std.math.add(u64, self.windows_history_pause_epoch, 1) catch return error.InvalidRuntime;
                const token = try owner.requestPause(epoch);
                self.windows_history_pause_epoch = epoch;
                windows_history_pause = token;
                const io = self.config.crypto_io orelse return error.InvalidRuntime;
                try owner.awaitPaused(token, std.Io.Clock.Timestamp.fromNow(io, .{ .clock = .awake, .raw = .fromMilliseconds(30_000) }));
            }
        }

        var windows_webtransport_pause: ?@import("runtime_pause.zig").Token = null;
        defer if (comptime builtin.os.tag == .windows) {
            if (windows_webtransport_pause) |token| {
                if (self.windows_webtransport_owner) |owner| owner.resumePaused(token) catch @panic("Windows WebTransport pause could not resume");
            }
        };
        if (comptime builtin.os.tag == .windows) {
            if (self.windows_webtransport_owner) |owner| {
                if (owner.thread != null or owner.runtime.view != null) {
                    const epoch = std.math.add(u64, self.windows_webtransport_pause_epoch, 1) catch return error.InvalidRuntime;
                    const token = try owner.requestPause(epoch);
                    self.windows_webtransport_pause_epoch = epoch;
                    windows_webtransport_pause = token;
                    const io = self.config.crypto_io orelse return error.InvalidRuntime;
                    try owner.awaitPaused(token, std.Io.Clock.Timestamp.fromNow(io, .{ .clock = .awake, .raw = .fromMilliseconds(30_000) }));
                }
            }
        }

        // A live WebRTC owner may have accepted routed egress that is still in
        // its queue. Fence producers and let its worker drain that exact queue
        // before parking either media pump. On any refused upgrade, restore the
        // same producer authority after both paused workers have resumed.
        var windows_media_upgrade_fence: ?*MediaRoutingBacking = null;
        errdefer if (comptime builtin.os.tag == .windows) {
            if (windows_media_upgrade_fence) |owner| {
                const Cut = struct {
                    owner: *MediaRoutingBacking,
                    fn restore(scope: *media_routing.Locked, ctx: @This()) !void {
                        try ctx.owner.server.media_plane.resumeRoutingProducersLocked(
                            ctx.owner.domain,
                            scope,
                            ctx.owner.producer_fence orelse return error.InvalidRuntime,
                        );
                    }
                };
                owner.domain.withLocked(Cut{ .owner = owner }, Cut.restore) catch
                    @panic("Windows media producer fence could not resume after refused upgrade");
                owner.producer_fence = null;
            }
        };
        if (comptime builtin.os.tag == .windows) {
            if (self.config.media_enabled) {
                const owner = mediaRoutingBacking(self.media_routing_owner orelse return error.InvalidRuntime);
                if (owner.producer_fence != null) return error.InvalidRuntime;
                windows_media_upgrade_fence = owner;
                const deadline_ms = try checkedMonotonicDeadlineMillis(30_000);
                try self.settleMediaRoutingBeforeStop(deadline_ms);
            }
        }

        var windows_native_media_pause: ?@import("runtime_pause.zig").Token = null;
        defer if (comptime builtin.os.tag == .windows) {
            if (windows_native_media_pause) |token|
                self.native_media.resumePaused(token) catch @panic("Windows native media pause could not resume");
        };
        var windows_webrtc_media_pause: ?@import("runtime_pause.zig").Token = null;
        defer if (comptime builtin.os.tag == .windows) {
            if (windows_webrtc_media_pause) |token|
                self.media_plane.resumePaused(token) catch @panic("Windows WebRTC media pause could not resume");
        };
        if (comptime builtin.os.tag == .windows) {
            if (self.config.media_enabled) {
                const io = self.config.crypto_io orelse return error.InvalidRuntime;
                const deadline = std.Io.Clock.Timestamp.fromNow(io, .{ .clock = .awake, .raw = .fromMilliseconds(30_000) });
                const native_epoch = std.math.add(u64, self.windows_native_media_pause_epoch, 1) catch return error.InvalidRuntime;
                const native_token = try self.native_media.requestPause(native_epoch);
                self.windows_native_media_pause_epoch = native_epoch;
                windows_native_media_pause = native_token;
                try self.native_media.awaitPaused(native_token, deadline);
                const webrtc_epoch = std.math.add(u64, self.windows_webrtc_media_pause_epoch, 1) catch return error.InvalidRuntime;
                const webrtc_token = try self.media_plane.requestPause(webrtc_epoch);
                self.windows_webrtc_media_pause_epoch = webrtc_epoch;
                windows_webrtc_media_pause = webrtc_token;
                try self.media_plane.awaitPaused(webrtc_token, deadline);
            }
        }

        // Reverse DNS has a separate worker and queued FCrDNS jobs. Park it
        // before the reactor cut, then freeze producers only after all accepted
        // socket work has drained so no accepted client loses its lookup.
        var windows_rdns_pause: ?rdns.runtime_pause.Token = null;
        defer if (comptime builtin.os.tag == .windows) {
            if (windows_rdns_pause) |token| {
                if (self.config.rdns) |owner| owner.resumePaused(token) catch @panic("Windows rDNS pause could not resume");
            }
        };
        if (comptime builtin.os.tag == .windows) {
            const owner = self.config.rdns orelse return error.InvalidRuntime;
            if (owner.thread != null or owner.runtime.view != null) {
                const epoch = std.math.add(u64, self.windows_rdns_pause_epoch, 1) catch return error.InvalidRuntime;
                const token = try owner.requestPause(epoch);
                self.windows_rdns_pause_epoch = epoch;
                windows_rdns_pause = token;
                const io = self.config.crypto_io orelse return error.InvalidRuntime;
                try owner.awaitPaused(token, std.Io.Clock.Timestamp.fromNow(io, .{ .clock = .awake, .raw = .fromMilliseconds(30_000) }));
            }
        }
        var windows_dnsbl_pause: ?dnsbl_resolver.runtime_pause.Token = null;
        defer if (comptime builtin.os.tag == .windows) {
            if (windows_dnsbl_pause) |token| {
                if (self.config.dnsbl) |owner| owner.resumePaused(token) catch @panic("Windows DNSBL pause could not resume");
            }
        };
        if (comptime builtin.os.tag == .windows) {
            if (self.config.dnsbl) |owner| {
                if (owner.thread != null or owner.runtime.view != null) {
                    const epoch = std.math.add(u64, self.windows_dnsbl_pause_epoch, 1) catch return error.InvalidRuntime;
                    const token = try owner.requestPause(epoch);
                    self.windows_dnsbl_pause_epoch = epoch;
                    windows_dnsbl_pause = token;
                    const io = self.config.crypto_io orelse return error.InvalidRuntime;
                    try owner.awaitPaused(token, std.Io.Clock.Timestamp.fromNow(io, .{ .clock = .awake, .raw = .fromMilliseconds(30_000) }));
                }
            }
        }
        var windows_webpush_pause: ?webpush_mod.runtime_pause.Token = null;
        defer if (comptime builtin.os.tag == .windows) {
            if (windows_webpush_pause) |token| {
                if (self.webpush_worker) |owner| owner.resumePaused(token) catch @panic("Windows Web Push pause could not resume");
            }
        };
        if (comptime builtin.os.tag == .windows) {
            if (self.webpush_worker) |owner| {
                if (owner.thread != null or owner.runtime.view != null) {
                    const epoch = std.math.add(u64, self.windows_webpush_pause_epoch, 1) catch return error.InvalidRuntime;
                    const token = try owner.requestPause(epoch);
                    self.windows_webpush_pause_epoch = epoch;
                    windows_webpush_pause = token;
                    const io = self.config.crypto_io orelse return error.InvalidRuntime;
                    try owner.awaitPaused(token, std.Io.Clock.Timestamp.fromNow(io, .{ .clock = .awake, .raw = .fromMilliseconds(30_000) }));
                }
            }
        }
        var windows_geo_pause: ?geo_services.runtime_pause.Token = null;
        defer if (comptime builtin.os.tag == .windows) {
            if (windows_geo_pause) |token| self.geo.resumePaused(token) catch @panic("Windows Geo pause could not resume");
        };
        if (comptime builtin.os.tag == .windows) {
            if (self.geo.thread != null or self.geo.runtime.view != null) {
                const epoch = std.math.add(u64, self.windows_geo_pause_epoch, 1) catch return error.InvalidRuntime;
                const token = try self.geo.requestPause(epoch);
                self.windows_geo_pause_epoch = epoch;
                windows_geo_pause = token;
                const io = self.config.crypto_io orelse return error.InvalidRuntime;
                try self.geo.awaitPaused(token, std.Io.Clock.Timestamp.fromNow(io, .{ .clock = .awake, .raw = .fromMilliseconds(30_000) }));
            }
        }
        var windows_mail_pause: ?mail_sender.runtime_pause.Token = null;
        defer if (comptime builtin.os.tag == .windows) {
