        };
        var sbuf: [320]u8 = undefined;
        srvLog("onyx-server: {s}\n", .{std.fmt.bufPrint(&sbuf, "UPGRADE: {d} capsule(s) sealed ({d} TLS, {d} wss, {d} mesh link(s) preserved, {d} re-dial hint(s), {d} session account(s), {d} replica object(s), {d} staged migration(s), {d} consumed tombstone(s), mandatory state {d}/{d}/{d}/{d}/{d}/{d} bytes); re-exec preserving listener", .{ prepared.capsule_count, tls_carried, ws_carried, s2s_preserved, s2s_hints, session_accounts_sealed, replica_objects_sealed, migrations_sealed, tombstones_sealed, mandatory_state_sealed.world_bytes, mandatory_state_sealed.history_bytes, mandatory_state_sealed.webhook_bytes, mandatory_state_sealed.relay_replay_bytes, mandatory_state_sealed.event_replay_bytes, mandatory_state_sealed.e2ee_group_replay_bytes }) catch "UPGRADE: re-exec"});

        // Preserve EVERY shard's client listener + the arena across execve
        // (clear FD_CLOEXEC). The successor adopts one listener per shard, so
        // no shard's SO_REUSEPORT accept queue is dropped at the swap. The list
        // is shard-ordered; entry 0 also rides the singular env variable for
        // an older successor image.
        const listener_fds = self.allocator.alloc(linux.fd_t, self.reactors.len) catch |e| {
            restoreCloexec(carried_fds[0..carried_fd_count]);
            var eb: [96]u8 = undefined;
            self.deferredUpgradeNotice(request, std.fmt.bufPrint(&eb, "UPGRADE failed (plan): {s}", .{@errorName(e)}) catch "UPGRADE failed");
            return;
        };
        defer self.allocator.free(listener_fds);
        var listener_fd_count: usize = 0;
        for (self.reactors, listener_fds) |*r, *lfd| {
            lfd.* = r.listener_fd;
            if (!setCloexec(r.listener_fd, false)) {
                restoreCloexec(carried_fds[0..carried_fd_count]);
                restoreCloexec(listener_fds[0..listener_fd_count]);
                self.deferredUpgradeNotice(request, "UPGRADE refused: a listener fd could not be prepared for exec");
                return error.SessionReplicaConverging;
            }
            listener_fd_count += 1;
        }
        if (!setCloexec(arena.fd, false)) {
            restoreCloexec(carried_fds[0..carried_fd_count]);
            restoreCloexec(listener_fds[0..listener_fd_count]);
            self.deferredUpgradeNotice(request, "UPGRADE refused: the sealed state arena fd could not be prepared for exec");
            return error.SessionReplicaConverging;
        }
        // Exec the on-disk launch path (the swapped-in new binary) when known,
        // not /proc/self/exe (which re-runs the current, old image). Carry the
        // config path so the successor boots with the real config.
        var plan = helix_live.buildArenaListenerExecPlan(
            self.allocator,
            exe_target,
            arena.fd,
            listener_fds,
            carried_fds[0..carried_fd_count],
            self.config.config_path,
        ) catch |e| {
            restoreCloexec(carried_fds[0..carried_fd_count]);
            restoreCloexec(listener_fds);
            _ = setCloexec(arena.fd, true);
            var eb: [96]u8 = undefined;
            self.deferredUpgradeNotice(request, std.fmt.bufPrint(&eb, "UPGRADE failed (plan): {s}", .{@errorName(e)}) catch "UPGRADE failed");
            return;
        };
        defer plan.deinit(self.allocator);
        plan.commitExecutableFd(self.allocator, executable_fd) catch |e| {
            restoreCloexec(carried_fds[0..carried_fd_count]);
            restoreCloexec(listener_fds);
            _ = setCloexec(arena.fd, true);
            var eb: [96]u8 = undefined;
            self.deferredUpgradeNotice(request, std.fmt.bufPrint(&eb, "UPGRADE failed (execve): {s}", .{@errorName(e)}) catch "UPGRADE failed");
            return;
        };
    }

    /// Successor side of UPGRADE: read the inherited state arena and re-attach
    /// every carried-over client connection (inherited socket fd + restored
    /// session, plus its live TLS engine when one was carried) into the client
    /// table and stage mesh redials / connection I/O activation for the first
    /// reactor turn. Called after Server.init but before the successor starts
    /// serving. Invalid, incomplete, or failed capsule adoption is startup-fatal;
    /// no partial inherited population is published.
    fn clearInheritedStateFdManifest(self: *LinuxServer) void {
        self.config.inherited_state_fds = &.{};
        self.config.inherited_state_fd_manifest_present = false;
        self.config.inherited_state_fd_manifest_valid = false;
    }

    const InheritedStateFdClaims = struct {
        fds: []const linux.fd_t,
        claimed: []bool,

        /// Claim one ownership-bearing client/S2S capsule fd exactly once.
        /// TLS/WS and per-client sidecars only reference a socket and therefore
        /// never call this method.
        fn claim(self: *InheritedStateFdClaims, fd: linux.fd_t) bool {
            for (self.fds, 0..) |candidate, index| {
                if (candidate != fd) continue;
                if (self.claimed[index]) return false;
                self.claimed[index] = true;
                return true;
            }
            return false;
        }

        fn allClaimed(self: *const InheritedStateFdClaims) bool {
            for (self.claimed) |claimed| if (!claimed) return false;
            return true;
        }
    };

    /// Trust the version-independent manifest only when it is a bounded set of
    /// state sockets disjoint from the arena and every inherited/live listener.
    /// A malformed environment must never trick cleanup into closing the port.
    fn inheritedStateFdIsConnectedStreamSocket(fd: linux.fd_t) bool {
        if (comptime builtin.os.tag == .windows) {
            io_backend.observeWindowsHelixConnectedTcpSocket(fd) catch |err| {
                srvLog("onyx-server: Windows Helix inherited state socket {d} invalid ({s})\n", .{ fd, @errorName(err) });
                return false;
            };
            return true;
        }
        if (comptime builtin.os.tag == .openbsd) {
            if (!os_runtime.fdValid(fd)) return false;
            const socket_type = os_runtime.socketType(fd) catch return false;
            if (socket_type != posix.SOCK.STREAM) return false;
            var peer: os_runtime.AddressStorage = undefined;
            var peer_len: os_runtime.AddressLength = @sizeOf(os_runtime.AddressStorage);
            os_runtime.getpeername(fd, &peer, &peer_len) catch return false;
            return true;
        }
        if (fd < 0 or linux.errno(linux.fcntl(fd, posix.F.GETFD, 0)) != .SUCCESS)
            return false;

        var socket_type: u32 = 0;
        var socket_type_len: posix.socklen_t = @sizeOf(@TypeOf(socket_type));
        const type_rc = linux.getsockopt(
            fd,
            posix.SOL.SOCKET,
            posix.SO.TYPE,
            @ptrCast(&socket_type),
            &socket_type_len,
        );
        if (linux.errno(type_rc) != .SUCCESS or
            socket_type_len != @sizeOf(@TypeOf(socket_type)) or
            socket_type != posix.SOCK.STREAM)
            return false;

        // A listener or merely-created stream socket has the right SO_TYPE but
        // no peer. Only an accepted/connected endpoint is valid carried state.
        var peer: posix.sockaddr.storage = undefined;
        var peer_len: posix.socklen_t = @sizeOf(posix.sockaddr.storage);
        return linux.errno(linux.getpeername(fd, @ptrCast(&peer), &peer_len)) == .SUCCESS;
    }

    fn inheritedStateFdManifestTrusted(self: *LinuxServer, arena_fd: linux.fd_t) bool {
        if (!self.config.inherited_state_fd_manifest_present or
            !self.config.inherited_state_fd_manifest_valid or
            (self.config.inherited_state_fds.len == 0 and builtin.os.tag == .linux) or
            self.config.inherited_state_fds.len > helix_live.max_inherited_state_fds)
            return false;

        // The arena is itself inherited and untrusted. Reject an alias to any
        // service listener before readArena's failure cleanup can close the port.
        if (arena_fd >= 0) {
            if (self.config.inherited_listener_fd) |listener_fd| {
                if (arena_fd == listener_fd) return false;
            }
            for (self.config.inherited_listener_fds) |listener_fd| {
                if (arena_fd == listener_fd) return false;
            }
            for (self.config.inherited_listener_companion_fds) |listener_fd| {
                if (arena_fd == listener_fd) return false;
            }
            for (self.reactors) |*r| {
                if (r.ownsListenerFd(arena_fd)) return false;
            }
        }

        for (self.config.inherited_state_fds, 0..) |fd, i| {
            if (fd == arena_fd or !inheritedStateFdIsConnectedStreamSocket(fd)) return false;
            if (self.config.inherited_listener_fd) |listener_fd| {
                if (fd == listener_fd) return false;
            }
            for (self.config.inherited_listener_fds) |listener_fd| {
                if (fd == listener_fd) return false;
            }
            for (self.config.inherited_listener_companion_fds) |listener_fd| {
                if (fd == listener_fd) return false;
            }
            for (self.reactors) |*r| {
                if (r.ownsListenerFd(fd)) return false;
            }
            for (self.config.inherited_state_fds[0..i]) |prior| {
                if (fd == prior) return false;
            }
        }
        return true;
    }

    /// Close the exact authoritative state-fd set when it is trustworthy, then
    /// clear the borrowed config slice before any caller can attempt cleanup a
    /// second time. Returns false for legacy/malformed manifests.
    fn closeInheritedStateFdManifest(self: *LinuxServer, arena_fd: linux.fd_t) bool {
        if (!self.inheritedStateFdManifestTrusted(arena_fd)) {
            self.clearInheritedStateFdManifest();
            return false;
        }
        const state_fds = self.config.inherited_state_fds;
        self.clearInheritedStateFdManifest();
        for (state_fds) |fd| closeFd(fd);
        return true;
    }

    fn inheritedOwningCapsuleFd(c: helix_capsule.Capsule) ?linux.fd_t {
        if (c.fields.len == 0) return null;
        return switch (c.header.kind) {
            .clients => session_snapshot.peekFd(c.fields[0].bytes),
            .s2s_link => s2s_snapshot.peekFd(c.fields[0].bytes),
            else => null,
        };
    }

    fn inheritedOwningFdSeenBefore(caps: []const helix_capsule.Capsule, index: usize, fd: linux.fd_t) bool {
        for (caps[0..index]) |prior| {
            if (inheritedOwningCapsuleFd(prior)) |prior_fd| {
                if (prior_fd == fd) return true;
            }
        }
        return false;
    }

    /// Mandatory state families are exact singleton authorities, not
    /// best-effort/evolvable records. Null covers absence and every ambiguous
    /// representation; the caller abandons the complete handoff in either case.
    fn canonicalMandatorySingleton(
        caps: []const helix_capsule.Capsule,
        kind: helix_capsule.CapsuleKind,
    ) ?[]const u8 {
        const descriptor = helix_capsule.descriptor(kind);
        var selected: ?[]const u8 = null;
        for (caps) |c| {
            if (c.header.kind != kind) continue;
            if (selected != null or
                c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != descriptor.min_supported or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
                return null;
            selected = c.fields[0].bytes;
        }
        return selected;
    }

    /// Validate the restored MESSAGE_V2 consequence authorities as one image.
    /// Individually well-formed RVG2/RVO2/RVL2 checkpoints are not sufficient:
    /// an outbound retry without its exact retained wire, or a retained wire the
    /// replay guard considers unseen/equivocating, would publish a torn handoff.
    /// Receipt-only RVO2 rows are deliberately excluded because a confirmed or
    /// retired RVL2 row may leave its ingress ACK proof alive until confirmation.
    const RelayV2RestoreRelationFailure = enum {
        retry_without_event,
        retry_unbound_peer,
        retry_local_peer,
        retry_peer_not_required,
        retry_peer_already_confirmed,
        retry_wire_mismatch,
        local_node_not_required,
        local_node_not_confirmed,
        unknown_required_peer,
        invalid_retained_wire,
        replay_probe_failed,
        replay_identity_mismatch,
        replay_authority_missing,
    };

    fn relayV2RestoreRelationFailure(
        self: *const LinuxServer,
        guard: *const relay_v2_replay_guard.Guard,
        outbox: *const relay_v2_outbox.Outbox,
        event_log: *const relay_v2_event_log.EventLog,
    ) ?RelayV2RestoreRelationFailure {
        for (outbox.items()) |entry| {
            const row = event_log.viewFor(entry.relay_id) orelse return .retry_without_event;
            if (entry.peer == relay_v2_outbox.unbound_peer) return .retry_unbound_peer;
            if (entry.peer == self.config.node_id) return .retry_local_peer;
            if (std.mem.indexOfScalar(u64, row.required_nodes, entry.peer) == null) return .retry_peer_not_required;
            if (std.mem.indexOfScalar(u64, row.confirmed_nodes, entry.peer) != null) return .retry_peer_already_confirmed;
            if (!std.mem.eql(u8, row.wire, entry.wire)) return .retry_wire_mismatch;
        }
        for (0..event_log.len()) |index| {
            const row = event_log.viewAt(index);
            if (self.config.node_id == 0 or
                std.mem.indexOfScalar(u64, row.required_nodes, self.config.node_id) == null) return .local_node_not_required;
            if (std.mem.indexOfScalar(u64, row.confirmed_nodes, self.config.node_id) == null) return .local_node_not_confirmed;
            for (row.required_nodes) |required| {
                if (std.mem.indexOfScalar(u64, row.confirmed_nodes, required) != null) continue;
                if (std.mem.indexOfScalar(u64, self.relay_v2_required_nodes, required) == null)
                    return .unknown_required_peer;
            }
            var owned = message_relay_v2.decode(self.allocator, row.wire) catch return .invalid_retained_wire;
            defer owned.deinit(self.allocator);
            switch (guard.probeMessage(owned.msg) catch return .replay_probe_failed) {
                .duplicate => |id| if (!std.mem.eql(u8, &id, &row.relay_id)) return .replay_identity_mismatch,
                .retired => |id| if (!std.mem.eql(u8, &id, &row.relay_id)) return .replay_identity_mismatch,
                else => return .replay_authority_missing,
            }
        }
        return null;
    }

    fn relayV2RestoreRelationValid(
        self: *const LinuxServer,
        guard: *const relay_v2_replay_guard.Guard,
        outbox: *const relay_v2_outbox.Outbox,
        event_log: *const relay_v2_event_log.EventLog,
    ) bool {
        return self.relayV2RestoreRelationFailure(guard, outbox, event_log) == null;
    }

    fn abandonInheritedSessionState(self: *LinuxServer, caps: anytype, arena_fd: linux.fd_t, reason: []const u8) void {
        // New predecessors provide a version-independent exact fd set, so even
        // an unfamiliar capsule schema cannot strand sockets. Legacy or invalid
        // manifests fall back to the structurally decoded fixed fd prefixes.
        if (!self.closeInheritedStateFdManifest(arena_fd)) {
            for (caps, 0..) |c, index| {
                const fd = inheritedOwningCapsuleFd(c) orelse continue;
                if (fd >= 0 and !inheritedOwningFdSeenBefore(caps, index, fd)) closeFd(fd);
            }
        }
        closeFd(arena_fd);
        self.config.resume_arena_fd = null;
        self.config.native_arena_bytes = null;
        srvLog("onyx-server: UPGRADE resume refused inherited state: {s}\n", .{reason});
    }

    const NativeBotStage = struct {
        allocator: std.mem.Allocator,
        table: *bot_grant_snapshot.Table,
        registry: bot_registry_mod.BotRegistry,

        fn deinit(self: *NativeBotStage) void {
            self.registry.deinit();
            self.allocator.destroy(self.table);
        }
    };

    fn stageNativeBotGrants(self: *LinuxServer, checkpoint: ?bot_grant_snapshot.Snapshot) !NativeBotStage {
        const table = try self.allocator.create(bot_grant_snapshot.Table);
        errdefer self.allocator.destroy(table);
        table.* = self.bot_grants;
        var registry = bot_registry_mod.BotRegistry.init(self.allocator);
        errdefer registry.deinit();
        var existing = self.bot_registry.map.iterator();
        while (existing.next()) |row| {
            try registry.register(row.key_ptr.*, row.value_ptr.info);
            const replacement = registry.map.getPtr(row.key_ptr.*).?;
            @memcpy(replacement.ring.stamps, row.value_ptr.ring.stamps);
            replacement.ring.head = row.value_ptr.ring.head;
            replacement.ring.len = row.value_ptr.ring.len;
        }
        if (checkpoint) |snap| {
            var bots = snap.botIterator();
            while (bots.next()) |account| {
                try table.insertBot(account);
                try registry.register(account, .{});
            }
            var grants = snap.grantIterator();
            while (grants.next()) |g| try table.upsert(g.account, g.kind, g.scope, g.expiry_ms, self.grantNowU64());
        }
        return .{ .allocator = self.allocator, .table = table, .registry = registry };
    }

    fn validateInheritedAdmissionRelation(
        self: *LinuxServer,
        detector: ?*clone_detect_mod.CloneDetector,
        clones: ?*mesh_clones_mod.MeshClones,
    ) (error{InvalidAdmissionRelation} || std.mem.Allocator.Error)!void {
        var throttle_counts = std.StringHashMap(usize).init(self.allocator);
        defer throttle_counts.deinit();
        if (detector) |value| {
            var ips = value.ips.iterator();
            while (ips.next()) |entry| try throttle_counts.put(entry.key_ptr.*, 0);
        }
        var clone_counts = std.AutoHashMap(u64, usize).init(self.allocator);
        defer clone_counts.deinit();
        if (clones) |value| {
            var locals = value.local.iterator();
            while (locals.next()) |entry| try clone_counts.put(entry.key_ptr.*, 0);
        }
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                if (conn.throttle_counted) {
                    if (detector == null) return error.InvalidAdmissionRelation;
                    const addr = conn.peer_addr orelse return error.InvalidAdmissionRelation;
                    var ip_buf: [128]u8 = undefined;
                    const ip = addrText(addr, &ip_buf) orelse return error.InvalidAdmissionRelation;
                    const count = throttle_counts.getPtr(ip) orelse return error.InvalidAdmissionRelation;
                    count.* = std.math.add(usize, count.*, 1) catch return error.InvalidAdmissionRelation;
                }
                if (conn.mesh_clone_counted) {
                    if (clones == null) return error.InvalidAdmissionRelation;
                    const hash = self.meshCloneHash(conn) orelse return error.InvalidAdmissionRelation;
                    if (hash != conn.mesh_clone_hash) return error.InvalidAdmissionRelation;
                    const count = clone_counts.getPtr(conn.mesh_clone_hash) orelse return error.InvalidAdmissionRelation;
                    count.* = std.math.add(usize, count.*, 1) catch return error.InvalidAdmissionRelation;
                }
            }
        }
        if (detector) |value| {
            var counts = throttle_counts.iterator();
            while (counts.next()) |entry| {
                if (entry.value_ptr.* != value.activeCount(entry.key_ptr.*))
                    return error.InvalidAdmissionRelation;
            }
        }
        if (clones) |value| {
            var counts = clone_counts.iterator();
            while (counts.next()) |entry| {
                if (entry.value_ptr.* != value.localCount(entry.key_ptr.*))
                    return error.InvalidAdmissionRelation;
            }
        }
    }

    pub fn adoptInheritedSessions(self: *LinuxServer) error{ InvalidInheritedHandoff, DurableDeviceActivationFailed }!void {
        if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd and builtin.os.tag != .windows) {
            io_backend.refuseForeignCapsule() catch return error.InvalidInheritedHandoff;
            return error.InvalidInheritedHandoff;
        }
        const arena_fd: linux.fd_t = if (builtin.os.tag == .openbsd or builtin.os.tag == .windows) blk: {
            if (self.config.native_arena_bytes == null) {
                if (self.config.resume_arena_fd != null or self.config.inherited_state_fd_manifest_present or
                    self.config.native_adopt_barrier != null or self.config.native_listener_manifest.len != 0) return error.InvalidInheritedHandoff;
                return;
            }
            if (self.config.resume_arena_fd != null or self.config.native_adopt_barrier == null or
                self.config.native_listener_manifest.len == 0)
            {
                if (comptime builtin.os.tag == .windows)
                    srvLog("onyx-server: Windows Helix incomplete native adoption inputs (arena_fd={any}, barrier={any}, listeners={d})\n", .{ self.config.resume_arena_fd, self.config.native_adopt_barrier != null, self.config.native_listener_manifest.len });
                return error.InvalidInheritedHandoff;
            }
            break :blk -1;
        } else self.config.resume_arena_fd orelse {
            // A state-fd manifest without its arena is an incomplete handoff. A
            // malformed/colliding list is startup-fatal because guessing at
            // numeric fds is unsafe (the kernel closes the whole table on exit).
            // A TRUSTED exact list is recoverable: we can close precisely the
            // named descriptors and cold-boot with the process still up — but that
            // silently downgrades a hot upgrade to a cold boot, so LOG it loudly
            // (this branch is an anomaly: the predecessor should always seal the
            // arena alongside the manifest, so a missing arena means a bug there).
            if (self.config.inherited_state_fd_manifest_present) {
                if (!self.inheritedStateFdManifestTrusted(-1))
                    return error.InvalidInheritedHandoff;
                srvLog("onyx-server: UPGRADE resume DOWNGRADED to cold boot — state-fd manifest present but sealed arena fd absent; closing {d} carried descriptor(s) and booting fresh\n", .{self.config.inherited_state_fds.len});
                _ = self.closeInheritedStateFdManifest(-1);
            }
            return;
        };
        // A present malformed/colliding manifest is a startup-fatal handoff,
        // not legacy absence. Do not guess which numeric descriptors are safe
        // to close: returning the error makes main unwind/exit and lets the
        // kernel close the inherited table atomically before a cold restart.
        if (self.config.inherited_state_fd_manifest_present and
            !self.inheritedStateFdManifestTrusted(arena_fd))
        {
            if (comptime builtin.os.tag == .windows)
                srvLog("onyx-server: Windows Helix inherited state manifest refused ({d} socket(s), {d} listener(s))\n", .{ self.config.inherited_state_fds.len, self.config.native_listener_manifest.len });
            return error.InvalidInheritedHandoff;
        }
        // Boot-time only (before the reactor loop): bind this thread to reactor
        // 0, the reactor that owns the inherited listener and every connection
        // adopted below.
        current_reactor = &self.reactors[0];
        const caps = (if (builtin.os.tag == .openbsd or builtin.os.tag == .windows) blk: {
            const bytes = self.config.native_arena_bytes.?;
            if (bytes.len > helix_live.max_arena_bytes) break :blk error.ArenaTooLarge;
            break :blk helix_capsule.decodeStream(self.allocator, bytes);
        } else helix_live.readArena(self.allocator, arena_fd)) catch |e| {
            _ = self.closeInheritedStateFdManifest(arena_fd);
            closeFd(arena_fd);
            self.config.resume_arena_fd = null;
            self.config.native_arena_bytes = null;
            srvLog("onyx-server: UPGRADE resume — arena read failed ({s})\n", .{@errorName(e)});
            return error.InvalidInheritedHandoff;
        };
        defer {
            for (caps) |*c| c.deinit(self.allocator);
            self.allocator.free(caps);
        }
        helix_live.verifyHandoffManifest(caps) catch |e| {
            var reason_buf: [128]u8 = undefined;
            const reason = std.fmt.bufPrint(
                &reason_buf,
                "invalid or incomplete whole-handoff manifest ({s})",
                .{@errorName(e)},
            ) catch "invalid or incomplete whole-handoff manifest";
            self.abandonInheritedSessionState(caps, arena_fd, reason);
            return error.InvalidInheritedHandoff;
        };
        const relations = handoff_relations.validateCurrent(caps, self.config.inherited_state_fds) catch |e| {
            var reason_buf: [128]u8 = undefined;
            const reason = std.fmt.bufPrint(
                &reason_buf,
                "invalid whole-handoff ownership relation ({s})",
                .{@errorName(e)},
            ) catch "invalid whole-handoff ownership relation";
            self.abandonInheritedSessionState(caps, arena_fd, reason);
            return error.InvalidInheritedHandoff;
        };
        if (relations.tls_replay != @as(usize, @intFromBool(builtin.os.tag == .windows and self.config.tls_enable_resumption))) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing or unexpected Windows TLS replay authority");
            return error.InvalidInheritedHandoff;
        }
