                    };
                    const restored = reputation_replacement.?.config;
                    const expected = self.reputation.config;
                    if (restored.half_life_ms != expected.half_life_ms or
                        @as(u64, @bitCast(restored.refuse_threshold)) != @as(u64, @bitCast(expected.refuse_threshold)) or
                        @as(u64, @bitCast(restored.negligible)) != @as(u64, @bitCast(expected.negligible)))
                    {
                        self.abandonInheritedSessionState(caps, arena_fd, "configuration-incompatible Windows reputation checkpoint");
                        return error.InvalidInheritedHandoff;
                    }
                } else if (spamtrap_checkpoint.isCheckpoint(bytes)) {
                    spamtrap_replacement = spamtrap_checkpoint.decode(self.allocator, bytes) catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid Windows spamtrap checkpoint");
                        srvLog("onyx-server: Windows spamtrap restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                } else if (native_windows_webpush.isCheckpoint(bytes)) {
                    const owner = self.webpush_worker orelse unreachable;
                    const result = if (owner.runtime.view != null)
                        native_windows_webpush.restoreEncodedParked(self.allocator, owner, bytes)
                    else
                        native_windows_webpush.restoreEncoded(self.allocator, owner, bytes);
                    result catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid Windows Web Push checkpoint");
                        srvLog("onyx-server: Windows Web Push restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                } else if (native_windows_geo.isCheckpoint(bytes)) {
                    const result = if (self.geo.runtime.view != null)
                        native_windows_geo.restoreEncodedParked(self.allocator, self.geo, bytes)
                    else
                        native_windows_geo.restoreEncoded(self.allocator, self.geo, bytes);
                    result catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid Windows Geo checkpoint");
                        srvLog("onyx-server: Windows Geo restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                } else if (native_windows_mail.isCheckpoint(bytes)) {
                    const owner = self.config.mail_sender orelse unreachable;
                    const result = if (owner.runtime.view != null)
                        native_windows_mail.restoreEncodedParked(self.allocator, owner, bytes)
                    else
                        native_windows_mail.restoreEncoded(self.allocator, owner, bytes);
                    result catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid Windows mail checkpoint");
                        srvLog("onyx-server: Windows mail restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                } else if (native_windows_acme.isCheckpoint(bytes)) {
                    const owner = self.acme_worker orelse unreachable;
                    native_windows_acme.restoreEncodedParked(owner, bytes) catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid Windows ACME scheduler checkpoint");
                        srvLog("onyx-server: Windows ACME scheduler restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                } else if (native_windows_tls_material.isCheckpoint(bytes)) {
                    tls_material_replacement = native_windows_tls_material.decodeOwned(self.allocator, bytes) catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid Windows TLS material checkpoint");
                        srvLog("onyx-server: Windows TLS material restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                    _ = tls_material_replacement.?.servingDigest() catch {
                        self.abandonInheritedSessionState(caps, arena_fd, "Windows TLS material has invalid serving identity");
                        return error.InvalidInheritedHandoff;
                    };
                } else if (native_windows_wasm.isCheckpoint(bytes)) {
                    wasm_replacement = native_windows_wasm.stage(
                        self.allocator,
                        bytes,
                        self.wasm.options,
                        self.config.wasm_plugin_dir,
                    ) catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid Windows OroWasm checkpoint");
                        srvLog("onyx-server: Windows OroWasm restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                } else if (native_windows_ocsp.isCheckpoint(bytes)) {
                    const owner = self.ocsp_worker orelse unreachable;
                    native_windows_ocsp.restoreEncodedParked(owner, bytes) catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid Windows OCSP scheduler checkpoint");
                        srvLog("onyx-server: Windows OCSP scheduler restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                } else if (native_windows_ocsp_state.isCheckpoint(bytes)) {
                    if (self.ocsp_staple_owned != null or self.ocsp_staple_prev != null or
                        self.ocsp_staple_incoming != null or self.config.tls_ocsp_staple != null)
                    {
                        self.abandonInheritedSessionState(caps, arena_fd, "Windows OCSP candidate has preexisting staple ownership");
                        return error.InvalidInheritedHandoff;
                    }
                    ocsp_state_replacement = native_windows_ocsp_state.decodeOwned(self.allocator, bytes) catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid Windows OCSP staple checkpoint");
                        srvLog("onyx-server: Windows OCSP staple restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                } else if (clone_detect_mod.isUpgradeCheckpoint(bytes)) {
                    const expected = if (self.conn_throttle) |*detector| detector.params else unreachable;
                    throttle_replacement = clone_detect_mod.CloneDetector.restoreUpgradeCheckpoint(
                        self.allocator,
                        expected,
                        bytes,
                    ) catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid or configuration-incompatible Windows connection-throttle checkpoint");
                        srvLog("onyx-server: Windows connection-throttle restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                } else if (mesh_clones_mod.isUpgradeCheckpoint(bytes)) {
                    mesh_clones_replacement = mesh_clones_mod.MeshClones.restoreUpgradeCheckpoint(
                        self.allocator,
                        bytes,
                    ) catch |e| {
                        self.abandonInheritedSessionState(caps, arena_fd, "invalid Windows mesh-clone checkpoint");
                        srvLog("onyx-server: Windows mesh-clone restore failed ({s})\n", .{@errorName(e)});
                        return error.InvalidInheritedHandoff;
                    };
                }
            }
        }

        if (comptime builtin.os.tag == .windows) {
            if (tls_material_replacement) |*replacement| {
                if (replacement.reload_pending and self.acme_worker == null) {
                    self.abandonInheritedSessionState(caps, arena_fd, "Windows TLS reload intent has no ACME owner");
                    return error.InvalidInheritedHandoff;
                }
            }
            if (ocsp_state_replacement) |*replacement| {
                if (replacement.active) {
                    const serving_chain = if (tls_material_replacement) |*material|
                        material.default.?.cert_chain
                    else
                        self.config.tls_cert_chain;
                    ocsp_restored_valid_until_unix = managed_ocsp.stapleValidUntilForChain(
                        replacement.current.?,
                        serving_chain,
                        @divFloor(platform.realtimeMillis(), 1000),
                        @import("../crypto/ocsp.zig").default_staple_skew_seconds,
                    ) orelse {
                        self.abandonInheritedSessionState(caps, arena_fd, "Windows OCSP staple is incompatible with transferred TLS leaf");
                        return error.InvalidInheritedHandoff;
                    };
                }
            }
        }

        // Before publishing ANY restored state, bind every ownership-bearing
        // client/S2S capsule to the exact version-independent descriptor set.
        // This rejects an unauthorized or duplicate fd before it can be adopted
        // twice, while leaving sidecar TLS/WS/session capsules free to reference
        // the same socket as their one owning capsule.
        var state_fd_claim_bits: ?[]bool = null;
        defer if (state_fd_claim_bits) |bits| self.allocator.free(bits);
        var state_fd_claims: ?InheritedStateFdClaims = null;
        if (self.config.inherited_state_fd_manifest_present) {
            const bits = self.allocator.alloc(bool, self.config.inherited_state_fds.len) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "could not allocate inherited-fd claim set");
                return error.InvalidInheritedHandoff;
            };
            @memset(bits, false);
            state_fd_claim_bits = bits;
            state_fd_claims = .{ .fds = self.config.inherited_state_fds, .claimed = bits };
            for (caps) |c| {
                if (c.header.kind != .clients and c.header.kind != .s2s_link) continue;
                if (c.fields.len != 1 or c.fields[0].ordinal != 1) {
                    self.abandonInheritedSessionState(caps, arena_fd, "invalid inherited-fd owner capsule");
                    return error.InvalidInheritedHandoff;
                }
                const maybe_fd = switch (c.header.kind) {
                    .clients => session_snapshot.peekFd(c.fields[0].bytes),
                    .s2s_link => s2s_snapshot.peekFd(c.fields[0].bytes),
                    else => unreachable,
                };
                const fd = maybe_fd orelse {
                    self.abandonInheritedSessionState(caps, arena_fd, "missing inherited-fd owner prefix");
                    return error.InvalidInheritedHandoff;
                };
                if (fd < 0 or !state_fd_claims.?.claim(fd)) {
                    self.abandonInheritedSessionState(caps, arena_fd, "invalid or duplicate inherited-fd owner");
                    return error.InvalidInheritedHandoff;
                }
            }
            if (!state_fd_claims.?.allClaimed()) {
                self.abandonInheritedSessionState(caps, arena_fd, "unclaimed inherited descriptor");
                return error.InvalidInheritedHandoff;
            }
        } else {
            // The current whole-handoff relation has already proved there are
            // no client/S2S owner capsules when the fd manifest is absent. This
            // is the legitimate state-only arena shape; no descriptor ownership
            // exists to claim or alias here.
        }

        // The current Helix contract always carries these three authorities,
        // including their empty images. Exact current descriptor metadata plus
        // one ordinal-1 field keeps absence, duplicates, and evolvable wrapper
        // ambiguity from silently degrading a hot upgrade into a disk reload.
        const world_checkpoint_bytes = canonicalMandatorySingleton(caps, .channels) orelse {
            self.abandonInheritedSessionState(caps, arena_fd, "missing, duplicate, or noncanonical World checkpoint");
            return error.InvalidInheritedHandoff;
        };
        const history_checkpoint_bytes = canonicalMandatorySingleton(caps, .history) orelse {
            self.abandonInheritedSessionState(caps, arena_fd, "missing, duplicate, or noncanonical history checkpoint");
            return error.InvalidInheritedHandoff;
        };
        const webhook_checkpoint_bytes = canonicalMandatorySingleton(caps, .webhook_store) orelse {
            self.abandonInheritedSessionState(caps, arena_fd, "missing, duplicate, or noncanonical webhook checkpoint");
            return error.InvalidInheritedHandoff;
        };
        var relay_replay_checkpoint_bytes: ?[]const u8 = null;
        var relay_outbox_checkpoint_bytes: ?[]const u8 = null;
        var relay_event_log_checkpoint_bytes: ?[]const u8 = null;
        var attachment_delivery_checkpoint_bytes: ?[]const u8 = null;
        var event_replay_checkpoint_bytes: ?[]const u8 = null;
        var e2ee_group_replay_checkpoint_bytes: ?[]const u8 = null;
        const mesh_descriptor = helix_capsule.descriptor(.mesh_checkpoint);
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint) continue;
            var recognized_e2ee_group = false;
            for (c.fields) |field| {
                if (e2ee_group_mesh_authority.isCheckpoint(field.bytes)) {
                    recognized_e2ee_group = true;
                    break;
                }
            }
            if (recognized_e2ee_group) {
                if (e2ee_group_replay_checkpoint_bytes != null or
                    c.header.schema_id != mesh_descriptor.schema_id or
                    c.header.version != mesh_descriptor.current_version or
                    c.header.min_supported != 2 or
                    c.header.max_supported != mesh_descriptor.max_supported or
                    c.fields.len != 1 or c.fields[0].ordinal != 1 or
                    !e2ee_group_mesh_authority.isCheckpoint(c.fields[0].bytes))
                {
                    self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate E2EEGROUP replay checkpoint");
                    return error.InvalidInheritedHandoff;
                }
                e2ee_group_replay_checkpoint_bytes = c.fields[0].bytes;
                continue;
            }
            var recognized_relay = false;
            for (c.fields) |field| {
                if (relay_v2_replay_guard.isCheckpoint(field.bytes)) {
                    recognized_relay = true;
                    break;
                }
            }
            if (recognized_relay) {
                if (relay_replay_checkpoint_bytes != null or
                    c.header.schema_id != mesh_descriptor.schema_id or
                    c.header.version != mesh_descriptor.current_version or
                    c.header.min_supported != 2 or
                    c.header.max_supported != mesh_descriptor.max_supported or
                    c.fields.len != 1 or c.fields[0].ordinal != 1 or
                    !relay_v2_replay_guard.isCheckpoint(c.fields[0].bytes))
                {
                    self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate MESSAGE_V2 replay checkpoint");
                    return error.InvalidInheritedHandoff;
                }
                relay_replay_checkpoint_bytes = c.fields[0].bytes;
                continue;
            }
            var recognized_outbox = false;
            for (c.fields) |field| {
                if (relay_v2_outbox.isCheckpoint(field.bytes)) {
                    recognized_outbox = true;
                    break;
                }
            }
            if (recognized_outbox) {
                if (relay_outbox_checkpoint_bytes != null or
                    c.header.schema_id != mesh_descriptor.schema_id or
                    c.header.version != mesh_descriptor.current_version or
                    c.header.min_supported != 2 or
                    c.header.max_supported != mesh_descriptor.max_supported or
                    c.fields.len != 1 or c.fields[0].ordinal != 1 or
                    !relay_v2_outbox.isCheckpoint(c.fields[0].bytes))
                {
                    self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate MESSAGE_V2 outbox checkpoint");
                    return error.InvalidInheritedHandoff;
                }
                relay_outbox_checkpoint_bytes = c.fields[0].bytes;
                continue;
            }
            var recognized_event_log = false;
            for (c.fields) |field| {
                if (relay_v2_event_log.isCheckpoint(field.bytes)) {
                    recognized_event_log = true;
                    break;
                }
            }
            if (recognized_event_log) {
                if (relay_event_log_checkpoint_bytes != null or
                    c.header.schema_id != mesh_descriptor.schema_id or
                    c.header.version != mesh_descriptor.current_version or
                    c.header.min_supported != 2 or
                    c.header.max_supported != mesh_descriptor.max_supported or
                    c.fields.len != 1 or c.fields[0].ordinal != 1 or
                    !relay_v2_event_log.isCheckpoint(c.fields[0].bytes))
                {
                    self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate MESSAGE_V2 event-log checkpoint");
                    return error.InvalidInheritedHandoff;
                }
                relay_event_log_checkpoint_bytes = c.fields[0].bytes;
                continue;
            }
            var recognized_attachment_delivery = false;
            for (c.fields) |field| {
                if (attachment_delivery_spool.isCheckpoint(field.bytes)) {
                    recognized_attachment_delivery = true;
                    break;
                }
            }
            if (recognized_attachment_delivery) {
                if (attachment_delivery_checkpoint_bytes != null or
                    c.header.schema_id != mesh_descriptor.schema_id or
                    c.header.version != mesh_descriptor.current_version or
                    c.header.min_supported != 2 or
                    c.header.max_supported != mesh_descriptor.max_supported or
                    c.fields.len != 1 or c.fields[0].ordinal != 1 or
                    !attachment_delivery_spool.isCheckpoint(c.fields[0].bytes))
                {
                    self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate attachment-delivery checkpoint");
                    return error.InvalidInheritedHandoff;
                }
                attachment_delivery_checkpoint_bytes = c.fields[0].bytes;
                continue;
            }
            var recognized = false;
            for (c.fields) |field| {
                if (event_spine_replay_guard.isCheckpoint(field.bytes)) {
                    recognized = true;
                    break;
                }
            }
            if (!recognized) continue;
            if (event_replay_checkpoint_bytes != null or
                c.header.schema_id != mesh_descriptor.schema_id or
                c.header.version != mesh_descriptor.current_version or
                c.header.min_supported != 2 or
                c.header.max_supported != mesh_descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1 or
                !event_spine_replay_guard.isCheckpoint(c.fields[0].bytes))
            {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate Event Spine replay checkpoint");
                return error.InvalidInheritedHandoff;
            }
            event_replay_checkpoint_bytes = c.fields[0].bytes;
        }
        if (relay_replay_checkpoint_bytes == null) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory MESSAGE_V2 replay checkpoint");
            return error.InvalidInheritedHandoff;
        }
        if (relay_outbox_checkpoint_bytes == null) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory MESSAGE_V2 outbox checkpoint");
            return error.InvalidInheritedHandoff;
        }
        if (relay_event_log_checkpoint_bytes == null) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory MESSAGE_V2 event-log checkpoint");
            return error.InvalidInheritedHandoff;
        }
        if (attachment_delivery_checkpoint_bytes == null) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory attachment-delivery checkpoint");
            return error.InvalidInheritedHandoff;
        }
        if (event_replay_checkpoint_bytes == null) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory Event Spine replay checkpoint");
            return error.InvalidInheritedHandoff;
        }
        if (e2ee_group_replay_checkpoint_bytes == null) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory E2EEGROUP replay checkpoint");
            return error.InvalidInheritedHandoff;
        }

        // Decode all mandatory images and the complete client/member projection
        // before the boot-exclusive publication boundary. Every value below is
        // independently owned; a late failure destroys only staged candidates.
        var world_replacement = world_checkpoint.decode(self.allocator, world_checkpoint_bytes) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid World checkpoint");
            return error.InvalidInheritedHandoff;
        };
        defer world_replacement.deinit();

        const history_payloads = history_checkpoint.decode(.{}, history_checkpoint_bytes) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid history checkpoint bundle");
            return error.InvalidInheritedHandoff;
        };
        var history_replacement = HistoryStore.decodeCheckpoint(self.allocator, history_payloads.lotus) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid Lotus history checkpoint");
            return error.InvalidInheritedHandoff;
        };
        defer history_replacement.deinit();
        var search_replacement = search_index_mod.SearchIndex.decodeCheckpoint(
            self.allocator,
            self.config.search_index_config,
            history_payloads.search_index,
        ) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid search-index checkpoint");
            return error.InvalidInheritedHandoff;
        };
        defer search_replacement.deinit();
        const event_history_replacement = event_history_mod.EventHistory(512).restoreHelixCheckpoint(
            history_payloads.event_history,
        ) orelse {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid EventHistory checkpoint");
            return error.InvalidInheritedHandoff;
        };
        var relay_replay_replacement = relay_v2_replay_guard.Guard.decodeCheckpoint(
            self.allocator,
            self.relay_v2_replay_guard.config,
            relay_replay_checkpoint_bytes.?,
        ) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid or configuration-incompatible MESSAGE_V2 replay checkpoint");
            return error.InvalidInheritedHandoff;
        };
        defer relay_replay_replacement.deinit();
        var relay_outbox_replacement = relay_v2_outbox.Outbox.decodeCheckpoint(
            self.allocator,
            self.relay_v2_outbox.max_entries,
            relay_outbox_checkpoint_bytes.?,
        ) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid or configuration-incompatible MESSAGE_V2 outbox checkpoint");
            return error.InvalidInheritedHandoff;
        };
        defer relay_outbox_replacement.deinit();
        var relay_event_log_replacement = relay_v2_event_log.EventLog.decodeCheckpoint(
            self.allocator,
            self.relay_v2_event_log.config,
            relay_event_log_checkpoint_bytes.?,
        ) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid or configuration-incompatible MESSAGE_V2 event-log checkpoint");
            return error.InvalidInheritedHandoff;
        };
        defer relay_event_log_replacement.deinit();
        if (self.relayV2RestoreRelationFailure(
            &relay_replay_replacement,
            &relay_outbox_replacement,
            &relay_event_log_replacement,
        )) |reason| {
            srvLog("onyx-server: inherited MESSAGE_V2 relation failed ({s})\n", .{@tagName(reason)});
            self.abandonInheritedSessionState(caps, arena_fd, "inconsistent MESSAGE_V2 replay, retry, and retained-event checkpoints");
            return error.InvalidInheritedHandoff;
        }
        var attachment_delivery_replacement = attachment_delivery_spool.Spool.decodeCheckpoint(
            self.allocator,
            self.attachment_delivery_spool.config,
            attachment_delivery_checkpoint_bytes.?,
        ) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid or configuration-incompatible attachment-delivery checkpoint");
            return error.InvalidInheritedHandoff;
        };
        defer attachment_delivery_replacement.deinit();
        var event_replay_replacement = event_spine_replay_guard.Guard.decodeCheckpoint(
            self.allocator,
            self.event_spine_replay_guard.config,
            event_replay_checkpoint_bytes.?,
        ) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid or configuration-incompatible Event Spine replay checkpoint");
            return error.InvalidInheritedHandoff;
        };
        defer event_replay_replacement.deinit();
        var e2ee_group_replay_replacement = e2ee_group_mesh_authority.Authority.decodeCheckpoint(
            self.allocator,
            self.e2ee_group_mesh_authority.config,
            e2ee_group_replay_checkpoint_bytes.?,
        ) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid or configuration-incompatible E2EEGROUP replay checkpoint");
            return error.InvalidInheritedHandoff;
        };
        defer e2ee_group_replay_replacement.deinit();
        const webhook_replacement = webhook_mod.WebhookStore.restoreUpgradeCheckpoint(
            webhook_checkpoint_bytes,
        ) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "invalid webhook checkpoint");
            return error.InvalidInheritedHandoff;
        };

        var client_capsule_count: usize = 0;
        var projected_member_count: usize = 0;
        for (caps) |c| {
            if (c.header.kind != .clients) continue;
            const descriptor = helix_capsule.descriptor(.clients);
            if (c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != descriptor.min_supported or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                self.abandonInheritedSessionState(caps, arena_fd, "malformed client wrapper in World projection");
                return error.InvalidInheritedHandoff;
            }
            const snap = session_snapshot.decodeCurrent(c.fields[0].bytes) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "malformed client snapshot in World projection");
                return error.InvalidInheritedHandoff;
            };
            client_capsule_count = std.math.add(usize, client_capsule_count, 1) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "client projection count overflow");
                return error.InvalidInheritedHandoff;
            };
            var channels = session_snapshot.channelIter(snap.channels_blob);
            while (channels.next()) |_| {
                projected_member_count = std.math.add(usize, projected_member_count, 1) catch {
                    self.abandonInheritedSessionState(caps, arena_fd, "client membership projection overflow");
                    return error.InvalidInheritedHandoff;
                };
            }
            if (channels.remaining == null or channels.remaining.? != 0) {
                self.abandonInheritedSessionState(caps, arena_fd, "truncated client membership projection");
                return error.InvalidInheritedHandoff;
            }
        }
        const member_projection = self.allocator.alloc(
            world_checkpoint.MemberProjection,
            projected_member_count,
        ) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "could not stage client membership projection");
            return error.InvalidInheritedHandoff;
        };
        defer self.allocator.free(member_projection);
        const client_projection = self.allocator.alloc(
            world_checkpoint.ClientProjection,
            client_capsule_count,
        ) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "could not stage client relation projection");
            return error.InvalidInheritedHandoff;
        };
        defer self.allocator.free(client_projection);
        var projected_index: usize = 0;
        var projected_client_index: usize = 0;
        for (caps) |c| {
            if (c.header.kind != .clients) continue;
            // An identical decode already succeeded in the counting loop above, so
            // this is dead in practice — but never assert `unreachable` on
            // inherited bytes: propagate into the existing transactional abort so
            // any drift between the two passes fails closed instead of panicking.
            const snap = session_snapshot.decodeCurrent(c.fields[0].bytes) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "malformed client snapshot in World relation projection");
                return error.InvalidInheritedHandoff;
            };
            if (snap.fd < 0) {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid client fd in World relation projection");
                return error.InvalidInheritedHandoff;
            }
            const join_key: u64 = @intCast(snap.fd);
            client_projection[projected_client_index] = .{
                .join_key = join_key,
                .nick = snap.nick,
            };
            projected_client_index += 1;
            var channels = session_snapshot.channelIter(snap.channels_blob);
            while (channels.next()) |membership| {
                member_projection[projected_index] = .{
                    .channel = membership.name,
                    .join_key = join_key,
                    .nick = snap.nick,
                    .modes = .{ .bits = membership.modes },
                };
                projected_index += 1;
            }
        }
        std.debug.assert(projected_index == member_projection.len);
        std.debug.assert(projected_client_index == client_projection.len);
        world_replacement.validateMemberProjection(member_projection) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "client snapshots do not exactly project the World membership image");
            return error.InvalidInheritedHandoff;
        };
        world_replacement.validateInviteProjection(client_projection) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "client snapshots do not exactly project the World invite image");
            return error.InvalidInheritedHandoff;
        };

        // Stage the mandatory mesh clock alongside every exact singleton below.
        // Nothing is published until PROP, SESSION_REPLICA, and PMST have all
        // decoded and validated successfully; a late corrupt singleton must
        // leave the whole successor image untouched.
        lockSpin(&self.mesh_clock_lock);
        var staged_mesh_clock = self.mesh_clock;
        var staged_migration_offer_epoch = self.migration_offer_epoch;
        self.mesh_clock_lock.unlock();
        var mesh_clock_checkpoint_seen = false;
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint) continue;
            var recognized = false;
            for (c.fields) |field| {
                if (field.bytes.len >= mesh_clock_snapshot.magic.len and
                    std.mem.eql(u8, field.bytes[0..mesh_clock_snapshot.magic.len], &mesh_clock_snapshot.magic))
                {
                    recognized = true;
                    break;
                }
            }
            if (!recognized) continue;
            const descriptor = helix_capsule.descriptor(.mesh_checkpoint);
            if (mesh_clock_checkpoint_seen or
                c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != 2 or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate mesh-clock checkpoint");
                return error.InvalidInheritedHandoff;
            }
            const restored = mesh_clock_snapshot.decodeCurrent(c.fields[0].bytes) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "malformed mesh-clock checkpoint");
                return error.InvalidInheritedHandoff;
            };
            if (!relay_v2_activation.permitsHandoff(
                restored.relay_v2_activation,
                self.relay_v2_activation_state,
            )) {
                self.abandonInheritedSessionState(caps, arena_fd, "MESSAGE_V2 activation state is downgraded, unstaged, or roster-mismatched");
                return error.InvalidInheritedHandoff;
            }
            staged_mesh_clock = restored.clock;
            staged_migration_offer_epoch = restored.migration_offer_epoch;
            mesh_clock_checkpoint_seen = true;
        }
        if (!mesh_clock_checkpoint_seen) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory mesh-clock checkpoint");
            return error.InvalidInheritedHandoff;
        }

        // Select the carried cross-mesh oper-grant registry image without
        // publishing it. AT-MOST-once: an arena sealed by a pre-checkpoint
        // predecessor lacks the piece and adopts with an empty registry (the
        // exact pre-checkpoint behavior, mirroring a pre-v4 rosterless
        // `.s2s_link` capsule); requiring it would cold-refuse the first
        // post-introduction USR2. Present-but-malformed, downgraded, or
        // duplicate images reject the complete handoff fail-closed.
        var oper_grant_checkpoint: ?oper_grant_snapshot.Snapshot = null;
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint) continue;
            var recognized = false;
            for (c.fields) |field| {
                if (oper_grant_snapshot.isCheckpoint(field.bytes)) {
                    recognized = true;
                    break;
                }
            }
            if (!recognized) continue;
            const descriptor = helix_capsule.descriptor(.mesh_checkpoint);
            if (oper_grant_checkpoint != null or
                c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != 2 or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate oper-grant checkpoint");
                return error.InvalidInheritedHandoff;
            }
            oper_grant_checkpoint = oper_grant_snapshot.decodeCurrent(c.fields[0].bytes) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "malformed oper-grant checkpoint");
                return error.InvalidInheritedHandoff;
            };
        }
        if (comptime builtin.os.tag == .windows) {
            if (self.config.native_arena_bytes != null and oper_grant_checkpoint == null) {
                self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory Windows oper-grant checkpoint");
                return error.InvalidInheritedHandoff;
            }
        }

        // Same at-most-once rule as oper grants: a pre-checkpoint arena lacks
        // BGNT and adopts with an empty bot-grant table. A malformed or
        // duplicate image rejects the handoff. Restoring the table does not
        // set operator privilege bits.
        var bot_grant_checkpoint: ?bot_grant_snapshot.Snapshot = null;
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint) continue;
            var recognized = false;
            for (c.fields) |field| {
                if (bot_grant_snapshot.isCheckpoint(field.bytes)) {
                    recognized = true;
                    break;
                }
            }
            if (!recognized) continue;
            const descriptor = helix_capsule.descriptor(.mesh_checkpoint);
            if (bot_grant_checkpoint != null or
                c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != 2 or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate bot-grant checkpoint");
                return error.InvalidInheritedHandoff;
            }
            bot_grant_checkpoint = bot_grant_snapshot.decodeCurrent(c.fields[0].bytes) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "malformed bot-grant checkpoint");
                return error.InvalidInheritedHandoff;
            };
        }

        // Same at-most-once rule: a pre-thread arena lacks THRD and adopts with
        // an empty thread table. A malformed or duplicate image rejects the handoff.
        var thread_checkpoint: ?thread_snapshot.Snapshot = null;
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint) continue;
            var recognized = false;
            for (c.fields) |field| {
                if (thread_snapshot.isCheckpoint(field.bytes)) {
                    recognized = true;
                    break;
                }
            }
            if (!recognized) continue;
            const descriptor = helix_capsule.descriptor(.mesh_checkpoint);
            if (thread_checkpoint != null or
                c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != 2 or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate thread checkpoint");
                return error.InvalidInheritedHandoff;
            }
            thread_checkpoint = thread_snapshot.decodeCurrent(c.fields[0].bytes) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "malformed thread checkpoint");
                return error.InvalidInheritedHandoff;
            };
        }

        // Same at-most-once rule: a pre-schedule arena lacks SCHD and adopts
        // with an empty table. A malformed or duplicate image rejects the handoff.
        var schedule_checkpoint: ?schedule_snapshot.Snapshot = null;
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint) continue;
            var recognized = false;
            for (c.fields) |field| {
                if (schedule_snapshot.isCheckpoint(field.bytes)) {
                    recognized = true;
                    break;
                }
            }
            if (!recognized) continue;
            const descriptor = helix_capsule.descriptor(.mesh_checkpoint);
            if (schedule_checkpoint != null or
                c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != 2 or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate schedule checkpoint");
                return error.InvalidInheritedHandoff;
            }
            schedule_checkpoint = schedule_snapshot.decodeCurrent(c.fields[0].bytes) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "malformed schedule checkpoint");
                return error.InvalidInheritedHandoff;
            };
        }

        // Select the process-global TLS ticket-key authority without publishing
        // it. Resumption-enabled predecessors in the current Helix contract emit
        // exactly one canonical v1 singleton. Missing, duplicate, malformed, or
        // evolvable-wrapper variants are ambiguous key authority and therefore
        // reject the complete handoff. A resumption-disabled successor likewise
        // rejects any key capsule instead of silently importing secret state the
        // active configuration says must not exist.
        var ticket_key_replacement: ?ticket_key_capsule.Snapshot = null;
        const ticket_descriptor = helix_capsule.descriptor(.tls_ticket_keys);
        for (caps) |c| {
            if (c.header.kind != .tls_ticket_keys) continue;
            if (!self.config.tls_enable_resumption) {
                self.abandonInheritedSessionState(caps, arena_fd, "unexpected TLS ticket-key authority while resumption is disabled");
                return error.InvalidInheritedHandoff;
            }
            const canonical_outer = c.header.schema_id == ticket_descriptor.schema_id and
                c.header.version == ticket_descriptor.current_version and
                c.header.min_supported == ticket_descriptor.min_supported and
                c.header.max_supported == ticket_descriptor.max_supported;
            if (!canonical_outer or c.fields.len != 1 or c.fields[0].ordinal != 1 or
                ticket_key_replacement != null)
            {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid, noncanonical, or duplicate TLS ticket-key authority");
                return error.InvalidInheritedHandoff;
            }
            ticket_key_replacement = ticket_key_capsule.decodeCurrent(c.fields[0].bytes) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "malformed TLS ticket-key authority");
                return error.InvalidInheritedHandoff;
            };
        }
        if (self.config.tls_enable_resumption and ticket_key_replacement == null) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing TLS ticket-key authority while resumption is enabled");
            return error.InvalidInheritedHandoff;
        }

        // Restore raw PROP rows and both LWW/tombstone maps as one mandatory-v2
        // image before any replica/client/link can observe the successor. The
        // recognizable property bytes under min=1 are a downgrade attempt.
        // `min=2` is shared by multiple mandatory authorities (PROP and ESG2),
        // so it is not itself a property discriminator; whole-relation
        // validation above already rejects every unknown current family.
        var property_checkpoint_bytes: ?[]const u8 = null;
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint) continue;
            var recognized = false;
            for (c.fields) |field| {
                if (prop_checkpoint.isUpgradeCheckpoint(field.bytes)) {
                    recognized = true;
                    break;
                }
            }
            if (!recognized) continue;
            if (c.header.version != 2 or c.header.min_supported != 2 or c.header.max_supported != 2 or
                c.fields.len != 1 or c.fields[0].ordinal != 1 or
                !prop_checkpoint.isUpgradeCheckpoint(c.fields[0].bytes) or
                property_checkpoint_bytes != null)
            {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid, downgraded, unknown, or duplicate property-state checkpoint");
                return error.InvalidInheritedHandoff;
            }
            property_checkpoint_bytes = c.fields[0].bytes;
        }
        const durable_hot_plan = validateDurableDeviceBoot(self.config) catch |err| {
            var reason_buf: [160]u8 = undefined;
            const reason = std.fmt.bufPrint(
                &reason_buf,
                "invalid DPROP1 boot authority during hot adoption ({s})",
                .{@errorName(err)},
            ) catch "invalid DPROP1 boot authority during hot adoption";
            self.abandonInheritedSessionState(caps, arena_fd, reason);
            return error.DurableDeviceActivationFailed;
        };
        if (property_checkpoint_bytes == null and durable_hot_plan == .inactive) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory property-state checkpoint");
            return error.InvalidInheritedHandoff;
        }
        // Select the signed exact-token authority singleton without publishing it.
        // Recognizable Store bytes in any non-canonical field are a malformed
        // wrapper, not an ignorable ordinary mesh checkpoint.
        const replica_now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        var replica_checkpoint: ?[]const u8 = null;
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint) continue;
            var recognized = false;
            for (c.fields) |field| {
                if (session_replica_v2.Store.isUpgradeCheckpoint(field.bytes)) {
                    recognized = true;
                    break;
                }
            }
            if (!recognized) continue;
            // Whole-relation validation above establishes this is a current
            // handoff. Keep the Store selector equally strict: accepting a
            // legacy outer or inner SRST here would omit current attachment
            // lease authority while presenting a current arena.
            const descriptor = helix_capsule.descriptor(.mesh_checkpoint);
            const canonical_outer = c.header.schema_id == descriptor.schema_id and
                c.header.version == descriptor.current_version and
                c.header.min_supported == descriptor.min_supported and
                c.header.max_supported == descriptor.max_supported;
            if (!canonical_outer or
                c.fields.len != 1 or c.fields[0].ordinal != 1 or
                !session_replica_v2.Store.isUpgradeCheckpoint(c.fields[0].bytes) or
                replica_checkpoint != null)
            {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid or duplicate SESSION_REPLICA Store checkpoint");
                return error.InvalidInheritedHandoff;
            }
            replica_checkpoint = c.fields[0].bytes;
        }
        if (replica_checkpoint == null) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory SESSION_REPLICA Store checkpoint");
            return error.InvalidInheritedHandoff;
        }

        // Select the complete pending-migration holding area without publishing
        // it. Helix schema v2 is exactly one min=2/max=2 PMST checkpoint; mixing
        // it with legacy per-entry/tombstone capsules is ambiguous. This is a
        // current whole handoff, so there is no best-effort legacy restore arm.
        var pending_checkpoint: ?[]const u8 = null;
        const pending_descriptor = helix_capsule.descriptor(.pending_migration);
        for (caps) |c| switch (c.header.kind) {
            .pending_migration => {
                if (c.header.schema_id != pending_descriptor.schema_id or
                    c.header.version != pending_descriptor.current_version or
                    c.header.min_supported != 2 or c.header.max_supported != 2 or
                    c.fields.len != 1 or c.fields[0].ordinal != 1 or pending_checkpoint != null)
                {
                    self.abandonInheritedSessionState(caps, arena_fd, "invalid or duplicate current pending-migration checkpoint");
                    return error.InvalidInheritedHandoff;
                }
                pending_checkpoint = c.fields[0].bytes;
            },
            .session_tombstone => {
                self.abandonInheritedSessionState(caps, arena_fd, "legacy session tombstone in current whole handoff");
                return error.InvalidInheritedHandoff;
            },
            else => {},
        };
        if (pending_checkpoint == null) {
            self.abandonInheritedSessionState(caps, arena_fd, "missing mandatory pending-migration checkpoint");
            return error.InvalidInheritedHandoff;
        }

        // Decode every exact singleton into an independently-owned replacement.
        // Each defer destroys either an unpublished candidate on failure or the
        // displaced old live image after the no-fail commit below.
        var property_replacement: ?prop_checkpoint.Restored = null;
        defer if (property_replacement) |*replacement| replacement.deinit();
        if (property_checkpoint_bytes) |checkpoint| {
            property_replacement = prop_checkpoint.decode(self.allocator, checkpoint) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid property-state checkpoint");
                return error.InvalidInheritedHandoff;
            };
        }
        switch (durable_hot_plan) {
            .inactive => {},
            .purge_only, .authoritative => {
                const base_props = if (property_replacement) |*replacement| &replacement.props else &self.props;
                const base_channel = if (property_replacement) |*replacement| &replacement.channel_clocks else &self.channel_prop_clocks;
                const base_entity = if (property_replacement) |*replacement| &replacement.entity_clocks else &self.entity_prop_clocks;
                var reconciled = buildConfiguredDurableDeviceCandidate(
                    self.allocator,
                    base_props,
                    base_channel,
                    base_entity,
                    durable_hot_plan,
                ) catch |err| {
                    var reason_buf: [160]u8 = undefined;
                    const reason = std.fmt.bufPrint(
                        &reason_buf,
                        "DPROP1 hot property reconciliation failed ({s})",
                        .{@errorName(err)},
                    ) catch "DPROP1 hot property reconciliation failed";
                    self.abandonInheritedSessionState(caps, arena_fd, reason);
                    return error.DurableDeviceActivationFailed;
                };
                if (property_replacement) |*replacement| replacement.deinit();
                property_replacement = reconciled;
                reconciled = undefined;
            },
        }
        if (property_replacement) |*replacement| {
            staged_mesh_clock.observeChecked(
                replacement.max_hlc,
                self.meshWallMs(),
                mesh_clock_mod.default_max_future_skew_ms,
            ) catch |err| {
                var reason_buf: [176]u8 = undefined;
                const reason = std.fmt.bufPrint(
                    &reason_buf,
                    "property-state HLC is future-skewed or exhausted ({s})",
                    .{@errorName(err)},
                ) catch "property-state HLC is future-skewed or exhausted";
                self.abandonInheritedSessionState(caps, arena_fd, reason);
                if (durable_hot_plan != .inactive)
                    return error.DurableDeviceActivationFailed;
                return error.InvalidInheritedHandoff;
            };
        }

        var replica_replacement: ?session_replica_v2.Store = null;
        defer if (replica_replacement) |*replacement| replacement.deinit();
        if (replica_checkpoint) |checkpoint| {
            replica_replacement = session_replica_v2.Store.restoreCurrentUpgradeCheckpoint(
                self.allocator,
                self.session_replica_store.cfg,
                checkpoint,
                replica_now_wall,
            ) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid SESSION_REPLICA Store checkpoint");
                return error.InvalidInheritedHandoff;
            };
            if (replica_replacement.?.maxAuthorityRevision()) |revision| {
                staged_mesh_clock.observeChecked(
                    revision.sequence,
                    self.meshWallMs(),
                    session_replica_v2.default_max_future_skew_ms,
                ) catch {
                    self.abandonInheritedSessionState(caps, arena_fd, "SESSION_REPLICA Store clock is future-skewed or exhausted");
                    return error.InvalidInheritedHandoff;
                };
            }
        }

        var pending_replacement: ?session_migrate.PendingMigrations = null;
        defer if (pending_replacement) |*replacement| replacement.deinit();
        if (pending_checkpoint) |checkpoint| {
            const pending_cfg: session_migrate.PendingMigrations.Config = if (self.pending_migrations) |pending|
                pending.cfg
            else
                .{
                    .max_entries = self.config.session_max_pending_migrations,
                    .max_per_account = self.config.session_max_per_account,
                };
            pending_replacement = session_migrate.PendingMigrations.restoreUpgradeCheckpoint(
                self.allocator,
                pending_cfg,
                checkpoint,
                @max(@as(i64, 0), self.nowMs()),
                mesh_reclaim_ttl_ms,
            ) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "invalid pending-migration checkpoint");
                return error.InvalidInheritedHandoff;
            };
        }

        // Stage every mutable late-adoption authority behind a boot-only
        // transaction. Client reconstruction still uses the ordinary server
        // helpers, but those helpers now see candidate client tables and fresh
        // Session/MONITOR/SILENCE stores. On any later error the errdefers below
        // restore the byte-for-byte boot image before this public function
        // returns; a caller may catch InvalidInheritedHandoff without observing a
        // torn successor. No reactor SQE or service thread is active here.
        for (self.reactors) |*reactor| {
            if (reactor.clients.len() != 0 or !reactor.acceptsQuiesced() or reactor.timer_armed or
                reactor.wake_armed)
            {
                self.abandonInheritedSessionState(caps, arena_fd, "successor reactor is not inert before inherited-state adoption");
                return error.InvalidInheritedHandoff;
            }
        }

        const staged_client_tables = self.allocator.alloc(ClientTable, self.reactors.len) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "could not allocate candidate client tables");
            return error.InvalidInheritedHandoff;
        };
        var staged_client_tables_initialized: usize = 0;
        defer {
            for (staged_client_tables[0..staged_client_tables_initialized]) |*table| table.deinit();
            self.allocator.free(staged_client_tables);
        }
        while (staged_client_tables_initialized < staged_client_tables.len) : (staged_client_tables_initialized += 1) {
            const shard_id: u12 = @intCast(staged_client_tables_initialized);
            staged_client_tables[staged_client_tables_initialized] = ClientTable.init(self.allocator, shard_id);
            staged_client_tables[staged_client_tables_initialized].reserve(self.config.max_clients) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "could not reserve a candidate client table");
                return error.InvalidInheritedHandoff;
            };
        }

        var s2s_capsule_count: usize = 0;
        for (caps) |c| if (c.header.kind == .s2s_link) {
            s2s_capsule_count = std.math.add(usize, s2s_capsule_count, 1) catch {
                self.abandonInheritedSessionState(caps, arena_fd, "secured-link count overflow");
                return error.InvalidInheritedHandoff;
            };
        };
        var adopted_s2s_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer adopted_s2s_ids.deinit(self.allocator);
        adopted_s2s_ids.ensureTotalCapacity(self.allocator, s2s_capsule_count) catch {
            self.abandonInheritedSessionState(caps, arena_fd, "could not reserve secured-link publication registry");
            return error.InvalidInheritedHandoff;
        };

        var sessions_replacement = sessions_mod.SessionStore.initWithConfig(self.allocator, self.sessions.cfg);
        defer sessions_replacement.deinit();
        var monitor_replacement = monitor.MonitorStore.init(self.allocator, self.monitor.max_monitor);
        defer monitor_replacement.deinit();
        var silence_replacement = silence.Store.initWithParams(self.allocator, self.silence.params);
        defer silence_replacement.deinit();

        for (self.reactors, staged_client_tables) |*reactor, *replacement|
            std.mem.swap(ClientTable, &reactor.clients, replacement);
        std.mem.swap(sessions_mod.SessionStore, &self.sessions, &sessions_replacement);
        std.mem.swap(monitor.MonitorStore, &self.monitor, &monitor_replacement);
        std.mem.swap(silence.Store, &self.silence, &silence_replacement);
        const prior_ticket_key = self.tls_ticket_key;
        const prior_previous_ticket_key = self.tls_previous_ticket_key;
        if (ticket_key_replacement) |replacement| {
            self.tls_ticket_key = replacement.current;
            self.tls_previous_ticket_key = replacement.previous;
        }
        errdefer {
            self.tls_ticket_key = prior_ticket_key;
            self.tls_previous_ticket_key = prior_previous_ticket_key;
        }
        lockSpin(&self.mesh_clock_lock);
        const prior_mesh_clock = self.mesh_clock;
        const prior_migration_offer_epoch = self.migration_offer_epoch;
        const prior_msg_seq = self.msg_seq;
        const prior_stage_retry_pending = self.session_replica_stage_retry_pending;
        const prior_stage_retry_cursor = self.session_replica_stage_retry_cursor;
        const prior_stage_retry_pass_failed = self.session_replica_stage_retry_pass_failed;
        self.mesh_clock_lock.unlock();
        errdefer {
            lockSpin(&self.mesh_clock_lock);
            self.mesh_clock = prior_mesh_clock;
            self.migration_offer_epoch = prior_migration_offer_epoch;
            self.mesh_clock_lock.unlock();
            self.msg_seq = prior_msg_seq;
            self.session_replica_stage_retry_pending = prior_stage_retry_pending;
            self.session_replica_stage_retry_cursor = prior_stage_retry_cursor;
            self.session_replica_stage_retry_pass_failed = prior_stage_retry_pass_failed;
        }

        world_replacement.swapWorldInto(&self.world);
        var property_entities_restored: usize = 0;
        var property_clocks_restored: usize = 0;

        const replica_checkpoint_restored = replica_replacement != null;
        if (replica_replacement) |*replacement|
            std.mem.swap(session_replica_v2.Store, &self.session_replica_store, replacement);
        if (pending_replacement != null)
            std.mem.swap(?session_migrate.PendingMigrations, &self.pending_migrations, &pending_replacement);
        errdefer {
            if (pending_replacement != null)
                std.mem.swap(?session_migrate.PendingMigrations, &self.pending_migrations, &pending_replacement);
            if (replica_replacement) |*replacement|
                std.mem.swap(session_replica_v2.Store, &self.session_replica_store, replacement);
        }

        const prior_replica_store_generation = self.session_replica_store_generation;
        if (replica_checkpoint_restored) {
            self.session_replica_store_generation +%= 1;
        }
        errdefer self.session_replica_store_generation = prior_replica_store_generation;
        var adoption_stage: []const u8 = "TLS sidecars";
        // Registered after every candidate authority swap so it executes first
        // on error. This destructor releases only candidate-owned heap state;
        // the exact inherited-fd manifest remains the one close authority.
        errdefer {
            for (self.reactors) |*reactor| self.deinitInheritedCandidateClients(&reactor.clients);
            current_reactor = &self.reactors[0];
            for (self.reactors, staged_client_tables) |*reactor, *replacement|
                std.mem.swap(ClientTable, &reactor.clients, replacement);
            std.mem.swap(sessions_mod.SessionStore, &self.sessions, &sessions_replacement);
            std.mem.swap(monitor.MonitorStore, &self.monitor, &monitor_replacement);
            std.mem.swap(silence.Store, &self.silence, &silence_replacement);
            var reason_buf: [160]u8 = undefined;
            const reason = std.fmt.bufPrint(&reason_buf, "late inherited-state transaction failed during {s}", .{adoption_stage}) catch
                "late inherited-state transaction failed";
            self.abandonInheritedSessionState(caps, arena_fd, reason);
        }
        const replica_objects_restored = self.session_replica_store.entryCount() +
            self.session_replica_store.attachmentLeaseCount() +
            self.session_replica_store.tombstoneCount() + self.session_replica_store.quarantineCount();

        var migrations_staged: usize = 0;
        var tombstones_staged: usize = 0;
        if (pending_checkpoint != null) {
            migrations_staged = self.pending_migrations.?.count();
            tombstones_staged = self.pending_migrations.?.consumedCount();
            _ = self.prunePendingReplicasWithoutStoreAuthority(replica_now_wall);
            migrations_staged = self.pending_migrations.?.count();
        }

        // Pass 1: index the carried TLS engine states by socket fd (the join key
        // back to the matching client snapshot). The relation preflight already
        // proved every secured client has exactly one valid match; any decode or
        // join failure below rejects the whole successor before serving.
        var tls_snaps: std.ArrayList(tls_snapshot.Snapshot) = .empty;
        defer tls_snaps.deinit(self.allocator);
        for (caps) |c| {
            if (c.header.kind != .tls_session) continue;
            // Rolling-compatible like `.s2s_link`: a pre-bump predecessor stamps a
            // lower version (the flag-widened-but-still-v1 TLS blob), so negotiate
            // the header and decode per version rather than pinning current —
            // pinning would `Truncated → whole-handoff abort` (netsplit) on the
            // first USR2 from such a predecessor.
            const descriptor = helix_capsule.descriptor(.tls_session);
            const negotiated = helix_capsule.negotiate(descriptor, c.header) catch {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — incompatible TLS-session capsule\n", .{});
                return error.InvalidInheritedHandoff;
            };
            if (negotiated != c.header.version or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — noncanonical TLS-session capsule\n", .{});
                return error.InvalidInheritedHandoff;
            }
            const ts = tls_snapshot.decode(c.fields[0].bytes, c.header.version) catch |e| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — invalid TLS-session checkpoint ({s})\n", .{@errorName(e)});
                return error.InvalidInheritedHandoff;
            };
            if (ts.fd < 0) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            for (tls_snaps.items) |prior| {
                if (prior.fd == ts.fd) {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — duplicate TLS sidecar for fd {d}\n", .{ts.fd});
                    return error.InvalidInheritedHandoff;
                }
            }
            tls_snaps.append(self.allocator, ts) catch {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            };
        }

        // Pass 1b: index the carried WebSocket adapter markers by socket fd, the
        // same join key. A wss client is joined to BOTH its TLS state and this
        // marker; the marker tells the successor to rebuild the WS framing layer.
        adoption_stage = "WebSocket sidecars";
        var ws_snaps: std.ArrayList(ws_snapshot.Snapshot) = .empty;
        defer ws_snaps.deinit(self.allocator);
        for (caps) |c| {
            if (c.header.kind != .ws_session) continue;
            // Exact current adoption: the selected subprotocol controls whether
            // binary application frames may reach Cadence. A v1/v2 sidecar lacks
            // that authority and is accepted only by explicit cold migration,
            // never by live Helix adoption.
            const descriptor = helix_capsule.descriptor(.ws_session);
            if (c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != descriptor.min_supported or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — noncanonical WebSocket-session capsule\n", .{});
                return error.InvalidInheritedHandoff;
            }
            const wss = ws_snapshot.decodeCurrent(c.fields[0].bytes) catch |e| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — invalid WebSocket-session checkpoint ({s})\n", .{@errorName(e)});
                return error.InvalidInheritedHandoff;
            };
            if (wss.fd < 0 or !wss.phase_open) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            for (ws_snaps.items) |prior| {
                if (prior.fd == wss.fd) {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — duplicate WebSocket sidecar for fd {d}\n", .{wss.fd});
                    return error.InvalidInheritedHandoff;
                }
            }
            ws_snaps.append(self.allocator, wss) catch {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            };
        }

        // Pass 2: adopt the carried clients.
        adoption_stage = "physical client adoption";
        var adopted: usize = 0;
        var adopted_tls: usize = 0;
        var adopted_ws: usize = 0;
        var matched_tls: usize = 0;
        var matched_ws: usize = 0;
        for (caps) |c| {
            if (c.header.kind != .clients) continue;
            if (c.fields.len != 1 or c.fields[0].ordinal != 1) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            const snap = session_snapshot.decodeCurrent(c.fields[0].bytes) catch {
                // Descriptor ownership remains centralized in the trusted
                // manifest even when the body is malformed; the transaction's
                // abandonment path closes it exactly once.
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            };
            if (snap.fd < 0) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            var tls_state: ?tls_snapshot.Snapshot = null;
            for (tls_snaps.items) |ts| {
                if (ts.fd == snap.fd) {
                    tls_state = ts;
                    break;
                }
            }
            if (snap.was_secured != (tls_state != null)) {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — client/TLS sidecar join mismatch for fd {d}\n", .{snap.fd});
                return error.InvalidInheritedHandoff;
            }
            if (tls_state != null) matched_tls += 1;
            var ws_state: ?ws_snapshot.Snapshot = null;
            for (ws_snaps.items) |wss| {
                if (wss.fd == snap.fd) {
                    ws_state = wss;
                    break;
                }
            }
            if (snap.was_websocket != (ws_state != null)) {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — client/WebSocket sidecar join mismatch for fd {d}\n", .{snap.fd});
                return error.InvalidInheritedHandoff;
            }
            if (ws_state != null) matched_ws += 1;
            // Multi-shard: re-pin the client to its fd-derived shard by binding
            // this (boot, pre-reactor-loop) thread to the target reactor for the
            // adoption — every rx() inside adoptInheritedClient (slot alloc,
            // recv arm on the shard's ring) then lands on that shard. The shard
            // choice is deterministic in the fd; client ids never survive the
            // swap (fd is the join key), so any consistent spread is correct.
            current_reactor = &self.reactors[self.adoptShardForFd(snap.fd)];
            const ok = self.adoptInheritedClient(snap, tls_state, ws_state, false);
            current_reactor = &self.reactors[0];
            if (ok) {
                const adopted_flat = self.adoptedClientIdByFd(snap.fd) orelse {
                    world_replacement.swapWorldInto(&self.world);
                    return error.InvalidInheritedHandoff;
                };
                _ = adopted_flat;
                adopted += 1;
                if (tls_state != null) adopted_tls += 1;
                if (ws_state != null) adopted_ws += 1;
            }
        }
        if (adopted != client_capsule_count) {
            world_replacement.swapWorldInto(&self.world);
            srvLog("onyx-server: UPGRADE resume fatal — adopted only {d} of {d} exact client snapshot(s)\n", .{ adopted, client_capsule_count });
            return error.InvalidInheritedHandoff;
        }
        if (matched_tls != tls_snaps.items.len or matched_ws != ws_snaps.items.len) {
            world_replacement.swapWorldInto(&self.world);
            srvLog("onyx-server: UPGRADE resume fatal — orphan TLS/WebSocket sidecar(s) remain after exact client join\n", .{});
            return error.InvalidInheritedHandoff;
        }
        if (comptime builtin.os.tag == .windows) {
            self.validateInheritedAdmissionRelation(
                if (throttle_replacement) |*value| value else null,
                if (mesh_clones_replacement) |*value| value else null,
            ) catch |e| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — Windows admission/client relation failed ({s})\n", .{@errorName(e)});
                return error.InvalidInheritedHandoff;
            };
        }
        adoption_stage = "World client relations";
        const adopted_world_resolver = self.helixWorldRelationResolver();
        world_replacement.validateAdoptedMembersResolved(
            &self.world,
            adopted_world_resolver,
        ) catch |e| {
            // Client adoption may fail only for resource/runtime reasons after
            // the pre-publication projection proved the wire images agree. Put
            // the displaced boot World back for deterministic destruction, then
            // make startup exit; continuing would expose adopted sockets beside
            // a partial membership graph.
            world_replacement.swapWorldInto(&self.world);
            srvLog("onyx-server: UPGRADE resume fatal — adopted World membership validation failed ({s})\n", .{@errorName(e)});
            return error.InvalidInheritedHandoff;
        };
        world_replacement.applyInvitesResolved(
            &self.world,
            adopted_world_resolver,
        ) catch |e| {
            // applyInvites preflights references but allocation can still fail
            // after a prefix was installed. The whole replacement World is
            // discarded and startup exits; no partially resumed daemon starts.
            world_replacement.swapWorldInto(&self.world);
            srvLog("onyx-server: UPGRADE resume fatal — inherited invite publication failed ({s})\n", .{@errorName(e)});
            return error.InvalidInheritedHandoff;
        };
        // MONITOR's online index is derived from registered local occupancy and
        // is not part of the per-client watch-list capsule. Rebuild it silently
        // in the rollback-owned candidate before restoring watcher relations.
        // Primary World owners first preserve the authoritative display casing;
        // same-fold secondary attachments are idempotent in the second pass.
        adoption_stage = "MONITOR relations";
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, slot_index| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                if (!conn.session.registered() or conn.s2s != null or conn.s2s_secured != null) continue;
                const id = slotClientId(reactor, slot_index, slot.gen);
                const nick = self.world.nickOf(worldIdFromClient(id)) orelse continue;
                if (nick.len == 0 or std.mem.eql(u8, nick, "*")) continue;
                self.monitor.restoreOnline(nick) catch |e| {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — MONITOR online-index restore failed ({s})\n", .{@errorName(e)});
                    return error.InvalidInheritedHandoff;
                };
            }
        }
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                if (!conn.session.registered() or conn.s2s != null or conn.s2s_secured != null) continue;
                const nick = conn.session.displayName();
                if (nick.len == 0 or std.mem.eql(u8, nick, "*")) continue;
                self.monitor.restoreOnline(nick) catch |e| {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — MONITOR alias-index restore failed ({s})\n", .{@errorName(e)});
                    return error.InvalidInheritedHandoff;
                };
            }
        }
        // Pass 2b: restore the exact one-per-client MONITOR relation. Empty
        // lists are material rows too: requiring one fd-keyed capsule for every
        // adopted client distinguishes "empty" from "silently missing". Restore
        // is SILENT because the client already knows each target's online state.
        const monitor_fds = self.allocator.alloc(i32, client_capsule_count) catch {
            world_replacement.swapWorldInto(&self.world);
            return error.InvalidInheritedHandoff;
        };
        defer self.allocator.free(monitor_fds);
        var monitor_lists_restored: usize = 0;
        for (caps) |c| {
            if (c.header.kind != .monitor_list) continue;
            const descriptor = helix_capsule.descriptor(.monitor_list);
            if (c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != descriptor.min_supported or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — noncanonical current MONITOR capsule\n", .{});
                return error.InvalidInheritedHandoff;
            }
            var tgt_buf: [max_carried_monitor_targets][]const u8 = undefined;
            const mc = monitor_capsule.MonitorCapsule.decode(c.fields[0].bytes, &tgt_buf) catch |e| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — invalid current MONITOR capsule ({s})\n", .{@errorName(e)});
                return error.InvalidInheritedHandoff;
            };
            if (mc.client_id > std.math.maxInt(i32)) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            const fd: i32 = @intCast(mc.client_id);
            if (fd < 0) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            for (monitor_fds[0..monitor_lists_restored]) |prior_fd| {
                if (prior_fd == fd) {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — duplicate MONITOR sidecar for fd {d}\n", .{fd});
                    return error.InvalidInheritedHandoff;
                }
            }
            if (monitor_lists_restored == monitor_fds.len) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            const watcher = self.adoptedClientIdByFd(fd) orelse {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — orphan MONITOR sidecar for fd {d}\n", .{fd});
                return error.InvalidInheritedHandoff;
            };
            for (mc.targets) |t| {
                const before_count = self.monitor.monitorCount(watcher);
                self.monitor.restoreTarget(watcher, t) catch |e| {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — MONITOR restore failed for fd {d} ({s})\n", .{ fd, @errorName(e) });
                    return error.InvalidInheritedHandoff;
                };
                // MonitorStore normalizes IRC casemapping before insertion and
                // intentionally treats duplicates as an idempotent no-op. The
                // predecessor image is a set, so a no-op here proves the wire
                // row contained a duplicate (including a case-fold alias).
                if (self.monitor.monitorCount(watcher) != before_count + 1) {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — duplicate MONITOR target for fd {d}\n", .{fd});
                    return error.InvalidInheritedHandoff;
                }
            }
            monitor_fds[monitor_lists_restored] = fd;
            monitor_lists_restored += 1;
        }
        if (monitor_lists_restored != client_capsule_count) {
            world_replacement.swapWorldInto(&self.world);
            srvLog("onyx-server: UPGRADE resume fatal — restored {d} of {d} exact MONITOR sidecar(s)\n", .{ monitor_lists_restored, client_capsule_count });
            return error.InvalidInheritedHandoff;
        }

        // Pass 2b (cont.): restore the exact one-per-client SILENCE relation.
        // Duplicate masks are invalid wire state: the predecessor Store is a
        // set, so accepting one would hide corruption or an ambiguous join.
        adoption_stage = "SILENCE relations";
        const silence_fds = self.allocator.alloc(i32, client_capsule_count) catch {
            world_replacement.swapWorldInto(&self.world);
            return error.InvalidInheritedHandoff;
        };
        defer self.allocator.free(silence_fds);
        var silence_lists_restored: usize = 0;
        for (caps) |c| {
            if (c.header.kind != .silence_list) continue;
            const descriptor = helix_capsule.descriptor(.silence_list);
            if (c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != descriptor.min_supported or
                c.header.max_supported != descriptor.max_supported or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — noncanonical current SILENCE capsule\n", .{});
                return error.InvalidInheritedHandoff;
            }
            var mask_buf: [max_carried_silence_masks][]const u8 = undefined;
            const sc = silence_capsule.SilenceCapsule.decode(c.fields[0].bytes, &mask_buf) catch |e| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — invalid current SILENCE capsule ({s})\n", .{@errorName(e)});
                return error.InvalidInheritedHandoff;
            };
            if (sc.client_id > std.math.maxInt(i32)) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            const fd: i32 = @intCast(sc.client_id);
            if (fd < 0) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            for (silence_fds[0..silence_lists_restored]) |prior_fd| {
                if (prior_fd == fd) {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — duplicate SILENCE sidecar for fd {d}\n", .{fd});
                    return error.InvalidInheritedHandoff;
                }
            }
            if (silence_lists_restored == silence_fds.len) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            const owner_conn = self.adoptedConnByFd(fd) orelse {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — orphan SILENCE sidecar for fd {d}\n", .{fd});
                return error.InvalidInheritedHandoff;
            };
            const owner = owner_conn.session.displayName();
            for (sc.masks) |m| {
                const added = self.silence.add(owner, m) catch |e| {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — SILENCE restore failed for fd {d} ({s})\n", .{ fd, @errorName(e) });
                    return error.InvalidInheritedHandoff;
                };
                if (!added) {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — duplicate SILENCE mask for fd {d}\n", .{fd});
                    return error.InvalidInheritedHandoff;
                }
            }
            silence_fds[silence_lists_restored] = fd;
            silence_lists_restored += 1;
        }
        if (silence_lists_restored != client_capsule_count) {
            world_replacement.swapWorldInto(&self.world);
            srvLog("onyx-server: UPGRADE resume fatal — restored {d} of {d} exact SILENCE sidecar(s)\n", .{ silence_lists_restored, client_capsule_count });
            return error.InvalidInheritedHandoff;
        }

        // Pass 2c: restore the account-level multi-session/bouncer registry
        // from the carried `.sessions` capsules (one per account). Runs AFTER
        // Pass 2 so an attached session can re-join its adopted connection by
        // inherited fd — the same join key the TLS/WS capsules use. An
        // undecodable capsule is FATAL to the whole handoff (a transactional
        // abort, not a silent skip); each account otherwise applies atomically
        // (all-or-nothing), so a fault never leaves a torn subset of an
        // account's sessions.
        adoption_stage = "session and attachment relations";
        var session_accounts: usize = 0;
        var sessions_restored: usize = 0;
        var detached_session_seq: u64 = 0;
        const attachment_client_count = attachment_delivery_replacement.attachmentCount();
        const attachment_client_buf = self.allocator.alloc(
            attachment_delivery_spool.ClientId,
            attachment_client_count,
        ) catch {
            world_replacement.swapWorldInto(&self.world);
            return error.InvalidInheritedHandoff;
        };
        defer self.allocator.free(attachment_client_buf);
        const attachment_clients = attachment_delivery_replacement.collectAttachmentClients(
            attachment_client_buf,
        );
        if (attachment_clients.len != attachment_client_count) {
            world_replacement.swapWorldInto(&self.world);
            return error.InvalidInheritedHandoff;
        }
        var attachment_remaps: std.ArrayList(attachment_delivery_spool.AttachmentRemap) = .empty;
        defer attachment_remaps.deinit(self.allocator);
        attachment_remaps.ensureTotalCapacity(self.allocator, attachment_client_count) catch {
            world_replacement.swapWorldInto(&self.world);
            return error.InvalidInheritedHandoff;
        };
        for (caps) |c| {
            if (c.header.kind != .sessions) continue;
            // Rolling-compatible: the descriptor advertises `min_supported = 1`, so
            // negotiate + decode per version rather than pin current (tightening
            // instead would refuse the currently-deployed predecessor's capsule —
            // sealed `min_supported = 1` — and netsplit the deploy). The current
            // version uses the strict `decodeCurrent` (current state stays
            // fail-closed); a genuine legacy version uses the version-aware `decode`.
            const descriptor = helix_capsule.descriptor(.sessions);
            const negotiated = helix_capsule.negotiate(descriptor, c.header) catch {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — incompatible session-registry capsule\n", .{});
                return error.InvalidInheritedHandoff;
            };
            if (negotiated != c.header.version or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — noncanonical session-registry capsule\n", .{});
                return error.InvalidInheritedHandoff;
            }
            const count = session_capsule.peekSessionCount(c.fields[0].bytes) catch |e| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — invalid session-registry header ({s})\n", .{@errorName(e)});
                return error.InvalidInheritedHandoff;
            };
            if (count == 0) {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            }
            const entries = self.allocator.alloc(session_capsule.SessionEntry, count) catch {
                world_replacement.swapWorldInto(&self.world);
                return error.InvalidInheritedHandoff;
            };
            defer self.allocator.free(entries);
            const cap = (if (c.header.version == descriptor.current_version)
                session_capsule.SessionCapsule.decodeCurrent(c.fields[0].bytes, entries)
            else
                session_capsule.SessionCapsule.decode(c.fields[0].bytes, entries)) catch |e| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — invalid session-registry checkpoint ({s})\n", .{@errorName(e)});
                return error.InvalidInheritedHandoff;
            };
            const restored = self.adoptSessionRegistryAccount(
                cap,
                &detached_session_seq,
                attachment_clients,
                &attachment_remaps,
            );
            if (restored != cap.sessions.len) {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — restored only {d} of {d} exact session row(s) for {s}\n", .{ restored, cap.sessions.len, cap.account });
                return error.InvalidInheritedHandoff;
            }
            session_accounts += 1;
            sessions_restored += restored;
        }
        // Per-row capsule restore is O(1). Normalize portable authority once
        // across the complete candidate registry so a legacy mixed [true,false]
        // token group cannot lose renewal when its original issuer disappears.
        // The store stages its token set before mutation; OOM rejects the whole
        // handoff before any replacement authority is published.
        self.sessions.normalizePortableGroupsAfterRestore() catch |e| {
            world_replacement.swapWorldInto(&self.world);
            srvLog("onyx-server: UPGRADE resume fatal — could not normalize portable attachment groups ({s})\n", .{@errorName(e)});
            return error.InvalidInheritedHandoff;
        };
        // ADS1 stores predecessor physical client ids. HSSN is the canonical
        // relation from each old id to either its fd-adopted successor id or the
        // reserved synthetic id assigned to a detached ghost. Apply the complete
        // simultaneous mapping once; orphan, duplicate-source, or collision
        // conflicts reject startup before any of the five authorities publish.
        if (attachment_remaps.items.len != attachment_clients.len) {
            world_replacement.swapWorldInto(&self.world);
            srvLog(
                "onyx-server: UPGRADE resume fatal — mapped only {d} of {d} attachment-delivery owner(s)\n",
                .{ attachment_remaps.items.len, attachment_clients.len },
            );
            return error.InvalidInheritedHandoff;
        }
        _ = attachment_delivery_replacement.remapAttachments(attachment_remaps.items) catch |e| {
            world_replacement.swapWorldInto(&self.world);
            srvLog("onyx-server: UPGRADE resume fatal — attachment-delivery client remap failed ({s})\n", .{@errorName(e)});
            return error.InvalidInheritedHandoff;
        };

        // Pass 3: decode carried hand-dial hints now, but leave their CONNECT
        // SQEs staged. The first reactor turn must reserve SQ space for
        // accept/wake/timer and inherited client activation before any redial.
        // Config-managed [mesh].connect peers are likewise staged by runOnce.
        adoption_stage = "mesh redial staging";
        var redialed: usize = 0;
        var redial_replacement: std.ArrayListUnmanaged(posix.sockaddr.in6) = .empty;
        defer redial_replacement.deinit(self.allocator);
        for (caps) |c| {
            if (c.header.kind != .mesh_checkpoint) continue;
            // `.mesh_checkpoint` is a shared family. MRED rows are identified by
            // their current discriminator; other magic-prefixed authorities were
            // already consumed above. Once identified, the row and its outer
            // wrapper are exact — trailing bytes, a zero port, or an evolvable
            // wrapper cannot silently turn a live hand-dial into a dropped peer.
            //
            // L9 robustness note: this `continue` is NOT a silent-loss path for an
            // UNKNOWN discriminator. `handoff_relations.validateCurrent` (run at
            // adoptInheritedSessions entry, before any adoption) already rejected
            // the whole handoff fail-closed with `UnknownMeshCheckpoint` for any
            // mesh_checkpoint row whose magic matches none of the known families
            // (handoff_relations.zig — the `!mesh_redial.isCurrent` arm). So by
            // here every row is a KNOWN discriminator; this only skips the ones
            // already consumed by their own earlier passes. A future sealer-side
            // magic added WITHOUT teaching validateCurrent about it is the single
            // maintenance point that keeps this guarantee — keep that arm in sync.
            if (c.fields.len != 1 or c.fields[0].ordinal != 1 or
                !mesh_redial.isCurrent(c.fields[0].bytes)) continue;
            const descriptor = helix_capsule.descriptor(.mesh_checkpoint);
            if (c.header.schema_id != descriptor.schema_id or
                c.header.version != descriptor.current_version or
                c.header.min_supported != descriptor.min_supported or
                c.header.max_supported != descriptor.max_supported)
            {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — noncanonical current mesh re-dial capsule\n", .{});
                return error.InvalidInheritedHandoff;
            }
            const peer = mesh_redial.decodeCurrent(c.fields[0].bytes) catch |e| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — invalid current mesh re-dial capsule ({s})\n", .{@errorName(e)});
                return error.InvalidInheritedHandoff;
            };
            const addr = posix.sockaddr.in6{
                .port = std.mem.nativeToBig(u16, peer.port),
                .flowinfo = 0,
                .addr = peer.addr,
                .scope_id = 0,
            };
            redial_replacement.append(self.allocator, addr) catch |e| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — could not stage exact mesh re-dial ({s})\n", .{@errorName(e)});
                return error.InvalidInheritedHandoff;
            };
            redialed += 1;
        }

        // Pass 4: re-attach PRESERVED secured mesh links (zero-drop). Their socket
        // fd survived execve; rebuild the SecuredLink established from the capsule
        // (crypto + inner framing) and RESYNC with the peer to refill the roster.
        // These are disjoint from the re-dial hints above (a preserved link never
        // sealed one), so there is no double-connect.
        adoption_stage = "secured mesh link adoption";
        var s2s_resumed: usize = 0;
        for (caps) |c| {
            if (c.header.kind != .s2s_link) continue;
            const descriptor = helix_capsule.descriptor(.s2s_link);
            const negotiated = helix_capsule.negotiate(descriptor, c.header) catch {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — incompatible secured-mesh capsule\n", .{});
                return error.InvalidInheritedHandoff;
            };
            if (negotiated != c.header.version or
                c.fields.len != 1 or c.fields[0].ordinal != 1)
            {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — noncanonical secured-mesh capsule\n", .{});
                return error.InvalidInheritedHandoff;
            }
            const snap = s2s_snapshot.decode(c.fields[0].bytes, c.header.version) catch |e| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — secured-mesh decode failed ({s})\n", .{@errorName(e)});
                return error.InvalidInheritedHandoff;
            };
            if (snap.fd < 0) {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — secured-mesh fd {d} could not be adopted exactly\n", .{snap.fd});
                return error.InvalidInheritedHandoff;
            }
            const adopted_id = self.adoptInheritedS2sLink(snap, false) orelse {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — secured-mesh fd {d} could not be adopted exactly\n", .{snap.fd});
                return error.InvalidInheritedHandoff;
            };
            adopted_s2s_ids.appendAssumeCapacity(adopted_id);
            s2s_resumed += 1;
        }

        // Reconcile the restored signed Store into the complete rollback-owned
        // candidate graph before descriptor ownership or any derived output can
        // publish. Silent mode still applies World/profile/Pending/route state,
        // but drains candidate transition queues and suppresses client/history/
        // activity emissions. Any fallible or semantically invalid projection
        // rejects the entire handoff.
        adoption_stage = "session replica projection";
        if (!self.reprojectLiveSessionReplicasV2(.helix_silent) or
            self.sessions.dirtyReplicaRowCount() != 0 or
            self.sessions.dirtyReplicaProjectionRowCount() != 0 or
            self.sessions.dirtyLocalProjectionRowCount() != 0 or
            self.session_replica_stage_retry_pending)
        {
            world_replacement.swapWorldInto(&self.world);
            srvLog("onyx-server: UPGRADE resume fatal — inherited session-replica projection was incomplete\n", .{});
            return error.InvalidInheritedHandoff;
        }

        adoption_stage = "native pre-commit preparation";
        var windows_active_media_stage: ?WindowsActiveMediaStage = null;
        defer if (windows_active_media_stage) |*stage| stage.deinit();
        if (comptime builtin.os.tag == .windows) {
            self.validateWindowsActiveWebTransportAcceptedJoin() catch |err| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — active WebTransport accepted-socket join failed ({s})\n", .{@errorName(err)});
                return error.InvalidInheritedHandoff;
            };
            if (self.windows_active_media_candidate) |candidate| {
                windows_active_media_stage = WindowsActiveMediaStage.prepare(self, candidate) catch |err| {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — active media graph join failed ({s})\n", .{@errorName(err)});
                    return error.InvalidInheritedHandoff;
                };
            }
        }
        var native_bot_stage: ?NativeBotStage = null;
        defer if (native_bot_stage) |*stage| stage.deinit();
        if (comptime builtin.os.tag == .openbsd or builtin.os.tag == .windows) {
            native_bot_stage = self.stageNativeBotGrants(bot_grant_checkpoint) catch |err| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — native bot staging failed ({s})\n", .{@errorName(err)});
                return error.InvalidInheritedHandoff;
            };
            if (self.account_services) |svc| {
                // A candidate may read the serving predecessor's WAL, but must
                // not recover, compact, append or repair it before COMMIT.
                if (comptime @hasDecl(@TypeOf(svc.store.*), "isReadOnly")) {
                    if (!svc.store.isReadOnly()) {
                        world_replacement.swapWorldInto(&self.world);
                        srvLog("onyx-server: UPGRADE resume fatal — native candidate store is mutable\n", .{});
                        return error.InvalidInheritedHandoff;
                    }
                    history_durable.replaceAll(HistoryStore, svc.store, &history_replacement) catch |err| {
                        world_replacement.swapWorldInto(&self.world);
                        srvLog("onyx-server: UPGRADE resume fatal — native durable history validation failed ({s})\n", .{@errorName(err)});
                        return error.InvalidInheritedHandoff;
                    };
                    svc.store.preparePromotion() catch |err| {
                        world_replacement.swapWorldInto(&self.world);
                        srvLog("onyx-server: UPGRADE resume fatal — native store promotion preparation failed ({s})\n", .{@errorName(err)});
                        return error.InvalidInheritedHandoff;
                    };
                    // After validation the reserved writer is the sole WAL
                    // owner. Close the replay handle before READY so the
                    // post-COMMIT authority swap performs no fallible I/O.
                    svc.store.releaseReadHandleForPreparedPromotion() catch |err| {
                        world_replacement.swapWorldInto(&self.world);
                        srvLog("onyx-server: UPGRADE resume fatal — native WAL replay release failed ({s})\n", .{@errorName(err)});
                        return error.InvalidInheritedHandoff;
                    };
                } else {
                    world_replacement.swapWorldInto(&self.world);
                    return error.InvalidInheritedHandoff;
                }
            }
            const barrier = self.config.native_adopt_barrier.?;
            if (comptime builtin.os.tag == .windows) {
                const claim = barrier.claimInertStateSocket orelse {
                    world_replacement.swapWorldInto(&self.world);
                    return error.InvalidInheritedHandoff;
                };
                for (self.config.inherited_state_fds) |fd| claim(barrier.ctx, fd) catch |err| {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — Windows socket custody claim failed ({s})\n", .{@errorName(err)});
                    return error.InvalidInheritedHandoff;
                };
                if (self.config.mail_sender) |owner| owner.requireStagedWalCut() catch |err| {
                    world_replacement.swapWorldInto(&self.world);
                    srvLog("onyx-server: UPGRADE resume fatal — Windows mail WAL custody changed before COMMIT ({s})\n", .{@errorName(err)});
                    return error.InvalidInheritedHandoff;
                };
            }
            barrier.readyAndAwaitCommit(barrier.ctx) catch |err| {
                world_replacement.swapWorldInto(&self.world);
                srvLog("onyx-server: UPGRADE resume fatal — native commit barrier failed ({s})\n", .{@errorName(err)});
                return error.InvalidInheritedHandoff;
            };
            // The authenticated control owner returned only after COMMIT.
            // Promotion and all remaining authority swaps cannot fail.
            if (comptime builtin.os.tag == .windows) {
                if (self.config.mail_sender) |owner| owner.releaseStagedWalCut();
            }
            if (self.account_services) |svc| {
                if (comptime @hasDecl(@TypeOf(svc.store.*), "promotePrepared")) svc.store.promotePrepared();
            }
        }

        // Single no-fail commit edge. Every decoder, allocator, relation join,
        // client/session restore, redial append, and preserved-link rebuild has
        // completed. The boot stores displaced by swaps remain owned by the
        // replacement values and are destroyed by the existing defers.
        if (comptime builtin.os.tag == .windows) {
            if (tls_replay_replacement) |*replacement| {
                // TLS configs borrow this exact address. Install the fully
                // decoded ring in place only after authenticated COMMIT.
                replacement.install(&self.tls_replay_guard);
            }
        }
        std.mem.swap(
            event_spine_replay_guard.Guard,
            &self.event_spine_replay_guard,
            &event_replay_replacement,
        );
        std.mem.swap(
            e2ee_group_mesh_authority.Authority,
            &self.e2ee_group_mesh_authority,
            &e2ee_group_replay_replacement,
        );
        if (comptime builtin.os.tag == .windows) {
            if (login_throttle_replacement) |*replacement|
                std.mem.swap(svc_login_throttle.Throttle, &self.login_throttle, replacement)
            else
                unreachable;
            if (nick_delay_replacement) |*replacement|
                std.mem.swap(nick_delay_mod.NickDelay, &self.nick_delay, replacement)
            else
                unreachable;
            if (temp_mode_replacement) |*replacement|
                std.mem.swap(svc_tempmode.TempModeQueue, &self.temp_modes, replacement)
            else
                unreachable;
            if (raid_shield_replacement) |*replacement|
                std.mem.swap(raid_shield.Shield, &self.raid_shield, replacement)
            else
                unreachable;
            if (slowmode_replacement) |*replacement|
                std.mem.swap(slowmode_checkpoint.Map, &self.slowmode_last, replacement)
            else
                unreachable;
            if (metadata_replacement) |*replacement|
                std.mem.swap(metadata_store.DefaultStore, &self.metadata, replacement)
            else
                unreachable;
            if (mlock_replacement) |*replacement|
                std.mem.swap(mlock_checkpoint.Map, &self.mlocks, replacement)
            else
                unreachable;
            self.draining = drain_replacement orelse unreachable;
            if (chanstats_replacement) |*replacement| {
                std.mem.swap(chanstats_mod.ChanStats, &self.chanstats, &replacement.stats);
                std.mem.swap(i64, &self.chanstats_last_write_ms, &replacement.last_write_ms);
                std.mem.swap(i64, &self.chanstats_prune_ready_ms, &replacement.prune_ready_ms);
                self.inherited_chanstats_restored = true;
            }
            if (access_replacement) |*replacement|
                std.mem.swap(ircx_access_store.AccessStore, &self.access, replacement)
            else
                unreachable;
            if (saccess_replacement) |*replacement|
                std.mem.swap(ircx_saccess.ServerAccessStore, &self.saccess, replacement)
            else
                unreachable;
            if (akick_replacement) |*replacement|
                std.mem.swap(svc_akick.AkickStore, &self.chan_akick, replacement)
            else
                unreachable;
            if (ward_replacement) |*replacement|
                std.mem.swap(warden.Registry, &self.warden, replacement)
            else
                unreachable;
            if (policy_replacement) |*replacement| {
                std.mem.swap(?PolicyUndo, &self.policy_undo, &policy_undo_replacement);
                self.policy_gen_ward = replacement.generations.ward;
                self.policy_gen_filter = replacement.generations.filter;
                self.policy_gen_class = replacement.generations.class;
                self.policy_gen_ban = replacement.generations.ban;
                self.proof_policy_version = replacement.generations.proof;
            } else unreachable;
            if (operator_replacement) |restored| {
                self.challenge_method = restored.method;
                self.challenge_question = restored.question;
                self.challenge_question_len = restored.question_len;
                self.challenge_answer = restored.answer;
                self.challenge_answer_len = restored.answer_len;
                self.challenge_issued = restored.issued;
                self.two_person_pending = if (restored.pending) |pending| blk: {
                    var next = TwoPersonPending{
                        .kind = switch (pending.kind) {
                            .die => .die,
                            .restart => .restart,
                            .ward_add => .ward_add,
                            .ward_del => .ward_del,
                        },
                        .at_ms = pending.at_ms,
                    };
                    @memcpy(next.target[0..pending.target_len], pending.target[0..pending.target_len]);
                    next.target_len = @intCast(pending.target_len);
                    @memcpy(next.identity[0..pending.identity_len], pending.identity[0..pending.identity_len]);
                    next.identity_len = @intCast(pending.identity_len);
                    break :blk next;
                } else null;
            } else unreachable;
            if (account_flow_replacement) |*replacement| replacement.commit() else unreachable;
            if (user_settings_replacement) |*replacement| replacement.commit() else unreachable;
            if (memo_forward_replacement) |*replacement|
                std.mem.swap(svc_memo_forward.MemoForwardStore, &self.memo_forward, replacement)
            else
                unreachable;
            if (memo_ignore_replacement) |*replacement|
                std.mem.swap(svc_memo_ignore.MemoIgnoreList, &self.memo_ignore, replacement)
            else
                unreachable;
            if (memo_inbox_replacement) |*replacement| {
                std.mem.swap(memo_mod.MemoBox, &self.memo, &replacement.box);
                self.memo_durable_dirty = replacement.dirty;
            } else unreachable;
            if (first_hold_replacement) |*replacement|
                std.mem.swap(first_hold.Table, &self.first_holds, replacement)
            else
                unreachable;
            if (tls_material_replacement) |*replacement| {
                const state = replacement.release();
                std.debug.assert(self.reload_tls == null and self.reload_tls12 == null and
                    self.reload_tls_prev == null and self.reload_tls12_prev == null);
                self.reload_tls = state.default;
                self.reload_tls12 = state.generated_tls12;
                self.config.tls_cert_chain = state.default.cert_chain;
                self.config.tls_signing_key = state.default.signing_key;
                self.config.tls_ecdsa_signing_key = state.default.ecdsa_p256_signing_key;
                self.config.tls_rsa_signing_key = state.default.rsa_signing_key;
                switch (state.tls12_mode) {
                    .disabled => {
                        self.config.tls12_cert_chain = &.{};
                        self.config.tls12_signing_key = null;
                    },
                    .shared_default => {
                        self.config.tls12_cert_chain = state.default.cert_chain;
                        self.config.tls12_signing_key = state.default.ecdsa_p256_signing_key;
                    },
                    .generated => {
                        self.config.tls12_cert_chain = state.generated_tls12.?.cert_chain;
                        self.config.tls12_signing_key = state.generated_tls12.?.key;
                    },
                }
                self.acme_reload_requested.store(state.reload_pending, .release);
                self.acme_reload_retry_after_ms = state.reload_retry_after_ms;
            }
            if (wasm_replacement) |*replacement| {
                var prior = self.wasm;
                self.wasm = replacement.release();
                prior.deinit();
            }
            if (self.ocsp_worker != null) {
                const state = if (ocsp_state_replacement) |*replacement| replacement.release() else unreachable;
                self.ocsp_staple_pending.store(state.pending, .release);
                self.ocsp_staple_rejected.store(state.rejected, .release);
                self.ocsp_staple_incoming = state.incoming;
                self.ocsp_staple_owned = state.current;
                self.ocsp_staple_prev = state.previous;
                self.config.tls_ocsp_staple = if (state.active) state.current else null;
                self.ocsp_staple_valid_until_unix = ocsp_restored_valid_until_unix;
                self.ocsp_staple_validated_at_unix = std.math.minInt(i64);
            }
            if (resv_replacement) |*replacement|
                std.mem.swap(svc_resv.ChannelResv, &self.chan_resv, replacement)
            else
                unreachable;
            if (jupe_replacement) |*replacement|
                std.mem.swap(svc_jupe.JupeStore, &self.server_jupe, replacement)
            else
                unreachable;
            if (gag_replacement) |*replacement|
                std.mem.swap(gag_set.GagSet, &self.gags, replacement)
            else
                unreachable;
            if (shun_replacement) |*replacement|
                std.mem.swap(shun_mod.ShunList, &self.shuns, replacement)
            else
                unreachable;
            if (account_abuse_replacement) |*replacement|
                std.mem.swap(account_abuse_mod.AccountAbuse, &self.account_abuse, replacement)
            else
                unreachable;
            if (content_filter_replacement) |*replacement|
                std.mem.swap(content_filter_mod.ContentFilter, &self.content_filter, replacement)
            else
                unreachable;
            if (reputation_replacement) |*replacement|
                std.mem.swap(ip_reputation_mod.IpReputation, &self.reputation, replacement)
            else
                unreachable;
            if (spamtrap_replacement) |*replacement| {
                lockSpin(&self.spamtrap_mu);
                std.mem.swap(spamtrap_mod.DefaultSpamtrap, &self.spamtrap, replacement);
                self.spamtrap_active.store(self.spamtrap.trapNickCount() + self.spamtrap.trapChannelCount() > 0, .release);
                self.spamtrap_mu.unlock();
            } else unreachable;
            if (throttle_replacement) |*replacement| {
                if (self.conn_throttle) |*live|
                    std.mem.swap(clone_detect_mod.CloneDetector, live, replacement)
                else
                    unreachable;
            }
            if (mesh_clones_replacement) |*replacement|
                std.mem.swap(mesh_clones_mod.MeshClones, &self.mesh_clones, replacement);
        }
        self.webhook_store.publishUpgradeReplacement(&webhook_replacement);
        self.inherited_webhook_store_restored = true;
        // DPROP1/PRPC and their causal boundary publish together only here.
        // Both candidates are fully built and checked; these swaps/assignments
        // allocate, persist, notify, gossip, and append transparency nowhere.
        if (comptime builtin.is_test) {
            if (durable_hot_plan != .inactive) {
                if (test_dprop_commit_fail_index) |fail_index| {
                    const alloc_index = test_dprop_commit_alloc_index orelse unreachable;
                    fail_index.* = alloc_index.*;
                }
            }
        }
        lockSpin(&self.mesh_clock_lock);
        if (property_replacement) |*replacement| {
            replacement.swapInto(
                &self.props,
                &self.channel_prop_clocks,
                &self.entity_prop_clocks,
            );
            property_entities_restored = self.props.entity_count;
            property_clocks_restored = self.channel_prop_clocks.count() + self.entity_prop_clocks.count();
        }
        if (staged_mesh_clock.last_stamp > self.mesh_clock.last_stamp)
            self.mesh_clock = staged_mesh_clock;
        self.migration_offer_epoch = @max(
            self.migration_offer_epoch,
            staged_migration_offer_epoch,
        );
        self.mesh_clock_lock.unlock();
        std.mem.swap(HistoryStore, &self.history, &history_replacement);
        std.mem.swap(search_index_mod.SearchIndex, &self.search_index, &search_replacement);
        // Identical durable history is a no-op. Divergent carried state still
        // needs this legacy fallible snapshot (including V2/edit/redaction state);
        // its publication has not yet been converted to a prepared transaction.
        if (comptime builtin.os.tag == .linux) self.snapshotDurableHistory();
        self.event_history.publishCheckpoint(&event_history_replacement);
        std.mem.swap(
            relay_v2_replay_guard.Guard,
            &self.relay_v2_replay_guard,
            &relay_replay_replacement,
        );
        std.mem.swap(
            relay_v2_outbox.Outbox,
            &self.relay_v2_outbox,
            &relay_outbox_replacement,
        );
        std.mem.swap(
            relay_v2_event_log.EventLog,
            &self.relay_v2_event_log,
            &relay_event_log_replacement,
        );
        std.mem.swap(
            attachment_delivery_spool.Spool,
            &self.attachment_delivery_spool,
            &attachment_delivery_replacement,
        );
        std.mem.swap(
            std.ArrayListUnmanaged(posix.sockaddr.in6),
            &self.inherited_mesh_redials,
            &redial_replacement,
        );
        self.inherited_mesh_redial_cursor = 0;
        self.inherited_event_history_restored = true;

        // Prime the carried cross-mesh oper-grant registry at the same no-fail
        // commit edge: fixed-capacity upserts of the pre-validated image cannot
        // fail, and the io loop (the only place a peer's post-RESYNC grant
        // re-mint is processed) has not started, so `applyMeshGrant` sees the
        // converged `had_oper_override` state and never announces a false +Y
        // transition. The checkpoint supersedes the best-effort grants file:
        // a stale file must never re-mint a revoked row past its tombstone.
        var oper_grants_restored: usize = 0;
        var oper_grants_dropped: usize = 0;
        if (oper_grant_checkpoint) |snap| {
            self.inherited_oper_grants_restored = true;
            self.grant_incarnation = @max(self.grant_incarnation, snap.mint_incarnation);
            var grant_it = snap.iterator();
            while (grant_it.next()) |g| {
                switch (self.oper_grants.upsert(g)) {
                    .inserted, .superseded => oper_grants_restored += 1,
                    // A full fixed-capacity registry silently drops a new-account
                    // grant (and its revocation tombstone, carried in the same
                    // record). Never swallow that — a lost cross-mesh grant means a
                    // stale +Y verdict after the swap.
                    .stale_ignored => oper_grants_dropped += 1,
                }
            }
        }
        if (oper_grants_restored != 0)
            srvLog("onyx-server: UPGRADE resume — primed {d} carried oper grant(s)\n", .{oper_grants_restored});
        if (oper_grants_dropped != 0)
            srvLog("onyx-server: UPGRADE resume — WARNING: dropped {d} carried oper grant(s) (registry capacity exhausted or superseded); a cross-mesh grant/revocation may be lost\n", .{oper_grants_dropped});

        // Prime scoped bot grants at the same no-fail edge. Slot inserts do not
        // allocate. Mirroring the account into the announcement registry can
        // allocate; a failure there still leaves the fixed table in place, so
        // the account stays gated. Nothing in this restore sets `is_oper`.
        var bot_grants_restored: usize = 0;
        var bot_grants_dropped: usize = 0;
        if (comptime builtin.os.tag == .openbsd or builtin.os.tag == .windows) {
            const stage = &native_bot_stage.?;
            std.mem.swap(bot_grant_snapshot.Table, &self.bot_grants, stage.table);
            std.mem.swap(bot_registry_mod.BotRegistry, &self.bot_registry, &stage.registry);
        } else if (bot_grant_checkpoint) |snap| {
            var bot_it = snap.botIterator();
            while (bot_it.next()) |account| {
                self.bot_grants.insertBot(account) catch {
                    bot_grants_dropped += 1;
                    continue;
                };
                self.bot_registry.register(account, .{}) catch {
                    bot_grants_dropped += 1;
                    continue;
                };
                bot_grants_restored += 1;
            }
            var grant_it = snap.grantIterator();
            while (grant_it.next()) |g| {
                self.bot_grants.upsert(g.account, g.kind, g.scope, g.expiry_ms, self.grantNowU64()) catch {
                    bot_grants_dropped += 1;
                    continue;
                };
                bot_grants_restored += 1;
            }
        }
        if (bot_grants_restored != 0)
            srvLog("onyx-server: UPGRADE resume — primed {d} carried bot grant record(s)\n", .{bot_grants_restored});
        if (bot_grants_dropped != 0)
            srvLog("onyx-server: UPGRADE resume — WARNING: dropped {d} carried bot grant record(s)\n", .{bot_grants_dropped});

        // Prime reply threads at the same no-fail edge. The table is already
        // allocated, so the copy does not allocate. A missing piece leaves the
        // cold-start rebuild (if any) untouched.
        if (thread_checkpoint) |snap| {
            const dropped = self.threads.replace(snap);
            const restored = self.threads.count();
            if (restored != 0)
                srvLog("onyx-server: UPGRADE resume — primed {d} carried thread(s)\n", .{restored});
            if (dropped != 0)
                srvLog("onyx-server: UPGRADE resume — WARNING: dropped {d} carried thread(s)\n", .{dropped});
        }

        // Prime deferred deliveries at the same no-fail edge. The table is
        // already allocated, so the copy does not allocate. A missing piece
        // leaves the table empty. Fired jobs stay fired.
        if (schedule_checkpoint) |snap| {
            const dropped = self.schedules.replace(snap);
            const restored = self.schedules.count();
            if (restored != 0)
                srvLog("onyx-server: UPGRADE resume — primed {d} carried schedule(s)\n", .{restored});
            if (dropped != 0)
                srvLog("onyx-server: UPGRADE resume — WARNING: dropped {d} carried schedule(s)\n", .{dropped});
        }

        // Transfer descriptor ownership immediately at the commit edge. Every
        // later action is retryable/best-effort derived work and must never
        // re-enter handoff abandonment.
        if (windows_active_media_stage) |*stage| stage.commit(self);
        self.windows_active_media_candidate = null;
        closeFd(arena_fd);
        self.config.resume_arena_fd = null;
        self.config.native_arena_bytes = null;
        self.config.native_adopt_barrier = null;
        self.windows_wt_active_candidate_snapshot = null;
        self.windows_wt_active_candidate_accepted = null;
        self.config.native_listener_manifest = &.{};
        // Every carried descriptor is now reactor-owned. Drop the manifest
        // without closing it; ordinary connection teardown owns them from here.
        self.clearInheritedStateFdManifest();

        // Active gauges are process-local derived state, not Helix authority.
        // Rebuild client ownership only after the single no-fail adoption commit:
        // a rejected candidate must never become observable as a live connection.
        // Preserved S2S slots publish separately below with their established
        // routes, keeping tcp-active and links-active as distinct transitions.
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                if (slot.value.s2s != null or slot.value.s2s_secured != null) continue;
                self.noteClientAccepted(&slot.value);
            }
        }

        // Queue rolling-old SESSION_MIGRATE authority before any inherited link
        // becomes operationally visible. A transient post-commit queue failure
        // closes only that preserved link; normal re-dial repairs it without ever
        // releasing a token-less roster ahead of missing session authority.
        for (adopted_s2s_ids.items) |id| {
            current_reactor = &self.reactors[id.shard];
            const conn = self.rx().clients.get(id) orelse continue;
            if (conn.s2s_secured == null) continue;
            self.scheduleSessionReplicaReplay(conn);
            self.publishInheritedS2sLink(id);
        }
        current_reactor = &self.reactors[0];
        srvLog(
            "onyx-server: UPGRADE resume — restored mandatory World/history/events/replay/webhooks ({d}/{d}/{d}/exact/{d}), {d} property entity(s)/{d} clock(s), re-attached {d} client connection(s) ({d} TLS, {d} wss), {d} MONITOR list(s), {d} session(s) across {d} account(s), {d} replica object(s), {d} staged migration(s), {d} consumed tombstone(s), {d} mesh link(s) preserved, {d} mesh re-dial(s)\n",
            .{ self.world.channelCount(), self.history.totalStoredCount(), self.event_history.len(), self.webhook_store.len(), property_entities_restored, property_clocks_restored, adopted, adopted_tls, adopted_ws, monitor_lists_restored, sessions_restored, session_accounts, replica_objects_restored, migrations_staged, tombstones_staged, s2s_resumed, redialed },
        );
    }

    /// Restore one account's carried session-registry record. An attached entry
    /// is re-joined to its adopted connection by inherited fd, keeping the SAME
    /// reclaim token; an attached entry whose connection did not survive the
    /// swap — and every detached entry — is retained as a detached ghost with
    /// its restore snapshot carried byte-identically. Per-account atomic: any
    /// failure rolls back every entry applied so far and returns 0, so the
    /// registry holds either the account's full pre-upgrade record or nothing
    /// (all-old-or-all-new, never a torn subset). Returns sessions restored.
    fn adoptSessionRegistryAccount(
        self: *LinuxServer,
        cap: session_capsule.SessionCapsule,
        detached_seq: *u64,
        attachment_clients: []const attachment_delivery_spool.ClientId,
        attachment_remaps: *std.ArrayList(attachment_delivery_spool.AttachmentRemap),
    ) usize {
        if (cap.account.len == 0 or cap.sessions.len == 0) return 0;
        self.bumpSessionListEpoch();
        // Validate first, apply second: one malformed entry rejects the whole
        // account BEFORE anything is written (fail-closed).
        var detached_count: usize = 0;
        for (cap.sessions, 0..) |entry, entry_index| {
            if (entry.token.len != @sizeOf(sessions_mod.Token)) return 0;
            if (entry.attachment_id) |raw| {
                _ = sessions_mod.AttachmentId.fromBytes(raw) catch return 0;
            }
            if (attachmentClientNeedsRemap(attachment_clients, entry.client)) {
                for (attachment_remaps.items) |mapping| {
                    if (mapping.old_client == entry.client) return 0;
                }
                for (cap.sessions[0..entry_index]) |prior| {
                    if (prior.client == entry.client) return 0;
                }
            }
            var token: sessions_mod.Token = undefined;
            @memcpy(&token, entry.token);
            const live_cid: ?u64 = if (!entry.detached and entry.fd >= 0)
                self.adoptedClientIdByFd(entry.fd)
            else
                null;
            if (live_cid) |cid| {
                const current = self.sessions.resumeHandleForClient(cap.account, cid) orelse return 0;
                if (!std.crypto.timing_safe.eql(sessions_mod.Token, current.token, token)) return 0;
            } else {
                detached_count += 1;
            }
        }
        const existing = self.sessions.copySessionsAlloc(self.allocator, cap.account) catch return 0;
        defer self.allocator.free(existing);
        if (existing.len + detached_count != cap.sessions.len or
            cap.sessions.len > self.sessions.cfg.max_sessions_per_account) return 0;

        const applied = self.allocator.alloc(u64, cap.sessions.len) catch return 0;
        defer self.allocator.free(applied);
        const remap_start = attachment_remaps.items.len;
        var remaps_committed = false;
        defer if (!remaps_committed) attachment_remaps.shrinkRetainingCapacity(remap_start);
        var applied_n: usize = 0;
        for (cap.sessions) |entry| {
            var token: sessions_mod.Token = undefined;
            @memcpy(&token, entry.token);
            // Attached entries re-join their adopted successor connection by fd.
            const live_cid: ?u64 = if (!entry.detached and entry.fd >= 0)
                self.adoptedClientIdByFd(entry.fd)
            else
                null;
            if (live_cid) |cid| {
                appendAttachmentRemapIfNeeded(
                    attachment_clients,
                    attachment_remaps,
                    entry.client,
                    cid,
                ) orelse return 0;
                // Pass 2 installs a compatibility row because the connection
                // capsule does not carry physical attachment identity. Refresh
                // that inert candidate row from HSSN v4 before it can become
                // live. A legacy v1-v3 row has no id; when successor crypto is
                // available, mint one now so the first reader upgrade creates
                // current identity and the next v4 upgrade preserves it.
                const outcome = self.restoreInheritedSessionAttachment(
                    cap.account,
                    cid,
                    token,
                    entry.attachment_id,
                    entry.signon_unix,
                ) orelse return 0;
                // Refreshing an already-adopted live client reports the
                // displaced pre-refresh row as `evicted`; it is the same
                // physical candidate, not a capacity eviction or retired
                // authority. Verify that exact identity instead of feeding it
                // to the ordinary eviction finalizer.
                const displaced = outcome.evicted orelse return 0;
                if (displaced.client != cid or
                    !std.crypto.timing_safe.eql(sessions_mod.Token, displaced.token, token)) return 0;
                continue;
            }
            const synthetic: client_model.ClientId = .{
                // Reactor shards never use the reserved all-ones shard id. Keep
                // inherited ghosts in that namespace so predecessor slab handles
                // cannot alias a newly adopted live successor connection.
                .shard = std.math.maxInt(u12),
                .slot = @truncate(detached_seq.*),
                .gen = @truncate(detached_seq.* >> 20),
            };
            detached_seq.* +%= 1;
            if (synthetic.isNone()) {
                for (applied[0..applied_n]) |rc| _ = self.sessions.remove(cap.account, rc);
                return 0;
            }
            const cid = monitorIdFromClient(synthetic);
            const outcome = self.restoreInheritedSessionAttachment(
                cap.account,
                cid,
                token,
                entry.attachment_id,
                entry.signon_unix,
            ) orelse {
                for (applied[0..applied_n]) |rc| _ = self.sessions.remove(cap.account, rc);
                return 0;
            };
            if (outcome.evicted != null) {
                _ = self.sessions.remove(cap.account, cid);
                for (applied[0..applied_n]) |rc| _ = self.sessions.remove(cap.account, rc);
                return 0;
            }
            _ = self.sessions.restorePortableResumeIssued(cap.account, cid, entry.portable_resume);
            // The connection did not survive the swap (or the session was
            // already detached): retain a detached ghost — the token still
            // reclaims, and the restore snapshot rides along when present.
            const snap: ?[]const u8 = if (entry.snapshot.len != 0) entry.snapshot else null;
            if (!self.sessions.markDetachedWithSnapshot(cap.account, cid, snap)) {
                _ = self.sessions.remove(cap.account, cid);
                for (applied[0..applied_n]) |rc| _ = self.sessions.remove(cap.account, rc);
                return 0;
            }
            applied[applied_n] = cid;
            applied_n += 1;
            appendAttachmentRemapIfNeeded(
                attachment_clients,
                attachment_remaps,
                entry.client,
                cid,
            ) orelse {
                _ = self.sessions.remove(cap.account, cid);
                applied_n -= 1;
                for (applied[0..applied_n]) |rc| _ = self.sessions.remove(cap.account, rc);
                return 0;
            };
        }
        // Live rows were already adopted in Pass 2 and validated above. Apply
        // their non-failing portability bit only after every synthetic ghost was
        // installed, keeping account adoption atomic on allocation failures.
        for (cap.sessions) |entry| {
            if (entry.detached or entry.fd < 0) continue;
            const cid = self.adoptedClientIdByFd(entry.fd) orelse continue;
            _ = self.sessions.restorePortableResumeIssued(cap.account, cid, entry.portable_resume);
        }
        remaps_committed = true;
        return cap.sessions.len;
    }

    /// Install the exact HSSN v4 attachment id, or mint the first stable id for
    /// a genuine legacy v1-v3 row. The latter is reader-first compatible: old
    /// predecessors never issued SRM2, while this successor's next v4 seal will
    /// preserve the freshly minted id byte-for-byte. Without configured crypto,
    /// retain the compatibility row without inventing weak identity.
    fn restoreInheritedSessionAttachment(
        self: *LinuxServer,
        account: []const u8,
        client: sessions_mod.ClientId,
        token: sessions_mod.Token,
        encoded_attachment_id: ?[session_capsule.attachment_id_len]u8,
        signon_ms: i64,
    ) ?sessions_mod.AttachOutcome {
        if (encoded_attachment_id) |raw| {
            const attachment_id = sessions_mod.AttachmentId.fromBytes(raw) catch return null;
            return self.sessions.attachWithAttachmentReportingEviction(
                account,
                client,
                token,
                attachment_id,
                signon_ms,
            ) catch null;
        }

        const io = self.config.crypto_io orelse
            return self.sessions.attachReportingEviction(
                account,
                client,
                token,
                signon_ms,
            ) catch null;
        // AttachmentId.mint already bounds zero-entropy retries. Bound global
        // collision retries independently so hostile/injected entropy cannot
        // spin adoption forever.
        for (0..4) |_| {
            const attachment_id = sessions_mod.AttachmentId.mint(io) catch return null;
            return self.sessions.attachWithAttachmentReportingEviction(
                account,
                client,
                token,
                attachment_id,
                signon_ms,
            ) catch |err| switch (err) {
                error.DuplicateAttachmentId => continue,
                else => return null,
            };
        }
        return null;
    }

    fn attachmentClientNeedsRemap(
        attachment_clients: []const attachment_delivery_spool.ClientId,
        old_client: attachment_delivery_spool.ClientId,
    ) bool {
        for (attachment_clients) |client| {
            if (client == old_client) return true;
        }
        return false;
    }

    /// Append only mappings that ADS1 can consume. The caller preallocates the
    /// exact ADS1 attachment cardinality, so a large HSSN registry cannot turn
    /// restore into unbounded remap allocation. Duplicate predecessor owners
    /// fail closed.
    fn appendAttachmentRemapIfNeeded(
        attachment_clients: []const attachment_delivery_spool.ClientId,
        attachment_remaps: *std.ArrayList(attachment_delivery_spool.AttachmentRemap),
        old_client: attachment_delivery_spool.ClientId,
        new_client: attachment_delivery_spool.ClientId,
    ) ?void {
        if (!attachmentClientNeedsRemap(attachment_clients, old_client)) return {};
        for (attachment_remaps.items) |mapping| {
            if (mapping.old_client == old_client) return null;
        }
        if (attachment_remaps.items.len == attachment_remaps.capacity) return null;
        attachment_remaps.appendAssumeCapacity(.{
            .old_client = old_client,
            .new_client = new_client,
        });
        return {};
    }

    /// Deterministic shard for an adopted inherited connection: derived from
    /// the (non-negative) socket fd so the spread is stable within one adoption
    /// pass without widening any capsule. The original owning shard is NOT
    /// preserved — client ids never survive the swap (the fd is the Helix join
    /// key), so shard identity carries no cross-upgrade meaning; only a
    /// consistent, balanced pinning matters.
    fn adoptShardForFd(self: *LinuxServer, fd: i32) usize {
        std.debug.assert(fd >= 0);
        return @as(usize, @intCast(fd)) % self.reactors.len;
    }

    /// Find the successor-side client id of an adopted connection by its
    /// inherited socket fd (the Helix join key). Boot-time only — the client
    /// tables hold exactly the connections Pass 2 adopted (across ALL shards).
    fn adoptedClientIdByFd(self: *LinuxServer, fd: i32) ?u64 {
        for (self.reactors) |*r| {
            var it = r.clients.iterator();
            while (it.next()) |e| {
                if (e.value.fd == fd) return monitorIdFromClient(e.id);
            }
        }
        return null;
    }

    /// As `adoptedClientIdByFd`, but returns the connection itself — for
    /// adoption passes that need session state (e.g. the SILENCE owner nick).
    fn adoptedConnByFd(self: *LinuxServer, fd: i32) ?*ConnState {
        for (self.reactors) |*r| {
            var it = r.clients.iterator();
            while (it.next()) |e| {
                if (e.value.fd == fd) return e.value;
            }
        }
        return null;
    }

    /// Re-attach one carried-over client: take ownership of its inherited socket
    /// fd, restore its session (and live TLS engine when carried), and arm recv.
    /// Returns true on success; ANY failure closes the fd and frees the slot.
    fn deinitInheritedCandidateClients(self: *LinuxServer, table: *ClientTable) void {
        for (table.slots.items) |*slot| {
            if (!slot.occupied) continue;
            const conn = &slot.value;
            // Candidate adoption never submits RECV/SEND/CONNECT. Releasing the
            // inline storage is therefore safe; the fd itself remains owned by
            // the exact inherited-state manifest and is closed once by the
            // centralized abandonment path after every candidate is dismantled.
            std.debug.assert(!conn.recv_armed and !conn.send_armed);
            if (conn.s2s) |link| {
                link.deinit();
                self.allocator.destroy(link);
                conn.s2s = null;
            }
            if (conn.s2s_secured) |link| {
                link.deinit();
                self.allocator.destroy(link);
                conn.s2s_secured = null;
            }
            self.abortMultiline(conn);
            if (conn.tls) |t| {
                t.deinit();
                self.allocator.destroy(t);
                conn.tls = null;
            }
            if (conn.ws) |w| {
                self.allocator.destroy(w);
                conn.ws = null;
            }
            self.clearDeferredSessionMeshParts(conn);
            conn.session_list_cache.reset();
            conn.send_overflow.clearAndFree(conn.overflow_allocator);
            conn.tls_deferred_plain.clearAndFree(conn.overflow_allocator);
            conn.tls_deferred_charge = 0;
            conn.tls_control_charge = 0;
            conn.recv_overflow.clearAndFree(conn.overflow_allocator);
            conn.fd = -1;
        }
    }

    fn rollbackInheritedClientBeforeRecv(self: *LinuxServer, id: client_model.ClientId, fd: linux.fd_t, close_fd: bool) void {
        const conn = self.rx().clients.get(id) orelse {
            if (close_fd) closeFd(fd);
            return;
        };
        if (conn.clone_counted) {
            if (conn.peer_addr) |addr| self.clone_limit.release(addr);
            conn.clone_counted = false;
        }
        self.world.removeClient(worldIdFromClient(id));
        if (conn.session.account()) |acct| _ = self.removeTrackedSession(acct, monitorIdFromClient(id));
        conn.session_list_cache.reset();
        conn.recv_overflow.clearAndFree(conn.overflow_allocator);
        conn.send_overflow.clearAndFree(conn.overflow_allocator);
        conn.tls_deferred_plain.clearAndFree(conn.overflow_allocator);
        conn.tls_deferred_charge = 0;
        conn.tls_control_charge = 0;
        if (conn.tls) |t| {
            t.deinit();
            self.allocator.destroy(t);
            conn.tls = null;
        }
        if (conn.ws) |w| {
            self.allocator.destroy(w);
            conn.ws = null;
        }
        _ = self.rx().clients.free(id);
        if (close_fd) closeFd(fd);
    }

    /// Tear down a carried secured link only while it is still inert. Callers
    /// must never use this after either a RECV or SEND SQE has been registered:
    /// both operations borrow storage inside the slab slot until completion.
    fn rollbackInheritedS2sBeforeIo(self: *LinuxServer, id: client_model.ClientId, fd: linux.fd_t, close_fd: bool) void {
        const conn = self.rx().clients.get(id) orelse {
            if (close_fd) closeFd(fd);
            return;
        };
        if (conn.s2s_secured) |link| {
            link.deinit();
            self.allocator.destroy(link);
            conn.s2s_secured = null;
        }
        conn.recv_overflow.clearAndFree(conn.overflow_allocator);
        conn.send_overflow.clearAndFree(conn.overflow_allocator);
        conn.tls_deferred_plain.clearAndFree(conn.overflow_allocator);
        conn.tls_deferred_charge = 0;
        conn.tls_control_charge = 0;
        conn.session_list_cache.reset();
        _ = self.rx().clients.free(id);
        if (close_fd) closeFd(fd);
    }

    fn adoptInheritedClient(self: *LinuxServer, snap: session_snapshot.Snapshot, tls_state: ?tls_snapshot.Snapshot, ws_state: ?ws_snapshot.Snapshot, close_fd_on_failure: bool) bool {
        // Per-SHARD cap (rx() is the fd-derived target shard): matches the
        // accept path, whose cap is also per-shard — each reactor's table is
        // reserved to max_clients, so the bound protects buffer address
        // stability, not a global head-count. Failure cleans up this inherited
        // fd locally, then the caller rejects the whole successor startup.
        if (self.rx().clients.len() >= self.config.max_clients) {
            if (close_fd_on_failure) closeFd(snap.fd);
            return false;
        }
        const id = self.rx().clients.alloc(ConnState.init(snap.fd)) catch {
            if (close_fd_on_failure) closeFd(snap.fd);
            return false;
        };
        const conn = self.rx().clients.get(id).?;
        conn.overflow_allocator = self.allocator; // backs the SendQ overflow heap
        conn.gagged = snap.gagged;
        conn.ircx = snap.ircx;
        conn.unfurl_opt_in = snap.unfurl_opt_in;
        conn.last_search_ms = snap.last_search_ms;
        conn.keytrans_require = snap.keytrans_require;
        conn.nick_claimed_at_ms = snap.nick_claimed_at_ms;
        conn.token = tokenFromId(id) catch {
            _ = self.rx().clients.free(id);
            if (close_fd_on_failure) closeFd(snap.fd);
            return false;
        };
        conn.peer_addr = snap.peer_addr;
        conn.throttle_counted = snap.throttle_counted;
        conn.mesh_clone_counted = snap.mesh_clone_counted;
        conn.mesh_clone_hash = snap.mesh_clone_hash;
        if (comptime builtin.os.tag == .windows) {
            const expected_mesh_hash = self.meshCloneHash(conn);
            if (self.config.native_adopt_barrier != null and conn.peer_addr == null) {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            }
            if (self.config.native_adopt_barrier != null and
                ((conn.throttle_counted and (self.conn_throttle == null or self.ipCloneExempt(conn))) or
                    (conn.mesh_clone_counted and (expected_mesh_hash == null or expected_mesh_hash.? != conn.mesh_clone_hash))))
            {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            }
        }
        if (snap.clone_counted) {
            const addr = conn.peer_addr orelse {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            };
            self.clone_limit.register(addr) catch {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            };
            conn.clone_counted = true;
        }
        // Restore the carried monotonic signon/last-message clocks so WHOIS idle
        // and signon stay continuous across the UPGRADE; a pre-signon snapshot
        // (or a fresh session) carries 0 → fall back to "now". last_activity is a
        // liveness/PING clock for THIS attachment, so it legitimately resets now.
        const now = self.nowMs();
        conn.connected_at_ms = if (snap.connected_at_ms != 0) snap.connected_at_ms else now;
        conn.last_message_ms = if (snap.last_message_ms != 0) snap.last_message_ms else now;
        conn.last_activity_ms = now;
        conn.session.restore(snap);
        // The carried oper block is profile history only: restore() deliberately
        // clears it. Re-derive successor authority from the restored authenticated
        // account and the live sealed local config, while keeping durable OCG2
        // explicitly disabled at the frozen Step 5 boundary. A forged/nonconfigured
        // carried `is_oper` therefore stays inert, while an exact configured-local
        // account retains its current privilege projection across Helix.
        const configured_binding = if (conn.session.account()) |account|
            if (self.oper_registry) |*registry|
                oper_session_provenance.configuredLocalBinding(registry, account)
            else
                null
        else
            null;
        _ = conn.session.reconcileOperAuthority(configured_binding, .disabled, self.grantNowU64());
        self.applyOperAutoOverride(conn); // re-affirm +j across USR2 for auto_override admins
        self.injectSessionState(conn);
        // Determine the destination physical cap before validating any carried
        // wire/tail/control charge. A smaller new policy refuses the whole adopt.
        self.assignConnClass(conn);
        if (snap.flood_guard) |carry| {
            const derived = conn.flood_guard orelse {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            };
            conn.flood_guard = flood_guard.FloodGuard.importCarry(derived.config, now, carry) catch {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            };
        } else if (comptime builtin.os.tag == .windows) {
            if (self.config.native_adopt_barrier != null and conn.flood_guard != null) {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            }
        }
        // TLS client: rebuild the live engine BEFORE anything else can touch the
        // socket. Any failure cleans up the fd/slot and propagates whole-startup
        // refusal — a TLS connection must never be adopted as plaintext.
        if (tls_state) |ts| {
            if (!self.adoptTlsState(conn, ts)) {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            }
        }
        // wss browser client: rebuild the WebSocket framing adapter, restoring
        // the carried partial framing state (current v3 capsule) — the deframer's
        // buffered partial inbound frame + fragmentation flags and the tx
        // accumulator's partial outbound line — so a mid-frame client resumes
        // with no lost bytes. Exact current adoption also restores the selected
        // subprotocol; legacy v1/v2 decoding is reserved for cold migration. The TLS
        // engine rebuilt above sits beneath it. ANY failure (allocation, or a
        // partial blob that cannot fit the adapter's buffers — impossible from
        // an honest predecessor, but the arena is validated fail-closed) cleans
        // the fd/slot and propagates whole-startup refusal, never adopting a wss
        // socket as raw IRC bytes (which would corrupt every frame).
        if (ws_state) |wsv| {
            if (wsv.phase_open) {
                const ws_ok = blk: {
                    const ws = self.allocator.create(WsState) catch break :blk false;
                    ws.* = .{ .phase = .open };
                    if (wsv.deframer.len > ws.deframer.buf.len or wsv.tx.len > ws.tx_buf.len or
                        wsv.binary_message.len > ws.binary_message_buf.len)
                    {
                        self.allocator.destroy(ws);
                        break :blk false;
                    }
                    @memcpy(ws.deframer.buf[0..wsv.deframer.len], wsv.deframer);
                    ws.deframer.len = wsv.deframer.len;
                    ws.deframer.fragmented = wsv.fragmented;
                    ws.deframer.msg_binary = wsv.msg_binary;
                    ws.subprotocol = wsv.subprotocol;
                    @memcpy(ws.binary_message_buf[0..wsv.binary_message.len], wsv.binary_message);
                    ws.binary_message_len = wsv.binary_message.len;
                    ws.binary_message_active = wsv.binary_message_active;
                    @memcpy(ws.tx_buf[0..wsv.tx.len], wsv.tx);
                    ws.tx_len = wsv.tx.len;
                    conn.ws = ws;
                    break :blk true;
                };
                if (!ws_ok) {
                    self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                    return false;
                }
            }
        }
        // v4: restore the partial inbound line into the RecvQ (inline fast path
        // when it fits, heap overflow otherwise) so the client's next bytes
        // continue the SAME line instead of parsing as a torn one. An overflow
        // allocation failure cleans the fd/slot and rejects successor startup;
        // adopting with a torn inbound stream is never allowed.
        if (snap.pending_in.len != 0) {
            if (snap.pending_in.len <= conn.line_buf.len) {
                @memcpy(conn.line_buf[0..snap.pending_in.len], snap.pending_in);
                conn.line_len = snap.pending_in.len;
            } else {
                conn.recv_overflow.appendSlice(conn.overflow_allocator, snap.pending_in) catch {
                    self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                    return false;
                };
            }
        }
        // v4: re-queue a plaintext connection's unsent SendQ tail verbatim (the
        // bytes are already framed/formatted wire bytes — bypass every seam).
        // A TLS connection's pending ciphertext was re-queued by adoptTlsState
        // above; the seal path guarantees this field is empty for those.
        if (snap.pending_out.len != 0 and tls_state == null) {
            conn.sendq_cap = @max(conn.sendq_cap, snap.pending_out.len);
            rawAppendToConn(conn, snap.pending_out) catch {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            };
        }
        // Re-track before the socket becomes live in io_uring. A carried
        // account session without its exact SessionStore row is not a usable
        // resume: later registry adoption cannot repair it safely, and freeing
        // a slot after submitRecv would race an in-flight completion. Therefore
        // allocation/capacity failure cleans this inherited client while it is
        // inert and makes the caller reject the whole successor startup.
        if (conn.session.account()) |acct| {
            var token: sessions_mod.Token = undefined;
            if (snap.session_token.len == @sizeOf(sessions_mod.Token)) {
                @memcpy(&token, snap.session_token);
            } else {
                token = self.genSessionToken();
            }
            const outcome = self.sessions.attachReportingEviction(
                acct,
                monitorIdFromClient(id),
                token,
                conn.connected_at_ms,
            ) catch {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            };
            // Exact inherited state may not repair capacity by evicting another
            // carried attachment. Such an eviction would also publish replica /
            // delivery side effects outside the candidate stores.
            if (outcome.evicted != null) {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            }
        }
        // Re-populate the world nick registry so the carried client stays
        // addressable (WHOIS, PRIVMSG target). A fresh successor world has no
        // collisions; ignore NickInUse defensively. Channel membership carry-over
        // is a further refinement.
        if (snap.nick.len != 0 and !std.mem.eql(u8, snap.nick, "*")) {
            self.world.registerNick(snap.nick, worldIdFromClient(id)) catch |err| switch (err) {
                error.NickInUse => {
                    const account = conn.session.account() orelse {
                        self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                        return false;
                    };
                    if (!self.nickHeldBySameAccount(snap.nick, account, worldIdFromClient(id))) {
                        self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                        return false;
                    }
                },
                else => {
                    self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                    return false;
                },
            };
        }
        // Re-join the carried channel memberships with their exact member modes.
        var cit = session_snapshot.channelIter(snap.channels_blob);
        while (cit.next()) |ch| {
            self.world.restoreMember(ch.name, worldIdFromClient(id), .{ .bits = ch.modes }) catch {
                self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
                return false;
            };
        }
        // Restore exec hygiene before the final causal stamp. A bad inherited
        // descriptor rejects the candidate and leaves the manifest as the sole
        // close authority for transactional callers.
        if (!setCloexec(snap.fd, true)) {
            self.rollbackInheritedClientBeforeRecv(id, snap.fd, close_fd_on_failure);
            return false;
        }
        // Nothing below this point can reject the adoption. Stamp the fresh
        // mesh claim only after every allocation/world/session mutation, so a
        // rolled-back client cannot leave a phantom causal advance behind.
        conn.mesh_nick_hlc = self.nextMeshHlc();
        // Carried outbound bytes remain inert too. runOnce fairly arms RECV and
        // any required SEND after control SQEs, retaining this slot on SQ-full.
        conn.io_activation_pending = true;
        conn.activation_recv_required = true;
        // Re-apply the connection class (the restored session carries the facets).
        self.assignConnClass(conn);
        return true;
    }

    /// Rebuild a carried client's live TLS engine from its snapshot. On success
    /// the conn owns a resumed TlsConn and any unflushed predecessor ciphertext
    /// is re-queued verbatim. Returns false on ANY failure; the caller cleans the
    /// client and rejects successor startup (TLS never falls back to plaintext).
    fn adoptTlsState(self: *LinuxServer, conn: *ConnState, ts: tls_snapshot.Snapshot) bool {
        tls_snapshot.validate(ts) catch return false;
        if (ts.fd != conn.fd) return false;
        const tail_charge = std.math.cast(usize, ts.deferred_ciphertext_charge) orelse return false;
        const charged = std.math.add(usize, std.math.add(usize, ts.pending_out.len, tail_charge) catch return false, ts.control_charge) catch return false;
        if (charged > conn.sendq_cap) return false;
        const t = self.allocator.create(tls_conn.TlsConn) catch return false;
        const cfg12: ?tls12_server.Config = if (self.config.tls12_cert_chain.len != 0 and
            (self.config.tls12_signing_key != null or self.config.tls_rsa_signing_key != null)) self.tls12Config() else null;
        t.* = tls_conn.TlsConn.resumeFrom(self.allocator, self.tls13Config(self.config.tls_request_client_cert), cfg12, ts.state) catch {
            self.allocator.destroy(t);
            return false;
        };
        // This candidate still owns no live transport. Every allocation/getter
        // and mandatory exporter derivation completes before publication.
        var success = false;
        defer if (!success) {
            t.deinit();
            self.allocator.destroy(t);
        };
        t.restoreInheritedOffload(conn.fd, ts.tx_offloaded, ts.rx_offloaded) catch return false;
        var exporter: [32]u8 = @splat(0);
        defer std.crypto.secureZero(u8, &exporter);
        if (ts.state.engine == .tls13) t.channelBindingTlsExporter(&exporter) catch return false;
        conn.tls_deferred_plain.ensureTotalCapacityPrecise(conn.overflow_allocator, ts.deferred_plain.len) catch return false;
        var wire = sendq.prepareAppend(conn, ts.pending_out.len) catch return false;
        defer wire.abort();
        // Allocation-free local publication; outer whole-adopt rollback retains
        // predecessor FD custody and tears down every speculative candidate.
        wire.commit(ts.pending_out);
        conn.tls_deferred_plain.appendSliceAssumeCapacity(ts.deferred_plain);
        conn.tls_deferred_charge = tail_charge;
        conn.tls_control_charge = ts.control_charge;
        conn.tls_kernel_prefix_remaining = ts.kernel_tx_prefix_remaining;
        conn.tls = t;
        conn.is_tls = true;
        conn.tls_tx_offloaded = ts.tx_offloaded;
        conn.tls_rx_offloaded = ts.rx_offloaded;
        if (ts.certfp.len != 0) {
            @memcpy(&conn.certfp_buf, ts.certfp);
            conn.session.tls_certfp = conn.certfp_buf[0..];
        }
        if (ts.state.engine == .tls13) {
            conn.tls_exporter_buf = exporter;
            conn.session.tls_exporter = exporter;
        }
        conn.session.tls_cipher = t.cipherName();
        success = true;
        return true;
    }

    /// Restore the sealed converged remote-member roster (the v4 capsule roster
    /// block) into a freshly-resumed link's route table. Runs BEFORE any RESYNC
    /// processing so the peer's re-burst of these same members dedups to
    /// `.unchanged` (or a genuine `.status_changed`) instead of re-announcing
    /// every surviving remote member to local clients as a spurious JOIN — and
    /// NAMES for remote members stays correct even before the re-burst lands.
    /// No deltas are queued for primes: restored state was already visible to
    /// local clients before the swap. Fail-closed: any malformed/duplicate
    /// record or allocation failure errors out and the caller aborts the whole
    /// adoption transactionally (the rollback tears down the link, so a partial
    /// roster never publishes).
    fn primeInheritedS2sRoster(
        self: *LinuxServer,
        link: *secured_s2s_link.SecuredLink,
        snap: *const s2s_snapshot.Snapshot,
        now: i64,
    ) !void {
        _ = self;
        var it = s2s_snapshot.rosterIterator(snap);
        while (try it.next()) |m| {
            try link.primeResumedMember(m.channel, m.nick, m.node, m.status, m.hlc, .{
                .username = m.username,
                .realname = m.realname,
                .host = m.host,
                .account = m.account,
                .real_host = m.real_host,
                .certfp = m.certfp,
                .session_token = m.session_token,
            }, now);
        }
    }

    /// Re-attach a PRESERVED secured mesh link across a Helix upgrade: take
    /// ownership of its inherited socket fd, rebuild the SecuredLink established
    /// from the capsule (Mooring record keys + counters + inner framing header),
    /// prime the carried remote-member roster, arm recv, then RESYNC with the
    /// peer + re-burst our state so the roster reconverges within a round-trip —
    /// the peer never saw a drop and local clients never see a spurious re-JOIN.
    /// ANY failure closes the fd + frees the slot (the mesh then heals via
    /// the normal re-dial on the next sweep). Returns the inert candidate id;
    /// peer/event/stat visibility is published only after the whole transaction
    /// commits.
    fn adoptInheritedS2sLink(self: *LinuxServer, snap: s2s_snapshot.Snapshot, close_fd_on_failure: bool) ?client_model.ClientId {
        // Validate before allocating a slot or touching a carried descriptor.
        // Empty is the historical unknown-endpoint representation in either
        // direction; nonempty addresses must be canonical in6 storage.
        var target: ?posix.sockaddr.in6 = null;
        if (snap.connect_addr.len != 0) {
            if (snap.connect_addr.len != @sizeOf(posix.sockaddr.in6)) {
                if (close_fd_on_failure) closeFd(snap.fd);
                return null;
            }
            var addr: posix.sockaddr.in6 = undefined;
            @memcpy(std.mem.asBytes(&addr), snap.connect_addr);
            if (addr.family != posix.AF.INET6 or addr.port == 0) {
                if (close_fd_on_failure) closeFd(snap.fd);
                return null;
            }
            target = addr;
        }
        if (!self.s2sSecured() or self.rx().clients.len() >= self.config.max_clients) {
            if (close_fd_on_failure) closeFd(snap.fd);
            return null;
        }
        const ident = self.config.node_identity orelse {
            if (close_fd_on_failure) closeFd(snap.fd);
            return null;
        };
        const io = self.config.crypto_io orelse {
            if (close_fd_on_failure) closeFd(snap.fd);
            return null;
        };
        const id = self.rx().clients.alloc(ConnState.init(snap.fd)) catch {
            if (close_fd_on_failure) closeFd(snap.fd);
            return null;
        };
        const conn = self.rx().clients.get(id).?;
        conn.overflow_allocator = self.allocator;
        const configured_sendq = if (self.config.class_registry) |*reg|
            reg.classFor(.{ .is_server_link = true }).policy.sendq
        else
            conn.sendq_cap;
        conn.sendq_cap = s2sSendqCap(configured_sendq);
        conn.token = tokenFromId(id) catch {
            _ = self.rx().clients.free(id);
            if (close_fd_on_failure) closeFd(snap.fd);
            return null;
        };
        const now = self.nowMs();
        conn.connected_at_ms = now;
        conn.last_activity_ms = now;
        conn.last_message_ms = now;
        conn.s2s_initiator = snap.s2s_initiator;
        // Restore the dial target so the [mesh].connect sweep recognizes this
        // preserved link and never dials a duplicate (→ collision churn).
        if (target) |addr| {
            conn.s2s_connect_addr = addr;
            conn.s2s_dial_target_known = true;
        }
        self.captureClientHost(conn);

        const wall: u64 = @intCast(@max(0, platform.realtimeMillis()));
        const not_before = wall -| (5 * 60 * 1000);
        const prekey = ident.signedPrekey(1, not_before, 24 * 60 * 60 * 1000, s2s_bands, s2s_features) catch {
            _ = self.rx().clients.free(id);
            if (close_fd_on_failure) closeFd(snap.fd);
            return null;
        };
        var pins: [secured_s2s_link.max_expected_remotes][20]u8 = undefined;
        var pin_count: usize = 0;
        for (self.config.mesh_trust_roots) |root| {
            if (pin_count == pins.len) break;
            if (parseMeshTrustRoot(root)) |pin| {
                pins[pin_count] = pin;
                pin_count += 1;
            }
        }
        const role: secured_s2s_link.Role = if (snap.role == 1) .responder else .initiator;
        const now_u: u64 = @intCast(@max(@as(i64, 0), now));
        const link = self.allocator.create(secured_s2s_link.SecuredLink) catch {
            _ = self.rx().clients.free(id);
            if (close_fd_on_failure) closeFd(snap.fd);
            return null;
        };
        var media_s2s_cfg = self.config.s2s_config;
        if (media_s2s_cfg.max_frame_size < media_ws_relay.required_max_frame_size) {
            media_s2s_cfg.max_frame_size = media_ws_relay.required_max_frame_size;
        }
        link.* = secured_s2s_link.SecuredLink.resumeOuter(.{
            .allocator = self.allocator,
            .role = role,
            .identity = ident,
            .local_prekey = prekey,
            .cfg = .{
                .realm = ident.realm,
                .supported_bands = s2s_bands,
                .supported_features = s2s_features,
                .mesh_pass = if (self.mesh_admission_token.len != 0) self.mesh_admission_token else self.config.mesh_pass,
                .meshpass_roots = self.meshpass_roots,
                .now_ms = wall,
            },
            .rng = io,
            .server_name = self.serverName(),
            .description = self.config.server_description,
            .local_epoch_ms = wall,
            .inner_config = media_s2s_cfg,
            .expected_remotes = pins[0..pin_count],
            .trusted_node_keys = self.mesh_trusted_node_keys,
        }, .{
            .established = mooring_hs.Established.deserialize(&snap.established),
            .send_counter = snap.send_counter,
            .recv_counter = snap.recv_counter,
            .feed_seq = snap.feed_seq,
            .inner = .{
                .link = .{
                    .local_epoch_ms = snap.pl_local_epoch_ms,
                    .remote_epoch_ms = snap.pl_remote_epoch_ms,
                    .send_credit = snap.pl_send_credit,
                    .pending_credit = snap.pl_pending_credit,
                    .next_out_seq = snap.pl_next_out_seq,
                    .next_in_seq = snap.pl_next_in_seq,
                    .last_acked_by_remote = snap.pl_last_acked,
                },
                .remote_node_id = snap.remote_node_id,
                .remote_epoch_ms = snap.remote_epoch_ms,
                .peer_supports_signing = (snap.caps & s2s_snapshot.cap_signing) != 0,
                .peer_supports_account = (snap.caps & s2s_snapshot.cap_account) != 0,
                .peer_supports_oper_info = (snap.caps & s2s_snapshot.cap_oper_info) != 0,
                .peer_supports_repair = (snap.caps & s2s_snapshot.cap_repair) != 0,
                .peer_supports_session_replica_v2 = (snap.caps & s2s_snapshot.cap_session_replica_v2) != 0,
                .peer_supports_session_attachment_lease_v2 = (snap.caps & s2s_snapshot.cap_session_attachment_lease_v2) != 0,
                .peer_supports_secure_relay_v2 = (snap.caps & s2s_snapshot.cap_secure_relay_v2) != 0,
                .peer_supports_event_spine_v2 = (snap.caps & s2s_snapshot.cap_event_spine_v2) != 0,
                .peer_supports_relay_v2_current = (snap.caps_ext & s2s_snapshot.cap_ext_relay_v2_current) != 0,
                .peer_supports_relay_v2_ack_confirm = (snap.caps_ext & s2s_snapshot.cap_ext_relay_v2_ack_confirm) != 0,
            },
            .remote_name = snap.remote_name,
            .rec_inbuf = snap.rec_inbuf,
            .now_ms = now_u,
            .rng_seed = snap.remote_node_id ^ now_u ^ @as(u64, @intCast(@max(@as(i32, 0), snap.fd))),
        }) catch {
            self.allocator.destroy(link);
            _ = self.rx().clients.free(id);
            if (close_fd_on_failure) closeFd(snap.fd);
            return null;
        };
        conn.s2s_secured = link;
        link.setLocalNickResolver(self.localNickResolver());
        link.setResidenceVerifier(self.residenceVerifier());
        link.setSessionTokenResolver(self.sessionTokenResolver());
        link.setSessionTokenNickAuthorizer(self.sessionTokenNickAuthorizer());
        conn.s2s_burst_done = true; // the reconverge below is driven explicitly

        // Prime the carried roster BEFORE any inbound/RESYNC processing (see
        // primeInheritedS2sRoster). A pre-v4 capsule carries an empty roster and
        // primes nothing — the RESYNC alone reconverges, the pre-bump behavior.
        self.primeInheritedS2sRoster(link, &snap, now) catch {
            self.rollbackInheritedS2sBeforeIo(id, snap.fd, close_fd_on_failure);
            return null;
        };

        if (snap.pending_out.len != 0) {
            conn.sendq_cap = @max(conn.sendq_cap, snap.pending_out.len);
            appendToConn(conn, snap.pending_out) catch {
                self.rollbackInheritedS2sBeforeIo(id, snap.fd, close_fd_on_failure);
                return null;
            };
        }

        // Reconverge over the preserved encrypted stream: ask the peer to re-burst
        // its full state (RESYNC) and re-burst ours. The record counters continue
        // from the capsule, so the peer accepts these seamlessly — no netsplit.
        // Stage the mandatory record without arming SEND. Until submitRecv below,
        // every failure can still destroy the slab slot safely; afterward no path
        // rejects adoption or frees storage borrowed by io_uring.
        // A v1/v2 predecessor could not checkpoint the relay-v2.1 extension
        // result. Re-probe on the preserved stream before replay; an old peer
        // sees only a harmless ordinary PING, while two current peers regain the
        // capability without disconnecting.
        if (!link.supportsSecureRelayV2()) {
            link.probeRelayV2Current() catch {
                self.rollbackInheritedS2sBeforeIo(id, snap.fd, close_fd_on_failure);
                return null;
            };
        }
        link.sendResync() catch {
            self.rollbackInheritedS2sBeforeIo(id, snap.fd, close_fd_on_failure);
            return null;
        };
        appendToConn(conn, link.outbound()) catch {
            self.rollbackInheritedS2sBeforeIo(id, snap.fd, close_fd_on_failure);
            return null;
        };
        link.clearOutbound();

        // The fd survived ONE execve on purpose; re-arm CLOEXEC before the slot
        // becomes a successful candidate.
        if (!setCloexec(snap.fd, true)) {
            self.rollbackInheritedS2sBeforeIo(id, snap.fd, close_fd_on_failure);
            return null;
        }

        // Replay the complete retained Store before the token-less roster burst.
        // This can span maintenance turns under SendQ pressure; the pending
        // RESYNC burst is released by the same gate as a fresh establishment.
        conn.session_replica_resync_burst_pending = true;
        conn.io_activation_pending = true;
        conn.activation_recv_required = true;
        // Refresh live/detached local snapshots before fixing the replay
        // generation/cursor, but do not replay here: replay/burst helpers normally
        // arm SEND. The maintenance driver resumes them only after activation has
        // armed the initial RESYNC, preserving authority-before-roster ordering.
        self.scheduleSessionReplicaReplay(conn);
        return id;
    }

    /// Publish the operational surfaces of one fully prepared inherited link.
    /// Called only after the complete inherited-state transaction commits.
    fn publishInheritedS2sLink(self: *LinuxServer, id: client_model.ClientId) void {
        current_reactor = &self.reactors[id.shard];
        defer current_reactor = &self.reactors[0];
        const conn = self.rx().clients.get(id) orelse return;
        const link = conn.s2s_secured orelse return;
        // The whole adoption has committed. Only now may the configured-dial
        // table point at this authenticated survivor; rollback never sees it.
        if (conn.s2s_dial_target_known and link.peerNodeKey() != null) {
            for (self.mesh_dials) |*dial| {
                if (dial.addr == null) dial.addr = sockaddrForHost(dial.host, dial.port, 2_000) catch continue;
                if (sameSockaddrIn(conn.s2s_connect_addr, dial.addr.?)) dial.token = conn.token;
            }
        }
        const rname = link.remoteName();
        if (rname.len != 0) {
            self.publishServerLink(rname, true);
            self.markPeerHealth(rname, .established);
        }
        self.publishPeerCount();
        self.updatePartitionTransitions();
        self.bindRelayV2UnboundIfReady(conn, link);
        self.noteS2sTcpOpened(conn);
        self.noteS2sEstablished(conn, rname, "helix-resume");
        self.traceLog(.info, .s2s, "s2s secured peer preserved across upgrade");
    }

    /// True when `token` is the live connection of a config-managed
    /// `[mesh].connect` dial. Those links are NOT sealed as re-dial hints — the
    /// successor's mesh boot pass re-dials every configured peer itself.
    fn dialManaged(self: *LinuxServer, token: RingFdToken) bool {
        for (self.mesh_dials) |dial| {
            const t = dial.token orelse continue;
            if (t.slot == token.slot and t.gen == token.gen) return true;
        }
        return false;
    }

    /// RESTART-only listener handoff: re-exec preserving just the listening
    /// socket (no state arena). This is never an UPGRADE fallback.
    pub fn upgradeListenerOnly(self: *LinuxServer, requester: ?*ConnState) !void {
        if (!setCloexec(self.rx().listener_fd, false)) return error.InvalidInheritedListener;
        const exe_target = self.config.exe_path orelse "/proc/self/exe";
        var plan = helix_live.buildListenerExecPlan(self.allocator, exe_target, self.rx().listener_fd, self.config.config_path) catch |e| {
            _ = setCloexec(self.rx().listener_fd, true);
            var eb: [96]u8 = undefined;
            self.upgradeNotice(requester, std.fmt.bufPrint(&eb, "UPGRADE failed (plan): {s}", .{@errorName(e)}) catch "UPGRADE failed");
            return;
        };
        defer plan.deinit(self.allocator);
        plan.commit(self.allocator) catch |e| {
            _ = setCloexec(self.rx().listener_fd, true);
            var eb: [96]u8 = undefined;
            self.upgradeNotice(requester, std.fmt.bufPrint(&eb, "UPGRADE failed (execve): {s}", .{@errorName(e)}) catch "UPGRADE failed");
            return;
        };
    }

    /// TRACE — oper-only: RPL_TRACEUSER (205) per connected client + RPL_ENDOFTRACE (262).
    pub fn handleTrace(self: *LinuxServer, conn: *ConnState) !void {
        return oper_cmd.handleTrace(self, conn);
    }

    /// `SESSIONS [filter]` (oper) — a filtered, sorted connection view rendered as
    /// RPL_TRACE* numerics. Richer than TRACE: filter tokens are `oper`/`user`,
    /// `tls`/`clear`, a bare nick glob, or `key=value` (account=, ip=, sort=, limit=
    /// …). Spans all reactor shards (read-only under the world lock).
    pub fn handleSessions(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleSessions(self, conn, parsed);
    }

    /// `ETRACE` (oper) — extended TRACE: one RPL_ETRACE (709) line per local
    /// registered user with class, nick, user, visible+real host, account, and
    /// real name; terminated by RPL_TRACEEND (262). Read-only.
    pub fn handleEtrace(self: *LinuxServer, conn: *ConnState) !void {
        return oper_cmd.handleEtrace(self, conn);
    }

    /// Map an EVENT category token (code or tag) to a daemon EventCategory.
    fn eventCategoryFromToken(token: []const u8) ?event_spine.EventCategory {
        inline for (@typeInfo(event_spine.EventCategory).@"enum".field_names) |field_name| {
            const c: event_spine.EventCategory = @field(event_spine.EventCategory, field_name);
            if (std.ascii.eqlIgnoreCase(token, c.code()) or std.ascii.eqlIgnoreCase(token, c.token())) return c;
        }
        // IRCX draft EVENT type aliases (CHANNEL/MEMBER/SERVER/CONNECTION/SOCKET/
        // USER) onto the Event-Spine taxonomy, mirroring ircx_event_cmd.draftAlias
        // so draft clients can scope `EVENT ADD CHANNEL #foo*` / `EVENT ADD USER
        // *!*@host` exactly as the pure parser documents.
        if (std.ascii.eqlIgnoreCase(token, "CHANNEL")) return .announce;
        if (std.ascii.eqlIgnoreCase(token, "MEMBER")) return .oper_action;
        if (std.ascii.eqlIgnoreCase(token, "SERVER")) return .server_link;
        if (std.ascii.eqlIgnoreCase(token, "CONNECTION")) return .connect;
        if (std.ascii.eqlIgnoreCase(token, "SOCKET")) return .disconnect;
        if (std.ascii.eqlIgnoreCase(token, "USER")) return .service;
        return null;
    }

    /// CONNECT <host> <port> — oper command: open an outbound server-to-server
    /// link to a peer. Creates a socket, stands up the outbound-side S2sLink, and
    /// submits an async io_uring connect; the handshake opens on connect completion.
    pub fn handleConnectCmd(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleConnectCmd(self, conn, parsed);
    }

    /// Open an outbound S2S link to `host:port`: resolve the address (IPv4
    /// literal or blocking DNS), create the socket + ConnState, stand up the
    /// outbound-side link (PQ-secured when `s2sSecured()`, else the plaintext
    /// handshake), and submit the async io_uring connect — the completion lands
    /// in `handleConnect`. Shared by the oper CONNECT command and the
    /// `[mesh].connect` auto-connect path; the new ConnState belongs to the
    /// calling reactor (same ownership as an inbound accept). Returns the new
    /// connection's token so callers can track the dial.
    pub fn initiateS2sConnect(self: *LinuxServer, host: []const u8, port: u16) !RingFdToken {
        const addr = try sockaddrForHost(host, port, 2_000);
        return self.initiateS2sConnectToAddr(addr);
    }

    /// Open an outbound S2S link to an already-resolved peer address. Shared by
    /// the oper CONNECT path (via `initiateS2sConnect`) and the post-UPGRADE
    /// re-dial of carried mesh links (the predecessor sealed the sockaddr).
    fn initiateS2sConnectToAddr(self: *LinuxServer, addr: posix.sockaddr.in6) !RingFdToken {
        if (self.rx().clients.len() >= self.config.max_clients) return error.SocketUnavailable;
        // [mesh].require_secured: never dial a plaintext outbound link. When secured
        // S2S is unavailable, refuse the dial rather than connecting in clear (the
        // secured path below is unaffected). Gated before any socket/slot alloc.
        if (self.config.require_secured and !self.s2sSecured()) {
            self.traceLog(.info, .s2s, "skipped plaintext S2S dial ([mesh].require_secured)");
            return error.SecuredS2sRequired;
        }
        // The logical dial/capsule address remains canonical in6. OpenBSD has
        // no mapped-v4 sockets: the backend translates that address for an
        // AF_INET socket before connect; real IPv6 uses AF_INET6 on both OSes.
        const fd = if (builtin.os.tag == .openbsd and isV4Mapped(addr.addr))
            try socketTcp()
        else
            try socketTcp6();
        errdefer closeFd(fd);
        const id = try self.rx().clients.alloc(ConnState.init(fd));
        errdefer _ = self.rx().clients.free(id);
        const peer = self.rx().clients.get(id).?;
        peer.overflow_allocator = self.allocator; // backs the SendQ overflow heap
        const configured_sendq = if (self.config.class_registry) |*reg|
            reg.classFor(.{ .is_server_link = true }).policy.sendq
        else
            peer.sendq_cap;
        peer.sendq_cap = s2sSendqCap(configured_sendq);
        peer.token = try tokenFromId(id);
        peer.s2s_connect_addr = addr;
        peer.s2s_dial_target_known = true;
        peer.s2s_initiator = true; // we dialed: this is the initiator side

        if (self.s2sSecured()) {
            // PQ-secured initiator: waits (await_prekey) for the responder's TOFU
            // preamble after the TCP connect completes — no output yet.
            const link = try self.newSecuredLink(.initiator);
            errdefer {
                link.deinit();
                self.allocator.destroy(link);
            }
            peer.s2s_secured = link;
            errdefer peer.s2s_secured = null;
            try self.armConnect(peer);
            // Outbound dial opens a TCP S2S slot (not yet Mooring-established).
            self.noteS2sTcpOpened(peer);
            return peer.token;
        }

        const link = try self.allocator.create(s2s_link.S2sLink);
        errdefer self.allocator.destroy(link);
        try link.init(.{
            .allocator = self.allocator,
            .local_node_id = self.config.node_id,
            .remote_node_id = 0,
            .local_epoch_ms = @intCast(@max(0, platform.realtimeMillis())),
            .server_name = self.serverName(),
            .config = self.config.s2s_config,
        });
        errdefer link.deinit();
        link.setLocalNickResolver(self.localNickResolver());
        link.setResidenceVerifier(self.residenceVerifier());
        link.setSessionTokenResolver(self.sessionTokenResolver());
        link.setSessionTokenNickAuthorizer(self.sessionTokenNickAuthorizer());
        peer.s2s = link;
        errdefer peer.s2s = null;

        try self.armConnect(peer);
        self.noteS2sTcpOpened(peer);
        return peer.token;
    }

    /// Dial every configured `[mesh].connect` peer whose outbound link is not
    /// up (boot pass + periodic re-dial from the sweep timer). Reactor-0 only:
    /// the dial table and every ConnState it creates belong to reactor 0, so no
    /// other shard ever touches them. `force` skips the re-dial rate cap (boot).
    /// A peer with a live dial (connect in flight or link established) is
    /// skipped, so attempts never pile up; a failed/closed dial frees its slot
    /// (generation mismatch on the saved token) and re-arms here.
    /// Drain a bounded number of post-UPGRADE hand-dial hints after this turn's
    /// control and inherited-socket SQEs. Returns true while work remains.
    fn activateInheritedMeshRedials(self: *LinuxServer, budget: usize) bool {
        if (self.rx() != &self.reactors[0] or budget == 0) return false;
        var attempted: usize = 0;
        while (self.inherited_mesh_redial_cursor < self.inherited_mesh_redials.items.len and attempted < budget) {
            const addr = self.inherited_mesh_redials.items[self.inherited_mesh_redial_cursor];
            if (self.initiateS2sConnectToAddr(addr)) |_| {
                self.inherited_mesh_redial_cursor += 1;
                attempted += 1;
            } else |err| switch (err) {
                error.SubmissionQueueFull => return true,
                else => {
                    srvLog("onyx-server: UPGRADE resume — mesh re-dial failed ({s})\n", .{@errorName(err)});
                    self.inherited_mesh_redial_cursor += 1;
                    attempted += 1;
                },
            }
        }
        if (self.inherited_mesh_redial_cursor == self.inherited_mesh_redials.items.len) {
            self.inherited_mesh_redials.clearRetainingCapacity();
            self.inherited_mesh_redial_cursor = 0;
            return false;
        }
        return true;
    }

    const MeshDialAttempt = enum { skipped, attempted, sq_full };

    /// Delay after `failures` handshake or stall failures. `failures == 1` is the
    /// first retry and yields the flat redial base; each further failure doubles
    /// it through `backoff.exponential`, clamped at 32× the base.
    fn meshBackoffDelayMs(failures: u32) i64 {
        const base: u64 = @intCast(mesh_redial_interval_ms);
        const attempt: u32 = if (failures == 0) 0 else failures - 1;
        return @intCast(backoff.exponential(base, 2, base * 32, attempt));
    }

    /// True while this dial must not open another TCP attempt. An open breaker
    /// waits out its cooldown even on the forced boot pass. Backoff applies to
    /// every pass. The healthy flat interval applies only to non-forced redials
    /// that have not failed.
    fn meshRedialWaiting(dial: *const MeshDial, now: i64, force: bool) bool {
        if (dial.breaker.state() == .open) {
            const opened: u64 = dial.breaker.opened_at_ms orelse 0;
            const now_u: u64 = @intCast(@max(now, 0));
            if (now_u -| opened < dial.breaker.config.cooldown_ms) return true;
        }
        if (dial.retry_not_before_ms != 0 and now < dial.retry_not_before_ms) return true;
        if (force) return false;
        if (dial.backoff_failures == 0 and dial.last_attempt_ms != 0 and now - dial.last_attempt_ms < mesh_redial_interval_ms) return true;
        return false;
    }

    fn publishMooringBreakerGauge(self: *LinuxServer) void {
        var open: i64 = 0;
        for (self.mesh_dials) |dial| {
            if (dial.breaker.state() == .open) open += 1;
        }
        self.stats.mooring_breakers_open.store(open, .release);
    }

    /// `allow` on an open breaker consumes the half-open probe before the dial
    /// runs. A local refusal (full submission queue, no client slot) is not a
    /// peer failure, so the probe is handed back and the breaker stays put.
    fn releaseMooringProbe(dial: *MeshDial, before: circuit_breaker.BreakerState) void {
        if (before == .open or before == .half_open) dial.breaker.half_open_in_flight -|= 1;
    }

    fn noteMeshDialFailure(self: *LinuxServer, dial: *MeshDial, reason: []const u8) void {
        const now_i = self.nowMs();
        const now_u: u64 = @intCast(@max(now_i, 0));
        const was_open = dial.breaker.state() == .open;
        dial.breaker.onFailure(now_u);
        dial.backoff_failures +|= 1;
        const delay = meshBackoffDelayMs(dial.backoff_failures);
        dial.retry_not_before_ms = if (now_i > std.math.maxInt(i64) - delay) std.math.maxInt(i64) else now_i + delay;
        if (!was_open and dial.breaker.state() == .open) {
            self.mooring_breaker_logs +|= 1;
            srvLog("onyx-server: mooring circuit open peer={s} after {s}\n", .{ dial.spec, reason });
        }
        self.publishMooringBreakerGauge();
    }

    fn noteMeshDialSuccess(self: *LinuxServer, dial: *MeshDial) void {
        if (dial.backoff_failures == 0 and dial.breaker.state() == .closed and dial.retry_not_before_ms == 0) return;
        dial.breaker.onSuccess();
        dial.backoff_failures = 0;
        dial.retry_not_before_ms = 0;
        self.publishMooringBreakerGauge();
    }

    fn meshDialForToken(self: *LinuxServer, token: RingFdToken) ?*MeshDial {
        for (self.mesh_dials) |*dial| {
            const tok = dial.token orelse continue;
            if (tok.slot == token.slot and tok.gen == token.gen) return dial;
        }
        return null;
    }

    fn meshDialForConn(self: *LinuxServer, conn: *const ConnState) ?*MeshDial {
        if (self.meshDialForToken(conn.token)) |dial| return dial;
        if (!conn.s2s_dial_target_known) return null;
        for (self.mesh_dials) |*dial| {
            const addr = dial.addr orelse continue;
            if (sameSockaddrIn(conn.s2s_connect_addr, addr)) return dial;
        }
        return null;
    }

    fn noteMeshConnectFailure(self: *LinuxServer, token: RingFdToken, reason: []const u8) void {
        const dial = self.meshDialForToken(token) orelse return;
        self.noteMeshDialFailure(dial, reason);
    }

    fn noteMeshDialSuccessByName(self: *LinuxServer, name: []const u8) void {
        if (name.len == 0) return;
        var it = self.reactors[0].clients.iterator();
        while (it.next()) |entry| {
            const conn = entry.value;
            const remote = activeMeshPeerName(conn) orelse continue;
            if (!std.ascii.eqlIgnoreCase(remote, name)) continue;
            if (self.meshDialForConn(conn)) |dial| self.noteMeshDialSuccess(dial);
        }
    }

    /// Handshake not finished, or anti-entropy quiet, long enough to count.
    fn mooringStallReason(self: *LinuxServer, conn: *const ConnState, now_u: u64) ?[]const u8 {
        if (!conn.meshAdmissionOpen()) return null;
        if (conn.s2s == null and conn.s2s_secured == null) return null;
        if (establishedPeerName(conn) == null) {
            const idle_from: u64 = @intCast(@max(conn.last_activity_ms, 0));
            if (now_u -| idle_from < mooring_stall_ms) return null;
            return "handshake stall";
        }
        const name = establishedPeerName(conn).?;
        const health = self.peer_health.get(name) orelse return null;
        if (health.since(now_u) < mooring_stall_ms) return null;
        const last = health.last_anti_entropy_ms orelse return "anti-entropy stall";
        if (now_u -| last < mooring_stall_ms) return null;
        return "anti-entropy stall";
    }

    /// One stall sample per dial per backoff window. An already-open breaker
    /// drops the stuck TCP slot instead of accepting another unsigned frame or
    /// extending the cooldown on every tick.
    fn sweepMooringStalls(self: *LinuxServer) void {
        if (!self.isMaintenanceReactor()) return;
        const now_u = self.nowU64();
        const now_i = self.nowMs();
        var closing: std.ArrayListUnmanaged(RingFdToken) = .empty;
        defer closing.deinit(self.allocator);
        var it = self.reactors[0].clients.iterator();
        while (it.next()) |entry| {
            const conn = entry.value;
            const reason = self.mooringStallReason(conn, now_u) orelse continue;
            const dial = self.meshDialForConn(conn) orelse continue;
            if (dial.breaker.state() == .open) {
                closing.append(self.allocator, conn.token) catch continue;
                continue;
            }
            if (dial.retry_not_before_ms != 0 and now_i < dial.retry_not_before_ms) continue;
            self.noteMeshDialFailure(dial, reason);
            if (dial.breaker.state() == .open) closing.append(self.allocator, conn.token) catch continue;
        }
        for (closing.items) |token| {
            const conn = self.connForToken(token) catch continue;
            const reason = self.mooringStallReason(conn, now_u) orelse "mooring circuit open";
            self.requestS2sClose(conn, reason);
        }
    }

    fn tryMeshAutoDial(self: *LinuxServer, dial: *MeshDial, force: bool, now: i64) MeshDialAttempt {
        if (dial.token) |tok| {
            if (self.rx().clients.get(idFromToken(tok))) |peer| {
                // Same slot AND same generation: our dial still owns it.
                if (peer.token.slot == tok.slot and peer.token.gen == tok.gen and !peer.closing) return .skipped;
            }
            dial.token = null; // dial's connection is gone — eligible again
        }
        if (meshRedialWaiting(dial, now, force)) return .skipped;
        // A fresh successor's dial table has no cached resolution yet, while an
        // inherited outbound link does retain its exact dial target. Resolve the
        // configured target before looking for that survivor; otherwise the boot
        // pass cannot match an IP-literal/DNS-alias config and opens a duplicate
        // connection beside the zero-drop inherited link.
        if (dial.addr == null) {
            dial.addr = sockaddrForHost(dial.host, dial.port, 2_000) catch |err| {
                dial.last_attempt_ms = now;
                srvLog("onyx-server: mesh auto-connect -> {s} failed ({s}); retrying\n", .{ dial.spec, @errorName(err) });
                return .attempted;
            };
        }
        // Already linked to this peer via the surviving (possibly inbound)
        // link? Don't dial a duplicate — that just loops collapse→redial.
        // A live link is not by itself a successful handshake or anti-entropy
        // round, so it does not close the breaker.
        if (self.meshPeerLinkedByDial(dial)) {
            dial.token = null;
            return .skipped;
        }
        if (meshRedialWaiting(dial, now, force)) return .skipped;

        const now_u: u64 = @intCast(@max(now, 0));
        const before = dial.breaker.state();
        if (!dial.breaker.allow(now_u)) return .skipped;
        if (before != dial.breaker.state()) self.publishMooringBreakerGauge();

        const prior_attempt_ms = dial.last_attempt_ms;
        dial.last_attempt_ms = now;
        const addr = dial.addr.?;
        if (self.initiateS2sConnectToAddr(addr)) |tok| {
            dial.token = tok;
            srvLog("onyx-server: mesh auto-connect -> {s} (dial initiated)\n", .{dial.spec});
            return .attempted;
        } else |err| switch (err) {
            error.SubmissionQueueFull => {
                releaseMooringProbe(dial, before);
                dial.last_attempt_ms = prior_attempt_ms;
                return .sq_full;
            },
            else => {
                releaseMooringProbe(dial, before);
                srvLog("onyx-server: mesh auto-connect -> {s} failed ({s}); retrying\n", .{ dial.spec, @errorName(err) });
                return .attempted;
            },
        }
    }

    fn sweepMeshAutoConnect(self: *LinuxServer, force: bool, budget: usize) bool {
        if (self.mesh_dials.len == 0) return true;
        if (!self.isMaintenanceReactor()) return true;
        if (budget == 0) return false;
        const now = self.nowMs();

        if (force) {
            if (self.mesh_boot_remaining == 0) self.mesh_boot_remaining = self.mesh_dials.len;
            var attempted: usize = 0;
            while (self.mesh_boot_remaining != 0) {
                const index = self.mesh_dial_cursor % self.mesh_dials.len;
                switch (self.tryMeshAutoDial(&self.mesh_dials[index], true, now)) {
                    .sq_full => return false, // retain cursor/current entry for retry
                    .skipped => {},
                    .attempted => attempted += 1,
                }
                self.mesh_dial_cursor = (index + 1) % self.mesh_dials.len;
                self.mesh_boot_remaining -= 1;
                if (attempted >= budget and self.mesh_boot_remaining != 0) return false;
            }
            return true;
        }

        // Periodic reconnects use the same rotating cursor, so one fast-failing
        // peer cannot monopolize the bounded maintenance budget either.
        const cursor_start = self.mesh_dial_cursor % self.mesh_dials.len;
        for (0..self.mesh_dials.len) |offset| {
            const index = (cursor_start + offset) % self.mesh_dials.len;
            switch (self.tryMeshAutoDial(&self.mesh_dials[index], false, now)) {
                .skipped => continue,
                .sq_full => {
                    self.mesh_dial_cursor = index;
                    return false;
                },
                .attempted => {
                    self.mesh_dial_cursor = (index + 1) % self.mesh_dials.len;
                    return false; // budget is currently one; preserve boundedness
                },
            }
        }
        return true;
    }

    /// SQUIT <server> [:reason] — oper command: tear down the S2S link to a peer
    /// identified by its (handshake-learned) server name.
    pub fn handleSquit(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleSquit(self, conn, parsed);
    }

    const SquitVictim = struct {
        id: client_model.ClientId,
        token: RingFdToken,
    };

    fn peerRemoteName(conn: *const ConnState) ?[]const u8 {
        if (conn.s2s_secured) |link| return link.remoteName();
        if (conn.s2s) |link| return link.remoteName();
        return null;
    }

    pub fn findSquitVictim(self: *LinuxServer, target: []const u8) ?SquitVictim {
        var it = self.reactors[0].clients.iterator();
        while (it.next()) |entry| {
            const remote = activeMeshPeerName(entry.value) orelse continue;
            if (std.ascii.eqlIgnoreCase(remote, target)) return .{ .id = entry.id, .token = entry.value.token };
        }
        // An oper may cancel an admitted named handshake, but a retained
        // retiring leg cannot shadow an established survivor or be revived.
        it = self.reactors[0].clients.iterator();
        while (it.next()) |entry| {
            if (!entry.value.meshAdmissionOpen() or entry.value.isActiveMeshPeer()) continue;
            const remote = peerRemoteName(entry.value) orelse continue;
            if (std.ascii.eqlIgnoreCase(remote, target)) return .{ .id = entry.id, .token = entry.value.token };
        }
        return null;
    }

    /// Send a server NOTICE to a single connection.
    pub fn noticeTo(self: *LinuxServer, conn: *ConnState, text: []const u8) !void {
        // CWE-93 (CRLF injection): `text` is reflected into a NOTICE line by many
        // callers that pass user-influenced content (WEBHOOK URLs, echoed params,
        // service messages). This builder bypasses the `ReplyCtx` control-byte
        // guard, so a raw CR/LF in `text` would smuggle a forged IRC line onto the
        // wire. Fail closed: drop the notice rather than inject. Legitimate
        // notices (all-printable) are byte-identical.
        if (dispatch.hasControlByte(text)) return;
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :{s}\r\n", .{ self.serverName(), conn.session.displayName(), text }) catch return;
        try emitReplyLine(conn, line);
    }

    /// Shard-safe server NOTICE for a connection that may be owned by another
    /// reactor. Session fields are read under World; completed bytes cross the
    /// fabric so a foreign SendQ and SINGLE_ISSUER ring remain owner-only.
    fn deliverNoticeTo(self: *LinuxServer, id: client_model.ClientId, conn: *const ConnState, text: []const u8) !void {
        if (dispatch.hasControlByte(text)) return;
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :{s}\r\n", .{ self.serverName(), conn.session.displayName(), text }) catch return;
        try self.enqueueDelivery(id, line);
    }

    /// Record a structured event into the flight recorder (+ category filter).
    /// Never faults the hot path.
    fn traceLog(self: *LinuxServer, comptime level: tracelog.Level, category: tracelog.Category, msg: []const u8) void {
        const now: u64 = @intCast(@max(0, self.nowMs()));
        tracelog.emit(.debug, level, &self.trace_filter, self.trace_recorder.sink(), category, now, 0, msg, &.{}) catch {};
    }

    fn bindFlightPanicTarget(self: *LinuxServer) void {
        flight_panic_server.store(@intFromPtr(self), .release);
    }

    fn clearFlightPanicTarget(self: *LinuxServer) void {
        _ = flight_panic_server.cmpxchgStrong(@intFromPtr(self), 0, .release, .monotonic);
    }

    /// Record `fault`, then replace the operator file with tracelog lines.
    /// An empty path does nothing. IO errors are swallowed so a dump cannot fault.
    fn flushFlightRecorder(self: *LinuxServer, category: tracelog.Category, fault: []const u8) void {
        const path = self.config.flight_recorder_path;
        if (path.len == 0) return;
        self.traceLog(.fatal, category, fault);
        if (path.len > flight_path_max) return;

        var path_buf: [flight_path_max + 1]u8 = undefined;
        @memcpy(path_buf[0..path.len], path);
        path_buf[path.len] = 0;
        const fd: linux.fd_t = if (builtin.os.tag == .openbsd or builtin.os.tag == .windows)
            os_runtime.openTruncateZ(path_buf[0..path.len :0], 0o600) catch return
        else blk: {
            const opened = linux.open(path_buf[0..path.len :0], .{
                .ACCMODE = .WRONLY,
                .CREAT = true,
                .TRUNC = true,
                .CLOEXEC = true,
            }, 0o600);
            if (linux.errno(opened) != .SUCCESS) return;
            break :blk @intCast(opened);
        };
        defer os_runtime.close(fd);

        // Same oldest-to-newest window as FlightRecorder.dump, one event at a
        // time, so the fault path does not stage the whole ring on the stack.
        const capacity = self.trace_recorder.events.len;
        const head = self.trace_recorder.head.load(.acquire);
        var tail = self.trace_recorder.tail.load(.acquire);
        if (head -% tail > capacity) tail = head - capacity;
        var written: usize = 0;
        var index = tail;
        while (index != head) : (index +%= 1) {
            const ev = self.trace_recorder.events[index % capacity];
            var fields: [tracelog.max_fields]tracelog.Field = undefined;
            var n: usize = 0;
            while (n < fields.len) : (n += 1) {
                fields[n] = ev.field(n) orelse break;
            }
            var line: [640]u8 = undefined;
            const rendered = tracelog.render(.{
                .level = ev.level,
                .category = ev.category,
                .ts_mono_ns = ev.ts_mono_ns,
                .hlc = ev.hlc,
                .msg = ev.message(),
                .fields = fields[0..n],
            }, &line) catch continue;
            if (written + rendered.len + 1 > flight_recorder_max_file_bytes) break;
            if (!writeAllNative(fd, rendered)) return;
            if (!writeAllNative(fd, "\n")) return;
            written += rendered.len + 1;
        }
    }

    /// DEBUG — oper command: dump the flight recorder (last N structured events)
    /// to the operator as notices. The "heavy debugging" entry point.
    pub fn handleDebug(self: *LinuxServer, conn: *ConnState) !void {
        return oper_cmd.handleDebug(self, conn);
    }

    /// TESTLINE <mask> — oper tool: report the first K/D-line whose mask matches
    /// `mask` (RPL_TESTLINE 725) or RPL_NOTESTLINE 726 if none.
    pub fn handleTestline(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleTestline(self, conn, parsed);
    }

    /// TESTMASK <mask> — oper tool: count connected clients whose nick!user@host
    /// matches `mask` (RPL_TESTMASK 727).
    pub fn handleTestmask(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleTestmask(self, conn, parsed);
    }

    /// MODEX <#chan[,nick]> [+/-NAMED...] — IRCX named-mode front-end. Translates
    /// named modes (AUTHONLY/OWNER/…) to mode letters and delegates to the regular
    /// MODE engine (which gates + broadcasts). A bare MODEX queries active modes
    /// (RPL_MODEXLIST 826 + RPL_MODEXEND 827).
    pub fn handleModex(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        var changes_buf: [ircx_modex.DEFAULT_MAX_CHANGES]ircx_modex.ModeChange = undefined;
        const req = ircx_modex.parseParams(parsed.paramSlice(), &changes_buf) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"MODEX"}, "Invalid MODEX");
            return;
        };
        const channel = req.target.channel;
        if (!self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        if (req.changes.len == 0) {
            // Query: collect active mode letters (base + IRCX-extended) as names.
            const ctx = ircx_modex.ReplyContext{ .server_name = self.serverName(), .requester = conn.session.displayName() };
            var names: [32][]const u8 = undefined;
            var nn: usize = 0;
            var flags_buf: [16]u8 = undefined;
            const base = self.world.channelModeString(channel, &flags_buf);
            var ext_buf: [32]u8 = undefined;
            const ext = chanmode_ext.renderModes(self.world.channelExtModes(channel), &ext_buf) catch ext_buf[0..0];
            for ([_][]const u8{ base, ext }) |letters| {
                for (letters) |c| {
                    if (c == '+' or c == '-') continue;
                    if (ircx_modex.letterToName(c)) |name| {
                        if (nn < names.len) {
                            names[nn] = name;
                            nn += 1;
                        }
                    } else |_| {}
                }
            }
            var lbuf: [default_reply_bytes]u8 = undefined;
            if (ircx_modex.writeModexList(&lbuf, ctx, channel, names[0..nn])) |line| {
                try appendToConn(conn, line);
            } else |_| {}
            var ebuf: [default_reply_bytes]u8 = undefined;
            if (ircx_modex.writeModexEnd(&ebuf, ctx, channel)) |line| {
                try appendToConn(conn, line);
            } else |_| {}
            return;
        }
        var has_named_ext = false;
        for (req.changes) |chg| {
            if (modexDirectExtFlag(chg) != null) {
                has_named_ext = true;
                break;
            }
        }
        var direct_applied_buf: [64]u8 = undefined;
        var direct_applied = Buf{ .storage = &direct_applied_buf };
        var direct_sign: u8 = 0;
        if (has_named_ext) {
            const active_override = overrideActive(conn);
            const setter_opt = self.world.memberModes(channel, worldIdFromClient(id));
            if (setter_opt == null and !active_override) {
                try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{channel}, "You're not on that channel");
                return;
            }
            const setter = setter_opt orelse world_model.MemberModes.empty();
            if (!setter.isOperator() and !active_override) {
                try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{channel}, "You're not channel operator");
                return;
            }
            const override_modex_bypass = active_override and !setter.isOperator();
            for (req.changes) |chg| {
                const flag = modexDirectExtFlag(chg) orelse continue;
                if (chanmode_ext.requiresOper(flag) and !conn.session.isOper()) {
                    try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "That channel mode is operator-only");
                    continue;
                }
                const on = chg.op == .add;
                const changed = self.world.setChannelExtFlag(channel, flag, on) catch continue;
                if (changed) appendModeLetter(&direct_applied, &direct_sign, chg.op.sign(), chg.letter.?);
            }
            if (direct_applied.written().len != 0) {
                var prefix_buf: [256]u8 = undefined;
                var line_buf: [default_reply_bytes]u8 = undefined;
                const msg = try formatMessage(&line_buf, try clientPrefix(conn, &prefix_buf), "MODE", &.{ channel, direct_applied.written() }, null);
                try self.broadcastChannel(channel, msg, null);
                self.announceChannelModeState(channel);
                if (override_modex_bypass) self.auditOverrideUse(conn, "MODEX", channel, "changed named channel mode without normal channel authority");
            }
        }
        // Set: synthesize equivalent MODE letters for the non-direct cases and
        // delegate (reuses all gating, tier rules, and broadcast). Member-mode
        // nicks become positional params, appended in the same order as their
        // letters so handleMode aligns them.
        var synth = irc_line.LineView{ .raw = "", .command = "MODE" };
        synth.params[0] = channel;
        synth.param_count = 1;
        var ms_buf: [128]u8 = undefined;
        var ms = Buf{ .storage = &ms_buf };
        for (req.changes) |chg| {
            if (modexDirectExtFlag(chg) != null) continue;
            if (chg.letter) |letter| {
                ms.appendByte(chg.op.sign()) catch break;
                ms.appendByte(letter) catch break;
            }
        }
        if (ms.written().len == 0) return;
        synth.params[1] = ms.written();
        synth.param_count = 2;
        for (req.changes) |chg| {
            if (modexDirectExtFlag(chg) != null) continue;
            if (chg.letter == null) continue;
            if (chg.param) |p| {
                if (synth.param_count < synth.params.len) {
                    synth.params[synth.param_count] = p;
                    synth.param_count += 1;
                }
            }
        }
        try self.handleMode(id, conn, &synth);
    }

    /// EVENT ADD|CHANGE|DELETE|CLEAR|LIST — IRCX EVENT subscription control.
    /// Opers manage IRCX CHANNEL/MEMBER/USER subscriptions with
    /// per-type subject masks; delivery maps those IRCX types onto Event Spine
    /// categories while replies stay on the IRCX numeric surface.
    pub fn handleEvent(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const params = parsed.paramSlice();
        const is_oper = conn.session.isOper();
        // Operators retain the full Event Spine command (gated by the
        // `event_subscribe` privilege). Ordinary clients may LIST/ADD/CHANGE/
        // DELETE/CLEAR the channel-scoped types CHANNEL, MEMBER, and MEDIA.
        // USER, category feeds, BROADCAST, and OBSERVE stay operator-only.
        // Delivery of CHANNEL, MEMBER, and MEDIA still requires membership.
        if (is_oper and !self.requirePriv(conn, .event_subscribe)) return;
        // EVENT BROADCAST :<message> — send an oper announce (the former WALLOPS,
        // now folded into the Event Spine): delivered as a chatsvc `:<srv> EVENT
        // <oper> <message>` line to every announce-subscribed operator.
        if (params.len > 0 and std.ascii.eqlIgnoreCase(params[0], "BROADCAST")) {
            if (!is_oper) {
                try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied; EVENT BROADCAST is for operators");
                return;
            }
            if (params.len < 2 or params[1].len == 0) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"EVENT"}, "Not enough parameters");
                return;
            }
            var subj_buf: [256]u8 = undefined;
            const subject = try clientPrefix(conn, &subj_buf);
            var msg_buf: [512]u8 = undefined;
            const message = std.fmt.bufPrint(&msg_buf, "{s}: {s}", .{ subject, params[1] }) catch params[1];
            try self.publishOperEvent(.announce, .notice, message);
            return;
        }
        // EVENT OBSERVE <mask> [actions…] | OFF | LIST — a standing operator
        // observation subscription. Unlike a one-shot spy dump, this records the
        // operator's interest mask and pushes a live `EVENT <oper> OBSERVE …` feed
        // of matching client lifecycle events (with real hosts); subscribing also
        // emits an immediate snapshot of the currently-matching population.
        if (params.len > 0 and std.ascii.eqlIgnoreCase(params[0], "OBSERVE")) {
            if (!is_oper) {
                try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied; EVENT OBSERVE is for operators");
                return;
            }
            try self.handleObserve(conn, params);
            return;
        }

        if (params.len == 0 or std.ascii.eqlIgnoreCase(params[0], "LIST")) {
            const filter: ?event_spine.IrcxEventType = if (params.len >= 2) blk: {
                break :blk event_spine.IrcxEventType.parse(params[1]) orelse {
                    try queueNumeric(conn, .ERR_NOSUCHEVENT, &.{params[1]}, "No such event");
                    return;
                };
            } else null;

            // draft-pfenning-04: RPL_EVENTSTART (808) opens the list, one
            // RPL_EVENTLIST (809) per subscribed event, RPL_EVENTEND (810) closes.
            try queueNumeric(conn, .RPL_EVENTSTART, &.{}, "Start of event list");
            for (event_spine.ircx_event_types) |typ| {
                if (filter) |wanted| {
                    if (wanted != typ) continue;
                }
                if (!conn.session.subscribesToIrcxEvent(typ)) continue;
                try queueNumeric(conn, .RPL_EVENTLIST, &.{ typ.wireName(), conn.session.ircxEventSubjectMask(typ) }, "Event subscription");
            }
            try queueNumeric(conn, .RPL_EVENTEND, &.{}, "End of event list");
            // Opers also see their Event Spine category subscriptions + severity
            // floor (the KILL/FLOOD/… plane, separate from the IRCX list above).
            if (is_oper) try self.replyEventCategories(conn, conn.session.event_mask);
            return;
        }

        if (std.ascii.eqlIgnoreCase(params[0], "SEVERITY")) {
            return self.handleEventSeverity(conn, is_oper, params);
        }

        if (std.ascii.eqlIgnoreCase(params[0], "REPLAY")) {
            return self.handleEventReplay(conn, is_oper, params);
        }

        if (std.ascii.eqlIgnoreCase(params[0], "STATS")) {
            return self.handleEventStats(conn, is_oper, params);
        }

        if (std.ascii.eqlIgnoreCase(params[0], "ADD")) {
            if (params.len < 2) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"EVENT ADD"}, "Not enough parameters");
                return;
            }
            // IRCX plane (CHANNEL/MEMBER/USER/MEDIA) first; a token that is not an
            // IRCX type falls through to the Event Spine CATEGORY plane below.
            if (event_spine.IrcxEventType.parse(params[1])) |typ| {
                if (!clientIrcxTypeAllowed(is_oper, typ)) {
                    try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied; USER events are for operators");
                    return;
                }
                if (conn.session.subscribesToIrcxEvent(typ)) {
                    try queueNumeric(conn, .ERR_EVENTDUP, &.{params[1]}, "Event already subscribed");
                    return;
                }
                const mask = if (params.len >= 3 and params[2].len != 0) params[2] else "*";
                conn.session.setIrcxEventSubscription(typ, mask) catch {
                    try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"EVENT ADD"}, "EVENT subject mask too long");
                    return;
                };
                // IRCX EVENT lives on its own subscription plane (token-routed by
                // type); it deliberately does NOT pollute the legacy oper category
                // mask, so a USER subscriber receives only USER events.
                try queueNumeric(conn, .RPL_EVENTADD, &.{ params[1], conn.session.ircxEventSubjectMask(typ) }, "Event added");
                return;
            }
            return self.handleEventCategoryOp(conn, is_oper, .add, params[1..]);
        }

        if (std.ascii.eqlIgnoreCase(params[0], "CHANGE")) {
            if (params.len < 2) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"EVENT CHANGE"}, "Not enough parameters");
                return;
            }
            const typ = event_spine.IrcxEventType.parse(params[1]) orelse {
                try queueNumeric(conn, .ERR_NOSUCHEVENT, &.{params[1]}, "No such event");
                return;
            };
            if (!is_oper and typ != .media) {
                try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied; only MEDIA events are client-subscribable");
                return;
            }
            if (!conn.session.subscribesToIrcxEvent(typ)) {
                try queueNumeric(conn, .ERR_EVENTMIS, &.{params[1]}, "Not subscribed to event");
                return;
            }
            const mask = if (params.len >= 3 and params[2].len != 0) params[2] else "*";
            conn.session.setIrcxEventSubscription(typ, mask) catch {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"EVENT CHANGE"}, "EVENT subject mask too long");
                return;
            };
            try queueNumeric(conn, .RPL_EVENTCHANGE, &.{ params[1], conn.session.ircxEventSubjectMask(typ) }, "Event updated");
            return;
        }

        if (std.ascii.eqlIgnoreCase(params[0], "DELETE") or std.ascii.eqlIgnoreCase(params[0], "DEL")) {
            if (params.len < 2) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"EVENT DELETE"}, "Not enough parameters");
                return;
            }
            if (event_spine.IrcxEventType.parse(params[1])) |typ| {
                if (!clientIrcxTypeAllowed(is_oper, typ)) {
                    try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied; USER events are for operators");
                    return;
                }
                if (!conn.session.clearIrcxEventSubscription(typ)) {
                    try queueNumeric(conn, .ERR_EVENTMIS, &.{params[1]}, "Not subscribed to event");
                    return;
                }
                try queueNumeric(conn, .RPL_EVENTDELETE, &.{params[1]}, "Event removed");
                return;
            }
            return self.handleEventCategoryOp(conn, is_oper, .del, params[1..]);
        }

        if (std.ascii.eqlIgnoreCase(params[0], "CLEAR")) {
            if (params.len >= 2) {
                const typ = event_spine.IrcxEventType.parse(params[1]) orelse {
                    try queueNumeric(conn, .ERR_NOSUCHEVENT, &.{params[1]}, "No such event");
                    return;
                };
                if (!conn.session.clearIrcxEventSubscription(typ)) {
                    try queueNumeric(conn, .ERR_EVENTMIS, &.{params[1]}, "Not subscribed to event");
                    return;
                }
                try queueNumeric(conn, .RPL_EVENTDELETE, &.{params[1]}, "Event removed");
            } else {
                conn.session.clearIrcxEventSubscriptions();
                // Also drop the Event Spine category subscriptions + severity floor.
                conn.session.setEventMask(event_spine.CategoryMask.empty());
                conn.session.clearEventSubjectMasks();
                conn.session.setEventMinSeverity(.debug);
                try self.noticeTo(conn, "All event subscriptions cleared");
            }
            return;
        }

        var notice_buf: [256]u8 = undefined;
        const notice = std.fmt.bufPrint(&notice_buf, "Unknown EVENT subcommand '{s}'. Usage: EVENT ADD|DEL|CLEAR|LIST|SEVERITY|REPLAY|STATS <CHANNEL|MEMBER|USER|MEDIA | category | ALL> [mask]", .{params[0]}) catch "Unknown EVENT subcommand";
        try self.noticeTo(conn, notice);
    }

    /// Live Event Spine CATEGORY subscription (oper-only): toggle bits on the
    /// session's category mask for the KILL/FLOOD/SECURITY/… taxonomy — the plane
    /// that was previously settable ONLY via `[[opers]] presubscribe` config.
    /// `EVENT ADD|DEL <cat...>`; "ALL" resolves to every category. Distinct from
    /// the token-routed IRCX plane (handled by the caller for known IRCX types).
    fn handleEventCategoryOp(self: *LinuxServer, conn: *ConnState, is_oper: bool, op: enum { add, del }, tokens: []const []const u8) !void {
        if (!is_oper) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied; category events are for operators");
            return;
        }
        if (tokens.len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"EVENT"}, "Not enough parameters");
            return;
        }
        var delta = event_spine.CategoryMask.empty();
        for (tokens) |tok| {
            if (std.ascii.eqlIgnoreCase(tok, "ALL")) {
                delta = delta.include(event_spine.CategoryMask.all());
                continue;
            }
            const cat = event_spine.EventCategory.parse(tok) orelse {
                try queueNumeric(conn, .ERR_NOSUCHEVENT, &.{tok}, "No such event category");
                return;
            };
            delta.add(cat);
        }
        const cur = conn.session.event_mask;
        const next = switch (op) {
            .add => cur.include(delta),
            .del => cur.exclude(delta),
        };
        conn.session.setEventMask(next);
        try self.replyEventCategories(conn, next);
    }

    /// `EVENT SEVERITY [level]` (oper-only): set — or, with no arg, report — the
    /// minimum Event Spine severity delivered to this session's category feed.
    fn handleEventSeverity(self: *LinuxServer, conn: *ConnState, is_oper: bool, params: []const []const u8) !void {
        if (!is_oper) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied; EVENT SEVERITY is for operators");
            return;
        }
        if (params.len < 2 or params[1].len == 0) {
            var b: [96]u8 = undefined;
            try self.noticeTo(conn, std.fmt.bufPrint(&b, "Event minimum severity: {s} (debug|info|notice|warn|error|critical)", .{conn.session.eventMinSeverity().token()}) catch "Event minimum severity");
            return;
        }
        const sev = event_spine.EventSeverity.parse(params[1]) orelse {
            try self.noticeTo(conn, "Unknown severity; use debug|info|notice|warn|error|critical");
            return;
        };
        conn.session.setEventMinSeverity(sev);
        var b: [96]u8 = undefined;
        try self.noticeTo(conn, std.fmt.bufPrint(&b, "Event minimum severity set to {s}", .{sev.token()}) catch "Event minimum severity set");
    }

    /// `EVENT REPLAY [JSON] [category|ALL] [count]` (oper-only): re-send recent
    /// Event Spine events from the node-wide history ring — what happened before
    /// this oper connected/subscribed. Filtered by the optional category and the
    /// session's minimum-severity floor; delivered oldest→newest as NOTICEs with
    /// either a relative-age prefix or bounded JSON records for operator UIs.
    fn handleEventReplay(self: *LinuxServer, conn: *ConnState, is_oper: bool, params: []const []const u8) !void {
        if (!is_oper) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied; EVENT REPLAY is for operators");
            return;
        }
        var filter_cat: ?u8 = null;
        var count: usize = 30;
        var argi: usize = 1;
        var json = false;
        if (params.len > argi and std.ascii.eqlIgnoreCase(params[argi], "JSON")) {
            json = true;
            argi += 1;
        }
        // A leading non-numeric arg is a category (or ALL); then an optional count.
        if (params.len > argi and params[argi].len != 0 and !isAsciiDigits(params[argi])) {
            if (!std.ascii.eqlIgnoreCase(params[argi], "ALL")) {
                filter_cat = @intFromEnum(event_spine.EventCategory.parse(params[argi]) orelse {
                    try queueNumeric(conn, .ERR_NOSUCHEVENT, &.{params[argi]}, "No such event category");
                    return;
                });
            }
            argi += 1;
        }
        if (params.len > argi and isAsciiDigits(params[argi])) {
            count = std.fmt.parseInt(usize, params[argi], 10) catch 30;
        }
        count = std.math.clamp(count, 1, 200);

        var buf: [200]event_history_mod.StoredEvent = undefined;
        const got = self.event_history.collect(filter_cat, @intFromEnum(conn.session.eventMinSeverity()), buf[0..count]);

        if (json) {
            var hb: [160]u8 = undefined;
            try self.noticeTo(conn, std.fmt.bufPrint(&hb, "{{\"type\":\"event-replay\",\"count\":{d},\"severity_floor\":\"{s}\"}}", .{
                got,
                conn.session.eventMinSeverity().token(),
            }) catch "{\"type\":\"event-replay\"}");
            var i = got;
            while (i > 0) {
                i -= 1;
                self.noticeEventReplayJson(conn, &buf[i]) catch continue;
            }
            var eb: [96]u8 = undefined;
            try self.noticeTo(conn, std.fmt.bufPrint(&eb, "{{\"type\":\"event-replay-end\",\"count\":{d}}}", .{got}) catch "{\"type\":\"event-replay-end\"}");
            return;
        }

        var hb: [96]u8 = undefined;
        try self.noticeTo(conn, std.fmt.bufPrint(&hb, "Event replay: {d} event(s){s}", .{ got, if (got == 0) " (history empty or nothing matched)" else "" }) catch "Event replay");
        const now = platform.realtimeMillis();
        // `collect` returned newest-first; walk backwards to render chronologically.
        var i = got;
        while (i > 0) {
            i -= 1;
            const ev = &buf[i];
            const cat = ev.categoryEnum() orelse continue;
            var age_buf: [16]u8 = undefined;
            const age = formatRelativeAge(&age_buf, now - ev.ts_unix_ms);
            var line_buf: [default_reply_bytes]u8 = undefined;
            const text = std.fmt.bufPrint(&line_buf, "[{s} ago] {s}/{s} <{s}> {s}", .{
                age, cat.code(), ev.severityEnum().token(), ev.origin(), ev.message(),
            }) catch continue;
            try self.noticeTo(conn, text);
        }
        if (got != 0) try self.noticeTo(conn, "End of event replay.");
    }

    fn noticeEventReplayJson(self: *LinuxServer, conn: *ConnState, ev: *const event_history_mod.StoredEvent) !void {
        const cat = ev.categoryEnum() orelse return;
        const sev = ev.severityEnum();
        var line_buf: [default_reply_bytes]u8 = undefined;
        var w = std.Io.Writer.fixed(&line_buf);
        try w.print("{{\"type\":\"event\",\"ts\":{d},\"category\":", .{ev.ts_unix_ms});
        try writeJsonEscaped(&w, cat.token());
        try w.writeAll(",\"category_code\":");
        try writeJsonEscaped(&w, cat.code());
        try w.writeAll(",\"severity\":");
        try writeJsonEscaped(&w, sev.token());
        try w.writeAll(",\"origin\":");
        try writeJsonEscaped(&w, ev.origin());
        try w.writeAll(",\"message\":");
        try writeJsonEscaped(&w, ev.message());
        try w.writeByte('}');
        try self.noticeTo(conn, w.buffered());
    }

    /// Render the machine-readable operator UI form of `EVENT STATS`.
    fn writeEventStatsJson(self: *LinuxServer, w: *std.Io.Writer) !void {
        try w.print("{{\"total\":{d},\"history_depth\":{d},\"categories\":{{", .{ self.event_stats.totalCount(), self.event_history.len() });
        var first = true;
        inline for (@typeInfo(event_spine.EventCategory).@"enum".field_names) |field_name| {
            const cat: event_spine.EventCategory = @field(event_spine.EventCategory, field_name);
            if (!first) try w.writeAll(",");
            first = false;
            try w.print("\"{s}\":{d}", .{ cat.token(), self.event_stats.categoryCount(@intFromEnum(cat)) });
        }
        try w.writeAll("},\"severities\":{");
        first = true;
        inline for (@typeInfo(event_spine.EventSeverity).@"enum".field_names) |field_name| {
            const sev: event_spine.EventSeverity = @field(event_spine.EventSeverity, field_name);
            if (!first) try w.writeAll(",");
            first = false;
            try w.print("\"{s}\":{d}", .{ sev.token(), self.event_stats.severityCount(@intFromEnum(sev)) });
        }
        try w.writeAll(
            "},\"operator_surfaces\":{" ++
                "\"event_replay_json\":true," ++
                "\"event_stats_json\":true," ++
                "\"audit_event_spine\":true," ++
                "\"audit_json\":true," ++
                "\"audit_proof_json\":true," ++
                "\"proofmark\":true," ++
                "\"admission_security_events\":true," ++
                "\"security_reputation_events\":true," ++
                "\"security_throttle_events\":true," ++
                "\"security_clone_events\":true" ++
                "}",
        );
        try w.writeAll("}}");
    }

    /// `EVENT STATS [JSON]` (oper-only): per-category + per-severity Event Spine
    /// event counts since boot, plus the total and the live history-ring depth.
    fn handleEventStats(self: *LinuxServer, conn: *ConnState, is_oper: bool, params: []const []const u8) !void {
        if (!is_oper) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied; EVENT STATS is for operators");
            return;
        }
        if (params.len >= 2 and std.ascii.eqlIgnoreCase(params[1], "JSON")) {
            var buf: [1024]u8 = undefined;
            var w = std.Io.Writer.fixed(&buf);
            try self.writeEventStatsJson(&w);
            try self.noticeTo(conn, w.buffered());
            return;
        }
        var hb: [96]u8 = undefined;
        try self.noticeTo(conn, std.fmt.bufPrint(&hb, "Event stats since boot: {d} total, {d} in history ring", .{ self.event_stats.totalCount(), self.event_history.len() }) catch "Event stats");
        // Per-category line (skip zero-count categories to stay compact).
        {
            var buf: [640]u8 = undefined;
            var w = std.Io.Writer.fixed(&buf);
            w.writeAll("  by category:") catch {};
            var any = false;
            inline for (@typeInfo(event_spine.EventCategory).@"enum".field_names) |field_name| {
                const cat: event_spine.EventCategory = @field(event_spine.EventCategory, field_name);
                const n = self.event_stats.categoryCount(@intFromEnum(cat));
                if (n != 0) {
                    var nb: [40]u8 = undefined;
                    w.writeAll(std.fmt.bufPrint(&nb, " {s}={d}", .{ cat.code(), n }) catch "") catch {};
                    any = true;
                }
            }
            if (!any) w.writeAll(" (none yet)") catch {};
            try self.noticeTo(conn, w.buffered());
        }
        // Per-severity line.
        {
            var buf: [320]u8 = undefined;
            var w = std.Io.Writer.fixed(&buf);
            w.writeAll("  by severity:") catch {};
            inline for (@typeInfo(event_spine.EventSeverity).@"enum".field_names) |field_name| {
                const sev: event_spine.EventSeverity = @field(event_spine.EventSeverity, field_name);
                const n = self.event_stats.severityCount(@intFromEnum(sev));
                if (n != 0) {
                    var nb: [40]u8 = undefined;
                    w.writeAll(std.fmt.bufPrint(&nb, " {s}={d}", .{ sev.token(), n }) catch "") catch {};
                }
            }
            try self.noticeTo(conn, w.buffered());
        }
    }

    /// NOTICE the session's current Event Spine category subscriptions + severity.
    fn replyEventCategories(self: *LinuxServer, conn: *ConnState, mask: event_spine.CategoryMask) !void {
        var buf: [512]u8 = undefined;
        var w = std.Io.Writer.fixed(&buf);
        w.writeAll("Event categories:") catch {};
        if (mask.isEmpty()) {
            w.writeAll(" (none)") catch {};
        } else {
            inline for (@typeInfo(event_spine.EventCategory).@"enum".field_names) |field_name| {
                const cat: event_spine.EventCategory = @field(event_spine.EventCategory, field_name);
                if (mask.contains(cat)) {
                    w.writeAll(" ") catch {};
                    w.writeAll(cat.code()) catch {};
                }
            }
        }
        var sb: [48]u8 = undefined;
        const sev_note = std.fmt.bufPrint(&sb, " (min severity: {s})", .{conn.session.eventMinSeverity().token()}) catch "";
        w.writeAll(sev_note) catch {};
        try self.noticeTo(conn, w.buffered());
    }

    /// Stable observer key for a connection (bitcast ClientId, matching the
    /// monitor/session keying convention).
    fn observeKey(conn: *const ConnState) u64 {
        return monitorIdFromClient(idFromToken(conn.token));
    }

    /// Build an OBSERVE subject from a live connection. `host` is the REAL host —
    /// observation is an operator-trust surface, so it deliberately bypasses the
    /// cloak applied to ordinary visibility.
    fn observeSubject(conn: *const ConnState, detail: []const u8) observe_mod.Subject {
        return .{
            .nick = conn.session.displayName(),
            .user = conn.session.username(),
            .host = conn.session.realHost(),
            .account = conn.session.account(),
            .detail = detail,
        };
    }

    fn publishChannelEvent(self: *LinuxServer, action: []const u8, channel: []const u8) !void {
        var msg_buf: [256]u8 = undefined;
        const message = std.fmt.bufPrint(&msg_buf, "CHANNEL {s} {s}", .{ action, channel }) catch return error.OutputTooSmall;
        try self.publishOperEventSubject(.announce, .notice, message, channel);
    }

    /// CHANNEL event carrying a trailing detail token (e.g. the applied mode
    /// string for MODE, or the new name for RENAME): `"CHANNEL <action> <chan>
    /// <detail>"`. Subject stays the channel so CHANNEL subscribers' channel-glob
    /// masks match. An empty detail degrades to the bare channel form.
    fn publishChannelEventDetail(self: *LinuxServer, action: []const u8, channel: []const u8, detail: []const u8) !void {
        if (detail.len == 0) return self.publishChannelEvent(action, channel);
        var msg_buf: [512]u8 = undefined;
        const message = std.fmt.bufPrint(&msg_buf, "CHANNEL {s} {s} {s}", .{ action, channel, detail }) catch return error.OutputTooSmall;
        try self.publishOperEventSubject(.announce, .notice, message, channel);
    }

    fn publishMemberEvent(self: *LinuxServer, action: []const u8, channel: []const u8, nick: []const u8, detail: ?[]const u8) !void {
        var msg_buf: [512]u8 = undefined;
        const message = if (detail) |text|
            std.fmt.bufPrint(&msg_buf, "MEMBER {s} {s} {s} :{s}", .{ action, channel, nick, text }) catch return error.OutputTooSmall
        else
            std.fmt.bufPrint(&msg_buf, "MEMBER {s} {s} {s}", .{ action, channel, nick }) catch return error.OutputTooSmall;
        try self.publishOperEventSubject(.oper_action, .notice, message, channel);
    }

    /// Publish a MEDIA (voice/video) presence/state transition as a first-class
    /// IRCX EVENT: `"MEDIA <action> <channel> <nick> [detail]"`. Routes through the
    /// Event Spine — local subscribers across all shards + every mesh peer — so
    /// call presence converges network-wide (the old local-only media notice
    /// broadcast did not). Subject is the channel so MEDIA subscribers' channel-glob
    /// masks match; delivery to a NON-oper additionally requires channel membership
    /// (see `mediaEventAllowed`), preserving member-only visibility.
    pub fn publishMediaEvent(self: *LinuxServer, action: []const u8, channel: []const u8, nick: []const u8, detail: []const u8) !void {
        // E2EE key-exchange envelopes are still bounded by the IRC/Event Spine
        // line ceiling, but can legitimately exceed the old presence-only
        // scratch size. The server relays these opaque tokens; it never parses
        // or stores the enclosed key material.
        var msg_buf: [event_spine.max_event_line_len]u8 = undefined;
        const message = if (detail.len != 0)
            std.fmt.bufPrint(&msg_buf, "MEDIA {s} {s} {s} {s}", .{ action, channel, nick, detail }) catch return error.OutputTooSmall
        else
            std.fmt.bufPrint(&msg_buf, "MEDIA {s} {s} {s}", .{ action, channel, nick }) catch return error.OutputTooSmall;
        try self.publishOperEventSubject(.service, .notice, message, channel);
    }

    const media_e2ee_p256_public_bytes: usize = 65;
    pub const media_e2ee_attachment_bytes: usize = 16;
    const media_e2ee_handshake_unsigned_bytes: usize = 211;
    pub const media_e2ee_handshake_v2_bytes: usize = 275;
    const media_e2ee_handshake_domain = "onyx-media-handshake-v2\x00";
    pub const media_e2ee_max_wrapped_key_bytes: usize = 512;
    pub const media_e2ee_max_base64_bytes: usize = std.base64.standard.Encoder.calcSize(media_e2ee_max_wrapped_key_bytes);

    /// Validate canonical padded RFC 4648 base64 without interpreting the
    /// decoded cryptographic payload. Decoding into fixed stack storage proves
    /// both the alphabet/padding and decoded-size bounds; re-encoding rejects
    /// alternate/non-canonical encodings of the same bytes.
    pub fn validMediaE2eeBase64(encoded: []const u8, min_decoded: usize, max_decoded: usize) bool {
        if (encoded.len == 0 or encoded.len > media_e2ee_max_base64_bytes or encoded.len % 4 != 0) return false;
        const decoded_len = std.base64.standard.Decoder.calcSizeForSlice(encoded) catch return false;
        if (decoded_len < min_decoded or decoded_len > max_decoded) return false;

        var decoded: [media_e2ee_max_wrapped_key_bytes]u8 = undefined;
        std.base64.standard.Decoder.decode(decoded[0..decoded_len], encoded) catch return false;
        var canonical: [media_e2ee_max_base64_bytes]u8 = undefined;
        const canonical_len = std.base64.standard.Encoder.calcSize(decoded_len);
        const reencoded = std.base64.standard.Encoder.encode(canonical[0..canonical_len], decoded[0..decoded_len]);
        return std.mem.eql(u8, encoded, reencoded);
    }

    /// Validate the signed-v2 handshake envelope's immutable framing while
    /// leaving its cryptographic contents opaque to the relay. Return the stable
    /// physical attachment id so subsequent GROUPKEY authorship can be bound to
    /// this exact authenticated connection.
    pub fn mediaE2eeHandshakeAttachment(encoded: []const u8) ?[media_e2ee_attachment_bytes]u8 {
        if (!validMediaE2eeBase64(encoded, media_e2ee_handshake_v2_bytes, media_e2ee_handshake_v2_bytes)) return null;
        var envelope: [media_e2ee_handshake_v2_bytes]u8 = undefined;
        std.base64.standard.Decoder.decode(&envelope, encoded) catch return null;
        if (envelope[0] != 2 or envelope[17] != 0x04 or envelope[82] != 0x04) return null;
        const attachment: [media_e2ee_attachment_bytes]u8 = envelope[1..17].*;
        _ = sessions_mod.AttachmentId.fromBytes(attachment) catch return null;
        return attachment;
    }

    fn mediaE2eeHandshakeTranscript(
        channel: []const u8,
        unsigned: []const u8,
        out: *[media_e2ee_handshake_domain.len + client_model.MAX_CHANNEL_NAME_BYTES + 1 + media_e2ee_handshake_unsigned_bytes]u8,
    ) ?[]const u8 {
        if (channel.len == 0 or channel.len > client_model.MAX_CHANNEL_NAME_BYTES or
            unsigned.len != media_e2ee_handshake_unsigned_bytes) return null;
        var offset: usize = 0;
        @memcpy(out[offset..][0..media_e2ee_handshake_domain.len], media_e2ee_handshake_domain);
        offset += media_e2ee_handshake_domain.len;
        for (channel) |byte| {
            out[offset] = std.ascii.toLower(byte);
            offset += 1;
        }
        out[offset] = 0;
        offset += 1;
        @memcpy(out[offset..][0..unsigned.len], unsigned);
        offset += unsigned.len;
        return out[0..offset];
    }

    pub fn mediaE2eeHandshakeSignatureValid(channel: []const u8, envelope: *const [media_e2ee_handshake_v2_bytes]u8) bool {
        const Ed25519 = std.crypto.sign.Ed25519;
        const public_bytes: [Ed25519.PublicKey.encoded_length]u8 = envelope[179..211].*;
        const public_key = Ed25519.PublicKey.fromBytes(public_bytes) catch return false;
        const signature_bytes: [Ed25519.Signature.encoded_length]u8 = envelope[media_e2ee_handshake_unsigned_bytes..media_e2ee_handshake_v2_bytes].*;
        const signature = Ed25519.Signature.fromBytes(signature_bytes);
        var transcript_buf: [media_e2ee_handshake_domain.len + client_model.MAX_CHANNEL_NAME_BYTES + 1 + media_e2ee_handshake_unsigned_bytes]u8 = undefined;
        const transcript = mediaE2eeHandshakeTranscript(channel, envelope[0..media_e2ee_handshake_unsigned_bytes], &transcript_buf) orelse return false;
        signature.verifyStrict(transcript, public_key) catch return false;
        return true;
    }

    pub fn mediaE2eeAttachmentToken(token: []const u8) ?[media_e2ee_attachment_bytes]u8 {
        if (token.len != base64url.encodedLen(media_e2ee_attachment_bytes)) return null;
        var raw: [media_e2ee_attachment_bytes]u8 = undefined;
        const decoded = base64url.decode(&raw, token) catch return null;
        if (decoded.len != raw.len) return null;
        var canonical_buf: [base64url.encodedLen(media_e2ee_attachment_bytes)]u8 = undefined;
        const canonical = base64url.encode(&canonical_buf, &raw) catch return null;
        if (!std.mem.eql(u8, canonical, token)) return null;
        _ = sessions_mod.AttachmentId.fromBytes(raw) catch return null;
        return raw;
    }

    pub fn accountHasMediaIdentityKey(self: *LinuxServer, account: []const u8, public_key: [account_identity.public_key_len]u8) bool {
        const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
        var views: [ircx_prop_store.default_max_props_per_entity]ircx_prop_store.EntryView = undefined;
        const rows = self.props.listProps(entity, &views) catch return false;
        for (rows) |row| {
            if (!account_identity.isPropKey(row.key)) continue;
            const claim = account_identity.parseClaimValue(row.value) orelse continue;
            if (std.crypto.timing_safe.eql([account_identity.public_key_len]u8, claim.public_key, public_key)) return true;
        }
        return false;
    }

    /// Epochs are opaque client ratchet coordinates, but their wire form is
    /// canonical and bounded: unsigned decimal u64, no sign or leading zeroes.
    pub fn validMediaE2eeEpoch(epoch: []const u8) bool {
        if (epoch.len == 0 or epoch.len > 20) return false;
        if (epoch.len > 1 and epoch[0] == '0') return false;
        for (epoch) |ch| if (!std.ascii.isDigit(ch)) return false;
        _ = std.fmt.parseInt(u64, epoch, 10) catch return false;
        return true;
    }

    /// Render a caller-only MEDIA response in Event Spine wire form. Transport
    /// credentials and MAC keys are intentionally targeted to the requesting
    /// session instead of published to all MEDIA subscribers.
    pub fn sendMediaEventReply(self: *LinuxServer, conn: *ConnState, action: []const u8, channel: []const u8, detail: []const u8) !void {
        var line_buf: [event_spine.max_event_line_len]u8 = undefined;
        defer std.crypto.secureZero(u8, &line_buf);
        try appendToConn(conn, try self.renderMediaEventReply(conn, action, channel, detail, &line_buf));
    }

    /// Caller-owned rendering only. A capability candidate retains these exact
    /// issuer bytes until protected output and authority can publish together.
    fn renderMediaEventReply(self: *LinuxServer, conn: *const ConnState, action: []const u8, channel: []const u8, detail: []const u8, line_buf: []u8) ![]const u8 {
        var msg_buf: [event_spine.max_event_line_len]u8 = undefined;
        defer std.crypto.secureZero(u8, &msg_buf);
        const message = if (detail.len != 0)
            std.fmt.bufPrint(&msg_buf, "MEDIA {s} {s} {s}", .{ action, channel, detail }) catch return error.OutputTooSmall
        else
            std.fmt.bufPrint(&msg_buf, "MEDIA {s} {s}", .{ action, channel }) catch return error.OutputTooSmall;

        var tag_buf: [128]u8 = undefined;
        const tags = if (conn.session.hasCap(.message_tags))
            event_spine.buildEventTags(&tag_buf, .service, .notice) catch ""
        else
            "";
        return event_spine.renderEventTagged(tags, self.serverName(), conn.session.displayName(), message, line_buf) catch return error.OutputTooSmall;
    }

    /// CHANNEL, MEMBER, and MEDIA bodies put the channel in the third token.
    fn mediaEventChannel(message: []const u8) ?[]const u8 {
        var it = std.mem.tokenizeScalar(u8, message, ' ');
        _ = it.next() orelse return null;
        _ = it.next() orelse return null;
        return it.next();
    }

    /// A non-oper may subscribe to channel-scoped IRCX types. USER names every
    /// connect, so it stays an operator feed.
    fn clientIrcxTypeAllowed(is_oper: bool, typ: event_spine.IrcxEventType) bool {
        if (is_oper) return true;
        return typ == .channel or typ == .member or typ == .media;
    }

    /// Whether `message` may be delivered to the recipient identified by `id` /
    /// `session`. CHANNEL, MEMBER, and MEDIA are channel-scoped: a non-oper must
    /// be a member of the event's channel. USER and every oper pass here.
    fn mediaEventAllowed(self: *LinuxServer, id: client_model.ClientId, session: *const dispatch.ClientSession, message: []const u8) bool {
        const typ = event_spine.IrcxEventType.fromMessage(message) orelse return true;
        if (typ != .channel and typ != .member and typ != .media) return true;
        if (session.isOper()) return true;
        const chan = mediaEventChannel(message) orelse return false;
        return self.world.isMember(chan, worldIdFromClient(id));
    }

    fn userEventSubject(conn: *const ConnState, storage: []u8) ServerError![]const u8 {
        const real_host = conn.session.realHost();
        const host = if (real_host.len == 0) default_host else real_host;
        return std.fmt.bufPrint(storage, "{s}!{s}@{s}", .{ conn.session.displayName(), conn.session.username(), host }) catch return error.OutputTooSmall;
    }

    fn publishUserConnectEvent(self: *LinuxServer, conn: *const ConnState) !void {
        var subject_buf: [256]u8 = undefined;
        const subject = try userEventSubject(conn, &subject_buf);
        var msg_buf: [320]u8 = undefined;
        const message = std.fmt.bufPrint(&msg_buf, "USER CONNECT {s}", .{subject}) catch return error.OutputTooSmall;
        try self.publishOperEventSubject(.connect, .notice, message, subject);
    }

    fn publishUserDisconnectEvent(self: *LinuxServer, conn: *const ConnState, reason: []const u8) !void {
        var subject_buf: [256]u8 = undefined;
        const subject = try userEventSubject(conn, &subject_buf);
        var msg_buf: [512]u8 = undefined;
        const message = std.fmt.bufPrint(&msg_buf, "USER DISCONNECT {s} :{s}", .{ subject, reason }) catch return error.OutputTooSmall;
        try self.publishOperEventSubject(.disconnect, .notice, message, subject);
    }

    fn publishUserNickEvent(self: *LinuxServer, old_prefix: []const u8, newnick: []const u8) !void {
        var msg_buf: [384]u8 = undefined;
        const message = std.fmt.bufPrint(&msg_buf, "USER NICK {s} -> {s}", .{ old_prefix, newnick }) catch return error.OutputTooSmall;
        try self.publishOperEventSubject(.oper_action, .notice, message, old_prefix);
    }

    /// Generic USER administrative-lifecycle event (e.g. OPER): `"USER <action>
    /// <subject> [:detail]"`. Published under OPER_ACTION so legacy oper
    /// subscribers see operator-status transitions, while IRCX USER subscribers
    /// receive it via leading-token routing. An empty detail omits the trailer.
    fn publishUserEvent(self: *LinuxServer, conn: *const ConnState, action: []const u8, detail: []const u8) !void {
        var subject_buf: [256]u8 = undefined;
        const subject = try userEventSubject(conn, &subject_buf);
        var msg_buf: [512]u8 = undefined;
        const message = if (detail.len != 0)
            std.fmt.bufPrint(&msg_buf, "USER {s} {s} :{s}", .{ action, subject, detail }) catch return error.OutputTooSmall
        else
            std.fmt.bufPrint(&msg_buf, "USER {s} {s}", .{ action, subject }) catch return error.OutputTooSmall;
        try self.publishOperEventSubject(.oper_action, .notice, message, subject);
    }

    fn willChannelDestroyOnPart(self: *LinuxServer, channel: []const u8) bool {
        return self.world.memberCount(channel) == 1 and !self.world.channelHasExtFlag(channel, .registered);
    }

    fn publishChannelDestroyEventsForClient(self: *LinuxServer, id: client_model.ClientId) void {
        const wid = worldIdFromClient(id);
        var it = self.world.channels.iterator();
        while (it.next()) |entry| {
            if (!entry.value_ptr.members.contains(wid)) continue;
            if (entry.value_ptr.members.count() != 1) continue;
            if (entry.value_ptr.ext_modes.has(.registered)) continue;
            self.publishChannelEvent("DESTROY", entry.key_ptr.*) catch {};
        }
    }

    /// Push a live OBSERVE record to every operator whose standing filter matches
    /// the subject for this action. Best-effort; delivery failures are ignored.
    /// Publish a lifecycle OBSERVE record: deliver to THIS node's watching opers
    /// (across ALL shards) AND fan it to every mesh peer so a standing
    /// `EVENT OBSERVE <mask>` matches network-wide. Mirror of the Event-Spine
    /// publish split (`publishOperEventSubject`).
    fn notifyObservers(self: *LinuxServer, action: observe_mod.Action, subject: observe_mod.Subject) void {
        self.deliverObserveLocal(self.serverName(), action, subject);
        self.meshBroadcastObserveEvent(action, subject);
    }

    fn truncObserve(s: []const u8, max: usize) []const u8 {
        return if (s.len > max) s[0..max] else s;
    }

    /// Deliver one OBSERVE record to this node's watching opers across ALL shards,
    /// rendered `:<origin_server> EVENT <oper> OBSERVE …` (origin = this server for
    /// a local event, or the raising peer for a mesh-drained one). Pure local
    /// fan-out; never touches the wire.
    /// Push an OBSERVE line to watchers homed on THIS reactor only (no cross-shard
    /// fan). Shared by the local-publish path and the cross-shard receive
    /// (`deliverObserveFromWire`), so the receiving shard never re-fans (loop-safe).
    fn deliverObserveToReactor(self: *LinuxServer, origin_server: []const u8, action: observe_mod.Action, subject: observe_mod.Subject) void {
        if (self.observe.count() == 0) return;
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            if (!entry.value.session.isOper()) continue;
            const filter = self.observe.get(observeKey(entry.value)) orelse continue;
            if (!observe_mod.Registry.matches(filter, subject, action)) continue;
            var buf: [default_reply_bytes]u8 = undefined;
            const line = observe_mod.Registry.formatEvent(&buf, origin_server, entry.value.session.displayName(), action, subject) orelse continue;
            self.deliver(entry.id, line) catch {};
        }
    }

    const ObserveDecoded = struct { origin: []const u8, action: observe_mod.Action, subject: observe_mod.Subject };

    /// Decode an observe_event payload into an origin + action + structured
    /// subject, rejecting an action `u8` that is not a defined `observe_mod.Action`
    /// variant (a hostile peer could send any value). Borrows `bytes`.
    fn decodeObserveEvent(bytes: []const u8) ?ObserveDecoded {
        const ev = observe_event.decode(bytes) catch return null;
        var action_opt: ?observe_mod.Action = null;
        inline for (@typeInfo(observe_mod.Action).@"enum".field_values) |f_value| {
            if (f_value == ev.action) action_opt = @enumFromInt(ev.action);
        }
        const action = action_opt orelse return null;
        return .{ .origin = ev.origin_server, .action = action, .subject = .{
            .nick = ev.nick,
            .user = ev.user,
            .host = ev.host,
            .account = ev.account,
            .detail = ev.detail,
        } };
    }

    /// Decode a cross-shard-handed observe_event payload and deliver it to THIS
    /// reactor's watchers (no re-fan — the publishing shard already addressed every
    /// other shard).
    fn deliverObserveFromWire(self: *LinuxServer, bytes: []const u8) void {
        const d = decodeObserveEvent(bytes) orelse return;
        self.deliverObserveToReactor(d.origin, d.action, d.subject);
    }

    /// A shard-wide OBSERVE handoff is one logical delivery per matching watcher.
    /// If the shared fabric record cannot be admitted, publish the ordering gap to
    /// those exact live generations instead of silently leaving them connected
    /// after they missed a record. Non-matching clients on the shard are untouched.
    fn poisonObserveSubscribersOnShard(
        self: *LinuxServer,
        shard: u12,
        action: observe_mod.Action,
        subject: observe_mod.Subject,
    ) void {
        if (shard >= self.reactors.len) return;
        var it = self.reactors[shard].clients.iterator();
        while (it.next()) |entry| {
            const conn = entry.value;
            if (conn.closing or !conn.session.isOper()) continue;
            // `observeKey(conn)` reconstructs the shard from `current_reactor`
            // and is therefore valid only for owner-local iteration. This path
            // deliberately scans a FOREIGN shard after a failed shared handoff;
            // use the iterator's exact generational id so poison cannot miss or
            // select a same-slot observer on the publishing shard.
            const filter = self.observe.get(monitorIdFromClient(entry.id)) orelse continue;
            if (!observe_mod.Registry.matches(filter, subject, action)) continue;
            _ = self.poisonDeliveryGeneration(entry.id);
        }
    }

    fn deliverObserveLocal(self: *LinuxServer, origin_server: []const u8, action: observe_mod.Action, subject: observe_mod.Subject) void {
        // Watchers homed on THIS reactor.
        self.deliverObserveToReactor(origin_server, action, subject);
        // Cross-shard: watchers on OTHER reactors are not in this reactor's client
        // table. Encode the event once and hand it to each other shard's inbox; that
        // reactor decodes (`drainFabric`) and matches its own watchers. The fabric is
        // null for a single-shard daemon, so this is a no-op there.
        if (self.fabric) |*fabric| {
            var enc: [observe_event.max_encoded_len]u8 = undefined;
            const wire = observe_event.encode(.{
                .action = @intFromEnum(action),
                .origin_server = truncObserve(origin_server, observe_event.max_origin_len),
                .nick = truncObserve(subject.nick, observe_event.max_nick_len),
                .user = truncObserve(subject.user, observe_event.max_user_len),
                .host = truncObserve(subject.host, observe_event.max_host_len),
                .account = if (subject.account) |a| truncObserve(a, observe_event.max_account_len) else null,
                .detail = truncObserve(subject.detail, observe_event.max_detail_len),
            }, &enc) catch return;
            const my_shard = self.rx().shard_id;
            const total: u12 = @intCast(fabric.numShards());
            var shard: u12 = 0;
            while (shard < total) : (shard += 1) {
                if (shard == my_shard) continue;
                const buf = fabric.acquire(shard, wire) orelse {
                    self.poisonObserveSubscribersOnShard(shard, action, subject);
                    self.noteCrossShardDrop(fabric, 1);
                    continue;
                };
                const fan = reactor_fabric.DeliverMsg{
                    .to = client_model.ClientId.invalid,
                    .buf = buf,
                    .broadcast_observe = true,
                };
                if (fabric.sendTo(shard, fan)) {
                    self.wakeShard(shard);
                } else {
                    fabric.release(shard, buf);
                    self.poisonObserveSubscribersOnShard(shard, action, subject);
                    self.noteCrossShardDrop(fabric, 1);
                }
            }
        }
    }

    /// Fan a locally-raised OBSERVE record to every established mesh peer as a
    /// signed OBSERVE_EVENT carrying our server name as the origin. Best-effort; a
    /// send failure to one peer never blocks the others or the local delivery.
    /// Unconditional like the Event-Spine fan-out — the fired actions (connect,
    /// quit, nick, oper-up) are session-lifecycle, the same low volume the
    /// `.connect`/`.disconnect` Event-Spine categories already broadcast.
    fn meshBroadcastObserveEvent(self: *LinuxServer, action: observe_mod.Action, subject: observe_mod.Subject) void {
        const act: u8 = @intFromEnum(action);
        const origin = self.serverName();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    link.sendObserveEvent(act, origin, subject.nick, subject.user, subject.host, subject.account, subject.detail) catch continue;
                    if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendObserveEvent(act, origin, subject.nick, subject.user, subject.host, subject.account, subject.detail) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    /// Decode a peer's inbound OBSERVE_EVENT payloads and deliver each to this
    /// node's watching opers (all shards), rendered with the ORIGIN server the
    /// event carries (NOT this node). Never re-broadcast — a peer already fanned it
    /// to every node directly. An action value that is not a defined
    /// `observe_mod.Action` variant (a hostile peer could send any `u8`) is skipped.
    fn drainObserveEvents(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const payloads = link.takeObserveEvents() catch return;
        defer {
            for (payloads) |p| self.allocator.free(p);
            self.allocator.free(payloads);
        }
        for (payloads) |p| {
            const d = decodeObserveEvent(p) orelse continue;
            // Mesh-drained: deliver to THIS node's watchers across all shards
            // (reactor 0 owns the link; fan to the rest). Never re-broadcast.
            // Origin is the authenticated peer, not the spoofable wire field.
            self.deliverObserveLocal(trustedOrigin(link, d.origin), d.action, d.subject);
        }
    }

    /// `EVENT OBSERVE <mask> [actions…] | OFF | LIST` — manage the caller's
    /// observation subscription. Oper-gated by the EVENT command itself.
    pub fn handleObserve(self: *LinuxServer, conn: *ConnState, params: []const []const u8) !void {
        const key = observeKey(conn);
        if (params.len < 2 or params[1].len == 0 or std.ascii.eqlIgnoreCase(params[1], "LIST")) {
            if (self.observe.get(key)) |f| {
                try self.noticeTo(conn, "OBSERVE: active");
                var lbuf: [default_reply_bytes]u8 = undefined;
                if (std.fmt.bufPrint(&lbuf, ":{s} EVENT {s} OBSERVE filter {s}\r\n", .{ self.serverName(), conn.session.displayName(), f.mask })) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
            } else {
                try self.noticeTo(conn, "OBSERVE: no active subscription (EVENT OBSERVE <mask>)");
            }
            return;
        }
        if (std.ascii.eqlIgnoreCase(params[1], "OFF")) {
            _ = self.observe.clear(key);
            try self.noticeTo(conn, "OBSERVE: subscription cleared");
            return;
        }
        // Optional trailing action tokens narrow the subscription; default = all.
        var actions: u16 = 0;
        for (params[2..]) |tok| {
            if (observe_mod.Action.parse(tok)) |a| actions |= a.bit();
        }
        self.observe.set(key, params[1], actions, self.nowMs()) catch {
            try self.noticeTo(conn, "OBSERVE: could not set subscription (mask too long or too many observers)");
            return;
        };
        var hbuf: [default_reply_bytes]u8 = undefined;
        if (std.fmt.bufPrint(&hbuf, ":{s} EVENT {s} OBSERVE watching {s}\r\n", .{ self.serverName(), conn.session.displayName(), params[1] })) |line| {
            try appendToConn(conn, line);
        } else |_| {}
        // Immediate snapshot: enumerate the currently-matching population so the
        // operator gets present state, not only future transitions.
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            if (!entry.value.session.registered()) continue;
            const subj = observeSubject(entry.value, "present");
            var hm: [512]u8 = undefined;
            const mask_str = std.fmt.bufPrint(&hm, "{s}!{s}@{s}", .{ subj.nick, subj.user, subj.host }) catch continue;
            if (!observe_mod.globMatch(params[1], mask_str)) continue;
            var lbuf: [default_reply_bytes]u8 = undefined;
            if (std.fmt.bufPrint(&lbuf, ":{s} EVENT {s} OBSERVE present {s}!{s}@{s} acct={s}\r\n", .{ self.serverName(), conn.session.displayName(), subj.nick, subj.user, subj.host, subj.account orelse "*" })) |line| {
                try appendToConn(conn, line);
            } else |_| {}
        }
        try self.noticeTo(conn, "OBSERVE: end of snapshot");
    }

    /// Whether `conn` may view/manage the IRCX ACCESS list of `channel`: opers or
    /// channel-operators only (access masks are operator-sensitive).
    fn accessCanManage(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, level: ?ircx_access_store.Level) bool {
        if (conn.session.isOper()) return true;
        const mm = self.world.memberModes(channel, worldIdFromClient(id)) orelse return false;
        // FOUNDER entries are founder-only; OWNER entries owner-or-founder; op
        // suffices for HOST/VOICE/GRANT/DENY (IRCX ACCESS write rule).
        if (level) |lv| {
            if (lv == .founder) return mm.contains(.founder);
            if (lv == .owner) return mm.contains(.owner) or mm.contains(.founder);
        }
        return mm.isOperator();
    }

    fn accessOverrideWouldBypass(self: *LinuxServer, id: client_model.ClientId, channel: []const u8, level: ?ircx_access_store.Level) bool {
        const mm = self.world.memberModes(channel, worldIdFromClient(id)) orelse return true;
        if (level) |lv| {
            if (lv == .founder) return !mm.contains(.founder);
            if (lv == .owner) return !(mm.contains(.owner) or mm.contains(.founder));
        }
        return !mm.isOperator();
    }

    /// Enforce the Warden registry against a freshly registered client. The
    /// client presents its identity facets (address/host/mask/account/realname/
    /// certfp); the first matching Ward decides the outcome by its Action:
    ///   * refuse/expel       → ERROR + close (the network-ban / AKILL role)
    ///   * require_auth        → close unless authenticated to an account
    ///   * quarantine          → admitted but restricted (network silence / SHUN)
    /// Opers are never warded off. Returns true if the connection was closed.
    /// The active Ward matching this connection's live identity facets, or null.
    /// Builds the subject's facets (address / host / mask / account / realname /
    /// certfp / GeoIP country+asn) exactly as the registration-time checkpoint
    /// does, checks them against the registry on the WALL clock, and — on a miss —
    /// re-checks the key-derived host/mask facets recomputed under the PREVIOUS
    /// cloak key so bans survive a key rotation for a grace window. Shared by the
    /// registration-time `enforceWard` and the live sweep `reapWardMatches`, so a
    /// ward matches identically whether the subject is connecting now or already
    /// connected. Pure read of session fields — safe under `world.lockWrite`.
    fn wardMatch(self: *LinuxServer, conn: *ConnState) ?*const warden.Ward {
        var mask_buf: [256]u8 = undefined;
        const mask = clientPrefix(conn, &mask_buf) catch "";
        // GeoIP country + ASN facets (e.g. `WARD ADD country RU ...` /
        // `WARD ADD asn 15169 ...`). Resolved only when a database is configured;
        // empty facets never match a ward.
        var country: []const u8 = "";
        var asn_buf: [16]u8 = undefined;
        var asn_str: []const u8 = "";
        if (parseGeoIp(conn.session.realHost())) |gip| {
            if (self.ensureGeoip()) |db| {
                if (db.lookupInfo(gip) catch null) |gi| {
                    country = gi.country_iso orelse "";
                    if (gi.asn) |asn| asn_str = std.fmt.bufPrint(&asn_buf, "{d}", .{asn}) catch "";
                }
            }
        }
        const facets = warden.Facets{
            .address = conn.session.realHost(),
            .host = conn.session.host(),
            .mask = mask,
            .account = conn.session.account(),
            .realname = conn.session.realname(),
            .certfp = conn.session.tls_certfp orelse "",
            .country = country,
            .asn = asn_str,
        };
        // Wards are stamped + expire on the WALL clock (addWardLive /
        // applyRemoteWard use realtimeMillis, matching the WARD/TESTLINE oper
        // commands). nowMs() is MONOTONIC (per-boot uptime); checking expiry
        // against it would leave a wall-epoch expires_ms always in the "future"
        // → a temporary ward would never expire for new connections.
        const now_wall = platform.realtimeMillis();
        return self.warden.check(facets, now_wall) orelse blk: {
            // Rotatable cloak key: bans written against the PREVIOUS key's cloak
            // still reference old host/mask tokens. Re-check the host + mask facets
            // recomputed under the previous key so those bans survive a rotation
            // for a grace window. Only the key-derived facets differ; address /
            // account / country / asn / certfp / realname are key-independent.
            var prev_host_buf: [cloak.max_cloak_len]u8 = undefined;
            const prev_host = self.prevKeyCloakHost(conn, &prev_host_buf) orelse return null;
            var prev_mask_buf: [256]u8 = undefined;
            const prev_mask = std.fmt.bufPrint(&prev_mask_buf, "{s}!{s}@{s}", .{
                conn.session.displayName(),
                conn.session.username(),
                prev_host,
            }) catch "";
            var alt = facets;
            alt.host = prev_host;
            alt.mask = prev_mask;
            break :blk self.warden.check(alt, now_wall) orelse return null;
        };
    }

    fn subjectHitsMeshFilter(self: *const LinuxServer, conn: *const ConnState) bool {
        const filter = self.mesh_ban_filter orelse return false;
        const fields = [_]struct { match: warden.Match, value: []const u8 }{
            .{ .match = .address, .value = conn.session.realHost() },
            .{ .match = .host, .value = conn.session.host() },
            .{ .match = .account, .value = conn.session.account() orelse "" },
            .{ .match = .realname, .value = conn.session.realname() },
            .{ .match = .certfp, .value = conn.session.tls_certfp orelse "" },
        };
        for (fields) |field| {
            if (field.value.len == 0) continue;
            if (filter.mayContain(field.match, field.value)) return true;
        }
        return false;
    }

    fn enforceWard(self: *LinuxServer, conn: *ConnState) bool {
        if (conn.session.isOper()) return false;
        const hit = self.wardMatch(conn);
        if (hit == null and self.subjectHitsMeshFilter(conn)) {
            // The filter said this subject may be banned. The registry does
            // not agree, so this is a false positive and not a refusal.
            self.mesh_ban_filter_rechecks +|= 1;
            return false;
        }
        const listed = hit orelse return false;
        if (listed.scope == .mesh) {
            const filter_ptr: ?*const warden.MeshBanFilter = if (self.mesh_ban_filter) |*f| f else null;
            switch (warden.decideMeshBan(filter_ptr, &self.warden, listed.match, listed.pattern, platform.realtimeMillis())) {
                .false_positive => {
                    self.mesh_ban_filter_rechecks +|= 1;
                    return false;
                },
                .absent, .confirmed => {},
            }
        }

        switch (listed.action) {
            .quarantine => {
                // Admitted but restricted: no JOIN, no PRIVMSG/NOTICE. Enforced
                // at the JOIN and message gates via session.isRestricted().
                conn.session.setRestricted(true);
                return false;
            },
            .require_auth => {
                // Authenticated subjects pass; everyone else is refused.
                if (conn.session.account() != null) return false;
                return self.closeWarded(conn, listed.reason);
            },
            .refuse, .expel => return self.closeWarded(conn, listed.reason),
        }
    }

    /// Publish a SECURITY-category Event Spine event (`.warn`) describing a
    /// connection-refusing enforcement, so opers subscribed to SECURITY (and the
    /// EVENT REPLAY history) see WARD/DNSBL/auth blocks in real time. Best-effort.
    fn publishSecurityBlock(self: *LinuxServer, conn: *const ConnState, comptime what: []const u8, detail: []const u8) void {
        var pbuf: [256]u8 = undefined;
        const prefix = clientPrefix(conn, &pbuf) catch conn.session.displayName();
        var mbuf: [640]u8 = undefined;
        const msg = std.fmt.bufPrint(&mbuf, what ++ " refused {s} ({s})", .{ prefix, detail }) catch return;
        self.publishOperEvent(.security, .warn, msg) catch {};
    }

    /// Emit a Warden close ERROR and mark the connection for teardown.
    fn closeWarded(self: *LinuxServer, conn: *ConnState, reason: []const u8) bool {
        var eb: [640]u8 = undefined;
        const el = std.fmt.bufPrint(&eb, ":{s} ERROR :Closing Link: {s} (Banned: {s})\r\n", .{ protocol_inventory.currentServerName(), conn.session.displayName(), reason }) catch null;
        if (el) |line| appendToConn(conn, line) catch {};
        self.publishSecurityBlock(conn, "WARD", reason);
        conn.close_reason = "Banned (WARD)";
        conn.closing = true;
        self.armSendIfNeeded(conn) catch {};
        return true;
    }

    /// Sweep every live, registered, non-oper client session against the active
    /// Warden registry and apply the first matching ward's action IMMEDIATELY, so
    /// a ward added locally (`addWardLive`) or propagated from the mesh
    /// (`applyRemoteWard`) acts on already-connected abusers instead of only
    /// refusing their next reconnect — a network ban must bite during a live raid,
    /// not one reconnect later. Oper sessions and S2S links are exempt (opers are
    /// never restricted; a link is not a subject). Matching reuses `wardMatch`, so
    /// the sweep and the registration checkpoint agree exactly (facets + previous-
    /// cloak-key fallback).
    ///
    /// Runs under `world.lockWrite` (both call sites — the WARD command dispatch
    /// and the mesh-WARD drain — execute inside `onCompletion`, which holds it), so
    /// the cross-reactor session reads are race-free and no other reactor mutates a
    /// session concurrently. The close path (`reapClose` → `enqueueDeliveryThenClose`)
    /// only marks the connection `closing` (local) or hands off through the fabric
    /// (foreign); it NEVER frees a slot the way `closeConn` does, so applying it
    /// inline while iterating `clients.slots` cannot invalidate the iteration.
    fn reapWardMatches(self: *LinuxServer) void {
        if (self.warden.count() == 0) return;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                // S2S links share the slab but are not ban subjects.
                if (conn.s2s != null or conn.s2s_secured != null) continue;
                if (conn.closing) continue;
                // Pre-registration clients present no facets yet — they face the
                // ward at their own registration checkpoint (`enforceWard`).
                if (!conn.session.registered()) continue;
                if (conn.session.isOper()) continue; // opers are exempt
                const hit = self.wardMatch(conn) orelse continue;
                const id = slotClientId(reactor, i, slot.gen);
                switch (hit.action) {
                    // Restrict in place: no JOIN, no PRIVMSG/NOTICE (enforced at the
                    // join/message gates via isRestricted). A plain field write, no
                    // teardown — slot-safe.
                    .quarantine => conn.session.setRestricted(true),
                    // Authenticated subjects pass; everyone else is expelled.
                    .require_auth => {
                        if (conn.session.account() != null) continue;
                        self.reapClose(conn, id, hit.reason);
                    },
                    .refuse, .expel => self.reapClose(conn, id, hit.reason),
                }
            }
        }
    }

    /// Expel a live client matched by a newly-active ward, mirroring the
    /// registration `closeWarded` wire shape
    /// (`:server ERROR :Closing Link: <name> (Banned: <reason>)`). Routed through
    /// `enqueueDeliveryThenClose` so it is correct for a client on THIS reactor
    /// (append + arm + mark closing) AND one on ANOTHER shard (fabric handoff +
    /// wake) — and, unlike `closeConn`, it defers teardown, so it never frees the
    /// slot being iterated.
    fn reapClose(self: *LinuxServer, conn: *ConnState, id: client_model.ClientId, reason: []const u8) void {
        var eb: [640]u8 = undefined;
        const line = std.fmt.bufPrint(
            &eb,
            ":{s} ERROR :Closing Link: {s} (Banned: {s})\r\n",
            .{ protocol_inventory.currentServerName(), conn.session.displayName(), reason },
        ) catch return;
        self.enqueueDeliveryThenClose(id, line, "Banned (WARD)") catch {};
    }

    /// Connect-time DNS blocklist enforcement, run at registration. Returns true
    /// when it refused (closed) the connection. Reads the cached verdict for the
    /// client's IP (requested at accept); a not-yet-resolved OR not-listed IP
    /// passes (fail-open). Operators and loopback (never requested) are exempt.
    fn enforceDnsbl(self: *LinuxServer, conn: *ConnState) bool {
        const bl = self.config.dnsbl orelse return false;
        if (conn.session.isOper()) return false;
        const addr = conn.peer_addr orelse return false;
        const verdict = bl.lookup(addr) orelse return false; // pending/unknown → pass
        if (!verdict.listed) return false;

        if (self.config.dnsbl_ward) {
            // action = ward: record a node-scope Warden ban for the IP so the
            // block persists across this IP's reconnects, then close this one.
            const ip = conn.session.realHost();
            if (ip.len != 0) {
                self.warden.add(.{
                    .match = .address,
                    .pattern = ip,
                    .scope = .node,
                    .action = .expel,
                    .reason = "DNSBL listed",
                    .set_by = "dnsbl",
                    // Wall clock: created_ms is a wire field gossiped mesh-wide
                    // and all ward timestamps live in the wall domain.
                    .created_ms = platform.realtimeMillis(),
                    .expires_ms = 0,
                }) catch {};
            }
        }
        return self.closeDnsbl(conn, verdict.code);
    }

    /// Emit a DNSBL close ERROR and mark the connection for teardown.
    fn closeDnsbl(self: *LinuxServer, conn: *ConnState, code: u8) bool {
        var eb: [256]u8 = undefined;
        const el = std.fmt.bufPrint(
            &eb,
            ":{s} ERROR :Closing Link: {s} (Connection refused: your address is listed on a DNS blocklist [{d}])\r\n",
            .{ protocol_inventory.currentServerName(), conn.session.displayName(), code },
        ) catch null;
        if (el) |line| appendToConn(conn, line) catch {};
        var db: [48]u8 = undefined;
        self.publishSecurityBlock(conn, "DNSBL", std.fmt.bufPrint(&db, "listed [{d}]", .{code}) catch "listed");
        conn.close_reason = "DNSBL listed";
        conn.closing = true;
        self.armSendIfNeeded(conn) catch {};
        return true;
    }

    /// RESV/UNRESV — reserve a channel-name glob network-wide (oper-only).
    /// `RESV <pattern> <duration-ms> :reason | RESV DEL <pattern> | RESV LIST`
    /// and `UNRESV <pattern>`. Reserved names are refused at JOIN for non-opers.
    pub fn handleResv(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        // Operator gate is enforced declaratively by the registry (access=.oper).
        const nick = conn.session.displayName();
        const cmd = svc_resv.parseServerCommand(parsed.command, parsed.paramSlice(), self.nowMs()) catch |err| {
            const msg = switch (err) {
                error.MissingParameter => "Usage: RESV <#pattern> <duration-ms> :reason | RESV DEL <#pattern> | RESV LIST",
                error.UnknownCommand => "Unknown RESV command",
                error.InvalidDuration, error.DurationOverflow => "RESV: invalid duration",
                error.EmptyPattern, error.PatternTooLong, error.PatternIsNotChannel, error.InvalidPattern => "RESV: pattern must be a valid channel glob (e.g. #help*)",
                error.ReasonTooLong => "RESV: reason too long",
                error.SetterTooLong => "RESV: setter too long",
                error.TooManyReservations => "RESV list is full",
            };
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"RESV"}, msg);
            return;
        };

        switch (cmd) {
            .add => |req| {
                self.chan_resv.addParsed(req, nick, self.nowMs()) catch |err| {
                    const msg = switch (err) {
                        error.TooManyReservations => "RESV list is full",
                        error.PatternTooLong, error.InvalidPattern, error.PatternIsNotChannel, error.EmptyPattern => "RESV: invalid pattern",
                        error.ReasonTooLong => "RESV: reason too long",
                        else => "RESV add failed",
                    };
                    var nb: [256]u8 = undefined;
                    const nl = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :{s}\r\n", .{ protocol_inventory.currentServerName(), nick, msg }) catch return;
                    try emitReplyLine(conn, nl);
                    return;
                };
                var nb: [384]u8 = undefined;
                const nl = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :RESV added: {s}\r\n", .{ protocol_inventory.currentServerName(), nick, req.pattern }) catch return;
                try emitReplyLine(conn, nl);
            },
            .remove => |pattern| {
                const removed = self.chan_resv.remove(pattern);
                var nb: [320]u8 = undefined;
                const nl = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :{s}\r\n", .{ protocol_inventory.currentServerName(), nick, if (removed) "RESV removed" else "RESV pattern not found" }) catch return;
                try emitReplyLine(conn, nl);
            },
            .list => {
                var buf: [256]svc_resv.Reservation = undefined;
                for (self.chan_resv.list(&buf)) |e| {
                    var line_buf: [768]u8 = undefined;
                    const ln = std.fmt.bufPrint(&line_buf, ":{s} NOTICE {s} :RESV {s} :{s}\r\n", .{ protocol_inventory.currentServerName(), nick, e.pattern, e.reason }) catch continue;
                    try emitReplyLine(conn, ln);
                }
                var eb: [128]u8 = undefined;
                const endl = std.fmt.bufPrint(&eb, ":{s} NOTICE {s} :End of RESV list\r\n", .{ protocol_inventory.currentServerName(), nick }) catch return;
                try emitReplyLine(conn, endl);
            },
            .sweep => {
                const n = self.chan_resv.sweep(self.nowMs());
                var nb: [256]u8 = undefined;
                const nl = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :RESV swept {d} expired\r\n", .{ protocol_inventory.currentServerName(), nick, n }) catch return;
                try emitReplyLine(conn, nl);
            },
        }
    }

    /// JUPE/UNJUPE — forbid a server-name glob from linking into the mesh
    /// (oper-only). `JUPE <pattern> <duration-ms> :reason | JUPE DEL <pattern> |
    /// JUPE LIST | JUPE SWEEP` and `UNJUPE <pattern>`. A juped name is refused
    /// when a peer presenting it reaches the link-established transition; an
    /// already-linked peer that becomes juped is dropped on its next drive.
    pub fn handleJupe(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        // Operator gate is enforced declaratively by the registry (access=.oper).
        const nick = conn.session.displayName();
        const srv = protocol_inventory.currentServerName();
        const cmd = svc_jupe.parseServerCommand(parsed.command, parsed.paramSlice(), self.nowMs()) catch |err| {
            const msg = switch (err) {
                error.MissingParameter => "Usage: JUPE <server-glob> <duration-ms> :reason | JUPE DEL <glob> | JUPE LIST",
                error.UnknownCommand => "Unknown JUPE command",
                error.InvalidDuration, error.DurationOverflow => "JUPE: invalid duration",
                error.EmptyPattern, error.PatternTooLong, error.InvalidPattern => "JUPE: pattern must be a server-name glob (e.g. *.evil.net)",
                error.ReasonTooLong => "JUPE: reason too long",
                error.SetterTooLong => "JUPE: setter too long",
                error.TooManyEntries => "JUPE list is full",
            };
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"JUPE"}, msg);
            return;
        };

        switch (cmd) {
            .add => |req| {
                self.server_jupe.addParsed(req, nick, self.nowMs()) catch |err| {
                    const msg = switch (err) {
                        error.TooManyEntries => "JUPE list is full",
                        error.PatternTooLong, error.InvalidPattern, error.EmptyPattern => "JUPE: invalid pattern",
                        error.ReasonTooLong => "JUPE: reason too long",
                        else => "JUPE add failed",
                    };
                    var nb: [256]u8 = undefined;
                    const nl = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :{s}\r\n", .{ srv, nick, msg }) catch return;
                    try emitReplyLine(conn, nl);
                    return;
                };
                // Already-linked peers matching the new jupe are dropped on their
                // next drive (each on its own reactor thread — see refuseJupedPeer),
                // so a JUPE takes effect within a keepalive without a cross-reactor
                // mutation here.
                var nb: [384]u8 = undefined;
                const nl = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :JUPE added: {s} (takes effect on next peer activity)\r\n", .{ srv, nick, req.pattern }) catch return;
                try emitReplyLine(conn, nl);
                const proof_id = self.recordOperAudit(nick, .jupe, req.pattern, req.reason);
                var event_buf: [default_reply_bytes]u8 = undefined;
                const event_msg = if (proof_id) |pid|
                    std.fmt.bufPrint(&event_buf, "JUPE ADD {s} proof={s}", .{ req.pattern, pid[0..] }) catch "JUPE ADD"
                else
                    std.fmt.bufPrint(&event_buf, "JUPE ADD {s}", .{req.pattern}) catch "JUPE ADD";
                try self.publishOperEvent(.oper_action, .notice, event_msg);
            },
            .remove => |pattern| {
                const removed = self.server_jupe.remove(pattern);
                var nb: [320]u8 = undefined;
                const nl = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :{s}\r\n", .{ srv, nick, if (removed) "JUPE removed" else "JUPE pattern not found" }) catch return;
                try emitReplyLine(conn, nl);
            },
            .list => {
                var buf: [256]svc_jupe.Entry = undefined;
                for (self.server_jupe.list(&buf)) |e| {
                    var line_buf: [896]u8 = undefined;
                    const ln = std.fmt.bufPrint(&line_buf, ":{s} NOTICE {s} :JUPE {s} (by {s}) :{s}\r\n", .{ srv, nick, e.pattern, e.setter, e.reason }) catch continue;
                    try emitReplyLine(conn, ln);
                }
                var eb: [128]u8 = undefined;
                const endl = std.fmt.bufPrint(&eb, ":{s} NOTICE {s} :End of JUPE list\r\n", .{ srv, nick }) catch return;
                try emitReplyLine(conn, endl);
            },
            .sweep => {
                const n = self.server_jupe.sweep(self.nowMs());
                var nb: [256]u8 = undefined;
                const nl = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :JUPE swept {d} expired\r\n", .{ srv, nick, n }) catch return;
                try emitReplyLine(conn, nl);
            },
        }
    }

    /// Whether `server_name` is currently juped (forbidden from linking). Empty
    /// names never match. Shared by both S2S drive paths.
    fn serverNameJuped(self: *const LinuxServer, peer_name: []const u8) ?svc_jupe.Entry {
        if (peer_name.len == 0) return null;
        return self.server_jupe.isJuped(peer_name, self.nowMs());
    }

    /// Drop a peer link whose remote server name is juped. Logs the refusal and
    /// marks the connection closing (mirroring the collision-loser path). Returns
    /// true when the link was refused so the caller stops driving it. `s2s_dedup`
    /// is set so the close does not emit a spurious netsplit.
    fn refuseJupedPeer(self: *LinuxServer, conn: *ConnState, remote_name: []const u8) bool {
        if (self.serverNameJuped(remote_name) == null) return false;
        conn.s2s_dedup = true;
        conn.closing = true;
        self.logMeshEvent(.peer_down, remote_name, "link refused: server is juped");
        self.publishOperEvent(.server_link, .warn, "JUPE refused server link") catch {};
        return true;
    }

    /// FORCEOP / FORCEDEOP / FORCEJOIN / FORCEPART / FORCETOPIC — operator force
    /// actions over channels and members. Each maps to a real server effect
    /// (MODE/JOIN/KICK/TOPIC) applied on behalf of the target; no pseudo-client.
    pub fn handleForceAction(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        _ = id;
        // Operator gate is enforced declaratively by the registry (access=.oper).
        // The pure parser expects the verb as argv[0], then the parameters.
        var argv: [8][]const u8 = undefined;
        var n: usize = 0;
        argv[n] = parsed.command;
        n += 1;
        for (parsed.paramSlice()) |p| {
            if (n == argv.len) break;
            argv[n] = p;
            n += 1;
        }
        const action = svc_forceaction.parseRequest(argv[0..n]) catch |err| {
            const msg = switch (err) {
                error.NeedMoreParams => "Not enough parameters",
                error.TooManyParams => "Too many parameters",
                error.InvalidChannel => "Invalid channel name",
                error.InvalidNick => "Invalid nickname",
                error.TopicTooLong => "Topic too long",
                error.ReasonTooLong => "Reason too long",
                error.UnknownAction => "Unknown force action",
            };
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{parsed.command}, msg);
            return;
        };
        switch (action) {
            .forcejoin => |t| try self.forceJoin(conn, t.channel, t.nick),
            .forcepart => |t| try self.forcePart(conn, t.channel, t.nick, t.reason),
            .forceop => |t| try self.forceMemberOp(conn, t.channel, t.nick, true),
            .forcedeop => |t| try self.forceMemberOp(conn, t.channel, t.nick, false),
            .forcetopic => |t| try self.forceTopic(conn, t.channel, t.topic),
        }
    }

    /// Resolve a target nick to its live (client-id, conn). Emits ERR_NOSUCHNICK
    /// on `conn` and returns null when the nick is not online.
    fn resolveTargetConn(self: *LinuxServer, conn: *ConnState, nick: []const u8) ?struct { id: client_model.ClientId, conn: *ConnState } {
        const twid = self.world.findNick(nick) orelse {
            queueNumeric(conn, .ERR_NOSUCHNICK, &.{nick}, "No such nick") catch {};
            return null;
        };
        const tid = clientIdFromWorld(twid);
        const tconn = self.connFor(tid) orelse {
            queueNumeric(conn, .ERR_NOSUCHNICK, &.{nick}, "No such nick") catch {};
            return null;
        };
        return .{ .id = tid, .conn = tconn };
    }

    fn forceJoin(self: *LinuxServer, conn: *ConnState, channel: []const u8, nick: []const u8) !void {
        const t = self.resolveTargetConn(conn, nick) orelse return;
        try self.joinOne(t.id, t.conn, channel, null, 0);
        self.auditForceAction(conn, .forcejoin, "FORCEJOIN", channel, nick);
        try self.noticeTo(conn, "Force action applied");
    }

    fn forcePart(self: *LinuxServer, conn: *ConnState, channel: []const u8, nick: []const u8, reason: []const u8) !void {
        if (!self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        const t = self.resolveTargetConn(conn, nick) orelse return;
        const part_reason = if (reason.len > 0) reason else "Removed by operator";
        try self.partOne(t.id, t.conn, channel, part_reason);
        self.auditForceAction(conn, .forcepart, "FORCEPART", channel, nick);
        try self.noticeTo(conn, "Force action applied");
    }

    fn forceMemberOp(self: *LinuxServer, conn: *ConnState, channel: []const u8, nick: []const u8, adding: bool) !void {
        if (!self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        const twid = self.world.findNick(nick) orelse {
            try queueNumeric(conn, .ERR_NOSUCHNICK, &.{nick}, "No such nick");
            return;
        };
        const current = self.world.memberModes(channel, twid) orelse {
            try queueNumeric(conn, .ERR_USERNOTINCHANNEL, &.{ nick, channel }, "They aren't on that channel");
            return;
        };
        var desired = current;
        if (adding) desired.add(.op) else desired.remove(.op);
        if (desired.bits == current.bits) {
            self.auditForceAction(conn, if (adding) .forceop else .forcedeop, if (adding) "FORCEOP" else "FORCEDEOP", channel, nick);
            try self.noticeTo(conn, "Force action applied (no change)");
            return;
        }
        const target_id = clientIdFromWorld(twid);
        const target_conn = self.connFor(target_id);
        const local_projection = if (target_conn) |local_target|
            self.armLocalChannelProjectionForClient(target_id, local_target, channel, true, desired.bits) catch {
                try self.failReply(conn, if (adding) "FORCEOP" else "FORCEDEOP", "TEMPORARILY_UNAVAILABLE", "Session channel state is busy; retry force action");
                return;
            }
        else
            null;
        const changed = self.world.setMemberMode(channel, twid, .op, adding) catch unreachable;
        std.debug.assert(changed);
        if (target_conn) |local_target| {
            self.completeLocalMemberModeMutation(target_id, local_target, channel, nick, desired, local_projection, conn.session.displayName());
        } else {
            self.announceMembership(channel, nick, @truncate(desired.bits), true, .{}, conn.session.displayName());
        }
        var buf: [256]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} MODE {s} {s}o {s}\r\n", .{ self.serverName(), channel, if (adding) "+" else "-", nick }) catch return;
        try self.broadcastChannel(channel, line, null);
        self.auditForceAction(conn, if (adding) .forceop else .forcedeop, if (adding) "FORCEOP" else "FORCEDEOP", channel, nick);
    }

    fn forceTopic(self: *LinuxServer, conn: *ConnState, channel: []const u8, topic: []const u8) !void {
        if (!self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        try self.world.setTopic(channel, topic, self.serverName(), @divFloor(platform.realtimeMillis(), 1000));
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} TOPIC {s} :{s}\r\n", .{ self.serverName(), channel, topic }) catch return;
        try self.broadcastChannel(channel, line, null);
        self.auditForceAction(conn, .forcetopic, "FORCETOPIC", channel, topic);
    }

    fn auditForceAction(self: *LinuxServer, conn: *ConnState, action: svc_operaudit.Action, command: []const u8, channel: []const u8, detail: []const u8) void {
        var target_buf: [320]u8 = undefined;
        const target = std.fmt.bufPrint(&target_buf, "{s} {s}", .{ channel, detail }) catch channel;
        const proof_id = self.recordOperAudit(conn.session.displayName(), action, target, command);
        var event_buf: [default_reply_bytes]u8 = undefined;
        const event_note = if (proof_id) |pid|
            std.fmt.bufPrint(&event_buf, "{s} {s} {s} proof={s}", .{ command, channel, detail, pid[0..] }) catch return
        else
            std.fmt.bufPrint(&event_buf, "{s} {s} {s}", .{ command, channel, detail }) catch return;
        self.publishOperEvent(.oper_action, .notice, event_note) catch {};
    }

    /// Map a member's channel-status modes to the mass-kick rank ladder.
    fn masskickRank(mm: world_model.MemberModes) svc_masskick.Rank {
        if (mm.contains(.founder)) return .founder;
        if (mm.contains(.owner)) return .owner;
        if (mm.contains(.op)) return .op;
        if (mm.contains(.voice)) return .voice;
        return .member;
    }

    /// CLEAR <#channel> USERS [KEEP <rank>] [ALLOW <acct[,acct]>] [:reason] —
    /// mass-kick every member below the keep rank (default: keep founders) that
    /// is not on the account allowlist. Requires channel founder or server oper.
    pub fn handleClear(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        // Reassemble the command line for the pure parser ("CLEAR <args...>").
        var lb: [1024]u8 = undefined;
        var used: usize = 0;
        const verb = "CLEAR";
        @memcpy(lb[0..verb.len], verb);
        used = verb.len;
        for (parsed.paramSlice()) |tok| {
            if (used + 1 + tok.len > lb.len) break;
            lb[used] = ' ';
            used += 1;
            @memcpy(lb[used..][0..tok.len], tok);
            used += tok.len;
        }
        var allow_buf: [16][]const u8 = undefined;
        const req = svc_masskick.parseClearUsers(lb[0..used], &allow_buf) catch |err| {
            const reply = svc_masskick.numericForError(err, "*");
            try self.noticeTo(conn, reply.text);
            return;
        };
        if (!self.world.channelExists(req.channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{req.channel}, "No such channel");
            return;
        }
        const actor_mm = self.world.memberModes(req.channel, worldIdFromClient(id)) orelse blk: {
            if (conn.session.isOper()) break :blk world_model.MemberModes.empty();
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{req.channel}, "You're not on that channel");
            return;
        };
        const actor = svc_masskick.Actor{
            .nick = conn.session.displayName(),
            .rank = masskickRank(actor_mm),
            .is_oper = conn.session.isOper(),
        };
        if (!svc_masskick.canExecuteClearUsers(actor)) {
            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{req.channel}, "CLEAR requires channel founder or operator");
            return;
        }

        // Snapshot the membership (nick/account/rank). Borrowed slices stay valid
        // for the duration of this call.
        var members: [256]svc_masskick.Member = undefined;
        var member_ids: [256]client_model.ClientId = undefined;
        var mn: usize = 0;
        var it = self.world.memberIterator(req.channel) orelse {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{req.channel}, "No such channel");
            return;
        };
        while (it.next()) |member| {
            if (mn == members.len) break;
            const mid = clientIdFromWorld(member.*);
            const mconn = self.connFor(mid) orelse continue;
            const mm = self.world.memberModes(req.channel, member.*) orelse world_model.MemberModes.empty();
            members[mn] = .{
                .nick = mconn.session.displayName(),
                .account = mconn.session.account(),
                .rank = masskickRank(mm),
            };
            member_ids[mn] = mid;
            mn += 1;
        }

        var plan_buf: [256]svc_masskick.KickPlanEntry = undefined;
        const plan = svc_masskick.buildKickPlan(actor, req, members[0..mn], &plan_buf) catch |err| {
            const reply = svc_masskick.numericForError(err, req.channel);
            try self.noticeTo(conn, reply.text);
            return;
        };

        const Victim = struct {
            entry: svc_masskick.KickPlanEntry,
            id: client_model.ClientId,
            conn: *ConnState,
            projection: ?sessions_mod.LocalChannelProjectionWork = null,
        };
        var victims: [256]Victim = undefined;
        var victim_len: usize = 0;
        for (plan) |entry| {
            if (entry.member_index >= mn) continue;
            // CLEAR is nick-addressed. If any concrete World row rendering this
            // nick was protected by the planner (for example its highest rank is
            // not kickable), preserve every row rather than privately stripping
            // only a lower-ranked token and leaving a misleading partial user.
            var rendered_identity_protected = false;
            for (members[0..mn], 0..) |sibling, sibling_index| {
                if (!std.ascii.eqlIgnoreCase(sibling.nick, entry.nick)) continue;
                var sibling_planned = false;
                for (plan) |planned| {
                    if (planned.member_index == sibling_index) {
                        sibling_planned = true;
                        break;
                    }
                }
                if (!sibling_planned) {
                    rendered_identity_protected = true;
                    break;
                }
            }
            if (rendered_identity_protected) continue;
            const target_id = member_ids[entry.member_index];
            const target_conn = self.connFor(target_id) orelse continue;
            var duplicate_group = false;
            for (victims[0..victim_len]) |victim| {
                if (self.clientsShareExactToken(victim.id, victim.conn, target_id, target_conn)) {
                    duplicate_group = true;
                    break;
                }
            }
            if (duplicate_group) continue;
            victims[victim_len] = .{ .entry = entry, .id = target_id, .conn = target_conn };
            victim_len += 1;
        }
        var first_arm_error = false;
        var kicked: usize = 0;
        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        for (victims[0..victim_len]) |*victim| {
            logical_ids.clearRetainingCapacity();
            self.collectAttachedExactTokenClients(victim.id, victim.conn, &logical_ids) catch {
                first_arm_error = true;
                continue;
            };
            victim.projection = self.armLocalChannelProjectionForClient(
                victim.id,
                victim.conn,
                req.channel,
                false,
                0,
            ) catch {
                first_arm_error = true;
                continue;
            };
            const nick_survives = self.renderedNickSurvivesTokenRemoval(
                victim.id,
                victim.conn,
                req.channel,
                victim.entry.nick,
            );
            var line_buf: [default_reply_bytes]u8 = undefined;
            if (svc_masskick.formatKickLine(protocol_inventory.currentServerName(), victim.entry, &line_buf)) |line| {
                if (nick_survives) {
                    for (logical_ids.items) |logical_id| {
                        if (!self.world.isMember(req.channel, worldIdFromClient(logical_id))) continue;
                        self.deliverTimed(logical_id, "", line) catch {};
                    }
                } else {
                    self.broadcastChannel(req.channel, line, null) catch {};
                }
            } else |_| {}
            self.completeLocalChannelRemoval(
                victim.id,
                victim.conn,
                req.channel,
                victim.entry.nick,
                victim.projection,
                !nick_survives,
            );
            kicked += 1;
        }
        if (first_arm_error)
            try self.failReply(conn, "CLEAR", "PARTIAL", "CLEAR removed staged sessions; retry to finish busy sessions");
        var nb: [128]u8 = undefined;
        const note = std.fmt.bufPrint(&nb, "CLEAR {s}: removed {d} user(s)", .{ req.channel, kicked }) catch return;
        try self.noticeTo(conn, note);
    }

    /// DEFER AT <unix-ms> <#channel> :<text>
    /// DEFER CRON <min> <hour> <dom> <mon> <dow> <#channel> :<text>
    /// DEFER AT <unix-ms> OPER <#channel> <flag>
    /// DEFER CRON <min> <hour> <dom> <mon> <dow> OPER <#channel> <flag>
    ///
    /// A registered user defers one channel message. An oper defers one boolean
    /// channel mode. Reactor 0 fires each job once. The body is stored through
    /// the offline memo path and, when fired, through history.
    pub fn handleDefer(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.registered()) {
            try queueNumeric(conn, .ERR_NOTREGISTERED, &.{}, "You have not registered");
            return;
        }
        const p = parsed.paramSlice();
        if (p.len < 4) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"DEFER"}, "Usage: DEFER AT <unix-ms> <#channel> :<text> | DEFER CRON <min> <hour> <dom> <mon> <dow> <#channel> :<text> | DEFER <when> OPER <#channel> <flag>");
            return;
        }
        const cron_form = std.ascii.eqlIgnoreCase(p[0], "CRON");
        const at_form = std.ascii.eqlIgnoreCase(p[0], "AT");
        if (!cron_form and !at_form) {
            try self.noticeTo(conn, "DEFER: invalid schedule");
            return;
        }

        var due_ms: i64 = 0;
        var cron_buf: [schedule_snapshot.max_cron]u8 = undefined;
        var cron_len: usize = 0;
        const rest: []const []const u8 = if (at_form) blk: {
            due_ms = std.fmt.parseInt(i64, p[1], 10) catch {
                try self.noticeTo(conn, "DEFER: invalid schedule");
                return;
            };
            if (due_ms < 0) {
                try self.noticeTo(conn, "DEFER: invalid schedule");
                return;
            }
            break :blk p[2..];
        } else blk: {
            if (p.len < 8) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"DEFER"}, "Usage: DEFER CRON <min> <hour> <dom> <mon> <dow> <#channel> :<text>");
                return;
            }
            var n: usize = 0;
            for (p[1..6], 0..) |field, i| {
                if (field.len == 0) {
                    try self.noticeTo(conn, "DEFER: invalid schedule");
                    return;
                }
                if (i != 0) {
                    if (n >= cron_buf.len) {
                        try self.noticeTo(conn, "DEFER: invalid schedule");
                        return;
                    }
                    cron_buf[n] = ' ';
                    n += 1;
                }
                if (n + field.len > cron_buf.len) {
                    try self.noticeTo(conn, "DEFER: invalid schedule");
                    return;
                }
                @memcpy(cron_buf[n..][0..field.len], field);
                n += field.len;
            }
            const parsed_cron = cron.parse(cron_buf[0..n]) catch {
                try self.noticeTo(conn, "DEFER: invalid schedule");
                return;
            };
            const wall = self.meshWallMs();
            const unix_secs: i64 = if (wall / 1000 > @as(u64, std.math.maxInt(i64))) std.math.maxInt(i64) else @intCast(wall / 1000);
            const next = cron.nextAfter(parsed_cron, unix_secs) orelse {
                try self.noticeTo(conn, "DEFER: invalid schedule");
                return;
            };
            due_ms = std.math.mul(i64, next, 1000) catch {
                try self.noticeTo(conn, "DEFER: invalid schedule");
                return;
            };
            cron_len = n;
            break :blk p[6..];
        };

        const oper_form = rest.len >= 1 and std.ascii.eqlIgnoreCase(rest[0], "OPER");
        var target: []const u8 = undefined;
        var body: []const u8 = undefined;
        var mode: u8 = 0;
        var kind: u8 = schedule_snapshot.kind_channel;
        var mode_body: [2]u8 = undefined;
        if (oper_form) {
            if (!conn.session.isOper()) {
                try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied");
                return;
            }
            if (rest.len < 3 or rest[2].len != 1) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"DEFER"}, "Usage: DEFER AT <unix-ms> OPER <#channel> <flag>");
                return;
            }
            target = rest[1];
            mode = rest[2][0];
            if (channelFlagFromLetter(mode) == null) {
                try queueNumeric(conn, .ERR_UNKNOWNMODE, &.{target}, "DEFER supports boolean channel flags only");
                return;
            }
            kind = schedule_snapshot.kind_oper;
            mode_body[0] = '+';
            mode_body[1] = mode;
            body = &mode_body;
        } else {
            if (rest.len < 2 or rest[1].len == 0) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"DEFER"}, "Usage: DEFER AT <unix-ms> <#channel> :<text>");
                return;
            }
            target = rest[0];
            body = rest[1];
            if (body.len > 400) {
                try self.noticeTo(conn, "DEFER: message is too long");
                return;
            }
            for (body) |ch| {
                if (ch == '\r' or ch == '\n' or ch == 0) {
                    try self.noticeTo(conn, "DEFER: invalid schedule");
                    return;
                }
            }
        }
        if (!world_model.isChannelName(target) or !self.world.channelExists(target)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{target}, "No such channel");
            return;
        }
        if (kind == schedule_snapshot.kind_channel and !self.world.isMember(target, worldIdFromClient(id))) {
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{target}, "You're not on that channel");
            return;
        }
        const sender = conn.session.displayName();
        if (sender.len == 0 or sender.len > schedule_snapshot.max_sender or target.len > schedule_snapshot.max_target) {
            try self.noticeTo(conn, "DEFER: invalid schedule");
            return;
        }
        if (self.schedules.find(kind, target) != null) {
            try self.noticeTo(conn, "DEFER: already scheduled");
            return;
        }

        const job_id = self.schedules.takeId() catch {
            try self.noticeTo(conn, "DEFER: could not schedule (limit)");
            return;
        };
        var key_buf: [schedule_snapshot.max_key]u8 = undefined;
        const key = schedule_snapshot.keyFromId(job_id, &key_buf);
        _ = self.storeOfflineMemo(key, sender, body, self.nowMs()) catch {
            try self.noticeTo(conn, "DEFER: could not store the message");
            return;
        };
        self.schedules.insert(.{
            .id = job_id,
            .kind = kind,
            .when_kind = if (cron_form) schedule_snapshot.when_cron else schedule_snapshot.when_timestamp,
            .mode = mode,
            .due_ms = due_ms,
            .target = target,
            .sender = sender,
            .key = key,
            .cron = cron_buf[0..cron_len],
        }) catch {
            try self.noticeTo(conn, "DEFER: could not schedule (limit)");
            return;
        };
        try self.noticeTo(conn, "DEFER: scheduled");
    }

    /// TEMPMODE ADD <#chan> <flag> [param] <duration> | CANCEL <#chan> <flag>
    /// [param] | SWEEP — schedule an auto-reverting channel flag mode. ADD sets
    /// the flag now and queues the `-flag` revert; the timer sweep applies it.
    /// Requires channel operator or server oper. Flag (boolean) modes only.
    pub fn handleTempmode(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const cmd = svc_tempmode.parseParams(parsed.paramSlice(), self.nowMs()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"TEMPMODE"}, "Usage: TEMPMODE ADD <#chan> <flag> [param] <duration> | CANCEL <#chan> <flag> [param] | SWEEP");
            return;
        };
        switch (cmd) {
            .add => |a| {
                if (!self.world.channelExists(a.channel)) {
                    try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{a.channel}, "No such channel");
                    return;
                }
                if (!self.canModerateChannel(id, conn, a.channel)) {
                    try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{a.channel}, "You're not channel operator");
                    return;
                }
                const mode = channelFlagFromLetter(a.mode_letter) orelse {
                    try queueNumeric(conn, .ERR_UNKNOWNMODE, &.{a.channel}, "TEMPMODE supports boolean channel flags only");
                    return;
                };
                _ = self.world.setChannelFlag(a.channel, mode, true) catch {};
                _ = self.temp_modes.addParsed(a) catch {
                    try self.noticeTo(conn, "TEMPMODE: could not schedule (limit or invalid window)");
                    return;
                };
                var buf: [128]u8 = undefined;
                const line = std.fmt.bufPrint(&buf, ":{s} MODE {s} +{c}\r\n", .{ self.serverName(), a.channel, a.mode_letter }) catch return;
                try self.broadcastChannel(a.channel, line, null);
            },
            .cancel => |c| {
                if (!self.canModerateChannel(id, conn, c.channel)) {
                    try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{c.channel}, "You're not channel operator");
                    return;
                }
                const removed = self.temp_modes.cancelAll(c.channel, c.mode_letter, c.param);
                var nb: [160]u8 = undefined;
                const note = std.fmt.bufPrint(&nb, "TEMPMODE: cancelled {d} scheduled revert(s)", .{removed}) catch return;
                try self.noticeTo(conn, note);
            },
            .sweep => {
                if (!conn.session.isOper()) {
                    try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "TEMPMODE SWEEP is operator-only");
                    return;
                }
                self.sweepTempModes();
                try self.noticeTo(conn, "TEMPMODE: swept due reverts");
            },
        }
    }

    /// Record a login/logout event in an account's SEEN history (no-op for an
    /// empty account). Keys are owned; the value is allocation-free inline state.
    fn recordSeen(self: *LinuxServer, account: []const u8, mask: []const u8, event: svc_lastseen.EventKind) void {
        if (account.len == 0) return;
        const gop = self.seen.getOrPut(self.allocator, account) catch return;
        if (!gop.found_existing) {
            const key = self.allocator.dupe(u8, account) catch {
                _ = self.seen.remove(account);
                return;
            };
            gop.key_ptr.* = key;
            gop.value_ptr.* = svc_lastseen.SeenHistory.init();
        }
        gop.value_ptr.record(platform.realtimeMillis(), mask, event);
    }

    /// SEEN <account> — report an account's last-seen / last-login time and its
    /// recent login/logout history. Available to any registered user.
    pub fn handleSeen(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const p = parsed.paramSlice();
        if (p.len < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"SEEN"}, "Usage: SEEN <account>");
            return;
        }
        const account = p[0];
        const hist = self.seen.getPtr(account) orelse {
            var nb: [192]u8 = undefined;
            const note = std.fmt.bufPrint(&nb, "SEEN {s}: no record", .{account}) catch return;
            try self.noticeTo(conn, note);
            return;
        };
        var sb: [256]u8 = undefined;
        const summary = std.fmt.bufPrint(&sb, "SEEN {s}: last_seen={d} last_login={d}", .{
            account,
            hist.lastSeen() orelse 0,
            hist.lastLogin() orelse 0,
        }) catch return;
        try self.noticeTo(conn, summary);
        var recs: [svc_lastseen.ring_capacity]svc_lastseen.Record = undefined;
        const n = hist.recent(svc_lastseen.default_render_count, &recs);
        for (recs[0..n]) |*r| {
            var lb: [256]u8 = undefined;
            const line = std.fmt.bufPrint(&lb, "  {s} {d} {s}", .{ r.event.label(), r.timestamp, r.hostmask() }) catch continue;
            try self.noticeTo(conn, line);
        }
    }

    /// Lazily load the configured MaxMind GeoIP database on first use. Returns
    /// the live database, or null when none is configured / it failed to load.
    fn ensureGeoip(self: *LinuxServer) ?geoip.Database {
        if (self.geoip_db) |db| return db;
        if (self.geoip_tried) return null;
        self.geoip_tried = true;
        if (self.config.geoip_db_path.len == 0) return null;
        const io = self.config.crypto_io orelse return null;
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, self.config.geoip_db_path, self.allocator, .limited(256 << 20)) catch return null;
        const db = geoip.Database.init(bytes) catch {
            self.allocator.free(bytes);
            return null;
        };
        self.geoip_bytes = bytes;
        self.geoip_db = db;
        return db;
    }

    /// Lazily load the separate ASN database (Config.geoip_asn_db_path) for the
    /// WHOIS AS-number/org line. Same load-once contract as `ensureGeoip`.
    fn ensureGeoipAsn(self: *LinuxServer) ?geoip.Database {
        if (self.geoip_asn_db) |db| return db;
        if (self.geoip_asn_tried) return null;
        self.geoip_asn_tried = true;
        if (self.config.geoip_asn_db_path.len == 0) return null;
        const io = self.config.crypto_io orelse return null;
        const bytes = std.Io.Dir.cwd().readFileAlloc(io, self.config.geoip_asn_db_path, self.allocator, .limited(256 << 20)) catch return null;
        const db = geoip.Database.init(bytes) catch {
            self.allocator.free(bytes);
            return null;
        };
        self.geoip_asn_bytes = bytes;
        self.geoip_asn_db = db;
        return db;
    }

    const GeoAsnLookup = struct {
        asn: ?u32 = null,
        asorg: ?[]const u8 = null,
    };

    fn lookupGeoAsn(self: *LinuxServer, ip: geoip.Ip) GeoAsnLookup {
        const db = self.ensureGeoipAsn() orelse return .{};
        const info = (db.lookupInfo(ip) catch null) orelse return .{};
        return .{
            .asn = info.asn,
            .asorg = info.asn_org orelse info.org orelse info.isp,
        };
    }

    /// On registration, record the client's `location` (city or country) and
    /// `country` (ISO) metadata from GeoIP, falling back to the configured
    /// default location. This gives `!weather` a per-user location with no
    /// per-request lookup, and the country drives imperial/metric unit choice.
    fn setGeoLocation(self: *LinuxServer, conn: *ConnState) void {
        const nick = conn.session.displayName();
        if (nick.len == 0) return;
        if (self.ensureGeoip()) |db| {
            if (parseGeoIp(conn.session.realHost())) |ip| {
                var cc_buf: [4]u8 = undefined;
                const country = db.lookupCountry(ip, &cc_buf) catch null;
                const city = db.lookupName(ip, "city", "en") catch null;
                if (country) |c| _ = self.metadata.set(nick, "country", c) catch {};
                const loc = city orelse country;
                if (loc) |l| {
                    _ = self.metadata.set(nick, "location", l) catch {};
                    return;
                }
            }
        }
        if (self.config.geo_default_location.len > 0) {
            _ = self.metadata.set(nick, "location", self.config.geo_default_location) catch {};
        }
    }

    /// Read a metadata string for `nick`/`key`, or "" if unset.
    fn metaValue(self: *LinuxServer, nick: []const u8, key: []const u8) []const u8 {
        if (self.metadata.get(nick, key)) |ev| return ev.value else |_| return "";
    }

    /// This node's own server name (the source prefix for server-originated
    /// lines). Configurable per node so mesh nodes don't collide; falls back to
    /// the build-time constant.
    pub fn serverName(self: *const LinuxServer) []const u8 {
        return if (self.config.server_name.len != 0) self.config.server_name else server_name;
    }

    /// Post a server NOTICE answer to `chan` from THIS server (the replier). The
    /// fantasy bot only ever runs on the requesting user's own server, so the
    /// answer is generated exactly once: it is delivered to local members AND
    /// relayed to peers (so members on other nodes see the one reply, sourced
    /// from this node's name). No peer regenerates it — no cross-server collision.
    fn fantasyReply(self: *LinuxServer, chan: []const u8, text: []const u8) void {
        // Fail-closed CRLF/control-byte guard (CWE-93). `text` is external-feed
        // content (weather/news bodies), NOT an IRC-line-parsed client field, so
        // it never passed through the inbound `requireNoControlBytes` gate — and
        // this sink is `broadcastChannel` + mesh relay, which bypass the
        // `emitReplyLine` choke point. A control byte in the reflected feed value
        // could inject a second wire line into the channel broadcast AND the S2S
        // relay, so a hostile/compromised feed is dropped whole here (clean feed
        // content is byte-identical). This single guard covers both sinks below.
        if (dispatch.hasControlByte(text)) return;
        const origin = self.serverName();
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :{s}\r\n", .{ origin, chan, text }) catch return;
        self.broadcastChannel(chan, line, null) catch {};

        // Relay across the mesh so remote members of the channel see the reply,
        // attributed to this (the replying) server. Deduped via relay_seen.
        if (self.hasEstablishedPeer()) {
            const hlc = self.nextMeshHlc();
            _ = self.relay_seen.observe(self.config.node_id, hlc);
            var relay_msg = s2s_link.RelayMessage{
                .verb = .notice,
                .target = chan,
                .source_nick = origin,
                .source_prefix = origin,
                .text = text,
                .origin_node = self.config.node_id,
                .hlc = hlc,
            };
            var pk_buf: [message_relay.pubkey_len]u8 = undefined;
            var sig_buf: [message_relay.sig_len]u8 = undefined;
            self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
            _ = self.relayToPeers(relay_msg, .{ .channel = chan });
        }
    }

    /// Channel fantasy dispatch: a member's PRIVMSG starting with `!` may invoke
    /// the weather/news bot. The triggering message is still delivered to the
    /// channel normally; this only posts the answer. `!news` is gated by the +W
    /// channel mode (see handleFantasyNews).
    fn handleFantasy(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, chan: []const u8, text: []const u8) void {
        const sp = std.mem.indexOfScalar(u8, text, ' ');
        const cmd = if (sp) |i| text[0..i] else text;
        const rest = if (sp) |i| std.mem.trim(u8, text[i + 1 ..], " \t") else "";
        const eqi = std.ascii.eqlIgnoreCase;
        // !setweather is a chanop config command (not a bot reply): no cooldown.
        if (eqi(cmd, "!setweather") or eqi(cmd, "!sw")) {
            self.handleFantasySetWeather(id, conn, chan, rest);
            return;
        }
        const is_weather = eqi(cmd, "!weather") or eqi(cmd, "!w") or eqi(cmd, "!wx");
        const is_news = eqi(cmd, "!news") or eqi(cmd, "!n");
        const is_local = eqi(cmd, "!localnews");
        if (!(is_weather or is_news or is_local)) return;
        // Anti-flood: rate-limit bot replies per channel so a user can't spam
        // `!weather` to flood the channel or hammer the fetcher.
        if (!self.fantasyCooldownOk(chan)) return;
        if (is_weather) {
            self.handleFantasyWeather(conn, chan, rest);
        } else if (is_news) {
            self.handleFantasyNews(conn, chan, rest, false);
        } else {
            self.handleFantasyNews(conn, chan, rest, true);
        }
    }

    /// Per-channel fantasy-bot rate limit. Returns true (and records the time) if
    /// the bot may reply in `chan` now; false if it is still within the cooldown
    /// window and should stay silent. A new channel claims the oldest slot.
    fn fantasyCooldownOk(self: *LinuxServer, chan: []const u8) bool {
        const cd: i64 = self.config.geo_cmd_cooldown_ms;
        if (cd == 0) return true;
        const now = self.nowMs();
        var oldest: *FantasyCooldown = &self.fantasy_cooldown[0];
        for (&self.fantasy_cooldown) |*e| {
            if (e.len != 0 and std.ascii.eqlIgnoreCase(e.key[0..e.len], chan)) {
                if (now - e.ts_ms < cd) return false;
                e.ts_ms = now;
                return true;
            }
            if (e.ts_ms < oldest.ts_ms) oldest = e;
        }
        const n = @min(chan.len, oldest.key.len);
        @memcpy(oldest.key[0..n], chan[0..n]);
        oldest.len = n;
        oldest.ts_ms = now;
        return true;
    }

    /// `!setweather <location>|clear` — set or clear this channel's default
    /// `!weather` location (used when a member has no argument/`location` meta).
    /// Stored as the channel's `weather_location` metadata; chanop/oper only.
    fn handleFantasySetWeather(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, chan: []const u8, arg: []const u8) void {
        if (!self.config.geo_enabled) return;
        const mm = self.world.memberModes(chan, worldIdFromClient(id)) orelse world_model.MemberModes.empty();
        if (!mm.isOperator() and !conn.session.isOper()) {
            self.fantasyReply(chan, "You need channel operator status to set the channel weather location.");
            return;
        }
        if (arg.len == 0) {
            self.fantasyReply(chan, "Usage: !setweather <location>  |  !setweather clear");
            return;
        }
        if (std.ascii.eqlIgnoreCase(arg, "clear")) {
            self.metadata.delete(chan, "weather_location") catch {};
            self.fantasyReply(chan, "Channel weather location cleared.");
            return;
        }
        const loc = arg[0..@min(arg.len, 80)];
        _ = self.metadata.set(chan, "weather_location", loc) catch {
            self.fantasyReply(chan, "Could not set the channel weather location.");
            return;
        };
        var b: [160]u8 = undefined;
        self.fantasyReply(chan, std.fmt.bufPrint(&b, "Channel weather location set to {s}.", .{loc}) catch "Channel weather location set.");
    }

    /// `!weather [location]` — serve cached weather for the argument, the sender's
    /// `location` metadata, or the channel's `!setweather` default; localized to
    /// the sender's `country`.
    fn handleFantasyWeather(self: *LinuxServer, conn: *ConnState, chan: []const u8, arg: []const u8) void {
        if (!self.config.geo_enabled) return;
        self.geo.start(); // lazy-start the fetcher thread on first use
        const nick = conn.session.displayName();

        var location = if (arg.len > 0) arg[0..@min(arg.len, 80)] else self.metaValue(nick, "location");
        if (location.len == 0) location = self.metaValue(chan, "weather_location"); // channel default
        if (location.len == 0) {
            self.fantasyReply(chan, "Set your location first: METADATA SET location <place>  (or use !weather <place>, or a chanop can !setweather <place>)");
            return;
        }

        const country = self.metaValue(nick, "country");
        const sys = weather_units.resolveSystem(self.config.weather_units, country);

        var loc_out: [64]u8 = undefined;
        var desc_out: [48]u8 = undefined;
        if (self.geo.getWeather(location, &loc_out, &desc_out)) |view| {
            var line_buf: [160]u8 = undefined;
            const line = weather_units.renderLine(&line_buf, view.location, view.reading, sys);
            var out: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&out, "Weather - {s}", .{line}) catch return;
            self.fantasyReply(chan, msg);
        } else {
            var out: [160]u8 = undefined;
            const msg = std.fmt.bufPrint(&out, "Fetching weather for {s}… try again in a moment.", .{location[0..@min(location.len, 80)]}) catch return;
            self.fantasyReply(chan, msg);
        }
    }

    /// `!news [source]` / `!localnews [CC]` — only in +W (news-wire) channels.
    /// `local` resolves a country feed (arg CC, else the sender's `country`
    /// metadata); otherwise a named source (arg key, else the default source).
    fn handleFantasyNews(self: *LinuxServer, conn: *ConnState, chan: []const u8, arg: []const u8, local: bool) void {
        if (!self.config.geo_enabled) return;
        // Gated by the +W channel mode: silent in channels that haven't enabled it.
        if (!self.world.channelHasFlag(chan, .news_wire)) return;
        self.geo.start();

        var keybuf: [80]u8 = undefined;
        var name: []const u8 = "";
        var key: []const u8 = "";
        if (local) {
            const cc = if (arg.len >= 2) arg[0..2] else self.metaValue(conn.session.displayName(), "country");
            if (cc.len == 0) {
                self.fantasyReply(chan, "Unknown country - try: !localnews <CC>  (e.g. !localnews JP)");
                return;
            }
            const feed = news_sources.countryFeed(cc) orelse {
                self.fantasyReply(chan, "No country feed for that code. Try !news for general headlines.");
                return;
            };
            name = feed.name;
            key = std.fmt.bufPrint(&keybuf, "cc:{s}", .{cc}) catch return;
        } else {
            const src = if (arg.len > 0)
                (news_sources.sourceByKey(arg) orelse {
                    self.fantasyReply(chan, "Unknown source. Try !news (default) or a key like bbc/npr/guardian.");
                    return;
                })
            else
                news_sources.defaultSource();
            name = src.name;
            key = std.fmt.bufPrint(&keybuf, "src:{s}", .{src.key}) catch return;
        }

        var out: [512]u8 = undefined;
        var lines: [5][]const u8 = undefined;
        if (self.geo.getNews(key, &out, &lines)) |got| {
            var hb: [128]u8 = undefined;
            self.fantasyReply(chan, std.fmt.bufPrint(&hb, "News - {s}:", .{name}) catch name);
            for (got, 1..) |headline, n| {
                var lb: [320]u8 = undefined;
                const line = std.fmt.bufPrint(&lb, "  {d}. {s}", .{ n, headline }) catch continue;
                self.fantasyReply(chan, line);
            }
        } else {
            var fb: [128]u8 = undefined;
            self.fantasyReply(chan, std.fmt.bufPrint(&fb, "Fetching {s} headlines… try again in a moment.", .{name}) catch return);
        }
    }

    /// Parse an IPv4 or IPv6 literal into a geoip.Ip, or null if malformed.
    fn parseGeoIp(text: []const u8) ?geoip.Ip {
        if (std.Io.net.Ip4Address.parse(text, 0)) |a4| {
            return geoip.Ip{ .v4 = a4.bytes };
        } else |_| {}
        if (std.Io.net.Ip6Address.parse(text, 0)) |a6| {
            return geoip.Ip{ .v6 = a6.bytes };
        } else |_| {}
        return null;
    }

    /// Render a compact `[CC ASn org]` geo tag for an IP into `buf`, or "" when
    /// no database is configured or the address yields no geo data. Used to
    /// annotate oper reports (CLONES) with country/ASN context.
    fn geoTag(self: *LinuxServer, ip_text: []const u8, buf: []u8) []const u8 {
        const db = self.ensureGeoip() orelse return "";
        const ip = parseGeoIp(ip_text) orelse return "";
        const gi = (db.lookupInfo(ip) catch null) orelse return "";
        const cc = gi.country_iso orelse "??";
        if (gi.asn) |asn| {
            const org = gi.asn_org orelse gi.org orelse "";
            return std.fmt.bufPrint(buf, " [{s} AS{d}{s}{s}]", .{
                cc, asn, if (org.len > 0) " " else "", org,
            }) catch "";
        }
        return std.fmt.bufPrint(buf, " [{s}]", .{cc}) catch "";
    }

    /// GEOIP <ip> — oper lookup of the configured MaxMind database. Reports the
    /// rich GeoInfo for the address as NOTICE lines.
    pub fn handleGeoip(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.requirePriv(conn, .oper_spy)) return;
        if (parsed.param_count < 1 or parsed.paramSlice()[0].len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"GEOIP"}, "Usage: GEOIP <ip>");
            return;
        }
        const target = parsed.paramSlice()[0];
        const ip = parseGeoIp(target) orelse {
            try self.noticeTo(conn, "GEOIP: invalid IP address");
            return;
        };
        const db = self.ensureGeoip() orelse {
            try self.noticeTo(conn, "GEOIP: no database configured");
            return;
        };
        const info = (db.lookupInfo(ip) catch {
            try self.noticeTo(conn, "GEOIP: database read error");
            return;
        }) orelse {
            var nb: [128]u8 = undefined;
            const note = std.fmt.bufPrint(&nb, "GEOIP {s}: no data", .{target}) catch return;
            try self.noticeTo(conn, note);
            return;
        };

        var b: [default_reply_bytes]u8 = undefined;
        const head = std.fmt.bufPrint(&b, "GEOIP {s}: country={s} continent={s} /{d}", .{
            target,
            info.country_iso orelse "?",
            info.continent_code orelse "?",
            info.prefix_len,
        }) catch return;
        try self.noticeTo(conn, head);

        if (info.latitude != null or info.time_zone != null or info.postal_code != null) {
            const loc = std.fmt.bufPrint(&b, "  loc: {d:.4},{d:.4} +/-{d}km tz={s} postal={s}", .{
                info.latitude orelse 0,
                info.longitude orelse 0,
                info.accuracy_radius orelse 0,
                info.time_zone orelse "?",
                info.postal_code orelse "?",
            }) catch return;
            try self.noticeTo(conn, loc);
        }
        if (info.asn != null or info.isp != null or info.org != null or info.connection_type != null) {
            const net = std.fmt.bufPrint(&b, "  net: AS{d} {s} isp={s} conn={s}", .{
                info.asn orelse 0,
                info.asn_org orelse info.org orelse "?",
                info.isp orelse "?",
                info.connection_type orelse "?",
            }) catch return;
            try self.noticeTo(conn, net);
        }
        const t = info.traits;
        if (t.is_anonymous or t.is_anonymous_proxy or t.is_anonymous_vpn or t.is_hosting_provider or
            t.is_public_proxy or t.is_residential_proxy or t.is_satellite_provider or t.is_tor_exit_node)
        {
            const flags = std.fmt.bufPrint(&b, "  flags:{s}{s}{s}{s}{s}{s}{s}{s}", .{
                if (t.is_anonymous) " anon" else "",
                if (t.is_anonymous_proxy) " anon-proxy" else "",
                if (t.is_anonymous_vpn) " vpn" else "",
                if (t.is_hosting_provider) " hosting" else "",
                if (t.is_public_proxy) " public-proxy" else "",
                if (t.is_residential_proxy) " residential-proxy" else "",
                if (t.is_satellite_provider) " satellite" else "",
                if (t.is_tor_exit_node) " tor" else "",
            }) catch return;
            try self.noticeTo(conn, flags);
        }
    }

    /// Compute the aggregation prefix string for an IP: a.b.c.0/24 for IPv4,
    /// the first four hextets + ::/64 for IPv6. Non-IP hosts (e.g. "localhost")
    /// fall back to the host itself. Allocated from `a`.
    fn netPrefixString(a: std.mem.Allocator, ip: []const u8) std.mem.Allocator.Error![]const u8 {
        if (std.mem.indexOfScalar(u8, ip, ':') != null) {
            // IPv6: keep up to the first four groups, then ::/64.
            var groups: usize = 0;
            var end: usize = 0;
            var i: usize = 0;
            while (i < ip.len and groups < 4) : (i += 1) {
                if (ip[i] == ':') {
                    groups += 1;
                    end = i;
                }
            }
            if (end == 0) return a.dupe(u8, ip);
            return std.fmt.allocPrint(a, "{s}::/64", .{ip[0..end]});
        }
        // IPv4: replace the last octet with 0/24.
        const last_dot = std.mem.lastIndexOfScalar(u8, ip, '.') orelse return a.dupe(u8, ip);
        return std.fmt.allocPrint(a, "{s}.0/24", .{ip[0..last_dot]});
    }

    /// CLONES — oper report of connection clusters sharing an exact IP or a
    /// /24/64 network prefix (>= 2 members). Read-only snapshot aggregation.
    pub fn handleClones(self: *LinuxServer, conn: *ConnState) !void {
        // Operator gate is enforced declaratively by the registry (access=.oper).
        var arena = std.heap.ArenaAllocator.init(self.allocator);
        defer arena.deinit();
        const a = arena.allocator();

        // Anti-clone policy summary: the global concurrent caps, the connection
        // rate throttle, and a pointer to the per-class caps (STATS Y).
        {
            var sb: [320]u8 = undefined;
            const clones_ip = if (self.config.max_clones_per_ip == 0) "off" else "on";
            const clones_net = if (self.config.max_clones_per_net == 0) "off" else "on";
            const hdr = std.fmt.bufPrint(&sb, "CLONES policy: max_per_ip={d} ({s}) max_per_net={d} ({s}); per-class clone caps via STATS Y", .{
                self.config.max_clones_per_ip, clones_ip, self.config.max_clones_per_net, clones_net,
            }) catch "CLONES policy";
            try self.noticeTo(conn, hdr);
            if (self.config.max_clones_per_ip_net != 0) {
                var nb: [200]u8 = undefined;
                const nl = std.fmt.bufPrint(&nb, "CLONES network-wide: max_per_ip_net={d} (mesh-aggregated, salted IP hash; accounts +2, limit_exempt opers bypass); {d} hash(es) tracked", .{
                    self.config.max_clones_per_ip_net, self.mesh_clones.local.count() + self.mesh_clones.remote_total.count(),
                }) catch "CLONES network-wide";
                try self.noticeTo(conn, nl);
            }
            if (self.conn_throttle) |*t| {
                var tb: [200]u8 = undefined;
                const tl = std.fmt.bufPrint(&tb, "CLONES throttle: {d} connect(s)/{d}ms per IP (loopback + trusted-proxy exempt); {d} IP(s) tracked", .{
                    self.config.throttle_connects, self.config.throttle_window_ms, t.trackedIps(),
                }) catch "CLONES throttle";
                try self.noticeTo(conn, tl);
            } else {
                try self.noticeTo(conn, "CLONES throttle: disabled (set [limits] throttle_connects)");
            }
        }

        var conns: std.ArrayListUnmanaged(svc_clonescan.Connection) = .empty;
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            const c = entry.value;
            if (!c.session.registered()) continue;
            if (c.s2s != null or c.s2s_secured != null) continue;
            const ip = c.session.realHost();
            if (ip.len == 0) continue;
            const prefix = netPrefixString(a, ip) catch continue;
            conns.append(a, .{
                .account = c.session.account(),
                .ip = ip,
                .prefix = prefix,
                .nick = c.session.displayName(),
            }) catch break;
        }

        var report = svc_clonescan.scan(self.allocator, conns.items, .{}) catch {
            try self.noticeTo(conn, "CLONES: scan failed");
            return;
        };
        defer report.deinit();

        if (report.clusterCount() == 0) {
            try self.noticeTo(conn, "CLONES: no clone clusters found");
            return;
        }
        for (report.clusters) |cluster| {
            const kind_str = switch (cluster.kind) {
                .exact_ip => "ip",
                .net_prefix => "net",
            };
            var hb: [256]u8 = undefined;
            const header = std.fmt.bufPrint(&hb, "CLONES {s} {s} ({d} clients)", .{ kind_str, cluster.key, cluster.members.len }) catch continue;
            try self.noticeTo(conn, header);
            for (cluster.members) |member| {
                var gb: [96]u8 = undefined;
                const geo = self.geoTag(member.ip, &gb);
                var mb: [416]u8 = undefined;
                const line = std.fmt.bufPrint(&mb, "  {s} {s} {s}{s}", .{ member.nick, member.ip, member.account orelse "*", geo }) catch continue;
                try self.noticeTo(conn, line);
            }
        }
        try self.noticeTo(conn, "CLONES: end of report");
    }

    /// Whether `conn` may moderate `channel`: server opers or channel operators.
    fn canModerateChannel(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8) bool {
        if (conn.session.isOper()) return true;
        const mm = self.world.memberModes(channel, worldIdFromClient(id)) orelse return false;
        return mm.isOperator();
    }

    fn handleServerAccessRequest(self: *LinuxServer, conn: *ConnState, req: ircx_saccess.Request) !void {
        if (!self.requirePriv(conn, .service_admin)) return;
        const ctx = ircx_saccess.ReplyContext{ .server_name = self.serverName(), .requester = conn.session.displayName() };
        var buf: [default_reply_bytes]u8 = undefined;
        switch (req) {
            .list => |entry_type| {
                if (ircx_saccess.buildAccessStart(&buf, ctx)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
                var entries: [256]ircx_saccess.Entry = undefined;
                const rows = self.saccess.list(entry_type, &entries) catch entries[0..0];
                for (rows) |entry| {
                    var ebuf: [default_reply_bytes]u8 = undefined;
                    const line = ircx_saccess.buildAccessEntry(&ebuf, ctx, entry) catch continue;
                    try appendToConn(conn, line);
                }
                var end_buf: [default_reply_bytes]u8 = undefined;
                if (ircx_saccess.buildAccessEnd(&end_buf, ctx)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
            },
            .add => |entry| {
                self.saccess.add(entry) catch {
                    try queueNumeric(conn, .ERR_TOOMANYACCESSES, &.{"*"}, "Cannot add SACCESS entry");
                    return;
                };
                // Durable mirror: persist AFTER the live add succeeds so the
                // entry replays on the next boot.
                self.persistSaccessMirror(entry);
                if (ircx_saccess.buildAccessAdd(&buf, ctx, entry)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
            },
            .delete => |entry| {
                const removed = self.saccess.remove(entry.entry_type, entry.mask) catch false;
                // Persist the delete unconditionally so a stale persisted entry
                // (e.g. one that pre-dated this process) is also reaped.
                self.deleteSaccessMirror(entry.entry_type, entry.mask);
                _ = removed;
                if (ircx_saccess.buildAccessDelete(&buf, ctx, entry)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
            },
            .clear => |entry_type| {
                _ = self.saccess.clear(entry_type);
                self.clearSaccessMirror(entry_type);
                if (ircx_saccess.buildAccessEnd(&buf, ctx)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
            },
        }
    }

    pub fn handleSaccess(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const req = ircx_saccess.parseSaccess(parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"SACCESS"}, "Invalid SACCESS");
            return;
        };
        try self.handleServerAccessRequest(conn, req);
    }

    fn auditAccessChange(self: *LinuxServer, conn: *ConnState, action: svc_operaudit.Action, channel: []const u8, detail: []const u8) void {
        const proof_id = self.recordOperAudit(conn.session.displayName(), action, channel, detail);
        var event_buf: [default_reply_bytes]u8 = undefined;
        const event_note = if (proof_id) |pid|
            std.fmt.bufPrint(&event_buf, "ACCESS {s} {s} proof={s}", .{ channel, detail, pid[0..] }) catch return
        else
            std.fmt.bufPrint(&event_buf, "ACCESS {s} {s}", .{ channel, detail }) catch return;
        self.publishOperEvent(.oper_action, .notice, event_note) catch {};
    }

    pub fn handleAccess(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count >= 1 and std.mem.eql(u8, parsed.paramSlice()[0], "*")) {
            const req = ircx_saccess.parseAccess(parsed.paramSlice()) catch {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"ACCESS"}, "Invalid ACCESS");
                return;
            };
            try self.handleServerAccessRequest(conn, req);
            return;
        }
        const req = ircx_access_store.parse(parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"ACCESS"}, "Invalid ACCESS");
            return;
        };
        // Refresh the store clock so ADD stamps a correct absolute expiry and
        // LIST/CLEAR see currently-lapsed timed entries as gone.
        self.access.now_seconds = self.accessNowSeconds();
        const ctx = ircx_access_store.ReplyContext{ .server_name = self.serverName(), .requester = conn.session.displayName() };
        var buf: [default_reply_bytes]u8 = undefined;
        switch (req) {
            .list => |sel| {
                if (!self.accessCanManage(id, conn, sel.channel, sel.level)) {
                    try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{sel.channel}, "You're not channel operator");
                    return;
                }
                if (ircx_access_store.buildAccessStart(&buf, ctx, sel.channel)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
                var views: [ircx_access_store.DEFAULT_MAX_ENTRIES]ircx_access_store.EntryView = undefined;
                const rows = self.access.listMatching(sel, &views) catch views[0..0];
                for (rows) |ev| {
                    var ebuf: [default_reply_bytes]u8 = undefined;
                    const eln = ircx_access_store.buildAccessEntry(&ebuf, ctx, ev) catch continue;
                    try appendToConn(conn, eln);
                }
                var endbuf: [default_reply_bytes]u8 = undefined;
                if (ircx_access_store.buildAccessEnd(&endbuf, ctx, sel.channel)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
            },
            .add => |a| {
                if (!self.accessCanManage(id, conn, a.channel, a.level)) {
                    try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{a.channel}, "You're not channel operator");
                    return;
                }
                if (overrideActive(conn) and self.accessOverrideWouldBypass(id, a.channel, a.level)) {
                    var detail_buf: [192]u8 = undefined;
                    const detail = std.fmt.bufPrint(&detail_buf, "ADD {s} {s}", .{ a.level.token(), a.mask }) catch "ADD";
                    self.auditOverrideUse(conn, "ACCESS", a.channel, detail);
                }
                self.access.add(a.channel, a.level, a.mask, conn.session.displayName(), a.timeout) catch {
                    try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{a.channel}, "Cannot add ACCESS entry");
                    return;
                };
                const ev = ircx_access_store.EntryView{
                    .channel = a.channel,
                    .level = a.level,
                    .mask = a.mask,
                    .set_by = conn.session.displayName(),
                    .duration = a.timeout,
                };
                if (ircx_access_store.buildAccessAdd(&buf, ctx, ev)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
                var detail_buf: [256]u8 = undefined;
                const detail = std.fmt.bufPrint(&detail_buf, "ADD {s} {s}", .{ a.level.token(), a.mask }) catch "ADD";
                self.auditAccessChange(conn, .access_add, a.channel, detail);
            },
            .delete => |d| {
                if (!self.accessCanManage(id, conn, d.channel, d.level)) {
                    try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{d.channel}, "You're not channel operator");
                    return;
                }
                if (overrideActive(conn) and self.accessOverrideWouldBypass(id, d.channel, d.level)) {
                    var detail_buf: [192]u8 = undefined;
                    const detail = std.fmt.bufPrint(&detail_buf, "DELETE {s} {s}", .{ d.level.token(), d.mask }) catch "DELETE";
                    self.auditOverrideUse(conn, "ACCESS", d.channel, detail);
                }
                _ = self.access.remove(d.channel, d.level, d.mask) catch false;
                if (ircx_access_store.buildAccessDelete(&buf, ctx, d)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
                var detail_buf: [256]u8 = undefined;
                const detail = std.fmt.bufPrint(&detail_buf, "DELETE {s} {s}", .{ d.level.token(), d.mask }) catch "DELETE";
                self.auditAccessChange(conn, .access_delete, d.channel, detail);
            },
            .clear => |sel| {
                if (!self.accessCanManage(id, conn, sel.channel, sel.level)) {
                    try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{sel.channel}, "You're not channel operator");
                    return;
                }
                if (overrideActive(conn) and self.accessOverrideWouldBypass(id, sel.channel, sel.level)) {
                    var detail_buf: [64]u8 = undefined;
                    const detail = if (sel.level) |level|
                        (std.fmt.bufPrint(&detail_buf, "CLEAR {s}", .{level.token()}) catch "CLEAR")
                    else
                        "CLEAR *";
                    self.auditOverrideUse(conn, "ACCESS", sel.channel, detail);
                }
                _ = self.access.clear(sel) catch 0;
                if (ircx_access_store.buildAccessEnd(&buf, ctx, sel.channel)) |line| {
                    try appendToConn(conn, line);
                } else |_| {}
                var detail_buf: [64]u8 = undefined;
                const detail = if (sel.level) |level|
                    (std.fmt.bufPrint(&detail_buf, "CLEAR {s}", .{level.token()}) catch "CLEAR")
                else
                    "CLEAR *";
                self.auditAccessChange(conn, .access_clear, sel.channel, detail);
            },
            .copy => |c| {
                // A template copy writes every level including FOUNDER, so gate it
                // on the FOUNDER tier of the DESTINATION rather than the per-level
                // rank a single ADD needs — otherwise an op could seed itself a
                // FOUNDER entry by copying a channel it controls. The source is
                // gated as a read (LIST rank) for the same reason ACCESS LIST is:
                // an ACL is not public.
                if (!self.accessCanManage(id, conn, c.destination, .founder)) {
                    try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{c.destination}, "You're not channel operator");
                    return;
                }
                if (!self.accessCanManage(id, conn, c.source, null)) {
                    try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{c.source}, "You're not channel operator");
                    return;
                }
                if (overrideActive(conn) and
                    (self.accessOverrideWouldBypass(id, c.destination, .founder) or
                        self.accessOverrideWouldBypass(id, c.source, null)))
                {
                    var od_buf: [192]u8 = undefined;
                    const od = std.fmt.bufPrint(&od_buf, "COPY {s}", .{c.source}) catch "COPY";
                    self.auditOverrideUse(conn, "ACCESS", c.destination, od);
                }
                const result = self.access.copyFrom(c.destination, c.source, c.mode) catch {
                    // Fail closed and SAY so: `copyFrom` sizes the template up
                    // front, so a store that cannot fit it leaves the destination
                    // untouched rather than half-copied.
                    try self.failReply(conn, "ACCESS", "ACCESS_COPY_FAILED", "Cannot copy ACCESS template");
                    return;
                };
                // Deliberately NO bare 805 here. A client folds 803 -> 804* -> 805
                // and commits whatever it buffered, so an 805 with no preceding
                // burst commits an EMPTY list — which is correct after CLEAR but
                // would wipe the client's view of an ACL that COPY just populated.
                // The NOTE reports the outcome; the client re-LISTs to see it.
                var note_buf: [192]u8 = undefined;
                const note = std.fmt.bufPrint(
                    &note_buf,
                    "copied {d} entries from {s}, removed {d}; re-run ACCESS {s} LIST",
                    .{ result.copied, c.source, result.removed, c.destination },
                ) catch "ACCESS template copied";
                try self.noteReply(conn, "ACCESS", "ACCESS_COPIED", note);
                var detail_buf: [256]u8 = undefined;
                const detail = std.fmt.bufPrint(&detail_buf, "COPY {s} {s} copied={d} removed={d}", .{
                    c.source,
                    if (c.mode == .replace) "REPLACE" else "MERGE",
                    result.copied,
                    result.removed,
                }) catch "COPY";
                self.auditAccessChange(conn, .access_copy, c.destination, detail);
            },
        }
    }

    /// Effective IRCX PROP access level for `conn` mutating `entity`, or null when
    /// the client may not write it. Opers act as sysop; channel/member props need
    /// channel-operator; user props need self-ownership.
    fn propAccess(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, entity: ircx_prop_store.Entity) ?ircx_prop_store.AccessLevel {
        if (conn.session.isOper()) return .sysop;
        switch (entity.kind) {
            .channel => {
                const mm = self.world.memberModes(entity.id, worldIdFromClient(id)) orelse return null;
                return if (mm.isOperator()) .owner else null;
            },
            .member => {
                const split = std.mem.indexOfScalar(u8, entity.id, ':') orelse return null;
                const chan = entity.id[0..split];
                const mm = self.world.memberModes(chan, worldIdFromClient(id)) orelse return null;
                return if (mm.isOperator()) .owner else null;
            },
            .user => return if (std.ascii.eqlIgnoreCase(entity.id, conn.session.displayName())) .member else null,
        }
    }

    fn propOverrideWouldBypass(self: *LinuxServer, id: client_model.ClientId, entity: ircx_prop_store.Entity) bool {
        return switch (entity.kind) {
            .channel => blk: {
                const mm = self.world.memberModes(entity.id, worldIdFromClient(id)) orelse break :blk true;
                break :blk !mm.isOperator();
            },
            .member => blk: {
                const split = std.mem.indexOfScalar(u8, entity.id, ':') orelse break :blk true;
                const chan = entity.id[0..split];
                const mm = self.world.memberModes(chan, worldIdFromClient(id)) orelse break :blk true;
                break :blk !mm.isOperator();
            },
            .user => false,
        };
    }

    /// Whether `key` on `entity` is an IRCX secret channel property (the *KEY
    /// family), which must not be disclosed to clients lacking the read tier.
    fn propIsSecret(entity: ircx_prop_store.Entity, key: []const u8) bool {
        if (entity.kind != .channel) return false;
        const info = ircx_prop_store.channelPropInfo(key) orelse return false;
        return info.secret;
    }

    /// Minimum channel member rank required to READ a secret channel key, in the
    /// per-tier visibility model: OWNERKEY → owner, HOSTKEY → op, VOICEKEY →
    /// voice, MEMBERKEY → any member. Ranks match `chanmode.MemberModes.rank()`
    /// (founder 4 > owner 3 > op 2 > voice 1 > plain member 0).
    fn secretKeyMinRank(key: []const u8) u8 {
        const k = ircx_prop_store.channelPropKey(key) orelse return 0;
        return switch (k) {
            .founderkey => chanmode.rankOfMode(.founder),
            .ownerkey => chanmode.rankOfMode(.owner),
            .hostkey => chanmode.rankOfMode(.op),
            .voicekey => chanmode.rankOfMode(.voice),
            else => 0, // memberkey (any member) + any non-tier key
        };
    }

    /// Whether member `id`/`conn` may READ the secret key `key` on `entity`.
    /// Channel keys use the per-tier rank gate (`secretKeyMinRank`); opers always
    /// may; non-channel entities fall back to the coarse `propAccess` gate. This
    /// is the single source of truth for secret-key visibility — PROP GET/LIST
    /// and the PROP-change notify fanout MUST both use it so a member is never
    /// notified of a value they could not GET.
    fn maySeeSecretKey(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, entity: ircx_prop_store.Entity, key: []const u8) bool {
        if (conn.session.isOper()) return true;
        if (entity.kind != .channel) return self.propAccess(id, conn, entity) != null;
        const mm = self.world.memberModes(entity.id, worldIdFromClient(id)) orelse return false;
        return mm.rank() >= secretKeyMinRank(key);
    }

    /// Fan a PROP set/delete out to LOCAL IRCX clients permitted to see it,
    /// mirroring PROP GET visibility exactly (a client is never notified of a
    /// value it could not GET). Wire form `:<setter-prefix> PROP <entity> <key>
    /// :<value>` (empty value = delete). The IRCX gate (`conn.ircx`) is what makes
    /// PROP-notify "just work"; there is no separate capability. Reactor-local:
    /// peer links carry the signed mesh fact separately, so a target on another
    /// shard converges via the S2S burst, not this fanout.
    fn notifyLocalPropChange(
        self: *LinuxServer,
        setter_conn: *ConnState,
        entity: ircx_prop_store.Entity,
        key: []const u8,
        value: []const u8,
    ) void {
        var prefix_buf: [256]u8 = undefined;
        const prefix = clientPrefix(setter_conn, &prefix_buf) catch return;
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&line_buf, ":{s} PROP {s} {s} :{s}\r\n", .{ prefix, entity.id, key, value }) catch return;
        switch (entity.kind) {
            .channel => self.fanChannelPropNotify(entity.id, key, line, setter_conn),
            .member => {
                // member entity id is "<channel>:<nick>" — fan to the channel.
                const split = std.mem.indexOfScalar(u8, entity.id, ':') orelse return;
                self.fanChannelPropNotify(entity.id[0..split], key, line, setter_conn);
            },
            .user => self.fanUserPropNotify(entity.id, line, setter_conn),
        }
    }

    /// Deliver `line` to every LOCAL IRCX member of `channel` allowed to see
    /// `key` (per-tier rank gate for secret keys, all members otherwise), except
    /// `except` if given (the local setter, who gets the direct echo). `except`
    /// is null for mesh-originated changes (no local setter).
    fn fanChannelPropNotify(self: *LinuxServer, channel: []const u8, key: []const u8, line: []const u8, except: ?*ConnState) void {
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const secret = propIsSecret(entity, key);
        const min_rank: u8 = if (secret) secretKeyMinRank(key) else 0;
        var members = self.world.memberIterator(channel) orelse return;
        while (members.next()) |member| {
            if (secret) {
                const mm = self.world.memberModes(channel, member.*) orelse continue;
                if (mm.rank() < min_rank) continue;
            }
            const mid = clientIdFromWorld(member.*);
            const mconn = self.connFor(mid) orelse continue;
            if (except) |e| if (mconn == e) continue;
            if (!mconn.ircx) continue;
            self.deliver(mid, line) catch continue;
        }
    }

    /// Deliver `line` to the target user (if local + IRCX) and to every local
    /// IRCX client sharing a channel with the target (deduped), except `except`
    /// if given (null for mesh-originated changes — no local setter).
    fn fanUserPropNotify(self: *LinuxServer, target_nick: []const u8, line: []const u8, except: ?*ConnState) void {
        const twid = self.world.findNick(target_nick) orelse return;
        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();
        const tid = clientIdFromWorld(twid);
        if (self.connFor(tid)) |tconn| {
            const is_except = if (except) |e| tconn == e else false;
            if (!is_except and tconn.ircx) {
                seen.put(@as(u64, @bitCast(tid)), {}) catch {};
                self.deliver(tid, line) catch {};
            }
        }
        var it = self.world.channels.iterator();
        while (it.next()) |entry| {
            if (!entry.value_ptr.members.contains(twid)) continue;
            var members = self.world.memberIterator(entry.key_ptr.*) orelse continue;
            while (members.next()) |member| {
                const mid = clientIdFromWorld(member.*);
                const skey = @as(u64, @bitCast(mid));
                if (seen.contains(skey)) continue;
                seen.put(skey, {}) catch {};
                const mconn = self.connFor(mid) orelse continue;
                if (except) |e| if (mconn == e) continue;
                if (!mconn.ircx) continue;
                self.deliver(mid, line) catch continue;
            }
        }
    }

    /// Computed/linked IRCX channel built-in property reads. These reflect live
    /// channel state, not the generic PROP store: NAME (the channel), MEMBERCOUNT
    /// (live count), MEMBERLIMIT (the +l limit), MEMBERKEY (the +k key). MEMBERKEY
    /// is secret and reached only after the caller's per-tier read gate passes.
    /// Returns a value rendered into `buf`, or null to fall through to the store.
    fn channelBuiltinGet(self: *LinuxServer, entity: ircx_prop_store.Entity, key: []const u8, buf: []u8) ?[]const u8 {
        if (entity.kind != .channel) return null;
        if (std.ascii.eqlIgnoreCase(key, "NAME")) return entity.id;
        if (std.ascii.eqlIgnoreCase(key, "OID")) {
            const oid = self.world.channelOid(entity.id) orelse return null;
            if (oid == 0) return null;
            // IRCX object id: '0' type prefix + 8 hex digits.
            return std.fmt.bufPrint(buf, "0{x:0>8}", .{oid}) catch null;
        }
        if (std.ascii.eqlIgnoreCase(key, "CREATION")) {
            const created = self.world.channelCreatedUnix(entity.id) orelse return null;
            if (created == 0) return null;
            return std.fmt.bufPrint(buf, "{d}", .{created}) catch null;
        }
        if (std.ascii.eqlIgnoreCase(key, "MEMBERCOUNT")) {
            return std.fmt.bufPrint(buf, "{d}", .{self.world.memberCount(entity.id)}) catch null;
        }
        if (std.ascii.eqlIgnoreCase(key, "MEMBERLIMIT")) {
            const limit = self.world.channelLimit(entity.id) orelse return null;
            return std.fmt.bufPrint(buf, "{d}", .{limit}) catch null;
        }
        // MEMBERKEY is the live +k channel key (linked, not stored). It is secret,
        // so this is only reached after the caller's maySeeSecretKey gate passes
        // (the sole caller is the gated PROP GET path); a member-tier requester or
        // oper may read it — matching `MODE #chan`, which shows +k to members.
        if (std.ascii.eqlIgnoreCase(key, "MEMBERKEY")) {
            const k = self.world.channelKey(entity.id) orelse return null;
            if (k.len == 0) return null;
            if (k.len > buf.len) return null;
            @memcpy(buf[0..k.len], k);
            return buf[0..k.len];
        }
        return null;
    }

    fn userBuiltinProviderForKey(key: []const u8) ?ircx_prop_providers.Provider {
        const lookup_key: []const u8 = if (std.ascii.eqlIgnoreCase(key, "MEMBEROF")) "MEMBER_OF" else key;
        var registry = ircx_prop_providers.ProviderRegistry.init();
        defer registry.deinit();
        const provider = registry.lookup(lookup_key) orelse return null;
        if (provider.scope != .user) return null;
        return provider;
    }

    fn isGeoUserProviderName(name: []const u8) bool {
        return std.ascii.eqlIgnoreCase(name, "country") or
            std.ascii.eqlIgnoreCase(name, "region") or
            std.ascii.eqlIgnoreCase(name, "city") or
            std.ascii.eqlIgnoreCase(name, "asn") or
            std.ascii.eqlIgnoreCase(name, "asorg");
    }

    fn isReadOnlyGeoUserBuiltinKey(key: []const u8) bool {
        const provider = userBuiltinProviderForKey(key) orelse return false;
        return isGeoUserProviderName(provider.name);
    }

    fn renderUserProviderValue(value: ircx_prop_providers.PropValue, buf: []u8) ?[]const u8 {
        return switch (value) {
            .text => |text| text,
            .number => |n| std.fmt.bufPrint(buf, "{d}", .{n}) catch null,
            .boolean => |flag| if (flag) "1" else "0",
            .list => |items| blk: {
                var w: usize = 0;
                for (items) |item| {
                    const need = item.len + @as(usize, if (w == 0) 0 else 1);
                    if (w + need > buf.len) break;
                    if (w != 0) {
                        buf[w] = ' ';
                        w += 1;
                    }
                    @memcpy(buf[w .. w + item.len], item);
                    w += item.len;
                }
                break :blk buf[0..w];
            },
        };
    }

    fn fillUserGeoSnapshot(
        self: *LinuxServer,
        target_nick: []const u8,
        tconn: *const ConnState,
        snapshot: *ircx_prop_providers.Snapshot,
        country_buf: *[4]u8,
    ) void {
        const stored_country = self.metaValue(target_nick, "country");
        if (stored_country.len != 0) snapshot.geo_country = stored_country;

        const ip = parseGeoIp(tconn.session.realHost()) orelse return;
        if (self.ensureGeoip()) |db| {
            if (snapshot.geo_country == null) {
                snapshot.geo_country = db.lookupCountry(ip, country_buf) catch null;
            }
            snapshot.geo_city = db.lookupName(ip, "city", "en") catch null;
            snapshot.geo_region = db.lookupString(ip, &.{ "subdivisions", "0", "names", "en" }) catch null;
        }

        const asn_info = self.lookupGeoAsn(ip);
        snapshot.geo_asn = asn_info.asn;
        snapshot.geo_asorg = asn_info.asorg;
    }

    /// Welcome-burst origin NOTICE: "connecting from <City>, <Region>, <Country> ·
    /// AS<n> (<org>)" derived from the client's OWN real IP. Shown only to the
    /// connecting user (privacy-safe; the GeoIP PROP keys gate cross-user reads).
    /// Omitted entirely when GeoIP yields nothing.
    fn emitGeoOriginNotice(self: *LinuxServer, conn: *ConnState) void {
        var snapshot = ircx_prop_providers.Snapshot{};
        var country_buf: [4]u8 = undefined;
        self.fillUserGeoSnapshot(conn.session.displayName(), conn, &snapshot, &country_buf);

        // Location segment: "City, Region, Country" (skip empty parts).
        var geo_buf: [256]u8 = undefined;
        var geo_len: usize = 0;
        for ([_][]const u8{ snapshot.geo_city orelse "", snapshot.geo_region orelse "", snapshot.geo_country orelse "" }) |p| {
            if (p.len == 0) continue;
            const seg = std.fmt.bufPrint(geo_buf[geo_len..], "{s}{s}", .{ if (geo_len == 0) "" else ", ", p }) catch break;
            geo_len += seg.len;
        }
        const geo = geo_buf[0..geo_len];

        // Network segment: "AS<n> (<org>)".
        var asn_buf: [80]u8 = undefined;
        const asorg = snapshot.geo_asorg orelse "";
        const asn: []const u8 = if (snapshot.geo_asn) |n|
            (if (asorg.len != 0)
                std.fmt.bufPrint(&asn_buf, "AS{d} ({s})", .{ n, asorg }) catch ""
            else
                std.fmt.bufPrint(&asn_buf, "AS{d}", .{n}) catch "")
        else
            "";

        if (geo.len == 0 and asn.len == 0) return;

        var out: [default_reply_bytes]u8 = undefined;
        const line = (if (geo.len != 0 and asn.len != 0)
            std.fmt.bufPrint(&out, ":{s} NOTICE {s} :connecting from {s} | {s}\r\n", .{ self.serverName(), conn.session.displayName(), geo, asn })
        else if (geo.len != 0)
            std.fmt.bufPrint(&out, ":{s} NOTICE {s} :connecting from {s}\r\n", .{ self.serverName(), conn.session.displayName(), geo })
        else
            std.fmt.bufPrint(&out, ":{s} NOTICE {s} :connecting via {s}\r\n", .{ self.serverName(), conn.session.displayName(), asn })) catch return;
        emitReplyLine(conn, line) catch {};
    }

    fn userProfileValue(self: *LinuxServer, entity: ircx_prop_store.Entity, key: []const u8) ?[]const u8 {
        const ev = self.props.getProp(entity, key) catch return null;
        return if (ev.value.len == 0) null else ev.value;
    }

    fn fillUserProfileSnapshot(self: *LinuxServer, entity: ircx_prop_store.Entity, snapshot: *ircx_prop_providers.Snapshot) bool {
        var filled = false;
        if (self.userProfileValue(entity, "display")) |value| {
            snapshot.profile_display_name = value;
            filled = true;
        }
        if (self.userProfileValue(entity, "real")) |value| {
            snapshot.profile_real_name = value;
            filled = true;
        }
        if (self.userProfileValue(entity, "title")) |value| {
            snapshot.profile_title = value;
            filled = true;
        }
        if (self.userProfileValue(entity, "location")) |value| {
            snapshot.profile_location = value;
            filled = true;
        }
        if (self.userProfileValue(entity, "note")) |value| {
            snapshot.profile_note = value;
            filled = true;
        }
        if (self.userProfileValue(entity, "URL")) |value| {
            snapshot.profile_url = value;
            filled = true;
        }
        if (self.userProfileValue(entity, "GENDER")) |value| {
            snapshot.profile_gender = value;
            filled = true;
        }
        if (self.userProfileValue(entity, "PICTURE")) |value| {
            snapshot.profile_picture = value;
            filled = true;
        }
        if (self.userProfileValue(entity, "BIO")) |value| {
            snapshot.profile_bio = value;
            filled = true;
        }
        if (self.userProfileValue(entity, "EMAIL")) |value| {
            snapshot.profile_email = value;
            filled = true;
        }
        return filled;
    }

    /// Computed IRCX built-in properties for a `user` entity. GET-only (computed,
    /// not stored), consulted ahead of the generic store:
    ///   - MEMBER_OF (aka MEMBEROF): the channels the target is in, space-
    ///     separated, with the WHOIS visibility filter (secret/private channels
    ///     omitted unless the requester is the target, an operator, or a member).
    ///   - ACCOUNT: the target's logged-in services account. Public (mirrors
    ///     WHOIS 330 / `account-tag`), so no visibility gate. Local target only.
    ///   - USER_PROFILE: a joined view of stored profile fields.
    ///   - COUNTRY/REGION/CITY/ASN/ASORG: read-only GeoIP fields from the target
    ///     connection, visible only to the target user or an operator. Missing
    ///     GeoIP data renders as an empty value.
    fn userBuiltinGet(self: *LinuxServer, entity: ircx_prop_store.Entity, key: []const u8, buf: []u8, requester_id: client_model.ClientId, conn: *const ConnState) ?[]const u8 {
        if (entity.kind != .user) return null;
        const provider = userBuiltinProviderForKey(key) orelse return null;
        const is_member_of = std.ascii.eqlIgnoreCase(provider.name, "member_of");
        const is_account = std.ascii.eqlIgnoreCase(provider.name, "account");
        const is_geo = isGeoUserProviderName(provider.name);
        const is_profile = std.ascii.eqlIgnoreCase(provider.name, "user_profile");
        if (!is_member_of and !is_account and !is_geo and !is_profile) return null;

        var snapshot = ircx_prop_providers.Snapshot{};
        var memberships: [64][]const u8 = undefined;
        var country_buf: [4]u8 = undefined;

        if (is_profile) {
            if (!self.fillUserProfileSnapshot(entity, &snapshot)) return null;
        } else if (is_member_of) {
            const target_wid = self.world.findNick(entity.id) orelse return null;
            const requester_wid = worldIdFromClient(requester_id);
            const sees_all = conn.session.isOper() or requester_wid.eql(target_wid);
            var names: [64][]const u8 = undefined;
            const n = self.world.channelsOf(target_wid, &names);
            var visible: usize = 0;
            for (names[0..n]) |cn| {
                if (!sees_all and self.channelHiddenFromWhois(cn, requester_wid)) continue;
                memberships[visible] = cn;
                visible += 1;
            }
            snapshot.member_of = memberships[0..visible];
        } else {
            const target_wid = self.world.findNick(entity.id) orelse return null;
            const requester_wid = worldIdFromClient(requester_id);
            const target_cid = client_model.ClientId{ .shard = target_wid.shard, .slot = target_wid.slot, .gen = target_wid.gen };
            const tconn = self.connFor(target_cid) orelse return null;
            if (is_account) {
                const acct = tconn.session.account() orelse return null;
                if (acct.len == 0) return null;
                snapshot.account_name = acct;
            } else {
                if (!(conn.session.isOper() or requester_wid.eql(target_wid))) return null;
                self.fillUserGeoSnapshot(tconn.session.displayName(), tconn, &snapshot, &country_buf);
            }
        }

        const value = provider.read(&snapshot, buf) catch return null;
        return renderUserProviderValue(value, buf);
    }

    /// Computed/linked IRCX channel built-in property writes. MEMBERKEY <-> +k
    /// channel key; MEMBERLIMIT <-> +l limit. Returns true if the key is a linked
    /// built-in (and was applied), false to fall through to the generic store.
    /// Access is gated by the caller (propAccess == channel-op/owner).
    const BuiltinSet = enum { not_handled, applied, bad_value };

    fn channelBuiltinSet(self: *LinuxServer, entity: ircx_prop_store.Entity, key: []const u8, value: []const u8, deleting: bool) BuiltinSet {
        if (entity.kind != .channel) return .not_handled;
        if (std.ascii.eqlIgnoreCase(key, "MEMBERKEY")) {
            // MEMBERKEY is a live +k set-path, so it honors the advertised KEYLEN
            // cap too — bounded by the stricter of the 31-byte draft cap and the
            // configured keylen, keeping enforce-then-advertise honest when an
            // operator lowers keylen below 31.
            const member_key_cap: usize = @min(@as(usize, 31), self.config.keylen);
            if (!deleting and value.len > member_key_cap) return .bad_value;
            self.world.setChannelKey(entity.id, if (deleting) null else value) catch return .bad_value;
            return .applied;
        }
        if (std.ascii.eqlIgnoreCase(key, "MEMBERLIMIT")) {
            if (deleting) {
                self.world.setChannelLimit(entity.id, null) catch return .bad_value;
            } else {
                const limit = std.fmt.parseInt(u32, value, 10) catch return .bad_value;
                self.world.setChannelLimit(entity.id, limit) catch return .bad_value;
            }
            return .applied;
        }
        if (std.ascii.eqlIgnoreCase(key, "EPHEMERAL")) {
            // Ephemeral-room message TTL, in whole seconds. Validate here but
            // return `.not_handled` so the value PERSISTS + PROPAGATES through
            // the generic (signed, mesh-replicated) channel-prop store; the
            // history-replay filter reads it back per request. 0 = disable.
            if (deleting) return .not_handled;
            const secs = std.fmt.parseInt(u64, value, 10) catch return .bad_value;
            if (secs != 0 and (secs < ephemeral_min_secs or secs > ephemeral_max_secs)) return .bad_value;
            return .not_handled;
        }
        if (std.ascii.eqlIgnoreCase(key, "SLOWMODE")) {
            // Minimum gap between one member's channel messages, in whole seconds.
            // 0 or delete clears. The value stays in the generic prop store so the
            // property checkpoint restores it across USR2.
            if (deleting) return .not_handled;
            const secs = std.fmt.parseInt(u64, value, 10) catch return .bad_value;
            if (secs > slowmode_max_secs) return .bad_value;
            return .not_handled;
        }
        if (std.ascii.eqlIgnoreCase(key, "SLOWVOICE")) {
            // "0" makes voice and channel operators wait out the gap. "1" or
            // delete keeps them exempt. Network operators are always exempt.
            if (deleting) return .not_handled;
            if (!std.mem.eql(u8, value, "0") and !std.mem.eql(u8, value, "1")) return .bad_value;
            return .not_handled;
        }
        if (std.ascii.eqlIgnoreCase(key, "RETAIN")) {
            // How long this channel keeps a history row, in whole seconds.
            // 0 or delete turns expiry off. The value stays in the generic
            // prop store. Expiry deletes the row; EPHEMERAL only hides replay.
            if (deleting) return .not_handled;
            const secs = std.fmt.parseInt(u64, value, 10) catch return .bad_value;
            if (secs != 0 and (secs < retain_min_secs or secs > retain_max_secs)) return .bad_value;
            return .not_handled;
        }
        if (std.ascii.eqlIgnoreCase(key, "PINS")) {
            // Pinned messages: a comma-separated list of msgids. Op-gated (all
            // channel prop writes are), bounded here, then persisted+propagated
            // as a plain prop (`.not_handled`). Clients render a pins drawer and
            // resolve each msgid against their history. 0-length = no pins.
            if (deleting) return .not_handled;
            if (!validPinsValueWithLimits(value, self.config.media_pins_max_per_channel, self.config.media_pins_max_msgid_bytes)) return .bad_value;
            return .not_handled;
        }
        if (std.ascii.eqlIgnoreCase(key, topic_tag.registry_key)) {
            // Per-channel topic registry: a comma-separated bounded set of
            // conversation labels. Auto-added by the daemon on first use and
            // op-manageable via PROP; validated here, then persisted+propagated
            // as a plain prop (`.not_handled`), like PINS/EPHEMERAL. Empty clears.
            if (deleting) return .not_handled;
            if (!topic_tag.validRegistryValue(value)) return .bad_value;
            return .not_handled;
        }
        if (isAiPolicyProp(key)) {
            // Room-level AI consent policy. Persist + mesh-propagate through the
            // ordinary channel PROP CRDT; validate here so later AI/plugin
            // paths can trust the values as boolean flags.
            if (deleting) return .not_handled;
            if (!validAiPolicyValue(value)) return .bad_value;
            return .not_handled;
        }
        if (std.ascii.eqlIgnoreCase(key, e2ee_policy.policy_prop)) {
            // Room-level E2EE policy. Persist + mesh-propagate through the
            // ordinary signed channel PROP CRDT; delivery reads it at send time.
            if (deleting) return .not_handled;
            if (!e2ee_policy.validPolicyValue(value)) return .bad_value;
            return .not_handled;
        }
        if (std.ascii.eqlIgnoreCase(key, sealed_room.prop_key)) {
            // Sealed rooms refuse a clear roster. Absent stays ordinary.
            // Delete clears the prop. Any other value is rejected.
            if (deleting) return .not_handled;
            if (sealed_room.visibilityValue(value) == null) return .bad_value;
            return .not_handled;
        }
        if (std.ascii.eqlIgnoreCase(key, "history-policy")) {
            // Aegis-lite room policy for history visibility. Persist as a normal
            // signed channel PROP; CHATHISTORY reads the value at request time.
            if (deleting) return .not_handled;
            if (!validHistoryPolicyValue(value)) return .bad_value;
            return .not_handled;
        }
        return .not_handled;
    }

    pub const AiPolicy = enum { unspecified, no_ai, local_only, server_ai_ok };
    pub const AiPolicyUse = enum { local_inference, server_plaintext };
    pub const AiPolicyDeny = enum { no_ai, local_only, server_ai_not_enabled };
    pub const AiPolicyDecision = struct {
        policy: AiPolicy,
        allowed: bool,
        deny: ?AiPolicyDeny = null,
    };

    fn isAiPolicyProp(key: []const u8) bool {
        return std.ascii.eqlIgnoreCase(key, "no-ai") or
            std.ascii.eqlIgnoreCase(key, "local-only") or
            std.ascii.eqlIgnoreCase(key, "server-ai-ok");
    }

    fn validAiPolicyValue(value: []const u8) bool {
        return std.mem.eql(u8, value, "0") or std.mem.eql(u8, value, "1");
    }

    pub const HistoryPolicy = enum { public, members, opers };
    pub const ChannelEncryptionPolicy = e2ee_policy.Policy;

    fn validHistoryPolicyValue(value: []const u8) bool {
        return std.ascii.eqlIgnoreCase(value, "public") or
            std.ascii.eqlIgnoreCase(value, "members") or
            std.ascii.eqlIgnoreCase(value, "opers");
    }

    pub fn channelHistoryPolicy(self: *LinuxServer, channel: []const u8) HistoryPolicy {
        if (channel.len == 0 or (channel[0] != '#' and channel[0] != '&')) return .public;
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const ev = self.props.getProp(entity, "history-policy") catch return .public;
        if (std.ascii.eqlIgnoreCase(ev.value, "public")) return .public;
        if (std.ascii.eqlIgnoreCase(ev.value, "members")) return .members;
        if (std.ascii.eqlIgnoreCase(ev.value, "opers")) return .opers;
        return .members;
    }

    pub fn channelEncryptionPolicy(self: *LinuxServer, channel: []const u8) ChannelEncryptionPolicy {
        if (channel.len == 0 or (channel[0] != '#' and channel[0] != '&')) return .off;
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const ev = self.props.getProp(entity, e2ee_policy.policy_prop) catch return .off;
        return e2ee_policy.policyValue(ev.value) orelse .off;
    }

    pub fn channelMembershipVisibility(self: *LinuxServer, channel: []const u8) sealed_room.Visibility {
        if (channel.len == 0 or (channel[0] != '#' and channel[0] != '&')) return .ordinary;
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const ev = self.props.getProp(entity, sealed_room.prop_key) catch return .ordinary;
        // A stored value this server does not understand refuses the roster.
        return sealed_room.visibilityValue(ev.value) orelse .sealed;
    }

    fn rosterRefused(self: *LinuxServer, channel: []const u8) bool {
        return sealed_room.rosterDisclosure(self.channelMembershipVisibility(channel)) == .refuse;
    }

    fn messageSatisfiesEncryptionPolicy(
        self: *LinuxServer,
        channel: []const u8,
        raw_tags: ?[]const u8,
        body: []const u8,
        tag_only: bool,
    ) bool {
        return switch (self.channelEncryptionPolicy(channel)) {
            .off, .optional => true,
            .required => e2ee_policy.requiredRoomCommandAdmitted(raw_tags, body, tag_only),
        };
    }

    fn historyPolicyAllows(self: *LinuxServer, channel: []const u8, is_member: bool, is_oper: bool) bool {
        return switch (self.channelHistoryPolicy(channel)) {
            .public => true,
            .members => is_member or is_oper,
            .opers => is_oper,
        };
    }

    pub fn channelAiPolicy(self: *LinuxServer, channel: []const u8) AiPolicy {
        if (channel.len == 0 or (channel[0] != '#' and channel[0] != '&')) return .unspecified;
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        if (propEnabled(self.props.getProp(entity, "no-ai") catch null)) return .no_ai;
        if (propEnabled(self.props.getProp(entity, "local-only") catch null)) return .local_only;
        if (propEnabled(self.props.getProp(entity, "server-ai-ok") catch null)) return .server_ai_ok;
        return .unspecified;
    }

    /// Server-side AI policy hook for future bot/plugin/WASM control paths. The
    /// room flags are intentionally stored as ordinary public channel PROP values,
    /// but all server-side plaintext processing must ask this helper so
    /// precedence and fail-closed defaults stay centralized.
    pub fn checkChannelAiPolicy(self: *LinuxServer, channel: []const u8, use: AiPolicyUse) AiPolicyDecision {
        const policy = self.channelAiPolicy(channel);
        return switch (use) {
            .local_inference => switch (policy) {
                .no_ai => .{ .policy = policy, .allowed = false, .deny = .no_ai },
                .unspecified, .local_only, .server_ai_ok => .{ .policy = policy, .allowed = true },
            },
            .server_plaintext => switch (policy) {
                .server_ai_ok => .{ .policy = policy, .allowed = true },
                .no_ai => .{ .policy = policy, .allowed = false, .deny = .no_ai },
                .local_only => .{ .policy = policy, .allowed = false, .deny = .local_only },
                .unspecified => .{ .policy = policy, .allowed = false, .deny = .server_ai_not_enabled },
            },
        };
    }

    fn propEnabled(entry: ?ircx_prop_store.EntryView) bool {
        const ev = entry orelse return false;
        return std.mem.eql(u8, ev.value, "1");
    }

    /// EPHEMERAL TTL bounds: at least a minute (below that, history is useless),
    /// at most 30 days (beyond that, just leave it non-ephemeral).
    const ephemeral_min_secs: u64 = 60;
    const ephemeral_max_secs: u64 = 30 * 24 * 60 * 60;
    /// SLOWMODE upper bound: one day. Zero disables. Not a table-size cap.
    const slowmode_max_secs: u64 = 24 * 60 * 60;
    /// RETAIN bounds match EPHEMERAL: at least a minute, at most 30 days.
    /// Zero disables. Not a table-size cap.
    const retain_min_secs: u64 = 60;
    const retain_max_secs: u64 = 30 * 24 * 60 * 60;
    /// Folded channel, a separator, and the nick. Protocol name limits fit;
    /// a longer pair fails closed instead of truncating into another member.
    const slowmode_key_max: usize = 512;

    /// A PINS value is a comma-separated list of msgid tokens: each printable,
    /// non-empty, bounded, no whitespace/commas.
    fn validPinsValue(value: []const u8) bool {
        return validPinsValueWithLimits(value, 50, 64);
    }

    fn validPinsValueWithLimits(value: []const u8, max_count: usize, max_msgid_bytes: usize) bool {
        if (value.len == 0) return true;
        var count: usize = 0;
        var it = std.mem.splitScalar(u8, value, ',');
        while (it.next()) |tok| {
            if (tok.len == 0 or tok.len > max_msgid_bytes) return false;
            count += 1;
            if (count > max_count) return false;
            for (tok) |c| {
                if (c <= 0x20 or c == 0x7f or c == ',') return false;
            }
        }
        return true;
    }

    const PinsMutation = struct {
        value: []const u8,
        changed: bool,
    };

    fn validPinToken(msgid: []const u8, max_msgid_bytes: usize) bool {
        return msgid.len != 0 and validPinsValueWithLimits(msgid, 1, max_msgid_bytes);
    }

    fn pinsContainsValue(value: []const u8, msgid: []const u8) bool {
        var it = std.mem.splitScalar(u8, value, ',');
        while (it.next()) |tok| {
            if (std.mem.eql(u8, tok, msgid)) return true;
        }
        return false;
    }

    fn pinsAddValue(
        current: []const u8,
        msgid: []const u8,
        out: []u8,
        max_count: usize,
        max_msgid_bytes: usize,
    ) ?PinsMutation {
        if (!validPinToken(msgid, max_msgid_bytes)) return null;
        if (pinsContainsValue(current, msgid)) return .{ .value = current, .changed = false };

        const next_len = current.len + msgid.len + @as(usize, if (current.len == 0) 0 else 1);
        if (next_len > out.len) return null;
        if (current.len != 0) {
            std.mem.copyForwards(u8, out[0..current.len], current);
            out[current.len] = ',';
            @memcpy(out[current.len + 1 .. next_len], msgid);
        } else {
            @memcpy(out[0..msgid.len], msgid);
        }
        const next = out[0..next_len];
        if (!validPinsValueWithLimits(next, max_count, max_msgid_bytes)) return null;
        return .{ .value = next, .changed = true };
    }

    fn pinsDeleteValue(current: []const u8, msgid: []const u8, out: []u8, max_msgid_bytes: usize) ?PinsMutation {
        if (!validPinToken(msgid, max_msgid_bytes)) return null;
        var len: usize = 0;
        var removed = false;
        var it = std.mem.splitScalar(u8, current, ',');
        while (it.next()) |tok| {
            if (std.mem.eql(u8, tok, msgid)) {
                removed = true;
                continue;
            }
            const need = tok.len + @as(usize, if (len == 0) 0 else 1);
            if (len + need > out.len) return null;
            if (len != 0) {
                out[len] = ',';
                len += 1;
            }
            std.mem.copyForwards(u8, out[len .. len + tok.len], tok);
            len += tok.len;
        }
        return .{ .value = if (removed) out[0..len] else current, .changed = removed };
    }

    /// Record a conversation label into a channel's browsable topic registry (the
    /// `onyx_server.topics` channel PROP). Best-effort and bounded: no-op if the label
    /// is already registered or the registry is full. A change is written through
    /// the generic channel-prop store and mesh-propagated with the same signed
    /// CRDT sequence a local PROP SET uses, so the registry converges across the
    /// mesh and survives a peer relink/USR2 via the channel-prop burst.
    ///
    /// The registry is a comma-string under LWW-per-value (like PINS): concurrent
    /// first-uses of two distinct labels on two nodes resolve by HLC, transiently
    /// dropping one until its next message re-adds it — self-healing, and messages
    /// are never lost. We deliberately do NOT emit a live `notifyLocalPropChange`
    /// here: auto-registration fires per first-use message and a push per message
    /// would be a storm; clients pick up new labels on their next PROP query.
    fn registerChannelTopic(self: *LinuxServer, channel: []const u8, label: []const u8) void {
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const current: []const u8 = if (self.props.getProp(entity, topic_tag.registry_key)) |ev| ev.value else |_| "";
        var next_buf: [topic_tag.registry_max_bytes]u8 = undefined;
        const next = topic_tag.addToRegistry(current, label, &next_buf) orelse return;

        // Server-authored write: the owner is this node's server name so the mesh
        // origin is consistent; `.server` access clears the generic host gate.
        const setter = ircx_prop_store.Setter{ .id = self.serverName(), .access = .server };
        const ev = self.props.setProp(entity, topic_tag.registry_key, next, setter) catch return;
        const hlc = self.nextChannelPropHlc();
        var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
        var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
        const ps = self.signLocalChannelProp(true, ev.entity.id, ev.key, ev.value, ev.owner, hlc, &pk_buf, &sig_buf);
        if (self.recordChannelPropClock(ev.entity.id, ev.key, ev.owner, hlc, true, ps.node, ps.pubkey, ps.sig)) {
            self.announceChannelProp(ev.entity.id, ev.key, ev.value, ev.owner, hlc, true, .{ .node = ps.node, .pubkey = ps.pubkey, .sig = ps.sig });
        }
    }

    /// Broadcast the equivalent MODE change after a PROP built-in linked to a
    /// channel mode, so every member's mode view stays in sync (MEMBERKEY→+k,
    /// MEMBERLIMIT→+l). Cleared values broadcast the `-` form.
    fn broadcastBuiltinMode(self: *LinuxServer, conn: *ConnState, channel: []const u8, key: []const u8, value: []const u8, deleting: bool) !void {
        const letter: u8 = if (std.ascii.eqlIgnoreCase(key, "MEMBERKEY")) 'k' else 'l';
        var sign_buf = [_]u8{ if (deleting) '-' else '+', letter };
        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const params: []const []const u8 = if (deleting)
            &.{ channel, sign_buf[0..] }
        else
            &.{ channel, sign_buf[0..], value };
        const msg = try formatMessage(&msg_buf, try clientPrefix(conn, &prefix_buf), "MODE", params, null);
        try self.broadcastChannel(channel, msg, null);
    }

    fn propEmitBuiltin(conn: *ConnState, entity: ircx_prop_store.Entity, key: []const u8, value: []const u8) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const ev = ircx_prop_store.EntryView{ .entity = entity, .key = key, .value = value, .owner = "*", .access = .user };
        const line = ircx_prop_store.buildPropListReply(protocol_inventory.currentServerName(), conn.session.displayName(), ev, &buf) catch return;
        try appendToConn(conn, line);
        try appendToConn(conn, "\r\n");
    }

    fn propEmitEntry(conn: *ConnState, entry: ircx_prop_store.EntryView) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const line = ircx_prop_store.buildPropListReply(protocol_inventory.currentServerName(), conn.session.displayName(), entry, &buf) catch return;
        try appendToConn(conn, line);
        try appendToConn(conn, "\r\n");
    }

    fn propEmitEnd(conn: *ConnState, entity: ircx_prop_store.Entity) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const line = ircx_prop_store.buildPropEndReply(protocol_inventory.currentServerName(), conn.session.displayName(), entity, &buf) catch return;
        try appendToConn(conn, line);
        try appendToConn(conn, "\r\n");
    }

    /// PROP <entity> [<key[,key]> [:<value>]] — IRCX property get/list/set/delete.
    /// One param lists all; two gets keys; three sets (empty trailing deletes).
    /// Replies are RPL_PROPLIST 818 + RPL_PROPEND 819. Writes are gated by
    /// channel-operator (channel/member entities) or self (user entities).
    pub fn handleProp(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        // The daemon's LineView keeps only folded params, so preserve the
        // historical PROP behavior: an empty final param means delete.
        const req = ircx_prop_store.parseParamsBounded(.{}, parsed.paramSlice(), true) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"PROP"}, "Invalid PROP");
            return;
        };
        switch (req) {
            .list => |entity| {
                // Secret props (channel keys) use the per-tier read gate: each key
                // is visible only to members at/above its tier (FOUNDERKEY→founder,
                // OWNERKEY→owner, HOSTKEY→op, VOICEKEY→voice, MEMBERKEY→member; opers
                // always). The store's plain listProps hides ALL secrets, so list
                // RAW and apply the daemon's per-tier gate per entry — an authorized
                // requester sees their tier's keys, everyone else sees none.
                var user_views: [ircx_prop_store.user_max_props_per_entity]ircx_prop_store.EntryView = undefined;
                var default_views: [ircx_prop_store.default_max_props_per_entity]ircx_prop_store.EntryView = undefined;
                const rows = switch (entity.kind) {
                    .user => self.props.listPropsRaw(entity, &user_views),
                    .channel, .member => self.props.listPropsRaw(entity, &default_views),
                } catch {
                    try queueNumeric(conn, .ERR_RESOURCE, &.{entity.id}, "Could not inspect complete property list");
                    return;
                };
                for (rows) |ev| {
                    if (isReadMarkerPropKey(ev.key)) continue;
                    if (propIsSecret(entity, ev.key) and !self.maySeeSecretKey(id, conn, entity, ev.key)) continue;
                    try propEmitEntry(conn, ev);
                }
                try propEmitEnd(conn, entity);
            },
            .get => |q| {
                var it = std.mem.splitScalar(u8, q.keys, ',');
                while (it.next()) |key| {
                    if (key.len == 0) continue;
                    if (isReadMarkerPropKey(key)) continue;
                    const is_secret = propIsSecret(q.entity, key);
                    if (is_secret and !self.maySeeSecretKey(id, conn, q.entity, key)) continue;
                    // Computed/linked built-ins (NAME/MEMBERCOUNT/MEMBERLIMIT and
                    // the linked +k MEMBERKEY) reflect live channel state, ahead of
                    // the generic store.
                    var bbuf: [64]u8 = undefined;
                    if (self.channelBuiltinGet(q.entity, key, &bbuf)) |val| {
                        try propEmitBuiltin(conn, q.entity, key, val);
                        continue;
                    }
                    // Computed user built-ins need the requester context for
                    // visibility and enough room for joined profile fields.
                    var ubuf: [default_reply_bytes]u8 = undefined;
                    if (self.userBuiltinGet(q.entity, key, &ubuf, id, conn)) |val| {
                        try propEmitBuiltin(conn, q.entity, key, val);
                        continue;
                    }
                    // A secret key that passed the per-tier gate is read RAW: the
                    // store's `getProp` hides secrets unconditionally, so the gated
                    // value must come from `getPropRaw` (the gate is the daemon's,
                    // not the store's).
                    const stored = if (is_secret)
                        self.props.getPropRaw(q.entity, key)
                    else
                        self.props.getProp(q.entity, key);
                    if (stored) |ev| {
                        try propEmitEntry(conn, ev);
                    } else |_| {}
                }
                try propEmitEnd(conn, q.entity);
            },
            .set => |m| {
                if (isReadMarkerPropKey(m.key)) {
                    try queueNumeric(conn, .ERR_SECURITY, &.{m.entity.id}, "Read markers are managed through MARKREAD");
                    return;
                }
                var device_key_buf: [e2ee_policy.device_prop_prefix.len + e2ee_policy.max_device_id_len]u8 = undefined;
                if (m.entity.kind == .user and isReservedDevicePropPrefix(m.key)) {
                    const device_key = canonicalDevicePropKey(m.key, &device_key_buf) orelse {
                        try queueNumeric(conn, .ERR_BADPROPERTY, &.{ m.entity.id, m.key }, "Invalid device property");
                        return;
                    };
                    if (!validDurableDeviceValue(device_key, m.value)) {
                        try queueNumeric(conn, .ERR_BADVALUE, &.{ m.entity.id, m.key }, "Invalid device property value");
                        return;
                    }
                    const outcome = self.commitLocalDurableDeviceProp(conn, m.entity, device_key, m.value, true);
                    if (outcome != .committed) {
                        try self.durableDeviceNumericReply(conn, m.entity, outcome);
                        return;
                    }
                    const canonical_account = services_mod.canonicalAccount(conn.session.account().?) catch unreachable;
                    const entity = ircx_prop_store.Entity{ .kind = .user, .id = canonical_account.asSlice() };
                    const ev = self.props.getPropRaw(entity, device_key) catch unreachable;
                    try propEmitEntry(conn, ev);
                    try propEmitEnd(conn, entity);
                    return;
                }
                const access = self.propAccess(id, conn, m.entity) orelse {
                    try queueNumeric(conn, .ERR_NOACCESS, &.{m.entity.id}, "Insufficient access to set property");
                    return;
                };
                if (overrideActive(conn) and self.propOverrideWouldBypass(id, m.entity)) {
                    var detail_buf: [192]u8 = undefined;
                    const detail = std.fmt.bufPrint(&detail_buf, "SET {s}", .{m.key}) catch "SET";
                    self.auditOverrideUse(conn, "PROP", m.entity.id, detail);
                }
                // Linked built-ins (MEMBERKEY<->+k, MEMBERLIMIT<->+l) write through
                // to live channel state instead of the generic store, and broadcast
                // the equivalent MODE so member mode views stay in sync.
                switch (self.channelBuiltinSet(m.entity, m.key, m.value, false)) {
                    .applied => {
                        try self.broadcastBuiltinMode(conn, m.entity.id, m.key, m.value, false);
                        try propEmitBuiltin(conn, m.entity, m.key, m.value);
                        try propEmitEnd(conn, m.entity);
                        return;
                    },
                    .bad_value => {
                        try queueNumeric(conn, .ERR_BADVALUE, &.{ m.entity.id, m.key }, "Invalid property value");
                        return;
                    },
                    .not_handled => {},
                }
                if (m.entity.kind == .user and isReadOnlyGeoUserBuiltinKey(m.key)) {
                    try queueNumeric(conn, .ERR_NOACCESS, &.{m.entity.id}, "Cannot set that property");
                    return;
                }
                const setter = ircx_prop_store.Setter{ .id = conn.session.displayName(), .access = access };
                const ev = self.props.setProp(m.entity, m.key, m.value, setter) catch {
                    try queueNumeric(conn, .ERR_NOACCESS, &.{m.entity.id}, "Cannot set that property");
                    return;
                };
                if (m.entity.kind == .channel) {
                    const hlc = self.nextChannelPropHlc();
                    // LOCAL origin: sign the fact ONCE so every re-broadcast/burst
                    // re-emits THIS node's signature and any hop self-certifies it.
                    var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
                    var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
                    const ps = self.signLocalChannelProp(true, ev.entity.id, ev.key, ev.value, ev.owner, hlc, &pk_buf, &sig_buf);
                    if (self.recordChannelPropClock(ev.entity.id, ev.key, ev.owner, hlc, true, ps.node, ps.pubkey, ps.sig)) {
                        self.announceChannelProp(ev.entity.id, ev.key, ev.value, ev.owner, hlc, true, .{ .node = ps.node, .pubkey = ps.pubkey, .sig = ps.sig });
                    }
                } else {
                    // user/member props propagate over ENTITY_PROP with the same
                    // signed multi-hop LWW guarantees. Exact credential keys
                    // share the observation helper with E2EEKEY/IDENTITY.
                    const hlc = self.nextChannelPropHlc();
                    self.observeLocalUserCredentialProp(true, ev.entity.kind, ev.entity.id, ev.key, ev.value, hlc);
                    self.propagateLocalEntityPropAt(true, ev.entity.kind, ev.entity.id, ev.key, ev.value, ev.owner, hlc);
                }
                // Notify local IRCX clients that may see this entity (per-tier
                // for secret channel keys); the setter's own echo follows.
                self.notifyLocalPropChange(conn, ev.entity, ev.key, ev.value);
                try propEmitEntry(conn, ev);
                try propEmitEnd(conn, m.entity);
            },
            .delete => |k| {
                if (isReadMarkerPropKey(k.key)) {
                    try queueNumeric(conn, .ERR_SECURITY, &.{k.entity.id}, "Read markers are managed through MARKREAD");
                    return;
                }
                var device_key_buf: [e2ee_policy.device_prop_prefix.len + e2ee_policy.max_device_id_len]u8 = undefined;
                if (k.entity.kind == .user and k.key.len != 0 and isReservedDevicePropPrefix(k.key)) {
                    const device_key = canonicalDevicePropKey(k.key, &device_key_buf) orelse {
                        try queueNumeric(conn, .ERR_BADPROPERTY, &.{ k.entity.id, k.key }, "Invalid device property");
                        return;
                    };
                    const outcome = self.commitLocalDurableDeviceProp(conn, k.entity, device_key, "", false);
                    if (outcome != .committed) {
                        try self.durableDeviceNumericReply(conn, k.entity, outcome);
                        return;
                    }
                    const canonical_account = services_mod.canonicalAccount(conn.session.account().?) catch unreachable;
                    try propEmitEnd(conn, .{ .kind = .user, .id = canonical_account.asSlice() });
                    return;
                }
                if (self.propAccess(id, conn, k.entity) == null) {
                    try queueNumeric(conn, .ERR_NOACCESS, &.{k.entity.id}, "Insufficient access to delete property");
                    return;
                }
                if (overrideActive(conn) and self.propOverrideWouldBypass(id, k.entity)) {
                    var detail_buf: [192]u8 = undefined;
                    const detail = if (k.key.len == 0)
                        "DELETE *"
                    else
                        (std.fmt.bufPrint(&detail_buf, "DELETE {s}", .{k.key}) catch "DELETE");
                    self.auditOverrideUse(conn, "PROP", k.entity.id, detail);
                }
                if (k.entity.kind == .user and k.key.len != 0 and isReadOnlyGeoUserBuiltinKey(k.key)) {
                    try queueNumeric(conn, .ERR_NOACCESS, &.{k.entity.id}, "Cannot delete that property");
                    return;
                }
                if (k.key.len == 0) {
                    var views: [ircx_prop_store.user_max_props_per_entity]ircx_prop_store.EntryView = undefined;
                    const rows = self.props.listPropsRaw(k.entity, &views) catch {
                        try queueNumeric(conn, .ERR_RESOURCE, &.{k.entity.id}, "Could not inspect properties before clear");
                        return;
                    };
                    if (k.entity.kind == .user) {
                        for (rows) |ev| {
                            if (isReservedDevicePropPrefix(ev.key) or isReadMarkerPropKey(ev.key)) {
                                try queueNumeric(conn, .ERR_SECURITY, &.{k.entity.id}, "Delete device properties individually through durable authority");
                                return;
                            }
                        }
                    }
                    const owner = conn.session.displayName();
                    // Sign + announce each deletion while the rows (which borrow the
                    // store's key bytes) are still live, THEN clear the store —
                    // clearing first would free `ev.key` out from under the loop.
                    if (k.entity.kind == .channel) {
                        for (rows) |ev| {
                            const hlc = self.nextChannelPropHlc();
                            var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
                            var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
                            const ps = self.signLocalChannelProp(false, k.entity.id, ev.key, "", owner, hlc, &pk_buf, &sig_buf);
                            if (self.recordChannelPropClock(k.entity.id, ev.key, owner, hlc, false, ps.node, ps.pubkey, ps.sig)) {
                                self.announceChannelProp(k.entity.id, ev.key, "", owner, hlc, false, .{ .node = ps.node, .pubkey = ps.pubkey, .sig = ps.sig });
                            }
                            self.notifyLocalPropChange(conn, k.entity, ev.key, "");
                        }
                    } else {
                        for (rows) |ev| {
                            const hlc = self.nextChannelPropHlc();
                            self.observeLocalUserCredentialProp(false, k.entity.kind, k.entity.id, ev.key, "", hlc);
                            self.propagateLocalEntityPropAt(false, k.entity.kind, k.entity.id, ev.key, "", owner, hlc);
                            self.notifyLocalPropChange(conn, k.entity, ev.key, "");
                        }
                    }
                    self.props.clearEntity(k.entity) catch {};
                    try propEmitEnd(conn, k.entity);
                    return;
                }
                const existed = if (self.props.getProp(k.entity, k.key)) |_| true else |_| false;
                self.props.deleteProp(k.entity, k.key) catch {};
                if (k.entity.kind == .channel) {
                    const hlc = self.nextChannelPropHlc();
                    const owner = conn.session.displayName();
                    var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
                    var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
                    const ps = self.signLocalChannelProp(false, k.entity.id, k.key, "", owner, hlc, &pk_buf, &sig_buf);
                    if (self.recordChannelPropClock(k.entity.id, k.key, owner, hlc, false, ps.node, ps.pubkey, ps.sig)) {
                        self.announceChannelProp(k.entity.id, k.key, "", owner, hlc, false, .{ .node = ps.node, .pubkey = ps.pubkey, .sig = ps.sig });
                    }
                } else {
                    const hlc = self.nextChannelPropHlc();
                    if (existed) {
                        self.observeLocalUserCredentialProp(false, k.entity.kind, k.entity.id, k.key, "", hlc);
                    }
                    self.propagateLocalEntityPropAt(false, k.entity.kind, k.entity.id, k.key, "", conn.session.displayName(), hlc);
                }
                self.notifyLocalPropChange(conn, k.entity, k.key, "");
                try propEmitEnd(conn, k.entity);
            },
        }
    }

    fn ircxAuthPackageList(conn: *ConnState, out: []u8) []const u8 {
        var len: usize = 0;
        if (conn.session.sasl_plain != null) appendSaslInfoMech(out, &len, "PLAIN") catch return out[0..len];
        if (conn.session.sasl_scram256 != null and conn.session.sasl_server_nonce.len != 0) appendSaslInfoMech(out, &len, "SCRAM-SHA-256") catch return out[0..len];
        if (conn.session.sasl_scram512 != null and conn.session.sasl_server_nonce.len != 0) appendSaslInfoMech(out, &len, "SCRAM-SHA-512") catch return out[0..len];
        if (conn.session.sasl_scram512 != null and conn.session.sasl_server_nonce.len != 0 and conn.session.tls_exporter != null) appendSaslInfoMech(out, &len, "SCRAM-SHA-512-PLUS") catch return out[0..len];
        if (conn.session.sasl_external != null) appendSaslInfoMech(out, &len, "EXTERNAL") catch return out[0..len];
        if (conn.session.sasl_session_token != null) appendSaslInfoMech(out, &len, "SESSION-TOKEN") catch return out[0..len];
        if (conn.session.sasl_oauthbearer != null) appendSaslInfoMech(out, &len, "OAUTHBEARER") catch return out[0..len];
        if (conn.session.sasl_allow_anonymous) appendSaslInfoMech(out, &len, "ANONYMOUS") catch return out[0..len];
        if (len == 0) return "*";
        return out[0..len];
    }

    fn ircxAuthMechName(package: ircx_auth.Package) ?[]const u8 {
        return ircx_auth.saslMechanism(package);
    }

    fn ircxAuthAllowsOperElevation(package: ircx_auth.Package) bool {
        return switch (package) {
            .plain,
            .external,
            .scram_sha_256,
            .scram_sha_512,
            .scram_sha_512_plus,
            .session_token,
            => true,
            .oauthbearer,
            .anonymous,
            .anon,
            .gatekeeper,
            .gatekeeper_passport,
            => false,
        };
    }

    fn ircxPlainAdapter(session: *dispatch.ClientSession) ?sasl_mechrouter.PlainLookup {
        if (session.sasl_plain == null) return null;
        return .{ .ptr = session, .verifyFn = ircxPlainVerify };
    }

    fn ircxPlainVerify(ptr: *anyopaque, creds: sasl.PlainCredentials) ?[]const u8 {
        const session: *dispatch.ClientSession = @ptrCast(@alignCast(ptr));
        const checker = session.sasl_plain orelse return null;
        if (!checker.verify(creds)) return null;
        return creds.authcid;
    }

    fn ircxAuthFailed(self: *LinuxServer, conn: *ConnState, package: []const u8) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const line = ircx_auth.buildAuthenticationFailedReply(&buf, .{
            .server_name = self.serverName(),
            .recipient_nick = conn.session.displayName(),
        }, package) catch return;
        try appendToConn(conn, line);
    }

    fn ircxAuthUnknownPackage(self: *LinuxServer, conn: *ConnState, package: []const u8) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const line = ircx_auth.buildUnknownPackageReply(&buf, .{
            .server_name = self.serverName(),
            .recipient_nick = conn.session.displayName(),
        }, package) catch return;
        try appendToConn(conn, line);
    }

    fn ircxAuthChallenge(conn: *ConnState, package: ircx_auth.Package, payload: []const u8) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const challenge = if (payload.len == 0) "+" else payload;
        const line = ircx_auth.buildChallenge(&buf, package, challenge) catch return;
        try appendToConn(conn, line);
    }

    /// Whether an IRCX AUTH package authenticates by a knowledge factor (password
    /// or password-derived) and so requires a TOTP second factor for a 2FA
    /// account. EXTERNAL (cert), OAUTHBEARER (IdP), SESSION-TOKEN (continuation),
    /// and ANON(YMOUS) are not knowledge factors.
    fn ircxAuthIsKnowledgeFactor(package: ircx_auth.Package) bool {
        return switch (package) {
            .plain, .scram_sha_256, .scram_sha_512, .scram_sha_512_plus, .gatekeeper, .gatekeeper_passport => true,
            .external, .oauthbearer, .session_token, .anon, .anonymous => false,
        };
    }

    fn completeIrcxAuth(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        package: ircx_auth.Package,
        result: sasl_mechrouter.Success,
    ) !void {
        if (!self.authenticationAvailable()) {
            conn.session.sasl_router = null;
            conn.session.sasl_pending = null;
            conn.session.sasl_issue_session_token = false;
            try self.ircxAuthFailed(conn, "*");
            return;
        }
        if (result.account.len > account_register.MAX_ACCOUNT_BYTES) {
            try self.ircxAuthFailed(conn, package.token());
            return;
        }
        var account_buf: [account_register.MAX_ACCOUNT_BYTES]u8 = undefined;
        const account = std.ascii.lowerString(account_buf[0..result.account.len], result.account);

        // TOTP second factor over IRCX AUTH: a knowledge-factor package (PLAIN,
        // SCRAM-*, GateKeeper) for a 2FA-active account is refused — IRCX AUTH
        // carries no second factor, so the user must complete 2FA via IDENTIFY.
        // EXTERNAL/OAUTHBEARER/SESSION-TOKEN/ANON(YMOUS) are other/continuation
        // factors and pass.
        if (!result.guest and ircxAuthIsKnowledgeFactor(package) and self.totpRequired(account)) {
            conn.session.sasl_router = null;
            conn.session.sasl_pending = null;
            self.noticeTo(conn, "Two-factor authentication required: log in with IDENTIFY <account> <password> <code>") catch {};
            try self.ircxAuthFailed(conn, package.token());
            return;
        }

        // Account-status chokepoint (IRCX AUTH): a SUSPENDED or FORBIDDEN account
        // must never bind, even though the mechanism verified — a SCRAM proof /
        // OAUTHBEARER token never consults account status. Same failure surface
        // as a bad credential (no enumeration of suspended vs forbidden).
        if (!result.guest) {
            if (self.account_services) |svc| {
                if (svc.accountAuthBlocked(account)) {
                    conn.session.sasl_router = null;
                    conn.session.sasl_pending = null;
                    try self.ircxAuthFailed(conn, package.token());
                    return;
                }
            }
        }

        // OAUTHBEARER binds a session only for an account that already
        // REGISTER'd, unless the operator set sasl.oauth_auto_provision.
        // Missing services fail closed. The reply stays the generic
        // authentication failure so the nick is not told "unknown".
        if (!result.guest and package == .oauthbearer and !conn.session.sasl_oauth_auto_provision) {
            const registered = if (self.account_services) |svc| svc.accountIsRegistered(account) else false;
            if (!registered) {
                conn.session.sasl_router = null;
                conn.session.sasl_pending = null;
                try self.ircxAuthFailed(conn, package.token());
                return;
            }
        }

        var final_buf: [sasl_mechrouter.MAX_B64_MESSAGE]u8 = undefined;
        const final_copy: ?[]const u8 = if (result.final_data) |final| blk: {
            if (final.len > final_buf.len) break :blk null;
            @memcpy(final_buf[0..final.len], final);
            break :blk final_buf[0..final.len];
        } else null;

        const oper_elevation_allowed = ircxAuthAllowsOperElevation(package);
        conn.session.sasl_router = null;
        conn.session.sasl_pending = null;
        self.retireMediaBeforeAccountMutation(id, conn, if (result.guest) null else account);
        _ = self.clearOperAuthorityTransition(
            id,
            conn,
            true,
            if (result.guest) "anonymous authentication replaced operator authority" else "account authentication replaced operator authority",
        );
        if (result.guest) {
            // ANONYMOUS is an account transition too: it clears account() and
            // therefore must retire the previous tracked portable authority.
            if (conn.session.account()) |old| _ = self.removeTrackedSession(old, monitorIdFromClient(id));
            conn.session_list_cache.reset();
            conn.session.loginGuest(account);
        } else {
            if (conn.session.account()) |old| {
                if (!std.ascii.eqlIgnoreCase(old, account)) _ = self.removeTrackedSession(old, monitorIdFromClient(id));
            }
            loginSession(conn, account);
            conn.session.sasl_oper_elevation_allowed = oper_elevation_allowed;
            self.restoreAccountMetadata(conn, account);
            self.restoreAccountSilence(conn, account);
        }
        conn.session.client.registration.sasl = .succeeded;
        if (conn.session.account()) |acct| self.emitAccountChange(id, conn, acct);
        if (final_copy) |final| try ircxAuthChallenge(conn, package, final);
        var ack_buf: [default_reply_bytes]u8 = undefined;
        const ack = ircx_auth.buildAck(&ack_buf, package, account, "0") catch return;
        try appendToConn(conn, ack);
        if (result.issue_session_token and !result.guest) self.issueSessionTokenNotice(conn, "AUTH") catch {};
        if (result.guest) {
            if (!try self.enforceE2eeSessionEligibility(id, conn)) return;
            self.deliverWelcome(conn);
            self.emitClientRegistered(id, conn);
            self.evaluateNickProtection(conn);
            return;
        }
        if (oper_elevation_allowed) try self.elevateOperFromAccount(conn);
        self.trackSession(id, conn);
        self.armBoundedExactResumeHoldIfNeeded(id, conn);
        if (!try self.enforceE2eeSessionEligibility(id, conn)) return;
        try self.deliverMemo(conn);
        self.applyLoginJoinState(id, conn);
        self.deliverWelcome(conn);
        self.emitClientRegistered(id, conn);
        self.evaluateNickProtection(conn);
    }

    fn handleIrcxAuthOutcome(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        package: ircx_auth.Package,
        outcome: sasl_mechrouter.Outcome,
    ) !void {
        switch (outcome) {
            .continue_ => |challenge| try ircxAuthChallenge(conn, package, challenge),
            .success => |result| try self.completeIrcxAuth(id, conn, package, result),
            .fail => {
                conn.session.sasl_router = null;
                conn.session.sasl_pending = null;
                try self.ircxAuthFailed(conn, package.token());
            },
        }
    }

    /// IRCX / ISIRCX — IRCX discovery + opt-in (draft-pfenning §IRCX). `IRCX`
    /// enables IRCX mode for the session; `ISIRCX` only queries. Both reply with
    /// RPL_IRCX (800): `<state> <version> <package-list> <maxmsg> <option-list>`.
    /// Onyx Server advertises live SASL-backed IRCX AUTH packages for this session.
    pub fn handleIrcx(self: *LinuxServer, conn: *ConnState, enable: bool) !void {
        _ = self;
        if (enable) conn.ircx = true;
        const state: []const u8 = if (conn.ircx) "1" else "0";
        var packages_buf: [128]u8 = undefined;
        const packages = ircxAuthPackageList(conn, &packages_buf);
        // version 0; package-list = advertised SASL-backed AUTH packages; maxmsg 512.
        try queueNumeric(conn, .RPL_IRCX, &.{ state, "0", packages, "512" }, "*");
    }

    pub fn handleIrcxAuth(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.authenticationAvailable()) {
            conn.session.sasl_router = null;
            conn.session.sasl_pending = null;
            conn.session.sasl_issue_session_token = false;
            try self.ircxAuthFailed(conn, "*");
            return;
        }
        const req = ircx_auth.parseParams(parsed.paramSlice()) catch |err| {
            if (err == error.UnknownPackage and parsed.param_count >= 1) {
                try self.ircxAuthUnknownPackage(conn, parsed.paramSlice()[0]);
                return;
            }
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"AUTH"}, "Invalid AUTH");
            return;
        };
        const mech = ircxAuthMechName(req.package) orelse {
            try self.ircxAuthUnknownPackage(conn, req.package_raw);
            return;
        };
        if (req.sequence == .abort) {
            conn.session.sasl_router = null;
            conn.session.sasl_pending = null;
            try self.ircxAuthFailed(conn, req.package.token());
            return;
        }
        if (conn.session.sasl_router == null) {
            if (conn.session.account()) |acct| {
                var ack_buf: [default_reply_bytes]u8 = undefined;
                const ack = ircx_auth.buildAck(&ack_buf, req.package, acct, "0") catch return;
                try appendToConn(conn, ack);
                return;
            }
            var router = sasl_mechrouter.Router.initWithLimit(.{
                .plain = ircxPlainAdapter(&conn.session),
                .external = conn.session.sasl_external,
                .scram256 = conn.session.sasl_scram256,
                .scram512 = conn.session.sasl_scram512,
                .session_token = conn.session.sasl_session_token,
                .oauthbearer = conn.session.sasl_oauthbearer,
                .anonymous = conn.session.sasl_allow_anonymous,
            }, conn.session.sasl_server_nonce, conn.session.sasl_decode_max_bytes);
            router.tls_certfp = conn.session.tls_certfp;
            router.tls_exporter = conn.session.tls_exporter;
            switch (router.start(mech)) {
                .continue_ => |challenge| {
                    conn.session.sasl_pending = sasl.Mechanism.parse(mech);
                    conn.session.sasl_router = router;
                    conn.session.client.registration.sasl = .authenticating;
                    if (req.data) |payload| {
                        var out_buf: [sasl_mechrouter.MAX_B64_MESSAGE]u8 = undefined;
                        try self.handleIrcxAuthOutcome(id, conn, req.package, conn.session.sasl_router.?.receive(payload, &out_buf));
                    } else {
                        try ircxAuthChallenge(conn, req.package, challenge);
                    }
                    return;
                },
                else => {
                    try self.ircxAuthFailed(conn, req.package.token());
                    return;
                },
            }
        }
        const payload = req.data orelse {
            try self.ircxAuthFailed(conn, req.package.token());
            return;
        };
        var out_buf: [sasl_mechrouter.MAX_B64_MESSAGE]u8 = undefined;
        try self.handleIrcxAuthOutcome(id, conn, req.package, conn.session.sasl_router.?.receive(payload, &out_buf));
    }

    /// Validate an IRCX DATA tag: first char [A-Za-z], rest [A-Za-z0-9.], ≤15.
    fn validDataTag(tag: []const u8) bool {
        if (tag.len == 0 or tag.len > 15) return false;
        if (!std.ascii.isAlphabetic(tag[0])) return false;
        for (tag) |c| {
            if (!std.ascii.isAlphanumeric(c) and c != '.') return false;
        }
        return true;
    }

    /// Resolve remote DATA reserved-prefix authority from receiver-owned state.
    /// During Step 5 no remote operator authority is active: OCG1 records are
    /// compatibility telemetry only and OCG2 has no runtime consumer. OWN/HST
    /// therefore require authenticated channel rank; SYS/ADM fail closed.
    fn remoteDataTagAuthorized(
        self: *LinuxServer,
        tag: []const u8,
        is_channel: bool,
        sender_modes: ?world_model.MemberModes,
        policy_account: []const u8,
    ) bool {
        if (tag.len < 3) return true;
        const prefix = tag[0..3];
        _ = self;
        _ = policy_account;
        const policy_is_oper = false;
        if (std.ascii.eqlIgnoreCase(prefix, "SYS") or
            std.ascii.eqlIgnoreCase(prefix, "ADM")) return policy_is_oper;
        if (std.ascii.eqlIgnoreCase(prefix, "OWN") or
            std.ascii.eqlIgnoreCase(prefix, "HST"))
        {
            return policy_is_oper or
                (is_channel and (sender_modes orelse world_model.MemberModes.empty()).isOperator());
        }
        return true;
    }

    /// DATA / REQUEST / REPLY <target> <tag> :<message> — IRCX typed directed
    /// messaging. Tag rules: [A-z][A-z0-9.]{0,14}; reserved prefixes SYS/ADM need
    /// operator, OWN/HST need channel owner/host on a channel target. Relays
    /// `:sender <CMD> <target> <tag> :<message>` to the target (a nick, or all
    /// members of a channel).
    pub fn handleData(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (self.senderSilenced(conn)) return;
        if (parsed.param_count < 3) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{parsed.command}, "Not enough parameters");
            return;
        }
        const target = parsed.paramSlice()[0];
        const tag = parsed.paramSlice()[1];
        const message = parsed.paramSlice()[2];
        if (!validDataTag(tag)) {
            try queueNumeric(conn, .ERR_BADTAG, &.{tag}, "Invalid DATA tag");
            return;
        }
        var chan = target;
        var min_rank: u8 = 0;
        if (target.len >= 2) {
            const r = statusPrefixRank(target[0]);
            if (r > 0 and world_model.isChannelName(target[1..])) {
                min_rank = r;
                chan = target[1..];
            }
        }
        // Reserved-prefix authorization (case-insensitive 3-letter prefix).
        const is_chan = world_model.isChannelName(chan);
        if (tag.len >= 3) {
            const p = tag[0..3];
            if (std.ascii.eqlIgnoreCase(p, "SYS") or std.ascii.eqlIgnoreCase(p, "ADM")) {
                if (!conn.session.isOper()) {
                    try queueNumeric(conn, .ERR_NOACCESS, &.{tag}, "Reserved DATA tag (operator only)");
                    return;
                }
            } else if (std.ascii.eqlIgnoreCase(p, "OWN") or std.ascii.eqlIgnoreCase(p, "HST")) {
                const ok = is_chan and blk: {
                    const mm = self.world.memberModes(chan, worldIdFromClient(id)) orelse break :blk false;
                    break :blk mm.isOperator();
                };
                if (!ok and !conn.session.isOper()) {
                    try queueNumeric(conn, .ERR_NOACCESS, &.{tag}, "Reserved DATA tag (channel owner/host only)");
                    return;
                }
            }
        }
        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const line = formatMessage(&msg_buf, try clientPrefix(conn, &prefix_buf), parsed.command, &.{ target, tag }, message) catch return;
        if (is_chan) {
            if (!self.world.channelExists(chan)) {
                try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{target}, "You're not on that channel");
                return;
            }
            if (!self.world.isMember(chan, worldIdFromClient(id)) and !overrideActive(conn)) {
                try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{target}, "You're not on that channel");
                return;
            }
            // +V NOCOMICDATA: the channel has comic-chat DATA disabled. Members
            // below channel-operator are refused with ERR_NOCOMICDATA (531);
            // channel ops/founder and network opers bypass (they manage the
            // channel / hold oper_override), mirroring moderation semantics.
            if (self.world.channelHasExtFlag(chan, .nocomicdata)) {
                const is_chan_op = if (self.world.memberModes(chan, worldIdFromClient(id))) |mm| mm.isOperator() else false;
                if (!is_chan_op and !conn.session.isOper()) {
                    try queueNumeric(conn, .ERR_NOCOMICDATA, &.{target}, "Channel does not allow comic-chat DATA (+V)");
                    return;
                }
            }
            const speech = try self.channelSpeechGate(id, conn, target, chan, message, false, min_rank, true);
            if (speech == .deny) return;
            if (speech == .opmoderate) {
                // Held for ops only: no cross-node relay (mirrors the PRIVMSG
                // opmoderate path), so a muted remote member is never reached.
                var time_buf: [40]u8 = undefined;
                const tags = MsgTags{ .time_value = serverTimeValue(&time_buf), .account = conn.session.account() };
                try self.broadcastChannelMinRank(chan, tags, line, null, 2, .ordinary);
                self.publishModerationHeld(chan, conn, message);
                return;
            }
            const event_hlc = self.nextMeshHlc();
            var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer delivery_ids.deinit(self.allocator);
            self.collectChannelDeliveryIds(chan, min_rank, null, null, &delivery_ids) catch {
                try self.failReply(conn, parsed.command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete attachment delivery set");
                return;
            };
            var accepted_v2: ?AcceptedAuthoredRelayV2 = null;
            defer if (accepted_v2) |*accepted| accepted.deinit(self.allocator);
            if (self.authoredRelayV2Configured()) {
                accepted_v2 = self.admitAuthoredRelayV2(
                    dataVerbV2(parsed.command) orelse return,
                    chan,
                    min_rank,
                    try clientPrefix(conn, &prefix_buf),
                    conn.session.account() orelse "",
                    "",
                    tag,
                    message,
                    .channel,
                    "",
                    self.portableSessionTokenForClient(id, conn),
                    (self.world.memberModes(chan, worldIdFromClient(id)) orelse
                        world_model.MemberModes.empty()).bits,
                    null,
                    event_hlc,
                    null,
                    .{ .recipients = delivery_ids.items, .line = line },
                ) catch {
                    try self.failReply(conn, parsed.command, "TEMPORARILY_UNAVAILABLE", "Mesh durable admit failed; event not sent — check mesh peers and retry");
                    return;
                };
                if (accepted_v2 == null) {
                    try self.failReply(conn, parsed.command, "TEMPORARILY_UNAVAILABLE", "Mesh authority rejected the event; not delivered — retry or contact opers");
                    return;
                }
            }
            var msgid_buf: [msgid_mod.id_len]u8 = undefined;
            var time_buf: [40]u8 = undefined;
            const stable_msgid = if (accepted_v2) |accepted|
                msgid_mod.fromStableId(accepted.relay_id, &msgid_buf)
            else
                msgid_mod.fromMeshEvent(self.config.node_id, event_hlc, &msgid_buf);
            const event_tags = MsgTags{
                .time_value = serverTimeValueAt(
                    &time_buf,
                    mesh_clock_mod.MeshClock.physicalOf(event_hlc),
                ),
                .account = conn.session.account(),
                .msgid = stable_msgid,
            };
            if (min_rank > 0)
                try self.broadcastChannelMinRank(
                    chan,
                    event_tags,
                    line,
                    null,
                    min_rank,
                    if (accepted_v2) |accepted| accepted.deliveryMode() else .ordinary,
                )
            else
                try self.broadcastChannelTagged(
                    chan,
                    event_tags,
                    line,
                    null,
                    if (accepted_v2) |accepted| accepted.deliveryMode() else .ordinary,
                );
            // Cross-node relay: forward this typed DATA/REQUEST/REPLY to mesh
            // peers that have members of `chan` so remote co-members receive it.
            // Loop-guarded; the far side delivers only to its own local members.
            self.relayChannelData(
                conn,
                parsed.command,
                chan,
                tag,
                message,
                min_rank,
                event_hlc,
                if (accepted_v2) |accepted| accepted.wire else null,
            );
        } else {
            const rwid = self.world.findNick(target) orelse {
                // Not local: relay to the peer that owns this nick (route_table
                // narrowed; an unknown route fails closed with ERR_NOSUCHNICK
                // instead of flooding the mesh, mirroring the PRIVMSG nick path).
                if (self.relayNickData(id, conn, parsed.command, target, tag, message)) return;
                try queueNumeric(conn, .ERR_NOSUCHNICK, &.{target}, "No such nick");
                return;
            };
            const recipient_id = clientIdFromWorld(rwid);
            const recipient_conn = self.connFor(recipient_id) orelse return;
            var recipient_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer recipient_ids.deinit(self.allocator);
            self.collectAttachedExactTokenClients(recipient_id, recipient_conn, &recipient_ids) catch {
                try self.failReply(conn, parsed.command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete session recipient set");
                return;
            };
            var sender_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer sender_ids.deinit(self.allocator);
            if (!self.clientsShareExactToken(id, conn, recipient_id, recipient_conn)) {
                self.collectAttachedExactTokenClients(id, conn, &sender_ids) catch {
                    try self.failReply(conn, parsed.command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete session sender set");
                    return;
                };
            }

            const event_hlc = self.nextMeshHlc();
            const sender_token = self.portableSessionTokenForClient(id, conn);
            const recipient_token = self.portableSessionTokenForClient(recipient_id, recipient_conn);
            var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer delivery_ids.deinit(self.allocator);
            self.collectDirectDeliveryIds(
                recipient_ids.items,
                sender_ids.items,
                id,
                false,
                null,
                &delivery_ids,
            ) catch {
                try self.failReply(conn, parsed.command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete attachment delivery set");
                return;
            };
            var accepted_v2: ?AcceptedAuthoredRelayV2 = null;
            defer if (accepted_v2) |*accepted| accepted.deinit(self.allocator);
            if (recipient_token != null and self.authoredRelayV2Configured()) {
                accepted_v2 = self.admitAuthoredRelayV2(
                    dataVerbV2(parsed.command) orelse return,
                    target,
                    0,
                    try clientPrefix(conn, &prefix_buf),
                    conn.session.account() orelse "",
                    "",
                    tag,
                    message,
                    .direct,
                    "",
                    sender_token,
                    null,
                    recipient_token,
                    event_hlc,
                    null,
                    .{ .recipients = delivery_ids.items, .line = line },
                ) catch {
                    try self.failReply(conn, parsed.command, "TEMPORARILY_UNAVAILABLE", "Mesh durable admit failed; event not sent — check mesh peers and retry");
                    return;
                };
                if (accepted_v2 == null) {
                    try self.failReply(conn, parsed.command, "TEMPORARILY_UNAVAILABLE", "Mesh authority rejected the event; not delivered — retry or contact opers");
                    return;
                }
            }

            var msgid_buf: [msgid_mod.id_len]u8 = undefined;
            var time_buf: [40]u8 = undefined;
            const stable_msgid = if (accepted_v2) |accepted|
                msgid_mod.fromStableId(accepted.relay_id, &msgid_buf)
            else
                msgid_mod.fromMeshEvent(self.config.node_id, event_hlc, &msgid_buf);
            const event_tags = MsgTags{
                .time_value = serverTimeValueAt(
                    &time_buf,
                    mesh_clock_mod.MeshClock.physicalOf(event_hlc),
                ),
                .account = conn.session.account(),
                .msgid = stable_msgid,
            };
            for (recipient_ids.items) |recipient_attachment|
                self.deliverTaggedMode(
                    recipient_attachment,
                    event_tags,
                    line,
                    if (accepted_v2) |accepted| accepted.deliveryMode() else .ordinary,
                ) catch {};
            for (sender_ids.items) |sender_attachment| {
                if (sender_attachment.eql(id)) continue;
                var is_recipient = false;
                for (recipient_ids.items) |recipient_attachment| if (sender_attachment.eql(recipient_attachment)) {
                    is_recipient = true;
                    break;
                };
                if (!is_recipient) self.deliverTaggedMode(
                    sender_attachment,
                    event_tags,
                    line,
                    if (accepted_v2) |accepted| accepted.deliveryMode() else .ordinary,
                ) catch {};
            }
            if (accepted_v2) |accepted| {
                self.forwardAcceptedRelayV2(accepted.wire);
                var relay_msg = s2s_link.RelayMessage{
                    .verb = dataVerb(parsed.command) orelse return,
                    .target = target,
                    .source_nick = conn.session.displayName(),
                    .source_prefix = try clientPrefix(conn, &prefix_buf),
                    .account = conn.session.account() orelse "",
                    .text = message,
                    .data_tag = tag,
                    .origin_node = self.config.node_id,
                    .hlc = event_hlc,
                };
                var pk_buf: [message_relay.pubkey_len]u8 = undefined;
                var sig_buf: [message_relay.sig_len]u8 = undefined;
                self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
                _ = self.relayLegacyToPeers(relay_msg, .{ .session_nick = .{
                    .nick = target,
                    .token = recipient_token.?,
                    .also_token = sender_token,
                } }, true);
            }
        }
    }

    /// Map an IRCX typed-message command word to its relay `Verb`. Returns null
    /// for anything that is not a relayable typed verb.
    fn dataVerb(command: []const u8) ?message_relay.Verb {
        const eqi = std.ascii.eqlIgnoreCase;
        if (eqi(command, "DATA")) return .data;
        if (eqi(command, "REQUEST")) return .request;
        if (eqi(command, "REPLY")) return .reply;
        return null;
    }

    fn dataVerbV2(command: []const u8) ?message_relay_v2.Verb {
        const eqi = std.ascii.eqlIgnoreCase;
        if (eqi(command, "DATA")) return .data;
        if (eqi(command, "REQUEST")) return .request;
        if (eqi(command, "REPLY")) return .reply;
        return null;
    }

    /// Relay a channel-targeted DATA/REQUEST/REPLY to mesh peers with members of
    /// `chan`. Best-effort and loop-guarded (records own origin/hlc in the
    /// seen-set so the echo back is dropped).
    fn relayChannelData(
        self: *LinuxServer,
        conn: *ConnState,
        command: []const u8,
        chan: []const u8,
        data_tag: []const u8,
        message: []const u8,
        min_rank: u8,
        hlc: u64,
        accepted_v2_wire: ?[]const u8,
    ) void {
        if (!self.hasEstablishedPeer() and accepted_v2_wire == null) return;
        const verb = dataVerb(command) orelse return;
        var pbuf: [320]u8 = undefined;
        const prefix = clientPrefix(conn, &pbuf) catch return;
        _ = self.relay_seen.observe(self.config.node_id, hlc);
        var relay_msg = s2s_link.RelayMessage{
            .verb = verb,
            .target = chan,
            .min_rank = min_rank,
            .source_nick = conn.session.displayName(),
            .source_prefix = prefix,
            .account = conn.session.account() orelse "",
            .text = message,
            .data_tag = data_tag,
            .origin_node = self.config.node_id,
            .hlc = hlc,
        };
        var pk_buf: [message_relay.pubkey_len]u8 = undefined;
        var sig_buf: [message_relay.sig_len]u8 = undefined;
        self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
        if (accepted_v2_wire) |wire| self.forwardAcceptedRelayV2(wire);
        _ = self.relayLegacyToPeers(relay_msg, .{ .channel = chan }, accepted_v2_wire != null);
    }

    /// Relay a nick-targeted DATA/REQUEST/REPLY to the peer that owns `nick`.
    /// Returns true when at least one peer link accepted the relay (the nick is
    /// reachable across the mesh); false when no route is known (caller then
    /// emits ERR_NOSUCHNICK rather than flooding the mesh).
    fn relayNickData(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        command: []const u8,
        nick: []const u8,
        data_tag: []const u8,
        message: []const u8,
    ) bool {
        const recipient_token = self.detachedReplicaTokenForNick(nick);
        if (!self.hasEstablishedPeer() and recipient_token == null) return false;
        const verb = dataVerb(command) orelse return false;
        var pbuf: [320]u8 = undefined;
        const prefix = clientPrefix(conn, &pbuf) catch return false;
        const hlc = self.nextMeshHlc();
        var accepted_v2: ?AcceptedAuthoredRelayV2 = null;
        defer if (accepted_v2) |*accepted| accepted.deinit(self.allocator);
        const sender_token = self.portableSessionTokenForClient(id, conn);
        var sender_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer sender_ids.deinit(self.allocator);
        self.collectAttachedExactTokenClients(id, conn, &sender_ids) catch return false;
        var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer delivery_ids.deinit(self.allocator);
        self.collectDirectDeliveryIds(
            &.{},
            sender_ids.items,
            id,
            false,
            null,
            &delivery_ids,
        ) catch return false;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const rendered = formatMessage(&msg_buf, prefix, command, &.{ nick, data_tag }, message) catch return false;
        if (recipient_token != null and self.authoredRelayV2Configured()) {
            accepted_v2 = self.admitAuthoredRelayV2(
                dataVerbV2(command) orelse return false,
                nick,
                0,
                prefix,
                conn.session.account() orelse "",
                "",
                data_tag,
                message,
                .direct,
                "",
                sender_token,
                null,
                recipient_token,
                hlc,
                null,
                .{ .recipients = delivery_ids.items, .line = rendered },
            ) catch return false;
            if (accepted_v2 == null) return false;
        }
        _ = self.relay_seen.observe(self.config.node_id, hlc);
        var relay_msg = s2s_link.RelayMessage{
            .verb = verb,
            .target = nick,
            .source_nick = conn.session.displayName(),
            .source_prefix = prefix,
            .account = conn.session.account() orelse "",
            .text = message,
            .data_tag = data_tag,
            .origin_node = self.config.node_id,
            .hlc = hlc,
        };
        var pk_buf: [message_relay.pubkey_len]u8 = undefined;
        var sig_buf: [message_relay.sig_len]u8 = undefined;
        self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
        if (accepted_v2) |accepted| self.forwardAcceptedRelayV2(accepted.wire);
        const scope: RelayScope = if (recipient_token) |token| .{ .session_nick = .{
            .nick = nick,
            .token = token,
            .also_token = sender_token,
        } } else .{ .nick = nick };
        const legacy_count = self.relayLegacyToPeers(relay_msg, scope, accepted_v2 != null);
        if (accepted_v2) |accepted| {
            var msgid_buf: [msgid_mod.id_len]u8 = undefined;
            var time_buf: [40]u8 = undefined;
            const event_tags = MsgTags{
                .time_value = serverTimeValueAt(&time_buf, mesh_clock_mod.MeshClock.physicalOf(hlc)),
                .account = conn.session.account(),
                .msgid = msgid_mod.fromStableId(accepted.relay_id, &msgid_buf),
            };
            for (sender_ids.items) |sender_attachment| {
                if (sender_attachment.eql(id)) continue;
                self.deliverPreparedTagged(sender_attachment, event_tags, rendered) catch {};
            }
        }
        return legacy_count > 0 or accepted_v2 != null;
    }

    /// WHISPER <channel> <nick[,nick...]> :<text> — IRCX channel-scoped private
    /// message. The sender must be on the channel; each recipient is delivered a
    /// `:sender WHISPER <channel> <nick> :<text>` line only if also on the channel
    /// (ERR_NOSUCHNICK 401 / ERR_NOTONCHANNEL 442 per failing recipient).
    pub fn handleWhisper(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        var recipient_storage: [whisper.DEFAULT_MAX_RECIPIENTS][]const u8 = undefined;
        const args = whisper.parseWhisperArgs(parsed.paramSlice(), &recipient_storage) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"WHISPER"}, "Not enough parameters");
            return;
        };
        if (!self.world.channelExists(args.channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{args.channel}, "No such channel");
            return;
        }
        if (!self.world.isMember(args.channel, worldIdFromClient(id))) {
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{args.channel}, "You're not on that channel");
            return;
        }
        // +w NOWHISPER blocks channel whispers (IRCX ERR_NOWHISPER 923).
        if (self.world.channelHasExtFlag(args.channel, .nowhisper)) {
            try queueNumeric(conn, .ERR_NOWHISPER, &.{args.channel}, "Channel does not allow whispers (+w)");
            return;
        }
        const sender = whisper.Prefix{
            .nick = conn.session.displayName(),
            .user = conn.session.username(),
            .host = hostOf(conn),
        };
        for (args.recipients) |nick| {
            const rwid = self.world.findNick(nick) orelse {
                // Not a local nick: try the mesh. The recipient must be a member
                // of THIS shared channel on a remote node (WHISPER's invariant).
                // We scope the relay to the owning peer (never flood the mesh);
                // a genuinely-unknown nick falls back to ERR_NOSUCHNICK.
                if (!self.relayWhisperRemote(id, conn, args.channel, nick, args.text)) {
                    try queueNumeric(conn, .ERR_NOSUCHNICK, &.{nick}, "No such nick");
                }
                continue;
            };
            if (!self.world.isMember(args.channel, rwid)) {
                try queueNumeric(conn, .ERR_USERNOTINCHANNEL, &.{ nick, args.channel }, "They aren't on that channel");
                continue;
            }
            var line_buf: [default_reply_bytes]u8 = undefined;
            const line = whisper.buildWhisperLine(&line_buf, sender, args.channel, nick, args.text) catch continue;
            var crlf_buf: [default_reply_bytes]u8 = undefined;
            const out = std.fmt.bufPrint(&crlf_buf, "{s}\r\n", .{line}) catch continue;
            const recipient_id = clientIdFromWorld(rwid);
            const recipient_conn = self.connFor(recipient_id) orelse continue;
            var recipient_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer recipient_ids.deinit(self.allocator);
            self.collectAttachedExactTokenClients(recipient_id, recipient_conn, &recipient_ids) catch {
                try self.failReply(conn, "WHISPER", "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete session recipient set");
                return;
            };
            var sender_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer sender_ids.deinit(self.allocator);
            if (!self.clientsShareExactToken(id, conn, recipient_id, recipient_conn)) {
                self.collectAttachedExactTokenClients(id, conn, &sender_ids) catch {
                    try self.failReply(conn, "WHISPER", "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete session sender set");
                    return;
                };
            }
            const event_hlc = self.nextMeshHlc();
            const sender_token = self.portableSessionTokenForClient(id, conn);
            const recipient_token = self.portableSessionTokenForClient(recipient_id, recipient_conn);
            var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer delivery_ids.deinit(self.allocator);
            self.collectDirectDeliveryIds(
                recipient_ids.items,
                sender_ids.items,
                id,
                false,
                null,
                &delivery_ids,
            ) catch {
                try self.failReply(conn, "WHISPER", "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete attachment delivery set");
                return;
            };
            var accepted_v2: ?AcceptedAuthoredRelayV2 = null;
            defer if (accepted_v2) |*accepted| accepted.deinit(self.allocator);
            if (recipient_token != null and self.authoredRelayV2Configured()) {
                var source_prefix_buf: [320]u8 = undefined;
                accepted_v2 = self.admitAuthoredRelayV2(
                    .whisper,
                    args.channel,
                    0,
                    try clientPrefix(conn, &source_prefix_buf),
                    conn.session.account() orelse "",
                    "",
                    "",
                    args.text,
                    .channel_whisper,
                    nick,
                    sender_token,
                    (self.world.memberModes(args.channel, worldIdFromClient(id)) orelse
                        world_model.MemberModes.empty()).bits,
                    recipient_token,
                    event_hlc,
                    null,
                    .{ .recipients = delivery_ids.items, .line = out },
                ) catch {
                    try self.failReply(conn, "WHISPER", "TEMPORARILY_UNAVAILABLE", "Mesh durable admit failed; event not sent — check mesh peers and retry");
                    return;
                };
                if (accepted_v2 == null) {
                    try self.failReply(conn, "WHISPER", "TEMPORARILY_UNAVAILABLE", "Mesh authority rejected the event; not delivered — retry or contact opers");
                    return;
                }
            }
            var msgid_buf: [msgid_mod.id_len]u8 = undefined;
            var time_buf: [40]u8 = undefined;
            const stable_msgid = if (accepted_v2) |accepted|
                msgid_mod.fromStableId(accepted.relay_id, &msgid_buf)
            else
                msgid_mod.fromMeshEvent(self.config.node_id, event_hlc, &msgid_buf);
            const event_tags = MsgTags{
                .time_value = serverTimeValueAt(
                    &time_buf,
                    mesh_clock_mod.MeshClock.physicalOf(event_hlc),
                ),
                .account = conn.session.account(),
                .msgid = stable_msgid,
            };
            // A single failed physical recipient must not abort healthy exact-token
            // siblings; every attachment remains an independent transport.
            for (recipient_ids.items) |recipient_attachment|
                self.deliverTaggedMode(
                    recipient_attachment,
                    event_tags,
                    out,
                    if (accepted_v2) |accepted| accepted.deliveryMode() else .ordinary,
                ) catch {};
            for (sender_ids.items) |sender_attachment| {
                if (sender_attachment.eql(id)) continue;
                var already_recipient = false;
                for (recipient_ids.items) |recipient_attachment| if (sender_attachment.eql(recipient_attachment)) {
                    already_recipient = true;
                    break;
                };
                if (!already_recipient) self.deliverTaggedMode(
                    sender_attachment,
                    event_tags,
                    out,
                    if (accepted_v2) |accepted| accepted.deliveryMode() else .ordinary,
                ) catch {};
            }
            if (accepted_v2) |accepted| {
                self.forwardAcceptedRelayV2(accepted.wire);
                var source_prefix_buf: [320]u8 = undefined;
                var relay_msg = s2s_link.RelayMessage{
                    .verb = .whisper,
                    .target = args.channel,
                    .source_nick = conn.session.displayName(),
                    .source_prefix = try clientPrefix(conn, &source_prefix_buf),
                    .account = conn.session.account() orelse "",
                    .text = args.text,
                    .recipient = nick,
                    .origin_node = self.config.node_id,
                    .hlc = event_hlc,
                };
                var pk_buf: [message_relay.pubkey_len]u8 = undefined;
                var sig_buf: [message_relay.sig_len]u8 = undefined;
                self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
                _ = self.relayLegacyToPeers(relay_msg, .{ .session_nick = .{
                    .nick = nick,
                    .token = recipient_token.?,
                    .also_token = sender_token,
                } }, true);
            }
        }
    }

    /// True if `nick` is a remote member of `channel` per any peer's converged
    /// route roster — the cross-shard form of `world.isMember` used to satisfy
    /// WHISPER's "recipient shares the channel" invariant for remote recipients.
    fn remoteMemberOfChannel(self: *LinuxServer, channel: []const u8, nick: []const u8) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                if (slot.value.s2s_secured) |link| {
                    if (link.established() and linkChannelHasMember(link, channel, nick)) return true;
                } else if (slot.value.s2s) |link| {
                    if (link.established() and linkChannelHasMember(link, channel, nick)) return true;
                }
            }
        }
        return false;
    }

    /// True only when the converged remote roster binds `nick`'s membership in
    /// `channel` to this exact authenticated origin. This is the receiver-side
    /// sender-membership proof for WHISPER; nick-only membership is insufficient
    /// because a different node may legitimately (or maliciously) claim it.
    fn remoteMemberOfChannelAtNode(self: *LinuxServer, channel: []const u8, nick: []const u8, origin_node: u64) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const members = if (slot.value.s2s_secured) |link| blk: {
                    if (!link.established()) continue;
                    break :blk link.channelMembers(channel);
                } else if (slot.value.s2s) |link| blk: {
                    if (!link.established()) continue;
                    break :blk link.channelMembers(channel);
                } else continue;
                for (members) |member| {
                    if (member.node == origin_node and std.ascii.eqlIgnoreCase(member.nick, nick)) return true;
                }
            }
        }
        return false;
    }

    /// Per-link roster probe: does `link`'s converged roster list `nick` as a
    /// member of `channel`? (ASCII case-insensitive, matching nick comparison.)
    fn linkChannelHasMember(link: anytype, channel: []const u8, nick: []const u8) bool {
        for (link.channelMembers(channel)) |m| {
            if (std.ascii.eqlIgnoreCase(m.nick, nick)) return true;
        }
        return false;
    }

    /// Relay a WHISPER to a remote recipient that shares `channel`. Returns true
    /// when the recipient is a known remote co-member AND at least one peer link
    /// (route_table-narrowed to the owning node) accepted the relay; false
    /// otherwise so the caller can emit ERR_NOSUCHNICK. Loop-guarded.
    fn relayWhisperRemote(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        nick: []const u8,
        text: []const u8,
    ) bool {
        const recipient_token = self.detachedReplicaTokenForNick(nick);
        if (!self.hasEstablishedPeer() and recipient_token == null) return false;
        // Enforce the channel-membership invariant against the remote roster
        // before relaying so an off-channel nick yields ERR_NOSUCHNICK, not a leak.
        if (!self.remoteMemberOfChannel(channel, nick)) return false;
        var pbuf: [320]u8 = undefined;
        const prefix = clientPrefix(conn, &pbuf) catch return false;
        const hlc = self.nextMeshHlc();
        const sender_token = self.portableSessionTokenForClient(id, conn);
        var sender_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer sender_ids.deinit(self.allocator);
        self.collectAttachedExactTokenClients(id, conn, &sender_ids) catch return false;
        var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer delivery_ids.deinit(self.allocator);
        self.collectDirectDeliveryIds(
            &.{},
            sender_ids.items,
            id,
            false,
            null,
            &delivery_ids,
        ) catch return false;
        const sender = whisper.Prefix{
            .nick = conn.session.displayName(),
            .user = conn.session.username(),
            .host = hostOf(conn),
        };
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = whisper.buildWhisperLine(&line_buf, sender, channel, nick, text) catch return false;
        var crlf_buf: [default_reply_bytes]u8 = undefined;
        const out = std.fmt.bufPrint(&crlf_buf, "{s}\r\n", .{line}) catch return false;
        var accepted_v2: ?AcceptedAuthoredRelayV2 = null;
        defer if (accepted_v2) |*accepted| accepted.deinit(self.allocator);
        if (recipient_token != null and self.authoredRelayV2Configured()) {
            accepted_v2 = self.admitAuthoredRelayV2(
                .whisper,
                channel,
                0,
                prefix,
                conn.session.account() orelse "",
                "",
                "",
                text,
                .channel_whisper,
                nick,
                sender_token,
                (self.world.memberModes(channel, worldIdFromClient(id)) orelse
                    world_model.MemberModes.empty()).bits,
                recipient_token,
                hlc,
                null,
                .{ .recipients = delivery_ids.items, .line = out },
            ) catch return false;
            if (accepted_v2 == null) return false;
        }
        _ = self.relay_seen.observe(self.config.node_id, hlc);
        // Scope to peers that have members of the SHARED channel. WHISPER's
        // recipient is known only via channel membership (the per-nick route
        // map tracks server names, not arbitrary user nicks), so `.channel`
        // narrowing is both correct and never floods the wider mesh.
        var relay_msg = s2s_link.RelayMessage{
            .verb = .whisper,
            .target = channel,
            .source_nick = conn.session.displayName(),
            .source_prefix = prefix,
            .account = conn.session.account() orelse "",
            .text = text,
            .recipient = nick,
            .origin_node = self.config.node_id,
            .hlc = hlc,
        };
        var pk_buf: [message_relay.pubkey_len]u8 = undefined;
        var sig_buf: [message_relay.sig_len]u8 = undefined;
        self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
        if (accepted_v2) |accepted| self.forwardAcceptedRelayV2(accepted.wire);
        const scope: RelayScope = if (recipient_token) |token| .{ .session_nick = .{
            .nick = nick,
            .token = token,
            .also_token = sender_token,
        } } else .{ .channel = channel };
        const legacy_count = self.relayLegacyToPeers(relay_msg, scope, accepted_v2 != null);
        if (accepted_v2) |accepted| {
            var msgid_buf: [msgid_mod.id_len]u8 = undefined;
            var time_buf: [40]u8 = undefined;
            const event_tags = MsgTags{
                .time_value = serverTimeValueAt(
                    &time_buf,
                    mesh_clock_mod.MeshClock.physicalOf(hlc),
                ),
                .account = conn.session.account(),
                .msgid = msgid_mod.fromStableId(accepted.relay_id, &msgid_buf),
            };
            for (sender_ids.items) |sender_attachment| {
                if (sender_attachment.eql(id)) continue;
                self.deliverPreparedTagged(sender_attachment, event_tags, out) catch {};
            }
        }
        return legacy_count > 0 or accepted_v2 != null;
    }

    fn clonePublicChannelProps(self: *LinuxServer, src: []const u8, dst: []const u8) void {
        const src_entity = ircx_prop_store.Entity{ .kind = .channel, .id = src };
        const dst_entity = ircx_prop_store.Entity{ .kind = .channel, .id = dst };
        var views: [ircx_prop_store.default_max_props_per_entity]ircx_prop_store.EntryView = undefined;
        const rows = self.props.listProps(src_entity, &views) catch return;
        for (rows) |entry| {
            const ev = self.props.setProp(dst_entity, entry.key, entry.value, .{ .id = entry.owner, .access = entry.access }) catch continue;
            const hlc = self.nextChannelPropHlc();
            var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
            var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
            const ps = self.signLocalChannelProp(true, ev.entity.id, ev.key, ev.value, ev.owner, hlc, &pk_buf, &sig_buf);
            if (self.recordChannelPropClock(ev.entity.id, ev.key, ev.owner, hlc, true, ps.node, ps.pubkey, ps.sig)) {
                self.announceChannelProp(ev.entity.id, ev.key, ev.value, ev.owner, hlc, true, .{ .node = ps.node, .pubkey = ps.pubkey, .sig = ps.sig });
            }
        }
    }

    /// CREATE <channel> [modes] [clone-source] — IRCX channel creation
    /// (create-or-join as founder). Delegates to the JOIN path after parsing the
    /// IRCX form. With a clone source, the source channel's channel-level modes
    /// and portable room metadata are copied onto the new channel before the
    /// requested `modes` are applied on top as an override.
    pub fn handleCreate(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const req = ircx_create_cmd.parseParams(parsed.paramSlice()) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"CREATE"}, "Invalid CREATE");
            return;
        };
        if (self.world.channelExists(req.channel)) {
            try queueNumeric(conn, .ERR_CHANNELEXIST, &.{req.channel}, "Channel already exists");
            return;
        }
        if (req.clone_from) |source| {
            // Clone materialization is the first irreversible CREATE side effect,
            // so duplicate joinOneWith's target-only denial gates while the
            // target is still absent. Pre-seating the founder would otherwise
            // bypass CHANLIMIT and a later SACCESS return would orphan the clone.
            if (self.saccess.matchChannel(req.channel)) |entry| {
                try queueNumeric(conn, .ERR_UNAVAILRESOURCE, &.{req.channel}, serverAccessReason(entry, "Channel blocked by SACCESS"));
                return;
            }
            const chan_cap = if (conn.class_policy.max_channels != 0) conn.class_policy.max_channels else self.config.chanlimit;
            if (!conn.session.isOper() and
                self.world.channelCountOf(worldIdFromClient(id)) >= chan_cap)
            {
                try queueNumeric(conn, .ERR_TOOMANYCHANNELS, &.{req.channel}, "You have joined too many channels");
                return;
            }
            // Clone the template's channel-level modes/limit/key/ext into the new
            // (empty) target. A missing source is reported like any other missing
            // channel and the target is NOT created.
            if (!self.world.channelExists(source)) {
                try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{source}, "No such channel");
                return;
            }
            if (try self.akickDenied(conn, req.channel, null, false)) return;
            var prepared_clone = (self.world.prepareCloneTemplate(source, req.channel) catch |err| switch (err) {
                error.NoSuchChannel => {
                    try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{source}, "No such channel");
                    return;
                },
                else => return err,
            }) orelse {
                try queueNumeric(conn, .ERR_CHANNELEXIST, &.{req.channel}, "Channel already exists");
                return;
            };
            defer prepared_clone.abort();
            const reversible_arm = self.armReversibleLocalChannelProjectionForClient(
                id,
                conn,
                req.channel,
                false,
                0,
            ) catch {
                try self.failReply(conn, "CREATE", "TEMPORARILY_UNAVAILABLE", "Session channel state is busy; retry CREATE");
                return;
            };
            prepared_clone.commitSeated(
                worldIdFromClient(id),
                world_model.MemberModes.fromModes(&.{.founder}),
            ) catch {
                self.rollbackReversibleLocalChannelProjection(reversible_arm);
                try self.failReply(conn, "CREATE", "TEMPORARILY_UNAVAILABLE", "Channel state is busy; retry CREATE");
                return;
            };
            self.clonePublicChannelProps(source, req.channel);
            try self.joinOneWith(id, conn, req.channel, null, 0, true, reversible_arm.work);
        } else {
            try self.joinOneWith(id, conn, req.channel, null, 0, false, null);
        }
        if (req.clone_from != null) {
            // joinOne suppresses the founder-MODE broadcast on a pre-existing
            // (cloned) channel; announce the inherited channel modes explicitly so
            // members see the clone's flags.
            var flags_buf: [16]u8 = undefined;
            const flags = self.world.channelModeString(req.channel, &flags_buf);
            if (flags.len > 1) {
                var line_buf: [default_reply_bytes]u8 = undefined;
                if (formatMessage(&line_buf, self.serverName(), "MODE", &.{ req.channel, flags }, null)) |msg|
                    self.broadcastChannel(req.channel, msg, null) catch {}
                else |_| {}
            }
        }
        if (req.initial_modes) |modes| {
            var synth = irc_line.LineView{ .raw = "", .command = "MODE" };
            synth.params[0] = req.channel;
            synth.params[1] = modes.raw;
            synth.param_count = 2;
            self.handleMode(id, conn, &synth) catch {};
        }
    }

    /// Whether `conn` may mutate metadata on `target`: own nick (case-insensitive)
    /// or a channel where the client holds operator status. Opers may write anywhere.
    fn metadataCanWrite(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, target: []const u8) bool {
        if (conn.session.isOper()) return true;
        // `*` is the IRCv3 metadata-2 alias for the requesting client itself.
        if (std.mem.eql(u8, target, "*")) return true;
        if (world_model.isChannelName(target)) {
            const mm = self.world.memberModes(target, worldIdFromClient(id)) orelse return false;
            return mm.isOperator();
        }
        return std.ascii.eqlIgnoreCase(target, conn.session.displayName());
    }

    fn metadataCanRead(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, target: []const u8, visibility: metadata_store.Visibility) bool {
        if (visibility == .public) return true;
        if (visibility == .secret) return false;
        if (conn.session.isOper()) return true;
        if (std.mem.eql(u8, target, "*") or std.ascii.eqlIgnoreCase(target, conn.session.displayName())) return true;
        if (world_model.isChannelName(target)) {
            const mm = self.world.memberModes(target, worldIdFromClient(id)) orelse return false;
            return switch (visibility) {
                .members => true,
                .admins => mm.isOperator(),
                .server => false,
                .public, .secret => unreachable,
            };
        }
        return false;
    }

    fn metadataTargetConn(self: *LinuxServer, actor: *ConnState, store_target: []const u8) ?*ConnState {
        if (std.ascii.eqlIgnoreCase(store_target, actor.session.displayName())) return actor;
        const wid = self.world.findNick(store_target) orelse return null;
        return self.connFor(clientIdFromWorld(wid));
    }

    fn metadataNotifyVisibility(visibility: metadata_store.Visibility) metadata_proto.Visibility {
        return switch (visibility) {
            .public => .public,
            .members => .members,
            .admins => .admins,
            .server => .server,
            .secret => .secret,
        };
    }

    fn notifyMetadataWatchers(
        self: *LinuxServer,
        actor: *ConnState,
        store_target: []const u8,
        key: []const u8,
        value: ?[]const u8,
        visibility: metadata_store.Visibility,
    ) void {
        if (world_model.isChannelName(store_target)) return;
        const target_conn = self.metadataTargetConn(actor, store_target) orelse return;
        const watcher_count = self.monitor.watcherCount(store_target);
        if (watcher_count == 0) return;

        var ids_buf: [128]monitor.ClientId = undefined;
        var allocated_ids: ?[]monitor.ClientId = null;
        defer if (allocated_ids) |buf| self.allocator.free(buf);
        const ids = if (watcher_count <= ids_buf.len) ids_buf[0..watcher_count] else blk: {
            const buf = self.allocator.alloc(monitor.ClientId, watcher_count) catch return;
            allocated_ids = buf;
            break :blk buf;
        };
        const n = self.monitor.watchersOf(store_target, ids);

        const event = extended_monitor_store.Event{
            .prefix = .{
                .nick = target_conn.session.displayName(),
                .user = target_conn.session.username(),
                .host = hostOf(target_conn),
            },
            .change = .{ .metadata = .{ .key = key, .value = value, .visibility = metadataNotifyVisibility(visibility) } },
        };
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = extended_monitor_store.buildEventLine(&line_buf, event) catch return;
        var out_buf: [default_reply_bytes]u8 = undefined;
        const out = std.fmt.bufPrint(&out_buf, "{s}\r\n", .{line}) catch return;

        for (ids[0..n]) |watcher| {
            const wid = clientIdFromMonitor(watcher);
            const wconn = self.connFor(wid) orelse continue;
            if (!wconn.session.hasCap(.extended_monitor) or !wconn.session.hasCap(.metadata_2)) continue;
            if (!self.metadataCanRead(wid, wconn, store_target, visibility)) continue;
            self.deliver(wid, out) catch continue;
        }
    }

    /// METADATA <target> <GET|LIST|SET|CLEAR> [key [:value]] — IRCv3 metadata-2.
    /// Per-target key/value store; RPL_KEYVALUE (761) + RPL_METADATAEND (762).
    pub fn handleMetadata(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.hasCap(.metadata_2)) {
            try queueNumeric(conn, .ERR_UNKNOWNCOMMAND, &.{"METADATA"}, "Unknown command");
            return;
        }
        if (parsed.param_count < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"METADATA"}, "Not enough parameters");
            return;
        }
        const target = parsed.paramSlice()[0];
        const sub = parsed.paramSlice()[1];
        // '*' is the IRCv3 metadata-2 alias for the requesting client. Key the
        // store by the resolved nick so each client has its own namespace, while
        // replies still echo the literal `target` the client sent.
        const store_target = if (std.mem.eql(u8, target, "*")) conn.session.displayName() else target;

        if (std.ascii.eqlIgnoreCase(sub, "GET")) {
            var i: usize = 2;
            while (i < parsed.param_count) : (i += 1) {
                const key = parsed.paramSlice()[i];
                if (self.metadata.get(store_target, key)) |ev| {
                    if (!self.metadataCanRead(id, conn, store_target, ev.visibility)) {
                        try queueNumeric(conn, .ERR_KEYNOPERMISSION, &.{ target, key }, "permission denied");
                        continue;
                    }
                    try queueNumeric(conn, .RPL_KEYVALUE, &.{ target, key, ev.ircv3VisibilityToken() }, ev.value);
                } else |_| {
                    try queueNumeric(conn, .ERR_KEYNOTSET, &.{ target, key }, "key not set");
                }
            }
        } else if (std.ascii.eqlIgnoreCase(sub, "LIST")) {
            var views: [64]metadata_store.EntryView = undefined;
            const all = self.metadata.list(store_target, &views) catch views[0..0];
            for (all) |ev| {
                if (!self.metadataCanRead(id, conn, store_target, ev.visibility)) continue;
                try queueNumeric(conn, .RPL_KEYVALUE, &.{ target, ev.key, ev.ircv3VisibilityToken() }, ev.value);
            }
        } else if (std.ascii.eqlIgnoreCase(sub, "SET")) {
            if (parsed.param_count < 3) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"METADATA"}, "Not enough parameters");
                return;
            }
            // Permission gate: a client may only mutate metadata on its own nick
            // or on a channel where it holds operator status.
            if (!self.metadataCanWrite(id, conn, target)) {
                try queueNumeric(conn, .ERR_KEYNOPERMISSION, &.{ target, parsed.paramSlice()[2] }, "permission denied");
                try queueNumeric(conn, .RPL_METADATAEND, &.{}, "end of metadata");
                return;
            }
            const key = parsed.paramSlice()[2];
            if (parsed.param_count >= 4 and parsed.paramSlice()[3].len != 0) {
                var visibility: metadata_store.Visibility = .public;
                var value_index: usize = 3;
                if (parsed.param_count >= 5) {
                    visibility = metadata_store.Visibility.fromToken(parsed.paramSlice()[3]) orelse {
                        try queueNumeric(conn, .ERR_KEYINVALID, &.{ target, key }, "invalid visibility");
                        return;
                    };
                    value_index = 4;
                }
                const value = parsed.paramSlice()[value_index];
                const ev = self.metadata.setWithVisibility(store_target, key, value, visibility) catch {
                    try queueNumeric(conn, .ERR_KEYINVALID, &.{ target, key }, "invalid key");
                    return;
                };
                try queueNumeric(conn, .RPL_KEYVALUE, &.{ target, key, ev.ircv3VisibilityToken() }, value);
                self.notifyMetadataWatchers(conn, store_target, key, value, ev.visibility);
                self.persistMetadata(conn, store_target, key, value, ev.visibility);
            } else {
                const old = self.metadata.get(store_target, key) catch null;
                const visibility = if (old) |ev| ev.visibility else .public;
                self.metadata.delete(store_target, key) catch {};
                try queueNumeric(conn, .RPL_KEYVALUE, &.{ target, key, visibility.token() }, "");
                self.notifyMetadataWatchers(conn, store_target, key, null, visibility);
                self.persistMetadataDelete(conn, store_target, key);
            }
        } else if (std.ascii.eqlIgnoreCase(sub, "CLEAR")) {
            if (!self.metadataCanWrite(id, conn, target)) {
                try queueNumeric(conn, .ERR_KEYNOPERMISSION, &.{ target, "*" }, "permission denied");
                try queueNumeric(conn, .RPL_METADATAEND, &.{}, "end of metadata");
                return;
            }
            var views: [64]metadata_store.EntryView = undefined;
            const all = self.metadata.list(store_target, &views) catch views[0..0];
            for (all) |ev| {
                var key_buf: [128]u8 = undefined;
                if (ev.key.len > key_buf.len) continue;
                @memcpy(key_buf[0..ev.key.len], ev.key);
                const key = key_buf[0..ev.key.len];
                const visibility = ev.ircv3VisibilityToken();
                self.metadata.delete(store_target, key) catch {};
                try queueNumeric(conn, .RPL_KEYVALUE, &.{ target, key, visibility }, "");
                self.notifyMetadataWatchers(conn, store_target, key, null, ev.visibility);
                self.persistMetadataDelete(conn, store_target, key);
            }
        }
        try queueNumeric(conn, .RPL_METADATAEND, &.{}, "end of metadata");
    }

    /// Persist a logged-in user's OWN metadata to their account (durable profile),
    /// so it survives a cold restart and is restored at next login. Channel and
    /// other-target metadata are not account-scoped and are skipped here.
    fn persistMetadata(self: *LinuxServer, conn: *ConnState, store_target: []const u8, key: []const u8, value: []const u8, visibility: metadata_store.Visibility) void {
        if (store_target.len != 0 and (store_target[0] == '#' or store_target[0] == '&' or store_target[0] == '%')) return;
        const acct = conn.session.account() orelse return;
        if (!std.ascii.eqlIgnoreCase(store_target, conn.session.displayName())) return;
        const svc = self.account_services orelse return;
        svc.metadataPut(acct, key, value, visibility.token()) catch {};
    }

    fn persistMetadataDelete(self: *LinuxServer, conn: *ConnState, store_target: []const u8, key: []const u8) void {
        if (store_target.len != 0 and (store_target[0] == '#' or store_target[0] == '&' or store_target[0] == '%')) return;
        const acct = conn.session.account() orelse return;
        if (!std.ascii.eqlIgnoreCase(store_target, conn.session.displayName())) return;
        const svc = self.account_services orelse return;
        svc.metadataDelete(acct, key) catch {};
    }

    /// Restore an account's durable metadata into the live store under the user's
    /// current nick at login, so a reconnecting/identifying user (and clients that
    /// query them) see their saved profile keys immediately.
    fn restoreAccountMetadata(self: *LinuxServer, conn: *ConnState, account: []const u8) void {
        if (self.account_services == null) return;
        const Ctx = struct { srv: *LinuxServer, nick: []const u8 };
        self.account_services.?.metadataForEach(account, Ctx{ .srv = self, .nick = conn.session.displayName() }, struct {
            fn cb(c: Ctx, key: []const u8, value: []const u8, vis: []const u8) void {
                const v = metadata_store.Visibility.fromToken(vis) orelse .public;
                _ = c.srv.metadata.setWithVisibility(c.nick, key, value, v) catch {};
            }
        }.cb);
    }

    /// Restore an account's persisted SILENCE masks into the live per-nick store at
    /// login, so a reconnecting user's ignore list is immediately back in effect.
    fn restoreAccountSilence(self: *LinuxServer, conn: *ConnState, account: []const u8) void {
        if (self.account_services == null) return;
        const cap: usize = if (conn.class_policy.silence != 0) conn.class_policy.silence else self.silence.params.max_masks_per_owner;
        const Ctx = struct { srv: *LinuxServer, owner: []const u8, cap: usize };
        self.account_services.?.silenceForEach(account, Ctx{ .srv = self, .owner = conn.session.displayName(), .cap = cap }, struct {
            fn cb(c: Ctx, mask: []const u8) void {
                _ = c.srv.silence.addWithLimit(c.owner, mask, c.cap) catch {};
            }
        }.cb);
    }

    /// REDACT <channel> <msgid> [:reason] — IRCv3 message-redaction. Tombstones
    /// the message in the CHATHISTORY ring (filtered from future replay) and
    /// broadcasts the redaction to the channel. Requires channel-operator.
    pub fn handleRedact(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.hasCap(.message_redaction)) {
            try self.failReply(conn, "REDACT", "NEED_REGISTRATION", "You must negotiate the draft/message-redaction capability");
            return;
        }
        if (parsed.param_count < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"REDACT"}, "Not enough parameters");
            return;
        }
        const channel = parsed.paramSlice()[0];
        const msgid = parsed.paramSlice()[1];
        const reason = if (parsed.param_count >= 3) parsed.paramSlice()[2] else null;
        if (!self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        const mm = self.world.memberModes(channel, worldIdFromClient(id)) orelse {
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{channel}, "You're not on that channel");
            return;
        };
        if (!mm.isOperator()) {
            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{channel}, "You're not channel operator");
            return;
        }
        self.history.redact(channel, msgid) catch |err| switch (err) {
            error.NotFound, error.InvalidTarget => {
                try self.failReply(conn, "REDACT", "UNKNOWN_MSGID", "Unknown message id");
                return;
            },
            else => return err,
        };
        // Drop the redacted message from the draft/search index so SEARCH no
        // longer surfaces it (the history slot is kept as a tombstone, but the
        // inverted index has no tombstone concept — we evict the msgid outright).
        _ = self.search_index.remove(msgid);
        var audit_target_buf: [320]u8 = undefined;
        const audit_target = std.fmt.bufPrint(&audit_target_buf, "{s} {s}", .{ channel, msgid }) catch channel;
        const audit_reason = reason orelse "REDACT";
        const proof_id = self.recordOperAudit(conn.session.displayName(), .redact, audit_target, audit_reason);
        var event_buf: [default_reply_bytes]u8 = undefined;
        const event_note = if (proof_id) |pid|
            std.fmt.bufPrint(&event_buf, "REDACT {s} {s} proof={s}", .{ channel, msgid, pid[0..] }) catch return
        else
            std.fmt.bufPrint(&event_buf, "REDACT {s} {s}", .{ channel, msgid }) catch return;
        self.publishOperEvent(.oper_action, .notice, event_note) catch {};
        var proof_reason_buf: [default_reply_bytes]u8 = undefined;
        var redaction_reason: ?[]const u8 = reason;
        if (proof_id) |pid| {
            redaction_reason = if (reason) |r|
                std.fmt.bufPrint(&proof_reason_buf, "{s} proof={s}", .{ r, pid[0..] }) catch r
            else
                std.fmt.bufPrint(&proof_reason_buf, "proof={s}", .{pid[0..]}) catch null;
        }
        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = try formatMessage(&msg_buf, try clientPrefix(conn, &prefix_buf), "REDACT", &.{ channel, msgid }, redaction_reason);
        try self.broadcastChannelCap(channel, msg, .message_redaction, null);
    }

    /// EDIT <target> <msgid> :text — draft/message-editing. Only the original
    /// sender may edit a message; channel operators cannot edit other users'
    /// messages. The history ring is updated so CHATHISTORY replays the new text.
    pub fn handleEdit(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, line: []const u8) !void {
        if (!conn.session.hasCap(.message_editing)) {
            try self.failReply(conn, "EDIT", "NEED_REGISTRATION", "You must negotiate the draft/message-editing capability");
            return;
        }
        const edit = msgedit.parseEditCommand(line) catch |err| {
            const reason: []const u8 = switch (err) {
                error.MissingTarget, error.MissingMsgid, error.MissingEditBody => "Missing EDIT parameters",
                else => "Invalid EDIT parameters",
            };
            try self.failReply(conn, "EDIT", "INVALID_PARAMS", reason);
            return;
        };

        var key_buf: [320]u8 = undefined;
        const store_target = self.historyKeyForTarget(conn, edit.target, &key_buf);
        if (world_model.isChannelName(edit.target)) {
            if (!self.world.channelExists(edit.target)) {
                try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{edit.target}, "No such channel");
                return;
            }
            if (!self.world.isMember(edit.target, worldIdFromClient(id))) {
                try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{edit.target}, "You're not on that channel");
                return;
            }
        } else if (self.world.findNick(edit.target) == null) {
            try queueNumeric(conn, .ERR_NOSUCHNICK, &.{edit.target}, "No such nick");
            return;
        }

        const original = self.historyMessageByMsgid(store_target, edit.msgid) orelse {
            try self.failReply(conn, "EDIT", "UNKNOWN_MSGID", "Unknown message id");
            return;
        };
        var current_prefix_buf: [256]u8 = undefined;
        const current_prefix = try clientPrefix(conn, &current_prefix_buf);
        if (!std.mem.eql(u8, original.sender, current_prefix)) {
            try self.failReply(conn, "EDIT", "PERMISSION_DENIED", "Only the original sender may edit a message");
            return;
        }

        self.history.edit(store_target, edit.msgid, edit.text) catch {
            try self.failReply(conn, "EDIT", "EDIT_FAILED", "Could not edit message");
            return;
        };
        // Re-index the new body so SEARCH matches the edited text, not the old
        // one. `index` first removes the msgid's prior words, then re-tokenizes.
        self.search_index.index(edit.msgid, edit.text) catch {};

        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = try formatMessage(&msg_buf, current_prefix, "PRIVMSG", &.{edit.target}, edit.text);
        var edit_tags_buf: [msgid_mod.id_len + 64]u8 = undefined;
        const edit_tags = std.fmt.bufPrint(&edit_tags_buf, "+draft/edit={s};+draft/revision=1", .{edit.msgid}) catch return;
        var time_buf: [40]u8 = undefined;
        const tags = MsgTags{
            .time_value = serverTimeValue(&time_buf),
            .account = conn.session.account(),
            .client_tags = edit_tags,
            .msgid = edit.msgid,
        };
        if (world_model.isChannelName(edit.target)) {
            try self.broadcastChannelTaggedCap(edit.target, tags, msg, .message_editing, null);
        } else if (self.world.findNick(edit.target)) |recipient| {
            const rid = clientIdFromWorld(recipient);
            if (self.connFor(rid)) |rconn| {
                if (rconn.session.hasCap(.message_editing)) try self.deliverTagged(rid, tags, msg);
            }
            try self.deliverTagged(id, tags, msg);
        }
    }

    /// HELP / HELPOP [topic] — static help topics (704/705/706, 524 if unknown).
    /// Defaults to the HELP index topic when no argument is given.
    pub fn handleHelp(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const topic = if (parsed.param_count >= 1 and parsed.paramSlice()[0].len != 0)
            parsed.paramSlice()[0]
        else
            "HELP";
        const reply = help_db.buildHelpLookupReply(self.allocator, self.serverName(), conn.session.displayName(), topic) catch return;
        defer self.allocator.free(reply);
        try appendToConn(conn, reply);
    }

    /// STATS k/d — list Warden wards of a match facet (RPL_STATSKLINE/DLINE).
    pub fn statsLines(self: *LinuxServer, conn: *ConnState, match: warden.Match, code: Numeric) !void {
        var rows: [256]warden.Ward = undefined;
        const wards = self.warden.list(match, &rows);
        for (wards) |w| {
            try queueNumeric(conn, code, &.{ w.match.token(), w.pattern, w.action.token() }, w.reason);
        }
    }

    /// LUSERS — network/user counters (251-255, 265/266).
    /// Count registered local user clients (excludes S2S links and connections
    /// still in registration). Shared by LUSERS and MAP so their user totals
    /// agree and never include peer links or half-open sockets.
    fn countRegisteredUsers(self: *LinuxServer) u64 {
        // Shared world nick registry (local clients only, consistent across
        // shards) — not this reactor's connection slice. See world.localNickCount.
        return @intCast(self.world.localNickCount());
    }

    /// Mesh-wide user total: this node's local nicks plus the distinct remote
    /// nicks each established S2S peer has announced into its route table. S2S
    /// links live only on reactor 0, so iterate every reactor (matching
    /// sendNames / findRemoteWhois); the whole completion runs under
    /// `world.lockWrite`, so the cross-reactor read is race-free. Each link's
    /// route table holds the nicks homed on that peer, so summing stays correct
    /// as long as a nick is homed on exactly one node (the mesh invariant).
    fn meshUserCount(self: *LinuxServer) u64 {
        var total: u64 = self.world.localNickCount();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                if (slot.value.s2s_secured) |link| {
                    if (link.established()) total += @intCast(link.remoteNickCount());
                } else if (slot.value.s2s) |link| {
                    if (link.established()) total += @intCast(link.remoteNickCount());
                }
            }
        }
        return total;
    }

    pub fn handleLusers(self: *LinuxServer, conn: *ConnState) !void {
        // Classify connections: registered local users vs unknown (still in
        // registration) vs established S2S peers (counted as servers, never
        // users). Previously every connection — S2S links and half-registered
        // sockets included — was lumped into `users`, and `unknown` was always 0.
        // Local registered users come from the shared world (the nick registry
        // holds only local clients and is consistent across reactor shards) —
        // iterating `self.rx().clients` would only see THIS shard's clients and
        // report a fraction of the node's users under multithreading.
        const users: u64 = @intCast(self.world.localNickCount());
        // opers/unknown remain best-effort per-shard: both are almost always 0
        // (their 252/253 lines only emit when >0), and there is no shared source
        // for half-registered sockets. A more exact cross-shard tally is not
        // worth the lifecycle bookkeeping for these rarely-nonzero fields.
        var unknown: u64 = 0;
        var opers: u64 = 0;
        var invisible: u64 = 0;
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            const c = entry.value;
            if (c.s2s != null or c.s2s_secured != null) continue;
            if (c.session.registered()) {
                if (c.session.isOper()) opers += 1;
                if (c.session.umodes.contains(.invisible)) invisible += 1;
            } else {
                unknown += 1;
            }
        }
        // Distinct peers + this node. Dedup collapses a transient duplicate link
        // to the same peer so the count never double-reports a neighbour.
        const servers: u64 = 1 + self.distinctPeerCount();
        // Network-wide user total for the global (251/266) figures. `users` stays
        // local for the 255/265 "Current local users" lines.
        const mesh: u64 = self.meshUserCount();
        const counts = lusers.Counts{
            .users = mesh,
            .invisible = invisible,
            .servers = servers,
            .opers = opers,
            .unknown = unknown,
            .channels = @intCast(self.world.channelCount()),
            .local_clients = users,
            .local_max = @max(users, self.stats_peak_clients),
            .global_clients = mesh,
            .global_max = @max(mesh, self.stats_peak_clients),
            // RPL_STATSCONN (250): the running peak client count and the
            // cumulative number of connections this node has accepted.
            .highest_connections = @max(users, self.stats_peak_clients),
            .total_connections = self.stats.connections_total.load(.monotonic),
        };
        var scratch: [default_reply_bytes]u8 = undefined;
        var sink = ConnLineSink{ .conn = conn };
        lusers.emit(.{ .server_name = self.serverName(), .requester = conn.session.displayName() }, counts, &scratch, &sink) catch return;
    }

    /// MOTD (375/372/376).
    /// Read + localize the configured weather source into `out` for the MOTD
    /// `{weather}` placeholder; empty on disabled/missing/unreadable source.
    /// Build the MOTD `{weather}` line for the connecting client. A configured
    /// `[weather] source` file (refreshed by an external updater) takes
    /// precedence; otherwise the line is served from the live geo cache,
    /// personalized to the user's `location` metadata, the configured default
    /// location, or — last resort — their GeoIP country, and localized to their
    /// `country`. Empty when nothing resolves (the `{if:weather}` block hides it).
    fn motdWeatherLine(self: *LinuxServer, conn: *ConnState, io: std.Io, out: []u8) []const u8 {
        // 1) File-based source (external updater) wins when configured.
        if (self.config.weather_enabled and self.config.weather_source.len != 0) {
            const content = std.Io.Dir.cwd().readFileAlloc(io, self.config.weather_source, self.allocator, .limited(4096)) catch return "";
            defer self.allocator.free(content);
            const f = weather_units.parseForecast(content);
            const country = if (self.config.weather_country.len != 0) self.config.weather_country else f.country;
            const loc = if (self.config.weather_location.len != 0) self.config.weather_location else f.location;
            const sys = weather_units.resolveSystem(self.config.weather_units, country);
            return weather_units.renderLine(out, loc, f.reading, sys);
        }
        // 2) Live geo cache, personalized to the connecting user.
        if (!self.config.geo_enabled) return "";
        const nick = conn.session.displayName();
        const country = self.metaValue(nick, "country");
        var location = self.metaValue(nick, "location");
        if (location.len == 0) location = self.config.weather_location;
        if (location.len == 0) location = country; // GeoIP country geolocates on the source
        if (location.len == 0) return "";
        const sys = weather_units.resolveSystem(self.config.weather_units, country);
        var loc_out: [64]u8 = undefined;
        var desc_out: [48]u8 = undefined;
        if (self.geo.getWeather(location, &loc_out, &desc_out)) |view| {
            return weather_units.renderLine(out, view.location, view.reading, sys);
        }
        return "";
    }

    /// Build the MOTD `{news}` line for the connecting client (first two
    /// headlines joined with " | "). A configured `[news] source` file wins;
    /// otherwise headlines come from the live geo cache, keyed by the user's
    /// GeoIP country feed when one exists, else the default wire. Empty hides the
    /// `{if:news}` block.
    fn motdNewsLine(self: *LinuxServer, conn: *ConnState, io: std.Io, out: []u8) []const u8 {
        // 1) File-based source (external updater) wins when configured.
        if (self.config.news_enabled and self.config.news_source.len != 0) {
            const content = std.Io.Dir.cwd().readFileAlloc(io, self.config.news_source, self.allocator, .limited(8192)) catch return "";
            defer self.allocator.free(content);
            var n: u32 = 0;
            var w: usize = 0;
            var it = std.mem.splitScalar(u8, content, '\n');
            while (it.next()) |raw| {
                if (n >= self.config.news_count) break;
                const line = std.mem.trim(u8, raw, " \t\r");
                if (line.len == 0 or line[0] == '#') continue;
                const sep: []const u8 = if (n == 0) "" else " | ";
                if (w + sep.len + line.len > out.len) break;
                @memcpy(out[w..][0..sep.len], sep);
                w += sep.len;
                @memcpy(out[w..][0..line.len], line);
                w += line.len;
                n += 1;
            }
            return out[0..w];
        }
        // 2) Live geo cache. Prefer the user's localized country feed; otherwise
        //    a RANDOM verified general source, varied per connect for variety.
        if (!self.config.geo_enabled) return "";
        const nick = conn.session.displayName();
        const cc = self.metaValue(nick, "country");
        var nbuf: [512]u8 = undefined;
        var lines: [5][]const u8 = undefined;
        var keybuf: [80]u8 = undefined;
        if (cc.len >= 2 and news_sources.countryFeed(cc[0..2]) != null) {
            const key = std.fmt.bufPrint(&keybuf, "cc:{s}", .{cc[0..2]}) catch return "";
            if (self.geo.getNews(key, &nbuf, &lines)) |got| return motdJoinHeadlines(got, out);
        }
        // Random general source, seeded by the clock mixed with the nick so each
        // connect varies. A cold pick enqueues a background fetch (warming the
        // pool); we try several and use the first warm one.
        const seed = self.nowU64() ^ std.hash.Wyhash.hash(0, nick);
        var attempt: usize = 0;
        while (attempt < 6) : (attempt += 1) {
            const src = news_sources.randomSource(seed +% attempt *% 0x9E3779B97F4A7C15);
            const key = std.fmt.bufPrint(&keybuf, "src:{s}", .{src.key}) catch return "";
            if (self.geo.getNews(key, &nbuf, &lines)) |got| return motdJoinHeadlines(got, out);
        }
        return "";
    }

    /// Join up to two cached headlines with " | " into `out` for the MOTD `{news}`
    /// placeholder. Returns the written slice (borrows `out`).
    fn motdJoinHeadlines(got: [][]const u8, out: []u8) []const u8 {
        var w: usize = 0;
        const take = @min(got.len, 2);
        for (got[0..take], 0..) |headline, idx| {
            const sep: []const u8 = if (idx == 0) "" else " | ";
            if (w + sep.len + headline.len > out.len) break;
            @memcpy(out[w..][0..sep.len], sep);
            w += sep.len;
            @memcpy(out[w..][0..headline.len], headline);
            w += headline.len;
        }
        return out[0..w];
    }

    pub fn handleMotd(self: *LinuxServer, conn: *ConnState) !void {
        // The MOTD is a personalized template: the configured [motd] text, or
        // the built-in default. It is expanded per connection (greeting by time
        // of day, the client's nick/account/host, live figures, and oper/login/
        // TLS conditionals) before being split into numeric reply lines.
        const template = if (self.config.motd_text_raw.len != 0)
            self.config.motd_text_raw
        else
            default_motd_template;

        var time_buf: [64]u8 = undefined;
        const now_ms = platform.realtimeMillis();
        const epoch_s: u64 = @intCast(@max(@as(i64, 0), @divFloor(now_ms, 1000)));

        // Optional localized weather + news, read fresh from their source files.
        var weather_buf: [256]u8 = undefined;
        var news_buf: [512]u8 = undefined;
        var weather_line: []const u8 = "";
        var news_line: []const u8 = "";
        if (self.config.crypto_io) |io| {
            // Ensure the background fetcher is running so the geo cache fills
            // (idempotent; the MOTD reads cache only, never blocks on network).
            if (self.config.geo_enabled) self.geo.start();
            weather_line = self.motdWeatherLine(conn, io, &weather_buf);
            news_line = self.motdNewsLine(conn, io, &news_buf);
        }

        const vars = motd_template.Vars{
            .nick = conn.session.displayName(),
            .account = conn.session.account(),
            .host = conn.session.host(),
            .network = protocol_inventory.currentNetworkName(),
            .server = self.serverName(),
            .version = server_version,
            .time = formatServerTime(&time_buf),
            // Network-wide total so a MOTD that says "users online" / "across the
            // mesh" reflects the whole mesh, not just this node's local clients.
            .users = self.meshUserCount(),
            .is_oper = conn.session.isOper(),
            .secure = conn.is_tls,
            .hour = @intCast(@mod(@divFloor(epoch_s, 3600), 24)),
            .weather = weather_line,
            .news = news_line,
        };

        var expanded_buf: [4096]u8 = undefined;
        // On overflow/malformed template, fall back to serving the raw text.
        const expanded = motd_template.expand(template, vars, &expanded_buf) catch template;

        var line_slices: [64][]const u8 = undefined;
        var n: usize = 0;
        var it = std.mem.splitScalar(u8, expanded, '\n');
        while (it.next()) |l| {
            if (n == line_slices.len) break;
            line_slices[n] = std.mem.trimEnd(u8, l, "\r");
            n += 1;
        }

        var out_buf: [8192]u8 = undefined;
        var lines_buf: [64]motd.MotdLine = undefined;
        var sink = motd.MotdLineSink{ .lines = &lines_buf };
        motd.writeMotdRepliesForRequester(&out_buf, self.serverName(), conn.session.displayName(), line_slices[0..n], &sink) catch return;
        for (sink.slice()) |line| {
            try appendToConn(conn, line.bytes);
            try appendToConn(conn, "\r\n");
        }
    }

    /// TIME (391) — current wall-clock server time.
    pub fn handleTime(self: *LinuxServer, conn: *ConnState) !void {
        var tbuf: [64]u8 = undefined;
        const tstr = formatServerTime(&tbuf);
        var out_buf: [default_reply_bytes]u8 = undefined;
        const line = serverinfo.writeTimeReply(&out_buf, .{ .server_name = self.serverName(), .requester = conn.session.displayName() }, self.serverName(), tstr) catch return;
        try appendToConn(conn, line);
    }

    /// ADMIN (256/257/258/259).
    pub fn handleAdmin(self: *LinuxServer, conn: *ConnState) !void {
        var out_buf: [default_reply_bytes]u8 = undefined;
        var lines_buf: [4]serverinfo.ReplyLine = undefined;
        var sink = serverinfo.ReplyLineSink{ .lines = &lines_buf };
        serverinfo.writeAdminReplies(&out_buf, .{ .server_name = self.serverName(), .requester = conn.session.displayName() }, .{
            .reply_server = protocol_inventory.currentServerName(),
            .location1 = self.config.admin_location,
            .email = self.config.admin_email,
        }, &sink) catch return;
        for (sink.slice()) |line| try appendToConn(conn, line.bytes);
    }

    /// VERSION (351).
    pub fn handleVersion(self: *LinuxServer, conn: *ConnState) !void {
        var out_buf: [default_reply_bytes]u8 = undefined;
        const info = serverinfo.VersionInfo{
            .version = server_version,
            // build token: compile target + git revision so opers can tell
            // binaries apart and pin the exact source commit.
            .build = @tagName(builtin.cpu.arch) ++ "-" ++ @tagName(builtin.os.tag) ++ "-" ++ build_info.git_commit,
            .branding = @tagName(builtin.mode),
            .reply_server = self.serverName(),
            .description = self.config.server_description,
        };
        const line = serverinfo.writeVersionReply(&out_buf, .{ .server_name = self.serverName(), .requester = conn.session.displayName() }, info) catch return;
        try appendToConn(conn, line);

        // Conventional ircd behaviour: VERSION re-advertises ISUPPORT (005) so a
        // client can refresh feature support without reconnecting. Mirrors the
        // single-line token set emitted at registration.
        try queueNumeric(conn, .RPL_ISUPPORT, protocol_inventory.currentIsupport(), "are supported by this server");
    }

    /// NICK <newnick> — registered nick change. Validates, rejects collisions
    /// (433), rewrites the world registry + session, then broadcasts
    /// `:old!u@h NICK :new` to the client and every common-channel member.
    /// MONITOR watchers see old offline / new online; the old identity is
    /// recorded in WHOWAS.
    /// Server-initiated forced nick change (nick-protection enforcement). Mirrors
    /// the broadcast path of handleNickChange. Best-effort: returns silently if the
    /// target nick is already taken (retried on a later sweep).
    fn collectExactLogicalClients(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        logical_ids: *std.ArrayList(client_model.ClientId),
    ) !void {
        try logical_ids.append(self.allocator, id);
        const account = conn.session.account() orelse return;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return;
        if (tokenIsNull(handle.token)) return;
        const rows = try self.sessions.copySessionsAlloc(self.allocator, account);
        defer self.allocator.free(rows);
        for (rows) |row| {
            if (!row.attached or row.client == monitorIdFromClient(id)) continue;
            if (!std.crypto.timing_safe.eql(sessions_mod.Token, row.token, handle.token)) continue;
            const sibling_id = clientIdFromMonitor(row.client);
            const sibling = self.connFor(sibling_id) orelse continue;
            if (sibling.closing or sibling.s2s != null or sibling.s2s_secured != null) continue;
            const sibling_account = sibling.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(sibling_account, account)) continue;
            try logical_ids.append(self.allocator, sibling_id);
        }
    }

    fn exactWorldIds(
        self: *LinuxServer,
        logical_ids: []const client_model.ClientId,
        world_ids: *std.ArrayList(world_model.ClientId),
    ) !void {
        try world_ids.ensureTotalCapacity(self.allocator, logical_ids.len);
        for (logical_ids) |logical_id| world_ids.appendAssumeCapacity(worldIdFromClient(logical_id));
    }

    fn existingExactWorldOwner(
        self: *LinuxServer,
        logical_ids: []const client_model.ClientId,
    ) client_model.ClientId {
        for (logical_ids) |logical_id| {
            if (self.world.nickOf(worldIdFromClient(logical_id)) != null) return logical_id;
        }
        return logical_ids[0];
    }

    /// Snapshot every recipient of one logical NICK event before changing any
    /// identity state. This keeps allocator failure on the safe side of the
    /// World/session transaction and a single seen set prevents duplicates when
    /// attachments or their channel peers overlap.
    fn collectExactLogicalNickRecipients(
        self: *LinuxServer,
        logical_ids: []const client_model.ClientId,
        recipients: *std.ArrayList(client_model.ClientId),
    ) !void {
        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();
        for (logical_ids) |logical_id| {
            try seen.put(@bitCast(logical_id), {});
            try recipients.append(self.allocator, logical_id);
        }
        var channels = self.world.channels.iterator();
        while (channels.next()) |entry| {
            var belongs = false;
            for (logical_ids) |logical_id| {
                if (entry.value_ptr.members.contains(worldIdFromClient(logical_id))) {
                    belongs = true;
                    break;
                }
            }
            if (!belongs) continue;
            var members = self.world.memberIterator(entry.key_ptr.*) orelse continue;
            while (members.next()) |member| {
                const member_id = clientIdFromWorld(member.*);
                const key: u64 = @bitCast(member_id);
                if (seen.contains(key)) continue;
                try seen.put(key, {});
                try recipients.append(self.allocator, member_id);
            }
        }
    }

    /// Output congestion on one transport must never prevent another attached
    /// transport or channel peer from observing the already-committed rename.
    fn deliverLogicalNickEvent(self: *LinuxServer, recipients: []const client_model.ClientId, msg: []const u8) void {
        for (recipients) |recipient| self.deliver(recipient, msg) catch {};
    }

    fn forceRenameTo(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, newnick: []const u8) void {
        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        self.collectExactLogicalClients(id, conn, &logical_ids) catch return;
        var logical_world_ids: std.ArrayList(world_model.ClientId) = .empty;
        defer logical_world_ids.deinit(self.allocator);
        self.exactWorldIds(logical_ids.items, &logical_world_ids) catch return;
        var nick_recipients: std.ArrayList(client_model.ClientId) = .empty;
        defer nick_recipients.deinit(self.allocator);
        self.collectExactLogicalNickRecipients(logical_ids.items, &nick_recipients) catch return;
        const registry_id = self.existingExactWorldOwner(logical_ids.items);
        const registry_conn = self.connFor(registry_id) orelse return;
        const registry_wid = worldIdFromClient(registry_id);

        var old_buf: [64]u8 = undefined;
        const old_slice = registry_conn.session.displayName();
        if (old_slice.len == 0 or old_slice.len > old_buf.len) return;
        @memcpy(old_buf[0..old_slice.len], old_slice);
        const old = old_buf[0..old_slice.len];
        const new_was_announced_online = self.monitor.isOnline(newnick);
        const old_remains_announced_online = self.localRenderedNickOccupiedExcept(old, logical_ids.items);
        var monitor_plan: ?PreparedMonitorTransition = null;
        defer if (monitor_plan) |*plan| plan.deinit(self.allocator);
        if (!std.mem.eql(u8, old, newnick)) {
            if (std.ascii.eqlIgnoreCase(old, newnick)) {
                self.monitor.reserveOnlineTransition(old, newnick, true, new_was_announced_online) catch return;
            } else {
                monitor_plan = self.prepareMonitorOccupancyTransition(
                    old,
                    newnick,
                    new_was_announced_online,
                ) catch return;
            }
        }

        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const old_prefix = clientPrefix(registry_conn, &prefix_buf) catch return;
        const msg = formatMessage(&msg_buf, old_prefix, "NICK", &.{}, newnick) catch return;

        _ = self.world.replaceExactSessionNickOwner(newnick, registry_wid, logical_world_ids.items) catch return;
        if (std.mem.eql(u8, old, newnick)) {
            // The World transaction may still have retired stale sibling aliases;
            // align every attachment without manufacturing a no-op NICK event.
            for (logical_ids.items) |logical_id| {
                if (self.connFor(logical_id)) |logical_conn| logical_conn.session.setNick(newnick) catch unreachable;
            }
            _ = self.commitPortableSessionMutation(id, conn);
            return;
        }

        self.retireLogicalMediaBeforeNickMutation(logical_ids.items);

        self.recordWhowas(registry_conn);
        for (logical_ids.items) |logical_id| {
            if (self.connFor(logical_id)) |logical_conn| logical_conn.session.setNick(newnick) catch unreachable;
        }
        const v2_authority_ready = self.commitPortableSessionMutation(id, conn);
        self.deliverLogicalNickEvent(nick_recipients.items, msg);
        var nick_body_buf: [64]u8 = undefined;
        const nick_body = std.fmt.bufPrint(&nick_body_buf, ":{s}", .{newnick}) catch newnick;
        var logical_channels = self.world.channels.iterator();
        while (logical_channels.next()) |entry| {
            var belongs = false;
            for (logical_ids.items) |logical_id| {
                if (entry.value_ptr.members.contains(worldIdFromClient(logical_id))) {
                    belongs = true;
                    break;
                }
            }
            if (belongs) self.recordHistoryEventSender(entry.key_ptr.*, old_prefix, "NICK", nick_body);
        }
        if (!conn.session_mesh_announce_pending)
            self.announceNickChange(old, newnick, membershipIdentityOf(conn), v2_authority_ready);
        const nick_hlc = self.nextMeshHlc();
        for (logical_ids.items) |logical_id| {
            if (self.connFor(logical_id)) |logical_conn| logical_conn.mesh_nick_hlc = nick_hlc;
        }
        if (std.ascii.eqlIgnoreCase(old, newnick)) {
            self.monitor.transitionOnlineSilent(old, newnick, true) catch {};
        } else {
            self.applyPreparedMonitorOccupancyTransition(
                &monitor_plan.?,
                old,
                newnick,
                old_remains_announced_online,
                new_was_announced_online,
            ) catch {};
        }
    }

    /// Re-evaluate nick protection after a connection (re)sets its nick: if the
    /// nick maps to a registered account this connection is NOT authenticated to,
    /// start the grace timer and warn; otherwise clear it. The sweep enforces.
    fn evaluateNickProtection(self: *LinuxServer, conn: *ConnState) void {
        conn.nick_claimed_at_ms = 0;
        if (self.config.nick_grace_ms <= 0) return;
        const svc = self.account_services orelse return;
        const nick = conn.session.displayName();
        if (nick.len == 0 or std.mem.eql(u8, nick, "*")) return;
        if (conn.session.account()) |acct| {
            if (std.ascii.eqlIgnoreCase(acct, nick)) return; // already owns it
        }
        _ = svc.accountInfo(nick) catch return; // not registered → nothing to protect
        conn.nick_claimed_at_ms = self.nowMs();
        var b: [default_reply_bytes]u8 = undefined;
        const secs: u64 = @intCast(@divFloor(self.config.nick_grace_ms, 1000));
        const note = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :Nick {s} is registered - IDENTIFY within {d}s or you'll be renamed to a Guest nick.\r\n", .{ self.serverName(), nick, nick, secs }) catch return;
        emitReplyLine(conn, note) catch {};
    }

    pub fn handleNickChange(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1 or parsed.paramSlice()[0].len == 0) {
            try queueNumeric(conn, .ERR_NONICKNAMEGIVEN, &.{}, "No nickname given");
            return;
        }
        const newnick = parsed.paramSlice()[0];
        if (!isValidNick(newnick)) {
            try queueNumeric(conn, .ERR_ERRONEUSNICKNAME, &.{newnick}, "Erroneous nickname");
            return;
        }
        if (self.registeredNickRequiresAuthentication(conn, newnick)) {
            try queueNumeric(conn, .ERR_ERRONEUSNICKNAME, &.{newnick}, "Nickname is registered; authenticate as this account before using it");
            return;
        }
        if (self.saccess.matchNick(newnick)) |entry| {
            try queueNumeric(conn, .ERR_ERRONEUSNICKNAME, &.{newnick}, serverAccessReason(entry, "Nickname blocked by SACCESS"));
            return;
        }
        if (self.nickReservationBlocks(conn, newnick)) |entry| {
            try queueNumeric(conn, .ERR_ERRONEUSNICKNAME, &.{newnick}, serverAccessReason(entry, "Nickname is reserved"));
            return;
        }
        // Snapshot the old nick into a stack buffer: displayName() borrows the
        // session's inline nick buffer, which setNick() overwrites below — so the
        // post-setNick MONITOR transition must read this copy, not the alias.
        var old_buf: [64]u8 = undefined;
        const old_slice = conn.session.displayName();
        @memcpy(old_buf[0..old_slice.len], old_slice);
        const old = old_buf[0..old_slice.len];
        if (std.mem.eql(u8, old, newnick)) return; // no-op
        const new_was_announced_online = self.monitor.isOnline(newnick);

        // Resolve the local attachments of this reusable logical-session token
        // before applying identity-wide policy. NICK mutates the logical
        // identity, so a sibling membership cannot be used to bypass +N.
        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        try self.collectExactLogicalClients(id, conn, &logical_ids);
        var logical_world_ids: std.ArrayList(world_model.ClientId) = .empty;
        defer logical_world_ids.deinit(self.allocator);
        try self.exactWorldIds(logical_ids.items, &logical_world_ids);
        const old_remains_announced_online = self.localRenderedNickOccupiedExcept(old, logical_ids.items);
        var monitor_plan: ?PreparedMonitorTransition = null;
        defer if (monitor_plan) |*plan| plan.deinit(self.allocator);
        if (std.ascii.eqlIgnoreCase(old, newnick)) {
            try self.monitor.reserveOnlineTransition(old, newnick, true, new_was_announced_online);
        } else {
            monitor_plan = try self.prepareMonitorOccupancyTransition(
                old,
                newnick,
                new_was_announced_online,
            );
        }

        // +N no-nick: a non-op member of any +N channel may not change nick.
        // Server opers bypass. Evaluate the complete exact-token membership
        // union rather than only the socket which issued NICK.
        if (!conn.session.isOper()) {
            var nit = self.world.channels.iterator();
            while (nit.next()) |entry| {
                if (!self.world.channelHasFlag(entry.key_ptr.*, .no_nick)) continue;
                var blocked = false;
                for (logical_world_ids.items) |logical_wid| {
                    if (!entry.value_ptr.members.contains(logical_wid)) continue;
                    const mm = self.world.memberModes(entry.key_ptr.*, logical_wid) orelse world_model.MemberModes.empty();
                    if (!mm.isOperator()) {
                        blocked = true;
                        break;
                    }
                }
                if (blocked) {
                    var nb: [default_reply_bytes]u8 = undefined;
                    const note = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :Cannot change nick while on {s} (+N)\r\n", .{ self.serverName(), old, entry.key_ptr.* }) catch return;
                    try emitReplyLine(conn, note);
                    return;
                }
            }
        }

        // Nick delay: refuse changing to a nick held against reuse (unless oper /
        // exempt / the held account's owner reclaiming). Checked before the world
        // register, which would otherwise succeed for a freed-but-held nick.
        if (self.nickDelayBlocks(conn, newnick)) {
            try queueNumeric(conn, .ERR_UNAVAILRESOURCE, &.{newnick}, "Nick is held (nick delay); try again shortly");
            return;
        }

        // Everything needed to render and route the identity-wide event must be
        // ready before the World nick transaction. A formatting/allocation
        // failure therefore cannot leave World resolving a nick that ConnState
        // has not adopted.
        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const old_prefix = try clientPrefix(conn, &prefix_buf);
        const msg = try formatMessage(&msg_buf, old_prefix, "NICK", &.{}, newnick);
        var nick_recipients: std.ArrayList(client_model.ClientId) = .empty;
        defer nick_recipients.deinit(self.allocator);
        try self.collectExactLogicalNickRecipients(logical_ids.items, &nick_recipients);

        // Reserve the new nick (frees the old mapping for this client).
        // Account-aware same-nick allowance (mirrors registerConnNick): if this
        // SASL-authed client changes to a nick already held by another LOCAL
        // connection on the SAME account, attach to it rather than 433 — the
        // existing holder keeps world ownership; this conn shares the nick. We
        // skip re-registering the world nick (which would collide) but still
        // rewrite the session nick and surface the local NICK line below so the
        // client sees its requested nick took effect.
        const registry_id = self.existingExactWorldOwner(logical_ids.items);
        const registry_wid = worldIdFromClient(registry_id);
        var shared_same_account = false;
        _ = self.world.replaceExactSessionNickOwner(newnick, registry_wid, logical_world_ids.items) catch |err| switch (err) {
            error.NickInUse => {
                if (self.world.findNick(newnick)) |foreign_owner| {
                    if (conn.session.account()) |acct| {
                        if (self.nickHeldBySameAccount(newnick, acct, registry_wid)) {
                            _ = self.world.relinquishExactSessionNickOwners(
                                newnick,
                                foreign_owner,
                                logical_world_ids.items,
                            ) catch |relinquish_err| switch (relinquish_err) {
                                error.NickInUse, error.InvalidOwnerSet => {
                                    try queueNumeric(conn, .ERR_NICKNAMEINUSE, &.{newnick}, "Nickname is already in use");
                                    return;
                                },
                                else => return relinquish_err,
                            };
                            shared_same_account = true;
                        }
                    }
                }
                if (!shared_same_account) {
                    try queueNumeric(conn, .ERR_NICKNAMEINUSE, &.{newnick}, "Nickname is already in use");
                    return;
                }
            },
            else => return err,
        };
        // World has reserved the new identity, so the rename can no longer be
        // rejected as a collision. Retire every old-nick physical publisher
        // before mutating ConnState or delivering NICK; fresh media JOIN and
        // E2EE-HANDSHAKE are required under the new nick.
        self.retireLogicalMediaBeforeNickMutation(logical_ids.items);
        // The nick is now this client's: clear any hold an oper / exempt class
        // bypassed so a later sweep cannot evict a stale entry for a live nick.
        if (self.config.nick_delay_ms != 0 and !shared_same_account) self.nick_delay.release(newnick);

        // Record the old identity, then rewrite the session nick.
        self.recordWhowas(conn);
        for (logical_ids.items) |logical_id| {
            const logical_conn = self.connFor(logical_id) orelse continue;
            logical_conn.session.setNick(newnick) catch unreachable; // validated above, <= NICKLEN/storage
        }
        // Publish the exact-token snapshot before any negotiated-v2
        // compatibility NICKCHANGE. If publication cannot complete, the dirty
        // token retries later and receiver-side Store projection surfaces the
        // rename; legacy links may still receive the immediate sidecar.
        const v2_authority_ready = self.commitPortableSessionMutation(id, conn);

        // Deliver to self + every common-channel member (dedup, except self once).
        self.deliverLogicalNickEvent(nick_recipients.items, msg);

        // draft/event-playback: record the rename as a NICK event into each channel
        // the user is in. Body is `:newnick` so it replays exactly like the live
        // broadcast (`:oldnick NICK :newnick`), with the OLD prefix.
        var nick_body_buf: [64]u8 = undefined;
        const nick_body = std.fmt.bufPrint(&nick_body_buf, ":{s}", .{newnick}) catch newnick;
        var logical_channels = self.world.channels.iterator();
        while (logical_channels.next()) |entry| {
            var belongs = false;
            for (logical_ids.items) |logical_id| {
                if (entry.value_ptr.members.contains(worldIdFromClient(logical_id))) {
                    belongs = true;
                    break;
                }
            }
            if (belongs) self.recordHistoryEventSender(entry.key_ptr.*, old_prefix, "NICK", nick_body);
        }

        // Propagate the nick change across the mesh so remote members rename the
        // user and see a live NICK line (identity is nick-independent).
        if (!conn.session_mesh_announce_pending)
            self.announceNickChange(old, newnick, membershipIdentityOf(conn), v2_authority_ready);
        // Re-stamp the mesh-claim HLC: changing nick is a fresh claim assertion, so
        // a same-account ghost on another node loses to this newer claim.
        const nick_hlc = self.nextMeshHlc();
        for (logical_ids.items) |logical_id| {
            if (self.connFor(logical_id)) |logical_conn| logical_conn.mesh_nick_hlc = nick_hlc;
        }

        // MONITOR follows physical occupancy, not one token's rename. A
        // distinct-token same-nick attachment keeps the old identity online;
        // an already-online target must not receive a duplicate 730.
        if (std.ascii.eqlIgnoreCase(old, newnick)) {
            self.monitor.transitionOnlineSilent(old, newnick, true) catch {};
        } else {
            self.applyPreparedMonitorOccupancyTransition(
                &monitor_plan.?,
                old,
                newnick,
                old_remains_announced_online,
                new_was_announced_online,
            ) catch {};
        }

        // OBSERVE: push a nick-change record (detail = "-> <new>"); the subject's
        // session now carries the new nick, so report the new identity + change.
        var dbuf: [80]u8 = undefined;
        const detail = std.fmt.bufPrint(&dbuf, "<- {s}", .{old}) catch "";
        self.notifyObservers(.nick, observeSubject(conn, detail));
        try self.publishUserNickEvent(old_prefix, newnick);

        // Nick protection: a newly-taken registered nick (while unauthenticated)
        // starts the grace timer; the sweep enforces a Guest rename on expiry.
        for (logical_ids.items) |logical_id| {
            if (self.connFor(logical_id)) |logical_conn| self.evaluateNickProtection(logical_conn);
        }
    }

    fn localRenderedNickOccupiedExcept(
        self: *LinuxServer,
        nick: []const u8,
        excluded: []const client_model.ClientId,
    ) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, slot_index| {
                if (!slot.occupied) continue;
                const candidate_id = slotClientId(reactor, slot_index, slot.gen);
                var skip = false;
                for (excluded) |excluded_id| {
                    if (candidate_id.eql(excluded_id)) {
                        skip = true;
                        break;
                    }
                }
                if (skip) continue;
                const candidate = &slot.value;
                if (candidate.closing or candidate.s2s != null or candidate.s2s_secured != null or
                    !candidate.session.registered()) continue;
                const display = candidate.session.displayName();
                if (std.mem.eql(u8, display, "*")) continue;
                if (std.ascii.eqlIgnoreCase(display, nick)) return true;
            }
        }
        return false;
    }

    /// MONITOR notify for a nick change: old offline, new online, WITHOUT
    /// dropping the client's own subscriptions (unlike a disconnect).
    fn monitorTransition(self: *LinuxServer, old: []const u8, new: []const u8) !void {
        if (std.ascii.eqlIgnoreCase(old, new)) {
            try self.monitor.transitionOnlineSilent(old, new, true);
            return;
        }
        try self.monitorOccupancyTransition(old, new, false, false);
    }

    fn monitorOccupancyTransition(
        self: *LinuxServer,
        old: []const u8,
        new: []const u8,
        old_remains_online: bool,
        new_was_announced_online: bool,
    ) !void {
        var plan = try self.prepareMonitorOccupancyTransition(old, new, new_was_announced_online);
        defer plan.deinit(self.allocator);
        try self.applyPreparedMonitorOccupancyTransition(
            &plan,
            old,
            new,
            old_remains_online,
            new_was_announced_online,
        );
    }

    fn prepareMonitorOccupancyTransition(
        self: *LinuxServer,
        old: []const u8,
        new: []const u8,
        new_was_announced_online: bool,
    ) !PreparedMonitorTransition {
        // Prepare for the conservative case where old really goes offline. A
        // World rename can reveal another old-nick owner and suppress those
        // replies later; excess capacity is harmless, missing capacity is not.
        const old_watchers = self.monitor.watcherCount(old);
        const new_watchers = if (new_was_announced_online) 0 else self.monitor.watcherCount(new);
        const reply_count = std.math.add(usize, old_watchers, new_watchers) catch return error.OutOfMemory;
        const exact_storage_len = std.math.add(
            usize,
            std.math.mul(usize, old_watchers, old.len) catch return error.OutOfMemory,
            std.math.mul(usize, new_watchers, new.len) catch return error.OutOfMemory,
        ) catch return error.OutOfMemory;
        var plan = PreparedMonitorTransition{
            .reply_count = reply_count,
            .storage_len = exact_storage_len,
        };
        errdefer plan.deinit(self.allocator);
        if (reply_count > plan.inline_replies.len)
            plan.allocated_replies = try self.allocator.alloc(monitor.MonitorReply, reply_count);
        if (exact_storage_len > plan.inline_storage.len)
            plan.allocated_storage = try self.allocator.alloc(u8, exact_storage_len);
        // Never rely on removing old to supply the new hash slot: the eventual
        // occupancy decision is allowed to preserve old after World reveals a
        // shadowed owner.
        try self.monitor.reserveOnlineTransition(old, new, true, new_was_announced_online);
        return plan;
    }

    fn applyPreparedMonitorOccupancyTransition(
        self: *LinuxServer,
        plan: *PreparedMonitorTransition,
        old: []const u8,
        new: []const u8,
        old_remains_online: bool,
        new_was_announced_online: bool,
    ) !void {
        var sink = monitor.MonitorReplySink{ .replies = plan.replies(), .storage = plan.storage() };
        if (!old_remains_online) try self.monitor.setOffline(old, &sink);
        if (!new_was_announced_online) try self.monitor.setOnline(new, &sink);
        try self.flushMonitorReplies(&sink);
    }

    /// AWAY [:message] — RFC 1459 / IRCv3 away-notify. A parameter sets the away
    /// message (RPL_NOWAWAY 306); a bare AWAY clears it (RPL_UNAWAY 305). When
    /// the away-notify cap is negotiated by peers, an `AWAY` state change is
    /// announced to all common-channel members.
    pub fn handleAway(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        // Cap the away reason at the configured AWAYLEN (advertised in ISUPPORT),
        // truncated on a UTF-8 codepoint boundary so it stays valid under UTF8ONLY.
        const reason: ?[]const u8 = if (parsed.param_count >= 1 and parsed.paramSlice()[0].len != 0)
            utf8TruncateBytes(parsed.paramSlice()[0], self.config.awaylen)
        else
            null;

        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        try self.collectAttachedExactTokenClients(id, conn, &logical_ids);

        if (reason) |text| {
            for (logical_ids.items) |logical_id| {
                const logical_conn = self.connFor(logical_id) orelse continue;
                logical_conn.session.setAway(text);
            }
        } else {
            for (logical_ids.items) |logical_id| {
                const logical_conn = self.connFor(logical_id) orelse continue;
                logical_conn.session.clearAway();
            }
        }

        _ = self.commitPortableSessionMutation(id, conn);
        if (reason != null) {
            queueNumeric(conn, .RPL_NOWAWAY, &.{}, "You have been marked as being away") catch {};
        } else {
            queueNumeric(conn, .RPL_UNAWAY, &.{}, "You are no longer marked as being away") catch {};
        }

        // away-notify: announce to common-channel members who negotiated it.
        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const prefix = try clientPrefix(conn, &prefix_buf);
        const msg = try formatMessage(&msg_buf, prefix, "AWAY", &.{}, reason);
        self.notifyCommonChannels(id, msg, .away_notify, id, conn.session.displayName()) catch {};
        for (logical_ids.items[1..]) |logical_id| {
            const logical_conn = self.connFor(logical_id) orelse continue;
            if (!logical_conn.session.hasCap(.away_notify)) continue;
            if (self.sharesAnyChannelWith(worldIdFromClient(id), worldIdFromClient(logical_id))) continue;
            self.deliver(logical_id, msg) catch {};
        }

        // #33: feed the ACTIVITY stream a presence transition.
        self.pushPresenceActivity(id, conn, if (reason != null) .away else .active);
    }

    /// SETNAME :<realname> — IRCv3 setname. Updates the GECOS and echoes the
    /// change to the client and to setname-capable common-channel members.
    pub fn handleSetname(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1 or parsed.paramSlice()[0].len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"SETNAME"}, "Not enough parameters");
            return;
        }
        const newname = parsed.paramSlice()[0];
        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        try self.collectAttachedExactTokenClients(id, conn, &logical_ids);
        conn.session.setRealname(newname) catch {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"SETNAME"}, "Realname too long");
            return;
        };
        for (logical_ids.items[1..]) |logical_id| {
            const logical_conn = self.connFor(logical_id) orelse continue;
            logical_conn.session.setRealname(newname) catch unreachable;
        }

        _ = self.commitPortableSessionMutation(id, conn);

        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const prefix = try clientPrefix(conn, &prefix_buf);
        const msg = try formatMessage(&msg_buf, prefix, "SETNAME", &.{}, newname);
        if (conn.session.hasCap(.setname)) self.deliver(id, msg) catch {}; // echo to self
        self.notifyCommonChannels(id, msg, .setname, id, conn.session.displayName()) catch {};
        for (logical_ids.items[1..]) |logical_id| {
            const logical_conn = self.connFor(logical_id) orelse continue;
            if (!logical_conn.session.hasCap(.setname)) continue;
            if (self.sharesAnyChannelWith(worldIdFromClient(id), worldIdFromClient(logical_id))) continue;
            self.deliver(logical_id, msg) catch {};
        }
    }

    /// OPER <name> <password> — elevate to IRC operator. Matches against the
    /// single configured oper block; success sets the session oper flag, emits
    /// RPL_YOUREOPER (381) and the +o umode reflection.
    pub fn handleOper(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleOper(self, conn, parsed);
    }

    /// SUMMON <nick> <channel> — force the target user into <channel>. Classic
    /// host-paging SUMMON (RFC 1459 §4.5) has no meaning on a modern network
    /// daemon, so Onyx Server repurposes it as an operator force-join (the registry
    /// gates it `.access = .oper`). Reuses the same target resolution + join path
    /// as `FORCEJOIN`, then replies `RPL_SUMMONING` (342) to the requester.
    fn channelHoldLimit(self: *LinuxServer, channel: []const u8) u16 {
        const entity = ircx_prop_store.Entity{ .kind = .channel, .id = channel };
        const ev = self.props.getProp(entity, "HOLD") catch return 0;
        const n = std.fmt.parseInt(u16, ev.value, 10) catch return 0;
        if (n == 0) return 0;
        return @min(n, first_hold.max_per_member);
    }

    /// True when this PRIVMSG is stored for review instead of delivered.
    /// A missing or zero HOLD prop leaves delivery unchanged.
    fn captureFirstHold(self: *LinuxServer, conn: *ConnState, channel: []const u8, text: []const u8) bool {
        if (conn.session.isOper()) return false;
        const limit = self.channelHoldLimit(channel);
        if (limit == 0) return false;
        const nick = conn.session.displayName();
        if (self.first_holds.seen(channel, nick) >= limit) return false;
        self.first_holds.hold(channel, nick, text, limit) catch {
            self.noticeTo(conn, "HOLD could not store") catch {};
            return true;
        };
        self.noticeTo(conn, "HOLD stored") catch {};
        return true;
    }

    pub fn handleHold(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.isOper()) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied");
            return;
        }
        const p = parsed.paramSlice();
        if (p.len < 3) {
            try self.noticeTo(conn, "Usage: HOLD RELEASE|DROP <#chan> <nick>");
            return;
        }
        const channel = p[1];
        const nick = p[2];
        if (std.ascii.eqlIgnoreCase(p[0], "DROP")) {
            const n = self.first_holds.drop(channel, nick);
            var buf: [64]u8 = undefined;
            const note = std.fmt.bufPrint(&buf, "HOLD dropped {d}", .{n}) catch "HOLD dropped";
            try self.noticeTo(conn, note);
            return;
        }
        if (!std.ascii.eqlIgnoreCase(p[0], "RELEASE")) {
            try self.noticeTo(conn, "Usage: HOLD RELEASE|DROP <#chan> <nick>");
            return;
        }
        var bodies: [first_hold.max_per_member][first_hold.max_body]u8 = undefined;
        var lens: [first_hold.max_per_member]usize = undefined;
        const n = self.first_holds.copyOut(channel, nick, &bodies, &lens);
        var i: usize = 0;
        while (i < n) : (i += 1) {
            const text = bodies[i][0..lens[i]];
            var prefix_buf: [96]u8 = undefined;
            const prefix = std.fmt.bufPrint(&prefix_buf, "{s}!{s}@held", .{ nick, nick }) catch nick;
            var msg_buf: [first_hold.max_body + 160]u8 = undefined;
            const msg = formatMessage(&msg_buf, prefix, "PRIVMSG", &.{channel}, text) catch continue;
            self.broadcastChannel(channel, msg, null) catch {};
            var id_buf: [16]u8 = undefined;
            const msgid = std.fmt.bufPrint(&id_buf, "hold{d}", .{i}) catch "hold";
            self.recordHistoryRelayAt(channel, prefix, msgid, "PRIVMSG", text, null, self.meshWallMs());
        }
        var buf: [64]u8 = undefined;
        const note = std.fmt.bufPrint(&buf, "HOLD released {d}", .{n}) catch "HOLD released";
        try self.noticeTo(conn, note);
    }

    fn botHasSpeakGrant(self: *LinuxServer, account: []const u8) bool {
        if (!self.accountIsGatedBot(account)) return false;
        const now = self.grantNowU64();
        var live: [bot_grant_snapshot.max_grants]bot_grant_snapshot.GrantView = undefined;
        const n = self.bot_grants.copyLive(now, &live);
        for (live[0..n]) |slot| {
            if (slot.kind == .speak and std.ascii.eqlIgnoreCase(slot.account, account)) return true;
        }
        return false;
    }

    /// `BOTCMD ADD <name> <argc> :<help>` registers one command for the caller's
    /// account. `BOTCMD RUN <name> [args...]` accepts it only when that account
    /// still holds a speak grant. The grant is not an oper bit, and this
    /// command does not create buttons.
    pub fn handleBotCmd(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const account = conn.session.account() orelse {
            try self.noticeTo(conn, "BOTCMD denied");
            return;
        };
        if (!self.botHasSpeakGrant(account)) {
            try self.noticeTo(conn, "BOTCMD denied");
            return;
        }
        const p = parsed.paramSlice();
        if (p.len < 1) {
            try self.noticeTo(conn, "Usage: BOTCMD ADD <name> <argc> :<help> | RUN <name> [args] | LIST");
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "LIST")) {
            var views: [slash_cmd.max_cmds]slash_cmd.View = undefined;
            const n = self.slash_cmds.list(account, &views);
            if (n == 0) {
                try self.noticeTo(conn, "BOTCMD none");
                return;
            }
            var i: usize = 0;
            while (i < n) : (i += 1) {
                var buf: [160]u8 = undefined;
                const note = std.fmt.bufPrint(&buf, "BOTCMD {s} args={d} {s}", .{ views[i].name, views[i].argc, views[i].help }) catch "BOTCMD";
                try self.noticeTo(conn, note);
            }
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "ADD")) {
            if (p.len < 4) {
                try self.noticeTo(conn, "Usage: BOTCMD ADD <name> <argc> :<help>");
                return;
            }
            const argc = std.fmt.parseInt(u8, p[2], 10) catch {
                try self.noticeTo(conn, "BOTCMD rejected");
                return;
            };
            self.slash_cmds.add(account, p[1], p[3], argc) catch {
                try self.noticeTo(conn, "BOTCMD rejected");
                return;
            };
            try self.noticeTo(conn, "BOTCMD added");
            return;
        }
        if (!std.ascii.eqlIgnoreCase(p[0], "RUN")) {
            try self.noticeTo(conn, "Usage: BOTCMD ADD <name> <argc> :<help> | RUN <name> [args] | LIST");
            return;
        }
        if (p.len < 2) {
            try self.noticeTo(conn, "Usage: BOTCMD RUN <name> [args]");
            return;
        }
        const cmd = self.slash_cmds.find(account, p[1]) orelse {
            try self.noticeTo(conn, "BOTCMD unknown");
            return;
        };
        if (p.len - 2 != @as(usize, cmd.argc)) {
            try self.noticeTo(conn, "BOTCMD args");
            return;
        }
        var buf: [240]u8 = undefined;
        var note: []const u8 = undefined;
        if (cmd.argc == 0) {
            note = std.fmt.bufPrint(&buf, "BOTCMD ok {s}", .{cmd.name}) catch "BOTCMD ok";
        } else {
            note = std.fmt.bufPrint(&buf, "BOTCMD ok {s} {s}", .{ cmd.name, p[2] }) catch "BOTCMD ok";
        }
        try self.noticeTo(conn, note);
    }

    pub fn handleQuarantine(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.isOper()) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied");
            return;
        }
        const p = parsed.paramSlice();
        if (p.len < 3 or !world_model.isChannelName(p[1]) or p[2].len == 0) {
            try self.noticeTo(conn, "Usage: QUARANTINE <nick> <#chan> :<reason>");
            return;
        }
        const nick = p[0];
        const channel = p[1];
        const reason = p[2];
        const target = self.resolveTargetConn(conn, nick) orelse return;
        const wid = worldIdFromClient(target.id);
        const listed = self.world.channelCount();
        const names = try self.allocator.alloc([]const u8, listed);
        defer self.allocator.free(names);
        const n = self.world.channelsOf(wid, names);
        var copies: std.ArrayList([]u8) = .empty;
        defer {
            for (copies.items) |item| self.allocator.free(item);
            copies.deinit(self.allocator);
        }
        var i: usize = 0;
        while (i < n) : (i += 1) {
            if (std.ascii.eqlIgnoreCase(names[i], channel)) continue;
            try copies.append(self.allocator, try self.allocator.dupe(u8, names[i]));
        }
        for (copies.items) |name| self.partOne(target.id, target.conn, name, reason) catch {};
        try self.joinOne(target.id, target.conn, channel, null, 0);
        var reason_buf: [180]u8 = undefined;
        const audit = std.fmt.bufPrint(&reason_buf, "quarantine {s}: {s}", .{ channel, reason }) catch "quarantine";
        _ = self.recordOperAudit(conn.session.displayName(), .other, nick, audit);
        try self.noticeTo(conn, "QUARANTINE moved");
    }

    pub fn handleSummon(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"SUMMON"}, "Not enough parameters (SUMMON <nick> <channel>)");
            return;
        }
        const target_nick = parsed.paramSlice()[0];
        const channel = parsed.paramSlice()[1];
        // resolveTargetConn emits ERR_NOSUCHNICK on a miss; joinOne performs the
        // actual join + membership broadcast + channel-name validation (same path
        // FORCEJOIN uses).
        const t = self.resolveTargetConn(conn, target_nick) orelse return;
        try self.joinOne(t.id, t.conn, channel, null, 0);
        try queueNumeric(conn, .RPL_SUMMONING, &.{ target_nick, channel }, "Summoned user to channel");
    }

    /// SASL-only operator elevation: if `conn` is authenticated as an account with
    /// an `[oper]` registry binding, grant operator status (RPL_YOUREOPER + the +o
    /// reflection) and subscribe it to the Event Spine. Idempotent and silent when
    /// the account is not an operator. Called after a successful SASL login.
    /// Lifetime of a minted cross-mesh operator grant.
    const oper_grant_ttl_ms: u64 = 24 * 60 * 60 * 1000;

    /// Cadence of the periodic grant refresh (`onTimerTick`, reactor 0):
    /// re-mint live opered sessions' grants every quarter-TTL so a grant is
    /// always renewed with ≥3/4 of its lifetime remaining — a peer's copy never
    /// lapses while the oper stays logged in, even across long-lived links.
    const oper_grant_refresh_interval_ms: i64 = @intCast(oper_grant_ttl_ms / 4);

    /// A zero marker means the periodic refresh has never run and is due even
    /// on a freshly booted host whose monotonic uptime is shorter than the
    /// normal refresh interval. Treat clock regression as not due; the next
    /// monotonic tick will recover without an overflowing subtraction.
    fn operGrantRefreshDue(last_refresh_ms: i64, now_ms: i64) bool {
        if (last_refresh_ms == 0) return true;
        return now_ms >= last_refresh_ms and
            now_ms - last_refresh_ms >= oper_grant_refresh_interval_ms;
    }

    /// Derive this node's Ed25519 signing keypair (for minting oper grants) from
    /// the sovereign node identity seed. Null when no node identity is configured
    /// (cross-mesh oper grants then unsigned/disabled).
    fn meshSignKey(self: *LinuxServer) ?std.crypto.sign.Ed25519.KeyPair {
        const ident = self.config.node_identity orelse return null;
        const sk = ident.sign_kp.secret_key.expose();
        if (sk.len < 32) return null;
        var seed: [32]u8 = undefined;
        @memcpy(&seed, sk[0..32]);
        return std.crypto.sign.Ed25519.KeyPair.generateDeterministic(seed) catch null;
    }

    /// Ingest a signed cross-mesh operator grant received from a peer node,
    /// verifying it against the peer's Ed25519 public key and merging it into the
    /// local grant registry (newer incarnation wins). Returns true if accepted.
    /// The S2S layer calls this when a grant frame arrives from a trusted peer.
    pub fn applyMeshGrant(self: *LinuxServer, bytes: []const u8, peer_pubkey: [32]u8) bool {
        const pk = std.crypto.sign.Ed25519.PublicKey.fromBytes(peer_pubkey) catch return false;
        const now: u64 = self.grantNowU64();
        const fields = oper_cred_share.verify(pk, bytes, now) catch return false;
        const prev_override = self.grantHasOverride(fields.account, now);
        const accepted = self.oper_grants.upsert(fields) != .stale_ignored;
        if (accepted) {
            self.logMeshEvent(.oper_grant_in, fields.account, fields.issuer_node);
            // Display-only: project `*` / +Y for remote roster nicks on an
            // override edge only. Privilege stays configured-local.
            self.projectRemoteOperPrefixEdge(
                fields.account,
                prev_override,
                fields.privilege_bits != 0 and
                    oper_mod.OperPrivileges.fromBits(fields.privilege_bits).has(.oper_override),
            );
        }
        return accepted;
    }

    fn grantHasOverride(self: *const LinuxServer, account: []const u8, now: u64) bool {
        const prev = self.oper_grants.lookup(account, now) orelse return false;
        return oper_mod.OperPrivileges.fromBits(prev.privilege_bits).has(.oper_override);
    }

    /// Announce remote `*` / +Y only when the override-display bit flips.
    /// Same-privilege anti-entropy remints stay silent.
    fn projectRemoteOperPrefixEdge(
        self: *LinuxServer,
        account: []const u8,
        prev_override: bool,
        now_override: bool,
    ) void {
        if (now_override and !prev_override) {
            self.announceRemoteOperPrefixForAccount(account, true);
        } else if (!now_override and prev_override) {
            self.announceRemoteOperPrefixForAccount(account, false);
        }
    }

    /// Mint + store a signed mesh oper grant for display projection across peers.
    /// Privilege (KICK/DATA/session authority) stays configured-local; the grant
    /// drives remote WHOIS 313 / NAMES `*` / `MODE +Y` only. Best-effort: silently
    /// skips the wire broadcast without a node key, but still records locally and
    /// projects the display edge for remotes already on this node's roster.
    pub fn mintOperGrant(self: *LinuxServer, account: []const u8, privileges: oper_mod.OperPrivileges, class_name: []const u8, title: []const u8) void {
        const now: u64 = self.grantNowU64();
        const prev_override = self.grantHasOverride(account, now);
        // Strictly-increasing incarnation so a later GRANT/REVOKE always wins,
        // even when issued within the same millisecond.
        self.grant_incarnation = @max(now, self.grant_incarnation + 1);
        const fields = oper_cred_share.GrantFields{
            .account = account,
            .privilege_bits = privileges.toBits(),
            .class = class_name,
            .title = title,
            .issuer_node = protocol_inventory.currentServerName(),
            .incarnation = self.grant_incarnation,
            .issued_ms = now,
            .expiry_ms = now + oper_grant_ttl_ms,
        };
        // Record locally first so a single node (no [node] key) still grants.
        _ = self.oper_grants.upsert(fields);
        self.projectRemoteOperPrefixEdge(account, prev_override, privileges.has(.oper_override));
        // Sign once and broadcast to every authenticated peer so they recognize
        // this grant (best-effort; no node key => local-only, no propagation).
        const kp = self.meshSignKey() orelse return;
        var buf: [oper_cred_share.max_grant_len]u8 = undefined;
        const n = oper_cred_share.sign(kp, fields, &buf) catch return;
        self.broadcastOperGrant(buf[0..n]);
        self.logMeshEvent(.oper_grant_out, account, self.serverName());
    }

    /// Broadcast a signed oper grant to every established **secured** peer. The
    /// plaintext S2S path is deliberately skipped: a grant only carries authority
    /// over a link whose peer identity the Mooring handshake authenticated.
    fn broadcastOperGrant(self: *LinuxServer, signed: []const u8) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                link.sendOperGrant(signed) catch continue;
                _ = self.flushSecuredS2sOutboundTo(pid, link);
            }
        }
    }

    /// Broadcast a `mesh`-scope WARD (add or remove) to every established secured
    /// peer so already-running nodes enforce (or forget) the network ban live.
    /// Like `broadcastOperGrant`, the plaintext S2S path is skipped: a network ban
    /// is operator authority and only rides a Mooring-authenticated link. The
    /// `ward` strings are encoded into `wire` once and signed per-peer.
    fn broadcastMeshWard(self: *LinuxServer, ward: warden.Ward, op: warden.WireOp) void {
        var wire_buf: [warden.max_wire_len]u8 = undefined;
        const wire = warden.encodeWire(.{
            .op = op,
            .match = ward.match,
            .pattern = ward.pattern,
            .action = ward.action,
            .reason = ward.reason,
            .set_by = ward.set_by,
            .created_ms = ward.created_ms,
            .expires_ms = ward.expires_ms,
        }, &wire_buf) catch return;
        var filter_buf: [warden.mesh_ban_filter_wire_len]u8 = undefined;
        const filter_wire = self.meshBanFilterWire(&filter_buf);
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (filter_wire) |fw| link.sendWard(fw) catch {};
                link.sendWard(wire) catch continue;
                _ = self.flushSecuredS2sOutboundTo(pid, link);
            }
        }
    }

    /// Decode + apply this peer's inbound WARD frames into the local Warden store:
    /// an `add` upserts the mesh ban so this node enforces it live; a `remove`
    /// drops it. The frame was already signature-verified by the substrate link
    /// (a network ban is operator authority). A received mesh ward is NOT re-
    /// broadcast here — each setting node fans it to all secured peers directly,
    /// and re-fanning would loop in a cyclic mesh. Malformed payloads are skipped.
    fn drainWards(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const payloads = link.takeWards() catch return;
        defer {
            for (payloads) |p| self.allocator.free(p);
            self.allocator.free(payloads);
        }
        // Coalesce the live sweep: a peer may burst several ward adds in one frame,
        // and each reap is an O(clients) walk under the coarse world lock — do it
        // ONCE after the whole batch applies rather than per add.
        var need_reap = false;
        for (payloads) |p| {
            if (self.ingestMeshWardPayload(p)) need_reap = true;
        }
        if (need_reap) self.reapWardMatches();
    }

    /// Apply one inbound mesh-ban payload. A filter frame replaces the compact
    /// hint and never installs a ward. An add/remove updates the registry.
    /// Returns true when a successful add should sweep live clients.
    fn ingestMeshWardPayload(self: *LinuxServer, payload: []const u8) bool {
        if (payload.len != 0 and payload[0] == @intFromEnum(warden.WireOp.filter)) {
            const decoded = warden.decodeMeshBanFilter(self.allocator, payload) catch {
                self.traceLog(.warn, .s2s, "dropped malformed mesh-ban filter from peer");
                return false;
            };
            if (self.mesh_ban_filter) |*old| old.deinit();
            self.mesh_ban_filter = decoded;
            return false;
        }
        const wire = warden.decodeWire(payload) catch {
            // A malformed mesh-WARD frame from a (signature-)trusted peer is a
            // security-relevant drop: the network ban it carried will not
            // converge here. Never silent — leave an oper-visible trace.
            self.traceLog(.warn, .s2s, "dropped malformed mesh-WARD frame from peer");
            return false;
        };
        return self.applyRemoteWard(wire);
    }

    /// Apply one decoded mesh-WARD record to the local registry. Returns true when
    /// a successful `add` warrants a live sweep (`reapWardMatches`) so the caller
    /// can coalesce the sweep across a batch; a `remove` or a failed add returns
    /// false (nothing new to enforce).
    fn applyRemoteWard(self: *LinuxServer, wire: warden.WireWard) bool {
        switch (wire.op) {
            .filter => return false,
            .remove => {
                _ = self.warden.remove(wire.match, wire.pattern);
                return false;
            },
            .add => {
                // Force mesh scope locally: the entry only reached us because the
                // setting node propagated a mesh ward.
                self.warden.add(.{
                    .match = wire.match,
                    .pattern = wire.pattern,
                    .scope = .mesh,
                    .action = wire.action,
                    .reason = wire.reason,
                    .set_by = wire.set_by,
                    .created_ms = wire.created_ms,
                    .expires_ms = wire.expires_ms,
                }) catch |err| {
                    // Apply failure (OOM / TooManyWards / oversized field) means a
                    // propagated network ban silently fails to install — surface it
                    // rather than diverge from the mesh without a trace.
                    var buf: [256]u8 = undefined;
                    const note = std.fmt.bufPrint(
                        &buf,
                        "failed to apply mesh-WARD {s} {s}: {s}",
                        .{ wire.match.token(), wire.pattern, @errorName(err) },
                    ) catch "failed to apply mesh-WARD from peer";
                    self.traceLog(.warn, .s2s, note);
                    return false;
                };
                // A freshly-installed network ban must bite already-connected
                // clients here immediately (not one reconnect later). Signal the
                // caller to sweep; the sweep is coalesced across the drain batch.
                return true;
            },
        }
    }

    fn elevateOperFromAccount(self: *LinuxServer, conn: *ConnState) !void {
        try self.elevateOperFromAccountWithPrefix(conn, true);
    }

    fn elevateOperFromAccountWithPrefix(
        self: *LinuxServer,
        conn: *ConnState,
        announce_prefix: bool,
    ) !void {
        try self.elevateOperFromAccountTo(idFromToken(conn.token), conn, announce_prefix);
    }

    fn elevateOperFromAccountTo(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        announce_prefix: bool,
    ) !void {
        // Account authentication is an authority replacement, never an
        // additive privilege path.  Revoke the prior projection before looking
        // up the newly-authenticated account so a same-account refresh, an
        // account switch, or a missing/revoked binding cannot retain or union
        // privileges from the previous grant.  ClientSession.loginAs() also
        // clears at the identity boundary; keeping this guard here makes every
        // direct reconciliation caller fail closed as well.
        _ = self.clearOperAuthorityTransition(id, conn, announce_prefix, "operator authority recomputed");
        const account = conn.session.account() orelse return;

        const application_now = self.grantNowU64();
        const configured_binding = if (self.oper_registry) |*registry|
            oper_session_provenance.configuredLocalBinding(registry, account)
        else
            null;
        const presubscribe_bits = if (configured_binding) |*binding| binding.presubscribeBits() else 0;

        // Step 5 deliberately consumes only the sealed live-config capability.
        // The durable Services image can already return a typed active OCG2
        // record, so threading it here would activate OCG2 before the frozen
        // transactional Step 6 boundary. Keep that source explicitly disabled.
        const outcome = conn.session.reconcileOperAuthority(configured_binding, .disabled, application_now);
        if (outcome != .replaced or !conn.session.isOper()) return;
        const privileges = conn.session.oper_priv;
        const class_name = conn.session.operClass();
        const title = conn.session.operTitle();

        if (!conn.session.isOper()) return;
        self.applyOperAutoOverride(conn); // [oper] auto_override → +j for oper_override holders
        // Opers are always in IRCX mode: SASL oper elevation auto-enables it, so
        // the IRCX command surface + PROP-change notifications "just work" without
        // an explicit IRCX command or a separate capability.
        conn.ircx = true;
        // Locally-authorized opers mint a signed grant so peers recognize them,
        // and persist it so the operator is restored after a full restart (a USR2
        // keeps the session's oper status; a cold restart does not) without waiting
        // for a peer to re-propagate it.
        self.mintOperGrant(account, privileges, class_name, title);
        self.persistGrants();
        self.traceLog(.notice, .oper, "operator elevated via SASL account");
        // Wallops, oper notices, kills, etc. arrive as typed Event-Spine events,
        // but ONLY for the categories this oper presubscribed to (per the
        // `[[opers]] presubscribe` config). With none configured the oper gets
        // nothing until it opts in via `EVENT ADD <category>`.
        conn.session.setEventMask(event_spine.CategoryMask{ .bits = presubscribe_bits });
        try self.deliverNumeric(id, .RPL_YOUREOPER, &.{}, "You are now an IRC operator");
        // USER OPER event: an account elevated to operator. A network-significant
        // privilege transition — published so USER subscribers and oper-action
        // opers see who gained operator status (and under what title/class).
        self.publishUserEvent(conn, "OPER", if (title.len != 0) title else class_name) catch {};
        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const prefix = try clientPrefix(conn, &prefix_buf);
        const nick = conn.session.displayName();
        // Announce the operator modes just granted: +o plus every server-managed
        // umode setOperGrant applied (e.g. +a for a server_admin). Letters come
        // from the umode catalog, not hardcoded, so the announcement always
        // matches what the session actually holds.
        var modes_buf: [usermode.MAX_MODE_CHANGES + 2]u8 = undefined;
        var ml: usize = 0;
        modes_buf[ml] = '+';
        ml += 1;
        modes_buf[ml] = 'o'; // the IRC operator mode (derived from is_oper)
        ml += 1;
        for (usermode.default_specs) |spec| {
            if (spec.policy == .server_managed and conn.session.hasUmode(spec.mode)) {
                modes_buf[ml] = spec.letter;
                ml += 1;
            }
        }
        // +j override is client-writable (skipped by the server-managed loop), so
        // announce it explicitly when auto_override turned it on at elevation.
        if (conn.session.hasUmode(.override)) {
            modes_buf[ml] = 'j';
            ml += 1;
        }
        const msg = try formatMessage(&msg_buf, prefix, "MODE", &.{ nick, modes_buf[0..ml] }, null);
        try self.enqueueDelivery(id, msg);
        // Surface the derived network-operator `*` to other members of this
        // oper's channels (the `*`/+Y never rides the user MODE above, which only
        // carries umodes). Skipped for opers without the override privilege.
        if (announce_prefix and conn.session.hasPriv(.oper_override))
            self.announceOperPrefixAllChannels(nick, true);
    }

    /// When `[oper] auto_override` is set, auto-enable the +j override umode for an
    /// operator holding the `oper_override` privilege — so admins get full channel
    /// authority (KICK/MODE/TOPIC/PROP/…) without a manual `/mode +j`. No-op when
    /// the option is off or the oper lacks the privilege.
    fn applyOperAutoOverride(self: *LinuxServer, conn: *ConnState) void {
        if (!self.config.oper_auto_override) return;
        if (conn.session.hasPriv(.oper_override)) _ = conn.session.setUmode(.override, true);
    }

    /// Revoke one live operator projection and publish every externally-visible
    /// consequence exactly once. Account mutation callers invoke this BEFORE
    /// loginAs/loginGuest/logout clears the session, preserving the old +a/+j
    /// and derived +Y facts long enough to retract them from clients. The
    /// actual authority cut happens first; all wire/event publication is
    /// best-effort and can never keep privilege alive on delivery failure.
    fn clearOperAuthorityTransition(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        announce_prefix: bool,
        reason: []const u8,
    ) bool {
        if (!conn.session.isOper()) return false;
        const had_admin = conn.session.hasUmode(.admin);
        const had_override_mode = conn.session.hasUmode(.override);
        const had_oper_prefix = conn.session.hasPriv(.oper_override);
        const nick = conn.session.displayName();

        conn.session.clearOper();

        var modes_buf: [5]u8 = undefined;
        var modes_len: usize = 0;
        modes_buf[modes_len] = '-';
        modes_len += 1;
        modes_buf[modes_len] = 'o';
        modes_len += 1;
        if (had_admin) {
            modes_buf[modes_len] = usermode.letterOf(.admin) orelse 'a';
            modes_len += 1;
        }
        if (had_override_mode) {
            modes_buf[modes_len] = usermode.letterOf(.override) orelse 'j';
            modes_len += 1;
        }
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = formatMessage(&msg_buf, self.serverName(), "MODE", &.{ nick, modes_buf[0..modes_len] }, null) catch "";
        if (msg.len != 0) self.enqueueDelivery(id, msg) catch {};
        self.publishUserEvent(conn, "DEOPER", reason) catch {};
        if (announce_prefix and had_oper_prefix)
            self.announceOperPrefixAllChannels(nick, false);
        return true;
    }

    /// Resolve a GRANT's privilege set: an explicit comma-separated privilege-name
    /// list when supplied, otherwise a class preset — admin/netadmin/sa => full
    /// authority (incl. oper_grant); any other class => a standard operator set.
    pub fn grantPrivileges(class: []const u8, priv_list: []const u8) ?oper_mod.OperPrivileges {
        if (priv_list.len != 0) {
            var names: [16][]const u8 = undefined;
            var n: usize = 0;
            var it = std.mem.splitScalar(u8, priv_list, ',');
            while (it.next()) |raw| {
                const name = std.mem.trim(u8, raw, " \t");
                if (name.len == 0) continue;
                if (n >= names.len) break;
                names[n] = name;
                n += 1;
            }
            return oper_mod.OperPrivileges.fromNames(names[0..n]) catch null;
        }
        const eqi = std.ascii.eqlIgnoreCase;
        if (eqi(class, "admin") or eqi(class, "netadmin") or eqi(class, "sa")) {
            return oper_mod.OperPrivileges.full;
        }
        return oper_mod.OperPrivileges.initMany(&.{
            .server_rehash, .client_moderate, .channel_moderate, .client_kill,
            .mesh_admin,    .oper_spy,        .event_subscribe,  .audit_read,
            .oper_override,
        });
    }

    /// GRANT <account> <class> [priv,priv,...] — mint a mesh oper grant that
    /// peers project as remote WHOIS 313 / NAMES `*` / `MODE +Y`. Requires
    /// `oper_grant`. Does not elevate a local session; configured `[[opers]]`
    /// remain the authority plane for KICK/DATA/isOverrideOper.
    pub fn handleGrant(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleGrant(self, conn, parsed);
    }

    /// REVOKE <account> — supersede a mesh display grant with a zero-privilege
    /// tombstone (peers drop remote `*` / +Y). Configured `[[opers]]` accounts
    /// remain outside this plane and cannot be revoked by this command.
    pub fn handleRevoke(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleRevoke(self, conn, parsed);
    }

    /// GRANTS — list non-tombstone mesh display grants.
    pub fn handleGrants(self: *LinuxServer, conn: *ConnState) !void {
        return oper_cmd.handleGrants(self, conn);
    }

    /// Persist non-tombstone mesh display grants this node issued to
    /// `[oper] grants_path` (tab-separated account/privbits/class/title).
    /// Tombstones (privilege_bits == 0) are omitted. No-op when no path is set.
    pub fn persistGrants(self: *LinuxServer) void {
        if (self.config.oper_grants_path.len == 0) return;
        // Accumulate into a growable buffer: a fixed buffer silently dropped
        // grants past its size, so a large network would fail to persist (and
        // thus restore) the tail of its grant set.
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(self.allocator);
        const now: u64 = self.grantNowU64();
        var it = self.oper_grants.liveIterator(now);
        while (it.next()) |g| {
            if (g.privilege_bits == 0) continue;
            // Persist only grants THIS node issued. A peer's grants are re-learned
            // when it relinks; re-minting them here on restart would resurrect ones
            // the peer may have since revoked and mis-attribute their provenance.
            if (!std.mem.eql(u8, g.issuer_node, protocol_inventory.currentServerName())) continue;
            // Skip any field carrying a separator byte (keeps the format simple).
            if (hasSep(g.account) or hasSep(g.class) or hasSep(g.title)) continue;
            out.print(self.allocator, "{s}\t{d}\t{s}\t{s}\n", .{ g.account, g.privilege_bits, g.class, g.title }) catch return;
        }
        writeFileAbs(self.allocator, self.config.oper_grants_path, out.items);
    }

    /// Reload persisted mesh display grants at boot. Re-minting does not elevate
    /// local sessions; remote `*` / +Y projection follows the override edge.
    /// Called once from `start`; no-op without a configured path / readable file.
    fn loadGrants(self: *LinuxServer) void {
        if (self.inherited_oper_grants_restored) return;
        if (self.config.oper_grants_path.len == 0) return;
        const io = self.config.crypto_io orelse return;
        const text = std.Io.Dir.cwd().readFileAlloc(io, self.config.oper_grants_path, self.allocator, .limited(1 << 20)) catch return;
        defer self.allocator.free(text);
        var restored: usize = 0;
        var lines = std.mem.splitScalar(u8, text, '\n');
        while (lines.next()) |raw| {
            const line = std.mem.trim(u8, raw, " \r\t");
            if (line.len == 0 or line[0] == '#') continue;
            var f = std.mem.splitScalar(u8, line, '\t');
            const account = f.next() orelse continue;
            const bits_s = f.next() orelse continue;
            const class = f.next() orelse "operator";
            const title = f.next() orelse "";
            const bits = std.fmt.parseInt(u64, std.mem.trim(u8, bits_s, " "), 10) catch continue;
            if (account.len == 0 or bits == 0) continue;
            self.mintOperGrant(account, oper_mod.OperPrivileges.fromBits(bits), class, title);
            restored += 1;
        }
        if (restored != 0) srvLog("onyx-server: restored {d} mesh display OCG1 grant(s)\n", .{restored});
    }

    /// Restore the per-channel statistics snapshot persisted by a previous run,
    /// invoked once from `start`. No-op without a configured dir / readable file.
    fn loadChanstats(self: *LinuxServer) void {
        if (self.inherited_chanstats_restored) return;
        if (self.config.chanstats_dir.len == 0) return;
        const io = self.config.crypto_io orelse return;
        chanstats_mod.loadSnapshot(&self.chanstats, io, self.config.chanstats_dir);
        // Apply ophion-style ignore list after snapshot load so ignored bots
        // never gain new samples (historical rows stay in the snapshot until prune).
        self.chanstats.setIgnoredNicks(self.config.chanstats_ignore_nicks);
        const interval = @max(self.config.stats_interval_ms, @as(i64, 1));
        self.chanstats_prune_ready_ms = self.nowMs() + @max(interval * 4, @as(i64, 120_000));
    }

    /// Restore the Event Spine history ring from `[oper] event_history_path` so
    /// `EVENT REPLAY` survives a USR2 hot-upgrade and a cold restart. Best-effort.
    fn loadEventHistory(self: *LinuxServer) void {
        if (self.config.event_history_path.len == 0) return;
        const io = self.config.crypto_io orelse return;
        const data = std.Io.Dir.cwd().readFileAlloc(io, self.config.event_history_path, self.allocator, .limited(1 << 22)) catch return;
        defer self.allocator.free(data);
        _ = self.event_history.load(data);
    }

    fn restoreEventHistoryAtStart(self: *LinuxServer) void {
        if (self.inherited_event_history_restored) return;
        self.loadEventHistory();
    }

    /// Persist the Event Spine history ring (best-effort). Called on the stats
    /// cadence so at most one interval of events is lost across a restart.
    fn saveEventHistory(self: *LinuxServer) void {
        if (self.config.event_history_path.len == 0) return;
        // Atomic write (tmp+rename): a SIGKILL/power-loss mid-write must not leave
        // a truncated snapshot behind the loader's exact-length framing. Requires
        // the same `crypto_io` the loader uses; symmetric with `loadEventHistory`,
        // which already no-ops without it (so persistence is off either way).
        const io = self.config.crypto_io orelse return;
        var aw = std.Io.Writer.Allocating.init(self.allocator);
        defer aw.deinit();
        self.event_history.serializeInto(&aw.writer) catch return;
        const path = self.config.event_history_path;
        const dir = std.fs.path.dirname(path) orelse ".";
        const name = std.fs.path.basename(path);
        chanstats_mod.writeFileAtomicIo(io, dir, name, aw.written());
    }

    // --- Account command family (Phase 2) ----------------------------------

    /// Map a services registration error to an IRCv3 standard-reply FAIL code.
    fn registerFailCode(err: anyerror) []const u8 {
        return switch (err) {
            error.AlreadyExists => "ACCOUNT_EXISTS",
            error.InvalidName => "BAD_ACCOUNT_NAME",
            error.InvalidPassword => "INVALID_PASSWORD",
            error.InvalidValue => "INVALID_EMAIL",
            error.Forbidden => "ACCOUNT_FORBIDDEN",
            else => "TEMPORARILY_UNAVAILABLE",
        };
    }

    /// Services bridge: mark `channel` REGISTERED (+r) in the live world, or
    /// clear it. Registering materializes an empty persistent channel so a
    /// reserved channel survives with no members; dropping clears +r so the
    /// channel becomes ephemeral and is reclaimed on the next empty.
    pub fn markChannelRegistered(self: *LinuxServer, channel: []const u8, registered: bool) std.mem.Allocator.Error!void {
        _ = try self.world.markRegistered(channel, registered);
    }

    pub fn replayServicesLiveState(self: *LinuxServer, svc: *services_mod.Services) void {
        _ = self.replayServicesLiveStateFallible(svc) catch |err| {
            srvLog("onyx-server: services live-state replay failed ({s})\n", .{@errorName(err)});
        };
    }

    /// Unpublished cold graph: a replay error aborts its owner before READY.
    /// Inherited state is restored from its strict capsule instead of replayed.
    pub fn replayServicesLiveStateFallible(self: *LinuxServer, svc: *services_mod.Services) !services_mod.LiveReplaySummary {
        const ReplayCtx = struct {
            server: *LinuxServer,

            fn onChannel(ctx: *anyopaque, channel: []const u8, mlock: []const u8) services_mod.ServiceError!void {
                const self_ctx: *@This() = @ptrCast(@alignCast(ctx));
                try self_ctx.server.markChannelRegistered(channel, true);
                if (mlock.len != 0) try self_ctx.server.setMlock(channel, mlock);
            }

            fn onAkick(ctx: *anyopaque, channel: []const u8, mask: []const u8, reason: []const u8, setter: []const u8) services_mod.ServiceError!void {
                const self_ctx: *@This() = @ptrCast(@alignCast(ctx));
                self_ctx.server.chan_akick.add(channel, mask, reason, setter, self_ctx.server.nowMs(), null) catch |err| switch (err) {
                    error.Duplicate => {},
                    error.InvalidMask, error.ListFull => return error.InvalidRecord,
                    error.OutOfMemory => return error.OutOfMemory,
                };
            }

            fn onWard(ctx: *anyopaque, replay: services_mod.ReplayWard) services_mod.ServiceError!void {
                const self_ctx: *@This() = @ptrCast(@alignCast(ctx));
                const match = warden.Match.parse(replay.match) orelse return error.InvalidRecord;
                const scope = warden.Scope.parse(replay.scope) orelse return error.InvalidRecord;
                const action = warden.Action.parse(replay.action) orelse return error.InvalidRecord;
                self_ctx.server.warden.add(.{
                    .match = match,
                    .pattern = replay.pattern,
                    .scope = scope,
                    .action = action,
                    .reason = replay.reason,
                    .set_by = replay.setter,
                    .created_ms = replay.created_ms,
                    .expires_ms = replay.expires_ms,
                }) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    else => return error.InvalidRecord,
                };
            }

            fn onSaccess(ctx: *anyopaque, replay: services_mod.ReplaySaccess) services_mod.ServiceError!void {
                const self_ctx: *@This() = @ptrCast(@alignCast(ctx));
                const entry_type = ircx_saccess.EntryType.parse(replay.entry_type) orelse return error.InvalidRecord;
                self_ctx.server.saccess.add(.{
                    .entry_type = entry_type,
                    .mask = replay.mask,
                    .duration = if (replay.duration != 0) replay.duration else null,
                    .reason = if (replay.reason.len != 0) replay.reason else null,
                }) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    else => return error.InvalidRecord,
                };
            }
        };

        var ctx = ReplayCtx{ .server = self };
        const summary = try svc.replayLiveState(.{
            .ptr = &ctx,
            .channel = ReplayCtx.onChannel,
            .akick = ReplayCtx.onAkick,
            .ward = ReplayCtx.onWard,
            .saccess = ReplayCtx.onSaccess,
        });
        if (summary.channels != 0 or summary.akicks != 0 or summary.wards != 0 or summary.saccesses != 0) {
            srvLog(
                "onyx-server: services replay restored {d} channel(s), {d} MLOCK(s), {d} AKICK(s), {d} WARD(s), {d} SACCESS(es)\n",
                .{ summary.channels, summary.mlocks, summary.akicks, summary.wards, summary.saccesses },
            );
        }
        return summary;
    }

    /// Mark `conn` logged in as the canonical (lowercased) `account`.
    fn loginSession(conn: *ConnState, account: []const u8) void {
        conn.session_list_cache.reset();
        var buf: [account_register.MAX_ACCOUNT_BYTES]u8 = undefined;
        const n = @min(account.len, buf.len);
        const lower = std.ascii.lowerString(buf[0..n], account[0..n]);
        conn.session.loginAs(lower);
    }

    /// Successful account replacement is an authority boundary for live media.
    /// Retire the old account's physical publisher while its nick, membership,
    /// and account route are still intact. Failed authentication never reaches
    /// this helper, and a case-insensitive same-account refresh is a no-op.
    fn retireMediaBeforeAccountMutation(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        target_account: ?[]const u8,
    ) void {
        const old_account = conn.session.account() orelse return;
        if (target_account) |target| {
            if (std.ascii.eqlIgnoreCase(old_account, target)) return;
        }
        self.leaveAllMediaRooms(id, conn);
        conn.clearMediaCall();
        conn.clearMediaE2eeAttachment();
    }

    /// Shared post-authentication login sequence, factored so a password-less
    /// login (WEBAUTHN AUTH-FINISH) fires the same side effects as the IDENTIFY
    /// success path (`handleIdentify`): bind the session to `account`, emit the
    /// account-change/registration notices, restore metadata/silence, elevate an
    /// operator whose account is oper-bound, track the session, and run the login
    /// deliverables (memo, autojoin, welcome, nick protection). The caller has
    /// already verified the credential and cleared the login throttle. This
    /// mirrors — and is intentionally kept in lockstep with — the tail of
    /// `handleIdentify`; it does NOT emit the "You are now identified" notice so
    /// each caller can print its own success line.
    fn finishLogin(self: *LinuxServer, conn: *ConnState, account: []const u8) !void {
        if (!self.authenticationAvailable()) return error.StorePoisoned;
        const id = idFromToken(conn.token);
        self.retireMediaBeforeAccountMutation(id, conn, account);
        _ = self.clearOperAuthorityTransition(id, conn, true, "account authentication replaced operator authority");
        // Re-login to a different account: drop the previous account's session
        // binding first (mirrors handleLogout / handleIdentify) so a stale
        // SessionStore entry can't keep this connection in the old delivery set.
        if (conn.session.account()) |old| {
            if (!std.ascii.eqlIgnoreCase(old, account))
                _ = self.removeTrackedSession(old, monitorIdFromClient(id));
        }
        loginSession(conn, account);
        if (conn.session.account()) |acct| self.emitAccountChange(id, conn, acct);
        self.maybeApplyAccountCloak(id, conn);
        self.restoreAccountMetadata(conn, account);
        self.restoreAccountSilence(conn, account);
        try self.elevateOperFromAccount(conn);
        self.trackSession(id, conn);
        self.armBoundedExactResumeHoldIfNeeded(id, conn);
        if (!try self.enforceE2eeSessionEligibility(id, conn)) return;
        try self.deliverMemo(conn);
        self.applyLoginJoinState(id, conn);
        self.deliverWelcome(conn);
        self.emitClientRegistered(id, conn);
        self.evaluateNickProtection(conn);
    }

    /// `REGISTER <account> <email|*> <password>` (IRCv3 draft/account-registration).
    /// Immediate registration (no email verification step yet); logs the client in
    /// and applies oper elevation if the account is bound in the registry.
    pub fn handleRegister(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.authenticationAvailable())
            return self.failReply(conn, "REGISTER", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        const svc = self.account_services orelse return self.failReply(conn, "REGISTER", "TEMPORARILY_UNAVAILABLE", "Account registration is unavailable");
        if (parsed.param_count < 3) {
            try self.failReply(conn, "REGISTER", "NEED_MORE_PARAMS", "Usage: REGISTER <account> <email|*> <password>");
            return;
        }
        const requested_account = parsed.paramSlice()[0];
        const account = if (std.mem.eql(u8, requested_account, "*")) conn.session.displayName() else requested_account;
        const email = parsed.paramSlice()[1];
        const has_email = email.len != 0 and !std.mem.eql(u8, email, "*");
        const password = parsed.paramSlice()[2];
        var scratch: [1024]u8 = undefined;
        _ = svc.registerAccountWithEmail(account, password, if (has_email) email else null, false, &scratch) catch |err| {
            try self.failReply(conn, "REGISTER", registerFailCode(err), "Registration failed");
            return;
        };
        if (!self.authenticationAvailable())
            return self.failReply(conn, "REGISTER", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        self.retireMediaBeforeAccountMutation(idFromToken(conn.token), conn, account);
        _ = self.clearOperAuthorityTransition(
            idFromToken(conn.token),
            conn,
            true,
            "account registration replaced operator authority",
        );
        if (conn.session.account()) |old| {
            if (!std.ascii.eqlIgnoreCase(old, account))
                _ = self.removeTrackedSession(old, monitorIdFromClient(idFromToken(conn.token)));
        }
        loginSession(conn, account);
        if (conn.session.account()) |acct| self.emitAccountChange(idFromToken(conn.token), conn, acct);
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} REGISTER SUCCESS {s} :Account registered\r\n", .{ self.serverName(), account }) catch return;
        try appendToConn(conn, line);
        // Email verification. With a configured mail transport, issue a token and
        // deliver it OUT-OF-BAND to the address (proving ownership); the user
        // confirms with VERIFY. Without a transport, the address is recorded but
        // stays UNVERIFIED and we say so plainly — we never show an in-band code
        // (the user verifying themselves on the same connection proves nothing).
        if (has_email) {
            if (self.config.mail_sender) |ms| {
                if (self.config.crypto_io) |io| {
                    var tok_bytes: [16]u8 = undefined;
                    io.random(&tok_bytes);
                    const now_u: u64 = @intCast(@max(0, self.nowMs()));
                    if (svc.beginEmailVerification(&self.account_verifies, account, email, &tok_bytes, now_u, &scratch)) |token| {
                        var body_buf: [512]u8 = undefined;
                        const body = std.fmt.bufPrint(&body_buf, "Hello {s},\r\n\r\nYour verification code for {s} is: {s}\r\n\r\nConfirm it on IRC with:  VERIFY {s}\r\n\r\nIf you did not request this, ignore this message.\r\n", .{ account, self.serverName(), token, token }) catch "";
                        if (body.len != 0) ms.enqueue(email, "Verify your account", body);
                        try channelNotice(conn, "A verification code was emailed to {s}; confirm it with: VERIFY <code>", .{email});
                    } else |_| {
                        try channelNotice(conn, "Email {s} recorded (unverified — a verification code could not be issued)", .{email});
                    }
                }
            } else {
                try channelNotice(conn, "Email {s} recorded (unverified — this server cannot verify email ownership yet)", .{email});
            }
        }
        if (conn.session.sasl_oper_elevation_allowed) try self.elevateOperFromAccount(conn);
        self.trackSession(idFromToken(conn.token), conn);
        self.armBoundedExactResumeHoldIfNeeded(idFromToken(conn.token), conn);
        if (!try self.enforceE2eeSessionEligibility(idFromToken(conn.token), conn)) return;
        try self.deliverMemo(conn);
        self.applyLoginJoinState(idFromToken(conn.token), conn);
        self.deliverWelcome(conn);
        self.emitClientRegistered(idFromToken(conn.token), conn);
        self.evaluateNickProtection(conn);
    }

    /// Source-IP key for the login throttle, or null when the connection has no
    /// real host or is the loopback/local default (local/trusted sources are
    /// never throttled — same exemption as the connection-rate throttle).
    fn loginThrottleIp(conn: *const ConnState) ?[]const u8 {
        const ip = conn.session.realHost();
        if (ip.len == 0 or std.mem.eql(u8, ip, default_host)) return null;
        return ip;
    }

    /// Retry-after (ms) if password auth for `account` on `conn` is currently
    /// locked out by the brute-force throttle (account OR source-IP namespace),
    /// else null. Pure read — never records.
    fn loginLockedFor(self: *LinuxServer, conn: *const ConnState, account: []const u8) ?i64 {
        const now = self.nowMs();
        if (self.login_throttle.isLocked(.account, account, now)) |ms| return ms;
        if (loginThrottleIp(conn)) |ip| {
            if (self.login_throttle.isLocked(.ip, ip, now)) |ms| return ms;
        }
        return null;
    }

    /// Record one failed password attempt against `account` + the source IP.
    fn loginRecordFailure(self: *LinuxServer, conn: *const ConnState, account: []const u8) void {
        const now = self.nowMs();
        _ = self.login_throttle.recordFailure(.account, account, now);
        if (loginThrottleIp(conn)) |ip| _ = self.login_throttle.recordFailure(.ip, ip, now);
        // SECURITY event: surface auth failures so opers see brute-force activity
        // (and it lands in EVENT REPLAY). Real host — a security/oper-trust feed.
        var mbuf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&mbuf, "auth failure for account {s} from {s}", .{ account, conn.session.realHost() }) catch return;
        self.publishOperEvent(.security, .warn, msg) catch {};
    }

    /// Clear throttle state for `account` + the source IP after a success.
    fn loginRecordSuccess(self: *LinuxServer, conn: *const ConnState, account: []const u8) void {
        self.login_throttle.recordSuccess(.account, account);
        if (loginThrottleIp(conn)) |ip| self.login_throttle.recordSuccess(.ip, ip);
    }

    /// Reject `cmd` (IDENTIFY/DROP) with ERR_PASSWDMISMATCH carrying the lockout
    /// retry-after. Shared by the password-auth brute-force guard.
    fn rejectLoginLocked(self: *LinuxServer, conn: *ConnState, retry_ms: i64) !void {
        _ = self;
        var rb: [192]u8 = undefined;
        const secs = @divFloor(retry_ms + 999, 1000); // ceil to whole seconds
        const msg = std.fmt.bufPrint(&rb, "Too many failed login attempts - retry in {d}s", .{secs}) catch "Too many failed login attempts";
        try queueNumeric(conn, .ERR_PASSWDMISMATCH, &.{}, msg);
    }

    /// `IDENTIFY <account> <password>` — authenticate to an existing account.
    pub fn handleIdentify(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.authenticationAvailable())
            return self.failReply(conn, "IDENTIFY", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        const svc = self.account_services orelse return self.failReply(conn, "IDENTIFY", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        if (parsed.param_count < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"IDENTIFY"}, "Usage: IDENTIFY <account> <password> [<2fa-code>]");
            return;
        }
        const account = parsed.paramSlice()[0];
        // Brute-force guard: refuse before attempting auth when locked out.
        if (self.loginLockedFor(conn, account)) |retry_ms| return self.rejectLoginLocked(conn, retry_ms);
        _ = svc.identifyAccount(account, parsed.paramSlice()[1]) catch {
            self.loginRecordFailure(conn, account);
            try queueNumeric(conn, .ERR_PASSWDMISMATCH, &.{}, "Invalid account or password");
            return;
        };
        // TOTP second factor: a 2FA-active account must also supply a valid code
        // as the 3rd parameter. A correct password with a missing/incorrect code
        // is a FAILED login (an attacker may hold the password) — it counts
        // against the brute-force throttle and never logs in.
        if (self.totpRequired(account)) {
            _ = self.totpActiveForAccount(account); // load the secret into the live store
            const code = if (parsed.param_count >= 3) parsed.paramSlice()[2] else "";
            const ok = code.len != 0 and (self.totp.verify(account, code, totpUnixSeconds()) catch .bad_code) == .ok;
            if (!ok) {
                self.loginRecordFailure(conn, account);
                return self.failReply(conn, "IDENTIFY", "TOTP_REQUIRED", "Two-factor code required: IDENTIFY <account> <password> <6-digit-code>");
            }
        }
        if (!self.authenticationAvailable())
            return self.failReply(conn, "IDENTIFY", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        self.loginRecordSuccess(conn, account);
        self.retireMediaBeforeAccountMutation(idFromToken(conn.token), conn, account);
        _ = self.clearOperAuthorityTransition(
            idFromToken(conn.token),
            conn,
            true,
            "account authentication replaced operator authority",
        );
        // Re-IDENTIFY to a different account: drop the previous account's session
        // binding first (mirrors handleLogout), so a stale SessionStore entry can
        // never keep this connection in the old account's delivery/fan-out set.
        if (conn.session.account()) |old| {
            if (!std.ascii.eqlIgnoreCase(old, account))
                _ = self.removeTrackedSession(old, monitorIdFromClient(idFromToken(conn.token)));
        }
        loginSession(conn, account);
        if (conn.session.account()) |acct| self.emitAccountChange(idFromToken(conn.token), conn, acct);
        // Per-account cloak: switch the visible host to <account>.users.<suffix>
        // now that the login is confirmed (post-registration path; the handshake
        // path is handled by applyVisibleHost at registration).
        self.maybeApplyAccountCloak(idFromToken(conn.token), conn);
        self.restoreAccountMetadata(conn, account);
        self.restoreAccountSilence(conn, account);
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :You are now identified as {s}\r\n", .{ self.serverName(), conn.session.displayName(), account }) catch return;
        try emitReplyLine(conn, line);
        try self.elevateOperFromAccount(conn);
        self.trackSession(idFromToken(conn.token), conn);
        self.armBoundedExactResumeHoldIfNeeded(idFromToken(conn.token), conn);
        if (!try self.enforceE2eeSessionEligibility(idFromToken(conn.token), conn)) return;
        try self.deliverMemo(conn);
        self.applyLoginJoinState(idFromToken(conn.token), conn);
        self.deliverWelcome(conn);
        self.emitClientRegistered(idFromToken(conn.token), conn);
        self.evaluateNickProtection(conn);
    }

    /// `LOGOUT` — drop the session's account login. Because operator status is
    /// SASL-account-derived (no password OPER), logging out also revokes oper:
    /// otherwise an operator could log out yet retain +o and its privileges.
    pub fn handleLogout(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) !void {
        self.retireMediaBeforeAccountMutation(id, conn, null);
        // Drop this connection's live session before clearing the account binding
        // (the session is keyed by account; logout fully ends it, no reclaim).
        conn.session_list_cache.reset();
        if (conn.session.account()) |acct| _ = self.removeTrackedSession(acct, monitorIdFromClient(id));
        // Whether an account session is actually being cleared decides if we emit
        // 901 RPL_LOGGEDOUT below (a no-op LOGOUT on an unauthenticated session
        // must not claim a logout happened).
        const was_logged_in = conn.session.account() != null;
        // account-notify: tell common channels this user is no longer logged in
        // (emit BEFORE clearing the account so the prefix/state is still valid).
        self.emitAccountChange(id, conn, "*");
        const was_oper = conn.session.isOper();
        // RPL_LOGGEDOUT (901): emit the IRCv3 logout numeric with the user's full
        // mask BEFORE clearing the binding, so the mask still reflects the
        // logged-in identity. Emitted as a raw line because this daemon's local
        // numeric enum repurposes the 9xx range for IRCX errors; 901 is the
        // standard SASL logout numeric and must use the spec code. Only fires when
        // a session was actually cleared.
        if (was_logged_in) {
            var mask_buf: [256]u8 = undefined;
            const mask = clientPrefix(conn, &mask_buf) catch conn.session.displayName();
            var l901: [default_reply_bytes]u8 = undefined;
            if (std.fmt.bufPrint(&l901, ":{s} 901 {s} {s} :You are now logged out\r\n", .{ self.serverName(), conn.session.displayName(), mask })) |line| {
                try appendToConn(conn, line);
            } else |_| {}
        }
        if (was_oper)
            _ = self.clearOperAuthorityTransition(id, conn, true, "account logout revoked operator authority");
        conn.session.logout();
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :You are now logged out\r\n", .{ self.serverName(), conn.session.displayName() }) catch return;
        try emitReplyLine(conn, line);
    }

    fn closeDroppedAccountConnections(
        self: *LinuxServer,
        account: []const u8,
        except: ?client_model.ClientId,
    ) void {
        // Account deletion revokes the identity, not merely its resumable rows.
        // ConnState is owner-reactor storage: inspect it under the World lock but
        // route teardown through the owner seam so foreign SendQ/ring state is
        // never mutated here. Local close errors still leave `closing` set by
        // closeConn's retry path; cross-shard mailbox exhaustion poisons the
        // exact generation and is swept closed by its owner.
        for (self.reactors) |*reactor| {
            var slot_index: usize = 0;
            while (slot_index < reactor.clients.slots.items.len) : (slot_index += 1) {
                const slot = &reactor.clients.slots.items[slot_index];
                if (!slot.occupied) continue;
                const live_account = slot.value.session.account() orelse continue;
                if (!std.ascii.eqlIgnoreCase(live_account, account)) continue;
                const id = slotClientId(reactor, slot_index, slot.gen);
                if (except) |retained| if (id.eql(retained)) continue;
                self.enqueueCloseOnOwner(id, "Account dropped") catch {};
            }
        }
    }

    /// `DROP <account> <password>` — delete an account (requires its password).
    pub fn handleDrop(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const svc = self.account_services orelse return self.failReply(conn, "DROP", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        if (parsed.param_count < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"DROP"}, "Usage: DROP <account> <password>");
            return;
        }
        const account = parsed.paramSlice()[0];
        // Shared brute-force guard: DROP is the same password-auth surface as
        // IDENTIFY, so failed DROP attempts accumulate on the same throttle keys.
        if (self.loginLockedFor(conn, account)) |retry_ms| return self.rejectLoginLocked(conn, retry_ms);
        _ = svc.dropAccount(account, parsed.paramSlice()[1]) catch {
            self.loginRecordFailure(conn, account);
            try queueNumeric(conn, .ERR_PASSWDMISMATCH, &.{}, "Invalid account or password");
            return;
        };
        self.loginRecordSuccess(conn, account);
        // Account deletion is an authorization boundary, not just a services
        // record mutation. Retire every local reusable-session authority now so
        // a previously issued MTOKEN cannot resurrect the deleted account from a
        // mesh replica.
        _ = self.removeAllTrackedSessions(account);
        // Hand any channels this account founded to their configured successors.
        self.promoteSuccessorsForDroppedFounder(account);
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :Account {s} dropped\r\n", .{ self.serverName(), conn.session.displayName(), account }) catch return;
        const requester = idFromToken(conn.token);
        // Account deletion closes every authenticated socket, but the requester
        // must observe the committed result first. Queue its notice and terminal
        // close as one ordered owner operation; an immediate local close would
        // discard the just-appended SendQ before the kernel could transmit it.
        try self.enqueueDeliveryThenClose(requester, line, "Account dropped");
        self.closeDroppedAccountConnections(account, requester);
    }

    /// `SETPASS <current-password> <new-password>` — change the logged-in account's
    /// password after verifying the current one. The new password must satisfy the
    /// length policy (8-512) and differ from the current one. SCRAM credentials are
    /// re-derived so SCRAM logins keep working.
    /// Whether `conn` has proven its identity for `account` by a CLIENT
    /// CERTIFICATE bound to that account — a possession factor. Lets a user who
    /// forgot their password recover it (set a new one without the current one)
    /// after authenticating with their bound cert (e.g. via SASL EXTERNAL).
    fn sessionCertVerifiedFor(self: *LinuxServer, conn: *const ConnState, account: []const u8) bool {
        const svc = self.account_services orelse return false;
        const fp = conn.session.tls_certfp orelse return false;
        if (fp.len == 0) return false;
        const bound = svc.accountForCertfp(fp) orelse return false;
        return std.ascii.eqlIgnoreCase(bound, account);
    }

    pub fn handleSetpass(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.authenticationAvailable())
            return self.failReply(conn, "SETPASS", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        const svc = self.account_services orelse return self.failReply(conn, "SETPASS", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        const account = conn.session.account() orelse {
            try self.failReply(conn, "SETPASS", "ACCOUNT_REQUIRED", "Log in to change your password");
            return;
        };
        const p = parsed.paramSlice();
        var scratch: [1024]u8 = undefined;

        // Recovery form: SETPASS <new-password> (one argument) sets a new password
        // WITHOUT the current one — allowed only when the connection proved its
        // identity by a client certificate bound to this account (a possession
        // factor), so a forgotten password can be reset after a SASL EXTERNAL login.
        if (p.len == 1 and p[0].len != 0) {
            if (!self.sessionCertVerifiedFor(conn, account))
                return self.failReply(conn, "SETPASS", "RESET_NOT_AUTHORIZED", "One-argument SETPASS (reset without the current password) requires a connection authenticated by a client certificate bound to this account");
            svc.setAccountPasswordForced(account, p[0], &scratch) catch |err| {
                const code: []const u8 = if (err == error.InvalidPassword) "INVALID_PASSWORD" else "TEMPORARILY_UNAVAILABLE";
                return self.failReply(conn, "SETPASS", code, "New password rejected");
            };
            try self.noticeTo(conn, "SETPASS: your password has been reset (verified by client certificate)");
            return;
        }

        if (p.len < 2 or p[0].len == 0 or p[1].len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"SETPASS"}, "Usage: SETPASS <current-password> <new-password>  (or, on a cert-verified connection, SETPASS <new-password>)");
            return;
        }
        svc.changeAccountPassword(account, p[0], p[1], &scratch) catch |err| {
            const code: []const u8 = switch (err) {
                error.AuthFailed => "WRONG_PASSWORD",
                error.InvalidPassword => "INVALID_PASSWORD",
                else => "TEMPORARILY_UNAVAILABLE",
            };
            const msg: []const u8 = switch (err) {
                error.AuthFailed => "Current password is incorrect",
                error.InvalidPassword => "New password rejected (8-512 chars, must differ from current)",
                else => "Could not change password",
            };
            try self.failReply(conn, "SETPASS", code, msg);
            return;
        };
        try self.noticeTo(conn, "SETPASS: your password has been changed");
    }

    /// Reset token: 16 random bytes rendered as 32 lowercase-hex chars (matches
    /// the email-verification token style).
    const reset_token_hex_len: usize = 32;
    /// Don't re-send a reset email while a token issued within this window is
    /// still pending — an anti-bombing cooldown.
    const reset_resend_cooldown_ms: u64 = 60 * 1000;

    /// Non-committal reply for the RESETPASS REQUEST form. Sent identically
    /// whether or not the account exists / has a verified email, so the command
    /// cannot be used to enumerate accounts.
    fn resetGenericReply(self: *LinuxServer, conn: *ConnState) !void {
        try self.noticeTo(conn, "RESETPASS: if that account has a verified email, a reset code has been sent.");
    }

    /// `RESETPASS <account>` — request an emailed reset code; or
    /// `RESETPASS <account> <code> <new-password>` — set a new password with the
    /// code. The "other method" companion to the cert-verified SETPASS recovery:
    /// a forgotten password is reset by proving ownership of the account's
    /// verified email. Usable while logged out. Requires a configured mail
    /// transport ([mail]); the code is delivered out-of-band only.
    pub fn handleResetpass(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.authenticationAvailable())
            return self.failReply(conn, "RESETPASS", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        const svc = self.account_services orelse return self.failReply(conn, "RESETPASS", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        if (parsed.param_count == 0 or parsed.paramSlice()[0].len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"RESETPASS"}, "Usage: RESETPASS <account>  (request a code)  or  RESETPASS <account> <code> <new-password>  (set it)");
            return;
        }
        const p = parsed.paramSlice();
        const account = p[0];
        const now_u: u64 = @intCast(@max(0, self.nowMs()));

        // Confirm form: RESETPASS <account> <code> <new-password>.
        if (p.len >= 3 and p[1].len != 0 and p[2].len != 0) {
            switch (self.reset_store.confirm(account, p[1], now_u)) {
                .ok => {
                    var scratch: [1024]u8 = undefined;
                    svc.setAccountPasswordForced(account, p[2], &scratch) catch |err| {
                        const code: []const u8 = if (err == error.InvalidPassword) "INVALID_PASSWORD" else "TEMPORARILY_UNAVAILABLE";
                        const message: []const u8 = if (err == error.InvalidPassword) "New password rejected (8-512 chars)" else "Could not complete password reset; account storage may require recovery";
                        return self.failReply(conn, "RESETPASS", code, message);
                    };
                    // Services commits password, SCRAM and token authority
                    // together. Reset-code consumption above still precedes
                    // admission, so a failed admission requires a fresh code.
                    var buf: [default_reply_bytes]u8 = undefined;
                    const line = std.fmt.bufPrint(&buf, ":{s} RESETPASS SUCCESS {s} :Password reset; log in with your new password\r\n", .{ self.serverName(), account }) catch return;
                    try appendToConn(conn, line);
                },
                .no_request => try self.failReply(conn, "RESETPASS", "NO_REQUEST", "No password reset is pending for that account"),
                .expired => try self.failReply(conn, "RESETPASS", "EXPIRED", "That reset code has expired; request a new one"),
                .bad_token => try self.failReply(conn, "RESETPASS", "BAD_CODE", "Incorrect reset code"),
                .too_many_attempts => try self.failReply(conn, "RESETPASS", "TOO_MANY_ATTEMPTS", "Too many incorrect codes; request a new reset"),
            }
            return;
        }

        // Request form: RESETPASS <account>. Email transport is mandatory.
        const ms = self.config.mail_sender orelse
            return self.failReply(conn, "RESETPASS", "UNAVAILABLE", "Email password reset is not configured on this server");
        const io = self.config.crypto_io orelse return self.resetGenericReply(conn);

        // Look up the account's VERIFIED email; respond generically on any miss so
        // the command never reveals whether an account exists.
        const info = svc.accountInfo(account) catch return self.resetGenericReply(conn);
        const ai = info.account_info;
        const email = ai.email.asSlice();
        if (!ai.email_verified or email.len == 0) return self.resetGenericReply(conn);

        // Anti-bomb cooldown: skip re-sending while a fresh token is still pending.
        if (self.reset_store.pending(account)) |pend| {
            if (now_u >= pend.issued_ms and now_u - pend.issued_ms < reset_resend_cooldown_ms)
                return self.resetGenericReply(conn);
        }

        var rand_bytes: [reset_token_hex_len / 2]u8 = undefined;
        io.random(&rand_bytes);
        var token_buf: [reset_token_hex_len]u8 = undefined;
        const hex = "0123456789abcdef";
        for (rand_bytes, 0..) |b, i| {
            token_buf[i * 2] = hex[b >> 4];
            token_buf[i * 2 + 1] = hex[b & 0x0f];
        }
        self.reset_store.issue(account, token_buf[0..], now_u) catch return self.resetGenericReply(conn);

        // `email` borrows `ai`, which lives until this function returns; enqueue
        // dupes it, so no separate copy is needed.
        var body_buf: [640]u8 = undefined;
        const body = std.fmt.bufPrint(&body_buf, "Hello {s},\r\n\r\nA password reset was requested for your account on {s}.\r\n\r\nReset code: {s}\r\n\r\nSet a new password on IRC with:\r\n  RESETPASS {s} {s} <new-password>\r\n\r\nThis code expires in 15 minutes. If you did not request this, ignore this message.\r\n", .{ account, self.serverName(), token_buf[0..], account, token_buf[0..] }) catch "";
        if (body.len != 0) ms.enqueue(email, "Password reset code", body);
        try self.resetGenericReply(conn);
    }

    /// `SUCCESSOR <#channel> SHOW|SET <account>|CLEAR` — a registered channel's
    /// founder heir. If the founder's account is later dropped, the channel is
    /// handed to its configured successor (see handleDrop). SET/CLEAR require the
    /// caller to be the channel founder or an operator.
    pub fn handleSuccessor(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const svc = self.account_services orelse return self.failReply(conn, "SUCCESSOR", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        const params = parsed.paramSlice();
        if (params.len < 1 or params[0].len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"SUCCESSOR"}, "Usage: SUCCESSOR <#channel> SHOW|SET <account>|CLEAR");
            return;
        }
        const channel = params[0];
        const action = if (params.len >= 2) params[1] else "SHOW";

        if (std.ascii.eqlIgnoreCase(action, "SHOW")) {
            var sb: [160]u8 = undefined;
            var nb: [256]u8 = undefined;
            const msg = if (svc.channelSuccessorGet(channel, &sb)) |acct|
                std.fmt.bufPrint(&nb, "SUCCESSOR: {s} successor is {s}", .{ channel, acct }) catch return
            else
                std.fmt.bufPrint(&nb, "SUCCESSOR: {s} has no successor", .{channel}) catch return;
            try self.noticeTo(conn, msg);
            return;
        }

        // SET/CLEAR are founder-gated (operators may always manage).
        const is_founder = blk: {
            const a = conn.session.account() orelse break :blk false;
            const lvl = (svc.channelAccessLevelFor(channel, a) catch break :blk false) orelse break :blk false;
            break :blk lvl == .founder;
        };
        if (!is_founder and !conn.session.isOper()) {
            try self.failReply(conn, "SUCCESSOR", "NOT_FOUNDER", "Only the channel founder may set its successor");
            return;
        }

        if (std.ascii.eqlIgnoreCase(action, "CLEAR")) {
            svc.channelSuccessorClear(channel) catch {};
            try self.noticeTo(conn, "SUCCESSOR: cleared");
            return;
        }
        if (std.ascii.eqlIgnoreCase(action, "SET")) {
            if (params.len < 3 or params[2].len == 0) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"SUCCESSOR"}, "Usage: SUCCESSOR <#channel> SET <account>");
                return;
            }
            const account = params[2];
            _ = svc.accountInfo(account) catch {
                try self.failReply(conn, "SUCCESSOR", "ACCOUNT_UNKNOWN", "No such account");
                return;
            };
            svc.channelSuccessorSet(channel, account) catch {
                try self.failReply(conn, "SUCCESSOR", "INVALID_VALUE", "Could not set successor");
                return;
            };
            var nb: [256]u8 = undefined;
            const msg = std.fmt.bufPrint(&nb, "SUCCESSOR: {s} successor set to {s}", .{ channel, account }) catch return;
            try self.noticeTo(conn, msg);
            self.publishOperEvent(.service, .notice, msg) catch {};
            return;
        }
        try self.failReply(conn, "SUCCESSOR", "INVALID_SUBCOMMAND", "Use SHOW, SET <account>, or CLEAR");
    }

    /// After an account is dropped, hand each channel it founded to that channel's
    /// configured successor (svc_successor.decideFounderSuccession with the stored
    /// successor). Channels with no successor are left as-is. Best-effort.
    fn promoteSuccessorsForDroppedFounder(self: *LinuxServer, dropped_account: []const u8) void {
        const svc = self.account_services orelse return;
        // Collect channels founded by the dropped account (can't transfer inside
        // the services-locked iteration, so snapshot names first).
        var founded: [64][128]u8 = undefined;
        var founded_len: [64]u8 = undefined;
        var n: usize = 0;
        const Ctx = struct {
            founded: *[64][128]u8,
            founded_len: *[64]u8,
            n: *usize,
        };
        var ctx = Ctx{ .founded = &founded, .founded_len = &founded_len, .n = &n };
        svc.channelsForAccount(dropped_account, &ctx, struct {
            fn cb(c: *Ctx, channel: []const u8, level: services_mod.AccessLevel) void {
                if (level != .founder) return;
                if (c.n.* >= c.founded.len or channel.len > 128) return;
                @memcpy(c.founded[c.n.*][0..channel.len], channel);
                c.founded_len[c.n.*] = @intCast(channel.len);
                c.n.* += 1;
            }
        }.cb);

        var scratch: [1024]u8 = undefined;
        for (0..n) |i| {
            const channel = founded[i][0..founded_len[i]];
            var sb: [160]u8 = undefined;
            const successor = svc.channelSuccessorGet(channel, &sb) orelse continue;
            const decision = svc_successor.decideFounderSuccession(.{
                .channel = channel,
                .founder = dropped_account,
                .reason = .dropped,
                .configured_successor = successor,
            });
            switch (decision) {
                .transfer => |t| {
                    _ = svc.transferChannel(channel, dropped_account, t.new_founder, &scratch) catch continue;
                    svc.channelSuccessorClear(channel) catch {};
                    var nb: [320]u8 = undefined;
                    const note = std.fmt.bufPrint(&nb, "SUCCESSOR: {s} handed to {s} (founder {s} dropped)", .{ channel, t.new_founder, dropped_account }) catch continue;
                    self.publishOperEvent(.oper_action, .notice, note) catch {};
                },
                .mark_for_deletion => {}, // no successor eligible; leave the channel as-is
            }
        }
    }

    /// `ACCOUNTINFO [account]` — report account name + flags (self if omitted).
    pub fn handleAccountInfo(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const svc = self.account_services orelse return self.failReply(conn, "ACCOUNTINFO", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        const target = if (parsed.param_count >= 1 and parsed.paramSlice()[0].len != 0)
            parsed.paramSlice()[0]
        else
            (conn.session.account() orelse {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"ACCOUNTINFO"}, "Not logged in; specify an account");
                return;
            });
        const result = svc.accountInfo(target) catch {
            try self.failReply(conn, "ACCOUNTINFO", "ACCOUNT_UNKNOWN", "No such account");
            return;
        };
        const info = result.account_info;
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(
            &buf,
            ":{s} NOTICE {s} :account={s} flags={d} suspended={} forbidden={} noexpire={}\r\n",
            .{
                self.serverName(),
                conn.session.displayName(),
                info.name.asSlice(),
                info.flags,
                (info.flags & services_mod.account_flag_suspended) != 0,
                (info.flags & services_mod.account_flag_forbidden) != 0,
                (info.flags & services_mod.account_flag_noexpire) != 0,
            },
        ) catch return;
        try appendToConn(conn, line);
    }

    /// `ACCOUNT <SUSPEND|UNSUSPEND|FORBID|UNFORBID|NOEXPIRE|INFO> <account>`
    /// — operator account lifecycle administration. The registry gates this to
    /// opers; this handler requires the narrower `service_admin` privilege.
    pub fn handleAccountAdmin(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.hasPriv(.service_admin)) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission denied (service_admin required)");
            return;
        }
        const svc = self.account_services orelse return self.failReply(conn, "ACCOUNT", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        if (parsed.param_count < 2) {
            try self.failReply(conn, "ACCOUNT", "NEED_MORE_PARAMS", "Usage: ACCOUNT <SUSPEND|UNSUSPEND|FORBID|UNFORBID|NOEXPIRE|INFO> <account> [on|off]");
            return;
        }

        const p = parsed.paramSlice();
        const sub = p[0];
        const target = p[1];
        var scratch: [1024]u8 = undefined;

        if (std.ascii.eqlIgnoreCase(sub, "SUSPEND")) {
            const info = svc.setAccountSuspended(target, true, &scratch) catch return self.failReply(conn, "ACCOUNT", "ACCOUNT_UNKNOWN", "No such account");
            return self.noticeAccountAdmin(conn, "SUSPEND", info);
        }
        if (std.ascii.eqlIgnoreCase(sub, "UNSUSPEND")) {
            const info = svc.setAccountSuspended(target, false, &scratch) catch return self.failReply(conn, "ACCOUNT", "ACCOUNT_UNKNOWN", "No such account");
            return self.noticeAccountAdmin(conn, "UNSUSPEND", info);
        }
        if (std.ascii.eqlIgnoreCase(sub, "FORBID")) {
            const info = svc.setAccountForbidden(target, true, &scratch) catch |err| {
                return self.failReply(conn, "ACCOUNT", accountAdminFailCode(err), "Could not forbid account");
            };
            return self.noticeAccountAdmin(conn, "FORBID", info);
        }
        if (std.ascii.eqlIgnoreCase(sub, "UNFORBID")) {
            const info = svc.setAccountForbidden(target, false, &scratch) catch |err| {
                return self.failReply(conn, "ACCOUNT", accountAdminFailCode(err), "Could not unforbid account");
            };
            return self.noticeAccountAdmin(conn, "UNFORBID", info);
        }
        if (std.ascii.eqlIgnoreCase(sub, "NOEXPIRE")) {
            const enabled = if (parsed.param_count >= 3)
                parseOnOff(p[2]) orelse return self.failReply(conn, "ACCOUNT", "INVALID_VALUE", "NOEXPIRE value must be on or off")
            else
                true;
            const info = svc.setAccountNoExpire(target, enabled, &scratch) catch |err| {
                return self.failReply(conn, "ACCOUNT", accountAdminFailCode(err), "Could not update account");
            };
            return self.noticeAccountAdmin(conn, if (enabled) "NOEXPIRE on" else "NOEXPIRE off", info);
        }
        if (std.ascii.eqlIgnoreCase(sub, "INFO")) {
            const info = svc.adminAccountInfo(target) catch |err| {
                return self.failReply(conn, "ACCOUNT", accountAdminFailCode(err), "No such account");
            };
            return self.noticeAccountAdmin(conn, "INFO", info);
        }

        try self.failReply(conn, "ACCOUNT", "INVALID_SUBCOMMAND", "Use SUSPEND, UNSUSPEND, FORBID, UNFORBID, NOEXPIRE, or INFO");
    }

    fn accountAdminFailCode(err: anyerror) []const u8 {
        return switch (err) {
            error.NotFound => "ACCOUNT_UNKNOWN",
            error.InvalidName => "BAD_ACCOUNT_NAME",
            error.BufferTooSmall => "TEMPORARILY_UNAVAILABLE",
            else => "TEMPORARILY_UNAVAILABLE",
        };
    }

    fn parseOnOff(value: []const u8) ?bool {
        if (std.ascii.eqlIgnoreCase(value, "on")) return true;
        if (std.ascii.eqlIgnoreCase(value, "off")) return false;
        return null;
    }

    fn noticeAccountAdmin(self: *LinuxServer, conn: *ConnState, action: []const u8, info: services_mod.AccountAdminInfo) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(
            &buf,
            ":{s} NOTICE {s} :ACCOUNT {s} {s} registered={} flags={d} suspended={} forbidden={} noexpire={}\r\n",
            .{
                self.serverName(),
                conn.session.displayName(),
                action,
                info.name.asSlice(),
                info.registered,
                info.flags,
                info.suspended(),
                info.forbidden(),
                info.noexpire(),
            },
        ) catch return;
        try appendToConn(conn, line);
    }

    /// `SASLINFO` — report the SASL mechanisms this server accepts and the
    /// caller's current authentication state. Read-only; available to anyone.
    pub fn handleSaslInfo(self: *LinuxServer, conn: *ConnState) !void {
        var mech_buf: [128]u8 = undefined;
        var mech_len: usize = 0;
        if (conn.session.sasl_plain != null) appendSaslInfoMech(&mech_buf, &mech_len, "PLAIN") catch return;
        if (conn.session.sasl_external != null) appendSaslInfoMech(&mech_buf, &mech_len, "EXTERNAL") catch return;
        if (conn.session.sasl_scram256 != null and conn.session.sasl_server_nonce.len != 0) appendSaslInfoMech(&mech_buf, &mech_len, "SCRAM-SHA-256") catch return;
        if (conn.session.sasl_scram512 != null and conn.session.sasl_server_nonce.len != 0) appendSaslInfoMech(&mech_buf, &mech_len, "SCRAM-SHA-512") catch return;
        if (conn.session.sasl_scram512 != null and conn.session.sasl_server_nonce.len != 0 and conn.session.tls_exporter != null) appendSaslInfoMech(&mech_buf, &mech_len, "SCRAM-SHA-512-PLUS") catch return;
        if (conn.session.sasl_session_token != null) appendSaslInfoMech(&mech_buf, &mech_len, "SESSION-TOKEN") catch return;
        if (conn.session.sasl_oauthbearer != null) appendSaslInfoMech(&mech_buf, &mech_len, "OAUTHBEARER") catch return;
        if (conn.session.sasl_allow_anonymous) appendSaslInfoMech(&mech_buf, &mech_len, "ANONYMOUS") catch return;
        const mechs = if (mech_len == 0) "(none configured)" else mech_buf[0..mech_len];
        var buf: [default_reply_bytes]u8 = undefined;
        const m = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :SASL mechanisms: {s}\r\n", .{ self.serverName(), conn.session.displayName(), mechs }) catch return;
        try emitReplyLine(conn, m);
        var buf2: [default_reply_bytes]u8 = undefined;
        const status = if (conn.session.account()) |acct|
            std.fmt.bufPrint(&buf2, ":{s} NOTICE {s} :You are logged in as {s}\r\n", .{ self.serverName(), conn.session.displayName(), acct }) catch return
        else if (conn.session.sasl_guest)
            std.fmt.bufPrint(&buf2, ":{s} NOTICE {s} :You authenticated as an anonymous guest with no registered-account privileges\r\n", .{ self.serverName(), conn.session.displayName() }) catch return
        else
            std.fmt.bufPrint(&buf2, ":{s} NOTICE {s} :You are not logged in\r\n", .{ self.serverName(), conn.session.displayName() }) catch return;
        try emitReplyLine(conn, status);
    }

    fn issueSessionTokenNotice(self: *LinuxServer, conn: *ConnState, command: []const u8) !void {
        conn.session.sasl_issue_session_token = false;
        if (!conn.is_tls) {
            if (std.ascii.eqlIgnoreCase(command, "SESSIONTOKEN")) {
                var fail_buf: [default_reply_bytes]u8 = undefined;
                const fail = std.fmt.bufPrint(
                    &fail_buf,
                    "FAIL SESSIONTOKEN INSECURE_TRANSPORT :Session tokens require a secure connection\r\n",
                    .{},
                ) catch return;
                try appendToConn(conn, fail);
            }
            return;
        }
        const svc = self.account_services orelse return self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        const account = conn.session.account() orelse return self.failReply(conn, command, "NOT_LOGGED_IN", "Log in before requesting a session token");
        // Durable expiry and the SASL verifier share the Unix clock domain.
        // Refuse an unavailable clock before rotating any stored credential.
        const wall_ms = if (self.reactor) |r|
            r.wallMillis()
        else
            platform.realtimeMillisChecked() orelse return self.failReply(conn, command, "TOKEN_ISSUE_FAILED", "Could not issue session token");
        const now_unix = @divTrunc(wall_ms, 1000);
        if (now_unix <= 0) return self.failReply(conn, command, "TOKEN_ISSUE_FAILED", "Could not issue session token");
        const issued = svc.issueSessionToken(account, now_unix) catch return self.failReply(conn, command, "TOKEN_ISSUE_FAILED", "Could not issue session token");
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(
            &buf,
            ":{s} NOTICE {s} :SESSIONTOKEN {s} {s} expires={d}\r\n",
            .{ self.serverName(), conn.session.displayName(), issued.account.asSlice(), issued.tokenSlice(), issued.expires_unix },
        ) catch return;
        try appendToConn(conn, line);
    }

    pub fn handleSessionToken(self: *LinuxServer, conn: *ConnState) !void {
        try self.issueSessionTokenNotice(conn, "SESSIONTOKEN");
    }

    /// `CERTADD` — bind the TLS client-certificate fingerprint presented on this
    /// connection to the caller's logged-in account, enabling future password-less
    /// SASL EXTERNAL logins. Requires both an account login and a presented cert.
    pub fn handleCertAdd(self: *LinuxServer, conn: *ConnState) !void {
        if (!self.authenticationAvailable())
            return self.failReply(conn, "CERTADD", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        const svc = self.account_services orelse return self.failReply(conn, "CERTADD", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        const account = conn.session.account() orelse return self.failReply(conn, "CERTADD", "NOT_LOGGED_IN", "Log in before binding a certificate");
        const fp = conn.session.tls_certfp orelse return self.failReply(conn, "CERTADD", "NO_CLIENT_CERT", "No TLS client certificate presented on this connection");
        svc.bindCertfp(account, fp) catch return self.failReply(conn, "CERTADD", "CERT_ADD_FAILED", "Could not bind certificate");
        var buf: [default_reply_bytes]u8 = undefined;
        const m = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :Certificate fingerprint {s} bound to {s}\r\n", .{ self.serverName(), conn.session.displayName(), fp, account }) catch return;
        try emitReplyLine(conn, m);
    }

    pub fn handleCertList(self: *LinuxServer, conn: *ConnState) !void {
        const svc = self.account_services orelse return self.failReply(conn, "CERTLIST", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        const account = conn.session.account() orelse return self.failReply(conn, "CERTLIST", "NOT_LOGGED_IN", "Log in before listing certificates");
        var fps_buf: [16][]const u8 = undefined;
        const fps = svc.listCertfps(account, fps_buf[0..]) catch return self.failReply(conn, "CERTLIST", "CERT_LIST_FAILED", "Could not list certificates");
        if (fps.len == 0) {
            try self.noticeTo(conn, "CERTLIST: no certificate fingerprints bound");
            return;
        }
        for (fps) |fp| {
            var buf: [default_reply_bytes]u8 = undefined;
            const m = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :CERTLIST {s}\r\n", .{ self.serverName(), conn.session.displayName(), fp }) catch return;
            try emitReplyLine(conn, m);
        }
    }

    pub fn handleCertDel(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.authenticationAvailable())
            return self.failReply(conn, "CERTDEL", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        const svc = self.account_services orelse return self.failReply(conn, "CERTDEL", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        const account = conn.session.account() orelse return self.failReply(conn, "CERTDEL", "NOT_LOGGED_IN", "Log in before deleting a certificate");
        if (parsed.param_count < 1) {
            try self.failReply(conn, "CERTDEL", "NEED_MORE_PARAMS", "Usage: CERTDEL <fingerprint>");
            return;
        }
        const fp = parsed.paramSlice()[0];
        svc.deleteCertfp(account, fp) catch |err| {
            const code: []const u8 = switch (err) {
                error.Forbidden => "CERT_NOT_OWNED",
                error.NotFound => "CERT_NOT_FOUND",
                else => "CERT_DEL_FAILED",
            };
            return self.failReply(conn, "CERTDEL", code, "Certificate fingerprint is not bound to your account");
        };
        var buf: [default_reply_bytes]u8 = undefined;
        const m = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :Certificate fingerprint {s} removed from {s}\r\n", .{ self.serverName(), conn.session.displayName(), fp, account }) catch return;
        try emitReplyLine(conn, m);
    }

    fn keyTransReply(self: *LinuxServer, conn: *ConnState, body: []const u8) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const text = std.fmt.bufPrint(&buf, "KEYTRANS {s}", .{body}) catch return;
        try self.noticeTo(conn, text);
    }

    fn e2eeKeyReply(self: *LinuxServer, conn: *ConnState, body: []const u8) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const text = std.fmt.bufPrint(&buf, "E2EEKEY {s}", .{body}) catch return;
        try self.noticeTo(conn, text);
    }

    fn keyTransparencyTimestampMs(self: *const LinuxServer) i64 {
        return @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
    }

    fn localPropOriginNode(self: *const LinuxServer) u64 {
        if (self.config.node_identity) |ident| return ident.shortId();
        return self.config.node_id;
    }

    fn observationalCredentialKind(key: []const u8) ?key_transparency.CredentialKind {
        if (e2ee_policy.isDevicePropKey(key)) return .e2ee_device;
        if (account_identity.isPropKey(key)) return .identity;
        return null;
    }

    fn observationalCredentialKeyId(key: []const u8) ?[]const u8 {
        if (e2ee_policy.isDevicePropKey(key)) return key[e2ee_policy.device_prop_prefix.len..];
        if (account_identity.isPropKey(key)) return key[account_identity.prop_prefix.len..];
        return null;
    }

    fn observationalBindMaterial(
        kind: key_transparency.CredentialKind,
        value: []const u8,
        identity_key_buf: *[account_identity.public_key_len]u8,
    ) []const u8 {
        if (kind == .identity) {
            if (account_identity.parseClaimValue(value)) |claim| {
                identity_key_buf.* = claim.public_key;
                return identity_key_buf;
            }
        }
        return value;
    }

    /// Best-effort observation of an exact `e2ee.device.*` or `identity.key.*`
    /// user PROP after the mutation has already succeeded. Member, residence,
    /// and unrelated keys are ignored. Never changes the caller's reply.
    fn observeUserCredentialProp(
        self: *LinuxServer,
        present: bool,
        store_kind: ircx_prop_store.EntityKind,
        account: []const u8,
        key: []const u8,
        value: []const u8,
        hlc: u64,
        origin_node: u64,
        origin_pubkey: []const u8,
    ) void {
        if (store_kind != .user) return;
        const kind = observationalCredentialKind(key) orelse return;
        const key_id = observationalCredentialKeyId(key) orelse return;
        var identity_key_buf: [account_identity.public_key_len]u8 = undefined;
        const material = if (present)
            observationalBindMaterial(kind, value, &identity_key_buf)
        else
            "";
        self.observeCredentialFact(
            account,
            kind,
            if (present) .bind else .delete,
            key_id,
            material,
            hlc,
            origin_node,
            origin_pubkey,
        );
    }

    fn observeLocalUserCredentialProp(
        self: *LinuxServer,
        present: bool,
        store_kind: ircx_prop_store.EntityKind,
        account: []const u8,
        key: []const u8,
        value: []const u8,
        hlc: u64,
    ) void {
        self.observeUserCredentialProp(
            present,
            store_kind,
            account,
            key,
            value,
            hlc,
            self.localPropOriginNode(),
            "",
        );
    }

    /// Record one node-local observation after a PROP mutation has already
    /// succeeded. Never rolls back the prop and never holds a prop lock.
    fn observeCredentialFact(
        self: *LinuxServer,
        account: []const u8,
        kind: key_transparency.CredentialKind,
        action: key_transparency.Action,
        key_id: []const u8,
        material: []const u8,
        hlc: u64,
        origin_node: u64,
        origin_pubkey: []const u8,
    ) void {
        const svc = self.account_services orelse return;
        svc.observeKeyTransparencyFact(
            account,
            kind,
            action,
            key_id,
            material,
            key_transparency.observationTimestampMs(hlc),
            .{
                .hlc = hlc,
                .origin_node = origin_node,
                .origin_pubkey = origin_pubkey,
            },
        );
    }

    const E2eeDeviceValue = struct {
        algorithm: []const u8,
        public_key: []const u8,
    };

    fn splitE2eeDeviceValue(value: []const u8) ?E2eeDeviceValue {
        const colon = std.mem.indexOfScalar(u8, value, ':') orelse return null;
        if (colon == 0 or colon + 1 >= value.len) return null;
        const algorithm = value[0..colon];
        const public_key = value[colon + 1 ..];
        if (!e2ee_policy.validAlgorithm(algorithm) or !e2ee_policy.validPublicKey(public_key)) return null;
        return .{ .algorithm = algorithm, .public_key = public_key };
    }

    const E2eeGroupDeliveryOutcome = enum {
        accepted,
        duplicate,
        retry,
        rejected,
    };

    fn collectE2eeGroupOutboxPeers(
        self: *LinuxServer,
        excluded_peer: ?u64,
    ) std.mem.Allocator.Error![]u64 {
        var peers: std.ArrayList(u64) = .empty;
        errdefer peers.deinit(self.allocator);
        // A pinned direct-neighbor roster is event-time custody authority even
        // while a peer is disconnected. Omitting a down peer here would turn
        // RAM-only persistence into mesh fire-and-forget: there would be no row
        // left for the reconnect retry API to drive.
        if (self.relay_v2_required_nodes.len != 0) {
            for (self.relay_v2_required_nodes) |peer| {
                if (peer == self.config.node_id or
                    (excluded_peer != null and peer == excluded_peer.?)) continue;
                try peers.append(self.allocator, peer);
            }
            return peers.toOwnedSlice(self.allocator);
        }

        // TOFU has no configured offline membership to preserve. Its bounded
        // fallback may custody only peers authenticated and eligible at this
        // exact admission instant; operators that require partition recovery
        // must pin the direct-neighbor trust-root set above.
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                if (!entry.value.isActiveMeshPeer()) continue;
                const link = entry.value.s2s_secured orelse continue;
                if (!link.established() or !link.supportsE2eeGroup()) continue;
                const peer = link.remoteNodeId() orelse continue;
                if (peer == 0 or peer == self.config.node_id or
                    (excluded_peer != null and peer == excluded_peer.?)) continue;
                var duplicate = false;
                for (peers.items) |known| {
                    if (known == peer) {
                        duplicate = true;
                        break;
                    }
                }
                if (!duplicate) try peers.append(self.allocator, peer);
            }
        }
        return peers.toOwnedSlice(self.allocator);
    }

    fn e2eeGroupDirectNeighbor(self: *LinuxServer, peer: u64) bool {
        if (peer == 0 or peer == self.config.node_id) return false;
        if (self.relay_v2_required_nodes.len != 0) {
            for (self.relay_v2_required_nodes) |required| {
                if (required == peer) return true;
            }
            return false;
        }
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                if (!entry.value.isActiveMeshPeer()) continue;
                const link = entry.value.s2s_secured orelse continue;
                if (link.established() and link.supportsE2eeGroup() and
                    link.remoteNodeId() == peer) return true;
            }
        }
        return false;
    }

    fn replayE2eeGroupWireToPeer(
        self: *LinuxServer,
        peer: u64,
        wire: []const u8,
    ) bool {
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                if (!entry.value.isActiveMeshPeer()) continue;
                const link = entry.value.s2s_secured orelse continue;
                if (!link.established() or !link.supportsE2eeGroup() or
                    link.remoteNodeId() != peer) continue;
                // The retained exact-wire API deliberately bypasses the
                // reflection cache. A lost receipt must remain recoverable.
                // A prior attempt may already own one complete encrypted record
                // in the link while its SendQ is full. Page that record first;
                // never append another retry behind congestion on every timer
                // tick.
                if (!self.flushSecuredS2sOutboundTo(entry.id, link)) return false;
                link.replayRetainedE2eeGroupWire(wire) catch return false;
                if (!self.flushSecuredS2sOutboundTo(entry.id, link)) return false;
                return true;
            }
        }
        return false;
    }

    fn collectE2eeGroupRetryWork(
        self: *LinuxServer,
        work: *[e2ee_group_retry_frame_budget]E2eeGroupRetryWork,
    ) usize {
        lockSpin(&self.e2ee_group_mesh_mu);
        defer self.e2ee_group_mesh_mu.unlock();
        const items = self.e2ee_group_mesh_authority.retryItems();
        if (items.len == 0) {
            self.e2ee_group_retry_cursor = 0;
            return 0;
        }
        var cursor = self.e2ee_group_retry_cursor % items.len;
        var count: usize = 0;
        const limit = @min(items.len, work.len);
        while (count < limit) : (count += 1) {
            const item = items[cursor];
            const wire = self.allocator.dupe(u8, item.wire) catch break;
            work[count] = .{
                .peer = item.peer,
                .relay_id = item.relay_id,
                .wire = wire,
            };
            cursor = (cursor + 1) % items.len;
        }
        self.e2ee_group_retry_cursor = cursor;
        return count;
    }

    fn retryE2eeGroupCustody(self: *LinuxServer) void {
        var work: [e2ee_group_retry_frame_budget]E2eeGroupRetryWork = undefined;
        const work_len = self.collectE2eeGroupRetryWork(&work);
        defer for (work[0..work_len]) |item| self.allocator.free(item.wire);
        for (work[0..work_len]) |item| {
            _ = item.relay_id;
            _ = self.replayE2eeGroupWireToPeer(item.peer, item.wire);
        }
        self.retryE2eeGroupReceipts();
    }

    fn driveAcceptedE2eeGroupCustody(self: *LinuxServer) void {
        if (current_reactor == &self.reactors[0]) {
            self.retryE2eeGroupCustody();
        } else if (self.reactors[0].wake) |*wake| {
            self.e2ee_group_retry_requested.store(true, .release);
            wake.wake();
        }
    }

    fn markE2eeGroupReceiptAttempt(
        self: *LinuxServer,
        peer: u64,
        relay_id: e2ee_group_relay.RelayId,
        now_ms: u64,
    ) void {
        lockSpin(&self.e2ee_group_mesh_mu);
        defer self.e2ee_group_mesh_mu.unlock();
        for (self.e2ee_group_mesh_authority.receiptItems()) |receipt| {
            if (receipt.peer != peer or
                !std.mem.eql(u8, &receipt.relay_id, &relay_id)) continue;
            const next_attempt = receipt.attempts +| 1;
            const shift: u5 = @intCast(@min(next_attempt, 5));
            _ = self.e2ee_group_mesh_authority.markReceiptAttempt(
                peer,
                relay_id,
                now_ms +| (e2ee_group_initial_retry_ms << shift),
            ) catch false;
            return;
        }
    }

    fn sendE2eeGroupAckOnLink(
        self: *LinuxServer,
        conn: *ConnState,
        link: *secured_s2s_link.SecuredLink,
        relay_id: e2ee_group_relay.RelayId,
    ) bool {
        if (!conn.ownsActiveMeshLink(link)) return false;
        if (!link.established() or !link.supportsE2eeGroup()) return false;
        // Preflight any complete ciphertext retained by a prior congested ACK.
        // With a full healthy SendQ, one receipt may remain link-owned, but a
        // duplicate replay cannot append an unbounded receipt train behind it.
        if (!self.flushMeshBurstStage(conn)) return false;
        // `sendE2eeGroupAck` first commits a complete encrypted record into the
        // SecuredLink-owned outbound buffer. Paging may move it into SendQ; on
        // backpressure it remains link-owned. Either way no successful return
        // depends on the socket having already written the bytes.
        link.sendE2eeGroupAck(relay_id) catch return false;
        _ = self.flushMeshBurstStage(conn);
        return true;
    }

    fn sendE2eeGroupAckToPeer(
        self: *LinuxServer,
        peer: u64,
        relay_id: e2ee_group_relay.RelayId,
    ) bool {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, slot_index| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established() or !link.supportsE2eeGroup()) continue;
                if ((link.remoteNodeId() orelse continue) != peer) continue;
                const peer_id = slotClientId(reactor, slot_index, slot.gen);
                if (!self.flushSecuredS2sOutboundTo(peer_id, link)) return false;
                link.sendE2eeGroupAck(relay_id) catch return false;
                // Encoding the authenticated ACK is the send attempt. Even if
                // SendQ is now full, the complete record remains link-owned and
                // the next due pass will preflush instead of appending behind it.
                _ = self.flushSecuredS2sOutboundTo(peer_id, link);
                return true;
            }
        }
        return false;
    }

    fn sendE2eeGroupAckConfirmToPeer(
        self: *LinuxServer,
        peer: u64,
        relay_id: e2ee_group_relay.RelayId,
    ) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, slot_index| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established() or !link.supportsE2eeGroupAckConfirm()) continue;
                if ((link.remoteNodeId() orelse continue) != peer) continue;
                const peer_id = slotClientId(reactor, slot_index, slot.gen);
                if (!self.flushSecuredS2sOutboundTo(peer_id, link)) return;
                link.sendE2eeGroupAckConfirm(relay_id) catch return;
                _ = self.flushSecuredS2sOutboundTo(peer_id, link);
                return;
            }
        }
    }

    fn retryE2eeGroupReceipts(self: *LinuxServer) void {
        const now_ms = self.meshWallMs();
        var receipts: [e2ee_group_retry_frame_budget]e2ee_group_mesh_authority.Receipt = undefined;
        lockSpin(&self.e2ee_group_mesh_mu);
        const receipt_len = self.e2ee_group_mesh_authority.collectDueReceipts(
            now_ms,
            &receipts,
        );
        self.e2ee_group_mesh_mu.unlock();

        for (receipts[0..receipt_len]) |receipt| {
            if (!self.sendE2eeGroupAckToPeer(receipt.peer, receipt.relay_id))
                continue;
            self.markE2eeGroupReceiptAttempt(
                receipt.peer,
                receipt.relay_id,
                now_ms,
            );
        }
    }

    fn e2eeGroupControlRecord(
        record: e2ee_group_relay.RelayRecord,
    ) e2ee_group_control.Record {
        return .{
            .channel = record.channel,
            .kind = record.kind,
            .from_device = record.from_device,
            .to_account = if (record.to_account.len == 0) null else record.to_account,
            .to_device = if (record.to_device.len == 0) null else record.to_device,
            .payload = record.payload,
        };
    }

    fn renderE2eeGroupLineFromPrefix(
        prefix: []const u8,
        from_account: []const u8,
        record: e2ee_group_control.Record,
        out: []u8,
    ) ServerError![]const u8 {
        return e2ee_group_delivery.renderClientLine(prefix, from_account, record, out) catch |err| switch (err) {
            error.OutputTooSmall => error.OutputTooSmall,
            error.InvalidRecord => error.OutputTooSmall,
        };
    }

    fn deliverE2eeGroupLine(
        self: *LinuxServer,
        recipients: []const client_model.ClientId,
        line: []const u8,
    ) usize {
        self.beginWakeBatch();
        defer self.endWakeBatch();
        var delivered: usize = 0;
        for (recipients) |id| {
            if (self.enqueueDeliveryMaybeClose(id, line, false, "Client quit") == .delivered)
                delivered += 1;
        }
        return delivered;
    }

    /// Authorize one already origin-verified immutable control against the
    /// receiver's converged residence, membership, account, and device facts.
    /// Every fallible recipient/render/custody/receipt reservation precedes the
    /// single authority commit. Only `.accepted` publishes local delivery; an
    /// exact duplicate reserves or refreshes only its authenticated ingress
    /// receipt, never custody, and earns another hop ACK.
    fn deliverE2eeGroup(
        self: *LinuxServer,
        record: e2ee_group_relay.RelayRecord,
        wire: []const u8,
        via_peer: u64,
    ) E2eeGroupDeliveryOutcome {
        if (!self.e2eeGroupDirectNeighbor(via_peer)) return .rejected;

        // Authenticate first, then perform an allocation-free replay lookup
        // before consulting receiver-wall or mutable residence/membership/device
        // state. An exact previously accepted identity is sufficient to re-ACK
        // a lost receipt even after the receiver's wall clock steps backward.
        lockSpin(&self.e2ee_group_mesh_mu);
        const authenticated = self.e2ee_group_mesh_authority.authenticateRecord(
            record,
        ) catch {
            self.e2ee_group_mesh_mu.unlock();
            return .retry;
        };
        const verified = switch (authenticated) {
            .verified => |identity| identity,
            .origin_mismatch, .bad_signature, .invalid_semantic => {
                self.e2ee_group_mesh_mu.unlock();
                return .rejected;
            },
        };
        const identity_lookup = self.e2ee_group_mesh_authority.probeIdentity(verified);
        self.e2ee_group_mesh_mu.unlock();
        switch (identity_lookup) {
            .duplicate => {
                // Reserve/refresh only the authenticated ingress receipt in the
                // same authority lane. Custody membership stays fixed at first
                // acceptance: recomputing peers here would recreate an already
                // ACKed edge and make a valid A-B-C reflection cycle immortal.
                lockSpin(&self.e2ee_group_mesh_mu);
                const duplicate = self.e2ee_group_mesh_authority.admitAuthorizedWithCustodyAndIngress(
                    verified,
                    &.{},
                    wire,
                    via_peer,
                    self.meshWallMs() +| e2ee_group_initial_retry_ms,
                ) catch {
                    self.e2ee_group_mesh_mu.unlock();
                    return .retry;
                };
                self.e2ee_group_mesh_mu.unlock();
                switch (duplicate.admission) {
                    .duplicate => {},
                    .origin_capacity => return .retry,
                    .accepted, .equivocation, .retired => return .rejected,
                }
                self.driveAcceptedE2eeGroupCustody();
                return .duplicate;
            },
            .equivocation, .retired => return .rejected,
            .unseen => {},
        }
        if (e2ee_group_mesh_authority.isFutureSkewed(
            verified,
            self.meshWallMs(),
            mesh_clock_mod.default_max_future_skew_ms,
        ))
            return .retry;

        const source_nick = relaySourceNickFromPrefix(record.source_prefix) orelse
            return .rejected;
        const home = self.meshNickHomeNode(source_nick) orelse return .retry;
        if (home != record.origin_node) return .rejected;
        const residence_account = self.trustedRemoteAccountAtNode(
            source_nick,
            record.origin_node,
        ) orelse return .retry;
        if (!std.ascii.eqlIgnoreCase(residence_account, record.account))
            return .rejected;
        if (!self.remoteMemberOfChannelAtNode(
            record.channel,
            source_nick,
            record.origin_node,
        )) return .retry;
        if (!self.e2eeDeviceOwnedByAccount(record.account, record.from_device))
            return .retry;
        if (record.kind == .welcome and
            !self.e2eeDeviceOwnedByAccount(record.to_account, record.to_device))
            return .retry;

        const control = e2eeGroupControlRecord(record);
        var recipients: std.ArrayList(client_model.ClientId) = .empty;
        defer recipients.deinit(self.allocator);
        self.collectE2eeGroupRecipients(control, &recipients) catch return .retry;
        var line_buf: [e2ee_group_max_line_bytes]u8 = undefined;
        const line = renderE2eeGroupLineFromPrefix(
            record.source_prefix,
            record.account,
            control,
            &line_buf,
        ) catch return .rejected;
        const peers = self.collectE2eeGroupOutboxPeers(via_peer) catch return .retry;
        defer self.allocator.free(peers);
        var prepared_delivery = self.prepareE2eeGroupAttachmentDeliveryBatch(
            recipients.items,
            verified.relay_id,
            line,
        ) catch return .retry;
        defer prepared_delivery.deinit();

        // attachment_delivery_mu -> e2ee_group_mesh_mu. Authority performs all
        // of its fallible preparation before its own no-fail publication; while
        // both lanes remain locked, the accepted arm joins ADS1 to that same
        // externally indivisible cut before any caller can emit ACK.
        lockSpin(&self.e2ee_group_mesh_mu);
        const admitted = self.e2ee_group_mesh_authority.admitAuthorizedWithCustodyAndIngress(
            verified,
            peers,
            wire,
            via_peer,
            self.meshWallMs() +| e2ee_group_initial_retry_ms,
        ) catch {
            self.e2ee_group_mesh_mu.unlock();
            return .retry;
        };
        switch (admitted.admission) {
            .accepted => prepared_delivery.commit(),
            else => {},
        }
        self.e2ee_group_mesh_mu.unlock();

        switch (admitted.admission) {
            .accepted => {
                prepared_delivery.release();
                self.driveE2eeGroupAttachmentDeliveries(recipients.items);
                self.driveAcceptedE2eeGroupCustody();
                return .accepted;
            },
            .duplicate => return .rejected,
            .origin_capacity => return .retry,
            .equivocation, .retired => return .rejected,
        }
    }

    fn drainE2eeGroup(
        self: *LinuxServer,
        conn: *ConnState,
        link: *secured_s2s_link.SecuredLink,
    ) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const peer = link.remoteNodeId() orelse return;
        const inbound = link.takeInboundE2eeGroup() catch return;
        defer self.allocator.free(inbound);
        for (inbound) |*item| {
            defer item.deinit(self.allocator);
            if (item.via_peer != peer) {
                conn.closing = true;
                return;
            }
            switch (self.deliverE2eeGroup(item.owned.record, item.wire, peer)) {
                .accepted, .duplicate => {
                    if (self.sendE2eeGroupAckOnLink(conn, link, item.relay_id))
                        self.markE2eeGroupReceiptAttempt(
                            peer,
                            item.relay_id,
                            self.meshWallMs(),
                        );
                },
                .retry, .rejected => {},
            }
        }
    }

    fn drainE2eeGroupAcks(
        self: *LinuxServer,
        conn: *const ConnState,
        link: *secured_s2s_link.SecuredLink,
    ) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const peer = link.remoteNodeId() orelse return;
        const acks = link.takeInboundE2eeGroupAcks() catch return;
        defer self.allocator.free(acks);
        const confirms = link.takeInboundE2eeGroupAckConfirms() catch return;
        defer self.allocator.free(confirms);
        // Consume both independently bounded transport queues before rejecting
        // an authenticated-but-off-roster link. Leaving confirms queued here
        // would pin transport memory and replay the stale control on every read.
        if (!self.e2eeGroupDirectNeighbor(peer)) return;
        for (acks) |relay_id| {
            lockSpin(&self.e2ee_group_mesh_mu);
            _ = self.e2ee_group_mesh_authority.acknowledgeOutgoing(
                peer,
                relay_id,
            ) catch false;
            self.e2ee_group_mesh_mu.unlock();
            // Authenticated direct-neighbor duplicate ACKs must receive another
            // confirm after a lost ACK_CONFIRM, even after custody is gone.
            self.sendE2eeGroupAckConfirmToPeer(peer, relay_id);
        }

        for (confirms) |relay_id| {
            lockSpin(&self.e2ee_group_mesh_mu);
            _ = self.e2ee_group_mesh_authority.confirmIngress(
                peer,
                relay_id,
            ) catch false;
            self.e2ee_group_mesh_mu.unlock();
        }
    }

    fn e2eeDeviceCount(self: *LinuxServer, account: []const u8) !usize {
        const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
        var views: [ircx_prop_store.user_max_props_per_entity]ircx_prop_store.EntryView = undefined;
        const rows = try self.props.listPropsRaw(entity, &views);
        var count: usize = 0;
        for (rows) |ev| {
            if (e2ee_policy.isDevicePropKey(ev.key)) count += 1;
        }
        return count;
    }

    fn e2eeDeviceOwnedByAccount(self: *LinuxServer, account: []const u8, device: []const u8) bool {
        var key_buf: [e2ee_policy.device_prop_prefix.len + e2ee_policy.max_device_id_len]u8 = undefined;
        const key = e2ee_policy.devicePropKey(device, &key_buf) orelse return false;
        const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
        const entry = self.props.getProp(entity, key) catch return false;
        return splitE2eeDeviceValue(entry.value) != null;
    }

    fn appendE2eeGroupRecipient(
        self: *LinuxServer,
        recipients: *std.ArrayList(client_model.ClientId),
        id: client_model.ClientId,
    ) std.mem.Allocator.Error!void {
        const target = self.connFor(id) orelse return;
        if (target.closing or target.s2s != null or target.s2s_secured != null) return;
        if (!target.session.hasCap(.onyx_e2ee)) return;
        // The CAP is only a feature negotiation bit, not durable participation
        // authority. E2EEGROUP recipients must have an HSSN-tracked reusable
        // attachment so their opaque row can survive SendQ pressure, reconnect,
        // and Helix remap. Anonymous or session-cap-exhausted sockets are
        // explicitly ineligible here; they cannot veto a room's accepted event.
        if (!self.attachmentHasReusableSession(id)) return;
        try self.appendUniqueDeliveryId(recipients, id);
    }

    fn collectE2eeGroupRecipients(
        self: *LinuxServer,
        record: e2ee_group_control.Record,
        recipients: *std.ArrayList(client_model.ClientId),
    ) std.mem.Allocator.Error!void {
        if (record.kind != .welcome) {
            var members = self.world.memberIterator(record.channel) orelse return;
            while (members.next()) |member| {
                try self.appendE2eeGroupRecipient(recipients, clientIdFromWorld(member.*));
            }
            return;
        }

        // Route targeted account authority through SessionStore rather than a
        // nick lookup. One logical session may have several physical
        // attachments; every live, capable attachment in the room receives the
        // same opaque Welcome and lets its client filter by `to_device`.
        const account = record.to_account.?;
        var canonical_account_buf: [e2ee_group_control.max_account_len]u8 = undefined;
        const canonical_account = std.ascii.lowerString(canonical_account_buf[0..account.len], account);
        const sessions = try self.sessions.copySessionsAlloc(self.allocator, canonical_account);
        defer self.allocator.free(sessions);
        for (sessions) |session| {
            if (!session.attached) continue;
            const id = clientIdFromMonitor(session.client);
            const target = self.connFor(id) orelse continue;
            const live_account = target.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(live_account, account)) continue;
            if (!self.world.isMember(record.channel, worldIdFromClient(id))) continue;
            try self.appendE2eeGroupRecipient(recipients, id);
        }
    }

    fn renderE2eeGroupLine(
        conn: *const ConnState,
        record: e2ee_group_control.Record,
        out: []u8,
    ) ServerError![]const u8 {
        const from_account = conn.session.account() orelse return error.OutputTooSmall;
        var prefix_buf: [default_reply_bytes]u8 = undefined;
        const prefix = try clientPrefix(conn, &prefix_buf);
        return renderE2eeGroupLineFromPrefix(prefix, from_account, record, out);
    }

    /// Operator-only process-local activation barrier:
    ///
    ///   E2EEGROUP STATUS
    ///   E2EEGROUP OFF      (quiesce local authorship)
    ///   E2EEGROUP ON       (resume local authorship)
    ///
    /// Count-only status deliberately omits RelayIds, origin keys, signed wires,
    /// and opaque client payloads. Privilege is checked before any state read
    /// so non-operators never observe drain/peer gauges through this command.
    /// Returns false for every ordinary E2EEGROUP record so the module registry
    /// retains its established min-params / feature-gate behavior.
    fn handleE2eeGroupOperatorControl(
        self: *LinuxServer,
        conn: *ConnState,
        parsed: *const irc_line.LineView,
    ) !bool {
        if (!std.ascii.eqlIgnoreCase(parsed.command, "E2EEGROUP")) return false;
        const params = parsed.paramSlice();
        if (params.len != 1) return false;
        const sub = params[0];
        const is_status = std.ascii.eqlIgnoreCase(sub, "STATUS");
        const is_on = std.ascii.eqlIgnoreCase(sub, "ON");
        const is_off = std.ascii.eqlIgnoreCase(sub, "OFF");
        if (!is_status and !is_on and !is_off) return false;

        // Match SerpentRegistry oper/registration gates before any barrier or
        // observability side effects. Unregistered sockets never become oper.
        if (!conn.session.registered()) {
            try queueNumeric(conn, .ERR_NOTREGISTERED, &.{}, "You have not registered");
            return true;
        }
        if (!conn.session.isOper()) {
            try queueNumeric(
                conn,
                .ERR_NOPRIVILEGES,
                &.{"E2EEGROUP"},
                "Permission denied: E2EEGROUP authoring control is operator-only",
            );
            return true;
        }

        if (is_on) {
            // Re-read readiness under the same operational snapshot used by
            // metrics so ON cannot race a stale peer count against STATUS.
            const readiness = self.e2eeGroupOperationalState();
            if (!readiness.activationReady()) {
                var reason_buf: [192]u8 = undefined;
                const reason = std.fmt.bufPrint(
                    &reason_buf,
                    "Cannot enable local authoring: current-capable peers={d} required peers={d}",
                    .{ readiness.current_peers, readiness.required_peers },
                ) catch unreachable;
                try self.failReply(
                    conn,
                    "E2EEGROUP",
                    "PEERS_NOT_CURRENT",
                    reason,
                );
                return true;
            }
        }

        if (is_on or is_off) {
            const enabled = is_on;
            const prior = self.e2ee_group_local_authoring_enabled.swap(enabled, .acq_rel);
            if (prior != enabled) {
                // Log only the operator nick and the barrier transition — never
                // relay IDs, peer shortIds, or payload material.
                srvLog(
                    "onyx-server: E2EEGROUP local authoring {s} by operator {s}\n",
                    .{ if (enabled) "enabled" else "quiesced", conn.session.displayName() },
                );
                // Make the live scrape reflect the barrier transition without
                // waiting for the ordinary stats cadence.
                if (self.config.metrics_port != 0) self.refreshMetricsSnapshot();
            }
        }

        const state = self.e2eeGroupOperationalState();
        var buf: [512]u8 = undefined;
        const reply = std.fmt.bufPrint(
            &buf,
            "E2EEGROUP STATUS local_authoring={s} quiesced={d} current_peers={d} required_peers={d} activation_ready={d} custody={d} receipts={d} pending={d}",
            .{
                if (state.authoring_enabled) "ON" else "OFF",
                @as(u8, if (state.authoring_enabled) 0 else 1),
                state.current_peers,
                state.required_peers,
                @as(u8, if (state.activationReady()) 1 else 0),
                state.custody,
                state.receipts,
                state.pending,
            },
        ) catch unreachable;
        try self.noticeTo(conn, reply);
        return true;
    }

    /// Local Phase 4a E2EEGROUP admission. The opaque payload is validated and
    /// copied only into the final bounded IRC line. It is never decrypted,
    /// logged, or placed in history; mesh-enabled delivery retains only the
    /// bounded exact per-attachment ADS1 record until that SendQ accepts it.
    pub fn handleE2eeGroup(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const account = conn.session.account() orelse
            return self.failReply(conn, "E2EEGROUP", "NOT_LOGGED_IN", "Authenticate before sending group E2EE controls");
        if (!conn.ircx)
            return self.failReply(conn, "E2EEGROUP", "IRCX_REQUIRED", "Opt in with IRCX before sending group E2EE controls");
        if (!conn.session.hasCap(.onyx_e2ee))
            return self.failReply(conn, "E2EEGROUP", "CAP_REQUIRED", "Negotiate onyx/e2ee before sending group E2EE controls");
        if (!self.e2ee_group_local_authoring_enabled.load(.acquire))
            return self.warnReply(conn, "E2EEGROUP", "AUTHORING_QUIESCED", "Local group E2EE authoring is quiesced by an operator");

        const record = e2ee_group_control.parse(parsed.paramSlice()) catch |err| {
            const code: []const u8 = switch (err) {
                error.NeedMoreParams => "NEED_MORE_PARAMS",
                error.TooManyParams => "TOO_MANY_PARAMS",
                error.InvalidChannel => "BAD_CHANNEL",
                error.InvalidKind => "BAD_KIND",
                error.InvalidDevice => "BAD_DEVICE",
                error.InvalidAccount => "BAD_ACCOUNT",
                error.InvalidPayload => "BAD_PAYLOAD",
            };
            return self.failReply(conn, "E2EEGROUP", code, "Malformed group E2EE control record");
        };

        const sender_id = idFromToken(conn.token);
        if (!self.attachmentHasReusableSession(sender_id))
            return self.warnReply(conn, "E2EEGROUP", "TEMPORARILY_UNAVAILABLE", "A reusable session is required for group E2EE");
        if (!self.world.isMember(record.channel, worldIdFromClient(sender_id)))
            return self.failReply(conn, "E2EEGROUP", "NOT_ON_CHANNEL", "Sender is not a member of the target channel");
        if (!self.e2eeDeviceOwnedByAccount(account, record.from_device))
            return self.failReply(conn, "E2EEGROUP", "DEVICE_NOT_OWNED", "The sending account does not own from-device");
        if (record.kind == .welcome and
            !self.e2eeDeviceOwnedByAccount(record.to_account.?, record.to_device.?))
        {
            return self.failReply(conn, "E2EEGROUP", "TARGET_UNAVAILABLE", "Target account/device is absent or offline");
        }

        // Complete every fallible parse, authority, recipient-set, and render
        // step before publishing the first socket delivery.
        var recipients: std.ArrayList(client_model.ClientId) = .empty;
        defer recipients.deinit(self.allocator);
        self.collectE2eeGroupRecipients(record, &recipients) catch
            return self.warnReply(conn, "E2EEGROUP", "TEMPORARILY_UNAVAILABLE", "Could not stage group E2EE delivery");
        if (record.kind == .welcome and recipients.items.len == 0)
            return self.failReply(conn, "E2EEGROUP", "TARGET_UNAVAILABLE", "Target account/device is absent or offline");

        var source_prefix_buf: [default_reply_bytes]u8 = undefined;
        const source_prefix = clientPrefix(conn, &source_prefix_buf) catch
            return self.warnReply(conn, "E2EEGROUP", "TEMPORARILY_UNAVAILABLE", "Could not bind group E2EE origin");
        var line_buf: [e2ee_group_max_line_bytes]u8 = undefined;
        const line = renderE2eeGroupLineFromPrefix(source_prefix, account, record, &line_buf) catch
            return self.failReply(conn, "E2EEGROUP", "BAD_PAYLOAD", "Group E2EE control record is too large");

        // A standalone server has no mesh signing authority and preserves the
        // Phase 4a local-only behavior. Once a node identity exists, every local
        // control enters the exact same signed replay/custody authority as
        // inbound mesh controls before any client delivery becomes visible.
        if (self.config.node_identity) |ident| {
            var origin_pubkey: [e2ee_group_relay.pubkey_len]u8 = undefined;
            var origin_sig: [e2ee_group_relay.sig_len]u8 = undefined;
            var relay_record = e2ee_group_relay.RelayRecord{
                .kind = record.kind,
                .channel = record.channel,
                .source_prefix = source_prefix,
                .account = account,
                .from_device = record.from_device,
                .to_account = record.to_account orelse "",
                .to_device = record.to_device orelse "",
                .payload = record.payload,
                .origin_node = ident.shortId(),
                .hlc = self.nextMeshHlc(),
            };
            e2ee_group_relay.stampOrigin(
                self.allocator,
                &relay_record,
                &ident.sign_kp,
                &origin_pubkey,
                &origin_sig,
            ) catch
                return self.warnReply(conn, "E2EEGROUP", "TEMPORARILY_UNAVAILABLE", "Could not sign group E2EE control");
            const wire = e2ee_group_relay.encode(self.allocator, relay_record) catch
                return self.warnReply(conn, "E2EEGROUP", "TEMPORARILY_UNAVAILABLE", "Could not stage group E2EE custody");
            defer self.allocator.free(wire);
            const peers = self.collectE2eeGroupOutboxPeers(null) catch
                return self.warnReply(conn, "E2EEGROUP", "TEMPORARILY_UNAVAILABLE", "Could not stage group E2EE custody");
            defer self.allocator.free(peers);

            lockSpin(&self.e2ee_group_mesh_mu);
            const verification = self.e2ee_group_mesh_authority.verifyRecord(
                relay_record,
                self.meshWallMs(),
                mesh_clock_mod.default_max_future_skew_ms,
            ) catch {
                self.e2ee_group_mesh_mu.unlock();
                return self.warnReply(conn, "E2EEGROUP", "TEMPORARILY_UNAVAILABLE", "Could not verify group E2EE origin");
            };
            const verified = switch (verification) {
                .verified => |identity| identity,
                else => {
                    self.e2ee_group_mesh_mu.unlock();
                    return self.failReply(conn, "E2EEGROUP", "ORIGIN_REJECTED", "Group E2EE origin was rejected");
                },
            };
            self.e2ee_group_mesh_mu.unlock();
            var prepared_delivery = self.prepareE2eeGroupAttachmentDeliveryBatch(
                recipients.items,
                verified.relay_id,
                line,
            ) catch
                return self.warnReply(conn, "E2EEGROUP", "TEMPORARILY_UNAVAILABLE", "Could not retain group E2EE delivery");
            defer prepared_delivery.deinit();

            // Hold ADS1 through the authority admit. Once accepted, both
            // publications complete allocation-free before either lane opens.
            lockSpin(&self.e2ee_group_mesh_mu);
            const admitted = self.e2ee_group_mesh_authority.admitAuthorizedWithCustody(
                verified,
                peers,
                wire,
            ) catch {
                self.e2ee_group_mesh_mu.unlock();
                return self.warnReply(conn, "E2EEGROUP", "TEMPORARILY_UNAVAILABLE", "Could not retain group E2EE custody");
            };
            switch (admitted.admission) {
                .accepted => prepared_delivery.commit(),
                else => {},
            }
            self.e2ee_group_mesh_mu.unlock();
            switch (admitted.admission) {
                .accepted => {
                    prepared_delivery.release();
                    self.driveE2eeGroupAttachmentDeliveries(recipients.items);
                },
                .duplicate => return,
                .origin_capacity => return self.warnReply(
                    conn,
                    "E2EEGROUP",
                    "TEMPORARILY_UNAVAILABLE",
                    "Group E2EE custody or receipt capacity is temporarily full",
                ),
                .equivocation, .retired => return self.failReply(
                    conn,
                    "E2EEGROUP",
                    "ORIGIN_REJECTED",
                    "Group E2EE origin was rejected",
                ),
            }
            self.driveAcceptedE2eeGroupCustody();
            return;
        }

        const delivered = self.deliverE2eeGroupLine(recipients.items, line);
        if (record.kind == .welcome and delivered == 0)
            return self.failReply(conn, "E2EEGROUP", "TARGET_UNAVAILABLE", "Target account/device is absent or offline");
    }

    pub fn handleE2eeKey(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const p = parsed.paramSlice();
        const sub = if (p.len == 0) "STATUS" else p[0];

        if (std.ascii.eqlIgnoreCase(sub, "STATUS")) {
            const account = conn.session.account() orelse
                return self.failReply(conn, "E2EEKEY", "NOT_LOGGED_IN", "Log in before managing E2EE device keys");
            const count = self.e2eeDeviceCount(account) catch
                return self.failReply(conn, "E2EEKEY", "TEMPORARILY_UNAVAILABLE", "Could not inspect the complete device directory");
            var b: [128]u8 = undefined;
            const body = std.fmt.bufPrint(&b, "STATUS account={s} devices={d}", .{ account, count }) catch return;
            return self.e2eeKeyReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "LIST")) {
            const account = if (p.len >= 2) p[1] else (conn.session.account() orelse
                return self.failReply(conn, "E2EEKEY", "NOT_LOGGED_IN", "Log in before listing your E2EE device keys"));
            const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
            var views: [ircx_prop_store.user_max_props_per_entity]ircx_prop_store.EntryView = undefined;
            const rows = self.props.listPropsRaw(entity, &views) catch
                return self.failReply(conn, "E2EEKEY", "TEMPORARILY_UNAVAILABLE", "Could not inspect the complete device directory");
            var count: usize = 0;
            for (rows) |ev| {
                if (!e2ee_policy.isDevicePropKey(ev.key)) continue;
                const device = ev.key[e2ee_policy.device_prop_prefix.len..];
                const parsed_value = splitE2eeDeviceValue(ev.value) orelse continue;
                var b: [default_reply_bytes]u8 = undefined;
                const body = std.fmt.bufPrint(
                    &b,
                    "DEVICE account={s} id={s} alg={s} key={s}",
                    .{ account, device, parsed_value.algorithm, parsed_value.public_key },
                ) catch continue;
                try self.e2eeKeyReply(conn, body);
                count += 1;
            }
            var end_buf: [128]u8 = undefined;
            const end = std.fmt.bufPrint(&end_buf, "END account={s} devices={d}", .{ account, count }) catch return;
            return self.e2eeKeyReply(conn, end);
        }

        if (std.ascii.eqlIgnoreCase(sub, "ADD")) {
            _ = conn.session.account() orelse
                return self.failReply(conn, "E2EEKEY", "NOT_LOGGED_IN", "Log in before adding E2EE device keys");
            if (p.len < 4) return self.failReply(conn, "E2EEKEY", "NEED_MORE_PARAMS", "Usage: E2EEKEY ADD <device-id> <algorithm> <public-key>");
            var key_buf: [e2ee_policy.device_prop_prefix.len + e2ee_policy.max_device_id_len]u8 = undefined;
            const key = e2ee_policy.devicePropKey(p[1], &key_buf) orelse
                return self.failReply(conn, "E2EEKEY", "BAD_DEVICE", "Device id must use A-Z, a-z, 0-9, dot, dash, or underscore");
            e2ee_policy.validateAdvertisement(p[1], p[2], p[3]) catch |err| switch (err) {
                error.InvalidDevice => return self.failReply(
                    conn,
                    "E2EEKEY",
                    "BAD_DEVICE",
                    "Device id must match the OGC1 directory identifier",
                ),
                error.InvalidKey => return self.failReply(conn, "E2EEKEY", "BAD_KEY", "Algorithm or public key is invalid"),
            };
            var value_buf: [e2ee_policy.max_device_value_len]u8 = undefined;
            const value = e2ee_policy.deviceValue(p[2], p[3], &value_buf) orelse
                return self.failReply(conn, "E2EEKEY", "BAD_KEY", "Algorithm or public key is invalid");
            const outcome = self.commitLocalDurableDeviceProp(conn, null, key, value, true);
            if (outcome != .committed)
                return self.durableDeviceFailureReply(conn, "E2EEKEY", outcome);
            var b: [128]u8 = undefined;
            const body = std.fmt.bufPrint(&b, "ADDED id={s} alg={s}", .{ p[1], p[2] }) catch return;
            return self.e2eeKeyReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "DEL") or std.ascii.eqlIgnoreCase(sub, "DELETE")) {
            _ = conn.session.account() orelse
                return self.failReply(conn, "E2EEKEY", "NOT_LOGGED_IN", "Log in before deleting E2EE device keys");
            if (p.len < 2) return self.failReply(conn, "E2EEKEY", "NEED_MORE_PARAMS", "Usage: E2EEKEY DEL <device-id>");
            var key_buf: [e2ee_policy.device_prop_prefix.len + e2ee_policy.max_device_id_len]u8 = undefined;
            const key = e2ee_policy.devicePropKey(p[1], &key_buf) orelse
                return self.failReply(conn, "E2EEKEY", "BAD_DEVICE", "Device id must use A-Z, a-z, 0-9, dot, dash, or underscore");
            const outcome = self.commitLocalDurableDeviceProp(conn, null, key, "", false);
            if (outcome != .committed)
                return self.durableDeviceFailureReply(conn, "E2EEKEY", outcome);
            var b: [96]u8 = undefined;
            const body = std.fmt.bufPrint(&b, "DELETED id={s}", .{p[1]}) catch return;
            return self.e2eeKeyReply(conn, body);
        }

        return self.failReply(conn, "E2EEKEY", "INVALID_SUBCOMMAND", "Usage: E2EEKEY [STATUS|LIST [account]|ADD <device-id> <algorithm> <public-key>|DEL <device-id>]");
    }

    fn identityReply(self: *LinuxServer, conn: *ConnState, body: []const u8) !void {
        var buf: [default_reply_bytes]u8 = undefined;
        const text = std.fmt.bufPrint(&buf, "IDENTITY {s}", .{body}) catch return;
        try self.noticeTo(conn, text);
    }

    fn identityKeyCount(self: *LinuxServer, account: []const u8) usize {
        const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
        var views: [ircx_prop_store.default_max_props_per_entity]ircx_prop_store.EntryView = undefined;
        const rows = self.props.listProps(entity, &views) catch return 0;
        var count: usize = 0;
        for (rows) |ev| {
            if (account_identity.isPropKey(ev.key)) count += 1;
        }
        return count;
    }

    pub fn handleIdentity(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const p = parsed.paramSlice();
        const sub = if (p.len == 0) "STATUS" else p[0];

        if (std.ascii.eqlIgnoreCase(sub, "VERIFY")) {
            if (p.len < 5) return self.failReply(conn, "IDENTITY", "NEED_MORE_PARAMS", "Usage: IDENTITY VERIFY <account> <label> <public-key-hex> <signature-hex>");
            const ok = account_identity.verifyClaim(p[1], p[2], p[3], p[4]);
            var b: [160]u8 = undefined;
            const body = std.fmt.bufPrint(&b, "VERIFY account={s} label={s} result={s}", .{ p[1], p[2], if (ok) "valid" else "invalid" }) catch return;
            return self.identityReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "STATUS")) {
            const account = conn.session.account() orelse
                return self.failReply(conn, "IDENTITY", "NOT_LOGGED_IN", "Log in before managing portable identity keys");
            var b: [128]u8 = undefined;
            const body = std.fmt.bufPrint(&b, "STATUS account={s} keys={d}", .{ account, self.identityKeyCount(account) }) catch return;
            return self.identityReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "LIST")) {
            const account = if (p.len >= 2) p[1] else (conn.session.account() orelse
                return self.failReply(conn, "IDENTITY", "NOT_LOGGED_IN", "Log in before listing your portable identity keys"));
            const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
            var views: [ircx_prop_store.default_max_props_per_entity]ircx_prop_store.EntryView = undefined;
            const rows = self.props.listProps(entity, &views) catch rows: {
                break :rows views[0..0];
            };
            var count: usize = 0;
            for (rows) |ev| {
                if (!account_identity.isPropKey(ev.key)) continue;
                if (account_identity.parseClaimValue(ev.value) == null) continue;
                const label = ev.key[account_identity.prop_prefix.len..];
                var b: [default_reply_bytes]u8 = undefined;
                const body = std.fmt.bufPrint(
                    &b,
                    "KEY account={s} label={s} pub={s} sig={s}",
                    .{ account, label, ev.value[0..account_identity.public_key_hex_len], ev.value[account_identity.public_key_hex_len + 1 ..] },
                ) catch continue;
                try self.identityReply(conn, body);
                count += 1;
            }
            var end_buf: [128]u8 = undefined;
            const end = std.fmt.bufPrint(&end_buf, "END account={s} keys={d}", .{ account, count }) catch return;
            return self.identityReply(conn, end);
        }

        if (std.ascii.eqlIgnoreCase(sub, "ADD")) {
            const account = conn.session.account() orelse
                return self.failReply(conn, "IDENTITY", "NOT_LOGGED_IN", "Log in before adding portable identity keys");
            if (p.len < 4) return self.failReply(conn, "IDENTITY", "NEED_MORE_PARAMS", "Usage: IDENTITY ADD <label> <public-key-hex> <signature-hex>");
            if (!account_identity.verifyClaim(account, p[1], p[2], p[3]))
                return self.failReply(conn, "IDENTITY", "BAD_ASSERTION", "Identity key assertion did not verify for this account and label");
            var key_buf: [account_identity.prop_prefix.len + account_identity.max_label_len]u8 = undefined;
            const key = account_identity.propKey(p[1], &key_buf) orelse
                return self.failReply(conn, "IDENTITY", "BAD_LABEL", "Identity label must use A-Z, a-z, 0-9, dot, dash, or underscore");
            var value_buf: [account_identity.max_value_len]u8 = undefined;
            const value = account_identity.claimValue(p[2], p[3], &value_buf) orelse
                return self.failReply(conn, "IDENTITY", "BAD_ASSERTION", "Identity public key or signature is invalid");
            const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
            const ev = self.props.setProp(entity, key, value, .{ .id = account, .access = .member }) catch
                return self.failReply(conn, "IDENTITY", "STORE_FAILED", "Could not store portable identity key");
            const hlc = self.nextChannelPropHlc();
            self.observeLocalUserCredentialProp(true, ev.entity.kind, ev.entity.id, ev.key, ev.value, hlc);
            self.propagateLocalEntityPropAt(true, ev.entity.kind, ev.entity.id, ev.key, ev.value, ev.owner, hlc);
            self.notifyLocalPropChange(conn, ev.entity, ev.key, ev.value);
            var b: [128]u8 = undefined;
            const body = std.fmt.bufPrint(&b, "ADDED label={s}", .{p[1]}) catch return;
            return self.identityReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "RESIDENCE")) {
            // Design C (F1): publish/refresh this account's signed residence
            // proof for THIS node as the replicated `identity.residence.<node>`
            // user prop. The CLIENT signs (the daemon never holds account keys);
            // the daemon verifies the binding against the caller's own enrolled
            // identity keys before storing — fail-closed at every step, so an
            // account with no proof simply stays on the conservative UID path.
            const account = conn.session.account() orelse
                return self.failReply(conn, "IDENTITY", "NOT_LOGGED_IN", "Log in before publishing a residence proof");
            if (p.len < 5) return self.failReply(conn, "IDENTITY", "NEED_MORE_PARAMS", "Usage: IDENTITY RESIDENCE <node-shortid-hex> <epoch> <expiry-ms> <signature-hex>");
            const ident = self.config.node_identity orelse
                return self.failReply(conn, "IDENTITY", "TEMPORARILY_UNAVAILABLE", "This server has no mesh identity; residence proofs are unavailable");
            const local_node = ident.shortId();
            const node = std.fmt.parseUnsigned(u64, p[1], 16) catch
                return self.failReply(conn, "IDENTITY", "BAD_NODE", "Node must be this server's 16-hex mesh shortId (see ISUPPORT ACCOUNTRESIDENCE)");
            // A proof binds the node the client is actually logged in to. This
            // node never publishes (or relays as its own) a residence claim for
            // a DIFFERENT node — that is exactly the forgery the proof exists to
            // prevent.
            if (node != local_node)
                return self.failReply(conn, "IDENTITY", "WRONG_NODE", "A residence proof must bind the server you are connected to");
            const epoch = std.fmt.parseUnsigned(u64, p[2], 10) catch
                return self.failReply(conn, "IDENTITY", "BAD_EPOCH", "Epoch must be an unsigned integer");
            const expiry_ms = std.fmt.parseUnsigned(u64, p[3], 10) catch
                return self.failReply(conn, "IDENTITY", "BAD_EXPIRY", "Expiry must be wall-clock unix milliseconds");
            const sig = account_identity.parseSignatureHex(p[4]) orelse
                return self.failReply(conn, "IDENTITY", "BAD_ASSERTION", "Residence signature must be 128 hex chars");
            var wire_buf: [account_identity.max_residence_len]u8 = undefined;
            const wire = account_identity.encodeResidence(
                .{ .account = account, .node = node, .epoch = epoch, .expiry_ms = expiry_ms },
                sig,
                &wire_buf,
            ) orelse return self.failReply(conn, "IDENTITY", "BAD_ASSERTION", "Residence binding is malformed");
            // Verify against ANY of the caller's own enrolled identity keys —
            // the same replicated `identity.key.*` props every mesh node holds.
            // verifyResidence also enforces freshness and the hard max window.
            const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
            const now_ms = self.grantNowU64();
            const verified = blk: {
                var views: [ircx_prop_store.default_max_props_per_entity]ircx_prop_store.EntryView = undefined;
                const rows = self.props.listProps(entity, &views) catch break :blk false;
                for (rows) |kv| {
                    if (!account_identity.isPropKey(kv.key)) continue;
                    const claim = account_identity.parseClaimValue(kv.value) orelse continue;
                    _ = account_identity.verifyResidence(wire, claim.public_key, account, node, now_ms) catch continue;
                    break :blk true;
                }
                break :blk false;
            };
            if (!verified)
                return self.failReply(conn, "IDENTITY", "BAD_ASSERTION", "Residence proof did not verify against any enrolled identity key (check enrollment, node binding, epoch/expiry)");
            var rkey_buf: [account_identity.residence_prop_prefix.len + account_identity.residence_node_hex_len]u8 = undefined;
            const rkey = account_identity.residencePropKey(node, &rkey_buf) orelse
                return self.failReply(conn, "IDENTITY", "BAD_NODE", "Residence prop key overflow");
            // Per-(account, node) monotonic epoch floor: the CURRENTLY stored
            // proof IS the floor (state = the replicated prop itself, so the
            // supersede rule survives USR2 for free). A non-increasing epoch is
            // a stale re-publish / replay and is rejected.
            if (self.props.getProp(entity, rkey)) |prev| {
                var prev_buf: [account_identity.max_residence_len]u8 = undefined;
                if (decodeResidenceHex(prev.value, &prev_buf)) |prev_wire| {
                    if (account_identity.parseResidence(prev_wire)) |prev_parsed| {
                        if (epoch <= prev_parsed.res.epoch)
                            return self.failReply(conn, "IDENTITY", "STALE_EPOCH", "Residence epoch must exceed the currently-published epoch");
                    }
                }
            } else |_| {}
            var value_buf: [account_identity.max_residence_hex_len]u8 = undefined;
            const value = encodeResidenceHex(wire, &value_buf) orelse
                return self.failReply(conn, "IDENTITY", "STORE_FAILED", "Could not encode residence proof");
            const ev = self.props.setProp(entity, rkey, value, .{ .id = account, .access = .member }) catch
                return self.failReply(conn, "IDENTITY", "STORE_FAILED", "Could not store residence proof");
            self.propagateLocalEntityProp(true, ev.entity.kind, ev.entity.id, ev.key, ev.value, ev.owner);
            self.notifyLocalPropChange(conn, ev.entity, ev.key, ev.value);
            var b: [160]u8 = undefined;
            const body = std.fmt.bufPrint(&b, "RESIDENCE PUBLISHED node={x:0>16} epoch={d} expiry={d}", .{ node, epoch, expiry_ms }) catch return;
            return self.identityReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "DEL") or std.ascii.eqlIgnoreCase(sub, "DELETE")) {
            const account = conn.session.account() orelse
                return self.failReply(conn, "IDENTITY", "NOT_LOGGED_IN", "Log in before deleting portable identity keys");
            if (p.len < 2) return self.failReply(conn, "IDENTITY", "NEED_MORE_PARAMS", "Usage: IDENTITY DEL <label>");
            var key_buf: [account_identity.prop_prefix.len + account_identity.max_label_len]u8 = undefined;
            const key = account_identity.propKey(p[1], &key_buf) orelse
                return self.failReply(conn, "IDENTITY", "BAD_LABEL", "Identity label must use A-Z, a-z, 0-9, dot, dash, or underscore");
            const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
            const existed = if (self.props.getProp(entity, key)) |_| true else |_| false;
            self.props.deleteProp(entity, key) catch {};
            const hlc = self.nextChannelPropHlc();
            if (existed) {
                self.observeLocalUserCredentialProp(false, entity.kind, entity.id, key, "", hlc);
            }
            self.propagateLocalEntityPropAt(false, entity.kind, entity.id, key, "", account, hlc);
            self.notifyLocalPropChange(conn, entity, key, "");
            var b: [96]u8 = undefined;
            const body = std.fmt.bufPrint(&b, "DELETED label={s}", .{p[1]}) catch return;
            return self.identityReply(conn, body);
        }

        return self.failReply(conn, "IDENTITY", "INVALID_SUBCOMMAND", "Usage: IDENTITY [STATUS|LIST [account]|ADD <label> <public-key-hex> <signature-hex>|DEL <label>|RESIDENCE <node-shortid-hex> <epoch> <expiry-ms> <signature-hex>|VERIFY <account> <label> <public-key-hex> <signature-hex>]");
    }

    /// Hex-decode a stored `identity.residence.*` prop value into `out`,
    /// returning the raw wire bytes, or null on any malformation (odd length,
    /// non-hex, oversize) — fail-closed, the caller treats null as "no proof".
    fn decodeResidenceHex(value: []const u8, out: *[account_identity.max_residence_len]u8) ?[]const u8 {
        if (value.len == 0 or value.len % 2 != 0 or value.len / 2 > out.len) return null;
        return std.fmt.hexToBytes(out[0 .. value.len / 2], value) catch null;
    }

    /// Lowercase-hex encode a residence wire into `out` (the replicated prop
    /// VALUE is text). Null when `wire` exceeds the codec's bound.
    fn encodeResidenceHex(wire: []const u8, out: *[account_identity.max_residence_hex_len]u8) ?[]const u8 {
        if (wire.len * 2 > out.len) return null;
        const alphabet = "0123456789abcdef";
        for (wire, 0..) |byte, i| {
            out[i * 2] = alphabet[byte >> 4];
            out[i * 2 + 1] = alphabet[byte & 0xF];
        }
        return out[0 .. wire.len * 2];
    }

    pub fn handleKeyTrans(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const p = parsed.paramSlice();
        const sub = if (p.len == 0) "STATUS" else p[0];
        if (std.ascii.eqlIgnoreCase(sub, "REQUIRE")) {
            if (p.len < 2) return self.failReply(conn, "KEYTRANS", "NEED_MORE_PARAMS", "Usage: KEYTRANS REQUIRE <on|off>");
            if (std.ascii.eqlIgnoreCase(p[1], "on")) {
                conn.keytrans_require = true;
            } else if (std.ascii.eqlIgnoreCase(p[1], "off")) {
                conn.keytrans_require = false;
            } else return self.failReply(conn, "KEYTRANS", "BAD_VALUE", "REQUIRE must be on or off");
            return self.keyTransReply(conn, if (conn.keytrans_require) "REQUIRE on" else "REQUIRE off");
        }
        const svc = self.account_services orelse {
            if (conn.keytrans_require) return self.failReply(conn, "KEYTRANS", "MISSING_LOG", "Key transparency log is missing");
            return self.failReply(conn, "KEYTRANS", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        };

        if (std.ascii.eqlIgnoreCase(sub, "STATUS") or std.ascii.eqlIgnoreCase(sub, "ROOT")) {
            const status = svc.keyTransparencyStatus();
            if (conn.keytrans_require and (!status.enabled or !status.available)) {
                return self.failReply(conn, "KEYTRANS", "MISSING_LOG", "Key transparency log is missing");
            }
            if (!status.enabled) return self.keyTransReply(conn, "STATUS disabled semantics=observational scope=node-local");
            if (!status.available) return self.keyTransReply(conn, "STATUS unavailable semantics=observational scope=node-local");
            const root_hex = std.fmt.bytesToHex(status.root, .lower);
            var b: [220]u8 = undefined;
            const body = std.fmt.bufPrint(
                &b,
                "STATUS enabled semantics=observational scope=node-local entries={d} root={s}",
                .{ status.entries, &root_hex },
            ) catch return;
            return self.keyTransReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "PROOF")) {
            if (p.len < 2) return self.failReply(conn, "KEYTRANS", "NEED_MORE_PARAMS", "Usage: KEYTRANS PROOF <position>");
            const position = std.fmt.parseInt(usize, p[1], 10) catch
                return self.failReply(conn, "KEYTRANS", "BAD_POSITION", "Proof position must be a decimal leaf index");
            var proof = svc.keyTransparencyProof(self.allocator, position) catch |err| {
                const code: []const u8 = switch (err) {
                    error.Disabled => "DISABLED",
                    error.Unavailable => "TEMPORARILY_UNAVAILABLE",
                    error.IndexOutOfRange => "NO_SUCH_LEAF",
                    error.OutOfMemory => "INTERNAL_ERROR",
                };
                const reason: []const u8 = switch (err) {
                    error.Disabled => "Key transparency log is not enabled",
                    error.Unavailable => "Key transparency log is unavailable",
                    error.IndexOutOfRange => "No key transparency leaf exists at that position",
                    error.OutOfMemory => "Could not allocate proof snapshot",
                };
                return self.failReply(conn, "KEYTRANS", code, reason);
            };
            defer proof.deinit(self.allocator);

            const root_hex = std.fmt.bytesToHex(proof.root, .lower);
            var hb: [192]u8 = undefined;
            const header = std.fmt.bufPrint(
                &hb,
                "PROOF position={d} size={d} root={s} path={d} peaks={d}",
                .{ proof.position, proof.size, &root_hex, proof.path.len, proof.peaks.len },
            ) catch return;
            try self.keyTransReply(conn, header);

            for (proof.path, 0..) |step, i| {
                const hash_hex = std.fmt.bytesToHex(step.hash, .lower);
                const side: []const u8 = switch (step.side) {
                    .left => "left",
                    .right => "right",
                };
                var lb: [160]u8 = undefined;
                const line = std.fmt.bufPrint(&lb, "PATH {d} {s} {s}", .{ i, side, &hash_hex }) catch continue;
                try self.keyTransReply(conn, line);
            }

            for (proof.peaks, 0..) |peak, i| {
                const hash_hex = std.fmt.bytesToHex(peak, .lower);
                var lb: [160]u8 = undefined;
                const line = std.fmt.bufPrint(&lb, "PEAK {d} {s}", .{ i, &hash_hex }) catch continue;
                try self.keyTransReply(conn, line);
            }

            var eb: [80]u8 = undefined;
            const end = std.fmt.bufPrint(&eb, "PROOF-END position={d}", .{proof.position}) catch return;
            return self.keyTransReply(conn, end);
        }

        // EVENT/DEVICE are a public transparency surface: they reveal the
        // canonical account, kind, action, key id, material hash, timestamp,
        // and leaf. They never emit raw COSE keys, identity signatures, or
        // passwords. Anyone who can walk positions can audit the log; that is
        // the point, not a directory of live credentials.
        if (std.ascii.eqlIgnoreCase(sub, "EVENT")) {
            if (p.len < 2) return self.failReply(conn, "KEYTRANS", "NEED_MORE_PARAMS", "Usage: KEYTRANS EVENT <position>");
            const position = std.fmt.parseInt(usize, p[1], 10) catch
                return self.failReply(conn, "KEYTRANS", "BAD_POSITION", "Event position must be a decimal leaf index");
            const snapshot = svc.keyTransparencyEvent(position) catch |err| {
                const code: []const u8 = switch (err) {
                    error.Disabled => "DISABLED",
                    error.Unavailable => "TEMPORARILY_UNAVAILABLE",
                    error.IndexOutOfRange => "NO_SUCH_LEAF",
                };
                const reason: []const u8 = switch (err) {
                    error.Disabled => "Key transparency log is not enabled",
                    error.Unavailable => "Key transparency log is unavailable",
                    error.IndexOutOfRange => "No key transparency event exists at that position",
                };
                return self.failReply(conn, "KEYTRANS", code, reason);
            };
            const key_hash_hex = std.fmt.bytesToHex(snapshot.event.key_hash, .lower);
            const leaf_hex = std.fmt.bytesToHex(snapshot.event.leaf, .lower);
            var b: [default_reply_bytes]u8 = undefined;
            const body = std.fmt.bufPrint(
                &b,
                "EVENT position={d} size={d} account={s} kind={s} action={s} key_id={s} key_hash={s} time={d} leaf={s}",
                .{
                    snapshot.position,
                    snapshot.size,
                    snapshot.event.account(),
                    snapshot.event.kind.wireName(),
                    snapshot.event.action.wireName(),
                    snapshot.event.keyId(),
                    &key_hash_hex,
                    snapshot.event.timestamp_ms,
                    &leaf_hex,
                },
            ) catch return;
            return self.keyTransReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "DEVICE")) {
            if (p.len < 3) return self.failReply(conn, "KEYTRANS", "NEED_MORE_PARAMS", "Usage: KEYTRANS DEVICE <account> <device-id>");
            const snapshot = svc.keyTransparencyDevice(p[1], p[2]) catch |err| {
                const code: []const u8 = switch (err) {
                    error.Disabled => "DISABLED",
                    error.Unavailable => "TEMPORARILY_UNAVAILABLE",
                    error.InvalidName => "BAD_ACCOUNT",
                    error.InvalidKeyId => "BAD_DEVICE",
                    error.NotFound => "NO_SUCH_DEVICE",
                };
                const reason: []const u8 = switch (err) {
                    error.Disabled => "Key transparency log is not enabled",
                    error.Unavailable => "Key transparency log is unavailable",
                    error.InvalidName => "Account must be a canonical services name",
                    error.InvalidKeyId => "Device id contains unsupported bytes",
                    error.NotFound => "No key transparency event exists for that account and device",
                };
                return self.failReply(conn, "KEYTRANS", code, reason);
            };
            const key_hash_hex = std.fmt.bytesToHex(snapshot.event.key_hash, .lower);
            const leaf_hex = std.fmt.bytesToHex(snapshot.event.leaf, .lower);
            var b: [default_reply_bytes]u8 = undefined;
            const body = std.fmt.bufPrint(
                &b,
                "DEVICE account={s} id={s} observation={s} scope=node-local position={d} size={d} key_hash={s} time={d} leaf={s}",
                .{
                    snapshot.event.account(),
                    snapshot.event.keyId(),
                    snapshot.observation.wireName(),
                    snapshot.position,
                    snapshot.size,
                    &key_hash_hex,
                    snapshot.event.timestamp_ms,
                    &leaf_hex,
                },
            ) catch return;
            return self.keyTransReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "CONSISTENCY")) {
            if (p.len < 2) return self.failReply(conn, "KEYTRANS", "NEED_MORE_PARAMS", "Usage: KEYTRANS CONSISTENCY <old-size>");
            const old_size = std.fmt.parseInt(usize, p[1], 10) catch
                return self.failReply(conn, "KEYTRANS", "BAD_SIZE", "Consistency size must be a decimal prefix length");
            const cmp = svc.keyTransparencyConsistency(old_size) catch |err| {
                const code: []const u8 = switch (err) {
                    error.Disabled => "DISABLED",
                    error.Unavailable => "TEMPORARILY_UNAVAILABLE",
                    error.SizeAhead => "BAD_SIZE",
                    error.UnknownCheckpoint => "UNKNOWN_CHECKPOINT",
                    error.Corrupt => "CORRUPT",
                    error.OutOfMemory => "INTERNAL_ERROR",
                };
                const reason: []const u8 = switch (err) {
                    error.Disabled => "Observational key log is not enabled",
                    error.Unavailable => "Observational key log is unavailable",
                    error.SizeAhead => "Requested size is ahead of the current log",
                    error.UnknownCheckpoint => "No durable checkpoint exists at that size",
                    error.Corrupt => "Durable checkpoint is corrupt or does not match this log",
                    error.OutOfMemory => "Could not compare checkpoint",
                };
                return self.failReply(conn, "KEYTRANS", code, reason);
            };
            const prefix: []const u8 = switch (cmp.prefix) {
                .match => "match",
                .mismatch => "mismatch",
            };
            const old_root_hex = std.fmt.bytesToHex(cmp.old_root, .lower);
            const root_hex = std.fmt.bytesToHex(cmp.root, .lower);
            var b: [360]u8 = undefined;
            const body = std.fmt.bufPrint(
                &b,
                "CONSISTENCY old_size={d} old_root={s} size={d} root={s} prefix={s} scheme=checkpoint-comparison",
                .{ cmp.old_size, &old_root_hex, cmp.size, &root_hex, prefix },
            ) catch return;
            return self.keyTransReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "STORE")) {
            if (p.len < 7) return self.failReply(conn, "KEYTRANS", "NEED_MORE_PARAMS", "Usage: KEYTRANS STORE <node> <entries> <root-hex> <sig-hex> <pubkey-hex> <action> [key-id]");
            const node_id = std.fmt.parseInt(u64, p[1], 10) catch
                return self.failReply(conn, "KEYTRANS", "BAD_NODE", "Node id must be a decimal integer");
            const entries = std.fmt.parseInt(u64, p[2], 10) catch
                return self.failReply(conn, "KEYTRANS", "BAD_SIZE", "Entry count must be a decimal integer");
            const key_id = if (p.len >= 8) p[7] else "";
            const head = key_transparency.parseSignedHead(node_id, entries, p[3], p[4], p[5], p[6], key_id) catch
                return self.failReply(conn, "KEYTRANS", "BAD_HEAD", "Signed head fields are not canonical");
            svc.storeKeyTransparencyHead(head) catch |err| {
                const code: []const u8 = switch (err) {
                    error.Disabled => "DISABLED",
                    error.Unavailable => "TEMPORARILY_UNAVAILABLE",
                    error.BadSignature => "BAD_SIGNATURE",
                    error.KeyMismatch => "KEY_MISMATCH",
                    error.BadHead => "BAD_HEAD",
                    error.StaleHead => "STALE_HEAD",
                    error.OutOfMemory => "INTERNAL_ERROR",
                };
                const reason: []const u8 = switch (err) {
                    error.Disabled => "Key transparency log is not enabled",
                    error.Unavailable => "Key transparency log is unavailable",
                    error.BadSignature => "Signed head did not verify",
                    error.KeyMismatch => "That node id is already pinned to a different key",
                    error.BadHead => "Signed head fields are not canonical",
                    error.StaleHead => "A newer signed head is already stored",
                    error.OutOfMemory => "Could not store the signed head",
                };
                return self.failReply(conn, "KEYTRANS", code, reason);
            };
            var b: [160]u8 = undefined;
            const body = std.fmt.bufPrint(&b, "STORE node={d} entries={d} action={s}", .{
                head.node_id,
                head.entries,
                head.action.wireName(),
            }) catch return;
            return self.keyTransReply(conn, body);
        }

        if (std.ascii.eqlIgnoreCase(sub, "PEER")) {
            if (p.len < 2) return self.failReply(conn, "KEYTRANS", "NEED_MORE_PARAMS", "Usage: KEYTRANS PEER <node>");
            const node_id = std.fmt.parseInt(u64, p[1], 10) catch
                return self.failReply(conn, "KEYTRANS", "BAD_NODE", "Node id must be a decimal integer");
            const stored = svc.keyTransparencyPeerHead(node_id) catch |err| {
                const code: []const u8 = switch (err) {
                    error.Disabled => "DISABLED",
                    error.Unavailable => "TEMPORARILY_UNAVAILABLE",
                };
                const reason: []const u8 = switch (err) {
                    error.Disabled => "Key transparency log is not enabled",
                    error.Unavailable => "Key transparency log is unavailable",
                };
                if (conn.keytrans_require and err == error.Disabled) {
                    return self.failReply(conn, "KEYTRANS", "MISSING_LOG", "Key transparency log is missing");
                }
                return self.failReply(conn, "KEYTRANS", code, reason);
            };
            if (stored) |head| {
                const root_hex = std.fmt.bytesToHex(head.root, .lower);
                var b: [320]u8 = undefined;
                const body = std.fmt.bufPrint(
                    &b,
                    "PEER node={d} entries={d} root={s} action={s} key_id={s} scheme=signed-head",
                    .{ head.node_id, head.entries, &root_hex, head.action.wireName(), head.keyId() },
                ) catch return;
                return self.keyTransReply(conn, body);
            }
            if (conn.keytrans_require) {
                return self.failReply(conn, "KEYTRANS", "MISSING_LOG", "No signed head is stored for that node");
            }
            var absent: [64]u8 = undefined;
            const body = std.fmt.bufPrint(&absent, "PEER node={d} present=no", .{node_id}) catch return;
            return self.keyTransReply(conn, body);
        }

        return self.failReply(conn, "KEYTRANS", "INVALID_SUBCOMMAND", "Usage: KEYTRANS [STATUS|ROOT|PROOF <position>|EVENT <position>|DEVICE <account> <device-id>|CONSISTENCY <old-size>|STORE <node> <entries> <root-hex> <sig-hex> <pubkey-hex> <action> [key-id]|PEER <node>|REQUIRE <on|off>]");
    }

    // ── WEBAUTHN: passkey (FIDO2) registration + passwordless login ──────────
    //
    // Ceremony state lives in `conn.webauthn_pending` (per-connection, single-
    // use, TTL-bounded). Durable credential records live in the account store
    // (`services.webauthn*`, mirroring certfp). Signature/COSE/attested-data
    // verification lives in `crypto/webauthn.zig`; this handler orchestrates the
    // challenge issue, clientDataJSON binding (type/challenge/origin), and login.

    /// Resolved `[webauthn]` config, or null when the feature is inert (missing
    /// rp_id or origins). WEBAUTHN fails closed until both are set.
    const WebauthnRp = struct {
        rp_id: []const u8,
        origins: []const []const u8,
        require_uv: bool,
        require_attestation: bool,
    };
    fn webauthnRp(self: *const LinuxServer) ?WebauthnRp {
        const rp_id = self.config.webauthn_rp_id orelse return null;
        if (rp_id.len == 0 or self.config.webauthn_origins.len == 0) return null;
        return .{
            .rp_id = rp_id,
            .origins = self.config.webauthn_origins,
            .require_uv = self.config.webauthn_require_uv,
            .require_attestation = self.config.webauthn_require_attestation,
        };
    }

    /// Emit a WEBAUTHN service reply as a caller-targeted Event Spine line:
    /// `:<server> EVENT <caller-nick> WEBAUTHN <body>`. `body` is a preformatted,
    /// CRLF-free `<SUBTYPE> <args>` payload. This mirrors the MEDIA EVENT plane
    /// (`sendMediaEventReply`) — the result is targeted to the requesting
    /// connection, never published to subscribers. The Event Spine renderer
    /// validates every message byte (rejecting CR/LF/control), so a hostile
    /// label can never smuggle a forged line; a render failure drops the reply,
    /// fail-closed, exactly like the old NOTICE control-byte guard did.
    fn webauthnReply(self: *LinuxServer, conn: *ConnState, body: []const u8) !void {
        var msg_buf: [event_spine.max_event_line_len]u8 = undefined;
        const message = std.fmt.bufPrint(&msg_buf, "WEBAUTHN {s}", .{body}) catch return;
        var tag_buf: [128]u8 = undefined;
        const tags = if (conn.session.hasCap(.message_tags))
            event_spine.buildEventTags(&tag_buf, .service, .notice) catch ""
        else
            "";
        var line_buf: [event_spine.max_event_line_len]u8 = undefined;
        const line = event_spine.renderEventTagged(tags, self.serverName(), conn.session.displayName(), message, &line_buf) catch return;
        try appendToConn(conn, line);
    }

    pub fn handleWebauthn(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!self.authenticationAvailable())
            return self.failReply(conn, "WEBAUTHN", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery");
        const svc = self.account_services orelse
            return self.failReply(conn, "WEBAUTHN", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        const rp = self.webauthnRp() orelse
            return self.failReply(conn, "WEBAUTHN", "NOT_CONFIGURED", "Passkey login is not configured on this network");
        const p = parsed.paramSlice();
        if (p.len == 0)
            return self.failReply(conn, "WEBAUTHN", "NEED_MORE_PARAMS", "Usage: WEBAUTHN <REGISTER|REGISTER-FINISH|AUTH|AUTH-FINISH|LIST|REMOVE|RENAME|STATUS>");
        const sub = p[0];

        if (std.ascii.eqlIgnoreCase(sub, "STATUS")) return self.webauthnStatus(conn, svc);
        if (std.ascii.eqlIgnoreCase(sub, "REGISTER")) return self.webauthnRegister(conn, rp, p);
        if (std.ascii.eqlIgnoreCase(sub, "REGISTER-FINISH")) return self.webauthnRegisterFinish(conn, svc, rp, p);
        if (std.ascii.eqlIgnoreCase(sub, "AUTH")) return self.webauthnAuth(conn, svc, rp, p);
        if (std.ascii.eqlIgnoreCase(sub, "AUTH-FINISH")) return self.webauthnAuthFinish(conn, svc, rp, p);
        if (std.ascii.eqlIgnoreCase(sub, "LIST")) return self.webauthnListCmd(conn, svc);
        if (std.ascii.eqlIgnoreCase(sub, "REMOVE")) return self.webauthnRemove(conn, svc, p);
        if (std.ascii.eqlIgnoreCase(sub, "RENAME")) return self.webauthnRename(conn, svc, p);
        return self.failReply(conn, "WEBAUTHN", "INVALID_SUBCOMMAND", "Usage: WEBAUTHN <REGISTER|REGISTER-FINISH|AUTH|AUTH-FINISH|LIST|REMOVE|RENAME|STATUS>");
    }

    /// Fill `out` with a fresh CSPRNG challenge. Returns false (fail-closed) when
    /// no randomness source is configured.
    fn webauthnChallenge(self: *LinuxServer, out: *[webauthn_creds_mod.challenge_len]u8) bool {
        const io = self.config.crypto_io orelse return false;
        io.random(out);
        return true;
    }

    fn webauthnStatus(self: *LinuxServer, conn: *ConnState, svc: *services_mod.Services) !void {
        const account = conn.session.account() orelse
            return self.failReply(conn, "WEBAUTHN", "NOT_LOGGED_IN", "Log in to see your passkeys");
        var entries: [webauthn_creds_mod.max_creds_per_account]services_mod.Services.WebauthnListEntry = undefined;
        const listed = svc.webauthnList(account, entries[0..]) catch
            return self.failReply(conn, "WEBAUTHN", "INTERNAL_ERROR", "Could not read passkeys");
        var b: [128]u8 = undefined;
        const body = std.fmt.bufPrint(&b, "STATUS :{d} passkey(s) registered", .{listed.len}) catch return;
        try self.webauthnReply(conn, body);
    }

    /// `WEBAUTHN REGISTER [label]` — issue a registration challenge to the
    /// caller's own logged-in account.
    fn webauthnRegister(self: *LinuxServer, conn: *ConnState, rp: WebauthnRp, p: []const []const u8) !void {
        const account = conn.session.account() orelse
            return self.failReply(conn, "WEBAUTHN", "NOT_LOGGED_IN", "Log in before registering a passkey");
        const label = if (p.len >= 2) p[1] else "";
        if (label.len > webauthn_creds_mod.max_label_bytes)
            return self.failReply(conn, "WEBAUTHN", "LABEL_TOO_LONG", "Passkey label is too long");
        if (!webauthn_creds_mod.validLabel(label))
            return self.failReply(conn, "WEBAUTHN", "BAD_LABEL", "Passkey label contains control characters");
        var challenge: [webauthn_creds_mod.challenge_len]u8 = undefined;
        if (!self.webauthnChallenge(&challenge))
            return self.failReply(conn, "WEBAUTHN", "TEMPORARILY_UNAVAILABLE", "No randomness source configured");
        conn.webauthn_pending.arm(.register, challenge, label, self.nowMs());

        var cb: [base64url.encodedLen(webauthn_creds_mod.challenge_len)]u8 = undefined;
        const chal_b64 = base64url.encode(&cb, &challenge) catch return;
        var b: [512]u8 = undefined;
        const body = std.fmt.bufPrint(&b, "REGISTER-CHALLENGE {s} {s} :{s}", .{ chal_b64, rp.rp_id, account }) catch return;
        try self.webauthnReply(conn, body);
    }

    /// `WEBAUTHN REGISTER-FINISH <cred_id_b64> <client_data_json_b64> <authdata_b64> [attestation_object_b64]`
    /// — verify the ceremony and store the credential.
    ///
    /// When the optional 4th arg (`attestationObject`, CBOR {fmt, attStmt,
    /// authData}) is present, the attestation statement is cryptographically
    /// verified (packed self/basic, fido-u2f; `none` accepted as unattested
    /// unless `[webauthn] require_attestation`). When absent, the legacy
    /// trust-on-first-use path runs over the raw `authData` (3-arg form) — this
    /// keeps existing clients byte-identical. `[webauthn] require_uv` (when set)
    /// additionally requires the UV flag on either path.
    fn webauthnRegisterFinish(self: *LinuxServer, conn: *ConnState, svc: *services_mod.Services, rp: WebauthnRp, p: []const []const u8) !void {
        const account = conn.session.account() orelse
            return self.failReply(conn, "WEBAUTHN", "NOT_LOGGED_IN", "Log in before registering a passkey");
        if (p.len < 4)
            return self.failReply(conn, "WEBAUTHN", "NEED_MORE_PARAMS", "Usage: WEBAUTHN REGISTER-FINISH <cred_id> <client_data_json> <authdata> [attestation_object]");
        const cred_id_b64 = p[1];
        // Consume the single-use challenge FIRST (cleared regardless of outcome).
        const taken = conn.webauthn_pending.take(.register, self.nowMs()) orelse
            return self.failReply(conn, "WEBAUTHN", "NO_PENDING", "No pending registration challenge (expired or never issued)");
        const label = taken.aux();

        if (!webauthn_creds_mod.validCredIdB64(cred_id_b64))
            return self.failReply(conn, "WEBAUTHN", "BAD_CREDENTIAL_ID", "Malformed credential id");

        // Decode clientDataJSON.
        var cdj_buf: [webauthn_creds_mod.max_client_data_bytes]u8 = undefined;
        const client_data_json = base64url.decode(&cdj_buf, p[2]) catch
            return self.failReply(conn, "WEBAUTHN", "BAD_CLIENT_DATA", "clientDataJSON is not valid base64url");

        // Bind clientDataJSON: type == webauthn.create, challenge, origin.
        var json_scratch: [16384]u8 = undefined;
        const cd = webauthn_creds_mod.parseClientData(client_data_json, &json_scratch) catch
            return self.failReply(conn, "WEBAUTHN", "BAD_CLIENT_DATA", "clientDataJSON did not parse");
        if (!std.mem.eql(u8, cd.type_str, webauthn_creds_mod.type_create))
            return self.failReply(conn, "WEBAUTHN", "WRONG_TYPE", "clientDataJSON type is not webauthn.create");
        if (!webauthn_creds_mod.challengeMatchesB64(&taken.challenge, cd.challenge_b64))
            return self.failReply(conn, "WEBAUTHN", "CHALLENGE_MISMATCH", "clientDataJSON challenge does not match");
        if (!webauthn_creds_mod.originAllowed(cd.origin, rp.origins))
            return self.failReply(conn, "WEBAUTHN", "BAD_ORIGIN", "clientDataJSON origin is not allowed");

        // clientDataHash binds the attestation signature (attestation path).
        var client_data_hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(client_data_json, &client_data_hash, .{});

        const has_attestation = p.len >= 5;
        if (rp.require_attestation and !has_attestation)
            return self.failReply(conn, "WEBAUTHN", "ATTESTATION_REQUIRED", "This network requires a passkey attestation object");

        // Decode buffers live at function scope: `att` borrows whichever buffer
        // the taken branch fills, and that borrow must survive through
        // webauthnBind in the common tail below.
        var ao_buf: [webauthn_attobj_max]u8 = undefined;
        var ad_buf: [webauthn_authdata_max]u8 = undefined;
        var att: webauthn.AttestedCredential = undefined;
        var reg_sign_count: u32 = undefined;

        if (has_attestation) {
            const att_obj = base64url.decode(&ao_buf, p[4]) catch
                return self.failReply(conn, "WEBAUTHN", "BAD_ATTESTATION", "attestationObject is not valid base64url");
            const verified = webauthn.verifyAttestation(att_obj, .{
                .rp_id = rp.rp_id,
                .client_data_hash = client_data_hash,
                .require_uv = rp.require_uv,
                .require_attestation = rp.require_attestation,
            }) catch |err|
                return self.failReply(conn, "WEBAUTHN", webauthnAttestationFailCode(err), "Attestation verification failed");
            att = verified.credential;
            reg_sign_count = verified.sign_count;
        } else {
            // Legacy trust-on-first-use: verify authData binding only. Behaviour
            // is byte-identical to the pre-attestation command unless require_uv
            // is set (the sole added check on this path).
            const auth_data = base64url.decode(&ad_buf, p[3]) catch
                return self.failReply(conn, "WEBAUTHN", "BAD_AUTHDATA", "authenticatorData is not valid base64url");
            const ad = webauthn.parseAuthData(auth_data) catch
                return self.failReply(conn, "WEBAUTHN", "BAD_AUTHDATA", "authenticatorData did not parse");
            var rp_hash: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(rp.rp_id, &rp_hash, .{});
            if (!std.mem.eql(u8, &ad.rp_id_hash, &rp_hash))
                return self.failReply(conn, "WEBAUTHN", "RP_MISMATCH", "authenticatorData rpIdHash does not match rp_id");
            // User Presence is mandatory at registration (WebAuthn §7.1), matching
            // the attestation path (webauthn.verifyAttestation checks UP always).
            if (!webauthn.userPresent(ad))
                return self.failReply(conn, "WEBAUTHN", "USER_PRESENCE_REQUIRED", "authenticatorData has no user-presence (UP) flag");
            if (rp.require_uv and !webauthn.userVerified(ad))
                return self.failReply(conn, "WEBAUTHN", "USER_VERIFICATION_REQUIRED", "This network requires user verification (UV)");
            if (!webauthn.hasAttestedCredentialData(auth_data))
                return self.failReply(conn, "WEBAUTHN", "NO_CREDENTIAL", "authenticatorData carries no attested credential");
            att = webauthn.parseAttestedCredentialData(auth_data) catch
                return self.failReply(conn, "WEBAUTHN", "BAD_CREDENTIAL", "Could not parse attested credential data");
            reg_sign_count = ad.sign_count;
        }

        // Cross-check the embedded credential id against the presented id.
        var cred_id_raw: [webauthn_creds_mod.max_cred_id_bytes]u8 = undefined;
        const cred_id = base64url.decode(&cred_id_raw, cred_id_b64) catch
            return self.failReply(conn, "WEBAUTHN", "BAD_CREDENTIAL_ID", "Malformed credential id");
        if (!std.mem.eql(u8, cred_id, att.credential_id))
            return self.failReply(conn, "WEBAUTHN", "CREDENTIAL_ID_MISMATCH", "credential id does not match authenticatorData");

        // Validate the COSE key is a supported public key we can verify later.
        _ = webauthn.parseCoseKey(att.cose_public_key) catch
            return self.failReply(conn, "WEBAUTHN", "UNSUPPORTED_KEY", "Unsupported credential public key (need ES256 or Ed25519)");

        // Store, keyed by credential id, bound to the account. The registration
        // signCount seeds the stored monotonic counter.
        svc.webauthnBind(account, cred_id_b64, att.cose_public_key, reg_sign_count, label, @divTrunc(platform.realtimeMillis(), 1000)) catch |err| {
            const code: []const u8 = switch (err) {
                error.AlreadyExists => "ALREADY_REGISTERED",
                error.InvalidValue => "BAD_CREDENTIAL",
                else => "STORE_FAILED",
            };
            return self.failReply(conn, "WEBAUTHN", code, "Could not store the passkey");
        };

        var b: [512]u8 = undefined;
        const body = std.fmt.bufPrint(&b, "REGISTERED {s} :{s}", .{ cred_id_b64, label }) catch return;
        try self.webauthnReply(conn, body);
    }

    /// Map a `webauthn.verifyAttestation` error to a stable FAIL code. The
    /// `else` default covers the folded
    /// signature/encoding failure sets (all render as a generic verify failure).
    fn webauthnAttestationFailCode(err: webauthn.AttestationError) []const u8 {
        return switch (err) {
            error.RpIdHashMismatch => "RP_MISMATCH",
            error.UserPresenceRequired => "USER_PRESENCE_REQUIRED",
            error.UserVerificationRequired => "USER_VERIFICATION_REQUIRED",
            error.AttestationRequired => "ATTESTATION_REQUIRED",
            error.UnsupportedFormat => "UNSUPPORTED_ATTESTATION",
            error.AttestationAlgMismatch => "ATTESTATION_ALG_MISMATCH",
            error.UnsupportedAttestationKey => "UNSUPPORTED_ATTESTATION_KEY",
            error.InvalidCredentialData => "NO_CREDENTIAL",
            error.TooShort => "BAD_AUTHDATA",
            error.MalformedAttestation, error.MissingAttestationField => "BAD_ATTESTATION",
            error.Overflow, error.InvalidEncoding, error.UnexpectedType, error.MapKeyNotFound => "BAD_ATTESTATION",
            error.UnsupportedAlgorithm, error.MissingField, error.InvalidKeyType, error.InvalidCurve, error.InvalidKeyLength => "UNSUPPORTED_KEY",
            else => "ATTESTATION_VERIFY_FAILED",
        };
    }

    /// `WEBAUTHN AUTH <account>` — issue an authentication challenge + the
    /// account's allowed credential ids (caller not yet identified).
    fn webauthnAuth(self: *LinuxServer, conn: *ConnState, svc: *services_mod.Services, rp: WebauthnRp, p: []const []const u8) !void {
        if (p.len < 2)
            return self.failReply(conn, "WEBAUTHN", "NEED_MORE_PARAMS", "Usage: WEBAUTHN AUTH <account>");
        const account = p[1];
        if (account.len == 0 or account.len > account_register.MAX_ACCOUNT_BYTES)
            return self.failReply(conn, "WEBAUTHN", "BAD_ACCOUNT", "Invalid account name");

        // Gate challenge issuance behind the shared login lockout: once an
        // account/IP is throttled by failed AUTH-FINISH (or password) attempts,
        // refuse to mint further challenges or disclose credential ids — this
        // ties the passkey allow-list oracle to the same brute-force backpressure
        // as every other login surface. (AUTH itself records no failure, so a
        // legitimate user who abandons a ceremony is never penalised.)
        if (self.loginLockedFor(conn, account)) |retry_ms| return self.rejectLoginLocked(conn, retry_ms);

        var challenge: [webauthn_creds_mod.challenge_len]u8 = undefined;
        if (!self.webauthnChallenge(&challenge))
            return self.failReply(conn, "WEBAUTHN", "TEMPORARILY_UNAVAILABLE", "No randomness source configured");
        conn.webauthn_pending.arm(.auth, challenge, account, self.nowMs());

        var cb: [base64url.encodedLen(webauthn_creds_mod.challenge_len)]u8 = undefined;
        const chal_b64 = base64url.encode(&cb, &challenge) catch return;
        var b: [512]u8 = undefined;
        const body = std.fmt.bufPrint(&b, "AUTH-CHALLENGE {s} {s} :{s}", .{ chal_b64, rp.rp_id, account }) catch return;
        try self.webauthnReply(conn, body);

        // Advertise the account's allowed credential ids (for non-discoverable
        // authenticators). A malformed account or none registered simply yields
        // an empty allow-list — the ceremony still fails closed at AUTH-FINISH.
        var entries: [webauthn_creds_mod.max_creds_per_account]services_mod.Services.WebauthnListEntry = undefined;
        const listed = svc.webauthnList(account, entries[0..]) catch entries[0..0];
        for (listed) |*e| {
            var lb: [webauthn_creds_mod.max_cred_id_b64 + 32]u8 = undefined;
            const line = std.fmt.bufPrint(&lb, "ALLOW-CRED {s}", .{e.credId()}) catch continue;
            try self.webauthnReply(conn, line);
        }
    }

    /// `WEBAUTHN AUTH-FINISH <cred_id> <client_data_json_b64> <authdata_b64> <sig_b64>`
    /// — verify the assertion and, on success, log the caller into the bound
    /// account via the shared IDENTIFY login path (`finishLogin`).
    fn webauthnAuthFinish(self: *LinuxServer, conn: *ConnState, svc: *services_mod.Services, rp: WebauthnRp, p: []const []const u8) !void {
        if (p.len < 5)
            return self.failReply(conn, "WEBAUTHN", "NEED_MORE_PARAMS", "Usage: WEBAUTHN AUTH-FINISH <cred_id> <client_data_json> <authdata> <signature>");
        const cred_id_b64 = p[1];
        // Consume the single-use challenge FIRST (cleared regardless of outcome).
        const taken = conn.webauthn_pending.take(.auth, self.nowMs()) orelse
            return self.failReply(conn, "WEBAUTHN", "NO_PENDING", "No pending authentication challenge (expired or never issued)");
        const target_account = taken.aux();

        // Brute-force guard: a failed passkey assertion counts against the same
        // login throttle as a password attempt.
        if (self.loginLockedFor(conn, target_account)) |retry_ms| return self.rejectLoginLocked(conn, retry_ms);

        if (!webauthn_creds_mod.validCredIdB64(cred_id_b64))
            return self.webauthnAuthFail(conn, target_account, "BAD_CREDENTIAL_ID", "Malformed credential id");

        // Decode the base64url wire args.
        var cdj_buf: [webauthn_creds_mod.max_client_data_bytes]u8 = undefined;
        const client_data_json = base64url.decode(&cdj_buf, p[2]) catch
            return self.webauthnAuthFail(conn, target_account, "BAD_CLIENT_DATA", "clientDataJSON is not valid base64url");
        var ad_buf: [webauthn_authdata_max]u8 = undefined;
        const auth_data = base64url.decode(&ad_buf, p[3]) catch
            return self.webauthnAuthFail(conn, target_account, "BAD_AUTHDATA", "authenticatorData is not valid base64url");
        var sig_buf: [256]u8 = undefined;
        const signature = base64url.decode(&sig_buf, p[4]) catch
            return self.webauthnAuthFail(conn, target_account, "BAD_SIGNATURE", "signature is not valid base64url");

        // Bind clientDataJSON: type == webauthn.get, challenge, origin.
        var json_scratch: [16384]u8 = undefined;
        const cd = webauthn_creds_mod.parseClientData(client_data_json, &json_scratch) catch
            return self.webauthnAuthFail(conn, target_account, "BAD_CLIENT_DATA", "clientDataJSON did not parse");
        if (!std.mem.eql(u8, cd.type_str, webauthn_creds_mod.type_get))
            return self.webauthnAuthFail(conn, target_account, "WRONG_TYPE", "clientDataJSON type is not webauthn.get");
        if (!webauthn_creds_mod.challengeMatchesB64(&taken.challenge, cd.challenge_b64))
            return self.webauthnAuthFail(conn, target_account, "CHALLENGE_MISMATCH", "clientDataJSON challenge does not match");
        if (!webauthn_creds_mod.originAllowed(cd.origin, rp.origins))
            return self.webauthnAuthFail(conn, target_account, "BAD_ORIGIN", "clientDataJSON origin is not allowed");

        // Look up the stored credential. It MUST be bound to the target account.
        var cred: services_mod.Services.WebauthnCredential = .{};
        svc.webauthnLookup(cred_id_b64, &cred) catch
            return self.webauthnAuthFail(conn, target_account, "UNKNOWN_CREDENTIAL", "No such passkey");
        if (!std.ascii.eqlIgnoreCase(cred.account(), target_account))
            return self.webauthnAuthFail(conn, target_account, "CREDENTIAL_ACCOUNT_MISMATCH", "Passkey is not bound to that account");

        const cose_key = webauthn.parseCoseKey(cred.coseKey()) catch
            return self.webauthnAuthFail(conn, target_account, "STORED_KEY_INVALID", "Stored credential key is unreadable");

        // Verify the assertion: signature + rpIdHash + UP flag + sign_count
        // monotonic regression (clone detection). verifyAssertion returns the
        // authenticator's counter on success.
        const new_count = webauthn.verifyAssertion(auth_data, client_data_json, signature, .{
            .rp_id = rp.rp_id,
            .credential_public_key = cose_key,
            .stored_sign_count = cred.sign_count,
            .require_uv = rp.require_uv,
        }) catch |err| {
            const code: []const u8 = switch (err) {
                error.CounterRegression => "SIGN_COUNT_REGRESSION",
                error.RpIdHashMismatch => "RP_MISMATCH",
                error.UserPresenceRequired => "USER_PRESENCE_REQUIRED",
                error.UserVerificationRequired => "USER_VERIFICATION_REQUIRED",
                else => "ASSERTION_FAILED",
            };
            return self.webauthnAuthFail(conn, target_account, code, "Passkey assertion rejected");
        };

        // Persist the advanced counter (best-effort; a store hiccup must not
        // fail an already-verified login, but a monotonic counter is important
        // for clone detection, so surface nothing and continue on error).
        if (new_count > cred.sign_count) svc.webauthnUpdateSignCount(cred_id_b64, new_count) catch {};

        // Success: clear the throttle and log the caller in via the shared path.
        // Log in as the CANONICAL stored owner (cred.account(), already lowercased
        // at bind time), not the client-echoed AUTH argument case-variant — the
        // eqlIgnoreCase gate above already proved they name the same account, and
        // downstream account keying (metadata/silence restore) is case-sensitive.
        self.loginRecordSuccess(conn, target_account);
        self.finishLogin(conn, cred.account()) catch |err| switch (err) {
            error.StorePoisoned => return self.failReply(conn, "WEBAUTHN", "TEMPORARILY_UNAVAILABLE", "Account storage requires recovery"),
            else => return err,
        };
        var b: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :You are now identified as {s}\r\n", .{ self.serverName(), conn.session.displayName(), conn.session.account() orelse target_account }) catch return;
        try emitReplyLine(conn, line);
    }

    /// Record a failed passkey assertion against the brute-force throttle and
    /// send a FAIL reply. Shared by every AUTH-FINISH rejection path so a probe
    /// can't distinguish "wrong account" from "bad signature" by throttle state.
    fn webauthnAuthFail(self: *LinuxServer, conn: *ConnState, account: []const u8, code: []const u8, reason: []const u8) !void {
        self.loginRecordFailure(conn, account);
        return self.failReply(conn, "WEBAUTHN", code, reason);
    }

    fn webauthnListCmd(self: *LinuxServer, conn: *ConnState, svc: *services_mod.Services) !void {
        const account = conn.session.account() orelse
            return self.failReply(conn, "WEBAUTHN", "NOT_LOGGED_IN", "Log in to list your passkeys");
        var entries: [webauthn_creds_mod.max_creds_per_account]services_mod.Services.WebauthnListEntry = undefined;
        const listed = svc.webauthnList(account, entries[0..]) catch
            return self.failReply(conn, "WEBAUTHN", "INTERNAL_ERROR", "Could not list passkeys");
        for (listed) |*e| {
            var b: [webauthn_creds_mod.max_cred_id_b64 + 128]u8 = undefined;
            // `CRED <credId> <sign_count> <created_unix> :<label>` — the 3rd
            // numeric column is backward-compatible (older clients parse it as
            // an optional field).
            const body = std.fmt.bufPrint(&b, "CRED {s} {d} {d} :{s}", .{ e.credId(), e.sign_count, e.created_unix, e.label() }) catch continue;
            try self.webauthnReply(conn, body);
        }
        var eb: [64]u8 = undefined;
        const end = std.fmt.bufPrint(&eb, "LIST :end ({d})", .{listed.len}) catch return;
        try self.webauthnReply(conn, end);
    }

    fn webauthnRemove(self: *LinuxServer, conn: *ConnState, svc: *services_mod.Services, p: []const []const u8) !void {
        const account = conn.session.account() orelse
            return self.failReply(conn, "WEBAUTHN", "NOT_LOGGED_IN", "Log in before removing a passkey");
        if (p.len < 2)
            return self.failReply(conn, "WEBAUTHN", "NEED_MORE_PARAMS", "Usage: WEBAUTHN REMOVE <cred_id|label>");
        const target = p[1];
        svc.webauthnDelete(account, target) catch |err| {
            const code: []const u8 = switch (err) {
                error.Forbidden => "NOT_OWNED",
                error.NotFound => "NOT_FOUND",
                else => "REMOVE_FAILED",
            };
            return self.failReply(conn, "WEBAUTHN", code, "No matching passkey bound to your account");
        };
        var b: [256]u8 = undefined;
        const body = std.fmt.bufPrint(&b, "REMOVED :{s}", .{target}) catch return;
        try self.webauthnReply(conn, body);
    }

    /// `WEBAUTHN RENAME <cred_id> :<label>` — update the stored label of a
    /// passkey the caller owns, keyed by credential id. Replies
    /// `WEBAUTHN RENAMED <cred_id> :<label>` through the Event Spine.
    fn webauthnRename(self: *LinuxServer, conn: *ConnState, svc: *services_mod.Services, p: []const []const u8) !void {
        const account = conn.session.account() orelse
            return self.failReply(conn, "WEBAUTHN", "NOT_LOGGED_IN", "Log in before renaming a passkey");
        if (p.len < 3)
            return self.failReply(conn, "WEBAUTHN", "NEED_MORE_PARAMS", "Usage: WEBAUTHN RENAME <cred_id> :<label>");
        const cred_id = p[1];
        const label = p[2];
        if (label.len > webauthn_creds_mod.max_label_bytes)
            return self.failReply(conn, "WEBAUTHN", "LABEL_TOO_LONG", "Passkey label is too long");
        if (!webauthn_creds_mod.validLabel(label))
            return self.failReply(conn, "WEBAUTHN", "BAD_LABEL", "Passkey label contains control characters");
        svc.webauthnRename(account, cred_id, label) catch |err| {
            const code: []const u8 = switch (err) {
                error.Forbidden => "NOT_OWNED",
                error.NotFound => "NOT_FOUND",
                error.InvalidValue => "BAD_CREDENTIAL_ID",
                else => "RENAME_FAILED",
            };
            return self.failReply(conn, "WEBAUTHN", code, "No matching passkey bound to your account");
        };
        var b: [256]u8 = undefined;
        const body = std.fmt.bufPrint(&b, "RENAMED {s} :{s}", .{ cred_id, label }) catch return;
        try self.webauthnReply(conn, body);
    }

    /// `ACCOUNTSET <account> <password> <field> <value>` — update an account
    /// setting (field = `email` or `flags`). Backed by services.setAccount.
    pub fn handleAccountSet(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const svc = self.account_services orelse return self.failReply(conn, "ACCOUNTSET", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        if (parsed.param_count < 4) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"ACCOUNTSET"}, "Usage: ACCOUNTSET <account> <password> <email|flags|secure|enforce> <value>");
            return;
        }
        const p = parsed.paramSlice();
        const account = p[0];
        const field: services_mod.AccountSetField = blk: {
            if (std.ascii.eqlIgnoreCase(p[2], "email")) break :blk .{ .email = p[3] };
            if (std.ascii.eqlIgnoreCase(p[2], "flags")) {
                const flags = std.fmt.parseInt(u32, p[3], 10) catch {
                    try self.failReply(conn, "ACCOUNTSET", "INVALID_VALUE", "flags must be a number");
                    return;
                };
                break :blk .{ .flags = flags };
            }
            // SECURE: recognize this account only via identify. ENFORCE: protect
            // the registered nick from unauthenticated holders (on by default).
            if (std.ascii.eqlIgnoreCase(p[2], "secure")) {
                const on = parseOnOff(p[3]) orelse {
                    try self.failReply(conn, "ACCOUNTSET", "INVALID_VALUE", "secure must be on or off");
                    return;
                };
                break :blk .{ .secure = on };
            }
            if (std.ascii.eqlIgnoreCase(p[2], "enforce")) {
                const on = parseOnOff(p[3]) orelse {
                    try self.failReply(conn, "ACCOUNTSET", "INVALID_VALUE", "enforce must be on or off");
                    return;
                };
                break :blk .{ .enforce = on };
            }
            try self.failReply(conn, "ACCOUNTSET", "INVALID_FIELD", "Unknown field (use email, flags, secure, or enforce)");
            return;
        };
        var scratch: [512]u8 = undefined;
        _ = svc.setAccount(account, p[1], field, &scratch) catch |err| {
            if (err == error.Forbidden) {
                try self.failReply(conn, "ACCOUNTSET", "PRIVILEGED_FLAGS", "Lifecycle flags require service_admin");
                return;
            }
            try queueNumeric(conn, .ERR_PASSWDMISMATCH, &.{}, "Invalid account or password");
            return;
        };
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :Account {s} updated ({s})\r\n", .{ self.serverName(), conn.session.displayName(), account, p[2] }) catch return;
        try emitReplyLine(conn, line);
    }

    /// `GHOST <nick> <password>` — disconnect a stale session occupying a nick
    /// that belongs to the caller's account (password-verified). The victim is
    /// torn down via the standard drain-close path.
    pub fn handleGhost(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const svc = self.account_services orelse return self.failReply(conn, "GHOST", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        if (parsed.param_count < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"GHOST"}, "Usage: GHOST <nick> <password>");
            return;
        }
        const target = parsed.paramSlice()[0];
        const account = conn.session.account() orelse {
            try self.failReply(conn, "GHOST", "ACCOUNT_REQUIRED", "Log in before ghosting a nick");
            return;
        };
        _ = svc.ghostAccount(account, parsed.paramSlice()[1], target) catch {
            try queueNumeric(conn, .ERR_PASSWDMISMATCH, &.{}, "Invalid account or password");
            return;
        };
        const victim_wid = self.world.findNick(target) orelse {
            try self.failReply(conn, "GHOST", "NICK_NOT_OWNED", "Nick is not logged in to your account");
            return;
        };
        const victim_id = clientIdFromWorld(victim_wid);
        const victim = self.connFor(victim_id) orelse {
            try self.failReply(conn, "GHOST", "NICK_NOT_OWNED", "Nick is not logged in to your account");
            return;
        };
        if (victim == conn) {
            try self.failReply(conn, "GHOST", "NICK_NOT_OWNED", "Cannot ghost your own session");
            return;
        }
        const victim_account = victim.session.account() orelse {
            try self.failReply(conn, "GHOST", "NICK_NOT_OWNED", "Nick is not logged in to your account");
            return;
        };
        if (!std.ascii.eqlIgnoreCase(victim_account, account)) {
            try self.failReply(conn, "GHOST", "NICK_NOT_OWNED", "Nick is not logged in to your account");
            return;
        }
        var buf: [default_reply_bytes]u8 = undefined;
        const ln = std.fmt.bufPrint(&buf, ":{s} ERROR :Ghosted by {s}\r\n", .{ self.serverName(), conn.session.displayName() }) catch return;
        try self.enqueueDeliveryThenClose(victim_id, ln, "Ghosted");
        const line = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :Ghost session for {s} removed\r\n", .{ self.serverName(), conn.session.displayName(), target }) catch return;
        try emitReplyLine(conn, line);
    }

    /// Shared RECOVER/RELEASE gate: whether `nick` maps to a registered account,
    /// and whether the requester is identified to (owns) that account. Both feed
    /// `svc_recover.decide`; kept in one place so the two commands never drift.
    fn recoverOwnership(svc: *services_mod.Services, conn: *ConnState, nick: []const u8) struct { registered: bool, owns: bool } {
        const registered = blk: {
            _ = svc.accountInfo(nick) catch break :blk false;
            break :blk true;
        };
        const owns = if (conn.session.account()) |a| svc_recover.namesEqual(a, nick) else false;
        return .{ .registered = registered, .owns = owns };
    }

    /// `RECOVER <nick>` — the account owner forces an unauthenticated holder off
    /// their registered nick immediately (instead of waiting out the protection
    /// grace), then briefly holds the nick (nick-delay) so the owner can reclaim
    /// it. The requester MUST be identified to the account that owns the nick.
    /// Real server command; decision logic is the pure `svc_recover`.
    pub fn handleRecover(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const svc = self.account_services orelse return self.failReply(conn, "RECOVER", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"RECOVER"}, "Usage: RECOVER <nick>");
            return;
        }
        const nick = parsed.paramSlice()[0];
        const gate = recoverOwnership(svc, conn, nick);

        // Holder state: is some OTHER live connection sitting on the nick, and is
        // it the owner's own authed session (which must never be ejected)?
        var holder_present = false;
        var holder_authed = false;
        var holder_wid: ?world_model.ClientId = null;
        if (self.world.findNick(nick)) |wid| {
            const id = clientIdFromWorld(wid);
            if (self.connFor(id)) |hc| {
                if (hc != conn) {
                    holder_present = true;
                    holder_wid = wid;
                    if (hc.session.account()) |ha| holder_authed = svc_recover.namesEqual(ha, nick);
                }
            }
        }

        switch (svc_recover.decide(.{
            .command = .recover,
            .nick_is_registered = gate.registered,
            .requester_owns_account = gate.owns,
            .holder_present = holder_present,
            .holder_authenticated_to_owner = holder_authed,
            .reservation_held = false,
        })) {
            .no_such_account => try self.failReply(conn, "RECOVER", "NICK_NOT_REGISTERED", "That nick is not registered"),
            .not_owner => try self.failReply(conn, "RECOVER", "ACCESS_DENIED", "You must be identified to that account to recover its nick"),
            .nothing_to_recover => try self.noticeTo(conn, "RECOVER: nobody else is holding that nick"),
            .recover_holder => {
                const wid = holder_wid.?;
                const id = clientIdFromWorld(wid);
                if (self.connFor(id)) |hc| {
                    var gbuf: [32]u8 = undefined;
                    const seed: u64 = @as(u64, @bitCast(id)) & 0xFFFFFF;
                    if (nick_enforcement.guestNick(&gbuf, seed)) |guest| {
                        self.forceRenameTo(id, hc, guest);
                        self.armSendIfNeeded(hc) catch {};
                    } else |_| {}
                }
                // Briefly hold the freed nick for the owner to reclaim.
                if (self.config.nick_delay_ms != 0) {
                    const expires = self.nowMs() + @as(i64, @intCast(self.config.nick_delay_ms));
                    self.nick_delay.hold(nick, expires, conn.session.account()) catch {};
                }
                var b: [default_reply_bytes]u8 = undefined;
                const note = std.fmt.bufPrint(&b, "RECOVER: forced the holder off {s}; reclaim it now", .{nick}) catch return;
                try self.noticeTo(conn, note);
            },
            .release_reservation => {},
        }
    }

    /// `RELEASE <nick>` — the account owner drops a server-held nick reservation
    /// (nick-delay) on their own registered nick ahead of its window, making the
    /// nick immediately available again. Requires identification to the account.
    pub fn handleRelease(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const svc = self.account_services orelse return self.failReply(conn, "RELEASE", "TEMPORARILY_UNAVAILABLE", "Accounts are unavailable");
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"RELEASE"}, "Usage: RELEASE <nick>");
            return;
        }
        const nick = parsed.paramSlice()[0];
        const gate = recoverOwnership(svc, conn, nick);
        const reservation_held = self.config.nick_delay_ms != 0 and self.nick_delay.check(nick, self.nowMs()) != null;

        switch (svc_recover.decide(.{
            .command = .release,
            .nick_is_registered = gate.registered,
            .requester_owns_account = gate.owns,
            .holder_present = false,
            .holder_authenticated_to_owner = false,
            .reservation_held = reservation_held,
        })) {
            .no_such_account => try self.failReply(conn, "RELEASE", "NICK_NOT_REGISTERED", "That nick is not registered"),
            .not_owner => try self.failReply(conn, "RELEASE", "ACCESS_DENIED", "You must be identified to that account to release its nick"),
            .nothing_to_recover => try self.noticeTo(conn, "RELEASE: there is no server hold on that nick"),
            .release_reservation => {
                self.nick_delay.release(nick);
                var b: [default_reply_bytes]u8 = undefined;
                const note = std.fmt.bufPrint(&b, "RELEASE: dropped the server hold on {s}", .{nick}) catch return;
                try self.noticeTo(conn, note);
            },
            .recover_holder => {},
        }
    }

    /// Emit a `NOTICE` from the server to this connection (services replies use
    /// real server NOTICEs — Onyx Server has NO pseudo-clients).
    fn channelNotice(conn: *ConnState, comptime fmt: []const u8, args: anytype) !void {
        // Assemble the header and the (reflected-args) body into ONE contiguous
        // line so the whole thing routes through the emitReplyLine guard —
        // otherwise a control byte in `args` would smuggle a forged line
        // (CWE-93). The header carries only the server name + the caller's own
        // (validated) nick; the guard covers the body's reflected fields.
        var buf: [default_reply_bytes]u8 = undefined;
        const head = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :", .{ protocol_inventory.currentServerName(), conn.session.displayName() }) catch return;
        const body = std.fmt.bufPrint(buf[head.len..], fmt ++ "\r\n", args) catch return;
        try emitReplyLine(conn, buf[0 .. head.len + body.len]);
    }

    /// `CHANNEL <subcommand> …` (alias `CS`) — channel registration services as a
    /// real server command (no pseudo-client). REGISTER/DROP/INFO are backed by
    /// `services.zig`; REGISTER/DROP additionally reflect into the live `+r`
    /// REGISTERED flag via the installed state hook. Founder/actor identity is the
    /// caller's logged-in account.
    pub fn handleChannel(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const svc = self.account_services orelse return self.failReply(conn, "CHANNEL", "TEMPORARILY_UNAVAILABLE", "Channel services are unavailable");
        if (parsed.param_count < 1) {
            try self.failReply(conn, "CHANNEL", "NEED_MORE_PARAMS", "Usage: CHANNEL <REGISTER|DROP|INFO|ACCESS|AKICK|SET|TRANSFER> <#channel> …");
            return;
        }
        const account = conn.session.account() orelse {
            try self.failReply(conn, "CHANNEL", "ACCOUNT_REQUIRED", "You must be logged in to use channel services");
            return;
        };
        // The CHANNEL parser expects argv[0] to be the command verb; paramSlice()
        // holds only the trailing params, so prepend the command token.
        var argv: [16][]const u8 = undefined;
        argv[0] = parsed.command;
        const params = parsed.paramSlice();
        const take = @min(params.len, argv.len - 1);
        for (params[0..take], 0..) |p, i| argv[1 + i] = p;
        const req = chanserv_cmd.parse(argv[0 .. 1 + take]) catch {
            try self.failReply(conn, "CHANNEL", "INVALID_PARAMS", "Bad CHANNEL syntax");
            return;
        };
        var scratch: [2048]u8 = undefined;
        switch (req) {
            .register => |r| {
                _ = svc.registerChannel(r.channel, account, &scratch) catch |err| {
                    try self.failReply(conn, "CHANNEL", channelFailCode(err), "Channel registration failed");
                    return;
                };
                try channelNotice(conn, "Channel {s} registered to {s}", .{ r.channel, account });
            },
            .drop => |r| {
                _ = svc.dropChannel(r.channel, account) catch |err| {
                    try self.failReply(conn, "CHANNEL", channelFailCode(err), "Channel drop failed");
                    return;
                };
                try channelNotice(conn, "Channel {s} dropped", .{r.channel});
            },
            .info => |r| {
                const result = svc.channelInfo(r.channel) catch |err| {
                    try self.failReply(conn, "CHANNEL", channelFailCode(err), "No such registered channel");
                    return;
                };
                const ci = result.channel_info;
                const mlock = ci.mlock.asSlice();
                const topiclock = (ci.flags & services_mod.channel_flag_topiclock) != 0;
                const guard = (ci.flags & services_mod.channel_flag_guard) != 0;
                const private = (ci.flags & services_mod.channel_flag_private) != 0;
                try channelNotice(conn, "channel={s} founder={s} flags={d} mlock={s} topiclock={} guard={} private={}", .{ ci.name.asSlice(), ci.founder.asSlice(), ci.flags, mlock, topiclock, guard, private });
                var meta_buf: [512]u8 = undefined;
                if (svc.chanDescGet(r.channel, &meta_buf)) |desc| {
                    try channelNotice(conn, "  desc: {s}", .{desc});
                }
                if (svc.chanUrlGet(r.channel, &meta_buf)) |url| {
                    try channelNotice(conn, "  url: {s}", .{url});
                }
            },
            .set => |r| {
                // Only the registered founder may SET channel properties.
                const info = svc.channelInfo(r.channel) catch |err| {
                    try self.failReply(conn, "CHANNEL", channelFailCode(err), "No such registered channel");
                    return;
                };
                if (!std.ascii.eqlIgnoreCase(info.channel_info.founder.asSlice(), account)) {
                    try self.failReply(conn, "CHANNEL", "ACCESS_DENIED", "Only the founder may SET channel properties");
                    return;
                }
                if (r.field == .mlock) {
                    _ = mode_lock_mod.LockSpec.parse(r.value) catch {
                        try self.failReply(conn, "CHANNEL", "INVALID_PARAMS", "Bad MLOCK spec (e.g. +nt-k)");
                        return;
                    };
                    _ = svc.setChannel(r.channel, account, .{ .mlock = r.value }, &scratch) catch |err| {
                        try self.failReply(conn, "CHANNEL", channelFailCode(err), "Could not persist MLOCK");
                        return;
                    };
                    self.setMlock(r.channel, r.value) catch {
                        try self.failReply(conn, "CHANNEL", "TEMPORARILY_UNAVAILABLE", "Could not store MLOCK");
                        return;
                    };
                    try channelNotice(conn, "Channel {s} MLOCK set to {s}", .{ r.channel, r.value });
                } else if (r.field == .keeptopic) {
                    const on = std.ascii.eqlIgnoreCase(r.value, "on") or std.ascii.eqlIgnoreCase(r.value, "true") or std.ascii.eqlIgnoreCase(r.value, "yes") or std.mem.eql(u8, r.value, "1");
                    svc.chanKeepTopicEnable(r.channel, on) catch {
                        try self.failReply(conn, "CHANNEL", "TEMPORARILY_UNAVAILABLE", "Could not store KEEPTOPIC");
                        return;
                    };
                    // On enable, snapshot the current live topic — with its setter
                    // and set-time — so recreation restores all three, not a fake
                    // serverName()/now.
                    if (on) {
                        if (self.world.topicInfo(r.channel)) |cur| {
                            if (cur.text.len != 0) svc.chanKeepTopicSave(r.channel, cur.text, cur.setter, cur.set_at) catch {};
                        }
                    }
                    try channelNotice(conn, "Channel {s} KEEPTOPIC {s}", .{ r.channel, if (on) "on" else "off" });
                } else if (r.field == .topiclock or r.field == .guard or r.field == .private) {
                    // Boolean settings persisted as channel-record flags. GUARD and
                    // PRIVATE also take immediate live effect (see below).
                    const on = setFieldBoolOn(r.value);
                    const flag: u32 = switch (r.field) {
                        .topiclock => services_mod.channel_flag_topiclock,
                        .guard => services_mod.channel_flag_guard,
                        .private => services_mod.channel_flag_private,
                        else => unreachable,
                    };
                    svc.setChannelFlag(r.channel, account, flag, on, &scratch) catch |err| {
                        try self.failReply(conn, "CHANNEL", channelFailCode(err), "Could not store channel setting");
                        return;
                    };
                    // PRIVATE flips the live channel's secret flag so it drops out of
                    // public LIST/NAMES enumeration immediately, not just on recreate.
                    if (r.field == .private and self.world.channelExists(r.channel)) {
                        _ = self.world.setChannelFlag(r.channel, .secret, on) catch {};
                    }
                    try channelNotice(conn, "Channel {s} {s} {s}", .{ r.channel, @tagName(r.field), if (on) "on" else "off" });
                } else if (r.field == .desc) {
                    svc.chanDescSet(r.channel, r.value) catch |err| {
                        try self.failReply(conn, "CHANNEL", channelFailCode(err), "Could not store DESC");
                        return;
                    };
                    if (r.value.len == 0) {
                        try channelNotice(conn, "Channel {s} DESC cleared", .{r.channel});
                    } else {
                        try channelNotice(conn, "Channel {s} DESC set", .{r.channel});
                    }
                } else if (r.field == .url) {
                    svc.chanUrlSet(r.channel, r.value) catch |err| {
                        try self.failReply(conn, "CHANNEL", channelFailCode(err), "Could not store URL");
                        return;
                    };
                    if (r.value.len == 0) {
                        try channelNotice(conn, "Channel {s} URL cleared", .{r.channel});
                    } else {
                        try channelNotice(conn, "Channel {s} URL set to {s}", .{ r.channel, r.value });
                    }
                } else {
                    try channelNotice(conn, "CHANNEL SET {s} is not available yet", .{@tagName(r.field)});
                }
            },
            .access => |r| {
                if (r.action == .list and r.account == null) {
                    var entries_buf: [64]services_mod.AccessInfo = undefined;
                    const entries = svc.channelAccessList(r.channel, account, &entries_buf) catch |err| {
                        try self.failReply(conn, "CHANNEL", channelFailCode(err), "Channel access list failed");
                        return;
                    };
                    for (entries) |access| {
                        try channelNotice(conn, "ACCESS {s} {s} {s}", .{ access.channel.asSlice(), access.account.asSlice(), channelAccessLevelName(access.level) });
                    }
                    try channelNotice(conn, "End of ACCESS list for {s}", .{r.channel});
                    return;
                }

                const target = r.account orelse {
                    try self.failReply(conn, "CHANNEL", "NEED_MORE_PARAMS", "Usage: CHANNEL ACCESS <#channel> <ADD|DEL|LIST> <account> <FOUNDER|OP|VOICE>");
                    return;
                };
                const level = channelAccessLevel(r.level orelse .voice) orelse {
                    try self.failReply(conn, "CHANNEL", "INVALID_PARAMS", "ACCESS level AKICK belongs under CHANNEL AKICK");
                    return;
                };
                const action: services_mod.AccessAction = switch (r.action) {
                    .add => .grant,
                    .del => .revoke,
                    .list => .query,
                };
                const result = svc.channelAccess(r.channel, account, target, action, level, &scratch) catch |err| {
                    try self.failReply(conn, "CHANNEL", channelFailCode(err), "Channel access operation failed");
                    return;
                };
                switch (result) {
                    .access => |access| try channelNotice(conn, "ACCESS {s} {s} {s}", .{ access.channel.asSlice(), access.account.asSlice(), channelAccessLevelName(access.level) }),
                    .access_revoked => |access| try channelNotice(conn, "ACCESS removed {s} {s} {s}", .{ access.channel.asSlice(), access.account.asSlice(), channelAccessLevelName(access.level) }),
                    else => try channelNotice(conn, "ACCESS updated {s}", .{r.channel}),
                }
            },
            .akick => |r| {
                switch (r.action) {
                    .list => {
                        if (r.mask) |mask| {
                            const result = svc.channelAkick(r.channel, account, mask, .query, "", &scratch) catch |err| {
                                try self.failReply(conn, "CHANNEL", channelFailCode(err), "Channel AKICK query failed");
                                return;
                            };
                            if (result == .akick) {
                                const ak = result.akick;
                                try channelNotice(conn, "AKICK {s} {s} :{s}", .{ ak.channel.asSlice(), ak.mask.asSlice(), ak.reason.asSlice() });
                            }
                        } else {
                            var entries_buf: [64]services_mod.AkickInfo = undefined;
                            const entries = svc.channelAkickList(r.channel, account, &entries_buf) catch |err| {
                                try self.failReply(conn, "CHANNEL", channelFailCode(err), "Channel AKICK list failed");
                                return;
                            };
                            for (entries) |ak| {
                                try channelNotice(conn, "AKICK {s} {s} :{s}", .{ ak.channel.asSlice(), ak.mask.asSlice(), ak.reason.asSlice() });
                            }
                            try channelNotice(conn, "End of AKICK list for {s}", .{r.channel});
                        }
                    },
                    .add => {
                        const mask = r.mask orelse {
                            try self.failReply(conn, "CHANNEL", "NEED_MORE_PARAMS", "Usage: CHANNEL AKICK <#channel> ADD <mask> [reason...]");
                            return;
                        };
                        const reason = try joinChannelAkickReason(r.reason, &scratch);
                        const result = svc.channelAkick(r.channel, account, mask, .add, reason, &scratch) catch |err| {
                            try self.failReply(conn, "CHANNEL", channelFailCode(err), "Channel AKICK add failed");
                            return;
                        };
                        if (result == .akick) {
                            const ak = result.akick;
                            self.chan_akick.add(ak.channel.asSlice(), ak.mask.asSlice(), ak.reason.asSlice(), account, self.nowMs(), null) catch |err| {
                                try self.failReply(conn, "CHANNEL", akickLiveFailCode(err), "Channel AKICK live mirror failed");
                                return;
                            };
                            try self.kickCurrentAkickMatches(ak.channel.asSlice(), ak.mask.asSlice(), ak.reason.asSlice());
                            try channelNotice(conn, "AKICK added on {s}: {s}", .{ ak.channel.asSlice(), ak.mask.asSlice() });
                        }
                    },
                    .del => {
                        const mask = r.mask orelse {
                            try self.failReply(conn, "CHANNEL", "NEED_MORE_PARAMS", "Usage: CHANNEL AKICK <#channel> DEL <mask>");
                            return;
                        };
                        const result = svc.channelAkick(r.channel, account, mask, .remove, "", &scratch) catch |err| {
                            try self.failReply(conn, "CHANNEL", channelFailCode(err), "Channel AKICK delete failed");
                            return;
                        };
                        if (result == .akick_removed) {
                            const ak = result.akick_removed;
                            _ = self.chan_akick.remove(ak.channel.asSlice(), ak.mask.asSlice());
                            try channelNotice(conn, "AKICK removed on {s}: {s}", .{ ak.channel.asSlice(), ak.mask.asSlice() });
                        }
                    },
                }
            },
            .transfer => |r| {
                const result = svc.transferChannel(r.channel, account, r.account, &scratch) catch |err| {
                    try self.failReply(conn, "CHANNEL", channelFailCode(err), "Channel TRANSFER failed");
                    return;
                };
                if (result == .registered_channel) {
                    try channelNotice(conn, "Channel {s} founder transferred to {s}", .{ result.registered_channel.name.asSlice(), result.registered_channel.founder.asSlice() });
                }
            },
        }
    }

    /// Store (replace) a channel's services MLOCK spec, owning both strings.
    fn setMlock(self: *LinuxServer, channel: []const u8, spec: []const u8) !void {
        if (self.mlocks.getEntry(channel)) |e| {
            const new_spec = try self.allocator.dupe(u8, spec);
            self.allocator.free(e.value_ptr.*);
            e.value_ptr.* = new_spec;
            return;
        }
        const k = try self.allocator.dupe(u8, channel);
        errdefer self.allocator.free(k);
        const v = try self.allocator.dupe(u8, spec);
        errdefer self.allocator.free(v);
        try self.mlocks.put(self.allocator, k, v);
    }

    /// Map a services channel error to an IRCv3 standard-reply FAIL code.
    fn channelFailCode(err: anyerror) []const u8 {
        return switch (err) {
            error.AlreadyExists => "CHANNEL_EXISTS",
            error.NotFound => "CHANNEL_UNKNOWN",
            error.Forbidden => "ACCESS_DENIED",
            error.InvalidChannel, error.InvalidName => "BAD_CHANNEL_NAME",
            error.InvalidValue => "INVALID_PARAMS",
            else => "TEMPORARILY_UNAVAILABLE",
        };
    }

    /// Interpret a CHANNEL SET boolean value. Truthy: on/true/yes/1/enable/+.
    /// Everything else (including empty) is "off", so `SET <flag> off` clears it.
    fn setFieldBoolOn(value: []const u8) bool {
        return std.ascii.eqlIgnoreCase(value, "on") or
            std.ascii.eqlIgnoreCase(value, "true") or
            std.ascii.eqlIgnoreCase(value, "yes") or
            std.ascii.eqlIgnoreCase(value, "enable") or
            std.mem.eql(u8, value, "1") or
            std.mem.eql(u8, value, "+");
    }

    /// Generate a 16-byte session reclaim token from the daemon CSPRNG. With no
    /// crypto_io configured this yields the all-zero SENTINEL token: the session
    /// is still tracked (SESSION LIST / session-sync fan-out keep working), but
    /// `SESSION TOKEN` never reveals it and RESUME never honors it (see
    /// `tokenIsNull`) — a CSPRNG-less boot disables reclaim instead of silently
    /// minting one constant, guessable credential per account.
    fn genSessionToken(self: *LinuxServer) sessions_mod.Token {
        var t: sessions_mod.Token = @splat(0);
        if (self.config.crypto_io) |io| io.random(&t);
        return t;
    }

    /// The all-zero "no reclaim token" sentinel (crypto_io unset at issue time).
    /// Refused everywhere a token acts as a credential — fail closed. (A real
    /// CSPRNG token is all-zero with probability 2^-128; refusing it too is the
    /// cheap fail-closed side of that coin.)
    fn tokenIsNull(t: sessions_mod.Token) bool {
        return std.mem.allEqual(u8, &t, 0);
    }

    fn portableSessionTokenForClient(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *const ConnState,
    ) ?session_migrate.Token {
        const account = conn.session.account() orelse return null;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return null;
        if (!handle.portable or tokenIsNull(handle.token)) return null;
        return handle.token;
    }

    /// Queue one restored attachment's complete compatibility batch to one peer.
    /// A v2 secured peer gets the retained exact OFFER in the SAME outbound batch
    /// before NICK/MEMBERSHIP, so a cross-shard handoff cannot separate authority
    /// from its token-less rendering sidecars. On any encode/allocation failure,
    /// whatever prefix was already built remains in the link/connection queue and
    /// the caller keeps the deferred state for an idempotent full retry.
    fn queueDeferredSessionMeshAnnouncementsTo(
        self: *LinuxServer,
        peer_id: client_model.ClientId,
        link: anytype,
        id: client_model.ClientId,
        conn: *const ConnState,
    ) bool {
        if (comptime @TypeOf(link) == *secured_s2s_link.SecuredLink) {
            // A prior attempt owns a complete OFFER/sidecar ciphertext batch.
            // Drain it before regenerating HLC-bearing semantic frames; otherwise
            // every timer retry under a full peer SendQ appends another distinct
            // batch and grows the shared secured buffer without bound.
            if (!self.flushSecuredS2sOutboundTo(peer_id, link)) return false;
        }
        var complete = true;

        if (!conn.session_mesh_announce_token_bound) return false;
        const account = conn.session.account() orelse return false;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return false;
        if (!std.crypto.timing_safe.eql(
            sessions_mod.Token,
            handle.token,
            conn.session_mesh_announce_token,
        )) return false;
        const requires_authority = conn.session_mesh_announce_requires_authority or handle.portable;
        if (link.supportsSessionReplicaV2() and
            requires_authority)
        authority: {
            if (!conn.session_mesh_announce_token_bound) {
                complete = false;
                break :authority;
            }
            const entry = self.session_replica_store.getOrigin(
                conn.session_mesh_announce_token,
                self.config.node_id,
            ) orelse {
                complete = false;
                break :authority;
            };
            link.sendSessionReplica(.offer, entry.wire) catch {
                complete = false;
                break :authority;
            };
        }

        if (complete and
            conn.session_mesh_announce_parts.len != 0 and
            (conn.session_mesh_announce_nick_change or !requires_authority))
        {
            const old_len: usize = conn.session_mesh_announce_old_nick_len;
            const old_nick = if (old_len != 0)
                conn.session_mesh_announce_old_nick[0..old_len]
            else
                conn.session.displayName();
            const membership_hlc = self.nextMeshHlc();
            const old_identity = conn.session_mesh_announce_old_identity.view();
            for (conn.session_mesh_announce_parts) |*part| {
                link.sendMembership(
                    part.channel(),
                    old_nick,
                    0,
                    membership_hlc,
                    false,
                    old_identity,
                    "",
                ) catch {
                    complete = false;
                    break;
                };
            }
        }

        if (complete and conn.session_mesh_announce_nick_change) {
            const old_len: usize = conn.session_mesh_announce_old_nick_len;
            link.sendNickChange(
                conn.session_mesh_announce_old_nick[0..old_len],
                conn.session.displayName(),
                membershipIdentityOf(conn),
                self.nextMeshHlc(),
            ) catch {
                complete = false;
            };
        }

        if (complete) {
            const membership_hlc = self.nextMeshHlc();
            var channels = self.world.channelIterator();
            while (channels.next()) |channel| {
                const modes = self.world.memberModes(channel.name, worldIdFromClient(id)) orelse continue;
                link.sendMembership(
                    channel.name,
                    conn.session.displayName(),
                    @truncate(modes.bits),
                    membership_hlc,
                    true,
                    membershipIdentityOf(conn),
                    "",
                ) catch {
                    complete = false;
                    break;
                };
            }
        }

        if (comptime @TypeOf(link) == *secured_s2s_link.SecuredLink) {
            if (!self.flushSecuredS2sOutboundTo(peer_id, link)) return false;
        } else {
            const outbound = link.outbound();
            if (outbound.len == 0) return complete;
            if (peer_id.shard == self.rx().shard_id) {
                self.flushS2sOutboundTo(peer_id, outbound) catch return false;
                link.clearOutbound();
            } else {
                // Plaintext CRDT rows are idempotent; retain the original after
                // the prompt foreign-shard handoff until the owner flushes it.
                self.flushS2sOutboundTo(peer_id, outbound) catch {};
            }
        }
        return complete;
    }

    /// Emit the compatibility identity/membership sidecars for a successfully
    /// restored attachment. The signed token snapshot is the authority; pending
    /// state is cleared only after EVERY established eligible peer has accepted
    /// the complete OFFER -> NICK -> MEMBERSHIP batch into durable outbound or
    /// connection SendQ storage.
    fn flushDeferredSessionMeshAnnouncements(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
    ) void {
        if (!conn.session_mesh_announce_pending) return;

        var complete = true;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const peer_id = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    if (!self.queueDeferredSessionMeshAnnouncementsTo(peer_id, link, id, conn)) complete = false;
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    if (!self.queueDeferredSessionMeshAnnouncementsTo(peer_id, link, id, conn)) complete = false;
                }
            }
        }
        if (!complete) return;

        conn.session_mesh_announce_pending = false;
        conn.session_mesh_announce_token_bound = false;
        conn.session_mesh_announce_requires_authority = false;
        conn.session_mesh_announce_token = @splat(0);
        conn.session_mesh_announce_old_retracted = false;
        conn.session_mesh_announce_nick_change = false;
        conn.session_mesh_announce_old_nick_len = 0;
        conn.session_mesh_announce_old_identity = .{};
        self.clearDeferredSessionMeshParts(conn);
    }

    fn clearDeferredSessionMeshParts(self: *LinuxServer, conn: *ConnState) void {
        if (conn.session_mesh_announce_parts.len != 0)
            self.allocator.free(conn.session_mesh_announce_parts);
        conn.session_mesh_announce_parts = &.{};
    }

    /// A connection may close while its restored identity is still held behind
    /// the authority barrier. Retained predecessor-only channel departures are
    /// safe only while the predecessor alias is distinct. With a shared same nick,
    /// another attachment can join a formerly old-only channel before this pending
    /// claimant closes, so even a retained PART could evict live identity. When an
    /// exact identity still exists, never retract any same-nick channel or PRESENCE
    /// merely because this transport closed.
    fn retractDeferredSessionMeshIdentity(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        restored_identity_remains: bool,
    ) void {
        if (!conn.session_mesh_announce_pending or conn.session_mesh_announce_old_retracted) return;
        conn.session_mesh_announce_old_retracted = true;
        const old_nick = if (conn.session_mesh_announce_nick_change)
            conn.session_mesh_announce_old_nick[0..conn.session_mesh_announce_old_nick_len]
        else
            conn.session.displayName();
        if (old_nick.len == 0 or std.mem.eql(u8, old_nick, "*")) return;

        const old_identity = conn.session_mesh_announce_old_identity.view();
        const restored_nick = conn.session.displayName();
        const predecessor_parts_are_safe = !std.ascii.eqlIgnoreCase(old_nick, restored_nick);
        if (!restored_identity_remains or predecessor_parts_are_safe) {
            for (conn.session_mesh_announce_parts) |*part|
                self.announceMembership(part.channel(), old_nick, 0, false, old_identity, "");
        }
        if (restored_identity_remains) return;

        var channels = self.world.channelIterator();
        while (channels.next()) |channel| {
            if (!self.world.isMember(channel.name, worldIdFromClient(id))) continue;
            self.announceMembership(channel.name, old_nick, 0, false, old_identity, "");
            if (!std.ascii.eqlIgnoreCase(old_nick, restored_nick))
                self.announceMembership(channel.name, restored_nick, 0, false, membershipIdentityOf(conn), "");
        }
        self.announceMembership(presence_channel, old_nick, 0, false, old_identity, "");
        if (!std.ascii.eqlIgnoreCase(old_nick, restored_nick))
            self.announceMembership(presence_channel, restored_nick, 0, false, membershipIdentityOf(conn), "");
    }

    /// Arm a restored sidecar only after SessionStore accepted the exact group
    /// binding. Until this call, housekeeping must never infer readiness from a
    /// pre-existing token (or from the absence of one) after a failed attach.
    fn bindDeferredSessionMeshAnnouncements(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        token: sessions_mod.Token,
    ) void {
        if (!conn.session_mesh_announce_pending) return;
        const account = conn.session.account() orelse return;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return;
        if (!std.crypto.timing_safe.eql(sessions_mod.Token, handle.token, token)) return;
        conn.session_mesh_announce_token = token;
        conn.session_mesh_announce_token_bound = true;
        conn.session_mesh_announce_requires_authority = handle.portable;
    }

    /// Portability can be enabled after a non-portable restore has already armed
    /// a compatibility sidecar. Promote the barrier monotonically with the Store
    /// row so no later housekeeping turn can release that sidecar OFFER-less.
    fn markPortableResumeIssuedForConn(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
    ) bool {
        // Portability is irreversible for the lifetime of this reusable token:
        // every later detach/mutation owes peers an encodable canonical image.
        // Prove the current physical image fits the shared v2/legacy envelope
        // before flipping the durable bit or exposing MTOKEN to the client.
        const snapshot = self.encodeMigrationSnapshot(id, conn) orelse return false;
        defer self.allocator.free(snapshot);
        if (snapshot.len > session_portability.max_snapshot_len) return false;
        if (!self.sessions.markPortableResumeIssued(account, monitorIdFromClient(id))) return false;
        if (conn.session_mesh_announce_pending)
            conn.session_mesh_announce_requires_authority = true;
        return true;
    }

    /// A portable restore needs an exact signed projection before compatibility
    /// sidecars are released. A non-portable local TOKEN never crosses this
    /// privacy boundary and may use compatibility NICK/MEMBERSHIP directly.
    fn deferredSessionMeshAuthorityReady(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *const ConnState,
    ) bool {
        if (!conn.session_mesh_announce_pending or !conn.session_mesh_announce_token_bound) return false;
        const account = conn.session.account() orelse return false;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return false;
        if (!std.crypto.timing_safe.eql(
            sessions_mod.Token,
            handle.token,
            conn.session_mesh_announce_token,
        )) return false;
        if (!conn.session_mesh_announce_requires_authority and !handle.portable) return true;
        const token = conn.session_mesh_announce_token;
        if (self.sessions.tokenReplicaDirty(token) or self.sessions.tokenReplicaProjectionDirty(token)) return false;
        const entry = self.session_replica_store.getOrigin(token, self.config.node_id) orelse return false;
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        if (entry.quarantine_until_ms != null or now_wall > entry.expires_at_ms) return false;
        return std.ascii.eqlIgnoreCase(entry.account, account) and
            std.ascii.eqlIgnoreCase(entry.nick, conn.session.displayName());
    }

    /// Retry publication may complete on a later housekeeping turn. Flush every
    /// restored attachment whose exact authority is now live so allocation
    /// pressure delays compatibility routing instead of losing it permanently.
    fn flushReadyDeferredSessionMeshAnnouncements(self: *LinuxServer) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.session_mesh_announce_pending) continue;
                const conn = &slot.value;
                if (conn.closing or conn.s2s != null or conn.s2s_secured != null) continue;
                const id = slotClientId(reactor, i, slot.gen);
                if (conn.session_mesh_announce_token_bound and
                    !self.deferredSessionMeshAuthorityReady(id, conn))
                {
                    _ = self.publishCurrentSessionReplicaToken(conn.session_mesh_announce_token);
                }
                if (!self.deferredSessionMeshAuthorityReady(id, conn)) continue;
                self.flushDeferredSessionMeshAnnouncements(id, conn);
            }
        }
    }

    /// A successful reusable-session attach changes which mesh node is actively
    /// serving the token. Re-offer that attachment's freshly restored snapshot so
    /// this node learns reciprocal token routes to every secured peer; otherwise
    /// only the original issuer can fan messages across the logical session.
    fn refreshPortableSessionReplicas(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        token: session_migrate.Token,
    ) bool {
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return false;
        if (!std.crypto.timing_safe.eql(session_migrate.Token, handle.token, token)) return false;
        if (handle.portable) {
            if (!self.config.session_migrate_on_detach or self.config.node_identity == null) return false;
            return self.shipSessionMigration(id, conn, account, token);
        }
        return true;
    }

    /// Lifetime of a cross-server (mesh-sealed) reclaim token.
    const mesh_reclaim_ttl_ms: u64 = 12 * 60 * 60 * 1000;

    /// Positive attachment authority is deliberately much shorter than the
    /// portable OFFER. A live attachment will renew this 90-second lease every
    /// 30 seconds; silence therefore fails closed without deleting resumable
    /// identity state.
    const session_attachment_lease_ttl_ms: u64 = 90 * 1000;

    /// Lowercase-hex encode `bytes` into `out`, returning the written slice
    /// (runtime length — `std.fmt.bytesToHex` needs a comptime length).
    fn toHexLower(bytes: []const u8, out: []u8) []const u8 {
        const hexchars = "0123456789abcdef";
        var i: usize = 0;
        while (i < bytes.len and i * 2 + 1 < out.len) : (i += 1) {
            out[i * 2] = hexchars[bytes[i] >> 4];
            out[i * 2 + 1] = hexchars[bytes[i] & 0x0f];
        }
        return out[0 .. i * 2];
    }

    fn sessionTokenFromHex(hex: []const u8) ?sessions_mod.Token {
        if (hex.len != 2 * @sizeOf(sessions_mod.Token)) return null;
        var token: sessions_mod.Token = undefined;
        _ = std.fmt.hexToBytes(&token, hex) catch return null;
        if (tokenIsNull(token)) return null; // sentinel: never a reclaim credential
        return token;
    }

    /// Seal a cross-server (mesh) reclaim token for the caller's live session
    /// and write its lowercase hex into `out_hex`. Returns null when the mesh
    /// shared key is unset (cross-server reclaim then disabled) or sealing
    /// fails. `origin_node` is this server, so a peer can redirect the client
    /// home; `session_id` correlates the session at the origin.
    fn meshReclaimToken(self: *LinuxServer, account: []const u8, session_id: []const u8, out_hex: []u8) ?[]const u8 {
        const key = self.config.mesh_pass;
        if (key.len == 0) return null;
        // No CSPRNG => no fresh single-use nonce. A constant nonce would make
        // every issued token mutually "replay" each other (and the first consume
        // burn all later ones), so match the unset-mesh-key behavior: reclaim
        // disabled rather than silently degraded.
        const io = self.config.crypto_io orelse return null;
        // Portable credentials cross hosts, so their absolute issued/expiry
        // timestamps must use the mesh wall-clock domain. Host monotonic clocks
        // encode uptime and are not comparable between origin and reclaim node.
        const now = self.meshWallMs();
        var nb: [8]u8 = undefined;
        io.random(&nb);
        const nonce = std.mem.readInt(u64, &nb, .big);
        const fields = session_reclaim_mesh.ReclaimFields{
            .account = account,
            .session_id = session_id,
            // Bind placement to this server instance's configured mesh name.
            // The protocol-inventory global can describe a different test/node
            // instance in a multi-server process and produced false redirects.
            .origin_node = self.serverName(),
            .issued_ms = now,
            .expiry_ms = now + mesh_reclaim_ttl_ms,
            .nonce = nonce,
        };
        var raw: [512]u8 = undefined;
        const n = session_reclaim_mesh.seal(key, fields, &raw) catch return null;
        if (n * 2 > out_hex.len) return null;
        return toHexLower(raw[0..n], out_hex);
    }

    /// Mint an origin-signed, attachment-scoped SRM2 exact-restore claim. The
    /// first rollout binds destination to the issuer: another trusted node may
    /// verify and redirect to it, but may not restore a local same-token row.
    fn meshExactReclaimClaim(
        self: *LinuxServer,
        account: []const u8,
        token: sessions_mod.Token,
        attachment_id: sessions_mod.AttachmentId,
        out_hex: []u8,
    ) ?[]const u8 {
        const identity = self.config.node_identity orelse return null;
        const io = self.config.crypto_io orelse return null;
        const now_u64 = self.meshWallMs();
        const now: i64 = @intCast(@min(now_u64, @as(u64, std.math.maxInt(i64))));
        var nonce_bytes: [8]u8 = undefined;
        io.random(&nonce_bytes);
        const nonce = std.mem.readInt(u64, &nonce_bytes, .big);
        if (nonce == 0) return null;
        const wire = session_reclaim_attachment.encodeClaim(
            self.allocator,
            .{
                .kind = .exact_restore,
                .account = account,
                .group_token = token,
                .attachment_id = attachment_id,
                .origin_node = identity.shortId(),
                .destination_node = identity.shortId(),
                .issued_at_ms = now,
                .expires_at_ms = now + @as(i64, @intCast(mesh_reclaim_ttl_ms)),
                .nonce = nonce,
            },
            &identity.sign_kp,
        ) catch return null;
        defer self.allocator.free(wire);
        if (wire.len * 2 > out_hex.len) return null;
        return toHexLower(wire, out_hex);
    }

    /// Register a live session for the client's account (once; keeps the token
    /// stable). No-op if the client is not logged in. Called after account login.
    fn finalizeRemovedSessionAuthority(self: *LinuxServer, handle: sessions_mod.ResumeHandle) void {
        if (tokenIsNull(handle.token)) return;
        // Tokens are globally unique capabilities, even though SessionStore is
        // account-indexed. A same-token sibling anywhere in the local store keeps
        // this node's authority alive; removing one attachment must never revoke
        // the whole reusable session.
        var account_buf: [session_replica_account_max]u8 = undefined;
        if (self.sessions.findByTokenInto(handle.token, &account_buf) != null) return;

        // Portability is group authority, not reliably a per-row property: one
        // sibling can issue MTOKEN after another already joined the token group.
        // The retained local-origin OFFER is therefore an independent proof that
        // this token needs a closing REVOKE when the final local row disappears.
        const locally_published = self.session_replica_store.getOrigin(handle.token, self.config.node_id) != null;
        if (!handle.portable and !locally_published) return;
        self.publishSessionReplicaRevoke(handle.token);
    }

    /// Remove one SessionStore row and close its mesh authority iff it was the
    /// final local row for the exact portable token. All explicit logout/account-
    /// rebind/ghost-replacement paths use this chokepoint; transport detach does
    /// not, because it retains the row for resume.
    fn removeTrackedSession(self: *LinuxServer, account: []const u8, client: sessions_mod.ClientId) bool {
        const handle = self.sessions.resumeHandleForClient(account, client);
        const removed = self.sessions.remove(account, client);
        if (removed) {
            // Logical authority retirement (logout, account rebind, explicit
            // drop, ghost replacement) makes this physical attachment
            // permanently ineligible to resume. Retire its durable plaintext
            // before releasing the token's mesh authority. Transport detach
            // deliberately never calls this chokepoint and therefore retains
            // its rows for later resume/remap.
            lockSpin(&self.attachment_delivery_mu);
            _ = self.attachment_delivery_spool.discardAttachment(client);
            self.attachment_delivery_mu.unlock();
            if (handle) |captured| self.finalizeRemovedSessionAuthority(captured);
        }
        return removed;
    }

    /// SESSION DROP's compare-and-remove boundary. The SessionStore verifies
    /// token/client/signon/attachment while exclusively locked; nothing after a
    /// LIST snapshot may retarget a recycled runtime client id.
    fn removeTrackedSessionExact(self: *LinuxServer, account: []const u8, expected: sessions_mod.Session) bool {
        const handle = self.sessions.removeExact(account, expected) orelse return false;
        lockSpin(&self.attachment_delivery_mu);
        _ = self.attachment_delivery_spool.discardAttachment(expected.client);
        self.attachment_delivery_mu.unlock();
        self.finalizeRemovedSessionAuthority(handle);
        return true;
    }

    /// Remove every local authority row for an account without allocating. The
    /// fixed-size snapshot is drained repeatedly so configured account caps above
    /// `snapshot_capacity` are still complete; same-token rows naturally publish
    /// exactly one REVOKE when the final row passes through the central wrapper.
    fn removeAllTrackedSessions(self: *LinuxServer, account: []const u8) usize {
        var removed: usize = 0;
        while (true) {
            var rows: [sessions_mod.snapshot_capacity]sessions_mod.Session = undefined;
            const batch = self.sessions.sessionsInto(account, &rows);
            if (batch.len == 0) return removed;
            var progressed = false;
            for (batch) |row| {
                if (self.removeTrackedSession(account, row.client)) {
                    removed += 1;
                    progressed = true;
                }
            }
            if (!progressed) return removed;
        }
    }

    fn finalizeAttachEviction(self: *LinuxServer, outcome: sessions_mod.AttachOutcome) void {
        if (outcome.evicted) |evicted| {
            // Capacity eviction destroys a distinct logical token. Never re-key
            // its attachment-specific plaintext onto the newcomer: that would
            // cross an authority boundary. Explicit retirement frees the rows
            // before the portable mesh authority is revoked, so no orphan can
            // pin spool capacity after SessionStore drops its only lookup key.
            lockSpin(&self.attachment_delivery_mu);
            _ = self.attachment_delivery_spool.discardAttachment(evicted.client);
            self.attachment_delivery_mu.unlock();
            self.finalizeRemovedSessionAuthority(evicted.resumeHandle());
        }
    }

    fn trackSession(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) void {
        _ = self.trackSessionChecked(id, conn);
    }

    fn trackSessionChecked(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) bool {
        const account = conn.session.account() orelse return false;
        const cid = monitorIdFromClient(id);
        if (self.sessions.containsClient(account, cid)) return true;
        const signon: i64 = @intCast(@max(@as(i64, 0), self.nowMs()));
        const io = self.config.crypto_io orelse {
            // Compatibility-only deployments still need LIST/fan-out tracking.
            // The sentinel row has no bearer and no stable attachment id, so it
            // cannot enter either exact resume path.
            const legacy = self.sessions.attachReportingEviction(
                account,
                cid,
                @splat(0),
                signon,
            ) catch |err| {
                srvLog("onyx-server: compatibility session tracking failed for account '{s}': {s}\n", .{ account, @errorName(err) });
                return false;
            };
            self.finalizeAttachEviction(legacy);
            return true;
        };
        const token = self.genSessionToken();
        if (tokenIsNull(token)) {
            srvLog("onyx-server: session tracking failed for account '{s}': invalid generated token\n", .{account});
            return false;
        }
        _ = self.sessions.mintBootstrapAttachmentNoEvict(
            account,
            cid,
            token,
            signon,
            io,
        ) catch |err| {
            // Surface, never swallow: at the per-account cap with every slot
            // occupied there is no safe row to evict, so this session goes
            // UNTRACKED (no reclaim token, no session-sync fan-out, absent from
            // SESSION LIST). An immediately following exact RESUME may still
            // replace its selected detached row without destroying a sibling.
            srvLog("onyx-server: session tracking failed for account '{s}': {s}\n", .{ account, @errorName(err) });
            return false;
        };
        return true;
    }

    /// `onyx/e2ee` promises retained attachment delivery for authenticated
    /// account sockets. A capable account socket may not remain live when its
    /// reusable SessionStore row could not be established (for example, every
    /// per-account slot is still attached). True guests / unauthenticated
    /// sockets never attach a reusable row and keep the ordinary best-effort
    /// delivery contract, so they may negotiate the cap without a session.
    /// Close at registration/login/CAP boundaries before autojoin or further
    /// participation; the delivery collector keeps its own defensive row check
    /// for inherited or manually-constructed legacy state.
    fn enforceE2eeSessionEligibility(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
    ) !bool {
        if (!conn.session.hasCap(.onyx_e2ee)) return true;
        if (self.attachmentHasReusableSession(id)) return true;
        // At the account cap, initial no-evict tracking intentionally leaves a
        // reconnecting socket untracked so its exact RESUME can replace the
        // selected detached row. Honor only the existing bounded autojoin hold;
        // expiry returns here and closes an E2EE socket that never proves it.
        if (conn.resume_autojoin_deferred and conn.resume_autojoin_deadline_ms > self.nowMs())
            return true;
        // No authenticated account ⇒ no reusable SessionStore attachment is
        // expected (guest / anonymous best-effort). Fail closed only for
        // account sockets that negotiated the durable-delivery promise without
        // a live reusable row.
        if (conn.session.account() == null) return true;
        retainCloseReason(conn, "E2EE reusable session unavailable");
        conn.closing = true;
        try self.failReply(
            conn,
            "E2EEGROUP",
            "SESSION_UNAVAILABLE",
            "onyx/e2ee requires an available reusable session",
        );
        return false;
    }

    const ExternalResumeCandidate = union(enum) {
        none,
        /// Retained for callers/tests that still name the old fail-closed path.
        /// Selection no longer emits this: N-node meshes pick one canonical
        /// logical session instead of disconnecting WeeChat/legacy clients.
        ambiguous,
        blocked,
        local: sessions_mod.Token,
        mesh: sessions_mod.Token,
    };

    /// Mesh-wide total order for tokenless EXTERNAL auto-attach. Any number of
    /// secured peers may advertise the same account+nick; the claimant joins
    /// exactly one canonical logical session rather than minting another token
    /// or failing closed on accumulation.
    const CanonicalExternalPick = struct {
        token: sessions_mod.Token,
        source: enum { local, mesh },
        /// 3 = live local attachment, 2 = live mesh attachment lease, 1 = detached/portable only.
        liveness: u8,
        recency_ms: i64,
        revision: ?session_replica_v2.Revision,

        fn beats(self: CanonicalExternalPick, other: CanonicalExternalPick) bool {
            if (self.liveness != other.liveness) return self.liveness > other.liveness;
            if (self.recency_ms != other.recency_ms) return self.recency_ms > other.recency_ms;
            if (self.revision) |self_rev| {
                if (other.revision) |other_rev| {
                    const ord = self_rev.compare(other_rev);
                    if (ord != .eq) return ord == .gt;
                } else return true;
            } else if (other.revision != null) return false;
            return std.mem.order(u8, &self.token, &other.token) == .gt;
        }
    };

    fn considerCanonicalExternalPick(best: *?CanonicalExternalPick, next: CanonicalExternalPick) void {
        if (tokenIsNull(next.token)) return;
        if (best.*) |*current| {
            if (std.crypto.timing_safe.eql(sessions_mod.Token, current.token, next.token)) {
                // Same logical session seen from local + mesh: keep the stronger
                // liveness and prefer a local restore path when either side has one.
                if (next.liveness > current.liveness) current.liveness = next.liveness;
                if (next.source == .local) current.source = .local;
                if (next.recency_ms > current.recency_ms) current.recency_ms = next.recency_ms;
                if (next.revision) |rev| {
                    if (current.revision == null or rev.compare(current.revision.?) == .gt)
                        current.revision = rev;
                }
                return;
            }
            if (next.beats(current.*)) best.* = next;
            return;
        }
        best.* = next;
    }

    fn tokenHasLiveMeshAttachmentLease(
        self: *const LinuxServer,
        token: sessions_mod.Token,
        now_ms: i64,
    ) bool {
        var it = self.session_replica_store.attachment_leases.iterator();
        while (it.next()) |slot| {
            if (!std.crypto.timing_safe.eql(sessions_mod.Token, slot.key_ptr.token, token)) continue;
            const lease = slot.value_ptr.*;
            if (lease.conflicted or now_ms > lease.expires_at_ms) continue;
            return true;
        }
        return false;
    }

    /// Select the canonical reusable session for a certificate-authenticated
    /// legacy client that cannot send SESSION RESUME. Account and nick
    /// comparisons are byte-exact. Multiple rows carrying one token are one
    /// logical session. Distinct tokens for the same account+nick — whether
    /// from two peers or twenty — collapse to one deterministic pick:
    /// live local attachments beat live mesh leases beat detached/portable
    /// replicas; within a tier, newer signon/issued time and higher replica
    /// revision win; token bytes break remaining ties.
    fn externalResumeCandidate(
        self: *LinuxServer,
        claimant: sessions_mod.ClientId,
        account: []const u8,
        nick: []const u8,
    ) ExternalResumeCandidate {
        var best: ?CanonicalExternalPick = null;
        var saw_unstaged_mesh_match = false;
        const rows = self.sessions.copySessionsAlloc(self.allocator, account) catch return .blocked;
        defer self.allocator.free(rows);
        for (rows) |row| {
            if (row.client == claimant or tokenIsNull(row.token)) continue;
            if (row.attached) {
                const sibling = self.connFor(clientIdFromMonitor(row.client)) orelse continue;
                const sibling_account = sibling.session.account() orelse continue;
                if (!std.mem.eql(u8, sibling_account, account) or
                    !std.mem.eql(u8, sibling.session.displayName(), nick)) continue;
                considerCanonicalExternalPick(&best, .{
                    .token = row.token,
                    .source = .local,
                    .liveness = 3,
                    .recency_ms = row.signon_ms,
                    .revision = null,
                });
                continue;
            }
            // Prove the exact physical ghost that the retained bootstrap
            // ticket will later restore. In particular, equal-sign-on
            // siblings use the ticket's client-id tie break rather than a
            // separate array-order selector.
            const signon: i64 = @intCast(@max(@as(i64, 0), self.nowMs()));
            var proof_ticket = self.sessions.prepareBootstrapTokenAttach(
                account,
                claimant,
                row.token,
                .join_existing,
                signon,
            ) orelse return .blocked;
            defer proof_ticket.deinit();
            const source = proof_ticket.detachedSource() orelse continue;
            var snapshot = migration_relay.Snapshot.decode(self.allocator, source.snapshot) catch
                return .blocked;
            const matches = std.mem.eql(u8, snapshot.account, account) and
                std.mem.eql(u8, snapshot.nick, nick);
            snapshot.deinit(self.allocator);
            if (!matches) continue;
            considerCanonicalExternalPick(&best, .{
                .token = row.token,
                .source = .local,
                .liveness = 1,
                .recency_ms = row.signon_ms,
                .revision = null,
            });
        }

        // Current secured-mesh replicas are end-to-end signed before entering
        // this Store and staged into PendingMigrations for transactional restore.
        // Scan the bounded ordered token index so selection is deterministic and
        // independent of hash-map iteration order / mesh size.
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        var after: ?session_replica_v2.Token = null;
        var page_buf: [32]session_replica_v2.Token = undefined;
        while (true) {
            const page = self.session_replica_store.liveTokensAfter(now_wall, after, &page_buf);
            if (page.len == 0) break;
            for (page) |token| {
                const entry = self.session_replica_store.bestLiveIdentity(token, now_wall) orelse continue;
                if (!std.mem.eql(u8, entry.account, account) or !std.mem.eql(u8, entry.nick, nick)) continue;
                const staged = if (self.pending_migrations) |*pending|
                    pending.getLive(token, now_wall)
                else
                    null;
                const staged_entry = staged orelse {
                    saw_unstaged_mesh_match = true;
                    continue;
                };
                const staged_revision = staged_entry.replica_revision orelse {
                    saw_unstaged_mesh_match = true;
                    continue;
                };
                if (!std.mem.eql(u8, staged_entry.account, account) or
                    !staged_revision.eql(entry.revision) or
                    staged_entry.replica_expires_at_ms != entry.expires_at_ms or
                    !std.mem.eql(u8, staged_entry.snapshot, entry.snapshot))
                {
                    saw_unstaged_mesh_match = true;
                    continue;
                }
                const live_lease = self.tokenHasLiveMeshAttachmentLease(token, now_wall);
                considerCanonicalExternalPick(&best, .{
                    .token = token,
                    .source = .mesh,
                    .liveness = if (live_lease) 2 else 1,
                    .recency_ms = entry.issued_at_ms,
                    .revision = entry.revision,
                });
            }
            after = page[page.len - 1];
        }

        const pick = best orelse {
            // Matching mesh authority exists but is not staged locally yet.
            // Do not mint a competing token; ask the client to retry.
            if (saw_unstaged_mesh_match) return .blocked;
            return .none;
        };
        return switch (pick.source) {
            .local => .{ .local = pick.token },
            .mesh => .{ .mesh = pick.token },
        };
    }

    /// Compatibility attach for WeeChat and other clients that possess a bound
    /// certificate but do not implement SESSION RESUME. This never runs for a
    /// password/session-token login. Across any mesh size it attaches to the
    /// single canonical account+nick logical session when one exists.
    const ExternalResumeOutcome = enum { fresh, resumed, blocked };

    fn autoResumeExternalSession(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        candidate: ExternalResumeCandidate,
    ) !ExternalResumeOutcome {
        if (!conn.sasl_external_authenticated) return .fresh;
        const account = conn.session.account() orelse return .fresh;
        const nick = conn.session.displayName();
        if (account.len == 0 or nick.len == 0 or std.mem.eql(u8, nick, "*")) return .fresh;
        const cid = monitorIdFromClient(id);
        switch (candidate) {
            .none => {
                // Concurrent EXTERNAL registrations across the mesh can both
                // observe an empty candidate set. Re-scan before minting so the
                // second claimant joins the first logical session instead of
                // poisoning every later tokenless login with a second token.
                const raced = self.externalResumeCandidate(cid, account, nick);
                switch (raced) {
                    .none, .ambiguous => {},
                    .blocked, .local, .mesh => return try self.autoResumeExternalSession(id, conn, raced),
                }
                // The first EXTERNAL attachment has no earlier logical session
                // to select. Make its fresh token portable and publish the exact
                // signed image proactively; a later tokenless EXTERNAL attach on
                // another secured node can then select it by this same exact
                // account+nick proof. No credential is revealed to the client.
                const snapshot = self.encodeMigrationSnapshot(id, conn) orelse {
                    try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "could not snapshot reusable certificate session; retry login");
                    return .blocked;
                };
                defer self.allocator.free(snapshot);
                if (snapshot.len > session_portability.max_snapshot_len) {
                    try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "certificate session exceeds the portable snapshot limit");
                    return .blocked;
                }
                const token = self.genSessionToken();
                if (tokenIsNull(token)) return .blocked;
                const signon: i64 = @intCast(@max(@as(i64, 0), self.nowMs()));
                var ticket = self.sessions.prepareBootstrapTokenAttach(
                    account,
                    cid,
                    token,
                    .{ .adopt_verified = true },
                    signon,
                ) orelse {
                    try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "could not create reusable certificate session; retry login");
                    return .blocked;
                };
                defer ticket.deinit();
                // Cross the fallible signed-Store boundary while the ticket
                // still preserves any cap victim byte-for-byte. Commit is
                // allocation-free, so successful publication can be followed
                // immediately by the exact local authority insertion.
                if (!self.publishPreparedFreshSessionReplica(
                    token,
                    account,
                    conn.session.displayName(),
                    snapshot,
                )) {
                    try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "could not publish certificate session authority; retry login");
                    return .blocked;
                }
                const outcome = ticket.commit();
                ticket.finish();
                self.finalizeAttachEviction(outcome);
                // Refresh also emits the legacy migration sidecar. Any transient
                // failure now marks this committed portable row dirty for retry;
                // it can no longer destroy the cap victim on a rejected login.
                _ = self.shipSessionMigration(id, conn, account, token);
                return .fresh;
            },
            .ambiguous => {
                // Legacy enum arm: selection is total-ordered now. Re-resolve so
                // a stale caller still joins the canonical session.
                const resolved = self.externalResumeCandidate(cid, account, nick);
                if (resolved == .ambiguous or resolved == .none) {
                    return try self.autoResumeExternalSession(id, conn, .none);
                }
                return try self.autoResumeExternalSession(id, conn, resolved);
            },
            .blocked => {
                try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "signed session authority is not ready locally; retry without replacing it");
                return .blocked;
            },
            .local => |token| {
                if (self.sessions.findAttachedTokenSessionInAccount(account, token, cid)) |source| {
                    const source_id = clientIdFromMonitor(source.client);
                    const source_conn = self.connFor(source_id) orelse return .blocked;
                    const encoded = self.encodeMigrationSnapshot(source_id, source_conn) orelse return .blocked;
                    defer self.allocator.free(encoded);
                    if (!self.restoreBootstrapLiveMigrationSnapshot(
                        id,
                        conn,
                        account,
                        token,
                        encoded,
                        .join_existing,
                    )) return .blocked;
                } else {
                    if (!self.restoreBootstrapDetachedMigrationSnapshot(id, conn, account, token))
                        return .blocked;
                }
                conn.preserve_resume_credential_once = false;
                if (self.refreshPortableSessionReplicas(id, conn, account, token))
                    self.flushDeferredSessionMeshAnnouncements(id, conn);
                try self.noticeTo(conn, "SESSION RESUME: certificate-authenticated session restored");
                return .resumed;
            },
            .mesh => |token| {
                const pm = if (self.pending_migrations) |*pending| pending else return .blocked;
                const entry = pm.getLive(
                    token,
                    @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64)))),
                ) orelse return .blocked;
                if (!std.mem.eql(u8, entry.account, account)) return .blocked;
                if (!self.restoreBootstrapLiveMigrationSnapshot(
                    id,
                    conn,
                    account,
                    token,
                    entry.snapshot,
                    .{ .adopt_verified = true },
                ))
                    return .blocked;
                conn.preserve_resume_credential_once = false;
                _ = self.markPortableResumeIssuedForConn(id, conn, account);
                self.finishDeferredSessionAutojoin(id, conn, true);
                if (self.refreshPortableSessionReplicas(id, conn, account, token))
                    self.flushDeferredSessionMeshAnnouncements(id, conn);
                try self.noticeTo(conn, "SESSION RESUME: certificate-authenticated mesh session restored");
                return .resumed;
            },
        }
    }

    fn bumpSessionListEpoch(self: *LinuxServer) void {
        self.session_list_epoch +%= 1;
        if (self.session_list_epoch == 0) self.session_list_epoch = 1;
    }

    const ListedSessionRevoke = enum {
        removed,
        self_target,
        stale,
        temporarily_unavailable,
    };

    const session_drop_timeout_ms: u64 = 5_000;

    fn dropStoreSelector(row: sessions_mod.Session) sessions_mod.ExactSelector {
        return .{
            .client = row.client,
            .token = row.token,
            .signon_ms = row.signon_ms,
            .attachment_id = row.attachment_id,
        };
    }

    fn dropJournalSelector(row: sessions_mod.Session) session_drop_tx.ExactSelector {
        return .{
            .client = row.client,
            .token = row.token,
            .signon_ms = row.signon_ms,
            .attachment_id = row.attachment_id,
        };
    }

    fn dropJournalToStore(selector: session_drop_tx.ExactSelector) sessions_mod.ExactSelector {
        return .{
            .client = selector.client,
            .token = selector.token,
            .signon_ms = selector.signon_ms,
            .attachment_id = selector.attachment_id,
        };
    }

    fn hintSessionDropOwner(self: *LinuxServer, shard: u12, id: session_drop_tx.TxId) void {
        if (shard == self.rx().shard_id) return;
        const fabric = if (self.fabric) |*f| f else return;
        const control = session_drop_tx.Control.init(id) orelse return;
        // Full controls are counted by ReactorFabric but are not authoritative:
        // every reactor timer scans the journal and recovers the same state.
        if (!fabric.sendControlTo(shard, control)) {
            const total = fabric.controlMissCount();
            if (total == 1 or total % 1024 == 0) {
                var buf: [144]u8 = undefined;
                const line = std.fmt.bufPrint(
                    &buf,
                    "SESSION DROP control hint missed; journal sweep remains authoritative (total {d})",
                    .{total},
                ) catch "SESSION DROP control hint missed; journal sweep remains authoritative";
                self.traceLog(.warn, .reactor, line);
            }
        }
        self.wakeShard(shard);
    }

    fn finishSessionDropAbort(self: *LinuxServer, id: session_drop_tx.TxId, result: session_drop_tx.TerminalResult) void {
        const before = self.session_drop_journal.get(id) orelse return;
        switch (before.state) {
            .committing => self.session_drop_journal.failCommitBeforeLinearization(id, result) catch {},
            .target_pending, .successor_pending, .commit_pending => self.session_drop_journal.requestAbort(id, result) catch {},
            else => {},
        }
        const entry = self.session_drop_journal.get(id) orelse return;
        const reservation = session_drop_tx.reservationId(id);
        if (entry.target_reserved) {
            _ = self.sessions.cancelDropReservation(entry.accountName(), dropJournalToStore(entry.target), reservation);
            _ = self.session_drop_journal.markReservationReleased(id, .target) catch {};
        }
        const after_target = self.session_drop_journal.get(id) orelse return;
        if (after_target.successor_reserved) if (after_target.successor) |successor| {
            _ = self.sessions.cancelDropReservation(after_target.accountName(), dropJournalToStore(successor), reservation);
            _ = self.session_drop_journal.markReservationReleased(id, .successor) catch {};
        };
        const terminal = self.session_drop_journal.get(id) orelse return;
        if (terminal.terminalResult() != null)
            self.session_drop_journal.markResultConsumed(id) catch {};
        _ = self.session_drop_journal.reapIfDone(id);
    }

    /// Timer/control recovery. Admission drives the transaction synchronously
    /// while World is locked, but every pre-linearization phase is journaled so
    /// a missed owner hint or vanished requester can still release reservations.
    fn sweepSessionDropTransactions(self: *LinuxServer) void {
        var ids_buf: [session_drop_tx.capacity]session_drop_tx.TxId = undefined;
        const ids = self.session_drop_journal.activeIdsInto(&ids_buf);
        const now = self.nowU64();
        for (ids) |id| {
            const entry = self.session_drop_journal.get(id) orelse continue;
            if (entry.state.isPrecommit() and now >= entry.deadline_ms) {
                _ = self.session_drop_journal.expire(id, now) catch {};
            } else if (entry.state.isPrecommit() and self.connFor(entry.requester) == null) {
                self.session_drop_journal.requestAbort(id, .requester_gone) catch {};
            }
            const current = self.session_drop_journal.get(id) orelse continue;
            if (current.state == .abort_pending or current.state == .aborted)
                self.finishSessionDropAbort(id, current.result orelse .cancelled);
        }
    }

    /// A normal close/logout/rebind must never free ConnState while a token-group
    /// reservation prevented its Store row from detaching. Cancel every
    /// pre-linearization DROP that freezes this logical token, release its exact
    /// reservations, then let the caller retry the owner mutation in the same
    /// World-locked turn. A committing transaction cannot interleave here.
    fn cancelSessionDropsForToken(self: *LinuxServer, account: []const u8, token: sessions_mod.Token) void {
        var ids_buf: [session_drop_tx.capacity]session_drop_tx.TxId = undefined;
        const ids = self.session_drop_journal.activeIdsInto(&ids_buf);
        for (ids) |tx| {
            const entry = self.session_drop_journal.get(tx) orelse continue;
            if (!std.ascii.eqlIgnoreCase(entry.accountName(), account)) continue;
            const target_matches = std.crypto.timing_safe.eql(sessions_mod.Token, entry.target.token, token);
            const successor_matches = if (entry.successor) |successor|
                std.crypto.timing_safe.eql(sessions_mod.Token, successor.token, token)
            else
                false;
            if (!target_matches and !successor_matches) continue;
            if (!entry.state.isPrecommit()) continue;
            self.finishSessionDropAbort(tx, .cancelled);
        }
    }

    fn revokeListedSessionRow(
        self: *LinuxServer,
        account: []const u8,
        caller_id: client_model.ClientId,
        target: sessions_mod.Session,
        reply: session_drop_tx.ReplyKey,
    ) ListedSessionRevoke {
        const caller_cid = monitorIdFromClient(caller_id);
        if (target.client == caller_cid) return .self_target;
        if (target.attached)
            return self.revokeAttachedSessionReserved(account, caller_id, target, reply);
        return if (self.removeTrackedSessionExact(account, target)) .removed else .stale;
    }

    /// Reserved cross-reactor DROP. World serialization protects the journal,
    /// connection generations, and prepared identity handoff; SessionStore's
    /// exact token-group reservation freezes every row whose liveness could
    /// change the successor decision. The Store CAS is the linearization point.
    fn revokeAttachedSessionReserved(
        self: *LinuxServer,
        account: []const u8,
        requester: client_model.ClientId,
        expected: sessions_mod.Session,
        reply: session_drop_tx.ReplyKey,
    ) ListedSessionRevoke {
        if (account.len > session_drop_tx.account_capacity) return .stale;
        const target_id = clientIdFromMonitor(expected.client);
        const target_conn = self.connFor(target_id) orelse
            return if (target_id.shard == self.rx().shard_id) .stale else .temporarily_unavailable;
        const target_account = target_conn.session.account() orelse return .stale;
        if (!std.ascii.eqlIgnoreCase(target_account, account) or target_conn.closing)
            return .stale;
        const target_nick = target_conn.session.displayName();
        const tx = self.session_drop_journal.begin(.{
            .requester = requester,
            .account = account,
            .target = dropJournalSelector(expected),
            .target_nick = target_nick,
            .reply = reply,
            .deadline_ms = self.nowU64() +| session_drop_timeout_ms,
        }) catch return .temporarily_unavailable;
        var completed = false;
        defer if (!completed) self.finishSessionDropAbort(tx, .temporarily_unavailable);

        self.hintSessionDropOwner(target_id.shard, tx);
        const reservation = session_drop_tx.reservationId(tx);
        switch (self.sessions.reserveDrop(account, dropStoreSelector(expected), reservation)) {
            .reserved, .already_reserved => {},
            .stale => return .stale,
            .reserved_by_other, .invalid_id => return .temporarily_unavailable,
        }
        self.session_drop_journal.markTargetReserved(tx) catch return .temporarily_unavailable;

        const rows = self.sessions.copySessionsAlloc(self.allocator, account) catch
            return .temporarily_unavailable;
        defer self.allocator.free(rows);
        var successor_row: ?sessions_mod.Session = null;
        var first_eligible: ?sessions_mod.Session = null;
        var unattested = false;
        const from_wid = worldIdFromClient(target_id);
        const nick_owner = self.world.findNick(target_nick);
        for (rows) |row| {
            if (!row.attached or row.client == expected.client) continue;
            if (!std.crypto.timing_safe.eql(sessions_mod.Token, row.token, expected.token)) continue;
            const candidate_id = clientIdFromMonitor(row.client);
            const candidate = self.connFor(candidate_id) orelse {
                unattested = true;
                continue;
            };
            const candidate_account = candidate.session.account() orelse {
                unattested = true;
                continue;
            };
            if (candidate.closing or candidate.s2s != null or candidate.s2s_secured != null or
                !std.ascii.eqlIgnoreCase(candidate_account, account) or
                !std.ascii.eqlIgnoreCase(candidate.session.displayName(), target_nick))
            {
                unattested = true;
                continue;
            }
            if (first_eligible == null) first_eligible = row;
            if (nick_owner) |owner| if (owner.eql(worldIdFromClient(candidate_id))) {
                successor_row = row;
                break;
            };
        }
        if (successor_row == null) if (nick_owner) |owner| {
            if (owner.eql(from_wid)) successor_row = first_eligible;
        };
        if (successor_row == null and (unattested or first_eligible != null))
            return .temporarily_unavailable;

        if (successor_row) |successor| {
            self.session_drop_journal.setSuccessorPending(tx, dropJournalSelector(successor)) catch
                return .temporarily_unavailable;
            const successor_id = clientIdFromMonitor(successor.client);
            self.hintSessionDropOwner(successor_id.shard, tx);
            switch (self.sessions.reserveDrop(account, dropStoreSelector(successor), reservation)) {
                .reserved, .already_reserved => {},
                .stale => return .stale,
                .reserved_by_other, .invalid_id => return .temporarily_unavailable,
            }
            self.session_drop_journal.markSuccessorReserved(tx) catch return .temporarily_unavailable;
        } else {
            self.session_drop_journal.markCommitPending(tx) catch return .temporarily_unavailable;
        }

        var restores: std.ArrayListUnmanaged(world_model.MemberRestore) = .empty;
        defer restores.deinit(self.allocator);
        var handoff: ?world_model.World.PreparedSessionRestore = null;
        if (successor_row) |successor| {
            const successor_id = clientIdFromMonitor(successor.client);
            const to_wid = worldIdFromClient(successor_id);
            var channels = self.world.channels.iterator();
            while (channels.next()) |entry| {
                const old_modes = self.world.memberModes(entry.key_ptr.*, from_wid);
                const next_modes = self.world.memberModes(entry.key_ptr.*, to_wid);
                if (old_modes == null and next_modes == null) continue;
                restores.append(self.allocator, .{
                    .channel = entry.key_ptr.*,
                    .modes = .{ .bits = (if (old_modes) |m| m.bits else 0) | (if (next_modes) |m| m.bits else 0) },
                }) catch return .temporarily_unavailable;
            }
            const exact = [_]world_model.ClientId{ from_wid, to_wid };
            handoff = self.world.prepareSessionRestore(
                target_nick,
                to_wid,
                &exact,
                .{ .claim_exact = to_wid },
                restores.items,
            ) catch return .temporarily_unavailable;
        }
        defer if (handoff) |*prepared| prepared.abort();

        self.session_drop_journal.beginCommit(tx) catch return .temporarily_unavailable;
        const handle = self.sessions.commitDropReservation(account, dropStoreSelector(expected), reservation) orelse {
            self.session_drop_journal.failCommitBeforeLinearization(tx, .stale_list) catch {};
            return .stale;
        };
        _ = self.session_drop_journal.markReservationReleased(tx, .target) catch {};
        if (handoff) |*prepared| {
            prepared.commit();
            handoff = null;
            target_conn.session_handoff_complete = true;
        }
        target_conn.session_handoff_checked = true;

        if (successor_row) |successor| {
            _ = self.sessions.cancelDropReservation(account, dropStoreSelector(successor), reservation);
            _ = self.session_drop_journal.markReservationReleased(tx, .successor) catch {};
        }
        lockSpin(&self.attachment_delivery_mu);
        _ = self.attachment_delivery_spool.discardAttachment(expected.client);
        self.attachment_delivery_mu.unlock();
        self.finalizeRemovedSessionAuthority(handle);
        const notice = ":onyx.local NOTICE * :SESSION: this session was revoked from another device\r\n";
        self.enqueueDeliveryThenClose(target_id, notice, "session revoked") catch {};
        // Nothing after the Store CAS may report failure: these journal
        // transitions are allocation-free invariants of the already-committed
        // path, and the client-visible result must follow the linearization.
        self.session_drop_journal.markCommitted(tx) catch unreachable;
        self.session_drop_journal.markResultConsumed(tx) catch unreachable;
        _ = self.session_drop_journal.reapIfDone(tx);
        completed = true;
        return .removed;
    }

    fn handleSessionDrop(
        self: *LinuxServer,
        conn: *ConnState,
        account: []const u8,
        caller_cid: sessions_mod.ClientId,
        raw: []const u8,
    ) !void {
        const target = session_sid.parseDropTarget(raw) catch {
            try self.failReply(conn, "SESSION", "INVALID_INDEX", "DROP requires a session sid or a positive index from SESSION LIST");
            return;
        };
        const account_sessions = self.sessions.copySessionsAlloc(self.allocator, account) catch {
            try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "could not snapshot the session list");
            return;
        };
        defer self.allocator.free(account_sessions);

        var buf: [default_reply_bytes]u8 = undefined;
        switch (target) {
            .ordinal => |idx| {
                const cached = conn.session_list_cache.lookup(self.session_list_epoch, account, idx) catch {
                    try self.failReply(conn, "SESSION", "STALE_LIST", "SESSION LIST snapshot is no longer valid; list again");
                    return;
                };
                const current = session_sid.resolveCachedRow(account_sessions, cached) catch {
                    try self.failReply(conn, "SESSION", "STALE_LIST", "SESSION LIST snapshot is no longer valid; list again");
                    return;
                };
                switch (self.revokeListedSessionRow(account, clientIdFromMonitor(caller_cid), current, .{ .ordinal = idx })) {
                    .removed => {},
                    .self_target => {
                        try self.failReply(conn, "SESSION", "CANNOT_DROP_CURRENT", "Cannot drop this connection; use LOGOUT or disconnect");
                        return;
                    },
                    .stale => {
                        try self.failReply(conn, "SESSION", "STALE_LIST", "Session changed; list again");
                        return;
                    },
                    .temporarily_unavailable => {
                        try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "Cross-reactor session revoke is temporarily unavailable");
                        return;
                    },
                }
                // Keep ordinal numbering stable but erase the successfully
                // revoked row's token/AID immediately.
                conn.session_list_cache.invalidate(idx);
                const ok_line = std.fmt.bufPrint(&buf, "SESSION DROP #{d} ok", .{idx}) catch "SESSION DROP ok";
                try self.noticeTo(conn, ok_line);
            },
            .sid => |sid| {
                const matched = session_sid.matchSid(account_sessions, sid);
                const row = switch (matched) {
                    .none => {
                        try self.failReply(conn, "SESSION", "NO_SUCH_SESSION", "No session matches that sid");
                        return;
                    },
                    .ambiguous => {
                        try self.failReply(conn, "SESSION", "AMBIGUOUS_SID", "Session sid is ambiguous; refuse to revoke");
                        return;
                    },
                    .unique => |value| value,
                };
                const current = session_sid.resolveCachedRow(account_sessions, row) catch {
                    try self.failReply(conn, "SESSION", "STALE_LIST", "Session changed; list again");
                    return;
                };
                switch (self.revokeListedSessionRow(account, clientIdFromMonitor(caller_cid), current, .{ .sid = sid })) {
                    .removed => {},
                    .self_target => {
                        try self.failReply(conn, "SESSION", "CANNOT_DROP_CURRENT", "Cannot drop this connection; use LOGOUT or disconnect");
                        return;
                    },
                    .stale => {
                        try self.failReply(conn, "SESSION", "STALE_LIST", "Session changed; list again");
                        return;
                    },
                    .temporarily_unavailable => {
                        try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "Cross-reactor session revoke is temporarily unavailable");
                        return;
                    },
                }
                conn.session_list_cache.invalidateExact(row);
                const sid_hex = session_sid.formatSid(sid);
                const ok_line = std.fmt.bufPrint(&buf, "SESSION DROP sid={s} ok", .{sid_hex}) catch "SESSION DROP ok";
                try self.noticeTo(conn, ok_line);
            },
        }
    }

    /// `SESSION [LIST|TOKEN|DROP]` — list the account's live sessions, reveal this
    /// session's reclaim token (to the owning session only), or revoke another
    /// session by sid or by the caller's last LIST ordinal (`SESSION DROP #<n>`).
    pub fn handleSession(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const account = conn.session.account() orelse {
            try self.noticeTo(conn, "SESSION: you are not logged in to an account");
            return;
        };
        const cid = monitorIdFromClient(id);
        const sub = if (parsed.param_count >= 1) parsed.paramSlice()[0] else "LIST";
        var buf: [default_reply_bytes]u8 = undefined;
        if (std.ascii.eqlIgnoreCase(sub, "RESUME")) {
            try self.handleSessionResume(id, conn, account, parsed);
            return;
        }
        if (std.ascii.eqlIgnoreCase(sub, "DROP")) {
            // SESSION DROP <sid|#n> — sid revokes exactly one physical row;
            // #n binds to the last LIST this connection emitted. Never drops the
            // caller's own current attachment (use LOGOUT for that).
            if (parsed.param_count < 2) {
                try self.failReply(conn, "SESSION", "NEED_MORE_PARAMS", "Usage: SESSION DROP <sid|#n>");
                return;
            }
            try self.handleSessionDrop(conn, account, cid, parsed.paramSlice()[1]);
            return;
        }
        if (std.ascii.eqlIgnoreCase(sub, "TOKEN")) {
            if (conn.preserve_resume_credential_once) {
                conn.preserve_resume_credential_once = false;
                if (!conn.resume_autojoin_deferred) conn.resume_autojoin_deadline_ms = 0;
                try self.warnReply(conn, "SESSION", "RESUME_CREDENTIAL_PRESERVED", "retryable resume did not consume the stored credential; repeat SESSION TOKEN to replace it");
                return;
            }
            // Onyx sends RESUME then TOKEN in-order after 001. Reaching TOKEN with
            // the deferral still set means no resume succeeded; release autojoin
            // now instead of waiting for the timer. A retryable RESUME failure is
            // handled above and deliberately preserves both the credential and
            // deferral, preventing a temporary nick from joining account rooms.
            self.finishDeferredSessionAutojoin(id, conn, false);
            if (self.sessions.resumeHandleForClient(account, cid)) |handle| {
                if (!tokenIsNull(handle.token)) {
                    const token_hex = std.fmt.bytesToHex(handle.token, .lower);
                    const attachment_id = handle.attachment_id;
                    const exact_issuance = self.config.session_resume_composite_issuance and
                        attachment_id != null;
                    const line = if (exact_issuance) blk: {
                        const aid = attachment_id.?;
                        const credential = session_resume_credential.encodeLocal(handle.token, aid) catch return;
                        break :blk std.fmt.bufPrint(
                            &buf,
                            "SESSION TOKEN {s}",
                            .{credential},
                        ) catch return;
                    } else std.fmt.bufPrint(&buf, "SESSION TOKEN {s}", .{token_hex}) catch return;
                    try self.noticeTo(conn, line);
                    // Also offer a mesh-sealed token usable to reclaim/redirect from
                    // ANY node in the mesh (only when a mesh shared key is set).
                    var mbuf: [1024]u8 = undefined;
                    const mesh_authority = if (exact_issuance)
                        self.meshExactReclaimClaim(account, handle.token, attachment_id.?, &mbuf)
                    else
                        self.meshReclaimToken(account, &token_hex, &mbuf);
                    if (mesh_authority) |mhex| {
                        // Set the replication gate before emitting the credential: if
                        // the connection drops after the write is queued, detach must
                        // still ship the snapshot that this token can unlock.
                        if (!self.markPortableResumeIssuedForConn(id, conn, account)) return;
                        // Replicate LIVE state too. A second client may present this
                        // MTOKEN on another node while the issuer remains connected;
                        // waiting until detach would force a redirect/ownership race
                        // and violate mesh-wide multi-attachment semantics.
                        _ = self.shipSessionMigration(id, conn, account, handle.token);
                        var lb: [1152]u8 = undefined;
                        const expires_unix = (self.meshWallMs() + mesh_reclaim_ttl_ms) / 1000;
                        const mline = if (exact_issuance) blk: {
                            var credential_buf: [1200]u8 = undefined;
                            const credential = session_resume_credential.encodeMesh(
                                &credential_buf,
                                mhex,
                                attachment_id.?,
                            ) catch return;
                            break :blk std.fmt.bufPrint(
                                &lb,
                                "SESSION MTOKEN {s} expires={d}",
                                .{ credential, expires_unix },
                            ) catch return;
                        } else std.fmt.bufPrint(
                            &lb,
                            "SESSION MTOKEN {s} expires={d}",
                            .{ mhex, expires_unix },
                        ) catch return;
                        try self.noticeTo(conn, mline);
                    }
                    return;
                }
            }
            try self.noticeTo(conn, "SESSION: no token for this session");
            return;
        }
        // LIST (default): never reveal tokens here. Bind #n to this emission.
        // LIST failure must invalidate the previous selector image before any
        // allocation can fail; a caller cannot reuse stale ordinals after OOM.
        conn.session_list_cache.reset();
        const account_sessions = self.sessions.copySessionsAlloc(self.allocator, account) catch {
            try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "could not snapshot the session list");
            return;
        };
        defer self.allocator.free(account_sessions);
        // Never let an old or precomputed image select a row that was not
        // actually emitted. Any formatting/write/allocation failure leaves the
        // cache empty and requires the client to LIST again.
        var staged_cache = session_sid.ListCache{};
        defer staged_cache.reset();
        staged_cache.prepare(self.allocator, self.session_list_epoch, account, account_sessions.len) catch {
            try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "could not securely stage the complete session list");
            return;
        };
        var emitted: usize = 0;
        for (account_sessions) |s| {
            const current: []const u8 = if (s.client == cid) "*" else "-";
            const state: []const u8 = if (s.attached) "attached" else "detached";
            const sid = session_sid.sidOf(s);
            const next_idx = emitted + 1;
            const line = if (sid) |id_bytes| blk: {
                const sid_hex = session_sid.formatSid(id_bytes);
                break :blk std.fmt.bufPrint(
                    &buf,
                    "SESSION LIST {s} #{d} signon={d} {s} sid={s}",
                    .{ current, next_idx, s.signon_ms, state, sid_hex },
                ) catch continue;
            } else std.fmt.bufPrint(
                &buf,
                "SESSION LIST {s} #{d} signon={d} {s}",
                .{ current, next_idx, s.signon_ms, state },
            ) catch continue;
            try self.noticeTo(conn, line);
            staged_cache.rows.appendAssumeCapacity(.{ .token = s.token, .client = s.client, .signon_ms = s.signon_ms, .attachment_id = s.attachment_id });
            emitted += 1;
        }
        try self.noticeTo(conn, "SESSION: end of session list");
        conn.session_list_cache.reset();
        conn.session_list_cache = staged_cache;
        staged_cache = .{};
    }

    /// `SESSION RESUME <token>` — attach this client to the caller's logical
    /// account session. Tokens are stable, reusable group credentials: if another
    /// attachment is live we clone its current state and KEEP it connected; if
    /// only a detached attachment exists we replace that ghost. Every successful
    /// attachment carries the same token so later reconnects can land on any live
    /// sibling instead of racing for one-shot ownership.
    fn markSessionResumeRetryable(self: *LinuxServer, conn: *ConnState) void {
        conn.preserve_resume_credential_once = true;
        // A WARN means the exact credential is still authoritative and the
        // client is expected to retry it. Preservation itself owns this bounded
        // deadline even for a later manual RESUME with no autojoin hold; when a
        // hold exists the same deadline also prevents seating a temporary
        // account-room identity before the next attempt.
        conn.resume_autojoin_deadline_ms = self.nowMs() + 2_000;
    }

    fn handleExactLocalResume(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        token: sessions_mod.Token,
        attachment_id: sessions_mod.AttachmentId,
        cross_server: bool,
    ) !void {
        const outcome = self.restoreExactAttachment(id, conn, account, token, attachment_id);
        switch (outcome) {
            .missing => {
                try self.failReply(conn, "SESSION", "NO_ATTACHMENT", "No exact session attachment matches that credential");
                return;
            },
            .busy => {
                try self.failReply(conn, "SESSION", "ATTACHMENT_IN_USE", "Exact session attachment is already active");
                return;
            },
            .retryable => {
                self.markSessionResumeRetryable(conn);
                try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "exact session restore failed; credential remains valid");
                return;
            },
            .already_attached => {
                self.finishDeferredSessionAutojoin(id, conn, true);
                try self.noticeTo(conn, "SESSION RESUME: already attached to this exact session");
                return;
            },
            .restored, .reclaimed => {},
        }

        conn.preserve_resume_credential_once = false;
        self.finishDeferredSessionAutojoin(id, conn, outcome == .restored);
        if (self.refreshPortableSessionReplicas(id, conn, account, token))
            self.flushDeferredSessionMeshAnnouncements(id, conn);
        const action: []const u8 = if (outcome == .restored) "restored" else "reclaimed";
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(
            &line_buf,
            "SESSION RESUME: exact session {s}{s}",
            .{ action, if (cross_server) " (cross-server)" else "" },
        ) catch return;
        try self.noticeTo(conn, line);
        var event_buf: [default_reply_bytes]u8 = undefined;
        const event = std.fmt.bufPrint(
            &event_buf,
            "SESSION exact-{s}{s} account={s}",
            .{ action, if (cross_server) " cross-server" else "", account },
        ) catch return;
        self.publishOperEvent(.service, .notice, event) catch {};
    }

    pub fn handleSessionResume(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, account: []const u8, parsed: *const irc_line.LineView) !void {
        // Preservation belongs to exactly one retryable attempt. Clear any prior
        // WARN latch before parsing this attempt; only a retryable outcome below
        // may arm it again. Terminal and already-attached results therefore can
        // never leave SESSION TOKEN stuck behind a stale preservation warning.
        conn.preserve_resume_credential_once = false;
        if (!conn.resume_autojoin_deferred) conn.resume_autojoin_deadline_ms = 0;
        const cid = monitorIdFromClient(id);
        const params = parsed.paramSlice();
        if (params.len < 2 or params[1].len == 0) {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "RESUME requires a valid session token");
            return;
        }
        const raw_credential = params[1];
        if (std.mem.startsWith(u8, raw_credential, session_resume_credential.local_prefix ++ ".") or
            std.mem.startsWith(u8, raw_credential, session_resume_credential.mesh_prefix ++ "."))
        {
            const credential = session_resume_credential.decode(raw_credential) catch {
                try self.failReply(conn, "SESSION", "INVALID_TOKEN", "RESUME credential is malformed or noncanonical");
                return;
            };
            switch (credential) {
                .local => |exact| {
                    try self.handleExactLocalResume(
                        id,
                        conn,
                        account,
                        exact.group_token,
                        exact.attachment_id,
                        false,
                    );
                },
                .mesh => |exact| try self.handleMeshExactReclaim(
                    id,
                    conn,
                    account,
                    exact.sealed_hex,
                    exact.attachment_id,
                ),
            }
            return;
        }
        const token = sessionTokenFromHex(raw_credential) orelse {
            if (raw_credential.len == 2 * @sizeOf(sessions_mod.Token)) {
                try self.failReply(conn, "SESSION", "INVALID_TOKEN", "RESUME requires a valid session token");
                return;
            }
            // Unprefixed non-local credentials are the rolling SRM1 path.
            try self.handleMeshReclaim(id, conn, account, raw_credential);
            return;
        };
        if (self.sessions.clientHasToken(account, cid, token)) {
            self.finishDeferredSessionAutojoin(id, conn, true);
            try self.noticeTo(conn, "SESSION RESUME: already attached to this session");
            return;
        }

        // A live sibling is not an error and is never disconnected. Snapshot its
        // current identity/channels, attach this client to the same token group,
        // and leave the source untouched.
        if (self.sessions.findAttachedTokenSessionInAccount(account, token, cid)) |source| {
            const source_id = clientIdFromMonitor(source.client);
            const source_conn = self.connFor(source_id) orelse {
                self.markSessionResumeRetryable(conn);
                try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "live session attachment is converging; retry the same token");
                return;
            };
            const snapshot = self.encodeMigrationSnapshot(source_id, source_conn) orelse {
                self.markSessionResumeRetryable(conn);
                try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "could not snapshot the live session; retry the same token");
                return;
            };
            defer self.allocator.free(snapshot);
            if (!self.restoreEncodedMigrationSnapshot(id, conn, account, token, snapshot, .join_existing)) {
                self.markSessionResumeRetryable(conn);
                try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "live session attach failed; token remains valid");
                return;
            }
            conn.preserve_resume_credential_once = false;
            self.finishDeferredSessionAutojoin(id, conn, true);
            if (self.refreshPortableSessionReplicas(id, conn, account, token))
                self.flushDeferredSessionMeshAnnouncements(id, conn);
            try self.noticeTo(conn, "SESSION RESUME: attached to live session");
            return;
        }

        _ = self.sessions.findDetachedTokenSessionInAccount(account, token) orelse {
            try self.failReply(conn, "SESSION", "NO_SESSION", "No session matches that token");
            return;
        };
        const snapshot = self.sessions.copyDetachedSnapshotInAccount(self.allocator, account, token) catch null;
        defer if (snapshot) |bytes| self.allocator.free(bytes);
        // Bare legacy tokens carry no stable physical selector. They may clone
        // group state into this freshly minted attachment, but must never consume
        // a detached sibling or transfer its attachment-specific spool.
        const restored = if (snapshot) |bytes| self.restoreEncodedMigrationSnapshot(
            id,
            conn,
            account,
            token,
            bytes,
            .join_existing,
        ) else false;
        if (snapshot != null and !restored) {
            self.markSessionResumeRetryable(conn);
            try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "session restore failed; token remains valid");
            return;
        }
        if (snapshot == null and !self.sessions.joinTokenGroup(account, cid, token)) {
            self.markSessionResumeRetryable(conn);
            try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "session registry changed during resume; retry the same token");
            return;
        }
        if (snapshot == null) self.bindDeferredSessionMeshAnnouncements(id, conn, token);
        conn.preserve_resume_credential_once = false;
        self.finishDeferredSessionAutojoin(id, conn, true);
        if (self.refreshPortableSessionReplicas(id, conn, account, token))
            self.flushDeferredSessionMeshAnnouncements(id, conn);
        if (restored) {
            try self.noticeTo(conn, "SESSION RESUME: legacy session state cloned into a new attachment");
        } else {
            try self.noticeTo(conn, "SESSION RESUME: legacy session attached as a new attachment");
        }
        var event_buf: [default_reply_bytes]u8 = undefined;
        const event = std.fmt.bufPrint(&event_buf, "SESSION legacy-create-new account={s}", .{account}) catch return;
        self.publishOperEvent(.service, .notice, event) catch {};
    }

    const TrustedReclaimRoute = union(enum) {
        local,
        remote: struct {
            name: []u8,

            fn slice(self: *const @This()) []const u8 {
                return self.name;
            }
        },
    };

    fn trustedReclaimRoute(
        self: *LinuxServer,
        origin_node: u64,
        signer: session_reclaim_attachment.SignedClaim,
    ) ?TrustedReclaimRoute {
        const identity = self.config.node_identity orelse return null;
        if (origin_node == identity.shortId()) {
            if (!std.mem.eql(u8, &signer.signer, &identity.sign_kp.public_key)) return null;
            return .local;
        }
        lockSpin(&self.mesh_peer_identity_mu);
        defer self.mesh_peer_identity_mu.unlock();
        const count = @min(
            @as(usize, @intCast(self.net_peer_count.load(.acquire))),
            self.mesh_published_peers.items.len,
        );
        for (self.mesh_published_peers.items[0..count]) |peer| {
            if (peer.node_id != origin_node or
                !peer.public_key_present or
                !std.mem.eql(u8, &peer.public_key, &signer.signer)) continue;
            if (peer.name.len == 0) return null;
            const name = self.allocator.dupe(u8, peer.name) catch return null;
            return .{ .remote = .{ .name = name } };
        }
        return null;
    }

    fn handleMeshExactReclaim(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        claim_hex: []const u8,
        attachment_id: sessions_mod.AttachmentId,
    ) !void {
        if (claim_hex.len % 2 != 0 or
            claim_hex.len / 2 < session_reclaim_attachment.min_claim_wire_len or
            claim_hex.len / 2 > session_reclaim_attachment.max_claim_wire_len)
        {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "malformed exact mesh credential");
            return;
        }
        var raw: [session_reclaim_attachment.max_claim_wire_len]u8 = undefined;
        const wire = std.fmt.hexToBytes(raw[0 .. claim_hex.len / 2], claim_hex) catch {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "exact mesh credential is not valid hex");
            return;
        };
        const signed = session_reclaim_attachment.decodeClaim(wire) catch {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "malformed exact mesh claim");
            return;
        };
        session_reclaim_attachment.verifyClaim(signed) catch {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "exact mesh claim failed verification");
            return;
        };
        const claim = signed.claim;
        const now: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        session_reclaim_attachment.validateAt(claim, now, .{}) catch {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "exact mesh claim expired or is not yet valid");
            return;
        };
        if (claim.kind != .exact_restore or
            claim.origin_node != claim.destination_node or
            !std.ascii.eqlIgnoreCase(claim.account, account) or
            !claim.attachment_id.eql(attachment_id))
        {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "exact mesh claim does not match this session");
            return;
        }
        const route = self.trustedReclaimRoute(claim.origin_node, signed) orelse {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "exact mesh claim signer is not a trusted route");
            return;
        };
        switch (route) {
            .local => try self.handleExactLocalResume(
                id,
                conn,
                account,
                claim.group_token,
                attachment_id,
                true,
            ),
            .remote => |remote_route| {
                defer self.allocator.free(remote_route.name);
                self.markSessionResumeRetryable(conn);
                var buf: [default_reply_bytes]u8 = undefined;
                const line = std.fmt.bufPrint(
                    &buf,
                    "SESSION REDIRECT: exact session lives on {s}; reconnect there to reclaim",
                    .{remote_route.slice()},
                ) catch return;
                try self.noticeTo(conn, line);
            },
        }
    }

    /// Cross-server reclaim: `SESSION RESUME <mesh-token>` where the token is a
    /// mesh-sealed `session_reclaim_mesh` blob (hex). Verify it under the mesh
    /// shared key, confirm it is for the caller's OWN authenticated account, then
    /// either attach to a local/replicated session or tell the client where a
    /// replica can be obtained. Portable credentials are reusable for their
    /// bounded lifetime: replay rejection would make two legitimate clients race
    /// for ownership, contradicting the multi-attachment session contract.
    fn handleMeshReclaim(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, account: []const u8, tok_hex: []const u8) !void {
        const key = self.config.mesh_pass;
        if (key.len == 0) {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "cross-server reclaim is not enabled");
            return;
        }
        if (tok_hex.len % 2 != 0 or tok_hex.len / 2 > 512) {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "malformed reclaim token");
            return;
        }
        var raw: [512]u8 = undefined;
        const rb = std.fmt.hexToBytes(raw[0 .. tok_hex.len / 2], tok_hex) catch {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "reclaim token is not valid hex");
            return;
        };
        const now = self.meshWallMs();
        const fields = session_reclaim_mesh.open(key, rb, now) catch |e| {
            const msg = switch (e) {
                error.Expired => "reclaim token expired",
                error.BadMac => "reclaim token failed verification",
                else => "malformed reclaim token",
            };
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", msg);
            return;
        };
        // A client may only reclaim sessions of its OWN authenticated account.
        if (!std.ascii.eqlIgnoreCase(fields.account, account)) {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "reclaim token is for a different account");
            return;
        }
        const cid = monitorIdFromClient(id);
        const migrate_token = sessionTokenFromHex(fields.session_id) orelse {
            try self.failReply(conn, "SESSION", "INVALID_TOKEN", "reclaim token carries an invalid session id");
            return;
        };
        if (self.sessions.clientHasToken(account, cid, migrate_token)) {
            self.finishDeferredSessionAutojoin(id, conn, true);
            try self.noticeTo(conn, "SESSION RESUME: already attached to this mesh session");
            return;
        }

        // Join an already-live local attachment without disturbing it. This is
        // the common same-node multi-client path for an MTOKEN shared by browser
        // tabs/devices.
        if (self.sessions.findAttachedTokenSessionInAccount(account, migrate_token, cid)) |source| {
            const source_id = clientIdFromMonitor(source.client);
            const source_conn = self.connFor(source_id) orelse {
                self.markSessionResumeRetryable(conn);
                try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "live mesh attachment is converging; retry the same token");
                return;
            };
            const snapshot = self.encodeMigrationSnapshot(source_id, source_conn) orelse {
                self.markSessionResumeRetryable(conn);
                try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "could not snapshot the live mesh session; retry the same token");
                return;
            };
            defer self.allocator.free(snapshot);
            if (!self.restoreEncodedMigrationSnapshot(id, conn, account, migrate_token, snapshot, .join_existing)) {
                self.markSessionResumeRetryable(conn);
                try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "mesh session attach failed; token remains valid");
                return;
            }
            conn.preserve_resume_credential_once = false;
            _ = self.markPortableResumeIssuedForConn(id, conn, account);
            self.finishDeferredSessionAutojoin(id, conn, true);
            if (self.refreshPortableSessionReplicas(id, conn, account, migrate_token))
                self.flushDeferredSessionMeshAnnouncements(id, conn);
            try self.noticeTo(conn, "SESSION RESUME: attached to live mesh session");
            return;
        }

        const detached = self.sessions.findDetachedTokenSessionInAccount(account, migrate_token);
        const ghost: ?sessions_mod.ClientId = if (detached) |session| session.client else null;
        const origin_is_self = std.mem.eql(u8, fields.origin_node, self.serverName());
        // A live-session migration capsule for this exact session token may have
        // been shipped ahead of the client by the owning node. The token's HMAC,
        // expiry and account-ownership checks above gate this restore
        // EXACTLY as they gate the legacy grant paths — migration never weakens
        // them. A staged capsule means the full session state is now HERE, so a
        // would-be redirect becomes a local restore.
        const have_capsule = if (self.pending_migrations) |*pm|
            pm.getLive(migrate_token, @intCast(@min(now, @as(u64, std.math.maxInt(i64))))) != null
        else
            false;
        var buf: [default_reply_bytes]u8 = undefined;
        // A signed staged snapshot is a bounded replica, not a one-shot transfer.
        // Keep it staged so every authenticated client presenting the same valid
        // MTOKEN can attach on this node.
        if (have_capsule and now <= fields.expiry_ms) {
            const staged_bind: sessions_mod.TokenBindKind = if (ghost != null)
                .join_existing
            else
                .{ .adopt_verified = true };
            if (self.restoreStagedMigration(id, conn, account, migrate_token, staged_bind, null)) {
                conn.preserve_resume_credential_once = false;
                _ = self.markPortableResumeIssuedForConn(id, conn, account);
                self.finishDeferredSessionAutojoin(id, conn, true);
                if (self.refreshPortableSessionReplicas(id, conn, account, migrate_token))
                    self.flushDeferredSessionMeshAnnouncements(id, conn);
                try self.noticeTo(conn, "SESSION RESUME: attached to replicated mesh session");
                const event = std.fmt.bufPrint(&buf, "SESSION replica-attached account={s}", .{account}) catch return;
                self.publishOperEvent(.service, .notice, event) catch {};
                return;
            }
            // Restore failed mid-way: fall through to the legacy decision so the
            // client still gets a coherent (redirect/deny) answer.
        }
        const peer_names = self.readPeerNames() catch PeerNameSnapshot{
            .names = &.{},
            .count = 0,
            .allocator = self.allocator,
            .owned = false,
        };
        defer peer_names.deinit();
        var origin_reachable = origin_is_self;
        for (0..peer_names.count) |i| {
            const name = peer_names.name(i);
            if (std.ascii.eqlIgnoreCase(name, fields.origin_node)) {
                origin_reachable = true;
                break;
            }
        }
        switch (session_reclaim_mesh.decide(fields, ghost != null, origin_is_self, origin_reachable, false, now)) {
            .grant_local => {
                // Legacy SRM1 has only group authority. Clone its state into the
                // claimant's fresh attachment; never consume a detached sibling
                // or transfer attachment-specific durable delivery ownership.
                const local_snapshot = self.sessions.copyDetachedSnapshotInAccount(self.allocator, account, migrate_token) catch null;
                defer if (local_snapshot) |bytes| self.allocator.free(bytes);
                const restored = if (local_snapshot) |bytes| self.restoreEncodedMigrationSnapshot(
                    id,
                    conn,
                    account,
                    migrate_token,
                    bytes,
                    .join_existing,
                ) else false;

                if (local_snapshot != null and !restored) {
                    self.markSessionResumeRetryable(conn);
                    try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "session restore failed; token remains valid");
                    return;
                }

                if (ghost) |g| {
                    _ = g;
                    if (local_snapshot == null and !self.sessions.joinTokenGroup(account, cid, migrate_token)) {
                        self.markSessionResumeRetryable(conn);
                        try self.warnReply(conn, "SESSION", "TEMPORARILY_UNAVAILABLE", "mesh session registry changed during resume; retry the same token");
                        return;
                    }
                } else unreachable;
                if (local_snapshot == null) self.bindDeferredSessionMeshAnnouncements(id, conn, migrate_token);
                conn.preserve_resume_credential_once = false;
                _ = self.markPortableResumeIssuedForConn(id, conn, account);
                self.finishDeferredSessionAutojoin(id, conn, restored);
                if (self.refreshPortableSessionReplicas(id, conn, account, migrate_token))
                    self.flushDeferredSessionMeshAnnouncements(id, conn);
                if (restored) {
                    try self.noticeTo(conn, "SESSION RESUME: session restored (cross-server)");
                } else {
                    try self.noticeTo(conn, "SESSION RESUME: session reclaimed (cross-server)");
                }
                const event = std.fmt.bufPrint(&buf, "SESSION {s} cross-server account={s}", .{ if (restored) "restored" else "reclaimed", account }) catch return;
                self.publishOperEvent(.service, .notice, event) catch {};
            },
            .grant_redirect => |node| {
                // The session lives on `node`; the client must reconnect there. The
                // owning node ships the migration capsule from its own grant_local
                // path (above) when it consumes the ghost, so the peer the client
                // lands on already has the staged capsule to restore from.
                self.markSessionResumeRetryable(conn);
                const line = std.fmt.bufPrint(&buf, "SESSION REDIRECT: session lives on {s}; reconnect there to reclaim", .{node}) catch return;
                try self.noticeTo(conn, line);
            },
            .deny_expired => try self.failReply(conn, "SESSION", "INVALID_TOKEN", "reclaim token expired"),
            .deny_replay => unreachable, // reusable credentials are never probed as consumed
            .deny_unknown => try self.failReply(conn, "SESSION", "NO_SESSION", "no matching session on origin node"),
            .deny_unreachable => {
                self.markSessionResumeRetryable(conn);
                try self.warnReply(conn, "SESSION", "ORIGIN_UNREACHABLE", "origin is disconnected; retry this resume credential when the mesh converges");
            },
        }
    }

    // -----------------------------------------------------------------------
    // Live cross-mesh session migration (Helix migration_relay over Undertow).
    //
    // A node that holds a detached session ("origin"/owner) ships a signed
    // migration capsule to its secured peers ahead of the client's reconnect.
    // The peer that receives the capsule verifies it (`MigrationTarget.accept`)
    // and stages it in `pending_migrations`, keyed by the 16-byte session token.
    // When the client reconnects there and presents its mesh-sealed reclaim
    // token, `handleMeshReclaim` consumes the staged capsule and restores the
    // full session, REUSING the same restore helpers as the Helix UPGRADE path
    // (`session.restore` + `world.registerNick` + `world.restoreMember`).
    // -----------------------------------------------------------------------

    /// The Ed25519 signing identity for migration capsules — the SAME key used to
    /// sign oper grants (node identity), so a receiving peer verifies a capsule
    /// against `peerNodeKey()` exactly as it does an oper grant.
    fn migrationKeypair(self: *LinuxServer) ?migration_relay.KeyPair {
        return self.meshSignKey();
    }

    /// Build a borrowed `migration_relay.Snapshot` of `conn`'s session into the
    /// caller-provided channel-name buffer. The returned snapshot borrows `conn`'s
    /// inline session buffers + `chan_buf`, so it must be encoded before `conn` is
    /// mutated. Mirrors the field set the Helix UPGRADE snapshot carries.
    fn buildMigrationSnapshot(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        chan_buf: [][]const u8,
        chan_mode_buf: []u8,
        umode_buf: []u8,
    ) migration_relay.Snapshot {
        const wid = worldIdFromClient(id);
        const nch = self.world.channelsOf(wid, chan_buf);
        var chan_n: usize = 0;
        for (chan_buf[0..nch]) |chan| {
            const modes = self.world.memberModes(chan, wid) orelse continue;
            chan_buf[chan_n] = chan;
            chan_mode_buf[chan_n] = modes.bits;
            chan_n += 1;
        }
        const umodes = conn.session.umodeString(umode_buf);
        return .{
            .nick = conn.session.displayName(),
            .umodes = umodes,
            .channels = chan_buf[0..chan_n],
            .channel_modes = chan_mode_buf[0..chan_n],
            .realname = conn.session.realname(),
            .host = conn.session.host(),
            .account = conn.session.account() orelse "",
            .away = conn.session.awayMessage() orelse "",
            .username = conn.session.username(),
            .is_oper = conn.session.isOper(),
        };
    }

    fn encodeMigrationSnapshot(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) ?[]u8 {
        const chan_cap = self.world.channelCountOf(worldIdFromClient(id));
        const chan_buf = self.allocator.alloc([]const u8, chan_cap) catch return null;
        defer self.allocator.free(chan_buf);
        const chan_mode_buf = self.allocator.alloc(u8, chan_cap) catch return null;
        defer self.allocator.free(chan_mode_buf);
        var umode_buf: [usermode.MAX_MODE_CHANGES + 2]u8 = undefined;
        const snapshot = self.buildMigrationSnapshot(id, conn, chan_buf, chan_mode_buf, umode_buf[0..]);
        return snapshot.encode(self.allocator) catch null;
    }

    /// Ship a migration capsule for the live attachment `conn` (the session
    /// identified by the 16-byte `session_token`) to every established secured
    /// peer, so another client can attach there immediately and a resumed node
    /// can establish reciprocal routes. Detach snapshots use the companion
    /// detached-copy path below. Best-effort: a missing signing key or any
    /// encode/ship failure silently no-ops (the legacy redirect path still
    /// works). Uses `MigrationOrigin.prepare` for canonical hashing/signatures.
    fn shipSessionMigration(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        session_token: session_migrate.Token,
    ) bool {
        const chan_cap = self.world.channelCountOf(worldIdFromClient(id));
        const chan_buf = self.allocator.alloc([]const u8, chan_cap) catch {
            _ = self.sessions.markTokenReplicaDirty(session_token);
            return false;
        };
        defer self.allocator.free(chan_buf);
        const chan_mode_buf = self.allocator.alloc(u8, chan_cap) catch {
            _ = self.sessions.markTokenReplicaDirty(session_token);
            return false;
        };
        defer self.allocator.free(chan_mode_buf);
        var umode_buf: [usermode.MAX_MODE_CHANGES + 2]u8 = undefined;
        const snapshot = self.buildMigrationSnapshot(id, conn, chan_buf, chan_mode_buf, umode_buf[0..]);

        const snapshot_bytes = snapshot.encode(self.allocator) catch {
            _ = self.sessions.markTokenReplicaDirty(session_token);
            return false;
        };
        defer self.allocator.free(snapshot_bytes);
        // Set the durable retry bit BEFORE crossing the Store boundary. A
        // successful accept clears it; every allocation/signing/capacity failure
        // leaves both the exact publication and deferred sidecars retryable.
        _ = self.sessions.markTokenReplicaDirty(session_token);
        const published = self.publishSessionReplicaUpsert(
            session_token,
            account,
            snapshot.nick,
            snapshot_bytes,
            self.sessions.tokenHasAttachedPortable(session_token),
        );
        // Rolling-old compatibility is an independent best-effort sidecar. A
        // legacy encode/send failure must never suppress the v2 signed OFFER.
        const wire = self.encodeSessionMigration(account, session_token, snapshot) orelse return published;
        defer self.allocator.free(wire);
        self.broadcastSessionMigration(session_token, wire);
        self.recordSessionReplicaIdentity(session_token, account, snapshot.nick);
        return published;
    }

    fn recordSessionReplicaRoute(self: *LinuxServer, token: session_migrate.Token, peer: u64) void {
        const key = SessionReplicaRoute{ .token = token, .peer = peer };
        if (self.session_replica_routes.contains(key)) return;
        // Bound stale routes without evicting a token that still belongs to a
        // live/detached local logical session.  Independent arbitrary eviction
        // used to delete an active route while its identity row survived (or the
        // reverse), permanently disabling a valid remote attachment at the cap.
        const cap = @max(@as(usize, 64), self.config.session_max_pending_migrations *| 16);
        if (self.session_replica_routes.count() >= cap) {
            var it = self.session_replica_routes.keyIterator();
            var stale: ?SessionReplicaRoute = null;
            while (it.next()) |candidate| {
                if (!self.sessionReplicaTokenTracked(candidate.token)) {
                    stale = candidate.*;
                    break;
                }
            }
            if (stale) |evict| {
                _ = self.session_replica_routes.remove(evict);
            } else return; // all entries are pinned active; refuse unsafe eviction
        }
        self.session_replica_routes.put(self.allocator, key, {}) catch {};
        if (self.session_replica_identities.get(token)) |identity| self.rebuildSessionReplicaNick(identity.nickSlice());
    }

    fn sessionReplicaIndexCap(self: *const LinuxServer) usize {
        return @max(@as(usize, 64), self.config.session_max_pending_migrations *| 16);
    }

    fn sessionReplicaTokenTracked(self: *const LinuxServer, token: session_migrate.Token) bool {
        var account_buf: [session_replica_account_max]u8 = undefined;
        return self.sessions.findByTokenInto(token, &account_buf) != null;
    }

    fn removeSessionReplicaRoutes(self: *LinuxServer, token: session_migrate.Token) void {
        while (true) {
            var it = self.session_replica_routes.keyIterator();
            var found: ?SessionReplicaRoute = null;
            while (it.next()) |route| {
                if (std.crypto.timing_safe.eql(session_migrate.Token, route.token, token)) {
                    found = route.*;
                    break;
                }
            }
            if (found) |route| {
                _ = self.session_replica_routes.remove(route);
            } else return;
        }
    }

    fn recordSessionReplicaIdentity(
        self: *LinuxServer,
        token: session_migrate.Token,
        account: []const u8,
        nick: []const u8,
    ) void {
        if (account.len == 0 or account.len > session_replica_account_max or nick.len == 0 or nick.len > session_replica_nick_max) return;
        if (!self.session_replica_identities.contains(token) and self.session_replica_identities.count() >= self.sessionReplicaIndexCap()) {
            var it = self.session_replica_identities.keyIterator();
            var stale: ?session_migrate.Token = null;
            while (it.next()) |candidate| {
                if (!self.sessionReplicaTokenTracked(candidate.*)) {
                    stale = candidate.*;
                    break;
                }
            }
            if (stale) |evicted_token| {
                const evicted = self.session_replica_identities.get(evicted_token);
                _ = self.session_replica_identities.remove(evicted_token);
                self.removeSessionReplicaRoutes(evicted_token);
                if (evicted) |identity| self.rebuildSessionReplicaNick(identity.nickSlice());
            } else return; // never split an active identity from its route
        }
        const result = self.session_replica_identities.getOrPut(self.allocator, token) catch return;
        const previous: ?SessionReplicaIdentity = if (result.found_existing) result.value_ptr.* else null;
        const identity = result.value_ptr;
        @memcpy(identity.account[0..account.len], account);
        identity.account_len = @intCast(account.len);
        @memcpy(identity.nick[0..nick.len], nick);
        identity.nick_len = @intCast(nick.len);
        if (previous) |old| {
            if (!std.ascii.eqlIgnoreCase(old.nickSlice(), nick)) self.rebuildSessionReplicaNick(old.nickSlice());
        }
        self.rebuildSessionReplicaNick(nick);
    }

    fn sessionReplicaIdentityIsCurrentDetached(
        self: *LinuxServer,
        token: session_migrate.Token,
        identity: *const SessionReplicaIdentity,
        nick: []const u8,
    ) bool {
        if (!self.hasSessionReplicaRoute(token)) return false;
        const encoded_opt = self.sessions.copyDetachedSnapshotInAccount(self.allocator, identity.accountSlice(), token) catch return false;
        const encoded = encoded_opt orelse return false;
        defer self.allocator.free(encoded);
        var snapshot = migration_relay.Snapshot.decode(self.allocator, encoded) catch return false;
        defer snapshot.deinit(self.allocator);
        return std.ascii.eqlIgnoreCase(snapshot.account, identity.accountSlice()) and
            std.ascii.eqlIgnoreCase(snapshot.nick, nick);
    }

    fn rebuildSessionReplicaNick(self: *LinuxServer, nick: []const u8) void {
        const key = SessionReplicaNickKey.init(nick) orelse return;
        var candidates = SessionReplicaNickCandidates{};
        var it = self.session_replica_identities.iterator();
        while (it.next()) |entry| {
            if (!std.ascii.eqlIgnoreCase(entry.value_ptr.nickSlice(), nick)) continue;
            // Only current detached snapshots can authorize the fallback lookup.
            // Historical identity rows therefore cannot make a live token
            // permanently ambiguous, and the hot path remains O(1)/two checks.
            if (!self.sessionReplicaIdentityIsCurrentDetached(entry.key_ptr.*, entry.value_ptr, nick)) continue;
            if (candidates.count < candidates.tokens.len) {
                candidates.tokens[candidates.count] = entry.key_ptr.*;
                candidates.count += 1;
            } else {
                candidates.ambiguous = true;
                break;
            }
        }
        if (candidates.count == 0) {
            _ = self.session_replica_nicks.remove(key);
        } else {
            self.session_replica_nicks.put(self.allocator, key, candidates) catch {};
        }
    }

    fn hasSessionReplicaRoute(self: *const LinuxServer, token: session_migrate.Token) bool {
        var it = self.session_replica_routes.keyIterator();
        while (it.next()) |route| {
            if (std.crypto.timing_safe.eql(session_migrate.Token, route.token, token)) return true;
        }
        return false;
    }

    /// Resolve an otherwise-unroutable nick through one detached portable
    /// session snapshot that this node already replicated to authenticated peers.
    /// The case-folded primary index makes attacker-controlled misses O(1) and
    /// validates at most two matching current snapshots. More candidates are an
    /// explicit ambiguity marker and fail closed.
    fn detachedReplicaTokenForNick(self: *LinuxServer, nick: []const u8) ?session_migrate.Token {
        const key = SessionReplicaNickKey.init(nick) orelse return null;
        const candidates = self.session_replica_nicks.get(key) orelse return null;
        if (candidates.ambiguous) return null;
        var found: ?session_migrate.Token = null;
        for (candidates.tokens[0..candidates.count]) |token| {
            if (!self.hasSessionReplicaRoute(token)) continue;
            const identity = self.session_replica_identities.getPtr(token) orelse continue;
            const encoded = self.sessions.copyDetachedSnapshotInAccount(self.allocator, identity.accountSlice(), token) catch null orelse continue;
            defer self.allocator.free(encoded);
            var snapshot = migration_relay.Snapshot.decode(self.allocator, encoded) catch continue;
            defer snapshot.deinit(self.allocator);
            if (!std.ascii.eqlIgnoreCase(snapshot.account, identity.accountSlice())) continue;
            if (!std.ascii.eqlIgnoreCase(snapshot.nick, nick)) continue;
            if (found) |previous| {
                if (!std.crypto.timing_safe.eql(session_migrate.Token, previous, token)) return null;
            } else {
                found = token;
            }
        }
        return found;
    }

    /// Sign and wrap one portable snapshot. Detach-time fanout and peer-rejoin
    /// anti-entropy deliberately share this path so nonce/epoch ordering,
    /// account binding, and replay policy cannot drift apart.
    fn encodeSessionMigration(
        self: *LinuxServer,
        account: []const u8,
        session_token: session_migrate.Token,
        snapshot: migration_relay.Snapshot,
    ) ?[]u8 {
        const kp = self.migrationKeypair() orelse return null;

        // The relay object verifies and signs one message. Durable replay/order
        // state lives in the bounded token-keyed pending/tombstone store, not in
        // the relay's unbounded account/nonce maps (which also collide across
        // independent origin peers whose counters start at the same value).
        var origin = migration_relay.MigrationOrigin.init(self.allocator, kp);
        defer origin.deinit();

        // Reserve six decimal digits per wall-clock millisecond for same-tick
        // offers. The process-local floor makes every offer strictly newer;
        // wall time makes restart/USR2 epochs comparable at another host.
        const wall_epoch = @max(@as(u64, 1), self.meshWallMs()) *| 1_000_000;
        lockSpin(&self.mesh_clock_lock);
        const next_epoch = std.math.add(u64, self.migration_offer_epoch, 1) catch {
            self.mesh_clock_lock.unlock();
            return null;
        };
        const epoch = @max(wall_epoch, next_epoch);
        if (epoch <= self.migration_offer_epoch) {
            self.mesh_clock_lock.unlock();
            return null;
        }
        self.migration_offer_epoch = epoch;
        self.mesh_clock_lock.unlock();
        var prepared = origin.prepare(account, snapshot, epoch, epoch) catch return null;
        defer prepared.deinit(self.allocator);

        // Wrap the relay frame in a session_migrate.Capsule keyed by the 16-byte
        // session token (the key the attachment side looks up), and ship it over the
        // secured mesh. The relay frame bytes ARE the capsule's snapshot blob.
        const cap = session_migrate.Capsule{
            .token = session_token,
            .account = account,
            .snapshot = prepared.frame_bytes,
        };
        return session_migrate.encode(self.allocator, cap) catch null;
    }

    /// Re-encode one dirty portable token from a live attachment (preferred) or
    /// its retained detached snapshot. The dirty bit remains set until
    /// `publishSessionReplicaUpsert` synchronously accepts the canonical signed
    /// object into the local Store; allocation/signing/Store failures therefore
    /// become retryable rather than silently losing a JOIN/PART mutation.
    fn publishCurrentSessionReplicaToken(self: *LinuxServer, token: session_migrate.Token) bool {
        var account_buf: [session_replica_account_max]u8 = undefined;
        const match = self.sessions.findByTokenInto(token, &account_buf) orelse return false;
        const rows = self.sessions.copySessionsAlloc(self.allocator, match.account) catch return false;
        defer self.allocator.free(rows);

        for (rows) |row| {
            if (!row.attached or !std.crypto.timing_safe.eql(sessions_mod.Token, row.token, token)) continue;
            const id = clientIdFromMonitor(row.client);
            const conn = self.connFor(id) orelse continue;
            if (conn.closing or conn.s2s != null or conn.s2s_secured != null) continue;
            const account = conn.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(account, match.account)) continue;
            const snapshot = self.encodeMigrationSnapshot(id, conn) orelse continue;
            defer self.allocator.free(snapshot);
            if (self.publishSessionReplicaUpsert(token, match.account, conn.session.displayName(), snapshot, true)) return true;
        }

        // A disconnect may race the retry turn after preserving an exact owned
        // snapshot in SessionStore. That detached copy is still a valid source;
        // it keeps the mutation retryable without retaining a dead ConnState.
        const encoded = self.sessions.copyDetachedSnapshotInAccount(self.allocator, match.account, token) catch null orelse return false;
        defer self.allocator.free(encoded);
        var snapshot = migration_relay.Snapshot.decode(self.allocator, encoded) catch return false;
        defer snapshot.deinit(self.allocator);
        if (!std.ascii.eqlIgnoreCase(snapshot.account, match.account)) return false;
        return self.publishSessionReplicaUpsert(token, match.account, snapshot.nick, encoded, false);
    }

    /// Cross the publication boundary for one exact logical token. Remote
    /// projection deliberately does nothing: the accepted signed object was
    /// already forwarded canonically by `drainSessionReplicaV2`.
    fn convergeSessionReplicaToken(
        self: *LinuxServer,
        token: session_migrate.Token,
        source: SessionReplicaConvergenceSource,
    ) void {
        switch (source) {
            .remote_projection => return,
            .local_mutation => {},
        }
        if (tokenIsNull(token) or !self.sessions.markTokenReplicaDirty(token)) return;
        _ = self.publishCurrentSessionReplicaToken(token);
    }

    fn commitPortableSessionMutation(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) bool {
        const account = conn.session.account() orelse return true;
        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse return true;
        if (!handle.portable or tokenIsNull(handle.token)) return true;
        if (!self.sessions.markTokenReplicaDirty(handle.token)) return false;
        return self.publishCurrentSessionReplicaToken(handle.token);
    }

    /// Reactor-0 bounded retry for local mutations that could not allocate,
    /// encode, sign, or enter the local Store on their command turn. Successful
    /// tokens clear themselves only at Store acceptance; failures stay dirty for
    /// the next turn.
    fn retryDirtySessionReplicaTokens(self: *LinuxServer) void {
        var tokens: [session_replica_dirty_retry_batch]sessions_mod.Token = undefined;
        const dirty = self.sessions.dirtyPortableTokensInto(&tokens);
        for (dirty) |token| _ = self.publishCurrentSessionReplicaToken(token);
        self.flushReadyDeferredSessionMeshAnnouncements();
    }

    fn retryDirtySessionReplicaProjections(self: *LinuxServer) void {
        var tokens: [session_replica_dirty_retry_batch]sessions_mod.Token = undefined;
        const dirty = self.sessions.dirtyProjectionTokensInto(&tokens);
        for (dirty) |token| _ = self.projectBestSessionReplicaV2(token);
    }

    /// Retry final removal authority after the row that would normally carry a
    /// dirty bit no longer exists. A failed REVOKE leaves the local-origin OFFER
    /// in the checkpointed Store, so this ordered bounded scan is both the retry
    /// journal and its hot-upgrade recovery path.
    fn retryOrphanedLocalSessionReplicaRevokes(self: *LinuxServer) void {
        if (self.config.node_identity == null) return;
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        var tokens: [session_replica_dirty_retry_batch]session_migrate.Token = undefined;
        const page = self.session_replica_store.authorityTokensAfter(
            now_wall,
            self.session_replica_orphan_revoke_cursor,
            &tokens,
        );
        if (page.len == 0) {
            self.session_replica_orphan_revoke_cursor = null;
            return;
        }
        for (page) |token| {
            if (self.session_replica_store.getOrigin(token, self.config.node_id) == null) continue;
            if (self.sessions.containsToken(token)) continue;
            self.publishSessionReplicaRevoke(token);
        }
        self.session_replica_orphan_revoke_cursor = if (page.len == tokens.len) page[page.len - 1] else null;
    }

    fn scheduleSessionReplicaStageRetry(self: *LinuxServer) void {
        if (self.session_replica_stage_retry_pending) {
            // A new failed token may sort behind the active value cursor. Force
            // one wrap after this pass so mutation churn cannot strand it.
            self.session_replica_stage_retry_pass_failed = true;
        } else {
            self.session_replica_stage_retry_cursor = null;
            self.session_replica_stage_retry_pass_failed = false;
        }
        self.session_replica_stage_retry_pending = true;
    }

    fn retrySessionReplicaStoreStages(self: *LinuxServer) void {
        if (!self.session_replica_stage_retry_pending) return;

        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        var tokens: [session_replica_dirty_retry_batch]session_migrate.Token = undefined;
        const page = self.session_replica_store.authorityTokensAfter(
            now_wall,
            self.session_replica_stage_retry_cursor,
            &tokens,
        );
        if (page.len == 0) {
            if (self.session_replica_stage_retry_pass_failed) {
                self.session_replica_stage_retry_cursor = null;
                self.session_replica_stage_retry_pass_failed = false;
            } else {
                self.session_replica_stage_retry_pending = false;
                self.session_replica_stage_retry_cursor = null;
            }
            return;
        }

        for (page) |token| _ = self.projectBestSessionReplicaV2(token);
        self.session_replica_stage_retry_cursor = page[page.len - 1];
        if (page.len < tokens.len) {
            if (self.session_replica_stage_retry_pass_failed) {
                self.session_replica_stage_retry_cursor = null;
                self.session_replica_stage_retry_pass_failed = false;
            } else {
                self.session_replica_stage_retry_pending = false;
                self.session_replica_stage_retry_cursor = null;
            }
        }
    }

    fn nextSessionReplicaRevision(self: *LinuxServer) session_replica_v2.Revision {
        // The mesh HLC is snapshotted across Helix UPGRADE and never regresses.
        // Reusing it here makes revisions restart-safe without a second volatile
        // counter that could repeat after exec/resume.
        const stamp = self.nextMeshHlc();
        return .{
            .epoch = mesh_clock_mod.MeshClock.physicalOf(stamp),
            .sequence = stamp,
            .origin_node = self.config.node_id,
        };
    }

    /// Mint one short positive proof for this node's current local OFFER. The
    /// lease uses a strictly newer HLC revision and is stored before fanout, so
    /// reconnect replay can recover a socket-send failure. A failure keeps the
    /// token dirty: the ordinary exact-token retry will republish a fresh OFFER
    /// and lease without relying on volatile per-link state.
    fn publishSessionAttachmentLease(self: *LinuxServer, token: session_migrate.Token) bool {
        if (!self.sessions.tokenHasAttachedPortable(token)) return false;
        const ident = self.config.node_identity orelse return false;
        if (ident.shortId() != self.config.node_id) return false;
        const offer = self.session_replica_store.getOrigin(token, self.config.node_id) orelse return false;
        const signed_offer = session_replica_v2.decodeOffer(offer.wire) catch return false;
        if (!std.crypto.timing_safe.eql(crypto_sign.PublicKey, signed_offer.signer, ident.sign_kp.public_key))
            return false;

        const revision = self.nextSessionReplicaRevision();
        if (revision.compare(offer.revision) != .gt) return false;
        const latest_issue = @as(u64, std.math.maxInt(i64)) - session_attachment_lease_ttl_ms;
        const issued_u = @min(@min(self.meshWallMs(), revision.epoch), latest_issue);
        const issued: i64 = @intCast(issued_u);
        const signed_wire = session_replica_v2.encodeAttachmentLease(self.allocator, .{
            .token = token,
            .revision = revision,
            .issued_at_ms = issued,
            .expires_at_ms = issued + @as(i64, @intCast(session_attachment_lease_ttl_ms)),
        }, &ident.sign_kp) catch {
            _ = self.sessions.markTokenReplicaDirty(token);
            return false;
        };
        defer self.allocator.free(signed_wire);
        const signed = session_replica_v2.decodeAttachmentLease(signed_wire) catch {
            _ = self.sessions.markTokenReplicaDirty(token);
            return false;
        };
        const disposition = self.session_replica_store.applySignedAttachmentLease(signed, issued) catch {
            _ = self.sessions.markTokenReplicaDirty(token);
            return false;
        };
        switch (disposition) {
            .inserted, .superseded => {},
            .duplicate, .conflict, .stale => {
                _ = self.sessions.markTokenReplicaDirty(token);
                return false;
            },
        }
        self.session_replica_store_generation +%= 1;
        self.broadcastSessionReplicaV2(.attachment_lease, signed_wire, null);
        return true;
    }

    /// Sign one exact local snapshot, seed the local authority Store, then send
    /// the SAME canonical object to every v2-capable secured peer. Minting once
    /// is essential: per-link revisions would make arrival order choose a route.
    fn publishPreparedFreshSessionReplica(
        self: *LinuxServer,
        token: session_migrate.Token,
        account: []const u8,
        nick: []const u8,
        snapshot: []const u8,
    ) bool {
        // Called while PreparedBootstrapTokenAttach retains SessionStore's
        // exclusive lock. Do not consult or mutate SessionStore here. Every
        // fallible signing/Store step precedes the ticket's no-fail commit.
        const ident = self.config.node_identity orelse return false;
        if (ident.shortId() != self.config.node_id) return false;
        const issued_u = @min(self.meshWallMs(), @as(u64, std.math.maxInt(i64)) - mesh_reclaim_ttl_ms);
        const issued: i64 = @intCast(issued_u);
        const signed_wire = session_replica_v2.encodeOffer(self.allocator, .{
            .operation = .upsert,
            .token = token,
            .revision = self.nextSessionReplicaRevision(),
            .issued_at_ms = issued,
            .expires_at_ms = issued + @as(i64, @intCast(mesh_reclaim_ttl_ms)),
            .account = account,
            .nick = nick,
            .snapshot = snapshot,
        }, &ident.sign_kp) catch return false;
        defer self.allocator.free(signed_wire);
        const signed = session_replica_v2.decodeOffer(signed_wire) catch return false;
        const result = self.session_replica_store.applySignedOffer(signed, 0, issued) catch return false;
        const accepted = switch (result.disposition) {
            .inserted, .conflict_replaced, .superseded => true,
            .duplicate, .conflict, .quarantined, .stale, .tombstoned => false,
        };
        if (!accepted) return false;
        self.session_replica_store_generation +%= 1;
        self.broadcastSessionReplicaV2(.offer, signed_wire, null);
        return true;
    }

    fn publishSessionReplicaUpsert(
        self: *LinuxServer,
        token: session_migrate.Token,
        account: []const u8,
        nick: []const u8,
        snapshot: []const u8,
        attached: bool,
    ) bool {
        // Arm the row-backed retry before any fallible encode/sign/Store step.
        // Periodic refresh calls this function directly; without this boundary a
        // transient failure would disappear until the next four-hour pass.
        _ = self.sessions.markTokenReplicaDirty(token);
        const ident = self.config.node_identity orelse return false;
        if (ident.shortId() != self.config.node_id) return false;
        const issued_u = @min(self.meshWallMs(), @as(u64, std.math.maxInt(i64)) - mesh_reclaim_ttl_ms);
        const issued: i64 = @intCast(issued_u);
        const signed_wire = session_replica_v2.encodeOffer(self.allocator, .{
            .operation = .upsert,
            .token = token,
            .revision = self.nextSessionReplicaRevision(),
            .issued_at_ms = issued,
            .expires_at_ms = issued + @as(i64, @intCast(mesh_reclaim_ttl_ms)),
            .account = account,
            .nick = nick,
            .snapshot = snapshot,
        }, &ident.sign_kp) catch return false;
        defer self.allocator.free(signed_wire);
        const signed = session_replica_v2.decodeOffer(signed_wire) catch return false;
        const result = self.session_replica_store.applySignedOffer(signed, 0, issued) catch return false;
        const accepted = switch (result.disposition) {
            .inserted, .conflict_replaced, .superseded => true,
            .duplicate, .conflict, .quarantined, .stale, .tombstoned => false,
        };
        if (!accepted) return false;
        self.session_replica_store_generation +%= 1;
        // Store acceptance is the durability boundary. Socket fanout is
        // best-effort because the canonical signed object now participates in
        // retained anti-entropy replay; only after this point may an OOM dirty
        // bit be cleared.
        _ = self.projectBestSessionReplicaV2(token);
        self.broadcastSessionReplicaV2(.offer, signed_wire, null);
        if (attached and !self.publishSessionAttachmentLease(token)) return false;
        _ = self.sessions.clearTokenReplicaDirty(token);
        return true;
    }

    /// Close this node's authority for an exact reusable token. The signed
    /// tombstone is applied locally before fanout so reclaim stops immediately
    /// on this node and anti-entropy retains the same canonical REVOKE for peers
    /// that reconnect later. Other origins remain independent and may become the
    /// Store-selected live projection.
    fn publishSessionReplicaRevoke(self: *LinuxServer, token: session_migrate.Token) void {
        const ident = self.config.node_identity orelse return;
        if (ident.shortId() != self.config.node_id) return;
        const issued_u = @min(self.meshWallMs(), @as(u64, std.math.maxInt(i64)) - mesh_reclaim_ttl_ms);
        const issued: i64 = @intCast(issued_u);
        const signed_wire = session_replica_v2.encodeOffer(self.allocator, .{
            .operation = .remove,
            .token = token,
            .revision = self.nextSessionReplicaRevision(),
            .issued_at_ms = issued,
            .expires_at_ms = issued + @as(i64, @intCast(mesh_reclaim_ttl_ms)),
        }, &ident.sign_kp) catch return;
        defer self.allocator.free(signed_wire);
        const signed = session_replica_v2.decodeOffer(signed_wire) catch return;
        const result = self.session_replica_store.applySignedOffer(signed, 0, issued) catch return;
        const advanced = switch (result.disposition) {
            .conflict_replaced, .superseded, .tombstoned => true,
            .inserted, .duplicate, .conflict, .quarantined, .stale => false,
        };
        if (!advanced) return;
        self.session_replica_store_generation +%= 1;
        _ = self.projectBestSessionReplicaV2(token);
        self.broadcastSessionReplicaV2(.revoke, signed_wire, null);
    }

    /// Forward or publish one canonical v2 object over negotiated secured links.
    /// `skip_peer` prevents immediate bounce on forwarded OFFER/REVOKE objects;
    /// per-Store disposition prevents later loop amplification.
    fn broadcastSessionReplicaV2(
        self: *LinuxServer,
        kind: s2s_link.SessionReplicaKind,
        signed_wire: []const u8,
        skip_peer: ?u64,
    ) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established()) continue;
                if (!link.supportsSessionReplicaV2()) {
                    // Reusable portable authority cannot be represented exactly
                    // by the legacy one-shot SESSION_MIGRATE envelope. In
                    // particular its receiver intentionally ignores consumed
                    // notices, has no signed revoke/quarantine object, and
                    // restages a fresh TTL on every proxy. Keep such a peer out
                    // of a portability-enabled mesh instead of releasing a
                    // roster that will later diverge silently.
                    if (self.config.session_migrate_on_detach) slot.value.closing = true;
                    continue;
                }
                if (kind == .attachment_lease and !link.supportsSessionAttachmentLeaseV2()) continue;
                if (skip_peer) |skip| if (link.peerShortId() == skip) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                // The Store already retained this canonical object. Do not append
                // another live/lease record behind older secured ciphertext on
                // every refresh tick; drain first or let bounded Store replay
                // deliver the newest authority once the peer makes progress.
                if (!self.flushSecuredS2sOutboundTo(pid, link)) {
                    self.requestSessionReplicaReplayAfterFanoutFailure(&slot.value);
                    continue;
                }
                link.sendSessionReplica(kind, signed_wire) catch {
                    self.requestSessionReplicaReplayAfterFanoutFailure(&slot.value);
                    continue;
                };
                if (!self.flushSecuredS2sOutboundTo(pid, link)) {
                    self.requestSessionReplicaReplayAfterFanoutFailure(&slot.value);
                    continue;
                }
            }
        }
    }

    fn requestSessionReplicaReplayAfterFanoutFailure(self: *LinuxServer, conn: *ConnState) void {
        if (conn.session_replica_replay_pending) {
            // Mutations coalesced before this pass emits object zero are already
            // covered by its canonical Store scan. Only a failure behind an
            // advanced value cursor needs one bounded wrap.
            if (conn.session_replica_replay_after != null or conn.session_replica_replay_cursor != 0)
                conn.session_replica_replay_restart_pending = true;
        } else {
            self.scheduleSessionReplicaReplay(conn);
        }
    }

    fn scheduleSessionReplicaReplay(self: *LinuxServer, conn: *ConnState) void {
        conn.session_replica_replay_pending = true;
        conn.session_replica_replay_cursor = 0;
        conn.session_replica_replay_now_ms = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        conn.session_replica_replay_after = null;
        conn.session_replica_replay_restart_pending = false;
    }

    /// A peer whose converged view was reset must receive a replay from the
    /// beginning even when an earlier establishment/fanout pass is mid-page.
    /// Exact ciphertext already retained in the secured link cannot be thrown
    /// away because doing so would skip an AEAD send counter; finish that one
    /// frame and request a bounded wrap instead.
    fn requestFullSessionReplicaReplay(self: *LinuxServer, conn: *ConnState) void {
        const first_request = !conn.session_replica_resync_burst_pending;
        conn.session_replica_resync_burst_pending = true;
        if (conn.mesh_burst_stage != .idle) conn.mesh_burst_restart_pending = true;
        if (!conn.session_replica_replay_pending) return self.scheduleSessionReplicaReplay(conn);
        if (first_request) return self.scheduleSessionReplicaReplay(conn);
        // Every subsequent peer reset needs a complete Store generation too.
        // If this pass has not emitted anything it already starts at zero;
        // otherwise finish it and wrap once, preserving deterministic progress
        // under a burst of duplicate RESYNC records.
        if (conn.session_replica_replay_after != null or conn.session_replica_replay_cursor != 0)
            conn.session_replica_replay_restart_pending = true;
    }

    /// Release either the one-shot establishment burst or a requested RESYNC
    /// burst only after every retained signed authority object has entered this
    /// connection's SendQ. Both requests collapse into one full burst when they
    /// overlap during establishment.
    fn releaseMeshBurstAfterSessionReplicaReplay(
        self: *LinuxServer,
        conn: *ConnState,
        link: *secured_s2s_link.SecuredLink,
    ) void {
        if (!conn.ownsActiveMeshLink(link) or conn.session_replica_replay_pending) return;
        const establishment_pending = !conn.s2s_burst_done;
        if (!establishment_pending and !conn.session_replica_resync_burst_pending) return;

        if (!self.sendMeshStateBurstTo(conn)) return;
        conn.s2s_burst_done = true;
        conn.session_replica_resync_burst_pending = false;
    }

    fn finishSessionReplicaReplayPass(conn: *ConnState, current_now: i64) void {
        if (conn.session_replica_replay_restart_pending) {
            // A live direct fanout failed somewhere behind the ordered cursor.
            // Wrap exactly once after finishing this pass; mutation itself never
            // resets forward progress, so periodic lease renewal cannot starve a
            // Store larger than one timer window.
            conn.session_replica_replay_restart_pending = false;
            conn.session_replica_replay_after = null;
            conn.session_replica_replay_cursor = 0;
            conn.session_replica_replay_now_ms = current_now;
            return;
        }
        conn.session_replica_replay_pending = false;
        conn.session_replica_replay_cursor = 0;
        conn.session_replica_replay_after = null;
    }

    /// Replay a bounded deterministic retained-object page. Canonical Store
    /// wires are borrowed only for this call, while the connection retains a
    /// complete value cursor (token/kind/origin/revision/digest) between turns.
    /// Hash-map growth, expiry, supersede, and lease renewal therefore cannot
    /// invalidate or reset a large replay. Each turn queues at most eight frames
    /// and targets at most 256 KiB of actual ciphertext; one otherwise-legal
    /// oversized frame is allowed alone so the byte target cannot prevent
    /// progress. Cursor advancement happens only after exact ciphertext enters
    /// the socket SendQ.
    fn replaySessionReplicaStoreTo(
        self: *LinuxServer,
        conn: *ConnState,
        link: *secured_s2s_link.SecuredLink,
    ) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        if (!conn.session_replica_replay_pending) return;
        if (!link.established()) {
            conn.session_replica_replay_pending = false;
            conn.session_replica_replay_after = null;
            return;
        }
        const replica_v2 = link.supportsSessionReplicaV2();
        if (!replica_v2) {
            // A legacy peer is safe only when portable mesh sessions are
            // disabled. Otherwise there is no wire representation for reusable
            // authority expiry/revoke/quarantine; never release the membership
            // burst on a link that cannot converge those facts.
            if (self.config.session_migrate_on_detach) conn.closing = true;
            conn.session_replica_replay_pending = false;
            conn.session_replica_replay_after = null;
            return;
        }

        const max_frames_per_turn: usize = 8;
        const max_bytes_per_turn: usize = 256 * 1024;
        var queued_bytes: usize = 0;
        var frames_queued: usize = 0;

        // A RESYNC may interrupt a retryable mesh family whose complete sealed
        // records are still in the shared secured-link buffer. They cannot be
        // discarded or reordered past newly sealed authority records. Page them
        // through the same whole-record SendQ edge before selecting an object;
        // `mesh_burst_restart_pending` guarantees a fresh full family pass after
        // this authority generation completes.
        if (link.outbound().len != 0) {
            if (!self.flushMeshBurstStage(conn)) return;
        }

        const current_now: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        const now = conn.session_replica_replay_now_ms;
        if (frames_queued >= max_frames_per_turn or
            (frames_queued != 0 and queued_bytes >= max_bytes_per_turn)) return;

        var objects: [max_frames_per_turn]session_replica_v2.Store.RetainedObject = undefined;
        const remaining_frames = max_frames_per_turn - frames_queued;
        const n = self.session_replica_store.retainedObjectsAfter(
            now,
            conn.session_replica_replay_after,
            objects[0..remaining_frames],
        );
        if (n == 0) {
            finishSessionReplicaReplayPass(conn, current_now);
            return;
        }
        for (objects[0..n]) |object| {
            const object_cursor = object.cursor();
            const kind: s2s_link.SessionReplicaKind = switch (object.kind) {
                .offer => .offer,
                .revoke => .revoke,
                .attachment_lease => blk: {
                    if (!link.supportsSessionAttachmentLeaseV2()) {
                        // Rolling-old v2 peers must skip the extension without
                        // pinning this value cursor and blocking their residence
                        // burst forever.
                        conn.session_replica_replay_after = object_cursor;
                        conn.session_replica_replay_cursor += 1;
                        continue;
                    }
                    break :blk .attachment_lease;
                },
            };
            const ciphertext_len = sessionReplicaSecuredRecordLen(object.wire.len) orelse {
                conn.closing = true;
                return;
            };
            // Decide both byte budget and physical SendQ capacity before
            // encoding. `sendSessionReplica` advances the secured record counter;
            // once called, its exact ciphertext must have a no-fail commit edge.
            if (queued_bytes != 0 and
                (queued_bytes >= max_bytes_per_turn or ciphertext_len > max_bytes_per_turn - queued_bytes))
            {
                return;
            }
            reserveRawAppendToConn(conn, ciphertext_len) catch return;
            std.debug.assert(link.outbound().len == 0);
            link.sendSessionReplica(kind, object.wire) catch return;
            if (link.outbound().len != ciphertext_len) {
                conn.closing = true;
                return;
            }
            // Capacity and any overflow allocation were reserved above; failure
            // here is an internal invariant violation, not recoverable
            // backpressure. Keep the exact ciphertext and fail the peer closed.
            appendToConn(conn, link.outbound()) catch {
                conn.closing = true;
                return;
            };
            link.clearOutbound();
            conn.session_replica_replay_after = object_cursor;
            conn.session_replica_replay_cursor += 1;
            frames_queued += 1;
            self.armSendIfNeeded(conn) catch {
                conn.closing = true;
                return;
            };
            queued_bytes = std.math.add(usize, queued_bytes, ciphertext_len) catch std.math.maxInt(usize);
        }
        if (n < remaining_frames) finishSessionReplicaReplayPass(conn, current_now);
    }

    fn resumeSessionReplicaReplays(self: *LinuxServer) void {
        for (self.rx().clients.slots.items) |*slot| {
            if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
            const link = slot.value.s2s_secured orelse continue;
            if (slot.value.session_replica_replay_pending)
                self.replaySessionReplicaStoreTo(&slot.value, link);
            self.releaseMeshBurstAfterSessionReplicaReplay(&slot.value, link);
        }
    }

    /// Renew every locally held portable token once per lease cadence. A token
    /// shared by several live attachments is emitted exactly once per pass.
    fn refreshPortableSessionReplicasV2(self: *LinuxServer) void {
        if (!self.config.session_migrate_on_detach or self.config.node_identity == null) return;
        var refreshed: std.AutoHashMapUnmanaged(session_migrate.Token, void) = .empty;
        defer refreshed.deinit(self.allocator);

        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                if (conn.s2s != null or conn.s2s_secured != null or conn.closing) continue;
                const account = conn.session.account() orelse continue;
                const id = slotClientId(reactor, i, slot.gen);
                const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse continue;
                if (!handle.portable or tokenIsNull(handle.token) or refreshed.contains(handle.token)) continue;
                const snapshot_bytes = self.encodeMigrationSnapshot(id, conn) orelse continue;
                defer self.allocator.free(snapshot_bytes);
                var snapshot = migration_relay.Snapshot.decode(self.allocator, snapshot_bytes) catch continue;
                defer snapshot.deinit(self.allocator);
                refreshed.put(self.allocator, handle.token, {}) catch {
                    _ = self.sessions.markTokenReplicaDirty(handle.token);
                    continue;
                };
                _ = self.publishSessionReplicaUpsert(handle.token, account, snapshot.nick, snapshot_bytes, true);
            }
        }

        const copies = self.sessions.copyPortableDetachedSnapshots(self.allocator) catch return;
        defer {
            for (copies) |*copy| copy.deinit(self.allocator);
            self.allocator.free(copies);
        }
        for (copies) |copy| {
            if (refreshed.contains(copy.token)) continue;
            var snapshot = migration_relay.Snapshot.decode(self.allocator, copy.snapshot) catch continue;
            defer snapshot.deinit(self.allocator);
            if (!std.ascii.eqlIgnoreCase(snapshot.account, copy.account)) continue;
            refreshed.put(self.allocator, copy.token, {}) catch {
                _ = self.sessions.markTokenReplicaDirty(copy.token);
                continue;
            };
            _ = self.publishSessionReplicaUpsert(copy.token, copy.account, snapshot.nick, copy.snapshot, false);
        }
    }

    /// Renew only short positive attachment evidence. Detached rows never enter
    /// this walk, so their long-lived OFFER remains resumable without suppressing
    /// a final mesh QUIT. Allocation pressure in the dedup set marks the exact
    /// token dirty instead of silently missing a lease window.
    fn refreshAttachedSessionReplicaLeases(self: *LinuxServer) void {
        if (!self.config.session_migrate_on_detach or self.config.node_identity == null) return;
        var renewed: std.AutoHashMapUnmanaged(session_migrate.Token, void) = .empty;
        defer renewed.deinit(self.allocator);

        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                if (conn.s2s != null or conn.s2s_secured != null or conn.closing) continue;
                const account = conn.session.account() orelse continue;
                const id = slotClientId(reactor, i, slot.gen);
                const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse continue;
                if (!handle.portable or tokenIsNull(handle.token) or renewed.contains(handle.token)) continue;
                renewed.put(self.allocator, handle.token, {}) catch {
                    _ = self.sessions.markTokenReplicaDirty(handle.token);
                    continue;
                };
                if (self.session_replica_store.getOrigin(handle.token, self.config.node_id) == null) {
                    _ = self.sessions.markTokenReplicaDirty(handle.token);
                    _ = self.publishCurrentSessionReplicaToken(handle.token);
                    continue;
                }
                _ = self.publishSessionAttachmentLease(handle.token);
            }
        }
    }

    /// Broadcast an encoded `session_migrate` capsule to every established secured
    /// peer (the encrypted, authenticated leg — never the plaintext S2S path,
    /// since the capsule carries account/host state). Mirrors `broadcastOperGrant`.
    fn broadcastSessionMigration(self: *LinuxServer, token: session_migrate.Token, wire: []const u8) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                link.sendSessionMigrate(wire) catch continue;
                if (!self.flushSecuredS2sOutboundTo(pid, link)) continue;
                if (link.peerShortId()) |peer| self.recordSessionReplicaRoute(token, peer);
            }
        }
    }

    /// Legacy rolling-version compatibility for pre-multi-attachment peers that
    /// still emit one-shot consume notices. New code never calls this for a
    /// successful attach: reusable session replicas are retained until TTL.
    fn convergeSessionConsumed(self: *LinuxServer, account: []const u8, token: session_migrate.Token, nonce: ?u64) void {
        if (self.pending_migrations) |*pm| pm.markConsumed(token, self.nowMs()) catch {};
        if (nonce) |n| self.session_reclaim_replay.record(n);

        var payload_buf: [512]u8 = undefined;
        const payload = session_reclaim_mesh.encodeConsumeNotice(.{
            .session_token = token,
            .account = account,
            .nonce = nonce,
        }, &payload_buf) catch return;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                link.sendSessionMigrateConsumed(payload) catch continue;
                _ = self.flushSecuredS2sOutboundTo(pid, link);
            }
        }
    }

    fn drainSessionMigrationConsumed(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const notices = link.takeSessionMigrateConsumed() catch return;
        defer self.allocator.free(notices);
        for (notices) |wire| {
            defer self.allocator.free(wire);
            const notice = session_reclaim_mesh.decodeConsumeNotice(wire) catch continue;
            if (notice.account.len == 0) continue;
            self.applySessionConsumedNotice(notice);
        }
    }

    fn sendSessionReplicaAckV2(
        self: *LinuxServer,
        conn: *const ConnState,
        link: *secured_s2s_link.SecuredLink,
        status: session_replica_v2.AckStatus,
        offered: session_replica_v2.Revision,
        observed: session_replica_v2.Revision,
        token: session_migrate.Token,
        now_wall: i64,
    ) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const ident = self.config.node_identity orelse return;
        if (ident.shortId() != self.config.node_id) return;
        const ack_ttl_ms: i64 = 5 * 60 * 1000;
        const wire = session_replica_v2.encodeAck(self.allocator, .{
            .status = status,
            .token = token,
            .offered_revision = offered,
            .observed_revision = observed,
            .ack_node = self.config.node_id,
            .issued_at_ms = now_wall,
            .expires_at_ms = now_wall + ack_ttl_ms,
        }, &ident.sign_kp) catch return;
        defer self.allocator.free(wire);
        // ACK is a direct receipt only. It is intentionally never flooded: ACK
        // carries no path vector and therefore cannot safely create reachability.
        link.sendSessionReplicaAck(wire) catch {};
    }

    fn stageSessionReplicaV2Entry(self: *LinuxServer, token: session_migrate.Token, entry: *const session_replica_v2.Store.Entry) bool {
        const pm = if (self.pending_migrations) |*pending| pending else return true;
        var snapshot = migration_relay.Snapshot.decode(self.allocator, entry.snapshot) catch |err| {
            // Malformed signed state is terminal; only allocator pressure is
            // retryable. The live World projection makes the same distinction.
            return err != error.OutOfMemory;
        };
        defer snapshot.deinit(self.allocator);
        // The signed envelope and the exact encoded snapshot must describe one
        // identity. A relay-controlled account field is never consulted here.
        if (!std.mem.eql(u8, snapshot.account, entry.account) or
            !std.mem.eql(u8, snapshot.nick, entry.nick)) return true;
        pm.putReplica(.{
            .token = token,
            .account = entry.account,
            .snapshot = entry.snapshot,
        }, self.nowMs(), entry.revision, entry.expires_at_ms) catch |err| return switch (err) {
            error.OutOfMemory, error.PendingFull => false,
            error.AlreadyConsumed, error.StaleOffer, error.TokenAccountMismatch => true,
        };
        return true;
    }

    /// Remove checkpointed v2 reconnect projections that are not the exact
    /// deterministic winner in the independently restored signed Store. PMST is
    /// a cache of reclaim-ready snapshots, never an authority source: retaining
    /// an orphan after SRST revoke/quarantine would resurrect a denied session.
    /// Repeated single removals keep the boot-time pass allocation-free.
    fn prunePendingReplicasWithoutStoreAuthority(self: *LinuxServer, now_wall: i64) usize {
        const pm = if (self.pending_migrations) |*pending| pending else return 0;
        var removed: usize = 0;
        while (true) {
            var victim: ?session_migrate.Token = null;
            var it = pm.map.iterator();
            while (it.next()) |slot| {
                const revision = slot.value_ptr.replica_revision orelse continue;
                const best = self.session_replica_store.bestLiveIdentity(slot.key_ptr.*, now_wall);
                if (best == null or
                    !revision.eql(best.?.revision) or
                    slot.value_ptr.replica_expires_at_ms != best.?.expires_at_ms or
                    !std.mem.eql(u8, slot.value_ptr.account, best.?.account) or
                    !std.mem.eql(u8, slot.value_ptr.snapshot, best.?.snapshot))
                {
                    victim = slot.key_ptr.*;
                    break;
                }
            }
            const token = victim orelse break;
            if (pm.removeReplica(token)) removed += 1;
        }
        return removed;
    }

    /// Re-evaluate receiver-owned token metadata on every negotiated v2 roster
    /// after one signed origin/nick authority changes. Ambiguity preserves the
    /// existing tag; allocation failure is reported so the exact token remains
    /// projection-dirty and the operation can be retried.
    fn rebindSessionReplicaRoutes(self: *LinuxServer, origin_node: u64, nick: []const u8) bool {
        if (origin_node == 0 or nick.len == 0) return true;
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        // Ambiguity is not absence: preserve existing receiver-owned tags until
        // exact Store reconciliation resolves them. Clearing here would turn a
        // protected row back into a token-less compatibility mutation target.
        const match = self.session_replica_store.uniqueLiveOriginNick(origin_node, nick, now_wall) catch return true;
        const token: ?session_migrate.Token = if (match) |identity| identity.token else null;
        var complete = true;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established() or !link.supportsSessionReplicaV2()) continue;
                _ = link.rebindSessionToken(origin_node, nick, token) catch {
                    complete = false;
                    continue;
                };
            }
        }
        return complete;
    }

    /// Bind every current origin/nick authority for one exact token before
    /// reconciliation. This ordering makes OFFER-after-MEMBERSHIP safe and is
    /// repeated by retries, so a partial first pass cannot strand an untagged
    /// compatibility row with contradictory channel state.
    fn bindSessionReplicaRouteAuthorities(
        self: *LinuxServer,
        token: session_migrate.Token,
        now_wall: i64,
    ) bool {
        var complete = true;
        var cursor: ?u64 = null;
        while (true) {
            var identities: [16]session_replica_v2.Store.OriginIdentity = undefined;
            const page = self.session_replica_store.liveOriginIdentitiesAfter(token, now_wall, cursor, &identities);
            if (page.len == 0) return complete;
            for (page) |identity| {
                if (!self.rebindSessionReplicaRoutes(identity.origin_node, identity.nick)) complete = false;
            }
            cursor = page[page.len - 1].origin_node;
            if (page.len < identities.len) return complete;
        }
    }

    /// Remove only roster rows receiver-tagged with this exact token and absent
    /// from the deterministic best signed snapshot. Malformed signed snapshots
    /// fail closed to an empty desired set; allocation pressure is retryable.
    fn reconcileSessionReplicaRoutes(
        self: *LinuxServer,
        token: session_migrate.Token,
        entry: *const session_replica_v2.Store.Entry,
        mode: SessionReplicaProjectionMode,
    ) bool {
        var snapshot = migration_relay.Snapshot.decode(self.allocator, entry.snapshot) catch |err| {
            if (err == error.OutOfMemory) return false;
            return self.reconcileSessionReplicaRouteProjection(token, null, &.{}, mode);
        };
        defer snapshot.deinit(self.allocator);
        const desired = if (std.ascii.eqlIgnoreCase(snapshot.account, entry.account) and
            std.ascii.eqlIgnoreCase(snapshot.nick, entry.nick))
            snapshot.channels
        else
            &.{};
        const desired_nick: ?[]const u8 = if (desired.len != 0 or
            (std.ascii.eqlIgnoreCase(snapshot.account, entry.account) and
                std.ascii.eqlIgnoreCase(snapshot.nick, entry.nick)))
            entry.nick
        else
            null;
        return self.reconcileSessionReplicaRouteProjection(token, desired_nick, desired, mode);
    }

    fn reconcileSessionReplicaRouteProjection(
        self: *LinuxServer,
        token: session_migrate.Token,
        desired_nick: ?[]const u8,
        desired_channels: []const []const u8,
        mode: SessionReplicaProjectionMode,
    ) bool {
        var complete = true;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established() or !link.supportsSessionReplicaV2()) continue;
                _ = link.reconcileSessionToken(token, desired_nick, desired_channels) catch {
                    complete = false;
                    if (mode == .live)
                        self.drainIdentityTransitions(&slot.value, link)
                    else
                        self.discardIdentityTransitions(link);
                    continue;
                };
                // OFFER-only rename/revoke still has a client-visible event even
                // when no compatibility NICK/PART sidecar follows this feed.
                if (mode == .live)
                    self.drainIdentityTransitions(&slot.value, link)
                else
                    self.discardIdentityTransitions(link);
            }
        }
        return complete;
    }

    fn sessionSnapshotChannelMode(snapshot: *const migration_relay.Snapshot, channel: []const u8) ?u8 {
        for (snapshot.channels, 0..) |candidate, i| {
            if (!std.ascii.eqlIgnoreCase(candidate, channel)) continue;
            return if (i < snapshot.channel_modes.len) snapshot.channel_modes[i] else 0;
        }
        return null;
    }

    fn renderReplicaJoin(
        self: *LinuxServer,
        snapshot: *const migration_relay.Snapshot,
        channel: []const u8,
        only: ?client_model.ClientId,
    ) void {
        const user = if (snapshot.username.len != 0) snapshot.username else world_projection.remote_user_placeholder;
        const host = if (snapshot.host.len != 0) snapshot.host else default_host;
        var line_buf: [900]u8 = undefined;
        const line = std.fmt.bufPrint(
            &line_buf,
            ":{s}!{s}@{s} JOIN :{s}\r\n",
            .{ snapshot.nick, user, host, channel },
        ) catch return;
        if (only) |id| {
            var tag_buf: [48]u8 = undefined;
            self.deliverTimed(id, serverTimeTag(&tag_buf), line) catch {};
        } else {
            self.broadcastChannel(channel, line, null) catch {};
        }
    }

    fn renderReplicaPart(
        self: *LinuxServer,
        snapshot: *const migration_relay.Snapshot,
        channel: []const u8,
    ) void {
        const user = if (snapshot.username.len != 0) snapshot.username else world_projection.remote_user_placeholder;
        const host = if (snapshot.host.len != 0) snapshot.host else default_host;
        var line_buf: [900]u8 = undefined;
        const line = std.fmt.bufPrint(
            &line_buf,
            ":{s}!{s}@{s} PART {s}\r\n",
            .{ snapshot.nick, user, host, channel },
        ) catch return;
        self.broadcastChannel(channel, line, null) catch {};
    }

    /// Only client-owned modes are portable profile state. `+M` is the sole
    /// server-managed exception: a remote authority may carry the restrictive
    /// media deny forward, but absence never clears a locally imposed deny.
    fn portableReplicaUmode(mode: usermode.UserMode) bool {
        const spec = usermode.specFor(mode) orelse return false;
        return spec.policy == .client_writable or mode == .media_tx_deny;
    }

    /// Parse the rendered migration form without trusting it as a raw bitset.
    /// Derived/server privilege letters (`o`, `r`, `z`, `x`, `a`) are accepted
    /// for compatibility but ignored; unknown/malformed input is terminal.
    fn parsePortableReplicaUmodes(mode_str: []const u8) ?usermode.UmodeSet {
        if (mode_str.len > usermode.MAX_MODE_CHANGES + 2) return null;
        var desired = usermode.UmodeSet.empty();
        var adding: ?bool = null;
        for (mode_str) |letter| {
            switch (letter) {
                '+' => adding = true,
                '-' => adding = false,
                'o' => if (adding == null) return null,
                else => {
                    const on = adding orelse return null;
                    const mode = usermode.modeFromLetter(letter) orelse return null;
                    if (!portableReplicaUmode(mode)) continue;
                    if (on) desired.add(mode) else desired.remove(mode);
                },
            }
        }
        return desired;
    }

    fn writeReplicaUmodeDelta(
        out: []u8,
        added: usermode.UmodeSet,
        removed: usermode.UmodeSet,
    ) ?[]const u8 {
        var n: usize = 0;
        if (!added.isEmpty()) {
            if (n >= out.len) return null;
            out[n] = '+';
            n += 1;
            for (usermode.default_specs) |spec| {
                if (!portableReplicaUmode(spec.mode) or !added.contains(spec.mode)) continue;
                if (n >= out.len) return null;
                out[n] = spec.letter;
                n += 1;
            }
        }
        if (!removed.isEmpty()) {
            if (n >= out.len) return null;
            out[n] = '-';
            n += 1;
            for (usermode.default_specs) |spec| {
                if (!portableReplicaUmode(spec.mode) or !removed.contains(spec.mode)) continue;
                if (n >= out.len) return null;
                out[n] = spec.letter;
                n += 1;
            }
        }
        return out[0..n];
    }

    /// Deliver a remote logical-session profile transition once to observers
    /// and once to every exact attachment that negotiated the relevant cap.
    /// Different tokens sharing account/nick are never selected.
    fn notifyReplicaProfileEvent(
        self: *LinuxServer,
        source_id: client_model.ClientId,
        logical_ids: []const client_model.ClientId,
        msg: []const u8,
        cap: dispatch.CapId,
        monitor_nick: []const u8,
    ) void {
        self.notifyCommonChannels(source_id, msg, cap, source_id, monitor_nick) catch {};
        const source_wid = worldIdFromClient(source_id);
        for (logical_ids) |logical_id| {
            const logical_conn = self.connFor(logical_id) orelse continue;
            if (!logical_conn.session.hasCap(cap)) continue;
            if (!logical_id.eql(source_id) and
                self.sharesAnyChannelWith(source_wid, worldIdFromClient(logical_id))) continue;
            self.deliver(logical_id, msg) catch {};
        }
    }

    /// Diff one accepted best signed snapshot into attached LOCAL rows bearing
    /// exactly `token`. Account+nick alone never selects an attachment. JOIN is
    /// restored to every exact row before one logical broadcast; PART broadcasts
    /// while the rows are still members, then removes them. Duplicate projection
    /// is therefore idempotent and produces no second event.
    fn projectSessionReplicaChannels(
        self: *LinuxServer,
        token: session_migrate.Token,
        entry: *const session_replica_v2.Store.Entry,
        mode: SessionReplicaProjectionMode,
    ) bool {
        var snapshot = migration_relay.Snapshot.decode(self.allocator, entry.snapshot) catch |err| {
            if (err != error.OutOfMemory) {
                // A cryptographically valid authority can still carry a
                // permanently malformed snapshot. It is terminal for live
                // projection, not a reason to pin a retry slot forever.
                return true;
            }
            return false;
        };
        defer snapshot.deinit(self.allocator);
        if (!std.mem.eql(u8, snapshot.account, entry.account) or
            !std.mem.eql(u8, snapshot.nick, entry.nick))
        {
            return true;
        }
        // Decode success alone does not make reflected text safe. Validate the
        // complete profile before mutating any attachment so malformed signed
        // state is terminal and can never leave a half-updated token group.
        if (snapshot.realname.len > 256 or dispatch.hasControlByte(snapshot.realname) or
            snapshot.away.len > self.config.awaylen or dispatch.hasControlByte(snapshot.away))
        {
            return true;
        }
        const desired_umodes = parsePortableReplicaUmodes(snapshot.umodes) orelse return true;

        const rows = self.sessions.copySessionsAlloc(self.allocator, entry.account) catch return false;
        defer self.allocator.free(rows);
        var logical_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer logical_ids.deinit(self.allocator);
        for (rows) |row| {
            if (!row.attached or !std.crypto.timing_safe.eql(sessions_mod.Token, row.token, token)) continue;
            const id = clientIdFromMonitor(row.client);
            const conn = self.connFor(id) orelse continue;
            if (conn.closing or conn.s2s != null or conn.s2s_secured != null) continue;
            const account = conn.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(account, entry.account)) continue;
            logical_ids.append(self.allocator, id) catch return false;
        }
        if (logical_ids.items.len == 0) return true;

        var logical_world_ids: std.ArrayList(world_model.ClientId) = .empty;
        defer logical_world_ids.deinit(self.allocator);
        self.exactWorldIds(logical_ids.items, &logical_world_ids) catch return false;
        const registry_id = self.existingExactWorldOwner(logical_ids.items);
        const registry_wid = worldIdFromClient(registry_id);

        var event_id: ?client_model.ClientId = null;
        for (logical_ids.items) |logical_id| {
            const logical_conn = self.connFor(logical_id) orelse continue;
            if (!std.mem.eql(u8, logical_conn.session.displayName(), entry.nick)) {
                event_id = logical_id;
                break;
            }
        }
        var old_buf: [session_replica_v2.max_nick_len]u8 = undefined;
        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        var old_nick: []const u8 = "";
        var old_prefix: []const u8 = "";
        var nick_msg: []const u8 = "";
        var old_remains_online = false;
        const new_was_announced_online = self.monitor.isOnline(entry.nick);
        if (event_id) |source_id| {
            const source = self.connFor(source_id) orelse return false;
            const old = source.session.displayName();
            if (old.len > old_buf.len) return true;
            @memcpy(old_buf[0..old.len], old);
            old_nick = old_buf[0..old.len];
            if (mode == .live) {
                old_prefix = clientPrefix(source, &prefix_buf) catch return true;
                nick_msg = formatMessage(&msg_buf, old_prefix, "NICK", &.{}, entry.nick) catch return true;
            }
            for (rows) |row| {
                if (!row.attached or std.crypto.timing_safe.eql(sessions_mod.Token, row.token, token)) continue;
                const sibling = self.connFor(clientIdFromMonitor(row.client)) orelse continue;
                if (sibling.closing or !sibling.session.registered()) continue;
                if (std.ascii.eqlIgnoreCase(sibling.session.displayName(), old_nick)) {
                    old_remains_online = true;
                    break;
                }
            }
        }
        var nick_recipients: std.ArrayList(client_model.ClientId) = .empty;
        defer nick_recipients.deinit(self.allocator);
        if (event_id != null and mode == .live)
            self.collectExactLogicalNickRecipients(logical_ids.items, &nick_recipients) catch return false;

        const case_only_nick = event_id != null and std.ascii.eqlIgnoreCase(old_nick, entry.nick);
        var monitor_plan: ?PreparedMonitorTransition = null;
        defer if (monitor_plan) |*plan| plan.deinit(self.allocator);
        // MONITOR's derived online map participates in the same live rename.
        // Prepare both dynamic watcher output and map capacity before World or
        // profile mutation; apply after commit performs no allocation.
        if (event_id != null and mode == .live) {
            if (case_only_nick) {
                self.monitor.reserveOnlineTransition(
                    old_nick,
                    entry.nick,
                    true,
                    new_was_announced_online,
                ) catch return false;
            } else {
                monitor_plan = self.prepareMonitorOccupancyTransition(
                    old_nick,
                    entry.nick,
                    new_was_announced_online,
                ) catch return false;
            }
        }

        _ = self.world.replaceExactSessionNickOwner(entry.nick, registry_wid, logical_world_ids.items) catch |err| switch (err) {
            error.NickInUse => {
                const foreign_owner = self.world.findNick(entry.nick) orelse return false;
                if (!self.nickHeldBySameAccount(entry.nick, entry.account, registry_wid)) return false;
                _ = self.world.relinquishExactSessionNickOwners(
                    entry.nick,
                    foreign_owner,
                    logical_world_ids.items,
                ) catch return false;
            },
            else => return false,
        };
        for (logical_ids.items) |logical_id| {
            const logical_conn = self.connFor(logical_id) orelse continue;
            logical_conn.session.setNick(entry.nick) catch unreachable;
        }
        if (event_id != null and !case_only_nick)
            old_remains_online = old_remains_online or self.world.findNick(old_nick) != null;
        if (event_id != null and mode == .live) {
            self.deliverLogicalNickEvent(nick_recipients.items, nick_msg);
            var nick_body_buf: [session_replica_v2.max_nick_len + 1]u8 = undefined;
            const nick_body = std.fmt.bufPrint(&nick_body_buf, ":{s}", .{entry.nick}) catch entry.nick;
            var logical_channels = self.world.channels.iterator();
            while (logical_channels.next()) |channel_entry| {
                var belongs = false;
                for (logical_ids.items) |logical_id| {
                    if (channel_entry.value_ptr.members.contains(worldIdFromClient(logical_id))) {
                        belongs = true;
                        break;
                    }
                }
                if (belongs) self.recordHistoryEventSender(channel_entry.key_ptr.*, old_prefix, "NICK", nick_body);
            }
            if (case_only_nick)
                self.monitor.transitionOnlineSilent(old_nick, entry.nick, true) catch {}
            else
                self.applyPreparedMonitorOccupancyTransition(
                    &monitor_plan.?,
                    old_nick,
                    entry.nick,
                    old_remains_online,
                    new_was_announced_online,
                ) catch {};
        } else if (mode == .helix_silent) {
            if (event_id != null) {
                const display = if (self.world.findNick(entry.nick)) |owner|
                    self.world.nickOf(owner) orelse entry.nick
                else
                    entry.nick;
                self.monitor.transitionOnlineSilent(old_nick, display, old_remains_online) catch return false;
            } else self.monitor.restoreOnline(entry.nick) catch return false;
        }

        // Snapshot all channels that must be removed before mutating World: a
        // PART may destroy the last-local-member channel and invalidate a live
        // channel-map iterator. Owned names make the subsequent diff safe.
        var removals: std.ArrayListUnmanaged([]u8) = .empty;
        defer {
            for (removals.items) |channel| self.allocator.free(channel);
            removals.deinit(self.allocator);
        }
        for (logical_ids.items) |id| {
            const cap = self.world.channelCountOf(worldIdFromClient(id));
            const names = self.allocator.alloc([]const u8, cap) catch return false;
            defer self.allocator.free(names);
            const n = self.world.channelsOf(worldIdFromClient(id), names);
            for (names[0..n]) |channel| {
                if (sessionSnapshotChannelMode(&snapshot, channel) != null) continue;
                var duplicate = false;
                for (removals.items) |existing| {
                    if (std.ascii.eqlIgnoreCase(existing, channel)) {
                        duplicate = true;
                        break;
                    }
                }
                if (duplicate) continue;
                const owned = self.allocator.dupe(u8, channel) catch return false;
                removals.append(self.allocator, owned) catch {
                    self.allocator.free(owned);
                    return false;
                };
            }
        }

        var complete = true;
        for (snapshot.channels, 0..) |channel, i| {
            const modes = world_model.MemberModes{
                .bits = if (i < snapshot.channel_modes.len) snapshot.channel_modes[i] else 0,
            };
            var logical_was_present = false;
            for (logical_ids.items) |id| {
                if (self.world.isMember(channel, worldIdFromClient(id))) {
                    logical_was_present = true;
                    break;
                }
            }

            var restored_any = false;
            for (logical_ids.items) |id| {
                const wid = worldIdFromClient(id);
                const was_member = self.world.isMember(channel, wid);
                self.world.restoreMember(channel, wid, modes) catch |err| {
                    if (err == error.OutOfMemory) complete = false;
                    continue;
                };
                restored_any = true;
                if (mode == .live and logical_was_present and !was_member)
                    self.renderReplicaJoin(&snapshot, channel, id);
            }
            if (mode == .live and !logical_was_present and restored_any)
                self.renderReplicaJoin(&snapshot, channel, null);
        }

        for (removals.items) |channel| {
            var logical_was_present = false;
            for (logical_ids.items) |id| {
                if (self.world.isMember(channel, worldIdFromClient(id))) {
                    logical_was_present = true;
                    break;
                }
            }
            if (!logical_was_present) continue;
            if (mode == .live) self.renderReplicaPart(&snapshot, channel);
            for (logical_ids.items) |id| {
                self.world.part(channel, worldIdFromClient(id)) catch |err| {
                    if (err == error.OutOfMemory) complete = false;
                };
            }
        }

        // Do not expose profile state ahead of a retryable channel projection.
        // Once the World diff is complete, applying profile fields is entirely
        // allocation-free and therefore atomic across this exact token group.
        if (!complete) return false;
        const profile_source_id = logical_ids.items[0];
        const profile_source = self.connFor(profile_source_id) orelse return false;
        var away_changed = false;
        var realname_changed = false;
        var modes_added = usermode.UmodeSet.empty();
        var modes_removed = usermode.UmodeSet.empty();
        for (logical_ids.items) |logical_id| {
            const logical_conn = self.connFor(logical_id) orelse continue;
            const old_away = logical_conn.session.awayMessage() orelse "";
            away_changed = away_changed or !std.mem.eql(u8, old_away, snapshot.away);
            realname_changed = realname_changed or !std.mem.eql(u8, logical_conn.session.realname(), snapshot.realname);
            for (usermode.default_specs) |spec| {
                if (!portableReplicaUmode(spec.mode)) continue;
                var want = desired_umodes.contains(spec.mode);
                if (spec.mode == .override and !logical_conn.session.hasPriv(.oper_override)) want = false;
                // A missing remote +M cannot clear a stricter local policy.
                if (spec.mode == .media_tx_deny and !want) continue;
                const had = logical_conn.session.hasUmode(spec.mode);
                if (had == want) continue;
                _ = logical_conn.session.setUmode(spec.mode, want);
                if (want) modes_added.add(spec.mode) else modes_removed.add(spec.mode);
            }
            if (snapshot.away.len == 0) logical_conn.session.clearAway() else logical_conn.session.setAway(snapshot.away);
            logical_conn.session.setRealname(snapshot.realname) catch unreachable;
        }

        if (mode == .live) {
            var profile_prefix_buf: [256]u8 = undefined;
            const profile_prefix = clientPrefix(profile_source, &profile_prefix_buf) catch "";
            if (away_changed and profile_prefix.len != 0) {
                var away_buf: [default_reply_bytes]u8 = undefined;
                const away_msg = formatMessage(
                    &away_buf,
                    profile_prefix,
                    "AWAY",
                    &.{},
                    if (snapshot.away.len == 0) null else snapshot.away,
                ) catch "";
                if (away_msg.len != 0) self.notifyReplicaProfileEvent(
                    profile_source_id,
                    logical_ids.items,
                    away_msg,
                    .away_notify,
                    snapshot.nick,
                );
                self.pushPresenceActivity(
                    profile_source_id,
                    profile_source,
                    if (snapshot.away.len == 0) .active else .away,
                );
            }
            if (realname_changed and profile_prefix.len != 0) {
                var setname_buf: [default_reply_bytes]u8 = undefined;
                const setname_msg = formatMessage(
                    &setname_buf,
                    profile_prefix,
                    "SETNAME",
                    &.{},
                    snapshot.realname,
                ) catch "";
                if (setname_msg.len != 0) self.notifyReplicaProfileEvent(
                    profile_source_id,
                    logical_ids.items,
                    setname_msg,
                    .setname,
                    snapshot.nick,
                );
            }
            if ((!modes_added.isEmpty() or !modes_removed.isEmpty()) and profile_prefix.len != 0) {
                var delta_buf: [usermode.MAX_MODE_CHANGES + 2]u8 = undefined;
                if (writeReplicaUmodeDelta(&delta_buf, modes_added, modes_removed)) |delta| {
                    var mode_buf: [default_reply_bytes]u8 = undefined;
                    const mode_msg = formatMessage(&mode_buf, profile_prefix, "MODE", &.{ snapshot.nick, delta }, null) catch "";
                    if (mode_msg.len != 0) {
                        for (logical_ids.items) |logical_id| self.deliver(logical_id, mode_msg) catch {};
                    }
                }
            }
        }

        // Make the receive-side no-republish rule explicit at the same boundary
        // local JOIN/PART uses. This is intentionally a no-op.
        self.convergeSessionReplicaToken(token, .remote_projection);
        return true;
    }

    /// Project only the Store's deterministic best signed identity. The pending
    /// store owns a distinct v2 revision domain, so legacy epochs cannot
    /// downgrade it and arrival permutations across origins converge identically.
    fn projectBestSessionReplicaV2(self: *LinuxServer, token: session_migrate.Token) bool {
        return self.projectBestSessionReplicaV2Mode(token, .live);
    }

    fn validateSessionReplicaProjectionEntry(
        self: *LinuxServer,
        entry: *const session_replica_v2.Store.Entry,
    ) bool {
        var snapshot = migration_relay.Snapshot.decode(self.allocator, entry.snapshot) catch return false;
        defer snapshot.deinit(self.allocator);
        return std.mem.eql(u8, snapshot.account, entry.account) and
            std.mem.eql(u8, snapshot.nick, entry.nick) and
            snapshot.realname.len <= 256 and
            !dispatch.hasControlByte(snapshot.realname) and
            snapshot.away.len <= self.config.awaylen and
            !dispatch.hasControlByte(snapshot.away) and
            parsePortableReplicaUmodes(snapshot.umodes) != null;
    }

    fn projectBestSessionReplicaV2Mode(
        self: *LinuxServer,
        token: session_migrate.Token,
        mode: SessionReplicaProjectionMode,
    ) bool {
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        if (self.session_replica_store.bestLiveIdentity(token, now_wall)) |surviving| {
            if (mode == .helix_silent and !self.validateSessionReplicaProjectionEntry(surviving))
                return false;
            const marked = self.sessions.markTokenReplicaProjectionDirty(token);
            const staged = self.stageSessionReplicaV2Entry(token, surviving);
            if (!staged) self.scheduleSessionReplicaStageRetry();
            const projected = self.projectSessionReplicaChannels(token, surviving, mode);
            const authorities_bound = self.bindSessionReplicaRouteAuthorities(token, now_wall);
            const routes_reconciled = self.reconcileSessionReplicaRoutes(token, surviving, mode);
            if (!authorities_bound or !routes_reconciled) self.scheduleSessionReplicaStageRetry();
            const complete = staged and projected and authorities_bound and routes_reconciled;
            if (marked and complete)
                _ = self.sessions.clearTokenReplicaProjectionDirty(token);
            return complete;
        } else {
            if (self.pending_migrations) |*pm| _ = pm.removeReplica(token);
            const marked = self.sessions.markTokenReplicaProjectionDirty(token);
            const routes_reconciled = self.reconcileSessionReplicaRouteProjection(token, null, &.{}, mode);
            if (!routes_reconciled) self.scheduleSessionReplicaStageRetry();
            if (marked and routes_reconciled) _ = self.sessions.clearTokenReplicaProjectionDirty(token);
            return routes_reconciled;
        }
    }

    /// After expiry sweeping removes a formerly-best origin, reproject each token
    /// that still has at least one live signed OFFER so Pending falls back to the
    /// Store-selected surviving origin even when its revision is lower.
    fn reprojectLiveSessionReplicasV2(self: *LinuxServer, mode: SessionReplicaProjectionMode) bool {
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        var cursor: ?session_migrate.Token = null;
        while (true) {
            var tokens: [32]session_migrate.Token = undefined;
            const page = self.session_replica_store.liveTokensAfter(now_wall, cursor, &tokens);
            if (page.len == 0) return true;
            for (page) |token|
                if (!self.projectBestSessionReplicaV2Mode(token, mode)) return false;
            cursor = page[page.len - 1];
            if (page.len < tokens.len) return true;
        }
    }

    /// Drain signed SESSION_REPLICA v2 objects from one secured link. OFFER and
    /// REVOKE authority is retained by the Store and forwarded unchanged only
    /// when it advances local state. ACKs are verified direct receipts and stop
    /// here. Invalid objects are isolated to this frame and never kill the link.
    fn drainSessionReplicaV2(
        self: *LinuxServer,
        conn: *ConnState,
        link: *secured_s2s_link.SecuredLink,
    ) bool {
        if (!conn.ownsActiveMeshLink(link)) return false;
        const dropped = link.takeDroppedSessionReplicaFrames();
        var residence_batch_complete = dropped == 0;
        var replica_resync_needed = dropped != 0;
        if (dropped != 0) {
            var detail_buf: [160]u8 = undefined;
            const detail = std.fmt.bufPrint(
                &detail_buf,
                "dropped {d} inbound SESSION_REPLICA frames; requesting bounded anti-entropy replay",
                .{dropped},
            ) catch "dropped inbound SESSION_REPLICA frames; requesting anti-entropy replay";
            self.traceLog(.warn, .s2s, detail);
            // Queue pressure dropped authenticated objects before application.
            // The common incomplete-batch path below requests bounded replay.
        }
        const authenticated_peer = link.peerShortId() orelse {
            while (link.takeNextSessionReplicaFrame()) |owned| {
                var frame = owned;
                frame.deinit(self.allocator);
            }
            return false;
        };
        const now_wall: i64 = @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64))));
        while (link.takeNextSessionReplicaFrame()) |owned| {
            var frame = owned;
            defer frame.deinit(self.allocator);
            if (frame.via_peer == 0 or frame.via_peer != authenticated_peer) {
                residence_batch_complete = false;
                replica_resync_needed = true;
                continue;
            }
            switch (frame.kind) {
                .ack => {
                    const signed = session_replica_v2.decodeAck(frame.signed_payload) catch continue;
                    _ = self.session_replica_store.applySignedAck(signed, authenticated_peer, now_wall) catch continue;
                },
                .attachment_lease => {
                    const signed = session_replica_v2.decodeAttachmentLease(frame.signed_payload) catch {
                        replica_resync_needed = true;
                        continue;
                    };
                    const before = self.session_replica_store.getAttachmentLease(
                        signed.lease.token,
                        signed.lease.revision.origin_node,
                    );
                    const was_conflicted = if (before) |entry| entry.conflicted else false;
                    const had_conflict_witness = if (before) |entry| entry.conflict_wire != null else false;
                    const disposition = self.session_replica_store.applySignedAttachmentLease(signed, now_wall) catch |err| {
                        const after = self.session_replica_store.getAttachmentLease(
                            signed.lease.token,
                            signed.lease.revision.origin_node,
                        );
                        if (!was_conflicted and after != null and after.?.conflicted)
                            self.session_replica_store_generation +%= 1;
                        switch (err) {
                            error.OutOfMemory, error.AttachmentLeaseFull => replica_resync_needed = true,
                            else => {},
                        }
                        continue;
                    };
                    switch (disposition) {
                        .inserted, .superseded => {
                            self.observeSessionReplicaRevision(signed.lease.revision);
                            self.session_replica_store_generation +%= 1;
                            self.broadcastSessionReplicaV2(.attachment_lease, frame.signed_payload, authenticated_peer);
                        },
                        .conflict => {
                            const current = self.session_replica_store.getAttachmentLease(
                                signed.lease.token,
                                signed.lease.revision.origin_node,
                            ) orelse continue;
                            const captured_witness = current.conflict_wire != null;
                            if (!was_conflicted or (!had_conflict_witness and captured_witness))
                                self.session_replica_store_generation +%= 1;
                            // The ingress peer is only known to possess the wire
                            // it sent. Replay the retained pair back over this
                            // same authenticated link; skipping it during flood
                            // fanout could leave one side falsely live forever.
                            if (captured_witness and !conn.session_replica_replay_pending)
                                self.scheduleSessionReplicaReplay(conn);
                            // Forward both authenticated witnesses together. A
                            // peer that missed the historical first transcript
                            // must still learn portable fail-closed evidence.
                            if (captured_witness and (!had_conflict_witness or !was_conflicted)) {
                                self.broadcastSessionReplicaV2(.attachment_lease, current.wire, authenticated_peer);
                                self.broadcastSessionReplicaV2(.attachment_lease, current.conflict_wire.?, authenticated_peer);
                            }
                        },
                        .duplicate => {
                            const current = self.session_replica_store.getAttachmentLease(
                                signed.lease.token,
                                signed.lease.revision.origin_node,
                            );
                            if (current != null and current.?.conflicted and current.?.conflict_wire != null and
                                !conn.session_replica_replay_pending)
                                self.scheduleSessionReplicaReplay(conn);
                        },
                        .stale => {},
                    }
                },
                .offer, .revoke => {
                    const signed = session_replica_v2.decodeOffer(frame.signed_payload) catch {
                        residence_batch_complete = false;
                        replica_resync_needed = true;
                        continue;
                    };
                    const expected_operation: session_replica_v2.OfferOperation = if (frame.kind == .offer) .upsert else .remove;
                    if (signed.offer.operation != expected_operation) {
                        residence_batch_complete = false;
                        replica_resync_needed = true;
                        continue;
                    }
                    const was_quarantined = self.session_replica_store.isQuarantined(signed.offer.token);
                    // Applying a newer revision may free/replace the old Store
                    // entry, so retain its bounded nick by value for receiver-
                    // owned RouteTable token metadata cleanup afterward.
                    var previous_nick_buf: [session_replica_v2.max_nick_len]u8 = undefined;
                    var previous_nick_len: usize = 0;
                    if (self.session_replica_store.getOrigin(
                        signed.offer.token,
                        signed.offer.revision.origin_node,
                    )) |previous| {
                        previous_nick_len = previous.nick.len;
                        @memcpy(previous_nick_buf[0..previous_nick_len], previous.nick);
                    }
                    const result = self.session_replica_store.applySignedOffer(signed, authenticated_peer, now_wall) catch |err| {
                        residence_batch_complete = false;
                        replica_resync_needed = true;
                        switch (err) {
                            error.EntryFull, error.RouteFull, error.TombstoneFull, error.QuarantineFull => self.sendSessionReplicaAckV2(
                                conn,
                                link,
                                .capacity,
                                signed.offer.revision,
                                signed.offer.revision,
                                signed.offer.token,
                                now_wall,
                            ),
                            else => {},
                        }
                        continue;
                    };
                    switch (result.disposition) {
                        .inserted, .conflict_replaced, .superseded, .duplicate, .tombstoned => self.observeSessionReplicaRevision(result.current_revision),
                        .conflict, .quarantined, .stale => {},
                    }
                    self.sendSessionReplicaAckV2(
                        conn,
                        link,
                        result.disposition.ackStatus(),
                        signed.offer.revision,
                        result.current_revision,
                        signed.offer.token,
                        now_wall,
                    );
                    const advances = switch (result.disposition) {
                        .inserted, .conflict_replaced, .superseded, .tombstoned => true,
                        .duplicate, .conflict, .quarantined, .stale => false,
                    };
                    if (!advances and result.disposition != .duplicate and result.disposition != .quarantined) {
                        residence_batch_complete = false;
                        replica_resync_needed = true;
                    }
                    const quarantine_changed = result.disposition == .quarantined and !was_quarantined;
                    if (advances or quarantine_changed)
                        self.session_replica_store_generation +%= 1;
                    // Reconcile exact-token rows while their receiver-owned tag
                    // is still present. Clearing/rebinding the old nick first
                    // would make revoke, quarantine, and nick-change cleanup
                    // unable to find the stale compatibility route.
                    const projection_complete = if (advances or result.disposition == .duplicate or quarantine_changed)
                        self.projectBestSessionReplicaV2(signed.offer.token)
                    else
                        false;
                    if ((advances or quarantine_changed) and projection_complete) {
                        if (previous_nick_len != 0) _ = self.rebindSessionReplicaRoutes(
                            signed.offer.revision.origin_node,
                            previous_nick_buf[0..previous_nick_len],
                        );
                    }
                    if (advances or quarantine_changed)
                        self.broadcastSessionReplicaV2(frame.kind, frame.signed_payload, authenticated_peer);
                },
            }
        }
        // Any incomplete authority batch invalidates the residence sidecars
        // correlated with this feed. Ask the peer to replay its retained
        // canonical Store before a later membership re-burst.
        if (replica_resync_needed) link.sendResync() catch {
            conn.closing = true;
            return false;
        };
        const out = link.outbound();
        if (out.len != 0) {
            if (!self.flushMeshBurstStage(conn) and conn.closing) return false;
        }
        return residence_batch_complete;
    }

    fn applySessionConsumedNotice(self: *LinuxServer, notice: session_reclaim_mesh.ConsumeNotice) void {
        // Compatibility-only wire input from one-shot migration releases. A
        // modern logical session is reusable and may have other live clients, so
        // deleting its replica/ghost here would strand those attachments. Fresh
        // signed offers supersede legacy tombstones in PendingMigrations.
        _ = self;
        _ = notice;
    }

    /// Drain a secured link's inbound session-migration capsules: verify each via
    /// `MigrationTarget.accept` (pinned to the peer's node key), then stage the
    /// decoded session into the bounded, epoch-ordered `pending_migrations` store
    /// keyed by its 16-byte session token. A capsule that fails verification or
    /// whose outer/inner accounts disagree is dropped, never fatal to the link.
    fn drainSessionMigrations(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const caps = link.takeSessionMigrations() catch return;
        defer self.allocator.free(caps);
        const expected_signer = link.peerNodeKey() orelse {
            for (caps) |c| self.allocator.free(c);
            return;
        };
        const pm = if (self.pending_migrations) |*p| p else {
            for (caps) |c| self.allocator.free(c);
            return;
        };
        for (caps) |c| {
            defer self.allocator.free(c);
            self.stageSessionMigration(pm, expected_signer, c);
        }
    }

    /// Verify + stage one inbound `session_migrate` capsule wire blob. Splits the
    /// 16-byte session-token key from the embedded relay frame, runs the relay's
    /// `MigrationTarget.accept` signature/account/hash checks for the authenticated
    /// peer, then copies the decoded snapshot into the bounded token-keyed store.
    /// That store enforces signed-epoch order and consumed tombstones without a
    /// global nonce journal that could collide across peers or grow forever.
    fn stageSessionMigration(
        self: *LinuxServer,
        pm: *session_migrate.PendingMigrations,
        expected_signer: migration_relay.PublicKey,
        wire: []const u8,
    ) void {
        const outer = session_migrate.decode(wire) catch return;

        var target = migration_relay.MigrationTarget.init(self.allocator, expected_signer);
        defer target.deinit();

        var capsule = target.accept(outer.snapshot) catch return;
        defer capsule.deinit(self.allocator);

        // The relay capsule's account must match the outer session_migrate
        // account — a spliced token/snapshot pairing is dropped.
        if (!std.mem.eql(u8, capsule.account, outer.account)) return;

        // Re-encode the verified snapshot so the staged blob is a self-contained
        // migration_relay.Snapshot the attachment side decodes directly.
        const snap_bytes = capsule.snapshot.encode(self.allocator) catch return;
        defer self.allocator.free(snap_bytes);

        pm.putAtEpoch(.{
            .token = outer.token,
            .account = outer.account,
            .snapshot = snap_bytes,
        }, self.nowMs(), capsule.token.epoch) catch return;
    }

    /// Borrow the staged replica for `session_token` and restore the full session
    /// into the live `conn`, REUSING the Helix-upgrade restore
    /// helpers (`session.restore` + `world.registerNick` + `world.restoreMember`)
    /// so join/mode logic is never duplicated. Returns true on a successful
    /// restore; false if no replica was staged or it failed to decode. The entry
    /// stays staged so concurrent clients may attach until its TTL expires.
    /// Caller has ALREADY passed the mesh token HMAC/expiry/account gates.
    fn restoreStagedMigration(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        session_token: session_migrate.Token,
        bind_kind: sessions_mod.TokenBindKind,
        attachment_transfer: ?RestoreAttachmentTransfer,
    ) bool {
        const pm = if (self.pending_migrations) |*p| p else return false;
        const entry = pm.getLive(
            session_token,
            @intCast(@min(self.meshWallMs(), @as(u64, std.math.maxInt(i64)))),
        ) orelse return false;
        if (!std.ascii.eqlIgnoreCase(entry.account, account)) return false;

        var snap = migration_relay.Snapshot.decode(self.allocator, entry.snapshot) catch return false;
        defer snap.deinit(self.allocator);

        if (attachment_transfer == null)
            return self.restoreAndBindMigrationSnapshot(id, conn, account, session_token, bind_kind, &snap);
        if (!self.migrationRestorePreflight(id, conn, account, &snap)) return false;

        const cid = monitorIdFromClient(id);
        var token_ticket = self.sessions.prepareTokenBind(account, cid, session_token, bind_kind) orelse return false;
        defer token_ticket.deinit();
        return self.restoreAndBindMigrationSnapshotWithTicket(
            id,
            conn,
            account,
            session_token,
            &snap,
            &token_ticket,
            attachment_transfer,
        );
    }

    fn restoreEncodedMigrationSnapshot(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        session_token: sessions_mod.Token,
        bytes: []const u8,
        bind_kind: sessions_mod.TokenBindKind,
    ) bool {
        var snap = migration_relay.Snapshot.decode(self.allocator, bytes) catch return false;
        defer snap.deinit(self.allocator);
        return self.restoreAndBindMigrationSnapshot(id, conn, account, session_token, bind_kind, &snap);
    }

    const ExactAttachmentResumeOutcome = enum {
        already_attached,
        restored,
        reclaimed,
        missing,
        busy,
        retryable,
    };

    /// Replace only the detached physical attachment selected by the composite
    /// credential. The retained exact ticket freezes token/id ownership while
    /// the common World/output restore planner and durable delivery remap are
    /// prepared; no sibling selection or token-only fallback is permitted.
    fn restoreExactAttachment(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        session_token: sessions_mod.Token,
        attachment_id: sessions_mod.AttachmentId,
    ) ExactAttachmentResumeOutcome {
        const cid = monitorIdFromClient(id);
        if (self.sessions.clientHasAttachment(account, cid, session_token, attachment_id))
            return .already_attached;
        const target = self.sessions.findAttachmentSessionInAccount(
            account,
            session_token,
            attachment_id,
        ) orelse return .missing;
        if (target.attached) return .busy;

        var ticket = self.sessions.prepareExactAttachmentRebind(
            account,
            cid,
            session_token,
            attachment_id,
        ) orelse return .retryable;
        defer ticket.deinit();
        const remap = ticket.remap();
        var delivery_ticket = self.prepareResumeAttachmentTransfer(
            remap.old_client,
            remap.new_client,
        ) catch return .retryable;
        defer delivery_ticket.deinit();
        if (ticket.snapshot()) |bytes| {
            var snap = migration_relay.Snapshot.decode(self.allocator, bytes) catch return .retryable;
            defer snap.deinit(self.allocator);
            if (!self.migrationRestorePreflight(id, conn, account, &snap)) return .retryable;
            if (!self.restoreAndBindMigrationSnapshotWithTicket(
                id,
                conn,
                account,
                session_token,
                &snap,
                &ticket,
                .{ .prepared_exact = &delivery_ticket },
            )) return .retryable;
            return .restored;
        }

        if (!ticket.commit()) {
            ticket.abort();
            return .retryable;
        }
        delivery_ticket.commit();
        // SessionStore remains exclusively retained by `ticket`; release ADS1
        // before finish or any helper can reacquire SessionStore. This preserves
        // the global SessionStore -> attachment_delivery_mu lock order.
        delivery_ticket.release();
        ticket.finish();
        self.bindDeferredSessionMeshAnnouncements(id, conn, session_token);
        return .reclaimed;
    }

    /// Restore one detached physical attachment and move its retained delivery
    /// ownership inside the same prepared SessionStore/World transaction. A
    /// conflicting event-id rendering therefore aborts before the claimant's
    /// token, identity, membership, or output becomes visible.
    fn restoreEncodedMigrationSnapshotReplacingAttachment(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        session_token: sessions_mod.Token,
        bytes: []const u8,
        bind_kind: sessions_mod.TokenBindKind,
        old_client: sessions_mod.ClientId,
    ) bool {
        var snap = migration_relay.Snapshot.decode(self.allocator, bytes) catch return false;
        defer snap.deinit(self.allocator);
        if (!self.migrationRestorePreflight(id, conn, account, &snap)) return false;

        const new_client = monitorIdFromClient(id);
        var token_ticket = self.sessions.prepareTokenBind(
            account,
            new_client,
            session_token,
            bind_kind,
        ) orelse return false;
        defer token_ticket.deinit();
        return self.restoreAndBindMigrationSnapshotWithTicket(
            id,
            conn,
            account,
            session_token,
            &snap,
            &token_ticket,
            .{ .legacy = .{ .old_client = old_client, .new_client = new_client } },
        );
    }

    /// Join an existing reusable-token group while replacing one detached
    /// attachment's durable delivery ownership. The retained SessionStore
    /// ticket prevents registry drift between spool conflict preflight and the
    /// allocation-free token commit, including the degraded no-snapshot path.
    fn bindTokenReplacingAttachment(
        self: *LinuxServer,
        account: []const u8,
        new_client: sessions_mod.ClientId,
        session_token: sessions_mod.Token,
        bind_kind: sessions_mod.TokenBindKind,
        old_client: sessions_mod.ClientId,
    ) bool {
        var token_ticket = self.sessions.prepareTokenBind(
            account,
            new_client,
            session_token,
            bind_kind,
        ) orelse return false;
        defer token_ticket.deinit();

        self.transferAttachmentDeliveries(old_client, new_client) catch return false;
        if (!token_ticket.commit()) {
            token_ticket.abort();
            return false;
        }
        token_ticket.finish();
        return true;
    }

    fn restoreBootstrapLiveMigrationSnapshot(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        session_token: sessions_mod.Token,
        bytes: []const u8,
        kind: sessions_mod.TokenBindKind,
    ) bool {
        var snap = migration_relay.Snapshot.decode(self.allocator, bytes) catch return false;
        defer snap.deinit(self.allocator);
        if (!self.migrationRestorePreflight(id, conn, account, &snap)) return false;
        const signon: i64 = @intCast(@max(@as(i64, 0), self.nowMs()));
        var ticket = self.sessions.prepareBootstrapTokenAttach(
            account,
            monitorIdFromClient(id),
            session_token,
            kind,
            signon,
        ) orelse return false;
        defer ticket.deinit();
        return self.restoreAndBindMigrationSnapshotWithTicket(
            id,
            conn,
            account,
            session_token,
            &snap,
            &ticket,
            null,
        );
    }

    fn restoreBootstrapDetachedMigrationSnapshot(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        session_token: sessions_mod.Token,
    ) bool {
        // Flush/check deferred authority before taking SessionStore's retained
        // lock. The snapshot itself is borrowed only after preparation, so its
        // pure identity validation happens separately below.
        if (!self.migrationRestoreAuthorityReady(id, conn)) return false;
        const signon: i64 = @intCast(@max(@as(i64, 0), self.nowMs()));
        var ticket = self.sessions.prepareBootstrapTokenAttach(
            account,
            monitorIdFromClient(id),
            session_token,
            .join_existing,
            signon,
        ) orelse return false;
        defer ticket.deinit();
        const source = ticket.detachedSource() orelse return false;
        var snap = migration_relay.Snapshot.decode(self.allocator, source.snapshot) catch return false;
        defer snap.deinit(self.allocator);
        if (!migrationSnapshotMatchesIdentity(account, &snap)) return false;
        return self.restoreAndBindMigrationSnapshotWithTicket(
            id,
            conn,
            account,
            session_token,
            &snap,
            &ticket,
            .{ .legacy = .{
                .old_client = source.client,
                .new_client = monitorIdFromClient(id),
            } },
        );
    }

    const ResumePartPlan = struct {
        channel: []u8,
        line: []u8,
        recipients: []client_model.ClientId,
        logical_part: bool,
        time_tag: ResumeEventTime,

        fn deinit(self: *ResumePartPlan, allocator: std.mem.Allocator) void {
            allocator.free(self.recipients);
            allocator.free(self.line);
            allocator.free(self.channel);
            self.* = undefined;
        }
    };

    const ResumeJoinPlan = struct {
        channel: []const u8,
        plain: []u8,
        extended: []u8,
        recipients: []client_model.ClientId,
        logical_join: bool,
        time_tag: ResumeEventTime,

        fn deinit(self: *ResumeJoinPlan, allocator: std.mem.Allocator) void {
            allocator.free(self.recipients);
            allocator.free(self.extended);
            allocator.free(self.plain);
            self.* = undefined;
        }
    };

    /// Immutable server-time metadata minted once while a logical resume event
    /// is planned. Claimant bootstrap capture and post-commit peer delivery must
    /// reuse these exact bytes rather than sampling the wall clock independently.
    const ResumeEventTime = struct {
        storage: [48]u8 = undefined,
        len: u8 = 0,

        fn init() ResumeEventTime {
            var result = ResumeEventTime{};
            const rendered = serverTimeTag(&result.storage);
            result.len = @intCast(rendered.len);
            return result;
        }

        fn bytes(self: *const ResumeEventTime) []const u8 {
            return self.storage[0..self.len];
        }
    };

    const ResumeNamesProjection = struct {
        exact_world_ids: []const world_model.ClientId,
        nick: []const u8,
        user: []const u8,
        modes: world_model.MemberModes,
        is_override_oper: bool,

        fn contains(self: ResumeNamesProjection, candidate: world_model.ClientId) bool {
            return worldIdInResumeSet(self.exact_world_ids, candidate);
        }
    };

    fn appendUniqueResumeRecipient(
        self: *LinuxServer,
        recipients: *std.ArrayList(client_model.ClientId),
        id: client_model.ClientId,
    ) std.mem.Allocator.Error!void {
        for (recipients.items) |existing| if (existing.eql(id)) return;
        try recipients.append(self.allocator, id);
    }

    fn prepareResumePartPlan(
        self: *LinuxServer,
        id: client_model.ClientId,
        channel: []const u8,
        old_prefix: []const u8,
        surviving_old_identity_ids: []const world_model.ClientId,
    ) !ResumePartPlan {
        const owned_channel = try self.allocator.dupe(u8, channel);
        errdefer self.allocator.free(owned_channel);
        var line_buf: [default_reply_bytes]u8 = undefined;
        const rendered = try formatMessage(&line_buf, old_prefix, "PART", &.{channel}, null);
        const line = try self.allocator.dupe(u8, rendered);
        errdefer self.allocator.free(line);

        const claimant_wid = worldIdFromClient(id);
        var old_sibling_remains = false;
        for (surviving_old_identity_ids) |exact_wid| {
            if (exact_wid.eql(claimant_wid)) continue;
            if (self.world.isMember(channel, exact_wid)) {
                old_sibling_remains = true;
                break;
            }
        }
        var recipients: std.ArrayList(client_model.ClientId) = .empty;
        defer recipients.deinit(self.allocator);
        if (old_sibling_remains) {
            try self.appendUniqueResumeRecipient(&recipients, id);
        } else {
            const claimant_rank = auditoriumRank(
                self.world.memberModes(channel, claimant_wid) orelse world_model.MemberModes.empty(),
            );
            const restricted = self.world.channelHasExtFlag(channel, .auditorium) and
                !auditorium.shouldRelayJoinPart(claimant_rank);
            var members = self.world.memberIterator(channel) orelse return error.NoSuchChannel;
            while (members.next()) |member| {
                if (restricted and !member.*.eql(claimant_wid)) {
                    const rank = auditoriumRank(
                        self.world.memberModes(channel, member.*) orelse world_model.MemberModes.empty(),
                    );
                    if (!auditorium.shouldRelayJoinPart(rank)) continue;
                }
                try self.appendUniqueResumeRecipient(&recipients, clientIdFromWorld(member.*));
            }
        }
        return .{
            .channel = owned_channel,
            .line = line,
            .recipients = try recipients.toOwnedSlice(self.allocator),
            .logical_part = !old_sibling_remains,
            .time_tag = .init(),
        };
    }

    fn prepareResumeJoinPlan(
        self: *LinuxServer,
        id: client_model.ClientId,
        channel: []const u8,
        desired_prefix: []const u8,
        account: []const u8,
        realname: []const u8,
        desired_modes: world_model.MemberModes,
        exact_sibling_was_member: bool,
    ) !ResumeJoinPlan {
        var plain_buf: [default_reply_bytes]u8 = undefined;
        const plain = try formatMessage(&plain_buf, desired_prefix, "JOIN", &.{channel}, null);
        const owned_plain = try self.allocator.dupe(u8, plain);
        errdefer self.allocator.free(owned_plain);
        var ext_buf: [default_reply_bytes]u8 = undefined;
        const extended = try formatMessage(&ext_buf, desired_prefix, "JOIN", &.{ channel, account }, realname);
        const owned_extended = try self.allocator.dupe(u8, extended);
        errdefer self.allocator.free(owned_extended);

        var recipients: std.ArrayList(client_model.ClientId) = .empty;
        defer recipients.deinit(self.allocator);
        if (exact_sibling_was_member) {
            try self.appendUniqueResumeRecipient(&recipients, id);
        } else {
            const restricted = self.world.channelHasExtFlag(channel, .auditorium) and
                !auditorium.shouldRelayJoinPart(auditoriumRank(desired_modes));
            if (self.world.memberIterator(channel)) |members_src| {
                var members = members_src;
                while (members.next()) |member| {
                    if (restricted) {
                        const rank = auditoriumRank(
                            self.world.memberModes(channel, member.*) orelse world_model.MemberModes.empty(),
                        );
                        if (!auditorium.shouldRelayJoinPart(rank)) continue;
                    }
                    try self.appendUniqueResumeRecipient(&recipients, clientIdFromWorld(member.*));
                }
            }
            try self.appendUniqueResumeRecipient(&recipients, id);
        }
        return .{
            .channel = channel,
            .plain = owned_plain,
            .extended = owned_extended,
            .recipients = try recipients.toOwnedSlice(self.allocator),
            .logical_join = !exact_sibling_was_member,
            .time_tag = .init(),
        };
    }

    fn snapshotContainsChannel(snap: *const migration_relay.Snapshot, channel: []const u8) bool {
        for (snap.channels) |desired| {
            if (std.ascii.eqlIgnoreCase(desired, channel)) return true;
        }
        return false;
    }

    fn worldIdInResumeSet(ids: []const world_model.ClientId, candidate: world_model.ClientId) bool {
        for (ids) |id| if (id.eql(candidate)) return true;
        return false;
    }

    fn memberRestoreContainsChannel(members: []const world_model.MemberRestore, channel: []const u8) bool {
        for (members) |member|
            if (std.ascii.eqlIgnoreCase(member.channel, channel)) return true;
        return false;
    }

    fn resumeRecipientsContain(recipients: []const client_model.ClientId, id: client_model.ClientId) bool {
        for (recipients) |recipient| if (recipient.eql(id)) return true;
        return false;
    }

    fn appendResumeTimed(
        capture: *ReplyCapture,
        conn: *const ConnState,
        time_tag: []const u8,
        line: []const u8,
    ) void {
        if (conn.session.hasCap(.server_time)) capture.append(time_tag);
        capture.append(line);
    }

    /// Conservative raw SendQ bytes consumed when one complete plaintext resume
    /// bootstrap crosses WebSocket and/or userspace TLS. WebSocket emits one frame
    /// per IRC line (10 bytes is the largest server-frame header); TLS record
    /// ciphertext is bounded by plaintext plus 256 bytes per <=16 KiB record.
    fn resumeBootstrapRawBound(conn: *const ConnState, plaintext: []const u8) ?usize {
        var bytes = plaintext.len;
        var records: usize = 0;
        if (conn.ws) |ws| {
            if (ws.phase == .open) {
                if (ws.tx_len != 0) return null;
                const lines = std.mem.count(u8, plaintext, "\n");
                const terminators = std.math.mul(usize, lines, 2) catch return null;
                if (terminators > bytes) return null;
                bytes -= terminators;
                bytes = std.math.add(usize, bytes, std.math.mul(usize, lines, 10) catch return null) catch return null;
                records = lines;
            }
        }
        if (conn.tls) |tls| {
            if (tls.handshakeDone() and !conn.tls_tx_offloaded) {
                if (records == 0)
                    records = if (bytes == 0) 0 else (bytes + 16 * 1024 - 1) / (16 * 1024);
                bytes = std.math.add(usize, bytes, std.math.mul(usize, records, 256) catch return null) catch return null;
            }
        }
        return bytes;
    }

    const PreparedResumeClaimantOutput = struct {
        storage: []u8,
        len: usize,

        fn bytes(self: *const PreparedResumeClaimantOutput) []const u8 {
            return self.storage[0..self.len];
        }

        fn deinit(self: *PreparedResumeClaimantOutput, allocator: std.mem.Allocator) void {
            allocator.free(self.storage);
            self.* = undefined;
        }
    };

    /// Prepare the complete claimant-local restore stream while World and
    /// SessionStore remain abortable. It includes claimant-visible PART/NICK,
    /// attachment-local JOIN/topic, and—unless no-implicit-names was negotiated—
    /// one projected 353..366 completion for every desired channel, including a
    /// channel where this physical World row was already present.
    fn prepareResumeClaimantOutput(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        desired_session: dispatch.ClientSession,
        exact_world_ids: []const world_model.ClientId,
        desired: []const world_model.MemberRestore,
        part_plans: []const ResumePartPlan,
        nick_line: ?[]const u8,
        nick_recipients: []const client_model.ClientId,
        join_plans: []const ResumeJoinPlan,
    ) ?PreparedResumeClaimantOutput {
        const inline_queued = conn.send_len - conn.send_offset;
        const queued = std.math.add(usize, inline_queued, conn.send_overflow.items.len) catch return null;
        if (queued >= conn.sendq_cap) return null;
        const storage = self.allocator.alloc(u8, conn.sendq_cap - queued) catch return null;
        var retained = false;
        defer if (!retained) self.allocator.free(storage);
        var capture = ReplyCapture{ .buf = storage };

        for (part_plans) |plan| {
            if (resumeRecipientsContain(plan.recipients, id))
                appendResumeTimed(&capture, conn, plan.time_tag.bytes(), plan.line);
        }
        if (nick_line) |line| {
            if (resumeRecipientsContain(nick_recipients, id)) capture.append(line);
        }

        var preview = conn.*;
        preview.session = desired_session;
        preview.reply_capture = &capture;
        for (desired) |member| {
            for (join_plans) |plan| {
                if (!std.ascii.eqlIgnoreCase(plan.channel, member.channel)) continue;
                if (resumeRecipientsContain(plan.recipients, id)) {
                    appendResumeTimed(
                        &capture,
                        conn,
                        plan.time_tag.bytes(),
                        if (desired_session.hasCap(.extended_join)) plan.extended else plan.plain,
                    );
                    self.sendTopicReply(&preview, member.channel) catch return null;
                }
                break;
            }
            if (!desired_session.hasCap(.no_implicit_names)) {
                self.sendNamesWithProjection(&preview, member.channel, .{
                    .exact_world_ids = exact_world_ids,
                    .nick = desired_session.displayName(),
                    .user = desired_session.username(),
                    .modes = member.modes,
                    .is_override_oper = desired_session.hasPriv(.oper_override),
                }) catch return null;
            }
        }
        if (capture.overflowed) return null;

        const output = storage[0..capture.len];
        const raw_bound = resumeBootstrapRawBound(conn, output) orelse return null;
        reserveRawAppendToConn(conn, raw_bound) catch return null;
        retained = true;
        return .{ .storage = storage, .len = capture.len };
    }

    /// Restore one decoded migration image and bind its reusable token as a
    /// single failure-atomic operation. Every fallible allocation and every
    /// recipient/message snapshot precedes the World and SessionStore tickets;
    /// after the token ticket commits, the remaining state changes cannot fail.
    fn migrationSnapshotMatchesIdentity(
        account: []const u8,
        snap: *const migration_relay.Snapshot,
    ) bool {
        if (snap.account.len != 0 and !std.ascii.eqlIgnoreCase(snap.account, account)) return false;
        return snap.nick.len != 0 and !std.mem.eql(u8, snap.nick, "*") and isValidNick(snap.nick);
    }

    fn migrationRestoreAuthorityReady(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
    ) bool {
        if (conn.session_mesh_announce_pending and self.deferredSessionMeshAuthorityReady(id, conn))
            self.flushDeferredSessionMeshAnnouncements(id, conn);
        return !conn.session_mesh_announce_pending;
    }

    fn migrationRestorePreflight(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        snap: *const migration_relay.Snapshot,
    ) bool {
        return migrationSnapshotMatchesIdentity(account, snap) and
            self.migrationRestoreAuthorityReady(id, conn);
    }

    fn restoreAndBindMigrationSnapshot(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        session_token: sessions_mod.Token,
        bind_kind: sessions_mod.TokenBindKind,
        snap: *const migration_relay.Snapshot,
    ) bool {
        // The authenticated account and mesh-token HMAC are the authorization
        // boundary. A signed peer snapshot may restore only that same account;
        // never let carried snapshot data switch the live connection's identity.
        if (!self.migrationRestorePreflight(id, conn, account, snap)) return false;

        const cid = monitorIdFromClient(id);
        var token_ticket = self.sessions.prepareTokenBind(account, cid, session_token, bind_kind) orelse return false;
        defer token_ticket.deinit();
        return self.restoreAndBindMigrationSnapshotWithTicket(
            id,
            conn,
            account,
            session_token,
            snap,
            &token_ticket,
            null,
        );
    }

    const RestoreAttachmentTransfer = union(enum) {
        legacy: struct {
            old_client: sessions_mod.ClientId,
            new_client: sessions_mod.ClientId,
        },
        prepared_exact: *PreparedResumeAttachmentTransfer,
    };

    /// Complete a restore with either an ordinary token-bind ticket or the
    /// non-destructive bootstrap ticket used by tokenless SASL EXTERNAL. The
    /// caller owns the prepared ticket and must defer its deinit.
    fn restoreAndBindMigrationSnapshotWithTicket(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        account: []const u8,
        session_token: sessions_mod.Token,
        snap: *const migration_relay.Snapshot,
        token_ticket: anytype,
        attachment_transfer: ?RestoreAttachmentTransfer,
    ) bool {

        // Lock order is the completion-wide World write lock (already held by
        // the reactor), then SessionStore exclusive, then World's internal RCU
        // writer stages. The retained bind ticket freezes every folded-account
        // row through World/profile/output planning and both no-fail commits.
        // No SessionStore API may be called again before token_ticket.finish().
        const wid = worldIdFromClient(id);
        const cid = monitorIdFromClient(id);
        const session_rows = token_ticket.accountRows();

        // Decide exact-token attachment semantics before any live identity,
        // World, Store, output, or sidecar mutation. The claimant's current row
        // may belong to another reusable group. Moving its World nick while a
        // sibling still sustains that group would orphan the old identity, so
        // require a fresh connection for that cross-group attach.
        var claimant_token: ?sessions_mod.Token = null;
        var displaced_handle: ?sessions_mod.ResumeHandle = null;
        for (session_rows) |row| {
            if (row.client == cid) {
                claimant_token = row.token;
                displaced_handle = .{ .token = row.token, .portable = row.portable_resume };
            }
        }
        const requires_v2_authority = token_ticket.resultPortable();
        if (claimant_token) |current_token| {
            if (!tokenIsNull(current_token) and
                !std.crypto.timing_safe.eql(sessions_mod.Token, current_token, session_token))
            {
                for (session_rows) |row| {
                    if (row.client == cid or !row.attached) continue;
                    if (std.crypto.timing_safe.eql(sessions_mod.Token, row.token, current_token)) return false;
                }
            }
        }

        // Public IRC lifecycle follows rendered nick occupancy, not token
        // authority. Any OTHER attached row that will keep rendering old_nick
        // suppresses a public PART, even if it belongs to another token; a target
        // sibling rendering a different nick must not suppress old identity exit.
        var surviving_old_identity_ids: std.ArrayList(world_model.ClientId) = .empty;
        defer surviving_old_identity_ids.deinit(self.allocator);
        for (session_rows) |row| {
            if (!row.attached or row.client == cid) continue;
            const old_id = clientIdFromMonitor(row.client);
            const old_conn = self.connFor(old_id) orelse continue;
            const old_account = old_conn.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(old_account, account) or
                !std.ascii.eqlIgnoreCase(old_conn.session.displayName(), conn.session.displayName())) continue;
            const old_wid = worldIdFromClient(old_id);
            if (!worldIdInResumeSet(surviving_old_identity_ids.items, old_wid))
                surviving_old_identity_ids.append(self.allocator, old_wid) catch return false;
        }
        var surviving_target_identity_ids: std.ArrayList(world_model.ClientId) = .empty;
        defer surviving_target_identity_ids.deinit(self.allocator);
        for (session_rows) |row| {
            if (!row.attached or row.client == cid) continue;
            const target_id = clientIdFromMonitor(row.client);
            const target_conn = self.connFor(target_id) orelse continue;
            const target_account = target_conn.session.account() orelse continue;
            if (!std.ascii.eqlIgnoreCase(target_account, account) or
                !std.ascii.eqlIgnoreCase(target_conn.session.displayName(), snap.nick)) continue;
            const target_wid = worldIdFromClient(target_id);
            if (!worldIdInResumeSet(surviving_target_identity_ids.items, target_wid))
                surviving_target_identity_ids.append(self.allocator, target_wid) catch return false;
        }
        if (!std.ascii.eqlIgnoreCase(conn.session.displayName(), snap.nick) and
            surviving_old_identity_ids.items.len != 0)
        {
            if (self.world.findNick(conn.session.displayName())) |old_owner|
                if (old_owner.eql(wid)) return false;
        }

        var exact_world_ids: std.ArrayList(world_model.ClientId) = .empty;
        defer exact_world_ids.deinit(self.allocator);
        for (session_rows) |row| {
            if (!row.attached or !std.crypto.timing_safe.eql(sessions_mod.Token, row.token, session_token)) continue;
            const sibling_id = clientIdFromMonitor(row.client);
            const sibling = self.connFor(sibling_id) orelse return false;
            if (sibling.closing or sibling.s2s != null or sibling.s2s_secured != null) return false;
            const sibling_account = sibling.session.account() orelse return false;
            if (!std.ascii.eqlIgnoreCase(sibling_account, account)) return false;
            const sibling_wid = worldIdFromClient(sibling_id);
            if (!worldIdInResumeSet(exact_world_ids.items, sibling_wid))
                exact_world_ids.append(self.allocator, sibling_wid) catch return false;
        }
        if (!worldIdInResumeSet(exact_world_ids.items, wid))
            exact_world_ids.append(self.allocator, wid) catch return false;

        const disposition: world_model.World.SessionNickDisposition = if (self.world.findNick(snap.nick)) |owner|
            if (worldIdInResumeSet(exact_world_ids.items, owner))
                .{ .claim_exact = owner }
            else blk: {
                const owner_conn = self.connFor(clientIdFromWorld(owner)) orelse return false;
                if (owner_conn.closing or owner_conn.s2s != null or owner_conn.s2s_secured != null) return false;
                const owner_account = owner_conn.session.account() orelse return false;
                if (!std.ascii.eqlIgnoreCase(owner_account, account)) return false;
                break :blk .{ .preserve_foreign = owner };
            }
        else
            .{ .claim_exact = wid };
        const target_owner_is_other = switch (disposition) {
            .claim_exact => |owner| !owner.eql(wid),
            .preserve_foreign => |owner| !owner.eql(wid),
        };
        const exclusive_rename = !std.ascii.eqlIgnoreCase(conn.session.displayName(), snap.nick) and
            surviving_old_identity_ids.items.len == 0 and !target_owner_is_other;
        const nonexclusive_rename = !std.ascii.eqlIgnoreCase(conn.session.displayName(), snap.nick) and
            !exclusive_rename;

        // Preview the SAME merged retry journal the retained ticket's no-fail
        // commit will publish. A detached snapshot may lag an accepted
        // PART/JOIN/MODE intent; overlaying here prevents RESUME from visibly
        // replaying stale membership for even one event-loop turn.
        var projection_buf: [sessions_mod.local_channel_projection_capacity]sessions_mod.LocalChannelProjection = undefined;
        const pending_projections = token_ticket.mergedLocalChannelProjectionsInto(&projection_buf);

        const desired_members = self.allocator.alloc(
            world_model.MemberRestore,
            snap.channels.len + pending_projections.len,
        ) catch return false;
        defer self.allocator.free(desired_members);
        var desired_member_len: usize = snap.channels.len;
        for (snap.channels, 0..) |channel, i| {
            desired_members[i] = .{
                .channel = channel,
                .modes = .{ .bits = if (i < snap.channel_modes.len) snap.channel_modes[i] else 0 },
            };
        }
        for (pending_projections) |*projection| {
            var found: ?usize = null;
            for (desired_members[0..desired_member_len], 0..) |member, i| {
                if (std.ascii.eqlIgnoreCase(member.channel, projection.channel())) {
                    found = i;
                    break;
                }
            }
            if (projection.present) {
                if (found) |index| {
                    desired_members[index].modes.bits = projection.member_mode_bits;
                } else {
                    desired_members[desired_member_len] = .{
                        .channel = projection.channel(),
                        .modes = .{ .bits = projection.member_mode_bits },
                    };
                    desired_member_len += 1;
                }
            } else if (found) |index| {
                var cursor = index;
                while (cursor + 1 < desired_member_len) : (cursor += 1)
                    desired_members[cursor] = desired_members[cursor + 1];
                desired_member_len -= 1;
            }
        }
        const desired = desired_members[0..desired_member_len];

        // Profile preparation runs on a value copy. restore() deliberately does
        // not touch negotiated capabilities, transport callbacks, or the SASL
        // nonce, but the latter is self-referential and must be repointed after
        // assigning the value into ConnState.
        var nonce_buf: [32]u8 = undefined;
        const nonce_len = @min(conn.session.sasl_server_nonce.len, nonce_buf.len);
        @memcpy(nonce_buf[0..nonce_len], conn.session.sasl_server_nonce[0..nonce_len]);
        var desired_session = conn.session;
        const configured_binding = if (self.oper_registry) |*registry|
            oper_session_provenance.configuredLocalBinding(registry, account)
        else
            null;
        const profile = prepareMigratedSessionProfile(
            &desired_session,
            account,
            snap,
            conn.is_tls,
            configured_binding,
            self.grantNowU64(),
        );

        var old_nick_buf: [64]u8 = undefined;
        const old_nick_src = conn.session.displayName();
        const old_nick_len = @min(old_nick_src.len, old_nick_buf.len);
        @memcpy(old_nick_buf[0..old_nick_len], old_nick_src[0..old_nick_len]);
        const old_nick = old_nick_buf[0..old_nick_len];
        var old_user_buf: [64]u8 = undefined;
        const old_user_src = conn.session.username();
        const old_user_len = @min(old_user_src.len, old_user_buf.len);
        @memcpy(old_user_buf[0..old_user_len], old_user_src[0..old_user_len]);
        const old_user = old_user_buf[0..old_user_len];
        const old_mesh_identity = DeferredSessionMeshIdentity.init(conn);

        var old_prefix_buf: [256]u8 = undefined;
        const old_prefix = clientPrefix(conn, &old_prefix_buf) catch "";
        const announce_nick = snap.nick.len != 0 and
            !std.mem.eql(u8, snap.nick, "*") and
            old_nick.len != 0 and
            !std.mem.eql(u8, old_nick, "*") and
            !std.ascii.eqlIgnoreCase(old_nick, snap.nick);
        var part_plans: std.ArrayListUnmanaged(ResumePartPlan) = .empty;
        defer {
            for (part_plans.items) |*plan| plan.deinit(self.allocator);
            part_plans.deinit(self.allocator);
        }
        var join_plans: std.ArrayListUnmanaged(ResumeJoinPlan) = .empty;
        defer {
            for (join_plans.items) |*plan| plan.deinit(self.allocator);
            join_plans.deinit(self.allocator);
        }

        const old_channel_count = self.world.channelCountOf(wid);
        const old_channels = self.allocator.alloc([]const u8, old_channel_count) catch return false;
        defer self.allocator.free(old_channels);
        const old_channel_len = self.world.channelsOf(wid, old_channels);
        for (old_channels[0..old_channel_len]) |channel| {
            var old_identity_survives = false;
            for (surviving_old_identity_ids.items) |old_wid| {
                if (self.world.isMember(channel, old_wid)) {
                    old_identity_survives = true;
                    break;
                }
            }
            if (memberRestoreContainsChannel(desired, channel) and
                (!nonexclusive_rename or old_identity_survives)) continue;
            var plan = self.prepareResumePartPlan(
                id,
                channel,
                old_prefix,
                surviving_old_identity_ids.items,
            ) catch return false;
            part_plans.append(self.allocator, plan) catch {
                plan.deinit(self.allocator);
                return false;
            };
        }

        var nick_line: ?[]u8 = null;
        defer if (nick_line) |line| self.allocator.free(line);
        var nick_recipients: std.ArrayList(client_model.ClientId) = .empty;
        defer nick_recipients.deinit(self.allocator);
        if (announce_nick and old_prefix.len != 0) {
            var nick_buf: [default_reply_bytes]u8 = undefined;
            const rendered = formatMessage(&nick_buf, old_prefix, "NICK", &.{}, snap.nick) catch return false;
            nick_line = self.allocator.dupe(u8, rendered) catch return false;
            self.appendUniqueResumeRecipient(&nick_recipients, id) catch return false;
            if (!nonexclusive_rename) {
                for (old_channels[0..old_channel_len]) |channel| {
                    if (!memberRestoreContainsChannel(desired, channel)) continue;
                    var members = self.world.memberIterator(channel) orelse continue;
                    while (members.next()) |member|
                        self.appendUniqueResumeRecipient(&nick_recipients, clientIdFromWorld(member.*)) catch return false;
                }
            }
        }

        var desired_prefix_buf: [256]u8 = undefined;
        const desired_prefix = std.fmt.bufPrint(&desired_prefix_buf, "{s}!{s}@{s}", .{
            desired_session.displayName(),
            desired_session.username(),
            if (desired_session.host().len == 0) default_host else desired_session.host(),
        }) catch return false;
        const claimant_was_member = self.allocator.alloc(bool, desired.len) catch return false;
        defer self.allocator.free(claimant_was_member);
        for (desired, 0..) |member, i| {
            const chan = member.channel;
            claimant_was_member[i] = self.world.isMember(chan, wid);
            var target_identity_was_member = false;
            for (surviving_target_identity_ids.items) |target_wid| {
                if (self.world.isMember(chan, target_wid)) {
                    target_identity_was_member = true;
                    break;
                }
            }
            if (claimant_was_member[i] and
                (!nonexclusive_rename or target_identity_was_member)) continue;
            var plan = self.prepareResumeJoinPlan(
                id,
                chan,
                desired_prefix,
                account,
                desired_session.realname(),
                member.modes,
                target_identity_was_member,
            ) catch return false;
            join_plans.append(self.allocator, plan) catch {
                plan.deinit(self.allocator);
                return false;
            };
        }

        var deferred_parts: []DeferredSessionMeshPart = &.{};
        var deferred_parts_transferred = false;
        defer if (!deferred_parts_transferred and deferred_parts.len != 0) self.allocator.free(deferred_parts);
        var logical_part_count: usize = 0;
        for (part_plans.items) |plan| {
            logical_part_count += @intFromBool(plan.logical_part);
        }
        if (logical_part_count != 0) {
            deferred_parts = self.allocator.alloc(DeferredSessionMeshPart, logical_part_count) catch return false;
            var next_part: usize = 0;
            for (part_plans.items) |plan| {
                if (!plan.logical_part) continue;
                deferred_parts[next_part] = DeferredSessionMeshPart.init(plan.channel) catch return false;
                next_part += 1;
            }
        }
        const monitor_display_changes = old_nick.len != 0 and snap.nick.len != 0 and
            !std.mem.eql(u8, old_nick, snap.nick);
        const monitor_case_only = monitor_display_changes and
            std.ascii.eqlIgnoreCase(old_nick, snap.nick);
        const new_was_announced_online = target_owner_is_other or
            surviving_target_identity_ids.items.len != 0;
        var monitor_plan: ?PreparedMonitorTransition = null;
        defer if (monitor_plan) |*plan| plan.deinit(self.allocator);
        if (monitor_display_changes) {
            // Prepare every fallible MONITOR operation while the session and
            // World tickets are still abortable. The later observable apply is
            // allocation-free even for an unbounded watcher set.
            if (monitor_case_only) {
                self.monitor.reserveOnlineTransition(
                    old_nick,
                    snap.nick,
                    true,
                    new_was_announced_online,
                ) catch return false;
            } else {
                monitor_plan = self.prepareMonitorOccupancyTransition(
                    old_nick,
                    snap.nick,
                    new_was_announced_online,
                ) catch return false;
            }
        }
        var claimant_output = self.prepareResumeClaimantOutput(
            id,
            conn,
            desired_session,
            exact_world_ids.items,
            desired,
            part_plans.items,
            nick_line,
            nick_recipients.items,
            join_plans.items,
        ) orelse return false;
        defer claimant_output.deinit(self.allocator);
        // The token ticket above retains SessionStore's exclusive lock across
        // this World preparation, guaranteeing the previewed journal overlay is
        // exactly what the following no-fail cross-component commit installs.
        var world_ticket = self.world.prepareSessionRestore(
            snap.nick,
            wid,
            exact_world_ids.items,
            disposition,
            desired,
        ) catch return false;
        defer world_ticket.abort();
        // Attachment delivery ownership moves only after every fallible World,
        // profile, and output plan has succeeded. The spool transfer performs
        // conflict preflight before its allocation-free commit; after it
        // succeeds, both retained tickets have no-fail commits remaining.
        if (attachment_transfer) |transfer| switch (transfer) {
            .legacy => |legacy| self.transferAttachmentDeliveries(
                legacy.old_client,
                legacy.new_client,
            ) catch return false,
            .prepared_exact => {},
        };
        var bootstrap_eviction: ?sessions_mod.EvictedSession = null;
        if (@TypeOf(token_ticket.*) == sessions_mod.PreparedTokenBind) {
            if (!token_ticket.commit()) {
                token_ticket.abort();
                return false;
            }
        } else if (@TypeOf(token_ticket.*) == sessions_mod.PreparedAttachmentRebind) {
            if (!token_ticket.commit()) {
                token_ticket.abort();
                return false;
            }
        } else if (@TypeOf(token_ticket.*) == sessions_mod.PreparedBootstrapTokenAttach) {
            const outcome = token_ticket.commit();
            bootstrap_eviction = outcome.evicted;
        } else {
            @compileError("unsupported session restore ticket type");
        }
        world_ticket.commit();
        if (attachment_transfer) |transfer| switch (transfer) {
            .legacy => {},
            .prepared_exact => |prepared| {
                prepared.commit();
                // Do not carry ADS1 into token_ticket.finish() or any later
                // SessionStore helper: teardown takes these locks in the
                // opposite temporal phase under the documented global order.
                prepared.release();
            },
        };
        conn.session = desired_session;
        if (!conn.session_mesh_announce_pending) {
            conn.session_mesh_announce_pending = true;
            conn.session_mesh_announce_token_bound = true;
            conn.session_mesh_announce_requires_authority = requires_v2_authority;
            conn.session_mesh_announce_token = session_token;
            conn.session_mesh_announce_old_retracted = false;
            conn.session_mesh_announce_nick_change = announce_nick and exclusive_rename;
            conn.session_mesh_announce_old_nick_len = if (announce_nick or deferred_parts.len != 0) @intCast(old_nick.len) else 0;
            if (announce_nick or deferred_parts.len != 0)
                @memcpy(conn.session_mesh_announce_old_nick[0..old_nick.len], old_nick);
            conn.session_mesh_announce_old_identity = old_mesh_identity;
            conn.session_mesh_announce_parts = deferred_parts;
            deferred_parts_transferred = true;
        }
        conn.nick_claimed_at_ms = 0;
        token_ticket.finish();

        // Only retire displaced token authority after SessionStore, World, and
        // the physical attachment delivery mapping are all committed.
        if (bootstrap_eviction) |evicted| {
            lockSpin(&self.attachment_delivery_mu);
            _ = self.attachment_delivery_spool.discardAttachment(evicted.client);
            self.attachment_delivery_mu.unlock();
            self.finalizeRemovedSessionAuthority(evicted.resumeHandle());
        }

        // Restore runtime callbacks/policy only after the transaction is visible,
        // then repair the nonce's self pointer to ConnState's inline backing.
        self.injectSessionState(conn);
        conn.session.setSaslServerNonce(nonce_buf[0..nonce_len]);
        if (displaced_handle) |old_handle| {
            if (!std.crypto.timing_safe.eql(sessions_mod.Token, old_handle.token, session_token))
                self.finalizeRemovedSessionAuthority(old_handle);
        }

        // Capacity and overflow storage for this exact transport representation
        // were reserved before either ticket committed. Emit the complete
        // claimant-local PART/NICK/JOIN/topic/NAMES stream as one prepared
        // plaintext batch; an unexpected transport-crypto failure poisons the
        // connection, so it can never observe a successful resume after a
        // partial roster.
        if (claimant_output.len != 0) {
            appendToConn(conn, claimant_output.bytes()) catch {
                self.poisonOwnedDelivery(conn);
                return true;
            };
            self.armSendIfNeeded(conn) catch {
                self.poisonOwnedDelivery(conn);
                return true;
            };
        }

        // Observable ordering mirrors a real client transition: leave obsolete
        // channels under the old prefix, rename while common peers still see the
        // identity, then enter/bootstrap target-only channels under the new one.
        for (part_plans.items) |plan| {
            for (plan.recipients) |recipient| {
                if (recipient.eql(id)) continue;
                self.deliverTimed(recipient, plan.time_tag.bytes(), plan.line) catch {};
            }
            if (!plan.logical_part) continue;
            self.recordHistoryEventSender(plan.channel, old_prefix, "PART", plan.channel);
            self.publishMemberEvent("PART", plan.channel, old_nick, null) catch {};
            self.notifyObservers(.part, .{
                .nick = old_nick,
                .user = old_user,
                .host = old_mesh_identity.real_host[0..old_mesh_identity.real_host_len],
                .account = account,
                .detail = plan.channel,
            });
            if (!self.world.channelExists(plan.channel)) self.publishChannelEvent("DESTROY", plan.channel) catch {};
        }
        if (nick_line) |line| {
            for (nick_recipients.items) |recipient| {
                if (recipient.eql(id)) continue;
                self.deliver(recipient, line) catch {};
            }
            var nick_body_buf: [64]u8 = undefined;
            const nick_body = std.fmt.bufPrint(&nick_body_buf, ":{s}", .{snap.nick}) catch snap.nick;
            if (exclusive_rename) {
                for (desired, 0..) |member, i|
                    if (claimant_was_member[i]) self.recordHistoryEventSender(member.channel, old_prefix, "NICK", nick_body);
            }
        }
        if (monitor_case_only) {
            const display = if (self.world.findNick(snap.nick)) |owner|
                self.world.nickOf(owner) orelse snap.nick
            else
                snap.nick;
            self.monitor.transitionOnlineSilent(old_nick, display, true) catch {};
        } else if (monitor_display_changes) {
            self.applyPreparedMonitorOccupancyTransition(
                &monitor_plan.?,
                old_nick,
                snap.nick,
                surviving_old_identity_ids.items.len != 0,
                new_was_announced_online,
            ) catch {};
        }
        for (join_plans.items) |plan| {
            for (plan.recipients) |recipient| {
                if (recipient.eql(id)) continue;
                const recipient_conn = self.connFor(recipient) orelse continue;
                self.deliverTimed(
                    recipient,
                    plan.time_tag.bytes(),
                    if (recipient_conn.session.hasCap(.extended_join)) plan.extended else plan.plain,
                ) catch {};
            }
            if (plan.logical_join) {
                self.recordHistoryEventSender(plan.channel, desired_prefix, "JOIN", plan.channel);
                self.publishMemberEvent("JOIN", plan.channel, conn.session.displayName(), null) catch {};
                self.notifyObservers(.join, observeSubject(conn, plan.channel));
            }
        }
        if (profile.override_activated) {
            self.auditOverrideUse(conn, "UMODE", conn.session.displayName(), "override restored via migration");
        }
        return true;
    }

    const MigratedProfileResult = struct {
        /// A carried +j changed an authorized claimant from override-off to
        /// override-on. The caller audits this only after the enclosing restore
        /// commits; preparation itself performs no I/O or audit side effects.
        override_activated: bool = false,
    };

    /// Project one authenticated migration snapshot onto a ClientSession value.
    /// The authenticated account and current transport/grant are authoritative;
    /// carried profile data may move visible identity but cannot rewrite the peer
    /// address, CAP negotiation, transport proof, or derived privilege modes.
    fn prepareMigratedSessionProfile(
        session: *dispatch.ClientSession,
        authenticated_account: []const u8,
        snap: *const migration_relay.Snapshot,
        transport_secure: bool,
        configured_binding: ?oper_session_provenance.ConfiguredLocalBinding,
        authority_now_ms: u64,
    ) MigratedProfileResult {
        // restore() overwrites inline storage, so copy every live slice needed for
        // re-derivation before entering it. Negotiated caps live outside the fields
        // restore replaces and therefore survive this in-place value preparation.
        var real_host_buf: [255]u8 = undefined;
        const real_host_src = session.realHost();
        const real_host_len = @min(real_host_src.len, real_host_buf.len);
        @memcpy(real_host_buf[0..real_host_len], real_host_src[0..real_host_len]);
        var account_buf: [64]u8 = undefined;
        const account_len = @min(authenticated_account.len, account_buf.len);
        @memcpy(account_buf[0..account_len], authenticated_account[0..account_len]);

        const live_had_override = session.hasUmode(.override);
        const live_media_tx_denied = session.hasUmode(.media_tx_deny);

        // The HMAC-authenticated caller account is canonical even for rolling-old
        // snapshots that omitted their account field. The current socket's real
        // host remains local transport identity; only its visible host migrates.
        session.restore(.{
            .nick = snap.nick,
            .realname = snap.realname,
            .account = account_buf[0..account_len],
            .real_host = real_host_buf[0..real_host_len],
            .host = snap.host,
            .away = snap.away,
            .username = snap.username,
            .logged_in = true,
            .away_active = snap.away.len != 0,
            // A carried oper bit is profile history, not current authority. RESUME
            // runs after local authentication/elevation, so only the claimant's
            // verified live grant may retain +o or derive +a/+j.
            .is_oper = false,
        });

        // A carried oper bit and the predecessor's in-memory projection are
        // profile history, never authority. Recompute from the live sealed
        // configured binding after restore; OCG2 remains explicitly disabled
        // until the transactional activation step is accepted.
        _ = session.reconcileOperAuthority(configured_binding, .disabled, authority_now_ms);
        if (live_had_override and session.hasPriv(.oper_override)) {
            _ = session.setUmode(.override, true);
        }

        return applyMigratedUmodesToSession(
            session,
            snap.umodes,
            transport_secure,
            live_media_tx_denied,
        );
    }

    /// Apply a rendered directional umode string to a ClientSession value without
    /// audit or external mutation. Derived/transport/privileged letters are never
    /// accepted from the snapshot: +r/+a come from login/grant, +z from the live
    /// transport, and o/x are ignored. +j additionally requires oper_override.
    fn applyMigratedUmodesToSession(
        session: *dispatch.ClientSession,
        mode_str: []const u8,
        transport_secure: bool,
        preserve_media_tx_deny: bool,
    ) MigratedProfileResult {
        const override_before = session.hasUmode(.override);
        var adding: ?bool = null;
        for (mode_str) |letter| switch (letter) {
            '+' => adding = true,
            '-' => adding = false,
            'o' => {},
            else => {
                const on = adding orelse continue;
                const mode = usermode.modeFromLetter(letter) orelse continue;
                // Share the replica projector's fail-closed allowlist. A future
                // server-managed catalog addition is non-portable by default.
                if (!portableReplicaUmode(mode)) continue;
                if (mode == .override and on and !session.hasPriv(.oper_override)) continue;
                _ = session.setUmode(mode, on);
            },
        };

        // Re-derive rather than merge these authority-bearing bits. In particular,
        // a plaintext claimant cannot escalate by presenting a carried +z.
        _ = session.setUmode(.secure_tls, transport_secure);
        _ = session.setUmode(.registered, session.account() != null);
        _ = session.setUmode(.admin, session.isAdmin());
        if (preserve_media_tx_deny) _ = session.setUmode(.media_tx_deny, true);
        if (!session.hasPriv(.oper_override)) _ = session.setUmode(.override, false);

        return .{
            .override_activated = !override_before and session.hasUmode(.override),
        };
    }

    /// `MEMO <SEND <account> :<msg> | LIST | CLEAR | FORWARD <account>|OFF |
    /// IGNORE ADD|DEL|LIST <account>>` — Onyx Server offline mail. SEND stores a message
    /// for an account (delivered when it next logs in, following the recipient's
    /// forward chain, unless that account ignores the sender — then it is silently
    /// dropped); LIST shows the caller's own pending mail; CLEAR discards it;
    /// FORWARD sets/clears/queries the caller's auto-forward target; IGNORE manages
    /// the caller's blocked-sender list. SEND/FORWARD/IGNORE require login.
    pub fn handleMemo(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const sub = if (parsed.param_count >= 1) parsed.paramSlice()[0] else "LIST";
        const me = conn.session.account();

        if (std.ascii.eqlIgnoreCase(sub, "LIST")) {
            const acct = me orelse {
                try self.failReply(conn, "MEMO", "ACCOUNT_REQUIRED", "Log in to read your offline memos");
                return;
            };
            try self.memoList(conn, acct);
            return;
        }
        if (std.ascii.eqlIgnoreCase(sub, "CLEAR")) {
            const acct = me orelse {
                try self.failReply(conn, "MEMO", "ACCOUNT_REQUIRED", "Log in to clear your offline memos");
                return;
            };
            const n = self.clearOfflineMemo(acct);
            var buf: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&buf, "MEMO: Cleared {d} message(s)", .{n}) catch return;
            try self.noticeTo(conn, line);
            const event = std.fmt.bufPrint(&buf, "MEMO cleared account={s} count={d}", .{ acct, n }) catch return;
            self.publishOperEvent(.service, .notice, event) catch {};
            return;
        }
        if (std.ascii.eqlIgnoreCase(sub, "FORWARD")) {
            const acct = me orelse {
                try self.failReply(conn, "MEMO", "ACCOUNT_REQUIRED", "Log in to manage memo forwarding");
                return;
            };
            // No target: report the current forward (or none).
            if (parsed.param_count < 2 or parsed.paramSlice()[1].len == 0) {
                var buf: [192]u8 = undefined;
                const line = if (self.memo_forward.forwardTarget(acct) catch null) |t|
                    std.fmt.bufPrint(&buf, "MEMO: Forwarding your offline memos to {s}", .{t}) catch return
                else
                    std.fmt.bufPrint(&buf, "MEMO: No forward set", .{}) catch return;
                try self.noticeTo(conn, line);
                return;
            }
            const target = parsed.paramSlice()[1];
            if (std.ascii.eqlIgnoreCase(target, "OFF") or std.ascii.eqlIgnoreCase(target, "NONE")) {
                _ = self.memo_forward.clearForward(acct) catch {};
                try self.noticeTo(conn, "MEMO: forwarding disabled");
                return;
            }
            // Set: the target must be a known account (and never the caller itself).
            if (self.account_services) |svc| {
                _ = svc.accountInfo(target) catch {
                    try self.failReply(conn, "MEMO", "ACCOUNT_UNKNOWN", "No such account");
                    return;
                };
            }
            self.memo_forward.setForward(acct, target) catch |err| {
                const code: []const u8 = switch (err) {
                    error.ForwardCycle => "FORWARD_CYCLE",
                    error.TooManyAccounts => "TEMPORARILY_UNAVAILABLE",
                    else => "INVALID_ACCOUNT",
                };
                try self.failReply(conn, "MEMO", code, "Could not set forwarding");
                return;
            };
            var buf: [192]u8 = undefined;
            const line = std.fmt.bufPrint(&buf, "MEMO: Forwarding your offline memos to {s}", .{target}) catch return;
            try self.noticeTo(conn, line);
            const event = std.fmt.bufPrint(&buf, "MEMO forward account={s} target={s}", .{ acct, target }) catch return;
            self.publishOperEvent(.service, .notice, event) catch {};
            return;
        }
        if (std.ascii.eqlIgnoreCase(sub, "IGNORE")) {
            const acct = me orelse {
                try self.failReply(conn, "MEMO", "ACCOUNT_REQUIRED", "Log in to manage memo ignores");
                return;
            };
            const action = if (parsed.param_count >= 2) parsed.paramSlice()[1] else "LIST";
            if (std.ascii.eqlIgnoreCase(action, "LIST")) {
                var out: [svc_memo_ignore.DEFAULT_MAX_ENTRIES_PER_ACCOUNT]svc_memo_ignore.Entry = undefined;
                const entries = self.memo_ignore.list(acct, &out) catch out[0..0];
                for (entries) |e| {
                    var lb: [192]u8 = undefined;
                    const ln = std.fmt.bufPrint(&lb, "MEMO: ignoring {s}", .{e.sender}) catch continue;
                    try self.noticeTo(conn, ln);
                }
                var eb: [128]u8 = undefined;
                const end = std.fmt.bufPrint(&eb, "MEMO: End of ignore list ({d})", .{entries.len}) catch return;
                try self.noticeTo(conn, end);
                return;
            }
            const is_add = std.ascii.eqlIgnoreCase(action, "ADD");
            const is_del = std.ascii.eqlIgnoreCase(action, "DEL") or std.ascii.eqlIgnoreCase(action, "REMOVE");
            if (!is_add and !is_del) {
                try self.failReply(conn, "MEMO", "INVALID_SUBCOMMAND", "Use MEMO IGNORE ADD|DEL|LIST <account>");
                return;
            }
            if (parsed.param_count < 3 or parsed.paramSlice()[2].len == 0) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"MEMO"}, "Usage: MEMO IGNORE ADD|DEL <account>");
                return;
            }
            const blocked_sender = parsed.paramSlice()[2];
            if (is_add) {
                const added = self.memo_ignore.add(acct, blocked_sender) catch {
                    try self.failReply(conn, "MEMO", "INVALID_ACCOUNT", "Could not add ignore");
                    return;
                };
                var nb: [192]u8 = undefined;
                const msg = if (added)
                    std.fmt.bufPrint(&nb, "MEMO: now ignoring memos from {s}", .{blocked_sender}) catch "MEMO: ignore updated"
                else
                    std.fmt.bufPrint(&nb, "MEMO: {s} was already ignored", .{blocked_sender}) catch "MEMO: ignore updated";
                try self.noticeTo(conn, msg);
            } else {
                const removed = self.memo_ignore.remove(acct, blocked_sender) catch false;
                var nb: [192]u8 = undefined;
                const msg = if (removed)
                    std.fmt.bufPrint(&nb, "MEMO: no longer ignoring {s}", .{blocked_sender}) catch "MEMO: ignore updated"
                else
                    std.fmt.bufPrint(&nb, "MEMO: {s} was not ignored", .{blocked_sender}) catch "MEMO: ignore updated";
                try self.noticeTo(conn, msg);
            }
            return;
        }
        if (std.ascii.eqlIgnoreCase(sub, "SEND")) {
            const from = me orelse {
                try self.failReply(conn, "MEMO", "ACCOUNT_REQUIRED", "Log in to send an offline memo");
                return;
            };
            if (parsed.param_count < 3 or parsed.paramSlice()[2].len == 0) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"MEMO"}, "Usage: MEMO SEND <account> :<message>");
                return;
            }
            const to = parsed.paramSlice()[1];
            const text = parsed.paramSlice()[2];
            // The recipient must be a known account (delivery is account-scoped).
            if (self.account_services) |svc| {
                _ = svc.accountInfo(to) catch {
                    try self.failReply(conn, "MEMO", "ACCOUNT_UNKNOWN", "No such account");
                    return;
                };
            }
            // Recipient memo-ignore: if the addressed account blocks this sender,
            // silently drop — the success reply is unchanged so the block cannot be
            // probed (fail-open if the check itself errors).
            if (!(self.memo_ignore.shouldAccept(to, from) catch true)) {
                try self.noticeTo(conn, "MEMO: message stored for delivery");
                return;
            }
            // Resolve the recipient's forward chain (hop/cycle-bounded). A broken
            // chain falls back to direct delivery rather than refusing the memo.
            const decision = self.memo_forward.resolveDelivery(to) catch svc_memo_forward.ForwardDecision{
                .original_account = to,
                .delivery_account = to,
                .forwarded = false,
                .hops = 0,
            };
            // Direct delivery borrows `to`; a forwarded account borrows the
            // forwarding store. Consume either before changing its owner.
            const delivery = if (decision.forwarded) decision.delivery_account else to;
            // A forward target must itself be a known account.
            if (decision.forwarded) {
                if (self.account_services) |svc| {
                    _ = svc.accountInfo(delivery) catch {
                        try self.failReply(conn, "MEMO", "ACCOUNT_UNKNOWN", "Forward target account is unknown");
                        return;
                    };
                }
            }
            _ = self.storeOfflineMemo(delivery, from, text, platform.realtimeMillis()) catch |err| {
                const code: []const u8 = switch (err) {
                    error.MailboxFull => "MAILBOX_FULL",
                    error.MessageInvalid => "INVALID_MESSAGE",
                    else => "TEMPORARILY_UNAVAILABLE",
                };
                try self.failReply(conn, "MEMO", code, "Could not deliver offline memo");
                return;
            };
            // Reach: the recipient has no attached session — nudge their
            // browser(s) through Web Push (best-effort; memo holds the DM).
            self.webpushNotify(delivery, from, text);
            self.meshBroadcastMemoPush(delivery, from, text);
            if (decision.forwarded) {
                var fb: [192]u8 = undefined;
                const msg = std.fmt.bufPrint(&fb, "MEMO: message stored (forwarded to {s})", .{delivery}) catch "MEMO: message stored for delivery";
                try self.noticeTo(conn, msg);
            } else {
                try self.noticeTo(conn, "MEMO: message stored for delivery");
            }
            return;
        }
        try self.failReply(conn, "MEMO", "INVALID_SUBCOMMAND", "Use SEND, LIST, CLEAR, FORWARD, or IGNORE");
    }

    /// WEBPUSH — browser push subscriptions (Onyx "reach you with the tab
    /// closed"). The server VAPID key is discovered via ISUPPORT `VAPID=`;
    /// lifecycle lands on the Event Spine.
    ///   SUBSCRIBE <endpoint> <p256dh> <auth>     → store (account-scoped, max 3)
    ///   UNSUBSCRIBE <endpoint>                   → remove one
    ///   LIST                                     → NOTICE per stored endpoint
    /// Keys are base64url-unpadded exactly as PushSubscription.getKey() gives
    /// them. Disabled (no worker) → FAIL, so clients can probe safely.
    pub fn handleWebpush(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (self.webpush_worker == null) {
            try self.failReply(conn, "WEBPUSH", "DISABLED", "Web push is not enabled on this server");
            return;
        }
        const sub = if (parsed.param_count >= 1) parsed.paramSlice()[0] else "LIST";

        const acct = conn.session.account() orelse {
            try self.failReply(conn, "WEBPUSH", "ACCOUNT_REQUIRED", "Log in to manage push subscriptions");
            return;
        };
        const svc = self.account_services orelse {
            try self.failReply(conn, "WEBPUSH", "TEMPORARILY_UNAVAILABLE", "Account services are unavailable");
            return;
        };

        if (std.ascii.eqlIgnoreCase(sub, "SUBSCRIBE")) {
            if (parsed.param_count < 4) {
                try self.failReply(conn, "WEBPUSH", "NEED_MORE_PARAMS", "WEBPUSH SUBSCRIBE <endpoint> <p256dh> <auth>");
                return;
            }
            const endpoint = parsed.paramSlice()[1];
            if (!webpush_mod.validEndpoint(endpoint)) {
                try self.failReply(conn, "WEBPUSH", "INVALID_ENDPOINT", "Endpoint must be a well-formed https URL");
                return;
            }
            const ua_public = webpush_mod.decodeKey65(parsed.paramSlice()[2]) catch {
                try self.failReply(conn, "WEBPUSH", "INVALID_KEY", "p256dh must be a base64url P-256 public key");
                return;
            };
            const auth = webpush_mod.decodeAuth16(parsed.paramSlice()[3]) catch {
                try self.failReply(conn, "WEBPUSH", "INVALID_KEY", "auth must be a 16-byte base64url secret");
                return;
            };

            const subs = self.webpushLoad(svc, acct);
            defer webpush_mod.freeList(self.allocator, subs);
            // Re-subscribing an existing endpoint refreshes its keys in place.
            var replaced = false;
            for (subs) |*existing| {
                if (std.mem.eql(u8, existing.endpoint, endpoint)) {
                    existing.ua_public = ua_public;
                    existing.auth = auth;
                    replaced = true;
                    break;
                }
            }
            if (!replaced and subs.len >= webpush_mod.max_subscriptions_per_account) {
                try self.failReply(conn, "WEBPUSH", "TOO_MANY_SUBSCRIPTIONS", "Subscription limit reached — UNSUBSCRIBE one first");
                return;
            }
            if (replaced) {
                self.webpushStore(svc, acct, subs);
            } else {
                const ep_owned = self.allocator.dupe(u8, endpoint) catch return;
                const grown = std.mem.concat(self.allocator, webpush_mod.Subscription, &.{ subs, &.{.{ .endpoint = ep_owned, .ua_public = ua_public, .auth = auth }} }) catch {
                    self.allocator.free(ep_owned);
                    return;
                };
                defer self.allocator.free(grown);
                self.webpushStore(svc, acct, grown);
                self.allocator.free(ep_owned);
            }
            try self.noticeTo(conn, "WEBPUSH: subscription stored");
            // Subscription lifecycle rides the Event Spine (oper-observable).
            var eb: [192]u8 = undefined;
            const ev = std.fmt.bufPrint(&eb, "WEBPUSH: {s} subscribed a push endpoint", .{acct}) catch "WEBPUSH: subscription stored";
            self.publishOperEventSubject(.service, .notice, ev, acct) catch {};
            return;
        }

        if (std.ascii.eqlIgnoreCase(sub, "UNSUBSCRIBE")) {
            if (parsed.param_count < 2) {
                try self.failReply(conn, "WEBPUSH", "NEED_MORE_PARAMS", "WEBPUSH UNSUBSCRIBE <endpoint>");
                return;
            }
            const endpoint = parsed.paramSlice()[1];
            const subs = self.webpushLoad(svc, acct);
            defer webpush_mod.freeList(self.allocator, subs);
            var kept: [webpush_mod.max_subscriptions_per_account]webpush_mod.Subscription = undefined;
            var n: usize = 0;
            for (subs) |existing| {
                if (std.mem.eql(u8, existing.endpoint, endpoint)) continue;
                if (n < kept.len) {
                    kept[n] = existing;
                    n += 1;
                }
            }
            if (n == subs.len) {
                try self.failReply(conn, "WEBPUSH", "NOT_SUBSCRIBED", "No such subscription");
                return;
            }
            self.webpushStore(svc, acct, kept[0..n]);
            try self.noticeTo(conn, "WEBPUSH: subscription removed");
            var eb: [192]u8 = undefined;
            const ev = std.fmt.bufPrint(&eb, "WEBPUSH: {s} removed a push endpoint", .{acct}) catch "WEBPUSH: subscription removed";
            self.publishOperEventSubject(.service, .notice, ev, acct) catch {};
            return;
        }

        if (std.ascii.eqlIgnoreCase(sub, "LIST")) {
            const subs = self.webpushLoad(svc, acct);
            defer webpush_mod.freeList(self.allocator, subs);
            for (subs) |existing| {
                var buf: [default_reply_bytes]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "WEBPUSH: {s}", .{existing.endpoint}) catch continue;
                try self.noticeTo(conn, msg);
            }
            var buf: [default_reply_bytes]u8 = undefined;
            const msg = std.fmt.bufPrint(&buf, "WEBPUSH: {d} subscription(s)", .{subs.len}) catch return;
            try self.noticeTo(conn, msg);
            return;
        }

        try self.failReply(conn, "WEBPUSH", "INVALID_SUBCOMMAND", "Use SUBSCRIBE, UNSUBSCRIBE, or LIST");
    }

    /// Load an account's stored subscriptions (empty on any failure).
    fn webpushLoad(self: *LinuxServer, svc: *services_mod.Services, account: []const u8) []webpush_mod.Subscription {
        const blob = svc.webpushGetAlloc(self.allocator, account) orelse return &.{};
        defer self.allocator.free(blob);
        return webpush_mod.decodeList(self.allocator, blob) catch &.{};
    }

    /// Persist a subscription list (best-effort).
    fn webpushStore(self: *LinuxServer, svc: *services_mod.Services, account: []const u8, subs: []const webpush_mod.Subscription) void {
        const blob = webpush_mod.encodeList(self.allocator, subs) catch return;
        defer self.allocator.free(blob);
        svc.webpushPut(account, blob) catch {};
    }

    /// Source consumer cut, called under World. Worker retains its own mutex
    /// through each callback; callbacks may enter Services, never this Worker.
    /// A partial synced Services prefix is idempotent: retain the complete
    /// original endpoint list until every account has reconciled successfully.
    fn reconcileWebpushOutcomesLocked(self: *LinuxServer, deadline: ?std.Io.Clock.Timestamp) !void {
        const worker = self.webpush_worker orelse return;
        try self.requireMediaRetirementDeadline(deadline);
        const Context = struct {
            server: *LinuxServer,
            deadline: ?std.Io.Clock.Timestamp,

            fn prune(context: @This(), endpoints: []const []const u8) !void {
                try context.server.requireMediaRetirementDeadline(context.deadline);
                const svc = context.server.account_services orelse return error.MissingAccountServices;
                if (context.deadline) |limit| {
                    _ = try svc.webpushPruneDeadUntil(context.server.allocator, endpoints, limit);
                } else {
                    _ = try svc.webpushPruneDead(context.server.allocator, endpoints);
                }
                // If the deadline elapsed during synchronous storage work,
                // retain the whole original cut for an idempotent later pass.
                try context.server.requireMediaRetirementDeadline(context.deadline);
            }
            fn publish(context: @This(), message: []const u8) !void {
                try context.server.requireMediaRetirementDeadline(context.deadline);
                try context.server.acceptWebpushOverflowLocked(message);
            }
        };
        const context: Context = .{ .server = self, .deadline = deadline };
        // Accepted prefixes must fan out even if a later notice hit pressure.
        // This defer runs after the leaf returned and unlocked its real mutex.
        defer self.publishWebpushOverflowFanoutLocked();
        try worker.reconcileDead(context, Context.prune);
        try worker.reconcileOverflow(context, Context.publish);
    }

    fn acceptWebpushOverflowLocked(self: *LinuxServer, message: []const u8) !void {
        if (!std.mem.eql(u8, message, webpush_mod.overflow_oper_message)) return error.InvalidValue;
        const destination = for (&self.webpush_overflow_deliveries) |*slot| {
            if (slot.* == null) break slot;
        } else return error.Capacity;
        var candidate: WebpushOverflowDelivery = .{
            .origin = try self.allocator.dupe(u8, self.serverName()),
            .origin_node = self.config.node_id,
            .hlc = 0,
        };
        errdefer candidate.deinit(self.allocator);
        const body = formatOutboundBody(&candidate.body, .service, .warn, candidate.origin, message) orelse return error.Capacity;
        candidate.body_len = body.len;
        for (self.outbound_webhooks, &candidate.destinations) |subscription, *owned| {
            const sub = subscription orelse continue;
            if (!sub.mask.contains(.service)) continue;
            const url = try self.allocator.dupe(u8, sub.url);
            errdefer self.allocator.free(url);
            const secret = try self.allocator.dupe(u8, sub.secret);
            owned.* = .{ .url = url, .secret = secret, .mask = sub.mask };
        }
        if (self.config.node_identity) |identity| {
            // No identity has accepted before this cut. A staging/admission
            // failure may retry with a fresh HLC, so later accepted events
            // cannot retire a never-published candidate and wedge its notice.
            candidate.hlc = self.nextMeshHlc();
            var event = candidate.event();
            try oper_event.stampOrigin(&event, &identity.sign_kp, &candidate.public_key, &candidate.signature);
            candidate.event_id = (try self.admitEventSpineV2(event)) orelse return error.EventSpineAdmissionRejected;
        } else {
            // Legacy source append is allocation-free, with the same accepted
            // local history semantics as the existing direct-leaf publisher.
            self.event_history.record(@intFromEnum(event_spine.EventCategory.service), @intFromEnum(event_spine.EventSeverity.warn), platform.realtimeMillis(), candidate.origin, message);
            self.event_stats.record(@intFromEnum(event_spine.EventCategory.service), @intFromEnum(event_spine.EventSeverity.warn));
        }
        // Every fallible candidate precedes source acceptance. Publish owned
        // downstream work and consume exactly one Worker notice without failure.
        destination.* = candidate;
    }

    fn publishWebpushOverflowFanoutLocked(self: *LinuxServer) void {
        for (&self.webpush_overflow_deliveries) |*slot| {
            const delivery = if (slot.*) |*value| value else continue;
            if (!delivery.fanout_published) {
                if (delivery.event_id) |event_id| {
                    const event = delivery.event();
                    self.deliverOperEventV2Local(event, event_id, .service, .warn, event.subject);
                    self.meshBroadcastAuthoredOperEventV2(event);
                } else {
                    self.deliverOperEventLocal(delivery.origin, .service, .warn, webpush_mod.overflow_oper_message, webpush_mod.overflow_oper_message);
                    self.meshBroadcastOperEvent(.service, .warn, webpush_mod.overflow_oper_message);
                }
                delivery.fanout_published = true;
            }
            while (delivery.next_destination < delivery.destinations.len and delivery.destinations[delivery.next_destination] == null)
                delivery.next_destination += 1;
            if (delivery.next_destination == delivery.destinations.len) {
                delivery.deinit(self.allocator);
                slot.* = null;
            }
        }
    }

    /// One synchronous destination attempt per maintenance turn, outside Worker.
    /// Failure retains the exact body, URL, signing secret and destination cursor.
    fn retryWebpushOverflowOutputsLocked(self: *LinuxServer) void {
        for (&self.webpush_overflow_deliveries) |*slot| {
            const delivery = if (slot.*) |*value| value else continue;
            if (!delivery.fanout_published) continue;
            const sub = delivery.destinations[delivery.next_destination].?;
            const parsed = http_fetch.parseUrl(sub.url) catch return;
            const addr = self.resolveOutboundWebhookAddress(parsed.host, parsed.port) catch return;
            const test_anchors = self.outboundTrustOverrideForTest();
            var trust: ?outbound_trust.Store = if (parsed.tls and test_anchors == null)
                self.loadOutboundTrust() catch return
            else
                null;
            defer if (trust) |*store| store.deinit();
            var signature_buffer: [71]u8 = undefined;
            const body = delivery.body[0..delivery.body_len];
            const signature = outboundSignature(sub.secret, body, &signature_buffer);
            var opts = http_fetch.Options{
                .connect_timeout_ms = 400,
                .recv_timeout_ms = 400,
                .max_response_bytes = 4096,
            };
            opts.trust_anchors = if (test_anchors) |anchors| anchors else if (trust) |*store| store.anchors() else &.{};
            opts.disallowed_certs = if (trust) |*store| store.disallowed() else &.{};
            opts.windows_chain_policy = builtin.os.tag == .windows and trust != null;
            var connected = false;
            opts.connect_established = &connected;
            self.outbound_webhook_attempts += 1;
            const response = self.postOutboundAtAddress(parsed, body, signature, addr, opts) catch |err| blk: {
                if (!shouldWindowsPinnedAAAAFallback(addr, outboundHostIsHostname(parsed.host, parsed.port), connected, err)) return;
                const fallback_addr = self.resolveOutboundWebhookAAAAAddress(parsed.host, parsed.port) catch return;
                connected = false;
                self.outbound_webhook_attempts += 1;
                break :blk self.postOutboundAtAddress(parsed, body, signature, fallback_addr, opts) catch return;
            };
            defer self.allocator.free(response);
            if (!self.retainedWebhookResponseAccepted(response)) return;
            self.outbound_webhook_delivered += 1;
            // Only a real successful HTTP response releases this source output.
            self.allocator.free(sub.url);
            std.crypto.secureZero(u8, sub.secret);
            self.allocator.free(sub.secret);
            delivery.destinations[delivery.next_destination] = null;
            delivery.next_destination += 1;
            self.publishWebpushOverflowFanoutLocked();
            return;
        }
    }

    fn hasRetainedWebpushOverflow(self: *const LinuxServer) bool {
        for (self.webpush_overflow_deliveries) |slot| if (slot != null) return true;
        return false;
    }

    /// HTTP bytes at EOF alone are not a receipt. Refuse malformed status,
    /// ambiguous framing and incomplete bodies before releasing accepted output.
    fn retainedWebhookResponseAccepted(self: *LinuxServer, response: []u8) bool {
        const client_http = @import("../proto/http1_client.zig");
        const head_end = std.mem.indexOf(u8, response, "\r\n\r\n") orelse return false;
        const status_end = std.mem.indexOf(u8, response[0 .. head_end + 2], "\r\n") orelse return false;
        const status_line = response[0..status_end];
        if (status_line.len < 13 or status_line[8] != ' ' or status_line[12] != ' ') return false;
        for (status_line) |byte| if (byte < 0x20 or byte == 0x7f) return false;
        const head = response[0 .. head_end + 4];
        for (head, 0..) |byte, index| {
            if (byte == '\r' and (index + 1 == head.len or head[index + 1] != '\n')) return false;
            if (byte == '\n' and (index == 0 or head[index - 1] != '\r')) return false;
        }
        // Parse the complete original response only after strict framing and
        // chunk validation of untouched bytes.
        var content_length: ?usize = null;
        var chunked = false;
        const fields_start = if (status_end == head_end) head_end else status_end + 2;
        var fields = std.mem.splitSequence(u8, response[fields_start..head_end], "\r\n");
        var count: usize = 0;
        while (fields.next()) |field| {
            if (field.len == 0) continue;
            count += 1;
            if (count > 64) return false;
            const colon = std.mem.indexOfScalar(u8, field, ':') orelse return false;
            if (colon == 0) return false;
            const name = field[0..colon];
            for (name) |byte| if (!std.ascii.isAlphanumeric(byte) and std.mem.indexOfScalar(u8, "!#$%&'*+-.^_`|~", byte) == null) return false;
            const value = std.mem.trim(u8, field[colon + 1 ..], " \t");
            for (value) |byte| if ((byte < 0x20 and byte != '\t') or byte == 0x7f) return false;
            if (std.ascii.eqlIgnoreCase(name, "content-length")) {
                if (content_length != null or chunked or value.len == 0) return false;
                for (value) |byte| if (!std.ascii.isDigit(byte)) return false;
                content_length = std.fmt.parseInt(usize, value, 10) catch return false;
            }
            if (std.ascii.eqlIgnoreCase(name, "transfer-encoding")) {
                if (chunked or content_length != null or !std.ascii.eqlIgnoreCase(value, "chunked")) return false;
                chunked = true;
            }
        }
        const body = response[head_end + 4 ..];
        if (content_length) |length| {
            if (body.len != length) return false;
        } else if (chunked) {
            // This source decoder checks the final zero chunk, strict trailers,
            // every chunk boundary and exact consumption, without accepting an
            // apparent status from truncated or trailing bytes.
            var decoded = @import("../proto/http1.zig").decodeChunked(self.allocator, body, .{ .max_body_bytes = 4096, .max_header_bytes = 4096 }) catch return false;
            defer decoded.deinit(self.allocator);
        }
        var headers: [64]client_http.Header = undefined;
        const parsed = client_http.parseResponse(response, &headers) catch return false;
        if (parsed.status < 200 or parsed.status >= 300) return false;
        if (parsed.status == 204) return !chunked and body.len == 0 and (content_length == null or content_length.? == 0);
        // The fetcher can return immediately at a header without framing.
        // Until it supplies a source EOF proof, that cannot retire this output.
        return content_length != null or chunked;
    }

    /// Fire a push for an offline/closed-tab recipient. Payload is compact JSON
    /// sealed to the push subscription:
    ///   `{"type":"dm|mention|call","from":…,"text":…[,"channel":…]}`
    /// Also prunes endpoints the push service reported gone (404/410).
    fn webpushNotify(self: *LinuxServer, account: []const u8, from: []const u8, text: []const u8) void {
        self.webpushNotifyKind(account, "dm", from, text, null);
    }

    fn webpushNotifyKind(
        self: *LinuxServer,
        account: []const u8,
        kind: []const u8,
        from: []const u8,
        text: []const u8,
        channel: ?[]const u8,
    ) void {
        const worker = self.webpush_worker orelse return;
        const svc = self.account_services orelse return;
        if (account.len == 0 or kind.len == 0) return;

        // All accounts share worker outcomes. Refuse new notification work on
        // reconciliation failure, keeping the exact source outcomes for retry.
        self.reconcileWebpushOutcomesLocked(null) catch return;

        const subs = self.webpushLoad(svc, account);
        defer webpush_mod.freeList(self.allocator, subs);
        if (subs.len == 0) return;

        // Payload: compact JSON, text truncated so it always encrypts in one record.
        var pb: [640]u8 = undefined;
        var w = std.Io.Writer.fixed(&pb);
        w.writeAll("{\"type\":") catch return;
        writeJsonEscaped(&w, kind) catch return;
        w.writeAll(",\"from\":") catch return;
        writeJsonEscaped(&w, from) catch return;
        w.writeAll(",\"text\":") catch return;
        const preview = if (text.len > 240) text[0..240] else text;
        writeJsonEscaped(&w, preview) catch return;
        if (channel) |ch| {
            w.writeAll(",\"channel\":") catch return;
            writeJsonEscaped(&w, ch) catch return;
        }
        w.writeAll("}") catch return;

        for (subs) |subscription| _ = worker.enqueue(subscription.endpoint, subscription.ua_public, subscription.auth, w.buffered());
        self.reconcileWebpushOutcomesLocked(null) catch {};
    }

    /// True when `hay` contains `needle` as a case-insensitive IRC nick token
    /// (bounded by non-nick characters). Used for mention push (Era 3 C3).
    fn textMentionsNick(hay: []const u8, needle: []const u8) bool {
        if (needle.len == 0 or hay.len < needle.len) return false;
        var i: usize = 0;
        while (i + needle.len <= hay.len) : (i += 1) {
            if (!std.ascii.eqlIgnoreCase(hay[i .. i + needle.len], needle)) continue;
            const before_ok = i == 0 or !isIrcNickChar(hay[i - 1]);
            const after = i + needle.len;
            const after_ok = after == hay.len or !isIrcNickChar(hay[after]);
            if (before_ok and after_ok) return true;
        }
        return false;
    }

    fn isIrcNickChar(c: u8) bool {
        return std.ascii.isAlphanumeric(c) or c == '-' or c == '_' or c == '[' or c == ']' or c == '\\' or c == '`' or c == '^' or c == '{' or c == '}' or c == '|';
    }

    /// Closed-tab mention push for channel PRIVMSG (best-effort, local members).
    fn webpushNotifyChannelMentions(self: *LinuxServer, channel: []const u8, from: []const u8, text: []const u8) void {
        if (self.webpush_worker == null) return;
        var members = self.world.memberIterator(channel) orelse return;
        while (members.next()) |member| {
            const id = clientIdFromWorld(member.*);
            const mconn = self.connFor(id) orelse continue;
            const nick = mconn.session.displayName();
            if (std.ascii.eqlIgnoreCase(nick, from)) continue;
            if (!textMentionsNick(text, nick)) continue;
            const acct = mconn.session.account() orelse continue;
            self.webpushNotifyKind(acct, "mention", from, text, channel);
        }
    }

    /// Closed-tab call invite when someone first joins media in a room.
    pub fn webpushNotifyCallInvite(self: *LinuxServer, channel: []const u8, from: []const u8) void {
        if (self.webpush_worker == null) return;
        var members = self.world.memberIterator(channel) orelse return;
        while (members.next()) |member| {
            const id = clientIdFromWorld(member.*);
            const mconn = self.connFor(id) orelse continue;
            const nick = mconn.session.displayName();
            if (std.ascii.eqlIgnoreCase(nick, from)) continue;
            if (self.media_rooms.isParticipant(channel, nick)) continue;
            const acct = mconn.session.account() orelse continue;
            self.webpushNotifyKind(acct, "call", from, "Voice/video call started", channel);
        }
    }

    /// Ask every secured mesh peer to run its own account-local Web Push worker
    /// for a stored offline memo/DM. This intentionally does NOT copy memo
    /// storage or push subscriptions; the peer only delivers if it already owns a
    /// local subscription for `account`.
    fn meshBroadcastMemoPush(self: *LinuxServer, account: []const u8, from: []const u8, text: []const u8) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                link.sendMemoPush(account, from, text) catch continue;
                _ = self.flushSecuredS2sOutboundTo(pid, link);
            }
        }
    }

    /// Decode inbound secured MEMO_PUSH hints and run local Web Push delivery.
    /// No re-fan and no memo storage: the original node remains the memo source
    /// of truth, while this node can notify browsers subscribed here.
    fn drainMemoPushes(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const payloads = link.takeMemoPushes() catch return;
        defer {
            for (payloads) |p| self.allocator.free(p);
            self.allocator.free(payloads);
        }
        for (payloads) |p| {
            const ev = memo_push_relay.decode(p) catch continue;
            self.webpushNotify(ev.account, ev.from, ev.text);
        }
    }

    /// Fan an already-validated browser Cadence datagram to every established
    /// secured mesh peer. Origin-only: receivers never re-mesh (see
    /// `drainMediaWsDatagrams`). Best-effort — a peer that rejects oversize or
    /// is not signing-capable is skipped without affecting local delivery.
    fn meshBroadcastMediaWsDatagram(self: *LinuxServer, channel: []const u8, datagram: []const u8) void {
        if (datagram.len == 0 or datagram.len > media_ws_relay.max_datagram_len) return;
        if (channel.len == 0 or channel.len > media_ws_relay.max_channel_len) return;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                link.sendMediaWsDatagram(channel, datagram) catch continue;
                _ = self.flushSecuredS2sOutboundTo(pid, link);
            }
        }
    }

    /// Decode inbound secured MEDIA_WS_DATAGRAM cascades and fan out locally to
    /// WS call participants. Never re-meshes: the origin node is the sole mesh
    /// emitter (loop prevention). Browser MAC is not re-verified — the origin
    /// already admitted the opaque E2EE datagram.
    fn drainMediaWsDatagrams(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const payloads = link.takeMediaWsDatagrams() catch return;
        defer {
            for (payloads) |p| self.allocator.free(p);
            self.allocator.free(payloads);
        }
        for (payloads) |p| {
            const ev = media_ws_relay.decode(p) catch continue;
            // Local-only fanout: pass a null sender so no local client is
            // excluded as "self", and skip the mesh publish path.
            self.fanoutWsMediaDatagramLocal(null, ev.channel, ev.datagram);
        }
    }

    /// Emit the caller's pending memos as server notices (without clearing).
    fn memoList(self: *LinuxServer, conn: *ConnState, account: []const u8) !void {
        for (self.memo.pending(account)) |m| {
            var buf: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&buf, "MEMO from {s} :{s}", .{ m.from, m.text }) catch continue;
            try self.noticeTo(conn, line);
        }
        var end_buf: [default_reply_bytes]u8 = undefined;
        const end = std.fmt.bufPrint(&end_buf, "MEMO: End of offline memos ({d})", .{self.memo.count(account)}) catch return;
        try self.noticeTo(conn, end);
    }

    /// Deliver and clear any pending memos for the freshly-logged-in account.
    fn deliverMemo(self: *LinuxServer, conn: *ConnState) !void {
        const account = conn.session.account() orelse return;
        const msgs = self.memo.pending(account);
        if (msgs.len == 0) return;
        for (msgs) |m| {
            var buf: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&buf, "MEMO from {s} :{s}", .{ m.from, m.text }) catch continue;
            try self.noticeTo(conn, line);
            self.meshBroadcastMemoPush(account, m.from, m.text);
        }
        _ = self.clearOfflineMemo(account);
    }

    pub fn mediaPhysicalIndex(self: *const LinuxServer, id: client_model.ClientId, channel: []const u8, nick: []const u8) ?usize {
        for (self.media_physical_attachments.items, 0..) |*entry, idx| {
            if (entry.client.eql(id) and
                std.ascii.eqlIgnoreCase(entry.channelSlice(), channel) and
                std.ascii.eqlIgnoreCase(entry.nickSlice(), nick)) return idx;
        }
        return null;
    }

    fn mediaPhysicalKindPresent(self: *const LinuxServer, channel: []const u8, nick: []const u8, kind: media_room.MediaKind) bool {
        const bit = mediaKindBit(kind);
        for (self.media_physical_attachments.items) |*entry| {
            if ((entry.kind_bits & bit) != 0 and
                std.ascii.eqlIgnoreCase(entry.channelSlice(), channel) and
                std.ascii.eqlIgnoreCase(entry.nickSlice(), nick)) return true;
        }
        return false;
    }

    fn mediaPhysicalNickPresent(self: *const LinuxServer, channel: []const u8, nick: []const u8) bool {
        for (self.media_physical_attachments.items) |*entry| {
            if (std.ascii.eqlIgnoreCase(entry.channelSlice(), channel) and
                std.ascii.eqlIgnoreCase(entry.nickSlice(), nick)) return true;
        }
        return false;
    }

    /// Stage one physical membership before publishing nick-level MediaRooms
    /// state. Returns whether this is the first physical publisher of `kind`.
    pub fn addMediaPhysicalAttachment(
        self: *LinuxServer,
        id: client_model.ClientId,
        channel: []const u8,
        nick: []const u8,
        kind: media_room.MediaKind,
    ) !struct { first_kind: bool, changed: bool } {
        const first_kind = !self.mediaPhysicalKindPresent(channel, nick, kind);
        const bit = mediaKindBit(kind);
        if (self.mediaPhysicalIndex(id, channel, nick)) |idx| {
            if ((self.media_physical_attachments.items[idx].kind_bits & bit) != 0)
                return .{ .first_kind = false, .changed = false };
            self.media_physical_attachments.items[idx].kind_bits |= bit;
            return .{ .first_kind = first_kind, .changed = true };
        }
        const entry = MediaPhysicalAttachment.init(id, channel, nick, kind) orelse return error.NameTooLong;
        try self.media_physical_attachments.append(self.allocator, entry);
        return .{ .first_kind = first_kind, .changed = true };
    }

    pub fn rollbackMediaPhysicalKind(self: *LinuxServer, id: client_model.ClientId, channel: []const u8, nick: []const u8, kind: media_room.MediaKind) void {
        const idx = self.mediaPhysicalIndex(id, channel, nick) orelse return;
        const bit = mediaKindBit(kind);
        self.media_physical_attachments.items[idx].kind_bits &= ~bit;
        if (self.media_physical_attachments.items[idx].kind_bits == 0)
            _ = self.media_physical_attachments.swapRemove(idx);
    }

    fn removeMediaPhysicalAttachment(self: *LinuxServer, id: client_model.ClientId, channel: []const u8, nick: []const u8) MediaPhysicalRemoval {
        const idx = self.mediaPhysicalIndex(id, channel, nick) orelse return .absent;
        const removed = self.media_physical_attachments.swapRemove(idx);
        if (!self.mediaPhysicalNickPresent(channel, nick)) return .last;

        const pid = undertow_media.ParticipantId.init(nick) catch return .remaining;
        const room = self.media_rooms.room(channel) orelse return .remaining;
        inline for (.{ media_room.MediaKind.voice, media_room.MediaKind.video, media_room.MediaKind.screen }) |kind| {
            if ((removed.kind_bits & mediaKindBit(kind)) != 0 and !self.mediaPhysicalKindPresent(channel, nick, kind))
                room.leave(pid, kind) catch {};
        }
        return .remaining;
    }

    fn mediaPhysicalCanPublish(self: *const LinuxServer, id: client_model.ClientId, channel: []const u8, nick: []const u8, kind: media_room.MediaKind) bool {
        const idx = self.mediaPhysicalIndex(id, channel, nick) orelse return false;
        return (self.media_physical_attachments.items[idx].kind_bits & mediaKindBit(kind)) != 0;
    }

    /// Retire one physical connection's media authority for a channel while the
    /// old World membership and nick are still available for Event Spine routing.
    /// A surviving same-nick publisher gets attachment-granular crypto teardown;
    /// the final publisher keeps the existing nick-wide LEAVE lifecycle edge.
    pub fn retireMediaPhysicalChannel(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        nick: []const u8,
    ) !MediaPhysicalRemoval {
        const detached_attachment: ?[media_e2ee_attachment_bytes]u8 = if (conn.media_e2ee_attachment_bound)
            conn.media_e2ee_attachment
        else
            null;
        const removal = self.removeMediaPhysicalAttachment(id, channel, nick);
        conn.clearMediaE2eeAttachment();
        switch (removal) {
            .last => {
                self.media_plane.remove(channel, nick);
                self.native_media.unregister(channel, nick);
                self.bridgeUnregister(channel, nick);
                self.media_rooms.clearParticipantProfile(channel, nick);
                if (self.media_rooms.leaveAll(channel, nick)) {
                    try self.broadcastMediaEvent(channel, "LEAVE", nick, "");
                    if (self.media_rooms.room(channel) == null) _ = self.transcript.clearChannel(channel);
                }
            },
            .remaining => if (detached_attachment) |attachment|
                try self.publishMediaE2eeDetach(channel, nick, attachment),
            .absent => {},
        }
        if (conn.mediaCallChannel()) |bound| {
            if (std.ascii.eqlIgnoreCase(bound, channel)) conn.clearMediaCall();
        }
        return removal;
    }

    pub const reply_scratch_bytes: usize = default_reply_bytes;
    pub const fallback_host: []const u8 = default_host;

