    /// MEDIA control plane. The command body lives in `media_cmd.zig`.
    pub fn handleMedia(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return media_cmd.handle(self, id, conn, parsed);
    }

    /// Surface a media (voice/video) presence/state transition through the IRCX
    /// EVENT plane: `MEDIA <verb> <#chan> <nick> [kind]`, delivered as
    /// `:server EVENT <member> MEDIA …` to MEDIA-subscribed members across all
    /// shards AND every mesh peer (call presence now converges network-wide). The
    /// old local-only media notice broadcast is gone; clients consume EVENT MEDIA.
    pub fn broadcastMediaEvent(self: *LinuxServer, channel: []const u8, verb: []const u8, nick: []const u8, kind: []const u8) !void {
        if (self.mediaPresencePrivate(nick)) return;
        try self.publishMediaEvent(verb, channel, nick, kind);
    }

    pub fn publishMediaE2eeDetach(self: *LinuxServer, channel: []const u8, nick: []const u8, attachment: [media_e2ee_attachment_bytes]u8) !void {
        var token_buf: [base64url.encodedLen(media_e2ee_attachment_bytes)]u8 = undefined;
        const token = base64url.encode(&token_buf, &attachment) catch return error.OutputTooSmall;
        try self.publishMediaEvent("E2EE-DETACH", channel, nick, token);
    }

    /// Ingest one binary-WebSocket media datagram from a registered call
    /// participant: validate the Cadence frame shape, lenient-verify the per-stream
    /// MAC, and fan it out to the channel's other on-node WS call members.
    ///
    /// Browser media plane (primary when `ws_media_relay` is on): MACKEY on JOIN
    /// authenticates each Cadence frame; the Cadence payload is client-held E2EE
    /// ciphertext (attachment-bound AES-GCM). The daemon never decrypts it and
    /// never feeds it into the native↔WebRTC rewrap bridge — doing so would either
    /// require a group key the server does not hold, or would ship undecryptable
    /// ciphertext to native/RTP peers. Cross-leg mixed calls remain native UDP ↔
    /// WebRTC RTP only. A bad datagram is not relayed and does not close the IRC
    /// session. The sender is told with numeric 404, at most once a second.
    fn handleWsMediaDatagram(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, datagram: []const u8) void {
        if (!self.config.ws_media_relay) return;
        if (!conn.session.registered()) return;
        if (conn.session.hasUmode(.media_tx_deny)) {
            self.noteMediaFrameDrop(conn, "*", "Media transmission is disabled");
            return;
        }
        const channel = conn.mediaCallChannel() orelse {
            self.noteMediaFrameDrop(conn, "*", "Join the call before sending media");
            return;
        };
        const participant = conn.mediaCallParticipant();

        // One call validates the frame shape AND lenient-verifies a present tag,
        // using the same `native_stream_key`-derived `(channel, participant)` key
        // the native UDP leg uses. On any error the datagram is dropped.
        const frame_bytes = cadence_frame.acceptNativeMediaMac(
            &self.native_stream_key,
            channel,
            participant,
            datagram,
            self.config.ws_media_require_mac,
        ) catch {
            self.noteMediaFrameDrop(conn, channel, "Media frame rejected");
            return;
        };
        const frame = cadence_frame.decode(frame_bytes) catch {
            self.noteMediaFrameDrop(conn, channel, "Media frame rejected");
            return;
        };

        // The participant-scoped MAC proves possession of this connection's
        // media key, not that the caller used its own stream id or an authorized
        // media kind. Bind both after MAC verification and before any relay so a
        // participant cannot MAC a victim's stream id and impersonate that track.
        if (!self.wsMediaFrameAuthorized(id, channel, participant, frame)) {
            self.noteMediaFrameDrop(conn, channel, "Media frame rejected");
            return;
        }

        // Opaque WS fan-out only — never rewrap into native/RTP (E2EE).
        self.relayWsMediaDatagram(id, channel, datagram);
    }

    /// Tell the sender that a browser media datagram was not relayed. The IRC
    /// session stays up. A one-second quiet period keeps a stream of bad frames
    /// from filling the send queue.
    fn noteMediaFrameDrop(self: *LinuxServer, conn: *ConnState, channel: []const u8, why: []const u8) void {
        const now = self.nowMs();
        const quiet_until = std.math.add(i64, conn.media_drop_notice_ms, 1000) catch std.math.maxInt(i64);
        if (conn.media_drop_notice_ms != 0 and now < quiet_until) return;
        conn.media_drop_notice_ms = now;
        const chan = if (channel.len == 0) "*" else channel;
        queueNumeric(conn, .ERR_CANNOTSENDTOCHAN, &.{chan}, why) catch return;
        if (conn.fd >= 0) self.armSendIfNeeded(conn) catch {};
    }

    fn wsMediaFrameAuthorized(
        self: *LinuxServer,
        id: client_model.ClientId,
        channel: []const u8,
        participant: []const u8,
        frame: cadence_frame.FrameView,
    ) bool {
        if (!self.world.isMember(channel, worldIdFromClient(id))) return false;
        if (!connForMediaAttachmentAuthorized(self, id, frame.payload)) return false;

        const expected_stream = switch (frame.codec) {
            .cadencevox_audio => browserMediaStreamId(channel, participant, "audio"),
            .cadencevis_video => browserMediaStreamId(channel, participant, "video"),
            .raw => return false,
        };
        if (frame.stream_id != expected_stream) return false;

        for (self.media_rooms.roster(channel)) |entry| {
            if (!std.mem.eql(u8, entry.id.slice(), participant)) continue;
            return switch (frame.codec) {
                .cadencevox_audio => self.mediaPhysicalCanPublish(id, channel, participant, .voice) and entry.canPublish(.voice),
                // CadenceVis is the encoded family for both camera and screen;
                // either explicit publishing kind authorizes that codec family.
                .cadencevis_video => (self.mediaPhysicalCanPublish(id, channel, participant, .video) and entry.canPublish(.video)) or
                    (self.mediaPhysicalCanPublish(id, channel, participant, .screen) and entry.canPublish(.screen)),
                // `raw` has no exact MediaKind binding in the Cadence header, so
                // the authenticated WS admission path rejects it fail-closed.
                .raw => false,
            };
        }
        return false;
    }

    fn connForMediaAttachmentAuthorized(self: *LinuxServer, id: client_model.ClientId, payload: []const u8) bool {
        const conn = self.connFor(id) orelse return false;
        if (!conn.media_e2ee_attachment_bound or payload.len < media_e2ee_attachment_bytes + account_identity.signature_len) return false;
        const claimed: [media_e2ee_attachment_bytes]u8 = payload[0..media_e2ee_attachment_bytes].*;
        return std.crypto.timing_safe.eql([media_e2ee_attachment_bytes]u8, conn.media_e2ee_attachment, claimed);
    }

    /// Browser Cadence stream-id contract: JS FNV-1a32 over UTF-8
    /// `lower(channel) + NUL + lower(nick) + NUL + kind`. IRC channel/nick
    /// syntax is ASCII, so bytewise ASCII lowering is exactly the browser result
    /// for every accepted identity byte.
    fn browserMediaStreamId(channel: []const u8, nick: []const u8, kind: []const u8) u32 {
        var hash: u32 = 0x811c9dc5;
        for (channel) |byte| {
            hash ^= std.ascii.toLower(byte);
            hash *%= 0x01000193;
        }
        hash ^= 0;
        hash *%= 0x01000193;
        for (nick) |byte| {
            hash ^= std.ascii.toLower(byte);
            hash *%= 0x01000193;
        }
        hash ^= 0;
        hash *%= 0x01000193;
        for (kind) |byte| {
            hash ^= byte;
            hash *%= 0x01000193;
        }
        return hash;
    }

    /// Fan a validated media datagram out to the channel's other call participants
    /// over a binary WS frame, then origin-cascade once onto the secured mesh so
    /// remote-node participants receive the same opaque E2EE bytes. Same-node
    /// recipients are encoded once and reused; cross-shard recipients ride the
    /// reactor fabric as a preframed secure payload. Cross-node receivers only
    /// local-fanout (never re-mesh) — see `drainMediaWsDatagrams`.
    fn relayWsMediaDatagram(self: *LinuxServer, sender: client_model.ClientId, channel: []const u8, datagram: []const u8) void {
        self.fanoutWsMediaDatagramLocal(sender, channel, datagram);
        self.meshBroadcastMediaWsDatagram(channel, datagram);
    }

    /// Local-only binary WS fanout for a Cadence media datagram. `sender` is the
    /// originating client when this node admitted the frame (excluded from the
    /// fanout); `null` means a mesh-received cascade (every local participant
    /// is a candidate). Does not mesh-publish — callers that own the origin
    /// path invoke `meshBroadcastMediaWsDatagram` separately.
    fn fanoutWsMediaDatagramLocal(self: *LinuxServer, sender: ?client_model.ClientId, channel: []const u8, datagram: []const u8) void {
        if (datagram.len > WsState.max_media_frame) return; // exceeds the media frame ceiling
        // A media datagram (video keyframe) can be ~1.3 MB — far too large for a
        // stack buffer — so encode the binary WS frame once on the heap and reuse
        // it for every recipient. Best-effort: an OOM just drops this datagram.
        const frame_buf = self.allocator.alloc(u8, datagram.len + 10) catch return;
        defer self.allocator.free(frame_buf);
        const ws_frame = websocket.encodeFrame(WsState.max_media_frame, .{ .opcode = .binary }, datagram, frame_buf) catch return;

        var members = self.world.memberIterator(channel) orelse return;
        while (members.next()) |member| {
            const mid = clientIdFromWorld(member.*);
            if (sender) |sid| {
                if (mid.eql(sid)) continue;
            }
            const mconn = self.connFor(mid) orelse continue;
            if (mconn.closing) continue;
            const recipient_ws = mconn.ws orelse continue; // browser media only goes to WS peers
            // Never inject a binary application frame before the HTTP Upgrade
            // completes or onto a text.ircv3.net connection. Legacy/no-offer
            // and onyx.irc-media.v1 recipients retain binary compatibility.
            if (recipient_ws.phase != .open or !wsAdmitsBinaryApplication(recipient_ws)) continue;
            // Deliver to actual call participants, not every channel member.
            if (!self.media_rooms.isParticipant(channel, mconn.session.displayName())) continue;
            self.enqueuePreframedSecureDelivery(mid, ws_frame) catch continue;
        }
    }

    /// Derive this participant's per-stream MAC key and hand it to them over the
    /// authenticated WS as a caller-only MEDIA Event Spine reply (`MACKEY`).
    /// For browser clients with `ws_media_relay`, this key plus binary Cadence
    /// frames is the primary media plane — not the UDP NATIVE/TRANSPORT
    /// candidates (those are suppressed when unroutable; see
    /// `provisionMediaTransports`). Only the owning participant ever receives
    /// its own key; the server re-derives to verify (stateless).
    pub fn issueMediaMacKey(self: *LinuxServer, conn: *ConnState, channel: []const u8, participant: []const u8) void {
        var k32: [cadence_frame.MAC_KEY_BYTES]u8 = undefined;
        cadence_frame.deriveNativeMediaMacKey(&self.native_stream_key, channel, participant, &k32);
        defer std.crypto.secureZero(u8, k32[0..]);

        var b64: [std.base64.standard.Encoder.calcSize(cadence_frame.MAC_KEY_BYTES)]u8 = undefined;
        const enc = std.base64.standard.Encoder.encode(&b64, &k32);

        var detail_buf: [128]u8 = undefined;
        const detail = std.fmt.bufPrint(&detail_buf, "{s}", .{enc}) catch return;
        self.sendMediaEventReply(conn, "MACKEY", channel, detail) catch {
            conn.closing = true;
            return;
        };
        self.armSendIfNeeded(conn) catch {};
    }

    fn mediaPresencePrivate(self: *LinuxServer, nick: []const u8) bool {
        const wid = self.world.findNick(nick) orelse return false;
        const c = self.connFor(clientIdFromWorld(wid)) orelse return false;
        return c.session.hasUmode(.media_presence_private);
    }

    /// Remove a departing client from every media call it was in, broadcasting a
    /// LEAVE to each affected channel. Called on disconnect (before the client is
    /// removed from the world, so it is still a member for the broadcast).
    fn leaveAllMediaRooms(self: *LinuxServer, id: client_model.ClientId, conn: *const ConnState) void {
        const nick = conn.session.displayName();
        if (std.mem.eql(u8, nick, "*")) return;
        const detached_attachment: ?[media_e2ee_attachment_bytes]u8 = if (conn.media_e2ee_attachment_bound)
            conn.media_e2ee_attachment
        else
            null;
        var it = self.world.channels.iterator();
        while (it.next()) |entry| {
            if (!entry.value_ptr.members.contains(worldIdFromClient(id))) continue;
            const removal = self.removeMediaPhysicalAttachment(id, entry.key_ptr.*, nick);
            if (removal == .remaining) {
                if (detached_attachment) |attachment|
                    self.publishMediaE2eeDetach(entry.key_ptr.*, nick, attachment) catch {};
                continue;
            }
            if (removal == .absent) continue;
            self.media_plane.remove(entry.key_ptr.*, nick);
            self.native_media.unregister(entry.key_ptr.*, nick);
            self.bridgeUnregister(entry.key_ptr.*, nick);
            self.media_rooms.clearParticipantProfile(entry.key_ptr.*, nick);
            if (self.media_rooms.leaveAll(entry.key_ptr.*, nick)) {
                self.broadcastMediaEvent(entry.key_ptr.*, "LEAVE", nick, "") catch {};
                if (self.media_rooms.room(entry.key_ptr.*) == null) _ = self.transcript.clearChannel(entry.key_ptr.*);
            }
        }
    }

    fn retireLogicalMediaBeforeNickMutation(self: *LinuxServer, logical_ids: []const client_model.ClientId) void {
        for (logical_ids) |logical_id| {
            const logical_conn = self.connFor(logical_id) orelse continue;
            self.leaveAllMediaRooms(logical_id, logical_conn);
            // Fail closed even when this connection had no physical registry
            // entry: no old-nick WS call or handshake authority survives NICK.
            logical_conn.clearMediaCall();
            logical_conn.clearMediaE2eeAttachment();
        }
    }

    /// Emit the current call roster for `channel` to the caller as targeted
    /// MEDIA Event Spine replies.
    fn codecTagName(tag: sdp.CodecTag) []const u8 {
        return switch (tag) {
            .cadencevox => "cadencevox",
            .cadencevis => "cadencevis",
            .raw => "raw",
        };
    }

    fn codecMediaKind(tag: sdp.CodecTag) ?media_room.MediaKind {
        return switch (tag) {
            .cadencevox => .voice,
            .cadencevis => .video,
            .raw => null,
        };
    }

    fn codecSetHasKind(codecs: []const sdp.Codec, kind: media_room.MediaKind) bool {
        for (codecs) |codec| {
            if (codecMediaKind(codec.tag) == kind) return true;
        }
        return false;
    }

    fn bridgeCodecTag(tag: sdp.CodecTag) media_bridge_mod.Codec {
        return switch (tag) {
            .cadencevox => .cadencevox,
            .cadencevis => .cadencevis,
            .raw => .raw,
        };
    }

    fn bridgeCodecsFromSdp(out: []media_bridge_mod.Codec, codecs: []const sdp.Codec) []const media_bridge_mod.Codec {
        var n: usize = 0;
        for (codecs) |codec| {
            if (n >= out.len) break;
            out[n] = bridgeCodecTag(codec.tag);
            n += 1;
        }
        return out[0..n];
    }

    fn fecSchemeName(scheme: sdp.FecScheme) []const u8 {
        return switch (scheme) {
            .none => "none",
            .rateless_lt => "rateless_lt",
            .rs_block => "rs_block",
        };
    }

    /// Parse a "codec[,codec...]" list into `out`, returning how many were
    /// recognized. Unknown names are skipped; the clock rate is codec-derived.
    fn parseCodecCsv(out: []sdp.Codec, codec_csv: []const u8) usize {
        var n: usize = 0;
        var it = std.mem.splitScalar(u8, codec_csv, ',');
        while (it.next()) |name| {
            if (name.len == 0 or n >= out.len) continue;
            // English wire names only (no Japanese codec aliases).
            const tag: sdp.CodecTag = if (std.ascii.eqlIgnoreCase(name, "cadencevox"))
                .cadencevox
            else if (std.ascii.eqlIgnoreCase(name, "cadencevis"))
                .cadencevis
            else if (std.ascii.eqlIgnoreCase(name, "raw"))
                .raw
            else
                continue;
            out[n] = .{ .tag = tag, .clock_rate = if (tag == .cadencevis) 90000 else 48000, .params = 0 };
            n += 1;
        }
        return n;
    }

    test "parseCodecCsv: English only; codecTagName emits English" {
        var out: [8]sdp.Codec = undefined;
        var n = parseCodecCsv(&out, "cadencevox,cadencevis,raw");
        try std.testing.expectEqual(@as(usize, 3), n);
        try std.testing.expectEqual(sdp.CodecTag.cadencevox, out[0].tag);
        try std.testing.expectEqual(sdp.CodecTag.cadencevis, out[1].tag);
        try std.testing.expectEqual(sdp.CodecTag.raw, out[2].tag);
        // Japanese aliases are rejected.
        n = parseCodecCsv(&out, "kaguravox,kaguravis");
        try std.testing.expectEqual(@as(usize, 0), n);
        n = parseCodecCsv(&out, "CADENCEVOX");
        try std.testing.expectEqual(@as(usize, 1), n);
        try std.testing.expectEqualStrings("cadencevox", codecTagName(.cadencevox));
        try std.testing.expectEqualStrings("cadencevis", codecTagName(.cadencevis));
        try std.testing.expectEqualStrings("raw", codecTagName(.raw));
    }

    /// Format just `codecs=<list> fec=<scheme>` (no wire prefix) — the detail body
    /// of a MEDIA PROFILE event. Returns the written slice, or null if it overflows.
    fn formatMediaCodecDetail(buf: []u8, codecs: []const sdp.Codec, fec: sdp.Fec) ?[]const u8 {
        var w = Buf{ .storage = buf };
        w.append("codecs=") catch return null;
        for (codecs, 0..) |c, i| {
            if (i != 0) w.appendByte(',') catch return null;
            w.append(codecTagName(c.tag)) catch return null;
        }
        w.append(" fec=") catch return null;
        w.append(fecSchemeName(fec.scheme)) catch return null;
        return w.written();
    }

    /// Emit `MEDIA <label> <#chan> codecs=<list> fec=<scheme>` to the caller as an
    /// Event Spine reply.
    pub fn mediaNegotiatedReply(self: *LinuxServer, conn: *ConnState, channel: []const u8, label: []const u8, codecs: []const sdp.Codec, fec: sdp.Fec) !void {
        var buf: [320]u8 = undefined;
        const detail = formatMediaCodecDetail(&buf, codecs, fec) orelse return;
        try self.sendMediaEventReply(conn, label, channel, detail);
    }

    fn publishMediaCaps(self: *LinuxServer, channel: []const u8, nick: []const u8, codecs: []const sdp.Codec, fec: sdp.Fec) !void {
        var buf: [320]u8 = undefined;
        const detail = formatMediaCodecDetail(&buf, codecs, fec) orelse return;
        try self.publishMediaEvent("CAPS", channel, nick, detail);
    }

    fn sendDeniedMediaKinds(self: *LinuxServer, conn: *ConnState, channel: []const u8, offered: []const sdp.Codec, accepted: []const sdp.Codec) !void {
        const kinds = [_]media_room.MediaKind{ .voice, .video };
        for (kinds) |kind| {
            if (!codecSetHasKind(offered, kind) or codecSetHasKind(accepted, kind)) continue;
            var buf: [96]u8 = undefined;
            const detail = std.fmt.bufPrint(&buf, "kind={s} reason=no_common_codec", .{media_room.kindName(kind)}) catch return;
            try self.sendMediaEventReply(conn, "KIND-DENIED", channel, detail);
        }
    }

    pub fn mediaAbrActionName(action: undertow_media.AbrAction) []const u8 {
        return switch (action) {
            .hold => "hold",
            .increase => "increase",
            .decrease => "decrease",
            .pause => "pause",
        };
    }

    fn mediaAbrLayers() [3]simulcast_select.Layer {
        return .{
            .{ .spatial = 0, .temporal = 0, .bitrate_bps = 150_000 },
            .{ .spatial = 1, .temporal = 0, .bitrate_bps = 500_000 },
            .{ .spatial = 2, .temporal = 0, .bitrate_bps = 1_200_000 },
        };
    }

    fn mediaAbrTargetBps(target_kbps: u32) u32 {
        const bps = @as(u64, target_kbps) * 1000;
        return if (bps > std.math.maxInt(u32)) std.math.maxInt(u32) else @intCast(bps);
    }

    pub fn mediaAbrSelection(hint: undertow_media.AbrHint) !simulcast_select.Selection {
        const layers = mediaAbrLayers();
        const target_bps = if (hint.action == .pause) layers[0].bitrate_bps else mediaAbrTargetBps(hint.target_bitrate_kbps);
        return simulcast_select.selectStable(&layers, target_bps, null, 50_000);
    }

    /// The peer's RFC 8122 DTLS-SRTP request, parsed from a MEDIA OFFER/ANSWER's
    /// trailing args. `.none` = no fingerprint token (legacy SDES path);
    /// `.malformed` = a fingerprint token present but invalid (⇒ FAIL MEDIA);
    /// `.ok` = a well-formed SHA-256 fingerprint of the cert the peer will present.
    const OfferedFp = union(enum) {
        none,
        malformed,
        ok: [dtls_peer_verify_mod.digest_len]u8,
    };

    /// Value of a `key=` token within `args`, or null if not present.
    fn mediaTokenValue(args: []const []const u8, prefix: []const u8) ?[]const u8 {
        for (args) |a| {
            if (std.mem.startsWith(u8, a, prefix)) return a[prefix.len..];
        }
        return null;
    }

    /// Parse a `fingerprint=sha-256:<colon-hex>` token from a MEDIA OFFER/ANSWER.
    /// A single whitespace-delimited token (colon-joined alg) so it survives IRC
    /// param tokenization; the daemon's TRANSPORT reply renders the RFC 8122
    /// space form. Fail-closed: any malformed value (bad/unknown alg, wrong hex
    /// length, non-hex nibble) yields `.malformed` rather than being ignored.
    fn parseOfferedFingerprint(args: []const []const u8) OfferedFp {
        const val = mediaTokenValue(args, "fingerprint=") orelse return .none;
        const colon = std.mem.indexOfScalar(u8, val, ':') orelse return .malformed;
        const alg = val[0..colon];
        // Only SHA-256 is accepted (SHA-1 and unknown algs are rejected, not
        // silently downgraded).
        if (!std.ascii.eqlIgnoreCase(alg, "sha-256")) return .malformed;
        const hex = val[colon + 1 ..];
        var digest: [dtls_peer_verify_mod.digest_len]u8 = undefined;
        _ = dtls_fingerprint_mod.decodeDigest(.sha256, hex, &digest) catch return .malformed;
        return .{ .ok = digest };
    }

    test "parseOfferedFingerprint: none / malformed / ok" {
        // No fingerprint token → legacy path.
        try std.testing.expect(parseOfferedFingerprint(&.{ "transport=webrtc", "setup=active" }) == .none);
        try std.testing.expect(parseOfferedFingerprint(&.{}) == .none);

        // Well-formed sha-256 token → ok, decoded to the raw digest.
        var fpbuf: [128]u8 = undefined;
        const line = try dtls_fingerprint_mod.format(.sha256, "some cert der", &fpbuf);
        const hex = line["sha-256 ".len..];
        var tokbuf: [160]u8 = undefined;
        const tok = try std.fmt.bufPrint(&tokbuf, "fingerprint=sha-256:{s}", .{hex});
        const ok = parseOfferedFingerprint(&.{ "transport=webrtc", tok });
        try std.testing.expect(ok == .ok);
        var expect: [dtls_peer_verify_mod.digest_len]u8 = undefined;
        _ = try dtls_fingerprint_mod.decodeDigest(.sha256, hex, &expect);
        try std.testing.expectEqualSlices(u8, &expect, &ok.ok);

        // Malformed variants → .malformed (never ignored, never a trap).
        try std.testing.expect(parseOfferedFingerprint(&.{"fingerprint=sha-256"}) == .malformed); // no colon
        try std.testing.expect(parseOfferedFingerprint(&.{"fingerprint=sha-1:00:11"}) == .malformed); // unsupported alg
        try std.testing.expect(parseOfferedFingerprint(&.{"fingerprint=sha-256:00:11:22"}) == .malformed); // short hex
        try std.testing.expect(parseOfferedFingerprint(&.{"fingerprint="}) == .malformed); // empty value
    }

    /// Physical selectors are joined to the actual owned row and World here;
    /// nick, fd, transport flags and a surviving sibling do not identify a caller.
    /// The command owner holds World and its connection turn through publication.
    fn requireMediaCaller(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8) !void {
        if (id.isNone() or id.shard != self.rx().shard_id or self.connFor(id) != conn or
            !conn.session.registered() or conn.closing or conn.tls_terminal_failure or
            !self.world.isMember(channel, worldIdFromClient(id))) return error.BadState;
    }

    /// `MEDIA OFFER <#chan> <codec[,codec...]>` — negotiate the call's codec + FEC
    /// set against the SFU's supported codecs (real sdp/media_session offer/answer),
    /// persist it as the channel's active call profile, and reply with the agreed
    /// set. The UDP transport plane (ICE/STUN/TURN/jitter) is a separate layer;
    /// this is the live signaling/negotiation half.
    pub fn mediaOffer(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, codec_csv: []const u8, extra_args: []const []const u8) !void {
        try self.mediaNegotiateJoined(id, conn, channel, .offer, codec_csv, extra_args);
    }

    fn mediaNegotiateJoined(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, action: PreparedMediaNegotiation.Action, codec_csv: []const u8, extra_args: []const []const u8) !void {
        try self.requireMediaCaller(id, conn, channel);
        const negotiation = PreparedMediaNegotiation.prepare(self, id, conn, channel, action, codec_csv, extra_args) catch |err| switch (err) {
            error.NoCodecs => return self.failReply(conn, "MEDIA", "NO_CODECS", "Offer at least one codec: cadencevox,cadencevis,raw"),
            error.NoOffer => return self.failReply(conn, "MEDIA", "NO_OFFER", "No active call profile; send MEDIA OFFER first"),
            error.NoCommonCodec => return self.failReply(conn, "MEDIA", "NO_COMMON_CODEC", "No codec in common with the SFU"),
            error.BadFingerprint => return self.failReply(conn, "MEDIA", "BAD_FINGERPRINT", "Malformed fingerprint (expected fingerprint=sha-256:<colon-hex>)"),
            error.DtlsUnavailable => return self.failReply(conn, "MEDIA", "DTLS_UNAVAILABLE", "DTLS-SRTP keying is not enabled on this server"),
            else => return err,
        };
        const turn = try MediaAuthorityTurn.require(self, id, conn, if (action == .offer) .offer else .answer, channel);
        const owner = self.media_routing_owner orelse return self.failReply(conn, "MEDIA", "TRANSPORT_UNAVAILABLE", "Media transport is unavailable");
        var candidate: ?PreparedMediaOfferCommand = PreparedMediaOfferCommand.prepare(turn, mediaRoutingBacking(owner).domain, negotiation) catch |err| switch (err) {
            error.NoTransportSelected, error.BrowserTransportUnroutable => null,
            error.BadState => return self.failReply(conn, "MEDIA", "SECURE_SIGNALING_REQUIRED", "Endpoint credentials require a live protected signaling connection"),
            error.DtlsUnavailable => return self.failReply(conn, "MEDIA", "DTLS_UNAVAILABLE", "DTLS-SRTP keying is not enabled on this server"),
            else => return err,
        };
        if (candidate) |*plan| {
            defer plan.deinit();
            try plan.domain.withLocked(plan, PreparedMediaOfferCommand.publishLocked);
        } else {
            // Public-only negotiation creates neither an empty offer nor a
            // credential. Its Room profile and complete reply still join once.
            var plan = try PreparedPublicMediaNegotiation.prepare(turn, mediaRoutingBacking(owner).domain, negotiation);
            defer plan.deinit();
            try plan.domain.withLocked(&plan, PreparedPublicMediaNegotiation.publishLocked);
        }
        // Accepted issuer bytes already have protected SendQ custody. Subsequent
        // channel events use the existing Event Spine and never a label capture.
        conn.reply_capture = null;
        try self.publishMediaCaps(channel, conn.session.displayName(), negotiation.offered.slice(), negotiation.offered.fec);
        if (action == .offer) {
            var detail_buf: [256]u8 = undefined;
            const detail = formatMediaCodecDetail(&detail_buf, negotiation.agreed.slice(), negotiation.agreed.fec) orelse return error.OutputTooSmall;
            try self.publishMediaEvent("PROFILE", channel, conn.session.displayName(), detail);
        }
    }

    fn provisionMediaTransports(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, participant_codecs: []const sdp.Codec, dtls_mode: bool, extra_args: []const []const u8) !void {
        try self.requireMediaCaller(id, conn, channel);
        const nick = conn.session.displayName();
        const want_webrtc = dtls_mode or isWebrtcTransport(extra_args);

        // Prefer the STUN-discovered reflexive candidate over the static host.
        var host_buf: [16]u8 = undefined;
        const cand_host = self.media_plane.candidateIp(&host_buf) orelse self.config.media_host;
        const host_loopback = mediaHostIsLoopback(cand_host);

        // Browser WebSocket clients: the primary media plane is MACKEY + binary
        // Cadence frames over the authenticated WS (`ws_media_relay`). Those
        // frames carry client-held E2EE ciphertext the daemon cannot decrypt, so
        // they are never rewrapped onto the native Cadence UDP or WebRTC RTP legs
        // (see `handleWsMediaDatagram`). Advertising NATIVE/TRANSPORT with the
        // default loopback `media_host` (no STUN) is actively misleading — the
        // browser cannot use raw Cadence UDP, and a 127.0.0.1 ICE candidate is
        // unroutable from a remote peer.
        //
        // Policy for WS connections:
        //   - never advertise NATIVE (browser path is not the native UDP leg)
        //   - advertise TRANSPORT only when the client explicitly requested
        //     WebRTC/DTLS AND the candidate host is not loopback
        //   - bridge-register only when a UDP leg was actually provisioned
        // Non-WS (native IRC) clients keep the historical TRANSPORT+NATIVE path.
        const is_ws = conn.ws != null;
        const advertise_transport = if (is_ws) want_webrtc and !host_loopback else true;
        const advertise_native = !is_ws;

        // Allocate this participant's ICE endpoint and advertise the server
        // transport (ufrag/pwd + media candidate) so the client can run STUN to
        // the SFU. OFFER and ANSWER both call this: negotiation is useless if
        // the answerer never receives reachable transport credentials.
        if (advertise_transport) {
            if (self.media_plane.allocate(channel, nick)) |creds| {
                var tbuf: [400]u8 = undefined;
                if (dtls_mode) {
                    // RFC 8122: advertise the server's DTLS certificate fingerprint +
                    // setup=passive (Onyx Server is the DTLS server) INSTEAD of the SDES
                    // group key. The peer's offered fingerprint was already stored
                    // (fail-closed) above, so the handshake fails closed on a cert
                    // mismatch. `dtls_mode` implies `dtlsFingerprint` is non-null.
                    var fp_buf: [128]u8 = undefined;
                    const server_fp = self.media_plane.dtlsFingerprint(&fp_buf) orelse "";
                    const detail = std.fmt.bufPrint(&tbuf, "ufrag={s} pwd={s} candidate={s}:{d} fingerprint={s} setup=passive", .{
                        creds.ufragSlice(), creds.pwdSlice(), cand_host, self.media_plane.port, server_fp,
                    }) catch return;
                    try self.sendMediaEventReply(conn, "TRANSPORT", channel, detail);
                } else {
                    // Legacy SDES path (byte-identical to pre-Increment-3): ship the
                    // per-call SRTP group key, base64'd, over the TLS IRC link.
                    const gk = self.media_plane.groupKey(channel);
                    var gk_b64: [std.base64.standard.Encoder.calcSize(gk.len)]u8 = undefined;
                    const srtp_b64 = std.base64.standard.Encoder.encode(&gk_b64, &gk);
                    const detail = std.fmt.bufPrint(&tbuf, "ufrag={s} pwd={s} candidate={s}:{d} srtp={s}", .{
                        creds.ufragSlice(), creds.pwdSlice(), cand_host, self.media_plane.port, srtp_b64,
                    }) catch return;
                    try self.sendMediaEventReply(conn, "TRANSPORT", channel, detail);
                }
            }
        }

        // Native transport (our own CadenceVox/CadenceVis codec leg): register this
        // participant for the channel's native call and advertise the candidate +
        // the stream_id the client must stamp into its cadence frames. Independent
        // of the WebRTC plane above; best-effort (media is optional). Skipped for
        // WebSocket clients — their media plane is MACKEY + binary WS frames.
        const stream_id = self.nativeStreamId(channel, nick);
        if (advertise_native and self.native_media.port != 0) {
            self.native_media.register(channel, nick, .voice, stream_id, .{}) catch {};
            var nbuf: [256]u8 = undefined;
            const mac_token = if (self.config.native_media_require_mac) " mac=hmac-sha256-128" else "";
            // Advertise the STUN-discovered reflexive candidate (the public NAT
            // address), falling back to the configured host — same as the WebRTC
            // plane above. The native UDP socket sits behind the same NAT as the
            // WebRTC socket, so the reflexive IP is identical; without this a
            // remote native client would be told 127.0.0.1 and never reach the SFU.
            const detail = std.fmt.bufPrint(&nbuf, "candidate={s}:{d} stream={d} codec=CadenceVox/CadenceVis{s}", .{
                cand_host, self.native_media.port, stream_id, mac_token,
            }) catch return;
            try self.sendMediaEventReply(conn, "NATIVE", channel, detail);
        }

        // Record this participant's leg in the per-channel cross-leg bridge only
        // when they actually sit on a UDP leg. The bridge lets a native participant
        // and an opt-in-WebRTC participant in the same call hear each other
        // (rewrap only, never transcode). A pure WS browser is on neither leg.
        if (advertise_transport or advertise_native) {
            const leg: media_bridge_mod.Leg = if (want_webrtc and advertise_transport) .webrtc else .native;
            self.bridgeRegister(channel, nick, leg, stream_id, participant_codecs);
        }
    }

    /// True when an advertised media candidate host is loopback/unroutable from
    /// a remote peer. Used to suppress TRANSPORT/NATIVE replies to browser WS
    /// clients so they do not chase a 127.0.0.1 ICE path.
    fn mediaHostIsLoopback(host: []const u8) bool {
        if (host.len == 0) return true;
        if (std.ascii.eqlIgnoreCase(host, "localhost")) return true;
        if (std.mem.eql(u8, host, "::1")) return true;
        // IPv4 loopback 127.0.0.0/8 (covers 127.0.0.1 and the whole block).
        if (std.mem.startsWith(u8, host, "127.")) return true;
        return false;
    }

    test "mediaHostIsLoopback covers loopback and rejects routable hosts" {
        try std.testing.expect(mediaHostIsLoopback("127.0.0.1"));
        try std.testing.expect(mediaHostIsLoopback("127.1.2.3"));
        try std.testing.expect(mediaHostIsLoopback("::1"));
        try std.testing.expect(mediaHostIsLoopback("localhost"));
        try std.testing.expect(mediaHostIsLoopback("LOCALHOST"));
        try std.testing.expect(mediaHostIsLoopback(""));
        try std.testing.expect(!mediaHostIsLoopback("203.0.113.5"));
        try std.testing.expect(!mediaHostIsLoopback("stun.example.net"));
        try std.testing.expect(!mediaHostIsLoopback("10.0.0.1"));
    }

    /// True when the OFFER opts into the WebRTC leg via a `transport=webrtc`
    /// token (or a bare `webrtc` token); anything else means native. A DTLS-SRTP
    /// request always implies the WebRTC leg.
    fn isWebrtcTransport(args: []const []const u8) bool {
        for (args) |a| {
            const v = if (std.mem.startsWith(u8, a, "transport=")) a["transport=".len..] else a;
            if (std.ascii.eqlIgnoreCase(v, "webrtc")) return true;
        }
        return false;
    }

    /// Register (or update) a participant's leg in the channel's bridge roster.
    fn bridgeRegister(self: *LinuxServer, channel: []const u8, id: []const u8, leg: media_bridge_mod.Leg, stream_id: u32, codecs: []const sdp.Codec) void {
        lockSpin(&self.media_bridges_mu);
        defer self.media_bridges_mu.unlock();
        const gop = self.media_bridges.getOrPut(self.allocator, channel) catch return;
        if (!gop.found_existing) {
            const key = self.allocator.dupe(u8, channel) catch {
                _ = self.media_bridges.remove(channel);
                return;
            };
            gop.key_ptr.* = key;
            gop.value_ptr.* = Bridge.init();
        }
        var member = media_bridge_mod.Member{ .leg = leg, .stream_id = stream_id, .ssrc = stream_id };
        var codec_buf: [media_bridge_mod.max_member_codecs]media_bridge_mod.Codec = undefined;
        member.setCodecs(bridgeCodecsFromSdp(&codec_buf, codecs));
        gop.value_ptr.register(id, member) catch {};
    }

    /// Remove a participant from the channel's bridge; drop the channel once empty.
    fn bridgeUnregister(self: *LinuxServer, channel: []const u8, id: []const u8) void {
        lockSpin(&self.media_bridges_mu);
        defer self.media_bridges_mu.unlock();
        const br = self.media_bridges.getPtr(channel) orelse return;
        _ = br.unregister(id);
        if (br.count() != 0) return;
        const key = self.media_bridges.getKey(channel).?;
        _ = self.media_bridges.remove(channel);
        self.allocator.free(key);
    }

    /// Per-(channel,participant) cadence stream id advertised to the native client;
    /// it stamps this into every cadence frame it publishes so the SFU can map a
    /// frame back to its publisher. Keyed by the per-process `native_stream_key`
    /// (a secret PRF), so the id is UNGUESSABLE without that secret: it doubles as
    /// a capability token delivered over the TLS IRC channel, preventing an
    /// attacker who knows the public (channel, nick) from precomputing a victim's
    /// stream id and hijacking/injecting on the native-media UDP port. Stable per
    /// (channel,nick) for the process lifetime so re-JOIN is idempotent. Never 0.
    fn nativeStreamId(self: *const LinuxServer, channel: []const u8, nick: []const u8) u32 {
        return nativeStreamIdKeyed(&self.native_stream_key, channel, nick);
    }

    /// Pure keyed derivation behind `nativeStreamId` (HMAC-SHA256 over
    /// `channel ":" nick` under `key`, low 32 bits). Factored out so it is unit
    /// testable without constructing a full server.
    fn nativeStreamIdKeyed(key: *const [16]u8, channel: []const u8, nick: []const u8) u32 {
        const HmacSha256 = std.crypto.auth.hmac.sha2.HmacSha256;
        var mac = HmacSha256.init(key);
        mac.update(channel);
        mac.update(":");
        mac.update(nick);
        var out: [HmacSha256.mac_length]u8 = undefined;
        mac.final(&out);
        const v = std.mem.readInt(u32, out[0..4], .little);
        return if (v == 0) 1 else v;
    }

    test "native stream id is keyed, stable per key, and unguessable across keys" {
        const key_a = @as([16]u8, @splat(0xA1));
        const key_b = @as([16]u8, @splat(0xB2));
        // Stable per (key, channel, nick): re-JOIN must reproduce the same id.
        const a1 = nativeStreamIdKeyed(&key_a, "#chan", "alice");
        try std.testing.expectEqual(a1, nativeStreamIdKeyed(&key_a, "#chan", "alice"));
        // A different secret yields a different id, so the public (channel, nick)
        // does not reveal the id without the per-process key.
        try std.testing.expect(a1 != nativeStreamIdKeyed(&key_b, "#chan", "alice"));
        // Distinct participants get distinct ids; never 0.
        try std.testing.expect(a1 != nativeStreamIdKeyed(&key_a, "#chan", "bob"));
        try std.testing.expect(a1 != 0);
    }

    /// `MEDIA ANSWER <#chan> <codec[,codec...]>` — a later participant reconciles
    /// their codec capabilities against the call's active profile (set by OFFER).
    /// Replies with the intersection so everyone converges on a shared media set.
    /// A DTLS-SRTP answerer may carry its own `fingerprint=sha-256:<hex>`; it is
    /// validated (fail-closed) and stored so the answerer's DTLS leg fails closed
    /// on a certificate mismatch, exactly as the OFFER path.
    pub fn mediaAnswer(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, codec_csv: []const u8, extra_args: []const []const u8) !void {
        try self.mediaNegotiateJoined(id, conn, channel, .answer, codec_csv, extra_args);
    }

    /// `MEDIA STATS <#chan>` — per-participant transport state: ICE status and
    /// relayed packet/byte counts, terminated by an end line.
    pub fn mediaStats(self: *LinuxServer, conn: *ConnState, channel: []const u8) !void {
        var buf_stats: [64]media_plane_mod.MediaTransport.ParticipantStat = undefined;
        const n = self.media_plane.statsForChannel(channel, &buf_stats);
        for (buf_stats[0..n]) |s| {
            var buf: [default_reply_bytes]u8 = undefined;
            const detail = std.fmt.bufPrint(&buf, "{s} leg=webrtc ice={s} ssrc={x} rx_pkts={d} rx_bytes={d}", .{
                s.name(), if (s.connected) "connected" else "pending", s.ssrc, s.rx_packets, s.rx_bytes,
            }) catch continue;
            try self.sendMediaEventReply(conn, "STATS", channel, detail);
        }
        // Native leg (our own CadenceVox/CadenceVis codec) stats.
        var native_stats: [native_media_mod.max_call_participants]native_media_mod.NativeMediaTransport.Stat = undefined;
        const nn = self.native_media.statsForChannel(channel, &native_stats);
        for (native_stats[0..nn]) |s| {
            var buf: [default_reply_bytes]u8 = undefined;
            const detail = std.fmt.bufPrint(&buf, "{s} leg=native stream={d} rx_pkts={d} rx_bytes={d}", .{
                s.name(), s.stream_id, s.rx_packets, s.rx_bytes,
            }) catch continue;
            try self.sendMediaEventReply(conn, "STATS", channel, detail);
        }
        var end_buf: [default_reply_bytes]u8 = undefined;
        const end = std.fmt.bufPrint(&end_buf, "count={d}", .{n + nn}) catch return;
        try self.sendMediaEventReply(conn, "STATS-END", channel, end);
    }

    /// `MEDIA QUALITY <#chan>` — one latest sample per current member who has
    /// reported. Loss, RTT, chosen spatial layer, and target bitrate only.
    /// Ice credentials, SRTP keys, and any other keying material are not fields
    /// of the sample and are not copied into the reply.
    pub fn mediaQuality(self: *LinuxServer, conn: *ConnState, channel: []const u8) !void {
        var emitted: usize = 0;
        for (self.media_rooms.roster(channel)) |p| {
            const sample = self.media_rooms.qualityOf(channel, p.id.slice()) orelse continue;
            var buf: [default_reply_bytes]u8 = undefined;
            const detail = std.fmt.bufPrint(&buf, "{s} loss={d} rtt={d} spatial={d} bitrate={d}", .{
                p.id.slice(),
                sample.loss_pct,
                sample.rtt_ms,
                sample.spatial,
                sample.bitrate_kbps,
            }) catch continue;
            try self.sendMediaEventReply(conn, "QUALITY", channel, detail);
            emitted += 1;
        }
        var end_buf: [64]u8 = undefined;
        const end = std.fmt.bufPrint(&end_buf, "count={d}", .{emitted}) catch return;
        try self.sendMediaEventReply(conn, "QUALITY-END", channel, end);
    }

    /// `MEDIA QUEUE <#chan>` — raised-hand order, head first. Positions are not
    /// an input, and the reply is only the order the room can read.
    pub fn mediaQueue(self: *LinuxServer, conn: *ConnState, channel: []const u8) !void {
        var nicks: [media_room.max_participants][]const u8 = undefined;
        const n = self.media_rooms.copySpeakQueue(channel, &nicks);
        for (nicks[0..n], 0..) |speaker, i| {
            var buf: [default_reply_bytes]u8 = undefined;
            const detail = std.fmt.bufPrint(&buf, "{d} {s}", .{ i, speaker }) catch continue;
            try self.sendMediaEventReply(conn, "QUEUE", channel, detail);
        }
        var end_buf: [64]u8 = undefined;
        const end = std.fmt.bufPrint(&end_buf, "count={d}", .{n}) catch return;
        try self.sendMediaEventReply(conn, "QUEUE-END", channel, end);
    }

    pub fn mediaRoster(self: *LinuxServer, conn: *ConnState, channel: []const u8) !void {
        for (self.media_rooms.roster(channel)) |p| {
            var kinds_buf: [32]u8 = undefined;
            var n: usize = 0;
            inline for (.{ media_room.MediaKind.voice, .video, .screen }) |k| {
                if (p.joined.contains(k)) {
                    const name = media_room.kindName(k);
                    const mark: []const u8 = if (p.muted.contains(k)) "-" else if (p.speaking.contains(k)) "*" else "";
                    if (n != 0 and n < kinds_buf.len) {
                        kinds_buf[n] = ',';
                        n += 1;
                    }
                    for (mark) |c| {
                        if (n < kinds_buf.len) {
                            kinds_buf[n] = c;
                            n += 1;
                        }
                    }
                    if (n + name.len <= kinds_buf.len) {
                        @memcpy(kinds_buf[n .. n + name.len], name);
                        n += name.len;
                    }
                }
            }
            const breakout = self.media_rooms.breakoutOf(channel, p.id.slice());
            const pos = self.media_rooms.positionOf(channel, p.id.slice());
            const hand: []const u8 = if (self.media_rooms.handRaised(channel, p.id.slice())) "hand" else "-";
            var buf: [default_reply_bytes]u8 = undefined;
            const consent: u8 = if (self.media_rooms.hasConsent(channel, p.id.slice())) 1 else 0;
            const detail = if (self.media_rooms.participantProfileOf(channel, p.id.slice())) |prof| blk: {
                var caps_buf: [256]u8 = undefined;
                const caps = formatMediaCodecDetail(&caps_buf, prof.slice(), prof.fec) orelse break :blk std.fmt.bufPrint(&buf, "{s} {s} {s} {d} {d} {s} consent={d}", .{ p.id.slice(), kinds_buf[0..n], breakout, pos.x, pos.y, hand, consent }) catch continue;
                break :blk std.fmt.bufPrint(&buf, "{s} {s} {s} {d} {d} {s} {s} consent={d}", .{ p.id.slice(), kinds_buf[0..n], breakout, pos.x, pos.y, hand, caps, consent }) catch continue;
            } else std.fmt.bufPrint(&buf, "{s} {s} {s} {d} {d} {s} consent={d}", .{ p.id.slice(), kinds_buf[0..n], breakout, pos.x, pos.y, hand, consent }) catch continue;
            try self.sendMediaEventReply(conn, "ROSTER", channel, detail);
        }
        var end_buf: [default_reply_bytes]u8 = undefined;
        const end = std.fmt.bufPrint(&end_buf, "count={d}", .{self.media_rooms.roster(channel).len}) catch return;
        try self.sendMediaEventReply(conn, "ROSTER-END", channel, end);
    }

    fn destroyPolicyUndo(self: *LinuxServer, undo: *PolicyUndo) void {
        switch (undo.*) {
            .ward => |*snap| warden.deinitWardList(self.allocator, &snap.wards),
            .filter => |snap| {
                for (snap.patterns) |p| self.allocator.free(p);
                self.allocator.free(snap.patterns);
            },
            .class => |*snap| {
                if (snap.registry) |*reg| reg.deinit();
                snap.registry = null;
            },
            .ban => |snap| {
                for (snap.rows) |*row| {
                    self.allocator.free(row.channel);
                    self.allocator.free(row.mask);
                    self.allocator.free(row.setter);
                }
                self.allocator.free(snap.rows);
            },
        }
    }

    fn commitPolicy(self: *LinuxServer, undo: PolicyUndo) void {
        if (self.policy_undo) |*old| self.destroyPolicyUndo(old);
        const kind = std.meta.activeTag(undo);
        self.policy_undo = undo;
        const slot: *u32 = switch (kind) {
            .ward => &self.policy_gen_ward,
            .filter => &self.policy_gen_filter,
            .class => &self.policy_gen_class,
            .ban => &self.policy_gen_ban,
        };
        if (slot.* != std.math.maxInt(u32)) slot.* += 1;
        self.proof_policy_version = slot.*;
    }

    fn windowsPolicySnapshot(self: *LinuxServer) policy_checkpoint.SnapshotView {
        var view = policy_checkpoint.SnapshotView{ .generations = .{
            .ward = self.policy_gen_ward,
            .filter = self.policy_gen_filter,
            .class = self.policy_gen_class,
            .ban = self.policy_gen_ban,
            .proof = self.proof_policy_version,
        } };
        if (self.policy_undo) |*undo| {
            view.previous_generation = undo.generation();
            view.undo = switch (undo.*) {
                .ward => |*snap| .{ .ward = .{ .params = self.warden.params, .rows = snap.wards.items } },
                .filter => |*snap| .{ .filter = .{
                    .max_patterns = self.content_filter.cfg.max_patterns,
                    .max_pattern_len = self.content_filter.cfg.max_pattern_len,
                    .patterns = snap.patterns,
                } },
                .class => |*snap| .{ .class = if (snap.registry) |*registry| registry else null },
                .ban => |*snap| .{ .ban = snap.rows },
            };
        }
        return view;
    }

    fn windowsPolicyUndoFromOwned(owned: policy_checkpoint.OwnedUndo, generation: u32) PolicyUndo {
        return switch (owned) {
            .ward => |snap| .{ .ward = .{ .generation = generation, .wards = snap.rows } },
            .filter => |snap| .{ .filter = .{ .generation = generation, .patterns = snap.patterns } },
            .class => |registry| .{ .class = .{ .generation = generation, .registry = registry } },
            .ban => |rows| .{ .ban = .{ .generation = generation, .rows = rows } },
        };
    }

    fn snapshotWard(self: *LinuxServer) !PolicyUndo {
        return .{ .ward = .{
            .generation = self.policy_gen_ward,
            .wards = try self.warden.clonedWards(),
        } };
    }

    fn snapshotFilter(self: *LinuxServer) !PolicyUndo {
        return .{ .filter = .{
            .generation = self.policy_gen_filter,
            .patterns = try self.content_filter.clonedPatterns(),
        } };
    }

    fn snapshotClass(self: *LinuxServer) !PolicyUndo {
        const registry = if (self.config.class_registry) |*reg| try reg.clone() else null;
        return .{ .class = .{
            .generation = self.policy_gen_class,
            .registry = registry,
        } };
    }

    fn snapshotBan(self: *LinuxServer) !PolicyUndo {
        var rows: std.ArrayListUnmanaged(PolicyBanRow) = .empty;
        errdefer {
            for (rows.items) |*row| {
                self.allocator.free(row.channel);
                self.allocator.free(row.mask);
                self.allocator.free(row.setter);
            }
            rows.deinit(self.allocator);
        }
        var it = self.world.channelIterator();
        while (it.next()) |view| {
            const bans = self.world.bansOf(view.name) orelse continue;
            for (bans) |ban| {
                const channel = try self.allocator.dupe(u8, view.name);
                errdefer self.allocator.free(channel);
                const mask = try self.allocator.dupe(u8, ban.mask);
                errdefer self.allocator.free(mask);
                const setter = try self.allocator.dupe(u8, ban.setter);
                try rows.append(self.allocator, .{
                    .channel = channel,
                    .mask = mask,
                    .setter = setter,
                    .set_at = ban.set_at,
                });
            }
        }
        return .{ .ban = .{
            .generation = self.policy_gen_ban,
            .rows = try rows.toOwnedSlice(self.allocator),
        } };
    }

    fn restorePolicy(self: *LinuxServer, undo: *PolicyUndo) !void {
        switch (undo.*) {
            .ward => |*snap| self.warden.exchangeWards(&snap.wards),
            .filter => |snap| try self.content_filter.restorePatterns(snap.patterns),
            .class => |*snap| {
                if (self.reload_class_registry) |*old| old.deinit();
                if (snap.registry) |reg| {
                    self.reload_class_registry = reg;
                    self.config.class_registry = reg;
                    snap.registry = null;
                } else {
                    self.reload_class_registry = null;
                    self.config.class_registry = null;
                }
            },
            .ban => |snap| {
                var names: std.ArrayListUnmanaged([]u8) = .empty;
                defer {
                    for (names.items) |name| self.allocator.free(name);
                    names.deinit(self.allocator);
                }
                var it = self.world.channelIterator();
                while (it.next()) |view| {
                    const owned = try self.allocator.dupe(u8, view.name);
                    try names.append(self.allocator, owned);
                }
                for (names.items) |name| {
                    const bans = self.world.bansOf(name) orelse continue;
                    var masks: std.ArrayListUnmanaged([]u8) = .empty;
                    defer {
                        for (masks.items) |mask| self.allocator.free(mask);
                        masks.deinit(self.allocator);
                    }
                    for (bans) |ban| try masks.append(self.allocator, try self.allocator.dupe(u8, ban.mask));
                    for (masks.items) |mask| _ = self.world.removeBan(name, mask) catch {};
                }
                for (snap.rows) |row| {
                    _ = self.world.addBan(row.channel, row.mask, row.setter, row.set_at) catch {};
                }
            },
        }
    }

    fn rollbackPolicy(self: *LinuxServer) !void {
        if (self.policy_undo == null) return error.NothingToRollback;
        const kind = std.meta.activeTag(self.policy_undo.?);
        const generation = self.policy_undo.?.generation();
        try self.restorePolicy(&self.policy_undo.?);
        switch (kind) {
            .ward => self.policy_gen_ward = generation,
            .filter => self.policy_gen_filter = generation,
            .class => self.policy_gen_class = generation,
            .ban => self.policy_gen_ban = generation,
        }
        self.proof_policy_version = generation;
        self.destroyPolicyUndo(&self.policy_undo.?);
        self.policy_undo = null;
    }

    /// Install a finished connection-class table and number that generation.
    /// The server takes ownership of `new_reg`. REHASH uses this path.
    fn installClassRegistry(self: *LinuxServer, new_reg: conn_class.Registry) void {
        var policy_snap: ?PolicyUndo = self.snapshotClass() catch null;
        defer if (policy_snap) |*snap| self.destroyPolicyUndo(snap);
        if (self.reload_class_registry) |*old| old.deinit();
        self.reload_class_registry = new_reg;
        self.config.class_registry = new_reg;
        if (policy_snap) |snap| {
            self.commitPolicy(snap);
            policy_snap = null;
            _ = self.recordOperAudit(self.serverName(), .other, "class", "class replace");
        }
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const conn = &slot.value;
                if (conn.s2s == null and conn.s2s_secured == null) continue;
                self.assignConnClass(conn);
            }
        }
    }

    /// `POLICY` lists ward, filter, class, and ban generations.
    /// `POLICY ROLLBACK` restores the last of those changes. The ProofMark
    /// version is the generation that is live after the command.
    pub fn handlePolicy(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.isOper()) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied- You're not an IRC operator");
            return;
        }
        const sub = if (parsed.param_count >= 1) parsed.paramSlice()[0] else "LIST";
        if (std.ascii.eqlIgnoreCase(sub, "ROLLBACK")) {
            if (self.policy_undo == null) {
                try self.noticeTo(conn, "POLICY: nothing to roll back");
                return;
            }
            const kind = std.meta.activeTag(self.policy_undo.?);
            self.rollbackPolicy() catch {
                try self.noticeTo(conn, "POLICY: rollback failed");
                return;
            };
            _ = self.recordOperAudit(conn.session.displayName(), .other, @tagName(kind), "policy rollback");
            var buf: [default_reply_bytes]u8 = undefined;
            const note = std.fmt.bufPrint(&buf, "POLICY: rolled {s} back to generation {d}", .{
                @tagName(kind),
                self.proof_policy_version,
            }) catch "POLICY: rolled back";
            try self.noticeTo(conn, note);
            return;
        }
        var buf: [default_reply_bytes]u8 = undefined;
        const note = std.fmt.bufPrint(&buf, "POLICY: ward={d} filter={d} class={d} ban={d}", .{
            self.policy_gen_ward,
            self.policy_gen_filter,
            self.policy_gen_class,
            self.policy_gen_ban,
        }) catch return;
        try self.noticeTo(conn, note);
    }

    /// `FILTER ADD|DEL|LIST [pattern]` — oper-only Koshi content-filter control.
    /// ADD/DEL manage case-insensitive substring patterns; LIST reports them.
    /// Matching messages from non-opers are blocked in the message path.
    pub fn handleFilter(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!conn.session.isOper()) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied- You're not an IRC operator");
            return;
        }
        const sub = if (parsed.param_count >= 1) parsed.paramSlice()[0] else "LIST";
        if (std.ascii.eqlIgnoreCase(sub, "LIST")) {
            var buf: [default_reply_bytes]u8 = undefined;
            for (self.content_filter.list(), 0..) |p, i| {
                const line = std.fmt.bufPrint(&buf, "FILTER LIST #{d} {s}", .{ i + 1, p }) catch continue;
                try self.noticeTo(conn, line);
            }
            var end_buf: [default_reply_bytes]u8 = undefined;
            const end = std.fmt.bufPrint(&end_buf, "FILTER: End of filter list ({d})", .{self.content_filter.list().len}) catch return;
            try self.noticeTo(conn, end);
            return;
        }
        if (parsed.param_count < 2 or parsed.paramSlice()[1].len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"FILTER"}, "Usage: FILTER <ADD|DEL|LIST> [pattern]");
            return;
        }
        const pattern = parsed.paramSlice()[1];
        if (std.ascii.eqlIgnoreCase(sub, "ADD")) {
            var policy_snap: ?PolicyUndo = self.snapshotFilter() catch null;
            defer if (policy_snap) |*snap| self.destroyPolicyUndo(snap);
            const ok = self.content_filter.add(pattern) catch {
                try self.failReply(conn, "FILTER", "TEMPORARILY_UNAVAILABLE", "Filter store error");
                return;
            };
            if (!ok) {
                try self.failReply(conn, "FILTER", "INVALID_PATTERN", "Pattern empty, too long, full, or duplicate");
                return;
            }
            if (policy_snap) |snap| {
                self.commitPolicy(snap);
                policy_snap = null;
            }
            _ = self.recordOperAudit(conn.session.displayName(), .other, pattern, "filter add");
            self.snapshotKoshi();
            try self.noticeTo(conn, "FILTER: pattern added");
        } else if (std.ascii.eqlIgnoreCase(sub, "DEL")) {
            var policy_snap: ?PolicyUndo = self.snapshotFilter() catch null;
            defer if (policy_snap) |*snap| self.destroyPolicyUndo(snap);
            const removed = self.content_filter.remove(pattern) catch false;
            if (!removed) {
                try self.failReply(conn, "FILTER", "NO_SUCH_PATTERN", "No such filter pattern");
                return;
            }
            if (policy_snap) |snap| {
                self.commitPolicy(snap);
                policy_snap = null;
            }
            _ = self.recordOperAudit(conn.session.displayName(), .other, pattern, "filter del");
            self.snapshotKoshi();
            try self.noticeTo(conn, "FILTER: pattern removed");
        } else {
            try self.failReply(conn, "FILTER", "INVALID_SUBCOMMAND", "Use ADD, DEL, or LIST");
        }
    }

    /// `PRIVS` — report the caller's operator class and privilege set
    /// (RPL_PRIVS 270). Re-derived from the oper registry by account, so it
    /// always reflects the current config binding.
    /// Require a specific operator privilege for a sensitive action. On failure
    /// emits ERR_NOPRIVILEGES and returns false. The coarse oper gate is already
    /// enforced by the registry (access=.oper); this refines it per-action.
    pub fn requirePriv(self: *LinuxServer, conn: *ConnState, privilege: oper_mod.Privilege) bool {
        _ = self;
        if (conn.session.hasPriv(privilege)) return true;
        var nb: [128]u8 = undefined;
        const msg = std.fmt.bufPrint(&nb, "Permission denied: requires the '{s}' operator privilege", .{@tagName(privilege)}) catch "Permission denied";
        queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, msg) catch {};
        return false;
    }

    pub fn handlePrivs(self: *LinuxServer, conn: *ConnState) !void {
        _ = self;
        if (!conn.session.isOper()) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied- You're not an IRC operator");
            return;
        }
        // Report the reconciled projection stored on the session.
        var buf: [default_reply_bytes]u8 = undefined;
        var n: usize = 0;
        var it = conn.session.oper_priv.set.iterator();
        while (it.next()) |p| {
            const name = @tagName(p);
            if (n != 0 and n < buf.len) {
                buf[n] = ' ';
                n += 1;
            }
            if (n + name.len <= buf.len) {
                @memcpy(buf[n .. n + name.len], name);
                n += name.len;
            }
        }
        const class = conn.session.operClass();
        try queueNumeric(conn, .RPL_PRIVS, &.{ conn.session.displayName(), if (class.len > 0) class else "operator" }, buf[0..n]);
    }

    /// `VHOST <newhost>` — oper-only visible-host override. Updates the caller's
    /// visible host and broadcasts a native CHGHOST to common-channel members who
    /// negotiated the chghost cap (others see the new host on the next message).
    pub fn handleVhost(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1 or parsed.paramSlice()[0].len == 0) {
            return self.vhostList(id, conn); // bare VHOST shows the wardrobe
        }
        const p = parsed.paramSlice();
        // Guise wardrobe (self-service): LIST/USE/OFF/CLAIM, plus REQUEST to ask.
        if (std.ascii.eqlIgnoreCase(p[0], "LIST")) {
            return self.vhostList(id, conn);
        } else if (std.ascii.eqlIgnoreCase(p[0], "USE")) {
            return self.handleVhostUse(id, conn, p);
        } else if (std.ascii.eqlIgnoreCase(p[0], "OFF")) {
            return self.handleVhostOff(id, conn);
        } else if (std.ascii.eqlIgnoreCase(p[0], "CLAIM")) {
            return self.handleVhostClaim(id, conn, p);
        } else if (std.ascii.eqlIgnoreCase(p[0], "REQUEST")) {
            return self.handleVhostRequest(conn, p);
        } else if (std.ascii.eqlIgnoreCase(p[0], "OFFERLIST")) {
            return self.handleVhostOfferList(conn);
        } else if (std.ascii.eqlIgnoreCase(p[0], "APPROVE") or std.ascii.eqlIgnoreCase(p[0], "DENY")) {
            return self.handleVhostReview(id, conn, p);
        } else if (std.ascii.eqlIgnoreCase(p[0], "OFFER")) {
            return self.handleVhostOffer(conn, p);
        } else if (std.ascii.eqlIgnoreCase(p[0], "SET")) {
            return self.handleVhostSet(conn, p);
        }
        // Bare `VHOST <host>` — oper immediate self-set (kept for convenience).
        if (!conn.session.isOper()) {
            try self.noticeTo(conn, "Usage: VHOST LIST|USE <name>|OFF|CLAIM <host>|REQUEST <host>|OFFERLIST");
            return;
        }
        const new_host = parsed.paramSlice()[0];
        const user = conn.session.username();
        chghost.validateHost(new_host) catch {
            try self.failReply(conn, "VHOST", "INVALID_HOST", "Invalid host");
            return;
        };

        // Build the CHGHOST line from the OLD prefix before mutating the host.
        var prefix_buf: [256]u8 = undefined;
        const old_prefix = clientPrefix(conn, &prefix_buf) catch return;
        // old_prefix is nick!user@oldhost; split it back into a chghost.Prefix.
        const bang = std.mem.indexOfScalar(u8, old_prefix, '!') orelse return;
        const at = std.mem.indexOfScalarPos(u8, old_prefix, bang + 1, '@') orelse return;
        const pfx = chghost.Prefix{
            .nick = old_prefix[0..bang],
            .user = old_prefix[bang + 1 .. at],
            .host = old_prefix[at + 1 ..],
        };
        var line_buf: [default_reply_bytes]u8 = undefined;
        const body = chghost.buildChghostLine(&line_buf, pfx, user, new_host) catch {
            try self.failReply(conn, "VHOST", "INVALID_HOST", "Invalid host");
            return;
        };
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "{s}\r\n", .{body}) catch return;

        // Apply the new visible host, then fan the CHGHOST out.
        conn.session.setVisibleHost(new_host);
        try self.notifyCommonChannels(id, msg, .chghost, id, conn.session.displayName());
        if (conn.session.hasCap(.chghost)) try appendToConn(conn, msg);
        var note_buf: [default_reply_bytes]u8 = undefined;
        const note = std.fmt.bufPrint(&note_buf, ":{s} NOTICE {s} :Your host is now {s}\r\n", .{ self.serverName(), conn.session.displayName(), new_host }) catch return;
        try emitReplyLine(conn, note);
    }

    /// `VHOST REQUEST <host>` — a logged-in user asks for a vhost; queued for oper
    /// review. No effect until an oper APPROVEs.
    pub fn handleVhostRequest(self: *LinuxServer, conn: *ConnState, p: []const []const u8) !void {
        const account = conn.session.account() orelse {
            try self.failReply(conn, "VHOST", "ACCOUNT_REQUIRED", "Log in before requesting a vhost");
            return;
        };
        if (p.len < 2 or p[1].len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"VHOST"}, "Usage: VHOST REQUEST <host>");
            return;
        }
        const want = p[1];
        chghost.validateHost(want) catch {
            try self.failReply(conn, "VHOST", "INVALID_HOST", "Invalid host");
            return;
        };
        self.host_requests.submit(account, want, self.nowMs()) catch {
            try self.failReply(conn, "VHOST", "TEMPORARILY_UNAVAILABLE", "Could not queue request");
            return;
        };
        try self.noticeTo(conn, "VHOST request submitted; pending operator approval");
    }

    /// `VHOST LIST|APPROVE <account>|DENY <account> [:reason]` — oper review side.
    pub fn handleVhostReview(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, p: []const []const u8) !void {
        _ = id;
        if (!conn.session.isOper()) {
            try queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied- You're not an IRC operator");
            return;
        }
        if (std.ascii.eqlIgnoreCase(p[0], "LIST")) {
            var buf: [128]host_request_mod.Request = undefined;
            const pending = self.host_requests.pendingList(&buf) catch &.{};
            for (pending) |r| {
                var b: [default_reply_bytes]u8 = undefined;
                const line = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :VHOST pending {s} -> {s}\r\n", .{ self.serverName(), conn.session.displayName(), r.account, r.vhost }) catch continue;
                try emitReplyLine(conn, line);
            }
            try self.noticeTo(conn, "VHOST: end of pending list");
            return;
        }
        if (p.len < 2 or p[1].len == 0) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"VHOST"}, "Usage: VHOST APPROVE|DENY <account> [:reason]");
            return;
        }
        const account = p[1];
        if (std.ascii.eqlIgnoreCase(p[0], "DENY")) {
            const reason = if (p.len >= 3) p[2] else "denied";
            self.host_requests.deny(account, reason, self.nowMs()) catch {
                try self.noticeTo(conn, "VHOST: no such pending request");
                return;
            };
            try self.noticeTo(conn, "VHOST request denied");
            return;
        }
        // APPROVE: record approval, then apply to any online sessions of the
        // account immediately (offline accounts pick it up on next login).
        const req = self.host_requests.get(account) orelse {
            try self.noticeTo(conn, "VHOST: no such pending request");
            return;
        };
        self.host_requests.approve(account, self.nowMs()) catch {
            try self.noticeTo(conn, "VHOST: could not approve");
            return;
        };
        var hbuf: [128]u8 = undefined;
        const host = std.fmt.bufPrint(&hbuf, "{s}", .{req.vhost}) catch return;
        // Record the approved host as a switchable "granted" persona.
        self.grantDurablePersona(account, "granted", host, .granted) catch {};
        _ = self.applyVhostToAccount(account, host);
        try self.noticeTo(conn, "VHOST approved and applied");
    }

    /// `VHOST LIST` (or bare VHOST) — show the caller's persona wardrobe and the
    /// operator-published offer templates they can CLAIM.
    fn vhostList(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) !void {
        _ = id;
        if (conn.session.account()) |account| {
            for (self.guises.personas(account)) |p| {
                var b: [default_reply_bytes]u8 = undefined;
                const line = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :VHOST persona {s} = {s} ({s})\r\n", .{ self.serverName(), conn.session.displayName(), p.name, p.host, p.source.token() }) catch continue;
                try emitReplyLine(conn, line);
            }
        }
        for (self.guises.offerList()) |o| {
            var b: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :VHOST offer {s} :{s}\r\n", .{ self.serverName(), conn.session.displayName(), o.template, o.label }) catch continue;
            try emitReplyLine(conn, line);
        }
        try self.noticeTo(conn, "VHOST: USE <name> to wear a persona, CLAIM <host> for an offer, REQUEST <host> to ask");
    }

    /// `VHOST USE <name>` — instantly wear one of your granted personas.
    pub fn handleVhostUse(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, p: []const []const u8) !void {
        const account = conn.session.account() orelse return self.failReply(conn, "VHOST", "ACCOUNT_REQUIRED", "Log in to use personas");
        if (p.len < 2 or p[1].len == 0) return self.noticeTo(conn, "Usage: VHOST USE <name>");
        const persona = self.guises.find(account, p[1]) orelse return self.noticeTo(conn, "VHOST: no such persona (try VHOST LIST)");
        try applyVhostLine(self, id, conn, persona.host);
    }

    /// `VHOST OFF` — drop the active vhost, restoring the connection's host.
    pub fn handleVhostOff(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) !void {
        var hb: [128]u8 = undefined;
        const real = conn.session.realHost();
        const host = std.fmt.bufPrint(&hb, "{s}", .{real}) catch return;
        try applyVhostLine(self, id, conn, host);
    }

    /// `VHOST CLAIM <host>` — self-service a host matching an operator offer
    /// template; it becomes a `.claimed` persona and is worn immediately.
    pub fn handleVhostClaim(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, p: []const []const u8) !void {
        const account = conn.session.account() orelse return self.failReply(conn, "VHOST", "ACCOUNT_REQUIRED", "Log in to claim a vhost");
        if (p.len < 2 or p[1].len == 0) return self.noticeTo(conn, "Usage: VHOST CLAIM <host>");
        const host = p[1];
        chghost.validateHost(host) catch return self.failReply(conn, "VHOST", "INVALID_HOST", "Invalid host");
        _ = self.claimDurablePersona(account, host) catch |err| switch (err) {
            // Self-service CLAIM is account-bound: a user may only claim a host
            // that spells their own account, and not one another account wears.
            error.NotYours => return self.failReply(conn, "VHOST", "HOST_NOT_YOURS", "You may only claim a vhost whose leading label is your account name"),
            error.HostClaimedByOther => return self.failReply(conn, "VHOST", "HOST_TAKEN", "That host is already claimed by another account"),
            else => return self.noticeTo(conn, "VHOST: no operator offer matches that host"),
        };
        try applyVhostLine(self, id, conn, host);
    }

    /// `VHOST OFFERLIST` — show offer templates (any user).
    pub fn handleVhostOfferList(self: *LinuxServer, conn: *ConnState) !void {
        for (self.guises.offerList()) |o| {
            var b: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&b, ":{s} NOTICE {s} :VHOST offer {s} :{s}\r\n", .{ self.serverName(), conn.session.displayName(), o.template, o.label }) catch continue;
            try emitReplyLine(conn, line);
        }
        try self.noticeTo(conn, "VHOST: end of offer list");
    }

    /// `VHOST OFFER <template> [:label]` — oper publishes a claimable template.
    pub fn handleVhostOffer(self: *LinuxServer, conn: *ConnState, p: []const []const u8) !void {
        if (!conn.session.isOper()) return queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied- You're not an IRC operator");
        if (p.len < 2 or p[1].len == 0) return self.noticeTo(conn, "Usage: VHOST OFFER <template> [:label]");
        const label = if (p.len >= 3) p[2] else "vhost offer";
        self.addDurableOffer(p[1], label) catch return self.noticeTo(conn, "VHOST: could not add offer (duplicate or limit)");
        var b: [default_reply_bytes]u8 = undefined;
        const note = std.fmt.bufPrint(&b, "VHOST OFFER {s}", .{p[1]}) catch return;
        try self.publishOperEvent(.oper_action, .notice, note);
    }

    /// `VHOST SET <account> <host> [name]` — oper assigns a fully custom vhost to
    /// an account as a `.granted` persona, applied live. The robust escape hatch
    /// for hosts no offer template covers.
    pub fn handleVhostSet(self: *LinuxServer, conn: *ConnState, p: []const []const u8) !void {
        if (!conn.session.isOper()) return queueNumeric(conn, .ERR_NOPRIVILEGES, &.{}, "Permission Denied- You're not an IRC operator");
        if (p.len < 3 or p[1].len == 0 or p[2].len == 0) return self.noticeTo(conn, "Usage: VHOST SET <account> <host> [name]");
        const account = p[1];
        const host = p[2];
        const name = if (p.len >= 4) p[3] else "oper";
        chghost.validateHost(host) catch return self.failReply(conn, "VHOST", "INVALID_HOST", "Invalid host");
        self.grantDurablePersona(account, name, host, .granted) catch return self.noticeTo(conn, "VHOST: could not set (limit or invalid)");
        _ = self.applyVhostToAccount(account, host);
        var b: [default_reply_bytes]u8 = undefined;
        const note = std.fmt.bufPrint(&b, "VHOST SET {s} -> {s}", .{ account, host }) catch return;
        try self.publishOperEvent(.oper_action, .notice, note);
        try self.noticeTo(conn, "VHOST set and applied");
    }

    /// On login, apply (and consume) an approved vhost request for the account.
    fn maybeApplyApprovedVhost(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) void {
        const account = conn.session.account() orelse return;
        const req = self.host_requests.get(account) orelse return;
        if (req.status != .approved) return;
        var hbuf: [128]u8 = undefined;
        const host = std.fmt.bufPrint(&hbuf, "{s}", .{req.vhost}) catch return;
        _ = id;
        if (!self.applyVhostToAccount(account, host)) return;
        if (self.host_requests.take(account)) |owned| {
            var retired = owned;
            retired.deinit(self.allocator);
        }
    }

    /// Apply `new_host` to every online session of `account` (CHGHOST fan-out).
    fn applyVhostToAccount(self: *LinuxServer, account: []const u8, new_host: []const u8) bool {
        // Account vhost approval is account-wide, while physical attachments
        // are sharded. Registration runs under the completion-wide writer lock,
        // so walk every reactor and persist the mutation for each exact client.
        var all_applied = true;
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                const c = entry.value;
                const acct = c.session.account() orelse continue;
                if (!std.ascii.eqlIgnoreCase(acct, account)) continue;
                applyVhostLine(self, entry.id, c, new_host) catch {};
                // applyVhostLine mutates before fan-out/output. Send pressure
                // can therefore report failure after the host is already live;
                // persist that mutation instead of skipping the portable row.
                if (!std.mem.eql(u8, c.session.host(), new_host)) {
                    all_applied = false;
                    continue;
                }
                if (!self.commitPortableSessionMutation(entry.id, c)) all_applied = false;
            }
        }
        return all_applied;
    }

    /// When `[cloak] account_cloak` is on, (re)apply the friendly
    /// `<account>.users.<suffix>` host after a post-registration login and fan the
    /// resulting CHGHOST to common channels. Pre-registration logins are covered
    /// by the registration-time `applyVisibleHost`, so this only fires once the
    /// client is registered (and no-ops when the host already matches, so a
    /// re-IDENTIFY to the same account does not emit a redundant CHGHOST).
    fn maybeApplyAccountCloak(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState) void {
        if (!self.config.cloak_account) return;
        if (self.config.cloak_key == null) return;
        if (!conn.session.registered()) return;
        const acct = conn.session.account() orelse return;
        var cbuf: [cloak.max_cloak_len]u8 = undefined;
        const ac = cloak.cloakAccount(&cbuf, acct, self.config.cloak_suffix) catch return;
        if (std.mem.eql(u8, conn.session.host(), ac)) return;
        applyVhostLine(self, id, conn, ac) catch {};
    }

    /// Set a client's visible host and fan a CHGHOST out to common channels.
    fn applyVhostLine(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, new_host: []const u8) !void {
        var prefix_buf: [256]u8 = undefined;
        const old_prefix = clientPrefix(conn, &prefix_buf) catch return;
        const bang = std.mem.indexOfScalar(u8, old_prefix, '!') orelse return;
        const at = std.mem.indexOfScalarPos(u8, old_prefix, bang + 1, '@') orelse return;
        const pfx = chghost.Prefix{ .nick = old_prefix[0..bang], .user = old_prefix[bang + 1 .. at], .host = old_prefix[at + 1 ..] };
        var line_buf: [default_reply_bytes]u8 = undefined;
        const body = chghost.buildChghostLine(&line_buf, pfx, conn.session.username(), new_host) catch return;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "{s}\r\n", .{body}) catch return;
        conn.session.setVisibleHost(new_host);
        try self.notifyCommonChannels(id, msg, .chghost, id, conn.session.displayName());
        if (conn.session.hasCap(.chghost)) try appendToConn(conn, msg);
        // Standing OBSERVE feed: fire the host-change action (previously never
        // emitted) so an oper watching a nick sees vhost/cloak changes.
        self.notifyObservers(.host_change, observeSubject(conn, new_host));
        var nb: [default_reply_bytes]u8 = undefined;
        const note = std.fmt.bufPrint(&nb, ":{s} NOTICE {s} :Your host is now {s}\r\n", .{ self.serverName(), conn.session.displayName(), new_host }) catch return;
        try emitReplyLine(conn, note);
    }

    /// Emit an IRCv3 `FAIL <command> <code> :<reason>` standard reply.
    pub fn failReply(self: *LinuxServer, conn: *ConnState, command: []const u8, code: []const u8, reason: []const u8) !void {
        // CWE-93 (CRLF/command injection): these FAIL/NOTICE builders reflect
        // caller-supplied fields onto the wire WITHOUT the `ReplyCtx`
        // `requireNoControlBytes` guard that numeric/message replies enforce.
        // Some call sites pass user-influenced bytes (e.g. a reflected command
        // verb), so a raw CR/LF here would inject a forged IRC line that the
        // peer/relay parses as a separate message. Fail closed: if any reflected
        // field carries a control byte, drop the reply rather than emit an
        // injectable line. Legitimate (control-byte-free) replies are unchanged.
        if (dispatch.hasControlByte(command) or dispatch.hasControlByte(code) or dispatch.hasControlByte(reason)) return;
        if (!conn.session.hasCap(.standard_replies)) {
            var notice_buf: [default_reply_bytes]u8 = undefined;
            const notice = std.fmt.bufPrint(&notice_buf, "FAIL {s} {s}: {s}", .{ command, code, reason }) catch return;
            try self.noticeTo(conn, notice);
            return;
        }
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, "FAIL {s} {s} :{s}\r\n", .{ command, code, reason }) catch return;
        try appendToConn(conn, line);
    }

    /// Emit a retryable IRCv3 `WARN`. Unlike `FAIL`, clients must retain the
    /// credential/state needed to retry the operation.
    fn warnReply(self: *LinuxServer, conn: *ConnState, command: []const u8, code: []const u8, reason: []const u8) !void {
        if (dispatch.hasControlByte(command) or dispatch.hasControlByte(code) or dispatch.hasControlByte(reason)) return;
        if (!conn.session.hasCap(.standard_replies)) {
            var notice_buf: [default_reply_bytes]u8 = undefined;
            const notice = std.fmt.bufPrint(&notice_buf, "WARN {s} {s}: {s}", .{ command, code, reason }) catch return;
            try self.noticeTo(conn, notice);
            return;
        }
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, "WARN {s} {s} :{s}\r\n", .{ command, code, reason }) catch return;
        try appendToConn(conn, line);
    }

    /// Emit an advisory IRCv3 `NOTE` standard reply. `NOTE` carries information
    /// about an operation that SUCCEEDED, so it must never be the only signal a
    /// client needs to act on. Same CWE-93 fail-closed guard as `failReply`.
    fn noteReply(self: *LinuxServer, conn: *ConnState, command: []const u8, code: []const u8, reason: []const u8) !void {
        if (dispatch.hasControlByte(command) or dispatch.hasControlByte(code) or dispatch.hasControlByte(reason)) return;
        if (!conn.session.hasCap(.standard_replies)) {
            var notice_buf: [default_reply_bytes]u8 = undefined;
            const notice = std.fmt.bufPrint(&notice_buf, "NOTE {s} {s}: {s}", .{ command, code, reason }) catch return;
            try self.noticeTo(conn, notice);
            return;
        }
        var buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, "NOTE {s} {s} :{s}\r\n", .{ command, code, reason }) catch return;
        try appendToConn(conn, line);
    }

    pub fn overrideActive(conn: *const ConnState) bool {
        return conn.session.hasUmode(.override) and conn.session.hasPriv(.oper_override);
    }

    pub fn auditOverrideUse(self: *LinuxServer, conn: *const ConnState, action: []const u8, target: []const u8, detail: []const u8) void {
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "override {s} by {s} on {s}: {s}", .{
            action,
            conn.session.displayName(),
            target,
            detail,
        }) catch return;
        const proof_id = self.recordOperAudit(conn.session.displayName(), .other, target, msg);
        var event_buf: [default_reply_bytes]u8 = undefined;
        const event_msg = if (proof_id) |pid|
            std.fmt.bufPrint(&event_buf, "{s} proof={s}", .{ msg, pid[0..] }) catch msg
        else
            msg;
        self.publishOperEvent(.oper_action, .notice, event_msg) catch {};
        self.publishOperEvent(.security, .notice, event_msg) catch {};
    }

    fn operProofEvidence(
        self: *LinuxServer,
        ts: i64,
        oper: []const u8,
        action: svc_operaudit.Action,
        target: []const u8,
        reason: []const u8,
        id_out: *[proofmark.proof_id_hex_len]u8,
        sig_out: *[@sizeOf(proofmark.Signature) * 2]u8,
        pub_out: *[@sizeOf(proofmark.PublicKey) * 2]u8,
    ) ?svc_operaudit.ProofEvidence {
        const kp = self.meshSignKey() orelse return null;
        const reason_hash = proofmark.reasonHash(reason);
        const proof = proofmark.Proof{
            .actor = oper,
            .target = target,
            .action = action.proofCode(),
            .reason_hash = reason_hash,
            .policy_version = self.proof_policy_version,
            .issued_ms = ts,
            .expiry_ms = std.math.maxInt(i64),
        };
        const sig = proofmark.sign(proof, kp.secret_key.toBytes()) catch return null;
        const proof_id = proofmark.proofIdHex(proof, sig, id_out) catch return null;
        const sig_hex = std.fmt.bytesToHex(sig, .lower);
        @memcpy(sig_out, &sig_hex);
        const pub_hex = std.fmt.bytesToHex(kp.public_key.toBytes(), .lower);
        @memcpy(pub_out, &pub_hex);
        return .{
            .id = proof_id,
            .signature = sig_out[0..],
            .public_key = pub_out[0..],
            .reason_hash = reason_hash,
            .policy_version = proof.policy_version,
            .action = proof.action,
            .issued_ms = proof.issued_ms,
            .expiry_ms = proof.expiry_ms,
        };
    }

    /// Append one privileged action to the oper-action audit ring. When this node
    /// has a mesh signing key, attach a ProofMark id committing to actor, action,
    /// target, reason hash, policy version, and timestamp. Best-effort: an
    /// allocation/signing failure drops proof metadata or the record rather than
    /// faulting the action's hot path.
    pub fn recordOperAudit(self: *LinuxServer, oper: []const u8, action: svc_operaudit.Action, target: []const u8, reason: []const u8) ?[proofmark.proof_id_hex_len]u8 {
        const ts = self.nowMs();
        var proof_id_buf: [proofmark.proof_id_hex_len]u8 = undefined;
        var proof_sig_buf: [@sizeOf(proofmark.Signature) * 2]u8 = undefined;
        var proof_pub_buf: [@sizeOf(proofmark.PublicKey) * 2]u8 = undefined;
        const proof = self.operProofEvidence(ts, oper, action, target, reason, &proof_id_buf, &proof_sig_buf, &proof_pub_buf);
        _ = self.oper_audit.recordWithProofEvidence(ts, oper, action, target, reason, proof) catch return null;
        self.sealProofChain();
        self.persistProofChain();
        if (proof) |p| {
            if (p.id.len != proofmark.proof_id_hex_len) return null;
            var out: [proofmark.proof_id_hex_len]u8 = undefined;
            @memcpy(out[0..], p.id);
            return out;
        }
        return null;
    }

    fn proofHashHex(hash: proofmark.Digest, out: *[proofmark.proof_id_hex_len]u8) []const u8 {
        const hex = std.fmt.bytesToHex(hash, .lower);
        @memcpy(out, &hex);
        return out[0..];
    }

    fn auditProofVerified(entry: *const svc_operaudit.Entry) bool {
        if (entry.proof_id.len != proofmark.proof_id_hex_len) return false;
        if (entry.proof_signature.len != @sizeOf(proofmark.Signature) * 2) return false;
        if (entry.proof_public_key.len != @sizeOf(proofmark.PublicKey) * 2) return false;
        var sig: proofmark.Signature = undefined;
        var public_key: proofmark.PublicKey = undefined;
        _ = std.fmt.hexToBytes(&sig, entry.proof_signature) catch return false;
        _ = std.fmt.hexToBytes(&public_key, entry.proof_public_key) catch return false;
        const proof = proofmark.Proof{
            .actor = entry.oper,
            .target = entry.target,
            .action = entry.proof_action,
            .reason_hash = entry.proof_reason_hash,
            .policy_version = entry.proof_policy_version,
            .issued_ms = entry.proof_issued_ms,
            .expiry_ms = entry.proof_expiry_ms,
        };
        if (!proofmark.verify(proof, sig, public_key)) return false;
        var id_buf: [proofmark.proof_id_hex_len]u8 = undefined;
        const id = proofmark.proofIdHex(proof, sig, &id_buf) catch return false;
        return std.mem.eql(u8, id, entry.proof_id);
    }

    pub fn appendAuditEventPayload(self: *LinuxServer, conn: *ConnState, payload: []const u8) !void {
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = std.fmt.bufPrint(&line_buf, ":{s} EVENT {s} AUDIT {s}\r\n", .{ self.serverName(), conn.session.displayName(), payload }) catch return;
        try appendToConn(conn, line);
    }

    fn writeAuditEntryJson(w: *std.Io.Writer, entry: *const svc_operaudit.Entry) !void {
        try w.print("{{\"type\":\"audit-entry\",\"seq\":{d},\"ts\":{d},\"oper\":", .{ entry.seq, entry.ts });
        try writeJsonEscaped(w, entry.oper);
        try w.writeAll(",\"action\":");
        try writeJsonEscaped(w, entry.action.label());
        try w.writeAll(",\"target\":");
        try writeJsonEscaped(w, entry.target);
        try w.writeAll(",\"reason\":");
        try writeJsonEscaped(w, entry.reason);
        try w.writeAll(",\"proof_id\":");
        if (entry.proof_id.len != 0) {
            try writeJsonEscaped(w, entry.proof_id);
        } else {
            try w.writeAll("null");
        }
        try w.print(",\"proof_action\":{d}}}", .{entry.proof_action});
    }

    pub fn appendAuditEntryJson(self: *LinuxServer, conn: *ConnState, entry: *const svc_operaudit.Entry) !void {
        var payload: [default_reply_bytes]u8 = undefined;
        var w = std.Io.Writer.fixed(&payload);
        try writeAuditEntryJson(&w, entry);
        try self.appendAuditEventPayload(conn, w.buffered());
    }

    fn appendAuditProofJson(self: *LinuxServer, conn: *ConnState, proof_id: []const u8) !void {
        const entry = self.oper_audit.findByProofId(proof_id) orelse {
            var payload: [512]u8 = undefined;
            var w = std.Io.Writer.fixed(&payload);
            try w.writeAll("{\"type\":\"audit-proof\",\"found\":false,\"proof_id\":");
            try writeJsonEscaped(&w, proof_id);
            try w.writeByte('}');
            try self.appendAuditEventPayload(conn, w.buffered());
            return;
        };

        if (entry.proof_signature.len == 0 or entry.proof_public_key.len == 0) {
            var payload: [default_reply_bytes]u8 = undefined;
            var w = std.Io.Writer.fixed(&payload);
            try w.writeAll("{\"type\":\"audit-proof\",\"found\":true,\"has_evidence\":false,\"proof_id\":");
            try writeJsonEscaped(&w, proof_id);
            try w.print(",\"seq\":{d}}}", .{entry.seq});
            try self.appendAuditEventPayload(conn, w.buffered());
            return;
        }

        const verified = auditProofVerified(entry);
        var hash_buf: [proofmark.proof_id_hex_len]u8 = undefined;
        const reason_hash = proofHashHex(entry.proof_reason_hash, &hash_buf);
        var payload: [default_reply_bytes]u8 = undefined;
        var w = std.Io.Writer.fixed(&payload);
        try w.print("{{\"type\":\"audit-proof\",\"found\":true,\"has_evidence\":true,\"valid\":{s},\"seq\":{d},\"proof_id\":", .{
            if (verified) "true" else "false",
            entry.seq,
        });
        try writeJsonEscaped(&w, entry.proof_id);
        try w.writeAll(",\"actor\":");
        try writeJsonEscaped(&w, entry.oper);
        try w.writeAll(",\"action\":");
        try writeJsonEscaped(&w, entry.action.label());
        try w.print(",\"proof_action\":{d},\"target\":", .{entry.proof_action});
        try writeJsonEscaped(&w, entry.target);
        try w.print(",\"policy\":{d},\"issued_ms\":{d},\"expiry_ms\":{d},\"reason_hash\":", .{
            entry.proof_policy_version,
            entry.proof_issued_ms,
            entry.proof_expiry_ms,
        });
        try writeJsonEscaped(&w, reason_hash);
        try w.writeAll(",\"public_key\":");
        try writeJsonEscaped(&w, entry.proof_public_key);
        try w.writeAll(",\"signature\":");
        try writeJsonEscaped(&w, entry.proof_signature);
        try w.writeByte('}');
        try self.appendAuditEventPayload(conn, w.buffered());
    }

    pub fn handleAuditProof(self: *LinuxServer, conn: *ConnState, proof_id: []const u8, json: bool) !void {
        if (json) return self.appendAuditProofJson(conn, proof_id);
        const entry = self.oper_audit.findByProofId(proof_id) orelse {
            var buf: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&buf, ":{s} EVENT {s} AUDIT Proof {s} not found\r\n", .{ self.serverName(), conn.session.displayName(), proof_id }) catch return;
            try appendToConn(conn, line);
            return;
        };
        if (entry.proof_signature.len == 0 or entry.proof_public_key.len == 0) {
            var buf: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&buf, ":{s} EVENT {s} AUDIT Proof {s} has no stored evidence\r\n", .{ self.serverName(), conn.session.displayName(), proof_id }) catch return;
            try appendToConn(conn, line);
            return;
        }
        const target = if (entry.target.len != 0) entry.target else "-";
        const verified = auditProofVerified(entry);
        var hash_buf: [proofmark.proof_id_hex_len]u8 = undefined;
        const reason_hash = proofHashHex(entry.proof_reason_hash, &hash_buf);
        var line1: [default_reply_bytes]u8 = undefined;
        const out1 = std.fmt.bufPrint(&line1, ":{s} EVENT {s} AUDIT Proof {s} seq={d} valid={s} actor={s} action={s}/{d} target={s}\r\n", .{
            self.serverName(),
            conn.session.displayName(),
            entry.proof_id,
            entry.seq,
            if (verified) "true" else "false",
            entry.oper,
            entry.action.label(),
            entry.proof_action,
            target,
        }) catch return;
        try appendToConn(conn, out1);
        var line2: [default_reply_bytes]u8 = undefined;
        const out2 = std.fmt.bufPrint(&line2, ":{s} EVENT {s} AUDIT Proof policy={d} issued_ms={d} expiry_ms={d} reason_hash={s}\r\n", .{
            self.serverName(),
            conn.session.displayName(),
            entry.proof_policy_version,
            entry.proof_issued_ms,
            entry.proof_expiry_ms,
            reason_hash,
        }) catch return;
        try appendToConn(conn, out2);
        var line3: [default_reply_bytes]u8 = undefined;
        const out3 = std.fmt.bufPrint(&line3, ":{s} EVENT {s} AUDIT Proof public_key={s} signature={s}\r\n", .{
            self.serverName(),
            conn.session.displayName(),
            entry.proof_public_key,
            entry.proof_signature,
        }) catch return;
        try appendToConn(conn, out3);
    }

    /// `AUDIT [JSON] [oper] [count]` — dump the oper-action audit ring, most
    /// recent first. A leading non-numeric arg filters to one operator's actions.
    /// Gated on the audit_read privilege (the same priv guarding the DEBUG flight
    /// recorder). `AUDIT PROOF [JSON] <id>` inspects one ProofMark record.
    pub fn handleAudit(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleAudit(self, conn, parsed);
    }

    /// Whether `session` should receive a `category` event with subject `subject`:
    /// an IRCX EVENT mask can add delivery for mapped CHANNEL/MEMBER/USER events,
    /// and the native Event Spine subscription still delivers all category matches
    /// allowed by its own subject scope.
    fn sessionWantsEvent(session: *const dispatch.ClientSession, category: event_spine.EventCategory, severity: event_spine.EventSeverity, message: []const u8, subject: []const u8) bool {
        // The IRCX plane (CHANNEL/MEMBER/USER/MEDIA) is token-routed and has no
        // severity semantics, so it is unaffected by the category severity filter.
        if (sessionIrcxWantsEvent(session, message, subject)) return true;
        if (!session.subscribesTo(category)) return false;
        // Category-plane severity gate: opt-in narrowing (default min = .debug
        // shows everything), so a plain category subscription is unchanged.
        if (!session.severityWanted(severity)) return false;
        const scope = session.eventSubjectMask(category);
        if (std.mem.eql(u8, scope, "*")) return true;
        return observe_mod.globMatch(scope, subject);
    }

    /// IRCX EVENT masks are per IRCX type (CHANNEL/MEMBER/USER), keyed on the
    /// event body's leading TYPE token — NOT the daemon EventCategory. Token
    /// routing is exact: a USER subscriber never receives MEMBER lines and a
    /// MEMBER subscriber never receives USER lines, eliminating the cross-talk
    /// that category-overlap caused (MEMBER and USER both rode OPER_ACTION). It is
    /// an additive overlay: a matching IRCX type+subject grants delivery, but a
    /// non-matching IRCX mask never subtracts native Event Spine (category)
    /// delivery to legacy oper subscribers.
    fn sessionIrcxWantsEvent(session: *const dispatch.ClientSession, message: []const u8, subject: []const u8) bool {
        const typ = event_spine.IrcxEventType.fromMessage(message) orelse return false;
        if (!session.subscribesToIrcxEvent(typ)) return false;
        const scope = session.ircxEventSubjectMask(typ);
        return std.mem.eql(u8, scope, "*") or observe_mod.globMatch(scope, subject);
    }

    /// Render a typed Event Spine event as a chatsvc-faithful `:<srv> EVENT
    /// <target> <message>` line (per recipient) and deliver it to every session
    /// subscribed to that category (oper notices: wallops, kills, connects, …).
    /// Replaces the legacy snote/wallops broadcast channels.
    /// The event's subject defaults to its message text; subscribers may scope a
    /// category to a subject glob (`EVENT ADD <CAT> <mask>`), so this is the thin
    /// wrapper that uses the message as the subject for the common case.
    pub fn publishOperEvent(self: *LinuxServer, category: event_spine.EventCategory, severity: event_spine.EventSeverity, message: []const u8) !void {
        return self.publishOperEventSubject(category, severity, message, message);
    }

    /// Raise a one-shot Event-Spine raid alert for a channel whose join throttle
    /// (explicit +j or the network raid-guard default) just tripped. `world`
    /// already rate-limited this to one call per throttle window per channel, so
    /// this just renders and publishes. Best-effort: alert failure never blocks
    /// the join-deny path.
    fn raidAlert(self: *LinuxServer, channel: []const u8) void {
        var buf: [default_reply_bytes]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "FLOOD possible raid on {s}: join rate exceeded, throttling new joins", .{channel}) catch return;
        self.publishOperEvent(.flood, .notice, msg) catch {};
    }

    /// Hot-path spam-trap check for a non-oper that just touched `target` (a nick
    /// via PRIVMSG, or a channel via JOIN). Skips the lock entirely via the
    /// lock-free `spamtrap_active` atomic when no traps are configured — the
    /// common case. On a trip, raises a one-shot `.flood` oper alert; the actor
    /// is flagged inside the registry for later `SPAMTRAP`/`WARD` follow-up.
    fn spamtrapCheck(self: *LinuxServer, actor: []const u8, kind: spamtrap_mod.TrapKind, target: []const u8, actor_is_oper: bool) void {
        if (!self.spamtrap_active.load(.acquire)) return;
        lockSpin(&self.spamtrap_mu);
        const tripped = self.spamtrap.triggered(actor, kind, target, actor_is_oper) catch false;
        self.spamtrap_mu.unlock();
        if (!tripped) return;
        var buf: [default_reply_bytes]u8 = undefined;
        const kindstr = if (kind == .nick) "nick" else "channel";
        const msg = std.fmt.bufPrint(&buf, "FLOOD spamtrap tripped: {s} touched honeypot {s} {s}", .{ actor, kindstr, target }) catch return;
        self.publishOperEvent(.flood, .warn, msg) catch {};
    }

    /// `SPAMTRAP <ADD|DEL> <NICK|CHAN> <target>` / `SPAMTRAP LIST` — operators
    /// manage the honeypot registry. Oper-gated (client_moderate).
    pub fn handleSpamtrap(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleSpamtrap(self, conn, parsed);
    }

    /// Core publish path with an explicit `subject` used for per-category subject
    /// filtering (distinct from the displayed `message`). Delivery to a subscriber
    /// requires both the category bit and a subject glob match (default scope `*`).
    fn publishOperEventSubject(
        self: *LinuxServer,
        category: event_spine.EventCategory,
        severity: event_spine.EventSeverity,
        message: []const u8,
        subject: []const u8,
    ) !void {
        // Deliver to THIS node's local oper subscribers (rendered with our server
        // name as the origin), then fan the same event to every mesh peer so opers
        // on OTHER nodes see it too — network-wide Event Spine. A peer renders it
        // with THIS node's name as the origin (carried on the wire).
        // Flood-collapse: an identical low-severity event repeated past the
        // threshold within the window is suppressed here (dropped from delivery,
        // mesh, history, and stats); the stats-tick flush later emits one
        // "collapsed N×" summary. Severity >= warn is never collapsed.
        if (!self.event_collapse.admit(@intFromEnum(category), @intFromEnum(severity), message, platform.realtimeMillis())) return;
        if (self.config.node_identity) |identity| {
            var origin_pubkey: [oper_event.pubkey_len]u8 = undefined;
            var origin_sig: [oper_event.sig_len]u8 = undefined;
            var event = oper_event.SignedOperEventV2{
                .category = @intFromEnum(category),
                .severity = @intFromEnum(severity),
                .origin_node = self.config.node_id,
                .hlc = self.nextMeshHlc(),
                .origin_server = self.serverName(),
                .subject = subject,
                .message = message,
            };
            try oper_event.stampOrigin(&event, &identity.sign_kp, &origin_pubkey, &origin_sig);
            const event_id = (try self.admitEventSpineV2(event)) orelse return;
            self.deliverOperEventV2Local(event, event_id, category, severity, subject);
            self.meshBroadcastAuthoredOperEventV2(event);
            self.deliverOutboundWebhooks(category, severity, message);
            return;
        }

        // A node without a sovereign signing identity cannot author OEVT v2.
        // Retain deployed direct-leaf v1 behavior; peers never re-flood it.
        self.event_history.record(@intFromEnum(category), @intFromEnum(severity), platform.realtimeMillis(), self.serverName(), message);
        self.event_stats.record(@intFromEnum(category), @intFromEnum(severity));
        self.deliverOperEventLocal(self.serverName(), category, severity, subject, message);
        self.meshBroadcastOperEvent(category, severity, message);
        self.deliverOutboundWebhooks(category, severity, message);
    }

    /// A failed shard-wide Event-Spine handoff is an ordering gap only for the
    /// exact generations that would have matched that event on the destination
    /// shard. Publish poison to those recipients so reconnect/resume can replay a
    /// coherent stream; unrelated clients remain live and later fan-out continues.
    fn poisonEventSubscribersOnShard(
        self: *LinuxServer,
        shard: u12,
        category: event_spine.EventCategory,
        severity: event_spine.EventSeverity,
        message: []const u8,
        subject: []const u8,
    ) void {
        if (shard >= self.reactors.len) return;
        var it = self.reactors[shard].clients.iterator();
        while (it.next()) |entry| {
            const conn = entry.value;
            if (conn.closing) continue;
            if (!sessionWantsEvent(&conn.session, category, severity, message, subject)) continue;
            if (!self.mediaEventAllowed(entry.id, &conn.session, message)) continue;
            _ = self.poisonDeliveryGeneration(entry.id);
        }
    }

    const EventSpineDeliveryIdentity = struct {
        event_id: oper_event.EventId,
        origin_time_ms: u64,
    };

    fn eventSpineDeliveryTags(
        session: *const dispatch.ClientSession,
        category: event_spine.EventCategory,
        severity: event_spine.EventSeverity,
        identity: ?EventSpineDeliveryIdentity,
        out: []u8,
    ) []const u8 {
        if (!session.hasCap(.message_tags)) return "";
        var structured_buf: [128]u8 = undefined;
        const structured = event_spine.buildEventTags(&structured_buf, category, severity) catch return "";
        const stable = identity orelse {
            if (structured.len > out.len) return "";
            @memcpy(out[0..structured.len], structured);
            return out[0..structured.len];
        };
        const msgid = std.fmt.bytesToHex(stable.event_id, .lower);
        if (session.hasCap(.server_time)) {
            var time_buf: [32]u8 = undefined;
            const time = serverTimeValueAt(&time_buf, stable.origin_time_ms);
            return std.fmt.bufPrint(out, "time={s};msgid={s};{s}", .{ time, msgid, structured }) catch "";
        }
        return std.fmt.bufPrint(out, "msgid={s};{s}", .{ msgid, structured }) catch "";
    }

    /// Deliver one Event-Spine event to this node's local oper subscribers across
    /// ALL shards, rendered `:<origin_server> EVENT <oper-nick> <message>`. Shared
    /// by the local publish path (origin = this server) and the mesh drain (origin
    /// = the peer that raised it). Pure local fan-out; never touches the wire.
    fn deliverOperEventLocal(
        self: *LinuxServer,
        origin_server: []const u8,
        category: event_spine.EventCategory,
        severity: event_spine.EventSeverity,
        subject: []const u8,
        message: []const u8,
    ) void {
        self.deliverOperEventLocalWithIdentity(
            origin_server,
            category,
            severity,
            subject,
            message,
            null,
        );
    }

    fn deliverOperEventV2Local(
        self: *LinuxServer,
        event: oper_event.SignedOperEventV2,
        event_id: oper_event.EventId,
        category: event_spine.EventCategory,
        severity: event_spine.EventSeverity,
        subject: []const u8,
    ) void {
        self.deliverOperEventLocalWithIdentity(
            event.origin_server,
            category,
            severity,
            subject,
            event.message,
            .{ .event_id = event_id, .origin_time_ms = event.originTimeMs() },
        );
    }

    fn deliverOperEventLocalWithIdentity(
        self: *LinuxServer,
        origin_server: []const u8,
        category: event_spine.EventCategory,
        severity: event_spine.EventSeverity,
        subject: []const u8,
        message: []const u8,
        identity: ?EventSpineDeliveryIdentity,
    ) void {
        // chatsvc-faithful delivery: render a raw `:<origin> EVENT <target> <body>`
        // line PER RECIPIENT (target = the subscribed oper's OWN nick). Category
        // gates delivery; the TYPE leads the body (e.g. "USER CONNECT …").
        // Structured IRCv3 message-tags (category + severity), built once and
        // delivered only to clients that negotiated `message-tags`; everyone
        // else gets the plain line.
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            if (!sessionWantsEvent(&entry.value.session, category, severity, message, subject)) continue;
            // MEDIA events are member-scoped: a non-oper only sees call presence for
            // channels they are in (no snooping calls in channels they've not joined).
            if (!self.mediaEventAllowed(entry.id, &entry.value.session, message)) continue;
            var line_buf: [default_reply_bytes]u8 = undefined;
            var tag_buf: [256]u8 = undefined;
            const client_tags = eventSpineDeliveryTags(&entry.value.session, category, severity, identity, &tag_buf);
            const line = event_spine.renderEventTagged(client_tags, origin_server, entry.value.session.displayName(), message, &line_buf) catch continue;
            self.deliver(entry.id, line) catch continue;
        }
        // Cross-shard fan-out: opers on OTHER reactors are not in this reactor's
        // client table, so hand the BODY + subject + ORIGIN to each other shard's
        // inbox and that reactor renders/delivers to its own subscribers. The
        // fabric is null for a single-shard daemon, so this is a no-op there.
        if (self.fabric) |*fabric| {
            const my_shard = self.rx().shard_id;
            const total: u12 = @intCast(fabric.numShards());
            var shard: u12 = 0;
            while (shard < total) : (shard += 1) {
                if (shard == my_shard) continue;
                const buf = fabric.acquire(shard, message) orelse {
                    self.poisonEventSubscribersOnShard(shard, category, severity, message, subject);
                    self.noteCrossShardDrop(fabric, 1);
                    continue;
                };
                var fan = reactor_fabric.DeliverMsg{
                    .to = client_model.ClientId.invalid,
                    .buf = buf,
                    .broadcast_category = @intFromEnum(category),
                    .broadcast_severity = @intFromEnum(severity),
                };
                const sn = @min(subject.len, deliver_handle.broadcast_subject_max);
                @memcpy(fan.broadcast_subject[0..sn], subject[0..sn]);
                fan.broadcast_subject_len = @intCast(sn);
                // Carry the origin server so the receiving reactor renders the right
                // source (the local server name, or a peer's for a network event).
                const on = @min(origin_server.len, deliver_handle.broadcast_origin_max);
                @memcpy(fan.broadcast_origin[0..on], origin_server[0..on]);
                fan.broadcast_origin_len = @intCast(on);
                if (identity) |stable| {
                    fan.broadcast_event_id = stable.event_id;
                    fan.broadcast_event_time_ms = stable.origin_time_ms;
                    fan.broadcast_has_event_identity = true;
                }
                if (fabric.sendTo(shard, fan)) {
                    self.wakeShard(shard);
                } else {
                    fabric.release(shard, buf);
                    self.poisonEventSubscribersOnShard(shard, category, severity, message, subject);
                    self.noteCrossShardDrop(fabric, 1);
                }
            }
        }
    }

    /// Verify and enter one immutable OEVT v2 object into the daemon-global
    /// replay authority and exact OEH1 history as a single serialized mutation.
    /// Only an accepted result authorizes stats, delivery, or re-flood. The
    /// history id is the exact payload returned by Guard.admit for this event;
    /// it is never independently re-derived.
    fn admitEventSpineV2(
        self: *LinuxServer,
        event: oper_event.SignedOperEventV2,
    ) std.mem.Allocator.Error!?oper_event.EventId {
        // The signed display/history origin is not self-authenticating by name.
        // Bind it to the sovereign node id's canonical mesh registry entry
        // before either replay authority can move. Unknown transit origins and
        // aliases are rejected; the immediate hop is never substituted.
        const expected_origin = if (event.origin_node == self.config.node_id) local: {
            // A 64-bit mesh handle is only a routing accelerator. Do not let a
            // (deliberate or accidental) short-id collision impersonate this
            // daemon: local authorship must bind to the complete configured
            // sovereign public key before the replay/history transaction.
            const identity = self.config.node_identity orelse return null;
            if (event.origin_pubkey.len != oper_event.pubkey_len or
                !std.mem.eql(u8, event.origin_pubkey, &identity.sign_kp.public_key))
                return null;
            break :local self.serverName();
        } else self.relayOriginServerName(event.origin_node) orelse return null;
        if (!std.mem.eql(u8, event.origin_server, expected_origin)) return null;

        // OEH1 is deliberately narrower than the protocol's future-facing
        // origin bound. Reject before guard mutation if this build cannot retain
        // the event exactly; accepted replay authority must never outrun history.
        if (event.origin_server.len > event_history_mod.max_origin_len or
            event.message.len > event_history_mod.max_message_len)
            return null;

        var category_valid = false;
        inline for (@typeInfo(event_spine.EventCategory).@"enum".field_values) |value| {
            if (value == event.category) category_valid = true;
        }
        if (!category_valid) return null;
        var severity_valid = false;
        inline for (@typeInfo(event_spine.EventSeverity).@"enum".field_values) |value| {
            if (value == event.severity) severity_valid = true;
        }
        if (!severity_valid) return null;

        const accepted_id: ?oper_event.EventId = blk: {
            lockSpin(&self.event_spine_replay_mu);
            defer self.event_spine_replay_mu.unlock();
            // Stage the replay mutation in a complete candidate. Guard encode,
            // decode, and candidate admission may allocate; none touches the
            // live authority. OEH1 ingestion below is allocation-free after the
            // width precheck and conflicts do not mutate. Only `.inserted`
            // reaches the two no-fail publications (history append, then swap).
            const guard_checkpoint = self.event_spine_replay_guard.encodeCheckpoint(self.allocator) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                else => break :blk null,
            };
            defer self.allocator.free(guard_checkpoint);
            var guard_candidate = event_spine_replay_guard.Guard.decodeCheckpoint(
                self.allocator,
                self.event_spine_replay_guard.config,
                guard_checkpoint,
            ) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                else => break :blk null,
            };
            defer guard_candidate.deinit();
            const admission = try guard_candidate.admit(
                event,
                self.meshWallMs(),
                mesh_clock_mod.default_max_future_skew_ms,
            );
            const event_id = switch (admission) {
                .accepted => |id| id,
                .duplicate,
                .equivocation,
                .retired,
                .origin_capacity,
                .origin_mismatch,
                .bad_signature,
                .invalid_semantic,
                .future_skew,
                => break :blk null,
            };
            const stable = event_history_mod.StableEvent{
                .event_id = event_id,
                .category = event.category,
                .severity = event.severity,
                .origin_ts_unix_ms = @intCast(@min(event.originTimeMs(), @as(u64, std.math.maxInt(i64)))),
                .origin = event.origin_server,
                .message = event.message,
            };
            const history_result = self.event_history.ingestStableEvent(stable) catch
                break :blk null;
            if (history_result != .inserted) break :blk null;
            std.mem.swap(
                event_spine_replay_guard.Guard,
                &self.event_spine_replay_guard,
                &guard_candidate,
            );
            break :blk event_id;
        };
        if (accepted_id != null) self.event_stats.record(event.category, event.severity);
        return accepted_id;
    }

    /// Send one locally-authored immutable v2 object to capable secured peers.
    /// A direct legacy peer receives a v1 terminal leaf copy; it cannot re-flood
    /// that representation. Every v2 peer receives the same signed object.
    fn meshBroadcastAuthoredOperEventV2(
        self: *LinuxServer,
        event: oper_event.SignedOperEventV2,
    ) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    if (link.supportsEventSpineV2()) {
                        _ = link.sendOperEventV2(event) catch continue;
                    } else {
                        link.sendOperEvent(event.category, event.severity, event.origin_server, event.message) catch continue;
                    }
                    _ = self.flushSecuredS2sOutboundTo(pid, link);
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendOperEvent(event.category, event.severity, event.origin_server, event.message) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    /// Fan a locally-raised Event-Spine event to every established mesh peer as a
    /// signed OPER_EVENT, carrying our server name as the origin. Best-effort; a
    /// send failure to one peer never blocks the others or the local delivery.
    fn meshBroadcastOperEvent(self: *LinuxServer, category: event_spine.EventCategory, severity: event_spine.EventSeverity, message: []const u8) void {
        const cat: u6 = @intFromEnum(category);
        const sev: u8 = @intFromEnum(severity);
        const origin = self.serverName();
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                if (slot.value.s2s_secured) |link| {
                    if (!link.established()) continue;
                    link.sendOperEvent(cat, sev, origin, message) catch continue;
                    _ = self.flushSecuredS2sOutboundTo(pid, link);
                } else if (slot.value.s2s) |link| {
                    if (!link.established()) continue;
                    link.sendOperEvent(cat, sev, origin, message) catch continue;
                    self.flushS2sOutboundTo(pid, link.outbound()) catch continue;
                    link.clearOutbound();
                }
            }
        }
    }

    /// Decode a peer's inbound OPER_EVENT payloads and deliver each to this node's
    /// local oper subscribers, rendered with the ORIGIN server the event carries
    /// (NOT this node). Never re-broadcast — that would loop the mesh; a peer
    /// already fanned it to every node directly. Malformed payloads are skipped.
    fn drainOperEvents(self: *LinuxServer, conn: *const ConnState, link: anytype) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const payloads = link.takeOperEvents() catch return;
        defer {
            for (payloads) |p| self.allocator.free(p);
            self.allocator.free(payloads);
        }
        for (payloads) |p| {
            const ev = oper_event.decode(p) catch continue;
            // Reject a category value that is not a defined EventCategory variant
            // (a hostile peer could send any in-range u6) — never @enumFromInt blind.
            var category_opt: ?event_spine.EventCategory = null;
            inline for (@typeInfo(event_spine.EventCategory).@"enum".field_values) |f_value| {
                if (f_value == ev.category) category_opt = @enumFromInt(ev.category);
            }
            const category = category_opt orelse continue;
            // Severity rides the wire (u8); clamp an out-of-range value from a
            // hostile/newer peer to the top defined level rather than @enumFromInt blind.
            const sev_max = @as(u8, @typeInfo(event_spine.EventSeverity).@"enum".field_names.len - 1);
            const severity: event_spine.EventSeverity = @enumFromInt(@min(ev.severity, sev_max));
            // Subject == message (callers that publish locally use the same).
            // Origin is the authenticated peer, not the spoofable wire field.
            const origin = trustedOrigin(link, ev.origin_server);
            self.event_history.record(ev.category, ev.severity, platform.realtimeMillis(), origin, ev.message);
            self.event_stats.record(ev.category, ev.severity);
            self.deliverOperEventLocal(origin, category, severity, ev.message, ev.message);
        }
    }

    /// Admit signed Event Spine v2 objects through the daemon-global authority,
    /// then deliver locally and re-flood the exact immutable byte image. The
    /// transport already verified both immediate-hop and origin signatures, but
    /// the global guard repeats the self-contained verification before durable
    /// replay mutation; no per-link cache can authorize delivery.
    fn drainOperEventsV2(self: *LinuxServer, conn: *const ConnState, link: *secured_s2s_link.SecuredLink) void {
        if (!conn.ownsActiveMeshLink(link)) return;
        const inbound = link.takeOperEventsV2() catch return;
        defer {
            for (inbound) |*item| item.deinit(self.allocator);
            self.allocator.free(inbound);
        }
        for (inbound) |item| {
            const event = oper_event.decodeV2(item.wire) catch continue;
            const event_id = (self.admitEventSpineV2(event) catch null) orelse continue;

            var category_opt: ?event_spine.EventCategory = null;
            inline for (@typeInfo(event_spine.EventCategory).@"enum".field_values) |value| {
                if (value == event.category) category_opt = @enumFromInt(event.category);
            }
            const category = category_opt orelse continue;
            const sev_max = @as(u8, @typeInfo(event_spine.EventSeverity).@"enum".field_names.len - 1);
            const severity: event_spine.EventSeverity = @enumFromInt(@min(event.severity, sev_max));
            self.deliverOperEventV2Local(event, event_id, category, severity, event.subject);
            self.meshForwardOperEventV2(item.wire);
        }
    }

    /// Re-wrap one accepted OEVT v2 byte image for every capable secured peer.
    /// `forwardOperEventV2` never rewrites the origin object. The inbound link's
    /// reflection cache returns false, while the daemon-global guard prevents
    /// delivery or forwarding again if the same object arrives by another path.
    fn meshForwardOperEventV2(self: *LinuxServer, wire: []const u8) void {
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items, 0..) |*slot, i| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const link = slot.value.s2s_secured orelse continue;
                if (!link.established() or !link.supportsEventSpineV2()) continue;
                const emitted = link.forwardOperEventV2(wire) catch continue;
                if (!emitted) continue;
                const pid = slotClientId(reactor, i, slot.gen);
                _ = self.flushSecuredS2sOutboundTo(pid, link);
            }
        }
    }

    /// Mirror a mesh peer link/unlink into the Event Spine as a SERVER_LINK oper
    /// event, alongside the existing `logMeshEvent` entry, so opers subscribed to
    /// SERVER_LINK see peers appear and disappear in real time. Local oper notice
    /// only — no S2S wire change. Reaches opers on the publishing reactor (reactor
    /// 0 owns the peer links), consistent with every other publishOperEvent caller.
    fn publishServerLink(self: *LinuxServer, remote: []const u8, up: bool) void {
        if (remote.len == 0) return;
        // chatsvc SERVER topology event body: `SERVER LINK <peer>` / `SERVER UNLINK
        // <peer>` (the `<TYPE> <SUBTYPE> <args>` form). Onyx Server identifies peers by
        // mesh server name rather than chatsvc's <ip>:<port> <id> <id>.
        var buf: [256]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "SERVER {s} {s}", .{ if (up) "LINK" else "UNLINK", remote }) catch return;
        self.publishOperEvent(.server_link, .notice, msg) catch {};
    }

    /// Surface an opmoderate (+U) held message to the Event Spine as a POLICY
    /// event, so opers subscribed to POLICY get a structured moderation feed in
    /// addition to the channel ops who already receive the raw routed message.
    /// This is the `mode_rearchitecture.md` "held → structured signal" intent for
    /// the network-oper monitoring audience (channel-op raw delivery is unchanged).
    /// Best-effort; reaches opers on the publishing reactor, the same caveat as
    /// every other publishOperEvent caller.
    fn publishModerationHeld(self: *LinuxServer, channel: []const u8, conn: *ConnState, text: []const u8) void {
        var buf: [default_reply_bytes]u8 = undefined;
        const held = if (text.len > 200) text[0..200] else text;
        const msg = std.fmt.bufPrint(&buf, "{s} held message from {s}: {s}", .{ channel, conn.session.displayName(), held }) catch return;
        self.publishOperEvent(.policy, .notice, msg) catch {};
    }

    /// Surface an Aegis-lite history-policy denial to the Event Spine. The client
    /// still receives the ordinary CHATHISTORY failure; this gives operators a
    /// structured reason without reporting unrelated hidden/secret channel probes.
    fn publishHistoryPolicyDeny(self: *LinuxServer, channel: []const u8, conn: *ConnState) void {
        var buf: [default_reply_bytes]u8 = undefined;
        const policy = @tagName(self.channelHistoryPolicy(channel));
        const msg = std.fmt.bufPrint(&buf, "{s} CHATHISTORY denied by history-policy={s} for {s}", .{ channel, policy, conn.session.displayName() }) catch return;
        self.publishOperEventSubject(.policy, .notice, msg, channel) catch {};
    }

    pub fn ocg2RehashHasRestartOnlyIntent(
        runtime_present: bool,
        config: config_format.Config.OperOcg2,
    ) bool {
        return runtime_present or config.enabled or config.projection_enabled or
            config.minting_enabled or config.authority_node_id != 0 or
            config.authority_public_key != null;
    }

    pub fn ocg2RehashHasUnsupportedRuntimeMode(_: config_format.Config.OperOcg2) bool {
        return false;
    }

    fn liveListenerSet(self: *const LinuxServer) config_format.ListenerSet {
        return .{
            .irc = self.config.port,
            .tls = self.config.tls_port,
            .ws = if (self.config.ws_enabled) self.config.ws_port else 0,
            .webtransport = self.config.webtransport_port,
            .s2s = self.config.s2s_port,
            .media = self.config.media_port,
            .native_media = self.config.native_media_port,
        };
    }

    fn rehashLimitLive(self: *const LinuxServer) rehash_dry.LimitSnap {
        return .{
            .max_clones_per_ip = self.config.max_clones_per_ip,
            .max_clones_per_net = self.config.max_clones_per_net,
            .max_clones_per_ip_net = self.config.max_clones_per_ip_net,
            .nick_delay_ms = self.config.nick_delay_ms,
            .throttle_connects = self.config.throttle_connects,
            .throttle_window_ms = self.config.throttle_window_ms,
            .raid_joins = self.config.raid_joins,
            .raid_secs = self.config.raid_secs,
        };
    }

    fn rehashLimitProposed(lim: config_format.Config.Limits) rehash_dry.LimitSnap {
        return .{
            .max_clones_per_ip = lim.max_clones_per_ip,
            .max_clones_per_net = lim.max_clones_per_net,
            .max_clones_per_ip_net = lim.max_clones_per_ip_net,
            .nick_delay_ms = lim.nick_delay_ms,
            .throttle_connects = lim.throttle_connects,
            .throttle_window_ms = lim.throttle_window_ms,
            .raid_joins = lim.raid_joins,
            .raid_secs = @max(@as(u64, 1), lim.raid_window_ms / 1000),
        };
    }

    /// Build the class registry a real REHASH would install. The caller frees it.
    /// A failure leaves the live registry alone.
    fn proposedClassRegistry(self: *LinuxServer, parsed: *const config_format.Config) ?conn_class.Registry {
        var cb = conn_class.Builder.init(self.allocator);
        for (parsed.classes) |c| {
            cb.add(.{
                .name = c.name,
                .policy = c.policy,
                .cidr_texts = c.match_texts,
                .tls_only = c.match_tls,
                .account_only = c.match_account,
                .oper_only = c.match_oper,
                .ident_glob = c.ident_glob,
                .host_glob = c.host_glob,
            }) catch {
                cb.deinit();
                return null;
            };
        }
        return cb.finish() catch {
            cb.deinit();
            return null;
        };
    }

    pub fn emitRehashDry(self: *LinuxServer, conn: *ConnState, path: []const u8, parsed: *const config_format.Config) !void {
        var proposed_reg = self.proposedClassRegistry(parsed);
        defer if (proposed_reg) |*reg| reg.deinit();
        const lines = try rehash_dry.report(self.allocator, .{
            .live_limits = self.rehashLimitLive(),
            .proposed_limits = rehashLimitProposed(parsed.limits),
            .live_classes = if (self.config.class_registry) |*reg| reg.classes else &.{},
            .proposed_classes = if (proposed_reg) |*reg| reg.classes else &.{},
            .class_rejected = proposed_reg == null,
            .live_dnsbl_ward = self.config.dnsbl_ward,
            .proposed_dnsbl_ward = parsed.dnsbl.ward,
            .running_wards = self.warden.wards.items,
            .live_listeners = self.liveListenerSet(),
            .proposed_listeners = config_format.listenerSetFromConfig(parsed.*),
        });
        defer rehash_dry.freeReport(self.allocator, lines);
        for (lines) |line| try self.noticeTo(conn, line);
        try queueNumeric(conn, .RPL_REHASHING, &.{path}, "dry-run; applied none");
    }

    /// REHASH — oper-only configuration reload. Re-reads and re-parses the
    /// configured file and swaps in a freshly-built oper registry (account→class
    /// bindings). Existing sessions keep their current oper state; new SASL logins
    /// observe the reloaded bindings. Without a config path it acknowledges only.
    /// `REHASH DRY` prints the diff and returns before any of those commits.
    pub fn handleRehash(self: *LinuxServer, conn: *ConnState) !void {
        return oper_cmd.handleRehash(self, conn);
    }

    pub fn handleRehashParsed(self: *LinuxServer, conn: *ConnState, parsed_line: *const irc_line.LineView) !void {
        return oper_cmd.handleRehashParsed(self, conn, parsed_line);
    }

    /// Rotate the RFC 5077 / TLS 1.3 session-ticket key: the current key becomes
    /// the previous key (tickets sealed under it still open for one more window,
    /// via tls_resumption.openTicketWithRotation) and a fresh current key is
    /// generated. Called on REHASH when resumption is enabled.
    pub fn rotateTicketKey(self: *LinuxServer) void {
        self.tls_previous_ticket_key = self.tls_ticket_key;
        secure_fns.randomBytes(&self.tls_ticket_key);
    }

    /// Apply the anti-abuse runtime knobs from a freshly parsed config on REHASH:
    /// the connection-class registry (per-class clone/flood/admission policy), the
    /// global clone caps, the connection-rate throttle, and the nick-delay window.
    /// Best-effort: a failed class-registry rebuild keeps the current registry.
    pub fn applyReloadedLimits(self: *LinuxServer, parsed: *const config_format.Config) void {
        const lim = parsed.limits;

        // Scalar caps — pure value updates (no ownership concerns).
        self.config.max_clones_per_ip = lim.max_clones_per_ip;
        self.config.max_clones_per_net = lim.max_clones_per_net;
        self.clone_limit.config = .{ .max_per_ip = lim.max_clones_per_ip, .max_per_net = lim.max_clones_per_net };
        self.config.max_clones_per_ip_net = lim.max_clones_per_ip_net; // network-wide IP cap (aggregate is kept live)
        self.config.nick_delay_ms = lim.nick_delay_ms;

        // Connection-rate throttle: rebuild from the new window/limit. Drops the
        // in-flight rate windows (a momentary, harmless leniency); the concurrent
        // dimension stays owned by clone_limit.
        self.config.throttle_connects = lim.throttle_connects;
        self.config.throttle_window_ms = lim.throttle_window_ms;
        // Network raid-guard default join-throttle (live retune; channels keep any
        // explicit +j, which always overrides this default).
        self.config.raid_joins = lim.raid_joins;
        self.config.raid_secs = @intCast(@max(@as(u64, 1), lim.raid_window_ms / 1000));
        if (self.conn_throttle) |*t| t.deinit();
        self.conn_throttle = if (lim.throttle_connects != 0) clone_detect_mod.CloneDetector.init(self.allocator, .{
            .max_concurrent_per_ip = 0,
            .max_connects_per_window = lim.throttle_connects,
            .window_ms = @max(@as(u64, 1), lim.throttle_window_ms),
        }) else null;

        // Connection classes: build a fresh self-owning registry (the Builder dupes
        // everything), then free the prior server-owned generation and repoint the
        // live registry. The initial registry stays owned by `Loaded`.
        var cb = conn_class.Builder.init(self.allocator);
        var ok = true;
        for (parsed.classes) |c| {
            cb.add(.{
                .name = c.name,
                .policy = c.policy,
                .cidr_texts = c.match_texts,
                .tls_only = c.match_tls,
                .account_only = c.match_account,
                .oper_only = c.match_oper,
                .ident_glob = c.ident_glob,
                .host_glob = c.host_glob,
            }) catch {
                ok = false;
                break;
            };
        }
        if (ok) {
            if (cb.finish()) |new_reg| {
                self.installClassRegistry(new_reg);
            } else |_| {
                cb.deinit();
            }
        } else {
            cb.deinit();
        }

        // Reload OroWasm plugins from the (possibly changed) [wasm] plugin_dir.
        // Rebuild the bridge so removed plugins disappear; the dir string lives in
        // the just-committed reload_parsed, so repoint the live config at it first.
        self.config.wasm_plugin_dir = if (parsed.wasm.plugin_dir) |v| v else "";
        self.config.wasm_max_plugin_bytes = parsed.wasm.max_plugin_bytes;
        self.config.wasm_max_memory_bytes = parsed.wasm.max_memory_bytes;
        self.config.wasm_default_fuel = parsed.wasm.default_fuel;
        self.config.wasm_allowed_caps = parsed.wasm.allowed_caps;
        self.config.wasm_allowed_intents = parsed.wasm.allowed_intents;
        self.config.wasm_registry = parsed.wasm.registry;
        self.config.wasm_revoked_hashes = parsed.wasm.revoked_blake3;
        self.config.wasm_disabled_plugins = parsed.wasm.disabled_plugins;
        self.wasm.deinit();
        self.wasm = wasm_bridge.Bridge.initWithOptions(self.allocator, .{
            .max_plugin_bytes = self.config.wasm_max_plugin_bytes,
            .max_memory_bytes = self.config.wasm_max_memory_bytes,
            .default_fuel = self.config.wasm_default_fuel,
            .allowed_caps = self.config.wasm_allowed_caps,
            .allowed_intents = self.config.wasm_allowed_intents,
            .registry = self.config.wasm_registry,
            .revoked_hashes = self.config.wasm_revoked_hashes,
            .disabled_plugins = self.config.wasm_disabled_plugins,
        });
        self.loadWasmPlugins();
    }

    /// Load OroWasm control-plane plugins from `[wasm] plugin_dir` (best-effort).
    /// Called at boot and on REHASH. A missing dir / malformed plugin is logged,
    /// never fatal — the plugin system simply stays empty.
    pub fn loadWasmPlugins(self: *LinuxServer) void {
        const n = self.loadWasmPluginsFallible() catch |err| {
            srvLog("onyx-server: wasm plugin load from {s} failed: {s}\n", .{ self.config.wasm_plugin_dir, @errorName(err) });
            return;
        };
        if (n > 0) srvLog("onyx-server: loaded {d} OroWasm plugin(s) from {s}\n", .{ n, self.config.wasm_plugin_dir });
    }

    /// Parsing and registration only: Instance.init executes no exports or
    /// hostcalls. Every non-absent load failure remains prepublication.
    pub fn loadWasmPluginsFallible(self: *LinuxServer) !usize {
        if (self.config.wasm_plugin_dir.len == 0) return 0;
        return try self.wasm.loadFromDir(self.config.wasm_plugin_dir);
    }

    /// Outcome of the REHASH cert hot-reload, folded into the RPL_REHASHING note.
    pub const TlsReloadOutcome = enum {
        /// TLS is not configured on this node — nothing to reload.
        not_configured,
        /// Cert/key material was re-read and the live config was swapped.
        reloaded,
        /// A failure (validation/decode/OOM) was reported via NOTICE; the current
        /// certs remain live.
        kept,

        pub fn note(self: TlsReloadOutcome) []const u8 {
            return switch (self) {
                .not_configured => "TLS not configured",
                .reloaded => "TLS certificates reloaded",
                .kept => "TLS certificates unchanged",
            };
        }
    };

    pub fn setAcmeTlsReloadConfig(self: *LinuxServer, tls: *const config_format.Config.Tls) void {
        self.acme_reload_tls = tls;
    }

    /// Read the exact serving TLS generations under the World lock. The
    /// candidate may have loaded different bytes from disk after ACME wrote a
    /// renewal or may have minted a different TLS 1.2 side certificate.
    fn windowsServingTlsSnapshot(self: *LinuxServer) !native_windows_tls_material.Snapshot {
        if (self.config.tls_cert_chain.len == 0) return error.InvalidRuntime;
        const default = native_windows_tls_proof.Material{
            .cert_chain = self.config.tls_cert_chain,
            .signing_key = if (self.config.tls_signing_key) |*key| key else null,
            .ecdsa_p256_signing_key = if (self.config.tls_ecdsa_signing_key) |*key| key else null,
            .rsa_signing_key = if (self.config.tls_rsa_signing_key) |*key| key else null,
        };
        const mode: native_windows_tls_proof.Tls12Mode = if (self.config.tls12_cert_chain.len == 0)
            .disabled
        else if (self.config.tls_signing_key != null)
            .generated
        else
            .shared_default;
        const side_key: ?*const ecdsa_p256.KeyPair = if (self.config.tls12_signing_key) |*key| key else null;
        const tls12_serving: ?native_windows_tls_proof.Material = if (mode == .disabled) null else .{
            .cert_chain = self.config.tls12_cert_chain,
            .ecdsa_p256_signing_key = side_key,
            .rsa_signing_key = if (mode == .shared_default and default.rsa_signing_key != null) default.rsa_signing_key else null,
        };
        return .{
            .default = default,
            .tls12_serving = tls12_serving,
            .tls12_mode = mode,
            .generated_tls12 = if (mode == .generated) .{
                .cert_chain = self.config.tls12_cert_chain,
                .signing_key = side_key orelse return error.InvalidRuntime,
            } else null,
            .reload_pending = self.acme_reload_requested.load(.acquire),
            .reload_retry_after_ms = self.acme_reload_retry_after_ms,
        };
    }

    pub fn requestAcmeTlsReload(self: *LinuxServer) void {
        self.acme_reload_requested.store(true, .release);
    }

    /// Hand a freshly verified OCSPResponse DER (server-owned; this takes it) to
    /// reactor 0 for publication. Called from the OCSP fetch worker thread, so the
    /// handoff slot is mutex-guarded; the atomic wakes the reactor's housekeeping
    /// tick. If a prior staple is still waiting to be consumed it is freed here so
    /// only the newest staple is ever published.
    pub fn publishOcspStaple(self: *LinuxServer, owned_der: []u8) void {
        lockSpin(&self.ocsp_staple_lock);
        if (self.ocsp_staple_incoming) |prior| self.allocator.free(prior);
        self.ocsp_staple_incoming = owned_der;
        self.ocsp_staple_lock.unlock();
        self.ocsp_staple_pending.store(true, .release);
    }

    pub fn takeOcspStapleRejected(self: *LinuxServer) bool {
        return self.ocsp_staple_rejected.swap(false, .acq_rel);
    }

    /// Reactor-0 side of the OCSP-staple handoff: swap in the newest staple. Runs
    /// only on reactor 0 (like `maybeReloadAcmeTls`). The `world.lockWrite` around
    /// each completion serializes this swap against per-connection `tls*Config`
    /// reads, exactly as for `config.tls_cert_chain`. A previously captured
    /// slice remains server-owned until no incomplete handshake borrows it.
    /// The published buffer is Service-allocated and freed with `self.allocator`.
    fn ocspGenerationBorrowed(self: *LinuxServer, generation: []const u8) bool {
        if (self.history_https) |*history| {
            const held = history.tls_config.ocsp_staple;
            if (held.len == generation.len and held.ptr == generation.ptr) return true;
        }
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const tls = slot.value.tls orelse continue;
                if (tls.handshakeDone()) continue;
                if (tls.cfg13.ocsp_staple.len == generation.len and tls.cfg13.ocsp_staple.ptr == generation.ptr)
                    return true;
                if (tls.cfg12) |cfg| {
                    if (cfg.ocsp_staple.len == generation.len and cfg.ocsp_staple.ptr == generation.ptr)
                        return true;
                }
            }
        }
        return false;
    }

    fn pruneRetiredOcspStaples(self: *LinuxServer) void {
        var index: usize = 0;
        while (index < self.ocsp_staple_retired.items.len) {
            if (self.ocspGenerationBorrowed(self.ocsp_staple_retired.items[index])) {
                index += 1;
            } else {
                self.allocator.free(self.ocsp_staple_retired.orderedRemove(index));
            }
        }
    }

    fn retireExpiredActiveOcspStaple(self: *LinuxServer) void {
        const active = self.config.tls_ocsp_staple orelse return;
        const now_unix = @divFloor(platform.realtimeMillis(), 1000);
        if (now_unix == self.ocsp_staple_validated_at_unix and now_unix < self.ocsp_staple_valid_until_unix) return;
        if (now_unix < self.ocsp_staple_valid_until_unix and managed_ocsp.stapleServableForChain(
            active,
            self.config.tls_cert_chain,
            now_unix,
            @import("../crypto/ocsp.zig").default_staple_skew_seconds,
        )) {
            self.ocsp_staple_validated_at_unix = now_unix;
            return;
        }
        // Keep the server-owned generation for incomplete handshakes and Helix
        // custody, but hide it from every new handshake after its deadline.
        self.config.tls_ocsp_staple = null;
        self.ocsp_staple_valid_until_unix = 0;
        self.ocsp_staple_validated_at_unix = std.math.minInt(i64);
    }

    fn maybeSwapOcspStaple(self: *LinuxServer) void {
        self.retireExpiredActiveOcspStaple();
        if (!self.ocsp_staple_pending.swap(false, .acq_rel)) return;
        lockSpin(&self.ocsp_staple_lock);
        const incoming = self.ocsp_staple_incoming;
        self.ocsp_staple_incoming = null;
        self.ocsp_staple_lock.unlock();
        const next = incoming orelse return;
        const valid_until_unix = managed_ocsp.stapleValidUntilForChain(
            next,
            self.config.tls_cert_chain,
            @divFloor(platform.realtimeMillis(), 1000),
            @import("../crypto/ocsp.zig").default_staple_skew_seconds,
        ) orelse {
            self.allocator.free(next);
            // The worker may have read a newly renewed disk leaf while the
            // serving TLS reload is still pending. Re-fetching now would
            // contact the same responder for the same unusable response.
            // The successful live reload below requests a fresh check.
            return;
        };
        const retiring = self.ocsp_staple_prev;
        const retain_retiring = if (retiring) |old| self.ocspGenerationBorrowed(old) else false;
        if (retain_retiring) self.ocsp_staple_retired.ensureUnusedCapacity(self.allocator, 1) catch {
            // Keep the already-fetched, verified DER for the next housekeeping
            // attempt. Re-fetching the responder cannot repair a local
            // allocation failure and may leave Must-Staple clients stranded.
            lockSpin(&self.ocsp_staple_lock);
            if (self.ocsp_staple_incoming == null) {
                self.ocsp_staple_incoming = next;
            } else {
                self.allocator.free(next);
            }
            self.ocsp_staple_lock.unlock();
            self.ocsp_staple_pending.store(true, .release);
            return;
        };
        // All fallible work is done. Publication and old-generation custody
        // now advance together under the World write lock.
        self.config.tls_ocsp_staple = next;
        self.ocsp_staple_valid_until_unix = valid_until_unix;
        self.ocsp_staple_validated_at_unix = @divFloor(platform.realtimeMillis(), 1000);
        if (retiring) |old| {
            if (retain_retiring) self.ocsp_staple_retired.appendAssumeCapacity(old) else self.allocator.free(old);
        }
        self.ocsp_staple_prev = self.ocsp_staple_owned;
        self.ocsp_staple_owned = next;
    }

    fn maybeReloadAcmeTls(self: *LinuxServer) void {
        if (platform.monotonicMillis() < self.acme_reload_retry_after_ms) return;
        if (!self.acme_reload_requested.swap(false, .acq_rel)) return;
        const tls = self.acme_reload_tls orelse {
            srvLog("onyx-server: acme TLS reload requested but no [tls] config is registered\n", .{});
            return;
        };
        const io = self.config.crypto_io orelse {
            srvLog("onyx-server: acme TLS reload requested but no I/O handle is available\n", .{});
            return;
        };
        const outcome = self.reloadTlsCerts(io, tls) catch |err| {
            srvLog("onyx-server: acme TLS reload failed ({s}); keeping current certificates\n", .{@errorName(err)});
            // A freshly written cert/key pair can be temporarily unreadable or
            // incomplete. Preserve the intent and retry without hammering disk
            // on every reactor housekeeping tick.
            self.acme_reload_retry_after_ms = platform.monotonicMillis() +| 30_000;
            self.acme_reload_requested.store(true, .release);
            return;
        };
        self.acme_reload_retry_after_ms = 0;
        srvLog("onyx-server: acme TLS reload on reactor 0: {s}\n", .{outcome.note()});
    }

    /// Re-read the TLS cert chain + signing key from the reloaded config's paths
    /// and, on success, swap the live `config.tls_*` (and TLS 1.2 leg)
    /// fields to a fresh server-owned reload generation — freeing the prior reload
    /// generation, never the main-owned boot generation. On ANY failure the live
    /// config is left wholly untouched (the error propagates; the caller keeps the
    /// current certs and NOTICEs). `tls` borrows caller-owned config that must
    /// outlive the reload call; REHASH uses `self.reload_parsed`, while ACME uses
    /// main's held boot config on reactor 0.
    pub fn reloadTlsCerts(self: *LinuxServer, io: std.Io, tls: *const config_format.Config.Tls) !TlsReloadOutcome {
        return self.reloadTlsCertsLocked(io, tls);
    }

    /// The caller holds the accepted-event boundary. A TLS engine keeps its
    /// certificate config until its handshake finishes, so reload cadence is
    /// never a safe proxy for the lifetime of a borrowed chain or RSA key.
    fn tlsGenerationBorrowed(self: *LinuxServer, generation: *const RetiredTlsGeneration) bool {
        if (self.history_https) |*history| {
            if (generation.primary) |loaded| {
                if (history.tls_config.cert_chain.ptr == loaded.cert_chain.ptr) return true;
            }
            if (generation.side) |loaded| {
                if (history.tls_config.cert_chain.ptr == loaded.cert_chain.ptr) return true;
            }
        }
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied) continue;
                const tls = slot.value.tls orelse continue;
                if (tls.handshakeDone()) continue;
                if (generation.primary) |loaded| {
                    if (tls.cfg13.cert_chain.ptr == loaded.cert_chain.ptr) return true;
                    if (tls.cfg12) |cfg| if (cfg.cert_chain.ptr == loaded.cert_chain.ptr) return true;
                }
                if (generation.side) |loaded| {
                    if (tls.cfg13.cert_chain.ptr == loaded.cert_chain.ptr) return true;
                    if (tls.cfg12) |cfg| if (cfg.cert_chain.ptr == loaded.cert_chain.ptr) return true;
                }
            }
        }
        return false;
    }

    fn pruneRetiredTlsGenerations(self: *LinuxServer) void {
        var index: usize = 0;
        while (index < self.reload_tls_retired.items.len) {
            if (self.tlsGenerationBorrowed(&self.reload_tls_retired.items[index])) {
                index += 1;
            } else {
                var retired = self.reload_tls_retired.orderedRemove(index);
                retired.deinit(self.allocator);
            }
        }
    }

    fn reloadTlsCertsLocked(self: *LinuxServer, io: std.Io, tls: *const config_format.Config.Tls) !TlsReloadOutcome {
        // Mirror the boot gate in main.zig: only [tls] enabled nodes load certs.
        if (!tls.enabled or self.config.tls_cert_chain.len == 0) return .not_configured;

        // Load + validate the new material BEFORE touching any live field, so a
        // failure cannot leave the listener half-swapped.
        const tls_options: tls_certs.Options = .{
            .enabled = true,
            .cert_path = tls.cert_path,
            .key_path = tls.key_path,
            .dns_name = tls.dns_name,
        };
        var loaded = if (builtin.os.tag == .windows and self.config.webtransport_port != 0)
            try tls_certs.loadOrBootstrapWebTransport(self.allocator, io, tls_options)
        else
            try tls_certs.loadOrBootstrap(self.allocator, io, tls_options);
        errdefer loaded.deinit(self.allocator);
        try validateReloadedChain(loaded.cert_chain);
        try native_windows_tls_proof.validateIdentity(native_windows_tls_proof.fromLoaded(&loaded));

        // Resolve the hardened TLS 1.2 leg the same way main.zig does at boot:
        // an ECDSA-P256 or RSA leaf serves 1.2 natively (reusing the 1.3 chain);
        // an Ed25519 leaf needs a freshly-minted ECDSA-P256 leaf for the 1.2 leg.
        // Only mint the side leaf when the node already had a 1.2 leg configured.
        const want_tls12 = self.config.tls12_cert_chain.len != 0;
        var new_tls12: ?tls_certs.Tls12 = null;
        errdefer if (new_tls12) |*t| t.deinit(self.allocator);
        var tls12_chain: []const []const u8 = &.{};
        var tls12_key: ?ecdsa_p256.KeyPair = null;
        if (want_tls12) {
            switch (loaded.key_kind) {
                .ecdsa_p256 => {
                    tls12_chain = loaded.cert_chain;
                    tls12_key = loaded.ecdsa_p256_signing_key;
                },
                .rsa => {
                    tls12_chain = loaded.cert_chain;
                    // 1.2 RSA leg signs with the shared tls_rsa_signing_key (set below).
                },
                .ed25519 => {
                    new_tls12 = try tls_certs.bootstrapTls12(self.allocator, io, tls.dns_name);
                    tls12_chain = new_tls12.?.cert_chain;
                    tls12_key = new_tls12.?.key;
                },
            }
        }

        const still_servable_expiry: ?i64 = if (self.ocsp_staple_owned) |der|
            managed_ocsp.stapleValidUntilForChain(
                der,
                loaded.cert_chain,
                @divFloor(platform.realtimeMillis(), 1000),
                @import("../crypto/ocsp.zig").default_staple_skew_seconds,
            )
        else
            null;
        const still_servable_staple: ?[]u8 = if (still_servable_expiry != null) self.ocsp_staple_owned else null;

        self.pruneRetiredTlsGenerations();
        const retiring = RetiredTlsGeneration{ .primary = self.reload_tls_prev, .side = self.reload_tls12_prev };
        const retain_retiring = self.tlsGenerationBorrowed(&retiring);
        if (retain_retiring) try self.reload_tls_retired.ensureUnusedCapacity(self.allocator, 1);

        // WebTransport owns its own QUIC TLS view. Park its pump and require
        // that no connection still borrows the old certificate before changing
        // the serving generation. A busy listener retries the reload later;
        // the ordinary TLS and QUIC views never diverge after publication.
        const windows_wt_owner: ?*managed_wt.WebTransportListener =
            if (builtin.os.tag == .windows and self.config.webtransport_port != 0)
                self.windows_webtransport_owner orelse return error.InvalidRuntime
            else
                null;
        var windows_wt_pause: ?@import("runtime_pause.zig").Token = null;
        defer if (windows_wt_owner) |owner| {
            if (windows_wt_pause) |token|
                owner.resumePaused(token) catch @panic("WebTransport TLS reload pause could not resume");
        };
        if (windows_wt_owner) |owner| {
            const epoch = std.math.add(u64, self.windows_webtransport_pause_epoch, 1) catch return error.InvalidRuntime;
            const token = try owner.requestPause(epoch);
            self.windows_webtransport_pause_epoch = epoch;
            windows_wt_pause = token;
            try owner.awaitPaused(token, std.Io.Clock.Timestamp.fromNow(io, .{
                .clock = .awake,
                .raw = .fromMilliseconds(2_000),
            }));
            const signing_key: @TypeOf(owner.tls.signing_key) =
                if (loaded.ecdsa_p256_signing_key) |key| .{ .ecdsa_p256 = key } else if (loaded.signing_key) |key| .{ .ed25519 = key } else if (loaded.rsa_signing_key) |key| .{ .rsa = key } else return error.InvalidRuntime;
            try owner.replaceTlsPausedIdle(token, .{ .cert_chain = loaded.cert_chain, .signing_key = signing_key });
        }

        // Commit the live config after reserving any retired-generation custody.
        // The boot generation is main-owned and never freed here.
        self.config.tls_cert_chain = loaded.cert_chain;
        self.config.tls_signing_key = loaded.signing_key;
        self.config.tls_ecdsa_signing_key = loaded.ecdsa_p256_signing_key;
        self.config.tls_rsa_signing_key = loaded.rsa_signing_key;
        if (want_tls12) {
            self.config.tls12_cert_chain = tls12_chain;
            self.config.tls12_signing_key = tls12_key;
        }

        // Keep a generation older than `*_prev` for as long as any unfinished
        // TLS handshake still borrows it. The retired-list reservation above
        // makes this ownership transfer allocation-free after publication.
        if (retain_retiring) {
            self.reload_tls_retired.appendAssumeCapacity(retiring);
        } else {
            var unused = retiring;
            unused.deinit(self.allocator);
        }
        self.reload_tls_prev = self.reload_tls;
        self.reload_tls12_prev = self.reload_tls12;
        self.reload_tls = loaded;
        self.reload_tls12 = new_tls12;

        // An unchanged leaf can keep its still-valid response. A rotated or
        // expired leaf clears the active view and wakes the worker's retry lane;
        // it must not wait out the former certificate's refresh deadline.
        self.config.tls_ocsp_staple = still_servable_staple;
        self.ocsp_staple_valid_until_unix = still_servable_expiry orelse 0;
        self.ocsp_staple_validated_at_unix = std.math.minInt(i64);
        if (self.ocsp_worker != null and still_servable_staple == null)
            self.ocsp_staple_rejected.store(true, .release);
        return .reloaded;
    }

    /// CHANSTATS — ophion m_chanstats subset over the native ChanStats engine.
    /// Registered members may query: TOPUSERS | WORDS | ACTIVITY | RECORD | HELP [#channel]
    pub fn handleChanstats(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (self.config.chanstats_dir.len == 0) {
            try self.noticeTo(conn, "CHANSTATS: channel statistics are disabled on this node");
            return;
        }
        if (!conn.session.registered()) {
            try queueNumeric(conn, .ERR_NOTREGISTERED, &.{}, "You have not registered");
            return;
        }
        const params = parsed.paramSlice();
        const sub = if (params.len >= 1) params[0] else "HELP";
        const chan_arg = if (params.len >= 2) params[1] else "";

        if (std.ascii.eqlIgnoreCase(sub, "HELP") or std.ascii.eqlIgnoreCase(sub, "USAGE")) {
            try self.noticeTo(conn, "CHANSTATS TOPUSERS|WORDS|ACTIVITY|RECORD [#channel] — live channel stats");
            try self.noticeTo(conn, "  TOPUSERS  top speakers by line count");
            try self.noticeTo(conn, "  WORDS     top words (length ≥ 4)");
            try self.noticeTo(conn, "  ACTIVITY  hourly UTC message totals");
            try self.noticeTo(conn, "  RECORD    busiest day, peak hour, peak members, actions");
            return;
        }

        if (chan_arg.len == 0 or !world_model.isChannelName(chan_arg)) {
            try self.noticeTo(conn, "CHANSTATS: usage — CHANSTATS TOPUSERS|WORDS|ACTIVITY|RECORD #channel");
            return;
        }
        const channel = chan_arg;

        const agg: *chanstats_mod.ChannelAgg = blk: {
            if (self.chanstats.channels.get(channel)) |a| break :blk a;
            var it = self.chanstats.channels.iterator();
            while (it.next()) |e| {
                if (std.ascii.eqlIgnoreCase(e.key_ptr.*, channel)) break :blk e.value_ptr.*;
            }
            var nb: [default_reply_bytes]u8 = undefined;
            try self.noticeTo(conn, std.fmt.bufPrint(&nb, "CHANSTATS: no data for {s} yet", .{channel}) catch "CHANSTATS: no data");
            return;
        };

        var line: [default_reply_bytes]u8 = undefined;
        if (std.ascii.eqlIgnoreCase(sub, "TOPUSERS") or std.ascii.eqlIgnoreCase(sub, "TOP")) {
            try self.noticeTo(conn, std.fmt.bufPrint(&line, "CHANSTATS TOPUSERS for {s} ({d} lines, {d} speakers):", .{
                agg.name, agg.messages, agg.users.count(),
            }) catch "CHANSTATS TOPUSERS:");
            // Partial sort into a small stack buffer of pointers.
            const max_show = 15;
            var ptrs: [64]*chanstats_mod.UserAgg = undefined;
            var n: usize = 0;
            var uit = agg.users.valueIterator();
            while (uit.next()) |v| {
                if (n == ptrs.len) break;
                ptrs[n] = v.*;
                n += 1;
            }
            // Selection sort by messages desc, limited.
            var i: usize = 0;
            while (i < n and i < max_show) : (i += 1) {
                var best = i;
                var j = i + 1;
                while (j < n) : (j += 1) {
                    if (ptrs[j].messages > ptrs[best].messages) best = j;
                }
                if (best != i) {
                    const tmp = ptrs[i];
                    ptrs[i] = ptrs[best];
                    ptrs[best] = tmp;
                }
                try self.noticeTo(conn, std.fmt.bufPrint(&line, "  #{d}  {s}  {d} lines  {d} words  {d} actions", .{
                    i + 1, ptrs[i].nick, ptrs[i].messages, ptrs[i].words, ptrs[i].actions,
                }) catch continue);
            }
            if (n == 0) try self.noticeTo(conn, "  (no speakers yet)");
            return;
        }

        if (std.ascii.eqlIgnoreCase(sub, "WORDS")) {
            try self.noticeTo(conn, std.fmt.bufPrint(&line, "CHANSTATS WORDS for {s}:", .{agg.name}) catch "CHANSTATS WORDS:");
            const Word = struct { w: []const u8, c: u64 };
            var words: [40]Word = undefined;
            var wn: usize = 0;
            var wit = agg.word_freq.iterator();
            while (wit.next()) |e| {
                if (wn == words.len) break;
                words[wn] = .{ .w = e.key_ptr.*, .c = e.value_ptr.* };
                wn += 1;
            }
            var i: usize = 0;
            const show = @min(wn, @as(usize, 15));
            while (i < show) : (i += 1) {
                var best = i;
                var j = i + 1;
                while (j < wn) : (j += 1) {
                    if (words[j].c > words[best].c) best = j;
                }
                if (best != i) {
                    const tmp = words[i];
                    words[i] = words[best];
                    words[best] = tmp;
                }
                try self.noticeTo(conn, std.fmt.bufPrint(&line, "  {s} ×{d}", .{ words[i].w, words[i].c }) catch continue);
            }
            if (wn == 0) try self.noticeTo(conn, "  (no words yet)");
            return;
        }

        if (std.ascii.eqlIgnoreCase(sub, "ACTIVITY") or std.ascii.eqlIgnoreCase(sub, "HOURS")) {
            try self.noticeTo(conn, std.fmt.bufPrint(&line, "CHANSTATS ACTIVITY for {s} (UTC hour → messages):", .{agg.name}) catch "CHANSTATS ACTIVITY:");
            var hour: usize = 0;
            while (hour < 24) : (hour += 1) {
                if (agg.hours[hour] == 0) continue;
                try self.noticeTo(conn, std.fmt.bufPrint(&line, "  {d:0>2}:00  {d}", .{ hour, agg.hours[hour] }) catch continue);
            }
            return;
        }

        if (std.ascii.eqlIgnoreCase(sub, "RECORD") or std.ascii.eqlIgnoreCase(sub, "RECORDS")) {
            var best_msgs: u64 = 0;
            for (agg.days.items) |d| {
                if (d.messages >= best_msgs) best_msgs = d.messages;
            }
            var peak_h: usize = 0;
            var peak_c: u64 = 0;
            for (agg.hours, 0..) |h, hi| {
                if (h > peak_c) {
                    peak_c = h;
                    peak_h = hi;
                }
            }
            try self.noticeTo(conn, std.fmt.bufPrint(&line, "CHANSTATS RECORD for {s}:", .{agg.name}) catch "CHANSTATS RECORD:");
            try self.noticeTo(conn, std.fmt.bufPrint(&line, "  messages={d} words={d} actions={d} joins={d} kicks={d}", .{
                agg.messages, agg.words, agg.actions, agg.joins, agg.kicks,
            }) catch "CHANSTATS RECORD");
            try self.noticeTo(conn, std.fmt.bufPrint(&line, "  busiest_day_msgs={d}  peak_hour={d:0>2}:00 UTC ({d} msgs)  peak_members={d}", .{
                best_msgs, peak_h, peak_c, agg.peak_members,
            }) catch "CHANSTATS RECORD");
            return;
        }

        try self.noticeTo(conn, "CHANSTATS: unknown subcommand — try CHANSTATS HELP");
    }

    /// INFO — RPL_INFO (371) lines bracketed by RPL_INFOSTART/RPL_ENDOFINFO.
    pub fn handleInfo(self: *LinuxServer, conn: *ConnState) !void {
        const now = self.nowMs();
        const uptime_secs: u64 = @intCast(@max(@as(i64, 0), @divTrunc(now - self.start_ms, 1000)));
        const online_since: i64 = @divTrunc(platform.realtimeMillis(), 1000) - @as(i64, @intCast(uptime_secs));
        const about = server_about.AboutInfo{
            .version = server_version,
            .zig_version = builtin.zig_version_string,
            .target = @tagName(builtin.cpu.arch) ++ "-" ++ @tagName(builtin.os.tag),
            .optimize = @tagName(builtin.mode),
            .network = protocol_inventory.currentNetworkName(),
            .online_since_unix = online_since,
            .uptime_secs = uptime_secs,
        };

        var body_buf: [1024]u8 = undefined;
        var w = std.Io.Writer.fixed(&body_buf);
        server_about.renderInfo(about, &w) catch {};
        const body = w.buffered();

        try queueNumeric(conn, .RPL_INFOSTART, &.{}, self.serverName());
        var it = std.mem.splitScalar(u8, body, '\n');
        while (it.next()) |line| {
            // splitScalar yields a trailing empty segment after the final '\n';
            // emit blank separators as a single space so the numeric stays valid.
            const text = if (line.len == 0) " " else line;
            if (it.peek() == null and line.len == 0) break;
            try queueNumeric(conn, .RPL_INFO, &.{}, text);
        }
        try self.infoRuntimeLines(conn);
        try queueNumeric(conn, .RPL_ENDOFINFO, &.{}, "End of /INFO list");
    }

    /// Append the runtime-detail INFO block: advertised limits, connection-class
    /// count, established mesh peers, and the active subsystem inventory.
    fn infoRuntimeLines(self: *LinuxServer, conn: *ConnState) !void {
        try queueNumeric(conn, .RPL_INFO, &.{}, " ");
        var b: [480]u8 = undefined;
        if (std.fmt.bufPrint(&b, "Limits: NICKLEN={d} CHANNELLEN={d} TOPICLEN={d} AWAYLEN={d} KICKLEN={d} CHANLIMIT={d} MAXTARGETS={d} MONITOR={d} SILENCE={d} MAXLIST={d}", .{
            self.config.nicklen,    self.config.channellen,   self.config.topiclen,
            self.config.awaylen,    self.config.kicklen,      self.config.chanlimit,
            self.config.maxtargets, self.config.monitorlimit, self.config.silencelimit,
            self.config.maxlist,
        })) |t| try queueNumeric(conn, .RPL_INFO, &.{}, t) else |_| {}

        const nclasses = if (self.config.class_registry) |*r| r.classes.len else 0;
        if (std.fmt.bufPrint(&b, "Connection classes: {d} active (see STATS Y for per-class sendq/recvq/limits/match)", .{nclasses})) |t| try queueNumeric(conn, .RPL_INFO, &.{}, t) else |_| {}

        if (self.config.nick_delay_ms != 0) {
            if (std.fmt.bufPrint(&b, "Nick delay: {d}ms hold on release - {d} nick(s) currently held", .{ self.config.nick_delay_ms, self.nick_delay.count() })) |t| try queueNumeric(conn, .RPL_INFO, &.{}, t) else |_| {}
        }

        var peers: usize = 0;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const c = &slot.value;
                const up = if (c.s2s_secured) |l| l.established() else if (c.s2s) |l| l.established() else false;
                if (up) peers += 1;
            }
        }
        if (std.fmt.bufPrint(&b, "Mesh: {d} established S2S peer link(s) - Undertow CRDT routing over Mooring forward-secret transport", .{peers})) |t| try queueNumeric(conn, .RPL_INFO, &.{}, t) else |_| {}

        try queueNumeric(conn, .RPL_INFO, &.{}, "Subsystems: IRCX + IRCv3, Armor TLS 1.3 (+ hardened 1.2), connection classes, Event Spine, CHATHISTORY + bouncer, native voice/video (CadenceVox/CadenceVis)");
    }

    /// DIRECTORY — registered-client view of the public discovery-directory
    /// entry this node would publish. Mirrors the aggregate-only status.json
    /// directory block: opt-in flag, liveness score, public activity, and mesh
    /// peer health counts. It deliberately does not list channel names.
    pub fn handleDirectory(self: *LinuxServer, conn: *ConnState) !void {
        const public_activity = self.chanstats.publicSummary(platform.realtimeMillis());
        var peers_total: u32 = 0;
        var peers_up: u32 = 0;
        for (self.peer_health.entries.items) |*slot| {
            peers_total += 1;
            if (slot.health.state == .established) peers_up += 1;
        }

        try queueNumeric(conn, .RPL_INFOSTART, &.{}, "Onyx Server discovery directory");
        var b: [640]u8 = undefined;
        if (std.fmt.bufPrint(&b, "listed={s} network={s} node={s} description={s}", .{
            if (self.config.network_discoverable) "true" else "false",
            self.config.network_name,
            self.serverName(),
            self.config.server_description,
        })) |line| try queueNumeric(conn, .RPL_INFO, &.{}, line) else |_| {}

        if (std.fmt.bufPrint(&b, "rank_score={d} users_online={d} channels={d} messages={d} active_channels_24h={d}", .{
            directoryRankScore(public_activity),
            self.meshUserCount(),
            public_activity.channels,
            public_activity.messages,
            public_activity.active_channels_24h,
        })) |line| try queueNumeric(conn, .RPL_INFO, &.{}, line) else |_| {}

        if (public_activity.last_active_ms) |last| {
            if (std.fmt.bufPrint(&b, "last_active={d} heatline_days={d}", .{ @divFloor(last, 1000), public_activity.heatline_len })) |line| try queueNumeric(conn, .RPL_INFO, &.{}, line) else |_| {}
        } else {
            try queueNumeric(conn, .RPL_INFO, &.{}, "last_active=null heatline_days=0");
        }

        if (std.fmt.bufPrint(&b, "mesh_peers_up={d} mesh_peers_total={d}", .{ peers_up, peers_total })) |line| try queueNumeric(conn, .RPL_INFO, &.{}, line) else |_| {}
        if (!self.config.network_discoverable) {
            try queueNumeric(conn, .RPL_INFO, &.{}, "private: set [network] discoverable=true to opt into public directory crawlers");
        }
        try queueNumeric(conn, .RPL_ENDOFINFO, &.{}, "End of /DIRECTORY");
    }

    /// USERS — local user listing (RPL_USERSSTART/RPL_USERS/RPL_ENDOFUSERS).
    pub fn handleUsers(self: *LinuxServer, conn: *ConnState) !void {
        try queueNumeric(conn, .RPL_USERSSTART, &.{}, "UserID   Terminal  Host");
        var any = false;
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            if (!entry.value.session.registered()) continue;
            any = true;
            var line_buf: [128]u8 = undefined;
            const detail = std.fmt.bufPrint(&line_buf, "{s} {s} {s}", .{
                entry.value.session.username(),
                entry.value.session.displayName(),
                default_host,
            }) catch continue;
            try queueNumeric(conn, .RPL_USERS, &.{}, detail);
        }
        if (!any) try queueNumeric(conn, .RPL_NOUSERS, &.{}, "Nobody logged in");
        try queueNumeric(conn, .RPL_ENDOFUSERS, &.{}, "End of users");
    }

    /// LINKS — Undertow mesh view: this server plus every established S2S peer as
    /// a 1-hop neighbour (RPL_LINKS 364 / RPL_ENDOFLINKS 365). Reflects both
    /// plaintext and PQ-secured links, matching the MESH peer view.
    pub fn handleLinks(self: *LinuxServer, conn: *ConnState) !void {
        var line_buf: [256]u8 = undefined;
        // This server's own line carries its CONFIGURED description.
        const own_desc = if (self.config.server_description.len != 0) self.config.server_description else "Onyx Server IRC daemon";
        const detail = std.fmt.bufPrint(&line_buf, "0 {s}", .{own_desc}) catch return;
        try queueNumeric(conn, .RPL_LINKS, &.{ self.serverName(), protocol_inventory.currentServerName() }, detail);
        var seen: [32][]const u8 = undefined;
        var seen_n: usize = 0;
        // S2S peer links live ONLY on reactor 0; iterate it directly (under the
        // world lock) so LINKS finds every peer regardless of which shard answered
        // this query — previously `self.rx()` missed peers on shards 1..N.
        var it = self.reactors[0].clients.iterator();
        outer: while (it.next()) |entry| {
            const c = entry.value;
            if (!c.isActiveMeshPeer()) continue;
            const rname = establishedPeerName(c) orelse continue;
            // One line per distinct peer: a transient duplicate link to the same
            // server must not appear twice.
            for (seen[0..seen_n]) |s| {
                if (std.mem.eql(u8, s, rname)) continue :outer;
            }
            if (seen_n < seen.len) {
                seen[seen_n] = rname;
                seen_n += 1;
            }
            // The peer's REAL handshake-gossiped description (not a generic).
            const pdesc = peerDescription(c) orelse "Undertow peer";
            var lbuf: [256]u8 = undefined;
            const ldetail = std.fmt.bufPrint(&lbuf, "1 {s}", .{pdesc}) catch continue;
            try queueNumeric(conn, .RPL_LINKS, &.{ rname, protocol_inventory.currentServerName() }, ldetail);
        }
        try queueNumeric(conn, .RPL_ENDOFLINKS, &.{"*"}, "End of /LINKS list");
    }

    /// The handshake-gossiped description of the established S2S peer on `conn`,
    /// or null when not an established peer / no description was carried.
    ///
    /// Resolves via `remoteDescription()`, which keys the registry through the
    /// peer's name → route-table node id (the same id space as the WHOIS 312
    /// path). Using `remoteNodeId()` here was WRONG for a secured link: it
    /// returns the authenticated Ed25519 shortId, which is a different u64 than
    /// the peer's advertised registry node id, so `nodeDescription` missed and
    /// LINKS fell back to the generic "Undertow peer" placeholder.
    fn peerDescription(conn: *const ConnState) ?[]const u8 {
        if (conn.s2s) |l| {
            if (l.established()) if (l.remoteDescription()) |d| if (d.len != 0) return d;
        } else if (conn.s2s_secured) |l| {
            if (l.established()) if (l.remoteDescription()) |d| if (d.len != 0) return d;
        }
        return null;
    }

    /// The remote name of an established S2S peer on `conn` (plaintext or
    /// secured), or null when the connection is not an established peer. Shared
    /// by LINKS and MAP so both reflect the same live mesh neighbours as MESH.
    fn activeMeshPeerName(conn: *const ConnState) ?[]const u8 {
        if (!conn.isActiveMeshPeer()) return null;
        return establishedPeerName(conn);
    }

    fn establishedPeerName(conn: *const ConnState) ?[]const u8 {
        if (conn.s2s) |l| {
            if (l.established() and l.remoteName().len != 0) return l.remoteName();
        } else if (conn.s2s_secured) |l| {
            if (l.established() and l.remoteName().len != 0) return l.remoteName();
        }
        return null;
    }

    /// Only a proven complete target identifies a configured endpoint. Neither
    /// an inbound source IP nor a peer's advertised name proves its listener.
    fn meshPeerLinkedByDial(self: *LinuxServer, dial: *const MeshDial) bool {
        const addr = dial.addr orelse return false;
        var it = self.reactors[0].clients.iterator();
        while (it.next()) |entry| {
            const conn = entry.value;
            if (!conn.isActiveMeshPeer() or !conn.s2s_dial_target_known or
                self.s2sPeerLivenessExpired(conn, self.nowMs())) continue;
            _ = establishedPeerName(conn) orelse continue;
            if (sameSockaddrIn(conn.s2s_connect_addr, addr)) return true;
        }
        return false;
    }

    fn sameS2sPeer(a: *const ConnState, b: *const ConnState) bool {
        if (a.s2s_secured) |al| {
            const bl = b.s2s_secured orelse return false;
            const ak = al.peerNodeKey() orelse return false;
            const bk = bl.peerNodeKey() orelse return false;
            return std.mem.eql(u8, &ak, &bk);
        }
        if (b.s2s_secured != null) return false;
        const al = a.s2s orelse return false;
        const bl = b.s2s orelse return false;
        return al.remoteNodeId() == bl.remoteNodeId();
    }

    /// Move the existing endpoint binding before retiring its physical slot.
    /// No address that is still owned by a CONNECT submission may be changed.
    fn transferMeshDialBinding(self: *LinuxServer, loser: *const ConnState, survivor: *ConnState) void {
        if (!sameS2sPeer(loser, survivor) or !loser.s2s_dial_target_known) return;
        if (!survivor.s2s_dial_target_known and !survivor.connect_armed) {
            survivor.s2s_connect_addr = loser.s2s_connect_addr;
            survivor.s2s_dial_target_known = true;
        }
        for (self.mesh_dials) |*dial| {
            const token = dial.token orelse continue;
            if (token.slot == loser.token.slot and token.gen == loser.token.gen) dial.token = survivor.token;
        }
    }

    /// Begin no-allocation S2S teardown while preserving exact io_uring storage
    /// ownership. shutdown wakes an armed recv; the matching completion performs
    /// the ordinary closeConn finalization once every kernel reference is gone.
    fn requestS2sClose(self: *LinuxServer, conn: *ConnState, reason: []const u8) void {
        // closeConn already separates request-close from final teardown using the
        // exact kernel-ownership latches. In particular, an SQ-pressure slot can
        // be activation-pending with no armed operation: finalize it immediately
        // instead of clearing the only maintenance signal and waiting for a CQE
        // that cannot exist.
        if (!conn.closing or conn.close_reason.len == 0) retainCloseReason(conn, reason);
        const token = conn.token;
        self.closeConn(token, conn.close_reason) catch {};
    }

    fn requestS2sDedupDrain(self: *LinuxServer, conn: *ConnState) void {
        retainCloseReason(conn, "Duplicate link collapsed");
        conn.closing = true;
        if (conn.s2s_dedup_drain_deadline_ms == 0)
            conn.s2s_dedup_drain_deadline_ms = self.nowMs() +| 5_000;
        self.progressS2sDedupDrain(conn);
    }

    /// Stage the retained final flight and retire only after the kernel releases
    /// every SEND. The timer retries capacity/OOM/SQ pressure; no input is parsed
    /// once closing is set. Fault/timeout retirement keeps closeConn's exact
    /// kernel-storage ownership protocol.
    fn progressS2sDedupDrain(self: *LinuxServer, conn: *ConnState) void {
        std.debug.assert(conn.closing and conn.s2s_dedup);
        if (self.rx().socket_io_quiescing) return;
        if (self.nowMs() >= conn.s2s_dedup_drain_deadline_ms) {
            conn.s2s_dedup_drain_deadline_ms = 0;
            self.closeConn(conn.token, conn.close_reason) catch {};
            return;
        }
        if (conn.s2s_secured != null) {
            _ = self.flushMeshBurstStage(conn);
        } else if (conn.s2s) |link| {
            const out = link.outbound();
            if (out.len != 0) {
                reserveRawAppendToConn(conn, out.len) catch {
                    self.armSendIfNeeded(conn) catch {};
                    return;
                };
                appendToConn(conn, out) catch return;
                // Commit ownership before attempting SEND so a submission
                // failure cannot append the same handshake a second time.
                link.clearOutbound();
            }
        }
        self.armSendIfNeeded(conn) catch {
            conn.s2s_dedup_drain_deadline_ms = 0;
            self.closeConn(conn.token, conn.close_reason) catch {};
            return;
        };
        const retained = if (conn.s2s_secured) |link|
            link.outbound().len != 0
        else if (conn.s2s) |link|
            link.outbound().len != 0
        else
            false;
        if (!retained and !conn.send_armed and connSendBacklog(conn) == 0) {
            conn.s2s_dedup_drain_deadline_ms = 0;
            self.closeConn(conn.token, conn.close_reason) catch {};
        }
    }

    /// Collapse the duplicate S2S link that forms when both nodes auto-dial each
    /// other: each side ends up with two established links to the same peer (one
    /// it dialed, one the peer dialed), so LINKS/LUSERS over-count and a link is
    /// wasted. When `new_conn` reaches established, look for another established
    /// link to the same `remote_name`; if found, keep the connection initiated by
    /// the lexicographically-smaller server name and close the other. Both nodes
    /// compute the same survivor, so exactly one physical link remains and the
    /// mesh never fully splits. A closing or liveness-expired predecessor is not
    /// a viable survivor, however: the newly authenticated link replaces it
    /// regardless of direction. This is what breaks the half-open-socket loop in
    /// which every healthy redial was previously collapsed against a zombie TCP
    /// ESTABLISHED fd. Returns true when `new_conn` itself was the loser (so the
    /// caller stops driving it). Best-effort within this reactor.
    fn resolveS2sCollision(self: *LinuxServer, new_conn: *ConnState, remote_name: []const u8) bool {
        if (remote_name.len == 0) return false;
        var new_loses = false;
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            const other = entry.value;
            if (other == new_conn) continue;
            const oname = establishedPeerName(other) orelse continue;
            if (!std.mem.eql(u8, oname, remote_name)) continue;
            if (!sameS2sPeer(new_conn, other)) continue;
            const old_unusable = other.closing or other.s2s_dedup or
                self.s2sPeerLivenessExpired(other, self.nowMs());
            if (old_unusable) {
                self.transferMeshDialBinding(other, new_conn);
                other.s2s_dedup = true; // the replacement keeps the peer reachable
                self.requestS2sClose(other, "Stale duplicate link replaced");
                self.logMeshEvent(.peer_down, remote_name, "stale duplicate link replaced");
                // There may also be a healthy survivor for this peer. Continue
                // the scan so the new link is still resolved against every viable
                // route instead of publication hiding two relay-capable sockets.
                continue;
            }
            // Only collapse a clean initiator+responder pair; if both somehow hold
            // the same role, leave them (counting dedup still hides the dup) rather
            // than risk closing the only usable link.
            if (new_conn.s2s_initiator == other.s2s_initiator) continue;
            const keep_initiator = std.mem.lessThan(u8, self.serverName(), remote_name);
            const loser = if (new_conn.s2s_initiator == keep_initiator) other else new_conn;
            const survivor = if (loser == new_conn) other else new_conn;
            self.transferMeshDialBinding(loser, survivor);
            loser.s2s_dedup = true; // collapsed duplicate: suppress its netsplit on close
            if (loser == new_conn) {
                // Finish the scan without touching new_conn again. Marking the
                // decision first avoids freeing the current drive's link object
                // while the iterator still compares remaining predecessors.
                new_loses = true;
                continue;
            }
            self.logMeshEvent(.peer_down, remote_name, "duplicate link collapsed");
            self.requestS2sDedupDrain(loser);
        }
        if (new_loses) {
            new_conn.s2s_dedup = true;
            self.logMeshEvent(.peer_down, remote_name, "duplicate link collapsed");
            self.requestS2sDedupDrain(new_conn);
            return true;
        }
        return false;
    }

    /// Count distinct established S2S peers visible to this reactor (deduped by
    /// remote server name), so a transient duplicate link to one peer is counted
    /// once. Returns the peer count (servers = this node + peers).
    /// Distinct established peers, read from the cross-shard published count.
    /// Safe on any reactor (LUSERS may run on any shard); reactor 0 keeps it
    /// fresh via `publishPeerCount`.
    fn distinctPeerCount(self: *LinuxServer) u64 {
        return self.net_peer_count.load(.acquire);
    }

    /// Recompute the distinct established-peer count from THIS reactor's client
    /// set. Only correct on reactor 0 (the reactor that owns the S2S links) and
    /// must only be called there — it iterates `self.rx().clients`.
    /// Publish reactor 0's authoritative distinct established-peer set (count +
    /// names) for cross-shard LUSERS/MAP reads. MUST be called on reactor 0 only
    /// — it iterates `self.rx().clients`, valid only there. Names are written
    /// before the release-store of the count so cross-shard readers observe a
    /// consistent (count, names) pair.
    fn publishPeerCount(self: *LinuxServer) void {
        // S2S peer links live only on reactor 0 (see the load-bearing comment
        // at `server.zig:6239-6252`). The `onTimerTick` call site already
        // gates this, but that is not the only path to this function — guard
        // internally too, or a sibling reactor's zero-peer view overwrites the
        // shared publication and erases mesh identity for every shard's
        // cross-shard reads. docs/audit/timer-guard-0.7.md P0-TG-2.
        if (!self.isMaintenanceReactor()) return;
        var seen: std.ArrayList(MeshPeerSeen) = .empty;
        defer seen.deinit(self.allocator);
        var owned_names: std.ArrayList([]u8) = .empty;
        defer {
            for (owned_names.items) |name| self.allocator.free(name);
            owned_names.deinit(self.allocator);
        }
        var it = self.rx().clients.iterator();
        outer: while (it.next()) |entry| {
            // A collision loser remains established until its final close, but
            // it is no longer a route. Excluding it lets the winner replace the
            // authenticated node/key atomically at collision commitment.
            if (!entry.value.isActiveMeshPeer()) continue;
            const name = establishedPeerName(entry.value) orelse continue;
            for (seen.items) |row| {
                if (std.mem.eql(u8, row.name, name)) continue :outer;
            }
            const owned = self.allocator.dupe(u8, name) catch return;
            owned_names.append(self.allocator, owned) catch {
                self.allocator.free(owned);
                return;
            };
            var row = MeshPeerSeen{ .name = owned };
            if (entry.value.s2s_secured) |link| {
                if (link.remoteNodeId()) |node_id| row.node_id = node_id;
                if (link.peerNodeKey()) |key| {
                    row.public_key = key;
                    row.public_key_present = true;
                }
            }
            seen.append(self.allocator, row) catch return;
        }
        // A failed replacement keeps the previous peers. Publishing a prefix
        // would hide a live route.
        self.storePublishedMeshPeers(seen.items) catch return;
    }

    /// Replace the published set with copies of `seen`. The previous set stays
    /// in place until every copy has been allocated.
    fn storePublishedMeshPeers(self: *LinuxServer, seen: []const MeshPeerSeen) !void {
        var next: std.ArrayList(PublishedMeshPeer) = .empty;
        var committed = false;
        errdefer if (!committed) {
            for (next.items) |peer| self.allocator.free(peer.name);
            next.deinit(self.allocator);
        };
        try next.ensureTotalCapacity(self.allocator, seen.len);
        for (seen) |row| {
            const name = try self.allocator.dupe(u8, row.name);
            next.appendAssumeCapacity(.{
                .name = name,
                .node_id = row.node_id,
                .public_key = row.public_key,
                .public_key_present = row.public_key_present,
            });
        }
        const count = std.math.cast(u32, next.items.len) orelse return error.PeerCountOverflow;
        lockSpin(&self.mesh_peer_identity_mu);
        defer self.mesh_peer_identity_mu.unlock();
        for (self.mesh_published_peers.items) |peer| self.allocator.free(peer.name);
        self.mesh_published_peers.deinit(self.allocator);
        self.mesh_published_peers = next;
        committed = true;
        protocol_inventory.setMeshPeerCount(count);
        self.net_peer_count.store(count, .release);
    }

    fn freePublishedMeshPeers(self: *LinuxServer) void {
        for (self.mesh_published_peers.items) |peer| self.allocator.free(peer.name);
        self.mesh_published_peers.deinit(self.allocator);
    }

    const PeerNameSnapshot = struct {
        names: [][]u8,
        count: usize,
        allocator: std.mem.Allocator,
        owned: bool,

        fn name(self: *const PeerNameSnapshot, index: usize) []const u8 {
            return self.names[index];
        }

        fn deinit(self: PeerNameSnapshot) void {
            if (!self.owned) return;
            for (self.names) |peer_name| self.allocator.free(peer_name);
            self.allocator.free(self.names);
        }
    };

    /// Return a caller-owned, internally consistent copy of the published peer
    /// names. The copy stays valid after a later publication replaces the
    /// shared list. `deinit` frees it.
    fn readPeerNames(self: *LinuxServer) !PeerNameSnapshot {
        lockSpin(&self.mesh_peer_identity_mu);
        defer self.mesh_peer_identity_mu.unlock();
        const count = @min(
            @as(usize, @intCast(self.net_peer_count.load(.acquire))),
            self.mesh_published_peers.items.len,
        );
        const names = try self.allocator.alloc([]u8, count);
        errdefer self.allocator.free(names);
        var filled: usize = 0;
        errdefer for (names[0..filled]) |peer_name| self.allocator.free(peer_name);
        for (0..count) |i| {
            names[i] = try self.allocator.dupe(u8, self.mesh_published_peers.items[i].name);
            filled += 1;
        }
        return .{
            .names = names,
            .count = count,
            .allocator = self.allocator,
            .owned = true,
        };
    }

    /// MAP — network topology: this server with each established S2S peer (both
    /// plaintext and secured) as a child node (RPL_MAP 015 / RPL_MAPEND 017).
    pub fn handleMap(self: *LinuxServer, conn: *ConnState) !void {
        var line_buf: [160]u8 = undefined;
        const detail = std.fmt.bufPrint(&line_buf, "{s} [Users: {d}]", .{
            protocol_inventory.currentServerName(),
            self.countRegisteredUsers(),
        }) catch return;
        try queueNumeric(conn, .RPL_MAP, &.{}, detail);
        // Peer names come from the reactor-0-published snapshot, not this shard's
        // own connection set — otherwise MAP run on a non-zero shard (the peer
        // links live only on reactor 0) would list no peers.
        const names = self.readPeerNames() catch {
            try queueNumeric(conn, .RPL_MAPEND, &.{}, "End of /MAP");
            return;
        };
        defer names.deinit();
        for (0..names.count) |i| {
            const rname = names.name(i);
            const pdetail = std.fmt.allocPrint(self.allocator, "  `- {s}", .{rname}) catch continue;
            defer self.allocator.free(pdetail);
            queueNumeric(conn, .RPL_MAP, &.{}, pdetail) catch continue;
        }
        try queueNumeric(conn, .RPL_MAPEND, &.{}, "End of /MAP");
    }

    /// Record a mesh event (peer up/down, oper grant, …) into the bounded audit
    /// ring surfaced by `MESH LOG`. Best-effort; never fails a caller.
    fn logMeshEvent(self: *LinuxServer, kind: mesh_event_log.MeshEventKind, subject: []const u8, detail: []const u8) void {
        self.mesh_log.push(.{
            .kind = kind,
            .ts_unix = @divTrunc(platform.realtimeMillis(), 1000),
            .subject = subject,
            .detail = detail,
        });
    }

    /// Mark a peer's link state in the health table (best-effort). Used at the
    /// S2S establish/drop transitions so MESH shows accurate state + uptime.
    fn markPeerHealth(self: *LinuxServer, name: []const u8, state: link_health_mod.PeerState) void {
        if (name.len == 0) return;
        const now: u64 = @intCast(@max(@as(i64, 0), self.nowMs()));
        const h = self.peer_health.upsert(name, now) catch return;
        h.transition(state, now);
        if (state == .down) h.partitioned = false;
    }

    /// Record that `name` is still reachable. `peer_hlc` is ignored: an older
    /// hybrid logical clock must not freeze the local activity stamp.
    fn notePeerStillHere(self: *LinuxServer, name: []const u8, peer_hlc: u64) void {
        if (name.len == 0) return;
        const h = self.peer_health.get(name) orelse return;
        h.noteStillHere(self.nowU64(), peer_hlc);
    }

    pub fn notePeerSendBacklog(self: *LinuxServer, name: []const u8, bytes: u64) void {
        if (name.len == 0) return;
        const h = self.peer_health.get(name) orelse return;
        h.noteSendBacklog(bytes);
    }

    /// Stamp the last finished anti-entropy round and mark value-sync complete.
    /// Value-sync stays its own field from Ripple suspicion.
    fn notePeerAntiEntropy(self: *LinuxServer, name: []const u8) void {
        if (name.len == 0) return;
        const now = self.nowU64();
        const h = self.peer_health.upsert(name, now) catch return;
        h.noteAntiEntropy(now);
        h.value_sync = .synced;
        self.noteMeshDialSuccessByName(name);
    }

    /// Account inbound/outbound bytes for a peer link (best-effort), feeding the
    /// MESH throughput columns. No-op when the peer has no health entry yet.
    fn accountPeerBytes(self: *LinuxServer, name: []const u8, in_bytes: u64, out_bytes: u64) void {
        if (name.len == 0) return;
        const now: u64 = @intCast(@max(@as(i64, 0), self.nowMs()));
        const h = self.peer_health.get(name) orelse return;
        if (in_bytes != 0) h.addIn(in_bytes, now);
        if (out_bytes != 0) h.addOut(out_bytes, now);
    }

    /// Fold a live mesh RTT sample into the peer health table (status.json / MESH).
    fn syncPeerRtt(self: *LinuxServer, name: []const u8, rtt_ms: ?u32) void {
        const sample = rtt_ms orelse return;
        self.latency_stats.record(.mooring_rtt, latencyReactorIndex(), @as(u64, sample) * 1000);
        if (name.len == 0) return;
        const now: u64 = @intCast(@max(@as(i64, 0), self.nowMs()));
        const h = self.peer_health.get(name) orelse return;
        h.observeRtt(sample, now);
    }

    /// Cadence for mesh RTT probes (status page "up · N ms"). Short enough that a
    /// hard-refreshed status page usually sees a sample within one load.
    const peer_rtt_probe_interval_ms: i64 = if (builtin.is_test) 50 else 15_000;

    /// An established S2S link is live only while its most recent application
    /// probe has recoverable inbound evidence. Kernel TCP state and successful
    /// local writes are deliberately insufficient: both can survive a remote
    /// restart as a half-open socket. Any bytes received on the already-authenticated
    /// stream clear awaiting_pong in handleRecv; until then the original probe
    /// timestamp is never extended.
    fn s2sPeerLivenessExpired(self: *const LinuxServer, conn: *const ConnState, now_ms: i64) bool {
        if (!conn.awaiting_pong) return false;
        if (establishedPeerName(conn) == null) return false;
        const grace_ms = @max(@as(i64, 1), self.config.ping_timeout_ms);
        return now_ms - conn.ping_sent_ms > grace_ms;
    }

    /// Emit timestamped PING probes on every established mesh peer and flush the
    /// resulting outbound. Reactor-0-only caller (S2S slots live there).
    fn maybeProbeMeshPeerRtt(self: *LinuxServer) void {
        // S2S peer links live only on reactor 0. Guard internally, and check
        // it BEFORE the throttle counter — not just at the `onTimerTick` call
        // site — so a sibling reactor with no peer links can never consume
        // `last_peer_rtt_probe_ms` while probing nothing (guard theft).
        // docs/audit/timer-guard-0.7.md P0-TG-2.
        if (!self.isMaintenanceReactor()) return;
        const now = self.nowMs();
        if (self.last_peer_rtt_probe_ms != 0 and now - self.last_peer_rtt_probe_ms < peer_rtt_probe_interval_ms)
            return;
        self.last_peer_rtt_probe_ms = now;
        const now_u: u64 = @intCast(@max(@as(i64, 0), now));
        for (self.rx().clients.slots.items) |*slot| {
            if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
            if (slot.value.s2s_probe_pending) {
                // The exact probe ciphertext survived a previous congestion/OOM
                // turn inside SecuredLink. Its receipt clock begins only after
                // the complete record crosses into this connection's SendQ.
                if (self.flushMeshBurstStage(&slot.value)) {
                    std.debug.assert(!slot.value.s2s_probe_pending);
                    std.debug.assert(slot.value.s2s_probe_pending_bytes == 0);
                    std.debug.assert(slot.value.awaiting_pong);
                } else if (slot.value.closing) {
                    self.requestS2sClose(&slot.value, "Mesh probe queue failure");
                }
                continue;
            }
            // Do not keep moving the receipt deadline while the peer is silent.
            // A second queued write is no stronger evidence than the first.
            if (slot.value.awaiting_pong) continue;
            if (slot.value.s2s_secured) |link| {
                if (!link.established()) continue;
                link.probeRtt(now_u) catch continue;
                const probe_boundary = link.outbound().len;
                if (probe_boundary == 0) continue;
                slot.value.s2s_probe_pending = true;
                slot.value.s2s_probe_pending_bytes = probe_boundary;
                if (!self.flushMeshBurstStage(&slot.value)) {
                    if (slot.value.closing)
                        self.requestS2sClose(&slot.value, "Mesh probe queue failure");
                    continue;
                }
                std.debug.assert(!slot.value.s2s_probe_pending);
                std.debug.assert(slot.value.s2s_probe_pending_bytes == 0);
                std.debug.assert(slot.value.awaiting_pong);
                self.syncPeerRtt(link.remoteName(), link.lastRttMs());
                self.notePeerSendBacklog(link.remoteName(), connSendBacklog(&slot.value));
            } else if (slot.value.s2s) |link| {
                if (!link.established()) continue;
                link.probeRtt(now_u) catch continue;
                self.flushS2sOutbound(&slot.value, link.outbound()) catch {
                    link.clearOutbound();
                    continue;
                };
                link.clearOutbound();
                slot.value.awaiting_pong = true;
                slot.value.ping_sent_ms = now;
                self.syncPeerRtt(link.remoteName(), link.lastRttMs());
                self.notePeerSendBacklog(link.remoteName(), connSendBacklog(&slot.value));
            }
        }
    }

    /// MESH (a.k.a. NETSTAT) — oper view of server-to-server mesh health,
    /// rendered by the pure `mesh_report` renderer from live S2S link state,
    /// enriched with per-peer link health (RTT, byte counters, time-in-state)
    /// from the live health table. Operator-gated by the registry (access=.oper).
    /// TTL after which a node not re-observed in the mesh topology is forgotten
    /// (and a split it caused heals). Generous so brief flaps do not churn.
    const partition_seen_ttl_ms: u64 = 5 * 60 * 1000;

    /// Gather the multi-hop mesh topology from `self`'s perspective: an explicit
    /// local<->peer edge per established direct link plus each peer's gossiped
    /// server registry. Returns the number of `partition_detector.TopoNode`
    /// entries written to `out`.
    pub fn assembleMeshTopology(self: *LinuxServer, local_id: u64, out: []partition_detector.TopoNode) usize {
        var tn: usize = 0;
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            if (tn >= out.len) break;
            const c = entry.value;
            if (!c.isActiveMeshPeer()) continue;
            if (c.s2s) |l| {
                if (!l.established()) continue;
                if (l.remoteNodeId()) |rid| {
                    if (tn < out.len) {
                        out[tn] = .{ .node_id = rid, .uplink = local_id };
                        tn += 1;
                    }
                }
                tn += l.collectTopology(out[tn..]);
            } else if (c.s2s_secured) |l| {
                if (!l.established()) continue;
                if (l.peerShortId()) |rid| {
                    if (tn < out.len) {
                        out[tn] = .{ .node_id = rid, .uplink = local_id };
                        tn += 1;
                    }
                }
                tn += l.collectTopology(out[tn..]);
            }
        }
        return tn;
    }

    /// Recompute mesh reachability and emit a `.split` / `.heal` mesh event when
    /// the local node crosses a partition boundary. Observes the live topology
    /// into the persistent SeenSet (so a node lost with its peer link stays
    /// "expected" and registers as unreachable), ages out nodes past the TTL
    /// (healing stale splits), then runs the detector over the remembered node
    /// set. Best-effort; call at S2S link establish/drop transitions.
    fn updatePartitionTransitions(self: *LinuxServer) void {
        const ident = self.config.node_identity orelse return;
        const local_id = ident.shortId();
        const now: u64 = @intCast(@max(@as(i64, 0), self.nowMs()));

        var topo: [partition_detector.max_nodes]partition_detector.TopoNode = undefined;
        const tn = self.assembleMeshTopology(local_id, &topo);

        // Remember the local node and every node currently in view, then forget
        // anything not seen within the TTL.
        self.partition_seen.observe(local_id, now);
        for (topo[0..tn]) |t| {
            self.partition_seen.observe(t.node_id, now);
            if (t.uplink) |up| self.partition_seen.observe(up, now);
        }
        _ = self.partition_seen.prune(now, partition_seen_ttl_ms);

        // Known node set = everything still remembered; edges = the live topology.
        var ids: [partition_detector.max_nodes]u64 = undefined;
        const idn = self.partition_seen.ids(&ids);
        var live: [partition_detector.max_nodes]partition_detector.Liveness = undefined;
        for (0..idn) |i| live[i] = .alive;
        var edges: [partition_detector.max_nodes]partition_detector.Edge = undefined;
        var en: usize = 0;
        for (topo[0..tn]) |t| {
            if (t.uplink) |up| {
                if (up == t.node_id) continue;
                if (en < edges.len) {
                    edges[en] = .{ .a = t.node_id, .b = up };
                    en += 1;
                }
            }
        }

        var det = partition_detector.Detector.init();
        det.update(ids[0..idn], live[0..idn], edges[0..en]) catch return;
        const now_split = det.isPartitioned(local_id);
        // Consume the quorum + component signals (previously computed-and-dropped).
        // Quorum = local's reachable component holds a strict majority of all live
        // known nodes; losing it means this node is in a MINORITY partition.
        const now_quorum = det.hasQuorum(local_id);
        self.partition_components = det.componentCount();

        if (now_split != self.partition_split) {
            self.partition_split = now_split;
            self.logMeshEvent(if (now_split) .split else .heal, self.serverName(), if (now_split) "lost reachability to part of the mesh" else "regained full mesh reachability");
        }

        // Quorum transition: surface a minority-partition (degraded) state to opers
        // when it crosses, and clear it when quorum returns. Distinct from the
        // split signal — a node can be partitioned yet still hold the majority.
        if (now_quorum != self.partition_quorum) {
            self.partition_quorum = now_quorum;
            if (now_quorum) {
                self.logMeshEvent(.heal, self.serverName(), "regained mesh quorum (majority partition)");
                self.publishOperEvent(.server_link, .notice, "NETHEALTH: mesh quorum regained — node is on the majority side") catch {};
            } else {
                self.logMeshEvent(.split, self.serverName(), "lost mesh quorum (minority partition — degraded)");
                self.publishOperEvent(.server_link, .warn, "NETHEALTH: mesh quorum LOST — node is in a minority partition (degraded)") catch {};
            }
        }
    }

    /// True when the local node currently holds mesh quorum (its reachable
    /// component is a strict majority of live known nodes). A node WITHOUT quorum
    /// is in a minority partition and should treat itself as degraded. Read from
    /// the live `partition_quorum` flag maintained by `updatePartitionTransitions`,
    /// so the quorum signal is observable, not dead.
    pub fn meshHasQuorum(self: *const LinuxServer) bool {
        return self.partition_quorum;
    }

    pub fn handleMesh(self: *LinuxServer, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        return oper_cmd.handleMesh(self, conn, parsed);
    }

    pub fn noticeBody(self: *LinuxServer, conn: *ConnState, text: []const u8) !void {
        var lines = std.mem.splitScalar(u8, text, '\n');
        while (lines.next()) |line| {
            if (line.len == 0) continue;
            try self.noticeTo(conn, line);
        }
    }

    /// Append this node's established S2S peer names. Shared by ROUTE and
    /// NETHEALTH so they reflect the same live view. The list grows with the
    /// number of peers.
    pub fn collectPeerNames(self: *LinuxServer, out: *std.ArrayList([]const u8)) !void {
        var it = self.rx().clients.iterator();
        while (it.next()) |entry| {
            if (!entry.value.isActiveMeshPeer()) continue;
            const name = establishedPeerName(entry.value) orelse continue;
            try out.append(self.allocator, name);
        }
    }

    /// ROUTE — oper view of the mesh routing table: this node (distance 0) plus a
    /// one-hop route to every established peer. Rendered by the pure route_report
    /// renderer. Multi-hop routes light up when the route table substrate lands.
    pub fn handleRoute(self: *LinuxServer, conn: *ConnState) !void {
        return oper_cmd.handleRoute(self, conn);
    }

    /// NETHEALTH — this node plus each established peer, marked alive, with link
    /// RTT and idle time. The lines go through the Ripple report renderer. This
    /// command does not run the witness machine. A direct link still dies on
    /// ping timeout, and `witness_quorum` cannot bury a pair.
    pub fn handleNethealth(self: *LinuxServer, conn: *ConnState) !void {
        return oper_cmd.handleNethealth(self, conn);
    }

    /// Fan a pre-built message out to every member of every channel `id` shares,
    /// optionally gated on a negotiated capability, skipping `except`. Each
    /// recipient is delivered at most once even across multiple shared channels.
    /// Fan an IRCv3 `ACCOUNT` line out to common-channel members that negotiated
    /// account-notify, after this client logs in (`label` = account name) or out
    /// (`label` = "*"). Best-effort; no-op if the client shares no channels.
    fn emitAccountChange(self: *LinuxServer, id: client_model.ClientId, conn: *const ConnState, label: []const u8) void {
        // Compose via the shared account_notify builder (single source of truth
        // for the ACCOUNT line format + validation); "*" is the logout sentinel.
        const change: account_notify.AccountChange = if (std.mem.eql(u8, label, account_notify.LOGOUT_SENTINEL))
            .logout
        else
            .{ .login = label };
        const prefix = account_notify.Prefix{
            .nick = conn.session.displayName(),
            .user = conn.session.username(),
            .host = conn.session.host(),
        };
        var body_buf: [default_reply_bytes]u8 = undefined;
        const body = account_notify.buildAccountNotifyLine(&body_buf, prefix, change) catch return;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "{s}\r\n", .{body}) catch return;
        self.notifyCommonChannels(id, msg, .account_notify, id, conn.session.displayName()) catch {};
    }

    fn notifyCommonChannels(
        self: *LinuxServer,
        id: client_model.ClientId,
        msg: []const u8,
        cap: ?dispatch.CapId,
        except: client_model.ClientId,
        monitor_nick: ?[]const u8,
    ) !void {
        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();
        var it = self.world.channels.iterator();
        while (it.next()) |entry| {
            if (!entry.value_ptr.members.contains(worldIdFromClient(id))) continue;
            var members = self.world.memberIterator(entry.key_ptr.*) orelse continue;
            while (members.next()) |member| {
                const mid = clientIdFromWorld(member.*);
                if (mid.eql(except)) continue;
                const key = @as(u64, @bitCast(mid));
                if (seen.contains(key)) continue;
                seen.put(key, {}) catch {};
                const mconn = self.connFor(mid) orelse continue;
                if (cap) |c| {
                    if (!mconn.session.hasCap(c)) continue;
                }
                self.deliver(mid, msg) catch continue;
            }
        }
        // extended-monitor: also deliver to clients MONITORing this nick who do
        // NOT already share a channel (those are in `seen`) and negotiated the
        // cap. Keeps the no-duplicate guarantee against the channel fan-out.
        if (monitor_nick) |nick| {
            const watcher_count = self.monitor.watcherCount(nick);
            var watchers_buf: [128]monitor.ClientId = undefined;
            var allocated_watchers: ?[]monitor.ClientId = null;
            defer if (allocated_watchers) |buf| self.allocator.free(buf);
            const watchers = if (watcher_count <= watchers_buf.len) watchers_buf[0..watcher_count] else blk: {
                const buf = try self.allocator.alloc(monitor.ClientId, watcher_count);
                allocated_watchers = buf;
                break :blk buf;
            };
            const n = self.monitor.watchersOf(nick, watchers);
            for (watchers[0..n]) |w| {
                const wid = clientIdFromMonitor(w);
                if (wid.eql(except)) continue;
                if (seen.contains(@as(u64, @bitCast(wid)))) continue;
                const wconn = self.connFor(wid) orelse continue;
                if (!wconn.session.hasCap(.extended_monitor)) continue;
                if (cap) |c| {
                    if (!wconn.session.hasCap(c)) continue;
                }
                self.deliver(wid, msg) catch continue;
            }
        }
    }

    const ChannelSpeechResult = enum { allow, deny, opmoderate };

    fn channelSpeechGate(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        target: []const u8,
        chan: []const u8,
        text: []const u8,
        is_notice: bool,
        min_rank: u8,
        allow_opmoderate: bool,
    ) !ChannelSpeechResult {
        const wid = worldIdFromClient(id);
        const is_member = self.world.isMember(chan, wid);
        const member_modes = self.world.memberModes(chan, wid) orelse world_model.MemberModes.empty();
        const active_override = overrideActive(conn);

        if (active_override) {
            const bypass = blk: {
                if (!is_member and self.world.channelHasFlag(chan, .no_external)) break :blk "+n no-external";
                if (self.world.channelHasFlag(chan, .moderated) and !member_modes.canSpeakModerated()) break :blk "+m moderated";
                if (self.world.channelHasFlag(chan, .mod_reg) and conn.session.account() == null and !member_modes.canSpeakModerated()) break :blk "+M registered-only speech";

                var mask_buf: [256]u8 = undefined;
                const mask = clientPrefix(conn, &mask_buf) catch "";
                if (mask.len != 0) {
                    var chan_buf: [64][]const u8 = undefined;
                    const ban_ctx = banContextFor(self, conn, wid, mask, &chan_buf);
                    if (self.world.isBannedCtx(chan, ban_ctx)) break :blk "+b ban";
                    if (!member_modes.canSpeakModerated() and self.world.isMutedCtx(chan, ban_ctx)) break :blk "+Z quiet";
                }

                const channel_op = member_modes.isOperator();
                if (!channel_op and self.world.channelHasFlag(chan, .no_ctcp) and isBlockableCtcp(text)) break :blk "+C no-CTCP";
                if (is_notice and !channel_op and self.world.channelHasFlag(chan, .no_notice)) break :blk "+T no-NOTICE";
                if (min_rank > 0 and member_modes.rank() < 1) break :blk "statusmsg rank";
                break :blk null;
            };
            if (bypass) |reason| self.auditOverrideUse(conn, "SEND", chan, reason);
            return .allow;
        }

        if (!is_member and self.world.channelHasFlag(chan, .no_external)) {
            if (!is_notice) try queueNumeric(conn, .ERR_CANNOTSENDTOCHAN, &.{target}, "Cannot send to channel (+n)");
            return .deny;
        }

        const opmod = allow_opmoderate and self.world.channelHasExtFlag(chan, .opmoderate);
        var opmod_route = false;

        if (self.world.channelHasFlag(chan, .moderated) and !member_modes.canSpeakModerated()) {
            if (opmod) {
                opmod_route = true;
            } else {
                if (!is_notice) try queueNumeric(conn, .ERR_CANNOTSENDTOCHAN, &.{target}, "Cannot send to channel (+m)");
                return .deny;
            }
        }

        if (self.world.channelHasFlag(chan, .mod_reg) and conn.session.account() == null and !member_modes.canSpeakModerated()) {
            if (opmod) {
                opmod_route = true;
            } else {
                if (!is_notice) try queueNumeric(conn, .ERR_CANNOTSENDTOCHAN, &.{target}, "Cannot send to channel (+M: identify to a registered account to speak)");
                return .deny;
            }
        }

        if (!conn.session.isOper()) {
            var mask_buf: [256]u8 = undefined;
            const mask = clientPrefix(conn, &mask_buf) catch "";
            if (mask.len != 0) {
                var chan_buf: [64][]const u8 = undefined;
                const ban_ctx = banContextFor(self, conn, wid, mask, &chan_buf);
                if (self.world.isBannedCtx(chan, ban_ctx)) {
                    if (!is_notice) try queueNumeric(conn, .ERR_CANNOTSENDTOCHAN, &.{target}, "Cannot send to channel (+b)");
                    return .deny;
                }
                if (!member_modes.canSpeakModerated() and self.world.isMutedCtx(chan, ban_ctx)) {
                    if (opmod) {
                        opmod_route = true;
                    } else {
                        if (!is_notice) try queueNumeric(conn, .ERR_CANNOTSENDTOCHAN, &.{target}, "Cannot send to channel (+Z: you are quieted)");
                        return .deny;
                    }
                }
            }
        }

        const sender_op = member_modes.isOperator() or conn.session.isOper();
        if (!sender_op and self.world.channelHasFlag(chan, .no_ctcp) and isBlockableCtcp(text)) {
            if (!is_notice) try queueNumeric(conn, .ERR_CANNOTSENDTOCHAN, &.{target}, "Cannot send to channel (+C: no CTCP)");
            return .deny;
        }
        if (is_notice and !sender_op and self.world.channelHasFlag(chan, .no_notice)) {
            return .deny;
        }
        if (min_rank > 0 and member_modes.rank() < 1) {
            if (!is_notice) try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{target}, "You're not channel operator");
            return .deny;
        }

        const slow_exempt = conn.session.isOper() or
            (self.channelSlowmodeVoiceExempt(chan) and member_modes.canSpeakModerated());
        if (self.slowmodeDenies(chan, conn.session.displayName(), slow_exempt)) {
            if (!is_notice) try queueNumeric(conn, .ERR_CANNOTSENDTOCHAN, &.{target}, "Cannot send to channel (slowmode)");
            return .deny;
        }

        return if (opmod_route) .opmoderate else .allow;
    }

    /// TAGMSG <target> — relay sender client tags without a text body. General
    /// client-only tags require message-tags; draft typing/react/reply tags can
    /// also flow to recipients that negotiated their specific draft cap.
    pub fn handleTagmsg(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (!sessionCanUseTagmsg(&conn.session)) {
            try queueNumeric(conn, .ERR_UNKNOWNCOMMAND, &.{"TAGMSG"}, "Unknown command");
            return;
        }
        if (parsed.param_count < 1 or parsed.paramSlice()[0].len == 0) return;
        const raw_tags = parsed.tags_raw orelse return; // nothing to relay
        var tag_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
        var topic_strip_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
        var topic_label_buf: [topic_tag.max_label_len]u8 = undefined;
        const client_tags = clientOnlyTags(raw_tags, &tag_buf);
        const tags = sanitizeTopicClientTags(client_tags, &topic_strip_buf, null, &topic_label_buf);
        if (tags.len == 0) return;
        const target = parsed.paramSlice()[0];

        // Allocate one mesh event identity before local/remote fan-out. Every
        // reusable attachment receives the same stable msgid/time and remote
        // history can replay the exact event clients saw live.
        const event_hlc = self.nextMeshHlc();
        const event_time_ms = mesh_clock_mod.MeshClock.physicalOf(event_hlc);
        var msgid_buf: [msgid_mod.id_len]u8 = undefined;
        var message_id = msgid_mod.fromMeshEvent(self.config.node_id, event_hlc, &msgid_buf);

        var prefix_buf: [256]u8 = undefined;
        const prefix = try clientPrefix(conn, &prefix_buf);
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, ":{s} TAGMSG {s}\r\n", .{
            prefix, target,
        }) catch return error.OutputTooSmall;
        var time_buf: [40]u8 = undefined;
        const ctags = MsgTags{
            .time_value = serverTimeValueAt(&time_buf, event_time_ms),
            .account = conn.session.account(),
            .client_tags = tags,
            .msgid = message_id,
            .is_bot = conn.session.isBot(),
        };
        const echo = conn.session.hasCap(.echo_message);

        if (world_model.isChannelName(target)) {
            if (!self.world.channelExists(target)) {
                try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{target}, "No such channel");
                return;
            }
            if (try self.channelSpeechGate(id, conn, target, target, "", false, 0, false) != .allow) return;
            const history_plan: ?RelayV2History = if (tagmsgHistoryEligible(tags)) .{
                .target = target,
                .sender = prefix,
                .text = "",
                .command = "TAGMSG",
                .client_tags = tags,
                .timestamp_ms = event_time_ms,
            } else null;
            var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer delivery_ids.deinit(self.allocator);
            self.collectChannelDeliveryIds(
                target,
                0,
                if (echo) null else id,
                tags,
                &delivery_ids,
            ) catch {
                try self.failReply(conn, "TAGMSG", "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete attachment delivery set");
                return;
            };
            var accepted_v2: ?AcceptedAuthoredRelayV2 = null;
            defer if (accepted_v2) |*accepted| accepted.deinit(self.allocator);
            if (self.authoredRelayV2Configured()) {
                accepted_v2 = self.admitAuthoredRelayV2(
                    .tagmsg,
                    target,
                    0,
                    prefix,
                    conn.session.account() orelse "",
                    tags,
                    "",
                    "",
                    .channel,
                    "",
                    self.portableSessionTokenForClient(id, conn),
                    (self.world.memberModes(target, worldIdFromClient(id)) orelse
                        world_model.MemberModes.empty()).bits,
                    null,
                    event_hlc,
                    history_plan,
                    .{ .recipients = delivery_ids.items, .line = msg, .is_bot = conn.session.isBot() },
                ) catch {
                    try self.failReply(conn, "TAGMSG", "TEMPORARILY_UNAVAILABLE", "Mesh durable admit failed; event not sent — check mesh peers and retry");
                    return;
                };
                if (accepted_v2) |accepted|
                    message_id = msgid_mod.fromStableId(accepted.relay_id, &msgid_buf)
                else {
                    try self.failReply(conn, "TAGMSG", "TEMPORARILY_UNAVAILABLE", "Mesh authority rejected the event; not delivered — retry or contact opers");
                    return;
                }
            }
            var members = self.world.memberIterator(target) orelse return;
            while (members.next()) |member| {
                const mid = clientIdFromWorld(member.*);
                if (mid.eql(id) and !echo) continue;
                const mconn = self.connFor(mid) orelse continue;
                var visible_tags_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
                if (clientTagsForSession(&mconn.session, tags, &visible_tags_buf).len == 0) continue;
                try self.deliverTaggedMode(
                    mid,
                    ctags,
                    msg,
                    if (accepted_v2) |accepted| accepted.deliveryMode() else .ordinary,
                );
            }
            if (accepted_v2 == null) self.recordHistoryTagmsgAt(target, conn, message_id, tags, event_time_ms);
            // Channel TAGMSG is a first-class mesh event. Relay the sanitized
            // client-only tags with the SAME origin HLC used above; receivers
            // filter tags per-capability before delivery and store eligible
            // typing/reaction events under the same msgid.
            var relay_msg = s2s_link.RelayMessage{
                .verb = .tagmsg,
                .target = target,
                .source_nick = conn.session.displayName(),
                .source_prefix = prefix,
                .account = conn.session.account() orelse "",
                .tags = tags,
                .text = "",
                .origin_node = self.config.node_id,
                .hlc = event_hlc,
            };
            var pk_buf: [message_relay.pubkey_len]u8 = undefined;
            var sig_buf: [message_relay.sig_len]u8 = undefined;
            self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
            if (relay_msg.origin_sig.len != 0)
                _ = self.relay_seen.observe(self.config.node_id, event_hlc)
            else
                _ = self.relay_seen.observeUnsigned(self.config.node_id, event_hlc);
            if (accepted_v2) |accepted| self.forwardAcceptedRelayV2(accepted.wire);
            _ = self.relayLegacyToPeers(relay_msg, .{ .channel = target }, accepted_v2 != null);
            // #33: typing and reaction tags also feed the ACTIVITY stream.
            var tag_it = std.mem.splitScalar(u8, tags, ';');
            while (tag_it.next()) |pair| {
                const eq = std.mem.indexOfScalar(u8, pair, '=') orelse {
                    if (msgedit.isTypingTag(pair)) self.pushTypingActivity(id, conn, target, pair[0..0]) catch {};
                    continue;
                };
                if (msgedit.isTypingTag(pair[0..eq])) {
                    self.pushTypingActivity(id, conn, target, pair[eq + 1 ..]) catch {};
                    break;
                }
            }
            if (findTagValue(tags, "+draft/react")) |rv| {
                self.pushReactionActivity(id, conn, target, rv, findTagValue(tags, "+draft/reply"), .add) catch {};
            } else if (findTagValue(tags, "+draft/unreact")) |rv| {
                self.pushReactionActivity(id, conn, target, rv, findTagValue(tags, "+draft/reply"), .remove) catch {};
            }
            return;
        }
        const recipient = self.world.findNick(target) orelse {
            const recipient_token = self.detachedReplicaTokenForNick(target) orelse return;
            if (self.config.node_identity == null) return;
            const sender_token = self.portableSessionTokenForClient(id, conn);
            var sender_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer sender_ids.deinit(self.allocator);
            self.collectAttachedExactTokenClients(id, conn, &sender_ids) catch return;
            var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer delivery_ids.deinit(self.allocator);
            self.collectDirectDeliveryIds(
                &.{},
                sender_ids.items,
                id,
                echo,
                tags,
                &delivery_ids,
            ) catch return;
            var accepted = (self.admitAuthoredRelayV2(
                .tagmsg,
                target,
                0,
                prefix,
                conn.session.account() orelse "",
                tags,
                "",
                "",
                .direct,
                "",
                sender_token,
                null,
                recipient_token,
                event_hlc,
                null,
                .{ .recipients = delivery_ids.items, .line = msg, .is_bot = conn.session.isBot() },
            ) catch {
                try self.failReply(conn, "TAGMSG", "TEMPORARILY_UNAVAILABLE", "Mesh durable admit failed; event not sent — check mesh peers and retry");
                return;
            }) orelse {
                try self.failReply(conn, "TAGMSG", "TEMPORARILY_UNAVAILABLE", "Mesh authority rejected the event; not delivered — retry or contact opers");
                return;
            };
            defer accepted.deinit(self.allocator);
            message_id = msgid_mod.fromStableId(accepted.relay_id, &msgid_buf);
            self.forwardAcceptedRelayV2(accepted.wire);

            var relay_msg = s2s_link.RelayMessage{
                .verb = .tagmsg,
                .target = target,
                .source_nick = conn.session.displayName(),
                .source_prefix = prefix,
                .account = conn.session.account() orelse "",
                .tags = tags,
                .text = "",
                .origin_node = self.config.node_id,
                .hlc = event_hlc,
            };
            var pk_buf: [message_relay.pubkey_len]u8 = undefined;
            var sig_buf: [message_relay.sig_len]u8 = undefined;
            self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
            _ = self.relayLegacyToPeers(relay_msg, .{ .session_nick = .{
                .nick = target,
                .token = recipient_token,
                .also_token = sender_token,
            } }, true);

            for (sender_ids.items) |sender_attachment| {
                if (sender_attachment.eql(id) and !echo) continue;
                const attachment = self.connFor(sender_attachment) orelse continue;
                var visible_tags_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
                if (clientTagsForSession(&attachment.session, tags, &visible_tags_buf).len == 0) continue;
                self.deliverPreparedTagged(sender_attachment, ctags, msg) catch {};
            }
            return;
        };
        const recipient_id = clientIdFromWorld(recipient);
        const rconn = self.connFor(recipient_id) orelse return;
        var recipient_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer recipient_ids.deinit(self.allocator);
        self.collectAttachedExactTokenClients(recipient_id, rconn, &recipient_ids) catch {
            try self.failReply(conn, "TAGMSG", "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete session recipient set");
            return;
        };
        var sender_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer sender_ids.deinit(self.allocator);
        if (!self.clientsShareExactToken(id, conn, recipient_id, rconn)) {
            self.collectAttachedExactTokenClients(id, conn, &sender_ids) catch {
                try self.failReply(conn, "TAGMSG", "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete session sender set");
                return;
            };
        }
        const recipient_account = rconn.session.account();
        var dm_key_buf: [320]u8 = undefined;
        const store_target = dmHistoryKey(
            conn.session.displayName(),
            conn.session.account(),
            target,
            recipient_account,
            &dm_key_buf,
        );
        const sender_token = self.portableSessionTokenForClient(id, conn);
        const recipient_token = self.portableSessionTokenForClient(recipient_id, rconn);
        var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer delivery_ids.deinit(self.allocator);
        self.collectDirectDeliveryIds(
            recipient_ids.items,
            sender_ids.items,
            id,
            echo,
            tags,
            &delivery_ids,
        ) catch {
            try self.failReply(conn, "TAGMSG", "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete attachment delivery set");
            return;
        };
        var accepted_v2: ?AcceptedAuthoredRelayV2 = null;
        defer if (accepted_v2) |*accepted| accepted.deinit(self.allocator);
        if (recipient_token != null and self.authoredRelayV2Configured()) {
            accepted_v2 = self.admitAuthoredRelayV2(
                .tagmsg,
                target,
                0,
                prefix,
                conn.session.account() orelse "",
                tags,
                "",
                "",
                .direct,
                "",
                sender_token,
                null,
                recipient_token,
                event_hlc,
                if (store_target) |key| if (tagmsgHistoryEligible(tags)) .{
                    .target = key,
                    .sender = prefix,
                    .text = "",
                    .command = "TAGMSG",
                    .client_tags = tags,
                    .timestamp_ms = event_time_ms,
                } else null else null,
                .{ .recipients = delivery_ids.items, .line = msg, .is_bot = conn.session.isBot() },
            ) catch {
                try self.failReply(conn, "TAGMSG", "TEMPORARILY_UNAVAILABLE", "Mesh durable admit failed; event not sent — check mesh peers and retry");
                return;
            };
            if (accepted_v2) |accepted|
                message_id = msgid_mod.fromStableId(accepted.relay_id, &msgid_buf)
            else {
                try self.failReply(conn, "TAGMSG", "TEMPORARILY_UNAVAILABLE", "Mesh authority rejected the event; not delivered — retry or contact opers");
                return;
            }
        }
        for (recipient_ids.items) |recipient_attachment| {
            const attachment = self.connFor(recipient_attachment) orelse continue;
            var visible_tags_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
            if (clientTagsForSession(&attachment.session, tags, &visible_tags_buf).len == 0) continue;
            self.deliverTaggedMode(
                recipient_attachment,
                ctags,
                msg,
                if (accepted_v2) |accepted| accepted.deliveryMode() else .ordinary,
            ) catch {};
        }
        for (sender_ids.items) |sender_attachment| {
            if (sender_attachment.eql(id) and !echo) continue;
            var already_recipient = false;
            for (recipient_ids.items) |recipient_attachment| if (sender_attachment.eql(recipient_attachment)) {
                already_recipient = true;
                break;
            };
            if (already_recipient) continue;
            const attachment = self.connFor(sender_attachment) orelse continue;
            var visible_tags_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
            if (clientTagsForSession(&attachment.session, tags, &visible_tags_buf).len == 0) continue;
            self.deliverTaggedMode(
                sender_attachment,
                ctags,
                msg,
                if (accepted_v2) |accepted| accepted.deliveryMode() else .ordinary,
            ) catch {};
        }
        if (accepted_v2) |accepted| {
            self.forwardAcceptedRelayV2(accepted.wire);
            var relay_msg = s2s_link.RelayMessage{
                .verb = .tagmsg,
                .target = target,
                .source_nick = conn.session.displayName(),
                .source_prefix = prefix,
                .account = conn.session.account() orelse "",
                .tags = tags,
                .text = "",
                .origin_node = self.config.node_id,
                .hlc = event_hlc,
            };
            var pk_buf: [message_relay.pubkey_len]u8 = undefined;
            var sig_buf: [message_relay.sig_len]u8 = undefined;
            self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
            _ = self.relayLegacyToPeers(relay_msg, .{ .session_nick = .{
                .nick = target,
                .token = recipient_token.?,
                .also_token = sender_token,
            } }, true);
        }
        if (accepted_v2 == null) {
            if (store_target) |key| self.recordHistoryTagmsgAt(key, conn, message_id, tags, event_time_ms);
        }
    }

    /// ACTIVITY SUBSCRIBE|UNSUBSCRIBE <#channel> — opt in/out of a channel's
    /// real-time activity stream (#33). A subscriber must be a channel member.
    pub fn handleActivity(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 2) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"ACTIVITY"}, "Not enough parameters");
            return;
        }
        const sub = parsed.paramSlice()[0];
        const channel = parsed.paramSlice()[1];
        if (!world_model.isChannelName(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }
        const cid = monitorIdFromClient(id);
        if (std.ascii.eqlIgnoreCase(sub, "SUBSCRIBE")) {
            if (!self.world.isMember(channel, worldIdFromClient(id))) {
                try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{channel}, "You're not on that channel");
                return;
            }
            _ = self.activity_subs.subscribe(channel, cid) catch {
                try self.noticeTo(conn, "ACTIVITY: subscription limit reached");
                return;
            };
            var buf: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&buf, "Subscribed to activity on {s}", .{channel}) catch return;
            try self.noticeTo(conn, line);
        } else if (std.ascii.eqlIgnoreCase(sub, "UNSUBSCRIBE")) {
            _ = self.activity_subs.unsubscribe(channel, cid);
            var buf: [default_reply_bytes]u8 = undefined;
            const line = std.fmt.bufPrint(&buf, "Unsubscribed from activity on {s}", .{channel}) catch return;
            try self.noticeTo(conn, line);
        } else if (std.ascii.eqlIgnoreCase(sub, "TALLY")) {
            if (parsed.param_count < 3) {
                try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"ACTIVITY"}, "Not enough parameters");
                return;
            }
            const target = parsed.paramSlice()[2];
            var tally_buf: [512]u8 = undefined;
            const tally = self.activity_subs.reactionTally(channel, cid, target, &tally_buf) catch |err| switch (err) {
                error.NotSubscribed => {
                    try self.noticeTo(conn, "ACTIVITY: not subscribed");
                    return;
                },
                error.NoSpaceLeft => return,
            };
            try self.noticeTo(conn, tally);
        } else {
            try self.noticeTo(conn, "ACTIVITY: expected SUBSCRIBE, UNSUBSCRIBE, or TALLY");
        }
    }

    /// Push a typing ActivityEvent to a channel's activity-stream subscribers
    /// (server-relayed as `:<typer> ACTIVITY <#chan> typing <state>`), skipping
    /// the typer. Best-effort; an unknown typing value is dropped.
    fn pushTypingActivity(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, state_value: []const u8) !void {
        const subs = self.activity_subs.subscribers(channel);
        if (subs.len == 0) return;
        const state = activity.TypingState.parse(state_value) catch return;
        var prefix_buf: [256]u8 = undefined;
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = try formatMessage(&line_buf, try clientPrefix(conn, &prefix_buf), "ACTIVITY", &.{ channel, "typing", state.token() }, null);
        for (subs) |sid| {
            const cid = clientIdFromMonitor(sid);
            if (cid.eql(id)) continue;
            self.deliver(cid, line) catch continue;
        }
    }

    /// Push a reaction ActivityEvent (`:reactor ACTIVITY <#chan> react|unreact
    /// <msgid> <reaction>`) to subscribers. Requires a `+draft/reply` target
    /// msgid; an empty/oversized reaction is dropped.
    ///
    /// The tally is recorded before the subscriber check. An empty subscriber
    /// set used to return first, so a client who subscribed after this returned
    /// had no stored tally to read.
    fn pushReactionActivity(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, react_value: []const u8, reply_target: ?[]const u8, op: activity.ReactionOp) !void {
        const r = activity.Reaction.fromTagsWithOp(react_value, reply_target, op) catch return;
        self.activity_subs.recordReaction(channel, monitorIdFromClient(id), r) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => {},
        };
        const subs = self.activity_subs.subscribers(channel);
        if (subs.len == 0) return;
        const verb: []const u8 = if (r.op == .add) "react" else "unreact";
        var prefix_buf: [256]u8 = undefined;
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = try formatMessage(&line_buf, try clientPrefix(conn, &prefix_buf), "ACTIVITY", &.{ channel, verb, r.target_msgid, r.reaction }, null);
        for (subs) |sid| {
            const cid = clientIdFromMonitor(sid);
            if (cid.eql(id)) continue;
            self.deliver(cid, line) catch continue;
        }
    }

    /// Push a presence ActivityEvent to the activity-stream subscribers of every
    /// channel the client is in (`:client ACTIVITY <#chan> presence <state>`),
    /// on AWAY set/clear. Best-effort; skips the client itself.
    fn pushPresenceActivity(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, availability: activity.Availability) void {
        var prefix_buf: [256]u8 = undefined;
        const prefix = clientPrefix(conn, &prefix_buf) catch return;
        var line_buf: [default_reply_bytes]u8 = undefined;
        var it = self.world.channels.iterator();
        while (it.next()) |entry| {
            if (!entry.value_ptr.members.contains(worldIdFromClient(id))) continue;
            const chan = entry.key_ptr.*;
            const subs = self.activity_subs.subscribers(chan);
            if (subs.len == 0) continue;
            const line = formatMessage(&line_buf, prefix, "ACTIVITY", &.{ chan, "presence", availability.token() }, null) catch continue;
            for (subs) |sid| {
                const cid = clientIdFromMonitor(sid);
                if (cid.eql(id)) continue;
                self.deliver(cid, line) catch continue;
            }
        }
    }

    /// Whether `conn`'s outbound messages must be silently dropped before
    /// delivery. Unifies the three independent silencing mechanisms so they
    /// always work together on every message path (PRIVMSG/NOTICE, IRCX DATA,
    /// reassembled multiline):
    ///   * +z GAG (IRCX, IP-keyed, oper-set; authoritative via the `gags` set so
    ///     it survives reconnect and covers every nick on the IP)
    ///   * Warden quarantine (network silence set by a WARD quarantine action)
    ///   * SHUN (network-wide silence; matches by IP, nick, or host-mask; opers
    ///     exempt)
    fn senderSilenced(self: *LinuxServer, conn: *ConnState) bool {
        if (conn.gagged) return true;
        const real_ip = conn.session.realHost();
        if (real_ip.len > 0 and self.gags.count() > 0 and self.gags.contains(real_ip)) return true;
        if (conn.session.isRestricted()) return true;
        if (self.shuns.count() > 0 and !conn.session.isOper()) {
            const now = self.nowMs();
            // A SHUN pattern may be an IP, a nick, or a nick!user@host glob — so
            // test the active shuns against each identity facet the client
            // presents. Any match silences the sender.
            const nick = conn.session.displayName();
            const ip = conn.session.realHost();
            if (nick.len > 0 and self.shuns.isShunned(nick, now)) return true;
            if (ip.len > 0 and self.shuns.isShunned(ip, now)) return true;
            var hm_buf: [320]u8 = undefined;
            if (clientPrefix(conn, &hm_buf)) |hm| {
                if (self.shuns.isShunned(hm, now)) return true;
            } else |_| {}
        }
        return false;
    }

    pub fn handleMessage(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        parsed: *const irc_line.LineView,
        command: []const u8,
    ) !void {
        // GAG + quarantine + SHUN are applied together for every message path.
        if (self.senderSilenced(conn)) return;
        // NOTICE must never generate an automatic error reply (RFC 1459):
        // missing recipient/text is silently dropped to prevent bot reply loops.
        const is_notice = std.ascii.eqlIgnoreCase(command, "NOTICE");
        if (parsed.param_count < 1 or parsed.paramSlice()[0].len == 0) {
            if (!is_notice) {
                var reason_buf: [64]u8 = undefined;
                const reason = std.fmt.bufPrint(&reason_buf, "No recipient given ({s})", .{command}) catch "No recipient given";
                try queueNumeric(conn, .ERR_NORECIPIENT, &.{}, reason);
            }
            return;
        }
        if (parsed.param_count < 2 or parsed.paramSlice()[1].len == 0) {
            if (!is_notice) try queueNumeric(conn, .ERR_NOTEXTTOSEND, &.{}, "No text to send");
            return;
        }
        const text = parsed.paramSlice()[1];
        if (!try self.messageContentGates(id, conn, command, parsed.paramSlice()[0], text, is_notice)) return;
        // Reset the WHOIS idle clock on a real PRIVMSG (NOTICE never resets idle,
        // by convention — so bots/services don't keep a user looking "active").
        if (!is_notice) conn.last_message_ms = self.nowMs();

        // `PRIVMSG a,#b,c :text`: deliver to each comma-separated target, capped
        // at MAXTARGETS to bound fan-out / resist spam amplification.
        var targets = std.mem.splitScalar(u8, parsed.paramSlice()[0], ',');
        var ntarget: u32 = 0;
        var unique_targets: [64][]const u8 = undefined;
        var unique_count: usize = 0;
        // A per-connection-class `max_targets` cap (when set) overrides the global
        // advertised MAXTARGETS for this client's fan-out.
        const target_cap: u32 = if (conn.class_policy.max_targets != 0)
            conn.class_policy.max_targets
        else
            self.config.maxtargets;
        while (targets.next()) |target| {
            if (target.len == 0) continue;
            var duplicate = false;
            for (unique_targets[0..unique_count]) |seen| {
                if (self.sameResolvedMessageTarget(seen, target)) {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate) continue;
            ntarget += 1;
            if (ntarget > target_cap) {
                try queueNumeric(conn, .ERR_TOOMANYTARGETS, &.{target}, "Too many recipients");
                break;
            }
            if (unique_count < unique_targets.len) {
                unique_targets[unique_count] = target;
                unique_count += 1;
            }
            if (self.botChannelSpeakDenied(conn, target)) {
                if (!is_notice) try queueNumeric(conn, .ERR_CANNOTSENDTOCHAN, &.{target}, "Cannot send to channel (bot grant)");
                continue;
            }
            try self.messageOne(id, conn, command, target, text, parsed.tags_raw);
        }
    }

    /// Body-dependent veto gates shared by PRIVMSG/NOTICE and reassembled
    /// draft/multiline: the message_pre_deliver hook, utf8only, and the Koshi
    /// content filter. Returns true if delivery may proceed; on a drop it emits
    /// the appropriate FAIL (PRIVMSG) or stays silent (NOTICE) and returns
    /// false. Callers apply gag/shun and parameter checks beforehand.
    fn messageContentGates(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        command: []const u8,
        target: []const u8,
        text: []const u8,
        is_notice: bool,
    ) !bool {
        // message_pre_deliver typed hook (veto-capable): a subscribed module/plugin
        // may drop the message by clearing `approved`. No subscriber today =>
        // approved stays true => identical behavior. Errors never break delivery.
        {
            var mpd = mod_registry.MessagePreDeliverPayload{
                .source_id = @as(u64, @bitCast(id)),
                .target = target,
                .text = text,
            };
            const verdict = module_manifest.Live.callHook(.message_pre_deliver, self, &mpd) catch mod_registry.HookResult.continue_;
            _ = verdict;
            if (!mpd.approved) return false;
        }
        if (self.wasm.count() > 0 and self.wasm.hasHook("message_pre_deliver")) {
            var parsed_stub = irc_line.LineView{ .raw = "", .command = command };
            var wcore = module_core.Core{
                .services = .{ .allocator = self.allocator, .config = &self.config },
                .server = self,
                .id = id,
                .conn = conn,
                .parsed = &parsed_stub,
                .line = "",
            };
            const host = wasm_bridge.HostBindings{
                .ctx = &wcore,
                .reply = wasmReplyCb,
                .log = wasmLogCb,
                .now_ms = wasmNowCb,
            };
            switch (self.wasm.dispatchHook("message_pre_deliver", host)) {
                .stop => return false,
                .continue_, .not_found, .denied, .trap => {},
            }
        }
        // utf8only: reject malformed UTF-8 bodies with a standard-replies FAIL and
        // drop the message (ISUPPORT advertises UTF8ONLY). NOTICE stays silent.
        if (!utf8_guard.isValidMessageBody(text)) {
            if (!is_notice) {
                var fail_buf: [128]u8 = undefined;
                if (utf8_guard.buildInvalidUtf8Fail(&fail_buf, command)) |line| {
                    var crlf: [160]u8 = undefined;
                    const out = std.fmt.bufPrint(&crlf, "{s}\r\n", .{line}) catch return false;
                    try appendToConn(conn, out);
                } else |_| {}
            }
            return false;
        }
        // Koshi content filter: block messages matching an oper-curated pattern.
        // Opers are exempt; NOTICE drops silently (no auto-reply), PRIVMSG FAILs.
        // Match both the raw text AND a formatting-stripped copy so a filtered
        // word can't be smuggled past Koshi via embedded mIRC color/format codes.
        // The strip buffer matches the largest deliverable body so an oversized
        // colour-formatted message still gets a full strip (not a silent skip
        // that would leave only the raw-text match — CWE-693 policy bypass).
        if (!conn.session.isOper()) {
            var filtered = self.content_filter.matches(text);
            if (!filtered and color_strip.hasFormatting(text)) {
                var strip_buf: [default_reply_bytes]u8 = undefined;
                if (color_strip.stripFormattingWith(.{ .max_output_bytes = default_reply_bytes }, text, &strip_buf)) |clean| {
                    filtered = self.content_filter.matches(clean);
                } else |_| {}
            }
            if (filtered) {
                if (!is_notice) try self.failReply(conn, command, "ONYX_FILTERED", "Message blocked by the content filter");
                return false;
            }
        }
        // Per-channel bad-word filter (svc_chanbadwords): channel-op-managed list,
        // channel targets only. Channel operators and server opers are exempt.
        if (target.len != 0 and (target[0] == '#' or target[0] == '&' or target[0] == '%') and !conn.session.isOper()) {
            const exempt = if (self.world.memberModes(target, worldIdFromClient(id))) |mm| mm.isOperator() else false;
            if (!exempt) {
                if (self.account_services) |svc| {
                    if (svc.chanBadwordMatches(target, text)) {
                        if (!is_notice) try self.failReply(conn, command, "ONYX_FILTERED", "Message blocked by the channel word filter");
                        return false;
                    }
                }
            }
        }
        return true;
    }

    fn sameResolvedMessageTarget(self: *LinuxServer, a: []const u8, b: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(a, b)) return true;
        const an = self.world.findNick(a) orelse return false;
        const bn = self.world.findNick(b) orelse return false;
        return an.eql(bn);
    }

    /// Route one line from a draft/multiline-capable client into the per-conn
    /// reassembler. Returns true when the line was consumed (a multiline BATCH
    /// open/close or a tagged chunk); false to let normal dispatch handle it.
    fn routeMultiline(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        parsed: *const irc_line.LineView,
        line: []const u8,
    ) !bool {
        const is_batch = std.ascii.eqlIgnoreCase(parsed.command, "BATCH");

        if (conn.multiline) |ms| {
            // A batch is open: a BATCH line is its close, anything tagged with
            // our reference is a chunk. Any assembler error aborts + FAILs.
            if (is_batch) {
                const msg = ms.assembler.finish(line, ms.out) catch {
                    self.abortMultiline(conn);
                    try self.failReply(conn, "BATCH", "MULTILINE_INVALID", "Invalid multiline batch");
                    return true;
                };
                try self.deliverMultiline(id, conn, msg.command, msg.target, msg.value);
                self.abortMultiline(conn); // batch closed; release the buffer
                return true;
            }
            if (batchTagValue(parsed)) |ref| {
                if (std.mem.eql(u8, ref, ms.assembler.reference())) {
                    if (ms.assembler.line_count >= self.config.multiline_max_lines) {
                        self.abortMultiline(conn);
                        try self.failReply(conn, "BATCH", "MULTILINE_INVALID", "Invalid multiline batch");
                        return true;
                    }
                    ms.assembler.append(line, ms.out) catch {
                        self.abortMultiline(conn);
                        try self.failReply(conn, "BATCH", "MULTILINE_INVALID", "Invalid multiline batch");
                        return true;
                    };
                    return true;
                }
            }
            return false; // unrelated line; leave the open batch untouched
        }

        // No open batch: only consume a `BATCH +ref draft/multiline target` open.
        if (is_batch and isMultilineOpen(parsed)) {
            const ms = self.allocator.create(MultilineState) catch return false;
            const out = self.allocator.alloc(u8, self.config.multiline_max_bytes) catch {
                self.allocator.destroy(ms);
                return false;
            };
            ms.* = .{ .out = out };
            ms.assembler.begin(line) catch {
                self.allocator.free(ms.out);
                self.allocator.destroy(ms);
                try self.failReply(conn, "BATCH", "MULTILINE_INVALID", "Invalid multiline batch");
                return true;
            };
            if (ms.assembler.reference().len > self.config.multiline_ref_len or
                ms.assembler.target().len > self.config.multiline_target_len)
            {
                self.allocator.free(ms.out);
                self.allocator.destroy(ms);
                try self.failReply(conn, "BATCH", "MULTILINE_INVALID", "Invalid multiline batch");
                return true;
            }
            conn.multiline = ms;
            return true;
        }
        return false;
    }

    /// Deliver a reassembled multiline message: split the joined value on the
    /// inter-chunk newline and emit each segment as an individual PRIVMSG/NOTICE
    /// (server-side splitting is spec-permitted for any recipient).
    fn deliverMultiline(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        command: multiline.PayloadCommand,
        target: []const u8,
        value: []const u8,
    ) !void {
        if (self.senderSilenced(conn)) return;
        const cmd = command.token();
        const is_notice = command == .notice;
        if (!try self.messageContentGates(id, conn, cmd, target, value, is_notice)) return;

        var it = std.mem.splitScalar(u8, value, '\n');
        while (it.next()) |segment| {
            try self.messageOne(id, conn, cmd, target, segment, null);
        }
    }

    /// Free and clear a connection's open multiline batch state, if any.
    fn abortMultiline(self: *LinuxServer, conn: *ConnState) void {
        if (conn.multiline) |ms| {
            self.allocator.free(ms.out);
            self.allocator.destroy(ms);
            conn.multiline = null;
        }
    }

    fn messageOne(
        self: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        command: []const u8,
        target: []const u8,
        text: []const u8,
        client_tags: ?[]const u8,
    ) !void {
        // Spamtrap: a non-oper messaging an operator-designated honeypot nick
        // trips the trap (channel honeypots trip on JOIN instead). Lock-free
        // no-op when no nick traps are configured; checked before delivery so a
        // trap nick need not be online to flag the sender.
        if (!world_model.isChannelName(target)) {
            self.spamtrapCheck(conn.session.displayName(), .nick, target, conn.session.isOper());
        }

        // RFC 1459: NOTICE must NEVER generate an error
        // reply (prevents NOTICE/error ping-pong between bots and servers). All
        // delivery-failure numerics below are suppressed for NOTICE.
        const is_notice = std.ascii.eqlIgnoreCase(command, "NOTICE");
        var clean_tag_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
        var topic_strip_buf: [irc_line.max_client_tags_raw_len]u8 = undefined;
        var topic_label_buf: [topic_tag.max_label_len]u8 = undefined;
        // Named conversations ("topics"): a channel message may carry a
        // `+onyx/topic=<label>` client-only tag. A valid label is kept verbatim
        // (it rides the ordinary client-tag path to members, echo, mesh and
        // history) and captured for the per-channel topic registry; an
        // oversized/invalid label is stripped fail-closed so it never reaches the
        // wire, store, or registry. No topic tag => byte-identical to before.
        var topic_label: ?[]const u8 = null;
        const clean_client_tags: ?[]const u8 = if (client_tags) |raw| blk: {
            const clean = clientOnlyTags(raw, &clean_tag_buf);
            if (clean.len == 0) break :blk null;
            const sanitized = sanitizeTopicClientTags(clean, &topic_strip_buf, &topic_label, &topic_label_buf);
            break :blk if (sanitized.len == 0) null else sanitized;
        } else null;

        // STATUSMSG: a leading prefix (!/./@/+) before a channel name restricts
        // delivery to members of that rank or higher. `chan` is the bare channel
        // for world lookups; `target` keeps the prefix for the displayed line.
        var chan = target;
        var min_rank: u8 = 0;
        if (target.len >= 2) {
            const r = statusPrefixRank(target[0]);
            if (r > 0 and world_model.isChannelName(target[1..])) {
                min_rank = r;
                chan = target[1..];
            }
        }

        if (world_model.isChannelName(chan)) {
            if (!self.world.channelExists(chan)) {
                if (!is_notice) try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{target}, "No such channel");
                return;
            }
            if (!self.messageSatisfiesEncryptionPolicy(chan, clean_client_tags, text, false)) {
                if (!is_notice) try self.failReply(conn, command, "E2EE_REQUIRED", "Channel requires encrypted messages");
                return;
            }
        }

        // Required-room admission happened above, before we format an IRC line
        // or allocate an event identity. In particular, an oversized tagged
        // plaintext candidate produces E2EE_REQUIRED (or silent NOTICE), not an
        // OutputTooSmall error or a partially admitted event.
        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = try formatMessage(&msg_buf, try clientPrefix(conn, &prefix_buf), command, &.{target}, text);

        // Allocate one event identity before any local/mesh fan-out. The same
        // authenticated `(origin,hlc)` deterministically yields msgid + time on
        // every node, so all attachments can reference and order one event.
        const event_hlc = self.nextMeshHlc();
        const event_time_ms = mesh_clock_mod.MeshClock.physicalOf(event_hlc);
        var msgid_buf: [msgid_mod.id_len]u8 = undefined;
        var message_id = msgid_mod.fromMeshEvent(self.config.node_id, event_hlc, &msgid_buf);

        // IRCv3 echo-message: a sender that negotiated the cap also receives its
        // own message back, byte-identical to what recipients see (`msg`).
        const echo = conn.session.hasCap(.echo_message);

        if (world_model.isChannelName(chan)) {
            const speech = try self.channelSpeechGate(id, conn, target, chan, text, is_notice, min_rank, true);
            if (speech == .deny) return;
            if (!is_notice and min_rank == 0 and self.captureFirstHold(conn, chan, text)) return;
            const opmod_route = speech == .opmoderate;
            // Fantasy bot: a speaker's PRIVMSG beginning with '!' may invoke the
            // weather/news bot. The message is still delivered to the channel
            // normally below; this only posts the server's answer as a NOTICE.
            // Required rooms never treat ciphertext as a bot command.
            if (!is_notice and self.channelEncryptionPolicy(chan) != .required and
                text.len > 1 and text[0] == '!')
            {
                self.handleFantasy(id, conn, chan, text);
            }
            // +f noformat (IRCX NOFORMAT; chm_nocolour): strip mIRC
            // colour/formatting from the message body for every recipient.
            // Buffer sized to the deliverable body ceiling so an oversized
            // colour-formatted PRIVMSG still strips (fail-closed on policy)
            // rather than silently keeping the raw codes (CWE-400 / CWE-693).
            var nf_text_buf: [default_reply_bytes]u8 = undefined;
            var nf_msg_buf: [default_reply_bytes]u8 = undefined;
            var eff_text = text;
            var eff_msg = msg;
            if (self.channelEncryptionPolicy(chan) != .required and
                self.world.channelHasExtFlag(chan, .noformat) and color_strip.hasFormatting(text))
            {
                if (color_strip.stripFormattingWith(.{ .max_output_bytes = default_reply_bytes }, text, &nf_text_buf)) |clean| {
                    var nf_prefix_buf: [320]u8 = undefined;
                    if (clientPrefix(conn, &nf_prefix_buf)) |pfx| {
                        if (formatMessage(&nf_msg_buf, pfx, command, &.{target}, clean)) |rebuilt| {
                            eff_text = clean;
                            eff_msg = rebuilt;
                        } else |_| {}
                    } else |_| {}
                } else |_| {}
            }
            if (opmod_route) {
                // +U is intentionally a local moderation side-channel: it has
                // no mesh authority, no Lotus row, and no cross-node flood.
                var held_time_buf: [40]u8 = undefined;
                const held_tags = MsgTags{ .time_value = serverTimeValueAt(&held_time_buf, event_time_ms), .account = conn.session.account(), .client_tags = clean_client_tags, .msgid = message_id, .is_bot = conn.session.isBot() };
                const fanout_started_at_ms = if (!is_notice) self.nowMs() else 0;
                {
                    defer if (!is_notice) self.recordElapsedLatency(.privmsg_fanout, fanout_started_at_ms);
                    try self.broadcastChannelMinRank(chan, held_tags, eff_msg, id, 2, .ordinary);
                }
                self.publishModerationHeld(chan, conn, eff_text);
                return;
            }
            // delivery_ids feeds durable MESSAGE_V2 ADS1. When authoring is
            // active, admit MUST succeed before broadcast — fail closed so mesh
            // and local views stay consistent. mIRC formatting is legal body
            // content (message_relay.validTextField); ADS1 spool soft-fails
            // inside admitAuthoredRelayV2 without aborting mesh publish.
            var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
            defer delivery_ids.deinit(self.allocator);
            self.collectChannelDeliveryIds(
                chan,
                min_rank,
                if (echo) null else id,
                null,
                &delivery_ids,
            ) catch {
                if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete attachment delivery set");
                return;
            };
            var accepted_v2: ?AcceptedAuthoredRelayV2 = null;
            defer if (accepted_v2) |*accepted| accepted.deinit(self.allocator);
            if (self.authoredRelayV2Configured()) {
                var authored_prefix_buf: [320]u8 = undefined;
                const authored_prefix = clientPrefix(conn, &authored_prefix_buf) catch return;
                const history_plan: ?RelayV2History = if (min_rank == 0) .{
                    .target = chan,
                    .sender = authored_prefix,
                    .text = eff_text,
                    .command = command,
                    .client_tags = clean_client_tags,
                    .timestamp_ms = event_time_ms,
                } else null;
                accepted_v2 = self.admitAuthoredRelayV2(
                    if (is_notice) .notice else .privmsg,
                    chan,
                    min_rank,
                    authored_prefix,
                    conn.session.account() orelse "",
                    clean_client_tags orelse "",
                    "",
                    eff_text,
                    .channel,
                    "",
                    self.portableSessionTokenForClient(id, conn),
                    (self.world.memberModes(chan, worldIdFromClient(id)) orelse
                        world_model.MemberModes.empty()).bits,
                    null,
                    event_hlc,
                    history_plan,
                    .{ .recipients = delivery_ids.items, .line = eff_msg, .is_bot = conn.session.isBot() },
                ) catch {
                    if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Mesh durable admit failed; message not sent — check mesh peers and retry");
                    return;
                };
                if (accepted_v2) |accepted| {
                    message_id = msgid_mod.fromStableId(accepted.relay_id, &msgid_buf);
                } else {
                    if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Mesh authority rejected the message; not delivered — retry or contact opers");
                    return;
                }
            }
            const delivery_mode: TaggedDeliveryMode = if (accepted_v2) |accepted|
                accepted.deliveryMode()
            else
                .ordinary;
            var time_buf: [40]u8 = undefined;
            const ctags = MsgTags{ .time_value = serverTimeValueAt(&time_buf, event_time_ms), .account = conn.session.account(), .client_tags = clean_client_tags, .msgid = message_id, .is_bot = conn.session.isBot() };
            const fanout_started_at_ms = if (!is_notice) self.nowMs() else 0;
            {
                defer if (!is_notice) self.recordElapsedLatency(.privmsg_fanout, fanout_started_at_ms);
                if (min_rank == 0) {
                    try self.broadcastChannelTagged(
                        chan,
                        ctags,
                        eff_msg,
                        id,
                        delivery_mode,
                    );
                } else {
                    try self.broadcastChannelMinRank(
                        chan,
                        ctags,
                        eff_msg,
                        id,
                        min_rank,
                        delivery_mode,
                    );
                }
            }
            if (echo) try self.deliverTaggedMode(
                id,
                ctags,
                eff_msg,
                delivery_mode,
            );
            // Era 3 C3: closed-tab Web Push for nick mentions (best-effort).
            if (!is_notice and min_rank == 0) {
                self.webpushNotifyChannelMentions(chan, conn.session.displayName(), eff_text);
            }
            // Cross-node relay: forward this channel message to mesh peers so
            // remote members of `chan` receive it. Loop-guarded; the far side
            // delivers only to its own local members. Best-effort.
            {
                var pbuf: [320]u8 = undefined;
                if (clientPrefix(conn, &pbuf)) |prefix| {
                    _ = self.relay_seen.observe(self.config.node_id, event_hlc); // drop an echo back
                    var relay_tag_buf: [256]u8 = undefined;
                    var relay_msg = s2s_link.RelayMessage{
                        .verb = if (is_notice) .notice else .privmsg,
                        .target = chan,
                        .min_rank = min_rank,
                        .source_nick = conn.session.displayName(),
                        .source_prefix = prefix,
                        .account = conn.session.account() orelse "",
                        .tags = clientOnlyTags(clean_client_tags orelse "", &relay_tag_buf),
                        .text = eff_text,
                        .origin_node = self.config.node_id,
                        .hlc = event_hlc,
                    };
                    var pk_buf: [message_relay.pubkey_len]u8 = undefined;
                    var sig_buf: [message_relay.sig_len]u8 = undefined;
                    self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
                    if (accepted_v2) |accepted| self.forwardAcceptedRelayV2(accepted.wire);
                    _ = self.relayLegacyToPeers(
                        relay_msg,
                        .{ .channel = chan },
                        accepted_v2 != null,
                    ); // route_table: only peers with members
                } else |_| {}
            }
            // Record into the CHATHISTORY ring (full status-prefix stripped: bare
            // chan). Only the message body + sender prefix are stored.
            if (min_rank == 0) {
                if (accepted_v2 != null) {
                    self.indexHistoryBody(message_id, eff_text, clean_client_tags);
                    var history_prefix_buf: [256]u8 = undefined;
                    if (clientPrefix(conn, &history_prefix_buf)) |history_prefix|
                        self.chanstatsMessage(chan, history_prefix, command, eff_text)
                    else |_| {}
                } else {
                    self.recordHistoryAt(chan, conn, message_id, command, eff_text, clean_client_tags, event_time_ms);
                }
                // Record the conversation label in the channel's browsable topic
                // registry (mesh-propagated channel PROP), gated to rank-0 so the
                // registry stays aligned with the history CHATHISTORY can filter
                // (a STATUSMSG's op-only line is not browsable). Best-effort.
                if (topic_label) |lbl| self.registerChannelTopic(chan, lbl);
            }
            return;
        }

        const recipient = self.world.findNick(target) orelse {
            // Not local: relay to mesh peers so the node that owns this nick can
            // deliver (loop-guarded; a truly-nonexistent nick is dropped far-side).
            if (self.hasEstablishedPeer() or self.detachedReplicaTokenForNick(target) != null) {
                var pbuf2: [320]u8 = undefined;
                if (clientPrefix(conn, &pbuf2)) |prefix| {
                    const recipient_token = self.detachedReplicaTokenForNick(target);
                    const target_route_known = self.meshNickHomeNode(target) != null or recipient_token != null;
                    if (!target_route_known) {
                        if (!is_notice) try queueNumeric(conn, .ERR_NOSUCHNICK, &.{target}, "No such nick");
                        return;
                    }
                    var local_sender_ids: std.ArrayList(client_model.ClientId) = .empty;
                    defer local_sender_ids.deinit(self.allocator);
                    self.collectAttachedExactTokenClients(id, conn, &local_sender_ids) catch {
                        if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete session sender set");
                        return;
                    };
                    var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
                    defer delivery_ids.deinit(self.allocator);
                    self.collectDirectDeliveryIds(
                        &.{},
                        local_sender_ids.items,
                        id,
                        echo,
                        null,
                        &delivery_ids,
                    ) catch {
                        if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete attachment delivery set");
                        return;
                    };
                    const exact_sender_token: ?sessions_mod.Token = if (conn.session.account()) |account| blk: {
                        const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse break :blk null;
                        break :blk if (tokenIsNull(handle.token)) null else handle.token;
                    } else null;
                    var accepted_v2: ?AcceptedAuthoredRelayV2 = null;
                    defer if (accepted_v2) |*accepted| accepted.deinit(self.allocator);
                    // Fail closed: durable admit required when authoring active.
                    if (recipient_token != null and self.authoredRelayV2Configured()) {
                        accepted_v2 = self.admitAuthoredRelayV2(
                            if (is_notice) .notice else .privmsg,
                            target,
                            0,
                            prefix,
                            conn.session.account() orelse "",
                            clean_client_tags orelse "",
                            "",
                            text,
                            .direct,
                            "",
                            exact_sender_token,
                            null,
                            recipient_token,
                            event_hlc,
                            null,
                            .{ .recipients = delivery_ids.items, .line = msg, .is_bot = conn.session.isBot() },
                        ) catch {
                            if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Mesh durable admit failed; message not sent — check mesh peers and retry");
                            return;
                        };
                        if (accepted_v2 == null) {
                            if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Mesh authority rejected the message; not delivered — retry or contact opers");
                            return;
                        }
                        if (accepted_v2) |accepted| {
                            message_id = msgid_mod.fromStableId(accepted.relay_id, &msgid_buf);
                        }
                    }
                    _ = self.relay_seen.observe(self.config.node_id, event_hlc);
                    var relay_tag_buf: [256]u8 = undefined;
                    var relay_msg = s2s_link.RelayMessage{
                        .verb = if (is_notice) .notice else .privmsg,
                        .target = target,
                        .source_nick = conn.session.displayName(),
                        .source_prefix = prefix,
                        .account = conn.session.account() orelse "",
                        .tags = clientOnlyTags(clean_client_tags orelse "", &relay_tag_buf),
                        .text = text,
                        .origin_node = self.config.node_id,
                        .hlc = event_hlc,
                    };
                    var pk_buf: [message_relay.pubkey_len]u8 = undefined;
                    var sig_buf: [message_relay.sig_len]u8 = undefined;
                    self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
                    // Route to the target's ordinary nick home or detached
                    // portable replica, plus the author's other portable-session
                    // peers so every sender attachment observes the sent event.
                    // `target_route_known` was checked independently: a sender-
                    // only replica route can never hide an unreachable target.
                    const sender_token = self.portableSessionTokenForClient(id, conn);
                    const relay_scope: RelayScope = if (recipient_token orelse sender_token) |token|
                        .{ .session_nick = .{
                            .nick = target,
                            .token = token,
                            .also_token = if (recipient_token != null) sender_token else null,
                        } }
                    else
                        .{ .nick = target };
                    if (accepted_v2) |accepted| self.forwardAcceptedRelayV2(accepted.wire);
                    const legacy_relays = self.relayLegacyToPeers(
                        relay_msg,
                        relay_scope,
                        accepted_v2 != null,
                    );
                    if (legacy_relays == 0 and accepted_v2 == null) {
                        if (!is_notice) try queueNumeric(conn, .ERR_NOSUCHNICK, &.{target}, "No such nick");
                        return;
                    }
                    var et_buf: [40]u8 = undefined;
                    const etags = MsgTags{ .time_value = serverTimeValueAt(&et_buf, event_time_ms), .account = conn.session.account(), .client_tags = clean_client_tags, .msgid = message_id, .is_bot = conn.session.isBot() };
                    const remote_dm_mode: TaggedDeliveryMode = if (accepted_v2) |accepted|
                        accepted.deliveryMode()
                    else if (self.authoredRelayV2Configured() and recipient_token != null)
                        .mesh_busy_local
                    else
                        .ordinary;
                    for (local_sender_ids.items) |logical_id| {
                        if (logical_id.eql(id) and !echo) continue;
                        self.deliverTaggedMode(
                            logical_id,
                            etags,
                            msg,
                            remote_dm_mode,
                        ) catch {};
                    }
                    if (conn.session.account()) |sender_account| {
                        self.deliverSessionSyncSiblingsNick(sender_account, exact_sender_token, null, etags, msg, id, null, conn.session.displayName(), null);
                    }
                    return;
                } else |_| {}
            }
            if (!is_notice) try queueNumeric(conn, .ERR_NOSUCHNICK, &.{target}, "No such nick");
            return;
        };
        const recipient_id = clientIdFromWorld(recipient);
        const recipient_conn = self.connFor(recipient_id);
        // +R regonly-pm: the recipient rejects PMs/notices from unauthenticated
        // senders. Logged-in senders and opers always pass.
        if (conn.session.account() == null and !conn.session.isOper()) {
            if (recipient_conn) |rconn| {
                if (rconn.session.umodes.contains(.regonly_pm)) {
                    if (!is_notice) try queueNumeric(conn, .ERR_NEEDREGGEDNICK, &.{target}, "Cannot message this user (+R: identify to a registered account)");
                    return;
                }
            }
        }
        if (!is_notice and isBlockableCtcp(text)) {
            if (recipient_conn) |rconn| {
                if (rconn.session.umodes.contains(.no_ctcp)) {
                    try self.failReply(conn, command, "CTCP_BLOCKED", "Cannot message this user (+C: no CTCP)");
                    return;
                }
            }
        }
        // +g callerid: a recipient in +g mode only receives DMs from senders on
        // its ACCEPT list. Unaccepted senders are dropped: the sender gets 716
        // (ERR_CANTSENDTOUSER) and the recipient is notified once with 718
        // (RPL_UMODEGMSG). Opers and same-account siblings bypass the gate, and a
        // client can always message its own nick.
        if (recipient_conn) |rconn| {
            if (rconn.session.umodes.contains(.callerid)) {
                const sender_nick = conn.session.displayName();
                const self_msg = recipient_id.eql(id);
                const accepted = self.accepts.contains(target, sender_nick) catch false;
                const sender_account = conn.session.account();
                const same_account = if (sender_account) |sa|
                    if (rconn.session.account()) |ra| std.mem.eql(u8, sa, ra) else false
                else
                    false;
                const bypass = self_msg or accepted or conn.session.isOper() or same_account;
                if (!bypass) {
                    if (!is_notice) {
                        try queueNumeric(conn, .ERR_CANTSENDTOUSER, &.{target}, "is in +g mode (must be accepted)");
                        try queueNumeric(conn, .RPL_TARGNOTIFY, &.{target}, "has been informed that you messaged them");
                    }
                    // 718 carries the sender's nick and user@host as distinct
                    // tokens (the RPL_UMODEGMSG numeric layout) so the
                    // recipient's client can populate an accept-prompt. A client
                    // parsing by position would otherwise read a literal "G".
                    var umask_buf: [256]u8 = undefined;
                    const sender_uh = std.fmt.bufPrint(&umask_buf, "{s}@{s}", .{ conn.session.username(), hostOf(conn) }) catch sender_nick;
                    try queueNumeric(rconn, .RPL_UMODEGMSG, &.{ sender_nick, sender_uh }, "is messaging you, and you have umode +g set. Use ACCEPT to allow");
                    // 718 is queued onto the recipient's connection (not the one
                    // being processed), so its send buffer must be armed explicitly
                    // or the bytes never reach the socket this reactor cycle.
                    try self.armSendIfNeeded(rconn);
                    return;
                }
            }
        }
        // SILENCE: if the recipient has silenced a mask matching the sender, drop
        // the message silently (no error to the sender — ircu/charybdis behavior).
        {
            var smask_buf: [256]u8 = undefined;
            const sender_mask = try clientPrefix(conn, &smask_buf);
            if (self.silence.isSilenced(target, sender_mask)) return;
        }

        // Snapshot both exact logical-session recipient sets before the first
        // delivery. Allocation failure is retryable for PRIVMSG and silent for
        // NOTICE; it must never expose a partial account/nick-selected fan-out.
        var recipient_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer recipient_ids.deinit(self.allocator);
        if (recipient_conn) |rconn| {
            self.collectAttachedExactTokenClients(recipient_id, rconn, &recipient_ids) catch {
                if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete session recipient set");
                return;
            };
        } else {
            recipient_ids.append(self.allocator, recipient_id) catch {
                if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete session recipient set");
                return;
            };
        }
        const same_logical_session = if (recipient_conn) |rconn|
            self.clientsShareExactToken(id, conn, recipient_id, rconn)
        else
            false;
        const sender_exact_token: ?sessions_mod.Token = if (conn.session.account()) |account| blk: {
            const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(id)) orelse break :blk null;
            break :blk if (tokenIsNull(handle.token)) null else handle.token;
        } else null;
        const recipient_exact_token: ?sessions_mod.Token = if (recipient_conn) |rconn| if (rconn.session.account()) |account| blk: {
            const handle = self.sessions.resumeHandleForClient(account, monitorIdFromClient(recipient_id)) orelse break :blk null;
            break :blk if (tokenIsNull(handle.token)) null else handle.token;
        } else null else null;
        var sender_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer sender_ids.deinit(self.allocator);
        if (!same_logical_session) {
            self.collectAttachedExactTokenClients(id, conn, &sender_ids) catch {
                if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete session sender set");
                return;
            };
        }
        var delivery_ids: std.ArrayList(client_model.ClientId) = .empty;
        defer delivery_ids.deinit(self.allocator);
        self.collectDirectDeliveryIds(
            recipient_ids.items,
            sender_ids.items,
            id,
            echo,
            null,
            &delivery_ids,
        ) catch {
            if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Could not resolve the complete attachment delivery set");
            return;
        };
        const recipient_account = if (recipient_conn) |rconn| rconn.session.account() else null;
        var accepted_direct_v2: ?AcceptedAuthoredRelayV2 = null;
        defer if (accepted_direct_v2) |*accepted| accepted.deinit(self.allocator);
        var direct_history_key_buf: [320]u8 = undefined;
        var direct_history_key: ?[]const u8 = null;
        if (recipient_exact_token != null and self.authoredRelayV2Configured()) {
            const authored_prefix = try clientPrefix(conn, &prefix_buf);
            const history_plan: ?RelayV2History = if (!is_notice)
                if (dmHistoryKey(
                    conn.session.displayName(),
                    conn.session.account(),
                    target,
                    recipient_account,
                    &direct_history_key_buf,
                )) |key| blk: {
                    direct_history_key = key;
                    break :blk .{
                        .target = key,
                        .sender = authored_prefix,
                        .text = text,
                        .command = command,
                        .client_tags = clean_client_tags,
                        .timestamp_ms = event_time_ms,
                    };
                } else null
            else
                null;
            // Fail closed on durable DM admit — same contract as channel.
            accepted_direct_v2 = self.admitAuthoredRelayV2(
                if (is_notice) .notice else .privmsg,
                target,
                0,
                authored_prefix,
                conn.session.account() orelse "",
                clean_client_tags orelse "",
                "",
                text,
                .direct,
                "",
                sender_exact_token,
                null,
                recipient_exact_token,
                event_hlc,
                history_plan,
                .{ .recipients = delivery_ids.items, .line = msg, .is_bot = conn.session.isBot() },
            ) catch {
