                }
            } else {
                if (!is_notice) try self.failReply(conn, command, "TEMPORARILY_UNAVAILABLE", "Mesh authority rejected the message; not delivered — retry or contact opers");
                return;
            }
        }
        const direct_delivery_mode: TaggedDeliveryMode = if (accepted_direct_v2) |accepted|
            accepted.deliveryMode()
        else if (self.authoredRelayV2Configured() and recipient_exact_token != null)
            .mesh_busy_local
        else
            .ordinary;
        var time_buf: [40]u8 = undefined;
        const dtags = MsgTags{ .time_value = serverTimeValueAt(&time_buf, event_time_ms), .account = conn.session.account(), .client_tags = clean_client_tags, .msgid = message_id, .is_bot = conn.session.isBot() };
        // Every exact recipient attachment participates independently. A full or
        // closing owner's queue cannot prevent its siblings from receiving the
        // event. Same-account/same-nick DIFFERENT tokens are absent by design.
        for (recipient_ids.items) |logical_id| self.deliverTaggedMode(
            logical_id,
            dtags,
            msg,
            direct_delivery_mode,
        ) catch {};
        const sender_account = conn.session.account();
        const same_account = if (sender_account) |sa|
            if (recipient_account) |ra| std.ascii.eqlIgnoreCase(sa, ra) else false
        else
            false;
        if (!same_logical_session) {
            for (sender_ids.items) |logical_id| {
                if (logical_id.eql(id) and !echo) continue;
                self.deliverTaggedMode(
                    logical_id,
                    dtags,
                    msg,
                    direct_delivery_mode,
                ) catch {};
            }
        }
        if (same_account) {
            if (sender_account) |account| self.deliverSessionSyncSiblingsNick(
                account,
                recipient_exact_token,
                sender_exact_token,
                dtags,
                msg,
                id,
                recipient_id,
                target,
                conn.session.displayName(),
            );
        } else {
            if (recipient_account) |account| self.deliverSessionSyncSiblingsNick(
                account,
                recipient_exact_token,
                null,
                dtags,
                msg,
                recipient_id,
                id,
                target,
                null,
            );
            if (sender_account) |account| self.deliverSessionSyncSiblingsNick(
                account,
                sender_exact_token,
                null,
                dtags,
                msg,
                id,
                recipient_id,
                conn.session.displayName(),
                null,
            );
        }
        // Cross-node multi-client relay: the target nick resolved LOCALLY, but
        // the same identity may hold live sessions on other mesh nodes (one nick
        // on many devices — by design), so a local-only short-circuit here
        // split-brains the DM. Forward it: the peer's `deliverRelay` DM branch +
        // same-nick sibling fan-out complete delivery to the remote devices, and
        // its sender mirror hands the sent-copy to the author's remote sessions.
        // Loop-guarded via `relay_seen`; scoped via route_table, so a
        // single-homed nick matches zero links (per-link route tables only hold
        // the direct peer's members) and this is a cheap no-op in the common
        // single-device case. Best-effort, like the channel relay above.
        if (self.hasEstablishedPeer()) {
            var rp_buf: [320]u8 = undefined;
            if (clientPrefix(conn, &rp_buf)) |prefix| {
                // Route by the recipient's CANONICAL nick (the per-link nick
                // index is an exact-key map); fall back to the typed target.
                const route_nick = if (recipient_conn) |rconn| rconn.session.displayName() else target;
                _ = self.relay_seen.observe(self.config.node_id, event_hlc); // drop an echo back
                var relay_tag_buf: [256]u8 = undefined;
                var relay_msg = s2s_link.RelayMessage{
                    .verb = if (is_notice) .notice else .privmsg,
                    .target = route_nick,
                    .source_nick = conn.session.displayName(),
                    .source_prefix = prefix,
                    .account = conn.session.account() orelse "",
                    .tags = clientOnlyTags(clean_client_tags orelse "", &relay_tag_buf),
                    .text = text,
                    .origin_node = self.config.node_id,
                    .hlc = event_hlc,
                };
                var pk_buf: [message_relay.pubkey_len]u8 = undefined;
                var sig_buf: [message_relay.sig_len]u8 = undefined;
                self.signRelayOrigin(&relay_msg, &pk_buf, &sig_buf);
                // A portable reusable session has an authenticated token->peer
                // route independent of nick residence. That route is essential
                // when the remote attachment has not published an account-key
                // residence proof: the F1 gate correctly refuses to home its
                // same-account nick, but the signed migration capsule still
                // authorizes delivery to this exact logical session on that peer.
                const recipient_token = if (recipient_conn) |rconn| self.portableSessionTokenForClient(recipient_id, rconn) else null;
                const sender_token = self.portableSessionTokenForClient(id, conn);
                const relay_scope: RelayScope = if (recipient_token orelse sender_token) |token|
                    .{ .session_nick = .{
                        .nick = route_nick,
                        .token = token,
                        .also_token = if (recipient_token != null) sender_token else null,
                    } }
                else
                    .{ .nick = route_nick };
                if (accepted_direct_v2) |accepted| self.forwardAcceptedRelayV2(accepted.wire);
                _ = self.relayLegacyToPeers(
                    relay_msg,
                    relay_scope,
                    accepted_direct_v2 != null,
                );
            } else |_| {}
        }
        if (!is_notice and accepted_direct_v2 == null) {
            var dm_key_buf: [320]u8 = undefined;
            if (dmHistoryKey(conn.session.displayName(), conn.session.account(), target, recipient_account, &dm_key_buf)) |store_target| {
                self.recordHistoryAt(store_target, conn, message_id, command, text, clean_client_tags, event_time_ms);
            }
        }

        // RFC 1459: a PRIVMSG (not NOTICE) to an away user returns RPL_AWAY so
        // the sender sees the auto-reply. NOTICE never auto-responds.
        if (std.ascii.eqlIgnoreCase(command, "PRIVMSG")) {
            if (recipient_conn) |rconn| {
                try self.autoReplyCtcp(conn, rconn, text);
                if (rconn.session.awayMessage()) |reason| {
                    try queueNumeric(conn, .RPL_AWAY, &.{target}, reason);
                }
            }
        }
    }

    fn autoReplyCtcp(self: *LinuxServer, sender: *ConnState, recipient: *ConnState, text: []const u8) !void {
        const ctcp = @import("../proto/ctcp.zig");
        const view = ctcp.parseFirst(.privmsg, text) catch return;
        const req = view orelse return;
        if (req.id == .action) return;

        var ping_arg_buf: [256]u8 = undefined;
        var time_buf: [40]u8 = undefined;
        const reply_arg: ?[]const u8 = switch (req.id) {
            .version => server_version,
            .ping => req.dequoteArg(&ping_arg_buf) catch return,
            .time => serverTimeValue(&time_buf),
            .clientinfo => "ACTION CLIENTINFO PING SOURCE TIME VERSION",
            .source => "https://github.com/devinkbrown/onyx-server",
            else => return,
        };
        const command_name = ctcp.commandName(req.id) orelse return;

        var payload_buf: [512]u8 = undefined;
        const payload = ctcp.buildPayload(command_name, reply_arg, &payload_buf) catch return;
        var prefix_buf: [256]u8 = undefined;
        var line_buf: [default_reply_bytes]u8 = undefined;
        const line = try formatMessage(&line_buf, try clientPrefix(recipient, &prefix_buf), "NOTICE", &.{sender.session.displayName()}, payload);
        try appendToConn(sender, line);
        _ = self;
    }

    pub fn handleTopic(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        if (parsed.param_count < 1) {
            try queueNumeric(conn, .ERR_NEEDMOREPARAMS, &.{"TOPIC"}, "Not enough parameters");
            return;
        }

        const channel = parsed.paramSlice()[0];
        if (!self.world.channelExists(channel)) {
            try queueNumeric(conn, .ERR_NOSUCHCHANNEL, &.{channel}, "No such channel");
            return;
        }

        if (parsed.param_count == 1) {
            try self.sendTopicReply(conn, channel);
            return;
        }

        const topic_setter = self.world.memberModes(channel, worldIdFromClient(id)) orelse {
            try queueNumeric(conn, .ERR_NOTONCHANNEL, &.{channel}, "You're not on that channel");
            return;
        };
        // +t: only channel operators (op or higher) may change the topic — unless
        // the actor holds the oper_override privilege (network admin override).
        // TOPICLOCK (CHANNEL SET): a registered channel's persistent topic lock
        // gates the topic exactly like +t even when +t is not set live, so the
        // lock holds across recreation. The oper-override still bypasses it.
        const topic_locked = if (self.account_services) |svc|
            svc.channelFlagSet(channel, services_mod.channel_flag_topiclock)
        else
            false;
        if ((self.world.channelHasFlag(channel, .topic_ops) or topic_locked) and
            !topic_setter.isOperator() and !conn.session.hasPriv(.oper_override))
        {
            try queueNumeric(conn, .ERR_CHANOPRIVSNEEDED, &.{channel}, "You're not channel operator");
            return;
        }

        // Cap the topic at the configured TOPICLEN (advertised in ISUPPORT).
        // Truncate on a UTF-8 codepoint boundary so the stored topic stays valid
        // under UTF8ONLY, and broadcast the truncated form so every member sees
        // the same text.
        const text = utf8TruncateBytes(parsed.paramSlice()[1], self.config.topiclen);
        var setter_buf: [256]u8 = undefined;
        const setter = try clientPrefix(conn, &setter_buf);
        const set_at = @divFloor(platform.realtimeMillis(), 1000);
        try self.world.setTopic(channel, text, setter, set_at);
        // KEEPTOPIC: persist the new topic — with the setter and set-time that set
        // it — for a registered channel that opted in, so recreation restores all
        // three (not a fake serverName()/now).
        if (self.account_services) |kt| kt.chanKeepTopicSave(channel, text, setter, set_at) catch {};

        var prefix_buf: [256]u8 = undefined;
        var msg_buf: [default_reply_bytes]u8 = undefined;
        const msg = try formatMessage(&msg_buf, try clientPrefix(conn, &prefix_buf), "TOPIC", &.{channel}, text);
        try self.broadcastChannel(channel, msg, null);
        try self.publishChannelEvent("TOPIC", channel);
        // draft/event-playback: record the topic change in channel history so it
        // replays as a TOPIC event (`:setter TOPIC #chan :topic`) to event-playback
        // clients. The event body is the full post-command text (target + trailing).
        var topic_ev_buf: [640]u8 = undefined;
        if (std.fmt.bufPrint(&topic_ev_buf, "{s} :{s}", .{ channel, text })) |body| {
            self.recordHistoryEvent(channel, conn, "TOPIC", body);
        } else |_| {}
        // Propagate the topic across the mesh so remote members see it live.
        self.announceTopic(channel, text, setter, set_at, text.len != 0);
    }

    /// Truncate `s` to at most `max` bytes without splitting a UTF-8 codepoint:
    /// if the cut would land inside a multibyte sequence, back off to its start.
    fn utf8TruncateBytes(s: []const u8, max: usize) []const u8 {
        if (s.len <= max) return s;
        var i = max;
        while (i > 0 and (s[i] & 0xC0) == 0x80) i -= 1; // skip back over continuation bytes
        return s[0..i];
    }

    pub fn handleQuit(self: *LinuxServer, id: client_model.ClientId, conn: *ConnState, parsed: *const irc_line.LineView) !void {
        const reason = if (parsed.param_count >= 1) parsed.paramSlice()[0] else "Client quit";
        // QUIT closes this transport, not the shared logical identity. If another
        // attachment is live, hand ownership/state to it and let the ordinary
        // close path detach this row without emitting offline/QUIT for the user.
        const handed_off = self.handoffLiveSessionIdentity(id, conn) catch {
            retainCloseReason(conn, reason);
            conn.session_handoff_retry = true;
            conn.closing = true;
            return;
        };
        if (handed_off) {
            conn.session_handoff_complete = true;
            conn.session_handoff_checked = true;
            conn.closing = true;
            return;
        }
        conn.session_handoff_checked = true;
        // A live other-origin Store row for this exact portable token is the
        // remote equivalent of a local sibling. Leave World intact so closeConn
        // can retain/ship the complete image, then suppress identity-wide QUIT.
        if (self.connHasExactRemoteSessionAuthority(id, conn)) {
            conn.closing = true;
            return;
        }
        // Clean QUIT normally removes World before closeConn runs. Retain and
        // publish the full pre-removal image now; on OOM, leave World untouched
        // and let closeConn take the ordinary abrupt-drop path instead.
        if (conn.session.account() != null and !self.prepareCleanSessionDetach(id, conn)) {
            conn.closing = true;
            return;
        }
        // SEEN: record this account's logout for the LASTSEEN history.
        if (conn.session.account()) |acct| {
            var mb: [256]u8 = undefined;
            const mask = clientPrefix(conn, &mb) catch "";
            self.recordSeen(acct, mask, .logout);
        }
        self.publishUserDisconnectEvent(conn, reason) catch {};
        self.recordWhowas(conn); // before removeClient: snapshot the live identity
        try self.broadcastQuit(id, conn, reason);
        self.publishChannelDestroyEventsForClient(id);
        self.holdNickOnExit(id, conn); // hold the nick before the world drops it
        self.world.removeClient(worldIdFromClient(id));
        conn.closing = true;
    }

    fn sendTopicReply(self: *LinuxServer, conn: *ConnState, channel: []const u8) !void {
        if (conn.session.registered()) {
            if (self.world.topicInfo(channel)) |topic| {
                try queueNumeric(conn, .RPL_TOPIC, &.{channel}, topic.text);
                var ts_buf: [32]u8 = undefined;
                const ts = std.fmt.bufPrint(&ts_buf, "{d}", .{topic.set_at}) catch "0";
                try queueNumeric(conn, .RPL_TOPICWHOTIME, &.{ channel, topic.setter, ts }, "");
            } else {
                try queueNumeric(conn, .RPL_NOTOPIC, &.{channel}, "No topic is set");
            }
        }
    }

    /// RPL_BANLIST (367) for each +b mask, terminated by RPL_ENDOFBANLIST (368).
    fn sendBanList(self: *LinuxServer, conn: *ConnState, channel: []const u8) !void {
        try self.sendMaskList(conn, channel, self.world.bansOf(channel), .RPL_BANLIST, .RPL_ENDOFBANLIST, "End of channel ban list");
    }

    /// Emit a channel mask list (one `list_code` per mask, then `end_code`).
    /// Shared by +b (367/368), +e (348/349), +I (346/347).
    fn sendMaskList(
        self: *LinuxServer,
        conn: *ConnState,
        channel: []const u8,
        masks: ?[]const world_model.ListEntry,
        list_code: Numeric,
        end_code: Numeric,
        end_text: []const u8,
    ) !void {
        _ = self;
        if (masks) |entries| {
            for (entries) |entry| {
                var ts_buf: [32]u8 = undefined;
                const ts = std.fmt.bufPrint(&ts_buf, "{d}", .{entry.set_at}) catch "0";
                try queueNumeric(conn, list_code, &.{ channel, entry.mask, entry.setter, ts }, "");
            }
        }
        try queueNumeric(conn, end_code, &.{channel}, end_text);
    }

    /// Map a member's channel-status modes to an auditorium visibility rank.
    fn auditoriumRank(mm: world_model.MemberModes) auditorium.Rank {
        if (mm.isOperator()) return .op;
        if (mm.contains(.voice)) return .voice;
        return .regular;
    }

    /// Display projection of a live signed mesh grant. Privilege bits of 0 are
    /// a tombstone. Never use this for KICK/DATA/session authority.
    const RemoteOperDisplay = struct {
        is_admin: bool,
        is_override: bool,
        title: []const u8,
    };

    fn remoteOperDisplay(self: *LinuxServer, account: []const u8) ?RemoteOperDisplay {
        if (account.len == 0) return null;
        const grant = self.oper_grants.lookup(account, self.grantNowU64()) orelse return null;
        if (grant.privilege_bits == 0) return null;
        const priv = oper_mod.OperPrivileges.fromBits(grant.privilege_bits);
        return .{
            .is_admin = priv.has(.server_admin),
            .is_override = priv.has(.oper_override),
            .title = grant.title,
        };
    }

    fn remoteHasOverridePrefix(self: *LinuxServer, account: []const u8) bool {
        const display = self.remoteOperDisplay(account) orelse return false;
        return display.is_override;
    }

    /// Whether `nick` is a locally projected IRC operator holding oper_override.
    /// Authority only: KICK immunity, DATA admission, local NAMES `*`. Remote
    /// display uses `remoteOperDisplay` / `remoteHasOverridePrefix` instead.
    fn isOverrideOper(self: *LinuxServer, nick: []const u8) bool {
        for (self.reactors) |*reactor| {
            var it = reactor.clients.iterator();
            while (it.next()) |entry| {
                const c = entry.value;
                if (c.s2s != null or c.s2s_secured != null) continue;
                if (!c.session.registered()) continue;
                if (c.session.hasPriv(.oper_override) and std.ascii.eqlIgnoreCase(c.session.displayName(), nick)) return true;
            }
        }
        return false;
    }

    fn sendNames(self: *LinuxServer, conn: *ConnState, channel: []const u8) !void {
        return self.sendNamesWithProjection(conn, channel, null);
    }

    /// Render NAMES against the current World plus an optional not-yet-committed
    /// exact-session membership image. SESSION RESUME uses the projection while
    /// its World/SessionStore tickets are still abortable, allowing the complete
    /// 353..366 plaintext batch and its SendQ storage to be prepared before the
    /// transaction becomes visible.
    fn sendNamesWithProjection(
        self: *LinuxServer,
        conn: *ConnState,
        channel: []const u8,
        projection: ?ResumeNamesProjection,
    ) !void {
        // Render NAMES via the names_reply module: each member carries its status
        // prefixes (all of them when the requester negotiated multi-prefix, else
        // only the highest) and optionally nick!user@host (userhost-in-names).
        //
        // Bound collection by the exact plaintext room remaining in the current
        // destination. A NAMES entry has a non-empty nick and consumes at least a
        // token byte plus a separator; accepting more unique identities than
        // this two-byte bound could never produce a complete burst. Unlike the
        // old fixed 512 stack array, this scales to every roster that can actually
        // fit the caller's configured SendQ or transactional reply capture.
        const plaintext_budget = if (conn.reply_capture) |capture|
            capture.buf.len - capture.len
        else budget: {
            const inline_queued = conn.send_len - conn.send_offset;
            const queued = std.math.add(usize, inline_queued, conn.send_overflow.items.len) catch
                return error.OutputTooSmall;
            if (queued >= conn.sendq_cap) return error.OutputTooSmall;
            break :budget conn.sendq_cap - queued;
        };
        if (plaintext_budget == 0) return error.OutputTooSmall;

        const caps = names_reply.RequesterCaps{
            .multi_prefix = conn.session.hasCap(.multi_prefix) or conn.ircx,
            .userhost_in_names = conn.session.hasCap(.userhost_in_names),
        };
        const srv = self.serverName();
        const requester = conn.session.displayName();
        const end_text = "End of /NAMES list";
        const minimum_end_len = std.math.add(
            usize,
            1 + srv.len + 1 + 3 + 1 + requester.len + 1 + channel.len + 2 + end_text.len,
            2,
        ) catch return error.OutputTooSmall;
        if (minimum_end_len > plaintext_budget) return error.OutputTooSmall;

        // Exact current-topology candidate bound: local physical rows, every
        // established peer's retained channel roster, and at most one synthetic
        // resume claimant. The dedupe index collapses physical/mesh aliases, but
        // its allocation can never grow beyond this authoritative source image.
        var topology_upper = self.world.memberCount(channel);
        if (projection != null)
            topology_upper = std.math.add(usize, topology_upper, 1) catch
                return error.OutputTooSmall;
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                const remote_count = if (slot.value.s2s_secured) |link|
                    if (link.established()) link.channelMembers(channel).len else 0
                else if (slot.value.s2s) |link|
                    if (link.established()) link.channelMembers(channel).len else 0
                else
                    0;
                topology_upper = std.math.add(usize, topology_upper, remote_count) catch
                    return error.OutputTooSmall;
            }
        }
        // Each emitted identity costs at least its non-empty nick plus either a
        // separator or a strictly-larger 353 header. Reserve the complete 366
        // first, then use the checked two-byte minimum to constrain heap growth.
        const output_member_limit = (plaintext_budget - minimum_end_len) / 2;
        const max_entries = @min(topology_upper, output_member_limit);
        var roster: std.ArrayListUnmanaged(NamesRosterEntry) = .empty;
        defer roster.deinit(self.allocator);
        var seen: NamesNickSet = .empty;
        defer seen.deinit(self.allocator);

        // +x AUDITORIUM: regular members are hidden from each other; only ops and
        // voiced members are visible (plus the viewer always sees themselves).
        const is_auditorium = self.world.channelHasExtFlag(channel, .auditorium);
        const viewer_wid = self.world.findNick(conn.session.displayName());
        const viewer_rank = if (projection) |projected|
            auditoriumRank(projected.modes)
        else if (viewer_wid) |vw|
            auditoriumRank(self.world.memberModes(channel, vw) orelse world_model.MemberModes.empty())
        else
            auditorium.Rank.regular;

        var projected_member_seen = false;
        if (self.world.memberIterator(channel)) |members_src| {
            var it = members_src;
            while (it.next()) |member| {
                const projected = if (projection) |image| image.contains(member.*) else false;
                const nick = if (projected)
                    projection.?.nick
                else
                    self.world.nickOf(member.*) orelse continue;
                const modes = if (projected)
                    projection.?.modes
                else
                    self.world.memberModes(channel, member.*) orelse world_model.MemberModes.empty();
                if (is_auditorium) {
                    const is_self = projected or if (viewer_wid) |vw| member.*.eql(vw) else false;
                    if (!is_self and !auditorium.visibleTo(viewer_rank, auditoriumRank(modes))) continue;
                }
                // Multiple sockets attached to one logical session are distinct
                // delivery endpoints but one IRC identity. Keep every endpoint in
                // World for fan-out/participation, while rendering the nick once in
                // NAMES so clients do not manufacture duplicate users.
                const added = try self.appendNamesRosterEntry(
                    &roster,
                    &seen,
                    max_entries,
                    nick,
                    if (projected) projection.?.user else usernameOf(self, member.*),
                    default_host,
                    modes,
                    (projected and projection.?.is_override_oper) or self.isOverrideOper(nick),
                );
                if (projected and (added or seen.contains(nick)))
                    projected_member_seen = true;
            }
        }

        // A fresh/detached claimant is absent from the pre-commit World. Seat one
        // logical rendering of its prepared final identity; the real commit may
        // add several physical exact-token rows, which ordinary NAMES dedupes by
        // nick in the same way.
        if (projection) |projected| synthetic: {
            if (projected_member_seen or seen.contains(projected.nick)) break :synthetic;
            _ = try self.appendNamesRosterEntry(
                &roster,
                &seen,
                max_entries,
                projected.nick,
                projected.user,
                default_host,
                projected.modes,
                projected.is_override_oper or self.isOverrideOper(projected.nick),
            );
        }

        // World projection (#6): merge remote members announced by established S2S
        // peers for this channel. Deduped against already-listed nicks; the stored
        // u4 status IS the MemberModes bitset, so prefixes/auditorium rank apply
        // uniformly. Host is the origin server name (placeholder user).
        //
        // Iterate ALL reactors, not just the requester's shard: S2S peer links live
        // only on reactor 0, so a `self.rx()` scan would show remote members only to
        // shard-0 clients (the multi-shard NAMES gap). The whole completion runs
        // under `world.lockWrite`, so this cross-reactor read is race-free — the
        // same pattern `findRemoteWhois`/`relayToPeers` already rely on.
        for (self.reactors) |*reactor| {
            for (reactor.clients.slots.items) |*slot| {
                if (!slot.occupied or !slot.value.isActiveMeshPeer()) continue;
                if (slot.value.s2s_secured) |link| {
                    if (link.established()) try self.addRemoteMembers(&roster, &seen, max_entries, is_auditorium, viewer_rank, link.remoteName(), link.channelMembers(channel));
                } else if (slot.value.s2s) |link| {
                    if (link.established()) try self.addRemoteMembers(&roster, &seen, max_entries, is_auditorium, viewer_rank, link.remoteName(), link.channelMembers(channel));
                }
            }
        }

        // 353 visibility symbol: '@' for secret (+s), '=' otherwise.
        const channel_status: u8 = if (self.world.channelHasFlag(channel, .secret)) '@' else '=';

        // Render the WHOLE burst into isolated bounded storage before touching
        // the live socket/capture. This prevents a SendQ limit or allocation
        // failure after an early 353 from leaving a client with a partial roster.
        // The pessimistic size assumes every member needs its own 353 line; the
        // actual writer folds multiple tokens per standards-compliant line.
        const header_len = 1 + srv.len + 1 + 3 + 1 + requester.len + 3 + channel.len + 2;
        var storage_upper = minimum_end_len;
        for (roster.items) |*entry| {
            const member = entry.asMember();
            var token_len = (if (member.prefixes.len == 0) @as(usize, 0) else if (caps.multi_prefix) member.prefixes.len else 1) + member.nick.len;
            if (caps.userhost_in_names) {
                token_len = std.math.add(usize, token_len, 1 + member.user.len + 1 + member.host.len) catch
                    return error.OutputTooSmall;
            }
            if (header_len > names_reply.DEFAULT_MAX_LINE_BYTES or
                token_len > names_reply.DEFAULT_MAX_LINE_BYTES - header_len)
                return error.OutputTooSmall;
            const line_upper = std.math.add(usize, header_len + 2, token_len) catch
                return error.OutputTooSmall;
            storage_upper = std.math.add(usize, storage_upper, line_upper) catch
                return error.OutputTooSmall;
        }
        const burst_storage = try self.allocator.alloc(u8, @min(storage_upper, plaintext_budget));
        defer self.allocator.free(burst_storage);
        var burst = ReplyCapture{ .buf = burst_storage };

        // Render 353 lines in fixed-size view pages. The owned roster itself is
        // dynamically complete; only this scratch view remains stack-bounded.
        // Binary shrinking handles worst-case userhost-in-names tokens or the
        // line-sink bound without truncating the next page.
        var out_buf: [default_reply_bytes]u8 = undefined;
        var lines_buf: [64]names_reply.NamesLine = undefined;
        var page_buf: [128]names_reply.Member = undefined;
        var offset: usize = 0;
        while (offset < roster.items.len) {
            const page_len = @min(page_buf.len, roster.items.len - offset);
            for (roster.items[offset .. offset + page_len], 0..) |*entry, i|
                page_buf[i] = entry.asMember();
            var end = page_len;
            var progressed = false;
            while (end > 0) {
                var sink = names_reply.NamesLineSink{ .lines = &lines_buf };
                if (names_reply.writeNamReplyLines(
                    &out_buf,
                    srv,
                    requester,
                    channel,
                    channel_status,
                    page_buf[0..end],
                    caps,
                    &sink,
                )) |_| {
                    for (sink.slice()) |line| {
                        burst.append(line.bytes);
                        burst.append("\r\n");
                    }
                    if (burst.overflowed) return error.OutputTooSmall;
                    offset += end;
                    progressed = true;
                    break;
                } else |err| switch (err) {
                    error.OutputTooSmall, error.TooManyRecipients => {
                        const mid = end / 2;
                        if (mid == 0) return error.OutputTooSmall;
                        end = mid;
                    },
                    else => return error.OutputTooSmall,
                }
            }
            if (!progressed) break;
        }

        var end_buf: [default_reply_bytes]u8 = undefined;
        const end_line = names_reply.buildEndOfNamesLine(&end_buf, srv, requester, channel, end_text) catch {
            return error.OutputTooSmall;
        };
        burst.append(end_line);
        burst.append("\r\n");
        if (burst.overflowed) return error.OutputTooSmall;

        if (conn.reply_capture == null) {
            const raw_bound = resumeBootstrapRawBound(conn, burst.captured()) orelse
                return error.OutputTooSmall;
            try reserveRawAppendToConn(conn, raw_bound);
            appendToConn(conn, burst.captured()) catch |err| {
                // Raw capacity is reserved, but userspace TLS/WS framing can
                // still fail after producing an earlier record. JOIN ignores a
                // NAMES error, so make that unexpected partial stream terminal.
                self.poisonOwnedDelivery(conn);
                return err;
            };
            return;
        }
        try appendToConn(conn, burst.captured());
    }
};

/// Public entry point. `LinuxServer` is the io_uring fast path. Other targets
/// construct `PortableServer`, which serves on the native `IoBackend`.
/// Helix USR2 adoption stays on `LinuxServer`.
// Private implementation fragment for server.zig. Not an exported module.
// Every allocation made through this storage is wiped, including allocations
// freed before an OOM unwind. No arena metadata/default deinit hides secrets.
const PolicyStorage = struct {
    owner: std.mem.Allocator,
    mutex: std.atomic.Mutex = .unlocked,
    first: ?*Allocation = null,
    const Allocation = struct {
        next: ?*Allocation,
        bytes: []u8,
        alignment: std.mem.Alignment,
    };

    fn allocator(self: *PolicyStorage) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &.{ .alloc = alloc, .resize = resize, .remap = remap, .free = free } };
    }
    fn lock(self: *PolicyStorage) void {
        while (!self.mutex.tryLock()) std.atomic.spinLoopHint();
    }
    fn alloc(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const self: *PolicyStorage = @ptrCast(@alignCast(ctx));
        const node = self.owner.create(Allocation) catch return null;
        const bytes = self.owner.rawAlloc(len, alignment, ret_addr) orelse {
            self.owner.destroy(node);
            return null;
        };
        self.lock();
        defer self.mutex.unlock();
        node.* = .{ .next = self.first, .bytes = bytes[0..len], .alignment = alignment };
        self.first = node;
        return bytes;
    }
    fn resize(_: *anyopaque, _: []u8, _: std.mem.Alignment, _: usize, _: usize) bool {
        return false;
    }
    fn remap(_: *anyopaque, _: []u8, _: std.mem.Alignment, _: usize, _: usize) ?[*]u8 {
        return null;
    }
    fn free(ctx: *anyopaque, bytes: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const self: *PolicyStorage = @ptrCast(@alignCast(ctx));
        self.lock();
        var cursor = &self.first;
        while (cursor.*) |node| {
            if (node.bytes.ptr == bytes.ptr) {
                std.debug.assert(node.bytes.len == bytes.len and node.alignment == alignment);
                cursor.* = node.next;
                self.mutex.unlock();
                std.crypto.secureZero(u8, node.bytes);
                self.owner.rawFree(node.bytes, node.alignment, ret_addr);
                self.owner.destroy(node);
                return;
            }
            cursor = &node.next;
        }
        self.mutex.unlock();
        @panic("foreign policy allocation");
    }
    /// Only after every policy borrower has joined/detached. This also handles
    /// allocations not yet installed into a fully constructed typed object.
    fn deinit(self: *PolicyStorage) void {
        while (self.first) |node| {
            self.first = node.next;
            std.crypto.secureZero(u8, node.bytes);
            self.owner.rawFree(node.bytes, node.alignment, @returnAddress());
            self.owner.destroy(node);
        }
    }
};

/// Data-only recursive clone. A source pointer/allocator/Io must instead have
/// an explicit typed lifetime binding; it cannot quietly pass through here.
fn clonePolicyValue(allocator: std.mem.Allocator, value: anytype) std.mem.Allocator.Error!@TypeOf(value) {
    const T = @TypeOf(value);
    return switch (@typeInfo(T)) {
        .pointer => |info| blk: {
            if (info.size != .slice or info.sentinel() != null) @compileError("policy clone requires an explicit source binding for this pointer");
            const out = try allocator.alloc(info.child, value.len);
            for (out, value) |*dst, src| dst.* = try clonePolicyValue(allocator, src);
            break :blk out;
        },
        .optional => if (value) |inner| try clonePolicyValue(allocator, inner) else null,
        .array => blk: {
            var out: T = undefined;
            for (&out, value) |*dst, src| dst.* = try clonePolicyValue(allocator, src);
            break :blk out;
        },
        .@"struct" => |info| blk: {
            var out: T = undefined;
            inline for (info.field_names) |name| @field(out, name) = try clonePolicyValue(allocator, @field(value, name));
            break :blk out;
        },
        .@"union" => |info| blk: {
            if (info.tag_type == null) @compileError("policy clone refuses untagged union");
            const tag = std.meta.activeTag(value);
            inline for (info.field_names) |name| {
                if (tag == @field(info.tag_type.?, name)) break :blk @unionInit(T, name, try clonePolicyValue(allocator, @field(value, name)));
            }
            unreachable;
        },
        .bool, .int, .float, .@"enum", .void => value,
        else => @compileError("policy clone encountered non-data state"),
    };
}

