fn checkedMonotonicDeadlineMillis(timeout_ms: u64) !u64 {
    const now_ms = std.math.cast(u64, platform.monotonicMillis()) orelse return error.InvalidMonotonicClock;
    return std.math.add(u64, now_ms, timeout_ms);
}

