    var fixture: ManagedStopTest = .{};
    try fixture.initWithMedia(2, null, true);
    errdefer fixture.deinit() catch |cleanup_error| {
        std.debug.print("managed core media fixture cleanup after test failure: {s}\n", .{@errorName(cleanup_error)});
    };
    try fixture.core.?.requirePrepared();
    const before = fixture.graph.?.view.inspect();
    for ([_]ManagedCoreFixture.Tamper{
        .native_cross,         .media_cross,           .native_routing_domain, .native_routing_binding,
        .media_routing_domain, .media_routing_binding, .media_routing_fifo,
    }) |kind| {
        try ManagedCoreFixture.tamper(fixture.core.?, kind, true);
        var restored = false;
        defer if (!restored) ManagedCoreFixture.tamper(fixture.core.?, kind, false) catch {};
        try std.testing.expectError(error.ConfiguredOwnerMismatch, fixture.core.?.requirePrepared());
        try ManagedCoreFixture.tamper(fixture.core.?, kind, false);
        restored = true;
        try fixture.core.?.requirePrepared();
        try std.testing.expect(std.meta.eql(before, fixture.graph.?.view.inspect()));
    }
    try fixture.deinit();
}

fn managedCreateChannel(ptr: *anyopaque, channel: []const u8) services_mod.ServiceError!void {
    const context: *ManagedServicesContextBacking = @ptrCast(@alignCast(ptr));
    try context.core.server.?.markChannelRegistered(channel, true);
}
fn managedDropChannel(ptr: *anyopaque, channel: []const u8) services_mod.ServiceError!void {
    const context: *ManagedServicesContextBacking = @ptrCast(@alignCast(ptr));
    try context.core.server.?.markChannelRegistered(channel, false);
}
fn destroyManagedCoreBacking(b: *ManagedCoreBacking) void {
    // No wrapper/companion can still borrow these objects. Constructor errors
    // are pre-spawn; prepared errors first cancel/join/detach in Runtime.
    if (b.acme) |owner| {
        owner.stop();
        std.crypto.secureZero(u8, std.mem.asBytes(owner));
        b.allocator.destroy(owner);
        b.acme = null;
    }
    if (b.ocsp) |owner| {
        owner.stop();
        std.crypto.secureZero(u8, std.mem.asBytes(owner));
        b.allocator.destroy(owner);
        b.ocsp = null;
    }
    if (b.services) |*services| services.state = null;
    // Drop the actual leaf registration and loans before original World
    // destruction. This closed branch cannot have entered a runtime graph.
    releaseManagedLeasedSources(b) catch |err| std.debug.panic("managed leased source cleanup: {s}", .{@errorName(err)});
    std.debug.assert(b.leased_active_scope == null);
    var scope = b.leased_scope_tokens;
    while (scope) |source| {
        scope = source.next;
        std.debug.assert(source.consumed);
        b.allocator.destroy(source);
    }
    b.leased_scope_tokens = null;
    if (b.server) |server| {
        server.deinit();
        std.crypto.secureZero(u8, std.mem.asBytes(server));
        b.allocator.destroy(server);
        b.server = null;
    }
    if (b.ocg2_observer) |owner| ocg2_runtime_mod.destroy(owner);
    if (b.ocg2_projection) |owner| owner.deinit();
    if (b.ocg2_audit) |*owner| owner.deinit();
    if (b.scram) |*owner| owner.deinit();
    if (b.certfp_binds) |*owner| owner.deinit();
    if (b.transparency) |*owner| owner.deinit();
    if (b.owned_identity) |identity| {
        identity.deinit();
        b.owned_identity = null;
    }
    b.policy.deinit();
}

pub const Server = if (builtin.os.tag == .linux or builtin.os.tag == .openbsd or builtin.os.tag == .windows) LinuxServer else PortableServer;

const PortableChan = struct {
    name: []u8,
    members: []*PortableConn,
    live: usize = 0,
};

const PortableConn = struct {
    fd: linux.fd_t = -1,
    token: RingFdToken = .{ .slot = 0, .gen = 0 },
    state: *ConnState,
    recv_buf: [512]u8 = undefined,
    line_buf: [512]u8 = undefined,
    line_len: usize = 0,
    send_buf: [default_reply_bytes]u8 = undefined,
    send_len: usize = 0,
    send_off: usize = 0,
    pending_output: std.ArrayList(u8) = .empty,
    recv_armed: bool = false,
    send_armed: bool = false,
    live: bool = true,
    graceful_close: bool = false,
    write_shutdown: bool = false,
    peer_closed: bool = false,
    close_deadline_ms: i64 = 0,
    recv_cancel_queued: bool = false,
    send_cancel_queued: bool = false,
    drop_pending: bool = false,
};

const PortableSendSink = struct {
    conn: *PortableConn,
    allocator: std.mem.Allocator,

    fn write(self: *PortableSendSink, bytes: []const u8) ServerError!void {
        try portableQueueBytes(self.conn, self.allocator, bytes);
    }
};

const max_portable_pending_output: usize = 1024 * 1024;

fn portableQueueBytes(conn: *PortableConn, allocator: std.mem.Allocator, bytes: []const u8) ServerError!void {
    if (conn.pending_output.items.len != 0 or bytes.len > conn.send_buf.len - conn.send_len) {
        if (bytes.len > max_portable_pending_output -| conn.pending_output.items.len)
            return error.OutputTooSmall;
        try conn.pending_output.appendSlice(allocator, bytes);
        return;
    }
    @memcpy(conn.send_buf[conn.send_len..][0..bytes.len], bytes);
    conn.send_len += bytes.len;
}

fn portableMessageLine(buf: *[512]u8, nick: []const u8, username: []const u8, command: []const u8, target: []const u8, message: []const u8) ServerError![]const u8 {
    const prefix = std.fmt.bufPrint(buf, ":{s}!{s}@localhost {s} {s} :", .{
        nick, username, command, target,
    }) catch return error.OutputTooSmall;
    if (prefix.len + 2 > buf.len) return error.OutputTooSmall;
    const text_len = @min(message.len, buf.len - prefix.len - 2);
    @memcpy(buf[prefix.len..][0..text_len], message[0..text_len]);
    @memcpy(buf[prefix.len + text_len ..][0..2], "\r\n");
    return buf[0 .. prefix.len + text_len + 2];
}

const PortableServer = struct {
    allocator: std.mem.Allocator = std.heap.page_allocator,
    backend: io_backend.IoBackend = undefined,
    listener: linux.fd_t = -1,
    port: u16 = 0,
    max_clients: usize = 0,
    chanlimit: usize = 0,
    channellen: usize = 0,
    conns: std.ArrayList(*PortableConn) = .empty,
    chans: std.ArrayList(PortableChan) = .empty,
    next_slot: u32 = 1,
    pending: bool = false,
    wake_armed: bool = false,
    wake: linux.kernel_timespec = .{ .sec = 0, .nsec = 200_000_000 },
    runtime_failure: ?ServerError = null,
    fanout_depth: usize = 0,
    flushing_drops: bool = false,

    pub fn init(allocator: std.mem.Allocator, config: Config) ServerError!PortableServer {
        var backend = io_backend.IoBackend.openOwned(io_backend.familyFor(builtin.os.tag), config.ring_entries, .{}) catch return error.Unsupported;
        backend.requireAll() catch {
            backend.deinit();
            return error.Unsupported;
        };
        const listener = io_backend.listenTcp(config.host, config.port) catch |err| {
            backend.deinit();
            return err;
        };
        const listen_token = RingFdToken{ .slot = 0, .gen = 1 };
        backend.accept(listen_token, listener.fd) catch {
            io_backend.closeSocket(listener.fd);
            backend.deinit();
            return error.Unsupported;
        };
        _ = backend.submit() catch {
            io_backend.closeSocket(listener.fd);
            backend.deinit();
            return error.Unsupported;
        };
        if (comptime builtin.os.tag == .freebsd) {
            kernel_other.enterDaemonCapsicum(&.{ listener.fd, backend.queueFd() }) catch {
                io_backend.closeSocket(listener.fd);
                backend.deinit();
                return error.Unsupported;
            };
        }
        return .{
            .allocator = allocator,
            .backend = backend,
            .listener = listener.fd,
            .port = listener.port,
            .max_clients = config.max_clients,
            .chanlimit = config.chanlimit,
            .channellen = config.channellen,
        };
    }
    /// Heap slot used by `main`. Same listener and backend as `init`.
    pub fn initInPlace(self: *PortableServer, allocator: std.mem.Allocator, config: Config) ServerError!void {
        self.* = try init(allocator, config);
    }
    pub fn deinit(self: *PortableServer) void {
        const listen_token = RingFdToken{ .slot = 0, .gen = 1 };
        self.backend.cancel(.accept, listen_token) catch {};
        for (self.conns.items) |conn| {
            if (conn.recv_armed) self.backend.cancel(.recv, conn.token) catch {};
            if (conn.send_armed) self.backend.cancel(.send, conn.token) catch {};
        }
        _ = self.backend.submit() catch {};
        if (comptime builtin.os.tag == .windows) {
            // The kernel can still write into recv/send buffers after a
            // cancellation request. Retire every IOCP slot before freeing
            // any connection storage or the backend's status blocks.
            self.backend.quiesce() catch @panic("IOCP requests could not be drained");
        } else {
            var evs: [8]io_backend.Reaped = undefined;
            var spins: u8 = 0;
            while (spins < 8) : (spins += 1) {
                // wait_ms 0 does not block. A positive wait on the ring asks for
                // one CQE and will sit there after the last completion.
                const n = self.backend.reap(&evs, 0) catch break;
                if (n == 0) break;
            }
        }
        self.backend.deinit();
        self.freeChans();
        for (self.conns.items) |conn| {
            io_backend.closeSocket(conn.fd);
            conn.pending_output.deinit(self.allocator);
            self.allocator.destroy(conn.state);
            self.allocator.destroy(conn);
        }
        self.conns.deinit(self.allocator);
        self.conns = .empty;
        io_backend.closeSocket(self.listener);
        self.listener = -1;
    }

    pub fn start(_: *PortableServer) void {}

    pub fn boundPort(self: *PortableServer) ServerError!u16 {
        if (self.port == 0) return error.Unsupported;
        return self.port;
    }
    pub fn s2sBoundPort(_: *PortableServer) ServerError!u16 {
        return error.Unsupported;
    }
    pub fn runOnce(self: *PortableServer) ServerError!void {
        if (self.backend.family == .ringlane and !self.wake_armed) {
            self.backend.timeout(.{ .slot = 0, .gen = 0 }, &self.wake) catch return error.Unsupported;
            self.wake_armed = true;
            self.pending = true;
        }
        if (self.pending) {
            _ = self.backend.submit() catch return error.Unsupported;
            self.pending = false;
        }
        var evs: [16]io_backend.Reaped = undefined;
        const n = self.backend.reap(&evs, 200) catch return error.Unsupported;
        var i: usize = 0;
        while (i < n) : (i += 1) try self.dispatch(evs[i]);
        if (self.pending) {
            _ = self.backend.submit() catch return error.Unsupported;
            self.pending = false;
        }
        try self.retireClosedConns();
    }
    /// Serve loop `main` runs after `init` returns a listener.
    pub fn runThreaded(self: *PortableServer, run: *std.atomic.Value(bool)) void {
        while (run.load(.acquire)) {
            self.runOnce() catch |err| {
                std.debug.print("onyx-server: portable reactor failed ({s})\n", .{@errorName(err)});
                self.runtime_failure = err;
                return;
            };
        }
    }
    pub fn runtimeFailure(self: *const PortableServer) ?ServerError {
        return self.runtime_failure;
    }
    /// Symbol parity for the services → world +r bridge (see LinuxServer).
    pub fn markChannelRegistered(_: *PortableServer, _: []const u8, _: bool) std.mem.Allocator.Error!void {}
    /// Services bridge. A non-Linux boot does not replay a Linux Helix capsule.
    pub fn replayServicesLiveState(_: *PortableServer, _: *services_mod.Services) void {}
    pub fn loadWasmPlugins(_: *PortableServer) void {}

    fn dispatch(self: *PortableServer, ev: io_backend.Reaped) ServerError!void {
        switch (ev.op) {
            .timeout => self.wake_armed = false,
            .cancel, .poll, .connect => {},
            .accept => try self.onAccept(ev),
            .recv => try self.onRecv(ev),
            .send => try self.onSend(ev),
        }
    }

    fn onAccept(self: *PortableServer, ev: io_backend.Reaped) ServerError!void {
        if (ev.token.slot != 0 or ev.token.gen != 1) return;
        if (!self.backend.levelTriggered()) self.armAccept() catch |err| {
            if (ev.result >= 0) io_backend.closeSocket(@intCast(ev.result));
            return err;
        };
        if (ev.result < 0) return;
        try self.adopt(@intCast(ev.result));
    }

    fn onRecv(self: *PortableServer, ev: io_backend.Reaped) ServerError!void {
        const conn = self.findConn(ev.token) orelse return;
        if (!self.backend.levelTriggered()) conn.recv_armed = false;
        if (!conn.live) {
            if (conn.graceful_close) {
                if ((ev.result > 0 or portableAgain(ev.result)) and
                    platform.monotonicMillis() < conn.close_deadline_ms)
                {
                    try self.armRecv(conn);
                } else {
                    conn.peer_closed = true;
                }
            }
            return;
        }
        if (ev.result < 0) {
            if (portableAgain(ev.result)) {
                if (!self.backend.levelTriggered()) try self.armRecv(conn);
                return;
            }
            self.dropConn(conn);
            return;
        }
        if (ev.result == 0) {
            self.dropConn(conn);
            return;
        }
        try self.takeBytes(conn, @intCast(ev.result));
        if (conn.live and !self.backend.levelTriggered()) try self.armRecv(conn);
    }

    fn onSend(self: *PortableServer, ev: io_backend.Reaped) ServerError!void {
        const conn = self.findConn(ev.token) orelse return;
        conn.send_armed = false;
        if (!conn.live and !conn.graceful_close) return;
        if (ev.result < 0) {
            if (portableAgain(ev.result)) {
                try self.armSend(conn);
                return;
            }
            conn.graceful_close = false;
            self.dropConn(conn);
            return;
        }
        const sent: usize = @intCast(ev.result);
        if (sent == 0 or conn.send_off + sent > conn.send_len) {
            conn.graceful_close = false;
            self.dropConn(conn);
            return;
        }
        conn.send_off += sent;
        try self.armSend(conn);
    }

    fn adopt(self: *PortableServer, fd: linux.fd_t) ServerError!void {
        // Closing connections still own backend buffers and count toward the
        // allocation bound until their original completions are retired.
        if (self.conns.items.len >= self.max_clients) {
            io_backend.closeSocket(fd);
            return;
        }
        if (self.next_slot == 0) {
            io_backend.closeSocket(fd);
            return error.Unexpected;
        }
        io_backend.setTcpNoDelay(fd);
        const conn = self.allocator.create(PortableConn) catch {
            io_backend.closeSocket(fd);
            return error.OutOfMemory;
        };
        const state = self.allocator.create(ConnState) catch {
            self.allocator.destroy(conn);
            io_backend.closeSocket(fd);
            return error.OutOfMemory;
        };
        state.* = .{};
        // This local-only reactor implements no negotiated IRCv3 extensions.
        // Keep registration and CAP advertising aligned with the commands
        // actually handled by PortableServer.
        state.session.setAvailableCapabilities(&.{});
        conn.* = .{
            .fd = fd,
            .token = .{ .slot = self.next_slot, .gen = 1 },
            .state = state,
        };
        self.conns.append(self.allocator, conn) catch {
            self.allocator.destroy(state);
            self.allocator.destroy(conn);
            io_backend.closeSocket(fd);
            return error.OutOfMemory;
        };
        self.next_slot +%= 1;
        self.armRecv(conn) catch |err| {
            self.dropConn(conn);
            return err;
        };
    }

    fn takeBytes(self: *PortableServer, conn: *PortableConn, n: usize) ServerError!void {
        if (n > conn.recv_buf.len) return error.Unexpected;
        var i: usize = 0;
        while (i < n) {
            if (!conn.live) return;
            if (conn.line_len >= conn.line_buf.len) {
                self.dropConn(conn);
                return;
            }
            const byte = conn.recv_buf[i];
            i += 1;
            if (byte != '\n') {
                conn.line_buf[conn.line_len] = byte;
                conn.line_len += 1;
                continue;
            }
            var end = conn.line_len;
            if (end > 0 and conn.line_buf[end - 1] == '\r') end -= 1;
            const line = conn.line_buf[0..end];
            conn.line_len = 0;
            if (line.len == 0) continue;
            try self.handleLine(conn, line);
        }
    }

    fn armAccept(self: *PortableServer) ServerError!void {
        self.backend.accept(.{ .slot = 0, .gen = 1 }, self.listener) catch |err| {
            try self.flushIocpBatch(err);
            self.backend.accept(.{ .slot = 0, .gen = 1 }, self.listener) catch return error.Unsupported;
        };
        self.pending = true;
    }

    fn armRecv(self: *PortableServer, conn: *PortableConn) ServerError!void {
        if ((!conn.live and !conn.graceful_close) or conn.peer_closed or conn.recv_armed) return;
        self.backend.recv(conn.token, conn.fd, &conn.recv_buf) catch |err| {
            try self.flushIocpBatch(err);
            self.backend.recv(conn.token, conn.fd, &conn.recv_buf) catch return error.Unsupported;
        };
        conn.recv_armed = true;
        self.pending = true;
    }

    fn flushIocpBatch(self: *PortableServer, err: anyerror) ServerError!void {
        if (self.backend.family != .iocp or err != error.SubmissionQueueFull) return error.Unsupported;
        _ = self.backend.submit() catch return error.Unsupported;
        self.pending = false;
    }

    fn cancelWindows(self: *PortableServer, kind: ringlane.OpKind, token: RingFdToken) ServerError!void {
        self.backend.cancel(kind, token) catch |err| {
            if (err == error.MissingOp) return;
            // A wave of disconnected clients can fill the bounded submission
            // batch before the next reap. Submit this batch and retry the
            // exact cancellation without dropping reactor liveness.
            try self.flushIocpBatch(err);
            self.backend.cancel(kind, token) catch |retry_err| {
                if (retry_err == error.MissingOp) return;
                return error.Unsupported;
            };
        };
        self.pending = self.backend.queuedCount() != 0;
    }

    fn armSend(self: *PortableServer, conn: *PortableConn) ServerError!void {
        if ((!conn.live and !conn.graceful_close) or conn.send_armed) return;
        if (conn.send_off >= conn.send_len) {
            conn.send_off = 0;
            conn.send_len = 0;
            if (conn.pending_output.items.len != 0) {
                const n = @min(conn.pending_output.items.len, conn.send_buf.len);
                @memcpy(conn.send_buf[0..n], conn.pending_output.items[0..n]);
                const remaining = conn.pending_output.items.len - n;
                std.mem.copyForwards(u8, conn.pending_output.items[0..remaining], conn.pending_output.items[n..]);
                conn.pending_output.items.len = remaining;
                conn.send_len = n;
            } else return;
        }
        self.backend.send(conn.token, conn.fd, conn.send_buf[conn.send_off..conn.send_len]) catch |err| {
            try self.flushIocpBatch(err);
            self.backend.send(conn.token, conn.fd, conn.send_buf[conn.send_off..conn.send_len]) catch return error.Unsupported;
        };
        conn.send_armed = true;
        self.pending = true;
    }

    fn dropConn(self: *PortableServer, conn: *PortableConn) void {
        self.dropConnReason(conn, "Connection closed");
    }

    fn dropConnReason(self: *PortableServer, conn: *PortableConn, reason: []const u8) void {
        if (!conn.live or conn.drop_pending) return;
        if (self.fanout_depth != 0) {
            // All recursive failures in a fanout use the generic reason.
            // Finish delivering the original event before sending QUIT.
            conn.drop_pending = true;
            return;
        }
        self.dropConnNow(conn, reason);
    }

    fn dropConnNow(self: *PortableServer, conn: *PortableConn, reason: []const u8) void {
        conn.live = false;
        if (conn.state.session.registered()) {
            var buf: [1024]u8 = undefined;
            const quit_line = std.fmt.bufPrint(&buf, ":{s}!{s}@localhost QUIT :{s}\r\n", .{
                conn.state.session.displayName(), conn.state.session.username(), reason,
            }) catch null;
            if (quit_line) |line| self.broadcastShared(conn, line, false);
        }
        self.detachChan(conn);
    }

    fn endFanout(self: *PortableServer) void {
        self.fanout_depth -= 1;
        if (self.fanout_depth == 0) self.flushPendingDrops();
    }

    fn flushPendingDrops(self: *PortableServer) void {
        if (self.fanout_depth != 0 or self.flushing_drops) return;
        self.flushing_drops = true;
        defer self.flushing_drops = false;
        while (true) {
            var next: ?*PortableConn = null;
            for (self.conns.items) |conn| {
                if (conn.drop_pending) {
                    next = conn;
                    break;
                }
            }
            const conn = next orelse break;
            conn.drop_pending = false;
            if (conn.live) self.dropConnNow(conn, "Connection closed");
        }
    }

    fn retireClosedConns(self: *PortableServer) ServerError!void {
        // Reap and dispatch the whole batch first: kqueue may already have
        // forgotten a send registration whose completion follows an EOF here.
        // Ring/IOCP buffers remain owned until their original CQEs arrive.
        var i: usize = 0;
        while (i < self.conns.items.len) {
            const conn = self.conns.items[i];
            if (conn.live) {
                i += 1;
                continue;
            }
            if (conn.fd >= 0) {
                if (comptime builtin.os.tag == .windows) {
                    // Bound the whole QUIT drain, including a send to a peer
                    // that stopped reading. After the deadline, cancel exact
                    // in-flight requests and retain buffers until completion.
                    if (conn.graceful_close and platform.monotonicMillis() >= conn.close_deadline_ms)
                        conn.graceful_close = false;
                    // QUIT must finish replies already queued for this client.
                    // Closing a socket with an overlapped send still pending
                    // turns its final TCP bytes into a reset on Windows.
                    if (conn.graceful_close and !conn.send_armed) try self.armSend(conn);
                    if (conn.graceful_close and (conn.send_armed or conn.send_off < conn.send_len or
                        conn.pending_output.items.len != 0))
                    {
                        i += 1;
                        continue;
                    }
                    if (conn.graceful_close and !conn.write_shutdown) {
                        io_backend.shutdownSocketWrite(conn.fd);
                        conn.write_shutdown = true;
                    }
                    if (conn.graceful_close and !conn.peer_closed and
                        platform.monotonicMillis() < conn.close_deadline_ms)
                    {
                        if (!conn.recv_armed) try self.armRecv(conn);
                        i += 1;
                        continue;
                    }
                    if (conn.recv_armed and !conn.recv_cancel_queued) {
                        // MissingOp means the original completion is already
                        // queued for a later batch. Keep buffer custody until
                        // dispatch clears recv_armed.
                        try self.cancelWindows(.recv, conn.token);
                        conn.recv_cancel_queued = true;
                    }
                    if (conn.send_armed and !conn.send_cancel_queued) {
                        try self.cancelWindows(.send, conn.token);
                        conn.send_cancel_queued = true;
                    }
                    if (conn.recv_armed or conn.send_armed) {
                        i += 1;
                        continue;
                    }
                    io_backend.closeSocket(conn.fd);
                    conn.fd = -1;
                } else {
                    var cancelled = false;
                    if (conn.recv_armed) {
                        self.backend.cancel(.recv, conn.token) catch return error.Unsupported;
                        cancelled = true;
                    }
                    if (conn.send_armed) {
                        self.backend.cancel(.send, conn.token) catch return error.Unsupported;
                        cancelled = true;
                    }
                    if (cancelled) _ = self.backend.submit() catch return error.Unsupported;
                    if (self.backend.levelTriggered()) {
                        conn.recv_armed = false;
                        conn.send_armed = false;
                    }
                    io_backend.closeSocket(conn.fd);
                    conn.fd = -1;
                }
            }
            if (conn.recv_armed or conn.send_armed) {
                i += 1;
                continue;
            }
            _ = self.conns.swapRemove(i);
            conn.pending_output.deinit(self.allocator);
            self.allocator.destroy(conn.state);
            self.allocator.destroy(conn);
        }
        // Channel pointers can be in use by the current fanout, so reclaim
        // empty channels only after the entire completion batch has finished.
        i = 0;
        while (i < self.chans.items.len) {
            if (self.chans.items[i].live != 0) {
                i += 1;
                continue;
            }
            const chan = self.chans.swapRemove(i);
            self.allocator.free(chan.name);
            self.allocator.free(chan.members);
        }
    }

    fn handleLine(self: *PortableServer, conn: *PortableConn, line: []const u8) ServerError!void {
        const parsed = irc_line.parseLine(line) catch {
            self.dropConn(conn);
            return;
        };
        const was_registered = conn.state.session.registered();
        if (std.ascii.eqlIgnoreCase(parsed.command, "QUIT")) {
            conn.graceful_close = true;
            conn.close_deadline_ms = platform.monotonicMillis() + 5_000;
            self.dropConnReason(conn, if (parsed.param_count > 0) parsed.paramSlice()[0] else "Client quit");
            return;
        }
        if (std.ascii.eqlIgnoreCase(parsed.command, "NICK")) {
            if (parsed.param_count == 0 or parsed.paramSlice()[0].len == 0)
                return self.portableNumeric(conn, "431", "", "No nickname given");
            const requested = parsed.paramSlice()[0];
            if (!isValidNick(requested))
                return self.portableNumeric(conn, "432", requested, "Erroneous nickname");
            for (self.conns.items) |other| {
                if (!other.live or other == conn or !other.state.session.registration.nick_seen) continue;
                if (std.ascii.eqlIgnoreCase(other.state.session.displayName(), requested))
                    return self.portableNumeric(conn, "433", requested, "Nickname is already in use");
            }
        }
        const portable_command = std.ascii.eqlIgnoreCase(parsed.command, "JOIN") or
            std.ascii.eqlIgnoreCase(parsed.command, "PART") or
            std.ascii.eqlIgnoreCase(parsed.command, "NAMES") or
            std.ascii.eqlIgnoreCase(parsed.command, "PRIVMSG") or
            std.ascii.eqlIgnoreCase(parsed.command, "NOTICE");
        if (portable_command and !conn.state.session.registered()) {
            if (!std.ascii.eqlIgnoreCase(parsed.command, "NOTICE"))
                try self.portableNumeric(conn, "451", parsed.command, "You have not registered");
            return;
        }
        if (portable_command) {
            self.handleChannel(conn, parsed) catch self.dropConn(conn);
            return;
        }
        var old_nick: [128]u8 = undefined;
        var old_nick_len: usize = 0;
        const nick_change = was_registered and std.ascii.eqlIgnoreCase(parsed.command, "NICK");
        if (nick_change) {
            const before = conn.state.session.displayName();
            old_nick_len = @min(before.len, old_nick.len);
            @memcpy(old_nick[0..old_nick_len], before[0..old_nick_len]);
        }
        var sink = PortableSendSink{ .conn = conn, .allocator = self.allocator };
        processLine(conn.state, line, &sink) catch {
            self.dropConn(conn);
            return;
        };
        if (conn.state.session.client.registration.prereg == .closing) {
            self.dropConn(conn);
            return;
        }
        if (nick_change and !std.mem.eql(u8, old_nick[0..old_nick_len], conn.state.session.displayName())) {
            var buf: [512]u8 = undefined;
            const nick_line = std.fmt.bufPrint(&buf, ":{s}!{s}@localhost NICK :{s}\r\n", .{
                old_nick[0..old_nick_len], conn.state.session.username(), conn.state.session.displayName(),
            }) catch return error.OutputTooSmall;
            self.broadcastShared(conn, nick_line, true);
        }
        try self.armSend(conn);
    }

    /// Small shared-state IRC surface for the portable reactor. Linux/OpenBSD
    /// use the full server path; these commands must work across live clients.
    fn handleChannel(self: *PortableServer, conn: *PortableConn, parsed: irc_line.LineView) ServerError!void {
        if (std.ascii.eqlIgnoreCase(parsed.command, "JOIN")) {
            if (parsed.param_count == 0) return self.portableNumeric(conn, "461", "JOIN", "Not enough parameters");
            const name = parsed.paramSlice()[0];
            if (!portableChanName(name, self.channellen)) return self.portableNumeric(conn, "479", name, "Illegal channel name");
            if (self.findChan(name)) |existing| {
                if (self.onChan(existing, conn)) return;
            }
            var joined: usize = 0;
            for (self.chans.items) |*joined_chan| {
                if (self.onChan(joined_chan, conn)) joined += 1;
            }
            if (joined >= self.chanlimit)
                return self.portableNumeric(conn, "405", name, "You have joined too many channels");
            const chan = try self.ensureChan(name);
            try self.addMember(chan, conn);
            try self.broadcastJoin(chan, conn);
            try self.namesAndEnd(chan, conn);
            return;
        }
        if (std.ascii.eqlIgnoreCase(parsed.command, "PART")) {
            if (parsed.param_count == 0) return self.portableNumeric(conn, "461", "PART", "Not enough parameters");
            const name = parsed.paramSlice()[0];
            const chan = self.findChan(name) orelse return self.portableNumeric(conn, "403", name, "No such channel");
            if (!self.onChan(chan, conn)) return self.portableNumeric(conn, "442", name, "You're not on that channel");
            var buf: [1024]u8 = undefined;
            const reason = if (parsed.param_count > 1) parsed.paramSlice()[1] else "Leaving";
            const line = std.fmt.bufPrint(&buf, ":{s}!{s}@localhost PART {s} :{s}\r\n", .{
                conn.state.session.displayName(), conn.state.session.username(), chan.name, reason,
            }) catch return error.OutputTooSmall;
            self.fanout_depth += 1;
            defer self.endFanout();
            var i: usize = 0;
            while (i < chan.live) {
                const dest = chan.members[i];
                if (!dest.drop_pending) self.enqueueBytes(dest, line) catch self.dropConn(dest);
                if (i < chan.live and chan.members[i] == dest) i += 1;
            }
            self.removeMember(chan, conn);
            return;
        }
        if (std.ascii.eqlIgnoreCase(parsed.command, "NAMES")) {
            if (parsed.param_count == 0) return self.portableNumeric(conn, "461", "NAMES", "Not enough parameters");
            const name = parsed.paramSlice()[0];
            if (self.findChan(name)) |chan| return self.namesAndEnd(chan, conn);
            return self.portableNumeric(conn, "366", name, "End of /NAMES list");
        }
        const is_notice = std.ascii.eqlIgnoreCase(parsed.command, "NOTICE");
        if (parsed.param_count < 2) {
            if (!is_notice) return self.portableNumeric(conn, "461", "PRIVMSG", "Not enough parameters");
            return;
        }
        const target = parsed.paramSlice()[0];
        const text = parsed.paramSlice()[1];
        const command = if (is_notice) "NOTICE" else "PRIVMSG";
        if (target.len != 0 and (target[0] == '#' or target[0] == '&')) {
            if (!portableChanName(target, self.channellen)) {
                if (!is_notice) return self.portableNumeric(conn, "403", target, "No such channel");
                return;
            }
            const chan = self.findChan(target) orelse {
                if (!is_notice) try self.portableNumeric(conn, "403", target, "No such channel");
                return;
            };
            if (!self.onChan(chan, conn)) {
                if (!is_notice) try self.portableNumeric(conn, "442", target, "You're not on that channel");
                return;
            }
            return self.broadcastMessage(chan, conn, command, text);
        }
        const dest = self.findNick(target) orelse {
            if (!is_notice) try self.portableNumeric(conn, "401", target, "No such nick/channel");
            return;
        };
        var buf: [512]u8 = undefined;
        const line = try portableMessageLine(&buf, conn.state.session.displayName(), conn.state.session.username(), command, dest.state.session.displayName(), text);
        self.enqueueBytes(dest, line) catch self.dropConn(dest);
    }

    fn portableNumeric(self: *PortableServer, conn: *PortableConn, code: []const u8, target: []const u8, msg: []const u8) ServerError!void {
        var buf: [1024]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s} {s} {s} {s} :{s}\r\n", .{
            protocol_inventory.currentServerName(),
            code,
            conn.state.session.displayName(),
            target,
            msg,
        }) catch {
            self.dropConn(conn);
            return;
        };
        self.enqueueBytes(conn, line) catch self.dropConn(conn);
    }

    fn broadcastJoin(self: *PortableServer, chan: *PortableChan, joiner: *PortableConn) ServerError!void {
        var buf: [512]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, ":{s}!{s}@localhost JOIN {s}\r\n", .{
            joiner.state.session.displayName(),
            joiner.state.session.username(),
            chan.name,
        }) catch return error.OutputTooSmall;
        self.fanout_depth += 1;
        defer self.endFanout();
        var i: usize = 0;
        while (i < chan.live) {
            const dest = chan.members[i];
            if (!dest.live or dest.drop_pending) {
                i += 1;
                continue;
            }
            self.enqueueBytes(dest, line) catch self.dropConn(dest);
            if (i < chan.live and chan.members[i] == dest) i += 1;
        }
    }

    fn namesAndEnd(self: *PortableServer, chan: *PortableChan, conn: *PortableConn) ServerError!void {
        var buf: [512]u8 = undefined;
        const prefix = std.fmt.bufPrint(&buf, ":{s} 353 {s} = {s} :", .{
            protocol_inventory.currentServerName(),
            conn.state.session.displayName(),
            chan.name,
        }) catch return error.OutputTooSmall;
        const prefix_len = prefix.len;
        if (prefix_len + 2 > buf.len) return error.OutputTooSmall;
        var line_len = prefix_len;
        var count: usize = 0;
        for (chan.members[0..chan.live]) |member| {
            if (!member.live) continue;
            const nick = member.state.session.displayName();
            const extra = nick.len + @intFromBool(count != 0);
            if (line_len + extra + 2 > buf.len) {
                if (count == 0) return error.OutputTooSmall;
                @memcpy(buf[line_len..][0..2], "\r\n");
                try self.enqueueBytes(conn, buf[0 .. line_len + 2]);
                line_len = prefix_len;
                count = 0;
            }
            if (line_len + nick.len + 2 > buf.len) return error.OutputTooSmall;
            if (count != 0) {
                buf[line_len] = ' ';
                line_len += 1;
            }
            @memcpy(buf[line_len..][0..nick.len], nick);
            line_len += nick.len;
            count += 1;
        }
        @memcpy(buf[line_len..][0..2], "\r\n");
        try self.enqueueBytes(conn, buf[0 .. line_len + 2]);
        const end = std.fmt.bufPrint(&buf, ":{s} 366 {s} {s} :End of /NAMES list\r\n", .{
            protocol_inventory.currentServerName(),
            conn.state.session.displayName(),
            chan.name,
        }) catch return error.OutputTooSmall;
        try self.enqueueBytes(conn, end);
    }

    fn broadcastMessage(self: *PortableServer, chan: *PortableChan, from: *PortableConn, command: []const u8, text: []const u8) ServerError!void {
        var buf: [512]u8 = undefined;
        const line = try portableMessageLine(&buf, from.state.session.displayName(), from.state.session.username(), command, chan.name, text);
        self.fanout_depth += 1;
        defer self.endFanout();
        var i: usize = 0;
        while (i < chan.live) {
            const dest = chan.members[i];
            if (!dest.live or dest.drop_pending or dest == from) {
                i += 1;
                continue;
            }
            self.enqueueBytes(dest, line) catch self.dropConn(dest);
            if (i < chan.live and chan.members[i] == dest) i += 1;
        }
    }

    fn enqueueBytes(self: *PortableServer, conn: *PortableConn, bytes: []const u8) ServerError!void {
        if (!conn.live or conn.drop_pending) return;
        try portableQueueBytes(conn, self.allocator, bytes);
        try self.armSend(conn);
    }

    fn ensureChan(self: *PortableServer, name: []const u8) ServerError!*PortableChan {
        if (self.findChan(name)) |existing| return existing;
        const owned = self.allocator.alloc(u8, name.len) catch return error.OutOfMemory;
        errdefer self.allocator.free(owned);
        @memcpy(owned, name);
        self.chans.append(self.allocator, .{
            .name = owned,
            .members = &.{},
            .live = 0,
        }) catch return error.OutOfMemory;
        return &self.chans.items[self.chans.items.len - 1];
    }

    fn addMember(self: *PortableServer, chan: *PortableChan, conn: *PortableConn) ServerError!void {
        if (self.onChan(chan, conn)) return;
        if (chan.live == chan.members.len) {
            const nlen: usize = if (chan.members.len == 0) 4 else chan.members.len * 2;
            const grown = self.allocator.alloc(*PortableConn, nlen) catch return error.OutOfMemory;
            if (chan.members.len != 0) {
                @memcpy(grown[0..chan.members.len], chan.members);
                self.allocator.free(chan.members);
            }
            chan.members = grown;
        }
        chan.members[chan.live] = conn;
        chan.live += 1;
    }

    fn onChan(_: *PortableServer, chan: *PortableChan, conn: *PortableConn) bool {
        var i: usize = 0;
        while (i < chan.live) : (i += 1) {
            if (chan.members[i] == conn) return true;
        }
        return false;
    }

    fn findChan(self: *PortableServer, name: []const u8) ?*PortableChan {
        for (self.chans.items) |*chan| {
            if (std.ascii.eqlIgnoreCase(chan.name, name)) return chan;
        }
        return null;
    }

    fn findNick(self: *PortableServer, name: []const u8) ?*PortableConn {
        for (self.conns.items) |conn| {
            if (conn.live and conn.state.session.registered() and
                std.ascii.eqlIgnoreCase(conn.state.session.displayName(), name)) return conn;
        }
        return null;
    }

    fn broadcastShared(self: *PortableServer, from: *PortableConn, bytes: []const u8, include_self: bool) void {
        self.fanout_depth += 1;
        defer self.endFanout();
        for (self.conns.items) |dest| {
            if (!dest.live or dest.drop_pending) continue;
            if (dest == from) {
                if (include_self) self.enqueueBytes(dest, bytes) catch self.dropConn(dest);
                continue;
            }
            var shared = false;
            for (self.chans.items) |*chan| {
                if (self.onChan(chan, from) and self.onChan(chan, dest)) {
                    shared = true;
                    break;
                }
            }
            if (shared) self.enqueueBytes(dest, bytes) catch self.dropConn(dest);
        }
    }

    fn removeMember(_: *PortableServer, chan: *PortableChan, conn: *PortableConn) void {
        var w: usize = 0;
        for (chan.members[0..chan.live]) |member| {
            if (member == conn) continue;
            chan.members[w] = member;
            w += 1;
        }
        chan.live = w;
    }

    fn detachChan(self: *PortableServer, conn: *PortableConn) void {
        for (self.chans.items) |*chan| {
            var w: usize = 0;
            var i: usize = 0;
            while (i < chan.live) : (i += 1) {
                if (chan.members[i] == conn) continue;
                chan.members[w] = chan.members[i];
                w += 1;
            }
            chan.live = w;
        }
    }

    fn freeChans(self: *PortableServer) void {
        for (self.chans.items) |chan| {
            self.allocator.free(chan.name);
            if (chan.members.len != 0) self.allocator.free(chan.members);
        }
        self.chans.deinit(self.allocator);
        self.chans = .empty;
    }

    fn findConn(self: *PortableServer, token: RingFdToken) ?*PortableConn {
        for (self.conns.items) |conn| {
            if (conn.token.slot == token.slot and conn.token.gen == token.gen) return conn;
        }
        return null;
    }
};

fn portableAgain(result: i32) bool {
    return result == -4 or result == -11 or result == -35;
}

test "GAP-X1 PortableServer answers PING through processLine" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = PortableServer.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    try std.testing.expectError(error.SocketFailed, io_backend.pullAccept(-1));
    var addr = posix.sockaddr.in{
        .port = std.mem.nativeToBig(u16, port),
        .addr = std.mem.nativeToBig(u32, 0x7f000001),
    };
    var tv = posix.timeval{ .sec = 2, .usec = 0 };
    const rounds = [_][]const u8{ "lane", "two", "third" };
    for (rounds, 0..) |token, round| {
        const raw = portable_test_system.socket(posix.AF.INET, posix.SOCK.STREAM | posix.SOCK.CLOEXEC, posix.IPPROTO.TCP);
        if (posix.errno(raw) != .SUCCESS) {
            if (round == 0) return error.SkipZigTest;
            return error.Unexpected;
        }
        const client: linux.fd_t = @intCast(raw);
        defer _ = portable_test_system.close(client);
        if (posix.errno(portable_test_system.connect(client, @ptrCast(&addr), @sizeOf(posix.sockaddr.in))) != .SUCCESS) return error.Unexpected;
        if (posix.errno(portable_test_system.setsockopt(client, posix.SOL.SOCKET, posix.SO.RCVTIMEO, std.mem.asBytes(&tv), @sizeOf(posix.timeval))) != .SUCCESS) return error.Unexpected;
        var msg_buf: [32]u8 = undefined;
        const msg = std.fmt.bufPrint(&msg_buf, "PING {s}\r\n", .{token}) catch return error.Unexpected;
        var off: usize = 0;
        while (off < msg.len) {
            const wrote = portable_test_system.write(client, msg[off..].ptr, msg.len - off);
            switch (posix.errno(wrote)) {
                .SUCCESS => {
                    if (wrote == 0) return error.Unexpected;
                    off += @intCast(wrote);
                },
                .INTR => continue,
                else => return error.Unexpected,
            }
        }
        var spins: u8 = 0;
        while (spins < 12) : (spins += 1) try server.runOnce();
        var got: [128]u8 = @splat(0);
        const read_rc = portable_test_system.read(client, &got, got.len);
        if (posix.errno(read_rc) != .SUCCESS or read_rc == 0) return error.Unexpected;
        const text = got[0..@intCast(read_rc)];
        try std.testing.expect(std.mem.indexOf(u8, text, "PONG") != null);
        try std.testing.expect(std.mem.indexOf(u8, text, token) != null);
        _ = portable_test_system.shutdown(client, 2);
        var drain: u8 = 0;
        while (drain < 12) : (drain += 1) try server.runOnce();
    }
    try std.testing.expectError(error.Unsupported, io_backend.refuseForeignCapsule());
    std.debug.print("GAP-X1 branch=PortableServer answered PING lane two third with PONG through processLine on {s}\n", .{@tagName(server.backend.family)});
}

test "GAP-X4 PortableServer joins and fans out PRIVMSG" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = PortableServer.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var addr = posix.sockaddr.in{
        .port = std.mem.nativeToBig(u16, port),
        .addr = std.mem.nativeToBig(u32, 0x7f000001),
    };
    var tv = posix.timeval{ .sec = 2, .usec = 0 };
    var fds = [3]linux.fd_t{ -1, -1, -1 };
    defer {
        for (fds) |fd| {
            if (fd >= 0) _ = portable_test_system.close(fd);
        }
    }
    for (&fds, 0..) |*slot, i| {
        const raw = portable_test_system.socket(posix.AF.INET, posix.SOCK.STREAM | posix.SOCK.CLOEXEC, posix.IPPROTO.TCP);
        if (posix.errno(raw) != .SUCCESS) {
            if (i == 0) return error.SkipZigTest;
            return error.Unexpected;
        }
        slot.* = @intCast(raw);
        if (posix.errno(portable_test_system.connect(slot.*, @ptrCast(&addr), @sizeOf(posix.sockaddr.in))) != .SUCCESS) return error.Unexpected;
        if (posix.errno(portable_test_system.setsockopt(slot.*, posix.SOL.SOCKET, posix.SO.RCVTIMEO, std.mem.asBytes(&tv), @sizeOf(posix.timeval))) != .SUCCESS) return error.Unexpected;
        var reg_buf: [64]u8 = undefined;
        const reg = std.fmt.bufPrint(&reg_buf, "NICK b{d}\r\nUSER b{d} 0 * :bench\r\n", .{ i, i }) catch return error.Unexpected;
        var off: usize = 0;
        while (off < reg.len) {
            const wrote = portable_test_system.write(slot.*, reg[off..].ptr, reg.len - off);
            switch (posix.errno(wrote)) {
                .SUCCESS => {
                    if (wrote == 0) return error.Unexpected;
                    off += @intCast(wrote);
                },
                .INTR => continue,
                else => return error.Unexpected,
            }
        }
        if (!try portableExpect(&server, slot.*, " 001 ")) return error.Unexpected;
    }
    for (fds) |fd| {
        var join_buf: [32]u8 = undefined;
        const join = std.fmt.bufPrint(&join_buf, "JOIN #bench\r\n", .{}) catch return error.Unexpected;
        var off: usize = 0;
        while (off < join.len) {
            const wrote = portable_test_system.write(fd, join[off..].ptr, join.len - off);
            switch (posix.errno(wrote)) {
                .SUCCESS => {
                    if (wrote == 0) return error.Unexpected;
                    off += @intCast(wrote);
                },
                .INTR => continue,
                else => return error.Unexpected,
            }
        }
        if (!try portableExpect(&server, fd, " 366 ")) return error.Unexpected;
    }
    const token = "x4fan";
    var msg_buf: [64]u8 = undefined;
    const msg = std.fmt.bufPrint(&msg_buf, "PRIVMSG #bench :{s}\r\n", .{token}) catch return error.Unexpected;
    var off: usize = 0;
    while (off < msg.len) {
        const wrote = portable_test_system.write(fds[0], msg[off..].ptr, msg.len - off);
        switch (posix.errno(wrote)) {
            .SUCCESS => {
                if (wrote == 0) return error.Unexpected;
                off += @intCast(wrote);
            },
            .INTR => continue,
            else => return error.Unexpected,
        }
    }
    if (!try portableExpect(&server, fds[1], token)) return error.Unexpected;
    if (!try portableExpect(&server, fds[2], token)) return error.Unexpected;
    var live_nodelay: usize = 0;
    for (server.conns.items) |conn| {
        if (!conn.live) continue;
        var nodelay: u32 = 0;
        var opt_len: posix.socklen_t = @sizeOf(u32);
        const rc = portable_test_system.getsockopt(conn.fd, posix.IPPROTO.TCP, 1, @ptrCast(&nodelay), &opt_len);
        if (posix.errno(rc) != .SUCCESS or opt_len != @sizeOf(u32)) return error.Unexpected;
        // OpenBSD returns the enabled TF_NODELAY bit (4); the public option is
        // boolean. Linux normalizes its readback to exactly 1.
        const enabled = if (builtin.os.tag == .openbsd) nodelay != 0 else nodelay == 1;
        try std.testing.expect(enabled);
        live_nodelay += 1;
    }
    if (live_nodelay != 3) return error.Unexpected;

    // A full bounded queue disconnects that receiver. Detaching its
    // membership must not skip the following healthy receiver in this fan-out.
    var slow_token: ?RingFdToken = null;
    for (server.conns.items) |conn| {
        if (!std.mem.eql(u8, conn.state.session.displayName(), "b1")) continue;
        try std.testing.expect(!conn.send_armed);
        slow_token = conn.token;
        conn.send_len = conn.send_buf.len;
        const full = try std.testing.allocator.alloc(u8, max_portable_pending_output);
        defer std.testing.allocator.free(full);
        @memset(full, 'x');
        try conn.pending_output.appendSlice(std.testing.allocator, full);
    }
    try std.testing.expect(slow_token != null);
    try writeAllFd(fds[0], "PRIVMSG #bench :after-slow-receiver\r\n");
    try std.testing.expect(try portableExpect(&server, fds[2], "after-slow-receiver"));
    var drains: usize = 0;
    while (server.findConn(slow_token.?) != null and drains < 16) : (drains += 1)
        try server.runOnce();
    try std.testing.expect(server.findConn(slow_token.?) == null);
    std.debug.print("GAP-X4 branch=PortableServer registered three clients, answered 366, fanned out PRIVMSG, and set TCP_NODELAY on {s}\n", .{@tagName(server.backend.family)});
}

test "PortableServer churn preserves nick ownership and ignores retired completion tokens" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = PortableServer.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .max_clients = 2, .chanlimit = 1 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var owner_fd = try connectPortableLoopbackForTest(port);
    defer if (owner_fd >= 0) closeFd(owner_fd);
    try writeAllFd(owner_fd, "NICK Owner\r\nUSER owner 0 * :Owner\r\n");
    try std.testing.expect(try portableExpect(&server, owner_fd, " 001 "));
    const owner = server.conns.items[0];
    try writeAllFd(owner_fd, "JOIN #keeper\r\n");
    try std.testing.expect(try portableExpect(&server, owner_fd, " 366 "));
    try writeAllFd(owner_fd, "JOIN #over-channel-limit\r\n");
    try std.testing.expect(try portableExpect(&server, owner_fd, " 405 "));
    try std.testing.expectEqual(@as(usize, 1), server.chans.items.len);

    const guest_fd = try connectPortableLoopbackForTest(port);
    var guest_open = true;
    defer if (guest_open) closeFd(guest_fd);
    try writeAllFd(guest_fd, "NICK owner\r\nUSER guest 0 * :Guest\r\n");
    try std.testing.expect(try portableExpect(&server, guest_fd, " 433 "));
    try std.testing.expect(!server.conns.items[1].state.session.registered());
    try writeAllFd(guest_fd, "NICK Guest\r\n");
    try std.testing.expect(try portableExpect(&server, guest_fd, " 001 "));
    try writeAllFd(guest_fd, "NICK OWNER\r\n");
    try std.testing.expect(try portableExpect(&server, guest_fd, " 433 "));
    try std.testing.expectEqualStrings("Guest", server.conns.items[1].state.session.displayName());
    const excess_fd = try connectPortableLoopbackForTest(port);
    defer closeFd(excess_fd);
    const next_slot = server.next_slot;
    var admission_spins: usize = 0;
    while (admission_spins < 4) : (admission_spins += 1) try server.runOnce();
    var refused: [1]u8 = undefined;
    try std.testing.expectEqual(@as(usize, 0), try readFd(excess_fd, &refused));
    try std.testing.expectEqual(@as(usize, 2), server.conns.items.len);
    try std.testing.expectEqual(next_slot, server.next_slot);
    closeFd(guest_fd);
    guest_open = false;
    var drains: usize = 0;
    while (server.conns.items.len != 1 and drains < 16) : (drains += 1) try server.runOnce();
    try std.testing.expectEqual(@as(usize, 1), server.conns.items.len);

    for (0..64) |round| {
        const fd = try connectPortableLoopbackForTest(port);
        var open = true;
        defer if (open) closeFd(fd);
        var register: [128]u8 = undefined;
        const commands = try std.fmt.bufPrint(&register, "NICK Churn\r\nUSER churn 0 * :Churn\r\nJOIN #churn-{d}\r\n", .{round});
        try writeAllFd(fd, commands);
        var spins: usize = 0;
        while ((server.conns.items.len != 2 or !server.conns.items[1].state.session.registered()) and spins < 16) : (spins += 1)
            try server.runOnce();
        try std.testing.expectEqual(@as(usize, 2), server.conns.items.len);
        try std.testing.expect(server.conns.items[1].state.session.registered());
        try std.testing.expectEqual(@as(usize, 2), server.chans.items.len);
        const retired = server.conns.items[1].token;
        try writeAllFd(fd, "QUIT :churn complete\r\n");
        drains = 0;
        while (server.conns.items.len != 1 and drains < 16) : (drains += 1) try server.runOnce();
        try std.testing.expectEqual(@as(usize, 1), server.conns.items.len);
        try std.testing.expectEqual(@as(usize, 1), server.chans.items.len);
        closeFd(fd);
        open = false;
        try server.dispatch(.{ .op = .recv, .token = retired, .result = 0 });
        try server.dispatch(.{ .op = .send, .token = retired, .result = 0 });
        try std.testing.expect(owner.live);
    }
    try writeAllFd(owner_fd, "PING :after-churn\r\n");
    try std.testing.expect(try portableExpect(&server, owner_fd, "after-churn"));
    closeFd(owner_fd);
    owner_fd = -1;
    drains = 0;
    while (server.conns.items.len != 0 and drains < 16) : (drains += 1) try server.runOnce();
    try std.testing.expectEqual(@as(usize, 0), server.conns.items.len);
    try std.testing.expectEqual(@as(usize, 0), server.chans.items.len);
    const reused_fd = try connectPortableLoopbackForTest(port);
    defer closeFd(reused_fd);
    try writeAllFd(reused_fd, "NICK owner\r\nUSER next 0 * :Next\r\n");
    try std.testing.expect(try portableExpect(&server, reused_fd, " 001 "));
}

fn portableChanName(name: []const u8, max_len: usize) bool {
    if (name.len < 2 or name.len > max_len) return false;
    if (name[0] != '#' and name[0] != '&') return false;
    for (name) |byte| {
        if (byte <= 0x20 or byte == 0x7f or byte == ',' or byte == ':') return false;
    }
    return true;
}

test "PortableServer defers full-queue disconnect until fanout completes" {
    var server = PortableServer{ .allocator = std.testing.allocator };
    defer {
        server.freeChans();
        server.conns.deinit(std.testing.allocator);
    }
    var states: [3]ConnState = @splat(.{});
    var conns = [_]PortableConn{
        .{ .state = &states[0], .send_armed = true },
        .{ .state = &states[1], .send_armed = true },
        .{ .state = &states[2], .send_armed = true },
    };
    const nicks = [_][]const u8{ "alice", "bob", "cara" };
    for (&conns, &states, nicks) |*conn, *state, nick| {
        try state.session.setNick(nick);
        state.session.registration.registered = true;
        try server.conns.append(std.testing.allocator, conn);
    }
    defer conns[0].pending_output.deinit(std.testing.allocator);
    const full = try std.testing.allocator.alloc(u8, max_portable_pending_output);
    defer std.testing.allocator.free(full);
    @memset(full, 'x');
    try conns[0].pending_output.appendSlice(std.testing.allocator, full);
    conns[0].send_len = conns[0].send_buf.len;

    const nick_chan = try server.ensureChan("#nick");
    for (&conns) |*conn| try server.addMember(nick_chan, conn);
    try states[0].session.setNick("alice2");
    server.broadcastShared(&conns[0], ":alice!user@localhost NICK :alice2\r\n", true);
    const nick_peer = conns[1].send_buf[0..conns[1].send_len];
    const nick_at = std.mem.indexOf(u8, nick_peer, " NICK :alice2") orelse return error.Unexpected;
    const nick_quit_at = std.mem.indexOf(u8, nick_peer, " QUIT :Connection closed") orelse return error.Unexpected;
    try std.testing.expect(nick_at < nick_quit_at);
    try std.testing.expect(!conns[0].live);

    conns[0].live = true;
    conns[1].send_len = 0;
    conns[2].send_len = 0;
    _ = try server.ensureChan("#part");
    _ = try server.ensureChan("#shared");
    const part_chan = server.findChan("#part").?;
    const shared_chan = server.findChan("#shared").?;
    for (&conns) |*conn| {
        try server.addMember(part_chan, conn);
        try server.addMember(shared_chan, conn);
    }
    const part = try irc_line.parseLine("PART #part :bye");
    try server.handleChannel(&conns[0], part);
    const part_peer = conns[1].send_buf[0..conns[1].send_len];
    const part_at = std.mem.indexOf(u8, part_peer, " PART #part :bye") orelse return error.Unexpected;
    const part_quit_at = std.mem.indexOf(u8, part_peer, " QUIT :Connection closed") orelse return error.Unexpected;
    try std.testing.expect(part_at < part_quit_at);
    try std.testing.expect(!conns[0].live);
}

const portable_test_system = if (builtin.os.tag == .openbsd) posix.system else linux;

fn connectPortableLoopbackForTest(port: u16) !linux.fd_t {
    const fd = if (comptime builtin.os.tag == .openbsd)
        try connectNativeLoopbackForTest(.ipv4, port)
    else
        try connectLoopback(port);
    errdefer closeFd(fd);
    const timeout: posix.timeval = .{ .sec = 2, .usec = 0 };
    if (posix.errno(portable_test_system.setsockopt(fd, posix.SOL.SOCKET, posix.SO.RCVTIMEO, std.mem.asBytes(&timeout), @sizeOf(posix.timeval))) != .SUCCESS) return error.Unexpected;
    return fd;
}

fn portableExpect(server: *PortableServer, fd: linux.fd_t, needle: []const u8) !bool {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.Unsupported;
    var acc: [8192]u8 = undefined;
    var n: usize = 0;
    var warm: u8 = 0;
    while (warm < 4) : (warm += 1) try server.runOnce();
    var spins: u8 = 0;
    while (spins < 4 and n < acc.len) : (spins += 1) {
        try server.runOnce();
        const got = portable_test_system.read(fd, acc[n..].ptr, acc.len - n);
        switch (posix.errno(got)) {
            .SUCCESS => {
                if (got == 0) return false;
                n += @intCast(got);
                if (std.mem.indexOf(u8, acc[0..n], needle) != null) return true;
            },
            .INTR, .AGAIN => continue,
            else => return false,
        }
    }
    return std.mem.indexOf(u8, acc[0..n], needle) != null;
}

fn expectListenerKernelOptions(fd: linux.fd_t, cpu: u32) !void {
    try std.testing.expectEqual(kernel_linux.fastopen_queue, try kernel_linux.readU32Option(fd, linux.IPPROTO.TCP, linux.TCP.FASTOPEN));
    try std.testing.expectEqual(kernel_linux.user_timeout_ms, try kernel_linux.readU32Option(fd, linux.IPPROTO.TCP, linux.TCP.USER_TIMEOUT));
    try std.testing.expectEqual(cpu, try kernel_linux.readU32Option(fd, posix.SOL.SOCKET, linux.SO.INCOMING_CPU));
}

