    if (posix.errno(linux.dup2(pipes[0], 2048)) != .SUCCESS) return error.Unexpected;
    if (posix.errno(linux.dup2(pipes[1], 2049)) != .SUCCESS) return error.Unexpected;
    _ = linux.close(pipes[0]);
