        else => return err,
    };
    defer closed.deinit();
    try std.testing.expect(closed.surplus_closed_with_close_range);
    try std.testing.expect(posix.errno(linux.fcntl(2048, posix.F.GETFD, 0)) == .BADF);
    try std.testing.expect(posix.errno(linux.fcntl(2049, posix.F.GETFD, 0)) == .BADF);
    try expectPidfdIsSelf(closed.self_pidfd);

    var sharded = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .num_shards = 2,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer sharded.deinit();
    try std.testing.expect(sharded.msg_ring_booted);
    try std.testing.expect(sharded.reactors.len == 2);
    std.debug.print("GAP-X3 branch=close_range drops surplus listeners and IORING_OP_MSG_RING boots a second reactor\n", .{});
}

test "GAP-X3 landlock and seccomp restrict a forked daemon sandbox" {
    if (builtin.os.tag != .linux) return error.SkipZigTest;
    const child = linux.fork();
    if (posix.errno(child) != .SUCCESS) return error.Unexpected;
    if (child == 0) linux.exit_group(kernel_linux.sandboxChildStatus());
    var status: i32 = 0;
    const waited = linux.waitpid(@intCast(child), &status, 0);
    if (posix.errno(waited) != .SUCCESS) return error.Unexpected;
    try std.testing.expect((status & 0x7f) == 0);
    const code: u8 = @intCast((status >> 8) & 0xff);
    var dir_buf: [80]u8 = undefined;
    const dir = std.fmt.bufPrintSentinel(&dir_buf, "/tmp/onyx-x3-ll-{d}", .{child}, 0) catch return error.Unexpected;
    var file_buf: [96]u8 = undefined;
    const file_path = std.fmt.bufPrintSentinel(&file_buf, "{s}/inside", .{dir}, 0) catch return error.Unexpected;
    _ = linux.unlinkat(linux.AT.FDCWD, file_path.ptr, 0);
    _ = linux.unlinkat(linux.AT.FDCWD, dir.ptr, linux.AT.REMOVEDIR);
    if (code != 0) {
        std.debug.print("GAP-X3 sandbox child status {d}\n", .{code});
        return error.TestUnexpectedResult;
    }
    std.debug.print("GAP-X3 branch=landlock confines a directory and seccomp denies ptrace\n", .{});
}

const CompletionHandler = struct {
    server: *LinuxServer,
    err: ?anyerror = null,

    pub fn onCompletion(self: *CompletionHandler, completion: ringlane.Completion) void {
        // Never abandon the remainder of a CQE batch after one handler error.
        // Later CQEs may be the exact RECV/SEND ownership releases that make a
        // connection safe to close or a Helix snapshot exact. Preserve only the
        // first error for the caller while dispatching every copied completion.
        // World-lock boundary (multithreading Phase B): take the shared world's
        // write lock once around the whole completion so concurrent reactors
        // serialize all world (channel/nick/membership) reads + mutations + the
        // delivery they drive. This is the single outermost acquire — no handler
        // re-locks the world, so the non-recursive lock can never self-deadlock.
        // Per-instance state (clients table, send buffers, ring) is reactor-local
        // and needs no lock. Uncontended with one reactor (a couple of atomics).
        self.server.world.lockWrite();
        defer self.server.world.unlockWrite();
        switch (completion) {
            .accept => |event| self.server.handleAccept(event) catch |err| {
                if (self.err == null) self.err = err;
            },
            .recv => |event| self.server.handleRecv(event) catch |err| {
                self.recordOpErr(err);
            },
            .send => |event| self.server.handleSend(event) catch |err| {
                self.recordOpErr(err);
            },
            .connect => |event| self.server.handleConnect(event) catch |err| {
                self.recordOpErr(err);
            },
            .timeout => self.server.onTimerTick(),
            // poll: the cross-reactor wake eventfd became readable — drain it so
            // the loop ran (and, once sharded, drain this reactor's mailbox).
            .poll => |event| {
                if (event.token.slot == wake_token.slot) self.server.onWakePoll();
            },
            .other => {},
        }
    }

    /// Record a per-connection op error, tolerating completions that arrive for a
    /// connection whose slot was already freed (e.g. an in-flight recv reaping
    /// after `closeConn` drained and freed the slot). The generational slab makes
    /// such stale tokens impossible to alias a reused slot, so `ClientNotFound`
    /// here is a benign lifecycle event, not a fatal loop error.
    fn recordOpErr(self: *CompletionHandler, err: anyerror) void {
        if (err == error.ClientNotFound) return;
        if (self.err == null) self.err = err;
    }
};

fn tokenFromId(id: client_model.ClientId) ServerError!RingFdToken {
    if (id.gen > ((@as(u32, 1) << 28) - 1)) return error.TokenOutOfRange;
    return .{ .slot = id.slot, .gen = id.gen };
}

fn idFromToken(token: RingFdToken) client_model.ClientId {
    // A completion's token always names a connection on the reactor whose ring
    // produced it — i.e. the reactor bound to this thread. Stamp that reactor's
    // shard so the reconstructed id matches the slab that allocated it (the slab
    // is keyed by `shard`, so a 0 here would miss on any shard but 0). Off any
    // reactor thread (direct test calls), `current_reactor` is null and we fall
    // back to shard 0 — the single-reactor identity, exactly as before.
    const shard_id: u12 = if (current_reactor) |r| r.shard_id else 0;
    return .{ .shard = shard_id, .slot = @intCast(token.slot), .gen = token.gen };
}

fn worldIdFromClient(id: client_model.ClientId) world_model.ClientId {
    return .{ .shard = id.shard, .slot = id.slot, .gen = id.gen };
}

/// The USER-supplied username of the member behind a world client id, or "user".
fn usernameOf(self: *LinuxServer, world_id: world_model.ClientId) []const u8 {
    if (self.connFor(clientIdFromWorld(world_id))) |c| return c.session.username();
    return "user";
}

/// Find a tag's value in a raw IRCv3 tag segment (`a=1;+typing=active;b`).
/// Returns the value slice (may be empty), or null if the key is absent.
fn findTagValue(tags_raw: []const u8, key: []const u8) ?[]const u8 {
    var it = std.mem.splitScalar(u8, tags_raw, ';');
    while (it.next()) |pair| {
        const eq = std.mem.indexOfScalar(u8, pair, '=') orelse {
            if (std.mem.eql(u8, pair, key)) return pair[0..0]; // bare key, no value
            continue;
        };
        if (std.mem.eql(u8, pair[0..eq], key)) return pair[eq + 1 ..];
    }
    return null;
}

fn clientTagAllowedForSession(session: *const dispatch.ClientSession, key: []const u8) bool {
    if (session.hasCap(.message_tags)) return true;
    if (std.mem.eql(u8, key, topic_tag.tag_key)) return session.hasCap(.onyx_topics);
    if (e2ee_policy.isEncryptedTagKey(key)) return session.hasCap(.onyx_e2ee);
    if (msgedit.isTypingTag(key)) return session.hasCap(.typing);
    if (std.mem.eql(u8, key, "+draft/react") or std.mem.eql(u8, key, "+draft/unreact")) return session.hasCap(.react);
    if (std.mem.eql(u8, key, "+draft/reply")) return session.hasCap(.reply);
    if (std.mem.eql(u8, key, "+draft/edit") or std.mem.eql(u8, key, "+draft/revision")) return session.hasCap(.message_editing);
    return false;
}

fn clientTagsForSession(session: *const dispatch.ClientSession, raw: []const u8, out: []u8) []const u8 {
    var b = Buf{ .storage = out };
    var any = false;
    var it = std.mem.splitScalar(u8, raw, ';');
    while (it.next()) |pair| {
        if (pair.len == 0 or pair[0] != '+') continue;
        const eq = std.mem.indexOfScalar(u8, pair, '=') orelse pair.len;
        if (!clientTagAllowedForSession(session, pair[0..eq])) continue;
        if (any) b.appendByte(';') catch return b.written();
        b.append(pair) catch return b.written();
        any = true;
    }
    return b.written();
}

fn sanitizeTopicClientTags(
    tags: []const u8,
    strip_out: []u8,
    label_out: ?*?[]const u8,
    label_buf: []u8,
) []const u8 {
    if (!topic_tag.present(tags)) return tags;
    if (topic_tag.labelFromTags(tags, label_buf)) |label| {
        if (label_out) |out| out.* = label;
        return tags;
    }
    return topic_tag.stripTag(tags, strip_out);
}

fn sessionCanUseTagmsg(session: *const dispatch.ClientSession) bool {
    return session.hasCap(.message_tags) or session.hasCap(.typing) or session.hasCap(.react) or session.hasCap(.reply);
}

fn clientIdFromWorld(id: world_model.ClientId) client_model.ClientId {
    return .{ .shard = id.shard, .slot = id.slot, .gen = id.gen };
}

/// MonitorStore keys clients by a flat u64; convert to/from the packed ClientId.
fn monitorIdFromClient(id: client_model.ClientId) u64 {
    return @bitCast(id);
}

fn clientIdFromMonitor(id: u64) client_model.ClientId {
    return @bitCast(id);
}

fn allowsSessionSyncSibling(
    session: sessions_mod.Session,
    conn: *const ConnState,
    skip_a_flat: ?u64,
    skip_b_flat: ?u64,
) bool {
    if (!session.attached) return false;
    if (skip_a_flat) |skip| {
        if (session.client == skip) return false;
    }
    if (skip_b_flat) |skip| {
        if (session.client == skip) return false;
    }
    if (conn.closing) return false;
    if (conn.s2s != null or conn.s2s_secured != null) return false;
    // Exact-token siblings use the mandatory logical-session path. This helper
    // is only optional mirroring to a differently named account session.
    return conn.session.hasCap(.onyx_session_sync);
}

/// Map a MonitorStore numeric to the live server's numeric enum.
fn monitorNumeric(n: monitor.MonitorNumeric) Numeric {
    return switch (n) {
        .RPL_MONONLINE => .RPL_MONONLINE,
        .RPL_MONOFFLINE => .RPL_MONOFFLINE,
        .RPL_MONLIST => .RPL_MONLIST,
        .RPL_ENDOFMONLIST => .RPL_ENDOFMONLIST,
        .ERR_MONLISTFULL => .ERR_MONLISTFULL,
    };
}

/// OroWasm host callbacks: route a plugin's granted hostcalls to the live
/// connection. `ctx` is the per-invocation `*module_core.Core`. A plugin reply is
/// framed as a server NOTICE to the requesting client.
fn wasmReplyCb(ctx: *anyopaque, text: []const u8) void {
    const core: *module_core.Core = @ptrCast(@alignCast(ctx));
    var buf: [600]u8 = undefined;
    const line = std.fmt.bufPrint(&buf, ":{s} NOTICE {s} :{s}\r\n", .{ protocol_inventory.currentServerName(), core.conn.session.displayName(), text }) catch return;
    emitReplyLine(core.conn, line) catch {};
}
fn wasmLogCb(_: *anyopaque, text: []const u8) void {
    srvLog("onyx-server: wasm-plugin: {s}\n", .{text});
}
fn wasmNowCb(_: *anyopaque) i64 {
    return platform.monotonicMillis();
}

const Buf = struct {
    storage: []u8,
    len: usize = 0,

    fn append(self: *Buf, bytes: []const u8) ServerError!void {
        if (self.len + bytes.len > self.storage.len) return error.OutputTooSmall;
        @memcpy(self.storage[self.len .. self.len + bytes.len], bytes);
        self.len += bytes.len;
    }

    fn appendByte(self: *Buf, byte: u8) ServerError!void {
        if (self.len == self.storage.len) return error.OutputTooSmall;
        self.storage[self.len] = byte;
        self.len += 1;
    }

    fn written(self: *const Buf) []const u8 {
        return self.storage[0..self.len];
    }
};

fn clientOnlyTags(raw: []const u8, out: []u8) []const u8 {
    var b = Buf{ .storage = out };
    var any = false;
    var seen_keys: [irc_line.max_client_tag_count][]const u8 = undefined;
    var seen_count: usize = 0;
    var it = std.mem.splitScalar(u8, raw, ';');
    while (it.next()) |tag| {
        if (tag.len == 0 or tag[0] != '+') continue;
        const key_end = std.mem.indexOfScalar(u8, tag, '=') orelse tag.len;
        const key = tag[0..key_end];
        var duplicate = false;
        for (seen_keys[0..seen_count]) |seen| {
            if (std.mem.eql(u8, seen, key)) {
                duplicate = true;
                break;
            }
        }
        if (duplicate) continue;
        if (seen_count == seen_keys.len) break;
        const sep_len: usize = if (any) 1 else 0;
        const extra = tag.len + sep_len;
        if (b.len + extra > b.storage.len) break;
        if (any) b.appendByte(';') catch break;
        b.append(tag) catch break;
        seen_keys[seen_count] = key;
        seen_count += 1;
        any = true;
    }
    return b.written();
}

fn restoreCloexec(fds: []const linux.fd_t) void {
    for (fds) |fd| _ = setCloexec(fd, true);
}

fn setCloexec(fd: linux.fd_t, enabled: bool) bool {
    if (builtin.os.tag == .windows and fd > 0 and fd < 0x4000_0000) {
        // Native Helix imports sockets with WSA_FLAG_NO_HANDLE_INHERIT.
        // Their canonical IDs are registry keys, not kernel file handles.
        return enabled and io_backend.windowsSocketValid(fd);
    }
    if (builtin.os.tag == .openbsd or builtin.os.tag == .windows) {
        os_runtime.setCloexec(fd, enabled) catch return false;
        return true;
    }
    const flags: usize = if (enabled) posix.FD_CLOEXEC else 0;
    return linux.errno(linux.fcntl(fd, posix.F.SETFD, flags)) == .SUCCESS;
}

fn validCapturedBatchRef(ref: []const u8) bool {
    if (ref.len == 0 or ref.len > labeled_response.MAX_BATCH_REF_LEN) return false;
    for (ref) |ch| switch (ch) {
        'a'...'z', 'A'...'Z', '0'...'9', '-' => {},
        else => return false,
    };
    return true;
}

fn isApplicableHistoryBatchType(batch_type: []const u8) bool {
    return std.mem.eql(u8, batch_type, "chathistory") or
        std.mem.eql(u8, batch_type, chathistory_cmd.targets_batch_type);
}

/// A labeled CHATHISTORY response already has its protocol-defined batch. Keep
/// that one batch, validate all membership before emitting anything to the
/// connection, and put the command label on its opening BATCH line.
fn emitLabeledApplicableHistoryBatch(
    sink: *FrameBufSink,
    label: []const u8,
    captured: []const u8,
) error{OutputTooSmall}!bool {
    var it = CrlfReplyIterator{ .bytes = captured };
    const opening = it.next() orelse return false;
    if (opening.len < 2 or !std.mem.endsWith(u8, opening, "\r\n")) return error.OutputTooSmall;
    const parsed_open = irc_line.parseLine(opening) catch return error.OutputTooSmall;
    if (!std.ascii.eqlIgnoreCase(parsed_open.command, "BATCH")) return false;

    // A captured non-history batch still follows the generic labeled-response
    // contract. A malformed BATCH opening fails closed rather than being nested.
    if (parsed_open.param_count < 2 or parsed_open.params[0].len < 2 or
        parsed_open.params[0][0] != '+' or !validCapturedBatchRef(parsed_open.params[0][1..]))
    {
        return error.OutputTooSmall;
    }
    if (!isApplicableHistoryBatchType(parsed_open.params[1])) return false;
    const ref = parsed_open.params[0][1..];

    var labeled_open_buf: [labeled_response.MAX_WIRE_LINE]u8 = undefined;
    const labeled_open = labeled_response.tagLine(label, opening, &labeled_open_buf) catch
        return error.OutputTooSmall;
    try sink.appendLine(labeled_open);

    while (it.next()) |line| {
        if (line.len < 2 or !std.mem.endsWith(u8, line, "\r\n")) return error.OutputTooSmall;
        const parsed = irc_line.parseLine(line) catch return error.OutputTooSmall;
        if (std.ascii.eqlIgnoreCase(parsed.command, "BATCH")) {
            if (parsed.tags_raw != null or parsed.param_count != 1 or parsed.params[0].len != ref.len + 1 or
                parsed.params[0][0] != '-' or !std.mem.eql(u8, parsed.params[0][1..], ref) or it.next() != null)
            {
                return error.OutputTooSmall;
            }
            try sink.appendLine(line);
            return true;
        }
        const member_ref = batchTagValue(&parsed) orelse return error.OutputTooSmall;
        if (!std.mem.eql(u8, member_ref, ref)) return error.OutputTooSmall;
        try sink.appendLine(line);
    }
    return error.OutputTooSmall;
}

/// Reframe a captured labeled command's plaintext replies under `label` and
/// emit them on the wire (through the normal WS/TLS seam). Bulk commands receive
/// a bounded larger capture in dispatchRegistered; any remaining capture
/// overflow fails closed before a truncated IRC line can reach the transport.
fn emitLabeledIssuer(
    conn: *ConnState,
    label: []const u8,
    capture: *const ReplyCapture,
    allocator: std.mem.Allocator,
) ServerError!void {
    if (capture.overflowed) return error.OutputTooSmall;
    const lines = std.mem.count(u8, capture.captured(), "\n");
    const framing_slack = std.math.mul(usize, lines + 3, 256) catch return error.OutputTooSmall;
    const capacity = std.math.add(usize, capture.captured().len, framing_slack) catch return error.OutputTooSmall;
    const frame_buf = allocator.alloc(u8, @max(capacity, default_reply_bytes)) catch return error.OutputTooSmall;
    defer allocator.free(frame_buf);
    var sink = FrameBufSink{ .buf = frame_buf };
    const emitted_existing_batch = try emitLabeledApplicableHistoryBatch(&sink, label, capture.captured());
    if (!emitted_existing_batch) {
        var it = CrlfReplyIterator{ .bytes = capture.captured() };
        labeled_response.emitIterator(&sink, label, labeled_batch_ref, &it) catch return error.OutputTooSmall;
    }
    return LinuxServer.appendHistoryReplay(conn, sink.written());
}

/// The same labeled-response renderer used by dispatch, before any authority or
/// output publication. Owned final bytes are wiped after preparation/abort; the
/// bounded capture must never turn overflow into a successful media reply.
fn prepareMediaIssuerBytes(allocator: std.mem.Allocator, capture: *const ReplyCapture, label: ?[]const u8) ![]u8 {
    if (capture.overflowed) return error.OutputTooSmall;
    const selected = label orelse return allocator.dupe(u8, capture.captured());
    const lines = std.mem.count(u8, capture.captured(), "\n");
    const slack = std.math.mul(usize, lines + 3, 256) catch return error.OutputTooSmall;
    const capacity = std.math.add(usize, capture.captured().len, slack) catch return error.OutputTooSmall;
    const storage = try allocator.alloc(u8, @max(capacity, default_reply_bytes));
    defer {
        std.crypto.secureZero(u8, storage);
        allocator.free(storage);
    }
    var sink = FrameBufSink{ .buf = storage };
    const existing_batch = try emitLabeledApplicableHistoryBatch(&sink, selected, capture.captured());
    if (!existing_batch) {
        var it = CrlfReplyIterator{ .bytes = capture.captured() };
        try labeled_response.emitIterator(&sink, selected, labeled_batch_ref, &it);
    }
    return allocator.dupe(u8, sink.written());
}

/// Source-private, one physical owner turn. Preparation owns the final labeled
/// IRC bytes and WS frames before TLS/deferred/kernel queue admission. Endpoint
/// candidates are validated separately; this plan cannot publish media authority.
const PreparedMediaOutput = struct {
    server: *LinuxServer,
    id: client_model.ClientId,
    conn: *ConnState,
    adapter: *tls_conn.TlsConn,
    allocator: std.mem.Allocator,
    channel: [128]u8 = @splat(0),
    channel_len: usize,
    plaintext: []u8,
    raw_chunk: [1][]const u8,
    framed: ?ws_output.Prepared,
    snapshot: Snapshot,
    newly_funded_control: bool,
    done: bool = false,
    custody: union(enum) {
        software: struct {
            write: tls_conn.TlsConn.PreparedWrite,
            queue: sendq.PreparedAppend(*ConnState),
        },
        kernel: sendq.PreparedAppend(*ConnState),
        deferred: sendq.PreparedDeferred(*ConnState),
    },

    const Snapshot = struct {
        fd: linux.fd_t,
        token: RingFdToken,
        send_len: usize,
        send_offset: usize,
        send_overflow_len: usize,
        send_overflow_ptr: usize,
        send_overflow_capacity: usize,
        sendq_cap: usize,
        send_armed: bool,
        submitted_len: usize,
        submitted_offset: usize,
        deferred_len: usize,
        deferred_ptr: usize,
        deferred_capacity: usize,
        deferred_charge: usize,
        control_charge: usize,
        kernel_prefix: u64,
        overflow_allocator: std.mem.Allocator,
        ws: ?*WsState,
        tx_offloaded: bool,
        rx_offloaded: bool,
        version: ?tls_conn.Version,
        read_sequence: u64,
        write_sequence: u64,
        control_phase: tls_conn.ControlBarrierPhase,
        held_len: u32,
        reply_pending: bool,
        reply_sent: u8,
        open_control: u8,
        alert_prefix_len: u8,
        alert_prefix_byte: u8,

        fn capture(c: *const ConnState, t: *const tls_conn.TlsConn) Snapshot {
            return .{
                .fd = c.fd,
                .token = c.token,
                .send_len = c.send_len,
                .send_offset = c.send_offset,
                .send_overflow_len = c.send_overflow.items.len,
                .send_overflow_ptr = @intFromPtr(c.send_overflow.items.ptr),
                .send_overflow_capacity = c.send_overflow.capacity,
                .sendq_cap = c.sendq_cap,
                .send_armed = c.send_armed,
                .submitted_len = c.send_submitted_len,
                .submitted_offset = c.send_submitted_offset,
                .deferred_len = c.tls_deferred_plain.items.len,
                .deferred_ptr = @intFromPtr(c.tls_deferred_plain.items.ptr),
                .deferred_capacity = c.tls_deferred_plain.capacity,
                .deferred_charge = c.tls_deferred_charge,
                .control_charge = c.tls_control_charge,
                .kernel_prefix = c.tls_kernel_prefix_remaining,
                .overflow_allocator = c.overflow_allocator,
                .ws = c.ws,
                .tx_offloaded = c.tls_tx_offloaded,
                .rx_offloaded = c.tls_rx_offloaded,
                .version = t.negotiatedVersion(),
                .read_sequence = switch (t.engine) {
                    inline .tls12, .tls13 => |*s| s.app_read_seq,
                    .undecided => 0,
                },
                .write_sequence = switch (t.engine) {
                    inline .tls12, .tls13 => |*s| s.app_write_seq,
                    .undecided => 0,
                },
                .control_phase = t.control_phase,
                .held_len = t.held_record_len,
                .reply_pending = t.tx_ku_reply_pending,
                .reply_sent = t.tx_ku_reply_sent,
                .open_control = t.rx_open_control_type,
                .alert_prefix_len = t.alert_prefix_len,
                .alert_prefix_byte = t.alert_prefix_byte,
            };
        }
    };

    fn requireCaller(server: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8) !*tls_conn.TlsConn {
        try server.requireMediaCaller(id, conn, channel);
        if (conn.fd < 0) return error.BadState;
        const t = conn.tls orelse return error.BadState;
        if (!t.handshakeDone() or t.terminal_error != null or t.control_turn_active or
            t.unpublished.items.len != 0 or conn.tls_tx_offloaded != t.ktls_tx_offloaded or
            conn.tls_rx_offloaded != t.ktls_rx_offloaded) return error.BadState;
        if (conn.ws) |ws| if (ws.phase != .open) return error.BadState;
        return t;
    }

    fn prepare(server: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, final_plaintext: []const u8) !PreparedMediaOutput {
        const t = try requireCaller(server, id, conn, channel);
        if (channel.len > 128 or final_plaintext.len == 0 or !std.mem.endsWith(u8, final_plaintext, "\r\n") or
            t.hasPreparedWrite()) return error.BadState;
        // Backend observation is outside the final routing cut. The original
        // owner retains this exact fd/adapter turn through publication. Kernel
        // sequence may advance under an armed SEND; its key epoch may not.
        if (conn.tls_tx_offloaded) {
            try t.validateKernelTxEpoch(conn.fd);
            try tls_conn.validateKernelTxPrefix(true, t.control_phase, t.tx_ku_reply_pending, @intCast(conn.tls_control_charge), conn.tls_kernel_prefix_remaining, sendq.wireBacklog(conn));
        }
        const allocator = server.allocator;
        const plaintext = try allocator.dupe(u8, final_plaintext);
        errdefer {
            std.crypto.secureZero(u8, plaintext);
            allocator.free(plaintext);
        }
        var framed: ?ws_output.Prepared = null;
        errdefer if (framed) |*frames| {
            std.crypto.secureZero(u8, frames.initial);
            std.crypto.secureZero(u8, frames.wire.items);
            std.crypto.secureZero(u8, frames.suffix.items);
            frames.deinit();
        };
        if (conn.ws) |ws| {
            const backlog = sendq.backlog(conn);
            if (backlog > conn.sendq_cap) return error.OutputTooSmall;
            framed = try ws_output.prepareSensitive(WsState.max_frame, conn.overflow_allocator, ws.tx_buf[0..ws.tx_len], &.{plaintext}, ws.tx_buf.len, conn.sendq_cap - @as(usize, @intCast(backlog)));
            if (framed.?.tail().len != 0 or framed.?.frameChunks().len == 0) return error.BadState;
        }
        const plaintext_chunks: []const []const u8 = if (framed) |*frames| frames.frameChunks() else &.{plaintext};
        const wire_plaintext = if (framed) |*frames| frames.bytes() else plaintext;
        const holding = t.control_phase == .userspace_requested_ku_held or t.control_phase == .kernel_control_read_held;
        var funded = false;
        errdefer if (funded) sendq.cancelControlReservation(conn);
        const custody: @FieldType(PreparedMediaOutput, "custody") = if (conn.tls_tx_offloaded) blk: {
            if (holding and conn.tls_control_charge == 0) {
                var credit = try sendq.prepareControlReservation(conn, 5);
                credit.commit();
                funded = true;
            }
            break :blk .{ .kernel = try sendq.prepareAppend(conn, wire_plaintext.len) };
        } else if (t.applicationOutputDeferred() or conn.tls_deferred_plain.items.len != 0) blk: {
            const charge = try t.applicationWireCharge(plaintext_chunks);
            if (holding and conn.tls_control_charge == 0 and charge != 0) {
                var credit = try sendq.prepareControlReservation(conn, 27);
                credit.commit();
                funded = true;
            }
            break :blk .{ .deferred = try sendq.prepareDeferredAppend(conn, plaintext_chunks, charge) };
        } else blk: {
            var write = try t.prepareWriteBatch(plaintext_chunks);
            errdefer write.deinit();
            break :blk .{ .software = .{ .write = write, .queue = try sendq.prepareAppend(conn, write.bytes().len) } };
        };
        var result: PreparedMediaOutput = .{
            .server = server,
            .id = id,
            .conn = conn,
            .adapter = t,
            .allocator = allocator,
            .channel_len = channel.len,
            .plaintext = plaintext,
            .raw_chunk = .{plaintext},
            .framed = framed,
            .snapshot = Snapshot.capture(conn, t),
            .newly_funded_control = funded,
            .custody = custody,
        };
        @memcpy(result.channel[0..channel.len], channel);
        return result;
    }

    /// Pure revalidation inside the final Domain cut; no getters, allocations,
    /// arming, callbacks or destructor. The enclosing command holds World and
    /// the same original connection owner turn throughout prepare/validate/commit.
    fn validate(self: *const PreparedMediaOutput) !void {
        if (self.done or try requireCaller(self.server, self.id, self.conn, self.channel[0..self.channel_len]) != self.adapter or
            !std.meta.eql(self.snapshot, Snapshot.capture(self.conn, self.adapter))) return error.BadState;
        if (self.framed) |*frames| {
            const ws = self.conn.ws orelse return error.BadState;
            if (ws.tx_len != frames.initial.len or !std.mem.eql(u8, ws.tx_buf[0..ws.tx_len], frames.initial)) return error.BadState;
        }
        switch (self.custody) {
            .software => |*prepared| if (!prepared.write.canCommit()) return error.BadState,
            .kernel => {
                if (self.adapter.hasPreparedWrite()) return error.BadState;
                try tls_conn.validateKernelTxPrefix(true, self.adapter.control_phase, self.adapter.tx_ku_reply_pending, @intCast(self.conn.tls_control_charge), self.conn.tls_kernel_prefix_remaining, sendq.wireBacklog(self.conn));
            },
            .deferred => |*prepared| {
                if (self.adapter.hasPreparedWrite() or try self.adapter.applicationWireCharge(self.chunks()) != prepared.charge) return error.BadState;
            },
        }
    }

    fn chunks(self: *const PreparedMediaOutput) []const []const u8 {
        return if (self.framed) |*frames| frames.frameChunks() else &self.raw_chunk;
    }

    /// Caller has validated every endpoint/profile/JOIN/output plan under ONE
    /// cut. All accepted storage publication is pure; retirement is deferred.
    fn commit(self: *PreparedMediaOutput) void {
        self.validate() catch unreachable;
        switch (self.custody) {
            .software => |*prepared| {
                prepared.queue.commit(prepared.write.bytes());
                prepared.write.commit();
            },
            .kernel => |*queue| queue.commit(if (self.framed) |*frames| frames.bytes() else self.plaintext),
            .deferred => |*retained| retained.commitRetainingMetadata(self.chunks()),
        }
        if (self.framed) |*frames| frames.commitTail(self.conn.ws.?);
        self.done = true;
    }

    /// Outside Domain, while source lifetimes still hold. Abort cancels only
    /// this unadmitted speculative credit; previously admitted obligations stay.
    fn deinit(self: *PreparedMediaOutput) void {
        switch (self.custody) {
            .software => |*prepared| {
                if (!self.done) prepared.queue.abort();
                prepared.write.deinit();
            },
            .kernel => |*queue| if (!self.done) queue.abort(),
            .deferred => |*retained| retained.deinit(),
        }
        if (!self.done and self.newly_funded_control) sendq.cancelControlReservation(self.conn);
        if (self.framed) |*frames| {
            std.crypto.secureZero(u8, frames.initial);
            std.crypto.secureZero(u8, frames.wire.items);
            std.crypto.secureZero(u8, frames.suffix.items);
            frames.deinit();
        }
        std.crypto.secureZero(u8, self.plaintext);
        self.allocator.free(self.plaintext);
        self.* = undefined;
    }
};

/// One private command-owned value constructs every agreed transport candidate
/// and the separate caller-offered Room capability profile. It is data, never
/// an endpoint, protected-output or source readiness receipt. World and the
/// original ConnState owner remain held through all preparation/publication.
const PreparedMediaNegotiation = struct {
    server: *LinuxServer,
    id: client_model.ClientId,
    conn: *ConnState,
    action: Action,
    channel: [128]u8 = @splat(0),
    channel_len: usize,
    offered: media_room.CallProfile,
    agreed: media_room.CallProfile,
    shared_before: ?media_room.CallProfile,
    expected_fp: ?[dtls_peer_verify_mod.digest_len]u8,
    wants_webrtc: bool,
    ws: ?*WsState,
    tx_denied: bool,
    media_enabled: bool,
    dtls_enabled: bool,
    ws_relay: bool,
    fallback_host: [255]u8 = @splat(0),
    fallback_host_len: usize,

    const Action = enum { offer, answer };

    /// CallProfile intentionally leaves unused codec tails uninitialized. Only
    /// semantic initialized values participate in the captured source relation.
    fn sameProfile(a: media_room.CallProfile, b: media_room.CallProfile) bool {
        return a.eql(b);
    }

    fn sameOptionalProfile(a: ?media_room.CallProfile, b: ?media_room.CallProfile) bool {
        if ((a == null) != (b == null)) return false;
        return if (a) |first| sameProfile(first, b.?) else true;
    }

    fn copyProfile(codecs: []const sdp.Codec, fec: sdp.Fec) !media_room.CallProfile {
        if (codecs.len == 0 or codecs.len > media_room.max_profile_codecs) return error.NoCommonCodec;
        var result: media_room.CallProfile = .{ .fec = fec, .codec_count = @intCast(codecs.len) };
        @memcpy(result.codecs[0..codecs.len], codecs);
        return result;
    }

    fn prepare(server: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, action: Action, codec_csv: []const u8, extra_args: []const []const u8) !PreparedMediaNegotiation {
        try server.requireMediaCaller(id, conn, channel);
        if (channel.len == 0 or channel.len > 128) return error.BadState;
        const host = server.config.media_host;
        if (host.len == 0 or host.len > 255 or std.mem.indexOfAny(u8, host, "\r\n\x00") != null) return error.BadState;
        var offered_storage: [media_room.max_profile_codecs]sdp.Codec = undefined;
        const offered_count = LinuxServer.parseCodecCsv(&offered_storage, codec_csv);
        if (offered_count == 0) return error.NoCodecs;
        const offered_fec: sdp.Fec = .{ .scheme = .rs_block, .redundancy = 1 };
        const offered = try copyProfile(offered_storage[0..offered_count], offered_fec);
        const shared = server.media_rooms.transportProfileOf(channel);
        if (shared) |profile| {
            if (profile.codec_count == 0 or profile.codec_count > media_room.max_profile_codecs) return error.BadState;
        }
        var expected_fp: ?[dtls_peer_verify_mod.digest_len]u8 = null;
        switch (LinuxServer.parseOfferedFingerprint(extra_args)) {
            .none => {},
            .malformed => return error.BadFingerprint,
            .ok => |digest| {
                if (!server.config.media_dtls_srtp) return error.DtlsUnavailable;
                expected_fp = digest;
            },
        }
        // Preserve the actual command's supported SFU profile. Raw offered
        // capabilities remain recorded even when this agreement denies them.
        const supported_codecs = [_]sdp.Codec{
            .{ .tag = .cadencevox, .clock_rate = 48000, .params = 0 },
            .{ .tag = .cadencevis, .clock_rate = 90000, .params = 0 },
        };
        const basis: media_room.CallProfile = switch (action) {
            .offer => try copyProfile(&supported_codecs, offered_fec),
            .answer => shared orelse return error.NoOffer,
        };
        const local: sdp.MediaDescription = .{ .band_id = 64, .kind = .audio, .codecs = basis.slice(), .fec = basis.fec, .direction = .sendrecv };
        const remote: sdp.MediaDescription = .{ .band_id = 64, .kind = .audio, .codecs = offered.slice(), .fec = offered.fec, .direction = .sendrecv };
        var negotiated = try media_session.negotiate(server.allocator, local, remote);
        defer negotiated.deinit(server.allocator);
        var result: PreparedMediaNegotiation = .{
            .server = server,
            .id = id,
            .conn = conn,
            .action = action,
            .channel_len = channel.len,
            .offered = offered,
            .agreed = try copyProfile(negotiated.codecs, negotiated.fec),
            .shared_before = shared,
            .expected_fp = expected_fp,
            .wants_webrtc = expected_fp != null or LinuxServer.isWebrtcTransport(extra_args),
            .ws = conn.ws,
            .tx_denied = conn.session.hasUmode(.media_tx_deny),
            .media_enabled = server.config.media_enabled,
            .dtls_enabled = server.config.media_dtls_srtp,
            .ws_relay = server.config.ws_media_relay,
            .fallback_host_len = host.len,
        };
        @memcpy(result.channel[0..channel.len], channel);
        @memcpy(result.fallback_host[0..host.len], host);
        return result;
    }

    fn channelSlice(self: *const PreparedMediaNegotiation) []const u8 {
        return self.channel[0..self.channel_len];
    }

    /// Pure current-source check in the final routing cut. This does not replace
    /// required leaf advertisement/negotiation, Profiles, Bridge or output joins.
    fn validate(self: *const PreparedMediaNegotiation) !void {
        try self.server.requireMediaCaller(self.id, self.conn, self.channelSlice());
        if (self.conn.ws != self.ws or
            self.conn.session.hasUmode(.media_tx_deny) != self.tx_denied or
            self.server.config.media_enabled != self.media_enabled or
            self.server.config.media_dtls_srtp != self.dtls_enabled or
            self.server.config.ws_media_relay != self.ws_relay or
            !std.mem.eql(u8, self.server.config.media_host, self.fallback_host[0..self.fallback_host_len]) or
            !sameOptionalProfile(self.shared_before, self.server.media_rooms.transportProfileOf(self.channelSlice()))) return error.BadState;
    }
};

/// Private ownership of the source-issued advertisement relation used to render
/// ONE command's final issuer bytes. Endpoint candidates and their parent offers
/// outlive this value and its final validation. It publishes no route or output.
/// Server retains only an opaque owned routing lifetime. A saved construction
/// pointer exposes neither a Domain nor release/join authority through this type.
const OwnedMediaRouting = opaque {};
const MediaRoutingBacking = struct {
    server: *LinuxServer,
    allocator: std.mem.Allocator,
    domain: *media_routing.Domain,
    native_binding: ?*media_routing.NativeBinding,
    webrtc_binding: ?*media_routing.WebrtcBinding,
    producer_fence: ?media_plane_mod.RoutingProducerFence = null,
    prepared_egress: ?*const anyopaque = null,
    queue_retired: bool = false,
};
fn mediaRoutingBacking(owner: *OwnedMediaRouting) *MediaRoutingBacking {
    return @ptrCast(@alignCast(owner));
}

/// Exclusive command ownership. Every source plan and final issuer allocation
/// is prepared before the one routing cut; no candidate can rebind after render.
/// Public codec negotiation may use plaintext signaling. This distinct plan
/// contains no endpoint credential and can never satisfy a secret output join.
const PreparedPublicMediaOutput = struct {
    protected: ?PreparedMediaOutput = null,
    plain: ?Plain = null,
    const Plain = struct {
        server: *LinuxServer,
        id: client_model.ClientId,
        conn: *ConnState,
        channel: []const u8,
        bytes: []u8,
        framed: ?ws_output.Prepared,
        queue: sendq.PreparedAppend(*ConnState),
        fd: linux.fd_t,
        token: RingFdToken,
        send_len: usize,
        send_offset: usize,
        overflow_len: usize,
        overflow_ptr: usize,
        overflow_capacity: usize,
        cap: usize,
        ws: ?*WsState,
        overflow_allocator: std.mem.Allocator,
        send_armed: bool,
        submitted_len: usize,
        submitted_offset: usize,
        done: bool = false,
    };

    fn prepare(server: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, bytes: []const u8) !PreparedPublicMediaOutput {
        if (conn.tls != null) return .{ .protected = try PreparedMediaOutput.prepare(server, id, conn, channel, bytes) };
        try server.requireMediaCaller(id, conn, channel);
        if (conn.fd < 0 or conn.tls_tx_offloaded or conn.tls_rx_offloaded or conn.tls_control_charge != 0 or conn.tls_deferred_charge != 0 or conn.tls_deferred_plain.items.len != 0) return error.BadState;
        const owned = try server.allocator.dupe(u8, bytes);
        errdefer server.allocator.free(owned);
        var framed: ?ws_output.Prepared = null;
        errdefer if (framed) |*frames| frames.deinit();
        if (conn.ws) |ws| {
            if (ws.phase != .open) return error.BadState;
            const backlog = sendq.backlog(conn);
            if (backlog > conn.sendq_cap) return error.OutputTooSmall;
            framed = try ws_output.prepareSensitive(WsState.max_frame, conn.overflow_allocator, ws.tx_buf[0..ws.tx_len], &.{owned}, ws.tx_buf.len, conn.sendq_cap - @as(usize, @intCast(backlog)));
            if (framed.?.tail().len != 0) return error.BadState;
        }
        const wire = if (framed) |*frames| frames.bytes() else owned;
        var queue = try sendq.prepareAppend(conn, wire.len);
        errdefer queue.abort();
        return .{ .plain = .{ .server = server, .id = id, .conn = conn, .channel = channel, .bytes = owned, .framed = framed, .queue = queue, .fd = conn.fd, .token = conn.token, .send_len = conn.send_len, .send_offset = conn.send_offset, .overflow_len = conn.send_overflow.items.len, .overflow_ptr = @intFromPtr(conn.send_overflow.items.ptr), .overflow_capacity = conn.send_overflow.capacity, .cap = conn.sendq_cap, .ws = conn.ws, .overflow_allocator = conn.overflow_allocator, .send_armed = conn.send_armed, .submitted_len = conn.send_submitted_len, .submitted_offset = conn.send_submitted_offset } };
    }

    fn validate(self: *const PreparedPublicMediaOutput) !void {
        if (self.protected) |*output| return output.validate();
        const plain = if (self.plain) |*owned| owned else return error.BadState;
        const conn = plain.conn;
        try plain.server.requireMediaCaller(plain.id, conn, plain.channel);
        if (plain.done or conn.fd != plain.fd or !std.meta.eql(conn.token, plain.token) or conn.tls != null or conn.tls_tx_offloaded or conn.tls_rx_offloaded or conn.tls_control_charge != 0 or conn.tls_deferred_charge != 0 or conn.tls_deferred_plain.items.len != 0 or conn.send_len != plain.send_len or conn.send_offset != plain.send_offset or conn.send_overflow.items.len != plain.overflow_len or @intFromPtr(conn.send_overflow.items.ptr) != plain.overflow_ptr or conn.send_overflow.capacity != plain.overflow_capacity or conn.sendq_cap != plain.cap or conn.ws != plain.ws or conn.overflow_allocator.ptr != plain.overflow_allocator.ptr or conn.overflow_allocator.vtable != plain.overflow_allocator.vtable or conn.send_armed != plain.send_armed or conn.send_submitted_len != plain.submitted_len or conn.send_submitted_offset != plain.submitted_offset) return error.BadState;
        if (plain.framed) |*frames| {
            const ws = conn.ws orelse return error.BadState;
            if (ws.phase != .open or ws.tx_len != frames.initial.len or !std.mem.eql(u8, ws.tx_buf[0..ws.tx_len], frames.initial)) return error.BadState;
        } else if (conn.ws != null) return error.BadState;
    }

    fn commit(self: *PreparedPublicMediaOutput) void {
        self.validate() catch unreachable;
        if (self.protected) |*output| return output.commit();
        const plain = &self.plain.?;
        plain.queue.commit(if (plain.framed) |*frames| frames.bytes() else plain.bytes);
        if (plain.framed) |*frames| frames.commitTail(plain.conn.ws.?);
        plain.done = true;
    }

    fn deinit(self: *PreparedPublicMediaOutput) void {
        if (self.protected) |*output| output.deinit();
        if (self.plain) |*plain| {
            if (!plain.done) plain.queue.abort();
            if (plain.framed) |*frames| frames.deinit();
            plain.server.allocator.free(plain.bytes);
        }
        self.* = undefined;
    }
};

const PreparedPublicMediaNegotiation = struct {
    turn: *MediaAuthorityTurn,
    domain: *media_routing.Domain,
    negotiation: PreparedMediaNegotiation,
    profile: ?*media_room.PreparedSharedProfile,
    output: PreparedPublicMediaOutput,
    done: bool = false,

    fn prepare(turn: *MediaAuthorityTurn, domain: *media_routing.Domain, negotiation: PreparedMediaNegotiation) !PreparedPublicMediaNegotiation {
        try turn.requireEmptyIssuer();
        if (negotiation.expected_fp != null) return error.DtlsUnavailable;
        const server = negotiation.server;
        const profile = if (negotiation.action == .offer) try server.media_rooms.prepareSharedProfile(negotiation.channelSlice(), negotiation.agreed) else null;
        errdefer if (profile) |plan| plan.deinit();
        var storage: [default_reply_bytes]u8 = undefined;
        var capture: ReplyCapture = .{ .buf = &storage };
        var line: [event_spine.max_event_line_len]u8 = undefined;
        var detail_buf: [256]u8 = undefined;
        const detail = LinuxServer.formatMediaCodecDetail(&detail_buf, negotiation.agreed.slice(), negotiation.agreed.fec) orelse return error.OutputTooSmall;
        capture.append(try server.renderMediaEventReply(negotiation.conn, if (negotiation.action == .offer) "OFFER-ACK" else "ANSWER-ACK", negotiation.channelSlice(), detail, &line));
        for ([_]media_room.MediaKind{ .voice, .video }) |kind| {
            if (!LinuxServer.codecSetHasKind(negotiation.offered.slice(), kind) or LinuxServer.codecSetHasKind(negotiation.agreed.slice(), kind)) continue;
            const denied = try std.fmt.bufPrint(&detail_buf, "kind={s} reason=no_common_codec", .{media_room.kindName(kind)});
            capture.append(try server.renderMediaEventReply(negotiation.conn, "KIND-DENIED", negotiation.channelSlice(), denied, &line));
        }
        const final_bytes = try prepareMediaIssuerBytes(server.allocator, &capture, turn.label());
        defer server.allocator.free(final_bytes);
        return .{ .turn = turn, .domain = domain, .negotiation = negotiation, .profile = profile, .output = try PreparedPublicMediaOutput.prepare(server, negotiation.id, negotiation.conn, negotiation.channelSlice(), final_bytes) };
    }

    fn publishLocked(scope: *media_routing.Locked, self: *PreparedPublicMediaNegotiation) !void {
        if (self.done) return error.BadState;
        const expected: MediaAuthorityTurn.Action = if (self.negotiation.action == .offer) .offer else .answer;
        if (try MediaAuthorityTurn.require(self.negotiation.server, self.negotiation.id, self.negotiation.conn, expected, self.negotiation.channelSlice()) != self.turn) return error.BadState;
        try self.turn.requireEmptyIssuer();
        try self.negotiation.validate();
        if (self.profile) |plan| try plan.validateLocked(self.domain, scope, self.negotiation.agreed);
        try self.output.validate();
        self.output.commit();
        if (self.profile) |plan| plan.commitLocked(self.domain, scope);
        self.done = true;
        self.turn.published = true;
    }

    fn deinit(self: *PreparedPublicMediaNegotiation) void {
        self.output.deinit();
        if (self.profile) |plan| plan.deinit();
        self.* = undefined;
    }
};

/// A non-browser JOIN publishes actual physical and logical membership without
/// deriving a MACKEY or creating a UDP offer. Labels are admitted before commit.
const PreparedLogicalMediaJoin = struct {
    turn: *MediaAuthorityTurn,
    domain: *media_routing.Domain,
    physical: PreparedMediaPhysicalJoin,
    membership: *media_routing.PreparedMembership,
    room: *media_room.PreparedJoin,
    output: ?PreparedPublicMediaOutput,
    recording: ?PreparedMediaBrowserJoin.RecordingBinding,
    consent: bool,
    stops_recording: bool,
    done: bool = false,
    fn prepare(turn: *MediaAuthorityTurn, domain: *media_routing.Domain, kind: media_room.MediaKind) !?PreparedLogicalMediaJoin {
        try turn.requireEmptyIssuer();
        var physical = try PreparedMediaPhysicalJoin.prepare(turn.server, turn.id, turn.conn, turn.channel, kind);
        errdefer physical.deinit();
        if (physical.browser) return error.BadState;
        if (!physical.changed) {
            physical.deinit();
            return null;
        }
        const membership = try domain.prepareMembership(turn.channel, turn.id, mediaKindBit(kind));
        errdefer membership.deinit();
        const room = try turn.server.media_rooms.prepareJoin(membership.preview(), turn.channel, turn.conn.session.displayName(), kind);
        errdefer room.deinit();
        const recording = PreparedMediaBrowserJoin.RecordingBinding.capture(turn.server, turn.channel);
        const consent = turn.server.media_rooms.hasConsent(turn.channel, turn.conn.session.displayName());
        const stops_recording = physical.first_kind and recording != null and recording.?.active and !consent;
        var output: ?PreparedPublicMediaOutput = null;
        errdefer if (output) |*plan| plan.deinit();
        if (stops_recording or turn.label() != null) {
            var storage: [default_reply_bytes]u8 = undefined;
            var capture: ReplyCapture = .{ .buf = &storage };
            var line: [event_spine.max_event_line_len]u8 = undefined;
            if (stops_recording) capture.append(try turn.server.renderMediaEventReply(turn.conn, "RECORD", turn.channel, "stopped", &line));
            const bytes = try prepareMediaIssuerBytes(turn.server.allocator, &capture, turn.label());
            defer turn.server.allocator.free(bytes);
            output = try PreparedPublicMediaOutput.prepare(turn.server, turn.id, turn.conn, turn.channel, bytes);
        }
        return .{ .turn = turn, .domain = domain, .physical = physical, .membership = membership, .room = room, .output = output, .recording = recording, .consent = consent, .stops_recording = stops_recording };
    }
    fn publishLocked(scope: *media_routing.Locked, self: *PreparedLogicalMediaJoin) !void {
        if (self.done or try MediaAuthorityTurn.require(self.turn.server, self.turn.id, self.turn.conn, .join, self.turn.channel) != self.turn) return error.BadState;
        try self.turn.requireEmptyIssuer();
        try self.physical.validate();
        try self.membership.validateLocked(self.domain, scope);
        try self.room.validateLocked(self.domain, scope, self.membership);
        if (!std.meta.eql(self.recording, PreparedMediaBrowserJoin.RecordingBinding.capture(self.turn.server, self.turn.channel)) or self.consent != self.turn.server.media_rooms.hasConsent(self.turn.channel, self.turn.conn.session.displayName())) return error.BadState;
        if (self.output) |*plan| try plan.validate();
        if (self.output) |*plan| plan.commit();
        self.physical.commit();
        self.room.commitLocked(self.domain, scope);
        self.membership.commitLocked(self.domain, scope);
        if (self.stops_recording) {
            const stopped = self.turn.server.media_rooms.stopRecording(self.turn.channel);
            std.debug.assert(stopped);
        }
        self.done = true;
        self.turn.published = true;
    }
    fn deinit(self: *PreparedLogicalMediaJoin) void {
        if (self.output) |*plan| plan.deinit();
        self.room.deinit();
        self.membership.deinit();
        self.physical.deinit();
        self.* = undefined;
    }
};

const PreparedMediaOfferCommand = struct {
    turn: *MediaAuthorityTurn,
    domain: *media_routing.Domain,
    negotiation: PreparedMediaNegotiation,
    offers: *media_routing.PreparedOffers,
    native: ?*native_media_mod.PreparedNativeOffer,
    webrtc: ?*media_plane_mod.PreparedWebrtcOffer,
    profiles: *media_room.PreparedProfiles,
    bridge: *media_routing.PreparedPhysicalBridge,
    advertisements: PreparedMediaAdvertisements,
    output: PreparedMediaOutput,
    done: bool = false,

    fn acceptedKinds(profile: media_room.CallProfile) !u8 {
        return media_room.agreedKindBits(profile) catch return error.NoCommonCodec;
    }

    fn prepare(turn: *MediaAuthorityTurn, domain: *media_routing.Domain, negotiation: PreparedMediaNegotiation) !PreparedMediaOfferCommand {
        try turn.requireEmptyIssuer();
        const server = negotiation.server;
        const is_ws = negotiation.ws != null;
        var legs: [2]media_routing.OfferLeg = undefined;
        var count: usize = 0;
        if (!is_ws and server.native_media.port != 0) {
            legs[count] = .{ .leg = .native, .mode = .legacy_group };
            count += 1;
        }
        if (server.media_plane.port != 0 and (!is_ws or negotiation.wants_webrtc)) {
            legs[count] = .{ .leg = .webrtc, .mode = if (negotiation.expected_fp != null) .dtls_required else .legacy_group };
            count += 1;
        }
        if (count == 0) return error.NoTransportSelected;
        _ = try PreparedMediaOutput.requireCaller(negotiation.server, negotiation.id, negotiation.conn, negotiation.channelSlice());

        if (negotiation.expected_fp != null and legs[count - 1].leg != .webrtc) return error.DtlsUnavailable;
        const offers = try domain.prepareOffers(negotiation.channelSlice(), negotiation.id, legs[0..count]);
        errdefer offers.deinit();
        const kinds = try acceptedKinds(negotiation.agreed);
        var native: ?*native_media_mod.PreparedNativeOffer = null;
        errdefer if (native) |plan| plan.deinit();
        var webrtc: ?*media_plane_mod.PreparedWebrtcOffer = null;
        errdefer if (webrtc) |plan| plan.deinit();
        for (legs[0..count]) |leg| switch (leg.leg) {
            .native => native = try server.native_media.prepareOffer(domain, offers, negotiation.channelSlice(), negotiation.conn.session.displayName(), negotiation.agreed, kinds),
            .webrtc => webrtc = try server.media_plane.prepareOffer(domain, offers, negotiation.channelSlice(), negotiation.agreed, kinds, negotiation.expected_fp),
        };
        const preview = offers.preview();
        var keys: [2]media_room.PhysicalProfileKey = undefined;
        for (preview.endpoints[0..preview.count], 0..) |endpoint, n| keys[n] = .{
            .call = preview.call,
            .client = negotiation.id,
            .leg = endpoint.reference.endpoint.leg,
        };
        const profiles = try server.media_rooms.prepareTransportProfiles(keys[0..preview.count], negotiation.channelSlice(), negotiation.conn.session.displayName(), if (negotiation.action == .offer) negotiation.agreed else null, negotiation.offered);
        errdefer profiles.deinit();
        const bridge = try domain.preparePhysicalBridge(offers, negotiation.channelSlice(), native, webrtc);
        errdefer bridge.deinit();
        var advertisements = try PreparedMediaAdvertisements.prepare(&negotiation, domain, offers, native, webrtc, kinds);
        errdefer advertisements.deinit();
        var output = try prepareMediaTransportIssuerOutput(&advertisements, turn.label());
        errdefer output.deinit();
        return .{ .turn = turn, .domain = domain, .negotiation = negotiation, .offers = offers, .native = native, .webrtc = webrtc, .profiles = profiles, .bridge = bridge, .advertisements = advertisements, .output = output };
    }

    fn publishLocked(scope: *media_routing.Locked, self: *PreparedMediaOfferCommand) !void {
        if (self.done) return error.BadState;
        const action: MediaAuthorityTurn.Action = if (self.negotiation.action == .offer) .offer else .answer;
        if (try MediaAuthorityTurn.require(self.negotiation.server, self.negotiation.id, self.negotiation.conn, action, self.negotiation.channelSlice()) != self.turn) return error.BadState;
        try self.turn.requireEmptyIssuer();
        try self.negotiation.validate();
        try self.offers.validateLocked(self.domain, scope);
        if (self.native) |plan| try plan.validateLocked(self.domain, scope, self.offers);
        if (self.webrtc) |plan| try plan.validateLocked(self.domain, scope, self.offers);
        try self.profiles.validateLocked(self.domain, scope, self.offers);
        try self.bridge.validateLocked(self.domain, scope, self.offers, self.native, self.webrtc);
        try self.advertisements.validateLocked(scope);
        try self.output.validate();
        // No allocator callback, backend syscall, SEND or external notification
        // can intervene between accepted output and exact authority publication.
        self.output.commit();
        if (self.native) |plan| plan.commitLocked(self.domain, scope);
        if (self.webrtc) |plan| plan.commitLocked(self.domain, scope);
        self.profiles.commitLocked(self.domain, scope);
        self.bridge.commitLocked(self.domain, scope);
        self.offers.commitLocked(self.domain, scope);
        self.done = true;
        self.turn.published = true;
    }

    fn deinit(self: *PreparedMediaOfferCommand) void {
        self.output.deinit();
        self.advertisements.deinit();
        self.bridge.deinit();
        self.profiles.deinit();
        if (self.webrtc) |plan| plan.deinit();
        if (self.native) |plan| plan.deinit();
        self.offers.deinit();
        self.* = undefined;
    }
};

const PreparedMediaAdvertisements = struct {
    negotiation: PreparedMediaNegotiation,
    domain: *media_routing.Domain,
    offers: *media_routing.PreparedOffers,
    native: ?*native_media_mod.PreparedNativeOffer,
    webrtc: ?*media_plane_mod.PreparedWebrtcOffer,
    native_ad: ?native_media_mod.NativeAdvertisement,
    webrtc_ad: ?media_plane_mod.WebrtcAdvertisement,
    native_host: ?*media_plane_mod.PreparedAdvertisementHost,
    native_host_ad: ?media_plane_mod.HostAdvertisement,
    accepted_kind_bits: u8,

    fn requirePreview(negotiation: *const PreparedMediaNegotiation, offers: *media_routing.PreparedOffers, native: ?*native_media_mod.PreparedNativeOffer, webrtc: ?*media_plane_mod.PreparedWebrtcOffer) !void {
        try negotiation.validate();
        const preview = offers.preview();
        if (preview.count == 0 or preview.count > preview.endpoints.len) return error.BadState;
        var expected_native: ?media_routing.EndpointObservation = null;
        var expected_webrtc: ?media_routing.EndpointObservation = null;
        for (preview.endpoints[0..preview.count]) |endpoint| {
            if (!endpoint.reference.offering_client.eql(negotiation.id) or
                !std.meta.eql(endpoint.reference.endpoint.call, preview.call)) return error.BadState;
            switch (endpoint.reference.endpoint.leg) {
                .native => {
                    if (expected_native != null or negotiation.ws != null) return error.BadState;
                    expected_native = endpoint;
                },
                .webrtc => {
                    if (expected_webrtc != null or
                        (negotiation.ws != null and !negotiation.wants_webrtc)) return error.BadState;
                    const expected_mode: media_routing.SecurityMode = if (negotiation.expected_fp != null) .dtls_required else .legacy_group;
                    if (endpoint.mode != expected_mode) return error.BadState;
                    expected_webrtc = endpoint;
                },
            }
        }
        if ((native == null) != (expected_native == null) or
            (webrtc == null) != (expected_webrtc == null) or
            (negotiation.expected_fp != null and webrtc == null)) return error.BadState;
        if (native) |candidate| if (!std.meta.eql(candidate.preview().identity, expected_native.?)) return error.BadState;
        if (webrtc) |candidate| if (!std.meta.eql(candidate.preview().identity, expected_webrtc.?)) return error.BadState;
    }

    /// The enclosing private command candidate builder supplies accepted kinds
    /// from its actual source policy. This mask is only the relation checked
    /// against genuine leaf plans; it is not an independent admission proof.
    fn prepare(negotiation: *const PreparedMediaNegotiation, domain: *media_routing.Domain, offers: *media_routing.PreparedOffers, native: ?*native_media_mod.PreparedNativeOffer, webrtc: ?*media_plane_mod.PreparedWebrtcOffer, accepted_kind_bits: u8) !PreparedMediaAdvertisements {
        try requirePreview(negotiation, offers, native, webrtc);
        _ = try PreparedMediaOutput.requireCaller(negotiation.server, negotiation.id, negotiation.conn, negotiation.channelSlice());
        if (accepted_kind_bits == 0 or accepted_kind_bits & ~@as(u8, 7) != 0) return error.BadState;
        var native_ad: ?native_media_mod.NativeAdvertisement = null;
        if (native) |candidate| {
            try candidate.captureAdvertisement();
            native_ad = try candidate.advertisement();
        }
        var webrtc_ad: ?media_plane_mod.WebrtcAdvertisement = null;
        var host: ?*media_plane_mod.PreparedAdvertisementHost = null;
        errdefer if (host) |candidate| candidate.deinit();
        const fallback = negotiation.fallback_host[0..negotiation.fallback_host_len];
        if (webrtc) |candidate| {
            try candidate.captureAdvertisement(fallback);
            webrtc_ad = try candidate.advertisement();
        } else {
            // The Server owns this real final-address inline Plane even when no
            // RTC leg/socket/credentials were selected. Its issued binding and
            // pending pin supply host lifetime; a scalar fallback never does.
            host = try negotiation.server.media_plane.prepareAdvertisementHost(domain, offers, negotiation.channelSlice(), fallback);
        }
        const result: PreparedMediaAdvertisements = .{
            .negotiation = negotiation.*,
            .domain = domain,
            .offers = offers,
            .native = native,
            .webrtc = webrtc,
            .native_ad = native_ad,
            .webrtc_ad = webrtc_ad,
            .native_host = host,
            .native_host_ad = if (host) |candidate| candidate.preview() else null,
            .accepted_kind_bits = accepted_kind_bits,
        };
        if (result.negotiation.ws != null and LinuxServer.mediaHostIsLoopback(result.hostSlice())) return error.BrowserTransportUnroutable;
        return result;
    }

    fn hostSlice(self: *const PreparedMediaAdvertisements) []const u8 {
        if (self.webrtc_ad) |*advertisement| return advertisement.hostSlice();
        if (self.native_host_ad) |*advertisement| return advertisement.hostSlice();
        unreachable;
    }

    /// EVERY related leaf/Room/Bridge/output validator must finish before the
    /// enclosing authority turn's first no-fail publication. No getter syscall,
    /// preparation, cleanup, SEND or backend callback occurs in this function.
    fn validateLocked(self: *const PreparedMediaAdvertisements, scope: *const media_routing.Locked) !void {
        try requirePreview(&self.negotiation, self.offers, self.native, self.webrtc);
        try self.offers.validateLocked(self.domain, scope);
        if (self.native) |candidate| {
            try candidate.requireAdvertisementLocked(self.domain, scope, self.offers);
            try candidate.requireNegotiationLocked(self.domain, scope, self.offers, self.negotiation.agreed, self.accepted_kind_bits);
        }
        if (self.webrtc) |candidate| {
            try candidate.requireAdvertisementLocked(self.domain, scope, self.offers);
            try candidate.requireNegotiationLocked(self.domain, scope, self.offers, self.negotiation.agreed, self.accepted_kind_bits, self.negotiation.expected_fp);
        } else {
            try self.native_host.?.validateLocked(self.domain, scope, self.offers, self.negotiation.fallback_host[0..self.negotiation.fallback_host_len]);
        }
    }

    /// Outside Domain while the actual parent offers, leaf owner, config and
    /// original physical connection lifetimes are retained. Other plans remain
    /// exclusively owned by the enclosing command transaction.
    fn deinit(self: *PreparedMediaAdvertisements) void {
        if (self.native_host) |candidate| candidate.deinit();
        self.* = undefined;
    }
};

/// Final issuer bytes use the same private command negotiation plus owned
/// source-issued advertisement copies. A copy is a rendering value only. The
/// outer command must validate these original source plans and EVERY related
/// Room/Bridge/output participant before one no-fail joined publication.
fn prepareMediaTransportIssuerOutput(advertisements: *const PreparedMediaAdvertisements, label: ?[]const u8) !PreparedMediaOutput {
    const negotiation = &advertisements.negotiation;
    try PreparedMediaAdvertisements.requirePreview(negotiation, advertisements.offers, advertisements.native, advertisements.webrtc);
    const server = negotiation.server;
    const id = negotiation.id;
    const conn = negotiation.conn;
    const channel = negotiation.channelSlice();
    _ = try PreparedMediaOutput.requireCaller(server, id, conn, channel);
    const native = advertisements.native;
    const webrtc = advertisements.webrtc;
    const action = negotiation.action;
    const offered = negotiation.offered.slice();
    const negotiated = negotiation.agreed.slice();
    const fec = negotiation.agreed.fec;
    var storage: [default_reply_bytes]u8 = undefined;
    defer std.crypto.secureZero(u8, &storage);
    var capture: ReplyCapture = .{ .buf = &storage };
    var line: [event_spine.max_event_line_len]u8 = undefined;
    defer std.crypto.secureZero(u8, &line);
    var detail_buf: [512]u8 = undefined;
    defer std.crypto.secureZero(u8, &detail_buf);
    const detail = LinuxServer.formatMediaCodecDetail(&detail_buf, negotiated, fec) orelse return error.OutputTooSmall;
    capture.append(try server.renderMediaEventReply(conn, switch (action) {
        .offer => "OFFER-ACK",
        .answer => "ANSWER-ACK",
    }, channel, detail, &line));
    for ([_]media_room.MediaKind{ .voice, .video }) |kind| {
        if (!LinuxServer.codecSetHasKind(offered, kind) or LinuxServer.codecSetHasKind(negotiated, kind)) continue;
        const denied = try std.fmt.bufPrint(&detail_buf, "kind={s} reason=no_common_codec", .{media_room.kindName(kind)});
        capture.append(try server.renderMediaEventReply(conn, "KIND-DENIED", channel, denied, &line));
    }
    const host = advertisements.hostSlice();
    if (webrtc) |candidate| {
        const credentials = candidate.preview();
        if (conn.ws != null and LinuxServer.mediaHostIsLoopback(host)) return error.BadState;
        const transport = if (credentials.identity.mode == .dtls_required) blk: {
            if (credentials.group_key != null) return error.BadState;
            const fp = advertisements.webrtc_ad.?.fingerprintSlice();
            if (fp.len == 0) return error.BadState;
            break :blk try std.fmt.bufPrint(&detail_buf, "ufrag={s} pwd={s} candidate={s}:{d} fingerprint={s} setup=passive", .{
                credentials.ufrag, credentials.pwd, host, advertisements.webrtc_ad.?.port, fp,
            });
        } else blk: {
            const key = credentials.group_key orelse return error.BadState;
            var encoded_key: [std.base64.standard.Encoder.calcSize(@sizeOf(@TypeOf(key.*)))]u8 = undefined;
            defer std.crypto.secureZero(u8, &encoded_key);
            const encoded = std.base64.standard.Encoder.encode(&encoded_key, key);
            break :blk try std.fmt.bufPrint(&detail_buf, "ufrag={s} pwd={s} candidate={s}:{d} srtp={s}", .{
                credentials.ufrag, credentials.pwd, host, advertisements.webrtc_ad.?.port, encoded,
            });
        };
        capture.append(try server.renderMediaEventReply(conn, "TRANSPORT", channel, transport, &line));
    }
    if (native) |candidate| {
        const credentials = candidate.preview();
        const description = try std.fmt.bufPrint(&detail_buf, "candidate={s}:{d} stream={d} codec=CadenceVox/CadenceVis mac=hmac-sha256-128", .{
            host, advertisements.native_ad.?.port, credentials.identity.stream_id,
        });
        capture.append(try server.renderMediaEventReply(conn, "NATIVE", channel, description, &line));
        var encoded_key: [std.base64.standard.Encoder.calcSize(@sizeOf(@TypeOf(credentials.master.*)))]u8 = undefined;
        defer std.crypto.secureZero(u8, &encoded_key);
        const encoded = std.base64.standard.Encoder.encode(&encoded_key, credentials.master);
        const secret = try std.fmt.bufPrint(&detail_buf, "stream={d} key={s}", .{ credentials.identity.stream_id, encoded });
        capture.append(try server.renderMediaEventReply(conn, "NATIVE-MACKEY", channel, secret, &line));
    }
    // Overflow, labels/BATCH, WS framing, TLS epochs, control credit and complete
    // queue admission all fail before any endpoint/profile publication. Every
    // temporary secret buffer is wiped on ordinary and allocation-failure exit.
    const final_bytes = try prepareMediaIssuerBytes(server.allocator, &capture, label);
    defer {
        std.crypto.secureZero(u8, final_bytes);
        server.allocator.free(final_bytes);
    }
    return PreparedMediaOutput.prepare(server, id, conn, channel, final_bytes);
}

/// Server-owned half of browser JOIN. Domain/Room source plans still validate
/// their own authority; this private plan stages the existing physical/E2EE and
/// WS-call fields without publishing them during reply/capacity preparation.
const PreparedMediaPhysicalJoin = struct {
    server: *LinuxServer,
    id: client_model.ClientId,
    conn: *ConnState,
    requested: MediaPhysicalAttachment,
    kind: media_room.MediaKind,
    old_index: ?usize,
    old_kind_bits: u8,
    old_len: usize,
    old_capacity: usize,
    old_ptr: usize,
    first_kind: bool,
    changed: bool,
    browser: bool,
    binding: Binding,
    replacement: ?std.ArrayList(MediaPhysicalAttachment) = null,
    done: bool = false,

    const Binding = struct {
        channel: [media_call_chan_max]u8 = @splat(0),
        channel_len: usize,
        participant: [media_call_part_max]u8 = @splat(0),
        participant_len: usize,
        attachment: [LinuxServer.media_e2ee_attachment_bytes]u8,
        attachment_bound: bool,
        ws: ?*WsState,

        fn capture(conn: *const ConnState) Binding {
            var result: Binding = .{
                .channel_len = conn.media_call_channel_len,
                .participant_len = conn.media_call_participant_len,
                .attachment = conn.media_e2ee_attachment,
                .attachment_bound = conn.media_e2ee_attachment_bound,
                .ws = conn.ws,
            };
            @memcpy(result.channel[0..result.channel_len], conn.media_call_channel[0..result.channel_len]);
            @memcpy(result.participant[0..result.participant_len], conn.media_call_participant[0..result.participant_len]);
            return result;
        }
    };

    fn arrayPtr(attachments: *const std.ArrayList(MediaPhysicalAttachment)) usize {
        return if (attachments.capacity == 0) 0 else @intFromPtr(attachments.items.ptr);
    }

    fn prepare(server: *LinuxServer, id: client_model.ClientId, conn: *ConnState, channel: []const u8, kind: media_room.MediaKind) !PreparedMediaPhysicalJoin {
        try server.requireMediaCaller(id, conn, channel);
        const nick = conn.session.displayName();
        const requested = MediaPhysicalAttachment.init(id, channel, nick, kind) orelse return error.NameTooLong;
        const index = server.mediaPhysicalIndex(id, channel, nick);
        const old_bits = if (index) |idx| server.media_physical_attachments.items[idx].kind_bits else 0;
        const changed = (old_bits & mediaKindBit(kind)) == 0;
        const browser = server.config.ws_media_relay and conn.ws != null;
        if (browser and (channel.len > conn.media_call_channel.len or nick.len > conn.media_call_participant.len)) return error.NameTooLong;
        var plan: PreparedMediaPhysicalJoin = .{
            .server = server,
            .id = id,
            .conn = conn,
            .requested = requested,
            .kind = kind,
            .old_index = index,
            .old_kind_bits = old_bits,
            .old_len = server.media_physical_attachments.items.len,
            .old_capacity = server.media_physical_attachments.capacity,
            .old_ptr = arrayPtr(&server.media_physical_attachments),
            .first_kind = !server.mediaPhysicalKindPresent(channel, nick, kind),
            .changed = changed,
            .browser = browser,
            .binding = Binding.capture(conn),
        };
        if (changed and index == null and plan.old_len == plan.old_capacity) {
            const required = std.math.add(usize, plan.old_len, 1) catch return error.OutOfMemory;
            var detached: std.ArrayList(MediaPhysicalAttachment) = .empty;
            errdefer detached.deinit(server.allocator);
            try detached.ensureTotalCapacity(server.allocator, required);
            plan.replacement = detached;
        }
        return plan;
    }

    /// World and original connection ownership are retained through this cut.
    /// No byte comparison touches undefined padding in the inline name buffers.
    fn validate(self: *const PreparedMediaPhysicalJoin) !void {
        if (self.done) return error.BadState;
        const channel = self.requested.channelSlice();
        const nick = self.requested.nickSlice();
        try self.server.requireMediaCaller(self.id, self.conn, channel);
        if (!std.mem.eql(u8, nick, self.conn.session.displayName()) or
            self.server.media_physical_attachments.items.len != self.old_len or
            self.server.media_physical_attachments.capacity != self.old_capacity or
            arrayPtr(&self.server.media_physical_attachments) != self.old_ptr or
            self.server.mediaPhysicalIndex(self.id, channel, nick) != self.old_index or
            self.browser != (self.server.config.ws_media_relay and self.conn.ws != null) or
            !std.meta.eql(self.binding, Binding.capture(self.conn)) or
            self.first_kind == self.server.mediaPhysicalKindPresent(channel, nick, self.kind)) return error.BadState;
        if (self.old_index) |idx| {
            if (self.server.media_physical_attachments.items[idx].kind_bits != self.old_kind_bits) return error.BadState;
        }
    }

    /// Pure publication alongside actual Domain/Room/output commits. Retired
    /// physical backing stays owned here until the caller leaves Domain.
    fn commit(self: *PreparedMediaPhysicalJoin) void {
        self.validate() catch unreachable;
        if (self.changed) {
            if (self.replacement) |*detached| {
                detached.appendSliceAssumeCapacity(self.server.media_physical_attachments.items);
                std.mem.swap(std.ArrayList(MediaPhysicalAttachment), &self.server.media_physical_attachments, detached);
            }
            if (self.old_index) |idx| self.server.media_physical_attachments.items[idx].kind_bits |= mediaKindBit(self.kind) else self.server.media_physical_attachments.appendAssumeCapacity(self.requested);
            if (self.server.media_physical_attachments.items.len == 1 or self.first_kind) self.conn.clearMediaE2eeAttachment();
            if (self.browser) self.conn.setMediaCall(self.requested.channelSlice(), self.requested.nickSlice());
        }
        self.done = true;
    }

    fn deinit(self: *PreparedMediaPhysicalJoin) void {
        if (self.replacement) |*retired| retired.deinit(self.server.allocator);
        self.* = undefined;
    }
};

/// Server-owned physical membership retirement for ONE complete ClientId cut.
/// The command/close owner retains World and the original slab row throughout.
/// This candidate alone cannot revoke transport, Bridge or pending FIFO work.
/// Every genuine Domain/leaf/Room/Bridge plan must validate before this commit.
const PreparedMediaPhysicalClientDeparture = struct {
    server: *LinuxServer,
    id: client_model.ClientId,
    conn: *ConnState,
    allocator: std.mem.Allocator,
    old_ptr: usize,
    old_capacity: usize,
    old_rows: []MediaPhysicalAttachment,
    remaining: std.ArrayList(MediaPhysicalAttachment) = .empty,
    removed: usize,
    binding: PreparedMediaPhysicalJoin.Binding,
    nick: [client_model.MAX_NICK_BYTES]u8 = @splat(0),
    nick_len: usize,
    done: bool = false,

    fn sameRow(a: *const MediaPhysicalAttachment, b: *const MediaPhysicalAttachment) bool {
        // Inline names have undefined unused tails. Compare logical initialized
        // fields only; hashing/comparing struct padding is not a revision proof.
        return a.client.eql(b.client) and a.kind_bits == b.kind_bits and
            std.mem.eql(u8, a.channelSlice(), b.channelSlice()) and
            std.mem.eql(u8, a.nickSlice(), b.nickSlice());
    }

    fn requireOwner(server: *LinuxServer, id: client_model.ClientId, conn: *ConnState) !void {
        // Closing is legal here: retirement precedes slab/World removal. An
        // active signalling requirement would strand a just-closed owner.
        if (id.isNone() or id.shard != server.rx().shard_id or
            server.connFor(id) != conn or !conn.session.registered()) return error.BadState;
    }

    fn prepare(server: *LinuxServer, id: client_model.ClientId, conn: *ConnState) !PreparedMediaPhysicalClientDeparture {
        try requireOwner(server, id, conn);
        const allocator = server.allocator;
        const rows = server.media_physical_attachments.items;
        var removed: usize = 0;
        for (rows) |row| if (row.client.eql(id)) {
            removed += 1;
        };
        var result: PreparedMediaPhysicalClientDeparture = .{
            .server = server,
            .id = id,
            .conn = conn,
            .allocator = allocator,
            .old_ptr = PreparedMediaPhysicalJoin.arrayPtr(&server.media_physical_attachments),
            .old_capacity = server.media_physical_attachments.capacity,
            .old_rows = try allocator.dupe(MediaPhysicalAttachment, rows),
            .removed = removed,
            .binding = PreparedMediaPhysicalJoin.Binding.capture(conn),
            .nick_len = conn.session.displayName().len,
        };
        errdefer allocator.free(result.old_rows);
        @memcpy(result.nick[0..result.nick_len], conn.session.displayName());
        if (removed != 0) {
            try result.remaining.ensureTotalCapacity(allocator, rows.len - removed);
            errdefer result.remaining.deinit(allocator);
            for (rows) |row| if (!row.client.eql(id)) {
                result.remaining.appendAssumeCapacity(row);
            };
        }
        return result;
    }

    fn validate(self: *const PreparedMediaPhysicalClientDeparture) !void {
        if (self.done) return error.BadState;
        try requireOwner(self.server, self.id, self.conn);
        const source = &self.server.media_physical_attachments;
        if (!std.meta.eql(self.allocator, self.server.allocator) or
            PreparedMediaPhysicalJoin.arrayPtr(source) != self.old_ptr or
            source.capacity != self.old_capacity or source.items.len != self.old_rows.len or
            !std.meta.eql(self.binding, PreparedMediaPhysicalJoin.Binding.capture(self.conn)) or
            !std.mem.eql(u8, self.nick[0..self.nick_len], self.conn.session.displayName())) return error.BadState;
        for (source.items, self.old_rows) |*current, *old| {
            if (!sameRow(current, old)) return error.BadState;
        }
    }

    fn hasPart(actual: *media_routing.PreparedClientDeparture, channel: []const u8) bool {
        for (0..actual.count()) |n| {
            if (std.ascii.eqlIgnoreCase(actual.part(n).channel(), channel)) return true;
        }
        return false;
    }

    fn validateLocked(self: *const PreparedMediaPhysicalClientDeparture, domain: *media_routing.Domain, scope: *media_routing.Locked, actual: *media_routing.PreparedClientDeparture) !void {
        try self.validate();
        try actual.validateLocked(domain, scope);
        for (0..actual.count()) |n| {
            const part = actual.part(n);
            try actual.requirePartLocked(domain, scope, n, part);
            if (!part.ownerKey(.native).client.eql(self.id) or
                !part.ownerKey(.webrtc).client.eql(self.id)) return error.BadState;
        }
        // Server rows missing from the actual Domain census are an explicit
        // join failure. Never remove them using nick or a caller remaining bit.
        for (self.old_rows) |*row| {
            if (row.client.eql(self.id) and !hasPart(actual, row.channelSlice())) return error.BadState;
        }
        if (self.binding.channel_len != 0 and
            !hasPart(actual, self.binding.channel[0..self.binding.channel_len])) return error.BadState;
    }

    /// Pure after ALL participants validate. Detached OLD storage stays owned
    /// by this plan until deinit OUTSIDE routing exclusion.
    fn commit(self: *PreparedMediaPhysicalClientDeparture) void {
        self.validate() catch unreachable;
        if (self.removed != 0)
            std.mem.swap(std.ArrayList(MediaPhysicalAttachment), &self.server.media_physical_attachments, &self.remaining);
        self.conn.clearMediaCall();
        self.done = true;
    }

    fn deinit(self: *PreparedMediaPhysicalClientDeparture) void {
        self.remaining.deinit(self.allocator);
        self.allocator.free(self.old_rows);
        std.crypto.secureZero(u8, &self.binding.attachment);
        self.* = undefined;
    }
};

/// Browser JOIN joins actual Domain and Room candidates, Server physical/E2EE
/// binding, and final protected issuer bytes. The original World/connection turn
/// and every allocator outlive cleanup; this plan grants no Domain lifetime.
const PreparedMediaBrowserJoin = struct {
    server: *LinuxServer,
    domain: *media_routing.Domain,
    physical: PreparedMediaPhysicalJoin,
    membership: *media_routing.PreparedMembership,
    room: *media_room.PreparedJoin,
    output: PreparedMediaOutput,
    recording: ?RecordingBinding,
    consent: bool,
    stops_recording: bool,
    done: bool = false,

    const RecordingBinding = struct {
        active: bool,
        by: [64]u8 = @splat(0),
        by_len: usize,
        fn capture(server: *LinuxServer, channel: []const u8) ?RecordingBinding {
            const note = server.media_rooms.recordingOf(channel) orelse return null;
            var result: RecordingBinding = .{ .active = note.active, .by_len = note.by_len };
            @memcpy(result.by[0..note.by_len], note.by());
            return result;
        }
    };

    fn prepare(server: *LinuxServer, domain: *media_routing.Domain, id: client_model.ClientId, conn: *ConnState, channel: []const u8, kind: media_room.MediaKind, label: ?[]const u8) !?PreparedMediaBrowserJoin {
        // A WS label, TLS flag or authenticated IRC nick cannot grant capability
        // delivery. Refuse before preparing membership or deriving its key.
        _ = try PreparedMediaOutput.requireCaller(server, id, conn, channel);
        var physical = try PreparedMediaPhysicalJoin.prepare(server, id, conn, channel, kind);
        errdefer physical.deinit();
        if (!physical.browser) return error.BadState;
        if (!physical.changed) {
            physical.deinit();
            return null;
        }
        const membership = try domain.prepareMembership(channel, id, mediaKindBit(kind));
        errdefer membership.deinit();
        const room = try server.media_rooms.prepareJoin(membership.preview(), channel, conn.session.displayName(), kind);
        errdefer room.deinit();
        const recording = RecordingBinding.capture(server, channel);
        const consent = server.media_rooms.hasConsent(channel, conn.session.displayName());
        const stops_recording = physical.first_kind and recording != null and recording.?.active and !consent;
        var storage: [default_reply_bytes]u8 = undefined;
        defer std.crypto.secureZero(u8, &storage);
        var capture: ReplyCapture = .{ .buf = &storage };
        var line_buf: [event_spine.max_event_line_len]u8 = undefined;
        defer std.crypto.secureZero(u8, &line_buf);
        if (stops_recording) capture.append(try server.renderMediaEventReply(conn, "RECORD", channel, "stopped", &line_buf));
        var key: [cadence_frame.MAC_KEY_BYTES]u8 = undefined;
        defer std.crypto.secureZero(u8, &key);
        cadence_frame.deriveNativeMediaMacKey(&server.native_stream_key, channel, conn.session.displayName(), &key);
        var b64: [std.base64.standard.Encoder.calcSize(cadence_frame.MAC_KEY_BYTES)]u8 = undefined;
        defer std.crypto.secureZero(u8, &b64);
        const encoded = std.base64.standard.Encoder.encode(&b64, &key);
        capture.append(try server.renderMediaEventReply(conn, "MACKEY", channel, encoded, &line_buf));
        const final_bytes = try prepareMediaIssuerBytes(server.allocator, &capture, label);
        defer {
            std.crypto.secureZero(u8, final_bytes);
            server.allocator.free(final_bytes);
        }
        const output = try PreparedMediaOutput.prepare(server, id, conn, channel, final_bytes);
        return .{ .server = server, .domain = domain, .physical = physical, .membership = membership, .room = room, .output = output, .recording = recording, .consent = consent, .stops_recording = stops_recording };
    }

    fn validateLocked(self: *PreparedMediaBrowserJoin, scope: *media_routing.Locked) !void {
        if (self.done) return error.BadState;
        try self.membership.validateLocked(self.domain, scope);
        try self.room.validateLocked(self.domain, scope, self.membership);
        try self.physical.validate();
        try self.output.validate();
        const channel = self.physical.requested.channelSlice();
        if (!std.meta.eql(self.recording, RecordingBinding.capture(self.server, channel)) or
            self.consent != self.server.media_rooms.hasConsent(channel, self.physical.requested.nickSlice())) return error.BadState;
    }

    /// All validation precedes the first publication. No destructor, allocator,
    /// entropy, getter, SEND arming or external notification occurs inside cut.
    fn publishLocked(scope: *media_routing.Locked, self: *PreparedMediaBrowserJoin) !void {
        try self.validateLocked(scope);
        self.output.commit();
        self.physical.commit();
        self.membership.commitLocked(self.domain, scope);
        self.room.commitLocked(self.domain, scope);
        if (self.stops_recording) {
            const stopped = self.server.media_rooms.stopRecording(self.physical.requested.channelSlice());
            std.debug.assert(stopped);
        }
        self.done = true;
    }

    fn deinit(self: *PreparedMediaBrowserJoin) void {
        self.output.deinit();
        self.room.deinit();
        self.membership.deinit();
        self.physical.deinit();
        self.* = undefined;
    }
};

/// Guarded choke point for the inline reply-line builders that embed
/// user/oper-influenced fields directly into a complete `... NOTICE ...\r\n`
/// wire line, bypassing both `noticeTo` and the `ReplyCtx` control-byte guard.
///
/// CWE-93 (CRLF/command injection): a smuggled CR/LF/NUL in any reflected field
/// (a SHUN/WARD/RESV/JUPE reason or pattern, a CHANBADWORDS pattern, a Recognize
/// mask, an account/nick/channel/vhost/geo value, …) would terminate the line
/// early and start a forged IRC line the peer/relay parses as its own message.
///
/// `line` is one complete single wire line ending in exactly one CRLF. Fail
/// closed: reject unless it ends in `\r\n` AND carries no other control byte in
/// the body — a lone CR/LF, an embedded CRLF, or a NUL is an injection attempt.
/// Legitimate (control-byte-free, single-line) replies pass through
/// byte-identically to `appendToConn`. This is the single point every inline
/// NOTICE builder is routed through so no reflection path can smuggle a raw
/// CR/LF onto the wire; `appendToConn`'s own full-line contract is untouched.
fn emitReplyLine(conn: *ConnState, line: []const u8) ServerError!void {
    if (line.len < 2 or line[line.len - 2] != '\r' or line[line.len - 1] != '\n') return;
    if (dispatch.hasControlByte(line[0 .. line.len - 2])) return;
    return appendToConn(conn, line);
}

/// Queue one already-framed plaintext line on this connection.
/// `appendToConn` is the channel-delivery choke point. A fresh connection
/// has no TLS session, WebSocket adapter, or labeled-response capture, so
/// the line lands in the inline SendQ.
pub fn enqueuePlainFanout(conn: *ConnState, bytes: []const u8) ServerError!void {
    return appendToConn(conn, bytes);
}

fn appendToConn(conn: *ConnState, bytes: []const u8) ServerError!void {
    // labeled-response: divert this connection's own plaintext replies into the
    // active capture buffer (before WS framing / TLS encryption) so the caller
    // can reframe them under the command's `@label`. Other connections' buffers
    // (channel fan-out to peers) are untouched — only the issuer's conn carries
    // a capture, and only for the duration of one dispatch.
    if (conn.reply_capture) |cap| {
        cap.append(bytes);
        return;
    }
    // WebSocket clients: once upgraded, outbound IRC bytes are cut on CRLF
    // boundaries and wrapped one-line-per-text-frame before the TLS seam. The
    // HTTP 101/refusal responses themselves bypass this (phase != .open yet).
    if (conn.ws) |ws| {
        if (ws.phase == .open) return wsAppendToConn(conn, ws, bytes);
    }
    return appendSecuredToConn(conn, bytes);
}

/// TLS seam: once the handshake is live, every app-layer write is encrypted
/// into TLS records before it reaches the wire buffer. Pre-handshake writes (the
/// server's own handshake flight, queued by driveTls) pass through untouched.
fn appendSecuredToConn(conn: *ConnState, bytes: []const u8) ServerError!void {
    if (conn.tls) |t| {
        if (t.handshakeDone()) {
            if (!conn.tls_tx_offloaded) return appendTlsBatchToConn(conn, t, &.{bytes});
            return appendKernelPlainToConn(conn, bytes);
        }
    }
    // Plain/kTLS and the server's pre-handshake flight are already wire bytes.
    return rawAppendToConn(conn, bytes);
}

/// Kernel plaintext suffix custody funds the speculative five-byte response
/// first. Queue failure restores only a previously absent, unadmitted credit.
fn appendKernelPlainToConn(conn: *ConnState, bytes: []const u8) ServerError!void {
    const t = conn.tls.?;
    const holding = t.control_phase == .userspace_requested_ku_held or t.control_phase == .kernel_control_read_held;
    const fund = holding and conn.tls_control_charge == 0 and bytes.len != 0;
    if (fund) {
        var reservation = try sendq.prepareControlReservation(conn, 5);
        reservation.commit();
    }
    errdefer if (fund) sendq.cancelControlReservation(conn);
    return rawAppendToConn(conn, bytes);
}

/// Same exclusive physical connection turn throughout: ciphertext is owned
/// before exact queue admission, then queue custody and TX publication cannot
/// allocate/fail. Nothing arms SEND or yields between these operations.
fn appendTlsBatchToConn(conn: *ConnState, t: *tls_conn.TlsConn, chunks: []const []const u8) ServerError!void {
    if (t.applicationOutputDeferred() or conn.tls_deferred_plain.items.len != 0) {
        const charge = t.applicationWireCharge(chunks) catch return error.OutputTooSmall;
        const holding = t.control_phase == .userspace_requested_ku_held or t.control_phase == .kernel_control_read_held;
        const fund = holding and conn.tls_control_charge == 0 and charge != 0;
        if (fund) {
            var reservation = try sendq.prepareControlReservation(conn, 27);
            reservation.commit();
        }
        errdefer if (fund) sendq.cancelControlReservation(conn);
        var retained = try sendq.prepareDeferredAppend(conn, chunks, charge);
        defer retained.deinit();
        retained.commit(chunks);
        return;
    }
    var prepared = t.prepareWriteBatch(chunks) catch return error.OutputTooSmall;
    defer prepared.deinit();
    var custody = try sendq.prepareAppend(conn, prepared.bytes().len);
    custody.commit(prepared.bytes());
    prepared.commit();
}

/// Stage every completed frame and the final partial line as one transaction.
/// The live prefix changes only after complete physical queue custody succeeds.
fn wsAppendToConn(conn: *ConnState, ws: *WsState, bytes: []const u8) ServerError!void {
    const backlog = connSendBacklog(conn);
    if (backlog > conn.sendq_cap) return error.OutputTooSmall;
    const remaining = conn.sendq_cap - @as(usize, @intCast(backlog));
    var framed = ws_output.prepare(WsState.max_frame, conn.overflow_allocator, ws.tx_buf[0..ws.tx_len], &.{bytes}, ws.tx_buf.len, remaining) catch
        return error.OutputTooSmall;
    defer framed.deinit();
    if (conn.tls) |t| {
        if (t.handshakeDone() and !conn.tls_tx_offloaded) {
            try appendTlsBatchToConn(conn, t, framed.frameChunks());
        } else if (t.handshakeDone() and conn.tls_tx_offloaded) {
            try appendKernelPlainToConn(conn, framed.bytes());
        } else try rawAppendToConn(conn, framed.bytes());
    } else try rawAppendToConn(conn, framed.bytes());
    framed.commitTail(ws);
}

/// Queue a small control frame (pong / close echo; payload <= 125 bytes per
/// RFC 6455 §5.5). Best-effort: an over-long payload is simply dropped and a
/// full send buffer drain-closes the connection.
fn wsQueueControl(conn: *ConnState, opcode: websocket.Opcode, payload: []const u8) void {
    var frame_buf: [2 + 125]u8 = undefined;
    const frame = websocket.encodeFrame(125, .{ .opcode = opcode }, payload, &frame_buf) catch return;
    appendSecuredToConn(conn, frame) catch {
        conn.closing = true;
    };
}

/// Close a WebSocket whose application message violates the negotiated
/// subprotocol. The status is network-order RFC 6455 code 1002 (protocol
/// error); setting `closing` after queueing lets the normal drain-close path
/// transmit it without accepting more application bytes.
fn wsProtocolError(conn: *ConnState) void {
    wsCloseStatus(conn, 1002);
}

/// Map fatal Deframer faults to an on-wire close status before the normal
/// drain-close path takes ownership. Size/capacity violations are 1009; every
/// malformed RFC 6455 frame/fragmentation relation is a protocol error (1002).
/// Either way only the offending connection closes.
fn wsDeframeError(conn: *ConnState, err: websocket.DeframeError) void {
    switch (err) {
        error.PayloadTooLarge, error.BufferFull => wsMessageTooBig(conn),
        error.Truncated,
        error.ReservedBitsSet,
        error.InvalidOpcode,
        error.FragmentedControlFrame,
        error.ControlFrameTooLarge,
        error.NonCanonicalLength,
        error.UnmaskedClientFrame,
        error.MaskedServerFrame,
        error.OutputTooSmall,
        error.UnexpectedContinuation,
        error.NestedFragmentation,
        => wsProtocolError(conn),
    }
}

/// RFC 6455 1009: the reassembled application message exceeded the server's
/// advertised 4 MiB media ceiling. No fragment of that message is routed.
fn wsMessageTooBig(conn: *ConnState) void {
    wsCloseStatus(conn, 1009);
}

fn wsCloseStatus(conn: *ConnState, status: u16) void {
    var payload: [2]u8 = undefined;
    std.mem.writeInt(u16, &payload, status, .big);
    wsQueueControl(conn, .close, &payload);
    conn.closing = true;
}

fn wsAdmitsBinaryApplication(ws: *const WsState) bool {
    return ws.subprotocol != .ircv3_text;
}

/// Accumulate HTTP Upgrade bytes for a handshake-phase WebSocket connection.
/// On a complete request head: validate it, queue the 101 (with the computed
/// Sec-WebSocket-Accept) and flip to `.open`, returning any bytes that arrived
/// pipelined behind the request (early frames). Returns an empty slice while
/// the head is still incomplete, and null when the request was refused (an
/// HTTP error response is queued and the connection drain-closes).
///
/// permessage-deflate is deliberately NOT negotiated: omitting the extension
/// from the 101 is RFC 7692-compliant and clients fall back to plain frames.
fn wsDriveHandshake(conn: *ConnState, ws: *WsState, bytes: []const u8) ?[]const u8 {
    if (ws.http_len + bytes.len > ws.http_buf.len) {
        wsRefuseHttp(conn, "400 Bad Request");
        return null;
    }
    @memcpy(ws.http_buf[ws.http_len..][0..bytes.len], bytes);
    ws.http_len += bytes.len;

    const head_end = std.mem.indexOf(u8, ws.http_buf[0..ws.http_len], "\r\n\r\n") orelse
        return ws.http_buf[0..0];
    const request = ws.http_buf[0 .. head_end + 4];

    var response_buf: [websocket.MAX_RESPONSE_LEN]u8 = undefined;
    const handshake = websocket.buildHandshakeResponseWithSelection(request, &response_buf) catch |err| {
        // A well-formed GET that simply isn't a WebSocket upgrade gets the
        // RFC 6455 §4.2.2 hint; everything else is a plain bad request.
        switch (err) {
            error.MissingUpgrade,
            error.InvalidUpgrade,
            error.MissingConnection,
            error.InvalidConnection,
            error.MissingVersion,
            error.UnsupportedVersion,
            => wsRefuseHttp(conn, "426 Upgrade Required"),
            else => wsRefuseHttp(conn, "400 Bad Request"),
        }
        return null;
    };
    appendSecuredToConn(conn, handshake.response) catch {
        conn.closing = true;
        return null;
    };
    ws.subprotocol = handshake.subprotocol;
    ws.phase = .open;
    return ws.http_buf[head_end + 4 .. ws.http_len];
}

/// Queue a terse HTTP refusal for a non-upgrade (or malformed) request on the
/// ws listener and drain-close the connection.
fn wsRefuseHttp(conn: *ConnState, comptime status: []const u8) void {
    const upgrade_hint = if (comptime std.mem.startsWith(u8, status, "426")) "Upgrade: websocket\r\n" else "";
    const response = "HTTP/1.1 " ++ status ++ "\r\n" ++ upgrade_hint ++
        "Connection: close\r\nContent-Length: 0\r\n\r\n";
    appendSecuredToConn(conn, response) catch {};
    conn.closing = true;
}

// -- Inbound RecvQ (growable line accumulator) -------------------------------
// The inbound twin of the SendQ below: an inline `line_buf` fast path that
// spills to a `recv_overflow` heap once a line outgrows it, bounded by the
// per-class `recvq_cap`. Server-free so the framing logic unit-tests directly.

/// Bytes of unprocessed inbound buffered for `conn` (the pending partial line):
/// the heap overflow once a line has spilled past the inline `line_buf`, else
/// the inline accumulator. The RecvQ ceiling bounds this.
fn pendingInbound(conn: *const ConnState) usize {
    return if (conn.recv_overflow.items.len != 0) conn.recv_overflow.items.len else conn.line_len;
}

/// Accumulate one inbound byte into `conn`'s growable RecvQ. Returns the
/// complete line (including its terminator) when `byte` terminates one, else
/// null. Returns `error.LineTooLong` when the pending line would exceed the
/// connection's `recvq_cap`. The caller dispatches the returned line and then
/// calls `recvqReset`.
///
/// A line is terminated by a bare LF (`\n`); an immediately preceding CR is
/// part of the canonical `\r\n` but is NOT required. RFC 1459/2812 specify
/// CRLF, but the robustness principle — and real clients (some mIRC builds and
/// many bots/scripts) — send LF-only. `irc_line.stripLineEnding` then drops the
/// optional trailing `\r`, so both `\r\n` and `\n` framings dispatch identically.
fn recvqPush(conn: *ConnState, byte: u8) error{ LineTooLong, OutOfMemory }!?[]const u8 {
    const spilled = conn.recv_overflow.items.len != 0;
    if (pendingInbound(conn) >= conn.recvq_cap) return error.LineTooLong;

    if (!spilled and conn.line_len < conn.line_buf.len) {
        conn.line_buf[conn.line_len] = byte;
        conn.line_len += 1;
        if (conn.line_buf[conn.line_len - 1] == '\n')
            return conn.line_buf[0..conn.line_len];
        return null;
    }

    // The line outgrew the inline buffer: migrate the inline prefix to the heap
    // once (so the whole line stays contiguous), then keep appending there.
    if (!spilled) try conn.recv_overflow.appendSlice(conn.overflow_allocator, conn.line_buf[0..conn.line_len]);
    try conn.recv_overflow.append(conn.overflow_allocator, byte);
    const items = conn.recv_overflow.items;
    const n = items.len;
    if (items[n - 1] == '\n') return items[0..n];
    return null;
}

/// Reset the RecvQ accumulator after a completed line has been dispatched,
/// releasing the overflow heap when it was used (steady-state memory stays
/// bounded; the rare oversized line does not pin `recvq_cap` bytes).
fn recvqReset(conn: *ConnState) void {
    if (conn.recv_overflow.items.len != 0) conn.recv_overflow.clearAndFree(conn.overflow_allocator);
    conn.line_len = 0;
}

/// Bytes waiting in this connection's SendQ. Inline tail plus overflow.
fn connSendBacklog(conn: *const ConnState) u64 {
    return sendq.backlog(conn);
}

fn rawAppendToConn(conn: *ConnState, bytes: []const u8) ServerError!void {
    return sendq.rawAppend(conn, bytes);
}

fn reserveRawAppendToConn(conn: *ConnState, bytes_len: usize) ServerError!void {
    return sendq.reserve(conn, bytes_len);
}

/// Exact outer Mooring record size for one signed SESSION_REPLICA object. A v2
/// peer necessarily negotiated the direct signed envelope, and SecuredLink
/// seals each inner drain into one `[u32 length][ciphertext][tag]` record.
fn sessionReplicaSecuredRecordLen(signed_payload_len: usize) ?usize {
    const transport_len = session_replica_frame.encodedLen(signed_payload_len) catch return null;
    const inner_len = std.math.add(
        usize,
        s2s_frame.header_len + signed_s2s_frame.header_len,
        transport_len,
    ) catch return null;
    return std.math.add(
        usize,
        inner_len,
        @sizeOf(u32) + std.crypto.aead.chacha_poly.ChaCha20Poly1305.tag_length,
    ) catch null;
}

fn refillFromOverflow(conn: *ConnState) void {
    sendq.refill(conn);
}

test "GAP-X2 SendQ inline fast path, heap overflow, refill, and per-class cap" {
    var conn = ConnState.init(-1);
    conn.overflow_allocator = std.testing.allocator;
    conn.sendq_cap = 20 * 1024; // 20 KiB
    defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);

    const chunk = @as([4096]u8, @splat('a'));
    // Two chunks fill the inline 8 KiB buffer exactly (no heap).
    try rawAppendToConn(&conn, &chunk);
    try rawAppendToConn(&conn, &chunk);
    try std.testing.expectEqual(@as(usize, 8192), conn.send_len);
    try std.testing.expectEqual(@as(usize, 0), conn.send_overflow.items.len);

    // Next three chunks spill to the overflow heap, up to the 20 KiB ceiling.
    try rawAppendToConn(&conn, &chunk);
    try rawAppendToConn(&conn, &chunk);
    try rawAppendToConn(&conn, &chunk);
    try std.testing.expectEqual(@as(usize, 12288), conn.send_overflow.items.len);
    // One more byte blows the cap (8192 + 12288 = 20480 == cap).
    try std.testing.expectError(error.OutputTooSmall, rawAppendToConn(&conn, "x"));

    // Drain the inline buffer → refill pulls the next 8 KiB from overflow.
    conn.send_offset = 0;
    conn.send_len = 0;
    refillFromOverflow(&conn);
    try std.testing.expectEqual(@as(usize, 8192), conn.send_len);
    try std.testing.expectEqual(@as(usize, 4096), conn.send_overflow.items.len);

    // Drain again → the last 4 KiB refills and the overflow heap is freed.
    conn.send_offset = 0;
    conn.send_len = 0;
    refillFromOverflow(&conn);
    try std.testing.expectEqual(@as(usize, 4096), conn.send_len);
    try std.testing.expectEqual(@as(usize, 0), conn.send_overflow.capacity);
    try std.testing.expectEqual(@as(u64, 4096), connSendBacklog(&conn));

    var compact = ConnState.init(-1);
    compact.overflow_allocator = std.testing.allocator;
    compact.sendq_cap = 20 * 1024;
    defer if (compact.send_overflow.capacity > 0) compact.send_overflow.deinit(compact.overflow_allocator);
    compact.send_buf[100] = 'Q';
    compact.send_buf[compact.send_buf.len - 1] = 'W';
    compact.send_offset = 100;
    compact.send_len = compact.send_buf.len;
    compact.send_armed = false;
    try rawAppendToConn(&compact, "Z");
    try std.testing.expectEqual(@as(usize, 0), compact.send_offset);
    try std.testing.expectEqual(compact.send_buf.len - 100 + 1, compact.send_len);
    try std.testing.expectEqual(@as(u8, 'Q'), compact.send_buf[0]);
    try std.testing.expectEqual(@as(u8, 'W'), compact.send_buf[compact.send_buf.len - 101]);
    try std.testing.expectEqual(@as(u8, 'Z'), compact.send_buf[compact.send_len - 1]);
    try std.testing.expectEqual(@as(usize, 0), compact.send_overflow.items.len);

    var armed = ConnState.init(-1);
    armed.overflow_allocator = std.testing.allocator;
    armed.sendq_cap = 20 * 1024;
    defer if (armed.send_overflow.capacity > 0) armed.send_overflow.deinit(armed.overflow_allocator);
    armed.send_offset = 100;
    armed.send_len = armed.send_buf.len;
    armed.send_armed = true;
    try rawAppendToConn(&armed, "Z");
    try std.testing.expectEqual(@as(usize, 100), armed.send_offset);
    try std.testing.expectEqual(armed.send_buf.len, armed.send_len);
    try std.testing.expectEqualStrings("Z", armed.send_overflow.items);
    try std.testing.expect(armed.send_armed);

    std.debug.print("GAP-X2 step2 branch=SendQ append reserve refill and backlog moved out of server.zig and the inline overflow cap and armed-buffer rules still hold\n", .{});
}

test "GAP-X2 SendQ per-class cap also bounds the inline fast path" {
    var conn = ConnState.init(-1);
    conn.overflow_allocator = std.testing.allocator;
    conn.sendq_cap = 3;
    defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);

    try reserveRawAppendToConn(&conn, 3);
    try std.testing.expectError(error.OutputTooSmall, reserveRawAppendToConn(&conn, 4));
    try std.testing.expectEqual(@as(usize, 0), conn.send_overflow.items.len);
    try std.testing.expectError(error.OutputTooSmall, rawAppendToConn(&conn, "four"));
    try std.testing.expectEqual(@as(usize, 0), conn.send_len);
    try rawAppendToConn(&conn, "abc");
    try std.testing.expectEqualStrings("abc", conn.send_buf[0..conn.send_len]);
    try std.testing.expectError(error.OutputTooSmall, rawAppendToConn(&conn, "x"));
    try std.testing.expectEqual(@as(usize, 3), conn.send_len);
    try std.testing.expectEqual(@as(usize, 0), conn.send_overflow.items.len);
}

test "GAP-X5 enqueuePlainFanout queues one line on the connection SendQ" {
    var conn = ConnState.init(-1);
    conn.overflow_allocator = std.testing.allocator;
    defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);

    const line = ":nick!u@h PRIVMSG #c :hi";
    try enqueuePlainFanout(&conn, line);
    try std.testing.expectEqualStrings(line, conn.send_buf[0..conn.send_len]);
    try std.testing.expectEqual(@as(usize, 0), conn.send_overflow.items.len);
    try std.testing.expectEqual(@as(usize, 0), conn.recv_overflow.items.len);
    try std.testing.expectEqual(@as(usize, 0), conn.session_list_cache.rows.items.len);
    std.debug.print(
        "GAP-X5 branch=plaintext fan-out line queued on the inline SendQ; ConnState bytes={d}\n",
        .{@sizeOf(ConnState)},
    );
}

test "GAP-O5 REHASH DRY prints diffs and applies none" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    var server = Server.init(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const text =
        \\[node]
        \\id = 1
        \\
        \\[listen]
        \\host = "127.0.0.1"
        \\irc = 18981
        \\ws = 18982
        \\
        \\[limits]
        \\max_clones_per_ip = 9
        \\nick_delay = "3s"
        \\
        \\[class.trusted]
        \\sendq = "2M"
        \\
        \\[dnsbl]
        \\action = "ward"
        \\
    ;
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "rehash.toml", .data = text });
    var path_buf: [256]u8 = undefined;
    const path = std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/rehash.toml", .{tmp.sub_path[0..]}) catch return error.TestUnexpectedResult;

    server.config.config_path = path;
    server.config.crypto_io = std.testing.io;
    server.config.port = 18981;
    server.config.ws_enabled = false;
    server.config.ws_port = 0;
    server.config.tls_port = 0;
    server.config.s2s_port = 0;
    server.config.webtransport_port = 0;
    server.config.media_port = 0;
    server.config.native_media_port = 0;
    server.config.max_clones_per_ip = 2;
    server.config.nick_delay_ms = 0;
    server.config.raid_joins = 0;
    server.config.raid_secs = 10;
    server.config.dnsbl_ward = false;
    server.config.tls_enable_resumption = true;
    server.tls_ticket_key = @splat(0x5a);
    const ticket_before = server.tls_ticket_key;
    try server.warden.add(.{
        .match = .address,
        .pattern = "203.0.113.9",
        .reason = "gap-o5",
        .set_by = "test",
    });

    const id = try server.rx().clients.alloc(ConnState.init(-1));
    const conn = server.rx().clients.get(id).?;
    conn.overflow_allocator = allocator;
    conn.token = try tokenFromId(id);
    conn.send_armed = true;
    defer {
        if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(allocator);
        if (server.rx().clients.get(id)) |live| {
            live.send_armed = false;
            _ = server.rx().clients.free(id);
        }
    }
    conn.session.is_oper = true;
    conn.session.oper_priv = oper_mod.OperPrivileges.initMany(&.{.server_rehash});
    try conn.session.setNick("oper");

    const invocation = try irc_line.parseLine("REHASH DRY");
    try server.handleRehashParsed(conn, &invocation);

    const reply = conn.send_buf[0..conn.send_len];
    try std.testing.expect(std.mem.indexOf(u8, reply, "REHASH DRY: applied none") != null);
    try std.testing.expect(std.mem.indexOf(u8, reply, "REHASH DRY ward dnsbl.action: refuse -> ward") != null);
    try std.testing.expect(std.mem.indexOf(u8, reply, "REHASH DRY ward running address 203.0.113.9 kept") != null);
    try std.testing.expect(std.mem.indexOf(u8, reply, "REHASH DRY class +trusted") != null);
    try std.testing.expect(std.mem.indexOf(u8, reply, "REHASH DRY limit max_clones_per_ip: 2 -> 9") != null);
    try std.testing.expect(std.mem.indexOf(u8, reply, "REHASH DRY limit nick_delay_ms: 0 -> 3000") != null);
    try std.testing.expect(std.mem.indexOf(u8, reply, "REHASH DRY listener ws: 0 -> 18982") != null);
    try std.testing.expect(std.mem.indexOf(u8, reply, config_format.cold_restart_required_reason) != null);
    try std.testing.expect(std.mem.indexOf(u8, reply, "dry-run; applied none") != null);

    try std.testing.expectEqual(@as(u32, 2), server.config.max_clones_per_ip);
    try std.testing.expectEqual(@as(u64, 0), server.config.nick_delay_ms);
    try std.testing.expect(!server.config.dnsbl_ward);
    try std.testing.expect(!server.config.ws_enabled);
    try std.testing.expectEqual(@as(u16, 0), server.config.ws_port);
    try std.testing.expectEqual(@as(u16, 18981), server.config.port);
    try std.testing.expect(server.config.class_registry == null);
    try std.testing.expect(server.reload_parsed == null);
    try std.testing.expect(server.oper_registry == null);
    try std.testing.expectEqual(@as(usize, 0), server.reload_bindings.len);
    try std.testing.expectEqual(ticket_before, server.tls_ticket_key);
    try std.testing.expect(server.tls_previous_ticket_key == null);
    try std.testing.expect(server.warden.check(.{ .address = "203.0.113.9" }, 0) != null);

    try server.handleRehash(conn);
    try std.testing.expectEqual(@as(u32, 9), server.config.max_clones_per_ip);
    try std.testing.expectEqual(@as(u64, 3000), server.config.nick_delay_ms);
    try std.testing.expect(!server.config.ws_enabled);
    try std.testing.expectEqual(@as(u16, 0), server.config.ws_port);
    try std.testing.expect(!server.config.dnsbl_ward);
    try std.testing.expect(server.reload_parsed != null);
    try std.testing.expect(server.config.class_registry.?.byName("trusted") != null);
    try std.testing.expect(server.tls_previous_ticket_key != null);
    try std.testing.expectEqual(ticket_before, server.tls_previous_ticket_key.?);
    try std.testing.expect(server.warden.check(.{ .address = "203.0.113.9" }, 0) != null);

    std.debug.print("GAP-O5 branch=REHASH DRY named ward class limit and listener diffs, applied none, then a real REHASH applied the limit without moving the listener\n", .{});
}

test "GAP-V3 MEDIA ABR stores independent spatial ceilings from the hint" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;
    var server = Server.init(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const low_id = try addTestLocalClient(&server, "low", null);
    const high_id = try addTestLocalClient(&server, "high", null);
    _ = try server.world.join("#v", worldIdFromClient(low_id));
    _ = try server.world.join("#v", worldIdFromClient(high_id));
    const low = server.rx().clients.get(low_id).?;
    const high = server.rx().clients.get(high_id).?;
    low.send_armed = true;
    high.send_armed = true;

    const join_low = try irc_line.parseLine("MEDIA JOIN #v voice");
    const join_high = try irc_line.parseLine("MEDIA JOIN #v voice");
    try server.handleMedia(low_id, low, &join_low);
    try server.handleMedia(high_id, high, &join_high);
    try server.native_media.register("#v", "low", .voice, 11, .{});
    try server.native_media.register("#v", "high", .voice, 12, .{});
    try std.testing.expect(server.media_plane.allocate("#v", "low") != null);
    try std.testing.expect(server.media_plane.allocate("#v", "high") != null);

    // Congested report: loss drives abrHint down to the base spatial layer.
    const abr_low = try irc_line.parseLine("MEDIA ABR #v 200 200 20 10");
    try server.handleMedia(low_id, low, &abr_low);
    // Uncongested report with headroom: abrHint raises this receiver only.
    const abr_high = try irc_line.parseLine("MEDIA ABR #v 1100 6000 0 20");
    try server.handleMedia(high_id, high, &abr_high);

    try std.testing.expectEqual(@as(u8, 0), server.native_media.selectionOf("#v", "low").max_spatial);
    try std.testing.expectEqual(@as(u8, 2), server.native_media.selectionOf("#v", "high").max_spatial);
    try std.testing.expectEqual(@as(u8, 0), server.media_plane.receiverSpatial("#v", "low").?);
    try std.testing.expectEqual(@as(u8, 2), server.media_plane.receiverSpatial("#v", "high").?);

    const low_reply = low.send_buf[0..low.send_len];
    const high_reply = high.send_buf[0..high.send_len];
    try std.testing.expect(std.mem.indexOf(u8, low_reply, "spatial<=0") != null);
    try std.testing.expect(std.mem.indexOf(u8, high_reply, "spatial<=2") != null);
    try std.testing.expect(std.mem.indexOf(u8, low_reply, "action=decrease") != null);
    try std.testing.expect(std.mem.indexOf(u8, high_reply, "action=increase") != null);

    std.debug.print("GAP-V3 branch=MEDIA ABR applies each receiver's abrHint to its own spatial ceiling\n", .{});
}

test "GAP-V4 recording waits for every member and stops when one joins" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;
    var server = Server.init(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const alice_id = try addTestLocalClient(&server, "alice", null);
    const bob_id = try addTestLocalClient(&server, "bob", null);
    const carol_id = try addTestLocalClient(&server, "carol", null);
    _ = try server.world.join("#rec", worldIdFromClient(alice_id));
    _ = try server.world.join("#rec", worldIdFromClient(bob_id));
    _ = try server.world.join("#rec", worldIdFromClient(carol_id));
    const alice = server.rx().clients.get(alice_id).?;
    const bob = server.rx().clients.get(bob_id).?;
    const carol = server.rx().clients.get(carol_id).?;
    alice.send_armed = true;
    bob.send_armed = true;
    carol.send_armed = true;

    const join_a = try irc_line.parseLine("MEDIA JOIN #rec voice");
    const join_b = try irc_line.parseLine("MEDIA JOIN #rec voice");
    try server.handleMedia(alice_id, alice, &join_a);
    try server.handleMedia(bob_id, bob, &join_b);

    alice.send_len = 0;
    const too_soon = try irc_line.parseLine("MEDIA RECORD #rec");
    try server.handleMedia(alice_id, alice, &too_soon);
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], "CONSENT_REQUIRED") != null);

    const consent_a = try irc_line.parseLine("MEDIA CONSENT #rec on");
    const consent_b = try irc_line.parseLine("MEDIA CONSENT #rec on");
    try server.handleMedia(alice_id, alice, &consent_a);
    try server.handleMedia(bob_id, bob, &consent_b);
    alice.send_len = 0;
    const record = try irc_line.parseLine("MEDIA RECORD #rec");
    try server.handleMedia(alice_id, alice, &record);
    const note = server.media_rooms.recordingOf("#rec") orelse return error.TestUnexpectedResult;
    try std.testing.expect(note.active);
    try std.testing.expectEqualStrings("alice", note.by());
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], "RECORD") != null);
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], "started") != null);

    const roster = try irc_line.parseLine("MEDIA ROSTER #rec");
    alice.send_len = 0;
    try server.handleMedia(alice_id, alice, &roster);
    const roster_text = alice.send_buf[0..alice.send_len];
    try std.testing.expect(std.mem.indexOf(u8, roster_text, "alice voice main 0 0 - consent=1") != null);
    try std.testing.expect(std.mem.indexOf(u8, roster_text, "bob voice main 0 0 - consent=1") != null);

    const join_c = try irc_line.parseLine("MEDIA JOIN #rec voice");
    try server.handleMedia(carol_id, carol, &join_c);
    const stopped = server.media_rooms.recordingOf("#rec") orelse return error.TestUnexpectedResult;
    try std.testing.expect(!stopped.active);
    try std.testing.expect(std.mem.indexOf(u8, carol.send_buf[0..carol.send_len], "stopped") != null);

    std.debug.print("GAP-V4 branch=recording starts only after every member consents, is announced, and stops when a member joins without consent\n", .{});
}

test "GAP-V5 a participant or oper reads loss rtt and layer without key material" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;
    var server = Server.init(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const alice_id = try addTestLocalClient(&server, "alice", null);
    const bob_id = try addTestLocalClient(&server, "bob", null);
    const carol_id = try addTestLocalClient(&server, "carol", null);
    const oper_id = try addTestLocalClient(&server, "oper", null);
    const eve_id = try addTestLocalClient(&server, "eve", null);
    _ = try server.world.join("#q", worldIdFromClient(alice_id));
    _ = try server.world.join("#q", worldIdFromClient(bob_id));
    _ = try server.world.join("#q", worldIdFromClient(carol_id));
    const alice = server.rx().clients.get(alice_id).?;
    const bob = server.rx().clients.get(bob_id).?;
    const carol = server.rx().clients.get(carol_id).?;
    const oper = server.rx().clients.get(oper_id).?;
    const eve = server.rx().clients.get(eve_id).?;
    alice.send_armed = true;
    bob.send_armed = true;
    carol.send_armed = true;
    oper.send_armed = true;
    eve.send_armed = true;
    oper.session.is_oper = true;

    const join_a = try irc_line.parseLine("MEDIA JOIN #q voice");
    const join_b = try irc_line.parseLine("MEDIA JOIN #q voice");
    const join_c = try irc_line.parseLine("MEDIA JOIN #q voice");
    try server.handleMedia(alice_id, alice, &join_a);
    try server.handleMedia(bob_id, bob, &join_b);
    try server.handleMedia(carol_id, carol, &join_c);
    try server.native_media.register("#q", "alice", .voice, 11, .{});
    try server.native_media.register("#q", "bob", .voice, 12, .{});
    try std.testing.expect(server.media_plane.allocate("#q", "alice") != null);
    try std.testing.expect(server.media_plane.allocate("#q", "bob") != null);

    // The trailing token is key material a naive echo would leak. It is not a
    // field of the stored sample.
    const abr_a = try irc_line.parseLine("MEDIA ABR #q 200 200 20 10 0 ufrag=planted-ufrag ice-pwd=planted-pwd srtp=planted-srtp");
    const abr_b = try irc_line.parseLine("MEDIA ABR #q 1100 6000 0 20");
    try server.handleMedia(alice_id, alice, &abr_a);
    try server.handleMedia(bob_id, bob, &abr_b);

    const alice_q = server.media_rooms.qualityOf("#q", "alice") orelse return error.TestUnexpectedResult;
    const bob_q = server.media_rooms.qualityOf("#q", "bob") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u8, 20), alice_q.loss_pct);
    try std.testing.expectEqual(@as(u16, 10), alice_q.rtt_ms);
    try std.testing.expectEqual(@as(u8, 0), alice_q.spatial);
    try std.testing.expectEqual(@as(u8, 0), bob_q.loss_pct);
    try std.testing.expectEqual(@as(u16, 20), bob_q.rtt_ms);
    try std.testing.expectEqual(@as(u8, 2), bob_q.spatial);
    try std.testing.expect(server.media_rooms.qualityOf("#q", "carol") == null);

    alice.send_len = 0;
    const quality = try irc_line.parseLine("MEDIA QUALITY #q");
    try server.handleMedia(alice_id, alice, &quality);
    const summary = alice.send_buf[0..alice.send_len];
    var alice_expect: [96]u8 = undefined;
    const alice_line = std.fmt.bufPrint(&alice_expect, "alice loss={d} rtt={d} spatial={d} bitrate={d}", .{
        alice_q.loss_pct, alice_q.rtt_ms, alice_q.spatial, alice_q.bitrate_kbps,
    }) catch unreachable;
    var bob_expect: [96]u8 = undefined;
    const bob_line = std.fmt.bufPrint(&bob_expect, "bob loss={d} rtt={d} spatial={d} bitrate={d}", .{
        bob_q.loss_pct, bob_q.rtt_ms, bob_q.spatial, bob_q.bitrate_kbps,
    }) catch unreachable;
    try std.testing.expect(std.mem.indexOf(u8, summary, alice_line) != null);
    try std.testing.expect(std.mem.indexOf(u8, summary, bob_line) != null);
    try std.testing.expect(std.mem.indexOf(u8, summary, "count=2") != null);
    try std.testing.expect(std.mem.indexOf(u8, summary, "carol") == null);
    try std.testing.expect(std.mem.indexOf(u8, summary, "ufrag") == null);
    try std.testing.expect(std.mem.indexOf(u8, summary, "ice-pwd") == null);
    try std.testing.expect(std.mem.indexOf(u8, summary, "srtp") == null);
    try std.testing.expect(std.mem.indexOf(u8, summary, "planted-ufrag") == null);
    try std.testing.expect(std.mem.indexOf(u8, summary, "planted-pwd") == null);
    try std.testing.expect(std.mem.indexOf(u8, summary, "planted-srtp") == null);
    try std.testing.expect(std.mem.indexOf(u8, summary, "keyframe") == null);

    const abr_a2 = try irc_line.parseLine("MEDIA ABR #q 200 200 7 44");
    try server.handleMedia(alice_id, alice, &abr_a2);
    const alice_q2 = server.media_rooms.qualityOf("#q", "alice") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u8, 7), alice_q2.loss_pct);
    try std.testing.expectEqual(@as(u16, 44), alice_q2.rtt_ms);
    alice.send_len = 0;
    try server.handleMedia(alice_id, alice, &quality);
    const updated = alice.send_buf[0..alice.send_len];
    try std.testing.expect(std.mem.indexOf(u8, updated, "alice loss=7 rtt=44") != null);
    try std.testing.expect(std.mem.indexOf(u8, updated, "loss=20") == null);

    oper.send_len = 0;
    try server.handleMedia(oper_id, oper, &quality);
    const oper_summary = oper.send_buf[0..oper.send_len];
    try std.testing.expect(std.mem.indexOf(u8, oper_summary, "alice loss=7 rtt=44") != null);
    try std.testing.expect(std.mem.indexOf(u8, oper_summary, bob_line) != null);
    try std.testing.expect(std.mem.indexOf(u8, oper_summary, "ufrag") == null);
    try std.testing.expect(std.mem.indexOf(u8, oper_summary, "srtp") == null);
    try std.testing.expect(!server.world.isMember("#q", worldIdFromClient(oper_id)));

    eve.send_len = 0;
    try server.handleMedia(eve_id, eve, &quality);
    const refused = eve.send_buf[0..eve.send_len];
    try std.testing.expect(std.mem.indexOf(u8, refused, "442") != null);
    try std.testing.expect(std.mem.indexOf(u8, refused, "loss=") == null);

    std.debug.print("GAP-V5 branch=participant and oper read loss rtt spatial bitrate; key material is absent\n", .{});
}

test "GAP-V6 the room reads the speaking queue and the server forwards positions" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;
    var server = Server.init(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const alice_id = try addTestLocalClient(&server, "alice", null);
    const bob_id = try addTestLocalClient(&server, "bob", null);
    const carol_id = try addTestLocalClient(&server, "carol", null);
    _ = try server.world.join("#q", worldIdFromClient(alice_id));
    _ = try server.world.join("#q", worldIdFromClient(bob_id));
    _ = try server.world.join("#q", worldIdFromClient(carol_id));
    const alice = server.rx().clients.get(alice_id).?;
    const bob = server.rx().clients.get(bob_id).?;
    const carol = server.rx().clients.get(carol_id).?;
    alice.send_armed = true;
    bob.send_armed = true;
    carol.send_armed = true;

    const join_a = try irc_line.parseLine("MEDIA JOIN #q voice");
    const join_b = try irc_line.parseLine("MEDIA JOIN #q voice");
    const join_c = try irc_line.parseLine("MEDIA JOIN #q voice");
    try server.handleMedia(alice_id, alice, &join_a);
    try server.handleMedia(bob_id, bob, &join_b);
    try server.handleMedia(carol_id, carol, &join_c);

    const hand_a = try irc_line.parseLine("MEDIA HAND #q up");
    const hand_b = try irc_line.parseLine("MEDIA HAND #q up");
    const hand_c = try irc_line.parseLine("MEDIA HAND #q up");
    try server.handleMedia(alice_id, alice, &hand_a);
    try server.handleMedia(bob_id, bob, &hand_b);
    try server.handleMedia(carol_id, carol, &hand_c);

    bob.send_len = 0;
    const queue = try irc_line.parseLine("MEDIA QUEUE #q");
    try server.handleMedia(bob_id, bob, &queue);
    const listed = bob.send_buf[0..bob.send_len];
    const alice_at = std.mem.indexOf(u8, listed, "0 alice") orelse return error.TestUnexpectedResult;
    const bob_at = std.mem.indexOf(u8, listed, "1 bob") orelse return error.TestUnexpectedResult;
    const carol_at = std.mem.indexOf(u8, listed, "2 carol") orelse return error.TestUnexpectedResult;
    try std.testing.expect(alice_at < bob_at and bob_at < carol_at);
    try std.testing.expect(std.mem.indexOf(u8, listed, "count=3") != null);

    // Carol is last in the queue. Speaking still succeeds.
    carol.send_len = 0;
    const speak = try irc_line.parseLine("MEDIA SPEAKING #q voice on");
    try server.handleMedia(carol_id, carol, &speak);
    const speak_reply = carol.send_buf[0..carol.send_len];
    try std.testing.expect(std.mem.indexOf(u8, speak_reply, "FAIL") == null);
    try std.testing.expect(std.mem.indexOf(u8, speak_reply, "head") == null);
    var carol_speaking = false;
    for (server.media_rooms.roster("#q")) |p| {
        if (std.mem.eql(u8, p.id.slice(), "carol")) carol_speaking = p.speaking.contains(.voice);
    }
    try std.testing.expect(carol_speaking);

    const hand_down = try irc_line.parseLine("MEDIA HAND #q down");
    try server.handleMedia(alice_id, alice, &hand_down);
    bob.send_len = 0;
    try server.handleMedia(bob_id, bob, &queue);
    const promoted = bob.send_buf[0..bob.send_len];
    try std.testing.expect(std.mem.indexOf(u8, promoted, "0 bob") != null);
    try std.testing.expect(std.mem.indexOf(u8, promoted, "1 carol") != null);
    try std.testing.expect(std.mem.indexOf(u8, promoted, "0 alice") == null);

    const pos = try irc_line.parseLine("MEDIA POS #q 120 -45");
    try server.handleMedia(alice_id, alice, &pos);
    const stored = server.media_rooms.positionOf("#q", "alice");
    try std.testing.expectEqual(@as(i32, 120), stored.x);
    try std.testing.expectEqual(@as(i32, -45), stored.y);
    bob.send_len = 0;
    const roster = try irc_line.parseLine("MEDIA ROSTER #q");
    try server.handleMedia(bob_id, bob, &roster);
    const room = bob.send_buf[0..bob.send_len];
    try std.testing.expect(std.mem.indexOf(u8, room, "alice voice main 120 -45 - consent=0") != null);
    try std.testing.expect(std.mem.indexOf(u8, room, "distance") == null);
    try std.testing.expect(std.mem.indexOf(u8, room, "gain") == null);

    std.debug.print("GAP-V6 branch=queue is listed in raise order; a non-head still speaks; positions are forwarded unchanged\n", .{});
}

fn expectFlightOnce(haystack: []const u8, needle: []const u8) !void {
    const at = std.mem.indexOf(u8, haystack, needle) orelse return error.TestExpectedEqual;
    try std.testing.expect(std.mem.indexOf(u8, haystack[at + needle.len ..], needle) == null);
}

test "GAP-O3 a fault writes the tracelog to the named file" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd and builtin.os.tag != .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    const server = try allocator.create(Server);
    server.initInPlace(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| {
        allocator.destroy(server);
        return switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => error.SkipZigTest,
            else => err,
        };
    };
    defer {
        server.deinit();
        allocator.destroy(server);
    }
    current_reactor = &server.reactors[0];
    server.bindFlightPanicTarget();

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try rehashTmpPath(allocator, tmp, "flight.log");
    defer allocator.free(path);

    // An empty operator path must not create the file and must not record the fault.
    flushFlightRecorderOnPanic("GAP-O3 panic fault");
    try std.testing.expectError(error.FileNotFound, tmp.dir.readFileAlloc(std.testing.io, "flight.log", allocator, .limited(64)));

    server.config.flight_recorder_path = path;
    server.traceLog(.info, .reactor, "GAP-O3 recorder marker");
    flushFlightRecorderOnPanic("GAP-O3 panic fault");
    const panic_body = try tmp.dir.readFileAlloc(std.testing.io, "flight.log", allocator, .limited(flight_recorder_max_file_bytes + 1));
    defer allocator.free(panic_body);
    try std.testing.expect(panic_body.len <= flight_recorder_max_file_bytes);
    try std.testing.expect(std.mem.indexOf(u8, panic_body, "level=") != null);
    try std.testing.expect(std.mem.indexOf(u8, panic_body, "category=") != null);
    try std.testing.expect(std.mem.indexOf(u8, panic_body, "msg=") != null);
    try expectFlightOnce(panic_body, "GAP-O3 recorder marker");
    try expectFlightOnce(panic_body, "GAP-O3 panic fault");
    try std.testing.expect(std.mem.indexOf(u8, panic_body, "reactor giving up after persistent errors") == null);
    try std.testing.expect(std.mem.indexOf(u8, panic_body, "mooring link dropped") == null);

    server.reactor_fail_for_test = true;
    var run = std.atomic.Value(bool).init(true);
    server.runLoopResilient(&run);
    server.reactor_fail_for_test = false;
    const give_up = try tmp.dir.readFileAlloc(std.testing.io, "flight.log", allocator, .limited(flight_recorder_max_file_bytes + 1));
    defer allocator.free(give_up);
    try std.testing.expect(give_up.len <= flight_recorder_max_file_bytes);
    try expectFlightOnce(give_up, "GAP-O3 recorder marker");
    try expectFlightOnce(give_up, "GAP-O3 panic fault");
    try expectFlightOnce(give_up, "reactor giving up after persistent errors");

    var pair = try SessionReplayTestPair.init(allocator);
    const link = allocator.create(secured_s2s_link.SecuredLink) catch |err| {
        pair.deinit();
        return err;
    };
    // The established link is moved onto the heap so closeConn can destroy it.
    // The stack copy keeps the same bytes for any interior pointers and is not
    // deinited; closeConn owns the heap link from here.
    link.* = pair.a;
    var link_live = true;
    defer {
        pair.b.deinit();
        // Inner deinit unmaps the shared signing page. Drop the dangling
        // identity pointer before the identity wipe.
        pair.ida.sign_kp.secret_key.page = null;
        pair.idb.sign_kp.secret_key.page = null;
        pair.ida.deinit();
        pair.idb.deinit();
    }
    errdefer {
        if (link_live) {
            link.deinit();
            allocator.destroy(link);
        }
    }

    const id = try server.rx().clients.alloc(ConnState.init(-1));
    const conn = server.rx().clients.get(id).?;
    conn.overflow_allocator = allocator;
    conn.token = try tokenFromId(id);
    conn.s2s_secured = link;
    try server.closeConn(conn.token, "mooring test");
    link_live = false;
    try std.testing.expect(server.rx().clients.get(id) == null);

    const dropped = try tmp.dir.readFileAlloc(std.testing.io, "flight.log", allocator, .limited(flight_recorder_max_file_bytes + 1));
    defer allocator.free(dropped);
    try std.testing.expect(dropped.len <= flight_recorder_max_file_bytes);
    try expectFlightOnce(dropped, "GAP-O3 recorder marker");
    try expectFlightOnce(dropped, "GAP-O3 panic fault");
    try expectFlightOnce(dropped, "reactor giving up after persistent errors");
    try expectFlightOnce(dropped, "mooring link dropped");
    try std.testing.expect(std.mem.indexOf(u8, dropped, "category=s2s") != null);
    try std.testing.expect(std.mem.indexOf(u8, dropped, "qlog") == null);

    std.debug.print("GAP-O3 branch=tracelog file on panic, reactor give-up, and mooring death\n", .{});
}

/// Real encrypted link pair for daemon-level retained-replay tests. Keeping the
/// fixture here exercises the exact SecuredLink record counters and ciphertext
/// retention used in production rather than a fake byte sink.
const SessionReplayTestPair = struct {
    ida: node_identity.NodeIdentity,
    idb: node_identity.NodeIdentity,
    a: secured_s2s_link.SecuredLink,
    b: secured_s2s_link.SecuredLink,

    fn init(allocator: std.mem.Allocator) !SessionReplayTestPair {
        return initWithSeeds(allocator, 0x31, 0x32);
    }

    fn initWithSeeds(
        allocator: std.mem.Allocator,
        local_seed: u8,
        remote_seed: u8,
    ) !SessionReplayTestPair {
        return initWithSeedsAndNames(allocator, local_seed, remote_seed, "replay-a.test", "replay-b.test");
    }

    fn initWithSeedsAndNames(
        allocator: std.mem.Allocator,
        local_seed: u8,
        remote_seed: u8,
        name_a: []const u8,
        name_b: []const u8,
    ) !SessionReplayTestPair {
        var ida = try node_identity.fromSeed(
            @as([32]u8, @splat(local_seed)),
            "session-replay-test",
        );
        errdefer ida.deinit();
        var idb = try node_identity.fromSeed(
            @as([32]u8, @splat(remote_seed)),
            "session-replay-test",
        );
        errdefer idb.deinit();
        const pre_a = try ida.signedPrekey(1, 10, 1000, LinuxServer.s2s_bands, LinuxServer.s2s_features);
        const pre_b = try idb.signedPrekey(2, 10, 1000, LinuxServer.s2s_bands, LinuxServer.s2s_features);
        var a = try secured_s2s_link.SecuredLink.init(.{
            .allocator = allocator,
            .role = .initiator,
            .identity = &ida,
            .local_prekey = pre_a,
            .cfg = .{
                .realm = ida.realm,
                .supported_bands = LinuxServer.s2s_bands,
                .supported_features = LinuxServer.s2s_features,
                .mesh_pass = "session-replay-secret",
                .now_ms = 20,
            },
            .rng = std.testing.io,
            .server_name = name_a,
        });
        errdefer a.deinit();
        var b = try secured_s2s_link.SecuredLink.init(.{
            .allocator = allocator,
            .role = .responder,
            .identity = &idb,
            .local_prekey = pre_b,
            .cfg = .{
                .realm = idb.realm,
                .supported_bands = LinuxServer.s2s_bands,
                .supported_features = LinuxServer.s2s_features,
                .mesh_pass = "",
                .now_ms = 20,
            },
            .rng = std.testing.io,
            .server_name = name_b,
        });
        errdefer b.deinit();
        var pair = SessionReplayTestPair{ .ida = ida, .idb = idb, .a = a, .b = b };
        try pair.pump(allocator);
        try std.testing.expect(pair.a.established());
        try std.testing.expect(pair.b.established());
        try std.testing.expect(pair.a.supportsSessionReplicaV2());
        try std.testing.expect(pair.b.supportsSessionReplicaV2());
        return pair;
    }

    fn pump(self: *SessionReplayTestPair, allocator: std.mem.Allocator) !void {
        var rounds: usize = 0;
        while (rounds < 64) : (rounds += 1) {
            if (self.a.outbound().len == 0 and self.b.outbound().len == 0) return;
            {
                const a_out = try allocator.dupe(u8, self.a.outbound());
                defer allocator.free(a_out);
                const b_out = try allocator.dupe(u8, self.b.outbound());
                defer allocator.free(b_out);
                self.a.clearOutbound();
                self.b.clearOutbound();
                if (a_out.len != 0) try self.b.feed(a_out, @as(u64, @intCast(rounds + 21)));
                if (b_out.len != 0) try self.a.feed(b_out, @as(u64, @intCast(rounds + 21)));
            }
        }
        return error.TestUnexpectedResult;
    }

    fn deinit(self: *SessionReplayTestPair) void {
        self.a.deinit();
        self.b.deinit();
        // Link deinit unmaps the shared identity signing page. Drop the
        // dangling pointer so the identity wipe does not unmap it again.
        self.ida.sign_kp.secret_key.page = null;
        self.idb.sign_kp.secret_key.page = null;
        self.ida.deinit();
        self.idb.deinit();
    }
};

fn pumpSecuredTestLinks(
    allocator: std.mem.Allocator,
    a: *secured_s2s_link.SecuredLink,
    b: *secured_s2s_link.SecuredLink,
) !void {
    var rounds: usize = 0;
    while (rounds < 64) : (rounds += 1) {
        if (a.outbound().len == 0 and b.outbound().len == 0) return;
        const a_out = try allocator.dupe(u8, a.outbound());
        defer allocator.free(a_out);
        const b_out = try allocator.dupe(u8, b.outbound());
        defer allocator.free(b_out);
        a.clearOutbound();
        b.clearOutbound();
        if (a_out.len != 0) try b.feed(a_out, @as(u64, @intCast(rounds + 21)));
        if (b_out.len != 0) try a.feed(b_out, @as(u64, @intCast(rounds + 21)));
    }
    return error.TestUnexpectedResult;
}

fn copyTestSendQ(allocator: std.mem.Allocator, conn: *const ConnState) ![]u8 {
    const inline_bytes = conn.send_buf[conn.send_offset..conn.send_len];
    const total = try std.math.add(usize, inline_bytes.len, conn.send_overflow.items.len);
    const out = try allocator.alloc(u8, total);
    @memcpy(out[0..inline_bytes.len], inline_bytes);
    @memcpy(out[inline_bytes.len..], conn.send_overflow.items);
    return out;
}

fn resetTestSendQ(conn: *ConnState) void {
    conn.send_len = 0;
    conn.send_offset = 0;
    if (conn.send_overflow.items.len != 0) conn.send_overflow.clearRetainingCapacity();
}

test "secured establishment immediately publishes authenticated trust route" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    var initiator_identity = try node_identity.fromSeed(@as([32]u8, @splat(0x61)), "session-replay-test");
    defer initiator_identity.deinit();
    var responder_identity = try node_identity.fromSeed(@as([32]u8, @splat(0x62)), "session-replay-test");
    defer responder_identity.deinit();
    const initiator_prekey = try initiator_identity.signedPrekey(1, 10, 1000, LinuxServer.s2s_bands, LinuxServer.s2s_features);
    const responder_prekey = try responder_identity.signedPrekey(2, 10, 1000, LinuxServer.s2s_bands, LinuxServer.s2s_features);
    var initiator = try secured_s2s_link.SecuredLink.init(.{
        .allocator = allocator,
        .role = .initiator,
        .identity = &initiator_identity,
        .local_prekey = initiator_prekey,
        .cfg = .{
            .realm = initiator_identity.realm,
            .supported_bands = LinuxServer.s2s_bands,
            .supported_features = LinuxServer.s2s_features,
            .mesh_pass = "session-replay-secret",
            .now_ms = 20,
        },
        .rng = std.testing.io,
        .server_name = "replay-a.test",
    });
    defer initiator.deinit();
    var responder = try secured_s2s_link.SecuredLink.init(.{
        .allocator = allocator,
        .role = .responder,
        .identity = &responder_identity,
        .local_prekey = responder_prekey,
        .cfg = .{
            .realm = responder_identity.realm,
            .supported_bands = LinuxServer.s2s_bands,
            .supported_features = LinuxServer.s2s_features,
            .mesh_pass = "session-replay-secret",
            .now_ms = 20,
        },
        .rng = std.testing.io,
        .server_name = "replay-b.test",
    });
    defer responder.deinit();
    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = responder_identity.shortId(),
        .server_name = "replay-b.test",
        .node_identity = &responder_identity,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const id = try server.rx().clients.alloc(ConnState.init(-1));
    const conn = server.rx().clients.get(id).?;
    conn.overflow_allocator = allocator;
    conn.token = try tokenFromId(id);
    conn.send_armed = true; // retain deterministic handshake output in SendQ
    conn.s2s_secured = &responder;
    defer {
        if (server.rx().clients.get(id)) |live| {
            live.s2s_secured = null; // stack-owned by `pair`
            live.send_armed = false;
            _ = server.rx().clients.free(id);
        }
    }

    var rounds: usize = 0;
    while (!responder.established() and rounds < 64) : (rounds += 1) {
        var progressed = false;
        // A secured responder speaks first with its prekey preamble. Move that
        // output through the daemon SendQ, then return the initiator response
        // through the real secured drive path where establishment publishes.
        if (responder.outbound().len != 0) {
            if (!server.flushMeshBurstStage(conn)) return error.TestUnexpectedResult;
        }
        {
            const to_peer = try copyTestSendQ(allocator, conn);
            defer allocator.free(to_peer);
            resetTestSendQ(conn);
            if (to_peer.len != 0) {
                progressed = true;
                try initiator.feed(to_peer, @intCast(rounds + 21));
            }
        }
        {
            const to_server = try allocator.dupe(u8, initiator.outbound());
            defer allocator.free(to_server);
            initiator.clearOutbound();
            if (to_server.len != 0) {
                progressed = true;
                server.driveS2sSecured(conn, &responder, to_server);
                if (conn.closing) return error.TestUnexpectedResult;
            }
        }
        if (!progressed) return error.TestUnexpectedResult;
    }
    try std.testing.expect(responder.established());

    // No timer/adoption publication is invoked: the establishment transition
    // itself must make the authenticated peer immediately available to SRM2.
    try std.testing.expectEqual(@as(u32, 1), server.net_peer_count.load(.acquire));
    lockSpin(&server.mesh_peer_identity_mu);
    defer server.mesh_peer_identity_mu.unlock();
    try std.testing.expectEqual(@as(usize, 1), server.mesh_published_peers.items.len);
    try std.testing.expectEqual(initiator_identity.shortId(), server.mesh_published_peers.items[0].node_id);
    try std.testing.expect(server.mesh_published_peers.items[0].public_key_present);
    try std.testing.expectEqualSlices(u8, &initiator_identity.sign_kp.public_key, &server.mesh_published_peers.items[0].public_key);
    try std.testing.expectEqualStrings("replay-a.test", server.mesh_published_peers.items[0].name);
}

test "mesh peer-count publish and RTT probe refuse a sibling (non-reactor-0) caller" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .num_shards = 2,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    if (server.reactors.len < 2) return error.SkipZigTest;

    // Seed the shared mesh identity/RTT state as reactor 0 would have already
    // published it, then call both functions with `current_reactor` pinned to
    // reactor 1 — the shard that never holds an S2S link. docs/audit/
    // timer-guard-0.7.md P0-TG-2: neither call may move anything from here,
    // and the RTT throttle specifically must not advance ahead of its guard
    // (guard theft) even though nothing on this shard gets probed.
    current_reactor = &server.reactors[0];
    const seeded_name = "reactor0-peer.test";
    try server.storePublishedMeshPeers(&.{.{ .name = seeded_name }});
    server.last_peer_rtt_probe_ms = 12_345;

    // A connection on the sibling reactor that WOULD be probed and WOULD zero
    // the published peer table if the guard were absent — proves the internal
    // guard, not merely an empty client table on reactor 1, stops the work.
    current_reactor = &server.reactors[1];
    const id = try server.rx().clients.alloc(ConnState.init(-1));
    defer _ = server.rx().clients.free(id);

    server.publishPeerCount();
    server.maybeProbeMeshPeerRtt();

    try std.testing.expectEqualStrings(seeded_name, server.mesh_published_peers.items[0].name);
    try std.testing.expectEqual(@as(u32, 1), server.net_peer_count.load(.acquire));
    try std.testing.expectEqual(@as(i64, 12_345), server.last_peer_rtt_probe_ms);

    // Called from the owning reactor, both are free to act: the stale peer
    // identity is replaced by today's (empty, on this fixture) reactor-0
    // roster, and the RTT throttle legitimately advances.
    current_reactor = &server.reactors[0];
    server.publishPeerCount();
    server.maybeProbeMeshPeerRtt();
    try std.testing.expectEqual(@as(u32, 0), server.net_peer_count.load(.acquire));
    try std.testing.expectEqual(@as(usize, 0), server.mesh_published_peers.items.len);
    try std.testing.expect(server.last_peer_rtt_probe_ms != 12_345);
}

test "published mesh peers grow past the old 32 by 64 ceiling" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x5c)), "growth.test");
    defer ident.deinit();
    server.config.node_identity = &ident;

    var long_name: [200]u8 = @splat('n');
    long_name[0] = 'P';
    const key: [crypto_sign.public_key_len]u8 = @splat(0xab);
    const origin = ident.shortId() +% 1;

    var name_buf: [39][8]u8 = undefined;
    var rows: [40]MeshPeerSeen = undefined;
    for (0..39) |i| {
        const n = std.fmt.bufPrint(&name_buf[i], "p{d:0>3}", .{i}) catch unreachable;
        rows[i] = .{ .name = n };
    }
    rows[39] = .{
        .name = &long_name,
        .node_id = origin,
        .public_key = key,
        .public_key_present = true,
    };
    try server.storePublishedMeshPeers(&rows);

    const snap = try server.readPeerNames();
    defer snap.deinit();
    try std.testing.expectEqual(@as(usize, 40), snap.count);
    try std.testing.expectEqual(@as(u32, 40), server.net_peer_count.load(.acquire));
    try std.testing.expectEqualStrings("p000", snap.name(0));
    try std.testing.expectEqualStrings(&long_name, snap.name(39));
    try std.testing.expectEqual(@as(usize, 200), server.mesh_published_peers.items[39].name.len);

    const signed = session_reclaim_attachment.SignedClaim{
        .claim = .{
            .kind = .create_new,
            .account = "",
            .group_token = @splat(0),
            .attachment_id = .{ .raw = @splat(0) },
            .origin_node = 0,
            .destination_node = 0,
            .issued_at_ms = 0,
            .expires_at_ms = 0,
            .nonce = 0,
        },
        .signer = key,
        .signature = @splat(0),
        .transcript = &.{},
        .wire = &.{},
    };
    const route = server.trustedReclaimRoute(origin, signed) orelse return error.TestUnexpectedResult;
    defer switch (route) {
        .local => {},
        .remote => |remote| allocator.free(remote.name),
    };
    switch (route) {
        .local => return error.TestUnexpectedResult,
        .remote => |remote| try std.testing.expectEqualStrings(&long_name, remote.slice()),
    }
}

test "stats_peak_clients counts registered clients across shards" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const dir = try rehashTmpPath(allocator, tmp, ".");
    defer allocator.free(dir);

    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .num_shards = 2,
        .stats_web_dir = dir,
        .crypto_io = std.testing.io,
        .stats_interval_ms = 1,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    if (server.reactors.len < 2) return error.SkipZigTest;

    current_reactor = &server.reactors[0];
    const a_id = try addTestLocalClient(&server, "Alice", "alice");
    server.connFor(a_id).?.session.registration.registered = true;

    current_reactor = &server.reactors[1];
    const b_id = try addTestLocalClient(&server, "Bob", "bob");
    server.connFor(b_id).?.session.registration.registered = true;

    const rendered = server.tallyRegisteredLocalClients();
    try std.testing.expectEqual(@as(u64, 2), rendered.clients);
    try std.testing.expectEqual(@as(usize, 1), server.reactors[0].clients.len());
    try std.testing.expectEqual(@as(usize, 1), server.reactors[1].clients.len());

    // Peak is raised on the web-stats path from the all-shard tally, not
    // from `rx().clients` (which here is shard 1 only).
    server.maybeWriteStats();
    try std.testing.expectEqual(@as(u64, 2), server.stats_peak_clients);
}

fn gapA11HoldOtherCadences(server: *Server) void {
    const held = server.nowMs() + 3_600_000;
    server.last_oper_grant_refresh_ms = held;
    server.last_session_replica_refresh_ms = held;
    server.last_session_attachment_lease_refresh_ms = held;
    server.last_peer_rtt_probe_ms = held;
}

fn gapA11QueuedWire(allocator: std.mem.Allocator, conn: *const ConnState) ![]u8 {
    const inline_bytes = conn.send_buf[conn.send_offset..conn.send_len];
    const out = try allocator.alloc(u8, inline_bytes.len + conn.send_overflow.items.len);
    @memcpy(out[0..inline_bytes.len], inline_bytes);
    @memcpy(out[inline_bytes.len..], conn.send_overflow.items);
    return out;
}

fn gapA11ClearQueued(conn: *ConnState) void {
    conn.send_len = 0;
    conn.send_offset = 0;
    conn.send_overflow.clearRetainingCapacity();
}

fn gapA11RosterHas(members: []const s2s_peer_mod.MemberInfo, nick: []const u8) bool {
    for (members) |member| {
        if (std.mem.eql(u8, member.nick, nick)) return true;
    }
    return false;
}

test "DST GAP-A11 maintenance reactor re-bursts the local roster on the membership interval" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    var left = try SessionReplayTestPair.initWithSeeds(allocator, 0xA1, 0xA2);
    defer left.deinit();
    var right = try SessionReplayTestPair.initWithSeeds(allocator, 0xA3, 0xA4);
    defer right.deinit();
    left.a.clearOutbound();
    left.b.clearOutbound();
    right.a.clearOutbound();
    right.b.clearOutbound();

    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .num_shards = 2,
        .node_id = left.ida.shortId(),
        .server_name = "reburs-home.test",
        .node_identity = &left.ida,
        .crypto_io = std.testing.io,
        .mesh_pass = "session-replay-secret",
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    if (server.reactors.len < 2) return error.SkipZigTest;
    current_reactor = &server.reactors[0];

    const alice = try addTestLocalClient(&server, "ReburstA", null);
    const bob = try addTestLocalClient(&server, "ReburstB", null);
    _ = try server.world.join("#reburs", worldIdFromClient(alice));
    _ = try server.world.join("#reburs", worldIdFromClient(bob));
    server.connFor(alice).?.session.registration.registered = true;
    server.connFor(bob).?.session.registration.registered = true;
    const fresh_activity = server.nowMs();
    server.connFor(alice).?.last_activity_ms = fresh_activity;
    server.connFor(bob).?.last_activity_ms = fresh_activity;

    const left_id = try server.rx().clients.alloc(ConnState.init(-1));
    const left_peer = server.rx().clients.get(left_id).?;
    left_peer.overflow_allocator = allocator;
    left_peer.token = try tokenFromId(left_id);
    left_peer.send_armed = true;
    left_peer.sendq_cap = default_sendq_cap;
    left_peer.s2s_secured = &left.a;
    left_peer.s2s_burst_done = true;
    const right_id = try server.rx().clients.alloc(ConnState.init(-1));
    const right_peer = server.rx().clients.get(right_id).?;
    right_peer.overflow_allocator = allocator;
    right_peer.token = try tokenFromId(right_id);
    right_peer.send_armed = true;
    right_peer.sendq_cap = default_sendq_cap;
    right_peer.s2s_secured = &right.a;
    right_peer.s2s_burst_done = true;
    defer {
        left_peer.s2s_secured = null;
        right_peer.s2s_secured = null;
        _ = server.rx().clients.free(left_id);
        _ = server.rx().clients.free(right_id);
    }

    // Inside the interval, reactor 0 does not copy the world.
    gapA11HoldOtherCadences(&server);
    server.last_membership_resync_ms = server.nowMs();
    const quiet = server.last_membership_resync_ms;
    gapA11ClearQueued(left_peer);
    gapA11ClearQueued(right_peer);
    server.onTimerTick();
    try std.testing.expectEqual(quiet, server.last_membership_resync_ms);
    try std.testing.expectEqual(@as(usize, 0), left_peer.send_len);
    try std.testing.expectEqual(@as(usize, 0), right_peer.send_len);

    // A sibling reactor must not consume the shared interval or emit the copy.
    server.last_membership_resync_ms = server.nowMs() - membership_resync_interval_ms;
    const planted = server.last_membership_resync_ms;
    current_reactor = &server.reactors[1];
    server.onTimerTick();
    try std.testing.expectEqual(planted, server.last_membership_resync_ms);
    try std.testing.expectEqual(@as(usize, 0), left_peer.send_len);
    try std.testing.expectEqual(@as(usize, 0), right_peer.send_len);

    // Reactor 0 copies the whole local roster to every established peer.
    current_reactor = &server.reactors[0];
    gapA11HoldOtherCadences(&server);
    server.onTimerTick();
    try std.testing.expect(server.last_membership_resync_ms != planted);
    const left_wire = try gapA11QueuedWire(allocator, left_peer);
    defer allocator.free(left_wire);
    const right_wire = try gapA11QueuedWire(allocator, right_peer);
    defer allocator.free(right_wire);
    try std.testing.expect(left_wire.len > 0);
    try std.testing.expect(right_wire.len > 0);
    const fed_at: u64 = @intCast(@max(@as(i64, 0), server.nowMs()));
    try left.b.feed(left_wire, fed_at);
    left.b.processDeferredResidenceFrames(fed_at);
    server.discardIdentityTransitions(&left.b);
    try right.b.feed(right_wire, fed_at);
    right.b.processDeferredResidenceFrames(fed_at);
    server.discardIdentityTransitions(&right.b);
    const left_members = left.b.channelMembers("#reburs");
    const right_members = right.b.channelMembers("#reburs");
    try std.testing.expectEqual(@as(usize, 2), left_members.len);
    try std.testing.expectEqual(@as(usize, 2), right_members.len);
    try std.testing.expect(gapA11RosterHas(left_members, "ReburstA"));
    try std.testing.expect(gapA11RosterHas(left_members, "ReburstB"));
    try std.testing.expect(gapA11RosterHas(right_members, "ReburstA"));
    try std.testing.expect(gapA11RosterHas(right_members, "ReburstB"));

    // A later tick inside the same interval does not copy the world again.
    const stamped = server.last_membership_resync_ms;
    gapA11HoldOtherCadences(&server);
    gapA11ClearQueued(left_peer);
    gapA11ClearQueued(right_peer);
    server.onTimerTick();
    try std.testing.expectEqual(stamped, server.last_membership_resync_ms);
    try std.testing.expectEqual(@as(usize, 0), left_peer.send_len);
    try std.testing.expectEqual(@as(usize, 0), right_peer.send_len);
}

