            .now_ms = 20,
        },
        .rng = std.testing.io,
        .server_name = "aaa.test",
    });
    defer replacement.deinit();

    var sim_time = reactor_mod.SimReactor.init(20_000);
    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .server_name = "aaa.test",
        .node_id = local_identity.shortId(),
        .node_identity = &local_identity,
        .crypto_io = std.testing.io,
        .reactor = sim_time.reactor(),
        .ping_timeout_ms = 100,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    var old_socket: [2]linux.fd_t = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &old_socket)) != .SUCCESS)
        return error.SkipZigTest;
    defer closeFd(old_socket[1]);
    const old_id = try server.rx().clients.alloc(ConnState.init(old_socket[0]));
    const old_conn = server.rx().clients.get(old_id).?;
    old_conn.overflow_allocator = allocator;
    old_conn.token = try tokenFromId(old_id);
    old_conn.s2s_secured = old_local;
    old_local_owned_by_server = true;
    old_conn.s2s_initiator = true;
    old_conn.awaiting_pong = true;
    old_conn.ping_sent_ms = sim_time.clock_ms - server.config.ping_timeout_ms - 1;
    // Model the SQ-pressure gap the old teardown used to orphan: activation is
    // pending, but no kernel operation owns inline ConnState storage.
    old_conn.io_activation_pending = true;
    old_conn.activation_recv_required = true;
    server.noteS2sTcpOpened(old_conn);
    server.noteS2sEstablished(old_conn, old_local.remoteName(), "secured-test-old");

    const replacement_id = try server.rx().clients.alloc(ConnState.init(-1));
    const replacement_conn = server.rx().clients.get(replacement_id).?;
    replacement_conn.overflow_allocator = allocator;
    replacement_conn.token = try tokenFromId(replacement_id);
    replacement_conn.s2s_secured = &replacement;
    replacement_conn.s2s_initiator = false;
    replacement_conn.send_armed = true;
    server.noteS2sTcpOpened(replacement_conn);
    defer {
        if (server.rx().clients.get(old_id)) |live| {
            // Failure-only cleanup: on success collision teardown already freed
            // this heap-owned link and its socket.
            live.s2s_secured = null;
            closeFd(live.fd);
            _ = server.rx().clients.free(old_id);
            old_local.deinit();
            allocator.destroy(old_local);
            old_local_owned_by_server = false;
        }
        if (server.rx().clients.get(replacement_id)) |live| {
            live.s2s_secured = null;
            live.send_armed = false;
        }
        _ = server.rx().clients.free(replacement_id);
    }

    var rounds: usize = 0;
    while (!replacement.established() and rounds < 64) : (rounds += 1) {
        var progressed = false;
        if (replacement.outbound().len != 0) {
            if (!server.flushMeshBurstStage(replacement_conn)) return error.TestUnexpectedResult;
        }
        {
            const to_remote = try copyTestSendQ(allocator, replacement_conn);
            defer allocator.free(to_remote);
            resetTestSendQ(replacement_conn);
            if (to_remote.len != 0) {
                progressed = true;
                try remote.feed(to_remote, @intCast(rounds + 21));
            }
        }
        {
            const to_server = try allocator.dupe(u8, remote.outbound());
            defer allocator.free(to_server);
            remote.clearOutbound();
            if (to_server.len != 0) {
                progressed = true;
                server.driveS2sSecured(replacement_conn, &replacement, to_server);
                if (replacement_conn.closing) return error.TestUnexpectedResult;
            }
        }
        if (!progressed) return error.TestUnexpectedResult;
    }

    try std.testing.expect(replacement.established());
    // The stale predecessor had no armed CQE to wake. Replacement must therefore
    // finalize it synchronously instead of orphaning an activation-pending slot.
    try std.testing.expect(server.rx().clients.get(old_id) == null);
    try std.testing.expect(!replacement_conn.closing);
    try std.testing.expectEqual(@as(u32, 1), server.net_peer_count.load(.acquire));
    try std.testing.expectEqualStrings("replay-b.test", server.mesh_published_peers.items[0].name);
    var metrics: std.ArrayList(u8) = .empty;
    defer metrics.deinit(allocator);
    try server.stats.writePrometheus(allocator, &metrics);
    try std.testing.expect(std.mem.indexOf(u8, metrics.items, "onyx_s2s_tcp_active 1\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, metrics.items, "onyx_s2s_links_active 1\n") != null);
}

test "secured collision scan passes stale loser before resolving viable route" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    var stale_pair = try SessionReplayTestPair.initWithSeeds(allocator, 0x71, 0x76);
    defer stale_pair.deinit();
    var viable_pair = try SessionReplayTestPair.initWithSeeds(allocator, 0x73, 0x76);
    defer viable_pair.deinit();
    var new_pair = try SessionReplayTestPair.initWithSeeds(allocator, 0x75, 0x76);
    defer new_pair.deinit();
    var sim_time = reactor_mod.SimReactor.init(30_000);
    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .server_name = "aaa.test",
        .reactor = sim_time.reactor(),
        .ping_timeout_ms = 100,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const stale_id = try server.rx().clients.alloc(ConnState.init(-1));
    const stale = server.rx().clients.get(stale_id).?;
    stale.token = try tokenFromId(stale_id);
    stale.s2s_secured = &stale_pair.a;
    stale.s2s_initiator = false;
    stale.recv_armed = true;
    stale.awaiting_pong = true;
    stale.ping_sent_ms = sim_time.clock_ms - server.config.ping_timeout_ms - 1;

    const viable_id = try server.rx().clients.alloc(ConnState.init(-1));
    const viable = server.rx().clients.get(viable_id).?;
    viable.token = try tokenFromId(viable_id);
    viable.s2s_secured = &viable_pair.a;
    viable.s2s_initiator = false;
    viable.recv_armed = true;

    const new_id = try server.rx().clients.alloc(ConnState.init(-1));
    const new_conn = server.rx().clients.get(new_id).?;
    new_conn.token = try tokenFromId(new_id);
    new_conn.s2s_secured = &new_pair.a;
    new_conn.s2s_initiator = true; // preferred direction for aaa.test
    defer {
        for ([_]client_model.ClientId{ stale_id, viable_id, new_id }) |id| {
            if (server.rx().clients.get(id)) |live| {
                live.s2s_secured = null;
                live.recv_armed = false;
                _ = server.rx().clients.free(id);
            }
        }
    }

    try std.testing.expect(!server.resolveS2sCollision(new_conn, "replay-b.test"));
    try std.testing.expect(stale.closing);
    try std.testing.expect(stale.s2s_dedup);
    try std.testing.expect(viable.closing);
    try std.testing.expect(viable.s2s_dedup);
    try std.testing.expect(!new_conn.closing);
    try std.testing.expect(!new_conn.s2s_dedup);
}

test "client active gauge follows physical slot ownership through close and refusal" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    const server = createTestServer(allocator, .{ .host = "127.0.0.1", .port = 0, .crypto_io = std.testing.io }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer {
        server.deinit();
        std.testing.allocator.destroy(server);
    }
    current_reactor = &server.reactors[0];

    var live_pair: [2]i32 = undefined;
    if (posix.errno(socket_system.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &live_pair)) != .SUCCESS)
        return error.SkipZigTest;
    defer closeFd(live_pair[1]);
    const live_id = try server.rx().clients.alloc(ConnState.init(live_pair[0]));
    const live = server.rx().clients.get(live_id).?;
    live.overflow_allocator = allocator;
    live.token = try tokenFromId(live_id);
    try std.testing.expect(try server.startAcceptedPlain(live, false));
    // Re-entering an admission helper must not double-own the gauge.
    server.noteClientAccepted(live);

    var metrics: std.ArrayList(u8) = .empty;
    defer metrics.deinit(allocator);
    try server.stats.writePrometheus(allocator, &metrics);
    try std.testing.expect(std.mem.indexOf(u8, metrics.items, "onyx_connections_active 1\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, metrics.items, "onyx_connections_total 1\n") != null);

    // A slot that never acquired gauge ownership (for example, an older
    // pre-admission error path) must not subtract some other live connection.
    var uncounted_pair: [2]i32 = undefined;
    if (posix.errno(socket_system.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &uncounted_pair)) != .SUCCESS)
        return error.SkipZigTest;
    defer closeFd(uncounted_pair[1]);
    const uncounted_id = try server.rx().clients.alloc(ConnState.init(uncounted_pair[0]));
    const uncounted = server.rx().clients.get(uncounted_id).?;
    uncounted.overflow_allocator = allocator;
    uncounted.token = try tokenFromId(uncounted_id);
    try server.closeConn(uncounted.token, "uncounted gauge test close");
    metrics.clearRetainingCapacity();
    try server.stats.writePrometheus(allocator, &metrics);
    try std.testing.expect(std.mem.indexOf(u8, metrics.items, "onyx_connections_active 1\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, metrics.items, "onyx_connections_total 1\n") != null);

    try server.closeConn(live.token, "gauge test close");
    metrics.clearRetainingCapacity();
    try server.stats.writePrometheus(allocator, &metrics);
    try std.testing.expect(std.mem.indexOf(u8, metrics.items, "onyx_connections_active 0\n") != null);

    var refused_pair: [2]i32 = undefined;
    if (posix.errno(socket_system.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &refused_pair)) != .SUCCESS)
        return error.SkipZigTest;
    defer closeFd(refused_pair[1]);
    server.draining = true;
    try server.handleAccept(.{ .token = tls_listener_token, .res = refused_pair[0], .more = false });
    try std.testing.expectEqual(@as(usize, 0), server.rx().clients.len());

    metrics.clearRetainingCapacity();
    try server.stats.writePrometheus(allocator, &metrics);
    try std.testing.expect(std.mem.indexOf(u8, metrics.items, "onyx_connections_active 0\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, metrics.items, "onyx_connections_total 2\n") != null);
}

test "non-dedup S2S close immediately removes published peer" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    var server = Server.init(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    var sender: s2s_link.S2sLink = undefined;
    try sender.init(.{
        .allocator = allocator,
        .local_node_id = 71,
        .remote_node_id = 72,
        .local_epoch_ms = 100,
        .server_name = "closing-peer.test",
        .config = .{ .require_signed_frames = false },
    });
    defer sender.deinit();
    const receiver = try allocator.create(s2s_link.S2sLink);
    var receiver_owned_by_server = false;
    try receiver.init(.{
        .allocator = allocator,
        .local_node_id = 72,
        .remote_node_id = 71,
        .local_epoch_ms = 101,
        .server_name = "local.test",
        .config = .{ .require_signed_frames = false },
    });
    errdefer if (!receiver_owned_by_server) {
        receiver.deinit();
        allocator.destroy(receiver);
    };
    try sender.start(102);
    try pumpLinkPair(&sender, receiver, allocator);
    try std.testing.expect(receiver.established());

    const id = try server.rx().clients.alloc(ConnState.init(-1));
    const conn = server.rx().clients.get(id).?;
    conn.overflow_allocator = allocator;
    conn.token = try tokenFromId(id);
    conn.s2s = receiver; // closeConn owns the heap link from here
    receiver_owned_by_server = true;
    server.publishPeerCount();
    try std.testing.expectEqual(@as(u32, 1), server.net_peer_count.load(.acquire));
    const before_close = try server.readPeerNames();
    defer before_close.deinit();
    try std.testing.expectEqualStrings("closing-peer.test", before_close.name(0));

    try server.closeConn(conn.token, "test peer close");
    try std.testing.expect(server.rx().clients.get(id) == null);
    try std.testing.expectEqual(@as(u32, 0), server.net_peer_count.load(.acquire));
    try std.testing.expectEqual(@as(usize, 0), server.mesh_published_peers.items.len);
    // Caller-owned copy remains stable after the shared same/zero-count rewrite.
    try std.testing.expectEqualStrings("closing-peer.test", before_close.name(0));
}

test "session replica live publication pairs a newer lease and detached publication invalidates it" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x6a)), "lease-publisher.test");
    defer ident.deinit();
    var server = LinuxServer.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = ident.shortId(),
        .server_name = "lease-publisher.test",
        .node_identity = &ident,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const token: session_migrate.Token = @splat(0x6a);
    _ = try server.sessions.attach("alice", 1, token, 1);
    try std.testing.expect(server.sessions.markPortableResumeIssued("alice", 1));
    try std.testing.expect(server.publishSessionReplicaUpsert(token, "alice", "Alice", "attached", true));
    const offer = server.session_replica_store.getOrigin(token, ident.shortId()).?;
    const lease = server.session_replica_store.getAttachmentLease(token, ident.shortId()).?;
    try std.testing.expect(lease.revision.compare(offer.revision) == .gt);
    try std.testing.expect(server.session_replica_store.hasAttachedOriginOtherThan(token, 999, lease.issued_at_ms));

    // A detached snapshot advances the OFFER without a positive proof. The old
    // lease remains only as a replay floor and cannot suppress final QUIT.
    try std.testing.expect(server.sessions.markDetachedWithSnapshot("alice", 1, "detached"));
    try std.testing.expect(server.publishSessionReplicaUpsert(token, "alice", "Alice", "detached", false));
    const detached_offer = server.session_replica_store.getOrigin(token, ident.shortId()).?;
    try std.testing.expect(detached_offer.revision.compare(lease.revision) == .gt);
    try std.testing.expect(!server.session_replica_store.hasAttachedOriginOtherThan(token, 999, lease.issued_at_ms));
    try std.testing.expect(!server.publishSessionAttachmentLease(token));

    // A newly attached portable sibling re-enables lease minting at the exact
    // SessionStore boundary; arbitrary direct callers cannot do so while every
    // row is detached.
    _ = try server.sessions.attach("alice", 2, token, 2);
    try std.testing.expect(server.sessions.markPortableResumeIssued("alice", 2));
    try std.testing.expect(server.publishSessionAttachmentLease(token));
    const renewed = server.session_replica_store.getAttachmentLease(token, ident.shortId()).?;
    try std.testing.expect(renewed.revision.compare(detached_offer.revision) == .gt);
    try std.testing.expect(server.session_replica_store.hasAttachedOriginOtherThan(token, 999, renewed.issued_at_ms));
    try std.testing.expect(server.session_replica_store.hasAttachedOriginOtherThan(token, 999, renewed.expires_at_ms + 1));
    try std.testing.expect(!server.session_replica_store.hasAttachedOriginOtherThan(token, 999, detached_offer.expires_at_ms + 1));

    // Detaching one sibling while another exact-token portable attachment
    // survives must advance both OFFER and lease, not create a false-offline.
    _ = try server.sessions.attach("alice", 3, token, 3);
    try std.testing.expect(server.sessions.markPortableResumeIssued("alice", 3));
    try std.testing.expect(server.sessions.markDetachedWithSnapshot("alice", 2, "sibling-detached"));
    try std.testing.expect(server.sessions.tokenHasAttachedPortable(token));
    try std.testing.expect(server.publishSessionReplicaUpsert(
        token,
        "alice",
        "Alice",
        "surviving-sibling",
        server.sessions.tokenHasAttachedPortable(token),
    ));
    const sibling_offer = server.session_replica_store.getOrigin(token, ident.shortId()).?;
    const sibling_lease = server.session_replica_store.getAttachmentLease(token, ident.shortId()).?;
    try std.testing.expect(sibling_lease.revision.compare(sibling_offer.revision) == .gt);
    try std.testing.expect(server.session_replica_store.hasAttachedOriginOtherThan(token, 999, sibling_lease.issued_at_ms));
}

test "DST GAP-A10 late lease refresh does not emit QUIT while the session is live" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var home = try node_identity.fromSeed(@as([32]u8, @splat(0x81)), "late-lease-home.test");
    defer home.deinit();
    var remote = try node_identity.fromSeed(@as([32]u8, @splat(0x82)), "late-lease-remote.test");
    defer remote.deinit();
    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = home.shortId(),
        .node_identity = &home,
        .server_name = "late-lease-home.test",
        .crypto_io = std.testing.io,
        .session_migrate_on_detach = true,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const id = try addTestLocalClient(&server, "RemoteLive", "remote-acct");
    const conn = server.connFor(id).?;
    const token = server.sessions.resumeHandleForClient("remote-acct", monitorIdFromClient(id)).?.token;
    try std.testing.expect(server.sessions.markPortableResumeIssued("remote-acct", monitorIdFromClient(id)));
    try server.world.restoreMember("#late-lease", worldIdFromClient(id), world_model.MemberModes.empty());
    const observer_id = try addTestLocalClient(&server, "Observer", null);
    const observer = server.connFor(observer_id).?;
    try server.world.restoreMember("#late-lease", worldIdFromClient(observer_id), world_model.MemberModes.empty());

    const now: i64 = @intCast(@min(server.meshWallMs(), @as(u64, std.math.maxInt(i64) - 3_600_000)));
    const physical: u64 = @intCast(now);
    const origin = message_relay.originShortId(remote.sign_kp.public_key);
    const snapshot = try (migration_relay.Snapshot{
        .nick = "RemoteLive",
        .umodes = "+i",
        .channels = &.{},
        .channel_modes = &.{},
        .account = "remote-acct",
    }).encode(allocator);
    defer allocator.free(snapshot);

    const offer_epoch = physical - 2_000;
    const offer_wire = try session_replica_v2.encodeOffer(allocator, .{
        .operation = .upsert,
        .token = token,
        .revision = .{
            .epoch = offer_epoch,
            .sequence = (offer_epoch << mesh_clock_mod.seq_bits) | 1,
            .origin_node = origin,
        },
        .issued_at_ms = now - 2_000,
        .expires_at_ms = now + 3_600_000,
        .account = "remote-acct",
        .nick = "RemoteLive",
        .snapshot = snapshot,
    }, &remote.sign_kp);
    defer allocator.free(offer_wire);
    const offered = try server.session_replica_store.applySignedOffer(
        try session_replica_v2.decodeOffer(offer_wire),
        origin,
        now,
    );
    try std.testing.expectEqual(session_replica_v2.ApplyDisposition.inserted, offered.disposition);

    const lease_epoch = physical - 1_000;
    const lease_wire = try session_replica_v2.encodeAttachmentLease(allocator, .{
        .token = token,
        .revision = .{
            .epoch = lease_epoch,
            .sequence = (lease_epoch << mesh_clock_mod.seq_bits) | 2,
            .origin_node = origin,
        },
        .issued_at_ms = now - 1_000,
        .expires_at_ms = now - 1,
    }, &remote.sign_kp);
    defer allocator.free(lease_wire);
    try std.testing.expectEqual(
        session_replica_v2.AttachmentLeaseDisposition.inserted,
        try server.session_replica_store.applySignedAttachmentLease(
            try session_replica_v2.decodeAttachmentLease(lease_wire),
            now,
        ),
    );

    try std.testing.expect(server.connHasExactRemoteSessionAuthority(id, conn));
    var quit_line = try irc_line.parseLine("QUIT :partition blip");
    try server.handleQuit(id, conn, &quit_line);
    try std.testing.expect(server.world.nickOf(worldIdFromClient(id)) != null);
    try std.testing.expect(std.mem.indexOf(u8, observer.send_buf[0..observer.send_len], " QUIT ") == null);

    const live_offer = server.session_replica_store.getOrigin(token, origin) orelse return error.TestUnexpectedResult;
    try std.testing.expect(!server.session_replica_store.hasAttachedOriginOtherThan(
        token,
        server.config.node_id,
        live_offer.expires_at_ms + 1,
    ));
}

const GapA3Roster = struct {
    peer: s2s_peer_mod.S2sPeer,
    state: *s2s_peer_mod.ChannelCrdt,

    fn deinit(self: *@This()) void {
        self.peer.deinit();
        self.state.deinit();
        std.testing.allocator.destroy(self.state);
    }
};

/// Handshake a secured SESSION_REPLICA_V2 link and apply one MEMBERSHIP through
/// `server.residenceVerifier`. `prime_node == 0` starts from an empty roster.
/// A non-zero prime is the Helix-restored holder already on this link: the
/// new frame still arrives through `sendMembership`, and trust is the verifier's.
fn gapA3Exchange(
    server: *LinuxServer,
    now_ms: *u64,
    sender_seed: [sign_mod.seed_len]u8,
    observer_seed: [sign_mod.seed_len]u8,
    channel: []const u8,
    nick: []const u8,
    account: []const u8,
    hlc: u64,
    prime_node: u64,
    prime_hlc: u64,
    prime_account: []const u8,
    prime_trusted: bool,
) !GapA3Roster {
    const allocator = std.testing.allocator;
    var sender_kp = try sign_mod.KeyPair.fromSeed(sender_seed);
    var observer_kp = try sign_mod.KeyPair.fromSeed(observer_seed);
    const sender_node = message_relay.originShortId(sender_kp.public_key);
    const observer_node = message_relay.originShortId(observer_kp.public_key);
    if (sender_node == 0 or observer_node == 0 or sender_node == observer_node) {
        sender_kp.deinit();
        observer_kp.deinit();
        return error.TestUnexpectedResult;
    }

    const sender_state = try allocator.create(s2s_peer_mod.ChannelCrdt);
    sender_state.* = s2s_peer_mod.ChannelCrdt.init(allocator, sender_node);
    const receiver_state = try allocator.create(s2s_peer_mod.ChannelCrdt);
    receiver_state.* = s2s_peer_mod.ChannelCrdt.init(allocator, observer_node);

    var sender = initServerTestPeer(sender_state, now_ms, sender_kp, observer_node, 1000, "a3-origin.test", true) catch |err| {
        sender_kp.deinit();
        observer_kp.deinit();
        sender_state.deinit();
        receiver_state.deinit();
        allocator.destroy(sender_state);
        allocator.destroy(receiver_state);
        return err;
    };
    var receiver = initServerTestPeer(receiver_state, now_ms, observer_kp, sender_node, 2000, "a3-obs.test", true) catch |err| {
        observer_kp.deinit();
        sender.deinit();
        sender_state.deinit();
        receiver_state.deinit();
        allocator.destroy(sender_state);
        allocator.destroy(receiver_state);
        return err;
    };

    var failed = true;
    defer {
        if (failed) {
            sender.deinit();
            receiver.deinit();
            sender_state.deinit();
            receiver_state.deinit();
            allocator.destroy(sender_state);
            allocator.destroy(receiver_state);
        }
    }

    receiver.setResidenceVerifier(server.residenceVerifier());
    var to_receiver = ServerPeerTestBuffer{};
    defer to_receiver.deinit();
    var to_sender = ServerPeerTestBuffer{};
    defer to_sender.deinit();
    try sender.startHandshake(to_receiver.sink());
    try receiver.startHandshake(to_sender.sink());
    try pumpServerTestPeers(&sender, &receiver, &to_receiver, &to_sender, now_ms.*, 0xA310);
    try std.testing.expect(receiver.supportsSessionReplicaV2());

    if (prime_node != 0) {
        const primed_at: i64 = @intCast(@min(now_ms.*, @as(u64, std.math.maxInt(i64))));
        _ = try receiver.routes.applyMembership(channel, nick, prime_node, 0, prime_hlc, true, .{
            .username = "u",
            .realname = "r",
            .host = "held.test",
            .account = prime_account,
            .account_trusted = prime_trusted,
        }, primed_at);
    }

    try sender.sendMembership(to_receiver.sink(), channel, nick, 0, hlc, true, .{
        .username = "u",
        .realname = "r",
        .host = "origin.test",
        .account = account,
    }, "");
    try pumpServerTestPeers(&sender, &receiver, &to_receiver, &to_sender, now_ms.*, 0xA311);
    // v2 links hold MEMBERSHIP until the daemon has committed this feed's
    // authority. The offers were already applied; this is that commit point.
    receiver.processDeferredResidenceFrames(now_ms.*);

    sender.deinit();
    sender_state.deinit();
    allocator.destroy(sender_state);
    failed = false;
    return .{ .peer = receiver, .state = receiver_state };
}

test "DST GAP-A3 replica residence keeps two honest nicks and UID-renames a forged account" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var home = try node_identity.fromSeed(@as([32]u8, @splat(0xA3)), "a3-third.test");
    defer home.deinit();
    var origin_a = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0xA4)));
    defer origin_a.deinit();
    var origin_b = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0xA5)));
    defer origin_b.deinit();
    var origin_c = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0xA6)));
    defer origin_c.deinit();
    const node_a = message_relay.originShortId(origin_a.public_key);
    const node_b = message_relay.originShortId(origin_b.public_key);
    const node_c = message_relay.originShortId(origin_c.public_key);
    if (node_a == 0 or node_b == 0 or node_c == 0 or node_a == node_b or node_a == node_c or node_b == node_c) {
        return error.TestUnexpectedResult;
    }

    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = home.shortId(),
        .node_identity = &home,
        .server_name = "a3-third.test",
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const token_a: session_migrate.Token = @splat(0xA3);
    const token_b: session_migrate.Token = @splat(0xA4);
    try applyTestRemoteSessionReplica(&server, &origin_a, token_a, "alice", "alice", 1);
    try applyTestRemoteSessionReplica(&server, &origin_b, token_b, "alice", "alice", 2);

    try std.testing.expectEqual(
        s2s_link.S2sLink.ResidenceDecision.trusted,
        LinuxServer.residenceTrusted(&server, "alice", "alice", node_a, true),
    );
    try std.testing.expectEqual(
        s2s_link.S2sLink.ResidenceDecision.trusted,
        LinuxServer.residenceTrusted(&server, "ALICE", "Alice", node_b, true),
    );
    try std.testing.expectEqual(
        s2s_link.S2sLink.ResidenceDecision.untrusted,
        LinuxServer.residenceTrusted(&server, "alice", "alice", node_c, true),
    );
    try std.testing.expectEqual(
        s2s_link.S2sLink.ResidenceDecision.reject,
        LinuxServer.residenceTrusted(&server, "mallory", "alice", node_a, true),
    );
    try std.testing.expectEqual(
        s2s_link.S2sLink.ResidenceDecision.untrusted,
        LinuxServer.residenceTrusted(&server, "", "alice", node_a, true),
    );
    try std.testing.expectEqual(
        s2s_link.S2sLink.ResidenceDecision.reject,
        LinuxServer.residenceTrusted(&server, "alice", "alice", node_a, false),
    );

    // The secured link applies MEMBERSHIP itself. Trust comes from the signed
    // replica offers above via residenceVerifier, then resolveIncomingNick.
    var now_ms: u64 = 50_000;
    var roster_a = try gapA3Exchange(&server, &now_ms, @as([sign_mod.seed_len]u8, @splat(0xA4)), @as([sign_mod.seed_len]u8, @splat(0xB3)), "#a3", "alice", "alice", 100, 0, 0, "", false);
    defer roster_a.deinit();
    const admitted_a = roster_a.peer.channelMembers("#a3");
    try std.testing.expectEqual(@as(usize, 1), admitted_a.len);
    try std.testing.expectEqualStrings("alice", admitted_a[0].nick);
    try std.testing.expectEqualStrings("alice", admitted_a[0].account);
    try std.testing.expect(admitted_a[0].account_trusted);
    try std.testing.expectEqual(node_a, admitted_a[0].node);
    const held_trusted = admitted_a[0].account_trusted;

    var roster_b = try gapA3Exchange(&server, &now_ms, @as([sign_mod.seed_len]u8, @splat(0xA5)), @as([sign_mod.seed_len]u8, @splat(0xB4)), "#a3", "alice", "alice", 200, node_a, 100, "alice", held_trusted);
    defer roster_b.deinit();
    const admitted_b = roster_b.peer.channelMembers("#a3");
    try std.testing.expectEqual(@as(usize, 1), admitted_b.len);
    try std.testing.expectEqualStrings("alice", admitted_b[0].nick);
    try std.testing.expect(admitted_b[0].account_trusted);
    try std.testing.expectEqual(node_b, admitted_b[0].node);

    var roster_c = try gapA3Exchange(&server, &now_ms, @as([sign_mod.seed_len]u8, @splat(0xA6)), @as([sign_mod.seed_len]u8, @splat(0xB5)), "#a3", "alice", "alice", 9_000, node_a, 100, "alice", held_trusted);
    defer roster_c.deinit();
    const admitted_c = roster_c.peer.channelMembers("#a3");
    var saw_honest = false;
    var saw_forged = false;
    for (admitted_c) |member| {
        if (member.node == node_a) {
            saw_honest = true;
            try std.testing.expectEqualStrings("alice", member.nick);
            try std.testing.expect(member.account_trusted);
        }
        if (member.node == node_c) {
            saw_forged = true;
            try std.testing.expect(!std.ascii.eqlIgnoreCase(member.nick, "alice"));
            try std.testing.expect(!member.account_trusted);
        }
    }
    try std.testing.expect(saw_honest);
    try std.testing.expect(saw_forged);

    const token_ambiguous: session_migrate.Token = @splat(0xA7);
    try applyTestRemoteSessionReplica(&server, &origin_a, token_ambiguous, "alice", "alice", 3);
    try std.testing.expectEqual(
        s2s_link.S2sLink.ResidenceDecision.reject,
        LinuxServer.residenceTrusted(&server, "alice", "alice", node_a, true),
    );
    std.debug.print("GAP-A3 branch=rowless session replica proof; forged account is UID-renamed\n", .{});
}

test "session attachment lease encode OOM retains exact dirty token until full retry succeeds" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x6d)), "lease-oom.test");
    defer ident.deinit();
    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = ident.shortId(),
        .server_name = "lease-oom.test",
        .node_identity = &ident,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const token: session_migrate.Token = @splat(0x6d);
    _ = try server.sessions.attach("alice", 1, token, 1);
    try std.testing.expect(server.sessions.markPortableResumeIssued("alice", 1));
    try std.testing.expect(server.publishSessionReplicaUpsert(token, "alice", "Alice", "base", false));

    var failing = std.testing.FailingAllocator.init(allocator, .{});
    server.allocator = failing.allocator();
    failing.fail_index = failing.alloc_index;
    try std.testing.expect(!server.publishSessionAttachmentLease(token));
    server.allocator = allocator;
    try std.testing.expectEqual(@as(usize, 1), server.sessions.dirtyReplicaRowCount());
    var dirty_buf: [1]sessions_mod.Token = undefined;
    const dirty = server.sessions.dirtyPortableTokensInto(&dirty_buf);
    try std.testing.expectEqual(@as(usize, 1), dirty.len);
    try std.testing.expectEqualSlices(u8, &token, &dirty[0]);

    // Retry republishes a newer complete OFFER and only then a newer lease; the
    // durable row bit clears at the combined Store acceptance boundary.
    try std.testing.expect(server.publishSessionReplicaUpsert(token, "alice", "Alice", "retry", true));
    try std.testing.expectEqual(@as(usize, 0), server.sessions.dirtyReplicaRowCount());
    const offer = server.session_replica_store.getOrigin(token, ident.shortId()).?;
    const lease = server.session_replica_store.getAttachmentLease(token, ident.shortId()).?;
    try std.testing.expect(lease.revision.compare(offer.revision) == .gt);

    var offer_failing = std.testing.FailingAllocator.init(allocator, .{});
    server.allocator = offer_failing.allocator();
    offer_failing.fail_index = offer_failing.alloc_index;
    try std.testing.expect(!server.publishSessionReplicaUpsert(token, "alice", "Alice", "refresh", true));
    server.allocator = allocator;
    try std.testing.expectEqual(@as(usize, 1), server.sessions.dirtyReplicaRowCount());
    try std.testing.expect(server.publishSessionReplicaUpsert(token, "alice", "Alice", "refresh-retry", true));
    try std.testing.expectEqual(@as(usize, 0), server.sessions.dirtyReplicaRowCount());
}

test "session replica orphaned final revoke survives encode Store OOM and checkpoint" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x6e)), "revoke-retry.test");
    defer ident.deinit();
    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = ident.shortId(),
        .server_name = "revoke-retry.test",
        .node_identity = &ident,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const encode_token: session_migrate.Token = @splat(0x6e);
    const store_token: session_migrate.Token = @splat(0x6f);
    _ = try server.sessions.attach("alice", 1, encode_token, 1);
    _ = try server.sessions.attach("alice", 2, store_token, 2);
    try std.testing.expect(server.publishSessionReplicaUpsert(encode_token, "alice", "Alice", "encode", false));
    try std.testing.expect(server.publishSessionReplicaUpsert(store_token, "alice", "Alice", "store", false));
    try std.testing.expect(server.sessions.remove("alice", 1));
    try std.testing.expect(server.sessions.remove("alice", 2));

    var encode_failing = std.testing.FailingAllocator.init(allocator, .{});
    server.allocator = encode_failing.allocator();
    encode_failing.fail_index = encode_failing.alloc_index;
    server.publishSessionReplicaRevoke(encode_token);
    server.allocator = allocator;
    try std.testing.expect(server.session_replica_store.getOrigin(encode_token, ident.shortId()) != null);

    var store_failing = std.testing.FailingAllocator.init(allocator, .{});
    server.session_replica_store.allocator = store_failing.allocator();
    store_failing.fail_index = store_failing.alloc_index;
    server.publishSessionReplicaRevoke(store_token);
    server.session_replica_store.allocator = allocator;
    try std.testing.expect(server.session_replica_store.getOrigin(store_token, ident.shortId()) != null);

    // The surviving OFFERs are the durable retry journal and travel through the
    // ordinary Store checkpoint even though their SessionStore rows are gone.
    const checkpoint_now: i64 = @intCast(@min(server.meshWallMs(), @as(u64, std.math.maxInt(i64))));
    const checkpoint = try server.session_replica_store.encodeUpgradeCheckpoint(allocator, checkpoint_now);
    defer allocator.free(checkpoint);
    try server.session_replica_store.replaceFromUpgradeCheckpoint(checkpoint, checkpoint_now);

    server.retryOrphanedLocalSessionReplicaRevokes();
    try std.testing.expect(server.session_replica_store.getOrigin(encode_token, ident.shortId()) == null);
    try std.testing.expect(server.session_replica_store.getOrigin(store_token, ident.shortId()) == null);
    try std.testing.expect(server.session_replica_store.getOriginTombstone(encode_token, ident.shortId()) != null);
    try std.testing.expect(server.session_replica_store.getOriginTombstone(store_token, ident.shortId()) != null);
}

test "session replica sweep retains expired orphan until local revoke retry succeeds" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x70)), "revoke-presweep.test");
    defer ident.deinit();
    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = ident.shortId(),
        .server_name = "revoke-presweep.test",
        .node_identity = &ident,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const token: session_migrate.Token = @splat(0x70);
    _ = try server.sessions.attach("alice", 1, token, 1);
    try std.testing.expect(server.sessions.remove("alice", 1));

    // Model a wall-clock jump after this locally accepted OFFER was minted. It is
    // expired at the timer's current wall but remains the only durable journal
    // proving that the now-rowless local origin still needs a final REVOKE.
    const now_wall: i64 = @intCast(@min(server.meshWallMs(), @as(u64, std.math.maxInt(i64))));
    const issued_at_ms = now_wall - 2;
    const physical: u64 = @intCast(issued_at_ms);
    const wire = try session_replica_v2.encodeOffer(allocator, .{
        .operation = .upsert,
        .token = token,
        .revision = .{
            .epoch = physical,
            .sequence = physical << mesh_clock_mod.seq_bits,
            .origin_node = ident.shortId(),
        },
        .issued_at_ms = issued_at_ms,
        .expires_at_ms = now_wall - 1,
        .account = "alice",
        .nick = "Alice",
        .snapshot = "expired-local-offer",
    }, &ident.sign_kp);
    defer allocator.free(wire);
    const accepted = try server.session_replica_store.applySignedOffer(
        try session_replica_v2.decodeOffer(wire),
        0,
        issued_at_ms,
    );
    try std.testing.expectEqual(session_replica_v2.ApplyDisposition.inserted, accepted.disposition);

    // The first timer-order attempt cannot encode the tombstone. Destructive
    // expiry must stop and leave the OFFER intact for the next bounded retry.
    var encode_failing = std.testing.FailingAllocator.init(allocator, .{});
    server.allocator = encode_failing.allocator();
    encode_failing.fail_index = encode_failing.alloc_index;
    server.sweepSessionReplicaStore();
    server.allocator = allocator;
    try std.testing.expect(server.session_replica_store.getOrigin(token, ident.shortId()) != null);
    try std.testing.expect(server.session_replica_store.getOriginTombstone(token, ident.shortId()) == null);

    // The next timer turn can encode/apply the REVOKE. Only then may sweep remove
    // expired identity state; the signed tombstone remains restart/replay durable.
    server.sweepSessionReplicaStore();
    try std.testing.expect(server.session_replica_store.getOrigin(token, ident.shortId()) == null);
    try std.testing.expect(server.session_replica_store.getOriginTombstone(token, ident.shortId()) != null);
}

test "session replica replay skips attachment leases for rolling-old peers without pinning burst" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();
    try std.testing.expect(pair.a.supportsSecureRelayV2());
    try std.testing.expect(pair.a.supportsEventSpineV2());
    if (pair.a.inner) |inner| {
        inner.peer.peer_supports_session_attachment_lease_v2 = false;
    } else return error.TestUnexpectedResult;
    try std.testing.expect(pair.a.supportsSessionReplicaV2());
    try std.testing.expect(!pair.a.supportsSessionAttachmentLeaseV2());

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "lease-old-peer.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const token: session_migrate.Token = @splat(0x6b);
    _ = try server.sessions.attach("alice", 1, token, 1);
    try std.testing.expect(server.sessions.markPortableResumeIssued("alice", 1));
    try std.testing.expect(server.publishSessionReplicaUpsert(token, "alice", "Alice", "attached", true));
    const now: i64 = @intCast(@min(server.meshWallMs(), @as(u64, std.math.maxInt(i64))));
    try std.testing.expectEqual(@as(usize, 2), server.session_replica_store.retainedCount(now));

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.test_sendq_capture = true; // Buffered unit sink owns no kernel SEND.
    conn.s2s_secured = &pair.a; // Borrowed; the pair owns the link.
    try std.testing.expect(conn.ownsActiveMeshLink(&pair.a));
    conn.sendq_cap = default_sendq_cap;
    defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    server.scheduleSessionReplicaReplay(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(!conn.session_replica_replay_pending);
    try std.testing.expectEqual(@as(usize, 0), conn.session_replica_replay_cursor);

    const ciphertext = try copyTestSendQ(allocator, &conn);
    defer allocator.free(ciphertext);
    try pair.b.feed(ciphertext, 100);
    const frames = try pair.b.takeSessionReplicaFrames();
    defer {
        for (frames) |*frame| frame.deinit(allocator);
        allocator.free(frames);
    }
    try std.testing.expectEqual(@as(usize, 1), frames.len);
    try std.testing.expectEqual(s2s_link.SessionReplicaKind.offer, frames[0].kind);
}

test "session replica mid-flight RESYNC restarts canonical Store without revision churn" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "resync-coalesce.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    var i: u8 = 1;
    while (i <= 10) : (i += 1) {
        var token: session_migrate.Token = @splat(0);
        token[token.len - 1] = i;
        try std.testing.expect(server.publishSessionReplicaUpsert(token, "alice", "Alice", "canonical", false));
    }
    const generation = server.session_replica_store_generation;
    const maximum = server.session_replica_store.maxAuthorityRevision().?;

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.send_armed = true;
    conn.sendq_cap = default_sendq_cap;
    conn.s2s_secured = &pair.a;
    defer {
        conn.s2s_secured = null;
        if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    }

    // Model an establishment replay already in flight before the peer resets
    // its converged view and asks for its first RESYNC burst.
    server.scheduleSessionReplicaReplay(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expectEqual(@as(usize, 8), conn.session_replica_replay_cursor);
    const cutoff = conn.session_replica_replay_now_ms;
    try std.testing.expectEqual(generation, server.session_replica_store_generation);
    try std.testing.expect(server.session_replica_store.maxAuthorityRevision().?.eql(maximum));

    // The peer's RESYNC contract resets its converged view to empty. Its first
    // request arriving mid-page must therefore restart from object zero;
    // continuing the old cursor would send only the final two objects and then
    // release roster.
    resetTestSendQ(&conn);
    try pair.b.sendResync();
    const second = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(second);
    pair.b.clearOutbound();
    server.driveS2sSecured(&conn, &pair.a, second);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expectEqual(@as(usize, 8), conn.session_replica_replay_cursor);
    try std.testing.expect(conn.session_replica_replay_now_ms >= cutoff);

    // Reset the receiver a SECOND time before the restarted pass reaches its
    // tail. This request must not be swallowed by the coalescing latch: the
    // current tail completes, then the replay wraps to object zero for the new
    // reset generation.
    resetTestSendQ(&conn);
    try pair.b.sendResync();
    const third = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(third);
    pair.b.clearOutbound();
    server.driveS2sSecured(&conn, &pair.a, third);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expectEqual(@as(usize, 0), conn.session_replica_replay_cursor);
    try std.testing.expect(conn.session_replica_replay_after == null);

    // The second reset's complete pass must expose page one again before its
    // tail is allowed to clear the pending burst.
    resetTestSendQ(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expectEqual(@as(usize, 8), conn.session_replica_replay_cursor);
    resetTestSendQ(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(!conn.session_replica_replay_pending);
    try std.testing.expectEqual(generation, server.session_replica_store_generation);
    try std.testing.expect(server.session_replica_store.maxAuthorityRevision().?.eql(maximum));
}

test "session replica value replay completes 140 objects under continuous behind-cursor renewal" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "stable-replay.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const object_count = 140;
    for (0..object_count) |index| {
        var token: session_migrate.Token = @splat(0);
        std.mem.writeInt(u16, token[token.len - 2 ..][0..2], @intCast(index + 1), .big);
        try std.testing.expect(server.publishSessionReplicaUpsert(token, "alice", "Alice", "initial", false));
    }

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.test_sendq_capture = true; // Buffered unit sink owns no kernel SEND.
    conn.s2s_secured = &pair.a; // Borrowed; the pair owns the link.
    try std.testing.expect(conn.ownsActiveMeshLink(&pair.a));
    conn.sendq_cap = default_sendq_cap;
    defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    server.scheduleSessionReplicaReplay(&conn);

    var seen: [object_count]bool = @splat(false);
    var turns: usize = 0;
    while (conn.session_replica_replay_pending and turns < 24) : (turns += 1) {
        resetTestSendQ(&conn);
        server.replaySessionReplicaStoreTo(&conn, &pair.a);
        const ciphertext = try copyTestSendQ(allocator, &conn);
        defer allocator.free(ciphertext);
        try pair.b.feed(ciphertext, @intCast(500 + turns));
        const frames = try pair.b.takeSessionReplicaFrames();
        defer {
            for (frames) |*frame| frame.deinit(allocator);
            allocator.free(frames);
        }
        for (frames) |frame| {
            if (frame.kind != .offer) continue;
            const signed = try session_replica_v2.decodeOffer(frame.signed_payload);
            const value = std.mem.readInt(u16, signed.offer.token[signed.offer.token.len - 2 ..][0..2], .big);
            try std.testing.expect(value >= 1 and value <= object_count);
            seen[value - 1] = true;
        }

        if (conn.session_replica_replay_pending) {
            // Replace an object lexicographically behind the current cursor on
            // every page. The old numeric/hash iterator reset here forever once
            // the Store exceeded roughly 120 objects under normal lease cadence.
            var behind: session_migrate.Token = @splat(0);
            std.mem.writeInt(u16, behind[behind.len - 2 ..][0..2], 1, .big);
            try std.testing.expect(server.publishSessionReplicaUpsert(
                behind,
                "alice",
                "Alice",
                "renewed-behind-cursor",
                false,
            ));
        }
    }
    try std.testing.expect(!conn.session_replica_replay_pending);
    try std.testing.expect(turns <= 18);
    for (seen) |present| try std.testing.expect(present);
}

test "session replica conflicted lease replays both witnesses back to ingress peer" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "lease-conflict-ingress.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const token: session_migrate.Token = @splat(0x6c);
    const revision = server.nextSessionReplicaRevision();
    const latest_issue = @as(u64, std.math.maxInt(i64)) - LinuxServer.session_attachment_lease_ttl_ms;
    const issued_u = @min(@min(server.meshWallMs(), revision.epoch), latest_issue);
    const issued: i64 = @intCast(issued_u);
    const first_wire = try session_replica_v2.encodeAttachmentLease(allocator, .{
        .token = token,
        .revision = revision,
        .issued_at_ms = issued,
        .expires_at_ms = issued + @as(i64, @intCast(LinuxServer.session_attachment_lease_ttl_ms)),
    }, &pair.ida.sign_kp);
    defer allocator.free(first_wire);
    const conflict_wire = try session_replica_v2.encodeAttachmentLease(allocator, .{
        .token = token,
        .revision = revision,
        .issued_at_ms = issued,
        .expires_at_ms = issued + @as(i64, @intCast(LinuxServer.session_attachment_lease_ttl_ms)) - 1,
    }, &pair.ida.sign_kp);
    defer allocator.free(conflict_wire);
    _ = try server.session_replica_store.applySignedAttachmentLease(
        try session_replica_v2.decodeAttachmentLease(first_wire),
        issued,
    );
    try std.testing.expectEqual(
        session_replica_v2.AttachmentLeaseDisposition.conflict,
        try server.session_replica_store.applySignedAttachmentLease(
            try session_replica_v2.decodeAttachmentLease(conflict_wire),
            issued,
        ),
    );
    server.session_replica_store_generation +%= 1;

    // The ingress sends only the second transcript. Because this server already
    // knows both, a duplicate must schedule retained replay back to ingress.
    try pair.b.sendSessionAttachmentLease(conflict_wire);
    const inbound = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(inbound);
    pair.b.clearOutbound();
    try pair.a.feed(inbound, 100);

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.send_armed = true;
    conn.sendq_cap = default_sendq_cap;
    defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    conn.s2s_secured = &pair.a;
    _ = server.drainSessionReplicaV2(&conn, &pair.a);
    try std.testing.expect(conn.session_replica_replay_pending);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(!conn.session_replica_replay_pending);

    const backfill = try copyTestSendQ(allocator, &conn);
    defer allocator.free(backfill);
    try pair.b.feed(backfill, 101);
    const frames = try pair.b.takeSessionReplicaFrames();
    defer {
        for (frames) |*frame| frame.deinit(allocator);
        allocator.free(frames);
    }
    try std.testing.expectEqual(@as(usize, 2), frames.len);
    try std.testing.expectEqual(s2s_link.SessionReplicaKind.attachment_lease, frames[0].kind);
    try std.testing.expectEqual(s2s_link.SessionReplicaKind.attachment_lease, frames[1].kind);
    try std.testing.expect(!std.mem.eql(u8, frames[0].signed_payload, frames[1].signed_payload));
}

test "session replica replay preflights SendQ before AEAD advance and resumes at eight frames" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "replay-a.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
        .mesh_pass = "session-replay-secret",
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    var i: u8 = 1;
    while (i <= 10) : (i += 1) {
        var token: session_migrate.Token = @splat(0);
        token[token.len - 1] = i;
        _ = server.publishSessionReplicaUpsert(token, "alice", "Alice", "portable-state", false);
    }
    const now: i64 = @intCast(@min(server.meshWallMs(), @as(u64, std.math.maxInt(i64))));
    try std.testing.expectEqual(@as(usize, 10), server.session_replica_store.retainedCount(now));

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.test_sendq_capture = true; // Buffered unit sink owns no kernel SEND.
    conn.s2s_secured = &pair.a; // Borrowed; the pair owns the link.
    try std.testing.expect(conn.ownsActiveMeshLink(&pair.a));
    defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    const filler: [8192]u8 = @splat(0x5a);
    conn.sendq_cap = filler.len;
    try rawAppendToConn(&conn, &filler);

    server.scheduleSessionReplicaReplay(&conn);
    const held_counter = pair.a.exportOuter().send_counter;
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expectEqual(@as(usize, 0), conn.session_replica_replay_cursor);
    try std.testing.expectEqual(@as(usize, 0), pair.a.outbound().len);
    try std.testing.expectEqual(held_counter, pair.a.exportOuter().send_counter);

    // Resume with room. The first attempt did not advance the encrypted record
    // counter or manufacture shared outbound ownership, so this turn may encode
    // the ordinary eight-record page exactly once.
    resetTestSendQ(&conn);
    conn.sendq_cap = default_sendq_cap;
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expectEqual(@as(usize, 8), conn.session_replica_replay_cursor);
    try std.testing.expectEqual(@as(usize, 0), pair.a.outbound().len);

    var seen: [10]bool = @splat(false);
    const first_page = try copyTestSendQ(allocator, &conn);
    defer allocator.free(first_page);
    try pair.b.feed(first_page, 100);
    {
        const frames = try pair.b.takeSessionReplicaFrames();
        defer {
            for (frames) |*frame| frame.deinit(allocator);
            allocator.free(frames);
        }
        try std.testing.expectEqual(@as(usize, 8), frames.len);
        for (frames) |frame| {
            const signed = try session_replica_v2.decodeOffer(frame.signed_payload);
            const index = signed.offer.token[signed.offer.token.len - 1];
            try std.testing.expect(index >= 1 and index <= seen.len);
            try std.testing.expect(!seen[index - 1]);
            seen[index - 1] = true;
        }
    }
    try pair.pump(allocator);

    resetTestSendQ(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(!conn.session_replica_replay_pending);
    try std.testing.expectEqual(@as(usize, 0), conn.session_replica_replay_cursor);
    const tail = try copyTestSendQ(allocator, &conn);
    defer allocator.free(tail);
    try pair.b.feed(tail, 101);
    {
        const frames = try pair.b.takeSessionReplicaFrames();
        defer {
            for (frames) |*frame| frame.deinit(allocator);
            allocator.free(frames);
        }
        try std.testing.expectEqual(@as(usize, 2), frames.len);
        for (frames) |frame| {
            const signed = try session_replica_v2.decodeOffer(frame.signed_payload);
            const index = signed.offer.token[signed.offer.token.len - 1];
            try std.testing.expect(index >= 1 and index <= seen.len);
            try std.testing.expect(!seen[index - 1]);
            seen[index - 1] = true;
        }
    }
    for (seen) |present| try std.testing.expect(present);

    const before = try copyTestSendQ(allocator, &conn);
    defer allocator.free(before);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    const after = try copyTestSendQ(allocator, &conn);
    defer allocator.free(after);
    try std.testing.expectEqualSlices(u8, before, after);
}

test "session replica gates establishment and RESYNC membership behind every retained authority page" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "replay-gate-a.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
        .mesh_pass = "session-replay-secret",
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const local_id = try addTestLocalClient(&server, "LocalMember", "alice");
    try server.world.restoreMember("#authority-gate", worldIdFromClient(local_id), world_model.MemberModes.empty());

    var i: u8 = 1;
    while (i <= 10) : (i += 1) {
        var token: session_migrate.Token = @splat(0);
        token[token.len - 1] = i;
        try std.testing.expect(server.publishSessionReplicaUpsert(token, "alice", "Replica", "portable-state", false));
    }
    const now: i64 = @intCast(@min(server.meshWallMs(), @as(u64, std.math.maxInt(i64))));
    try std.testing.expectEqual(@as(usize, 10), server.session_replica_store.retainedCount(now));

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.send_armed = true; // keep the unit seam independent of io_uring
    conn.sendq_cap = default_sendq_cap;
    conn.s2s_secured = &pair.a;
    defer {
        conn.s2s_secured = null;
        if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    }

    // Page one is exactly the replay turn limit. Releasing the establishment
    // burst here would put token-less MEMBERSHIP in an earlier TCP read than the
    // two remaining Store objects.
    server.scheduleSessionReplicaReplay(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expectEqual(@as(usize, 8), conn.session_replica_replay_cursor);
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expect(!conn.s2s_burst_done);

    const first_page = try copyTestSendQ(allocator, &conn);
    defer allocator.free(first_page);
    try pair.b.feed(first_page, 300);
    {
        const replicas = try pair.b.takeSessionReplicaFrames();
        defer {
            for (replicas) |*frame| frame.deinit(allocator);
            allocator.free(replicas);
        }
        try std.testing.expectEqual(@as(usize, 8), replicas.len);
    }
    pair.b.processDeferredResidenceFrames(300);
    {
        const membership = try pair.b.takeMembershipChanges();
        defer {
            for (membership) |*change| change.deinit(allocator);
            allocator.free(membership);
        }
        try std.testing.expectEqual(@as(usize, 0), membership.len);
    }

    // The next turn queues the last two authority records. Only after replay is
    // complete may the helper append the membership burst behind them.
    resetTestSendQ(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(!conn.session_replica_replay_pending);
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    try std.testing.expect(conn.s2s_burst_done);
    const tail = try copyTestSendQ(allocator, &conn);
    defer allocator.free(tail);

    const TestRecord = struct {
        fn len(bytes: []const u8) !usize {
            if (bytes.len < 4) return error.TestUnexpectedResult;
            const body_len: usize = std.mem.readInt(u32, bytes[0..4], .little);
            const total = std.math.add(usize, 4, body_len) catch return error.TestUnexpectedResult;
            if (total > bytes.len) return error.TestUnexpectedResult;
            return total;
        }
    };
    const first_len = try TestRecord.len(tail);
    const second_len = try TestRecord.len(tail[first_len..]);
    const authority_prefix_len = first_len + second_len;
    try std.testing.expect(authority_prefix_len < tail.len); // a later burst exists

    // Feed the tail one encrypted record at a time. Both leading records must be
    // SESSION_REPLICA; no MEMBERSHIP may appear until both have been received.
    try pair.b.feed(tail[0..first_len], 301);
    {
        const replicas = try pair.b.takeSessionReplicaFrames();
        defer {
            for (replicas) |*frame| frame.deinit(allocator);
            allocator.free(replicas);
        }
        try std.testing.expectEqual(@as(usize, 1), replicas.len);
    }
    pair.b.processDeferredResidenceFrames(301);
    {
        const membership = try pair.b.takeMembershipChanges();
        defer {
            for (membership) |*change| change.deinit(allocator);
            allocator.free(membership);
        }
        try std.testing.expectEqual(@as(usize, 0), membership.len);
    }

    try pair.b.feed(tail[first_len..authority_prefix_len], 302);
    {
        const replicas = try pair.b.takeSessionReplicaFrames();
        defer {
            for (replicas) |*frame| frame.deinit(allocator);
            allocator.free(replicas);
        }
        try std.testing.expectEqual(@as(usize, 1), replicas.len);
    }
    pair.b.processDeferredResidenceFrames(302);
    {
        const membership = try pair.b.takeMembershipChanges();
        defer {
            for (membership) |*change| change.deinit(allocator);
            allocator.free(membership);
        }
        try std.testing.expectEqual(@as(usize, 0), membership.len);
    }

    try pair.b.feed(tail[authority_prefix_len..], 303);
    pair.b.processDeferredResidenceFrames(303);
    {
        const membership = try pair.b.takeMembershipChanges();
        defer {
            for (membership) |*change| change.deinit(allocator);
            allocator.free(membership);
        }
        var saw_channel = false;
        for (membership) |change| {
            if (std.ascii.eqlIgnoreCase(change.channel, "#authority-gate")) saw_channel = true;
        }
        try std.testing.expect(saw_channel);
    }

    // RESYNC uses the same gate even after the one-shot establishment burst is
    // complete. The first page cannot consume its pending burst request.
    resetTestSendQ(&conn);
    conn.session_replica_resync_burst_pending = true;
    server.scheduleSessionReplicaReplay(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expect(conn.session_replica_resync_burst_pending);
    resetTestSendQ(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    try std.testing.expect(!conn.session_replica_replay_pending);
    try std.testing.expect(!conn.session_replica_resync_burst_pending);
    const resync_tail = try copyTestSendQ(allocator, &conn);
    defer allocator.free(resync_tail);
    try std.testing.expect(resync_tail.len != 0);

    // A repair-triggered secured RESYNC must enter the identical deferred
    // burst state instead of bypassing retained authority replay.
    resetTestSendQ(&conn);
    if (pair.a.inner) |inner| {
        inner.peer.repair_resync_requested = true;
    } else return error.TestUnexpectedResult;
    server.drainRepairResync(&conn, &pair.a, true);
    // Production reaches the identical common drive tail after the repair
    // scheduler; exercise its single bounded batch explicitly at this unit seam.
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expectEqual(@as(usize, 8), conn.session_replica_replay_cursor);
    try std.testing.expect(conn.session_replica_resync_burst_pending);
    resetTestSendQ(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    try std.testing.expect(!conn.session_replica_replay_pending);
    try std.testing.expect(!conn.session_replica_resync_burst_pending);
}

test "session replica burst retains whole-record ciphertext across SendQ backpressure" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "burst-retry-a.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    // A token-less local member keeps this test focused on authenticated record
    // continuity rather than residence admission (covered by the gate campaign
    // above).
    const local_id = try addTestLocalClient(&server, "BurstLocal", null);
    try server.world.restoreMember("#burst-retry", worldIdFromClient(local_id), world_model.MemberModes.empty());

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.send_armed = true;
    conn.s2s_secured = &pair.a;
    defer {
        conn.s2s_secured = null;
        if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    }

    // Leave no SendQ room at the exact roster-release edge. The burst flags and
    // family cursor must remain pending, and the already-sealed membership
    // record must remain byte-identical in SecuredLink.
    const filler: [32]u8 = @splat(0x5a);
    conn.sendq_cap = filler.len;
    try rawAppendToConn(&conn, &filler);
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    try std.testing.expect(!conn.closing);
    try std.testing.expect(!conn.s2s_burst_done);
    try std.testing.expectEqual(MeshBurstStage.membership, conn.mesh_burst_stage);
    try std.testing.expect(conn.mesh_burst_stage_encoded);
    try std.testing.expect(pair.a.outbound().len != 0);
    const retained = try allocator.dupe(u8, pair.a.outbound());
    defer allocator.free(retained);

    // The receiver resets while that first pass is still retained. Preserve the
    // sealed record, replay authority, and require a membership-first wrap after
    // the interrupted pass rather than resuming only its later families.
    try pair.b.sendResync();
    const inbound_resync = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(inbound_resync);
    pair.b.clearOutbound();
    server.driveS2sSecured(&conn, &pair.a, inbound_resync);
    try std.testing.expect(!conn.closing);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expect(conn.session_replica_resync_burst_pending);
    try std.testing.expect(conn.mesh_burst_restart_pending);

    // Once the socket queue drains, retry consumes only complete records, keeps
    // the retained bytes as the exact prefix, and clears the gate only after the
    // interrupted pass AND a fresh full pass have entered SendQ.
    resetTestSendQ(&conn);
    conn.sendq_cap = LinuxServer.s2sSendqCap(default_sendq_cap);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(!conn.session_replica_replay_pending);
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    try std.testing.expect(!conn.closing);
    try std.testing.expect(conn.s2s_burst_done);
    try std.testing.expect(!conn.session_replica_resync_burst_pending);
    try std.testing.expectEqual(MeshBurstStage.idle, conn.mesh_burst_stage);
    try std.testing.expect(!conn.mesh_burst_stage_encoded);
    try std.testing.expect(!conn.mesh_burst_restart_pending);
    try std.testing.expectEqual(@as(usize, 0), pair.a.outbound().len);
    const burst = try copyTestSendQ(allocator, &conn);
    defer allocator.free(burst);
    try std.testing.expect(burst.len >= retained.len);
    try std.testing.expectEqualSlices(u8, retained, burst[0..retained.len]);

    // Observe the retained pre-reset membership first, then the remaining old
    // families plus the mandatory fresh membership pass. Draining between them
    // prevents the receiver's LWW change queue from coalescing the two facts.
    try pair.b.feed(burst[0..retained.len], 400);
    pair.b.processDeferredResidenceFrames(400);
    var interrupted_hlc: ?u64 = null;
    {
        const membership = try pair.b.takeMembershipChanges();
        defer {
            for (membership) |*change| change.deinit(allocator);
            allocator.free(membership);
        }
        var saw_channel = false;
        for (membership) |change| {
            if (std.ascii.eqlIgnoreCase(change.channel, "#burst-retry")) saw_channel = true;
        }
        try std.testing.expect(saw_channel);
        for (pair.b.channelMembers("#burst-retry")) |member| {
            if (std.ascii.eqlIgnoreCase(member.nick, "BurstLocal")) interrupted_hlc = member.hlc;
        }
        try std.testing.expect(interrupted_hlc != null);
    }
    try pair.b.feed(burst[retained.len..], 401);
    pair.b.processDeferredResidenceFrames(401);
    {
        const membership = try pair.b.takeMembershipChanges();
        defer {
            for (membership) |*change| change.deinit(allocator);
            allocator.free(membership);
        }
        // An identical PRESENT refresh need not enqueue another user-visible
        // delta, but its newer HLC must prove the fresh pass was accepted.
        var fresh_hlc: ?u64 = null;
        for (pair.b.channelMembers("#burst-retry")) |member| {
            if (std.ascii.eqlIgnoreCase(member.nick, "BurstLocal")) fresh_hlc = member.hlc;
        }
        try std.testing.expect(fresh_hlc != null);
        try std.testing.expect(fresh_hlc.? > interrupted_hlc.?);
    }

    // A later authenticated record must still verify. If the denied attempt had
    // cleared even one ciphertext record, this feed would fail with AuthFailed
    // because the receiver's record counter would lag the sender's.
    try pair.a.sendResync();
    const later = try allocator.dupe(u8, pair.a.outbound());
    defer allocator.free(later);
    pair.a.clearOutbound();
    try pair.b.feed(later, 402);
}

test "session replica live fanout preserves retained ciphertext on a full peer SendQ" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "fanout-backpressure-a.test",
