test "session replica burst retries incomplete family after secured record allocation failure" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "burst-oom-a.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const local_id = try addTestLocalClient(&server, "BurstOom", null);
    try server.world.restoreMember("#burst-oom", worldIdFromClient(local_id), world_model.MemberModes.empty());

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.send_armed = true;
    conn.sendq_cap = LinuxServer.s2sSendqCap(default_sendq_cap);
    conn.s2s_secured = &pair.a;
    defer {
        conn.s2s_secured = null;
        if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    }

    // The inner signed frame is already durable when the outer record resize is
    // attempted. Fail exactly that allocation. The burst family must remain
    // uncommitted rather than treating the caught row as a completed snapshot.
    pair.a.out.clearAndFree(pair.a.allocator);
    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    pair.a.allocator = failing.allocator();
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    pair.a.allocator = allocator;
    try std.testing.expect(failing.has_induced_failure);
    try std.testing.expect(!conn.closing);
    try std.testing.expect(!conn.s2s_burst_done);
    try std.testing.expectEqual(MeshBurstStage.membership, conn.mesh_burst_stage);
    try std.testing.expect(!conn.mesh_burst_stage_encoded);

    // Recovery retries the entire idempotent family, then releases the gate only
    // after the missing row and every later family have entered this SendQ.
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    try std.testing.expect(conn.s2s_burst_done);
    try std.testing.expectEqual(MeshBurstStage.idle, conn.mesh_burst_stage);
    const burst = try copyTestSendQ(allocator, &conn);
    defer allocator.free(burst);
    try pair.b.feed(burst, 500);
    pair.b.processDeferredResidenceFrames(500);
    const membership = try pair.b.takeMembershipChanges();
    defer {
        for (membership) |*change| change.deinit(allocator);
        allocator.free(membership);
    }
    var saw_channel = false;
    for (pair.b.channelMembers("#burst-oom")) |member| {
        if (std.ascii.eqlIgnoreCase(member.nick, "BurstOom")) saw_channel = true;
    }
    try std.testing.expect(saw_channel);

    // No failed outer allocation may advance the AEAD counter; a later record
    // authenticates only if the retry preserved exact counter continuity.
    try pair.a.sendResync();
    const later = try allocator.dupe(u8, pair.a.outbound());
    defer allocator.free(later);
    pair.a.clearOutbound();
    try pair.b.feed(later, 501);
}

test "session replica replay leaves no inner residue after outer record allocation failure" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "replay-outer-oom.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const token: session_migrate.Token = @splat(0x81);
    try std.testing.expect(server.publishSessionReplicaUpsert(token, "alice", "Alice", "outer-oom", false));

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.test_sendq_capture = true; // Buffered unit sink owns no kernel SEND.
    conn.s2s_secured = &pair.a; // Borrowed; the pair owns the link.
    try std.testing.expect(conn.ownsActiveMeshLink(&pair.a));
    conn.sendq_cap = default_sendq_cap;
    defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    server.scheduleSessionReplicaReplay(&conn);

    // Force the secured outer ArrayList to allocate, then deny exactly that
    // reservation. Transactional send must fail before appending the signed
    // plaintext frame to the inner link.
    pair.a.out.clearAndFree(pair.a.allocator);
    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    pair.a.allocator = failing.allocator();
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    pair.a.allocator = allocator;
    try std.testing.expect(failing.has_induced_failure);
    try std.testing.expect(!conn.closing);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expectEqual(@as(usize, 0), conn.session_replica_replay_cursor);
    try std.testing.expectEqual(@as(usize, 0), pair.a.outbound().len);
    try std.testing.expectEqual(@as(usize, 0), pair.a.inner.?.outbound().len);
    try std.testing.expectEqual(@as(usize, 0), conn.send_len - conn.send_offset);

    // Recovery emits exactly one object and completes normally; a duplicate
    // inner residue would make the exact ciphertext-length invariant close it.
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(!conn.closing);
    try std.testing.expect(!conn.session_replica_replay_pending);
    const ciphertext = try copyTestSendQ(allocator, &conn);
    defer allocator.free(ciphertext);
    try pair.b.feed(ciphertext, 600);
    const frames = try pair.b.takeSessionReplicaFrames();
    defer {
        for (frames) |*frame| frame.deinit(allocator);
        allocator.free(frames);
    }
    try std.testing.expectEqual(@as(usize, 1), frames.len);
}

test "session replica burst sends every legal mesh ward beyond legacy scratch cap" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "ward-burst-a.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const ward_count: usize = 257;
    for (0..ward_count) |index| {
        var pattern_buf: [48]u8 = undefined;
        const pattern = try std.fmt.bufPrint(&pattern_buf, "192.0.2.{d}", .{index});
        try server.warden.add(.{
            .match = .address,
            .pattern = pattern,
            .scope = .mesh,
            .action = .expel,
            .reason = "anti-entropy completeness",
            .set_by = "ward-test",
            .created_ms = @intCast(index + 1),
        });
    }
    try std.testing.expectEqual(ward_count, server.warden.count());

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.send_armed = true;
    conn.sendq_cap = LinuxServer.s2sSendqCap(default_sendq_cap);
    conn.s2s_secured = &pair.a;
    defer {
        conn.s2s_secured = null;
        if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    }
    server.releaseMeshBurstAfterSessionReplicaReplay(&conn, &pair.a);
    try std.testing.expect(conn.s2s_burst_done);
    try std.testing.expectEqual(MeshBurstStage.idle, conn.mesh_burst_stage);

    const burst = try copyTestSendQ(allocator, &conn);
    defer allocator.free(burst);
    try pair.b.feed(burst, 700);
    const received = try pair.b.takeWards();
    defer {
        for (received) |wire| allocator.free(wire);
        allocator.free(received);
    }
    // The compact filter is the first mesh-ban frame. Every authoritative add follows it.
    try std.testing.expectEqual(ward_count + 1, received.len);
    var filter = try warden.decodeMeshBanFilter(allocator, received[0]);
    defer filter.deinit();
    for (0..ward_count) |index| {
        var pattern_buf: [48]u8 = undefined;
        const pattern = try std.fmt.bufPrint(&pattern_buf, "192.0.2.{d}", .{index});
        try std.testing.expect(filter.mayContain(.address, pattern));
        const wire = try warden.decodeWire(received[index + 1]);
        try std.testing.expectEqual(warden.WireOp.add, wire.op);
        try std.testing.expectEqualStrings(pattern, wire.pattern);
    }
}

test "session replica replay budgets actual ciphertext with one-frame progress exception" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const replay_budget: usize = 256 * 1024;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    {
        var server = LinuxServer.init(allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .node_id = pair.ida.shortId(),
            .server_name = "replay-budget-a.test",
            .node_identity = &pair.ida,
            .crypto_io = std.testing.io,
            .mesh_pass = "session-replay-secret",
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const snapshot = try allocator.alloc(u8, 200 * 1024);
        defer allocator.free(snapshot);
        @memset(snapshot, 0x41);
        const token_a: session_migrate.Token = @splat(0x41);
        const token_b: session_migrate.Token = @splat(0x42);
        _ = server.publishSessionReplicaUpsert(token_a, "alice", "Alice", snapshot, false);
        _ = server.publishSessionReplicaUpsert(token_b, "alice", "Alice", snapshot, false);

        var conn = ConnState.init(-1);
        conn.overflow_allocator = allocator;
        conn.test_sendq_capture = true; // Buffered unit sink owns no kernel SEND.
        conn.s2s_secured = &pair.a; // Borrowed; the pair owns the link.
        try std.testing.expect(conn.ownsActiveMeshLink(&pair.a));
        conn.sendq_cap = default_sendq_cap;
        defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
        server.scheduleSessionReplicaReplay(&conn);
        server.replaySessionReplicaStoreTo(&conn, &pair.a);
        const first = try copyTestSendQ(allocator, &conn);
        defer allocator.free(first);
        try std.testing.expect(first.len != 0 and first.len <= replay_budget);
        try std.testing.expectEqual(@as(usize, 1), conn.session_replica_replay_cursor);
        try std.testing.expectEqual(@as(usize, 0), pair.a.outbound().len);
        try pair.b.feed(first, 200);
        {
            const frames = try pair.b.takeSessionReplicaFrames();
            defer {
                for (frames) |*frame| frame.deinit(allocator);
                allocator.free(frames);
            }
            try std.testing.expectEqual(@as(usize, 1), frames.len);
        }

        resetTestSendQ(&conn);
        server.replaySessionReplicaStoreTo(&conn, &pair.a);
        const second = try copyTestSendQ(allocator, &conn);
        defer allocator.free(second);
        try std.testing.expect(second.len != 0 and second.len <= replay_budget);
        try std.testing.expect(!conn.session_replica_replay_pending);
        try std.testing.expectEqual(@as(usize, 0), pair.a.outbound().len);
        try pair.b.feed(second, 201);
        {
            const frames = try pair.b.takeSessionReplicaFrames();
            defer {
                for (frames) |*frame| frame.deinit(allocator);
                allocator.free(frames);
            }
            try std.testing.expectEqual(@as(usize, 1), frames.len);
        }
        try pair.pump(allocator);
    }

    // A legal object larger than the per-turn target must still make progress:
    // it is the sole frame in its turn, explicitly exempt from the byte target.
    {
        var server = LinuxServer.init(allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .node_id = pair.ida.shortId(),
            .server_name = "replay-large-a.test",
            .node_identity = &pair.ida,
            .crypto_io = std.testing.io,
            .mesh_pass = "session-replay-secret",
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const snapshot = try allocator.alloc(u8, 300 * 1024);
        defer allocator.free(snapshot);
        @memset(snapshot, 0x51);
        const token: session_migrate.Token = @splat(0x51);
        _ = server.publishSessionReplicaUpsert(token, "alice", "Alice", snapshot, false);

        var conn = ConnState.init(-1);
        conn.overflow_allocator = allocator;
        conn.test_sendq_capture = true; // Buffered unit sink owns no kernel SEND.
        conn.s2s_secured = &pair.a; // Borrowed; the pair owns the link.
        try std.testing.expect(conn.ownsActiveMeshLink(&pair.a));
        conn.sendq_cap = default_sendq_cap;
        defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
        server.scheduleSessionReplicaReplay(&conn);
        server.replaySessionReplicaStoreTo(&conn, &pair.a);
        const wire = try copyTestSendQ(allocator, &conn);
        defer allocator.free(wire);
        try std.testing.expect(wire.len > replay_budget);
        try std.testing.expect(!conn.session_replica_replay_pending);
        try std.testing.expectEqual(@as(usize, 0), pair.a.outbound().len);
        try pair.b.feed(wire, 202);
        const frames = try pair.b.takeSessionReplicaFrames();
        defer {
            for (frames) |*frame| frame.deinit(allocator);
            allocator.free(frames);
        }
        try std.testing.expectEqual(@as(usize, 1), frames.len);
    }
}

test "maximum legal session replica fits the clamped server-link SendQ and progresses" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "replay-max-a.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
        .mesh_pass = "session-replay-secret",
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const snapshot = try allocator.alloc(u8, session_replica_v2.max_snapshot_len);
    defer allocator.free(snapshot);
    @memset(snapshot, 0x61);
    const account: [session_replica_v2.max_account_len]u8 = @splat('a');
    const nick: [session_replica_v2.max_nick_len]u8 = @splat('N');
    const token: session_migrate.Token = @splat(0x6d);
    _ = server.publishSessionReplicaUpsert(token, &account, &nick, snapshot, false);
    const now: i64 = @intCast(@min(server.meshWallMs(), @as(u64, std.math.maxInt(i64))));
    try std.testing.expectEqual(@as(usize, 1), server.session_replica_store.retainedCount(now));

    var conn = ConnState.init(-1);
    conn.overflow_allocator = allocator;
    conn.test_sendq_capture = true; // Buffered unit sink owns no kernel SEND.
    conn.s2s_secured = &pair.a; // Borrowed; the pair owns the link.
    try std.testing.expect(conn.ownsActiveMeshLink(&pair.a));
    // The server-link floor must fit the shared portable maximum plus every v2
    // and secured-record wrapper. The shared cap deliberately leaves legacy
    // envelope headroom, so the emitted record need not fill the entire queue.
    conn.sendq_cap = LinuxServer.s2sSendqCap(default_sendq_cap);
    defer if (conn.send_overflow.capacity > 0) conn.send_overflow.deinit(conn.overflow_allocator);
    try std.testing.expectEqual(min_s2s_sendq_cap, conn.sendq_cap);

    server.scheduleSessionReplicaReplay(&conn);
    server.replaySessionReplicaStoreTo(&conn, &pair.a);
    try std.testing.expect(!conn.session_replica_replay_pending);
    try std.testing.expectEqual(@as(usize, 0), pair.a.outbound().len);
    const wire = try copyTestSendQ(allocator, &conn);
    defer allocator.free(wire);
    try std.testing.expect(wire.len > snapshot.len);
    try std.testing.expect(wire.len <= conn.sendq_cap);
    try pair.b.feed(wire, 250);
    const frames = try pair.b.takeSessionReplicaFrames();
    defer {
        for (frames) |*frame| frame.deinit(allocator);
        allocator.free(frames);
    }
    try std.testing.expectEqual(@as(usize, 1), frames.len);
    const signed = try session_replica_v2.decodeOffer(frames[0].signed_payload);
    try std.testing.expectEqualSlices(u8, &account, signed.offer.account);
    try std.testing.expectEqualSlices(u8, &nick, signed.offer.nick);
    try std.testing.expectEqualSlices(u8, snapshot, signed.offer.snapshot);
}

test "v2 Store hot-adoption is SQ-inert until authority-first link activation" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    defer current_reactor = null;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "adopt-store.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
        .mesh_pass = "adopt-store-secret",
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const replica_token: session_migrate.Token = @splat(0x74);
    _ = server.publishSessionReplicaUpsert(replica_token, "alice", "Alice", "authority-snapshot", false);
    try std.testing.expectEqual(@as(usize, 1), server.session_replica_store.retainedCount(server.nowMs()));

    var sockets: [2]linux.fd_t = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets)) != .SUCCESS)
        return error.SkipZigTest;
    defer closeFd(sockets[1]);

    const outer = pair.a.exportOuter();
    const inner = pair.a.snapshotInner() orelse return error.TestUnexpectedResult;
    var caps: u8 = 0;
    if (inner.peer_supports_signing) caps |= s2s_snapshot.cap_signing;
    if (inner.peer_supports_account) caps |= s2s_snapshot.cap_account;
    if (inner.peer_supports_oper_info) caps |= s2s_snapshot.cap_oper_info;
    if (inner.peer_supports_repair) caps |= s2s_snapshot.cap_repair;
    if (inner.peer_supports_session_replica_v2) caps |= s2s_snapshot.cap_session_replica_v2;
    if (inner.peer_supports_session_attachment_lease_v2) caps |= s2s_snapshot.cap_session_attachment_lease_v2;
    var snap = s2s_snapshot.Snapshot{
        .fd = sockets[0],
        .role = @intFromEnum(outer.role),
        .send_counter = outer.send_counter,
        .recv_counter = outer.recv_counter,
        .feed_seq = outer.feed_seq,
        .pl_local_epoch_ms = inner.link.local_epoch_ms,
        .pl_remote_epoch_ms = inner.link.remote_epoch_ms,
        .pl_send_credit = inner.link.send_credit,
        .pl_pending_credit = inner.link.pending_credit,
        .pl_next_out_seq = inner.link.next_out_seq,
        .pl_next_in_seq = inner.link.next_in_seq,
        .pl_last_acked = inner.link.last_acked_by_remote,
        .remote_node_id = inner.remote_node_id,
        .remote_epoch_ms = inner.remote_epoch_ms,
        .caps = caps,
        .remote_name = pair.a.snapshotInnerRemoteName(),
        .rec_inbuf = outer.rec_inbuf,
    };
    outer.established.serialize(&snap.established);

    const sq_before = server.rx().ring.inner.sq_ready();
    try std.testing.expect(server.adoptInheritedS2sLink(snap, true) != null);
    try std.testing.expectEqual(sq_before, server.rx().ring.inner.sq_ready());
    var it = server.rx().clients.iterator();
    const conn = (it.next() orelse return error.TestExpectedEqual).value;
    try std.testing.expect(conn.io_activation_pending);
    try std.testing.expect(conn.activation_recv_required);
    try std.testing.expect(!conn.recv_armed and !conn.send_armed);
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expect(conn.session_replica_resync_burst_pending);
    try std.testing.expectEqual(@as(usize, 0), conn.session_replica_replay_cursor);

    _ = try server.activatePendingSocketIo();
    try std.testing.expect(conn.recv_armed and conn.send_armed);
    try std.testing.expect(!conn.io_activation_pending);
    try std.testing.expectEqual(sq_before + 2, server.rx().ring.inner.sq_ready());
    // Activation sends only the mandatory RESYNC. Retained authority is still
    // pending and the roster burst remains gated behind it.
    try std.testing.expect(conn.session_replica_replay_pending);
    try std.testing.expect(conn.session_replica_resync_burst_pending);
    server.replaySessionReplicaStoreTo(conn, conn.s2s_secured.?);
    try std.testing.expect(!conn.session_replica_replay_pending);
    try std.testing.expect(conn.session_replica_resync_burst_pending);
    server.releaseMeshBurstAfterSessionReplicaReplay(conn, conn.s2s_secured.?);
    try std.testing.expect(!conn.session_replica_resync_burst_pending);
}

test "secured roster repair follows inbound membership generations across asymmetric replay" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    const allocator = std.testing.allocator;
    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = LinuxServer.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "roster-gc-barrier.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
        .mesh_pass = "roster-gc-barrier-secret",
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const peer_id = try server.rx().clients.alloc(ConnState.init(-1));
    const peer = server.rx().clients.get(peer_id).?;
    peer.overflow_allocator = allocator;
    peer.token = try tokenFromId(peer_id);
    peer.send_armed = true;
    peer.s2s_secured = &pair.a;
    peer.s2s_burst_done = true;
    defer {
        peer.s2s_secured = null;
        _ = server.rx().clients.free(peer_id);
    }

    const pending_id = try addTestLocalClient(&server, "PendingLocal", null);
    const pending = server.connFor(pending_id).?;
    _ = try server.world.join("#roster-gc-barrier", worldIdFromClient(pending_id));

    // Seed B's existing view through the actual daemon burst path.
    try std.testing.expect(server.sendMembershipBurstTo(peer));
    const initial_daemon_burst = try allocator.dupe(u8, pair.a.outbound());
    defer allocator.free(initial_daemon_burst);
    pair.a.clearOutbound();
    try pair.b.feed(initial_daemon_burst, 80);
    pair.b.processDeferredResidenceFrames(80);
    server.discardIdentityTransitions(&pair.b);
    try std.testing.expectEqual(@as(usize, 1), pair.b.channelMembers("#roster-gc-barrier").len);

    // The same live attachment now awaits signed Store authority. It is omitted,
    // so the daemon must withhold the marker and leave the stage retryable; B's
    // existing row cannot be repaired away before deferred reannouncement.
    pending.session_mesh_announce_pending = true;
    try std.testing.expect(!server.sendMembershipBurstTo(peer));
    try std.testing.expectEqual(@as(usize, 0), pair.a.outbound().len);
    try std.testing.expectEqual(@as(usize, 1), pair.b.channelMembers("#roster-gc-barrier").len);

    // Once authority is ready, the complete daemon burst reaffirms the row before
    // its marker, producing neither a repair PART nor a replacement JOIN.
    pending.session_mesh_announce_pending = false;
    try std.testing.expect(server.sendMembershipBurstTo(peer));
    const daemon_burst = try allocator.dupe(u8, pair.a.outbound());
    defer allocator.free(daemon_burst);
    pair.a.clearOutbound();
    try pair.b.feed(daemon_burst, 90);
    pair.b.processDeferredResidenceFrames(90);
    try std.testing.expectEqual(@as(?i64, 90), pair.b.inner.?.peer.last_membership_sync_ms);
    try std.testing.expectEqual(@as(usize, 1), pair.b.channelMembers("#roster-gc-barrier").len);
    try std.testing.expect(pair.b.inner.?.peer.peekNextMembershipTransition() == null);

    try pair.b.sendMembership(
        "#roster-gc-barrier",
        "RemoteLive",
        0,
        100,
        true,
        .{ .username = "remote", .host = "peer.test" },
        "",
    );
    const wire = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(wire);
    pair.b.clearOutbound();
    try pair.a.feed(wire, 100);
    pair.a.processDeferredResidenceFrames(100);
    server.discardIdentityTransitions(&pair.a);
    try std.testing.expectEqual(@as(usize, 1), pair.a.channelMembers("#roster-gc-barrier").len);

    try pair.b.sendMembershipSync();
    const first_marker = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(first_marker);
    pair.b.clearOutbound();
    try pair.a.feed(first_marker, 100);
    pair.a.processDeferredResidenceFrames(100);
    server.discardIdentityTransitions(&pair.a);

    // A's outbound authority/replay state is already settled, while B sends no
    // completed inbound generation for longer than the historical TTL. A must
    // retain B's live member: local egress state cannot authorize inbound loss.
    peer.session_replica_replay_pending = false;
    peer.session_replica_resync_burst_pending = false;
    peer.s2s_burst_done = true;
    const refreshed_at = pair.a.channelMembers("#roster-gc-barrier")[0].last_refreshed_ms;
    const stale_now = refreshed_at + stale_member_ttl_ms + 1;
    server.pruneStaleMeshMembers(stale_now);
    try std.testing.expectEqual(@as(usize, 1), pair.a.channelMembers("#roster-gc-barrier").len);

    // B eventually completes a full generation containing RemoteLive. Its
    // reaffirmation refreshes the inbound row before the authenticated marker.
    try pair.b.sendMembership(
        "#roster-gc-barrier",
        "RemoteLive",
        0,
        101,
        true,
        .{ .username = "remote", .host = "peer.test" },
        "",
    );
    try pair.b.sendMembershipSync();
    const live_generation = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(live_generation);
    pair.b.clearOutbound();
    try pair.a.feed(live_generation, @intCast(stale_now));
    pair.a.processDeferredResidenceFrames(@intCast(stale_now));
    server.discardIdentityTransitions(&pair.a);
    try std.testing.expectEqual(@as(usize, 1), pair.a.channelMembers("#roster-gc-barrier").len);

    // A later completed B generation omits the member. Its last refresh shares
    // the preceding marker's millisecond, so the ambiguous equality survives
    // one extra generation rather than risking a false PART across read splits.
    try pair.b.sendMembershipSync();
    const first_omitted_generation = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(first_omitted_generation);
    pair.b.clearOutbound();
    const first_omitted_now: u64 = @intCast(stale_now + membership_resync_interval_ms);
    try pair.a.feed(first_omitted_generation, first_omitted_now);
    pair.a.processDeferredResidenceFrames(first_omitted_now);
    try std.testing.expectEqual(@as(usize, 1), pair.a.channelMembers("#roster-gc-barrier").len);
    try std.testing.expect(pair.a.inner.?.peer.peekNextMembershipTransition() == null);

    // The following authenticated generation gives an unambiguous boundary:
    // only peer-originated omission proof—not elapsed time or A's egress flags—
    // authorizes the repair PART.
    try pair.b.sendMembershipSync();
    const second_omitted_generation = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(second_omitted_generation);
    pair.b.clearOutbound();
    const second_omitted_now = first_omitted_now + @as(u64, @intCast(membership_resync_interval_ms));
    try pair.a.feed(second_omitted_generation, second_omitted_now);
    pair.a.processDeferredResidenceFrames(second_omitted_now);
    try std.testing.expectEqual(@as(usize, 0), pair.a.channelMembers("#roster-gc-barrier").len);
    const repair = pair.a.inner.?.peer.peekNextMembershipTransition() orelse return error.TestExpectedEqual;
    try std.testing.expectEqual(s2s_peer_mod.S2sPeer.MembershipDelta.Kind.parted, repair.kind);
    try std.testing.expectEqualStrings("RemoteLive", repair.nick);
}

