    return .{
        .host = "127.0.0.1",
        .port = port,
        .num_shards = 1,
        .sasl_checker = test_runtime_grant_checker,
        .oper_registry = oper_mod.OperRegistry.init(&test_oper_bindings) catch unreachable,
    };
