/// Drive a live client through SASL PLAIN as the "admin" oper account. Call
/// before NICK/USER so the client is elevated automatically at registration.
fn saslAdminPrelude(fd: linux.fd_t) ServerError!void {
    try saslPlainPrelude(fd, "admin", "onyx");
}

fn saslPlainPrelude(fd: linux.fd_t, account: []const u8, password: []const u8) ServerError!void {
    try saslPlainPreludeWithCaps(fd, account, password, "");
}

fn saslPlainPreludeWithCaps(fd: linux.fd_t, account: []const u8, password: []const u8, extra_caps: []const u8) ServerError!void {
    var plain: [128]u8 = undefined;
    if (account.len + password.len + 2 > plain.len) return error.OutputTooSmall;
    var plain_len: usize = 0;
    plain[plain_len] = 0;
    plain_len += 1;
    @memcpy(plain[plain_len .. plain_len + account.len], account);
    plain_len += account.len;
    plain[plain_len] = 0;
    plain_len += 1;
    @memcpy(plain[plain_len .. plain_len + password.len], password);
    plain_len += password.len;
    var b64: [64]u8 = undefined;
    const enc = std.base64.standard.Encoder.encode(&b64, plain[0..plain_len]);
    var line: [128]u8 = undefined;
    if (extra_caps.len == 0) {
        try writeAllFd(fd, "CAP REQ :sasl\r\n");
    } else {
        try writeAllFd(fd, std.fmt.bufPrint(&line, "CAP REQ :sasl {s}\r\n", .{extra_caps}) catch return error.OutputTooSmall);
    }
    try writeAllFd(fd, "AUTHENTICATE PLAIN\r\n");
    try writeAllFd(fd, std.fmt.bufPrint(&line, "AUTHENTICATE {s}\r\n", .{enc}) catch return error.OutputTooSmall);
    try writeAllFd(fd, "CAP END\r\n");
}

fn enrollTestMediaIdentity(server: *Server, account: []const u8, label: []const u8, seed_byte: u8) !std.crypto.sign.Ed25519.KeyPair {
    // Media identity enrollment writes the full-server prop store; no portable equivalent exists.
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.Unsupported;
    const Ed25519 = std.crypto.sign.Ed25519;
    const key_pair = try Ed25519.KeyPair.generateDeterministic(@as([Ed25519.KeyPair.seed_length]u8, @splat(seed_byte)));
    const public_key = key_pair.public_key.toBytes();
    const public_hex = std.fmt.bytesToHex(public_key, .lower);
    var transcript_buf: [account_identity.max_transcript_len]u8 = undefined;
    const transcript = account_identity.transcript(account, label, public_key, &transcript_buf).?;
    const signature = try key_pair.sign(transcript, null);
    const signature_hex = std.fmt.bytesToHex(signature.toBytes(), .lower);
    var value_buf: [account_identity.max_value_len]u8 = undefined;
    const value = account_identity.claimValue(&public_hex, &signature_hex, &value_buf).?;
    var prop_key_buf: [account_identity.prop_prefix.len + account_identity.max_label_len]u8 = undefined;
    const prop_key = account_identity.propKey(label, &prop_key_buf).?;
    const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
    _ = try server.props.setProp(entity, prop_key, value, .{ .id = account, .access = .member });
    return key_pair;
}

fn encodeTestMediaHandshake(
    out: *[std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8,
    attachment: [Server.media_e2ee_attachment_bytes]u8,
    identity: std.crypto.sign.Ed25519.KeyPair,
    channel: []const u8,
) ![]const u8 {
    var raw: [Server.media_e2ee_handshake_v2_bytes]u8 = @splat(0x5a);
    raw[0] = 2;
    @memcpy(raw[1..17], &attachment);
    raw[17] = 0x04;
    raw[82] = 0x04;
    const identity_public = identity.public_key.toBytes();
    @memcpy(raw[179..211], &identity_public);
    var transcript_buf: [Server.media_e2ee_handshake_domain.len + client_model.MAX_CHANNEL_NAME_BYTES + 1 + Server.media_e2ee_handshake_unsigned_bytes]u8 = undefined;
    const transcript = Server.mediaE2eeHandshakeTranscript(channel, raw[0..Server.media_e2ee_handshake_unsigned_bytes], &transcript_buf).?;
    const signature = try identity.sign(transcript, null);
    const signature_bytes = signature.toBytes();
    @memcpy(raw[Server.media_e2ee_handshake_unsigned_bytes..], &signature_bytes);
    return std.base64.standard.Encoder.encode(out, &raw);
}

test "media E2EE handshake transcript ASCII-folds channel bytes without Unicode rewriting" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const Ed25519 = std.crypto.sign.Ed25519;
    const identity = try Ed25519.KeyPair.generateDeterministic(@as([Ed25519.KeyPair.seed_length]u8, @splat(0x79)));
    const attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0xa5);
    var encoded_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const encoded = try encodeTestMediaHandshake(&encoded_buf, attachment, identity, "%#\xc3\x84BC");
    var envelope: [Server.media_e2ee_handshake_v2_bytes]u8 = undefined;
    try std.base64.standard.Decoder.decode(&envelope, encoded);
    try std.testing.expect(Server.mediaE2eeHandshakeSignatureValid("%#\xc3\x84BC", &envelope));
    try std.testing.expect(Server.mediaE2eeHandshakeSignatureValid("%#\xc3\x84bc", &envelope));
    try std.testing.expect(!Server.mediaE2eeHandshakeSignatureValid("%#\xc3\xa4bc", &envelope));
}

fn sendTestMediaHandshake(fd: linux.fd_t, client: *LiveClient, channel: []const u8, handshake: []const u8, marker: []const u8) !void {
    var command_buf: [512]u8 = undefined;
    client.reset();
    try writeAllFd(fd, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE {s} :{s}\r\n", .{ channel, handshake }));
    try writeAllFd(fd, try std.fmt.bufPrint(&command_buf, "PING :{s}\r\n", .{marker}));
    var pong_buf: [128]u8 = undefined;
    const pong = try std.fmt.bufPrint(&pong_buf, "PONG onyx.local :{s}", .{marker});
    try recvUntil(client, pong, 200);
    try std.testing.expect(std.mem.indexOf(u8, client.written(), "FAIL MEDIA") == null);
}

fn saslOAuthBearerPrelude(fd: linux.fd_t, token: []const u8) ServerError!void {
    var raw: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(&raw, "n,,\x01auth=Bearer {s}\x01\x01", .{token}) catch return error.OutputTooSmall;
    var b64: [384]u8 = undefined;
    const enc = std.base64.standard.Encoder.encode(&b64, msg);
    var line: [512]u8 = undefined;
    try writeAllFd(fd, "CAP REQ :sasl\r\n");
    try writeAllFd(fd, "AUTHENTICATE OAUTHBEARER\r\n");
    try writeAllFd(fd, std.fmt.bufPrint(&line, "AUTHENTICATE {s}\r\n", .{enc}) catch return error.OutputTooSmall);
    try writeAllFd(fd, "CAP END\r\n");
}

fn connectLoopback(port: u16) ServerError!linux.fd_t {
    if (comptime builtin.os.tag == .openbsd) {
        // Test clients are blocking; the daemon's socketTcp helper deliberately
        // creates nonblocking OpenBSD sockets for reactor ownership.
        const fd = try connectNativeLoopbackForTest(.ipv4, port);
        errdefer closeFd(fd);
        // Bound direct TLS/WebSocket fixture reads as well as poll-driven IRC
        // reads. A missing reply must fail the runner rather than hang it.
        var timeout = posix.timeval{ .sec = 20, .usec = 0 };
        if (posix.errno(posix.system.setsockopt(fd, posix.SOL.SOCKET, posix.SO.RCVTIMEO, std.mem.asBytes(&timeout), @sizeOf(posix.timeval))) != .SUCCESS)
            return error.Unexpected;
        return fd;
    } else if (comptime builtin.os.tag == .linux) {
        const fd = try socketTcp();
        errdefer closeFd(fd);
        var addr = try sockaddrIn("127.0.0.1", port);
        const rc = linux.connect(fd, @ptrCast(&addr), @sizeOf(posix.sockaddr.in));
        switch (posix.errno(rc)) {
            .SUCCESS => return fd,
            .CONNREFUSED => return error.ConnectionRefused,
            .ACCES, .PERM => return error.PermissionDenied,
            else => return error.Unexpected,
        }
    } else return error.Unsupported;
}

fn connectNativeLoopbackForTest(family: ListenerFamily, port: u16) !linux.fd_t {
    if (comptime builtin.os.tag != .openbsd) return error.Unsupported;
    const rc = posix.system.socket(if (family == .ipv4) posix.AF.INET else posix.AF.INET6, posix.SOCK.STREAM | posix.SOCK.CLOEXEC, posix.IPPROTO.TCP);
    if (posix.errno(rc) != .SUCCESS) return error.SocketUnavailable;
    const fd: linux.fd_t = @intCast(rc);
    errdefer closeFd(fd);
    const result = if (family == .ipv4) blk: {
        var address = try sockaddrIn("127.0.0.1", port);
        break :blk posix.system.connect(fd, @ptrCast(&address), @sizeOf(posix.sockaddr.in));
    } else blk: {
        var address = try sockaddrIn6("::1", port);
        break :blk posix.system.connect(fd, @ptrCast(&address), @sizeOf(posix.sockaddr.in6));
    };
    if (posix.errno(result) != .SUCCESS) return error.Unexpected;
    return fd;
}

/// Deterministically stop a threaded server and join its reactor thread within a
/// bounded deadline. A throwaway SO_REUSEPORT connection only nudges the ONE
/// reactor the kernel happens to route it to, so on a multi-reactor server the
/// other reactors can stay blocked in `submitAndWait` forever and the unbounded
/// `pool.join()` never returns — the classic "several threads parked in
/// futex_do_wait" hang. `requestStop` avoids the lottery: it clears the run flag
/// AND writes every reactor's wake eventfd, so each blocked loop returns, re-reads
/// the flag, and exits. A watchdog turns any residual hang (a wake regression, or
/// an orphan `onyx-server`/`test` process from a force-killed prior run still holding a
/// loopback port) into a loud, bounded failure instead of an opaque futex park.
fn stopThreadedServer(server: *Server, run: *std.atomic.Value(bool), thr: std.Thread) void {
    server.requestStop(run);

    var joined = std.atomic.Value(bool).init(false);
    const Watchdog = struct {
        fn guard(done: *std.atomic.Value(bool)) void {
            const deadline = platform.monotonicMillis() + 30_000;
            while (!done.load(.acquire)) {
                if (platform.monotonicMillis() >= deadline) {
                    std.debug.print(
                        "\nstopThreadedServer: reactor thread did not stop within 30s — a " ++
                            "reactor is wedged in submitAndWait. Sweep stale `onyx-server`/`test` " ++
                            "processes holding a loopback port and re-run from a clean table.\n",
                        .{},
                    );
                    @panic("stopThreadedServer watchdog: reactor never stopped");
                }
                if (builtin.os.tag == .openbsd) {
                    os_runtime.sleepMillis(25);
                } else {
                    var req = linux.timespec{ .sec = 0, .nsec = 25 * std.time.ns_per_ms };
                    _ = linux.nanosleep(&req, null);
                }
            }
        }
    };
    const watchdog = std.Thread.spawn(.{}, Watchdog.guard, .{&joined}) catch {
        // No spare thread for the guard — fall back to a plain (unbounded) join.
        thr.join();
        return;
    };
    thr.join();
    joined.store(true, .release);
    watchdog.join();
}

fn writeAllFd(fd: linux.fd_t, bytes: []const u8) ServerError!void {
    var sent: usize = 0;
    if (comptime builtin.os.tag == .openbsd) {
        while (sent < bytes.len) {
            const rc = posix.system.write(fd, bytes[sent..].ptr, bytes.len - sent);
            switch (posix.errno(rc)) {
                .SUCCESS => {
                    if (rc == 0) return error.ConnectionReset;
                    sent += @intCast(rc);
                },
                .INTR => continue,
                .CONNRESET => return error.ConnectionReset,
                else => return error.Unexpected,
            }
        }
        return;
    }
    while (sent < bytes.len) {
        const rc = linux.write(fd, bytes[sent..].ptr, bytes.len - sent);
        switch (posix.errno(rc)) {
            .SUCCESS => sent += @intCast(rc),
            .CONNRESET => return error.ConnectionReset,
            else => return error.Unexpected,
        }
    }
}

fn readFd(fd: linux.fd_t, buf: []u8) ServerError!usize {
    const n = posix.read(fd, buf) catch |err| switch (err) {
        error.ConnectionResetByPeer => return error.ConnectionReset,
        error.WouldBlock => return error.Unexpected,
        else => return error.Unexpected,
    };
    return n;
}

fn closeFd(fd: linux.fd_t) void {
    if (comptime builtin.os.tag == .windows) {
        io_backend.closeSocket(fd);
        return;
    }
    if (comptime builtin.os.tag == .openbsd) {
        // kqueue drops registrations at close; no io_uring reference needs a
        // forced shutdown. SCM_RIGHTS copies share a socket with the serving
        // predecessor, so an aborted inert candidate must close only its copy.
        os_runtime.close(fd);
        return;
    }
    // Force FIN to the peer and complete any in-flight recv NOW. An io_uring
    // recv SQE holds a reference to the socket's `struct file`, so a bare
    // close(fd) only drops the fd-table entry — the socket lingers (no FIN)
    // until that pending op is canceled. shutdown() releases it immediately:
    // the peer sees EOF and the pending recv reaps with res=0 (its slot is
    // already freed, so the completion is harmlessly ignored).
    _ = linux.shutdown(fd, linux.SHUT.RDWR);
    _ = linux.close(fd);
}

const TestSink = struct {
    storage: []u8,
    used: usize = 0,

    fn write(self: *TestSink, bytes: []const u8) ServerError!void {
        if (self.used + bytes.len > self.storage.len) return error.OutputTooSmall;
        @memcpy(self.storage[self.used .. self.used + bytes.len], bytes);
        self.used += bytes.len;
    }

    fn written(self: *const TestSink) []const u8 {
        return self.storage[0..self.used];
    }
};

fn expectContains(haystack: []const u8, needle: []const u8) !void {
    try std.testing.expect(std.mem.indexOf(u8, haystack, needle) != null);
}

fn expectCodesInOrder(haystack: []const u8, codes: []const []const u8) !void {
    var pos: usize = 0;
    for (codes) |code| {
        const found = std.mem.indexOfPos(u8, haystack, pos, code) orelse return error.TestExpectedEqual;
        pos = found + code.len;
    }
}

fn expectDigitAfter(haystack: []const u8, marker: []const u8) !void {
    const pos = (std.mem.indexOf(u8, haystack, marker) orelse return error.TestExpectedEqual) + marker.len;
    try std.testing.expect(pos < haystack.len);
    try std.testing.expect(std.ascii.isDigit(haystack[pos]));
}

fn expectNoEmptyIrcLine(haystack: []const u8) !void {
    try std.testing.expect(std.mem.indexOf(u8, haystack, "\r\n\r\n") == null);
}

fn countOccurrences(haystack: []const u8, needle: []const u8) usize {
    var count: usize = 0;
    var pos: usize = 0;
    while (std.mem.indexOfPos(u8, haystack, pos, needle)) |found| {
        count += 1;
        pos = found + needle.len;
    }
    return count;
}

