fn countSliceForTest(hay: []const u8, needle: []const u8) usize {
    if (needle.len == 0 or hay.len < needle.len) return 0;
    var n: usize = 0;
    var i: usize = 0;
    while (i + needle.len <= hay.len) : (i += 1) {
        if (std.mem.eql(u8, hay[i..][0..needle.len], needle)) n += 1;
    }
    return n;
}

fn copyTaggedValueForTest(buf: []const u8, key: []const u8, out: []u8) ?[]const u8 {
    const at = std.mem.indexOf(u8, buf, key) orelse return null;
    const rest = buf[at + key.len ..];
    var end: usize = 0;
    while (end < rest.len) : (end += 1) {
        switch (rest[end]) {
            ';', ' ', '\r', '\n' => break,
            else => {},
        }
    }
    if (end == 0 or end > out.len) return null;
    @memcpy(out[0..end], rest[0..end]);
    return out[0..end];
}

