    const cfg = Config{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
        .crypto_io = std.testing.io,
    };
    const first = createTestServer(alloc, cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => {
            scram.deinit();
            binds.deinit();
            store.deinit();
            return error.SkipZigTest;
        },
        else => return err,
    };
    var verify_bytes: [16]u8 = @splat(0x31);
    const issued = try first.account_verifies.issue("alice", "alice@example.test", &verify_bytes, 10);
    var issued_copy: [64]u8 = undefined;
    try std.testing.expect(issued.len <= issued_copy.len);
    @memcpy(issued_copy[0..issued.len], issued);
    const issued_len = issued.len;
    var reset_token: [32]u8 = "0123456789abcdef0123456789abcdef".*;
    try first.reset_store.issue("alice", &reset_token, 10);

    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |blob| alloc.free(blob);
        blobs.deinit(alloc);
    }
    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(alloc);
    try appendCurrentMandatoryUpgradeStateForTest(first, &pieces, &blobs);

    first.deinit();
    alloc.destroy(first);
    scram.deinit();
    binds.deinit();
    store.deinit();

    var store2 = try services_mod.OroStore.open(alloc, std.testing.io, tmp.dir, "gap-d5-usr2.wal");
    defer store2.deinit();
    var scram2 = scram_store_mod.ScramStore.init(alloc);
    defer scram2.deinit();
    var binds2 = certfp_bind_mod.CertfpBindStore.init(alloc);
    defer binds2.deinit();
    var services2 = services_mod.Services.init(&store2, null);
    services2.attachScramStore(&scram2);
    services2.attachCertfpBinds(&binds2);
    scram2.setLoader(services2.scramLoader());
    var cfg2 = cfg;
    cfg2.account_services = &services2;
    const second = createTestServer(alloc, cfg2) catch |err| return err;
    defer alloc.destroy(second);
    defer second.deinit();
    try std.testing.expectEqual(account_verify_mod.Result.no_pending, second.account_verifies.confirm("alice", issued_copy[0..issued_len], 11));
    try std.testing.expectEqual(password_reset.Result.no_request, second.reset_store.confirm("alice", &reset_token, 11));

    _ = try adoptUpgradePiecesForTest(second, pieces.items, "onyx-test-gap-d5-usr2");
    current_reactor = null;
    try std.testing.expectEqual(account_verify_mod.Result.no_pending, second.account_verifies.confirm("alice", issued_copy[0..issued_len], 12));
    try std.testing.expectEqual(password_reset.Result.no_request, second.reset_store.confirm("alice", &reset_token, 12));

    second.config.sasl_scram256 = scram2.scram256Lookup();
    second.config.sasl_scram512 = scram2.scram512Lookup();
    try std.testing.expect(second.config.sasl_scram256.?.lookup("alice") != null);
    try std.testing.expect(second.config.sasl_scram512.?.lookup("alice") != null);
    var external = bridge.ServicesExternalLookup{ .services = &services2 };
    second.config.sasl_external = external.lookup();
    try std.testing.expectEqualStrings("alice", (second.config.sasl_external.?.verify(fp, "")).?);

    var conn = ConnState{};
    Server.loginSession(&conn, "alice");
    conn.session.tls_certfp = fp;
    try std.testing.expect(second.sessionCertVerifiedFor(&conn, "alice"));

    var again_bytes: [16]u8 = @splat(0x32);
    const again = try second.account_verifies.issue("alice", "alice@example.test", &again_bytes, 13);
    try std.testing.expect(again.len != 0);
    try std.testing.expect(!std.mem.eql(u8, again, issued_copy[0..issued_len]));
    try std.testing.expectEqual(account_verify_mod.Result.verified, second.account_verifies.confirm("alice", again, 14));
    var reset_again: [32]u8 = "fedcba9876543210fedcba9876543210".*;
    try second.reset_store.issue("alice", &reset_again, 13);
    try std.testing.expectEqual(password_reset.Result.ok, second.reset_store.confirm("alice", &reset_again, 14));
    std.debug.print("GAP-D5 branch=same-image USR2 invalidated the pre-crash verify and reset tokens, then SCRAM and CertFP still resolved and a new token confirmed\n", .{});
}

test "GAP-D6 daemon backup set verifies and restores into a scratch directory" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    const io = std.testing.io;
    defer current_reactor = null;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const wal_rel = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/gap-d6.wal", .{tmp.sub_path});
    defer alloc.free(wal_rel);
    const backup_rel = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/backup", .{tmp.sub_path});
    defer alloc.free(backup_rel);
    const scratch_rel = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/scratch", .{tmp.sub_path});
    defer alloc.free(scratch_rel);
    try std.Io.Dir.cwd().createDir(io, backup_rel, .default_dir);

    var store = try services_mod.OroStore.open(alloc, io, std.Io.Dir.cwd(), wal_rel);
    defer store.deinit();
    try store.put(.accounts, "d6acct", "plain-row");
    try store.put(.nicks, "d6nick", "nick-row");
    try store.put(.chanregs, "d6chan", "chan-row");
    try store.put(.bans, "shun:d6", "mute");
    try store.put(.memos, "d6memo", "memo-row");
    try store.put(.vhosts, "d6vh", "vhost-row");
    try store.put(.props, "d6prop", "prop-row");
    try store.put(.history, "d6hist", "history-row");
    var services = services_mod.Services.init(&store, null);
    const server = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
        .crypto_io = io,
        .backup_dir = backup_rel,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();
    try std.testing.expect(server.writeBackupSet(io));

    const manifest_path = try std.fmt.allocPrint(alloc, "{s}/latest.json", .{backup_rel});
    defer alloc.free(manifest_path);
    const text = try std.Io.Dir.cwd().readFileAlloc(io, manifest_path, alloc, .limited(1 << 20));
    defer alloc.free(text);
    for (backup_set.included_families) |name| {
        try std.testing.expect(std.mem.indexOf(u8, text, name) != null);
    }
    for (backup_set.excluded_families) |name| {
        try std.testing.expect(std.mem.indexOf(u8, text, name) != null);
    }
    try std.testing.expect(std.mem.indexOf(u8, text, "\"kind\":\"chanstats\"") == null);
    const verified = try backup_set.verify(alloc, text);
    defer verified.deinit(alloc);
    try std.testing.expect(std.mem.startsWith(u8, verified.accounts_name, "accounts-"));
    try std.testing.expect(std.mem.endsWith(u8, verified.accounts_name, ".db.snap"));

    try backup_set.restoreDrill(alloc, io, backup_rel, scratch_rel);
    const restored_wal = try std.fmt.allocPrint(alloc, "{s}/restored.wal", .{scratch_rel});
    defer alloc.free(restored_wal);
    var restored = try services_mod.OroStore.open(alloc, io, std.Io.Dir.cwd(), restored_wal);
    defer restored.deinit();
    const accounts = restored.get(.accounts, "d6acct") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("plain-row", accounts);
    const nicks = restored.get(.nicks, "d6nick") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("nick-row", nicks);
    const chanregs = restored.get(.chanregs, "d6chan") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("chan-row", chanregs);
    const bans = restored.get(.bans, "shun:d6") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("mute", bans);
    const memos = restored.get(.memos, "d6memo") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("memo-row", memos);
    const vhosts = restored.get(.vhosts, "d6vh") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("vhost-row", vhosts);
    const props = restored.get(.props, "d6prop") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("prop-row", props);
    const history = restored.get(.history, "d6hist") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("history-row", history);
    std.debug.print("GAP-D6 branch=daemon writeBackupSet listed the included and excluded families and restoreDrill reopened every family in a scratch directory\n", .{});
}

test "UPGRADE GAP-D1 cold restart restores history msgids and skips ciphertext search" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(alloc, std.testing.io, tmp.dir, "gap-d1.wal");
    var services = services_mod.Services.init(&store, null);
    const cfg = Config{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
        .crypto_io = std.testing.io,
    };
    const first = createTestServer(alloc, cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    first.recordHistoryRelayAt("#room", "alice!a@h", "chan-1", "PRIVMSG", "hello durableword", null, 10);
    first.recordHistoryRelayAt("$dm:nick:alice:bob", "alice!a@h", "dm-1", "PRIVMSG", "dm body", null, 11);
    first.recordHistoryRelayAt("#room", "alice!a@h", "e2ee-1", "PRIVMSG", "ONYXROOM1 secretphrase", "+onyx/e2ee=mls", 12);
    try std.testing.expect(first.search_index.find("durableword").len == 1);
    try std.testing.expect(first.search_index.find("secretphrase").len == 0);
    first.deinit();
    alloc.destroy(first);
    store.deinit();

    var store2 = try services_mod.OroStore.open(alloc, std.testing.io, tmp.dir, "gap-d1.wal");
    defer store2.deinit();
    var services2 = services_mod.Services.init(&store2, null);
    var cfg2 = cfg;
    cfg2.account_services = &services2;
    const second = createTestServer(alloc, cfg2) catch |err| return err;
    defer alloc.destroy(second);
    defer second.deinit();

    var out: [4]lotus.Message = undefined;
    const channel = try second.history.latest("#room", 4, &out);
    try std.testing.expectEqual(@as(usize, 2), channel.len);
    try std.testing.expectEqualStrings("e2ee-1", channel[0].msgid);
    try std.testing.expectEqualStrings("ONYXROOM1 secretphrase", channel[0].text);
    try std.testing.expectEqualStrings("chan-1", channel[1].msgid);
    var dm_out: [2]lotus.Message = undefined;
    const dm = try second.history.latest("$dm:nick:alice:bob", 2, &dm_out);
    try std.testing.expectEqual(@as(usize, 1), dm.len);
    try std.testing.expectEqualStrings("dm-1", dm[0].msgid);
    try std.testing.expectEqualStrings("dm body", dm[0].text);
    try std.testing.expect(second.search_index.find("durableword").len == 1);
    try std.testing.expect(second.search_index.find("secretphrase").len == 0);

    const lotus_wire = try second.history.encodeCheckpoint(alloc);
    defer alloc.free(lotus_wire);
    const search_wire = try second.search_index.encodeCheckpoint(alloc);
    defer alloc.free(search_wire);
    var event_writer = std.Io.Writer.Allocating.init(alloc);
    defer event_writer.deinit();
    try second.event_history.serializeInto(&event_writer.writer);
    const bundle = try history_checkpoint.encode(alloc, .{}, .{
        .lotus = lotus_wire,
        .search_index = search_wire,
        .event_history = event_writer.written(),
    });
    defer alloc.free(bundle);
    const payloads = try history_checkpoint.decode(.{}, bundle);
    var adopted = try HistoryStore.decodeCheckpoint(alloc, payloads.lotus);
    defer adopted.deinit();
    var adopted_msgs: [4]lotus.Message = undefined;
    const adopted_channel = try adopted.latest("#room", 4, &adopted_msgs);
    try std.testing.expectEqualStrings("chan-1", adopted_channel[1].msgid);
    try std.testing.expectEqualStrings("e2ee-1", adopted_channel[0].msgid);
}

test "GAP-D1 kill-restart restores channel and DM msgids" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
