    try gapP2Say(successor, later_id, later, "PRIVMSG", "s2");
    try expectContains(later.send_buf[0..later.send_len], "slowmode");
    try std.testing.expect(std.mem.indexOf(u8, later_ear.send_buf[0..later_ear.send_len], "PRIVMSG #slow :s2") == null);

    resetTestSendQ(later_voice);
    resetTestSendQ(later_ear);
    try gapP2Say(successor, later_voice_id, later_voice, "PRIVMSG", "sv1");
    try expectContains(later_ear.send_buf[0..later_ear.send_len], "PRIVMSG #slow :sv1");
    resetTestSendQ(later_voice);
    resetTestSendQ(later_ear);
    try gapP2Say(successor, later_voice_id, later_voice, "PRIVMSG", "sv2");
    try expectContains(later_voice.send_buf[0..later_voice.send_len], "slowmode");

    resetTestSendQ(later_oper);
    resetTestSendQ(later_ear);
    try gapP2Say(successor, later_oper_id, later_oper, "PRIVMSG", "so1");
    try gapP2Say(successor, later_oper_id, later_oper, "PRIVMSG", "so2");
    try expectContains(later_ear.send_buf[0..later_ear.send_len], "PRIVMSG #slow :so1");
    try expectContains(later_ear.send_buf[0..later_ear.send_len], "PRIVMSG #slow :so2");
    try std.testing.expect(std.mem.indexOf(u8, later_oper.send_buf[0..later_oper.send_len], "slowmode") == null);

    try successor.setChannelSlowmode("#slow", null);
    try std.testing.expectError(error.PropMissing, successor.props.getProp(channel, "SLOWMODE"));
    sim_after.advance(2_000);
    resetTestSendQ(later);
    resetTestSendQ(later_ear);
    try gapP2Say(successor, later_id, later, "PRIVMSG", "s3");
    try gapP2Say(successor, later_id, later, "PRIVMSG", "s4");
    try expectContains(later_ear.send_buf[0..later_ear.send_len], "PRIVMSG #slow :s3");
    try expectContains(later_ear.send_buf[0..later_ear.send_len], "PRIVMSG #slow :s4");

    std.debug.print("GAP-P2 branch=PROP SLOWMODE gap; oper exempt; SLOWVOICE gates voice; raid set and clear; configured gap restored by property checkpoint; in-window timer starts empty after adopt\n", .{});
}

fn gapP4Send(server: *Server, id: client_model.ClientId, conn: *ConnState, line: []const u8) !void {
    var parsed = try irc_line.parseLine(line);
    try server.handleMessage(id, conn, &parsed, parsed.command);
}

fn gapP4SearchHas(index: *search_index_mod.SearchIndex, word: []const u8, msgid: []const u8) bool {
    for (index.find(word)) |hit| {
        if (std.mem.eql(u8, hit, msgid)) return true;
    }
    return false;
}

fn gapP4BodyIndexed(index: *search_index_mod.SearchIndex, body: []const u8, msgid: []const u8) bool {
    const payload = if (std.mem.startsWith(u8, body, e2ee_policy.room_envelope_prefix))
        body[e2ee_policy.room_envelope_prefix.len..]
    else
        body;
    var start: ?usize = null;
    for (payload, 0..) |byte, index_at| {
        const word = std.ascii.isAlphanumeric(byte) or byte == '_';
        if (word) {
            if (start == null) start = index_at;
            continue;
        }
        if (start) |from| {
            if (gapP4SearchHas(index, payload[from..index_at], msgid)) return true;
            start = null;
        }
    }
    if (start) |from| return gapP4SearchHas(index, payload[from..], msgid);
    return false;
}

fn gapP4RoomBody(raw: *const [33]u8, out: []u8) []const u8 {
    const prefix = e2ee_policy.room_envelope_prefix;
    @memcpy(out[0..prefix.len], prefix);
    const payload = std.base64.url_safe_no_pad.Encoder.encode(out[prefix.len..], raw);
    return out[0 .. prefix.len + payload.len];
}

fn gapP4Newest(server: *Server, target: []const u8, id_out: []u8) !struct { id: []const u8, text: []const u8 } {
    var msgs: [1]lotus.Message = undefined;
    const found = try server.history.latest(target, 1, &msgs);
    if (found.len == 0 or found[0].msgid.len > id_out.len) return error.NotFound;
    @memcpy(id_out[0..found[0].msgid.len], found[0].msgid);
    return .{ .id = id_out[0..found[0].msgid.len], .text = found[0].text };
}

test "DST GAP-P4 channel retention TTL deletes history search ids and memo copies" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    const server = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();
    current_reactor = &server.reactors[0];
    var sim = reactor_mod.SimReactor.init(5_000_000);
    server.reactor = sim.reactor();

    const founder_id = try addTestLocalClient(server, "Founder", "founder");
    const member_id = try addTestLocalClient(server, "Member", "member");
    const founder = server.connFor(founder_id).?;
    const member = server.connFor(member_id).?;
    founder.ircx = true;
    member.ircx = true;
    founder.session.addCap(.message_tags);

    _ = try server.world.join("#retain", worldIdFromClient(founder_id));
    _ = try server.world.join("#secret", worldIdFromClient(founder_id));
    _ = try server.world.join("#plain", worldIdFromClient(founder_id));
    _ = try server.world.join("#eph", worldIdFromClient(founder_id));
    _ = try server.world.join("#retain", worldIdFromClient(member_id));

    const retain = ircx_prop_store.Entity{ .kind = .channel, .id = "#retain" };
    const secret = ircx_prop_store.Entity{ .kind = .channel, .id = "#secret" };

    var bad_text = try irc_line.parseLine("PROP #retain RETAIN :nope");
    try server.handleProp(founder_id, founder, &bad_text);
    try expectContains(founder.send_buf[0..founder.send_len], "Invalid property value");
    resetTestSendQ(founder);
    var bad_low = try irc_line.parseLine("PROP #retain RETAIN :59");
    try server.handleProp(founder_id, founder, &bad_low);
    try expectContains(founder.send_buf[0..founder.send_len], "Invalid property value");
    resetTestSendQ(founder);
    var bad_high = try irc_line.parseLine("PROP #retain RETAIN :2592001");
    try server.handleProp(founder_id, founder, &bad_high);
    try expectContains(founder.send_buf[0..founder.send_len], "Invalid property value");
    resetTestSendQ(founder);
    try std.testing.expectError(error.PropMissing, server.props.getProp(retain, "RETAIN"));

    var steal = try irc_line.parseLine("PROP #retain RETAIN :60");
    try server.handleProp(member_id, member, &steal);
    try expectContains(member.send_buf[0..member.send_len], "Insufficient access");
    try std.testing.expectError(error.PropMissing, server.props.getProp(retain, "RETAIN"));

    var set_retain = try irc_line.parseLine("PROP #retain RETAIN :60");
    try server.handleProp(founder_id, founder, &set_retain);
    try std.testing.expectEqualStrings("60", (try server.props.getProp(retain, "RETAIN")).value);
    var set_secret = try irc_line.parseLine("PROP #secret RETAIN :60");
    try server.handleProp(founder_id, founder, &set_secret);
    try std.testing.expectEqualStrings("60", (try server.props.getProp(secret, "RETAIN")).value);
    var set_eph = try irc_line.parseLine("PROP #eph EPHEMERAL :60");
    try server.handleProp(founder_id, founder, &set_eph);
    var set_policy = try irc_line.parseLine("PROP #secret encryption-policy :required");
    try server.handleProp(founder_id, founder, &set_policy);
    try std.testing.expectEqual(e2ee_policy.Policy.required, server.channelEncryptionPolicy("#secret"));

    resetTestSendQ(founder);
    try gapP4Send(server, founder_id, founder, "PRIVMSG #secret :not-ciphertext");
    try expectContains(founder.send_buf[0..founder.send_len], "E2EE_REQUIRED");
    try std.testing.expectEqual(@as(usize, 0), try server.history.storedCount("#secret"));

    var first_raw: [33]u8 = @splat(0);
    first_raw[0] = 1;
    var first_body_buf: [96]u8 = undefined;
    const first_body = gapP4RoomBody(&first_raw, &first_body_buf);
    try std.testing.expect(e2ee_policy.isCanonicalRoomEnvelope(first_body));
    var first_line_buf: [160]u8 = undefined;
    const first_line = try std.fmt.bufPrint(&first_line_buf, "@+onyx/e2ee=mls PRIVMSG #secret :{s}", .{first_body});

    try gapP4Send(server, founder_id, founder, "PRIVMSG #retain :p4expireword");
    try gapP4Send(server, founder_id, founder, "PRIVMSG #plain :p4stayword");
    try gapP4Send(server, founder_id, founder, "PRIVMSG #eph :p4ephword");
    resetTestSendQ(founder);
    try gapP4Send(server, founder_id, founder, first_line);
    try std.testing.expect(std.mem.indexOf(u8, founder.send_buf[0..founder.send_len], "E2EE_REQUIRED") == null);

    var plain_id_buf: [64]u8 = undefined;
    var cipher_id_buf: [64]u8 = undefined;
    const plain_row = try gapP4Newest(server, "#retain", &plain_id_buf);
    const cipher_row = try gapP4Newest(server, "#secret", &cipher_id_buf);
    const plain_id = plain_row.id;
    const cipher_id = cipher_row.id;
    try std.testing.expectEqualStrings("p4expireword", plain_row.text);
    try std.testing.expectEqualStrings(first_body, cipher_row.text);
    try std.testing.expect(gapP4SearchHas(&server.search_index, "p4expireword", plain_id));
    try std.testing.expect(!gapP4BodyIndexed(&server.search_index, first_body, cipher_id));

    _ = try server.storeOfflineMemo("p4box", "Founder", "p4expireword", 1);
    _ = try server.storeOfflineMemo("p4box", "Founder", first_body, 1);
    _ = try server.storeOfflineMemo("p4box", "Founder", "independent-note", 1);
    _ = try server.storeOfflineMemo("p4box", "Founder", "plaintext-the-daemon-never-saw", 1);
    _ = try server.storeOfflineMemo("p4other", "Founder", "p4expireword", 1);
    try std.testing.expectEqual(@as(usize, 4), server.memo.count("p4box"));
    try std.testing.expectEqual(@as(usize, 1), server.memo.count("p4other"));

    server.expireRetainedHistory();
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#retain"));
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#secret"));
    try std.testing.expectEqual(@as(usize, 4), server.memo.count("p4box"));

    sim.advance(60_000);
    server.expireRetainedHistory();
    try std.testing.expectEqual(@as(usize, 0), try server.history.storedCount("#retain"));
    try std.testing.expectEqual(@as(usize, 0), try server.history.storedCount("#secret"));
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#plain"));
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#eph"));
    try std.testing.expect(server.history.timestampOf("#retain", plain_id) == null);
    try std.testing.expect(server.history.timestampOf("#secret", cipher_id) == null);
    try std.testing.expectEqual(@as(usize, 0), server.search_index.find("p4expireword").len);
    try std.testing.expect(server.search_index.find("p4stayword").len != 0);
    try std.testing.expect(server.search_index.find("p4ephword").len != 0);
    try std.testing.expectEqual(@as(usize, 0), server.memo.count("p4other"));
    const kept = server.memo.pending("p4box");
    try std.testing.expectEqual(@as(usize, 2), kept.len);
    var saw_note = false;
    var saw_unknown = false;
    for (kept) |memo| {
        try std.testing.expect(!std.mem.eql(u8, memo.text, "p4expireword"));
        try std.testing.expect(!std.mem.startsWith(u8, memo.text, e2ee_policy.room_envelope_prefix));
        if (std.mem.eql(u8, memo.text, "independent-note")) saw_note = true;
        if (std.mem.eql(u8, memo.text, "plaintext-the-daemon-never-saw")) saw_unknown = true;
    }
    try std.testing.expect(saw_note and saw_unknown);
    const history_wire = try server.history.encodeCheckpoint(alloc);
    defer alloc.free(history_wire);

    try gapP4Send(server, founder_id, founder, "PRIVMSG #retain :p4keeperword");
    var second_raw: [33]u8 = @splat(0);
    second_raw[0] = 1;
    second_raw[10] = 7;
    var second_body_buf: [96]u8 = undefined;
    const second_body = gapP4RoomBody(&second_raw, &second_body_buf);
    try std.testing.expect(e2ee_policy.isCanonicalRoomEnvelope(second_body));
    try std.testing.expect(!std.mem.eql(u8, first_body, second_body));
    var second_line_buf: [160]u8 = undefined;
    const second_line = try std.fmt.bufPrint(&second_line_buf, "@+onyx/e2ee=mls PRIVMSG #secret :{s}", .{second_body});
    try gapP4Send(server, founder_id, founder, second_line);
    server.expireRetainedHistory();
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#retain"));
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#secret"));
    try std.testing.expect(server.search_index.find("p4keeperword").len != 0);
    var keeper_cipher_buf: [64]u8 = undefined;
    const keeper_cipher = try gapP4Newest(server, "#secret", &keeper_cipher_buf);
    try std.testing.expectEqualStrings(second_body, keeper_cipher.text);
    try std.testing.expect(!gapP4BodyIndexed(&server.search_index, second_body, keeper_cipher.id));

    var clear_retain = try irc_line.parseLine("PROP #retain RETAIN :0");
    try server.handleProp(founder_id, founder, &clear_retain);
    try std.testing.expectEqualStrings("0", (try server.props.getProp(retain, "RETAIN")).value);
    var clear_secret = try irc_line.parseLine("PROP #secret RETAIN :0");
    try server.handleProp(founder_id, founder, &clear_secret);
    sim.advance(60_000);
    server.expireRetainedHistory();
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#retain"));
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#secret"));
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#plain"));
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#eph"));
    try std.testing.expect(server.search_index.find("p4keeperword").len != 0);

    var drop_retain = try irc_line.parseLine("PROP #retain RETAIN :");
    try server.handleProp(founder_id, founder, &drop_retain);
    try std.testing.expectError(error.PropMissing, server.props.getProp(retain, "RETAIN"));
    server.expireRetainedHistory();
    try std.testing.expectEqual(@as(usize, 1), try server.history.storedCount("#retain"));

    std.debug.print("GAP-P4 branch=PROP RETAIN ttl; expiry deletes the lotus row, search id, and memo copies; ciphertext expires without plaintext\n", .{});
}

const O6Remote = struct {
    kind: s2s_peer_mod.S2sPeer.MembershipDelta.Kind,
    nick: []const u8,
    username: []const u8 = "u",
    realname: []const u8 = "",
    host: []const u8 = "remote.test",
    channel: []const u8,
    status: u4 = 0,
    prev_status: u4 = 0,
    setter: []const u8 = "",
    account: []const u8 = "",
};

fn gapO6Remote(server: *Server, channel: []const u8, remote: []const u8, nick: []const u8) void {
    server.emitRemoteMembership(O6Remote{
        .kind = .joined,
        .nick = nick,
        .host = remote,
        .channel = channel,
    }, remote);
}

fn gapO6Join(server: *Server, id: client_model.ClientId, conn: *ConnState, channel: []const u8) !void {
    var buf: [64]u8 = undefined;
    const line = try std.fmt.bufPrint(&buf, "JOIN {s}", .{channel});
    var parsed = try irc_line.parseLine(line);
    try server.handleJoin(id, conn, &parsed);
}

fn gapO6FloodVerdicts(server: *Server, needle: []const u8) usize {
    var buf: [8]event_history_mod.StoredEvent = undefined;
    const n = server.event_history.collect(
        @intFromEnum(event_spine.EventCategory.flood),
        @intFromEnum(event_spine.EventSeverity.warn),
        &buf,
    );
    var count: usize = 0;
    for (buf[0..n]) |ev| {
        if (!ev.has_event_id) continue;
        if (std.mem.indexOf(u8, ev.message(), needle) == null) continue;
        count += 1;
    }
    return count;
}

test "DST GAP-O6 raid shield correlates peers and relaxes slowmode" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x06)), "o6.test");
    defer ident.deinit();
    const server = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_port = 0,
        .crypto_io = std.testing.io,
        .server_name = "o6.test",
        .node_identity = &ident,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();
    current_reactor = &server.reactors[0];
    var sim = reactor_mod.SimReactor.init(5_000_000);
    server.reactor = sim.reactor();

    const popular_nicks = [_][]const u8{ "o6p0", "o6p1", "o6p2", "o6p3", "o6p4", "o6p5" };
    const noted_before = server.raid_shield.noted;
    var popular_ids: [popular_nicks.len]client_model.ClientId = undefined;
    for (popular_nicks, 0..) |nick, index| {
        popular_ids[index] = try addTestLocalClient(server, nick, null);
    }
    for (popular_ids) |id| {
        try gapO6Join(server, id, server.connFor(id).?, "#popular");
    }
    try std.testing.expect(server.raid_shield.noted >= noted_before + popular_nicks.len);
    try std.testing.expect(server.raid_shield.joins.estimate("#popular") >= popular_nicks.len);
    server.onTimerTick();
    const popular = ircx_prop_store.Entity{ .kind = .channel, .id = "#popular" };
    try std.testing.expectError(error.PropMissing, server.props.getProp(popular, "SLOWMODE"));
    try std.testing.expectEqual(@as(usize, 0), gapO6FloodVerdicts(server, "raid shield"));

    gapO6Remote(server, "#trickle", "peer-a.test", "ta");
    gapO6Remote(server, "#trickle", "peer-b.test", "tb");
    gapO6Remote(server, "#trickle", "peer-c.test", "tc");
    server.onTimerTick();
    const trickle = ircx_prop_store.Entity{ .kind = .channel, .id = "#trickle" };
    try std.testing.expectError(error.PropMissing, server.props.getProp(trickle, "SLOWMODE"));

    const founder = try addTestLocalClient(server, "o6found", null);
    try gapO6Join(server, founder, server.connFor(founder).?, "#raid");

    var batch = [_]O6Remote{
        .{ .kind = .joined, .nick = "batch1", .channel = "#raid", .host = "peer-a.test" },
        .{ .kind = .joined, .nick = "batch2", .channel = "#raid", .host = "peer-a.test" },
    };
    server.emitNetjoinRun("#raid", "peer-a.test", &batch);
    const raid_peers = [_][]const u8{ "peer-a.test", "peer-b.test", "peer-c.test" };
    const raid_nicks = [_][]const u8{ "ra1", "ra2", "rb1", "rb2", "rc1", "rc2" };
    for (raid_nicks, 0..) |nick, index| {
        gapO6Remote(server, "#raid", raid_peers[index / 2], nick);
    }
    server.onTimerTick();
    const raid = ircx_prop_store.Entity{ .kind = .channel, .id = "#raid" };
    const engaged = try server.props.getProp(raid, "SLOWMODE");
    try std.testing.expectEqualStrings("10", engaged.value);
    try std.testing.expectEqualStrings("raid-shield", engaged.owner);
    try std.testing.expectEqual(@as(usize, 1), gapO6FloodVerdicts(server, "#raid"));

    const late = try addTestLocalClient(server, "o6late", null);
    try gapO6Join(server, late, server.connFor(late).?, "#raid");
    try std.testing.expect(server.world.isMember("#raid", worldIdFromClient(late)));
    server.onTimerTick();
    try std.testing.expectEqual(@as(usize, 1), gapO6FloodVerdicts(server, "#raid"));
    try std.testing.expectEqualStrings("10", (try server.props.getProp(raid, "SLOWMODE")).value);

    sim.advance(raid_shield.relax_after_ms);
    server.onTimerTick();
    try std.testing.expectError(error.PropMissing, server.props.getProp(raid, "SLOWMODE"));
    try std.testing.expectEqual(@as(usize, 1), gapO6FloodVerdicts(server, "#raid"));
    try std.testing.expectError(error.PropMissing, server.props.getProp(popular, "SLOWMODE"));

    var extra: usize = 0;
    while (extra < raid_shield.max_channels + 40) : (extra += 1) {
        var name_buf: [32]u8 = undefined;
        const name = try std.fmt.bufPrint(&name_buf, "#s{d}", .{extra});
        server.noteRaidJoin(name, "peer-a.test");
    }
    var origin_i: usize = 0;
    while (origin_i < 80) : (origin_i += 1) {
        var origin_buf: [32]u8 = undefined;
        const origin = try std.fmt.bufPrint(&origin_buf, "scale-peer-{d}", .{origin_i});
        server.noteRaidJoin("#scale", origin);
    }
    try std.testing.expect(server.raid_shield.channelCount() <= raid_shield.max_channels);
    try std.testing.expectEqual(raid_shield.sketch_width * raid_shield.sketch_depth, server.raid_shield.sketchCells());
    try std.testing.expectEqual(raid_shield.hottest_capacity, server.raid_shield.hottest.capacity());

    const tail = try addTestLocalClient(server, "o6tail", null);
    try gapO6Join(server, tail, server.connFor(tail).?, "#tail");
    try std.testing.expect(server.world.isMember("#tail", worldIdFromClient(tail)));

    std.debug.print("GAP-O6 branch=reactor 0 correlates peer joins; one signed flood verdict; slowmode engages and relaxes; one origin does not trip\n", .{});
}

test "UPGRADE mandatory restored EventHistory and webhook store skip stale disk reload at start" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const event_path = try rehashTmpPath(alloc, tmp, "event-history.snapshot");
    defer alloc.free(event_path);
    const webhook_path = try rehashTmpPath(alloc, tmp, "webhooks.tsv");
    defer alloc.free(webhook_path);

    var disk_events = event_history_mod.EventHistory(512){};
    disk_events.record(1, 1, 1, "disk.node", "stale disk event");
    var event_writer = std.Io.Writer.Allocating.init(alloc);
    defer event_writer.deinit();
    try disk_events.serializeInto(&event_writer.writer);
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "event-history.snapshot",
        .data = event_writer.written(),
    });

    var disk_webhooks = webhook_mod.WebhookStore.init();
    _ = try disk_webhooks.create(
        "#disk",
        "stale disk hook",
        "disk",
        1,
        1,
        .{ .per_min = 60, .burst = 10 },
        @splat(0x91),
        @splat(0x92),
    );
    var webhook_text: std.ArrayList(u8) = .empty;
    defer webhook_text.deinit(alloc);
    try disk_webhooks.serialize(alloc, &webhook_text);
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "webhooks.tsv",
        .data = webhook_text.items,
    });

    var server = Server.init(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_port = 0,
        .crypto_io = std.testing.io,
        .event_history_path = event_path,
        .webhook_enabled = true,
        .webhook_port = 0,
        .webhook_store_path = webhook_path,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    server.event_history.record(2, 2, 2, "inherited.node", "authoritative inherited event");
    _ = try server.webhook_store.create(
        "#inherited",
        "authoritative hook",
        "inherited",
        2,
        2,
        .{ .per_min = 60, .burst = 10 },
        @splat(0x81),
        @splat(0x82),
    );
    server.inherited_event_history_restored = true;
    server.inherited_webhook_store_restored = true;

    server.start();

    var events: [4]event_history_mod.StoredEvent = undefined;
    const event_count = server.event_history.collect(null, 0, &events);
    try std.testing.expectEqual(@as(usize, 1), event_count);
    try std.testing.expectEqualStrings("authoritative inherited event", events[0].message());
    try std.testing.expectEqual(@as(usize, 1), server.webhook_store.len());
    var inherited_entries: [2]webhook_mod.ListEntry = undefined;
    try std.testing.expectEqual(@as(usize, 1), server.webhook_store.list("#inherited", &inherited_entries));
    var disk_entries: [2]webhook_mod.ListEntry = undefined;
    try std.testing.expectEqual(@as(usize, 0), server.webhook_store.list("#disk", &disk_entries));
}

test "UPGRADE exact client adoption failure is startup fatal and restores displaced World" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var predecessor = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer predecessor.deinit();
    const predecessor_client = try addTestLocalClient(&predecessor, "fatal-client", null);
    _ = try predecessor.world.join("#fatal", worldIdFromClient(predecessor_client));
    const fatal_modes = predecessor.world.memberModes("#fatal", worldIdFromClient(predecessor_client)).?.bits;

    var sockets: [2]linux.fd_t = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets)) != .SUCCESS)
        return error.SkipZigTest;
    var inherited_socket_open = true;
    defer if (inherited_socket_open) closeFd(sockets[0]);
    defer closeFd(sockets[1]);
    // Current World checkpoints key physical member relations by the carried
    // connection fd. Give the predecessor fixture the same live join key used
    // by the deliberately-invalid client capsule below, then relinquish it once
    // the checkpoint has been sealed (execve would transfer that ownership).
    const predecessor_conn = predecessor.rx().clients.get(predecessor_client).?;
    predecessor_conn.fd = sockets[0];
    defer {
        if (predecessor_conn.fd == sockets[0]) predecessor_conn.fd = -1;
    }
    const client_wire = try session_snapshot.encode(alloc, .{
        .nick = "fatal-client",
        .realname = "Fatal Client",
        .fd = sockets[0],
        .was_secured = true,
        // Deliberately omit the matching TLS capsule. Exact adoption must fail
        // startup after publication, never expose this socket as plaintext.
        .channels = &.{.{ .name = "#fatal", .modes = fatal_modes }},
    });
    defer alloc.free(client_wire);

    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |blob| alloc.free(blob);
        blobs.deinit(alloc);
    }
    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(alloc);
    try appendCurrentMandatoryUpgradeStateForTest(&predecessor, &pieces, &blobs);
    predecessor_conn.fd = -1;
    try pieces.append(alloc, .{ .kind = .clients, .bytes = client_wire });

    var prepared = try helix_live.prepare(alloc, .{
        .epoch = 1,
        .now_ms = 1,
        .timeout_ms = 1000,
        .arena_name = "onyx-test-client-fatal",
        .pieces = pieces.items,
        .fds = &.{},
    });
    defer prepared.deinit();
    const dup_rc = linux.dup(prepared.runtime.arena.?.fd);
    if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
    const arena_dup: linux.fd_t = @intCast(dup_rc);
    var arena_open = true;
    defer if (arena_open) closeFd(arena_dup);

    var successor = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer successor.deinit();
    _ = try successor.world.markRegistered("#old-world", true);
    successor.config.resume_arena_fd = arena_dup;
    try std.testing.expectError(error.InvalidInheritedHandoff, successor.adoptInheritedSessions());
    inherited_socket_open = false; // the secured-without-TLS fail-safe closed it
    current_reactor = null;

    // The whole-handoff relation catches the missing TLS join before ANY
    // publication. Startup fails, the inherited socket is closed, and every
    // fresh-boot authority remains untouched.
    try std.testing.expect(!successor.inherited_event_history_restored);
    try std.testing.expect(!successor.inherited_webhook_store_restored);
    try std.testing.expect(successor.world.channelExists("#old-world"));
    try std.testing.expect(!successor.world.channelExists("#fatal"));
    try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(sockets[0], posix.F.GETFD, 0)));

    closeFd(arena_dup);
    arena_open = false;
    successor.config.resume_arena_fd = null;
}

fn fixedHexAfter(haystack: []const u8, marker: []const u8, hex_len: usize) ?[]const u8 {
    const start = (std.mem.indexOf(u8, haystack, marker) orelse return null) + marker.len;
    if (start + hex_len > haystack.len) return null;
    const out = haystack[start .. start + hex_len];
    for (out) |ch| {
        if (!std.ascii.isHex(ch)) return null;
    }
    return out;
}

fn addTestLocalClient(server: *Server, nick: []const u8, account: ?[]const u8) !client_model.ClientId {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const id = try server.rx().clients.alloc(ConnState.init(-1));
        const conn = server.rx().clients.get(id).?;
        conn.token = try tokenFromId(id);
        // Match the production accept path: tests that exercise a real SendQ
        // overflow must have an allocator for the heap-backed tail.
        conn.overflow_allocator = server.allocator;
        // These clients have no socket and their tests inspect the retained
        // SendQ. Native kqueue rejects fd=-1 immediately; declare the fixture
        // sink instead of attempting an operation or inventing kernel custody.
        if (comptime builtin.is_test and builtin.os.tag == .openbsd)
            conn.test_sendq_capture = true;
        try conn.session.setNick(nick);
        if (account) |acct| conn.session.loginAs(acct);
        try server.world.registerNick(nick, worldIdFromClient(id));
        if (account != null) server.trackSession(id, conn);
        return id;
    } else return error.SkipZigTest;
}

/// Install roster-backed sender-home authority for tests that call the legacy
/// relay-v1 delivery boundary directly. Production only accepts such a relay
/// after membership convergence; keeping that precondition explicit in the
/// fixture prevents policy tests from accidentally exercising an unknown-home
/// drop instead of the delivery rule they intend to cover.
fn addTestRelayHomes(
    server: *Server,
    peer: *s2s_link.S2sLink,
    origin_node: s2s_link.NodeId,
    nicks: []const []const u8,
) !void {
    const alloc = std.testing.allocator;
    try peer.init(.{
        .allocator = alloc,
        .local_node_id = origin_node,
        .remote_node_id = server.config.node_id,
        .local_epoch_ms = 1000,
        .server_name = "relay-origin.test",
        .config = .{ .require_signed_frames = false },
    });
    errdefer peer.deinit();
    const link = try alloc.create(s2s_link.S2sLink);
    var server_owns_link = false;
    errdefer if (!server_owns_link) alloc.destroy(link);
    try link.init(.{
        .allocator = alloc,
        .local_node_id = server.config.node_id,
        .remote_node_id = origin_node,
        .local_epoch_ms = 1001,
        .server_name = "relay-receiver.test",
        .config = .{ .require_signed_frames = false },
    });
    errdefer if (!server_owns_link) link.deinit();
    const link_id = try server.rx().clients.alloc(ConnState.init(-1));
    server.rx().clients.get(link_id).?.s2s = link;
    server_owns_link = true;

    try peer.start(50);
    for (nicks, 0..) |nick, index| try peer.sendMembership(
        "#relay-home",
        nick,
        0,
        100 + index,
        true,
        .{ .username = "relay", .host = "origin.test" },
        "",
    );
    try pumpLinkPair(peer, link, alloc);
    try std.testing.expect(link.established());
    for (nicks) |nick| try std.testing.expectEqual(origin_node, server.meshNickHomeNode(nick).?);
}

test "verified webhook residence bypass is restricted to server-authored channel PRIVMSG" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    var relay_peer: s2s_link.S2sLink = undefined;
    try addTestRelayHomes(&server, &relay_peer, 99, &.{"Remote"});
    defer relay_peer.deinit();

    const base = s2s_link.RelayMessage{
        .verb = .privmsg,
        .target = "#room",
        .source_nick = "CI-Bot",
        .source_prefix = "CI-Bot!webhook@relay-origin.test",
        .text = "build passed",
        .origin_node = 99,
        .hlc = 1,
    };
    try std.testing.expect(server.isVerifiedWebhookRelay(base, .verified));
    try std.testing.expect(!server.isVerifiedWebhookRelay(base, .unsigned));

    var direct = base;
    direct.target = "Victim";
    try std.testing.expect(!server.isVerifiedWebhookRelay(direct, .verified));
    var notice = base;
    notice.verb = .notice;
    try std.testing.expect(!server.isVerifiedWebhookRelay(notice, .verified));
    var typed = base;
    typed.data_tag = "comic";
    try std.testing.expect(!server.isVerifiedWebhookRelay(typed, .verified));
}

/// Most legacy server fixtures predate physical attachment identifiers. SESSION
/// SID tests must opt into the production-only stable row identity explicitly;
/// a null attachment intentionally has no public SID.
fn assignTestSessionAttachment(server: *Server, account: []const u8, id: client_model.ClientId, marker: u8) !void {
    const cid = monitorIdFromClient(id);
    const rows = try server.sessions.copySessionsAlloc(std.testing.allocator, account);
    defer std.testing.allocator.free(rows);
    const old = for (rows) |row| {
        if (row.client == cid) break row;
    } else return error.TestUnexpectedResult;
    try std.testing.expect(server.sessions.remove(account, cid));
    const attachment = try sessions_mod.AttachmentId.fromBytes(@as([16]u8, @splat(marker)));
    _ = try server.sessions.attachWithAttachment(account, cid, old.token, attachment, old.signon_ms);
}

test "remote QUIT marked mesh departures render once per local recipient across shared channels" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    current_reactor = &server.reactors[0];
    const both_id = try addTestLocalClient(&server, "BothWatcher", null);
    const later_id = try addTestLocalClient(&server, "LaterWatcher", null);
    const both = server.connFor(both_id).?;
    const later = server.connFor(later_id).?;
    both.session.registration.registered = true;
    later.session.registration.registered = true;
    try server.world.restoreMember("#first", worldIdFromClient(both_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#later", worldIdFromClient(both_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#later", worldIdFromClient(later_id), world_model.MemberModes.empty());
    resetTestSendQ(both);
    resetTestSendQ(later);

    const Delta = struct {
        channel: []const u8,
        nick: []const u8 = "Remote",
        username: []const u8 = "remote",
        realname: []const u8 = "Connection reset",
        host: []const u8 = "remote.example",
        setter: []const u8 = mesh_quit_setter,
        account: []const u8 = "",
        kind: s2s_peer_mod.S2sPeer.MembershipDelta.Kind = .parted,
        status: u4 = 0,
        prev_status: u4 = 0,
    };

    // Presence arrives first but has no channel audience and must not consume
    // the recipient-local dedup slot.
    const presence = Delta{ .channel = presence_channel };
    server.emitRemoteQuit(&presence, "origin.example");
    try std.testing.expectEqual(@as(usize, 0), both.send_len);
    try std.testing.expectEqual(@as(usize, 0), later.send_len);

    const first = Delta{ .channel = "#first" };
    server.emitRemoteMembership(&first, "origin.example");
    try std.testing.expectEqual(
        @as(usize, 1),
        countOccurrences(both.send_buf[0..both.send_len], " QUIT :Connection reset\r\n"),
    );
    try std.testing.expectEqual(@as(usize, 0), later.send_len);

    const later_delta = Delta{ .channel = "#later" };
    server.emitRemoteMembership(&later_delta, "origin.example");
    try std.testing.expectEqual(
        @as(usize, 1),
        countOccurrences(both.send_buf[0..both.send_len], " QUIT :Connection reset\r\n"),
    );
    try std.testing.expectEqual(
        @as(usize, 1),
        countOccurrences(later.send_buf[0..later.send_len], " QUIT :Connection reset\r\n"),
    );

    resetTestSendQ(both);
    const ordinary_part = .{
        .channel = "#first",
        .nick = "Remote",
        .username = "remote",
        .realname = "",
        .host = "remote.example",
        .setter = "",
        .account = "",
        .kind = s2s_peer_mod.S2sPeer.MembershipDelta.Kind.parted,
        .status = @as(u4, 0),
        .prev_status = @as(u4, 0),
    };
    server.emitRemoteMembership(&ordinary_part, "origin.example");
    try std.testing.expectEqual(
        @as(usize, 1),
        countOccurrences(both.send_buf[0..both.send_len], " PART #first\r\n"),
    );
}

const LiveClient = struct {
    fd: linux.fd_t,
    buf: [default_reply_bytes]u8 = undefined,
    len: usize = 0,

    fn readAvailable(self: *LiveClient) ServerError!void {
        if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
            while (true) {
                var fds = [_]posix.pollfd{.{
                    .fd = self.fd,
                    .events = posix.POLL.IN,
                    .revents = 0,
                }};
                const ready = posix.poll(&fds, 0) catch return error.Unexpected;
                if (ready == 0 or (fds[0].revents & posix.POLL.IN) == 0) return;
                if (self.len == self.buf.len) return error.OutputTooSmall;
                const n = try readFd(self.fd, self.buf[self.len..]);
                if (n == 0) return;
                self.len += n;
            }
        } else return error.Unsupported;
    }

    fn written(self: *const LiveClient) []const u8 {
        return self.buf[0..self.len];
    }

    fn reset(self: *LiveClient) void {
        self.len = 0;
    }
};

test "rebroadcastLocalOpers re-mints an oper homed on a non-zero shard" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .num_shards = 2 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        try std.testing.expectEqual(@as(usize, 2), server.reactors.len);

        // Home an opered, registered, logged-in session on reactor 1 — NOT the
        // reactor-0 table the relink re-propagation scan was once limited to.
        // A connection is pinned to its shard for life, so a shard-1 oper that
        // the scan misses is never re-propagated on relink/RESYNC/repair and a
        // restarted peer never learns the grant (its `*` silently missing).
        const id = try server.reactors[1].clients.alloc(ConnState.init(-1));
        const conn = server.reactors[1].clients.get(id).?;
        try conn.session.setNick("kain");
        conn.session.loginAs("kain");
        conn.session.registration.registered = true;
        try reconcileTestOper(&conn.session, oper_mod.OperPrivileges.initMany(&.{.oper_override}), "netadmin", "");

        // The read-only scan must cover every reactor; the re-mint lands in the
        // local grant registry (and best-effort broadcasts to secured peers).
        server.rebroadcastLocalOpers();
        const g = server.oper_grants.lookup("kain", server.grantNowU64()) orelse return error.TestExpectedGrant;
        try std.testing.expect(oper_mod.OperPrivileges.fromBits(g.privilege_bits).has(.oper_override));
    } else return error.SkipZigTest;
}

test "multi-shard UPGRADE seal carries clients on EVERY shard (CLOEXEC cleared)" {
    if (comptime builtin.os.tag == .linux) {
        const alloc = std.testing.allocator;
        var server = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .num_shards = 2 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        try std.testing.expectEqual(@as(usize, 2), server.reactors.len);

        // One registered client homed on EACH shard, each with a real socket
        // (the seal clears FD_CLOEXEC on every carried fd — the H1 bug was
        // exactly that shards 1..N-1 never got this and dropped at execve).
        var sp0: [2]i32 = undefined;
        if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sp0)) != .SUCCESS) return error.SkipZigTest;
        defer for (sp0) |fd| closeFd(fd);
        var sp1: [2]i32 = undefined;
        if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sp1)) != .SUCCESS) return error.SkipZigTest;
        defer for (sp1) |fd| closeFd(fd);
        _ = linux.fcntl(sp0[0], posix.F.SETFD, posix.FD_CLOEXEC);
        _ = linux.fcntl(sp1[0], posix.F.SETFD, posix.FD_CLOEXEC);

        const id0 = try server.reactors[0].clients.alloc(ConnState.init(sp0[0]));
        const c0 = server.reactors[0].clients.get(id0).?;
        c0.overflow_allocator = alloc;
        try c0.session.setNick("shardzero");
        c0.session.registration.registered = true;
        const id1 = try server.reactors[1].clients.alloc(ConnState.init(sp1[0]));
        const c1 = server.reactors[1].clients.get(id1).?;
        c1.overflow_allocator = alloc;
        try c1.session.setNick("shardone");
        c1.session.registration.registered = true;

        var blobs: std.ArrayList([]u8) = .empty;
        defer {
            for (blobs.items) |b| alloc.free(b);
            blobs.deinit(alloc);
        }
        var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
        defer pieces.deinit(alloc);
        var fds: [8]linux.fd_t = undefined;
        var nfds: usize = 0;
        var counts = Server.SealCounts{};
        // No reactor threads run in this test (pool idle), so sealing every
        // shard from this thread mirrors the post-quiesce state of a live
        // multi-shard UPGRADE.
        for (server.reactors) |*r| server.sealShardClients(r, &pieces, &blobs, &fds, &nfds, &counts);

        // Both shards' clients were carried: a `.clients` capsule each, the fd
        // recorded, and CLOEXEC cleared so the socket survives execve.
        try std.testing.expectEqual(@as(usize, 2), counts.clients);
        try std.testing.expectEqual(@as(usize, 2), nfds);
        var client_pieces: usize = 0;
        for (pieces.items) |p| {
            if (p.kind == .clients) client_pieces += 1;
        }
        try std.testing.expectEqual(@as(usize, 2), client_pieces);
        const fl0 = linux.fcntl(sp0[0], posix.F.GETFD, 0);
        const fl1 = linux.fcntl(sp1[0], posix.F.GETFD, 0);
        try std.testing.expectEqual(@as(usize, 0), fl0 & posix.FD_CLOEXEC);
        try std.testing.expectEqual(@as(usize, 0), fl1 & posix.FD_CLOEXEC);
    } else return error.SkipZigTest;
}

test "UPGRADE exact cancels target operation kind and generation" {
    const token = RingFdToken{ .slot = 0x1234, .gen = 0x5678 };
    inline for (.{ ringlane.OpKind.accept, .recv, .send, .connect }) |kind| {
        const ud = try ringlane.Ring.exactCancelUserData(kind, token);
        try std.testing.expectEqual(try ringlane.encodeUserData(kind, token), ud.target);
        try std.testing.expectEqual(try ringlane.encodeUserData(.other, token), ud.completion);
        const decoded = try ringlane.decodeUserData(ud.target);
        try std.testing.expectEqual(kind, decoded.kind);
        try std.testing.expectEqual(token.slot, decoded.token.slot);
        try std.testing.expectEqual(token.gen, decoded.token.gen);
    }
    try std.testing.expectError(
        error.InvalidCancelKind,
        ringlane.Ring.exactCancelUserData(.timeout, token),
    );
}

test "UPGRADE TLS ticket-key capsule allocation failure is fatal to the seal" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = 0 });
    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(std.testing.allocator);
    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |blob| std.testing.allocator.free(blob);
        blobs.deinit(std.testing.allocator);
    }
    try std.testing.expect(!Server.sealTlsTicketKeyUpgradeCapsule(
        failing.allocator(),
        @splat(0xA1),
        @as(tls_resumption.TicketKey, @splat(0xB2)),
        &pieces,
        &blobs,
    ));
    try std.testing.expectEqual(@as(usize, 0), pieces.items.len);
    try std.testing.expectEqual(@as(usize, 0), blobs.items.len);
}

test "Windows HXRG seal and stage retain TLS ticket and binder replay across no-fail install" {
    const allocator = std.testing.allocator;
    var source = tls_resumption.ReplayGuard{};
    const ticket_tag: [16]u8 = @splat(0x16);
    const binder32: [32]u8 = @splat(0x32);
    const binder48: [48]u8 = @splat(0x48);
    try std.testing.expect(source.checkAndRecord(&ticket_tag));
    try std.testing.expect(source.checkAndRecord(&binder32));
    try std.testing.expect(source.checkAndRecord(&binder48));

    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(allocator);
    const wire = try Server.sealTlsReplayUpgradeCheckpoint(allocator, &source, &pieces);
    defer {
        std.crypto.secureZero(u8, wire);
        allocator.free(wire);
    }
    try std.testing.expectEqual(@as(usize, 1), pieces.items.len);
    try std.testing.expectEqual(helix_capsule.CapsuleKind.mesh_checkpoint, pieces.items[0].kind);
    try std.testing.expectEqual(@as(?u16, 2), pieces.items[0].min_supported);
    var field = [_]helix_capsule.Field{.{ .ordinal = 1, .bytes = wire }};
    var cap = helix_capsule.make(.mesh_checkpoint, &field);
    cap.header.min_supported = 2;

    var candidate = tls_resumption.ReplayGuard{};
    const candidate_address = @intFromPtr(&candidate);
    var replacement = (try Server.stageTlsReplayUpgradeCheckpoint(allocator, true, &.{cap})) orelse
        return error.TestUnexpectedResult;
    defer replacement.deinit();
    try std.testing.expect(candidate.checkAndRecord(&(@as([16]u8, @splat(0x71)))));
    replacement.install(&candidate);
    try std.testing.expectEqual(candidate_address, @intFromPtr(&candidate));
    try std.testing.expect(!candidate.checkAndRecord(&ticket_tag));
    try std.testing.expect(!candidate.checkAndRecord(&binder32));
    try std.testing.expect(!candidate.checkAndRecord(&binder48));
    try std.testing.expect(try Server.stageTlsReplayUpgradeCheckpoint(allocator, false, &.{}) == null);
    try std.testing.expectError(error.InvalidInheritedHandoff, Server.stageTlsReplayUpgradeCheckpoint(allocator, true, &.{}));
    try std.testing.expectError(error.InvalidInheritedHandoff, Server.stageTlsReplayUpgradeCheckpoint(allocator, false, &.{cap}));
    try std.testing.expectError(error.InvalidInheritedHandoff, Server.stageTlsReplayUpgradeCheckpoint(allocator, true, &.{ cap, cap }));

    const corrupt = try allocator.dupe(u8, wire);
    defer allocator.free(corrupt);
    corrupt[corrupt.len - 1] ^= 1;
    var corrupt_field = [_]helix_capsule.Field{.{ .ordinal = 1, .bytes = corrupt }};
    var corrupt_cap = helix_capsule.make(.mesh_checkpoint, &corrupt_field);
    corrupt_cap.header.min_supported = 2;
    try std.testing.expectError(error.InvalidSnapshot, Server.stageTlsReplayUpgradeCheckpoint(allocator, true, &.{corrupt_cap}));
    var downgraded = cap;
    downgraded.header.min_supported = 1;
    try std.testing.expectError(error.InvalidInheritedHandoff, Server.stageTlsReplayUpgradeCheckpoint(allocator, true, &.{downgraded}));
    var future = cap;
    future.header.version += 1;
    future.header.max_supported += 1;
    try std.testing.expectError(error.InvalidInheritedHandoff, Server.stageTlsReplayUpgradeCheckpoint(allocator, true, &.{future}));

    // The source ring is read-only during sealing. Every injected allocation
    // failure leaves the plan empty and the consumed identities unchanged.
    var saw_success = false;
    for (0..16) |fail_index| {
        var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = fail_index });
        var fail_pieces: std.ArrayList(helix_live.StatePiece) = .empty;
        defer fail_pieces.deinit(failing.allocator());
        if (Server.sealTlsReplayUpgradeCheckpoint(failing.allocator(), &source, &fail_pieces)) |encoded| {
            try std.testing.expectEqual(@as(usize, 1), fail_pieces.items.len);
            std.crypto.secureZero(u8, encoded);
            failing.allocator().free(encoded);
            saw_success = true;
            break;
        } else |err| {
            try std.testing.expectEqual(error.OutOfMemory, err);
            try std.testing.expectEqual(@as(usize, 0), fail_pieces.items.len);
            try std.testing.expect(!source.checkAndRecord(&ticket_tag));
            try std.testing.expect(!source.checkAndRecord(&binder32));
            try std.testing.expect(!source.checkAndRecord(&binder48));
        }
    }
    try std.testing.expect(saw_success);
    var failing_decode = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    try std.testing.expectError(error.OutOfMemory, Server.stageTlsReplayUpgradeCheckpoint(failing_decode.allocator(), true, &.{cap}));
    try std.testing.expect(!source.checkAndRecord(&ticket_tag));
}

test "Windows HXMB seal and staged adopt retain RAM inbox and dirty reconciliation" {
    if (comptime builtin.os.tag != .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const source = createTestServer(allocator, .{ .host = "127.0.0.1", .port = 0, .crypto_io = std.testing.io }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer allocator.destroy(source);
    defer source.deinit();
    const candidate = createTestServer(allocator, .{ .host = "127.0.0.1", .port = 0, .crypto_io = std.testing.io }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer allocator.destroy(candidate);
    defer candidate.deinit();
    try std.testing.expect(source.account_services == null);
    try std.testing.expect(candidate.account_services == null);
    _ = try source.storeOfflineMemo("alice", "bob", "first", 101);
    _ = try source.storeOfflineMemo("alice", "carol", "second", 102);
    source.memo_durable_dirty = true;
    _ = try candidate.storeOfflineMemo("stale", "mallory", "old", 1);
    try std.testing.expect(source.upgradeContinuityBlockerLocked() == null);
    try std.testing.expect(!candidate.memo_durable_dirty);

    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(allocator);
    const wire = try Server.sealMemoInboxUpgradeCheckpoint(allocator, &source.memo, source.memo_durable_dirty, &pieces);
    defer {
        std.crypto.secureZero(u8, wire);
        allocator.free(wire);
    }
    try std.testing.expectEqual(@as(usize, 1), pieces.items.len);
    try std.testing.expectEqual(helix_capsule.CapsuleKind.mesh_checkpoint, pieces.items[0].kind);
    try std.testing.expectEqual(@as(?u16, 2), pieces.items[0].min_supported);
    var field = [_]helix_capsule.Field{.{ .ordinal = 1, .bytes = wire }};
    var cap = helix_capsule.make(.mesh_checkpoint, &field);
    cap.header.min_supported = 2;

    try std.testing.expectError(error.InvalidInheritedHandoff, Server.stageMemoInboxUpgradeCheckpoint(allocator, candidate.memo.cfg, &.{}));
    try std.testing.expectError(error.InvalidInheritedHandoff, Server.stageMemoInboxUpgradeCheckpoint(allocator, candidate.memo.cfg, &.{ cap, cap }));
    var downgraded = cap;
    downgraded.header.min_supported = 1;
    try std.testing.expectError(error.InvalidInheritedHandoff, Server.stageMemoInboxUpgradeCheckpoint(allocator, candidate.memo.cfg, &.{downgraded}));
    var future = cap;
    future.header.version += 1;
    future.header.max_supported += 1;
    try std.testing.expectError(error.InvalidInheritedHandoff, Server.stageMemoInboxUpgradeCheckpoint(allocator, candidate.memo.cfg, &.{future}));
    var wrong_config = candidate.memo.cfg;
    wrong_config.max_text_bytes += 1;
    try std.testing.expectError(error.ConfigMismatch, Server.stageMemoInboxUpgradeCheckpoint(allocator, wrong_config, &.{cap}));
    const corrupt = try allocator.dupe(u8, wire);
    defer allocator.free(corrupt);
    corrupt[corrupt.len - 1] ^= 1;
    var corrupt_field = [_]helix_capsule.Field{.{ .ordinal = 1, .bytes = corrupt }};
    var corrupt_cap = helix_capsule.make(.mesh_checkpoint, &corrupt_field);
    corrupt_cap.header.min_supported = 2;
    try std.testing.expectError(error.ChecksumMismatch, Server.stageMemoInboxUpgradeCheckpoint(allocator, candidate.memo.cfg, &.{corrupt_cap}));
    var failing_decode = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    try std.testing.expectError(error.OutOfMemory, Server.stageMemoInboxUpgradeCheckpoint(failing_decode.allocator(), candidate.memo.cfg, &.{cap}));
    try std.testing.expectEqualStrings("old", candidate.memo.pending("stale")[0].text);
    try std.testing.expectEqual(@as(usize, 0), candidate.memo.count("alice"));

    var failing_encode = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    var failed_pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer failed_pieces.deinit(failing_encode.allocator());
    try std.testing.expectError(error.OutOfMemory, Server.sealMemoInboxUpgradeCheckpoint(failing_encode.allocator(), &source.memo, true, &failed_pieces));
    try std.testing.expectEqual(@as(usize, 0), failed_pieces.items.len);
    try std.testing.expectEqual(@as(usize, 2), source.memo.count("alice"));
    try std.testing.expect(source.memo_durable_dirty);

    var replacement = try Server.stageMemoInboxUpgradeCheckpoint(allocator, candidate.memo.cfg, &.{cap});
    defer replacement.deinit();
    try std.testing.expect(replacement.dirty);
    try std.testing.expectEqualStrings("old", candidate.memo.pending("stale")[0].text);
    std.mem.swap(memo_mod.MemoBox, &candidate.memo, &replacement.box);
    candidate.memo_durable_dirty = replacement.dirty;
    try std.testing.expect(candidate.memo_durable_dirty);
    try std.testing.expectEqual(@as(usize, 0), candidate.memo.count("stale"));
    const messages = candidate.memo.pending("alice");
    try std.testing.expectEqual(@as(usize, 2), messages.len);
    try std.testing.expectEqualStrings("bob", messages[0].from);
    try std.testing.expectEqualStrings("first", messages[0].text);
    try std.testing.expectEqual(@as(i64, 101), messages[0].sent_ms);
    try std.testing.expectEqualStrings("carol", messages[1].from);
    try std.testing.expectEqualStrings("second", messages[1].text);
    try std.testing.expectEqual(@as(i64, 102), messages[1].sent_ms);
    try std.testing.expectEqual(@as(usize, 2), source.memo.count("alice"));
}

test "Windows malformed HXMB actual adopt preserves boot inbox" {
    if (comptime builtin.os.tag != .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;
    const candidate = createTestServer(allocator, .{ .host = "127.0.0.1", .port = 0, .crypto_io = std.testing.io }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer allocator.destroy(candidate);
    defer candidate.deinit();
    _ = try candidate.storeOfflineMemo("boot", "sender", "retained", 7);
    const rows = try candidate.collectListenerManifest(allocator);
    defer allocator.free(rows);
    try std.testing.expect(rows.len != 0);
    const Barrier = struct {
        calls: usize = 0,
        fn ready(ctx: *anyopaque) !void {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.calls += 1;
            return error.TestUnexpectedResult;
        }
    };
    var barrier = Barrier{};
    candidate.config.native_listener_manifest = rows;
    candidate.config.native_adopt_barrier = .{ .ctx = &barrier, .readyAndAwaitCommit = Barrier.ready };
    candidate.config.inherited_state_fd_manifest_present = true;
    candidate.config.inherited_state_fd_manifest_valid = true;

    var source_box = memo_mod.MemoBox.init(allocator);
    defer source_box.deinit();
    _ = try source_box.send("carried", "sender", "source", 8);
    const valid = try native_windows_memo_inbox.encode(allocator, &source_box, true);
    defer {
        std.crypto.secureZero(u8, valid);
        allocator.free(valid);
    }
    const corrupt = try allocator.dupe(u8, valid);
    defer {
        std.crypto.secureZero(u8, corrupt);
        allocator.free(corrupt);
    }
    corrupt[corrupt.len - 1] ^= 1;
    const malformed = [_]helix_live.StatePiece{.{ .kind = .mesh_checkpoint, .bytes = corrupt, .min_supported = 2 }};
    const stream = try encodeUpgradeStreamWithWidenedHeaderForTest(allocator, &malformed, .handoff_manifest);
    defer allocator.free(stream);
    candidate.config.native_arena_bytes = stream;
    try std.testing.expectError(error.InvalidInheritedHandoff, candidate.adoptInheritedSessions());
    try std.testing.expectEqual(@as(usize, 0), barrier.calls);
    try std.testing.expectEqualStrings("retained", candidate.memo.pending("boot")[0].text);
    try std.testing.expectEqual(@as(usize, 0), candidate.memo.count("carried"));
    try std.testing.expect(os_runtime.fdValid(rows[0].fd));
    try std.testing.expectEqual(@as(usize, 1), source_box.count("carried"));
}

test "dirty memo repair snapshots accepted RAM image on send and timer" {
    const allocator = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.openWithConfig(allocator, std.testing.io, tmp.dir, "dirty-memos.wal", .{ .max_record_bytes = 128 });
    var store_open = true;
    defer if (store_open) store.deinit();
    var services = services_mod.Services.init(&store, null);
    const server = createTestServer(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
        .memo_config = .{ .max_text_bytes = 65_536 },
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    var server_open = true;
    defer if (server_open) {
        server.deinit();
        allocator.destroy(server);
    };
    const unencodable = try allocator.alloc(u8, 65_536);
    defer allocator.free(unencodable);
    @memset(unencodable, 'x');
    try std.testing.expectError(error.MessageInvalid, server.storeOfflineMemo("oversize", "bob", unencodable, 0));
    try std.testing.expectEqual(@as(usize, 0), server.memo.count("oversize"));
    const too_wide_record = try allocator.alloc(u8, 128);
    defer allocator.free(too_wide_record);
    @memset(too_wide_record, 'y');
    try std.testing.expectError(error.MessageInvalid, server.storeOfflineMemo("too-wide-record", "bob", too_wide_record, 0));
    try std.testing.expectEqual(@as(usize, 0), server.memo.count("too-wide-record"));
    _ = try server.memo.send("alice", "bob", "missed append", 1);
    server.memo_durable_dirty = true;
    _ = try server.storeOfflineMemo("alice", "carol", "next append", 2);
    try std.testing.expect(!server.memo_durable_dirty);
    _ = try server.memo.send("alice", "dave", "timer repair", 3);
    server.memo_durable_dirty = true;
    server.memo_durable_retry_after_ms = server.nowMs() +| 60_000;
    server.retryDirtyDurableMemos();
    try std.testing.expect(server.memo_durable_dirty);
    server.memo_durable_retry_after_ms = 0;
    server.retryDirtyDurableMemos();
    try std.testing.expect(!server.memo_durable_dirty);
    server.deinit();
    allocator.destroy(server);
    server_open = false;
    store.deinit();
    store_open = false;

    var restored_store = try services_mod.OroStore.openWithConfig(allocator, std.testing.io, tmp.dir, "dirty-memos.wal", .{ .max_record_bytes = 128 });
    defer restored_store.deinit();
    var restored = memo_mod.MemoBox.init(allocator);
    defer restored.deinit();
    try memo_durable.restoreInto(&restored_store, &restored);
    const messages = restored.pending("alice");
    try std.testing.expectEqual(@as(usize, 3), messages.len);
    try std.testing.expectEqualStrings("missed append", messages[0].text);
    try std.testing.expectEqualStrings("next append", messages[1].text);
    try std.testing.expectEqualStrings("timer repair", messages[2].text);
}

test "UPGRADE successor adopts one canonical TLS ticket-key authority atomically" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;
    const carried_current: tls_resumption.TicketKey = @splat(0xA4);
    const carried_previous: tls_resumption.TicketKey = @splat(0xB5);
    const blob = try ticket_key_capsule.encode(allocator, .{
        .current = carried_current,
        .previous = carried_previous,
    });
    defer allocator.free(blob);

    var successor = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_enable_resumption = true,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer successor.deinit();
    successor.tls_ticket_key = @splat(0x11);
    successor.tls_previous_ticket_key = @as(tls_resumption.TicketKey, @splat(0x22));
    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |owned| allocator.free(owned);
        blobs.deinit(allocator);
    }
    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(allocator);
    try appendCurrentMandatoryUpgradeStateForTest(&successor, &pieces, &blobs);
    var ticket_replaced = false;
    for (pieces.items) |*piece| {
        if (piece.kind != .tls_ticket_keys) continue;
        piece.bytes = blob;
        ticket_replaced = true;
        break;
    }
    try std.testing.expect(ticket_replaced);
    const listener_fd = successor.reactors[0].listener_fd;
    const arena_fd = try adoptUpgradePiecesForTest(&successor, pieces.items, "onyx-test-ticket-key-success");
    current_reactor = null;

    try std.testing.expectEqualSlices(u8, &carried_current, &successor.tls_ticket_key);
    try std.testing.expect(successor.tls_previous_ticket_key != null);
    try std.testing.expectEqualSlices(u8, &carried_previous, &successor.tls_previous_ticket_key.?);
    try std.testing.expect(successor.config.resume_arena_fd == null);
    try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(arena_fd, posix.F.GETFD, 0)));
    try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(listener_fd, posix.F.GETFD, 0)));
}

test "UPGRADE successor rejects missing duplicate corrupt and late-failing TLS ticket authority without publication" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;
    const carried_current: tls_resumption.TicketKey = @splat(0xC6);
    const carried_previous: tls_resumption.TicketKey = @splat(0xD7);
    const valid = try ticket_key_capsule.encode(allocator, .{
        .current = carried_current,
        .previous = carried_previous,
    });
    defer allocator.free(valid);
    const Scenario = enum { missing, duplicate, corrupt, late_failure };
    for ([_]Scenario{ .missing, .duplicate, .corrupt, .late_failure }) |scenario| {
        var successor = Server.init(allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .tls_enable_resumption = true,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer successor.deinit();
        const boot_current: tls_resumption.TicketKey = @splat(0x31);
        const boot_previous: tls_resumption.TicketKey = @splat(0x42);
        successor.tls_ticket_key = boot_current;
        successor.tls_previous_ticket_key = boot_previous;
        var blobs: std.ArrayList([]u8) = .empty;
        defer {
            for (blobs.items) |owned| allocator.free(owned);
            blobs.deinit(allocator);
        }
        var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
        defer pieces.deinit(allocator);
        try appendCurrentMandatoryUpgradeStateForTest(&successor, &pieces, &blobs);
        var ticket_index: ?usize = null;
        var pmst_index: ?usize = null;
        for (pieces.items, 0..) |piece, index| {
            if (piece.kind == .tls_ticket_keys) ticket_index = index;
            if (piece.kind == .pending_migration and piece.min_supported == 2) pmst_index = index;
        }
        try std.testing.expect(ticket_index != null);
        try std.testing.expect(pmst_index != null);
        switch (scenario) {
            .missing => _ = pieces.orderedRemove(ticket_index.?),
            .duplicate => try pieces.append(allocator, .{ .kind = .tls_ticket_keys, .bytes = valid }),
            .corrupt => pieces.items[ticket_index.?].bytes = "bad-ticket-key",
            .late_failure => {
                pieces.items[ticket_index.?].bytes = valid;
                // The ticket singleton decodes successfully, then this exact
                // PMST checkpoint fails before the common publication boundary.
                pieces.items[pmst_index.?].bytes = "bad-pmst";
            },
        }
        const listener_fd = successor.reactors[0].listener_fd;
        const arena_fd = try rejectUpgradePiecesForTest(&successor, pieces.items, "onyx-test-ticket-key-refuse");
        current_reactor = null;

        try std.testing.expectEqualSlices(u8, &boot_current, &successor.tls_ticket_key);
        try std.testing.expect(successor.tls_previous_ticket_key != null);
        try std.testing.expectEqualSlices(u8, &boot_previous, &successor.tls_previous_ticket_key.?);
        try std.testing.expect(successor.config.resume_arena_fd == null);
        try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(arena_fd, posix.F.GETFD, 0)));
        try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(listener_fd, posix.F.GETFD, 0)));
    }
}

test "UPGRADE successor rejects noncanonical TLS ticket wrapper and disabled authority" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;
    const carried: tls_resumption.TicketKey = @splat(0xE8);
    const blob = try ticket_key_capsule.encode(allocator, .{ .current = carried });
    defer allocator.free(blob);

    inline for (.{ true, false }) |resumption_enabled| {
        var successor = Server.init(allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .tls_enable_resumption = resumption_enabled,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer successor.deinit();
        const boot_current: tls_resumption.TicketKey = @splat(if (resumption_enabled) 0x51 else 0x61);
        successor.tls_ticket_key = boot_current;
        successor.tls_previous_ticket_key = null;
        var blobs: std.ArrayList([]u8) = .empty;
        defer {
            for (blobs.items) |owned| allocator.free(owned);
            blobs.deinit(allocator);
        }
        var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
        defer pieces.deinit(allocator);
        try appendCurrentMandatoryUpgradeStateForTest(&successor, &pieces, &blobs);
        const listener_fd = successor.reactors[0].listener_fd;
        const arena_fd = if (resumption_enabled) blk: {
            var ticket_replaced = false;
            for (pieces.items) |*piece| {
                if (piece.kind != .tls_ticket_keys) continue;
                piece.bytes = blob;
                ticket_replaced = true;
                break;
            }
            try std.testing.expect(ticket_replaced);
            const stream = try encodeUpgradeStreamWithWidenedHeaderForTest(
                allocator,
                pieces.items,
                .tls_ticket_keys,
            );
            defer allocator.free(stream);
            break :blk try rejectUpgradeStreamForTest(&successor, stream, "onyx-test-ticket-key-outer");
        } else blk: {
            try pieces.append(allocator, .{ .kind = .tls_ticket_keys, .bytes = blob });
            break :blk try rejectUpgradePiecesForTest(&successor, pieces.items, "onyx-test-ticket-key-disabled");
        };
        current_reactor = null;

        try std.testing.expectEqualSlices(u8, &boot_current, &successor.tls_ticket_key);
        try std.testing.expect(successor.tls_previous_ticket_key == null);
        try std.testing.expect(successor.config.resume_arena_fd == null);
        try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(arena_fd, posix.F.GETFD, 0)));
        try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(listener_fd, posix.F.GETFD, 0)));
    }
}

