    const conn = predecessor.reactors[0].clients.get(id).?;
    conn.overflow_allocator = allocator;
    conn.token = try tokenFromId(id);
    conn.s2s_secured = &pair.a;

    // Put one complete encrypted record in the kernel, then reap it only into
    // io_uring's CQ. Helix quiescence, not the ordinary reactor loop, must
    // dispatch this completion before it snapshots the record counters.
    const before_recv_counter = pair.a.exportOuter().recv_counter;
    try pair.b.sendMembership(
        "#before-upgrade",
        "BeforeUpgrade",
        0,
        700,
        true,
        .{ .username = "before", .realname = "Before Upgrade", .host = "mesh.test" },
        "",
    );
    const completed_wire = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(completed_wire);
    pair.b.clearOutbound();
    try predecessor.armRecv(conn);
    _ = try predecessor.reactors[0].ring.submit();
    try writeAllFd(sockets[1], completed_wire);
    _ = try predecessor.reactors[0].ring.submitAndWait(1);

    try predecessor.quiesceOwnedSocketIo();
    try std.testing.expect(!conn.recv_armed);
    try std.testing.expect(!conn.recv_cancel_pending);
    try std.testing.expectEqual(before_recv_counter + 1, pair.a.exportOuter().recv_counter);

    // The exact post-dispatch counters and any response bytes are the only
    // stream image the successor may inherit.
    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(allocator);
    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |blob| allocator.free(blob);
        blobs.deinit(allocator);
    }
    try std.testing.expect(predecessor.sealSecuredLink(conn, &pair.a, &pieces, &blobs));
    try std.testing.expectEqual(@as(usize, 1), pieces.items.len);
    try std.testing.expectEqual(.s2s_link, pieces.items[0].kind);
    const snap = try s2s_snapshot.decode(pieces.items[0].bytes, s2s_snapshot.schema_version);
    try std.testing.expectEqual(before_recv_counter + 1, snap.recv_counter);
    try std.testing.expectEqual(sockets[0], snap.fd);
    try std.testing.expect((snap.caps & s2s_snapshot.cap_secure_relay_v2) != 0);
    try std.testing.expect((snap.caps & s2s_snapshot.cap_event_spine_v2) != 0);

    // Transfer descriptor ownership away from the predecessor fixture exactly
    // as execve would. The stack-owned pair.a remains alive only as an oracle;
    // the successor constructs an independent resumed SecuredLink from `snap`.
    conn.s2s_secured = null;
    conn.fd = -1;

    var successor = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "upgrade-stream-a.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
        .mesh_pass = "session-replay-secret",
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer successor.deinit();
    current_reactor = &successor.reactors[0];
    try std.testing.expect(successor.adoptInheritedS2sLink(snap, true) != null);

    var adopted: ?*ConnState = null;
    var clients = successor.reactors[0].clients.iterator();
    while (clients.next()) |entry| {
        if (entry.value.fd == sockets[0] and entry.value.s2s_secured != null) {
            try std.testing.expect(adopted == null);
            adopted = entry.value;
        }
    }
    const adopted_conn = adopted orelse return error.TestUnexpectedResult;
    const resumed = adopted_conn.s2s_secured orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(snap.recv_counter, resumed.exportOuter().recv_counter);
    try std.testing.expect(resumed.supportsSecureRelayV2());
    try std.testing.expect(resumed.supportsEventSpineV2());

    // Successor -> live peer: the carried response plus mandatory RESYNC remain
    // valid at the next send counter. RESYNC is observed exactly once.
    const peer_recv_before = pair.b.exportOuter().recv_counter;
    const successor_wire = try copyTestSendQ(allocator, adopted_conn);
    defer allocator.free(successor_wire);
    try std.testing.expect(successor_wire.len != 0);
    resetTestSendQ(adopted_conn);
    try pair.b.feed(successor_wire, 701);
    try std.testing.expect(pair.b.exportOuter().recv_counter > peer_recv_before);
    try std.testing.expect(pair.b.takeResyncRequest());
    try std.testing.expect(!pair.b.takeResyncRequest());

    // RESYNC can make the peer answer with its current roster. Drain that
    // ordinary post-adoption exchange in both directions before minting the
    // single record whose exactly-once delivery is asserted below; discarding
    // either side would deliberately create a record-counter hole.
    var pump_rounds: usize = 0;
    while (pair.b.outbound().len != 0 or resumed.outbound().len != 0) : (pump_rounds += 1) {
        if (pump_rounds == 32) return error.TestUnexpectedResult;
        const peer_out = try allocator.dupe(u8, pair.b.outbound());
        defer allocator.free(peer_out);
        const resumed_out = try allocator.dupe(u8, resumed.outbound());
        defer allocator.free(resumed_out);
        pair.b.clearOutbound();
        resumed.clearOutbound();
        if (peer_out.len != 0) try resumed.feed(peer_out, 702 + pump_rounds);
        if (resumed_out.len != 0) try pair.b.feed(resumed_out, 702 + pump_rounds);
    }
    resumed.processDeferredResidenceFrames(734);
    const baseline_changes = try resumed.takeMembershipChanges();
    defer {
        for (baseline_changes) |*change| change.deinit(allocator);
        allocator.free(baseline_changes);
    }

    // Live peer -> successor: the next signed membership is one complete AEAD
    // record and decrypts under the resumed receive counter exactly once.
    try pair.b.sendMembership(
        "#after-upgrade",
        "AfterUpgrade",
        0,
        701,
        true,
        .{ .username = "after", .realname = "After Upgrade", .host = "mesh.test" },
        "",
    );
    const post_wire = try allocator.dupe(u8, pair.b.outbound());
    defer allocator.free(post_wire);
    pair.b.clearOutbound();
    try std.testing.expect(post_wire.len > 4);
    try std.testing.expectEqual(post_wire.len, 4 + @as(usize, std.mem.readInt(u32, post_wire[0..4], .little)));
    const successor_recv_before = resumed.exportOuter().recv_counter;
    try resumed.feed(post_wire, 702);
    try std.testing.expectEqual(successor_recv_before + 1, resumed.exportOuter().recv_counter);
    resumed.processDeferredResidenceFrames(702);
    const changes = try resumed.takeMembershipChanges();
    defer {
        for (changes) |*change| change.deinit(allocator);
        allocator.free(changes);
    }
    try std.testing.expectEqual(@as(usize, 1), changes.len);
    try std.testing.expectEqualStrings("#after-upgrade", changes[0].channel);
    try std.testing.expectEqualStrings("AfterUpgrade", changes[0].nick);
}

/// Shared skeleton for the two RESYNC-re-burst tests below: converge a
/// predecessor holding a remote OPER member (+o) in #root over a live secured
/// pair, seal the link (v4 roster) + the mandatory state (OGNT grants), and
/// adopt the link on a successor that has a local member `alice` in #root whose
/// SendQ the tests then assert. Returns everything the caller needs; the caller
/// decides whether to prime the grant registry (the fix vs the negative
/// control).
const ResyncQuietFixture = struct {
    predecessor: *Server,
    successor: *Server,
    pair: *SessionReplayTestPair,
    pieces: std.ArrayList(helix_live.StatePiece),
    blobs: std.ArrayList([]u8),
    sockets: [2]linux.fd_t,
    alice: *ConnState,
    resumed: *secured_s2s_link.SecuredLink,
    grant_kp: std.crypto.sign.Ed25519.KeyPair,
    op_status: u4,
    now: u64,

    const trev_ident = s2s_peer_mod.MemberIdentity{
        .username = "trev",
        .realname = "Trevor",
        .host = "cloak.ircx.us",
        .account = "trev",
    };

    fn verifyTrevResidence(
        _: *anyopaque,
        account: []const u8,
        nick: []const u8,
        _: u64,
        _: bool,
    ) s2s_link.S2sLink.ResidenceDecision {
        if (std.ascii.eqlIgnoreCase(account, "trev") and std.ascii.eqlIgnoreCase(nick, "trev"))
            return .trusted;
        return .untrusted;
    }

    fn trevResidenceVerifier(ctx: *anyopaque) s2s_link.S2sLink.ResidenceVerifier {
        return .{ .ctx = ctx, .verify_fn = verifyTrevResidence };
    }

    fn init(alloc: std.mem.Allocator, pair: *SessionReplayTestPair) !ResyncQuietFixture {
        const op_status: u4 = @truncate(chanmode.MemberModes.fromModes(&.{.op}).bits);

        var predecessor = createTestServer(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .node_id = pair.ida.shortId(),
            .server_name = "resync-quiet-a.test",
            .node_identity = &pair.ida,
            .crypto_io = std.testing.io,
            .mesh_pass = "session-replay-secret",
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => {
                if (comptime builtin.os.tag == .openbsd) return err;
                return error.SkipZigTest;
            },
            else => return err,
        };
        errdefer {
            predecessor.deinit();
            alloc.destroy(predecessor);
        }
        current_reactor = &predecessor.reactors[0];
        pair.a.setResidenceVerifier(trevResidenceVerifier(predecessor));

        var sockets: [2]linux.fd_t = undefined;
        if (comptime builtin.os.tag == .openbsd) {
            if (posix.system.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets) != 0)
                return error.SocketUnavailable;
            errdefer {
                closeFd(sockets[0]);
                closeFd(sockets[1]);
            }
            try os_runtime.setCloexec(sockets[0], true);
            try os_runtime.setCloexec(sockets[1], true);
        } else {
            if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets)) != .SUCCESS)
                return error.SkipZigTest;
        }
        var socket0_owned_by_fixture = true;
        errdefer if (socket0_owned_by_fixture) closeFd(sockets[0]);
        errdefer closeFd(sockets[1]);

        const peer_id = try predecessor.reactors[0].clients.alloc(ConnState.init(sockets[0]));
        socket0_owned_by_fixture = false;
        const peer_conn = predecessor.reactors[0].clients.get(peer_id).?;
        peer_conn.overflow_allocator = alloc;
        peer_conn.token = try tokenFromId(peer_id);
        peer_conn.s2s_secured = &pair.a;
        // The pair owns this borrowed link even if fixture preparation fails.
        errdefer peer_conn.s2s_secured = null;

        // Pre-upgrade convergence: the peer projects remote oper `trev` as an
        // OP (+o) member of #root; the predecessor's route table converges and
        // its (already-announced) transitions are consumed.
        // The account is residence-verified mesh identity. Prefix routing must
        // resolve grants through that account-to-display mapping; an empty
        // account is intentionally ineligible and would correctly stay quiet.
        try pair.b.sendMembership("#root", "trev", op_status, 700, true, trev_ident, "");
        const pre_wire = try alloc.dupe(u8, pair.b.outbound());
        defer alloc.free(pre_wire);
        pair.b.clearOutbound();
        try pair.a.feed(pre_wire, 700);
        pair.a.processDeferredResidenceFrames(700);
        predecessor.discardIdentityTransitions(&pair.a);

        // The converged pre-upgrade grant registry: trev's oper_override grant,
        // exactly as `applyMeshGrant` stored it when the grant first arrived.
        const now = predecessor.grantNowU64();
        _ = predecessor.oper_grants.upsert(.{
            .account = "trev",
            .privilege_bits = oper_mod.OperPrivileges.initMany(&.{.oper_override}).toBits(),
            .class = "netadmin",
            .title = "",
            .issuer_node = "resync-quiet-b.test",
            .incarnation = 100,
            .issued_ms = now,
            .expiry_ms = now + Server.oper_grant_ttl_ms,
        });

        // Seal: the mandatory state (carries the OGNT grants piece) and the
        // secured link (carries the v4 roster incl. trev's +o and hlc 700).
        var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
        errdefer pieces.deinit(alloc);
        var blobs: std.ArrayList([]u8) = .empty;
        errdefer {
            for (blobs.items) |blob| alloc.free(blob);
            blobs.deinit(alloc);
        }
        try appendCurrentMandatoryUpgradeStateForTest(predecessor, &pieces, &blobs);
        try std.testing.expect(predecessor.sealSecuredLink(peer_conn, &pair.a, &pieces, &blobs));

        // Transfer descriptor ownership exactly as execve would.
        peer_conn.s2s_secured = null;
        peer_conn.fd = -1;
        socket0_owned_by_fixture = true;

        var successor = createTestServer(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .node_id = pair.ida.shortId(),
            .server_name = "resync-quiet-a.test",
            .node_identity = &pair.ida,
            .crypto_io = std.testing.io,
            .mesh_pass = "session-replay-secret",
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => {
                if (comptime builtin.os.tag == .openbsd) return err;
                return error.SkipZigTest;
            },
            else => return err,
        };
        errdefer {
            successor.deinit();
            alloc.destroy(successor);
        }
        current_reactor = &successor.reactors[0];

        // The successor's carried World image: alice (a local client whose view
        // was preserved across the swap) in #root, with the topic the World
        // capsule carries.
        const alice_id = try addTestLocalClient(successor, "alice", null);
        const alice = successor.connFor(alice_id).?;
        alice.overflow_allocator = alloc;
        alice.session.registration.registered = true;
        if (comptime builtin.os.tag == .openbsd) {
            // Only the declared fixture sink bypasses I/O. An ordinary invalid
            // descriptor must still fail native admission without poisoning a
            // real reactor registration or consuming its token.
            var invalid = ConnState.init(-1);
            invalid.token = alice.token;
            invalid.send_buf[0] = 'x';
            invalid.send_len = 1;
            try std.testing.expectError(error.MissingOp, successor.armSendIfNeeded(&invalid));
            try std.testing.expect(!invalid.send_armed and !alice.send_armed);
            try std.testing.expect(!alice.closing);
        }
        _ = try successor.world.join("#root", worldIdFromClient(alice_id));
        // Topic setter is trev (+o via the carried link roster): the receiver's
        // +t defense resolves the setter across the combined projection, so a
        // non-op setter would be rejected there and mask what these tests
        // actually prove (the unchanged-re-affirmation dedup).
        try successor.world.setTopic("#root", "stormy weather", "trev", 1234);

        // Adopt the preserved link: primes the carried v4 roster (trev, +o,
        // hlc 700) BEFORE any RESYNC processing.
        const link_bytes = upgradePieceBytesForTest(pieces.items, .s2s_link) orelse
            return error.TestUnexpectedResult;
        const snap = try s2s_snapshot.decode(link_bytes, s2s_snapshot.schema_version);
        try std.testing.expect(snap.roster_count != 0);
        // The adopter consumes the descriptor on either success or refusal.
        socket0_owned_by_fixture = false;
        try std.testing.expect(successor.adoptInheritedS2sLink(snap, true) != null);
        var resumed: ?*secured_s2s_link.SecuredLink = null;
        var clients_it = successor.reactors[0].clients.iterator();
        while (clients_it.next()) |entry| {
            if (entry.value.fd == sockets[0]) resumed = entry.value.s2s_secured;
        }

        const grant_kp = try std.crypto.sign.Ed25519.KeyPair.generateDeterministic(@as([32]u8, @splat(0x42)));
        const resumed_link = resumed orelse return error.TestUnexpectedResult;
        resumed_link.setResidenceVerifier(trevResidenceVerifier(successor));
        return .{
            .predecessor = predecessor,
            .successor = successor,
            .pair = pair,
            .pieces = pieces,
            .blobs = blobs,
            .sockets = sockets,
            .alice = alice,
            .resumed = resumed_link,
            .grant_kp = grant_kp,
            .op_status = op_status,
            .now = now,
        };
    }

    /// Prime the successor's grant registry from the sealed OGNT piece — the
    /// same decode + infallible upserts the adoption commit edge performs
    /// (proven end-to-end by the arena-path adopt test above).
    fn primeGrants(self: *ResyncQuietFixture) !void {
        const bytes = upgradeOperGrantBytesForTest(self.pieces.items) orelse
            return error.TestUnexpectedResult;
        const gsnap = try oper_grant_snapshot.decodeCurrent(bytes);
        self.successor.grant_incarnation = @max(self.successor.grant_incarnation, gsnap.mint_incarnation);
        var it = gsnap.iterator();
        while (it.next()) |g| _ = self.successor.oper_grants.upsert(g);
    }

    /// One signed grant re-mint for trev, as the peer's post-RESYNC opers burst
    /// re-sends it: fresh (higher) incarnation, UNCHANGED privileges.
    fn applyRemintedGrant(self: *ResyncQuietFixture, incarnation: u64, privilege_bits: u64) !bool {
        var buf: [oper_cred_share.max_grant_len]u8 = undefined;
        const n = try oper_cred_share.sign(self.grant_kp, .{
            .account = "trev",
            .privilege_bits = privilege_bits,
            .class = "netadmin",
            .title = "",
            .issuer_node = "resync-quiet-b.test",
            .incarnation = incarnation,
            .issued_ms = self.now,
            .expiry_ms = self.now + Server.oper_grant_ttl_ms,
        }, &buf);
        return self.successor.applyMeshGrant(buf[0..n], self.grant_kp.public_key.toBytes());
    }

    /// Feed one peer->successor burst and run the daemon drains, mirroring the
    /// established-link drive order.
    fn feedAndDrain(self: *ResyncQuietFixture, alloc: std.mem.Allocator, now_ms: u64) !void {
        const wire = try alloc.dupe(u8, self.pair.b.outbound());
        defer alloc.free(wire);
        self.pair.b.clearOutbound();
        if (wire.len != 0) try self.resumed.feed(wire, now_ms);
        self.resumed.processDeferredResidenceFrames(now_ms);
        var clients = self.successor.reactors[0].clients.iterator();
        var owner: ?*ConnState = null;
        while (clients.next()) |entry| {
            if (entry.value.s2s_secured == self.resumed) owner = entry.value;
        }
        self.successor.drainIdentityTransitions(owner orelse return error.TestUnexpectedResult, self.resumed);
        self.successor.drainChannelModeFlagChanges(owner orelse return error.TestUnexpectedResult, self.resumed);
        self.successor.drainTopicChanges(owner orelse return error.TestUnexpectedResult, self.resumed);
    }

    fn deinit(self: *ResyncQuietFixture, alloc: std.mem.Allocator) void {
        for (self.blobs.items) |blob| alloc.free(blob);
        self.blobs.deinit(alloc);
        self.pieces.deinit(alloc);
        closeFd(self.sockets[1]);
        self.successor.deinit();
        alloc.destroy(self.successor);
        self.predecessor.deinit();
        alloc.destroy(self.predecessor);
    }
};

test "UPGRADE resume: peer RESYNC re-burst of unchanged remote state emits zero client-visible lines" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var pair = try SessionReplayTestPair.init(alloc);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var fx = try ResyncQuietFixture.init(alloc, &pair);
    defer fx.deinit(alloc);

    // THE FIX under test: the carried grant registry is primed before any
    // re-mint can be processed (arena-path adoption does this at its commit
    // edge; the negative-control test below omits exactly this step).
    try fx.primeGrants();

    resetTestSendQ(fx.alice);

    // The peer's post-RESYNC re-burst of UNCHANGED converged state: the same
    // member (+o, fresh hlc), the same topic (fresh hlc — `sendTopicBurstTo`
    // always stamps a fresh one), the same aggregate mode flags, and the
    // re-minted oper grant (fresh incarnation, unchanged privileges).
    fx.successor.world.lockWrite();
    try pair.b.sendMembership("#root", "trev", fx.op_status, 900, true, ResyncQuietFixture.trev_ident, "");
    try pair.b.sendTopic("#root", "stormy weather", "trev", 1234, 901, true);
    try pair.b.sendChannelModeFlags("#root", fx.successor.channelModeFlagBits("#root"), 902);
    try fx.feedAndDrain(alloc, 903);
    try std.testing.expect(try fx.applyRemintedGrant(
        101,
        oper_mod.OperPrivileges.initMany(&.{.oper_override}).toBits(),
    ));
    fx.successor.world.unlockWrite();

    // ZERO spurious client-visible lines for the unchanged member: no JOIN, no
    // +Y/oper MODE, no member-mode MODE, no channel-mode MODE, no TOPIC, no
    // NICK — alice's view was preserved across the swap and must stay silent.
    const quiet = try copyTestSendQ(alloc, fx.alice);
    defer alloc.free(quiet);
    try std.testing.expectEqualStrings("", quiet);

    // Genuine member/topic changes after adoption still surface exactly once.
    // Revoking override must emit a single derived -Y for the remote oper.
    fx.successor.world.lockWrite();
    const op_voice: u4 = @truncate(chanmode.MemberModes.fromModes(&.{ .op, .voice }).bits);
    try pair.b.sendMembership("#root", "trev", op_voice, 950, true, ResyncQuietFixture.trev_ident, "kain");
    try pair.b.sendTopic("#root", "calm seas", "trev", 2000, 951, true);
    try fx.feedAndDrain(alloc, 952);
    try std.testing.expect(try fx.applyRemintedGrant(102, 0));
    fx.successor.world.unlockWrite();

    const changed = try copyTestSendQ(alloc, fx.alice);
    defer alloc.free(changed);
    try std.testing.expect(std.mem.indexOf(u8, changed, "MODE #root +v trev") != null);
    try std.testing.expect(std.mem.indexOf(u8, changed, "TOPIC #root :calm seas") != null);
    // Exactly once each.
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, changed, "TOPIC #root"));
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, changed, "MODE #root -Y trev"));
    // And still no spurious re-JOIN anywhere in the whole exchange.
    try std.testing.expect(std.mem.indexOf(u8, changed, "JOIN") == null);
    try std.testing.expect(std.mem.indexOf(u8, changed, "NICK") == null);
    try std.testing.expect(std.mem.indexOf(u8, changed, "+Y") == null);
}

test "UPGRADE resume: first override grant after missing registry projects +Y once" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var pair = try SessionReplayTestPair.init(alloc);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var fx = try ResyncQuietFixture.init(alloc, &pair);
    defer fx.deinit(alloc);

    // Deliberately DO NOT prime the grant registry — the first live override
    // grant must project remote `*` / +Y (display edge), not stay silent.
    try fx.successor.world.setTopic("#root", "", "", 0);
    resetTestSendQ(fx.alice);

    fx.successor.world.lockWrite();
    try pair.b.sendTopic("#root", "stormy weather", "trev", 1234, 901, true);
    try fx.feedAndDrain(alloc, 903);
    try std.testing.expect(try fx.applyRemintedGrant(
        101,
        oper_mod.OperPrivileges.initMany(&.{.oper_override}).toBits(),
    ));
    fx.successor.world.unlockWrite();

    const first = try copyTestSendQ(alloc, fx.alice);
    defer alloc.free(first);
    try std.testing.expect(std.mem.indexOf(u8, first, "TOPIC #root :stormy weather") != null);
    try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, first, "MODE #root +Y trev"));

    // Same-privilege remint (30s anti-entropy) must stay silent.
    resetTestSendQ(fx.alice);
    fx.successor.world.lockWrite();
    try std.testing.expect(try fx.applyRemintedGrant(
        102,
        oper_mod.OperPrivileges.initMany(&.{.oper_override}).toBits(),
    ));
    fx.successor.world.unlockWrite();

    const quiet_refresh = try copyTestSendQ(alloc, fx.alice);
    defer alloc.free(quiet_refresh);
