test "KEYTRANS exposes credential transparency root and inclusion proof" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-keytrans.wal");
    defer store.deinit();
    var kt = key_transparency.KeyTransparencyLog.init(std.testing.allocator);
    defer kt.deinit();
    var services = services_mod.Services.init(&store, null);
    services.attachKeyTransparencyLog(&kt);

    _ = try kt.append(.{
        .account = "alice",
        .kind = .certfp,
        .action = .bind,
        .key_id = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
        .key_hash = key_transparency.materialHash("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),
        .timestamp_ms = 1_700_000_000_000,
    });
    _ = try kt.append(.{
        .account = "alice",
        .kind = .webauthn,
        .action = .bind,
        .key_id = "credAAA",
        .key_hash = key_transparency.materialHash("cose-key"),
        .timestamp_ms = 1_700_000_001_000,
    });

    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .account_services = &services }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const id = try addTestLocalClient(&server, "kain", null);
    const conn = server.connFor(id).?;

    var status = irc_line.LineView{ .raw = "", .command = "KEYTRANS" };
    status.params[0] = "STATUS";
    status.param_count = 1;
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &status);
    const root_hex = std.fmt.bytesToHex(kt.root(), .lower);
    try expectContains(conn.send_buf[0..conn.send_len], "KEYTRANS STATUS enabled semantics=observational scope=node-local entries=2 root=");
    try expectContains(conn.send_buf[0..conn.send_len], &root_hex);

    var proof = irc_line.LineView{ .raw = "", .command = "KEYTRANS" };
    proof.params[0] = "PROOF";
    proof.params[1] = "1";
    proof.param_count = 2;
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &proof);
    try expectContains(conn.send_buf[0..conn.send_len], "KEYTRANS PROOF position=1 size=2 root=");
    try expectContains(conn.send_buf[0..conn.send_len], "KEYTRANS PATH 0 left ");
    try expectContains(conn.send_buf[0..conn.send_len], "KEYTRANS PROOF-END position=1");

    proof.params[1] = "9";
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &proof);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL KEYTRANS NO_SUCH_LEAF");

    var event_lv = irc_line.LineView{ .raw = "", .command = "KEYTRANS" };
    event_lv.params[0] = "EVENT";
    event_lv.params[1] = "1";
    event_lv.param_count = 2;
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &event_lv);
    try expectContains(conn.send_buf[0..conn.send_len], "KEYTRANS EVENT position=1 size=2 account=alice kind=webauthn action=bind key_id=credAAA");
    try expectContains(conn.send_buf[0..conn.send_len], "leaf=");

    var consist = irc_line.LineView{ .raw = "", .command = "KEYTRANS" };
    consist.params[0] = "CONSISTENCY";
    consist.params[1] = "1";
    consist.param_count = 2;
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &consist);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL KEYTRANS UNKNOWN_CHECKPOINT");

    consist.params[1] = "0";
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &consist);
    try expectContains(conn.send_buf[0..conn.send_len], "KEYTRANS CONSISTENCY old_size=0");
    try expectContains(conn.send_buf[0..conn.send_len], "prefix=match scheme=checkpoint-comparison");

    consist.params[1] = "9";
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &consist);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL KEYTRANS BAD_SIZE");

    event_lv.params[1] = "9";
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &event_lv);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL KEYTRANS NO_SUCH_LEAF");

    var need = irc_line.LineView{ .raw = "", .command = "KEYTRANS" };
    need.params[0] = "EVENT";
    need.param_count = 1;
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &need);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL KEYTRANS NEED_MORE_PARAMS");

    need.params[0] = "DEVICE";
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &need);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL KEYTRANS NEED_MORE_PARAMS");
}

test "GAP-K2 a stored signed head shows a revocation and a missing log fails closed only when required" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-keytrans-peer.wal");
    defer store.deinit();
    var kt = key_transparency.KeyTransparencyLog.init(std.testing.allocator);
    defer kt.deinit();
    var services = services_mod.Services.init(&store, null);
    services.attachKeyTransparencyLog(&kt);

    var source = key_transparency.KeyTransparencyLog.init(std.testing.allocator);
    defer source.deinit();
    var kp = try crypto_sign.KeyPair.fromSeed(@as(crypto_sign.Seed, @splat(0x42)));
    defer kp.deinit();

    const bind_pos = try source.append(.{
        .account = "alice",
        .kind = .e2ee_device,
        .action = .bind,
        .key_id = "phone",
        .key_hash = key_transparency.materialHash("mls-phone"),
        .timestamp_ms = 10,
    });
    var bind_head = try key_transparency.headFromParts(7, 1, bind_pos.root, .bind, "phone");
    try key_transparency.signHead(&kp, &bind_head);

    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .account_services = &services }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const id = try addTestLocalClient(&server, "kain", null);
    const conn = server.connFor(id).?;

    const store_ok = try gapK2Store(&server, conn, bind_head);
    try expectContains(store_ok, "KEYTRANS STORE node=7 entries=1 action=bind");

    const absent = try gapK2Peer(&server, conn, "99");
    try expectContains(absent, "KEYTRANS PEER node=99 present=no");
    try std.testing.expect(std.mem.indexOf(u8, absent, "FAIL") == null);

    conn.send_len = 0;
    var require = irc_line.LineView{ .raw = "", .command = "KEYTRANS" };
    require.params[0] = "REQUIRE";
    require.params[1] = "on";
    require.param_count = 2;
    try server.handleKeyTrans(conn, &require);
    const missing = try gapK2Peer(&server, conn, "99");
    try expectContains(missing, "FAIL KEYTRANS MISSING_LOG");

    require.params[1] = "off";
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &require);

    const bound = try gapK2Peer(&server, conn, "7");
    const bind_root = std.fmt.bytesToHex(bind_head.root, .lower);
    try expectContains(bound, "action=bind key_id=phone scheme=signed-head");
    try expectContains(bound, &bind_root);

    const delete_pos = try source.append(.{
        .account = "alice",
        .kind = .e2ee_device,
        .action = .delete,
        .key_id = "phone",
        .key_hash = key_transparency.materialHash("mls-phone"),
        .timestamp_ms = 11,
    });
    var delete_head = try key_transparency.headFromParts(7, 2, delete_pos.root, .delete, "phone");
    try key_transparency.signHead(&kp, &delete_head);
    _ = try gapK2Store(&server, conn, delete_head);
    const revoked = try gapK2Peer(&server, conn, "7");
    const delete_root = std.fmt.bytesToHex(delete_head.root, .lower);
    try expectContains(revoked, "entries=2");
    try expectContains(revoked, "action=delete key_id=phone");
    try expectContains(revoked, &delete_root);
    try std.testing.expect(std.mem.indexOf(u8, revoked, &bind_root) == null);

    var forged = delete_head;
    forged.signature[0] ^= 0x01;
    const forged_reply = try gapK2Store(&server, conn, forged);
    try expectContains(forged_reply, "FAIL KEYTRANS BAD_SIGNATURE");
    const still = try gapK2Peer(&server, conn, "7");
    try expectContains(still, &delete_root);

    var other = try crypto_sign.KeyPair.fromSeed(@as(crypto_sign.Seed, @splat(0x99)));
    defer other.deinit();
    var swapped = delete_head;
    try key_transparency.signHead(&other, &swapped);
    const mismatch = try gapK2Store(&server, conn, swapped);
    try expectContains(mismatch, "FAIL KEYTRANS KEY_MISMATCH");
    const pinned = try gapK2Peer(&server, conn, "7");
    try expectContains(pinned, &delete_root);

    var bare_store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-keytrans-missing.wal");
    defer bare_store.deinit();
    var bare_services = services_mod.Services.init(&bare_store, null);
    var bare = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .account_services = &bare_services }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer bare.deinit();
    const bare_id = try addTestLocalClient(&bare, "rita", null);
    const bare_conn = bare.connFor(bare_id).?;
    var status = irc_line.LineView{ .raw = "", .command = "KEYTRANS" };
    status.params[0] = "STATUS";
    status.param_count = 1;
    bare_conn.send_len = 0;
    try bare.handleKeyTrans(bare_conn, &status);
    try expectContains(bare_conn.send_buf[0..bare_conn.send_len], "STATUS disabled");
    try std.testing.expect(std.mem.indexOf(u8, bare_conn.send_buf[0..bare_conn.send_len], "MISSING_LOG") == null);
    var req = irc_line.LineView{ .raw = "", .command = "KEYTRANS" };
    req.params[0] = "REQUIRE";
    req.params[1] = "on";
    req.param_count = 2;
    bare_conn.send_len = 0;
    try bare.handleKeyTrans(bare_conn, &req);
    bare_conn.send_len = 0;
    try bare.handleKeyTrans(bare_conn, &status);
    try expectContains(bare_conn.send_buf[0..bare_conn.send_len], "FAIL KEYTRANS MISSING_LOG");

    std.debug.print("GAP-K2 branch=each node stores the other signed head and a missing log fails closed only when required\n", .{});
}

fn gapK2Store(server: *Server, conn: *ConnState, head: key_transparency.SignedHead) ![]const u8 {
    const root_hex = std.fmt.bytesToHex(head.root, .lower);
    const sig_hex = std.fmt.bytesToHex(head.signature, .lower);
    const pub_hex = std.fmt.bytesToHex(head.public_key, .lower);
    var node_buf: [32]u8 = undefined;
    var entries_buf: [32]u8 = undefined;
    const node_s = std.fmt.bufPrint(&node_buf, "{d}", .{head.node_id}) catch return error.SkipZigTest;
    const entries_s = std.fmt.bufPrint(&entries_buf, "{d}", .{head.entries}) catch return error.SkipZigTest;
    var lv = irc_line.LineView{ .raw = "", .command = "KEYTRANS" };
    lv.params[0] = "STORE";
    lv.params[1] = node_s;
    lv.params[2] = entries_s;
    lv.params[3] = &root_hex;
    lv.params[4] = &sig_hex;
    lv.params[5] = &pub_hex;
    lv.params[6] = head.action.wireName();
    lv.params[7] = head.keyId();
    lv.param_count = 8;
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &lv);
    return conn.send_buf[0..conn.send_len];
}

fn gapK2Peer(server: *Server, conn: *ConnState, node: []const u8) ![]const u8 {
    var lv = irc_line.LineView{ .raw = "", .command = "KEYTRANS" };
    lv.params[0] = "PEER";
    lv.params[1] = node;
    lv.param_count = 2;
    conn.send_len = 0;
    try server.handleKeyTrans(conn, &lv);
    return conn.send_buf[0..conn.send_len];
}

test "GAP-K2 a revocation is visible on the other node after anti-entropy" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var store_a = try services_mod.OroStore.open(alloc, std.testing.io, tmp.dir, "kt-anti-a.wal");
    defer store_a.deinit();
    var store_b = try services_mod.OroStore.open(alloc, std.testing.io, tmp.dir, "kt-anti-b.wal");
    defer store_b.deinit();
    var kt_a = key_transparency.KeyTransparencyLog.init(alloc);
    defer kt_a.deinit();
    var kt_b = key_transparency.KeyTransparencyLog.init(alloc);
    defer kt_b.deinit();
    var services_a = services_mod.Services.init(&store_a, null);
    var services_b = services_mod.Services.init(&store_b, null);
    services_a.attachKeyTransparencyLog(&kt_a);
    services_b.attachKeyTransparencyLog(&kt_b);

    const bind = try kt_a.append(.{
        .account = "alice",
        .kind = .e2ee_device,
        .action = .bind,
        .key_id = "phone",
        .key_hash = key_transparency.materialHash("mls-phone"),
        .timestamp_ms = 10,
    });
    _ = try kt_a.append(.{
        .account = "alice",
        .kind = .e2ee_device,
        .action = .delete,
        .key_id = "phone",
        .key_hash = key_transparency.materialHash("mls-phone"),
        .timestamp_ms = 11,
    });

    var ident_a = try node_identity.fromSeed(@as([32]u8, @splat(0x42)), "kt-a");
    defer ident_a.deinit();
    var ident_b = try node_identity.fromSeed(@as([32]u8, @splat(0x43)), "kt-b");
    defer ident_b.deinit();

    const origin = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .server_name = "kt-a.test",
        .account_services = &services_a,
        .node_identity = &ident_a,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(origin);
    defer origin.deinit();
    const other = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .server_name = "kt-b.test",
        .account_services = &services_b,
        .node_identity = &ident_b,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(other);
    defer other.deinit();

    const reader_id = try addTestLocalClient(other, "rita", null);
    const reader = other.connFor(reader_id).?;

    var now_ms: u64 = 30;
    var origin_state = s2s_peer_mod.ChannelCrdt.init(alloc, 0x71);
    defer origin_state.deinit();
    var other_state = s2s_peer_mod.ChannelCrdt.init(alloc, 0x72);
    defer other_state.deinit();
    var to_other = ServerPeerTestBuffer{};
    defer to_other.deinit();
    var to_origin = ServerPeerTestBuffer{};
    defer to_origin.deinit();

    const origin_kp = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0x42)));
    const other_kp = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0x43)));
    var origin_peer = try initServerTestPeer(&origin_state, &now_ms, origin_kp, message_relay.originShortId(other_kp.public_key), 1000, "kt-a.test", false);
    defer origin_peer.deinit();
    var other_peer = try initServerTestPeer(&other_state, &now_ms, other_kp, message_relay.originShortId(origin_kp.public_key), 2000, "kt-b.test", false);
    defer other_peer.deinit();

    const KeyTransSend = struct {
        peer: *s2s_peer_mod.S2sPeer,
        sink: s2s_peer_mod.ByteSink,
        fn sendKeyTransHead(bridge: *@This(), wire: []const u8) !void {
            try bridge.peer.sendKeyTransHead(bridge.sink, wire);
        }
    };
    var send = KeyTransSend{ .peer = &origin_peer, .sink = to_other.sink() };
    try std.testing.expect(origin.sendKeyTransHeadOn(&send));
    try std.testing.expectEqual(@as(usize, 0), to_other.bytes.items.len);

    try origin_peer.startHandshake(to_other.sink());
    try other_peer.startHandshake(to_origin.sink());
    try pumpServerTestPeers(&origin_peer, &other_peer, &to_other, &to_origin, now_ms, 0x71A0);
    try std.testing.expect(origin_peer.supportsKeyTransHead());
    try std.testing.expect(other_peer.supportsKeyTransHead());

    try std.testing.expect(origin.sendKeyTransHeadOn(&send));
    try pumpServerTestPeers(&origin_peer, &other_peer, &to_other, &to_origin, now_ms, 0x71A1);
    other.drainKeyTransPeer(&other_peer);

    var node_buf: [32]u8 = undefined;
    const node_s = std.fmt.bufPrint(&node_buf, "{d}", .{ident_a.shortId()}) catch return error.TestUnexpectedResult;
    const seen = try gapK2Peer(other, reader, node_s);
    try expectContains(seen, "action=delete key_id=phone");
    try expectContains(seen, "entries=2");

    var stale = try key_transparency.headFromParts(ident_a.shortId(), 1, bind.root, .bind, "phone");
    try key_transparency.signHead(&ident_a.sign_kp, &stale);
    var stale_buf: [key_transparency.head_wire_len]u8 = undefined;
    const stale_wire = try key_transparency.encodeHeadWire(stale, &stale_buf);
    try origin_peer.sendKeyTransHead(to_other.sink(), stale_wire);
    try pumpServerTestPeers(&origin_peer, &other_peer, &to_other, &to_origin, now_ms, 0x71A2);
    other.drainKeyTransPeer(&other_peer);
    const still = try gapK2Peer(other, reader, node_s);
    try expectContains(still, "action=delete key_id=phone");
    try expectContains(still, "entries=2");
    try std.testing.expect(std.mem.indexOf(u8, still, "action=bind") == null);

    var bad_buf: [key_transparency.head_wire_len]u8 = undefined;
    const current = origin.localKeyTransHeadWire(&bad_buf) orelse return error.TestUnexpectedResult;
    bad_buf[current.len - 1] ^= 0x01;
    try origin_peer.sendKeyTransHead(to_other.sink(), bad_buf[0..current.len]);
    try pumpServerTestPeers(&origin_peer, &other_peer, &to_other, &to_origin, now_ms, 0x71A3);
    other.drainKeyTransPeer(&other_peer);
    const after_bad = try gapK2Peer(other, reader, node_s);
    try expectContains(after_bad, "action=delete key_id=phone");
    try expectContains(after_bad, "entries=2");

    std.debug.print("GAP-K2 branch=a revocation is visible on the other node after anti-entropy and a stale head does not replace it\n", .{});
}

fn expectNodeProof(ident: *const node_identity.NodeIdentity, entry: *const svc_operaudit.Entry) !void {
    try std.testing.expect(entry.proof_signature.len == @sizeOf(proofmark.Signature) * 2);
    try std.testing.expect(entry.proof_public_key.len == @sizeOf(proofmark.PublicKey) * 2);
    var sig: proofmark.Signature = undefined;
    var stored_pk: proofmark.PublicKey = undefined;
    _ = std.fmt.hexToBytes(&sig, entry.proof_signature) catch return error.TestExpectedEqual;
    _ = std.fmt.hexToBytes(&stored_pk, entry.proof_public_key) catch return error.TestExpectedEqual;
    try std.testing.expectEqualSlices(u8, &ident.sign_kp.public_key, &stored_pk);
    const proof = proofmark.Proof{
        .actor = entry.oper,
        .target = entry.target,
        .action = entry.proof_action,
        .reason_hash = entry.proof_reason_hash,
        .policy_version = entry.proof_policy_version,
        .issued_ms = entry.proof_issued_ms,
        .expiry_ms = entry.proof_expiry_ms,
    };
    try std.testing.expect(proofmark.verify(proof, sig, ident.sign_kp.public_key));
    var id_buf: [proofmark.proof_id_hex_len]u8 = undefined;
    const id = try proofmark.proofIdHex(proof, sig, &id_buf);
    try std.testing.expectEqualStrings(id, entry.proof_id);
}

test "GAP-K3 a node public key verifies a ban or kick after restart and a removed entry breaks the chain" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const wal_name = "server-proof-chain.wal";
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x3a)), "proof-chain");
    defer ident.deinit();
    var kline_id: [proofmark.proof_id_hex_len]u8 = undefined;
    var kick_id: [proofmark.proof_id_hex_len]u8 = undefined;
    {
        var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, wal_name);
        defer store.deinit();
        var services = services_mod.Services.init(&store, null);
        const server = createTestServer(std.testing.allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .account_services = &services,
            .node_identity = &ident,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer std.testing.allocator.destroy(server);
        defer server.deinit();
        const ban = server.recordOperAudit("op", .kline, "*@spam", "flood") orelse return error.TestExpectedEqual;
        const kick_proof = server.recordOperAudit("op", .kick, "#room nick", "flood") orelse return error.TestExpectedEqual;
        _ = server.recordOperAudit("op", .shun, "bad!*@*", "flood") orelse return error.TestExpectedEqual;
        kline_id = ban;
        kick_id = kick_proof;
        try std.testing.expect(server.oper_audit.chainStatus(ident.sign_kp.public_key) == .intact);
        try expectNodeProof(&ident, server.oper_audit.findByProofId(&kline_id).?);
        try expectNodeProof(&ident, server.oper_audit.findByProofId(&kick_id).?);
        try std.testing.expectEqual(svc_operaudit.Action.kline, server.oper_audit.findByProofId(&kline_id).?.action);
        try std.testing.expectEqual(svc_operaudit.Action.kick, server.oper_audit.findByProofId(&kick_id).?.action);
    }

    var tampered_holder: []u8 = &.{};
    defer if (tampered_holder.len != 0) std.testing.allocator.free(tampered_holder);
    {
        var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, wal_name);
        defer store.deinit();
        var services = services_mod.Services.init(&store, null);
        const server = createTestServer(std.testing.allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .account_services = &services,
            .node_identity = &ident,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer std.testing.allocator.destroy(server);
        defer server.deinit();
        try std.testing.expectEqual(@as(usize, 3), server.oper_audit.len());
        try std.testing.expect(server.oper_audit.chainStatus(ident.sign_kp.public_key) == .intact);
        const ban = server.oper_audit.findByProofId(&kline_id).?;
        const kick_proof = server.oper_audit.findByProofId(&kick_id).?;
        try expectNodeProof(&ident, ban);
        try expectNodeProof(&ident, kick_proof);
        try std.testing.expect(LinuxServer.auditProofVerified(ban));
        try std.testing.expect(LinuxServer.auditProofVerified(kick_proof));
        const blob = store.get(.props, svc_operaudit.chain_store_key) orelse return error.TestExpectedEqual;
        tampered_holder = try svc_operaudit.omitEncodedEntry(std.testing.allocator, blob, 1);
        try store.put(.props, svc_operaudit.chain_store_key, tampered_holder);
    }

    {
        var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, wal_name);
        defer store.deinit();
        var services = services_mod.Services.init(&store, null);
        const server = createTestServer(std.testing.allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .account_services = &services,
            .node_identity = &ident,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer std.testing.allocator.destroy(server);
        defer server.deinit();
        try std.testing.expectEqual(@as(usize, 2), server.oper_audit.len());
        try std.testing.expect(server.oper_audit.chainStatus(ident.sign_kp.public_key) == .broken);
        try std.testing.expect(server.oper_audit.findByProofId(&kick_id) == null);
        try expectNodeProof(&ident, server.oper_audit.findByProofId(&kline_id).?);
    }
    std.debug.print("GAP-K3 branch=a node public key verifies a ban or kick after restart and a removed entry breaks the chain\n", .{});
}

test "KEYTRANS DEVICE and EVENT survive store restart" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const wal_name = "server-keytrans-restart.wal";
    var first_root: [64]u8 = undefined;
    {
        var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, wal_name);
        defer store.deinit();
        var kt = key_transparency.KeyTransparencyLog.init(std.testing.allocator);
        defer kt.deinit();
        var services = services_mod.Services.init(&store, null);
        services.attachKeyTransparencyLog(&kt);
        try services.recordExternalKeyTransparencyEvent("Alice", .e2ee_device, .bind, "phone", "mls-x25519:abcd+/=", 11);
        try services.recordExternalKeyTransparencyEvent("Alice", .e2ee_device, .delete, "phone", "mls-x25519:abcd+/=", 12);
        first_root = std.fmt.bytesToHex(kt.root(), .lower);
    }

    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, wal_name);
    defer store.deinit();
    var kt = key_transparency.KeyTransparencyLog.init(std.testing.allocator);
    defer kt.deinit();
    var services = services_mod.Services.init(&store, null);
    services.attachKeyTransparencyLog(&kt);
    try std.testing.expectEqual(@as(usize, 2), kt.len());
    try std.testing.expectEqualStrings(&first_root, &std.fmt.bytesToHex(kt.root(), .lower));

    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .account_services = &services }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
