test "KEYTRANS remote ENTITY_PROP apply: clock-stage allocation failure on a delete fact leaves the prop, clock, HLC, and log unchanged" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-kt-delete-oom.wal");
    defer store.deinit();
    var kt = key_transparency.KeyTransparencyLog.init(std.testing.allocator);
    defer kt.deinit();
    var services = services_mod.Services.init(&store, null);
    services.attachKeyTransparencyLog(&kt);
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .account_services = &services }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    // A tombstone never touches the prop-store allocator (`deleteProp` only
    // frees), so this exercises the OTHER fallible step: clock staging via
    // `server.allocator`. Before this repair, `observeRemotePropertyHlc` ran
    // BEFORE clock staging, so a staging failure here still left the HLC
    // watermark advanced; asserting it unchanged is the regression proof.
    var seed = makeEntityPropChange(.user, "bob", "profile.phone", "seed-value", 100, 0xA);
    try std.testing.expect(server.applyRemoteEntityProp(&seed));
    const before_len = kt.len();
    const before_clocks = server.entity_prop_clocks.count();
    const before_entities = server.props.entity_count;
    const before_stamp = server.mesh_clock.last_stamp;
    const saved_allocator = server.allocator;
    var applied = false;
    var fail_index: usize = 0;
    while (fail_index < 16) : (fail_index += 1) {
        var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = fail_index });
        server.allocator = failing.allocator();
        var tomb = makeEntityPropChange(.user, "bob", "profile.phone", "", 300, 0xA);
        tomb.present = false;
        applied = server.applyRemoteEntityProp(&tomb);
        server.allocator = saved_allocator;
        if (!applied) {
            try std.testing.expectEqual(before_entities, server.props.entity_count);
            try std.testing.expectEqual(before_clocks, server.entity_prop_clocks.count());
            try std.testing.expectEqual(before_len, kt.len());
            try std.testing.expectEqual(before_stamp, server.mesh_clock.last_stamp);
            try std.testing.expectEqualStrings(
                "seed-value",
                (try server.props.getProp(.{ .kind = .user, .id = "bob" }, "profile.phone")).value,
            );
            continue;
        }
        break;
    }
    try std.testing.expect(applied);
    try std.testing.expectError(
        error.PropMissing,
        server.props.getProp(.{ .kind = .user, .id = "bob" }, "profile.phone"),
    );
}

test "E2EEKEY advertises account device keys through user props" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const id = try addTestLocalClient(&server, "kain", "kain");
    const conn = server.connFor(id).?;

    var add = irc_line.LineView{ .raw = "", .command = "E2EEKEY" };
    add.params[0] = "ADD";
    add.params[1] = "phone";
    add.params[2] = "mls-x25519";
    add.params[3] = "abcd+/=";
    add.param_count = 4;
    conn.send_len = 0;
    try server.handleE2eeKey(conn, &add);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL E2EEKEY DURABLE_UNAVAILABLE");

    const entity = ircx_prop_store.Entity{ .kind = .user, .id = "kain" };
    try std.testing.expectError(error.PropMissing, server.props.getProp(entity, "e2ee.device.phone"));

    var list_lv = irc_line.LineView{ .raw = "", .command = "E2EEKEY" };
    list_lv.params[0] = "LIST";
    list_lv.param_count = 1;
    conn.send_len = 0;
    try server.handleE2eeKey(conn, &list_lv);
    try expectContains(conn.send_buf[0..conn.send_len], "E2EEKEY END account=kain devices=0");

    var del = irc_line.LineView{ .raw = "", .command = "E2EEKEY" };
    del.params[0] = "DEL";
    del.params[1] = "phone";
    del.param_count = 2;
    conn.send_len = 0;
    try server.handleE2eeKey(conn, &del);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL E2EEKEY DURABLE_UNAVAILABLE");
    try std.testing.expectError(error.PropMissing, server.props.getProp(entity, "e2ee.device.phone"));
}

fn testOgc1Advertisement() !struct {
    encoded: [136]u8,
    device_id: [27]u8,
} {
    const directory = @import("../proto/e2ee_device_directory.zig");
    comptime {
        if (directory.encoded_len != 136 or directory.device_id_len != 27)
            @compileError("OGC1 advertisement test vector sizes drifted");
    }
    const Ed25519 = std.crypto.sign.Ed25519;
    const kp = try Ed25519.KeyPair.generateDeterministic(
        @as([Ed25519.KeyPair.seed_length]u8, @splat(0x5a)),
    );
    const odd1 = directory.fromParts(
        kp.public_key.toBytes(),
        std.crypto.ecc.P256.basePoint.toUncompressedSec1(),
    ) orelse return error.TestUnexpectedResult;
    var encoded: [directory.encoded_len]u8 = undefined;
    _ = directory.encodeCanonical(odd1, &encoded);
    var device_id: [directory.device_id_len]u8 = undefined;
    _ = directory.deviceId(odd1, &device_id);
    return .{ .encoded = encoded, .device_id = device_id };
}

test "E2EEKEY ADD accepts onyx-ogc1-v1 only with the derived device id" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const directory = @import("../proto/e2ee_device_directory.zig");
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const id = try addTestLocalClient(&server, "kain", "kain");
    const conn = server.connFor(id).?;
    const advertisement = try testOgc1Advertisement();

    var mismatched = irc_line.LineView{ .raw = "", .command = "E2EEKEY" };
    mismatched.params[0] = "ADD";
    mismatched.params[1] = "phone";
    mismatched.params[2] = directory.stored_algorithm;
    mismatched.params[3] = &advertisement.encoded;
    mismatched.param_count = 4;
    conn.send_len = 0;
    try server.handleE2eeKey(conn, &mismatched);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL E2EEKEY BAD_DEVICE");

    var malformed = mismatched;
    malformed.params[1] = &advertisement.device_id;
    malformed.params[3] = "abcd+/=";
    conn.send_len = 0;
    try server.handleE2eeKey(conn, &malformed);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL E2EEKEY BAD_KEY");

    var add = mismatched;
    add.params[1] = &advertisement.device_id;
    add.params[3] = &advertisement.encoded;
    conn.send_len = 0;
    try server.handleE2eeKey(conn, &add);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL E2EEKEY DURABLE_UNAVAILABLE");

    var key_buf: [e2ee_policy.device_prop_prefix.len + e2ee_policy.max_device_id_len]u8 = undefined;
    const key = e2ee_policy.devicePropKey(&advertisement.device_id, &key_buf).?;
    const entity = ircx_prop_store.Entity{ .kind = .user, .id = "kain" };
    try std.testing.expectError(error.PropMissing, server.props.getProp(entity, key));
}

test "DPROP1 E2EEKEY mixed-case ODD1 commits folded PROP lists and restores" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    const dprop_boot = @import("durable_credential_props_boot.zig");
    const directory = @import("../proto/e2ee_device_directory.zig");
    const wal_name = "server-dprop-odd1-folded-restart.wal";
    const folded_id = "ogc1-mpeycfzdqv8bz2wubf_ukd";
    const folded_key = "e2ee.device." ++ folded_id;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0xe1)), "dprop-odd1-folded.test");
    defer ident.deinit();
    const origin = ident.shortId();
    const advertisement = try testOgc1Advertisement();

    {
        var store = try services_mod.OroStore.open(alloc, std.testing.io, tmp.dir, wal_name);
        defer store.deinit();
        var dprop = try dprop_boot.load(alloc, &store, origin);
        defer dprop.deinit();
        var services = services_mod.Services.init(&store, null);
        services.attachDurableCredentialProps(&dprop);
        var server = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .account_services = &services,
            .node_identity = &ident,
            .durable_device_boot = .{ .authoritative = .{
                .state = &dprop,
                .local_origin_node = origin,
            } },
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const id = try addTestLocalClient(&server, "Alice", "alice");
        const conn = server.connFor(id).?;
        var add = irc_line.LineView{ .raw = "", .command = "E2EEKEY" };
        add.params[0] = "ADD";
        add.params[1] = &advertisement.device_id;
        add.params[2] = directory.stored_algorithm;
        add.params[3] = &advertisement.encoded;
        add.param_count = 4;
        var unrelated = add;
        unrelated.params[1] = "ogc1-aaaaaaaaaaaaaaaaaaaaaa";
        try server.handleE2eeKey(conn, &unrelated);
        try expectContains(conn.send_buf[0..conn.send_len], "FAIL E2EEKEY BAD_DEVICE");
        try std.testing.expectEqual(@as(usize, 0), dprop.count());
        conn.send_len = 0;
        try server.handleE2eeKey(conn, &add);
        try expectContains(conn.send_buf[0..conn.send_len], "E2EEKEY ADDED id=ogc1-MPEyCFzdqv8BZ2wUbf_uKD alg=onyx-ogc1-v1");
        try std.testing.expectEqual(@as(usize, 1), dprop.count());
        try std.testing.expect(dprop.get("alice", folded_key) != null);
        const live = try server.props.getPropRaw(.{ .kind = .user, .id = "alice" }, folded_key);
        try std.testing.expectEqualStrings(directory.stored_algorithm ++ ":" ++ directory.kat_wire.*, live.value);

        var list_cmd = irc_line.LineView{ .raw = "", .command = "E2EEKEY" };
        list_cmd.params[0] = "LIST";
        list_cmd.param_count = 1;
        conn.send_len = 0;
        try server.handleE2eeKey(conn, &list_cmd);
        try expectContains(conn.send_buf[0..conn.send_len], "E2EEKEY DEVICE account=alice id=" ++ folded_id ++ " alg=onyx-ogc1-v1");
        try expectContains(conn.send_buf[0..conn.send_len], "E2EEKEY END account=alice devices=1");
    }

    {
        var store = try services_mod.OroStore.open(alloc, std.testing.io, tmp.dir, wal_name);
        defer store.deinit();
        var dprop = try dprop_boot.load(alloc, &store, origin);
        defer dprop.deinit();
        try std.testing.expectEqual(@as(usize, 1), dprop.count());
        var services = services_mod.Services.init(&store, null);
        services.attachDurableCredentialProps(&dprop);
        var server = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .account_services = &services,
            .node_identity = &ident,
            .durable_device_boot = .{ .authoritative = .{
                .state = &dprop,
                .local_origin_node = origin,
            } },
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const live = try server.props.getPropRaw(.{ .kind = .user, .id = "alice" }, folded_key);
        try std.testing.expectEqualStrings(directory.stored_algorithm ++ ":" ++ directory.kat_wire.*, live.value);
        const id = try addTestLocalClient(&server, "Alice", "alice");
        const conn = server.connFor(id).?;
        var list_cmd = irc_line.LineView{ .raw = "", .command = "E2EEKEY" };
        list_cmd.params[0] = "LIST";
        list_cmd.param_count = 1;
        try server.handleE2eeKey(conn, &list_cmd);
        try expectContains(conn.send_buf[0..conn.send_len], "E2EEKEY DEVICE account=alice id=" ++ folded_id ++ " alg=onyx-ogc1-v1");
        try expectContains(conn.send_buf[0..conn.send_len], "E2EEKEY END account=alice devices=1");
    }
}

test "E2EEKEY and IDENTITY live mutations append verifiable key transparency events" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(
        alloc,
        std.testing.io,
        tmp.dir,
        "server-external-keytrans.wal",
    );
    defer store.deinit();
    var kt = key_transparency.KeyTransparencyLog.init(alloc);
    defer kt.deinit();
    var services = services_mod.Services.init(&store, null);
    services.attachKeyTransparencyLog(&kt);
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0xd4)), "dprop-server-keytrans.test");
    defer ident.deinit();
    var dprop = try durable_credential_props.State.init(alloc, .{ .local_origin_node = ident.shortId() });
    defer dprop.deinit();
    services.attachDurableCredentialProps(&dprop);
    const event_time_ms: i64 = 1_700_000_123_000;
    var sim_time = reactor_mod.SimReactor.init(event_time_ms);

    var server = Server.init(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
        .reactor = sim_time.reactor(),
        .node_identity = &ident,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    try std.testing.expectEqual(event_time_ms, server.keyTransparencyTimestampMs());

    const id = try addTestLocalClient(&server, "Alice", "Alice");
    const conn = server.connFor(id).?;
    var e2ee_add = irc_line.LineView{ .raw = "", .command = "E2EEKEY" };
    e2ee_add.params[0] = "ADD";
    e2ee_add.params[1] = "phone";
    e2ee_add.params[2] = "mls-x25519";
    e2ee_add.params[3] = "abcd+/=";
    e2ee_add.param_count = 4;
    try server.handleE2eeKey(conn, &e2ee_add);
    try std.testing.expectEqual(@as(usize, 1), kt.len());

    // A rejected property mutation never fabricates a transparency append.
    var bad_e2ee = e2ee_add;
    bad_e2ee.params[1] = "bad device";
    try server.handleE2eeKey(conn, &bad_e2ee);
    try std.testing.expectEqual(@as(usize, 1), kt.len());

    var e2ee_del = irc_line.LineView{ .raw = "", .command = "E2EEKEY" };
    e2ee_del.params[0] = "DEL";
    e2ee_del.params[1] = "phone";
    e2ee_del.param_count = 2;
    try server.handleE2eeKey(conn, &e2ee_del);
    try std.testing.expectEqual(@as(usize, 2), kt.len());
    // A missing-row delete is still a durable tombstone with a fresh HLC.
    try server.handleE2eeKey(conn, &e2ee_del);
    try std.testing.expectEqual(@as(usize, 3), kt.len());

    const Ed25519 = std.crypto.sign.Ed25519;
    const kp = try Ed25519.KeyPair.generateDeterministic(
        @as([Ed25519.KeyPair.seed_length]u8, @splat(0x79)),
    );
    const identity_public = kp.public_key.toBytes();
    const public_hex = std.fmt.bytesToHex(identity_public, .lower);
    var transcript_buf: [account_identity.max_transcript_len]u8 = undefined;
    const transcript = account_identity.transcript(
        "Alice",
        "primary",
        identity_public,
        &transcript_buf,
    ).?;
    const signature = try kp.sign(transcript, null);
    const sig_hex = std.fmt.bytesToHex(signature.toBytes(), .lower);

    var identity_add = irc_line.LineView{ .raw = "", .command = "IDENTITY" };
    identity_add.params[0] = "ADD";
    identity_add.params[1] = "primary";
    identity_add.params[2] = &public_hex;
    identity_add.params[3] = &sig_hex;
    identity_add.param_count = 4;
    try server.handleIdentity(conn, &identity_add);
    try std.testing.expectEqual(@as(usize, 4), kt.len());

    var identity_del = irc_line.LineView{ .raw = "", .command = "IDENTITY" };
    identity_del.params[0] = "DEL";
    identity_del.params[1] = "primary";
    identity_del.param_count = 2;
    try server.handleIdentity(conn, &identity_del);
    try std.testing.expectEqual(@as(usize, 5), kt.len());

    const bind_e2ee = try kt.eventAt(0);
    try std.testing.expectEqual(key_transparency.Action.bind, bind_e2ee.action);
    try std.testing.expectEqual(key_transparency.CredentialKind.e2ee_device, bind_e2ee.kind);
    const del_e2ee = try kt.eventAt(1);
    try std.testing.expectEqual(key_transparency.Action.delete, del_e2ee.action);
    const bind_id = try kt.eventAt(3);
    try std.testing.expectEqual(key_transparency.CredentialKind.identity, bind_id.kind);
    try std.testing.expectEqualSlices(u8, &key_transparency.factObservationHash(.{
        .account = "alice",
        .kind = .identity,
        .action = .bind,
        .key_id = "primary",
        .hlc = @intCast(bind_id.timestamp_ms),
        .origin_node = server.localPropOriginNode(),
        .origin_pubkey = "",
    }, &identity_public), &bind_id.key_hash);
    const del_id = try kt.eventAt(4);
    try std.testing.expectEqual(key_transparency.Action.delete, del_id.action);

    const root = kt.root();
    for (0..kt.len()) |position| {
        const owned = try kt.eventAt(position);
        var proof = try kt.proof(position);
        defer proof.deinit(alloc);
        try std.testing.expect(key_transparency.verifyInclusion(
            root,
            owned.asEvent(),
            proof,
            position,
            kt.len(),
        ));
    }
}

fn enrollTestE2eeDevice(server: *Server, account: []const u8, device: []const u8) !void {
    var key_buf: [e2ee_policy.device_prop_prefix.len + e2ee_policy.max_device_id_len]u8 = undefined;
    const key = e2ee_policy.devicePropKey(device, &key_buf) orelse return error.TestUnexpectedResult;
    const entity = ircx_prop_store.Entity{ .kind = .user, .id = account };
    _ = try server.props.setProp(entity, key, "mls-x25519:abcd", .{ .id = account, .access = .member });
}

test "E2EEGROUP cap-exhausted login and late negotiation fail explicitly before membership" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
        .session_max_per_account = 1,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const owner_id = try addTestLocalClient(&server, "Owner", "shared");
    _ = try server.world.join("#secure", worldIdFromClient(owner_id));
    try std.testing.expect(server.sessions.containsClient("shared", monitorIdFromClient(owner_id)));

    // Model normal pre-registration capability negotiation followed by account
    // login. The sole account slot remains attached to Owner, so the login must
    // fail the E2EE eligibility boundary before autojoin can run.
    const login_id = try addTestLocalClient(&server, "LoginExtra", null);
    const login_extra = server.connFor(login_id).?;
    login_extra.session.addCap(.standard_replies);
    login_extra.session.addCap(.onyx_e2ee);
    try server.finishLogin(login_extra, "shared");
    try std.testing.expect(login_extra.closing);
    try std.testing.expectEqualStrings("E2EE reusable session unavailable", login_extra.close_reason);
    try expectContains(
        login_extra.send_buf[0..login_extra.send_len],
        "FAIL E2EEGROUP SESSION_UNAVAILABLE :onyx/e2ee requires an available reusable session",
    );
    try std.testing.expect(!server.sessions.containsClient("shared", monitorIdFromClient(login_id)));
    try std.testing.expect(!server.world.isMember("#secure", worldIdFromClient(login_id)));

    // CAP is also legal after registration. A legacy/untracked logged-in socket
    // may request onyx/e2ee there, but it is closed explicitly instead of being
    // silently omitted from encrypted fan-out.
    const cap_id = try addTestLocalClient(&server, "CapExtra", "shared");
    const cap_extra = server.connFor(cap_id).?;
    cap_extra.session.registration.registered = true;
    cap_extra.session.addCap(.standard_replies);
    try std.testing.expect(!cap_extra.session.hasCap(.onyx_e2ee));
    try std.testing.expect(!server.sessions.containsClient("shared", monitorIdFromClient(cap_id)));
    try server.processLiveLine(cap_id, cap_extra, "CAP REQ :onyx/e2ee");
    try std.testing.expect(cap_extra.session.hasCap(.onyx_e2ee));
    try std.testing.expect(cap_extra.closing);
    try expectContains(
        cap_extra.send_buf[0..cap_extra.send_len],
        "FAIL E2EEGROUP SESSION_UNAVAILABLE :onyx/e2ee requires an available reusable session",
    );
    try std.testing.expect(!server.world.isMember("#secure", worldIdFromClient(cap_id)));
}

test "E2EEGROUP guest CAP REQ onyx/e2ee after registration stays open" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
        .session_max_per_account = 2,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    // True unauthenticated guest: registered, no account, no reusable SessionStore
    // row. Best-effort delivery permits onyx/e2ee without SESSION_UNAVAILABLE.
    const guest_id = try addTestLocalClient(&server, "GuestE2ee", null);
    const guest = server.connFor(guest_id).?;
    guest.session.registration.registered = true;
    guest.session.addCap(.standard_replies);
    try std.testing.expect(guest.session.account() == null);
    try std.testing.expect(!guest.session.hasCap(.onyx_e2ee));
    try std.testing.expect(!server.attachmentHasReusableSession(guest_id));
    try server.processLiveLine(guest_id, guest, "CAP REQ :onyx/e2ee");
    try std.testing.expect(guest.session.hasCap(.onyx_e2ee));
    try std.testing.expect(!guest.closing);
    try std.testing.expect(std.mem.indexOf(u8, guest.send_buf[0..guest.send_len], "SESSION_UNAVAILABLE") == null);
    try std.testing.expect(std.mem.indexOf(u8, guest.send_buf[0..guest.send_len], "E2EEGROUP") == null);
}

test "E2EEGROUP local handler renders exact capable-member and targeted Welcome lines" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const sender_id = try addTestLocalClient(&server, "Alice", "alice");
    const bob_id = try addTestLocalClient(&server, "Bob", "bob");
    const bob_phone_id = try addTestLocalClient(&server, "BobPhone", "bob");
    const old_id = try addTestLocalClient(&server, "Old", "old");
    const outsider_id = try addTestLocalClient(&server, "Outside", "outside");
    const sender = server.connFor(sender_id).?;
    const bob = server.connFor(bob_id).?;
    const bob_phone = server.connFor(bob_phone_id).?;
    const old = server.connFor(old_id).?;
    const outsider = server.connFor(outsider_id).?;

    for ([_]*ConnState{ sender, bob, bob_phone, old, outsider }) |conn| conn.ircx = true;
    for ([_]*ConnState{ sender, bob, bob_phone, outsider }) |conn| conn.session.addCap(.onyx_e2ee);
    _ = try server.world.join("#secure", worldIdFromClient(sender_id));
    _ = try server.world.join("#secure", worldIdFromClient(bob_id));
    _ = try server.world.join("#secure", worldIdFromClient(bob_phone_id));
    _ = try server.world.join("#secure", worldIdFromClient(old_id));
    try enrollTestE2eeDevice(&server, "alice", "phone");
    try enrollTestE2eeDevice(&server, "bob", "tablet");

    var key_package = try irc_line.parseLine("E2EEGROUP #secure key-package phone :AQIDBA");
    try server.handleE2eeGroup(sender, &key_package);
    const expected_key = ":Alice!alice@localhost E2EE.KEYPACKAGE #secure alice phone :AQIDBA\r\n";
    try expectContains(sender.send_buf[0..sender.send_len], expected_key);
    try expectContains(bob.send_buf[0..bob.send_len], expected_key);
    try expectContains(bob_phone.send_buf[0..bob_phone.send_len], expected_key);
    try std.testing.expectEqual(@as(usize, 0), old.send_len);
    try std.testing.expectEqual(@as(usize, 0), outsider.send_len);

    sender.send_len = 0;
    sender.send_offset = 0;
    bob.send_len = 0;
    bob.send_offset = 0;
    bob_phone.send_len = 0;
    bob_phone.send_offset = 0;
    var commit = try irc_line.parseLine("E2EEGROUP #secure commit phone :b3BhcXVl");
    try server.handleE2eeGroup(sender, &commit);
    const expected_commit = ":Alice!alice@localhost E2EE.COMMIT #secure alice phone :b3BhcXVl\r\n";
    try expectContains(sender.send_buf[0..sender.send_len], expected_commit);
    try expectContains(bob.send_buf[0..bob.send_len], expected_commit);
    try expectContains(bob_phone.send_buf[0..bob_phone.send_len], expected_commit);

    sender.send_len = 0;
    sender.send_offset = 0;
    bob.send_len = 0;
    bob.send_offset = 0;
    bob_phone.send_len = 0;
    bob_phone.send_offset = 0;
    // Wire account spelling is preserved for clients, while the route-first
    // SessionStore lookup must use the canonical lowercase key stored at login.
    var welcome = try irc_line.parseLine("E2EEGROUP #secure welcome phone Bob tablet :d2VsY29tZQ");
    try server.handleE2eeGroup(sender, &welcome);
    const expected_welcome = ":Alice!alice@localhost E2EE.WELCOME #secure alice phone Bob tablet :d2VsY29tZQ\r\n";
    try std.testing.expectEqual(@as(usize, 0), sender.send_len);
    try expectContains(bob.send_buf[0..bob.send_len], expected_welcome);
    try expectContains(bob_phone.send_buf[0..bob_phone.send_len], expected_welcome);
    try std.testing.expectEqual(@as(usize, 0), old.send_len);
    try std.testing.expectEqual(@as(usize, 0), outsider.send_len);
}

test "E2EEGROUP local handler fails closed and accepts the full payload bound" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const sender_id = try addTestLocalClient(&server, "Alice", "alice");
    const target_id = try addTestLocalClient(&server, "Bob", "bob");
    const off_channel_id = try addTestLocalClient(&server, "Carol", "carol");
    const guest_id = try addTestLocalClient(&server, "Guest", null);
    const no_cap_id = try addTestLocalClient(&server, "NoCap", "nocap");
    const no_ircx_id = try addTestLocalClient(&server, "NoIrcx", "noircx");
    const outsider_id = try addTestLocalClient(&server, "Outside", "outside");
    const sender = server.connFor(sender_id).?;
    const target = server.connFor(target_id).?;
    const off_channel = server.connFor(off_channel_id).?;
    const guest = server.connFor(guest_id).?;
    const no_cap = server.connFor(no_cap_id).?;
    const no_ircx = server.connFor(no_ircx_id).?;
    const outsider = server.connFor(outsider_id).?;
    for ([_]*ConnState{ sender, target, off_channel, guest, outsider }) |conn| {
        conn.ircx = true;
        conn.session.addCap(.onyx_e2ee);
    }
    no_cap.ircx = true;
    no_ircx.session.addCap(.onyx_e2ee);
    _ = try server.world.join("#secure", worldIdFromClient(sender_id));
    _ = try server.world.join("#secure", worldIdFromClient(target_id));
    _ = try server.world.join("#secure", worldIdFromClient(guest_id));
    _ = try server.world.join("#secure", worldIdFromClient(no_cap_id));
    _ = try server.world.join("#secure", worldIdFromClient(no_ircx_id));
    try enrollTestE2eeDevice(&server, "alice", "phone");
    try enrollTestE2eeDevice(&server, "bob", "tablet");
    try enrollTestE2eeDevice(&server, "carol", "laptop");

    var malformed = try irc_line.parseLine("E2EEGROUP #secure commit phone :not+base64url");
    try server.handleE2eeGroup(sender, &malformed);
    try expectContains(sender.send_buf[0..sender.send_len], "FAIL E2EEGROUP BAD_PAYLOAD");
    try std.testing.expectEqual(@as(usize, 0), target.send_len);

    sender.send_len = 0;
    sender.send_offset = 0;
    var unowned = try irc_line.parseLine("E2EEGROUP #secure commit missing :AQIDBA");
    try server.handleE2eeGroup(sender, &unowned);
    try expectContains(sender.send_buf[0..sender.send_len], "FAIL E2EEGROUP DEVICE_NOT_OWNED");
    try std.testing.expectEqual(@as(usize, 0), target.send_len);

    sender.send_len = 0;
    sender.send_offset = 0;
    var no_target_device = try irc_line.parseLine("E2EEGROUP #secure welcome phone bob missing :AQIDBA");
    try server.handleE2eeGroup(sender, &no_target_device);
    try expectContains(sender.send_buf[0..sender.send_len], "FAIL E2EEGROUP TARGET_UNAVAILABLE");
    try std.testing.expectEqual(@as(usize, 0), target.send_len);

    sender.send_len = 0;
    sender.send_offset = 0;
    var off_channel_target = try irc_line.parseLine("E2EEGROUP #secure welcome phone carol laptop :AQIDBA");
    try server.handleE2eeGroup(sender, &off_channel_target);
    try expectContains(sender.send_buf[0..sender.send_len], "FAIL E2EEGROUP TARGET_UNAVAILABLE");
    try std.testing.expectEqual(@as(usize, 0), off_channel.send_len);

    var guest_line = try irc_line.parseLine("E2EEGROUP #secure commit phone :AQIDBA");
    try server.handleE2eeGroup(guest, &guest_line);
    try expectContains(guest.send_buf[0..guest.send_len], "FAIL E2EEGROUP NOT_LOGGED_IN");

    var no_cap_line = try irc_line.parseLine("E2EEGROUP #secure commit phone :AQIDBA");
    try server.handleE2eeGroup(no_cap, &no_cap_line);
    try expectContains(no_cap.send_buf[0..no_cap.send_len], "FAIL E2EEGROUP CAP_REQUIRED");

    var no_ircx_line = try irc_line.parseLine("E2EEGROUP #secure commit phone :AQIDBA");
    try server.handleE2eeGroup(no_ircx, &no_ircx_line);
    try expectContains(no_ircx.send_buf[0..no_ircx.send_len], "FAIL E2EEGROUP IRCX_REQUIRED");

    var outsider_line = try irc_line.parseLine("E2EEGROUP #secure commit phone :AQIDBA");
    try server.handleE2eeGroup(outsider, &outsider_line);
    try expectContains(outsider.send_buf[0..outsider.send_len], "FAIL E2EEGROUP NOT_ON_CHANNEL");

    var max_payload: [e2ee_group_control.max_payload_len]u8 = @splat('A');
    var max_line = irc_line.LineView{ .raw = "", .command = "E2EEGROUP" };
    max_line.params[0] = "#secure";
    max_line.params[1] = "commit";
    max_line.params[2] = "phone";
    max_line.params[3] = &max_payload;
    max_line.param_count = 4;
    sender.send_len = 0;
    sender.send_offset = 0;
    target.send_len = 0;
    target.send_offset = 0;
    try server.handleE2eeGroup(sender, &max_line);
    var expected_buf: [e2ee_group_max_line_bytes]u8 = undefined;
    const expected = try std.fmt.bufPrint(
        &expected_buf,
        ":Alice!alice@localhost E2EE.COMMIT #secure alice phone :{s}\r\n",
        .{&max_payload},
    );
    try std.testing.expectEqualSlices(u8, expected, target.send_buf[0..target.send_len]);
}

test "E2EEGROUP live operator quiesce is privileged observable non-mutating and reversible" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    // Exercise the registered command path with the accounts feature actually
    // available. A nil services pointer intentionally disables that registry
    // feature, which would test its generic 421 gate instead of the E2EEGROUP
    // authoring barrier below.
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(alloc, std.testing.io, tmp.dir, "e2ee-group-quiesce.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);

    var pair = try SessionReplayTestPair.initWithSeeds(alloc, 0xa1, 0xa2);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var server = Server.init(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
        .mesh_connect = &.{"peer.test:7777"},
        .e2ee_group_authoring_enabled = false,
        .account_services = &services,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const peer_id = try server.rx().clients.alloc(ConnState.init(-1));
    const peer_conn = server.rx().clients.get(peer_id).?;
    peer_conn.overflow_allocator = alloc;
    peer_conn.token = try tokenFromId(peer_id);
    peer_conn.send_armed = true;
    peer_conn.sendq_cap = default_sendq_cap;
    peer_conn.s2s_secured = &pair.a;
    defer {
        peer_conn.s2s_secured = null;
        _ = server.rx().clients.free(peer_id);
    }

    const oper_id = try addTestLocalClient(&server, "Oper", "oper");
    const sender_id = try addTestLocalClient(&server, "Alice", "alice");
    const target_id = try addTestLocalClient(&server, "Bob", "bob");
    const oper = server.connFor(oper_id).?;
    const sender = server.connFor(sender_id).?;
    const target = server.connFor(target_id).?;
    for ([_]*ConnState{ oper, sender, target }) |conn|
        conn.session.registration.registered = true;
    try reconcileTestOper(&oper.session, oper_mod.OperPrivileges.full, "netadmin", "Network Admin");
    oper.session.addCap(.standard_replies);
    sender.ircx = true;
    sender.session.addCap(.standard_replies);
    sender.session.addCap(.onyx_e2ee);
    target.session.addCap(.onyx_e2ee);
    _ = try server.world.join("#secure", worldIdFromClient(sender_id));
    _ = try server.world.join("#secure", worldIdFromClient(target_id));
    try enrollTestE2eeDevice(&server, "alice", "phone");

    // The same live command path used by clients enforces privilege before
    // touching the process-local activation barrier.
    try server.processLiveLine(sender_id, sender, "E2EEGROUP ON");
    try expectContains(sender.send_buf[0..sender.send_len], " 481 Alice E2EEGROUP ");
    try std.testing.expect(!server.e2ee_group_local_authoring_enabled.load(.acquire));
    resetTestSendQ(sender);

    try server.processLiveLine(oper_id, oper, "E2EEGROUP STATUS");
    try expectContains(
        oper.send_buf[0..oper.send_len],
        "E2EEGROUP STATUS local_authoring=OFF quiesced=1 current_peers=1 required_peers=1 activation_ready=1 custody=0 receipts=0 pending=0",
    );
    resetTestSendQ(oper);

    // The startup config keeps a cold successor quiesced. Even an operator
    // cannot release that barrier while its configured peer is missing.
    peer_conn.s2s_secured = null;
    try server.processLiveLine(oper_id, oper, "E2EEGROUP ON");
    try expectContains(oper.send_buf[0..oper.send_len], "FAIL E2EEGROUP PEERS_NOT_CURRENT");
    try expectContains(oper.send_buf[0..oper.send_len], "current-capable peers=0 required peers=1");
    try std.testing.expect(!server.e2ee_group_local_authoring_enabled.load(.acquire));
    resetTestSendQ(oper);

    // Inbound-only mesh (S2S listen / trust without dial targets and without a
    // live peer) must also fail closed: 0/0 readiness would let ON succeed
    // while the dual-node peer is still pre-v2 or absent.
    const prior_mesh_connect = server.config.mesh_connect;
    server.config.mesh_connect = &.{};
    server.config.s2s_port = 6697;
    try server.processLiveLine(oper_id, oper, "E2EEGROUP ON");
    try expectContains(oper.send_buf[0..oper.send_len], "FAIL E2EEGROUP PEERS_NOT_CURRENT");
    try expectContains(oper.send_buf[0..oper.send_len], "current-capable peers=0 required peers=1");
    try std.testing.expect(!server.e2ee_group_local_authoring_enabled.load(.acquire));
    const inbound_only = server.e2eeGroupOperationalState();
    try std.testing.expectEqual(@as(usize, 0), inbound_only.current_peers);
    try std.testing.expectEqual(@as(usize, 1), inbound_only.required_peers);
    try std.testing.expect(!inbound_only.activationReady());
    resetTestSendQ(oper);
    server.config.mesh_connect = prior_mesh_connect;
    server.config.s2s_port = 0;
    peer_conn.s2s_secured = &pair.a;

    // An established secured transport is still ineligible until the exact
    // E2EEGROUP current-capability bit is present.
    if (pair.a.inner) |inner| {
        inner.peer.peer_supports_e2ee_group_current = false;
    } else return error.TestUnexpectedResult;
    try server.processLiveLine(oper_id, oper, "E2EEGROUP ON");
    try expectContains(oper.send_buf[0..oper.send_len], "FAIL E2EEGROUP PEERS_NOT_CURRENT");
    try expectContains(oper.send_buf[0..oper.send_len], "current-capable peers=0 required peers=1");
    try std.testing.expect(!server.e2ee_group_local_authoring_enabled.load(.acquire));
    resetTestSendQ(oper);
    pair.a.inner.?.peer.peer_supports_e2ee_group_current = true;

    // Non-operator STATUS never discloses count gauges (privilege before read).
    resetTestSendQ(sender);
    try server.processLiveLine(sender_id, sender, "E2EEGROUP STATUS");
    try expectContains(sender.send_buf[0..sender.send_len], " 481 Alice E2EEGROUP ");
    try std.testing.expect(std.mem.indexOf(u8, sender.send_buf[0..sender.send_len], "custody=") == null);
    try std.testing.expect(std.mem.indexOf(u8, sender.send_buf[0..sender.send_len], "local_authoring=") == null);
    resetTestSendQ(sender);

    // OFF never depends on peer readiness and is idempotent.
    try server.processLiveLine(oper_id, oper, "E2EEGROUP OFF");
    try expectContains(oper.send_buf[0..oper.send_len], "local_authoring=OFF quiesced=1");
    try std.testing.expect(!server.e2ee_group_local_authoring_enabled.load(.acquire));
    resetTestSendQ(oper);

    const Seed = struct {
        fn admit(
            srv: *Server,
            identity: *const node_identity.NodeIdentity,
            hlc: u64,
            peers: []const u64,
            ingress_peer: ?u64,
        ) !e2ee_group_relay.RelayId {
            var origin_pubkey: [e2ee_group_relay.pubkey_len]u8 = undefined;
            var origin_sig: [e2ee_group_relay.sig_len]u8 = undefined;
            var record = e2ee_group_relay.RelayRecord{
                .kind = .commit,
                .channel = "#seed",
                .source_prefix = "Seed!seed@local",
                .account = "seed",
                .from_device = "device",
                .payload = "AQIDBA",
                .origin_node = identity.shortId(),
                .hlc = hlc,
            };
            try e2ee_group_relay.stampOrigin(
                srv.allocator,
                &record,
                &identity.sign_kp,
                &origin_pubkey,
                &origin_sig,
            );
            const wire = try e2ee_group_relay.encode(srv.allocator, record);
            defer srv.allocator.free(wire);
            const verified = switch (try srv.e2ee_group_mesh_authority.verifyRecord(
                record,
                srv.meshWallMs(),
                mesh_clock_mod.default_max_future_skew_ms,
            )) {
                .verified => |value| value,
                else => return error.TestUnexpectedResult,
            };
            const admitted = try srv.e2ee_group_mesh_authority.admitAuthorizedWithCustodyAndIngress(
                verified,
                peers,
                wire,
                ingress_peer,
                srv.meshWallMs() + e2ee_group_initial_retry_ms,
            );
            try std.testing.expectEqual(
                std.meta.Tag(e2ee_group_mesh_authority.Admission).accepted,
                std.meta.activeTag(admitted.admission),
            );
            return verified.relay_id;
        }
    };

    // Seed independent outgoing custody and ingress-receipt obligations. The
    // public surface exposes only their depths, never either RelayId or wire.
    const custody_id = try Seed.admit(
        &server,
        &pair.ida,
        server.nextMeshHlc(),
        &.{pair.idb.shortId()},
        null,
    );
    const receipt_id = try Seed.admit(
        &server,
        &pair.ida,
        server.nextMeshHlc(),
        &.{},
        pair.idb.shortId(),
    );
    try server.processLiveLine(oper_id, oper, "E2EEGROUP STATUS");
    try expectContains(
        oper.send_buf[0..oper.send_len],
        "local_authoring=OFF quiesced=1 current_peers=1 required_peers=1 activation_ready=1 custody=1 receipts=1 pending=2",
    );
    resetTestSendQ(oper);

    var metrics: std.ArrayList(u8) = .empty;
    defer metrics.deinit(alloc);
    try server.writeE2eeGroupPrometheus(alloc, &metrics);
    try expectContains(metrics.items, "onyx_e2ee_group_local_authoring_enabled 0");
    try expectContains(metrics.items, "onyx_e2ee_group_current_capable_peers 1");
    try expectContains(metrics.items, "onyx_e2ee_group_required_peers 1");
    try expectContains(metrics.items, "onyx_e2ee_group_activation_ready 1");
    try expectContains(metrics.items, "onyx_e2ee_group_hop_custody 1");
    try expectContains(metrics.items, "onyx_e2ee_group_ingress_receipts 1");
    try expectContains(metrics.items, "onyx_e2ee_group_pending 2");

    // Quiesce never gates the authenticated receipt spine. A peer ACK retires
    // outgoing custody and ACK_CONFIRM retires ingress receipt while authoring
    // remains OFF.
    try pair.b.sendE2eeGroupAck(custody_id);
    const ack_wire = try alloc.dupe(u8, pair.b.outbound());
    defer alloc.free(ack_wire);
    pair.b.clearOutbound();
    server.driveS2sSecured(peer_conn, &pair.a, ack_wire);
    try pair.b.sendE2eeGroupAckConfirm(receipt_id);
    const confirm_wire = try alloc.dupe(u8, pair.b.outbound());
    defer alloc.free(confirm_wire);
    pair.b.clearOutbound();
    server.driveS2sSecured(peer_conn, &pair.a, confirm_wire);
    const drained = server.e2eeGroupOperationalState();
    try std.testing.expect(!drained.authoring_enabled);
    try std.testing.expectEqual(@as(usize, 0), drained.custody);
    try std.testing.expectEqual(@as(usize, 0), drained.receipts);
    try std.testing.expectEqual(@as(usize, 0), drained.pending);

    // A locally authored control is refused before nextMeshHlc, signing, replay
    // admission, custody, or attachment delivery can mutate.
    const authority_before = try server.e2ee_group_mesh_authority.encodeCheckpoint(alloc);
    defer alloc.free(authority_before);
    resetTestSendQ(sender);
    resetTestSendQ(target);
    try server.processLiveLine(
        sender_id,
        sender,
        "E2EEGROUP #secure commit phone :AQIDBA",
    );
    try expectContains(sender.send_buf[0..sender.send_len], "WARN E2EEGROUP AUTHORING_QUIESCED");
    try std.testing.expectEqual(@as(usize, 0), target.send_len);
    const authority_after = try server.e2ee_group_mesh_authority.encodeCheckpoint(alloc);
    defer alloc.free(authority_after);
    try std.testing.expectEqualSlices(u8, authority_before, authority_after);

    // Re-enabling restores the pre-quiesce live authoring path unchanged.
    resetTestSendQ(oper);
    try server.processLiveLine(oper_id, oper, "E2EEGROUP ON");
    try expectContains(oper.send_buf[0..oper.send_len], "local_authoring=ON quiesced=0");
    resetTestSendQ(sender);
    try server.processLiveLine(
        sender_id,
        sender,
        "E2EEGROUP #secure commit phone :AQIDBA",
    );
    try expectContains(
        target.send_buf[0..target.send_len],
        ":Alice!alice@localhost E2EE.COMMIT #secure alice phone :AQIDBA\r\n",
    );
}

test "E2EEGROUP mesh live path accepts once refloods exact wire retries and retires exact peer ACK" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var ingress = try SessionReplayTestPair.initWithSeeds(alloc, 0x41, 0x42);
    defer ingress.deinit();
    var egress = try SessionReplayTestPair.initWithSeeds(alloc, 0x41, 0x43);
    defer egress.deinit();
    var sim_time = reactor_mod.SimReactor.init(1_000_000);
    ingress.a.clearOutbound();
    ingress.b.clearOutbound();
    egress.a.clearOutbound();
    egress.b.clearOutbound();
    try std.testing.expect(ingress.a.supportsE2eeGroup());
    try std.testing.expect(ingress.b.supportsE2eeGroup());
    try std.testing.expect(egress.a.supportsE2eeGroup());
    try std.testing.expect(egress.b.supportsE2eeGroup());

    const server = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .num_shards = 2,
        .node_id = ingress.ida.shortId(),
        .node_identity = &ingress.ida,
        .crypto_io = std.testing.io,
        .reactor = sim_time.reactor(),
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();
    if (server.reactors.len < 2) return error.SkipZigTest;
    server.fabric = reactor_fabric.ReactorFabric.init(alloc, server.reactors.len) catch |err| switch (err) {
        error.ReactorWakeUnsupported => return error.SkipZigTest,
        else => return err,
    };
    current_reactor = &server.reactors[0];
    // Keep the live authority deliberately small so this one encrypted harness
    // also proves settled traffic does not consume finite pending capacity.
    server.e2ee_group_mesh_authority.deinit();
    server.e2ee_group_mesh_authority = try e2ee_group_mesh_authority.Authority.init(
        alloc,
        .{
            .replay = .{
                .window_size = 4,
                .max_origins = 16,
                .exact_history_size = 4,
            },
            .max_outbox_entries = 16,
            .max_receipts = 4,
        },
    );

    const Residence = struct {
        fn verify(
            _: *anyopaque,
            account: []const u8,
            nick: []const u8,
            origin_node: u64,
            _: bool,
        ) s2s_link.S2sLink.ResidenceDecision {
            if (origin_node != 0 and std.ascii.eqlIgnoreCase(account, "bob") and
                std.ascii.eqlIgnoreCase(nick, "Bob")) return .trusted;
            return .untrusted;
        }
    };
    ingress.a.setResidenceVerifier(.{ .ctx = server, .verify_fn = Residence.verify });

    const ingress_id = try server.rx().clients.alloc(ConnState.init(-1));
    const ingress_conn = server.rx().clients.get(ingress_id).?;
    ingress_conn.overflow_allocator = alloc;
    ingress_conn.token = try tokenFromId(ingress_id);
    ingress_conn.send_armed = true;
    ingress_conn.sendq_cap = default_sendq_cap;
    ingress_conn.s2s_secured = &ingress.a;
    const egress_id = try server.rx().clients.alloc(ConnState.init(-1));
    const egress_conn = server.rx().clients.get(egress_id).?;
    egress_conn.overflow_allocator = alloc;
    egress_conn.token = try tokenFromId(egress_id);
    egress_conn.send_armed = true;
    egress_conn.sendq_cap = default_sendq_cap;
    egress_conn.s2s_secured = &egress.a;
    defer {
        ingress_conn.s2s_secured = null;
        egress_conn.s2s_secured = null;
        _ = server.rx().clients.free(ingress_id);
        _ = server.rx().clients.free(egress_id);
    }
    // The secured-link cleanup above owns reactor-0 ids. Restore its owner
    // before that defer even if a later cross-shard assertion exits early.
    defer current_reactor = &server.reactors[0];

    const local_id = try addTestLocalClient(server, "Local", "local");
    const local = server.connFor(local_id).?;
    local.session.addCap(.onyx_e2ee);
    local.send_armed = true;
    _ = try server.world.join("#secure", worldIdFromClient(local_id));

    // A same-token physical sibling on another shard must receive its own
    // retained row. It deliberately keeps a distinct display nick: attachment
    // authority comes from the exact reusable token, not nick affinity.
    const local_token = server.sessions.resumeHandleForClient(
        "local",
        monitorIdFromClient(local_id),
    ).?.token;
    current_reactor = &server.reactors[1];
    const sibling_id = try addTestLocalClient(server, "LocalSibling", "local");
    const sibling = server.connFor(sibling_id).?;
    sibling.session.addCap(.onyx_e2ee);
    sibling.send_armed = true;
    try std.testing.expect(server.sessions.joinTokenGroup(
        "local",
        monitorIdFromClient(sibling_id),
        local_token,
    ));
    _ = try server.world.join("#secure", worldIdFromClient(sibling_id));

    // CAP alone is not E2EE participation authority. This anonymous capable
    // member remains in the room but is ineligible for durable delivery and
    // cannot pin custody or veto the tracked attachments' ACK.
    current_reactor = &server.reactors[0];
    const anonymous_id = try addTestLocalClient(server, "Anonymous", null);
    const anonymous = server.connFor(anonymous_id).?;
    anonymous.session.addCap(.onyx_e2ee);
    anonymous.send_armed = true;
    _ = try server.world.join("#secure", worldIdFromClient(anonymous_id));
    try enrollTestE2eeDevice(server, "bob", "phone");

    // Apply origin-bound membership/account authority before the E2EEGROUP
    // frame. This is the same same-read ordering enforced by driveS2sSecured.
    try ingress.b.sendMembership(
        "#secure",
        "Bob",
        0,
        server.nextMeshHlc(),
        true,
        .{
            .username = "bob",
            .realname = "Bob",
            .host = "peer-b.test",
            .account = "bob",
        },
        "",
    );
    const membership_wire = try alloc.dupe(u8, ingress.b.outbound());
    defer alloc.free(membership_wire);
    ingress.b.clearOutbound();
    server.driveS2sSecured(ingress_conn, &ingress.a, membership_wire);
    try std.testing.expect(!ingress_conn.closing);
    try std.testing.expect(server.remoteMemberOfChannelAtNode(
        "#secure",
        "Bob",
        ingress.idb.shortId(),
    ));
    try std.testing.expectEqualStrings(
        "bob",
        server.trustedRemoteAccountAtNode("Bob", ingress.idb.shortId()).?,
    );
    // Do not discard any encrypted authority response emitted by `ingress.a`:
    // that would advance its send counter without advancing `ingress.b`'s
    // receive counter, making the later authenticated E2EEGROUP receipt look
    // corrupt. Page and consume the response before beginning the assertion
    // window.
    const authority_response = try copyTestSendQ(alloc, ingress_conn);
    defer alloc.free(authority_response);
    resetTestSendQ(ingress_conn);
    if (authority_response.len != 0)
        try ingress.b.feed(authority_response, server.meshWallMs());
    try std.testing.expectEqual(@as(usize, 0), ingress.a.outbound().len);
    current_reactor = &server.reactors[1];
    server.drainFabric();
    current_reactor = &server.reactors[0];
    resetTestSendQ(egress_conn);
    local.send_len = 0;
    local.send_offset = 0;
    sibling.send_len = 0;
    sibling.send_offset = 0;
    anonymous.send_len = 0;
    anonymous.send_offset = 0;
    egress.a.clearOutbound();

    var origin_pubkey: [e2ee_group_relay.pubkey_len]u8 = undefined;
    var origin_sig: [e2ee_group_relay.sig_len]u8 = undefined;
    var record = e2ee_group_relay.RelayRecord{
        .kind = .commit,
        .channel = "#secure",
        .source_prefix = "Bob!bob@peer-b.test",
        .account = "bob",
        .from_device = "phone",
        .payload = "AQIDBA",
        .origin_node = ingress.idb.shortId(),
        .hlc = server.nextMeshHlc(),
    };
    try e2ee_group_relay.stampOrigin(
        alloc,
        &record,
        &ingress.idb.sign_kp,
        &origin_pubkey,
        &origin_sig,
    );
    const exact_wire = try e2ee_group_relay.encode(alloc, record);
    defer alloc.free(exact_wire);
    const relay_id = switch (try e2ee_group_relay.verifyAndRelayId(alloc, record)) {
        .verified => |id| id,
        else => return error.TestUnexpectedResult,
    };

    // First attempt cannot reserve the complete two-attachment batch. The
    // exact ingress must remain unseen and receive no ACK; otherwise the sender
    // could retire its only copy before any local handoff existed.
    var limited_spool = try attachment_delivery_spool.Spool.init(alloc, .{
        .max_attachments = 1,
        .max_records = 1,
        .max_total_bytes = 512,
        .max_record_bytes = 256,
    });
    var limited_installed = false;
    defer {
        if (limited_installed) std.mem.swap(
            attachment_delivery_spool.Spool,
            &server.attachment_delivery_spool,
            &limited_spool,
        );
        limited_spool.deinit();
    }
    std.mem.swap(
        attachment_delivery_spool.Spool,
        &server.attachment_delivery_spool,
        &limited_spool,
    );
    limited_installed = true;
    _ = try server.attachment_delivery_spool.reserveBatch(&.{.{
        .client = monitorIdFromClient(local_id),
        .event_id = @splat(0x95),
        .bytes = ":seed!u@h E2EE.COMMIT #secure phone :occupy\r\n",
    }});
    const spool_before_refusal = try server.attachment_delivery_spool.encodeCheckpoint(alloc);
    defer alloc.free(spool_before_refusal);
    const authority_before_refusal = try server.e2ee_group_mesh_authority.encodeCheckpoint(alloc);
    defer alloc.free(authority_before_refusal);
    try ingress.b.sendE2eeGroup(record);
    const refused_ciphertext = try alloc.dupe(u8, ingress.b.outbound());
    ingress.b.clearOutbound();
    server.driveS2sSecured(ingress_conn, &ingress.a, refused_ciphertext);
    alloc.free(refused_ciphertext);
    const refused_reply = try copyTestSendQ(alloc, ingress_conn);
    defer alloc.free(refused_reply);
    try std.testing.expectEqual(@as(usize, 0), refused_reply.len);
    try std.testing.expectEqual(@as(usize, 0), ingress.a.outbound().len);
    const refused_verified = switch (try server.e2ee_group_mesh_authority.authenticateRecord(record)) {
        .verified => |identity| identity,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(
        e2ee_group_mesh_authority.IdentityLookup.unseen,
        server.e2ee_group_mesh_authority.probeIdentity(refused_verified),
    );
    try std.testing.expectEqual(@as(usize, 0), server.e2ee_group_mesh_authority.custodyLen());
    try std.testing.expectEqual(@as(usize, 0), server.e2ee_group_mesh_authority.receiptLen());
    try std.testing.expectEqual(@as(usize, 1), server.attachment_delivery_spool.len());
    const spool_after_refusal = try server.attachment_delivery_spool.encodeCheckpoint(alloc);
    defer alloc.free(spool_after_refusal);
    const authority_after_refusal = try server.e2ee_group_mesh_authority.encodeCheckpoint(alloc);
    defer alloc.free(authority_after_refusal);
    try std.testing.expectEqualSlices(u8, spool_before_refusal, spool_after_refusal);
    try std.testing.expectEqualSlices(u8, authority_before_refusal, authority_after_refusal);

    // Restore the roomy live spool. Retrying the byte-identical signed origin
    // now reaches the joint ADS1 + replay/custody/receipt cut.
    std.mem.swap(
        attachment_delivery_spool.Spool,
        &server.attachment_delivery_spool,
        &limited_spool,
    );
    limited_installed = false;
    resetTestSendQ(ingress_conn);
    local.sendq_cap = 0;
    sibling.sendq_cap = 0;
    try ingress.b.replayRetainedE2eeGroupWire(exact_wire);
    const ingress_ciphertext = try alloc.dupe(u8, ingress.b.outbound());
    defer alloc.free(ingress_ciphertext);
    ingress.b.clearOutbound();
    server.driveS2sSecured(ingress_conn, &ingress.a, ingress_ciphertext);
    try std.testing.expectEqual(@as(usize, 2), server.attachment_delivery_spool.len());
    try std.testing.expectEqual(@as(usize, 0), local.send_len);
    try std.testing.expectEqual(@as(usize, 0), sibling.send_len);
    try std.testing.expectEqual(@as(usize, 0), anonymous.send_len);
    try std.testing.expect(!local.closing);
    try std.testing.expect(!sibling.closing);
    try std.testing.expect(!local.delivery_gap.load(.acquire));
    try std.testing.expect(!sibling.delivery_gap.load(.acquire));
    var retained: [2]attachment_delivery_spool.PendingRecord = undefined;
    const retained_rows = server.attachment_delivery_spool.collectPending(&retained);
    try std.testing.expectEqual(@as(usize, 2), retained_rows.len);
    try expectContains(retained_rows[0].bytes, "E2EE.COMMIT #secure bob phone :AQIDBA");
    try expectContains(retained_rows[1].bytes, "E2EE.COMMIT #secure bob phone :AQIDBA");
    try std.testing.expectEqual(@as(usize, 1), server.e2ee_group_mesh_authority.custodyLen());
    try std.testing.expect(server.e2ee_group_mesh_authority.containsCustody(
        egress.idb.shortId(),
        relay_id,
    ));

    // The accepted inbound hop receives a receipt only after global admission.
    const ingress_ack_ciphertext = try copyTestSendQ(alloc, ingress_conn);
    defer alloc.free(ingress_ack_ciphertext);
    resetTestSendQ(ingress_conn);
    try ingress.b.feed(ingress_ack_ciphertext, server.meshWallMs());
    const ingress_acks = try ingress.b.takeInboundE2eeGroupAcks();
    defer alloc.free(ingress_acks);
    try std.testing.expectEqual(@as(usize, 1), ingress_acks.len);
    try std.testing.expectEqualSlices(u8, &relay_id, &ingress_acks[0]);

    // Free each physical SendQ independently. The shard-local drains retire
    // exactly their own ADS1 head, and each attachment observes one copy.
    local.sendq_cap = default_sendq_cap;
    server.drainAttachmentSpoolForCurrentReactor();
    try std.testing.expectEqual(@as(usize, 1), server.attachment_delivery_spool.len());
    current_reactor = &server.reactors[1];
    sibling.sendq_cap = default_sendq_cap;
    server.drainAttachmentSpoolForCurrentReactor();
    current_reactor = &server.reactors[0];
    try std.testing.expectEqual(@as(usize, 0), server.attachment_delivery_spool.len());
    const delivered_line = ":Bob!bob@peer-b.test E2EE.COMMIT #secure bob phone :AQIDBA\r\n";
    try std.testing.expectEqual(
        @as(usize, 1),
        countOccurrences(local.send_buf[0..local.send_len], delivered_line),
    );
    try std.testing.expectEqual(
        @as(usize, 1),
        countOccurrences(sibling.send_buf[0..sibling.send_len], delivered_line),
    );
    try std.testing.expectEqual(@as(usize, 0), anonymous.send_len);
    // Drop this first ACK at the application boundary: the durable ingress
    // receipt must remain until a later retry is explicitly confirmed.
    try std.testing.expect(server.e2ee_group_mesh_authority.containsReceipt(
        ingress.idb.shortId(),
        relay_id,
    ));
    // An ACK from the ingress hop cannot retire C's distinct custody row.
    try std.testing.expect(server.e2ee_group_mesh_authority.containsCustody(
        egress.idb.shortId(),
        relay_id,
    ));

    // The eligible second direct peer receives byte-identical signed origin.
    const first_reflood = try copyTestSendQ(alloc, egress_conn);
    defer alloc.free(first_reflood);
    resetTestSendQ(egress_conn);
    try egress.b.feed(first_reflood, server.meshWallMs());
    const first_inbound = try egress.b.takeInboundE2eeGroup();
    defer {
        for (first_inbound) |*item| item.deinit(alloc);
        alloc.free(first_inbound);
    }
    try std.testing.expectEqual(@as(usize, 1), first_inbound.len);
    try std.testing.expectEqualSlices(u8, exact_wire, first_inbound[0].wire);

    // Reactor-0 receipt retry recovers the deliberately lost first ACK without
    // replaying or redelivering the control. ACK_CONFIRM retires only B's exact
    // ingress receipt; C's outgoing custody remains independently retained.
    sim_time.advance(3 * e2ee_group_initial_retry_ms);
    server.retryE2eeGroupReceipts();
    const ingress_ack_retry_ciphertext = try copyTestSendQ(alloc, ingress_conn);
    defer alloc.free(ingress_ack_retry_ciphertext);
    resetTestSendQ(ingress_conn);
    try ingress.b.feed(ingress_ack_retry_ciphertext, server.meshWallMs());
    const ingress_ack_retries = try ingress.b.takeInboundE2eeGroupAcks();
    defer alloc.free(ingress_ack_retries);
    try std.testing.expectEqual(@as(usize, 1), ingress_ack_retries.len);
    try std.testing.expectEqualSlices(u8, &relay_id, &ingress_ack_retries[0]);
    try ingress.b.sendE2eeGroupAckConfirm(relay_id);
    const ingress_confirm_ciphertext = try alloc.dupe(u8, ingress.b.outbound());
    defer alloc.free(ingress_confirm_ciphertext);
    ingress.b.clearOutbound();
    server.driveS2sSecured(
        ingress_conn,
        &ingress.a,
        ingress_confirm_ciphertext,
    );
    try std.testing.expect(!server.e2ee_group_mesh_authority.containsReceipt(
        ingress.idb.shortId(),
        relay_id,
    ));
    try std.testing.expect(server.e2ee_group_mesh_authority.containsCustody(
        egress.idb.shortId(),
        relay_id,
    ));

    // A lost C receipt remains recoverable through the public exact-wire replay
    // API. Saturate the healthy peer's SendQ: the first due attempt may retain
    // one complete encrypted record in the link, but every later timer pass
    // must preflight that record and leave both link growth and custody bounded.
    const egress_sendq_cap = egress_conn.sendq_cap;
    resetTestSendQ(egress_conn);
    egress_conn.sendq_cap = 1;
    egress_conn.send_buf[0] = 'x';
    egress_conn.send_len = 1;
    server.retryE2eeGroupCustody();
    const congested_retry_len = egress.a.outbound().len;
    try std.testing.expect(congested_retry_len != 0);
    var congested_round: usize = 0;
    while (congested_round < 8) : (congested_round += 1) {
        server.retryE2eeGroupCustody();
        try std.testing.expectEqual(congested_retry_len, egress.a.outbound().len);
        try std.testing.expect(!egress_conn.closing);
        try std.testing.expectEqual(
            @as(usize, 1),
            server.e2ee_group_mesh_authority.custodyLen(),
        );
    }
    resetTestSendQ(egress_conn);
    egress_conn.sendq_cap = egress_sendq_cap;
    try std.testing.expect(server.flushMeshBurstStage(egress_conn));
    try std.testing.expectEqual(@as(usize, 0), egress.a.outbound().len);
    const retry_ciphertext = try copyTestSendQ(alloc, egress_conn);
    defer alloc.free(retry_ciphertext);
    resetTestSendQ(egress_conn);
    try egress.b.feed(retry_ciphertext, server.meshWallMs());
    const retry_inbound = try egress.b.takeInboundE2eeGroup();
    defer {
        for (retry_inbound) |*item| item.deinit(alloc);
        alloc.free(retry_inbound);
    }
    try std.testing.expectEqual(@as(usize, 1), retry_inbound.len);
    try std.testing.expectEqualSlices(u8, exact_wire, retry_inbound[0].wire);

    // Replayed ingress is a global duplicate: no second local delivery, but it
    // is re-ACKed and re-drives the still-live C custody obligation. Remove the
    // mutable device authority first: a lost receipt must be resolved from the
    // retained exact identity, not stranded because account state changed after
    // the first globally authorized acceptance.
    try server.props.deleteProp(
        .{ .kind = .user, .id = "bob" },
        "e2ee.device.phone",
    );
    try std.testing.expect(!server.e2eeDeviceOwnedByAccount("bob", "phone"));
    // The accepted HLC is now more than the allowed future window ahead of the
    // receiver's apparent wall. Immutable duplicate proof must still win over
    // current skew policy and mutable authority drift.
    sim_time.advance(-600_000);
    try std.testing.expect(
        mesh_clock_mod.MeshClock.physicalOf(record.hlc) >
            server.meshWallMs() + mesh_clock_mod.default_max_future_skew_ms,
    );
    local.send_len = 0;
    local.send_offset = 0;
    resetTestSendQ(ingress_conn);
    resetTestSendQ(egress_conn);
    const ingress_sendq_cap = ingress_conn.sendq_cap;
    ingress_conn.sendq_cap = 1;
    ingress_conn.send_buf[0] = 'x';
    ingress_conn.send_len = 1;
    try ingress.b.replayRetainedE2eeGroupWire(exact_wire);
    const duplicate_ciphertext = try alloc.dupe(u8, ingress.b.outbound());
    defer alloc.free(duplicate_ciphertext);
    ingress.b.clearOutbound();
    server.driveS2sSecured(ingress_conn, &ingress.a, duplicate_ciphertext);
    try std.testing.expect(std.mem.indexOf(
        u8,
        local.send_buf[0..local.send_len],
        "E2EE.COMMIT",
    ) == null);
    const congested_ack_len = ingress.a.outbound().len;
    try std.testing.expect(congested_ack_len != 0);
    var duplicate_round: usize = 0;
    while (duplicate_round < 8) : (duplicate_round += 1) {
        try ingress.b.replayRetainedE2eeGroupWire(exact_wire);
        const repeated_ciphertext = try alloc.dupe(u8, ingress.b.outbound());
        ingress.b.clearOutbound();
        server.driveS2sSecured(ingress_conn, &ingress.a, repeated_ciphertext);
        alloc.free(repeated_ciphertext);
        try std.testing.expectEqual(congested_ack_len, ingress.a.outbound().len);
        try std.testing.expect(!ingress_conn.closing);
        try std.testing.expectEqual(
            @as(usize, 1),
            server.e2ee_group_mesh_authority.custodyLen(),
        );
        try std.testing.expect(std.mem.indexOf(
            u8,
            local.send_buf[0..local.send_len],
            "E2EE.COMMIT",
        ) == null);
    }
    resetTestSendQ(ingress_conn);
    ingress_conn.sendq_cap = ingress_sendq_cap;
    try std.testing.expect(server.flushMeshBurstStage(ingress_conn));
    try std.testing.expectEqual(@as(usize, 0), ingress.a.outbound().len);
    const duplicate_ack = try copyTestSendQ(alloc, ingress_conn);
    defer alloc.free(duplicate_ack);
    resetTestSendQ(ingress_conn);
    try ingress.b.feed(duplicate_ack, server.meshWallMs());
    const duplicate_acks = try ingress.b.takeInboundE2eeGroupAcks();
    defer alloc.free(duplicate_acks);
    try std.testing.expectEqual(@as(usize, 1), duplicate_acks.len);
    try std.testing.expectEqualSlices(u8, &relay_id, &duplicate_acks[0]);
    try std.testing.expect(server.e2ee_group_mesh_authority.containsReceipt(
        ingress.idb.shortId(),
        relay_id,
    ));
    try ingress.b.sendE2eeGroupAckConfirm(relay_id);
    const duplicate_confirm_ciphertext = try alloc.dupe(u8, ingress.b.outbound());
    defer alloc.free(duplicate_confirm_ciphertext);
    ingress.b.clearOutbound();
    server.driveS2sSecured(
        ingress_conn,
        &ingress.a,
        duplicate_confirm_ciphertext,
    );
    try std.testing.expect(!server.e2ee_group_mesh_authority.containsReceipt(
        ingress.idb.shortId(),
        relay_id,
    ));

    // The same stepped-back wall must still reject a genuinely unseen future
    // identity without consuming replay authority or emitting a receipt.
    var future_pubkey: [e2ee_group_relay.pubkey_len]u8 = undefined;
    var future_sig: [e2ee_group_relay.sig_len]u8 = undefined;
    var future_record = record;
    future_record.hlc += 1;
    try e2ee_group_relay.stampOrigin(
        alloc,
        &future_record,
        &ingress.idb.sign_kp,
        &future_pubkey,
        &future_sig,
    );
    const future_verified = switch (try server.e2ee_group_mesh_authority.authenticateRecord(
        future_record,
    )) {
        .verified => |identity| identity,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(e2ee_group_mesh_authority.isFutureSkewed(
        future_verified,
        server.meshWallMs(),
        mesh_clock_mod.default_max_future_skew_ms,
    ));
    try ingress.b.sendE2eeGroup(future_record);
    const future_ciphertext = try alloc.dupe(u8, ingress.b.outbound());
    defer alloc.free(future_ciphertext);
    ingress.b.clearOutbound();
    resetTestSendQ(ingress_conn);
    server.driveS2sSecured(ingress_conn, &ingress.a, future_ciphertext);
    const future_reply = try copyTestSendQ(alloc, ingress_conn);
    defer alloc.free(future_reply);
    try std.testing.expectEqual(@as(usize, 0), future_reply.len);
    lockSpin(&server.e2ee_group_mesh_mu);
    const future_lookup = server.e2ee_group_mesh_authority.probeIdentity(future_verified);
    const custody_len_after_future = server.e2ee_group_mesh_authority.custodyLen();
    server.e2ee_group_mesh_mu.unlock();
    try std.testing.expectEqual(
        e2ee_group_mesh_authority.IdentityLookup.unseen,
        future_lookup,
    );
    try std.testing.expectEqual(@as(usize, 1), custody_len_after_future);

    // Only C's authenticated ACK retires `(C, RelayId)`. Drop the first
    // ACK_CONFIRM after decoding it, then send a duplicate ACK: even though
    // custody is already gone, A must emit the exact confirm again.
    try egress.b.sendE2eeGroupAck(relay_id);
    const egress_ack_ciphertext = try alloc.dupe(u8, egress.b.outbound());
    defer alloc.free(egress_ack_ciphertext);
    egress.b.clearOutbound();
    server.driveS2sSecured(egress_conn, &egress.a, egress_ack_ciphertext);
    try std.testing.expectEqual(@as(usize, 0), server.e2ee_group_mesh_authority.custodyLen());
    const first_ack_confirm_ciphertext = try copyTestSendQ(alloc, egress_conn);
    defer alloc.free(first_ack_confirm_ciphertext);
    resetTestSendQ(egress_conn);
    try egress.b.feed(first_ack_confirm_ciphertext, server.meshWallMs());
    const dropped_ack_confirms = try egress.b.takeInboundE2eeGroupAckConfirms();
    defer alloc.free(dropped_ack_confirms);
    try std.testing.expectEqual(@as(usize, 1), dropped_ack_confirms.len);
    try std.testing.expectEqualSlices(u8, &relay_id, &dropped_ack_confirms[0]);

    try egress.b.sendE2eeGroupAck(relay_id);
    const duplicate_egress_ack_ciphertext = try alloc.dupe(u8, egress.b.outbound());
    defer alloc.free(duplicate_egress_ack_ciphertext);
    egress.b.clearOutbound();
    server.driveS2sSecured(
        egress_conn,
        &egress.a,
        duplicate_egress_ack_ciphertext,
    );
    const retried_ack_confirm_ciphertext = try copyTestSendQ(alloc, egress_conn);
    defer alloc.free(retried_ack_confirm_ciphertext);
    resetTestSendQ(egress_conn);
    try egress.b.feed(retried_ack_confirm_ciphertext, server.meshWallMs());
    const retried_ack_confirms = try egress.b.takeInboundE2eeGroupAckConfirms();
    defer alloc.free(retried_ack_confirms);
    try std.testing.expectEqual(@as(usize, 1), retried_ack_confirms.len);
    try std.testing.expectEqualSlices(u8, &relay_id, &retried_ack_confirms[0]);
    try std.testing.expectEqual(@as(usize, 0), server.e2ee_group_mesh_authority.custodyLen());

    // Consume C's queued exact-wire retries so both encrypted receive counters
    // are aligned before exercising a full B -> A -> C -> A -> B reflection
    // cycle. Once C's obligation is ACKed, duplicates from either side may earn
    // a receipt, but must never recreate the opposite edge.
    const queued_c_retries = try copyTestSendQ(alloc, egress_conn);
    defer alloc.free(queued_c_retries);
    resetTestSendQ(egress_conn);
    if (queued_c_retries.len != 0)
        try egress.b.feed(queued_c_retries, server.meshWallMs());
    const queued_c_inbound = try egress.b.takeInboundE2eeGroup();
    defer {
        for (queued_c_inbound) |*item| item.deinit(alloc);
        alloc.free(queued_c_inbound);
    }

    var cycle_round: usize = 0;
    while (cycle_round < 3) : (cycle_round += 1) {
        resetTestSendQ(ingress_conn);
        resetTestSendQ(egress_conn);
        local.send_len = 0;
        local.send_offset = 0;

        try ingress.b.replayRetainedE2eeGroupWire(exact_wire);
        const from_b = try alloc.dupe(u8, ingress.b.outbound());
        ingress.b.clearOutbound();
        server.driveS2sSecured(ingress_conn, &ingress.a, from_b);
        alloc.free(from_b);
        try std.testing.expectEqual(@as(usize, 0), server.e2ee_group_mesh_authority.custodyLen());
        try std.testing.expectEqual(@as(usize, 0), egress_conn.send_len);
        try std.testing.expectEqual(@as(usize, 0), egress.a.outbound().len);
        try std.testing.expectEqual(@as(usize, 0), local.send_len);
        const ack_b = try copyTestSendQ(alloc, ingress_conn);
        resetTestSendQ(ingress_conn);
        try ingress.b.feed(ack_b, server.meshWallMs());
        alloc.free(ack_b);
        const acks_b = try ingress.b.takeInboundE2eeGroupAcks();
        try std.testing.expectEqual(@as(usize, 1), acks_b.len);
        try std.testing.expectEqualSlices(u8, &relay_id, &acks_b[0]);
        alloc.free(acks_b);
        try ingress.b.sendE2eeGroupAckConfirm(relay_id);
        const confirm_b = try alloc.dupe(u8, ingress.b.outbound());
        ingress.b.clearOutbound();
        server.driveS2sSecured(ingress_conn, &ingress.a, confirm_b);
        alloc.free(confirm_b);
        try std.testing.expect(!server.e2ee_group_mesh_authority.containsReceipt(
            ingress.idb.shortId(),
            relay_id,
        ));

        try egress.b.replayRetainedE2eeGroupWire(exact_wire);
        const from_c = try alloc.dupe(u8, egress.b.outbound());
        egress.b.clearOutbound();
        server.driveS2sSecured(egress_conn, &egress.a, from_c);
        alloc.free(from_c);
        try std.testing.expectEqual(@as(usize, 0), server.e2ee_group_mesh_authority.custodyLen());
        try std.testing.expectEqual(@as(usize, 0), ingress_conn.send_len);
        try std.testing.expectEqual(@as(usize, 0), ingress.a.outbound().len);
        try std.testing.expectEqual(@as(usize, 0), local.send_len);
        const ack_c = try copyTestSendQ(alloc, egress_conn);
        resetTestSendQ(egress_conn);
        try egress.b.feed(ack_c, server.meshWallMs());
        alloc.free(ack_c);
        const acks_c = try egress.b.takeInboundE2eeGroupAcks();
        try std.testing.expectEqual(@as(usize, 1), acks_c.len);
        try std.testing.expectEqualSlices(u8, &relay_id, &acks_c[0]);
        alloc.free(acks_c);
        try egress.b.sendE2eeGroupAckConfirm(relay_id);
        const confirm_c = try alloc.dupe(u8, egress.b.outbound());
        egress.b.clearOutbound();
        server.driveS2sSecured(egress_conn, &egress.a, confirm_c);
        alloc.free(confirm_c);
        try std.testing.expect(!server.e2ee_group_mesh_authority.containsReceipt(
            egress.idb.shortId(),
            relay_id,
        ));
    }

    // More than 10x the deliberately small pending cap of settled local
    // controls must continue to admit: no custody and no ingress receipt means
    // no pending-exact slot is consumed. Since the original receipt/custody is
    // fully settled above, aging it beyond the ordinary window must retire it.
    sim_time.advance(600_000);
    const later_count =
        server.e2ee_group_mesh_authority.config.replay.exact_history_size * 10 + 1;
    var later_index: usize = 0;
    while (later_index < later_count) : (later_index += 1) {
        var later_pubkey: [e2ee_group_relay.pubkey_len]u8 = undefined;
        var later_sig: [e2ee_group_relay.sig_len]u8 = undefined;
        var later_record = record;
        later_record.hlc = record.hlc + @as(u64, @intCast(later_index + 1));
        try e2ee_group_relay.stampOrigin(
            alloc,
            &later_record,
            &ingress.idb.sign_kp,
            &later_pubkey,
            &later_sig,
        );
        const later_wire = try e2ee_group_relay.encode(alloc, later_record);
        const later_verified = switch (try server.e2ee_group_mesh_authority.authenticateRecord(
            later_record,
        )) {
            .verified => |identity| identity,
            else => return error.TestUnexpectedResult,
        };
        lockSpin(&server.e2ee_group_mesh_mu);
        const later_admitted = server.e2ee_group_mesh_authority.admitAuthorizedWithCustody(
            later_verified,
            &.{},
            later_wire,
        ) catch |err| {
            server.e2ee_group_mesh_mu.unlock();
            alloc.free(later_wire);
            return err;
        };
        server.e2ee_group_mesh_mu.unlock();
        alloc.free(later_wire);
        try std.testing.expectEqual(
            std.meta.Tag(e2ee_group_mesh_authority.Admission).accepted,
            std.meta.activeTag(later_admitted.admission),
        );
    }
    const old_verified = switch (try server.e2ee_group_mesh_authority.authenticateRecord(
        record,
    )) {
        .verified => |identity| identity,
        else => return error.TestUnexpectedResult,
    };
    lockSpin(&server.e2ee_group_mesh_mu);
    const old_after_window = server.e2ee_group_mesh_authority.probeIdentity(old_verified);
    server.e2ee_group_mesh_mu.unlock();
    try std.testing.expectEqual(
        e2ee_group_mesh_authority.IdentityLookup.retired,
        old_after_window,
    );

    resetTestSendQ(ingress_conn);
    resetTestSendQ(egress_conn);
    local.send_len = 0;
    local.send_offset = 0;
    try ingress.b.replayRetainedE2eeGroupWire(exact_wire);
    const aged_retry = try alloc.dupe(u8, ingress.b.outbound());
    defer alloc.free(aged_retry);
    ingress.b.clearOutbound();
    server.driveS2sSecured(ingress_conn, &ingress.a, aged_retry);
    try std.testing.expectEqual(@as(usize, 0), local.send_len);
    try std.testing.expectEqual(@as(usize, 0), server.e2ee_group_mesh_authority.custodyLen());
    try std.testing.expectEqual(@as(usize, 0), egress_conn.send_len);
    const aged_ack = try copyTestSendQ(alloc, ingress_conn);
    defer alloc.free(aged_ack);
    try std.testing.expectEqual(@as(usize, 0), aged_ack.len);

    // Partition pressure consumes the four pending/receipt slots and fails the
    // fifth admission closed without guard-only acceptance. One exact confirm
    // frees capacity, and retrying the same fifth identity then succeeds.
    const pending_cap: usize = 4;
    var partition_ids: [pending_cap]e2ee_group_relay.RelayId = undefined;
    var partition_index: usize = 0;
    while (partition_index < pending_cap) : (partition_index += 1) {
        var partition_pubkey: [e2ee_group_relay.pubkey_len]u8 = undefined;
        var partition_sig: [e2ee_group_relay.sig_len]u8 = undefined;
        var partition_record = record;
        partition_record.hlc =
            record.hlc + @as(u64, @intCast(later_count + partition_index + 100));
        try e2ee_group_relay.stampOrigin(
            alloc,
            &partition_record,
            &ingress.idb.sign_kp,
            &partition_pubkey,
            &partition_sig,
        );
        const partition_wire = try e2ee_group_relay.encode(alloc, partition_record);
        const partition_verified = switch (try server.e2ee_group_mesh_authority.authenticateRecord(
            partition_record,
        )) {
            .verified => |identity| identity,
            else => return error.TestUnexpectedResult,
        };
        partition_ids[partition_index] = partition_verified.relay_id;
        lockSpin(&server.e2ee_group_mesh_mu);
        const partition_admitted = server.e2ee_group_mesh_authority.admitAuthorizedWithCustodyAndIngress(
            partition_verified,
            &.{},
            partition_wire,
            ingress.idb.shortId(),
            server.meshWallMs() +| e2ee_group_initial_retry_ms,
        ) catch |err| {
            server.e2ee_group_mesh_mu.unlock();
            alloc.free(partition_wire);
            return err;
        };
        server.e2ee_group_mesh_mu.unlock();
        alloc.free(partition_wire);
        try std.testing.expectEqual(
            std.meta.Tag(e2ee_group_mesh_authority.Admission).accepted,
            std.meta.activeTag(partition_admitted.admission),
        );
    }
    try std.testing.expectEqual(
        pending_cap,
        server.e2ee_group_mesh_authority.receiptLen(),
    );

    var overflow_pubkey: [e2ee_group_relay.pubkey_len]u8 = undefined;
    var overflow_sig: [e2ee_group_relay.sig_len]u8 = undefined;
    var overflow_record = record;
    overflow_record.hlc =
        record.hlc + @as(u64, @intCast(later_count + pending_cap + 100));
    try e2ee_group_relay.stampOrigin(
        alloc,
        &overflow_record,
        &ingress.idb.sign_kp,
        &overflow_pubkey,
        &overflow_sig,
    );
    const overflow_wire = try e2ee_group_relay.encode(alloc, overflow_record);
    defer alloc.free(overflow_wire);
    const overflow_verified = switch (try server.e2ee_group_mesh_authority.authenticateRecord(
        overflow_record,
    )) {
        .verified => |identity| identity,
        else => return error.TestUnexpectedResult,
    };
    lockSpin(&server.e2ee_group_mesh_mu);
    const overflow_refused = server.e2ee_group_mesh_authority.admitAuthorizedWithCustodyAndIngress(
        overflow_verified,
        &.{},
        overflow_wire,
        ingress.idb.shortId(),
        server.meshWallMs() +| e2ee_group_initial_retry_ms,
    );
    const overflow_probe = server.e2ee_group_mesh_authority.probeIdentity(overflow_verified);
    server.e2ee_group_mesh_mu.unlock();
    try std.testing.expectError(
        error.CapacityExceeded,
        overflow_refused,
    );
    try std.testing.expectEqual(
        e2ee_group_mesh_authority.IdentityLookup.unseen,
        overflow_probe,
    );
    try std.testing.expectEqual(
        pending_cap,
        server.e2ee_group_mesh_authority.receiptLen(),
    );

    lockSpin(&server.e2ee_group_mesh_mu);
    try std.testing.expect(try server.e2ee_group_mesh_authority.confirmIngress(
        ingress.idb.shortId(),
        partition_ids[0],
    ));
    const overflow_recovered = try server.e2ee_group_mesh_authority.admitAuthorizedWithCustodyAndIngress(
        overflow_verified,
        &.{},
        overflow_wire,
        ingress.idb.shortId(),
        server.meshWallMs() +| e2ee_group_initial_retry_ms,
    );
    server.e2ee_group_mesh_mu.unlock();
    try std.testing.expectEqual(
        std.meta.Tag(e2ee_group_mesh_authority.Admission).accepted,
        std.meta.activeTag(overflow_recovered.admission),
    );
    for (partition_ids[1..]) |partition_id| {
        lockSpin(&server.e2ee_group_mesh_mu);
        try std.testing.expect(try server.e2ee_group_mesh_authority.confirmIngress(
            ingress.idb.shortId(),
            partition_id,
        ));
        server.e2ee_group_mesh_mu.unlock();
    }
    lockSpin(&server.e2ee_group_mesh_mu);
    try std.testing.expect(try server.e2ee_group_mesh_authority.confirmIngress(
        ingress.idb.shortId(),
        overflow_verified.relay_id,
    ));
    server.e2ee_group_mesh_mu.unlock();
    try std.testing.expectEqual(
        @as(usize, 0),
        server.e2ee_group_mesh_authority.receiptLen(),
    );
}

test "E2EEGROUP configured disconnected peer remains in event-time custody" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    var local = try node_identity.fromSeed(@as([32]u8, @splat(0x51)), "e2ee-disconnected");
    defer local.deinit();
    var ingress = try node_identity.fromSeed(@as([32]u8, @splat(0x52)), "e2ee-disconnected");
    defer ingress.deinit();
    var disconnected = try node_identity.fromSeed(@as([32]u8, @splat(0x53)), "e2ee-disconnected");
    defer disconnected.deinit();
    const ingress_root = std.fmt.bytesToHex(ingress.sign_kp.public_key, .lower);
    const disconnected_root = std.fmt.bytesToHex(disconnected.sign_kp.public_key, .lower);
    const roots = [_][]const u8{ &ingress_root, &disconnected_root };

    const server = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = local.shortId(),
        .node_identity = &local,
        .crypto_io = std.testing.io,
        .mesh_trust_roots = &roots,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();

    const peers = try server.collectE2eeGroupOutboxPeers(ingress.shortId());
    defer alloc.free(peers);
    try std.testing.expectEqual(@as(usize, 1), peers.len);
    try std.testing.expectEqual(disconnected.shortId(), peers[0]);

    var origin_pubkey: [e2ee_group_relay.pubkey_len]u8 = undefined;
    var origin_sig: [e2ee_group_relay.sig_len]u8 = undefined;
    var record = e2ee_group_relay.RelayRecord{
        .kind = .key_package,
        .channel = "#offline-peer",
        .source_prefix = "Local!local@node.test",
        .account = "local",
        .from_device = "phone",
        .payload = "AQIDBA",
        .origin_node = local.shortId(),
        .hlc = server.nextMeshHlc(),
    };
    try e2ee_group_relay.stampOrigin(
        alloc,
        &record,
        &local.sign_kp,
        &origin_pubkey,
        &origin_sig,
    );
    const wire = try e2ee_group_relay.encode(alloc, record);
    defer alloc.free(wire);
    const verification = try server.e2ee_group_mesh_authority.verifyRecord(
        record,
        server.meshWallMs(),
        mesh_clock_mod.default_max_future_skew_ms,
    );
    const verified = switch (verification) {
        .verified => |identity| identity,
        else => return error.TestUnexpectedResult,
    };
    const admitted = try server.e2ee_group_mesh_authority.admitAuthorizedWithCustody(
        verified,
        peers,
        wire,
    );
    try std.testing.expect(admitted.admission == .accepted);
    try std.testing.expect(server.e2ee_group_mesh_authority.containsCustody(
        disconnected.shortId(),
        verified.relay_id,
    ));

    // A retry while C is down emits nothing and cannot retire its exact row.
    server.retryE2eeGroupCustody();
    try std.testing.expect(server.e2ee_group_mesh_authority.containsCustody(
        disconnected.shortId(),
        verified.relay_id,
    ));
    // Another authenticated direct peer cannot steal C's obligation.
    try std.testing.expect(!try server.e2ee_group_mesh_authority.acknowledge(
        ingress.shortId(),
        verified.relay_id,
    ));
    try std.testing.expect(try server.e2ee_group_mesh_authority.acknowledge(
        disconnected.shortId(),
        verified.relay_id,
    ));
    try std.testing.expectEqual(@as(usize, 0), server.e2ee_group_mesh_authority.custodyLen());
}

