// P1 (F1 account-key authority): the ENTITY_PROP ingest gate that makes the
// replicated `identity.key.*`/`identity.residence.*` pubkey source authoritative
// enough for residence trust. A Byzantine admitted peer must not be able to
// inject `identity.key.<victim>` = its own key; without this gate Design C's
// premise (the replicated pubkey is authoritative) is unmet.
fn makeEntityPropChange(
    kind: entity_prop_event.EntityKind,
    entity: []const u8,
    key: []const u8,
    value: []const u8,
    hlc: u64,
    origin_node: u64,
) struct {
    present: bool,
    kind: entity_prop_event.EntityKind,
    origin_node: u64,
    hlc: u64,
    entity: []const u8,
    key: []const u8,
    value: []const u8,
    owner: []const u8,
    origin_pubkey: []const u8,
    origin_sig: []const u8,
} {
    return .{
        .present = true,
        .kind = kind,
        .origin_node = origin_node,
        .hlc = hlc,
        .entity = entity,
        .key = key,
        .value = value,
        .owner = entity,
        .origin_pubkey = "", // unsigned path: entityPropOriginVerified ⇒ .unsigned ⇒ true
        .origin_sig = "",
    };
}

test "P1: identity.key ENTITY_PROP ingest rejects a REMOTE write for a LOCALLY-homed account (local SASL anchor)" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x71)), "local");
    defer ident.deinit();
    const self_node = ident.shortId();
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .node_id = self_node, .node_identity = &ident }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    // kain is SASL-authenticated on THIS node ⇒ this node is kain's authoritative
    // home. Even with NO enrolled key yet (clock absent), a remote-origin write
    // for kain's identity key is a forgery and must be rejected fail-closed.
    _ = try addTestLocalClient(&server, "kain", "kain");

    const byz_node: u64 = self_node ^ 0xABCD; // some other admitted peer
    var forged = makeEntityPropChange(.user, "kain", "identity.key.primary", "forged-key-value", 100, byz_node);
    try std.testing.expect(!server.applyRemoteEntityProp(&forged));
    // Nothing was stored: the victim's key is untouched.
    const entity = ircx_prop_store.Entity{ .kind = .user, .id = "kain" };
    try std.testing.expectError(error.PropMissing, server.props.getProp(entity, "identity.key.primary"));

    // A residence prop for the locally-homed account is likewise rejected from a
    // remote origin.
    var rkey_buf: [account_identity.residence_prop_prefix.len + account_identity.residence_node_hex_len]u8 = undefined;
    const rkey = account_identity.residencePropKey(byz_node, &rkey_buf).?;
    var forged_res = makeEntityPropChange(.user, "kain", rkey, "deadbeef", 100, byz_node);
    try std.testing.expect(!server.applyRemoteEntityProp(&forged_res));
}

test "E5E1 identity ENTITY_PROP ingest rejects every remote origin before LWW" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x72)), "local");
    defer ident.deinit();
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .node_id = ident.shortId(), .node_identity = &ident }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    // Neither an asserted home nor a later competing origin may establish the
    // retired replicated identity namespace.
    const home_a: u64 = 0xA;
    const byz_b: u64 = 0xB;
    const key_a = "home-A-key-value";
    var genuine = makeEntityPropChange(.user, "kain", "identity.key.primary", key_a, 100, home_a);
    try std.testing.expect(!server.applyRemoteEntityProp(&genuine));
    const entity = ircx_prop_store.Entity{ .kind = .user, .id = "kain" };
    try std.testing.expectError(error.PropMissing, server.props.getProp(entity, "identity.key.primary"));

    // A Byzantine peer B tries to OVERWRITE kain's key with its own, at a HIGHER
    // hlc so plain LWW would accept it — the origin binding rejects it.
    const key_b = "byzantine-B-value";
    var forged = makeEntityPropChange(.user, "kain", "identity.key.primary", key_b, 999, byz_b);
    try std.testing.expect(!server.applyRemoteEntityProp(&forged));
    try std.testing.expectError(error.PropMissing, server.props.getProp(entity, "identity.key.primary"));

    // Even the same asserted origin cannot rotate through ENTITY_PROP.
    const key_a2 = "home-A-rotated-v2";
    var rotate = makeEntityPropChange(.user, "kain", "identity.key.primary", key_a2, 200, home_a);
    try std.testing.expect(!server.applyRemoteEntityProp(&rotate));
    try std.testing.expectError(error.PropMissing, server.props.getProp(entity, "identity.key.primary"));
    try std.testing.expectEqual(@as(u64, 3), server.remote_identity_props_quarantined);
}

test "P1: a NON-identity user prop is NOT origin-bound (regression: ordinary ENTITY_PROP LWW is unchanged)" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x73)), "local");
    defer ident.deinit();
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .node_id = ident.shortId(), .node_identity = &ident }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    // An ordinary user prop is NOT an identity anchor: a later, higher-hlc write
    // from a different node applies via plain LWW (the gate must not over-reach).
    var first = makeEntityPropChange(.user, "bob", "display.pronouns", "they", 100, 0xA);
    try std.testing.expect(server.applyRemoteEntityProp(&first));
    var second = makeEntityPropChange(.user, "bob", "display.pronouns", "she", 200, 0xB);
    try std.testing.expect(server.applyRemoteEntityProp(&second));
    const entity = ircx_prop_store.Entity{ .kind = .user, .id = "bob" };
    try std.testing.expectEqualStrings("she", (try server.props.getProp(entity, "display.pronouns")).value);
}

test "ISUPPORT advertises ACCOUNTRESIDENCE only when the node has a mesh identity (account residence discovery)" {
    // Without a node identity the 005 burst is byte-identical (no token).
    const plain = try buildIsupportTokens(std.testing.allocator, .{ .port = 0 });
    defer freeIsupportTokens(std.testing.allocator, plain);
    for (plain) |tok| try std.testing.expect(!std.mem.startsWith(u8, tok, "ACCOUNTRESIDENCE="));

    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x63)), "local");
    defer ident.deinit();
    const with_ident = try buildIsupportTokens(std.testing.allocator, .{ .port = 0, .node_identity = &ident });
    defer freeIsupportTokens(std.testing.allocator, with_ident);
    var expected_buf: [64]u8 = undefined;
    const expected = try std.fmt.bufPrint(&expected_buf, "ACCOUNTRESIDENCE={x:0>16}", .{ident.shortId()});
    var found = false;
    for (with_ident) |tok| {
        if (std.mem.eql(u8, tok, expected)) found = true;
    }
    try std.testing.expect(found);
}

test "WEBAUTHN register + passwordless auth (ES256), with tamper/challenge/regression rejects" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-wa-e2e.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("kain", "correct horse battery staple", &scratch);

    const rp_id = "chat.example";
    const origin = "https://chat.example";
    const origins = [_][]const u8{origin};
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
        .crypto_io = std.testing.io,
        .webauthn_rp_id = rp_id,
        .webauthn_origins = &origins,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    // The passkey key pair (would live in the authenticator).
    const kp = WaEc.KeyPair.generate(std.testing.io);
    const sec1 = kp.public_key.toUncompressedSec1();
    var cose: [77]u8 = undefined;
    waBuildCoseEs256(sec1[1..33].*, sec1[33..65].*, &cose);
    const cred_id_raw = "kain-passkey-01"; // 15 bytes
    var cred_id_b64_buf: [base64url.encodedLen(cred_id_raw.len)]u8 = undefined;
    const cred_id_b64 = try base64url.encode(&cred_id_b64_buf, cred_id_raw);

    // ── REGISTER (logged-in client) ─────────────────────────────────────────
    const reg_id = try addTestLocalClient(&server, "kain", "kain");
    const reg_conn = server.connFor(reg_id).?;
    reg_conn.send_len = 0;
    var reg_lv = irc_line.LineView{ .raw = "", .command = "WEBAUTHN" };
    reg_lv.params[0] = "REGISTER";
    reg_lv.params[1] = "phone";
    reg_lv.param_count = 2;
    try server.handleWebauthn(reg_conn, &reg_lv);
    const reg_chal = waTokenAfter(reg_conn.send_buf[0..reg_conn.send_len], "REGISTER-CHALLENGE ") orelse return error.TestUnexpectedResult;

    // Build the create clientDataJSON + registration authData (signCount 0).
    var cdj_buf: [512]u8 = undefined;
    const create_cdj = try std.fmt.bufPrint(&cdj_buf, "{{\"type\":\"webauthn.create\",\"challenge\":\"{s}\",\"origin\":\"{s}\"}}", .{ reg_chal, origin });
    var reg_ad_buf: [256]u8 = undefined;
    const reg_ad_len = waBuildRegAuthData(rp_id, 0, cred_id_raw, cose, &reg_ad_buf);
    var cdj_b64_buf: [1024]u8 = undefined;
    const cdj_b64 = try base64url.encode(&cdj_b64_buf, create_cdj);
    var ad_b64_buf: [512]u8 = undefined;
    const ad_b64 = try base64url.encode(&ad_b64_buf, reg_ad_buf[0..reg_ad_len]);

    reg_conn.send_len = 0;
    var rf_lv = irc_line.LineView{ .raw = "", .command = "WEBAUTHN" };
    rf_lv.params[0] = "REGISTER-FINISH";
    rf_lv.params[1] = cred_id_b64;
    rf_lv.params[2] = cdj_b64;
    rf_lv.params[3] = ad_b64;
    rf_lv.param_count = 4;
    try server.handleWebauthn(reg_conn, &rf_lv);
    // The result rides the Event Spine (`:server EVENT kain WEBAUTHN …`), NOT a
    // NOTICE — the onyx client consumes the WEBAUTHN EVENT plane.
    try expectContains(reg_conn.send_buf[0..reg_conn.send_len], " EVENT kain WEBAUTHN REGISTERED");
    try std.testing.expect(std.mem.indexOf(u8, reg_conn.send_buf[0..reg_conn.send_len], " NOTICE ") == null);
    // The credential is now durably bound to "kain".
    var cred: services_mod.Services.WebauthnCredential = .{};
    try services.webauthnLookup(cred_id_b64, &cred);
    try std.testing.expectEqualStrings("kain", cred.account());

    // helper closure to run one AUTH → AUTH-FINISH on a fresh logged-out client.
    const Ceremony = struct {
        fn run(
            srv: *Server,
            nick: []const u8,
            keypair: WaEc.KeyPair,
            cid_b64: []const u8,
            rpid: []const u8,
            org: []const u8,
            sign_count: u32,
            tamper_sig: bool,
            wrong_challenge: bool,
        ) !*ConnState {
            const cid = try addTestLocalClient(srv, nick, null);
            const c = srv.connFor(cid).?;
            c.send_len = 0;
            var a_lv = irc_line.LineView{ .raw = "", .command = "WEBAUTHN" };
            a_lv.params[0] = "AUTH";
            a_lv.params[1] = "kain";
            a_lv.param_count = 2;
            try srv.handleWebauthn(c, &a_lv);
            const chal = waTokenAfter(c.send_buf[0..c.send_len], "AUTH-CHALLENGE ") orelse return error.TestUnexpectedResult;

            var used_chal_buf: [64]u8 = undefined;
            const used_chal = if (wrong_challenge) blk: {
                // A syntactically-valid but different 32-byte challenge.
                var raw: [32]u8 = @splat(0x5a);
                break :blk try base64url.encode(&used_chal_buf, &raw);
            } else chal;

            var jbuf: [512]u8 = undefined;
            const get_cdj = try std.fmt.bufPrint(&jbuf, "{{\"type\":\"webauthn.get\",\"challenge\":\"{s}\",\"origin\":\"{s}\"}}", .{ used_chal, org });
            var adbuf: [37]u8 = undefined;
            waBuildAuthData(rpid, sign_count, &adbuf);
            var der_buf: [WaEc.Signature.der_encoded_length_max]u8 = undefined;
            const der = waSignDer(keypair, &adbuf, get_cdj, &der_buf);

            var cdjb: [1024]u8 = undefined;
            const cdj_enc = try base64url.encode(&cdjb, get_cdj);
            var adb: [128]u8 = undefined;
            const ad_enc = try base64url.encode(&adb, &adbuf);
            var sigb: [256]u8 = undefined;
            const sig_enc = try base64url.encode(&sigb, der);
            // Tamper directly in the mutable backing buffer (base64url.encode
            // returned a const view into `sigb`).
            if (tamper_sig) sigb[sig_enc.len - 2] = if (sig_enc[sig_enc.len - 2] == 'A') 'B' else 'A';

            c.send_len = 0;
            var f_lv = irc_line.LineView{ .raw = "", .command = "WEBAUTHN" };
            f_lv.params[0] = "AUTH-FINISH";
            f_lv.params[1] = cid_b64;
            f_lv.params[2] = cdj_enc;
            f_lv.params[3] = ad_enc;
            f_lv.params[4] = sig_enc;
            f_lv.param_count = 5;
            try srv.handleWebauthn(c, &f_lv);
            return c;
        }
    };

    // ── Successful passwordless login (signCount 10 > stored 0) ──────────────
    const ok_conn = try Ceremony.run(&server, "logan", kp, cred_id_b64, rp_id, origin, 10, false, false);
    try std.testing.expectEqualStrings("kain", ok_conn.session.account().?);
    try expectContains(ok_conn.send_buf[0..ok_conn.send_len], "You are now identified as kain");

    // ── Sign-count regression (5 <= stored 10) → rejected, not logged in ─────
    const regr_conn = try Ceremony.run(&server, "riley", kp, cred_id_b64, rp_id, origin, 5, false, false);
    try std.testing.expect(regr_conn.session.account() == null);
    try expectContains(regr_conn.send_buf[0..regr_conn.send_len], "SIGN_COUNT_REGRESSION");

    // ── Tampered signature → rejected, not logged in ─────────────────────────
    const tamper_conn = try Ceremony.run(&server, "quinn", kp, cred_id_b64, rp_id, origin, 20, true, false);
    try std.testing.expect(tamper_conn.session.account() == null);
    try expectContains(tamper_conn.send_buf[0..tamper_conn.send_len], "ASSERTION_FAILED");

    // ── Wrong challenge → rejected before signature check ────────────────────
    const wc_conn = try Ceremony.run(&server, "sasha", kp, cred_id_b64, rp_id, origin, 30, false, true);
    try std.testing.expect(wc_conn.session.account() == null);
    try expectContains(wc_conn.send_buf[0..wc_conn.send_len], "CHALLENGE_MISMATCH");
}

test "WEBAUTHN LIST/RENAME ride the EVENT plane; CRED carries created_unix; RENAME round-trips" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-wa-event.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("kain", "correct horse battery staple", &scratch);

    // Bind a credential directly (the full ceremony is exercised elsewhere).
    const kp = WaEc.KeyPair.generate(std.testing.io);
    const sec1 = kp.public_key.toUncompressedSec1();
    var cose: [77]u8 = undefined;
    waBuildCoseEs256(sec1[1..33].*, sec1[33..65].*, &cose);
    const cred_id_raw = "kain-passkey-01";
    var cred_id_b64_buf: [base64url.encodedLen(cred_id_raw.len)]u8 = undefined;
    const cred_id_b64 = try base64url.encode(&cred_id_b64_buf, cred_id_raw);
    try services.webauthnBind("kain", cred_id_b64, &cose, 7, "phone", 1_700_000_000);

    const rp_id = "chat.example";
    const origins = [_][]const u8{"https://chat.example"};
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
        .crypto_io = std.testing.io,
        .webauthn_rp_id = rp_id,
        .webauthn_origins = &origins,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const cid = try addTestLocalClient(&server, "kain", "kain");
    const conn = server.connFor(cid).?;

    // ── LIST: reply is an EVENT line (NOT a NOTICE) and carries created_unix ──
    conn.send_len = 0;
    var list_lv = irc_line.LineView{ .raw = "", .command = "WEBAUTHN" };
    list_lv.params[0] = "LIST";
    list_lv.param_count = 1;
    try server.handleWebauthn(conn, &list_lv);
    const list_out = conn.send_buf[0..conn.send_len];
    var exp_buf: [256]u8 = undefined;
    const exp_cred = try std.fmt.bufPrint(&exp_buf, " EVENT kain WEBAUTHN CRED {s} 7 1700000000 :phone", .{cred_id_b64});
    try expectContains(list_out, exp_cred);
    try expectContains(list_out, " EVENT kain WEBAUTHN LIST :end (1)");
    try std.testing.expect(std.mem.indexOf(u8, list_out, " NOTICE ") == null);

    // ── RENAME: relabels the passkey, replies via the EVENT plane, round-trips ──
    conn.send_len = 0;
    var ren_lv = irc_line.LineView{ .raw = "", .command = "WEBAUTHN" };
    ren_lv.params[0] = "RENAME";
    ren_lv.params[1] = cred_id_b64;
    ren_lv.params[2] = "laptop";
    ren_lv.param_count = 3;
    try server.handleWebauthn(conn, &ren_lv);
    const ren_out = conn.send_buf[0..conn.send_len];
    var exp2_buf: [256]u8 = undefined;
    const exp_ren = try std.fmt.bufPrint(&exp2_buf, " EVENT kain WEBAUTHN RENAMED {s} :laptop", .{cred_id_b64});
    try expectContains(ren_out, exp_ren);
    try std.testing.expect(std.mem.indexOf(u8, ren_out, " NOTICE ") == null);

    // The new label is durable; sign_count + created_unix are preserved.
    var cred: services_mod.Services.WebauthnCredential = .{};
    try services.webauthnLookup(cred_id_b64, &cred);
    try std.testing.expectEqualStrings("laptop", cred.label());
    try std.testing.expectEqual(@as(u32, 7), cred.sign_count);
    try std.testing.expectEqual(@as(i64, 1_700_000_000), cred.created_unix);

    // ── RENAME of an unbound id → NOT_FOUND FAIL (still not a NOTICE) ──
    conn.send_len = 0;
    var missing_id_buf: [base64url.encodedLen("nope-nope-nope-01".len)]u8 = undefined;
    const missing_id = try base64url.encode(&missing_id_buf, "nope-nope-nope-01");
    var bad_lv = irc_line.LineView{ .raw = "", .command = "WEBAUTHN" };
    bad_lv.params[0] = "RENAME";
    bad_lv.params[1] = missing_id;
    bad_lv.params[2] = "ghost";
    bad_lv.param_count = 3;
    try server.handleWebauthn(conn, &bad_lv);
    try expectContains(conn.send_buf[0..conn.send_len], "NOT_FOUND");
}

test "WEBAUTHN malformed base64 rejected without panic" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-wa-bad.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("kain", "correct horse battery staple", &scratch);

    const origins = [_][]const u8{"https://chat.example"};
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
        .crypto_io = std.testing.io,
        .webauthn_rp_id = "chat.example",
        .webauthn_origins = &origins,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const reg_id = try addTestLocalClient(&server, "kain", "kain");
    const conn = server.connFor(reg_id).?;

    // Arm a register challenge, then hand REGISTER-FINISH garbage base64. Must be
    // a graceful FAIL, never a panic, and it consumes the single-use challenge.
    conn.send_len = 0;
    var reg_lv = irc_line.LineView{ .raw = "", .command = "WEBAUTHN" };
    reg_lv.params[0] = "REGISTER";
    reg_lv.param_count = 1;
    try server.handleWebauthn(conn, &reg_lv);

    conn.send_len = 0;
    var rf = irc_line.LineView{ .raw = "", .command = "WEBAUTHN" };
    rf.params[0] = "REGISTER-FINISH";
    rf.params[1] = "validcredid";
    rf.params[2] = "!!!not-base64!!!";
    rf.params[3] = "@@@also-bad@@@";
    rf.param_count = 4;
    try server.handleWebauthn(conn, &rf);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL WEBAUTHN");

    // Challenge was single-use: a second FINISH now reports NO_PENDING.
    conn.send_len = 0;
    try server.handleWebauthn(conn, &rf);
    try expectContains(conn.send_buf[0..conn.send_len], "NO_PENDING");
}

// ── WEBAUTHN passkey-label exploit corpus ──────────────────────────────────
//
// The passkey label is user-controlled text that is stored durably (base64url,
// so control bytes survive) and later reflected back to the caller on the
// Event Spine (`WEBAUTHN CRED …`, `WEBAUTHN RENAMED …`). The attack class is
// CWE-93 CRLF/command injection through a smuggled label, plus the robustness
// gap of a control-laden label poisoning the durable record so LIST silently
// drops that credential's line. These assert fail-closed: rejected at the
// input boundary (BAD_LABEL), no poison stored, no forged wire line — and the
// Event-Spine render firewall still holds as the last line of defence.

/// Bind a throwaway ES256 passkey to `account` under `services`, returning the
/// base64url credential id (borrowing `id_buf`). Keeps the exploit tests below
/// focused on the label/ownership surface, not the full ceremony.
fn waBindTestCred(
    services: *services_mod.Services,
    account: []const u8,
    cred_id_raw: []const u8,
    label: []const u8,
    id_buf: []u8,
) ![]const u8 {
    const kp = WaEc.KeyPair.generate(std.testing.io);
    const sec1 = kp.public_key.toUncompressedSec1();
    var cose: [77]u8 = undefined;
    waBuildCoseEs256(sec1[1..33].*, sec1[33..65].*, &cose);
    const cred_id_b64 = try base64url.encode(id_buf, cred_id_raw);
    try services.webauthnBind(account, cred_id_b64, &cose, 1, label, 1_700_000_000);
    return cred_id_b64;
}

test "exploit: WEBAUTHN RENAME rejects a CRLF-smuggled label (no poison stored, no wire injection)" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "exploit-wa-rename.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("kain", "correct horse battery staple", &scratch);
    var id_buf: [base64url.encodedLen("kain-key-01".len)]u8 = undefined;
    const cred_id_b64 = try waBindTestCred(&services, "kain", "kain-key-01", "phone", &id_buf);

    const origins = [_][]const u8{"https://chat.example"};
    const server = try std.testing.allocator.create(Server);
    defer std.testing.allocator.destroy(server);
    server.initInPlace(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
        .crypto_io = std.testing.io,
        .webauthn_rp_id = "chat.example",
        .webauthn_origins = &origins,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const cid = try addTestLocalClient(server, "kain", "kain");
    const conn = server.connFor(cid).?;

    // A label carrying CR/LF and a forged trailing IRC command. The handler
    // must reject it at the boundary — never store it, never render it.
    conn.send_len = 0;
    var lv = irc_line.LineView{ .raw = "", .command = "WEBAUTHN" };
    lv.params[0] = "RENAME";
    lv.params[1] = cred_id_b64;
    lv.params[2] = "pwn\r\nPRIVMSG #ops :hijacked-via-label";
    lv.param_count = 3;
    try server.handleWebauthn(conn, &lv);
    const out = conn.send_buf[0..conn.send_len];

    // Fail-closed: a clean BAD_LABEL reply, and NO forged command on the wire.
    try expectContains(out, "BAD_LABEL");
    try std.testing.expect(std.mem.indexOf(u8, out, "PRIVMSG") == null);
    try std.testing.expect(std.mem.indexOf(u8, out, "hijacked") == null);
    try std.testing.expect(std.mem.indexOf(u8, out, "RENAMED") == null);

    // The durable label is UNCHANGED — no poison reached the store.
    var cred: services_mod.Services.WebauthnCredential = .{};
    try services.webauthnLookup(cred_id_b64, &cred);
    try std.testing.expectEqualStrings("phone", cred.label());
}

