}

test "portable local NICK publishes exact Store authority before v2 authorization" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x6E)), "portable-nick-authority");
    defer ident.deinit();
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = ident.shortId(),
        .node_identity = &ident,
        .crypto_io = std.testing.io,
        .session_migrate_on_detach = true,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const id = try addTestLocalClient(&server, "Nova", "nova");
    const conn = server.connFor(id).?;
    const handle = server.sessions.resumeHandleForClient("nova", monitorIdFromClient(id)).?;
    try std.testing.expect(server.sessions.markPortableResumeIssued("nova", monitorIdFromClient(id)));
    try std.testing.expect(server.commitPortableSessionMutation(id, conn));

    var parsed = try irc_line.parseLine("NICK Nova2");
    try server.handleNickChange(id, conn, &parsed);
    try std.testing.expectEqualStrings("Nova2", conn.session.displayName());
    try std.testing.expect(!server.sessions.tokenReplicaDirty(handle.token));
    const current = server.session_replica_store.getOrigin(handle.token, ident.shortId()) orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("Nova2", current.nick);
    var snapshot = try migration_relay.Snapshot.decode(std.testing.allocator, current.snapshot);
    defer snapshot.deinit(std.testing.allocator);
    try std.testing.expectEqualStrings("Nova2", snapshot.nick);
    switch (LinuxServer.authorizeSessionTokenNick(&server, ident.shortId(), "Nova", null, "Nova2")) {
        .bind => |token| try std.testing.expect(std.crypto.timing_safe.eql(session_migrate.Token, token, handle.token)),
        .reject, .legacy => return error.TestUnexpectedResult,
    }
}

test "exact-token NICK enforces no-nick across sibling membership union" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const primary_id = try addTestLocalClient(&server, "Primary", "shared-acct");
    const sibling_id = try addTestLocalClient(&server, "Sibling", "shared-acct");
    const primary = server.connFor(primary_id).?;
    const sibling = server.connFor(sibling_id).?;
    const token = server.sessions.resumeHandleForClient("shared-acct", monitorIdFromClient(primary_id)).?.token;
    try std.testing.expect(server.sessions.joinTokenGroup("shared-acct", monitorIdFromClient(sibling_id), token));

    // Only the sibling is in +N. The initiating transport must not bypass the
    // logical session's restriction merely because its own World id is absent.
    try server.world.restoreMember("#locked", worldIdFromClient(sibling_id), world_model.MemberModes.empty());
    _ = try server.world.setChannelFlag("#locked", .no_nick, true);
    var parsed = try irc_line.parseLine("NICK Renamed");
    try server.handleNickChange(primary_id, primary, &parsed);
    try std.testing.expectEqualStrings("Primary", primary.session.displayName());
    try std.testing.expectEqualStrings("Sibling", sibling.session.displayName());
    try std.testing.expect(server.world.findNick("Renamed") == null);
    try expectContains(primary.send_buf[0..primary.send_len], "Cannot change nick while on #locked (+N)");

    // Once the sibling is an operator, the same identity-wide action succeeds
    // and every exact attachment adopts the new rendered nick.
    _ = try server.world.setMemberMode("#locked", worldIdFromClient(sibling_id), .op, true);
    primary.send_len = 0;
    try server.handleNickChange(primary_id, primary, &parsed);
    try std.testing.expectEqualStrings("Renamed", primary.session.displayName());
    try std.testing.expectEqualStrings("Renamed", sibling.session.displayName());
    try std.testing.expect(server.world.findNick("Renamed") != null);
}

test "MONITOR rename prepares unbounded watcher output before identity commit" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const id = try addTestLocalClient(&server, "Alice", "alice");
    const conn = server.connFor(id).?;
    try server.monitor.restoreOnline("Alice");

    // One watcher beyond the inline reply plan forces the live rename to own a
    // heap buffer. The watcher ids need not be connected: MONITOR's reverse
    // index is the authority being exercised, while delivery remains best-effort.
    for (0..65) |index| {
        var replies: [2]monitor.MonitorReply = undefined;
        var storage: [128]u8 = undefined;
        var sink = monitor.MonitorReplySink{ .replies = &replies, .storage = &storage };
        try server.monitor.addTargets(10_000 + index, "Alice", &sink);
    }
    try std.testing.expectEqual(@as(usize, 65), server.monitor.watcherCount("Alice"));

    // Deny the dynamic reply plan itself. No MONITOR occupancy or World/session
    // identity has moved, so an enclosing NICK/RESUME transaction can still
    // return without exposing a split-brain rename.
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{ .fail_index = 0 });
    const stable_allocator = server.allocator;
    {
        server.allocator = failing.allocator();
        defer server.allocator = stable_allocator;
        try std.testing.expectError(
            error.OutOfMemory,
            server.prepareMonitorOccupancyTransition("Alice", "Bob", false),
        );
    }
    try std.testing.expect(failing.has_induced_failure);
    try std.testing.expectEqualStrings("Alice", conn.session.displayName());
    try std.testing.expect(server.world.findNick("Alice") != null);
    try std.testing.expect(server.world.findNick("Bob") == null);
    try std.testing.expect(server.monitor.isOnline("Alice"));
    try std.testing.expect(!server.monitor.isOnline("Bob"));

    // With capacity available, the ordinary live path commits World, session,
    // and the derived MONITOR index together even though watcher delivery is
    // larger than the historical fixed sink.
    var parsed = try irc_line.parseLine("NICK Bob");
    try server.handleNickChange(id, conn, &parsed);
    try std.testing.expectEqualStrings("Bob", conn.session.displayName());
    try std.testing.expect(server.world.findNick("Alice") == null);
    try std.testing.expect(server.world.findNick("Bob") != null);
    try std.testing.expect(!server.monitor.isOnline("Alice"));
    try std.testing.expect(server.monitor.isOnline("Bob"));
}

