test "session replica nick index is case-folded bounded and ambiguity-safe" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const server = try std.testing.allocator.create(Server);
    defer std.testing.allocator.destroy(server);
    server.initInPlace(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const Fixture = struct {
        fn install(
            srv: *LinuxServer,
            client: sessions_mod.ClientId,
            token: session_migrate.Token,
            account: []const u8,
            nick: []const u8,
        ) !void {
            _ = try srv.sessions.attach(account, client, token, @intCast(client));
            const encoded = try (migration_relay.Snapshot{
                .nick = nick,
                .umodes = "+i",
                .channels = &.{},
                .account = account,
            }).encode(std.testing.allocator);
            defer std.testing.allocator.free(encoded);
            try std.testing.expect(srv.sessions.markDetachedWithSnapshot(account, client, encoded));
            srv.recordSessionReplicaRoute(token, 42);
            srv.recordSessionReplicaIdentity(token, account, nick);
        }

        fn updateNick(
            srv: *LinuxServer,
            client: sessions_mod.ClientId,
            token: session_migrate.Token,
            account: []const u8,
            nick: []const u8,
        ) !void {
            const encoded = try (migration_relay.Snapshot{
                .nick = nick,
                .umodes = "+i",
                .channels = &.{},
                .account = account,
            }).encode(std.testing.allocator);
            defer std.testing.allocator.free(encoded);
            try std.testing.expect(srv.sessions.markDetachedWithSnapshot(account, client, encoded));
            srv.recordSessionReplicaIdentity(token, account, nick);
        }
    };

    const t1: session_migrate.Token = @splat(1);
    const t2: session_migrate.Token = @splat(2);
    const t3: session_migrate.Token = @splat(3);
    // All three installs MUST share one English case-folded primary key ("nova").
    // Lookup uses mixed case "nOvA" — never the retired Japanese product nick.
    try Fixture.install(server, 1, t1, "acct-a", "Nova");
    const mixed = SessionReplicaNickKey.init("nOvA").?;
    var candidates = server.session_replica_nicks.get(mixed) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u8, 1), candidates.count);
    try std.testing.expect(!candidates.ambiguous);
    try std.testing.expect(std.crypto.timing_safe.eql(session_migrate.Token, t1, candidates.tokens[0]));

    try Fixture.install(server, 2, t2, "acct-b", "NOVA");
    candidates = server.session_replica_nicks.get(mixed) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u8, 2), candidates.count);
    try std.testing.expect(!candidates.ambiguous);

    try Fixture.install(server, 3, t3, "acct-c", "nova");
    candidates = server.session_replica_nicks.get(mixed) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u8, 2), candidates.count);
    try std.testing.expect(candidates.ambiguous);
    try std.testing.expect(server.detachedReplicaTokenForNick("NOVA") == null);
    try std.testing.expect(server.detachedReplicaTokenForNick("definitely-unknown") == null);

    // Historical same-nick identities do not poison a newly current detached
    // replica: rebuilding filters the stale rows before marking ambiguity.
    try std.testing.expect(server.sessions.remove("acct-a", 1));
    try std.testing.expect(server.sessions.remove("acct-b", 2));
    try std.testing.expect(server.sessions.remove("acct-c", 3));
    const t4: session_migrate.Token = @splat(4);
    try Fixture.install(server, 4, t4, "acct-d", "Nova");
    candidates = server.session_replica_nicks.get(mixed) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u8, 1), candidates.count);
    try std.testing.expect(!candidates.ambiguous);
    try std.testing.expect(std.crypto.timing_safe.eql(session_migrate.Token, t4, server.detachedReplicaTokenForNick("NOVA").?));

    // Updating a current token's nick rebuilds both primary keys outside the hot path.
    try Fixture.updateNick(server, 4, t4, "acct-d", "OldNick");
    try Fixture.updateNick(server, 4, t4, "acct-d", "NewNick");
    try std.testing.expect(server.session_replica_nicks.get(SessionReplicaNickKey.init("OldNick").?) == null);
    try std.testing.expect(server.session_replica_nicks.get(SessionReplicaNickKey.init("newnick").?) != null);
}

test "mesh nick-home claim fold is deterministic across every link order" {
    const claims = [_]s2s_link.NickClaim{
        .{ .node_id = 1, .hlc = 10 },
        .{ .node_id = 1, .hlc = 20 },
        .{ .node_id = 2, .hlc = 15 },
    };
    const permutations = [_][3]usize{
        .{ 0, 1, 2 }, .{ 0, 2, 1 }, .{ 1, 0, 2 },
        .{ 1, 2, 0 }, .{ 2, 0, 1 }, .{ 2, 1, 0 },
    };
    for (permutations) |permutation| {
        var best: ?s2s_link.NickClaim = null;
        for (permutation) |idx| mergeMeshNickClaim(&best, claims[idx]);
        try std.testing.expectEqual(@as(u64, 1), best.?.node_id);
        try std.testing.expectEqual(@as(u64, 20), best.?.hlc);
    }

    var tie: ?s2s_link.NickClaim = null;
    mergeMeshNickClaim(&tie, .{ .node_id = 3, .hlc = 7 });
    mergeMeshNickClaim(&tie, .{ .node_id = 9, .hlc = 7 });
    mergeMeshNickClaim(&tie, .{ .node_id = 9, .hlc = 7 });
    try std.testing.expectEqual(@as(u64, 9), tie.?.node_id);
}

test "relay direct messages honor local +R SILENCE and recipient session-sync" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        var relay_peer: s2s_link.S2sLink = undefined;
        try addTestRelayHomes(&server, &relay_peer, 99, &.{"Remote"});
        defer relay_peer.deinit();

        const target_id = try addTestLocalClient(&server, "Target", "targetacct");
        const sibling_id = try addTestLocalClient(&server, "Sibling", "targetacct");
        const target = server.connFor(target_id).?;
        const sibling = server.connFor(sibling_id).?;
        _ = target.session.setUmode(.regonly_pm, true);
        sibling.session.addCap(.onyx_session_sync);

        server.deliverRelay(.{
            .verb = .privmsg,
            .target = "Target",
            .source_nick = "Remote",
            .source_prefix = "Remote!r@host",
            // Mutable relay account text is not authentication and cannot
            // bypass the recipient's +R policy.
            .account = "forged-logged-in",
            .tags = "",
            .text = "blocked by +R",
            .origin_node = 99,
            .hlc = 1,
        });
        try std.testing.expectEqual(@as(usize, 0), target.send_len);
        try std.testing.expectEqual(@as(usize, 0), sibling.send_len);

        _ = target.session.setUmode(.regonly_pm, false);
        _ = target.session.setUmode(.callerid, true);
        server.deliverRelay(.{
            .verb = .privmsg,
            .target = "Target",
            .source_nick = "Remote",
            .source_prefix = "Remote!r@elsewhere",
            // Nor can an attacker claim the recipient account to obtain +g's
            // same-account bypass without signed residence/token authority.
            .account = "targetacct",
            .tags = "",
            .text = "blocked by +g",
            .origin_node = 99,
            .hlc = 2,
        });
        try std.testing.expectEqual(@as(usize, 0), target.send_len);
        try std.testing.expectEqual(@as(usize, 0), sibling.send_len);
        _ = target.session.setUmode(.callerid, false);
        _ = try server.silence.add("Target", "Remote!*@host");
        server.deliverRelay(.{
            .verb = .privmsg,
            .target = "Target",
            .source_nick = "Remote",
            .source_prefix = "Remote!r@host",
            .account = "remoteacct",
            .tags = "",
            .text = "blocked by silence",
            .origin_node = 99,
            .hlc = 3,
        });
        try std.testing.expectEqual(@as(usize, 0), target.send_len);
        try std.testing.expectEqual(@as(usize, 0), sibling.send_len);

        server.deliverRelay(.{
            .verb = .privmsg,
            .target = "Target",
            .source_nick = "Remote",
            .source_prefix = "Remote!r@elsewhere",
            .account = "remoteacct",
            .tags = "",
            .text = "delivered",
            .origin_node = 99,
            .hlc = 4,
        });
        try expectContains(target.send_buf[0..target.send_len], ":Remote!r@elsewhere PRIVMSG Target :delivered\r\n");
        try expectContains(sibling.send_buf[0..sibling.send_len], ":Remote!r@elsewhere PRIVMSG Target :delivered\r\n");
        try std.testing.expectEqual(@as(usize, 1), countOccurrences(sibling.send_buf[0..sibling.send_len], "PRIVMSG Target :delivered"));
    } else return error.SkipZigTest;
}

// Named with the "ACCESS" token so the focused `test-ircx` suite collects it:
// SILENCE is per-recipient access control, and a case-sensitive owner key let a
// silenced sender bypass the ignore simply by varying the target nick's case.
test "SILENCE ACCESS control is case-insensitive: nick-case cannot bypass the ignore" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    var relay_peer: s2s_link.S2sLink = undefined;
    try addTestRelayHomes(&server, &relay_peer, 99, &.{ "Remote", "Friend" });
    defer relay_peer.deinit();

    const target_id = try addTestLocalClient(&server, "Target", "targetacct");
    const target = server.connFor(target_id).?;

    // The live SILENCE list is keyed by the recipient's own (canonical) nick.
    _ = try server.silence.add(target.session.displayName(), "Remote!*@host");

    // A relayed PRIVMSG addressed with a DIFFERENT-CASE target ("target") still
    // resolves to this recipient — nick routing is case-insensitive — so the
    // SILENCE gate MUST also match case-insensitively. If it keys the owner
    // case-sensitively, the silenced sender is delivered anyway (bypass).
    server.deliverRelay(.{
        .verb = .privmsg,
        .target = "target",
        .source_nick = "Remote",
        .source_prefix = "Remote!r@host",
        .account = "remoteacct",
        .tags = "",
        .text = "should be silenced",
        .origin_node = 99,
        .hlc = 1,
    });
    try std.testing.expectEqual(@as(usize, 0), target.send_len);

    // A non-matching sender (different host) is still delivered — no over-match,
    // and the case-folded owner lookup does not swallow legitimate traffic.
    server.deliverRelay(.{
        .verb = .privmsg,
        .target = "target",
        .source_nick = "Friend",
        .source_prefix = "Friend!f@elsewhere",
        .account = "friendacct",
        .tags = "",
        .text = "delivered",
        .origin_node = 99,
        .hlc = 2,
    });
    try expectContains(target.send_buf[0..target.send_len], ":Friend!f@elsewhere PRIVMSG target :delivered\r\n");
}

test "session-sync: sender same-account same-nick sibling gets the DM sent-copy without the cap" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .crypto_io = std.testing.io }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const sender_id = try addTestLocalClient(&server, "Kazu", "kazuacct");
    const sibling_id = try addTestLocalClient(&server, "KazuTmp", "kazuacct");
    const recipient_id = try addTestLocalClient(&server, "Nova", "novaacct");
    const sender = server.connFor(sender_id).?;
    const sibling = server.connFor(sibling_id).?;
    const recipient = server.connFor(recipient_id).?;
    // Bind the second transport to the exact reusable credential. Account+nick
    // alone is deliberately insufficient; exact-token siblings receive the
    // sent copy without requiring the optional account session-sync cap.
    try sibling.session.setNick("Kazu");
    const sender_token = server.sessions.resumeHandleForClient("kazuacct", monitorIdFromClient(sender_id)).?.token;
    try std.testing.expect(server.sessions.joinTokenGroup("kazuacct", monitorIdFromClient(sibling_id), sender_token));

    try server.messageOne(sender_id, sender, "PRIVMSG", "Nova", "hello there", null);

    try expectContains(recipient.send_buf[0..recipient.send_len], "PRIVMSG Nova :hello there\r\n");
    try expectContains(sibling.send_buf[0..sibling.send_len], "PRIVMSG Nova :hello there\r\n");
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(sibling.send_buf[0..sibling.send_len], "PRIVMSG Nova :hello there"));
    // No echo-message cap: the sending session itself gets nothing back.
    try std.testing.expectEqual(@as(usize, 0), sender.send_len);
}

test "session-sync exact-once matrix: local same-account distinct tokens dedupe mandatory and optional copies" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const account = "matrix-acct";
    const token_a: sessions_mod.Token = @splat(0xA1);
    const token_b: sessions_mod.Token = @splat(0xB2);
    const token_c: sessions_mod.Token = @splat(0xC3);
    const token_decoy: sessions_mod.Token = @splat(0xD4);
    const sender_id = try addTestLocalClient(&server, "Sender", account);
    const sender_exact_id = try addTestLocalClient(&server, "SenderAttach", account);
    const recipient_id = try addTestLocalClient(&server, "Recipient", account);
    const account_sync_id = try addTestLocalClient(&server, "Archive", account);
    const same_nick_decoy_id = try addTestLocalClient(&server, "SenderDecoy", account);
    const sender = server.connFor(sender_id).?;
    const sender_exact = server.connFor(sender_exact_id).?;
    const recipient = server.connFor(recipient_id).?;
    const account_sync = server.connFor(account_sync_id).?;
    const same_nick_decoy = server.connFor(same_nick_decoy_id).?;

    // A and B are independent exact-token identities under one account. A's
    // second attachment is mandatory fan-out; C explicitly opts into the account
    // DM view. The cap-enabled same-nick decoy remains a separate authority and
    // must not consume Sender's event through account/nick affinity.
    try std.testing.expect(server.sessions.adoptTokenGroup(account, monitorIdFromClient(sender_id), token_a, false));
    try std.testing.expect(server.sessions.joinTokenGroup(account, monitorIdFromClient(sender_exact_id), token_a));
    try std.testing.expect(server.sessions.adoptTokenGroup(account, monitorIdFromClient(recipient_id), token_b, false));
    try std.testing.expect(server.sessions.adoptTokenGroup(account, monitorIdFromClient(account_sync_id), token_c, false));
    try std.testing.expect(server.sessions.adoptTokenGroup(account, monitorIdFromClient(same_nick_decoy_id), token_decoy, false));
    try sender_exact.session.setNick("Sender");
    try same_nick_decoy.session.setNick("Sender");
    account_sync.session.addCap(.onyx_session_sync);
    same_nick_decoy.session.addCap(.onyx_session_sync);

    try server.messageOne(sender_id, sender, "PRIVMSG", "Recipient", "matrix-local", null);

    try std.testing.expectEqual(@as(usize, 0), countOccurrences(sender.send_buf[0..sender.send_len], "PRIVMSG Recipient :matrix-local"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(sender_exact.send_buf[0..sender_exact.send_len], "PRIVMSG Recipient :matrix-local"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(recipient.send_buf[0..recipient.send_len], "PRIVMSG Recipient :matrix-local"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(account_sync.send_buf[0..account_sync.send_len], "PRIVMSG Recipient :matrix-local"));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(same_nick_decoy.send_buf[0..same_nick_decoy.send_len], "PRIVMSG Recipient :matrix-local"));
}

test "threaded server: auxiliary direct events fan out exact-token attachments once with stable identity" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var identity = try node_identity.fromSeed(@as([32]u8, @splat(0xA9)), "auxiliary-matrix.test");
    defer identity.deinit();
    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = identity.shortId(),
        .server_name = "auxiliary-matrix.test",
        .node_identity = &identity,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const account = "auxiliary-matrix";
    const sender_token: sessions_mod.Token = @splat(0x11);
    const recipient_token: sessions_mod.Token = @splat(0x22);
    const decoy_token: sessions_mod.Token = @splat(0x33);
    const sender_id = try addTestLocalClient(&server, "Sender", account);
    const sender_exact_id = try addTestLocalClient(&server, "SenderAttach", account);
    const recipient_id = try addTestLocalClient(&server, "Recipient", account);
    const recipient_exact_id = try addTestLocalClient(&server, "RecipientAttach", account);
    const decoy_id = try addTestLocalClient(&server, "SenderDecoy", account);
    const sender = server.connFor(sender_id).?;
    const sender_exact = server.connFor(sender_exact_id).?;
    const recipient = server.connFor(recipient_id).?;
    const recipient_exact = server.connFor(recipient_exact_id).?;
    const decoy = server.connFor(decoy_id).?;

    try std.testing.expect(server.sessions.adoptTokenGroup(
        account,
        monitorIdFromClient(sender_id),
        sender_token,
        true,
    ));
    try std.testing.expect(server.sessions.joinTokenGroup(
        account,
        monitorIdFromClient(sender_exact_id),
        sender_token,
    ));
    try std.testing.expect(server.sessions.adoptTokenGroup(
        account,
        monitorIdFromClient(recipient_id),
        recipient_token,
        true,
    ));
    try std.testing.expect(server.sessions.joinTokenGroup(
        account,
        monitorIdFromClient(recipient_exact_id),
        recipient_token,
    ));
    try std.testing.expect(server.sessions.adoptTokenGroup(
        account,
        monitorIdFromClient(decoy_id),
        decoy_token,
        true,
    ));

    // Render both physical attachments with their shared session nick. The
    // independently-issued decoy deliberately renders Sender too: account and
    // nick affinity must never widen exact-token authority.
    server.world.unregisterNick(worldIdFromClient(sender_exact_id));
    try sender_exact.session.setNick("Sender");
    server.world.unregisterNick(worldIdFromClient(recipient_exact_id));
    try recipient_exact.session.setNick("Recipient");
    server.world.unregisterNick(worldIdFromClient(decoy_id));
    try decoy.session.setNick("Sender");

    // Every attachment participates in the WHISPER channel independently.
    // Exact-token fan-out, rather than a single World nick owner, must still
    // deliver one physical copy to each eligible sibling.
    inline for (.{ sender_id, sender_exact_id, recipient_id, recipient_exact_id, decoy_id }) |member_id|
        try server.world.restoreMember("#auxiliary", worldIdFromClient(member_id), world_model.MemberModes.empty());

    sender.session.addCap(.message_tags);
    sender.session.addCap(.server_time);
    sender.session.addCap(.echo_message);
    sender_exact.session.addCap(.message_tags);
    sender_exact.session.addCap(.server_time);
    recipient.session.addCap(.message_tags);
    recipient.session.addCap(.server_time);
    // Deliberately no message-tags/typing cap on this exact recipient: DATA and
    // WHISPER still arrive, while a semantically empty TAGMSG must be filtered.
    recipient_exact.session.addCap(.server_time);
    decoy.session.addCap(.message_tags);
    decoy.session.addCap(.server_time);

    const outputs = [_]*ConnState{ sender, sender_exact, recipient, recipient_exact, decoy };
    const Reset = struct {
        fn run(conns: []const *ConnState) void {
            for (conns) |conn| {
                conn.send_len = 0;
                conn.send_offset = 0;
            }
        }
    };

    const typed_cases = [_]struct { wire: []const u8, marker: []const u8 }{
        .{ .wire = "DATA Recipient TAG :matrix-data", .marker = "DATA Recipient TAG :matrix-data" },
        .{ .wire = "REQUEST Recipient RPC :matrix-request", .marker = "REQUEST Recipient RPC :matrix-request" },
        .{ .wire = "REPLY Recipient RPC :matrix-reply", .marker = "REPLY Recipient RPC :matrix-reply" },
    };
    for (typed_cases) |case| {
        Reset.run(&outputs);
        var parsed = try irc_line.parseLine(case.wire);
        try server.handleData(sender_id, sender, &parsed);
        try std.testing.expectEqual(@as(usize, 0), countOccurrences(sender.send_buf[0..sender.send_len], case.marker));
        try std.testing.expectEqual(@as(usize, 1), countOccurrences(sender_exact.send_buf[0..sender_exact.send_len], case.marker));
        try std.testing.expectEqual(@as(usize, 1), countOccurrences(recipient.send_buf[0..recipient.send_len], case.marker));
        try std.testing.expectEqual(@as(usize, 1), countOccurrences(recipient_exact.send_buf[0..recipient_exact.send_len], case.marker));
        try std.testing.expectEqual(@as(usize, 0), countOccurrences(decoy.send_buf[0..decoy.send_len], case.marker));
        try std.testing.expectEqualStrings(
            extractMsgid(sender_exact.send_buf[0..sender_exact.send_len]) orelse return error.TestUnexpectedResult,
            extractMsgid(recipient.send_buf[0..recipient.send_len]) orelse return error.TestUnexpectedResult,
        );
    }

    Reset.run(&outputs);
    var tagmsg = try irc_line.parseLine("@+draft/typing=active TAGMSG Recipient");
    try server.handleTagmsg(sender_id, sender, &tagmsg);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(sender.send_buf[0..sender.send_len], "TAGMSG Recipient"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(sender_exact.send_buf[0..sender_exact.send_len], "TAGMSG Recipient"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(recipient.send_buf[0..recipient.send_len], "TAGMSG Recipient"));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(recipient_exact.send_buf[0..recipient_exact.send_len], "TAGMSG Recipient"));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(decoy.send_buf[0..decoy.send_len], "TAGMSG Recipient"));
    const tagmsg_id = extractMsgid(sender.send_buf[0..sender.send_len]) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(tagmsg_id, extractMsgid(sender_exact.send_buf[0..sender_exact.send_len]) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(tagmsg_id, extractMsgid(recipient.send_buf[0..recipient.send_len]) orelse return error.TestUnexpectedResult);

    Reset.run(&outputs);
    var whisper_line = try irc_line.parseLine("WHISPER #auxiliary Recipient :matrix-whisper");
    try server.handleWhisper(sender_id, sender, &whisper_line);
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(sender.send_buf[0..sender.send_len], "WHISPER #auxiliary Recipient :matrix-whisper"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(sender_exact.send_buf[0..sender_exact.send_len], "WHISPER #auxiliary Recipient :matrix-whisper"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(recipient.send_buf[0..recipient.send_len], "WHISPER #auxiliary Recipient :matrix-whisper"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(recipient_exact.send_buf[0..recipient_exact.send_len], "WHISPER #auxiliary Recipient :matrix-whisper"));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(decoy.send_buf[0..decoy.send_len], "WHISPER #auxiliary Recipient :matrix-whisper"));
    try std.testing.expectEqualStrings(
        extractMsgid(sender_exact.send_buf[0..sender_exact.send_len]) orelse return error.TestUnexpectedResult,
        extractMsgid(recipient.send_buf[0..recipient.send_len]) orelse return error.TestUnexpectedResult,
    );
}

test "threaded server: inactive OCG1 never authorizes remote DATA reserved tags" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const now = server.grantNowU64();
    _ = server.oper_grants.upsert(.{
        .account = "trusted-oper",
        .privilege_bits = oper_mod.OperPrivileges.initMany(&.{.oper_override}).toBits(),
        .class = "oper",
        .title = "",
        .issuer_node = "authority.test",
        .incarnation = 1,
        .issued_ms = now,
        .expiry_ms = now + 60_000,
    });
    const member = world_model.MemberModes.empty();
    const channel_op = world_model.MemberModes.fromModes(&.{.op});

    try std.testing.expect(server.remoteDataTagAuthorized("TAG", false, null, ""));
    try std.testing.expect(!server.remoteDataTagAuthorized("SYS.notice", false, null, ""));
    // A mutable relay account claim cannot become `policy_account`; passing an
    // ungranted forged value demonstrates that mere text has no authority.
    try std.testing.expect(!server.remoteDataTagAuthorized("ADM.alert", true, member, "forged-oper-text"));
    try std.testing.expect(!server.remoteDataTagAuthorized("SYS.notice", false, null, "trusted-oper"));
    try std.testing.expect(!server.remoteDataTagAuthorized("ADM.alert", true, member, "trusted-oper"));
    try std.testing.expect(server.remoteDataTagAuthorized("OWN.state", true, channel_op, ""));
    try std.testing.expect(!server.remoteDataTagAuthorized("HST.state", true, member, ""));
    try std.testing.expect(!server.remoteDataTagAuthorized("OWN.state", false, null, ""));
    // The stored OCG1 record also cannot bypass channel rank for a direct target.
    try std.testing.expect(!server.remoteDataTagAuthorized("HST.state", false, null, "trusted-oper"));
}

test "session-sync exact-once matrix: authenticated inbound relay dedupes exact tokens and account mirror" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const account = "relay-matrix-acct";
    const token_a: sessions_mod.Token = @splat(0xA5);
    const token_b: sessions_mod.Token = @splat(0xB6);
    const token_c: sessions_mod.Token = @splat(0xC7);
    const token_decoy: sessions_mod.Token = @splat(0xD8);
    const sender_owner_id = try addTestLocalClient(&server, "Remote", account);
    const sender_exact_id = try addTestLocalClient(&server, "RemoteAttach", account);
    const recipient_id = try addTestLocalClient(&server, "Target", account);
    const account_sync_id = try addTestLocalClient(&server, "RelayArchive", account);
    const same_nick_decoy_id = try addTestLocalClient(&server, "RemoteDecoy", account);
    const sender_owner = server.connFor(sender_owner_id).?;
    const sender_exact = server.connFor(sender_exact_id).?;
    const recipient = server.connFor(recipient_id).?;
    const account_sync = server.connFor(account_sync_id).?;
    const same_nick_decoy = server.connFor(same_nick_decoy_id).?;

    try std.testing.expect(server.sessions.adoptTokenGroup(account, monitorIdFromClient(sender_owner_id), token_a, true));
    try std.testing.expect(server.sessions.joinTokenGroup(account, monitorIdFromClient(sender_exact_id), token_a));
    try std.testing.expect(server.sessions.adoptTokenGroup(account, monitorIdFromClient(recipient_id), token_b, false));
    try std.testing.expect(server.sessions.adoptTokenGroup(account, monitorIdFromClient(account_sync_id), token_c, false));
    try std.testing.expect(server.sessions.adoptTokenGroup(account, monitorIdFromClient(same_nick_decoy_id), token_decoy, false));
    try sender_exact.session.setNick("Remote");
    try same_nick_decoy.session.setNick("Remote");
    account_sync.session.addCap(.onyx_session_sync);
    same_nick_decoy.session.addCap(.onyx_session_sync);

    // The signed Store offer binds the remote author to exact token A. Therefore
    // both local A attachments receive the sent-copy, B receives as the target,
    // and C receives one optional account mirror. The same-nick D decoy is outside
    // both exact sets and remains excluded even though it negotiated session-sync.
    var remote = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0x5A)));
    defer remote.deinit();
    try applyTestRemoteSessionReplica(&server, &remote, token_a, account, "Remote", 1);
    var pk_buf: [message_relay.pubkey_len]u8 = undefined;
    var sig_buf: [message_relay.sig_len]u8 = undefined;
    var msg = try buildSignedRelay(&remote, "Target", "Remote!r@mesh.test", "matrix-relay", 7, &pk_buf, &sig_buf);
    msg.account = account;
    server.deliverRelay(msg);

    try std.testing.expectEqual(@as(usize, 1), countOccurrences(sender_owner.send_buf[0..sender_owner.send_len], "PRIVMSG Target :matrix-relay"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(sender_exact.send_buf[0..sender_exact.send_len], "PRIVMSG Target :matrix-relay"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(recipient.send_buf[0..recipient.send_len], "PRIVMSG Target :matrix-relay"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(account_sync.send_buf[0..account_sync.send_len], "PRIVMSG Target :matrix-relay"));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(same_nick_decoy.send_buf[0..same_nick_decoy.send_len], "PRIVMSG Target :matrix-relay"));
}

test "relay DM rejects an unproven same-account sender-copy claim" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const recipient_id = try addTestLocalClient(&server, "Nova", "novaacct");
    const sender_local_id = try addTestLocalClient(&server, "Kazu", "kazuacct");
    const bystander_id = try addTestLocalClient(&server, "Mira", "miraacct");
    const recipient = server.connFor(recipient_id).?;
    const sender_local = server.connFor(sender_local_id).?;
    const bystander = server.connFor(bystander_id).?;

    // Make the spoof maximally tempting: this node really did offer Kazu's
    // portable token to peer 42. The unsigned frame below can claim that origin
    // id, but it still cannot consume the route because it has no self-contained
    // origin signature binding the claim to peer 42's key.
    const handle = server.sessions.resumeHandleForClient("kazuacct", monitorIdFromClient(sender_local_id)) orelse return error.TestUnexpectedResult;
    _ = server.sessions.markPortableResumeIssued("kazuacct", monitorIdFromClient(sender_local_id));
    server.recordSessionReplicaRoute(handle.token, 42);

    // A keyed peer may assert the same account text, but without an authenticated
    // portable-session token route it has not proven that this is another Kazu
    // attachment. Fail closed: do not render the claim to either the recipient
    // or the alleged sender sibling. The secured integration test below proves
    // the reciprocal positive case after a real MTOKEN attach.
    server.deliverRelay(.{
        .verb = .privmsg,
        .target = "Nova",
        .source_nick = "Kazu",
        .source_prefix = "Kazu!k@peer",
        .account = "kazuacct",
        .tags = "",
        .text = "from my other device",
        .origin_node = 42,
        .hlc = 1,
    });
    try std.testing.expectEqual(@as(usize, 0), recipient.send_len);
    try std.testing.expectEqual(@as(usize, 0), sender_local.send_len);
    try std.testing.expectEqual(@as(usize, 0), bystander.send_len);

    // A later attempt remains rejected regardless of recipient policy.
    _ = try server.silence.add("Nova", "Kazu!*@peer");
    const recipient_len_before = recipient.send_len;
    const sender_len_before = sender_local.send_len;
    server.deliverRelay(.{
        .verb = .privmsg,
        .target = "Nova",
        .source_nick = "Kazu",
        .source_prefix = "Kazu!k@peer",
        .account = "kazuacct",
        .tags = "",
        .text = "silenced",
        .origin_node = 42,
        .hlc = 2,
    });
    try std.testing.expectEqual(recipient_len_before, recipient.send_len);
    try std.testing.expectEqual(sender_len_before, sender_local.send_len);
}

test "relay direct messages honor local +C and +g callerid policy" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        var relay_peer: s2s_link.S2sLink = undefined;
        try addTestRelayHomes(&server, &relay_peer, 99, &.{"Remote"});
        defer relay_peer.deinit();

        const target_id = try addTestLocalClient(&server, "Target", "targetacct");
        const target = server.connFor(target_id).?;

        _ = target.session.setUmode(.no_ctcp, true);
        server.deliverRelay(.{
            .verb = .privmsg,
            .target = "Target",
            .source_nick = "Remote",
            .source_prefix = "Remote!r@host",
            .account = "remoteacct",
            .tags = "",
            .text = "\x01VERSION\x01",
            .origin_node = 99,
            .hlc = 11,
        });
        try std.testing.expectEqual(@as(usize, 0), target.send_len);

        _ = target.session.setUmode(.no_ctcp, false);
        _ = target.session.setUmode(.callerid, true);
        server.deliverRelay(.{
            .verb = .privmsg,
            .target = "Target",
            .source_nick = "Remote",
            .source_prefix = "Remote!r@host",
            .account = "remoteacct",
            .tags = "",
            .text = "blocked by callerid",
            .origin_node = 99,
            .hlc = 12,
        });
        try std.testing.expectEqual(@as(usize, 0), target.send_len);

        try server.accepts.add("Target", "Remote");
        server.deliverRelay(.{
            .verb = .privmsg,
            .target = "Target",
            .source_nick = "Remote",
            .source_prefix = "Remote!r@host",
            .account = "remoteacct",
            .tags = "",
            .text = "accepted",
            .origin_node = 99,
            .hlc = 13,
        });
        try expectContains(target.send_buf[0..target.send_len], ":Remote!r@host PRIVMSG Target :accepted\r\n");
    } else return error.SkipZigTest;
}

