test "E2EEPOLICYBODY TAGMSG stays tag-only in required rooms" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    var relay_peer: s2s_link.S2sLink = undefined;
    try addTestRelayHomes(&server, &relay_peer, 4242, &.{"Remote"});
    defer relay_peer.deinit();

    const chan = ircx_prop_store.Entity{ .kind = .channel, .id = "#e2eetag" };
    _ = try server.props.setProp(chan, e2ee_policy.policy_prop, "required", .{ .id = "op", .access = .owner });
    const alice_id = try addTestLocalClient(&server, "alice", null);
    const bob_id = try addTestLocalClient(&server, "bob", null);
    const alice = server.connFor(alice_id).?;
    const bob = server.connFor(bob_id).?;
    alice.session.addCap(.message_tags);
    alice.session.addCap(.typing);
    bob.session.addCap(.message_tags);
    bob.session.addCap(.typing);
    _ = try server.world.join("#e2eetag", worldIdFromClient(alice_id));
    _ = try server.world.join("#e2eetag", worldIdFromClient(bob_id));
    _ = try server.world.setChannelFlag("#e2eetag", .no_external, false);

    // Existing required-room policy never demanded a text envelope for TAGMSG.
    // Typing/react remain tag-only; requiring ONYXROOM1 would drop them.
    const history_before = server.history.totalStoredCount();
    resetTestSendQ(alice);
    resetTestSendQ(bob);
    var tagmsg = try irc_line.parseLine("@+typing=active TAGMSG #e2eetag");
    try server.handleTagmsg(alice_id, alice, &tagmsg);
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], "FAIL") == null);
    try expectContains(bob.send_buf[0..bob.send_len], "TAGMSG #e2eetag");
    try expectContains(bob.send_buf[0..bob.send_len], "+typing=active");
    try std.testing.expect(server.history.totalStoredCount() >= history_before);

    resetTestSendQ(alice);
    resetTestSendQ(bob);
    server.deliverRelay(.{
        .verb = .tagmsg,
        .target = "#e2eetag",
        .source_nick = "Remote",
        .source_prefix = "Remote!r@peer",
        .account = "",
        .tags = "+typing=active",
        .text = "",
        .origin_node = 4242,
        .hlc = 21,
    });
    try expectContains(alice.send_buf[0..alice.send_len], "TAGMSG #e2eetag");
    try expectContains(bob.send_buf[0..bob.send_len], "TAGMSG #e2eetag");
}

test "AI policy: public PROP visibility reaches non-op channel members" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();

        const op_id = try addTestLocalClient(&server, "Op", null);
        const op_conn = server.connFor(op_id).?;
        op_conn.ircx = true;
        const member_id = try addTestLocalClient(&server, "Member", null);
        const member_conn = server.connFor(member_id).?;
        member_conn.ircx = true;

        _ = try server.world.join("#aivis", worldIdFromClient(op_id));
        _ = try server.world.setMemberMode("#aivis", worldIdFromClient(op_id), .op, true);
        _ = try server.world.join("#aivis", worldIdFromClient(member_id));

        var set_line = try irc_line.parseLine("PROP #aivis no-ai :1");
        try server.handleProp(op_id, op_conn, &set_line);
        try std.testing.expectEqual(LinuxServer.AiPolicy.no_ai, server.channelAiPolicy("#aivis"));

        member_conn.send_len = 0;
        var get_line = try irc_line.parseLine("PROP #aivis GET no-ai,local-only,server-ai-ok");
        try server.handleProp(member_id, member_conn, &get_line);
        const get_written = member_conn.send_buf[0..member_conn.send_len];
        try expectContains(get_written, " 818 Member #aivis no-ai :1");
        try expectContains(get_written, " 819 Member #aivis ");
        try std.testing.expect(std.mem.indexOf(u8, get_written, "local-only") == null);
        try std.testing.expect(std.mem.indexOf(u8, get_written, "server-ai-ok") == null);

        member_conn.send_len = 0;
        var list_line = try irc_line.parseLine("PROP #aivis");
        try server.handleProp(member_id, member_conn, &list_line);
        const list_written = member_conn.send_buf[0..member_conn.send_len];
        try expectContains(list_written, " 818 Member #aivis no-ai :1");
        try expectContains(list_written, " 819 Member #aivis ");
    } else return error.SkipZigTest;
}

test "ephemeral room: replay drops messages older than the TTL, keeps fresh ones" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();

        const member_id = try addTestLocalClient(&server, "Reader", null);
        const member = server.connFor(member_id).?;

        const now: u64 = @intCast(platform.realtimeMillis());
        const two_hours: u64 = 2 * 60 * 60 * 1000;
        const one_min: u64 = 60 * 1000;
        _ = server.history.append("#eph", .{ .msgid = "old1", .sender = "a!u@h", .text = "ancient", .timestamp = now - two_hours }) catch {};
        _ = server.history.append("#eph", .{ .msgid = "new1", .sender = "b!u@h", .text = "recent", .timestamp = now - one_min }) catch {};

        // Without the prop, both replay.
        var out_buf: [4096]u8 = undefined;
        var hbuf: [8]lotus.Message = undefined;
        const all = server.history.latest("#eph", hbuf.len, &hbuf) catch &.{};
        const before_prop = try server.renderHistoryReplay(member, &out_buf, "t", "#eph", all, null);
        try expectContains(before_prop, "ancient");
        try expectContains(before_prop, "recent");

        // With a 1-hour TTL, the 2-hour-old message is filtered; the 1-min one stays.
        const chan = ircx_prop_store.Entity{ .kind = .channel, .id = "#eph" };
        _ = try server.props.setProp(chan, "EPHEMERAL", "3600", .{ .id = "op", .access = .owner });
        var out_buf2: [4096]u8 = undefined;
        const after_prop = try server.renderHistoryReplay(member, &out_buf2, "t", "#eph", all, null);
        try std.testing.expect(std.mem.indexOf(u8, after_prop, "ancient") == null);
        try expectContains(after_prop, "recent");
    } else return error.SkipZigTest;
}

test "topics: registry PROP gates, auto-adds, records a mesh clock, and is CRDT-portable" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();

        const chan = ircx_prop_store.Entity{ .kind = .channel, .id = "#topics" };
        // channelBuiltinSet validates then defers to the generic (persisted,
        // mesh-propagated) store, exactly like PINS/EPHEMERAL.
        try std.testing.expectEqual(server.channelBuiltinSet(chan, topic_tag.registry_key, "general,random", false), .not_handled);
        try std.testing.expectEqual(server.channelBuiltinSet(chan, topic_tag.registry_key, "bad\rlabel", false), .bad_value);
        try std.testing.expectEqual(server.channelBuiltinSet(chan, topic_tag.registry_key, "a,,b", false), .bad_value);

        // Auto-add: the first sighting registers the label AND authors a channel
        // -prop CRDT clock (the fact that mesh-propagates + survives peer relink).
        server.registerChannelTopic("#topics", "general");
        try std.testing.expectEqualStrings("general", (try server.props.getProp(chan, topic_tag.registry_key)).value);
        try std.testing.expect(server.channelPropClock("#topics", topic_tag.registry_key) != null);

        // Idempotent re-add; a distinct label appends.
        server.registerChannelTopic("#topics", "general");
        server.registerChannelTopic("#topics", "random");
        try std.testing.expectEqualStrings("general,random", (try server.props.getProp(chan, topic_tag.registry_key)).value);

        // CRDT-portable: a remote node's `onyx_server.topics` fact (unsigned legacy
        // path) applies locally through the ordinary channel-prop receive path.
        try std.testing.expect(server.applyRemoteChannelProp(.{
            .channel = "#remote",
            .key = topic_tag.registry_key,
            .value = "release plan,general",
            .owner = "peer",
            .hlc = @as(u64, 100),
            .present = true,
            .origin_node = @as(u64, 0),
            .origin_pubkey = @as([]const u8, ""),
            .origin_sig = @as([]const u8, ""),
        }));
        const rentity = ircx_prop_store.Entity{ .kind = .channel, .id = "#remote" };
        try std.testing.expectEqualStrings("release plan,general", (try server.props.getProp(rentity, topic_tag.registry_key)).value);
    } else return error.SkipZigTest;
}

test "topics: CHATHISTORY topic filter replays only the matching conversation" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();

        const member_id = try addTestLocalClient(&server, "Reader", null);
        const member = server.connFor(member_id).?;

        const now: u64 = @intCast(platform.realtimeMillis());
        _ = server.history.append("#tf", .{ .msgid = "g1", .sender = "a!u@h", .text = "in-general-one", .timestamp = now, .client_tags = "+onyx/topic=general" }) catch {};
        _ = server.history.append("#tf", .{ .msgid = "r1", .sender = "b!u@h", .text = "in-random-one", .timestamp = now, .client_tags = "+onyx/topic=random" }) catch {};
        _ = server.history.append("#tf", .{ .msgid = "n1", .sender = "c!u@h", .text = "no-topic-here", .timestamp = now }) catch {};
        _ = server.history.append("#tf", .{ .msgid = "g2", .sender = "d!u@h", .text = "in-general-two", .timestamp = now, .client_tags = "+onyx/topic=general" }) catch {};

        var hbuf: [16]lotus.Message = undefined;
        const all = server.history.latest("#tf", hbuf.len, &hbuf) catch &.{};

        // No filter → every message (backward-compatible funnel).
        var out_buf: [8192]u8 = undefined;
        const unfiltered = try server.renderHistoryReplay(member, &out_buf, "t", "#tf", all, null);
        try expectContains(unfiltered, "in-general-one");
        try expectContains(unfiltered, "in-random-one");
        try expectContains(unfiltered, "no-topic-here");
        try expectContains(unfiltered, "in-general-two");

        // Filter "general" → only the two general messages; nothing else.
        var out_buf2: [8192]u8 = undefined;
        const filtered = try server.renderHistoryReplay(member, &out_buf2, "t", "#tf", all, "general");
        try expectContains(filtered, "in-general-one");
        try expectContains(filtered, "in-general-two");
        try std.testing.expect(std.mem.indexOf(u8, filtered, "in-random-one") == null);
        try std.testing.expect(std.mem.indexOf(u8, filtered, "no-topic-here") == null);

        // A topic nobody used → empty replay (no message lines).
        var out_buf3: [8192]u8 = undefined;
        const none = try server.renderHistoryReplay(member, &out_buf3, "t", "#tf", all, "nonexistent");
        try std.testing.expect(std.mem.indexOf(u8, none, "PRIVMSG") == null);
    } else return error.SkipZigTest;
}

test "topics: CHATHISTORY topic filter is extracted from the command's message tag" {
    // Locks the extraction contract renderHistoryReplay depends on: the daemon's
    // inline parser exposes an @-stripped, +-preserving `tags_raw`, and
    // `handleChathistory` reads the filter from it via `topic_tag.labelFromTags`.
    const tagged = try irc_line.parseLine("@+onyx/topic=general CHATHISTORY LATEST #t * 50");
    try std.testing.expectEqualStrings(
        "CHATHISTORY LATEST #t * 50",
        LinuxServer.chathistoryCommandLine("@+onyx/topic=general CHATHISTORY LATEST #t * 50\r\n").?,
    );
    var tbuf: [topic_tag.max_label_len]u8 = undefined;
    const filter = if (tagged.tags_raw) |tr| topic_tag.labelFromTags(tr, &tbuf) else null;
    try std.testing.expectEqualStrings("general", filter.?);

    // Escaped value decodes (\s -> space) just as on the message path.
    const escaped = try irc_line.parseLine("@+onyx/topic=release\\splan CHATHISTORY LATEST #t * 50");
    const escaped_filter = if (escaped.tags_raw) |tr| topic_tag.labelFromTags(tr, &tbuf) else null;
    try std.testing.expectEqualStrings("release plan", escaped_filter.?);

    // No tag → null → the funnel replays everything (backward-compatible).
    const plain = try irc_line.parseLine("CHATHISTORY LATEST #t * 50");
    try std.testing.expect((if (plain.tags_raw) |tr| topic_tag.labelFromTags(tr, &tbuf) else null) == null);
    try std.testing.expectEqualStrings(
        "CHATHISTORY LATEST #t * 50",
        LinuxServer.chathistoryCommandLine("CHATHISTORY LATEST #t * 50\r\n").?,
    );
    try std.testing.expect(LinuxServer.chathistoryCommandLine("@label=only") == null);
}

test "threaded server: +onyx/topic tag rides fanout + echo; untagged is unchanged" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.ConnectionRefused => return error.SkipZigTest,
        else => return err,
    };
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);

    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };

    // Both negotiate message-tags; the sender also negotiates echo-message.
    try writeAllFd(fd_a, "CAP REQ :message-tags echo-message\r\nNICK A\r\nUSER alice 0 * :Alice\r\nCAP END\r\n");
    try writeAllFd(fd_b, "CAP REQ :message-tags\r\nNICK B\r\nUSER bob 0 * :Bob\r\nCAP END\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try recvUntil(&b, " 001 B ", 200);

    try writeAllFd(fd_a, "JOIN #t\r\n");
    try recvUntil(&a, " 366 A #t ", 200);
    try writeAllFd(fd_b, "JOIN #t\r\n");
    try recvUntil(&b, " 366 B #t ", 200);

    // A tagged channel message: B (a member with message-tags) sees the topic
    // tag, and A's echo carries it too.
    a.reset();
    b.reset();
    try writeAllFd(fd_a, "@+onyx/topic=general PRIVMSG #t :hi\r\n");
    try recvUntil(&b, "PRIVMSG #t :hi\r\n", 200);
    try expectContains(b.written(), "+onyx/topic=general");
    try recvUntil(&a, "PRIVMSG #t :hi\r\n", 200); // echo-message
    try expectContains(a.written(), "+onyx/topic=general");

    // An untagged message is unchanged: no topic tag appears anywhere.
    a.reset();
    b.reset();
    try writeAllFd(fd_a, "PRIVMSG #t :plain\r\n");
    try recvUntil(&b, "PRIVMSG #t :plain\r\n", 200);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "+onyx/topic") == null);
    try recvUntil(&a, "PRIVMSG #t :plain\r\n", 200);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "+onyx/topic") == null);
}

test "threaded server: onyx/topics receives topic tags without generic message-tags" {
