// ---------------------------------------------------------------------------
// CHANNEL_PROP CRDT multi-hop origin signing (daemon paths)
// ---------------------------------------------------------------------------

/// A borrowed-slice CHANNEL_PROP fact shaped like `S2sPeer.ChannelPropDelta`,
/// for feeding the daemon's `applyRemoteChannelProp` (which reads slices and
/// dupes into the clock). Tests own the backing buffers.
const TestPropFact = struct {
    channel: []const u8,
    key: []const u8,
    value: []const u8,
    owner: []const u8,
    hlc: u64,
    present: bool,
    origin_node: u64,
    origin_pubkey: []const u8 = "",
    origin_sig: []const u8 = "",
};

/// Build a CHANNEL_PROP fact signed by `kp` at its self-certified origin id.
fn buildSignedProp(
    kp: *const sign_mod.KeyPair,
    channel: []const u8,
    key: []const u8,
    value: []const u8,
    owner: []const u8,
    hlc: u64,
    present: bool,
    pk_buf: *[channel_prop_event.pubkey_len]u8,
    sig_buf: *[channel_prop_event.sig_len]u8,
) !TestPropFact {
    var ev = channel_prop_event.ChannelPropEvent{
        .present = present,
        .origin_node = channel_prop_event.originShortId(kp.public_key),
        .hlc = hlc,
        .channel = channel,
        .key = key,
        .value = value,
        .owner = owner,
    };
    const transcript = try channel_prop_event.originTranscript(std.testing.allocator, ev);
    defer std.testing.allocator.free(transcript);
    try channel_prop_event.signInPlace(&ev, kp, transcript, pk_buf, sig_buf);
    return .{
        .channel = channel,
        .key = key,
        .value = value,
        .owner = owner,
        .hlc = hlc,
        .present = present,
        .origin_node = ev.origin_node,
        .origin_pubkey = ev.origin_pubkey,
        .origin_sig = ev.origin_sig,
    };
}

test "channel prop: a locally-authored fact is signed and verifies against its origin" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x71)), "local");
        defer ident.deinit();
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .node_id = ident.shortId(), .node_identity = &ident }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();

        var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
        var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
        const ps = server.signLocalChannelProp(true, "#room", "TOPICLOCK", "1", "alice", 100, &pk_buf, &sig_buf);
        try std.testing.expectEqual(ident.shortId(), ps.node);
        try std.testing.expectEqual(@as(usize, channel_prop_event.pubkey_len), ps.pubkey.len);

        // Store + read back; the stored signature self-certifies the local origin.
        try std.testing.expect(server.recordChannelPropClock("#room", "TOPICLOCK", "alice", 100, true, ps.node, ps.pubkey, ps.sig));
        const clock = server.channelPropClock("#room", "TOPICLOCK").?;
        const ev = channel_prop_event.ChannelPropEvent{
            .present = true,
            .origin_node = clock.origin_node,
            .hlc = clock.hlc,
            .channel = "#room",
            .key = "TOPICLOCK",
            .value = "1",
            .owner = "alice",
            .origin_pubkey = clock.origin_pubkey,
            .origin_sig = clock.origin_sig,
        };
        try std.testing.expectEqual(channel_prop_event.VerifyOutcome.verified, try channel_prop_event.verifyOrigin(std.testing.allocator, ev));
    } else return error.SkipZigTest;
}

test "channel prop: an inbound signed fact verifies, applies, and is stored for re-broadcast" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const founder_id = try addTestLocalClient(&server, "Founder", null);
        _ = try server.world.join("#mesh", worldIdFromClient(founder_id));

        var kp = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0x82)));
        defer kp.deinit();
        var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
        var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
        const fact = try buildSignedProp(&kp, "#mesh", "SUBJECT", "hello", "remoteacct", 500, true, &pk_buf, &sig_buf);

        try std.testing.expect(server.applyRemoteChannelProp(fact));
        try std.testing.expectEqual(@as(u64, 0), server.rejected_relay_signatures);

        // The ORIGINAL author's origin + signature were stored verbatim (NOT this
        // node's), so a re-broadcast/burst re-emits the original author's signature.
        const clock = server.channelPropClock("#mesh", "SUBJECT").?;
        try std.testing.expectEqual(fact.origin_node, clock.origin_node);
        try std.testing.expectEqualSlices(u8, fact.origin_pubkey, clock.origin_pubkey);
        try std.testing.expectEqualSlices(u8, fact.origin_sig, clock.origin_sig);

        // burstPropOrigin re-derives the emit attribution and, because the live tuple
        // still matches the signed one, re-emits the ORIGINAL author's (pubkey, sig).
        const origin = server.burstPropOrigin(clock, true, "hello", "remoteacct");
        try std.testing.expectEqual(fact.origin_node, origin.node);
        try std.testing.expectEqualSlices(u8, fact.origin_pubkey, origin.pubkey);
        try std.testing.expectEqualSlices(u8, fact.origin_sig, origin.sig);
    } else return error.SkipZigTest;
}

test "channel prop: a forged inbound fact is rejected, counted, and not applied" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const founder_id = try addTestLocalClient(&server, "Founder", null);
        _ = try server.world.join("#mesh", worldIdFromClient(founder_id));

        var kp = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0x83)));
        defer kp.deinit();
        var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
        var sig_buf: [channel_prop_event.sig_len]u8 = undefined;

        // (1) Tampered value after signing: structure valid, signature is not.
        var tampered = try buildSignedProp(&kp, "#mesh", "K", "original", "alice", 600, true, &pk_buf, &sig_buf);
        tampered.value = "tampered value the origin never authored";
        try std.testing.expect(!server.applyRemoteChannelProp(tampered));
        try std.testing.expectEqual(@as(u64, 1), server.rejected_relay_signatures);
        try std.testing.expect(server.channelPropClock("#mesh", "K") == null);

        // (2) A pubkey whose originShortId does not self-certify the claimed origin.
        var bad_origin = try buildSignedProp(&kp, "#mesh", "K2", "v", "alice", 601, true, &pk_buf, &sig_buf);
        bad_origin.origin_node = channel_prop_event.originShortId(kp.public_key) ^ 0x1;
        try std.testing.expect(!server.applyRemoteChannelProp(bad_origin));
        try std.testing.expectEqual(@as(u64, 2), server.rejected_relay_signatures);
        try std.testing.expect(server.channelPropClock("#mesh", "K2") == null);

        // (3) Tampered owner/channel/key each break verification too.
        inline for (.{ "owner", "channel", "key" }) |field| {
            var t = try buildSignedProp(&kp, "#mesh", "K3", "v", "alice", 602, true, &pk_buf, &sig_buf);
            @field(t, field) = "HIJACKED";
            try std.testing.expect(!server.applyRemoteChannelProp(t));
            try std.testing.expect(server.channelPropClock("#mesh", "K3") == null);
        }
        try std.testing.expectEqual(@as(u64, 5), server.rejected_relay_signatures);
    } else return error.SkipZigTest;
}

test "channel prop: a re-broadcast preserves the ORIGINAL author's signature (multi-hop)" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const founder_id = try addTestLocalClient(&server, "Founder", null);
        _ = try server.world.join("#mesh", worldIdFromClient(founder_id));

        // A THIRD node authored the fact; THIS node is a relay with its own identity.
        var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x84)), "relay");
        defer ident.deinit();
        server.config.node_id = ident.shortId();
        server.config.node_identity = &ident;

        var author = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0x90)));
        defer author.deinit();
        var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
        var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
        const fact = try buildSignedProp(&author, "#mesh", "OWNERKEY", "v", "carol", 700, true, &pk_buf, &sig_buf);
        // Sanity: the author is NOT this relay node.
        try std.testing.expect(fact.origin_node != ident.shortId());

        try std.testing.expect(server.applyRemoteChannelProp(fact));
        const clock = server.channelPropClock("#mesh", "OWNERKEY").?;

        // The re-broadcast attribution is the AUTHOR's, not the relay's: a receiver
        // self-certifies `originShortId(pubkey) == origin_node` (the author), which is
        // the whole point of multi-hop CRDT signing.
        const origin = server.burstPropOrigin(clock, true, "v", "carol");
        try std.testing.expectEqual(fact.origin_node, origin.node);
        try std.testing.expectEqualSlices(u8, fact.origin_pubkey, origin.pubkey);
        const reemit = channel_prop_event.ChannelPropEvent{
            .present = true,
            .origin_node = origin.node,
            .hlc = clock.hlc,
            .channel = "#mesh",
            .key = "OWNERKEY",
            .value = "v",
            .owner = "carol",
            .origin_pubkey = origin.pubkey,
            .origin_sig = origin.sig,
        };
        try std.testing.expectEqual(channel_prop_event.VerifyOutcome.verified, try channel_prop_event.verifyOrigin(std.testing.allocator, reemit));
    } else return error.SkipZigTest;
}

test "channel prop: a legacy unsigned inbound fact still applies (backward compat)" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const founder_id = try addTestLocalClient(&server, "Founder", null);
        _ = try server.world.join("#mesh", worldIdFromClient(founder_id));

        // No origin_pubkey/origin_sig: the legacy unsigned path, applied unchanged.
        const fact = TestPropFact{
            .channel = "#mesh",
            .key = "LEGACY",
            .value = "unsigned still flows",
            .owner = "dave",
            .hlc = 800,
            .present = true,
            .origin_node = 99,
        };
        try std.testing.expect(server.applyRemoteChannelProp(fact));
        try std.testing.expectEqual(@as(u64, 0), server.rejected_relay_signatures);
        const clock = server.channelPropClock("#mesh", "LEGACY").?;
        try std.testing.expectEqual(@as(usize, 0), clock.origin_pubkey.len);
        try std.testing.expectEqual(@as(usize, 0), clock.origin_sig.len);
        // An unsigned clock re-emits an unsigned origin (legacy LWW at the receiver).
        const origin = server.burstPropOrigin(clock, true, "unsigned still flows", "dave");
        try std.testing.expectEqual(@as(u64, 99), origin.node);
        try std.testing.expectEqual(@as(usize, 0), origin.pubkey.len);
    } else return error.SkipZigTest;
}

// ---------------------------------------------------------------------------
// ENTITY_PROP CRDT multi-hop origin signing (user/member daemon paths)
// ---------------------------------------------------------------------------

/// A borrowed-slice ENTITY_PROP fact shaped like `S2sPeer.EntityPropDelta`, for
/// feeding the daemon's `applyRemoteEntityProp`. Tests own the backing buffers.
const TestEntityPropFact = struct {
    kind: entity_prop_event.EntityKind,
    entity: []const u8,
    key: []const u8,
    value: []const u8,
    owner: []const u8,
    hlc: u64,
    present: bool,
    origin_node: u64,
    origin_pubkey: []const u8 = "",
    origin_sig: []const u8 = "",
};

/// Build an ENTITY_PROP fact signed by `kp` at its self-certified origin id.
fn buildSignedEntityProp(
    kp: *const sign_mod.KeyPair,
    kind: entity_prop_event.EntityKind,
    entity: []const u8,
    key: []const u8,
    value: []const u8,
    owner: []const u8,
    hlc: u64,
    present: bool,
    pk_buf: *[entity_prop_event.pubkey_len]u8,
    sig_buf: *[entity_prop_event.sig_len]u8,
) !TestEntityPropFact {
    var ev = entity_prop_event.EntityPropEvent{
        .present = present,
        .kind = kind,
        .origin_node = entity_prop_event.originShortId(kp.public_key),
        .hlc = hlc,
        .entity = entity,
        .key = key,
        .value = value,
        .owner = owner,
    };
    const transcript = try entity_prop_event.originTranscript(std.testing.allocator, ev);
    defer std.testing.allocator.free(transcript);
    try entity_prop_event.signInPlace(&ev, kp, transcript, pk_buf, sig_buf);
    return .{
        .kind = kind,
        .entity = entity,
        .key = key,
        .value = value,
        .owner = owner,
        .hlc = hlc,
        .present = present,
        .origin_node = ev.origin_node,
        .origin_pubkey = ev.origin_pubkey,
        .origin_sig = ev.origin_sig,
    };
}

test "E5E1 remote identity namespace quarantine precedes signatures clocks stores and authority" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const baseline_hlc = server.nextMeshHlc();
    const baseline_clock = server.mesh_clock;
    const baseline_signatures = server.rejected_relay_signatures;
    const baseline_authority = server.rejected_relay_home_mismatch;
    const quarantined = [_]TestEntityPropFact{
        .{ .kind = .user, .entity = "alice", .key = "identity.key.primary", .value = "bad", .owner = "alice", .hlc = baseline_hlc + 1, .present = true, .origin_node = 7, .origin_pubkey = "forged", .origin_sig = "forged" },
        .{ .kind = .user, .entity = "alice", .key = "IDENTITY.KEY.", .value = "", .owner = "alice", .hlc = baseline_hlc + 2, .present = false, .origin_node = 7 },
        .{ .kind = .user, .entity = "alice", .key = "Identity.Residence.0000000000000007", .value = "bad", .owner = "alice", .hlc = baseline_hlc + 3, .present = true, .origin_node = 7 },
        .{ .kind = .user, .entity = "alice", .key = "identity.residence.abc", .value = "", .owner = "alice", .hlc = baseline_hlc + 4, .present = false, .origin_node = 7 },
    };
    for (quarantined) |fact| {
        try std.testing.expect(!server.applyRemoteEntityProp(fact));
        try std.testing.expect(server.entityPropClock(.user, fact.entity, fact.key) == null);
        try std.testing.expectError(
            error.PropMissing,
            server.props.getPropRaw(.{ .kind = .user, .id = fact.entity }, fact.key),
        );
        try std.testing.expectEqual(baseline_clock.last_physical, server.mesh_clock.last_physical);
        try std.testing.expectEqual(baseline_clock.last_stamp, server.mesh_clock.last_stamp);
        try std.testing.expectEqual(baseline_signatures, server.rejected_relay_signatures);
        try std.testing.expectEqual(baseline_authority, server.rejected_relay_home_mismatch);
    }
    try std.testing.expectEqual(@as(u64, quarantined.len), server.remote_identity_props_quarantined);

    const near = TestEntityPropFact{ .kind = .user, .entity = "alice", .key = "identity.keyX.keep", .value = "ordinary", .owner = "alice", .hlc = baseline_hlc + 10, .present = true, .origin_node = 7 };
    try std.testing.expect(server.applyRemoteEntityProp(near));
    try std.testing.expectEqualStrings("ordinary", (try server.props.getPropRaw(.{ .kind = .user, .id = "alice" }, near.key)).value);

    const member = TestEntityPropFact{ .kind = .member, .entity = "#room:alice", .key = "identity.key.primary", .value = "member", .owner = "alice", .hlc = baseline_hlc + 11, .present = true, .origin_node = 7 };
    try std.testing.expect(server.applyRemoteEntityProp(member));
    try std.testing.expectEqualStrings("member", (try server.props.getPropRaw(.{ .kind = .member, .id = member.entity }, member.key)).value);
}

test "E5E1 local identity add residence and delete never export to plaintext or secured links" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;

    var plain_local: s2s_link.S2sLink = undefined;
    try plain_local.init(.{ .allocator = allocator, .local_node_id = 0xA1, .remote_node_id = 0xA2, .local_epoch_ms = 1000, .server_name = "e5e1-local.test", .config = .{ .require_signed_frames = false } });
    defer plain_local.deinit();
    var plain_remote: s2s_link.S2sLink = undefined;
    try plain_remote.init(.{ .allocator = allocator, .local_node_id = 0xA2, .remote_node_id = 0xA1, .local_epoch_ms = 2000, .server_name = "e5e1-remote.test", .config = .{ .require_signed_frames = false } });
    defer plain_remote.deinit();
    try plain_local.start(10);
    var round: usize = 0;
    while (round < 32) : (round += 1) {
        const local_wire = try allocator.dupe(u8, plain_local.outbound());
        defer allocator.free(local_wire);
        const remote_wire = try allocator.dupe(u8, plain_remote.outbound());
        defer allocator.free(remote_wire);
        plain_local.clearOutbound();
        plain_remote.clearOutbound();
        if (local_wire.len == 0 and remote_wire.len == 0) break;
        if (local_wire.len != 0) try plain_remote.feed(local_wire, round + 11, 0xE5E1 +% round);
        if (remote_wire.len != 0) try plain_local.feed(remote_wire, round + 11, 0x1E5E +% round);
    }
    try std.testing.expect(plain_local.established());

    var secured = try SessionReplayTestPair.initWithSeeds(allocator, 0xB1, 0xB2);
    defer secured.deinit();
    secured.a.clearOutbound();
    secured.b.clearOutbound();

    var server = Server.init(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const plain_id = try server.rx().clients.alloc(ConnState.init(-1));
    const plain_conn = server.rx().clients.get(plain_id).?;
    plain_conn.overflow_allocator = allocator;
    plain_conn.token = try tokenFromId(plain_id);
    plain_conn.send_armed = true;
    plain_conn.sendq_cap = default_sendq_cap;
    plain_conn.s2s = &plain_local;
    const secured_id = try server.rx().clients.alloc(ConnState.init(-1));
    const secured_conn = server.rx().clients.get(secured_id).?;
    secured_conn.overflow_allocator = allocator;
    secured_conn.token = try tokenFromId(secured_id);
    secured_conn.send_armed = true;
    secured_conn.sendq_cap = default_sendq_cap;
    secured_conn.s2s_secured = &secured.a;
    defer {
        plain_conn.s2s = null;
        secured_conn.s2s_secured = null;
        _ = server.rx().clients.free(plain_id);
        _ = server.rx().clients.free(secured_id);
    }

    const entity = ircx_prop_store.Entity{ .kind = .user, .id = "alice" };
    _ = try server.props.setProp(entity, "identity.key.primary", "local-key", .{ .id = "alice", .access = .user });
    server.propagateLocalEntityPropAt(true, .user, "alice", "identity.key.primary", "local-key", "alice", 100);
    _ = try server.props.setProp(entity, "identity.residence.0000000000000001", "local-proof", .{ .id = "alice", .access = .user });
    server.propagateLocalEntityPropAt(true, .user, "alice", "identity.residence.0000000000000001", "local-proof", "alice", 101);
    try server.props.deleteProp(entity, "identity.key.primary");
    server.propagateLocalEntityPropAt(false, .user, "alice", "identity.key.primary", "", "alice", 102);

    try std.testing.expect(server.entityPropClock(.user, "alice", "identity.key.primary") != null);
    try std.testing.expect(server.entityPropClock(.user, "alice", "identity.residence.0000000000000001") != null);
    try std.testing.expectEqual(@as(usize, 0), plain_conn.send_len);
    try std.testing.expectEqual(@as(usize, 0), plain_conn.send_overflow.items.len);
    try std.testing.expectEqual(@as(usize, 0), secured_conn.send_len);
    try std.testing.expectEqual(@as(usize, 0), secured_conn.send_overflow.items.len);
    try std.testing.expectEqual(@as(usize, 0), plain_local.outbound().len);
    try std.testing.expectEqual(@as(usize, 0), secured.a.outbound().len);
}

test "remote property admission advances HLC only for accepted channel and entity facts" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const baseline = server.nextMeshHlc();
    const baseline_clock = server.mesh_clock;
    const invalid_channel_facts = [_]TestPropFact{
        .{ .channel = "#mesh", .key = "BADVALUE", .value = "line\nbreak", .owner = "remote", .hlc = baseline + 10, .present = true, .origin_node = 9 },
        .{ .channel = "#mesh", .key = "BADOWNER", .value = "safe", .owner = "bad:owner", .hlc = baseline + 11, .present = true, .origin_node = 9 },
        .{ .channel = "#mesh", .key = "OID", .value = "read-only", .owner = "remote", .hlc = baseline + 12, .present = true, .origin_node = 9 },
    };
    for (invalid_channel_facts) |fact| {
        try std.testing.expect(!server.applyRemoteChannelProp(fact));
        try std.testing.expect(server.channelPropClock(fact.channel, fact.key) == null);
        try std.testing.expectError(
            error.PropMissing,
            server.props.getPropRaw(.{ .kind = .channel, .id = fact.channel }, fact.key),
        );
        try std.testing.expectEqual(baseline_clock.last_physical, server.mesh_clock.last_physical);
        try std.testing.expectEqual(baseline_clock.last_stamp, server.mesh_clock.last_stamp);
    }

    const invalid_entity_facts = [_]TestEntityPropFact{
        .{ .kind = .user, .entity = "alice", .key = "BADVALUE", .value = "line\nbreak", .owner = "alice", .hlc = baseline + 13, .present = true, .origin_node = 9 },
        .{ .kind = .member, .entity = "#mesh:alice", .key = "BADOWNER", .value = "safe", .owner = "bad owner", .hlc = baseline + 14, .present = true, .origin_node = 9 },
    };
    for (invalid_entity_facts) |fact| {
        try std.testing.expect(!server.applyRemoteEntityProp(fact));
        try std.testing.expect(server.entityPropClock(fact.kind, fact.entity, fact.key) == null);
        try std.testing.expectError(
            error.PropMissing,
            server.props.getPropRaw(.{ .kind = fact.kind.toStoreKind(), .id = fact.entity }, fact.key),
        );
        try std.testing.expectEqual(baseline_clock.last_physical, server.mesh_clock.last_physical);
        try std.testing.expectEqual(baseline_clock.last_stamp, server.mesh_clock.last_stamp);
    }

    const channel_hlc = baseline + 100;
    const accepted_channel = TestPropFact{
        .channel = "#mesh",
        .key = "CUSTOM",
        .value = "committed",
        .owner = "remote",
        .hlc = channel_hlc,
        .present = true,
        .origin_node = 9,
    };
    try std.testing.expect(server.applyRemoteChannelProp(accepted_channel));
    try std.testing.expectEqual(channel_hlc, server.mesh_clock.last_stamp);
    try std.testing.expectEqualStrings(
        "committed",
        (try server.props.getPropRaw(.{ .kind = .channel, .id = "#mesh" }, "CUSTOM")).value,
    );
    try std.testing.expect(server.nextMeshHlc() > channel_hlc);

    const after_channel = server.mesh_clock;
    var stale_channel = accepted_channel;
    stale_channel.hlc = channel_hlc - 1;
    stale_channel.value = "stale";
    try std.testing.expect(!server.applyRemoteChannelProp(stale_channel));
    try std.testing.expectEqual(after_channel.last_physical, server.mesh_clock.last_physical);
    try std.testing.expectEqual(after_channel.last_stamp, server.mesh_clock.last_stamp);

    var signer = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0x4d)));
    defer signer.deinit();
    var pk_buf: [channel_prop_event.pubkey_len]u8 = undefined;
    var sig_buf: [channel_prop_event.sig_len]u8 = undefined;
    var forged = try buildSignedProp(
        &signer,
        "#mesh",
        "SIGNED",
        "authored",
        "remote",
        after_channel.last_stamp + 100,
        true,
        &pk_buf,
        &sig_buf,
    );
    forged.value = "tampered";
    try std.testing.expect(!server.applyRemoteChannelProp(forged));
    try std.testing.expectEqual(after_channel.last_physical, server.mesh_clock.last_physical);
    try std.testing.expectEqual(after_channel.last_stamp, server.mesh_clock.last_stamp);

    const future_physical = server.meshWallMs() + mesh_clock_mod.default_max_future_skew_ms + 60_000;
    const future_hlc = (future_physical << mesh_clock_mod.seq_bits) | 1;
    const rejected_clock = server.mesh_clock;
    var future = accepted_channel;
    future.key = "FUTURE";
    future.hlc = future_hlc;
    try std.testing.expect(!server.applyRemoteChannelProp(future));
    future.key = "EXHAUSTED";
    future.hlc = std.math.maxInt(u64);
    try std.testing.expect(!server.applyRemoteChannelProp(future));
    try std.testing.expectEqual(rejected_clock.last_physical, server.mesh_clock.last_physical);
    try std.testing.expectEqual(rejected_clock.last_stamp, server.mesh_clock.last_stamp);

    const entity_hlc = server.mesh_clock.last_stamp + 100;
    const accepted_entity = TestEntityPropFact{
        .kind = .user,
        .entity = "alice",
        .key = "STATUS",
        .value = "online",
        .owner = "alice",
        .hlc = entity_hlc,
        .present = true,
        .origin_node = 9,
    };
    try std.testing.expect(server.applyRemoteEntityProp(accepted_entity));
    try std.testing.expectEqual(entity_hlc, server.mesh_clock.last_stamp);
    try std.testing.expectEqualStrings(
        "online",
        (try server.props.getPropRaw(.{ .kind = .user, .id = "alice" }, "STATUS")).value,
    );
    try std.testing.expect(server.nextMeshHlc() > entity_hlc);
}

