test "remote channel mode state applies params and respects local MLOCK" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();

        const founder_id = try addTestLocalClient(&server, "Founder", null);
        _ = try server.world.join("#param", worldIdFromClient(founder_id));

        const delta = .{
            .channel = "#param",
            .private = true,
            .hidden = true,
            .ext_bits = @as(u32, 0),
            .key = @as(?[]const u8, "sekret"),
            .limit = @as(?u32, 42),
            .throttle_joins = @as(u16, 3),
            .throttle_secs = @as(u32, 20),
            .forward = @as(?[]const u8, "#next"),
        };
        var before: Server.ChannelModeStateSnapshot = undefined;
        var after: Server.ChannelModeStateSnapshot = undefined;
        try std.testing.expect(server.applyRemoteChannelModeState(delta, &before, &after));
        try std.testing.expect(server.world.isPrivate("#param"));
        try std.testing.expect(server.world.isHidden("#param"));
        try std.testing.expectEqualStrings("sekret", server.world.channelKey("#param").?);
        try std.testing.expectEqual(@as(?u32, 42), server.world.channelLimit("#param"));
        try std.testing.expectEqual(@as(u16, 3), server.world.throttleOf("#param").?.joins);
        try std.testing.expectEqual(@as(u32, 20), server.world.throttleOf("#param").?.secs);
        try std.testing.expectEqualStrings("#next", server.world.forwardOf("#param").?);

        const locked = .{
            .channel = "#param",
            .private = false,
            .hidden = false,
            .ext_bits = @as(u32, 0),
            .key = @as(?[]const u8, "blocked"),
            .limit = @as(?u32, 7),
            .throttle_joins = @as(u16, 0),
            .throttle_secs = @as(u32, 0),
            .forward = @as(?[]const u8, null),
        };
        try server.mlocks.put(
            server.allocator,
            try server.allocator.dupe(u8, "#param"),
            try server.allocator.dupe(u8, "+nt-k"),
        );
        try std.testing.expect(!server.applyRemoteChannelModeState(locked, &before, &after));
        try std.testing.expect(server.world.isPrivate("#param"));
        try std.testing.expectEqualStrings("sekret", server.world.channelKey("#param").?);
        try std.testing.expectEqual(@as(?u32, 42), server.world.channelLimit("#param"));
    } else return error.SkipZigTest;
}

/// Pump a plaintext S2S link pair to convergence: shuttle each side's outbound
/// bytes to the other's `feed` until both stop producing output (or the round cap
/// is hit). Used by mesh tests to establish a link and propagate membership/mode
/// frames without a live socket.
fn pumpLinkPair(a: *s2s_link.S2sLink, b: *s2s_link.S2sLink, alloc: std.mem.Allocator) !void {
    var now: u64 = 100;
    var rounds: usize = 0;
    while (rounds < 128) : (rounds += 1) {
        const a_out = a.outbound();
        const b_out = b.outbound();
        if (a_out.len == 0 and b_out.len == 0) break;
        const a_copy = try alloc.dupe(u8, a_out);
        defer alloc.free(a_copy);
        const b_copy = try alloc.dupe(u8, b_out);
        defer alloc.free(b_copy);
        a.clearOutbound();
        b.clearOutbound();
        if (a_copy.len != 0) try b.feed(a_copy, now, 7);
        if (b_copy.len != 0) try a.feed(b_copy, now, 9);
        now += 1;
    }
}

test "S2S identity transition renders PART before NICK before JOIN" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    var server = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .node_id = 2 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const observer_id = try addTestLocalClient(&server, "Observer", null);
    const observer = server.connFor(observer_id).?;
    _ = try server.world.join("#obsolete", worldIdFromClient(observer_id));
    _ = try server.world.join("#common", worldIdFromClient(observer_id));
    _ = try server.world.join("#desired", worldIdFromClient(observer_id));

    var sender: s2s_link.S2sLink = undefined;
    try sender.init(.{
        .allocator = alloc,
        .local_node_id = 1,
        .remote_node_id = 2,
        .local_epoch_ms = 1000,
        .server_name = "peer.onyx",
        .config = .{ .require_signed_frames = false },
    });
    defer sender.deinit();
    const receiver = try alloc.create(s2s_link.S2sLink);
    try receiver.init(.{
        .allocator = alloc,
        .local_node_id = 2,
        .remote_node_id = 1,
        .local_epoch_ms = 1001,
        .server_name = "self.onyx",
        .config = .{ .require_signed_frames = false },
    });
    const link_id = try server.rx().clients.alloc(ConnState.init(-1));
    const link_conn = server.rx().clients.get(link_id).?;
    link_conn.s2s = receiver;

    try sender.start(50);
    try pumpLinkPair(&sender, receiver, alloc);
    try std.testing.expect(receiver.established());

    const old_ident = s2s_peer_mod.MemberIdentity{ .username = "device", .realname = "Device B", .host = "mesh.test" };
    try sender.sendMembership("#obsolete", "DeviceB", 0, 100, true, old_ident, "");
    try sender.sendMembership("#common", "DeviceB", 0, 101, true, old_ident, "");
    const seed_bytes = try alloc.dupe(u8, sender.outbound());
    defer alloc.free(seed_bytes);
    sender.clearOutbound();
    server.driveS2s(link_conn, receiver, seed_bytes);
    try std.testing.expect(!link_conn.closing);
    observer.send_len = 0;
    observer.send_offset = 0;

    try sender.sendMembership("#obsolete", "DeviceB", 0, 200, false, old_ident, "");
    try sender.sendNickChange("DeviceB", "Nova", old_ident, 201);
    try sender.sendMembership("#desired", "Nova", 0, 202, true, old_ident, "");
    const transition_bytes = try alloc.dupe(u8, sender.outbound());
    defer alloc.free(transition_bytes);
    sender.clearOutbound();
    server.driveS2s(link_conn, receiver, transition_bytes);
    try std.testing.expect(!link_conn.closing);

    const rendered = observer.send_buf[0..observer.send_len];
    const part_at = std.mem.indexOf(u8, rendered, ":DeviceB!device@mesh.test PART #obsolete\r\n") orelse return error.TestUnexpectedResult;
    const nick_at = std.mem.indexOf(u8, rendered, ":DeviceB!device@mesh.test NICK Nova\r\n") orelse return error.TestUnexpectedResult;
    const join_at = std.mem.indexOf(u8, rendered, ":Nova!device@mesh.test JOIN :#desired\r\n") orelse return error.TestUnexpectedResult;
    try std.testing.expect(part_at < nick_at);
    try std.testing.expect(nick_at < join_at);
}

test "secured S2S v2 identity transition renders PART before NICK before JOIN" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
