    }

    const old_ident = s2s_peer_mod.MemberIdentity{ .username = "device", .realname = "Secure Device", .host = "secure.mesh" };
    try pair.a.sendMembership("#secure-old", "SecureB", 0, 300, true, old_ident, "");
