    try std.testing.expect(std.mem.indexOf(u8, out, "#secret") == null);
    std.debug.print("GAP-P0c branch=listx remote topic\n", .{});
}

/// Blocking read with a bounded poll budget (so a misbehaving server fails the
/// test instead of hanging). Accumulates into `client` and returns when `needle`
/// is present, or errors after ~3s.
fn recvUntil(client: *LiveClient, needle: []const u8, max_polls: usize) !void {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        // Use a WALL-CLOCK deadline rather than a fixed poll count: under heavy
        // parallel-test CPU contention the reactor thread can be briefly starved, so
        // a count-based budget (poll returns early on data, burning iterations)
        // produced spurious TestTimeouts. `max_polls` now sets a lower bound on the
        // budget; we wait at least that long but cap at a generous 20s so genuine
        // bugs still fail in bounded time.
        const budget_ms: i64 = @max(@as(i64, @intCast(max_polls)) * 25, 20_000);
        const deadline = platform.monotonicMillis() + budget_ms;
        while (true) {
            if (std.mem.indexOf(u8, client.written(), needle) != null) return;
            if (platform.monotonicMillis() >= deadline) return error.TestTimeout;
            var fds = [_]posix.pollfd{.{ .fd = client.fd, .events = posix.POLL.IN, .revents = 0 }};
            const ready = posix.poll(&fds, 50) catch return error.Unexpected;
            if (ready == 0) continue;
            if ((fds[0].revents & posix.POLL.IN) == 0) continue;
            if (client.len == client.buf.len) return error.OutputTooSmall;
            const n = try readFd(client.fd, client.buf[client.len..]);
            if (n == 0) return error.ConnectionReset;
            client.len += n;
        }
    } else return error.SkipZigTest;
}

fn extractMsgid(bytes: []const u8) ?[]const u8 {
    const marker = "msgid=";
    const start = (std.mem.indexOf(u8, bytes, marker) orelse return null) + marker.len;
    var end = start;
    while (end < bytes.len and bytes[end] != ';' and bytes[end] != ' ') : (end += 1) {}
    if (end == start) return null;
    return bytes[start..end];
}

fn extractTimeTag(bytes: []const u8) ?[]const u8 {
    const marker = "time=";
    const start = (std.mem.indexOf(u8, bytes, marker) orelse return null) + marker.len;
    var end = start;
    while (end < bytes.len and bytes[end] != ';' and bytes[end] != ' ') : (end += 1) {}
    if (end == start) return null;
    return bytes[start..end];
}

/// Return the complete IRC line containing `needle`.  Threaded mesh tests can
/// legitimately receive unrelated presence/maintenance lines alongside the
/// event under test, so extracting the first tag in the whole receive buffer
/// would compare metadata from different events.
fn ircLineContaining(bytes: []const u8, needle: []const u8) ?[]const u8 {
    const at = std.mem.indexOf(u8, bytes, needle) orelse return null;
    const start = if (std.mem.lastIndexOf(u8, bytes[0..at], "\r\n")) |previous|
        previous + 2
    else
        0;
    const end = if (std.mem.indexOf(u8, bytes[at..], "\r\n")) |following|
        at + following
    else
        bytes.len;
    return bytes[start..end];
}

/// Assert that one concrete 353 line carries a non-empty authoritative roster
/// entry for `nick`, exactly once, with its complete expected status prefix.
/// Matching strips only Onyx Server's advertised status prefix alphabet.
fn expectSingleNamesNick(
    bytes: []const u8,
    header: []const u8,
    nick: []const u8,
    expected_entry: []const u8,
) !void {
    const line = ircLineContaining(bytes, header) orelse return error.TestUnexpectedResult;
    const trailing_at = std.mem.indexOf(u8, line, " :") orelse return error.TestUnexpectedResult;
    const trailing = line[trailing_at + 2 ..];
    var entries = std.mem.tokenizeScalar(u8, trailing, ' ');
    var matches: usize = 0;
    while (entries.next()) |entry| {
        var nick_at: usize = 0;
        while (nick_at < entry.len and std.mem.indexOfScalar(u8, "*!.@+", entry[nick_at]) != null)
            nick_at += 1;
        if (!std.ascii.eqlIgnoreCase(entry[nick_at..], nick)) continue;
        matches += 1;
        try std.testing.expectEqualStrings(expected_entry, entry);
    }
    try std.testing.expectEqual(@as(usize, 1), matches);
}

/// Assert the complete (possibly split across several 353 replies) roster has
/// exactly one entry, with the expected status spelling, and no generated mesh
/// UID. The terminating 366 must already have been received by the caller.
fn expectExactSingleNamesRoster(bytes: []const u8, header: []const u8, expected_entry: []const u8) !void {
    var lines = std.mem.splitSequence(u8, bytes, "\r\n");
    var entries_seen: usize = 0;
    while (lines.next()) |line| {
        if (std.mem.indexOf(u8, line, header) == null) continue;
        const trailing_at = std.mem.indexOf(u8, line, " :") orelse return error.TestUnexpectedResult;
        var entries = std.mem.tokenizeScalar(u8, line[trailing_at + 2 ..], ' ');
        while (entries.next()) |entry| {
            entries_seen += 1;
            try std.testing.expectEqualStrings(expected_entry, entry);
            var nick_at: usize = 0;
            while (nick_at < entry.len and std.mem.indexOfScalar(u8, "*!.@+", entry[nick_at]) != null)
                nick_at += 1;
            try std.testing.expect(!mesh_uid_alloc.validate(entry[nick_at..]));
        }
    }
    try std.testing.expectEqual(@as(usize, 1), entries_seen);
}

fn waitMillis(ms: i64) void {
    const deadline = platform.monotonicMillis() + ms;
    while (platform.monotonicMillis() < deadline) {}
}

test "threaded server: malformed pre-auth lines never kill the reactor" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    // Attacker connection: a blank line (ParseError.EmptyLine), a NUL inside a
    // line, and a tags-only line with no command. Before the firewall, the first
    // of these escaped processLiveLine and exited the reactor loop — one line of
    // garbage from an unauthenticated peer took down the whole daemon.
    const fd_evil = connectLoopback(port) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.ConnectionRefused => return error.SkipZigTest,
        else => return err,
    };
    defer closeFd(fd_evil);
    try writeAllFd(fd_evil, "\r\n");
    try writeAllFd(fd_evil, "PING a\x00b\r\n");
    try writeAllFd(fd_evil, "@tag-only-no-command \r\n");

    // The reactor must still be alive: a fresh client registers normally.
    const fd_ok = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_ok);
    var ok = LiveClient{ .fd = fd_ok };
    try writeAllFd(fd_ok, "NICK survivor\r\nUSER s 0 * :Survivor\r\n");
    try recvUntil(&ok, " 001 survivor ", 400);
}

test "threaded server: real end-to-end registration, JOIN, PRIVMSG (T1)" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    // Reactor on its own thread; the test thread is a real loopback client.
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    // Shutdown that can't hang: clear the flag, then a throwaway connection wakes
    // the reactor (accept completion) so it observes the flag, then join.
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.ConnectionRefused => return error.SkipZigTest,
        else => return err,
    };
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);

    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };

    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try writeAllFd(fd_b, "CAP REQ :draft/metadata-2\r\nNICK B\r\nUSER bob 0 * :Bob\r\nCAP END\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try recvUntil(&b, " 001 B ", 200);

    a.reset();
    try writeAllFd(fd_a, "JOIN #x\r\n");
    try recvUntil(&a, " 366 A #x ", 200);
    try writeAllFd(fd_b, "JOIN #x\r\n");

    b.reset();
    try writeAllFd(fd_a, "PRIVMSG #x :hi\r\n");
    // Real username (alice) now flows through (not the old "user" placeholder).
    try recvUntil(&b, ":A!alice@localhost PRIVMSG #x :hi\r\n", 200);
}

test "threaded server: CERTLIST and CERTDEL use authenticated account bindings" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-cert.wal");
    defer store.deinit();
    var binds = certfp_bind_mod.CertfpBindStore.init(std.testing.allocator);
    defer binds.deinit();
    var services = services_mod.Services.init(&store, null);
    services.attachCertfpBinds(&binds);

    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .account_services = &services }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd);
    var client = LiveClient{ .fd = fd };

    try writeAllFd(fd, "CAP REQ :standard-replies\r\nNICK A\r\nUSER alice 0 * :Alice\r\nCAP END\r\n");
    try recvUntil(&client, " 001 A ", 200);
    try writeAllFd(fd, "REGISTER alice * correcthorse\r\n");
    try recvUntil(&client, "REGISTER SUCCESS alice", 200);

    const own_fp = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    const other_fp = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
    try services.bindCertfp("alice", own_fp);
    try services.bindCertfp("bob", other_fp);

    client.reset();
    try writeAllFd(fd, "CERTLIST\r\n");
    try recvUntil(&client, own_fp, 200);

    client.reset();
    try writeAllFd(fd, "CERTDEL bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\r\n");
    try recvUntil(&client, "FAIL CERTDEL CERT_NOT_OWNED", 200);

    client.reset();
    try writeAllFd(fd, "CERTDEL aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\r\n");
    try recvUntil(&client, "removed from alice", 200);

    client.reset();
    try writeAllFd(fd, "CERTLIST\r\n");
    try recvUntil(&client, "CERTLIST: no certificate fingerprints bound", 200);
}

