test "threaded server: login defers autojoin and restores only after exact SESSION RESUME token" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-session-resume.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);

    var cfg = Config{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
        .crypto_io = std.testing.io,
        .session_resume_composite_issuance = true,
    };
    cfg.chanlimit = 96;
    var server = Server.init(std.testing.allocator, cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    var fd_a_open = true;
    defer if (fd_a_open) closeFd(fd_a);
    var a = LiveClient{ .fd = fd_a };

    try writeAllFd(fd_a, "NICK trev\r\nUSER trev 0 * :Trev\r\n");
    try recvUntil(&a, " 001 trev ", 200);
    try writeAllFd(fd_a, "REGISTER trev * correcthorse\r\n");
    try recvUntil(&a, "REGISTER SUCCESS trev", 200);
    a.reset();
    try writeAllFd(fd_a, "JOIN #root,#ops,#dev\r\n");
    try recvUntil(&a, " 366 trev #root ", 200);
    try recvUntil(&a, " 366 trev #ops ", 200);
    try recvUntil(&a, " 366 trev #dev ", 200);
    a.reset();
    var join_line: [64]u8 = undefined;
    var join_reply: [64]u8 = undefined;
    for (0..67) |i| {
        const line = try std.fmt.bufPrint(&join_line, "JOIN #r{d:0>2}\r\n", .{i});
        try writeAllFd(fd_a, line);
        const reply = try std.fmt.bufPrint(&join_reply, " 366 trev #r{d:0>2} ", .{i});
        try recvUntil(&a, reply, 200);
        a.reset();
    }

    a.reset();
    try writeAllFd(fd_a, "SESSION TOKEN\r\n");
    try recvUntil(&a, "SESSION TOKEN ", 200);
    const token_marker = "SESSION TOKEN ";
    const token_start = (std.mem.indexOf(u8, a.written(), token_marker) orelse return error.TestUnexpectedResult) + token_marker.len;
    const token_tail = a.written()[token_start..];
    const token_len = std.mem.indexOfScalar(u8, token_tail, '\r') orelse return error.TestUnexpectedResult;
    var token_buf: [session_resume_credential.local_text_len]u8 = undefined;
    @memcpy(token_buf[0..token_len], token_tail[0..token_len]);
    const resume_token = token_buf[0..token_len];

    closeFd(fd_a);
    fd_a_open = false;
    testSleepMs(50);

    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var b = LiveClient{ .fd = fd_b };

    try writeAllFd(fd_b, "CAP REQ :no-implicit-names\r\nNICK TempResume\r\nUSER webchat 0 * :Webchat\r\nCAP END\r\n");
    try recvUntil(&b, " 001 TempResume ", 200);
    b.reset();
    try writeAllFd(fd_b, "IDENTIFY trev correcthorse\r\n");
    try recvUntil(&b, "You are now identified as trev", 200);
    // Same-account authentication alone must not consume an arbitrary device
    // ghost. The exact credential is the ownership proof.
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "NICK :trev") == null);
    var resume_line: [160]u8 = undefined;
    try writeAllFd(fd_b, try std.fmt.bufPrint(&resume_line, "SESSION RESUME {s}\r\n", .{resume_token}));
    try recvUntil(&b, "SESSION RESUME: exact session restored", 200);
    try recvUntil(&b, "NICK :trev", 200);
    try recvUntil(&b, "JOIN #root", 200);
    try recvUntil(&b, "JOIN #ops", 200);
    try recvUntil(&b, "JOIN #dev", 200);
    try recvUntil(&b, "JOIN #r66", 200);
    try writeAllFd(fd_b, "PING :resume-no-names-barrier\r\n");
    try recvUntil(&b, "PONG onyx.local :resume-no-names-barrier", 200);
    testSleepMs(10);
    try b.readAvailable();
    // Restoring an already-known session still honors no-implicit-names: the
    // client explicitly opted out and may issue NAMES itself. The PONG barrier
    // proves these absence checks inspect the complete queued resume bootstrap.
    try std.testing.expect(std.mem.indexOf(u8, b.written(), " 353 trev = #root ") == null);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), " 366 trev #root ") == null);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), ":TempResume!webchat@localhost JOIN") == null);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "Guest") == null);

    b.reset();
    try writeAllFd(fd_b, "WHOIS trev\r\n");
    try recvUntil(&b, " 318 trev trev ", 200);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "TempResume") == null);
}

