test "SESSION DROP prefers the current nick-owning sibling among three local token attachments" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const source_id = try addTestLocalClient(&server, "Tri", "three-way");
    const earlier_id = try addTestLocalClient(&server, "Earlier", "three-way");
    const owner_id = try addTestLocalClient(&server, "Owner", "three-way");
    const source_cid = monitorIdFromClient(source_id);
    const earlier_cid = monitorIdFromClient(earlier_id);
    const owner_cid = monitorIdFromClient(owner_id);
    const token = server.sessions.resumeHandleForClient("three-way", source_cid).?.token;
    try std.testing.expect(server.sessions.joinTokenGroup("three-way", earlier_cid, token));
    try std.testing.expect(server.sessions.joinTokenGroup("three-way", owner_cid, token));

    const earlier = server.connFor(earlier_id).?;
    const owner = server.connFor(owner_id).?;
    server.world.unregisterNick(worldIdFromClient(earlier_id));
    server.world.unregisterNick(worldIdFromClient(owner_id));
    try earlier.session.setNick("Tri");
    try owner.session.setNick("Tri");
    // Model two prior handoffs: the later sibling, not the first eligible row,
    // is now authoritative for the rendered nick.
    server.world.unregisterNick(worldIdFromClient(source_id));
    try server.world.registerNick("Tri", worldIdFromClient(owner_id));
    try server.world.restoreMember("#three-way", worldIdFromClient(source_id), world_model.MemberModes.fromModes(&.{.op}));

    const rows = try server.sessions.copySessionsAlloc(std.testing.allocator, "three-way");
    defer std.testing.allocator.free(rows);
    const source = for (rows) |row| {
        if (row.client == source_cid) break row;
    } else return error.TestUnexpectedResult;
    try std.testing.expectEqual(LinuxServer.ListedSessionRevoke.removed, server.revokeAttachedSessionOnLocalOwner("three-way", source));
    try std.testing.expectEqual(@as(?world_model.ClientId, worldIdFromClient(owner_id)), server.world.findNick("Tri"));
    try std.testing.expect(server.world.memberModes("#three-way", worldIdFromClient(owner_id)).?.isOperator());
    try std.testing.expect(server.sessions.containsClient("three-way", earlier_cid));
    try std.testing.expect(server.sessions.containsClient("three-way", owner_cid));
}

test "threaded server: EXTERNAL auto-resume latch excludes certificates and PLAIN" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .sasl_checker = test_oper_checker,
        .sasl_external = test_external_lookup,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const plain_id = try server.rx().clients.alloc(ConnState.init(-1));
    const plain = server.connFor(plain_id).?;
    plain.token = try tokenFromId(plain_id);
    server.injectSessionState(plain);
    plain.session.tls_certfp = "presented-but-not-external";
    try server.processLiveLine(plain_id, plain, "CAP REQ :sasl");
    try server.processLiveLine(plain_id, plain, "AUTHENTICATE PLAIN");
    var raw: [32]u8 = undefined;
    const credentials = "\x00admin\x00onyx";
    const encoded = std.base64.standard.Encoder.encode(&raw, credentials);
    var auth_line_buf: [64]u8 = undefined;
    const auth_line = try std.fmt.bufPrint(&auth_line_buf, "AUTHENTICATE {s}", .{encoded});
    try server.processLiveLine(plain_id, plain, auth_line);
    try std.testing.expectEqualStrings("admin", plain.session.account().?);
    try std.testing.expect(!plain.sasl_external_authenticated);

    const external_id = try server.rx().clients.alloc(ConnState.init(-1));
    const external = server.connFor(external_id).?;
    external.token = try tokenFromId(external_id);
    server.injectSessionState(external);
    external.session.tls_certfp = "verified-certfp";
    try std.testing.expect(!external.sasl_external_authenticated);
    try server.processLiveLine(external_id, external, "CAP REQ :sasl");
    try server.processLiveLine(external_id, external, "AUTHENTICATE EXTERNAL");
    try std.testing.expect(!external.sasl_external_authenticated);
    try server.processLiveLine(external_id, external, "AUTHENTICATE YWRtaW4=");
    try std.testing.expectEqualStrings("admin", external.session.account().?);
    try std.testing.expect(external.sasl_external_authenticated);

    // A later SASL exchange must replace, not inherit, the mechanism proof.
    // Clearing happens as soon as the non-EXTERNAL exchange starts, so even a
    // failed or abandoned re-auth cannot retain tokenless resume authority.
    try server.processLiveLine(external_id, external, "AUTHENTICATE PLAIN");
    try std.testing.expect(!external.sasl_external_authenticated);
}

test "threaded server: EXTERNAL exact account nick auto-attaches one local token and picks canonical among many" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const owner_id = try addTestLocalClient(&server, "kain", "kain");
    const owner = server.connFor(owner_id).?;
    try server.world.restoreMember(
        "#root",
        worldIdFromClient(owner_id),
        world_model.MemberModes.fromModes(&.{.founder}),
    );
    const claimant_id = try addTestLocalClient(&server, "bootstrap", "kain");
    const claimant = server.connFor(claimant_id).?;
    try claimant.session.setNick("kain");
    try reconcileTestOper(
        &claimant.session,
        oper_mod.OperPrivileges.initMany(&.{.oper_override}),
        "root",
        "Network Operator",
    );
    claimant.sasl_external_authenticated = true;
    try std.testing.expect(server.removeTrackedSession("kain", monitorIdFromClient(claimant_id)));
    const owner_token = server.sessions.resumeHandleForClient("kain", monitorIdFromClient(owner_id)).?.token;
    // Model the reported edge directly: another server-side convergence path
    // has already seated this physical row before EXTERNAL resolves the exact
    // token. Resume must still send the claimant a fresh authoritative roster,
    // without manufacturing any JOIN for either attachment.
    try server.world.restoreMember(
        "#root",
        worldIdFromClient(claimant_id),
        world_model.MemberModes.fromModes(&.{.founder}),
    );
    try std.testing.expectEqual(
        LinuxServer.ExternalResumeOutcome.resumed,
        try server.autoResumeExternalSession(
            claimant_id,
            claimant,
            server.externalResumeCandidate(monitorIdFromClient(claimant_id), "kain", "kain"),
        ),
    );
    try std.testing.expect(server.sessions.clientHasToken("kain", monitorIdFromClient(owner_id), owner_token));
    try std.testing.expect(server.sessions.clientHasToken("kain", monitorIdFromClient(claimant_id), owner_token));
    try std.testing.expect(server.connFor(owner_id) != null);
    try std.testing.expect(server.world.isMember("#root", worldIdFromClient(claimant_id)));
    try expectContains(claimant.send_buf[0..claimant.send_len], " 353 kain = #root ");
    try expectContains(claimant.send_buf[0..claimant.send_len], " 366 kain #root ");
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(
        claimant.send_buf[0..claimant.send_len],
        " 353 kain = #root ",
    ));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(
        claimant.send_buf[0..claimant.send_len],
        " 366 kain #root ",
    ));
    try expectSingleNamesNick(
        claimant.send_buf[0..claimant.send_len],
        " 353 kain = #root ",
        "kain",
        "!kain",
    );
    // The physical row already existed: neither claimant nor owner gets a
    // duplicate logical JOIN, and neither side gets +Y churn.
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(
        claimant.send_buf[0..claimant.send_len],
        " JOIN #root",
    ));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(
        owner.send_buf[0..owner.send_len],
        " JOIN #root",
    ));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(
        owner.send_buf[0..owner.send_len],
        " MODE #root +Y kain",
    ));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(
        claimant.send_buf[0..claimant.send_len],
        " MODE #root +Y kain",
    ));

    // A second distinct live token (for example minted on another mesh peer
    // before replicas converged) must not disconnect WeeChat: pick the newest
    // live local attachment as the canonical logical session.
    const other_id = try addTestLocalClient(&server, "other-bootstrap", "kain");
    const other = server.connFor(other_id).?;
    try other.session.setNick("kain");
    const other_token = server.sessions.resumeHandleForClient("kain", monitorIdFromClient(other_id)).?.token;
    try std.testing.expect(!std.crypto.timing_safe.eql(sessions_mod.Token, other_token, owner_token));
    const fresh_id = try addTestLocalClient(&server, "fresh-bootstrap", "kain");
    const fresh = server.connFor(fresh_id).?;
    try fresh.session.setNick("kain");
    fresh.sasl_external_authenticated = true;
    try std.testing.expect(server.removeTrackedSession("kain", monitorIdFromClient(fresh_id)));
    try std.testing.expectEqual(
        LinuxServer.ExternalResumeOutcome.resumed,
        try server.autoResumeExternalSession(
            fresh_id,
            fresh,
            server.externalResumeCandidate(monitorIdFromClient(fresh_id), "kain", "kain"),
        ),
    );
    try std.testing.expect(server.sessions.clientHasToken("kain", monitorIdFromClient(fresh_id), other_token));
    try expectContains(fresh.send_buf[0..fresh.send_len], "certificate-authenticated session restored");
}

