    const token: sessions_mod.Token = @splat(0x91);
    const low: sessions_mod.ClientId = 41;
    const high: sessions_mod.ClientId = 42;
    _ = try server.sessions.attach("kain", high, token, 100);
    _ = try server.sessions.attach("kain", low, token, 100);
    const kain_snapshot = try (migration_relay.Snapshot{
        .nick = "kain",
        .umodes = "+i",
        .channels = &.{},
        .channel_modes = &.{},
        .realname = "Kain",
        .host = "host",
