    try std.testing.expect(server.sessions.markDetachedWithSnapshot("kain", high, kain_snapshot));
    try std.testing.expect(server.sessions.markDetachedWithSnapshot("kain", low, other_snapshot));

    const claimant_id = try addTestLocalClient(&server, "claimant", null);
    switch (server.externalResumeCandidate(
        monitorIdFromClient(claimant_id),
        "kain",
        "kain",
