        .local => |found| try std.testing.expect(std.crypto.timing_safe.eql(sessions_mod.Token, found, token)),
        else => return error.TestUnexpectedResult,
    }
    try std.testing.expect(server.externalResumeCandidate(
        monitorIdFromClient(claimant_id),
        "kain",
        "other",
    ) == .none);
}

