    try server.host_requests.submit("admin", "approved.example", server.nowMs());
    try server.host_requests.approve("admin", server.nowMs());

    const claimant_id = try server.rx().clients.alloc(ConnState.init(-1));
    owner = server.connFor(owner_id).?;
    const claimant = server.connFor(claimant_id).?;
    claimant.token = try tokenFromId(claimant_id);
    server.injectSessionState(claimant);
    claimant.session.tls_certfp = "verified-certfp";
    // This direct allocation is a socketless SendQ inspection fixture too.
    if (comptime builtin.os.tag == .openbsd) claimant.test_sendq_capture = true;
    try server.processLiveLine(claimant_id, claimant, "CAP REQ :sasl");
    try server.processLiveLine(claimant_id, claimant, "AUTHENTICATE EXTERNAL");
    try server.processLiveLine(claimant_id, claimant, "AUTHENTICATE YWRtaW4=");
    try server.processLiveLine(claimant_id, claimant, "CAP END");
    try server.processLiveLine(claimant_id, claimant, "NICK admin");
    owner.send_len = 0;
    claimant.send_len = 0;
    try server.processLiveLine(claimant_id, claimant, "USER admin 0 * :Admin Resume");

    try std.testing.expect(claimant.session.registered());
    try std.testing.expect(server.sessions.clientHasToken(
        "admin",
        monitorIdFromClient(claimant_id),
        owner_token,
    ));
    try std.testing.expect(server.world.isMember("#root", worldIdFromClient(claimant_id)));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(
        owner.send_buf[0..owner.send_len],
        " MODE #root +Y admin",
    ));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(
        claimant.send_buf[0..claimant.send_len],
        " MODE #root +Y admin",
    ));
    try std.testing.expectEqualStrings("approved.example", owner.session.host());
    try std.testing.expectEqualStrings("approved.example", claimant.session.host());
    const published = server.session_replica_store.bestLiveIdentity(
        owner_token,
        @intCast(@min(server.meshWallMs(), @as(u64, std.math.maxInt(i64)))),
    ) orelse return error.TestUnexpectedResult;
    var snapshot = try migration_relay.Snapshot.decode(std.testing.allocator, published.snapshot);
    defer snapshot.deinit(std.testing.allocator);
    try std.testing.expectEqualStrings("approved.example", snapshot.host);
}

