    bob.reset();
    try writeAllFd(fd_bob, "JOIN #c\r\n");
    try recvUntil(&bob, " 366 Bob #c ", 200);
    bob.reset();
    try writeAllFd(fd_bob, "MODE #c +v Bob\r\n");
    try recvUntil(&bob, "MODE #c +v Bob", 200);
}

