test "threaded server: CHANNEL SET TOPICLOCK DESC URL PRIVATE persist and take effect" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-channel-set.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("admin", "correcthorse", &scratch);

    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .sasl_checker = test_oper_checker,
        .oper_registry = oper_mod.OperRegistry.init(&test_oper_bindings) catch unreachable,
        .account_services = &services,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_admin = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_admin);
    var admin = LiveClient{ .fd = fd_admin };
    try saslAdminPrelude(fd_admin);
    try writeAllFd(fd_admin, "NICK Founder\r\nUSER founder 0 * :Founder\r\n");
    try recvUntil(&admin, " 381 Founder ", 200);

    admin.reset();
    try writeAllFd(fd_admin, "CHANNEL REGISTER #c\r\n");
    try recvUntil(&admin, "Channel #c registered to admin", 200);

    // Founder joins first so they hold channel ops; a later joiner is a plain
    // member (otherwise the first joiner of the empty channel would be op and
    // TOPICLOCK enforcement below would not apply to them).
    admin.reset();
    try writeAllFd(fd_admin, "JOIN #c\r\n");
    try recvUntil(&admin, " 366 Founder #c ", 200);

    // DESC / URL persist and echo back.
    admin.reset();
    try writeAllFd(fd_admin, "CHANNEL SET #c DESC :Our cool room\r\n");
    try recvUntil(&admin, "Channel #c DESC set", 200);
    admin.reset();
    try writeAllFd(fd_admin, "CHANNEL SET #c URL https://example.test\r\n");
    try recvUntil(&admin, "Channel #c URL set to https://example.test", 200);

    // Boolean flags persist.
    admin.reset();
    try writeAllFd(fd_admin, "CHANNEL SET #c TOPICLOCK on\r\n");
    try recvUntil(&admin, "Channel #c topiclock on", 200);
    admin.reset();
    try writeAllFd(fd_admin, "CHANNEL SET #c PRIVATE on\r\n");
    try recvUntil(&admin, "Channel #c private on", 200);

    // INFO surfaces the persisted metadata + flags.
    admin.reset();
    try writeAllFd(fd_admin, "CHANNEL INFO #c\r\n");
    try recvUntil(&admin, "topiclock=true", 200);
    try recvUntil(&admin, "private=true", 200);

    // TOPICLOCK gates TOPIC for a non-op member even when +t isn't set live.
    const fd_bob = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_bob);
    var bob = LiveClient{ .fd = fd_bob };
    try writeAllFd(fd_bob, "NICK Bob\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&bob, " 001 Bob ", 200);
    bob.reset();
    try writeAllFd(fd_bob, "JOIN #c\r\n");
    try recvUntil(&bob, " 366 Bob #c ", 200);
    bob.reset();
    try writeAllFd(fd_bob, "TOPIC #c :hijack\r\n");
    try recvUntil(&bob, " 482 Bob #c ", 200); // ERR_CHANOPRIVSNEEDED
}

test "threaded server: STATS m reports per-command usage to an oper" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-stats-m.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("admin", "correcthorse", &scratch);

    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .sasl_checker = test_oper_checker,
        .oper_registry = oper_mod.OperRegistry.init(&test_oper_bindings) catch unreachable,
        .account_services = &services,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_admin = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_admin);
    var admin = LiveClient{ .fd = fd_admin };
    try saslAdminPrelude(fd_admin);
    try writeAllFd(fd_admin, "NICK Oper\r\nUSER oper 0 * :Oper\r\n");
    try recvUntil(&admin, " 381 Oper ", 200);

    // STATS m: 212 RPL_STATSCOMMANDS as `<cmd> <count> <bytes> <remote>`, then
    // 219. NICK was dispatched during registration so it appears in the table
    // with a positive count and a trailing remote field of 0.
    admin.reset();
    try writeAllFd(fd_admin, "STATS m\r\n");
    try recvUntil(&admin, " 212 Oper NICK ", 200);
    // Discrete params — not a single space-joined "count bytes 0" middle field.
    // Shape: `212 Oper NICK <count> <bytes> 0` before the empty trailing.
    const stats_m = admin.written();
    const nick_row = std.mem.indexOf(u8, stats_m, " 212 Oper NICK ") orelse return error.TestUnexpectedResult;
    const after_nick = stats_m[nick_row + " 212 Oper NICK ".len ..];
    const sp1 = std.mem.indexOfScalar(u8, after_nick, ' ') orelse return error.TestUnexpectedResult;
    const count_tok = after_nick[0..sp1];
    try std.testing.expect(count_tok.len > 0);
    for (count_tok) |ch| try std.testing.expect(ch >= '0' and ch <= '9');
    const rest = after_nick[sp1 + 1 ..];
    const sp2 = std.mem.indexOfScalar(u8, rest, ' ') orelse return error.TestUnexpectedResult;
    const bytes_tok = rest[0..sp2];
    try std.testing.expect(bytes_tok.len > 0);
    for (bytes_tok) |ch| try std.testing.expect(ch >= '0' and ch <= '9');
    try std.testing.expect(std.mem.startsWith(u8, rest[sp2 + 1 ..], "0"));
    try recvUntil(&admin, " 219 Oper m ", 200);

    // STATS i: 215 allow blocks (connection classes) for the configured registry.
    admin.reset();
    try writeAllFd(fd_admin, "STATS i\r\n");
    try recvUntil(&admin, " 219 Oper i ", 200);
}

test "threaded server: OROWASM reports ABI budgets and plugin registrations to opers" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var cfg = operTestConfig(0);
    cfg.wasm_max_plugin_bytes = 4096;
    cfg.wasm_max_memory_bytes = 128 * 1024;
    cfg.wasm_default_fuel = 1234;
    cfg.wasm_allowed_caps = wasm_abi.CapabilitySet.initMany(&.{ .reply, .hooks });
    var guard_digest: [std.crypto.hash.Blake3.digest_length]u8 = undefined;
    std.crypto.hash.Blake3.hash(wasm_bridge.testing.stop_hook_wasm, &guard_digest, .{});
    var publisher = try crypto_sign.KeyPair.fromSeed(@as([crypto_sign.seed_len]u8, @splat(0x61)));
    defer publisher.deinit();
    var registry_pin = wasm_bridge.RegistryPin{ .name = "guard", .blake3 = guard_digest, .tier = .verified, .publisher = publisher.public_key };
    var transcript_buf: [1024]u8 = undefined;
    const transcript = try wasm_bridge.registryPinTranscript(&transcript_buf, registry_pin);
    registry_pin.signature = try publisher.signCtx(wasm_bridge.registry_signature_domain, transcript);
    const registry_pins = [_]wasm_bridge.RegistryPin{registry_pin};
    cfg.wasm_registry = &registry_pins;
    const revoked_hashes = [_][std.crypto.hash.Blake3.digest_length]u8{@as([std.crypto.hash.Blake3.digest_length]u8, @splat(0xaa))};
    cfg.wasm_revoked_hashes = &revoked_hashes;
    cfg.wasm_disabled_plugins = &.{"bad"};
    var server = Server.init(std.testing.allocator, cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    try std.testing.expectError(error.PluginDisabled, server.wasm.loadBytes("bad", wasm_bridge.testing.stop_hook_wasm));
    try server.wasm.loadBytes("guard", wasm_bridge.testing.stop_hook_wasm);
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_user = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_user);
    var user = LiveClient{ .fd = fd_user };
    try writeAllFd(fd_user, "NICK User\r\nUSER user 0 * :User\r\n");
    try recvUntil(&user, " 001 User ", 200);
    user.reset();
    try writeAllFd(fd_user, "OROWASM STATUS\r\n");
    try recvUntil(&user, " 481 User ", 200);

    const fd_admin = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_admin);
    var admin = LiveClient{ .fd = fd_admin };
    try saslAdminPrelude(fd_admin);
    try writeAllFd(fd_admin, "NICK Oper\r\nUSER oper 0 * :Oper\r\n");
    try recvUntil(&admin, " 381 Oper ", 200);

    admin.reset();
    try writeAllFd(fd_admin, "OROWASM STATUS\r\n");
    try recvUntil(&admin, "OroWasm runtime status", 200);
    try recvUntil(&admin, "plugins=1 commands=0 hooks=1 allowed_caps=reply,hooks allowed_intents=(none) registry_pins=1 signed_pins=1 revoked_hashes=1 disabled_plugins=1 blocked_loads=1", 200);
    try recvUntil(&admin, "budgets max_plugin_bytes=4096 max_memory_bytes=131072 default_fuel=1234", 200);

    admin.reset();
    try writeAllFd(fd_admin, "OROWASM ABI\r\n");
    try recvUntil(&admin, "manifest_schema=1.0 host_functions=9 allowed_caps=reply,hooks allowed_intents=(none)", 200);
    try recvUntil(&admin, "hostcall reply v1.0 cap=reply", 200);
    try recvUntil(&admin, "hostcall net_connect v1.0 cap=net:outbound min_tier=verified", 200);
    try recvUntil(&admin, "intent message-content min_tier=verified", 200);

    admin.reset();
    try writeAllFd(fd_admin, "OROWASM WIT\r\n");
    try recvUntil(&admin, "OroWasm ABI WIT v1", 200);
    try recvUntil(&admin, "package onyx:orowasm@1.0.0;", 200);
    try recvUntil(&admin, "net-connect: func(host: string, port: u16)", 200);

    admin.reset();
    try writeAllFd(fd_admin, "OROWASM PLUGINS\r\n");
    try recvUntil(&admin, "handle=1 name=guard tier=verified signed=true commands=0 hooks=1 grants=(none) intents=(none)", 200);
