test "Helix grant checkpoint ignores stale persisted grant after revocation" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(std.testing.io, .{
        .sub_path = "oper-grants.tsv",
        .data = "revoked_oper\t1\tnetadmin\tStale grant\n",
    });
    var tmp_path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const tmp_path_len = try tmp.dir.realPath(std.testing.io, &tmp_path_buf);
    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const grants_path = try std.fmt.bufPrint(&path_buf, "{s}/oper-grants.tsv", .{tmp_path_buf[0..tmp_path_len]});
    const successor = createTestServer(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
        .oper_grants_path = grants_path,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer std.testing.allocator.destroy(successor);
    defer successor.deinit();
    const now = successor.grantNowU64();
    const incarnation = now + 5;
    _ = successor.oper_grants.upsert(.{
        .account = "revoked_oper",
        .privilege_bits = 0,
        .class = "revoked",
        .title = "",
        .issuer_node = protocol_inventory.currentServerName(),
        .incarnation = incarnation,
        .issued_ms = now,
        .expiry_ms = now + Server.oper_grant_ttl_ms,
    });
    successor.grant_incarnation = incarnation;
    successor.inherited_oper_grants_restored = true;
    successor.loadGrants();
    const carried = successor.oper_grants.lookup("revoked_oper", now) orelse return error.TestExpectedGrant;
    try std.testing.expectEqual(@as(u64, 0), carried.privilege_bits);
    try std.testing.expectEqual(incarnation, carried.incarnation);
    try std.testing.expectEqual(incarnation, successor.grant_incarnation);
}

test "threaded server: SASL oper elevation persists inactive OCG1 compatibility record" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-grant-persist.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("admin", "correcthorse", &scratch);

    // Keep the persistence target inside this test's cryptographically unique
    // tmpDir. A realtime-millisecond `/tmp` name collides when test-mod and
    // test-roadmap run this artifact in parallel, letting one process truncate
    // the other's grant between 381 and the assertion.
    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const grants_path = if (builtin.os.tag == .openbsd)
        // TmpDir is rooted under the runner's .zig-cache/tmp. OpenBSD has no
        // descriptor-to-path operation; keep the same unique owned directory.
        try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/oper-grants.tsv", .{tmp.sub_path})
    else blk: {
        var tmp_path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
        const tmp_path_len = try tmp.dir.realPath(std.testing.io, &tmp_path_buf);
        break :blk try std.fmt.bufPrint(&path_buf, "{s}/oper-grants.tsv", .{tmp_path_buf[0..tmp_path_len]});
    };

    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .sasl_checker = test_oper_checker,
        .oper_registry = oper_mod.OperRegistry.init(&test_oper_bindings) catch unreachable,
        .account_services = &services,
        .oper_grants_path = grants_path,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd);
    var admin = LiveClient{ .fd = fd };
    try saslAdminPrelude(fd);
    try writeAllFd(fd, "NICK Oper\r\nUSER oper 0 * :Oper\r\n");
    try recvUntil(&admin, " 381 Oper ", 200);

    // Configured-local elevation still emits the legacy compatibility record,
    // but loadGrants never treats this TSV row as session authority.
    const contents = std.Io.Dir.cwd().readFileAlloc(std.testing.io, grants_path, std.testing.allocator, .limited(4096)) catch |err| {
        std.debug.print("grants file not written: {any}\n", .{err});
        return error.TestUnexpectedResult;
    };
    defer std.testing.allocator.free(contents);
    try std.testing.expect(std.mem.indexOf(u8, contents, "admin\t") != null);
    try std.testing.expect(std.mem.indexOf(u8, contents, "netadmin") != null);

    // A cold-start consumer may reload that TSV row into its OCG1 registry, but
    // the row remains compatibility telemetry rather than runtime authority.
    var restored = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
        .oper_grants_path = grants_path,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer restored.deinit();
    restored.loadGrants();
    const loaded = restored.oper_grants.lookup("admin", restored.grantNowU64()) orelse
        return error.TestExpectedGrant;
    try std.testing.expect(oper_mod.OperPrivileges.fromBits(loaded.privilege_bits).has(.oper_override));
    try std.testing.expect(!restored.isOverrideOper("admin"));
    try std.testing.expect(!restored.remoteDataTagAuthorized("SYS.notice", false, null, "admin"));
}

test "threaded server: a joining network operator announces the derived +Y prefix to existing members" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-opery-join.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("admin", "correcthorse", &scratch);

    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .sasl_checker = test_oper_checker,
        .oper_registry = oper_mod.OperRegistry.init(&test_oper_bindings) catch unreachable,
        .account_services = &services,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    // A regular member joins first (and so founds the channel).
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    var alice = LiveClient{ .fd = fd_a };
    try writeAllFd(fd_a, "NICK Alice\r\nUSER alice 0 * :Alice\r\n");
    try recvUntil(&alice, " 001 Alice ", 200);
    try writeAllFd(fd_a, "JOIN #ops\r\n");
    try recvUntil(&alice, "JOIN", 200);

    // A network operator (oper_override via the admin grant) joins second.
    const fd_o = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_o);
    var oper = LiveClient{ .fd = fd_o };
    try saslAdminPrelude(fd_o);
    try writeAllFd(fd_o, "NICK Oper\r\nUSER oper 0 * :Oper\r\n");
    try recvUntil(&oper, " 381 Oper ", 200);

    // The bare JOIN cannot carry the derived `*`; the server must follow it with a
    // synthetic MODE +Y so Alice's nicklist shows the star without a fresh NAMES.
    alice.reset();
    try writeAllFd(fd_o, "JOIN #ops\r\n");
    try recvUntil(&alice, "MODE #ops +Y Oper", 200);
}

test "server services replay restores registered channels mlocks akicks and wards" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();

        var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-services-replay.wal");
        defer store.deinit();
        var services = services_mod.Services.init(&store, null);
        var scratch: [1024]u8 = undefined;
        _ = try services.registerAccount("admin", "correcthorse", &scratch);
        _ = try services.registerChannel("#c", "admin", &scratch);
        _ = try services.setChannel("#c", "admin", .{ .mlock = "+nt-k" }, &scratch);
        _ = try services.channelAkick("#c", "admin", "Bad!*@*", .add, "no bad", &scratch);
        try services.persistWard(.{
            .match = "mask",
            .pattern = "Bad!*@*",
            .scope = "node",
            .action = "expel",
            .reason = "spam",
            .setter = "admin",
            .created_ms = 1,
            .expires_ms = 0,
        }, &scratch);

        var server = Server.init(std.testing.allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .account_services = &services,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();

        server.replayServicesLiveState(&services);

        try std.testing.expect(server.world.channelHasExtFlag("#c", .registered));
        try std.testing.expectEqualStrings("+nt-k", server.mlocks.get("#c").?);
        const akick = server.chan_akick.matchOnJoin("#c", "Bad!bad@host", null, server.nowMs()) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("bad!*@*", akick.mask);
        try std.testing.expectEqualStrings("no bad", akick.reason);
        const ward = server.warden.check(.{ .mask = "Bad!bad@host" }, server.nowMs()) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqual(warden.Match.mask, ward.match);
        try std.testing.expectEqualStrings("Bad!*@*", ward.pattern);
        try std.testing.expectEqualStrings("spam", ward.reason);
    } else return error.SkipZigTest;
}

// GAP 2: SACCESS entries persist to the durable store and replay into the live
// `self.saccess` at boot. Simulates a restart by persisting via one Services
// handle and replaying into a freshly-initialized server, asserting the
// restored entries are present and enforce (matchHostmask).
test "server services replay restores persisted SACCESS entries" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();

        var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-saccess-replay.wal");
        defer store.deinit();
        var services = services_mod.Services.init(&store, null);
        var scratch: [1024]u8 = undefined;

        // Persist a DENY (with duration + reason), a GAG, and a GRANT.
        try services.persistSaccess(.{ .entry_type = "DENY", .mask = "bad!*@*", .duration = 60, .reason = "abuse" }, &scratch);
        try services.persistSaccess(.{ .entry_type = "GAG", .mask = "noisy!*@*" }, &scratch);
        try services.persistSaccess(.{ .entry_type = "GRANT", .mask = "trusted!*@*" }, &scratch);
        // A deleted entry must NOT come back after replay.
        try services.persistSaccess(.{ .entry_type = "DENY", .mask = "temp!*@*" }, &scratch);
        try services.deleteSaccess("DENY", "temp!*@*", &scratch);

        var server = Server.init(std.testing.allocator, .{
            .host = "127.0.0.1",
            .port = 0,
            .account_services = &services,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();

        server.replayServicesLiveState(&services);

        const deny = server.saccess.matchHostmask(.deny, "bad!user@host") orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("bad!*@*", deny.mask);
        try std.testing.expectEqual(@as(?u64, 60), deny.duration);
        try std.testing.expectEqualStrings("abuse", deny.reason.?);
        try std.testing.expect(server.saccess.matchHostmask(.gag, "noisy!x@j") != null);
        try std.testing.expect(server.saccess.matchHostmask(.grant, "trusted!x@j") != null);
        // The deleted DENY did not survive.
        try std.testing.expect(server.saccess.matchHostmask(.deny, "temp!x@j") == null);
    } else return error.SkipZigTest;
}

// GAP 2: a CLEAR mutation is durable. After clearing one type, replay restores
// only the surviving types.
test "server services replay honors persisted SACCESS clear" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();

        var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-saccess-clear.wal");
        defer store.deinit();
