    user.reset();
    try writeAllFd(fd_user, "REGISTER bob * correcthorse\r\n");
    try recvUntil(&user, "REGISTER SUCCESS bob", 200);
    user.reset();
    try writeAllFd(fd_user, "LOGOUT\r\n");
