// Same account + SAME nick from a second client stays connected, but the reusable
// token remains the authority boundary: pre-resume DMs are isolated and the same
// socket joins mandatory fan-out immediately after exact SESSION RESUME.
test "threaded server: same-account same-nick second client attaches, not 433-dropped" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-same-nick-resume.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var cfg = operTestConfig(0);
    cfg.crypto_io = std.testing.io;
    cfg.session_resume_composite_issuance = true;
    cfg.account_services = &services;
    var server = Server.init(std.testing.allocator, cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_s = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_s);
    const fd_k1 = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_k1);
    const fd_k2 = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_k2);
    var s = LiveClient{ .fd = fd_s };
    var k1 = LiveClient{ .fd = fd_k1 };
    var k2 = LiveClient{ .fd = fd_k2 };

    // A plain sender, plus two clients SASL-authed to the SAME account both
    // requesting the SAME nick "kain". The second must NOT be dropped.
    try writeAllFd(fd_s, "NICK S\r\nUSER sender 0 * :Sender\r\n");
    try saslPlainPrelude(fd_k1, "admin", "onyx");
    try writeAllFd(fd_k1, "NICK kain\r\nUSER kain 0 * :Kain One\r\n");
    try recvUntil(&k1, " 001 kain ", 200);
    try saslPlainPrelude(fd_k2, "admin", "onyx");
    try writeAllFd(fd_k2, "NICK kain\r\nUSER kain 0 * :Kain Two\r\n");
    // BOTH reach 001 (the second is NOT 433'd/closed). Display nick is "kain".
    try recvUntil(&k2, " 001 kain ", 200);
    try recvUntil(&s, " 001 S ", 200);

    // The second client must NOT have received a fatal ERR_NICKNAMEINUSE (433).
    try std.testing.expect(std.mem.indexOf(u8, k2.written(), " 433 ") == null);

    k1.reset();
    try writeAllFd(fd_k1, "SESSION TOKEN\r\n");
    try recvUntil(&k1, "SESSION TOKEN ", 200);
    const marker = "SESSION TOKEN ";
    const start = (std.mem.indexOf(u8, k1.written(), marker) orelse return error.TestUnexpectedResult) + marker.len;
    const tail = k1.written()[start..];
    const token_len = std.mem.indexOfScalar(u8, tail, '\r') orelse return error.TestUnexpectedResult;
    var token_buf: [session_resume_credential.local_text_len]u8 = undefined;
    @memcpy(token_buf[0..token_len], tail[0..token_len]);
    const token = token_buf[0..token_len];
    const exact = (try session_resume_credential.decode(token)).local;
    const legacy_group_token = std.fmt.bytesToHex(exact.group_token, .lower);

    // Same account and nick but a distinct token cannot consume the DM.
    k1.reset();
    k2.reset();
    try writeAllFd(fd_s, "PRIVMSG kain :before exact resume\r\n");
    try recvUntil(&k1, ":S!sender@localhost PRIVMSG kain :before exact resume\r\n", 200);
    waitMillis(50);
    try k2.readAvailable();
    try std.testing.expect(std.mem.indexOf(u8, k2.written(), "before exact resume") == null);

    // Presenting the exact credential joins the live logical session; the next
    // event reaches both transports once while both remain connected.
    var resume_buf: [128]u8 = undefined;
    k2.reset();
    try writeAllFd(fd_k2, try std.fmt.bufPrint(&resume_buf, "SESSION RESUME {s}\r\n", .{legacy_group_token}));
    try recvUntil(&k2, "attached to live session", 200);
    k1.reset();
    k2.reset();
    try writeAllFd(fd_s, "PRIVMSG kain :after exact resume\r\n");
    try recvUntil(&k1, ":S!sender@localhost PRIVMSG kain :after exact resume\r\n", 200);
    try recvUntil(&k2, ":S!sender@localhost PRIVMSG kain :after exact resume\r\n", 200);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(k1.written(), "after exact resume"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(k2.written(), "after exact resume"));

    // And the second connection is still live: it answers a PING.
    k2.reset();
    try writeAllFd(fd_k2, "PING probe2\r\n");
    try recvUntil(&k2, "PONG", 200);
}

test "threaded server: reusable session keeps all local clients live, synchronized, and participating" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-multi-attachment.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);

    var cfg = operTestConfig(0);
    cfg.crypto_io = std.testing.io;
    cfg.session_resume_composite_issuance = true;
    cfg.account_services = &services;
    // Use an ordinary authenticated account: the oper-test "admin" identity is
    // deliberately kick-immune, which would test +Y protection instead of
    // logical-session KICK fan-out.
    cfg.sasl_checker = test_dm_relay_checker;
    var server = Server.init(std.testing.allocator, cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_sender = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_sender);
    const fd_one = connectLoopback(port) catch return error.SkipZigTest;
    var one_open = true;
    defer if (one_open) closeFd(fd_one);
    const fd_two = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_two);
    var sender = LiveClient{ .fd = fd_sender };
    var one = LiveClient{ .fd = fd_one };
    var two = LiveClient{ .fd = fd_two };

    try writeAllFd(fd_sender, "NICK Sender\r\nUSER sender 0 * :Sender\r\n");
    try recvUntil(&sender, " 001 Sender ", 200);

    try saslPlainPreludeWithCaps(fd_one, "nova", "pw", "onyx/session-sync");
    try writeAllFd(fd_one, "NICK kain\r\nUSER one 0 * :One\r\n");
    try recvUntil(&one, " 001 kain ", 200);
    try writeAllFd(fd_one, "JOIN #shared\r\n");
    try recvUntil(&one, " 366 kain #shared ", 200);
    one.reset();
    try writeAllFd(fd_one, "SESSION TOKEN\r\n");
    try recvUntil(&one, "SESSION TOKEN ", 200);
    const marker = "SESSION TOKEN ";
    const start = (std.mem.indexOf(u8, one.written(), marker) orelse return error.TestUnexpectedResult) + marker.len;
    const tail = one.written()[start..];
    const token_len = std.mem.indexOfScalar(u8, tail, '\r') orelse return error.TestUnexpectedResult;
    var token_buf: [session_resume_credential.local_text_len]u8 = undefined;
    @memcpy(token_buf[0..token_len], tail[0..token_len]);
    const token = token_buf[0..token_len];
    const exact = (try session_resume_credential.decode(token)).local;
    const legacy_group_token = std.fmt.bytesToHex(exact.group_token, .lower);

    // The second socket reaches 001 but must NOT inherit by account+nick alone:
    // it starts with a distinct generated token. Only presenting the SAME
    // credential joins the exact logical token group and restores #shared as a
    // real member. The first socket remains connected throughout.
    try saslPlainPreludeWithCaps(fd_two, "nova", "pw", "onyx/session-sync");
    try writeAllFd(fd_two, "NICK kain\r\nUSER two 0 * :Two\r\n");
    try recvUntil(&two, " 001 kain ", 200);
    waitMillis(50);
    try two.readAvailable();
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "JOIN #shared") == null);
    var resume_buf: [128]u8 = undefined;
    one.reset();
    two.reset();
    try writeAllFd(fd_two, try std.fmt.bufPrint(&resume_buf, "SESSION RESUME {s}\r\n", .{legacy_group_token}));
    try recvUntil(&two, "attached to live session", 200);
    try recvUntil(&two, "JOIN #shared", 200);
    try recvUntil(&two, " 353 kain = #shared ", 200);
    try recvUntil(&two, " 366 kain #shared ", 200);
    try writeAllFd(fd_two, "PING :live-resume-names-complete\r\n");
    try recvUntil(&two, "PONG onyx.local :live-resume-names-complete", 200);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(two.written(), " 353 kain = #shared "));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(two.written(), " 366 kain #shared "));
    try expectSingleNamesNick(two.written(), " 353 kain = #shared ", "kain", "!kain");
    // The new transport receives its own JOIN bootstrap, topic and NAMES, but
    // the logical session was already in #shared. Existing attachments must not
    // see another identity-wide JOIN merely because a sibling resumed.
    waitMillis(50);
    try one.readAvailable();
    try std.testing.expect(std.mem.indexOf(u8, one.written(), "JOIN #shared") == null);
    try std.testing.expect(std.mem.indexOf(u8, one.written(), " 353 kain = #shared ") == null);
    try std.testing.expect(std.mem.indexOf(u8, one.written(), " 366 kain #shared ") == null);

    one.reset();
    two.reset();
    try writeAllFd(fd_sender, "JOIN #shared\r\n");
    try recvUntil(&sender, " 366 Sender #shared ", 200);
    sender.reset();
    try writeAllFd(fd_sender, "PRIVMSG #shared :event-to-every-client\r\n");
    try recvUntil(&one, "PRIVMSG #shared :event-to-every-client", 200);
    try recvUntil(&two, "PRIVMSG #shared :event-to-every-client", 200);

    // Either attachment can act with the shared channel membership.
    sender.reset();
    one.reset();
    try writeAllFd(fd_two, "PRIVMSG #shared :sent-from-second\r\n");
    try recvUntil(&sender, "PRIVMSG #shared :sent-from-second", 200);
    try recvUntil(&one, "PRIVMSG #shared :sent-from-second", 200);

    // A new logical JOIN bootstraps every attached transport, including topic
    // and NAMES, and the sibling can participate immediately.
    try writeAllFd(fd_sender, "JOIN #bootstrap\r\n");
    try recvUntil(&sender, " 366 Sender #bootstrap ", 200);
    try writeAllFd(fd_sender, "TOPIC #bootstrap :shared state\r\n");
    try recvUntil(&sender, "TOPIC #bootstrap :shared state", 200);
    one.reset();
    two.reset();
    try writeAllFd(fd_one, "JOIN #bootstrap\r\n");
    try recvUntil(&one, " 366 kain #bootstrap ", 200);
    try recvUntil(&two, "JOIN #bootstrap", 200);
    try recvUntil(&two, " 332 kain #bootstrap :shared state", 200);
    try recvUntil(&two, " 366 kain #bootstrap ", 200);
    sender.reset();
    try writeAllFd(fd_two, "PRIVMSG #bootstrap :joined-on-sibling\r\n");
    try recvUntil(&sender, "PRIVMSG #bootstrap :joined-on-sibling", 200);

    // NICK is token-group atomic: both attachments observe it exactly once,
    // both immediately render the new identity, and direct lookup moves with it.
    one.reset();
    two.reset();
    sender.reset();
    // Keep the semantic assertion independent of the per-connection command
    // flood bucket under a CPU-saturated full-suite run.
    testSleepMs(1_100);
    try writeAllFd(fd_two, "NICK OnyxUser\r\n");
    try recvUntil(&one, " NICK :OnyxUser", 200);
    try recvUntil(&two, " NICK :OnyxUser", 200);
    try recvUntil(&sender, " NICK :OnyxUser", 200);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(one.written(), "NICK :OnyxUser"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(two.written(), "NICK :OnyxUser"));
    one.reset();
    two.reset();
    try writeAllFd(fd_sender, "PRIVMSG OnyxUser :after-group-nick\r\n");
    try recvUntil(&one, "PRIVMSG OnyxUser :after-group-nick", 200);
    try recvUntil(&two, "PRIVMSG OnyxUser :after-group-nick", 200);

    // Member MODE and KICK also target the logical token group, not whichever
    // transport happens to own the nick lookup.
    sender.reset();
    try writeAllFd(fd_sender, "MODE #bootstrap +m\r\nMODE #bootstrap +v OnyxUser\r\n");
    try recvUntil(&sender, "MODE #bootstrap +v OnyxUser", 200);
    try writeAllFd(fd_one, "PRIVMSG #bootstrap :voice-from-one\r\n");
    try recvUntil(&sender, "PRIVMSG #bootstrap :voice-from-one", 200);
    try writeAllFd(fd_two, "PRIVMSG #bootstrap :voice-from-two\r\n");
    try recvUntil(&sender, "PRIVMSG #bootstrap :voice-from-two", 200);
    one.reset();
    two.reset();
    // Refill the sender's command-rate bucket after the rapid JOIN/TOPIC/MODE
    // setup so this assertion exercises KICK semantics rather than throttling.
    testSleepMs(1_100);
    try writeAllFd(fd_sender, "KICK #bootstrap OnyxUser :group kick\r\n");
    try recvUntil(&one, "KICK #bootstrap OnyxUser :group kick", 1000);
    try recvUntil(&two, "KICK #bootstrap OnyxUser :group kick", 1000);
    one.reset();
    two.reset();
    try writeAllFd(fd_one, "PRIVMSG #bootstrap :must fail one\r\n");
    try writeAllFd(fd_two, "PRIVMSG #bootstrap :must fail two\r\n");
    try recvUntil(&one, " 404 OnyxUser #bootstrap ", 1000);
    try recvUntil(&two, " 404 OnyxUser #bootstrap ", 1000);

    // Losing the original world owner hands nick/channel ownership to the second
    // attachment without an offline transition or disconnecting it.
    closeFd(fd_one);
    one_open = false;
    testSleepMs(80);
    two.reset();
    try writeAllFd(fd_sender, "PRIVMSG OnyxUser :after-handoff\r\n");
    try recvUntil(&two, "PRIVMSG OnyxUser :after-handoff", 200);
    sender.reset();
    try writeAllFd(fd_two, "PRIVMSG #shared :still-participating\r\n");
    try recvUntil(&sender, "PRIVMSG #shared :still-participating", 200);

    // TOKEN remains the group credential after handoff, not a newly minted
    // per-owner secret.
    two.reset();
    try writeAllFd(fd_two, "SESSION TOKEN\r\n");
    try recvUntil(&two, "SESSION TOKEN ", 200);
    const handoff_credential = testSessionTokenFromReply(two.written(), "SESSION TOKEN ") orelse
        return error.TestUnexpectedResult;
    const handoff_local = switch (try session_resume_credential.decode(handoff_credential)) {
        .local => |value| value,
        .mesh => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(exact.group_token, handoff_local.group_token);
    try std.testing.expect(!handoff_local.attachment_id.eql(exact.attachment_id));
}

test "threaded server: draft/multiline batch reassembles + splits to recipient" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };

    // A negotiates draft/multiline; B is an ordinary member.
    try writeAllFd(fd_a, "CAP REQ :draft/multiline\r\nNICK A\r\nUSER alice 0 * :Alice\r\nCAP END\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&b, " 001 B ", 200);
    try writeAllFd(fd_a, "JOIN #m\r\n");
    try recvUntil(&a, " 366 A #m ", 200);
    try writeAllFd(fd_b, "JOIN #m\r\n");
    try recvUntil(&b, " 366 B #m ", 200);

    // chunk2 carries the concat tag so it joins chunk1 into one line; chunk3 is a
    // fresh line. The reassembled value is "Line1more\nLine2" and is delivered to
    // B as two separate PRIVMSGs.
    b.reset();
    try writeAllFd(fd_a, "BATCH +z draft/multiline #m\r\n" ++
        "@batch=z PRIVMSG #m :Line1\r\n" ++
        "@batch=z;draft/multiline-concat PRIVMSG #m :more\r\n" ++
        "@batch=z PRIVMSG #m :Line2\r\n" ++
        "BATCH -z\r\n");
    try recvUntil(&b, ":A!alice@localhost PRIVMSG #m :Line1more\r\n", 200);
    try recvUntil(&b, ":A!alice@localhost PRIVMSG #m :Line2\r\n", 200);
}

