test "Windows history HTTPS stages old TLS material long OCSP and mandatory HXRG" {
    if (comptime builtin.os.tag != .windows) return error.SkipZigTest;
    const native_history = @import("helix/native_windows_history.zig");
    const allocator = std.testing.allocator;
    var cert_buf: [1024]u8 = undefined;
    const cert = try mintRehashTlsLeaf(&cert_buf, 0x95, "history-replay.test");
    const chain = [_][]const u8{cert.der};
    var renewed_cert_buf: [1024]u8 = undefined;
    const renewed_cert = try mintRehashTlsLeaf(&renewed_cert_buf, 0x96, "history-replay.test");
    const renewed_chain = [_][]const u8{renewed_cert.der};
    const long_staple: [2048]u8 = @splat(0x5a);
    const config = Config{
        .host = "127.0.0.1",
        .port = 0,
        .tls_cert_chain = &chain,
        .tls_signing_key = cert.kp,
        .tls_enable_resumption = true,
        .tls_early_data_max_size = 4096,
        .crypto_io = std.testing.io,
    };

    const source = try allocator.create(Server);
    defer allocator.destroy(source);
    source.initInPlace(allocator, config) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer source.deinit();
    source.tls_ticket_key = @splat(0x21);
    var history_config = source.tls13Config(false);
    history_config.ocsp_staple = &long_staple;
    _ = source.openHistoryHttps("127.0.0.1", 0, history_config) catch |err| switch (err) {
        error.SocketUnavailable, error.BindFailed, error.ListenFailed => return error.SkipZigTest,
        else => return err,
    };
    const history_key = source.history_https.?.tls_config.ticket_key.?;
    const history_clock = source.history_https.?.tls_config.now_unix_seconds.?;
    // Model a later ACME renewal: the current Server generation is B while
    // the independent history listener is still pinned to A and its staple.
    source.config.tls_cert_chain = &renewed_chain;
    source.config.tls_signing_key = renewed_cert.kp;
    source.rotateTicketKey();
    try std.testing.expectEqualSlices(u8, cert.der, source.history_https.?.tls_config.cert_chain[0]);
    try std.testing.expectEqualSlices(u8, renewed_cert.der, source.config.tls_cert_chain[0]);
    try std.testing.expect(!std.mem.eql(u8, &history_key, &source.tls_ticket_key));
    try std.testing.expect(source.historyTlsReplayCustodyValid(source.history_https.?.tls_config));

    const tag16: [16]u8 = @splat(0x16);
    const binder32: [32]u8 = @splat(0x32);
    const binder48: [48]u8 = @splat(0x48);
    try std.testing.expect(source.tls_replay_guard.checkAndRecord(&tag16));
    try std.testing.expect(source.tls_replay_guard.checkAndRecord(&binder32));
    try std.testing.expect(source.tls_replay_guard.checkAndRecord(&binder48));

    const token = try source.history_https.?.requestPause(1);
    try source.history_https.?.awaitPaused(token, std.Io.Clock.Timestamp.fromNow(std.testing.io, .{ .clock = .awake, .raw = .fromSeconds(2) }));
    defer source.history_https.?.resumePaused(token) catch {};
    const carry = try source.history_https.?.capturePaused(token);
    const process = @intFromPtr(std.os.windows.GetCurrentProcess());
    const pid = std.os.windows.GetCurrentProcessId();
    var prepared = try native_history.prepareSource(.{ .owner = &source.history_https.?, .carry = &carry, .pause_token = token }, process, pid);
    defer prepared.deinit();
    var received = (try native_history.receive(&prepared.body, pid)) orelse return error.TestUnexpectedResult;
    defer received.deinit();
    const history_material_wire = try native_windows_history_material.encodeSnapshot(allocator, source.history_https.?.tls_config);
    defer native_windows_history_material.freeEncoded(allocator, history_material_wire);
    try native_windows_history_material.validateCheckpoint(history_material_wire);
    var history_material = try native_windows_history_material.decodeOwned(allocator, history_material_wire);
    defer history_material.deinit();

    const candidate = try allocator.create(Server);
    defer allocator.destroy(candidate);
    var renewed_config = config;
    renewed_config.tls_cert_chain = &renewed_chain;
    renewed_config.tls_signing_key = renewed_cert.kp;
    candidate.initInPlace(allocator, renewed_config) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer candidate.deinit();
    candidate.tls_ticket_key = @splat(0x99);
    const stable_guard = @intFromPtr(&candidate.tls_replay_guard);
    const candidate_base = candidate.tls13Config(false);
    const without_history_material = try received.tlsConfig(candidate_base, &candidate.tls_replay_guard);
    try std.testing.expectError(error.ConfigMismatch, received.carry.validate(false, without_history_material));
    const restored = try received.tlsConfig(history_material.tlsConfig(candidate_base), &candidate.tls_replay_guard);
    try std.testing.expectEqualSlices(u8, cert.der, restored.cert_chain[0]);
    try std.testing.expectEqualSlices(u8, &long_staple, restored.ocsp_staple);
    try std.testing.expectEqualSlices(u8, &history_key, &restored.ticket_key.?);
    try std.testing.expectEqual(history_clock, restored.now_unix_seconds.?);
    try std.testing.expectEqual(@as(u32, 4096), restored.max_early_data_size);
    try std.testing.expect(restored.replay_guard == &candidate.tls_replay_guard);
    try std.testing.expect(!std.mem.eql(u8, &candidate.tls_ticket_key, &restored.ticket_key.?));
    try std.testing.expectEqual(carry.tls_digest, try history_http.tlsConfigDigest(restored));

    var foreign_guard = tls_resumption.ReplayGuard{};
    var wrong_guard = restored;
    wrong_guard.replay_guard = &foreign_guard;
    try std.testing.expectError(error.InvalidInheritedHandoff, candidate.stageWindowsInheritedHistory(&received.transfer, &received.carry, wrong_guard, std.testing.io));
    try std.testing.expect(!received.transfer.consumed);

    // A resumed ticket or early-data binder in history HTTPS must hit the same
    // server guard after its socket and pinned TLS policy are staged.
    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(allocator);
    const wire = try Server.sealTlsReplayUpgradeCheckpoint(allocator, &source.tls_replay_guard, &pieces);
    defer {
        std.crypto.secureZero(u8, wire);
        allocator.free(wire);
    }
    try std.testing.expectError(error.InvalidInheritedHandoff, Server.stageTlsReplayUpgradeCheckpoint(allocator, true, &.{}));
    var field = [_]helix_capsule.Field{.{ .ordinal = 1, .bytes = wire }};
    var cap = helix_capsule.make(.mesh_checkpoint, &field);
    cap.header.min_supported = 2;
    var replacement = (try Server.stageTlsReplayUpgradeCheckpoint(allocator, true, &.{cap})) orelse return error.TestUnexpectedResult;
    defer replacement.deinit();
    try candidate.stageWindowsInheritedHistory(&received.transfer, &received.carry, restored, std.testing.io);
    try std.testing.expect(received.transfer.consumed);
    try std.testing.expect(candidate.history_https.?.tls_config.replay_guard == &candidate.tls_replay_guard);
    replacement.install(&candidate.tls_replay_guard);
    try std.testing.expectEqual(stable_guard, @intFromPtr(&candidate.tls_replay_guard));
    try std.testing.expect(!candidate.tls_replay_guard.checkAndRecord(&tag16));
    try std.testing.expect(!candidate.tls_replay_guard.checkAndRecord(&binder32));
    try std.testing.expect(!candidate.tls_replay_guard.checkAndRecord(&binder48));
}

test "Windows Helix admission checkpoints match the carried physical clients" {
    if (comptime builtin.os.tag != .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const server = try allocator.create(Server);
    defer allocator.destroy(server);
    server.initInPlace(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .max_clients = 2,
        .throttle_connects = 5,
        .max_clones_per_ip_net = 6,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const id = try server.reactors[0].clients.alloc(ConnState.init(-1));
    defer _ = server.reactors[0].clients.free(id);
    const conn = server.reactors[0].clients.get(id).?;
    conn.peer_addr = .{ .ipv4 = .{ 203, 0, 113, 7 } };
    conn.throttle_counted = true;
    const hash = server.meshCloneHash(conn).?;
    conn.mesh_clone_counted = true;
    conn.mesh_clone_hash = hash;

    var detector = clone_detect_mod.CloneDetector.init(allocator, server.conn_throttle.?.params);
    defer detector.deinit();
    try std.testing.expectEqual(clone_detect_mod.Decision.allow, try detector.classifyConnect(100, "203.0.113.7"));
    var clones = mesh_clones_mod.MeshClones.init(allocator);
    defer clones.deinit();
    try std.testing.expectEqual(@as(u32, 1), try clones.addLocal(hash));
    try server.validateInheritedAdmissionRelation(&detector, &clones);

    try std.testing.expect(detector.disconnect("203.0.113.7"));
    try std.testing.expectError(error.InvalidAdmissionRelation, server.validateInheritedAdmissionRelation(&detector, &clones));
    try std.testing.expectEqual(clone_detect_mod.Decision.allow, try detector.classifyConnect(101, "203.0.113.7"));
    try std.testing.expectEqual(@as(u32, 0), clones.removeLocal(hash));
    try std.testing.expectError(error.InvalidAdmissionRelation, server.validateInheritedAdmissionRelation(&detector, &clones));
}

test "shared full server: OpenBSD native Helix stages live clients until COMMIT and preserves ABORT peers" {
    if (comptime builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    current_reactor = null;
    defer current_reactor = null;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store_allocator = std.testing.FailingAllocator.init(allocator, .{});
    var store = try services_mod.OroStore.open(store_allocator.allocator(), std.testing.io, tmp.dir, "native-history.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    const predecessor = try createTestServer(allocator, .{
        .host = "::",
        .port = 0,
        .max_clients = 8,
        .ws_enabled = true,
        .ws_allow_plain = true,
        .ws_port = 0,
        .num_shards = 2,
        .account_services = &services,
        .crypto_io = std.testing.io,
    });
    defer allocator.destroy(predecessor);
    var predecessor_deinited = false;
    defer if (!predecessor_deinited) predecessor.deinit();
    var run = std.atomic.Value(bool).init(true);
    var thread = try std.Thread.spawn(.{}, Server.runThreaded, .{ predecessor, &run });
    var running = true;
    defer if (running) stopThreadedServer(predecessor, &run, thread);
    const port = try predecessor.boundPort();
    const fd4 = try connectNativeLoopbackForTest(.ipv4, port);
    defer closeFd(fd4);
    const fd6 = try connectNativeLoopbackForTest(.ipv6, port);
    defer closeFd(fd6);
    var v4 = LiveClient{ .fd = fd4 };
    var v6 = LiveClient{ .fd = fd6 };
    try writeAllFd(fd4, "NICK Four\r\nUSER four 0 * :Four\r\nJOIN #native-helix\r\n");
    try recvUntil(&v4, " 366 Four #native-helix ", 200);
    try writeAllFd(fd6, "NICK Six\r\nUSER six 0 * :Six\r\nJOIN #native-helix\r\n");
    try recvUntil(&v6, " 366 Six #native-helix ", 200);
    v6.reset();
    try writeAllFd(fd4, "PRIVMSG #native-helix :before-native-upgrade\r\n");
    try recvUntil(&v6, "PRIVMSG #native-helix :before-native-upgrade", 200);
    // A second live channel is appended after the first, while canonical
    // iteration orders it first. The readonly candidate cannot repair this
    // ordinary append-order difference in the predecessor's WAL.
    try writeAllFd(fd4, "JOIN #aaa-native-history\r\n");
    try recvUntil(&v4, " 366 Four #aaa-native-history ", 200);
    try writeAllFd(fd6, "JOIN #aaa-native-history\r\n");
    try recvUntil(&v6, " 366 Six #aaa-native-history ", 200);
    try writeAllFd(fd4, "PRIVMSG #aaa-native-history :accepted-durable-history\r\n");
    try recvUntil(&v6, "PRIVMSG #aaa-native-history :accepted-durable-history", 200);
    stopThreadedServer(predecessor, &run, thread);
    running = false;
    for (predecessor.reactors) |*r| {
        current_reactor = r;
        try predecessor.quiesceOwnedSocketIo();
    }
    // Exercise the production refusal/unwind before any capsule or native
    // transfer. Only the storage allocator fails; live accepted history and
    // the prior published durable generation must remain usable.
    const meta_before = try allocator.dupe(u8, store.get(.history, "meta").?);
    defer allocator.free(meta_before);
    const wal_offset_before = store.wal_offset;
    const history_before = try predecessor.history.encodeCheckpoint(allocator);
    defer allocator.free(history_before);
    const history_count_before = predecessor.history.totalStoredCount();
    try std.testing.expect(history_count_before >= 2);
    current_reactor = &predecessor.reactors[0];
    store_allocator.fail_index = store_allocator.alloc_index;
    const refused = predecessor.performUpgradeAfterCompatibleTarget(.signal, -1, "/unused-native-test-image");
    store_allocator.fail_index = std.math.maxInt(usize);
    try std.testing.expectError(error.OutOfMemory, refused);
    try std.testing.expect(store_allocator.has_induced_failure);
    try std.testing.expectEqualSlices(u8, meta_before, store.get(.history, "meta").?);
    try std.testing.expectEqual(wal_offset_before, store.wal_offset);
    const history_after_refusal = try predecessor.history.encodeCheckpoint(allocator);
    defer allocator.free(history_after_refusal);
    try std.testing.expectEqualSlices(u8, history_before, history_after_refusal);
    try std.testing.expectEqual(no_quiesce_shard, predecessor.upgrade_quiesce_shard.load(.acquire));

    // Refusal resumed its coordinator as production requires. Re-enter each
    // owner safe point before this stopped-worker fixture seals a candidate.
    for (predecessor.reactors) |*r| {
        current_reactor = r;
        try predecessor.quiesceOwnedSocketIo();
    }
    predecessor.world.lockWrite();
    const synchronized = predecessor.prepareNativeDurableHistoryUpgradeBoundary();
    predecessor.world.unlockWrite();
    try synchronized;
    const original_rows = try predecessor.collectListenerManifest(allocator);
    defer allocator.free(original_rows);

    const Barrier = struct {
        candidate: *Server,
        abort: bool,
        calls: usize = 0,
        wal_dir: std.Io.Dir,
        wal_before: []const u8,
        fn expectWalUnchanged(self: *const @This()) !void {
            const bytes = try self.wal_dir.readFileAlloc(std.testing.io, "native-history.wal", std.testing.allocator, .unlimited);
            defer std.testing.allocator.free(bytes);
            try std.testing.expectEqualSlices(u8, self.wal_before, bytes);
        }
        fn ready(ctx: *anyopaque) !void {
            const self: *@This() = @ptrCast(@alignCast(ctx));
            self.calls += 1;
            try std.testing.expect(!self.candidate.inheritedStateConsumedBeforeServices());
            const candidate_store = self.candidate.account_services.?.store;
            try std.testing.expect(candidate_store.isReadOnly());
            try std.testing.expectEqual(@as(usize, 0), candidate_store.changeCount());
            try self.expectWalUnchanged();
            try std.testing.expectEqual(@as(usize, 2), self.candidate.reactors.len);
            for (self.candidate.reactors) |*r| {
                // Canonical copied fds below deliberately select both modulo
                // owners; kernel REUSEPORT distribution is not assumed.
                try std.testing.expectEqual(@as(usize, 1), r.clients.len());
                try std.testing.expect(r.acceptsQuiesced());
                for (r.clients.slots.items) |slot| if (slot.occupied) {
                    try std.testing.expect(!slot.value.recv_armed and !slot.value.send_armed);
                };
            }
            if (self.abort) return error.NativeCandidateAborted;
        }
    };

    for ([_]bool{ true, false }) |abort| {
        const rows = try allocator.dupe(ListenerDescriptor, original_rows);
        defer allocator.free(rows);
        var duplicated: usize = 0;
        var listeners_transferred = false;
        defer if (!listeners_transferred) for (rows[0..duplicated]) |row| os_runtime.close(row.fd);
        for (rows) |*row| {
            row.fd = try os_runtime.duplicate(row.fd);
            duplicated += 1;
        }
        const wal_before_adopt = try tmp.dir.readFileAlloc(std.testing.io, "native-history.wal", allocator, .unlimited);
        defer allocator.free(wal_before_adopt);
        var readonly_store = try services_mod.OroStore.openReadOnlyWithConfig(allocator, std.testing.io, tmp.dir, "native-history.wal", .{});
        defer readonly_store.deinit();
        var readonly_services = services_mod.Services.init(&readonly_store, null);
        var cfg = predecessor.config;
        cfg.account_services = &readonly_services;
        cfg.native_listener_manifest = rows;
        // No descriptor may be silently dropped or replaced by a fresh bind.
        var missing = cfg;
        missing.native_listener_manifest = rows[0 .. rows.len - 1];
        try std.testing.expectError(error.InvalidInheritedListener, createTestServer(allocator, missing));
        var invalid = try allocator.dupe(ListenerDescriptor, rows);
        defer allocator.free(invalid);
        invalid[1].kind = invalid[0].kind;
        invalid[1].family = invalid[0].family;
        var duplicate_key = cfg;
        duplicate_key.native_listener_manifest = invalid;
        try std.testing.expectError(error.InvalidInheritedListener, createTestServer(allocator, duplicate_key));
        for (rows) |row| try std.testing.expect(os_runtime.fdValid(row.fd));
        const candidate = try createTestServer(allocator, cfg);
        listeners_transferred = true;
        defer allocator.destroy(candidate);
        defer candidate.deinit();
        const adopted_rows = try candidate.collectListenerManifest(allocator);
        defer allocator.free(adopted_rows);
        try std.testing.expectEqualSlices(ListenerDescriptor, rows, adopted_rows);

        // Duplicate accepted sockets as SCM_RIGHTS does. For this one-process
        // fixture seal their canonical copied numbers while retaining the
        // serving predecessor's original descriptor and socket authority.
        const Saved = struct { conn: *ConnState, original: linux.fd_t };
        var saved: [2]Saved = undefined;
        var copied_fds: [2]linux.fd_t = undefined;
        var count: usize = 0;
        var restored = false;
        var state_transferred = false;
        defer {
            if (!restored) for (saved[0..count]) |s| {
                s.conn.fd = s.original;
            };
            if (!state_transferred) for (copied_fds[0..count]) |fd| os_runtime.close(fd);
        }
        var minimum: i32 = 0;
        for (rows) |row| minimum = @max(minimum, row.fd);
        for (predecessor.reactors) |*r| for (r.clients.slots.items) |slot| {
            if (slot.occupied) minimum = @max(minimum, slot.value.fd);
        };
        minimum = (minimum + 32) & ~@as(i32, 1);
        for (predecessor.reactors) |*r| for (r.clients.slots.items) |*slot| {
            if (!slot.occupied) continue;
            try std.testing.expect(count < saved.len);
            const rc = posix.system.fcntl(slot.value.fd, posix.F.DUPFD, minimum + @as(i32, @intCast(count)));
            if (posix.errno(rc) != .SUCCESS) return error.Unexpected;
            const copy: linux.fd_t = @intCast(rc);
            saved[count] = .{ .conn = &slot.value, .original = slot.value.fd };
            copied_fds[count] = copy;
            slot.value.fd = copy;
            count += 1;
        };
        try std.testing.expectEqual(@as(usize, 2), count);
        var blobs: std.ArrayList([]u8) = .empty;
        defer {
            for (blobs.items) |blob| allocator.free(blob);
            blobs.deinit(allocator);
        }
        var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
        defer pieces.deinit(allocator);
        try appendCurrentMandatoryUpgradeStateForTest(predecessor, &pieces, &blobs);
        _ = predecessor.sealSessionRegistry(&pieces, &blobs) orelse return error.TestUnexpectedResult;
        var carried: [2]linux.fd_t = undefined;
        var carried_count: usize = 0;
        var counts = Server.SealCounts{};
        for (predecessor.reactors) |*r| predecessor.sealShardClients(r, &pieces, &blobs, &carried, &carried_count, &counts);
        try std.testing.expectEqual(@as(usize, 2), counts.clients);
        try std.testing.expect(!counts.fd_prepare_failed);
        for (saved[0..count]) |s| s.conn.fd = s.original;
        restored = true;
        for (carried[0..carried_count]) |fd| {
            const flags = posix.system.fcntl(fd, posix.F.GETFD, @as(i32, 0));
            try std.testing.expect(flags & posix.FD_CLOEXEC != 0);
        }
        // No source piece has kind handoff_manifest, so this test helper leaves
        // every header canonical and appends the mandatory manifest normally.
        const arena = try encodeUpgradeStreamWithWidenedHeaderForTest(allocator, pieces.items, .handoff_manifest);
        defer {
            std.crypto.secureZero(u8, arena);
            allocator.free(arena);
        }
        var barrier = Barrier{ .candidate = candidate, .abort = abort, .wal_dir = tmp.dir, .wal_before = wal_before_adopt };
        candidate.config.native_arena_bytes = arena;
        candidate.config.native_adopt_barrier = .{ .ctx = &barrier, .readyAndAwaitCommit = Barrier.ready };
        candidate.config.inherited_state_fds = &copied_fds;
        candidate.config.inherited_state_fd_manifest_present = true;
        candidate.config.inherited_state_fd_manifest_valid = true;
        state_transferred = true;
        if (abort) {
            try std.testing.expectError(error.InvalidInheritedHandoff, candidate.adoptInheritedSessions());
            try std.testing.expectEqual(@as(usize, 1), barrier.calls);
            try std.testing.expect(readonly_store.isReadOnly());
            try barrier.expectWalUnchanged();
            try std.testing.expectEqual(@as(usize, 0), readonly_store.changeCount());
            for (candidate.reactors) |*r| try std.testing.expectEqual(@as(usize, 0), r.clients.len());
            try std.testing.expectEqual(@as(usize, 0), candidate.world.channelCount());
            for (copied_fds) |fd| try std.testing.expect(!os_runtime.fdValid(fd));
            // An aborted candidate closes its copies without shutdown of the
            // same socket OFDs still owned by the serving predecessor.
            // This fixture stopped and joined the original workers; a live
            // upgrade instead resumes them. Drain retained delivery before
            // releasing the old run's pool/fabric and starting a fresh run.
            for (predecessor.reactors) |*r| {
                current_reactor = r;
                predecessor.drainUpgradeFabric();
            }
            predecessor.world.lockWrite();
            const drained = predecessor.drainAllUpgradeFabricFixedPointLocked();
            predecessor.world.unlockWrite();
            _ = try drained;
            predecessor.pool.deinit();
            if (predecessor.fabric) |*fabric| fabric.deinit();
            predecessor.fabric = null;
            for (predecessor.reactors) |*r| {
                current_reactor = r;
                predecessor.resumeOwnedSocketIo();
            }
            run.store(true, .release);
            thread = try std.Thread.spawn(.{}, Server.runThreaded, .{ predecessor, &run });
            running = true;
            v4.reset();
            try writeAllFd(fd4, "PING :abort-preserved\r\n");
            try recvUntil(&v4, "PONG onyx.local :abort-preserved", 200);
            stopThreadedServer(predecessor, &run, thread);
            running = false;
            for (predecessor.reactors) |*r| {
                current_reactor = r;
                try predecessor.quiesceOwnedSocketIo();
            }
        } else {
            try candidate.adoptInheritedSessions();
            try std.testing.expectEqual(@as(usize, 1), barrier.calls);
            try std.testing.expect(candidate.inheritedStateConsumedBeforeServices());
            try std.testing.expect(!readonly_store.isReadOnly());
            try std.testing.expectEqual(@as(usize, 0), readonly_store.changeCount());
            try std.testing.expectEqual(history_count_before, candidate.history.totalStoredCount());
            try barrier.expectWalUnchanged();
            predecessor.deinit();
            predecessor_deinited = true;
            current_reactor = null;
            var next_run = std.atomic.Value(bool).init(true);
            const next_thread = try std.Thread.spawn(.{}, Server.runThreaded, .{ candidate, &next_run });
            defer stopThreadedServer(candidate, &next_run, next_thread);
            v4.reset();
            v6.reset();
            try writeAllFd(fd6, "PING :commit-preserved\r\n");
            try recvUntil(&v6, "PONG onyx.local :commit-preserved", 200);
            try writeAllFd(fd4, "PRIVMSG #native-helix :after-native-commit\r\n");
            const message = "PRIVMSG #native-helix :after-native-commit";
            try recvUntil(&v6, message, 200);
            try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, v6.written(), message));
        }
        current_reactor = null;
    }
}

test "shared full server: poisoned shard stops and joins every reactor with a terminal outcome" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    current_reactor = null;
    defer current_reactor = null;
    const allocator = std.testing.allocator;
    const server = createTestServer(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .num_shards = 2,
        .max_clients = 8,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer allocator.destroy(server);
    defer server.deinit();
    try std.testing.expectEqual(@as(usize, 2), server.reactors.len);
    try std.testing.expect(server.runtimeFailure() == null);
    for (server.reactors) |r| try std.testing.expect(r.wake != null);

    var run = std.atomic.Value(bool).init(true);
    const Runner = struct {
        fn entry(s: *Server, flag: *std.atomic.Value(bool), done: *std.atomic.Value(bool)) void {
            s.runThreaded(flag);
            done.store(true, .release);
        }
    };
    var done = std.atomic.Value(bool).init(false);
    const thr = try std.Thread.spawn(.{}, Runner.entry, .{ server, &run, &done });
    defer stopThreadedServer(server, &run, thr);

    // Both real reactor threads must have armed and consumed a native wake
    // before poisoning just shard 1; shard 0 is healthy and can be asleep.
    const startup_deadline = platform.monotonicMillis() + 5_000;
    while (server.reactors[0].wake_count.load(.acquire) == 0 or
        server.reactors[1].wake_count.load(.acquire) == 0)
    {
        if (platform.monotonicMillis() >= startup_deadline) return error.TestTimeout;
        server.wakeAllReactors();
        os_runtime.sleepMillis(1);
    }
    server.reactor_poison_shard_for_test.store(1, .release);
    server.wakeAllReactors();
    const stop_deadline = platform.monotonicMillis() + 5_000;
    while (!done.load(.acquire)) {
        if (platform.monotonicMillis() >= stop_deadline) return error.TestTimeout;
        os_runtime.sleepMillis(1);
    }
    try std.testing.expect(!run.load(.acquire));
    try std.testing.expectEqual(error.BackendPoisoned, server.runtimeFailure().?);
    try std.testing.expectEqual(@as(usize, 0), server.pool.count());
    // Runtime shutdown preserves the slabs until backend teardown releases all
    // outstanding references; no fatal callback frees another shard's buffers.
    for (server.reactors) |r| try std.testing.expect(r.clients.slots.capacity >= 8);
}

test "threaded server: external wakeReactor drives the running reactor loop" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        if (server.rx().wake == null) return error.SkipZigTest; // eventfd unavailable
        const plain_port = try server.boundPort();

        var run = std.atomic.Value(bool).init(true);
        var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
        defer {
            run.store(false, .release);
            if (connectLoopback(plain_port)) |wfd| closeFd(wfd) else |_| {}
            thr.join();
        }

        // From this (foreign) thread, wake the reactor; the in-flight wake poll
        // completes, the loop runs, and onWakePoll bumps the counter.
        server.wakeReactor();
        var spins: usize = 0;
        while (server.rx().wake_count.load(.monotonic) == 0) : (spins += 1) {
            if (spins > 5_000_000) return error.TestUnexpectedResult;
            std.Thread.yield() catch {};
        }
        try std.testing.expect(server.rx().wake_count.load(.monotonic) >= 1);
    } else return error.SkipZigTest;
}

test "ring: poll op fires a completion when a watched eventfd becomes readable" {
    if (comptime builtin.os.tag == .linux) {
        var ring = RingCore.init(8, .{}) catch |err| {
            if (ringlane.isUnsupportedInitError(err)) return error.SkipZigTest;
            return err;
        };
        defer ring.deinit();

        const efd_rc = linux.eventfd(0, 0);
        if (posix.errno(efd_rc) != .SUCCESS) return error.SkipZigTest;
        const efd: linux.fd_t = @intCast(efd_rc);
        defer closeFd(efd);

        const tok = RingFdToken{ .slot = 7, .gen = 3 };
        try ring.submitPollAdd(tok, efd, linux.POLL.IN);

        // Make the eventfd readable, then reap: the poll completion must fire.
        var one: u64 = 1;
        _ = linux.write(efd, std.mem.asBytes(&one), @sizeOf(u64));

        const Sink = struct {
            got: bool = false,
            slot: u32 = 0,
            res: i32 = 0,
            pub fn onCompletion(self: *@This(), c: ringlane.Completion) void {
                switch (c) {
                    .poll => |e| {
                        self.got = true;
                        self.slot = e.token.slot;
                        self.res = e.res;
                    },
                    else => {},
                }
            }
        };
        var sink = Sink{};
        _ = try ring.submitAndWait(1);
        var cqes: [8]linux.io_uring_cqe = undefined;
        try ring.reapCompletions(&cqes, 0, &sink);

        try std.testing.expect(sink.got);
        try std.testing.expectEqual(@as(u32, 7), sink.slot);
        try std.testing.expect(sink.res >= 0); // poll res carries the ready mask
    } else return error.SkipZigTest;
}

test "threaded server: implicit-TLS client handshakes + registers over the wire" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const Ed25519 = std.crypto.sign.Ed25519;
        const tls_client = @import("../crypto/tls_client.zig");
        const x509_selfsign = @import("../proto/x509_selfsign.zig");
        const alloc = std.testing.allocator;

        // Bootstrap a self-signed Ed25519 leaf with a SAN the client will accept.
        const kp = try Ed25519.KeyPair.generateDeterministic(@as([Ed25519.KeyPair.seed_length]u8, @splat(0x51)));
        var cert_buf: [1024]u8 = undefined;
        const der = try x509_selfsign.buildSelfSigned(&cert_buf, .{
            .common_name = "irc.test",
            .not_before = 1_704_067_200,
            .not_after = 4_102_444_800,
            .serial = &.{ 0x51, 0x01 },
            .key_pair = kp,
            .dns_names = &.{"irc.test"},
            .is_ca = true,
        });
        const chain = [_][]const u8{der};

        const server = try alloc.create(Server);
        defer alloc.destroy(server);
        server.initInPlace(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .tls_port = 0,
            .tls_cert_chain = &chain,
            .tls_signing_key = kp,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const tls_port = try server.tlsBoundPort();
        const plain_port = try server.boundPort();

        var run = std.atomic.Value(bool).init(true);
        var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ server, &run });
        defer {
            run.store(false, .release);
            if (connectLoopback(plain_port)) |wfd| closeFd(wfd) else |_| {}
            thr.join();
        }

        const fd = connectLoopback(tls_port) catch return error.SkipZigTest;
        defer closeFd(fd);

        var client = try tls_client.Client.init(alloc, .{ .server_name = "irc.test", .trust_anchors = &chain });
        defer client.deinit();

        // TLS 1.3 handshake driven over the live socket.
        const ch = try client.start();
        defer alloc.free(ch);
        try writeAllFd(fd, ch);
        var rbuf: [4096]u8 = undefined;
        var guard: usize = 0;
        while (!client.handshakeDone()) : (guard += 1) {
            if (guard > 64) return error.TestUnexpectedResult;
            const n = try readFd(fd, &rbuf);
            if (n == 0) return error.TestUnexpectedResult;
            switch (try client.feed(rbuf[0..n])) {
                .bytes_to_send => |b| {
                    defer alloc.free(b);
                    try writeAllFd(fd, b);
                },
                .need_more => {},
            }
        }

        try std.testing.expect(client.handshakeDone());

        // Registration over the encrypted channel: send NICK/USER, then read the
        // welcome burst back, framing + decrypting TLS records until RPL_WELCOME.
        const reg = try client.encrypt("NICK T\r\nUSER t 0 * :Tester\r\n");
        defer alloc.free(reg);
        try writeAllFd(fd, reg);

        var plain: std.ArrayList(u8) = .empty;
        defer plain.deinit(alloc);
        var cipher: std.ArrayList(u8) = .empty;
        defer cipher.deinit(alloc);
        guard = 0;
        while (std.mem.indexOf(u8, plain.items, " 001 T ") == null) : (guard += 1) {
            if (guard > 64) return error.TestUnexpectedResult;
            const n = try readFd(fd, &rbuf);
            if (n == 0) return error.TestUnexpectedResult;
            try cipher.appendSlice(alloc, rbuf[0..n]);
            // Drain every complete TLS record (5-byte header + big-endian length).
            while (cipher.items.len >= 5) {
                const body_len = std.mem.readInt(u16, cipher.items[3..5], .big);
                const wire_len = 5 + @as(usize, body_len);
                if (cipher.items.len < wire_len) break;
                switch (try client.decryptApp(cipher.items[0..wire_len])) {
                    .application_data => |pt| {
                        defer alloc.free(pt);
                        try plain.appendSlice(alloc, pt);
                    },
                    .control => {},
                }
                std.mem.copyForwards(u8, cipher.items[0 .. cipher.items.len - wire_len], cipher.items[wire_len..]);
                cipher.shrinkRetainingCapacity(cipher.items.len - wire_len);
            }
        }
        try expectContains(plain.items, " 001 T ");
    } else return error.SkipZigTest;
}

/// A live TLS client that frames the encrypted socket into DISCRETE application
/// records, keeping BOTH the concatenated plaintext (for substring waits) AND
/// each record's decrypted bytes separately (so a test can assert how a single
/// logical message was split across records). Used to prove atomic tag+line
/// delivery: a tagged fan-out to this client must arrive as ONE record whose
/// plaintext holds both the `@tag` and the line.
const TlsRecordProbe = struct {
    const tls_client = @import("../crypto/tls_client.zig");
    const rec_hdr_len: usize = 5; // 1 type + 2 legacy version + 2 length

    fd: linux.fd_t,
    alloc: std.mem.Allocator,
    client: *tls_client.Client,
    cipher: std.ArrayList(u8) = .empty,
    plain: std.ArrayList(u8) = .empty,
    records: std.ArrayList([]u8) = .empty,

    fn deinit(self: *TlsRecordProbe) void {
        for (self.records.items) |r| self.alloc.free(r);
        self.records.deinit(self.alloc);
        self.cipher.deinit(self.alloc);
        self.plain.deinit(self.alloc);
    }

    /// TLS 1.3 handshake driven over the live socket (server side is the reactor).
    fn handshake(self: *TlsRecordProbe) !void {
        const ch = try self.client.start();
        defer self.alloc.free(ch);
        try writeAllFd(self.fd, ch);
        var rbuf: [4096]u8 = undefined;
        var guard: usize = 0;
        const native_deadline = platform.monotonicMillis() + 20_000;
        while (!self.client.handshakeDone()) : (guard += 1) {
            if (guard > 64) return error.TestUnexpectedResult;
            if (comptime builtin.os.tag == .openbsd) {
                var ready = false;
                while (platform.monotonicMillis() < native_deadline) {
                    var fds = [_]posix.pollfd{.{ .fd = self.fd, .events = posix.POLL.IN, .revents = 0 }};
                    if (try posix.poll(&fds, 50) != 0) {
                        if (fds[0].revents & posix.POLL.IN == 0) return error.ConnectionReset;
                        ready = true;
                        break;
                    }
                }
                if (!ready) return error.TestTimeout;
            }
            const n = try readFd(self.fd, &rbuf);
            if (n == 0) return error.TestUnexpectedResult;
            switch (try self.client.feed(rbuf[0..n])) {
                .bytes_to_send => |b| {
                    defer self.alloc.free(b);
                    try writeAllFd(self.fd, b);
                },
                .need_more => {},
            }
        }
    }

    fn send(self: *TlsRecordProbe, text: []const u8) !void {
        const ct = try self.client.encrypt(text);
        defer self.alloc.free(ct);
        try writeAllFd(self.fd, ct);
    }

    /// Frame every COMPLETE TLS record currently buffered, decrypting each into
    /// its own `records` entry (application_data only; control records like a
    /// post-handshake ticket are consumed but not counted).
    fn frame(self: *TlsRecordProbe) !void {
        while (self.cipher.items.len >= rec_hdr_len) {
            const body_len = std.mem.readInt(u16, self.cipher.items[3..5], .big);
            const wire_len = rec_hdr_len + @as(usize, body_len);
            if (self.cipher.items.len < wire_len) break;
            switch (try self.client.decryptApp(self.cipher.items[0..wire_len])) {
                .application_data => |pt| {
                    // Ownership of `pt` transfers to `records`; also mirror into
                    // the concatenated `plain` view for substring waits.
                    try self.plain.appendSlice(self.alloc, pt);
                    try self.records.append(self.alloc, pt);
                },
                .control => {},
            }
            std.mem.copyForwards(u8, self.cipher.items[0 .. self.cipher.items.len - wire_len], self.cipher.items[wire_len..]);
            self.cipher.shrinkRetainingCapacity(self.cipher.items.len - wire_len);
        }
    }

    /// Read + frame until the concatenated plaintext contains `needle`, bounded by
    /// a wall-clock budget so a delivery regression fails loudly instead of hanging.
    fn pumpUntil(self: *TlsRecordProbe, needle: []const u8, budget_ms: i64) !void {
        const deadline = platform.monotonicMillis() + budget_ms;
        var rbuf: [4096]u8 = undefined;
        while (std.mem.indexOf(u8, self.plain.items, needle) == null) {
            if (platform.monotonicMillis() >= deadline) return error.TestTimeout;
            const poll_in = if (builtin.os.tag == .openbsd) posix.POLL.IN else linux.POLL.IN;
            var fds = [_]posix.pollfd{.{ .fd = self.fd, .events = poll_in, .revents = 0 }};
            const ready = posix.poll(&fds, 50) catch return error.Unexpected;
            if (ready == 0) continue;
            if ((fds[0].revents & poll_in) == 0) continue;
            const n = try readFd(self.fd, &rbuf);
            if (n == 0) return error.ConnectionReset;
            try self.cipher.appendSlice(self.alloc, rbuf[0..n]);
            try self.frame();
        }
    }

    /// The single record whose plaintext carries `body_needle`, or null.
    fn recordCarrying(self: *const TlsRecordProbe, body_needle: []const u8) ?[]const u8 {
        for (self.records.items) |r| {
            if (std.mem.indexOf(u8, r, body_needle) != null) return r;
        }
        return null;
    }
};

const NativeTlsProbeForTest = struct {
    client: @import("../crypto/tls_client.zig").Client,
    probe: TlsRecordProbe,

    fn init(allocator: std.mem.Allocator, fd: linux.fd_t, chain: []const []const u8) !*@This() {
        errdefer closeFd(fd);
        const self = try allocator.create(@This());
        errdefer allocator.destroy(self);
        self.client = try @import("../crypto/tls_client.zig").Client.init(allocator, .{ .server_name = "irc.test", .trust_anchors = chain });
        self.probe = .{ .fd = fd, .alloc = allocator, .client = &self.client };
        return self;
    }

    fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
        self.probe.deinit();
        self.client.deinit();
        closeFd(self.probe.fd);
        allocator.destroy(self);
    }

    fn sendTextFrame(self: *@This(), text: []const u8) !void {
        var buffer: [1024]u8 = undefined;
        const frame = try websocket.encodeFrame(8192, .{ .opcode = .text, .mask_key = .{ 0x13, 0x27, 0x35, 0x49 } }, text, &buffer);
        try self.probe.send(frame);
    }
};

// Regression pin for atomic tag+line delivery. A tagged channel PRIVMSG to a
// userspace-TLS recipient must seal the `@tag` prefix and line into ONE TLS
// record on the wire. This drives a REAL tagged fan-out through the reactor's
// delivery path and asserts the recipient's single body-bearing record ALSO
// carries the tag, while a plaintext member receives the same intact line.
test "threaded server: tagged PRIVMSG to a userspace-TLS member seals one TLS record; plaintext unaffected" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const Ed25519 = std.crypto.sign.Ed25519;
        const tls_client = @import("../crypto/tls_client.zig");
        const x509_selfsign = @import("../proto/x509_selfsign.zig");
        const alloc = std.testing.allocator;

        const kp = try Ed25519.KeyPair.generateDeterministic(@as([Ed25519.KeyPair.seed_length]u8, @splat(0x5c)));
        var cert_buf: [1024]u8 = undefined;
        const der = try x509_selfsign.buildSelfSigned(&cert_buf, .{
            .common_name = "irc.test",
            .not_before = 1_704_067_200,
            .not_after = 4_102_444_800,
            .serial = &.{ 0x5c, 0x01 },
            .key_pair = kp,
            .dns_names = &.{"irc.test"},
            .is_ca = true,
        });
        const chain = [_][]const u8{der};

        const server = try alloc.create(Server);
        defer alloc.destroy(server);
        server.initInPlace(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .tls_port = 0,
            .tls_cert_chain = &chain,
            .tls_signing_key = kp,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const tls_port = try server.tlsBoundPort();
        const plain_port = try server.boundPort();

        var run = std.atomic.Value(bool).init(true);
        const thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ server, &run });
        defer stopThreadedServer(server, &run, thr);

        // Recipient A: a userspace-TLS member that negotiates server-time +
        // message-tags, so a relayed channel PRIVMSG carries a non-empty
        // `@time=…;msgid=… ` prefix — the exact input to the coalescing branch.
        const fd_a = connectLoopback(tls_port) catch return error.SkipZigTest;
        defer closeFd(fd_a);
        var client = try tls_client.Client.init(alloc, .{ .server_name = "irc.test", .trust_anchors = &chain });
        defer client.deinit();
        var a = TlsRecordProbe{ .fd = fd_a, .alloc = alloc, .client = &client };
        defer a.deinit();
        try a.handshake();

        try a.send("CAP REQ :server-time message-tags\r\n");
        try a.pumpUntil("ACK", 4_000);
        try a.send("NICK A\r\nUSER a 0 * :Alice\r\nCAP END\r\n");
        try a.pumpUntil(" 001 A ", 4_000);
        try a.send("JOIN #tls\r\n");
        try a.pumpUntil(" 366 A #tls ", 4_000);

        // Plaintext member C: same caps, so it too gets the fully tagged line —
        // proving the plaintext path still delivers the tag+line intact.
        const fd_c = connectLoopback(plain_port) catch return error.SkipZigTest;
        defer closeFd(fd_c);
        var c = LiveClient{ .fd = fd_c };
        try writeAllFd(fd_c, "CAP REQ :server-time message-tags\r\n");
        try recvUntil(&c, "ACK", 200);
        try writeAllFd(fd_c, "NICK C\r\nUSER c 0 * :Carol\r\nCAP END\r\n");
        try recvUntil(&c, " 001 C ", 200);
        try writeAllFd(fd_c, "JOIN #tls\r\n");
        try recvUntil(&c, " 366 C #tls ", 200);

        // Sender B (plaintext) joins and messages the channel once.
        const fd_b = connectLoopback(plain_port) catch return error.SkipZigTest;
        defer closeFd(fd_b);
        var b = LiveClient{ .fd = fd_b };
        try writeAllFd(fd_b, "NICK B\r\nUSER b 0 * :Bob\r\n");
        try recvUntil(&b, " 001 B ", 200);
        try writeAllFd(fd_b, "JOIN #tls\r\n");
        try recvUntil(&b, " 366 B #tls ", 200);

        // Drain A + C past B's JOIN notification so the measurement window holds
        // only the PRIVMSG delivery.
        try a.pumpUntil(":B", 4_000);
        try a.pumpUntil("JOIN #tls", 4_000);
        try recvUntil(&c, "JOIN #tls", 200);
        c.reset();

        const marker = "one-record-9a7c3f";
        const body = ":B!b@localhost PRIVMSG #tls :" ++ marker;
        try writeAllFd(fd_b, "PRIVMSG #tls :" ++ marker ++ "\r\n");

        // The recipient must see the message body. Find the record carrying it and
        // assert the SAME record also carries the tag prefix — proving the tag and
        // line coalesced into ONE TLS record (not two discrete records).
        try a.pumpUntil("PRIVMSG #tls :" ++ marker, 4_000);
        const rec = a.recordCarrying(marker) orelse return error.TestExpectedEqual;
        // One-record proof: the body-bearing record opens with the `@`-tag segment
        // and includes the server-time tag. A two-append regression would put the
        // tag in a PRIOR record, leaving this one starting at the `:` prefix.
        try std.testing.expect(rec.len != 0 and rec[0] == '@');
        try expectContains(rec, "@time=");
        try expectContains(rec, body);
        // And no record is a bare tag segment lacking the line (the split shape).
        for (a.records.items) |r| {
            if (std.mem.indexOf(u8, r, "@time=") != null and std.mem.indexOf(u8, r, marker) != null) {
                try expectContains(r, "PRIVMSG #tls :");
            }
        }

        // Plaintext member C received the fully tagged line intact (unaffected):
        // the delivered line begins with the `@`-tag and carries the body.
        try recvUntil(&c, marker, 200);
        const cbytes = c.written();
        const cpos = std.mem.indexOf(u8, cbytes, body) orelse return error.TestExpectedEqual;
        const line_start = if (std.mem.lastIndexOfScalar(u8, cbytes[0..cpos], '\n')) |nl| nl + 1 else 0;
        try std.testing.expect(cbytes[line_start] == '@');
        try expectContains(cbytes[line_start..], "@time=");
    } else return error.SkipZigTest;
}

// Heap-owned real TLS peers for the physical daemon application-output seam.
const DaemonOutputTestPair = struct {
    const Client = union(tls_conn.Version) {
        tls12: @import("../crypto/tls12_client.zig").Client,
        tls13: @import("../crypto/tls_client.zig").Client,
    };
    conn: ConnState,
    tls: tls_conn.TlsConn,
    client: Client,
    cert13: [2048]u8,
    cert12: [4096]u8,
    chain13: [1][]const u8,
    chain12: [1][]const u8,

    fn create(version: tls_conn.Version) !*DaemonOutputTestPair {
        return createSuite(version, null);
    }

    fn createSuite(version: tls_conn.Version, suite: ?u16) !*DaemonOutputTestPair {
        const a = std.testing.allocator;
        const pair = try a.create(DaemonOutputTestPair);
        errdefer a.destroy(pair);
        pair.conn = .{ .overflow_allocator = a, .test_sendq_capture = true };
        pair.conn.tls = &pair.tls;
        const Ed25519 = std.crypto.sign.Ed25519;
        const kp = try Ed25519.KeyPair.generateDeterministic(@as([32]u8, @splat(0x5d)));
        const x509 = @import("../proto/x509_selfsign.zig");
        pair.chain13[0] = try x509.buildSelfSigned(&pair.cert13, .{
            .common_name = "irc.test",
            .not_before = 1_704_067_200,
            .not_after = 1_893_456_000,
            .serial = &.{1},
            .key_pair = kp,
            .dns_names = &.{"irc.test"},
            .is_ca = true,
        });
        const cfg13 = tls_server.Config{ .cert_chain = &pair.chain13, .signing_key = kp };
        switch (version) {
            .tls13 => {
                pair.tls = try tls_conn.TlsConn.init(a, cfg13);
                errdefer pair.tls.deinit();
                pair.client = .{ .tls13 = try @import("../crypto/tls_client.zig").Client.init(a, .{ .server_name = "irc.test", .trust_anchors = &pair.chain13 }) };
            },
            .tls12 => {
                const ec = ecdsa_p256.KeyPair.generate(std.testing.io);
                pair.chain12[0] = try x509.buildSelfSignedEcdsaP256(&pair.cert12, .{
                    .common_name = "irc.test",
                    .not_before = 1_704_067_200,
                    .not_after = 1_893_456_000,
                    .serial = &.{1},
                    .key_pair = ec,
                    .dns_names = &.{"irc.test"},
                    .is_ca = true,
                });
                pair.tls = tls_conn.TlsConn.initDual(a, cfg13, .{ .cert_chain = &pair.chain12, .ecdsa_p256_signing_key = ec });
                errdefer pair.tls.deinit();
                pair.client = .{ .tls12 = try @import("../crypto/tls12_client.zig").Client.init(a, .{ .server_name = "irc.test", .trust_anchors = &pair.chain12, .now_unix_seconds = 1_735_689_600 }) };
            },
        }
        errdefer {
            pair.tls.deinit();
            switch (pair.client) {
                inline else => |*client| client.deinit(),
            }
        }
        if (suite) |chosen| {
            std.debug.assert(version == .tls13);
            pair.client.tls13.force_aes256_only_for_test = chosen == 0x1302;
            pair.client.tls13.force_chacha_only_for_test = chosen == 0x1303;
        }
        const hello = switch (pair.client) {
            inline else => |*client| try client.start(),
        };
        defer a.free(hello);
        const flight = try pair.tls.onInbound(hello);
        const finished = switch (pair.client) {
            inline else => |*client| switch (try client.feed(flight.handshake_bytes)) {
                .bytes_to_send => |bytes| bytes,
                .need_more => return error.TestUnexpectedResult,
            },
        };
        defer a.free(finished);
        const final = try pair.tls.onInbound(finished);
        if (version == .tls12) _ = try pair.client.tls12.feed(final.handshake_bytes);
        try std.testing.expect(pair.tls.handshakeDone());
        return pair;
    }

    fn destroy(self: *DaemonOutputTestPair) void {
        self.conn.send_overflow.deinit(std.testing.allocator);
        self.conn.tls_deferred_plain.deinit(std.testing.allocator);
        self.tls.deinit();
        switch (self.client) {
            inline else => |*client| client.deinit(),
        }
        std.testing.allocator.destroy(self);
    }

    fn sequence(self: *const DaemonOutputTestPair) u64 {
        return switch (self.tls.engine) {
            inline .tls12, .tls13 => |engine| engine.app_write_seq,
            .undecided => unreachable,
        };
    }

    fn generation(self: *const DaemonOutputTestPair) u64 {
        return switch (self.tls.engine) {
            inline .tls12, .tls13 => |engine| engine.app_write_generation,
            .undecided => unreachable,
        };
    }

    fn decode(self: *DaemonOutputTestPair, bytes: []const u8) ![]u8 {
        const a = std.testing.allocator;
        var decoded: std.ArrayList(u8) = .empty;
        errdefer decoded.deinit(a);
        var at: usize = 0;
        while (at != bytes.len) {
            if (bytes.len - at < 5) return error.TestUnexpectedResult;
            const len = 5 + @as(usize, std.mem.readInt(u16, bytes[at..][3..5], .big));
            if (len > bytes.len - at) return error.TestUnexpectedResult;
            const payload = switch (self.client) {
                inline else => |*client| try client.decrypt(bytes[at..][0..len]),
            };
            defer a.free(payload);
            try decoded.appendSlice(a, payload);
            at += len;
        }
        return decoded.toOwnedSlice(a);
    }
};

fn daemonOutputQueued(a: std.mem.Allocator, conn: *const ConnState) ![]u8 {
    var queued: std.ArrayList(u8) = .empty;
    errdefer queued.deinit(a);
    try queued.appendSlice(a, conn.send_buf[conn.send_offset..conn.send_len]);
    try queued.appendSlice(a, conn.send_overflow.items);
    return queued.toOwnedSlice(a);
}

// The declared sink owns a real slab connection and socket. The test explicitly
// drives the physical FIFO; no armed operation or fake kernel custody is used.
const Tls3ServerFixture = struct {
    server: *Server,
    pair: *DaemonOutputTestPair,
    id: client_model.ClientId,
    peer_fd: i32,

    fn create(suite: u16) !Tls3ServerFixture {
        return createTransport(suite, false);
    }

    fn createTransport(suite: u16, tcp: bool) !Tls3ServerFixture {
        // The TLS fixture drives full-server reactors; no portable equivalent exists.
        if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.Unsupported;
        const a = std.testing.allocator;
        const pair = try DaemonOutputTestPair.createSuite(.tls13, suite);
        errdefer pair.destroy();
        const server = try createTestServer(a, .{ .host = "127.0.0.1", .port = 0, .tls_cert_chain = &pair.chain13, .tls_signing_key = pair.tls.cfg13.signing_key });
        errdefer {
            server.deinit();
            a.destroy(server);
        }
        const sockets = if (tcp) blk: {
            if (comptime builtin.os.tag != .linux) return error.Unsupported;
            const peer = try connectLoopback(try server.boundPort());
            errdefer closeFd(peer);
            var ready = [_]posix.pollfd{.{ .fd = server.reactors[0].listener_fd, .events = posix.POLL.IN, .revents = 0 }};
            if (try posix.poll(&ready, 2000) == 0) return error.TestTimeout;
            const accepted = linux.accept4(server.reactors[0].listener_fd, null, null, linux.SOCK.CLOEXEC);
            if (posix.errno(accepted) != .SUCCESS) return error.TestUnexpectedResult;
            break :blk [2]i32{ @intCast(accepted), peer };
        } else try sameIPTestSocketPair();
        errdefer closeFd(sockets[0]);
        errdefer closeFd(sockets[1]);
        try os_runtime.setNonblocking(sockets[0]);
        const id = try addTestLocalClient(server, "Tls3Owner", null);
        const conn = server.rx().clients.get(id).?;
        conn.session.restore(.{ .nick = "Tls3Owner", .username = "owner", .realname = "TLS3 owner" });
        conn.test_sendq_capture = true;
        // Move the authenticated adapter into the same heap custody used by a
        // live accepted connection. Real close/CQE paths may destroy this row.
        var empty_adapter = try tls_conn.TlsConn.init(a, pair.tls.cfg13);
        errdefer empty_adapter.deinit();
        const owned_adapter = try a.create(tls_conn.TlsConn);
        owned_adapter.* = pair.tls;
        pair.tls = empty_adapter;
        conn.fd = sockets[0];
        conn.tls = owned_adapter;
        conn.is_tls = true;
        return .{ .server = server, .pair = pair, .id = id, .peer_fd = sockets[1] };
    }

    fn connection(self: *Tls3ServerFixture) *ConnState {
        return self.server.reactors[0].clients.get(self.id).?;
    }

    fn deinit(self: *Tls3ServerFixture) void {
        // The first adapter and any adopted adapters have ordinary Server
        // ownership, including when a real completion already retired the row.
        self.server.deinit();
        std.testing.allocator.destroy(self.server);
        closeFd(self.peer_fd);
        self.pair.destroy();
    }
};

fn tls3ServerDrain(fixture: *Tls3ServerFixture, conn: *ConnState) ![]u8 {
    const a = std.testing.allocator;
    try std.testing.expect(!conn.send_armed);
    const queued = try daemonOutputQueued(a, conn);
    defer a.free(queued);
    try std.testing.expect(queued.len != 0);
    // These bounded fixtures fit the socket buffer. Compare actual received
    // ciphertext before the owner retires the queue prefix.
    try writeAllFd(conn.fd, queued);
    const received = try a.alloc(u8, queued.len);
    defer a.free(received);
    var offset: usize = 0;
    while (offset != received.len) {
        var ready = [_]posix.pollfd{.{ .fd = fixture.peer_fd, .events = posix.POLL.IN, .revents = 0 }};
        if (try posix.poll(&ready, 2000) == 0) return error.TestTimeout;
        const n = try readFd(fixture.peer_fd, received[offset..]);
        if (n == 0) return error.TestUnexpectedResult;
        offset += n;
    }
    try std.testing.expectEqualSlices(u8, queued, received);
    const decoded = try fixture.pair.decode(received);
    conn.send_len = 0;
    conn.send_offset = 0;
    conn.send_overflow.clearRetainingCapacity();
    return decoded;
}

fn tls3ServerCapture(conn: *ConnState) ![]u8 {
    return tls3ServerCaptureWithAllocator(conn, std.testing.allocator);
}

fn tls3ServerCaptureWithAllocator(conn: *ConnState, a: std.mem.Allocator) ![]u8 {
    var captured = try conn.tls.?.prepareCapture(a, .{
        .fd = conn.fd,
        .tx_offloaded = conn.tls_tx_offloaded,
        .rx_offloaded = conn.tls_rx_offloaded,
        .wire_chunks = &.{ conn.send_buf[conn.send_offset..conn.send_len], conn.send_overflow.items },
        .deferred_plain = conn.tls_deferred_plain.items,
        .deferred_ciphertext_charge = conn.tls_deferred_charge,
        .control_charge = @intCast(conn.tls_control_charge),
        .queue_cap = conn.sendq_cap,
        .kernel_tx_prefix_remaining = conn.tls_kernel_prefix_remaining,
    });
    defer captured.deinit();
    return tls_snapshot.encode(a, .{
        .kernel_tx_prefix_remaining = captured.kernel_tx_prefix_remaining,
        .fd = conn.fd,
        .state = captured.state,
        .pending_out = captured.pending_out,
        .tx_offloaded = conn.tls_tx_offloaded,
        .rx_offloaded = conn.tls_rx_offloaded,
        .control_charge = @intCast(conn.tls_control_charge),
        .deferred_ciphertext_charge = conn.tls_deferred_charge,
        .deferred_plain = conn.tls_deferred_plain.items,
    });
}

fn tls3ServerSoftwareBarrier(suite: u16) !void {
    defer current_reactor = null;
    const a = std.testing.allocator;
    var fixture = try Tls3ServerFixture.create(suite);
    defer fixture.deinit();
    const conn = fixture.connection();
    const t = conn.tls.?;
    const ws = try a.create(WsState);
    defer a.destroy(ws);
    ws.* = .{ .phase = .open };
    conn.ws = ws;
    defer conn.ws = null;
    try appendSecuredToConn(conn, "old sealed prefix");
    const tx_before = t.engine.tls13.app_write_seq;
    const old_rx_secret = t.engine.tls13.client_app_secret;
    const old_tx_secret = t.engine.tls13.server_app_secret;
    try fixture.pair.client.tls13.sendKeyUpdateFragmentsForTest(true, &.{ 1, 4 });
    const request = (try fixture.pair.client.tls13.takePendingSend()).?;
    defer a.free(request);
    try fixture.server.driveTls(fixture.id, conn, request);
    try std.testing.expect(!conn.closing);
    try std.testing.expectEqual(tls_conn.ControlBarrierPhase.userspace_requested_ku_held, t.control_phase);
    try std.testing.expectEqual(@as(usize, 27), conn.tls_control_charge);
    try std.testing.expectEqual(tx_before, t.engine.tls13.app_write_seq);
    try std.testing.expectEqualSlices(u8, &old_rx_secret, &t.engine.tls13.client_app_secret);
    try std.testing.expectEqualSlices(u8, &old_tx_secret, &t.engine.tls13.server_app_secret);
    const held = try a.dupe(u8, t.recv_buf.items);
    defer a.free(held);

    // Complete WS frames gain deferred custody; their unframed suffix remains
    // in WsState and no TLS sequence moves until the reply has wire custody.
    @memcpy(ws.tx_buf[0..4], "held");
    ws.tx_len = 4;
    const cap_before = conn.sendq_cap;
    conn.sendq_cap = @intCast(sendq.backlog(conn));
    try std.testing.expectError(error.OutputTooSmall, appendToConn(conn, " line\r\nsecond\r\nsuffix"));
    try std.testing.expectEqualStrings("held", ws.tx_buf[0..ws.tx_len]);
    try std.testing.expectEqual(@as(usize, 0), conn.tls_deferred_plain.items.len);
    var failing = std.testing.FailingAllocator.init(a, .{ .fail_index = 0 });
    conn.sendq_cap = cap_before;
    conn.overflow_allocator = failing.allocator();
    try std.testing.expectError(error.OutputTooSmall, appendToConn(conn, " line\r\nsecond\r\nsuffix"));
    conn.overflow_allocator = a;
    try std.testing.expectEqualStrings("held", ws.tx_buf[0..ws.tx_len]);
    try appendToConn(conn, " line\r\nsecond\r\nsuffix");
    try std.testing.expectEqualStrings("suffix", ws.tx_buf[0..ws.tx_len]);
    try std.testing.expectEqual(tx_before, t.engine.tls13.app_write_seq);
    try std.testing.expectEqualSlices(u8, held, t.recv_buf.items);
    const tail = try a.dupe(u8, conn.tls_deferred_plain.items);
    defer a.free(tail);
    const charge = conn.tls_deferred_charge;
    try std.testing.expectEqual(try tls_conn.deferredCiphertextCharge(.{ .tls13 = (try t.engine.tls13.captureWithPending()).state }, tail), charge);

    const phase1_wire = try tls3ServerCapture(conn);
    defer a.free(phase1_wire);
    const phase1 = try tls_snapshot.decodeCurrent(phase1_wire);
    try std.testing.expectEqualSlices(u8, tail, phase1.deferred_plain);
    try std.testing.expectEqual(tls_conn.ControlBarrierPhase.userspace_requested_ku_held, phase1.state.barrier_phase);
    const old_plain = try tls3ServerDrain(&fixture, conn);
    defer a.free(old_plain);
    try std.testing.expectEqualStrings("old sealed prefix", old_plain);
    // A retryable allocation failure after reply custody leaves a drainable
    // phase3 rather than pretending that the already admitted request is held.
    var after_reply_fault = std.testing.FailingAllocator.init(a, .{ .fail_index = 0 });
    fixture.server.allocator = after_reply_fault.allocator();
    try fixture.server.progressTlsControl(conn);
    fixture.server.allocator = a;
    try std.testing.expect(!conn.closing);
    try std.testing.expectEqual(tls_conn.ControlBarrierPhase.software_tail_ready, t.control_phase);
    try std.testing.expectEqual(@as(usize, 0), conn.tls_control_charge);
    try std.testing.expectEqualSlices(u8, tail, conn.tls_deferred_plain.items);
    try std.testing.expectEqual(@as(u64, 0), t.engine.tls13.app_write_seq);
    const phase3_wire = try tls3ServerCapture(conn);
    defer a.free(phase3_wire);
    const phase3 = try tls_snapshot.decodeCurrent(phase3_wire);
    try std.testing.expectEqual(tls_conn.ControlBarrierPhase.software_tail_ready, phase3.state.barrier_phase);
    try std.testing.expectEqualSlices(u8, tail, phase3.deferred_plain);
    const reply_plain = try tls3ServerDrain(&fixture, conn);
    defer a.free(reply_plain);
    try std.testing.expectEqual(@as(usize, 0), reply_plain.len);
    try fixture.server.progressTlsControl(conn);
    try std.testing.expectEqual(tls_conn.ControlBarrierPhase.none, t.control_phase);
    try std.testing.expectEqual(@as(usize, 0), conn.tls_deferred_plain.items.len);
    try std.testing.expectEqual(@as(usize, 0), conn.tls_deferred_charge);
    const frames = try tls3ServerDrain(&fixture, conn);
    defer a.free(frames);
    const first = try websocket.decodeFrame(WsState.max_frame, .server_to_client, frames, &.{});
    try std.testing.expectEqualStrings("held line", first.frame.payload);
    const second = try websocket.decodeFrame(WsState.max_frame, .server_to_client, frames[first.consumed..], &.{});
    try std.testing.expectEqualStrings("second", second.frame.payload);
    try std.testing.expectEqual(frames.len, first.consumed + second.consumed);
    try std.testing.expectEqualStrings("suffix", ws.tx_buf[0..ws.tx_len]);
}

test "TLS3: Server software requested KU retains WSS tail through cap OOM and two capture phases" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    for ([_]u16{ 0x1301, 0x1302, 0x1303 }) |suite| try tls3ServerSoftwareBarrier(suite);
}

fn tls3ServerAdoptBarrier(suite: u16) !void {
    defer current_reactor = null;
    const a = std.testing.allocator;
    var fixture = try Tls3ServerFixture.create(suite);
    defer fixture.deinit();
    const original = fixture.connection();
    const original_fd = original.fd;
    const ws = try a.create(WsState);
    defer a.destroy(ws);
    ws.* = .{ .phase = .open };
    original.ws = ws;
    defer original.ws = null;
    try appendSecuredToConn(original, "preserved physical ciphertext");
    var exporter: [32]u8 = undefined;
    try original.tls.?.channelBindingTlsExporter(&exporter);
    try fixture.pair.client.tls13.sendKeyUpdateFragmentsForTest(true, &.{ 4, 1 });
    const request = (try fixture.pair.client.tls13.takePendingSend()).?;
    defer a.free(request);
    try fixture.server.driveTls(fixture.id, original, request);
    try appendToConn(original, "first framed\r\nsecond framed\r\nheld suffix");
    const tail = try a.dupe(u8, original.tls_deferred_plain.items);
    defer a.free(tail);
    const phase1 = try tls3ServerCapture(original);
    defer a.free(phase1);
    const ts1 = try tls_snapshot.decodeCurrent(phase1);
    const successor1 = try createTestServer(a, fixture.server.config);
    defer a.destroy(successor1);
    defer successor1.deinit();
    current_reactor = &successor1.reactors[0];
    const ws1: ws_snapshot.Snapshot = .{ .fd = original_fd, .phase_open = true, .tx = ws.tx_buf[0..ws.tx_len] };
    var client1 = original.session.snapshot();
    client1.fd = original_fd;
    client1.was_secured = true;
    client1.was_websocket = true;

    // A correctly framed but unauthenticated held request is refused before
    // candidate publication, without closing the predecessor's descriptor.
    const bad_request = try a.dupe(u8, ts1.state.pending_recv);
    defer a.free(bad_request);
    bad_request[ts1.state.held_record_len - 1] ^= 1;
    var bad_tls = ts1;
    bad_tls.state.pending_recv = bad_request;
    const before_clock = successor1.mesh_clock;
    try std.testing.expect(!successor1.adoptInheritedClient(client1, bad_tls, ws1, false));
    try std.testing.expectEqual(@as(usize, 0), successor1.reactors[0].clients.len());
    try std.testing.expect(successor1.world.findNick("Tls3Owner") == null);
    try std.testing.expectEqual(before_clock.last_stamp, successor1.mesh_clock.last_stamp);
    try std.testing.expect(successor1.adoptInheritedClient(client1, ts1, ws1, false));
    original.fd = -1; // same live descriptor now belongs to the inert successor
    var first_it = successor1.reactors[0].clients.iterator();
    const first = first_it.next().?;
    const c1 = first.value;
    c1.test_sendq_capture = true;
    try std.testing.expectEqual(original_fd, c1.fd);
    try std.testing.expect(!c1.recv_armed and !c1.send_armed);
    try std.testing.expectEqual(tls_conn.ControlBarrierPhase.userspace_requested_ku_held, c1.tls.?.control_phase);
    try std.testing.expectEqualSlices(u8, tail, c1.tls_deferred_plain.items);
    try std.testing.expectEqualStrings("held suffix", c1.ws.?.tx_buf[0..c1.ws.?.tx_len]);
    try std.testing.expectEqualSlices(u8, &exporter, &c1.tls_exporter_buf);
    const prefix = try tls3ServerDrain(&fixture, c1);
    defer a.free(prefix);
    try std.testing.expectEqualStrings("preserved physical ciphertext", prefix);
    var fault = std.testing.FailingAllocator.init(a, .{ .fail_index = 0 });
    successor1.allocator = fault.allocator();
    defer successor1.allocator = a;
    try successor1.progressTlsControl(c1);
    successor1.allocator = a;
    try std.testing.expectEqual(tls_conn.ControlBarrierPhase.software_tail_ready, c1.tls.?.control_phase);
    const phase3 = try tls3ServerCapture(c1);
    defer a.free(phase3);
    const ts3 = try tls_snapshot.decodeCurrent(phase3);
    const successor2 = try createTestServer(a, fixture.server.config);
    defer a.destroy(successor2);
    defer successor2.deinit();
    current_reactor = &successor2.reactors[0];
    var client2 = c1.session.snapshot();
    client2.fd = original_fd;
    client2.was_secured = true;
    client2.was_websocket = true;
    const ws2: ws_snapshot.Snapshot = .{ .fd = original_fd, .phase_open = true, .tx = c1.ws.?.tx_buf[0..c1.ws.?.tx_len] };
    try std.testing.expect(successor2.adoptInheritedClient(client2, ts3, ws2, false));
    c1.fd = -1;
    var second_it = successor2.reactors[0].clients.iterator();
    const second = second_it.next().?;
    const c2 = second.value;
    c2.test_sendq_capture = true;
    try std.testing.expectEqual(original_fd, c2.fd);
    try std.testing.expect(!c2.recv_armed and !c2.send_armed);
    try std.testing.expectEqualSlices(u8, &exporter, &c2.tls_exporter_buf);
    try std.testing.expectEqualSlices(u8, tail, c2.tls_deferred_plain.items);
    const reply = try tls3ServerDrain(&fixture, c2);
    defer a.free(reply);
    try std.testing.expectEqual(@as(usize, 0), reply.len);
    try successor2.progressTlsControl(c2);
    try std.testing.expectEqual(tls_conn.ControlBarrierPhase.none, c2.tls.?.control_phase);
    const frames = try tls3ServerDrain(&fixture, c2);
    defer a.free(frames);
    const one = try websocket.decodeFrame(WsState.max_frame, .server_to_client, frames, &.{});
    const two = try websocket.decodeFrame(WsState.max_frame, .server_to_client, frames[one.consumed..], &.{});
    try std.testing.expectEqualStrings("first framed", one.frame.payload);
    try std.testing.expectEqualStrings("second framed", two.frame.payload);
    try std.testing.expectEqual(frames.len, one.consumed + two.consumed);
    try std.testing.expectEqualStrings("held suffix", c2.ws.?.tx_buf[0..c2.ws.?.tx_len]);
}

test "TLS3: Server authentic held request and framed tail survive two inert physical adoptions" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    for ([_]u16{ 0x1301, 0x1302, 0x1303 }) |suite| try tls3ServerAdoptBarrier(suite);
}

fn tls3ServerArmedBarrier(suite: u16) !void {
    defer current_reactor = null;
    const a = std.testing.allocator;
    var fixture = try Tls3ServerFixture.create(suite);
    defer fixture.deinit();
    current_reactor = &fixture.server.reactors[0];
    const conn = fixture.connection();
    conn.test_sendq_capture = false;
    const small_buffer: u32 = 1024;
    if (posix.errno(portable_test_system.setsockopt(conn.fd, posix.SOL.SOCKET, posix.SO.SNDBUF, std.mem.asBytes(&small_buffer), @sizeOf(u32))) != .SUCCESS) return error.Unexpected;
    const prefix: [32768]u8 = @splat('p');
    try appendSecuredToConn(conn, &prefix);
    const tx_before = conn.tls.?.engine.tls13.app_write_seq;
    try fixture.server.armSendIfNeeded(conn);
    try std.testing.expect(conn.send_armed);
    const submitted_prefix = try a.dupe(u8, conn.send_buf[conn.send_offset..conn.send_len]);
    defer a.free(submitted_prefix);
    try fixture.pair.client.tls13.sendKeyUpdateFragmentsForTest(true, &.{ 3, 2 });
    const request = (try fixture.pair.client.tls13.takePendingSend()).?;
    defer a.free(request);
    try fixture.server.driveTls(fixture.id, conn, request);
    try appendSecuredToConn(conn, "tail after armed prefix");
    try fixture.server.armSendIfNeeded(conn);
    try std.testing.expect(conn.send_armed);
    try std.testing.expectEqual(tx_before, conn.tls.?.engine.tls13.app_write_seq);
    try std.testing.expectEqualSlices(u8, submitted_prefix, conn.send_buf[conn.send_offset..conn.send_len]);
    try std.testing.expectEqual(tls_conn.ControlBarrierPhase.userspace_requested_ku_held, conn.tls.?.control_phase);

    const Observed = struct {
        handler: CompletionHandler,
        connection: *ConnState,
        partial: bool = false,
        sends: usize = 0,
        pub fn onCompletion(self: *@This(), c: ringlane.Completion) void {
            switch (c) {
                .send => |event| {
                    if (event.token.slot == self.connection.token.slot and event.token.gen == self.connection.token.gen and event.res > 0) {
                        self.partial = self.partial or @as(usize, @intCast(event.res)) < self.connection.send_len - self.connection.send_offset;
                        self.sends += 1;
                    }
                },
                else => {},
            }
            self.handler.onCompletion(c);
        }
    };
    var observed: Observed = .{ .handler = .{ .server = fixture.server }, .connection = conn };
    var completions: [8]reactor_backend.CompletionBuffer = undefined;
    var wire: std.ArrayList(u8) = .empty;
    defer wire.deinit(a);
    var scratch: [1024]u8 = undefined;
    var finished = false;
    for (0..2000) |_| {
        _ = try fixture.server.rx().ring.submit();
        _ = try fixture.server.rx().ring.reapCompletions(&completions, 0, &observed);
        if (observed.handler.err) |err| return err;
        var ready = [_]posix.pollfd{.{ .fd = fixture.peer_fd, .events = posix.POLL.IN, .revents = 0 }};
        if (try posix.poll(&ready, 1) != 0) {
            const n = try readFd(fixture.peer_fd, &scratch);
            if (n == 0) return error.TestUnexpectedResult;
            try wire.appendSlice(a, scratch[0..n]);
        }
        if (!conn.send_armed and sendq.wireBacklog(conn) == 0 and conn.tls_deferred_charge == 0 and
            conn.tls.?.control_phase == .none and wire.items.len == 32768 + 2 * 22 + 27 + "tail after armed prefix".len + 22)
        {
            finished = true;
            break;
        }
    }
    try std.testing.expect(finished);
    try std.testing.expect(observed.sends >= 3);
    // Linux io_uring reports a genuine partial send under this socket pressure.
    // Native kqueue may internally own retries and report the complete request.
    if (comptime builtin.os.tag == .linux) try std.testing.expect(observed.partial);
    const plaintext = try fixture.pair.decode(wire.items);
    defer a.free(plaintext);
    try std.testing.expectEqual(@as(usize, prefix.len + "tail after armed prefix".len), plaintext.len);
    try std.testing.expectEqualSlices(u8, &prefix, plaintext[0..prefix.len]);
    try std.testing.expectEqualStrings("tail after armed prefix", plaintext[prefix.len..]);
    try std.testing.expectEqual(@as(usize, 0), conn.tls_control_charge);
    try std.testing.expect(!conn.closing);
}

test "TLS3: Server armed SEND and real partial CQEs drain old ciphertext before requested KU tail" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    for ([_]u16{ 0x1301, 0x1302, 0x1303 }) |suite| try tls3ServerArmedBarrier(suite);
}

// This fixture uses real TCP kTLS, submits the physical queue to the owner
// ring and lets actual CQEs retire it. The peer proves the control did not
// overtake any previously accepted plaintext, including an overflow suffix.
fn tls3ServerKernelPrefix(suite: u16, kernel_rx: bool, armed: bool, overflow: bool, sq_pressure: bool, clean_close: bool, quiesce_pressure: bool) !void {
    defer current_reactor = null;
    const a = std.testing.allocator;
    var fixture = try Tls3ServerFixture.createTransport(suite, true);
    defer fixture.deinit();
    current_reactor = &fixture.server.reactors[0];
    const conn = fixture.connection();
    const t = conn.tls.?;
    conn.test_sendq_capture = false;
    try t.enableKtlsTx(conn.fd);
    conn.tls_tx_offloaded = true;
    if (kernel_rx) {
        try t.enableKtlsRx(conn.fd);
        conn.tls_rx_offloaded = true;
    }
    var small: i32 = 1024;
    try posix.setsockopt(conn.fd, posix.SOL.SOCKET, posix.SO.SNDBUF, std.mem.asBytes(&small));
    const prefix = try a.alloc(u8, if (overflow) 32768 else 128);
    defer a.free(prefix);
    @memset(prefix, 'k');
    try appendSecuredToConn(conn, prefix);
    const old_secret = t.engine.tls13.server_app_secret;
    if (armed) {
        try fixture.server.armSendIfNeeded(conn);
        try std.testing.expect(conn.send_armed);
    }
    try fixture.pair.client.tls13.sendKeyUpdateFragmentsForTest(true, &.{ 2, 3 });
    const request = (try fixture.pair.client.tls13.takePendingSend()).?;
    defer a.free(request);
    if (kernel_rx) {
        try writeAllFd(fixture.peer_fd, request);
        var ready = [_]posix.pollfd{.{ .fd = conn.fd, .events = posix.POLL.IN, .revents = 0 }};
        if (try posix.poll(&ready, 2000) == 0) return error.TestTimeout;
        const rc = linux.recvfrom(conn.fd, conn.recv_buf[0..].ptr, conn.recv_buf.len, linux.MSG.DONTWAIT, null, null);
        try std.testing.expectEqual(posix.E.IO, posix.errno(rc));
        try std.testing.expectEqual(Server.KtlsRxDrain.survived, try fixture.server.handleKtlsRxControl(fixture.id, conn));
    } else try fixture.server.driveTls(fixture.id, conn, request);
    const prefix_before_append = conn.tls_kernel_prefix_remaining;
    const submitted_before_append = conn.send_submitted_len;
    if (clean_close) {
        try std.testing.expectEqual(Server.DeliveryOutcome.delivered, fixture.server.enqueueDeliveryMaybeClose(fixture.id, "new suffix held behind kernel prefix", true, "completed drain-close"));
        try std.testing.expect(conn.closing);
    } else try appendSecuredToConn(conn, "new suffix held behind kernel prefix");
    try std.testing.expectEqual(prefix_before_append, conn.tls_kernel_prefix_remaining);
    try std.testing.expectEqual(submitted_before_append, conn.send_submitted_len);
    if (armed) {
        // The real armed physical row cannot be silently omitted or exported
        // as quiescent merely because engine metadata itself is copyable.
        var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
        defer pieces.deinit(a);
        var blobs: std.ArrayList([]u8) = .empty;
        defer {
            for (blobs.items) |blob| a.free(blob);
            blobs.deinit(a);
        }
        var fds: [1]i32 = undefined;
        var fd_count: usize = 0;
        var counts = Server.SealCounts{};
        const flags = linux.fcntl(conn.fd, linux.F.GETFD, 0);
        fixture.server.sealShardClients(&fixture.server.reactors[0], &pieces, &blobs, &fds, &fd_count, &counts);
        try std.testing.expectEqual(@as(usize, 1), counts.clients_expected);
        try std.testing.expectEqual(@as(usize, 0), counts.clients);
        try std.testing.expectEqual(@as(usize, 0), fd_count);
        try std.testing.expectEqual(@as(usize, 0), pieces.items.len);
        try std.testing.expectEqual(flags, linux.fcntl(conn.fd, linux.F.GETFD, 0));
    }
    var timeout = linux.kernel_timespec{ .sec = 60, .nsec = 0 };
    if (sq_pressure) {
        var full = false;
        for (0..128) |_| {
            fixture.server.rx().ring.submitTimeout(timer_token, &timeout) catch |err| switch (err) {
                error.SubmissionQueueFull => {
                    full = true;
                    break;
                },
                else => return err,
            };
        }
        try std.testing.expect(full);
        try std.testing.expect(try fixture.server.activatePendingSocketIo());
        try std.testing.expect(!conn.send_armed and !conn.recv_armed);
        try std.testing.expectEqual(@as(usize, 0), conn.send_submitted_len);
        try std.testing.expect(!conn.activation_recv_required);
        try std.testing.expectEqual(prefix_before_append, conn.tls_kernel_prefix_remaining);
        _ = try fixture.server.rx().ring.submit();
        _ = try fixture.server.activatePendingSocketIo();
        try std.testing.expect(conn.send_armed);
        try std.testing.expect(!conn.recv_armed);
    } else {
        try fixture.server.progressTlsControl(conn);
        try fixture.server.armSendIfNeeded(conn);
    }

    if (quiesce_pressure) {
        // Submit into real socket pressure without reading the peer. Let one
        // positive CQE retire its exact span, then cancel the still-owned retry.
        var pressure_handler: CompletionHandler = .{ .server = fixture.server };
        var pressure_cqes: [8]reactor_backend.CompletionBuffer = undefined;
        for (0..2000) |_| {
            _ = try fixture.server.rx().ring.submit();
            _ = try fixture.server.rx().ring.reapCompletions(&pressure_cqes, 0, &pressure_handler);
            if (pressure_handler.err) |err| return err;
            if (conn.tls_kernel_prefix_remaining < prefix_before_append and conn.send_armed) break;
        }
        try std.testing.expect(conn.tls_kernel_prefix_remaining > 0 and conn.tls_kernel_prefix_remaining < prefix_before_append);
        try std.testing.expect(conn.send_armed);
        const remaining = conn.tls_kernel_prefix_remaining;
        try fixture.server.quiesceOwnedSocketIo();
        try std.testing.expect(fixture.server.ownedSocketIoQuiesced());
        try std.testing.expect(!conn.send_armed and !conn.recv_armed and !conn.send_cancel_pending);
        try std.testing.expectEqual(@as(usize, 0), conn.send_submitted_len);
        try std.testing.expectEqual(@as(usize, 0), conn.send_submitted_offset);
        try std.testing.expect(conn.tls_kernel_prefix_remaining <= remaining);
        try std.testing.expectEqual(@as(usize, "new suffix held behind kernel prefix".len), sendq.wireBacklog(conn) - @as(usize, @intCast(conn.tls_kernel_prefix_remaining)));
        const capture = try tls3ServerCapture(conn);
        defer a.free(capture);
        const snapshot = try tls_snapshot.decodeCurrent(capture);
        try std.testing.expectEqual(conn.tls_kernel_prefix_remaining, snapshot.kernel_tx_prefix_remaining);
        // This production failure-resume path rearms the remaining OLD prefix,
        // never a forbidden RECV prerequisite or the accepted new suffix.
        fixture.server.resumeOwnedSocketIo();
        try std.testing.expect(!fixture.server.rx().socket_io_quiescing);
    }

    var handler: CompletionHandler = .{ .server = fixture.server };
    var completions: [8]reactor_backend.CompletionBuffer = undefined;
    var cipher: std.ArrayList(u8) = .empty;
    defer cipher.deinit(a);
    var plain: std.ArrayList(u8) = .empty;
    defer plain.deinit(a);
    var replies: usize = 0;
    var suffix: std.ArrayList(u8) = .empty;
    defer suffix.deinit(a);
    var scratch: [1024]u8 = undefined;
    var complete = false;
    for (0..2000) |_| {
        _ = try fixture.server.rx().ring.submit();
        _ = try fixture.server.rx().ring.reapCompletions(&completions, 0, &handler);
        if (handler.err) |err| return err;
        _ = try fixture.server.activatePendingSocketIo();
        var ready = [_]posix.pollfd{.{ .fd = fixture.peer_fd, .events = posix.POLL.IN, .revents = 0 }};
        if (try posix.poll(&ready, 1) != 0) {
            const n = try readFd(fixture.peer_fd, &scratch);
            if (n == 0) return error.TestUnexpectedResult;
            try cipher.appendSlice(a, scratch[0..n]);
        }
        while (cipher.items.len >= 5) {
            const len = 5 + @as(usize, std.mem.readInt(u16, cipher.items[3..5], .big));
            if (cipher.items.len < len) break;
            switch (try fixture.pair.client.tls13.decryptApp(cipher.items[0..len])) {
                .application_data => |bytes| {
                    defer a.free(bytes);
                    if (replies == 0) try plain.appendSlice(a, bytes) else {
                        try std.testing.expectEqual(@as(usize, 1), replies);
                        try suffix.appendSlice(a, bytes);
                    }
                },
                .control => {
                    // An actual authenticated reply under the old epoch must
                    // follow the whole old plaintext prefix, never just its
                    // first inline portion or the first partial CQE.
                    try std.testing.expectEqualSlices(u8, prefix, plain.items);
                    try std.testing.expectEqual(@as(usize, 0), suffix.items.len);
                    replies += 1;
                },
            }
            std.mem.copyForwards(u8, cipher.items[0 .. cipher.items.len - len], cipher.items[len..]);
            cipher.shrinkRetainingCapacity(cipher.items.len - len);
        }
        if (clean_close and fixture.server.rx().clients.get(fixture.id) == null) {
            complete = plain.items.len == prefix.len and replies == 1 and
                suffix.items.len == "new suffix held behind kernel prefix".len and cipher.items.len == 0;
            break;
        }
        if (!conn.send_armed and sendq.wireBacklog(conn) == 0 and !t.tx_ku_reply_pending and
            t.control_phase == .none and plain.items.len == prefix.len and replies == 1 and
            suffix.items.len == "new suffix held behind kernel prefix".len and cipher.items.len == 0)
        {
            complete = true;
            break;
        }
    }
    if (!complete and fixture.server.rx().clients.get(fixture.id) != null) std.debug.print("kernel prefix suite={x} rx={} armed={} overflow={} plain={} replies={} phase={s} prefix={} credit={} wire={} sendarmed={}\n", .{ suite, kernel_rx, armed, overflow, plain.items.len, replies, @tagName(t.control_phase), conn.tls_kernel_prefix_remaining, conn.tls_control_charge, sendq.wireBacklog(conn), conn.send_armed });
    try std.testing.expect(complete);
    try std.testing.expectEqualStrings("new suffix held behind kernel prefix", suffix.items);
    if (clean_close) {
        try std.testing.expect(fixture.server.rx().clients.get(fixture.id) == null);
        var ready = [_]posix.pollfd{.{ .fd = fixture.peer_fd, .events = posix.POLL.IN, .revents = 0 }};
        if (try posix.poll(&ready, 2000) == 0) return error.TestTimeout;
        try std.testing.expectEqual(@as(usize, 0), try readFd(fixture.peer_fd, &scratch));
        return;
    }
    try tls3ServerAssertKernelTuple(suite, conn.fd, .tx, &fixture.pair.client.tls13.server_app_secret, 1);
    try std.testing.expectEqual(@as(usize, 0), conn.tls_control_charge);
    try std.testing.expectEqualSlices(u8, &fixture.pair.client.tls13.server_app_secret, &t.engine.tls13.server_app_secret);
    try std.testing.expect(!std.mem.eql(u8, &old_secret, &t.engine.tls13.server_app_secret));
    try std.testing.expect(!conn.closing);
    try appendSecuredToConn(conn, "new epoch after kernel prefix");
    try fixture.server.armSendIfNeeded(conn);
    for (0..2000) |_| {
        _ = try fixture.server.rx().ring.submit();
        _ = try fixture.server.rx().ring.reapCompletions(&completions, 0, &handler);
        if (handler.err) |err| return err;
        _ = try fixture.server.activatePendingSocketIo();
        var ready = [_]posix.pollfd{.{ .fd = fixture.peer_fd, .events = posix.POLL.IN, .revents = 0 }};
        if (try posix.poll(&ready, 1) != 0) {
            const n = try readFd(fixture.peer_fd, &scratch);
            if (n == 0) return error.TestUnexpectedResult;
            try cipher.appendSlice(a, scratch[0..n]);
        }
        if (cipher.items.len >= 5 and cipher.items.len == 5 + @as(usize, std.mem.readInt(u16, cipher.items[3..5], .big)) and !conn.send_armed) break;
    }
    const after = try fixture.pair.decode(cipher.items);
    defer a.free(after);
    try std.testing.expectEqualStrings("new epoch after kernel prefix", after);
}

test "TLS3: funded kernel TX old inline and overflow FIFO precede KU under actual CQEs" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    for ([_]u16{ 0x1301, 0x1302, 0x1303 }) |suite| {
        for ([_]bool{ false, true }) |rx| {
            for ([_]bool{ false, true }) |armed| {
                for ([_]bool{ false, true }) |overflow| try tls3ServerKernelPrefix(suite, rx, armed, overflow, false, false, false);
            }
        }
    }
}

