        WsState.max_media_frame,
        .{ .opcode = .binary, .mask_key = .{ 1, 2, 3, 4 } },
        "must-not-route",
        &frame_buf,
    );
    try server.driveWs(.none, &conn, frame);

    try std.testing.expect(conn.closing);
