    try std.testing.expectEqual(websocket.Opcode.close, close.frame.opcode);
    try std.testing.expectEqualSlices(u8, &.{ 0x03, 0xea }, close.frame.payload);
}

test "fragmented binary aggregate over 4 MiB closes 1009 without routing" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const server = try std.testing.allocator.create(Server);
    defer std.testing.allocator.destroy(server);
    server.initInPlace(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const ws = try std.testing.allocator.create(WsState);
    defer std.testing.allocator.destroy(ws);
    ws.* = .{ .phase = .open, .subprotocol = .onyx_irc_media };
    ws.deframer.fragmented = true;
    ws.deframer.msg_binary = true;
    ws.binary_message_active = true;
    ws.binary_message_len = WsState.max_media_frame;
    var conn = ConnState{};
    conn.ws = ws;
    var frame_buf: [64]u8 = undefined;
    const frame = try websocket.encodeFrame(
        WsState.max_media_frame,
        .{ .opcode = .continuation, .mask_key = .{ 1, 2, 3, 4 } },
        "x",
        &frame_buf,
    );
    try server.driveWs(.none, &conn, frame);

    try std.testing.expect(conn.closing);
    const close = try websocket.decodeFrame(125, .server_to_client, conn.send_buf[0..conn.send_len], &.{});
    try std.testing.expectEqual(websocket.Opcode.close, close.frame.opcode);
    try std.testing.expectEqualSlices(u8, &.{ 0x03, 0xf1 }, close.frame.payload);
}

test "single binary frame declaring over 4 MiB closes 1009 from its header" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const server = try std.testing.allocator.create(Server);
    defer std.testing.allocator.destroy(server);
    server.initInPlace(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const ws = try std.testing.allocator.create(WsState);
    defer std.testing.allocator.destroy(ws);
    ws.* = .{ .phase = .open, .subprotocol = .onyx_irc_media };
    var conn = ConnState{};
    conn.ws = ws;

    // A complete payload is unnecessary: RFC 6455's extended-length header is
    // sufficient for Deframer.next() to prove this frame exceeds its ceiling.
    var header: [14]u8 = @splat(0);
    header[0] = 0x82; // FIN + binary
    header[1] = 0xff; // masked + 64-bit length
    std.mem.writeInt(u64, header[2..10], WsState.max_media_frame + 1, .big);
    header[10..14].* = .{ 1, 2, 3, 4 };
    try server.driveWs(.none, &conn, &header);

    try std.testing.expect(conn.closing);
    const close = try websocket.decodeFrame(125, .server_to_client, conn.send_buf[0..conn.send_len], &.{});
    try std.testing.expectEqual(websocket.Opcode.close, close.frame.opcode);
    try std.testing.expectEqualSlices(u8, &.{ 0x03, 0xf1 }, close.frame.payload);
}

test "coalesced Deframer buffer overflow closes 1009 instead of abnormally" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const server = try allocator.create(Server);
    defer allocator.destroy(server);
    server.initInPlace(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
