    const ws = try allocator.create(WsState);
    defer allocator.destroy(ws);
    ws.* = .{ .phase = .open, .subprotocol = .onyx_irc_media };
    var conn = ConnState{};
    conn.ws = ws;

    var first_buf: [64]u8 = undefined;
    const first = try websocket.encodeFrame(WsState.max_media_frame, .{
        .opcode = .binary,
        .mask_key = .{ 1, 2, 3, 4 },
    }, "small", &first_buf);
