test "coalesced feed preserves pending binary opening-frame identity" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const server = try allocator.create(Server);
    defer allocator.destroy(server);
    server.initInPlace(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const ws = try allocator.create(WsState);
    defer allocator.destroy(ws);
    ws.* = .{ .phase = .open, .subprotocol = .onyx_irc_media };
    var conn = ConnState{};
    conn.ws = ws;

    const opening_payload = "open";
    var opening_buf: [64]u8 = undefined;
    const opening = try websocket.encodeFrame(WsState.max_media_frame, .{
        .fin = false,
        .opcode = .binary,
        .mask_key = .{ 1, 2, 3, 4 },
    }, opening_payload, &opening_buf);

    // Fill past Deframer's wire buffer so feed() must drain `opening` into its
    // PendingEvent before driveWs calls next(). The final payload keeps the
    // aggregate exactly at the 4 MiB application-message ceiling.
    const final_payload = try allocator.alloc(u8, WsState.max_media_frame - opening_payload.len);
    defer allocator.free(final_payload);
    @memset(final_payload, 0xa5);
    const final_buf = try allocator.alloc(u8, final_payload.len + 14);
    defer allocator.free(final_buf);
    const final = try websocket.encodeFrame(WsState.max_media_frame, .{
        .opcode = .continuation,
        .mask_key = .{ 5, 6, 7, 8 },
    }, final_payload, final_buf);
    const coalesced = try allocator.alloc(u8, opening.len + final.len);
    defer allocator.free(coalesced);
    @memcpy(coalesced[0..opening.len], opening);
    @memcpy(coalesced[opening.len..], final);
    try std.testing.expect(coalesced.len > ws.deframer.buf.len);

    try server.driveWs(.none, &conn, coalesced);
    try std.testing.expect(!conn.closing);
    try std.testing.expect(!ws.binary_message_active and !ws.deframer.fragmented);
    try std.testing.expectEqual(@as(usize, 0), ws.binary_message_len);
    try std.testing.expectEqualStrings(opening_payload, ws.binary_message_buf[0..opening_payload.len]);
    try std.testing.expectEqual(@as(u8, 0xa5), ws.binary_message_buf[WsState.max_media_frame - 1]);
}

test "coalesced feed preserves pending final-continuation identity" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const server = try allocator.create(Server);
    defer allocator.destroy(server);
    server.initInPlace(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const ws = try allocator.create(WsState);
    defer allocator.destroy(ws);
    ws.* = .{ .phase = .open, .subprotocol = .onyx_irc_media };
    ws.deframer.fragmented = true;
    ws.deframer.msg_binary = true;
    ws.binary_message_active = true;
    const opening_payload = "opening-";
    @memcpy(ws.binary_message_buf[0..opening_payload.len], opening_payload);
    ws.binary_message_len = opening_payload.len;
    var conn = ConnState{};
    conn.ws = ws;

    const tail = "tail";
    var final_buf: [64]u8 = undefined;
    const final = try websocket.encodeFrame(WsState.max_media_frame, .{
        .opcode = .continuation,
        .mask_key = .{ 9, 10, 11, 12 },
    }, tail, &final_buf);

    // A following maximum-size single-frame message forces feed() to queue the
    // final continuation as PendingEvent. queuePending has already cleared the
    // Deframer's fragmented bit, so mutable post-feed state cannot identify it.
    const next_payload = try allocator.alloc(u8, WsState.max_media_frame);
    defer allocator.free(next_payload);
    @memset(next_payload, 0x5a);
    const next_buf = try allocator.alloc(u8, next_payload.len + 14);
    defer allocator.free(next_buf);
    const next = try websocket.encodeFrame(WsState.max_media_frame, .{
        .opcode = .binary,
        .mask_key = .{ 13, 14, 15, 16 },
    }, next_payload, next_buf);
    const coalesced = try allocator.alloc(u8, final.len + next.len);
    defer allocator.free(coalesced);
    @memcpy(coalesced[0..final.len], final);
    @memcpy(coalesced[final.len..], next);
    try std.testing.expect(coalesced.len > ws.deframer.buf.len);

    try server.driveWs(.none, &conn, coalesced);
    try std.testing.expect(!conn.closing);
    try std.testing.expect(!ws.binary_message_active and !ws.deframer.fragmented);
    try std.testing.expectEqual(@as(usize, 0), ws.binary_message_len);
    try std.testing.expectEqualStrings(opening_payload ++ tail, ws.binary_message_buf[0 .. opening_payload.len + tail.len]);
}

