test "threaded server: ws listener rejects a non-upgrade HTTP request" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const alloc = std.testing.allocator;
        var server = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .ws_enabled = true,
            .ws_port = 0,
            .ws_allow_plain = true,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        const ws_port = try server.wsBoundPort();
        const plain_port = try server.boundPort();

        var run = std.atomic.Value(bool).init(true);
        var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
        defer {
            run.store(false, .release);
            if (connectLoopback(plain_port)) |wfd| closeFd(wfd) else |_| {}
            thr.join();
        }

        // A plain GET without the WebSocket headers gets a clean 426 + close, and
        // the server keeps running (a fresh client can still register: the
        // per-connection error firewall held).
        const fd = connectLoopback(ws_port) catch return error.SkipZigTest;
        defer closeFd(fd);
        try writeAllFd(fd, "GET / HTTP/1.1\r\nHost: irc.test\r\n\r\n");
        var rbuf: [1024]u8 = undefined;
        var got: std.ArrayList(u8) = .empty;
        defer got.deinit(alloc);
        var guard: usize = 0;
        while (std.mem.indexOf(u8, got.items, "\r\n\r\n") == null) : (guard += 1) {
            if (guard > 64) return error.TestUnexpectedResult;
            const n = try readFd(fd, &rbuf);
            if (n == 0) break; // server may close right after the refusal
            try got.appendSlice(alloc, rbuf[0..n]);
        }
        try expectContains(got.items, "HTTP/1.1 426 Upgrade Required");
        try expectContains(got.items, "Upgrade: websocket");

        // The reactor survived: a second, well-formed upgrade still works.
        const fd2 = connectLoopback(ws_port) catch return error.SkipZigTest;
        defer closeFd(fd2);
        try writeAllFd(fd2, "GET /irc HTTP/1.1\r\n" ++
            "Host: irc.test\r\n" ++
            "Upgrade: websocket\r\n" ++
            "Connection: Upgrade\r\n" ++
            "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n" ++
            "Sec-WebSocket-Version: 13\r\n\r\n");
        var head2: std.ArrayList(u8) = .empty;
        defer head2.deinit(alloc);
        guard = 0;
        while (std.mem.indexOf(u8, head2.items, "\r\n\r\n") == null) : (guard += 1) {
            if (guard > 64) return error.TestUnexpectedResult;
            const n = try readFd(fd2, &rbuf);
            if (n == 0) return error.TestUnexpectedResult;
            try head2.appendSlice(alloc, rbuf[0..n]);
        }
        try expectContains(head2.items, "HTTP/1.1 101 Switching Protocols");
    } else return error.SkipZigTest;
}

test "threaded server: empty NOTICE never returns ERR_NEEDMOREPARAMS" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    var a = LiveClient{ .fd = fd_a };
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try recvUntil(&a, " 001 A ", 200);
    a.reset();
    // A param-less NOTICE must be silently dropped; the trailing PING proves the
    // server kept processing and that no 461 was interleaved.
    try writeAllFd(fd_a, "NOTICE\r\nPING :tok\r\n");
    try recvUntil(&a, "PONG onyx.local :tok", 200);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), " 461 ") == null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), " 411 ") == null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), " 412 ") == null);

    a.reset();
    try writeAllFd(fd_a, "PRIVMSG\r\n");
    try recvUntil(&a, " 411 A :No recipient given (PRIVMSG)", 200);

    a.reset();
    try writeAllFd(fd_a, "PRIVMSG A\r\n");
    try recvUntil(&a, " 412 A :No text to send", 200);

    a.reset();
    try writeAllFd(fd_a, "NOTICE A\r\nPING :tok2\r\n");
    try recvUntil(&a, "PONG onyx.local :tok2", 200);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), " 411 ") == null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), " 412 ") == null);
}

test "threaded server: control byte reflected into a reply closes only that client" {
    // Regression for the firewall hole where `error.ControlByte` — raised by the
    // outbound reply builders' requireNoControlBytes guard (CWE-93 CRLF/command
    // injection defense) when reflected client data would carry a control byte —
    // escaped the per-connection firewall to `runOnce`, surfacing as a bogus
    // "reactor loop error ControlByte". It must be handled per-connection.
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    // Client A registers.
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    var a = LiveClient{ .fd = fd_a };
    try writeAllFd(fd_a, "NICK ctlA\r\nUSER a 0 * :A\r\n");
    try recvUntil(&a, " 001 ctlA ", 200);

    // A sends an unknown command whose verb carries a control byte (0x01 SOH).
    // The inbound line parser tolerates it (only NUL/CR/LF are rejected), so it
    // reaches the ERR_UNKNOWNCOMMAND builder, which reflects the verb and trips
    // the outbound control-byte guard → DispatchError.ControlByte. The firewall
    // must close ONLY A, never fault the reactor.
    try writeAllFd(fd_a, "WA\x01T\r\n");

    // Post-fix the server closes A (per-client firewall → conn.closing → EOF).
    // Pre-fix the error escaped `handleRecv` before `closeConn` ran, leaving A
    // open indefinitely, so this timed out instead of seeing the reset.
    try std.testing.expectError(error.ConnectionReset, recvUntil(&a, "__never__", 200));

    // The reactor kept serving: a fresh client still registers and gets replies.
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var b = LiveClient{ .fd = fd_b };
    try writeAllFd(fd_b, "NICK ctlB\r\nUSER b 0 * :B\r\n");
    try recvUntil(&b, " 001 ctlB ", 200);
    b.reset();
    try writeAllFd(fd_b, "PING :tok\r\n");
    try recvUntil(&b, "PONG onyx.local :tok", 200);
}

