test "threaded server: re-handshake detaches superseded attachment and same-nick leave preserves sibling" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, multiOperTestConfig(0)) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const identity = try enrollTestMediaIdentity(&server, "admin", "detach-explicit", 0x73);
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_one = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_one);
    const fd_two = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_two);
    var one = LiveClient{ .fd = fd_one };
    var two = LiveClient{ .fd = fd_two };

    try saslPlainPrelude(fd_one, "admin", "onyx");
    try writeAllFd(fd_one, "NICK kain\r\nUSER one 0 * :Kain One\r\n");
    try recvUntil(&one, " 001 kain ", 200);
    try saslPlainPrelude(fd_two, "admin", "onyx");
    try writeAllFd(fd_two, "NICK kain\r\nUSER two 0 * :Kain Two\r\n");
    try recvUntil(&two, " 001 kain ", 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), " 433 ") == null);

    try writeAllFd(fd_one, "JOIN #media\r\n");
    try recvUntil(&one, " 366 kain #media ", 200);
    try writeAllFd(fd_two, "JOIN #media\r\n");
    try recvUntil(&two, " 366 kain #media ", 200);

    try writeAllFd(fd_one, "MEDIA JOIN #media voice\r\n");
    try recvUntil(&one, "MEDIA JOIN #media kain voice", 200);
    one.reset();
    two.reset();
    try writeAllFd(fd_two, "MEDIA JOIN #media voice\r\n");
    try writeAllFd(fd_two, "PING :second-media-join\r\n");
    try recvUntil(&two, "PONG onyx.local :second-media-join", 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "FAIL MEDIA") == null);

    const attachment_one: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x11);
    const attachment_two: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x22);
    const attachment_replacement: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x33);
    var attachment_one_token_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    var attachment_replacement_token_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    const attachment_one_token = try base64url.encode(&attachment_one_token_buf, &attachment_one);
    const attachment_replacement_token = try base64url.encode(&attachment_replacement_token_buf, &attachment_replacement);
    var handshake_one_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    var handshake_two_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    var handshake_replacement_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const handshake_one = try encodeTestMediaHandshake(&handshake_one_buf, attachment_one, identity, "#media");
    const handshake_two = try encodeTestMediaHandshake(&handshake_two_buf, attachment_two, identity, "#media");
    const handshake_replacement = try encodeTestMediaHandshake(&handshake_replacement_buf, attachment_replacement, identity, "#media");
    var command_buf: [512]u8 = undefined;

    one.reset();
    try writeAllFd(fd_one, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{handshake_one}));
    try writeAllFd(fd_one, "PING :handshake-one\r\n");
    try recvUntil(&one, "PONG onyx.local :handshake-one", 200);
    try std.testing.expect(std.mem.indexOf(u8, one.written(), "FAIL MEDIA") == null);
    two.reset();
    try writeAllFd(fd_two, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{handshake_two}));
    try writeAllFd(fd_two, "PING :handshake-two\r\n");
    try recvUntil(&two, "PONG onyx.local :handshake-two", 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "FAIL MEDIA") == null);

    // An enrolled key is not enough: corrupting its transcript signature must
    // neither publish B nor detach the already-bound A. A zero attachment is
    // likewise rejected before any lifecycle mutation.
    var invalid_signature_raw: [Server.media_e2ee_handshake_v2_bytes]u8 = undefined;
    try std.base64.standard.Decoder.decode(&invalid_signature_raw, handshake_replacement);
    invalid_signature_raw[invalid_signature_raw.len - 1] ^= 0x01;
    var invalid_signature_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const invalid_signature = std.base64.standard.Encoder.encode(&invalid_signature_buf, &invalid_signature_raw);
    one.reset();
    two.reset();
    try writeAllFd(fd_one, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{invalid_signature}));
    try recvUntil(&one, "FAIL MEDIA BAD_E2EE_HANDSHAKE", 200);
    try writeAllFd(fd_two, "PING :invalid-signature-barrier\r\n");
    try recvUntil(&two, "PONG onyx.local :invalid-signature-barrier", 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "MEDIA E2EE-DETACH #media kain") == null);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), invalid_signature) == null);

    var zero_attachment_raw = invalid_signature_raw;
    @memset(zero_attachment_raw[1..17], 0);
    var zero_attachment_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const zero_attachment = std.base64.standard.Encoder.encode(&zero_attachment_buf, &zero_attachment_raw);
    one.reset();
    two.reset();
    try writeAllFd(fd_one, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{zero_attachment}));
    try recvUntil(&one, "FAIL MEDIA BAD_E2EE_HANDSHAKE", 200);
    try writeAllFd(fd_two, "PING :zero-attachment-barrier\r\n");
    try recvUntil(&two, "PONG onyx.local :zero-attachment-barrier", 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "MEDIA E2EE-DETACH #media kain") == null);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), zero_attachment) == null);

    // Refreshing the same physical attachment republishes its handshake without
    // retiring it. Replacing A with B must then retire exact A before B appears.
    two.reset();
    try writeAllFd(fd_one, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{handshake_one}));
    var refresh_needle_buf: [512]u8 = undefined;
    const refresh_needle = try std.fmt.bufPrint(&refresh_needle_buf, "MEDIA E2EE-HANDSHAKE #media kain :{s}", .{handshake_one});
    try recvUntil(&two, refresh_needle, 200);
    var detach_one_needle_buf: [128]u8 = undefined;
    const detach_one_needle = try std.fmt.bufPrint(&detach_one_needle_buf, "MEDIA E2EE-DETACH #media kain {s}", .{attachment_one_token});
    try std.testing.expect(std.mem.indexOf(u8, two.written(), detach_one_needle) == null);

    two.reset();
    try writeAllFd(fd_one, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{handshake_replacement}));
    var replacement_needle_buf: [512]u8 = undefined;
    const replacement_needle = try std.fmt.bufPrint(&replacement_needle_buf, "MEDIA E2EE-HANDSHAKE #media kain :{s}", .{handshake_replacement});
    try recvUntil(&two, replacement_needle, 200);
    const detach_index = std.mem.indexOf(u8, two.written(), detach_one_needle) orelse return error.TestUnexpectedResult;
    const replacement_index = std.mem.indexOf(u8, two.written(), replacement_needle) orelse return error.TestUnexpectedResult;
    try std.testing.expect(detach_index < replacement_index);

    // The detach event is server authority. A client cannot synthesize one.
    two.reset();
    try writeAllFd(fd_two, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-DETACH #media {s}\r\n", .{attachment_one_token}));
    try recvUntil(&two, "FAIL MEDIA INVALID_SUBCOMMAND", 200);

    // Leaving one transport must remove only that physical publisher. The
    // nick-level room participant stays live, its exact crypto attachment is
    // retired, and no identity-wide LEAVE leaks.
    one.reset();
    two.reset();
    try writeAllFd(fd_one, "MEDIA LEAVE #media\r\n");
    var detach_needle_buf: [128]u8 = undefined;
    const detach_needle = try std.fmt.bufPrint(&detach_needle_buf, "MEDIA E2EE-DETACH #media kain {s}", .{attachment_replacement_token});
    try recvUntil(&two, detach_needle, 200);
    try writeAllFd(fd_two, "MEDIA ROSTER #media\r\n");
    try recvUntil(&two, "MEDIA ROSTER #media kain voice", 200);
    try recvUntil(&two, "MEDIA ROSTER-END #media", 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "MEDIA LEAVE #media kain") == null);

    two.reset();
    try writeAllFd(fd_two, "MEDIA SPEAKING #media voice on\r\n");
    try recvUntil(&two, "MEDIA SPEAKING #media kain voice", 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "FAIL MEDIA") == null);

    // The final physical attachment is the identity-wide lifecycle edge.
    one.reset();
    try writeAllFd(fd_two, "MEDIA LEAVE #media\r\n");
    try recvUntil(&one, "MEDIA LEAVE #media kain", 200);
}

test "threaded server: same-nick disconnect detaches crypto attachment before final leave" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, multiOperTestConfig(0)) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const identity = try enrollTestMediaIdentity(&server, "admin", "detach-disconnect", 0x74);
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_one = connectLoopback(port) catch return error.SkipZigTest;
    var one_open = true;
    defer if (one_open) closeFd(fd_one);
    const fd_two = connectLoopback(port) catch return error.SkipZigTest;
    var two_open = true;
    defer if (two_open) closeFd(fd_two);
    const fd_watcher = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_watcher);
    var one = LiveClient{ .fd = fd_one };
    var two = LiveClient{ .fd = fd_two };
    var watcher = LiveClient{ .fd = fd_watcher };

    try saslPlainPrelude(fd_one, "admin", "onyx");
    try writeAllFd(fd_one, "NICK kain\r\nUSER one 0 * :Kain One\r\n");
    try recvUntil(&one, " 001 kain ", 200);
    try saslPlainPrelude(fd_two, "admin", "onyx");
    try writeAllFd(fd_two, "NICK kain\r\nUSER two 0 * :Kain Two\r\n");
    try recvUntil(&two, " 001 kain ", 200);
    try saslPlainPrelude(fd_watcher, "oper", "onyx");
    try writeAllFd(fd_watcher, "NICK Watcher\r\nUSER watcher 0 * :Watcher\r\n");
    try recvUntil(&watcher, " 001 Watcher ", 200);

    try writeAllFd(fd_one, "JOIN #media\r\n");
    try recvUntil(&one, " 366 kain #media ", 200);
    try writeAllFd(fd_two, "JOIN #media\r\n");
    try recvUntil(&two, " 366 kain #media ", 200);
    try writeAllFd(fd_watcher, "JOIN #media\r\n");
    try recvUntil(&watcher, " 366 Watcher #media ", 200);
    try writeAllFd(fd_one, "MEDIA JOIN #media voice\r\n");
    try recvUntil(&one, "MEDIA JOIN #media kain voice", 200);
    try writeAllFd(fd_two, "MEDIA JOIN #media voice\r\n");
    try writeAllFd(fd_two, "PING :disconnect-media-join\r\n");
    try recvUntil(&two, "PONG onyx.local :disconnect-media-join", 200);

    const attachment_one: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x33);
    const attachment_two: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x44);
    var attachment_one_token_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    var attachment_two_token_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    const attachment_one_token = try base64url.encode(&attachment_one_token_buf, &attachment_one);
    const attachment_two_token = try base64url.encode(&attachment_two_token_buf, &attachment_two);
    var handshake_one_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    var handshake_two_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const handshake_one = try encodeTestMediaHandshake(&handshake_one_buf, attachment_one, identity, "#media");
    const handshake_two = try encodeTestMediaHandshake(&handshake_two_buf, attachment_two, identity, "#media");
    var command_buf: [512]u8 = undefined;
    one.reset();
    try writeAllFd(fd_one, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{handshake_one}));
    try writeAllFd(fd_one, "PING :disconnect-handshake-one\r\n");
    try recvUntil(&one, "PONG onyx.local :disconnect-handshake-one", 200);
    two.reset();
    try writeAllFd(fd_two, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{handshake_two}));
    try writeAllFd(fd_two, "PING :disconnect-handshake-two\r\n");
    try recvUntil(&two, "PONG onyx.local :disconnect-handshake-two", 200);

    // Abrupt retirement of the first socket identifies only its crypto
    // attachment; the sibling stays in the call and no nick-wide LEAVE fires.
    two.reset();
    closeFd(fd_one);
    one_open = false;
    var detach_one_buf: [128]u8 = undefined;
    const detach_one = try std.fmt.bufPrint(&detach_one_buf, "MEDIA E2EE-DETACH #media kain {s}", .{attachment_one_token});
    try recvUntil(&two, detach_one, 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "MEDIA LEAVE #media kain") == null);
    try writeAllFd(fd_two, "MEDIA ROSTER #media\r\n");
    try recvUntil(&two, "MEDIA ROSTER #media kain voice", 200);

    // Once the surviving socket disconnects, the observer sees the existing
    // nick-wide LEAVE. There is no attachment detach for the final publisher.
    watcher.reset();
    closeFd(fd_two);
    two_open = false;
    try recvUntil(&watcher, "MEDIA LEAVE #media kain", 200);
    var detach_two_buf: [128]u8 = undefined;
    const detach_two = try std.fmt.bufPrint(&detach_two_buf, "MEDIA E2EE-DETACH #media kain {s}", .{attachment_two_token});
    try std.testing.expect(std.mem.indexOf(u8, watcher.written(), detach_two) == null);
}

test "threaded server: PART and KICK retire physical media before channel membership" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const server = createTestServer(std.testing.allocator, multiOperTestConfig(0)) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer {
        server.deinit();
        std.testing.allocator.destroy(server);
    }
    const identity = try enrollTestMediaIdentity(server, "admin", "membership-retire", 0x75);
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_one = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_one);
    const fd_two = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_two);
    const fd_watcher = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_watcher);
    var one = LiveClient{ .fd = fd_one };
    var two = LiveClient{ .fd = fd_two };
    var watcher = LiveClient{ .fd = fd_watcher };

    try saslPlainPrelude(fd_one, "admin", "onyx");
    try writeAllFd(fd_one, "NICK kain\r\nUSER one 0 * :Kain One\r\n");
    try recvUntil(&one, " 001 kain ", 200);
    try saslPlainPrelude(fd_two, "admin", "onyx");
    try writeAllFd(fd_two, "NICK kain\r\nUSER two 0 * :Kain Two\r\n");
    try recvUntil(&two, " 001 kain ", 200);
    try saslPlainPrelude(fd_watcher, "oper", "onyx");
    try writeAllFd(fd_watcher, "NICK Watcher\r\nUSER watcher 0 * :Watcher\r\n");
    try recvUntil(&watcher, " 001 Watcher ", 200);

    // Self-PART: the first physical attachment detaches while the same-nick
    // sibling remains; the sibling's final PART emits the nick-wide LEAVE.
    try writeAllFd(fd_one, "JOIN #part-media\r\n");
    try recvUntil(&one, " 366 kain #part-media ", 200);
    try writeAllFd(fd_two, "JOIN #part-media\r\n");
    try recvUntil(&two, " 366 kain #part-media ", 200);
    try writeAllFd(fd_watcher, "JOIN #part-media\r\n");
    try recvUntil(&watcher, " 366 Watcher #part-media ", 200);
    try writeAllFd(fd_one, "MEDIA JOIN #part-media voice\r\n");
    try recvUntil(&one, "MEDIA JOIN #part-media kain voice", 200);
    try writeAllFd(fd_two, "MEDIA JOIN #part-media voice\r\nPING :part-media-two\r\n");
    try recvUntil(&two, "PONG onyx.local :part-media-two", 200);

    const part_one_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x51);
    const part_two_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x52);
    var part_one_token_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    const part_one_token = try base64url.encode(&part_one_token_buf, &part_one_attachment);
    var part_one_hs_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    var part_two_hs_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const part_one_hs = try encodeTestMediaHandshake(&part_one_hs_buf, part_one_attachment, identity, "#part-media");
    const part_two_hs = try encodeTestMediaHandshake(&part_two_hs_buf, part_two_attachment, identity, "#part-media");
    try sendTestMediaHandshake(fd_one, &one, "#part-media", part_one_hs, "part-handshake-one");
    try sendTestMediaHandshake(fd_two, &two, "#part-media", part_two_hs, "part-handshake-two");

    two.reset();
    try writeAllFd(fd_one, "PART #part-media :device part\r\n");
    var part_detach_buf: [160]u8 = undefined;
    const part_detach = try std.fmt.bufPrint(&part_detach_buf, "MEDIA E2EE-DETACH #part-media kain {s}", .{part_one_token});
    try recvUntil(&two, part_detach, 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "MEDIA LEAVE #part-media kain") == null);
    watcher.reset();
    try writeAllFd(fd_two, "PART #part-media :last device\r\n");
    try recvUntil(&watcher, "MEDIA LEAVE #part-media kain", 200);

    // KICK with a same-nick survivor retires only the selected physical target.
    try writeAllFd(fd_one, "JOIN #kick-media\r\n");
    try recvUntil(&one, " 366 kain #kick-media ", 200);
    try writeAllFd(fd_two, "JOIN #kick-media\r\n");
    try recvUntil(&two, " 366 kain #kick-media ", 200);
    try writeAllFd(fd_watcher, "JOIN #kick-media\r\n");
    try recvUntil(&watcher, " 366 Watcher #kick-media ", 200);
    try writeAllFd(fd_one, "MODE #kick-media +o Watcher\r\n");
    try recvUntil(&watcher, "MODE #kick-media +o Watcher", 200);
    try writeAllFd(fd_one, "MEDIA JOIN #kick-media voice\r\n");
    try recvUntil(&one, "MEDIA JOIN #kick-media kain voice", 200);
    try writeAllFd(fd_two, "MEDIA JOIN #kick-media voice\r\nPING :kick-media-two\r\n");
    try recvUntil(&two, "PONG onyx.local :kick-media-two", 200);

    const kick_one_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x61);
    const kick_two_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x62);
    var kick_one_token_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    const kick_one_token = try base64url.encode(&kick_one_token_buf, &kick_one_attachment);
    var kick_one_hs_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    var kick_two_hs_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const kick_one_hs = try encodeTestMediaHandshake(&kick_one_hs_buf, kick_one_attachment, identity, "#kick-media");
    const kick_two_hs = try encodeTestMediaHandshake(&kick_two_hs_buf, kick_two_attachment, identity, "#kick-media");
    try sendTestMediaHandshake(fd_one, &one, "#kick-media", kick_one_hs, "kick-handshake-one");
    try sendTestMediaHandshake(fd_two, &two, "#kick-media", kick_two_hs, "kick-handshake-two");

    two.reset();
    try writeAllFd(fd_watcher, "KICK #kick-media kain :device kick\r\n");
    var kick_detach_buf: [160]u8 = undefined;
    const kick_detach = try std.fmt.bufPrint(&kick_detach_buf, "MEDIA E2EE-DETACH #kick-media kain {s}", .{kick_one_token});
    try recvUntil(&two, kick_detach, 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "MEDIA LEAVE #kick-media kain") == null);

    // A separate final-target KICK retains the existing nick-wide LEAVE edge.
    try writeAllFd(fd_one, "JOIN #kick-final\r\n");
    try recvUntil(&one, " 366 kain #kick-final ", 200);
    try writeAllFd(fd_watcher, "JOIN #kick-final\r\n");
    try recvUntil(&watcher, " 366 Watcher #kick-final ", 200);
    try writeAllFd(fd_one, "MODE #kick-final +o Watcher\r\n");
    try recvUntil(&watcher, "MODE #kick-final +o Watcher", 200);
    try writeAllFd(fd_one, "MEDIA JOIN #kick-final voice\r\n");
    try recvUntil(&one, "MEDIA JOIN #kick-final kain voice", 200);
    watcher.reset();
    try writeAllFd(fd_watcher, "KICK #kick-final kain :final kick\r\n");
    try recvUntil(&watcher, "MEDIA LEAVE #kick-final kain", 200);
}

test "threaded server: mid-call NICK retires old media authority before identity mutation" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, multiOperTestConfig(0)) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const identity = try enrollTestMediaIdentity(&server, "admin", "nick-retire", 0x76);
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_one = connectLoopback(port) catch return error.SkipZigTest;
    var one_open = true;
    defer if (one_open) closeFd(fd_one);
    const fd_two = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_two);
    const fd_watcher = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_watcher);
    var one = LiveClient{ .fd = fd_one };
    var two = LiveClient{ .fd = fd_two };
    var watcher = LiveClient{ .fd = fd_watcher };

    try saslPlainPrelude(fd_one, "admin", "onyx");
    try writeAllFd(fd_one, "NICK kain\r\nUSER one 0 * :Kain One\r\n");
    try recvUntil(&one, " 001 kain ", 200);
    try saslPlainPrelude(fd_two, "admin", "onyx");
    try writeAllFd(fd_two, "NICK kain\r\nUSER two 0 * :Kain Two\r\n");
    try recvUntil(&two, " 001 kain ", 200);
    try saslPlainPrelude(fd_watcher, "oper", "onyx");
    try writeAllFd(fd_watcher, "NICK Watcher\r\nUSER watcher 0 * :Watcher\r\n");
    try recvUntil(&watcher, " 001 Watcher ", 200);
    try writeAllFd(fd_one, "JOIN #nick-media\r\n");
    try recvUntil(&one, " 366 kain #nick-media ", 200);
    try writeAllFd(fd_two, "JOIN #nick-media\r\n");
    try recvUntil(&two, " 366 kain #nick-media ", 200);
    try writeAllFd(fd_watcher, "JOIN #nick-media\r\n");
    try recvUntil(&watcher, " 366 Watcher #nick-media ", 200);
    try writeAllFd(fd_one, "MEDIA JOIN #nick-media voice\r\n");
    try recvUntil(&one, "MEDIA JOIN #nick-media kain voice", 200);
    try writeAllFd(fd_two, "MEDIA JOIN #nick-media voice\r\nPING :nick-media-two\r\n");
    try recvUntil(&two, "PONG onyx.local :nick-media-two", 200);

    const attachment_one: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x71);
    const attachment_two: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x72);
    var attachment_one_token_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    const attachment_one_token = try base64url.encode(&attachment_one_token_buf, &attachment_one);
    var handshake_one_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    var handshake_two_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const handshake_one = try encodeTestMediaHandshake(&handshake_one_buf, attachment_one, identity, "#nick-media");
    const handshake_two = try encodeTestMediaHandshake(&handshake_two_buf, attachment_two, identity, "#nick-media");
    try sendTestMediaHandshake(fd_one, &one, "#nick-media", handshake_one, "nick-handshake-one");
    try sendTestMediaHandshake(fd_two, &two, "#nick-media", handshake_two, "nick-handshake-two");

    // NICK first retires the physical old-nick publisher. The independent kain
    // sibling stays live, so peers receive exact attachment retirement, not a
    // nick-wide LEAVE.
    two.reset();
    try writeAllFd(fd_one, "NICK NewKain\r\n");
    var detach_buf: [160]u8 = undefined;
    const detach = try std.fmt.bufPrint(&detach_buf, "MEDIA E2EE-DETACH #nick-media kain {s}", .{attachment_one_token});
    try recvUntil(&two, detach, 200);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), "MEDIA LEAVE #nick-media kain") == null);

    // Old publishing authority is gone under NewKain. Both media membership and
    // the E2EE attachment must be re-established; neither old state is inherited.
    one.reset();
    try writeAllFd(fd_one, "MEDIA SPEAKING #nick-media voice on\r\n");
    try recvUntil(&one, "FAIL MEDIA NOT_PUBLISHING", 200);
    one.reset();
    var command_buf: [768]u8 = undefined;
    try writeAllFd(fd_one, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #nick-media :{s}\r\n", .{handshake_one}));
    try recvUntil(&one, "FAIL MEDIA NOT_IN_CALL", 200);
    try writeAllFd(fd_one, "MEDIA JOIN #nick-media voice\r\n");
    try recvUntil(&one, "MEDIA JOIN #nick-media NewKain voice", 200);
    // The old binding was cleared: only this newly submitted post-JOIN
    // handshake re-establishes attachment authority under NewKain.
    try sendTestMediaHandshake(fd_one, &one, "#nick-media", handshake_one, "new-nick-fresh-handshake");

    // Disconnect after the rename retires only the newly joined NewKain media
    // participant. It must not repeat old kain's attachment detach.
    watcher.reset();
    two.reset();
    closeFd(fd_one);
    one_open = false;
    try recvUntil(&watcher, "MEDIA LEAVE #nick-media NewKain", 200);
    try writeAllFd(fd_two, "PING :post-newnick-disconnect\r\n");
    try recvUntil(&two, "PONG onyx.local :post-newnick-disconnect", 1000);
    try std.testing.expect(std.mem.indexOf(u8, two.written(), detach) == null);
    watcher.reset();
    try writeAllFd(fd_two, "MEDIA LEAVE #nick-media\r\n");
    try recvUntil(&watcher, "MEDIA LEAVE #nick-media kain", 200);
}

test "threaded server: account logout and replacement retire old physical media authority" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var tmp = std.testing.tmpDir(.{});
