    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("bob", "correcthorse", &scratch);

    var cfg = multiOperTestConfig(0);
    cfg.account_services = &services;
    const server = createTestServer(std.testing.allocator, cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer {
        server.deinit();
        std.testing.allocator.destroy(server);
    }
    const admin_identity = try enrollTestMediaIdentity(server, "admin", "account-old", 0x77);
    const bob_identity = try enrollTestMediaIdentity(server, "bob", "account-new", 0x78);
    const port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_logout = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_logout);
    const fd_logout_sibling = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_logout_sibling);
    const fd_switch = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_switch);
    const fd_switch_sibling = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_switch_sibling);
    const fd_watcher = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_watcher);
    var logout_client = LiveClient{ .fd = fd_logout };
    var logout_sibling = LiveClient{ .fd = fd_logout_sibling };
    var switch_client = LiveClient{ .fd = fd_switch };
    var switch_sibling = LiveClient{ .fd = fd_switch_sibling };
    var watcher = LiveClient{ .fd = fd_watcher };

    try saslPlainPrelude(fd_logout, "admin", "onyx");
    try writeAllFd(fd_logout, "NICK kain\r\nUSER logout 0 * :Logout Device\r\n");
    try recvUntil(&logout_client, " 001 kain ", 200);
    try saslPlainPrelude(fd_logout_sibling, "admin", "onyx");
    try writeAllFd(fd_logout_sibling, "NICK kain\r\nUSER sibling 0 * :Logout Sibling\r\n");
    try recvUntil(&logout_sibling, " 001 kain ", 200);
    try saslPlainPrelude(fd_switch, "admin", "onyx");
    try writeAllFd(fd_switch, "NICK Switch\r\nUSER switch 0 * :Switch Device\r\n");
    try recvUntil(&switch_client, " 001 Switch ", 200);
    try saslPlainPrelude(fd_switch_sibling, "admin", "onyx");
    try writeAllFd(fd_switch_sibling, "NICK Switch\r\nUSER sibling 0 * :Switch Sibling\r\n");
    try recvUntil(&switch_sibling, " 001 Switch ", 200);
    try saslPlainPrelude(fd_watcher, "oper", "onyx");
    try writeAllFd(fd_watcher, "NICK Watcher\r\nUSER watcher 0 * :Watcher\r\n");
    try recvUntil(&watcher, " 001 Watcher ", 200);

    // LOGOUT retires only this physical admin attachment while the independent
    // same-nick admin sibling remains live.
    inline for (.{ fd_logout, fd_logout_sibling, fd_watcher }) |fd| try writeAllFd(fd, "JOIN #logout-media\r\n");
    try recvUntil(&logout_client, " 366 kain #logout-media ", 200);
    try recvUntil(&logout_sibling, " 366 kain #logout-media ", 200);
    try recvUntil(&watcher, " 366 Watcher #logout-media ", 200);
    try writeAllFd(fd_logout, "MEDIA JOIN #logout-media voice\r\n");
    try recvUntil(&logout_client, "MEDIA JOIN #logout-media kain voice", 200);
    try writeAllFd(fd_logout_sibling, "MEDIA JOIN #logout-media voice\r\nPING :logout-sibling-join\r\n");
    try recvUntil(&logout_sibling, "PONG onyx.local :logout-sibling-join", 200);
    const logout_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x81);
    const logout_sibling_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x82);
    var logout_token_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    const logout_token = try base64url.encode(&logout_token_buf, &logout_attachment);
    var logout_hs_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    var logout_sibling_hs_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const logout_hs = try encodeTestMediaHandshake(&logout_hs_buf, logout_attachment, admin_identity, "#logout-media");
    const logout_sibling_hs = try encodeTestMediaHandshake(&logout_sibling_hs_buf, logout_sibling_attachment, admin_identity, "#logout-media");
    try sendTestMediaHandshake(fd_logout, &logout_client, "#logout-media", logout_hs, "logout-handshake");
    try sendTestMediaHandshake(fd_logout_sibling, &logout_sibling, "#logout-media", logout_sibling_hs, "logout-sibling-handshake");

    logout_sibling.reset();
    try writeAllFd(fd_logout, "LOGOUT\r\n");
    var logout_detach_buf: [160]u8 = undefined;
    const logout_detach = try std.fmt.bufPrint(&logout_detach_buf, "MEDIA E2EE-DETACH #logout-media kain {s}", .{logout_token});
    try recvUntil(&logout_sibling, logout_detach, 200);
    try std.testing.expect(std.mem.indexOf(u8, logout_sibling.written(), "MEDIA LEAVE #logout-media kain") == null);
    logout_client.reset();
    var command_buf: [768]u8 = undefined;
    try writeAllFd(fd_logout, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #logout-media :{s}\r\n", .{logout_hs}));
    try recvUntil(&logout_client, "FAIL MEDIA AUTH_REQUIRED", 200);
    watcher.reset();
    try writeAllFd(fd_logout_sibling, "MEDIA LEAVE #logout-media\r\n");
    try recvUntil(&watcher, "MEDIA LEAVE #logout-media kain", 200);

    // Failed A->B authentication leaves media untouched; successful replacement
    // retires exact A and requires a fresh JOIN plus B handshake.
    inline for (.{ fd_switch, fd_switch_sibling, fd_watcher }) |fd| try writeAllFd(fd, "JOIN #switch-media\r\n");
    try recvUntil(&switch_client, " 366 Switch #switch-media ", 200);
    try recvUntil(&switch_sibling, " 366 Switch #switch-media ", 200);
    try recvUntil(&watcher, " 366 Watcher #switch-media ", 200);
    try writeAllFd(fd_switch, "MEDIA JOIN #switch-media voice\r\n");
    try recvUntil(&switch_client, "MEDIA JOIN #switch-media Switch voice", 1000);
    try writeAllFd(fd_switch_sibling, "MEDIA JOIN #switch-media voice\r\nPING :switch-sibling-join\r\n");
    try recvUntil(&switch_sibling, "PONG onyx.local :switch-sibling-join", 200);
    const switch_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x91);
    const switch_sibling_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x92);
    const bob_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0x93);
    var switch_token_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    const switch_token = try base64url.encode(&switch_token_buf, &switch_attachment);
    var switch_hs_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    var switch_sibling_hs_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    var bob_hs_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const switch_hs = try encodeTestMediaHandshake(&switch_hs_buf, switch_attachment, admin_identity, "#switch-media");
    const switch_sibling_hs = try encodeTestMediaHandshake(&switch_sibling_hs_buf, switch_sibling_attachment, admin_identity, "#switch-media");
    const bob_hs = try encodeTestMediaHandshake(&bob_hs_buf, bob_attachment, bob_identity, "#switch-media");
    try sendTestMediaHandshake(fd_switch, &switch_client, "#switch-media", switch_hs, "switch-handshake");
    try sendTestMediaHandshake(fd_switch_sibling, &switch_sibling, "#switch-media", switch_sibling_hs, "switch-sibling-handshake");

    switch_sibling.reset();
    try writeAllFd(fd_switch, "IDENTIFY bob wrong-password\r\n");
    try recvUntil(&switch_client, "Invalid account or password", 200);
    try writeAllFd(fd_switch, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #switch-media :{s}\r\n", .{switch_hs}));
    try recvUntil(&switch_sibling, "MEDIA E2EE-HANDSHAKE #switch-media Switch", 200);
    try std.testing.expect(std.mem.indexOf(u8, switch_sibling.written(), "MEDIA E2EE-DETACH #switch-media Switch") == null);

    switch_sibling.reset();
    try writeAllFd(fd_switch, "IDENTIFY bob correcthorse\r\n");
    var switch_detach_buf: [160]u8 = undefined;
    const switch_detach = try std.fmt.bufPrint(&switch_detach_buf, "MEDIA E2EE-DETACH #switch-media Switch {s}", .{switch_token});
    try recvUntil(&switch_sibling, switch_detach, 200);
    try std.testing.expect(std.mem.indexOf(u8, switch_sibling.written(), "MEDIA LEAVE #switch-media Switch") == null);
    switch_client.reset();
    try writeAllFd(fd_switch, try std.fmt.bufPrint(&command_buf, "MEDIA E2EE-HANDSHAKE #switch-media :{s}\r\n", .{bob_hs}));
    try recvUntil(&switch_client, "FAIL MEDIA NOT_IN_CALL", 200);
    try writeAllFd(fd_switch, "MEDIA JOIN #switch-media voice\r\n");
    try writeAllFd(fd_switch, "PING :bob-fresh-join\r\n");
    try recvUntil(&switch_client, "PONG onyx.local :bob-fresh-join", 1000);
    try sendTestMediaHandshake(fd_switch, &switch_client, "#switch-media", bob_hs, "bob-fresh-handshake");

    // A same-account refresh is not an authority transition and must not detach B.
    switch_sibling.reset();
    try writeAllFd(fd_switch, "IDENTIFY bob correcthorse\r\n");
    try recvUntil(&switch_client, "You are now identified as bob", 200);
    try writeAllFd(fd_switch, "PING :same-account-refresh\r\n");
    try recvUntil(&switch_client, "PONG onyx.local :same-account-refresh", 200);
    try std.testing.expect(std.mem.indexOf(u8, switch_sibling.written(), "MEDIA E2EE-DETACH #switch-media Switch") == null);
}

test "threaded server: authenticated call participants relay bounded opaque E2EE signaling" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, multiOperTestConfig(0)) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const Ed25519 = std.crypto.sign.Ed25519;
    const enrolled_kp = try Ed25519.KeyPair.generateDeterministic(@as([Ed25519.KeyPair.seed_length]u8, @splat(0x71)));
    const enrolled_public = enrolled_kp.public_key.toBytes();
    const enrolled_public_hex = std.fmt.bytesToHex(enrolled_public, .lower);
    var identity_transcript_buf: [account_identity.max_transcript_len]u8 = undefined;
    const identity_transcript = account_identity.transcript("admin", "media", enrolled_public, &identity_transcript_buf).?;
    const identity_signature = try enrolled_kp.sign(identity_transcript, null);
    const identity_signature_hex = std.fmt.bytesToHex(identity_signature.toBytes(), .lower);
    var identity_value_buf: [account_identity.max_value_len]u8 = undefined;
    const identity_value = account_identity.claimValue(&enrolled_public_hex, &identity_signature_hex, &identity_value_buf).?;
    const identity_entity = ircx_prop_store.Entity{ .kind = .user, .id = "admin" };
    _ = try server.props.setProp(identity_entity, "identity.key.media", identity_value, .{ .id = "admin", .access = .member });
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    const fd_guest = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_guest);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };
    var guest = LiveClient{ .fd = fd_guest };

    try saslPlainPreludeWithCaps(fd_a, "admin", "onyx", "standard-replies");
    try saslPlainPreludeWithCaps(fd_b, "oper", "onyx", "standard-replies");
    try writeAllFd(fd_guest, "CAP REQ :standard-replies\r\n");
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try writeAllFd(fd_guest, "NICK Guest\r\nUSER guest 0 * :Guest\r\nCAP END\r\n");
    try recvUntil(&a, " 381 A ", 200);
    try recvUntil(&b, " 381 B ", 200);
    try recvUntil(&guest, " 001 Guest ", 200);

    try writeAllFd(fd_a, "JOIN #media\r\nMEDIA JOIN #media voice\r\n");
    try recvUntil(&a, "MEDIA JOIN #media A voice", 200);
    try writeAllFd(fd_b, "JOIN #media\r\nMEDIA JOIN #media voice\r\n");
    try recvUntil(&b, "MEDIA JOIN #media B voice", 200);
    try writeAllFd(fd_guest, "JOIN #media\r\nMEDIA JOIN #media voice\r\n");
    try writeAllFd(fd_guest, "PING :guest-in-call\r\n");
    try recvUntil(&guest, "PONG onyx.local :guest-in-call", 200);

    const wrapped_key = "d3JhcHBlZC1tZWRpYS1ncm91cC1rZXk=";
    var handshake_raw: [Server.media_e2ee_handshake_v2_bytes]u8 = @splat(0x5a);
    handshake_raw[0] = 2;
    @memset(handshake_raw[1..17], 0xa1);
    handshake_raw[17] = 0x04;
    handshake_raw[82] = 0x04;
    @memcpy(handshake_raw[179..211], &enrolled_public);
    var media_transcript_buf: [Server.media_e2ee_handshake_domain.len + client_model.MAX_CHANNEL_NAME_BYTES + 1 + Server.media_e2ee_handshake_unsigned_bytes]u8 = undefined;
    const media_transcript = Server.mediaE2eeHandshakeTranscript("#media", handshake_raw[0..Server.media_e2ee_handshake_unsigned_bytes], &media_transcript_buf).?;
    const media_signature = try enrolled_kp.sign(media_transcript, null);
    const media_signature_bytes = media_signature.toBytes();
    @memcpy(handshake_raw[Server.media_e2ee_handshake_unsigned_bytes..], &media_signature_bytes);
    var handshake_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const handshake_envelope = std.base64.standard.Encoder.encode(&handshake_buf, &handshake_raw);
    const sender_attachment_raw: [Server.media_e2ee_attachment_bytes]u8 = @splat(0xa1);
    const target_attachment_raw: [Server.media_e2ee_attachment_bytes]u8 = @splat(0xb2);
    const mismatched_sender_raw: [Server.media_e2ee_attachment_bytes]u8 = @splat(0xc3);
    var sender_attachment_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    var target_attachment_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    var mismatched_sender_buf: [base64url.encodedLen(Server.media_e2ee_attachment_bytes)]u8 = undefined;
    const sender_attachment = try base64url.encode(&sender_attachment_buf, &sender_attachment_raw);
    const target_attachment = try base64url.encode(&target_attachment_buf, &target_attachment_raw);
    const mismatched_sender = try base64url.encode(&mismatched_sender_buf, &mismatched_sender_raw);

    guest.reset();
    var line_buf: [2048]u8 = undefined;
    try writeAllFd(fd_guest, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{handshake_envelope}) catch return error.OutputTooSmall);
    try recvUntil(&guest, "FAIL MEDIA AUTH_REQUIRED", 200);

    a.reset();
    b.reset();
    try writeAllFd(fd_a, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{handshake_envelope}) catch return error.OutputTooSmall);
    try recvUntil(&a, "MEDIA E2EE-HANDSHAKE #media A :", 200);
    try recvUntil(&b, "MEDIA E2EE-HANDSHAKE #media A :", 200);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), handshake_envelope) != null);

    a.reset();
    b.reset();
    try writeAllFd(fd_a, "MEDIA E2EE-HANDSHAKE #media :not-base64!\r\n");
    try recvUntil(&a, "FAIL MEDIA BAD_E2EE_HANDSHAKE", 200);
    try writeAllFd(fd_b, "PING :bad-handshake\r\n");
    try recvUntil(&b, "PONG onyx.local :bad-handshake", 200);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "not-base64!") == null);

    a.reset();
    handshake_raw[0] = 1;
    const bad_version = std.base64.standard.Encoder.encode(&handshake_buf, &handshake_raw);
    try writeAllFd(fd_a, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{bad_version}) catch return error.OutputTooSmall);
    try recvUntil(&a, "FAIL MEDIA BAD_E2EE_HANDSHAKE", 200);

    a.reset();
    handshake_raw[0] = 2;
    handshake_raw[17] = 0x05;
    const bad_static_prefix = std.base64.standard.Encoder.encode(&handshake_buf, &handshake_raw);
    try writeAllFd(fd_a, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{bad_static_prefix}) catch return error.OutputTooSmall);
    try recvUntil(&a, "FAIL MEDIA BAD_E2EE_HANDSHAKE", 200);

    a.reset();
    handshake_raw[17] = 0x04;
    handshake_raw[82] = 0x05;
    const bad_ephemeral_prefix = std.base64.standard.Encoder.encode(&handshake_buf, &handshake_raw);
    try writeAllFd(fd_a, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{bad_ephemeral_prefix}) catch return error.OutputTooSmall);
    try recvUntil(&a, "FAIL MEDIA BAD_E2EE_HANDSHAKE", 200);

    a.reset();
    handshake_raw[82] = 0x04;
    var short_handshake_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes - 1)]u8 = undefined;
    const short_handshake = std.base64.standard.Encoder.encode(&short_handshake_buf, handshake_raw[0 .. handshake_raw.len - 1]);
    try writeAllFd(fd_a, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{short_handshake}) catch return error.OutputTooSmall);
    try recvUntil(&a, "FAIL MEDIA BAD_E2EE_HANDSHAKE", 200);

    a.reset();
    const unregistered_kp = try Ed25519.KeyPair.generateDeterministic(@as([Ed25519.KeyPair.seed_length]u8, @splat(0x72)));
    const unregistered_public = unregistered_kp.public_key.toBytes();
    @memcpy(handshake_raw[179..211], &unregistered_public);
    const unregistered_handshake = std.base64.standard.Encoder.encode(&handshake_buf, &handshake_raw);
    try writeAllFd(fd_a, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-HANDSHAKE #media :{s}\r\n", .{unregistered_handshake}) catch return error.OutputTooSmall);
    try recvUntil(&a, "FAIL MEDIA UNENROLLED_E2EE_IDENTITY", 200);

    a.reset();
    b.reset();
    try writeAllFd(fd_a, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-GROUPKEY #media {s} B {s} 7 :{s}\r\n", .{
        sender_attachment,
        target_attachment,
        wrapped_key,
    }) catch return error.OutputTooSmall);
    var expected_groupkey_buf: [256]u8 = undefined;
    const expected_groupkey = std.fmt.bufPrint(&expected_groupkey_buf, "MEDIA E2EE-GROUPKEY #media A {s} B {s} 7 :", .{
        sender_attachment,
        target_attachment,
    }) catch return error.OutputTooSmall;
    try recvUntil(&b, expected_groupkey, 200);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), wrapped_key) != null);

    a.reset();
    try writeAllFd(fd_a, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-GROUPKEY #media {s} B {s} 7 :{s}\r\n", .{
        mismatched_sender,
        target_attachment,
        wrapped_key,
    }) catch return error.OutputTooSmall);
    try recvUntil(&a, "FAIL MEDIA BAD_E2EE_SENDER", 200);

    a.reset();
    try writeAllFd(fd_a, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-GROUPKEY #media {s} Missing {s} 7 :{s}\r\n", .{
        sender_attachment,
        target_attachment,
        wrapped_key,
    }) catch return error.OutputTooSmall);
    try recvUntil(&a, "FAIL MEDIA BAD_E2EE_TARGET", 200);

    a.reset();
    try writeAllFd(fd_a, std.fmt.bufPrint(&line_buf, "MEDIA E2EE-GROUPKEY #media {s} B {s} 007 :{s}\r\n", .{
        sender_attachment,
        target_attachment,
        wrapped_key,
    }) catch return error.OutputTooSmall);
    try recvUntil(&a, "FAIL MEDIA BAD_E2EE_GROUPKEY", 200);
}

test "WS media admission binds a valid participant MAC to its own stream and active kind" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;

    const server = try std.testing.allocator.create(Server);
    defer std.testing.allocator.destroy(server);
    server.initInPlace(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_port = 0,
        .num_shards = 2,
        .ws_media_relay = true,
        .ws_media_require_mac = true,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    server.fabric = reactor_fabric.ReactorFabric.init(server.allocator, server.reactors.len) catch |err| switch (err) {
        error.ReactorWakeUnsupported => return error.SkipZigTest,
        else => return err,
    };
    current_reactor = &server.reactors[0];

    const sender_id = try addTestLocalClient(server, "Alice", "alice");
    const receiver_id = try addTestLocalClient(server, "Bob", "bob");
    current_reactor = &server.reactors[1];
    const custom_id = try addTestLocalClient(server, "Custom", "custom");
    const text_id = try addTestLocalClient(server, "TextOnly", "text-only");
    const handshake_id = try addTestLocalClient(server, "Handshaking", "handshaking");
    current_reactor = &server.reactors[0];
    const sender = server.connFor(sender_id).?;
    const receiver = server.connFor(receiver_id).?;
    const custom = server.connFor(custom_id).?;
    const text_only = server.connFor(text_id).?;
    const handshaking = server.connFor(handshake_id).?;
    sender.session.registration.registered = true;
    receiver.session.registration.registered = true;
    custom.session.registration.registered = true;
    text_only.session.registration.registered = true;
    handshaking.session.registration.registered = true;
    // Synthetic recipients have no live fd. Keep their send arms set so the
    // delivery tests observe queued bytes without submitting invalid test I/O.
    receiver.send_armed = true;
    custom.send_armed = true;

    const sender_ws = try std.testing.allocator.create(WsState);
    sender_ws.* = .{ .phase = .open, .subprotocol = .onyx_irc_media };
    sender.ws = sender_ws;
    const receiver_ws = try std.testing.allocator.create(WsState);
    receiver_ws.* = .{ .phase = .open };
    receiver.ws = receiver_ws;
    const custom_ws = try std.testing.allocator.create(WsState);
    custom_ws.* = .{ .phase = .open, .subprotocol = .onyx_irc_media };
    custom.ws = custom_ws;
    const text_ws = try std.testing.allocator.create(WsState);
    text_ws.* = .{ .phase = .open, .subprotocol = .ircv3_text };
    text_only.ws = text_ws;
    const handshake_ws = try std.testing.allocator.create(WsState);
    handshake_ws.* = .{ .phase = .handshake };
    handshaking.ws = handshake_ws;

    try server.world.restoreMember("#ws-media", worldIdFromClient(sender_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#ws-media", worldIdFromClient(receiver_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#ws-media", worldIdFromClient(custom_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#ws-media", worldIdFromClient(text_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#ws-media", worldIdFromClient(handshake_id), world_model.MemberModes.empty());
    _ = try server.addMediaPhysicalAttachment(sender_id, "#ws-media", "Alice", .voice);
    _ = try server.addMediaPhysicalAttachment(receiver_id, "#ws-media", "Bob", .voice);
    _ = try server.addMediaPhysicalAttachment(custom_id, "#ws-media", "Custom", .voice);
    _ = try server.addMediaPhysicalAttachment(text_id, "#ws-media", "TextOnly", .voice);
    _ = try server.addMediaPhysicalAttachment(handshake_id, "#ws-media", "Handshaking", .voice);
    try server.media_rooms.join("#ws-media", "Alice", .voice);
    try server.media_rooms.join("#ws-media", "Bob", .voice);
    try server.media_rooms.join("#ws-media", "Custom", .voice);
    try server.media_rooms.join("#ws-media", "TextOnly", .voice);
    try server.media_rooms.join("#ws-media", "Handshaking", .voice);
    sender.setMediaCall("#ws-media", "Alice");
    receiver.setMediaCall("#ws-media", "Bob");
    custom.setMediaCall("#ws-media", "Custom");
    text_only.setMediaCall("#ws-media", "TextOnly");
    handshaking.setMediaCall("#ws-media", "Handshaking");
    try std.testing.expectEqual(@as(u12, 1), custom_id.shard);
    try std.testing.expect(server.world.isMember("#ws-media", worldIdFromClient(custom_id)));
    try std.testing.expect(server.media_rooms.isParticipant("#ws-media", "Custom"));
    try std.testing.expect(custom_ws.phase == .open and wsAdmitsBinaryApplication(custom_ws));
    const sender_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0xa1);
    sender.bindMediaE2eeAttachment(sender_attachment);

    const expected_stream: u32 = 1_646_215_215;
    try std.testing.expectEqual(expected_stream, Server.browserMediaStreamId("#ws-media", "Alice", "audio"));
    var signed_payload: [Server.media_e2ee_attachment_bytes + 1 + account_identity.signature_len]u8 = @splat(0x5a);
    @memcpy(signed_payload[0..Server.media_e2ee_attachment_bytes], &sender_attachment);
    var frame_buf: [128]u8 = undefined;
    const good_len = try cadence_frame.encode(.{
        .band_id = cadence_frame.MEDIA_BAND_FLOOR,
        .stream_id = expected_stream,
        .sequence = 1,
        .timestamp = 1,
        .keyframe = false,
        .codec = .cadencevox_audio,
        .payload = &signed_payload,
    }, &frame_buf);
    var tagged_buf: [128 + cadence_frame.MAC_TAG_BYTES]u8 = undefined;
    const good = try cadence_frame.appendNativeMediaMac(
        &server.native_stream_key,
        "#ws-media",
        "Alice",
        frame_buf[0..good_len],
        &tagged_buf,
    );
    // Later negative fixtures reuse `tagged_buf`; retain the accepted datagram
    // so fragmented-delivery assertions cannot accidentally exercise the last
    // overwritten negative frame instead.
    var accepted_good_buf: [tagged_buf.len]u8 = undefined;
    @memcpy(accepted_good_buf[0..good.len], good);
    const accepted_good = accepted_good_buf[0..good.len];
    var single_frame_buf: [256]u8 = undefined;
    const single_frame = try websocket.encodeFrame(WsState.max_media_frame, .{
        .opcode = .binary,
        .mask_key = .{ 1, 2, 3, 4 },
    }, accepted_good, &single_frame_buf);
    try server.driveWs(sender_id, sender, single_frame);
    try std.testing.expect(!sender.closing);
    try std.testing.expect(receiver.send_len != 0);
    // Custom is shard-1-owned, so the preframed payload crosses the reactor
    // fabric and becomes visible only when that owner drains it.
    try std.testing.expectEqual(@as(usize, 0), custom.send_len);
    current_reactor = &server.reactors[1];
    try std.testing.expectEqual(@as(usize, 1), server.drainFabricCount());
    current_reactor = &server.reactors[0];
    try std.testing.expect(custom.send_len != 0);
    try std.testing.expectEqual(@as(usize, 0), text_only.send_len);
    try std.testing.expectEqual(@as(usize, 0), handshaking.send_len);
    const delivered = try websocket.decodeFrame(WsState.max_media_frame, .server_to_client, receiver.send_buf[0..receiver.send_len], &.{});
    try std.testing.expectEqual(websocket.Opcode.binary, delivered.frame.opcode);
    try std.testing.expectEqualSlices(u8, accepted_good, delivered.frame.payload);
    const custom_delivered = try websocket.decodeFrame(WsState.max_media_frame, .server_to_client, custom.send_buf[0..custom.send_len], &.{});
    try std.testing.expectEqual(websocket.Opcode.binary, custom_delivered.frame.opcode);
    try std.testing.expectEqualSlices(u8, accepted_good, custom_delivered.frame.payload);

    // Alice can compute a valid Alice MAC over any bytes. A victim-derived
    // stream id must still fail the post-MAC identity binding and never relay.
    resetTestSendQ(receiver);
    const forged_len = try cadence_frame.encode(.{
        .band_id = cadence_frame.MEDIA_BAND_FLOOR,
        .stream_id = 87_157_561,
        .sequence = 2,
        .timestamp = 2,
        .keyframe = false,
        .codec = .cadencevox_audio,
        .payload = &signed_payload,
    }, &frame_buf);
    const forged = try cadence_frame.appendNativeMediaMac(
        &server.native_stream_key,
        "#ws-media",
        "Alice",
        frame_buf[0..forged_len],
        &tagged_buf,
    );
    server.handleWsMediaDatagram(sender_id, sender, forged);
    try std.testing.expectEqual(@as(usize, 0), receiver.send_len);

    // The public stream id and sender MAC are both correct, but the signed
    // payload claims another physical attachment. Reject before relay.
    var wrong_attachment_payload = signed_payload;
    @memset(wrong_attachment_payload[0..Server.media_e2ee_attachment_bytes], 0xb2);
    const wrong_attachment_len = try cadence_frame.encode(.{
        .band_id = cadence_frame.MEDIA_BAND_FLOOR,
        .stream_id = expected_stream,
        .sequence = 3,
        .timestamp = 3,
        .keyframe = false,
        .codec = .cadencevox_audio,
        .payload = &wrong_attachment_payload,
    }, &frame_buf);
    const wrong_attachment = try cadence_frame.appendNativeMediaMac(
        &server.native_stream_key,
        "#ws-media",
        "Alice",
        frame_buf[0..wrong_attachment_len],
        &tagged_buf,
    );
    server.handleWsMediaDatagram(sender_id, sender, wrong_attachment);
    try std.testing.expectEqual(@as(usize, 0), receiver.send_len);

    // The stream id is Alice's, but Alice joined only voice. A validly MACed
    // CadenceVis frame cannot smuggle an unjoined video/screen publishing kind.
    const wrong_kind_len = try cadence_frame.encode(.{
        .band_id = cadence_frame.MEDIA_BAND_FLOOR,
        .stream_id = 3_201_646_558,
        .sequence = 4,
        .timestamp = 4,
        .keyframe = true,
        .codec = .cadencevis_video,
        .payload = &signed_payload,
    }, &frame_buf);
    const wrong_kind = try cadence_frame.appendNativeMediaMac(
        &server.native_stream_key,
        "#ws-media",
        "Alice",
        frame_buf[0..wrong_kind_len],
        &tagged_buf,
    );
    server.handleWsMediaDatagram(sender_id, sender, wrong_kind);
    try std.testing.expectEqual(@as(usize, 0), receiver.send_len);

    // RFC 6455 fragmentation is an application-message boundary, not a media
    // datagram boundary. Custom and legacy clients both reassemble byte-exactly;
    // no prefix routes, an interleaved control frame is handled independently,
    // and the final continuation causes exactly one local and one cross-shard
    // delivery while text-only/handshake recipients remain excluded.
    const protocols = [_]?websocket.Subprotocol{ .onyx_irc_media, null };
    for (protocols, 0..) |protocol, protocol_index| {
        resetTestSendQ(sender);
        resetTestSendQ(receiver);
        resetTestSendQ(custom);
        sender_ws.subprotocol = protocol;
        const split = accepted_good.len / 2;
        var opening_buf: [256]u8 = undefined;
        const opening = try websocket.encodeFrame(WsState.max_media_frame, .{
            .fin = false,
            .opcode = .binary,
            .mask_key = .{ 5, 6, 7, 8 },
        }, accepted_good[0..split], &opening_buf);
        try server.driveWs(sender_id, sender, opening);
        try std.testing.expect(!sender.closing);
        try std.testing.expect(sender_ws.binary_message_active);
        try std.testing.expectEqual(split, sender_ws.binary_message_len);
        try std.testing.expectEqual(@as(usize, 0), receiver.send_len);
        current_reactor = &server.reactors[1];
        try std.testing.expectEqual(@as(usize, 0), server.drainFabricCount());
        current_reactor = &server.reactors[0];
        try std.testing.expectEqual(@as(usize, 0), custom.send_len);

        var ping_buf: [32]u8 = undefined;
        const ping = try websocket.encodeFrame(WsState.max_media_frame, .{
            .opcode = .ping,
            .mask_key = .{ 9, 10, 11, 12 },
        }, "p", &ping_buf);
        try server.driveWs(sender_id, sender, ping);
        const pong = try websocket.decodeFrame(125, .server_to_client, sender.send_buf[0..sender.send_len], &.{});
        try std.testing.expectEqual(websocket.Opcode.pong, pong.frame.opcode);
        try std.testing.expectEqualStrings("p", pong.frame.payload);
        resetTestSendQ(sender);

        var final_buf: [256]u8 = undefined;
        const final = try websocket.encodeFrame(WsState.max_media_frame, .{
            .opcode = .continuation,
            .mask_key = .{ 13, 14, 15, @intCast(16 + protocol_index) },
        }, accepted_good[split..], &final_buf);
        try server.driveWs(sender_id, sender, final);
        try std.testing.expect(!sender.closing);
        try std.testing.expect(!sender_ws.binary_message_active);
        try std.testing.expectEqual(@as(usize, 0), sender_ws.binary_message_len);
        try std.testing.expectEqualSlices(u8, accepted_good, sender_ws.binary_message_buf[0..accepted_good.len]);
        try std.testing.expect(receiver.send_len != 0);
        const local_fragmented = try websocket.decodeFrame(WsState.max_media_frame, .server_to_client, receiver.send_buf[0..receiver.send_len], &.{});
        try std.testing.expectEqual(websocket.Opcode.binary, local_fragmented.frame.opcode);
        try std.testing.expectEqualSlices(u8, accepted_good, local_fragmented.frame.payload);
        current_reactor = &server.reactors[1];
        try std.testing.expectEqual(@as(usize, 1), server.drainFabricCount());
        current_reactor = &server.reactors[0];
        const cross_fragmented = try websocket.decodeFrame(WsState.max_media_frame, .server_to_client, custom.send_buf[0..custom.send_len], &.{});
        try std.testing.expectEqual(websocket.Opcode.binary, cross_fragmented.frame.opcode);
        try std.testing.expectEqualSlices(u8, accepted_good, cross_fragmented.frame.payload);
        try std.testing.expectEqual(@as(usize, 0), text_only.send_len);
        try std.testing.expectEqual(@as(usize, 0), handshaking.send_len);
    }

    // Any channel-removal path routed through physical retirement clears both
    // the WS call binding and its E2EE attachment. Old datagrams cannot publish.
    _ = try server.retireMediaPhysicalChannel(sender_id, sender, "#ws-media", "Alice");
    try std.testing.expect(sender.mediaCallChannel() == null);
    try std.testing.expect(!sender.media_e2ee_attachment_bound);
    resetTestSendQ(receiver);
    server.handleWsMediaDatagram(sender_id, sender, accepted_good);
    try std.testing.expectEqual(@as(usize, 0), receiver.send_len);
}

test "GAP-V2 a node identity still delivers the signed media handshake" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;

    const seed = @as([32]u8, @splat(0x5c));
    var ident = try node_identity.fromSeed(seed, "local");
    defer ident.deinit();
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_port = 0,
        .num_shards = 1,
        .node_identity = &ident,
        .ws_media_relay = true,
        .ws_media_require_mac = true,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const sender_id = try addTestLocalClient(&server, "speaker", "speaker");
    const peer_id = try addTestLocalClient(&server, "listener", "listener");
    const sender = server.connFor(sender_id).?;
    const peer = server.connFor(peer_id).?;
    sender.session.registration.registered = true;
    peer.session.registration.registered = true;
    sender.send_armed = true;
    peer.send_armed = true;
    Server.loginSession(sender, "speaker");
    Server.loginSession(peer, "listener");
    const speaker_key = try enrollTestMediaIdentity(&server, "speaker", "primary", 0x31);
    _ = try enrollTestMediaIdentity(&server, "listener", "primary", 0x32);

    try server.world.restoreMember("#media", worldIdFromClient(sender_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#media", worldIdFromClient(peer_id), world_model.MemberModes.empty());
    _ = try server.addMediaPhysicalAttachment(sender_id, "#media", "speaker", .voice);
    _ = try server.addMediaPhysicalAttachment(peer_id, "#media", "listener", .voice);
    try server.media_rooms.join("#media", "speaker", .voice);
    try server.media_rooms.join("#media", "listener", .voice);
    sender.setMediaCall("#media", "speaker");
    peer.setMediaCall("#media", "listener");

    var subscribe = irc_line.LineView{ .raw = "", .command = "EVENT" };
    subscribe.params[0] = "ADD";
    subscribe.params[1] = "MEDIA";
    subscribe.params[2] = "*";
    subscribe.param_count = 3;
    try server.handleEvent(sender, &subscribe);
    try server.handleEvent(peer, &subscribe);

    const attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0xa5);
    var handshake_buf: [std.base64.standard.Encoder.calcSize(Server.media_e2ee_handshake_v2_bytes)]u8 = undefined;
    const handshake = try encodeTestMediaHandshake(&handshake_buf, attachment, speaker_key, "#media");
    var media = irc_line.LineView{ .raw = "", .command = "MEDIA" };
    media.params[0] = "E2EE-HANDSHAKE";
    media.params[1] = "#media";
    media.params[2] = handshake;
    media.param_count = 3;
    resetTestSendQ(sender);
    resetTestSendQ(peer);
    try server.handleMedia(sender_id, sender, &media);
    try std.testing.expect(sender.media_e2ee_attachment_bound);
    const delivered = peer.send_buf[0..peer.send_len];
    try std.testing.expect(std.mem.indexOf(u8, delivered, "E2EE-HANDSHAKE") != null);
    try std.testing.expect(std.mem.indexOf(u8, delivered, handshake) != null);
    try std.testing.expect(std.mem.indexOf(u8, sender.send_buf[0..sender.send_len], "FAIL MEDIA") == null);
    std.debug.print("GAP-V2 branch=node identity delivers the signed media handshake\n", .{});
}

test "GAP-V2 a rejected browser media frame returns numeric 404" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;

    const server = try std.testing.allocator.create(Server);
    defer std.testing.allocator.destroy(server);
    server.initInPlace(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_port = 0,
        .num_shards = 1,
        .ws_media_relay = true,
        .ws_media_require_mac = true,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const sender_id = try addTestLocalClient(server, "browser", "browser");
    const peer_id = try addTestLocalClient(server, "listener", "listener");
    const sender = server.connFor(sender_id).?;
    const peer = server.connFor(peer_id).?;
    sender.session.registration.registered = true;
    peer.session.registration.registered = true;
    peer.send_armed = true;

    const sender_ws = try std.testing.allocator.create(WsState);
    sender_ws.* = .{ .phase = .open, .subprotocol = .onyx_irc_media };
    sender.ws = sender_ws;
    const peer_ws = try std.testing.allocator.create(WsState);
    peer_ws.* = .{ .phase = .open, .subprotocol = .onyx_irc_media };
    peer.ws = peer_ws;

    try server.world.restoreMember("#media", worldIdFromClient(sender_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#media", worldIdFromClient(peer_id), world_model.MemberModes.empty());
    _ = try server.addMediaPhysicalAttachment(sender_id, "#media", "browser", .voice);
    _ = try server.addMediaPhysicalAttachment(peer_id, "#media", "listener", .voice);
    try server.media_rooms.join("#media", "browser", .voice);
    try server.media_rooms.join("#media", "listener", .voice);
    sender.setMediaCall("#media", "browser");
    peer.setMediaCall("#media", "listener");

    // The stock-browser failure: a 27-byte unsigned CadenceVox container.
    var bare_payload = [_]u8{ 1, 2, 3, 4 };
    var bare_buf: [64]u8 = undefined;
    const bare_len = try cadence_frame.encode(.{
        .band_id = cadence_frame.MEDIA_BAND_FLOOR,
        .stream_id = 1,
        .sequence = 1,
        .timestamp = 1,
        .keyframe = false,
        .codec = .cadencevox_audio,
        .payload = &bare_payload,
    }, &bare_buf);
    try std.testing.expectEqual(@as(usize, 27), bare_len);
    var ws_buf: [128]u8 = undefined;
    const bare_frame = try websocket.encodeFrame(WsState.max_media_frame, .{
        .opcode = .binary,
        .mask_key = .{ 1, 2, 3, 4 },
    }, bare_buf[0..bare_len], &ws_buf);
    try server.driveWs(sender_id, sender, bare_frame);
    try std.testing.expect(!sender.closing);
    try std.testing.expectEqual(@as(usize, 0), peer.send_len);
    const first = sender.send_buf[0..sender.send_len];
    try std.testing.expect(std.mem.indexOf(u8, first, " 404 ") != null);
    try std.testing.expect(std.mem.indexOf(u8, first, "Media frame rejected") != null);
    const first_hits = std.mem.count(u8, first, " 404 ");

    // A second bad frame inside the quiet window must not stack another numeric.
    try server.driveWs(sender_id, sender, bare_frame);
    try std.testing.expectEqual(first_hits, std.mem.count(u8, sender.send_buf[0..sender.send_len], " 404 "));
    try std.testing.expectEqual(@as(usize, 0), peer.send_len);

    // A frame that satisfies the same admission path is relayed and adds no 404.
    const sender_attachment: [Server.media_e2ee_attachment_bytes]u8 = @splat(0xa1);
    sender.bindMediaE2eeAttachment(sender_attachment);
    const expected_stream = Server.browserMediaStreamId("#media", "browser", "audio");
    var signed_payload: [Server.media_e2ee_attachment_bytes + 1 + account_identity.signature_len]u8 = @splat(0x5a);
    @memcpy(signed_payload[0..Server.media_e2ee_attachment_bytes], &sender_attachment);
    var good_buf: [160]u8 = undefined;
    const good_len = try cadence_frame.encode(.{
        .band_id = cadence_frame.MEDIA_BAND_FLOOR,
        .stream_id = expected_stream,
        .sequence = 2,
        .timestamp = 2,
        .keyframe = false,
        .codec = .cadencevox_audio,
        .payload = &signed_payload,
    }, &good_buf);
    var tagged_buf: [192]u8 = undefined;
    const good = try cadence_frame.appendNativeMediaMac(
        &server.native_stream_key,
        "#media",
        "browser",
        good_buf[0..good_len],
        &tagged_buf,
    );
    var good_ws_buf: [256]u8 = undefined;
    const good_frame = try websocket.encodeFrame(WsState.max_media_frame, .{
        .opcode = .binary,
        .mask_key = .{ 5, 6, 7, 8 },
    }, good, &good_ws_buf);
    resetTestSendQ(peer);
    try server.driveWs(sender_id, sender, good_frame);
    try std.testing.expect(!sender.closing);
    try std.testing.expectEqual(first_hits, std.mem.count(u8, sender.send_buf[0..sender.send_len], " 404 "));
    try std.testing.expect(peer.send_len != 0);
    const delivered = try websocket.decodeFrame(WsState.max_media_frame, .server_to_client, peer.send_buf[0..peer.send_len], &.{});
    try std.testing.expectEqual(websocket.Opcode.binary, delivered.frame.opcode);
    try std.testing.expectEqualSlices(u8, good, delivered.frame.payload);
    std.debug.print("GAP-V2 branch=a rejected browser frame returns numeric 404 and is not relayed\n", .{});
}

test "GAP-V2 TURN is cut and allocates no relay" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const id = try addTestLocalClient(&server, "alice", null);
    const conn = server.connFor(id).?;
    var line = irc_line.LineView{ .raw = "", .command = "MEDIA" };
    line.params[0] = "TURN";
    line.params[1] = "#media";
    line.params[2] = "secret-must-not-echo";
    line.param_count = 3;
    conn.send_len = 0;
    try server.handleMedia(id, conn, &line);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL MEDIA TURN_CUT");
    try expectContains(conn.send_buf[0..conn.send_len], "TURN relay is not offered");
    try std.testing.expect(std.mem.indexOf(u8, conn.send_buf[0..conn.send_len], "secret-must-not-echo") == null);
    try std.testing.expect(std.mem.indexOf(u8, conn.send_buf[0..conn.send_len], "allocated") == null);
    line.param_count = 1;
    conn.send_len = 0;
    try server.handleMedia(id, conn, &line);
    try expectContains(conn.send_buf[0..conn.send_len], "FAIL MEDIA TURN_CUT");
    std.debug.print("GAP-V2 branch=TURN is cut and MEDIA TURN allocates nothing\n", .{});
}

test "MEDIA WS OFFER suppresses unroutable NATIVE/TRANSPORT; non-WS still gets UDP candidates" {
    // Browser WS media is MACKEY + binary Cadence (E2EE ciphertext). OFFER must
    // not advertise loopback NATIVE/TRANSPORT candidates that the browser cannot
    // use, and must not seat the WS client on the native↔WebRTC bridge.
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;

    const server = try std.testing.allocator.create(Server);
    defer std.testing.allocator.destroy(server);
    server.initInPlace(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_port = 0,
        .media_enabled = true,
        .media_host = "127.0.0.1",
        .ws_media_relay = true,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    server.start();
    if (server.media_plane.port == 0 or server.native_media.port == 0) return error.SkipZigTest;
    current_reactor = &server.reactors[0];

    const ws_id = try addTestLocalClient(server, "Browser", "browser");
    const native_id = try addTestLocalClient(server, "Desktop", "desktop");
    const ws_conn = server.connFor(ws_id).?;
    const native_conn = server.connFor(native_id).?;
    ws_conn.session.registration.registered = true;
    native_conn.session.registration.registered = true;
    ws_conn.send_armed = true;
    native_conn.send_armed = true;

    const ws_state = try std.testing.allocator.create(WsState);
    ws_state.* = .{ .phase = .open, .subprotocol = .onyx_irc_media };
    ws_conn.ws = ws_state;

    try server.world.restoreMember("#ws-offer", worldIdFromClient(ws_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#ws-offer", worldIdFromClient(native_id), world_model.MemberModes.empty());
    try server.media_rooms.join("#ws-offer", "Browser", .voice);
    try server.media_rooms.join("#ws-offer", "Desktop", .voice);

    // WS browser OFFER without transport=webrtc: no TRANSPORT, no NATIVE, no bridge seat.
    resetTestSendQ(ws_conn);
    try server.mediaOffer(ws_id, ws_conn, "#ws-offer", "cadencevox", &.{});
    const ws_plain = ws_conn.send_buf[0..ws_conn.send_len];
    try std.testing.expect(std.mem.indexOf(u8, ws_plain, "OFFER-ACK") != null);
    try std.testing.expect(std.mem.indexOf(u8, ws_plain, " MEDIA TRANSPORT ") == null);
    try std.testing.expect(std.mem.indexOf(u8, ws_plain, " MEDIA NATIVE ") == null);
    {
        lockSpin(&server.media_bridges_mu);
        defer server.media_bridges_mu.unlock();
        try std.testing.expect(server.media_bridges.getPtr("#ws-offer") == null);
    }

    // Explicit transport=webrtc with loopback media_host is still suppressed
    // (unroutable from a remote browser).
    resetTestSendQ(ws_conn);
    try server.mediaOffer(ws_id, ws_conn, "#ws-offer", "cadencevox", &.{"transport=webrtc"});
    const ws_webrtc = ws_conn.send_buf[0..ws_conn.send_len];
    try std.testing.expect(std.mem.indexOf(u8, ws_webrtc, " MEDIA TRANSPORT ") == null);
    try std.testing.expect(std.mem.indexOf(u8, ws_webrtc, " MEDIA NATIVE ") == null);

    // Non-WS native client still receives TRANSPORT + NATIVE and is bridge-registered.
    resetTestSendQ(native_conn);
    try server.mediaOffer(native_id, native_conn, "#ws-offer", "cadencevox", &.{});
    const native_out = native_conn.send_buf[0..native_conn.send_len];
    try std.testing.expect(std.mem.indexOf(u8, native_out, " MEDIA TRANSPORT ") != null);
    try std.testing.expect(std.mem.indexOf(u8, native_out, " MEDIA NATIVE ") != null);
    {
        lockSpin(&server.media_bridges_mu);
        defer server.media_bridges_mu.unlock();
        const br = server.media_bridges.getPtr("#ws-offer");
        try std.testing.expect(br != null);
        try std.testing.expectEqual(@as(usize, 1), br.?.count());
    }
}

test "threaded server: MEDIA OFFER RFC 8122 DTLS signaling (fingerprint/setup vs legacy srtp)" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var cfg = multiOperTestConfig(0);
    cfg.media_enabled = true;
    cfg.media_dtls_srtp = true; // opt-in DTLS-SRTP keying on
    const server = try std.testing.allocator.create(Server);
    defer std.testing.allocator.destroy(server);
    server.initInPlace(std.testing.allocator, cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    server.start(); // bring up the media plane + DTLS terminator
    // Skip in sandboxes where the media UDP plane cannot bind (no terminator).
    if (server.media_plane.port == 0) return error.SkipZigTest;
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    var a = LiveClient{ .fd = fd_a };
    try saslPlainPrelude(fd_a, "admin", "onyx");
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try recvUntil(&a, " 381 A ", 200);
    try writeAllFd(fd_a, "JOIN #media\r\n");
    try recvUntil(&a, " 366 A #media ", 200);

    // Build a well-formed sha-256 fingerprint token (colon-joined single token).
    var fpbuf: [128]u8 = undefined;
    const fpline = try dtls_fingerprint_mod.format(.sha256, "peer client certificate", &fpbuf);
    const peer_hex = fpline["sha-256 ".len..];

    // (a) OFFER requesting DTLS keying → TRANSPORT carries fingerprint=sha-256 …
    //     + setup=passive and NO srtp= group key.
    a.reset();
    var offer_buf: [256]u8 = undefined;
    const offer = try std.fmt.bufPrint(&offer_buf, "MEDIA OFFER #media cadencevox transport=webrtc fingerprint=sha-256:{s} setup=active\r\n", .{peer_hex});
    try writeAllFd(fd_a, offer);
    try recvUntil(&a, "EVENT A MEDIA TRANSPORT #media", 200);
    // Drain a beat so the whole TRANSPORT line is buffered before we inspect it.
    try recvUntil(&a, "setup=passive", 200);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "fingerprint=sha-256 ") != null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "setup=passive") != null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "srtp=") == null);

    // (b) OFFER WITHOUT a fingerprint (feature on, not requested) → byte-identical
    //     legacy srtp= group-key reply, no fingerprint/setup.
    a.reset();
    try writeAllFd(fd_a, "MEDIA OFFER #media cadencevox transport=webrtc\r\n");
    try recvUntil(&a, "EVENT A MEDIA TRANSPORT #media", 200);
    try recvUntil(&a, "srtp=", 200);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "srtp=") != null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "fingerprint=") == null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "setup=") == null);

    // (e) Malformed fingerprint → FAIL MEDIA BAD_FINGERPRINT, never a trap.
    a.reset();
    try writeAllFd(fd_a, "MEDIA OFFER #media cadencevox transport=webrtc fingerprint=sha-256:00:11:22 setup=active\r\n");
    try recvUntil(&a, "FAIL MEDIA BAD_FINGERPRINT", 200);
}

test "threaded server: MEDIA OFFER with DTLS off is byte-identical + fails closed on a fingerprint request" {
    var cfg = multiOperTestConfig(0);
    cfg.media_enabled = true;
    cfg.media_dtls_srtp = false; // DTLS-SRTP disabled (default)
