test "threaded server: IRCX opt-in gates DATA then permits typed channel delivery" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try recvUntil(&b, " 001 B ", 200);
    try writeAllFd(fd_a, "JOIN #dx\r\n");
    try writeAllFd(fd_b, "JOIN #dx\r\n");
    try recvUntil(&a, " 366 A #dx ", 200);
    try recvUntil(&b, " 366 B #dx ", 200);

    a.reset();
    try writeAllFd(fd_a, "DATA #dx TAG :legacy\r\n");
    try recvUntil(&a, " 421 A DATA :IRCX command requires ISIRCX", 200);

    a.reset();
    try writeAllFd(fd_a, "IRCX\r\n");
    try recvUntil(&a, " 800 A 1 0 ", 200);
    b.reset();
    try writeAllFd(fd_a, "DATA #dx TAG :typed\r\n");
    try recvUntil(&b, ":A!alice@localhost DATA #dx TAG :typed\r\n", 200);
}

test "threaded server: DATA respects moderated channel speech gate" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try recvUntil(&b, " 001 B ", 200);
    try writeAllFd(fd_a, "IRCX\r\n");
    try writeAllFd(fd_b, "IRCX\r\n");
    try recvUntil(&a, " 800 A 1 0 ", 200);
    try recvUntil(&b, " 800 B 1 0 ", 200);
    // Serialize the joins so A is deterministically the first member (and thus
    // channel-op) before B joins — with the sharded reactor pool, writing both
    // JOINs before reading either 366 races on who becomes op.
    try writeAllFd(fd_a, "JOIN #dm\r\n");
    try recvUntil(&a, " 366 A #dm ", 200);
    try writeAllFd(fd_b, "JOIN #dm\r\n");
    try recvUntil(&b, " 366 B #dm ", 200);
    a.reset();
    try writeAllFd(fd_a, "MODE #dm +m\r\n");
    try recvUntil(&a, "MODE #dm +m", 200);

    b.reset();
    try writeAllFd(fd_b, "DATA #dm TAG :blocked\r\n");
    try recvUntil(&b, " 404 B #dm :Cannot send to channel (+m)", 200);
}

test "threaded server: +V NOCOMICDATA refuses non-op DATA with 531" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };

    // A founds #v, opts into IRCX, and sets +V (NOCOMICDATA). Serialized so the
    // mode is committed before B joins/sends.
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try writeAllFd(fd_a, "IRCX\r\n");
    try recvUntil(&a, " 800 A 1 0 ", 200);
    try writeAllFd(fd_a, "JOIN #v\r\n");
    try recvUntil(&a, " 366 A #v ", 200);
    try writeAllFd(fd_a, "MODE #v +V\r\n");
    try recvUntil(&a, "MODE #v +V", 200);

    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&b, " 001 B ", 200);
    try writeAllFd(fd_b, "IRCX\r\n");
    try recvUntil(&b, " 800 B 1 0 ", 200);
    try writeAllFd(fd_b, "JOIN #v\r\n");
    try recvUntil(&b, " 366 B #v ", 200);

    // B (a plain member) is refused DATA with ERR_NOCOMICDATA (531).
    b.reset();
    try writeAllFd(fd_b, "DATA #v TAG :blocked\r\n");
    try recvUntil(&b, " 531 B #v :", 200);

    // A (founder/channel-op) bypasses +V: its DATA reaches B.
    b.reset();
    try writeAllFd(fd_a, "DATA #v TAG :fromop\r\n");
    try recvUntil(&b, "DATA #v TAG :fromop", 200);
}

test "threaded server: +U OPMODERATE routes a muted member's message to ops only" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    const fd_c = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_c);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };
    var c = LiveClient{ .fd = fd_c };

    // A founds #o (founder/op) and makes it +m (moderated) + +U (opmoderate);
    // B and C join as plain, non-voiced members. Serialized so the modes commit
    // before anyone speaks.
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try writeAllFd(fd_a, "JOIN #o\r\n");
    try recvUntil(&a, " 366 A #o ", 200);
    try writeAllFd(fd_a, "MODE #o +m\r\n");
    try recvUntil(&a, "MODE #o +m", 200);
    try writeAllFd(fd_a, "MODE #o +U\r\n");
    try recvUntil(&a, "MODE #o +U", 200);

    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&b, " 001 B ", 200);
    try writeAllFd(fd_b, "JOIN #o\r\n");
    try recvUntil(&b, " 366 B #o ", 200);
    try writeAllFd(fd_c, "NICK C\r\nUSER carol 0 * :Carol\r\n");
    try recvUntil(&c, " 001 C ", 200);
    try writeAllFd(fd_c, "JOIN #o\r\n");
    try recvUntil(&c, " 366 C #o ", 200);

    // B (muted under +m) speaks: instead of a 404, the message is routed to ops
    // only — A (op) receives it, with no error back to B.
    a.reset();
    c.reset();
    try writeAllFd(fd_b, "PRIVMSG #o :muted-attempt\r\n");
    try recvUntil(&a, "PRIVMSG #o :muted-attempt", 200);

    // A (op, may speak) sends a normal message that reaches every member. C
    // receiving THIS but never the earlier routed-to-ops line proves the muted
    // attempt was withheld from non-ops (deterministic ordering, no flaky sleep).
    try writeAllFd(fd_a, "PRIVMSG #o :op-says-hi\r\n");
    try recvUntil(&c, "PRIVMSG #o :op-says-hi", 200);
    try std.testing.expect(std.mem.indexOf(u8, c.written(), "muted-attempt") == null);
}

test "threaded server: +U OPMODERATE held message surfaces a POLICY event to opers" {
    // The live loopback path covers the +U trigger; the two-shard fabric
    // regression below pins the Event Spine fan-out contract independently of
    // SO_REUSEPORT's host-specific accept distribution.
    var server = Server.init(std.testing.allocator, operTestConfig(0)) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };

    // A is a network oper (auto-subscribed to POLICY on SASL elevation) and the
    // founder/op of #o, which it makes +m (moderated) + +U (opmoderate).
    try saslAdminPrelude(fd_a);
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try recvUntil(&a, " 381 A ", 200);
    try writeAllFd(fd_a, "JOIN #o\r\n");
    try recvUntil(&a, " 366 A #o ", 200);
    try writeAllFd(fd_a, "MODE #o +m\r\n");
    try recvUntil(&a, "MODE #o +m", 200);
    try writeAllFd(fd_a, "MODE #o +U\r\n");
    try recvUntil(&a, "MODE #o +U", 200);

    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&b, " 001 B ", 200);
    try writeAllFd(fd_b, "JOIN #o\r\n");
    try recvUntil(&b, " 366 B #o ", 200);

    // B (muted) speaks: besides the raw routed copy, A receives a structured
    // POLICY event naming the channel, sender, and held text.
    a.reset();
    try writeAllFd(fd_b, "PRIVMSG #o :held-here\r\n");
    try recvUntil(&a, "#o held message from B: held-here", 200);
}

test "event spine: +U OPMODERATE POLICY fan-out reaches oper on another shard" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var cfg = operTestConfig(0);
        cfg.num_shards = 2;
        var server = Server.init(std.testing.allocator, cfg) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        if (server.reactors.len < 2) return error.SkipZigTest;
        server.fabric = reactor_fabric.ReactorFabric.init(server.allocator, server.reactors.len) catch |err| switch (err) {
            error.ReactorWakeUnsupported => return error.SkipZigTest,
            else => return err,
        };

        const prev_reactor = current_reactor;
        defer current_reactor = prev_reactor;

        current_reactor = &server.reactors[1];
        const oper_id = try server.rx().clients.alloc(ConnState.init(-1));
        const oper_conn = server.rx().clients.get(oper_id).?;
        oper_conn.token = try tokenFromId(oper_id);
        try oper_conn.session.setNick("RemoteOper");
        try reconcileTestOper(&oper_conn.session, oper_mod.OperPrivileges.full, "netadmin", "Network Admin");
        oper_conn.session.setEventMask(event_spine.CategoryMask.only(.policy));

        current_reactor = &server.reactors[0];
        var muted = ConnState.init(-1);
        try muted.session.setNick("B");
        server.publishModerationHeld("#o", &muted, "held-cross-shard");

        current_reactor = &server.reactors[1];
        server.drainFabric();
        const written = oper_conn.send_buf[0..oper_conn.send_len];
        try expectContains(written, " EVENT RemoteOper ");
        try expectContains(written, "#o held message from B: held-cross-shard");
    } else return error.SkipZigTest;
}

test "broadcast wake batch coalesces M member marks into K distinct shard wakes" {
    // FIX B: a broadcast to M cross-shard members must cost one wake per DISTINCT
    // touched shard (K), not one per member (M). The coalescer's distinct-shard
    // count IS that wake count, so proving it collapses duplicates proves the fix.
    var wb: WakeBatch = .{};
    // A 10-member fan-out landing on shards {0,1,2}: 10 marks, 3 distinct shards.
    const member_shards = [_]u12{ 1, 2, 0, 1, 2, 0, 1, 2, 0, 1 };
    for (member_shards) |s| wb.mark(s);
    try std.testing.expectEqual(@as(usize, 3), wb.distinctCount());

    // A single shard hammered by hundreds of members still costs exactly one wake.
    var single: WakeBatch = .{};
    for (0..300) |_| single.mark(2);
    try std.testing.expectEqual(@as(usize, 1), single.distinctCount());

    // A high shard index must land in a later bitmap word (word-index + bit math).
    var hi: WakeBatch = .{};
    hi.mark(0);
    hi.mark(shard_mod.max_shards - 1);
    try std.testing.expectEqual(@as(usize, 2), hi.distinctCount());
}

test "delivery fanout continues past stale and poisoned members to a later healthy member" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const ids = [_]client_model.ClientId{
        try addTestLocalClient(&server, "FanoutA", null),
        try addTestLocalClient(&server, "FanoutB", null),
        try addTestLocalClient(&server, "FanoutC", null),
    };
    for (ids) |id| _ = try server.world.join("#delivery-isolation", worldIdFromClient(id));

    // Select roles in the channel map's REAL iteration order. This makes both
    // failures precede the healthy recipient regardless of hash-table layout.
    var ordered: [ids.len]client_model.ClientId = undefined;
    var n: usize = 0;
    var members = server.world.memberIterator("#delivery-isolation") orelse return error.TestUnexpectedResult;
    while (members.next()) |member| : (n += 1) ordered[n] = clientIdFromWorld(member.*);
    try std.testing.expectEqual(ids.len, n);

    const stale_id = ordered[0];
    const poisoned_id = ordered[1];
    const healthy_id = ordered[2];
    try std.testing.expect(server.rx().clients.free(stale_id));

    const poisoned = server.connFor(poisoned_id) orelse return error.TestUnexpectedResult;
    poisoned.sendq_cap = 0;
    poisoned.send_armed = true;
    const healthy = server.connFor(healthy_id) orelse return error.TestUnexpectedResult;
    healthy.send_armed = true;

    const line = ":source!u@h PRIVMSG #delivery-isolation :survives\r\n";
    try server.broadcastChannelTagged("#delivery-isolation", .{
        .time_value = "",
        .account = null,
    }, line, null, .ordinary);

    try std.testing.expect(poisoned.delivery_gap.load(.acquire));
    try std.testing.expect(poisoned.delivery_abort_started);
    try std.testing.expectEqualStrings(line, healthy.send_buf[0..healthy.send_len]);
}

test "tagged near-max line fails atomically without retaining its prefix" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const id = try addTestLocalClient(&server, "AtomicTag", null);
    const conn = server.connFor(id) orelse return error.TestUnexpectedResult;
    conn.session.addCap(.message_tags);
    conn.send_armed = true;

    // The body alone fits this SendQ, but `@msgid=... ` + body does not. The old
    // two-enqueue shape retained the prefix before rejecting the body; the one
    // logical-record path must reject without mutating either SendQ tier.
    var body: [default_reply_bytes - 32]u8 = @splat('x');
    body[0] = ':';
    body[body.len - 2] = '\r';
    body[body.len - 1] = '\n';
    conn.sendq_cap = body.len;

    try server.deliverTagged(id, .{
        .time_value = "",
        .account = null,
        .msgid = "0123456789abcdef0123456789abcdef",
    }, &body);
    try std.testing.expect(conn.delivery_gap.load(.acquire));
    try std.testing.expect(conn.delivery_abort_started);
    try std.testing.expectEqual(@as(usize, 0), conn.send_len);
    try std.testing.expectEqual(@as(usize, 0), conn.send_overflow.items.len);
}

test "reusable attachment SendQ pressure retains tagged event without poisoning" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const id = try addTestLocalClient(&server, "Durable", "durable-account");
    const conn = server.connFor(id) orelse return error.TestUnexpectedResult;
    conn.session.addCap(.message_tags);
    conn.send_armed = true; // keep the synthetic fd out of the io_uring arm path
    conn.sendq_cap = 0;

    const line = ":source!u@h PRIVMSG Durable :retained\r\n";
    try server.deliverTagged(id, .{
        .time_value = "",
        .account = null,
        .msgid = "0123456789ABCDEFGHJKMNPQRS",
    }, line);

    try std.testing.expectEqual(@as(usize, 1), server.attachment_delivery_spool.len());
    try std.testing.expectEqual(@as(usize, 0), conn.send_len);
    try std.testing.expect(!conn.delivery_gap.load(.acquire));
    try std.testing.expect(!conn.closing);

    conn.sendq_cap = 4096;
    server.drainAttachmentSpoolForCurrentReactor();
    try std.testing.expectEqual(@as(usize, 0), server.attachment_delivery_spool.len());
    try expectContains(conn.send_buf[0..conn.send_len], "@msgid=0123456789ABCDEFGHJKMNPQRS ");
    try expectContains(conn.send_buf[0..conn.send_len], line);
    try std.testing.expect(!conn.delivery_gap.load(.acquire));
    try std.testing.expect(!conn.closing);
}

