test "threaded server: IDENTIFY brute-force throttle locks after repeated failures" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-login-throttle.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("bob", "correcthorse", &scratch);

    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd);
    var c = LiveClient{ .fd = fd };
    try writeAllFd(fd, "NICK U\r\nUSER u 0 * :U\r\n");
    try recvUntil(&c, " 001 U ", 200);

    // The first wrong-password attempt gets the generic mismatch (throttle not yet
    // engaged) — proving the guard does not reject before any failure. Loopback is
    // IP-exempt, so this exercises the ACCOUNT-scope throttle.
    try writeAllFd(fd, "IDENTIFY bob wrongpass\r\n");
    try recvUntil(&c, "Invalid account or password", 300);
    // Hammer past the lock threshold. Each attempt answers with a 464 (the generic
    // mismatch, or the lockout once armed); the exact crossover beat is fuzzy
    // because the failure score decays continuously, so just drive well past it.
    var i: usize = 0;
    while (i < 8) : (i += 1) {
        c.reset();
        try writeAllFd(fd, "IDENTIFY bob wrongpass\r\n");
        try recvUntil(&c, " 464 ", 300);
    }
    // Now definitively locked: even the CORRECT password is refused before auth,
    // with the retry-after lockout message.
    c.reset();
    try writeAllFd(fd, "IDENTIFY bob correcthorse\r\n");
    try recvUntil(&c, "Too many failed login attempts", 300);
}

test "threaded server: SETPASS changes an account password (verified by re-login)" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-setpass.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("bob", "correcthorse", &scratch);

    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .account_services = &services,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd);
    var c = LiveClient{ .fd = fd };
    try writeAllFd(fd, "NICK B\r\nUSER b 0 * :B\r\n");
    try recvUntil(&c, " 001 B ", 200);
    try writeAllFd(fd, "IDENTIFY bob correcthorse\r\n");
    try recvUntil(&c, "You are now identified as bob", 300);

    // Wrong current password is refused.
    c.reset();
    try writeAllFd(fd, "SETPASS wrongcurrent newpassword99\r\n");
    try recvUntil(&c, "FAIL SETPASS WRONG_PASSWORD", 300);
    // A too-short new password is refused by policy.
    c.reset();
    try writeAllFd(fd, "SETPASS correcthorse short\r\n");
    try recvUntil(&c, "FAIL SETPASS INVALID_PASSWORD", 300);
    // Valid change succeeds.
    c.reset();
    try writeAllFd(fd, "SETPASS correcthorse newpassword99\r\n");
    try recvUntil(&c, "SETPASS: your password has been changed", 300);

    // The change persisted: a fresh connection logs in with the NEW password and
    // the old one no longer works.
    const fd2 = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd2);
    var c2 = LiveClient{ .fd = fd2 };
    try writeAllFd(fd2, "NICK B2\r\nUSER b 0 * :B2\r\n");
    try recvUntil(&c2, " 001 B2 ", 200);
    try writeAllFd(fd2, "IDENTIFY bob correcthorse\r\n");
    try recvUntil(&c2, "Invalid account or password", 300);
    try writeAllFd(fd2, "IDENTIFY bob newpassword99\r\n");
    try recvUntil(&c2, "You are now identified as bob", 300);
}

test "threaded server: SUCCESSOR hands a dropped founder's channel to its successor" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(std.testing.allocator, std.testing.io, tmp.dir, "server-successor.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    var scratch: [1024]u8 = undefined;
    _ = try services.registerAccount("alice", "correcthorse", &scratch);
    _ = try services.registerAccount("bob", "correcthorse", &scratch);
    _ = try services.registerAccount("carol", "correcthorse", &scratch);

    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .account_services = &services }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };

    try writeAllFd(fd_a, "NICK A\r\nUSER a 0 * :A\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try writeAllFd(fd_a, "IDENTIFY alice correcthorse\r\n");
    try recvUntil(&a, "You are now identified as alice", 300);
    // alice founds #ch and designates bob as successor.
    try writeAllFd(fd_a, "CHANNEL REGISTER #ch\r\n");
    try recvUntil(&a, "Channel #ch registered to alice", 300);
    try writeAllFd(fd_a, "SUCCESSOR #ch SET bob\r\n");
    try recvUntil(&a, "#ch successor set to bob", 300);
    a.reset();
    try writeAllFd(fd_a, "SUCCESSOR #ch SHOW\r\n");
    try recvUntil(&a, "#ch successor is bob", 300);

    // alice DROPs her account -> #ch is handed to bob.
    try writeAllFd(fd_a, "DROP alice correcthorse\r\n");
    try recvUntil(&a, "Account alice dropped", 300);

    // bob is now the founder: he can manage #ch's successor (founder-gated), which
    // a non-founder could not.
    try writeAllFd(fd_b, "NICK B\r\nUSER b 0 * :B\r\n");
    try recvUntil(&b, " 001 B ", 200);
    try writeAllFd(fd_b, "IDENTIFY bob correcthorse\r\n");
    try recvUntil(&b, "You are now identified as bob", 300);
    try writeAllFd(fd_b, "SUCCESSOR #ch SET carol\r\n");
    try recvUntil(&b, "#ch successor set to carol", 300);
}

