test "threaded server: WHOIS shows the target's registered case + nick re-case allowed" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };
    // A registers as "Kain" (capital K).
    try writeAllFd(fd_a, "NICK Kain\r\nUSER kain 0 * :Kain\r\n");
    try recvUntil(&a, " 001 Kain ", 200);
    try writeAllFd(fd_b, "NICK bob\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&b, " 001 bob ", 200);
    // B whois-es "kain" (lowercase) — the reply must show the registered case "Kain".
    b.reset();
    try writeAllFd(fd_b, "WHOIS kain\r\n");
    try recvUntil(&b, " 311 bob Kain ", 200); // canonical case, not the typed "kain"
    try recvUntil(&b, " 318 bob Kain ", 200);
    // A re-cases its own nick Kain -> kain: allowed (no 433), broadcast with old prefix.
    a.reset();
    try writeAllFd(fd_a, "NICK kain\r\n");
    try recvUntil(&a, ":Kain!", 200);
    try recvUntil(&a, "NICK :kain", 200);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), " 433 ") == null);
}

test "threaded server: PROP user profile extended keys round-trip and enforce access" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };

    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try recvUntil(&b, " 001 B ", 200);
    try writeAllFd(fd_a, "IRCX\r\n");
    try writeAllFd(fd_b, "IRCX\r\n");
    try recvUntil(&a, " 800 A 1 0 ", 200);
    try recvUntil(&b, " 800 B 1 0 ", 200);

    const cases = [_]struct {
        key: []const u8,
        value: []const u8,
        profile_fragment: []const u8,
    }{
        .{ .key = "URL", .value = "https://example.test/a", .profile_fragment = "url=https://example.test/a" },
        .{ .key = "GENDER", .value = "nonbinary", .profile_fragment = "gender=nonbinary" },
        .{ .key = "PICTURE", .value = "https://example.test/a.png", .profile_fragment = "picture=https://example.test/a.png" },
        .{ .key = "BIO", .value = "Onyx operator", .profile_fragment = "bio=Onyx operator" },
        .{ .key = "EMAIL", .value = "alice@example.test", .profile_fragment = "email=alice@example.test" },
    };

    for (cases) |case| {
        a.reset();
        try writeAllFd(fd_a, "PROP A SET ");
        try writeAllFd(fd_a, case.key);
        try writeAllFd(fd_a, " :");
        try writeAllFd(fd_a, case.value);
        try writeAllFd(fd_a, "\r\n");
        try recvUntil(&a, " 819 A A ", 200);
        try std.testing.expect(std.mem.indexOf(u8, a.written(), case.value) != null);

        a.reset();
        try writeAllFd(fd_a, "PROP A GET ");
        try writeAllFd(fd_a, case.key);
        try writeAllFd(fd_a, "\r\n");
        try recvUntil(&a, " 819 A A ", 200);
        try std.testing.expect(std.mem.indexOf(u8, a.written(), case.value) != null);
    }

    a.reset();
    try writeAllFd(fd_a, "PROP A GET user_profile\r\n");
    try recvUntil(&a, " 818 A A user_profile :", 200);
    try recvUntil(&a, " 819 A A ", 200);
    for (cases) |case| {
        try std.testing.expect(std.mem.indexOf(u8, a.written(), case.profile_fragment) != null);
    }

    var too_long = @as([(ircx_prop_store.user_profile_max_value + 1)]u8, @splat('x'));
    a.reset();
    try writeAllFd(fd_a, "PROP A SET URL :");
    try writeAllFd(fd_a, too_long[0..]);
    try writeAllFd(fd_a, "\r\n");
    try recvUntil(&a, " 913 ", 200);

    b.reset();
    try writeAllFd(fd_b, "PROP A SET URL :https://example.test/b\r\n");
    try recvUntil(&b, " 913 ", 200);

    b.reset();
    try writeAllFd(fd_b, "PROP A SET display :Mallory\r\n");
    try recvUntil(&b, " 913 ", 200);
}

test "threaded server: PROP user MEMBER_OF lists visible channels (WHOIS filter)" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };

    // A joins a public channel and a secret one; both A and B opt into IRCX.
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try writeAllFd(fd_a, "IRCX\r\n");
    try recvUntil(&a, " 800 A 1 0 ", 200);
    try writeAllFd(fd_a, "JOIN #mpub\r\n");
    try recvUntil(&a, " 366 A #mpub ", 200);
    try writeAllFd(fd_a, "JOIN #msec\r\n");
    try recvUntil(&a, " 366 A #msec ", 200);
    try writeAllFd(fd_a, "MODE #msec +s\r\n");
    try recvUntil(&a, "MODE #msec +s", 200);

    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&b, " 001 B ", 200);
    try writeAllFd(fd_b, "IRCX\r\n");
    try recvUntil(&b, " 800 B 1 0 ", 200);

    // Outsider B sees A's public channel but NOT the secret one.
    b.reset();
    try writeAllFd(fd_b, "PROP A GET MEMBER_OF\r\n");
    try recvUntil(&b, " 818 B A MEMBER_OF :", 200);
    try recvUntil(&b, " 819 B A ", 200);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "#mpub") != null);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "#msec") == null);

    // A querying itself sees both.
    a.reset();
    try writeAllFd(fd_a, "PROP A GET MEMBER_OF\r\n");
    try recvUntil(&a, " 818 A A MEMBER_OF :", 200);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "#mpub") != null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "#msec") != null);
}

