    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };

    // A logs into the "admin" services account via SASL.
    try saslAdminPrelude(fd_a);
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try recvUntil(&a, " 900 ", 200); // RPL_LOGGEDIN — A is now account "admin"
    try writeAllFd(fd_a, "IRCX\r\n");
    try recvUntil(&a, " 800 A 1 0 ", 200);

    // B (unauthenticated) opts into IRCX and asks for A's account.
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&b, " 001 B ", 200);
    try writeAllFd(fd_b, "IRCX\r\n");
    try recvUntil(&b, " 800 B 1 0 ", 200);

    b.reset();
    try writeAllFd(fd_b, "PROP A GET ACCOUNT\r\n");
    try recvUntil(&b, " 818 B A ACCOUNT :admin", 200);
    try recvUntil(&b, " 819 B A ", 200);

    // An unauthenticated target yields no ACCOUNT value (provider declines).
    b.reset();
    try writeAllFd(fd_b, "PROP B GET ACCOUNT\r\n");
    try recvUntil(&b, " 819 B B ", 200);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "ACCOUNT :") == null);
}

const PropGeoTestBytes = std.array_list.Managed(u8);

fn propGeoAppendHeader(out: *PropGeoTestBytes, value_type: u8, size: usize) !void {
    const ctrl_type: u8 = if (value_type >= 8) 0 else value_type;
    const ext: ?u8 = if (value_type >= 8) value_type - 7 else null;
    if (size < 29) {
        try out.append((ctrl_type << 5) | @as(u8, @intCast(size)));
        if (ext) |e| try out.append(e);
    } else if (size < 285) {
        try out.append((ctrl_type << 5) | 29);
        if (ext) |e| try out.append(e);
        try out.append(@intCast(size - 29));
    } else if (size < 65821) {
        const n = size - 285;
        try out.append((ctrl_type << 5) | 30);
        if (ext) |e| try out.append(e);
        try out.append(@intCast(n >> 8));
        try out.append(@intCast(n & 0xff));
    } else {
        const n = size - 65821;
        try out.append((ctrl_type << 5) | 31);
        if (ext) |e| try out.append(e);
        try out.append(@intCast((n >> 16) & 0xff));
        try out.append(@intCast((n >> 8) & 0xff));
        try out.append(@intCast(n & 0xff));
    }
}

fn propGeoAppendString(out: *PropGeoTestBytes, bytes: []const u8) !void {
    try propGeoAppendHeader(out, 2, bytes.len);
    try out.appendSlice(bytes);
}

fn propGeoAppendUint(out: *PropGeoTestBytes, value_type: u8, value: u64) !void {
    const max_len: usize = switch (value_type) {
        5 => 2,
        6 => 4,
        9 => 8,
        else => return error.UnsupportedDatabase,
    };
    var tmp = @as([8]u8, @splat(0));
    var value_copy = value;
    var len: usize = 0;
    while (value_copy != 0) : (value_copy >>= 8) len += 1;
    if (len > max_len) return error.InvalidDatabase;

    var i: usize = 0;
    while (i < len) : (i += 1) {
        const shift: u6 = @intCast((len - 1 - i) * 8);
        tmp[i] = @intCast((value >> shift) & 0xff);
    }

    try propGeoAppendHeader(out, value_type, len);
    try out.appendSlice(tmp[0..len]);
}

fn propGeoAppendMapHeader(out: *PropGeoTestBytes, pairs: usize) !void {
    try propGeoAppendHeader(out, 7, pairs);
}

fn propGeoAppendArrayHeader(out: *PropGeoTestBytes, items: usize) !void {
    try propGeoAppendHeader(out, 11, items);
}

fn propGeoAppendNode24(out: *PropGeoTestBytes, left: u32, right: u32) !void {
    try out.append(@intCast((left >> 16) & 0xff));
    try out.append(@intCast((left >> 8) & 0xff));
    try out.append(@intCast(left & 0xff));
    try out.append(@intCast((right >> 16) & 0xff));
    try out.append(@intCast((right >> 8) & 0xff));
    try out.append(@intCast(right & 0xff));
}

fn propGeoAppendMetadata(out: *PropGeoTestBytes, node_count: u32, record_size: u16, ip_version: u16) !void {
    try out.appendSlice("\xab\xcd\xefMaxMind.com");
    try propGeoAppendMapHeader(out, 3);
    try propGeoAppendString(out, "node_count");
    try propGeoAppendUint(out, 6, node_count);
    try propGeoAppendString(out, "record_size");
    try propGeoAppendUint(out, 5, record_size);
    try propGeoAppendString(out, "ip_version");
    try propGeoAppendUint(out, 5, ip_version);
}

fn buildPropGeoTestMmdb(allocator: std.mem.Allocator) ![]u8 {
    var bytes = PropGeoTestBytes.init(allocator);
    defer bytes.deinit();

    const data_separator_len = 16;
    const record_pointer: u32 = 1 + data_separator_len;
    try propGeoAppendNode24(&bytes, record_pointer, record_pointer);
    try bytes.appendNTimes(0, data_separator_len);

    try propGeoAppendMapHeader(&bytes, 5);

    try propGeoAppendString(&bytes, "country");
    try propGeoAppendMapHeader(&bytes, 1);
    try propGeoAppendString(&bytes, "iso_code");
    try propGeoAppendString(&bytes, "ZZ");

    try propGeoAppendString(&bytes, "city");
    try propGeoAppendMapHeader(&bytes, 1);
    try propGeoAppendString(&bytes, "names");
    try propGeoAppendMapHeader(&bytes, 1);
    try propGeoAppendString(&bytes, "en");
    try propGeoAppendString(&bytes, "Testopolis");

    try propGeoAppendString(&bytes, "subdivisions");
    try propGeoAppendArrayHeader(&bytes, 1);
    try propGeoAppendMapHeader(&bytes, 1);
    try propGeoAppendString(&bytes, "names");
    try propGeoAppendMapHeader(&bytes, 1);
    try propGeoAppendString(&bytes, "en");
    try propGeoAppendString(&bytes, "Testregion");

    try propGeoAppendString(&bytes, "autonomous_system_number");
    try propGeoAppendUint(&bytes, 6, 64512);

    try propGeoAppendString(&bytes, "autonomous_system_organization");
    try propGeoAppendString(&bytes, "Example Net");

    try propGeoAppendMetadata(&bytes, 1, 24, 4);
    return allocator.dupe(u8, bytes.items);
}

fn installPropGeoTestDatabases(server: *LinuxServer) !void {
    const city_bytes = try buildPropGeoTestMmdb(server.allocator);
    errdefer server.allocator.free(city_bytes);
    const city_db = try geoip.Database.init(city_bytes);

    const asn_bytes = try buildPropGeoTestMmdb(server.allocator);
    errdefer server.allocator.free(asn_bytes);
    const asn_db = try geoip.Database.init(asn_bytes);

    server.geoip_bytes = city_bytes;
    server.geoip_db = city_db;
    server.geoip_tried = true;
    server.geoip_asn_bytes = asn_bytes;
    server.geoip_asn_db = asn_db;
    server.geoip_asn_tried = true;
}

test "threaded server: PROP user geo fields are self-or-oper only" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var server = Server.init(std.testing.allocator, operTestConfig(0)) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        try installPropGeoTestDatabases(&server);
        const port = try server.boundPort();

        var run = std.atomic.Value(bool).init(true);
        var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
        defer {
            run.store(false, .release);
            if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
            thr.join();
        }

        const fd_a = connectLoopback(port) catch return error.SkipZigTest;
        defer closeFd(fd_a);
        const fd_b = connectLoopback(port) catch return error.SkipZigTest;
        defer closeFd(fd_b);
        const fd_oper = connectLoopback(port) catch return error.SkipZigTest;
        defer closeFd(fd_oper);
        var a = LiveClient{ .fd = fd_a };
        var b = LiveClient{ .fd = fd_b };
        var oper = LiveClient{ .fd = fd_oper };

        try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
        try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
        try saslAdminPrelude(fd_oper);
        try writeAllFd(fd_oper, "NICK Oper\r\nUSER oper 0 * :Oper\r\n");
        try recvUntil(&a, " 001 A ", 200);
        try recvUntil(&b, " 001 B ", 200);
        try recvUntil(&oper, " 381 Oper ", 200);

        try writeAllFd(fd_a, "IRCX\r\n");
        try writeAllFd(fd_b, "IRCX\r\n");
        try writeAllFd(fd_oper, "IRCX\r\n");
        try recvUntil(&a, " 800 A 1 0 ", 200);
        try recvUntil(&b, " 800 B 1 0 ", 200);
        try recvUntil(&oper, " 800 Oper 1 0 ", 200);

        b.reset();
        try writeAllFd(fd_b, "PROP A GET CITY,ASN\r\n");
        try recvUntil(&b, " 819 B A ", 200);
        try std.testing.expect(std.mem.indexOf(u8, b.written(), " 818 ") == null);
        try std.testing.expect(std.mem.indexOf(u8, b.written(), "Testopolis") == null);
        try std.testing.expect(std.mem.indexOf(u8, b.written(), "64512") == null);

        // Self and oper PASS the gate: they receive the 818 CITY line (a non-oper,
        // non-self requester gets no 818 at all — asserted above). The value is empty
        // for a loopback test client whose 127.0.0.1 has no GeoIP record; in production
        // it carries the resolved city. The access *decision* is what this asserts;
        // value rendering is covered by the ircx_prop_providers unit tests.
        a.reset();
        try writeAllFd(fd_a, "PROP A GET CITY\r\n");
        try recvUntil(&a, " 818 A A CITY ", 200);
        try recvUntil(&a, " 819 A A ", 200);

        oper.reset();
        try writeAllFd(fd_oper, "PROP A GET CITY\r\n");
        try recvUntil(&oper, " 818 Oper A CITY ", 200);
        try recvUntil(&oper, " 819 Oper A ", 200);
    } else return error.SkipZigTest;
}

test "threaded server: HOSTKEY grants op on keyed join (not disclosed at join; op may read it per-tier)" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    const alloc = std.testing.allocator;
    const a = try alloc.create(LiveClient);
    defer alloc.destroy(a);
    const b = try alloc.create(LiveClient);
    defer alloc.destroy(b);
    a.* = .{ .fd = fd_a };
    b.* = .{ .fd = fd_b };

    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(a, " 001 A ", 200);
    try recvUntil(b, " 001 B ", 200);
    try writeAllFd(fd_a, "IRCX\r\n");
    try recvUntil(a, " 800 A 1 0 ", 200);
    try writeAllFd(fd_b, "IRCX\r\n");
    try recvUntil(b, " 800 B 1 0 ", 200);

    try writeAllFd(fd_a, "JOIN #hk\r\n");
    try recvUntil(a, " 366 A #hk ", 200);
    a.reset();
    try writeAllFd(fd_a, "PROP #hk HOSTKEY :s3cret\r\n");
    try recvUntil(a, " 818 A #hk HOSTKEY :s3cret", 200);
    try recvUntil(a, " 819 A #hk ", 200);

    b.reset();
    try writeAllFd(fd_b, "JOIN #hk s3cret\r\n");
    try recvUntil(b, " 366 B #hk ", 200);
    try expectContains(b.written(), "@B");
    // The JOIN flow itself never echoes the key back to the joiner — keyed join
    // grants the tier silently (the joiner supplied the key; it is not re-disclosed
    // in the join burst).
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "s3cret") == null);

    // B is now an op (rank 2), and HOSTKEY is the op-tier key, so a PROP GET DOES
    // return it under the per-tier read model (op may read HOSTKEY/VOICEKEY/MEMBERKEY).
    b.reset();
    try writeAllFd(fd_b, "PROP #hk HOSTKEY\r\n");
    try recvUntil(b, " 818 B #hk HOSTKEY :s3cret", 200);

    // ...but an OWNER-tier key stays above an op: B cannot read OWNERKEY.
    try writeAllFd(fd_a, "PROP #hk OWNERKEY :ownsek\r\n");
    try recvUntil(a, " 818 A #hk OWNERKEY :ownsek", 200);
    b.reset();
    try writeAllFd(fd_b, "PROP #hk OWNERKEY\r\n");
    try recvUntil(b, " 819 B #hk ", 200);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "ownsek") == null);
}

test "threaded server: ACCESS add/list/delete gated by channel-op" {
    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0xc3)), "local");
    defer ident.deinit();
    var cfg = operTestConfig(0);
    cfg.node_identity = &ident;
    var server = Server.init(std.testing.allocator, cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }
    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    const alloc = std.testing.allocator;
    const a = try alloc.create(LiveClient);
    defer alloc.destroy(a);
    const b = try alloc.create(LiveClient);
    defer alloc.destroy(b);
    a.* = .{ .fd = fd_a };
    b.* = .{ .fd = fd_b };
    try saslAdminPrelude(fd_a);
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(a, " 001 A ", 200);
    try recvUntil(a, " 381 A ", 200);
    try recvUntil(b, " 001 B ", 200);
    try writeAllFd(fd_a, "IRCX\r\n");
    try writeAllFd(fd_b, "IRCX\r\n");
    try recvUntil(a, " 800 A 1 0 ", 200);
    try recvUntil(b, " 800 B 1 0 ", 200);
    try writeAllFd(fd_a, "JOIN #a\r\n");
    try recvUntil(a, " 366 A #a ", 200);
    // Founder A grants VOICE access, lists it, then deletes it (801/803-805/802).
    a.reset();
    try writeAllFd(fd_a, "ACCESS #a ADD VOICE *!*@trusted.example\r\n");
    try recvUntil(a, " 801 A #a VOICE *!*@trusted.example", 200);
    try recvUntil(a, "ACCESS #a ADD VOICE *!*@trusted.example proof=", 300);
    a.reset();
    try writeAllFd(fd_a, "ACCESS #a LIST\r\n");
    try recvUntil(a, " 803 A #a ", 200);
    try recvUntil(a, " 804 A ", 200);
    try recvUntil(a, " 805 A #a ", 200);
    a.reset();
    try writeAllFd(fd_a, "ACCESS #a DELETE VOICE *!*@trusted.example\r\n");
    try recvUntil(a, " 802 A #a VOICE *!*@trusted.example", 200);
    try recvUntil(a, "ACCESS #a DELETE VOICE *!*@trusted.example proof=", 300);
    a.reset();
    try writeAllFd(fd_a, "AUDIT JSON A 5\r\n");
    try recvUntil(a, "\"type\":\"audit-end\"", 300);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "\"action\":\"access_delete\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "\"action\":\"access_add\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "\"proof_id\":") != null);
    // B (not a channel operator) cannot manage the access list (482).
    b.reset();
    try writeAllFd(fd_b, "ACCESS #a ADD VOICE *!*@x\r\n");
    try recvUntil(b, " 482 ", 200);
    a.reset();
    try writeAllFd(fd_a, "ACCESS #a ADD DENY *!*@clear.example\r\n");
    try recvUntil(a, "ACCESS #a ADD DENY *!*@clear.example proof=", 300);
    a.reset();
    try writeAllFd(fd_a, "ACCESS #a CLEAR DENY\r\n");
    try recvUntil(a, " 805 A #a ", 200);
    try recvUntil(a, "ACCESS #a CLEAR DENY proof=", 300);
    a.reset();
    try writeAllFd(fd_a, "AUDIT JSON A 5\r\n");
    try recvUntil(a, "\"type\":\"audit-end\"", 300);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "\"action\":\"access_clear\"") != null);
    // Channel-recycle: A seeds a DENY entry, parts (channel destroyed as sole
    // member), then recreates #a — the stale DENY must NOT survive into the new
    // incarnation (only 803 start + 805 end, no 804 entry line).
    try writeAllFd(fd_a, "ACCESS #a ADD DENY *!*@evil.example\r\n");
    try recvUntil(a, " 801 A #a DENY ", 200);
    try writeAllFd(fd_a, "PART #a\r\n");
    try recvUntil(a, "PART #a", 200);
    try writeAllFd(fd_a, "JOIN #a\r\n");
    try recvUntil(a, " 366 A #a ", 200);
    a.reset();
    try writeAllFd(fd_a, "ACCESS #a LIST\r\n");
    try recvUntil(a, " 805 A #a ", 200);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "evil.example") == null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), " 804 ") == null);
}

test "threaded server: IRCX ACCESS DENY blocks the matching join" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    const fd_c = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_c);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };
    var c = LiveClient{ .fd = fd_c };

    // A founds #d (opts into IRCX for ACCESS); B has username "bob", C "carol".
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try writeAllFd(fd_a, "IRCX\r\n");
    try recvUntil(&a, " 800 A ", 200);
    try writeAllFd(fd_a, "JOIN #d\r\n");
    try recvUntil(&a, " 366 A #d ", 200);

    // Founder denies anyone whose user is "bob" via an ACCESS DENY entry.
    a.reset();
    try writeAllFd(fd_a, "ACCESS #d ADD DENY *!bob@*\r\n");
    try recvUntil(&a, " 801 A #d DENY ", 200);

    // B (user bob) is blocked from JOIN with 474; B never reaches end-of-NAMES.
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&b, " 001 B ", 200);
    b.reset();
    try writeAllFd(fd_b, "JOIN #d\r\n");
    try recvUntil(&b, " 474 B #d :", 200);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), " 366 B #d ") == null);

    // C (user carol) does not match the DENY mask and joins normally.
    try writeAllFd(fd_c, "NICK C\r\nUSER carol 0 * :Carol\r\n");
    try recvUntil(&c, " 001 C ", 200);
    c.reset();
    try writeAllFd(fd_c, "JOIN #d\r\n");
    try recvUntil(&c, " 366 C #d ", 200);
}

test "threaded server: IRCX ACCESS GRANT auto-applies member status on join" {
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    const fd_c = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_c);
    var a = LiveClient{ .fd = fd_a };
    var b = LiveClient{ .fd = fd_b };
    var c = LiveClient{ .fd = fd_c };

    // A founds #g (opts into IRCX for ACCESS); B has username "bob", C "carol".
    try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
    try recvUntil(&a, " 001 A ", 200);
    try writeAllFd(fd_a, "IRCX\r\n");
    try recvUntil(&a, " 800 A ", 200);
    try writeAllFd(fd_a, "JOIN #g\r\n");
    try recvUntil(&a, " 366 A #g ", 200);

    // Founder grants VOICE to anyone whose user is "bob".
    a.reset();
    try writeAllFd(fd_a, "ACCESS #g ADD VOICE *!bob@*\r\n");
    try recvUntil(&a, " 801 A #g VOICE ", 200);

    // B (user bob) joins and is auto-voiced: its own end-of-NAMES burst lists it
    // with the '+' voice prefix.
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&b, " 001 B ", 200);
    b.reset();
    try writeAllFd(fd_b, "JOIN #g\r\n");
    try recvUntil(&b, " 366 B #g ", 200);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "+B") != null);

    // C (user carol) matches no ACCESS entry and joins as a plain member (no '+C').
    try writeAllFd(fd_c, "NICK C\r\nUSER carol 0 * :Carol\r\n");
    try recvUntil(&c, " 001 C ", 200);
    c.reset();
    try writeAllFd(fd_c, "JOIN #g\r\n");
    try recvUntil(&c, " 366 C #g ", 200);
    try std.testing.expect(std.mem.indexOf(u8, c.written(), "+C") == null);
}

test "threaded server: override user mode gates and audits channel bypasses" {
    var server = Server.init(std.testing.allocator, multiOperTestConfig(0)) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_o = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_o);
    const fd_b = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    var a = LiveClient{ .fd = fd_a };
    var o = LiveClient{ .fd = fd_o };
    var b = LiveClient{ .fd = fd_b };

    try saslPlainPrelude(fd_a, "admin", "onyx");
    try writeAllFd(fd_a, "NICK A\r\nUSER admin 0 * :Admin\r\n");
    try saslPlainPrelude(fd_o, "oper", "onyx");
    try writeAllFd(fd_o, "NICK O\r\nUSER oper 0 * :Oper\r\n");
    try writeAllFd(fd_b, "NICK B\r\nUSER bob 0 * :Bob\r\n");
    try recvUntil(&a, " 381 A ", 200);
    try recvUntil(&o, " 381 O ", 200);
    try recvUntil(&b, " 001 B ", 200);

    try writeAllFd(fd_a, "IRCX\r\n");
    try writeAllFd(fd_b, "IRCX\r\n");
    try recvUntil(&a, " 800 A 1 0 ", 200);
    try recvUntil(&b, " 800 B 1 0 ", 200);

    o.reset();
    try writeAllFd(fd_o, "MODE O +j\r\n");
    try recvUntil(&o, " 481 O ", 200);
    b.reset();
    try writeAllFd(fd_b, "MODE B +j\r\n");
    try recvUntil(&b, " 481 B ", 200);

    b.reset();
    try writeAllFd(fd_b, "JOIN #ov\r\n");
    try recvUntil(&b, " 366 B #ov ", 200);
    b.reset();
    try writeAllFd(fd_b, "MODE #ov +b A!*@*\r\n");
    try recvUntil(&b, "MODE #ov +b A!*@*", 200);
    b.reset();
    try writeAllFd(fd_b, "MODE #ov +k secret\r\n");
    try recvUntil(&b, "MODE #ov +k secret", 200);
    b.reset();
    try writeAllFd(fd_b, "MODE #ov +i\r\n");
    try recvUntil(&b, "MODE #ov +i", 200);
    b.reset();
    try writeAllFd(fd_b, "MODE #ov +l 1\r\n");
    try recvUntil(&b, "MODE #ov +l 1", 200);
    b.reset();
    try writeAllFd(fd_b, "MODE #ov +m\r\n");
    try recvUntil(&b, "MODE #ov +m", 200);

    a.reset();
    try writeAllFd(fd_a, "MODE #ov +s\r\n");
    try recvUntil(&a, " 442 A #ov ", 200);

    a.reset();
    try writeAllFd(fd_a, "MODE A +j\r\n");
    try recvUntil(&a, "MODE A +j", 200);
    // Override fires to the oper_action + security categories; both now render in
    // the chatsvc raw form `:<srv> EVENT A override UMODE …` (category off-wire).
    try expectContains(a.written(), "EVENT A override UMODE");
    try expectContains(a.written(), "enabled override");

    a.reset();
    try writeAllFd(fd_a, "MODE A -j\r\n");
    try recvUntil(&a, "MODE A -j", 200);
    try expectContains(a.written(), "EVENT A override UMODE");
    try expectContains(a.written(), "disabled override");

    a.reset();
    try writeAllFd(fd_a, "MODE A +j\r\n");
    try recvUntil(&a, "MODE A +j", 200);
    a.reset();
    try writeAllFd(fd_a, "MODE A\r\n");
    try recvUntil(&a, " 221 A :+", 200);
    try expectContains(a.written(), "j");

    a.reset();
    try writeAllFd(fd_a, "JOIN #ov wrong\r\n");
    try recvUntil(&a, " 366 A #ov ", 200);
    try expectContains(a.written(), "EVENT A override JOIN");

    a.reset();
    try writeAllFd(fd_a, "MODE #ov +s\r\n");
    try recvUntil(&a, "MODE #ov +s", 200);
    try expectContains(a.written(), "override MODE");

    a.reset();
    try writeAllFd(fd_a, "ACCESS #ov ADD VOICE *!*@trusted.example\r\n");
    try recvUntil(&a, " 801 A #ov VOICE *!*@trusted.example", 200);
    try expectContains(a.written(), "override ACCESS");

    a.reset();
    try writeAllFd(fd_a, "PROP #ov LANGUAGE :en\r\n");
    try recvUntil(&a, " 819 A #ov ", 200);
    try expectContains(a.written(), " 818 A #ov LANGUAGE :en");
    try expectContains(a.written(), "override PROP");

    a.reset();
    b.reset();
    try writeAllFd(fd_a, "PART #ov\r\n");
    try recvUntil(&a, "PART #ov", 200);
    a.reset();
    try writeAllFd(fd_a, "PRIVMSG #ov :override hi\r\n");
    try recvUntil(&b, "PRIVMSG #ov :override hi", 200);
    try recvUntil(&a, "override SEND", 200);

    a.reset();
    b.reset();
    try writeAllFd(fd_a, "DATA #ov MSG :override data\r\n");
    try recvUntil(&b, "DATA #ov MSG :override data", 200);
    try recvUntil(&a, "override SEND", 200);

    a.reset();
    b.reset();
    try writeAllFd(fd_a, "KICK #ov B :override kick\r\n");
    try recvUntil(&b, "KICK #ov B :override kick", 200);
    try recvUntil(&a, "override KICK", 200);

    a.reset();
    b.reset();
    try writeAllFd(fd_a, "KILL B :override kill\r\n");
    try recvUntil(&b, "Killed (SYSTEM (override kill))", 200);
    try expectContains(b.written(), ":SYSTEM KILL B :override kill");
    try std.testing.expect(std.mem.indexOf(u8, b.written(), "A!admin@") == null);
    try recvUntil(&a, "override KILL", 200);
    try recvUntil(&a, "A killed B as SYSTEM", 200);
}

test "override user mode letter does not collide with advertised mode catalogs" {
    const override_letter = usermode.letterOf(.override) orelse return error.ModeNotInCatalog;
    const folded = std.ascii.toLower(override_letter);
    try std.testing.expectEqual(@as(u8, 'j'), override_letter);

    for (usermode.default_specs) |spec| {
        if (spec.mode == .override) continue;
        try std.testing.expect(std.ascii.toLower(spec.letter) != folded);
    }
    for (chanmode.default_specs) |spec| {
        try std.testing.expect(std.ascii.toLower(spec.letter) != folded);
    }
    for (chanmode_ext.mode_specs) |spec| {
        try std.testing.expect(std.ascii.toLower(spec.letter) != folded);
    }
    const prefix_letters = [_]u8{
        chanmode.oper_mode_letter,
        chanmode.memberModeLetter(.founder),
        chanmode.memberModeLetter(.owner),
        chanmode.memberModeLetter(.op),
        chanmode.memberModeLetter(.voice),
    };
    for (prefix_letters) |letter| {
        try std.testing.expect(std.ascii.toLower(letter) != folded);
    }
}

test "migrated profile uses authenticated account and preserves local transport identity and caps" {
    var session = dispatch.ClientSession.init();
    session.loginAs("alice");
    session.setRealHost("203.0.113.41");
    session.setVisibleHost("old-cloak.example");
    session.addCap(.echo_message);
    session.addCap(.onyx_session_sync);

    const snap = migration_relay.Snapshot{
        .nick = "AlicePhone",
        .umodes = "+i",
        .channels = &.{},
        // Rolling-old migration snapshots may omit account. The already-
        // authenticated caller remains logged in under its canonical account.
        .account = "",
        .host = "migrated-cloak.example",
    };
    const result = LinuxServer.prepareMigratedSessionProfile(&session, "alice", &snap, false, null, 100);

    try std.testing.expect(!result.override_activated);
    try std.testing.expectEqualStrings("alice", session.account().?);
    try std.testing.expect(session.hasUmode(.registered));
    try std.testing.expectEqualStrings("203.0.113.41", session.realHost());
    try std.testing.expectEqualStrings("migrated-cloak.example", session.host());
    try std.testing.expect(session.hasCap(.echo_message));
    try std.testing.expect(session.hasCap(.onyx_session_sync));
}

test "migrated profile honors mode direction and rederives transport account and admin modes" {
    var tls_admin = dispatch.ClientSession.init();
    tls_admin.loginAs("admin");
    try reconcileTestOper(
        &tls_admin,
        oper_mod.OperPrivileges.initMany(&.{.server_admin}),
        "netadmin",
        "Network Admin",
    );
    const tls_snap = migration_relay.Snapshot{
        .nick = "AdminPhone",
        // +B is portable, +i is then removed. Attempts to remove derived +r/+a
        // and carried +z/+x cannot override current account/grant/transport.
        .umodes = "+iBzxa-irza",
        .channels = &.{},
    };
    _ = try prepareMigratedSessionProfileForTest(
        &tls_admin,
        "admin",
        &tls_snap,
        true,
        oper_mod.OperPrivileges.initMany(&.{.server_admin}),
        "netadmin",
        "Network Admin",
    );
    try std.testing.expect(!tls_admin.hasUmode(.invisible));
    try std.testing.expect(tls_admin.hasUmode(.bot));
    try std.testing.expect(tls_admin.hasUmode(.secure_tls));
    try std.testing.expect(!tls_admin.hasUmode(.cloaked));
    try std.testing.expect(tls_admin.hasUmode(.registered));
    try std.testing.expect(tls_admin.hasUmode(.admin));
    try std.testing.expect(tls_admin.isAdmin());

    var plaintext = dispatch.ClientSession.init();
    plaintext.loginAs("plain");
    const plain_snap = migration_relay.Snapshot{
        .nick = "PlainPhone",
        .umodes = "+zaxo",
        .channels = &.{},
        // Stale profile history cannot recreate an oper grant revoked locally.
        .is_oper = true,
    };
    _ = LinuxServer.prepareMigratedSessionProfile(&plaintext, "plain", &plain_snap, false, null, 100);
    try std.testing.expect(!plaintext.hasUmode(.secure_tls));
    try std.testing.expect(!plaintext.hasUmode(.cloaked));
    try std.testing.expect(!plaintext.hasUmode(.admin));
    try std.testing.expect(!plaintext.isOper());
    try std.testing.expect(plaintext.hasUmode(.registered));
}

test "migrated profile never relaxes a local media transmit deny" {
    var removed = dispatch.ClientSession.init();
    removed.loginAs("restricted");
    _ = removed.setUmode(.media_tx_deny, true);
    const remove_snap = migration_relay.Snapshot{
        .nick = "RestrictedPhone",
        .umodes = "-M",
        .channels = &.{},
    };
    _ = LinuxServer.prepareMigratedSessionProfile(&removed, "restricted", &remove_snap, false, null, 100);
    try std.testing.expect(removed.hasUmode(.media_tx_deny));

    var omitted = dispatch.ClientSession.init();
    omitted.loginAs("restricted");
    _ = omitted.setUmode(.media_tx_deny, true);
    const omitted_snap = migration_relay.Snapshot{
        .nick = "RestrictedTablet",
        .umodes = "+i",
        .channels = &.{},
    };
    _ = LinuxServer.prepareMigratedSessionProfile(&omitted, "restricted", &omitted_snap, false, null, 100);
    try std.testing.expect(omitted.hasUmode(.media_tx_deny));

    // A carried deny may still tighten an unrestricted claimant.
    var tightened = dispatch.ClientSession.init();
    tightened.loginAs("restricted");
    const add_snap = migration_relay.Snapshot{
        .nick = "RestrictedLaptop",
        .umodes = "+M",
        .channels = &.{},
    };
    _ = LinuxServer.prepareMigratedSessionProfile(&tightened, "restricted", &add_snap, false, null, 100);
    try std.testing.expect(tightened.hasUmode(.media_tx_deny));
}

test "migrated override mode is directional privilege gated and reports activation" {
    var plain = dispatch.ClientSession.init();
    plain.loginAs("plain");
    const plain_snap = migration_relay.Snapshot{
        .nick = "Plain",
        .umodes = "+ij",
        .channels = &.{},
    };
    const denied = LinuxServer.prepareMigratedSessionProfile(&plain, "plain", &plain_snap, false, null, 100);
    try std.testing.expect(plain.hasUmode(.invisible));
    try std.testing.expect(!plain.hasUmode(.override));
    try std.testing.expect(!denied.override_activated);

    var privileged = dispatch.ClientSession.init();
    privileged.loginAs("priv");
    try reconcileTestOper(&privileged, oper_mod.OperPrivileges.initMany(&.{.oper_override}), "netadmin", "");
    const add_snap = migration_relay.Snapshot{
        .nick = "Priv",
        .umodes = "+j",
        .channels = &.{},
    };
    const activated = try prepareMigratedSessionProfileForTest(
        &privileged,
        "priv",
        &add_snap,
        false,
        oper_mod.OperPrivileges.initMany(&.{.oper_override}),
        "netadmin",
        "",
    );
    try std.testing.expect(privileged.hasUmode(.override));
    try std.testing.expect(activated.override_activated);

    const remove_snap = migration_relay.Snapshot{
        .nick = "Priv",
        .umodes = "-j",
        .channels = &.{},
    };
    const removed = try prepareMigratedSessionProfileForTest(
        &privileged,
        "priv",
        &remove_snap,
        false,
        oper_mod.OperPrivileges.initMany(&.{.oper_override}),
        "netadmin",
        "",
    );
    try std.testing.expect(!privileged.hasUmode(.override));
    try std.testing.expect(!removed.override_activated);
}

test "threaded server: legacy GRANT remains inactive and cannot arm override" {
    var server = Server.init(std.testing.allocator, runtimeGrantTestConfig(0)) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_a = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_t = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_t);
    var a = LiveClient{ .fd = fd_a };
    var t = LiveClient{ .fd = fd_t };

    try saslPlainPrelude(fd_a, "admin", "onyx");
    try writeAllFd(fd_a, "NICK A\r\nUSER admin 0 * :Admin\r\n");
    try saslPlainPrelude(fd_t, "target", "onyx");
    try writeAllFd(fd_t, "NICK T\r\nUSER target 0 * :Target\r\n");
    try recvUntil(&a, " 381 A ", 200);
    try recvUntil(&t, " 001 T ", 200);
    try std.testing.expect(std.mem.indexOf(u8, t.written(), " 381 T ") == null);

    a.reset();
    t.reset();
    try writeAllFd(fd_a, "GRANT target netadmin\r\n");
    try recvUntil(&a, "mesh display grant stored for target", 300);
    try writeAllFd(fd_t, "PING :grant-inactive\r\n");
    try recvUntil(&t, "PONG", 200);
    try std.testing.expect(std.mem.indexOf(u8, t.written(), " 381 T ") == null);

    t.reset();
    try writeAllFd(fd_t, "MODE T +j\r\n");
    try recvUntil(&t, " 481 T ", 200);

    a.reset();
    t.reset();
    try writeAllFd(fd_a, "GRANT target ircop client_kill\r\n");
    try recvUntil(&a, "mesh display grant stored for target", 300);
    try writeAllFd(fd_t, "PING :narrow-inactive\r\n");
    try recvUntil(&t, "PONG", 200);
    try std.testing.expect(std.mem.indexOf(u8, t.written(), "MODE T -j") == null);
}

test "threaded server: legacy GRANT and REVOKE never announce oper prefix transitions" {
    var server = Server.init(std.testing.allocator, runtimeGrantTestConfig(0)) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    const port = try server.boundPort();
    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    const fd_admin = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_admin);
    const fd_target = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_target);
    const fd_bystander = connectLoopback(port) catch return error.SkipZigTest;
    defer closeFd(fd_bystander);
    var admin = LiveClient{ .fd = fd_admin };
    var target = LiveClient{ .fd = fd_target };
    var bystander = LiveClient{ .fd = fd_bystander };

    try saslPlainPrelude(fd_admin, "admin", "onyx");
    try writeAllFd(fd_admin, "NICK Grantor\r\nUSER admin 0 * :Grantor\r\n");
    try saslPlainPrelude(fd_target, "target", "onyx");
    try writeAllFd(fd_target, "NICK DisplayTarget\r\nUSER target 0 * :Target\r\n");
    try writeAllFd(fd_bystander, "NICK Watcher\r\nUSER watcher 0 * :Watcher\r\n");
    try recvUntil(&admin, " 381 Grantor ", 200);
    try recvUntil(&target, " 001 DisplayTarget ", 200);
    try recvUntil(&bystander, " 001 Watcher ", 200);

    // Inactive compatibility records are not operator lifecycle transitions.
    // Subscribe the grantor to that exact OBSERVE action and prove neither
    // GRANT nor REVOKE manufactures an `oper` event.
    try writeAllFd(fd_admin, "EVENT OBSERVE * oper\r\n");
    try recvUntil(&admin, "OBSERVE: end of snapshot", 300);

    try writeAllFd(fd_target, "JOIN #grants\r\n");
    try recvUntil(&target, " 366 DisplayTarget #grants ", 200);
    try writeAllFd(fd_bystander, "JOIN #grants\r\n");
    try recvUntil(&bystander, " 366 Watcher #grants ", 200);

    // Local GRANT/REVOKE store mesh display grants. They must not elevate a
    // local session (OPER/DEOPER remains authority) and must not project +Y/-Y
    // for locally-homed attachments — those stay configured-local.
    admin.reset();
    bystander.reset();
    try writeAllFd(fd_admin, "GRANT target ircop client_kill\r\n");
    try recvUntil(&admin, "mesh display grant stored for target", 300);
    try writeAllFd(fd_admin, "PING :grant-observe-inactive\r\n");
    try recvUntil(&admin, "PONG", 200);
    try std.testing.expect(std.mem.indexOf(u8, admin.written(), " OBSERVE oper ") == null);
    try writeAllFd(fd_bystander, "PING :first-grant\r\n");
    try recvUntil(&bystander, "PONG", 200);
    try std.testing.expect(std.mem.indexOf(u8, bystander.written(), "MODE #grants +Y") == null);

    admin.reset();
    bystander.reset();
    try writeAllFd(fd_admin, "GRANT target ircop client_kill,oper_override\r\n");
    try recvUntil(&admin, "mesh display grant stored for target", 300);
    try writeAllFd(fd_admin, "PING :override-observe-inactive\r\n");
    try recvUntil(&admin, "PONG", 200);
    try std.testing.expect(std.mem.indexOf(u8, admin.written(), " OBSERVE oper ") == null);
    try writeAllFd(fd_bystander, "PING :override-added\r\n");
    try recvUntil(&bystander, "PONG", 200);
    try std.testing.expect(std.mem.indexOf(u8, bystander.written(), "MODE #grants +Y") == null);

    admin.reset();
    bystander.reset();
    try writeAllFd(fd_admin, "REVOKE target\r\n");
    try recvUntil(&admin, "mesh display grant tombstoned for target", 300);
    try writeAllFd(fd_admin, "PING :revoke-observe-inactive\r\n");
    try recvUntil(&admin, "PONG", 200);
    try std.testing.expect(std.mem.indexOf(u8, admin.written(), " OBSERVE oper ") == null);
    try writeAllFd(fd_bystander, "PING :override-revoked\r\n");
    try recvUntil(&bystander, "PONG", 200);
    try std.testing.expect(std.mem.indexOf(u8, bystander.written(), "MODE #grants -Y") == null);
}

test "mesh OCG1 GRANT converges records but never authorizes sessions or prefixes" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .num_shards = 2,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    server.fabric = reactor_fabric.ReactorFabric.init(std.testing.allocator, server.reactors.len) catch
        return error.SkipZigTest;

    current_reactor = &server.reactors[0];
    const primary_id = try addTestLocalClient(&server, "DisplayTarget", "target");
    const primary = server.connFor(primary_id).?;
    primary.session.registration.registered = true;
    const watcher_id = try addTestLocalClient(&server, "Watcher", null);
    const watcher = server.connFor(watcher_id).?;
    const alternate_id = try addTestLocalClient(&server, "DisplayTablet", "target");
    const alternate = server.connFor(alternate_id).?;
    alternate.session.registration.registered = true;
    try server.world.restoreMember("#mesh-grant", worldIdFromClient(primary_id), world_model.MemberModes.empty());
    try server.world.restoreMember(
        "#mesh-grant",
        worldIdFromClient(watcher_id),
        world_model.MemberModes.fromModes(&.{.founder}),
    );
    try server.world.restoreMember("#mesh-grant", worldIdFromClient(alternate_id), world_model.MemberModes.empty());

    // A second physical attachment for the same account/session lives on the
    // sibling reactor. It intentionally does not claim a second World nick row;
    // reusable attachments share the logical display identity.
    current_reactor = &server.reactors[1];
    const sibling_id = try server.rx().clients.alloc(ConnState.init(-1));
    const sibling = server.connFor(sibling_id).?;
    sibling.token = try tokenFromId(sibling_id);
    try sibling.session.setNick("DisplayTarget");
    sibling.session.loginAs("target");
    sibling.session.registration.registered = true;

    current_reactor = &server.reactors[0];
    const signer = std.crypto.sign.Ed25519.KeyPair.generateDeterministic(@splat(0x7a)) catch unreachable;
    const now = server.grantNowU64();
    var wire_buf: [oper_cred_share.max_grant_len]u8 = undefined;
    const override_bits = oper_mod.OperPrivileges.initMany(&.{.oper_override}).toBits();
    const add_len = try oper_cred_share.sign(signer, .{
        .account = "DisplayTarget",
        .privilege_bits = override_bits,
        .class = "netadmin",
        .title = "",
        .issuer_node = "grant-origin.test",
        .incarnation = 1,
        .issued_ms = now,
        .expiry_ms = now + Server.oper_grant_ttl_ms,
    }, &wire_buf);
    try std.testing.expect(server.applyMeshGrant(wire_buf[0..add_len], signer.public_key.toBytes()));
    try std.testing.expect(!primary.session.isOper());
    try std.testing.expect(!sibling.session.isOper());
    try std.testing.expect(!alternate.session.isOper());
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "MODE #mesh-grant +Y") == null);
    try std.testing.expect(!server.isOverrideOper("DisplayTarget"));
    const stored_add = server.oper_grants.lookup("DisplayTarget", now) orelse return error.TestExpectedGrant;
    try std.testing.expectEqual(override_bits, stored_add.privilege_bits);

    // A grant that arrives BEFORE a remote JOIN must still project +Y once
    // the JOIN is emitted, so the nicklist does not wait for a later NAMES.
    const remote_add_len = try oper_cred_share.sign(signer, .{
        .account = "RemoteLegacy",
        .privilege_bits = override_bits,
        .class = "netadmin",
        .title = "",
        .issuer_node = "grant-origin.test",
        .incarnation = 1,
        .issued_ms = now,
        .expiry_ms = now + Server.oper_grant_ttl_ms,
    }, &wire_buf);
    try std.testing.expect(server.applyMeshGrant(wire_buf[0..remote_add_len], signer.public_key.toBytes()));
    resetTestSendQ(watcher);
    const remote_join = .{
        .channel = "#mesh-grant",
        .nick = "RemoteLegacy",
        .username = "remote",
        .realname = "Remote Legacy",
        .host = "remote.example",
        .setter = "",
        .account = "RemoteLegacy",
        .kind = s2s_peer_mod.S2sPeer.MembershipDelta.Kind.joined,
        .status = @as(u4, 0),
        .prev_status = @as(u4, 0),
    };
    server.emitRemoteMembership(&remote_join, "origin.example");
    try expectContains(watcher.send_buf[0..watcher.send_len], "RemoteLegacy!remote@remote.example JOIN :#mesh-grant");
    try expectContains(watcher.send_buf[0..watcher.send_len], "MODE #mesh-grant +Y RemoteLegacy");

    // A higher-incarnation refresh with unchanged privileges is silent.
    resetTestSendQ(watcher);
    const refresh_len = try oper_cred_share.sign(signer, .{
        .account = "DisplayTarget",
        .privilege_bits = override_bits,
        .class = "netadmin",
        .title = "",
        .issuer_node = "grant-origin.test",
        .incarnation = 2,
        .issued_ms = now,
        .expiry_ms = now + Server.oper_grant_ttl_ms,
    }, &wire_buf);
    try std.testing.expect(server.applyMeshGrant(wire_buf[0..refresh_len], signer.public_key.toBytes()));
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "+Y") == null);

    // RemoteLegacy was already projected; a same-privilege remint stays silent
    // (the 30s anti-entropy spam class).
    resetTestSendQ(watcher);
    const remote_refresh_len = try oper_cred_share.sign(signer, .{
        .account = "RemoteLegacy",
        .privilege_bits = override_bits,
        .class = "netadmin",
        .title = "",
        .issuer_node = "grant-origin.test",
        .incarnation = 2,
        .issued_ms = now,
        .expiry_ms = now + Server.oper_grant_ttl_ms,
    }, &wire_buf);
    try std.testing.expect(server.applyMeshGrant(wire_buf[0..remote_refresh_len], signer.public_key.toBytes()));
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "+Y") == null);
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "-Y") == null);

    // A higher-incarnation legacy record still converges without changing any
    // live session projection.
    const kill_bits = oper_mod.OperPrivileges.initMany(&.{.client_kill}).toBits();
    const narrow_len = try oper_cred_share.sign(signer, .{
        .account = "DisplayTarget",
        .privilege_bits = kill_bits,
        .class = "ircop",
        .title = "",
        .issuer_node = "grant-origin.test",
        .incarnation = 3,
        .issued_ms = now,
        .expiry_ms = now + Server.oper_grant_ttl_ms,
    }, &wire_buf);
    try std.testing.expect(server.applyMeshGrant(wire_buf[0..narrow_len], signer.public_key.toBytes()));
    try std.testing.expect(!primary.session.isOper());
    try std.testing.expect(!sibling.session.isOper());
    try std.testing.expect(!alternate.session.isOper());
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "MODE #mesh-grant -Y") == null);
    const stored_narrow = server.oper_grants.lookup("DisplayTarget", now) orelse return error.TestExpectedGrant;
    try std.testing.expectEqual(kill_bits, stored_narrow.privilege_bits);

    // Begin a new dedup horizon before the independent re-add/revoke scenario;
    // the test is about grant transition ownership, not waiting two wall seconds.
    server.oper_prefix_dedup = .{};
    resetTestSendQ(watcher);
    const restored_bits = oper_mod.OperPrivileges.initMany(&.{ .client_kill, .oper_override }).toBits();
    const restore_len = try oper_cred_share.sign(signer, .{
        .account = "DisplayTarget",
        .privilege_bits = restored_bits,
        .class = "netadmin",
        .title = "",
        .issuer_node = "grant-origin.test",
        .incarnation = 4,
        .issued_ms = now,
        .expiry_ms = now + Server.oper_grant_ttl_ms,
    }, &wire_buf);
    try std.testing.expect(server.applyMeshGrant(wire_buf[0..restore_len], signer.public_key.toBytes()));
    try std.testing.expect(!primary.session.isOper());
    try std.testing.expect(!sibling.session.isOper());
    try std.testing.expect(!alternate.session.isOper());
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "MODE #mesh-grant +Y") == null);

    // A preloaded grant cannot elevate a local session, authorize DATA, or
    // grant KICK immunity. Display `*` / 313 stay configured-local for this nick.
    resetTestSendQ(watcher);
    try server.sendNames(watcher, "#mesh-grant");
    try expectContains(watcher.send_buf[0..watcher.send_len], "DisplayTarget");
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "*DisplayTarget") == null);
    resetTestSendQ(watcher);
    var whois_line = try irc_line.parseLine("WHOIS DisplayTarget");
    try server.handleWhois(watcher, &whois_line);
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], " 313 ") == null);
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "*#mesh-grant") == null);
    try std.testing.expect(!server.remoteDataTagAuthorized("SYS.notice", false, null, "DisplayTarget"));
    try std.testing.expect(!server.remoteDataTagAuthorized("HST.state", false, null, "DisplayTarget"));
    resetTestSendQ(watcher);
    var kick_line = try irc_line.parseLine("KICK #mesh-grant DisplayTarget :legacy telemetry is not immunity");
    try server.handleKick(watcher_id, watcher, &kick_line);
    try std.testing.expect(!server.world.isMember("#mesh-grant", worldIdFromClient(primary_id)));
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "Cannot kick a network operator") == null);

    // The tombstone supersedes the stored record but likewise has no live
    // session or prefix side effect.
    resetTestSendQ(watcher);
    const revoke_len = try oper_cred_share.sign(signer, .{
        .account = "DisplayTarget",
        .privilege_bits = 0,
        .class = "revoked",
        .title = "",
        .issuer_node = "grant-origin.test",
        .incarnation = 5,
        .issued_ms = now,
        .expiry_ms = now + Server.oper_grant_ttl_ms,
    }, &wire_buf);
    try std.testing.expect(server.applyMeshGrant(wire_buf[0..revoke_len], signer.public_key.toBytes()));
    try std.testing.expect(!primary.session.isOper());
    try std.testing.expect(!sibling.session.isOper());
    try std.testing.expect(!alternate.session.isOper());
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "MODE #mesh-grant -Y") == null);
    const stored_tombstone = server.oper_grants.lookup("DisplayTarget", now) orelse return error.TestExpectedGrant;
    try std.testing.expectEqual(@as(u64, 0), stored_tombstone.privilege_bits);
}

