test "threaded server: oper CONNECT opens an outbound S2S link" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        // A test-owned listener stands in for the remote peer; the server dials it.
        const listen_fd = createListener("127.0.0.1", 0, 8) catch return error.SkipZigTest;
        defer closeFd(listen_fd);
        const remote_port = socketPort(listen_fd) catch return error.SkipZigTest;

        var ident = try node_identity.fromSeed(@as([32]u8, @splat(0xa4)), "local");
        defer ident.deinit();
        var cfg = operTestConfig(0);
        cfg.node_identity = &ident;
        // Plaintext CONNECT ⇒ keyless S2S link. A keyless node now fails CLOSED on
        // unsigned in-scope frames when require_signed_frames is set (the default),
        // so this plaintext-link integration smoke test opts into unsigned interop
        // as a plaintext operator would; signing enforcement is proven separately.
        cfg.s2s_config.require_signed_frames = false;
        var server = Server.init(std.testing.allocator, cfg) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer server.deinit();
        // Server.init canonicalizes the legacy configured id to the sovereign
        // identity short id. The fake remote must expect the exact node id the
        // live outbound link puts in its HANDSHAKE, not the old default `1`.
        const expected_server_node_id = ident.shortId();
        try std.testing.expectEqual(expected_server_node_id, server.config.node_id);
        const port = try server.boundPort();
        var run = std.atomic.Value(bool).init(true);
        var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
        defer {
            run.store(false, .release);
            if (connectLoopback(port)) |wfd| closeFd(wfd) else |_| {}
            thr.join();
        }

        // Oper client SASL-authenticates as the admin oper account, then CONNECTs.
        const fd_a = connectLoopback(port) catch return error.SkipZigTest;
        defer closeFd(fd_a);
        var a = LiveClient{ .fd = fd_a };
        try saslAdminPrelude(fd_a);
        try writeAllFd(fd_a, "NICK A\r\nUSER alice 0 * :Alice\r\n");
        try recvUntil(&a, " 001 A ", 200);
        try recvUntil(&a, " 381 A ", 200); // auto-elevated on SASL login
        var cmd_buf: [64]u8 = undefined;
        const cmd = try std.fmt.bufPrint(&cmd_buf, "CONNECT 127.0.0.1 {d}\r\n", .{remote_port});
        try writeAllFd(fd_a, cmd);
        var connect_event_buf: [96]u8 = undefined;
        const connect_event = try std.fmt.bufPrint(&connect_event_buf, "CONNECT 127.0.0.1:{d} plain proof=", .{remote_port});
        try recvUntil(&a, connect_event, 400);

        // Accept the server's outbound connection on the test listener.
        var poll_listen = [_]posix.pollfd{.{ .fd = listen_fd, .events = posix.POLL.IN, .revents = 0 }};
        const peer_fd: linux.fd_t = if (builtin.os.tag == .openbsd) blk: {
            // Once CONNECT was accepted, a missing native dial is a failure.
            // Readiness may race accept on a nonblocking listener, so retain
            // the existing five-second budget across AGAIN/INTR retries.
            const deadline = platform.monotonicMillis() + 5_000;
            while (platform.monotonicMillis() < deadline) {
                const ready = posix.poll(&poll_listen, 25) catch return error.Unexpected;
                if (ready == 0 or poll_listen[0].revents & posix.POLL.IN == 0) continue;
                const rc = posix.system.accept(listen_fd, null, null);
                switch (posix.errno(rc)) {
                    .SUCCESS => break :blk @intCast(rc),
                    .AGAIN, .INTR => continue,
                    else => return error.Unexpected,
                }
            }
            return error.TestTimeout;
        } else blk: {
            var waited: usize = 0;
            while (waited < 200) : (waited += 1) {
                const ready = posix.poll(&poll_listen, 25) catch return error.Unexpected;
                if (ready != 0 and poll_listen[0].revents & posix.POLL.IN != 0) break;
            }
            const rc = linux.accept4(listen_fd, null, null, 0);
            break :blk switch (posix.errno(rc)) {
                .SUCCESS => @intCast(rc),
                else => return error.SkipZigTest,
            };
        };
        defer closeFd(peer_fd);
        if (builtin.os.tag == .openbsd) try os_runtime.setCloexec(peer_fd, true);

        // Drive a responding S2sLink (no start — the server opened the handshake).
        const alloc = std.testing.allocator;
        const peer = try alloc.create(s2s_link.S2sLink);
        defer alloc.destroy(peer);
        try peer.init(.{
            .allocator = alloc,
            .local_node_id = 2,
            .remote_node_id = expected_server_node_id,
            .local_epoch_ms = 3000,
            .server_name = "remote.test",
            .config = .{ .require_signed_frames = false },
        });
        defer peer.deinit();

        var rx: [4096]u8 = undefined;
        var now: u64 = 1;
        var polls: usize = 0;
        while (polls < 200 and !peer.established()) : (polls += 1) {
            var fds = [_]posix.pollfd{.{ .fd = peer_fd, .events = posix.POLL.IN, .revents = 0 }};
            const ready = posix.poll(&fds, 25) catch return error.Unexpected;
            if (ready == 0) continue;
            if ((fds[0].revents & posix.POLL.IN) == 0) continue;
            const n = try readFd(peer_fd, &rx);
            if (n == 0) return error.ConnectionReset;
            now += 1;
            try peer.feed(rx[0..n], now, 3);
            if (peer.outbound().len != 0) {
                try writeAllFd(peer_fd, peer.outbound());
                peer.clearOutbound();
            }
        }
        try std.testing.expect(peer.established());
        try std.testing.expect(peer.knownServers() >= 2);

        // SERVER_LINK Event Spine mirror: the oper A (auto-subscribed to every
        // category on elevation) receives an `EVENT A SERVER LINK <peer>` when the peer link
        // comes up, alongside the mesh_event_log entry. The peer named itself
        // "remote.test", so that is the link subject. Asserted before the reset below.
        try recvUntil(&a, "EVENT A SERVER LINK remote.test", 400);

        // Deterministic readiness gate (no timing race): LINKS is idempotent and only
        // lists ESTABLISHED, handshake-NAMED peers. Poll it until 'remote.test'
        // appears — that is the observable signal the server learned the peer — THEN
        // SQUIT exactly once and require success. (Protocol convergence itself is
        // proven by the deterministic byte-loopback tests; this is the socket/reactor
        // integration smoke test, made non-flaky by gating on observable readiness.)
        var learned = false;
        var probes: usize = 0;
        while (probes < 60 and !learned) : (probes += 1) {
            a.reset();
            try writeAllFd(fd_a, "LINKS\r\n");
            recvUntil(&a, " 365 ", 80) catch {};
            if (std.mem.indexOf(u8, a.written(), "remote.test") != null) learned = true;
        }
        try std.testing.expect(learned);

        // Remote WHOIS via the mesh projection: the fake peer announces a channel
        // member (with its real propagated identity) on its side of the link; once
        // the MEMBERSHIP frame lands, the server answers WHOIS for that nick from
        // the converged roster — 311 with the PROPAGATED username + cloaked host
        // (not the mesh@<server> placeholder) and 312 naming the member's actual
        // home server (remote.test), not the local server.
        try peer.sendMembership("#mesh", "Zed", 0b0100, now + 1, true, .{
            .username = "zed",
            .realname = "Zed Remote",
            .host = "cloak-zed.users.test",
        }, "");
        if (peer.outbound().len != 0) {
            try writeAllFd(peer_fd, peer.outbound());
            peer.clearOutbound();
        }
        var whois_seen = false;
        probes = 0;
        while (probes < 60 and !whois_seen) : (probes += 1) {
            a.reset();
            try writeAllFd(fd_a, "WHOIS Zed\r\n");
            // " A Zed" arrives on BOTH outcomes (401 A Zed / 311 A Zed), so a miss
            // cycles quickly instead of riding out the full recvUntil budget.
            recvUntil(&a, " A Zed", 200) catch {};
            if (std.mem.indexOf(u8, a.written(), " 311 A Zed ") != null) {
                recvUntil(&a, " 318 A Zed", 200) catch {};
                const got = a.written();
                if (std.mem.indexOf(u8, got, " 311 A Zed zed cloak-zed.users.test ") != null and
                    std.mem.indexOf(u8, got, ":Zed Remote") != null and
                    std.mem.indexOf(u8, got, " 312 A Zed remote.test ") != null) whois_seen = true;
            }
        }
        try std.testing.expect(whois_seen);

        a.reset();
        try writeAllFd(fd_a, "SQUIT remote.test :maintenance\r\n");
        try recvUntil(&a, "SQUIT remote.test proof=", 300);
        try recvUntil(&a, "SQUIT complete", 200);

        a.reset();
        try writeAllFd(fd_a, "AUDIT JSON A 8\r\n");
        try recvUntil(&a, "\"type\":\"audit-end\"", 300);
        try std.testing.expect(std.mem.indexOf(u8, a.written(), "\"action\":\"squit\"") != null);
        try std.testing.expect(std.mem.indexOf(u8, a.written(), "\"action\":\"connect\"") != null);
    } else return error.SkipZigTest;
}

test "parseHostPort: host:port split, bad port rejected, IPv6 brackets" {
    // Plain host + numeric port.
    const hp = parseHostPort("ircx.us:6900").?;
    try std.testing.expectEqualStrings("ircx.us", hp.host);
    try std.testing.expectEqual(@as(u16, 6900), hp.port);
    // IPv4 literal.
    const v4 = parseHostPort("127.0.0.1:7000").?;
    try std.testing.expectEqualStrings("127.0.0.1", v4.host);
    try std.testing.expectEqual(@as(u16, 7000), v4.port);
    // Bracketed IPv6.
    const v6 = parseHostPort("[::1]:6900").?;
    try std.testing.expectEqualStrings("::1", v6.host);
    try std.testing.expectEqual(@as(u16, 6900), v6.port);
    // Unbracketed IPv6 splits on the LAST colon.
    const v6b = parseHostPort("::1:6900").?;
    try std.testing.expectEqualStrings("::1", v6b.host);
    try std.testing.expectEqual(@as(u16, 6900), v6b.port);
    // Rejected: missing port, empty host, bad/zero/oversized port, broken brackets.
    try std.testing.expectEqual(@as(?HostPort, null), parseHostPort(""));
    try std.testing.expectEqual(@as(?HostPort, null), parseHostPort("ircx.us"));
    try std.testing.expectEqual(@as(?HostPort, null), parseHostPort(":6900"));
    try std.testing.expectEqual(@as(?HostPort, null), parseHostPort("ircx.us:"));
    try std.testing.expectEqual(@as(?HostPort, null), parseHostPort("ircx.us:nope"));
    try std.testing.expectEqual(@as(?HostPort, null), parseHostPort("ircx.us:0"));
    try std.testing.expectEqual(@as(?HostPort, null), parseHostPort("ircx.us:65536"));
    try std.testing.expectEqual(@as(?HostPort, null), parseHostPort("[]:6900"));
    try std.testing.expectEqual(@as(?HostPort, null), parseHostPort("[::1]6900"));
    try std.testing.expectEqual(@as(?HostPort, null), parseHostPort("[::1]"));
}

test "tiny ring fairly activates more than 64 quiet inherited sockets with pending output" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    defer current_reactor = null;

    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .ring_entries = 8,
        .max_clients = 128,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    var peers: [65]linux.fd_t = @splat(-1);
    defer for (peers) |fd| if (fd >= 0) closeFd(fd);
    for (0..peers.len) |i| {
        var sockets: [2]linux.fd_t = undefined;
        if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets)) != .SUCCESS)
            return error.SkipZigTest;
        peers[i] = sockets[1];
        const id = try server.reactors[0].clients.alloc(ConnState.init(sockets[0]));
        const conn = server.reactors[0].clients.get(id).?;
        conn.overflow_allocator = std.testing.allocator;
        conn.token = try tokenFromId(id);
        try rawAppendToConn(conn, "x");
        conn.io_activation_pending = true;
        conn.activation_recv_required = true;
    }

    current_reactor = &server.reactors[0];
    // These three controls claim SQ space before socket activation. With eight
    // entries, the old eager-adoption ordering filled the SQ first and made the
    // next accept arm fail forever without ever submitting the queued work.
    try server.armAccept();
    server.armWake() catch {};
    server.armTimer() catch {};
    try std.testing.expect(server.reactors[0].ring.inner.sq_ready() >= 1);

    var turns: usize = 0;
    while (server.hasPendingSocketActivation()) : (turns += 1) {
        try std.testing.expect(turns < 128);
        _ = try server.activatePendingSocketIo();
        try std.testing.expect(server.reactors[0].ring.inner.sq_ready() <= 8);
        _ = try server.reactors[0].ring.submit();
    }
    try std.testing.expect(turns > 1); // activation was bounded, not one giant scan
    try std.testing.expectEqual(@as(usize, 65), server.reactors[0].clients.len());
    var it = server.reactors[0].clients.iterator();
    while (it.next()) |entry| {
        try std.testing.expect(entry.value.recv_armed);
        try std.testing.expect(entry.value.send_armed);
        try std.testing.expect(!entry.value.io_activation_pending);
    }
}

test "send error waits for quiet recv CQE and stale generation cannot free reuse" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    defer current_reactor = null;

    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    var sockets: [2]linux.fd_t = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets)) != .SUCCESS)
        return error.SkipZigTest;
    defer closeFd(sockets[1]);

    const old_id = try server.rx().clients.alloc(ConnState.init(sockets[0]));
    const old = server.rx().clients.get(old_id).?;
    old.overflow_allocator = std.testing.allocator;
    old.token = try tokenFromId(old_id);
    const old_token = old.token;
    old.recv_armed = true;
    old.send_armed = true;

    try server.handleSend(.{
        .token = old_token,
        .res = -@as(i32, @intFromEnum(linux.E.PIPE)),
        .more = false,
        .notif = false,
    });
    try std.testing.expect(old.closing);
    try std.testing.expect(old.recv_armed);
    try std.testing.expect(!old.send_armed);
    try std.testing.expect(server.rx().clients.get(old_id) != null);

    // The retained recv-owned slot cannot be selected for a new connection.
    const neighbor_id = try server.rx().clients.alloc(ConnState.init(-1));
    try std.testing.expect(neighbor_id.slot != old_id.slot);

    // Only the exact old RECV CQE releases recv_buf and permits final teardown.
    try server.handleRecv(.{
        .token = old_token,
        .res = -@as(i32, @intFromEnum(linux.E.CANCELED)),
        .more = false,
    });
    try std.testing.expect(server.rx().clients.get(old_id) == null);

    const reused_id = try server.rx().clients.alloc(ConnState.init(-1));
    try std.testing.expectEqual(old_id.slot, reused_id.slot);
    try std.testing.expect(reused_id.gen != old_id.gen);
    try std.testing.expectError(error.ClientNotFound, server.handleRecv(.{
        .token = old_token,
        .res = 1,
        .more = false,
    }));
    try std.testing.expect(server.rx().clients.get(reused_id) != null);

    // The delivery-gap abort path follows the same ownership barrier: it may
    // latch close immediately, but cannot recycle recv_buf before its CQE.
    const gap_id = try server.rx().clients.alloc(ConnState.init(-1));
    const gap = server.rx().clients.get(gap_id).?;
    gap.overflow_allocator = std.testing.allocator;
    gap.token = try tokenFromId(gap_id);
    gap.recv_armed = true;
    gap.delivery_gap.store(true, .release);
    try std.testing.expect(server.abortDeliveryGapFor(gap_id, gap));
    try std.testing.expect(gap.closing);
    try std.testing.expect(server.rx().clients.get(gap_id) != null);
    try server.handleRecv(.{
        .token = gap.token,
        .res = -@as(i32, @intFromEnum(linux.E.CANCELED)),
        .more = false,
    });
    try std.testing.expect(server.rx().clients.get(gap_id) == null);
}

