fn expectRetiringPlainMaintenance(pending: bool) !void {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    const alloc = std.testing.allocator;
    const server = try createTestServer(alloc, .{ .host = "127.0.0.1", .port = 0, .node_id = 2 });
    defer alloc.destroy(server);
    defer server.deinit();
    current_reactor = &server.reactors[0];
    const links = try alloc.alloc(s2s_link.S2sLink, 4);
    defer alloc.free(links);
    var initialized: usize = 0;
    defer for (links[0..initialized]) |*link| link.deinit();
    for (links, 0..) |*link, i| {
        try link.init(.{
            .allocator = alloc,
            .local_node_id = if (i % 2 == 0) 1 else 2,
            .remote_node_id = if (i % 2 == 0) 2 else 1,
            .local_epoch_ms = 1_000 + i,
            .server_name = if (i % 2 == 0) "legacy-peer.test" else "legacy-local.test",
            .config = .{ .require_signed_frames = false },
        });
        initialized += 1;
    }
    var ids: [2]client_model.ClientId = undefined;
    var attached: usize = 0;
    defer for (ids[0..attached]) |id| {
        if (server.rx().clients.get(id)) |conn| conn.s2s = null;
    };
    for (&ids, 0..) |*id, i| {
        try links[2 * i].start(50);
        try pumpLinkPair(&links[2 * i], &links[2 * i + 1], alloc);
        try std.testing.expect(links[2 * i + 1].established());
        try std.testing.expect(!links[2 * i + 1].supportsSessionReplicaV2());
        id.* = try server.rx().clients.alloc(ConnState.init(-1));
        attached += 1;
        const conn = server.rx().clients.get(id.*).?;
        conn.token = try tokenFromId(id.*);
        conn.overflow_allocator = alloc;
        conn.test_sendq_capture = true;
        conn.s2s = &links[2 * i + 1];
        // Captured legacy projections are maintenance inputs. No wire account
        // trust is asserted; this tests expiration/publication and legacy fold.
        const refreshed: i64 = if (i == 0) 1 else stale_member_ttl_ms + 10;
        _ = try links[2 * i + 1].peer.routes.applyMembership("#legacy", "Target", 1, 0, 100, true, .{ .username = "target", .host = "legacy.test", .account = "target" }, refreshed);
        _ = try links[2 * i + 1].peer.routes.applyMembership("#legacy", "OldNick", 1, 0, 101, true, .{ .username = "old", .host = "legacy.test" }, refreshed);
        // A fresh shared channel remains visible when legacy rows expire; NICK
        // recipient selection legitimately uses the post-prune live roster.
        _ = try links[2 * i + 1].peer.routes.applyMembership("#witness", "OldNick", 1, 0, 101, true, .{ .username = "old", .host = "legacy.test" }, stale_member_ttl_ms * 3);
    }
    const target_id = try addTestLocalClient(server, "Target", "target");
    const observer_id = try addTestLocalClient(server, "Observer", null);
    const target = server.connFor(target_id).?;
    const observer = server.connFor(observer_id).?;
    target.test_sendq_capture = true;
    observer.test_sendq_capture = true;
    _ = try server.world.join("#legacy", worldIdFromClient(target_id));
    _ = try server.world.join("#legacy", worldIdFromClient(observer_id));
    _ = try server.world.join("#witness", worldIdFromClient(observer_id));
    const loser = server.rx().clients.get(ids[0]).?;
    const survivor = server.rx().clients.get(ids[1]).?;
    const expired_now = stale_member_ttl_ms + 2;
    if (pending) {
        try links[0].sendNickChange("OldNick", "NewNick", .{ .username = "old", .host = "legacy.test" }, 102);
        const wire = try alloc.dupe(u8, links[0].outbound());
        defer alloc.free(wire);
        links[0].clearOutbound();
        try links[1].feed(wire, 1, 100);
        _ = try links[1].peer.pruneStaleMembers(expired_now, stale_member_ttl_ms);
        try std.testing.expect(links[1].peer.identity_transition_order.items.len >= 3);
    }
    const pending_before = links[1].peer.identity_transition_order.items.len;
    loser.closing = true;
    loser.s2s_dedup = true;
    loser.s2s_dedup_drain_deadline_ms = server.nowMs() +| 5_000;
    const held = "retained-legacy-final-flight";
    try rawAppendToConn(loser, held);
    resetTestSendQ(target);
    resetTestSendQ(observer);
    if (pending) {
        server.drainIdentityTransitions(loser, &links[1]);
        // An active sibling cannot attest ownership of the retained loser.
        server.drainIdentityTransitions(survivor, &links[1]);
        // Dedup alone revokes admission before closing is assigned. A late
        // receive must not parse bytes or consume the pending transition queue.
        loser.closing = false;
        const feed_seq = server.s2s_feed_seq;
        server.driveS2s(loser, &links[1], "late-retired-input");
        server.drainIdentityTransitions(loser, &links[1]);
        try std.testing.expectEqual(feed_seq, server.s2s_feed_seq);
        loser.closing = true;
    } else {
        server.pruneStaleMeshMembers(expired_now);
    }
    try std.testing.expect(server.world.isMember("#legacy", worldIdFromClient(target_id)));
    try std.testing.expectEqual(@as(usize, 0), observer.send_len);
    try std.testing.expectEqual(@as(usize, 0), target.send_len);
    try std.testing.expectEqual(pending_before, links[1].peer.identity_transition_order.items.len);
    if (!pending) try std.testing.expectEqual(@as(usize, 2), links[1].channelMembers("#legacy").len);
    try std.testing.expectEqualStrings(held, loser.send_buf[loser.send_offset..loser.send_len]);
    // The same expired/pending work on an active control still publishes and
    // performs the genuine legacy PART. A blanket disabled maintenance passes
    // neither this control nor the local membership assertion below.
    if (pending) {
        try links[2].sendNickChange("OldNick", "NewNick", .{ .username = "old", .host = "legacy.test" }, 102);
        const wire = try alloc.dupe(u8, links[2].outbound());
        defer alloc.free(wire);
        links[2].clearOutbound();
        try links[3].feed(wire, @intCast(stale_member_ttl_ms + 10), 101);
        _ = try links[3].peer.pruneStaleMembers(stale_member_ttl_ms * 2 + 20, stale_member_ttl_ms);
        server.drainIdentityTransitions(survivor, &links[3]);
        try expectContains(observer.send_buf[0..observer.send_len], "NICK NewNick");
    } else {
        server.pruneStaleMeshMembers(stale_member_ttl_ms * 2 + 20);
    }
    try std.testing.expect(!survivor.closing);
    try std.testing.expect(!server.world.isMember("#legacy", worldIdFromClient(target_id)));
    try expectContains(observer.send_buf[0..observer.send_len], "PART #legacy");
    try std.testing.expectEqualStrings(held, loser.send_buf[loser.send_offset..loser.send_len]);
    try std.testing.expectEqual(pending_before, links[1].peer.identity_transition_order.items.len);
}

test "same-IP mesh dial retiring plaintext roster expiration cannot publish or fold legacy PART" {
    try expectRetiringPlainMaintenance(false);
}
test "same-IP mesh dial retiring plaintext pending identity cannot publish NICK PART or fold legacy state" {
    try expectRetiringPlainMaintenance(true);
}

test "same-IP mesh dial unknown inbound peer cannot claim another configured endpoint" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    const alloc = std.testing.allocator;
    const pair = try alloc.create(SessionReplayTestPair);
    defer alloc.destroy(pair);
    pair.* = try SessionReplayTestPair.init(alloc);
    defer pair.deinit();
    const specs = [_][]const u8{"127.0.0.1:65042"};
    const server = try createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .mesh_connect = &specs,
    });
    defer alloc.destroy(server);
    defer server.deinit();
    current_reactor = &server.reactors[0];
    server.mesh_dials[0].addr = try sockaddrForHost("127.0.0.1", 65042, 2_000);
    const id = try server.rx().clients.alloc(ConnState.init(-1));
    const inbound = server.rx().clients.get(id).?;
    inbound.token = try tokenFromId(id);
    inbound.s2s_secured = &pair.a;
    defer inbound.s2s_secured = null;
    inbound.peer_addr = .{ .ipv4 = .{ 127, 0, 0, 1 } };
    try std.testing.expect(pair.a.established());
    try std.testing.expect(!inbound.s2s_initiator);
    // The configured peer is absent. A different authenticated node happened
    // to dial us from that IP; neither its source IP nor ephemeral source port
    // proves which listening endpoint it owns.
    try std.testing.expect(!server.meshPeerLinkedByDial(&server.mesh_dials[0]));
}

test "same-IP mesh dial binding requires the full secured key despite equal peer names" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    const alloc = std.testing.allocator;
    const pairs = try alloc.alloc(SessionReplayTestPair, 2);
    defer alloc.free(pairs);
    pairs[0] = try SessionReplayTestPair.initWithSeeds(alloc, 0xd1, 0xd2);
    defer pairs[0].deinit();
    pairs[1] = try SessionReplayTestPair.initWithSeeds(alloc, 0xd1, 0xd3);
    defer pairs[1].deinit();
    const specs = [_][]const u8{"127.0.0.1:65042"};
    const server = try createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .server_name = "zz-local.test",
        .mesh_connect = &specs,
    });
    defer alloc.destroy(server);
    defer server.deinit();
    current_reactor = &server.reactors[0];
    const outbound_id = try server.rx().clients.alloc(ConnState.init(-1));
    const outbound = server.rx().clients.get(outbound_id).?;
    outbound.token = try tokenFromId(outbound_id);
    outbound.s2s_secured = &pairs[0].a;
    outbound.s2s_initiator = true;
    outbound.s2s_dial_target_known = true;
    outbound.s2s_connect_addr = try sockaddrForHost("127.0.0.1", 65042, 2_000);
    outbound.recv_armed = true;
    const inbound_id = try server.rx().clients.alloc(ConnState.init(-1));
    const inbound = server.rx().clients.get(inbound_id).?;
    inbound.token = try tokenFromId(inbound_id);
    inbound.s2s_secured = &pairs[1].a;
    inbound.recv_armed = true;
    defer {
        for ([_]client_model.ClientId{ outbound_id, inbound_id }) |id| {
            if (server.rx().clients.get(id)) |conn| {
                conn.s2s_secured = null;
                conn.recv_armed = false;
            }
        }
    }
    server.mesh_dials[0].addr = outbound.s2s_connect_addr;
    server.mesh_dials[0].token = outbound.token;
    try std.testing.expectEqualStrings(pairs[0].a.remoteName(), pairs[1].a.remoteName());
    try std.testing.expect(!Server.sameS2sPeer(outbound, inbound));
    try std.testing.expect(!server.resolveS2sCollision(outbound, pairs[0].a.remoteName()));
    try std.testing.expect(!outbound.closing and !inbound.closing);
    try std.testing.expect(!outbound.s2s_dedup and !inbound.s2s_dedup);
    server.transferMeshDialBinding(outbound, inbound);
    try std.testing.expect(!inbound.s2s_dial_target_known);
    try std.testing.expectEqualDeep(outbound.token, server.mesh_dials[0].token.?);

    // The same name plus the same authenticated key is a reciprocal link.
    // Its inbound survivor inherits the complete port, role stays responder.
    inbound.s2s_secured = &pairs[0].a;
    try std.testing.expect(server.resolveS2sCollision(outbound, pairs[0].a.remoteName()));
    try std.testing.expect(outbound.closing and outbound.s2s_dedup);
    try std.testing.expect(!inbound.closing and !inbound.s2s_initiator);
    try std.testing.expect(inbound.s2s_dial_target_known);
    try std.testing.expectEqualDeep(outbound.s2s_connect_addr, inbound.s2s_connect_addr);
    try std.testing.expectEqualDeep(inbound.token, server.mesh_dials[0].token.?);
    try std.testing.expect(server.meshPeerLinkedByDial(&server.mesh_dials[0]));
    server.mesh_dials[0].addr.?.port = std.mem.nativeToBig(u16, 65043);
    try std.testing.expect(!server.meshPeerLinkedByDial(&server.mesh_dials[0]));
}

test "same-IP mesh dial malformed carried endpoint is refused before slot or dial mutation" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    const alloc = std.testing.allocator;
    const pair = try alloc.create(SessionReplayTestPair);
    defer alloc.destroy(pair);
    pair.* = try SessionReplayTestPair.init(alloc);
    defer pair.deinit();
    const specs = [_][]const u8{"127.0.0.1:65042"};
    const server = try createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .mesh_connect = &specs,
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
        .mesh_pass = "session-replay-secret",
    });
    defer alloc.destroy(server);
    defer server.deinit();
    current_reactor = &server.reactors[0];
    const listener = server.reactors[0].listener_fd;
    const conn = try alloc.create(ConnState);
    defer alloc.destroy(conn);
    conn.* = ConnState.init(listener);
    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(alloc);
    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |blob| alloc.free(blob);
        blobs.deinit(alloc);
    }
    try std.testing.expect(server.sealSecuredLink(conn, &pair.a, &pieces, &blobs));
    var snap = try s2s_snapshot.decode(pieces.items[0].bytes, s2s_snapshot.schema_version);
    var addr = try sockaddrForHost("127.0.0.1", 65042, 2_000);
    const before = server.rx().clients.len();
    snap.connect_addr = std.mem.asBytes(&addr)[0..1];
    try std.testing.expect(server.adoptInheritedS2sLink(snap, false) == null);
    addr.family = posix.AF.INET;
    snap.connect_addr = std.mem.asBytes(&addr);
    try std.testing.expect(server.adoptInheritedS2sLink(snap, false) == null);
    addr.family = posix.AF.INET6;
    addr.port = 0;
    try std.testing.expect(server.adoptInheritedS2sLink(snap, false) == null);
    try std.testing.expectEqual(before, server.rx().clients.len());
    try std.testing.expect(server.mesh_dials[0].token == null);
    try std.testing.expect(server.mesh_dials[0].addr == null);
    _ = try server.boundPort(); // false preserves the carried descriptor.
}

test "GAP-O7 handshake and anti-entropy stalls open a breaker and an unsigned frame stays refused" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    const allocator = std.testing.allocator;
    const specs = [_][]const u8{
        "127.0.0.1:65081",
        "127.0.0.1:65082",
    };
    var sim = reactor_mod.SimReactor.init(50_000);
    const server = createTestServer(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .mesh_connect = &specs,
        .reactor = sim.reactor(),
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer {
        server.deinit();
        allocator.destroy(server);
    }
    current_reactor = &server.reactors[0];
    try std.testing.expectEqual(@as(usize, 2), server.mesh_dials.len);
    server.mesh_dials[0].addr = try sockaddrForHost("127.0.0.1", 65081, 2_000);

    var failure: usize = 0;
    while (failure < 5) : (failure += 1) {
        const id = try server.rx().clients.alloc(ConnState.init(-1));
        const conn = server.rx().clients.get(id).?;
        conn.overflow_allocator = allocator;
        conn.token = try tokenFromId(id);
        server.mesh_dials[0].token = conn.token;
        try server.handleConnect(.{ .token = conn.token, .res = -1 });
        try std.testing.expect(server.rx().clients.get(id) == null);
    }
    try std.testing.expectEqual(circuit_breaker.BreakerState.open, server.mesh_dials[0].breaker.state());
    try std.testing.expectEqual(@as(u32, 5), server.mesh_dials[0].backoff_failures);
    try std.testing.expectEqual(@as(u64, 1), server.mooring_breaker_logs);
    const delay = Server.meshBackoffDelayMs(5);
    try std.testing.expectEqual(backoff.exponential(@as(u64, @intCast(mesh_redial_interval_ms)), 2, @as(u64, @intCast(mesh_redial_interval_ms)) * 32, 4), @as(u64, @intCast(delay)));
    try std.testing.expectEqual(sim.clock_ms + delay, server.mesh_dials[0].retry_not_before_ms);
    var metrics: std.ArrayList(u8) = .empty;
    defer metrics.deinit(allocator);
    try server.stats.writePrometheus(allocator, &metrics);
    try std.testing.expect(std.mem.indexOf(u8, metrics.items, "onyx_mooring_breakers_open 1\n") != null);

    // One more connect failure must not log a second open line.
    {
        const id = try server.rx().clients.alloc(ConnState.init(-1));
        const conn = server.rx().clients.get(id).?;
        conn.overflow_allocator = allocator;
        conn.token = try tokenFromId(id);
        server.mesh_dials[0].token = conn.token;
        try server.handleConnect(.{ .token = conn.token, .res = -1 });
    }
    try std.testing.expectEqual(@as(u64, 1), server.mooring_breaker_logs);
    try std.testing.expectEqual(circuit_breaker.BreakerState.open, server.mesh_dials[0].breaker.state());

    // An unsigned membership frame is still dropped while the breaker is open.
    // Accepting it would be the "keep the link up" path this gauge forbids.
    var sender: s2s_link.S2sLink = undefined;
    try sender.init(.{
        .allocator = allocator,
        .local_node_id = 81,
        .remote_node_id = 82,
        .local_epoch_ms = 100,
        .server_name = "unsigned-peer.test",
    });
    defer sender.deinit();
    const receiver = try allocator.create(s2s_link.S2sLink);
    var receiver_live = true;
    try receiver.init(.{
        .allocator = allocator,
        .local_node_id = 82,
        .remote_node_id = 81,
        .local_epoch_ms = 101,
        .server_name = "breaker.test",
    });
    errdefer if (receiver_live) {
        receiver.deinit();
        allocator.destroy(receiver);
    };
    try std.testing.expect(receiver.peer.config.require_signed_frames);
    try sender.start(102);
    try receiver.start(102);
    try pumpLinkPair(&sender, receiver, allocator);
    try std.testing.expect(receiver.established());
    try sender.sendMembership("#room", "bob", 0, 60, true, .{ .username = "u", .realname = "r", .host = "h" }, "");
    const frame = try allocator.dupe(u8, sender.outbound());
    defer allocator.free(frame);
    sender.clearOutbound();
    try std.testing.expect(frame.len != 0);
    const unsigned_id = try server.rx().clients.alloc(ConnState.init(-1));
    const unsigned = server.rx().clients.get(unsigned_id).?;
    unsigned.overflow_allocator = allocator;
    unsigned.token = try tokenFromId(unsigned_id);
    unsigned.s2s = receiver;
    unsigned.s2s_burst_done = true;
    defer {
        if (server.rx().clients.get(unsigned_id)) |live| live.s2s = null;
        if (receiver_live) {
            receiver.deinit();
            allocator.destroy(receiver);
            receiver_live = false;
        }
    }
    server.driveS2s(unsigned, receiver, frame);
    try std.testing.expect(!unsigned.closing);
    const changes = try receiver.takeMembershipChanges();
    defer {
        for (changes) |*change| change.deinit(allocator);
        allocator.free(changes);
    }
    try std.testing.expectEqual(@as(usize, 0), changes.len);
    try std.testing.expectEqual(circuit_breaker.BreakerState.open, server.mesh_dials[0].breaker.state());
    try std.testing.expect(server.meshDialForConn(unsigned) == null);

    // Cooldown still blocks the retry that the backoff helper would otherwise allow.
    server.config.max_clients = 0;
    const attempt_before = server.mesh_dials[0].last_attempt_ms;
    sim.advance(delay);
    try std.testing.expectEqual(Server.MeshDialAttempt.skipped, server.tryMeshAutoDial(&server.mesh_dials[0], false, sim.clock_ms));
    try std.testing.expectEqual(attempt_before, server.mesh_dials[0].last_attempt_ms);
    const opened = server.mesh_dials[0].breaker.opened_at_ms orelse return error.TestExpectedEqual;
    // The sixth failure refreshed opened_at. Step to the cooldown boundary.
    sim.clock_ms = @as(i64, @intCast(opened)) + @as(i64, @intCast(server.mesh_dials[0].breaker.config.cooldown_ms));
    try std.testing.expectEqual(Server.MeshDialAttempt.attempted, server.tryMeshAutoDial(&server.mesh_dials[0], false, sim.clock_ms));
    try std.testing.expectEqual(sim.clock_ms, server.mesh_dials[0].last_attempt_ms);
    try std.testing.expectEqual(circuit_breaker.BreakerState.half_open, server.mesh_dials[0].breaker.state());
    try std.testing.expectEqual(@as(i64, 0), server.stats.mooring_breakers_open.load(.acquire));

    // Anti-entropy quiet on the second configured peer opens its own breaker.
    var stall_sender: s2s_link.S2sLink = undefined;
    try stall_sender.init(.{
        .allocator = allocator,
        .local_node_id = 83,
        .remote_node_id = 84,
        .local_epoch_ms = 100,
        .server_name = "stall-peer.test",
    });
    defer stall_sender.deinit();
    const stall_receiver = try allocator.create(s2s_link.S2sLink);
    var stall_live = true;
    try stall_receiver.init(.{
        .allocator = allocator,
        .local_node_id = 84,
        .remote_node_id = 83,
        .local_epoch_ms = 101,
        .server_name = "stall-local.test",
    });
    errdefer if (stall_live) {
        stall_receiver.deinit();
        allocator.destroy(stall_receiver);
    };
    try stall_sender.start(102);
    try stall_receiver.start(102);
    try pumpLinkPair(&stall_sender, stall_receiver, allocator);
    try std.testing.expectEqualStrings("stall-peer.test", stall_receiver.remoteName());
    const stall_id = try server.rx().clients.alloc(ConnState.init(-1));
    const stall = server.rx().clients.get(stall_id).?;
    stall.overflow_allocator = allocator;
    stall.token = try tokenFromId(stall_id);
    stall.s2s = stall_receiver;
    // The server now owns the link, including cleanup after a failed assertion.
    stall_live = false;
    stall.s2s_initiator = true;
    server.mesh_dials[1].token = stall.token;
    server.markPeerHealth("stall-peer.test", .established);
    const health = server.peer_health.get("stall-peer.test") orelse return error.TestExpectedEqual;
    // A healthy newly established peer has not missed the first scheduled
    // anti-entropy burst. Runtime tests must use the same grace as production;
    // shortening only the stall threshold would close this live dial early.
    sim.advance(membership_resync_interval_ms - 1);
    try std.testing.expect(server.mooringStallReason(stall, server.nowU64()) == null);
    server.sweepMooringStalls();
    try std.testing.expectEqual(@as(u32, 0), server.mesh_dials[1].backoff_failures);
    try std.testing.expectEqual(circuit_breaker.BreakerState.closed, server.mesh_dials[1].breaker.state());
    try std.testing.expect(server.rx().clients.get(stall_id) != null);
    // The same live peer becomes a real stall when its last completed round
    // lies beyond the production grace; advance the simulator, not real time.
    health.state_since_ms = 0;
    health.last_anti_entropy_ms = 0;
    const logs_before = server.mooring_breaker_logs;
    var stalls: usize = 0;
    while (server.mesh_dials[1].breaker.state() != .open) {
        stalls += 1;
        try std.testing.expect(stalls <= 5);
        const before_failures = server.mesh_dials[1].backoff_failures;
        server.sweepMooringStalls();
        try std.testing.expectEqual(before_failures + 1, server.mesh_dials[1].backoff_failures);
        if (server.mesh_dials[1].breaker.state() == .open) break;
        const wait = server.mesh_dials[1].retry_not_before_ms - sim.clock_ms;
        sim.advance(wait + 1);
    }
    try std.testing.expectEqual(@as(usize, 5), stalls);
    try std.testing.expectEqual(logs_before + 1, server.mooring_breaker_logs);
    try std.testing.expect(server.rx().clients.get(stall_id) == null);
    stall_live = false;
    try std.testing.expectEqual(@as(i64, 1), server.stats.mooring_breakers_open.load(.acquire));
    std.debug.print("GAP-O7 branch=breaker open on handshake and anti-entropy stall, backoff retry, unsigned frame refused\n", .{});
}

test "GAP-O8 mesh ban filter is exchanged before the authoritative list" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    const allocator = std.testing.allocator;

    var pair = try SessionReplayTestPair.init(allocator);
    defer pair.deinit();
    pair.a.clearOutbound();
    pair.b.clearOutbound();

    var sender = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .node_id = pair.ida.shortId(),
        .server_name = "ward-filter-a.test",
        .node_identity = &pair.ida,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer sender.deinit();
    current_reactor = &sender.reactors[0];

    try sender.warden.add(.{
        .match = .address,
        .pattern = "203.0.113.9",
        .scope = .mesh,
        .action = .refuse,
        .reason = "netban",
        .set_by = "oper",
        .created_ms = 1,
    });
    try sender.warden.add(.{
        .match = .address,
        .pattern = "198.51.100.8",
        .scope = .node,
        .action = .expel,
        .reason = "local",
        .set_by = "oper",
        .created_ms = 2,
    });

    var link_conn = ConnState.init(-1);
    link_conn.overflow_allocator = allocator;
    link_conn.send_armed = true;
    link_conn.s2s_secured = &pair.a;
    defer link_conn.s2s_secured = null;
    try std.testing.expect(sender.sendMeshWardsTo(&link_conn));

    const burst = try allocator.dupe(u8, pair.a.outbound());
    defer allocator.free(burst);
    pair.a.clearOutbound();
    try std.testing.expect(burst.len != 0);
    try pair.b.feed(burst, 800);
    const received = try pair.b.takeWards();
    defer {
        for (received) |wire| allocator.free(wire);
        allocator.free(received);
    }
    try std.testing.expectEqual(@as(usize, 2), received.len);
    var exchanged = try warden.decodeMeshBanFilter(allocator, received[0]);
    defer exchanged.deinit();
    try std.testing.expect(exchanged.mayContain(.address, "203.0.113.9"));
    try std.testing.expect(!exchanged.mayContain(.address, "198.51.100.8"));
    const add = try warden.decodeWire(received[1]);
    try std.testing.expectEqual(warden.WireOp.add, add.op);
    try std.testing.expectEqualStrings("203.0.113.9", add.pattern);

    var receiver = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer receiver.deinit();
    current_reactor = &receiver.reactors[0];

    try std.testing.expect(!receiver.ingestMeshWardPayload(received[0]));
    try std.testing.expectEqual(@as(usize, 0), receiver.warden.count());
    try std.testing.expect(receiver.mesh_ban_filter != null);

    var client = ConnState.init(-1);
    client.overflow_allocator = allocator;
    client.send_armed = true;
    defer if (client.send_overflow.capacity > 0) client.send_overflow.deinit(allocator);
    client.session.setRealHost("203.0.113.9");
    try std.testing.expect(!receiver.enforceWard(&client));
    try std.testing.expect(!client.closing);
    try std.testing.expectEqual(@as(u64, 1), receiver.mesh_ban_filter_rechecks);

    try std.testing.expect(receiver.ingestMeshWardPayload(received[1]));
    try std.testing.expectEqual(@as(usize, 1), receiver.warden.count());
    try std.testing.expect(receiver.enforceWard(&client));
    try std.testing.expect(client.closing);
    try std.testing.expectEqual(@as(u64, 1), receiver.mesh_ban_filter_rechecks);

    var bystander = ConnState.init(-1);
    bystander.overflow_allocator = allocator;
    bystander.send_armed = true;
    defer if (bystander.send_overflow.capacity > 0) bystander.send_overflow.deinit(allocator);
    bystander.session.setRealHost("192.0.2.1");
    try std.testing.expect(!receiver.enforceWard(&bystander));
    try std.testing.expect(!bystander.closing);

    try receiver.warden.add(.{
        .match = .address,
        .pattern = "198.51.100.8",
        .scope = .node,
        .action = .expel,
        .reason = "local",
        .set_by = "oper",
        .created_ms = 3,
    });
    var local = ConnState.init(-1);
    local.overflow_allocator = allocator;
    local.send_armed = true;
    defer if (local.send_overflow.capacity > 0) local.send_overflow.deinit(allocator);
    local.session.setRealHost("198.51.100.8");
    try std.testing.expect(receiver.enforceWard(&local));
    try std.testing.expect(local.closing);
    try std.testing.expectEqual(@as(u64, 1), receiver.mesh_ban_filter_rechecks);

    current_reactor = null;
    std.debug.print("GAP-O8 branch=filter exchanged before the ward list; a hit is re-checked and is not the authority\n", .{});
}

test "SIGUSR2 handler sets the upgrade-request flag; reactor-0 consume is one-shot" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        // Deterministic, execve-safe: drive the handler directly (it only stores the
        // flag) and consume it the same way `onTimerTick` does — never installs a
        // process signal handler and never runs a reactor, so there is no path to an
        // actual re-exec inside the test binary.
        upgrade_signal_requested.store(false, .seq_cst);
        onUpgradeSignal(posix.SIG.USR2);
        try std.testing.expect(upgrade_signal_requested.load(.seq_cst));
        // First consume observes the request and clears it.
        try std.testing.expect(upgrade_signal_requested.swap(false, .seq_cst));
        // A second consume sees nothing — exactly one upgrade per signal.
        try std.testing.expect(!upgrade_signal_requested.swap(false, .seq_cst));
    } else return error.SkipZigTest;
}

test "UPGRADE refuses an incompatible target before listener or client CLOEXEC mutation" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    defer current_reactor = null;

    var sockets: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets)) != .SUCCESS)
        return error.SkipZigTest;
    var client_fd_owned = true;
    defer if (client_fd_owned) closeFd(sockets[0]);
    defer closeFd(sockets[1]);

    // /bin/true opens and executes successfully but does not advertise the
    // exact Helix handoff contract. This exercises capability incompatibility,
    // rather than merely a missing launch path.
    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
        .exe_path = "/bin/true",
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const id = try addTestLocalClient(&server, "UpgradePinned", null);
    const conn = server.rx().clients.get(id) orelse return error.TestUnexpectedResult;
    conn.fd = sockets[0];
    conn.session.registration.registered = true;
    client_fd_owned = false;

    const listener_fd = server.reactors[0].listener_fd;
    try std.testing.expect(setCloexec(listener_fd, true));
    try std.testing.expect(setCloexec(conn.fd, true));
    try std.testing.expectError(error.UpgradeTargetIncompatible, server.performUpgrade(.signal));

    const listener_flags = linux.fcntl(listener_fd, posix.F.GETFD, 0);
    const client_flags = linux.fcntl(conn.fd, posix.F.GETFD, 0);
    try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(listener_flags));
    try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(client_flags));
    try std.testing.expect((listener_flags & posix.FD_CLOEXEC) != 0);
    try std.testing.expect((client_flags & posix.FD_CLOEXEC) != 0);
    try std.testing.expectEqual(@as(usize, 1), server.reactors[0].clients.len());
}

test "MARKREAD UPGRADE refuses a v4-only executable preserving private carried ciphertext" {
    if (comptime builtin.os.tag != .linux or builtin.cpu.arch != .x86_64) return error.SkipZigTest;
    defer current_reactor = null;
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    // A tiny executable prints the exact frozen predecessor line. Unlike an
    // interpreter script, this ELF remains executable through the probe's
    // pinned CLOEXEC /proc/self/fd path. Its only syscalls are write and exit.
    const old_reply = helix_live.predecessor_v4_upgrade_capability_token ++ "\n";
    var image: [161 + old_reply.len]u8 = @splat(0);
    @memcpy(image[0..7], "\x7fELF\x02\x01\x01");
    std.mem.writeInt(u16, image[16..18], 2, .little); // ET_EXEC
    std.mem.writeInt(u16, image[18..20], 62, .little); // EM_X86_64
    std.mem.writeInt(u32, image[20..24], 1, .little);
    std.mem.writeInt(u64, image[24..32], 0x400080, .little);
    std.mem.writeInt(u64, image[32..40], 64, .little);
    std.mem.writeInt(u16, image[52..54], 64, .little);
    std.mem.writeInt(u16, image[54..56], 56, .little);
    std.mem.writeInt(u16, image[56..58], 1, .little);
    std.mem.writeInt(u32, image[64..68], 1, .little); // PT_LOAD
    std.mem.writeInt(u32, image[68..72], 5, .little); // read + execute
    std.mem.writeInt(u64, image[80..88], 0x400000, .little);
    std.mem.writeInt(u64, image[88..96], 0x400000, .little);
    std.mem.writeInt(u64, image[96..104], image.len, .little);
    std.mem.writeInt(u64, image[104..112], image.len, .little);
    std.mem.writeInt(u64, image[112..120], 4096, .little);
    @memcpy(image[128..161], &[_]u8{
        0xb8, 1, 0, 0, 0, // mov eax, SYS_write
        0xbf, 1, 0, 0, 0, // mov edi, stdout
        0x48, 0x8d, 0x35, 16, 0, 0, 0, // lea rsi, [rip + reply]
        0xba, 0, 0, 0, 0, // mov edx, reply length
        0x0f, 0x05, // syscall
        0xb8, 60, 0, 0, 0, // mov eax, SYS_exit
        0x31, 0xff, // xor edi, edi
        0x0f, 0x05, // syscall
    });
    std.mem.writeInt(u32, image[146..150], old_reply.len, .little);
    @memcpy(image[161..], old_reply);
    try tmp.dir.writeFile(std.testing.io, .{ .sub_path = "v4-only-reader", .data = &image, .flags = .{ .permissions = .executable_file } });
    var path_buf: [256]u8 = undefined;
    const old_path = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/v4-only-reader", .{tmp.sub_path});
    const probe = try std.process.run(alloc, std.testing.io, .{ .argv = &.{ old_path, helix_live.upgrade_capability_arg } });
    defer alloc.free(probe.stdout);
    defer alloc.free(probe.stderr);
    try std.testing.expect(probe.term.success());
    try std.testing.expectEqualStrings(old_reply, probe.stdout);
    try std.testing.expect(!helix_live.hasUpgradeCapabilityLine(probe.stdout));

    const pair = try alloc.create(SessionReplayTestPair);
    defer alloc.destroy(pair);
    pair.* = try SessionReplayTestPair.init(alloc);
    defer pair.deinit();
    var store = try services_mod.OroStore.open(alloc, std.testing.io, tmp.dir, "v4-refusal.wal");
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    const server = try readMarkerServerForTest(alloc, &services, &pair.ida);
    defer alloc.destroy(server);
    defer server.deinit();
    server.config.exe_path = old_path;
    const client_id = try readMarkerClientForTest(server, "PrivateOwner", "carol");
    const client = server.connFor(client_id).?;
    var sockets: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets)) != .SUCCESS) return error.SkipZigTest;
    defer closeFd(sockets[1]);
    client.fd = sockets[0];
    client.send_armed = true;
    try readMarkerLineForTest(server, client_id, "MARKREAD #private timestamp=2026-06-04T12:00:00.000Z");
    const client_pending = try copyTestSendQ(alloc, client);
    defer alloc.free(client_pending);
    try std.testing.expect(std.mem.indexOf(u8, client_pending, "MARKREAD #private timestamp=") != null);

    const mesh_id = try server.rx().clients.alloc(ConnState.init(-1));
    const mesh = server.rx().clients.get(mesh_id).?;
    mesh.token = try tokenFromId(mesh_id);
    mesh.overflow_allocator = alloc;
    mesh.send_armed = true;
    mesh.s2s_secured = &pair.a;
    defer mesh.s2s_secured = null; // The pair, rather than Server, owns this link.
    try std.testing.expect(server.sendReadMarkerBurstTo(mesh));
    const encrypted = try alloc.dupe(u8, pair.a.outbound());
    defer alloc.free(encrypted);
    try std.testing.expect(encrypted.len > 7);
    try rawAppendToConn(mesh, encrypted);
    pair.a.clearOutbound();
    // Separate consecutive records occupy the connection queue and the outer
    // link queue. Neither queue claims ownership of the other's ciphertext.
    try std.testing.expect(server.sendReadMarkerBurstTo(mesh));
    const outer_pending = try alloc.dupe(u8, pair.a.outbound());
    defer alloc.free(outer_pending);
    try pair.a.rec_inbuf.appendSlice(alloc, encrypted[0..7]);
    const mesh_pending = try copyTestSendQ(alloc, mesh);
    defer alloc.free(mesh_pending);
    const send_counter = pair.a.send_counter;
    const receive_counter = pair.a.recv_counter;
    const marker_clock = server.read_marker_clock;
    const durable_sequence = store.next_seq;
    var facts = server.read_marker_facts.valueIterator();
    const retained = try alloc.dupe(u8, facts.next().?.*);
    defer alloc.free(retained);
    const listener_fd = server.reactors[0].listener_fd;
    try std.testing.expect(setCloexec(listener_fd, true));
    try std.testing.expect(setCloexec(client.fd, true));

    // The exact reader gate precedes all upgrade staging and fd mutation.
    try std.testing.expectError(error.UpgradeTargetIncompatible, server.openCompatibleUpgradeTarget(old_path));
    try std.testing.expect((linux.fcntl(listener_fd, posix.F.GETFD, 0) & posix.FD_CLOEXEC) != 0);
    try std.testing.expect((linux.fcntl(client.fd, posix.F.GETFD, 0) & posix.FD_CLOEXEC) != 0);
    try std.testing.expectEqual(@as(usize, 2), server.reactors[0].clients.len());
    const client_after = try copyTestSendQ(alloc, client);
    defer alloc.free(client_after);
    const mesh_after = try copyTestSendQ(alloc, mesh);
    defer alloc.free(mesh_after);
    try std.testing.expectEqualSlices(u8, client_pending, client_after);
    try std.testing.expectEqualSlices(u8, mesh_pending, mesh_after);
    try std.testing.expectEqualSlices(u8, outer_pending, pair.a.outbound());
    try std.testing.expectEqualSlices(u8, encrypted[0..7], pair.a.rec_inbuf.items);
    try std.testing.expectEqual(send_counter, pair.a.send_counter);
    try std.testing.expectEqual(receive_counter, pair.a.recv_counter);
    try std.testing.expectEqualDeep(marker_clock, server.read_marker_clock);
    try std.testing.expectEqual(durable_sequence, store.next_seq);
    facts = server.read_marker_facts.valueIterator();
    try std.testing.expectEqualSlices(u8, retained, facts.next().?.*);

    // The public upgrade entry point emits its ordinary signed refusal audit.
    // That flush is permitted to transfer the pending outer record to SendQ,
    // but it must preserve the exact encrypted prefix and physical ownership.
    try std.testing.expectError(error.UpgradeTargetIncompatible, server.performUpgrade(.signal));
    const audited_pending = try copyTestSendQ(alloc, mesh);
    defer alloc.free(audited_pending);
    try std.testing.expect(audited_pending.len > mesh_pending.len + outer_pending.len);
    try std.testing.expectEqualSlices(u8, mesh_pending, audited_pending[0..mesh_pending.len]);
    try std.testing.expectEqualSlices(u8, outer_pending, audited_pending[mesh_pending.len..][0..outer_pending.len]);
    try std.testing.expectEqual(@as(usize, 0), pair.a.outbound().len);
    try std.testing.expectEqual(send_counter + 1, pair.a.send_counter);
    try std.testing.expectEqual(receive_counter, pair.a.recv_counter);
    try std.testing.expectEqualSlices(u8, encrypted[0..7], pair.a.rec_inbuf.items);
    try std.testing.expect((linux.fcntl(listener_fd, posix.F.GETFD, 0) & posix.FD_CLOEXEC) != 0);
    try std.testing.expect((linux.fcntl(client.fd, posix.F.GETFD, 0) & posix.FD_CLOEXEC) != 0);
    try std.testing.expectEqualDeep(marker_clock, server.read_marker_clock);
    try std.testing.expectEqual(durable_sequence, store.next_seq);
    const client_audited = try copyTestSendQ(alloc, client);
    defer alloc.free(client_audited);
    try std.testing.expectEqualSlices(u8, client_pending, client_audited);
    facts = server.read_marker_facts.valueIterator();
    try std.testing.expectEqualSlices(u8, retained, facts.next().?.*);
    try pair.b.feed(audited_pending, 900);
    const carried_facts = try pair.b.takeEntityPropChanges();
    defer {
        for (carried_facts) |*change| change.deinit(alloc);
        alloc.free(carried_facts);
    }
    try std.testing.expectEqual(@as(usize, 2), carried_facts.len);
    const signed = try entity_prop_event.decode(retained);
    for (carried_facts) |change| {
        try std.testing.expectEqualStrings(signed.key, change.key);
        try std.testing.expectEqualStrings(signed.value, change.value);
        try std.testing.expectEqualSlices(u8, signed.origin_sig, change.origin_sig);
    }
    const audit = try pair.b.takeOperEventsV2();
    defer {
        for (audit) |*item| item.deinit(alloc);
        alloc.free(audit);
    }
    try std.testing.expectEqual(@as(usize, 1), audit.len);
    const audit_event = try oper_event.decodeV2(audit[0].wire);
    try std.testing.expectEqualStrings("UPGRADE refused: target binary failed exact Helix capability probe", audit_event.message);
    try std.testing.expectEqual(oper_event.VerifyOutcome.verified, oper_event.verifyOrigin(audit_event));
}

test "failed inherited client adoption does not advance HLC or queue carried output" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    defer current_reactor = null;

    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var server = Server.init(failing.allocator(), .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    // Server teardown allocates no new state, but it must be allowed to free
    // everything even if an assertion below exits the test early.
    defer failing.fail_index = std.math.maxInt(usize);

    var sockets: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets)) != .SUCCESS)
        return error.SkipZigTest;
    var inherited_fd_unconsumed = true;
    defer if (inherited_fd_unconsumed) closeFd(sockets[0]);
    defer closeFd(sockets[1]);

    const clock_before = server.mesh_clock;
    const msg_seq_before = server.msg_seq;
    const sqes_before = server.reactors[0].ring.inner.sq_ready();
    // ConnState allocation is capacity-reserved and the carried SendQ fits
    // inline. Fail the next heap request, which is world nick publication,
    // after the old ordering had already stamped HLC and queued SEND.
    failing.fail_index = failing.alloc_index;
    const adopted = server.adoptInheritedClient(.{
        .fd = sockets[0],
        .nick = "Rollback",
        .realname = "Rollback",
        .pending_out = ":onyx NOTICE Rollback :carried\r\n",
    }, null, null, true);
    failing.fail_index = std.math.maxInt(usize);
    inherited_fd_unconsumed = false; // adoption either owns it or closed it

    try std.testing.expect(!adopted);
    try std.testing.expect(failing.has_induced_failure);
    try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(sockets[0], posix.F.GETFD, 0)));
    try std.testing.expectEqual(clock_before.last_physical, server.mesh_clock.last_physical);
    try std.testing.expectEqual(clock_before.last_stamp, server.mesh_clock.last_stamp);
    try std.testing.expectEqual(msg_seq_before, server.msg_seq);
    try std.testing.expectEqual(sqes_before, server.reactors[0].ring.inner.sq_ready());
    try std.testing.expectEqual(@as(usize, 0), server.reactors[0].clients.len());
}

test "current Helix adoption rederives only configured-local operator authority" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    defer current_reactor = null;

    var cfg = operTestConfig(0);
    cfg.oper_auto_override = true;
    var server = Server.init(std.testing.allocator, cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    var admin_sockets: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &admin_sockets)) != .SUCCESS)
        return error.SkipZigTest;
    var admin_fd_unconsumed = true;
    defer if (admin_fd_unconsumed) closeFd(admin_sockets[0]);
    defer closeFd(admin_sockets[1]);

    // The carried grant block is deliberately forged and must be ignored. The
    // matching authenticated account is re-projected exclusively from the live,
    // sealed configured-local binding on the successor.
    try std.testing.expect(server.adoptInheritedClient(.{
        .fd = admin_sockets[0],
        .nick = "HelixAdmin",
        .realname = "Helix Admin",
        .account = "admin",
        .logged_in = true,
        .is_oper = true,
        .oper_priv_bits = oper_mod.OperPrivileges.initMany(&.{.client_kill}).toBits(),
        .oper_class = "forged",
        .oper_title = "Forged title",
    }, null, null, true));
    admin_fd_unconsumed = false;

    const admin_wid = server.world.findNick("HelixAdmin") orelse return error.TestUnexpectedResult;
    const admin = server.connFor(clientIdFromWorld(admin_wid)) orelse return error.TestUnexpectedResult;
    try std.testing.expect(admin.session.isOper());
    try std.testing.expectEqual(
        oper_session_provenance.Source.configured_local,
        std.meta.activeTag(admin.session.operProvenance()),
    );
    try std.testing.expectEqual(oper_mod.OperPrivileges.full.toBits(), admin.session.oper_priv.toBits());
    try std.testing.expectEqualStrings("netadmin", admin.session.operClass());
    try std.testing.expectEqualStrings("", admin.session.operTitle());
    try std.testing.expect(admin.session.hasUmode(.override));
    try std.testing.expect(server.isOverrideOper("HelixAdmin"));

    var plain_sockets: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &plain_sockets)) != .SUCCESS)
        return error.SkipZigTest;
    var plain_fd_unconsumed = true;
    defer if (plain_fd_unconsumed) closeFd(plain_sockets[0]);
    defer closeFd(plain_sockets[1]);

    // A nonconfigured account remains non-oper even when every historical carry
    // field falsely claims full authority.
    try std.testing.expect(server.adoptInheritedClient(.{
        .fd = plain_sockets[0],
        .nick = "HelixPlain",
        .realname = "Helix Plain",
        .account = "plain",
        .logged_in = true,
        .is_oper = true,
        .oper_priv_bits = oper_mod.OperPrivileges.full.toBits(),
        .oper_class = "netadmin",
        .oper_title = "Forged administrator",
    }, null, null, true));
    plain_fd_unconsumed = false;

    const plain_wid = server.world.findNick("HelixPlain") orelse return error.TestUnexpectedResult;
    const plain = server.connFor(clientIdFromWorld(plain_wid)) orelse return error.TestUnexpectedResult;
    try std.testing.expect(!plain.session.isOper());
    try std.testing.expectEqual(
        oper_session_provenance.Source.none,
        std.meta.activeTag(plain.session.operProvenance()),
    );
    try std.testing.expectEqual(@as(u64, 0), plain.session.oper_priv.toBits());
    try std.testing.expectEqualStrings("", plain.session.operClass());
    try std.testing.expectEqualStrings("", plain.session.operTitle());
    try std.testing.expect(!plain.session.hasUmode(.override));
    try std.testing.expect(!server.isOverrideOper("HelixPlain"));

    const watcher_id = try addTestLocalClient(&server, "HelixWatcher", null);
    const watcher = server.connFor(watcher_id) orelse return error.TestUnexpectedResult;
    watcher.session.registration.registered = true;
    try server.world.restoreMember("#helix-oper", admin_wid, world_model.MemberModes.empty());
    try server.world.restoreMember("#helix-oper", plain_wid, world_model.MemberModes.empty());
    try server.world.restoreMember("#helix-oper", worldIdFromClient(watcher_id), world_model.MemberModes.empty());
    try server.sendNames(watcher, "#helix-oper");
    try expectContains(watcher.send_buf[0..watcher.send_len], "*HelixAdmin");
    try std.testing.expect(std.mem.indexOf(u8, watcher.send_buf[0..watcher.send_len], "*HelixPlain") == null);
}

test "current Helix adoption resumes a fragmented binary WebSocket message" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    defer current_reactor = null;
    const allocator = std.testing.allocator;

    var server = Server.init(allocator, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    var sockets: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets)) != .SUCCESS)
        return error.SkipZigTest;
    var inherited_fd_unconsumed = true;
    defer if (inherited_fd_unconsumed) closeFd(sockets[0]);
    defer closeFd(sockets[1]);

    const opening_payload = "cadence-opening-prefix";
    const encoded = try ws_snapshot.encode(allocator, .{
        .fd = sockets[0],
        .phase_open = true,
        .fragmented = true,
        .msg_binary = true,
        .subprotocol = .onyx_irc_media,
        .binary_message_active = true,
        .binary_message = opening_payload,
    });
    defer allocator.free(encoded);
    const carried = try ws_snapshot.decodeCurrent(encoded);

    const adopted = server.adoptInheritedClient(.{
        .fd = sockets[0],
        .nick = "ResumeWS",
        .realname = "Resume WS",
        .was_websocket = true,
    }, null, carried, true);
    inherited_fd_unconsumed = false; // successor owns it, or adoption closed it
    try std.testing.expect(adopted);

    var it = server.rx().clients.iterator();
    const entry = it.next() orelse return error.TestUnexpectedResult;
    const conn = entry.value;
    const ws = conn.ws orelse return error.TestUnexpectedResult;
    try std.testing.expect(ws.binary_message_active);
    try std.testing.expect(ws.deframer.fragmented and ws.deframer.msg_binary);
    try std.testing.expectEqual(websocket.Subprotocol.onyx_irc_media, ws.subprotocol.?);
    try std.testing.expectEqualStrings(opening_payload, ws.binary_message_buf[0..ws.binary_message_len]);

    const tail = "-final-continuation";
    var final_buf: [128]u8 = undefined;
    const final = try websocket.encodeFrame(WsState.max_media_frame, .{
        .opcode = .continuation,
        .mask_key = .{ 1, 2, 3, 4 },
    }, tail, &final_buf);
    try server.driveWs(entry.id, conn, final);
    try std.testing.expect(!conn.closing);
    try std.testing.expect(!ws.binary_message_active and !ws.deframer.fragmented);
    try std.testing.expectEqual(@as(usize, 0), ws.binary_message_len);
    try std.testing.expectEqualStrings(opening_payload ++ tail, ws.binary_message_buf[0 .. opening_payload.len + tail.len]);
}

test "failed inherited TLS plus WebSocket adoption frees carried SendQ overflow" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    const Ed25519 = std.crypto.sign.Ed25519;
    const x509_selfsign = @import("../proto/x509_selfsign.zig");
    defer current_reactor = null;

    const kp = try Ed25519.KeyPair.generateDeterministic(@as([Ed25519.KeyPair.seed_length]u8, @splat(0x7a)));
    var cert_buf: [1024]u8 = undefined;
    const der = try x509_selfsign.buildSelfSigned(&cert_buf, .{
        .common_name = "rollback.test",
        .not_before = 1_704_067_200,
        .not_after = 4_102_444_800,
        .serial = &.{ 0x7a, 0x01 },
        .key_pair = kp,
        .dns_names = &.{"rollback.test"},
        .is_ca = true,
    });
    const chain = [_][]const u8{der};
    var server = Server.init(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_cert_chain = &chain,
        .tls_signing_key = kp,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    var sockets: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sockets)) != .SUCCESS)
        return error.SkipZigTest;
    var inherited_fd_unconsumed = true;
    defer if (inherited_fd_unconsumed) closeFd(sockets[0]);
    defer closeFd(sockets[1]);

    // One byte beyond the inline buffer guarantees adoptTlsState owns a heap
    // SendQ overflow before WebSocket restoration rejects the oversized
    // partial line. Pool.free alone does not deinit that stale slot value.
    const carried = try alloc.alloc(u8, default_reply_bytes + 1);
    defer alloc.free(carried);
    @memset(carried, 0xa5);
    const oversized_ws_tail = try alloc.alloc(u8, WsState.max_frame + 1);
    defer alloc.free(oversized_ws_tail);

    const adopted = server.adoptInheritedClient(.{
        .fd = sockets[0],
        .nick = "RollbackWss",
        .realname = "Rollback WSS",
        .was_secured = true,
    }, .{
        .kernel_tx_prefix_remaining = 0,
        .fd = sockets[0],
        .state = .{ .barrier_phase = .none, .held_record_len = 0, .engine = .{ .tls13 = .{
            .suite = 0x1302,
            .client_app_secret = @splat(0x11),
            .server_app_secret = @splat(0x22),
            .app_read_seq = 7,
            .app_write_seq = 9,
            .peer_record_size_limit_raw = 16385,
            .local_receive_policy = 16385,
            .record_size_limit_negotiated = false,
            .selected_alpn = &.{},
            .exporter_master_secret = @splat(0),
            .exporter_master_secret_ready = true,
            .ku_prefix_len = 0,
            .ku_prefix = @splat(0),
        } } },
        .pending_out = carried,
    }, .{
        .fd = sockets[0],
        .phase_open = true,
        .tx = oversized_ws_tail,
    }, true);
    inherited_fd_unconsumed = false;

    try std.testing.expect(!adopted);
    try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(sockets[0], posix.F.GETFD, 0)));
    try std.testing.expectEqual(@as(usize, 0), server.reactors[0].clients.len());
}

test "threaded server: [mesh].connect auto-links two nodes without an oper" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const alloc = std.testing.allocator;

        // Node 2 (the dial target) boots first so its ephemeral S2S port is known
        // before node 1's config is built.
        var node2 = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .s2s_port = 0,
            .node_id = 2,
            .server_name = "node2.test",
            .num_shards = 2,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer node2.deinit();
        const s2s_port = node2.s2sBoundPort() catch return error.SkipZigTest;
        var run2 = std.atomic.Value(bool).init(true);
        var thr2 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node2, &run2 });
        defer {
            node2.requestStop(&run2);
            thr2.join();
        }

        // Node 1 carries node 2 in [mesh].connect — NO oper session, no CONNECT
        // command: the boot pass must dial and link on its own.
        var spec_buf: [32]u8 = undefined;
        const spec = try std.fmt.bufPrint(&spec_buf, "127.0.0.1:{d}", .{s2s_port});
        const peers = [_][]const u8{spec};
        var node1 = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .s2s_port = 0,
            .node_id = 1,
            .server_name = "node1.test",
            .mesh_connect = &peers,
            .num_shards = 2,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer node1.deinit();
        const port1 = node1.boundPort() catch return error.SkipZigTest;
        var run1 = std.atomic.Value(bool).init(true);
        var thr1 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node1, &run1 });
        defer {
            node1.requestStop(&run1);
            thr1.join();
        }

        // Observable readiness gate (same shape as the oper CONNECT test): a plain
        // client on node 1 polls LINKS until node 2's handshake-learned name shows,
        // proving the auto-dialed S2S link established without any oper command.
        const fd_c = connectLoopback(port1) catch return error.SkipZigTest;
        defer closeFd(fd_c);
        var c = LiveClient{ .fd = fd_c };
        try writeAllFd(fd_c, "NICK C\r\nUSER carol 0 * :Carol\r\n");
        try recvUntil(&c, " 001 C ", 200);

        var linked = false;
        var probes: usize = 0;
        while (probes < 120 and !linked) : (probes += 1) {
            c.reset();
            try writeAllFd(fd_c, "LINKS\r\n");
            recvUntil(&c, " 365 ", 80) catch {};
            if (std.mem.indexOf(u8, c.written(), "node2.test") != null) linked = true;
        }
        try std.testing.expect(linked);

        // Remote WHOIS via the mesh projection: D joins a channel on node 2; once
        // the membership gossip lands, node 1 answers WHOIS D from the converged
        // roster — 311 with the placeholder identity (user "mesh", host = origin)
        // and 312 naming D's actual home server, not the local one.
        const fd_d = connectLoopback(node2.boundPort() catch 0) catch return error.SkipZigTest;
        defer closeFd(fd_d);
        var d = LiveClient{ .fd = fd_d };
        try writeAllFd(fd_d, "NICK D\r\nUSER dave 0 * :Dave\r\n");
        try recvUntil(&d, " 001 D ", 200);
        try writeAllFd(fd_d, "JOIN #mesh\r\n");
        try recvUntil(&d, "JOIN", 200);

        var whois_seen = false;
        probes = 0;
        while (probes < 120 and !whois_seen) : (probes += 1) {
            c.reset();
            try writeAllFd(fd_c, "WHOIS D\r\n");
            // " C D " arrives on BOTH outcomes (401 C D / 311 C D), so a miss
            // cycles quickly instead of riding out the full recvUntil budget.
            recvUntil(&c, " C D ", 200) catch {};
            if (std.mem.indexOf(u8, c.written(), " 311 C D ") != null) {
                recvUntil(&c, " 318 C D ", 200) catch {};
                const got = c.written();
                if (std.mem.indexOf(u8, got, " 311 C D mesh node2.test ") != null and
                    std.mem.indexOf(u8, got, " 312 C D node2.test ") != null) whois_seen = true;
            }
        }
        try std.testing.expect(whois_seen);
    } else return error.SkipZigTest;
}

fn reserveTwoLoopbackPorts() ServerError!struct { u16, u16 } {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const fd1 = try createListener("127.0.0.1", 0, 8);
        defer closeFd(fd1);
        const fd2 = try createListener("127.0.0.1", 0, 8);
        defer closeFd(fd2);
        return .{ try socketPort(fd1), try socketPort(fd2) };
    } else return error.Unsupported;
}

fn reserveThreeLoopbackPorts() ServerError!struct { u16, u16, u16 } {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const fd1 = try createListener("127.0.0.1", 0, 8);
        defer closeFd(fd1);
        const fd2 = try createListener("127.0.0.1", 0, 8);
        defer closeFd(fd2);
        const fd3 = try createListener("127.0.0.1", 0, 8);
        defer closeFd(fd3);
        return .{ try socketPort(fd1), try socketPort(fd2), try socketPort(fd3) };
    } else return error.Unsupported;
}

/// Heavyweight mesh acceptance tests temporarily release their probed S2S
/// ports before the real listeners bind them. Multiple copies of the tests
/// running in separate Zig test processes can otherwise reserve the same ports,
/// authenticate each other's identical fixtures, and produce a false topology
/// timeout or silently Skip on AddressInUse. One advisory kernel lock serializes
/// these cross-process fixtures; a crashed test releases it automatically.
fn acquireHeavyMeshAcceptanceTestLock() !linux.fd_t {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const open_rc = linux.open(
        "/tmp/onyx-heavy-mesh-acceptance-test.lock",
        .{ .ACCMODE = .RDWR, .CREAT = true, .CLOEXEC = true },
        0o600,
    );
    if (linux.errno(open_rc) != .SUCCESS) return error.TestUnexpectedResult;
    const fd: linux.fd_t = @intCast(open_rc);
    errdefer closeFd(fd);
    while (true) {
        const lock_rc = linux.flock(fd, 2); // LOCK_EX
        switch (linux.errno(lock_rc)) {
            .SUCCESS => return fd,
            .INTR => continue,
            else => return error.TestUnexpectedResult,
        }
    }
}

fn testSleepMs(ms: isize) void {
    if (comptime builtin.os.tag == .openbsd) {
        os_runtime.sleepMillis(@intCast(@max(ms, 0)));
        return;
    }
    var ts = linux.timespec{
        .sec = @divFloor(ms, 1000),
        .nsec = @mod(ms, 1000) * @as(isize, std.time.ns_per_ms),
    };
    _ = linux.nanosleep(&ts, null);
}

fn expectMeshPeerVisible(client: *LiveClient, peer_name: []const u8, max_probes: usize) !void {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var probes: usize = 0;
        while (probes < max_probes) : (probes += 1) {
            client.reset();
            try writeAllFd(client.fd, "LINKS\r\nLUSERS\r\n");
            const deadline = platform.monotonicMillis() + 250;
            while (platform.monotonicMillis() < deadline) {
                var fds = [_]posix.pollfd{.{ .fd = client.fd, .events = posix.POLL.IN, .revents = 0 }};
                const ready = posix.poll(&fds, 20) catch return error.Unexpected;
                if (ready != 0 and (fds[0].revents & posix.POLL.IN) != 0) try client.readAvailable();
                const got_now = client.written();
                if (std.mem.indexOf(u8, got_now, " 365 ") != null and
                    std.mem.indexOf(u8, got_now, " 255 ") != null) break;
            }
            const got = client.written();
            if (std.mem.indexOf(u8, got, peer_name) != null and
                std.mem.indexOf(u8, got, " on 2 servers") != null) return;
            testSleepMs(25);
        }
        return error.TestTimeout;
    } else return error.SkipZigTest;
}

fn expectMeshPeersVisible(client: *LiveClient, peer_names: []const []const u8, max_probes: usize) !void {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        var probes: usize = 0;
        while (probes < max_probes) : (probes += 1) {
            client.reset();
            try writeAllFd(client.fd, "LINKS\r\n");
            const deadline = platform.monotonicMillis() + 250;
            while (platform.monotonicMillis() < deadline) {
                var fds = [_]posix.pollfd{.{ .fd = client.fd, .events = posix.POLL.IN, .revents = 0 }};
                const ready = posix.poll(&fds, 20) catch return error.Unexpected;
                if (ready != 0 and (fds[0].revents & posix.POLL.IN) != 0) try client.readAvailable();
                if (std.mem.indexOf(u8, client.written(), " 365 ") != null) break;
            }
            const got = client.written();
            var all_visible = std.mem.indexOf(u8, got, " 365 ") != null;
            for (peer_names) |peer_name| {
                if (std.mem.indexOf(u8, got, peer_name) == null) {
                    all_visible = false;
                    break;
                }
            }
            if (all_visible) return;
            testSleepMs(25);
        }
        return error.TestTimeout;
    } else return error.SkipZigTest;
}

fn countMeshLogDetail(server: *const LinuxServer, detail: []const u8) usize {
    var n: usize = 0;
    var it = server.mesh_log.iterator();
    while (it.next()) |ev| {
        if (std.mem.eql(u8, ev.detail, detail)) n += 1;
    }
    return n;
}

fn dumpMeshDialProofForTest(server: *Server) void {
    server.world.lockWrite();
    defer server.world.unlockWrite();
    for (server.reactors) |*reactor| {
        var it = reactor.clients.iterator();
        while (it.next()) |entry| {
            const conn = entry.value;
            if (conn.s2s == null and conn.s2s_secured == null) continue;
            var bound = false;
            for (server.mesh_dials) |dial| {
                if (dial.token) |token| {
                    if (token.slot == conn.token.slot and token.gen == conn.token.gen) bound = true;
                }
            }
            std.debug.print("mesh proof node={s} shard={d} fd={d} token={d}/{d} peer={s} initiator={} known={} target_port={d} bound={} dedup={} closing={} connect={} recv={} send={} backlog={d}\n", .{
                server.serverName(),                               reactor.shard_id,   conn.fd,                    conn.token.slot,                                                                                       conn.token.gen,
                Server.establishedPeerName(conn) orelse "pending", conn.s2s_initiator, conn.s2s_dial_target_known, if (conn.s2s_dial_target_known) std.mem.bigToNative(u16, conn.s2s_connect_addr.port) else @as(u16, 0), bound,
                conn.s2s_dedup,                                    conn.closing,       conn.connect_armed,         conn.recv_armed,                                                                                       conn.send_armed,
                connSendBacklog(conn),
            });
            var others = reactor.clients.iterator();
            while (others.next()) |other| {
                if (other.value == conn or (other.value.s2s == null and other.value.s2s_secured == null)) continue;
                std.debug.print("mesh proof identity tokens={d}/{d},{d}/{d} same_full_peer={}\n", .{
                    conn.token.slot,                       conn.token.gen, other.value.token.slot, other.value.token.gen,
                    Server.sameS2sPeer(conn, other.value),
                });
            }
        }
    }
}

fn runReciprocalMeshDurabilityTest(shards1: u16, shards2: u16) !void {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const alloc = std.testing.allocator;
        const s2s_ports = reserveTwoLoopbackPorts() catch return error.SkipZigTest;
        const s2s_port1 = s2s_ports[0];
        const s2s_port2 = s2s_ports[1];

        var spec1_buf: [32]u8 = undefined;
        var spec2_buf: [32]u8 = undefined;
        const node1_spec = try std.fmt.bufPrint(&spec1_buf, "127.0.0.1:{d}", .{s2s_port1});
        const node2_spec = try std.fmt.bufPrint(&spec2_buf, "127.0.0.1:{d}", .{s2s_port2});
        const node1_peers = [_][]const u8{node2_spec};
        const node2_peers = [_][]const u8{node1_spec};

        var node1 = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .s2s_port = s2s_port1,
            .node_id = 1,
            .server_name = "node1.test",
            .mesh_connect = &node1_peers,
            .num_shards = shards1,
            .sweep_interval_ms = 100,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
            else => return err,
        };
        defer node1.deinit();

        var node2 = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .s2s_port = s2s_port2,
            .node_id = 2,
            .server_name = "node2.test",
            .mesh_connect = &node2_peers,
            .num_shards = shards2,
            .sweep_interval_ms = 100,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
            else => return err,
        };
        defer node2.deinit();

        const port1 = node1.boundPort() catch return error.SkipZigTest;
        const port2 = node2.boundPort() catch return error.SkipZigTest;

        var run1 = std.atomic.Value(bool).init(true);
        var run2 = std.atomic.Value(bool).init(true);
        var thr1 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node1, &run1 });
        var thr2 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node2, &run2 });
        defer {
            node1.requestStop(&run1);
            node2.requestStop(&run2);
            thr1.join();
            thr2.join();
        }

        const fd1 = connectLoopback(port1) catch return error.SkipZigTest;
        defer closeFd(fd1);
        const fd2 = connectLoopback(port2) catch return error.SkipZigTest;
        defer closeFd(fd2);
        var c1 = LiveClient{ .fd = fd1 };
        var c2 = LiveClient{ .fd = fd2 };
        try writeAllFd(fd1, "NICK C1\r\nUSER c1 0 * :Client One\r\n");
        try writeAllFd(fd2, "NICK C2\r\nUSER c2 0 * :Client Two\r\n");
        try recvUntil(&c1, " 001 C1 ", 200);
        try recvUntil(&c2, " 001 C2 ", 200);

        try expectMeshPeerVisible(&c1, "node2.test", 160);
        try expectMeshPeerVisible(&c2, "node1.test", 160);
        // Immediate peer publication deliberately precedes the asynchronous
        // reciprocal-dial loser close. Wait for that one initial convergence
        // to settle before freezing the no-further-churn baseline.
        var node1_collapses = countMeshLogDetail(&node1, "duplicate link collapsed");
        var node2_collapses = countMeshLogDetail(&node2, "duplicate link collapsed");
        var stable_rounds: usize = 0;
        var settle_rounds: usize = 0;
        while (stable_rounds < 3 and settle_rounds < 20) : (settle_rounds += 1) {
            testSleepMs(100);
            try expectMeshPeerVisible(&c1, "node2.test", 8);
            try expectMeshPeerVisible(&c2, "node1.test", 8);
            const next1 = countMeshLogDetail(&node1, "duplicate link collapsed");
            const next2 = countMeshLogDetail(&node2, "duplicate link collapsed");
            if (next1 == node1_collapses and next2 == node2_collapses) {
                stable_rounds += 1;
            } else {
                node1_collapses = next1;
                node2_collapses = next2;
                stable_rounds = 0;
            }
        }
        try std.testing.expectEqual(@as(usize, 3), stable_rounds);

        // Hold through several accelerated auto-connect sweeps. A reciprocal mesh
        // used to establish, hit the next redial/collision pass, and then disappear.
        var checks: usize = 0;
        while (checks < 12) : (checks += 1) {
            testSleepMs(150);
            try expectMeshPeerVisible(&c1, "node2.test", 8);
            try expectMeshPeerVisible(&c2, "node1.test", 8);
        }
        const final1 = countMeshLogDetail(&node1, "duplicate link collapsed");
        const final2 = countMeshLogDetail(&node2, "duplicate link collapsed");
        if (final1 != node1_collapses or final2 != node2_collapses) {
            dumpMeshDialProofForTest(&node1);
            dumpMeshDialProofForTest(&node2);
        }
        try std.testing.expectEqual(node1_collapses, final1);
        try std.testing.expectEqual(node2_collapses, final2);
    } else return error.SkipZigTest;
}

/// Parse the user count out of a LUSERS 251 line ("There are N users ...").
fn parseLusersUserCount(buf: []const u8) ?u64 {
    const marker = "There are ";
    const at = std.mem.indexOf(u8, buf, marker) orelse return null;
    var i = at + marker.len;
    var n: u64 = 0;
    var any = false;
    while (i < buf.len and buf[i] >= '0' and buf[i] <= '9') : (i += 1) {
        n = n * 10 + (buf[i] - '0');
        any = true;
    }
    return if (any) n else null;
}

// The live "flap" was per-shard LUSERS inconsistency, not a link flap: a 4-shard
// node's S2S peer lives only on reactor 0 and its users spread across shards via
// SO_REUSEPORT, so LUSERS answered by shards 1..3 reported "1 server" and a
// fraction of the users. A reconnecting probe sampled that as 1<->2 oscillation.
// Open many connections (spread across shards) and assert EVERY one agrees on
// the server count (2) and the user count. Asymmetric 4<->1 mirrors the live
// topology (eshmaki 8 cores, ircx.us 1 core).
fn runLusersCrossShardConsistencyTest(shards1: u16, shards2: u16) !void {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const alloc = std.testing.allocator;
        const s2s_ports = reserveTwoLoopbackPorts() catch return error.SkipZigTest;
        var spec1_buf: [32]u8 = undefined;
        var spec2_buf: [32]u8 = undefined;
        const node1_spec = try std.fmt.bufPrint(&spec1_buf, "127.0.0.1:{d}", .{s2s_ports[0]});
        const node2_spec = try std.fmt.bufPrint(&spec2_buf, "127.0.0.1:{d}", .{s2s_ports[1]});
        const node1_peers = [_][]const u8{node2_spec};
        const node2_peers = [_][]const u8{node1_spec};

        var node1 = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .s2s_port = s2s_ports[0],
            .node_id = 1,
            .server_name = "node1.test",
            .mesh_connect = &node1_peers,
            .num_shards = shards1,
            .sweep_interval_ms = 100,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
            else => return err,
        };
        defer node1.deinit();
        var node2 = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .s2s_port = s2s_ports[1],
            .node_id = 2,
            .server_name = "node2.test",
            .mesh_connect = &node2_peers,
            .num_shards = shards2,
            .sweep_interval_ms = 100,
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
            else => return err,
        };
        defer node2.deinit();
        const port1 = node1.boundPort() catch return error.SkipZigTest;

        var run1 = std.atomic.Value(bool).init(true);
        var run2 = std.atomic.Value(bool).init(true);
        var thr1 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node1, &run1 });
        var thr2 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node2, &run2 });
        defer {
            node1.requestStop(&run1);
            node2.requestStop(&run2);
            thr1.join();
            thr2.join();
        }

        // Establish the mesh first (probe connection), so reactor 0 has published a
        // peer count of 1 before we fan out.
        const probe_fd = connectLoopback(port1) catch return error.SkipZigTest;
        var probe = LiveClient{ .fd = probe_fd };
        try writeAllFd(probe_fd, "NICK P\r\nUSER p 0 * :Probe\r\n");
        try recvUntil(&probe, " 001 P ", 200);
        try expectMeshPeerVisible(&probe, "node2.test", 200);
        closeFd(probe_fd);

        // Fan out: many connections spread across node1's shards by SO_REUSEPORT.
        const N = 16;
        var fds: [N]linux.fd_t = undefined;
        var clients: [N]LiveClient = undefined;
        var opened: usize = 0;
        defer for (fds[0..opened]) |fd| closeFd(fd);
        for (0..N) |i| {
            const fd = connectLoopback(port1) catch return error.SkipZigTest;
            fds[i] = fd;
            clients[i] = LiveClient{ .fd = fd };
            opened += 1;
            var rb: [48]u8 = undefined;
            const reg = try std.fmt.bufPrint(&rb, "NICK U{d}\r\nUSER u{d} 0 * :User\r\n", .{ i, i });
            try writeAllFd(fd, reg);
        }
        for (0..N) |i| {
            var nb: [16]u8 = undefined;
            const needle = try std.fmt.bufPrint(&nb, " 001 U{d} ", .{i});
            try recvUntil(&clients[i], needle, 200);
        }

        // Every connection's LUSERS must agree: same server count (2) and same user
        // count, regardless of which shard answered it.
        var first_users: ?u64 = null;
        for (0..N) |i| {
            clients[i].reset();
            try writeAllFd(fds[i], "LUSERS\r\n");
            try recvUntil(&clients[i], " 255 ", 200);
            const out = clients[i].written();
            if (std.mem.indexOf(u8, out, "2 servers") == null) {
                srvLog("conn {d} LUSERS missing '2 servers': {s}\n", .{ i, out });
                return error.TestUnexpectedResult;
            }
            const uc = parseLusersUserCount(out) orelse return error.TestUnexpectedResult;
            // At least the N fanned-out users are registered network-wide.
            try std.testing.expect(uc >= N);
            if (first_users) |fu| {
                try std.testing.expectEqual(fu, uc);
            } else first_users = uc;
        }
    } else return error.SkipZigTest;
}

test "threaded server: LUSERS counts are consistent across shards" {
    try runLusersCrossShardConsistencyTest(4, 1);
    try runLusersCrossShardConsistencyTest(1, 4);
}

test "threaded server: reciprocal [mesh].connect survives redial sweeps" {
    try runReciprocalMeshDurabilityTest(1, 1);
    try runReciprocalMeshDurabilityTest(2, 2);
    // Asymmetric: mirrors the live topology (eshmaki 8 cores -> 4 shards,
    // ircx.us 1 core -> 1 shard). This is the case that was reported to
    // oscillate live; the oscillation was the USR2 CLOEXEC strand (d06b8f4),
    // not a runtime flap. Lock in that the asymmetric mesh holds.
    try runReciprocalMeshDurabilityTest(4, 1);
    try runReciprocalMeshDurabilityTest(1, 4);
}

// SASL fixture for the cross-node multi-device DM test: two ordinary (non-oper)
// accounts, "nova" (recipient identity) and "kazu" (sender identity), password
// "pw", accepted by BOTH nodes so the same account can sign in on each.
fn testDmRelayVerify(_: *anyopaque, creds: sasl.PlainCredentials) bool {
    return (std.mem.eql(u8, creds.authcid, "nova") or std.mem.eql(u8, creds.authcid, "kazu")) and
        std.mem.eql(u8, creds.password, "pw");
}
var test_dm_relay_anchor: u8 = 0;
const test_dm_relay_checker = sasl.PlainChecker{ .ptr = &test_dm_relay_anchor, .verifyFn = testDmRelayVerify };

// Three-node line acceptance additionally needs one real mesh-admin connection
// to hold the B-C leg down and reconnect it deterministically.
fn testLineMeshVerify(_: *anyopaque, creds: sasl.PlainCredentials) bool {
    if (std.mem.eql(u8, creds.authcid, "admin"))
        return std.mem.eql(u8, creds.password, "onyx");
    return (std.mem.eql(u8, creds.authcid, "nova") or std.mem.eql(u8, creds.authcid, "kazu")) and
        std.mem.eql(u8, creds.password, "pw");
}
var test_line_mesh_anchor: u8 = 0;
const test_line_mesh_checker = sasl.PlainChecker{ .ptr = &test_line_mesh_anchor, .verifyFn = testLineMeshVerify };

// Design C / F1 fail-closed, at the live-integration level. Cross-node
// multi-device coexistence (account "nova" as nick Nova on BOTH nodes) is what
// lets a DM to a locally-held nick ALSO relay to the account's session on the
// peer node — but ONLY when the peer's same-account claim is TRUSTED. Over a
// plaintext (cryptographically UNauthenticated) mesh link with no enrolled
// residence proof, the claim is untrusted: node1 UID-disambiguates Nova@node2
// (`resolveIncomingNick` account gate → conservative UID), so it does NOT home
// "Nova" on the node2 link and the relay is correctly suppressed. This proves a
// FORGED/unproven plaintext account cannot draw a third node's DM to a phantom
// (the exact F1 hole). LOCAL delivery is unaffected. The RESTORED multi-device
// relay under a VERIFIED residence proof is proven deterministically in the
// route_table / s2s_peer unit tests and the seed-replayable residence DST
// (`substrate/undertow/residence_trust_dst.zig`).
test "threaded server: an UNPROVEN cross-node same-account claim grants no coexistence relay (F1 fail-closed)" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    const s2s_ports = reserveTwoLoopbackPorts() catch return error.SkipZigTest;
    var spec1_buf: [32]u8 = undefined;
    var spec2_buf: [32]u8 = undefined;
    const node1_spec = try std.fmt.bufPrint(&spec1_buf, "127.0.0.1:{d}", .{s2s_ports[0]});
    const node2_spec = try std.fmt.bufPrint(&spec2_buf, "127.0.0.1:{d}", .{s2s_ports[1]});
    const node1_peers = [_][]const u8{node2_spec};
    const node2_peers = [_][]const u8{node1_spec};

    // Keyless plaintext links: a keyless node fails CLOSED on unsigned in-scope
    // frames when require_signed_frames is the default (true), which would drop
    // the PRESENCE MEMBERSHIP gossip this test depends on. Opt into unsigned
    // interop as a plaintext operator would; signing enforcement is proven
    // separately.
    var node1_cfg = Config{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = s2s_ports[0],
        .node_id = 1,
        .server_name = "node1.test",
        .mesh_connect = &node1_peers,
        .num_shards = 1,
        .sweep_interval_ms = 100,
        .sasl_checker = test_dm_relay_checker,
    };
    node1_cfg.s2s_config.require_signed_frames = false;
    var node1 = Server.init(alloc, node1_cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
        else => return err,
    };
    defer node1.deinit();
    var node2_cfg = Config{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = s2s_ports[1],
        .node_id = 2,
        .server_name = "node2.test",
        .mesh_connect = &node2_peers,
        .num_shards = 1,
        .sweep_interval_ms = 100,
        .sasl_checker = test_dm_relay_checker,
    };
    node2_cfg.s2s_config.require_signed_frames = false;
    var node2 = Server.init(alloc, node2_cfg) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
        else => return err,
    };
    defer node2.deinit();
    const port1 = node1.boundPort() catch return error.SkipZigTest;
    const port2 = node2.boundPort() catch return error.SkipZigTest;

    var run1 = std.atomic.Value(bool).init(true);
    var run2 = std.atomic.Value(bool).init(true);
    var thr1 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node1, &run1 });
    var thr2 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node2, &run2 });
    defer {
        node1.requestStop(&run1);
        node2.requestStop(&run2);
        thr1.join();
        thr2.join();
    }

    // Establish the mesh BEFORE any account nick registers, so presence claims
    // flow forward over an up link and same-account same-nick reconciliation is
    // the steady-state path.
    const probe_fd = connectLoopback(port1) catch return error.SkipZigTest;
    var probe = LiveClient{ .fd = probe_fd };
    try writeAllFd(probe_fd, "NICK P\r\nUSER p 0 * :Probe\r\n");
    try recvUntil(&probe, " 001 P ", 200);
    try expectMeshPeerVisible(&probe, "node2.test", 200);
    closeFd(probe_fd);

    // Heap-allocate the four live clients (8 KiB buffers each): recipient
    // devices R1@node1 + R2@node2 (account "nova", nick Nova on both) and sender
    // devices S1@node1 + S2@node2 (account "kazu", nick Kazu on both).
    const clients = try alloc.alloc(LiveClient, 4);
    defer alloc.free(clients);
    const fd_r1 = connectLoopback(port1) catch return error.SkipZigTest;
    defer closeFd(fd_r1);
    const fd_r2 = connectLoopback(port2) catch return error.SkipZigTest;
    defer closeFd(fd_r2);
    const fd_s1 = connectLoopback(port1) catch return error.SkipZigTest;
    defer closeFd(fd_s1);
    const fd_s2 = connectLoopback(port2) catch return error.SkipZigTest;
    defer closeFd(fd_s2);
    clients[0] = LiveClient{ .fd = fd_r1 };
    clients[1] = LiveClient{ .fd = fd_r2 };
    clients[2] = LiveClient{ .fd = fd_s1 };
    clients[3] = LiveClient{ .fd = fd_s2 };
    const r1 = &clients[0];
    const r2 = &clients[1];
    const s1 = &clients[2];
    const s2 = &clients[3];

    try saslPlainPrelude(fd_r1, "nova", "pw");
    try writeAllFd(fd_r1, "NICK Nova\r\nUSER nova 0 * :Nova One\r\n");
    try recvUntil(r1, " 001 Nova ", 200);
    try saslPlainPrelude(fd_r2, "nova", "pw");
    try writeAllFd(fd_r2, "NICK Nova\r\nUSER nova 0 * :Nova Two\r\n");
    try recvUntil(r2, " 001 Nova ", 200);
    try saslPlainPrelude(fd_s1, "kazu", "pw");
    try writeAllFd(fd_s1, "NICK Kazu\r\nUSER kazu 0 * :Kazu One\r\n");
    try recvUntil(s1, " 001 Kazu ", 200);
    try saslPlainPrelude(fd_s2, "kazu", "pw");
    try writeAllFd(fd_s2, "NICK Kazu\r\nUSER kazu 0 * :Kazu Two\r\n");
    try recvUntil(s2, " 001 Kazu ", 200);
    r1.reset();
    r2.reset();
    s2.reset();

    // Kazu@node1 DMs Nova. node1 finds Nova LOCALLY (r1) and delivers directly.
    // Because the node2 link is plaintext (unauthenticated) and Nova@node2 has no
    // residence proof, node1 UID-disambiguated Nova@node2 and does NOT home "Nova"
    // on that link, so the coexistence relay is structurally suppressed — r2 and
    // the sender-mirror s2 receive nothing regardless of timing (fail-closed).
    try writeAllFd(fd_s1, "PRIVMSG Nova :ping-mesh\r\n");

    // The local holder on the origin node received it directly.
    try recvUntil(r1, "PRIVMSG Nova :ping-mesh", 400);
    try expectContains(r1.written(), ":Kazu!");

    // Drain the peer-node devices for a bounded window; the unproven-account
    // relay must never arrive. The suppression is structural (no route homing),
    // not a race, so a modest window is a sound negative assertion.
    const drain_deadline = platform.monotonicMillis() + 500;
    while (platform.monotonicMillis() < drain_deadline) {
        var fds = [_]posix.pollfd{
            .{ .fd = fd_r2, .events = linux.POLL.IN, .revents = 0 },
            .{ .fd = fd_s2, .events = linux.POLL.IN, .revents = 0 },
        };
        const ready = posix.poll(&fds, 40) catch return error.Unexpected;
        if (ready != 0) {
            if ((fds[0].revents & linux.POLL.IN) != 0) try r2.readAvailable();
            if ((fds[1].revents & linux.POLL.IN) != 0) try s2.readAvailable();
        }
    }
    try std.testing.expect(std.mem.indexOf(u8, r2.written(), "ping-mesh") == null);
    try std.testing.expect(std.mem.indexOf(u8, s2.written(), "ping-mesh") == null);
}

test "threaded server: one reusable session stays live and participatory across a secured mesh" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    const s2s_ports = reserveTwoLoopbackPorts() catch return error.SkipZigTest;

    var tmp1 = std.testing.tmpDir(.{});
    defer tmp1.cleanup();
    var tmp2 = std.testing.tmpDir(.{});
    defer tmp2.cleanup();
    var store1 = try services_mod.OroStore.open(alloc, std.testing.io, tmp1.dir, "mesh-session-node1.wal");
    defer store1.deinit();
    var store2 = try services_mod.OroStore.open(alloc, std.testing.io, tmp2.dir, "mesh-session-node2.wal");
    defer store2.deinit();
    var services1 = services_mod.Services.init(&store1, null);
    var services2 = services_mod.Services.init(&store2, null);

    var ident1 = try node_identity.fromSeed(@as([32]u8, @splat(0x91)), "mesh-session-test");
    defer ident1.deinit();
    var ident2 = try node_identity.fromSeed(@as([32]u8, @splat(0x92)), "mesh-session-test");
    defer ident2.deinit();
    const root1 = std.fmt.bytesToHex(ident1.sign_kp.public_key, .lower);
    const root2 = std.fmt.bytesToHex(ident2.sign_kp.public_key, .lower);
    const roots_for_node1 = [_][]const u8{&root2};
    const roots_for_node2 = [_][]const u8{&root1};
    const relay_v2_roster = [_][]const u8{ &root1, &root2 };

    // Boot the target first so node 1 can auto-dial its real ephemeral S2S port.
    const node2 = try alloc.create(Server);
    node2.initInPlace(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = s2s_ports[1],
        .node_id = ident2.shortId(),
        .server_name = "session-node2.test",
        .node_identity = &ident2,
        .crypto_io = std.testing.io,
        .session_resume_composite_issuance = true,
        .mesh_pass = "mesh-session-shared-secret",
        .mesh_trust_roots = &roots_for_node2,
        .require_secured = true,
        .relay_v2_authoring = .active,
        .relay_v2_activation_epoch = 1,
        .relay_v2_roster = &relay_v2_roster,
        .sasl_checker = test_dm_relay_checker,
        .account_services = &services2,
        .num_shards = 1,
        .sweep_interval_ms = 100,
    }) catch |err| {
        alloc.destroy(node2);
        return switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => error.SkipZigTest,
            else => err,
        };
    };
    defer {
        node2.deinit();
        alloc.destroy(node2);
    }
    node2.start();
    const port2 = node2.boundPort() catch return error.SkipZigTest;
    var run2 = std.atomic.Value(bool).init(true);
    var thr2 = try std.Thread.spawn(.{}, Server.runThreaded, .{ node2, &run2 });
    var node2_cleanup_owned = true;
    errdefer if (node2_cleanup_owned) {
        node2.requestStop(&run2);
        thr2.join();
    };

    var peer_buf: [32]u8 = undefined;
    const peer = try std.fmt.bufPrint(&peer_buf, "127.0.0.1:{d}", .{s2s_ports[1]});
    const peers = [_][]const u8{peer};
    const node1 = try alloc.create(Server);
    node1.initInPlace(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = s2s_ports[0],
        .node_id = ident1.shortId(),
        .server_name = "session-node1.test",
        .node_identity = &ident1,
        .crypto_io = std.testing.io,
        .session_resume_composite_issuance = true,
        .mesh_pass = "mesh-session-shared-secret",
        .mesh_trust_roots = &roots_for_node1,
        .require_secured = true,
        .relay_v2_authoring = .active,
        .relay_v2_activation_epoch = 1,
        .relay_v2_roster = &relay_v2_roster,
        .mesh_connect = &peers,
        .sasl_checker = test_dm_relay_checker,
        .account_services = &services1,
        .webhook_enabled = true,
        .webhook_port = 0,
        .num_shards = 1,
        .sweep_interval_ms = 100,
    }) catch |err| {
        alloc.destroy(node1);
        return switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => error.SkipZigTest,
            else => err,
        };
    };
    defer {
        node1.deinit();
        alloc.destroy(node1);
    }
    node1.start();
    const port1 = node1.boundPort() catch return error.SkipZigTest;
    var run1 = std.atomic.Value(bool).init(true);
    var thr1 = try std.Thread.spawn(.{}, Server.runThreaded, .{ node1, &run1 });
    node2_cleanup_owned = false;
    defer {
        node1.requestStop(&run1);
        node2.requestStop(&run2);
        thr1.join();
        thr2.join();
    }

    // Do not issue the portable credential until the authenticated link is up;
    // TOKEN must replicate the current live snapshot immediately.
    const fd_probe = connectLoopback(port1) catch return error.SkipZigTest;
    var probe = LiveClient{ .fd = fd_probe };
    try writeAllFd(fd_probe, "NICK Probe\r\nUSER probe 0 * :Probe\r\n");
    try recvUntil(&probe, " 001 Probe ", 200);
    try expectMeshPeerVisible(&probe, "session-node2.test", 80);
    closeFd(fd_probe);

    const clients = try alloc.alloc(LiveClient, 5);
    defer alloc.free(clients);
    const fd_a = connectLoopback(port1) catch return error.SkipZigTest;
    var a_open = true;
    defer if (a_open) closeFd(fd_a);
    const fd_b = connectLoopback(port2) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    const fd_c = connectLoopback(port2) catch return error.SkipZigTest;
    defer closeFd(fd_c);
    const fd_sender = connectLoopback(port1) catch return error.SkipZigTest;
    defer closeFd(fd_sender);
    const fd_sender2 = connectLoopback(port2) catch return error.SkipZigTest;
    defer closeFd(fd_sender2);
    clients[0] = .{ .fd = fd_a };
    clients[1] = .{ .fd = fd_b };
    clients[2] = .{ .fd = fd_c };
    clients[3] = .{ .fd = fd_sender };
    clients[4] = .{ .fd = fd_sender2 };
    const a = &clients[0];
    const b = &clients[1];
    const c = &clients[2];
    const sender = &clients[3];
    const sender2 = &clients[4];

    try saslPlainPreludeWithCaps(fd_a, "nova", "pw", "message-tags server-time draft/chathistory onyx/session-sync");
    try writeAllFd(fd_a, "NICK Nova\r\nUSER nova 0 * :Origin attachment\r\n");
    try recvUntil(a, " 001 Nova ", 200);
    try writeAllFd(fd_a, "JOIN #mesh-session\r\n");
    try recvUntil(a, " 366 Nova #mesh-session ", 200);
    a.reset();
    try writeAllFd(fd_a, "SESSION TOKEN\r\n");
    try recvUntil(a, "SESSION MTOKEN ", 200);
    const local_token_reply = testSessionTokenFromReply(a.written(), "SESSION TOKEN ") orelse
        return error.TestUnexpectedResult;
    if (local_token_reply.len > session_resume_credential.local_text_len) return error.TestUnexpectedResult;
    var local_token_buf: [session_resume_credential.local_text_len]u8 = undefined;
    @memcpy(local_token_buf[0..local_token_reply.len], local_token_reply);
    const local_token = local_token_buf[0..local_token_reply.len];
    const exact_mesh_token = try expectFreshMeshSessionToken(
        a.written(),
        "mesh-session-shared-secret",
        "nova",
        local_token,
    );
    var token_buf: [1024]u8 = undefined;
    const mesh_token = try testLegacyMeshResumeCredential(
        &token_buf,
        "mesh-session-shared-secret",
        "nova",
        local_token,
        "session-node1.test",
    );

    // Attach B on the other node. Retrying the same credential while the signed
    // replica is in flight must be safe: no nonce burn and no source disconnect.
    try saslPlainPreludeWithCaps(fd_b, "nova", "pw", "echo-message message-tags server-time draft/chathistory onyx/session-sync");
    try writeAllFd(fd_b, "NICK DeviceB\r\nUSER nova 0 * :Mesh attachment B\r\n");
    try recvUntil(b, " 001 DeviceB ", 200);
    var exact_resume_line: [1200]u8 = undefined;
    b.reset();
    try writeAllFd(fd_b, try std.fmt.bufPrint(
        &exact_resume_line,
        "SESSION RESUME {s}\r\n",
        .{exact_mesh_token},
    ));
    try recvUntil(b, "SESSION REDIRECT: exact session lives on session-node1.test", 200);
    var resume_line: [1200]u8 = undefined;
    const resume_cmd = try std.fmt.bufPrint(&resume_line, "SESSION RESUME {s}\r\n", .{mesh_token});
    var attached_b = false;
    for (0..80) |_| {
        b.reset();
        try writeAllFd(fd_b, resume_cmd);
        const retry_deadline = platform.monotonicMillis() + 250;
        while (platform.monotonicMillis() < retry_deadline and
            std.mem.indexOf(u8, b.written(), "attached to replicated mesh session") == null)
        {
            var retry_fds = [_]posix.pollfd{.{ .fd = fd_b, .events = linux.POLL.IN, .revents = 0 }};
            const ready = posix.poll(&retry_fds, 20) catch return error.Unexpected;
            if (ready != 0 and (retry_fds[0].revents & linux.POLL.IN) != 0) try b.readAvailable();
        }
        if (std.mem.indexOf(u8, b.written(), "attached to replicated mesh session") != null) {
            attached_b = true;
            break;
        }
        testSleepMs(15);
    }
    try std.testing.expect(attached_b);
    try expectContains(b.written(), "JOIN #mesh-session");

    // A second attachment on node 2 reuses the exact same staged replica while
    // A and B remain live; no attachment owns or consumes the session.
    try saslPlainPreludeWithCaps(fd_c, "nova", "pw", "message-tags server-time onyx/session-sync");
    try writeAllFd(fd_c, "NICK DeviceC\r\nUSER nova 0 * :Mesh attachment C\r\n");
    try recvUntil(c, " 001 DeviceC ", 200);
    c.reset();
    try writeAllFd(fd_c, resume_cmd);
    try recvUntil(c, "attached to live mesh session", 200);
    try expectContains(c.written(), "JOIN #mesh-session");

    // A neutral channel participant generates an event. Every attachment on
    // both nodes sees it, and either remote attachment can participate.
    try saslPlainPreludeWithCaps(fd_sender, "kazu", "pw", "message-tags server-time");
    try writeAllFd(fd_sender, "NICK Kazu\r\nUSER kazu 0 * :Mesh sender\r\n");
    try recvUntil(sender, " 001 Kazu ", 200);
    try writeAllFd(fd_sender, "JOIN #mesh-session\r\n");
    try recvUntil(sender, " 366 Kazu #mesh-session ", 200);
    try saslPlainPrelude(fd_sender2, "kazu", "pw");
    try writeAllFd(fd_sender2, "NICK Mira\r\nUSER mira 0 * :Node two sender\r\n");
    try recvUntil(sender2, " 001 Mira ", 200);
    a.reset();
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_sender, "PRIVMSG #mesh-session :event-for-all-attachments\r\n");
    try recvUntil(a, "PRIVMSG #mesh-session :event-for-all-attachments", 400);
    try recvUntil(b, "PRIVMSG #mesh-session :event-for-all-attachments", 400);
    try recvUntil(c, "PRIVMSG #mesh-session :event-for-all-attachments", 400);

    // TAGMSG is the same first-class event on the origin and replica nodes: one
    // authenticated HLC yields one msgid/time for the local channel member and
    // every reusable remote attachment. The replica node also records the same
    // identity in CHATHISTORY rather than treating the tag event as live-only.
    a.reset();
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_a, "@+typing=active TAGMSG #mesh-session\r\n");
    try recvUntil(sender, "TAGMSG #mesh-session", 400);
    try recvUntil(b, "TAGMSG #mesh-session", 400);
    try recvUntil(c, "TAGMSG #mesh-session", 400);
    const tagmsg_msgid = extractMsgid(sender.written()) orelse return error.TestUnexpectedResult;
    const tagmsg_time = extractTimeTag(sender.written()) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(tagmsg_msgid, extractMsgid(b.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(tagmsg_msgid, extractMsgid(c.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(tagmsg_time, extractTimeTag(b.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(tagmsg_time, extractTimeTag(c.written()) orelse return error.TestUnexpectedResult);
    var tagmsg_msgid_copy: [msgid_mod.id_len]u8 = undefined;
    @memcpy(&tagmsg_msgid_copy, tagmsg_msgid);
    b.reset();
    try writeAllFd(fd_b, "CHATHISTORY LATEST #mesh-session * 10\r\n");
    try recvUntil(b, "TAGMSG #mesh-session", 400);
    try std.testing.expectEqualStrings(&tagmsg_msgid_copy, extractMsgid(b.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(tagmsg_time, extractTimeTag(b.written()) orelse return error.TestUnexpectedResult);

    // A synthetic webhook follows the same identity path: the origin-local
    // attachment and both secured-mesh replicas must observe one msgid/time,
    // never a local random id followed by a separately minted relay HLC.
    var webhook_post: webhook_mod.PendingPost = .{};
    webhook_post.setChannel("#mesh-session");
    webhook_post.setNick("CI-Bot");
    const webhook_body = "webhook-for-all-attachments";
    @memcpy(webhook_post.body_buf[0..webhook_body.len], webhook_body);
    webhook_post.body_len = @intCast(webhook_body.len);
    a.reset();
    b.reset();
    c.reset();
    try std.testing.expect(LinuxServer.webhookSubmit(node1, &webhook_post));
    try recvUntil(a, "PRIVMSG #mesh-session :webhook-for-all-attachments", 400);
    try recvUntil(b, "PRIVMSG #mesh-session :webhook-for-all-attachments", 400);
    try recvUntil(c, "PRIVMSG #mesh-session :webhook-for-all-attachments", 400);
    const webhook_msgid = extractMsgid(a.written()) orelse return error.TestUnexpectedResult;
    const webhook_time = extractTimeTag(a.written()) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(webhook_msgid, extractMsgid(b.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(webhook_msgid, extractMsgid(c.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(webhook_time, extractTimeTag(b.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(webhook_time, extractTimeTag(c.written()) orelse return error.TestUnexpectedResult);

    // Direct-message acceptance for the same reusable identity: the sender's
    // target resolves locally on node 1 (attachment A), but the verified session
    // replica also homes Nova on node 2. The local-DM path must therefore relay
    // once to the peer, whose session fan-out reaches BOTH remote attachments.
    // This is the positive counterpart to the plaintext/unproven F1 test above:
    // verified coexistence receives everywhere, unproven coexistence receives
    // nowhere remotely.
    a.reset();
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_sender, "PRIVMSG Nova :direct-for-all-attachments\r\n");
    try recvUntil(a, "PRIVMSG Nova :direct-for-all-attachments", 400);
    try recvUntil(b, "PRIVMSG Nova :direct-for-all-attachments", 400);
    try recvUntil(c, "PRIVMSG Nova :direct-for-all-attachments", 400);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(a.written(), "PRIVMSG Nova :direct-for-all-attachments"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(b.written(), "PRIVMSG Nova :direct-for-all-attachments"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(c.written(), "PRIVMSG Nova :direct-for-all-attachments"));
    const direct_msgid = extractMsgid(a.written()) orelse return error.TestUnexpectedResult;
    const direct_time = extractTimeTag(a.written()) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(direct_msgid, extractMsgid(b.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(direct_msgid, extractMsgid(c.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(direct_time, extractTimeTag(b.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(direct_time, extractTimeTag(c.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expect(std.mem.indexOf(u8, sender.written(), "direct-for-all-attachments") == null);

    // Reciprocal route learning is essential: after B adopted the replica, node
    // 2 re-offered its live snapshot and learned token->node1. A neutral node-2
    // sender must therefore reach A as well as the two local attachments. Before
    // reciprocal re-advertisement this deterministically stranded A.
    a.reset();
    b.reset();
    c.reset();
    sender2.reset();
    try writeAllFd(fd_sender2, "PRIVMSG Nova :direct-from-replica-node\r\n");
    try recvUntil(a, "PRIVMSG Nova :direct-from-replica-node", 400);
    try recvUntil(b, "PRIVMSG Nova :direct-from-replica-node", 400);
    try recvUntil(c, "PRIVMSG Nova :direct-from-replica-node", 400);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(a.written(), "PRIVMSG Nova :direct-from-replica-node"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(b.written(), "PRIVMSG Nova :direct-from-replica-node"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(c.written(), "PRIVMSG Nova :direct-from-replica-node"));
    try std.testing.expect(std.mem.indexOf(u8, sender2.written(), "direct-from-replica-node") == null);

    // The author side is also one logical session. A message from A to a target
    // that exists only on node 1 must still reach B and C as one sent-copy each,
    // even though no recipient route would otherwise select node 2.
    a.reset();
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_a, "PRIVMSG Kazu :sent-from-origin-attachment\r\n");
    try recvUntil(sender, "PRIVMSG Kazu :sent-from-origin-attachment", 400);
    try recvUntil(b, "PRIVMSG Kazu :sent-from-origin-attachment", 400);
    try recvUntil(c, "PRIVMSG Kazu :sent-from-origin-attachment", 400);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(sender.written(), "PRIVMSG Kazu :sent-from-origin-attachment"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(b.written(), "PRIVMSG Kazu :sent-from-origin-attachment"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(c.written(), "PRIVMSG Kazu :sent-from-origin-attachment"));
    try std.testing.expect(std.mem.indexOf(u8, a.written(), "sent-from-origin-attachment") == null);

    // The reverse direction exercises the remote-target branch: B must mirror
    // locally to C before returning, while the target node mirrors to A. The
    // sending socket itself did not negotiate echo-message and receives no copy.
    a.reset();
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_b, "PRIVMSG Kazu :sent-from-remote-attachment\r\n");
    try recvUntil(sender, "PRIVMSG Kazu :sent-from-remote-attachment", 400);
    try recvUntil(a, "PRIVMSG Kazu :sent-from-remote-attachment", 400);
    try recvUntil(b, "PRIVMSG Kazu :sent-from-remote-attachment", 400);
    try recvUntil(c, "PRIVMSG Kazu :sent-from-remote-attachment", 400);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(sender.written(), "PRIVMSG Kazu :sent-from-remote-attachment"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(a.written(), "PRIVMSG Kazu :sent-from-remote-attachment"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(c.written(), "PRIVMSG Kazu :sent-from-remote-attachment"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(b.written(), "PRIVMSG Kazu :sent-from-remote-attachment"));
    const remote_sent_msgid = extractMsgid(a.written()) orelse return error.TestUnexpectedResult;
    const remote_sent_time = extractTimeTag(a.written()) orelse return error.TestUnexpectedResult;
    var remote_sent_msgid_copy: [msgid_mod.id_len]u8 = undefined;
    @memcpy(&remote_sent_msgid_copy, remote_sent_msgid);
    var remote_sent_time_copy: [24]u8 = undefined;
    if (remote_sent_time.len != remote_sent_time_copy.len) return error.TestUnexpectedResult;
    @memcpy(&remote_sent_time_copy, remote_sent_time);

    // Node 1 can safely derive both canonical accounts for this inbound relay:
    // Kazu is a local authenticated recipient, while Nova's exact account+nick
    // is authorized by the portable token route node 1 offered to node 2. Replay
    // on the origin attachment therefore returns the same HLC identity seen live.
    a.reset();
    try writeAllFd(fd_a, "CHATHISTORY LATEST Kazu * 10\r\n");
    try recvUntil(a, "PRIVMSG Kazu :sent-from-remote-attachment", 400);
    try std.testing.expectEqualStrings(&remote_sent_msgid_copy, extractMsgid(a.written()) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(&remote_sent_time_copy, extractTimeTag(a.written()) orelse return error.TestUnexpectedResult);

    // Owner=sender without echo-message: A is recipient of its own shared-nick
    // DM and must still receive exactly once, as must both remote attachments.
    a.reset();
    b.reset();
    c.reset();
    try writeAllFd(fd_a, "PRIVMSG Nova :self-dm-owner-no-echo\r\n");
    try recvUntil(a, "PRIVMSG Nova :self-dm-owner-no-echo", 400);
    try recvUntil(b, "PRIVMSG Nova :self-dm-owner-no-echo", 400);
    try recvUntil(c, "PRIVMSG Nova :self-dm-owner-no-echo", 400);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(a.written(), "PRIVMSG Nova :self-dm-owner-no-echo"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(b.written(), "PRIVMSG Nova :self-dm-owner-no-echo"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(c.written(), "PRIVMSG Nova :self-dm-owner-no-echo"));

    // A self-DM selects the same portable token as both recipient and sender.
    // The union scope must emit only once per link and each attachment receives
    // exactly one recipient copy (never recipient + sent-copy duplicates).
    a.reset();
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_b, "PRIVMSG Nova :self-dm-once\r\n");
    try recvUntil(a, "PRIVMSG Nova :self-dm-once", 400);
    try recvUntil(b, "PRIVMSG Nova :self-dm-once", 400);
    try recvUntil(c, "PRIVMSG Nova :self-dm-once", 400);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(a.written(), "PRIVMSG Nova :self-dm-once"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(b.written(), "PRIVMSG Nova :self-dm-once"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(c.written(), "PRIVMSG Nova :self-dm-once"));

    // C has no echo-message cap and is not the World nick owner. A self-DM is
    // still recipient traffic, so C must not be skipped merely because it is the
    // sending socket.
    a.reset();
    b.reset();
    c.reset();
    try writeAllFd(fd_c, "PRIVMSG Nova :self-dm-non-owner-no-echo\r\n");
    try recvUntil(a, "PRIVMSG Nova :self-dm-non-owner-no-echo", 400);
    try recvUntil(b, "PRIVMSG Nova :self-dm-non-owner-no-echo", 400);
    try recvUntil(c, "PRIVMSG Nova :self-dm-non-owner-no-echo", 400);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(a.written(), "PRIVMSG Nova :self-dm-non-owner-no-echo"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(b.written(), "PRIVMSG Nova :self-dm-non-owner-no-echo"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(c.written(), "PRIVMSG Nova :self-dm-non-owner-no-echo"));

    // Owner!=sender with echo-message: enabling echo on C must not turn the
    // recipient copy into recipient+echo duplicates.
    c.reset();
    try writeAllFd(fd_c, "CAP REQ :echo-message\r\n");
    try recvUntil(c, " ACK :echo-message", 200);
    a.reset();
    b.reset();
    c.reset();
    try writeAllFd(fd_c, "PRIVMSG Nova :self-dm-non-owner-with-echo\r\n");
    try recvUntil(a, "PRIVMSG Nova :self-dm-non-owner-with-echo", 400);
    try recvUntil(b, "PRIVMSG Nova :self-dm-non-owner-with-echo", 400);
    try recvUntil(c, "PRIVMSG Nova :self-dm-non-owner-with-echo", 400);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(a.written(), "PRIVMSG Nova :self-dm-non-owner-with-echo"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(b.written(), "PRIVMSG Nova :self-dm-non-owner-with-echo"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(c.written(), "PRIVMSG Nova :self-dm-non-owner-with-echo"));

    a.reset();
    b.reset();
    sender.reset();
    try writeAllFd(fd_c, "PRIVMSG #mesh-session :participating-from-node2\r\n");
    try recvUntil(sender, "PRIVMSG #mesh-session :participating-from-node2", 400);
    try recvUntil(a, "PRIVMSG #mesh-session :participating-from-node2", 400);
    try recvUntil(b, "PRIVMSG #mesh-session :participating-from-node2", 400);

    // Drop the original node-1 attachment. The logical identity remains online
    // on node 2: both survivors still receive events and can send back over the
    // mesh, proving this is multi-attachment rather than migration ownership.
    closeFd(fd_a);
    a_open = false;
    testSleepMs(150);
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_sender, "PRIVMSG #mesh-session :after-origin-detach\r\n");
    try recvUntil(b, "PRIVMSG #mesh-session :after-origin-detach", 400);
    try recvUntil(c, "PRIVMSG #mesh-session :after-origin-detach", 400);

    // The detached portable snapshot retains the authenticated token->peer route,
    // so direct delivery must survive immediately too; it cannot depend on a
    // later presence burst re-homing the remote attachment under the real nick.
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_sender, "PRIVMSG Nova :direct-after-origin-detach\r\n");
    try recvUntil(b, "PRIVMSG Nova :direct-after-origin-detach", 400);
    try recvUntil(c, "PRIVMSG Nova :direct-after-origin-detach", 400);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(b.written(), "PRIVMSG Nova :direct-after-origin-detach"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(c.written(), "PRIVMSG Nova :direct-after-origin-detach"));
    try std.testing.expect(std.mem.indexOf(u8, sender.written(), "direct-after-origin-detach") == null);

    sender.reset();
    c.reset();
    try writeAllFd(fd_b, "PRIVMSG #mesh-session :survivor-can-still-send\r\n");
    try recvUntil(sender, "PRIVMSG #mesh-session :survivor-can-still-send", 400);
    try recvUntil(c, "PRIVMSG #mesh-session :survivor-can-still-send", 400);
}

const LiveUpgradeTestNode = struct {
    allocator: std.mem.Allocator,
    server: *Server,
    run: std.atomic.Value(bool) = .init(false),
    thread: ?std.Thread = null,

    const UpgradeSummary = struct {
        state_fds: usize,
        clients: usize,
        s2s_preserved: usize,
    };

    fn init(allocator: std.mem.Allocator, config: Config) !LiveUpgradeTestNode {
        const server = try allocator.create(Server);
        errdefer allocator.destroy(server);
        try server.initInPlace(allocator, config);
        return .{ .allocator = allocator, .server = server };
    }

    fn start(self: *LiveUpgradeTestNode) !void {
        if (self.thread != null) return error.TestUnexpectedResult;
        self.server.start();
        self.run.store(true, .release);
        self.thread = try std.Thread.spawn(.{}, Server.runThreaded, .{ self.server, &self.run });
    }

    fn deinit(self: *LiveUpgradeTestNode) void {
        if (self.thread) |thread_value| {
            var thread = thread_value;
            self.server.requestStop(&self.run);
            thread.join();
            self.thread = null;
        }
        current_reactor = null;
        self.server.deinit();
        self.allocator.destroy(self.server);
        self.* = undefined;
    }

    fn upgrade(self: *LiveUpgradeTestNode, successor_config: Config) !UpgradeSummary {
        if (self.thread == null) return error.TestUnexpectedResult;
        var capture = TestLiveUpgradeCapture{};
        try self.server.requestLiveUpgradeCaptureForTest(&capture);
        const deadline = platform.monotonicMillis() + 15_000;
        while (!capture.completed.load(.acquire)) {
            if (platform.monotonicMillis() >= deadline) return error.TestTimeout;
            testSleepMs(1);
        }
        if (capture.failure) |err| {
            std.debug.print("live upgrade test capture failed: {s}\n", .{@errorName(err)});
            return err;
        }
        if (capture.arena_fd < 0 or capture.state_fd_count == 0) return error.TestUnexpectedResult;

        var predecessor_thread = self.thread.?;
        predecessor_thread.join();
        self.thread = null;
        try std.testing.expect(!self.run.load(.acquire));

        var arena_owned = true;
        defer if (arena_owned) closeFd(capture.arena_fd);
        var fds_owned = true;
        defer if (fds_owned) {
            for (capture.state_fds[0..capture.state_fd_count]) |fd| closeFd(fd);
        };

        // Linux exec closes the predecessor's CLOEXEC S2S listeners before the
        // successor rebinds that configured port. Model that same boundary only
        // after capture and join; every carried client/peer fd remains held.
        for (self.server.reactors) |*reactor| {
            closeFd(reactor.s2s_listener_fd);
            reactor.s2s_listener_fd = -1;
            closeFd(reactor.s2s_listener_companion_fd);
            reactor.s2s_listener_companion_fd = -1;
        }
        const successor = try createTestServer(self.allocator, successor_config);
        var successor_owned = true;
        errdefer if (successor_owned) {
            successor.deinit();
            self.allocator.destroy(successor);
        };
        successor.config.resume_arena_fd = capture.arena_fd;
        successor.config.inherited_state_fds = capture.state_fds[0..capture.state_fd_count];
        successor.config.inherited_state_fd_manifest_present = true;
        successor.config.inherited_state_fd_manifest_valid = true;
        try successor.adoptInheritedSessions();
        current_reactor = null;
        arena_owned = false;
        fds_owned = false;

        // The capture seam set every transferred predecessor ConnState fd to -1,
        // so destroying its rings/stores cannot close successor-owned sockets.
        self.server.deinit();
        self.allocator.destroy(self.server);
        self.server = successor;
        successor_owned = false;
        try self.start();
        return .{
            .state_fds = capture.state_fd_count,
            .clients = capture.clients,
            .s2s_preserved = capture.s2s_preserved,
        };
    }
};

fn testSessionTokenFromReply(bytes: []const u8, marker: []const u8) ?[]const u8 {
    const start = (std.mem.indexOf(u8, bytes, marker) orelse return null) + marker.len;
    const tail = bytes[start..];
    const cr = std.mem.indexOfScalar(u8, tail, '\r') orelse return null;
    const token_len = std.mem.indexOfScalar(u8, tail[0..cr], ' ') orelse cr;
    if (token_len == 0) return null;
    return tail[0..token_len];
}

fn expectFreshMeshSessionToken(
    bytes: []const u8,
    mesh_key: []const u8,
    account: []const u8,
    local_credential: []const u8,
) ![]const u8 {
    // SRM2 authority is asymmetric and origin-signed. The mesh shared secret is
    // intentionally irrelevant to validating this credential.
    _ = mesh_key;
    const local = switch (try session_resume_credential.decode(local_credential)) {
        .local => |value| value,
        .mesh => return error.TestUnexpectedResult,
    };
    const mesh_credential = testSessionTokenFromReply(bytes, "SESSION MTOKEN ") orelse
        return error.TestUnexpectedResult;
    const mesh = switch (try session_resume_credential.decode(mesh_credential)) {
        .mesh => |value| value,
        .local => return error.TestUnexpectedResult,
    };
    try std.testing.expect(mesh.attachment_id.eql(local.attachment_id));
    if (mesh.sealed_hex.len % 2 != 0 or
        mesh.sealed_hex.len / 2 > session_reclaim_attachment.max_claim_wire_len)
        return error.TestUnexpectedResult;
    var raw: [session_reclaim_attachment.max_claim_wire_len]u8 = undefined;
    const wire = std.fmt.hexToBytes(raw[0 .. mesh.sealed_hex.len / 2], mesh.sealed_hex) catch
        return error.TestUnexpectedResult;
    const signed = try session_reclaim_attachment.decodeClaim(wire);
    try session_reclaim_attachment.verifyClaim(signed);
    const now = @max(@as(i64, 0), platform.realtimeMillis());
    try session_reclaim_attachment.validateAt(signed.claim, now, .{});
    try std.testing.expectEqual(session_reclaim_attachment.ClaimKind.exact_restore, signed.claim.kind);
    try std.testing.expectEqualStrings(account, signed.claim.account);
    try std.testing.expectEqual(local.group_token, signed.claim.group_token);
    try std.testing.expect(signed.claim.attachment_id.eql(local.attachment_id));
    try std.testing.expectEqual(signed.claim.origin_node, signed.claim.destination_node);
    try std.testing.expectEqual(
        @as(i64, @intCast(LinuxServer.mesh_reclaim_ttl_ms)),
        signed.claim.expires_at_ms - signed.claim.issued_at_ms,
    );
    try std.testing.expect(signed.claim.expires_at_ms >= now);
    return mesh_credential;
}

/// Explicitly mint the SRM1 compatibility credential used by integration
/// scenarios whose contract is create-new attachment on another mesh node.
/// Current SESSION MTOKEN issuance is SRM2 exact-restore and must redirect to
/// its signed origin instead of silently changing these scenarios' semantics.
fn testLegacyMeshResumeCredential(
    out_hex: []u8,
    mesh_key: []const u8,
    account: []const u8,
    local_or_group_credential: []const u8,
    origin_node: []const u8,
) ![]const u8 {
    var token_hex: [session_resume_credential.token_hex_len]u8 = undefined;
    if (std.mem.startsWith(u8, local_or_group_credential, "srm2l.")) {
        const local = switch (try session_resume_credential.decode(local_or_group_credential)) {
            .local => |value| value,
            .mesh => return error.TestUnexpectedResult,
        };
        token_hex = std.fmt.bytesToHex(local.group_token, .lower);
    } else {
        if (local_or_group_credential.len != token_hex.len) return error.TestUnexpectedResult;
        var group: session_migrate.Token = undefined;
        _ = std.fmt.hexToBytes(&group, local_or_group_credential) catch
            return error.TestUnexpectedResult;
        @memcpy(&token_hex, local_or_group_credential);
    }
    const now: u64 = @intCast(@max(@as(i64, 0), platform.realtimeMillis()));
    var raw: [512]u8 = undefined;
    const len = try session_reclaim_mesh.seal(mesh_key, .{
        .account = account,
        .session_id = &token_hex,
        .origin_node = origin_node,
        .issued_ms = now,
        .expiry_ms = now + LinuxServer.mesh_reclaim_ttl_ms,
        .nonce = now | 1,
    }, &raw);
    if (len * 2 > out_hex.len) return error.TestUnexpectedResult;
    return LinuxServer.toHexLower(raw[0..len], out_hex);
}

fn expectLiveSessionToken(
    client: *LiveClient,
    expected: []const u8,
    mesh_key: []const u8,
    account: []const u8,
) !void {
    const expected_local = switch (try session_resume_credential.decode(expected)) {
        .local => |value| value,
        .mesh => return error.TestUnexpectedResult,
    };
    client.reset();
    try writeAllFd(client.fd, "SESSION TOKEN\r\n");
    const deadline = platform.monotonicMillis() + 1_000;
    while (platform.monotonicMillis() < deadline) {
        try client.readAvailable();
        if (testSessionTokenFromReply(client.written(), "SESSION TOKEN ")) |token| {
            if (std.mem.startsWith(u8, token, "srm2l.")) {
                const current = switch (try session_resume_credential.decode(token)) {
                    .local => |value| value,
                    .mesh => return error.TestUnexpectedResult,
                };
                try std.testing.expectEqual(expected_local.group_token, current.group_token);
                _ = try expectFreshMeshSessionToken(client.written(), mesh_key, account, token);
            } else {
                if (token.len != @sizeOf(session_migrate.Token) * 2)
                    return error.TestUnexpectedResult;
                var current_group: session_migrate.Token = undefined;
                _ = std.fmt.hexToBytes(&current_group, token) catch return error.TestUnexpectedResult;
                try std.testing.expectEqual(expected_local.group_token, current_group);
                const mesh_hex = testSessionTokenFromReply(client.written(), "SESSION MTOKEN ") orelse
                    return error.TestUnexpectedResult;
                if (mesh_hex.len % 2 != 0 or mesh_hex.len / 2 > 512)
                    return error.TestUnexpectedResult;
                var raw: [512]u8 = undefined;
                const sealed = std.fmt.hexToBytes(raw[0 .. mesh_hex.len / 2], mesh_hex) catch
                    return error.TestUnexpectedResult;
                const now: u64 = @intCast(@max(@as(i64, 0), platform.realtimeMillis()));
                const fields = try session_reclaim_mesh.open(mesh_key, sealed, now);
                try std.testing.expectEqualStrings(account, fields.account);
                try std.testing.expectEqualStrings(token, fields.session_id);
            }
            return;
        }
        testSleepMs(10);
    }
    return error.TestTimeout;
}

fn resumeLiveMeshSession(client: *LiveClient, command: []const u8) !void {
    // Retain bootstrap bytes when the attachment notice spans retry/read boundaries.
    client.reset();
    for (0..100) |_| {
        try writeAllFd(client.fd, command);
        const deadline = platform.monotonicMillis() + 250;
        while (platform.monotonicMillis() < deadline) {
            try client.readAvailable();
            if (std.mem.indexOf(u8, client.written(), "attached to") != null) return;
            testSleepMs(10);
        }
        testSleepMs(20);
    }
    return error.TestTimeout;
}

test "same-IP mesh dial session resume retains JOIN received before a retry" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const command = "SESSION RESUME :retry-token\r\n";
    const join = ":Device!nova@localhost JOIN #helix-mesh\r\n";
    const attached = ":fixture NOTICE Device :attached to retry-token\r\n";
    const ScriptedPeer = struct {
        fd: linux.fd_t,
        failure: ?anyerror = null,
        requests: usize = 0,

        fn receiveRequest(self: *@This()) !void {
            var request: [command.len]u8 = undefined;
            var received: usize = 0;
            const deadline = platform.monotonicMillis() + 5_000;
            while (received < request.len) {
                if (platform.monotonicMillis() >= deadline) return error.TestTimeout;
                var fds = [_]posix.pollfd{.{ .fd = self.fd, .events = posix.POLL.IN, .revents = 0 }};
                if (try posix.poll(&fds, 50) == 0) continue;
                if ((fds[0].revents & posix.POLL.IN) == 0) continue;
                const n = try readFd(self.fd, request[received..]);
                if (n == 0) return error.ConnectionReset;
                received += n;
            }
            try std.testing.expectEqualStrings(command, &request);
            self.requests += 1;
        }

        fn script(self: *@This()) !void {
            try self.receiveRequest();
            try writeAllFd(self.fd, join);
            // The second actual request proves the client's first deadline has
            // expired. Only then release the attachment reply; no timing sleep
            // can accidentally merge JOIN and ATTACHED into the first attempt.
            try self.receiveRequest();
            try writeAllFd(self.fd, attached);
        }

        fn run(self: *@This()) void {
            self.script() catch |err| {
                self.failure = err;
            };
        }
    };

    const sockets = try sameIPTestSocketPair();
    defer closeFd(sockets[0]);
    defer closeFd(sockets[1]);
    const client = try std.testing.allocator.create(LiveClient);
    defer std.testing.allocator.destroy(client);
    client.* = .{ .fd = sockets[0] };
    var peer = ScriptedPeer{ .fd = sockets[1] };
    var thread = try std.Thread.spawn(.{}, ScriptedPeer.run, .{&peer});
    var joined = false;
    defer if (!joined) thread.join();

    try resumeLiveMeshSession(client, command);
    thread.join();
    joined = true;
    if (peer.failure) |err| return err;
    try std.testing.expectEqual(@as(usize, 2), peer.requests);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(client.written(), join));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(client.written(), attached));
}

fn expectNoUpgradeTopologyChurn(clients: []const *LiveClient) !void {
    const deadline = platform.monotonicMillis() + 400;
    while (platform.monotonicMillis() < deadline) {
        for (clients) |client| try client.readAvailable();
        testSleepMs(10);
    }
    for (clients) |client| {
        const output = client.written();
        try std.testing.expect(std.mem.indexOf(u8, output, " JOIN ") == null);
        try std.testing.expect(std.mem.indexOf(u8, output, " JOIN :") == null);
        try std.testing.expect(std.mem.indexOf(u8, output, " PART ") == null);
        try std.testing.expect(std.mem.indexOf(u8, output, " QUIT ") == null);
        client.reset();
    }
}

fn expectAllUpgradeClientsPing(clients: []const *LiveClient, phase: []const u8) !void {
    for (clients, 0..) |client, index| {
        client.reset();
        var line_buf: [96]u8 = undefined;
        const line = try std.fmt.bufPrint(&line_buf, "PING :{s}-{d}\r\n", .{ phase, index });
        try writeAllFd(client.fd, line);
        var needle_buf: [96]u8 = undefined;
        const needle = try std.fmt.bufPrint(&needle_buf, "PONG onyx.local :{s}-{d}", .{ phase, index });
        try recvUntil(client, needle, 600);
        try std.testing.expectEqual(@as(usize, 1), countOccurrences(client.written(), needle));
    }
}

fn expectSharedUpgradeMessage(
    clients: []const *LiveClient,
    sender_index: usize,
    target: []const u8,
    body: []const u8,
) !void {
    for (clients) |client| client.reset();
    var line_buf: [256]u8 = undefined;
    const line = try std.fmt.bufPrint(&line_buf, "PRIVMSG {s} :{s}\r\n", .{ target, body });
    try writeAllFd(clients[sender_index].fd, line);
    var needle_buf: [224]u8 = undefined;
    const needle = try std.fmt.bufPrint(&needle_buf, "PRIVMSG {s} :{s}", .{ target, body });
    if (clients.len > 16) return error.TestUnexpectedResult;
    var received: [16]bool = @splat(false);
    var remaining = clients.len;
    const deadline = platform.monotonicMillis() + 20_000;
    while (remaining != 0 and platform.monotonicMillis() < deadline) {
        for (clients, 0..) |client, index| {
            if (received[index]) continue;
            try client.readAvailable();
            if (std.mem.indexOf(u8, client.written(), needle) == null) continue;
            received[index] = true;
            remaining -= 1;
        }
        if (remaining != 0) testSleepMs(10);
    }
    if (remaining != 0) {
        std.debug.print(
            "four-client Helix delivery timeout phase={s} sender={d} target={s} missing={d}\n",
            .{ body, sender_index, target, remaining },
        );
        for (clients, 0..) |client, index| {
            std.debug.print(
                "  recipient={d} received={} output=\n{s}\n",
                .{ index, received[index], client.written() },
            );
        }
        return error.TestTimeout;
    }
    testSleepMs(80);
    for (clients) |client| try client.readAvailable();

    const first_event = ircLineContaining(clients[0].written(), needle) orelse return error.TestUnexpectedResult;
    const expected_msgid = extractMsgid(first_event) orelse return error.TestUnexpectedResult;
    const expected_time = extractTimeTag(first_event) orelse return error.TestUnexpectedResult;
    for (clients) |client| {
        try std.testing.expectEqual(@as(usize, 1), countOccurrences(client.written(), needle));
        const event_line = ircLineContaining(client.written(), needle) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(expected_msgid, extractMsgid(event_line) orelse return error.TestUnexpectedResult);
        try std.testing.expectEqualStrings(expected_time, extractTimeTag(event_line) orelse return error.TestUnexpectedResult);
    }
    // Keep the flood buckets comfortably below their sustained rate while still
    // making this multi-event acceptance gate fast enough for the full suite.
    testSleepMs(120);
}

fn expectSharedUpgradeMarker(clients: []const *LiveClient, author_index: ?usize, timestamp: []const u8) !void {
    for (clients) |client| client.reset();
    var command_buf: [128]u8 = undefined;
    if (author_index) |index| {
        const command = try std.fmt.bufPrint(&command_buf, "MARKREAD #helix-mesh timestamp={s}\r\n", .{timestamp});
        try writeAllFd(clients[index].fd, command);
    } else {
        for (clients) |client| try writeAllFd(client.fd, "MARKREAD #helix-mesh\r\n");
    }
    var needle_buf: [128]u8 = undefined;
    const needle = try std.fmt.bufPrint(&needle_buf, "MARKREAD #helix-mesh timestamp={s}", .{timestamp});
    for (clients) |client| try recvUntil(client, needle, 600);
    testSleepMs(80);
    for (clients) |client| {
        try client.readAvailable();
        try std.testing.expectEqual(@as(usize, 1), countOccurrences(client.written(), needle));
    }
}

const SameIPPeerProof = struct {
    fd: linux.fd_t,
    token: RingFdToken,
    initiator: bool,
    target: ?posix.sockaddr.in6,
    bound: bool,
    collapses: usize,

    fn read(server: *Server, public_key: [32]u8) ?SameIPPeerProof {
        server.world.lockWrite();
        defer server.world.unlockWrite();
        var peers = server.reactors[0].clients.iterator();
        var result: ?SameIPPeerProof = null;
        while (peers.next()) |entry| {
            const conn = entry.value;
            if (conn.closing or conn.s2s_dedup) continue;
            const link = conn.s2s_secured orelse continue;
            if (!link.established()) continue;
            const key = link.peerNodeKey() orelse continue;
            if (!std.mem.eql(u8, &key, &public_key)) continue;
            if (result != null) return null; // more than one live route is a failure
            var bound = false;
            for (server.mesh_dials) |dial| {
                const token = dial.token orelse continue;
                if (token.slot == conn.token.slot and token.gen == conn.token.gen) bound = true;
            }
            result = .{
                .fd = conn.fd,
                .token = conn.token,
                .initiator = conn.s2s_initiator,
                .target = if (conn.s2s_dial_target_known) conn.s2s_connect_addr else null,
                .bound = bound,
                .collapses = countMeshLogDetail(server, "duplicate link collapsed"),
            };
        }
        return result;
    }

    fn wait(server: *Server, public_key: [32]u8) !SameIPPeerProof {
        const deadline = platform.monotonicMillis() + 20_000;
        while (platform.monotonicMillis() < deadline) {
            if (read(server, public_key)) |proof| return proof;
            testSleepMs(10);
        }
        return error.TestTimeout;
    }

    fn pauseDial(server: *Server, pause: bool) void {
        server.world.lockWrite();
        defer server.world.unlockWrite();
        for (server.mesh_dials) |*dial| {
            dial.retry_not_before_ms = if (pause) platform.monotonicMillis() + 60_000 else 0;
            dial.last_attempt_ms = 0;
        }
        server.wakeReactor();
    }

    fn closePeer(server: *Server, public_key: [32]u8) !void {
        server.world.lockWrite();
        defer server.world.unlockWrite();
        current_reactor = &server.reactors[0];
        defer current_reactor = null;
        var peers = server.reactors[0].clients.iterator();
        while (peers.next()) |entry| {
            const link = entry.value.s2s_secured orelse continue;
            const key = link.peerNodeKey() orelse continue;
            if (!std.mem.eql(u8, &key, &public_key)) continue;
            server.requestS2sClose(entry.value, "same-IP test partition");
            return;
        }
        return error.TestUnexpectedResult;
    }

    fn expectMembers(client: *LiveClient, names: []const []const u8) !void {
        const deadline = platform.monotonicMillis() + 20_000;
        while (platform.monotonicMillis() < deadline) {
            client.reset();
            try writeAllFd(client.fd, "NAMES #same-ip\r\n");
            try recvUntil(client, " 366 ", 200);
            const bytes = client.written();
            var ready = true;
            for (names) |name| {
                if (std.mem.indexOf(u8, bytes, name) == null) ready = false;
            }
            if (ready) return;
            testSleepMs(20);
        }
        std.debug.print("same-IP final NAMES response: {s}\n", .{client.written()});
        return error.TestTimeout;
    }
};

const FarOrdinaryNickCase = enum { whois, direct_message };

fn expectOrdinaryGuestForFarPresenceTest(server: *Server, nick: []const u8) !void {
    server.world.lockWrite();
    defer server.world.unlockWrite();
    const wid = server.world.findNick(nick) orelse return error.TestUnexpectedResult;
    const id = clientIdFromWorld(wid);
    const conn = server.connFor(id) orelse return error.TestUnexpectedResult;
    try std.testing.expect(conn.session.registered());
    try std.testing.expect(conn.session.account() == null);
    try std.testing.expect(server.portableSessionTokenForClient(id, conn) == null);
    try std.testing.expect(server.detachedReplicaTokenForNick(nick) == null);
    const now: i64 = @intCast(server.meshWallMs());
    try std.testing.expectEqual(@as(usize, 0), server.session_replica_store.retainedCount(now));
    var channels = server.world.channelIterator();
    try std.testing.expect(channels.next() == null);
}

/// Exercise truthful legacy ingress on one actual secured leg only. This is a
/// transport diagnostic, not a client-authoring route or an unknown-DM flood.
fn sendFarPresenceLegacyDiagnostic(server: *Server, peer_key: [32]u8) !u64 {
    server.world.lockWrite();
    defer server.world.unlockWrite();
    current_reactor = &server.reactors[0];
    defer current_reactor = null;
    const wid = server.world.findNick("GuestC") orelse return error.TestUnexpectedResult;
    const author = server.connFor(clientIdFromWorld(wid)) orelse return error.TestUnexpectedResult;
    var prefix_buf: [320]u8 = undefined;
    var msg = s2s_link.RelayMessage{
        .verb = .privmsg,
        .target = "GuestA",
        .source_nick = "GuestC",
        .source_prefix = try clientPrefix(author, &prefix_buf),
        .text = "legacy-terminal-control",
        .origin_node = server.config.node_id,
        .hlc = server.nextMeshHlc(),
    };
    var pubkey_buf: [message_relay.pubkey_len]u8 = undefined;
    var signature_buf: [message_relay.sig_len]u8 = undefined;
    server.signRelayOrigin(&msg, &pubkey_buf, &signature_buf);
    try std.testing.expectEqual(message_relay.VerifyOutcome.verified, try message_relay.verifyOrigin(server.allocator, msg));
    var peers = server.reactors[0].clients.iterator();
    while (peers.next()) |entry| {
        const link = entry.value.s2s_secured orelse continue;
        if (!entry.value.ownsActiveMeshLink(link)) continue;
        const key = link.peerNodeKey() orelse continue;
        if (!std.mem.eql(u8, &key, &peer_key)) continue;
        try link.sendMessage(msg);
        try std.testing.expect(server.flushSecuredS2sOutboundTo(entry.id, link));
        return msg.hlc;
    }
    return error.TestUnexpectedResult;
}

/// Actual TCP/Mooring A-B-C, with independent ordinary clients and no A-C leg.
/// The two intended-behavior assertions below are deliberately RED until the
/// separate signed presence and exact guest-DM contracts are integrated.
fn runFarOrdinaryNickRegression(case: FarOrdinaryNickCase) !void {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    const allocator = std.testing.allocator;
    const acceptance_lock = if (builtin.os.tag == .linux) try acquireHeavyMeshAcceptanceTestLock() else -1;
    defer if (acceptance_lock >= 0) closeFd(acceptance_lock);
    const ports = try reserveThreeLoopbackPorts();
    var tmp_a = std.testing.tmpDir(.{});
    defer tmp_a.cleanup();
    var tmp_b = std.testing.tmpDir(.{});
    defer tmp_b.cleanup();
    var tmp_c = std.testing.tmpDir(.{});
    defer tmp_c.cleanup();
    var store_a = try services_mod.OroStore.open(allocator, std.testing.io, tmp_a.dir, "far-guest-a.wal");
    defer store_a.deinit();
    var store_b = try services_mod.OroStore.open(allocator, std.testing.io, tmp_b.dir, "far-guest-b.wal");
    defer store_b.deinit();
    var store_c = try services_mod.OroStore.open(allocator, std.testing.io, tmp_c.dir, "far-guest-c.wal");
    defer store_c.deinit();
    var services_a = services_mod.Services.init(&store_a, null);
    var services_b = services_mod.Services.init(&store_b, null);
    var services_c = services_mod.Services.init(&store_c, null);
    var identity_a = try node_identity.fromSeed(@as([32]u8, @splat(0xf1)), "far-ordinary-presence-test");
    defer identity_a.deinit();
    var identity_b = try node_identity.fromSeed(@as([32]u8, @splat(0xf2)), "far-ordinary-presence-test");
    defer identity_b.deinit();
    var identity_c = try node_identity.fromSeed(@as([32]u8, @splat(0xf3)), "far-ordinary-presence-test");
    defer identity_c.deinit();
    const root_a = std.fmt.bytesToHex(identity_a.sign_kp.public_key, .lower);
    const root_b = std.fmt.bytesToHex(identity_b.sign_kp.public_key, .lower);
    const root_c = std.fmt.bytesToHex(identity_c.sign_kp.public_key, .lower);
    const roots = [_][]const u8{ &root_a, &root_b, &root_c };
    const roots_a = [_][]const u8{ &root_b, &root_c };
    const roots_b = [_][]const u8{ &root_a, &root_c };
    const roots_c = [_][]const u8{ &root_a, &root_b };
    var peer_buf: [32]u8 = undefined;
    const dial_b = [_][]const u8{try std.fmt.bufPrint(&peer_buf, "127.0.0.1:{d}", .{ports[1]})};
    const config_b = Config{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = ports[1],
        .node_id = identity_b.shortId(),
        .node_identity = &identity_b,
        .crypto_io = std.testing.io,
        .server_name = "far-presence-b.test",
        .mesh_pass = "far-presence-secret",
        .mesh_trust_roots = &roots_b,
        .require_secured = true,
        .relay_v2_authoring = .active,
        .relay_v2_activation_epoch = 1,
        .relay_v2_roster = &roots,
        .session_resume_composite_issuance = true,
        .account_services = &services_b,
        .num_shards = 1,
        .sweep_interval_ms = 100,
    };
    var config_a = config_b;
    config_a.s2s_port = ports[0];
    config_a.node_id = identity_a.shortId();
    config_a.node_identity = &identity_a;
    config_a.server_name = "far-presence-a.test";
    config_a.mesh_connect = &dial_b;
    config_a.mesh_trust_roots = &roots_a;
    config_a.account_services = &services_a;
    var config_c = config_a;
    config_c.s2s_port = ports[2];
    config_c.node_id = identity_c.shortId();
    config_c.node_identity = &identity_c;
    config_c.server_name = "far-presence-c.test";
    config_c.mesh_trust_roots = &roots_c;
    config_c.account_services = &services_c;
    var b = try LiveUpgradeTestNode.init(allocator, config_b);
    defer b.deinit();
    var a = try LiveUpgradeTestNode.init(allocator, config_a);
    defer a.deinit();
    var c = try LiveUpgradeTestNode.init(allocator, config_c);
    defer c.deinit();
    try b.start();
    try a.start();
    try c.start();
    const servers = [_]*Server{ a.server, b.server, c.server };
    const names = [_][]const u8{ "GuestA", "GuestB", "GuestC" };
    const live = try allocator.alloc(LiveClient, 3);
    defer allocator.free(live);
    var initialized: usize = 0;
    defer for (live[0..initialized]) |client| closeFd(client.fd);
    for (servers, live, names) |server, *client, nick| {
        client.* = .{ .fd = try connectLoopback(try server.boundPort()) };
        initialized += 1;
        var registration_buf: [200]u8 = undefined;
        const registration = try std.fmt.bufPrint(&registration_buf, "CAP REQ :echo-message message-tags server-time\r\nNICK {s}\r\nUSER ordinary 0 * :Independent {s}\r\nCAP END\r\n", .{ nick, nick });
        try writeAllFd(client.fd, registration);
        var welcome_buf: [40]u8 = undefined;
        try recvUntil(client, try std.fmt.bufPrint(&welcome_buf, " 001 {s} ", .{nick}), 200);
        try expectContains(client.written(), " ACK :echo-message message-tags server-time");
        try expectOrdinaryGuestForFarPresenceTest(server, nick);
    }
    _ = try SameIPPeerProof.wait(a.server, identity_b.sign_kp.public_key);
    _ = try SameIPPeerProof.wait(b.server, identity_a.sign_kp.public_key);
    _ = try SameIPPeerProof.wait(b.server, identity_c.sign_kp.public_key);
    _ = try SameIPPeerProof.wait(c.server, identity_b.sign_kp.public_key);
    try std.testing.expect(SameIPPeerProof.read(a.server, identity_c.sign_kp.public_key) == null);
    try std.testing.expect(SameIPPeerProof.read(c.server, identity_a.sign_kp.public_key) == null);

    // Wait for actual origin-owned PRESENCE on every direct leg. No route-table
    // seed, token, common channel, or foreign MEMBERSHIP exception supplies it.
    const roster_deadline = platform.monotonicMillis() + 20_000;
    while (true) {
        b.server.world.lockWrite();
        const middle_ready = b.server.meshNickHomeNode("GuestA") == identity_a.shortId() and
            b.server.meshNickHomeNode("GuestC") == identity_c.shortId();
        b.server.world.unlockWrite();
        a.server.world.lockWrite();
        const a_ready = a.server.meshNickHomeNode("GuestB") == identity_b.shortId();
        a.server.world.unlockWrite();
        c.server.world.lockWrite();
        const c_ready = c.server.meshNickHomeNode("GuestB") == identity_b.shortId();
        c.server.world.unlockWrite();
        if (middle_ready and a_ready and c_ready) break;
        if (platform.monotonicMillis() >= roster_deadline) return error.TestTimeout;
        testSleepMs(10);
    }
    live[1].reset();
    try writeAllFd(live[1].fd, "WHOIS GuestC\r\nPING :direct-whois-fence\r\n");
    try recvUntil(&live[1], "PONG onyx.local :direct-whois-fence", 200);
    try expectContains(live[1].written(), " 311 GuestB GuestC ordinary ");
    try expectContains(live[1].written(), " 312 GuestB GuestC far-presence-c.test ");
    try expectContains(live[1].written(), " 318 GuestB GuestC ");

    for (live) |*client| client.reset();
    try writeAllFd(live[1].fd, "PRIVMSG GuestC :ordinary-direct-control\r\n");
    try recvUntil(&live[2], "PRIVMSG GuestC :ordinary-direct-control", 200);
    try recvUntil(&live[1], "PRIVMSG GuestC :ordinary-direct-control", 200);
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(live[2].written(), "PRIVMSG GuestC :ordinary-direct-control"));
    try std.testing.expectEqual(@as(usize, 1), countOccurrences(live[1].written(), "PRIVMSG GuestC :ordinary-direct-control"));
    for (live) |*client| client.reset();

    switch (case) {
        .whois => {
            try writeAllFd(live[0].fd, "WHOIS GuestC\r\nPING :far-whois-fence\r\n");
            try recvUntil(&live[0], "PONG onyx.local :far-whois-fence", 200);
            std.debug.print("far ordinary nickname WHOIS proof: {s}\n", .{live[0].written()});
            try expectContains(live[0].written(), " 311 GuestA GuestC ordinary ");
            try expectContains(live[0].written(), " 312 GuestA GuestC far-presence-c.test ");
            try expectContains(live[0].written(), " 318 GuestA GuestC ");
        },
        .direct_message => {
            // A presence-only change cannot make a legacy DM transit. Prove the
            // genuine signed C->B frame reached B, where BOTH endpoint homes
            // are already known, while preserving legacy local-only semantics.
            const legacy_hlc = try sendFarPresenceLegacyDiagnostic(c.server, identity_b.sign_kp.public_key);
            const ingress_deadline = platform.monotonicMillis() + 5_000;
            while (true) {
                b.server.world.lockWrite();
                const admitted = b.server.relay_seen.seen.contains(.{
                    .origin_node = identity_c.shortId(),
                    .hlc = legacy_hlc,
                    .authenticated = true,
                });
                const home_matches = b.server.meshNickHomeNode("GuestC") == identity_c.shortId();
                b.server.world.unlockWrite();
                try std.testing.expect(home_matches);
                if (admitted) break;
                if (platform.monotonicMillis() >= ingress_deadline) return error.TestTimeout;
                testSleepMs(10);
            }
            live[0].reset();
            try writeAllFd(live[0].fd, "PING :legacy-terminal-fence\r\n");
            try recvUntil(&live[0], "PONG onyx.local :legacy-terminal-fence", 200);
            const legacy_deadline = platform.monotonicMillis() + 200;
            while (platform.monotonicMillis() < legacy_deadline) {
                try live[0].readAvailable();
                testSleepMs(10);
            }
            try std.testing.expectEqual(@as(usize, 0), countOccurrences(live[0].written(), "legacy-terminal-control"));
            std.debug.print("far ordinary nickname legacy control: signed C->B ingested; terminal transit, no GuestA delivery\n", .{});
            live[0].reset();
            try writeAllFd(live[0].fd, "PRIVMSG GuestC :ordinary-far-direct\r\nPING :far-dm-fence\r\n");
            try recvUntil(&live[0], "PONG onyx.local :far-dm-fence", 200);
            const delivery_deadline = platform.monotonicMillis() + 2_000;
            while (platform.monotonicMillis() < delivery_deadline) {
                try live[2].readAvailable();
                if (std.mem.indexOf(u8, live[2].written(), "PRIVMSG GuestC :ordinary-far-direct") != null) break;
                testSleepMs(10);
            }
            std.debug.print("far ordinary nickname DM author={s}\nrecipient={s}\n", .{ live[0].written(), live[2].written() });
            try expectContains(live[2].written(), "PRIVMSG GuestC :ordinary-far-direct");
            try std.testing.expectEqual(@as(usize, 1), countOccurrences(live[2].written(), "PRIVMSG GuestC :ordinary-far-direct"));
            try expectContains(live[0].written(), "PRIVMSG GuestC :ordinary-far-direct");
            try std.testing.expectEqual(@as(usize, 1), countOccurrences(live[0].written(), "PRIVMSG GuestC :ordinary-far-direct"));
        },
    }
}

test "threaded server: far ordinary nickname WHOIS crosses secured A-B-C without portable tokens" {
    try runFarOrdinaryNickRegression(.whois);
}

test "threaded server: far ordinary nickname direct DM crosses secured A-B-C without portable tokens" {
    try runFarOrdinaryNickRegression(.direct_message);
}

test "threaded server: same-IP mesh dial partition heals after inbound binding and sequential Helix" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;
    const alloc = std.testing.allocator;
    const cross_process_lock = if (builtin.os.tag == .linux) try acquireHeavyMeshAcceptanceTestLock() else -1;
    defer if (cross_process_lock >= 0) closeFd(cross_process_lock);
    const ports = try reserveThreeLoopbackPorts();
    var tmp_a = std.testing.tmpDir(.{});
    defer tmp_a.cleanup();
    var tmp_b = std.testing.tmpDir(.{});
    defer tmp_b.cleanup();
    var tmp_c = std.testing.tmpDir(.{});
    defer tmp_c.cleanup();
    var store_a = try services_mod.OroStore.open(alloc, std.testing.io, tmp_a.dir, "same-ip-a.wal");
    defer store_a.deinit();
    var store_b = try services_mod.OroStore.open(alloc, std.testing.io, tmp_b.dir, "same-ip-b.wal");
    defer store_b.deinit();
    var store_c = try services_mod.OroStore.open(alloc, std.testing.io, tmp_c.dir, "same-ip-c.wal");
    defer store_c.deinit();
    var services_a = services_mod.Services.init(&store_a, null);
    var services_b = services_mod.Services.init(&store_b, null);
    var services_c = services_mod.Services.init(&store_c, null);
    var id_a = try node_identity.fromSeed(@as([32]u8, @splat(0xe1)), "same-ip-redial-test");
    defer id_a.deinit();
    var id_b = try node_identity.fromSeed(@as([32]u8, @splat(0xe2)), "same-ip-redial-test");
    defer id_b.deinit();
    var id_c = try node_identity.fromSeed(@as([32]u8, @splat(0xe3)), "same-ip-redial-test");
    defer id_c.deinit();
    const root_a = std.fmt.bytesToHex(id_a.sign_kp.public_key, .lower);
    const root_b = std.fmt.bytesToHex(id_b.sign_kp.public_key, .lower);
    const root_c = std.fmt.bytesToHex(id_c.sign_kp.public_key, .lower);
    const roots = [_][]const u8{ &root_a, &root_b, &root_c };
    const roots_a = [_][]const u8{ &root_b, &root_c };
    const roots_b = [_][]const u8{ &root_a, &root_c };
    const roots_c = [_][]const u8{ &root_a, &root_b };
    var a_spec_buf: [32]u8 = undefined;
    var b_spec_buf: [32]u8 = undefined;
    const dial_a = [_][]const u8{try std.fmt.bufPrint(&a_spec_buf, "127.0.0.1:{d}", .{ports[0]})};
    const dial_b = [_][]const u8{try std.fmt.bufPrint(&b_spec_buf, "127.0.0.1:{d}", .{ports[1]})};
    const config_a = Config{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = ports[0],
        .node_id = id_a.shortId(),
        .node_identity = &id_a,
        .crypto_io = std.testing.io,
        .server_name = "zz-redial-a.test",
        .mesh_pass = "same-ip-secret",
        .mesh_trust_roots = &roots_a,
        .require_secured = true,
        .mesh_connect = &dial_b,
        .relay_v2_authoring = .active,
        .relay_v2_activation_epoch = 1,
        .relay_v2_roster = &roots,
        .account_services = &services_a,
        .sasl_checker = test_dm_relay_checker,
        .num_shards = 1,
        .sweep_interval_ms = 100,
    };
    var config_b = config_a;
    config_b.s2s_port = ports[1];
    config_b.node_id = id_b.shortId();
    config_b.node_identity = &id_b;
    config_b.server_name = "aa-redial-b.test";
    config_b.mesh_connect = &dial_a;
    config_b.mesh_trust_roots = &roots_b;
    config_b.account_services = &services_b;
    var config_c = config_a;
    config_c.s2s_port = ports[2];
    config_c.node_id = id_c.shortId();
    config_c.node_identity = &id_c;
    config_c.server_name = "cc-redial-c.test";
    config_c.mesh_connect = &dial_a;
    config_c.mesh_trust_roots = &roots_c;
    config_c.account_services = &services_c;
    var a = try LiveUpgradeTestNode.init(alloc, config_a);
    defer a.deinit();
    var b = try LiveUpgradeTestNode.init(alloc, config_b);
    defer b.deinit();
    // Both listeners exist before their reciprocal boot dials run.
    try a.start();
    try b.start();
    const live = try alloc.alloc(LiveClient, 3);
    defer alloc.free(live);
    live[0] = .{ .fd = try connectLoopback(try a.server.boundPort()) };
    defer closeFd(live[0].fd);
    live[1] = .{ .fd = try connectLoopback(try b.server.boundPort()) };
    defer closeFd(live[1].fd);
    const caps = "echo-message message-tags server-time";
    try saslPlainPreludeWithCaps(live[0].fd, "nova", "pw", caps);
    try writeAllFd(live[0].fd, "NICK DialA\r\nUSER a 0 * :Dial A\r\n");
    try recvUntil(&live[0], " 001 DialA ", 200);
    try saslPlainPreludeWithCaps(live[1].fd, "nova", "pw", caps);
    try writeAllFd(live[1].fd, "NICK DialB\r\nUSER b 0 * :Dial B\r\n");
    try recvUntil(&live[1], " 001 DialB ", 200);
    try expectMeshPeerVisible(&live[0], config_b.server_name, 80);
    // Wait through several actual periodic dials. B has the smaller name, so
    // A's managed endpoint must follow the B->A authenticated inbound survivor.
    const settle_deadline = platform.monotonicMillis() + 20_000;
    var before_b = try SameIPPeerProof.wait(a.server, id_b.sign_kp.public_key);
    while (before_b.initiator or !before_b.bound or before_b.target == null) {
        if (platform.monotonicMillis() >= settle_deadline) return error.TestTimeout;
        testSleepMs(20);
        before_b = try SameIPPeerProof.wait(a.server, id_b.sign_kp.public_key);
    }
    try std.testing.expectEqual(std.mem.nativeToBig(u16, ports[1]), before_b.target.?.port);
    var c = try LiveUpgradeTestNode.init(alloc, config_c);
    defer c.deinit();
    try c.start();
    live[2] = .{ .fd = try connectLoopback(try c.server.boundPort()) };
    defer closeFd(live[2].fd);
    try saslPlainPreludeWithCaps(live[2].fd, "kazu", "pw", caps);
    try writeAllFd(live[2].fd, "NICK DialC\r\nUSER c 0 * :Dial C\r\n");
    try recvUntil(&live[2], " 001 DialC ", 200);
    try expectMeshPeersVisible(&live[0], &.{ config_b.server_name, config_c.server_name }, 80);
    try expectMeshPeerVisible(&live[1], config_a.server_name, 80);
    try expectMeshPeerVisible(&live[2], config_a.server_name, 80);
    const before_c = try SameIPPeerProof.wait(a.server, id_c.sign_kp.public_key);
    try std.testing.expect(!before_c.initiator and before_c.target == null and !before_c.bound);
    try std.testing.expect(SameIPPeerProof.read(b.server, id_c.sign_kp.public_key) == null);
    try std.testing.expect(SameIPPeerProof.read(c.server, id_b.sign_kp.public_key) == null);
    for (live) |*client| {
        client.reset();
        try writeAllFd(client.fd, "JOIN #same-ip\r\n");
        try recvUntil(client, " 366 ", 200);
    }
    const clients = [_]*LiveClient{ &live[0], &live[1], &live[2] };
    try SameIPPeerProof.expectMembers(clients[0], &.{ "DialA", "DialB", "DialC" });
    try SameIPPeerProof.expectMembers(clients[1], &.{ "DialA", "DialB" });
    try SameIPPeerProof.expectMembers(clients[2], &.{ "DialA", "DialC" });
    try expectSharedUpgradeMessage(&clients, 1, "#same-ip", "before-same-ip-upgrades");

    var adopted_b = before_b;
    if (comptime builtin.os.tag == .linux) {
        // Linux's in-process seam uses the production safe-point seal and full
        // transactional adoption. Native Helix uses its separate process/fd
        // handoff acceptance campaign; its socket partition proof below still
        // runs here without a platform skip.
        const summary_a = try a.upgrade(config_a);
        try std.testing.expectEqual(@as(usize, 2), summary_a.s2s_preserved);
        adopted_b = try SameIPPeerProof.wait(a.server, id_b.sign_kp.public_key);
        const adopted_c = try SameIPPeerProof.wait(a.server, id_c.sign_kp.public_key);
        try std.testing.expectEqual(before_b.fd, adopted_b.fd);
        try std.testing.expectEqual(before_c.fd, adopted_c.fd);
        try std.testing.expect(!adopted_b.initiator and adopted_b.bound);
        try std.testing.expectEqualDeep(before_b.target.?, adopted_b.target.?);
        try std.testing.expect(!adopted_c.initiator and adopted_c.target == null and !adopted_c.bound);
        const b_before_a = try SameIPPeerProof.wait(b.server, id_a.sign_kp.public_key);
        const summary_b = try b.upgrade(config_b);
        try std.testing.expectEqual(@as(usize, 1), summary_b.s2s_preserved);
        const b_after_a = try SameIPPeerProof.wait(b.server, id_a.sign_kp.public_key);
        try std.testing.expectEqual(b_before_a.fd, b_after_a.fd);
    }
    try expectSharedUpgradeMessage(&clients, 2, "#same-ip", "after-same-ip-upgrades");
    testSleepMs(1_000);
    const stable_b = try SameIPPeerProof.wait(a.server, id_b.sign_kp.public_key);
    try std.testing.expectEqual(adopted_b.fd, stable_b.fd);
    try std.testing.expectEqual(adopted_b.collapses, stable_b.collapses);

    // Partition just A-B; C remains inbound on the SAME source IP. Hold both
    // configured dials, then permit only A's periodic dial to heal. B cannot
    // hide the regression by dialing A from the other side.
    SameIPPeerProof.pauseDial(a.server, true);
    SameIPPeerProof.pauseDial(b.server, true);
    try SameIPPeerProof.closePeer(a.server, id_b.sign_kp.public_key);
    const down_deadline = platform.monotonicMillis() + 20_000;
    while (SameIPPeerProof.read(a.server, id_b.sign_kp.public_key) != null or
        SameIPPeerProof.read(b.server, id_a.sign_kp.public_key) != null)
    {
        if (platform.monotonicMillis() >= down_deadline) return error.TestTimeout;
        testSleepMs(10);
    }
    try std.testing.expectEqual(before_c.fd, (try SameIPPeerProof.wait(a.server, id_c.sign_kp.public_key)).fd);
    try expectSharedUpgradeMessage(&.{ &live[0], &live[2] }, 1, "#same-ip", "during-same-ip-partition");
    live[1].reset();
    try writeAllFd(live[1].fd, "PING :isolated-b-still-connected\r\n");
    try recvUntil(&live[1], "isolated-b-still-connected", 200);
    SameIPPeerProof.pauseDial(a.server, false);
    const healed_b = try SameIPPeerProof.wait(a.server, id_b.sign_kp.public_key);
    try std.testing.expect(healed_b.initiator and healed_b.bound);
    try std.testing.expectEqual(std.mem.nativeToBig(u16, ports[1]), healed_b.target.?.port);
    try std.testing.expectEqual(before_c.fd, (try SameIPPeerProof.wait(a.server, id_c.sign_kp.public_key)).fd);
    try expectMeshPeersVisible(&live[0], &.{ config_b.server_name, config_c.server_name }, 80);
    try SameIPPeerProof.expectMembers(clients[0], &.{ "DialA", "DialB", "DialC" });
    try SameIPPeerProof.expectMembers(clients[1], &.{ "DialA", "DialB" });
    try SameIPPeerProof.expectMembers(clients[2], &.{ "DialA", "DialC" });
    try expectSharedUpgradeMessage(&clients, 1, "#same-ip", "after-same-ip-heal-b-to-c");
    try expectSharedUpgradeMessage(&clients, 2, "#same-ip", "after-same-ip-heal-c-to-b");
    SameIPPeerProof.pauseDial(b.server, false);
    // B's formerly unknown inbound endpoint gets one authenticated probe when
    // its configured dial resumes. That reciprocal collapse may choose a new
    // physical route; thereafter both bindings prevent repeated dial churn.
    const reciprocal_deadline = platform.monotonicMillis() + 20_000;
    var final_b = try SameIPPeerProof.wait(a.server, id_b.sign_kp.public_key);
    while (final_b.initiator or !final_b.bound) {
        if (platform.monotonicMillis() >= reciprocal_deadline) return error.TestTimeout;
        testSleepMs(20);
        final_b = try SameIPPeerProof.wait(a.server, id_b.sign_kp.public_key);
    }
    testSleepMs(1_000);
    const settled_b = try SameIPPeerProof.wait(a.server, id_b.sign_kp.public_key);
    try std.testing.expectEqual(final_b.fd, settled_b.fd);
    try std.testing.expectEqual(final_b.collapses, settled_b.collapses);
    try expectSharedUpgradeMessage(&clients, 0, "#same-ip", "after-reciprocal-probe-settled");
    try std.testing.expect(SameIPPeerProof.read(b.server, id_c.sign_kp.public_key) == null);
    try std.testing.expect(SameIPPeerProof.read(c.server, id_b.sign_kp.public_key) == null);
}

test "threaded server: four-client reusable session and MARKREAD survive sequential Helix upgrades across secured mesh" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    const cross_process_lock = try acquireHeavyMeshAcceptanceTestLock();
    defer closeFd(cross_process_lock);
    const s2s_ports = reserveTwoLoopbackPorts() catch return error.SkipZigTest;

    var tmp1 = std.testing.tmpDir(.{});
    defer tmp1.cleanup();
    var tmp2 = std.testing.tmpDir(.{});
    defer tmp2.cleanup();
    var store1 = try services_mod.OroStore.open(alloc, std.testing.io, tmp1.dir, "mesh-helix-node1.wal");
    defer store1.deinit();
    var store2 = try services_mod.OroStore.open(alloc, std.testing.io, tmp2.dir, "mesh-helix-node2.wal");
    defer store2.deinit();
    var services1 = services_mod.Services.init(&store1, null);
    var services2 = services_mod.Services.init(&store2, null);
    var ident1 = try node_identity.fromSeed(@as([32]u8, @splat(0xB1)), "mesh-helix-session-test");
    defer ident1.deinit();
    var ident2 = try node_identity.fromSeed(@as([32]u8, @splat(0xB2)), "mesh-helix-session-test");
    defer ident2.deinit();
    const root1 = std.fmt.bytesToHex(ident1.sign_kp.public_key, .lower);
    const root2 = std.fmt.bytesToHex(ident2.sign_kp.public_key, .lower);
    const roots_for_node1 = [_][]const u8{&root2};
    const roots_for_node2 = [_][]const u8{&root1};
    const relay_v2_helix_roster = [_][]const u8{ &root1, &root2 };

    var node2_config = Config{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = s2s_ports[1],
        .node_id = ident2.shortId(),
        .server_name = "helix-session-node2.test",
        .node_identity = &ident2,
        .crypto_io = std.testing.io,
        .session_resume_composite_issuance = true,
        .mesh_pass = "mesh-helix-shared-secret",
        .mesh_trust_roots = &roots_for_node2,
        .require_secured = true,
        .relay_v2_authoring = .active,
        .relay_v2_activation_epoch = 1,
        .relay_v2_roster = &relay_v2_helix_roster,
        .sasl_checker = test_dm_relay_checker,
        .account_services = &services2,
        .num_shards = 1,
        .sweep_interval_ms = 100,
    };
    var node2 = try LiveUpgradeTestNode.init(alloc, node2_config);
    defer node2.deinit();
    try node2.start();
    try std.testing.expect(node2.server.authoredRelayV2Configured());
    const port2 = try node2.server.boundPort();

    var peer_buf: [32]u8 = undefined;
    const peer = try std.fmt.bufPrint(&peer_buf, "127.0.0.1:{d}", .{s2s_ports[1]});
    const peers = [_][]const u8{peer};
    var node1_config = Config{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = s2s_ports[0],
        .node_id = ident1.shortId(),
        .server_name = "helix-session-node1.test",
        .node_identity = &ident1,
        .crypto_io = std.testing.io,
        .session_resume_composite_issuance = true,
        .mesh_pass = "mesh-helix-shared-secret",
        .mesh_trust_roots = &roots_for_node1,
        .require_secured = true,
        .relay_v2_authoring = .active,
        .relay_v2_activation_epoch = 1,
        .relay_v2_roster = &relay_v2_helix_roster,
        .mesh_connect = &peers,
        .sasl_checker = test_dm_relay_checker,
        .account_services = &services1,
        .num_shards = 2,
        .sweep_interval_ms = 100,
    };
    var node1 = try LiveUpgradeTestNode.init(alloc, node1_config);
    defer node1.deinit();
    try node1.start();
    try std.testing.expect(node1.server.authoredRelayV2Configured());
    const port1 = try node1.server.boundPort();

    const live_storage = try alloc.alloc(LiveClient, 4);
    defer alloc.free(live_storage);
    const fd_a = connectLoopback(port1) catch return error.SkipZigTest;
    defer closeFd(fd_a);
    const fd_d = connectLoopback(port1) catch return error.SkipZigTest;
    defer closeFd(fd_d);
    const fd_b = connectLoopback(port2) catch return error.SkipZigTest;
    defer closeFd(fd_b);
    const fd_c = connectLoopback(port2) catch return error.SkipZigTest;
    defer closeFd(fd_c);
    live_storage[0] = .{ .fd = fd_a };
    live_storage[1] = .{ .fd = fd_d };
    live_storage[2] = .{ .fd = fd_b };
    live_storage[3] = .{ .fd = fd_c };
    const clients = [_]*LiveClient{ &live_storage[0], &live_storage[1], &live_storage[2], &live_storage[3] };
    const caps = "echo-message message-tags server-time onyx/session-sync draft/read-marker";

    try saslPlainPreludeWithCaps(fd_a, "nova", "pw", caps);
    try writeAllFd(fd_a, "NICK Nova\r\nUSER nova 0 * :Helix origin\r\n");
    try recvUntil(clients[0], " 001 Nova ", 300);
    try expectMeshPeerVisible(clients[0], "helix-session-node2.test", 100);
    try writeAllFd(fd_a, "JOIN #helix-mesh\r\n");
    try recvUntil(clients[0], " 366 Nova #helix-mesh ", 300);
    clients[0].reset();
    try writeAllFd(fd_a, "SESSION TOKEN\r\n");
    try recvUntil(clients[0], "SESSION MTOKEN ", 500);
    const local_token_reply = testSessionTokenFromReply(clients[0].written(), "SESSION TOKEN ") orelse
        return error.TestUnexpectedResult;
    if (local_token_reply.len > session_resume_credential.local_text_len) return error.TestUnexpectedResult;
    var local_token_buf: [session_resume_credential.local_text_len]u8 = undefined;
    @memcpy(local_token_buf[0..local_token_reply.len], local_token_reply);
    const local_token = local_token_buf[0..local_token_reply.len];
    _ = try expectFreshMeshSessionToken(
        clients[0].written(),
        node1_config.mesh_pass,
        "nova",
        local_token,
    );
    var mesh_token_buf: [1024]u8 = undefined;
    const mesh_token = try testLegacyMeshResumeCredential(
        &mesh_token_buf,
        node1_config.mesh_pass,
        "nova",
        local_token,
        "helix-session-node1.test",
    );
    var resume_buf: [1200]u8 = undefined;
    const resume_command = try std.fmt.bufPrint(&resume_buf, "SESSION RESUME {s}\r\n", .{mesh_token});

    try saslPlainPreludeWithCaps(fd_d, "nova", "pw", caps);
    try writeAllFd(fd_d, "NICK DeviceD\r\nUSER nova 0 * :Helix local sibling\r\n");
    try recvUntil(clients[1], " 001 DeviceD ", 300);
    try resumeLiveMeshSession(clients[1], resume_command);
    try recvUntil(clients[1], "JOIN #helix-mesh", 300);
    try expectContains(clients[1].written(), "JOIN #helix-mesh");

    try saslPlainPreludeWithCaps(fd_b, "nova", "pw", caps);
    try writeAllFd(fd_b, "NICK DeviceB\r\nUSER nova 0 * :Helix remote sibling B\r\n");
    try recvUntil(clients[2], " 001 DeviceB ", 300);
    try resumeLiveMeshSession(clients[2], resume_command);
    try recvUntil(clients[2], "JOIN #helix-mesh", 300);
    try expectContains(clients[2].written(), "JOIN #helix-mesh");

    try saslPlainPreludeWithCaps(fd_c, "nova", "pw", caps);
    try writeAllFd(fd_c, "NICK DeviceC\r\nUSER nova 0 * :Helix remote sibling C\r\n");
    try recvUntil(clients[3], " 001 DeviceC ", 300);
    try resumeLiveMeshSession(clients[3], resume_command);
    try recvUntil(clients[3], "JOIN #helix-mesh", 300);
    try expectContains(clients[3].written(), "JOIN #helix-mesh");

    try expectSharedUpgradeMessage(&clients, 0, "#helix-mesh", "before-either-upgrade");
    try expectSharedUpgradeMarker(&clients, 0, "2026-06-04T12:00:00.000Z");
    for (clients) |client| client.reset();
    testSleepMs(150);
    for (clients) |client| {
        try client.readAvailable();
        client.reset();
    }

    node1_config.s2s_port = 0;
    const node1_upgrade = try node1.upgrade(node1_config);
    try std.testing.expect(node1.server.authoredRelayV2Configured());
    try std.testing.expectEqual(@as(usize, 2), node1_upgrade.clients);
    try std.testing.expectEqual(@as(usize, 1), node1_upgrade.s2s_preserved);
    try std.testing.expectEqual(@as(usize, 3), node1_upgrade.state_fds);
    try expectNoUpgradeTopologyChurn(&clients);
    try expectAllUpgradeClientsPing(&clients, "after-node1");
    for (clients) |client| try expectLiveSessionToken(client, local_token, node1_config.mesh_pass, "nova");
    try expectMeshPeerVisible(clients[0], "helix-session-node2.test", 100);
    try expectMeshPeerVisible(clients[2], "helix-session-node1.test", 100);
    try expectSharedUpgradeMarker(&clients, null, "2026-06-04T12:00:00.000Z");
    try expectSharedUpgradeMarker(&clients, 3, "2026-06-04T12:00:01.000Z");
    inline for (0..4) |sender_index| {
        var body_buf: [64]u8 = undefined;
        const body = try std.fmt.bufPrint(&body_buf, "after-node1-from-{d}", .{sender_index});
        try expectSharedUpgradeMessage(&clients, sender_index, "#helix-mesh", body);
    }

    for (clients) |client| client.reset();
    testSleepMs(150);
    for (clients) |client| {
        try client.readAvailable();
        client.reset();
    }
    node2_config.s2s_port = 0;
    const node2_upgrade = try node2.upgrade(node2_config);
    try std.testing.expect(node2.server.authoredRelayV2Configured());
    try std.testing.expectEqual(@as(usize, 2), node2_upgrade.clients);
    try std.testing.expectEqual(@as(usize, 1), node2_upgrade.s2s_preserved);
    try std.testing.expectEqual(@as(usize, 3), node2_upgrade.state_fds);
    try expectNoUpgradeTopologyChurn(&clients);
    try expectAllUpgradeClientsPing(&clients, "after-node2");
    for (clients) |client| try expectLiveSessionToken(client, local_token, node1_config.mesh_pass, "nova");
    try expectMeshPeerVisible(clients[0], "helix-session-node2.test", 100);
    try expectMeshPeerVisible(clients[2], "helix-session-node1.test", 100);
    try expectSharedUpgradeMarker(&clients, null, "2026-06-04T12:00:01.000Z");
    try expectSharedUpgradeMarker(&clients, 1, "2026-06-04T12:00:02.000Z");
    inline for (0..4) |sender_index| {
        var body_buf: [64]u8 = undefined;
        const body = try std.fmt.bufPrint(&body_buf, "after-node2-from-{d}", .{sender_index});
        try expectSharedUpgradeMessage(&clients, sender_index, "#helix-mesh", body);
    }

    // A freshly minted portable envelope after both upgrades must still carry
    // the original stable token and attach a new device on the opposite node;
    // the four existing transports remain connected and see no logical JOIN.
    clients[0].reset();
    try writeAllFd(clients[0].fd, "SESSION TOKEN\r\n");
    try recvUntil(clients[0], "SESSION MTOKEN ", 500);
    try std.testing.expectEqualStrings(
        local_token,
        testSessionTokenFromReply(clients[0].written(), "SESSION TOKEN ") orelse
            return error.TestUnexpectedResult,
    );
    _ = try expectFreshMeshSessionToken(
        clients[0].written(),
        node1_config.mesh_pass,
        "nova",
        local_token,
    );
    var fresh_mesh_buf: [1024]u8 = undefined;
    const fresh_mesh_reply = try testLegacyMeshResumeCredential(
        &fresh_mesh_buf,
        node1_config.mesh_pass,
        "nova",
        local_token,
        "helix-session-node1.test",
    );
    const fresh_resume = try std.fmt.bufPrint(
        &resume_buf,
        "SESSION RESUME {s}\r\n",
        .{fresh_mesh_reply},
    );
    for (clients) |client| client.reset();

    const fd_e = connectLoopback(try node2.server.boundPort()) catch return error.SkipZigTest;
    defer closeFd(fd_e);
    var extra = LiveClient{ .fd = fd_e };
    try saslPlainPreludeWithCaps(fd_e, "nova", "pw", caps);
    try writeAllFd(fd_e, "NICK DeviceE\r\nUSER nova 0 * :Helix post-upgrade sibling E\r\n");
    try recvUntil(&extra, " 001 DeviceE ", 300);
    try resumeLiveMeshSession(&extra, fresh_resume);
    try recvUntil(&extra, "JOIN #helix-mesh", 300);
    try expectContains(extra.written(), "JOIN #helix-mesh");
    try expectNoUpgradeTopologyChurn(&clients);
    const all_clients = [_]*LiveClient{
        clients[0], clients[1], clients[2], clients[3], &extra,
    };
    try expectAllUpgradeClientsPing(&all_clients, "after-fifth-attach");
    try expectLiveSessionToken(&extra, local_token, node1_config.mesh_pass, "nova");
    try expectSharedUpgradeMarker(&all_clients, null, "2026-06-04T12:00:02.000Z");
    try expectSharedUpgradeMarker(&all_clients, 4, "2026-06-04T12:00:03.000Z");
    try expectSharedUpgradeMessage(&all_clients, 4, "#helix-mesh", "post-upgrade-fifth-client-participates");
    try expectSharedUpgradeMessage(&all_clients, 0, "Nova", "opposite-node-self-dm-after-both-upgrades");
}

test "threaded server: reusable session and MARKREAD stay exact-once across a three-node secured line" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    const cross_process_lock = try acquireHeavyMeshAcceptanceTestLock();
    defer closeFd(cross_process_lock);
    const s2s_ports = reserveThreeLoopbackPorts() catch return error.SkipZigTest;

    var tmp1 = std.testing.tmpDir(.{});
    defer tmp1.cleanup();
    var tmp2 = std.testing.tmpDir(.{});
    defer tmp2.cleanup();
    var tmp3 = std.testing.tmpDir(.{});
    defer tmp3.cleanup();
    var store1 = try services_mod.OroStore.open(alloc, std.testing.io, tmp1.dir, "mesh-line-node1.wal");
    defer store1.deinit();
    var store2 = try services_mod.OroStore.open(alloc, std.testing.io, tmp2.dir, "mesh-line-node2.wal");
    defer store2.deinit();
    var store3 = try services_mod.OroStore.open(alloc, std.testing.io, tmp3.dir, "mesh-line-node3.wal");
    defer store3.deinit();
    var services1 = services_mod.Services.init(&store1, null);
    var services2 = services_mod.Services.init(&store2, null);
    var services3 = services_mod.Services.init(&store3, null);

    var ident1 = try node_identity.fromSeed(@as([32]u8, @splat(0xA1)), "mesh-session-line-test");
    defer ident1.deinit();
    var ident2 = try node_identity.fromSeed(@as([32]u8, @splat(0xA2)), "mesh-session-line-test");
    defer ident2.deinit();
    var ident3 = try node_identity.fromSeed(@as([32]u8, @splat(0xA3)), "mesh-session-line-test");
    defer ident3.deinit();
    const root1 = std.fmt.bytesToHex(ident1.sign_kp.public_key, .lower);
    const root2 = std.fmt.bytesToHex(ident2.sign_kp.public_key, .lower);
    const root3 = std.fmt.bytesToHex(ident3.sign_kp.public_key, .lower);
    const roots_for_node1 = [_][]const u8{&root2};
    const roots_for_node2 = [_][]const u8{ &root1, &root3 };
    const roots_for_node3 = [_][]const u8{&root2};
    const relay_v2_line_roster = [_][]const u8{ &root1, &root2, &root3 };

    var node2_spec_buf: [32]u8 = undefined;
    const node2_spec = try std.fmt.bufPrint(&node2_spec_buf, "127.0.0.1:{d}", .{s2s_ports[1]});
    const node1_to_node2 = [_][]const u8{node2_spec};

    // A strict line: node 1 dials node 2, node 2 dials node 3, and there is no
    // node-1/node-3 connection. End-to-end traffic therefore has to survive a
    // real forwarding hop through node 2 rather than accidentally using a clique.
    const node3 = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = s2s_ports[2],
        .node_id = ident3.shortId(),
        .server_name = "session-line-node3.test",
        .node_identity = &ident3,
        .crypto_io = std.testing.io,
        .session_resume_composite_issuance = true,
        .mesh_pass = "mesh-session-line-secret",
        .mesh_trust_roots = &roots_for_node3,
        .require_secured = true,
        .relay_v2_authoring = .active,
        .relay_v2_activation_epoch = 1,
        .relay_v2_roster = &relay_v2_line_roster,
        .sasl_checker = test_dm_relay_checker,
        .account_services = &services3,
        .num_shards = 1,
        .sweep_interval_ms = 100,
    }) catch |err| {
        return switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => error.SkipZigTest,
            else => err,
        };
    };
    defer {
        node3.deinit();
        alloc.destroy(node3);
    }

    const node2 = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = s2s_ports[1],
        .node_id = ident2.shortId(),
        .server_name = "session-line-node2.test",
        .node_identity = &ident2,
        .crypto_io = std.testing.io,
        .session_resume_composite_issuance = true,
        .mesh_pass = "mesh-session-line-secret",
        .mesh_trust_roots = &roots_for_node2,
        .require_secured = true,
        .relay_v2_authoring = .active,
        .relay_v2_activation_epoch = 1,
        .relay_v2_roster = &relay_v2_line_roster,
        // This edge is opened explicitly by an oper below, so the acceptance
        // test can hold it down deterministically between SQUIT and CONNECT.
        .sasl_checker = test_line_mesh_checker,
        .oper_registry = oper_mod.OperRegistry.init(&test_oper_bindings) catch unreachable,
        .account_services = &services2,
        .num_shards = 1,
        .sweep_interval_ms = 100,
    }) catch |err| {
        return switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => error.SkipZigTest,
            else => err,
        };
    };
    defer {
        node2.deinit();
        alloc.destroy(node2);
    }

    const node1 = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .s2s_port = s2s_ports[0],
        .node_id = ident1.shortId(),
        .server_name = "session-line-node1.test",
        .node_identity = &ident1,
        .crypto_io = std.testing.io,
        .session_resume_composite_issuance = true,
        .mesh_pass = "mesh-session-line-secret",
        .mesh_trust_roots = &roots_for_node1,
        .require_secured = true,
        .relay_v2_authoring = .active,
        .relay_v2_activation_epoch = 1,
        .relay_v2_roster = &relay_v2_line_roster,
        .mesh_connect = &node1_to_node2,
        .sasl_checker = test_dm_relay_checker,
        .account_services = &services1,
        .num_shards = 1,
        .sweep_interval_ms = 100,
    }) catch |err| {
        return switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => error.SkipZigTest,
            else => err,
        };
    };
    defer {
        node1.deinit();
        alloc.destroy(node1);
    }

    node3.start();
    node2.start();
    node1.start();
    try std.testing.expect(node1.authoredRelayV2Configured());
    try std.testing.expect(node2.authoredRelayV2Configured());
    try std.testing.expect(node3.authoredRelayV2Configured());
    const port1 = try node1.boundPort();
    const port2 = try node2.boundPort();
    const port3 = try node3.boundPort();
    var run1 = std.atomic.Value(bool).init(true);
    var run2 = std.atomic.Value(bool).init(true);
    var run3 = std.atomic.Value(bool).init(true);
    var thr1: ?std.Thread = null;
    var thr2: ?std.Thread = null;
    var thr3: ?std.Thread = null;
    defer {
        if (thr1 != null) node1.requestStop(&run1);
        if (thr2 != null) node2.requestStop(&run2);
        if (thr3 != null) node3.requestStop(&run3);
        if (thr1) |thread| thread.join();
        if (thr2) |thread| thread.join();
        if (thr3) |thread| thread.join();
    }
    thr3 = try std.Thread.spawn(.{}, Server.runThreaded, .{ node3, &run3 });
    thr2 = try std.Thread.spawn(.{}, Server.runThreaded, .{ node2, &run2 });
    thr1 = try std.Thread.spawn(.{}, Server.runThreaded, .{ node1, &run1 });

    // Establish B-C through the real oper CONNECT path. Unlike an auto-connect
    // dial this edge stays down after SQUIT until the test explicitly reconnects,
    // giving the retained V2 scheduler a deterministic partition window.
    const admin_fd = try connectLoopback(port2);
    defer closeFd(admin_fd);
    var admin = LiveClient{ .fd = admin_fd };
    try saslAdminPrelude(admin_fd);
    try writeAllFd(admin_fd, "NICK MeshAdmin\r\nUSER meshadmin 0 * :Line mesh admin\r\n");
    try recvUntil(&admin, " 001 MeshAdmin ", 200);
    try recvUntil(&admin, " 381 MeshAdmin ", 200);
    var connect_node3_buf: [64]u8 = undefined;
    const connect_node3 = try std.fmt.bufPrint(
        &connect_node3_buf,
        "CONNECT 127.0.0.1 {d}\r\n",
        .{s2s_ports[2]},
    );
    admin.reset();
    try writeAllFd(admin_fd, connect_node3);
    try recvUntil(&admin, "CONNECT initiated (secured)", 200);

    // Wait for both secured legs and prove the topology is a line from the client
    // surface: each edge sees only node 2, while node 2 sees both edge nodes.
    const probe1_fd = try connectLoopback(port1);
    defer closeFd(probe1_fd);
    var probe1 = LiveClient{ .fd = probe1_fd };
    try writeAllFd(probe1_fd, "NICK Probe1\r\nUSER probe 0 * :Probe One\r\n");
    try recvUntil(&probe1, " 001 Probe1 ", 200);
    try expectMeshPeerVisible(&probe1, "session-line-node2.test", 120);
    try std.testing.expect(std.mem.indexOf(u8, probe1.written(), "session-line-node3.test") == null);

    const probe2_fd = try connectLoopback(port2);
    defer closeFd(probe2_fd);
    var probe2 = LiveClient{ .fd = probe2_fd };
    try writeAllFd(probe2_fd, "NICK Probe2\r\nUSER probe 0 * :Probe Two\r\n");
    try recvUntil(&probe2, " 001 Probe2 ", 200);
    try expectMeshPeersVisible(&probe2, &.{ "session-line-node1.test", "session-line-node3.test" }, 120);

    const probe3_fd = try connectLoopback(port3);
    defer closeFd(probe3_fd);
    var probe3 = LiveClient{ .fd = probe3_fd };
    try writeAllFd(probe3_fd, "NICK Probe3\r\nUSER probe 0 * :Probe Three\r\n");
    try recvUntil(&probe3, " 001 Probe3 ", 200);
    try expectMeshPeerVisible(&probe3, "session-line-node2.test", 120);
    try std.testing.expect(std.mem.indexOf(u8, probe3.written(), "session-line-node1.test") == null);

    const clients = try alloc.alloc(LiveClient, 4);
    defer alloc.free(clients);
    const fd_a = try connectLoopback(port1);
    defer closeFd(fd_a);
    const fd_b = try connectLoopback(port2);
    defer closeFd(fd_b);
    const fd_c = try connectLoopback(port3);
    var c_open = true;
    defer if (c_open) closeFd(fd_c);
    const fd_sender = try connectLoopback(port3);
    defer closeFd(fd_sender);
    clients[0] = .{ .fd = fd_a };
    clients[1] = .{ .fd = fd_b };
    clients[2] = .{ .fd = fd_c };
    clients[3] = .{ .fd = fd_sender };
    const a = &clients[0];
    const b = &clients[1];
    const c = &clients[2];
    const sender = &clients[3];

    const Helpers = struct {
        fn attach(client: *LiveClient, command: []const u8) !void {
            for (0..100) |_| {
                client.reset();
                try writeAllFd(client.fd, command);
                const deadline = platform.monotonicMillis() + 250;
                while (platform.monotonicMillis() < deadline) {
                    var fds = [_]posix.pollfd{.{ .fd = client.fd, .events = linux.POLL.IN, .revents = 0 }};
                    const ready = posix.poll(&fds, 20) catch return error.Unexpected;
                    if (ready != 0 and (fds[0].revents & linux.POLL.IN) != 0) try client.readAvailable();
                    const got = client.written();
                    if (std.mem.indexOf(u8, got, "attached to replicated mesh session") != null or
                        std.mem.indexOf(u8, got, "attached to live mesh session") != null) return;
                }
                testSleepMs(15);
            }
            return error.TestTimeout;
        }

        fn settle(live: []const *LiveClient) !void {
            testSleepMs(80);
            for (live) |client| try client.readAvailable();
        }

        fn expectOnce(client: *const LiveClient, needle: []const u8) !void {
            try std.testing.expectEqual(@as(usize, 1), countOccurrences(client.written(), needle));
        }

        fn lineContaining(client: *const LiveClient, needle: []const u8) ?[]const u8 {
            const bytes = client.written();
            const at = std.mem.indexOf(u8, bytes, needle) orelse return null;
            const start = if (std.mem.lastIndexOfScalar(u8, bytes[0..at], '\n')) |newline| newline + 1 else 0;
            const end = if (std.mem.indexOfScalar(u8, bytes[at..], '\n')) |newline| at + newline else bytes.len;
            return bytes[start..end];
        }

        fn expectPeerAbsent(client: *LiveClient, peer_name: []const u8) !void {
            for (0..100) |_| {
                client.reset();
                try writeAllFd(client.fd, "LINKS\r\n");
                const deadline = platform.monotonicMillis() + 250;
                while (platform.monotonicMillis() < deadline) {
                    var fds = [_]posix.pollfd{.{ .fd = client.fd, .events = linux.POLL.IN, .revents = 0 }};
                    const ready = posix.poll(&fds, 20) catch return error.Unexpected;
                    if (ready != 0 and (fds[0].revents & linux.POLL.IN) != 0) try client.readAvailable();
                    if (std.mem.indexOf(u8, client.written(), " 365 ") != null) break;
                }
                if (std.mem.indexOf(u8, client.written(), " 365 ") != null and
                    std.mem.indexOf(u8, client.written(), peer_name) == null) return;
                testSleepMs(10);
            }
            return error.TestTimeout;
        }
    };

    // Mint one portable credential on node 1. Only node 2 is directly connected,
    // so node 3 receives the SAME origin-signed OFFER only through node 2's v2
    // forwarding path; no direct edge or intermediate re-signing can help it.
    const nova_caps = "echo-message message-tags server-time onyx/session-sync draft/read-marker";
    try saslPlainPreludeWithCaps(fd_a, "nova", "pw", nova_caps);
    try writeAllFd(fd_a, "NICK Nova\r\nUSER nova 0 * :Line attachment A\r\n");
    try recvUntil(a, " 001 Nova ", 200);
    try writeAllFd(fd_a, "JOIN #mesh-line\r\n");
    try recvUntil(a, " 366 Nova #mesh-line ", 200);
    a.reset();
    try writeAllFd(fd_a, "SESSION TOKEN\r\n");
    try recvUntil(a, "SESSION MTOKEN ", 200);
    const local_token_reply = testSessionTokenFromReply(a.written(), "SESSION TOKEN ") orelse
        return error.TestUnexpectedResult;
    if (local_token_reply.len > session_resume_credential.local_text_len) return error.TestUnexpectedResult;
    var local_token_buf: [session_resume_credential.local_text_len]u8 = undefined;
    @memcpy(local_token_buf[0..local_token_reply.len], local_token_reply);
    const local_token = local_token_buf[0..local_token_reply.len];
    _ = try expectFreshMeshSessionToken(
        a.written(),
        "mesh-session-line-secret",
        "nova",
        local_token,
    );
    var token_buf: [1024]u8 = undefined;
    const mesh_token = try testLegacyMeshResumeCredential(
        &token_buf,
        "mesh-session-line-secret",
        "nova",
        local_token,
        "session-line-node1.test",
    );
    var resume_buf: [1200]u8 = undefined;
    const resume_cmd = try std.fmt.bufPrint(&resume_buf, "SESSION RESUME {s}\r\n", .{mesh_token});

    try saslPlainPreludeWithCaps(fd_b, "nova", "pw", nova_caps);
    try writeAllFd(fd_b, "NICK DeviceB\r\nUSER nova 0 * :Line attachment B\r\n");
    try recvUntil(b, " 001 DeviceB ", 200);
    try Helpers.attach(b, resume_cmd);
    try expectContains(b.written(), "JOIN #mesh-line");

    try saslPlainPreludeWithCaps(fd_c, "nova", "pw", nova_caps);
    try writeAllFd(fd_c, "NICK DeviceC\r\nUSER nova 0 * :Line attachment C\r\n");
    try recvUntil(c, " 001 DeviceC ", 200);
    try Helpers.attach(c, resume_cmd);
    try expectContains(c.written(), "JOIN #mesh-line");

    // Restore sidecars are ordered after this node's exact signed OFFER. The
    // original DeviceB/DeviceC presence aliases must therefore reconcile to the
    // real logical nick without ever surfacing a collision UID JOIN/NICK beside
    // the exact #mesh-line projection on another attachment.
    try Helpers.settle(&.{ a, b, c });
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(a.written(), "JOIN :#mesh-line"));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(b.written(), "JOIN :#mesh-line"));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(c.written(), "JOIN :#mesh-line"));
    try std.testing.expect(std.mem.indexOf(u8, a.written(), ":DeviceB!") == null);
    try std.testing.expect(std.mem.indexOf(u8, a.written(), ":DeviceC!") == null);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), ":DeviceC!") == null);

    // Incremental transition silence is not enough: the converged NAMES image
    // must also collapse every receiver-derived UID/temporary alias into the
    // one signed logical identity on every node.
    for ([_]*LiveClient{ a, b, c }) |client| {
        client.reset();
        try writeAllFd(client.fd, "NAMES #mesh-line\r\n");
        try recvUntil(client, " 366 Nova #mesh-line ", 800);
        try expectExactSingleNamesRoster(client.written(), " 353 Nova = #mesh-line ", "!Nova");
        try std.testing.expect(std.mem.indexOf(u8, client.written(), "DeviceB") == null);
        try std.testing.expect(std.mem.indexOf(u8, client.written(), "DeviceC") == null);
    }

    // State changes after every original attachment is live must converge from
    // the exact-token signed snapshot, including across node 2's forwarding hop.
    // B initiates the first JOIN from the middle node; both edges receive one
    // synthetic logical JOIN and become real participants.
    a.reset();
    b.reset();
    c.reset();
    try writeAllFd(fd_b, "JOIN #mesh-late\r\n");
    try recvUntil(b, " 366 Nova #mesh-late ", 400);
    try recvUntil(a, "JOIN :#mesh-late", 800);
    try recvUntil(c, "JOIN :#mesh-late", 800);
    try Helpers.settle(&.{ a, c });
    try Helpers.expectOnce(a, "JOIN :#mesh-late");
    try Helpers.expectOnce(c, "JOIN :#mesh-late");

    // A fourth client resumes only AFTER that mutation. It must restore the
    // latest retained snapshot on the far node, not the TOKEN-time snapshot.
    const fd_d = try connectLoopback(port3);
    defer closeFd(fd_d);
    var d = LiveClient{ .fd = fd_d };
    try saslPlainPreludeWithCaps(fd_d, "nova", "pw", nova_caps);
    try writeAllFd(fd_d, "NICK DeviceD\r\nUSER nova 0 * :Late line attachment D\r\n");
    try recvUntil(&d, " 001 DeviceD ", 200);
    try Helpers.attach(&d, resume_cmd);
    try expectContains(d.written(), "JOIN #mesh-line");
    try expectContains(d.written(), "JOIN #mesh-late");

    // PART from the far edge removes every attachment once. Then JOIN from the
    // origin edge and PART from another far-edge attachment prove either side
    // can continue mutating the same logical session without ownership transfer.
    a.reset();
    b.reset();
    c.reset();
    d.reset();
    try writeAllFd(fd_d, "PART #mesh-late\r\n");
    try recvUntil(&d, "PART #mesh-late", 400);
    try recvUntil(c, "PART #mesh-late", 400);
    try recvUntil(b, "PART #mesh-late", 800);
    try recvUntil(a, "PART #mesh-late", 800);
    try Helpers.settle(&.{ a, b, c, &d });
    try Helpers.expectOnce(a, "PART #mesh-late");
    try Helpers.expectOnce(b, "PART #mesh-late");
    try Helpers.expectOnce(c, "PART #mesh-late");
    try Helpers.expectOnce(&d, "PART #mesh-late");

    a.reset();
    b.reset();
    c.reset();
    d.reset();
    try writeAllFd(fd_a, "JOIN #mesh-late\r\n");
    try recvUntil(a, " 366 Nova #mesh-late ", 400);
    try recvUntil(b, "JOIN :#mesh-late", 800);
    try recvUntil(c, "JOIN :#mesh-late", 800);
    try recvUntil(&d, "JOIN :#mesh-late", 800);
    try Helpers.settle(&.{ b, c, &d });
    try Helpers.expectOnce(b, "JOIN :#mesh-late");
    try Helpers.expectOnce(c, "JOIN :#mesh-late");
    try Helpers.expectOnce(&d, "JOIN :#mesh-late");

    a.reset();
    b.reset();
    c.reset();
    d.reset();
    try writeAllFd(fd_c, "PART #mesh-late\r\n");
    try recvUntil(c, "PART #mesh-late", 400);
    try recvUntil(&d, "PART #mesh-late", 400);
    try recvUntil(b, "PART #mesh-late", 800);
    try recvUntil(a, "PART #mesh-late", 800);
    try Helpers.settle(&.{ a, b, c, &d });
    try Helpers.expectOnce(a, "PART #mesh-late");
    try Helpers.expectOnce(b, "PART #mesh-late");
    try Helpers.expectOnce(c, "PART #mesh-late");
    try Helpers.expectOnce(&d, "PART #mesh-late");

    // The independent sender lives on node 3, the far edge from the token origin.
    try saslPlainPreludeWithCaps(fd_sender, "kazu", "pw", "message-tags server-time draft/read-marker");
    try writeAllFd(fd_sender, "NICK RelaySender\r\nUSER kazu 0 * :Third-node sender\r\n");
    try recvUntil(sender, " 001 RelaySender ", 200);
    try writeAllFd(fd_sender, "JOIN #mesh-line\r\n");
    try recvUntil(sender, " 366 RelaySender #mesh-line ", 200);

    // Account positions cross the real non-clique secured line and reach all
    // four physical attachments. An unrelated account sees no private target.
    const marker1 = "MARKREAD #mesh-line timestamp=2026-06-04T12:00:00.000Z";
    inline for (.{ a, b, c, &d, sender }) |client| client.reset();
    try writeAllFd(fd_a, marker1 ++ "\r\n");
    inline for (.{ a, b, c, &d }) |client| try recvUntil(client, marker1, 600);
    try Helpers.settle(&.{ a, b, c, &d, sender });
    inline for (.{ a, b, c, &d }) |client| try Helpers.expectOnce(client, marker1);
    try std.testing.expect(std.mem.indexOf(u8, sender.written(), "MARKREAD #mesh-line") == null);
    const MarkerProof = struct {
        fn wire(server: *Server) ![]u8 {
            server.world.lockWrite();
            defer server.world.unlockWrite();
            var key: [64]u8 = undefined;
            const row = server.read_marker_facts.get(Server.readMarkerFactKey("nova", "#mesh-line", &key)) orelse return error.TestUnexpectedResult;
            return std.testing.allocator.dupe(u8, row);
        }
    };
    const origin_wire = try MarkerProof.wire(node1);
    defer alloc.free(origin_wire);
    const middle_wire = try MarkerProof.wire(node2);
    defer alloc.free(middle_wire);
    const far_wire = try MarkerProof.wire(node3);
    defer alloc.free(far_wire);
    try std.testing.expectEqualSlices(u8, origin_wire, middle_wire);
    try std.testing.expectEqualSlices(u8, origin_wire, far_wire);
    try std.testing.expectEqual(ident1.shortId(), (try entity_prop_event.decode(far_wire)).origin_node);

    // The far edge may author a greater timestamp for the same account even
    // while the account also has a local attachment on the origin node.
    const marker2 = "MARKREAD #mesh-line timestamp=2026-06-04T12:00:01.000Z";
    inline for (.{ a, b, c, &d, sender }) |client| client.reset();
    try writeAllFd(fd_d, marker2 ++ "\r\n");
    inline for (.{ a, b, c, &d }) |client| try recvUntil(client, marker2, 600);
    try Helpers.settle(&.{ a, b, c, &d, sender });
    inline for (.{ a, b, c, &d }) |client| try Helpers.expectOnce(client, marker2);
    try std.testing.expect(std.mem.indexOf(u8, sender.written(), "MARKREAD #mesh-line") == null);
    sender.reset();
    try writeAllFd(fd_sender, "PROP nova\r\nMARKREAD #mesh-line\r\n");
    try recvUntil(sender, "MARKREAD #mesh-line *", 200);
    try std.testing.expect(std.mem.indexOf(u8, sender.written(), "read.marker/") == null);
    try std.testing.expect(std.mem.indexOf(u8, sender.written(), "2026-06-04T12:00:01.000Z") == null);

    // Third-party channel and direct events reach every live attachment exactly
    // once. msgid/time equality proves the two-hop copy is the same event, not a
    // locally reminted duplicate on the forwarding node.
    a.reset();
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_sender, "PRIVMSG #mesh-line :third-node-channel\r\n");
    try recvUntil(c, "PRIVMSG #mesh-line :third-node-channel", 600);
    try recvUntil(b, "PRIVMSG #mesh-line :third-node-channel", 600);
    try recvUntil(a, "PRIVMSG #mesh-line :third-node-channel", 600);
    try Helpers.settle(&.{ a, b, c });
    try Helpers.expectOnce(a, "PRIVMSG #mesh-line :third-node-channel");
    try Helpers.expectOnce(b, "PRIVMSG #mesh-line :third-node-channel");
    try Helpers.expectOnce(c, "PRIVMSG #mesh-line :third-node-channel");
    const channel_needle = "PRIVMSG #mesh-line :third-node-channel";
    const channel_a_line = Helpers.lineContaining(a, channel_needle) orelse return error.TestUnexpectedResult;
    const channel_b_line = Helpers.lineContaining(b, channel_needle) orelse return error.TestUnexpectedResult;
    const channel_c_line = Helpers.lineContaining(c, channel_needle) orelse return error.TestUnexpectedResult;
    const channel_msgid = extractMsgid(channel_a_line) orelse return error.TestUnexpectedResult;
    const channel_time = extractTimeTag(channel_a_line) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(channel_msgid, extractMsgid(channel_b_line) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(channel_msgid, extractMsgid(channel_c_line) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(channel_time, extractTimeTag(channel_b_line) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(channel_time, extractTimeTag(channel_c_line) orelse return error.TestUnexpectedResult);

    a.reset();
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_sender, "PRIVMSG Nova :third-node-direct\r\n");
    try recvUntil(a, "PRIVMSG Nova :third-node-direct", 600);
    try recvUntil(b, "PRIVMSG Nova :third-node-direct", 600);
    try recvUntil(c, "PRIVMSG Nova :third-node-direct", 600);
    try Helpers.settle(&.{ a, b, c });
    try Helpers.expectOnce(a, "PRIVMSG Nova :third-node-direct");
    try Helpers.expectOnce(b, "PRIVMSG Nova :third-node-direct");
    try Helpers.expectOnce(c, "PRIVMSG Nova :third-node-direct");
    const direct_needle = "PRIVMSG Nova :third-node-direct";
    const direct_a_line = Helpers.lineContaining(a, direct_needle) orelse return error.TestUnexpectedResult;
    const direct_b_line = Helpers.lineContaining(b, direct_needle) orelse return error.TestUnexpectedResult;
    const direct_c_line = Helpers.lineContaining(c, direct_needle) orelse return error.TestUnexpectedResult;
    const direct_msgid = extractMsgid(direct_a_line) orelse return error.TestUnexpectedResult;
    const direct_time = extractTimeTag(direct_a_line) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(direct_msgid, extractMsgid(direct_b_line) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(direct_msgid, extractMsgid(direct_c_line) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(direct_time, extractTimeTag(direct_b_line) orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings(direct_time, extractTimeTag(direct_c_line) orelse return error.TestUnexpectedResult);

    // Participation works from both edge attachments and from the forwarding node.
    // The opposite edge and the independent sender each observe one copy. The
    // retained signed offer authorizes the exact token and origin across the full
    // line; relay-controlled account or nick text is never a substitute.
    b.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_a, "PRIVMSG #mesh-line :participate-node1\r\n");
    try recvUntil(b, "PRIVMSG #mesh-line :participate-node1", 600);
    try recvUntil(c, "PRIVMSG #mesh-line :participate-node1", 600);
    try recvUntil(sender, "PRIVMSG #mesh-line :participate-node1", 600);
    try Helpers.settle(&.{ b, c, sender });
    try Helpers.expectOnce(b, "PRIVMSG #mesh-line :participate-node1");
    try Helpers.expectOnce(c, "PRIVMSG #mesh-line :participate-node1");
    try Helpers.expectOnce(sender, "PRIVMSG #mesh-line :participate-node1");

    a.reset();
    b.reset();
    sender.reset();
    try writeAllFd(fd_c, "PRIVMSG #mesh-line :participate-node3\r\n");
    try recvUntil(a, "PRIVMSG #mesh-line :participate-node3", 600);
    try recvUntil(b, "PRIVMSG #mesh-line :participate-node3", 600);
    try recvUntil(sender, "PRIVMSG #mesh-line :participate-node3", 600);
    try Helpers.settle(&.{ a, b, sender });
    try Helpers.expectOnce(a, "PRIVMSG #mesh-line :participate-node3");
    try Helpers.expectOnce(b, "PRIVMSG #mesh-line :participate-node3");
    try Helpers.expectOnce(sender, "PRIVMSG #mesh-line :participate-node3");

    a.reset();
    c.reset();
    sender.reset();
    try writeAllFd(fd_b, "PRIVMSG #mesh-line :participate-node2\r\n");
    try recvUntil(a, "PRIVMSG #mesh-line :participate-node2", 600);
    try recvUntil(c, "PRIVMSG #mesh-line :participate-node2", 600);
    try recvUntil(sender, "PRIVMSG #mesh-line :participate-node2", 600);
    try Helpers.settle(&.{ a, c, sender });
    try Helpers.expectOnce(a, "PRIVMSG #mesh-line :participate-node2");
    try Helpers.expectOnce(c, "PRIVMSG #mesh-line :participate-node2");
    try Helpers.expectOnce(sender, "PRIVMSG #mesh-line :participate-node2");

    // Remove node 3's local attachment. No identity-wide QUIT is allowed, and the
    // third-party sender must immediately fall back to the remote token route:
    // node3 -> node2 (local B) -> node1 (A), still exactly once at both survivors.
    a.reset();
    b.reset();
    sender.reset();
    closeFd(fd_c);
    c_open = false;
    testSleepMs(180);
    try a.readAvailable();
    try b.readAvailable();
    try sender.readAvailable();
    try std.testing.expect(std.mem.indexOf(u8, a.written(), " QUIT ") == null);
    try std.testing.expect(std.mem.indexOf(u8, b.written(), " QUIT ") == null);
    try std.testing.expect(std.mem.indexOf(u8, sender.written(), " QUIT ") == null);

    a.reset();
    b.reset();
    sender.reset();
    try writeAllFd(fd_sender, "PRIVMSG Nova :after-node3-attachment-detach\r\n");
    try recvUntil(a, "PRIVMSG Nova :after-node3-attachment-detach", 600);
    try recvUntil(b, "PRIVMSG Nova :after-node3-attachment-detach", 600);
    try Helpers.settle(&.{ a, b });
    try Helpers.expectOnce(a, "PRIVMSG Nova :after-node3-attachment-detach");
    try Helpers.expectOnce(b, "PRIVMSG Nova :after-node3-attachment-detach");

    a.reset();
    b.reset();
    sender.reset();
    try writeAllFd(fd_sender, "PRIVMSG #mesh-line :channel-after-node3-detach\r\n");
    try recvUntil(a, "PRIVMSG #mesh-line :channel-after-node3-detach", 600);
    try recvUntil(b, "PRIVMSG #mesh-line :channel-after-node3-detach", 600);
    try Helpers.settle(&.{ a, b });
    try Helpers.expectOnce(a, "PRIVMSG #mesh-line :channel-after-node3-detach");
    try Helpers.expectOnce(b, "PRIVMSG #mesh-line :channel-after-node3-detach");

    a.reset();
    sender.reset();
    try writeAllFd(fd_b, "PRIVMSG #mesh-line :survivor-participates-through-line\r\n");
    try recvUntil(a, "PRIVMSG #mesh-line :survivor-participates-through-line", 600);
    try recvUntil(sender, "PRIVMSG #mesh-line :survivor-participates-through-line", 600);
    try Helpers.settle(&.{ a, sender });
    try Helpers.expectOnce(a, "PRIVMSG #mesh-line :survivor-participates-through-line");
    try Helpers.expectOnce(sender, "PRIVMSG #mesh-line :survivor-participates-through-line");

    a.reset();
    b.reset();
    try writeAllFd(fd_a, "PING survivor-a\r\n");
    try writeAllFd(fd_b, "PING survivor-b\r\n");
    try recvUntil(a, "PONG", 200);
    try recvUntil(b, "PONG", 200);

    // Break the only B-C leg through the real oper SQUIT path and hold it down.
    // A message authored on A during the partition must reach B immediately but
    // remain absent on C until the same secured edge is explicitly restored.
    admin.reset();
    try writeAllFd(admin_fd, "SQUIT session-line-node3.test :retained-v2-test\r\n");
    try recvUntil(&admin, "SQUIT complete", 200);
    try Helpers.expectPeerAbsent(&admin, "session-line-node3.test");
    try Helpers.expectPeerAbsent(&probe3, "session-line-node2.test");

    const marker3 = "MARKREAD #mesh-line timestamp=2026-06-04T12:00:02.000Z";
    inline for (.{ a, b, &d, sender }) |client| client.reset();
    try writeAllFd(fd_a, marker3 ++ "\r\n");
    try recvUntil(a, marker3, 200);
    try recvUntil(b, marker3, 200);
    try writeAllFd(fd_d, "MARKREAD #mesh-line\r\n");
    try recvUntil(&d, marker2, 200);
    try std.testing.expect(std.mem.indexOf(u8, d.written(), marker3) == null);

    // Mutate the reusable session while the only far edge is physically down.
    // The near-side attachment receives the change, while the far-side
    // attachment cannot. Its later synthetic JOIN is positive proof that SRST
    // retained replay crossed the restored B-C link (not a local node3 resume).
    a.reset();
    b.reset();
    d.reset();
    sender.reset();
    try writeAllFd(fd_b, "JOIN #mesh-retained\r\n");
    try recvUntil(b, " 366 Nova #mesh-retained ", 400);
    try recvUntil(a, "JOIN :#mesh-retained", 600);
    try Helpers.settle(&.{ a, b });
    try Helpers.expectOnce(a, "JOIN :#mesh-retained");
    try d.readAvailable();
    try sender.readAvailable();
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(d.written(), "JOIN :#mesh-retained"));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(sender.written(), "JOIN :#mesh-retained"));

    const retained_needle = "PRIVMSG #mesh-line :retained-across-b-c-reconnect";
    a.reset();
    b.reset();
    d.reset();
    sender.reset();
    try writeAllFd(fd_a, "PRIVMSG #mesh-line :retained-across-b-c-reconnect\r\n");
    try recvUntil(a, retained_needle, 200);
    try recvUntil(b, retained_needle, 200);
    try Helpers.settle(&.{ a, b });
    try Helpers.expectOnce(a, retained_needle);
    try Helpers.expectOnce(b, retained_needle);
    const retained_partition_line = Helpers.lineContaining(a, retained_needle) orelse return error.TestUnexpectedResult;
    const retained_partition_msgid = extractMsgid(retained_partition_line) orelse return error.TestUnexpectedResult;
    var retained_expected_msgid: [msgid_mod.id_len]u8 = undefined;
    @memcpy(&retained_expected_msgid, retained_partition_msgid);
    testSleepMs(150);
    try d.readAvailable();
    try sender.readAvailable();
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(d.written(), retained_needle));
    try std.testing.expectEqual(@as(usize, 0), countOccurrences(sender.written(), retained_needle));
    // Force the first authenticated receipt ACK for this retained event to be
    // lost at node 2. The same-origin barrier below cannot pass it until node 2
    // retransmits, node 3 deduplicates/re-ACKs, and RVL2 retires the head.
    const retained_relay_id = try node2.dropRelayV2AckForMsgidFromForTest(
        ident3.shortId(),
        &retained_expected_msgid,
    );

    // Restore the exact secured edge. The retained session mutation and event
    // must cross only after reconnection; the event keeps one msgid/server-time
    // identity on every live copy.
    admin.reset();
    try writeAllFd(admin_fd, connect_node3);
    try recvUntil(&admin, "CONNECT initiated (secured)", 200);
    try expectMeshPeersVisible(
        &admin,
        &.{ "session-line-node1.test", "session-line-node3.test" },
        160,
    );
    try recvUntil(&d, marker3, 600);
    try Helpers.expectOnce(&d, marker3);
    try recvUntil(&d, "JOIN :#mesh-retained", 600);
    try Helpers.expectOnce(&d, "JOIN :#mesh-retained");
    const retained_session_token = switch (try session_resume_credential.decode(local_token)) {
        .local => |value| value.group_token,
        .mesh => return error.TestUnexpectedResult,
    };
    var retained_store_projected = false;
    for (0..100) |_| {
        if (node3.sessionReplicaChannelFromOriginForTest(
            retained_session_token,
            ident2.shortId(),
            "#mesh-retained",
        )) {
            retained_store_projected = true;
            break;
        }
        testSleepMs(10);
    }
    try std.testing.expect(retained_store_projected);
    try recvUntil(&d, retained_needle, 400);
    try recvUntil(sender, retained_needle, 400);
    try Helpers.settle(&.{ a, b, &d, sender });
    try Helpers.expectOnce(a, retained_needle);
    try Helpers.expectOnce(b, retained_needle);
    try Helpers.expectOnce(&d, retained_needle);
    try Helpers.expectOnce(sender, retained_needle);
    const retained_a_line = Helpers.lineContaining(a, retained_needle) orelse return error.TestUnexpectedResult;
    const retained_b_line = Helpers.lineContaining(b, retained_needle) orelse return error.TestUnexpectedResult;
    const retained_d_line = Helpers.lineContaining(&d, retained_needle) orelse return error.TestUnexpectedResult;
    const retained_sender_line = Helpers.lineContaining(sender, retained_needle) orelse return error.TestUnexpectedResult;
    const retained_msgid = extractMsgid(retained_a_line) orelse return error.TestUnexpectedResult;
    const retained_time = extractTimeTag(retained_a_line) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(&retained_expected_msgid, retained_msgid);
    inline for (.{ retained_b_line, retained_d_line, retained_sender_line }) |event_line| {
        try std.testing.expectEqualStrings(retained_msgid, extractMsgid(event_line) orelse return error.TestUnexpectedResult);
        try std.testing.expectEqualStrings(retained_time, extractTimeTag(event_line) orelse return error.TestUnexpectedResult);
    }

    // Same-origin RVL2 head ordering makes this a deterministic ACK-progress
    // fence: it cannot reach the far edge until the dropped ACK above has been
    // recovered. Keep the first event in every buffer and prove its exact-wire
    // retry remained delivery-exactly-once.
    const barrier_needle = "PRIVMSG #mesh-line :ack-barrier-after-retained";
    try writeAllFd(fd_a, "PRIVMSG #mesh-line :ack-barrier-after-retained\r\n");
    try recvUntil(a, barrier_needle, 600);
    try recvUntil(b, barrier_needle, 600);
    try recvUntil(&d, barrier_needle, 600);
    try recvUntil(sender, barrier_needle, 600);
    try Helpers.settle(&.{ a, b, &d, sender });
    try std.testing.expect(!node2.relayV2AckDropArmedForTest());
    inline for (.{ a, b, &d, sender }) |client| {
        try Helpers.expectOnce(client, retained_needle);
        try Helpers.expectOnce(client, barrier_needle);
    }
    const barrier_a_line = Helpers.lineContaining(a, barrier_needle) orelse return error.TestUnexpectedResult;
    const barrier_msgid = extractMsgid(barrier_a_line) orelse return error.TestUnexpectedResult;
    const barrier_time = extractTimeTag(barrier_a_line) orelse return error.TestUnexpectedResult;
    try std.testing.expect(!std.mem.eql(u8, retained_msgid, barrier_msgid));
    inline for (.{ b, &d, sender }) |client| {
        const barrier_line = Helpers.lineContaining(client, barrier_needle) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(barrier_msgid, extractMsgid(barrier_line) orelse return error.TestUnexpectedResult);
        try std.testing.expectEqualStrings(barrier_time, extractTimeTag(barrier_line) orelse return error.TestUnexpectedResult);
    }

    // Delivery alone is insufficient: a broken ACK_CONFIRM path can leave the
    // exact event/outbox/receipt transaction pinned while later messages flow.
    // Poll the synchronized authorities until the retained id is retired across
    // all three nodes, then assert each topology-specific row is absent.
    var retired = false;
    var retire_attempt: usize = 0;
    while (retire_attempt < 200) : (retire_attempt += 1) {
        const n1 = node1.relayV2AuthorityStateForTest(ident2.shortId(), retained_relay_id);
        const n2_to_3 = node2.relayV2AuthorityStateForTest(ident3.shortId(), retained_relay_id);
        const n2_from_1 = node2.relayV2AuthorityStateForTest(ident1.shortId(), retained_relay_id);
        const n3 = node3.relayV2AuthorityStateForTest(ident2.shortId(), retained_relay_id);
        retired = !n1.event_retained and !n1.outbox_retained and
            !n2_to_3.event_retained and !n2_to_3.outbox_retained and
            !n2_from_1.receipt_retained and !n3.event_retained and
            !n3.receipt_retained;
        if (retired) break;
        testSleepMs(10);
    }
    try std.testing.expect(retired);

    // A new far-edge client can still resume with the original portable token
    // after the partition. It joins the same logical session, then authors one
    // event that every surviving attachment and the independent member sees once.
    const fd_e = try connectLoopback(port3);
    defer closeFd(fd_e);
    var e = LiveClient{ .fd = fd_e };
    try saslPlainPreludeWithCaps(fd_e, "nova", "pw", nova_caps);
    try writeAllFd(fd_e, "NICK DeviceE\r\nUSER nova 0 * :Post-reconnect line attachment E\r\n");
    try recvUntil(&e, " 001 DeviceE ", 200);
    try Helpers.attach(&e, resume_cmd);
    try expectContains(e.written(), "JOIN #mesh-line");
    try expectContains(e.written(), "JOIN #mesh-retained");
    try expectLiveSessionToken(&e, local_token, "mesh-session-line-secret", "nova");
    e.reset();
    try writeAllFd(fd_e, "MARKREAD #mesh-line\r\n");
    try recvUntil(&e, marker3, 200);
    try Helpers.expectOnce(&e, marker3);

    sender.reset();
    try writeAllFd(fd_sender, "JOIN #mesh-retained\r\n");
    try recvUntil(sender, " 366 RelaySender #mesh-retained ", 400);
    const retained_participation = "PRIVMSG #mesh-retained :resumed-member-participates";
    a.reset();
    b.reset();
    d.reset();
    e.reset();
    sender.reset();
    try writeAllFd(fd_e, "PRIVMSG #mesh-retained :resumed-member-participates\r\n");
    try recvUntil(a, retained_participation, 400);
    try recvUntil(b, retained_participation, 400);
    try recvUntil(&d, retained_participation, 400);
    try recvUntil(&e, retained_participation, 400);
    try recvUntil(sender, retained_participation, 400);
    try Helpers.settle(&.{ a, b, &d, &e, sender });
    const retained_participation_line = Helpers.lineContaining(&e, retained_participation) orelse
        return error.TestUnexpectedResult;
    const participation_msgid = extractMsgid(retained_participation_line) orelse return error.TestUnexpectedResult;
    const participation_time = extractTimeTag(retained_participation_line) orelse return error.TestUnexpectedResult;
    inline for (.{ a, b, &d, &e, sender }) |client| {
        try Helpers.expectOnce(client, retained_participation);
        const event_line = Helpers.lineContaining(client, retained_participation) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(participation_msgid, extractMsgid(event_line) orelse return error.TestUnexpectedResult);
        try std.testing.expectEqualStrings(participation_time, extractTimeTag(event_line) orelse return error.TestUnexpectedResult);
    }

    const resumed_needle = "PRIVMSG #mesh-line :far-edge-resume-after-reconnect";
    a.reset();
    b.reset();
    d.reset();
    e.reset();
    sender.reset();
    try writeAllFd(fd_e, "PRIVMSG #mesh-line :far-edge-resume-after-reconnect\r\n");
    try recvUntil(a, resumed_needle, 400);
    try recvUntil(b, resumed_needle, 400);
    try recvUntil(&d, resumed_needle, 400);
    try recvUntil(&e, resumed_needle, 400);
    try recvUntil(sender, resumed_needle, 400);
    try Helpers.settle(&.{ a, b, &d, &e, sender });
    const resumed_e_line = Helpers.lineContaining(&e, resumed_needle) orelse return error.TestUnexpectedResult;
    const resumed_msgid = extractMsgid(resumed_e_line) orelse return error.TestUnexpectedResult;
    const resumed_time = extractTimeTag(resumed_e_line) orelse return error.TestUnexpectedResult;
    inline for (.{ a, b, &d, &e, sender }) |client| {
        try Helpers.expectOnce(client, resumed_needle);
        const event_line = Helpers.lineContaining(client, resumed_needle) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(resumed_msgid, extractMsgid(event_line) orelse return error.TestUnexpectedResult);
        try std.testing.expectEqualStrings(resumed_time, extractTimeTag(event_line) orelse return error.TestUnexpectedResult);
    }
}

// FIX 1: the RECEIVING node re-enforces ITS OWN channel policy against a remote
// (mesh-relayed) actor. Two live nodes are meshed; node A's #c is set -n/-t so a
// local non-op/non-member can legitimately speak/set-topic there and relay to
// node B, where #c keeps the default +n/+t. The receiver gate on B must drop the
// relayed PRIVMSG (+n, non-member) and reject the relayed TOPIC (+t, non-op),
// while a legitimate member's message still flows. The default channel modes are
// per-node and only converge on the 30s anti-entropy cadence, so the asymmetry
// is stable for the test's lifetime when A sets -n/-t before B materializes #c.
test "threaded server: inbound relay re-enforces local +n / +t against a remote actor" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const alloc = std.testing.allocator;
        const s2s_ports = reserveTwoLoopbackPorts() catch return error.SkipZigTest;
        var spec1_buf: [32]u8 = undefined;
        var spec2_buf: [32]u8 = undefined;
        const node1_spec = try std.fmt.bufPrint(&spec1_buf, "127.0.0.1:{d}", .{s2s_ports[0]});
        const node2_spec = try std.fmt.bufPrint(&spec2_buf, "127.0.0.1:{d}", .{s2s_ports[1]});
        const node1_peers = [_][]const u8{node2_spec};
        const node2_peers = [_][]const u8{node1_spec};

        var node1 = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .s2s_port = s2s_ports[0],
            .node_id = 1,
            .server_name = "node1.test",
            .mesh_connect = &node1_peers,
            .num_shards = 1,
            .sweep_interval_ms = 100,
            .s2s_config = .{ .require_signed_frames = false },
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
            else => return err,
        };
        defer node1.deinit();
        var node2 = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .s2s_port = s2s_ports[1],
            .node_id = 2,
            .server_name = "node2.test",
            .mesh_connect = &node2_peers,
            .num_shards = 1,
            .sweep_interval_ms = 100,
            .s2s_config = .{ .require_signed_frames = false },
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
            else => return err,
        };
        defer node2.deinit();

        const port1 = node1.boundPort() catch return error.SkipZigTest;
        const port2 = node2.boundPort() catch return error.SkipZigTest;

        var run1 = std.atomic.Value(bool).init(true);
        var run2 = std.atomic.Value(bool).init(true);
        var thr1 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node1, &run1 });
        var thr2 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node2, &run2 });
        defer {
            node1.requestStop(&run1);
            node2.requestStop(&run2);
            thr1.join();
            thr2.join();
        }

        // BMem on node 2 founds #c (+n/+t default) and stays. AMember on node 1 joins
        // #c (becomes A's founder) and sets it -n -t BEFORE BMem exists on B is not
        // possible (BMem founds B's #c); instead we set A's modes and rely on the
        // per-node default split: B's #c is +n/+t, A's #c is -n/-t.
        const fd_b = connectLoopback(port2) catch return error.SkipZigTest;
        defer closeFd(fd_b);
        var bmem = LiveClient{ .fd = fd_b };
        try writeAllFd(fd_b, "NICK BMem\r\nUSER bmem 0 * :B Member\r\n");
        try recvUntil(&bmem, " 001 BMem ", 400);

        // A's founder establishes #c on node 1 and relaxes it to -n -t so node 1's
        // local gate permits a non-member/non-op to speak / set topic and relay.
        const fd_af = connectLoopback(port1) catch return error.SkipZigTest;
        defer closeFd(fd_af);
        var afounder = LiveClient{ .fd = fd_af };
        try writeAllFd(fd_af, "NICK AFounder\r\nUSER af 0 * :A Founder\r\n");
        try recvUntil(&afounder, " 001 AFounder ", 400);
        try writeAllFd(fd_af, "JOIN #c\r\n");
        try recvUntil(&afounder, " 366 AFounder #c ", 400);
        try writeAllFd(fd_af, "MODE #c -n\r\n");
        try writeAllFd(fd_af, "MODE #c -t\r\n");
        // Wait for the mesh to link both directions before BMem joins B's #c.
        try expectMeshPeerVisible(&afounder, "node2.test", 200);
        try expectMeshPeerVisible(&bmem, "node1.test", 200);

        // BMem joins #c on node 2 (founds B's copy with default +n/+t).
        bmem.reset();
        try writeAllFd(fd_b, "JOIN #c\r\n");
        try recvUntil(&bmem, " 366 BMem #c ", 400);

        // --- Positive control: AFounder (a real member, gossiped into B's roster)
        // PRIVMSGs #c; BMem must receive it (the gate allows legit members). ---
        bmem.reset();
        var member_ok = false;
        var probes: usize = 0;
        while (probes < 80 and !member_ok) : (probes += 1) {
            try writeAllFd(fd_af, "PRIVMSG #c :from member\r\n");
            recvUntil(&bmem, "PRIVMSG #c :from member", 120) catch {};
            if (std.mem.indexOf(u8, bmem.written(), "PRIVMSG #c :from member") != null) member_ok = true;
        }
        try std.testing.expect(member_ok);

        // --- Negative (+n): ANon, NOT a member of #c, speaks on node 1 (which is -n,
        // so node 1 permits it) and node 1 relays to node 2. Node 2's #c is +n and
        // ANon is not in B's roster, so the receiver gate must DROP it: BMem must NOT
        // receive ANon's line within a generous window. ---
        const fd_an = connectLoopback(port1) catch return error.SkipZigTest;
        defer closeFd(fd_an);
        var anon = LiveClient{ .fd = fd_an };
        try writeAllFd(fd_an, "NICK ANon\r\nUSER anon 0 * :A NonMember\r\n");
        try recvUntil(&anon, " 001 ANon ", 400);
        bmem.reset();
        // Fire several times to be sure the relay had every chance to arrive.
        var n: usize = 0;
        while (n < 10) : (n += 1) {
            try writeAllFd(fd_an, "PRIVMSG #c :external blocked\r\n");
            testSleepMs(20);
        }
        testSleepMs(150);
        try bmem.readAvailable();
        try std.testing.expect(std.mem.indexOf(u8, bmem.written(), "external blocked") == null);

        // --- Negative (+t): ANonOp, a non-op member of #c on node 1 (-t there), sets
        // the topic; node 1 relays it to node 2 where #c is +t. Node 2 must REJECT it
        // (topic unchanged / not echoed). We assert BMem does not see ANonOp's topic.
        // First make ANon a member of #c on node 1 (it is -t, so a non-op can TOPIC).
        try writeAllFd(fd_an, "JOIN #c\r\n");
        try recvUntil(&anon, " 366 ANon #c ", 400);
        bmem.reset();
        n = 0;
        while (n < 10) : (n += 1) {
            try writeAllFd(fd_an, "TOPIC #c :hijacked topic\r\n");
            testSleepMs(20);
        }
        testSleepMs(150);
        try bmem.readAvailable();
        try std.testing.expect(std.mem.indexOf(u8, bmem.written(), "hijacked topic") == null);

        // --- Positive control (+t): AFounder (op on node 1) sets the topic; node 2
        // must APPLY+echo it to BMem (the +t gate allows ops). ---
        bmem.reset();
        var topic_ok = false;
        probes = 0;
        while (probes < 80 and !topic_ok) : (probes += 1) {
            try writeAllFd(fd_af, "TOPIC #c :legit topic\r\n");
            recvUntil(&bmem, "TOPIC #c :legit topic", 120) catch {};
            if (std.mem.indexOf(u8, bmem.written(), "TOPIC #c :legit topic") != null) topic_ok = true;
        }
        try std.testing.expect(topic_ok);
    } else return error.SkipZigTest;
}

test "threaded server: WHISPER and DATA relay to a remote-shard channel co-member" {
    if (comptime builtin.os.tag == .linux or builtin.os.tag == .openbsd) {
        const alloc = std.testing.allocator;
        const s2s_ports = reserveTwoLoopbackPorts() catch return error.SkipZigTest;
        var spec1_buf: [32]u8 = undefined;
        var spec2_buf: [32]u8 = undefined;
        const node1_spec = try std.fmt.bufPrint(&spec1_buf, "127.0.0.1:{d}", .{s2s_ports[0]});
        const node2_spec = try std.fmt.bufPrint(&spec2_buf, "127.0.0.1:{d}", .{s2s_ports[1]});
        const node1_peers = [_][]const u8{node2_spec};
        const node2_peers = [_][]const u8{node1_spec};

        var node1 = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .s2s_port = s2s_ports[0],
            .node_id = 1,
            .server_name = "node1.test",
            .mesh_connect = &node1_peers,
            .num_shards = 1,
            .sweep_interval_ms = 100,
            .s2s_config = .{ .require_signed_frames = false },
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
            else => return err,
        };
        defer node1.deinit();
        var node2 = Server.init(alloc, .{
            .host = "127.0.0.1",
            .port = 0,
            .s2s_port = s2s_ports[1],
            .node_id = 2,
            .server_name = "node2.test",
            .mesh_connect = &node2_peers,
            .num_shards = 1,
            .sweep_interval_ms = 100,
            .s2s_config = .{ .require_signed_frames = false },
        }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
            else => return err,
        };
        defer node2.deinit();

        const port1 = node1.boundPort() catch return error.SkipZigTest;
        const port2 = node2.boundPort() catch return error.SkipZigTest;

        var run1 = std.atomic.Value(bool).init(true);
        var run2 = std.atomic.Value(bool).init(true);
        var thr1 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node1, &run1 });
        var thr2 = try std.Thread.spawn(.{}, Server.runThreaded, .{ &node2, &run2 });
        defer {
            node1.requestStop(&run1);
            node2.requestStop(&run2);
            thr1.join();
            thr2.join();
        }

        // Alice on node 1 (IRCX-enabled, so she may WHISPER/DATA) joins #x.
        const fd_a = connectLoopback(port1) catch return error.SkipZigTest;
        defer closeFd(fd_a);
        var alice = LiveClient{ .fd = fd_a };
        try writeAllFd(fd_a, "NICK Alice\r\nUSER al 0 * :Alice\r\n");
        try recvUntil(&alice, " 001 Alice ", 400);
        try writeAllFd(fd_a, "IRCX\r\n");
        try recvUntil(&alice, " 800 Alice 1 0 ", 400);
        try writeAllFd(fd_a, "JOIN #x\r\n");
        try recvUntil(&alice, " 366 Alice #x ", 400);

        // Bob on node 2 joins #x; the mesh must converge both rosters before we send.
        const fd_b = connectLoopback(port2) catch return error.SkipZigTest;
        defer closeFd(fd_b);
        var bob = LiveClient{ .fd = fd_b };
        try writeAllFd(fd_b, "NICK Bob\r\nUSER bo 0 * :Bob\r\n");
        try recvUntil(&bob, " 001 Bob ", 400);
        try writeAllFd(fd_b, "JOIN #x\r\n");
        try recvUntil(&bob, " 366 Bob #x ", 400);

        try expectMeshPeerVisible(&alice, "node2.test", 200);
        try expectMeshPeerVisible(&bob, "node1.test", 200);

        // Wait until node 1 sees Bob's remote membership of #x land in the roster
        // (a remote JOIN is surfaced to local members of #x).
        var saw_bob = false;
        var jp: usize = 0;
        while (jp < 80 and !saw_bob) : (jp += 1) {
            alice.readAvailable() catch {};
            if (std.mem.indexOf(u8, alice.written(), "Bob") != null and
                std.mem.indexOf(u8, alice.written(), "JOIN") != null) saw_bob = true;
            if (!saw_bob) testSleepMs(25);
        }

        // --- Cross-shard WHISPER: Alice (node 1) whispers Bob (node 2) on #x. The
        // old bug returned ERR_NOSUCHNICK because Bob is not a LOCAL nick; the relay
        // must now reach Bob. Fire several times to defeat any residual convergence
        // lag, then assert Bob received the WHISPER and Alice got NO 401. ---
        bob.reset();
        alice.reset();
        var whisper_ok = false;
        var wp: usize = 0;
        while (wp < 80 and !whisper_ok) : (wp += 1) {
            try writeAllFd(fd_a, "WHISPER #x Bob :psst over the mesh\r\n");
            recvUntil(&bob, "WHISPER #x Bob :psst over the mesh", 120) catch {};
            if (std.mem.indexOf(u8, bob.written(), "WHISPER #x Bob :psst over the mesh") != null) whisper_ok = true;
        }
        try std.testing.expect(whisper_ok);
        try alice.readAvailable();
        // No ERR_NOSUCHNICK (401) for the relayed WHISPER.
        try std.testing.expect(std.mem.indexOf(u8, alice.written(), " 401 ") == null);

        // --- Negative: WHISPER to a nick that is NOT a member of #x anywhere must
        // still yield 401 (the relay fails closed, never floods peers). ---
        alice.reset();
        var got_401 = false;
        var np: usize = 0;
        while (np < 40 and !got_401) : (np += 1) {
            try writeAllFd(fd_a, "WHISPER #x Ghost :anyone there\r\n");
            recvUntil(&alice, " 401 ", 120) catch {};
            if (std.mem.indexOf(u8, alice.written(), " 401 ") != null) got_401 = true;
        }
        try std.testing.expect(got_401);

        // --- Cross-shard DATA: Alice sends a channel-targeted DATA to #x; Bob (the
        // remote co-member) must receive the typed line. ---
        bob.reset();
        var data_ok = false;
        var dp: usize = 0;
        while (dp < 80 and !data_ok) : (dp += 1) {
            try writeAllFd(fd_a, "DATA #x Mood :comic-frame-payload\r\n");
            recvUntil(&bob, "DATA #x Mood :comic-frame-payload", 120) catch {};
            if (std.mem.indexOf(u8, bob.written(), "DATA #x Mood :comic-frame-payload") != null) data_ok = true;
        }
        try std.testing.expect(data_ok);
    } else return error.SkipZigTest;
}

test "wsCarryable: any open adapter carries, incl. mid-frame; handshake/pending never" {
    const alloc = std.testing.allocator;
    const ws = try alloc.create(WsState); // heap: WsState holds MiB-sized buffers
    defer alloc.destroy(ws);

    // A fresh adapter is still in the HTTP Upgrade handshake — never carried.
    ws.* = .{};
    try std.testing.expect(!wsCarryable(ws));

    // Open, with nothing buffered in either direction: carried.
    ws.* = .{ .phase = .open };
    try std.testing.expect(wsCarryable(ws));

    // A partial inbound frame mid-arrival is carried now — its wire bytes are
    // serialized into the v2 capsule and restored verbatim by the successor
    // (the v1 clean-boundary gate dropped exactly this, i.e. every busy client).
    ws.* = .{ .phase = .open };
    ws.deframer.len = 3;
    try std.testing.expect(wsCarryable(ws));

    // A partial outbound line in the tx accumulator is carried too.
    ws.* = .{ .phase = .open };
    ws.tx_len = 5;
    try std.testing.expect(wsCarryable(ws));

    // An open fragmented message carries with its fragmentation flags.
    ws.* = .{ .phase = .open };
    ws.deframer.fragmented = true;
    try std.testing.expect(wsCarryable(ws));

    // Binary fragmentation carries only when the decoded application-message
    // accumulator and Deframer flags describe the same in-flight message.
    ws.* = .{ .phase = .open };
    ws.deframer.fragmented = true;
    ws.deframer.msg_binary = true;
    ws.binary_message_active = true;
    ws.binary_message_len = 3;
    @memcpy(ws.binary_message_buf[0..3], "abc");
    try std.testing.expect(wsCarryable(ws));
    ws.binary_message_active = false;
    try std.testing.expect(!wsCarryable(ws));

    // A popped-but-unconsumed deframed event cannot exist between reactor turns;
    // a mid-turn seal that sees one still refuses to carry (fail-safe).
    ws.* = .{ .phase = .open };
    ws.deframer.pending = .pong;
    try std.testing.expect(!wsCarryable(ws));

    // Same for a latent deframe error awaiting its next() surface.
    ws.* = .{ .phase = .open };
    ws.deframer.pending_error = error.BufferFull;
    try std.testing.expect(!wsCarryable(ws));
}

const UpgradeFixtureAuthority = enum {
    mesh_clock,
    property,
    replica_store,
    pending,
    e2ee_group,
};

fn replaceUpgradeFixtureAuthority(
    pieces: *std.ArrayList(helix_live.StatePiece),
    authority: UpgradeFixtureAuthority,
    replacement: helix_live.StatePiece,
) bool {
    for (pieces.items) |*piece| {
        const matches = switch (authority) {
            .mesh_clock => piece.kind == .mesh_checkpoint and
                std.mem.startsWith(u8, piece.bytes, &mesh_clock_snapshot.magic),
            .property => piece.kind == .mesh_checkpoint and prop_checkpoint.isUpgradeCheckpoint(piece.bytes),
            .replica_store => piece.kind == .mesh_checkpoint and session_replica_v2.Store.isUpgradeCheckpoint(piece.bytes),
            .pending => piece.kind == .pending_migration,
            .e2ee_group => piece.kind == .mesh_checkpoint and
                e2ee_group_mesh_authority.isCheckpoint(piece.bytes),
        };
        if (!matches) continue;
        piece.* = replacement;
        return true;
    }
    return false;
}

fn appendEmptyUpgradeClientSidecarsForTest(
    allocator: std.mem.Allocator,
    pieces: *std.ArrayList(helix_live.StatePiece),
    blobs: *std.ArrayList([]u8),
    fd: linux.fd_t,
) !void {
    const monitor_buf = try allocator.alloc(u8, 4 + 1 + 8 + 2);
    errdefer allocator.free(monitor_buf);
    const monitor_wire = try (monitor_capsule.MonitorCapsule{
        .client_id = @intCast(fd),
        .targets = &.{},
    }).encode(monitor_buf);
    try blobs.append(allocator, monitor_buf);
    try pieces.append(allocator, .{ .kind = .monitor_list, .bytes = monitor_wire });

    const silence_buf = try allocator.alloc(u8, 4 + 1 + 8 + 2);
    errdefer allocator.free(silence_buf);
    const silence_wire = try (silence_capsule.SilenceCapsule{
        .client_id = @intCast(fd),
        .masks = &.{},
    }).encode(silence_buf);
    try blobs.append(allocator, silence_buf);
    try pieces.append(allocator, .{ .kind = .silence_list, .bytes = silence_wire });
}

test "threaded server: UPGRADE resume arena re-attaches a live TLS client" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const Ed25519 = std.crypto.sign.Ed25519;
    const tls_client = @import("../crypto/tls_client.zig");
    const x509_selfsign = @import("../proto/x509_selfsign.zig");
    const alloc = std.testing.allocator;
    // adoptInheritedSessions binds this thread's reactor; unbind on exit so
    // later direct-runOnce tests never see a stale pointer.
    defer current_reactor = null;

    const kp = try Ed25519.KeyPair.generateDeterministic(@as([Ed25519.KeyPair.seed_length]u8, @splat(0x61)));
    var cert_buf: [1024]u8 = undefined;
    const der = try x509_selfsign.buildSelfSigned(&cert_buf, .{
        .common_name = "irc.test",
        .not_before = 1_704_067_200,
        .not_after = 4_102_444_800,
        .serial = &.{ 0x61, 0x01 },
        .key_pair = kp,
        .dns_names = &.{"irc.test"},
        .is_ca = true,
    });
    const chain = [_][]const u8{der};

    // The "predecessor" leg: a real TLS 1.3 handshake driven purely in memory,
    // exactly the state a live pre-upgrade connection would hold.
    var pre_conn = try tls_conn.TlsConn.init(alloc, .{ .cert_chain = &chain, .signing_key = kp });
    defer pre_conn.deinit();
    var client = try tls_client.Client.init(alloc, .{ .server_name = "irc.test", .trust_anchors = &chain });
    defer client.deinit();
    const ch = try client.start();
    defer alloc.free(ch);
    const sh = try pre_conn.onInbound(ch);
    const cfin = switch (try client.feed(sh.handshake_bytes)) {
        .bytes_to_send => |b| b,
        .need_more => return error.TestUnexpectedResult,
    };
    defer alloc.free(cfin);
    _ = try pre_conn.onInbound(cfin);
    try std.testing.expect(pre_conn.handshakeDone());
    // Advance both directions so the carried seqs are non-zero.
    const warm = try client.encrypt("warmup");
    defer alloc.free(warm);
    const warm_out = try pre_conn.onInbound(warm);
    try std.testing.expectEqualStrings("warmup", warm_out.plaintext);
    const warm_reply = try pre_conn.write("warm-ack");
    const warm_plain = try client.decrypt(warm_reply);
    defer alloc.free(warm_plain);
    // A record the predecessor encrypted but never flushed — carried as
    // pending_out so the client's record sequence stays unbroken.
    const pend = try pre_conn.write(":upgrade.test NOTICE TLSY :carried-across\r\n");
    const pend_copy = try alloc.dupe(u8, pend);
    defer alloc.free(pend_copy);
    const rs = try pre_conn.exportResume();

    // The carried socket: one end is "the client connection", the other stays
    // with the test as the remote peer.
    var sp: [2]i32 = undefined;
    const sp_rc = linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sp);
    if (linux.errno(sp_rc) != .SUCCESS) return error.SkipZigTest;
    defer closeFd(sp[1]); // sp[0] ownership transfers to the server on adopt

    // Seal the arena exactly like handleUpgrade does (TLS piece + session piece).
    const tls_blob = try tls_snapshot.encode(alloc, .{
        .kernel_tx_prefix_remaining = 0,
        .fd = sp[0],
        .state = rs,
        .pending_out = pend_copy,
    });
    defer alloc.free(tls_blob);
    const sess_blob = try session_snapshot.encode(alloc, .{ .nick = "TLSY", .realname = "Carried", .fd = sp[0], .was_secured = true });
    defer alloc.free(sess_blob);
    const fixture = try alloc.create(Server);
    defer alloc.destroy(fixture);
    fixture.initInPlace(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer fixture.deinit();
    var fixture_blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (fixture_blobs.items) |blob| alloc.free(blob);
        fixture_blobs.deinit(alloc);
    }
    var arena_pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer arena_pieces.deinit(alloc);
    try appendCurrentMandatoryUpgradeStateForTest(fixture, &arena_pieces, &fixture_blobs);
    try arena_pieces.append(alloc, .{ .kind = .tls_session, .bytes = tls_blob });
    try arena_pieces.append(alloc, .{ .kind = .clients, .bytes = sess_blob });
    try appendEmptyUpgradeClientSidecarsForTest(alloc, &arena_pieces, &fixture_blobs, sp[0]);
    var prepared = try helix_live.prepare(alloc, .{
        .epoch = 1,
        .now_ms = 1,
        .timeout_ms = 1000,
        .arena_name = "onyx-test-tls-adopt",
        .pieces = arena_pieces.items,
        .fds = &.{sp[0]},
    });
    defer prepared.deinit();
    const dup_rc = linux.dup(prepared.runtime.arena.?.fd);
    if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
    const arena_dup: linux.fd_t = @intCast(dup_rc);

    // The "successor": a fresh server adopting the arena before its loop runs.
    var server = Server.init(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_port = 0,
        .tls_cert_chain = &chain,
        .tls_signing_key = kp,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    server.config.resume_arena_fd = arena_dup;
    var state_fds = [_]linux.fd_t{sp[0]};
    server.config.inherited_state_fds = &state_fds;
    server.config.inherited_state_fd_manifest_present = true;
    server.config.inherited_state_fd_manifest_valid = true;
    try server.adoptInheritedSessions();
    var adopted_metrics: std.ArrayList(u8) = .empty;
    defer adopted_metrics.deinit(alloc);
    try server.stats.writePrometheus(alloc, &adopted_metrics);
    try std.testing.expect(std.mem.indexOf(u8, adopted_metrics.items, "onyx_connections_active 1\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, adopted_metrics.items, "onyx_connections_total 1\n") != null);
    // adopt binds this thread to the server's reactor; unbind so later
    // main-thread calls (and the teardown defers) resolve per-instance.
    current_reactor = null;
    const plain_port = try server.boundPort();

    var run = std.atomic.Value(bool).init(true);
    var thr = try std.Thread.spawn(.{}, Server.runThreaded, .{ &server, &run });
    defer {
        run.store(false, .release);
        if (connectLoopback(plain_port)) |wfd| closeFd(wfd) else |_| {}
        thr.join();
    }

    // The client end keeps speaking TLS across the swap: first the carried
    // pending record arrives, then a PING round-trips through the resumed
    // engine (read seq, write seq, and keys all survived).
    const ping = try client.encrypt("PING :across-upgrade\r\n");
    defer alloc.free(ping);
    try writeAllFd(sp[1], ping);

    var cipher: std.ArrayList(u8) = .empty;
    defer cipher.deinit(alloc);
    var plain: std.ArrayList(u8) = .empty;
    defer plain.deinit(alloc);
    var rbuf: [4096]u8 = undefined;
    var guard: usize = 0;
    while (std.mem.indexOf(u8, plain.items, "PONG onyx.local :across-upgrade") == null) : (guard += 1) {
        if (guard > 64) return error.TestUnexpectedResult;
        const n = try readFd(sp[1], &rbuf);
        if (n == 0) return error.TestUnexpectedResult;
        try cipher.appendSlice(alloc, rbuf[0..n]);
        // Drain every complete TLS record (5-byte header + big-endian length).
        while (cipher.items.len >= 5) {
            const body_len = std.mem.readInt(u16, cipher.items[3..5], .big);
            const wire_len = 5 + @as(usize, body_len);
            if (cipher.items.len < wire_len) break;
            const pt = try client.decrypt(cipher.items[0..wire_len]);
            defer alloc.free(pt);
            try plain.appendSlice(alloc, pt);
            std.mem.copyForwards(u8, cipher.items[0 .. cipher.items.len - wire_len], cipher.items[wire_len..]);
            cipher.shrinkRetainingCapacity(cipher.items.len - wire_len);
        }
    }
    // The predecessor's unflushed record arrived FIRST (no sequence hole) ...
    try expectContains(plain.items, ":upgrade.test NOTICE TLSY :carried-across");
    // ... and fresh traffic flows both ways on the resumed engine.
    try expectContains(plain.items, "PONG onyx.local :across-upgrade");
    const before = std.mem.indexOf(u8, plain.items, "carried-across").?;
    const after = std.mem.indexOf(u8, plain.items, "PONG onyx.local :across-upgrade").?;
    try std.testing.expect(before < after);
}

test "UPGRADE resume arena restores the mesh event clock high-water mark" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    const predecessor_stamp = (@as(u64, 1_900_000_000_000) << mesh_clock_mod.seq_bits) | 65_500;
    const predecessor = mesh_clock_mod.MeshClock{
        .last_physical = mesh_clock_mod.MeshClock.physicalOf(predecessor_stamp),
        .last_stamp = predecessor_stamp,
    };
    var fixture = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer fixture.deinit();
    fixture.mesh_clock = predecessor;
    const predecessor_migration_epoch: u64 = 1_900_000_000_000_123_456;
    fixture.migration_offer_epoch = predecessor_migration_epoch;
    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |blob| alloc.free(blob);
        blobs.deinit(alloc);
    }
    var arena_pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer arena_pieces.deinit(alloc);
    try appendCurrentMandatoryUpgradeStateForTest(&fixture, &arena_pieces, &blobs);
    var prepared = try helix_live.prepare(alloc, .{
        .epoch = 1,
        .now_ms = 1,
        .timeout_ms = 1000,
        .arena_name = "onyx-test-mesh-clock-adopt",
        .pieces = arena_pieces.items,
        .fds = &.{},
    });
    defer prepared.deinit();
    const dup_rc = linux.dup(prepared.runtime.arena.?.fd);
    if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
    const arena_dup: linux.fd_t = @intCast(dup_rc);

    var server = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    server.config.resume_arena_fd = arena_dup;
    try server.adoptInheritedSessions();
    current_reactor = null;

    try std.testing.expectEqual(predecessor_stamp, server.mesh_clock.last_stamp);
    try std.testing.expectEqual(predecessor_migration_epoch, server.migration_offer_epoch);
    // The successor's process-local sequence counter starts fresh, and the
    // synthetic predecessor wall time is deliberately ahead of the test host.
    // Only the restored high-water mark can make this next stamp advance.
    try std.testing.expect(server.nextMeshHlc() > predecessor_stamp);
}

test "UPGRADE property clock boundary prepares successor HLC without mutating predecessor" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var server = Server.init(std.testing.allocator, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    _ = server.nextMeshHlc();
    const predecessor = server.mesh_clock;
    const empty_candidate = server.preparePropertyUpgradeClockBoundary() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(predecessor.last_physical, empty_candidate.last_physical);
    try std.testing.expectEqual(predecessor.last_stamp, empty_candidate.last_stamp);
    try std.testing.expectEqual(predecessor.last_physical, server.mesh_clock.last_physical);
    try std.testing.expectEqual(predecessor.last_stamp, server.mesh_clock.last_stamp);

    const retained = ((server.meshWallMs() + 60_000) << mesh_clock_mod.seq_bits) | 77;
    try std.testing.expect(server.recordChannelPropClock("#upgrade", "CLOCK", "remote", retained, false, 7, "", ""));
    const candidate = server.preparePropertyUpgradeClockBoundary() orelse
        return error.TestUnexpectedResult;
    try std.testing.expectEqual(retained, candidate.last_stamp);
    try std.testing.expectEqual(mesh_clock_mod.MeshClock.physicalOf(retained), candidate.last_physical);
    try std.testing.expectEqual(predecessor.last_physical, server.mesh_clock.last_physical);
    try std.testing.expectEqual(predecessor.last_stamp, server.mesh_clock.last_stamp);
    const candidate_wire = try mesh_clock_snapshot.encode(candidate, 0, .{});
    var successor_clock = (try mesh_clock_snapshot.decode(&candidate_wire)).clock;
    try std.testing.expect(successor_clock.stamp(server.meshWallMs(), 1) > retained);

    const clock = server.channelPropClock("#upgrade", "CLOCK") orelse
        return error.TestUnexpectedResult;
    clock.hlc = std.math.maxInt(u64);
    try std.testing.expect(server.preparePropertyUpgradeClockBoundary() == null);
    try std.testing.expectEqual(predecessor.last_physical, server.mesh_clock.last_physical);
    try std.testing.expectEqual(predecessor.last_stamp, server.mesh_clock.last_stamp);

    clock.hlc = ((server.meshWallMs() + mesh_clock_mod.default_max_future_skew_ms + 60_000) << mesh_clock_mod.seq_bits) | 1;
    try std.testing.expect(server.preparePropertyUpgradeClockBoundary() == null);
    try std.testing.expectEqual(predecessor.last_physical, server.mesh_clock.last_physical);
    try std.testing.expectEqual(predecessor.last_stamp, server.mesh_clock.last_stamp);
}

test "UPGRADE resume atomically restores exact property rows clocks and tombstones" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var predecessor = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer predecessor.deinit();
    const channel = try ircx_prop_store.Entity.fromId("#CaseRoom");
    const user = try ircx_prop_store.Entity.fromId("CaseUser");
    const member = try ircx_prop_store.Entity.fromId("#CaseRoom:Alice");
    _ = try predecessor.props.setProp(channel, "TOPIC", "exact topic", .{ .id = "host", .access = .host });
    _ = try predecessor.props.setProp(channel, "HOSTKEY", "exact secret", .{ .id = "owner", .access = .owner });
    _ = try predecessor.props.setProp(channel, "STALE", "row survives tombstone divergence", .{ .id = "host", .access = .host });
    _ = try predecessor.props.setProp(user, "BIO", "user row", .{ .id = "CaseUser", .access = .user });
    _ = try predecessor.props.setProp(member, "ROLE", "operator", .{ .id = "Alice", .access = .member });

    const pubkey: [channel_prop_event.pubkey_len]u8 = @splat(0x31);
    const signature: [channel_prop_event.sig_len]u8 = @splat(0x52);
    const high_hlc = ((predecessor.meshWallMs() + 60_000) << mesh_clock_mod.seq_bits) | 104;
    try std.testing.expect(predecessor.recordChannelPropClock("#CaseRoom", "TOPIC", "host", 100, true, 7, "", ""));
    // Clock-only PRESENT and row-plus-TOMBSTONE deliberately disagree with the
    // raw store. Migration must preserve both images, never reconcile them.
    try std.testing.expect(predecessor.recordChannelPropClock("#CaseRoom", "CLOCKONLY", "remote", 101, true, 8, &pubkey, &signature));
    try std.testing.expect(predecessor.recordChannelPropClock("#CaseRoom", "STALE", "remote", 102, false, 8, &pubkey, &signature));
    try std.testing.expect(predecessor.recordEntityPropClock(.user, "CaseUser", "BIO", "CaseUser", 103, true, 7, "", ""));
    try std.testing.expect(predecessor.recordEntityPropClock(.member, "#CaseRoom:Ghost", "ROLE", "Ghost", high_hlc, false, 8, &pubkey, &signature));

    const checkpoint = try prop_checkpoint.encode(
        alloc,
        &predecessor.props,
        &predecessor.channel_prop_clocks,
        &predecessor.entity_prop_clocks,
    );
    defer alloc.free(checkpoint);
    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |blob| alloc.free(blob);
        blobs.deinit(alloc);
    }
    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(alloc);
    try appendCurrentMandatoryUpgradeStateForTest(&predecessor, &pieces, &blobs);
    try std.testing.expect(replaceUpgradeFixtureAuthority(&pieces, .property, .{
        .kind = .mesh_checkpoint,
        .bytes = checkpoint,
        .min_supported = 2,
    }));
    var prepared = try helix_live.prepare(alloc, .{
        .epoch = 1,
        .now_ms = 1,
        .timeout_ms = 1000,
        .arena_name = "onyx-test-property-state-adopt",
        .pieces = pieces.items,
        .fds = &.{},
    });
    defer prepared.deinit();
    const dup_rc = linux.dup(prepared.runtime.arena.?.fd);
    if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
    const arena_dup: linux.fd_t = @intCast(dup_rc);

    var successor = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer successor.deinit();
    const sentinel = try ircx_prop_store.Entity.fromId("Sentinel");
    _ = try successor.props.setProp(sentinel, "CUSTOM", "old triplet", .{ .id = "Sentinel", .access = .user });
    try std.testing.expect(successor.recordChannelPropClock("#Sentinel", "OLD", "old", 1, false, 1, "", ""));
    try std.testing.expect(successor.recordEntityPropClock(.user, "Sentinel", "OLD", "old", 1, false, 1, "", ""));
    successor.config.resume_arena_fd = arena_dup;
    try successor.adoptInheritedSessions();
    current_reactor = null;

    try std.testing.expect(successor.config.resume_arena_fd == null);
    try std.testing.expectError(error.PropMissing, successor.props.getPropRaw(sentinel, "CUSTOM"));
    try std.testing.expectEqual(@as(usize, 3), successor.props.entity_count);
    try std.testing.expectEqual(@as(usize, 3), successor.channel_prop_clocks.count());
    try std.testing.expectEqual(@as(usize, 2), successor.entity_prop_clocks.count());
    try std.testing.expectEqualStrings("exact topic", (try successor.props.getPropRaw(channel, "TOPIC")).value);
    try std.testing.expectEqualStrings("exact secret", (try successor.props.getPropRaw(channel, "HOSTKEY")).value);
    try std.testing.expectEqualStrings("row survives tombstone divergence", (try successor.props.getPropRaw(channel, "STALE")).value);
    try std.testing.expectEqualStrings("user row", (try successor.props.getPropRaw(user, "BIO")).value);
    try std.testing.expectEqualStrings("operator", (try successor.props.getPropRaw(member, "ROLE")).value);
    try std.testing.expect(successor.channelPropClock("#Sentinel", "OLD") == null);
    try std.testing.expect(successor.entityPropClock(.user, "Sentinel", "OLD") == null);
    try std.testing.expect(successor.channelPropClock("#CaseRoom", "HOSTKEY") == null);
    try std.testing.expect(successor.entityPropClock(.member, "#CaseRoom:Alice", "ROLE") == null);
    const clock_only = successor.channelPropClock("#caseroom", "clockonly") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("#CaseRoom", clock_only.channel);
    try std.testing.expectEqualStrings("CLOCKONLY", clock_only.key);
    try std.testing.expectEqualStrings("remote", clock_only.owner);
    try std.testing.expect(clock_only.present);
    try std.testing.expectEqual(@as(u64, 101), clock_only.hlc);
    try std.testing.expectEqual(@as(u64, 8), clock_only.origin_node);
    try std.testing.expectEqualSlices(u8, &pubkey, clock_only.origin_pubkey);
    try std.testing.expectEqualSlices(u8, &signature, clock_only.origin_sig);
    try std.testing.expectError(error.PropMissing, successor.props.getPropRaw(channel, "CLOCKONLY"));
    const stale = successor.channelPropClock("#CaseRoom", "STALE") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("#CaseRoom", stale.channel);
    try std.testing.expectEqualStrings("STALE", stale.key);
    try std.testing.expectEqualStrings("remote", stale.owner);
    try std.testing.expect(!stale.present);
    try std.testing.expectEqual(@as(u64, 102), stale.hlc);
    const member_tombstone = successor.entityPropClock(.member, "#caseroom:ghost", "role") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(entity_prop_event.EntityKind.member, member_tombstone.kind);
    try std.testing.expectEqualStrings("#CaseRoom:Ghost", member_tombstone.entity);
    try std.testing.expectEqualStrings("ROLE", member_tombstone.key);
    try std.testing.expectEqualStrings("Ghost", member_tombstone.owner);
    try std.testing.expect(!member_tombstone.present);
    try std.testing.expectEqual(high_hlc, member_tombstone.hlc);
    try std.testing.expectEqual(@as(u64, 8), member_tombstone.origin_node);
    try std.testing.expectEqualSlices(u8, &pubkey, member_tombstone.origin_pubkey);
    try std.testing.expectEqualSlices(u8, &signature, member_tombstone.origin_sig);
    // The restored max is causally observed before publication, so a fresh
    // process-local sequence still mints a strictly newer event immediately.
    try std.testing.expectEqual(high_hlc, successor.mesh_clock.last_stamp);
    try std.testing.expect(successor.nextMeshHlc() > high_hlc);
}

test "UPGRADE property checkpoint selection fails closed without tearing the live triplet" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var empty_props = ircx_prop_store.DefaultStore.init(alloc);
    defer empty_props.deinit();
    var empty_channel_clocks: prop_checkpoint.ChannelClockMap = .empty;
    defer empty_channel_clocks.deinit(alloc);
    var empty_entity_clocks: prop_checkpoint.EntityClockMap = .empty;
    defer empty_entity_clocks.deinit(alloc);
    const valid = try prop_checkpoint.encode(alloc, &empty_props, &empty_channel_clocks, &empty_entity_clocks);
    defer alloc.free(valid);
    const corrupt = try alloc.dupe(u8, valid);
    defer alloc.free(corrupt);
    corrupt[corrupt.len - 1] ^= 1;

    const Scenario = enum { corrupt_required, duplicate_required, downgraded_wrapper, unknown_required };
    for ([_]Scenario{ .corrupt_required, .duplicate_required, .downgraded_wrapper, .unknown_required }) |scenario| {
        var piece_buf: [2]helix_live.StatePiece = undefined;
        const malformed_pieces: []const helix_live.StatePiece = switch (scenario) {
            .corrupt_required => blk: {
                piece_buf[0] = .{ .kind = .mesh_checkpoint, .bytes = corrupt, .min_supported = 2 };
                break :blk piece_buf[0..1];
            },
            .duplicate_required => blk: {
                piece_buf[0] = .{ .kind = .mesh_checkpoint, .bytes = valid, .min_supported = 2 };
                piece_buf[1] = .{ .kind = .mesh_checkpoint, .bytes = valid, .min_supported = 2 };
                break :blk piece_buf[0..2];
            },
            .downgraded_wrapper => blk: {
                piece_buf[0] = .{ .kind = .mesh_checkpoint, .bytes = valid };
                break :blk piece_buf[0..1];
            },
            .unknown_required => blk: {
                piece_buf[0] = .{ .kind = .mesh_checkpoint, .bytes = "UNKNOWN-REQUIRED", .min_supported = 2 };
                break :blk piece_buf[0..1];
            },
        };
        const fixture = try alloc.create(Server);
        fixture.initInPlace(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| {
            alloc.destroy(fixture);
            return switch (err) {
                error.Unsupported, error.PermissionDenied, error.SocketUnavailable => error.SkipZigTest,
                else => err,
            };
        };
        defer {
            fixture.deinit();
            alloc.destroy(fixture);
        }
        var blobs: std.ArrayList([]u8) = .empty;
        defer {
            for (blobs.items) |blob| alloc.free(blob);
            blobs.deinit(alloc);
        }
        var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
        defer pieces.deinit(alloc);
        try appendCurrentMandatoryUpgradeStateForTest(fixture, &pieces, &blobs);
        try std.testing.expect(replaceUpgradeFixtureAuthority(&pieces, .property, malformed_pieces[0]));
        if (malformed_pieces.len == 2) try pieces.append(alloc, malformed_pieces[1]);
        var prepared = try helix_live.prepare(alloc, .{
            .epoch = 1,
            .now_ms = 1,
            .timeout_ms = 1000,
            .arena_name = "onyx-test-property-state-select",
            .pieces = pieces.items,
            .fds = &.{},
        });
        defer prepared.deinit();
        const dup_rc = linux.dup(prepared.runtime.arena.?.fd);
        if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
        const arena_dup: linux.fd_t = @intCast(dup_rc);

        var successor = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer successor.deinit();
        const sentinel = try ircx_prop_store.Entity.fromId("Sentinel");
        _ = try successor.props.setProp(sentinel, "CUSTOM", "old triplet", .{ .id = "Sentinel", .access = .user });
        try std.testing.expect(successor.recordChannelPropClock("#Sentinel", "OLD", "old", 1, false, 1, "", ""));
        try std.testing.expect(successor.recordEntityPropClock(.user, "Sentinel", "OLD", "old", 1, false, 1, "", ""));
        const listener_fd = successor.reactors[0].listener_fd;
        successor.config.resume_arena_fd = arena_dup;
        try std.testing.expectError(error.InvalidInheritedHandoff, successor.adoptInheritedSessions());
        current_reactor = null;

        try std.testing.expect(successor.config.resume_arena_fd == null);
        try std.testing.expectEqualStrings("old triplet", (try successor.props.getPropRaw(sentinel, "CUSTOM")).value);
        try std.testing.expect(successor.channelPropClock("#Sentinel", "OLD") != null);
        try std.testing.expect(successor.entityPropClock(.user, "Sentinel", "OLD") != null);
        try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(arena_dup, posix.F.GETFD, 0)));
        try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(listener_fd, posix.F.GETFD, 0)));
    }
}

test "UPGRADE property checkpoint rejects malformed required outer capsule shapes" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var props = ircx_prop_store.DefaultStore.init(alloc);
    defer props.deinit();
    var channel_clocks: prop_checkpoint.ChannelClockMap = .empty;
    defer channel_clocks.deinit(alloc);
    var entity_clocks: prop_checkpoint.EntityClockMap = .empty;
    defer entity_clocks.deinit(alloc);
    const valid = try prop_checkpoint.encode(alloc, &props, &channel_clocks, &entity_clocks);
    defer alloc.free(valid);

    const Scenario = enum { empty_fields, wrong_ordinal, extra_field, future_outer_version };
    for ([_]Scenario{ .empty_fields, .wrong_ordinal, .extra_field, .future_outer_version }) |scenario| {
        var field_buf: [2]helix_capsule.Field = undefined;
        const fields: []helix_capsule.Field = switch (scenario) {
            .empty_fields => field_buf[0..0],
            .wrong_ordinal => blk: {
                field_buf[0] = .{ .ordinal = 2, .bytes = valid };
                break :blk field_buf[0..1];
            },
            .extra_field => blk: {
                field_buf[0] = .{ .ordinal = 1, .bytes = valid };
                field_buf[1] = .{ .ordinal = 2, .bytes = "" };
                break :blk field_buf[0..2];
            },
            .future_outer_version => blk: {
                field_buf[0] = .{ .ordinal = 1, .bytes = valid };
                break :blk field_buf[0..1];
            },
        };
        var cap = helix_capsule.make(.mesh_checkpoint, fields);
        cap.header.min_supported = 2;
        if (scenario == .future_outer_version) {
            cap.header.version = 3;
            cap.header.max_supported = 3;
        } else {
            cap.header.max_supported = 2;
        }
        const encoded = try helix_capsule.encode(alloc, cap);
        defer alloc.free(encoded);
        // The generic decoder intentionally accepts these evolvable shapes;
        // the property selector is the layer that requires exact v2/ordinal-1.
        var generic = try helix_capsule.decode(alloc, encoded);
        generic.deinit(alloc);

        var arena = try helix_handoff.Arena.create("onyx-test-property-outer-shape");
        defer arena.close();
        try arena.writeAll(encoded);
        try arena.seal();
        const dup_rc = linux.dup(arena.fd);
        if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
        const arena_dup: linux.fd_t = @intCast(dup_rc);
        var arena_dup_owned = true;
        defer if (arena_dup_owned) closeFd(arena_dup);

        var successor = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
            else => return err,
        };
        defer successor.deinit();
        const sentinel = try ircx_prop_store.Entity.fromId("Sentinel");
        _ = try successor.props.setProp(sentinel, "CUSTOM", "old triplet", .{ .id = "Sentinel", .access = .user });
        try std.testing.expect(successor.recordChannelPropClock("#Sentinel", "OLD", "old", 1, false, 1, "", ""));
        try std.testing.expect(successor.recordEntityPropClock(.user, "Sentinel", "OLD", "old", 1, false, 1, "", ""));
        const listener_fd = successor.reactors[0].listener_fd;
        successor.config.resume_arena_fd = arena_dup;
        try std.testing.expectError(error.InvalidInheritedHandoff, successor.adoptInheritedSessions());
        arena_dup_owned = false;
        current_reactor = null;

        try std.testing.expect(successor.config.resume_arena_fd == null);
        try std.testing.expectEqualStrings("old triplet", (try successor.props.getPropRaw(sentinel, "CUSTOM")).value);
        try std.testing.expect(successor.channelPropClock("#Sentinel", "OLD") != null);
        try std.testing.expect(successor.entityPropClock(.user, "Sentinel", "OLD") != null);
        try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(arena_dup, posix.F.GETFD, 0)));
        try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(listener_fd, posix.F.GETFD, 0)));
    }
}

test "UPGRADE resume arena restores the multi-session registry (re-track + snapshot)" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    // The carried live connection: one end transfers to the server on adopt.
    var sp: [2]i32 = undefined;
    const sp_rc = linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sp);
    if (linux.errno(sp_rc) != .SUCCESS) return error.SkipZigTest;
    defer closeFd(sp[1]); // sp[0] ownership transfers to the server on adopt

    const tok_a: sessions_mod.Token = @splat('A'); // attached, conn carried
    const tok_b: sessions_mod.Token = @splat('B'); // detached ghost + snapshot
    const tok_c: sessions_mod.Token = @splat('C'); // attached, conn NOT carried

    // The predecessor's `.clients` snapshot for the carried connection ...
    const sess_blob = try session_snapshot.encode(alloc, .{
        .nick = "ALIA",
        .realname = "Carried",
        .account = "alice",
        .logged_in = true,
        .fd = sp[0],
        .session_token = &tok_a,
    });
    defer alloc.free(sess_blob);
    // ... and the `.sessions` registry capsule for its account: one attached
    // session joined by fd, another attachment carrying the SAME logical token
    // whose socket was not carried, one detached bouncer ghost with a restore
    // snapshot, and one unrelated attached session that also did not survive.
    const entries = [_]session_capsule.SessionEntry{
        .{ .token = &tok_a, .signon_unix = 1111, .detached = false, .client = 0xDEAD, .fd = sp[0], .portable_resume = true },
        .{ .token = &tok_a, .signon_unix = 1112, .detached = false, .client = 0xBEEF, .fd = 99_998, .portable_resume = true },
        .{ .token = &tok_b, .signon_unix = 2222, .detached = true, .client = 777, .snapshot = "restore-blob" },
        .{ .token = &tok_c, .signon_unix = 3333, .detached = false, .client = 888, .fd = 99_999 },
    };
    const cap = session_capsule.SessionCapsule{ .account = "alice", .sessions = &entries };
    var cap_buf: [512]u8 = undefined;
    const cap_wire = try cap.encode(&cap_buf);

    var fixture = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer fixture.deinit();
    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |blob| alloc.free(blob);
        blobs.deinit(alloc);
    }
    var arena_pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer arena_pieces.deinit(alloc);
    try appendCurrentMandatoryUpgradeStateForTest(&fixture, &arena_pieces, &blobs);
    try arena_pieces.append(alloc, .{ .kind = .clients, .bytes = sess_blob });
    try arena_pieces.append(alloc, .{ .kind = .sessions, .bytes = cap_wire });
    try appendEmptyUpgradeClientSidecarsForTest(alloc, &arena_pieces, &blobs, sp[0]);
    var prepared = try helix_live.prepare(alloc, .{
        .epoch = 1,
        .now_ms = 1,
        .timeout_ms = 1000,
        .arena_name = "onyx-test-sess-adopt",
        .pieces = arena_pieces.items,
        .fds = &.{sp[0]},
    });
    defer prepared.deinit();
    const dup_rc = linux.dup(prepared.runtime.arena.?.fd);
    if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
    const arena_dup: linux.fd_t = @intCast(dup_rc);

    var server = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    server.config.resume_arena_fd = arena_dup;
    var state_fds = [_]linux.fd_t{sp[0]};
    server.config.inherited_state_fds = &state_fds;
    server.config.inherited_state_fd_manifest_present = true;
    server.config.inherited_state_fd_manifest_valid = true;
    try server.adoptInheritedSessions();
    current_reactor = null;
    try std.testing.expect(server.monitor.isOnline("ALIA"));

    // (1) The attached session re-tracked against the adopted connection with
    // the SAME reclaim token — not wiped, not detached, not a fresh token.
    // The shared token remains a token GROUP: both rows survive atomically, the
    // carried socket is attached, and the missing socket degrades to a detached
    // attachment without rotating/consuming the credential or portability bit.
    const rows = try server.sessions.copySessionsAlloc(alloc, "alice");
    defer alloc.free(rows);
    var shared_count: usize = 0;
    var shared_attached: usize = 0;
    var shared_detached: usize = 0;
    var attached_client: ?u64 = null;
    var shared_ghost: ?u64 = null;
    for (rows) |row| {
        if (!std.crypto.timing_safe.eql(sessions_mod.Token, row.token, tok_a)) continue;
        shared_count += 1;
        if (row.attached) {
            shared_attached += 1;
            attached_client = row.client;
        } else {
            shared_detached += 1;
            shared_ghost = row.client;
        }
        try std.testing.expect(row.portable_resume);
    }
    try std.testing.expectEqual(@as(usize, 2), shared_count);
    try std.testing.expectEqual(@as(usize, 1), shared_attached);
    try std.testing.expectEqual(@as(usize, 1), shared_detached);
    try std.testing.expect(attached_client.? != 0xDEAD);
    try std.testing.expect(shared_ghost.? != 0xBEEF);
    try std.testing.expect(shared_ghost.? != attached_client.?);
    // (2) The detached bouncer ghost survived with token, identity, and a
    // byte-identical restore snapshot — SESSION RESUME finds it, not NO_SESSION.
    const tok_b_ghost = server.sessions.findDetachedTokenInAccount("alice", tok_b).?;
    try std.testing.expect(tok_b_ghost != 777);
    try std.testing.expect(tok_b_ghost != attached_client.?);
    const restored = (try server.sessions.copyDetachedSnapshotInAccount(alloc, "alice", tok_b)).?;
    defer alloc.free(restored);
    try std.testing.expectEqualSlices(u8, "restore-blob", restored);
    // (3) The attached session whose connection was NOT carried degrades to a
    // detached ghost (token preserved for reclaim), never a wrong re-join.
    const tok_c_ghost = server.sessions.findDetachedTokenInAccount("alice", tok_c).?;
    try std.testing.expect(tok_c_ghost != 888);
    try std.testing.expect(tok_c_ghost != attached_client.?);
}

test "DPROP1 UPGRADE late malformed sessions failure preserves causal triplet and MeshClock" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    const tok_good: sessions_mod.Token = @splat('G');
    const tok_valid: sessions_mod.Token = @splat('V');

    var inherited_pair: [2]linux.fd_t = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &inherited_pair)) != .SUCCESS)
        return error.SkipZigTest;
    var inherited_owner_open = true;
    defer if (inherited_owner_open) closeFd(inherited_pair[0]);
    defer closeFd(inherited_pair[1]);
    const client_wire = try session_snapshot.encode(alloc, .{
        .nick = "LateRollback",
        .realname = "Late transaction rollback client",
        .fd = inherited_pair[0],
    });
    defer alloc.free(client_wire);

    // A healthy account capsule ...
    const good_entries = [_]session_capsule.SessionEntry{
        .{ .token = &tok_good, .signon_unix = 10, .detached = true, .client = 42, .snapshot = "good-snap" },
    };
    var good_buf: [256]u8 = undefined;
    const good_wire = try (session_capsule.SessionCapsule{ .account = "good", .sessions = &good_entries }).encode(&good_buf);

    // ... an account with one VALID and one MALFORMED entry (8-byte token) —
    // the whole account must be rejected, including the valid entry (all-old-
    // or-all-new, never a torn subset) ...
    const torn_entries = [_]session_capsule.SessionEntry{
        .{ .token = &tok_valid, .signon_unix = 20, .detached = true, .client = 1 },
        .{ .token = "short-8b", .signon_unix = 21, .detached = true, .client = 2 },
    };
    var torn_buf: [256]u8 = undefined;
    const torn_wire = try (session_capsule.SessionCapsule{ .account = "torn", .sessions = &torn_entries }).encode(&torn_buf);

    // ... and a garbage `.sessions` payload (bad inner magic) — skipped, no panic.
    const garbage = "not-a-session-capsule-at-all";

    var fixture = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer fixture.deinit();
    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |blob| alloc.free(blob);
        blobs.deinit(alloc);
    }
    var arena_pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer arena_pieces.deinit(alloc);
    try appendCurrentMandatoryUpgradeStateForTest(&fixture, &arena_pieces, &blobs);
    try arena_pieces.append(alloc, .{ .kind = .clients, .bytes = client_wire });
    try appendEmptyUpgradeClientSidecarsForTest(alloc, &arena_pieces, &blobs, inherited_pair[0]);
    try arena_pieces.append(alloc, .{ .kind = .sessions, .bytes = good_wire });
    try arena_pieces.append(alloc, .{ .kind = .sessions, .bytes = torn_wire });
    try arena_pieces.append(alloc, .{ .kind = .sessions, .bytes = garbage });
    var prepared = try helix_live.prepare(alloc, .{
        .epoch = 1,
        .now_ms = 1,
        .timeout_ms = 1000,
        .arena_name = "onyx-test-sess-fault",
        .pieces = arena_pieces.items,
        .fds = &.{inherited_pair[0]},
    });
    defer prepared.deinit();
    const dup_rc = linux.dup(prepared.runtime.arena.?.fd);
    if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
    const arena_dup: linux.fd_t = @intCast(dup_rc);

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(alloc, std.testing.io, tmp.dir, "server-dprop-late-rollback.wal");
    defer store.deinit();
    var identity = try node_identity.fromSeed(@as([32]u8, @splat(0xc7)), "dprop-late-rollback.test");
    defer identity.deinit();
    var state = try durable_credential_props.State.init(alloc, .{ .local_origin_node = identity.shortId() });
    defer state.deinit();
    var services = services_mod.Services.init(&store, null);
    services.attachDurableCredentialProps(&state);

    var server = Server.init(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_port = 0,
        .node_id = identity.shortId(),
        .node_identity = &identity,
        .account_services = &services,
        .durable_device_boot = .{ .authoritative = .{ .state = &state, .local_origin_node = identity.shortId() } },
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    // Seed every late-adoption store with an unmistakable boot image. The
    // healthy first account is deliberately applied before the malformed second
    // account fails; transaction rollback must discard that prefix and restore
    // all old authorities, not merely World.
    const old_token: sessions_mod.Token = @splat('O');
    _ = try server.sessions.attach("old-account", 0xA11, old_token, 7);
    try std.testing.expect(server.sessions.markDetached("old-account", 0xA11));
    try server.monitor.restoreTarget(0xA11, "OldTarget");
    try server.monitor.restoreOnline("OldTarget");
    try std.testing.expect(try server.silence.add("OldOwner", "bad!*@example.test"));
    _ = try server.world.markRegistered("#old-world", true);
    try seedUpgradeAtomicPublicationSentinels(&server);
    try commitDurableDeviceFactForBootTest(&state, &identity, 53);
    const property_before = try prop_checkpoint.encode(
        alloc,
        &server.props,
        &server.channel_prop_clocks,
        &server.entity_prop_clocks,
    );
    defer alloc.free(property_before);
    const mesh_clock_before = server.mesh_clock;
    const migration_epoch_before = server.migration_offer_epoch;
    const old_generation = server.session_replica_store_generation;
    const old_ticket_key = server.tls_ticket_key;
    const old_previous_ticket_key = server.tls_previous_ticket_key;
    const old_msg_seq = server.msg_seq;
    server.config.resume_arena_fd = arena_dup;
    var state_fds = [_]linux.fd_t{inherited_pair[0]};
    server.config.inherited_state_fds = &state_fds;
    server.config.inherited_state_fd_manifest_present = true;
    server.config.inherited_state_fd_manifest_valid = true;
    try std.testing.expectError(error.InvalidInheritedHandoff, server.adoptInheritedSessions());
    inherited_owner_open = false;
    current_reactor = null;

    try std.testing.expect(server.config.resume_arena_fd == null);
    try std.testing.expect(server.world.channelExists("#old-world"));
    try std.testing.expect(server.sessions.findDetachedTokenInAccount("old-account", old_token) != null);
    const good_rows = try server.sessions.copySessionsAlloc(alloc, "good");
    defer alloc.free(good_rows);
    try std.testing.expectEqual(@as(usize, 0), good_rows.len);
    try std.testing.expectEqual(@as(usize, 1), server.monitor.monitorCount(0xA11));
    try std.testing.expect(server.monitor.isOnline("OldTarget"));
    try std.testing.expect(server.silence.isSilenced("OldOwner", "bad!user@example.test"));
    try std.testing.expectEqual(old_ticket_key, server.tls_ticket_key);
    try std.testing.expectEqual(old_previous_ticket_key, server.tls_previous_ticket_key);
    try std.testing.expectEqual(old_msg_seq, server.msg_seq);
    const property_after = try prop_checkpoint.encode(
        alloc,
        &server.props,
        &server.channel_prop_clocks,
        &server.entity_prop_clocks,
    );
    defer alloc.free(property_after);
    try std.testing.expectEqualSlices(u8, property_before, property_after);
    try std.testing.expectEqual(mesh_clock_before, server.mesh_clock);
    try std.testing.expectEqual(migration_epoch_before, server.migration_offer_epoch);
    try std.testing.expectEqual(@as(usize, 0), server.reactors[0].clients.len());
    try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(inherited_pair[0], posix.F.GETFD, 0)));
    try expectUpgradeAtomicPublicationSentinels(&server, old_generation);
}

test "UPGRADE session registry ghosts cannot collide with a live successor client id" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var sp: [2]i32 = undefined;
    const sp_rc = linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &sp);
    if (linux.errno(sp_rc) != .SUCCESS) return error.SkipZigTest;
    defer closeFd(sp[1]);

    var server = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];
    const id = try server.reactors[0].clients.alloc(ConnState.init(sp[0]));
    const live_client = monitorIdFromClient(id);
    const live_token: sessions_mod.Token = @splat(0xA1);
    const ghost_token: sessions_mod.Token = @splat(0xB2);
    _ = try server.sessions.attachReportingEviction("alice", live_client, live_token, 1);

    // Reproduce the old alias hazard directly: the predecessor's detached row
    // carries the same numeric client handle the successor just allocated live.
    const entries = [_]session_capsule.SessionEntry{
        .{ .token = &live_token, .signon_unix = 1, .detached = false, .client = 7, .fd = sp[0] },
        .{ .token = &ghost_token, .signon_unix = 2, .detached = true, .client = live_client, .snapshot = "ghost" },
    };
    var detached_seq: u64 = 0;
    var attachment_remaps: std.ArrayList(attachment_delivery_spool.AttachmentRemap) = .empty;
    defer attachment_remaps.deinit(alloc);
    const attachment_clients = [_]attachment_delivery_spool.ClientId{ 7, live_client };
    try attachment_remaps.ensureTotalCapacity(alloc, attachment_clients.len);
    try std.testing.expectEqual(
        @as(usize, 2),
        server.adoptSessionRegistryAccount(
            .{ .account = "alice", .sessions = &entries },
            &detached_seq,
            &attachment_clients,
            &attachment_remaps,
        ),
    );
    try std.testing.expectEqual(@as(usize, 2), attachment_remaps.items.len);

    const live = server.sessions.resumeHandleForClient("alice", live_client) orelse return error.TestUnexpectedResult;
    try std.testing.expect(server.sessions.containsClient("alice", live_client));
    try std.testing.expect(std.crypto.timing_safe.eql(sessions_mod.Token, live_token, live.token));
    const ghost_client = server.sessions.findDetachedTokenInAccount("alice", ghost_token) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(ghost_client != live_client);
    const ghost_snapshot = (try server.sessions.copyDetachedSnapshotInAccount(alloc, "alice", ghost_token)).?;
    defer alloc.free(ghost_snapshot);
    try std.testing.expectEqualStrings("ghost", ghost_snapshot);
}

test "UPGRADE attachment remaps stay bounded by tiny ADS1 authority across large HSSN registry" {
    const alloc = std.testing.allocator;
    const attachment_clients = [_]attachment_delivery_spool.ClientId{2048};
    var remaps: std.ArrayList(attachment_delivery_spool.AttachmentRemap) = .empty;
    defer remaps.deinit(alloc);
    try remaps.ensureTotalCapacity(alloc, attachment_clients.len);
    const planned_capacity = remaps.capacity;

    var old_client: u64 = 0;
    while (old_client < 4096) : (old_client += 1) {
        LinuxServer.appendAttachmentRemapIfNeeded(
            &attachment_clients,
            &remaps,
            old_client,
            old_client + 10_000,
        ) orelse return error.TestUnexpectedResult;
    }
    try std.testing.expectEqual(@as(usize, 1), remaps.items.len);
    try std.testing.expectEqual(@as(u64, 2048), remaps.items[0].old_client);
    try std.testing.expectEqual(@as(u64, 12_048), remaps.items[0].new_client);
    try std.testing.expectEqual(planned_capacity, remaps.capacity);

    // A second HSSN owner for the only spooled predecessor is ambiguous.
    try std.testing.expect(LinuxServer.appendAttachmentRemapIfNeeded(
        &attachment_clients,
        &remaps,
        2048,
        77,
    ) == null);
}

test "UPGRADE resume arena re-stages carried .pending_migration capsules" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    // Predecessor: one staged cross-mesh migration awaiting the client's
    // reconnect, sealed exactly like performUpgrade does.
    var pred = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer pred.deinit();
    pred.pending_migrations = session_migrate.PendingMigrations.init(alloc);
    const token: session_migrate.Token = @as([15]u8, @splat(0)) ++ .{9};
    const consumed_token: session_migrate.Token = @as([15]u8, @splat(0)) ++ .{10};
    const staged_at = @max(@as(i64, 0), pred.nowMs());
    try pred.pending_migrations.?.putAtEpoch(.{ .token = token, .account = "kain", .snapshot = "verified-relay-snapshot" }, staged_at, 77);
    try pred.pending_migrations.?.markConsumed(consumed_token, staged_at);

    var blobs: std.ArrayList([]u8) = .empty;
    defer {
        for (blobs.items) |b| alloc.free(b);
        blobs.deinit(alloc);
    }
    var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
    defer pieces.deinit(alloc);
    try appendCurrentMandatoryUpgradeStateForTest(&pred, &pieces, &blobs);
    var found_pending = false;
    for (pieces.items) |piece| {
        if (piece.kind == .pending_migration) found_pending = true;
    }
    try std.testing.expect(found_pending);

    var prepared = try helix_live.prepare(alloc, .{
        .epoch = 1,
        .now_ms = 1,
        .timeout_ms = 1000,
        .arena_name = "onyx-test-pm-adopt",
        .pieces = pieces.items,
        .fds = &.{},
    });
    defer prepared.deinit();
    const dup_rc = linux.dup(prepared.runtime.arena.?.fd);
    if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
    const arena_dup: linux.fd_t = @intCast(dup_rc);

    // Successor: adoption re-stages the migration under the SAME token, so the
    // client's eventual reconnect+reclaim still finds it after the swap.
    var succ = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer succ.deinit();
    succ.config.resume_arena_fd = arena_dup;
    try succ.adoptInheritedSessions();
    current_reactor = null;

    const pm = &succ.pending_migrations.?;
    try std.testing.expectEqual(@as(usize, 1), pm.count());
    const e = pm.get(token) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("kain", e.account);
    try std.testing.expectEqualStrings("verified-relay-snapshot", e.snapshot);
    try std.testing.expectEqual(staged_at, e.staged_at_ms);
    try std.testing.expectEqual(@as(u64, 77), e.offer_epoch);
    try std.testing.expect(pm.isConsumed(consumed_token));
    try std.testing.expectError(error.AlreadyConsumed, pm.put(.{ .token = consumed_token, .account = "kain", .snapshot = "late" }, 3));
}

test "UPGRADE arena read failure closes exact carried fd manifest but preserves listeners" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var server = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    var client_pair: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &client_pair)) != .SUCCESS)
        return error.SkipZigTest;
    defer closeFd(client_pair[1]);
    var link_pair: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &link_pair)) != .SUCCESS) {
        closeFd(client_pair[0]);
        return error.SkipZigTest;
    }
    defer closeFd(link_pair[1]);

    // A manifest that names any service listener is never trusted for cleanup.
    var collision = [_]linux.fd_t{server.reactors[0].listener_fd};
    server.config.inherited_state_fds = &collision;
    server.config.inherited_state_fd_manifest_present = true;
    server.config.inherited_state_fd_manifest_valid = true;
    try std.testing.expect(!server.inheritedStateFdManifestTrusted(-1));
    server.clearInheritedStateFdManifest();

    // Use a closed duplicate as the inherited arena so readArena takes its
    // earliest failure path, where no capsule bytes are available to scan.
    const arena_pieces = [_]helix_live.StatePiece{.{ .kind = .channels, .bytes = "unused" }};
    var prepared = try helix_live.prepare(alloc, .{
        .epoch = 1,
        .now_ms = 1,
        .timeout_ms = 1000,
        .arena_name = "onyx-test-state-fd-cleanup",
        .pieces = &arena_pieces,
        .fds = &.{},
    });
    defer prepared.deinit();
    const dup_rc = linux.dup(prepared.runtime.arena.?.fd);
    if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
    const dead_arena_fd: linux.fd_t = @intCast(dup_rc);
    closeFd(dead_arena_fd);

    var state_fds = [_]linux.fd_t{ client_pair[0], link_pair[0] };
    server.config.resume_arena_fd = dead_arena_fd;
    server.config.inherited_state_fds = &state_fds;
    server.config.inherited_state_fd_manifest_present = true;
    server.config.inherited_state_fd_manifest_valid = true;
    try std.testing.expectError(error.InvalidInheritedHandoff, server.adoptInheritedSessions());
    current_reactor = null;

    try std.testing.expect(server.config.resume_arena_fd == null);
    try std.testing.expectEqual(@as(usize, 0), server.config.inherited_state_fds.len);
    try std.testing.expect(!server.config.inherited_state_fd_manifest_present);
    try std.testing.expect(!server.config.inherited_state_fd_manifest_valid);
    try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(client_pair[0], posix.F.GETFD, 0)));
    try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(link_pair[0], posix.F.GETFD, 0)));
    try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(client_pair[1], posix.F.GETFD, 0)));
    try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(link_pair[1], posix.F.GETFD, 0)));
    try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(server.reactors[0].listener_fd, posix.F.GETFD, 0)));
}

test "UPGRADE authoritative manifest rejects an arena fd aliased to a listener" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var server = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    var state_pair: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &state_pair)) != .SUCCESS)
        return error.SkipZigTest;
    defer for (state_pair) |fd| closeFd(fd);

    const listener_fd = server.reactors[0].listener_fd;
    var state_fds = [_]linux.fd_t{state_pair[0]};
    server.config.resume_arena_fd = listener_fd;
    server.config.inherited_state_fds = &state_fds;
    server.config.inherited_state_fd_manifest_present = true;
    server.config.inherited_state_fd_manifest_valid = true;

    try std.testing.expect(!server.inheritedStateFdManifestTrusted(listener_fd));
    try std.testing.expectError(error.InvalidInheritedHandoff, server.adoptInheritedSessions());
    current_reactor = null;

    // Startup-fatal rejection leaves every descriptor untouched for process
    // unwind; in particular it never enters readArena's close(arena_fd) path.
    try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(listener_fd, posix.F.GETFD, 0)));
    try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(state_pair[0], posix.F.GETFD, 0)));
    try std.testing.expect(server.config.resume_arena_fd != null);
    try std.testing.expect(server.config.inherited_state_fd_manifest_present);
}

test "UPGRADE authoritative manifest accepts only open connected stream sockets" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    var server = Server.init(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const pieces = [_]helix_live.StatePiece{.{ .kind = .channels, .bytes = "unused" }};
    var prepared = try helix_live.prepare(alloc, .{
        .epoch = 1,
        .now_ms = 1,
        .timeout_ms = 1000,
        .arena_name = "onyx-test-state-fd-socket-kind",
        .pieces = &pieces,
        .fds = &.{},
    });
    defer prepared.deinit();
    const arena_rc = linux.dup(prepared.runtime.arena.?.fd);
    if (linux.errno(arena_rc) != .SUCCESS) return error.SkipZigTest;
    const arena_dup: linux.fd_t = @intCast(arena_rc);
    defer closeFd(arena_dup);

    var connected: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &connected)) != .SUCCESS)
        return error.SkipZigTest;
    defer for (connected) |fd| closeFd(fd);

    // A distinct duplicate of the sealed memfd is an open regular file, not a
    // socket. Keeping it distinct from arena_dup proves this is a type check,
    // not merely the numeric arena-collision guard.
    const regular_rc = linux.dup(prepared.runtime.arena.?.fd);
    if (linux.errno(regular_rc) != .SUCCESS) return error.SkipZigTest;
    const regular_fd: linux.fd_t = @intCast(regular_rc);
    defer closeFd(regular_fd);

    const event_rc = linux.eventfd(0, 0);
    if (linux.errno(event_rc) != .SUCCESS) return error.SkipZigTest;
    const event_fd: linux.fd_t = @intCast(event_rc);
    defer closeFd(event_fd);

    var pipe_fds: [2]i32 = undefined;
    if (linux.errno(linux.pipe(&pipe_fds)) != .SUCCESS) return error.SkipZigTest;
    defer for (pipe_fds) |fd| closeFd(fd);

    const rogue_listener = createListener("127.0.0.1", 0, 1) catch return error.SkipZigTest;
    defer closeFd(rogue_listener);

    // Allocate and close this last so its numeric slot cannot be reused by a
    // later setup syscall before the rejection is exercised.
    const closed_rc = linux.dup(connected[0]);
    if (linux.errno(closed_rc) != .SUCCESS) return error.SkipZigTest;
    const closed_fd: linux.fd_t = @intCast(closed_rc);
    closeFd(closed_fd);

    const invalid_fds = [_]linux.fd_t{
        closed_fd,
        regular_fd,
        event_fd,
        pipe_fds[0],
        rogue_listener,
    };
    for (invalid_fds) |invalid_fd| {
        var manifest = [_]linux.fd_t{invalid_fd};
        server.config.resume_arena_fd = arena_dup;
        server.config.inherited_state_fds = &manifest;
        server.config.inherited_state_fd_manifest_present = true;
        server.config.inherited_state_fd_manifest_valid = true;

        try std.testing.expect(!server.inheritedStateFdManifestTrusted(arena_dup));
        try std.testing.expectError(error.InvalidInheritedHandoff, server.adoptInheritedSessions());
        current_reactor = null;
        try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(arena_dup, posix.F.GETFD, 0)));
        try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(server.reactors[0].listener_fd, posix.F.GETFD, 0)));
        if (invalid_fd == closed_fd) {
            try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(invalid_fd, posix.F.GETFD, 0)));
        } else {
            // Fatal rejection never guesses at or closes the invalid descriptor.
            try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(invalid_fd, posix.F.GETFD, 0)));
        }
    }

    var valid_manifest = [_]linux.fd_t{connected[0]};
    server.config.inherited_state_fds = &valid_manifest;
    server.config.inherited_state_fd_manifest_present = true;
    server.config.inherited_state_fd_manifest_valid = true;
    try std.testing.expect(server.inheritedStateFdManifestTrusted(arena_dup));
}

test "UPGRADE authoritative state fd manifest requires an exact capsule bijection before restore" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    const Scenario = enum { extra_manifest_fd, capsule_fd_absent, duplicate_capsule_fd, unreadable_owner_capsule };
    for ([_]Scenario{ .extra_manifest_fd, .capsule_fd_absent, .duplicate_capsule_fd, .unreadable_owner_capsule }) |scenario| {
        var owned_pair: [2]i32 = undefined;
        if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &owned_pair)) != .SUCCESS)
            return error.SkipZigTest;
        defer for (owned_pair) |fd| closeFd(fd);
        var other_pair: [2]i32 = undefined;
        if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &other_pair)) != .SUCCESS)
            return error.SkipZigTest;
        defer for (other_pair) |fd| closeFd(fd);

        const client_blob = try session_snapshot.encode(alloc, .{
            .nick = "manifest-user",
            .realname = "Manifest",
            .fd = owned_pair[0],
        });
        defer alloc.free(client_blob);
        var piece_buf: [2]helix_live.StatePiece = undefined;
        const owner_pieces: []const helix_live.StatePiece = switch (scenario) {
            .duplicate_capsule_fd => blk: {
                piece_buf[0] = .{ .kind = .clients, .bytes = client_blob };
                piece_buf[1] = .{ .kind = .clients, .bytes = client_blob };
                break :blk piece_buf[0..2];
            },
            .unreadable_owner_capsule => blk: {
                piece_buf[0] = .{ .kind = .clients, .bytes = "short" };
                break :blk piece_buf[0..1];
            },
            else => blk: {
                piece_buf[0] = .{ .kind = .clients, .bytes = client_blob };
                break :blk piece_buf[0..1];
            },
        };
        const fixture = try alloc.create(Server);
        fixture.initInPlace(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| {
            alloc.destroy(fixture);
            return switch (err) {
                error.Unsupported, error.PermissionDenied, error.SocketUnavailable => error.SkipZigTest,
                else => err,
            };
        };
        defer {
            fixture.deinit();
            alloc.destroy(fixture);
        }
        var blobs: std.ArrayList([]u8) = .empty;
        defer {
            for (blobs.items) |blob| alloc.free(blob);
            blobs.deinit(alloc);
        }
        var pieces: std.ArrayList(helix_live.StatePiece) = .empty;
        defer pieces.deinit(alloc);
        try appendCurrentMandatoryUpgradeStateForTest(fixture, &pieces, &blobs);
        try pieces.appendSlice(alloc, owner_pieces);
        if (scenario != .unreadable_owner_capsule)
            try appendEmptyUpgradeClientSidecarsForTest(alloc, &pieces, &blobs, owned_pair[0]);
        var prepared = try helix_live.prepare(alloc, .{
            .epoch = 1,
            .now_ms = 1,
            .timeout_ms = 1000,
            .arena_name = "onyx-test-state-fd-bijection",
            .pieces = pieces.items,
            .fds = &.{},
        });
        defer prepared.deinit();
        const dup_rc = linux.dup(prepared.runtime.arena.?.fd);
        if (linux.errno(dup_rc) != .SUCCESS) return error.SkipZigTest;
        const arena_dup: linux.fd_t = @intCast(dup_rc);
        defer closeFd(arena_dup);

        const server = try alloc.create(Server);
        server.initInPlace(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| {
            alloc.destroy(server);
            return switch (err) {
                error.Unsupported, error.PermissionDenied, error.SocketUnavailable => error.SkipZigTest,
                else => err,
            };
        };
        defer {
            server.deinit();
            alloc.destroy(server);
        }
        const listener_fd = server.reactors[0].listener_fd;
        var manifest_buf: [2]linux.fd_t = undefined;
        const manifest: []linux.fd_t = switch (scenario) {
            .extra_manifest_fd => blk: {
                manifest_buf = .{ owned_pair[0], other_pair[0] };
                break :blk manifest_buf[0..2];
            },
            .capsule_fd_absent => blk: {
                manifest_buf[0] = other_pair[0];
                break :blk manifest_buf[0..1];
            },
            else => blk: {
                manifest_buf[0] = owned_pair[0];
                break :blk manifest_buf[0..1];
            },
        };
        server.config.resume_arena_fd = arena_dup;
        server.config.inherited_state_fds = manifest;
        server.config.inherited_state_fd_manifest_present = true;
        server.config.inherited_state_fd_manifest_valid = true;
        try std.testing.expectError(error.InvalidInheritedHandoff, server.adoptInheritedSessions());
        current_reactor = null;

        // The exact trusted manifest is the cleanup authority: rejection closes
        // the arena and precisely the descriptors it named, never an unlisted fd.
        try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(arena_dup, posix.F.GETFD, 0)));
        const owned_expected: linux.E = if (scenario == .capsule_fd_absent) .SUCCESS else .BADF;
        const other_expected: linux.E = if (scenario == .extra_manifest_fd or scenario == .capsule_fd_absent) .BADF else .SUCCESS;
        try std.testing.expectEqual(owned_expected, linux.errno(linux.fcntl(owned_pair[0], posix.F.GETFD, 0)));
        try std.testing.expectEqual(other_expected, linux.errno(linux.fcntl(other_pair[0], posix.F.GETFD, 0)));
        try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(listener_fd, posix.F.GETFD, 0)));
        try std.testing.expect(server.config.resume_arena_fd == null);
        try std.testing.expect(!server.config.inherited_state_fd_manifest_present);
    }

    const no_arena_server = try alloc.create(Server);
    no_arena_server.initInPlace(alloc, .{ .host = "127.0.0.1", .port = 0, .tls_port = 0 }) catch |err| {
        alloc.destroy(no_arena_server);
        return switch (err) {
            error.Unsupported, error.PermissionDenied, error.SocketUnavailable => error.SkipZigTest,
            else => err,
        };
    };
    defer {
        no_arena_server.deinit();
        alloc.destroy(no_arena_server);
    }
    no_arena_server.config.inherited_state_fd_manifest_present = true;
    no_arena_server.config.inherited_state_fd_manifest_valid = false;
    try std.testing.expectError(error.InvalidInheritedHandoff, no_arena_server.adoptInheritedSessions());
    try std.testing.expectEqual(
        linux.E.SUCCESS,
        linux.errno(linux.fcntl(no_arena_server.reactors[0].listener_fd, posix.F.GETFD, 0)),
    );

    var orphan_pair: [2]i32 = undefined;
    if (linux.errno(linux.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &orphan_pair)) != .SUCCESS)
        return error.SkipZigTest;
    var orphan_owner_closed = false;
    defer if (!orphan_owner_closed) closeFd(orphan_pair[0]);
    defer closeFd(orphan_pair[1]);
    var orphan_manifest = [_]linux.fd_t{orphan_pair[0]};
    no_arena_server.config.inherited_state_fds = &orphan_manifest;
    no_arena_server.config.inherited_state_fd_manifest_present = true;
    no_arena_server.config.inherited_state_fd_manifest_valid = true;
    try no_arena_server.adoptInheritedSessions();
    orphan_owner_closed = true;
    try std.testing.expectEqual(linux.E.BADF, linux.errno(linux.fcntl(orphan_pair[0], posix.F.GETFD, 0)));
    try std.testing.expectEqual(linux.E.SUCCESS, linux.errno(linux.fcntl(orphan_pair[1], posix.F.GETFD, 0)));
}

