    defer server.deinit();

    const account = "projector-detached";
    const primary_id = try addTestLocalClient(&server, "Shared", account);
    const ghost_id = try addTestLocalClient(&server, "Ghost", account);
    const survivor_id = try addTestLocalClient(&server, "Survivor", account);
    const primary = server.connFor(primary_id).?;
    const ghost = server.connFor(ghost_id).?;
    const survivor = server.connFor(survivor_id).?;
    server.world.unregisterNick(worldIdFromClient(ghost_id));
    server.world.unregisterNick(worldIdFromClient(survivor_id));
    try ghost.session.setNick("Shared");
    try survivor.session.setNick("Shared");

    const exact_token = server.sessions.resumeHandleForClient(
        account,
        monitorIdFromClient(primary_id),
    ).?.token;
    try std.testing.expect(server.sessions.joinTokenGroup(
        account,
        monitorIdFromClient(ghost_id),
        exact_token,
    ));
    const survivor_token = server.sessions.resumeHandleForClient(
        account,
        monitorIdFromClient(survivor_id),
    ).?.token;
    try std.testing.expect(!std.crypto.timing_safe.eql(
        sessions_mod.Token,
        exact_token,
        survivor_token,
    ));

    try server.world.restoreMember("#project-absent", worldIdFromClient(primary_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#project-absent", worldIdFromClient(ghost_id), world_model.MemberModes.empty());
    try server.world.restoreMember("#project-absent", worldIdFromClient(survivor_id), world_model.MemberModes.empty());
    try std.testing.expect(server.sessions.markDetached(account, monitorIdFromClient(ghost_id)));
    for ([_]*ConnState{ primary, ghost, survivor }) |conn| {
        conn.send_len = 0;
        conn.send_offset = 0;
    }

    const projection = try server.sessions.armTokenLocalChannelProjection(
        exact_token,
        "#project-absent",
        false,
        0,
    );
    try std.testing.expect(!server.projectLocalChannelProjection(.{
        .token = exact_token,
        .projection = projection,
    }, false));

    try std.testing.expect(!server.world.isMember("#project-absent", worldIdFromClient(primary_id)));
    try std.testing.expect(server.world.isMember("#project-absent", worldIdFromClient(ghost_id)));
    try std.testing.expect(server.world.isMember("#project-absent", worldIdFromClient(survivor_id)));
    try std.testing.expectEqual(projection.generation, server.sessions.tokenLocalChannelProjection(
        exact_token,
        "#PROJECT-ABSENT",
    ).?.generation);
    try std.testing.expectEqual(@as(usize, 0), primary.send_len);
    try std.testing.expectEqual(@as(usize, 0), ghost.send_len);
    try std.testing.expectEqual(@as(usize, 0), survivor.send_len);
}

test "session-foundation locked rows: folded exact owner survives while a current detached sibling is excluded" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;

    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const owner_id = try addTestLocalClient(&server, "Shared", "Alice");
    const detached_id = try addTestLocalClient(&server, "Retired", "ALICE");
    const claimant_id = try addTestLocalClient(&server, "Device", "aLiCe");
    const claimant = server.connFor(claimant_id).?;
    const target = server.sessions.resumeHandleForClient(
        "Alice",
        monitorIdFromClient(owner_id),
    ).?;
    try std.testing.expect(server.sessions.joinTokenGroup(
        "ALICE",
        monitorIdFromClient(detached_id),
        target.token,
    ));
    try std.testing.expect(server.sessions.markDetached(
        "ALICE",
        monitorIdFromClient(detached_id),
    ));
    server.world.removeClient(worldIdFromClient(detached_id));
    try server.world.restoreMember(
        "#folded-current",
        worldIdFromClient(owner_id),
        world_model.MemberModes.fromModes(&.{.op}),
    );

    const snapshot = migration_relay.Snapshot{
        .nick = "Shared",
        .umodes = "+i",
        .channels = &.{"#folded-current"},
        .channel_modes = &.{world_model.MemberModes.fromModes(&.{.voice}).bits},
        .account = "ALICE",
    };
    claimant.send_len = 0;
    claimant.send_offset = 0;
    try std.testing.expect(server.restoreAndBindMigrationSnapshot(
        claimant_id,
        claimant,
        "aLiCe",
        target.token,
        .join_existing,
        &snapshot,
    ));

    // The attached exact owner in another folded map keeps the rendered nick.
    // The detached exact sibling is part of the frozen row image but must not be
    // treated as a live World participant.
    try std.testing.expectEqual(
        @as(?world_model.ClientId, worldIdFromClient(owner_id)),
        server.world.findNick("Shared"),
    );
    try std.testing.expect(server.world.nickOf(worldIdFromClient(claimant_id)) == null);
    try std.testing.expect(server.world.nickOf(worldIdFromClient(detached_id)) == null);
    try std.testing.expect(server.world.isMember("#folded-current", worldIdFromClient(owner_id)));
    try std.testing.expect(server.world.isMember("#folded-current", worldIdFromClient(claimant_id)));
    try std.testing.expect(!server.world.isMember("#folded-current", worldIdFromClient(detached_id)));
    try std.testing.expectEqual(
        world_model.MemberModes.fromModes(&.{.voice}).bits,
        server.world.memberModes("#folded-current", worldIdFromClient(claimant_id)).?.bits,
    );
    try std.testing.expectEqualStrings("Shared", claimant.session.displayName());
    const rebound = server.sessions.resumeHandleForClient(
        "aLiCe",
        monitorIdFromClient(claimant_id),
    ).?;
    try std.testing.expectEqualSlices(u8, &target.token, &rebound.token);
    const detached_rows = try server.sessions.copySessionsAlloc(server.allocator, "ALICE");
    defer server.allocator.free(detached_rows);
    try std.testing.expectEqual(@as(usize, 1), detached_rows.len);
    try std.testing.expect(!detached_rows[0].attached);
    try std.testing.expectEqualSlices(u8, &target.token, &detached_rows[0].token);
}

test "session-foundation locked rows: duplicate client across folded accounts fails closed and clean retry succeeds" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;

    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const owner_id = try addTestLocalClient(&server, "Owner", "Dupe");
    const claimant_id = try addTestLocalClient(&server, "Claimant", "dupe");
    const claimant = server.connFor(claimant_id).?;
    const target = server.sessions.resumeHandleForClient(
        "Dupe",
        monitorIdFromClient(owner_id),
    ).?;
    const prior = server.sessions.resumeHandleForClient(
        "dupe",
        monitorIdFromClient(claimant_id),
    ).?;
    const conflicting: sessions_mod.Token = @splat(0xD7);
    _ = try server.sessions.attach(
        "DUPE",
        monitorIdFromClient(claimant_id),
        conflicting,
        3,
    );
    const snapshot = migration_relay.Snapshot{
        .nick = "Owner",
        .umodes = "+i",
        .channels = &.{"#dupe-safe"},
        .channel_modes = &.{0},
        .account = "dupe",
    };

    const claimant_send_len = claimant.send_len;
    const claimant_send_offset = claimant.send_offset;
    try std.testing.expect(!server.restoreAndBindMigrationSnapshot(
        claimant_id,
        claimant,
        "dupe",
        target.token,
        .join_existing,
        &snapshot,
    ));
    try std.testing.expectEqualStrings("Claimant", claimant.session.displayName());
    try std.testing.expectEqual(
        @as(?world_model.ClientId, worldIdFromClient(claimant_id)),
        server.world.findNick("Claimant"),
    );
    try std.testing.expectEqual(
        @as(?world_model.ClientId, worldIdFromClient(owner_id)),
        server.world.findNick("Owner"),
    );
    try std.testing.expect(!server.world.channelExists("#dupe-safe"));
    try std.testing.expectEqual(claimant_send_len, claimant.send_len);
    try std.testing.expectEqual(claimant_send_offset, claimant.send_offset);
    const retained = server.sessions.resumeHandleForClient(
        "dupe",
        monitorIdFromClient(claimant_id),
    ).?;
    try std.testing.expectEqualSlices(u8, &prior.token, &retained.token);

    // Removing the corrupt duplicate and retrying also proves the failed ticket
    // released its exclusive lock and left every authority row reusable.
    try std.testing.expect(server.sessions.remove("DUPE", monitorIdFromClient(claimant_id)));
    try std.testing.expect(server.restoreAndBindMigrationSnapshot(
        claimant_id,
        claimant,
        "dupe",
        target.token,
        .join_existing,
        &snapshot,
    ));
    const rebound = server.sessions.resumeHandleForClient(
        "dupe",
        monitorIdFromClient(claimant_id),
    ).?;
    try std.testing.expectEqualSlices(u8, &target.token, &rebound.token);
}

test "session-foundation locked rows: retained ticket blocks detach drift until abort" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;

    var server = Server.init(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();

    const account = "ticket-drift";
    const owner_id = try addTestLocalClient(&server, "Owner", account);
    const claimant_id = try addTestLocalClient(&server, "Claimant", account);
    const target = server.sessions.resumeHandleForClient(
        account,
        monitorIdFromClient(owner_id),
    ).?;
    var prepared = server.sessions.prepareTokenBind(
        account,
        monitorIdFromClient(claimant_id),
        target.token,
        .join_existing,
    ) orelse return error.TestUnexpectedResult;
    defer prepared.deinit();
    try std.testing.expectEqual(@as(usize, 2), prepared.accountRows().len);

    const DetachCtx = struct {
        store: *sessions_mod.SessionStore,
        account: []const u8,
        client: sessions_mod.ClientId,
        started: *std.atomic.Value(bool),
        done: *std.atomic.Value(bool),
        changed: *std.atomic.Value(bool),

        fn run(ctx: *@This()) void {
            ctx.started.store(true, .release);
            const result = ctx.store.markDetached(ctx.account, ctx.client);
            ctx.changed.store(result, .release);
            ctx.done.store(true, .release);
        }
    };
    var started = std.atomic.Value(bool).init(false);
    var done = std.atomic.Value(bool).init(false);
    var changed = std.atomic.Value(bool).init(false);
    var ctx = DetachCtx{
        .store = &server.sessions,
        .account = account,
        .client = monitorIdFromClient(owner_id),
        .started = &started,
        .done = &done,
        .changed = &changed,
    };
    var thread = std.Thread.spawn(.{}, DetachCtx.run, .{&ctx}) catch return error.SkipZigTest;
    var joined = false;
    defer if (!joined) {
        prepared.abort();
        thread.join();
    };

    var spins: usize = 0;
    while (!started.load(.acquire) and spins < 100_000) : (spins += 1)
        std.Thread.yield() catch {};
    try std.testing.expect(started.load(.acquire));
    try std.testing.expect(!done.load(.acquire));
    // The snapshot cannot drift while World/output planning consumes it.
    try std.testing.expect(prepared.accountRows()[0].attached);

    prepared.abort();
    thread.join();
    joined = true;
    try std.testing.expect(done.load(.acquire));
    try std.testing.expect(changed.load(.acquire));
    const rows = try server.sessions.copySessionsAlloc(server.allocator, account);
    defer server.allocator.free(rows);
    var owner_attached = true;
    for (rows) |row| if (row.client == monitorIdFromClient(owner_id)) {
        owner_attached = row.attached;
    };
    try std.testing.expect(!owner_attached);
}

test "session-foundation locked rows: capture OOM is failure-atomic and retryable through RESUME" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;

    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var server = Server.init(failing.allocator(), .{
        .host = "127.0.0.1",
        .port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer {
        failing.fail_index = std.math.maxInt(usize);
        server.deinit();
    }

    const account = "row-alloc";
    const owner_id = try addTestLocalClient(&server, "Owner", account);
    const claimant_id = try addTestLocalClient(&server, "Claimant", account);
    const claimant = server.connFor(claimant_id).?;
    const target = server.sessions.resumeHandleForClient(
        account,
        monitorIdFromClient(owner_id),
    ).?;
    const prior = server.sessions.resumeHandleForClient(
        account,
        monitorIdFromClient(claimant_id),
    ).?;
    const snapshot = migration_relay.Snapshot{
        .nick = "Owner",
        .umodes = "+i",
        .channels = &.{"#row-alloc"},
        .channel_modes = &.{0},
        .account = account,
    };

    const claimant_send_len = claimant.send_len;
    const claimant_send_offset = claimant.send_offset;
    failing.fail_index = failing.alloc_index;
    try std.testing.expect(!server.restoreAndBindMigrationSnapshot(
        claimant_id,
        claimant,
        account,
        target.token,
        .join_existing,
        &snapshot,
    ));
    failing.fail_index = std.math.maxInt(usize);
    try std.testing.expect(failing.has_induced_failure);
    try std.testing.expectEqualStrings("Claimant", claimant.session.displayName());
    try std.testing.expectEqual(
        @as(?world_model.ClientId, worldIdFromClient(claimant_id)),
        server.world.findNick("Claimant"),
    );
    try std.testing.expect(!server.world.channelExists("#row-alloc"));
    try std.testing.expectEqual(claimant_send_len, claimant.send_len);
    try std.testing.expectEqual(claimant_send_offset, claimant.send_offset);
    const retained = server.sessions.resumeHandleForClient(
        account,
        monitorIdFromClient(claimant_id),
    ).?;
    try std.testing.expectEqualSlices(u8, &prior.token, &retained.token);

    try std.testing.expect(server.restoreAndBindMigrationSnapshot(
        claimant_id,
        claimant,
        account,
        target.token,
        .join_existing,
        &snapshot,
    ));
    const rebound = server.sessions.resumeHandleForClient(
        account,
        monitorIdFromClient(claimant_id),
    ).?;
    try std.testing.expectEqualSlices(u8, &target.token, &rebound.token);
    try std.testing.expect(server.world.isMember("#row-alloc", worldIdFromClient(claimant_id)));
}

test "OCG2 server runtime requires an exact paired monotonic origin" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(
        std.testing.allocator,
        std.testing.io,
        tmp.dir,
        "server-ocg2-clock-pair.wal",
    );
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    const runtime = try ocg2_runtime_mod.createObserve(std.testing.allocator, &services);
    defer ocg2_runtime_mod.destroy(runtime);

    const missing_origin = try std.testing.allocator.create(Server);
    defer std.testing.allocator.destroy(missing_origin);
    try std.testing.expectError(error.InvalidOcg2RuntimeClock, missing_origin.initInPlace(
        std.testing.allocator,
        .{ .host = "127.0.0.1", .port = 0, .ocg2_runtime = runtime },
    ));

    const server_missing_runtime = try std.testing.allocator.create(Server);
    defer std.testing.allocator.destroy(server_missing_runtime);
    try std.testing.expectError(error.InvalidOcg2RuntimeClock, server_missing_runtime.initInPlace(
        std.testing.allocator,
        .{ .host = "127.0.0.1", .port = 0, .ocg2_runtime_monotonic_origin_ms = 1 },
    ));
}

test "OCG2 REHASH reports every restart-only authority intent" {
    try std.testing.expect(!LinuxServer.ocg2RehashHasRestartOnlyIntent(false, .{}));
    try std.testing.expect(LinuxServer.ocg2RehashHasRestartOnlyIntent(true, .{}));
    try std.testing.expect(LinuxServer.ocg2RehashHasRestartOnlyIntent(false, .{ .enabled = true }));
    try std.testing.expect(LinuxServer.ocg2RehashHasRestartOnlyIntent(false, .{ .projection_enabled = true }));
    try std.testing.expect(LinuxServer.ocg2RehashHasRestartOnlyIntent(false, .{ .minting_enabled = true }));
    try std.testing.expect(LinuxServer.ocg2RehashHasRestartOnlyIntent(false, .{ .authority_node_id = 1 }));
    try std.testing.expect(LinuxServer.ocg2RehashHasRestartOnlyIntent(false, .{
        .authority_public_key = @as([crypto_sign.public_key_len]u8, @splat(1)),
    }));
    try std.testing.expect(!LinuxServer.ocg2RehashHasUnsupportedRuntimeMode(.{}));
    try std.testing.expect(!LinuxServer.ocg2RehashHasUnsupportedRuntimeMode(.{ .enabled = true }));
    try std.testing.expect(!LinuxServer.ocg2RehashHasUnsupportedRuntimeMode(.{ .projection_enabled = true }));
    try std.testing.expect(!LinuxServer.ocg2RehashHasUnsupportedRuntimeMode(.{ .minting_enabled = true }));
}

test "OCG2 server runtime is inert by default and reactor zero owns terminal cadence" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    defer current_reactor = null;

    const defaults = Config{ .host = "127.0.0.1", .port = 0 };
    try std.testing.expectEqual(@as(?*ocg2_runtime_mod.Runtime, null), defaults.ocg2_runtime);
    try std.testing.expectEqual(@as(?u64, null), defaults.ocg2_runtime_monotonic_origin_ms);

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var store = try services_mod.OroStore.open(
        std.testing.allocator,
        std.testing.io,
        tmp.dir,
        "server-ocg2-terminal.wal",
    );
    defer store.deinit();
    var services = services_mod.Services.init(&store, null);
    const runtime = try ocg2_runtime_mod.createObserve(std.testing.allocator, &services);
    defer ocg2_runtime_mod.destroy(runtime);
    try std.testing.expectEqual(
        ocg2_runtime_mod.Failure.authority_disabled,
        runtime.tick(1, 0).failed,
    );
    const origin_ms: u64 = @intCast(@max(@as(i64, 0), platform.monotonicMillis()));

    const server = createTestServer(std.testing.allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .num_shards = 2,
        .account_services = &services,
        .ocg2_runtime = runtime,
        .ocg2_runtime_monotonic_origin_ms = origin_ms,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable, error.AddressInUse => return error.SkipZigTest,
        else => return err,
    };
    defer {
        server.deinit();
        std.testing.allocator.destroy(server);
    }
    if (server.reactors.len < 2) return error.SkipZigTest;

    current_reactor = &server.reactors[1];
    try std.testing.expect(!server.tickOcg2Runtime());
    try std.testing.expect(!server.ocg2_runtime_terminal_logged);

    current_reactor = &server.reactors[0];
    try std.testing.expect(server.tickOcg2Runtime());
    try std.testing.expect(server.ocg2_runtime_terminal_logged);
    try std.testing.expect(!server.tickOcg2Runtime());
}

test "GAP-P0c reaction tally is readable after a late subscribe" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    defer current_reactor = null;
    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const channel = "#p0c";
    const target = "msg-stable-1";
    const alice = try addTestLocalClient(&server, "Alice", null);
    const bob = try addTestLocalClient(&server, "Bob", null);
    const alice_conn = server.connFor(alice).?;
    const bob_conn = server.connFor(bob).?;

    // The shipped writer must store the tally while the subscriber set is empty.
    try std.testing.expectEqual(@as(usize, 0), server.activity_subs.subscribers(channel).len);
    try server.pushReactionActivity(alice, alice_conn, channel, "fire", target, .add);
    try server.pushReactionActivity(bob, bob_conn, channel, "fire", target, .add);
    try server.pushReactionActivity(alice, alice_conn, channel, "fire", target, .remove);
    try std.testing.expectEqual(@as(usize, 0), server.activity_subs.subscribers(channel).len);

    const late = try addTestLocalClient(&server, "Late", null);
    const late_conn = server.connFor(late).?;
    _ = try server.world.join(channel, worldIdFromClient(late));
    var denied = try irc_line.parseLine("ACTIVITY TALLY #p0c msg-stable-1");
    try server.handleActivity(late, late_conn, &denied);
    try expectContains(late_conn.send_buf[0..late_conn.send_len], "ACTIVITY: not subscribed");

    late_conn.send_len = 0;
    var sub = try irc_line.parseLine("ACTIVITY SUBSCRIBE #p0c");
    try server.handleActivity(late, late_conn, &sub);
    late_conn.send_len = 0;
    var query = try irc_line.parseLine("ACTIVITY TALLY #p0c msg-stable-1");
    try server.handleActivity(late, late_conn, &query);
    const out = late_conn.send_buf[0..late_conn.send_len];
    try expectContains(out, "target=msg-stable-1 fire=1");
    std.debug.print("GAP-P0c branch=reaction tally a late subscriber can read\n", .{});
}

test "GAP-O9 DIE, RESTART, and mesh bans wait for a second operator" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    var sim = reactor_mod.SimReactor.init(1_000_000);
    var shutdown = std.atomic.Value(bool).init(true);
    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .server_name = "two-person.test",
        .crypto_io = std.testing.io,
        .reactor = sim.reactor(),
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer {
        current_reactor = null;
        server.deinit();
    }
    current_reactor = &server.reactors[0];
    server.shutdown = &shutdown;

    var op1 = ConnState.init(-1);
    var op2 = ConnState.init(-1);
    var op3 = ConnState.init(-1);
    op1.overflow_allocator = allocator;
    op2.overflow_allocator = allocator;
    op3.overflow_allocator = allocator;
    op1.send_armed = true;
    op2.send_armed = true;
    op3.send_armed = true;
    defer if (op1.send_overflow.capacity > 0) op1.send_overflow.deinit(allocator);
    defer if (op2.send_overflow.capacity > 0) op2.send_overflow.deinit(allocator);
    defer if (op3.send_overflow.capacity > 0) op3.send_overflow.deinit(allocator);

    const privs = oper_mod.OperPrivileges.initMany(&.{ .server_shutdown, .server_restart, .client_moderate });
    try op1.session.setNick("op1");
    try op2.session.setNick("op2");
    try op3.session.setNick("op3");
    op1.session.is_oper = true;
    op2.session.is_oper = true;
    op3.session.is_oper = true;
    op1.session.oper_priv = privs;
    op2.session.oper_priv = privs;
    op3.session.oper_priv = privs;

    const AuditScan = struct {
        fn count(audit: *const svc_operaudit.OperAudit, action: svc_operaudit.Action, reason: []const u8) usize {
            var n: usize = 0;
            var i: usize = 0;
            while (i < audit.len()) : (i += 1) {
                const row = audit.at(i).?;
                if (row.action == action and std.mem.eql(u8, row.reason, reason)) n += 1;
            }
            return n;
        }
    };

    // Flag off: DIE stops the process and writes no die audit.
    const before_die = server.oper_audit.len();
    try server.handleDie(&op1, "DIE");
    try std.testing.expect(!shutdown.load(.acquire));
    try std.testing.expectEqual(before_die, server.oper_audit.len());
    try std.testing.expect(server.two_person_pending == null);
    shutdown.store(true, .release);

    // Flag off: a mesh ban installs on the first oper.
    try server.addWardLive(&op1, .address, "203.0.113.9", .mesh, .refuse, 0, "net", .ward_add);
    try std.testing.expect(server.warden.find(.address, "203.0.113.9") != null);
    try std.testing.expectEqual(@as(usize, 0), AuditScan.count(&server.oper_audit, .ward_add, "two-person approval"));

    server.config.two_person_rule = true;

    // RESTART waits. The test must return before upgradeListenerOnly execs.
    const before_restart = server.oper_audit.len();
    try server.handleDie(&op1, "RESTART");
    try std.testing.expect(shutdown.load(.acquire));
    try std.testing.expect(server.two_person_pending != null);
    try std.testing.expectEqual(TwoPersonKind.restart, server.two_person_pending.?.kind);
    try std.testing.expectEqual(before_restart + 1, server.oper_audit.len());
    const opened_at = server.two_person_pending.?.at_ms;

    // The same oper does not confirm and does not extend the window.
    sim.advance(1_000);
    try server.handleDie(&op1, "RESTART");
    try std.testing.expect(shutdown.load(.acquire));
    try std.testing.expectEqual(opened_at, server.two_person_pending.?.at_ms);
    try std.testing.expectEqual(before_restart + 1, server.oper_audit.len());

    // DIE does not confirm a pending RESTART. It replaces that approval.
    try server.handleDie(&op2, "DIE");
    try std.testing.expect(shutdown.load(.acquire));
    try std.testing.expectEqual(TwoPersonKind.die, server.two_person_pending.?.kind);
    try std.testing.expectEqualStrings("op2", server.two_person_pending.?.identitySlice());

    // A second distinct oper confirms DIE. The action is the extra audit row.
    try server.handleDie(&op1, "DIE");
    try std.testing.expect(!shutdown.load(.acquire));
    try std.testing.expect(server.two_person_pending == null);
    try std.testing.expectEqual(@as(usize, 2), AuditScan.count(&server.oper_audit, .die, "two-person approval"));
    try std.testing.expectEqual(@as(usize, 1), AuditScan.count(&server.oper_audit, .die, "two-person action"));
    try std.testing.expectEqual(@as(usize, 1), AuditScan.count(&server.oper_audit, .restart, "two-person approval"));
    shutdown.store(true, .release);

    // Mesh ban: logged-in account is the identity, so a second nick on the
    // same account is not a second operator.
    try op1.session.setNick("alpha-nick");
    op1.session.loginAs("alpha");
    op1.session.is_oper = true;
    op1.session.oper_priv = privs;
    try op2.session.setNick("alpha-other");
    op2.session.loginAs("alpha");
    op2.session.is_oper = true;
    op2.session.oper_priv = privs;
    try server.addWardLive(&op1, .host, "evil.example", .mesh, .expel, 0, "raid", .ward_add);
    try std.testing.expect(server.warden.find(.host, "evil.example") == null);
    try server.addWardLive(&op2, .host, "evil.example", .mesh, .expel, 0, "raid", .ward_add);
    try std.testing.expect(server.warden.find(.host, "evil.example") == null);
    try std.testing.expect(server.two_person_pending != null);

    try op3.session.setNick("beta-nick");
    op3.session.loginAs("beta");
    op3.session.is_oper = true;
    op3.session.oper_priv = privs;
    try server.addWardLive(&op3, .host, "evil.example", .mesh, .expel, 0, "raid", .ward_add);
    const installed = server.warden.find(.host, "evil.example") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(warden.Scope.mesh, installed.scope);
    try std.testing.expect(server.two_person_pending == null);

    // Node scope stays single-oper while the flag is on.
    const approvals_before_node = AuditScan.count(&server.oper_audit, .ward_add, "two-person approval");
    try server.addWardLive(&op1, .host, "local.example", .node, .expel, 0, "local", .ward_add);
    const local = server.warden.find(.host, "local.example") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(warden.Scope.node, local.scope);
    try std.testing.expectEqual(approvals_before_node, AuditScan.count(&server.oper_audit, .ward_add, "two-person approval"));

    // Past the window, the other oper's repeat is a new proposal, not a confirm.
    try server.addWardLive(&op1, .address, "198.51.100.7", .mesh, .refuse, 0, "later", .ward_add);
    try std.testing.expect(server.warden.find(.address, "198.51.100.7") == null);
    const expiry_at = server.two_person_pending.?.at_ms;
    const approvals_at_proposal = AuditScan.count(&server.oper_audit, .ward_add, "two-person approval");
    sim.advance(60_001);
    try server.addWardLive(&op3, .address, "198.51.100.7", .mesh, .refuse, 0, "later", .ward_add);
    try std.testing.expect(server.warden.find(.address, "198.51.100.7") == null);
    try std.testing.expect(server.two_person_pending.?.at_ms != expiry_at);
    try std.testing.expectEqual(approvals_at_proposal + 1, AuditScan.count(&server.oper_audit, .ward_add, "two-person approval"));
    try server.addWardLive(&op1, .address, "198.51.100.7", .mesh, .refuse, 0, "later", .ward_add);
    try std.testing.expect(server.warden.find(.address, "198.51.100.7") != null);

    // Mesh delete waits, then the second oper removes it.
    try server.deleteWardLive(&op1, .address, "198.51.100.7");
    try std.testing.expect(server.warden.find(.address, "198.51.100.7") != null);
    try server.deleteWardLive(&op3, .address, "198.51.100.7");
    try std.testing.expect(server.warden.find(.address, "198.51.100.7") == null);
    try std.testing.expectEqual(@as(usize, 2), AuditScan.count(&server.oper_audit, .ward_del, "two-person approval"));
    try std.testing.expectEqual(@as(usize, 1), AuditScan.count(&server.oper_audit, .ward_del, "removed"));

    std.debug.print("GAP-O9 branch=two-person rule waits for a second distinct operator; flag off is unchanged\n", .{});
}

test "GAP-O10 policy rollback restores the last ward, filter, class, and ban generation" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    var ident = try node_identity.fromSeed(@as([32]u8, @splat(0x51)), "policy-rollback.test");
    defer ident.deinit();
    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .server_name = "policy.test",
        .node_identity = &ident,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer {
        current_reactor = null;
        server.deinit();
    }
    current_reactor = &server.reactors[0];

    const id = try addTestLocalClient(&server, "op1", null);
    const conn = server.connFor(id).?;
    conn.session.is_oper = true;
    conn.session.oper_priv = oper_mod.OperPrivileges.initMany(&.{ .client_moderate, .server_admin });

    const expectProof = struct {
        fn check(audit: *const svc_operaudit.OperAudit, action: svc_operaudit.Action, reason: []const u8, version: u32) !void {
            var i = audit.len();
            while (i > 0) {
                i -= 1;
                const row = audit.at(i).?;
                if (row.action == action and std.mem.eql(u8, row.reason, reason)) {
                    try std.testing.expectEqual(version, row.proof_policy_version);
                    try std.testing.expect(LinuxServer.auditProofVerified(row));
                    return;
                }
            }
            return error.TestUnexpectedResult;
        }
    }.check;

    try std.testing.expectEqual(@as(u32, 1), server.policy_gen_ward);
    try std.testing.expectEqual(@as(u32, 1), server.policy_gen_filter);
    try std.testing.expectEqual(@as(u32, 1), server.policy_gen_class);
    try std.testing.expectEqual(@as(u32, 1), server.policy_gen_ban);

    try server.addWardLive(conn, .host, "evil.example", .node, .expel, 0, "policy-ward", .ward_add);
    try std.testing.expect(server.warden.find(.host, "evil.example") != null);
    try std.testing.expectEqual(@as(u32, 2), server.policy_gen_ward);
    try expectProof(&server.oper_audit, .ward_add, "policy-ward", 2);

    var rollback = try irc_line.parseLine("POLICY ROLLBACK");
    try server.handlePolicy(conn, &rollback);
    try std.testing.expect(server.warden.find(.host, "evil.example") == null);
    try std.testing.expectEqual(@as(u32, 1), server.policy_gen_ward);
    try expectProof(&server.oper_audit, .other, "policy rollback", 1);

    conn.send_len = 0;
    try server.handlePolicy(conn, &rollback);
    try std.testing.expect(std.mem.indexOf(u8, conn.send_buf[0..conn.send_len], "nothing to roll back") != null);
    try std.testing.expectEqual(@as(u32, 1), server.policy_gen_ward);

    var filter_add = try irc_line.parseLine("FILTER ADD spamword");
    try server.handleFilter(conn, &filter_add);
    try std.testing.expect(server.content_filter.matches("buy spamword now"));
    try std.testing.expectEqual(@as(u32, 2), server.policy_gen_filter);
    try expectProof(&server.oper_audit, .other, "filter add", 2);
    try server.handlePolicy(conn, &rollback);
    try std.testing.expect(!server.content_filter.matches("buy spamword now"));
    try std.testing.expectEqual(@as(u32, 1), server.policy_gen_filter);
    try expectProof(&server.oper_audit, .other, "policy rollback", 1);

    var builder = conn_class.Builder.init(allocator);
    defer builder.deinit();
    try builder.add(.{ .name = "vip", .policy = .{ .max_per_account = 9 } });
    server.installClassRegistry(try builder.finish());
    try std.testing.expectEqual(@as(u32, 9), server.config.class_registry.?.byName("vip").?.policy.max_per_account);
    try std.testing.expectEqual(@as(u32, 2), server.policy_gen_class);
    try expectProof(&server.oper_audit, .other, "class replace", 2);
    try server.handlePolicy(conn, &rollback);
    try std.testing.expect(server.config.class_registry == null);
    try std.testing.expectEqual(@as(u32, 1), server.policy_gen_class);

    _ = try server.world.join("#pol", worldIdFromClient(id));
    var mode = try irc_line.parseLine("MODE #pol +b *!*@banned.example");
    try server.handleMode(id, conn, &mode);
    const bans = server.world.bansOf("#pol") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), bans.len);
    try std.testing.expectEqualStrings("*!*@banned.example", bans[0].mask);
    try std.testing.expectEqual(@as(u32, 2), server.policy_gen_ban);
    try expectProof(&server.oper_audit, .other, "ban change", 2);
    try server.handlePolicy(conn, &rollback);
    const after = server.world.bansOf("#pol") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 0), after.len);
    try std.testing.expectEqual(@as(u32, 1), server.policy_gen_ban);
    try expectProof(&server.oper_audit, .other, "policy rollback", 1);

    std.debug.print("GAP-O10 branch=policy rollback restores the last numbered generation and the proof version matches it\n", .{});
}

fn appendRaw(buf: []u8, n: *usize, text: []const u8) bool {
    if (n.* + text.len > buf.len) return false;
    @memcpy(buf[n.*..][0..text.len], text);
    n.* += text.len;
    return true;
}

fn appendJsonQuoted(buf: []u8, n: *usize, text: []const u8) bool {
    if (!appendRaw(buf, n, "\"")) return false;
    const hex = "0123456789abcdef";
    for (text) |c| {
        if (c == '"') {
            if (!appendRaw(buf, n, "\\\"")) return false;
        } else if (c == '\\') {
            if (!appendRaw(buf, n, "\\\\")) return false;
        } else if (c == '\n') {
            if (!appendRaw(buf, n, "\\n")) return false;
        } else if (c == '\r') {
            if (!appendRaw(buf, n, "\\r")) return false;
        } else if (c < 0x20) {
            const piece = [_]u8{ '\\', 'u', '0', '0', hex[c >> 4], hex[c & 0xf] };
            if (!appendRaw(buf, n, &piece)) return false;
        } else {
            if (n.* >= buf.len) return false;
            buf[n.*] = c;
            n.* += 1;
        }
    }
    return appendRaw(buf, n, "\"");
}

fn formatOutboundBody(
    buf: []u8,
    category: event_spine.EventCategory,
    severity: event_spine.EventSeverity,
    origin: []const u8,
    message: []const u8,
) ?[]const u8 {
    var n: usize = 0;
    if (!appendRaw(buf, &n, "{\"category\":")) return null;
    if (!appendJsonQuoted(buf, &n, category.code())) return null;
    if (!appendRaw(buf, &n, ",\"severity\":")) return null;
    if (!appendJsonQuoted(buf, &n, severity.token())) return null;
    if (!appendRaw(buf, &n, ",\"server\":")) return null;
    if (!appendJsonQuoted(buf, &n, origin)) return null;
    if (!appendRaw(buf, &n, ",\"message\":")) return null;
    if (!appendJsonQuoted(buf, &n, message)) return null;
    if (!appendRaw(buf, &n, "}")) return null;
    return buf[0..n];
}

fn outboundSignature(secret: []const u8, body: []const u8, out: *[71]u8) []const u8 {
    const HmacSha256 = std.crypto.auth.hmac.sha2.HmacSha256;
    var mac: [HmacSha256.mac_length]u8 = undefined;
    HmacSha256.create(&mac, body, secret);
    const prefix = "sha256=";
    @memcpy(out[0..prefix.len], prefix);
    const hex = "0123456789abcdef";
    for (mac, 0..) |b, i| {
        out[prefix.len + i * 2] = hex[b >> 4];
        out[prefix.len + i * 2 + 1] = hex[b & 0xf];
    }
    return out;
}

fn outboundNormalizeHost(raw: []const u8, buf: []u8) []const u8 {
    var host = std.mem.trim(u8, raw, " \t");
    if (host.len >= 2 and host[0] == '[') {
        if (std.mem.indexOfScalar(u8, host, ']')) |end| host = host[1..end];
    }
    if (std.mem.indexOfScalar(u8, host, '%')) |zone| host = host[0..zone];
    if (host.len == 0 or host.len > buf.len) return "";
    for (host, 0..) |c, i| buf[i] = std.ascii.toLower(c);
    return buf[0..host.len];
}

fn outboundAddrPrivate(addr: std.Io.net.IpAddress) bool {
    return webpush_mod.isDisallowedPushAddr(addr);
}

fn outboundHostIsHostname(raw: []const u8, port: u16) bool {
    var host_buf: [256]u8 = undefined;
    const host = outboundNormalizeHost(raw, &host_buf);
    if (host.len == 0) return false;
    _ = std.Io.net.IpAddress.parse(host, port) catch return true;
    return false;
}

fn shouldWindowsPinnedAAAAFallback(addr: std.Io.net.IpAddress, hostname: bool, connected: bool, err: anyerror) bool {
    return builtin.os.tag == .windows and hostname and addr == .ip4 and !connected and
        (err == error.ConnectFailed or err == error.ConnectTimeout);
}

fn pinOutboundLoopbackForTest(_: []const u8, port: u16) anyerror!std.Io.net.IpAddress {
    return .{ .ip4 = .{ .bytes = .{ 127, 0, 0, 1 }, .port = port } };
}

fn outboundHostPrivate(raw: []const u8) bool {
    var buf: [256]u8 = undefined;
    const host = outboundNormalizeHost(raw, &buf);
    if (host.len == 0) return true;
    if (std.ascii.eqlIgnoreCase(host, "localhost") or std.ascii.eqlIgnoreCase(host, "localhost.")) return true;
    const parsed = std.Io.net.IpAddress.parse(host, 0) catch return false;
    return outboundAddrPrivate(parsed);
}

fn parseOutboundCategories(raw: []const u8) ?event_spine.CategoryMask {
    var mask = event_spine.CategoryMask.empty();
    var any = false;
    var it = std.mem.splitScalar(u8, raw, ',');
    while (it.next()) |part| {
        const tok = std.mem.trim(u8, part, " \t");
        if (tok.len == 0) return null;
        if (std.ascii.eqlIgnoreCase(tok, "ALL")) {
            mask = event_spine.CategoryMask.all();
            any = true;
            continue;
        }
        const cat = event_spine.EventCategory.parse(tok) orelse return null;
        mask.add(cat);
        any = true;
    }
    if (!any or mask.isEmpty()) return null;
    return mask;
}

fn outboundCategoryText(mask: event_spine.CategoryMask, buf: []u8) []const u8 {
    var n: usize = 0;
    inline for (@typeInfo(event_spine.EventCategory).@"enum".field_names) |field_name| {
        const cat: event_spine.EventCategory = @field(event_spine.EventCategory, field_name);
        if (mask.contains(cat)) {
            const name = cat.code();
            if (n != 0 and n < buf.len) {
                buf[n] = ',';
                n += 1;
            }
            if (n + name.len <= buf.len) {
                @memcpy(buf[n..][0..name.len], name);
                n += name.len;
            }
        }
    }
    return buf[0..n];
}

fn httpStatus2xx(resp: []const u8) bool {
    const sp = std.mem.indexOfScalar(u8, resp, ' ') orelse return false;
    if (sp + 4 > resp.len) return false;
    const code = std.fmt.parseInt(u16, resp[sp + 1 .. sp + 4], 10) catch return false;
    return code >= 200 and code < 300;
}

const BoundTcp = struct { fd: linux.fd_t, port: u16 };

fn bindLoopback(do_listen: bool) ServerError!BoundTcp {
    const fd = try socketTcp();
    errdefer closeFd(fd);
    var yes: u32 = 1;
    try setsockopt(fd, posix.SOL.SOCKET, posix.SO.REUSEADDR, std.mem.asBytes(&yes));
    const addr = posix.sockaddr.in{
        .port = 0,
        .addr = std.mem.nativeToBig(u32, 0x7f00_0001),
    };
    try bindSocket(fd, &addr);
    if (do_listen) {
        try listenSocket(fd, 16);
        // Readiness can disappear before the probe's accept. Keep that syscall
        // nonblocking on both targets; accepted Linux connections stay blocking.
        os_runtime.setNonblocking(fd) catch return error.Unexpected;
    }
    return .{ .fd = fd, .port = try socketPort(fd) };
}

const OutboundHookProbe = struct {
    stop: std.atomic.Value(bool) = .init(false),
    listen_fd: linux.fd_t = -1,
    mu: std.atomic.Mutex = .unlocked,
    hits: usize = 0,
    req: [2][1500]u8 = undefined,
    req_len: [2]usize = .{ 0, 0 },
    responses: [2]?[]const u8 = @splat(null),
    started: bool = false,
    thread: std.Thread = undefined,
    ready_pause: ?struct { arrived: *std.Io.Event, proceed: *std.Io.Event, returned: *std.Io.Event } = null,
    accept_wouldblock: bool = false,

    fn headerContentLength(head: []const u8) ?usize {
        var it = std.mem.splitScalar(u8, head, '\n');
        while (it.next()) |raw| {
            const line = std.mem.trim(u8, raw, " \t\r");
            const key = "content-length:";
            if (line.len < key.len) continue;
            if (!std.ascii.eqlIgnoreCase(line[0..key.len], key)) continue;
            const v = std.mem.trim(u8, line[key.len..], " \t");
            return std.fmt.parseInt(usize, v, 10) catch null;
        }
        return null;
    }

    fn serve(self: *OutboundHookProbe, fd: linux.fd_t) void {
        if (comptime builtin.os.tag == .openbsd) {
            // The native listener is nonblocking. This newly accepted probe
            // connection has no other owner; give its bounded reads/writes
            // blocking semantics rather than inheriting listener flags.
            const old = socket_system.fcntl(fd, posix.F.GETFL, @as(c_int, 0));
            if (posix.errno(old) != .SUCCESS) return;
            var flags: posix.O = @bitCast(@as(u32, @intCast(old)));
            flags.NONBLOCK = false;
            if (posix.errno(socket_system.fcntl(fd, posix.F.SETFL, @as(usize, @as(u32, @bitCast(flags))))) != .SUCCESS) return;
        }
        const tv = socket_system.timeval{ .sec = 1, .usec = 0 };
        if (posix.errno(socket_system.setsockopt(fd, posix.SOL.SOCKET, posix.SO.RCVTIMEO, std.mem.asBytes(&tv), @sizeOf(@TypeOf(tv)))) != .SUCCESS or
            posix.errno(socket_system.setsockopt(fd, posix.SOL.SOCKET, posix.SO.SNDTIMEO, std.mem.asBytes(&tv), @sizeOf(@TypeOf(tv)))) != .SUCCESS) return;
        var buf: [1500]u8 = undefined;
        var n: usize = 0;
        while (n < buf.len) {
            const rc = socket_system.read(fd, buf[n..].ptr, buf.len - n);
            switch (posix.errno(rc)) {
                .SUCCESS => {},
                .INTR => continue,
                else => break,
            }
            const got: usize = @intCast(rc);
            if (got == 0) break;
            n += got;
            if (std.mem.indexOf(u8, buf[0..n], "\r\n\r\n")) |head| {
                const want = headerContentLength(buf[0..head]) orelse 0;
                if (n >= head + 4 + want) break;
            }
        }
        lockSpin(&self.mu);
        const hit = self.hits;
        if (hit < self.req.len and n > 0) {
            const copy = @min(n, self.req[hit].len);
            @memcpy(self.req[hit][0..copy], buf[0..copy]);
            self.req_len[hit] = copy;
        }
        self.hits += 1;
        self.mu.unlock();
        const resp = if (hit < self.responses.len and self.responses[hit] != null)
            self.responses[hit].?
        else if (hit == 0)
            "HTTP/1.1 500 No\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
        else
            "HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
        var off: usize = 0;
        while (off < resp.len) {
            const rc = if (comptime builtin.os.tag == .openbsd)
                socket_system.send(fd, resp[off..].ptr, resp.len - off, posix.MSG.NOSIGNAL)
            else
                linux.sendto(fd, resp[off..].ptr, resp.len - off, posix.MSG.NOSIGNAL, null, 0);
            switch (posix.errno(rc)) {
                .SUCCESS => {},
                .INTR => continue,
                else => break,
            }
            const wrote: usize = @intCast(rc);
            if (wrote == 0) break;
            off += wrote;
        }
    }

    fn run(self: *OutboundHookProbe) void {
        defer if (self.ready_pause) |pause| pause.returned.set(std.testing.io);
        while (!self.stop.load(.acquire)) {
            var ready = [_]posix.pollfd{.{ .fd = self.listen_fd, .events = posix.POLL.IN, .revents = 0 }};
            const count = posix.poll(&ready, 100) catch return;
            if (self.stop.load(.acquire)) return;
            if (count == 0) continue;
            if (ready[0].revents & posix.POLL.IN == 0) return;
            if (self.ready_pause) |pause| {
                pause.arrived.set(std.testing.io);
                pause.proceed.waitUncancelable(std.testing.io);
            }
            const rc = if (comptime builtin.os.tag == .openbsd)
                socket_system.accept(self.listen_fd, null, null)
            else
                linux.accept4(self.listen_fd, null, null, posix.SOCK.CLOEXEC);
            switch (posix.errno(rc)) {
                .SUCCESS => {},
                .AGAIN => {
                    self.accept_wouldblock = true;
                    continue;
                },
                .INTR => continue,
                else => return,
            }
            const fd: linux.fd_t = @intCast(rc);
            if (comptime builtin.os.tag == .openbsd) os_runtime.setCloexec(fd, true) catch {
                closeFd(fd);
                continue;
            };
            self.serve(fd);
            closeFd(fd);
        }
    }
};

const ProbeCleanupObservation = struct { woke_and_joined: bool = false, hits: usize = 0 };

fn connectProbeWakeUntil(port: u16, deadline: std.Io.Clock.Timestamp) !linux.fd_t {
    const fd = try socketTcp();
    errdefer closeFd(fd);
    try os_runtime.setNonblocking(fd);
    const addr = try sockaddrIn("127.0.0.1", port);
    const rc = socket_system.connect(fd, @ptrCast(&addr), @sizeOf(posix.sockaddr.in));
    switch (posix.errno(rc)) {
        .SUCCESS => return fd,
        .INPROGRESS, .ALREADY => {},
        else => return error.ProbeWakeFailed,
    }
    while (true) {
        if (std.Io.Clock.Timestamp.compare(std.Io.Clock.Timestamp.now(std.testing.io, .awake), .gte, deadline)) return error.Timeout;
        var ready = [_]posix.pollfd{.{ .fd = fd, .events = posix.POLL.OUT, .revents = 0 }};
        if (try posix.poll(&ready, 20) == 0) continue;
        var pending: c_int = 0;
        var pending_len: posix.socklen_t = @sizeOf(c_int);
        if (posix.errno(socket_system.getsockopt(fd, posix.SOL.SOCKET, posix.SO.ERROR, @ptrCast(&pending), &pending_len)) != .SUCCESS or
            pending_len != @sizeOf(c_int) or pending != 0) return error.ProbeWakeFailed;
        return fd;
    }
}

fn wakeAndJoinProbe(probe: *OutboundHookProbe, port: u16, proceed: *std.Io.Event, returned: *std.Io.Event, thread: std.Thread) !void {
    probe.stop.store(true, .release);
    proceed.set(std.testing.io);
    const deadline = managedStopTestDeadline();
    // A blocking accept needs a real pending connection. Keep this owned peer
    // alive through the probe's bounded I/O and actual return, then join. A
    // failure to prove return must abort this fixture, never blindly join or
    // let a thread retain references into a returned stack frame.
    const wake = try connectProbeWakeUntil(port, deadline);
    defer closeFd(wake);
    try returned.waitTimeout(std.testing.io, .{ .deadline = deadline });
    thread.join();
}

fn exerciseDrainedProbeReadiness(force_blocking: bool, cleanup: *ProbeCleanupObservation) !void {
    const listener = try bindLoopback(true);
    defer closeFd(listener.fd);
    if (force_blocking) {
        const old = socket_system.fcntl(listener.fd, posix.F.GETFL, @as(c_int, 0));
        if (posix.errno(old) != .SUCCESS) return error.Unexpected;
        var flags: posix.O = @bitCast(@as(u32, @intCast(old)));
        flags.NONBLOCK = false;
        if (posix.errno(socket_system.fcntl(listener.fd, posix.F.SETFL, @as(usize, @as(u32, @bitCast(flags))))) != .SUCCESS) return error.Unexpected;
    }
    const client = try connectLoopback(listener.port);
    defer closeFd(client);
    var arrived: std.Io.Event = .unset;
    var proceed: std.Io.Event = .unset;
    var returned: std.Io.Event = .unset;
    var probe: OutboundHookProbe = .{ .listen_fd = listener.fd, .ready_pause = .{ .arrived = &arrived, .proceed = &proceed, .returned = &returned } };
    const thread = try std.Thread.spawn(.{}, OutboundHookProbe.run, .{&probe});
    var joined = false;
    defer if (!joined) {
        wakeAndJoinProbe(&probe, listener.port, &proceed, &returned, thread) catch |err|
            std.debug.panic("outbound probe could not prove bounded cleanup return: {s}", .{@errorName(err)});
        cleanup.* = .{ .woke_and_joined = true, .hits = probe.hits };
    };
    const deadline = managedStopTestDeadline();
    try arrived.waitTimeout(std.testing.io, .{ .deadline = deadline });
    // A second actual accept consumes the sole pending connection while the
    // original probe is stopped exactly between readiness and its own accept.
    const drained = if (comptime builtin.os.tag == .openbsd)
        socket_system.accept(listener.fd, null, null)
    else
        linux.accept4(listener.fd, null, null, posix.SOCK.CLOEXEC);
    try std.testing.expectEqual(posix.E.SUCCESS, posix.errno(drained));
    defer closeFd(@intCast(drained));
    probe.stop.store(true, .release);
    proceed.set(std.testing.io);
    const return_deadline = if (force_blocking)
        std.Io.Clock.Timestamp.fromNow(std.testing.io, .{ .clock = .awake, .raw = .fromMilliseconds(100) })
    else
        deadline;
    try returned.waitTimeout(std.testing.io, .{ .deadline = return_deadline });
    thread.join();
    joined = true;
    try std.testing.expect(probe.accept_wouldblock);
    try std.testing.expectEqual(@as(usize, 0), probe.hits);
    try std.testing.expect(os_runtime.fdValid(listener.fd));
    try std.testing.expectEqual(listener.port, try socketPort(listener.fd));
}

test "webpush consumer: actual drained probe readiness returns before listener closes" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var cleanup: ProbeCleanupObservation = .{};
    try exerciseDrainedProbeReadiness(false, &cleanup);
    try std.testing.expect(!cleanup.woke_and_joined);
}

test "webpush consumer: blocking accept fault has bounded real connection cleanup" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    var cleanup: ProbeCleanupObservation = .{};
    try std.testing.expectError(error.Timeout, exerciseDrainedProbeReadiness(true, &cleanup));
    try std.testing.expect(cleanup.woke_and_joined);
    try std.testing.expectEqual(@as(usize, 1), cleanup.hits);
}

fn outboundRequestBody(raw: []const u8) ?[]const u8 {
    const mark = "\r\n\r\n";
    const at = std.mem.indexOf(u8, raw, mark) orelse return null;
    return raw[at + mark.len ..];
}

fn outboundRequestSigned(secret: []const u8, raw: []const u8) bool {
    const body = outboundRequestBody(raw) orelse return false;
    const head_end = std.mem.indexOf(u8, raw, "\r\n\r\n") orelse return false;
    const head = raw[0..head_end];
    const prefix = "X-Onyx-Signature: ";
    const at = std.mem.indexOf(u8, head, prefix) orelse return false;
    const rest = head[at + prefix.len ..];
    const end = std.mem.indexOfAny(u8, rest, "\r\n") orelse rest.len;
    const got = std.mem.trim(u8, rest[0..end], " \t");
    var expect: [71]u8 = undefined;
    const want = outboundSignature(secret, body, &expect);
    return std.mem.eql(u8, got, want);
}

test "GAP-O11 outbound webhooks sign retries and refuse loopback" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    var server = Server.init(allocator, .{
        .host = "127.0.0.1",
        .port = 0,
        .server_name = "hook.test",
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer {
        current_reactor = null;
        server.deinit();
    }
    current_reactor = &server.reactors[0];

    var probe = OutboundHookProbe{};
    defer {
        probe.stop.store(true, .release);
        if (probe.listen_fd >= 0) closeFd(probe.listen_fd);
        if (probe.started) probe.thread.join();
    }
    const listener = bindLoopback(true) catch return error.SkipZigTest;
    probe.listen_fd = listener.fd;
    probe.thread = std.Thread.spawn(.{}, OutboundHookProbe.run, .{&probe}) catch return error.SkipZigTest;
    probe.started = true;

    const dead = bindLoopback(false) catch return error.SkipZigTest;
    defer closeFd(dead.fd);

    const user_id = try addTestLocalClient(&server, "user", null);
    const user = server.connFor(user_id).?;
    const oper_id = try addTestLocalClient(&server, "oper", null);
    const oper = server.connFor(oper_id).?;
    oper.session.is_oper = true;
    oper.session.oper_priv = oper_mod.OperPrivileges.initMany(&.{.server_admin});

    var denied = try irc_line.parseLine("OUTHOOK ADD http://203.0.113.5/hook secret KILL");
    try server.handleOutboundWebhook(user, &denied);
    try std.testing.expect(std.mem.indexOf(u8, user.send_buf[0..user.send_len], "not an IRC operator") != null);
    try std.testing.expectEqual(@as(usize, 0), server.outboundWebhookCount());

    var live_url: [96]u8 = undefined;
    const live = std.fmt.bufPrint(&live_url, "http://127.0.0.1:{d}/hook", .{listener.port}) catch unreachable;
    var refuse_live: [160]u8 = undefined;
    const refuse_line = std.fmt.bufPrint(&refuse_live, "OUTHOOK ADD {s} s3cret-token KILL", .{live}) catch unreachable;
    var refuse_cmd = try irc_line.parseLine(refuse_line);
    oper.send_len = 0;
    try server.handleOutboundWebhook(oper, &refuse_cmd);
    try std.testing.expect(std.mem.indexOf(u8, oper.send_buf[0..oper.send_len], "refusing private or local") != null);
    try std.testing.expectEqual(@as(usize, 0), server.outboundWebhookCount());
    try std.testing.expectEqual(@as(u64, 0), server.outbound_webhook_attempts);
    lockSpin(&probe.mu);
    try std.testing.expectEqual(@as(usize, 0), probe.hits);
    probe.mu.unlock();

    const private_urls = [_][]const u8{
        "http://127.0.0.8/hook",
        "http://localhost/hook",
        "http://LOCALHOST:8080/hook",
        "http://169.254.1.1/hook",
        "http://[::1]/hook",
        "http://[fe80::1]/hook",
        "http://[::ffff:127.0.0.1]/hook",
        "http://10.1.2.3/hook",
        "http://172.16.1.2/hook",
        "http://192.168.0.2/hook",
        "http://[fd00::1]/hook",
        "http://203.0.113.5/hook",
    };
    for (private_urls) |url| {
        var line_buf: [192]u8 = undefined;
        const line = std.fmt.bufPrint(&line_buf, "OUTHOOK ADD {s} s3cret-token KILL", .{url}) catch unreachable;
        var cmd = try irc_line.parseLine(line);
        oper.send_len = 0;
        try server.handleOutboundWebhook(oper, &cmd);
        try std.testing.expect(std.mem.indexOf(u8, oper.send_buf[0..oper.send_len], "refusing private or local") != null);
    }
    try std.testing.expectEqual(@as(usize, 0), server.outboundWebhookCount());

    var public_cmd = try irc_line.parseLine("OUTHOOK ADD http://1.1.1.1/hook s3cret-token KILL,POLICY");
    oper.send_len = 0;
    try server.handleOutboundWebhook(oper, &public_cmd);
    try std.testing.expect(std.mem.indexOf(u8, oper.send_buf[0..oper.send_len], "OUTHOOK: registered") != null);
    try std.testing.expect(std.mem.indexOf(u8, oper.send_buf[0..oper.send_len], "s3cret-token") == null);
    var public_v6 = try irc_line.parseLine("OUTHOOK ADD http://[2606:4700:4700::1111]/hook s3cret-token KILL");
    try server.handleOutboundWebhook(oper, &public_v6);
    try std.testing.expectEqual(@as(usize, 2), server.outboundWebhookCount());
    var list_cmd = try irc_line.parseLine("OUTHOOK LIST");
    oper.send_len = 0;
    try server.handleOutboundWebhook(oper, &list_cmd);
    const listed = oper.send_buf[0..oper.send_len];
    try std.testing.expect(std.mem.indexOf(u8, listed, "1.1.1.1") != null);
    try std.testing.expect(std.mem.indexOf(u8, listed, "KILL") != null);
    try std.testing.expect(std.mem.indexOf(u8, listed, "POLICY") != null);
    try std.testing.expect(std.mem.indexOf(u8, listed, "s3cret-token") == null);
    var bad_cat = try irc_line.parseLine("OUTHOOK ADD http://1.1.1.9/hook s3cret-token NOTACAT");
    oper.send_len = 0;
    try server.handleOutboundWebhook(oper, &bad_cat);
    try std.testing.expect(std.mem.indexOf(u8, oper.send_buf[0..oper.send_len], "unknown category") != null);
    try std.testing.expectEqual(@as(usize, 2), server.outboundWebhookCount());
    var del_public = try irc_line.parseLine("OUTHOOK DEL http://1.1.1.1/hook");
    try server.handleOutboundWebhook(oper, &del_public);
    var del_v6 = try irc_line.parseLine("OUTHOOK DEL http://[2606:4700:4700::1111]/hook");
    try server.handleOutboundWebhook(oper, &del_v6);
    try std.testing.expectEqual(@as(usize, 0), server.outboundWebhookCount());

    server.config.webhook_allow_private = true;
    var dead_url: [96]u8 = undefined;
    const dead_target = std.fmt.bufPrint(&dead_url, "http://127.0.0.1:{d}/dead", .{dead.port}) catch unreachable;
    var dead_line: [160]u8 = undefined;
    const dead_text = std.fmt.bufPrint(&dead_line, "OUTHOOK ADD {s} s3cret-token KILL", .{dead_target}) catch unreachable;
    var dead_cmd = try irc_line.parseLine(dead_text);
    oper.send_len = 0;
    try server.handleOutboundWebhook(oper, &dead_cmd);
    try std.testing.expect(std.mem.indexOf(u8, oper.send_buf[0..oper.send_len], "OUTHOOK: registered") != null);
    try server.publishOperEvent(.flood, .warn, "flood-ignored");
    try std.testing.expectEqual(@as(u64, 0), server.outbound_webhook_attempts);
    try server.publishOperEvent(.kill, .warn, "dead-port-kill");
    try std.testing.expectEqual(@as(u64, outbound_webhook_attempt_cap), server.outbound_webhook_attempts);
    try std.testing.expectEqual(@as(u64, 0), server.outbound_webhook_delivered);
    try std.testing.expectEqual(@as(u64, 1), server.outbound_webhook_dropped);
    var del_dead = try irc_line.parseLine(dead_text);
    // DEL needs the stored URL, which is the ADD argument, not the whole line.
    var del_dead_line: [160]u8 = undefined;
    const del_dead_text = std.fmt.bufPrint(&del_dead_line, "OUTHOOK DEL {s}", .{dead_target}) catch unreachable;
    del_dead = try irc_line.parseLine(del_dead_text);
    try server.handleOutboundWebhook(oper, &del_dead);
    try std.testing.expectEqual(@as(usize, 0), server.outboundWebhookCount());

    server.outbound_resolve_for_test = pinOutboundLoopbackForTest;
    var pinned_url: [96]u8 = undefined;
    const pinned = try std.fmt.bufPrint(&pinned_url, "http://pinned.invalid:{d}/hook", .{listener.port});
    var pinned_line: [160]u8 = undefined;
    const pinned_text = try std.fmt.bufPrint(&pinned_line, "OUTHOOK ADD {s} s3cret-token KILL", .{pinned});
    var add_live = try irc_line.parseLine(pinned_text);
    oper.send_len = 0;
    try server.handleOutboundWebhook(oper, &add_live);
    try std.testing.expect(std.mem.indexOf(u8, oper.send_buf[0..oper.send_len], "OUTHOOK: registered") != null);
    const attempts_before = server.outbound_webhook_attempts;
    try server.publishOperEvent(.flood, .warn, "flood-still-ignored");
    try std.testing.expectEqual(attempts_before, server.outbound_webhook_attempts);
    try server.publishOperEvent(.kill, .warn, "live-kill");
    try std.testing.expectEqual(attempts_before + 2, server.outbound_webhook_attempts);
    try std.testing.expectEqual(@as(u64, 1), server.outbound_webhook_delivered);
    lockSpin(&probe.mu);
    try std.testing.expectEqual(@as(usize, 2), probe.hits);
    try std.testing.expect(probe.req_len[0] > 0);
    try std.testing.expect(probe.req_len[1] > 0);
    const first = probe.req[0][0..probe.req_len[0]];
    const second = probe.req[1][0..probe.req_len[1]];
    try std.testing.expect(std.mem.indexOf(u8, first, "Host: pinned.invalid") != null);
    try std.testing.expect(outboundRequestSigned("s3cret-token", first));
    try std.testing.expect(outboundRequestSigned("s3cret-token", second));
    const body = outboundRequestBody(first) orelse return error.TestUnexpectedResult;
    try std.testing.expect(std.mem.indexOf(u8, body, "\"category\":\"KILL\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "live-kill") != null);
    try std.testing.expect(std.mem.indexOf(u8, body, "hook.test") != null);
    probe.mu.unlock();

    try std.testing.expect(!server.config.webhook_enabled);
    var inbound = try irc_line.parseLine("WEBHOOK LIST #hooks");
    oper.send_len = 0;
    try server.handleWebhook(oper_id, oper, &inbound);
    try std.testing.expect(std.mem.indexOf(u8, oper.send_buf[0..oper.send_len], "not enabled") != null);

    std.debug.print("GAP-O11 branch=outbound webhooks sign and retry with a cap; private and local targets stay refused unless config allows them\n", .{});
}

test "outbound webhook forwards screened address and fails closed" {
    if (comptime builtin.os.tag != .windows and builtin.os.tag != .linux) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const server = createTestServer(allocator, .{ .host = "127.0.0.1", .port = 0, .crypto_io = std.testing.io }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer allocator.destroy(server);
    defer server.deinit();

    const Fixture = struct {
        var selected: std.Io.net.IpAddress = .{ .ip4 = .{ .bytes = .{ 1, 1, 1, 7 }, .port = 443 } };
        var fail: bool = false;
        var resolutions: usize = 0;
        fn resolve(host: []const u8, port: u16) anyerror!std.Io.net.IpAddress {
            try std.testing.expectEqualStrings("public.example", host);
            try std.testing.expectEqual(@as(u16, 443), port);
            resolutions += 1;
            if (fail) return error.TestDnsFailure;
            return selected;
        }
    };
    Fixture.resolutions = 0;
    Fixture.fail = false;
    server.outbound_resolve_for_test = Fixture.resolve;
    const public = try server.resolveOutboundWebhookAddress("public.example", 443);
    try std.testing.expectEqualDeep(Fixture.selected, public);
    try std.testing.expectEqual(@as(usize, 1), Fixture.resolutions);

    const denied = [_][]const u8{ "10.1.2.3", "172.16.1.2", "192.168.0.2", "169.254.169.254", "fd00::1", "fe80::1", "::ffff:10.1.2.3" };
    for (denied) |raw| {
        Fixture.selected = try std.Io.net.IpAddress.parse(raw, 443);
        try std.testing.expectError(error.PrivateOutboundAddress, server.resolveOutboundWebhookAddress("public.example", 443));
    }
    try std.testing.expectEqual(@as(usize, 1 + denied.len), Fixture.resolutions);
    Fixture.fail = true;
    try std.testing.expectError(error.TestDnsFailure, server.resolveOutboundWebhookAddress("public.example", 443));
    Fixture.fail = false;
    server.config.webhook_allow_private = true;
    try std.testing.expectEqualDeep(Fixture.selected, try server.resolveOutboundWebhookAddress("public.example", 443));
}

test "Windows pinned webhook failover screens AAAA and stops after connection" {
    if (comptime builtin.os.tag != .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
