        const peer_text = std.fmt.bufPrint(&text_buf, "capword frompeer {d}", .{i}) catch return error.TestUnexpectedResult;
        remote.recordHistoryRelayAt("#room", "bob!bob@peer", peer_id, "PRIVMSG", peer_text, null, 1_700_000_100_000 + i);
    }

    var now_ms: u64 = 20;
    var asker_state = s2s_peer_mod.ChannelCrdt.init(alloc, 0x61);
    defer asker_state.deinit();
    var remote_state = s2s_peer_mod.ChannelCrdt.init(alloc, 0x62);
    defer remote_state.deinit();
    var to_remote = ServerPeerTestBuffer{};
    defer to_remote.deinit();
    var to_asker = ServerPeerTestBuffer{};
    defer to_asker.deinit();
    const asker_kp = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0x61)));
    const remote_kp = try sign_mod.KeyPair.fromSeed(@as([sign_mod.seed_len]u8, @splat(0x62)));
    var asker_peer = try initServerTestPeer(&asker_state, &now_ms, asker_kp, message_relay.originShortId(remote_kp.public_key), 3000, "asker-cap.test", false);
    defer asker_peer.deinit();
    var remote_peer = try initServerTestPeer(&remote_state, &now_ms, remote_kp, message_relay.originShortId(asker_kp.public_key), 4000, "remote-cap.test", false);
    defer remote_peer.deinit();
    try asker_peer.startHandshake(to_remote.sink());
    try remote_peer.startHandshake(to_asker.sink());
    try pumpServerTestPeers(&asker_peer, &remote_peer, &to_remote, &to_asker, now_ms, 0xCA90);
    try std.testing.expect(asker_peer.supportsMeshSearch());
    try asker.noteMeshSearchLink(&asker_peer, to_remote.sink());

    alice.send_len = 0;
    try asker.handleSearch(alice_id, alice, "SEARCH #room :capword");
    try pumpServerTestPeers(&asker_peer, &remote_peer, &to_remote, &to_asker, now_ms, 0xCA91);
    remote.drainMeshSearchPeer(&remote_peer, to_asker.sink());
    try pumpServerTestPeers(&asker_peer, &remote_peer, &to_remote, &to_asker, now_ms, 0xCA92);
    asker.drainMeshSearchPeer(&asker_peer, to_remote.sink());
    const got = alice.send_buf[0..alice.send_len];
    try std.testing.expectEqual(@as(usize, 50), countSliceForTest(got, "capword"));
    try std.testing.expectEqual(@as(usize, 40), countSliceForTest(got, "fromlocal"));
    try std.testing.expectEqual(@as(usize, 10), countSliceForTest(got, "frompeer"));
    current_reactor = null;
    std.debug.print("GAP-P5 branch=mesh link local batch plus peer hits stay inside the hard cap\n", .{});
}

var gap_p6_fetches: usize = 0;
var gap_p6_resolves: usize = 0;

fn gapP6Fetch(request: []const u8, dest: []u8) anyerror!usize {
    if (std.mem.indexOf(u8, request, "Cookie") != null) return error.Cookie;
    if (std.mem.indexOf(u8, request, "cookie") != null) return error.Cookie;
    gap_p6_fetches += 1;
    const html = "<html><title>Hello Title</title><meta property=\"og:description\" content=\"A description\"><meta property=\"og:image\" content=\"https://cdn.example/a.png\"></html>";
    if (html.len > dest.len) return error.TooBig;
    @memcpy(dest[0..html.len], html);
    return html.len;
}

fn gapP6Resolve(host: []const u8) anyerror!std.Io.net.IpAddress {
    _ = host;
    gap_p6_resolves += 1;
    return .{ .ip4 = .{ .bytes = .{ 1, 1, 1, 1 }, .port = 443 } };
}

test "GAP-P6 unfurl is opt-in, bounded, and refuses private addresses" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;
    gap_p6_fetches = 0;
    gap_p6_resolves = 0;

    const off_config = Config{ .host = "127.0.0.1", .port = 0, .server_name = "unfurl.test" };
    const off = createTestServer(alloc, off_config) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(off);
    defer off.deinit();
    off.unfurl_fetch_for_test = gapP6Fetch;
    off.unfurl_resolve_for_test = gapP6Resolve;
    const off_id = try addTestLocalClient(off, "alice", "alice");
    const off_alice = off.connFor(off_id).?;
    off_alice.session.registration.registered = true;
    off_alice.send_len = 0;
    var off_line = try irc_line.parseLine("UNFURL https://example.com/a");
    try off.handleUnfurl(off_alice, &off_line);
    try std.testing.expect(std.mem.indexOf(u8, off_alice.send_buf[0..off_alice.send_len], "disabled") != null);
    try std.testing.expectEqual(@as(usize, 0), gap_p6_fetches);

    var on_config = off_config;
    on_config.unfurl_enabled = true;
    const server = createTestServer(alloc, on_config) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();
    server.unfurl_fetch_for_test = gapP6Fetch;
    server.unfurl_resolve_for_test = gapP6Resolve;
    const alice_id = try addTestLocalClient(server, "alice", "alice");
    const alice = server.connFor(alice_id).?;
    alice.session.registration.registered = true;

    alice.send_len = 0;
    var refused = try irc_line.parseLine("UNFURL https://example.com/a");
    try server.handleUnfurl(alice, &refused);
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], "client refused") != null);
    try std.testing.expectEqual(@as(usize, 0), gap_p6_fetches);

    var on_line = try irc_line.parseLine("UNFURL ON");
    try server.handleUnfurl(alice, &on_line);

    const denied = [_][]const u8{
        "UNFURL https://127.0.0.1/secret",
        "UNFURL https://10.1.2.3/a",
        "UNFURL https://192.168.0.2/a",
        "UNFURL https://169.254.169.254/latest",
        "UNFURL https://[::1]/a",
        "UNFURL https://[fe80::1]/a",
        "UNFURL http://1.1.1.1/a",
    };
    for (denied) |raw| {
        alice.send_len = 0;
        var line = try irc_line.parseLine(raw);
        try server.handleUnfurl(alice, &line);
        const got = alice.send_buf[0..alice.send_len];
        try std.testing.expect(std.mem.indexOf(u8, got, "Hello Title") == null);
    }
    try std.testing.expectEqual(@as(usize, 0), gap_p6_fetches);
    try std.testing.expectEqual(@as(usize, 0), gap_p6_resolves);

    alice.send_len = 0;
    var ok_line = try irc_line.parseLine("UNFURL https://example.com/a");
    try server.handleUnfurl(alice, &ok_line);
    const preview = alice.send_buf[0..alice.send_len];
    try std.testing.expectEqual(@as(usize, 1), gap_p6_fetches);
    try std.testing.expectEqual(@as(usize, 1), gap_p6_resolves);
    try std.testing.expect(std.mem.indexOf(u8, preview, "Hello Title") != null);
    try std.testing.expect(std.mem.indexOf(u8, preview, "A description") != null);
    try std.testing.expect(std.mem.indexOf(u8, preview, "https://cdn.example/a.png") != null);

    var off_again = try irc_line.parseLine("UNFURL OFF");
    try server.handleUnfurl(alice, &off_again);
    alice.send_len = 0;
    var after = try irc_line.parseLine("UNFURL https://example.com/b");
    try server.handleUnfurl(alice, &after);
    try std.testing.expectEqual(@as(usize, 1), gap_p6_fetches);
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], "client refused") != null);
    current_reactor = null;
    std.debug.print("GAP-P6 branch=unfurl defaults off, the client can refuse, and private addresses are not fetched\n", .{});
}

test "UNFURL forwards the screened address to its fetch" {
    if (comptime builtin.os.tag != .windows and builtin.os.tag != .linux) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const server = createTestServer(allocator, .{ .host = "127.0.0.1", .port = 0, .unfurl_enabled = true, .crypto_io = std.testing.io }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer allocator.destroy(server);
    defer server.deinit();
    defer current_reactor = null;
    current_reactor = &server.reactors[0];

    const Fixture = struct {
        var answer: std.Io.net.IpAddress = .{ .ip4 = .{ .bytes = .{ 1, 1, 1, 9 }, .port = 443 } };
        var fail: bool = false;
        var resolves: usize = 0;
        var fetches: usize = 0;
        fn resolve(host: []const u8) anyerror!std.Io.net.IpAddress {
            try std.testing.expectEqualStrings("preview.invalid", host);
            resolves += 1;
            if (fail) return error.TestDnsFailure;
            return answer;
        }
        fn fetch(request: []const u8, addr: std.Io.net.IpAddress, dest: []u8) anyerror!usize {
            try std.testing.expect(std.mem.indexOf(u8, request, "Host: preview.invalid") != null);
            try std.testing.expectEqualDeep(answer, addr);
            fetches += 1;
            const html = "<title>Pinned preview</title>";
            @memcpy(dest[0..html.len], html);
            return html.len;
        }
    };
    Fixture.resolves = 0;
    Fixture.fetches = 0;
    Fixture.fail = false;
    server.unfurl_resolve_for_test = Fixture.resolve;
    server.unfurl_fetch_at_address_for_test = Fixture.fetch;
    const target = try unfurl.parseHttps("https://preview.invalid/a");
    const addr = try server.resolveUnfurlAddress(target);
    var request_buf: [512]u8 = undefined;
    const request = try unfurl.buildTargetRequest(&request_buf, target);
    var body_buf: [unfurl.max_body]u8 = undefined;
    const body = try server.unfurlBody(request, target, addr, &body_buf);
    try std.testing.expectEqualStrings("<title>Pinned preview</title>", body);
    try std.testing.expectEqual(@as(usize, 1), Fixture.resolves);
    try std.testing.expectEqual(@as(usize, 1), Fixture.fetches);

    Fixture.answer = try std.Io.net.IpAddress.parse("fd00::1", 443);
    try std.testing.expectError(error.PrivateUnfurlAddress, server.resolveUnfurlAddress(target));
    try std.testing.expectEqual(@as(usize, 1), Fixture.fetches);
    Fixture.fail = true;
    try std.testing.expectError(error.TestDnsFailure, server.resolveUnfurlAddress(target));
    try std.testing.expectEqual(@as(usize, 1), Fixture.fetches);
}

test "Windows UNFURL hostname lookup uses AAAA only after missing A" {
    if (comptime builtin.os.tag != .windows) return error.SkipZigTest;
    const IpAddress = std.Io.net.IpAddress;
    const Fixture = struct {
        var a_answer: IpAddress = undefined;
        var a_failure: ?anyerror = null;
        var aaaa_answer: IpAddress = undefined;
        var aaaa_failure: ?anyerror = null;
        var a_calls: usize = 0;
        var aaaa_calls: usize = 0;

        fn a(host: []const u8, port: u16, timeout_ms: u31) anyerror!IpAddress {
            try std.testing.expectEqualStrings("preview.invalid", host);
            try std.testing.expectEqual(@as(u16, 8443), port);
            try std.testing.expectEqual(@as(u31, 2000), timeout_ms);
            a_calls += 1;
            if (a_failure) |err| return err;
            return a_answer;
        }

        fn aaaa(host: []const u8, port: u16, timeout_ms: u31) anyerror!IpAddress {
            try std.testing.expectEqualStrings("preview.invalid", host);
            try std.testing.expectEqual(@as(u16, 8443), port);
            try std.testing.expectEqual(@as(u31, 2000), timeout_ms);
            aaaa_calls += 1;
            if (aaaa_failure) |err| return err;
            return aaaa_answer;
        }
    };
    Fixture.a_answer = try IpAddress.parse("1.1.1.9", 8443);
    Fixture.aaaa_answer = try IpAddress.parse("2606:4700:4700::1111", 8443);
    Fixture.a_failure = null;
    Fixture.aaaa_failure = null;
    Fixture.a_calls = 0;
    Fixture.aaaa_calls = 0;
    const host = "preview.invalid";
    try std.testing.expectEqualDeep(Fixture.a_answer, try LinuxServer.resolveUnfurlHostname(host, 8443, Fixture.a, Fixture.aaaa));
    try std.testing.expectEqual(@as(usize, 1), Fixture.a_calls);
    try std.testing.expectEqual(@as(usize, 0), Fixture.aaaa_calls);

    Fixture.a_failure = error.HostNotFound;
    try std.testing.expectEqualDeep(Fixture.aaaa_answer, try LinuxServer.resolveUnfurlHostname(host, 8443, Fixture.a, Fixture.aaaa));
    try std.testing.expectEqual(@as(usize, 2), Fixture.a_calls);
    try std.testing.expectEqual(@as(usize, 1), Fixture.aaaa_calls);

    Fixture.a_failure = error.TestDnsFailure;
    try std.testing.expectError(error.TestDnsFailure, LinuxServer.resolveUnfurlHostname(host, 8443, Fixture.a, Fixture.aaaa));
    try std.testing.expectEqual(@as(usize, 3), Fixture.a_calls);
    try std.testing.expectEqual(@as(usize, 1), Fixture.aaaa_calls);

    Fixture.a_failure = error.HostNotFound;
    Fixture.aaaa_failure = error.TestAAAAFailure;
    try std.testing.expectError(error.TestAAAAFailure, LinuxServer.resolveUnfurlHostname(host, 8443, Fixture.a, Fixture.aaaa));
    try std.testing.expectEqual(@as(usize, 4), Fixture.a_calls);
    try std.testing.expectEqual(@as(usize, 2), Fixture.aaaa_calls);
}

test "Windows pinned UNFURL failover screens AAAA and stops after connection" {
    if (comptime builtin.os.tag != .windows) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const server = try createTestServer(allocator, .{ .host = "127.0.0.1", .port = 0, .crypto_io = std.testing.io });
    defer allocator.destroy(server);
    defer server.deinit();
    const IpAddress = std.Io.net.IpAddress;
    const Fixture = struct {
        var aaaa: IpAddress = undefined;
        var aaaa_calls: usize = 0;
        var gets: usize = 0;
        var get_addrs: [2]IpAddress = undefined;
        var connected_on_failure: bool = false;
        var first_error: anyerror = error.ConnectTimeout;

        fn resolveA(host: []const u8) anyerror!IpAddress {
            try std.testing.expectEqualStrings("preview.test", host);
            return IpAddress.parse("1.1.1.7", 8443);
        }
        fn resolveAAAA(host: []const u8) anyerror!IpAddress {
            try std.testing.expectEqualStrings("preview.test", host);
            aaaa_calls += 1;
            return aaaa;
        }
        fn get(a: std.mem.Allocator, _: []const u8, port: u16, request: []const u8, addr: IpAddress, opts: http_fetch.Options) anyerror![]u8 {
            try std.testing.expectEqual(@as(u16, 8443), port);
            try std.testing.expect(std.mem.startsWith(u8, request, "GET "));
            try std.testing.expect(opts.connect_established != null);
            if (gets >= get_addrs.len) return error.TestUnexpectedGet;
            get_addrs[gets] = addr;
            gets += 1;
            if (gets == 1) {
                opts.connect_established.?.* = connected_on_failure;
                return first_error;
            }
            opts.connect_established.?.* = true;
            return a.dupe(u8, "HTTP/1.1 200 OK\r\nContent-Length: 19\r\n\r\n<title>IPv6</title>");
        }
    };
    server.unfurl_resolve_for_test = Fixture.resolveA;
    server.unfurl_resolve_aaaa_for_test = Fixture.resolveAAAA;
    server.unfurl_get_at_address_for_test = Fixture.get;
    server.outbound_trust_anchors_for_test = &.{};
    const target = try unfurl.parseHttps("https://preview.test:8443/preview");
    const addr = try server.resolveUnfurlAddress(target);
    var request_buf: [512]u8 = undefined;
    const request = try unfurl.buildTargetRequest(&request_buf, target);
    var body_buf: [unfurl.max_body]u8 = undefined;
    Fixture.aaaa = try IpAddress.parse("2606:4700:4700::1111", 8443);
    Fixture.aaaa_calls = 0;
    Fixture.gets = 0;
    Fixture.connected_on_failure = false;
    Fixture.first_error = error.ConnectTimeout;
    const body = try server.unfurlBody(request, target, addr, &body_buf);
    try std.testing.expectEqualStrings("<title>IPv6</title>", body);
    try std.testing.expectEqual(@as(usize, 2), Fixture.gets);
    try std.testing.expectEqual(@as(usize, 1), Fixture.aaaa_calls);
    try std.testing.expectEqualDeep(addr, Fixture.get_addrs[0]);
    try std.testing.expectEqualDeep(Fixture.aaaa, Fixture.get_addrs[1]);

    Fixture.aaaa = try IpAddress.parse("fd00::1", 8443);
    Fixture.aaaa_calls = 0;
    Fixture.gets = 0;
    try std.testing.expectError(error.PrivateUnfurlAddress, server.unfurlBody(request, target, addr, &body_buf));
    try std.testing.expectEqual(@as(usize, 1), Fixture.gets);
    try std.testing.expectEqual(@as(usize, 1), Fixture.aaaa_calls);

    Fixture.aaaa = try IpAddress.parse("2606:4700:4700::1111", 8443);
    Fixture.aaaa_calls = 0;
    Fixture.gets = 0;
    Fixture.connected_on_failure = true;
    Fixture.first_error = error.ConnectionClosed;
    try std.testing.expectError(error.ConnectionClosed, server.unfurlBody(request, target, addr, &body_buf));
    try std.testing.expectEqual(@as(usize, 1), Fixture.gets);
    try std.testing.expectEqual(@as(usize, 0), Fixture.aaaa_calls);

    Fixture.connected_on_failure = false;
    Fixture.first_error = error.ConnectTimeout;
    Fixture.gets = 0;
    const literal = try unfurl.parseHttps("https://1.1.1.7:8443/preview");
    const literal_addr = try server.resolveUnfurlAddress(literal);
    const literal_request = try unfurl.buildTargetRequest(&request_buf, literal);
    try std.testing.expectError(error.ConnectTimeout, server.unfurlBody(literal_request, literal, literal_addr, &body_buf));
    try std.testing.expectEqual(@as(usize, 1), Fixture.gets);
    try std.testing.expectEqual(@as(usize, 0), Fixture.aaaa_calls);
}

test "GAP-P7 a banned connection files one appeal and the oper answer is audited" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;
    const config = Config{ .host = "127.0.0.1", .port = 0, .server_name = "appeal.test" };
    const server = createTestServer(alloc, config) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();
    var sim = reactor_mod.SimReactor.init(1_700_000_000_000);
    server.reactor = sim.reactor();

    try server.warden.add(.{
        .match = .host,
        .pattern = "banned.example",
        .scope = .node,
        .action = .refuse,
        .reason = "network ban",
        .set_by = "carol",
    });

    const bob_id = try addTestLocalClient(server, "bob", "bob");
    const bob = server.connFor(bob_id).?;
    _ = try server.world.join("#room", worldIdFromClient(bob_id));
    bob.send_len = 0;

    const alice_id = try gapP8Open(server);
    const alice = server.connFor(alice_id).?;
    alice.session.setRealHost("banned.example");
    try gapP8Feed(server, alice_id, alice, "NICK alice\r\n");
    const banned = server.wardMatch(alice) orelse return error.TestUnexpectedResult;
    try std.testing.expect(banned.action == .refuse);
    try std.testing.expect(!alice.session.registered());
    try std.testing.expect(server.world.findNick("alice") == null);
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], " 001 ") == null);

    try gapP8Feed(server, alice_id, alice, "APPEAL :please review the ban\r\n");
    const filed_note = alice.send_buf[0..alice.send_len];
    try std.testing.expect(std.mem.indexOf(u8, filed_note, "APPEAL filed 1") != null);
    try std.testing.expect(!alice.session.registered());
    try std.testing.expect(server.world.findNick("alice") == null);
    try std.testing.expect(!server.world.isMember("#room", worldIdFromClient(alice_id)));
    try std.testing.expectEqual(@as(usize, 0), bob.send_len);

    try gapP8Feed(server, alice_id, alice, "APPEAL :please review again\r\n");
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], "already filed") != null);
    try std.testing.expectEqual(@as(usize, 1), server.appeals.count());

    sim.advance(appeal.window_ms - 1);
    try gapP8Feed(server, alice_id, alice, "APPEAL :still this window\r\n");
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], "already filed") != null);
    try std.testing.expectEqual(@as(usize, 1), server.appeals.count());

    sim.advance(1);
    try gapP8Feed(server, alice_id, alice, "APPEAL :the next window\r\n");
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], "APPEAL filed 2") != null);
    try std.testing.expectEqual(@as(usize, 2), server.appeals.count());
    try std.testing.expect(!alice.session.registered());
    try std.testing.expect(server.world.findNick("alice") == null);

    try gapP8Feed(server, alice_id, alice, "PRIVMSG #room :please review the ban\r\n");
    try gapP8Feed(server, alice_id, alice, "JOIN #room\r\n");
    try std.testing.expect(!server.world.isMember("#room", worldIdFromClient(alice_id)));
    try std.testing.expectEqual(@as(usize, 0), bob.send_len);

    const carol_id = try addTestLocalClient(server, "carol", "carol");
    const carol = server.connFor(carol_id).?;
    carol.session.registration.registered = true;
    carol.session.is_oper = true;
    try gapP8Feed(server, carol_id, carol, "APPEAL LIST\r\n");
    const listed = carol.send_buf[0..carol.send_len];
    try std.testing.expect(std.mem.indexOf(u8, listed, "please review the ban") != null);
    try std.testing.expect(std.mem.indexOf(u8, listed, "the next window") != null);
    try std.testing.expect(std.mem.indexOf(u8, listed, "open") != null);

    try gapP8Feed(server, carol_id, carol, "APPEAL ANSWER 1 :reviewed tomorrow\r\n");
    try std.testing.expect(std.mem.indexOf(u8, carol.send_buf[0..carol.send_len], "APPEAL answered") != null);
    try std.testing.expectEqual(@as(usize, 0), bob.send_len);
    try std.testing.expect(server.world.findNick("alice") == null);

    var audited = false;
    var i: usize = 0;
    while (i < server.oper_audit.len()) : (i += 1) {
        const entry = server.oper_audit.at(i) orelse continue;
        if (std.mem.indexOf(u8, entry.reason, "appeal answer") != null and
            std.mem.indexOf(u8, entry.reason, "reviewed tomorrow") != null)
        {
            audited = true;
        }
    }
    try std.testing.expect(audited);

    var hist: [16]lotus.Message = undefined;
    if (server.history.latest("#room", hist.len, &hist)) |rows| {
        for (rows) |row| {
            try std.testing.expect(std.mem.indexOf(u8, row.text, "please review") == null);
            try std.testing.expect(std.mem.indexOf(u8, row.text, "the next window") == null);
            try std.testing.expect(std.mem.indexOf(u8, row.text, "reviewed tomorrow") == null);
        }
    } else |_| {}
    current_reactor = null;
    std.debug.print("GAP-P7 branch=a network-banned new connection files one appeal per window without joining\n", .{});
}

fn gapP8Open(server: *Server) !client_model.ClientId {
    const id = try server.rx().clients.alloc(ConnState.init(-1));
    const conn = server.rx().clients.get(id).?;
    conn.token = try tokenFromId(id);
    conn.overflow_allocator = server.allocator;
    conn.connected_at_ms = server.nowMs();
    return id;
}

fn gapP8Feed(server: *Server, id: client_model.ClientId, conn: *ConnState, line: []const u8) !void {
    conn.send_len = 0;
    conn.send_offset = 0;
    try server.feedBytes(id, conn, line);
}

fn gapP8Pow(seed: []const u8, out: []u8) ?[]const u8 {
    var i: u32 = 0;
    while (i < 4096) : (i += 1) {
        const text = std.fmt.bufPrint(out, "{d}", .{i}) catch return null;
        if (challenge_mod.admit(.pow, .{ .seed = seed }, text)) return text;
    }
    return null;
}

test "GAP-P8 a tripped connection answers a challenge before 001" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;
    const config = Config{
        .host = "127.0.0.1",
        .port = 0,
        .server_name = "p8.test",
        .challenge_enabled = true,
        .reputation_refuse_threshold = 1,
    };
    const server = createTestServer(alloc, config) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();
    var sim = reactor_mod.SimReactor.init(1_000_000);
    server.reactor = sim.reactor();

    const clean_id = try gapP8Open(server);
    const clean = server.connFor(clean_id).?;
    try gapP8Feed(server, clean_id, clean, "NICK p8clean\r\nUSER p8clean 0 * :Clean\r\n");
    const clean_sent = clean.send_buf[0..clean.send_len];
    try std.testing.expect(std.mem.indexOf(u8, clean_sent, " 001 ") != null);
    try std.testing.expect(clean.session.registered());
    try std.testing.expect(!clean.session.logged_in);
    try std.testing.expect(clean.session.account() == null);

    const bad_addr: dns.Address = .{ .ipv4 = .{ 203, 0, 113, 9 } };
    _ = try server.reputation.penalize(bad_addr, 5, server.nowU64());
    const bad_id = try gapP8Open(server);
    const bad = server.connFor(bad_id).?;
    bad.peer_addr = bad_addr;
    try gapP8Feed(server, bad_id, bad, "NICK p8bad\r\nUSER p8bad 0 * :Bad\r\n");
    const held = bad.send_buf[0..bad.send_len];
    try std.testing.expect(std.mem.indexOf(u8, held, " 001 ") == null);
    try std.testing.expect(std.mem.indexOf(u8, held, "CHALLENGE pow ") != null);
    try std.testing.expect(!bad.session.registered());
    try std.testing.expect(!bad.session.logged_in);
    try std.testing.expect(bad.session.account() == null);
    var hex_buf: [32]u8 = undefined;
    const hex = challenge_mod.hexEncode(bad.challenge_seed[0..bad.challenge_seed_len], &hex_buf);
    try std.testing.expect(std.mem.indexOf(u8, held, hex) != null);

    try gapP8Feed(server, bad_id, bad, "CHALLENGE nope\r\n");
    try std.testing.expect(std.mem.indexOf(u8, bad.send_buf[0..bad.send_len], "CHALLENGE failed") != null);
    try std.testing.expect(!bad.session.registered());

    var nonce_buf: [8]u8 = undefined;
    const nonce = gapP8Pow(bad.challenge_seed[0..bad.challenge_seed_len], &nonce_buf) orelse return error.TestUnexpectedResult;
    var answer_buf: [64]u8 = undefined;
    const too_soon = std.fmt.bufPrint(&answer_buf, "CHALLENGE {s}\r\n", .{nonce}) catch return error.TestUnexpectedResult;
    try gapP8Feed(server, bad_id, bad, too_soon);
    try std.testing.expect(std.mem.indexOf(u8, bad.send_buf[0..bad.send_len], "CHALLENGE wait") != null);
    try std.testing.expect(!bad.session.registered());

    sim.advance(challenge_mod.fail_delay_ms);
    try gapP8Feed(server, bad_id, bad, too_soon);
    try std.testing.expect(std.mem.indexOf(u8, bad.send_buf[0..bad.send_len], " 001 ") != null);
    try std.testing.expect(bad.session.registered());
    try std.testing.expect(!bad.session.logged_in);
    try std.testing.expect(bad.session.account() == null);
    try std.testing.expect(!bad.closing);

    const oper_id = try addTestLocalClient(server, "p8oper", null);
    const oper = server.connFor(oper_id).?;
    oper.session.registration.registered = true;
    oper.session.is_oper = true;
    oper.send_len = 0;
    var question = try irc_line.parseLine("CHALLENGE QUESTION mascot :onyx");
    try server.handleChallenge(oper_id, oper, &question);
    try std.testing.expect(std.mem.indexOf(u8, oper.send_buf[0..oper.send_len], "question set") != null);
    try std.testing.expectEqual(challenge_mod.Method.question, server.challenge_method);

    var n: usize = 0;
    while (n < 6) : (n += 1) server.noteRaidJoin("#p8raid", "peer-a.test");
    server.noteRaidJoin("#p8raid", "peer-b.test");
    server.noteRaidJoin("#p8raid", "peer-c.test");
    current_reactor = &server.reactors[0];
    server.evaluateRaidShield();
    current_reactor = null;
    try std.testing.expect(server.raid_shield.engaged());

    const raid_id = try gapP8Open(server);
    const raid = server.connFor(raid_id).?;
    try gapP8Feed(server, raid_id, raid, "NICK p8raid\r\nUSER p8raid 0 * :Raid\r\n");
    const asked = raid.send_buf[0..raid.send_len];
    try std.testing.expect(std.mem.indexOf(u8, asked, " 001 ") == null);
    try std.testing.expect(std.mem.indexOf(u8, asked, "CHALLENGE question mascot") != null);
    try std.testing.expect(!raid.session.registered());
    try gapP8Feed(server, raid_id, raid, "CHALLENGE nope\r\n");
    try std.testing.expect(!raid.session.registered());
    sim.advance(challenge_mod.fail_delay_ms);
    try gapP8Feed(server, raid_id, raid, "CHALLENGE onyx\r\n");
    try std.testing.expect(std.mem.indexOf(u8, raid.send_buf[0..raid.send_len], " 001 ") != null);
    try std.testing.expect(raid.session.registered());
    try std.testing.expect(!raid.session.logged_in);
    try std.testing.expect(raid.session.account() == null);
    current_reactor = null;
    std.debug.print("GAP-P8 branch=reputation or raid shield holds 001 until a pluggable challenge admits and success is not an account\n", .{});
}

fn gapP9HistoryHas(server: *Server, channel: []const u8, needle: []const u8) bool {
    var hist: [16]lotus.Message = undefined;
    const rows = server.history.latest(channel, hist.len, &hist) catch return false;
    for (rows) |row| if (std.mem.indexOf(u8, row.text, needle) != null) return true;
    return false;
}

test "GAP-P9 a channel prop holds first messages and quarantine is audited" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;
    const config = Config{ .host = "127.0.0.1", .port = 0, .server_name = "p9.test" };
    const server = createTestServer(alloc, config) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();

    const alice_id = try addTestLocalClient(server, "alice", null);
    const bob_id = try addTestLocalClient(server, "bob", null);
    const eve_id = try addTestLocalClient(server, "eve", null);
    const dave_id = try addTestLocalClient(server, "dave", null);
    const oper_id = try addTestLocalClient(server, "p9oper", null);
    const alice = server.connFor(alice_id).?;
    const bob = server.connFor(bob_id).?;
    const eve = server.connFor(eve_id).?;
    const dave = server.connFor(dave_id).?;
    const oper = server.connFor(oper_id).?;
    alice.session.registration.registered = true;
    bob.session.registration.registered = true;
    eve.session.registration.registered = true;
    dave.session.registration.registered = true;
    oper.session.registration.registered = true;
    oper.session.is_oper = true;
    _ = try server.world.join("#room", worldIdFromClient(alice_id));
    _ = try server.world.join("#room", worldIdFromClient(bob_id));
    _ = try server.world.join("#room", worldIdFromClient(eve_id));
    _ = try server.world.join("#room", worldIdFromClient(dave_id));
    _ = try server.world.join("#other", worldIdFromClient(dave_id));
    const entity = ircx_prop_store.Entity{ .kind = .channel, .id = "#room" };
    _ = try server.props.setProp(entity, "HOLD", "1", .{ .id = "p9oper", .access = .host });

    bob.send_len = 0;
    var held = try irc_line.parseLine("PRIVMSG #room :hello held");
    try server.handleMessage(alice_id, alice, &held, "PRIVMSG");
    try std.testing.expect(std.mem.indexOf(u8, alice.send_buf[0..alice.send_len], "HOLD stored") != null);
    try std.testing.expectEqual(@as(usize, 0), bob.send_len);
    try std.testing.expect(!gapP9HistoryHas(server, "#room", "hello held"));

    bob.send_len = 0;
    var second = try irc_line.parseLine("PRIVMSG #room :second flows");
    try server.handleMessage(alice_id, alice, &second, "PRIVMSG");
    try std.testing.expect(std.mem.indexOf(u8, bob.send_buf[0..bob.send_len], "second flows") != null);
    try std.testing.expect(std.mem.indexOf(u8, bob.send_buf[0..bob.send_len], "hello held") == null);

    bob.send_len = 0;
    var release = try irc_line.parseLine("HOLD RELEASE #room alice");
    try server.handleHold(oper, &release);
    try std.testing.expect(std.mem.indexOf(u8, oper.send_buf[0..oper.send_len], "HOLD released 1") != null);
    try std.testing.expect(std.mem.indexOf(u8, bob.send_buf[0..bob.send_len], "hello held") != null);
    try std.testing.expect(gapP9HistoryHas(server, "#room", "hello held"));

    bob.send_len = 0;
    var secret = try irc_line.parseLine("PRIVMSG #room :secret drop");
    try server.handleMessage(eve_id, eve, &secret, "PRIVMSG");
    try std.testing.expectEqual(@as(usize, 0), bob.send_len);
    var drop = try irc_line.parseLine("HOLD DROP #room eve");
    try server.handleHold(oper, &drop);
    try std.testing.expect(!gapP9HistoryHas(server, "#room", "secret drop"));
    try std.testing.expect(std.mem.indexOf(u8, bob.send_buf[0..bob.send_len], "secret drop") == null);

    var move = try irc_line.parseLine("QUARANTINE dave #pen :review the join");
    try server.handleQuarantine(oper, &move);
    try std.testing.expect(!server.world.isMember("#room", worldIdFromClient(dave_id)));
    try std.testing.expect(!server.world.isMember("#other", worldIdFromClient(dave_id)));
    try std.testing.expect(server.world.isMember("#pen", worldIdFromClient(dave_id)));
    var audited = false;
    var ai: usize = 0;
    while (ai < server.oper_audit.len()) : (ai += 1) {
        const entry = server.oper_audit.at(ai) orelse continue;
        if (std.mem.indexOf(u8, entry.reason, "quarantine") != null and
            std.mem.indexOf(u8, entry.reason, "review the join") != null)
        {
            audited = true;
        }
    }
    try std.testing.expect(audited);
    current_reactor = null;
    std.debug.print("GAP-P9 branch=a channel HOLD prop keeps the first messages for release or drop and quarantine audits the reason\n", .{});
}

