fn gapP11ReadSource(allocator: std.mem.Allocator) ![]u8 {
    // Bind each handler witness to the source compiled into this test, even
    // when the artifact runs on another host or outside its build checkout.
    return try allocator.dupe(u8, @embedFile("server.zig"));
}

fn gapP11HandlerLine(text: []const u8, declaration: []const u8, needle: []const u8) ?usize {
    // Restrict each witness to its actual method, so the test's own string
    // literals cannot satisfy the contract after a handler is removed.
    var lines = std.mem.splitScalar(u8, text, '\n');
    var line_no: usize = 0;
    var in_handler = false;
    while (lines.next()) |line| {
        line_no += 1;
        if (!in_handler) {
            if (!std.mem.startsWith(u8, line, declaration)) continue;
            in_handler = true;
        }
        if (std.mem.eql(u8, line, "    }")) return null;
        if (std.mem.indexOf(u8, line, needle) != null) return line_no;
    }
    return null;
}

fn gapP12HttpReady(buf: []const u8) bool {
    const split = std.mem.indexOf(u8, buf, "\r\n\r\n") orelse return false;
    const head = buf[0..split];
    const body = buf[split + 4 ..];
    var it = std.mem.splitScalar(u8, head, '\n');
    while (it.next()) |raw| {
        const line = std.mem.trim(u8, raw, "\r");
        const prefix = "Content-Length:";
        if (line.len <= prefix.len) continue;
        if (!std.ascii.eqlIgnoreCase(line[0..prefix.len], prefix)) continue;
        const n = std.fmt.parseInt(usize, std.mem.trim(u8, line[prefix.len..], " \t"), 10) catch return false;
        return body.len >= n;
    }
    return false;
}

fn gapP12Https(alloc: std.mem.Allocator, port: u16, anchor: []const u8, request: []const u8, out: []u8) ![]const u8 {
    const tls_client = @import("../crypto/tls_client.zig");
    const fd = try connectLoopback(port);
    defer closeFd(fd);
    const nodelay: u32 = 1;
    _ = linux.setsockopt(fd, linux.IPPROTO.TCP, linux.TCP.NODELAY, std.mem.asBytes(&nodelay), @sizeOf(u32));
    const tv = linux.timeval{ .sec = 5, .usec = 0 };
    _ = linux.setsockopt(fd, posix.SOL.SOCKET, posix.SO.RCVTIMEO, std.mem.asBytes(&tv), @sizeOf(linux.timeval));

    var client = try tls_client.Client.init(alloc, .{ .server_name = "p12.test", .trust_anchors = &.{anchor} });
    defer client.deinit();
    const hello = try client.start();
    defer alloc.free(hello);
    try writeAllFd(fd, hello);

    var rbuf: [8192]u8 = undefined;
    var guard: usize = 0;
    while (!client.handshakeDone()) : (guard += 1) {
        if (guard > 32) return error.TestUnexpectedResult;
        const n = try readFd(fd, &rbuf);
        if (n == 0) return error.TestUnexpectedResult;
        switch (try client.feed(rbuf[0..n])) {
            .bytes_to_send => |b| {
                defer alloc.free(b);
                try writeAllFd(fd, b);
            },
            .need_more => {},
        }
    }
    try std.testing.expect(client.handshakeDone());

    const sealed = try client.encrypt(request);
    defer alloc.free(sealed);
    try writeAllFd(fd, sealed);

    var plain: std.ArrayList(u8) = .empty;
    defer plain.deinit(alloc);
    var cipher: std.ArrayList(u8) = .empty;
    defer cipher.deinit(alloc);
    guard = 0;
    while (!gapP12HttpReady(plain.items)) : (guard += 1) {
        if (guard > 32) return error.TestUnexpectedResult;
        const n = try readFd(fd, &rbuf);
        if (n == 0) break;
        try cipher.appendSlice(alloc, rbuf[0..n]);
        while (cipher.items.len >= 5) {
            const body_len = std.mem.readInt(u16, cipher.items[3..5], .big);
            if (body_len > 18432) return error.TestUnexpectedResult;
            const wire_len = 5 + @as(usize, body_len);
            if (cipher.items.len < wire_len) break;
            switch (try client.decryptApp(cipher.items[0..wire_len])) {
                .application_data => |pt| {
                    defer alloc.free(pt);
                    try plain.appendSlice(alloc, pt);
                },
                .control => {},
            }
            std.mem.copyForwards(u8, cipher.items[0 .. cipher.items.len - wire_len], cipher.items[wire_len..]);
            cipher.shrinkRetainingCapacity(cipher.items.len - wire_len);
        }
    }
    if (!gapP12HttpReady(plain.items)) return error.TestUnexpectedResult;
    if (plain.items.len > out.len) return error.TestUnexpectedResult;
    @memcpy(out[0..plain.items.len], plain.items);
    return out[0..plain.items.len];
}

test "GAP-P12 a loopback history read matches CHATHISTORY visibility" {
    if (comptime builtin.os.tag != .linux) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    const x509_selfsign = @import("../proto/x509_selfsign.zig");
    const Ed25519 = std.crypto.sign.Ed25519;
    defer current_reactor = null;
    const config = Config{ .host = "127.0.0.1", .port = 0, .server_name = "p12.test", .crypto_io = std.testing.io };
    const server = createTestServer(alloc, config) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();

    const member_id = try addTestLocalClient(server, "member", "member");
    const outsider_id = try addTestLocalClient(server, "outsider", "outsider");
    _ = try server.world.join("#room", worldIdFromClient(member_id));
    _ = try server.world.setChannelFlag("#room", .secret, true);
    server.recordHistoryRelayAt("#room", "member!member@localhost", "m1", "PRIVMSG", "visible line", null, server.meshWallMs());
    try std.testing.expect(!server.connFor(member_id).?.session.isOper());
    try std.testing.expect(!server.connFor(outsider_id).?.session.isOper());

    const kp = try Ed25519.KeyPair.generateDeterministic(@as([Ed25519.KeyPair.seed_length]u8, @splat(0x12)));
    var cert_buf: [1024]u8 = undefined;
    const der = try x509_selfsign.buildSelfSigned(&cert_buf, .{
        .common_name = "p12.test",
        .not_before = 1_704_067_200,
        .not_after = 4_102_444_800,
        .serial = &.{0x12},
        .key_pair = kp,
        .dns_names = &.{"p12.test"},
        .is_ca = true,
    });
    const chain = [_][]const u8{der};
    const tls_cfg = tls_server.Config{ .cert_chain = &chain, .signing_key = kp };
    try std.testing.expectError(error.PublicBind, server.openHistoryHttps("0.0.0.0", 0, tls_cfg));
    const v6_port = try server.openHistoryHttps("::1", 0, tls_cfg);
    try std.testing.expect(v6_port != 0);
    const port = try server.openHistoryHttps("127.0.0.1", 0, tls_cfg);
    try std.testing.expect(port != 0);

    var out: [2048]u8 = undefined;
    const allowed = try gapP12Https(alloc, port, der, "GET /history?target=%23room HTTP/1.1\r\nHost: p12.test\r\nAuthorization: Bearer member\r\nConnection: close\r\n\r\n", &out);
    try std.testing.expect(std.mem.indexOf(u8, allowed, " 200 ") != null);
    try std.testing.expect(std.mem.indexOf(u8, allowed, "visible line") != null);

    const denied = try gapP12Https(alloc, port, der, "GET /history?target=%23room HTTP/1.1\r\nHost: p12.test\r\nAuthorization: Bearer outsider\r\nConnection: close\r\n\r\n", &out);
    try std.testing.expect(std.mem.indexOf(u8, denied, " 403 ") != null);
    try std.testing.expect(std.mem.indexOf(u8, denied, "visible line") == null);

    const ghost = try gapP12Https(alloc, port, der, "GET /history?target=%23room HTTP/1.1\r\nHost: p12.test\r\nAuthorization: Bearer ghost\r\nConnection: close\r\n\r\n", &out);
    try std.testing.expect(std.mem.indexOf(u8, ghost, " 403 ") != null);

    const admin = try gapP12Https(alloc, port, der, "GET /admin HTTP/1.1\r\nHost: p12.test\r\nAuthorization: Bearer member\r\nConnection: close\r\n\r\n", &out);
    try std.testing.expect(std.mem.indexOf(u8, admin, " 404 ") != null);
    const posted = try gapP12Https(alloc, port, der, "POST /history?target=%23room HTTP/1.1\r\nHost: p12.test\r\nAuthorization: Bearer member\r\nConnection: close\r\n\r\n", &out);
    try std.testing.expect(std.mem.indexOf(u8, posted, " 405 ") != null);

    current_reactor = null;
    std.debug.print("GAP-P12 branch=loopback HTTPS GET /history returns the lines CHATHISTORY would and a public bind is refused\n", .{});
}

test "GAP-K4 a sealed room refuses the clear roster and an ordinary room still lists it" {
    if (comptime builtin.os.tag != .linux and builtin.os.tag != .openbsd) return error.SkipZigTest;
    const alloc = std.testing.allocator;
    defer current_reactor = null;

    const server = createTestServer(alloc, .{
        .host = "127.0.0.1",
        .port = 0,
        .tls_port = 0,
        .crypto_io = std.testing.io,
    }) catch |err| switch (err) {
        error.Unsupported, error.PermissionDenied, error.SocketUnavailable => return error.SkipZigTest,
        else => return err,
    };
    defer alloc.destroy(server);
    defer server.deinit();
    current_reactor = &server.reactors[0];

    const founder_id = try addTestLocalClient(server, "Founder", "founder");
    const member_id = try addTestLocalClient(server, "Member", "member");
    const founder = server.connFor(founder_id).?;
    const member = server.connFor(member_id).?;
    founder.ircx = true;
    member.ircx = true;

    _ = try server.world.join("#open", worldIdFromClient(founder_id));
    _ = try server.world.join("#sealed", worldIdFromClient(founder_id));
    _ = try server.world.join("#open", worldIdFromClient(member_id));
    _ = try server.world.join("#sealed", worldIdFromClient(member_id));

    resetTestSendQ(founder);
    var names_open = try irc_line.parseLine("NAMES #open");
    try server.handleNames(founder, &names_open);
    const open_roster = founder.send_buf[0..founder.send_len];
    try expectContains(open_roster, " 353 ");
    try expectContains(open_roster, "Member");

    resetTestSendQ(founder);
    var bad_vis = try irc_line.parseLine("PROP #sealed membership-visibility :hidden");
    try server.handleProp(founder_id, founder, &bad_vis);
    try expectContains(founder.send_buf[0..founder.send_len], "Invalid property value");
    const sealed_entity = ircx_prop_store.Entity{ .kind = .channel, .id = "#sealed" };
    try std.testing.expectError(error.PropMissing, server.props.getProp(sealed_entity, sealed_room.prop_key));

    resetTestSendQ(founder);
    var set_vis = try irc_line.parseLine("PROP #sealed membership-visibility :sealed");
    try server.handleProp(founder_id, founder, &set_vis);
    try std.testing.expectEqualStrings("sealed", (try server.props.getProp(sealed_entity, sealed_room.prop_key)).value);
    try std.testing.expectEqual(sealed_room.Visibility.sealed, server.channelMembershipVisibility("#sealed"));
    try std.testing.expectEqual(sealed_room.Visibility.ordinary, server.channelMembershipVisibility("#open"));
    try std.testing.expect(!sealed_room.helixPublishesClearRoster(server.channelMembershipVisibility("#sealed")));
    try std.testing.expect(sealed_room.helixPublishesClearRoster(server.channelMembershipVisibility("#open")));
    try std.testing.expect(server.world.memberCount("#sealed") >= 2);

    resetTestSendQ(founder);
    var names_open_again = try irc_line.parseLine("NAMES #open");
    try server.handleNames(founder, &names_open_again);
    try expectContains(founder.send_buf[0..founder.send_len], " 353 ");
    try expectContains(founder.send_buf[0..founder.send_len], "Member");

    resetTestSendQ(founder);
    var names_sealed = try irc_line.parseLine("NAMES #sealed");
    try server.handleNames(founder, &names_sealed);
    const sealed_names = founder.send_buf[0..founder.send_len];
    try expectContains(sealed_names, "MEMBERSHIP_SEALED");
    try std.testing.expect(std.mem.indexOf(u8, sealed_names, " 353 ") == null);
    try std.testing.expect(std.mem.indexOf(u8, sealed_names, "Member") == null);

    resetTestSendQ(founder);
    var names_bare = try irc_line.parseLine("NAMES");
    try server.handleNames(founder, &names_bare);
    const bare_names = founder.send_buf[0..founder.send_len];
    try expectContains(bare_names, " 353 ");
    try expectContains(bare_names, "#open");
    try expectContains(bare_names, "Member");
    try std.testing.expect(std.mem.indexOf(u8, bare_names, "#sealed") == null);

    resetTestSendQ(founder);
    var who_sealed = try irc_line.parseLine("WHO #sealed");
    try server.handleWho(founder, &who_sealed);
    const sealed_who = founder.send_buf[0..founder.send_len];
    try expectContains(sealed_who, "MEMBERSHIP_SEALED");
    try std.testing.expect(std.mem.indexOf(u8, sealed_who, " 352 ") == null);
    try std.testing.expect(std.mem.indexOf(u8, sealed_who, "Member") == null);

    resetTestSendQ(founder);
    var who_open = try irc_line.parseLine("WHO #open");
    try server.handleWho(founder, &who_open);
    try expectContains(founder.send_buf[0..founder.send_len], "Member");

    resetTestSendQ(founder);
    var whox_sealed = try irc_line.parseLine("WHO #sealed %n");
    try server.handleWho(founder, &whox_sealed);
    const sealed_whox = founder.send_buf[0..founder.send_len];
    try expectContains(sealed_whox, "MEMBERSHIP_SEALED");
    try std.testing.expect(std.mem.indexOf(u8, sealed_whox, " 354 ") == null);
    try std.testing.expect(std.mem.indexOf(u8, sealed_whox, "Member") == null);

    resetTestSendQ(founder);
    resetTestSendQ(member);
    try gapP4Send(server, founder_id, founder, "PRIVMSG #sealed :k4routeword");
    try expectContains(member.send_buf[0..member.send_len], "k4routeword");

    resetTestSendQ(founder);
    resetTestSendQ(member);
    var kick_line = try irc_line.parseLine("KICK #sealed Member :sealed-room abuse");
    try server.handleKick(founder_id, founder, &kick_line);
    const kicked = member.send_buf[0..member.send_len];
    try expectContains(kicked, "KICK #sealed Member");
    try std.testing.expect(std.mem.indexOf(u8, kicked, " 353 ") == null);

    resetTestSendQ(founder);
    var set_ordinary = try irc_line.parseLine("PROP #sealed membership-visibility :ordinary");
    try server.handleProp(founder_id, founder, &set_ordinary);
    try std.testing.expectEqual(sealed_room.Visibility.ordinary, server.channelMembershipVisibility("#sealed"));
    resetTestSendQ(founder);
    var names_restored = try irc_line.parseLine("NAMES #sealed");
    try server.handleNames(founder, &names_restored);
    const restored = founder.send_buf[0..founder.send_len];
    try expectContains(restored, " 353 ");
    try expectContains(restored, "Founder");
    try std.testing.expect(std.mem.indexOf(u8, restored, "MEMBERSHIP_SEALED") == null);

    std.debug.print("GAP-K4 branch=sealed room refuses NAMES WHO and WHOX; ordinary room still lists members; routing and KICK keep their targets\n", .{});
}

